window.HM_DATA.SHUOWEN_FULL = {"一":{"expl":"惟初太始，道立於一，造分天地，化成萬物。凡一之屬皆从一。","rad":"一","fq":"於悉切","vol":"01","py":"yī","duan":[{"e":"惟初大極。道立於一。造分天地。化成萬物。","n":"漢書曰。元元本本。數始於一。"}]},"示":{"expl":"天垂象，見吉凶，所以示人也。从二。(二，古文上字。)三垂，日月星也。觀乎天文，以察時變。示，神事也。凡示之屬皆从示。","rad":"示","fq":"神至切","vol":"01","py":"shì","duan":[{"e":"天𠂹象。見吉凶。","n":"見周易𣪠辭。"}]},"瑛":{"expl":"玉光也。从玉英聲。","rad":"玉","fq":"於京切","vol":"01","py":"yīnɡ","duan":[{"e":"玉光也。","n":"山海經言玉榮。離騷、孝經、援神契、雒書皆言玉英。淮南鴻烈曰。龍淵有玉英。高注。英、精光也。"}]},"䞪":{"expl":"行皃。从走匠聲。讀若匠。","rad":"走","fq":"疾亮切","vol":"02","py":"jiànɡ","duan":[{"e":"行皃。从走。匠聲。讀若匠。","n":"疾亮切。十部。"}]},"𧾝":{"expl":"走皃。从走㕡聲。讀若紃。","rad":"走","fq":"祥遵切","vol":"02","py":"xún","duan":[{"e":"走皃。","n":"走疾於行。"}]},"𧾯":{"expl":"走意。从走薊聲。讀若髽結之結。","rad":"走","fq":"古屑切","vol":"02","py":"jié","duan":[{"e":"走意。","n":"廣韵走皃。"}]},"𧼐":{"expl":"走意。从走囷聲。","rad":"走","fq":"丘忿切","vol":"02","py":"yǔn","duan":[{"e":"走意。","n":"廣韵走皃。"}]},"趖":{"expl":"走意。从走坐聲。","rad":"走","fq":"蘇和切","vol":"02","py":"suō","duan":[{"e":"走意。","n":"花閒詞曰。荳蔲花閒趖晚日。今京師人謂日跌爲晌午趖。"}]},"𧾨":{"expl":"走意。从走憲聲。","rad":"走","fq":"許建切","vol":"02","py":"xiàn","duan":[{"e":"走意。","n":"石𡔷詩。𧾨𧾨𤒞𤒞。"}]},"𧾫":{"expl":"走意。从走臱聲。","rad":"走","fq":"布賢切","vol":"02","py":"biān","duan":[{"e":"走意。从走。臱聲。","n":"布賢切。十二部。按鍇本作臱省聲。而其篆文不省。"}]},"䟈":{"expl":"走也。从走𢧜聲。讀若《詩》“威儀秩秩”。","rad":"走","fq":"直質切","vol":"02","py":"zhí","duan":[{"e":"走也。从走。𢧜聲。讀若詩威儀秩秩。","n":"此偁假樂威儀抑抑。德音秩秩。誤合二句爲一。如東方昌矣、昆夷呬矣亦然也。秩秩李仁甫本作祑祑。少牢饋食禮注曰。古文替爲秩。秩或爲𢧜與䟈。讀如秩相似。直質切。十一十二部合韵冣近。"}]},"䞥":{"expl":"走也。从走有聲。讀若又。","rad":"走","fq":"子救切（當作于救切）","vol":"02","py":"yòu","duan":[{"e":"走也。","n":"篇、韵皆作走皃。"}]},"𧽋":{"expl":"走輕也。从走烏聲。讀若鄔。","rad":"走","fq":"安古切","vol":"02","py":"wǔ","duan":[{"e":"走輕也。从走。烏聲。讀若鄔。","n":"安古切。五部。"}]},"璑":{"expl":"三采玉也。从玉無聲。","rad":"玉","fq":"武扶切","vol":"01","py":"wú","duan":[{"e":"三采玉也。","n":"周禮故書。璑玉三采。注曰。璑、惡玉名。江沅曰。惡王者、亞次之玉也。古惡亞字通。廣雅玉類有璑。玉裁按。天子純玉。公四玉一石。侯三玉二石。故書作璑。新書作珉。皆謂石之次玉者。諸公之冕、璑玉三采。謂以璑雜玉備三采。下於天子純玉備五采也。許云。三采玉謂之璑。誤矣。"}]},"𧾱":{"expl":"走顧皃。从走瞿聲。讀若劬。","rad":"走","fq":"其俱切","vol":"02","py":"qú","duan":[{"e":"走顧皃。从走。瞿聲。","n":"此形聲包會意。瞿、鷹隼之視也。記曰。見似目瞿。"}]},"䞿":{"expl":"走皃。从走，蹇省聲。","rad":"走","fq":"九輦切","vol":"02","py":"qiān","duan":[{"e":"走皃。从走。寒省聲。","n":"今本寒作蹇。誤。篇、韵皆丘言虛言二切。鉉云九輦切。"}]},"䞗":{"expl":"疑之，等䞗而去也。从走才聲。","rad":"走","fq":"倉才切","vol":"02","py":"cāi","duan":[{"e":"疑之等䞗而去也。","n":"等讀若𪒴。等䞗㬪韵字。濡滯之皃。疑之故等䞗而去。等在之止韵。音變入咍海韵。音轉入拯等韵。"}]},"𧺼":{"expl":"淺渡也。从走此聲。","rad":"走","fq":"雌氏切","vol":"02","py":"cǐ","duan":[{"e":"淺渡也。从走。此聲。","n":"雌氏切。十五十六部。"}]},"赹":{"expl":"獨行也。从走勻聲。讀若煢。","rad":"走","fq":"渠營切","vol":"02","py":"qiónɡ","duan":[{"e":"獨行也。","n":"唐風。獨行煢煢。毛曰。煢煢、無所依也。熒聲匀聲合音冣近。故煢赹同義。"}]},"𧾚":{"expl":"安行也。从走與聲。","rad":"走","fq":"余呂切","vol":"02","py":"yú","duan":[{"e":"安行也。","n":"廣韵九魚。𧾚𧾚、安行皃。按欠部歟、安气也。心部㦛、趣步㦛㦛也。馬部𩦡、馬行徐而疾也。論語曰。與與如也。漢書。長倩懙懙。"}]},"起":{"expl":"能立也。从走巳聲。","rad":"走","fq":"墟里切","vol":"02","py":"qǐ","duan":[{"e":"能立也。","n":"起本發步之偁。引伸之訓爲立。又引伸之爲凡始事、凡興作之偁。"}]},"𧻲":{"expl":"畱意也。从走里聲。讀若小兒孩。","rad":"走","fq":"戶來切","vol":"02","py":"hái","duan":[{"e":"畱意也。从走。里聲。讀若小兒咳。","n":"咳今本作孩。誤。許用小篆也。戸來切。一部。"}]},"𧽒":{"expl":"行也。从走臭聲。","rad":"走","fq":"香仲切","vol":"02","py":"xiònɡ","duan":[{"e":"行也。","n":"廣韵一送曰。䠢𧽒、疲行皃。大人賦說螭虯。沛艾赳螑。仡以佁儗兮。張揖曰。赳螑、申頸低卬也。按赳螑猶䠢𧽒。"}]},"趛":{"expl":"低頭疾行也。从走金聲。","rad":"走","fq":"牛錦切","vol":"02","py":"yǐn","duan":[{"e":"低頭疾行也。从走。金聲。","n":"牛錦切。七部。"}]},"珛":{"expl":"朽玉也。从玉有聲。讀若畜牧之畜。","rad":"玉","fq":"許救切","vol":"01","py":"xiù","duan":[{"e":"朽玉也。从王有點。讀若畜牧之畜。","n":"各本篆文作珛。解云从玉、有聲。今訂正。史記公玉帶。索隱曰。三輔決錄注云。杜陵有玉氏、音肅。說文以爲从王、音畜牧之畜。此可證唐本但作玉、不作珛。廣韻一屋云。玉音肅。朽玉。此說文本字。四十九宥云。珛音齅。此從俗字。玉篇玉、欣救思六二切。此說文本字。珛、許救切。引說文朽玉也。此後人據俗本說文所增。佩觿曰。玉有欣救、魚錄、息足、相逐四翻。俗別爲玊。郭云。別爲玊者、謂玉石字點在三畫之側。欣救、息足、相逐三切點在二畫之側也。葢後人以朽玉字爲玉石字。以別於帝王字。復高其點爲朽玉、玉姓字。以別於玉石字。又或改說文从王加點爲从王有聲、作珛。亦以別於玉石字也。朽玉者謂玉有瑕㓠。故从玉加點以象形。淮南書云。夏后之璜"}]},"趌":{"expl":"趌𧼨，怒走也。从走吉聲。","rad":"走","fq":"去吉切","vol":"02","py":"jí","duan":[{"e":"趌𧼨、","n":"逗。"}]},"𧼨":{"expl":"趌𧼨也。从走曷聲。","rad":"走","fq":"居謁切","vol":"02","py":"jié","duan":[{"e":"趌𧼨也。","n":"凡異部㬪韵。必部分相近。"}]},"𧾎":{"expl":"疾也。从走瞏聲。讀若讙。","rad":"走","fq":"況袁切","vol":"02","py":"xuān","duan":[{"e":"疾也。","n":"齊風。子之還兮。毛曰。還、便捷之皃。按毛以還爲𧾎之假借也。或毛、許所據詩本作𧾎。"}]},"䞘":{"expl":"直行也。从走气聲。","rad":"走","fq":"魚訖切","vol":"02","py":"jí","duan":[{"e":"直行也。从走。乞聲。","n":"魚訖切。十五部。"}]},"𧾰":{"expl":"趨進𧾰如也。从走翼聲。","rad":"走","fq":"與職切","vol":"02","py":"yì","duan":[{"e":"趨進𧾰如也。","n":"有但引經文不釋字義者。如此及詞之？矣、絬衣長短右袂是也。又色艴如也。又足躩如也。"}]},"赽":{"expl":"踶也。从走，決省聲。","rad":"走","fq":"古穴切","vol":"02","py":"jué","duan":[{"e":"踶也。","n":"足部曰。踶、躗也。按踶、蹋也。"}]},"趩":{"expl":"行聲也。一曰不行皃。从走異聲。讀若敕。","rad":"走","fq":"丑亦切","vol":"02","py":"chì","duan":[{"e":"行聲也。","n":"石𡔷詩。其來趩趩。"}]},"趆":{"expl":"趨也。从走氐聲。","rad":"走","fq":"都禮切","vol":"02","py":"dī","duan":[{"e":"趨也。","n":"玉篇。走皃。廣韵。趨走皃。"}]},"趍":{"expl":"趨趙，久也。从走多聲。","rad":"走","fq":"直离切","vol":"02","py":"chí","duan":[{"e":"趍趙。","n":"二字句。"}]},"趙":{"expl":"趨趙也。从走肖聲。","rad":"走","fq":"治小切","vol":"02","py":"zhào","duan":[{"e":"趍趙也。从走。肖聲。","n":"治小切。"}]},"璿":{"expl":"美玉也。从玉睿聲。《春秋傳》曰：“璿弁玉纓。”","rad":"玉","fq":"似沿切","vol":"01","py":"xuán","duan":[{"e":"美玉也。","n":"山海經。西王母之山。有璿瑰瑤碧。郭傳。璿瑰、玉名。竹書穆天子傳。重𢀄氏之所守曰枝斯璿瑰。郭注。璿瑰、玉名。引左傳贈我以璿瑰。按左傳成公十八年。今本作瓊瑰。僖公廿八年璿弁。今本作瓊弁。張守節史記璿璣作瓊璣。璿與瓊、古書多相亂。璿瑰、郭音旋回。合二字爲美玉名。山海經單言琁者、亦美玉也。"}]},"赾":{"expl":"行難也。从走斤聲。讀若堇。","rad":"走","fq":"丘堇切","vol":"02","py":"qǐn","duan":[{"e":"行難也。","n":"廣雅。赾、難也。按今人靳固字當作此赾字。"}]},"𧾣":{"expl":"走意也。从走夐聲。讀若繘。","rad":"走","fq":"居聿切","vol":"02","py":"jú","duan":[{"e":"走意也。从走。敻聲。讀若繘。","n":"居聿切。十五部。夐古音在十四部。合音冣近。故觼𧤾亦同字。"}]},"趠":{"expl":"遠也。从走卓聲。","rad":"走","fq":"敕角切","vol":"02","py":"chuò","duan":[{"e":"遠也。","n":"？部曰。逴、遠也。音義同。上林賦。捷垂條。逴希閒。玄應引如是。史記作踔。郭璞曰。踔、懸擿也。吳都賦。狖鼯猓然。騰趠飛超。按許云遠者、騰擲所到遠也。"}]},"䟑":{"expl":"趠䟑也。从走龠聲。","rad":"走","fq":"以灼切","vol":"02","py":"yuè","duan":[{"e":"趠䟑也。","n":"三字一句。趠䟑㬪韵字。廣韵。趠䟑、行皃。方言。𨈅、行也。𨈅卽䟑字。"}]},"𧾵":{"expl":"大步也。从走矍聲。","rad":"走","fq":"丘縛切","vol":"02","py":"jué","duan":[{"e":"大步也。从走。矍聲。","n":"丘縛切。五部。"}]},"𧼪":{"expl":"超特也。从走契聲。","rad":"走","fq":"丑例切","vol":"02","py":"chì","duan":[{"e":"超特也。","n":"廣韵曰。𧼪同跇按足部有跇字。𨒋也。𨒋踰也。禮樂志。體容與。迣萬里。迣、迾也。於義隔。史記樂書作跇。吳都賦。跇踰竹柏。李善引如淳曰。跇、超踰也。恥曳切。𧼪與跇音義同。"}]},"䟇":{"expl":"走也。从走幾聲。","rad":"走","fq":"居衣切","vol":"02","py":"jī","duan":[{"e":"走也。从走。幾聲。","n":"居衣切。十五部。"}]},"𧼗":{"expl":"走也。从走岪聲。","rad":"走","fq":"敷勿切","vol":"02","py":"fú","duan":[{"e":"走也。","n":"篇韵皆作䞞。云走皃。"}]},"𧽻":{"expl":"狂走也。从走矞聲。","rad":"走","fq":"余律切","vol":"02","py":"jú","duan":[{"e":"狂走也。","n":"東京賦。捎魑魅。斮獝狂。薛曰。獝狂、惡戾之鬼。按獝當作𧽻。"}]},"䟂":{"expl":"行遲也。从走曼聲。","rad":"走","fq":"莫還切","vol":"02","py":"mán","duan":[{"e":"行遟也。","n":"今人通用慢字。"}]},"球":{"expl":"玉聲也。从玉求聲。","rad":"玉","fq":"巨鳩切","vol":"01","py":"qiú","duan":[{"e":"玉也。","n":"鉉本玉罄也。非。爾雅釋器曰。璆、美玉也。禹貢、禮器鄭注同。商頌小球大球傳曰。球、玉也。按磬以球爲之。故名球。非球之本訓爲玉磬。"}]},"趉":{"expl":"走也。从走出聲。讀若無尾之屈。","rad":"走","fq":"瞿勿切","vol":"02","py":"jué","duan":[{"e":"走也。","n":"玉篇曰。卒起走也。按今俗語有之。"}]},"趜":{"expl":"窮也。从走匊聲。","rad":"走","fq":"居六切","vol":"02","py":"jú","duan":[{"e":"竆也。","n":"毛傳。鞫、竆也。說文。？、竆也。？、竆治辠人也。皆於雙聲㬪韵求之。廣韵曰。趜、困人也。"}]},"趑":{"expl":"趑趄，行不進也。从走次聲。","rad":"走","fq":"取私切","vol":"02","py":"cī","duan":[{"e":"趑趄、","n":"逗。"}]},"趄":{"expl":"趑趄也。从走且聲。","rad":"走","fq":"七余切","vol":"02","py":"jū","duan":[{"e":"趑趄也。从走。且聲。","n":"七余切。五部。"}]},"𧽐":{"expl":"蹇行𧽐𧽐也。从走虔聲。讀若愆。","rad":"走","fq":"去虔切","vol":"02","py":"qiān","duan":[{"e":"蹇行𧽐𧽐也。从走。䖍聲。讀若愆。","n":"去䖍切。十四部。"}]},"䟒":{"expl":"行䟒趢也。一曰行曲𦟝皃。从走雚聲。","rad":"走","fq":"巨員切","vol":"02","py":"quán","duan":[{"e":"行䟒趢也。","n":"廣韵。䟒、曲走皃。"}]},"趢":{"expl":"䟒趢也。从走录聲。","rad":"走","fq":"力玉切","vol":"02","py":"lù","duan":[{"e":"䟒趢也。","n":"東京賦曰。狹三王之趢？。薛云。趢？局小皃也。"}]},"䞭":{"expl":"行趚䞭也。从走夋聲。","rad":"走","fq":"七倫切","vol":"02","py":"qūn","duan":[{"e":"行速䞭䞭也。","n":"鍇本行速䞭䞭。䞭䞭者、行速皃。鉉本改下䞭爲也字。非。夂部曰。夋、行夋夋也。廣雅釋室曰。䞭、犇也。子綏反。今本綏譌繡。"}]},"𧻕":{"expl":"側行也。从走朿聲。《詩》曰：“謂地蓋厚，不敢不𧻕。”","rad":"走","fq":"資昔切","vol":"02","py":"qì","duan":[{"e":"側行也。","n":"側行者、謹畏也。"}]},"䞨":{"expl":"半步也。从走圭聲。讀若跬同。","rad":"走","fq":"丘弭切","vol":"02","py":"kuǐ","duan":[{"e":"半步也。","n":"今字作跬。司馬法曰。一舉足曰跬。跬三尺。㒳舉足曰步。步六尺。"}]},"琳":{"expl":"美玉也。从玉林聲。","rad":"玉","fq":"力尋切","vol":"01","py":"lín","duan":[{"e":"美玉也。","n":"高注淮南、王注楚辭、李孫郭注爾雅皆曰。琳、美玉名。某氏注尙書曰。琳、玉名。"}]},"䞾":{"expl":"䞾騭，輕薄也。从走虒聲。讀若池。","rad":"走","fq":"直离切","vol":"02","py":"chí","duan":[{"e":"䞾𨽥、","n":"逗。"}]},"䞳":{"expl":"僵也。从走咅聲。讀若匐。","rad":"走","fq":"朋北切","vol":"02","py":"bó","duan":[{"e":"僵也。","n":"僵、僨也。此與足部之踣音義竝同。未審孰爲本字。孰爲後增。"}]},"䞣":{"expl":"距也。从走，㡿省聲。《漢令》曰：“䞣張百人。”","rad":"走","fq":"車者切","vol":"02","py":"chě","duan":[{"e":"距也。","n":"距當作歫。歫、止也。一曰槍也。按蹠弩主於䟫歫。故曰？張。"}]},"䟏":{"expl":"動也。从走樂聲。讀若《春秋傳》曰“輔䟏”。","rad":"走","fq":"郎擊切","vol":"02","py":"lì","duan":[{"e":"動也。","n":"篇、韵皆云躒同。大戴禮曰。騏驥一躒。不能千步。"}]},"趡":{"expl":"動也。从走隹聲。《春秋傳》曰：“盟于趡。”趡，地名。","rad":"走","fq":"千水切","vol":"02","py":"cuǐ","duan":[{"e":"動也。","n":"楊雄河東賦曰。神騰鬼趡。師古子𥬇才𥬇二反。按說文有趡無趭。廣雅釋室。騰趭犇也。曹音子肖。今疑趭恐誤字。子肖恐誤音耳。然大人賦曰。騰而狂趭。師古音醮。吳都賦。狂趭獷猤。李子召反。則古非無趭字矣。"}]},"𧻚":{"expl":"𧻚田，易居也。从走亘聲。","rad":"走","fq":"羽元切","vol":"02","py":"yuán","duan":[{"e":"𧻚田、","n":"逗。"}]},"𧽍":{"expl":"走頓也。从走眞聲。讀若顚。","rad":"走","fq":"都年切","vol":"02","py":"diān","duan":[{"e":"走頓也。","n":"足部曰。蹎、跋也。此與音義同。"}]},"𧻹":{"expl":"喪辟𧻹。从走甬聲。","rad":"走","fq":"余隴切","vol":"02","py":"yǒnɡ","duan":[{"e":"喪擗𧻹。","n":"今禮經、禮記皆作踊。足部曰。踊、跳也。是二字義殊也。左傳曲踊三百、三踊于幕庭之類當从足。若卽位哭、三踊而出之踊當从走。擗、鉉作辟。詩邶風、爾雅諸家本多作擗。撫心爲擗。跳躍爲𧻹。"}]},"䟆":{"expl":"止行也。一曰竈上祭名。从走畢聲。","rad":"走","fq":"卑吉切","vol":"02","py":"bì","duan":[{"e":"止行也。","n":"今禮經皆作蹕。惟大司寇釋文作䟆。云本亦作蹕。是可見古經多後人改竄。亦有僅存古字也。五經文字曰。䟆、止行也。梁孝王傳。出稱警。入言䟆。"}]},"𧽯":{"expl":"進也。从走斬聲。","rad":"走","fq":"藏監切","vol":"02","py":"jiàn","duan":[{"e":"進也。","n":"按水部漸云。漸水也。則訓進者當專作？。許所見周易卦名當如是矣。"}]},"璧":{"expl":"瑞玉圜也。从玉辟聲。","rad":"玉","fq":"比激切","vol":"01","py":"bì","duan":[{"e":"瑞玉圜也。","n":"瑞、以玉爲信也。釋器。肉倍好謂之璧。邊大孔小也。鄭注周禮曰。璧圜象天。"}]},"趧":{"expl":"趧𡝤，四夷之舞，各自有曲。从走是聲。","rad":"走","fq":"都兮切","vol":"02","py":"tí","duan":[{"e":"趧婁、","n":"逗。"}]},"趒":{"expl":"雀行也。从走兆聲。","rad":"走","fq":"徒遼切","vol":"02","py":"tiáo","duan":[{"e":"雀行也。","n":"今人槩用跳字。"}]},"赶":{"expl":"舉尾走也。从走干聲。","rad":"走","fq":"巨言切","vol":"02","py":"qián","duan":[{"e":"舉尾走也。从走。干聲。","n":"巨言切。十四部。按此後人所增。非許書本有也。衆經音義曰。通俗文曰舉尾走曰揵。律文作赶馬走也。然則唐初說文無赶。卽有赶亦不訓舉尾走。都人士鄭箋。？、螫蟲也。尾末揵然。似婦人髮末上曲卷然。釋文引漢書音義。揵、舉也。此舉尾用揵不用赶之證。"}]},"止":{"expl":"下基也。象艸木出有址，故以止爲足。凡止之屬皆从止。","rad":"止","fq":"諸市切","vol":"02","py":"zhǐ","duan":[{"e":"下基也。","n":"與？同部同義。"}]},"歱":{"expl":"跟也。从止重聲。","rad":"止","fq":"之隴切","vol":"02","py":"zhǒnɡ","duan":[{"e":"跟也。","n":"足部曰。跟、足歱也。跟歱雙聲。釋名曰。足後曰跟。或曰踵。踵、鍾也。上體之所鍾聚也。按劉熙作踵。許歱、踵義別。"}]},"𣥺":{"expl":"歫也。从止尚聲。","rad":"止","fq":"丑庚切","vol":"02","py":"chēnɡ","duan":[{"e":"歫也。","n":"今音丑庚切。古音堂。今俗語亦如堂。考工記。維角䟫之。大鄭曰。䟫讀如牚距之牚。牚距、卽䟫歫字之變體。車䟫。急就篇、釋名作車棠。說文金部作車樘。木部曰。樘、衺柱也。今俗字䟫作撐。"}]},"歭":{"expl":"䠧也。从止寺聲。","rad":"止","fq":"直离切","vol":"02","py":"chí","duan":[{"e":"䠧也。","n":"足部曰。䠧者、歭䠧不前也。歭䠧爲雙聲字。此以䠧釋歭者。雙聲互訓也。心部曰？箸。足部曰蹢躅。毛詩曰踟躕。廣雅曰蹢䠱、跢跦。皆雙聲㬪韵而同義。"}]},"歫":{"expl":"止也。从止巨聲。一曰搶也。一曰超歫。","rad":"止","fq":"其呂切","vol":"02","py":"jù","duan":[{"e":"止也。","n":"許無拒字。歫卽拒也。此與彼相抵爲拒。相抵則止矣。書傳云。歫、至也。至則止矣。其義一也。漢石經論語。其不可者距之。字作距。許歫與距義別。"}]},"前":{"expl":"不行而進謂之歬。从止在舟上。","rad":"止","fq":"昨先切","vol":"02","py":"qián","duan":[{"e":"不行而進謂之歬。从止在舟上。","n":"昨先切。十二部。按後人以齊𣃔之前爲歬後字。又以羽生之翦爲前齊字。"}]},"歷":{"expl":"過也。从止厤聲。","rad":"止","fq":"郎擊切","vol":"02","py":"lì","duan":[{"e":"過也。傳也。","n":"引伸爲治曆明時之曆。"}]},"瑗":{"expl":"大孔璧。人君上除陛以相引。从玉爰聲。《爾雅》曰：“好倍肉謂之瑗，肉倍好謂之璧。”","rad":"玉","fq":"王眷切","vol":"01","py":"yuàn","duan":[{"e":"大孔璧。","n":"釋器曰。好倍肉謂之瑗。孔大於邊也。"}]},"𣥹":{"expl":"至也。从止叔聲。","rad":"止","fq":"昌六切","vol":"02","py":"chù","duan":[{"e":"至也。从止。叔聲。","n":"昌六切。三部。"}]},"𣦢":{"expl":"人不能行也。从止辟聲。","rad":"止","fq":"必益切","vol":"02","py":"bì","duan":[{"e":"人不能行也。","n":"王制。瘖聾跛躃。按跛說文作？。蹇也。蹇行？？。是能行而？邪不正者也。躃說文作𣦢。有足而不能行者。如有牟子而無見曰矇也。荀卿書、賈誼傳皆假辟字爲之。服虔曰。辟、病躃不能行也。"}]},"歸":{"expl":"女嫁也。从止，从婦省，𠂤聲。","rad":"止","fq":"舉韋切","vol":"02","py":"ɡuī","duan":[{"e":"女嫁也。","n":"公羊傳、毛傳皆云。婦人謂嫁歸。此非婦人假歸名。乃凡還家者假婦嫁之名也。"}]},"疌":{"expl":"疾也。从止从又。又，手也。屮聲。","rad":"止","fq":"疾葉切","vol":"02","py":"jié","duan":[{"e":"疾也。","n":"凡便捷之字當用此。捷、獵也。非其義。豫九四。朋盍簪。子夏傳云。簪、疾也。鄭云。速也。晁說之云。陰弘道按張揖古今字詁。？作？。？倉云。撍、疾也。說之案。撍簪同一字。王原叔謂卽詩不？字。祖感反。玉裁按。釋詁。寁、速也。本或作疌。"}]},"𤴘":{"expl":"機下足所履者。从止从又，入聲。","rad":"止","fq":"尼輒切","vol":"02","py":"niè","duan":[{"e":"機下足所履者。","n":"𤴘，者躡也。"}]},"𣥂":{"expl":"蹈也。从反止。讀若撻。","rad":"止","fq":"他達切","vol":"02","py":"tà","duan":[{"e":"蹈也。从反止。讀若撻。","n":"廣韵引文字音義同。他達切。十五部。"}]},"歰":{"expl":"不滑也。从四止。","rad":"止","fq":"色立切","vol":"02","py":"sè","duan":[{"e":"不滑也。从四止。","n":"色立切。七部。"}]},"癶":{"expl":"足剌癶也。从止、𣥂。凡癶之屬皆从癶。讀若撥。","rad":"癶","fq":"北末切","vol":"02","py":"bō","duan":[{"e":"足剌𣥠也。","n":"剌𣥠㬪韵字。剌盧達切。"}]},"登":{"expl":"上車也。从癶、豆。象登車形。","rad":"癶","fq":"都滕切","vol":"02","py":"dēnɡ","duan":[{"e":"上車也。","n":"引伸之凡上陞曰登。"}]},"癹":{"expl":"以足蹋夷艸。从癶从殳。《春秋傳》曰：“癹夷蘊崇之。”","rad":"癶","fq":"普活切","vol":"02","py":"bá","duan":[{"e":"㠯足蹋夷艸。","n":"周禮夷氏掌殺艸。一作雉氏。"}]},"環":{"expl":"璧也。肉好若一謂之環。从玉睘聲。","rad":"玉","fq":"戶關切","vol":"01","py":"huán","duan":[{"e":"璧肉好若一謂之環。","n":"亦見釋器。古者還人以環。亦瑞玉也。鄭注經解曰。環取其無窮止。肉上舊衍也字。"}]},"步":{"expl":"行也。从止𣥂相背。凡步之屬皆从步。","rad":"步","fq":"薄故切","vol":"02","py":"bù","duan":[{"e":"行也。","n":"行部曰。人之步趨也。步徐、趨疾。釋名曰。徐行曰步。"}]},"歲":{"expl":"木星也。越歴二十八宿，宣徧陰陽，十二月一次。从步戌聲。律歴書名五星爲五步。","rad":"步","fq":"相銳切","vol":"02","py":"suì","duan":[{"e":"木星也。","n":"五星。水曰辰星。金曰太白。火曰熒惑。木曰歲星。土曰塡星。"}]},"此":{"expl":"止也。从止从匕。匕，相比次也。凡此之屬皆从此。","rad":"此","fq":"雌氏切","vol":"","py":"cǐ","duan":[{"e":"止也。","n":"釋詁曰。巳、此也。正互相發明。於物爲止之処。於文爲止之䛐。"}]},"啙":{"expl":"窳也。闕。","rad":"此","fq":"將此切","vol":"02","py":"zǐ","duan":[{"e":"窳也。闕。","n":"將此切。十五十六部。按此非許本文。史記貨殖傳云。呰窳偷生。無積聚。漢地理志。啙窳媮生而無積聚。應劭曰。啙、弱也。晉灼曰。啙、病也。窳、惰也。徐廣曰。呰、窳、苟且惰嬾之謂也。師古曰。呰、短也。窳、弱也。言短力弱才不能勤作。是皆啙窳爲雙字。不以窳釋啙。小顏云啙短者、本方言。今說文以窳釋啙。非史、漢文義。又凡云闕者、或闕其義。或闕其音。或闕其形。旣釋爲窳。則義非闕也。其音則如淳音紫。其形則从此从吅、此亦聲。皆非葢闕無可言者。許以訾入言部。以呰入口部。惟啙不入吅部、入此部許必審知其說。今本葢許說亡後淺人補之也。釋詁曰茲斯咨呰巳此也。疑呰本作啙、訓此。故許類諸此止也、而入此部歟。"}]},"㭰":{"expl":"識也。从此朿聲。一曰藏也。","rad":"此","fq":"遵誄切","vol":"02","py":"zuǐ","duan":[{"e":"識也。从此。朿聲。","n":"遵誄切。古音在十六部。"}]},"些":{"expl":"語辭也。見《楚辭》。从此从二。其義未詳。","rad":"此","fq":"蘇箇切","vol":"02","py":"suò","duan":[]},"正":{"expl":"是也。从止，一以止。凡正之屬皆从正。","rad":"正","fq":"之盛切","vol":"02","py":"zhènɡ","duan":[{"e":"是也。从一。（句）一㠯止。","n":"江沅曰。一所㠯止之也。如乍之止亡、毋之止姦。皆以一止之。之盛切。十一部。"}]},"乏":{"expl":"《春秋傳》曰：“反正爲乏。”","rad":"正","fq":"房法切","vol":"02","py":"fá","duan":[{"e":"春秋傳曰。反正爲乏。","n":"左傳宣十五年文。此說字形而義在其中矣。不正則爲匱𣥄。二字相鄉背也。禮受矢者曰正。拒矢者曰𣥄。以其禦矢謂之𣥄。以獲者所容身謂之容。房法切。古音在七部。"}]},"是":{"expl":"直也。从日、正。凡是之屬皆从是。","rad":"是","fq":"承旨切","vol":"02","py":"shì","duan":[{"e":"直也。","n":"直部曰。正見也。"}]},"韙":{"expl":"是也。从是韋聲。《春秋傳》曰：“犯五不韙。”","rad":"是","fq":"于鬼切","vol":"02","py":"wěi","duan":[{"e":"是也。","n":"古文尙書曰。時五者來僃。今文尙書作五是來僃。李賢於李雲荀爽傳皆引史記五是來僃可證。凡史記多用今文尙書也。荀爽對策曰。五韙咸僃。韙與是義同。六書之轉注也。李雲上書曰。五氏來僃。氏與是音同在十六部。六書之叚借也。"}]},"璜":{"expl":"半璧也。从玉黃聲。","rad":"玉","fq":"戶光切","vol":"01","py":"huánɡ","duan":[{"e":"半璧也。","n":"鄭注周禮、高注淮南同。按大戴禮佩玉下有雙璜。皆半規。似璜而小。古者天子辟廱。築土雝水之外圜如璧。諸矦泮宮。泮之言半也。葢東西門以南通水。北無也。鄭箋詩云爾。然則辟廱似璧。泮宮似璜。此黌字之所由製歟。"}]},"尟":{"expl":"是少也。尟俱存也。从是、少。賈侍中說。","rad":"是","fq":"酥典切","vol":"02","py":"xiǎn","duan":[{"e":"是少也。","n":"易𣪠辭。故君子之道鮮矣。鄭本作尟。云少也。又尟不及矣。本亦作鮮。又釋詁。鮮、善也。本或作尠。尠者尟之俗。"}]},"辵":{"expl":"乍行乍止也。从彳从止。凡辵之屬皆从辵。讀若《春秋公羊傳》曰“辵階而走”。","rad":"辵","fq":"丑略切","vol":"02","py":"chuò","duan":[{"e":"乍行乍止也。","n":"公食大夫禮注曰。不拾級而下曰辵{彡+止[上下]}。鄭意不拾級而上曰栗階。亦曰歷階。不拾級下曰辵{彡+止[上下]}階也。廣雅。辵{彡+止[上下]}、奔也。"}]},"迹":{"expl":"步處也。从辵亦聲。","rad":"辵","fq":"資昔切","vol":"02","py":"jī","duan":[{"e":"步處也。","n":"莊子云。夫迹、履之所出。而迹豈履也。"}]},"𨘇":{"expl":"無違也。从辵𤛉聲。讀若害。","rad":"辵","fq":"胡蓋切","vol":"02","py":"huì","duan":[{"e":"無違也。","n":"舛部曰。舝、車軸耑鍵也。㒳相背从舛。𨘇从舝而曰無違。猶祀從巳而曰祭無巳也。"}]},"䢦":{"expl":"先道也。从辵率聲。","rad":"辵","fq":"疏密切","vol":"02","py":"shuài","duan":[{"e":"先道也。","n":"道今之導字。經典假率字爲之。周禮燕射。帥射夫以弓矢舞。故書帥爲率。鄭司農云。率當爲帥。大鄭以漢人帥領字通用帥。與周時用率不同故也。此所謂古今字。毛詩率時農夫。韓詩作帥時。許引周禮率都建旗。鄭周禮作帥都。聘禮注曰古文帥皆爲率。皆是也。又釋詁、毛傳皆云。率、循也。此引伸之義。有先導之者、乃有循而行者。亦謂之䢦也。"}]},"邁":{"expl":"遠行也。从辵，蠆省聲。","rad":"辵","fq":"莫話切","vol":"02","py":"mài","duan":[{"e":"遠行也。","n":"釋言、毛傳曰。邁行也。"}]},"巡":{"expl":"延行皃。从辵川聲。","rad":"辵","fq":"詳遵切","vol":"02","py":"xún","duan":[{"e":"視行也。","n":"也各本作皃。今依篇、韵訂。視行者、有所省視之行也。天子適諸矦曰巡狩。巡所守也。視行一作延行。延巡雙聲。"}]},"𨖏":{"expl":"恭謹行也。从辵㲃聲。讀若九。","rad":"辵","fq":"居又切","vol":"02","py":"jiù","duan":[{"e":"恭謹行也。从辵。㲃聲。讀若九。","n":"居又切。三部。"}]},"𨑒":{"expl":"步行也。从辵土聲。","rad":"辵","fq":"同都切","vol":"02","py":"tú","duan":[{"e":"步行也。","n":"賁初九。舍車而徒。引伸爲徒搏、徒涉、徒歌、徒擊𡔷。"}]},"邎":{"expl":"行邎徑也。从辵䌛聲。","rad":"辵","fq":"以周切","vol":"02","py":"yóu","duan":[{"e":"行邎徑也。","n":"玉篇。邎疾行也。按此當作行徑也。或作行由徑也。"}]},"祜":{"expl":"上諱。","rad":"示","fq":"候古切","vol":"01","py":"hù","duan":[{"e":"上諱。","n":"言上諱者五。禾部秀、漢世祖名也。艸部莊、顯宗名也。火部炟、肅宗名也。戈部肈、孝和帝名也。祜、恭宗名也。殤帝名隆不與焉。伏矦古今注曰。隆之字曰盛。亦當言上諱明矣。而五經異義云。漢幼小諸帝皆不廟祭。而祭於陵。旣不廟祭矣。則不諱可知。此許沖奏上時。於隆字不曰上諱所由也。諱止於世祖者。記曰。旣卒哭。宰夫執木鐸以徇於宫曰。舍故而諱新。故、謂高祖祖之父當遷者。杜預亦言自父至高祖皆不敢厈言。計許君卒於恭宗已後。自恭宗至世祖適五世。世祖已上雖高帝不諱。葢漢制也。此書之例。當是不書其字。但書上諱二字。書其字則非諱也。今本有篆文者。後人補之。不書故其詁訓形聲俱不言。假令補之。則曰祜福也、从示、古聲。祜訓福。則當與"}]},"琮":{"expl":"瑞玉。大八寸，似車釭。从玉宗聲。","rad":"玉","fq":"藏宗切","vol":"01","py":"cónɡ","duan":[{"e":"瑞玉。大八寸。似車釭。","n":"鄭注周禮曰。琮、八方象地。玉人日。大琮尺二寸。射四寸。注。射、其外鉏牙。疏云。角各出二寸。兩相幷。四寸也。玉裁按。除去射四寸。則大琮八方之徑八寸。許云瑞玉大八寸者、謂大琮也。其他琮不言射。惟瑑琮大八寸。如車釭者、葢車轂空中不正圜。爲八觚形。琮似之。琮釭曡韻。"}]},"𨒌":{"expl":"正、行也。从辵正聲。","rad":"辵","fq":"諸盈切","vol":"02","py":"zhēnɡ","duan":[{"e":"正行也。","n":"釋言、毛傳皆曰。征、行也。許分別之。征爲正行。邁爲遠行。"}]},"隨":{"expl":"从也。从辵，𡐦省聲。","rad":"辵","fq":"旬爲切","vol":"02","py":"suí","duan":[{"e":"从也。","n":"行可委曲從迹謂之委隨。"}]},"䢌":{"expl":"行皃。从辵巿聲。","rad":"辵","fq":"蒲撥切","vol":"02","py":"bó","duan":[{"e":"行皃。从辵。𣎵聲。","n":"按各本篆文作。非也。从卽禮切之𠂔。則不得云聲、云蒲撥切矣。普活切。隷變作巿。廣韵。䢌北末切。急走也。䟛蒲撥切。行皃。𧺡上同。此三字實一字。二音實一音也。許書言剌癶。癶與䢌音義同。自下文䢡譌爲䢌。因改此䢌爲𨒘而以蒲撥、北末分隷之。其誤久矣。十五部。"}]},"迋":{"expl":"往也。从辵王聲。《春秋傳》曰：“子無我迋。”","rad":"辵","fq":"于放切","vol":"02","py":"wànɡ","duan":[{"e":"往也。","n":"迋往疊韵。"}]},"逝":{"expl":"往也。从辵折聲。讀若誓。","rad":"辵","fq":"時制切","vol":"02","py":"shì","duan":[{"e":"往也。","n":"釋詁、方言同。方言曰。逝、秦晉語也。"}]},"䢐":{"expl":"往也。从辵且聲。䢐，齊語。","rad":"辵","fq":"全徒切","vol":"02","py":"cú","duan":[{"e":"往也。","n":"釋詁、方言皆曰。徂、往也。按鄭風匪我思且箋云。猶非我思存也。此謂且卽徂之叚借。釋詁又云。徂、存也是也。"}]},"述":{"expl":"循也。从辵术聲。","rad":"辵","fq":"食聿切","vol":"02","py":"shù","duan":[{"e":"循也。","n":"述循疊韵。述或叚借術爲之。如詩報我不述、本作術是也。古文多叚借遹爲之。如書祗遹乃文攷。詩遹駿有聲。遹追來孝。釋言、毛傳皆曰。遹、述也是也。孫炎曰。遹古述字。葢古文多以遹爲述。故孫云爾。謂今人用述。古人用遹也。凡言古今字者視此。"}]},"遵":{"expl":"循也。从辵尊聲。","rad":"辵","fq":"將倫切","vol":"02","py":"zūn","duan":[{"e":"循也。","n":"遵循疊韵。見釋詁。"}]},"適":{"expl":"之也。从辵啻聲。適，宋魯語。","rad":"辵","fq":"施隻切","vol":"02","py":"shì","duan":[{"e":"之也。","n":"釋詁。適之往也。方言。逝徂適往也。適、宋魯語也。按此不曰往而曰之。許意葢以之與往稍別。逝、徂、往自發動言之。適自所到言之。故變卦曰之卦。女子嫁曰適人。"}]},"過":{"expl":"度也。从辵咼聲。","rad":"辵","fq":"古禾切","vol":"02","py":"ɡuò","duan":[{"e":"度也。","n":"引伸爲有過之過。釋言。郵過也。謂郵亭是人所過。愆郵是人之過。皆是。分別平去聲者、俗說也。"}]},"琥":{"expl":"發兵瑞玉，爲虎文。从玉从虎，虎亦聲。《春秋傳》曰：“賜子家雙琥。”","rad":"玉","fq":"呼古切","vol":"01","py":"hǔ","duan":[{"e":"發兵瑞玉。","n":"周禮。牙璋以起軍旅。以治兵守。不以琥也。漢與郡國守相爲銅虎符。銅虎符從第一至第五。國家當發兵。遣使者至郡國合符。符合乃聽受之。葢以代牙璋也。許所云未聞。"}]},"遦":{"expl":"習也。从辵貫聲。","rad":"辵","fq":"工患切","vol":"02","py":"ɡuàn","duan":[{"e":"習也。","n":"此與手部摜音義同。"}]},"䢱":{"expl":"媟䢱也。从辵𧷏聲。","rad":"辵","fq":"徒谷切","vol":"02","py":"dú","duan":[{"e":"媟䢱也。","n":"女部作媟嬻。黑部作黷。今經典作瀆。"}]},"進":{"expl":"登也。从辵，閵省聲。","rad":"辵","fq":"卽刃切","vol":"02","py":"jìn","duan":[{"e":"登也。从辵。閵省聲。","n":"卽刃切。十三部。"}]},"造":{"expl":"就也。从辵告聲。譚長說：造，上士也。","rad":"辵","fq":"七到切","vol":"02","py":"zào","duan":[{"e":"就也。","n":"造就疊韵。廣雅。造詣也。"}]},"逾":{"expl":"𨒋進也。从辵俞聲。《周書》曰：“無敢昬逾。”","rad":"辵","fq":"羊朱切","vol":"02","py":"yú","duan":[{"e":"𨒋進也。","n":"𨒋進、有所超越而進也。"}]},"遝":{"expl":"䢔也。从辵眔聲。","rad":"辵","fq":"徒合切","vol":"02","py":"tà","duan":[{"e":"䢔也。","n":"廣韵。䢔、遝行相及也。文賦。紛葳蕤以馺遝。方言。迨遝、及也。東齊曰迨。關之東西曰遝。或曰及。公羊傳。祖之所逮聞也。漢石經作遝聞。"}]},"䢔":{"expl":"遝也。从辵合聲。","rad":"辵","fq":"侯閤切","vol":"02","py":"hé","duan":[{"e":"遝也。","n":"䢔遝疊韵。"}]},"迮":{"expl":"迮迮，起也。从辵，作省聲。","rad":"辵","fq":"阻革切","vol":"02","py":"zé","duan":[{"e":"迮迮。起也。","n":"此與人部作音義同。公羊傳。今若是迮而與季子國。何云。迮、起也。倉卒意。按孟子。乍見孺子將入於井。乍者倉卒意。卽迮之叚借也。引伸訓爲迫迮。卽今之窄字也。"}]},"逪":{"expl":"迹逪也。从辵昔聲。","rad":"辵","fq":"倉各切","vol":"02","py":"cuò","duan":[{"e":"䢒逪也。","n":"䢒各本作迹。依廣韵、玉篇正。小雅。獻醻交錯。毛曰。東西爲交。邪行爲錯。儀禮。交錯以辯旅醻行禮。一䢒一逪也。"}]},"遄":{"expl":"往來𢿙也。从辵耑聲。《易》曰：“㠯事遄往。”","rad":"辵","fq":"市緣切","vol":"02","py":"chuán","duan":[{"e":"往來數也。","n":"數、所角桑谷二切。釋詁曰。遄、疾也。速也。崧高、蒸民傳同。"}]},"瓏":{"expl":"禱旱玉。龍文。从玉从龍，龍亦聲。","rad":"玉","fq":"力鍾切","vol":"01","py":"lónɡ","duan":[{"e":"禱旱玉也。","n":"未聞。"}]},"速":{"expl":"疾也。从辵束聲。","rad":"辵","fq":"桑谷切","vol":"02","py":"sù","duan":[{"e":"疾也。","n":"見釋詁。"}]},"迅":{"expl":"疾也。从辵卂聲。","rad":"辵","fq":"息進切","vol":"02","py":"xùn","duan":[{"e":"疾也。","n":"見釋詁。迅疾疊韵。"}]},"适":{"expl":"疾也。从辵𠯑聲。讀與括同。","rad":"辵","fq":"古活切","vol":"02","py":"kuò","duan":[{"e":"疾也。从辵。𠯑聲。讀與括同。","n":"古活切。十五部。"}]},"逆":{"expl":"迎也。从辵屰聲。關東曰逆，關西曰迎。","rad":"辵","fq":"宜戟切","vol":"02","py":"nì","duan":[{"e":"迎也。","n":"逆迎雙聲。二字通用。如禹貢逆河、今文尙書作迎河是也。今人假以爲順屰之屰。逆行而屰廢矣。"}]},"迎":{"expl":"逢也。从辵卬聲。","rad":"辵","fq":"語京切","vol":"02","py":"yínɡ","duan":[{"e":"逢也。","n":"夆、牾也。逢、遇也。其理一也。"}]},"䢒":{"expl":"會也。从辵交聲。","rad":"辵","fq":"古肴切","vol":"02","py":"jiāo","duan":[{"e":"會也。","n":"東西正相值爲䢒。今人假交脛之交爲{䢒會字。"}]},"遇":{"expl":"逢也。从辵禺聲。","rad":"辵","fq":"牛具切","vol":"02","py":"yù","duan":[{"e":"逢也。从辵。禺聲。","n":"牛具切。古音在四部。"}]},"遭":{"expl":"遇也。从辵曹聲。一曰邐行。","rad":"辵","fq":"作曹切","vol":"02","py":"zāo","duan":[{"e":"遇也。","n":"見釋詁。"}]},"遘":{"expl":"遇也。从辵冓聲。","rad":"辵","fq":"古候切","vol":"02","py":"ɡòu","duan":[{"e":"遇也。","n":"見釋詁。易姤卦釋文曰。薛云古文作遘。鄭同。按襍卦傳。遘、遇也。柔遇剛也。可以證全經皆當作遘矣。遘遇疊韵。"}]},"逢":{"expl":"遇也。从辵，峯省聲。","rad":"辵","fq":"符容切","vol":"02","py":"fénɡ","duan":[{"e":"遇也。","n":"見釋詁。"}]},"琬":{"expl":"圭有琬者。从玉宛聲。","rad":"玉","fq":"於阮切","vol":"01","py":"wǎn","duan":[{"e":"圭有琬者。","n":"此當作圭首宛宛者。轉寫譌脫也。琬宛曡韻。先鄭云。琬圭無鋒𦬆。故以治德結好。後鄭云。琬猶圜也。王使之瑞節也。戴先生曰。凡圭剡上寸半。直剡之。倨句中矩。琬圭穹隆而起。宛然上見。玉裁謂。圜剡之、故曰圭首宛宛者。與𠀌上有𠀌爲宛𠀌同義。爾雅又云。宛中、宛𠀌。此與毛傳四方高中央下曰宛𠀌、釋名𠀌宛宛如偃器正同。謂窊其中宛宛然也。二義相反。俱得云宛。爾雅兼采異說。郭說宛中。失之。"}]},"遌":{"expl":"相遇驚也。从辵从㖾，㖾亦聲。","rad":"辵","fq":"五各切","vol":"02","py":"è","duan":[{"e":"相遇驚也。","n":"釋詁。遇、遻也。遻、見也。"}]},"迪":{"expl":"道也。从辵由聲。","rad":"辵","fq":"徒歴切","vol":"02","py":"dí","duan":[{"e":"道也。","n":"見釋詁。按道兼道路、引導二訓。方言。由迪正也。迪道疊韵。"}]},"遞":{"expl":"更易也。从辵虒聲。","rad":"辵","fq":"特計切","vol":"02","py":"dì","duan":[{"e":"更易也。","n":"招䰟。二八侍宿。射遞代些。王云。遞更也。遞易疊韵。"}]},"通":{"expl":"達也。从辵甬聲。","rad":"辵","fq":"他紅切","vol":"02","py":"tōnɡ","duan":[{"e":"達也。","n":"通達雙聲。達古音同闥。禹貢。達于河。今文尙書作通于河。按達之訓行不相遇也。通正相反。經傳中通達同訓者、正亂亦訓治、徂亦訓存之理。"}]},"𨑭":{"expl":"迻也。从辵止聲。","rad":"辵","fq":"斯氏切","vol":"02","py":"xǐ","duan":[{"e":"迻也。从辵止。","n":"各本有聲字。非也。止在一部。徙在十六部。從辵止會意者、乍行乍止而竟止則移其所矣。斯氏切。"}]},"迻":{"expl":"遷徙也。从辵多聲。","rad":"辵","fq":"弋支切","vol":"02","py":"yí","duan":[{"e":"遷徙也。","n":"今人假禾相倚移之移爲遷迻字。"}]},"遷":{"expl":"登也。从辵𠨧聲。","rad":"辵","fq":"七然切","vol":"02","py":"qiān","duan":[{"e":"登也。从辵䙴聲。","n":"七然切。十四部。"}]},"運":{"expl":"迻徙也。从辵軍聲。","rad":"辵","fq":"王問切","vol":"02","py":"yùn","duan":[{"e":"迻徙也。","n":"釋詁。遷運徙也。"}]},"遁":{"expl":"遷也。一曰逃也。从辵盾聲。","rad":"辵","fq":"徒困切","vol":"02","py":"dùn","duan":[{"e":"遷也。","n":"此字古音同循。遷延之意。凡逡遁字如此。今之逡巡也。儀禮鄭注用逡遁十有一。"}]},"遜":{"expl":"遁也。从辵孫聲。","rad":"辵","fq":"蘇困切","vol":"02","py":"xùn","duan":[{"e":"遁也。从辵。孫聲。","n":"穌困切。十三部。按六經有孫無遜。大雅孫謀、聘禮孫而說、學記不陵節而施之謂孫、論語孫以出之皆愻之叚借也。春秋夫人孫于齊、公孫於齊、詩公孫碩膚、尙書序將孫於位皆逡遁遷延之意。故穀梁云。孫之爲言猶孫也。公羊云。孫猶孫也。何休云。孫猶遁也。鄭箋云。孫之言孫遁也。釋言云。孫、遁也。釋名曰。孫、遜也。遜遁在後生也。古就孫義引伸。卑下如兒孫。非別有遜字也。至部𦥊字下云。從至。至而復孫。孫、遁也。此亦有孫無遜之證。今尙書、左氏經傳、爾雅釋言淺人改爲遜。許書遜遁也、葢後人據今本爾雅增之。非本有也。"}]},"璋":{"expl":"剡上爲圭，半圭爲璋。从玉章聲。《禮》：六幣：圭以馬，璋以皮，璧以帛，琮以錦，琥以繡，璜以黼。","rad":"玉","fq":"諸良切","vol":"01","py":"zhānɡ","duan":[{"e":"剡上爲圭。","n":"聘禮記曰。圭剡上寸半。雜記曰。剡上左右各半寸。"}]},"返":{"expl":"還也。从辵从反，反亦聲。《商書》曰：“祖甲返。”","rad":"辵","fq":"扶版切","vol":"02","py":"fǎn","duan":[{"e":"還也。","n":"返還疊韵。"}]},"還":{"expl":"復也。从辵瞏聲。","rad":"辵","fq":"戶關切","vol":"02","py":"huán","duan":[{"e":"復也。","n":"釋言。還復返也。今人還繞字用環。古經傳衹用還字。"}]},"選":{"expl":"遣也。从辵、巽，巽遣之；巽亦聲。一曰選，擇也。","rad":"辵","fq":"思沇切","vol":"02","py":"xuǎn","duan":[{"e":"遣也。","n":"選遣疊韵。左傳。秦後子有寵於桓。如二君於景。其母曰。弗去。懼選。鍼適晉。其車千乘。按此選字正訓遣。後子懼遣故適晉。實非出奔也。"}]},"送":{"expl":"遣也。从辵，㑞省。","rad":"辵","fq":"蘇弄切","vol":"02","py":"sònɡ","duan":[{"e":"遣也。从辵。㑞省。","n":"𠈪、送也。是會意。蘇弄切。九部。"}]},"遣":{"expl":"縱也。从辵𠳋聲。","rad":"辵","fq":"去衍切","vol":"02","py":"qiǎn","duan":[{"e":"縱也。","n":"糸部曰。縱、緩也。一曰舎也。"}]},"邐":{"expl":"行邐邐也。从辵麗聲。","rad":"辵","fq":"力紙切","vol":"02","py":"lǐ","duan":[{"e":"行邐邐也。","n":"邐邐、縈紆皃。"}]},"逮":{"expl":"唐逮，及也。从辵隶聲。","rad":"辵","fq":"徒耐切","vol":"02","py":"dài","duan":[{"e":"唐逮、（逗）及也。","n":"唐逮雙聲。葢古語也。釋言曰。遏遾逮也。方言曰。東齊曰蠍。北燕曰噬。逮通語也。"}]},"遲":{"expl":"徐行也。从辵犀聲。《詩》曰：“行道遲遲。”","rad":"辵","fq":"直尼切","vol":"02","py":"chí","duan":[{"e":"徐行也。","n":"今人謂稽延爲遲。平聲。謂待之爲遲。去聲。"}]},"邌":{"expl":"徐也。从辵黎聲。","rad":"辵","fq":"郎奚切","vol":"02","py":"lí","duan":[{"e":"徐也。","n":"或假黎爲之。史記衞霍傳。遲明。遲、待也。一作黎。傅毅賦。黎收而拜。李注。言舞將罷。徐收斂容態而拜。引倉頡篇。邌、徐也。又或假犂爲之。史記尉佗列傳。犂旦。城中皆降伏。犂旦卽黎明。漢書犂旦爲遲旦。晉世家。重耳妻笑曰。犂二十五年。吾冢上柏大矣。益可見犂之爲遲也。"}]},"遰":{"expl":"去也。从辵帶聲。","rad":"辵","fq":"特計切","vol":"02","py":"dì","duan":[{"e":"去也。","n":"夏小正。九月遰鴻鴈。遰、往也。"}]},"琰":{"expl":"璧上起美色也。从玉炎聲。","rad":"玉","fq":"以冉切","vol":"01","py":"yǎn","duan":[{"e":"璧上起美色也。","n":"璧當爲圭。也當爲者。周禮注云。凡圭剡上寸半。琰圭剡半以上。又半爲瑑飾。許云起美色。葢與鄭意同。或當作圭剡上起美飾者。若高注淮南、顏注司馬相如傳皆云。琬琰、美玉名。此當合二字爲一名。別是一物。尙書玉五重。琬琰亦是一物。非周禮之二圭也。"}]},"𨓯":{"expl":"行皃。从辵𣶒聲。","rad":"辵","fq":"烏玄切","vol":"02","py":"yuān","duan":[{"e":"行皃。从辵。𣶒聲。","n":"烏懸切。十二部。"}]},"𨙔":{"expl":"不行也。从辵𩣷聲。讀若住。","rad":"辵","fq":"中句切","vol":"02","py":"zhù","duan":[{"e":"不行也。","n":"不上有馬者誤。"}]},"逗":{"expl":"止也。从辵豆聲。","rad":"辵","fq":"田候切","vol":"02","py":"dòu","duan":[{"e":"止也。","n":"逗遛。"}]},"𨒅":{"expl":"曲行也。从辵只聲。","rad":"辵","fq":"綺戟切","vol":"02","py":"qì","duan":[{"e":"曲行也。","n":"𨒅曲雙聲。𠃊部曰。𨒅曲隱蔽。孟康注子虛賦曰。文理茀鬱𨒅曲。軍法有逗畱。有𨒅橈。光武紀。不拘以逗畱法。如淳曰。軍法行而逗畱畏偄者、要斬。此謂止而不進者。史、漢韓安國傳。廷尉當恢𨒅橈。當斬。服虔曰。𨒅音企。應劭曰。𨒅、曲行避敵也。橈、顧望也。軍法語也。此謂有意回遠遲誤者。淮南書云兩軍相當、屈橈者要斬是也。漢書一本作逗橈。蘇林逗、音豆。小顏、小司馬從之。而改服、應之注作逗。不可通矣。𨒅通作枳。明堂位注。枳椇謂曲橈之。莊子。吾行郤曲。郤曲卽𨒅曲。異部叚借也。"}]},"逶":{"expl":"逶迆，衺去之皃。从辵委聲。","rad":"辵","fq":"於爲切","vol":"02","py":"wēi","duan":[{"e":"逶迆、","n":"逗。疊韵。"}]},"迆":{"expl":"衺行也。从辵也聲。《夏書》曰：“東迆北，會于匯。”","rad":"辵","fq":"移尔切","vol":"02","py":"yǐ","duan":[{"e":"衺行也。从辵。也聲。","n":"移尒切。十六十七部。"}]},"遹":{"expl":"回避也。从辵矞聲。","rad":"辵","fq":"余律切","vol":"02","py":"yù","duan":[{"e":"回辟也。","n":"依韵會作辟。小雅。謀猶回遹。毛曰。回邪、遹辟也。按辟僻古今字。大雅兩言回遹。箋皆云。回邪。韓詩遹作穴。或作泬。或作鴥。皆叚借字也。遹古多假爲述字。釋言云。遹、述也。言叚借也。釋詁云。遹遵率循。釋訓云。不遹、不蹟也。皆謂遹卽述字也。言轉注也。不遹者、今邶風之報我不述也。"}]},"避":{"expl":"回也。从辵辟聲。","rad":"辵","fq":"毗義切","vol":"02","py":"bì","duan":[{"e":"回也。","n":"上文回辟之回訓衺𠆎之叚借字也。此回依本義訓轉。俗作迴是也。然其義實相近。"}]},"違":{"expl":"離也。从辵韋聲。","rad":"辵","fq":"羽非切","vol":"02","py":"wéi","duan":[{"e":"離也。","n":"邶風。中心有違。毛曰。違、離也。"}]},"遴":{"expl":"行難也。从辵㷠聲。《易》曰：“以往䢯。”","rad":"辵","fq":"良刃切","vol":"02","py":"lìn","duan":[{"e":"行難也。","n":"漢書。遴柬布章。遴𥳑謂難行封也。引伸爲遴𨕖。𨕖人必重難也。"}]},"玠":{"expl":"大圭也。从玉介聲。《周書》曰：“稱奉介圭。”","rad":"玉","fq":"古拜切","vol":"01","py":"jiè","duan":[{"e":"大圭也。","n":"攷工記。天子鎭圭。諸矦命圭。戴先生曰。二者皆謂之介圭。爾雅。圭大尺二寸爲玠。據鎭圭言也。詩。錫爾介圭。以作爾寶。據命圭言也。介者、大也。禮器。大圭不瑑。以素爲貴。亦謂此也。"}]},"逡":{"expl":"復也。从辵夋聲。","rad":"辵","fq":"七倫切","vol":"02","py":"qūn","duan":[{"e":"復也。","n":"彳部曰。復、往來也。方言。躔逡循也。日運爲躔。月運爲逡。"}]},"䢑":{"expl":"怒不進也。从辵氐聲。","rad":"辵","fq":"都禮切","vol":"02","py":"dǐ","duan":[{"e":"怒不進也。一曰驇也。","n":"惟鍇本有此四字。而驇从鳥則誤。馬部曰。驇、馬重皃。𡴂部曰。樊驇不行也。"}]},"達":{"expl":"行不相遇也。从辵羍聲。《詩》曰：“挑兮達兮。”","rad":"辵","fq":"徒葛切","vol":"02","py":"dá","duan":[{"e":"行不相遇也。","n":"此與水部滑、泰字音義皆同。讀如撻。今俗說不相遇尙有此言。乃古言也。讀徒葛切。訓通達者、今言也。"}]},"逯":{"expl":"行謹逯逯也。从辵录聲。","rad":"辵","fq":"盧谷切","vol":"02","py":"lù","duan":[{"e":"行謹逯逯也。","n":"張衡賦逯趗謂局小皃。義與此同。廣雅。逯逯衆也。女部。娽、隨从也。蕭相國世家平原君列傳作録録。義皆相近。"}]},"迵":{"expl":"迵，迭也。从辵同聲。","rad":"辵","fq":"徒弄切","vol":"02","py":"dònɡ","duan":[{"e":"迵、","n":"此複舉字之未𠜂者。"}]},"迭":{"expl":"更迭也。从辵失聲。一曰达。","rad":"辵","fq":"徒結切","vol":"02","py":"dié","duan":[{"e":"更迭也。","n":"或假佚字、迭字臷字爲之。"}]},"迷":{"expl":"或也。从辵米聲。","rad":"辵","fq":"莫兮切","vol":"02","py":"mí","duan":[{"e":"惑也。","n":"見釋言。惑、宋本作或。心部曰。惑、亂也。"}]},"連":{"expl":"員連也。从辵从車。","rad":"辵","fq":"力延切","vol":"02","py":"lián","duan":[{"e":"負車也。","n":"負車、各本作貟連。今正。連卽古文輦也。周禮鄉師輂輦、故書輦作連。大鄭讀爲輦。巾車連車。本亦作輦車。管子海王。服連軺輂。立政。餘戮民。不敢服絻。不敢畜連。負車者、人輓車而行。車在後如負也。字从辵車會意。猶輦从㚘車會意也。人與車相屬不絶。故引伸爲連屬字。耳部曰聯、連也。大宰注曰。古書連作聯。然則聯連爲古今字。連輦爲古今字。假連爲聯。乃專用輦爲連。大鄭當云連今之輦字。而云讀爲輦者、以今字易古字。令學者易曉也。許不於車部曰連古文輦而入之辵部者、小篆連與輦殊用。故云聯連也者、今義也。云連負車也者、古義也。"}]},"逑":{"expl":"斂聚也。从辵求聲。《虞書》曰：“㫄逑孱功。”又曰：“怨匹曰逑。”","rad":"辵","fq":"巨鳩切","vol":"02","py":"qiú","duan":[{"e":"斂聚也。","n":"勹部曰。勼、聚也。音義略同。"}]},"䢙":{"expl":"𣀩也。从辵貝聲。《周書》曰：“我興受其䢙。”","rad":"辵","fq":"薄邁切","vol":"02","py":"bài","duan":[{"e":"𣀩也。","n":"攵部曰。𣀩、毀也。䢙與敗音義同。"}]},"瑒":{"expl":"圭。尺二寸，有瓚，以祠宗廟者也。从玉昜聲。","rad":"玉","fq":"丑亮切","vol":"01","py":"chànɡ","duan":[{"e":"圭尺二寸。有瓚。以祠宗廟者也。","n":"玉人曰。祼圭尺有二寸。有瓚。以祀廟。祼圭謂之瑒圭。瑒讀如暢。魯語謂之鬯圭。用以灌鬯者也。祠玉篇作祀。"}]},"逭":{"expl":"逃也。从辵官聲。","rad":"辵","fq":"胡玩切","vol":"02","py":"huàn","duan":[{"e":"逃也。","n":"緇衣此大甲曰。天作孽可違也。自作孽不可以䠉。䠉本又作逭。鄭注。逭逃也。亦見釋言。"}]},"遯":{"expl":"逃也。从辵从豚。","rad":"辵","fq":"徒困切","vol":"02","py":"dùn","duan":[{"e":"逃也。","n":"鄭注周易曰。遯者、逃去之名。"}]},"逋":{"expl":"亾也。从辵甫聲。","rad":"辵","fq":"博孤切","vol":"02","py":"bū","duan":[{"e":"亡也。","n":"亡部曰。亡、逃也。訟九二曰。歸而逋。"}]},"遺":{"expl":"亾也。从辵䝿聲。","rad":"辵","fq":"以追切","vol":"02","py":"yí","duan":[{"e":"亡也。","n":"廣韵。失也。贈也。加也。按皆遺亡引伸之義也。"}]},"遂":{"expl":"亾也。从辵㒸聲。","rad":"辵","fq":"徐醉切","vol":"02","py":"suì","duan":[{"e":"亡也。","n":"廣韵。達也。進也。成也。安也。止也。往也。從志也。按皆引伸之義也。"}]},"逃":{"expl":"亾也。从辵兆聲。","rad":"辵","fq":"徒刀切","vol":"02","py":"táo","duan":[{"e":"亡也。","n":"亡逃互訓。"}]},"追":{"expl":"逐也。从辵𠂤聲。","rad":"辵","fq":"陟隹切","vol":"02","py":"zhuī","duan":[{"e":"逐也。","n":"詩禮假爲治金玉之鎚。"}]},"逐":{"expl":"追也。从辵，从豚省。","rad":"辵","fq":"直六切","vol":"02","py":"zhú","duan":[{"e":"追也。从辵。豖省聲。","n":"按鉉本作从豚省。鍇本、韵會作豕省。二字正豖省聲三字之誤也。直六切。三部。"}]},"逎":{"expl":"迫也。从辵酉聲。","rad":"辵","fq":"字秋切","vol":"02","py":"qiú","duan":[{"e":"迫也。","n":"大雅。似先公酋矣。正義。酋作遒。按酋者遒之叚借字。釋詁、毛傳皆曰。酋、終也。終與迫義相成。逎與揫義略同也。"}]},"近":{"expl":"附也。从辵斤聲。","rad":"辵","fq":"渠遴切","vol":"02","py":"jìn","duan":[{"e":"附也。","n":"許附爲附婁字。坿爲坿益字。疑附近當作坿也。經典釋文。遠近上聲。近之去聲。古無此分別。"}]},"瓛":{"expl":"桓圭。公所執。从玉獻聲。","rad":"玉","fq":"胡官切","vol":"01","py":"huán","duan":[{"e":"桓圭。公所執。","n":"大宗伯曰。公執桓圭。注。公、二王之後及王之上公。雙植謂之桓。桓、宫室之象。所以安其上。桓圭葢亦以桓爲瑑飾。玉裁按。鍇本作三公。韻會引亦無三。"}]},"邋":{"expl":"搚也。从辵巤聲。","rad":"辵","fq":"良涉切","vol":"02","py":"liè","duan":[{"e":"拹也。","n":"手部曰。拹、摺也。公羊傳曰。拹榦而殺之。邋拹疊韵。"}]},"迫":{"expl":"近也。从辵白聲。","rad":"辵","fq":"博陌切","vol":"02","py":"pò","duan":[{"e":"近也。","n":"釋言曰。逼、迫也。逼本又作偪。許無逼偪字。葢衹用畐。"}]},"𨖹":{"expl":"近也。从辵臸聲。","rad":"辵","fq":"人質切","vol":"02","py":"rì","duan":[{"e":"近也。","n":"釋言。馹、傳也。郭云。本或作𨖹。按此假𨖹爲馹也。聲類云。𨖹亦馹字。則附會爾雅或本而合爲一字。"}]},"邇":{"expl":"近也。从辵爾聲。","rad":"辵","fq":"兒氏切","vol":"02","py":"ěr","duan":[{"e":"近也。","n":"見釋詁、小雅毛傳。"}]},"遏":{"expl":"微止也。从辵曷聲。讀若桑蟲之蝎。","rad":"辵","fq":"烏割切","vol":"02","py":"è","duan":[{"e":"微止也。","n":"釋詁。遏、止也。按微者細密之意。"}]},"遮":{"expl":"遏也。从辵庶聲。","rad":"辵","fq":"止車切","vol":"02","py":"zhē","duan":[{"e":"遏也。从辵。庶聲。","n":"止車切。古音在五部。易用錫馬蕃庶。鄭讀爲藩遮。"}]},"䢭":{"expl":"遮䢭也。从辵羨聲。","rad":"辵","fq":"于線切","vol":"02","py":"yàn","duan":[{"e":"遮䢭也。","n":"此當是䢭遮也。之倒𠜂複字之僅存者。"}]},"迣":{"expl":"迾也。晉趙曰迣。从辵丗聲。讀若寘。","rad":"辵","fq":"征例切","vol":"02","py":"zhì","duan":[{"e":"迾也。晉趙曰迣。","n":"鮑宣傳。部落𡔷鳴。男女遮迣。此其義也。禮樂志。體容與。迣萬里。孟康迣音逝。此叚借也。"}]},"迾":{"expl":"遮也。从辵𠛱聲。","rad":"辵","fq":"良辥切","vol":"02","py":"liè","duan":[{"e":"遮也。","n":"周禮假厲爲之。山虞、澤虞、卝人、迹人厲禁。大鄭云。遮列守之是也。禮記假列爲之。玉藻。山澤列而不賦。鄭云。列之言遮列也是也。漢書假迣爲之。禮樂志、鮑宣傳晉灼云。迣古迾字是也。西京賦。迾卒淸𠋫。李引禮記注。迾、遮也。此可證玉藻注本作列之言迾遮也。今本誤。"}]},"迀":{"expl":"進也。从辵干聲。讀若干。","rad":"辵","fq":"古寒切","vol":"02","py":"ɡān","duan":[{"e":"進也。","n":"干求字當作迁。干犯字當作奸。"}]},"珽":{"expl":"大圭。長三尺，抒上，終葵首。从玉廷聲。","rad":"玉","fq":"他鼎切","vol":"01","py":"tǐnɡ","duan":[{"e":"大圭。長三尺。抒上。終葵首。","n":"見玉人。注曰。王所搢大圭也。或謂之珽。終葵、椎也。爲椎於其杼上。明無所屈也。杼、殺也。按玉藻謂之珽。注云。此亦笏也。珽之言挺然無所屈也。典瑞曰王晉大圭以朝日、魯語曰天子大采朝日、管子曰天子執玉笏以朝日皆謂此。司馬相如賦有晁采。晁古朝字。朝采卽朝日之大采也。長三尺。博三寸。葢自其中已上殺之。其殺六分而去一。至其首則仍博三寸而方之。鄭云。方如椎頭是也。珽王逸引相玉書作珵。抒今周禮作杼。玉藻注同。杼是也。"}]},"𨓲":{"expl":"過也。从辵侃聲。","rad":"辵","fq":"去虔切","vol":"02","py":"qiān","duan":[{"e":"過也。","n":"本義此爲經過之過。心部愆、㥶、諐爲有過之過。然其義相引伸也。故漢書劉輔傳云。元首無失道之？。"}]},"遱":{"expl":"連遱也。从辵婁聲。","rad":"辵","fq":"洛侯切","vol":"02","py":"lóu","duan":[{"e":"連遱也。","n":"連遱雙聲。集韵。連遱謂不絕皃。"}]},"𨔣":{"expl":"𨔣互，令不得行也。从辵枷聲。","rad":"辵","fq":"古牙切","vol":"02","py":"jiā","duan":[{"e":"𨔣牙、","n":"逗。"}]},"𨒋":{"expl":"踰也。从辵戉聲。《易》曰：“雜而不𨒋。”","rad":"辵","fq":"王伐切","vol":"02","py":"yuè","duan":[{"e":"踰也。","n":"足部曰。踰、𨒋也。踰與逾義小別。"}]},"逞":{"expl":"通也。从辵呈聲。楚謂疾行爲逞。《春秋傳》曰：“何所不逞欲。”","rad":"辵","fq":"丑郢切","vol":"02","py":"chěnɡ","duan":[{"e":"通也。","n":"方言曰。逞、快也。自山而東或曰逞。江淮陳楚之閒曰逞。又曰。逞、疾也。楚曰逞。又曰。逞、解也。"}]},"遼":{"expl":"遠也。从辵尞聲。","rad":"辵","fq":"洛蕭切","vol":"02","py":"liáo","duan":[{"e":"遠也。","n":"小雅。山川悠遠。維其勞矣。箋云。其道里長遠。邦域又勞勞廣闊。勞者、遼之叚借也。"}]},"遠":{"expl":"遼也。从辵袁聲。","rad":"辵","fq":"雲阮切","vol":"02","py":"yuǎn","duan":[{"e":"遼也。从辵。袁聲。","n":"雲阮切。十四部。"}]},"逖":{"expl":"遠也。从辵狄聲。","rad":"辵","fq":"他歴切","vol":"02","py":"tì","duan":[{"e":"遠也。","n":"釋詁。逷、遠也。按集韵云。說文引詩舍爾介逖。王伯厚詩攷因之。攷大雅作介狄。毛訓遠也。葢謂狄同逖。言叚借也。用逷蠻方。云逷、遠也。則言轉注也。集韵所據不足信。"}]},"迥":{"expl":"遠也。从辵冋聲。","rad":"辵","fq":"戶穎切","vol":"02","py":"jiǒnɡ","duan":[{"e":"遠也。","n":"見釋詁。大雅。泂酌彼行潦。毛曰。泂、遠也。謂泂爲迥之叚借也。"}]},"禮":{"expl":"履也。所以事神致福也。从示从豊，豊亦聲。","rad":"示","fq":"靈啓切","vol":"01","py":"lǐ","duan":[{"e":"𡳐也。","n":"見禮記祭義、周易序卦傳。𡳐、足所依也。引伸之凡所依皆曰𡳐。此假借之法。屨、𡳐也。禮、𡳐也。𡳐同而義不同。所㠯事神致福也。"}]},"瑁":{"expl":"諸侯執圭朝天子，天子執玉以冒之，似犂冠。《周禮》曰：“天子執瑁四寸。”从玉、冒，冒亦聲。","rad":"玉","fq":"莫報切","vol":"01","py":"mào","duan":[{"e":"諸矦執圭朝天子。天子執玉以冒之。似𤛿冠。周禮曰。天子執瑁四寸。","n":"玉人曰。天子執冒四寸以朝諸矦。注。名玉曰冒者、言德能覆葢天下也。四寸者方。以尊接卑。以小上爲貴。尙書大傳曰。古者圭必有冒。不敢專達也。天子執冒以朝諸矦。見則覆之。故冒圭者。天子所與諸矦爲瑞也。諸矦執所受圭以朝於天子。瑞也者、屬也。𤛿冠、爾雅注作犂錧。謂耜也。周禮匠人。耜廣五寸。二耜之伐廣尺。耜刃方。瑁上下方似之。"}]},"逴":{"expl":"遠也。从辵卓聲。一曰蹇也。讀若棹苕之棹。","rad":"辵","fq":"敕角切","vol":"02","py":"chuò","duan":[{"e":"遠也。","n":"哀時命曰。處逴逴而日遠。九章曰。道逴遠而日忘。"}]},"迂":{"expl":"避也。从辵于聲。","rad":"辵","fq":"憶倶切","vol":"02","py":"yū","duan":[{"e":"避也。","n":"迂曲回避。其義一也。"}]},"𨔥":{"expl":"目進極也。从辵𦘔聲。","rad":"辵","fq":"子僊切","vol":"02","py":"jiān","duan":[{"e":"自進極也。","n":"䢖進曡韵。埤倉云。？、至也。"}]},"邍":{"expl":"高平之野，人所登。从辵、备、录。闕。","rad":"辵","fq":"愚袁切","vol":"02","py":"yuán","duan":[{"e":"高平曰邍。","n":"此依韵會。各本作高平之野。非也。大司徒。山林川澤丘陵墳衍邍隰。鄭云。下平曰衍。高平曰原。下溼曰隰。釋地。廣平曰原。高平曰陸。此及鄭注皆以高平釋原者、謂大野廣平偁原。高而廣平亦偁原。下文所謂可食者曰原也。凡陸𨸏陵阿皆高地。其可種穀給食之處皆曰原。是之謂高平曰原也。序官邍師注云邍、地之廣平者。與大司徒注不同者、單言原則爲廣平。墳衍原隰並言則衍爲廣平、原爲高平也。邍字後人以水泉本之原代之。惟見周禮。"}]},"道":{"expl":"所行道也。从辵从𩠐。一達謂之道。","rad":"辵","fq":"徒皓切","vol":"02","py":"dào","duan":[{"e":"所行道也。","n":"毛傳每云行道也。道者人所行。故亦謂之行。道之引伸爲道理。亦爲引道。"}]},"遽":{"expl":"傳也。一曰窘也。从辵豦聲。","rad":"辵","fq":"其倨切","vol":"02","py":"jù","duan":[{"e":"傳也。","n":"釋言。馹遽傳也。孫炎曰。傳車、驛馬也。左傳僖卅三年。使遽告於鄭。遽興姜戎。昭二年。乘遽而至。傳中戀反。"}]},"迒":{"expl":"獸迹也。从辵亢聲。","rad":"辵","fq":"胡郎切","vol":"02","py":"hánɡ","duan":[{"e":"獸迹也。","n":"釋獸。兔迹迒。按序曰。黃帝之史倉頡見鳥獸蹏迒之迹。知分理之可相別異也。是凡獸迹皆偁迒。不專謂兔也。"}]},"𨑩":{"expl":"至也。从辵弔聲。","rad":"辵","fq":"都歴切","vol":"02","py":"dì","duan":[{"e":"至也。从辵。弔聲。","n":"都歷切。古音在二部。小雅、盤庚皆作弔。釋詁、毛傳皆云。弔、至也。至者、弔中引伸之義。加辵乃後人爲之。許葢本無此字。如本有之。則不當與邍道遽迒爲伍。"}]},"𨘢":{"expl":"行垂崖也。从辵𦤝聲。","rad":"辵","fq":"布賢切","vol":"02","py":"biān","duan":[{"e":"行垂崖也。","n":"釋詁曰。邊垂也。土部曰。垂、遠邊也。厂部曰。厓、山邊也。屵部曰。崖、高邊也。行於垂崖曰邊。因而垂崖謂之邊。然則邊不當廁於此。"}]},"邂":{"expl":"邂逅，不期而遇也。从辵解聲。","rad":"辵","fq":"胡懈切","vol":"02","py":"xiè","duan":[]},"璬":{"expl":"玉佩。从玉敫聲。","rad":"玉","fq":"古了切","vol":"01","py":"jiǎo","duan":[{"e":"玉佩。","n":"璬珩玦三字、鉉本在𤣽（玥）下瑞上。鍇本則珩玦又綴於部末。皆非舊次。凡一書內舊次可考者訂正之。此自璬至瑵九篆皆飾之類。古者雜佩謂之佩玉。見周禮玉府、大戴禮保傅篇、禮記玉藻。亦謂之玉佩。見詩秦風。璬之言皦也。玉石之白曰皦。"}]},"逅":{"expl":"邂逅也。从辵后聲。","rad":"辵","fq":"胡遘切","vol":"02","py":"hòu","duan":[]},"遑":{"expl":"急也。从辵皇聲。或从彳。","rad":"辵","fq":"胡光切","vol":"02","py":"huánɡ","duan":[]},"逼":{"expl":"近也。从辵畐聲。","rad":"辵","fq":"彼力切","vol":"02","py":"bī","duan":[]},"𨘷":{"expl":"遠也。从辵䫉聲。","rad":"辵","fq":"莫角切","vol":"02","py":"miǎo","duan":[]},"遐":{"expl":"遠也。从辵叚聲。","rad":"辵","fq":"胡加切","vol":"02","py":"xiá","duan":[]},"迄":{"expl":"至也。从辵气聲。","rad":"辵","fq":"許訖切","vol":"02","py":"qì","duan":[]},"迸":{"expl":"散走也。从辵并聲。","rad":"辵","fq":"北諍切","vol":"02","py":"bènɡ","duan":[]},"透":{"expl":"跳也。過也。从辵秀聲。","rad":"辵","fq":"他候切","vol":"02","py":"tòu","duan":[]},"邏":{"expl":"巡也。从辵羅聲。","rad":"辵","fq":"郎左切","vol":"02","py":"luó","duan":[]},"迢":{"expl":"迢，遰也。从辵召聲。","rad":"辵","fq":"徒聊切","vol":"02","py":"tiáo","duan":[]},"珩":{"expl":"佩上玉也。所以節行止也。从玉行聲。","rad":"玉","fq":"戶庚切","vol":"01","py":"hénɡ","duan":[{"e":"佩上玉也。","n":"詩毛傳曰。雜佩者、珩璜琚瑀衝牙之類。韓傳曰。佩玉上有蔥衡。下有雙璜、衝牙。蠙珠以納其閒。按衡卽珩字。晉語白玉之珩六雙注。珩、佩上飾。楚語楚之白珩注。珩佩上之橫者。玉藻曰。一命、再命幽衡。三命蔥衡。注。衡、佩上之衡也。其制珩上橫爲組三。繫於珩。繫於中組者曰衝牙。繫於左右組者曰璜。皆以玉。璜似半璧而小。亦謂之牙。繫於中者觸牙而成聲。故曰衝牙。蠙珠琚瑀貫於珩之下、璜衝牙之上。故毛、韓、大戴皆曰。以納其閒。云佩上玉者、謂此乃玉佩最上之玉也。統言曰佩玉。析言則珩居首、以玉爲之。依玉藻所言。則當天子白玉珩。公矦山玄玉珩。大夫水蒼玉珩。所謂三命蔥珩。士瑌玟、則以石。月令。春倉玉。夏赤玉。中央黃玉。秋白玉。冬"}]},"逍":{"expl":"逍遥，猶翱翔也。从辵肖聲。","rad":"辵","fq":"相邀切","vol":"02","py":"xiāo","duan":[]},"遥":{"expl":"逍遥也。又，遠也。从辵䍃聲。","rad":"辵","fq":"余招切","vol":"02","py":"yáo","duan":[]},"彳":{"expl":"小步也。象人脛三屬相連也。凡彳之屬皆从彳。","rad":"彳","fq":"丑亦切","vol":"02","py":"chì","duan":[{"e":"小步也。象人脛三屬相連也。","n":"三屬者。上爲股、中爲脛、下爲足也。單舉脛者、舉中以該上下也。脛動而股與足隨之。丑亦切。李斯作？。筆迹小變也。"}]},"德":{"expl":"升也。从彳㥁聲。","rad":"彳","fq":"多則切","vol":"02","py":"dé","duan":[{"e":"𦫵也。","n":"𦫵當作登。辵部曰。遷、登也。此當同之。德訓登者。公羊傳。公曷爲遠而觀魚。登來之也。何曰。登讀言得。得來之者、齊人語。齊人名求得爲得來。作登來者、其言大而急。由口授也。唐人詩。千水千山得得來。得卽德也。登德雙聲。一部與六部合韵又冣近。今俗謂用力徙前曰德。古語也。"}]},"徑":{"expl":"步道也。从彳巠聲。","rad":"彳","fq":"居正切","vol":"02","py":"jìnɡ","duan":[{"e":"步道也。","n":"周禮。夫閒有遂。遂上有徑。鄭曰。徑容牛馬。畛容大車。涂容乘車一軌。道容二軌。路容三軌。此云步道、謂人及牛馬可步行而不容車也。"}]},"復":{"expl":"往來也。从彳复聲。","rad":"彳","fq":"房六切","vol":"02","py":"fù","duan":[{"e":"往來也。","n":"辵部曰。返、還也。還、復也。皆訓往而仍來。今人分別入聲去聲。古無是分別也。"}]},"𢔟":{"expl":"復也。从彳从柔，柔亦聲。","rad":"彳","fq":"人九切","vol":"02","py":"rǒu","duan":[{"e":"復也。","n":"此字引伸爲狃忕之義。故玉篇云。習也。忕也。或與狃同。按狃行而？廢矣。左傳有愎字。愎者、狃忕之意。卽復字之變也。復之引伸之義亦爲狃忕。"}]},"徎":{"expl":"徑行也。从彳呈聲。","rad":"彳","fq":"丑郢切","vol":"02","py":"chěnɡ","duan":[{"e":"徑行也。","n":"廣韵丈井切。雨後徑也。玉篇力整丈井二切。徑也。"}]},"往":{"expl":"之也。从彳㞷聲。","rad":"彳","fq":"于兩切","vol":"02","py":"wǎnɡ","duan":[{"e":"之也。从彳。𡉚聲。","n":"于兩切。十部。"}]},"忂":{"expl":"行皃。从彳瞿聲。","rad":"彳","fq":"其俱切","vol":"02","py":"qú","duan":[{"e":"行皃。","n":"此與足部躣音義同。走部又有𧾱。"}]},"玦":{"expl":"玉佩也。从玉夬聲。","rad":"玉","fq":"古穴切","vol":"01","py":"jué","duan":[{"e":"玉佩也。","n":"九歌注曰。玦、玉佩也。先王所以命臣之瑞。故與環卽還、與玦卽去也。白虎通曰。君子能決斷則佩玦。韋昭曰。玦如環而缺。"}]},"彼":{"expl":"往，有所加也。从彳皮聲。","rad":"彳","fq":"補委切","vol":"02","py":"bǐ","duan":[{"e":"往有所加也。","n":"彼加曡韵。"}]},"徼":{"expl":"循也。从彳敫聲。","rad":"彳","fq":"古堯切","vol":"02","py":"jiào","duan":[{"e":"循也。","n":"百官表曰。中尉掌徼循京師。如淳曰。所謂游徼循禁僃盜賊也。按引伸爲徼求、爲邊徼。今人分平去。古無是也。"}]},"循":{"expl":"行順也。从彳盾聲。","rad":"彳","fq":"詳遵切","vol":"02","py":"xún","duan":[{"e":"行也。","n":"各本作行順也。淺人妄增耳。依大誓正義、衆經音義所引訂。行今音讀下孟反。如月令循行國邑、出行田原、循行縣鄙、周禮注行夜皆是也。釋詁。遹遵率循也。引伸爲撫循、爲循循有序。"}]},"彶":{"expl":"急行也。从彳及聲。","rad":"彳","fq":"居立切","vol":"02","py":"jí","duan":[{"e":"急行也。","n":"急彶曡韵。凡用汲汲字、乃彶彶之叚借也。"}]},"𢕬":{"expl":"行皃。从彳歰聲。一曰此與馺同。","rad":"彳","fq":"穌合切","vol":"02","py":"sà","duan":[{"e":"行皃。","n":"吳都賦。㒊譶澩㺒。㒊當从彳。廣韵。？、衆行皃。"}]},"微":{"expl":"隱行也。从彳𢼸聲。《春秋傳》曰：“白公其徒微之。”","rad":"彳","fq":"無非切","vol":"02","py":"wēi","duan":[{"e":"隱行也。","n":"𢼸訓眇。微从彳、訓隱行。叚借通用微而？不行。邶風。微我無酒。又假微爲非。"}]},"徥":{"expl":"徥徥，行皃。从彳是聲。《爾雅》曰：“徥，則也。”","rad":"彳","fq":"是支切","vol":"02","py":"shì","duan":[{"e":"徥徥行皃也。","n":"方言。徥用行也。郭曰。徥皆行皃。度揩反。集韵曰。徍徥、行皃。於佳度皆二切。"}]},"徐":{"expl":"安行也。从彳余聲。","rad":"彳","fq":"似魚切","vol":"02","py":"xú","duan":[{"e":"安行也。从彳。余聲。","n":"似魚切。五部。"}]},"𢓡":{"expl":"行平易也。从彳夷聲。","rad":"彳","fq":"以脂切","vol":"02","py":"yí","duan":[{"e":"行平易也。","n":"廣雅。𢓡𢓡行也。按凡平訓皆當作𢓡。今則夷行𢓡廢矣。"}]},"𢖊":{"expl":"使也。从彳䛣聲。","rad":"彳","fq":"普丁切","vol":"02","py":"pīnɡ","duan":[{"e":"使也。","n":"疑使上當有𢖊𢓱二字。周頌。莫予？蜂。蜂本又作夆。毛曰。？夆、𤸪曳也。釋訓作甹夆、𤸪曳也。𢖊𢓱、葢甹夆之正字。𤸪曳者、使之也。大雅傳曰。？、使也。"}]},"瑞":{"expl":"以玉爲信也。从玉、耑。","rad":"玉","fq":"是僞切","vol":"01","py":"ruì","duan":[{"e":"以玉爲信也。","n":"典瑞。掌玉瑞玉器之藏。注云。人執以見曰瑞。禮神曰器。又云。瑞、節信也。說文卪下云。瑞信也。是瑞卪二字爲轉注。禮神之器亦瑞也。瑞爲圭璧璋琮之總偁。自璧至瑁十五字皆瑞也。故總言之。引伸爲祥瑞者、亦謂感召若符節也。"}]},"𢓱":{"expl":"使也。从彳夆聲。讀若螽。","rad":"彳","fq":"敷容切","vol":"02","py":"fēnɡ","duan":[{"e":"使也。","n":"疑當作𢖊𢓱也三字。"}]},"㣤":{"expl":"迹也。从彳戔聲。","rad":"彳","fq":"慈衍切","vol":"02","py":"jiàn","duan":[{"e":"迹也。","n":"豳風。籩豆有踐。箋云。踐、行列皃。按踐同㣤。故云行列皃。"}]},"徬":{"expl":"附行也。从彳㫄聲。","rad":"彳","fq":"蒲浪切","vol":"02","py":"bànɡ","duan":[{"e":"附行也。","n":"牛人。共兵車之牛與其牽徬。注曰。牽徬、在轅外輓牛也。人御之。居其前曰牽。居其旁曰徬。按傍、附也。从人、徬、附行也。从彳。此音同義微別也。"}]},"徯":{"expl":"待也。从彳奚聲。","rad":"彳","fq":"胡計切","vol":"02","py":"xī","duan":[{"e":"待也。","n":"孟子引書徯我后。趙曰。徯、待也。"}]},"待":{"expl":"竢也。从彳寺聲。","rad":"彳","fq":"徒在切","vol":"02","py":"dài","duan":[{"e":"竢也。","n":"立部曰。竢待也。"}]},"㣙":{"expl":"行㣙㣙也。从彳由聲。","rad":"彳","fq":"徒歴切","vol":"02","py":"dí","duan":[{"e":"行㣙㣙也。","n":"㣙㣙葢與小弁踧踧同。行平易也。皆徒厤切。玉篇云。㣙除又切。與宙同。古往今來無極之名。"}]},"徧":{"expl":"帀也。从彳扁聲。","rad":"彳","fq":"比薦切","vol":"02","py":"biàn","duan":[{"e":"帀也。","n":"帀部曰。帀、𠣘也。勹部曰。𠣘、帀徧也。"}]},"徦":{"expl":"至也。从彳叚聲。","rad":"彳","fq":"古雅切","vol":"02","py":"jiǎ","duan":[{"e":"至也。","n":"方言曰。徦𢓜至也。邠唐冀兖之閒曰徦。或曰𢓜。按𢓜古格字。徦今本方言作假。非也。集韵四十禡可證。毛詩三頌假字或訓大也。或訓至也。訓至則爲徦之假借。尙書古文作格。今文作假。如假于上下是也。亦徦之假借。"}]},"𢓴":{"expl":"卻也。一曰行遲也。从彳从日从夊。","rad":"彳","fq":"他内切","vol":"02","py":"tuì","duan":[{"e":"卻也。从彳日夊。","n":"彳、行也。行而日日遲曳。是退也。夊、行遲曳夊夊也。他內切。十五部。"}]},"後":{"expl":"遲也。从彳、幺、夊者，後也。","rad":"彳","fq":"胡口切","vol":"02","py":"hòu","duan":[{"e":"遲也。从彳幺夊。幺夊者後也。","n":"各本奪二字。今補。幺者小也。小而行遲。後可知矣。故从幺夊會意。胡口切。四部。"}]},"珥":{"expl":"瑱也。从玉、耳，耳亦聲。","rad":"玉","fq":"仍吏切","vol":"01","py":"ěr","duan":[{"e":"瑱也。","n":"戰國策。孟嘗君進五珥。以請立后。李斯上書曰。宛珠之簪。傅璣之珥。"}]},"徲":{"expl":"久也。从彳犀聲。讀若遲。","rad":"彳","fq":"杜兮切","vol":"02","py":"tí","duan":[{"e":"久也。","n":"久疑當作夂。"}]},"很":{"expl":"不聽从也。一曰行難也。一曰盭也。从彳𥃩聲。","rad":"彳","fq":"胡懇切","vol":"02","py":"hěn","duan":[{"e":"不聽從也。一曰行難也。从彳。𥃩聲。","n":"胡𢡆切。十三部。"}]},"㣫":{"expl":"相迹也。从彳重聲。","rad":"彳","fq":"之隴切","vol":"02","py":"zhǒnɡ","duan":[{"e":"相迹也。","n":"後迹與前迹相繼也。玄應合踵㣫爲一字。"}]},"得":{"expl":"行有所得也。从彳㝵聲。","rad":"彳","fq":"多則切","vol":"02","py":"dé","duan":[{"e":"行有所㝵也。","n":"㝵各本作得誤。今正。見部曰。䙷、取也。行而有所取。是曰得也。左傳曰。凡獲器用曰得。"}]},"徛":{"expl":"舉脛有渡也。从彳奇聲。","rad":"彳","fq":"去奇切","vol":"02","py":"jì","duan":[{"e":"舉脛有渡也。","n":"釋宫曰。石杠謂之徛。郭曰。聚石水中以爲步渡彴也。音居義反。"}]},"𢓈":{"expl":"行示也。从彳勻聲。《司馬法》：“斬以𢓈。”","rad":"彳","fq":"詞閏切","vol":"02","py":"xùn","duan":[{"e":"行示也。","n":"大司馬。斬牲以左右徇陳曰。不用命者斬之。小子。凡師田、斬牲以左右徇陳。陸德明引古今字詁曰。徇、巡也。按如項羽傳。徇廣陵、徇下縣。李奇曰。徇、略也。如淳曰。徇音撫循之循。此古用循巡字、漢用徇字之證。此古今字詁之義也。"}]},"律":{"expl":"均布也。从彳聿聲。","rad":"彳","fq":"呂戌切","vol":"02","py":"lǜ","duan":[{"e":"均布也。","n":"均律雙聲。均古音同匀也。易曰。師出以律。尙書。正日。同律度量衡。爾雅。坎律銓也。律者所以笵天下之不一而歸於一。故曰均布也。"}]},"御":{"expl":"使馬也。从彳从卸。","rad":"彳","fq":"牛據切","vol":"02","py":"yù","duan":[{"e":"使馬也。","n":"周禮六藝。四曰五馭。大宰注曰。凡言馭者、所以？之內之於善。此引伸之義也。"}]},"亍":{"expl":"步止也。从反彳。讀若畜。","rad":"彳","fq":"丑玉切","vol":"02","py":"chù","duan":[{"e":"步止也。","n":"魏都賦曰。澤馬亍阜。赭白馬賦曰。秀騏齊亍。"}]},"廴":{"expl":"長行也。从彳引之。凡廴之屬皆从廴。","rad":"廴","fq":"余忍切","vol":"02","py":"yǐn","duan":[{"e":"長行也。","n":"玉篇曰。今作引。是引弓字行而廴廢也。"}]},"瑱":{"expl":"以玉充耳也。从玉眞聲。《詩》曰：“玉之瑱兮。”","rad":"玉","fq":"他甸切","vol":"01","py":"tiàn","duan":[{"e":"㠯玉充耳也。","n":"詩毛傳曰。瑱、塞耳也。又曰。充耳謂之瑱。天子玉瑱。諸矦以石。按瑱不皆以玉。許專云以玉者、爲其字之从玉也。凡字从某爲某之屬。許君必言其故。"}]},"廷":{"expl":"朝中也。从廴壬聲。","rad":"廴","fq":"特丁切","vol":"02","py":"tínɡ","duan":[{"e":"朝中也。","n":"朝中者、中於朝也。古外朝、治朝、燕朝、皆不屋。在廷。故雨霑服失容則廢。"}]},"𢌛":{"expl":"行也。从廴正聲。","rad":"廴","fq":"諸盈切","vol":"02","py":"zhēnɡ","duan":[{"e":"行也。","n":"此與辵部延征字音義同。漢武帝年號延和字如此作。今漢書多誤爲以然切之延。又或改爲从辵之延。亦非也。"}]},"建":{"expl":"立朝律也。从聿从廴。","rad":"廴","fq":"居萬切","vol":"02","py":"jiàn","duan":[{"e":"立朝律也。","n":"今謂凡豎立爲建。許云。立朝律也。此必古義。今未攷出。"}]},"㢟":{"expl":"安步㢟㢟也。从廴从止。凡㢟之屬皆从㢟。","rad":"㢟","fq":"丑連切","vol":"02","py":"chān","duan":[{"e":"安步㢟㢟也。从廴止。","n":"引而復止、是安步也。丑連切。十四部。魏志。鍾會兄子毅及峻辿下獄。裴曰。辿勑連反。按卽㢟字也。止之隷變作山。"}]},"延":{"expl":"長行也。从㢟丿聲。","rad":"㢟","fq":"以然切","vol":"02","py":"yán","duan":[{"e":"長行也。","n":"本義訓長行。引伸則專訓長。方言曰。延長也。凡施於年者謂之延。又曰。延徧也。"}]},"行":{"expl":"人之步趨也。从彳从亍。凡行之屬皆从行。","rad":"行","fq":"戶庚切","vol":"02","py":"xínɡ","duan":[{"e":"人之步趨也。","n":"步、行也。趨、走也。二者一徐一疾。皆謂之行。統言之也。爾雅。室中謂之時。堂上謂之行。堂下謂之步。門外謂之趨。中庭謂之走。大路謂之奔。析言之也。引伸爲巡行、行列、行事、德行。"}]},"術":{"expl":"邑中道也。从行术聲。","rad":"行","fq":"食聿切","vol":"02","py":"shù","duan":[{"e":"邑中道也。","n":"邑、國也。引伸爲技術。"}]},"街":{"expl":"四通道也。从行圭聲。","rad":"行","fq":"古膎切","vol":"02","py":"jiē","duan":[{"e":"四通道也。","n":"風俗通曰。街、攜也。離也。四出之路、攜離而別也。按此以曡韵爲訓。"}]},"衢":{"expl":"四達謂之衢。从行瞿聲。","rad":"行","fq":"其俱切","vol":"02","py":"qú","duan":[{"e":"四達謂之衢。","n":"釋宮文。釋名曰。四達曰衢。齊魯閒謂四齒杷爲欋。欋杷地則有四處。此道似之也。按中山經。宣山桑枝四衢。少室山木曰帝休。枝五衢。天問。靡萍九衢。淮南書。木大則根欋。皆謂䢒逪岐出。"}]},"𧘂":{"expl":"通道也。从行童聲。《春秋傳》曰：“及𧘂，以戈擊之。”","rad":"行","fq":"昌容切","vol":"02","py":"chōnɡ","duan":[{"e":"通道也。","n":"衝通曡韵。引伸之義爲當也。向也。突也。"}]},"琫":{"expl":"佩刀上飾。天子以玉，諸矦以金。从玉奉聲。","rad":"玉","fq":"邊孔切","vol":"01","py":"běnɡ","duan":[{"e":"佩刀上飾也。","n":"小雅鞞琫有珌傳。鞞、容刀鞞也。琫、上飾。珌、下飾。大雅鞞琫容刀傳。下曰鞞、上曰琫。戴先生疑瞻彼洛矣之珌下飾。當爲鞞下飾。珌文飾皃。有珌與首章有奭句法同。說文訓鞞爲刀室。誤也。玉裁按。鞞之言裨也。刀室所以裨護刀者。漢人曰削。俗作鞘。琫之言奉也。奉俗作捧。刀本曰環。人所捧握也。其飾曰琫。珌之言畢也。刀室之末。其飾曰珌。古文作㻫。傳云。鞞、容刀鞞也。謂刀削。其云琫上飾、珌下飾者。上下自全刀言之。琫在鞞上。鞞𡉄琫下。珌在鞞末。公劉詩不言珌。故云下曰鞞。舉鞞以該珌。鞞琫有珌。言鞞琫而又加珌也。王莽傳。瑒琫瑒珌。孟康曰。佩刀之飾。上曰琫。下曰珌。若劉熙釋名曰。室口之飾曰琫。琫、捧也。捧束口也。下末之飾曰琕"}]},"衕":{"expl":"通街也。从行同聲。","rad":"行","fq":"徒弄切","vol":"02","py":"tónɡ","duan":[{"e":"通街也。","n":"衕通曡韵。今京師衚衕字如此作。"}]},"𧗸":{"expl":"迹也。从行戔聲。","rad":"行","fq":"才綫切","vol":"02","py":"jiàn","duan":[{"e":"迹也。","n":"此與彳部㣤音義同。"}]},"衙":{"expl":"行皃。从行吾聲。","rad":"行","fq":"魚舉切","vol":"02","py":"yú","duan":[{"e":"衙衙、","n":"依廣韵九魚補二字。"}]},"衎":{"expl":"行喜皃。从行干聲。","rad":"行","fq":"空旱切","vol":"02","py":"kàn","duan":[{"e":"行喜皃。","n":"小雅毛傳曰。衎、樂也。"}]},"𧗳":{"expl":"行且賣也。从行从言。","rad":"行","fq":"黃絢切","vol":"02","py":"xuàn","duan":[{"e":"行且賣也。","n":"周禮。飾行儥慝。大鄭云。儥、賣也。慝、惡也。謂行且賣姦僞惡物者。後鄭云。謂使人行賣惡物於市。巧飾之令欺誑？者。"}]},"𧗿":{"expl":"將衞也。从行率聲。","rad":"行","fq":"所律切","vol":"02","py":"shuài","duan":[{"e":"將𧗿也。","n":"𧗿也今本作衞也。誤。將、如鳥將雛之將。古不分平去也。𧗿、導也。循也。今之率字。率行而𧗿廢矣。率者、捕鳥畢也。將帥字古衹作將𧗿。帥行而𧗿又廢矣。帥者、佩巾也。𧗿與辵部䢦音義同。"}]},"衞":{"expl":"宿衞也。从韋、帀，从行。行，列衞也。","rad":"行","fq":"于歲切","vol":"02","py":"wèi","duan":[{"e":"宿衞也。","n":"宮正。夕擊？而比之。注。暮行夜以比直宿者。宮伯。掌王宮之士庶子凡在版者。大鄭云。庶子宿衞之官。後鄭云。衞王宮者必居四角四中。於徼𠋫便也。漢有衞尉掌宮門衞屯兵。"}]},"齒":{"expl":"口齗骨也。象口齒之形，止聲。凡齒之屬皆从齒。","rad":"齒","fq":"昌里切","vol":"02","py":"chǐ","duan":[{"e":"口齗骨也。","n":"鄭注周禮曰。人生齒而體僃。男八月、女七月而生齒。"}]},"齗":{"expl":"齒本也。从齒斤聲。","rad":"齒","fq":"語斤切","vol":"02","py":"yín","duan":[{"e":"齒本肉也。","n":"各本無肉。玄應兩引作齒肉也。篇、韵皆作齒根肉也。今補。齗爲肉。故上文齒爲齗骨。此骨出肉外。故肉爲骨本。魯世家。甚矣魯道之衰也。洙泗之閒齗齗如也。地理志云。魯濱洙泗。其民涉渡。幼者扶老者而代其任。俗旣薄。長老不自安。與幼者相讓。故曰魯道衰。洙泗之閒齗齗如也。按彼此爭辤。露其齒本。故曰齗齗。徐廣五艱反。又按曲禮。𥬇不至矧。鄭云。齒本曰矧。大𥬇則見。矧正齗之近部叚借字也。"}]},"齔":{"expl":"毀齒也。男八月生齒，八歲而齔。女七月生齒，七歲而齔。从齒从七。","rad":"齒","fq":"初堇切","vol":"02","py":"chèn","duan":[{"e":"毀齒也。男八月生齒。八歲而齔。女七月生齒。七歲而齔。从齒匕。","n":"各本篆作齔。云从齒、从七。初忍初覲二音。殆傅會七聲爲之。今按其字从齒𠤎。𠤎、變也。今音呼？切。古音如貨。本命曰。陰以陽化。陽以陰變。故男以八月生齒。八歲而毀。女七月生齒。七歲而毀。毀與化義同音近。玄應書卷五。齔舊音差貴切。卷十一。舊音羌貴切。然則古讀如未韵之？。葢本从匕。匕亦聲。轉入寘至韵也。自誤从七旁。玄應云初忍切。孫愐云初堇切。廣韵乃初覲切。集韵乃初問恥問二切。其形唐宋人又譌齓从乚。絕不可通矣。今當依舊音差貴切。古音葢在十七部。"}]},"珌":{"expl":"佩刀下飾。天子以玉。从玉必聲。","rad":"玉","fq":"卑吉切","vol":"01","py":"bì","duan":[{"e":"佩刀下飾。天子以玉。","n":"毛傳云。天子以珧。說文珧字下亦云。天子珧珌。此當人云。天子以珧。諸矦以玉。淺人妄竄改之。"}]},"䶦":{"expl":"齒相值也。一曰齧也。从齒責聲。《春秋傳》曰：“晳䶦。”","rad":"齒","fq":"士革切","vol":"02","py":"zé","duan":[{"e":"齒相値也。","n":"今左傳作幘。譌字也。古無幘。則述傳時無此字也。杜云。齒上下相値也。按謂上下齒整齊相對。詩所云如瓠屖。"}]},"齜":{"expl":"齒相齗也。一曰開口見齒之皃。从齒，柴省聲。讀若柴。","rad":"齒","fq":"仕街切","vol":"02","py":"chái","duan":[{"e":"齒相齘也。","n":"齘各本誤齗。李本不誤。廣韵。？？、齒不正。上士佳、下五佳切。玉篇曰。？亦作？。"}]},"齘":{"expl":"齒相切也。从齒介聲。","rad":"齒","fq":"胡介切","vol":"02","py":"xiè","duan":[{"e":"齒相切也。","n":"謂上下齒緊相摩切也。相切則有聲。故三倉云。齘、鳴齒也。函人爲甲。衣之欲其無齘也。大鄭云。齘謂如齒齘。不齘則隨人身便利。方言。齘、怒也。郭曰。言噤齘也。噤亦作䫴。篇、韵皆云。䫴齘、切齒怒。"}]},"齞":{"expl":"口張齒見。从齒只聲。","rad":"齒","fq":"研繭切","vol":"02","py":"yǎn","duan":[{"e":"張口見齒也。","n":"依文選注訂。登徒子好色賦。齞脣歷齒。"}]},"𪙊":{"expl":"齒差也。从齒兼聲。","rad":"齒","fq":"五銜切","vol":"02","py":"yàn","duan":[{"e":"齒差也。","n":"差當作齹。"}]},"齺":{"expl":"齒搚也。一曰齰也。一曰馬口中糜也。从齒芻聲。","rad":"齒","fq":"側鳩切","vol":"02","py":"zōu","duan":[{"e":"齒拹也。","n":"拹今本作搚。手部曰。拹一曰拉也。齒拉者、謂齒折也。"}]},"齵":{"expl":"齒不正也。从齒禺聲。","rad":"齒","fq":"五婁切","vol":"02","py":"óu","duan":[{"e":"齱齵也。从齒。禺聲。","n":"五婁切。四部。按二字各本譌亂。今依廣韵正之。"}]},"䶥":{"expl":"齬齒也。从齒虘聲。","rad":"齒","fq":"側加切","vol":"02","py":"zhā","duan":[{"e":"䶥齬、","n":"逗。曡韵。"}]},"齱":{"expl":"齵也。从齒取聲。","rad":"齒","fq":"側鳩切","vol":"02","py":"zōu","duan":[{"e":"齱齵、","n":"逗。曡韵。"}]},"𪙉":{"expl":"齒參差。从齒差聲。","rad":"齒","fq":"楚宜切","vol":"02","py":"cī","duan":[]},"璏":{"expl":"劍鼻玉也。从玉彘聲。","rad":"玉","fq":"直例切","vol":"01","py":"zhì","duan":[{"e":"劒鼻玉也。","n":"各本篆文皆誤。今正。王莽傳。美玉可以滅瘢。欲獻其璏。服虔曰。璏音衞。蘇林曰。劒鼻玉也。俗本脫玉字。初學記、蓺文類聚引字林。劒鼻謂之璏。亦脫玉字。"}]},"𪘓":{"expl":"齒差跌皃。从齒佐聲。《春秋傳》曰：“鄭有子𪘓。”","rad":"齒","fq":"昨何切","vol":"02","py":"cuó","duan":[{"e":"齒差跌皃。","n":"差者、不値也。跌者踢也。齒差跌、謂參差踼跌不平正也。"}]},"齤":{"expl":"缺齒也。一曰曲齒。从齒𢍏聲。讀若權。","rad":"齒","fq":"巨員切","vol":"02","py":"quán","duan":[{"e":"缺齒也。一曰曲齒。","n":"缺齒者、？也。曲齒者、上云齒差跌。今俗云齒䶕也。按淮南道應訓。若士齤然而𥬇。謂露其齒病而𥬇也。"}]},"齳":{"expl":"無齒也。从齒軍聲。","rad":"齒","fq":"魚吻切","vol":"02","py":"yǔn","duan":[{"e":"無齒也。","n":"韓詩外傳。以爲姣好邪。則大公年七十二。齳然而齒墮矣。"}]},"齾":{"expl":"缺齒也。从齒獻聲。","rad":"齒","fq":"五鎋切","vol":"02","py":"yà","duan":[{"e":"缺齒也。","n":"引伸凡缺皆曰？。左傳曰。兩軍之士皆未慭也。杜曰。憖、缺也。釋文。憖魚覲反。又魚轄反。按憖得有魚轄反者、正因本或作？。陸氏失於不分別言之耳。正義曰。憖者缺之皃。今人猶謂缺爲憖。所據本必作？。故如此云。下文葢有一本作憖之語。亦爲淺人刪之矣。"}]},"䶙":{"expl":"齗腫也。从齒巨聲。","rad":"齒","fq":"區主切","vol":"02","py":"jù","duan":[{"e":"齗腫也。从齒。巨聲。","n":"巨主切。五部。廣韵其呂切。"}]},"齯":{"expl":"老人齒。从齒兒聲。","rad":"齒","fq":"五雞切","vol":"02","py":"ní","duan":[{"e":"老人齒。","n":"魯頌。黃髮兒齒。釋詁曰。黃髮齯齒、壽也。釋名曰。九十或曰齯齒。大齒落盡。更生細者。如小兒齒也。按毛詩作兒。古文。他書作齯。今文也。"}]},"齮":{"expl":"齧也。从齒奇聲。","rad":"齒","fq":"魚綺切","vol":"02","py":"yǐ","duan":[{"e":"齧也。","n":"史、漢田儋傳。齮齕用事者墳墓。如淳曰。齮齕、猶齚齧也。齕、齩也。按凡從奇之字多訓偏。如掎訓偏引、齮訓側齧。索隱注高紀云。許愼以爲側齧。"}]},"𪗨":{"expl":"齚齒也。从齒出聲。","rad":"齒","fq":"仕乙切","vol":"02","py":"zhí","duan":[{"e":"齚齒也。","n":"謂齚物而外露之齒也。故從齒出。"}]},"齰":{"expl":"齧也。从齒㫺聲。","rad":"齒","fq":"側革切","vol":"02","py":"zé","duan":[{"e":"齧也。","n":"漢書灌夫傳。齰舌自殺。鄧通傳。使大子齰癰。"}]},"䶢":{"expl":"齧也。从齒咸聲。","rad":"齒","fq":"工咸切","vol":"02","py":"jiān","duan":[{"e":"齧也。从齒。咸聲。","n":"工咸切。廣韵苦洽切。古音在七部。"}]},"禧":{"expl":"禮吉也。从示喜聲。","rad":"示","fq":"許其切","vol":"01","py":"xī","duan":[{"e":"禮吉也。","n":"行禮獲吉也。釋詁曰。禧、福也。"}]},"瑵":{"expl":"車蓋玉瑵。从玉蚤聲。","rad":"玉","fq":"側絞切","vol":"01","py":"zhǎo","duan":[{"e":"車葢玉瑵。","n":"司馬彪與服志曰。乘輿金根、安車、立車、羽葢華蚤。劉昭注。徐廣云。翠羽葢黃裏。所謂黃屋車也。金華施橑末有二十八枚。卽葢弓也。又張衡東京賦。羽葢威甤。葩瑵曲莖。薛綜注曰。羽葢、以翠羽覆車葢也。威甤、羽貎。葩瑵、悉以金作華形。莖皆低曲。蔡邕獨斷云。凡乘輿車皆羽葢金華爪。爪與瑵同。又王莽傳曰。造華葢九重。高八丈一尺。金瑵。師古曰。瑵讀曰爪。玉裁按。瑵蚤爪三字一也。皆謂葢橑末。說文指爪字作叉。當云車葢玉叉也。瑵叉曡韻。他家云華瑵金瑵者、謂金華飾之。許云玉瑵者、謂玉飾之。故字从玉也。"}]},"齦":{"expl":"齧也。从齒𥃩聲。","rad":"齒","fq":"康很切","vol":"02","py":"kěn","duan":[{"e":"齧也。","n":"此與豕部豤音義同。疑古衹作豤。齦者後出分別之字也。今人又用爲齗字矣。"}]},"𪗙":{"expl":"齒見皃。从齒干聲。","rad":"齒","fq":"五版切","vol":"02","py":"yǎn","duan":[{"e":"齒見皃。","n":"廣韵曰。𪘪𪗙、齒不正。"}]},"𪘧":{"expl":"𪘧，齚也。从齒卒聲。","rad":"齒","fq":"昨沒切","vol":"02","py":"zú","duan":[{"e":"𪘧、","n":"此複舉字之未刪者。"}]},"𪗿":{"expl":"齒分骨聲。从齒𠛱聲。讀若剌。","rad":"齒","fq":"慮達切","vol":"02","py":"là","duan":[{"e":"齒分骨聲。从齒。𠛱聲。","n":"篇、韵皆作䶛。"}]},"齩":{"expl":"齧骨也。从齒交聲。","rad":"齒","fq":"五巧切","vol":"02","py":"yǎo","duan":[{"e":"齧骨也。","n":"俗以鳥鳴之咬爲齩齧。"}]},"𪙑":{"expl":"齒差也。从齒屑聲。讀若切。","rad":"齒","fq":"千結切","vol":"02","py":"qiè","duan":[{"e":"齒差也。","n":"此與𪙊訓齒差義異。謂齒相摩切也。齒與齒相切。必參差上下之。差卽今磋磨字也。引伸之義、摩物曰？。衞風。如切如瑳。如琢如摩。釋器曰。骨謂之切。象謂之瑳。玉謂之琢。石謂之摩。切亦作？。瑳亦作磋。摩亦作磨。差者正字。瑳磋皆加偏旁字也。"}]},"𪗾":{"expl":"齒堅聲。从齒吉聲。","rad":"齒","fq":"赫鎋切","vol":"02","py":"xiá","duan":[{"e":"齧堅聲。","n":"齧各本作齒。今依玉篇訂。石部曰。硈、石堅也。皆於吉聲知之。"}]},"䶣":{"expl":"𪙌牙也。从齒豈聲。","rad":"齒","fq":"五來切","vol":"02","py":"ái","duan":[{"e":"𪙌牙也。","n":"𪙌牙猶差齒也。亦引伸爲摩器之名。刀部曰。剴、一曰摩也。皆於豈聲知之。"}]},"齝":{"expl":"吐而噍也。从齒台聲。《爾雅》曰：“牛曰齝。”","rad":"齒","fq":"丑之切","vol":"02","py":"chī","duan":[{"e":"吐而噍也。","n":"噍卽嚼字也。見口部。釋獸郭注曰。食之已久。復出嚼之。"}]},"齕":{"expl":"齧也。从齒气聲。","rad":"齒","fq":"戶骨切","vol":"02","py":"hé","duan":[{"e":"齧也。","n":"如淳注漢書曰。齕、齩也。曲禮。庶人齕之。"}]},"瑑":{"expl":"圭璧上起兆瑑也。从玉，篆省聲。《周禮》曰：“瑑圭璧。”","rad":"玉","fq":"直戀切","vol":"01","py":"zhuàn","duan":[{"e":"圭璧上起兆瑑也。","n":"周禮先鄭注云。瑑、有圻鄂瑑起也。後鄭云。瑑、文飾也。許云。起兆瑑。與先鄭說合。兆者、垗也。營域之象。先鄭所謂垠堮也。大圭不瑑者。以素爲貴也。"}]},"𪚁":{"expl":"齒見皃。从齒䏈聲。","rad":"齒","fq":"力延切","vol":"02","py":"lián","duan":[{"e":"齒見皃。从齒。聯聲。","n":"力延切。十四部。"}]},"齧":{"expl":"噬也。从齒㓞聲。","rad":"齒","fq":"五結切","vol":"02","py":"niè","duan":[{"e":"噬也。","n":"口部曰。噬、啗也。釋名曰。鳥曰啄。獸曰齧。齧、？也。所臨則秃？也。"}]},"齭":{"expl":"齒傷酢也。从齒所聲。讀若楚。","rad":"齒","fq":"創舉切","vol":"02","py":"chǔ","duan":[{"e":"齒傷酢也。","n":"酢者今之醋字。酸澀也。"}]},"齨":{"expl":"老人齒如臼也。一曰馬八歲齒臼也。从齒从臼，臼亦聲。","rad":"齒","fq":"其久切","vol":"02","py":"jiù","duan":[{"e":"老人齒如臼也。","n":"如臼者、齒坳。"}]},"齬":{"expl":"齒不相值也。从齒吾聲。","rad":"齒","fq":"魚舉切","vol":"02","py":"yǔ","duan":[{"e":"䶥齬也。从齒。吾聲。","n":"魚舉切。五部。"}]},"齛":{"expl":"羊粻也。从齒丗聲。","rad":"齒","fq":"私列切","vol":"02","py":"xiè","duan":[{"e":"羊粻也。","n":"釋獸曰。羊曰齛。郭曰。齛音漏泄。按唐人諱世作齥。粻、米部無此字。食部引歭乃餱粻。"}]},"齸":{"expl":"鹿麋粻。从齒益聲。","rad":"齒","fq":"伊昔切","vol":"02","py":"yì","duan":[{"e":"鹿麋粻。","n":"釋獸曰。麋鹿曰齸。釋文云。字或作嗌。按嗌、咽也。咽、喉也。郭云。䶗食之所在因名之。是也。然則齛與齝同。言其自喉出復嚼。故字从齒。嗌嗉嗛則皆自其藏食之處言之。字衹从口。嗌或作齸者。葢亦謂出嚼之也。"}]},"𪗻":{"expl":"齒堅也。从齒至聲。","rad":"齒","fq":"陟栗切","vol":"02","py":"zhì","duan":[{"e":"齧堅也。","n":"玉篇。齧堅皃。廣韵。齧聲。各本齧作齒。恐誤。"}]},"䶤":{"expl":"齧骨聲。从齒从骨，骨亦聲。","rad":"齒","fq":"戶八切","vol":"02","py":"huá","duan":[{"e":"齧骨聲。","n":"曲禮曰。母齧骨。鄭云。爲有聲響不敬。"}]},"𪗽":{"expl":"噍聲。从齒𠯑聲。","rad":"齒","fq":"古活切","vol":"02","py":"kuò","duan":[{"e":"噍聲。","n":"廣韵曰。骨端。"}]},"珇":{"expl":"琮玉之瑑。从玉且聲。","rad":"玉","fq":"則古切","vol":"01","py":"zǔ","duan":[{"e":"琮玉之瑑。","n":"玉人。駔琮五寸。宗后以爲權。駔琮七寸。天子以爲權。注。駔讀爲組。以組繫之。因名焉。許作珇。葢杜子春讀故書之駔爲珇。鄭所不從。不載其說者也。記又云。瑑琮八寸。則駔琮非謂瑑明矣。似讀駔爲珇、訓琮玉之瑑、失之。方言曰。珇、好也。美也。許意謂兆瑑之美曰珇。"}]},"𪙍":{"expl":"噍堅也。从齒，博省聲。","rad":"齒","fq":"補莫切","vol":"02","py":"bó","duan":[{"e":"噍堅也。","n":"口部㗘、㗱、噍皃。廣韵曰。？同㗘。"}]},"齡":{"expl":"年也。从齒令聲。","rad":"齒","fq":"郎丁切","vol":"02","py":"línɡ","duan":[]},"牙":{"expl":"牡齒也。象上下相錯之形。凡牙之屬皆从牙。","rad":"牙","fq":"五加切","vol":"02","py":"yá","duan":[{"e":"壯齒也。","n":"壯各本譌作牡。今本篇、韵皆譌。惟石刻九經字㨾不誤。而馬氏版本妄改之。士部曰。壯、大也。壯齒者、齒之大者也。統言之皆偁齒、偁牙。析言之則前當脣者偁齒。後在輔車者偁牙。牙較大於齒。非有牝牡也。釋名。牙樝牙也。隨形言之也。輔車或曰牙車。牙所載也。詩誰謂雀無角、誰謂鼠無牙。謂雀本無角、鼠本無牙。而穿屋穿牆似有角牙者然。鼠齒不大。故謂無牙也。東方朔說騶牙曰。其齒前後若一。齊等無牙。此爲齒小牙大之明證。"}]},"𤘌":{"expl":"武牙也。从牙从奇，奇亦聲。","rad":"牙","fq":"去奇切","vol":"02","py":"qī","duan":[{"e":"虎牙也。","n":"虎一本作武。避唐諱耳。今俗謂門齒外出爲虎牙。古語也。大招云。靨輔奇牙。宜𥬇嫣只。淮南云。奇牙出。䩉搖。高注。將𥬇故好齒出也。按奇牙所謂？也。可部曰。奇、異也。一曰不耦𥬇而露其齒獨好。故曰奇牙。"}]},"𤘐":{"expl":"齒蠧也。从牙禹聲。","rad":"牙","fq":"區禹切","vol":"02","py":"qǔ","duan":[{"e":"齒蠧也。","n":"釋名曰。𤘐、朽也。蟲齧之缺朽也。史記。齊中大夫病齲齒。淮南。斲木愈齲。司馬彪五行志。桓帝元嘉中。京都婦女作齲齒𥬇。"}]},"足":{"expl":"人之足也。在下。从止、口。凡足之屬皆从足。","rad":"足","fq":"即玉切","vol":"02","py":"zú","duan":[{"e":"人之足也。在體下。从口止。","n":"依玉篇訂。口猶人也。舉口以包足已上者也。齒、上止下口。次之以足、上口下止。次之以疋、似足者也。次之以品、从三口。今各本从口。非也。卽玉切。三部。"}]},"蹏":{"expl":"足也。从足虒聲。","rad":"足","fq":"杜兮切","vol":"02","py":"tí","duan":[{"e":"足也。","n":"俗作蹄。"}]},"跟":{"expl":"足踵也。从足𥃩聲。","rad":"足","fq":"古痕切","vol":"02","py":"ɡēn","duan":[{"e":"足歱也。","n":"歱各本作踵。誤。止部曰。歱、跟也。釋名曰。足後曰跟。一體任之。象本根也。"}]},"踝":{"expl":"足踝也。从足果聲。","rad":"足","fq":"胡瓦切","vol":"02","py":"huái","duan":[{"e":"足踝也。","n":"釋名曰。踝、确也。居足兩旁磽确然也。按踝者、人足左右骨隆然圜者也。在外者謂之外踝。在內謂之內踝。丮部曰。？、擊踝也。"}]},"跖":{"expl":"足下也。从足石聲。","rad":"足","fq":"之石切","vol":"02","py":"zhí","duan":[{"e":"足下也。","n":"今所謂腳掌也。史記曰。跖勁弩按弩以足蹋張之。故曰跖。跖或借蹠爲之。又作𨂂。賈誼傳曰。病非徒瘇也。又苦𨂂盭。𨂂、跖字之異者也。足跖、反戾不可行。"}]},"𤪌":{"expl":"弁飾，往往冒玉也。从玉綦聲。","rad":"玉","fq":"渠之切","vol":"01","py":"qí","duan":[{"e":"弁飾也。往往冒玉也。","n":"上也字依詩音義補。弁師曰。王之皮弁會五采玉琪。鄭司農云。故書會作䯤。䯤讀如馬會之會。謂以五采束髮也。琪讀如綦車轂之綦。按許謂以玉飾弁曰琪。與司農說同。後鄭則易琪爲綦。綦、結也。皮弁之縫中每貫結五采玉以爲飾、謂之綦。葢後鄭謂經琪字乃玉名。故易爲綦字。曹風。其弁伊騏。箋亦云騏當作綦。自用其周禮說也。許同先鄭說。往往、歴歴也。鄭云皪皪而處是也。"}]},"踦":{"expl":"一足也。从足奇聲。","rad":"足","fq":"去奇切","vol":"02","py":"qī","duan":[{"e":"一足也。","n":"管子。俈堯之時。一踦腓。一踦屨。而當死。謂一足剕、一足屨當死罪也。引伸之凡物單曰踦。方言。倚踦奇也。自關而西凡全物而體不具謂之倚。梁楚之閒謂之踦。雍梁之西郊凡嘼支體不具者謂之踦。公羊傳。匹馬隻輪無反者。何曰。匹馬、一馬也。隻、踦也。又相與踦閭而語。何云。閉一扇、開一扇。一人在內、一人在外。戰國策。必有踦重者矣。踦重、偏重也。若衣部曰。襱、絝踦也。毛傳曰蟰蛸、長踦也。則皆謂足。不必一足。"}]},"跪":{"expl":"拜也。从足危聲。","rad":"足","fq":"去委切","vol":"02","py":"ɡuì","duan":[{"e":"拜也。","n":"手部曰。？、首至手也。按跪與拜二事。不當一之。疑當云所以拜也。後人不達此書所以字。往往刪之。釋名。跪、危也。兩膝隱地。體危隉也。"}]},"跽":{"expl":"長跪也。从足忌聲。","rad":"足","fq":"渠几切","vol":"02","py":"jì","duan":[{"e":"長跽也。","n":"長跽各本作長跪。今正。按係於拜曰跪。不係於拜曰跽。范睢傳四言秦王跽、而後乃云秦王再拜是也。長跽乃古語。長俗作䠆。人安坐則形弛。敬則小跪聳體若加長焉。故曰長跽。方言。東齊海岱北燕之郊跪謂之䠆𨂣。郭曰。今東郡人亦呼長跽爲䠆𨂣。釋名。跽、忌也。見所敬忌不敢自安也。徐廣注滑稽傳鞠𦜕曰。𦜕其紀反。與跽同。謂小跪也。廣雅。䠆𨂣、跪拜也。此統言之。許跪跽析言之。"}]},"踧":{"expl":"行平易也。从足叔聲。《詩》曰：“踧踧周道。”","rad":"足","fq":"子六切","vol":"02","py":"dí","duan":[{"e":"行平易也。","n":"小雅毛傳曰。踧踧、平易也。"}]},"躣":{"expl":"行皃。从足瞿聲。","rad":"足","fq":"其俱切","vol":"02","py":"qú","duan":[{"e":"行皃。","n":"九辯。右蒼龍之躣躣。"}]},"踖":{"expl":"長脛行也。从足㫺聲。一曰踧踖。","rad":"足","fq":"資昔切","vol":"02","py":"jí","duan":[{"e":"長脛行也。","n":"小雅。執爨踖踖。毛曰。踖踖、言爨竈有容也。"}]},"踽":{"expl":"䟽行皃。从足禹聲。《詩》曰：“獨行踽踽。”","rad":"足","fq":"區主切","vol":"02","py":"jǔ","duan":[{"e":"疏行皃。","n":"唐風。獨行踽踽。毛曰。踽踽、無所親也。按許合經傳云爾。疏、通也。引伸爲親疏。孟子。行何爲踽踽涼涼。義同。"}]},"𨄚":{"expl":"行皃。从足將聲。《詩》曰：“管磬蹡蹡。”","rad":"足","fq":"七羊切","vol":"02","py":"qiānɡ","duan":[{"e":"行皃。","n":"聘禮。衆介北面蹌焉。鄭云。容皃舒揚。曲禮。天子穆穆。諸侯皇皇。大夫濟濟。士蹌蹌。鄭曰。皆行容止之皃也。按許𨄚爲行皃。蹌訓動也。然則禮言行容者皆𨄚爲正字、蹌爲叚借字。廣雅。蹡蹡、走也。"}]},"䠪":{"expl":"踐處也。从足，斷省聲。","rad":"足","fq":"徒管切","vol":"02","py":"duàn","duan":[{"e":"踐處也。","n":"此與疃同義。田部曰。疃、禽獸所踐處也。王逸九思。鹿蹊兮䠪䠪。亦作𨇰。按衹云踐處。別於疃字。專屬禽獸。"}]},"䟔":{"expl":"趣越皃。从足卜聲。","rad":"足","fq":"芳遇切","vol":"02","py":"fù","duan":[{"e":"趣越皃。","n":"趣、疾也。小徐作趨。䟔與赴音義略同。"}]},"璪":{"expl":"玉飾。如水藻之文。从玉喿聲。《虞書》曰：“璪火黺米。”","rad":"玉","fq":"子皓切","vol":"01","py":"zǎo","duan":[{"e":"玉飾。如水藻之文。","n":"謂彫飾玉之文。璪藻曡韻。"}]},"踰":{"expl":"越也。从足俞聲。","rad":"足","fq":"羊朱切","vol":"02","py":"yú","duan":[{"e":"越也。","n":"越、度也。踰與逾音義略同。"}]},"䟠":{"expl":"輕也。从足戉聲。","rad":"足","fq":"王伐切","vol":"02","py":"yuè","duan":[{"e":"輕也。","n":"廣韵。？、輕也。字从女。"}]},"蹻":{"expl":"舉足行高也。从足喬聲。《詩》曰：“小子蹻蹻。”","rad":"足","fq":"居勺切","vol":"02","py":"qiāo","duan":[{"e":"舉足小高也。","n":"蹻高曡韵。各本作行高。晉灼注漢書高帝妃作小高。玄應引文穎曰。蹻猶翹也。又引三蒼解詁云。蹻、舉足也。丘消切。按今俗語猶然。"}]},"跾":{"expl":"疾也。長也。从足攸聲。","rad":"足","fq":"式竹切","vol":"02","py":"shū","duan":[{"e":"疾也。長也。","n":"二義相反而相成。易。其欲逐逐。？云。速也。子夏傳作攸攸。荀作悠悠。劉作跾、云遠也。按方言透、驚也。式竹切。吳都賦。驚透沸亂。透卽跾字。音義正同。今人以爲透漏字。他𠋫切。"}]},"蹌":{"expl":"動也。从足倉聲。","rad":"足","fq":"七羊切","vol":"02","py":"qiānɡ","duan":[{"e":"動也。从足。倉聲。","n":"七羊切。十部。"}]},"踊":{"expl":"跳也。从足甬聲。","rad":"足","fq":"余隴切","vol":"02","py":"yǒnɡ","duan":[{"e":"跳也。","n":"與走部？別。"}]},"躋":{"expl":"登也。从足齊聲。《商書》曰：“予顚躋。”","rad":"足","fq":"祖雞切","vol":"02","py":"jī","duan":[{"e":"登也。从足。齊聲。","n":"祖雞切。十五部。"}]},"躍":{"expl":"迅也。从足翟聲。","rad":"足","fq":"以灼切","vol":"02","py":"yuè","duan":[{"e":"迅也。","n":"迅、疾也。"}]},"跧":{"expl":"蹴也。一曰卑也，絭也。从足全聲。","rad":"足","fq":"莊緣切","vol":"02","py":"zhuān","duan":[{"e":"蹴也。","n":"蹴、躡也。"}]},"蹴":{"expl":"躡也。从足就聲。","rad":"足","fq":"七宿切","vol":"02","py":"cù","duan":[{"e":"躡也。","n":"玄應云。說文。蹴、蹋也。以足逆蹋之曰蹴。"}]},"瑬":{"expl":"垂玉也。冕飾。从玉流聲。","rad":"玉","fq":"力求切","vol":"01","py":"liú","duan":[{"e":"𠂹玉也。冕飾。","n":"弁師。掌王之五冕。五采繅十有二就。皆五采玉十有二。諸矦之繅斿九就。珉玉三采。繅斿皆就。注。繅、雜文之名。合五采絲爲之繩。垂於延之前後。就、成也。繩之每一帀而貫五采玉。十二斿則十二玉也。繅不言皆。有不皆者。衮衣之冕十二斿。則用玉二百八十八。鷩衣之冕繅九斿。用玉二百一十六。毳衣之冕七斿。用玉百六十八。希衣之冕五斿。用玉百二十。玄衣之冕三斿。用玉七十二。矦當爲公。字之誤也。三采、朱白蒼也。繅斿皆就、皆三采也。每繅九成、則九玉也。公之冕用玉百六十二。按弁師作斿。玉藻从俗字作旒。皆瑬之假借字。"}]},"躡":{"expl":"蹈也。从足聶聲。","rad":"足","fq":"尼輒切","vol":"02","py":"niè","duan":[{"e":"蹈也。","n":"史記。張良、陳平躡漢王足是也。耤田賦注引說文。躡、追也。不同"}]},"跨":{"expl":"渡也。从足夸聲。","rad":"足","fq":"苦化切","vol":"02","py":"kuà","duan":[{"e":"渡也。","n":"謂大其兩股閒以有所越也。因之兩股閒謂之跨下。史記淮陰矦傳作胯下。夊部曰。？、跨步也。苦瓦切。"}]},"蹋":{"expl":"踐也。从足𦐇聲。","rad":"足","fq":"徒盍切","vol":"02","py":"tà","duan":[{"e":"踐也。从足。𦐇聲。","n":"徒盍切。八部。俗作踏。"}]},"踄":{"expl":"蹈也。从足步聲。","rad":"足","fq":"旁各切","vol":"02","py":"bó","duan":[{"e":"蹈也。从足。步聲。","n":"旁各切。又音步。五部。"}]},"蹈":{"expl":"踐也。从足舀聲。","rad":"足","fq":"徒到切","vol":"02","py":"dǎo","duan":[{"e":"踐也。","n":"釋名。蹈、道也。以足踐之如道。"}]},"躔":{"expl":"踐也。从足廛聲。","rad":"足","fq":"直連切","vol":"02","py":"chán","duan":[{"e":"踐也。","n":"方言。躔、歷行也。日運爲躔。"}]},"踐":{"expl":"履也。从足戔聲。","rad":"足","fq":"慈衍切","vol":"02","py":"jiàn","duan":[{"e":"履也。","n":"履之箸地曰履。履、足所依也。"}]},"踵":{"expl":"追也。从足重聲。一曰往來皃。","rad":"足","fq":"之隴切","vol":"02","py":"zhǒnɡ","duan":[{"e":"追也。","n":"與止部歱別。"}]},"踔":{"expl":"踶也。从足㔬聲。","rad":"足","fq":"知教切","vol":"02","py":"zhào","duan":[{"e":"踶也。","n":"許意踔與蹈義同。"}]},"蹛":{"expl":"踶也。从足帶聲。","rad":"足","fq":"當蓋切","vol":"02","py":"dài","duan":[{"e":"踶也。","n":"玄應曰。䠠三蒼音帝。郭訓古文奇字。以爲古文逝字。漢書韋昭音徒計切。按蹛卽䠠字。漢書䠠惲作䠠、蹛林作蹛。"}]},"璹":{"expl":"玉器也。从玉𠷎聲。讀若淑。","rad":"玉","fq":"殊六切","vol":"01","py":"shú","duan":[{"e":"玉器也。","n":"徐鍇曰。爾雅。璋大八寸謂之琡。說文有𤩈無琡。宜同也。"}]},"蹩":{"expl":"踶也。从足敝聲。一曰跛也。","rad":"足","fq":"蒲結切","vol":"02","py":"bié","duan":[{"e":"踶也。","n":"集韵作䠥。云反足踶也。匹蔑切。莊子。蹩躠爲仁。亦作弊薛。"}]},"踶":{"expl":"躛也。从足是聲。","rad":"足","fq":"特計切","vol":"02","py":"dì","duan":[{"e":"躛也。","n":"李軌曰。踶、蹋也。通俗文曰。小蹋謂之踶。"}]},"躛":{"expl":"衞也。从足衞聲。","rad":"足","fq":"于歲切","vol":"02","py":"wèi","duan":[{"e":"衞也。","n":"按此必有脫誤。當云躛踶也。牛部？下云。牛踶？也。然則躛？義略同。"}]},"䠟":{"expl":"䠟足也。从足執聲。","rad":"足","fq":"徒叶切","vol":"02","py":"dié","duan":[{"e":"䠟足也。","n":"案此三字一句。䠟卽蹀字也。叚借作啑作喋。文帝紀。新喋血京師。服䖍曰。喋音蹀屣履之蹀。如淳曰。殺人流血滂沱爲喋血。司馬貞引廣雅。喋、履也。然則喋血者、䠟血也。謂流血滿地汚足下也。"}]},"䟗":{"expl":"尌也。从足氏聲。","rad":"足","fq":"承旨切","vol":"02","py":"shì","duan":[{"e":"尌也。","n":"與歭偫雙聲。義略同。"}]},"蹢":{"expl":"住足也。从足，適省聲。或曰蹢躅。賈侍中說：足垢也。","rad":"足","fq":"直隻切","vol":"02","py":"zhí","duan":[{"e":"蹢躅、","n":"各本奪此二字。文選注四引皆有。"}]},"躅":{"expl":"蹢躅也。从足蜀聲。","rad":"足","fq":"直録切","vol":"02","py":"zhú","duan":[{"e":"蹢躅也。","n":"蹢躅雙聲。"}]},"踤":{"expl":"觸也。从足卒聲。一曰駭也。一曰蒼踤。","rad":"足","fq":"昨沒切","vol":"02","py":"zú","duan":[{"e":"觸也。","n":"長楊賦。帥軍踤阹。漢書音義曰。踤、聚也。師古曰。踤、足蹴也。"}]},"蹶":{"expl":"僵也。从足厥聲。一曰跳也。亦讀若橜。","rad":"足","fq":"居月切","vol":"02","py":"jué","duan":[{"e":"僵也。","n":"僵、僨也。方言。跌、蹷也。左傳。是謂蹷其本。"}]},"跳":{"expl":"蹶也。从足兆聲。一曰躍也。","rad":"足","fq":"徒遼切","vol":"02","py":"tiào","duan":[{"e":"蹷也。","n":"方言。自關而西秦晉之閒曰跳。"}]},"瓃":{"expl":"玉器也。从玉畾聲。","rad":"玉","fq":"魯回切","vol":"01","py":"léi","duan":[{"e":"玉器也。","n":"雋不疑傳。帶櫑具劒。晉灼曰。古長劒首以玉作井鹿盧形。上刻木作山形。如蓮花初生未敷時。霍淸治書云。攷古圖有玉轆轤玉具劒。古樂府所云腰閒轆轤劒也。按古玉器爲鹿盧轉旋。葢不獨劒具。先鄭注周禮云。駔外有捷盧也。捷盧亦謂鹿盧也。"}]},"䟴":{"expl":"動也。从足辰聲。","rad":"足","fq":"側鄰切","vol":"02","py":"zhèn","duan":[{"e":"動也。","n":"與口部唇、雨部震、手部振音義略同。"}]},"䠧":{"expl":"歭䠧，不前也。从足屠聲。","rad":"足","fq":"直魚切","vol":"02","py":"chú","duan":[{"e":"歭䠧、","n":"逗。"}]},"𧿳":{"expl":"跳也。从足弗聲。","rad":"足","fq":"敷勿切","vol":"02","py":"fú","duan":[{"e":"跳也。","n":"方言。𨃚䠛𧿳跳也。"}]},"蹠":{"expl":"楚人謂跳躍曰蹠。从足庶聲。","rad":"足","fq":"之石切","vol":"02","py":"zhí","duan":[{"e":"楚人謂跳躍曰蹠。","n":"見方言。"}]},"𨃚":{"expl":"趿也。从足荅聲。","rad":"足","fq":"他合切","vol":"02","py":"tà","duan":[{"e":"趿也。","n":"按趿當作跳。方言。𨃚、跳也。自關而西秦晉之閒曰跳。或曰𨃚。"}]},"䠛":{"expl":"跳也。从足䍃聲。","rad":"足","fq":"余招切","vol":"02","py":"yáo","duan":[{"e":"跳也。","n":"方言。䠛、跳也。陳鄭之閒曰䠛。"}]},"趿":{"expl":"進足有所擷取也。从足及聲。《爾雅》曰：“趿謂之擷。”","rad":"足","fq":"稣合切","vol":"02","py":"sà","duan":[{"e":"進足有所擷取也。","n":"爾雅、毛傳皆云。執袵曰袺。扱衽曰襭。衣部云。以衣衽扱物謂之襭。襭或作擷。"}]},"䟺":{"expl":"步行獵跋也。从足貝聲。","rad":"足","fq":"博蓋切","vol":"02","py":"bèi","duan":[{"e":"步行獵跋也。","n":"獵今之躐字。踐也。毛傳曰。跋、躐也。老狼進則躐其胡。獵跋猶踐踏也。"}]},"躓":{"expl":"跲也。从足質聲。《詩》曰：“載躓其尾。”","rad":"足","fq":"陟利切","vol":"02","py":"zhì","duan":[{"e":"跲也。","n":"釋言、毛傳皆曰。疐、跲也。疐者躓之叚借字。"}]},"跲":{"expl":"躓也。从足合聲。","rad":"足","fq":"居怯切","vol":"02","py":"jiá","duan":[{"e":"躓也。","n":"中庸。言前定、則不跲。"}]},"瑳":{"expl":"玉色鮮白。从玉差聲。","rad":"玉","fq":"七何切","vol":"01","py":"cuō","duan":[]},"跇":{"expl":"述也。从足丗聲。","rad":"足","fq":"丑例切","vol":"02","py":"yì","duan":[{"e":"述也。","n":"述當作𨒋。字之誤也。樂書。騁容與兮跇萬里。裴引如淳曰。？謂超逾也。吳都賦說田獵曰。？踰竹柏。？猭杞柟。"}]},"蹎":{"expl":"跋也。从足眞聲。","rad":"足","fq":"都年切","vol":"02","py":"diān","duan":[{"e":"跋也。","n":"經傳多叚借顚字爲之。如左傳子都自下射之顚是也。貢禹傳。誠恐一旦蹎仆氣竭。"}]},"跋":{"expl":"蹎跋也。从足犮聲。","rad":"足","fq":"北末切","vol":"02","py":"bá","duan":[{"e":"蹎也。","n":"依豳風正義訂。跋、經傳多叚借沛字爲之。大雅、論語顚沛皆卽蹎跋也。毛傳。顚、仆也。沛、拔也。拔同跋。豳風狼跋亦或作拔。馬融論語注曰。顚沛、僵仆也。按豳風狼跋其胡謂？也。？則仆矣。引伸爲近人題跋字。題者標其前。跋者系其後也。邶風傳。艸行曰跋。別一義。"}]},"蹐":{"expl":"小步也。从足𦟝聲。《詩》曰：“不敢不蹐。”","rad":"足","fq":"資昔切","vol":"02","py":"jí","duan":[{"e":"小步也。","n":"毛傳。蹐、絫足也。按絫蹐曡韵。絫足者、小步之至也。"}]},"跌":{"expl":"踼也。从足失聲。一曰越也。","rad":"足","fq":"徒結切","vol":"02","py":"diē","duan":[{"e":"踼也。从足。失聲。","n":"徒結切。十二部。"}]},"踼":{"expl":"跌踼也。从足昜聲。一曰搶也。","rad":"足","fq":"徒郎切","vol":"02","py":"tánɡ","duan":[{"e":"跌也。","n":"今本作跌踼也。恐是誤倒。吳都賦。䰟褫氣懾而自踼䟮者。劉曰。踼䟮、頓伏也。李引聲類。踼、跌也。漢書音義。䟮、崩也。"}]},"蹲":{"expl":"踞也。从足尊聲。","rad":"足","fq":"徂尊切","vol":"02","py":"dūn","duan":[{"e":"居也。","n":"尸部曰。居、蹲也。是爲轉注。各本作踞也。以俗改正。又增一踞篆於蹲後。今正而刪之。左傳。蹲甲而射之。蹲、居也。引伸爲居積之義。"}]},"踞":{"expl":"蹲也。从足居聲。","rad":"足","fq":"居御切","vol":"02","py":"jù","duan":[]},"𨃖":{"expl":"踞也。从足荂聲。","rad":"足","fq":"苦化切","vol":"02","py":"kuà","duan":[{"e":"居也。从足。荂聲。","n":"苦化切。按此恐又跨字之異體。"}]},"躩":{"expl":"足躩如也。从足矍聲。","rad":"足","fq":"丘縛切","vol":"02","py":"jué","duan":[{"e":"足躩如也。","n":"論語苞氏曰。躩、盤辟皃也。"}]},"玼":{"expl":"玉色鮮也。从玉此聲。《詩》曰：“新臺有玼。”","rad":"玉","fq":"千禮切","vol":"01","py":"cǐ","duan":[{"e":"新玉色鮮也。","n":"各本無新。詩音義兩引皆作新色鮮也。今補。玼本新玉色。引伸爲凡新色。如詩玼兮玼兮。言衣之鮮盛。新臺有玼。言臺之鮮明。韻會引作玉色鮮絜也。"}]},"踣":{"expl":"僵也。从足咅聲。《春秋傳》曰：“晉人踣之。”","rad":"足","fq":"蒲北切","vol":"02","py":"bó","duan":[{"e":"僵也。","n":"僵、卻偃也。"}]},"跛":{"expl":"行不正也。从足皮聲。一曰足排之。讀若彼。","rad":"足","fq":"布火切","vol":"02","py":"bǒ","duan":[]},"蹇":{"expl":"跛也。从足，寒省聲。","rad":"足","fq":"九輦切","vol":"02","py":"jiǎn","duan":[{"e":"𤿑也。","n":"尣部曰。𤿑、蹇也。是爲轉注。𤿑、曲脛也。易曰。蹇、難也。行難謂之蹇。言難亦謂之蹇。俗作謇。非。"}]},"蹁":{"expl":"足不正也。从足扁聲。一曰拖後足馬。讀若苹。或曰徧。","rad":"足","fq":"部田切","vol":"02","py":"pián","duan":[{"e":"足不正也。","n":"南都賦說舞曰。䠥𨇨蹁躚。卽上林賦之便跚蹩㞕也。"}]},"䟸":{"expl":"脛肉也。一曰曲脛也。从足𢌳聲。讀若逵。","rad":"足","fq":"渠追切","vol":"02","py":"kuí","duan":[{"e":"脛肉也。从足。𢌳聲。一曰曲脛也。","n":"廣韵作左脛曲。"}]},"踒":{"expl":"足跌也。从足委聲。","rad":"足","fq":"烏過切","vol":"02","py":"wō","duan":[{"e":"足跌也。","n":"跌當爲肤。字之誤也。肉部曰。胅、骨差也。踒者、骨委屈失其常。故曰胅。亦曰差跌。"}]},"跣":{"expl":"足親地也。从足先聲。","rad":"足","fq":"穌典切","vol":"02","py":"xiǎn","duan":[{"e":"足親地也。","n":"親跣曡韵。古者坐必脫屨。燕坐必褫韤。皆謂之跣。如趙盾侍君燕。跣以下。此褫韤之跣也。如晉悼公跣而出。此不暇屨之跣也。喪大記。主人徒跣。亦謂褫韤。"}]},"跔":{"expl":"天寒足跔也。从足句聲。","rad":"足","fq":"其俱切","vol":"02","py":"jū","duan":[{"e":"天寒足跔也。","n":"周書大子晉解。師曠東。躅其足。曰善哉善哉。大子曰。大師何舉足驟。師曠曰。天寒足跔。是以數也。此許所本。莊子音義亦引周書天寒足跔。今本周書作足躅。誤也。跔者、句曲不伸之意。"}]},"䠅":{"expl":"瘃足也。从足囷聲。","rad":"足","fq":"苦本切","vol":"02","py":"kǔn","duan":[{"e":"瘃足也。","n":"疒部曰。瘃、中寒腫覈也。據趙充國傳。手足皆有皸瘃之患。此字從足。故訓爲瘃足。"}]},"距":{"expl":"雞距也。从足巨聲。","rad":"足","fq":"其呂切","vol":"02","py":"jù","duan":[{"e":"雞距也。","n":"左傳。季氏介其雞。郈氏爲之金距。服曰。以金沓距也。按鳥距如人與獸之叉。此距與止部之歫異義。他家多以距爲歫。"}]},"禛":{"expl":"以眞受福也。从示眞聲。","rad":"示","fq":"側鄰切","vol":"01","py":"zhēn","duan":[{"e":"㠯眞受福也。从示。眞聲。","n":"此亦當云从示、从眞、眞亦聲。不言者省也。聲與義同原。故龤聲之偏㫄多與字義相近。此㑹意、形聲㒳兼之字致多也。說文或偁其㑹意、略其形聲。或偁其形聲、略其㑹意。雖則渻文。實欲互見。不知此則聲與義隔。又或如宋人字說。衹有㑹意。別無形聲。其失均誣矣。側鄰切。十二部。"}]},"璱":{"expl":"玉英華相帶如瑟弦。从玉瑟聲。《詩》曰：“瑟彼玉瓚。”","rad":"玉","fq":"所櫛切","vol":"01","py":"sè","duan":[{"e":"玉英華相帶如瑟弦也。","n":"左思吳都賦。符采彪炳。劉逵注曰。符采、玉之橫文也。郭璞引王子靈符應曰。赤如雞冠。黃如蒸栗。白如割肪。黑如純漆。玉之符采也。璱瑟曡韻。"}]},"躧":{"expl":"舞履也。从足麗聲。","rad":"足","fq":"所綺切","vol":"02","py":"xǐ","duan":[{"e":"舞履也。","n":"鄭注周禮曰。鞮屨、四夷舞者屝也。史記貨殖傳。躡利屣。徐廣曰。舞屣也。躡一作跕。跕吐協反。地理志。跕躧。臣瓚曰。躡跟爲跕。按舞不納履。故凡不著跟、曳之而行曰躧履。如雋不疑傳、長門賦皆是也。西京賦說舞曰。振朱屣於盤樽。薛曰。朱屣、赤絲履也。"}]},"䠍":{"expl":"足所履也。从足叚聲。","rad":"足","fq":"乎加切","vol":"02","py":"xiā","duan":[{"e":"足所履也。从足。叚聲。","n":"乎加切。凡叚聲古在五部。按䠍疑？之誤。篇、韵有踹字。丁貫切。今俗謂語用力踏地曰踹。？音同也。許書碫字譌碬。？？錯出、是其比矣。"}]},"䠊":{"expl":"跀也。从足非聲。讀若匪。","rad":"足","fq":"扶味切","vol":"02","py":"fèi","duan":[{"e":"跀也。","n":"字亦作剕。"}]},"跀":{"expl":"斷足也。从足月聲。","rad":"足","fq":"魚厥切","vol":"02","py":"yuè","duan":[{"e":"𣃔足也。","n":"此與刀部刖異義。刖、絕也。經傳多以刖爲跀。周禮司㓝注云。周改臏作刖。按唐虞夏㓝用髕。去其厀頭骨也。周用跀。𣃔足也。凡於周言臏者。舉本名也。莊子。魯有兀者叔山無趾。踵見仲尼。崔譔云。無趾故踵行。然則跀㓝卽漢之斬趾。無足指、故以足跟行也。無足指不能行。故別爲刖足者之屨以助其行。左氏云踊貴屨賤是也。髕則足廢不能行。跀則用踊尙可行。故跀輕於髕也。跀一名䠊。䠊一作剕。鄭駁異義云。皋陶改臏爲剕。呂㓝有剕。周改剕爲刖。此恐誤。與司㓝注不合。"}]},"趽":{"expl":"曲脛馬也。从足方聲。讀與彭同。","rad":"足","fq":"薄庚切","vol":"02","py":"fànɡ","duan":[{"e":"曲脛馬也。","n":"廣雅曰。趽䟸？也。䟸見上。？俱達切。"}]},"趹":{"expl":"馬行皃。从足，決省聲。","rad":"足","fq":"古穴切","vol":"02","py":"jué","duan":[{"e":"馬行皃。","n":"戰國策、史記云。秦馬之良。探前趹後。蹄閒三㝷。西都賦。要趹追蹤。廣雅。趹、奔也。"}]},"趼":{"expl":"獸足企也。从足幵聲。","rad":"足","fq":"五甸切","vol":"02","py":"yàn","duan":[{"e":"獸足企也。","n":"釋嘼。騉蹏硏、善陞甗。又騉駼、枝蹏硏、善陞甗。硏者謂其足企。企、舉歱也。故善登高。硏本或作硏。硏、滑石也。舍人、李巡、孫炎、郭樸、顏師古皆以蹄下平正如硏釋之。"}]},"路":{"expl":"道也。从足从各。","rad":"足","fq":"洛故切","vol":"02","py":"lù","duan":[{"e":"道也。","n":"釋宮。一達謂之道路。此統言也。周禮。澮上有道。川上有路。此析言也。爾雅、毛傳。路、大也。此引伸之義也。"}]},"蹸":{"expl":"轢也。从足㷠聲。","rad":"足","fq":"良忍切","vol":"02","py":"lìn","duan":[{"e":"轢也。","n":"車部曰。轢、車所踐也。"}]},"跂":{"expl":"足多指也。从足支聲。","rad":"足","fq":"巨支切","vol":"02","py":"qí","duan":[{"e":"足多指也。从足。支聲。","n":"巨支切。十六部。按足部當終於路。蹸字跂字不當廁此。莊子。駢拇枝指。字只作枝。跂葢俗體。"}]},"瑮":{"expl":"玉英華羅列秩秩。从玉㮚聲。《逸論語》曰：“玉粲之璱兮。其𤩰猛也。”","rad":"玉","fq":"力質切","vol":"01","py":"lì","duan":[{"e":"玉英華羅列秩秩。","n":"爾雅釋訓。秩秩、淸也。毛傳。秩秩、有常也。瑮列雙聲。瑮秩曡韻。"}]},"蹮":{"expl":"蹁蹮，旋行。从足䙴聲。","rad":"足","fq":"穌前切","vol":"02","py":"xiān","duan":[]},"蹭":{"expl":"蹭蹬，失道也。从足曾聲。","rad":"足","fq":"七鄧切","vol":"02","py":"cènɡ","duan":[]},"蹬":{"expl":"蹭蹬也。从足登聲。","rad":"足","fq":"徒亘切","vol":"02","py":"dènɡ","duan":[]},"蹉":{"expl":"蹉跎，失時也。从足差聲。","rad":"足","fq":"七何切","vol":"02","py":"cuō","duan":[]},"跎":{"expl":"蹉跎也。从足它聲。","rad":"足","fq":"徒何切","vol":"02","py":"tuó","duan":[]},"蹙":{"expl":"迫也。从足戚聲。臣鉉等案：李善《文選注》通蹴字。","rad":"足","fq":"子六切","vol":"02","py":"cù","duan":[]},"踸":{"expl":"踸踔，行無常皃。从足甚聲。","rad":"足","fq":"丑甚切","vol":"02","py":"chěn","duan":[]},"疋":{"expl":"足也。上象腓腸，下从止。《弟子職》曰：“問疋何止。”古文以爲《詩·大疋》字。亦以爲足字。或曰胥字。一曰疋，記也。凡疋之屬皆从疋。","rad":"疋","fq":"所菹切","vol":"02","py":"shū","duan":[{"e":"足也。上象腓腸。","n":"肉部曰。腨、腓腸也。"}]},"𤴙":{"expl":"門戶疏䆫也。从疋，疋亦聲。囪象𤴙形。讀若疏。","rad":"疋","fq":"所菹切","vol":"02","py":"shū","duan":[{"e":"門戸靑疏䆫也。","n":"靑字依篇、韵補。於門戸刻鏤爲䆫牖之形。而以靑飾之也。？部曰。疏、通也。薛注西京賦曰。疏、刻穿之也。招䰟。網戸朱綴。刻方連些。古詩曰。交疏結綺䆫。"}]},"𤕟":{"expl":"通也。从爻从疋，疋亦聲。","rad":"疋","fq":"所菹切","vol":"02","py":"shū","duan":[{"e":"通也。","n":"此與？部疏音義皆同。玉篇引月令。其器？以達。今月令作疏。諸書枎疏字。太玄作枎？。太玄又有？首。轉寫譌作𤕠。"}]},"瑩":{"expl":"玉色。从玉，熒省聲。一曰石之次玉者。《逸論語》曰：“如玉之瑩。”","rad":"玉","fq":"烏定切","vol":"01","py":"yínɡ","duan":[{"e":"玉色也。","n":"謂玉光明之皃。引伸爲磨。瑩亦作鎣。"}]},"品":{"expl":"眾庶也。从三口。凡品之屬皆从品。","rad":"品","fq":"丕飲切","vol":"02","py":"pǐn","duan":[{"e":"衆庶也。从三口。","n":"人三爲眾。故從三口。會意。丕飮切。七部。"}]},"喦":{"expl":"多言也。从品相連。《春秋傳》曰：“次于喦北。”讀與聶同。","rad":"品","fq":"尼輒切","vol":"02","py":"niè","duan":[{"e":"多言也。","n":"此與言部讘音義皆同。"}]},"喿":{"expl":"鳥羣鳴也。从品在木上。","rad":"品","fq":"穌到切","vol":"02","py":"zào","duan":[{"e":"鳥羣鳴也。","n":"此與雧同意。俗作噪。方言假喿爲鍬臿字。"}]},"龠":{"expl":"樂之竹管，三孔，以和眾聲也。从品、侖。侖，理也。凡龠之屬皆从龠。","rad":"龠","fq":"以灼切","vol":"02","py":"yuè","duan":[{"e":"樂之竹管。","n":"此與竹部籥異義。今經傳多用籥字。非也。"}]},"䶴":{"expl":"䶴，音律管壎之樂也。从龠炊聲。","rad":"龠","fq":"昌垂切","vol":"02","py":"chuī","duan":[{"e":"䶴音律管壎之樂也。","n":"八字一句。音律者、如王者行師、大師吹律合音是也。竽笙籥簫篪篴管皆竹屬。獨言管者。舉一以該六也。土屬則惟壎可吹。小師言𡔷、？矇言播、笙師言龡者。各因其文也。以人氣作音曰吹。"}]},"䶵":{"expl":"管樂也。从龠虒聲。","rad":"龠","fq":"直离切","vol":"02","py":"chí","duan":[{"e":"管樂也。","n":"管猶筩也。故龠䶵簫皆曰管樂。鄭司農注周禮云。篪七空。廣雅云八孔。賈公彥引禮圖云九孔。其言多轉寫錯亂。疑不能明也。世本云。暴辛公作塤。蘇成公作篪。譙周云。二人善塤善篪。記者因以爲作。謬矣。按許於壎䶵下皆不引世本。於鐘磬笙簧琴瑟則引之。其匡謬不在允南之前乎。"}]},"龢":{"expl":"調也。从龠禾聲。讀與和同。","rad":"龠","fq":"戶戈切","vol":"02","py":"hé","duan":[{"e":"調也。","n":"言部曰。調、龢也。此與口部和音同義別。經傳多假和爲龢。"}]},"龤":{"expl":"樂和龤也。从龠皆聲。《虞書》曰：“八音克龤。”","rad":"龠","fq":"戶皆切","vol":"02","py":"xié","duan":[{"e":"樂龢也。","n":"龤訓龢。龢訓調。調訓龢。三字爲轉注。龤龢作諧和者皆古今字變。許說其未變之義。今本龤下調下作和也。則與龢下調也不爲轉注。龤與言部諧音同義異。各書多用諧爲龤。"}]},"冊":{"expl":"符命也。諸矦進受於王也。象其札一長一短，中有二編之形。凡冊之屬皆从冊。","rad":"冊","fq":"楚革切","vol":"02","py":"cè","duan":[{"e":"符命也。諸侯進受於王者也。","n":"者字依韵會補。尙書王命周公後作𠕋逸誥、左傳王命尹氏及王子虎內史叔興父策命晉矦爲矦伯、王使劉定公賜齊侯命及三王世家策文皆是也。後人多假策爲之。"}]},"嗣":{"expl":"諸侯嗣國也。从冊从口，司聲。","rad":"冊","fq":"祥吏切","vol":"02","py":"sì","duan":[{"e":"諸侯嗣國也。","n":"引伸爲凡繼嗣之偁。"}]},"璊":{"expl":"玉䞓色也。从玉㒼聲。禾之赤苗謂之虋，言璊，玉色如之。","rad":"玉","fq":"莫奔切","vol":"01","py":"mén","duan":[{"e":"玉䞓色也。","n":"毛傳曰。璊、赬玉也。今本脫玉字。"}]},"扁":{"expl":"署也。从戶、冊。戶冊者，署門戶之文也。","rad":"冊","fq":"方沔切","vol":"02","py":"biǎn","duan":[{"e":"署也。","n":"署者、部署有所网屬也。"}]},"㗊":{"expl":"眾口也。从四口。凡㗊之屬皆从㗊。讀若戢。又讀若呶。","rad":"㗊","fq":"阻立切","vol":"03","py":"jí","duan":[{"e":"衆口也。从四口。凡㗊之屬皆从㗊。讀若戢。","n":"阻立切。七部。"}]},"嚚":{"expl":"語聲也。从㗊臣聲。","rad":"㗊","fq":"語巾切","vol":"03","py":"yín","duan":[{"e":"語聲也。","n":"左傳曰。口不道忠信之言爲嚚。引伸之義也。"}]},"囂":{"expl":"聲也。气出頭上。从㗊从頁。頁，首也。","rad":"㗊","fq":"許嬌切","vol":"03","py":"xiāo","duan":[{"e":"聲也。","n":"左傳。湫隘嚻塵。杜曰。嚻、聲也。廣韵曰。喧也。"}]},"嘂":{"expl":"高聲也。一曰大呼也。从㗊丩聲。《春秋公羊傳》曰：“魯昭公叫然而哭。”","rad":"㗊","fq":"古弔切","vol":"03","py":"jiào","duan":[{"e":"高聲也。","n":"此與口部叫噭聲同義異。"}]},"𡅻":{"expl":"呼也。从㗊萈聲。讀若讙。","rad":"㗊","fq":"呼官切","vol":"03","py":"huàn","duan":[{"e":"嘑也。","n":"嘑各本作呼。今正。嘑、號也。廣雅。𡅽、鳴也。玉篇云。𡅽荒貫切。與喚同。廣韵同。按説文無喚字。然則𡅽喚古今字也。"}]},"器":{"expl":"皿也。象器之口，犬所以守之。","rad":"㗊","fq":"去冀切","vol":"03","py":"qì","duan":[{"e":"皿也。","n":"皿部曰。皿、飯食之用器也。然則皿專謂食器。器乃凡器統偁。器下云皿也者、散文則不别也。木部曰。有所盛曰器。無所盛曰械。陸德明本如是。"}]},"舌":{"expl":"在口，所以言也、別味也。从干从口，干亦聲。凡舌之屬皆从舌。","rad":"舌","fq":"食列切","vol":"03","py":"shé","duan":[{"e":"在口所㠯言别味者也。","n":"言下各本有也。剩字。者依韵會補。口下曰。人所以言食也。口云食。舌云别味。各依文爲義。舌后字有互譌者。如左傳舌庸譌后庸、周書美女破后譌破舌是也。"}]},"𦧥":{"expl":"歠也。从舌沓聲。","rad":"舌","fq":"他合切","vol":"03","py":"tà","duan":[{"e":"歠也。","n":"歠、㱃也。曲禮曰。毋嚃羹。廣韵。嚃、歠也。然則嚃卽𦧥也。羹之無菜者不用梜。直歠之而已。禮禁𦧥羹者何也。𦧥者流歠。許渾言之耳。"}]},"舓":{"expl":"以舌取食也。从舌易聲。","rad":"舌","fq":"神旨切","vol":"03","py":"shì","duan":[{"e":"㠯舌取食也。从舌。易聲。","n":"神旨切。按旨當作紙。十六部。"}]},"瑕":{"expl":"玉小赤也。从玉叚聲。","rad":"玉","fq":"乎加切","vol":"01","py":"xiá","duan":[{"e":"玉小赤也。","n":"子虛賦。赤瑕駁犖。張揖曰。赤瑕、赤玉也。揚雄蜀都賦、左思吳都賦皆云瑕英。劉逵曰。瑕、玉屬也。木華海賦。瑕石詭暉。廣雅玉屬有赤瑕。若聘義瑕不揜瑜注。瑕、玉之病也。高注淮南書曰。瑕猶釁也。此別一義。釁同璺。"}]},"干":{"expl":"犯也。从反入，从一。凡干之屬皆从干。","rad":"干","fq":"古寒切","vol":"03","py":"ɡān","duan":[{"e":"犯也。","n":"犯、侵也。毛詩干旄、干旌假爲竿字。"}]},"𢆉":{"expl":"㨖也。从干。入一爲干，入二爲𢆉。讀若能。言稍甚也。","rad":"干","fq":"如審切","vol":"03","py":"rěn","duan":[{"e":"㨖也。","n":"捯、刺也。甘泉賦。洪臺崛其獨岀兮。㨖北極之嶟嶟。"}]},"屰":{"expl":"不順也。从干下屮。屰之也。","rad":"干","fq":"魚戟切","vol":"03","py":"nì","duan":[{"e":"不順也。","n":"後人多用逆。逆行而屰廢矣。"}]},"𧮫":{"expl":"口上阿也。从口，上象其理。凡𧮫之屬皆从𧮫。","rad":"𧮫","fq":"其虐切","vol":"03","py":"jué","duan":[{"e":"口上阿也。","n":"大雅。有卷者阿。箋云。有大陵卷然而曲。口上阿、謂口吻巳上之肉隨口卷曲。毛傳。臄、𦥖也。𢎘部𦥖、𧮫也。與毛合。晉灼注羽獵賦曰。口之上下名爲噱。按通俗文云。口上曰臄。口下曰𦥖。服析言之。毛、許、晉皆渾言之。許舉上以包下耳。今說文各本𦥖下譌作舌也。古者舌無𦥖名。特牲少牢禮。肵俎用心舌。與加殽胛臄異用。陸釋文云。說文曰𦥖、舌也。又云口次肉也。似陸時說文巳誤矣。單行釋文口次譌口裏。則義全非。讀書之難如是。"}]},"㐁":{"expl":"舌皃。从𧮫省。象形。","rad":"𧮫","fq":"他念切","vol":"03","py":"tiàn","duan":[{"e":"舌皃。","n":"魯靈光殿賦。玄熊䑙舕以齗齗。善曰。䑙舕、吐舌皃。吐玷吐暫二切。按䑙葢卽㐁之俗也。"}]},"只":{"expl":"語巳詞也。从口，象气下引之形。凡只之屬皆从只。","rad":"只","fq":"諸氏切","vol":"03","py":"zhǐ","duan":[{"e":"語巳䛐也。","n":"巳、止也。矣只皆語止之詞。庸風母也天只、不諒人只是也。亦借爲是字。小雅樂只君子箋云。只之言是也。王風其樂只且箋云。其且樂此而已。按以此釋只。與小雅箋同。宋人詩用只爲衹字。但也。今人仍之。讀如隻。"}]},"𠷓":{"expl":"聲也。从只甹聲。讀若聲。","rad":"只","fq":"呼形切","vol":"03","py":"xīnɡ","duan":[{"e":"聲也。","n":"謂語聲也。晉宋人多用馨字。若冷如鬼手馨。强來捉人臂。何物老嫗。生此寧馨兒。是也。馨行而𠷓廢矣。隨唐後則又無馨語。此古今之變也。"}]},"㕯":{"expl":"言之訥也。从口从内。凡㕯之屬皆从㕯。","rad":"㕯","fq":"女滑切","vol":"03","py":"nè","duan":[{"e":"言之訥也。","n":"檀弓作呐同。其言呐呐然。如不岀諸其口。注。呐呐、舒小皃。此與言部訥音義皆同。故以訥釋㕯。"}]},"矞":{"expl":"以錐有所穿也。从矛从㕯。一曰滿有所出也。","rad":"㕯","fq":"余律切","vol":"03","py":"yù","duan":[{"e":"㠯錐有所穿也。从矛㕯","n":"㕯者入意。小徐作㕯聲。會意兼形聲也。余律切。十五部。"}]},"商":{"expl":"从外知内也。从㕯，章省聲。","rad":"㕯","fq":"式陽切","vol":"03","py":"shānɡ","duan":[{"e":"從外知內也。从㕯。章省聲。","n":"漢律曆志云。商之爲言章也。物成孰可章度也。白虎通說商賈云。商之爲言章也。章其遠近。度其有亡。通四方之物。故謂之商也。按粊誓我、商賚女。徐仙民音章。此古音也。從外知內、了了章箸曰商。今式陽切。十部。"}]},"琢":{"expl":"治玉也。从玉豖聲。","rad":"玉","fq":"竹角切","vol":"01","py":"zhuó","duan":[{"e":"治玉也。","n":"釋器。玉謂之琢。石謂之摩。毛傳同。按琢琱字謂鐫鏨之事。理字謂分析之事。攷工記𠜜磨五工。玉人、記玉之用。楖人、雕人、闕。楖人葢理之。如楖之疏髮。雕人葢琢之。如鳥之啄物。左思賦水鳥曰。彫琢蔓藻、是其意。"}]},"句":{"expl":"曲也。从口丩聲。凡句之屬皆从句。","rad":"句","fq":"古矦切","vol":"03","py":"ɡōu","duan":[{"e":"曲也。","n":"凡曲折之物。侈爲倨、斂爲句。考工記多言倨句。樂記言倨中矩、句中鉤。淮南子說獸言句爪倨身。凡地名有句字者皆謂山川紆曲。如句容、句章、句餘、高句驪皆是也。凡章句之句亦取稽畱可鉤乙之意。古音總如鉤。後人句曲音鉤。章句音屨。又改句曲字爲勾。此淺俗分别。不可與道古也。"}]},"拘":{"expl":"止也。从句从手，句亦聲。","rad":"句","fq":"舉朱切","vol":"03","py":"jū","duan":[{"e":"止也。从手句。","n":"手句者、以手止之也。"}]},"笱":{"expl":"曲竹捕魚笱也。从竹从句，句亦聲。","rad":"句","fq":"古厚切","vol":"03","py":"ɡǒu","duan":[{"e":"曲竹捕魚笱也。","n":"邶風毛傳曰。笱所以捕魚也。周禮䲣人。掌以時䲣爲梁。大鄭云。梁、水偃。偃水而爲關空。以笱承其空。偃堰、空孔皆古今字。魚梁皆石。絕水。笱、曲竹爲之。以承孔。使魚入其中不得去者。若以薄爲梁。以笱承之。則謂之寡婦之笱。"}]},"鉤":{"expl":"曲也。从金从句，句亦聲。","rad":"句","fq":"古矦切","vol":"03","py":"ɡōu","duan":[{"e":"曲鉤也。","n":"鉤字依韵會補。曲物曰鉤。因之以鉤取物亦曰鉤。"}]},"丩":{"expl":"相糾繚也。一曰瓜瓠結丩起。象形。凡丩之屬皆从丩。","rad":"丩","fq":"居虯切","vol":"03","py":"jiū","duan":[{"e":"相糾繚也。","n":"丩糾曡韵。糾繚亦曡韵字也。毛傳曰。糾糾猶繚繚也。繚、纏也。"}]},"𦱠":{"expl":"艸之相丩者。从茻从丩，丩亦聲。","rad":"丩","fq":"居虯切","vol":"03","py":"jiū","duan":[{"e":"艸之相丩者。","n":"艸相糾繚。故从茻丩。不專謂秦𦫶也。"}]},"糾":{"expl":"繩三合也。从糸、丩。","rad":"丩","fq":"居黝切","vol":"03","py":"jiū","duan":[{"e":"繩三合也。","n":"糸部曰。紉、單繩也。劉表易章句曰。㒳股曰纆。按李善引字林。糾、㒳合繩。纆、三合繩。與許不合。糸部綸下曰。糾青絲繩也。凡交合之謂之糾。引伸爲糾合諸矦之糾。又爲糾責之糾。"}]},"古":{"expl":"故也。从十、口。識前言者也。凡古之屬皆从古。","rad":"古","fq":"公戶切","vol":"03","py":"ɡǔ","duan":[{"e":"故也。","n":"邶風、大雅毛傳曰。古、故也。攵部曰。故、使爲之也。按故者、凡事之所以然。而所以然皆備於古。故曰古、故也。逸周書。天爲古。地爲久。鄭注尚書稽古爲同天。"}]},"嘏":{"expl":"大遠也。从古叚聲。","rad":"古","fq":"古雅切","vol":"03","py":"jiǎ","duan":[{"e":"大遠也。","n":"釋詁、小雅大雅傳、少牢禮注皆曰。嘏、大也。少牢祝嘏于主人。謂予主人以大福。許獨兼遠言之者、大則必遠。故郊特牲曰。嘏、長也。大也。此許所本也。經傳嘏字多謂祭祀致福。其本訓則謂大遠。爾雅、毛傳。假、大也。假葢卽嘏之假借。"}]},"十":{"expl":"數之具也。一爲東西，|爲南北，則四方中央備矣。凡十之屬皆从十。","rad":"十","fq":"是執切","vol":"03","py":"shí","duan":[{"e":"數之具也。","n":"漢志。協於十。"}]},"琱":{"expl":"治玉也。一曰石似玉。从玉周聲。","rad":"玉","fq":"都寮切","vol":"01","py":"diāo","duan":[{"e":"治玉也。","n":"釋器。玉謂之雕。按琱琢同部雙聲、相轉注。詩周禮之追、大雅之敦弓皆與琱雙聲也。"}]},"丈":{"expl":"十尺也。从又持十。","rad":"十","fq":"直兩切","vol":"03","py":"zhànɡ","duan":[{"e":"十尺也。从又持十。","n":"夫部曰。周制八寸爲尺。十尺爲丈。人長八尺。故曰丈夫。然則伸臂一尋。周之丈也。故从又持十。直㒳切。十部。"}]},"千":{"expl":"十百也。从十从人。","rad":"十","fq":"此先切","vol":"03","py":"qiān","duan":[{"e":"十百也。从十。人聲。","n":"此先切。十二部。"}]},"肸":{"expl":"響，布也。从十从䏌。","rad":"十","fq":"羲乙切","vol":"03","py":"xì","duan":[{"e":"肸蠁、","n":"逗。"}]},"卙":{"expl":"卙卙，盛也。从十从甚。汝南名蠶盛曰卙。","rad":"十","fq":"子入切","vol":"03","py":"jí","duan":[{"e":"卙卙、","n":"逗。"}]},"博":{"expl":"大通也。从十从尃。尃，布也。","rad":"十","fq":"補各切","vol":"03","py":"bó","duan":[{"e":"大通也。","n":"凡取於人易爲力曰博。陳風鄭箋。交博好也。"}]},"㔹":{"expl":"材十人也。从十力聲。","rad":"十","fq":"盧則切","vol":"03","py":"lè","duan":[{"e":"材十人也。","n":"十倍於人也。十人爲㔹。千人爲俊。王制。祭用數之仂。注。仂、什一也。按一當十爲㔹。故十取一亦爲仂。葢仂本作㔹也。"}]},"廿":{"expl":"二十并也。古文省。","rad":"十","fq":"人汁切","vol":"03","py":"niàn","duan":[{"e":"二十幷也。古文省多。","n":"省多者、省作二十㒳字爲一字也。考工記。桯長倍之。四尺者二。十分寸之一謂之枚。本於二字爲句絶。故書十與上二合爲廿。此可證周時凡言二十可作廿也。古文廿仍讀二十㒳字。秦碑小篆則維卄六年、維卄九年、卅有七年皆讀一字。以合四言。卄之讀如入。卅之讀如？。皆自反也。至唐石經二十皆作卄。三十皆作卅。則仍讀爲二十、三十矣。人汁切。七部。"}]},"𠦫":{"expl":"詞之𠦫矣。从十咠聲。","rad":"十","fq":"秦入切","vol":"03","py":"jí","duan":[{"e":"詞之集也。","n":"此依廣韵玉篇訂。詞當作辭。此下當有詩曰辭之𠦫矣六字。葢詩作𠦫。許以集解之。今毛詩作輯。傳作輯、和也。許所偁葢三家詩。"}]},"卅":{"expl":"三十并也。古文省。凡卅之屬皆从卅。","rad":"卅","fq":"蘇沓切","vol":"03","py":"sà","duan":[{"e":"三十幷也。古文省。","n":"此亦當云省多。奪耳。古音當先立切。七部。今音蘇沓切。"}]},"世":{"expl":"三十年爲一丗。从卅而曳長之。亦取其聲也。","rad":"卅","fq":"舒制切","vol":"03","py":"shì","duan":[{"e":"三十年爲一世。","n":"論語。如有王者。必世而後仁。孔曰。三十年曰世。按父子相繼曰世。其引伸之義也。"}]},"理":{"expl":"治玉也。从玉里聲。","rad":"玉","fq":"良止切","vol":"01","py":"lǐ","duan":[{"e":"治玉也。","n":"戰國策。鄭人謂玉之未理者爲璞。是理爲剖析也。玉雖至堅。而治之得其䚡理以成器不難。謂之理。凡天下一事一物、必推其情至於無憾而後卽安。是之謂天理。是之謂善治。此引伸之義也。戴先生孟子字義疏證曰。理者、察之而幾微必區以別之名也。是故謂之分理。在物之質曰肌理。曰腠理。曰文理。得其分則有條而不紊、謂之條理。鄭注樂記曰。理者、分也。許叔重曰。知分理之可相別異也。古人之言天理何謂也。曰理也者、情之不爽失也。未有情不得而理得者也。天理云者、言乎自然之分理也。自然之分理。以我之情絜人之情、而無不得其平是也。"}]},"言":{"expl":"直言曰言，論難曰語。从口䇂聲。凡言之屬皆从言。","rad":"言","fq":"語軒切","vol":"03","py":"yán","duan":[{"e":"直言曰言。論難曰語。","n":"大雅毛傳曰。直言曰言。論難曰語。論、正義作荅。鄭注大司樂曰。發端曰言。荅難曰語。注襍記曰。言、言己事。爲人說爲語。按三注大略相同。下文語、論也。論、議也。議、語也。則詩傳當從定本、集注矣。爾雅、毛傳。言、我也。此於雙聲得之。本方俗語言也。"}]},"譻":{"expl":"聲也。从言賏聲。","rad":"言","fq":"烏莖切","vol":"03","py":"yīnɡ","duan":[{"e":"聲也。","n":"思玄賦。鳴玉鸞之譻譻。原注。譻譻、聲也。按篆下當有譻譻二字。淺人刪之。"}]},"謦":{"expl":"欬也。从言殸聲。殸，籒文磬字。","rad":"言","fq":"去挺切","vol":"03","py":"qǐnɡ","duan":[{"e":"欬也。","n":"欬、屰气也。通俗文曰。利喉謂之謦欬。按謦欬見莊子徐無鬼。"}]},"語":{"expl":"論也。从言吾聲。","rad":"言","fq":"魚舉切","vol":"03","py":"yǔ","duan":[{"e":"論也。","n":"此卽毛鄭說也。語者、禦也。如毛說。一人辯論是非謂之語。如鄭說。與人相荅問辯難謂之語。"}]},"談":{"expl":"語也。从言炎聲。","rad":"言","fq":"徒甘切","vol":"03","py":"tán","duan":[{"e":"語也。","n":"談者、淡也。平淡之語。"}]},"謂":{"expl":"報也。从言胃聲。","rad":"言","fq":"于貴切","vol":"03","py":"wèi","duan":[{"e":"報也。","n":"㚔部曰。報、當罪人也。葢㓝與罪相當謂之報。引伸凡論人論事得其實謂之報。謂者、論人論事得其實也。如論語謂韶、謂武子、謂子賤子、謂仲弓、其斯之謂與、大學此謂身不脩不可以齊其家是也。亦有借爲曰字者。如左傳王謂叔父、卽魯頌之王曰、叔父也。亦有訓爲勤者。亦以合音冣近也。"}]},"諒":{"expl":"信也。从言京聲。","rad":"言","fq":"力讓切","vol":"03","py":"liànɡ","duan":[{"e":"信也。","n":"方言。衆信曰、諒。周南、召南、衞之語也。經傳或假亮爲諒。"}]},"詵":{"expl":"致言也。从言从先，先亦聲。《詩》曰：“螽斯羽詵詵兮。”","rad":"言","fq":"所臻切","vol":"03","py":"shēn","duan":[{"e":"致言也。从言先。","n":"所謂先容也。"}]},"請":{"expl":"謁也。从言青聲。","rad":"言","fq":"七井切","vol":"03","py":"qǐnɡ","duan":[{"e":"謁也。","n":"周禮。春朝秋覲。漢改爲春朝秋請。"}]},"謁":{"expl":"白也。从言曷聲。","rad":"言","fq":"於歇切","vol":"03","py":"yè","duan":[{"e":"白也。","n":"廣韵曰。白、告也。按謁者、若後人書刺自言爵里姓名並列所白事。"}]},"珍":{"expl":"寶也。从玉㐱聲。","rad":"玉","fq":"陟鄰切","vol":"01","py":"zhēn","duan":[{"e":"寶也。","n":"宀部曰。寶、珍也。是爲轉注。"}]},"許":{"expl":"聽也。从言午聲。","rad":"言","fq":"虚呂切","vol":"03","py":"xǔ","duan":[{"e":"𦗟言也。","n":"𦗟從之言也。耳與聲相入曰𦗟。引伸之凡順從曰𦗟。許、或假爲所。或假爲御。下武傳。許、進也。卽御進也。東平王蒼正作昭茲來御。又爲鄦之叚借字。"}]},"諾":{"expl":"𧭭也。从言若聲。","rad":"言","fq":"奴各切","vol":"03","py":"nuò","duan":[{"e":"𤻮也。","n":"𤻮者、應之俗字。說解中有此字。或偶爾从俗。或後人妄改。疑不能明也。大徐於此部增𤻮字。誤矣。口部曰。唯、諾也。唯諾有急緩之别。統言之則皆應也。"}]},"𧭭":{"expl":"以言對也。从言𨿳聲。","rad":"言","fq":"於證切","vol":"03","py":"yìnɡ","duan":[]},"讎":{"expl":"猶𧭭也。从言雔聲。","rad":"言","fq":"市流切","vol":"03","py":"chóu","duan":[{"e":"猶𧭭也。","n":"心部曰。應、當也。讎者、以言對之。詩云無言不讎是也。引伸之爲物價之讎。詩賈用不讎、高祖飲酒讎數倍是也。又引伸之爲讎怨。詩不我能慉、反以我爲讎、周禮父之讎、兄弟之讎是也人部曰。仇、讎也。仇讎本皆兼善惡言之。後乃專謂怨爲讎矣。凡漢人作注云猶者皆義隔而通之。如公、穀皆云孫猶孫也。謂此子孫字同孫遁之孫。鄭風傳漂猶吹也。謂漂本訓浮。因吹而浮。故同首章之吹。凡鄭君、高誘等每言猶者皆同此。許造說文不比注經傳。故徑說字義不言猶。惟？字下云。㠭猶齊也。此因㠭之本義極巧視之。於？从㠭義隔。故通之曰猶齊。此以應釋讎甚明。不當曰猶應。葢淺人但知讎爲怨䛐。以爲不切。故加之耳。然則爾字下云麗爾猶靡麗也。此猶亦可刪與。曰此"}]},"諸":{"expl":"辯也。从言者聲。","rad":"言","fq":"章魚切","vol":"03","py":"zhū","duan":[{"e":"辯也。","n":"辯當作辨。判也。按辨下奪䛐字。諸不訓辨。辨之䛐也。䛐者、意內而言外也。白部曰。者、别事䛐也。諸與者音義皆同。釋魚。前弇諸果。後弇諸獵。諸卽者。郊特牲。或諸遠人乎。亦作或者遠人乎。凡舉其一。則其餘謂之諸以别之。因之訓諸爲衆。或訓爲之。或訓爲之於。則於雙聲曡韵求之。"}]},"詩":{"expl":"志也。从言寺聲。","rad":"言","fq":"書之切","vol":"03","py":"shī","duan":[{"e":"志也。","n":"毛詩序曰。詩者、志之所之也。在心爲志。發言爲詩。按許不云志之所之。徑云志也者。序析言之。許渾言之也。所以多渾言之者、欲使人因屬以求别也。又特牲禮詩懷之注。詩猶承也。謂奉納之懷中。內則詩負之注。詩之言承也。按正義引含神霧云。詩、持也。假詩爲持。假持爲承。一部與六部合音冣近也。上林賦葴持。持音懲。"}]},"讖":{"expl":"驗也。从言韱聲。","rad":"言","fq":"楚蔭切","vol":"03","py":"chèn","duan":[{"e":"驗也。","n":"驗本馬名。葢卽譣之假借。讖驗曡韵。"}]},"諷":{"expl":"誦也。从言風聲。","rad":"言","fq":"芳奉切","vol":"03","py":"fěnɡ","duan":[{"e":"誦也。","n":"大司樂。以樂語敎國子。興道諷誦言語。注。倍文曰諷。以聲節之曰誦。倍同背。謂不開讀也。誦則非直背文。又爲吟詠以聲節之。周禮經注析言之。諷誦是二。許統言之。諷誦是一也。"}]},"誦":{"expl":"諷也。从言甬聲。","rad":"言","fq":"似用切","vol":"03","py":"sònɡ","duan":[{"e":"諷也。从言。甬聲。","n":"似用切。九部。"}]},"讀":{"expl":"誦書也。从言賣聲。","rad":"言","fq":"徒谷切","vol":"03","py":"dú","duan":[{"e":"籒書也。","n":"籒各本作誦。此淺人改也。今正。竹部曰。籒、讀書也。讀與籒曡韵而互訓。庸風傳曰。讀、抽也。方言曰。抽、讀也。葢籒抽古通用。史記。紬史記石室金匱之書。字亦作紬。抽繹其義薀至於無窮。是之謂讀。故⺊筮之辭曰籒。謂抽繹易義而爲之也。尉律。學僮十七巳上始試。諷籒書九千字。乃得爲吏。諷謂背其文。籒謂能繹其義。大史公作史記。曰余讀高祖侯功臣、曰大史公讀列封至便侯、曰大史公讀秦楚之際、曰余讀諜記、曰大史公讀春秋暦諩諜、曰大史公讀秦記皆謂紬繹其事以作表也。漢濡注經。𣃔其章句爲讀。如周禮注鄭司農讀火絶之、儀禮注舊讀昆弟在下、舊讀合大夫之妾爲君之庶子女子子嫁者未嫁者是也。擬其音曰讀。凡言讀如、讀若皆是也。易其字以釋其"}]},"玩":{"expl":"弄也。从玉元聲。","rad":"玉","fq":"五換切","vol":"01","py":"wán","duan":[{"e":"弄也。","n":"廾部曰。弄、玩也。是爲轉注。周禮曰。玩好之用。"}]},"𠶷":{"expl":"快也。从言从中。","rad":"言","fq":"於力切","vol":"03","py":"yì","duan":[{"e":"快也。","n":"快、喜也。"}]},"訓":{"expl":"說教也。从言川聲。","rad":"言","fq":"許運切","vol":"03","py":"xùn","duan":[{"e":"說敎也。","n":"說敎者、說釋而教之。必順其理。引伸之凡順皆曰訓。如五品不訓、聞六律五聲八音七始訓以岀內五言是也。"}]},"誨":{"expl":"曉教也。从言每聲。","rad":"言","fq":"荒內切","vol":"03","py":"huì","duan":[{"e":"曉教也。","n":"曉教者。明曉而教之也。訓以柔克。誨以剛克。周書無逸胥訓告、胥教悔是也。曉之以破其晦是曰誨。"}]},"譔":{"expl":"專教也。从言巽聲。","rad":"言","fq":"此緣切","vol":"03","py":"zhuàn","duan":[{"e":"專教也。","n":"專教者、專壹而教之也。鄭注論語異乎三子者之撰。撰讀曰譔。譔之言善也。廣韵曰。譔、善言也。本鄭。"}]},"譬":{"expl":"諭也。从言辟聲。","rad":"言","fq":"匹至切","vol":"03","py":"pì","duan":[{"e":"諭也。","n":"諭、告也。譬與諭非一事。此亦統言之也。"}]},"謜":{"expl":"徐語也。从言原聲。《孟子》曰：“故謜謜而來。”","rad":"言","fq":"魚怨切","vol":"03","py":"yuán","duan":[{"e":"徐語也。从言。原聲。","n":"魚怨切。十四部。"}]},"詇":{"expl":"早知也。从言央聲。","rad":"言","fq":"於亮切","vol":"03","py":"yànɡ","duan":[{"e":"早知也。从言。央聲。","n":"於亮切。十部。"}]},"諭":{"expl":"告也。从言俞聲。","rad":"言","fq":"羊戍切","vol":"03","py":"yù","duan":[{"e":"告也。","n":"凡曉諭人者、皆舉其所易明也。周禮掌交注曰。諭、告曉也。曉之曰諭。其人因言而曉亦曰諭。諭或作喻。"}]},"詖":{"expl":"辯論也。古文以爲頗字。从言皮聲。","rad":"言","fq":"彼義切","vol":"03","py":"bì","duan":[{"e":"辨論也。","n":"此詖字正義。皮、剥取獸革也。柀、析也。凡从皮之字皆有分析之意。故詖爲辨論也。"}]},"諄":{"expl":"告曉之孰也。从言𦎫聲。讀若庉。","rad":"言","fq":"章倫切","vol":"03","py":"zhūn","duan":[{"e":"告曉之孰也。","n":"大雅。誨爾諄諄。左傳年未盈五十。而諄諄如八九十者。孟子。諄諄然命之乎。大雅諄諄、鄭注中庸引作忳忳。云忳忳、𢡆誠皃也。按其中𢡆誠。其外乃告曉之孰。義相足也。方言曰。諄、辠也。又曰。宋魯凡相惡謂之諄憎。此則敦字之假借。攵部曰。敦、怒也。詆也。詩。王事敦我。"}]},"祿":{"expl":"福也。从示彔聲。","rad":"示","fq":"盧谷切","vol":"01","py":"lù","duan":[{"e":"福也。","n":"詩言福祿多不別。商頌五篇。㒳言福、三言祿。大恉不殊。釋詁、毛詩傳皆曰。祿、福也。此古義也。鄭旣醉箋始爲分別之詞。"}]},"玲":{"expl":"玉聲。从玉令聲。","rad":"玉","fq":"郎丁切","vol":"01","py":"línɡ","duan":[{"e":"玉聲也。","n":"甘泉賦。和氏瓏玲。大玄。亾彼瓏玲。皆謂玉聲。法言、廣雅作玲瓏。"}]},"謘":{"expl":"語諄謘也。从言屖聲。","rad":"言","fq":"直离切","vol":"03","py":"chí","duan":[{"e":"語、諄謘也。","n":"諄謘葢猶鈍遟也。此諄字與上文不同。鍇本謘本在詑篆下。"}]},"詻":{"expl":"論訟也。《傳》曰：“詻詻孔子容。”从言各聲。","rad":"言","fq":"五陌切","vol":"03","py":"è","duan":[{"e":"論訟也。","n":"訟當作頌。論頌卽言容也。玉藻曰。戎容曁曁。言容詻詻。注。詻詻、教令嚴也。周禮𠈃氏六儀。五曰軍旅之容。注。軍旅之容。曁曁詻詻。"}]},"誾":{"expl":"和說而諍也。从言門聲。","rad":"言","fq":"語巾切","vol":"03","py":"yín","duan":[{"e":"和說而諍也。","n":"論語鄉黨孔注。侃侃、和樂皃。誾誾、、中正兒。先進皇侃亦云爾。按侃侃爲和樂者、謂侃侃卽衎衎之假借也。誾誾爲中正者、謂和悦而諍、柔剛得中也。言居門中。亦有中正之意。"}]},"謀":{"expl":"慮難曰謀。从言某聲。","rad":"言","fq":"莫浮切","vol":"03","py":"móu","duan":[{"e":"慮難曰謀。","n":"左傳叔孫豹說皇皇者華曰。訪問於善爲咨。咨難爲謀。魯語作咨事爲謀。韋曰。事當爲難。吳語大夫種曰。夫謀必素見成事焉而後履之。囗部曰。圖、畫計難也。圖與謀同義。"}]},"謨":{"expl":"議謀也。从言莫聲。《虞書》曰：“咎繇謨。”","rad":"言","fq":"莫胡切","vol":"03","py":"mó","duan":[{"e":"議謀也。","n":"釋詁曰。謨、謀也。許於雙聲釋爲議謀。詩巧言假莫爲謨。"}]},"訪":{"expl":"汎謀曰訪。从言方聲。","rad":"言","fq":"敷亮切","vol":"03","py":"fǎnɡ","duan":[{"e":"汎謀曰訪。","n":"汎與訪雙聲。方與旁古通用。溥也。洪範。王訪于箕子。晉語。文王諏於蔡原而訪於辛尹。韋曰。諏訪皆謀也。本釋詁。許於方聲别之曰汎謀。"}]},"諏":{"expl":"聚謀也。从言取聲。","rad":"言","fq":"子于切","vol":"03","py":"jū","duan":[{"e":"聚謀也。","n":"左傳。咨事爲諏。魯語作咨才。韋曰。才當爲事。按釋詁。諏、謀也。許於取聲别之曰聚謀。儀禮今文假詛爲諏。大玄作？"}]},"論":{"expl":"議也。从言侖聲。","rad":"言","fq":"盧昆切","vol":"03","py":"lún","duan":[{"e":"議也。","n":"論以侖會意。亼部曰。侖。思也。龠部曰。侖、理也。此非㒳義。思如玉部䚡理、自外可以知中之䚡。靈臺。於論𡔷鍾。毛曰。論、思也。此正許所本。詩於論正侖之假借。凡言語循其理、得其宜謂之論。故孔門師弟子之言謂之論語。皇侃依俗分去聲平聲異其解。不知古無異義。亦無平去之别也。王制。凡制五㓝。必卽天論。周易。君子以經論。中庸。經論天下之大經。皆謂言之有倫有脊者。許云。論者、議也。議者、語也。似未盡。"}]},"議":{"expl":"語也。从言義聲。","rad":"言","fq":"宜寄切","vol":"03","py":"yì","duan":[{"e":"語也。","n":"上文云論難曰語。又云語、論也。是論議語三字爲與人言之稱。按許說未盡。議者、誼也。誼者、人所宜也。言得其宜之謂議。至於詩言岀入風議、孟子言處士横議、而天下亂矣。"}]},"訂":{"expl":"平議也。从言丁聲。","rad":"言","fq":"他頂切","vol":"03","py":"dìnɡ","duan":[{"e":"平議也。","n":"考工記注。參訂之而平。"}]},"瑲":{"expl":"玉聲也。从玉倉聲。《詩》曰：“鞗革有瑲。”","rad":"玉","fq":"七羊切","vol":"01","py":"qiānɡ","duan":[{"e":"玉聲也。","n":"小雅。有瑲蔥珩。毛傳。瑲、珩聲也。秦風佩玉將將、玉藻然後玉鏘鳴皆當作此字。"}]},"詳":{"expl":"審議也。从言羊聲。","rad":"言","fq":"似羊切","vol":"03","py":"xiánɡ","duan":[{"e":"審議也。","n":"審、悉也。經傳多假爲祥字。又音羊。爲詳狂字。"}]},"諟":{"expl":"理也。从言是聲。","rad":"言","fq":"承旨切","vol":"03","py":"shì","duan":[{"e":"理也。","n":"左傳。君與大夫不善是也。國語作王弗是。韋曰。是、理也。是者諟之假借字。韋注與許合。理猶今人言是正也。臣之行𧮂者王不能是正也。大學引大甲。顧諟天之明命。注。諟猶正也。某氏僞大甲傳。諟、是也。皆與許合。大學諟或爲題。"}]},"諦":{"expl":"審也。从言帝聲。","rad":"言","fq":"都計切","vol":"03","py":"dì","duan":[{"e":"審也。","n":"毛傳曰審諦如帝。"}]},"識":{"expl":"常也。一曰知也。从言戠聲。","rad":"言","fq":"賞職切","vol":"03","py":"shí","duan":[{"e":"常也。","n":"常當爲意。字之誤也。草書常意相似。六朝以草寫書。迨草變眞。譌誤往往如此。意者、志也。志者、心所之也。意與志、志與識古皆通用。心之所存謂之意。所謂知識者此也。大學。誠其意。卽實其識也。"}]},"訊":{"expl":"問也。从言卂聲。","rad":"言","fq":"思晉切","vol":"03","py":"xùn","duan":[{"e":"問也","n":"釋言曰。訊、言也。小雅。訊之占夢。毛曰。訊、問也。鄭箋執訊皆兼言問爲訓。"}]},"詧":{"expl":"言微親詧也。从言，察省聲。","rad":"言","fq":"楚八切","vol":"03","py":"chá","duan":[{"e":"言微親察也。从言。祭省聲。","n":"鉉祭作察。誤。楚八切。十五部。"}]},"謹":{"expl":"愼也。从言堇聲。","rad":"言","fq":"居隱切","vol":"03","py":"jǐn","duan":[{"e":"愼也。","n":"心部曰。愼、謹也。"}]},"䚮":{"expl":"厚也。从言乃聲。","rad":"言","fq":"如乘切","vol":"03","py":"rénɡ","duan":[{"e":"厚也。","n":"因仍則加厚。䚮與仍音義略同。"}]},"諶":{"expl":"誠諦也。从言甚聲。《詩》曰：“天難諶斯。”","rad":"言","fq":"是吟切","vol":"03","py":"chén","duan":[{"e":"誠諦也。","n":"釋詁。諶、信也。許曰誠諦。未詳。疑諦乃締之誤。"}]},"信":{"expl":"誠也。从人从言。會意。","rad":"言","fq":"息晉切","vol":"03","py":"xìn","duan":[{"e":"誠也。","n":"釋詁。誠、信也。"}]},"玎":{"expl":"玉聲也。从玉丁聲。齊太公子伋謚曰玎公。","rad":"玉","fq":"當經切","vol":"01","py":"dīnɡ","duan":[{"e":"玉聲也。","n":"以椓之丁丁、伐木丁丁例之。葢當曡字言玎玎。"}]},"訦":{"expl":"燕、代、東齊謂信訦。从言冘聲。","rad":"言","fq":"是吟切","vol":"03","py":"chén","duan":[{"e":"燕代東齊謂信訦也。","n":"方言。允訦恂展諒穆信也。燕代東齊曰訦。"}]},"誠":{"expl":"信也。从言成聲。","rad":"言","fq":"氏征切","vol":"03","py":"chénɡ","duan":[{"e":"信也。从言。成聲。","n":"氏征切。十一部。"}]},"誡":{"expl":"敕也。从言戒聲。","rad":"言","fq":"古拜切","vol":"03","py":"jiè","duan":[{"e":"敕也。","n":"攵部曰。敕、誡也。"}]},"誋":{"expl":"誡也。从言忌聲。","rad":"言","fq":"渠記切","vol":"03","py":"jì","duan":[{"e":"誡也。","n":"淮南繆稱注曰。誋、誡也。"}]},"諱":{"expl":"誋也。从言韋聲。","rad":"言","fq":"許貴切","vol":"03","py":"huì","duan":[{"e":"忌也。","n":"鉉本諱、誋也。在誡誋二字之下。淺人妄移也。鍇本廁此是矣。而忌作誋、仍誤。誋誡也。忌、憎惡也。故諱與謚誄爲類。"}]},"誥":{"expl":"告也。从言告聲。","rad":"言","fq":"古到切","vol":"03","py":"ɡào","duan":[{"e":"告也。","n":"見釋詁。按以言告人。古用此字。今則用告字。以此誥爲上告下之字。又秦造詔字。惟天子獨稱之。文選注卅五引獨𣃔曰。詔猶告也。三代無其文。秦漢有也。據此可證秦巳前無詔字。至倉頡篇乃有幼子承詔之語。故許書不錄詔字。鉉補之。非也。"}]},"詔":{"expl":"告也。从言从召，召亦聲。","rad":"言","fq":"之紹切","vol":"03","py":"zhào","duan":[]},"誓":{"expl":"約束也。从言折聲。","rad":"言","fq":"時制切","vol":"03","py":"shì","duan":[{"e":"約束也。","n":"周禮五戒。一曰誓。用之於軍旅。按凡自表不食言之辭皆曰誓。亦約束之意也。"}]},"譣":{"expl":"問也。从言僉聲。《周書》曰：“勿以譣人。”","rad":"言","fq":"息廉切","vol":"03","py":"xiǎn","duan":[{"e":"問也。","n":"按言部讖、驗也。竹部籤、驗也。驗在馬部爲馬名。然則云徵驗者、於六書爲假借。莫詳其正字。今按譣其正字也。譣訓問、謂按問。與試驗、應驗義近。自驗切魚窆。譣切息廉二音迥異。尟識其關竅矣。"}]},"詁":{"expl":"訓故言也。从言古聲。《詩》曰詁訓。","rad":"言","fq":"公戶切","vol":"03","py":"ɡǔ","duan":[{"e":"訓故言也。","n":"故言者、舊言也。十口所識前言也。訓者、說教也。訓故言者、說釋故言以教人是之謂詁。分之則如爾雅析故訓言爲三。三而實一也。漢人傳注多偁故者、故卽詁也。毛詩云故訓傳者、故訓猶故言也。謂取故言爲傳也。取故言爲傳、是亦詁也。賈誼爲左氏傳訓故。訓故者、順釋其故言也。"}]},"琤":{"expl":"玉聲也。从玉爭聲。","rad":"玉","fq":"楚耕切","vol":"01","py":"chēnɡ","duan":[{"e":"玉聲也。从王。爭聲。","n":"楚耕切。十一部。按此字恐系瑲之俗。"}]},"藹":{"expl":"臣盡力之美。从言葛聲。《詩》曰：“譪譪王多吉士。”","rad":"言","fq":"於害切","vol":"03","py":"ǎi","duan":[{"e":"臣盡力之美。","n":"釋訓曰。譪譪、萋萋、臣盡力也。大雅毛傳曰。譪譪猶濟濟也。濟濟、多威儀也。"}]},"誎":{"expl":"餔旋促也。从言束聲。","rad":"言","fq":"桑谷切","vol":"03","py":"sù","duan":[{"e":"餔旋促也。","n":"未聞。疑有誤字。廣雅。誎、促也。集韵、手鑑云。飾也。"}]},"諝":{"expl":"知也。从言胥聲。","rad":"言","fq":"私呂切","vol":"03","py":"xū","duan":[{"e":"知也。","n":"周禮、詩皆假胥爲之。天官胥十有二人注。胥讀爲諝。謂其有才知爲什長。秋官象胥注。胥其有才知者也。小雅君子樂胥箋云。胥有才知之名也。周易假須爲之。鄭云。須、有才知之稱。天文有須女。屈原之妹名女須。按荀爽一名諝。"}]},"証":{"expl":"諫也。从言正聲。","rad":"言","fq":"之盛切","vol":"03","py":"zhènɡ","duan":[{"e":"諫也。","n":"呂覽士尉以証靜郭君。高曰。証、諫也。今俗以証爲證驗字。遂改呂覽之証爲證。"}]},"諫":{"expl":"証也。从言柬聲。","rad":"言","fq":"古晏切","vol":"03","py":"jiàn","duan":[{"e":"証也。从言。柬聲。","n":"古晏切。十四部。"}]},"諗":{"expl":"深諫也。从言念聲。《春秋傳》曰：“辛伯諗周桓公。”","rad":"言","fq":"式荏切","vol":"03","py":"shěn","duan":[{"e":"深諫也。","n":"諗深曡韵。深諫者、言人之所不能言也。小雅。是用作歌。將母來諗。箋云。諗、告也。以餋父母之志來告於君。左傳。昔辛伯諗周桓公。此皆於深諫義近。毛曰。諗、念也。此則謂諗爲念之同音假借。"}]},"課":{"expl":"試也。从言果聲。","rad":"言","fq":"苦臥切","vol":"03","py":"kè","duan":[{"e":"試也。","n":"廣韵。第也。税也。皆課試引伸之義。"}]},"試":{"expl":"用也。从言式聲。《虞書》曰：“明試以功。”","rad":"言","fq":"式吏切","vol":"03","py":"shì","duan":[{"e":"用也。从言。式聲。","n":"式束切。一部。"}]},"諴":{"expl":"和也。从言咸聲。《周書》曰：“不能諴于小民。”","rad":"言","fq":"胡毚切","vol":"03","py":"xián","duan":[{"e":"和也。","n":"和當作龢。某氏注尚書同。"}]},"䚻":{"expl":"徒歌。从言、肉。","rad":"言","fq":"余招切","vol":"03","py":"yáo","duan":[{"e":"徒歌。","n":"釋樂曰。徒歌曰謡。魏風毛傳曰。曲合樂曰歌。徒歌曰謡。又大雅傳曰。歌者比於琴瑟也。徒歌曰謡。徒擊𡔷曰咢。今本或妄刪之。"}]},"瑣":{"expl":"玉聲也。从玉𧴪聲。","rad":"玉","fq":"蘇果切","vol":"01","py":"suǒ","duan":[{"e":"玉聲。","n":"謂玉之小聲也。周易。旅瑣瑣。鄭君、陸績皆曰。瑣瑣、小也。"}]},"詮":{"expl":"具也。从言全聲。","rad":"言","fq":"此緣切","vol":"03","py":"quán","duan":[{"e":"具也。","n":"淮南書有詮言訓。高注曰。詮、就也。就萬物之指以言其徵。事之所謂。道之所依也。故曰詮言。欠部欥下曰。詮䛐也。然則許意。謂詮解。"}]},"訢":{"expl":"喜也。从言斤聲。","rad":"言","fq":"許斤切","vol":"03","py":"xīn","duan":[{"e":"喜也。从言。斤聲。","n":"許斤切。十三部。按此與欠部欣音義皆同。萬石君傳。僮僕訢訢如也。晉灼引許愼曰。訢古欣字。葢灼所據說文訢在欠部欣下。云古文欣、從言。"}]},"說":{"expl":"說，釋也。从言、兌。一曰談說。","rad":"言","fq":"失爇切","vol":"03","py":"shuō","duan":[{"e":"說釋也。","n":"說釋卽悦懌。說悦釋懌皆古今字。許書無悦懌二字也。說釋者、開解之意。故爲喜悦。釆部曰。釋、解也。"}]},"計":{"expl":"會也。筭也。从言从十。","rad":"言","fq":"古詣切","vol":"02","py":"jì","duan":[{"e":"會也。筭也。","n":"會、合也。筭當作算。數也。舊書多假筭爲算。"}]},"諧":{"expl":"詥也。从言皆聲。","rad":"言","fq":"戶皆切","vol":"03","py":"xié","duan":[{"e":"詥也。","n":"此與龠部龤異用。龤專謂樂和。"}]},"詥":{"expl":"諧也。从言合聲。","rad":"言","fq":"候閤切","vol":"03","py":"hé","duan":[{"e":"諧也。","n":"詥之言合也。"}]},"調":{"expl":"和也。从言周聲。","rad":"言","fq":"徒遼切","vol":"03","py":"tiáo","duan":[{"e":"龢也。","n":"龢各本作和今正。龠部曰。龢、調也。與此互訓。和本係唱和字。故許云相應也。今則槩用和而龢廢矣。"}]},"話":{"expl":"合會善言也。从言𠯑聲。《傳》曰：“告之話言。”","rad":"言","fq":"胡快切","vol":"03","py":"huà","duan":[{"e":"會合善言也。","n":"䛡會曡韵。大雅。愼爾岀話。毛曰。話、善言也。"}]},"諈":{"expl":"諈諉，纍也。从言𡍮聲。","rad":"言","fq":"竹寘切","vol":"03","py":"zhuì","duan":[{"e":"諈諉、絫也。","n":"絫累正俗字。今人槩作累而絫廢矣。見釋言。孫炎曰。楚人曰諈。齊人曰諉。郭璞曰。以事相屬累爲諈諉。"}]},"諉":{"expl":"纍也。从言委聲。","rad":"言","fq":"女恚切","vol":"03","py":"wěi","duan":[{"e":"諈諉也。","n":"舊作絫也。今依全書通例正。"}]},"瑝":{"expl":"玉聲也。从玉皇聲。","rad":"玉","fq":"乎光切","vol":"01","py":"huánɡ","duan":[{"e":"玉聲。","n":"謂玉之大聲也。"}]},"警":{"expl":"戒也。从言从敬，敬亦聲。","rad":"言","fq":"居影切","vol":"03","py":"jǐnɡ","duan":[{"e":"言之戒也。","n":"？部曰。戒警也。小雅。徒御不警。毛曰。不警、警也。大雅以敬爲之。常武。旣敬旣戒。箋云。敬之言警也。亦作僘。"}]},"謐":{"expl":"靜語也。从言𥁑聲。一曰無聲也。","rad":"言","fq":"彌必切","vol":"03","py":"mì","duan":[{"e":"靜語也。","n":"今文尚書維㓝之謐哉。周頌。誐以謐我。釋詁曰。謐、靜也。按周頌謐亦作溢、亦作恤。堯典謐亦作恤。釋詁。溢、愼也。溢、愼、謐、靜也。恤與謐同部。溢葢恤之譌體。愼靜二義相成。許云靜語者、爲其從言也。"}]},"謙":{"expl":"敬也。从言兼聲。","rad":"言","fq":"苦兼切","vol":"03","py":"qiān","duan":[{"e":"敬也。","n":"敬、肅也。謙與敬義相成。"}]},"𧧼":{"expl":"人所宜也。从言从宜，宜亦聲。","rad":"言","fq":"儀寄切","vol":"03","py":"yì","duan":[{"e":"人所宜也。","n":"周禮肆師注。故書儀爲義。鄭司農云。義讀爲儀。古者書儀但爲義。今時所謂義爲誼。按此則誼義古今字。周時作誼。漢時作義。皆今之仁義字也。其威儀字。則周時作義漢時作儀。凡讀經傳者。不可不知古今字。古今無定時。周爲古則漢爲今。漢爲古則晉宋爲今。隨時異用者謂之古今字。非如今人所言古今籒文爲古字。小篆隷書爲今字也。云誼者人所宜。則許謂誼爲仁義字。今俗分别爲恩誼字。乃野說也。中庸云。仁者人也。義者宜也。是古訓也。"}]},"詡":{"expl":"大言也。从言羽聲。","rad":"言","fq":"況羽切","vol":"03","py":"xǔ","duan":[{"e":"大言也。","n":"禮器。德發揚詡萬物。注。詡猶普也。按詡之本義爲大言。故訓爲普則曰猶。凡古注言猶者視此。詡之引伸之義爲大。故周弁殷吁夏收、白虎通吁作詡。鄭注禮云。吁名岀於幠。幠、覆也。義可相發明。"}]},"諓":{"expl":"善言也。从言戔聲。一曰謔也。","rad":"言","fq":"慈衍切","vol":"03","py":"jiàn","duan":[{"e":"善言也。","n":"善上當有諓諓二字。古文秦誓𢧵𢧵善諞言。諞字下引之。今文秦誓戔戔。戈部戔字下引之。釋云。巧言也。戔戔公羊傳作諓諓。云惟諓諓善靖言。劉向九歎、漢書李尋傳亦皆作諓諓。王逸注楚辭。引尚書諓諓靖言。正皆今文尚書也。諸家作諓許作戔者、同一今文而有異本。如同一古文而馬作偏許作諞不同也。戔下旣引戔戔矣。而諓下又云善言者。此又用王逸所據諓諓靖言之本也。善言釋靖言。何休曰。靖猶撰也。撰同譔。譔言、善言也。廣雅釋訓曰。諓諓、善也。賈逵外傳注曰。諓諓、巧言也。韋昭注曰。諓諓、巧辨之言。然則此善言、謂善爲言辭者。不同䛡下之善言也。"}]},"誐":{"expl":"嘉善也。从言我聲。《詩》曰：“誐以溢我。”","rad":"言","fq":"五何切","vol":"03","py":"é","duan":[{"e":"嘉善也。","n":"誐嘉曡韵。壴部嘉、美也。"}]},"詷":{"expl":"共也。一曰譀也。从言同聲。《周書》曰：“在夏后之詷。”","rad":"言","fq":"徒紅切","vol":"03","py":"tónɡ","duan":[{"e":"共也。从言。同聲。","n":"徒紅切。九部。"}]},"設":{"expl":"施陳也。从言从殳。殳，使人也。","rad":"言","fq":"識列切","vol":"03","py":"shè","duan":[{"e":"施陳也。","n":"設施雙聲。㫃部曰。施旗旖施也。有布列之義。𨸏部曰。敶、列也。然則凡言陳設者、敶之假借字。陳行而敶廢矣。"}]},"護":{"expl":"救視也。从言蒦聲。","rad":"言","fq":"胡故切","vol":"03","py":"hù","duan":[{"e":"救視也。","n":"尚書中𠋫握河紀。堯受河圖。伯禹進迎。舜契陪位。稷辨護。注云。辨護者、供時用相禮儀。周禮注亦云辨護。蕭何世家。數以吏事護高祖。"}]},"瑀":{"expl":"石之似玉者。从玉禹聲。","rad":"玉","fq":"王矩切","vol":"01","py":"yǔ","duan":[{"e":"石之次玉者。","n":"次各本譌似。依詩音義、正義引訂。鄭風傳曰。雜佩者、珩璜琚瑀衝牙之類。又曰。佩有琚瑀。所以納閒。納閒者、納於上珩下璜衝牙之中也。韓詩傳。蠙珠以納其閒。保傅篇曰。玭珠以納其閒。琚瑀以雜之。玭卽蠙。毛不言蠙珠。韓不言琚瑀。保傅篇兼言之。葢蠙珠居中。琚瑀皆美石、又貫於蠙珠之上下。故曰雜佩。雜、集也。集衆美也。盧辨曰。玭珠之赤者曰琚、白者曰瑀。誤矣。"}]},"譞":{"expl":"譞，慧也。从言，圜省聲。","rad":"言","fq":"許緣切","vol":"03","py":"xuān","duan":[{"e":"譞、","n":"此複舉字之未刪者。"}]},"誧":{"expl":"大也。一曰人相助也。从言甫聲。讀若逋。","rad":"言","fq":"博孤切","vol":"03","py":"bū","duan":[{"e":"大也。","n":"廣雅同。"}]},"諰":{"expl":"思之意。从言从思。","rad":"言","fq":"胥里切","vol":"03","py":"xǐ","duan":[{"e":"思之意。","n":"廣韵曰。言且思之。疑古本作言且思之意也。方言而又思之。故其字從言思。意者、䛐下意內言外之意。荀卿曰。諰諰然常恐天下之一合而？己也。漢書諰作鰓。蘇林曰。讀如愼而無禮則葸之葸。鰓、懼皃也。按又作𤟧。又作偲。皆訓懼。與思訓義近。"}]},"託":{"expl":"寄也。从言乇聲。","rad":"言","fq":"他各切","vol":"03","py":"tuō","duan":[{"e":"寄也。","n":"與人部侂音義皆同。"}]},"記":{"expl":"疏也。从言己聲。","rad":"言","fq":"居吏切","vol":"03","py":"jì","duan":[{"e":"疋也。","n":"疋各本作疏。今正。疋部曰。一曰疋、記也。此疋記二字轉注也。疋今字作疏。謂分疏而識之也。廣雅曰。註紀疏記學栞志識也。按晉唐人作註記字。註從言不從水。不與傳注字同。"}]},"譽":{"expl":"（纤）也。从言與聲。","rad":"言","fq":"羊茹切","vol":"03","py":"yù","duan":[{"e":"稱也。","n":"稱當作偁。轉寫失之也。偁、舉也。譽、偁美也。"}]},"譒":{"expl":"𢾭也。从言番聲。《商書》曰：“王譒告之。”","rad":"言","fq":"補過切","vol":"03","py":"bò","duan":[{"e":"𢾭也。","n":"手部播、一曰布也。此與音義同。"}]},"謝":{"expl":"辤去也。从言䠶聲。","rad":"言","fq":"辤夜切","vol":"03","py":"xiè","duan":[{"e":"辤去也。","n":"辤、不受也。曲禮。大夫七十而致事。若不得謝。則必賜之几杖。此謝之本義也。引伸爲凡去之偁。又爲衰退之偁。俗謂拜賜曰謝。"}]},"謳":{"expl":"齊歌也。从言區聲。","rad":"言","fq":"烏侯切","vol":"03","py":"ōu","duan":[{"e":"齊歌也。","n":"師古注高帝紀曰。謳、齊歌也。謂齊聲而歌。或曰齊地之歌。按假令許意齊聲而歌。則當曰衆歌。不曰齊歌也。李善注吳都賦引曹植妾薄相行曰。齊謳楚舞紛紛。太平御覽引古樂志曰。齊歌曰謳。吳歌曰歈。楚歌曰豔。淫歌曰哇。若楚辭吳歈蔡謳、孟子河西善謳、則不限於齊也。"}]},"詠":{"expl":"歌也。从言永聲。","rad":"言","fq":"爲命切","vol":"03","py":"yǒnɡ","duan":[{"e":"歌也。","n":"堯典曰。歌永言。樂記曰。歌之爲言也。長言之也。說之、故言之。言之不足、故長言之。"}]},"玤":{"expl":"石之次玉者。以爲系璧。从玉丰聲。讀若《詩》曰“瓜瓞菶菶”。一曰若𧊧蚌。","rad":"玉","fq":"補蠓切","vol":"01","py":"bànɡ","duan":[{"e":"石之次玉者。㠯爲系璧。","n":"系璧、葢爲小璧系帶閒、縣左右佩物也。"}]},"諍":{"expl":"止也。从言爭聲。","rad":"言","fq":"側迸切","vol":"03","py":"zhènɡ","duan":[{"e":"止也。","n":"經傳通作爭。"}]},"𧦝":{"expl":"召也。从言乎聲。","rad":"言","fq":"荒烏切","vol":"03","py":"hū","duan":[{"e":"召也。","n":"口部曰。召、𧦝也。後人以呼代之。呼行而𧦝廢矣。"}]},"謼":{"expl":"𧦝謼也。从言虖聲。","rad":"言","fq":"荒故切","vol":"03","py":"hū","duan":[{"e":"𧦝也。","n":"依韵會訂。此與口部嘑異義而通用。大雅崔本。式號式謼。"}]},"訖":{"expl":"止也。从言气聲。","rad":"言","fq":"居迄切","vol":"03","py":"qì","duan":[{"e":"止也。","n":"見釋詁。榖梁傳母訖糴。范曰。訖、止也。按孟子謂之遏糴。"}]},"諺":{"expl":"傳言也。从言彥聲。","rad":"言","fq":"魚變切","vol":"03","py":"yàn","duan":[{"e":"傳言也。","n":"諺傳曡韵。傳言者、古語也。古字從十口、識前言。凡經傳所偁之諺。無非前代故訓。而宋人作注乃以俗語俗諭當之。誤矣。玄應引此下有謂傳世常言也。葢庾儼黙注。"}]},"訝":{"expl":"相迎也。从言牙聲。《周禮》曰：“諸侯有卿訝發。”","rad":"言","fq":"吾駕切","vol":"03","py":"yà","duan":[{"e":"相迎也。周禮曰。諸矦有卿訝也。","n":"秋官掌訝職文。惟周禮作訝。他經皆作御。如詩百㒳御之。毛曰。御、迎也。以御田祖。箋云。御、迎也。書予御續乃命于天、弗御克奔、以役西土、御衡不迷、某氏皆訓迎。故衞包遂皆改爲迓。士昏禮媵御、曲禮大夫士必自御之、穀梁傳跛者御跛者、眇者御眇者、列子遇駭鹿御而擊之皆訓迎。則皆訝之同音假借。"}]},"詣":{"expl":"𠋫至也。从言旨聲。","rad":"言","fq":"五計切","vol":"03","py":"yì","duan":[{"e":"𠋫至也。","n":"𠋫至者、節𠋫所至也。致下云。送詣也。凡謹畏精微深造以道而至曰詣。關中記。建章宫有馺娑、駘盪、枍詣、承光四殿。西京、西都賦皆作枍詣。俗作栺誤。"}]},"講":{"expl":"和解也。从言冓聲。","rad":"言","fq":"古項切","vol":"03","py":"jiǎnɡ","duan":[{"e":"和解也。","n":"和當作龢。不合者調龢之、紛糾者解釋之是曰講。易曰。君子以朋友講習。史記虞卿甘茂二傳、漢書項羽傳皆假媾爲講。古音同也。"}]},"謄":{"expl":"迻書也。从言朕聲。","rad":"言","fq":"徒登切","vol":"03","py":"ténɡ","duan":[{"e":"迻書也。","n":"今人猶謂謄寫。"}]},"訒":{"expl":"頓也。从言刃聲。《論語》曰：“其言也訒。”","rad":"言","fq":"而振切","vol":"03","py":"rèn","duan":[{"e":"顿也。","n":"訒顿曡韵。顿之言鈍也。"}]},"玪":{"expl":"玪𤨙，石之次玉者。从玉今聲。","rad":"玉","fq":"古函切","vol":"01","py":"jiān","duan":[{"e":"玪𤨙、","n":"逗。"}]},"訥":{"expl":"言難也。从言从内。","rad":"言","fq":"內骨切","vol":"03","py":"nè","duan":[{"e":"言難也。","n":"與訒義同。與㕯音義皆同。論語。君子欲訥於言而敏於行。苞曰。訥、遟鈍也。"}]},"謯":{"expl":"謯，娽也。从言虘聲。","rad":"言","fq":"側加切","vol":"03","py":"jiē","duan":[{"e":"謯娽也。","n":"廣雅曰。謯、𧨹也。篇、韵皆曰。謯、𧨹也。𧨹、謯也。按許書有娽無𧨹。故仍之。其義則未聞。謯娽當是古語。許當是三字句。"}]},"𧧹":{"expl":"待也。从言伿聲。讀若䭆。","rad":"言","fq":"胡禮切","vol":"03","py":"xì","duan":[{"e":"待也。","n":"小徐曰。此與徯字義相通。"}]},"譥":{"expl":"痛呼也。从言敫聲。","rad":"言","fq":"古弔切","vol":"03","py":"jiào","duan":[{"e":"痛嘑也。","n":"嘑作呼。誤。譥與噭義略同。痛嘑、若顏氏家訓所云北人呼羽罪反之音、南人呼于來反之音也。"}]},"譊":{"expl":"恚呼也。从言堯聲。","rad":"言","fq":"女交切","vol":"03","py":"náo","duan":[{"e":"恚嘑也。从言。堯聲。","n":"女交切。二部。"}]},"謍":{"expl":"小聲也。从言，熒省聲。《詩》曰：“謍謍青蠅。”","rad":"言","fq":"余傾切","vol":"03","py":"yínɡ","duan":[{"e":"小聲也。","n":"小上當奪謍謍二字。謍𧭈、小聲也。"}]},"諎":{"expl":"大聲也。从言昔聲。讀若笮。","rad":"言","fq":"壯革切","vol":"03","py":"zé","duan":[{"e":"大聲也。","n":"爾雅。行扈唶唶。釋文曰。唶、說文云借字也。一云大聲也。按說文人部無借字。據陸則此大聲也之上今奪五字。但借字也三字語不完。且陸不分疏云唶、說文作諎。今未敢輒補。要陸所據爲善本。許書叚下曰。借也。耤下曰。古者使民如借。序目曰。六曰假借。人部未必無借字。而諎唶可以爲借字。固非無徵矣。借、資昔資夜二切。孔沖遠曰。假借字、在取者則假讀上聲借讀入聲。在與者、則皆讀去聲。聲類曰。嚄大笑。唶大呼。考工記侈則柞注。柞讀爲咋咋然之咋。聲大外也。按咋咋、諎諎同。皆大聲。"}]},"諛":{"expl":"諂也。从言㬰聲。","rad":"言","fq":"羊朱切","vol":"03","py":"yú","duan":[{"e":"讇也。","n":"諛者所以爲讇。故渾言之。"}]},"讇":{"expl":"諛也。从言閻聲。","rad":"言","fq":"丑𤥎切","vol":"03","py":"chǎn","duan":[{"e":"諛也。","n":"讇者未有不諛。"}]},"諼":{"expl":"詐也。从言爰聲。","rad":"言","fq":"況袁切","vol":"03","py":"xuān","duan":[{"e":"詐也。","n":"公羊傳。此伐楚也。其言救江何。爲諼也。何曰。諼、詐也。息夫躳傳。虚造詐諼之策。按師古注云。諼、詐辭也。辭當是䛐。此葢小顏所據說文作詐䛐也。淺人刪䛐耳。衞風。終不可諼兮、傳曰。諼、忘也。此諼葢藼之假借。藼本令人忘憂之艸。引伸之凡忘皆曰藼。伯兮詩作諼艸。淇奥詩作不可諼。皆假借也。許偁安得藼艸。葢三家詩也。"}]},"𤨙":{"expl":"玪𤨙也。从玉勒聲。","rad":"玉","fq":"盧則切","vol":"01","py":"lè","duan":[{"e":"玪𤨙也。从王。勒聲。","n":"盧則切。一部。"}]},"謷":{"expl":"不肖人也。从言敖聲。一曰哭不止，悲聲謷謷。","rad":"言","fq":"五牢切","vol":"03","py":"áo","duan":[{"e":"不省人言也。","n":"省各本作肖。今正。言字依韵會補。詩板。我卽爾謀。聽我囂囂。傳曰。囂囂猶謷謷也。箋云。女聽我言謷謷然不肎受。玉篇聱字下引廣雅。不入人語也。聱卽謷之俗。廣韵六豪曰。謷、不省人也。奪言字。五肴曰。謷、不肖也。則依誤本說文而又少二字。東方朔傳。聲謷謷。亦正謂其不省人言耳。此條得諸鈕非石。又按釋訓曰。囂囂、傲也。囂囂卽謷謷之叚借。"}]},"訹":{"expl":"誘也。从言术聲。","rad":"言","fq":"思律切","vol":"03","py":"xù","duan":[{"e":"誘也。","n":"按晉語。里克、㔻鄭告公子重耳曰。子盇入乎。吾請爲子鉥。此假鉥爲訹也。服鳥賦。怵迫之徒兮或趨西東。孟康曰。怵、爲利所誘怵然。此假怵爲訹也。"}]},"詑":{"expl":"沇州謂欺曰詑。从言它聲。","rad":"言","fq":"託何切","vol":"03","py":"tuó","duan":[{"e":"沇州謂欺曰詑。","n":"此不見於方言。方言。秦謂之謾。郭云。言謾詑。詑音大和切。按戰國策曰。寡人正不喜詑者言也。"}]},"謾":{"expl":"欺也。从言曼聲。","rad":"言","fq":"母官切","vol":"03","py":"mán","duan":[{"e":"欺也。","n":"宣帝詔欺謾。季布傳面謾。韋注漢書云。謾、相抵讕也。"}]},"譇":{"expl":"譇拏，羞窮也。从言奢聲。","rad":"言","fq":"陟加切","vol":"03","py":"zhā","duan":[{"e":"譇拏、","n":"逗。曡韵字。"}]},"𧧻":{"expl":"慙語也。从言作聲。","rad":"言","fq":"鉏駕切","vol":"03","py":"zhà","duan":[{"e":"慙語也。","n":"與心部怍音同義近。論語。其言之不怍。則爲之也難。當作此𧧻。"}]},"謺":{"expl":"謺讘也。从言執聲。","rad":"言","fq":"之涉切","vol":"03","py":"zhé","duan":[{"e":"謺讘也。","n":"謺讘當是曡韵雙字。但不類列。而讘在後謓字下。葢後人亂之。"}]},"謰":{"expl":"謰謱也。从言連聲。","rad":"言","fq":"力延切","vol":"03","py":"lián","duan":[{"e":"謰謱也。","n":"方言。㘓哰謰謱拏也。東齊周晉之鄙曰㘓哰。㘓哰亦通語也。南楚曰謰謱。或謂之支註。或謂之詀謕。按譇拏、謰謱皆雙聲。"}]},"謱":{"expl":"謰謱也。从言婁聲。","rad":"言","fq":"陟侯切","vol":"03","py":"lóu","duan":[{"e":"謰謱也。从言。婁聲。","n":"洛矦切。四部。"}]},"詒":{"expl":"相欺詒也。一曰遺也。从言台聲。","rad":"言","fq":"與之切","vol":"03","py":"yí","duan":[{"e":"相欺詒也。","n":"金縢。公乃爲詩以詒王。名之曰鴟鴞。鄭曰。詒、說也。周公恐其屬黨將死。恐其㓝濫。又破其家。而不敢正言。故作鴟鴞之詩以詒王。按尚書字本作詒。鄭注說當讀輸芮切。正義改爲怡悅字。誤矣。周公善辭以誘王。故史臣目之曰詒。此鄭意也。穀梁傳曰。夫請者、非可詒託而往也。必親之者也。注。詒託、猶假寄。列子。狎侮欺詒。郭注方言云。汝南人呼欺亦曰詒。音殆。史、漢多假紿爲之。"}]},"禠":{"expl":"福也。从示虒聲。","rad":"示","fq":"息移切","vol":"01","py":"sī","duan":[{"e":"福也。","n":"見釋詁。張衡東京賦曰。祈禠禳災。"}]},"琚":{"expl":"瓊琚。从玉居聲。《詩》曰：“報之以瓊琚。”","rad":"玉","fq":"九魚切","vol":"01","py":"jū","duan":[{"e":"佩玉石也。","n":"各本作瓊琚也。今正。詩鄭風正義、釋文皆引說文。琚、佩玉名。衞風釋文又引琚、佩玉名。按雜佩謂之佩玉。見周禮、大戴禮玉藻、詩鄭風秦風衞風、尙書大傳。贅以名字。語不可通。琚乃佩玉之一物。不得云佩玉名也。毛公、大戴皆云。琚瑀以納閒。許君以瑀字廁於石次玉之類。然則名字爲石之字誤無疑。佩玉石者、謂佩玉納閒之石也。木瓜毛傳云。琚、佩玉石也。許君用之。今毛傳石譌爲名。莫能是正。瑀下不言佩玉石。琚下不言美石次玉。互見也。詩。佩玉瓊琚。謂佩玉之閒有美琚也。瓊瑰玉佩。謂美瑰在玉佩之閒也。"}]},"謲":{"expl":"相怒使也。从言參聲。","rad":"言","fq":"倉南切","vol":"03","py":"càn","duan":[{"e":"相怒使也。从言。參聲。","n":"倉南切。七部。玉篇干紺切。"}]},"誑":{"expl":"欺也。从言狂聲。","rad":"言","fq":"居況切","vol":"03","py":"kuánɡ","duan":[{"e":"欺也。从言。𢚇聲。","n":"居況切。十部。"}]},"譺":{"expl":"騃也。从言疑聲。","rad":"言","fq":"五介切","vol":"03","py":"ài","duan":[{"e":"騃也。","n":"騃、馬行仡仡也。此騃之本義也。方言。癡、騃也。騃吾駭反。此騃之别義也。廣雅。譺、調也。謂相嘲調。通俗文。大調曰譺。按大相嘲調者如癡騃然也。"}]},"𧬮":{"expl":"相誤也。从言𥈀聲。","rad":"言","fq":"古罵切","vol":"03","py":"ɡuà","duan":[{"e":"相誤也。","n":"廣韵。相𧬮誤也。𧬮誤葢同詿誤。"}]},"訕":{"expl":"𧩂也。从言山聲。","rad":"言","fq":"所晏切","vol":"03","py":"shàn","duan":[{"e":"謗也。","n":"論語。惡居下而訕上者。訕與女部姗、誹也音義同。"}]},"譏":{"expl":"誹也。从言幾聲。","rad":"言","fq":"居衣切","vol":"03","py":"jī","duan":[{"e":"誹也。","n":"譏誹曡韵。譏之言微也。以微言相摩切也。引伸爲關市譏而不征之譏。"}]},"誣":{"expl":"加也。从言巫聲。","rad":"言","fq":"武扶切","vol":"03","py":"wū","duan":[{"e":"加也。","n":"玄應五引皆作加言。加言者架言也。古無架字。以加爲之。淮南時則訓。鵲加巢。加巢者、架巢也。毛詩箋曰。鵲之作巢。冬至加之。劉昌宗加音架。李善引呂氏春秋注曰。結、交也。構、架也。云加言者、謂憑空構架聽者所當審愼也。按力部曰。加、語相增加也。從力口。然則加與誣同義互訓。可不增言字。加與誣皆兼毁譽言之。毁譽不以實皆曰誣也。方言。誣䛳與也。吳越曰誣。荆楚曰䛳與。猶齊晉言阿與。表記。受禒不誣。注曰。於事不信曰誣。"}]},"誹":{"expl":"𧩂也。从言非聲。","rad":"言","fq":"敷尾切","vol":"03","py":"fěi","duan":[{"e":"謗也。","n":"誹之言非也言非其實。"}]},"謗":{"expl":"毀也。从言㫄聲。","rad":"言","fq":"補浪切","vol":"03","py":"bànɡ","duan":[{"e":"毁也。","n":"謗之言旁也。旁、溥也。大言之過其實。諭語。子貢方人。假方爲謗。"}]},"譸":{"expl":"詶也。从言壽聲。讀若醻。《周書》曰：“無或譸張爲幻。”","rad":"言","fq":"張流切","vol":"03","py":"zhōu","duan":[{"e":"詶也。","n":"按詶、詛也。則譸亦詛也。"}]},"璓":{"expl":"石之次玉者。从玉莠聲。《詩》曰：“充耳璓瑩。”","rad":"玉","fq":"息救切","vol":"01","py":"xiù","duan":[{"e":"石之次玉者。","n":"衞風充耳琇瑩傳。琇、瑩、美石也。按琇、瑩是二石名。故都人士傳曰。琇、美石也。著傳曰。瑩、石似玉也。"}]},"詶":{"expl":"譸也。从言州聲。","rad":"言","fq":"市流切","vol":"03","py":"chóu","duan":[{"e":"詛也。","n":"玉篇云。說文職又切。詛也。玄應六引曰。祝今作呪。說文作詶。詛也。之授切。今各本作譸也。乃因俗用詶爲酬應字、市流切。不欲釋以詛。遂改之耳。詶訓以言荅之。而詶詛作呪。此古今之變也。若經典則通用祝不用詶。左傳。雖其善祝。豈能勝億兆人之詛。此祝詛分言也。大雅。矦作矦祝傳云。作祝祖也。此祝讀呪。祝詛不分也。"}]},"詛":{"expl":"詶也。从言且聲。","rad":"言","fq":"莊助切","vol":"03","py":"zǔ","duan":[{"e":"詶也。从言。且聲。","n":"荘助切。五部。"}]},"䛆":{"expl":"詶也。从言由聲。","rad":"言","fq":"直又切","vol":"03","py":"zhòu","duan":[{"e":"詶也。","n":"祝？字亦作䄂。葢與䛆一字也。"}]},"誃":{"expl":"離別也。从言多聲。讀若《論語》“跢予之足”。周景王作洛陽誃臺。","rad":"言","fq":"尺氏切","vol":"03","py":"chǐ","duan":[{"e":"離别也。","n":"釋言曰。斯誃離也。郭云。誃見詩。今毛詩未見誃字。疑析薪扡矣、容有作誃者。别兵列切。"}]},"誖":{"expl":"亂也。从言孛聲。","rad":"言","fq":"蒲沒切","vol":"03","py":"bèi","duan":[{"e":"亂也。从言。孛聲。","n":"蒲没切。十五部。"}]},"䜌":{"expl":"亂也。一曰治也。一曰不絕也。从言、絲。","rad":"言","fq":"呂員切","vol":"03","py":"luán","duan":[{"e":"亂也。一曰治也。","n":"與爪部𤔔、乙部亂音義皆同。"}]},"誤":{"expl":"謬也。从言吳聲。","rad":"言","fq":"五故切","vol":"03","py":"wù","duan":[{"e":"謬也。","n":"按謬當作繆。古繆誤字從糸。如綢繆相戾也。大傳五者一物紕繆是。謬訓狂者妄言、與誤義隔。"}]},"詿":{"expl":"誤也。从言圭聲。","rad":"言","fq":"古賣切","vol":"03","py":"ɡuà","duan":[{"e":"誤也。","n":"詿謂有所挂牽而然也。史記吳王濞傳。詿亂天下。漢書。景帝詔曰。吳王濞爲逆。詿誤吏民。"}]},"誒":{"expl":"可惡之辭。从言矣聲。一曰誒然。《春秋傳》曰：“誒誒出出。”","rad":"言","fq":"許其切","vol":"03","py":"xī","duan":[{"e":"可惡之䛐。","n":"䛐各本作辭。誤。今正䛐者、意內而言外也。韋孟詩。勤唉厥生、漢書唉作誒。師古曰。誒歎聲。項羽本紀索隱曰。唉、歎恨發聲之䛐。皆與許此義合。"}]},"譆":{"expl":"痛也。从言喜聲。","rad":"言","fq":"火衣切","vol":"03","py":"xī","duan":[{"e":"痛也。","n":"當作痛聲。左傳。或叫于宋大廟曰。譆譆岀岀。鳥鳴于亳社。如曰譆譆。甲午宋大災。按譆與熹同音。故云痛聲。"}]},"玖":{"expl":"石之次玉黑色者。从玉久聲。《詩》曰：“貽我佩玖。”讀若芑。或曰若人句脊之句。","rad":"玉","fq":"舉友切","vol":"01","py":"jiǔ","duan":[{"e":"石之次玉黑色者。","n":"詩木瓜傳曰。玖、玉名。𠀌中有麻傳曰。玖、石次玉者。按不應同物異訓。葢木瓜傳本作玉石。漢書西域傳。于闐國多玉石。注曰。玉石、石之似玉者也。楊雄蜀都賦亦言玉石。轉寫石譌名耳。玖音近黝。故訓黑色。"}]},"詯":{"expl":"膽气滿聲在人上。从言自聲。讀若反目相睞。","rad":"言","fq":"荒內切","vol":"03","py":"huì","duan":[{"e":"膽气滿聲在人上。从言。自聲。","n":"葢卽元曲所用咱字。"}]},"謧":{"expl":"謧詍，多言也。从言离聲。","rad":"言","fq":"呂之切","vol":"03","py":"lí","duan":[{"e":"謧詍、","n":"逗。"}]},"詍":{"expl":"多言也。从言世聲。《詩》曰：“無然詍詍 。”","rad":"言","fq":"余制切","vol":"03","py":"yì","duan":[{"e":"多言也。","n":"與口部呭音義皆同。"}]},"訾":{"expl":"不思稱意也。从言此聲。《詩》曰：“翕翕訿訿。”","rad":"言","fq":"將此切","vol":"03","py":"zǐ","duan":[{"e":"訾訾、","n":"逗。二字今補。"}]},"䛬":{"expl":"往來言也。一曰小兒未能正言也。一曰祝也。从言匋聲。","rad":"言","fq":"大牢切","vol":"03","py":"táo","duan":[{"e":"往來言也。一曰小兒未能正言也。一曰祝也。从言。匋聲。","n":"大牢切。古音在三部。"}]},"𧧛":{"expl":"𧧛𧧛，多語也。从言冄聲。樂浪有𧧛邯縣。","rad":"言","fq":"汝閻切","vol":"03","py":"nán","duan":[{"e":"䛁䛁、","n":"逗。"}]},"䜚":{"expl":"語相反䜚也。从言遝聲。","rad":"言","fq":"他合切","vol":"03","py":"tà","duan":[{"e":"䜚誻、","n":"逗。"}]},"誻":{"expl":"䜚誻也。从言沓聲。","rad":"言","fq":"徒合切","vol":"03","py":"tà","duan":[{"e":"䜚誻也。","n":"與曰部沓字音義皆同。荀卿書。愚者之言。誻誻然而沸。注。誻誻、多言也。"}]},"詽":{"expl":"諍語詽詽也。从言幵聲。","rad":"言","fq":"呼堅切","vol":"03","py":"yán","duan":[{"e":"諍語訮訮也。","n":"劉祥言事。蒙遜曰。汝聞劉裕入關。敢研研然也。斬之。魏書作妍妍。皆訮訮之同音也。匡謬正俗所謂殿研卽此。"}]},"讗":{"expl":"言壯㒵。一曰數相怒也。从言巂聲。讀若畫。","rad":"言","fq":"呼麥切","vol":"03","py":"xié","duan":[{"e":"言壯皃。一曰數相怒也。从言。巂聲。讀若畫。","n":"呼麥切。十六部。"}]},"㺿":{"expl":"石之似玉者。从玉𦣞聲。讀若貽。","rad":"玉","fq":"與之切","vol":"01","py":"yí","duan":[{"e":"石之似玉者。","n":"似、玉篇作次。又引倉頡云五色石也。"}]},"訇":{"expl":"騃言聲。从言，勻省聲。漢中西城有訇鄉。又讀若玄。","rad":"言","fq":"虎橫切","vol":"03","py":"hōnɡ","duan":[{"e":"駭言聲。","n":"駭各本作騃。依韵會訂。此本義也。引伸爲匉訇大聲。"}]},"諞":{"expl":"便巧言也。从言扁聲。《周書》曰：“𢧵𢧵善諞言。”《論語》曰：“友諞佞。”","rad":"言","fq":"部田切","vol":"03","py":"piǎn","duan":[{"e":"便巧言也。","n":"諞便曡韵。"}]},"𧭹":{"expl":"匹也。从言頻聲。","rad":"言","fq":"符眞切","vol":"03","py":"pín","duan":[{"e":"匹也。","n":"於曡韵釋之。"}]},"𧥣":{"expl":"扣也。如求婦先𧥣叕之。从言从口，口亦聲。","rad":"言","fq":"苦后切","vol":"03","py":"kòu","duan":[{"e":"扣也。","n":"扣叩古今字。說文有敂無叩。此扣當作敂。"}]},"誽":{"expl":"言相誽司也。从言兒聲。","rad":"言","fq":"女家切","vol":"03","py":"nì","duan":[{"e":"言相誽司也。","n":"誽司猶刺探。誽之言惹也。司之言伺也。"}]},"誂":{"expl":"相呼誘也。从言兆聲。","rad":"言","fq":"徒了切","vol":"03","py":"tiǎo","duan":[{"e":"相𧦝誘也。","n":"戰國策。楚人有㒳妻。人誂其長者。長者詈之。誂其少者。少者許之。史記吳王濞傳。使中大夫應高誂膠西王。按後人多用挑字。"}]},"譄":{"expl":"加也。从言，从曾聲。","rad":"言","fq":"作滕切","vol":"03","py":"zēnɡ","duan":[{"e":"加也。","n":"加下曰。語相譄加也。按譄加誣三字互訓。"}]},"詄":{"expl":"忘也。从言失聲。","rad":"言","fq":"徒結切","vol":"03","py":"dié","duan":[{"e":"忘也。","n":"廣雅。誤也。"}]},"諅":{"expl":"忌也。从言其聲。《周書》曰：“上不諅于凶德。”","rad":"言","fq":"渠記切","vol":"03","py":"jì","duan":[{"e":"忌也。","n":"廣韵七之曰。謀也。七志曰。志也。"}]},"譀":{"expl":"誕也。从言敢聲。","rad":"言","fq":"下闞切","vol":"03","py":"hàn","duan":[{"e":"誕也。","n":"東觀漢記曰。雖誇譀猶令人熱。按誕也當作誇也。譀與誇互訓。"}]},"珢":{"expl":"石之似玉者。从玉艮聲。","rad":"玉","fq":"語巾切","vol":"01","py":"yín","duan":[{"e":"石之似玉者。从王。艮聲。","n":"語巾切。古音在十三部。"}]},"誇":{"expl":"譀也。从言夸聲。","rad":"言","fq":"苦瓜切","vol":"03","py":"kuā","duan":[{"e":"譀也。从言。夸聲。","n":"苦𤓰切。古音在五部。"}]},"誕":{"expl":"詞誕也。从言延聲。","rad":"言","fq":"徒旱切","vol":"03","py":"dàn","duan":[{"e":"䛐誕也。","n":"此三字葢有誤。釋詁、毛傳皆云。誕、大也。"}]},"䜕":{"expl":"譀也。从言萬聲。","rad":"言","fq":"莫話切","vol":"03","py":"mài","duan":[{"e":"譀也。从言。萬聲。","n":"莫話切。十五部。"}]},"謔":{"expl":"戲也。从言虐聲。《詩》曰：“善戲謔兮。”","rad":"言","fq":"虚約切","vol":"03","py":"xuè","duan":[{"e":"戲也。从言。虐聲。","n":"虚約切。古音在二部。"}]},"詪":{"expl":"眼戾也。从言𥃩聲。","rad":"言","fq":"乎懇切","vol":"03","py":"hěn","duan":[{"e":"很戾也。","n":"廣韵難語皃。"}]},"訌":{"expl":"䜋也。从言工聲。《詩》曰：“蟊賊内訌。”","rad":"言","fq":"戶工切","vol":"03","py":"hònɡ","duan":[{"e":"䜋也。","n":"大雅召旻傳曰。訌潰也。抑傳曰。虹、潰也。虹者訌之假借字。釋言。虹、潰也。亦作訌。郭云。謂潰敗。按許作䜋者、許以䜋與潰同也。詩。彼童而角。實虹小子。天降罪罟。蟊賊。內訌。皆謂禍由中岀。與中止之義合。"}]},"䜋":{"expl":"中止也。从言貴聲。《司馬法》曰：“師多則人䜋。”䜋，止也。","rad":"言","fq":"胡對切","vol":"03","py":"huì","duan":[{"e":"中止也。","n":"中止者自中而止。猶云內亂。魏都賦李注引說文。䜋列、中止也。此依賦文衍列字。賦云。齊被練而銛戈。襲偏裻以䜋列。非中止之訓也。"}]},"𧬨":{"expl":"聲也。从言歲聲。《詩》曰：“有𧬨其聲。”","rad":"言","fq":"呼會切","vol":"03","py":"huì","duan":[{"e":"聲也。","n":"廣韵。衆聲。"}]},"諣":{"expl":"疾言也。从言咼聲。","rad":"言","fq":"呼卦切","vol":"03","py":"huà","duan":[{"e":"疾言也。从言。咼聲。","n":"呼卦切。古音在十七部。"}]},"𧮓":{"expl":"譟也。从言魋聲。","rad":"言","fq":"杜回切","vol":"03","py":"tuí","duan":[{"e":"譟也。从言。魋聲。","n":"杜回切。十五部。按許書無魋字。大徐據此補入鬼部。"}]},"𤤺":{"expl":"石之似玉者。从玉曳聲。","rad":"玉","fq":"余制切","vol":"01","py":"yì","duan":[{"e":"石之似玉者。从王。曳聲。","n":"余制切。古音在十六部。曳从𦥔。以象抴引之。丿爲聲。按玉篇、廣韻皆兼有𤤺𤧙字。訓釋同。𤧙音臾。必有一誤。"}]},"譟":{"expl":"擾也。从言喿聲。","rad":"言","fq":"蘇到切","vol":"03","py":"zào","duan":[{"e":"擾也。","n":"手部曰。擾、煩也。"}]},"訆":{"expl":"大呼也。从言丩聲。《春秋傳》曰：“或訆于宋大廟。”","rad":"言","fq":"古弔切","vol":"03","py":"jiào","duan":[{"e":"大嘑也。","n":"與㗊部嘂、口部叫音義皆同。"}]},"諕":{"expl":"號也。从言从虎。","rad":"言","fq":"乎刀切","vol":"03","py":"háo","duan":[{"e":"號也。从言虎。","n":"此與号部號音義皆同。口部唬從口虎。亦讀若暠。凡嘑號之聲。虎爲冣猛。故皆從虎會意。乎刀切。二部。"}]},"讙":{"expl":"譁也。从言雚聲。","rad":"言","fq":"呼官切","vol":"03","py":"huān","duan":[{"e":"譁也。从言。雚聲。","n":"呼官切。十四部。"}]},"譁":{"expl":"讙也。从言華聲。","rad":"言","fq":"呼瓜切","vol":"03","py":"huā","duan":[{"e":"讙也。从言。䔢聲。","n":"呼𤓰切。古音在五部。"}]},"謣":{"expl":"妄言也。从言雩聲。","rad":"言","fq":"羽俱切","vol":"03","py":"yú","duan":[{"e":"妄言也。从言。雩聲。","n":"羽俱切。五部。"}]},"譌":{"expl":"譌言也。从言爲聲。《詩》曰：“民之譌言。”","rad":"言","fq":"五禾切","vol":"03","py":"é","duan":[{"e":"譌言也。","n":"疑當作僞言也。唐風。人之爲言。定本作僞言。箋云。爲、人爲善言以稱薦之。欲使見進用也。小雅。民之訛言。箋云。訛、僞也。人以僞言相陷入。按爲僞譌古同。通用。尚書南譌。周禮注、漢書皆作南僞。"}]},"謬":{"expl":"狂者之妄言也。从言翏聲。","rad":"言","fq":"靡幼切","vol":"03","py":"miù","duan":[{"e":"狂者之妄言也。","n":"古差繆多用從糸之字。與此謬義别。"}]},"璅":{"expl":"石之似玉者。从玉巢聲。","rad":"玉","fq":"子浩切","vol":"01","py":"zǎo","duan":[{"e":"石之似玉者。从王。巢聲。","n":"子晧切。二部。"}]},"詤":{"expl":"夢言也。从言巟聲。","rad":"言","fq":"呼光切","vol":"03","py":"huǎnɡ","duan":[{"e":"夢言也。","n":"夕部曰。夢、不明也。吕覽。無由接而言見？。高曰。？讀爲誣妄之誣。按讀？爲誣者、正如亡無通用。荒幠通用也。"}]},"謈":{"expl":"大呼自勉也。从言，暴省聲。","rad":"言","fq":"蒲角切","vol":"03","py":"bó","duan":[{"e":"大嘑自冤也。","n":"冤各本作勉。今依廣韵正。東方朔傳。舍人不勝痛。呼謈。鄧展曰。謈音𤓰瓝之瓝。按自冤者、自稱己冤枉也。田蚡疾。一身盡痛。若有擊者。謼服謝罪。晉灼曰。服音瓝。關西俗謂得杖呼及小兒啼呼爲呼瓝。然則謈亦作服、作瓝也。朔傳呼字亦音髐。蚡傳謼字亦音火交反。皆與下一字曡韵。廣韵曰嗃謈、大呼也是也。謈古音讀如匏。"}]},"訬":{"expl":"訬，擾也。一曰訬，獪。从言少聲。讀若毚。","rad":"言","fq":"楚交切","vol":"03","py":"chāo","duan":[{"e":"訬、","n":"此複舉字刪之未盡者。"}]},"諆":{"expl":"欺也。从言其聲。","rad":"言","fq":"去其切","vol":"03","py":"qī","duan":[{"e":"欺也。","n":"諆欺曡韵。小徐引漢書詆諆。然漢書自作詆欺也。"}]},"譎":{"expl":"權詐也。益、梁曰謬欺，天下曰譎。从言矞聲。","rad":"言","fq":"古穴切","vol":"03","py":"jué","duan":[{"e":"權詐也。益梁曰謬。欺天下曰譎。","n":"方言。膠譎詐也。涼州西南之閒曰膠。自關而東西或曰譎。或曰膠。詐、通語也。按廣雅及爾雅釋文引方言皆有謬字。此欺天下曰譎不可通。當爲關東西曰譎。"}]},"詐":{"expl":"欺也。从言乍聲。","rad":"言","fq":"側駕切","vol":"03","py":"zhà","duan":[{"e":"欺也。从言。𠆦聲。","n":"測駕切。古五部。"}]},"訏":{"expl":"詭譌也。从言于聲。一曰訏，𧪰。齊、楚謂信曰訏。","rad":"言","fq":"況于切","vol":"03","py":"xū","duan":[{"e":"詭譌也。从言。于聲。","n":"況于切。五部。"}]},"𧪘":{"expl":"咨也。一曰痛惜也。从言差聲。","rad":"言","fq":"子邪切","vol":"03","py":"jiē","duan":[{"e":"嗞也。","n":"口部曰。嗞、𦎍也。此云𦎍、嗞也。是爲異部互訓。各本改作咨者、淺人爲之耳。謀事曰咨。義不相涉。"}]},"讋":{"expl":"失气言。一曰不止也。从言，龖省聲。傅毅讀若慴。","rad":"言","fq":"之涉切","vol":"03","py":"zhé","duan":[{"e":"失气言。","n":"此與慴音義同。此从言、故釋之曰失气言。東都賦。陸讋水慄。"}]},"謵":{"expl":"言謵讋也。从言習聲。","rad":"言","fq":"秦入切","vol":"03","py":"xí","duan":[{"e":"言謵讋也。","n":"疑上文失气言之上當有謵讋二字。曡韵字也。"}]},"璡":{"expl":"石之似玉者。从玉進聲。讀若津。","rad":"玉","fq":"將鄰切","vol":"01","py":"jīn","duan":[{"e":"石之似玉者。从王。進聲。讀若津。","n":"將鄰切。十二部。"}]},"䛩":{"expl":"相毀也。从言亞聲。一曰畏亞。","rad":"言","fq":"宛古切","vol":"03","py":"wù","duan":[{"e":"相毁也。从言。亞聲。","n":"宛古切。五部。"}]},"䜐":{"expl":"相毀也。从言，隨省聲。","rad":"言","fq":"雖遂切","vol":"03","py":"huī","duan":[{"e":"相毁也。从言。隋聲。","n":"雖遂切。古音在十七部。篇、韵皆虚規切。"}]},"𧮑":{"expl":"嗑也。从言闒聲。","rad":"言","fq":"徒盍切","vol":"03","py":"tà","duan":[{"e":"嗑也。","n":"口部曰。嗑、多言也。玉篇曰。𧮑𧪞、多言也。𧮑𧪞卽𧮑嗑。"}]},"詾":{"expl":"說也。从言匈聲。","rad":"言","fq":"許容切","vol":"03","py":"xiōnɡ","duan":[{"e":"訟也。","n":"訟各本譌說。今依篇、韵及六書故所據唐本正。爾雅釋言、小雅魯頌傳箋皆云。訩、訟也。按下文糸之云訟爭也。說文之通例如是。"}]},"訟":{"expl":"爭也。从言公聲。曰：謌訟。","rad":"言","fq":"似用切","vol":"03","py":"sònɡ","duan":[{"e":"爭也。","n":"公言之也。漢書吕后紀。未敢訟言誅之。鄧展曰。訟言、公言也。"}]},"謓":{"expl":"恚也。从言眞聲。賈侍中說：謓，笑。一曰讀若振。","rad":"言","fq":"昌眞切","vol":"03","py":"chēn","duan":[{"e":"恚也。","n":"今人用嗔。古用謓。"}]},"讘":{"expl":"多言也。从言聶聲。河東有狐讘縣。","rad":"言","fq":"之涉切","vol":"03","py":"niè","duan":[{"e":"多言也。从言。聶聲。","n":"之涉切。七部。"}]},"訶":{"expl":"大言而怒也。从言可聲。","rad":"言","fq":"虎何切","vol":"03","py":"hē","duan":[{"e":"大言而怒也。从言。可聲。","n":"虎何切。十七部。"}]},"𧧰":{"expl":"訐也。从言臣聲。讀若指。","rad":"言","fq":"職雉切","vol":"03","py":"zhǐ","duan":[{"e":"訐也。","n":"訐或作許。誤。"}]},"訐":{"expl":"面相厈罪，相告訐也。从言干聲。","rad":"言","fq":"居謁切","vol":"03","py":"jié","duan":[{"e":"面相厈罪告訐也。","n":"依韵會訂。論語。惡訐以爲直者。"}]},"㻸":{"expl":"石之似玉者。从玉朁聲。","rad":"玉","fq":"側岑切","vol":"01","py":"zēn","duan":[{"e":"石之似玉者。从王。朁聲。","n":"側岑切。七部。"}]},"訴":{"expl":"告也。从言，厈省聲。《論語》曰：“訴子路於季孫。”","rad":"言","fq":"桑故切","vol":"03","py":"sù","duan":[{"e":"告也。从言。㡿聲。","n":"桑故切。五部。凡從㡿之字隷變爲厈。俗又譌斥。"}]},"譖":{"expl":"愬也。从言朁聲。","rad":"言","fq":"莊蔭切","vol":"03","py":"zèn","duan":[{"e":"愬也。","n":"論語𧮂愬析言之。此統言之。"}]},"讒":{"expl":"譖也。从言毚聲。","rad":"言","fq":"士咸切","vol":"03","py":"chán","duan":[{"e":"𧮂也。从言。毚聲。","n":"士咸切。八部。"}]},"譴":{"expl":"謫問也。从言遣聲。","rad":"言","fq":"去戰切","vol":"03","py":"qiǎn","duan":[{"e":"謫問也。从言。遣聲。","n":"去戰切。十四部。"}]},"謫":{"expl":"罰也。从言啻聲。","rad":"言","fq":"陟革切","vol":"03","py":"zhé","duan":[{"e":"罰也。从言。啻聲。","n":"陟革切。十六部。"}]},"諯":{"expl":"數也。一曰相讓也。从言耑聲。讀若專。","rad":"言","fq":"尺絹切","vol":"03","py":"zhuān","duan":[{"e":"數也。","n":"謂數責也。今音讀上聲。"}]},"讓":{"expl":"相責讓。从言襄聲。","rad":"言","fq":"人漾切","vol":"03","py":"rànɡ","duan":[{"e":"相責讓。","n":"經傳多以爲謙攘字。"}]},"譙":{"expl":"嬈譊也。从言焦聲。讀若嚼。","rad":"言","fq":"才肖切","vol":"03","py":"qiào","duan":[{"e":"嬈譊也。","n":"嬈、擾戲弄也。譊、恚嘑也。方言。譙、讓也。齊楚宋衞荆陳之閒曰譙。自關而西秦晉之閒凡言相責讓曰譙讓。"}]},"𧧒":{"expl":"數諫也。从言朿聲。","rad":"言","fq":"七賜切","vol":"03","py":"cì","duan":[{"e":"數諫也。","n":"謂數其失而諫之。凡譏刺字當用此。"}]},"誶":{"expl":"讓也。从言卒聲。《國語》曰：“誶申胥。”","rad":"言","fq":"雖遂切","vol":"03","py":"suì","duan":[{"e":"讓也。","n":"釋詁、毛傳皆云。誶、告也。許云。讓也。釋詁、毛傳泛言之。許專言之也。"}]},"璁":{"expl":"石之似玉者。从玉悤聲。讀若蔥。","rad":"玉","fq":"倉紅切","vol":"01","py":"cōnɡ","duan":[{"e":"石之似玉者。从王。悤聲。讀若蔥。","n":"倉紅切。九部。"}]},"詰":{"expl":"問也。从言吉聲。","rad":"言","fq":"去吉切","vol":"03","py":"jié","duan":[{"e":"問也。从言。吉聲。","n":"去吉切。十二部。"}]},"𧫢":{"expl":"責望也。从言望聲。","rad":"言","fq":"巫放切","vol":"03","py":"wànɡ","duan":[{"e":"責望也。","n":"太玄。宼⿰言𦣠其戸。范曰。⿰言𦣠、責也。按朢之古文作𦣠。故𧭅之古文亦作⿰言𦣠。"}]},"詭":{"expl":"責也。从言危聲。","rad":"言","fq":"過委切","vol":"03","py":"ɡuǐ","duan":[{"e":"責也。","n":"漢書。況自詭滅賊。孔融表云。昔賈誼求試屬國。詭係單于。"}]},"證":{"expl":"告也。从言登聲。","rad":"言","fq":"諸應切","vol":"03","py":"zhènɡ","duan":[{"e":"告也。从言。登聲。","n":"諸應切。六部。今人爲證驗字。"}]},"詘":{"expl":"詰詘也。一曰屈襞。从言出聲。","rad":"言","fq":"區勿切","vol":"03","py":"qū","duan":[{"e":"詰詘也。","n":"二字雙聲。屈曲之意。"}]},"𧧁":{"expl":"尉也。从言夗聲。","rad":"言","fq":"於願切","vol":"03","py":"yuǎn","duan":[{"e":"尉也。","n":"尉各本作慰。而集韵、類篇及葉石君抄本說文皆作尉。則知大徐本作尉也。火部曰尉者、從上案下也。䛄訓尉。未得其證。攷毛詩凱風傳。慰、安也。車舝傳曰。慰、怨也。二傳不同。車舝傳一本作尉、安也。陸氏德明從怨。謂作安乃馬融義。今按此毛詩及傳正當作尉、䛄也。爲許所本。後人以易識之字易之耳。䛄者、以善言案其心。如火申繒然。䛄尉雙聲。"}]},"詗":{"expl":"知處告言之。从言冋聲。","rad":"言","fq":"朽正切","vol":"03","py":"xiònɡ","duan":[{"e":"知処告言之。","n":"史、漢淮南傳。王愛陵。多予金錢。爲中詗長安。孟康曰。詗音偵。西方人以反閒爲偵。王使其女爲偵於中也。服䖍亦云。偵伺之也。如淳曰。詗音朽政反。按說文無偵字。則從服孟說詗卽偵。是也。"}]},"讂":{"expl":"流言也。从言夐聲。","rad":"言","fq":"火縣切","vol":"03","py":"juàn","duan":[{"e":"流言也。从言夐聲。","n":"火縣切。十四部。"}]},"詆":{"expl":"苛也。一曰訶也。从言氐聲。","rad":"言","fq":"都禮切","vol":"03","py":"dǐ","duan":[{"e":"訶也。","n":"鉉本苛也。一曰訶也。從言氐聲。鍇本荷也。從言氐聲一曰訶。今按二本皆誤。漢人訶多假荷爲之。如周禮宮正比長注。荷皆呼何反。宋槧周禮及釋文可證。淺人改爲苛。此亦其比也。不得其說。乃訶荷竝存矣。今依韵會刪正。"}]},"誰":{"expl":"何也。从言隹聲。","rad":"言","fq":"示隹切","vol":"03","py":"shuí","duan":[{"e":"誰何也。","n":"三字爲句。各本少誰字。誤刪之也。敦字下云一曰誰何也。可證。李善引有謂責問之也五字。葢注家語。六韜。令我壘上。誰何不絶。賈誼書。陳厲兵而誰何。史記衞綰傳。歲餘不誰何綰。漢書作不孰何。韋注國語。彉弩注矢以誰何。有單云誰者。如五行志。大誰卒。易林。無敢誰者。楊雄箴。閻樂矯搜。戟者不誰。耤田賦。靡誰督而常勤。有單云何者。如廣雅。何、問也。賈誼傳。大譴大何。"}]},"禎":{"expl":"祥也。从示貞聲。","rad":"示","fq":"陟盈切","vol":"01","py":"zhēn","duan":[{"e":"祥也。从示。貞聲。","n":"陟盈切。十一部。"}]},"𤩭":{"expl":"石之似玉者。从玉號聲。讀若鎬。","rad":"玉","fq":"乎到切","vol":"01","py":"hào","duan":[{"e":"石之似玉者。从王。號聲。讀若鎬。","n":"乎到切。二部。"}]},"諽":{"expl":"飾也。一曰更也。从言革聲。讀若戒。","rad":"言","fq":"古覈切","vol":"03","py":"ɡé","duan":[{"e":"飭也。","n":"作飾誤。諽與悈音義同。"}]},"讕":{"expl":"怟讕也。从言闌聲。","rad":"言","fq":"洛干切","vol":"03","py":"lán","duan":[{"e":"抵讕也。","n":"抵各本作詆。誤文三王傳。王陽病。抵讕置辭。師古曰。抵、距也。讕、誣諱也。文帝紀韋注曰。謾、抵讕也。按抵讕猶今俗語云抵賴也。"}]},"診":{"expl":"視也。从言㐱聲。","rad":"言","fq":"直刃切","vol":"03","py":"zhěn","duan":[{"e":"視也。","n":"倉公傳診脈、視脈也。從言者、醫家先問而後切也。"}]},"𧪷":{"expl":"悲聲也。从言，斯省聲。","rad":"言","fq":"先稽切","vol":"03","py":"xī","duan":[{"e":"悲聲也。","n":"斯、析也。澌、水索也。凡同聲多同義。鍇曰。今謂馬悲鳴爲嘶。"}]},"訧":{"expl":"罪也。从言尤聲。《周書》曰：“報以庶訧。”","rad":"言","fq":"羽求切","vol":"03","py":"yóu","duan":[{"e":"罪也。","n":"邶風毛傳。訧、過也。亦作郵。釋言。郵、過也。亦作尤。孟子引詩畜君何尤。"}]},"誅":{"expl":"討也。从言朱聲。","rad":"言","fq":"陟輸切","vol":"03","py":"zhū","duan":[{"e":"討也。","n":"凡殺戮、糾責皆是。"}]},"討":{"expl":"治也。从言从寸。","rad":"言","fq":"他皓切","vol":"03","py":"tǎo","duan":[{"e":"治也。","n":"發其紛糾而治之曰討。秦風傳曰。蒙討羽也。箋云。蒙尨也。討、襍也。畫襍羽之文於伐。故曰尨伐據鄭所言。則討者、亂也。治討曰討。猶治亂曰亂也。論語。世叔討論之。馬曰。討、治也。學記。古之學者。比物醜類。醜或作討。凡言討論、探討。皆謂理其不齊者而齊之也。"}]},"諳":{"expl":"悉也。从言音聲。","rad":"言","fq":"烏含切","vol":"03","py":"ān","duan":[{"e":"悉也。","n":"此與宷義同音近。"}]},"讄":{"expl":"禱也。累功德以求福。《論語》云：“讄曰：‘禱尔于上下神祇。’”从言，纍省聲。","rad":"言","fq":"力軌切","vol":"03","py":"lěi","duan":[{"e":"禱也。絫功德㠯求福也。","n":"讄絫雙聲。按讄施於生者以求福。誄施於死者以作謚。論語之讄曰。字當從畾。毛傳曰。桑紀、能誄。字當從耒。周禮六辭。鄭司農注二字巳不分矣。"}]},"諡":{"expl":"行之迹也。从言、兮、皿。闕。","rad":"言","fq":"神至切","vol":"03","py":"shì","duan":[]},"𤪍":{"expl":"石之似玉者。从玉舝聲。讀若曷。","rad":"玉","fq":"胡捌切","vol":"01","py":"xiá","duan":[{"e":"石之似玉者。从王。舝聲。讀若曷。","n":"乎捌切。十五部。"}]},"誄":{"expl":"諡也。从言耒聲。","rad":"言","fq":"力軌切","vol":"03","py":"lěi","duan":[{"e":"謚也。","n":"當云所以爲謚也。曾子問注曰。誄、絫也。絫列生時行迹。讀之以作謚。"}]},"謑":{"expl":"恥也。从言奚聲。","rad":"言","fq":"胡禮切","vol":"03","py":"xǐ","duan":[{"e":"謑詬、","n":"二字今補。逗。"}]},"詬":{"expl":"謑詬，恥也。从言后聲。","rad":"言","fq":"呼寇切","vol":"03","py":"ɡòu","duan":[{"e":"謑詬也。","n":"依全書例訂。"}]},"諜":{"expl":"軍中反閒也。从言枼聲。","rad":"言","fq":"徒叶切","vol":"03","py":"dié","duan":[{"e":"軍中反閒也。","n":"釋言。閒、俔也。郭云。左傳謂之諜。今之細作也。按左傳諜輅之、諜告曰楚幕有烏皆是。大史公書借爲牒札字。"}]},"該":{"expl":"軍中約也。从言亥聲。讀若心中滿該。","rad":"言","fq":"古哀切","vol":"03","py":"ɡāi","duan":[{"e":"軍中約也。","n":"凡俗云當該者皆本此。"}]},"譯":{"expl":"傳譯四夷之言者。从言睪聲。","rad":"言","fq":"羊昔切","vol":"03","py":"yì","duan":[{"e":"傳四夷之語者。","n":"依李善、徐堅訂。方言。譯、傳也。王制曰。東方曰寄南方曰象。西方曰狄鞮。北方曰譯。"}]},"訄":{"expl":"迫也。从言九聲。讀若求。","rad":"言","fq":"巨鳩切","vol":"03","py":"qiú","duan":[{"e":"迫也。","n":"廣雅同。"}]},"謚":{"expl":"笑皃。从言益聲。","rad":"言","fq":"伊昔切","vol":"03","py":"yì","duan":[{"e":"行之迹也。","n":"周書謚法解、檀弓樂記表記注皆云。謚者、行之迹也。謚迹曡韵。"}]},"譶":{"expl":"疾言也。从三言。讀若沓。","rad":"言","fq":"徒合切","vol":"03","py":"tà","duan":[{"e":"疾言也。从三言。讀若沓。","n":"文𨕖琴賦。紛？譶以流漫。注。？譶、聲多也。徒合切。吳都賦。？譶澩㺒。交貿相競。注引倉頡篇。譶、言不止也。佇立切。大徐引唐韵徒合切。"}]},"詢":{"expl":"謀也。从言旬聲。","rad":"言","fq":"相倫切","vol":"03","py":"xún","duan":[]},"𤧩":{"expl":"石之似玉者。从玉𥄗聲。","rad":"玉","fq":"烏貫切","vol":"01","py":"wàn","duan":[{"e":"石之似玉者。从王。𥄗聲。","n":"烏貫切。十四部。"}]},"讜":{"expl":"直言也。从言黨聲。","rad":"言","fq":"多朖切","vol":"03","py":"dǎnɡ","duan":[]},"譜":{"expl":"籍録也。从言普聲。《史記》从並。","rad":"言","fq":"博古切","vol":"03","py":"pǔ","duan":[]},"詎":{"expl":"詎犹豈也。从言巨聲。","rad":"言","fq":"其吕切","vol":"03","py":"jù","duan":[]},"𧩮":{"expl":"小也。誘也。从言叜聲。《禮記》曰：“足以𧩮聞。”","rad":"言","fq":"先鳥切","vol":"03","py":"xiǎo","duan":[]},"謎":{"expl":"隱語也。从言、迷，迷亦聲。","rad":"言","fq":"莫計切","vol":"03","py":"mí","duan":[]},"誌":{"expl":"記誌也。从言志聲。","rad":"言","fq":"職吏切","vol":"03","py":"zhì","duan":[]},"訣":{"expl":"訣别也。一曰法也。从言，決省聲。","rad":"言","fq":"古穴切","vol":"03","py":"jué","duan":[]},"誩":{"expl":"競言也。从二言。凡誩之屬皆从誩。讀若競。","rad":"誩","fq":"渠慶切","vol":"03","py":"jìnɡ","duan":[{"e":"竸言也。从二言。","n":"渠慶切。古音在十部。讀如彊。"}]},"譱":{"expl":"吉也。从誩从羊。此與義美同意。","rad":"誩","fq":"常衍切","vol":"03","py":"shàn","duan":[{"e":"吉也。","n":"口部曰。吉、譱也。"}]},"競":{"expl":"彊語也。一曰逐也。从誩，从二人。","rad":"誩","fq":"渠慶切","vol":"03","py":"jìnɡ","duan":[{"e":"彊語也。","n":"競彊曡韵。彊語謂相爭。"}]},"𤫉":{"expl":"石之次玉者。从玉燮聲。","rad":"玉","fq":"穌叶切","vol":"01","py":"xiè","duan":[{"e":"石之玉。","n":"鍇本如此。下有言次玉者四字。葢注釋語。自𤤺至㺮十八字。皆似玉者。鉉本作石之次玉者、與鍇本注皆非。玉篇、廣韻皆云。𤫉、石似玉。"}]},"讟":{"expl":"痛怨也。从誩𧷏聲。《春秋傳》曰：“民無怨讟。”","rad":"誩","fq":"徒谷切","vol":"03","py":"dú","duan":[{"e":"痛怨也。","n":"方言。讟、謗也。讟、痛也。二義相足。"}]},"音":{"expl":"聲也。生於心，有節於外，謂之音。宮商角徵羽，聲；絲竹金石匏土革木，音也。从言含一。凡音之屬皆从音。","rad":"音","fq":"於今切","vol":"03","py":"yīn","duan":[{"e":"聲生於心有節於外謂之音。","n":"十一字一句。各本聲下衍也字。樂記曰。聲成文謂之音。"}]},"響":{"expl":"聲也。从音鄉聲。","rad":"音","fq":"許兩切","vol":"03","py":"xiǎnɡ","duan":[{"e":"聲也。","n":"渾言之也。天文志曰。鄉之應聲。析言之也。鄉者假借字。按玉篇曰。響、應聲也。"}]},"韽":{"expl":"下徹聲。从音酓聲。","rad":"音","fq":"恩甘切","vol":"03","py":"ān","duan":[{"e":"下徹聲。","n":"周禮典同曰。微聲韽。此葢賈侍中周官解故說。杜子春、鄭康成說各異。"}]},"韶":{"expl":"虞舜樂也。《書》曰：“《簫韶》九成，鳳皇來儀。”从音召聲。","rad":"音","fq":"市招切","vol":"03","py":"sháo","duan":[{"e":"虞舜樂也。","n":"樂記曰。韶、繼也。公羊疏引宋鈞注樂說云。簫之言肅。舜時民樂其肅敬而紹堯道。故謂之簫韶。按韶字葢舜時始製。"}]},"章":{"expl":"樂竟爲一章。从音从十。十，數之終也。","rad":"音","fq":"諸良切","vol":"03","py":"zhānɡ","duan":[{"e":"樂竟爲一章。","n":"歌所止曰章。"}]},"竟":{"expl":"樂曲盡爲竟。从音从人。","rad":"音","fq":"居慶切","vol":"03","py":"jìnɡ","duan":[{"e":"樂曲盡爲竟。","n":"曲之所止也。引伸之凡事之所止、土地之所止皆曰竟。毛傳曰。疆、竟也。俗别製境字。非。"}]},"韻":{"expl":"和也。从音員聲。裴光遠云：古與均同。未知其審。","rad":"音","fq":"王問切","vol":"03","py":"yùn","duan":[]},"䇂":{"expl":"辠也。从干、二。二，古文上字。凡䇂之屬皆从䇂。讀若愆。張林說。","rad":"䇂","fq":"去虔切","vol":"03","py":"qiān","duan":[{"e":"辠也。","n":"辠、犯法也。"}]},"童":{"expl":"男有辠曰奴，奴曰童，女曰妾。从䇂，重省聲。","rad":"䇂","fq":"徒紅切","vol":"03","py":"tónɡ","duan":[{"e":"男有辠曰奴。奴曰童。女曰妾。","n":"女部曰。奴婢皆古之辠人也。偁周禮其奴男子入于辠隷。女子入于春稾。"}]},"玽":{"expl":"石之次玉者。从玉句聲。讀若苟。","rad":"玉","fq":"古厚切","vol":"01","py":"ɡǒu","duan":[{"e":"石之似玉者。","n":"似汲古原本作次。非。"}]},"妾":{"expl":"有辠女子，給事之得接於君者。从䇂从女。《春秋》云：“女爲人妾。”妾，不娉也。","rad":"䇂","fq":"七接切","vol":"03","py":"qiè","duan":[{"e":"有辠女子給事之得接於君者。","n":"十二字一句。妾接曡韵。有罪女子給事若周禮女酒女漿女籩女醢女醯女監女幂女祝女史內司服女御縫人女御女工女春抌女饎女稾各若干人、各有奚若干人是也。鄭注女酒、女奴曉酒者。古者從坐男女𣳚入縣官爲奴。其少才知以爲奚。今之侍史官婢或曰奚宦女。云得接於君者、如內司服縫人皆有女御。鄭云有女御者以衣服進。或當於王。廣其禮使無色過。是也。奚、女部作㜎。"}]},"丵":{"expl":"叢生艸也。象丵嶽相竝出也。凡丵之屬皆从丵。讀若浞。","rad":"丵","fq":"士角切","vol":"03","py":"zhuó","duan":[{"e":"叢生艸也。象丵嶽相並岀也。","n":"謂此象形字也。丵嶽曡韵字。或作？嶽。吳語不經見者謂丵嶽。"}]},"業":{"expl":"大版也。所以飾縣鍾鼓。捷業如鋸齒，以白畫之。象其鉏鋙相承也。从丵从巾。巾象版。《詩》曰：“巨業維樅。”","rad":"丵","fq":"魚怯切","vol":"03","py":"yè","duan":[{"e":"大版也。","n":"見釋器。"}]},"叢":{"expl":"聚也。从丵取聲。","rad":"丵","fq":"徂紅切","vol":"03","py":"cónɡ","duan":[{"e":"聚也。","n":"於曡韵得之。"}]},"對":{"expl":"譍無方也。从丵从口从寸。","rad":"丵","fq":"都隊切","vol":"03","py":"duì","duan":[{"e":"𧭭無方也。","n":"聘禮注曰。對、荅問也。按對荅古通用。云？無方者、所謂善待問者如撞鐘。叩以大者則大鳴。叩以小者則小鳴也。無方故從丵口。"}]},"菐":{"expl":"瀆菐也。从丵从廾，廾亦聲。凡菐之屬皆从菐。","rad":"菐","fq":"蒲沃切","vol":"03","py":"pú","duan":[{"e":"瀆菐也。","n":"瀆菐曡韵字。瀆、煩瀆也。菐、如孟子書之僕僕。趙云。煩猥皃。"}]},"僕":{"expl":"給事者。从人从菐，菐亦聲。","rad":"菐","fq":"蒲沃切","vol":"03","py":"pú","duan":[{"e":"給事者。","n":"周禮注曰。僕、侍御於尊者之名。然則大僕、戎僕、以及易之童僕、詩之臣僕、左傳人有十等、僕第九、臺第十皆是。大雅。景命有僕。毛傳。僕、附也。是其引伸之義也。大雅。芃芃棫樸。毛曰。樸、枹木也。考工記樸屬。此皆取附箸之義。字當作僕。方言作㯷。"}]},"𠔯":{"expl":"賦事也。从菐从八。八，分之也。八亦聲。讀若頒。一曰讀若非。","rad":"菐","fq":"布還切","vol":"03","py":"bān","duan":[{"e":"賦事也。","n":"賦者、布也。魯語曰。社而賦事。蒸而獻功。"}]},"𠬞":{"expl":"竦手也。从𠂇从又。凡廾之屬皆从廾。(今變隸作廾。)","rad":"𠬞","fq":"居竦切","vol":"03","py":"ɡǒnɡ","duan":[{"e":"竦手也。","n":"竦、敬也。"}]},"奉":{"expl":"承也。从手从廾，𡴀聲。","rad":"𠬞","fq":"扶隴切","vol":"03","py":"fènɡ","duan":[{"e":"承也。","n":"手部曰承、奉也。受也。"}]},"琂":{"expl":"石之似玉者。从玉言聲。","rad":"玉","fq":"語軒切","vol":"01","py":"yán","duan":[{"e":"石之似玉者。从王。言聲。","n":"語軒切。十四部。"}]},"丞":{"expl":"翊也。从廾从卩从山。山高，奉承之義。","rad":"𠬞","fq":"署陵切","vol":"03","py":"chénɡ","duan":[{"e":"翊也。","n":"翊當作翼。俗書以翊爲翼。翼猶輔也。哀十八年左傳曰。使帥師而行。請承。杜曰。承、佐也。承者丞之假借。文王世子引記曰。虞夏商周有師保、有疑丞。百官公卿表丞相。應劭曰。丞者、承也。相者、助也。按漢凡官多有丞者皆以輔之。"}]},"奐":{"expl":"取奐也。一曰大也。从廾，夐省。","rad":"𠬞","fq":"呼貫切","vol":"03","py":"huàn","duan":[{"e":"取奐也。","n":"未聞。"}]},"弇":{"expl":"蓋也。从廾从合。","rad":"𠬞","fq":"古南切","vol":"03","py":"yǎn","duan":[{"e":"葢也。","n":"釋言曰。弇、同也。弇、葢也。此與奄、覆也音義同。釋器曰。圜弇上謂之鼒。謂斂其上不全葢也。周禮說鐘弇聲鬰、弇謂中央寛也。"}]},"𢍰":{"expl":"引給也。从廾睪聲。","rad":"𠬞","fq":"羊益切","vol":"03","py":"yì","duan":[{"e":"引繒也。","n":"篇、韵此字皆作睪。非也。睪與𢍰不得合爲一字。各本引給也、不可通。惟廣韵作引繪皃、似是隨唐相傳說文古本引繒而長之。葢作僞之事。與斁解也、殬敗也、音義相通。或曰。當作引紿。紿、絲勞也。"}]},"𢍉":{"expl":"舉也。从廾甶聲。《春秋傳》曰：“晉人或以廣墜，楚人𢍉之。”黃顥說：廣車陷，楚人爲舉之。杜林以爲騏麟字。","rad":"𠬞","fq":"渠記切","vol":"03","py":"qí","duan":[{"e":"舉也。从廾。由聲。","n":"各本作由聲。誤。或從鬼頭之？亦非也。此從東楚名缶之由。故左傳作𢍁。今左作惎。糸部𦁰從𢍁聲。或字作綦。由聲、其聲皆在一部也。"}]},"异":{"expl":"舉也。从廾㠯聲。《虞書》曰： “岳曰：异哉！”","rad":"𠬞","fq":"羊吏切","vol":"03","py":"yì","duan":[{"e":"舉也。从廾。㠯聲。","n":"羊吏切。一部。按篆從㠯。隷作异不合。疑篆隷皆從己而誤也。"}]},"弄":{"expl":"玩也。从廾持玉。","rad":"𠬞","fq":"盧貢切","vol":"03","py":"lònɡ","duan":[{"e":"玩也。","n":"玉部曰。玩、弄也。小雅。載弄之璋。左傳曰。弱不好弄。又曰。君以弄馬之故。國語囗。還弄吳國於股掌之上。"}]},"𢌻":{"expl":"兩手盛也。从廾𡴆聲。","rad":"𠬞","fq":"余六切","vol":"03","py":"yù","duan":[{"e":"㒳手盛也。从廾。圥聲。","n":"余六切。三部廣韵曰。說文音匊。"}]},"𢍏":{"expl":"摶飯也。从廾釆聲。釆，古文辦字。讀若書卷。","rad":"𠬞","fq":"居券切","vol":"03","py":"juàn","duan":[{"e":"摶飯也。","n":"𢍏摶曡韵曲禮。母摶飯。"}]},"𢌳":{"expl":"持弩拊。从廾、肉。讀若逵。","rad":"𠬞","fq":"渠追切","vol":"03","py":"kuí","duan":[{"e":"持弩拊。","n":"凡弓刀把処皆曰拊。今攷工記弓人作柎。从木。"}]},"璶":{"expl":"石之似玉者。从玉盡聲。","rad":"玉","fq":"徐刃切","vol":"01","py":"jìn","duan":[{"e":"石之似玉者。从王。盡聲。","n":"徐刃切。十二部。"}]},"戒":{"expl":"警也。从廾持戈，以戒不虞。","rad":"𠬞","fq":"居拜切","vol":"03","py":"jiè","duan":[{"e":"警也。","n":"言部曰警、戒也。"}]},"兵":{"expl":"械也。从廾持斤，并力之皃。","rad":"𠬞","fq":"補明切","vol":"03","py":"bīnɡ","duan":[{"e":"械也。","n":"械者器之緫名。器曰兵。用器之人亦曰兵。下文云從廾持斤則製字兵與戒同意也。"}]},"龏":{"expl":"慤也。从廾龍聲。","rad":"𠬞","fq":"紀庸切","vol":"03","py":"ɡōnɡ","duan":[{"e":"愨也。","n":"心部曰。愨、謹也。此與心部恭音義同。"}]},"弈":{"expl":"圍棊也。从廾亦聲。《論語》曰：“不有博弈者乎！”","rad":"𠬞","fq":"羊益切","vol":"03","py":"yì","duan":[{"e":"圍棊也。从廾。亦聲。","n":"羊益切。古音在五部。"}]},"具":{"expl":"共置也。从廾，从貝省。古以貝爲貨。","rad":"𠬞","fq":"其遇切","vol":"03","py":"jù","duan":[{"e":"共置也。","n":"共供古今字。當從人部作供。"}]},"𠬜":{"expl":"引也。从反廾。凡𠬜之屬皆从𠬜。(今變隸作大。)","rad":"𠬜","fq":"普班切","vol":"03","py":"pān","duan":[{"e":"引也。","n":"上林賦。仰𠬜橑而椚天。晉灼曰。𠬜古攀字。按今字皆用攀則𠬜爲古字。𠬜亦小篆也。"}]},"樊":{"expl":"鷙不行也。从𠬜从棥，棥亦聲。","rad":"𠬜","fq":"附袁切","vol":"03","py":"fán","duan":[{"e":"驇不行也。","n":"驇各本譌驇。馬部曰。驇、馬重皃。驇不行、沈滯不行也。毛詩。折桺樊圃。借爲棥字。荘子。澤雉畜乎樊中。樊、籠也。亦是不行意。"}]},"奱":{"expl":"樊也。从𠬜䜌聲。","rad":"𠬜","fq":"呂員切","vol":"03","py":"luán","duan":[{"e":"樊也。","n":"此與手部攣音義皆同。玉篇云。攀、變也。"}]},"共":{"expl":"同也。从廿、廾。凡共之屬皆从共。","rad":"共","fq":"渠用切","vol":"03","py":"ɡònɡ","duan":[{"e":"同也。从廿廾。","n":"廿、二十幷也。二十人皆竦手是爲同也。渠用切。九部。周禮、尚書供給供奉字皆借共字爲之。衞包盡改尚書之共爲恭。非也。釋詁。供、歭、共、具也。郭云。皆謂備具。此古以共爲供之理也。尚書、毛詩、史記恭敬字皆作恭。不作共。漢石經之存者無逸一篇中徽柔懿共、惟正之共皆作共。嚴恭寅畏作恭。此可以知古之字例矣。毛詩溫溫恭人、敬恭明祀、溫恭朝夕皆不作共。靖共爾位箋云。共、具也。則非恭字也。虔共爾位箋云。古之恭字或作共。云或、則僅見之事也。史記恭敬字亦無作共者。"}]},"龔":{"expl":"給也。从共龍聲。","rad":"共","fq":"俱容切","vol":"03","py":"ɡōnɡ","duan":[{"e":"給也。","n":"糸部曰。給、相足也。此與人部供音義同。今供行而龔廢矣。尚書甘誓、牧誓龔行天之罰。謂奉行也。漢魏晉唐引此無不作龔。與供給義相近。衞包作恭。非也。秦和鐘銘。龔夤天命。言奉敬天命也。"}]},"琟":{"expl":"石之似玉者。从玉隹聲。讀若維。","rad":"玉","fq":"以追切","vol":"01","py":"wéi","duan":[{"e":"石之似玉者。从王。隹聲。讀若維。","n":"以追切。十五部。"}]},"異":{"expl":"分也。从廾从畀。畀，予也。凡異之屬皆从異。","rad":"異","fq":"羊吏切","vol":"03","py":"yì","duan":[{"e":"分也。","n":"分之則有彼此之異。"}]},"戴":{"expl":"分物得增益曰戴。从異𢦔聲。","rad":"異","fq":"都代切","vol":"03","py":"dài","duan":[{"e":"分物得增益曰戴。","n":"釋訓曰。蓁蓁、孽孽、戴也。毛傳云。蓁蓁、至盛皃。孽孽、盛飾。是皆謂加多也。引伸之凡加於上皆曰戴。如土山戴石曰崔嵬、石山戴土曰？是也。又與載通用。言其上曰戴。言其下曰載也。釋山或本。石載土謂之崔嵬。土載石爲砠。謂石載於土、土載於石則與毛傳不異也。周頌載弁俅俅、月令載青旗皆同戴。"}]},"舁":{"expl":"共舉也。从𦥑从廾。凡舁之屬皆从舁。讀若余。","rad":"舁","fq":"以諸切","vol":"03","py":"yú","duan":[{"e":"共舉也。从𦥑廾。","n":"謂有叉手者、有竦手者。皆共舉之人也。共舉則或休息更畨。故有叉手者。"}]},"𢍱":{"expl":"升高也。从舁囟聲。","rad":"舁","fq":"七然切","vol":"03","py":"qiān","duan":[{"e":"𦫵高也。","n":"𦫵之言登也。此與辵部遷？音義同。"}]},"與":{"expl":"黨與也。从舁从与。","rad":"舁","fq":"余呂切","vol":"03","py":"yǔ","duan":[{"e":"黨與也。","n":"黨當作攩。攩、朋群也。與當作与。与、賜予也。"}]},"興":{"expl":"起也。从舁从同。同力也。","rad":"舁","fq":"虚陵切","vol":"03","py":"xīnɡ","duan":[{"e":"起也。","n":"廣韵曰。盛也。舉也。善也。周禮六詩。曰比。曰興。興者託事於物。按古無平去之别也。"}]},"𦥑":{"expl":"叉手也。从纟、纠。凡𦥑之屬皆从𦥑。","rad":"𦥑","fq":"居玉切","vol":"03","py":"jū","duan":[{"e":"叉手也。","n":"又部曰。叉手、指相錯也。此云叉手者、謂手指正相向也。"}]},"要":{"expl":"身中也。象人要自𦥑之形。从𦥑，交省聲。","rad":"𦥑","fq":"於消切","vol":"03","py":"yāo","duan":[{"e":"身中也。象人𦥺自臼之形。从臼。","n":"按各本篆作？。從臼下有交省聲三字。淺人所妄改也。今依玉篇、九經字㨾訂。顧氏、唐氏所據說文未誤也。漢地理志。北地大？縣。注。一遥反。上黨沾縣大？谷。淸漳水所岀。說文、水經注作大要谷。今志誤爲黽字矣。上象人首。下象人足。中象人𦝫。而自臼持之。故從臼。必從臼者、象形猶未顯。人多護惜其𦝫故也。於消切。二部。"}]},"䢅":{"expl":"早昧爽也。从𦥑从辰。辰，時也。辰亦聲。𠃨夕爲𡖊，臼辰爲䢅，皆同意。凡䢅之屬皆从䢅。","rad":"䢅","fq":"食鄰切","vol":"03","py":"chén","duan":[{"e":"早昧爽也。","n":"日部曰。早䢅也。昧爽、旦明也。文王世子注曰。早昧爽。擊𡔷以召衆。亦三字絫言之。左傳僖五年正義解說文謂夜將旦雞鳴時也。"}]},"䢉":{"expl":"耕也。从䢅囟聲。","rad":"䢅","fq":"奴冬切","vol":"03","py":"nónɡ","duan":[{"e":"耕人也。","n":"各本無人字。今依玄應書卷十一補。食貨志。四民有業。闢土植穀曰農。洪範。次三日。農用八政。鄭云。農讀爲醲。易其字也。某氏因訓農爲厚矣。"}]},"瑦":{"expl":"石之似玉者。从玉烏聲。","rad":"玉","fq":"安古切","vol":"01","py":"wǔ","duan":[{"e":"石之似玉者。从王。烏聲。","n":"安古切。五部。"}]},"爨":{"expl":"齊謂之炊爨。𦥑象持甑，冂爲竈口，廾推林内火。凡爨之屬皆从爨。","rad":"爨","fq":"七亂切","vol":"03","py":"cuàn","duan":[{"e":"齊謂炊爨。","n":"各本謂下衍之字。今正。火部曰。炊、爨也。然則二字互相訓。孟子趙注曰。爨炊也。齊謂炊爨者、齊人謂炊曰爨。古言謂則不言曰。如毛傳婦人謂嫁歸是也。特牲、少牢禮注皆曰。爨、竈也。此因爨必於竈。故謂竈爲爨。禮器燔柴於爨同。楚茨傳曰。爨、饔爨廩爨也。此謂竈。又曰。踖踖、爨竈有容也。此謂炊。"}]},"𦦧":{"expl":"所以枝鬲者。从爨省，鬲省。","rad":"爨","fq":"渠容切","vol":"03","py":"qiónɡ","duan":[{"e":"所㠯枝鬲者。从爨省鬲省。","n":"渠容切。九部。"}]},"釁":{"expl":"血祭也。象祭竈也。从爨省，从酉。酉，所以祭也。从分，分亦聲。","rad":"爨","fq":"虚振切","vol":"03","py":"xìn","duan":[{"e":"血祭也。","n":"周禮大祝注云。隋釁謂薦血也。凡血祭曰釁。孟子梁惠王趙注曰。新鑄鐘。殺牲以血塗其釁郤。因以祭之曰釁。漢書高帝紀釁𡔷。應劭曰。釁、祭也。殺牲以血塗𡔷釁呼爲釁。呼同罅。按凡言釁廟、釁鐘、釁𡔷、釁寶鎭寶器、釁龜策、釁宗廟名器皆同。以血塗之因薦而祭之也。凡坼罅謂之釁。方言作璺。音問。以血血其坼罅亦曰釁。樂記作衅。"}]},"革":{"expl":"獸皮治去其毛，革更之。象古文革之形。凡革之屬皆从革。","rad":"革","fq":"古覈切","vol":"03","py":"ɡé","duan":[{"e":"獸皮治去其毛曰革。","n":"各本獸皮治去其毛革更之、象古文革之形。文義、句讀皆不可通。今依召南、齊風、大雅、周禮掌皮四疏訂正。革與鞹二字轉注。皮與革二字對文則分別。如秋斂皮、冬斂革是也。散文則通用。如司裘之皮車卽革路、詩羔羊傳革猶皮也是也。"}]},"鞹":{"expl":"去毛皮也。《論語》曰：“虎豹之鞹。”从革郭聲。","rad":"革","fq":"苦郭切","vol":"03","py":"kuò","duan":[{"e":"革也。","n":"各本作去毛皮也。今依載驅、韓奕正義正。大雅傳云。鞹、革也。論語孔注云。皮去毛曰鞹。此恐人不省詳言之。若說文革字下已注明。何庸辭費。"}]},"靬":{"expl":"靬，乾革也。武威有麗靬縣。从革干聲。","rad":"革","fq":"苦旰切","vol":"03","py":"jiān","duan":[{"e":"靬、","n":"此複舉字𠜂之未盡者。"}]},"𩊚":{"expl":"生革可以爲縷束也。从革各聲。","rad":"革","fq":"盧各切","vol":"03","py":"luò","duan":[{"e":"生革可㠯爲縷束也。","n":"小雅。約之閣閣。毛曰。約、束也。閣閣猶歷歷也。按閣讀如絡。秦風五楘傳曰。五束歷録。生革縷束曰𩊚者、謂束之歷録也。"}]},"鞄":{"expl":"柔革工也。从革包聲。讀若朴。《周禮》曰：“柔皮之工鮑氏。”鞄卽鮑也。","rad":"革","fq":"蒲角切","vol":"03","py":"páo","duan":[{"e":"柔革工也。从革。包聲。","n":"蒲角切。古音在二部。"}]},"䩵":{"expl":"攻皮治鼓工也。从革軍聲。讀若運。","rad":"革","fq":"王問切","vol":"03","py":"yùn","duan":[{"e":"攻皮治𡔷工也。","n":"考工記注。先鄭云。韗、書或爲𩋃。皋陶𡔷木也。後鄭云。𩋃者以皋陶名官也。𩋃則陶字從革。按先後鄭䩵𩋃兩存。許從䩵不從𩋃也。"}]},"鞣":{"expl":"耎也。从革从柔，柔亦聲。","rad":"革","fq":"耳由切","vol":"03","py":"róu","duan":[{"e":"耎也。","n":"耎同偄。弱也。"}]},"瑂":{"expl":"石之似玉者。从玉眉聲。讀若眉。","rad":"玉","fq":"武悲切","vol":"01","py":"méi","duan":[{"e":"石之似玉者。从王。眉聲。讀若眉。","n":"武悲切。十五部。"}]},"靼":{"expl":"柔革也。从革，从旦聲。","rad":"革","fq":"旨熱切","vol":"03","py":"dá","duan":[{"e":"柔革也。","n":"柔當作鞣。上文云柔皮之工、謂治之使柔。此云柔革、謂革之柔耎者也。"}]},"鞼":{"expl":"韋繡也。从革貴聲。","rad":"革","fq":"求位切","vol":"03","py":"ɡuì","duan":[{"e":"革繡也。","n":"齊語。管子曰。輕罪贖以鞼盾一𢧢（戟）。韋曰。鞼盾、綴革有文如繢也。後漢烏桓傳曰。婦人能刺韋作文繡。"}]},"鞶":{"expl":"大帶也。《易》曰：“或錫之鞶帶。”男子帶鞶，婦人帶絲。从革般聲。","rad":"革","fq":"蒲官切","vol":"03","py":"pán","duan":[{"e":"大帶也。易曰。或錫之鞶帶。","n":"訟上九。"}]},"鞏":{"expl":"以韋束也。《易》曰：“鞏用黃牛之革。”从革巩聲。","rad":"革","fq":"居竦切","vol":"03","py":"ɡǒnɡ","duan":[{"e":"㠯韋束也。","n":"大雅。藐藐昊天。無不克鞏。毛曰。鞏、固也。此引伸之義也。"}]},"鞔":{"expl":"履空也。从革免聲。","rad":"革","fq":"母官切","vol":"03","py":"mán","duan":[{"e":"𡳐空也。","n":"小徐曰。履空猶履𣪊也。按空腔古今字。履腔如今人言鞵幫也。逋旁切。呂氏春秋曰。南家工人也。爲鞔者也。高曰。鞔、履也。作履之工也。高不云履空者、渾言之也。三蒼。鞔、覆也。考工記注。飾車、謂革鞔輿也。此鞔引伸之義。凡鞔皆如綴幫於底。"}]},"靸":{"expl":"小兒履也。从革及聲。讀若沓。","rad":"革","fq":"穌合切","vol":"03","py":"sǎ","duan":[{"e":"小兒𡳐也。","n":"急就篇有靸。釋名曰。靸、韋履深頭者之名也。"}]},"䩕":{"expl":"䩕角，鞮屬。从革卬聲。","rad":"革","fq":"五岡切","vol":"03","py":"ánɡ","duan":[{"e":"䩕角、","n":"逗。"}]},"鞮":{"expl":"革履也。从革是聲。","rad":"革","fq":"都兮切","vol":"03","py":"dī","duan":[{"e":"革𡳐也。","n":"周禮釋文云。許愼曰。鞮、屨也。吕忱曰。鞮、革屨也。與今本異。徐堅、玄應引與今本同。曲禮鞮屨注。無絇之菲也。周禮鞮鞻氏注。鞮鞻、四夷舞者所屝也。王制西方曰狄鞮注。鞮之爲言知也。"}]},"䩡":{"expl":"鞮䩡沙也。从革从夾，夾亦聲。","rad":"革","fq":"古洽切","vol":"03","py":"jiá","duan":[{"e":"鞮䩡沙也。","n":"謂鞮之名䩡沙者也。䩕角、䩡沙皆漢人語。廣雅之𩌍𩊮也。𩌍古匣切。𩊮音沙。𩌍𩊮、𩌈𩍜、靸𡲲也。集韵。𡲲與鞾同。廣韵。𩌍𩊮、索𩍜、胡履也。釋名。𩌈𩍜、鞾之缺前壅者。胡中所名也。"}]},"𩌦":{"expl":"鞮屬。从革徙聲。","rad":"革","fq":"所綺切","vol":"03","py":"xǐ","duan":[{"e":"鞮屬。从革。徙聲。","n":"所綺切。十六部。"}]},"祥":{"expl":"福也。从示羊聲。一云善。","rad":"示","fq":"似羊切","vol":"01","py":"xiánɡ","duan":[{"e":"福也。","n":"凡統言則災亦謂之祥。析言則善者謂之祥。"}]},"璒":{"expl":"石之似玉者。从玉登聲。","rad":"玉","fq":"都騰切","vol":"01","py":"dēnɡ","duan":[{"e":"石之似玉者。从王。登聲。","n":"都騰切。六部。"}]},"鞵":{"expl":"革生鞮也。从革奚聲。","rad":"革","fq":"戶佳切","vol":"03","py":"xié","duan":[{"e":"生革鞮也。","n":"生革各本作革生。今正。"}]},"靪":{"expl":"補履下也。从革丁聲。","rad":"革","fq":"當經切","vol":"03","py":"dīnɡ","duan":[{"e":"補𡳐下也。","n":"原思納履則歱決。故履下可補也。今俗謂補綴曰打補靪。當作此字。"}]},"鞠":{"expl":"蹋鞠也。从革匊聲。","rad":"革","fq":"居六切","vol":"03","py":"jū","duan":[{"e":"蹋鞠也。","n":"劉向別錄曰。蹵鞠者、傳言黃帝所作。或曰。起戰國之時。蹋鞠、兵勢也。所以練武士、知有材也。皆因嬉戲而講練之。漢藝文志兵技巧十三家有蹵𩌽二十五篇。郭樸注三蒼云。毛丸可蹋戲者曰鞠。按鞠居六求六二切。廣韵曰。今通謂之毬子。巨鳩切。古今字也。"}]},"鞀":{"expl":"鞀遼也。从革召聲。","rad":"革","fq":"徒刀切","vol":"03","py":"táo","duan":[{"e":"鞀、","n":"此複字𠜂之未盡者。"}]},"𩌑":{"expl":"量物之𩌑。一曰抒井𩌑。古以革。从革冤聲。","rad":"革","fq":"於袁切","vol":"03","py":"yuān","duan":[{"e":"量物之𩌑。一曰抒井𩌑。","n":"小徐曰。抒井今言淘井。𩌑、取泥之器。玉裁按。依說文浚、抒也。則小徐說是。依手部抒、挹也。則汲井亦可云抒井。缶部曰。罋、汲缾也。春秋傳言具綆缶。周易言羸其缾。是其物用缶久矣。而其始用革也。"}]},"鞞":{"expl":"刀室也。从革卑聲。","rad":"革","fq":"并頂切","vol":"03","py":"bǐnɡ","duan":[{"e":"刀室也。","n":"刀部曰。削、鞞也。削鞘古今字。音肖。小雅、大雅毛傳不同。說詳玉部。"}]},"鞎":{"expl":"車革前曰鞎。从革艮聲。","rad":"革","fq":"戶恩切","vol":"03","py":"hén","duan":[{"e":"車革前曰鞎。","n":"釋器曰。輿革前謂之鞎。郭曰。以韋鞔車軾。按李巡云。輿革前、謂輿前以革爲車飾曰鞎。不言軾。依毛傳韋鞔軾、自名鞃。不名鞎。疑李注是。"}]},"鞃":{"expl":"車軾也。从革弘聲。《詩》曰：“鞹鞃淺幭。”讀若穹。","rad":"革","fq":"丘弘切","vol":"03","py":"hónɡ","duan":[{"e":"車軾中把也。","n":"各本無中把二字。韵會作中靶。靶字誤。今補正。大雅傳曰。鞹、革也。鞃、軾中也。此謂以去毛之皮鞔軾中人所凭處。篇、韵皆云。軾中靶。靶、轡革。不當以名軾。葢許本作把。而俗譌從革。軾中把者、人把持之處也。較毛多一字。"}]},"鞪":{"expl":"車軸束也。从革敄聲。","rad":"革","fq":"莫卜切","vol":"03","py":"mù","duan":[{"e":"車軸束也。","n":"此與木部楘音同義近。楘謂輈束。鞪謂軸束。分析易明。而小戎音義曰。楘本又作鞪。玉篇亦曰。鞪亦作楘。曲轅束也。疑本一字。許書有楘無鞪。後人補之。又改輈爲軸。"}]},"䩛":{"expl":"車束也。从革必聲。","rad":"革","fq":"毗必切","vol":"03","py":"bì","duan":[{"e":"車束也。","n":"考工記天子圭中必注。必、讀如鹿車縪之縪。謂以組約其中央。爲執之以備失隊。方言曰。車下鉄。陳宋淮楚之閒謂之畢。大者謂之綦。郭注云。鹿車也。按鄭、郭云鹿車者、非小車財容一鹿之謂。方言曰。繀車、趙魏之閒謂之轣轆車。東齊海岱之閒謂之道軌。廣雅。繀車謂之厤鹿。道軌謂之鹿車。本方言。葢厤鹿卽毛詩傳之歷錄。鹿車卽周禮注之鹿車。鹿車與歷鹿義同。皆於其圍繞命名也。糸部縪、止也。古畢必通用。故必䩛縪同。約圭與約車相類也。"}]},"㺨":{"expl":"石之似玉者。从玉厶聲。讀與私同。","rad":"玉","fq":"息夷切","vol":"01","py":"sī","duan":[{"e":"石之似玉者。从王。厶聲。讀與私同。","n":"凡言讀與某同者、亦卽讀若某也。息夷切。十五部。"}]},"𩎑":{"expl":"車衡三束也。曲轅𩎈縛，直轅𨏉縛。从革爨聲。讀若《論語》“鑽燧”之“鑽”。","rad":"革","fq":"借官切","vol":"03","py":"zuān","duan":[{"e":"車衡三束也。","n":"當作車句衡五束也。秦風。五楘梁輈。毛曰。小戎、兵車也。五、五束也。楘、歷錄也。梁輈、輈上句衡也。一輈五束。束曰歷錄。句衡謂轅也。故下文言轅不言衡。"}]},"𩊝":{"expl":"蓋杠絲也。从革旨聲。","rad":"革","fq":"脂利切","vol":"03","py":"zhì","duan":[{"e":"葢杠系也。","n":"葢杠考工記謂之桯。桯讀如楹。系各本作絲。今正。系、係也。係、絜束也。絜束者、圍而束之。𩊝用革。故字從革。"}]},"鞁":{"expl":"車駕具也。从革皮聲。","rad":"革","fq":"平祕切","vol":"03","py":"bèi","duan":[{"e":"車駕具也。","n":"晉語。吾兩鞁將絕。吾能止之。韋曰。鞁、靷也。按韋以左傳作靷。故以靷釋之。其實鞁所包者多。靷其大者。封禪書言雍五畤。路車各一乗。駕被具。西畤、畦畤。禺車各一乗。禺馬四匹。駕被具。被卽鞁字也。鞁與糸部絥[糹+𤰈]{𩍁}各物。"}]},"鞥":{"expl":"轡鞥。从革弇聲。讀若譍。一曰龍頭繞者。","rad":"革","fq":"烏合切","vol":"03","py":"ēnɡ","duan":[{"e":"轡鞥。","n":"轡鞥、葢古語。轡亦名鞥也。"}]},"靶":{"expl":"轡革也。从革巴聲。","rad":"革","fq":"必駕切","vol":"03","py":"bà","duan":[{"e":"轡革也。","n":"王褒傳。王良執靶。音義或曰。靶音霸。謂轡也。吳都賦。迴靶乎行邪睨。劉曰。靶、轡革也。按云轡革者、毛傳云革轡首也。"}]},"𩎍":{"expl":"著掖鞥也。从革顯聲。","rad":"革","fq":"呼典切","vol":"03","py":"xiǎn","duan":[{"e":"箸亦鞥也。","n":"亦鉉本作掖。非其物也。鍇作腋。俗字也。今正。亦、人之臂亦也。箸亦鞥、謂箸於馬兩亦之革也。箸亦、謂直者。當膺、謂橫者。鞥當作靼。左傳釋文、正義引皆作皮。作鞥非也。史記禮書鮫韅。徐曰。韅者、當馬腋之革。若釋名云橫經腹下、杜注左云在背曰韅皆異說也。"}]},"靳":{"expl":"當膺也。从革斤聲。","rad":"革","fq":"居近切","vol":"03","py":"jìn","duan":[{"e":"當𦢖也。","n":"左傳曰。吾從子如驂之有靳。杜曰。靳、車中馬也。言已從書。如驂馬之隨靳也。正義曰。驂馬之首當服馬之胸。胸上有靳。故云我從子如驂當服之靳。按左傳。晉車七百乗。韅靷鞅靽。杜曰。在胸曰靷。此正在匈曰靳之誤。以秦風傳靳環或作靷環證之。其誤正同矣。游環在服馬背上。驂馬外轡貫之。以止驂之出。故謂之靳環。靳者、驂馬止而不過之處。故引伸之義爲靳固。左傳。宋公靳之。吝其寵也。"}]},"䩶":{"expl":"驂具也。从革𧈪聲。讀若騁蜃。","rad":"革","fq":"丑郢切","vol":"03","py":"chěnɡ","duan":[{"e":"驂具也。","n":"上二文當是服馬鞁具。此云驂具。互文見義也。从革。蚩聲。丑郢切。十一部。"}]},"靷":{"expl":"引軸也。从革引聲。","rad":"革","fq":"余忍切","vol":"03","py":"yǐn","duan":[{"e":"所㠯引軸者也。","n":"所以者字、依楊倞注荀卿補。凡許書所以字淺人往往𠜂之。秦風毛傳曰。靷所以引也。毛不言軸。許云軸以箸明之。轅載於軸。兩靷亦係於軸。左傳。兩靷將絕。吾能止之。駕而乗材。兩靷皆絕。此可見靷之任力幾與轅等。靷在輿下而見於軓前。乃設環以續靷而係諸衡。故詩云。陰靷沃續。孔沖遠云。靷繫於陰版之上。令驂馬引之。此非是。驂在服外而後於服。與靷不正相當。且軓非能任力。不當係於軓也。許云所以引軸。說不可易。"}]},"䩪":{"expl":"車鞁具也。从革官聲。","rad":"革","fq":"古滿切","vol":"03","py":"ɡuǎn","duan":[{"e":"車鞁具也。从革。官聲。","n":"古滿切。十四部。"}]},"玗":{"expl":"石之似玉者。从玉于聲。","rad":"玉","fq":"羽俱切","vol":"01","py":"yú","duan":[{"e":"石之似玉者。","n":"鍇釋以珣玗琪。非也。珣玗琪合三字爲玉名。單言珣者、玉器也。單言璂者、弁飾也。單言玗者、美石也。齊風尚之以瓊華傳曰。華、美石。華葢卽玗。二字同于聲也。"}]},"𩊪":{"expl":"車鞁具也。从革豆聲。","rad":"革","fq":"田候切","vol":"03","py":"dòu","duan":[{"e":"車鞁具也。从革。豆聲。","n":"四𠋫切四部。"}]},"䩒":{"expl":"輨内環靼也。从革于聲。","rad":"革","fq":"羽俱切","vol":"03","py":"yú","duan":[{"e":"䩪内環靼也。","n":"䩪各本譌輨。今依玉篇。環靼者、環之以靼。"}]},"𩌏":{"expl":"車下索也。从革尃聲。","rad":"革","fq":"補各切","vol":"03","py":"bó","duan":[{"e":"車下索也。","n":"釋名。縛在車下。與輿相連縛也。當作𩌏在車下。"}]},"𩋊":{"expl":"車具也。从革奄聲。","rad":"革","fq":"烏合切","vol":"03","py":"è","duan":[{"e":"車具也。从革。奄聲。","n":"烏合切。八部。"}]},"𩋁":{"expl":"車具也。从革叕聲。","rad":"革","fq":"陟劣切","vol":"03","py":"zhuó","duan":[{"e":"車具也。从革。<>（叕）聲。","n":"陟劣切。十五部。"}]},"鞌":{"expl":"馬鞁具也。从革从安。","rad":"革","fq":"烏寒切","vol":"03","py":"ān","duan":[{"e":"馬鞁具也。","n":"此爲跨馬設也。左傳。趙𣃼以良馬二。㴉其兄與叔父。左師展將以公乘馬而歸。三代時非無跨馬者矣。春秋經有鞌字。"}]},"䩸":{"expl":"鞌毳飾也。从革茸聲。","rad":"革","fq":"而隴切","vol":"03","py":"rónɡ","duan":[{"e":"鞌毳飾也。","n":"毳、獸細毛也。"}]},"䩞":{"expl":"鞌飾。从革占聲。","rad":"革","fq":"他叶切","vol":"03","py":"tié","duan":[{"e":"鞌飾。","n":"篇、韵皆曰鞌䩞。"}]},"鞈":{"expl":"防汗也。从革合聲。","rad":"革","fq":"古洽切","vol":"03","py":"ɡé","duan":[{"e":"防汗也。","n":"此當作所以防捍也。轉寫奪誤。巾部曰。幩、馬纏鑣扇汗也。與此無涉。篇、韵皆曰防捍。是相傳古本捍亦作扞。故譌汗。荀卿曰。犀兕鮫革。鞈如金石。管子。輕罪入蘭盾鞈革二戟。注曰。鞈革、重革。當心箸之。可以禦矢。鼂錯曰。匈奴之革笥木薦弗能支。孟康曰。革笥、以皮作如鎧者被之。木薦、以木版作如楯。一曰革笥若楯。木薦之以當人心也。此皆防捍之說。鍇曰。今胡人扞𦝫也。知鍇本故作扞。"}]},"勒":{"expl":"馬頭絡銜也。从革力聲。","rad":"革","fq":"盧則切","vol":"03","py":"lè","duan":[{"e":"馬頭落銜也。","n":"落絡古今字。糸部繯下云落也。知許之不作絡矣。釋名。勒、絡也。絡其頭而引之。按网部𦋱、馬落頭也。金部銜、馬勒口中。此云落銜者、謂落其頭而銜其口。可控制也。引伸之爲抑勒之義。又爲物勒工名之義。廣韵云。石虎諱勒。呼馬勒爲轡。此名之不正也。爾雅。轡首謂之革。革卽勒之省。馬絡頭者、轡所係也。故曰轡首。毛詩䩦革皆當依古金石作𠈹勒、鋚勒。毛傳曰。攸、轡首飾也。革、轡首也。自來上句奪首飾二字而莫得其解。"}]},"𤣻":{"expl":"玉屬。从玉𠬸聲。讀若沒。","rad":"玉","fq":"莫悖切","vol":"01","py":"mò","duan":[{"e":"玉屬也。","n":"玉篇引穆天子傳。采石之山有𤣻瑤。凡言某屬者。謂某之類。"}]},"鞙":{"expl":"大車縛軛靼。从革肙聲。","rad":"革","fq":"狂沇切","vol":"03","py":"xuàn","duan":[{"e":"大車縛軛靼。","n":"大車、牛車也。縛軛者。苞注論語云。輗者、轅端橫木以縛枙者也。皇曰。古作牛車。先取一橫木縛著兩轅頭。又別取曲木爲枙縛著橫木。以駕牛脰也。然則軛縛於橫木。橫木縛於轅。縛於轅者輗也。軛縛於輗用靼。鞙亦作𩉥。釋名。𩉥、縣也。所以縣縛軛也。"}]},"𩋠":{"expl":"勒靼也。从革面聲。","rad":"革","fq":"弥沇切","vol":"03","py":"miǎn","duan":[{"e":"勒靼也。","n":"謂馬勒之靼也。勒在馬面。故從面。"}]},"靲":{"expl":"鞮也。从革今聲。","rad":"革","fq":"巨今切","vol":"03","py":"qín","duan":[{"e":"鞮也。","n":"鞮、革履也。玉篇靲下云。靲、鞻也。周禮鞮鞻氏音義。吕忱云。鞮者、革屨也。鞻者、靲鞻。按鞮鞻、走部作趧婁。故革部無鞻。字林有鞻。釋之曰靲鞻。則靲字亦字林始有之。說文靲字殆後人所增。不與䩕鞮䩡等爲伍。"}]},"鞬":{"expl":"所以戢弓矢。从革建聲。","rad":"革","fq":"居言切","vol":"03","py":"jiān","duan":[{"e":"所㠯戢弓矢。","n":"左傳。左執鞭弭。右屬櫜鞬。杜曰。櫜以受箭。鞬以受弓。方言。弓謂之鞬。釋名。受矢之器。馬上曰鞬。鞬、建也。言弓矢竝建立其中也。廣韵曰。馬上藏弓矢器。"}]},"韇":{"expl":"弓矢韇也。从革𧷏聲。","rad":"革","fq":"徒谷切","vol":"03","py":"dú","duan":[{"e":"弓矢韇也。","n":"方言。弓謂之鞬。或謂之𥀲（皾）丸。左傳服注云。冰、櫝丸葢也。後書南匈奴傳引方言。藏弓爲鞬。藏箭爲韇丸。廣雅。鞬、弓藏也。皾㿪、矢藏也。皆與今方言異。按絫呼之曰韇丸。單呼之曰韇。士冠禮。筮人執策抽上韇。注。韇、藏策之器。今時藏弓矢者謂之韇丸也。亦疑說文本有丸。淺人𠜂之。"}]},"䪎":{"expl":"緌也。从革巂聲。","rad":"革","fq":"山垂切","vol":"03","py":"suī","duan":[{"e":"緌也。","n":"㬪韵。糸部曰。緌、系冠纓也。引伸凡垂者謂之緌。廣雅。䪎謂之鞘。鞘音梢。玉篇云。鞌邊帶。是也。"}]},"䩯":{"expl":"急也。从革亟聲。","rad":"革","fq":"紀力切","vol":"03","py":"jí","duan":[{"e":"急也。","n":"雙聲。此亦𡔷郭、琴禁之例。廣韵。䩯、皮鞭皃。按䩯鞭二字相屬。疑本作鞭急也。轉寫奪鞭。"}]},"鞭":{"expl":"驅也。从革𠊳聲。","rad":"革","fq":"卑連切","vol":"03","py":"biān","duan":[{"e":"毆也。","n":"毆各本作驅。淺人改也。今正。毆上仍當有所以二字。尙書。鞭作官㓝。周禮條狼氏。掌執鞭而趨辟。凡誓、執鞭以趨於前。且命之。司市。凡市入則胥執鞭度守門。左傳。誅屨於徒人費。弗得。鞭之見血。又公怒。鞭師曹三百。皆謂鞭所以毆人之物。以之毆人亦曰鞭。經典之鞭皆施於人。不謂施於馬。曲禮。乗路馬。載鞭策。左傳。左執鞭弭。馬不出者。助之鞭之。皆是假借施人之用爲施馬之偁。非若今人竟謂以杖馬之物杖人也。葢馬箠曰策。所以擊馬曰箠。以箠擊馬曰敇。本皆有正名。不曰鞭也。擊馬之箠用竹。毆人之鞭用革。故其字亦從竹、從革不同。自唐以下毆變爲𢿛。與驅同音。謂鞭爲捶馬之物。因改此毆爲驅。不知絕非字義。毆、捶擊物也。驅、馬馳也。"}]},"鞅":{"expl":"頸靼也。从革央聲。","rad":"革","fq":"於兩切","vol":"03","py":"yǎnɡ","duan":[{"e":"頸靼也。","n":"釋名。鞅、嬰也。喉下稱嬰。言嬰絡之也。按劉與許合。杜云在腹曰鞅。恐未然也。小雅鞅掌。毛曰。失容也。"}]},"韄":{"expl":"佩刀絲也。从革蒦聲。","rad":"革","fq":"乙白切","vol":"03","py":"hù","duan":[{"e":"佩刀系也。","n":"系各本作絲。今正。此葢糸部所謂緱也。廣韵云。佩刀飾。莊子音義引三蒼云。韄、佩刀靶韋也。莊子外韄内韄。引伸之義也。李云。縛也。"}]},"瑎":{"expl":"黑石似玉者。从玉皆聲。讀若諧。","rad":"玉","fq":"戶皆切","vol":"01","py":"xié","duan":[{"e":"黑石似玉者。从王。皆聲。讀若諧。","n":"尸皆切。十五部。"}]},"𩉺":{"expl":"馬尾駝也。从革它聲。今之般緧。","rad":"革","fq":"徒何切","vol":"03","py":"tuó","duan":[{"e":"馬尾𩉺也。","n":"方言。車紂、自關而東、周雒汝潁而東謂之䋺。或謂之曲綯。或謂之曲綸。自關而西謂之紂。糸部曰。緧、馬紂也。紂、馬緧也。考工記。必緧其牛。後鄭云。關東謂紂爲緧。按𩉺𩋃語相似。𩉺葢𩋃之轉語。"}]},"䩤":{"expl":"繫牛脛也。从革見聲。","rad":"革","fq":"已彳切","vol":"03","py":"xié","duan":[{"e":"繫牛脛也。","n":"繫當作系。"}]},"鞘":{"expl":"刀室也。从革肖聲。","rad":"革","fq":"私妙切","vol":"03","py":"qiào","duan":[]},"韉":{"expl":"馬鞁具也。从革薦聲。","rad":"革","fq":"則前切","vol":"03","py":"jiān","duan":[]},"鞾":{"expl":"鞮屬。从革華聲。","rad":"革","fq":"許𦣛切","vol":"03","py":"xuē","duan":[]},"靮":{"expl":"馬羈也。从革勺聲。","rad":"革","fq":"都歴切","vol":"03","py":"dí","duan":[]},"鬲":{"expl":"鼎屬。實五觳。斗二升曰觳。象腹交文，三足。凡鬲之屬皆从鬲。","rad":"鬲","fq":"郎激切","vol":"03","py":"lì","duan":[{"e":"鼎屬也。","n":"釋器曰。鼎款足者謂之鬲。"}]},"䰙":{"expl":"三足鍑也。一曰滫米器也。从鬲支聲。","rad":"鬲","fq":"魚綺切","vol":"03","py":"yǐ","duan":[{"e":"三足鍑也。","n":"鍑如釜而大口。廣雅。䰙、鬴也。"}]},"鬹":{"expl":"三足釜也。有柄喙。讀若嬀。从鬲規聲。","rad":"鬲","fq":"居隨切","vol":"03","py":"ɡuī","duan":[{"e":"三足鬴也。","n":"廣雅。鬹、鬴也。有柄喙。有柄可持。有喙可寫物。此其別於䰙者也。"}]},"鬷":{"expl":"釜屬。从鬲㚇聲。","rad":"鬲","fq":"子紅切","vol":"03","py":"zōnɡ","duan":[{"e":"鬴屬。","n":"廣雅。鐈鬲鬷也。陳風。越以鬷邁。商頌。鬷假無言。毛曰。鬷、數也。又曰。鬷、緫也。數讀如數罟之數。數罟、豳風作緵罟。魚麗作緫罟。然則二傳皆謂鬷者、緫之假借字也。"}]},"碧":{"expl":"石之青美者。从玉、石，白聲。","rad":"玉","fq":"兵尺切","vol":"01","py":"bì","duan":[{"e":"石之靑美者。","n":"西山經。高山其下多靑碧。傳。碧亦玉類也。淮南書。崑崙有碧樹。注。碧、靑石也。劉逵、常璩、郭樸皆曰。越巂會無縣東山出碧。"}]},"𩰫":{"expl":"秦名土釜曰𩰫。从鬲𡕒聲。讀若過。","rad":"鬲","fq":"古禾切","vol":"03","py":"ɡuō","duan":[{"e":"秦名土鬴曰𩰫。","n":"今俗作鍋。土釜者、出於匋也。"}]},"鬵":{"expl":"大釜也。一曰鼎大上小下若甑曰鬵。从鬲兓聲。讀若岑。","rad":"鬲","fq":"才林切","vol":"03","py":"qín","duan":[{"e":"大鬴也。","n":"檜風。誰能亨魚。摡之釜鬵。毛曰。鬵、釜屬。按下文別一義。"}]},"䰝":{"expl":"鬵屬。从鬲曾聲。","rad":"鬲","fq":"子孕切","vol":"03","py":"zènɡ","duan":[{"e":"鬵屬。从鬲。曾聲。","n":"按此篆淺人𡚶增也。瓦部甑、甗也。甗、甑也。一穿。䰝者、甑之或體耳。爾雅音義云。䰝本或作甑。篇、韵皆云甑䰝同字。可知古本說文不分入鬲瓦二部。至集韵乃據徐鉉之書截然爲二字矣。"}]},"鬴":{"expl":"鍑屬。从鬲甫聲。","rad":"鬲","fq":"扶雨切","vol":"03","py":"fǔ","duan":[{"e":"鍑屬也。","n":"𦫵四曰豆。豆四曰區。區四曰鬴。"}]},"鬳":{"expl":"鬲屬。从鬲虍聲。","rad":"鬲","fq":"牛建切","vol":"03","py":"yàn","duan":[{"e":"鬲屬。","n":"鬲、鼎屬也。"}]},"融":{"expl":"炊气上出也。从鬲，蟲省聲。","rad":"鬲","fq":"以戎切","vol":"03","py":"rónɡ","duan":[{"e":"炊气上出也。","n":"釋詁、毛傳、方言皆曰。融、長也。此其引伸之義也。通作䑣。思玄賦。展泄泄以䑣䑣。廣成頌。豐䑣薱蔚。"}]},"𩱴":{"expl":"炊气㒵。从鬲嚻聲。","rad":"鬲","fq":"許嬌切","vol":"03","py":"xiāo","duan":[{"e":"炊气皃。","n":"㗊部曰。嚻、聲也。气出頭上。從㗊頁。炊气亦上出。故從嚻。"}]},"𩰱":{"expl":"煑也。从鬲羊聲。","rad":"鬲","fq":"式羊切","vol":"03","py":"shānɡ","duan":[{"e":"䰞也。","n":"𩰱亦作鬺。亦作䵼。韓詩。于以鬺之。惟錡及釜。封禪書。禹收九牧之金鑄九鼎。皆嘗亨鬺上帝鬼神。亨鬺、郊祀志作鬺亨。亨、許兩切。謂煑而獻之上帝鬼神也。毛詩假湘爲之。毛曰。湘、烹也。"}]},"𩰾":{"expl":"涫也。从鬲沸聲。","rad":"鬲","fq":"芳未切","vol":"03","py":"fèi","duan":[{"e":"涫也。","n":"水部曰。涫、𩰾也今俗字涫作滚、𩰾作沸。非也。上林賦曰。湁潗鼎𩰾。嚴夫子哀時命曰。氣涫𩰾其若波。"}]},"䰜":{"expl":"㽁也。古文亦鬲字。象孰飪五味气上出也。凡䰜之屬皆从𩰲。","rad":"䰜","fq":"郎激切","vol":"03","py":"lì","duan":[{"e":"㽁也。","n":"二字淺人𡚶增。此云古文亦鬲字。卽亣籒文大、改古文之例。何取以漢令鬲爲訓釋乎。"}]},"琨":{"expl":"石之美者。从玉昆聲。《虞書》曰：“楊州貢瑤琨。”","rad":"玉","fq":"古渾切","vol":"01","py":"kūn","duan":[{"e":"石之美者。","n":"王肅及某氏注禹貢皆曰。瑤琨皆美石。劉逵注吳都賦、顏師古注地理志皆曰。琨、美石。今本轉寫石多譌玉。穆天子傳。天子之珤玉昆。傳。石似美玉。今本昆譌果。招魂。昆蔽象棋。注。昆、玉也。當云昆同琨。石似玉。"}]},"𩱡":{"expl":"鬻也。从𩰲侃聲。","rad":"䰜","fq":"諸延切","vol":"03","py":"zhān","duan":[{"e":"鬻也。从䰜。侃聲。","n":"諸延切。十四部。按此當去虔切。𩱡或作餰。猶愆作諐也。淺人謂卽饘字不分。故同切諸延耳。"}]},"鬻":{"expl":"䭈也。从𩰲米聲。","rad":"䰜","fq":"武悲切","vol":"03","py":"zhōu","duan":[{"e":"䭈也。从䰜米。","n":"會意。之六切。三部。按一音余六切。是以賣鬻字作此。賣之假借也。鉉本作米聲。武悲切。此因誤衍聲字而爲之切音。非眞唐韵有武悲切也。爾雅猶如麂之猶。舍人本作鬻。異文同部。是可以定其非形聲矣。廣韵、集韵、篆韵𧪻脂韵內皆無鬻。玉篇云。說文又音糜。廣韵云。說文本音麋者、乃陳彭年輩誤用鉉本也。玉篇糜字又麋之誤。類篇𢗅皮切之誤本此。鬻作粥者、俗字也作。𢐲者、樂記假鬻爲育而轉寫致譌也。"}]},"𩱍":{"expl":"䭈也。从𩰲古聲。","rad":"䰜","fq":"戶吳切","vol":"03","py":"hú","duan":[{"e":"䭈也。","n":"釋言。餬、饘也。當作此字。今江蘇俗粉米麥爲粥曰餬。"}]},"𩱧":{"expl":"五味盉羹也。从𩰲从羔。《詩》曰：“亦有和𩱧。”","rad":"䰜","fq":"古行切","vol":"03","py":"ɡēnɡ","duan":[{"e":"五味盉𩱧也。","n":"皿部曰。盉、調味也。內則注曰。凡羹齊宜五味之和。米㞕之糝。晏子曰。和如羹焉。水火醯醢鹽梅以亨魚肉。宰夫和之。齊之以味。濟其不及。以泄其過。凡魚肉必用菜。菜謂之芼。儀禮。𨦕芼牛藿羊苦豕薇。芼及醯醢鹽梅是之謂五味之和也。實於𨦕謂之𨦕羹。肉汁不和五味謂之大羹。"}]},"𩱫":{"expl":"鼎實。惟葦及蒲。陳畱謂䭈爲𩱫。从𩰲速聲。","rad":"䰜","fq":"桑谷切","vol":"03","py":"sù","duan":[{"e":"鼎實、惟葦及蒲。","n":"此有奪。當云實也。詩云。其𩱫維何。維筍及蒲。或曰。筍作葦者、三家詩也。爾雅。其萌{艸+(弓+萑[左右])}。今蘆筍可食者也。按詩其殽維何。炰鱉鮮魚。此謂鼎中肉也。其蔌維何。維筍及蒲。此謂鼎中菜也。菜謂之芼。釋器曰。肉謂之羹。菜謂之蔌毛曰蔌。毛曰。菜、殽也。菜殽對肉殽而言。凡禮經之藿苦薇、昏義之蘋藻、二南之䓷、皆是。周易覆公餗。鄭曰。餗、菜也。凡肉謂之醢。菜謂之菹。皆主謂生物實於豆者。肉謂之羹。菜謂之芼。皆主謂孰物實於鼎者。說詳戴先生毛鄭詩考正。"}]},"𩱱":{"expl":"鬻也。从𩰲毓聲。","rad":"䰜","fq":"余六切","vol":"03","py":"yù","duan":[{"e":"鬻也。","n":"曡韵。"}]},"𩱷":{"expl":"涼州謂鬻爲𩱸。从𩰲𥽘聲。","rad":"䰜","fq":"莫結切","vol":"03","py":"miè","duan":[{"e":"涼州謂鬻爲𩱷。","n":"按此鬻、鍇本作糜爲長。糜𩱷雙聲故也。"}]},"𩱓":{"expl":"粉餅也。从𩰲耳聲。","rad":"䰜","fq":"仍吏切","vol":"03","py":"ěr","duan":[{"e":"粉餠也。","n":"周禮。糗餌粉餈。食部曰。餈、稻餠也。此曰𩱓粉餠也。葢謂餈者、不粉之稻米爲餠。餌者稻米粉之爲餠。文互相足。經云糗餌者、謂以熬米麥傅於餌。粉餈者、謂以他穀粉傅於餈。此許意與先、後鄭說異。小徐云。許說冣精。又內則注。餌筋腱也。又莊子。以五十犗爲餌。餌、釣㗖魚者。"}]},"𩱦":{"expl":"𤎅也。从𩰲芻聲。","rad":"䰜","fq":"尺沼切","vol":"03","py":"chǎo","duan":[{"e":"𤎅也。","n":"爾雅音義引三蒼𤎅也。說文火乾物也。與今本異。玄應再引與今本同。方言。𤎅㷅𤋎𤏛鞏火乾也。秦晉之閒或謂之㷅。按㷅卽𩱦字。或作𤌽。玄應曰。崔寔四民月令作炒。古文奇字作𤍕。"}]},"𩱲":{"expl":"内肉及菜湯中薄出之。从𩰲翟聲。","rad":"䰜","fq":"以勺切","vol":"03","py":"yuè","duan":[{"e":"內肉及菜湯中薄出之。","n":"內今之納字。薄音博。迫也。納肉及菜於𩰾湯中而迫出之。今俗所謂煠也。玄應曰。江東謂瀹爲煠。煠音助甲切。𩱲今字作瀹亦作汋。通俗文曰。以湯煑物曰瀹。廣雅曰。瀹、湯也。孫炎說夏礿之義曰。新菜可汋。"}]},"珉":{"expl":"石之美者。从玉民聲。","rad":"玉","fq":"武巾切","vol":"01","py":"mín","duan":[{"e":"石之美者。","n":"弁師。珉玉三采。"}]},"䰞":{"expl":"孚也。从𩰲者聲。","rad":"䰜","fq":"章與切","vol":"03","py":"zhǔ","duan":[{"e":"亯也。","n":"亯普庚切。𩰱、䰞也。䰞下當云𩰱也。經傳用亯、用烹乃𩰱之假借字耳。亯部曰。獻也。不訓䰞。"}]},"𩱚":{"expl":"吹聲沸也。从𩰲孛聲。","rad":"䰜","fq":"蒲沒切","vol":"03","py":"bó","duan":[{"e":"炊釜𩰾溢也。","n":"炊各本作吹。今從類篇。釜𩰾溢各本作釜溢。宋本作聲沸。今參合定爲釜𩰾溢。今江蘇俗謂火盛水𩰾溢出爲鋪也。𩱚之轉語也。正當作𩱚字。"}]},"爪":{"expl":"丮也。覆手曰爪。象形。凡爪之屬皆从爪。","rad":"爪","fq":"側狡切","vol":"03","py":"zhǎo","duan":[{"e":"𠃨也。","n":"𠃨持也。"}]},"孚":{"expl":"卵孚也。从爪从子。一曰信也。","rad":"爪","fq":"芳無切","vol":"03","py":"fú","duan":[{"e":"卵卽孚也。","n":"卽字依玄應書補。通俗文。卵化曰孚。音方赴反。廣雅。孚、生也。謂子出於卵也。方言。鷄卵伏而未孚。於此可得孚之解矣。卵因伏而孚。學者因卽呼伏爲孚。凡伏卵曰抱。房奧反亦曰蓲。央富反。"}]},"爲":{"expl":"母猴也。其爲禽好爪。爪，母猴象也。下腹爲母猴形。王育曰：“爪，象形也。”","rad":"爪","fq":"薳支切","vol":"03","py":"wéi","duan":[{"e":"母猴也。","n":"左傳魯昭公子公爲亦偁公叔務人。檀弓作公叔禺人。甶部曰。禺、母猴屬也。然則名爲字禺、所謂名字相應也。假借爲作爲之字。凡有所變化曰爲。"}]},"𤓯":{"expl":"亦丮也。从反爪。闕。","rad":"爪","fq":"諸兩切","vol":"03","py":"zhǎnɡ","duan":[{"e":"亦𠃨也。","n":"亦者、亦上篆。此亦持也。"}]},"丮":{"expl":"持也。象手有所丮據也。凡丮之屬皆从丮。讀若𢧢。","rad":"丮","fq":"几劇切","vol":"03","py":"jí","duan":[{"e":"持也。","n":"持握也。"}]},"𡎐":{"expl":"種也。从坴、丮。持亟種之。《書》曰：“我𡎐黍稷。”","rad":"丮","fq":"魚祭切","vol":"03","py":"yì","duan":[{"e":"穜也。","n":"齊風毛傳曰。蓺猶樹也。樹種義同。"}]},"𦏧":{"expl":"食飪也。从丮𦎫聲。《易》曰：“孰飪。”","rad":"丮","fq":"殊六切","vol":"03","py":"shú","duan":[{"e":"食餁也。","n":"餁、大孰也。可食之物大孰、則丮持食之。"}]},"𩛥":{"expl":"設飪也。从丮从食，才聲。讀若載。","rad":"丮","fq":"作代切","vol":"03","py":"zài","duan":[{"e":"設餁也。","n":"餁宋本作食。玉篇同。廣雅釋言曰。𩛥、設也。又釋詁四曰。飢詞也。錢氏大昕定飢爲𩛥字之誤。古用爲發語之載也。如石𡔷詩載作𩛥。"}]},"瑤":{"expl":"玉之美者。从玉䍃聲。《詩》曰：“報之以瓊瑤。”","rad":"玉","fq":"余招切","vol":"01","py":"yáo","duan":[{"e":"石之美者。","n":"各本石譌玉。今依詩音義正。衞風報之以瓊瑤傳曰。瑤、美石。正義不誤。王肅某氏注尚書、劉逵注吳都賦皆曰。瑤琨皆美石也。大雅曰。維玉及瑤。云及則瑤賤於玉。周禮。享先王。大宰贊王玉爵。內宰贊后瑤爵。禮記。尸飲五。君洗玉爵獻卿。尸飮七。以瑤爵獻大夫。是玉與瑤等差明證。九歌注云。瑤、石之次玉者。凡謂瑤爲玉者非是。"}]},"𢀜":{"expl":"袌也。从丮工聲。","rad":"丮","fq":"居悚切","vol":"03","py":"ɡǒnɡ","duan":[{"e":"袌也。","n":"手部曰。㧬、𢹬也。𢹬、袌也。"}]},"谻":{"expl":"相踦之也。从丮𧮫聲。","rad":"丮","fq":"其虐切","vol":"03","py":"jué","duan":[{"e":"相踦𧮭也。","n":"踦當作掎。𧮭玉篇作卻。"}]},"𢦚":{"expl":"擊踝也。从丮从戈。讀若踝。","rad":"丮","fq":"胡瓦切","vol":"03","py":"huà","duan":[{"e":"擊踝也。从𠃨戈。","n":"疑奪聲字。"}]},"𠩀":{"expl":"拖持也。从反丮。闕。","rad":"丮","fq":"居玉切","vol":"03","py":"jú","duan":[{"e":"亦持也。从反𠃨。","n":"此亦謂𠂇又手之別。"}]},"鬥":{"expl":"兩士相對，兵杖在後，象鬥之形。凡鬥之屬皆从鬥。","rad":"鬥","fq":"都豆切","vol":"03","py":"dòu","duan":[{"e":"㒳士相對。兵杖在後。象鬥之形。","n":"按此非許語也。許之分部次弟。自云據。形係聯。𠃨𠩀在前部。故受之以。然則當云爭也。兩丮相對象形。謂兩人手持相對也。乃云兩士相對。兵杖在後。與前部說自相戾。且文从兩手。非兩士也。此必他家異說。淺人取而竄改許書。雖孝經音義引之。未可信也。都豆切。四部。"}]},"鬭":{"expl":"遇也。从鬥𣂪聲。","rad":"鬥","fq":"都豆切","vol":"03","py":"dòu","duan":[{"e":"遇也。","n":"曡韵。凡今人云鬬接者、是遇之理也。周語。穀雒鬬。將毀王宫。謂二水本異道而忽相接合爲一也。古凡鬬接用鬬字。鬥爭用鬥字。俗皆用鬬爲爭競而鬥廢矣。"}]},"鬨":{"expl":"鬭也。从鬥共聲。《孟子》曰：“鄒與魯鬨。”","rad":"鬥","fq":"下降切","vol":"03","py":"hònɡ","duan":[{"e":"鬥也。","n":"舊作鬬。今正。"}]},"䰘":{"expl":"經繆殺也。从鬥翏聲。","rad":"鬥","fq":"力求切","vol":"03","py":"liú","duan":[{"e":"經繆殺也。","n":"手部曰。摎、縛殺也。按縛殺、若今以一繩勒死。經繆殺、若今絞罪。以二繩絞死。故從鬥。"}]},"鬮":{"expl":"鬭取也。从鬥龜聲。讀若三合繩糾。","rad":"鬥","fq":"古矦切","vol":"03","py":"jiū","duan":[{"e":"鬥取也。","n":"舊作鬬。今正。廣韵作鬮取。按力取是此字本義。今人以爲拈鬮字。殆古藏彄之譌。荆楚嵗時記注曰。藏彄之戲。辛氏三秦記以爲鈎弋夫人所起。周處、成公綏竝作彄字。藝經、庾闡則作鈎字。其事同也。"}]},"𩰞":{"expl":"智少力劣也。从鬥爾聲。","rad":"鬥","fq":"奴礼切","vol":"03","py":"nǐ","duan":[{"e":"智少力劣也。","n":"莊子。苶然疲役而不知其所歸。郭云。疲困苶然。釋文乃結反。按苶者、𩰞之變也。諸韵書皆於薺韵作𩰞、㞕怗韵作苶。是不知爲一字矣。"}]},"珠":{"expl":"蚌之陰精。从玉朱聲。《春秋國語》曰：“珠以禦火灾”是也。","rad":"玉","fq":"章俱切","vol":"01","py":"zhū","duan":[{"e":"蜯中陰精也。","n":"蜯、或蚌字。中各本作之。今依初學記。大戴禮曰。珠者、陰之陽也。故勝火。"}]},"𩰟":{"expl":"鬭連結𩰝紛相牽也。从鬥燹聲。","rad":"鬥","fq":"撫文切","vol":"03","py":"fēn","duan":[{"e":"𩰝𩰟也。从鬥。燹聲。","n":"按此下當有讀若紛三字。撫文切。十三部。𦆯紛、𩰝𩰟皆合二部曡韵。各本譌舛。今依全書通例正之。"}]},"𩰗":{"expl":"鬭也。从鬥，賓省聲。讀若賓。","rad":"鬥","fq":"匹賓切","vol":"03","py":"pīn","duan":[{"e":"𩰝𩰟、","n":"逗。"}]},"鬩":{"expl":"恆訟也。《詩》云：“兄弟鬩于牆。”从鬥从兒。兒，善訟者也。","rad":"鬥","fq":"許激切","vol":"03","py":"xì","duan":[{"e":"恒訟也。","n":"恆、常也。故以小兒善訟會意。"}]},"𩰎":{"expl":"試力士錘也。从鬥从戈。或从戰省。讀若縣。","rad":"鬥","fq":"胡畎切","vol":"03","py":"xuàn","duan":[{"e":"試力士錘也。","n":"錘當作縋。以繩有所縣鎭也。下文云讀若縣。知正當作縋。錘非其義。葢轉寫失之。呂氏春秋云。硾之以石。硾、鎭也。然則作錘亦可。左傳曰。主人縣布。堇父登之。及堞而絶之。隊。則又縣之。蘇而復上者三。又曰。子占使師夜縋而登。登者六十人。縋絶。"}]},"鬧":{"expl":"不静也。从市、鬥。","rad":"鬥","fq":"奴教切","vol":"03","py":"nào","duan":[]},"又":{"expl":"手也。象形。三指者，手之𠛱多略不過三也。凡又之屬皆从又。","rad":"又","fq":"于救切","vol":"03","py":"yòu","duan":[{"e":"手也。象形。","n":"此卽今之右字。不言又手者、本兼𠂇又而言。以屮別之。而又專謂右。猶有古文尚書而後有今文尚書之名、有後漢書而後有前漢書之名、有下曲禮而後有上曲禮之名也。又作右而又爲更然之詞。穀梁傳曰。又、有繼之辭也。"}]},"右":{"expl":"手口相助也。从又从口。","rad":"又","fq":"于救切","vol":"03","py":"yòu","duan":[{"e":"助也。","n":"李燾本及集韵如是。今二徐本皆作手口相助也。"}]},"厷":{"expl":"臂上也。从又，从古文。","rad":"又","fq":"古薨切","vol":"03","py":"ɡōnɡ","duan":[{"e":"臂上也。","n":"臂、手上也。古假弓爲厷。二字古音同也。傳易者江東馯臂子弓。馯姓、臂名、子弓字。名臂故字厷。左、穀梁邾黑肱。公羊作黑弓。鄭公孫黑肱字伯張。則肱卽弓也。"}]},"叉":{"expl":"手指相錯也。从又，象叉之形。","rad":"又","fq":"初牙切","vol":"03","py":"chā","duan":[{"e":"手措{𢫾}相錯也","n":"謂手𢫾與物相錯也。凡布𢫾錯物閒而取之曰叉。因之凡岐頭皆曰叉。是以首筓曰叉。今字作釵。魚部鰸下云。大如叉股。譙周異物志曰。涪陵多大龜。其甲可以卜。其緣中叉似瑇瑁。俗名曰靈叉。劉逵注蜀都賦常璩述華陽國志、郭樸注爾雅皆用其語。緣中叉謂緣可爲釵也。今爾雅注譌作緣中文似瑇瑁、俗呼爲靈龜。自賈公顔周禮疏所引已然矣。"}]},"㕚":{"expl":"手足甲也。从又，象㕚形。","rad":"又","fq":"側狡切","vol":"03","py":"zhǎo","duan":[{"e":"手足甲也。","n":"㕚爪古今字。古作㕚。今用爪。禮經假借作蚤。士喪禮。蚤揃如他日。士虞禮。浴沐櫛搔揃。搔或爲蚤。曲禮。大夫士去國不蚤鬋。蚤皆卽㕚字也。鄭注皆云。蚤讀爲爪。讀爲者、易其字也。不易爲㕚而易爲爪。於此可見漢人固以爪爲手足甲之字矣。釋名曰。爪、紹也。筋極爲爪。紹續𢫾端也。亦不作㕚。"}]},"祉":{"expl":"福也。从示止聲。","rad":"示","fq":"敕里切","vol":"01","py":"zhǐ","duan":[{"e":"福也。","n":"見釋詁。"}]},"玓":{"expl":"玓瓅，明珠色。从玉勺聲。","rad":"玉","fq":"都歴切","vol":"01","py":"dì","duan":[{"e":"玓瓅、","n":"逗。"}]},"父":{"expl":"矩也。家長率教者。从又舉杖。","rad":"又","fq":"扶雨切","vol":"03","py":"fù","duan":[{"e":"巨也。","n":"以曡韵釋之。"}]},"叜":{"expl":"老也。从又从灾。闕。","rad":"又","fq":"穌后切","vol":"03","py":"sǒu","duan":[{"e":"老也。","n":"曡韵。方言曰。𠋢艾長老也。東齊魯衞之閒凡尊老謂之𠋢。或謂之艾。"}]},"燮":{"expl":"和也。从言从又、炎。籒文𤎬从𢆉。𢆉，音飪。讀若溼。","rad":"又","fq":"穌叶切","vol":"03","py":"xiè","duan":[{"e":"和也。","n":"見釋詁。"}]},"曼":{"expl":"引也。从又冒聲。","rad":"又","fq":"無販切","vol":"03","py":"màn","duan":[{"e":"引也。","n":"魯頌毛傳曰。曼、長也。"}]},"𠭙":{"expl":"引也。从又𢑚聲。𢑚，古文申。","rad":"又","fq":"失人切","vol":"03","py":"shēn","duan":[{"e":"伸也。","n":"依宋本。"}]},"夬":{"expl":"分決也。从又，纡象決形。","rad":"又","fq":"古賣切","vol":"03","py":"ɡuài","duan":[{"e":"分決也。","n":"易彖傳曰。夬決也。剛決柔也。"}]},"尹":{"expl":"治也。从又、丿，握事者也。","rad":"又","fq":"余凖切","vol":"03","py":"yǐn","duan":[{"e":"治也。","n":"伊下曰。尹治天下。廣韵曰。正也。進也。誠也。"}]},"𠭯":{"expl":"又卑也。从又虘聲。","rad":"又","fq":"側加切","vol":"03","py":"zhā","duan":[{"e":"叉𤰞也。","n":"各本作又取。今依類篇作叉。宋本作𤰞正。叉𤰞者、用手自高取下也。今俗語讀如渣。若手部云簎者、以𨦵物刺而取之也。方言。抯摣取也。南楚之閒凡取物溝泥中謂之抯。或謂之摣。亦此字引伸之義。"}]},"𠭰":{"expl":"引也。从又𠩺聲。","rad":"又","fq":"里之切","vol":"03","py":"lí","duan":[{"e":"引也。从又。𠩺聲。","n":"里之切。一部。"}]},"㕞":{"expl":"拭也。从又持巾在尸下。","rad":"又","fq":"所劣切","vol":"03","py":"shuā","duan":[{"e":"飾也。","n":"飾各本作拭。今依五經文字正。巾部曰。飾、㕞也。彼此互訓。手部無拭字。彡下云。毛飾畫文也。𦘔下云。聿飾也。皆卽今之拭字。獨於㕞下改拭。與全書矛盾矣。按拭圭雖見聘禮。然必系俗改。古者拂拭字隻用飾。以巾去其塵。故二字皆從巾。去塵而得光明。故引伸爲文飾之義。可尊彝涚酌。大鄭云。捝、拭勺而酌也。拭釋文作飾。㕞亦通用刷。刀部云。禮有刷巾。卽㕞巾也。"}]},"瓅":{"expl":"玓瓅。从玉樂聲。","rad":"玉","fq":"郎擊切","vol":"01","py":"lì","duan":[{"e":"玓瓅也。从王。樂聲。","n":"郞擊切。古音在二部。二字曡韻。"}]},"及":{"expl":"逮也。从又从人。","rad":"又","fq":"巨立切","vol":"03","py":"jí","duan":[{"e":"逮也。","n":"辵部逮、及也。"}]},"秉":{"expl":"禾束也。从又持禾。","rad":"又","fq":"兵永切","vol":"03","py":"bǐnɡ","duan":[{"e":"禾束也。","n":"小雅。彼有遺秉。毛云。秉、把也。聘禮記四秉曰筥注。此秉謂刈禾盈手之秉也。左傳。或取一秉秆焉。按經傳假秉爲柄字。"}]},"反":{"expl":"覆也。从又，厂反形。","rad":"又","fq":"府遠切","vol":"03","py":"fǎn","duan":[{"e":"覆也。","n":"覆、覂也。"}]},"𠬝":{"expl":"治也。从又从卪。卪，事之節也。","rad":"又","fq":"房六切","vol":"03","py":"fú","duan":[{"e":"治也。从又卪。","n":"手持節以治之。"}]},"𠬢":{"expl":"滑也。《詩》云：“𠬢兮達兮。”从又、屮。一曰取也。","rad":"又","fq":"土刀切","vol":"03","py":"tāo","duan":[{"e":"滑也。詩云。𠬢兮𨔶兮。","n":"今鄭風挑兮𨔶兮。辵部引亦作挑。毛云。挑𨔶、往來相見皃。按往來相見卽滑泰之意。𨔶同泰。水部泰、滑也。"}]},"𠭥":{"expl":"楚人謂卜問吉凶曰𠭥。从又持祟，祟亦聲。讀若贅。","rad":"又","fq":"之芮切","vol":"03","py":"zhuì","duan":[{"e":"楚人謂卜問吉凶曰𠭥。","n":"與祝雙聲。"}]},"叔":{"expl":"拾也。从又尗聲。汝南名收芌爲叔。","rad":"又","fq":"式竹切","vol":"03","py":"shū","duan":[{"e":"拾也。","n":"豳風。九月叔苴。毛曰。叔拾也。按釋名。仲父之弟曰叔父。叔、少也。於其雙聲曡韵假借之。假借旣久。而叔之本義鮮知之者。惟見於毛詩而已。"}]},"𠬸":{"expl":"入水有所取也。从又在囘下。囘，古文回。回，淵水也。讀若沫。","rad":"又","fq":"莫勃切","vol":"03","py":"mò","duan":[{"e":"入水有所取也。从又在囘下。","n":"莫勃切。十五部。"}]},"取":{"expl":"捕取也。从又从耳。《周禮》：“獲者取左耳。”《司馬法》曰：“載獻聝。”聝者，耳也。","rad":"又","fq":"七庾切","vol":"03","py":"qǔ","duan":[{"e":"捕取也。","n":"幸部曰。執、捕罪人也。"}]},"彗":{"expl":"掃竹也。从又持甡。","rad":"又","fq":"祥歲切","vol":"03","py":"huì","duan":[{"e":"埽竹也。从又持甡「𤯓+𤯓」。","n":"甡、衆生竝立之皃。從甡者、取排比之意。祥嵗切。十五部。"}]},"玭":{"expl":"珠也。从玉比聲。宋弘云：“淮水中出玭珠。”玭，珠之有聲。","rad":"玉","fq":"步因切","vol":"01","py":"pín","duan":[{"e":"珠也。","n":"謂珠名也。"}]},"叚":{"expl":"借也。闕。","rad":"又","fq":"古雅切","vol":"03","py":"jiǎ","duan":[{"e":"借也。","n":"人部假云非眞也。此叚云借也。然則凡云假借當作此字。古多借瑕爲叚。晉士文伯名匈字伯瑕。楚陽匈、鄭駟乞皆字子瑕。古名字相應。則瑕卽叚也。禮記公肩假、古今人表作公肩瑕。左傳瑕嘉平戎於王。周禮注作叚嘉。皆同音叚借。"}]},"友":{"expl":"同𢖽爲友。从二又。相交友也。","rad":"又","fq":"云久切","vol":"03","py":"yǒu","duan":[{"e":"同志爲友。","n":"周禮注曰。同師曰明。同志曰友。"}]},"度":{"expl":"法制也。从又，庶省聲。","rad":"又","fq":"徒故切","vol":"03","py":"dù","duan":[{"e":"法制也。","n":"論語曰。謹權量。審法度。中庸曰。非天子不制度。今天下車同軌。古者五度。分寸尺丈引謂之制。周禮。出其淳制。天子巡守禮。制幣丈八尺。純三咫。純謂幅廣。"}]},"𠂇":{"expl":"𠂇手也。象形。凡𠂇之屬皆从𠂇。","rad":"𠂇","fq":"臧可切","vol":"03","py":"zuǒ","duan":[{"e":"左手也。","n":"鉉本作𠂇。手也。非。左今之佐字。左部曰。左、𠂇手相左也。是也。又手得𠂇手則不孤。故曰左助之手。"}]},"卑":{"expl":"賤也。執事也。从𠂇、甲。","rad":"𠂇","fq":"補移切","vol":"03","py":"bēi","duan":[{"e":"賤也。執事者。从𠂇甲。","n":"古者尊又而卑𠂇。故從𠂇在甲下。甲象人頭。補移切。十六部。"}]},"史":{"expl":"記事者也。从又持中。中，正也。凡史之屬皆从史。","rad":"史","fq":"疏士切","vol":"03","py":"shǐ","duan":[{"e":"記事者也。","n":"玉藻。動則左史書之。言則右史書之。不云記言者、以記事包之也。"}]},"事":{"expl":"職也。从史，之省聲。","rad":"史","fq":"鉏史切","vol":"03","py":"shì","duan":[{"e":"職也。","n":"曡韵。職記微也。古假借爲士字。鄭風曰。子不我思。豈無他事。毛曰。事、士也。今本依傳改經。又依經改傳。而此傳不可通矣。"}]},"支":{"expl":"去竹之枝也。从手持半竹。凡支之屬皆从支。","rad":"支","fq":"章移切","vol":"03","py":"zhī","duan":[{"e":"去竹之枝也。从手持半竹。","n":"此於字形得其義也。章移切。十六部。"}]},"攲":{"expl":"持去也。从支奇聲。","rad":"支","fq":"去奇切","vol":"03","py":"jī","duan":[{"e":"持去也。","n":"支有持義。故持去之攲從支。宗廟宥座之器曰攲器。按此攲當作㩻。危部曰。㩻、㩻䧢也。竹部箸訓飯攲。此攲亦當作㩻。箸必邪用之。故曰飯㩻。廣韵。㩻、不正也。玉篇曰。攲今作不正之㩻。"}]},"𦘒":{"expl":"手之疌巧也。从又持巾。凡𦘒之屬皆从𦘒。","rad":"𦘒","fq":"尼輒切","vol":"03","py":"niè","duan":[{"e":"手之疌巧也。从又持巾。","n":"尼輒切。八部。"}]},"珕":{"expl":"蜃屬。从玉劦聲。《禮》：“佩刀，士珕琫而珧珌。”","rad":"玉","fq":"郎計切","vol":"01","py":"lì","duan":[{"e":"蜃屬。","n":"謂蜃之類。其甲亦可飾物也。"}]},"𢄥":{"expl":"習也。从𦘒㣇聲。","rad":"𦘒","fq":"羊至切","vol":"03","py":"yì","duan":[{"e":"習也。从𦘒。㣇聲。","n":"羊至切。十五部。"}]},"肅":{"expl":"持事振敬也。从𦘒在𣶒上，戰戰兢兢也。","rad":"𦘒","fq":"息逐切","vol":"03","py":"sù","duan":[{"e":"持事振敬也。","n":"廣韵。恭也。敬也。戒也。進也。疾也。按訓進者、羞之假借。訓疾者、速之假借。皆見禮。"}]},"聿":{"expl":"所以書也。楚謂之聿，吳謂之不律，燕謂之弗。从𦘒一聲。凡聿之屬皆从聿。","rad":"聿","fq":"余律切","vol":"03","py":"yù","duan":[{"e":"所㠯書也。","n":"以用也。聿者、所用書之物也。凡言所以者視此。"}]},"筆":{"expl":"秦謂之筆。从聿从竹。","rad":"聿","fq":"鄙密切","vol":"03","py":"bǐ","duan":[{"e":"秦謂之筆。从聿竹。","n":"鄙密切。古音在十五部。"}]},"𦘔":{"expl":"聿飾也。从聿从彡。俗語以書好爲𦘔。讀若𣸁。","rad":"聿","fq":"將鄰切","vol":"03","py":"jīn","duan":[{"e":"聿飾也。","n":"飾、今之拭字。㕞下詳之矣。彡下曰。毛飾畫文也。象形。謂以毛拭畫成文。彡象其文形也。𦘔者、筆之所拭文成彡形。故從聿從彡。楚金以妝飾解之。繆矣。"}]},"書":{"expl":"箸也。从聿者聲。","rad":"聿","fq":"商魚切","vol":"03","py":"shū","duan":[{"e":"箸也。","n":"此琴禁、𡔷郭之例。以曡韵釋之也。敘目曰。箸於竹帛謂之書。書者、如也。箸於竹帛。非筆末由矣。"}]},"畫":{"expl":"界也。象田四界。聿，所以畫之。凡畫之屬皆从畫。","rad":"畫","fq":"胡麥切","vol":"03","py":"huà","duan":[{"e":"介也。","n":"介各本作畍。此不識字義者所改。今正。八部曰。介、畫也。從八從人。人各有介。"}]},"晝":{"expl":"日之出入，與夜爲界。从畫省，从日。","rad":"畫","fq":"陟救切","vol":"03","py":"zhòu","duan":[{"e":"日之出入。與夜爲介。从畫省。从日。","n":"按今篆體葢亦少一橫。陟救切。四部。"}]},"隶":{"expl":"及也。从又，从㞑省。又，持㞑者，从後及之也。凡隶之屬皆从隶。","rad":"隶","fq":"徒耐切","vol":"03","py":"dài","duan":[{"e":"及也。","n":"此與辵部逮音義皆同。逮專行而隶廢矣。"}]},"𨽿":{"expl":"及也。从隶枲聲。《詩》曰：“ 𨽿天之未陰雨。”","rad":"隶","fq":"徒耐切","vol":"03","py":"dài","duan":[{"e":"及也。","n":"釋言、毛傳、方言皆曰。迨、及也。此與歺部殆音義皆同。殆、危也。危猶及也。"}]},"珧":{"expl":"蜃甲也。所以飾物也。从玉兆聲。《禮》云：“佩刀，天子玉琫而珧珌。”","rad":"玉","fq":"余昭切","vol":"01","py":"yáo","duan":[{"e":"蜃甲也。","n":"介物之㱿曰甲。"}]},"隸":{"expl":"附箸也。从隶柰聲。","rad":"隶","fq":"郎計切","vol":"03","py":"lì","duan":[{"e":"附箸也。","n":"附當是本作坿。淺人改也。周禮注。隷、給勞辱之役者。漢始置司隷。亦使將徒治道溝渠之役。後稍尊之。使主官府及近郊。左傳人有十等。輿臣隷。按隷與僕義同。皆訓坿箸。故從隶。"}]},"臤":{"expl":"堅也。从又臣聲。凡臤之屬皆从臤。讀若鏗鏘之鏗。古文以爲賢字。","rad":"臤","fq":"苦閑切","vol":"03","py":"qiān","duan":[{"e":"堅也。从又。臣聲。","n":"謂握之固也。故從又。"}]},"緊":{"expl":"纏絲急也。从臤，从絲省。","rad":"臤","fq":"糾忍切","vol":"03","py":"jǐn","duan":[{"e":"纏絲急也。","n":"緊急雙聲。此字別作䋗。玉篇引成公四年鄭伯䋌卒。古千古兩二切。考左作堅、公作臤、穀作賢。則別本作䋗、切古千必矣。臣聲與臤聲一也。而顧書譌作䋌。釋名云。絹、䋌也。其絲䋌厚而疏也。是其譌久矣。集韵養韵作䋌、舉兩切。先韵作䋗、緊也。䌑堅同。經天切。是宋時故有䋗字。特丁度等不能用正䋌之譌。又不知卽是緊字耳。春秋鄭伯䋗。釋文不載。考經字者所當知。"}]},"堅":{"expl":"剛也。从臤从土。","rad":"臤","fq":"古賢切","vol":"03","py":"jiān","duan":[{"e":"土剛也。","n":"土字今補。周禮草人。騂剛用牛。九章筭術。穿地四。爲壤五。爲堅三。引伸爲凡物之剛。如云臤堅也。是也。"}]},"豎":{"expl":"豎立也。从臤豆聲。","rad":"臤","fq":"臣庾切","vol":"03","py":"shù","duan":[{"e":"堅立也。","n":"堅立謂堅固立之也。豎與對音義同。而豎從臤。故知爲堅立。周禮內豎。鄭云。豎、未冠者之官名。葢未冠者才能自立。故名之豎。因以爲官名。豎之言孺也。"}]},"臣":{"expl":"牽也。事君也。象屈服之形。凡臣之屬皆从臣。","rad":"臣","fq":"植鄰切","vol":"03","py":"chén","duan":[{"e":"牽也。","n":"以曡韵釋之。春秋說、廣雅皆曰。臣、堅也。白虎通曰。臣者、繵也。屬志自堅固也。"}]},"臦":{"expl":"乖也。从二臣相違。讀若誑。","rad":"臣","fq":"居況切","vol":"03","py":"ɡuànɡ","duan":[{"e":"乖也。从二臣相違。讀若誑。","n":"居況切。十部。按夰部臩以爲聲。"}]},"臧":{"expl":"善也。从臣戕聲。","rad":"臣","fq":"則郎切","vol":"03","py":"zānɡ","duan":[{"e":"善也。","n":"釋詁、毛傳同。按子郎才郎二反。本無二字。凡物善者必隱於內也。以從艸之藏爲臧匿字始於漢末。改易經典。不可從也。又贓私字。古亦用臧。"}]},"殳":{"expl":"以杸殊人也。《禮》：“殳以積竹，八觚，長丈二尺，建於兵車，車旅賁以先驅。”从又几聲。凡殳之屬皆从殳。","rad":"殳","fq":"市朱切","vol":"03","py":"shū","duan":[{"e":"㠯杖殊人也。","n":"杖各本作杸。依太平御覽正。云杖者、殳用積竹而無刃。毛傳殳長丈二而無刃是也。殊、𣃔也。以杖殊人者、謂以杖隔遠之。釋名。殳、殊也。有所撞挃於車上使殊離也。殳殊同音。故謂之殳。猶以近窮遠謂之弓也。"}]},"祋":{"expl":"殳也。从殳示聲。或說城郭市里，高縣羊皮，有不當入而欲入者，暫下以驚牛馬曰祋。故从示、殳。《詩》曰：“何戈與祋。”","rad":"殳","fq":"丁外切","vol":"03","py":"duì","duan":[{"e":"殳也。","n":"見毛傳。"}]},"玟":{"expl":"火齊，玫瑰也。一曰石之美者。从玉文聲。","rad":"玉","fq":"莫桮切","vol":"01","py":"méi","duan":[{"e":"玟瑰、","n":"逗。"}]},"杸":{"expl":"軍中士所持殳也。从木从殳。《司馬法》曰：“執羽从杸。”","rad":"殳","fq":"市朱切","vol":"03","py":"shū","duan":[{"e":"軍中士所持殳也。","n":"軍中士所持殳。不必皆用積竹。故字從木。"}]},"毄":{"expl":"相擊中也。如車相擊。故从殳从軎。","rad":"殳","fq":"古歴切","vol":"03","py":"jī","duan":[{"e":"相擊中也。","n":"考工記。毄兵同強。兼戈殳言之。和弓𣪠摩。注。𣪠、拂也。手部曰。拂、過擊也。惟記文用此字本義。若司門祭祀之牛牲𣪠焉。校人三皁爲𣪠。𣪠一馭夫。六𣪠爲廏。廏一僕夫。皆假借爲系字。今之繫也。易𣪠辭釋文作此字。故云系也。字從𣪠。若直作𣪠下系者音口奚反。非。此謂繫乃說文繫𦃇字。𣪠辭不當作繫也。漢書。景帝詔。農桑𣪠畜。注。食養之畜。"}]},"㱿":{"expl":"从上擊下也。一曰素也。从殳𡉉聲。𡉉，苦江切。","rad":"殳","fq":"苦角切","vol":"03","py":"què","duan":[{"e":"从上擊下也。","n":"從上擊下。正中其物。確然有聲。"}]},"㱽":{"expl":"下擊上也。从殳冘聲。","rad":"殳","fq":"知朕切","vol":"03","py":"zhěn","duan":[{"e":"下擊上也。","n":"廣雅四曰。㱽、禁也。謂禁上使不得下也。"}]},"𣪌":{"expl":"繇擊也。从殳豆聲。古文祋如此。","rad":"殳","fq":"度矦切","vol":"03","py":"tóu","duan":[{"e":"繇擊也。","n":"繇說文作䌛。隨從也。說文無遙字。此卽其遙字。繇擊者、遠而擊之。如良與客狙擊秦皇帝博浪沙中也。"}]},"𣫐":{"expl":"縣物𣪐擊。从殳𠃬聲。","rad":"殳","fq":"市流切","vol":"03","py":"chóu","duan":[{"e":"縣物𣪐擊也。","n":"此與手部𢶈音義同。𢶈手椎也。"}]},"𧰵":{"expl":"椎毄物也。从殳豖聲。","rad":"殳","fq":"冬毒切","vol":"03","py":"dú","duan":[{"e":"椎擊物也。","n":"謂用椎擊中物。與攴部𢽴、木部椓、音義略同。"}]},"毆":{"expl":"捶毄物也。从殳區聲。","rad":"殳","fq":"烏后切","vol":"03","py":"ōu","duan":[{"e":"捶𣪠物也。","n":"捶、以杖擊也。因謂杖爲捶。捶𣪠物者、謂用杖擊中人物也。按此字卽今經典之𢿛字。廣韵曰。俗作𢿛。是也。唐石經周禮。射鳥氏以弓矢毆烏鳶。方相氏索室毆疫。入壙以戈擊四隅毆方良。冥氏以靈𡔷毆之。庶氏凡毆蠱則令之比之。壷涿氏以炮土之𡔷毆之。今版本皆作𢿛。唐刻獨不誤。張參五經文字殳部毆一口反。攴部無𢿛。殳部毆字正爲經典而出。特未嘗箸之曰又起俱反。欲作𢿛耳。毆訓捶𣪠物。故以弓矢、以戈以靈𡔷、以炮土之𡔷皆捶擊意也。區聲古音在四部。讀一口反。音轉入五部。釋文讀起俱、𠀌于反。淺人乃分析一口爲毆打之字。起俱、𠀌于爲驅逐之字。誤矣。又云。𢿛是馬部驅之古文。夫𢿛在馬部爲古文。驅在殳部爲俗毆字。無庸牽合。驅訓馬馳。毆訓捶𣪠"}]},"毃":{"expl":"擊頭也。从殳高聲。","rad":"殳","fq":"口卓切","vol":"03","py":"qiāo","duan":[{"e":"擊頭也。","n":"淮南書曰。以年之少。爲閭丈人說事。救㪣不給。何道之能明也。高注。老人㪣其頭。自救不暇。按㪣當作毃。呂氏春秋曰。死而操金椎以葬。曰下見六王五伯。將毃其頭矣。按毃今本譌穀。"}]},"殿":{"expl":"擊聲也。从殳𡱂聲。","rad":"殳","fq":"堂練切","vol":"03","py":"diàn","duan":[{"e":"擊聲也。","n":"此字本義未見。假借爲宮殿字。燕禮注。人君爲殿屋。疏云。漢時殿屋四向流水。廣雅曰。堂堭、壂也。爾雅。無室曰榭。郭注。卽今堂堭。然則無室謂之殿矣。又假借爲軍後曰殿。"}]},"瑰":{"expl":"玟瑰。从玉鬼聲。一曰圜好。","rad":"玉","fq":"公回切","vol":"01","py":"ɡuī","duan":[{"e":"玟瑰也。从王。鬼聲。","n":"公回切。十五部。玟瑰本雙聲。後人讀爲曡韻。"}]},"殹":{"expl":"擊中聲也。从殳医聲。","rad":"殳","fq":"於計切","vol":"03","py":"yì","duan":[{"e":"擊中聲也。","n":"此字本義亦未見。酉部醫從殹。王育說殹、惡姿也。一曰殹、病聲也。此與𣪠中聲義近。秦人借爲語詞。詛楚文禮使介老將之以自救殹。薛尚功。所見秦權銘。其於久違殹石𡔷文。汧殹沔沔。權銘殹字、琅邪臺刻石及他秦權秦斤皆作𠃟。然則周秦人以殹爲也可信。詩之兮字、偁詩者或用也爲之。三字通用也。"}]},"段":{"expl":"椎物也。从殳，耑省聲。","rad":"殳","fq":"徒玩切","vol":"03","py":"duàn","duan":[{"e":"椎物也。","n":"周椎曰椎。考工記。段氏爲鎛器。徐丁亂反。劉徒亂反。徐音是也。鎛欲其段之堅。故官曰段氏。函人職曰。凡甲鍛不摰則不堅。鍛亦當作段。金部曰。鍛、小冶也。小冶、小鑄之竈也。後人以鍛爲段字。以段爲分段字。讀徒亂切。分段字自應作𣃔。葢古今字之不同如此。大雅。取厲取碫。毛曰。碫、段石也。鄭曰。段石所以爲段質也。古本當如是。石部碫、段石也。從石段。春秋傳鄭公孫段、字子石。古本當如是。段石與厲石各物。說文訓詁多宗毛傳。"}]},"𣪯":{"expl":"擊空聲也。从殳宮聲。","rad":"殳","fq":"徒冬切","vol":"03","py":"tónɡ","duan":[{"e":"擊空聲也。从殳。宮聲。","n":"徒冬切。又火宮切。九部。按亦作㲁。枯公切。"}]},"殽":{"expl":"相雜錯也。从殳肴聲。","rad":"殳","fq":"胡茅切","vol":"03","py":"xiáo","duan":[{"e":"相襍錯也。","n":"食貨志。鑄錢之情。非殽襍爲巧則不可得贏。按殽謂襍以鉛鐵也。董仲舒傳。賢不肖混殽。經典借爲肴字。禮記借爲效字。"}]},"毅":{"expl":"妄怒也。一曰有決也。从殳豙聲。","rad":"殳","fq":"魚旣切","vol":"03","py":"yì","duan":[{"e":"妄怒也。","n":"𡉚下曰。妄生也。凡氣盛曰妄。"}]},"㲃":{"expl":"揉屈也。从殳从𠧢。𠧢，古文叀字。廏字从此。","rad":"殳","fq":"居又切","vol":"03","py":"jiù","duan":[{"e":"揉屈也。","n":"說文有煣無揉。煣、屈申木也。煣屈、謂柔而屈之。廣韵曰。強擊正與柔屈相反。"}]},"役":{"expl":"戍邊也。从殳从彳。","rad":"殳","fq":"營隻切","vol":"03","py":"yì","duan":[{"e":"戍也。","n":"依韵會訂。戍、守邊也。司馬法曰。弓矢圉。殳矛守。戈𢧢助。凡五兵。長以衞短。短以救長。按圉、古禦字。今周禮注作圍。誤。殳所以守也。故其字從殳。引伸之義凡事勞皆曰役。又生民詩。禾役穟穟。役者、穎之假借。禾部兩引詩皆作禾穎。"}]},"㱾":{"expl":"㱾改，大剛卯也。以逐精鬼。从殳亥聲。","rad":"殳","fq":"古哀切","vol":"03","py":"ɡāi","duan":[{"e":"㱾改、","n":"逗。"}]},"殺":{"expl":"戮也。从殳杀聲。凡殺之屬皆从殺。","rad":"殺","fq":"所八切","vol":"03","py":"shā","duan":[{"e":"戮也。","n":"戈部曰。戮、殺也。"}]},"弒":{"expl":"臣殺君也。《易》曰：“臣弒其君。”从殺省，式聲。","rad":"殺","fq":"式吏切","vol":"03","py":"shì","duan":[{"e":"臣殺君也。","n":"經傳殺弑二字。轉寫旣多譌亂。音家又或拘泥。中無定見。多有殺讀弑者。按述其實則曰殺君。正其名則曰弑君。春秋正名之書也。故言弑不言殺。三傳述實以釋經之書也。故或言殺、或言弑。不必傳無殺君字也。許釋弑曰臣殺君。此可以證矣。殺在古音十五部。弑在一部。本不相通也。弑漢石經公羊作試。二字同式聲也。白虎通引春秋讖曰。弑者、試也。欲言臣子殺其君父不敢卒。𠋫閒司事。可稍稍試之。釋名曰。弑、伺也。說同。皆本文言傳之意。"}]},"璣":{"expl":"珠不圜也。从玉幾聲。","rad":"玉","fq":"居衣切","vol":"01","py":"jī","duan":[{"e":"珠不圜者。","n":"各本作也。今依尙書音義、後漢書注作者。凡經傳沂鄂謂之幾、門橜謂之機。故珠不圜之字从幾。"}]},"𠘧":{"expl":"鳥之短羽飛𠘧𠘧也。象形。凡𠘧之屬皆从𠘧。讀若殊。","rad":"𠘧","fq":"市朱切","vol":"03","py":"shū","duan":[{"e":"鳥之短羽飛𠘧𠘧也。象形。凡𠘧之屬皆从𠘧。讀若殊。","n":"市朱切。按以殳從𠘧聲求之。古音在四部。"}]},"𠘱":{"expl":"新生羽而飛也。从𠘧从彡。","rad":"𠘧","fq":"之忍切","vol":"03","py":"zhěn","duan":[{"e":"新生羽而飛。","n":"此與彡部㐱音同形似而義殊。"}]},"鳧":{"expl":"舒鳧，鶩也。从鳥𠘧聲。","rad":"𠘧","fq":"房無切","vol":"03","py":"fú","duan":[{"e":"舒鳧、","n":"逗。"}]},"寸":{"expl":"十分也。人手卻一寸，動𧖴，謂之寸口。从又从一。凡寸之屬皆从寸。","rad":"寸","fq":"倉困切","vol":"03","py":"cùn","duan":[{"e":"十分也。","n":"度別於分。忖於寸。禾部曰。十髮爲程。一程爲分。十分爲寸。"}]},"寺":{"expl":"廷也。有法度者也。从寸之聲。","rad":"寸","fq":"祥吏切","vol":"03","py":"sì","duan":[{"e":"廷也。","n":"廴部曰。廷、朝中也。漢書注曰。凡府庭所在皆謂之寺。釋名。寺、嗣也。治事者相嗣續於其內。廣韵。寺者、司也。官之所止有九寺。按經典假寺爲侍。詩瞻卬傳曰。寺、近也。周禮注曰。寺之言侍也。凡禮、詩、左傳言寺人皆同。若漢西域白馬駝經來。初止於鴻臚寺。遂取寺名。初置白馬寺。此名之不正者也。"}]},"將":{"expl":"帥也。从寸，𤖕省聲。","rad":"寸","fq":"卽諒切","vol":"03","py":"jiànɡ","duan":[{"e":"帥也。","n":"帥當作𧗿。行部曰。𧗿、將也。二字互訓。儀禮、周禮古文𧗿多作率。今文多作帥。毛詩率時農夫。韓詩作帥。說詳周禮漢讀考。帥者佩巾。漢人假爲率字。率亦𧗿之假也。許造說文。當是本作將𧗿也以自伸其說。經轉寫改竄而非舊矣。後人謂將帥二字去聲與平聲之將、入聲之帥別者。古無是說也。毛詩將字故訓特多。大也、送也、行也、養也、齊也、側也、願也、請也。此等或見爾雅。或不見。皆各依文爲義。亦皆就曡韵雙聲得之。如願請是一義將讀七羊反。故釋爲請也。將讀卽羊反。故皇矣傳釋爲側。釋言及楚茨傳釋爲齊。齊、徐仙民周禮音蔣細反。皆雙聲也。釋言。將、齊也。郭云謂分齊也。引詩或肆或將。此甚明畫或肆蒙或剥。言剥之乃陳於互也。或將蒙或烹。言"}]},"𢒫":{"expl":"繹理也。从工从口从又从寸。工、口，亂也。又、寸，分理之。彡聲。此與𤕦同意。度，人之兩臂爲尋，八尺也。","rad":"寸","fq":"徐林切","vol":"03","py":"xún","duan":[{"e":"繹理也。","n":"謂抽繹而治之。凡治亂必得其緒而後設法治之。引伸之義爲長。方言曰。尋長也。海岱大野之閒曰尋。自關而西秦晉梁益之閒凡物長謂之尋。周官之法度廣爲尋。古文禮假尋爲燅。有司徹乃燅屍俎注。燅、温也。古文燅皆作尋。記或作尋。春秋傳。若可尋也。亦可寒也。案左傳服注。尋之言重也、温也。論語。何注。温、尋也。互相發明。俗本禮注作燖誤。"}]},"專":{"expl":"六寸簿也。从寸叀聲。一曰專，紡專。","rad":"寸","fq":"職緣切","vol":"03","py":"zhuān","duan":[{"e":"六寸簿也。","n":"說文無簿有薄。葢後人易艸爲竹以分別其字耳。六寸薄、葢笏也。曰部云。𡇆、佩也。無笏字。釋名曰。笏、忽也。君有命則書其上。備忽忘也。或曰薄可以簿疏物也。徐廣車服儀制曰。古者貴賤皆執笏。卽今手版也。杜注左傳。珽玉笏也。若今吏之持簿。蜀志。秦宓見廣漢太守。以簿擊頰。裴松之曰。簿、手版也。六寸未聞。疑上𡙜二尺字。玉藻曰。笏度二尺有六寸。此法度也。故其字從寸。"}]},"尃":{"expl":"布也。从寸甫聲。","rad":"寸","fq":"芳無切","vol":"03","py":"fū","duan":[{"e":"布也。","n":"祭義。溥之而橫乎四海。釋文。溥本或作尃。同芳于反。今刻云或作敷。繆也。集韵、韵會可證。說卦傳。震爲專。鄭、虞、姚皆同。王肅、干寶作尃。干云。花之通名爲鋪。花皃謂之𧀮。漢書上林賦。布結縷。史記布作尃。徐廣曰。尃古布字。按尃訓布也。非一字。"}]},"導":{"expl":"導，引也。从寸道聲。","rad":"寸","fq":"徒皓切","vol":"03","py":"dǎo","duan":[{"e":"導。","n":"此複舉字未𠜂者。"}]},"琅":{"expl":"琅玕，似珠者。从玉良聲。","rad":"玉","fq":"魯當切","vol":"01","py":"lánɡ","duan":[{"e":"琅玕、","n":"逗。"}]},"皮":{"expl":"剥取獸革者謂之皮。从又，爲省聲。凡皮之屬皆从皮。","rad":"皮","fq":"符羈切","vol":"03","py":"pí","duan":[{"e":"剝取獸革者謂之皮。","n":"剝、裂也。謂使革與肉分裂也。云革者、析言則去毛曰革。統言則不別也。云者者、謂其人也。取獸革者謂之皮。皮、柀。柀、析也。見木部。因之所取謂之皮矣。引伸凡物之表皆曰皮。凡去物之表亦皆曰皮。戰國策言皮面抉眼王裦僮約言落桑皮椶釋名言皮瓠以爲蓄皆是。"}]},"皰":{"expl":"面生气也。从皮包聲。","rad":"皮","fq":"旁教切","vol":"03","py":"pào","duan":[{"e":"面生气也。","n":"玉篇作面皮生氣也。玄應書一作面生熱氣也。淮南。潰小皰而發痤疽。高曰。皰、面氣也。玄應引作靤。"}]},"皯":{"expl":"面黑气也。从皮干聲。","rad":"皮","fq":"古旱切","vol":"03","py":"ɡǎn","duan":[{"e":"面黑气也。","n":"列子曰。燋然肌色皯黣。"}]},"皸":{"expl":"足坼也。从皮軍聲。","rad":"皮","fq":"矩云切","vol":"03","py":"jūn","duan":[]},"皴":{"expl":"皮細起也。从皮夋聲。","rad":"皮","fq":"七倫切","vol":"03","py":"cūn","duan":[]},"㼱":{"expl":"柔韋也。从北，从皮省，从敻省。凡㼱之屬皆从㼱。讀若耎。一曰若雋。","rad":"㼱","fq":"而兖切","vol":"03","py":"ruǎn","duan":[{"e":"柔韋也。","n":"柔者治之使鞣也。韋、可用之皮也。考工記注曰。蒼頡篇有鞄㼱。"}]},"𤮪":{"expl":"羽獵韋絝。从㼱灷聲。","rad":"㼱","fq":"而隴切","vol":"03","py":"jùn","duan":[{"e":"羽獵韋絝。","n":"羽獵見高唐賦、楊雄傳。服虔曰。士卒負羽也。"}]},"攴":{"expl":"小擊也。从又卜聲。凡攴之屬皆从攴。","rad":"攴","fq":"普木切","vol":"03","py":"pū","duan":[{"e":"小擊也。","n":"手部曰。擊、攴也。此云小擊也。同義而微有別。按此字從又卜聲。又者手也。經典𥻳變作扑。凡尚書、三禮鞭扑字皆作扑。又變爲手。卜聲不改。葢漢石經之體。此手部無扑之原也。唐石經初刻作朴、從木者。唐元度覆挍正之從手。是也。豳風。八月剝棗。假剝爲攴。毛曰。擊也。音義曰。普卜反。"}]},"啟":{"expl":"教也。从攴启聲。《論語》曰：“不憤不啟。”","rad":"攴","fq":"康礼切","vol":"03","py":"qǐ","duan":[{"e":"敎也。从攴。启聲。","n":"康禮切。十五部。"}]},"徹":{"expl":"通也。从彳从攴从育。","rad":"攴","fq":"丑列切","vol":"03","py":"chè","duan":[{"e":"通也。","n":"孟子曰。徹者、徹也。鄭注論語曰。徹通也。爲天下通法也。按詩徹彼桑土。傳曰裂也。徹我牆屋。曰毀也。天命不徹。曰道也。徹我疆土。曰治也。各隨文解之。而通字可以隱栝。古有徹無轍。"}]},"玕":{"expl":"琅玕也。从玉干聲。《禹貢》：“雝州球琳琅玕。”","rad":"玉","fq":"古寒切","vol":"01","py":"ɡān","duan":[{"e":"琅玕也。从王。干聲。","n":"古寒切。十四部。"}]},"肇":{"expl":"擊也。从攴，肈省聲。","rad":"攴","fq":"治小切","vol":"03","py":"zhào","duan":[]},"敏":{"expl":"疾也。从攴每聲。","rad":"攴","fq":"眉殞切","vol":"03","py":"mǐn","duan":[{"e":"疾也。","n":"釋詁、毛傳同。"}]},"敃":{"expl":"彊也。从攴民聲。","rad":"攴","fq":"眉殞切","vol":"03","py":"mǐn","duan":[{"e":"彊也。","n":"釋詁。昏暋強也。按說文暋作𢽹。冒也。則許所據爾雅作敃。強也。昏字從氐省。不從民聲。自俗寫殽譌。音韵亦亂。玉篇謂敃𢽹同字。是也。"}]},"敄":{"expl":"彊也。从攴矛聲。","rad":"攴","fq":"亡遇切","vol":"03","py":"wù","duan":[{"e":"彊也。从攴。矛聲。","n":"亡遇切。古音在三部。"}]},"敀":{"expl":"迮也。从攴白聲。《周書》曰：“常敀常任。”","rad":"攴","fq":"博陌切","vol":"03","py":"pò","duan":[{"e":"迮也。","n":"迮、起也。敀者、起之也。與迫音義同。"}]},"整":{"expl":"齊也。从攴从束从正，正亦聲。","rad":"攴","fq":"之郢切","vol":"03","py":"zhěnɡ","duan":[{"e":"齊也。","n":"齊者、禾麥吐𥝩上平也。引伸爲凡齊之偁。"}]},"效":{"expl":"象也。从攴交聲。","rad":"攴","fq":"胡教切","vol":"03","py":"xiào","duan":[{"e":"象也。","n":"象當作像。人部曰。像、似也。毛詩。君子是則是傚。又民胥傚矣。皆效法字之或體。左傳引詩民胥效矣是也。彼行之而此效之。故俗云報效、云效力、云效驗。廣韵云。俗字作効。今俗分別效力作効、效法效驗作效。尤爲鄙俚。效法之字亦作爻。𣪠辭爻法之謂坤是。亦作殽。禮運殽以降命是。亦作詨。儀禮注引詩君子是則是詨是。皆假借也。"}]},"故":{"expl":"使爲之也。从攴古聲。","rad":"攴","fq":"古慕切","vol":"03","py":"ɡù","duan":[{"e":"使爲之也。","n":"今俗云原故是也。凡爲之必有使之者。使之而爲之則成故事矣。引伸之爲故舊。故曰古、故也。墨子經上曰。故、所得而後成也。許本之。"}]},"政":{"expl":"正也。从攴从正，正亦聲。","rad":"攴","fq":"之盛切","vol":"03","py":"zhènɡ","duan":[{"e":"正也。","n":"論語。孔子曰。政者、正也。"}]},"𢻱":{"expl":"𢾭也。从攴也聲。讀與施同。","rad":"攴","fq":"式支切","vol":"03","py":"shī","duan":[{"e":"𢾭也。","n":"今字作施。施行而𢻱廢矣。施、旗旖施也。經傳多假借。"}]},"元":{"expl":"始也。从一从兀。","rad":"一","fq":"愚袁切","vol":"01","py":"yuán","duan":[{"e":"始也。","n":"見爾雅釋詁。九家易曰。元者、氣之始也。"}]},"福":{"expl":"祐也。从示畐聲。","rad":"示","fq":"方六切","vol":"01","py":"fú","duan":[{"e":"備也。","n":"祭統曰。賢者之祭也。必受其福。非世所謂福也。福者備也。備者百順之名也。無所不順者之謂備。按福備古音皆在第一部。曡韵也。鉉本作祜也。非。祜正世所謂福也。"}]},"珊":{"expl":"珊瑚，色赤，生於海，或生於山。从玉，刪省聲。","rad":"玉","fq":"穌干切","vol":"01","py":"shān","duan":[{"e":"珊瑚、","n":"逗。"}]},"𢾭":{"expl":"𢻱也。从攴尃聲。《周書》曰：“用𢾭遺後人。”","rad":"攴","fq":"芳无切","vol":"03","py":"fū","duan":[{"e":"𢻱也。","n":"此與寸部尃音義同。"}]},"敟":{"expl":"主也。从攴典聲。","rad":"攴","fq":"多殄切","vol":"03","py":"diǎn","duan":[{"e":"主也。","n":"廣韵典字下曰。主也、常也、法也、經也。按凡典法、典守字皆當作敟。經傳多作典。典行而敟廢矣。"}]},"𣀷":{"expl":"數也。从攴麗聲。","rad":"攴","fq":"力米切","vol":"03","py":"lǐ","duan":[{"e":"數也。","n":"大雅。其麗不億毛曰。麗、數也。方言作？。亦云數也。葢？是正字。麗是假借字。從麗者麗㒳也。㒳㒳而數之也。"}]},"數":{"expl":"計也。从攴婁聲。","rad":"攴","fq":"所矩切","vol":"03","py":"shǔ","duan":[{"e":"計也。","n":"六藝六曰九數今九章筭術是也。今人謂在物者去聲。在人者上聲。昔人不盡然。又引伸之義、分析之音甚多。大約速與密二義可包之。"}]},"𣿊":{"expl":"辟𣿊鐵也。从攴从湅。","rad":"攴","fq":"郎電切","vol":"03","py":"liàn","duan":[{"e":"辟潄鐵也。","n":"張協七命。乃鍊乃鑠。萬辟千灌。李注。辟謂㬪之。灌謂鑄之。引典論魏太子丕造百辟寶劔。又引王？刀銘灌辟以數。質象以呈。按辟者、襞之假借也。潄者、段也。𥳑取精鐵。不計數摺㬪段之。因名爲辟潄鐵也。"}]},"孜":{"expl":"汲汲也。从攴子聲。《周書》曰：“孜孜無怠。”","rad":"攴","fq":"子之切","vol":"03","py":"zī","duan":[{"e":"孜孜、","n":"二字今補。"}]},"攽":{"expl":"分也。从攴分聲。《周書》曰：“乃惟孺子攽。”亦讀與彬同。","rad":"攴","fq":"布還切","vol":"03","py":"bān","duan":[{"e":"分也。从攴。分聲。","n":"此形聲包會意。"}]},"𢽎":{"expl":"止也。从攴旱聲。《周書》曰：“𢽎我于艱。”","rad":"攴","fq":"矦旰切","vol":"03","py":"hàn","duan":[{"e":"止也。","n":"𢽎扞古今字。扞行而𢽎廢矣。毛詩傳曰。干、扞也。謂干爲扞之假借。實則干爲𢽎之假借也。手部曰。扞、忮也。"}]},"敳":{"expl":"有所治也。从攴豈聲。讀若豤。","rad":"攴","fq":"五來切","vol":"03","py":"ái","duan":[{"e":"有所治也。","n":"左傳八凱有隤敳。"}]},"敞":{"expl":"平治高土，可以遠望也。从攴尚聲。","rad":"攴","fq":"昌兩切","vol":"03","py":"chǎnɡ","duan":[{"e":"平治高土可㠯遠望也。","n":"惟平治故字從攴。後人乃謂高土可以遠望爲敞而昧其本始矣。"}]},"瑚":{"expl":"珊瑚也。从玉胡聲。","rad":"玉","fq":"戶吳切","vol":"01","py":"hú","duan":[{"e":"珊瑚也。从王。胡聲。","n":"戸吳切。五部。"}]},"敒":{"expl":"理也。从攴伸聲。","rad":"攴","fq":"直刃切","vol":"03","py":"shēn","duan":[{"e":"理也。從攴。伸聲。","n":"直刄切。十二部。按直刄乃誤同敶音耳。東京賦。振天維。？地絡。？謂申布也。玉篇余忍切。？當是敒之或體。"}]},"改":{"expl":"更也。从攴、己。李陽冰曰：“已有過，攴之卽改。”","rad":"攴","fq":"古亥切","vol":"03","py":"ɡǎi","duan":[{"e":"更也。","n":"雙聲。"}]},"變":{"expl":"更也。从攴䜌聲。","rad":"攴","fq":"祕戀切","vol":"03","py":"biàn","duan":[{"e":"更也。从攴。䜌聲。","n":"祕戀切。十四部。"}]},"更":{"expl":"改也。从攴丙聲。","rad":"攴","fq":"古孟切","vol":"03","py":"ɡēnɡ","duan":[{"e":"改也。","n":"更訓改。亦訓繼。不改爲繼。改之亦爲繼。故小雅毛傳曰。庚、續也。用部庸下曰。庚、更事也。列子云。五年之後。心庚念是非。口庚言利害。七年之後。從心之所念庚無是非。從口之所言庚無利害。皆假庚爲更。今人分別平去二音。非古也。"}]},"敕":{"expl":"誡也。臿地曰敕。从攴束聲。","rad":"攴","fq":"恥力切","vol":"03","py":"chì","duan":[{"e":"誡也。","n":"言部曰。誡、敕也。二字互訓。小雅毛傳曰。敕、固也。此謂敕卽飭之假借。飭、致堅也。後人用勑爲敕。力部勑、勞也。洛代切。又或從力作勅。"}]},"𦔼":{"expl":"使也。从攴，𦔮省聲。","rad":"攴","fq":"而涉切","vol":"03","py":"xiè","duan":[{"e":"使也。从攴。耴省聲。","n":"而涉切。八部。"}]},"斂":{"expl":"收也。从攴僉聲。","rad":"攴","fq":"良冉切","vol":"03","py":"liǎn","duan":[{"e":"收也。从攴。僉聲。","n":"良冄切。七部。"}]},"敹":{"expl":"擇也。从攴𥹄聲。《周書》曰：“敹乃甲胄。”","rad":"攴","fq":"洛簫切","vol":"03","py":"liáo","duan":[{"e":"擇也。","n":"粊誓某氏注。言當善𥳑汝甲冑。與許說合。鄭注？謂穿徹之。"}]},"敿":{"expl":"繫連也。从攴喬聲。《周書》曰：“敿乃干。”讀若矯。","rad":"攴","fq":"居夭切","vol":"03","py":"jiǎo","duan":[{"e":"繫連也。","n":"繫當作系。粊誓某氏注云。施汝盾紛。王云。敿盾當有紛繫持之。鄭云。敿猶繫也。按鄭云猶者、鄭意敿是矯拂之偁。矯之而後繫之。非一事也。敿不訓繫故云猶。許云繫連者、謂繫而連之。秦風。龍盾之合。毛云。合而載之。左傳。齊子淵捷從泄聲子。射之。中盾瓦。繇胊汏輈。匕入者三寸。詳傳文。盾正蔽車前。必聯合之以爲車蔽。故云繫連。凡字有專釋經者、敹敿是也。"}]},"㪉":{"expl":"合會也。从攴从合，合亦聲。","rad":"攴","fq":"古沓切","vol":"03","py":"hé","duan":[{"e":"合會也。","n":"見釋詁。今俗云㪉縫。"}]},"𤥗":{"expl":"石之有光，璧𤥗也。出西胡中。从玉戼聲。","rad":"玉","fq":"力求切","vol":"01","py":"liú","duan":[{"e":"石之有光者。璧𤥗也。","n":"者字依李善江賦注補。此當作璧𤥗石之有光者也。恐亦後人倒之。璧𤥗、卽璧流離也。地理志曰。入海市明珠、璧流離。西域傳曰。罽賓國出璧流離。璧流離三字爲名、胡語也。猶珣玕琪之爲夷語。漢武梁祠堂畫有璧流離曰。王者不隱過則至。吳國山碑紀符瑞亦有璧流離。梵書言吠璢璃。吠與璧音相近。西域傳注。孟康曰。璧流離靑色如玉。今本漢書注無璧字。讀者誤認正文璧與流離爲二物矣。今人省言之曰流離。改其字爲璢璃。古人省言之曰璧𤥗。𤥗與流璢音同。楊雄羽獵賦。椎夜光之流離。是古亦省作流離也。"}]},"敶":{"expl":"𠛱也。从攴陳聲。","rad":"攴","fq":"直刃切","vol":"03","py":"chén","duan":[{"e":"列也。","n":"韓詩。信彼南山。惟禹敶之。爾雅。郊外謂之田。李巡云。田、？也。謂？列種榖之處。？者敶之省。素問注云。？古陳字。是也。此本敶列字。後人假借陳爲之。陳行而敶廢矣。亦本軍敶字。？下云。讀若軍敶之敶是也。後人別製無理之陣字。陣行而敶又廢矣。"}]},"敵":{"expl":"仇也。从攴啻聲。","rad":"攴","fq":"徒歴切","vol":"03","py":"dí","duan":[{"e":"仇也。","n":"仇、讎也。左傳曰。怨耦曰仇。仇者兼好惡之詞。相等爲敵。因之相角爲敵。古多假借適爲敵。襍記。計於適者。史記。適人開戸。適不及拒。荀卿子。天子四海之内無客禮。告無適也。文子曰。一也者。無敵之道也。按後人取文子注論語曰。敬者、主一無適之謂。適讀如字。夫主一則有適矣。乃云無適乎。敬者持事振敬。非謂主一也。淮南書曰。一者、萬物之本也。無適之道也。與文子同。正作敵。"}]},"救":{"expl":"止也。从攴求聲。","rad":"攴","fq":"居又切","vol":"03","py":"jiù","duan":[{"e":"止也。","n":"論語。子謂冉有曰。女弗能救與。馬曰。救猶止也。馬意救與止稍別。許謂凡止皆謂之救。"}]},"敓":{"expl":"彊取也。《周書》曰：“敓攘矯虔。”从攴兌聲。","rad":"攴","fq":"徒活切","vol":"03","py":"duó","duan":[{"e":"彊取也。","n":"此是爭敓正字。後人假𡙜爲敓。奪行而敓廢矣。"}]},"斁":{"expl":"解也。从攴睪聲。《詩》云：“服之無斁。”斁，猒也。一曰終也。","rad":"攴","fq":"羊益切","vol":"03","py":"yì","duan":[{"e":"解也。","n":"此與釋音義同。後人區別之。"}]},"赦":{"expl":"置也。从攴赤聲。","rad":"攴","fq":"始夜切","vol":"03","py":"shè","duan":[{"e":"置也。","n":"网部曰。置、赦也。二字互訓。赦與捨音義同。非專謂赦罪也。後捨行而赦廢。赦專爲赦罪矣。"}]},"攸":{"expl":"行水也。从攴从人，水省。","rad":"攴","fq":"以周切","vol":"03","py":"yōu","duan":[{"e":"行水也。","n":"戴侗曰。唐本作水行攸攸也。其中從巛按當作行水攸攸也。行水順其性則安流攸攸而入於海。衞風傳浟浟、流皃是也。作浟者、俗變也。左傳說火曰。鬱攸從之。蒙葺公屋。火之行如水之行。故曰鬱攸。大雅曰。爲韓姞相攸。釋言。攸、所也。水之安行爲攸。故凡可安爲攸。又借爲？字。？、气行皃。水行之攸、气行之？皆主和緩。故或用攸。或用？。"}]},"𢻲":{"expl":"撫也。从攴亾聲。讀與撫同。","rad":"攴","fq":"芳武切","vol":"03","py":"fǔ","duan":[{"e":"撫也。从攴。亡聲。讀與撫同。","n":"亡在九部。無在五部。古借亡爲無。故改讀如撫也。芳武切。"}]},"敉":{"expl":"撫也。从攴米聲。《周書》曰：“亦未克敉公功。”讀若弭。","rad":"攴","fq":"緜婢切","vol":"03","py":"mǐ","duan":[{"e":"撫也。","n":"見釋言。"}]},"敡":{"expl":"侮也。从攴从易，易亦聲。","rad":"攴","fq":"以豉切","vol":"03","py":"yì","duan":[{"e":"侮也。","n":"此與人部㑥義略同。"}]},"琀":{"expl":"送死口中玉也。从玉从含，含亦聲。","rad":"玉","fq":"胡紺切","vol":"01","py":"hán","duan":[{"e":"送死口中玉也。","n":"典瑞曰。大喪共飯玉、含玉。注。飯玉、碎玉以雜米也。含玉、柱左右顚及在口中者。雜記曰。含者執璧將命。則是璧形而小耳。穀梁傳曰。貝玉曰含。按琀、士用貝。見士喪禮。諸矦用璧。見雜記。天子用玉。"}]},"𢾝":{"expl":"戾也。从攴韋聲。","rad":"攴","fq":"羽非切","vol":"03","py":"wéi","duan":[{"e":"戾也。","n":"王注離騷曰。緯繣、乖戾也。廣雅釋訓曰。緯㦎、乖刺也。廣韵卄一麥曰。徽繣、乖違也。說文無繣。緯徽皆𢾝之假借也。"}]},"敦":{"expl":"怒也。詆也。一曰誰何也。从攴𦎫聲。","rad":"攴","fq":"都昆切","vol":"03","py":"dūn","duan":[{"e":"怒也。詆也。一曰誰何也。","n":"皆責問之意。邶風。王事敦我。毛曰。敦厚也。按心部惇、厚也。然則凡云敦厚者、皆假敦爲惇。此字本義訓責問。故從攵。誰何見言部。"}]},"𣀆":{"expl":"朋侵也。从攴从羣，羣亦聲。","rad":"攴","fq":"渠云切","vol":"03","py":"qún","duan":[{"e":"朋侵也。从羣攴。","n":"羣、朋也。攴、侵也。"}]},"敗":{"expl":"毀也。从攴、貝。敗、賊皆从貝，會意。","rad":"攴","fq":"薄邁切","vol":"03","py":"bài","duan":[{"e":"毁也。从攴貝。","n":"會意。貝亦聲。薄邁切。十五部。"}]},"𢿳":{"expl":"煩也。从攴从𤔔，𤔔亦聲。","rad":"攴","fq":"郎段切","vol":"03","py":"luàn","duan":[{"e":"煩也。","n":"煩、熱頭痛也。引伸爲煩亂。按𢿳與𠬪部？、乙部亂、言部䜌、音義皆同。煩曰𢿳。治其煩亦曰亂也。"}]},"寇":{"expl":"暴也。从攴从完。","rad":"攴","fq":"苦候切","vol":"03","py":"kòu","duan":[{"e":"暴也。","n":"暴當是夲部之？。暴疾之字引伸爲暴亂也。"}]},"𢾫":{"expl":"剌也。从攴蚩聲。","rad":"攴","fq":"豬几切","vol":"03","py":"zhǐ","duan":[{"e":"刺也。","n":"刺各本作剌。今按？與㨖雙聲。定作刺。七迹切。"}]},"𢾅":{"expl":"閉也。从攴度聲。讀若杜。","rad":"攴","fq":"徒古切","vol":"03","py":"dù","duan":[{"e":"閉也。","n":"杜門字當作此。杜行而𢾅廢矣。丹部引周書惟其？丹？。此假？爲塗也。"}]},"敜":{"expl":"塞也。从攴念聲。《周書》曰：“敜乃穽。”","rad":"攴","fq":"奴叶切","vol":"03","py":"niè","duan":[{"e":"塞也。","n":"粊誓某氏注云。窒敜之。按士喪禮𣜩人涅廁注。涅、塞也。葢敜其本字。涅其假借字也。異部雙聲相假借。故敜亦音乃結反。"}]},"㪤":{"expl":"㪤盡也。从攴畢聲。","rad":"攴","fq":"卑吉切","vol":"03","py":"bì","duan":[{"e":"㪤、","n":"此複舉字之僅存者。"}]},"𤪎":{"expl":"遺玉也。从玉𣣸聲。","rad":"玉","fq":"以周切","vol":"01","py":"yǒu","duan":[{"e":"遺玉也。","n":"謂贈遺之玉也。蒙上送死言之。何休曰。知死者贈襚。襚猶遺也。大宰、典瑞皆言大喪贈玉。注云。葢璧也。鍇說以山海經遺玉。儻是玉名。則當廁於璙已下十六字閒。"}]},"收":{"expl":"捕也。从攴丩聲。","rad":"攴","fq":"式州切","vol":"03","py":"shōu","duan":[{"e":"捕也。","n":"手部曰。捕、取也。"}]},"鼓":{"expl":"擊鼓也。从攴从壴，壴亦聲。","rad":"攴","fq":"公戶切","vol":"03","py":"ɡǔ","duan":[{"e":"擊𡔷也。从攴壴。","n":"壴者𡔷之省。攴者擊。"}]},"攷":{"expl":"敂也。从攴丂聲。","rad":"攴","fq":"苦浩切","vol":"03","py":"kǎo","duan":[{"e":"敂也。","n":"唐風。子有鐘𡔷。弗擊弗考。毛曰。考亦擊也。攷引伸之義爲攷課。周禮多作攷。他經攷擊、攷課皆作考。假借也。攷敂㬪韵。"}]},"敂":{"expl":"擊也。从攴句聲。讀若扣。","rad":"攴","fq":"苦候切","vol":"03","py":"kòu","duan":[{"e":"擊也。","n":"周禮。凡四方之賔客敂關。宋書山居賦敂弦、卽江賦之叩舷也。舟底曲如弓。故其上曰弦。自扣叩行而敂廢矣。手部扣、牽馬也。無叩字。"}]},"攻":{"expl":"擊也。从攴工聲。","rad":"攴","fq":"古洪切","vol":"03","py":"ɡōnɡ","duan":[{"e":"擊也。","n":"考工記攻木、攻皮、攻金注曰。攻猶治也。此引伸之義。"}]},"敲":{"expl":"橫擿也。从攴高聲。","rad":"攴","fq":"口交切","vol":"03","py":"qiāo","duan":[{"e":"橫擿也。","n":"擿今之擲字。橫擿、橫投之也。左傳。奪之杖以㪣之。釋文曰。說文作毃。此謂左字當作毃也。橫投不必以杖。又按公羊傳。以𣁬摮而殺之。何云。摮猶𢶡也。𢶡謂旁擊頭項。摮卽㪣字。𢶡卽毃字。其字義異故云猶。擿或作檛。誤。"}]},"𢽴":{"expl":"擊也。从攴豖聲。","rad":"攴","fq":"竹角切","vol":"03","py":"zhuó","duan":[{"e":"擊也。","n":"此與木部椓音義皆同。"}]},"𢼟":{"expl":"放也。从攴㞷聲。","rad":"攴","fq":"迂往切","vol":"03","py":"wǎnɡ","duan":[{"e":"放也。","n":"放部曰。逐也。廣韵曰。？曲侵。"}]},"𠩺":{"expl":"坼也。从攴从厂。厂之性坼，果孰有味亦坼。故謂之𠩺，从未聲。","rad":"攴","fq":"許其切","vol":"03","py":"xī","duan":[{"e":"坼也。从攴。","n":"攴可剖物。故從攴。"}]},"斀":{"expl":"去陰之刑也。从攴蜀聲。《周書》曰：“刖劓斀黥。”","rad":"攴","fq":"竹角切","vol":"03","py":"zhuó","duan":[{"e":"去陰之㓝也。","n":"𣀈、？也。大雅。昏椓靡共。鄭云。昏、椓皆奄人也。昏、其官名也。椓、毁陰者也。此假椓爲𣀈也。"}]},"璗":{"expl":"金之美者。與玉同色。从玉湯聲。《禮》：“佩刀，諸矦璗琫而璆珌。”","rad":"玉","fq":"徒朗切","vol":"01","py":"dànɡ","duan":[{"e":"金之美者。","n":"釋器。黃金謂之璗。其美者謂之鏐。許說小異。"}]},"敯":{"expl":"冒也。从攴昬聲。《周書》曰：“敯不畏死。”","rad":"攴","fq":"眉殞切","vol":"03","py":"mǐn","duan":[{"e":"冒也。","n":"今本爾雅。昏𢽹强也。般庚。不昏作勞。鄭注。昏讀爲𢽹。勉也。似鄭所據爾雅與今本亦不同。康誥。𢽹不畏死。孟子作閔。立政。其在受德𢽹。心部作忞。昏聲文聲同部。"}]},"敔":{"expl":"禁也。一曰樂器，椌楬也，形如木虎。从攴吾聲。","rad":"攴","fq":"魚舉切","vol":"03","py":"yǔ","duan":[{"e":"禁也。","n":"與圉禦音同。釋言。禦圉禁也。說文禦訓祀。圉訓囹圉。所以拘罪人。則敔爲禁禦本字。禦行而敔廢矣。古假借作御、作圉。"}]},"㪙":{"expl":"研治也。从攴果聲。舜女弟名㪙首。","rad":"攴","fq":"苦果切","vol":"03","py":"kě","duan":[{"e":"研治也。从攴。果聲。","n":"苦果切。十七部。"}]},"鈙":{"expl":"持也。从攴金聲。讀若琴。","rad":"攴","fq":"巨今切","vol":"03","py":"qín","duan":[]},"𣀘":{"expl":"棄也。从攴𠷎聲。《周書》以爲討。《詩》云：“無我𢿟兮。”","rad":"攴","fq":"市流切","vol":"03","py":"chóu","duan":[{"e":"棄也。","n":"鄭風、毛傳曰。𣀘、棄也。許本毛也。鄭乃讀爲醜。"}]},"畋":{"expl":"平田也。从攴、田。《周書》曰：“畋尒田。”","rad":"攴","fq":"待年切","vol":"03","py":"tián","duan":[{"e":"平田也。","n":"齊風。無田甫田。上田卽畋字。"}]},"攺":{"expl":"㱾改，大剛卯，以逐鬼鬽也。从攴巳聲。讀若巳。","rad":"攴","fq":"古亥切","vol":"03","py":"ɡǎi","duan":[{"e":"㱾攺、","n":"逗。"}]},"敘":{"expl":"次弟也。从攴余聲。","rad":"攴","fq":"徐呂切","vol":"03","py":"xù","duan":[{"e":"次弟也。","n":"咎繇謨曰。天敘有典。釋詁曰。舒業順敘緒也。古或假序爲之。"}]},"㪏":{"expl":"毀也。从攴卑聲。","rad":"攴","fq":"辟米切","vol":"03","py":"bǐ","duan":[{"e":"毁也。从攴。卑聲。","n":"辟米切。十六部。"}]},"㪒":{"expl":"㪏也。从攴兒聲。","rad":"攴","fq":"五計切","vol":"03","py":"ní","duan":[{"e":"㪏也。","n":"按㪏下當云㪏㪒、毁也。㪒下當云㪏㪒也。此全書之例。多爲淺人亂之。篇、韵皆連舉㪏㪒字。知爲曡韵無疑。廣韵云。㪏㪒、擊聲也。"}]},"𩆜":{"expl":"𩆜巫。以玉事神。从玉霝聲。","rad":"玉","fq":"郎丁切","vol":"01","py":"línɡ","duan":[{"e":"巫也。","n":"各本巫上有靈字。乃複舉篆文之未𠜂者也。許君原書。篆文之下以𣜩複寫其字。後人剛之。時有未盡。此因巫下脫也字。以靈巫爲句。失之。今補也字。屈賦九歌。靈偃蹇兮皎服。又靈連蜷兮旣畱。又思靈保兮賢姱。王注皆云。靈、巫也。楚人名巫爲靈。許亦當云巫也無疑矣。引伸之義如謚法曰極知鬼事曰靈。好祭鬼神曰靈。曾子曰陽之精氣曰神。陰之精氣曰靈。毛公曰神之精明者稱靈。皆是也。"}]},"牧":{"expl":"養牛人也。从攴从牛。《詩》曰：“牧人乃夢。”","rad":"攴","fq":"莫卜切","vol":"03","py":"mù","duan":[{"e":"養牛人也。","n":"左傳曰。馬有圉。牛有牧。引伸爲牧民之牧。"}]},"敇":{"expl":"擊馬也。从攴朿聲。","rad":"攴","fq":"楚革切","vol":"03","py":"cè","duan":[{"e":"擊馬也。","n":"所以擊馬者曰箠。亦曰策。以策擊馬曰敇。策專行而敇廢矣。"}]},"𣀔":{"expl":"小舂也。从攴算聲。","rad":"攴","fq":"初絭切","vol":"03","py":"chuàn","duan":[{"e":"小舂也。","n":"臼部言舂者三字。此云小舂。謂稍舂之。廣雅言舂者十一字。有？字。？亦作？。"}]},"𢿲":{"expl":"䚫田也。从攴堯聲。","rad":"攴","fq":"牽遙切","vol":"03","py":"qiāo","duan":[{"e":"䚫田也。","n":"玄應書卷六曰。三蒼？？相擊也。卷十三曰。㪣蒼頡訓詁作？。同苦交切。下擊也。說文橫檛也。擊頭也。據此則說文本無？字。後人増之。其訓葢本作𢶡也。𢶡者、旁擊也。一譌爲䚫。再譌又衍田。莫能通矣。李仁甫本尚無田字。篇、韵皆云？、擊也。"}]},"教":{"expl":"上所施下所效也。从攴从孝。凡教之屬皆从教。","rad":"教","fq":"古孝切","vol":"03","py":"jiào","duan":[{"e":"上所施、下所效也。","n":"教效㬪韵。"}]},"斆":{"expl":"覺悟也。从教从冂。冂，尚矇也。𦥑聲。","rad":"教","fq":"胡覺切","vol":"03","py":"xué","duan":[{"e":"覺悟也。","n":"斆覺㬪韵。學記曰。學然後知不足。知不足然後能自反也。按知不足所謂覺悟也。記又曰。敎然後知困。知困然後能自強也。故曰敎學相長也。兌命曰。學學半。其此之謂乎。按兌命上學字謂敎。言敎人乃益己之學半。敎人謂之學者。學所以自覺。下之效也。敎人所以覺人。上之施也。故古統謂之學也。枚頤僞尙書說命上字作斆、下字作學。乃巳下同玉篇之分別矣。"}]},"卜":{"expl":"灼剥龜也，象灸龜之形。一曰象龜兆之從橫也。凡卜之屬皆从卜。","rad":"卜","fq":"博木切","vol":"03","py":"bǔ","duan":[{"e":"灼剝龜也。","n":"火部灼、？也。刀部剝裂也。灼剝者。謂？而裂之。灼雙聲。剝㬪韵。"}]},"卦":{"expl":"筮也。从卜圭聲。","rad":"卜","fq":"古壞切","vol":"03","py":"ɡuà","duan":[{"e":"所㠯簭也。","n":"所以二字各本刪之。今補。"}]},"卟":{"expl":"卜以問疑也。从口、卜。讀與稽同。《書》云“卟疑”。","rad":"卜","fq":"古兮切","vol":"03","py":"jī","duan":[{"e":"⺊㠯問疑也。","n":"左傳曰。⺊以決疑。不疑何⺊。問疑故從口。俗作乩。"}]},"貞":{"expl":"卜問也。从卜，貝以爲贄。一曰鼎省聲。京房所說。","rad":"卜","fq":"陟盈切","vol":"03","py":"zhēn","duan":[{"e":"⺊問也。","n":"大⺊。凡國大貞。大鄭云。貞、問也。國有大疑。問於蓍龜。後鄭云。貞之爲問。問於正者。必先正之。乃從問焉。引易師貞丈人吉。"}]},"珈":{"expl":"婦人首飾。从玉加聲。《詩》曰：“副筓六珈。”","rad":"玉","fq":"古牙切","vol":"01","py":"jiā","duan":[]},"𠧩":{"expl":"《易》卦之上體也。《商書》曰：“貞曰𠧩。”从卜每聲。","rad":"卜","fq":"荒內切","vol":"03","py":"huì","duan":[{"e":"易卦之上體也。","n":"今尙書左傳皆作悔。疑𠧩是壁中古文。孔安國以今文讀之。易爲悔也。或曰據許則小篆有此字。玉裁謂不然。許書以先小篆後古文爲正例。以先古文後小篆爲變例。曷爲先古文也。於其所從系之也。如斆者古文。學者小篆。斆從敎則必先之。埶然也。然則𠧩本古文非小篆。因其從⺊則系之⺊部。亦埶然也。不曰篆文作悔。亦不於心部悔下列𠧩云古文悔者。本非一字也。小篆無𠧩。而壁中古文有𠧩。不可以不存之於⺊部。凡其存尙書古文之例如此。鄭注尙書云。悔之言晦。晦猶終也。"}]},"占":{"expl":"視兆問也。从卜从口。","rad":"卜","fq":"職廉切","vol":"03","py":"zhān","duan":[{"e":"視兆問也。","n":"周禮占人注曰。占蓍龜之卦兆吉凶。又占人掌占龜注曰。占人亦占簭。言掌占龜者。簭短龜長。主於長者。此云視兆問。亦專謂龜⺊。"}]},"𠧙":{"expl":"卜問也。从卜召聲。","rad":"卜","fq":"市沼切","vol":"03","py":"shào","duan":[{"e":"⺊問也。","n":"疑此卽後人杯珓字。後人所增。"}]},"𠧞":{"expl":"灼龜坼也。从卜；兆，象形。","rad":"卜","fq":"治小切","vol":"03","py":"zhào","duan":[{"e":"灼龜坼也。","n":"周禮注曰。兆者灼龜發於火。其形可占者。其象似玉瓦原之璺罅。是用名之焉。按凡曰朕兆者。朕者如舟之縫。兆者如龜之坼。皆引伸假借也。"}]},"用":{"expl":"可施行也。从卜从中。衞宏說。凡用之屬皆从用。","rad":"用","fq":"余訟切","vol":"03","py":"yònɡ","duan":[{"e":"可施行也。从⺊中。衞宏說。","n":"⺊中則可施行。故取以會意。余訟切。九部。"}]},"甫":{"expl":"男子美稱也。从用、父，父亦聲。","rad":"用","fq":"方矩切","vol":"03","py":"fǔ","duan":[{"e":"男子之美偁也。","n":"春秋。公及邾儀父盟于蔑。穀梁傳曰。儀、字也。父猶傅也。男子之美稱也。士冠禮。字辭曰。伯某甫。仲叔季惟其所當。注。伯仲叔季、長幼之稱。甫是丈夫之美稱。按甫者、男子美偁。某甫者、若言尼甫、嘉甫、孔甫。謂之且字。且者、薦也。五十以伯仲乃謂之字。以下一字爲伯仲叔季之薦。故曰且字也。甫則非字。凡男子皆得偁之。以男子始冠之偁、引伸爲始也。又引伸爲大也。"}]},"庸":{"expl":"用也。从用从庚。庚，更事也。《易》曰：“先庚三日。”","rad":"用","fq":"余封切","vol":"03","py":"yōnɡ","duan":[{"e":"用也。","n":"㬪韵。"}]},"𤰈":{"expl":"具也。从用，茍省。","rad":"用","fq":"平祕切","vol":"03","py":"bèi","duan":[{"e":"具也。","n":"具、供置也。人部曰。僃、愼也。然則防僃字當作僃。全具字當作？。義同而略有區別。今則專用僃而？廢矣。"}]},"甯":{"expl":"所願也。从用，寕省聲。","rad":"用","fq":"乃定切","vol":"03","py":"nìnɡ","duan":[{"e":"所願也。","n":"此與丂部寧音義皆同。許意寧爲願䛐。甯爲所願。略區別耳。二字古皆平聲。故公孫寧儀行父、公羊作公孫甯也。漢郊祀歌。穰穰復正直往甯。師古曰。言獲福旣多。歸於正道。克當往日所願也。甯音寧。"}]},"爻":{"expl":"交也。象《易》六爻頭交也。凡爻之屬皆从爻。","rad":"爻","fq":"胡茅切","vol":"03","py":"yáo","duan":[{"e":"交也。","n":"㬪韵。𣪠辭曰。爻也者、效天下之動者也。"}]},"璩":{"expl":"環屬。从玉豦聲。見《山海經》。","rad":"玉","fq":"彊魚切","vol":"01","py":"qú","duan":[]},"棥":{"expl":"藩也。从爻从林。《詩》曰：“營營青蠅，止于棥。”","rad":"爻","fq":"附袁切","vol":"03","py":"fán","duan":[{"e":"藩也。","n":"艸部曰。藩、屏也。按齊風。折桺樊圃。毛曰。樊、藩也。？者、棥之假借。藩、今人謂之籬笆。籬說文作杝。通俗文曰。柴垣曰㰚。木垣曰柵。字作㰚。六朝人謂之援。謝靈運云激流植援是也。"}]},"㸚":{"expl":"二爻也。凡㸚之屬皆从㸚。","rad":"㸚","fq":"力几切","vol":"03","py":"lǐ","duan":[{"e":"二爻也。","n":"二爻者、交之廣也。以形爲義。故下不云從二爻。珏？疑皆此例。無庸補從二玉、從二余也。玉篇力爾切。廣韵力紙切。云㸚尒布明白。象形也。此附合爾之同韵爲音。大徐力几切。"}]},"爾":{"expl":"麗爾，猶靡麗也。从冂从㸚，其孔㸚，尒聲。此與爽同意。","rad":"㸚","fq":"兒氏切","vol":"03","py":"ěr","duan":[{"e":"麗𤕨、","n":"逗。"}]},"爽":{"expl":"明也。从㸚从大。","rad":"㸚","fq":"疏兩切","vol":"03","py":"shuǎnɡ","duan":[{"e":"明也。","n":"爽本訓明。明之至而差生焉。故引伸訓差也。朝旦之時。半昧半明。故謂之早昧爽。日部曰。昧爽、旦明也。昧之字、三蒼作曶。云曶爽、早朝也。司馬相如傳云。疏逖不閉。曶爽得耀乎光明。今本多闇昧二字。乃用注家語？之耳。"}]},"𡕥":{"expl":"舉目使人也。从攴从目。凡𡕥之屬皆从𡕥。讀若𩖶。","rad":"𡕥","fq":"火劣切","vol":"04","py":"xuè","duan":[{"e":"舉目使人也。","n":"此與言部訹音同、義亦相似。項羽本紀。梁眴籍曰。可行矣。籍遂拔劍斬首頭。然則眴同𡕥也。目部曰。䀏、目搖也。謂有目搖而不使人者。"}]},"夐":{"expl":"營求也。从𡕥，从人在穴上。《商書》曰：“高宗夢得說，使百工夐求，得之傅巗。”巗，穴也。","rad":"𡕥","fq":"朽正切","vol":"04","py":"xuàn","duan":[{"e":"營求也。","n":"營求者、圍帀而求之也。帀而求之。則不遐遺矣。故引伸其義爲遠也。韓詩。于嗟夐兮。云遠也。毛詩作洵。異部假借字。"}]},"䦩":{"expl":"低目視也。从𡕥門聲。弘農湖縣有䦩鄉，汝南西平有䦩亭。","rad":"𡕥","fq":"無分切","vol":"04","py":"wén","duan":[{"e":"氐目視也。","n":"氐各本低。按人部無低。日部曰。氐者、下也。"}]},"𡙋":{"expl":"大視也。从大、𡕥。讀若齤。","rad":"𡕥","fq":"況晚切","vol":"04","py":"quán","duan":[{"e":"大視也。","n":"也廣韵作皃。"}]},"目":{"expl":"人眼。象形。重童子也。凡目之屬皆从目。","rad":"目","fq":"莫六切","vol":"04","py":"mù","duan":[{"e":"人眼也。象形。重、童子也。","n":"象形、緫言之。嫌人不解二。故釋之曰。重其童子也。釋名曰。瞳、重也。膚幕相裹重也。子、小偁也。主謂其精明者也。或曰眸子。眸、冒也。相裹冒也。按人目由白而盧、童而子。層層包裹。故重畫以象之。非如項羽本紀所云重瞳子也。目之引伸爲𢫾目、條目之目。莫六切。三部。"}]},"眼":{"expl":"目也。从目𥃩聲。","rad":"目","fq":"五限切","vol":"04","py":"yǎn","duan":[{"e":"目也。","n":"釋名。眼、限也。瞳子限限而出也。"}]},"琖":{"expl":"玉爵也。夏曰琖，殷曰斚，周曰爵。从玉戔聲。或从皿。","rad":"玉","fq":"阻限切","vol":"01","py":"zhǎn","duan":[]},"𥌡":{"expl":"兒初生瞥者。从目瞏聲。","rad":"目","fq":"邦免切","vol":"04","py":"biǎn","duan":[{"e":"兒初生蔽目者。","n":"蔽目二字各本作瞥。今依篇、韵正。蔽目謂外有物雍蔽之。非牟子之翳也。"}]},"眩":{"expl":"目無常主也。从目玄聲。","rad":"目","fq":"黃絢切","vol":"04","py":"xuàn","duan":[{"e":"目無常主也。","n":"孟子引書。若藥不瞑眩。方言凡飲藥而毒。東齊謂之瞑眩。漢書借爲幻字。犛靬眩人是也。二字音義皆相似。"}]},"眥":{"expl":"目匡也。从目此聲。","rad":"目","fq":"在詣切","vol":"04","py":"zì","duan":[{"e":"目匡也。","n":"謂目之匡當也。木部曰。槶、匡當也。字林作目厓。"}]},"䀹":{"expl":"目㫄毛也。从目夾聲。","rad":"目","fq":"子葉切","vol":"04","py":"jié","duan":[{"e":"目旁毛也。","n":"玄應曰。睫、說文作䀹。釋名作𣮌。云捷、接也。插於目眶而相接也。按大鄭周禮注云。無目朕謂之瞽。有目朕而無見謂之矇。朕或作䀹。無䀹有䀹、卽無朕有朕也。"}]},"𥌭":{"expl":"盧童子也。从目縣聲。","rad":"目","fq":"胡畎切","vol":"04","py":"xuàn","duan":[{"e":"盧童子也。","n":"方言。黸童之子謂之𥌣。宋衞韓鄭之閒曰鑠。按方言𥌣字當是𥌭之字誤。郭釋爲緜邈。云與上文䫵同。非也。緜邈可言目而不可言子。盧童子者、方言所謂黸瞳之子也。盧、黑也。俗作矑。有單言矑者。甘泉賦。玉女無所眺其淸矑是也。童、重也。膚幕相裹重也。子、小偁也。主謂其精明者也。居冣中如縣然。故謂之𥌭。"}]},"瞦":{"expl":"目童子精也。从目喜聲。讀若禧。","rad":"目","fq":"許其切","vol":"04","py":"xī","duan":[{"e":"目童子精瞦也。","n":"當作曰瞦也。精謂精光也。俗作睛。"}]},"𥌗":{"expl":"目㫄薄緻宀宀也。从目𦤝聲。","rad":"目","fq":"武延切","vol":"04","py":"mián","duan":[{"e":"目旁薄緻宀宀也。","n":"矏宀曡韵。自部曰。宀宀不見。按宀宀、微密之皃。目好者必目旁肉好。乃益見目好。矏葢卽方言之䫵。釋言曰。矏、密也引。伸爲凡密之偁也。"}]},"𥇖":{"expl":"大目也。从目非聲。","rad":"目","fq":"芳微切","vol":"04","py":"fēi","duan":[{"e":"大目也。从目。非聲。","n":"芳微切。十五部。"}]},"䁂":{"expl":"大目也。从目臤聲。","rad":"目","fq":"矦簡切","vol":"04","py":"xiàn","duan":[{"e":"大目也。从目。臤聲。","n":"矦𥳑切。古音在十二部。"}]},"睅":{"expl":"大目也。从目旱聲。","rad":"目","fq":"戶版切","vol":"04","py":"hàn","duan":[{"e":"大目也。","n":"左傳。宋城者謳曰。睅其目。杜曰。睅、出目。"}]},"祐":{"expl":"助也。从示右聲。","rad":"示","fq":"于救切","vol":"01","py":"yòu","duan":[{"e":"助也。","n":"古衹作右。"}]},"琛":{"expl":"寶也。从玉，深省聲。","rad":"玉","fq":"丑林切","vol":"01","py":"chēn","duan":[]},"䁔":{"expl":"大目也。从目爰聲。","rad":"目","fq":"況晚切","vol":"04","py":"xuān","duan":[{"e":"大目也。从目。爰聲。","n":"況晚切。十四部。"}]},"瞒":{"expl":"平目也。从目㒼聲。","rad":"目","fq":"母官切","vol":"04","py":"mán","duan":[{"e":"平目也。","n":"平目對出目、深目言之。今俗借爲欺謾字。"}]},"睴":{"expl":"大目出也。从目軍聲。","rad":"目","fq":"古鈍切","vol":"04","py":"ɡùn","duan":[{"e":"大目出也。","n":"目本大而又出其目也。考工記。望其轂。欲其眼也。注。眼出大皃也。陸云。魚懇反。按此鄭謂眼爲睴之假借也。"}]},"矕":{"expl":"目矕矕也。从目䜌聲。","rad":"目","fq":"武版切","vol":"04","py":"mǎn","duan":[{"e":"目矕矕也。","n":"廣雅曰。矕、視也。馬融傳。右矕三塗。左概嵩嶽。此廣雅義也。班固荅賔戲。矕龍虎之文。孟康、蘇林皆曰。矕、被也。此雙聲之假借也。"}]},"睔":{"expl":"目大也。从目、侖。《春秋傳》有鄭伯睔。","rad":"目","fq":"古本切","vol":"04","py":"ɡùn","duan":[{"e":"目大也。从目。侖聲。","n":"古本切。十三部。"}]},"盼":{"expl":"《詩》曰：“美目盼兮。”从目分聲。","rad":"目","fq":"匹莧切","vol":"04","py":"pàn","duan":[{"e":"白黑分也。","n":"玄應書引如此。"}]},"盰":{"expl":"目多白也。一曰張目也。从目干聲。","rad":"目","fq":"古旱切","vol":"04","py":"ɡàn","duan":[{"e":"目白皃。","n":"依玉篇訂。"}]},"眅":{"expl":"多白眼也。从目反聲。《春秋傳》曰：“鄭游眅，字子明。”","rad":"目","fq":"暜班切","vol":"04","py":"pān","duan":[{"e":"多白眼也。","n":"多白眼、見說卦傳。"}]},"睍":{"expl":"出目也。从目見聲。","rad":"目","fq":"胡典切","vol":"04","py":"xiàn","duan":[{"e":"目出皃也。","n":"依玄應訂。考工記曰。深其爪。出其目。邶風。睍睆黃鳥。毛曰。睍睆、好皃。韓詩有𥳑𥳑黃鳥。疑毛作睍睍、韓作𥳑𥳑。睆、說文無。詩、禮記有。詩古本又多作皖。杕杜傳云。實皃。大東傳云。明星皃。檀弓注云。刮節目。又許注淮南曰。睆謂目內白翳也。大徐謂睆爲或睅字。"}]},"矔":{"expl":"目多精也。从目雚聲。益州謂瞋目曰矔。","rad":"目","fq":"古玩切","vol":"04","py":"ɡuàn","duan":[{"e":"目多精也。","n":"矔之言灌注也。"}]},"璫":{"expl":"華飾也。从玉當聲。","rad":"玉","fq":"都郎切","vol":"01","py":"dānɡ","duan":[]},"瞵":{"expl":"目精也。从目粦聲。","rad":"目","fq":"力珍切","vol":"04","py":"lín","duan":[{"e":"目精也。","n":"吳都賦。鷹瞵鶚視。射雉賦。瞵悍目以旁睞。徐爰曰。瞵、視皃。"}]},"窅":{"expl":"深目也。从穴中目。","rad":"目","fq":"烏皎切","vol":"04","py":"yǎo","duan":[{"e":"㴱目皃。","n":"皃字依玉篇正。靈樞經按其腹。窅而不起。漢禮樂志。窅窊桂華。蘇林曰。窅音窅胅之窅。按窅胅即今坳突字。玄應云。倉頡篇作䆟𥥌。上烏交切。墊下也。下徒結切。突也。葛洪字苑。上作凹、陷也。下作凸、起也。䆟𥥌、凹凸許皆不收。然則許用窅胅也。孟康云。窅出窊入。葢對窊言之則訓窅爲出。如徂之爲存苦之爲快。"}]},"眊":{"expl":"目少精也。从目毛聲。《虞書》耄字从此。","rad":"目","fq":"亡報切","vol":"04","py":"mào","duan":[{"e":"目少精也。","n":"孟子。胷中不正、則眸子眊焉。趙曰。眊者、蒙蒙目不明之貌。廣雅。眊眊、思也。謂思勞而目少精也。或作毣毣。"}]},"矘":{"expl":"目無精直視也。从目黨聲。","rad":"目","fq":"他朗切","vol":"04","py":"tǎnɡ","duan":[{"e":"目無精直視也。","n":"後漢梁冀傳。洞精矘眄。注引說文目睛直視。按章懷因旣曰洞精。遂改易說文爲目睛直視。非也。洞精者、謂其目精洞達。矘眄者、謂其流眄矘䁳。此固不妨竝行。遠游曰。旹曖曃其曭莽。王曰。日月晻黮而無光也。矘䁳猶曭莽。"}]},"睒":{"expl":"暫視皃。从目炎聲。讀若白蓋謂之苫相似。","rad":"目","fq":"失冉切","vol":"04","py":"shǎn","duan":[{"e":"暫視皃。","n":"大玄曰。酒作失德。鬼睒其室。此與高明之家、鬼瞰其室語同也。吳都賦。踶跋乎紭中。忘其所以睒睗。江賦。獱𤢺睒瞲乎厱空。"}]},"眮":{"expl":"吳楚謂瞋目、顧視曰眮。从目同聲。","rad":"目","fq":"徒弄切","vol":"04","py":"dònɡ","duan":[{"e":"吳楚謂瞋目、顧視曰眮。","n":"方言。矔眮、轉目也。梁益之閒瞋目曰矔。轉目顧視亦曰矔。吳楚曰眮。按瞋目、顧視是二事。梁益皆曰矔。吳楚皆曰眮也。"}]},"䀣":{"expl":"直視也。从目必聲。讀若《詩》云“泌彼泉水”。","rad":"目","fq":"兵媚切","vol":"04","py":"bì","duan":[{"e":"直視也。从目。必聲。讀若詩云泌彼泉水。","n":"邶風文。今詩作毖。泌之假借也。釋文云。韓詩作秘。說文作䀣。陸氏此語葢誤。鉉本作泌。乃古本也。兵媚切。十五部。"}]},"瞴":{"expl":"瞴婁，微視也。从目無聲。","rad":"目","fq":"莫浮切","vol":"04","py":"móu","duan":[{"e":"瞴婁、","n":"逗。㬪韵。"}]},"钉":{"expl":"蔽人視也。从目幵聲。讀若攜手。一曰直視也。","rad":"目","fq":"","vol":"04","py":"xié","duan":[{"e":"蔽人視也。","n":"鍇曰。映人而視也。"}]},"睌":{"expl":"睌䁂，目視皃。从目免聲。","rad":"目","fq":"武限切","vol":"04","py":"mǎn","duan":[{"e":"睌䁂、","n":"逗。"}]},"琲":{"expl":"珠五百枚也。从玉非聲。","rad":"玉","fq":"暜乃切","vol":"01","py":"bèi","duan":[]},"眂":{"expl":"眂皃。从目氏聲。","rad":"目","fq":"承旨切","vol":"04","py":"shì","duan":[{"e":"視皃也。","n":"馬融長笛賦。特麚昏髟。李曰昏、視也。髟、振髦也。按昏眂一字也。與眡別。眡、古文視。氐聲。在十五部。眂、氏聲。在十六部。宋元以來尟有知氏氐之不可通用者。"}]},"睨":{"expl":"衺視也。从目兒聲。","rad":"目","fq":"研計切","vol":"04","py":"nì","duan":[{"e":"衺視也。","n":"左傳。余與褐之父睨之。中庸。睨而視之。"}]},"𥈆":{"expl":"低目視也。从目冒聲。《周書》曰：“武王惟𥈆。”","rad":"目","fq":"亡保切","vol":"04","py":"mào","duan":[{"e":"氐目視也。从目。冒聲。","n":"亡𠈃切。古音在三部。"}]},"眓":{"expl":"視高皃。从目戉聲。讀若《詩》曰“施罛濊濊”。","rad":"目","fq":"呼哲切","vol":"04","py":"huò","duan":[{"e":"視高皃。","n":"豁目字當作此。"}]},"眈":{"expl":"視近而志遠。从目冘聲。《易》曰：“虎視眈眈。”","rad":"目","fq":"丁含切","vol":"04","py":"dān","duan":[{"e":"視近而志遠。","n":"謂其意㴱沈也。馬云。虎下視皃。"}]},"𢌨":{"expl":"相顧視而行也。从目从㢟，㢟亦聲。","rad":"目","fq":"于線切","vol":"04","py":"yàn","duan":[{"e":"相顧視而行也。从目。从㢟。㢟亦聲。","n":"于線切。廣韵以然切。十四部。"}]},"盱":{"expl":"張目也。从目于聲。一曰朝鮮謂盧童子曰盱。","rad":"目","fq":"況于切","vol":"04","py":"xū","duan":[{"e":"張目也。","n":"張鄭注魏都賦盱衡曰。眉上曰衡。盱、舉眉大視也。釋詁。盱、憂也。此引伸之義。凡憂者亦有張目直視者也。毛詩卷耳曰。盱、憂也。何人斯、都人士皆無傳。然則三詩皆作盱、訓憂。今卷耳作吁。誤也。鄭箋盱爲病。又憂之引伸之義。"}]},"睘":{"expl":"目驚視也。从目袁聲。《詩》曰：“獨行瞏瞏。”","rad":"目","fq":"渠營切","vol":"04","py":"qiónɡ","duan":[{"e":"目驚視也。","n":"唐風毛傳曰。睘睘、無所依也。許不从毛者、許說字非說經也。製字之本義則尒。於从目知之。"}]},"䁴":{"expl":"視而止也。从目亶聲。","rad":"目","fq":"旨善切","vol":"04","py":"zhǎn","duan":[{"e":"視而不止也。","n":"不字依廣韵補。"}]},"䀛":{"expl":"目冥遠視也。从目勿聲。一曰久也。一曰旦明也。","rad":"目","fq":"莫佩切","vol":"04","py":"mèi","duan":[{"e":"目冥遠視也。","n":"冥當作瞑。目雖合而能遠視也。"}]},"珂":{"expl":"玉也。从玉可聲。","rad":"玉","fq":"苦何切","vol":"01","py":"kē","duan":[]},"眕":{"expl":"目有所恨而止也。从目㐱聲。","rad":"目","fq":"之忍切","vol":"04","py":"zhěn","duan":[{"e":"目有所恨而止也。","n":"左傳曰。夫寵而不驕。驕而能降。降而不憾。憾而能眕者鮮矣。許語葢古左傳說。釋言。眕、重也。重亦止意。"}]},"瞟":{"expl":"𥉻也。从目𤐫聲。","rad":"目","fq":"敷沼切","vol":"04","py":"piǎo","duan":[{"e":"𥉻也。","n":"今江蘇俗謂以目伺察曰瞟。音如瓢上聲。"}]},"𥉻":{"expl":"察也。从目祭聲。","rad":"目","fq":"戚細切","vol":"04","py":"qì","duan":[{"e":"察也。","n":"魏都賦。有𥉻吕梁。𥉻察㬪韵。"}]},"睹":{"expl":"見也。从目者聲。","rad":"目","fq":"當古切","vol":"04","py":"dǔ","duan":[{"e":"見也。从目。者聲。","n":"當古切。五部。"}]},"眔":{"expl":"目相及也。从目，从隶省。","rad":"目","fq":"徒合切","vol":"04","py":"dà","duan":[{"e":"目相及也。","n":"隶、及也。石經公羊。祖之所遝聞。今本作逮。中庸。所以逮賤。釋文作遝。此眔與隶音義俱同之證。"}]},"睽":{"expl":"目不相聽也。从目癸聲。","rad":"目","fq":"苦圭切","vol":"04","py":"kuí","duan":[{"e":"目不相聽也。","n":"聽猶順也。二女志不同行。猶二目不同視也。故卦曰睽。人部𠊾卽睽。"}]},"眜":{"expl":"目不明也。从目末聲。","rad":"目","fq":"莫撥切","vol":"04","py":"mò","duan":[{"e":"目不朙也。","n":"吳都賦。相與眜潛險、搜怪奇。劉曰。眜、冒也。李曰。說文眜、門撥切。謂之潛隱之穴也。撥、俗本作廢。"}]},"𥈼":{"expl":"轉目視也。从目般聲。","rad":"目","fq":"薄官切","vol":"04","py":"pán","duan":[{"e":"轉目視也。","n":"般、辟也。象舟之旋。故般目爲轉目。戰國策有田𥈼。"}]},"𥌊":{"expl":"小兒白眼也。从目辡聲。","rad":"目","fq":"蒲莧切","vol":"04","py":"pàn","duan":[{"e":"小兒白眼視也。","n":"依廣韵補視字。"}]},"眽":{"expl":"目財視也。从目𠂢聲。","rad":"目","fq":"莫獲切","vol":"04","py":"mò","duan":[{"e":"目財視也。","n":"財當依廣韵作邪。邪當作？。此與𠂢部、覛音義皆同。財視非其訓也。𠂢者、水之？流別也。九思。目眽眽兮寤終朝。注曰。眽眽、視貌也。古詩十九首。脈脈不得語。李引爾雅。脈、相也。郭璞曰。脈脈謂相視貌。按今釋詁無郭注。釋文曰。覛字又作眽。五經文字有眽字。文選脈皆系眽之譌。"}]},"玘":{"expl":"玉也。从玉己聲。","rad":"玉","fq":"去里切","vol":"01","py":"qǐ","duan":[]},"𥉈":{"expl":"失意視也。从目脩聲。","rad":"目","fq":"他歴切","vol":"04","py":"tì","duan":[]},"𥇜":{"expl":"謹鈍目也。从目𦎫聲。","rad":"目","fq":"之閏切","vol":"04","py":"zhùn","duan":[{"e":"謹鈍目也。从目。𦎧聲。","n":"之閏切。十三部。"}]},"瞤":{"expl":"目動也。从目閏聲。","rad":"目","fq":"如勻切","vol":"04","py":"rún","duan":[{"e":"目動也。","n":"素問。肉瞤瘛。注。動掣也。西京襍記。陸賈曰。目瞤得酒食。"}]},"矉":{"expl":"恨張目也。从目賓聲。《詩》曰：“國步斯矉。”","rad":"目","fq":"符眞切","vol":"04","py":"pín","duan":[{"e":"恨張目也。从目。賓聲。","n":"符眞切。十二部。"}]},"眢":{"expl":"目無明也。从目夗聲。","rad":"目","fq":"一丸切","vol":"04","py":"yuān","duan":[{"e":"目無朙也。","n":"左傳。目於眢井。井無水、若目無朙。故曰眢井。"}]},"睢":{"expl":"仰目也。从目隹聲。","rad":"目","fq":"許惟切","vol":"04","py":"huī","duan":[{"e":"仰目也。","n":"五行志。萬衆睢睢。莊子。而目睢睢。又恣睢讀去聲。暴戾也。"}]},"䀏":{"expl":"目搖也。从目，勻省聲。","rad":"目","fq":"黃絢切","vol":"04","py":"xuàn","duan":[{"e":"目搖也。","n":"項羽本紀。梁眴籍曰。可行矣。"}]},"矆":{"expl":"大視也。从目蒦聲。","rad":"目","fq":"許縛切","vol":"04","py":"huò","duan":[{"e":"大視皃。","n":"依廣韵作皃。魏都賦。㦜焉失容。李曰。今本作䂄。大視也。"}]},"睦":{"expl":"目順也。从目坴聲。一曰敬和也。","rad":"目","fq":"莫卜切","vol":"04","py":"mù","duan":[{"e":"目順也。从目。坴聲。","n":"莫⺊切。廣韵莫六切。三部。"}]},"瞻":{"expl":"臨視也。从目詹聲。","rad":"目","fq":"職廉切","vol":"04","py":"zhān","duan":[{"e":"臨視也。","n":"釋詁、毛傳皆曰。瞻、視也。許別之云臨視。今人謂仰視曰瞻。此古今義不同也。"}]},"珝":{"expl":"玉也。从玉羽聲。","rad":"玉","fq":"況主切","vol":"01","py":"xǔ","duan":[]},"瞀":{"expl":"氐目謹視也。从目敄聲。","rad":"目","fq":"莫候切","vol":"04","py":"mào","duan":[{"e":"氐目謹視也。","n":"氐各本作低。今从宋本。玉篇云。目不明皃。按洪範曰雺恒風若。尙書大傳作瞀。宋世家作霧。漢書五行志作霿。宋書、隨書五行志作瞀。班志云區霿。服虔云人傋瞀。荀卿云傋猶瞀儒。他書或云？瞀。或云？瞀。或云怐愗。說文子部云㝅瞀。皆謂冒亂不明。其字則霿爲正字。雨部云霿、晦也。"}]},"䁲":{"expl":"小視也。从目買聲。","rad":"目","fq":"莫佳切","vol":"04","py":"mái","duan":[{"e":"小視也。","n":"大玄。旌旗絓羅。干戈蛾蛾。師孕唁之。哭且䁲。注。䁲音麻。竊視之稱。"}]},"𥌈":{"expl":"視也。从目監聲。","rad":"目","fq":"古銜切","vol":"04","py":"jiān","duan":[{"e":"視也。","n":"釋詁。監瞻臨涖頫相視也。按釋文曰。監字又作？。然則小雅何用不監。亦可作？。？亦當爲臨視也。"}]},"䁈":{"expl":"省視也。从目，啓省聲。","rad":"目","fq":"苦系切","vol":"04","py":"qì","duan":[{"e":"省視也。","n":"如晝夝之明也。"}]},"相":{"expl":"省視也。从目从木。《易》曰：“地可觀者，莫可觀於木。”《詩》曰：“相鼠有皮。”","rad":"目","fq":"息良切","vol":"04","py":"xiānɡ","duan":[{"e":"省視也。","n":"釋詁、毛傳皆云相視也。此別之云省視。謂察視也。"}]},"瞋":{"expl":"張目也。从目眞聲。","rad":"目","fq":"昌眞切","vol":"04","py":"chēn","duan":[{"e":"張目也。","n":"此與言部謓義略同。"}]},"瞗":{"expl":"目孰視也。从目鳥聲。讀若雕。","rad":"目","fq":"都僚切","vol":"04","py":"diāo","duan":[{"e":"目孰視也。","n":"孰熟正俗字。"}]},"睗":{"expl":"目疾視也。从目易聲。","rad":"目","fq":"施隻切","vol":"04","py":"shì","duan":[{"e":"目疾視也。","n":"鍇本疾作孰。非。古睒睗聯用。雙聲字也。韵會引鍇本作目急視。毛晃增韵、龍龕手鑑皆作急。"}]},"睊":{"expl":"視皃。从目肙聲。","rad":"目","fq":"於絢切","vol":"04","py":"juàn","duan":[{"e":"視皃也。","n":"孟子引晏子睊、睊胥讒。趙曰。睊睊、側目相視。"}]},"𥈾":{"expl":"目深皃。从目、窅。讀若《易》曰“勿䘏”之“䘏”。","rad":"目","fq":"於悅切","vol":"04","py":"yuè","duan":[{"e":"目𥥍皃也。从目窅。","n":"會意。於恱切。十五部。"}]},"璀":{"expl":"璀璨，玉光也。从玉崔聲。","rad":"玉","fq":"七罪切","vol":"01","py":"cuǐ","duan":[]},"睼":{"expl":"迎視也。从目是聲。讀若珥瑱之瑱。","rad":"目","fq":"他計切","vol":"04","py":"tiàn","duan":[{"e":"迎視也。","n":"小雅。題彼脊令。毛云。題、視也。按題者、睼之假借。"}]},"䁙":{"expl":"目相戲也。从目晏聲。《詩》曰：“䁙婉之求。”","rad":"目","fq":"於殄切","vol":"04","py":"yǎn","duan":[{"e":"目相戲也。","n":"方言。䁙䀩視也。東齊曰䁙。吳楊曰䀩。凡以目相戲曰䁙。"}]},"䁊":{"expl":"短深目皃。从目𥄗聲。","rad":"目","fq":"烏括切","vol":"04","py":"wò","duan":[{"e":"短𥥍目皃也。","n":"上文曰窅、曰𥈾皆謂㴱目。此云短㴱者、目匡短而目㴱窐㘣䁂然如捾目也。故从𥄗。"}]},"眷":{"expl":"顧也。从目𢍏聲。《詩》曰：“乃眷西顧。”","rad":"目","fq":"居倦切","vol":"04","py":"juàn","duan":[{"e":"顧也。","n":"大東。睠言顧之。毛曰。睠、反顧也。睠同眷。小明云。睠睠懷顧。皇矣云。乃眷西顧。凡顧眷並言者、顧者還視也。眷者顧之㴱也。顧止於側而巳。眷則至於反。故毛云反顧。許渾言之故云顧也。引伸之訓爲眷屬。史記作婘。"}]},"督":{"expl":"察也。一曰目痛也。从目叔聲。","rad":"目","fq":"冬毒切","vol":"04","py":"dū","duan":[{"e":"察視也。","n":"視字依師古漢書注補。凡師古引說文多有不言說文曰者。車千秋傳。詔丞相御史督二千石求捕。又曰。宜有以敎督。按六經但言董。董卽督也。督者、以中道察視之。人身督脈在一身之中。衣之中縫亦曰督縫。"}]},"睎":{"expl":"望也。从目，稀省聲。海岱之閒謂眄曰睎 。","rad":"目","fq":"香衣切","vol":"04","py":"xī","duan":[{"e":"望也。","n":"西都賦曰。睎秦嶺。古多假？爲睎。如公孫弘傳？世用事、晉虞溥傳？顏之徒是也。"}]},"看":{"expl":"睎也。从手下目。","rad":"目","fq":"苦寒切","vol":"04","py":"kān","duan":[{"e":"睎也。从手下目。","n":"鍇曰。宋玉所謂揚袂障日而望所思也。此會意。苦寒切。十四部。"}]},"瞫":{"expl":"深視也。一曰下視也。又，竊見也。从目覃聲。","rad":"目","fq":"式荏切","vol":"04","py":"shěn","duan":[{"e":"㴱視也。","n":"瞫㴱㬪韵。見其底裏曰㴱視。"}]},"睡":{"expl":"坐寐也。从目、垂。","rad":"目","fq":"是僞切","vol":"04","py":"shuì","duan":[{"e":"坐寐也。","n":"知爲坐寐者、以其字从垂也。左傳曰。坐而假寐。戰國策。讀書欲睡。"}]},"瞑":{"expl":"翕目也。从目、冥，冥亦聲。","rad":"目","fq":"武延切","vol":"04","py":"mínɡ","duan":[{"e":"翕目也。","n":"釋詁、毛傳皆曰。翕、合也。莊子。晝瞑。據槁梧而瞑。引伸爲瞑眩。"}]},"璨":{"expl":"玉光也。从玉粲聲。","rad":"玉","fq":"倉案切","vol":"01","py":"càn","duan":[]},"眚":{"expl":"目病生翳也。从目生聲。","rad":"目","fq":"所景切","vol":"04","py":"shěnɡ","duan":[{"e":"目病生翳也。","n":"玄應曰。翳韵集作瞖。眚、引伸爲過誤。如眚災肆赦。不以一眚掩大德是也。又爲災眚。李奇曰内妖曰眚、外妖曰祥是也。又假爲減省之省。周禮。馮弱犯寡則眚之。注。眚猶人省瘦也。四面削其地。按省瘦亦作㾪瘦。俗云瘦省。"}]},"瞥":{"expl":"過目也。又，目翳也。从目敝聲。一曰財見也。","rad":"目","fq":"普滅切","vol":"04","py":"piē","duan":[{"e":"過目也。","n":"倏忽之意。莊子作覕。"}]},"眵":{"expl":"目傷眥也。从目多聲。一曰瞢兜。","rad":"目","fq":"叱支切","vol":"04","py":"chī","duan":[{"e":"目傷眥也。","n":"釋名曰。目眥傷赤曰䁾。䁾、末也。創在目㒳末也。許謂目傷眥曰眵。與劉異。"}]},"𥋚":{"expl":"目眵也。从目，蔑省聲。","rad":"目","fq":"莫結切","vol":"04","py":"miè","duan":[{"e":"𥋚兜、","n":"逗。"}]},"䀗":{"expl":"涓目也。从目夬聲。","rad":"目","fq":"古穴切","vol":"04","py":"jué","duan":[{"e":"睊也。","n":"按鍇作睊也。鉉作涓目也。皆誤。假令訓睊、則當與睊字類廁。自眚而下皆系目病。廣韵云。䀗、目患。可以得其解矣。刀部曰。剈、一曰窐也。此睊也當作剈目。謂窐目也。窐、下也。"}]},"䀶":{"expl":"目病也。从目良聲。","rad":"目","fq":"力讓切","vol":"04","py":"liànɡ","duan":[{"e":"目病也。","n":"急就篇。眵？䀶。顏曰。䀶、目視不正也。雷公炮炙論序云。目辟䀶？。有五花而自正。注。五加皮是也。"}]},"眛":{"expl":"目不明也。从目未聲。","rad":"目","fq":"莫佩切","vol":"04","py":"mèi","duan":[{"e":"目不朙也。","n":"今音眛。在末韵。眜在隊韵。攷从末之字見於公榖二傳及吳都賦。从未之字未之見。其訓皆曰目不明。何不類居而畫分二処。且玉篇於䀶瞯二字之閒云眛、莫達切。目不明。葢依說文舊次。則知說文原書从末之眜當在此。淺人改爲从未。則又增从末之眜於前也。"}]},"瞯":{"expl":"戴目也。从目閒聲。江淮之間謂眄曰瞯。","rad":"目","fq":"戶閒切","vol":"04","py":"xián","duan":[{"e":"戴目也。","n":"戴目者、上視如戴然。素問所謂戴眼也。諸書所謂望羊也。目上視則多白。故廣韵云。瞯、人目多白也。爾雅釋嘼。一目白？。？同瞯。亦作？。引伸爲闚伺之義。如孟子王使人瞯夫子是。"}]},"眯":{"expl":"艸入目中也。从目米聲。","rad":"目","fq":"莫禮切","vol":"04","py":"mǐ","duan":[{"e":"艸入目中也。","n":"莊子。簸穅眯目。字林云。眯物入眼爲病。然則非獨艸也。"}]},"眺":{"expl":"目不正也。从目兆聲。","rad":"目","fq":"他弔切","vol":"04","py":"tiào","duan":[{"e":"目不正也。","n":"按釋詁、說文皆云覜、視也。然則覜望字不得作眺。月令。可以遠眺望。系假借。小徐注引射雉賦。目不歩體。？眺旁剔。徐爰曰。視瞻不正。常驚惕也。此眺字本義。"}]},"琡":{"expl":"玉也。从玉叔聲。","rad":"玉","fq":"昌六切","vol":"01","py":"chù","duan":[]},"睞":{"expl":"目童子不正也。从目來聲。","rad":"目","fq":"洛代切","vol":"04","py":"lài","duan":[{"e":"目童子不正也。","n":"目精注人故从來。屈賦所謂目成也。洛神賦。明眸善睞。李曰。睞、旁視。"}]},"睩":{"expl":"目睞謹也。从目彔聲。讀若鹿。","rad":"目","fq":"盧谷切","vol":"04","py":"lù","duan":[{"e":"目睞謹也。","n":"娽娽、謹皃也。故睩爲目睞之謹。言注視而又謹畏也。招䰟。娥眉曼睩目騰光。王曰。好目曼澤。時睩睩然視。精光騰馳。感人心也。"}]},"䀺":{"expl":"眣也。从目攸聲。","rad":"目","fq":"敕鳩切","vol":"04","py":"chōu","duan":[{"e":"眣也。","n":"唐人小說。術士相裴夫人。目䀺而緩。主淫。俗誤脩長之脩。"}]},"眣":{"expl":"目不正也。从目失聲。","rad":"目","fq":"丑栗切","vol":"04","py":"dié","duan":[{"e":"目不從正也。","n":"鉉無從字。非。自眺至此皆狀目之邪。所謂匈中不正者也。按公羊傳文六年。䀢晉大夫使與公盟也。何云。以目通指曰䀢。成二年。卻克䀢魯衞之使。使以其辭而爲之請。釋文字皆从矢。云䀢音舜。本又作眣。丑乙反。又大結反。五經文字曰。䀢音舜。見春秋傳。開成石經公羊二皆作䀢。疑此字从矢會意。从失者其譌體。以譌體改說文。淺人無識之故也。陸云又作眣而巳。未嘗云說文作眣也。許云目不从正者、公羊㒳言䀢皆不以正也。"}]},"矇":{"expl":"童矇也。一曰不明也。从目蒙聲。","rad":"目","fq":"莫中切","vol":"04","py":"ménɡ","duan":[{"e":"童蒙也。","n":"此與周易童蒙異。謂目童子如冡覆也。毛公、劉熙、韋昭皆云。有眸子而無見曰矇。鄭司農云。有目朕而無見謂之矇。其意略同。毛說爲長。許主毛說也。禮記。昭然若發矇。謂如發其覆。"}]},"眇":{"expl":"一目小也。从目从少，少亦聲。","rad":"目","fq":"亡沼切","vol":"04","py":"miǎo","duan":[{"e":"小目也。","n":"各本作一目小也。誤。今依易釋文正。履六三。眇能視。虞翻曰。離目不正。兊爲小。故眇而視。方言曰。眇、小也。淮南說山訓。小馬大目不可謂大馬。大馬之目眇謂之眇馬。物有似然而似不然者。按眇訓小目。引伸爲凡小之偁。又引伸爲微妙之義。說文無妙字。眇卽妙也。史記。戸說以眇論。卽妙論也。周易。眇萬物而爲言。陸機賦。眇衆慮而爲言。皆今之妙字也。"}]},"眄":{"expl":"目偏合也。一曰衺視也。秦語。从目丏聲。","rad":"目","fq":"莫甸切","vol":"04","py":"miǎn","duan":[{"e":"目徧合也。","n":"徧各本作偏。誤。今依韵會正。徧、帀也。帀、周也。周、密也。瞑爲臥。眄爲目病。人有目眥全合而短視者。今眄字此義廢矣。"}]},"䀩":{"expl":"眄也。从目各聲。","rad":"目","fq":"盧各切","vol":"04","py":"luò","duan":[{"e":"眄也。","n":"方言。䀩、眄也。吳楊江淮之閒或曰瞯。或曰䀩。"}]},"盲":{"expl":"目無牟子。从目亡聲。","rad":"目","fq":"武庚切","vol":"04","py":"mánɡ","duan":[{"e":"目無牟子也。","n":"牟俗作眸。趙注孟子曰。眸子、目瞳子也。釋名曰。眸、冒也。相裹冒也。毛傳曰。無眸子曰？。鄭司農、韋昭皆云。有目無眸子謂之？。許云目無牟子謂之？。說與毛、鄭異。無牟子者、白黑不分是也。今俗謂靑？。"}]},"䁍":{"expl":"目陷也。从目咸聲。","rad":"目","fq":"苦夾切","vol":"04","py":"qià","duan":[{"e":"目陷也。","n":"廣雅。䁍、陷也。引伸爲凡陷之偁。"}]},"瑄":{"expl":"璧六寸也。从玉宣聲。","rad":"玉","fq":"須缘切","vol":"01","py":"xuān","duan":[]},"瞽":{"expl":"目但有眹也。从目鼓聲。","rad":"目","fq":"公戶切","vol":"04","py":"ɡǔ","duan":[{"e":"目但有朕也。","n":"朕、俗作眹。誤。朕从舟。舟之縫理也。引伸之凡縫皆曰朕。但有朕者、才有縫而巳。釋名曰。瞽、𡔷也。瞑瞑然目平合如𡔷皮也。眄者目合而有見。瞽者目合而無見。按鄭司農云。無目朕謂之瞽。韋昭云。無目曰瞽。皆與許異。"}]},"𥈟":{"expl":"無目也。从目叜聲。","rad":"目","fq":"穌后切","vol":"04","py":"sǒu","duan":[{"e":"無目也。","n":"無目與無牟子別。無牟子者、黑白不分。無目者、其中空洞無物。故字林云。？、目有朕無珠子也。瞽者才有朕而中有珠子。？者才有朕而中無珠子。此又瞽與？之別。凡若此等皆對文則別。散文則通。如詩箋云瞽矇也、史記云瞽叟盲皆是散文則通也。人偁爲瞽叟。其實則盲者也。凡作瞽瞍者、字誤也。國語。瞽獻曲。？獻賦。矇誦。此對文則別也。"}]},"䁝":{"expl":"惑也。从目，榮省聲。","rad":"目","fq":"戶扃切","vol":"04","py":"yínɡ","duan":[{"e":"䁝惑也。","n":"䁝惑雙聲字。各本誤刪䁝。今依廣韵補。淮南鴻烈、漢書皆假營爲䁝。高誘注每云。營、惑也。不誤。小顏多拘牽營字本義。訓爲回繞。非也。營行而䁝廢。"}]},"睉":{"expl":"目小也。从目坐聲。","rad":"目","fq":"昨禾切","vol":"04","py":"cuó","duan":[{"e":"小目也。从目。𡋲聲。","n":"昨禾切。十七部。鉉等曰。尙書。元首叢睉哉。今睉从肉。非是。按脞、馬鄭皆以小釋之。許書無脞。因改爲睉。此恐肊決專輒。攷玄應書卷一於睉字云出字林。不云出說文。許書睉疑後增。"}]},"𥄗":{"expl":"捾目也。从目、㕚。","rad":"目","fq":"烏括切","vol":"04","py":"wò","duan":[{"e":"捾目也。","n":"捾、搯也。吳語、吳世家皆云。子胥以手抉目是也。"}]},"睇":{"expl":"目小視也。从目弟聲。南楚謂眄曰睇。","rad":"目","fq":"特計切","vol":"04","py":"dì","duan":[{"e":"小衺視也。","n":"依小雅小宛正義。言小衺視者、別於睨眄爲衺視也。周易。夷於左股。夷、子夏作睇。鄭、陸同。云旁視曰睇。京作眱。按眱亦睇字也。夏小正。來降燕乃睇。睇者、眄也。内則。不敢睇視。鄭曰。睇、傾視也。"}]},"瞚":{"expl":"開闔目數搖也。从目寅聲。","rad":"目","fq":"舒問切","vol":"04","py":"shùn","duan":[{"e":"開闔目數搖也。","n":"開闔目、玄應本作目開閉。闔一曰閉也。左傳。臾駢曰。使者目動而言肆。懼我也。目動者、開閉數搖也。吕覽曰。夫死其視萬歲猶一瞚也。莊子。兒子終日視而目不瞚。此皆瞚字本義。凡謂與公羊䀢同者、非也。䀏爲目搖。瞚爲目數搖。皆不必以目使人。惟䀢主以目通指。"}]},"眙":{"expl":"直視也。从目台聲。","rad":"目","fq":"丑吏切","vol":"04","py":"chì","duan":[{"e":"直視也。","n":"方言。眙、逗也。西秦謂之眙。郭曰。眙謂住視也。按眙瞪古今字。敕吏、丈證古今音。廣韵七志作眙。四十七證作瞪。別爲二字矣。而瞪下云陸本作眙。攷玄應引通俗文云。直視曰瞪。是知眙之音自一部轉入六部。因改書作瞪。陸法言固知是一字也。"}]},"眝":{"expl":"長眙也。一曰張目也。从目宁聲。","rad":"目","fq":"陟呂切","vol":"04","py":"zhù","duan":[{"e":"長眙也。","n":"外戚傳。飾新宫以延貯。此貯正眝之誤。延貯謂長望也。凡辭章言延佇者亦皆當作眝。說文無佇竚字。惟有宁字。宁佇竚皆訓立。延眝非謂立也。九章。思美人兮。擥涕而竚眙。王逸云。竚立悲哀。文選注。佇眙、立視也。此則訓立。然作眝眙亦無不可。"}]},"盻":{"expl":"恨視也。从目兮聲。","rad":"目","fq":"胡計切","vol":"04","py":"xì","duan":[{"e":"恨視也。","n":"孟子引龍子曰。爲民父母。使民盻盻然。將終歲勤動。不得以養其父母。又稱貸而益之。趙云。盻盻、勤苦不休息之貌。按丁公著本盻盻作肸肸。據趙注則肸近是。作盻者、譌字也。"}]},"祺":{"expl":"吉也。从示其聲。","rad":"示","fq":"渠之切","vol":"01","py":"qí","duan":[{"e":"吉也。","n":"周頌曰。維周之祺。釋言曰。祺、祥也。祺、吉也。"}]},"珙":{"expl":"玉也。从玉共聲。","rad":"玉","fq":"拘竦切","vol":"01","py":"ɡǒnɡ","duan":[]},"𥄱":{"expl":"目不明也。从目弗聲。","rad":"目","fq":"普未切","vol":"04","py":"fèi","duan":[{"e":"目不朙也。从目。弗聲。","n":"普未切。十五部。按此疑卽䀛之或字。"}]},"瞼":{"expl":"目上下瞼也。从目僉聲。","rad":"目","fq":"居奄切","vol":"04","py":"jiǎn","duan":[]},"眨":{"expl":"動目也。从目乏聲。","rad":"目","fq":"側洽切","vol":"04","py":"zhǎ","duan":[]},"眭":{"expl":"深目也。亦人姓。从目圭聲。","rad":"目","fq":"許規切","vol":"04","py":"huī","duan":[]},"眹":{"expl":"目精也。从目灷聲。案：勝字賸，皆从朕聲。疑古以朕爲眹。","rad":"目","fq":"直引切","vol":"04","py":"zhèn","duan":[]},"眸":{"expl":"目童子也。从目牟聲。《說文》直作牟。","rad":"目","fq":"莫浮切","vol":"04","py":"móu","duan":[]},"睚":{"expl":"目際也。从目、厓。","rad":"目","fq":"五隘切","vol":"04","py":"yá","duan":[]},"䀠":{"expl":"左右視也。从二目。凡䀠之屬皆从䀠。讀若拘。又若良士瞿瞿。","rad":"䀠","fq":"九遇切","vol":"04","py":"jù","duan":[{"e":"𠂇又視也。","n":"𠂇又各本作左右。非也。今正。凡詩齊風、唐風、禮記檀弓、曾子問、雜記、玉藻或言瞿。或言瞿瞿。葢皆䀠之假借。瞿行而䀠廢矣。瞿下曰。？隼之視也。若毛傳於齊曰瞿瞿無守之皃、於唐曰瞿瞿然顧禮義也。各依文立義。而爲驚遽之狀則一。"}]},"𥆞":{"expl":"目圍也。从䀠、纾。讀若書卷之卷。古文以爲醜字。","rad":"䀠","fq":"居倦切","vol":"04","py":"juàn","duan":[{"e":"目圍也。","n":"圍當作回。回轉也。"}]},"𥇛":{"expl":"目衺也。从䀠从大。大，人也。","rad":"䀠","fq":"舉朱切","vol":"04","py":"jū","duan":[{"e":"目衺也。从䀠。从大。大人也。","n":"大人也三字疑非是。𥇛與爽奭同意。爽之明大。奭之盛大。𥇛之目衺淫視者大。故皆从大會意。舉朱切。㪺字从此。以小雅仇讀爲㪺求之。古音在三四部。"}]},"玨":{"expl":"二玉相合爲一𤤴。凡𤤴之屬皆从𤤴。","rad":"玨","fq":"古岳切","vol":"01","py":"jué","duan":[{"e":"二玉相合爲一珏。","n":"左傳正義曰。瑴、倉頡篇作珏。云雙玉爲珏。故字从雙玉。按淮南書曰。玄玉百工。注。二玉爲一工。工與珏雙聲。百工卽百珏也。不言从二玉者。義在於形、形見於義也。古岳切。三部。"}]},"眉":{"expl":"目上毛也。从目，象眉之形，上象頟理也。凡眉之屬皆从眉。","rad":"眉","fq":"武悲切","vol":"04","py":"méǐ","duan":[{"e":"目上毛也。","n":"人老則有長眉。豳風、小雅皆言眉壽。毛曰。豪眉也。又曰。秀眉也。方言。眉黎？鮐老也。東齊曰眉。士冠禮古文作麋。少牢饋食禮古文作微。皆假借字也。"}]},"省":{"expl":"視也。从眉省，从屮。","rad":"眉","fq":"所景切","vol":"04","py":"xǐnɡ","duan":[{"e":"視也。","n":"省者、察也。察者、覈也。漢禁中謂之省中。師古曰。言入此中者皆當察視。不可妄也。釋詁曰。省、善也。此引伸之義。大傳曰。大夫有大事省於其君。謂君察之而得其大善也。"}]},"盾":{"expl":"瞂也。所以扞身蔽目。象形。凡盾之屬皆从盾。","rad":"盾","fq":"食問切","vol":"04","py":"dùn","duan":[{"e":"瞂也。","n":"經典謂之干。戈部作？。"}]},"瞂":{"expl":"盾也。从盾犮聲。","rad":"盾","fq":"扶發切","vol":"04","py":"fá","duan":[{"e":"盾也。","n":"秦風。蒙伐有苑。毛曰。伐、中干也。周禮司兵。掌五盾。鄭曰。五盾、干櫓之屬。其名未盡聞也。按木部及韋昭曰。大楯曰櫓。則中干次之。盾之大小略見於釋名。毛云中干、析言之。方言及許統言之。方言曰。盾、自關而東謂之𢧕。或謂之干。關西謂之盾。作𢧕者、或體也。作伐者、假借字。蘇秦傳作㕹。"}]},"𡐠":{"expl":"盾握也。从盾圭聲。","rad":"盾","fq":"苦圭切","vol":"04","py":"kuī","duan":[{"e":"盾握也。","n":"人所握処也。其背脊隆処曰瓦。見左傳。"}]},"自":{"expl":"鼻也。象鼻形。凡自之屬皆从自。","rad":"自","fq":"疾二切","vol":"04","py":"zì","duan":[{"e":"鼻也。象鼻形。","n":"此以鼻訓自。而又曰象鼻形。王部曰。自讀若鼻。今俗以作始生子爲鼻子是。然則許謂自與鼻義同音同。而用自爲鼻者絕少也。凡从自之字、如尸部㞒、臥息也。言部詯、膽气滿聲在人上也。亦皆於鼻息會意。今義從也、己也、自然也皆引伸之義。疾二切。十五部。"}]},"𦤝":{"expl":"宮不見也。闕。","rad":"自","fq":"武延切","vol":"04","py":"mián","duan":[{"e":"宀宀不見也。","n":"臱宀㬪韵。宀、交覆㴱屋也。宀宀、密緻皃。毛詩曰緜緜。韓詩曰民民。其實一也。"}]},"𪞶":{"expl":"此亦自字也。省自者，詞言之气，从鼻出，與口相助也。凡𪞶之屬皆从𪞶。","rad":"𪞶","fq":"疾二切","vol":"04","py":"zì","duan":[]},"皆":{"expl":"俱詞也。从比从𪞶。","rad":"𪞶","fq":"古諧切","vol":"04","py":"jiē","duan":[{"e":"俱䛐也。","n":"司部曰。䛐者、意内而言外也。其意爲俱。其言爲皆。以言表意、是謂意内言外。人部俱下曰皆也、是謂轉注。又偕下曰一曰俱也。則音義皆同。"}]},"魯":{"expl":"鈍詞也。从白，鮺省聲。《論語》曰：“參也魯。”","rad":"𪞶","fq":"郎古切","vol":"04","py":"lǔ","duan":[{"e":"鈍䛐也。","n":"孔注論語曰。魯、鈍也。左傳。魯人以爲敏。謂鈍人也。釋名曰。魯、魯鈍也。國多山水。民性樸鈍。按椎魯、鹵莽皆卽此。"}]},"班":{"expl":"分瑞玉。从𤤴从刀。","rad":"玨","fq":"布還切","vol":"01","py":"bān","duan":[{"e":"分瑞玉。","n":"堯典曰。班瑞于羣后。"}]},"者":{"expl":"別事詞也。从𪞶纺聲。纺，古文旅字。","rad":"𪞶","fq":"之也切","vol":"04","py":"zhě","duan":[{"e":"別事䛐也。","n":"言主於別事。則言者以別之。喪服經。斬衰裳、苴絰杖絞帶、冠繩纓、菅屨者。注曰。者者、明爲下出也。此別事之例。凡俗語云者箇、者般、者回皆取別事之意。不知何時以迎這之這代之。這、魚戰切。"}]},"㿧":{"expl":"詞也。从𪞶𢏚聲。𢏚與疇同。《虞書》：“帝曰：𤾊咨。”","rad":"𪞶","fq":"直由切","vol":"04","py":"chóu","duan":[{"e":"䛐也。","n":"凡毛傳之例云辭也。如芣苢之薄、漢廣之思、草蟲之止、載馳之載、大叔于田之忌、山有扶蘇之且皆是。說文之例云某䛐。自部外。欥爲詮䛐、矣爲語巳䛐、矧爲況䛐、曶爲出气䛐、各爲異䛐、？爲驚䛐、尒䛐之必然也、會䛐之舒也皆是。然則䛐也二字。非例。當作誰䛐也三字。堯典言疇若予者二。皆訓誰。則言疇咨若者二。亦必同。疇咨當先咨後疇。語急故尒。壁中古文字作？。古字也。爾雅。疇孰誰也。字作疇。今字也。許以疇爲假借字。？爲正字。故口部曰？、誰也。則又？疇爲古今字。說文之例。敘篆文合以古籒。？者古文。非小篆也。何以廁此也。凡書、禮古文往往依其部居錄之。不必皆先小篆後古文。亦不必如上部之例、先古文必系以小篆。所以尊經也。尙書"}]},"𥏼":{"expl":"識詞也。从𪞶从亏从知。","rad":"𪞶","fq":"知義切","vol":"04","py":"zhì","duan":[{"e":"識䛐也。","n":"此與矢部知音義皆同。故二字多通用。"}]},"百":{"expl":"十十也。从一、𪞶。數，十百爲一貫。相章也。","rad":"𪞶","fq":"博陌切","vol":"04","py":"bǎi","duan":[{"e":"十十也。从一白。","n":"博陌切。五部。"}]},"鼻":{"expl":"引气自𢌿也。从自、𢌿。凡鼻之屬皆从鼻。","rad":"鼻","fq":"父二切","vol":"04","py":"bí","duan":[{"e":"所㠯引气自畀也。","n":"所以二字今補。口下曰所以言食也、舌下曰所以言別味也是其例。老子注曰。天食人以五氣。从鼻入。地食人以五味。从口入。白虎通引元命苞曰。鼻者肺之使。按鼻一呼一吸相乗除。而引氣於無竆。自讀如今人言自家之自。自本訓鼻。引伸爲自家。"}]},"齅":{"expl":"以鼻就臭也。从鼻从臭，臭亦聲。讀若畜牲之畜。","rad":"鼻","fq":"許救切","vol":"04","py":"xiù","duan":[{"e":"㠯鼻就𦤀也。","n":"玉篇引論語。三齅而作。"}]},"鼾":{"expl":"臥息也。从鼻干聲。讀若汗。","rad":"鼻","fq":"矦幹切","vol":"04","py":"hān","duan":[{"e":"臥息也。","n":"息、鼻息也。廣韵曰。臥氣激聲。許干切。"}]},"鼽":{"expl":"病寒鼻窒也。从鼻九聲。","rad":"鼻","fq":"巨鳩切","vol":"04","py":"qiú","duan":[{"e":"病寒鼻窒也。","n":"月令。民多鼽嚔。窒、？也。"}]},"齂":{"expl":"臥息也。从鼻隶聲。讀若虺。","rad":"鼻","fq":"許介切","vol":"04","py":"xiè","duan":[{"e":"臥息也。","n":"此與尸部㞒音義並同。篇、韵皆衹云鼻息。釋詁云。齂息也。"}]},"皕":{"expl":"二百也。凡皕之屬皆从皕。讀若祕。","rad":"皕","fq":"彼力切","vol":"04","py":"bì","duan":[{"e":"二百也。","n":"卽形爲義。不言从二百。"}]},"𨌥":{"expl":"車笭閒皮篋。古者使奉玉以藏之。从車、𤤴。讀與服同。","rad":"玨","fq":"房六切","vol":"01","py":"fú","duan":[{"e":"車笭閒皮匧也。","n":"也字依玉篇補。東京賦、司馬彪輿服志皆曰。𨌥弩。李善曰。𨌥、車闌閒皮筐。置弩於𨌥曰𨌥弩。師古亦曰。𨌥弩、皮篋盛弩也。今本輿服志𨌥弩二字譌爲𨏟輒弩三字。"}]},"奭":{"expl":"盛也。从大从皕，皕亦聲。此燕召公名。讀若郝。《史篇》名醜。","rad":"皕","fq":"詩亦切","vol":"04","py":"shì","duan":[{"e":"盛也。","n":"釋詁。赫赫躍躍。赫赫、舍人本作奭奭。常武毛傳云。赫赫然盛也。按奭是正字。赫是假借字。小雅。路車有奭。韎韐有奭。毛曰。奭、赤皃。此當作赫。赤部云。赫、火赤皃。奭是假借字。"}]},"習":{"expl":"數飛也。从羽从白。凡習之屬皆从習。","rad":"習","fq":"似入切","vol":"04","py":"xí","duan":[{"e":"數飛也。","n":"數所角切。月令。鷹乃學習。引伸之義爲習孰。"}]},"翫":{"expl":"習猒也。从習元聲。《春秋傳》曰：“翫歲而愒日。”","rad":"習","fq":"五換切","vol":"04","py":"wàn","duan":[{"e":"習猒也。","n":"猒、飽也。此與心部忨音同義近。"}]},"羽":{"expl":"鳥長毛也。象形。凡羽之屬皆从羽。","rad":"羽","fq":"王矩切","vol":"04","py":"yǔ","duan":[{"e":"鳥長毛也。","n":"長毛、別於毛之細縟者。引伸爲五音之羽。晉書樂志云。羽、舒也。陽氣將復。萬物孳育而舒生。漢志曰。羽、宇也。物聚臧宇覆之。爾雅。羽謂之桺。"}]},"翨":{"expl":"鳥之彊羽猛者。从羽是聲。","rad":"羽","fq":"俱豉切","vol":"04","py":"chì","duan":[{"e":"鳥之彊羽猛者。","n":"按當作猛鳥也彊羽。轉寫誤耳。周禮翨氏。掌攻猛鳥。以時獻其羽翮。此釋周禮。故云猛鳥也。猛鳥羽必彊。故其字从羽。此與赤羽、尾長皆从羽文法正同。大鄭翨讀爲翅翼之翅。以是聲、支聲皆在十六部。翨當卽是翅之奇字。後鄭以經云獻羽翮則訓翨爲鳥翮。是聲、鬲聲亦同十六部也。翮、羽莖。舉翮以該羽。許與二鄭說異。"}]},"翰":{"expl":"天雞赤羽也。从羽倝聲。《逸周書》曰：“大翰，若翬雉，一名鷐風。周成王時蜀人獻之。”","rad":"羽","fq":"矦幹切","vol":"04","py":"hàn","duan":[{"e":"天雞也。","n":"也字依御覽補。釋鳥。鶾、天雞。鶾本又作翰。鳥部鶾、訓雉肥翰音者。則此作翰是。天雞、樊光云一名山雞。"}]},"翟":{"expl":"山雉尾長者。从羽从隹。","rad":"羽","fq":"徒歴切","vol":"04","py":"dí","duan":[{"e":"山雉也。","n":"釋鳥。翟、山雉。郭曰。長尾者。按郭翰翟二注葢取諸說文。邶風。右手秉翟。毛曰。翟、翟羽也。庸風。其之翟也。毛曰。翟、褕翟、闕翟。翟羽飾衣也。周禮。王后五路。重翟、厭翟。鄭曰。重翟、重翟雉之羽。厭翟、次其羽使相迫。按翟羽、經傳多假狄爲之。狄人字、傳多假翟爲之。"}]},"翡":{"expl":"赤羽雀也。出鬱林。从羽非聲。","rad":"羽","fq":"房味切","vol":"04","py":"fěi","duan":[{"e":"赤羽雀也。出鬱林。","n":"漢郡。"}]},"翠":{"expl":"青羽雀也。出鬱林。从羽卒聲。","rad":"羽","fq":"七醉切","vol":"04","py":"cuì","duan":[{"e":"靑羽雀也。","n":"釋鳥。翠鷸。郭曰。似燕。紺色。按鳥部鷸下不云翠鳥也。"}]},"翦":{"expl":"羽生也。一曰𠂕羽。从羽前聲。","rad":"羽","fq":"卽淺切","vol":"04","py":"jiǎn","duan":[{"e":"羽生也。","n":"羽初生如前齊也。前、古之翦字。今之歬字。"}]},"气":{"expl":"雲气也。象形。凡气之屬皆从气。","rad":"气","fq":"去旣切","vol":"01","py":"qì","duan":[{"e":"雲气也。","n":"气氣古今字。自以氣爲雲气字。乃又作餼爲廩氣字矣。气本雲气。引伸爲凡气之偁。"}]},"翁":{"expl":"頸毛也。从羽公聲。","rad":"羽","fq":"烏紅切","vol":"04","py":"wēnɡ","duan":[{"e":"頸毛也。","n":"山海經。天帝之山有鳥。黑文而赤翁。漢郊祀歌。赤鴈集。六紛員。殊翁襍。五采文。急就篇鳧翁。按俗言老翁者、假翁爲公也。周禮酒人注假翁爲滃。"}]},"翄":{"expl":"翼也。从羽支聲。","rad":"羽","fq":"施智切","vol":"04","py":"chì","duan":[{"e":"翼也。","n":"飛部曰。？、翄也。翼、篆文？也。"}]},"𦑜":{"expl":"翅也。从羽革聲。","rad":"羽","fq":"古翮切","vol":"04","py":"ɡé","duan":[{"e":"翅也。","n":"小雅。如鳥斯革。毛云。革、翼也。韓詩作？。云翅也。毛用古文假借字。韓用正字。而訓正同。廣雅。？、𦐠、翼也。魏都賦。雲雀踶甍而矯首。壯翼摛鏤於靑霄。注。踶則舉羽翮用勢。若將飛而尙住。此如鳥斯？之謂。許不言詩曰者、省文。非有意也。"}]},"翹":{"expl":"尾長毛也。从羽堯聲。","rad":"羽","fq":"渠遙切","vol":"04","py":"qiáo","duan":[{"e":"尾長毛也。","n":"班固白雉詩。發晧羽兮奮翹英。射雉賦。斑尾揚翹。按尾長毛必高舉。故凡高舉曰翹。詩曰。翹翹錯薪。高則危。詩曰。予室翹翹。"}]},"𦑚":{"expl":"羽本也。一曰羽初生皃。从羽矦聲。","rad":"羽","fq":"乎溝切","vol":"04","py":"hóu","duan":[{"e":"羽本也。","n":"謂入於皮肉者也。按詩、周禮鍭矢。士喪禮作翭矢。葢此矢金鏃。𠊱物而中。如羽本之入肉。故假借通用也。"}]},"翮":{"expl":"羽莖也。从羽鬲聲。","rad":"羽","fq":"下革切","vol":"04","py":"hé","duan":[{"e":"羽莖也。","n":"莖、枝柱也。謂衆枝之柱。翮亦謂一羽之柱。莖翮雙聲。唐風。肅肅鴇行。毛曰。行、翮也。亦於雙聲求之。上文云鴇羽、鴇翼。故不得以行列釋之也。"}]},"𦐛":{"expl":"羽曲也。从羽句聲。","rad":"羽","fq":"其俱切","vol":"04","py":"qú","duan":[{"e":"羽曲也。","n":"凡從句者皆訓曲。釋木曰。句如羽喬。上句曰喬。然則羽曲者、謂上句反鄉。"}]},"𦐧":{"expl":"羽之𦐧風。亦古諸侯也。一曰射師。从羽幵聲。","rad":"羽","fq":"五計切","vol":"04","py":"yì","duan":[{"e":"羽之𦐧風。","n":"𦐧疑當爲幵。幵、平也。羽之幵風、謂摶扶搖而上之狀。"}]},"翥":{"expl":"飛舉也。从羽者聲。","rad":"羽","fq":"章庶切","vol":"04","py":"zhù","duan":[{"e":"飛舉也。","n":"方言曰。翥、舉也。楚謂之翥。郭云。謂軒翥也。西京賦。鳳鶱翥於甍標。"}]},"翕":{"expl":"起也。从羽合聲。","rad":"羽","fq":"許及切","vol":"04","py":"xī","duan":[{"e":"起也。","n":"釋詁、毛傳皆云。翕、合也。許云起也者、但言合則不見起。言起而合在其中矣。翕从合者、鳥將起必斂翼也。"}]},"氛":{"expl":"祥气也。从气分聲。","rad":"气","fq":"符分切","vol":"01","py":"fēn","duan":[{"e":"祥气也。","n":"謂吉凶先見之氣。左傳曰。非祭祥也。喪氛也。杜注。氛、惡氣也。晉語曰。見翟柤之氛。注。氛、祲氛。凶象也。凶曰氛。吉曰祥。玉裁按。統言則祥氛二字皆兼吉凶。析言則祥吉氛凶耳。許意是統言。左傳又曰。楚氛甚惡。杜注。氛、氣也。可見不容分別。"}]},"翾":{"expl":"小飛也。从羽瞏聲。","rad":"羽","fq":"許緣切","vol":"04","py":"xuān","duan":[{"e":"小飛也。","n":"九歌。翾飛兮翠曾。按荀子。喜則輕而翾。假翾爲儇也。"}]},"翬":{"expl":"大飛也。从羽軍聲。一曰伊、雒而南，雉五采皆備曰翬。《詩》曰：“如翬斯飛。”","rad":"羽","fq":"許歸切","vol":"04","py":"huī","duan":[{"e":"大飛也。","n":"釋鳥曰。鷹隼醜。其飛也翬。郭云。𡔷翅翬翬然疾。"}]},"翏":{"expl":"高飛也。从羽从㐱。","rad":"羽","fq":"力救切","vol":"04","py":"liù","duan":[{"e":"高飛也。从羽㐱。","n":"㐱、新生羽而飛也。羽毛新生豐滿。可以高飛也。莊子翏翏、謂長風之聲。此引伸之義。力救切。三部。匡謬正俗云。？古文戮字。湯？云。予則孥？女。按？正？之譌。假借字。"}]},"翩":{"expl":"疾飛也。从羽扁聲。","rad":"羽","fq":"芳連切","vol":"04","py":"piān","duan":[{"e":"疾飛也。","n":"魯頌傳曰。翩、飛皃。泰六四翩翩。虞曰。離飛故翩翩。"}]},"翜":{"expl":"捷也。飛之疾也。从羽夾聲。讀若瀒。一曰俠也。","rad":"羽","fq":"山洽切","vol":"04","py":"shà","duan":[{"e":"捷也。","n":"釋詁曰。際接翜捷也。郭云。捷謂相接續也。按翜捷皆謂敏疾。敏疾則際按無痕。其義相成也。許舉其本義。故下云飛之疾也。以釋从羽。今俗語霎時者當作此。止部曰。？、疾也。俗通用捷。疌翜㬪韵。"}]},"翊":{"expl":"飛㒵。从羽立聲。","rad":"羽","fq":"與職切","vol":"04","py":"yì","duan":[{"e":"飛皃。","n":"漢郊祀歌。神之來。泛翊翊。甘露降。慶雲集。師古曰。翊音弋入切。又音立。按翊字本義本音僅見於此。經史多假爲昱字。以同立聲也。釋言曰。翌、明也。尙書五言翌日。皆訓明日。一言翌室。訓明室。天寶閒盡改爲翼。凡尙書翼字訓敬、訓輔。與訓明者溷同無別、自衞包始。漢、魏、晉、唐初、皆有翌日無翼日。郭璞、玄應、李善引尙書皆作翌日。自同其字又同其音。以七部立聲之字讀一部異聲之與職切。字書韵書承譌襲繆。小顏弋入、力入之音無有採者矣。又吳都賦云翋𦑶。廣雅。翋𦑶、飛也。力荅徒合二切。翋同翊。此亦翊之本義本音也。"}]},"𦐇":{"expl":"飛盛皃。从羽从冃。","rad":"羽","fq":"土盍切","vol":"04","py":"tà","duan":[{"e":"飛盛皃。","n":"按廣雅翋𦑶、卽說文之翊𦐇。㬪韵字也。"}]},"𦐉":{"expl":"飛盛㒵。从羽之聲。","rad":"羽","fq":"侍之切","vol":"04","py":"chī","duan":[{"e":"羽盛皃也。","n":"羽、大徐作飛。集韵。？？、羽翼盛。"}]},"翱":{"expl":"翱翔也。从羽皐聲。","rad":"羽","fq":"五牢切","vol":"04","py":"áo","duan":[{"e":"翱、","n":"此複舉字之未刪者。"}]},"翔":{"expl":"回飛也。从羽羊聲。","rad":"羽","fq":"似羊切","vol":"04","py":"xiánɡ","duan":[{"e":"回飛也。","n":"釋鳥。鳶烏醜。其飛也翔。郭云。布翅翱翔。高注淮南曰。翼上下曰翱。直刺不動曰翔。曲禮。室中不翔。鄭曰。行而張拱曰翔。此引伸假借也。按翱翔統言不別。析言則殊。高注析言之也。夏小正。黑鳥浴。浴也者、飛乍高乍下也。此所謂翼上下曰翱也。"}]},"士":{"expl":"事也。數始於一，終於十。从一从十。孔子曰：“推十合一爲士。”凡士之屬皆从士。","rad":"士","fq":"鉏里切","vol":"01","py":"shì","duan":[{"e":"事也。","n":"豳風、周頌傳凡三見。大雅武王豈不仕傳亦云。仕、事也。鄭注表記申之曰。仕之言事也。士事㬪韻。引伸之、凡能事其事者偁士。白虎通曰。士者、事也。任事之稱也。故傳曰。通古今、辯然不、謂之士。"}]},"翽":{"expl":"飛聲也。从羽歲聲。《詩》曰：“鳳皇于飛，翽翽其羽。”","rad":"羽","fq":"呼會切","vol":"04","py":"huì","duan":[{"e":"飛聲也。","n":"詩釋文引說文。羽聲也。字林。飛聲也。此俗以字林改說文之證。毛傳云。翽翽、衆多也。此謂鳳飛羣鳥從以萬數。毛比傅下文多吉士、多吉人爲說。許說其字義。故不同也。"}]},"翯":{"expl":"鳥白肥澤皃。从羽高聲。《詩》云：“白鳥翯翯。”","rad":"羽","fq":"胡角切","vol":"04","py":"xué","duan":[{"e":"鳥白肥澤皃。","n":"大雅。白鳥翯翯。毛傳曰。翯翯、肥澤也。釋文引字林亦云。烏白肥澤曰翯。毛則言肥澤、而白在其中也。白部曰。㿥、鳥之白也。何晏賦。㿥㿥白鳥。翯與㿥音義皆同。賈誼書作皜皜。孟子作鶴鶴。趙注與毛傳合。"}]},"䍿":{"expl":"樂舞。以羽纣自翳其首，以祀星辰也。从羽王聲。讀若皇。","rad":"羽","fq":"胡光切","vol":"04","py":"huánɡ","duan":[{"e":"樂舞。㠯羽？自翳其首。㠯祀星辰也。","n":"？同𦒇。翳猶覆也。周禮舞師云。敎皇舞。帥而舞旱暵之事。注。鄭司農云。䍿舞、蒙羽舞。書或爲皇。或爲義。樂師云。有皇舞。注。故書皇作䍿。鄭司農云。䍿舞者、以羽冒覆頭上。衣飾翡翠之羽。䍿讀爲皇。書亦或爲皇。按大鄭從故書作䍿。後鄭則從今書作皇。云襍五采羽如鳳皇色。持以舞。許同大鄭。惟不云衣飾翡翠羽。又不同經文舞旱暵之事。而云祀星辰耳。葢本賈侍中周官解故。○禮注文今攷定。"}]},"翇":{"expl":"樂舞。執全羽以祀社稷也。从羽犮聲。讀若紱。","rad":"羽","fq":"分勿切","vol":"04","py":"fú","duan":[{"e":"樂舞。執全羽㠯祀社稷也。","n":"樂師有帗舞。有羽舞。注。故書帗作？。皇作䍿。鄭司農云。？舞者、全羽。羽舞者、析羽。社稷以？。玄謂帗析五采繒。今靈星舞子持之是也。按今本脫帗作？三字。又將大鄭注？改爲帗。非也。舞師注亦有脫。大鄭及許皆從故書作？。以字从羽。故知爲全羽。後鄭從今書作帗。以字从巾。故知析五采繒也。"}]},"翿":{"expl":"翳也。所以舞也。从羽𣪐聲。《詩》曰：“左執翿。”","rad":"羽","fq":"徒到切","vol":"04","py":"dào","duan":[{"e":"翳也。所㠯舞也。","n":"釋言曰。翢、𦇨也。𦇨、翳也。王風毛傳曰。翿、𦇨也。翳也。𦒇翢翿同字。毛傳本釋言。翳也之上當本有𦇨字。此熠燿㷠也、㷠熒火也之例也。陳風傳則約之云。翿、翳也。許本之。許無𦇨字者、無每部。亦無縣部。無所入也。王風音義曰。𦇨俗作纛。爾雅音義曰。𦇨字又作纛。五經文字曰。𦇨作纛譌。開成石經周禮、爾雅正作𦇨。今本爾雅音義譌舛。葉林宗鈔本不誤。𦇨从縣𣫭會意。與䋣从糸𣫭會意同。从𣫭者、如艸之盛也。淺人改从毒。謂爲諧聲耳。郭注爾雅云。今之羽葆幢。舞者所以自蔽翳。王風。左執翿。陳風。值其鷺羽。值其鷺翿。傳云。值、持也。鷺鳥之羽可以爲翳。䍿字下云。樂舞、以羽？自翳其首。皆謂舞也。射則用翿旌。見鄉射禮。喪則天子鄉師執𦇨"}]},"翳":{"expl":"華蓋也。从羽殹聲。","rad":"羽","fq":"於計切","vol":"04","py":"yì","duan":[{"e":"華葢也。","n":"司馬相如傳曰。泰山梁父設壇場。望華葢。劉歆遂初賦。奉華葢於帝側。西京賦。華葢承辰。薛綜曰。華葢星覆北斗。王者法而作之。蔡邕曰。凡乗輿車皆羽葢金華爪。張衡賦曰。羽葢葳㽔。葩瑵曲莖。又曰。樹翠羽之高葢。薛綜云。羽葢、以翠羽覆車葢也。按以羽故其字从羽。翳之言蔽也。引伸爲凡蔽之偁。在上在旁皆曰翳。"}]},"翣":{"expl":"棺羽飾也。天子八，諸侯六，大夫四，士二。下垂。从羽妾聲。","rad":"羽","fq":"山洽切","vol":"04","py":"shà","duan":[{"e":"棺羽飾也。","n":"羽衍文。棺飾本周禮。周禮。喪縫棺飾焉。衣翣桺之材。檀弓。周人牆置翣。又飾棺牆置翣。鄭曰。翣以布衣木如攝與。喪大記注。漢禮。翣以木爲筐。廣三尺。高二尺四寸。方、㒳角高。衣以白布。畫者畫雲氣。其餘各如其象。柄長五尺。車行。使人持之而從。旣窆。樹於壙中。按翣桺皆棺飾也。鄭云以布衣木。又引漢禮況之。經無用羽明文。以其物下垂。故从羽也。"}]},"翻":{"expl":"飛也。从羽番聲。或从飛。","rad":"羽","fq":"孚袁切","vol":"04","py":"fān","duan":[]},"翎":{"expl":"羽也。从羽令聲。","rad":"羽","fq":"郎丁切","vol":"04","py":"línɡ","duan":[]},"𦏺":{"expl":"飛聲。从羽工聲。","rad":"羽","fq":"户公切","vol":"04","py":"hónɡ","duan":[]},"壻":{"expl":"夫也。从士胥聲。《詩》曰：“女也不爽，士貳其行。”士者，夫也。讀與細同。","rad":"士","fq":"穌計切","vol":"01","py":"xù","duan":[{"e":"夫也。","n":"夫者丈夫也。然則壻爲男子之美稱。因以爲女夫之稱。釋親曰。女子子之夫爲壻。"}]},"隹":{"expl":"鳥之短尾緫名也。象形。凡隹之屬皆从隹。","rad":"隹","fq":"職追切","vol":"04","py":"zhuī","duan":[{"e":"鳥之短尾緫名也。","n":"短尾名隹。別於長尾名鳥。云緫名者、取數多也。亦鳥名。翩翩者鵻。夫不也。本又作隹。"}]},"雅":{"expl":"楚烏也。一名鸒，一名卑居。秦謂之雅。从隹牙聲。","rad":"隹","fq":"五下切","vol":"04","py":"yǎ","duan":[{"e":"楚烏也。一名鸒。一名卑居。秦謂之雅。","n":"楚烏、烏屬。其名楚烏。非荆楚之楚也。鳥部曰。𪇬、卑居也。卽此物也。酈善長曰。按小爾雅。純黑返哺謂之慈烏。小而腹下白、不返哺者謂之雅烏。爾雅曰。鸒斯、卑居也。孫炎曰。卑居、楚烏。犍爲舍人以爲壁居。說文謂之雅。莊子曰雅賈。馬融亦曰賈烏。按卑居之爲壁居。如史記卑耳之山卽齊語壁耳之山。卑壁同十六部。卑俗作鵯、音匹。非也。雅之訓亦云素也。正也。皆屬假借。"}]},"隻":{"expl":"鳥一枚也。从又持隹。持一隹曰隻，二隹曰雙。","rad":"隹","fq":"之石切","vol":"04","py":"zhī","duan":[{"e":"鳥一枚也。","n":"雙下曰。隹二枚也。隹鳥統言不別耳。"}]},"雒":{"expl":"鵋䳢也。从隹各聲。","rad":"隹","fq":"盧各切","vol":"04","py":"luò","duan":[{"e":"忌欺也。","n":"各本作鵋䳢。今考爾雅音義。當作忌欺。釋鳥曰。鵅、鵋䳢。玄應引作忌欺。釋鳥又曰。怪鴟。舍人曰。謂鵂？也。南陽名鉤鵅。一名忌欺。然則忌欺與怪鴟一物。玄應以爲關西名訓矦。關東名訓狐。皆此也。按萑部？舊、舊畱。不云卽雒。未知許意爲一不。鵅卽雒字。各家音格。但今江蘇此鳥尙呼鉤雒鴟。雒音同洛。則音格者南北語異耳。又按自魏黃初以前伊雒字皆作此。與雍州渭洛字迥判。曹丕云。漢忌水。改洛爲雒。欺世之言也。詳水部。"}]},"閵":{"expl":"今閵。似雊鵒而黃。从隹，𨳏省聲。","rad":"隹","fq":"良刃切","vol":"04","py":"lìn","duan":[{"e":"今閵、","n":"逗。"}]},"巂":{"expl":"周燕也。从隹，屮象其冠也。㕯聲。一曰蜀王望帝，婬其相妻，慙亡去，爲子巂鳥。故蜀人聞子巂鳴，皆起云“望帝”。","rad":"隹","fq":"戶圭切","vol":"04","py":"ɡuī","duan":[{"e":"巂周、","n":"逗。"}]},"𨾔":{"expl":"鳥也。从隹方聲。讀若方。","rad":"隹","fq":"府良切","vol":"04","py":"fānɡ","duan":[{"e":"𨾔鳥也。","n":"此與鳥部䲱各物。"}]},"雀":{"expl":"依人小鳥也。从小、隹。讀與爵同。","rad":"隹","fq":"卽略切","vol":"04","py":"què","duan":[{"e":"依人小鳥也。","n":"今俗云麻雀者是也。其色褐。其鳴節節足足。禮器象之曰爵。爵與雀同音。後人因書小鳥之字爲爵矣。月令。鴻鴈來賔。爵入大水爲蛤。高注吕覽曰。賔爵、老爵也。棲宿於人堂宇。有似賔客。故謂之賔爵。又有似雀而色純黃者曰黃雀。戰國策云。俛啄白粒。仰棲茂樹。詩所謂黃鳥也。"}]},"猚":{"expl":"鳥也。从隹犬聲。睢陽有猚水。","rad":"隹","fq":"五加切","vol":"04","py":"yá","duan":[{"e":"猚鳥也。","n":"也廣韵作名。"}]},"雗":{"expl":"雗鷽也。从隹倝聲。","rad":"隹","fq":"侯榦切","vol":"04","py":"hàn","duan":[{"e":"雗鷽也。","n":"三字一句。此與鳥部鶾各物。鳥部曰。雗鷽、山鵲。知來事鳥也。"}]},"壯":{"expl":"大也。从士爿聲。","rad":"士","fq":"側亮切","vol":"01","py":"zhuànɡ","duan":[{"e":"大也。","n":"方言曰。凡人之大謂之奘。或謂之壯。尋說文之例。當云大士也。故下云从士。此葢淺人𠜂士字。"}]},"雉":{"expl":"有十四種：盧諸雉，喬雉，鳪雉，鷩雉，秩秩海雉，翟山雉，翰雉，卓雉，伊洛而南曰翬，江淮而南曰搖，南方曰𢏚，東方曰钕，北方曰稀，西方曰蹲。从隹矢聲。","rad":"隹","fq":"直几切","vol":"04","py":"zhì","duan":[{"e":"有十四穜。","n":"目下文。"}]},"雊":{"expl":"雄雌鳴也。雷始動，雉鳴而雊其頸。从隹从句，句亦聲。","rad":"隹","fq":"古候切","vol":"04","py":"ɡòu","duan":[{"e":"雄雉鳴也。","n":"言雄雉鳴者、別於？之爲雌雉鳴也。小雅。雉之朝雊。尙求其雌。邶風。有鷕雉鳴。下云。雉鳴求其牡。按鄭注月令云。雊、雉鳴也。是雊不必系雄。？則毛公系諸雌。亦望文立訓耳。若潘安仁賦。雉鷕鷕而朝雊。此則所謂渾言不別也。顏延年、顏之推皆云潘誤用。未孰於訓詁之理。"}]},"雞":{"expl":"知時畜也。从隹奚聲。","rad":"隹","fq":"古兮切","vol":"04","py":"jī","duan":[{"e":"知時畜也。从隹。奚聲。","n":"古兮切。十六部。"}]},"雛":{"expl":"雞子也。从隹芻聲。","rad":"隹","fq":"士于切","vol":"04","py":"chú","duan":[{"e":"雞子也。","n":"雞子、雞之小者也。淮南。天子以雛嘗黍。高曰。雛、新雞也。吕覽注云。雛、春雡也。郭景純言今呼少雞爲？。則二注正同。王制。春薦韭。韭以？。？謂少雞。古者少雞亦曰？。方言。雞雛、徐魯之閒謂之？子。按雛引伸爲凡鳥子細小之偁。釋鳥曰。生哺？、生噣雛。"}]},"雡":{"expl":"鳥大雛也。从隹翏聲。一曰雉之莫子爲雡。","rad":"隹","fq":"力救切","vol":"04","py":"liù","duan":[{"e":"鳥大雛也。","n":"此與？別。而俗通用鷚。高注吕覽曰。雛、春鷚也。吳都賦。翳薈無？鷚。按爾雅音義、文選李注引說文同。鍇本作天？。誤。"}]},"離":{"expl":"黃倉庚也。鳴則蠶生。从隹离聲。","rad":"隹","fq":"呂支切","vol":"04","py":"lí","duan":[{"e":"離黃、","n":"逗。各本無離。淺人誤刪。如巂周刪巂之比。依爾雅音義、廣韵補。"}]},"雕":{"expl":"鷻也。从隹周聲。","rad":"隹","fq":"都僚切","vol":"04","py":"diāo","duan":[{"e":"鷻也。","n":"鳥部曰。鷻、雕也。假借爲琱琢、凋零字。"}]},"𨿳":{"expl":"鳥也。从隹，瘖省聲。或从人，人亦聲。","rad":"隹","fq":"於淩切","vol":"04","py":"yīnɡ","duan":[{"e":"𤸰鳥也。","n":"左傳。如鷹鸇之逐鳥雀。釋鳥。鷹來鳩。郭云。來當爲爽。按左傳。爽鳩氏司宼也。杜曰。爽鳩、鷹也。"}]},"𨾦":{"expl":"𨿠也。从隹氐聲。","rad":"隹","fq":"處脂切","vol":"04","py":"chī","duan":[{"e":"𨿠也。","n":"今江蘇俗呼鷂鷹。盤旋空中。攫雞子食之。大雅云。懿厥哲婦。爲梟爲鴟。莊周云。鴟得腐鼠是也。爾雅有鴟鴞、怪鴟、茅鴟。皆與單言鴟者各物。"}]},"𨿠":{"expl":"𨾦也。从隹垂聲。","rad":"隹","fq":"是僞切","vol":"04","py":"shuì","duan":[{"e":"鴟也。从隹。𡍮聲。","n":"是僞切。古音在十七部。"}]},"墫":{"expl":"舞也。从士尊聲。《詩》曰：“墫墫舞我。”","rad":"士","fq":"慈損切","vol":"01","py":"cūn","duan":[{"e":"士舞也。","n":"各本無士。依詩、爾雅音義補。周禮。大胥、以學士合舞。小胥、巡學士舞列。故其字从士。也當爲皃。毛傳。墫墫、舞皃。古書也皃二字多互譌。"}]},"鳽":{"expl":"石鳥。一名雝𪆫。一曰精𠛱。从隹幵聲。《春秋傳》：“秦有士鳽 。”","rad":"隹","fq":"苦堅切","vol":"04","py":"qiān","duan":[{"e":"石鳥。一名雝渠。一曰精列。","n":"毛傳曰。脊令、雝渠也。飛則鳴。行則搖。不能自舍爾。釋鳥作？鴒。俗字也。精列者、脊令之轉語。"}]},"雝":{"expl":"雝𪆫也。从隹邕聲。","rad":"隹","fq":"於容切","vol":"04","py":"yōnɡ","duan":[{"e":"雝渠也。","n":"渠鳥部作？。鉉本同。"}]},"雂":{"expl":"鳥也。从隹今聲。《春秋傳》有公子苦雂。","rad":"隹","fq":"巨淹切","vol":"04","py":"qián","duan":[{"e":"雂鳥也。","n":"廣韵云。句喙鳥。本字林。"}]},"雁":{"expl":"鳥也。从隹从人，厂聲。讀若鴈。","rad":"隹","fq":"五晏切","vol":"04","py":"yàn","duan":[{"e":"雁鳥也。","n":"此與鳥部鴈別。鴈从鳥爲䳘雁从隹爲鴻雁。禮舒鴈當作舒雁。謂雁之舒者。以別於眞雁也。舒雁謂之鴈。猶舒鳧謂之鶩也。經典鴻雁字多作鴈。毛傳曰。大曰鴻。小曰鴈。按鴻、大也。非鳥名。"}]},"𩁟":{"expl":"𩁟黃也。从隹黎聲。一曰楚雀也。其色黎黑而黃。","rad":"隹","fq":"郎兮切","vol":"04","py":"lí","duan":[{"e":"𩁟黃也。","n":"三字句。𩁟字林省作𨿯。又作鵹。？黃卽離黃。見離下。？離異部而雙聲。故？黃與離黃異名。但二字不類廁。其說未聞。"}]},"雐":{"expl":"鳥也。从隹虍聲。","rad":"隹","fq":"荒烏切","vol":"04","py":"hū","duan":[{"e":"雐鳥也。从隹。虍聲。","n":"荒烏切。五部。虧字從此。"}]},"𨾯":{"expl":"牟母也。从隹奴聲。","rad":"隹","fq":"人諸切","vol":"04","py":"rú","duan":[{"e":"牟母也。","n":"母音無。鉉作母。誤。釋鳥。鴽、牟母。鄭注公食大夫禮、月令皆作鴽、母無也。母與牟、無與母皆音同也。今二注舛譌。蔡邕月令章句。鴽爲鶉䳺之屬。時則訓注云。鴽、鶉也。李巡云。鴽䳺一名鴾母。郭云。鴽、䳺也。按内則、爾雅皆鶉鴽竝舉。則不可云？卽鶉也。"}]},"雇":{"expl":"九雇。農桑候鳥，扈民不婬者也。从隹戶聲。春雇，鳻盾；夏雇，竊玄；秋雇，竊藍；冬雇，竊黃；𣗥雇，竊丹；行雇，唶唶；宵雇，嘖嘖；桑雇，竊脂；老雇，鷃也。","rad":"隹","fq":"侯古切","vol":"04","py":"hù","duan":[{"e":"九雇、","n":"逗。"}]},"𨿡":{"expl":"䨄屬。从隹𦎫聲。","rad":"隹","fq":"常倫切","vol":"04","py":"chún","duan":[{"e":"䨄屬也。","n":"按說文或言屬。或言別。言屬而別在焉。言別而屬在焉。言䨄屬則？非䨄也。焦氏循曰。說文隼下云。一曰鶉字。鶉卽鷻省。輈人。鳥旟七斿以象鶉火。鳥隼爲旟。則鶉火之鶉卽鷻。左傳童謡鶉之賁賁。下舉鶉火證之。則詩之言奔奔者、當亦是鷻。惟有縣鶉兮。毛特訓爲小鳥。乃爲䳺鶉也。按内則有鶉羹、詩貆特鶉皆謂食物。"}]},"䨄":{"expl":"𩁛屬。从隹酓聲。","rad":"隹","fq":"恩含切","vol":"04","py":"ān","duan":[{"e":"𨿡屬也。从隹。酓聲。","n":"恩含切。七部。太平御覽引有一曰牟母四字。"}]},"祗":{"expl":"敬也。从示氐聲。","rad":"示","fq":"旨移切","vol":"01","py":"zhī","duan":[{"e":"敬也。","n":"見釋詁。"}]},"丨":{"expl":"上下通也。引而上行讀若囟，引而下行讀若𨓆。凡丨之屬皆从丨。","rad":"丨","fq":"古本切","vol":"01","py":"ɡǔn","duan":[{"e":"下上通也。","n":"依玉篇。"}]},"䧴":{"expl":"鳥也。从隹支聲。一曰䧴度。","rad":"隹","fq":"章移切","vol":"04","py":"zhī","duan":[{"e":"䧴鳥也。","n":"漢武帝造鳷鵲觀。在雲陽甘泉宫外。"}]},"𨾊":{"expl":"鳥肥大𨾊𨾊也。从隹工聲。","rad":"隹","fq":"戶工切","vol":"04","py":"hónɡ","duan":[{"e":"鳥肥大𨾊𨾊然也。","n":"然依韵會補。詩傳云。大曰鴻。小曰鴈。當作此𨾊字。謂鴈之肥大者也。"}]},"𩀼":{"expl":"繳𩀼也。从隹㪔聲。一曰飛𩀼也。","rad":"隹","fq":"穌旰切","vol":"04","py":"sàn","duan":[{"e":"繳𩀼也。","n":"繳𩀼者、謂縷繫矰矢。放散之加於飛鳥也。按繖葢字當作此。亦取先斂後放也。"}]},"隿":{"expl":"繳射飛鳥也。从隹弋聲。","rad":"隹","fq":"與職切","vol":"04","py":"yì","duan":[{"e":"繳射飛鳥也。","n":"經傳多假弋爲之。"}]},"雄":{"expl":"鳥父也。从隹厷聲。","rad":"隹","fq":"羽弓切","vol":"04","py":"xiónɡ","duan":[{"e":"鳥父也。从隹。厷聲。","n":"羽弓切。古音在六部。"}]},"雌":{"expl":"鳥母也。从隹此聲。","rad":"隹","fq":"此移切","vol":"04","py":"cī","duan":[{"e":"鳥母也。从隹。此聲。","n":"此移切。十五十六部。"}]},"䍜":{"expl":"覆鳥令不飛走也。从网、隹。讀若到。","rad":"隹","fq":"都校切","vol":"04","py":"zhào","duan":[{"e":"覆鳥令不得飛走也。","n":"得依廣韵補。网部有罩、捕魚器也。此與罩不獨魚鳥異用。亦且䍜非网？之類。謂家禽及生獲之禽慮其飛走而籠䍜之。故其字不入网部。今則罩行而䍜廢矣。"}]},"雋":{"expl":"肥肉也。从弓，所以射隹。長沙有下雋縣。","rad":"隹","fq":"徂沇切","vol":"04","py":"juàn","duan":[{"e":"鳥肥也。","n":"各本作肥肉也。今依廣韵。廣韵不云說文。然必說文善本也。不言鳥則字何以从隹。蒯通著書。號曰雋永。言其所說味美而長也。惟野鳥味可言雋。故从弓。"}]},"𩁌":{"expl":"飛也。从隹隓聲。","rad":"隹","fq":"山垂切","vol":"04","py":"wéi","duan":[{"e":"飛也。从隹。隓聲。","n":"山垂切。古音在十七部。"}]},"奞":{"expl":"鳥張毛羽自奮也。从大从隹。凡奞之屬皆从奞。讀若睢。","rad":"奞","fq":"息遺切","vol":"04","py":"suī","duan":[{"e":"鳥張毛羽自奮奞也。","n":"奞依篇、韵補。奮奞雙聲字。"}]},"中":{"expl":"内也。从口。丨，上下通。","rad":"丨","fq":"陟弓切","vol":"01","py":"zhōnɡ","duan":[{"e":"內也。","n":"俗本和也。非是。當作內也。宋麻沙本作肉也。一本作而也。正皆內之譌。入部曰。內者、入也。入者、內也。然則中者、別於外之辭也。别於偏之辭也。亦合宜之辭也。作內、則此字平聲去聲之義無不賅矣。許以和爲唱和字。龢爲諧龢字。龢和皆非中之訓也。周禮中失卽得失。"}]},"奪":{"expl":"手持隹失之也。从又从奞。","rad":"奞","fq":"徒活切","vol":"04","py":"duó","duan":[{"e":"手持隹失之也。","n":"引伸爲凡失去物之偁。凡手中遺落物當作此字。今乃用脫爲之。而用奪爲爭字。相承久矣。脫、消肉臞也。徒活切。鄭康成說禮記曰編𥳑爛脫。脫音奪。"}]},"奮":{"expl":"翬也。从奞在田上。《詩》曰：“不能奮飛。”","rad":"奞","fq":"方問切","vol":"04","py":"fèn","duan":[{"e":"翬也。","n":"㬪韵。羽部曰。翬、大飛也。雉雞羊絕有力皆曰奮。"}]},"雈":{"expl":"鴟屬。从隹从𦫳，有毛角。所鳴，其民有旤。凡雈之屬皆从雈。讀若和。","rad":"雈","fq":"胡官切","vol":"04","py":"huán","duan":[{"e":"𨾦屬。","n":"𨾦、𨿠也。釋鳥。雈老兔。郭云。木兔也。似鴟鵂而小、兔頭。"}]},"蒦":{"expl":"規蒦，商也。从又持雈。一曰視遽皃。一曰蒦，度也。","rad":"雈","fq":"乙虢切","vol":"04","py":"huò","duan":[{"e":"規蒦、","n":"逗。"}]},"雚":{"expl":"小爵也。从雈吅聲。《詩》曰：“雚鳴于垤。”","rad":"雈","fq":"工奐切","vol":"04","py":"ɡuàn","duan":[{"e":"雚爵也。","n":"三字句。爵當作雀。雚今字作鸛。鸛雀乃大鳥。各本作小爵。誤。今依太平御覽正。陸機疏云。鸛、鸛雀也。亦可證。陸云。似鴻而大。莊子作觀雀。土部垤下、鳥部鳳下皆作鸛。係俗改。"}]},"舊":{"expl":"𨾦舊，舊畱也。从雈臼聲。","rad":"雈","fq":"巨救切","vol":"04","py":"jiù","duan":[{"e":"𨾦舊、","n":"逗。"}]},"𦫳":{"expl":"羊角也。象形。凡𦫳之屬皆从𦫳。讀若𦮃。","rad":"𦫳","fq":"工瓦切","vol":"04","py":"ɡuǎ","duan":[{"e":"羊角也。","n":"玉篇曰。𦫳𦫳、㒳角皃。廣韵曰。𦫳𦫳、羊角開皃。"}]},"𦮃":{"expl":"戾也。从𦫳而兆。兆，古文別。","rad":"𦫳","fq":"古懷切","vol":"04","py":"ɡuāi","duan":[{"e":"戾也。","n":"犬部曰。戾、曲也。曲則不伸。故爲睽離。"}]},"芇":{"expl":"相當也。闕。讀若宀。","rad":"𦫳","fq":"母官切","vol":"04","py":"mián","duan":[{"e":"相當也。","n":"廣韵曰今人賭物相折謂之芇。按廣雅。芇、當也。亡殄亡安二切。俗本譌作㒼。"}]},"𥄕":{"expl":"目不正也。从𦫳从目。凡𥄕之屬皆从𥄕。萈从此。讀若末。","rad":"𥄕","fq":"徒結切","vol":"04","py":"mò","duan":[{"e":"目不正也。从𦫳目。","n":"𦫳者、外向之象。故爲不正。"}]},"𣃘":{"expl":"旌旗杠皃。从丨从㫃，㫃亦聲。","rad":"丨","fq":"丑善切","vol":"01","py":"chǎn","duan":[{"e":"旌旗杠皃。","n":"釋天曰。素錦韜杠。杠謂旗之竿也。詩謂之干。"}]},"瞢":{"expl":"目不明也。从𥄕从䀏。䀏，目數搖也。","rad":"𥄕","fq":"木空切","vol":"04","py":"ménɡ","duan":[{"e":"目不明也。","n":"周禮眡祲。六曰瞢。注云。日月瞢瞢無光也。按小雅。視天夢夢。夢與瞢音義同也。又左傳。亦無瞢焉。小爾雅。瞢、慙也。此引伸之義。"}]},"𤊾":{"expl":"火不明也。从𥄕从火，𥄕亦聲。《周書》曰：“布重𤊾席。”織蒻席也。讀與蔑同。","rad":"𥄕","fq":"莫結切","vol":"04","py":"miè","duan":[{"e":"火不明也。","n":"按火當作目。淺人所改也。假令訓火不明。則當入火部矣。此部四字皆說目。"}]},"蔑":{"expl":"勞目無精也。从𥄕，人勞則蔑然；从戍。","rad":"𥄕","fq":"莫結切","vol":"04","py":"miè","duan":[{"e":"勞目無精也。","n":"目勞則精光茫然。通作眜。如左傳公及邾儀父盟于蔑、晉先蔑、公穀皆作眜是也。引伸之義爲細。如木細枝謂之蔑是也。又引伸之義爲無。如亡之命矣夫、亦作蔑之命矣夫是也。左傳鬷蔑、字然明。此以相反爲名字也。"}]},"羊":{"expl":"祥也。从𦫳，象頭角足尾之形。孔子曰：“牛羊之字以形舉也。”凡羊之屬皆从羊。","rad":"羊","fq":"與章切","vol":"04","py":"yánɡ","duan":[{"e":"祥也。","n":"㬪韵。考工記注曰。羊、善也。按？義羑美字皆从羊。"}]},"羋":{"expl":"羊鳴也。从羊，象聲气上出。與牟同意。","rad":"羊","fq":"緜婢切","vol":"04","py":"mǐ","duan":[{"e":"羊鳴也。","n":"各本中筆直。今依五經文字、篆韵諩正。气出不徑直也。"}]},"羔":{"expl":"羊子也。从羊，照省聲。","rad":"羊","fq":"古牢切","vol":"04","py":"ɡāo","duan":[{"e":"羊子也。","n":"虞氏注說卦傳爲羊作爲羔。云女使也。妾與羔皆取位賤。鄭本作陽。云讀爲養。无家女行賃炊爨。今時有之。賤於妾也。二說字異義同。武進臧鏞堂曰。羔者、養之誤也。"}]},"羜":{"expl":"五月生羔也。从羊宁聲。讀若煑。","rad":"羊","fq":"直呂切","vol":"04","py":"zhù","duan":[{"e":"五月生羔也。","n":"謂羔生五月者也。釋畜、毛傳皆云。羜、未成羊也。郭云。俗呼五月羔爲羜。"}]},"𦎦":{"expl":"六月生羔也。从羊敄聲。讀若霧。","rad":"羊","fq":"已遇切","vol":"04","py":"yù","duan":[{"e":"六月生羔也。","n":"廣雅。羍𦎦羜䍻羔也。"}]},"羍":{"expl":"小羊也。从羊大聲。讀若達。","rad":"羊","fq":"他末切","vol":"04","py":"dá","duan":[{"e":"小羊也。","n":"羊當作羔。字之誤也。羜𦎦皆曰羔。羍又小於羔。是初生羔也。薛綜荅韋昭云。羊子初生名達。小名羔。未成羊曰羜。大曰羊。長幼之異名。初學記引羍七月生羔也。藝文類聚引七月生羊也。與陸德明、孔穎達所據不同。似未可信。按生民。誕彌厥月。先生如達。毛曰。達、生也。姜嫄之子先生者也。此不可通。當是經文作羍。傳云羍、達也。先生、姜嫄之子先生者也。達、他達切。卽滑達字。凡生子始生較難。后稷爲姜嫄始生子。乃如達出之易。故曰先生如羍。先釋羍後釋先生者、欲文義顯箸。文法與白華傳先釋煁、後釋桑薪正同。鄭箋如字訓爲羊子。云如羊子之生。媟矣。尊祖之詩似不應若是。且嘼類之生無不易者。何獨取乎羊。尋箋不云達讀爲羍。則知毛詩本作羍。"}]},"䍮":{"expl":"羊未卒歲也。从羊兆聲。或曰：夷羊百斤左右爲䍮。讀若《春秋》“盟于洮”。","rad":"羊","fq":"治小切","vol":"04","py":"zhào","duan":[{"e":"羊未卒歲也。","n":"廣雅。吳羊牡一歲曰牯䍮。三歲曰羝。其牝一歲曰牸䍮。三歲曰牂。"}]},"屮":{"expl":"艸木初生也。象丨出形，有枝莖也。古文或以爲艸字。讀若徹。凡屮之屬皆从屮。尹彤說。","rad":"屮","fq":"丑列切","vol":"01","py":"chè","duan":[{"e":"艸木初生也。象丨出形有枝莖也。","n":"丨讀若𦥓。引而上行也。枝謂兩旁莖枝。柱謂丨也。過乎屮則爲𡳿。下垂根則爲<>（木）。"}]},"羝":{"expl":"牡羊也。从羊氐聲。","rad":"羊","fq":"都兮切","vol":"04","py":"dī","duan":[{"e":"牡羊也。","n":"見大雅毛傳。"}]},"羒":{"expl":"牂羊也。从羊分聲。","rad":"羊","fq":"符分切","vol":"04","py":"fén","duan":[{"e":"牡羊也。","n":"各本作牂羊。誤。今依初學記正。釋嘼。羊牡羒。郭曰。謂吳羊白羝。廣韵。羒、白羝羊也。國語。土之怪羵羊。羵者、雌雄未成。"}]},"牂":{"expl":"牡羊也。从羊爿聲。","rad":"羊","fq":"則郎切","vol":"04","py":"zānɡ","duan":[{"e":"牝羊也。","n":"各本作牡羊。誤。今正。釋嘼、毛傳、内則注皆曰。牂、牝羊。角部觟下云。牂羊生角者也。羖羊無無角者。故詩以童羖爲難。牂羊多無角。故殊之。"}]},"羭":{"expl":"夏羊牡曰羭。从羊俞聲。","rad":"羊","fq":"羊朱切","vol":"04","py":"yú","duan":[{"e":"夏羊牝曰羭。","n":"牝各本作牡。誤。按釋嘼。夏羊牝羭、牡羖。自郭所據牝牡字巳互譌。引之者多誤。因之竄改說文。今正。下文夏羊牡曰羖。亦有譌作夏羊牝曰羖者。牝牡字易互譌。而羖必是牡。則知羭必是牝。爾雅牝羭牡羖。猶上文云牡㸮牝牂也。急就篇。牂羖羯羠䍮羝羭。師古曰。牂、吳羊之牝也。羝、牂羊之牡也。羭、夏羊之牝也。羖、夏羊之牡也。此所據說文尙不誤。左傳曰。攘公之羭。杜曰。羭、美也。牝羊美於牡者。故内則八珍亦用牂。歸藏齊母亦曰。㒳壷㒳羭。夏羊謂黑羊。郭注爾雅云。白者吳羊。黑者夏羊。"}]},"羖":{"expl":"夏羊牡曰羖。从羊殳聲。","rad":"羊","fq":"公戶切","vol":"04","py":"ɡǔ","duan":[{"e":"夏羊牡曰羖。","n":"此牡字大小徐皆不誤。今刻大徐本誤牝。假令羖是牝。則下文安得云犗乎。"}]},"羯":{"expl":"羊羖犗也。从羊曷聲。","rad":"羊","fq":"居謁切","vol":"04","py":"jié","duan":[{"e":"羊羖犗也。","n":"羊羖當作羖羊。廣雅曰。羖羊犗曰羯。牛部曰。犗者、？牛也。按小雅。俾出童羖。鄭云。羖羊之性。牝牡有角。則鄭謂羖羊兼有牡牝。與許說殊。疑鄭說卽郭所云。今人便以牂羖名白黑羊也。黑羊則名羖。牝牡皆角。故童羖爲難。白羊則名牂。牝者多無角。故許別言牂羊生角者。"}]},"羠":{"expl":"騬羊也。从羊夷聲。","rad":"羊","fq":"徐姉切","vol":"04","py":"yí","duan":[{"e":"騬羊也。","n":"夏羊犗曰羯。吳羊犗曰羠也。爾雅、說文皆無吳羊之名。單言羊則謂白羊也。馬部曰。？、犗馬也。貨殖傳。其民羯羠不均。謂很如羊也。"}]},"羳":{"expl":"黃腹羊。从羊番聲。","rad":"羊","fq":"附袁切","vol":"04","py":"fán","duan":[{"e":"黃腹羊也。","n":"見釋嘼。"}]},"羥":{"expl":"羊名。从羊巠聲。","rad":"羊","fq":"口莖切","vol":"04","py":"qiān","duan":[{"e":"羊名也。从羊。巠聲。","n":"口莖切。十一部。按初學記引說文楷閒反。葢本音隱。考工記顅字、故書或作牼。劉音牼苦顏反。皆雙聲合韵也。左傳。邾子牼卒。穀梁作瞯。"}]},"𦎷":{"expl":"羊名。从羊執聲。汝南平輿有𦎷亭。讀若晉。","rad":"羊","fq":"卽刃切","vol":"04","py":"jìn","duan":[{"e":"羊名。从羊。𡘺聲。汝南平輿有𦎷亭。讀若晉。","n":"春秋。蔡滅沈。杜預、司馬昭皆云。平輿有沈亭。疑沈亭卽？亭也。？从？聲。？與沈皆七部字也。讀若晉之晉疑有誤。大徐卽刃切。篇、韵同。"}]},"屯":{"expl":"難也。象艸木之初生。屯然而難。从屮貫一。一，地也。尾曲。《易》曰：“屯，剛柔始交而難生。”","rad":"屮","fq":"陟倫切","vol":"01","py":"zhūn","duan":[{"e":"難也。","n":"屯韵會有。"}]},"羸":{"expl":"瘦也。从羊𣎆聲。","rad":"羊","fq":"力爲切","vol":"04","py":"léi","duan":[{"e":"𤸃也。","n":"引伸爲凡𤸃之偁。又假借爲纍字。易。羸其角、羸其瓶。或作纍。或作虆。其意一也。"}]},"䍴":{"expl":"羊相𦎸也。从羊委聲。","rad":"羊","fq":"於僞切","vol":"04","py":"wèi","duan":[{"e":"羊相䍴𦎸也。","n":"各本誤。今依篇、韵補正。䍴𦎸㬪韵字。猶委積也。夏小正。三月䍷羊。傳曰。羊有相還之時。其類䍷䍷然。其䍴𦎸之謂與。"}]},"𦎸":{"expl":"䍴𦎸也。从羊責聲。","rad":"羊","fq":"子賜切","vol":"04","py":"zì","duan":[{"e":"羊相䍴𦎸也。从羊。責聲。","n":"子賜切。十六部。"}]},"羣":{"expl":"輩也。从羊君聲。","rad":"羊","fq":"渠云切","vol":"04","py":"qún","duan":[{"e":"輩也。","n":"若軍發車百兩爲輩。此就字之從車言也。朋也、類也、此輩之通訓也。小雅。誰謂爾無羊。三百維羣。犬部曰。羊爲羣。犬爲獨。引伸爲凡類聚之偁。"}]},"𦎣":{"expl":"羣羊相𦎸也。一曰黑羊。从羊垔聲。","rad":"羊","fq":"烏閑切","vol":"04","py":"yān","duan":[{"e":"羣羊相積也。","n":"積各本作？。今依玉篇。"}]},"𦍧":{"expl":"羊名。蹏皮可以割桼。从羊此聲。","rad":"羊","fq":"此思切","vol":"04","py":"cī","duan":[{"e":"羊名。蹏皮可㠯割桼。","n":"未聞。"}]},"美":{"expl":"甘也。从羊从大。羊在六畜主給膳也。美與善同意。","rad":"羊","fq":"無鄙切","vol":"04","py":"měi","duan":[{"e":"甘也。","n":"甘部曰。美也。甘者、五味之一。而五味之美皆曰甘。引伸之凡好皆謂之美。"}]},"羌":{"expl":"西戎牧羊人也。从人从羊，羊亦聲。南方蠻閩从虫，北方狄从犬，東方貉从豸，西方羌从羊：此六種也。西南僰人、僬僥，从人；蓋在坤地，頗有順理之性。唯東夷从大。大，人也。夷俗仁，仁者壽，有君子不死之國。孔子曰：“道不行，欲之九夷，乘桴浮於海。”有以也。","rad":"羊","fq":"去羊切","vol":"04","py":"qiānɡ","duan":[{"e":"西戎。","n":"句。按此當有也字。商頌自彼氐羌。箋云。氐羌、夷狄國在西方者也。王制曰。西方曰戎。是則戎與羌一也。"}]},"羑":{"expl":"進善也。从羊久聲。文王拘羑里，在湯陰。","rad":"羊","fq":"與久切","vol":"04","py":"yǒu","duan":[{"e":"進善也。","n":"進當作道。道善、導以善也。顧命。誕受羑若。馬曰。羑、道也。文王拘羑里。尙書大傳、史記作牖里。"}]},"羴":{"expl":"羊臭也。从三羊。凡羴之屬皆从羴。","rad":"羴","fq":"式連切","vol":"04","py":"shān","duan":[{"e":"羊臭也。","n":"臭者、气之通於鼻者也。羊多則气羴。故从三羊。"}]},"每":{"expl":"艸盛上出也。从屮母聲。","rad":"屮","fq":"武罪切","vol":"01","py":"měi","duan":[{"e":"艸盛上出也。","n":"左傳。輿人誦曰。原田每每。杜注。晉君美盛、若原田之艸每每然。魏都賦蘭渚每每、用此。俗改爲莓。按每是艸盛。引伸爲凡盛。如品庶每生。貪也每懷。懷、私也。皆盛意。毛公曰。每、雖也。凡言雖者皆充類之辭。今俗語言每每者、不一端之辭。皆盛也。"}]},"羼":{"expl":"羊相厠也。从羴在尸下。尸，屋也。一曰相出前也。","rad":"羴","fq":"初限切","vol":"04","py":"chàn","duan":[{"e":"羊相廁也。","n":"釋名曰。廁、襍也。"}]},"瞿":{"expl":"鷹隼之視也。从隹从䀠，䀠亦聲。凡瞿之屬皆从瞿。讀若章句之句。","rad":"瞿","fq":"九遇切","vol":"04","py":"jù","duan":[{"e":"𤸰隼之視也。","n":"隼亦鷻字也。知爲鷹隼之視者。以从隹䀠知之也。吳都賦曰。鷹瞵鶚視。經傳多假瞿爲䀠。見䀠下。"}]},"矍":{"expl":"隹欲逸走也。从又持之，矍矍也。讀若《詩》云“穬彼淮夷”之“穬”。一曰視遽皃。","rad":"瞿","fq":"九縛切","vol":"04","py":"jué","duan":[{"e":"隹欲逸走也。","n":"隹當作隼。也當作皃。隼欲逸走而未能。矍矍然。震上六。視矍矍。馬云。中未得之皃。人之中未得者、如隼之欲逸走也。"}]},"雔":{"expl":"雙鳥也。从二隹。凡雔之屬皆从雔。讀若醻。","rad":"雔","fq":"市流切","vol":"04","py":"chóu","duan":[{"e":"雙鳥也。","n":"按釋詁仇讎敵妃知儀匹也。此讎字作雔。則義尤切近。若應也、當也、醻物價也、怨也、宼也、此等義則當作讎。度古書必有用雔者。今則讎行而雔廢矣。"}]},"靃":{"expl":"飛聲也。雨而雙飛者，其聲靃然。","rad":"雔","fq":"呼郭切","vol":"04","py":"huò","duan":[{"e":"飛聲也。","n":"此字之本義也。引伸爲揮霍、爲靃靡。靃靡音選委切。"}]},"雙":{"expl":"隹二枚也。从雔，又持之。","rad":"雔","fq":"所江切","vol":"04","py":"shuānɡ","duan":[{"e":"隹二枚也。","n":"見隹部隻下。方言。飛鳥曰雙。鴈曰乗。"}]},"雥":{"expl":"羣鳥也。从三隹。凡雥之屬皆从雥。","rad":"雥","fq":"徂合切","vol":"04","py":"zá","duan":[{"e":"羣鳥也。","n":"許善心神雀頌。嘉貺雥集。"}]},"䨊":{"expl":"鳥羣也。从雥𣶒聲。","rad":"雥","fq":"烏玄切","vol":"04","py":"yuān","duan":[{"e":"鳥羣也。","n":"如𣶒爲水聚。"}]},"雧":{"expl":"羣鳥在木上也。从雥从木。","rad":"雥","fq":"秦入切","vol":"04","py":"jí","duan":[{"e":"羣鳥在木上也。","n":"引伸爲凡聚之偁。漢人多假襍爲集。"}]},"鳥":{"expl":"長尾禽緫名也。象形。鳥之足似匕，从匕。凡鳥之屬皆从鳥。","rad":"鳥","fq":"都了切","vol":"04","py":"niǎo","duan":[{"e":"長尾禽緫名也。","n":"釋鳥音義引長尾羽衆禽揔名也。按厹部云。禽、走獸緫名。此不同者。此依釋鳥二足而羽謂之禽也。短尾名隹。長尾名鳥。析言則然。渾言則不別也。"}]},"毒":{"expl":"厚也。害人之艸，往往而生。从屮从毒。","rad":"屮","fq":"徒沃切","vol":"01","py":"dú","duan":[{"e":"厚也。","n":"毒厚疊韵。三部四部同入也。毒兼善惡之辭。猶祥兼吉凶、臭兼香臭也。易曰。聖人以此毒天下而民從之。列子書曰。亭之毒之。皆謂厚民也。毒與竺篤同音通用。微子篇。天毒降災。史記作天篤。"}]},"鳳":{"expl":"神鳥也。天老曰：“鳳之象也，鴻前麐後，蛇頸魚尾，鸛顙鴛思，龍文虎背，燕頷雞喙，五色備舉。出於東方君子之國，翺翔四海之外，過崐崘，飲砥柱，濯羽弱水，莫宿風穴。見則天下大安寕。”从鳥凡聲。","rad":"鳥","fq":"馮貢切","vol":"04","py":"fènɡ","duan":[{"e":"神鳥也。天老曰。","n":"天老、黃帝臣。"}]},"鸞":{"expl":"亦神靈之精也。赤色，五采，雞形。鳴中五音，頌聲作則至。从鳥䜌聲。周成王時氐羌獻鸞鳥。","rad":"鳥","fq":"洛官切","vol":"04","py":"luán","duan":[{"e":"赤神靈之精也。","n":"赤各本作亦。誤。今依藝文類聚、埤雅、集韵、類篇、韵會正。後漢書注、廣韵皆引孫氏瑞應圖曰。鸞、赤神之精也。春秋元命包曰。离爲鸞。"}]},"鸑":{"expl":"鸑鷟，鳳屬，神鳥也。从鳥獄聲。《春秋國語》曰：“周之興也，鸑鷟鳴於岐山。”江中有鸑鷟，似鳧而大，赤目。","rad":"鳥","fq":"五角切","vol":"04","py":"yuè","duan":[{"e":"鸑鷟、","n":"逗。"}]},"鷟":{"expl":"鸑鷟也。从鳥族聲。","rad":"鳥","fq":"士角切","vol":"04","py":"zhuó","duan":[{"e":"鸑鷟也。从鳥。族聲。","n":"士角切。三部。"}]},"鷫":{"expl":"鷫鷞也。五方神鳥也。東方發明，南方焦明，西方鷫鷞，北方幽昌，中央鳳皇。从鳥肅聲。","rad":"鳥","fq":"息逐切","vol":"04","py":"sù","duan":[{"e":"鷫鷞也。从鳥。肅聲。","n":"息逐切。三部。"}]},"鷞":{"expl":"鷫鷞也。从鳥爽聲。","rad":"鳥","fq":"所莊切","vol":"04","py":"shuānɡ","duan":[{"e":"鷫鷞也。从鳥。爽聲。","n":"所莊切。十部。"}]},"鳩":{"expl":"鹘鵃也。从鳥九聲。","rad":"鳥","fq":"居求切","vol":"04","py":"jiū","duan":[{"e":"鶻鵃也。","n":"按今本說文奪譌。鳩與雉雇皆本左傳。鳩爲五鳩之緫名。猶雉爲十四雉之緫名、雇爲九雇之緫名也。當先出鳩篆。釋云五鳩、鳩民者也。乃後云鶌鳩、鶻鵃也。鵻、祝鳩也。秸𪈅、尸鳩也。鴡、王鴡、鴡鳩也。鴡鳩鷙鳥。故別爲類廁之。而𤸰爲爽鳩。已見於隹部矣。度說文古本當如是。今本以鳩名專系諸鶻鵃。則不可通矣。毛詩召南傳曰。鳩、尸鳩秸鞠也。衞風傳曰。鳩、鶻鳩也。月令注曰。鳩、搏榖也。經文皆單言鳩。傳注乃別爲某鳩。此可證鳩爲五鳩之緫名。經傳多假鳩爲逑、爲勼。辵部曰。逑、斂聚也。勹部曰。勼、聚也。"}]},"鶌":{"expl":"鶌鳩也。从鳥屈聲。","rad":"鳥","fq":"九勿切","vol":"04","py":"jué","duan":[{"e":"鶌鳩、鶻鵃也。","n":"鶻鵃二字依爾雅補。釋鳥曰。鶌鳩、鶻鵃。小雅。宛彼鳴鳩。毛曰。鳴鳩、鶻鵰也。衞風。于嗟鳩兮。無食桑葚。毛曰。鳩、鶻鳩也。食桑葚過則醉而傷其性。鶻鳩食桑葚。毛葢目驗而知。鵰與鵃音同。郭云。今江東亦呼爲鶻鵃。似山鵲而小。短尾。青黑色。多聲。卽是此也。舊說及廣雅皆云班鳩。非也。按此郭注見左正義。今本不完。左傳。鶻鳩氏司事也。鶻鳩春來冬去而多聲。故詩小宛謂之鳴鳩。若陳風、魯頌之鴞。毛皆謂惡聲之鳥。則必鉤雒之類。而非司事之鳥矣。"}]},"鵻":{"expl":"祝鳩也。从鳥隹聲。","rad":"鳥","fq":"思允切","vol":"04","py":"zhuī","duan":[{"e":"祝鳩也。","n":"小雅。翩翩者鵻。釋鳥。鵻其鳺鴀。毛傳曰。鵻、夫不也。南有嘉魚傳曰。鵻、壹宿之鳥。左傳。祝鳩氏司徒也。杜曰。祝鳩、䳡鳩也。䳡鳩孝故爲司徒。主敎民。樊光注爾雅亦云。孝故爲司徒。郭云。今䳕鳩也。按䳕鳩今俗呼爲勃姑。䳕勃語之轉。䳕卽爾雅之夫不也。"}]},"鶻":{"expl":"鶻鵃也。从鳥骨聲。","rad":"鳥","fq":"古忽切","vol":"04","py":"ɡǔ","duan":[{"e":"鶻鵃也。","n":"按鶻鵃二篆宜蒙鶌篆類廁。乃中隔以祝鳩。豈轉寫倒易與。小宛釋文云。鵰、字林作鵃。云骨鵃、小種鳩也。不云說文作鵃而係字林。且字林鶻作骨。豈鶻鵃二篆說文本無。而後人益之與。"}]},"㞣":{"expl":"艸初生，其香分布。从屮从分，分亦聲。","rad":"屮","fq":"撫文切","vol":"01","py":"fēn","duan":[{"e":"艸初生其香分布也。","n":"衆經音義兩引說文。芬、芳也。其所據本不同。按艸部。芳、艸香也。詩說馨香、多言苾芬。大雅毛傳曰。芬芬、香也。然則玄應所據正是古本。"}]},"鵃":{"expl":"鶻鵃也。从鳥舟聲。","rad":"鳥","fq":"張流切","vol":"04","py":"zhōu","duan":[{"e":"鶻鵃也。从鳥。舟聲。","n":"張流切。三部。按鶻音骨。鵃郭音嘲。釋文音陟交反。凡鳥名多取其聲爲之。郭云。今江東亦呼爲鶻鵃。正謂江東皆呼骨嘲而定此音也。"}]},"𪈅":{"expl":"秸𪈅，尸鳩。从鳥𥱩聲。","rad":"鳥","fq":"居六切","vol":"04","py":"jú","duan":[{"e":"秸𪈓、","n":"逗。"}]},"鴿":{"expl":"鳩屬。从鳥合聲。","rad":"鳥","fq":"古沓切","vol":"04","py":"ɡē","duan":[{"e":"鳩屬也。","n":"鳩之可畜於家者。狀全與勃姑同。"}]},"鴠":{"expl":"渴鴠也。从鳥旦聲。","rad":"鳥","fq":"得案切","vol":"04","py":"dàn","duan":[{"e":"渴鴠也。","n":"月令作曷旦。坊記作？旦。鄭云。夜鳴求旦之鳥。方言作䳚鴠、鶡鴠。廣志作侃旦。皆一語之轉。此渴旦當同月令作曷旦。淺人改之。誤用渴爲飢㵣字耳。太平御覽引鴠、可旦也。冣爲古本。曷旦、可旦、鳥語如此。故云求旦之鳥。"}]},"鶪":{"expl":"伯勞也。从鳥狊聲。","rad":"鳥","fq":"古闃切","vol":"04","py":"jú","duan":[{"e":"伯勞也。","n":"夏小正作百鷯。月令注作博勞。詩箋作伯勞。古音同也。鶪夏小正、孟子作鴂。乃雙聲假借字。小正、月令皆云五月鳴。惟豳風曰。七月鳴鶪。左傳曰。伯趙氏司至者也。"}]},"𪅡":{"expl":"天龠也。从鳥翏聲。","rad":"鳥","fq":"力救切","vol":"04","py":"liù","duan":[{"e":"天蘥也。","n":"𪅡今本作鷚。蘥今本作鸙。宋本、李燾本作𪅡、作龠。釋鳥。鷚天鸙。釋文曰。鷚字又作𪅡。？說文作蘥。今從之。玉篇。鸙、天蘥也。許無鸙字。郭云。大如鷃雀。色似鶉。好高飛作聲。今江東名之天鷚。音綢繆之繆。按此與隹部雡異義。"}]},"𪇬":{"expl":"卑居也。从鳥與聲。","rad":"鳥","fq":"羊茹切","vol":"04","py":"yù","duan":[{"e":"卑居也。","n":"見隹部雅下。卑音壁。"}]},"鷽":{"expl":"雗鷽，山鵲，知來事鳥也。从鳥，學省聲。","rad":"鳥","fq":"胡角切","vol":"04","py":"xué","duan":[{"e":"雗鷽、","n":"逗。"}]},"𪆩":{"expl":"鳥黑色多子。師曠曰：“南方有鳥，名曰羌𪆩，黃頭赤目，五色皆備。”从鳥就聲。","rad":"鳥","fq":"疾僦切","vol":"04","py":"jiù","duan":[{"e":"𪆩鳥。","n":"𪆩字今補。"}]},"鴞":{"expl":"鴟鴞，寕鴂也。从鳥号聲。","rad":"鳥","fq":"于嬌切","vol":"04","py":"xiāo","duan":[{"e":"鴟鴞、","n":"逗。鴟當作？。？、？也。？鴞則爲寧鴂。？舊則爲舊畱。不得舉一？字謂爲同物。又不得因鴞與梟音近謂爲一物。又不得因？鴞與鴟鵂音近謂爲一物也。？舊不可單言？。？鴞不可單言鴞。凡物以兩字爲名者、不可因一字與他物同謂爲一物。"}]},"𡴆":{"expl":"菌𡴆，地蕈。叢生田中。从屮六聲。","rad":"屮","fq":"力竹切","vol":"01","py":"lù","duan":[{"e":"菌𡴆、","n":"逗。"}]},"鴂":{"expl":"寕鴂也。从鳥夬聲。","rad":"鳥","fq":"古穴切","vol":"04","py":"jué","duan":[{"e":"寧鴂也。","n":"小正、孟子借鴂爲鶪。離騷。恐鵜鴂之先鳴。楊雄作鷤䳏。或釋爲子規。或釋爲伯勞。未得其審。而廣韵乃合鸋鴂、鶗鴂爲一物。凡物名因一字相同而溷誤之類如此。"}]},"䳳":{"expl":"鳥也。从鳥祟聲。","rad":"鳥","fq":"辛聿切","vol":"04","py":"xù","duan":[{"e":"鳥也。","n":"廣韵曰。小鳥名。"}]},"䲱":{"expl":"澤虞也。从鳥方聲。","rad":"鳥","fq":"分兩切","vol":"04","py":"fǎnɡ","duan":[{"e":"澤虞也。","n":"釋鳥。鶭、澤虞。釋文。鶭本或作鴋。說文作䲱。郭云。今婟澤鳥。常在澤中。有象主守之官。按此釋澤虞之意。謂若周禮之澤虞也。楊雄云。䲩鳩或謂之鶭鸅。葢尸鳩之一名耳。孫氏乃援以注爾雅之鴋澤虞。不知其𣃔句本異。"}]},"𪇲":{"expl":"鳥也。从鳥𢧵聲。","rad":"鳥","fq":"子結切","vol":"04","py":"jié","duan":[{"e":"𪇲鳥也。","n":"𪇲之言？也。小鳥名也。篇、韵皆云小雞。"}]},"𪄭":{"expl":"鳥也。从鳥桼聲。","rad":"鳥","fq":"親吉切","vol":"04","py":"qī","duan":[{"e":"𪄭鳥也。从鳥。桼聲。","n":"親吉切。十二部。"}]},"䳀":{"expl":"鋪豉也。从鳥失聲。","rad":"鳥","fq":"徒結切","vol":"04","py":"dié","duan":[{"e":"鋪豉也。","n":"二徐上字皆作鋪。宋刻鉉本、李燾本不作餔也。爾雅作餔。釋鳥。䳀、餔豉。此必鳥聲。如云鋪豉。自郭氏巳未詳矣。"}]},"鶤":{"expl":"鶤雞也。从鳥軍聲。讀若運。","rad":"鳥","fq":"古渾切","vol":"04","py":"kūn","duan":[{"e":"鶤雞也。","n":"釋鳥。雞三尺爲鶤。郭曰。陽溝巨鶤。古之名雞。釋文。字或作鵾。九辯。鵾雞啁哳而悲鳴。王云。奮翼鳴呼而低昂。王正謂雞三尺者也。高注淮南曰。鶤雞、鳳皇別名。張揖注上林賦曰。昆雞似鶴。黃白色。則非釋鳥所云矣。許意不謂雞嘼。亦不謂鳳皇。故其字廁於此。葢與張說同也。"}]},"𪁾":{"expl":"鳥也。从鳥芺聲。","rad":"鳥","fq":"烏浩切","vol":"04","py":"ǎo","duan":[{"e":"𪁾鳥也。","n":"各本𪇲𪄭𪁾等字皆刪。今補。三字句。疑卽釋鳥之鴢頭。"}]},"䳔":{"expl":"鳥也。从鳥臼聲。","rad":"鳥","fq":"居玉切","vol":"04","py":"jú","duan":[{"e":"䳔鳥也。从鳥𦥑聲。","n":"居玉切。三部。"}]},"𪆄":{"expl":"𪆄𪃐，桃蟲也。从鳥焦聲。","rad":"鳥","fq":"卽消切","vol":"04","py":"jiāo","duan":[{"e":"𪆄𪃐、","n":"逗。"}]},"熏":{"expl":"火煙上出也。从屮从黑。屮黑，熏黑也。","rad":"屮","fq":"許云切","vol":"01","py":"xūn","duan":[{"e":"火煙上出也。","n":"豳風曰。穹窒熏鼠。"}]},"𪃐":{"expl":"𪆄𪃐也。从鳥眇聲。","rad":"鳥","fq":"亡沼切","vol":"04","py":"miǎo","duan":[{"e":"𪆄𪃐也。从鳥。眇聲。","n":"眇、小也。亡沼切。二部。"}]},"𪅳":{"expl":"鳥少美長醜爲𪅳離。从鳥畱聲。","rad":"鳥","fq":"力求切","vol":"04","py":"liú","duan":[{"e":"鳥少美長醜爲𪅳離。","n":"邶風。瑣兮尾兮。畱離之子。毛云。畱離鳥也。少好長醜。釋鳥曰。鳥少美長醜爲？鷅。？與畱、鷅與離皆同也。詩字本作畱。爾雅注及音義可證。詩音義則淺人改易之。按此詩以少好長醜比衞臣始有小善。終無成功。陸疏乃謂流離、䲷也。其子長大還食其母。絕非爾雅、毛鄭許諸君意也。"}]},"𪅀":{"expl":"鳥也。从鳥堇聲。","rad":"鳥","fq":"那干切","vol":"04","py":"nán","duan":[{"e":"𪄿鳥也。","n":"今爲難易字、而本義隱矣。"}]},"鶨":{"expl":"欺老也。从鳥彖聲。","rad":"鳥","fq":"丑絹切","vol":"04","py":"chuàn","duan":[{"e":"欺老也。","n":"釋鳥。鶨、䳢老。下云鳸鴳。按許上文說九雇。旣云老雇、鴳也。則以老下屬。與賈逵、樊光同。此以老上屬。下云鴳雇也。復與舍人、李巡、孫炎同。葢兩從未定也。欺老未詳何鳥。"}]},"𪁑":{"expl":"鳥也。从鳥，說省聲。","rad":"鳥","fq":"弋雪切","vol":"04","py":"yuè","duan":[{"e":"𪁑鳥也。","n":"玉篇。水鳥也。"}]},"𩿢":{"expl":"鳥也。从鳥主聲。","rad":"鳥","fq":"天口切","vol":"04","py":"tǒu","duan":[{"e":"𩿢鳥也。","n":"篇、韵皆云水鳥。黑色。"}]},"𪂆":{"expl":"鳥也。从鳥昏聲。","rad":"鳥","fq":"武巾切","vol":"04","py":"mín","duan":[{"e":"𪂆鳥也。","n":"廣韵。鳥似翠而赤喙。玉篇作鴖作𪆨。"}]},"鷯":{"expl":"刀鷯。剖葦，食其中蟲。从鳥𤋯聲。","rad":"鳥","fq":"洛簫切","vol":"04","py":"liáo","duan":[{"e":"刀鷯、","n":"逗。"}]},"鶠":{"expl":"鳥也。其雌皇。从鳥匽聲。一曰鳳皇也。","rad":"鳥","fq":"於幰切","vol":"04","py":"yǎn","duan":[{"e":"鶠鳥也。其雌皇。","n":"釋鳥。鶠鳳、其雌皇。說者便以鳳皇釋之。據許則有鳥名鶠鳳。非可以鳳釋鶠也。鳥字葢鳳之誤。三字一句。"}]},"鴲":{"expl":"瞑鴲也。从鳥旨聲。","rad":"鳥","fq":"旨夷切","vol":"04","py":"zhī","duan":[{"e":"瞑鴲也。","n":"廣韵曰。小靑雀也。按廣韵葢謂卽竊脂。"}]},"禔":{"expl":"安福也。从示是聲。《易》曰：“禔旣平。”","rad":"示","fq":"市支切","vol":"01","py":"zhī","duan":[{"e":"安也。","n":"本安下有福。今依李善文𨕖注。"}]},"艸":{"expl":"百芔也。从二屮。凡艸之屬皆从艸。","rad":"艸","fq":"倉老切","vol":"01","py":"cǎo","duan":[{"e":"百芔也。","n":"卉下曰。艸之緫名也。是謂轉注。二屮三屮一也。引伸爲艸稿、艸具之艸。"}]},"鵅":{"expl":"烏鸔也。从鳥各聲。","rad":"鳥","fq":"盧各切","vol":"04","py":"luò","duan":[{"e":"烏鸔也。","n":"見釋鳥。郭云。水鳥也。按此與隹部雒音同義別。"}]},"鸔":{"expl":"烏鸔也。从鳥暴聲。","rad":"鳥","fq":"蒲木切","vol":"04","py":"bǔ","duan":[{"e":"烏鸔也。从鳥。㬥聲。","n":"蒲木切。古音在二部。"}]},"鶴":{"expl":"鳴九臯，聲聞于天。从鳥隺聲。","rad":"鳥","fq":"下各切","vol":"04","py":"hè","duan":[{"e":"鶴鳴九皐。聲聞于天。","n":"鶴字今補。此見詩小雅。毛曰。皐、澤也。言身隱而名著也。爾雅無鶴。故偁詩。後人鶴與鵠相亂。"}]},"鷺":{"expl":"白鷺也。从鳥路聲。","rad":"鳥","fq":"洛故切","vol":"04","py":"lù","duan":[{"e":"白鷺也。","n":"釋鳥曰。鷺、舂鋤。周頌、魯頌傳曰。鷺、白鳥也。按大雅。白鳥翯翯。白鳥謂鷺。傳不言者、人所共知也。漢人謂鷺爲白鳥也。於頌則以人所知說其所不知。此傳注之體也。陸氏疏云。好而潔白故謂之白鳥。此白鷺當作白鳥。許之例多因毛傳也。舂鋤者、謂其狀俯仰如舂如鋤。"}]},"鵠":{"expl":"鴻鵠也。从鳥告聲。","rad":"鳥","fq":"胡沃切","vol":"04","py":"hú","duan":[{"e":"黃鵠也。","n":"黃各本作鴻。今依玄應書、李善西都賦注正。戰國策。黃鵠游於江海。淹於大沼。奮其六翮而陵淸風。賈生惜誓曰。黃鵠一舉兮知山川之紆曲。再舉兮知天地之圜方。凡經史言鴻鵠者皆謂黃鵠也。或單言鵠。或單言鴻。"}]},"鴻":{"expl":"鴻鵠也。从鳥江聲。","rad":"鳥","fq":"戶工切","vol":"04","py":"hónɡ","duan":[{"e":"鴻、","n":"逗。此複舉字之未刪者。"}]},"𪀖":{"expl":"禿𪀖也。从鳥尗聲。","rad":"鳥","fq":"七由切","vol":"04","py":"qiū","duan":[{"e":"秃𪀖也。","n":"小雅毛傳。鶖、禿鶖也。張尙對孫皓曰。鳥之大者有禿鶖。古今注曰。扶老、秃秋也。大者頭高八尺。李時珍說其形甚詳。云頭項皆無毛。此其偁禿之故乎。"}]},"鴛":{"expl":"鴛鴦也。从鳥夗聲。","rad":"鳥","fq":"於袁切","vol":"04","py":"yuān","duan":[{"e":"鴛鴦也。","n":"小雅傳曰。鴛鴦、匹鳥也。古今注曰。雌雄未嘗相離。按鸂𪀦者、鴛鴦屬也。"}]},"鴦":{"expl":"鴛鴦也。从鳥央聲。","rad":"鳥","fq":"於良切","vol":"04","py":"yānɡ","duan":[{"e":"鴛鴦也。","n":"二字雙聲。"}]},"鵽":{"expl":"鵽鳩也。从鳥叕聲。","rad":"鳥","fq":"丁刮切","vol":"04","py":"duò","duan":[{"e":"鵽鳩也。","n":"釋鳥鵽鳩。郭連下文宼雉爲一物。釋鳥宼雉泆泆。郭云。卽鵽鳩也。據許不云宼雉也。則許讀不同郭也。郭云。鵽大如鴿。出北方沙漠地。俗名突厥雀。按南都賦。歸雁鳴鵽。黃稻鱻魚。以爲勺藥。若莊子逸篇云。青鵽愛子忘親。此必別是一物也。"}]},"莊":{"expl":"上諱。","rad":"艸","fq":"側羊切","vol":"01","py":"zhuānɡ","duan":[{"e":"上諱。","n":"見示部。其說解當曰艸大也、从艸壯聲。其次當在菿蔪二字之閒。此形聲兼會意字。壯訓大。故莊訓艸大。古書莊壯多通用。引伸爲凡壯盛精嚴之義。論語。臨之以莊。苞咸曰。莊、嚴也是也。側羊切。十部。"}]},"𪂚":{"expl":"蔞鵝也。从鳥坴聲。","rad":"鳥","fq":"力竹切","vol":"04","py":"lù","duan":[{"e":"蔞䳘也。","n":"釋鳥。鵱、鷜鵝。郭云。今之野鵝。按篇、韵皆以鵱鷜爲句。許作蔞而下屬。則古讀不同。蔞䳘、鳥名。今不定爲何鳥也。論衡云。蛢彈雀則失鷜。"}]},"鴚":{"expl":"鴚鵝也。从鳥可聲。","rad":"鳥","fq":"古俄切","vol":"04","py":"ɡē","duan":[{"e":"鴚䳘也。","n":"三字句。方言。鴈自關而東謂之鴚䳘。南楚之外謂之䳘。或謂之鶬鴚。廣雅𪀉鵞倉𪀉鴈也。本此。按楊、張所云鴈者、鴻雁也。許以鴻雁字系隹部。此不云鴚䳘雁也。知許意不爲鴻雁。鴚字亦作鴐。大玄作鴚䳘。子虛、上林、反離騷、南都賦皆作駕鵞古作駕。山海經駕鳥、魯大夫榮駕鵞皆卽駕鵞也。古加聲與可聲同音。張揖注上林賦曰。駕鵞、野鵞也。然則非家鵞。亦非鴻雁。鴻雁屬也。許意當同。○魯大夫榮駕鵞。左傳、漢書皆作駕。與山海經同。毛居正云从馬誤。毛非也。釋文宋刊皆作駕。通志堂乃於定元年改作駕。"}]},"䳘":{"expl":"鴚鵝也。从鳥我聲。","rad":"鳥","fq":"五何切","vol":"04","py":"é","duan":[{"e":"鴚䳘也。从鳥。我聲。","n":"五何切。十七部。"}]},"鴈":{"expl":"䳘也。从鳥、人，厂聲。","rad":"鳥","fq":"五晏切","vol":"04","py":"yàn","duan":[{"e":"䳘也。","n":"鴈與雁各字。䳘與鴚䳘各物。許意隹部雁爲鴻雁。鳥部鴈爲䳘。鴚䳘爲野䳘。單呼䳘、爲人家所畜之䳘。今字雁鴈不分久矣。禮經單言鴈者皆鴻雁也。言舒鴈者則䳘也。爾雅舒鴈鵝是也。李巡云。野曰鴈。家曰鵝。鵝謂之舒鴈者、家養馴不畏人。飛行舒遟也。是則當作舒雁。謂雁之舒者也。雁在野。䳘爲家雁也。儀禮。出如舒鴈。不言如鴈。内則。舒鴈翠。別於下文鴈腎。䳘之名舒鴈顯然。而某氏注爾雅云。在野舒翼飛遠者爲鴈。以爾雅舒鴈爲一物。鵝爲一物。非是。䳘固有單呼鴈者。如莊子。命豎子殺鴈而烹之。謂䳘也。王褒僮約云鴈鶩百餘者爲䳘鴨。別於上文云繳鴈彈鶩者爲雁鳧。葢雁鴈不分久矣。許當云鴈、舒雁也。舒雁、䳘也。文乃備。"}]},"鶩":{"expl":"舒鳧也。从鳥敄聲。","rad":"鳥","fq":"莫卜切","vol":"04","py":"wù","duan":[{"e":"舒鳧也。","n":"几部曰。舒鳧、鶩也。與釋鳥同。舍人、李巡云。鳧、野鴨名。鶩、家鴨名。許於鳧下當云鳧、水鳥也。舒鳧、鶩也。文乃備。左傳疏云。謂之舒鳧者、家養馴不畏人。故飛行遟。別野名耳。某氏注云在野舒飛遠者爲鳧。非是。詞章家鳧亦呼鶩。此如今野人雁亦呼雁䳘也。春秋？露。張湯問祠宗廟。或以鶩當鳧。可用否。仲舒曰。鶩非鳧。鳧非鶩也。以鶩當鳧名實不相應。以承大廟不可。此舒鳧與鳧之判。廣雅云。鳧鶩𪁗也。此統言而未析言之也。"}]},"鷖":{"expl":"鳧屬。从鳥殹聲。《詩》曰：“鳧鷖在梁。”","rad":"鳥","fq":"烏雞切","vol":"04","py":"yī","duan":[{"e":"鳧屬也。","n":"大雅鳧鷖傳曰。鳧、水鳥也。鷖、鳧屬也。按此謂鳧屬。非謂舒鳧屬也。周禮。王后之五路。安車彫面鷖緫。故書鷖或爲繄。鄭司農云。繄讀爲鳧鷖之鷖。鷖緫者、靑黑色。以繒爲之。按於此知此鳥靑黑色也。陸、孔皆引倉頡解詁曰。鷖、鷗也。一名水鴞。許云鷗、水鴞。而不云鷖、鷗也。則許不謂一物也。鳧屬者、似鳧而別。其釋鳥之鸍沈鳧乎。"}]},"𪃈":{"expl":"𪃈𪇷，鳧屬。从鳥契聲。","rad":"鳥","fq":"古節切","vol":"04","py":"jié","duan":[{"e":"𪃈𪇷、","n":"逗。"}]},"𪇷":{"expl":"𪃈𪇷也。从鳥辥聲。","rad":"鳥","fq":"魚列切","vol":"04","py":"jiá","duan":[{"e":"𪃈𪇷也。从鳥。辥聲。","n":"魚列切。十五部。集韵牛轄切。"}]},"䴌":{"expl":"水鳥也。从鳥蒙聲。","rad":"鳥","fq":"莫紅切","vol":"04","py":"ménɡ","duan":[{"e":"水鳥也。","n":"史記上林賦說水鳥有煩鶩。徐廣曰。煩鶩一作番？。按矛聲敄聲之字、音轉多讀如蒙。賦文當依此本。"}]},"鷸":{"expl":"知天將雨鳥也。从鳥矞聲。《禮記》曰：“知天文者冠鷸。”","rad":"鳥","fq":"余律切","vol":"04","py":"yù","duan":[{"e":"知天將雨鳥也。","n":"釋鳥。翠鷸。李巡、樊光、郭璞皆云一鳥。許於羽部曰。翠、靑羽雀也。合此條知其讀不同。各爲一鳥。"}]},"蓏":{"expl":"在木曰果，在地曰蓏。从艸从㼌。","rad":"艸","fq":"郎果切","vol":"01","py":"luǒ","duan":[{"e":"在木曰果。在艸曰蓏。","n":"各本作在地曰蓏。今正。考齊民要術引說文。在木曰果。在艸曰蓏。以別於許愼注淮南云。在樹曰果。在地曰蓏。然則賈氏所據未誤。後人用許淮南注、臣瓚漢書注改之。惟在艸曰蓏。故蓏字从艸。凡爲傳注者主說大義。造字書者主說字形。此所以注淮南、作說文出一手而互異也。應劭、宋衷云。木實曰果。艸實曰蓏。與說文合。若張晏云。有核曰果。無核曰蓏。臣瓚云。木上曰果。地上曰蓏。馬融、鄭康成云。果、桃李屬。蓏、瓜瓠屬。高注呂氏春秋云。有實曰果。無實曰蓏。沈約注春秋元命苞云。木實曰果。蓏、瓜瓠之屬。韓康伯注易傳云。果蓏者物之實。說各不同。皆無不合。高云有實無實、卽有核無核也。"}]},"𪇊":{"expl":"𪇊鷈也。从鳥辟聲。","rad":"鳥","fq":"普擊切","vol":"04","py":"pì","duan":[{"e":"𪇊鷈也。","n":"釋鳥。鷉須鸁。按單呼曰鷈。絫呼曰𪇊鷈。方言。野鳧其小而好𣳚水中者、南楚之外謂之鷿鷉。大者謂之鶻鷉。南都賦作鸊鶙。"}]},"鷈":{"expl":"𪇊鷈也。从鳥虒聲。","rad":"鳥","fq":"土雞切","vol":"04","py":"tī","duan":[{"e":"𪇊鷈也。从鳥虒聲。","n":"土雞切。十六部。按？？、𪇊鷈皆曡韵。"}]},"𪈒":{"expl":"𪈒鷀也。从鳥盧聲。","rad":"鳥","fq":"洛乎切","vol":"04","py":"lú","duan":[{"e":"𪈒鷀也。","n":"釋鳥。鶿鷧。郭云。卽鸕鶿也。按今江蘇人謂之水老鴉。畜以捕魚。？者謂其色黑也。鷀者謂其不𡖉而吐生。多者生八九。少生五六。相連而出。若絲緒也。有單言？者。上林賦箴疵鵁盧、南都賦鵾鸕是也。有單言鷀者。釋鳥是也。"}]},"鷀":{"expl":"𪈒鷀也。从鳥兹聲。","rad":"鳥","fq":"疾之切","vol":"04","py":"cí","duan":[{"e":"𪈒鷀也。从鳥。茲聲。","n":"疾之切。一部。"}]},"𪆖":{"expl":"鷀也。从鳥壹聲。","rad":"鳥","fq":"乙冀切","vol":"04","py":"yì","duan":[{"e":"鷀也。从鳥。壹聲。","n":"乙冀切。十五部。"}]},"𪀐":{"expl":"𪀐绉也。从鳥乏聲。","rad":"鳥","fq":"平立切","vol":"04","py":"fú","duan":[{"e":"𪀐鵖也。","n":"釋鳥。鵖鴔、戴鵀。郭云。鵀卽頭上勝。今亦呼爲戴勝。按說文倒之曰？鵖。疑當從爾雅。鵖戴、一音也。？鵀勝、一音也。吕覽作任。勝與任六部七部合音冣近。方言又謂之戴南。月令。戴勝降於桑。鄭云。戴勝、織紝之鳥。郭注方言云。勝所以纏紝。按木部云。榺、機持經者。糸部云。紝、機縷也。此鳥之首文有如纏機縷之榺。故曰戴勝。方言又謂之？鶝。鵖？之雙聲也。"}]},"绉":{"expl":"𪀐绉也。从鳥皀聲。","rad":"鳥","fq":"彼及切","vol":"04","py":"bí","duan":[{"e":"𪀐鵖也。从鳥。皀聲。","n":"彼及切。七部。"}]},"鴇":{"expl":"鳥也。肉出尺𦛹。从鳥𠤏聲。","rad":"鳥","fq":"博好切","vol":"04","py":"bǎo","duan":[{"e":"鴇鳥也。","n":"鴇見詩、禮記。陸疏曰。連蹄。性不樹止。"}]},"𪆫":{"expl":"𪄉𪆫也。从鳥渠聲。","rad":"鳥","fq":"强魚切","vol":"04","py":"qú","duan":[{"e":"雝𪆫也。","n":"見隹部？下。"}]},"䳼":{"expl":"水鴞也。从鳥區聲。","rad":"鳥","fq":"烏侯切","vol":"04","py":"ōu","duan":[{"e":"水鴞也。","n":"山海經注曰。鷗、水鷂也。按列子作漚。"}]},"芝":{"expl":"神艸也。从艸从之。","rad":"艸","fq":"止而切","vol":"01","py":"zhī","duan":[{"e":"神芝也。","n":"釋艸曰。苬芝。論衡曰。土氣和、故芝艸生。"}]},"䳁":{"expl":"鳥也。从鳥犮聲。讀若撥。","rad":"鳥","fq":"蒲達切","vol":"04","py":"bó","duan":[{"e":"䳁鳥也。从鳥。犮聲。讀若撥。","n":"蒲達切。十五部。"}]},"𪅟":{"expl":"鳥也。从鳥庸聲。","rad":"鳥","fq":"余封切","vol":"04","py":"yónɡ","duan":[{"e":"𪅟鳥也。","n":"上林賦說水鳥有庸渠。史記作？？。郭曰。？？似鶩。灰色而雞足。一名章渠。吳都賦？？。劉注同郭。李善音庸渠。按此鳥本單呼？也。"}]},"鶃":{"expl":"鳥也。从鳥兒聲。《春秋傳》曰：“六鶃退飛。”","rad":"鳥","fq":"五歴切","vol":"04","py":"yì","duan":[{"e":"鶃鳥也。","n":"字見春秋經文十六年。水鳥也。博物志曰。鷁雄雌相視則孕。或曰。雄鳴上風。雌鳴下風。薛綜曰。鷁首者、船頭象鷁鳥。厭水神。按今字多作鷁。"}]},"鴺":{"expl":"鴺胡，污澤也。从鳥夷聲。","rad":"鳥","fq":"杜兮切","vol":"04","py":"tí","duan":[{"e":"鴺胡、","n":"逗。"}]},"鴗":{"expl":"天狗也。从鳥立聲。","rad":"鳥","fq":"力入切","vol":"04","py":"lì","duan":[{"e":"天狗也。","n":"見釋鳥。郭曰。小鳥也。靑似翠。食魚。江東呼爲水狗。按今所在園池有之。謂之魚狗。亦謂之魚虎。"}]},"鶬":{"expl":"麋鴰也。从鳥倉聲。","rad":"鳥","fq":"七岡切","vol":"04","py":"cānɡ","duan":[{"e":"麋鴰也。","n":"見釋鳥。郭云。今呼鶬鴰。師古曰。今關西呼爲鴰鹿。山東通謂之鶬。鄙俗名爲錯落。司馬彪云。鶬似鴈而黑。"}]},"鴰":{"expl":"麋鴰也。从鳥𠯑聲。","rad":"鳥","fq":"古活切","vol":"04","py":"ɡuā","duan":[{"e":"麋鴰也。从鳥。𠯑聲。","n":"古活切。十五部。"}]},"𪁉":{"expl":"𪁉𪂴也。从鳥交聲。一曰𪁉𪈒也。","rad":"鳥","fq":"古肴切","vol":"04","py":"jiāo","duan":[{"e":"𪁉𪂴也。","n":"三字句。釋鳥。鳽、鵁鶄。職方氏。楊州其畜宜鳥獸。鄭云。孔雀、鸞、鵁鶄、犀、象之屬。史記上林賦𪁉𪂴。漢書作交精。爾雅音義曰。本亦作交精。"}]},"𪂴":{"expl":"𪁉𪂴也。从鳥青聲。","rad":"鳥","fq":"子盈切","vol":"04","py":"jīnɡ","duan":[{"e":"𪁉𪂴也。从鳥。靑聲。","n":"子盈切。十一部。按辭章家有單呼鶄者。吳都賦。鶄鶴𪃩鶬。謂四鳥也。"}]},"萐":{"expl":"萐莆，瑞艸也。堯時生於庖廚，扇暑而涼。从艸疌聲。","rad":"艸","fq":"士洽切","vol":"01","py":"shà","duan":[{"e":"萐莆、","n":"逗。"}]},"𪈁":{"expl":"𪈁鴜也。从鳥箴聲。","rad":"鳥","fq":"職深切","vol":"04","py":"zhēn","duan":[{"e":"𪇳鴜也。","n":"上林賦箴疵。史記作𪇳䳄。張揖曰。箴疵似魚虎而蒼黑色。按鍼貲二音。鴜之言觜也。觜、口也。𪇳鴜、葢其咮似鍼之銳。"}]},"鴜":{"expl":"𪈁鴜也。从鳥此聲。","rad":"鳥","fq":"卽夷切","vol":"04","py":"cí","duan":[{"e":"𪇳鴜也。从鳥。此聲。","n":"卽夷切。十六部。○按自鶩舒鳧也至此皆謂水鳥。而？鵖鴇鶬非水鳥。辭章家舖陳水鳥。或舉鴇鶬而不舉鵖？。"}]},"鷻":{"expl":"雕也。从鳥敦聲。《詩》曰：“匪鷻匪𪀝。”","rad":"鳥","fq":"度官切","vol":"04","py":"tuán","duan":[{"e":"雕也。","n":"隹部曰。雕、鷻也。今小雅四月匪鶉。鶉字或作？。毛曰。？、雕也。隹部隼下曰。一曰鶉字。鶉者鷻之省。鷻鶉字與隹部？字別。經典鶉首、鶉火、鶉尾字當爲鷻。魏風縣鶉、内則鶉羹字當爲？。當隨文釋之。漢書音義、廣雅皆雕鷲爲一鳥。許二之。且？不列於鷙鳥。"}]},"𪀝":{"expl":"鷙鳥也。从鳥屰聲。","rad":"鳥","fq":"與專切","vol":"04","py":"yuān","duan":[{"e":"鷙鳥也。","n":"此今之鶚字也。咢、說文作㖾。鶚、廣雅作？。古音屰聲㖾聲皆在五部。五各切。作鶚者、𣜩變耳。自鷻至鷐九篆皆鷙鳥、獨於𪀝鷂言之者、𪀝鷂無他名則直謂鷙鳥而已矣。詩。匪鷻匪鳶。正義鳶作鶚。引孟康曰。鶚、大雕也。又引說文。𪀝、鷙鳥也。是孔沖遠固知𪀝卽鶚字。陸德明本乃作鳶。云以專反。今毛詩本因之。又以與專反改說文𪀝字之音。誤之甚矣。鳶夏小正作弋。與職切。俗作鳶。與專切。此猶鷕切以水、譌爲以沼耳。弋者、？也。非鶚也。"}]},"鷳":{"expl":"鴟也。从鳥閒聲。","rad":"鳥","fq":"戶間切","vol":"04","py":"xián","duan":[{"e":"鴟也。","n":"隹部曰。鴟、𨿠也。𨿠、鴟也。又名鷳。今之鷂鷹也。廣雅曰。鷳鴟。夏小正謂之弋。十有二有鳴弋。弋卽鴟也。弋之字變爲鳶。讀與專切。鳶行而弋廢矣。鳶讀與專切者、與鷳㬪韵而又雙聲。毛詩正義引倉頡解詁鳶卽鴟也。然則倉頡有鳶字。从鳥弋聲。許無者、謂鷳爲正字、鳶爲俗字也。毛詩四月匪鶚。說文作匪𪀝。陸釋文作匪鳶。不獨改其字。且非其物矣。大雅。鳶飛戾天。魚躍于淵。語與四月相類。鳶亦當爲𪀝。箋云。鳶、鴟之類。云類則別於鴟。經文字本爲𪀝明矣。正義又引說文云。鳶、鷙鳥也。此亦引說文𪀝、鷙鳥而從俗寫爲鳶耳。葢唐初巳認𪀝爲鳶。二字不分。故正義不能質言。"}]},"鷂":{"expl":"鷙鳥也。从鳥䍃聲。","rad":"鳥","fq":"弋笑切","vol":"04","py":"yào","duan":[{"e":"鷙鳥也。","n":"釋鳥。鷣、負雀。郭曰。鷣、鷂也。江東呼之爲鷣。按鷣古音淫。見釋文。今音燿。見廣韵。語之轉也。說文鷂卽鷣。以其善捉雀。故亦爲鷙鳥。"}]},"鷢":{"expl":"白鷢，王鴡也。从鳥厥聲。","rad":"鳥","fq":"居月切","vol":"04","py":"jué","duan":[{"e":"白鷢、","n":"逗。"}]},"鴡":{"expl":"王鴡也。从鳥且聲。","rad":"鳥","fq":"七余切","vol":"04","py":"jū","duan":[{"e":"王鴡也。","n":"按鴡鳩見詩、春秋傳。傳曰。雎鳩氏司馬也。五鳩鳩民之一。許不當不箸鴡鳩二字。王鴡也之上當出鴡鳩。乃與前文鶌鳩、祝鳩、尸鳩爲一例。釋鳥。雎鳩、王雎。郭云。雕類。今江東呼之爲鶚。周南毛傳曰。雎鳩、王雎也。鳥摯而有別。摯本亦作鷙。古字同。"}]},"鸛":{"expl":"鸛專，畐蹂。如䧿，短尾。射之，銜矢射人。从鳥雚聲。","rad":"鳥","fq":"呼官切","vol":"04","py":"huān","duan":[{"e":"𪈩專、","n":"逗。"}]},"鸇":{"expl":"鷐風也。从鳥亶聲。","rad":"鳥","fq":"諸延切","vol":"04","py":"zhān","duan":[{"e":"鷐風也。","n":"秦風作晨風。釋鳥、毛傳皆云。晨風、鸇也郭云。鷂屬。孟子趙注謂之土鸇。"}]},"莆":{"expl":"萐莆也。从艸甫聲。","rad":"艸","fq":"方矩切","vol":"01","py":"fǔ","duan":[{"e":"萐莆也。从艸。甫聲。","n":"方矩切。五部。鍇本苖莆二字在𦯄下荼上。"}]},"鷐":{"expl":"鷐風也。从鳥晨聲。","rad":"鳥","fq":"植鄰切","vol":"04","py":"chén","duan":[{"e":"鷐風也。","n":"一名翰。見羽部。"}]},"鷙":{"expl":"擊殺鳥也。从鳥執聲。","rad":"鳥","fq":"脂利切","vol":"04","py":"zhì","duan":[{"e":"擊殺鳥也。","n":"夏小正。六月鷹始摯。月令。鷹隼蚤鷙。古字多假摯爲鷙。儒行。鷙蟲攫搏。注曰。鷙从鳥、𦥎省聲。此注正義本誤。郭忠恕所據不誤。六月毛傳云。輊、摯也。士喪禮注云。輖、𦥎也。考工記注云。摯、輖也。然則𦥎卽摯字。摯之或體也。鄭注少言字體。此言之者。葢鷙上从執。俗認爲執聲。則當在侵韵。而非音理。故云摯省聲以正之。摯之在質術韵而不在侵緝易明也。擊殺鳥者、謂能擊殺之鳥。自鷻至鷐風皆擊殺鳥也。故釋鷙。"}]},"鴥":{"expl":"鸇飛皃。从鳥穴聲。《詩》曰：“鴥彼晨風。”","rad":"鳥","fq":"余律切","vol":"04","py":"yù","duan":[{"e":"鸇飛皃。","n":"秦風。鴥彼晨風。毛曰。鴥、疾飛皃。許專系諸鸇。"}]},"鶯":{"expl":"鳥也。从鳥，榮省聲。《詩》曰：“有鶯其羽。”","rad":"鳥","fq":"烏莖切","vol":"04","py":"yīnɡ","duan":[{"e":"鳥有文章皃。","n":"各本作鳥也。必淺人所改。今正。毛詩曰。交交桑扈。有鶯其羽。有鶯其領。傳曰。鶯鶯然有文章皃。皃舊作也。非。鶯鶯猶熒熒也。皃其光彩不定。故从熒省。會意兼形聲。自淺人謂鶯卽鸎字。改說文爲鳥也。而與下引詩不貫。於形聲會意亦不合。不可以不辨也。"}]},"鴝":{"expl":"鴝鵒也。从鳥句聲。","rad":"鳥","fq":"其俱切","vol":"04","py":"qú","duan":[{"e":"鴝鵒也。","n":"今之八哥也。左氏春秋昭二十五年。有鸜鵒來巢。鸜本又作鴝。公羊作鸛。音權。穀梁作鸜。亦作鸛。考工記作鸛。亦作鸜。郭注山海經云。鸛鵒、鴝鵒也。按句瞿音同。作鸛音權者、語轉也。鴝與隹部雊各字。"}]},"鵒":{"expl":"鴝鵒也。从鳥谷聲。古者鴝鵒不踰泲。","rad":"鳥","fq":"余蜀切","vol":"04","py":"yù","duan":[{"e":"鴝鵒也。从鳥。谷聲。","n":"余蜀切。三部。"}]},"鷩":{"expl":"赤雉也。从鳥敝聲。《周禮》曰：“孤服鷩冕。”","rad":"鳥","fq":"幷列切","vol":"04","py":"biē","duan":[{"e":"赤雉也。","n":"隹部雉十四穜。有鷩雉。釋鳥。鷩雉。樊光曰。丹雉也。左傳。丹鳥氏司閉也。杜曰。丹鳥、鷩雉也。以立秋來。立冬去。入大水爲蜃。周禮鷩冕注曰。鷩畫以雉。謂華蟲也。華蟲、五色之蟲。繢人職曰鳥獸蛇襍四時五色以章之、謂是也。考工記鳥獸蛇注曰。蟲之毛鱗有文采者也。按鄭意鷩爲雉五色。不云赤雉也。許云赤雉。與樊光合。"}]},"鵔":{"expl":"鵔鸃，鷩也。从鳥夋聲。","rad":"鳥","fq":"私閏切","vol":"04","py":"jùn","duan":[{"e":"鵔鸃、","n":"逗。"}]},"鸃":{"expl":"鵔鸃也。从鳥義聲。秦漢之初，侍中冠鵔鸃冠。","rad":"鳥","fq":"魚羈切","vol":"04","py":"yí","duan":[{"e":"鵔鸃也。从鳥。義聲。","n":"魚羈切。古音在十七部。"}]},"𪄱":{"expl":"雉屬，戇鳥也。从鳥，𨗁省聲。","rad":"鳥","fq":"都歴切","vol":"04","py":"dí","duan":[{"e":"雉屬。戇鳥也。","n":"戇、愚也。"}]},"虋":{"expl":"赤苗，嘉穀也。从艸釁聲。","rad":"艸","fq":"莫奔切","vol":"01","py":"mén","duan":[{"e":"赤苗。","n":"句。"}]},"鶡":{"expl":"似雉，出上黨。从鳥曷聲。","rad":"鳥","fq":"胡割切","vol":"04","py":"hé","duan":[{"e":"佀雉。出上黨。","n":"後書輿服志。虎賁、羽林皆鶡冠。鶡者、勇雉也。其鬬對一死乃止。故趙武靈王以表武士。加雙鶡尾。豎左右爲鶡冠。徐廣曰。鶡似黑雉。出於上黨。"}]},"䲸":{"expl":"鳥，似鶡而青，出羌中。从鳥介聲。","rad":"鳥","fq":"古拜切","vol":"04","py":"jiè","duan":[{"e":"䲸雀也。","n":"依顏氏家訓、廣韵訂。"}]},"鸚":{"expl":"鸚䳇，能言鳥也。从鳥嬰聲。","rad":"鳥","fq":"烏莖切","vol":"04","py":"yīnɡ","duan":[{"e":"鸚䳇、","n":"逗。"}]},"䳇":{"expl":"鸚䳇也。从鳥母聲。","rad":"鳥","fq":"文甫切","vol":"04","py":"wǔ","duan":[{"e":"鸚䳇也。从鳥。母聲。","n":"曲禮釋文。嬰本或作鸚。母本或作鵡。同音武。諸葛恪茂后反。按裴松之引江表傳曰。恪呼殿前鳥爲白頭翁。張昭欲使恪復求白頭母。恪亦以鳥名鸚母未有鸚父相難。此陸氏所謂茂后反也。據此知彼時作母、作䳇、不作鵡。至唐武后時。狄仁傑對云。鵡者、陛下之姓。起二子則㒳翼振矣。其字其音皆與三國時不同。此古今語言文字變移之證也。釋文當云母本或作䳇。古茂后反。今作鵡。音武。乃合。李善注文選云。鵡一作䳇。莫口反。較明析。大徐用唐韵文甫切。亦鵡音。非䳇音也。古音母在一部。"}]},"鷮":{"expl":"走鳴長尾雉也。乘輿以爲防釳，著馬頭上。从鳥喬聲。","rad":"鳥","fq":"巨嬌切","vol":"04","py":"jiāo","duan":[{"e":"長尾雉。走且鳴。","n":"依毛詩正義、韵會訂。隹部雉十四穜。有鷮雉。小雅。有集維鷮。毛曰。鷮、鷮雉也。釋鳥。鷮雉。陸疏云。鷮、微小於翟。走而且鳴曰鷮鷮。薛綜曰。雉之健者爲鷮。尾長六尺。按韓詩鄭風。二矛重鷮。謂以鷮羽飾矛。"}]},"𪄼":{"expl":"雌雉鳴也。从鳥唯聲。《詩》曰“有鷕雉鳴。”","rad":"鳥","fq":"以沼切","vol":"04","py":"yǎo","duan":[{"e":"雌雉鳴也。","n":"邶風。有鷕雉鳴。又云。雉鳴求其牡。毛曰。鷕、雌雉聲也。此望文爲義。"}]},"䴎":{"expl":"鼠形。飛走且乳之鳥也。从鳥畾聲。","rad":"鳥","fq":"力軌切","vol":"04","py":"lěi","duan":[{"e":"鼠形、飛走且乳之鳥也。","n":"走字疑衍。釋鳥。鼯鼠、夷由。鼯或作？。由或作？。郭云。狀如小狐。似蝙蝠。肉翅。飛且乳。其飛善從高集下。劉淵林、陶隱居說略同。其物見本艸經。上林、西京、南都、吳都諸賦亦名飛生。飛而生子故也。亦名飛鸓。亦名？鼠。其字惟史記作鸓。本艸經作？。在獸部。賦家或作蠝。或作𤢹。以其似鳥、似獸、似蟲、似鼠也。諸家皆云。以肉翼飛。而張揖云。狀如兔而鼠首。以其？飛。此本北山經。有獸狀如兔而鼠首。以其背飛。名曰飛鼠。惟張所據背作？耳。不若劉、郭說可信也。今雲南有之。"}]},"鶾":{"expl":"雉肥鶾音者也。从鳥倝聲。魯郊以丹雞祝曰：“以斯鶾音赤羽，去魯侯之咎。”","rad":"鳥","fq":"矦幹切","vol":"04","py":"hàn","duan":[{"e":"雞肥翰音者也。","n":"各本作雉肥鶾音者也。今正。曲禮。凡祭宗廟之禮。雞曰翰音。注。翰猶長也。正義曰。雞肥則其鳴聲長也。易。翰音登于天。虞曰。翰、高也。按小雅。翰飛戾天。毛曰。翰、高也。高飛曰翰。因之聲高亦曰翰。故鄭云翰猶長也。翰音之雞謂之鶾。此許以疉韵爲訓也。玉篇曰。鶾、雞肥皃。此所據說文古本不誤也。若作雉則下文丹雞不可通矣。鶾與隹部雗義別。"}]},"鴳":{"expl":"雇也。从鳥安聲。","rad":"鳥","fq":"烏諫切","vol":"04","py":"yàn","duan":[{"e":"雇也。","n":"釋鳥。鳸、鴳。舍人、李巡、孫炎皆云。鳸一名鴳。鴳、雀也。玄應曰。鴳又作鷃。一名鳸。一名鶬鴳。纂文云關中有鴳濫堆是也。按杜注左傳靑鳥氏爲鶬鴳。而九鳸有老鳸鷃鷃。是則別爲二鳥。不如玄應所說也。國語。晉平公射鴳。內則云。雉兔鶉鷃。又云。爵鷃蜩范。雇下云老雇、鴳也。皆不云鶬鴳。"}]},"鴆":{"expl":"毒鳥也。从鳥冘聲。一名運日。","rad":"鳥","fq":"直禁切","vol":"04","py":"zhèn","duan":[{"e":"毒鳥也。","n":"左傳正義。鴆鳥食蝮。以羽翮擽酒水中。飲之則殺人。按左傳鴆毒字皆作酖。假借也。酉部曰。酖、樂酒也。"}]},"荅":{"expl":"小尗也。从艸合聲。","rad":"艸","fq":"都合切","vol":"01","py":"dá","duan":[{"e":"小尗也。","n":"禮注有麻荅。廣雅云。小豆荅也。叚借爲酬荅。"}]},"鷇":{"expl":"鳥子生哺者。从鳥𣪊聲。","rad":"鳥","fq":"口豆切","vol":"04","py":"kòu","duan":[{"e":"鳥子生哺者。","n":"釋鳥生哺鷇。郭云：鳥子須母食之。生噣雛。郭云：能自食。方言：北燕朝鮮洌水之閒，爵子及雞雛皆謂之鷇。"}]},"鳴":{"expl":"鳥聲也。从鳥从口。","rad":"鳥","fq":"武兵切","vol":"04","py":"mínɡ","duan":[{"e":"鳥聲也。","n":"引伸之凡出聲皆曰鳴。"}]},"鶱":{"expl":"飛皃。从鳥，寒省聲。","rad":"鳥","fq":"虚言切","vol":"04","py":"xiān","duan":[{"e":"飛皃也。","n":"楚辭。鳳鶱翥而飛翔。"}]},"𩿈":{"expl":"鳥聚皃。一曰飛皃。从鳥分聲。","rad":"鳥","fq":"府文切","vol":"04","py":"fēn","duan":[{"e":"鳥聚皃也。","n":"言繽紛也。"}]},"鷓":{"expl":"鷓鴣，鳥名。从鳥庶聲。","rad":"鳥","fq":"之夜切","vol":"04","py":"zhè","duan":[]},"鴣":{"expl":"鷓鴣也。从鳥古聲。","rad":"鳥","fq":"古乎切","vol":"04","py":"ɡū","duan":[]},"鴨":{"expl":"鶩也。俗謂之鴨。从鳥甲聲。","rad":"鳥","fq":"烏狎切","vol":"04","py":"yā","duan":[]},"𪀦":{"expl":"谿𪀦，水鳥。从鳥式聲。","rad":"鳥","fq":"恥力切","vol":"04","py":"shì","duan":[]},"烏":{"expl":"孝鳥也。象形。孔子曰：“烏，𥃳呼也。”取其助气，故以爲烏呼。凡烏之屬皆从烏。","rad":"烏","fq":"哀都切","vol":"04","py":"wū","duan":[{"e":"孝鳥也。","n":"謂其反哺也。小爾雅曰。純黑而反哺者謂之烏。"}]},"舄":{"expl":"𩁆也。象形。","rad":"烏","fq":"七雀切","vol":"04","py":"què","duan":[{"e":"䧿也。","n":"謂舄卽䧿字。此以今字釋古字之例。古文作舄。小篆作䧿。𣆪下曰。？也。周禮注曰。勛讀爲勲。皆以今字釋古字。鳥部曰。雗鷽、䧿也。言其物。此云。舄、䧿也。言其字。舄本䧿字。自經典借爲履舄字而本義廢矣。周禮注曰。複下曰舄。禪下曰屨。小雅毛傳曰。舄、達屨也。達之言重沓也。卽複下之謂也。釋名曰。舄、腊也。複其下使乾腊也。"}]},"萁":{"expl":"豆莖也。从艸其聲。","rad":"艸","fq":"渠之切","vol":"01","py":"qí","duan":[{"e":"豆莖也。","n":"當云尗而曰豆。從漢時語也。或後人改之。楊惲傳。種一頃豆。落而爲萁。孫子兵法曰。𦮼秆一石。當吾二十石。曹操注。𦮼音忌。豆稭也。按𦮼卽萁字。潘岳馬汧督誄曰。萁稈空虛。用𦮼秆字。"}]},"焉":{"expl":"焉鳥，黃色，出於江淮。象形。凡字：朋者，羽蟲之屬；烏者，日中之禽；舄者，知太歲之所在；燕者，請子之𠋫，作巢避戊己。所䝿者故皆象形。焉亦是也。","rad":"烏","fq":"有乾切","vol":"04","py":"yān","duan":[{"e":"焉鳥、","n":"逗。"}]},"𠦒":{"expl":"箕屬。所以推棄之器也。象形。凡𠦒之屬皆从𠦒。官溥說。","rad":"𠦒","fq":"北潘切","vol":"04","py":"bān","duan":[{"e":"箕屬。所㠯推糞之器也。","n":"糞各本作弃。今依篇韵正。推糞者、推而除之也。"}]},"畢":{"expl":"田罔也。从𠦒，象畢形。微也。或曰：甶聲。","rad":"𠦒","fq":"卑吉切","vol":"04","py":"bì","duan":[{"e":"田网也。","n":"謂田獵之网也。必云田者、以其字從田也。小雅毛傳曰。畢所以掩兔也。月令注曰。罔小而柄長謂之畢。按鴛鴦傳云。畢掩而羅之。然則不獨掩兔。亦可掩鳥。皆以上覆下也。畢星主弋獵。故曰畢。亦曰䍐車。許於率下曰。捕鳥畢也。此非別有一畢。亦是掩物之网。特牲饋食禮助載鼎實之噐象之亦曰畢。此則用以上載爲異。"}]},"𨤝":{"expl":"棄除也。从廾推𠦒棄釆也。官溥說：似米而非米者，矢字。","rad":"𠦒","fq":"方問切","vol":"04","py":"fèn","duan":[{"e":"棄除也。","n":"按棄亦糞之誤。亦復舉字之未𠜂者。糞方是除。非棄也。與土部𡊅音義皆略同。禮記作糞。亦作𢹔。亦作拚。曲禮曰。凡爲長者糞之禮。少儀曰。氾埽曰埽。埽席前曰拚。老子曰。天下有道。卻走馬以糞。謂用走馬佗棄糞除之物也。左傳。小人糞除先人之敝廬。許意𡊅用帚。故曰埽除。糞用𠦒。故但曰除。古謂除穢曰糞。今人直謂穢曰糞。此古義今義之別也。凡糞田多用所除之穢爲之。故曰糞。"}]},"棄":{"expl":"捐也。从廾推𠦒棄之，从𠫓。𠫓，逆子也。","rad":"𠦒","fq":"詰利切","vol":"04","py":"qì","duan":[{"e":"捐也。","n":"手部曰。捐、棄也。"}]},"冓":{"expl":"交積材也。象對交之形。凡冓之屬皆从冓。","rad":"冓","fq":"古候切","vol":"04","py":"ɡòu","duan":[{"e":"交積材也。","n":"高注淮南曰。構、架也。材木相乗架也。按結冓當作此。今字構行而冓廢矣。木部曰。構、葢也。義別。"}]},"再":{"expl":"一舉而二也。从冓省。","rad":"冓","fq":"作代切","vol":"04","py":"zài","duan":[{"e":"一舉而二也。","n":"凡言二者、對偶之詞。凡言再者、重複之詞。一而又有加也。"}]},"爯":{"expl":"并舉也。从爪，冓省。","rad":"冓","fq":"處陵切","vol":"04","py":"chēnɡ","duan":[{"e":"幷舉也。从爪。冓省。","n":"冓爲二。爪者、手也。一手舉二。故曰幷舉。趙注孟子稱貸曰。稱、舉也。凡手舉字當作爯。凡偁揚當作偁。凡銓衡當作稱。今字通用稱。處陵切。六部。"}]},"幺":{"expl":"小也。象子初生之形。凡幺之屬皆从幺。","rad":"幺","fq":"於堯切","vol":"04","py":"yāo","duan":[{"e":"小也。","n":"通俗文曰。不長曰幺。細小曰麽。許無麽字。"}]},"幼":{"expl":"少也。从幺从力。","rad":"幺","fq":"伊謬切","vol":"04","py":"yòu","duan":[{"e":"少也。","n":"釋言曰。幼鞠稚也。又曰。冥、幼也。斯干毛傳亦云。冥、幼也。幼同幽。一作窈。"}]},"𧆑":{"expl":"尗之少也。从艸靃聲。","rad":"艸","fq":"虚郭切","vol":"01","py":"huò","duan":[{"e":"尗之少也。","n":"少讀養幼少之少。毛詩傳曰。藿猶苗也。是也。李善引說文作豆之葉也。與士喪禮注合。"}]},"麽":{"expl":"細也。从幺麻聲。","rad":"幺","fq":"亡果切","vol":"04","py":"mǒ","duan":[]},"𢆶":{"expl":"微也。从二幺。凡𢆶之屬皆从𢆶。","rad":"𢆶","fq":"於虯切","vol":"04","py":"yōu","duan":[{"e":"微也。","n":"微當作𢼸。人部曰。𢼸、眇也。小之又小則曰𢼸。"}]},"幽":{"expl":"隱也。从山中𢆶，𢆶亦聲。","rad":"𢆶","fq":"於虯切","vol":"04","py":"yōu","duan":[{"e":"隱也。","n":"𨸏部曰。隱、蔽也。小雅。桑葉有幽。毛曰。幽、黑色也。此謂幽爲黝之假借。玉藻幽衡。鄭云。幽讀爲黝。毛不易字。鄭則易之周禮牧人陰祀用幽牲。守祧幽堊之。鄭司農皆幽讀爲黝。引爾雅地謂之黝。今本幽黝字互譌。"}]},"幾":{"expl":"微也。殆也。从𢆶从戍。戍，兵守也。𢆶而兵守者，危也。","rad":"𢆶","fq":"居衣切","vol":"04","py":"jī","duan":[{"e":"微也。","n":"𣪠辭傳曰。幾者、動之微。吉凶之先見也。又曰。顏氏之子其殆庶幾乎。虞曰。幾、神妙也。"}]},"叀":{"expl":"專小謹也。从幺省；屮，財見也；屮亦聲。凡叀之屬皆从叀。","rad":"叀","fq":"職緣切","vol":"04","py":"zhuān","duan":[{"e":"小謹也。","n":"各本小上有專字。此複舉字未𠜂。又誤加寸也。"}]},"惠":{"expl":"仁也。从心从叀。","rad":"叀","fq":"胡桂切","vol":"04","py":"huì","duan":[{"e":"仁也。","n":"人部曰。仁親也。經傳或假惠爲慧。"}]},"疐":{"expl":"礙不行也。从叀，引而止之也。叀者，如叀馬之鼻。从此與牽同意。","rad":"叀","fq":"陟利切","vol":"04","py":"zhì","duan":[{"e":"礙不行也。","n":"釋言云。𤴡、。跲也豳風毛傳同。足部躓、跲也。跲、躓也。以大學懥亦作懫推之則𤴡卽躓字。音義皆同。許不謂一字殊其義者、依字形爲之說也。如許說則爾雅、毛傳假𤴡爲躓。"}]},"玄":{"expl":"幽遠也。黑而有赤色者爲玄。象幽而入覆之也。凡玄之屬皆从玄。","rad":"玄","fq":"胡涓切","vol":"04","py":"xuán","duan":[{"e":"幽遠也。","n":"老子曰。玄之又玄。衆妙之門。高注淮南子曰。天也。聖經不言玄妙。至僞尙書乃有玄德升聞之語。"}]},"玆":{"expl":"黑也。从二玄。《春秋傳》曰：“何故使吾水兹？”","rad":"玄","fq":"子之切","vol":"04","py":"zī","duan":[{"e":"黑也。从二玄。","n":"胡涓切。十二部。今本子之切。非也。按左傳。何故使吾水玆。釋文曰。玆音玄。此相傳古音。在十二部也。又曰。本亦作滋。子絲反。此俗加水作滋。因誤認爲滋。益字而入之之韵也。艸部茲從絲省聲。凡水部之滋、子部之孳、鳥部之鷀皆以茲爲聲。而玆滋字衹當音懸。不當音孜。廣韵七之作滋。一先作滋。音義各不同爲是也。且訓此之茲本假借從艸之茲。而不當用二玄之玆。蔡邕石經見於𥻳釋、漢𥻳字原者、尙書茲字五見。皆从艸。則唐石經皆作玆者非矣。今本說文滋孳鷀篆體皆誤從玆。"}]},"玈":{"expl":"黑色也。从玄，旅省聲。義當用黸。","rad":"玄","fq":"洛乎切","vol":"04","py":"lú","duan":[]},"神":{"expl":"天神，引出萬物者也。从示、申。","rad":"示","fq":"食鄰切","vol":"01","py":"shén","duan":[{"e":"天神引出萬物者也。","n":"天神引三字同在古音第十二部。"}]},"莥":{"expl":"鹿藿之實名也。从艸狃聲。","rad":"艸","fq":"敕久切","vol":"01","py":"niǔ","duan":[{"e":"鹿藿之實名也。","n":"見釋艸。"}]},"予":{"expl":"推予也。象相予之形。凡予之屬皆从予。","rad":"予","fq":"余呂切","vol":"04","py":"yǔ","duan":[{"e":"推予也。","n":"予與古今字。釋詁曰。台朕賚畀卜陽予也。按推予之予。假借爲予我之予。其爲予字一也。故台朕陽與賚畀卜皆爲予也。爾雅有此例。廣雅尙多用此例。予我之予儀禮古文、左氏傳皆作余。鄭曰。余予古今字。"}]},"舒":{"expl":"伸也。从舍从予，予亦聲。一曰舒，緩也。","rad":"予","fq":"傷魚切","vol":"04","py":"shū","duan":[{"e":"伸也。","n":"經傳或假荼。或假豫。"}]},"幻":{"expl":"相詐惑也。从反予。《周書》曰：“無或譸張爲幻。”","rad":"予","fq":"胡辦切","vol":"04","py":"huàn","duan":[{"e":"相詐惑也。","n":"詭誕惑人也。漢書。犛靬眩人。字作眩。"}]},"放":{"expl":"逐也。从攴方聲。凡放之屬皆从放。","rad":"放","fq":"甫妄切","vol":"04","py":"fànɡ","duan":[{"e":"逐也。从攴。方聲。","n":"甫妄切。十部。"}]},"敖":{"expl":"出游也。从出从放。","rad":"放","fq":"五牢切","vol":"04","py":"áo","duan":[{"e":"出遊也。","n":"邶風曰。以敖以游。敖游同義也。經傳假借爲倨傲字。"}]},"敫":{"expl":"光景流也。从白从放。讀若龠。","rad":"放","fq":"以灼切","vol":"04","py":"yuè","duan":[{"e":"光景流皃。","n":"皃各本作也。今從廣韵。謂光景流行。煜燿昭箸。"}]},"𠬪":{"expl":"物落；上下相付也。从爪从又。凡𠬪之屬皆从𠬪。讀若《詩》“摽有梅”。","rad":"𠬪","fq":"平小切","vol":"04","py":"biào","duan":[{"e":"物落也","n":"也字依韵會補草曰苓木曰落引伸之凡物皆曰落"}]},"爰":{"expl":"引也。从𠬪从于。籒文以爲車轅字。","rad":"𠬪","fq":"羽元切","vol":"04","py":"yuán","duan":[{"e":"引也。","n":"此與手部援音義皆同。韵會作引也。謂引詞也六字。謂引詞也四字當出演說文。今按援從手爰聲。訓引也。爰從𠬪從亏。訓引詞也。轉寫奪詞字。釋詁。粵于爰曰也。爰粵于也。爰粵于那都繇於也。八字同訓。皆引詞也。粵于曰爰見經傳者多。那若越語吳人之那不穀。都若孟子謨葢都君、相如傳終都攸卒。繇同由。於卽今人所用於字。凡言於者、兩物相於自此引而之彼。此八字皆由上引下之詞也。曰下云䛐也。亏下云於也。粵下云于也。烏於同引孔子曰烏于呼也。是可以得其解。"}]},"𤔔":{"expl":"治也。幺子相亂，𠬪治之也。讀若亂同。一曰理也。","rad":"𠬪","fq":"郎段切","vol":"04","py":"luàn","duan":[{"e":"治也。","n":"此與乙部亂音義皆同。"}]},"受":{"expl":"相付也。从𠬪，舟省聲。","rad":"𠬪","fq":"殖酉切","vol":"04","py":"shòu","duan":[{"e":"相付也。","n":"𠬪者自此言。受者自彼言。其爲相付一也。"}]},"蓈":{"expl":"禾粟之𥝩，生而不成者，謂之蕫蓈。从艸郎聲。","rad":"艸","fq":"魯當切","vol":"01","py":"lánɡ","duan":[{"e":"禾粟之莠生而不成者。謂之童蓈。","n":"莠各本作𥝩。鍇音穗。童各本作蕫。今依詩、爾雅音義。生而不成、謂不成莠也。不成謂之童蓈。已成謂之莠。此蓈莠二字連屬之義。云禾。粟之莠者、惡其類禾而別之也。小雅曰。不稂不莠。爾雅、毛傳皆曰。稂、童粱也。童粱卽童蓈。陸璣疏云。禾莠爲穗而不成。崱嶷然謂之童粱。今本莠作秀。誤。"}]},"𤓿":{"expl":"撮也。从𠬪从己。","rad":"𠬪","fq":"力輟切","vol":"04","py":"liè","duan":[{"e":"撮也。从𠬪。乙聲。","n":"鍇本如是。云乙者、甲乙之乙。鉉本作從𠬪從己。云己者物也。以音求之。佀小徐近是。力輟切。乙聲則當在十二部。"}]},"爭":{"expl":"引也。从𠬪、𠂆。","rad":"𠬪","fq":"側莖切","vol":"04","py":"zhēnɡ","duan":[{"e":"引也。","n":"凡言爭者、皆謂引之使歸於己。"}]},"𤔌":{"expl":"所依據也。从𠬪、工。讀與隱同。","rad":"𠬪","fq":"於謹切","vol":"04","py":"yǐn","duan":[{"e":"有所依也。","n":"依玄應本訂。依𤔌雙聲。又合韵冣近。此與𨸏部隱音同義近。隱行而𤔌廢矣。凡諸書言安隱者當作此。今俗作安穩。"}]},"寽":{"expl":"五指持也。从𠬪一聲。讀若律。","rad":"𠬪","fq":"呂戌切","vol":"04","py":"lǜ","duan":[{"e":"五𢫾寽也。","n":"各本寽作持。宋本、李燾本、類篇、集韵六術皆作捋。捋又寽之誤。今依集韵十三末作寽。按寽與捋各字。捋、毛曰取也。許曰取易也。寽、許曰五𢫾寽也。凡今俗用五𢫾持物引取之曰寽。廣韵曰。今寽禾是。是也。芣苡。薄言捋之。說者謂取其子。假令謂取其子。則當作寽。"}]},"𠭖":{"expl":"進取也。从𠬪古聲。","rad":"𠬪","fq":"古覽切","vol":"04","py":"ɡǎn","duan":[{"e":"進取也。从𠬪。","n":"猶从手也。"}]},"𣦼":{"expl":"殘穿也。从又从歺。凡𣦼之屬皆从𣦼 。讀若殘。","rad":"𣦼","fq":"昨干切","vol":"04","py":"cán","duan":[{"e":"殘穿也。","n":"殘穿者、殘賊穿之也。䜭字下曰。𣦵、殘也。亦胃殘穿。"}]},"㕡":{"expl":"溝也。从𣦼从谷。讀若郝。","rad":"𣦼","fq":"呼各切","vol":"04","py":"hè","duan":[{"e":"溝也。","n":"大司徒溝封。鄭曰。溝穿地爲阻固也。水部溝、水瀆。廣四尺。深四尺。此單舉匠人文耳。凡穿地爲水瀆皆稱溝。稱㕡。毛詩。實墉實壑。謂城池也。鄭伯有爲窟室飲酒。人謂之壑谷。"}]},"㕢":{"expl":"𣦼探堅意也。从𣦼从貝。貝，堅寶也。讀若概。","rad":"𣦼","fq":"古代切","vol":"04","py":"ɡài","duan":[{"e":"𥥍堅意也。","n":"各本深上有㕢𣦼字。宋本無㕢有𣦼。今按㕢係複舉。𣦼則衍文也。凡言意者、䛐下意內言外之意。其意爲深堅。其言云㕢也。"}]},"𠭘":{"expl":"坑也。从𣦼从井，井亦聲。","rad":"𣦼","fq":"疾正切","vol":"04","py":"jǐnɡ","duan":[{"e":"阬也。","n":"𨸏部曰。阬、閬也。釋詁曰。㕡阬虛也。𠭗與井部𨸥穽音同義異。𠭗謂穿地使空也。"}]},"叡":{"expl":"深明也。通也。从𣦼从目，从谷省。","rad":"𣦼","fq":"以芮切","vol":"04","py":"ruì","duan":[{"e":"𥥍明也。","n":"鉉本此下有通也二字。雖合古訓。然恐俗增。馬注尙書、鄭注尙書大傳皆曰。睿、通也。許則於叡曰深明也。於聖曰通也。叡從目、故曰明。聖從耳、故曰通。此許意也。周書謚法解曰。叡、聖也。邶風毛傳曰。聖、叡也。古文尙書睿作聖。故周書、毛傳叡聖互訓。楚語。謂之睿聖武公。韋曰。睿、明也。按韋但曰明、許曰深明者、許主解字。爲其字之從𣦼也。"}]},"莠":{"expl":"禾粟下生莠。从艸秀聲。讀若酉。","rad":"艸","fq":"与久切","vol":"01","py":"yǒu","duan":[{"e":"禾粟下揚生莠也。","n":"禾粟下猶言禾粟閒也。禾粟者、今之小米。莠、今之狗尾艸。莖葉𥝩皆似禾。故曰惡莠恐其亂苗。苗者、禾也。凡禾𥝩下垂。故淮南書謂之向根。張衡賦美其顧本。莠則𥝩同而揚起不下垂。故詩刺其驕驕桀桀。此君子小人之別也。七月傳曰。揚、條揚也。"}]},"歺":{"expl":"𠛱骨之殘也。从半冎。凡歺之屬皆从歺。讀若櫱岸之櫱。","rad":"歺","fq":"五割切","vol":"04","py":"è","duan":[{"e":"𠛱骨之殘也。","n":"刀部曰。𠛱、分解也。殘當作㱚。許殘訓賊。㱚訓餘。後人輒同之也。"}]},"𣨙":{"expl":"病也。从歺委聲。","rad":"歺","fq":"於爲切","vol":"04","py":"wěi","duan":[{"e":"病也。","n":"艸部曰。菸、一曰𣨙也。菸𣨙雙聲。廣韵曰。𣨙、枯死也。萎、蔫也。按𣨙萎古今字。菸蔫古今字。內則注曰。今益州有鹿𣨙。"}]},"㱪":{"expl":"瞀也。从歺昬聲。","rad":"歺","fq":"呼昆切","vol":"04","py":"hūn","duan":[{"e":"瞀也。","n":"瞀當作霿。雨部曰。霿、晦也。諸家霿瞀通用。子部㝅瞀亦作瞀字。莊子。以瓦注者巧。以鉤注者憚。以黃金注者殙。釋文引說文瞀也。左傳。札瘥夭殙。杜曰。未名而死曰殙。今傳作昏。"}]},"殰":{"expl":"胎敗也。从歺𧶠聲。","rad":"歺","fq":"徒谷切","vol":"04","py":"dú","duan":[{"e":"胎敗也。","n":"樂記。胎生者不殰。注曰。內敗曰殰。管子。羽卵者不段。毛胎者不𦢌。房曰。𦢌謂胎敗潰也。集韵曰。古作𦢌。"}]},"歾":{"expl":"終也。从歺勿聲。","rad":"歺","fq":"莫勃切","vol":"04","py":"mò","duan":[{"e":"終也。","n":"白起王翦列傳曰。偷合取容。以至歾身。徐廣云。歾音𣳚。按今歾譌圽。集韵傳會之云。圽、埋也。"}]},"𣨛":{"expl":"大夫死曰𣨛。从歺卒聲。","rad":"歺","fq":"子聿切","vol":"04","py":"zú","duan":[{"e":"大夫死曰𣨛。","n":"曲禮。天子死曰𡹔。諸矦曰薨。大夫曰卒。士曰不祿。庶人曰死。白虎通曰。大夫曰卒。精燿終也。卒之爲言終於國也。字皆作卒。於說文爲假借。"}]},"殊":{"expl":"死也。从歺朱聲。漢令曰：“蠻夷長有罪，當殊之。”","rad":"歺","fq":"市朱切","vol":"04","py":"shū","duan":[{"e":"死也。","n":"凡漢詔云殊死者、皆謂死罪也。死罪者首身分離。故曰殊死。引伸爲殊異。"}]},"殟":{"expl":"胎敗也。从歺𥁕聲。","rad":"歺","fq":"烏沒切","vol":"04","py":"wēn","duan":[{"e":"曓無知也。","n":"各本作胎敗也。誤同殰解。玄應書卷八、卷十三、十四皆引說文殟、暴無知也。聲類。烏殟、欲死也。今據正。廣韵云。病也。又云。心悶。其義正合。葢上下文皆說死之類。此亦謂暴死者。烏殟雙聲。玄應殟於門切。"}]},"殤":{"expl":"不成人也。人年十九至十六死，爲長殤；十五至十二死，爲中殤；十一至八歲死，爲下殤。从歺，傷省聲。","rad":"歺","fq":"式陽切","vol":"04","py":"shānɡ","duan":[{"e":"不成人也。","n":"不、喪服傳作未。"}]},"殂":{"expl":"往、死也。从歺且聲。《虞書》曰：“勛乃殂。”","rad":"歺","fq":"昨胡切","vol":"04","py":"cú","duan":[{"e":"往死也。","n":"殂之言䢐也。䢐、往也。故曰往死。玉篇曰。殂今作徂。"}]},"萉":{"expl":"枲實也。从艸肥聲。","rad":"艸","fq":"房未切","vol":"01","py":"fèi","duan":[{"e":"枲實也。","n":"枲、麻也。枲實、麻子也。釋艸作黂。周禮籩人、艸人作蕡。喪服傳云。苴絰、苴麻之有萉者也。按麻實名萉。因之麻亦名萉。艸人用蕡。說文林下云。萉之緫名。皆是。"}]},"殛":{"expl":"殊也。从歺亟聲。《虞書》曰：“殛鯀于羽山。”","rad":"歺","fq":"巳力切","vol":"04","py":"jí","duan":[{"e":"殊也。","n":"殊謂死也。廣韵曰。殊陟輸切。殊殺字也。從歹。歹五割切。㦵同殊。據此知古殊殺字作殊。與誅責字作誅迥別矣。周禮。八曰誅。以馭其過。禁殺戮。禁暴氏、野盧氏皆云誅之。此誅責也。公羊傳。君親無將。將而誅焉。此殊殺也。當各因文爲訓。"}]},"殪":{"expl":"死也。从歺壹聲。","rad":"歺","fq":"於計切","vol":"04","py":"yì","duan":[{"e":"死也。","n":"左傳。聲子射其馬。斬鞅。殪。將擊子車。子車射之。殪。小雅毛傳、文穎注上林賦皆曰。壹發而死爲殪。是也。故其字從壹。按尚書言殪戎殷。殪、仆也。此引伸之義。中庸言壹戎衣。注。衣讀爲殷。聲之誤也。壹戎殷者、壹用兵伐殷也。郭忠恕佩觿乃引鄭注云。壹當爲殪。此記憶之誤耳。凡恃記憶而不檢閲者多此病。"}]},"㱳":{"expl":"死𡧯㱳也。从歺莫聲。","rad":"歺","fq":"莫各切","vol":"04","py":"mò","duan":[{"e":"死𡧯㱳也。","n":"𡧯㱳猶𠴫嗼也。"}]},"殯":{"expl":"死在棺，將遷葬柩，賓遇之。从歺从賓，賓亦聲。夏后殯於阼階，殷人殯於兩楹之閒，周人殯於賓階。","rad":"歺","fq":"必刃切","vol":"04","py":"bìn","duan":[{"e":"死在棺。將遷葬柩。賔遇之。","n":"按士喪禮。主人奉尸由阼階鄉西階。斂於棺。棺先在肂中矣。所謂殯也、在西階。故檀弓曰。殯於客位。又曰。周人殯於西階之上。賔之也。釋名亦曰。於西壁下塗之曰殯。殯、賔也。賔客遇之。言稍遠也。此去葬期尚遠。非將葬賔遇之也。將葬而朝於祖。而設遷祖奠。而載柩於車。而祖。而設祖奠。而設葬奠。此不得名殯。淺人竄改之致此不通耳。當云屍在棺。肂於西階。賔遇之。"}]},"殔":{"expl":"瘗也。从歺隶聲。","rad":"歺","fq":"羊至切","vol":"04","py":"yì","duan":[{"e":"瘞也。","n":"土部曰。瘞、幽薶也。士喪禮掘肂注曰。肂、埋棺之坎也。棺在肂中斂屍焉。所謂殯也。肂者所以殯。故其字次於殯。可證上文將遷葬柩之誤。"}]},"殣":{"expl":"道中死人，人所覆也。从歺堇聲。《詩》曰：“行有死人，尚或殣之。”","rad":"歺","fq":"渠吝切","vol":"04","py":"jìn","duan":[{"e":"道中死人。人所覆也。","n":"今小雅小弁作墐。傳曰。墐、路冢也。按墐者假借字。殣者正字也。義在人所覆。故其字次於殔。左傳。道殣相望。杜云。餓死爲殣。"}]},"殠":{"expl":"腐气也。从歺臭聲。","rad":"歺","fq":"尺救切","vol":"04","py":"chòu","duan":[{"e":"腐气也。","n":"廣韵曰。腐臭也。按臭者氣也。兼芳殠言之。今字專用臭而殠廢矣。儀禮釋文引孟子飯殠茹菜。楊敞傳。冒頓單于得漢美食好物。謂之殠惡。楊王孫傳。其穿下不亂泉。上不泄殠。"}]},"殨":{"expl":"爛也。从歺貴聲。","rad":"歺","fq":"胡對切","vol":"04","py":"kuì","duan":[{"e":"爛也。","n":"今殨爛字作潰而殨廢矣。"}]},"㱙":{"expl":"腐也。从歺丂聲。","rad":"歺","fq":"許久切","vol":"04","py":"xiǔ","duan":[{"e":"腐也。","n":"肉部曰。腐、爛也。今字用朽而㱙廢矣。"}]},"殆":{"expl":"危也。从歺台聲。","rad":"歺","fq":"徒亥切","vol":"04","py":"dài","duan":[{"e":"危也。","n":"危者、在高而懼也。引伸之凡將然之䛐皆曰殆、曰危。與？天之未陰雨音義同。又豳風殆及公子同歸傳曰。殆、始也。此謂殆爲始之假借也。"}]},"芓":{"expl":"麻母也。从艸子聲。一曰芓卽枲也。","rad":"艸","fq":"疾吏切","vol":"01","py":"zì","duan":[{"e":"麻母也。","n":"見釋艸。今爾雅作茡。按釋艸云。黂、枲實。枲實猶言麻實耳。儀禮傳云。牡麻者枲麻也。然則枲無實。芓乃有實。統言則皆偁枲。析言則有實者偁芓、無實者偁枲。麻母言麻子之母。喪服所謂苴。斬衰皃若苴。齊衰皃若枲。苴麤於枲矣。詩九月叔苴。則又𧦝麻子爲苴。"}]},"殃":{"expl":"咎也。从歺央聲。","rad":"歺","fq":"於良切","vol":"04","py":"yānɡ","duan":[{"e":"凶也。","n":"各本作咎也。今依易釋文。"}]},"殘":{"expl":"賊也。从歺戔聲。","rad":"歺","fq":"昨干切","vol":"04","py":"cán","duan":[{"e":"賊也。","n":"戈部曰。賊敗也。？部殘穿也。今俗用爲㱚餘字。按許意殘訓賊。㱚訓餘今則殘專行而㱚廢矣。周禮稾人注。假戔爲㱚。"}]},"殄":{"expl":"盡也。从歺㐱聲。","rad":"歺","fq":"徒典切","vol":"04","py":"tiǎn","duan":[{"e":"盡也。","n":"釋詁、大雅瞻卬傳同。邶風。籧篨不殄。傳曰。殄絕也。此盡義之引伸也。箋云。殄當作腆。腆、善也。按古文假殄爲腆。儀禮注云腆古文作殄。是也。"}]},"殲":{"expl":"微盡也。从歺韱聲。《春秋傳》曰：“齊人殲于遂。”","rad":"歺","fq":"子廉切","vol":"04","py":"jiān","duan":[{"e":"微盡也。","n":"殲之言纖也。纖細而盡之也。"}]},"殫":{"expl":"殛盡也。从歺單聲。","rad":"歺","fq":"都寒切","vol":"04","py":"dān","duan":[{"e":"極盡也。","n":"竆極而盡之也。極鉉本作殛。誤。古多假單字爲之郊特牲云。社事單出里。祭義。歲旣單矣大雅。其軍三單。箋云。單者、無羨卒也。皆是也。"}]},"殬":{"expl":"敗也。从歺睪聲。《商書》曰：“彞倫攸殬。”","rad":"歺","fq":"當故切","vol":"04","py":"dù","duan":[{"e":"敗也。","n":"經假斁爲殬。雲漢鄭箋云。斁、敗也。孔穎達引洪範。彝倫攸斁。"}]},"㱻":{"expl":"畜産疫病也。从歺从羸。","rad":"歺","fq":"郎果切","vol":"04","py":"luò","duan":[]},"㱯":{"expl":"殺羊出其胎也。从歺豈聲。","rad":"歺","fq":"五來切","vol":"04","py":"ái","duan":[{"e":"殺羊出其胎也。","n":"此與刀部刏音同義異。云殺羊出其胎。則廣雅云㱯腜胎也、辭不達意矣。"}]},"𣧻":{"expl":"禽獸所食餘也。从歺从肉。","rad":"歺","fq":"昨干切","vol":"04","py":"cán","duan":[{"e":"禽獸所食餘也。","n":"引伸爲凡物之餘。凡殘餘字當作㱚。"}]},"殖":{"expl":"脂膏久殖也。从歺直聲。","rad":"歺","fq":"常職切","vol":"04","py":"zhí","duan":[{"e":"脂膏久殖也。","n":"久下當有曰字。國語舊音引說文殖、脂膏久也。考工記故書昵或作樴。注云。樴讀爲脂膏䐈敗之䐈。按䐈卽殖字。字林云。䐈、膏敗也。亦作膱。廣雅云。膱、臭也。玉篇、廣韵皆云。膱、油敗也。其字常職切。亦音職。今俗語謂膏油久不可用、正讀職之平聲也。脂膏以久而敗。財用以多藏而厚亡。故多積者謂之殖貨。引伸假借之義也。"}]},"䔬":{"expl":"芓也。从艸異聲。","rad":"艸","fq":"羊吏切","vol":"01","py":"yì","duan":[{"e":"芓也。从艸。異聲。","n":"羊吏切。一部。"}]},"㱠":{"expl":"枯也。从歺古聲。","rad":"歺","fq":"苦孤切","vol":"04","py":"kū","duan":[{"e":"枯也。","n":"周禮。殺王之親者辜之。注。辜之也枯也。謂磔之。桀部曰。磔、辜也。按㱠同辜。磔也。玉篇曰。？、古文辜字。"}]},"㱦":{"expl":"棄也。从歺奇聲。俗語謂死曰大㱦。","rad":"歺","fq":"去其切","vol":"04","py":"qī","duan":[{"e":"棄也。从𣦵。奇聲。","n":"去其切。按其誤。當依廣韵去奇切。古音在十七部。"}]},"死":{"expl":"澌也，人所離也。从歺从人。凡死之屬皆从死。","rad":"死","fq":"息姊切","vol":"04","py":"sǐ","duan":[{"e":"澌也。","n":"水部曰。澌、水索也。方言。澌、索也。盡也。是澌爲凡盡之偁。人盡曰死。死澌異部曡韵。"}]},"薨":{"expl":"公矦𣨛也。从死，瞢省聲。","rad":"死","fq":"呼肱切","vol":"04","py":"hōnɡ","duan":[{"e":"公矦𣨛也。","n":"曲禮曰。公矦曰薨。？部曰。大夫死曰？。此不曰公矦死而言公矦碎者、欲見分別則惟大夫偁碎。統言則不爾也。曲禮又曰壽考曰卒。短折曰不祿。此槪言之。非謂大夫士也。"}]},"薧":{"expl":"死人里也。从死，蒿省聲。","rad":"死","fq":"呼毛切","vol":"04","py":"hāo","duan":[{"e":"死人里也。","n":"樂府相和曲有薤露、蒿里之歌。譙周、崔豹皆云。起於田橫自殺。從者爲作悲歌。崔云。謂人命奄忽。如薤上之露易晞滅。亦謂人死䰟魄歸於蒿里。蒿里辭曰。蒿里誰家地。聚斂䰟魄無賢愚。然則蒿里者、謂虛墓之閒也。且其字作蒿。此獨云薧、死人里。則字作薧而義亦殊。葢有一里人盡死者、因目爲薧里。許所聞不同譙、崔也。按周禮。乾魚謂之薧。內則。蓳荁衯榆免薧。注。免、新生者。薧、乾也。然則凡死而枯槁謂之薧。不必如許所說。"}]},"𣣌":{"expl":"戰見血曰傷；亂或爲惽；死而復生爲𣣌。从死次聲。","rad":"死","fq":"咨四切","vol":"04","py":"zì","duan":[{"e":"戰。","n":"句。"}]},"冎":{"expl":"剔人肉置其骨也。象形。頭隆骨也。凡冎之屬皆从冎。","rad":"冎","fq":"古瓦切","vol":"04","py":"ɡuǎ","duan":[{"e":"剔人肉置其骨也。","n":"剔當作𩮜。解也。其周禮膊之、焚之、辜之之㓝與。列子曰。炎人之國。其親戚死。冎其肉而棄之。刀部無剔字。冎俗作剮。"}]},"𠛰":{"expl":"分解也。从冎从刀。","rad":"冎","fq":"憑列切","vol":"04","py":"bié","duan":[{"e":"分解也。","n":"分別、離別皆是也。今人分別則彼列切。離別則憑列切。古無是也。俗謂八部？爲古別字。且或於？部乖字下益曰？古文別。假令果尒。則於此何不載乎。"}]},"𠕩":{"expl":"別也。从冎卑聲。讀若罷。","rad":"冎","fq":"府移切","vol":"04","py":"bēi","duan":[{"e":"別也。从冎。卑聲。讀若罷。","n":"府移切。十六部。罷聲古音在十七部。合韵也。脾與𠂢？字音義相近。"}]},"骨":{"expl":"肉之覈也。从冎有肉。凡骨之屬皆从骨。","rad":"骨","fq":"古忽切","vol":"04","py":"ɡǔ","duan":[{"e":"肉之覈也。","n":"西部而。覈、實也。肉中骨曰覈。蔡邕注典引曰。肴覈、食也。肉曰肴。骨曰覈。周禮。丘陵、其植物宜覆物。注云。核物、梅李之屬。小雅。殽核維旅。箋云。豆實菹醢也。籩實有桃梅之屬。按覈核古今字。故周禮經文作覈注文作核。古本皆如是。詩殽核、蔡邕所據魯詩作肴覈。梅李謂之覈者、亦肉中有骨也。"}]},"蘇":{"expl":"桂荏也。从艸穌聲。","rad":"艸","fq":"素孤切","vol":"01","py":"sū","duan":[{"e":"桂荏也。","n":"桂上鍇本有蘇字。此複寫隷字𠜂之未盡者。蘇、桂荏。釋艸文。內則注曰。薌蘇、桂之屬也。方言曰。蘇亦荏也。關之東西或謂之蘇。或謂之荏。郭樸曰。蘇、荏類。是則析言之則蘇荏二物。統言則不別也。桂荏今之紫蘇。蘇之叚借爲樵蘇。"}]},"髑":{"expl":"髑髏，頂也。从骨蜀聲。","rad":"骨","fq":"徒谷切","vol":"04","py":"dú","duan":[{"e":"髑髏、","n":"逗。"}]},"髏":{"expl":"髑髏也。从骨婁聲。","rad":"骨","fq":"洛矦切","vol":"04","py":"lóu","duan":[{"e":"髑髏也。","n":"二字曡韵。"}]},"髆":{"expl":"肩甲也。从骨尃聲。","rad":"骨","fq":"補各切","vol":"04","py":"bó","duan":[{"e":"肩甲也。","n":"肉部曰。肩、髆也。單呼曰肩。絫呼曰肩甲。甲之言葢也。肩葢乎衆體也。今俗云肩甲者、古語也。釋名作肩甲。靈樞經作肩胛。水經注云。如人袒胛。故謂之赤胛山。胛者、甲之俗也。應劭漢書注曰。大宛天馬汗血。汗從前肩髆中出。如血。周禮醢人豚拍注云。或曰豚拍、肩也。然則假拍爲髆字。"}]},"髃":{"expl":"肩前也。从骨禺聲。","rad":"骨","fq":"午口切","vol":"04","py":"ǒu","duan":[{"e":"肩前也。","n":"士喪禮記。卽牀而奠。當腢。注曰。腢、肩頭也。腢卽髃字。毛詩傳曰。自左膘而䠶之達於右髃。爲上殺。膘、脅後髀前肉也。何注公羊云。自左膘䠶之達於右髃。中心死疾鮮絜也。髃本謂人。亦假爲獸骨之偁。凡肩後統於背前爲髃。髃之言隅也。如物之有隅也。"}]},"骿":{"expl":"并脅也。从骨并聲。晉文公骿脅。","rad":"骨","fq":"部田切","vol":"04","py":"pián","duan":[{"e":"骿脅、","n":"逗。"}]},"髀":{"expl":"股也。从骨卑聲。","rad":"骨","fq":"并弭切","vol":"04","py":"bǐ","duan":[{"e":"股外也。","n":"各本無外。今依爾雅音義、文𨕖七命注、玄應書、太平御覽補。股外曰髀。髀上曰髖。肉部曰股、髀也。渾言之。此曰髀、股外也。析言之。其義相足。大部曰奎、兩髀之閒也。"}]},"髁":{"expl":"髀骨也。从骨果聲。","rad":"骨","fq":"苦臥切","vol":"04","py":"kē","duan":[{"e":"髀骨也。","n":"髀骨猶言股骨也。醫經亦謂之股骨。沈氏彤釋骨云。腰䯊骨旁臨兩股者曰堅骨、曰大骨、曰髂。一身之伸屈司焉。故通曰機關。關之旁曰髀樞、亦曰樞機者、髀骨之入樞者也。在膝以上者曰髀骨、曰股骨。其直者曰楗。其斜上俠髖者則所謂機也。按髀之上曰髖卽俗所謂髂也。髁者、髀與髖相按之處。人之所以能立、能行、能有力者皆在於是。故醫經謂之機。骨空論曰俠髖曰機是也。醫經曰腰髁骨者、其字當作䯊。卽髂字。不當作髁。文𨕖注引埤蒼曰。髂、腰骨也。"}]},"𩪗":{"expl":"臀骨也。从骨厥聲。","rad":"骨","fq":"居月切","vol":"04","py":"jué","duan":[{"e":"𡱂骨也。","n":"廣雅曰。臎、？也。臎者、翠之俗。內則所謂舒鴈翠、舒鳧翠是也。吕覽。雋觾之翠。高注曰。翠、厥也。此假厥爲？也。醫經曰。尻骨曰脊骶、曰尾骶、曰尾屈、曰橛骨、曰竆骨。"}]},"髖":{"expl":"髀上也。从骨寬聲。","rad":"骨","fq":"苦官切","vol":"04","py":"kuān","duan":[{"e":"髀上也。","n":"髀上爲？之兩旁。故其字次於？。髖者、其骨冣寬大也。諸書所謂䯊骨。？髂皆同也。埤蒼作髂。字林作䯊。皆云𦝫骨。謂上屬於𦝫也。釋名云。樞機也。要髀股動搖如樞機也。正謂此髖與髀相接處。釋骨曰。骶之上俠脊十七節至二十節起骨曰腰髁骨。曰兩髁。按髁當作䯊。○骨空論云。輔骨上、橫骨下爲楗。注。膝輔骨上、腰髖骨下爲楗。按橫骨卽髖。橫之言廣也。楗卽髀骨之直者。機卽髀骨與髖相構處也。"}]},"髕":{"expl":"厀耑也。从骨賓聲。","rad":"骨","fq":"毗忍切","vol":"04","py":"bìn","duan":[{"e":"厀耑也。","n":"厀、脛頭節也。釋骨云。葢膝之骨曰膝髕。大戴禮曰。人生朞而髕。髕不備則人不能行。古者五㓝臏、宫、劓、墨、死。臏者、髕之俗。去厀頭骨也。周改髕作跀。其字借作刖。𣃔足也。漢之斬趾是也。髕者癈不能行。跀者尚可箸踊而行。踊者、跀足者之屨。莊子。兀者叔山無趾。踵見仲尼。崔譔云。無趾故以踵行。是則跀輕於髕也。古文尚書吕㓝說夏㓝作剕。周本紀、漢㓝法志、周禮司㓝注引尚書大傳皆作髕。周禮注云。周改臏作刖。而公羊疏引鄭駁異義云。臯陶改臏爲剕。吕㓝有剕。周改剕爲刖。與周禮注不合。足部云。䠊、跀也。䠊卽剕字。許謂䠊卽跀矣。鄭析䠊跀爲二。不知其制何以分別。竊謂周禮注爲長。駁異義則未定之論。許說亦非是也。剕惟見於吕㓝。他經"}]},"荏":{"expl":"桂荏，蘇。从艸任聲。","rad":"艸","fq":"如甚切","vol":"01","py":"rěn","duan":[{"e":"桂荏、","n":"逗。"}]},"䯏":{"expl":"骨耑也。从骨𠯑聲。","rad":"骨","fq":"古𣴠切","vol":"04","py":"ɡuā","duan":[{"e":"骨耑也。","n":"骨當是骸之誤。骨空論云。膝解爲骸關。是也。關䯏雙聲。䯏取機括之意。"}]},"䯣":{"expl":"厀脛間骨也。从骨䝿聲。","rad":"骨","fq":"丘媿切","vol":"04","py":"kuì","duan":[{"e":"厀脛閒骨也。","n":"骨空論云。骸下爲輔。輔上爲膕。膕上爲關。是也。膝解爲骸關。言外也。膕上爲關。言內也。"}]},"骹":{"expl":"脛也。从骨交聲。","rad":"骨","fq":"口交切","vol":"04","py":"qiāo","duan":[{"e":"脛也。","n":"脛、厀下也。凡物之脛皆曰骹、釋嘼。馬四骹皆白驓。薛注西京曰。靑骹、鷹靑脛者。方言曰。矛骹細如鶴脛者、謂之鶴膝。考工記說輻材曰。參分其股圍。去一以爲骹圍。大鄭云。方言股以喻其豐。故言骹以喻其細。禮多假校爲之。士喪禮記。綴足用燕几。校在南。注。校、脛也。祭統。夫人薦豆執校。注。校、豆中央直者也。此皆假校爲骹也。"}]},"骭":{"expl":"骹也。从骨干聲。","rad":"骨","fq":"古案切","vol":"04","py":"ɡàn","duan":[{"e":"骹也。","n":"吕覽注引孟子。拔骭一毛而利天下。甯戚歌。短布單衣適至骭。按骭之言榦也。榦者、本也。人體之阯也。脅骨何以亦名榦也。曰脅榦見於左傳楄柎藉榦公羊拹公榦而殺之。古榦翰通用。毛詩翰字多爲榦之假借。脅榦乃翰之假借。脅肋如鳥之羽翰分布也。"}]},"骸":{"expl":"脛骨也。从骨亥聲。","rad":"骨","fq":"戶皆切","vol":"04","py":"hái","duan":[{"e":"脛骨也。","n":"上文言脛也、骹也。不言骨者。骹骭皆目其表也。骨空論曰。膝解爲骸關。俠膝之骨爲連骸。然則正謂脛骨爲骸矣。下文云。連骸下爲輔。輔卽骸也。膝解爲其關。俠膝之骨連之也。字從亥者。亥、荄也。荄、根也。公羊傳注。骸、人骨也。則引伸爲凡人骨之偁。"}]},"𩪦":{"expl":"骨中脂也。从骨隓聲。","rad":"骨","fq":"息委切","vol":"04","py":"suǐ","duan":[{"e":"骨中脂也。从骨。隓聲。","n":"息委切。古音在十七部。𣜩作髓。"}]},"䯜":{"expl":"骨間黃汁也。从骨易聲。讀若《易》曰“夕惕若厲”。","rad":"骨","fq":"他歴切","vol":"04","py":"tì","duan":[{"e":"骨閒黃汁也。从骨。易聲。讀若易曰夕惕若厲。","n":"讀若二字小徐無。非也。汗𥳑、古文四聲韵皆云。䯜出古周易。正因說文奪讀若字。遂徑作夕䯜也。夕惕若厲又見夕部及他古籍。易惟費氏以古字號古文易。鄭君傳費氏。亦云惕、懼也。且易惕字屢見。倘古文皆作䯜。諸家必有爲之說者、而未見也。他歷切。十六部。"}]},"體":{"expl":"緫十二屬也。从骨豊聲。","rad":"骨","fq":"他禮切","vol":"04","py":"tǐ","duan":[{"e":"緫十二屬也。","n":"十二屬許未詳言。今以人體及許書覈之。首之屬有三。曰頂、曰面、曰頤。身之屬三。曰肩、曰脊、曰？。手之屬三。曰厷、曰臂、曰手。足之屬三。曰股、曰脛、曰足。合說文全書求之。以十二者統之。皆此十二者所分屬也。"}]},"髍":{"expl":"㾫病也。从骨麻聲。","rad":"骨","fq":"莫鄱切","vol":"04","py":"mó","duan":[{"e":"㾫病也。","n":"？部曰。㾫、半枯也。漢書敘傳曰。又况幺䯢不及數子。鄭氏曰。䯢音麼。小也。晉灼曰。此骨偏䯢之䯢也。按二說皆是。本骨偏䯢字借爲幺麼。是以文𨕖作幺麼。且偏䯢是不全之病。不全則不大。故引伸爲不長曰幺、細小曰麼之義。許書無麼字。葢以髍包之。不得以髍平麼上爲疑也。"}]},"骾":{"expl":"食骨畱咽中也。从骨㪅聲。","rad":"骨","fq":"古杏切","vol":"04","py":"ɡěnɡ","duan":[{"e":"食骨畱咽中也。","n":"晉語。⺊籒曰。狹以銜骨。韋曰。骨所以鯁刺人也。忠言逆耳。如食骨在喉。故云骨骾之臣。漢書巳下皆作骨鯁。字從魚。謂畱咽者魚骨挍多也。依說文則鯁訓魚骨。骨畱咽中當作骾。按自髑至體皆言人骨。體者、緫上文言之也。髍者、人骨之病也。骼骴二文、則禽獸之骨。骾者、人哽於物。骨主謂人。故其字非人骨而從骨。其次則必先於駱骴也。"}]},"䒨":{"expl":"菜也。从艸矢聲。","rad":"艸","fq":"失匕切","vol":"01","py":"shǐ","duan":[{"e":"菜也。从艸。矢聲。","n":"失匕切。十五部。"}]},"骼":{"expl":"禽獸之骨曰骼。从骨各聲。","rad":"骨","fq":"古覈切","vol":"04","py":"ɡé","duan":[{"e":"禽獸之骨曰骼。","n":"按骨當作髖。許據禮十七篇。故云禽獸之髖曰骼也。禽者走獸緫名。儀禮多言肫骼。肫亦作膞。皆說文之腨字也。骼亦作胳。於人曰髖也。髖者、髀上也。牲前足體三。曰肩、曰臑、曰臂。臑於人爲厷。肩下臂上也。後足體三。曰骼、曰髀、曰腨。禮髀賤不升。故經多言肩臂臑膞骼。臑在臂上。骼在肫上。而先言臂肫者、葢四胑以下爲貴也。骼是本字。至埤蒼乃作髂。廣雅、字林變作䯊。又或作？。魚虞歌麻通轉之故也。云曰骼曰骴者、所以別人禽之異名。肉部曰。臂、羊豕曰臑。是其例也。許據十七篇爲言。故不敢謂骼爲人骨也。月令。孟春掩骼薶骴。鄭云。骨枯曰骼。肉腐曰骴。蔡云。露骨曰骼。有肉曰骴高注吕覽云。白骨曰骼。有肉曰髊。注淮南同。皆不言骼骴爲禽"}]},"骴":{"expl":"鳥獸殘骨曰骴。骴，可惡也。从骨此聲。《明堂月令》曰：“掩骼薶骴。”骴或从肉。","rad":"骨","fq":"資四切","vol":"04","py":"cī","duan":[{"e":"鳥獸殘骨曰骴。","n":"殘同㱚餘也。鳥獸廣韵作鳥鼠。曲禮曰。四足曰漬。注。漬謂相瀸污而死也。小雅。助我舉柴。手部引作㧘。毛、許皆云㧘、積也。鄭箋。雖不中。必助中者舉積禽。二經漬㧘字音義皆同骴。故許知骴不謂人骨也。周禮。蜡氏掌除骴。故書骴作脊。先鄭云。脊讀爲㱴。謂死人骨也。月令。掩骼埋胔。骨之尚有肉者也。乃禽獸之骨皆是。此先鄭兼人與禽獸言之。而公羊傳。大災者何。大瘠也。大瘠者何。㾐也。漢食貨志。國亡捐瘠。孟康曰。肉腐爲瘠。捐骨不薶者。公羊、漢志瘠卽骴字。合之鄭注月令肉腐曰骴。蔡氏、高氏云有肉曰骴。又皆指人言之。說雖不同。皆關王政仁民愛物之意。其字正作骴。假借作漬、作㧘、作瘠、作脊。皆同音假借也。漬又作㱴。"}]},"骫":{"expl":"骨耑骫奊也。从骨丸聲。","rad":"骨","fq":"於詭切","vol":"04","py":"wěi","duan":[{"e":"骨耑骫奊也。","n":"夨部奊下曰。頭衺骫奊態也。招隱士曰。林木茷骫。王注。枝條盤？也。枚皋傳。其文骫骳。曲隨其事。皆得其意。師古曰。骫骳猶言屈曲也。然則骫奊者、謂屈曲之狀。骫字廁於此者、統人及禽獸之骨言。"}]},"䯤":{"expl":"骨擿之可會髮者。从骨會聲。《詩》曰：“䯤弁如星。”","rad":"骨","fq":"古外切","vol":"04","py":"kuài","duan":[{"e":"骨擿之可會髮者。","n":"䯤㑹曡韵。鄘風。象之揥也。毛曰。揥所以摘髮。摘本又作擿。䯤所以㑹髮、與揥所以擿髮訓釋正同。䯤與揥一物而少異。釋名曰。揥、摘也。所以摘髮也。導所以導擽𩯭髮、使入巾幘之裏也。或曰擽𩯭以事名之也。然則揥一名擿。鄘風所云也。導一名撩𩯭。漢魏巳後多云玉導、簪導。今人之抿簪。詩、禮之䯤也。周禮弁師。㑹五采玉琪。注曰。故書㑹作䯤。先鄭云。讀如馬㑹之㑹。謂以五采束髮也。士喪禮。檜用組。乃筓。檜讀與䯤同。書之異耳。說曰。以組束髮。乃箸筓。謂之檜。沛國人謂反紒爲䯤。按先鄭說云爾者、葢由㑹髮之器謂之䯤。因之束髮謂之䯤。與儀禮之檜同。今士喪禮字作鬠。注云。古文鬠皆爲括。骨擿猶象揥也。必云骨者、爲其字從骨。䯤者、獸骨之"}]},"肉":{"expl":"胾肉。象形。凡肉之屬皆从肉。","rad":"肉","fq":"如六切","vol":"04","py":"ròu","duan":[{"e":"胾肉。","n":"下文曰。胾、大臠也。謂鳥獸之肉。說文之例。先人後物。何以先言肉也。曰以爲部首。不得不首言之也。生民之初。食鳥獸之肉。故肉字冣古。而製人體之字。用肉爲偏旁。是亦假借也。人曰肌。鳥獸曰肉。此其分別也。引伸爲爾雅肉好、樂記廉肉字。"}]},"腜":{"expl":"婦始孕腜兆也。从肉某聲。","rad":"肉","fq":"莫桮切","vol":"04","py":"méi","duan":[{"e":"婦孕始兆也。","n":"依廣韵訂。韓詩曰。周原腜腜。又曰。民雖靡腜。毛詩皆作膴。腜腜、美也。廣雅曰。腜腜、肥也。此引伸之義也。"}]},"肧":{"expl":"婦孕一月也。从肉不聲。","rad":"肉","fq":"匹桮切","vol":"04","py":"pēi","duan":[{"e":"婦孕一月也。","n":"文子曰。一月而膏。二月血脈。三月而肧。四月而胎。五月而筋。六月而骨。七月而成形。八月而動。九月而躁。十月而生。淮南曰。一月而膏。二月而胅。三月而胎。說各乖異。其大致一也。李善注江賦。引淮南三月而肧胎。與今本異。"}]},"胎":{"expl":"婦孕三月也。从肉台聲。","rad":"肉","fq":"土來切","vol":"04","py":"tāi","duan":[{"e":"婦孕三月也。","n":"玄應兩引皆作二月。釋詁曰。胎、始也。此引伸之義。方言曰。胎、養也。此假借胎爲頤養也。又曰。胎逃也。則方俗語言也。"}]},"肌":{"expl":"肉也。从肉几聲。","rad":"肉","fq":"居夷切","vol":"04","py":"jī","duan":[{"e":"肉也。从肉。几聲。","n":"居夷切。十五部。"}]},"臚":{"expl":"皮也。从肉盧聲。","rad":"肉","fq":"力居切","vol":"04","py":"lú","duan":[{"e":"皮也。","n":"今字皮膚從籒文作膚。膚行而臚廢矣。晉語。聽臚言於市。史、漢臚句傳。蘇林曰。上傳語吿下爲臚。此皆讀爲敷奏以言之敷也。史記。臚於郊祀。漢書。大夫臚岱。韋昭辨釋名。鴻、大也。臚、陳序也。謂大以禮陳序賔客。此皆讀爲廷實旅百之旅也。劉熙釋名。鴻臚。腹前肥者曰臚。以京師爲心體。王矦外國爲腹腴。以養之也。此讀爲夏右腴之腴。皆假借也。其本義則皮膚也。"}]},"䔇":{"expl":"菜之美者。雲夢之䔇。从艸豈聲。","rad":"艸","fq":"驅喜切","vol":"01","py":"qǐ","duan":[{"e":"菜之美者、雲夢之䔇。","n":"呂氏春秋。伊尹對湯曰。菜之美者、雲夢之芹。高注。雲夢、楚澤。芹生水涯。許作䔇。葢殷微二韵轉移冣近。許君采自伊尹書。與呂覽字異。音義則同。廣韵曰。䔇菜似蕨。生水中。說者謂豐水有芑卽此。"}]},"肫":{"expl":"面頯也。从肉屯聲。","rad":"肉","fq":"章倫切","vol":"04","py":"zhūn","duan":[{"e":"面頯也。","n":"頁部曰。頯、權也。權俗作顴。肫、史漢作準。高祖隆準。服虔曰。準音拙。應劭曰。隆、高也。準頰權準也。按準者假借字。肫其正字。儀禮釋文引說文肫、之允反。是也。其入聲則音拙。廣雅作䪼。是也。若戰國策準頞、權衡竝言則準訓鼻矣。儀禮。牲體肫骼。假借肫爲腨字也。腨者、腓腸也。又中庸。肫肫其仁。鄭讀爲誨爾忳忳之忳。忳忳、懇誠皃也。是亦假借也。士昏禮。腊一肫。肫者純之假借。純、全也。"}]},"𦠄":{"expl":"頰肉也。从肉幾聲。讀若畿。","rad":"肉","fq":"居衣切","vol":"04","py":"jī","duan":[{"e":"頰肉也。","n":"東方朔傳曰。樹頰胲。師古曰。胲、頰肉。音改。按集韵十五海曰。頰下曰䪱。或作胲、𦠄。廣韵十五海曰。頦、頰頦也。頦爲頰肉。與𦠄異部而同義。或作䪱。或假借胲字。"}]},"脣":{"expl":"口耑也。从肉辰聲。","rad":"肉","fq":"食倫切","vol":"04","py":"chún","duan":[{"e":"口耑也。","n":"口之厓也。假借爲水厓之字。鄭注乾鑿度引詩寘之河之脣。"}]},"脰":{"expl":"項也。从肉豆聲。","rad":"肉","fq":"徒候切","vol":"04","py":"dòu","duan":[{"e":"項也。","n":"頁部曰。項、頭後也。按頭後卽頸後也。左傳曰。兩矢夾脰。公羊傳曰。宋萬搏閔公。絕其脰。注。脰、頸也。齊人語。士虞禮。膚祭三。取諸左膉上。注。膉、脰肉也。古文曰左股上。此字從肉。非從殳矛之殳聲。鄭意謂股者髀也。禮經多言髀不升。則取諸左股爲膚祭。非也。尋古文用字之例。假股爲膉正與假脾爲髀、假肫膞爲腨、假胳爲骼、假頭爲脰皆以異物同音相假借。股與膉當是同音。葢從肉役省聲。如坄疫豛皆從役省聲之比。役與益同部。此股非股肱字。注當云此字從肉從役省聲。非從殳矛之殳聲。今本脫誤不完。據賈疏云。鄭以殳與股不是形聲之類。其理未審。賈實錯解。而可證有非字。今本又奪非字。則更不可通矣。"}]},"肓":{"expl":"心上鬲下也。从肉亡聲。《春秋傳》曰：“病在肓之下。”","rad":"肉","fq":"呼光切","vol":"04","py":"huānɡ","duan":[{"e":"心下鬲上也。","n":"下上各本互譌。篇、韵同。今依左傳音義正。左傳。疾不可爲也。在肓之上。膏之下。賈逵、杜預皆曰。肓、鬲也。心下爲膏。按鄭駁異義云。肺也、心也、肝也俱在鬲上。賈侍中說肓、鬲也。統言之。許云鬲上爲肓者、析言之。鬲上肓。肓上膏。膏上心。今本作心上鬲下則不可通矣。素問曰。肓之原在䐡下。釋名曰。膈、塞也。塞上下、使氣與榖不相亂也。"}]},"腎":{"expl":"水藏也。从肉臤聲。","rad":"肉","fq":"時忍切","vol":"04","py":"shèn","duan":[{"e":"水臧也。","n":"今尚書、古尚書說同。"}]},"肺":{"expl":"金藏也。从肉巿聲。","rad":"肉","fq":"芳吠切","vol":"04","py":"fèi","duan":[{"e":"金臧也。","n":"按各本不完。當云火藏也、博士說以爲金藏。下文脾下當云木藏也、博士說以爲土藏。肝下當云金藏也、博士說以爲木藏。乃與心字下土藏也、博士說以爲火藏一例。玄應書兩引說文肺、火藏也。其所據當是完本。但未引一曰金藏耳。五經異義云。今尚書歐陽說。肝、木也。心、火也。脾、土也。肺、金也。腎、水也。古尚書說。脾、木也。肺、火也。心、土也。肝、金也。腎、水也。許愼謹案。月令。春祭脾。夏祭肺。季夏祭心。秋祭肝。冬祭腎。與古尚書同。鄭駁之曰。月令祭四時之位。乃其五藏之上下次之耳。冬位在後。而腎在下。夏位在前。而肺在上。春位小前。故祭先脾。秋位小卻。故祭先肝。腎也、脾也俱在鬲下。肺也、心也、肝也俱在鬲上。祭者必三。故有"}]},"脾":{"expl":"土藏也。从肉卑聲。","rad":"肉","fq":"符支切","vol":"04","py":"pí","duan":[{"e":"土藏也。","n":"文有脫誤。說見上。"}]},"肝":{"expl":"木藏也。从肉干聲。","rad":"肉","fq":"古寒切","vol":"04","py":"ɡān","duan":[{"e":"木藏也。","n":"文有脫誤。說見上。"}]},"膽":{"expl":"連肝之府。从肉詹聲。","rad":"肉","fq":"都敢切","vol":"04","py":"dǎn","duan":[{"e":"連肝之府也。","n":"白虎通曰。府者、爲藏官府也。膽者、肝之府也、肝主仁。仁者不忍。故以膽𣃔。仁者必有勇也。素問曰。膽者、中正之官。決𣃔出焉。"}]},"祇":{"expl":"地祇，提出萬物者也。从示氏聲。","rad":"示","fq":"巨支切","vol":"01","py":"qí","duan":[{"e":"地祇提出萬物者也。","n":"地祇提三字同在古音第十六部。地本在十七部。而多轉入十六部用。"}]},"葵":{"expl":"菜也。从艸癸聲。","rad":"艸","fq":"彊惟切","vol":"01","py":"kuí","duan":[{"e":"菜也。","n":"崔寔曰。六月六日可種葵。中伏後可種冬葵。九月可作葵葅乾葵。齊民要術有種葵法、種冬葵法。"}]},"胃":{"expl":"穀府也。从肉；纻，象形。","rad":"肉","fq":"云貴切","vol":"04","py":"wèi","duan":[{"e":"榖府也。","n":"白虎通曰。胃者、脾之府也。脾主稟氣。胃者、榖之委也。故脾稟氣於胃也。素問。脾胃者、倉廩之官。五味出焉。"}]},"脬":{"expl":"𦜶光也。从肉孚聲。","rad":"肉","fq":"匹交切","vol":"04","py":"pāo","duan":[{"e":"旁光也。","n":"各本作膀。非。兩膀謂脅也。今正。白虎通曰。旁光者、肺之府也。肺者、𣃔決膽。旁光亦常張有勢。故先決難也。素問曰。旁光者、州都之官。津液藏焉。按此所引白虎通本小徐。與御覽所引元命苞合。脬俗作胞。旁光俗皆從肉。"}]},"腸":{"expl":"大小腸也。从肉昜聲。","rad":"肉","fq":"直良切","vol":"04","py":"chánɡ","duan":[{"e":"大小腸也。","n":"白虎通曰。大腸小腸、心之府也。心者、主禮。禮者、有分理。腸之大小相承受也。腸爲胃紀。胃爲脾府。心爲支體主。故有兩府。素問曰。大腸者、傳道之官。變化出焉。小腸者、受盛之官。化物出焉。按所引白虎通從顏氏急就篇注所引也。藏府古通偁。如周禮注五藏倂胃、旁光、大腸、小腸爲九藏是也。"}]},"膏":{"expl":"𦘺也。从肉高聲。","rad":"肉","fq":"古勞切","vol":"04","py":"ɡāo","duan":[{"e":"肥也。","n":"按肥當作脂。脂字不廁於此者、許嚴人物之別。自胙篆巳下乃謂人所食者。膏謂人脂。在人者可假以名物。如無角者膏是也。脂專謂物。在物者不得假以名人也。"}]},"肪":{"expl":"𦘺也。从肉方聲。","rad":"肉","fq":"甫良切","vol":"04","py":"fánɡ","duan":[{"e":"肥也。","n":"肥亦當作脂。王逸正部論說玉符曰。白如豬肪。通俗文曰。脂在腰曰肪。此假在人者以名物也。"}]},"钋":{"expl":"胷也。从肉𤸰聲。","rad":"肉","fq":"於陵切","vol":"04","py":"yīnɡ","duan":[{"e":"匈也。","n":"勹部曰。匈、膺也。魯頌。戎狄是膺。釋詁、毛傳曰。膺、當也。此引伸之義。凡當事以膺。任事以肩。"}]},"肊":{"expl":"胷骨也。从肉乙聲。","rad":"肉","fq":"於力切","vol":"04","py":"yì","duan":[{"e":"匈骨也。","n":"宋本、李燾本皆作骨。俗本作肉。非也。此如脅爲兩膀、榦爲脅骨。正名百物。不可紊也。"}]},"背":{"expl":"𦟝也。从肉北聲。","rad":"肉","fq":"補妹切","vol":"04","py":"bèi","duan":[{"e":"脊也。","n":"？部曰。脊、背吕也。然則脊者、背之一端。背不止於脊。如髀者股外、股不止於髀也。云背脊也、股髀也。文法正同。周易。艮其背。不獲其身。"}]},"脅":{"expl":"兩𦜶也。从肉劦聲。","rad":"肉","fq":"虚業切","vol":"04","py":"xié","duan":[{"e":"兩膀也。","n":"廣雅曰。膀胠胉脅也。按許無胉字。胠下云亦下者、析言之。不與廣雅同也。膀言其前。胠言旁迫於肱者。又按周禮豚脅謂之豚拍。儀禮牲體脅謂之兩胉。注曰。今文胉爲迫。許此部前後皆無胉字。是則鄭從古文胉。許從今文迫也。膀亦假旁爲之。考工記旁鳴、蜩屬是。"}]},"膀":{"expl":"脅也。从肉㫄聲。","rad":"肉","fq":"步光切","vol":"04","py":"pánɡ","duan":[{"e":"脅也。从肉。旁聲。","n":"步光切。十部。"}]},"䕬":{"expl":"禦溼之菜也。从艸彊聲。","rad":"艸","fq":"居良切","vol":"01","py":"jiānɡ","duan":[{"e":"御溼之菜也。","n":"御、鉉作禦。神農本艸經曰。乾薑主逐風溼痹、溼病也腸澼、匹辟切腸閒水下痢。生者尢良。久服去臭氣、通神明。按生者尢良、謂乾薑中之不孰而生者耳。今人謂不乾者爲生薑。失之矣。"}]},"脟":{"expl":"脅肉也。从肉寽聲。一曰脟，腸閒𦘺也。一曰膫也。","rad":"肉","fq":"力輟切","vol":"04","py":"liè","duan":[{"e":"脅肉也。","n":"脅者統言之。脟其肉也。肋其骨也。子虛賦。脟割輪焠。假脟爲臠也。九歎說流水。龍卭脟圏。繚戾宛轉。脟一作綸。"}]},"肋":{"expl":"脅骨也。从肉力聲。","rad":"肉","fq":"盧則切","vol":"04","py":"lèi","duan":[{"e":"脅骨也。","n":"亦謂之榦。榦者、翰也。如羽翰然也。"}]},"胂":{"expl":"夾𦟝肉也。从肉申聲。","rad":"肉","fq":"矢人切","vol":"04","py":"shēn","duan":[{"e":"夾脊肉也。","n":"易艮九三。艮其限。裂其夤。馬云。夤、夾脊肉也。虞亦云。夤、脊肉。王弼云。當中脊之肉也。按夕部。夤、敬惕也。周易假爲胂。故三家注云爾。若鄭本作𦟘。𦟘恐夤之誤。廣雅云。胂謂之脢。周易音義云胂以人反。則胂音同夤。○又按艮九三字、當是上肉下寅。故鄭本作𦟘。非叚夤敬字也。"}]},"脢":{"expl":"背肉也。从肉𣫭聲。《易》曰：“咸其脢。”","rad":"肉","fq":"莫桮切","vol":"04","py":"méi","duan":[{"e":"背肉也。","n":"咸九五。咸其脢。子夏易傳云。在脊曰脢。馬云。脢、背也。鄭云。脢、背脊肉也。虞云。夾脊肉也。按諸家之言。不若許分析憭然。胂爲迫吕之肉。脢爲全背之肉也。釋文云。說文同鄭作背脊肉。未知其審。內則注。脄、脊側肉也。脄卽脢字。"}]},"𦙪":{"expl":"髆也。从肉，象形。","rad":"肉","fq":"古賢切","vol":"04","py":"jiān","duan":[{"e":"髆也。","n":"骨部曰。髆、肩甲也。"}]},"胳":{"expl":"亦下也。从肉各聲。","rad":"肉","fq":"古洛切","vol":"04","py":"ɡē","duan":[{"e":"亦下也。","n":"亦腋古今字。亦部曰。人之臂亦也。兩厷迫於身者謂之亦。亦下謂之胳。又謂之胠。身之迫於兩厷者也。深衣曰。胳之高下。可以運肘。注。肘不能不出入。胳、衣袂當腋之縫也。按衣袂當胳之縫亦謂之胳。俗作袼。禮經牲體之胳。今文作胳。古文作骼。鄭出古文於注。是注從今文也。許訓胳爲亦下。訓骼爲禽獸之骨。是從古文禮。不同鄭也。"}]},"胠":{"expl":"亦下也。从肉去聲。","rad":"肉","fq":"去劫切","vol":"04","py":"qū","duan":[{"e":"亦下也。","n":"玉藻說袂二尺二寸。袪尺二寸。袪、袂末也。袪與胠同音。然則胳謂迫於厷者。胠謂迫於臂者。左傳襄廿三年。齊矦伐衞。有先驅、申驅、戎車、貳廣、啟胠、大殿。賈逵曰。左翼曰啟。右翼曰胠。啟胠皆在旁之軍。莊子胠篋。司馬曰。從旁開爲胠。皆取義於人體也。廣雅。胠、脅也。未若許說之明析。"}]},"臂":{"expl":"手上也。从肉辟聲。","rad":"肉","fq":"卑義切","vol":"04","py":"bì","duan":[{"e":"手上也。","n":"又部曰。厷、臂上也。此皆析言之。亦下云人之臂亦。渾言之也。渾言則厷臂互偁。"}]},"臑":{"expl":"臂羊矢也。从肉需聲。讀若襦。","rad":"肉","fq":"那到切","vol":"04","py":"nào","duan":[{"e":"臂。","n":"句。"}]},"肘":{"expl":"臂節也。从肉从寸。寸，手寸口也。","rad":"肉","fq":"陟柳切","vol":"04","py":"zhǒu","duan":[{"e":"臂節也。","n":"厷與臂之節曰肘。股與脛之節曰厀。卪部曰。厀、脛頭卪也。其文法同也。肘、今江蘇俗語曰手臂掙注是也。深衣曰。胳之高下。可以運肘。袂之長短。反詘之及肘。注云。肘當臂中爲節。臂骨上下各尺二寸。按上謂厷。下謂臂也。"}]},"蓼":{"expl":"辛菜，薔虞也。从艸翏聲。","rad":"艸","fq":"盧鳥切","vol":"01","py":"liǎo","duan":[{"e":"辛菜。","n":"句。"}]},"𪗇":{"expl":"𦚚𪗇也。从肉齊聲。","rad":"肉","fq":"徂兮切","vol":"04","py":"qí","duan":[{"e":"𣬈𪗇也。","n":"各本𣬈作肶。誤。𦥓部曰。𣬈臍、人臍也。凡居中曰臍。釋言、馬注吕㓝皆云。齊、中也。釋地。中州曰齊州。列子中國曰齊國。莊、列與齊俱入。與汩偕出。司馬云。齊、回水如磨齊也。皆臍字引伸假借之義。左傳噬齊字衹作齊。"}]},"腹":{"expl":"厚也。从肉复聲。","rad":"肉","fq":"方六切","vol":"04","py":"fù","duan":[{"e":"厚也。","n":"腹厚曡韵。此與髮拔也、尾微也一例。謂腹之取名。以其厚大。釋名曰。腹、複也。富也。文法同。釋詁、毛傳皆云。腹、厚也。則是引伸之義。謂凡厚者皆可偁腹。如小雅出入腹我、月令水澤腹堅是也。"}]},"腴":{"expl":"腹下𦘺也。从肉臾聲。","rad":"肉","fq":"羊朱切","vol":"04","py":"yú","duan":[{"e":"腹下肥者。","n":"者各本作也。今依文𨕖注。此主謂人。論衡。傳語曰。堯若腊、舜若腒、桀紂之君垂腴尺餘是也。若少儀。羞濡魚者進尾。冬右腴。七發。犓牛之腴。假人之偁偁之也。"}]},"脽":{"expl":"𡱂也。从肉隹聲。","rad":"肉","fq":"示隹切","vol":"04","py":"shuí","duan":[{"e":"𡱂也。","n":"𡱂鍇作尻。非也。東方朔傳曰。臣觀其臿齒牙。樹頰胲。吐脣吻。擢頷頤。結股腳。連脽尻。每句二字皆相爲屬別。師古曰。脽、臀也。本說文也。渾言則𡱂尻爲一。尸部曰。尻、𦞠也。朔傳曰尻益高是也。析言則𡱂統之。尻乃近穢處。今北方俗云溝子是也。連脽尻者、斂足而立之狀。漢武帝紀。立后土祠於汾陰脽上。如淳曰。脽者、河之東岸特堆。魏土地記云。河東郡北八十里有汾陰城。北去汾水三里。城西北隅曰脽丘。詳邑部鄈下。"}]},"䏐":{"expl":"孔也。从肉，決省聲。讀若決水之決。","rad":"肉","fq":"古穴切","vol":"04","py":"jué","duan":[{"e":"孔也。","n":"蒙脽言則謂？孔也。俗謂之？？。"}]},"胯":{"expl":"股也。从肉夸聲。","rad":"肉","fq":"苦故切","vol":"04","py":"kuà","duan":[{"e":"股也。","n":"合兩股言曰胯。廣韵曰。胯、兩股之閒也。史記曰。不能死。出我胯下。"}]},"股":{"expl":"髀也。从肉殳聲。","rad":"肉","fq":"公戶切","vol":"04","py":"ɡǔ","duan":[{"e":"髀也。","n":"骨部曰。髀、股外也。言股則統髀。故曰髀也。"}]},"腳":{"expl":"脛也。从肉卻聲。","rad":"肉","fq":"居勺切","vol":"04","py":"jiǎo","duan":[{"e":"脛也。","n":"東方朔傳曰。結股腳。謂跪坐之狀。股與腳以厀爲中。腳之言卻也。凡卻步必先脛。"}]},"脛":{"expl":"胻也。从肉坙聲。","rad":"肉","fq":"胡定切","vol":"04","py":"jìnɡ","duan":[{"e":"胻也。","n":"厀下踝上曰脛。脛之言莖也。如莖之載物。"}]},"胻":{"expl":"脛耑也。从肉行聲。","rad":"肉","fq":"戶更切","vol":"04","py":"hénɡ","duan":[{"e":"脛耑也。","n":"耑猶頭也。脛近膝者曰胻。如股之外曰髀也。言脛則統胻。言胻不統脛。龜策傳曰。壯士斬其胻。卽斮朝涉之脛也。"}]},"䔃":{"expl":"菜也。从艸祖聲。","rad":"艸","fq":"則古切","vol":"01","py":"zǔ","duan":[{"e":"菜也。","n":"廣雅。蒩、蕺也。崔豹古今注曰。荆楊人謂蒩爲蕺。蜀都賦劉注曰。蒩亦名土茄。葉覆地生。根可食。人饑則以繼糧。風土記曰。䔼、香菜。根似茅根。蜀人所謂蒩香。段公路北戸錄曰。䔼、秦人謂之葅子。按䔼與蕺同。側立切。作蕋者誤。蒩作蒩葅皆誤。說文無蕺字。卽今魚腥艸也。凶年人掘食之。"}]},"腓":{"expl":"脛腨也。从肉非聲。","rad":"肉","fq":"符飛切","vol":"04","py":"féi","duan":[{"e":"脛腨也。","n":"咸六二。咸其腓。鄭曰。腓、膞腸也。按諸書或言膞腸。或言腓腸。謂脛骨後之肉也。腓之言肥。似中有腸者然。故曰腓腸。荀爽易作肥。云謂五也尊盛。故稱肥。此荀以意改字耳。"}]},"腨":{"expl":"腓腸也。从肉耑聲。","rad":"肉","fq":"市沇切","vol":"04","py":"shuàn","duan":[{"e":"腓腸也。","n":"腨者、脛之一耑。舉腨不該脛也。然析言之如是。統言之則以腨該全脛。如禮經之言肫骼是也。禮經多作肫。或作膞。皆假借字。山海經謂之䏿。"}]},"胑":{"expl":"體四胑也。从肉只聲。","rad":"肉","fq":"章移切","vol":"04","py":"zhī","duan":[{"e":"體四胑也。","n":"荀子君道篇。如四胑之從心。淮南脩務訓。四胑不動。孟子謂之四體。孟子注胑作枝。云體者、四枝股肱也。又云折枝、按摩折手節、解罷枝也。自胳胠至腨言手足也。故緫之以胑。"}]},"胲":{"expl":"足大指毛也。从肉亥聲。","rad":"肉","fq":"古哀切","vol":"04","py":"ɡāi","duan":[{"e":"足大指毛肉。","n":"肉字依篇、韵補。倉公傳正義作皮。足母指上多生毛謂之毛肉。故字從肉。國語。至於手拇毛脈。謂手拇有毛脈也。莊子。臘者之有膍胲。音義云。胲、足大指也。漢書。樹頰胲。假爲𦠄也。"}]},"肖":{"expl":"骨肉相似也。从肉小聲。不似其先，故曰“不肖”也。","rad":"肉","fq":"私妙切","vol":"04","py":"xiào","duan":[{"e":"骨肉相佀也。","n":"骨肉相似者、謂此人骨肉與彼人骨肉狀皃略同也。故字從肉。漢㓝法志假宵。列子假俏。"}]},"胤":{"expl":"子孫相承續也。从肉；从八，象其長也；从幺，象重累也。","rad":"肉","fq":"羊晉切","vol":"04","py":"yìn","duan":[{"e":"子孫相承續也。","n":"釋詁。胤嗣繼也。大雅毛傳。胤嗣也。"}]},"胄":{"expl":"𦙍也。从肉由聲。","rad":"肉","fq":"直又切","vol":"04","py":"zhòu","duan":[]},"䏌":{"expl":"振䏌也。从肉八聲。","rad":"肉","fq":"許訖切","vol":"04","py":"qì","duan":[{"e":"振肸也。","n":"振肸依玉篇。今本玉篇肸譌眸。十部曰。肸蠁、布也。然則振肸者、謂振動布寫也。以曡韵爲訓也。鍇本云振也。鉉本云振䏌也。皆非是。禮樂志曰。鸞路龍鱗。罔不肸飾。師古曰。肸、振也。謂皆振整而飾之也。上林賦。肸蠁布寫。師古曰。肸蠁、盛作也。甘泉賦。薌呹肸以掍根。師古曰。言風之動樹。聲響振起。此皆與說文合。葢䏌與肸音義皆同許無八佾字。今按作䏌作肸皆可。左傳言振萬舞者、必振動也。尸部曰。㞕、動作切切也。此從䏌㑹意也。"}]},"膻":{"expl":"肉膻也。从肉亶聲。《詩》曰：“膻裼暴虎。”","rad":"肉","fq":"徒旱切","vol":"04","py":"dàn","duan":[{"e":"肉膻也。","n":"釋訓、毛傳皆云。襢裼、肉襢也。李巡云。脫衣見體曰肉襢。孫炎云。襢去裼衣。按多作襢、作袒、非正字。膻其正字。素問膻中、謂氣海。"}]},"䑋":{"expl":"益州鄙言人盛，諱其𦘺謂之䑋。从肉襄聲。","rad":"肉","fq":"如兩切","vol":"04","py":"rǎnɡ","duan":[{"e":"益州鄙言人盛諱其肥謂之䑋。","n":"方言曰。梁益之閒、凡人言盛及其所愛諱其肥？謂之壤。鄒陽上書。壤子王梁代。晉灼注引方言。梁益之閒、所愛諱其肥盛曰壤也。李善曰。諱、方言作瑋。按李所據方言作瑋。許書諱亦當作瑋。瑋同偉。奇也。驚羨之意也。䑋假借作壤。"}]},"𦼫":{"expl":"菜也。似蘇者。从艸豦聲。","rad":"艸","fq":"彊魚切","vol":"01","py":"qú","duan":[{"e":"菜也。佀蘇者。","n":"此齊民要術蘘荷芹𦼫之𦼫。本艸新補之苦苣也。野生者名褊苣。人家常食爲白苣。江外嶺南吳人無白苣。嘗植野苣以供廚饌。字或作𧃢。俗譌作苣。廣雅云。蕒、𧃢也。曹憲云。白𧃢與苦蕒大異。恐非。廣韵曰。苦𦼫、江東呼爲苦蕒。賈思勰引詩義疏云。𦼫、苦葵也。靑州謂之苞。"}]},"𦝨":{"expl":"臞也。从肉皆聲。","rad":"肉","fq":"古諧切","vol":"04","py":"jiē","duan":[{"e":"臞也。从肉。皆聲。","n":"古諧切。十五部。"}]},"臞":{"expl":"少肉也。从肉瞿聲。","rad":"肉","fq":"其俱切","vol":"04","py":"qú","duan":[{"e":"少肉也。","n":"釋言。臞、瘠也。周禮注。瘠、臞也。"}]},"脫":{"expl":"消肉臞也。从肉兌聲。","rad":"肉","fq":"徒活切","vol":"04","py":"tuō","duan":[{"e":"消肉臞也。","n":"消肉之臞、臞之甚者也。今俗語謂𤸃太甚者曰脫形。言其形象如解蛻也。此義少有用者。今俗用爲分散、遺失之義分散之義當用挩手部挩下曰。解挩也。遺失之義當用奪奞部曰。奪、手持隹失之也。"}]},"脙":{"expl":"齊人謂臞脙也。从肉求聲。讀若休止。","rad":"肉","fq":"巨鳩切","vol":"04","py":"qiú","duan":[{"e":"齊人謂臞脙也。","n":"臞、齊人曰脙。雙聲之轉也。釋言曰。臞、脙、瘠也。玉篇云。齊人謂瘠腹爲脙。"}]},"𦣏":{"expl":"臞也。从肉䜌聲。一曰切肉，臠也。《詩》曰：“棘人臠臠兮。”","rad":"肉","fq":"力沇切","vol":"04","py":"luán","duan":[{"e":"臞也。","n":"毛詩傳曰。欒欒、𤸃瘠皃。葢或三家詩有作臠、從正字。毛作欒、從假借字。抑許所據毛作臠。皆不能肊定也。"}]},"膌":{"expl":"瘦也。从肉𦟝聲。","rad":"肉","fq":"資昔切","vol":"04","py":"jí","duan":[{"e":"𤸃也。","n":"𤕫部曰。𤸃、臞也。許欲令其義錯見也。膌亦作瘠。𤸃亦作膄。凡人少肉則脊吕歷歷然。故其字從脊。大雅。串夷載路。箋云。路、瘠也。天意去殷之惡。就周之德。文王則侵伐混夷以瘠之。此讀路爲露也。瘠者露骨。"}]},"𦛆":{"expl":"騃也。从肉丞聲。讀若丞。","rad":"肉","fq":"署陵切","vol":"04","py":"chénɡ","duan":[{"e":"騃也。","n":"馬部曰。騃、馬行仡仡也。人部曰。仡、勇壯也。按騃取壯意。凡肥者多癡。故方言曰。癡、騃也。廣韵曰。脀、癡皃。下文胗腄等字皆言人病。騃亦病之一也。"}]},"胗":{"expl":"脣瘍也。从肉㐱聲。","rad":"肉","fq":"之忍切","vol":"04","py":"zhěn","duan":[{"e":"脣瘍也。","n":"宋玉風賦曰。中脣爲胗。"}]},"腄":{"expl":"瘢胝也。从肉垂聲。","rad":"肉","fq":"竹垂切","vol":"04","py":"zhuī","duan":[{"e":"跟胝也。","n":"跟鉉作瘢。不可通。跟、足歱也。戰國策。墨子聞之。百舍重繭。高注。重繭、絫胝也。是足跟生胝之說也。"}]},"胝":{"expl":"腄也。从肉氐聲。","rad":"肉","fq":"竹尼切","vol":"04","py":"zhī","duan":[{"e":"腄也。","n":"漢書。躳奏無胈。史記作躳胝無胈。徐廣曰。胝竹移反。胝、腄也。李善引郭璞三蒼解曰。胝、𨇿也。竹施反。按據此二音。似胝本從氏聲。在五支韵。然小顏注漢云。竹尸反。今說文作胝、從氐。今韵入六脂。姑仍其舊。"}]},"薇":{"expl":"菜也。似藿。从艸微聲。","rad":"艸","fq":"無非切","vol":"01","py":"wēi","duan":[{"e":"菜也。","n":"見毛傳。"}]},"肬":{"expl":"贅也。从肉尤聲。","rad":"肉","fq":"羽求切","vol":"04","py":"yóu","duan":[{"e":"贅肬也。","n":"各本奪肬字。今補。贅同綴。書傳多贅綴通用。故此直作贅。綴、屬也。屬於皮上。如地之有丘也。"}]},"肒":{"expl":"搔生創也。从肉丸聲。","rad":"肉","fq":"胡岸切","vol":"04","py":"huàn","duan":[{"e":"搔生創也。","n":"手搔皮肉成瘡。"}]},"腫":{"expl":"癰也。从肉重聲。","rad":"肉","fq":"之隴切","vol":"04","py":"zhǒnɡ","duan":[{"e":"癰也。","n":"𤕫部曰。癰、腫也。瘍醫注曰。腫瘍癰而上生創者。按凡膨脹粗大者謂之雍腫。生民毛傳。種、雍腫也。莊子說木盤癭曰雍腫。雍俗作擁。"}]},"胅":{"expl":"骨差也。从肉失聲。讀與跌同。","rad":"肉","fq":"徒結切","vol":"04","py":"dié","duan":[{"e":"骨差也。","n":"謂骨節差忒不相值。故胅出也。蘇林漢書注云。窅胅。窅謂入。胅謂出。爾雅注云胅起高二尺許、山海經結匈國注云臆前胅出如人結㗋、玄應書顀頭胅頟皆是。窅胅倉頡篇作容胅。葛洪字苑作凹凸。今俗通用作坳突。"}]},"脪":{"expl":"創肉反出也。从肉希聲。","rad":"肉","fq":"香近切","vol":"04","py":"xìn","duan":[{"e":"創肉反出也。","n":"今洗冤録所謂皮肉捲凸也。"}]},"䏖":{"expl":"瘢也。从肉引聲。一曰遽也。","rad":"肉","fq":"羊晉切","vol":"04","py":"zhèn","duan":[{"e":"瘢也。","n":"𤕫部瘢、痍也。痍、傷也。"}]},"臘":{"expl":"冬至後三戌，臘祭百神。从肉巤聲。","rad":"肉","fq":"盧盍切","vol":"04","py":"là","duan":[{"e":"冬至後三戌臘祭百神。","n":"三戌下玉篇有爲字。非也。臘本祭名。因呼臘月、臘日耳。月令。臘先祖五祀。左傳。虞不臘矣。皆在夏正十月。臘卽蜡也。風俗通云。禮傳夏曰嘉平。殷曰淸祀。周曰大蜡。皇侃曰。夏殷蜡在己之歲終。皇說是也。秦本紀。惠王十二年初臘。記秦始行周正亥月大蜡之禮也。始皇三十一年十二月更名臘曰嘉平。十二月者、丑月也。始皇始建亥。而不敢謂亥月爲春正月。但謂之十月朔而已。項羽紀書漢之二年冬。繼之以春。繼之以四月。可證也。更名臘爲嘉平者、改臘在丑月用夏制。因用夏名也。臘在丑月、因謂丑月爲臘月。陳勝傳書臘月是也。漢仍秦制。亦在丑月。而用戌日、則漢所獨也。風俗通曰。臘者、接也。新故交接。大祭以報功也。漢家火行。火衰於戌。故曰臘也"}]},"膢":{"expl":"楚俗以二月祭飲食也。从肉婁聲。一曰祈穀食新曰離膢。","rad":"肉","fq":"力俱切","vol":"04","py":"lǘ","duan":[{"e":"楚俗㠯二月祭㱃食也。","n":"風俗通曰。韓子書。山居谷汲者、膢臘而買水。楚俗常以十二月祭飮食也。按買水、今本韓子作相遺以水。皆謂水少耳。風俗通作十二月。劉昭引同。與許書二月異。疑十爲衍字。仲遠書多襲用說文也。劉玄傳注引漢書音義云。冀州北郡以八月朝作飮食爲膢。其俗語曰膢臘社伏。玄應引三倉云。膢、八月祭也。篇、韵皆云。膢、飮食祭也。冀州八月。楚俗二月。合說文與漢書音義言之。"}]},"朓":{"expl":"祭也。从肉兆聲。","rad":"肉","fq":"土了切","vol":"04","py":"tiǎo","duan":[{"e":"祭也。","n":"祭名也。廣雅云。祧祭也。祧當作？。"}]},"胙":{"expl":"祭福肉也。从肉乍聲。","rad":"肉","fq":"昨誤切","vol":"04","py":"zuò","duan":[{"e":"祭福肉也。","n":"福者、皇尸命工祝承致多福無疆于女孝孫是也。周禮。以脤膰之禮親兄弟之國。注曰。同福祿也。引伸之几福皆言胙。如左傳言天胙明德、無克胙國、國語胙以天下、胙四岳國是也。自後人肊造祚字以改經傳。由是胙祚錯出矣。"}]},"蓶":{"expl":"菜也。从艸唯聲。","rad":"艸","fq":"以水切","vol":"01","py":"wéi","duan":[{"e":"菜也。","n":"齊民要術曰。蓶菜音唯。似烏韭而黃。"}]},"隋":{"expl":"裂肉也。从肉，从隓省。","rad":"肉","fq":"徒果切","vol":"04","py":"duò","duan":[{"e":"裂肉也。","n":"衣部曰。裂、繒餘也。齊語。戎車待游車之？。韋曰。？、殘也。裂訓繒餘。引伸之凡餘皆曰裂。裂肉謂尸所祭之餘也。守祧。旣祭則藏其隋。注。隋、尸所祭肺脊黍稷之屬。其儀節詳於禮十七篇。其字故文士虞禮作隋。與周禮同。特牲、少牢篇今文作綏。古文作挼或作妥。鄭注云。周禮作隋。隋與挼讀同。又云。挼讀爲隋。注曾子問亦云。綏、周禮作隋。是鄭以隋爲正字。與許同也。尸祭刌肺黍稷之屬。巳祭則爲？餘無用之物。故云裂肉。單言肉者。爲其字從肉也。"}]},"膳":{"expl":"具食也。从肉善聲。","rad":"肉","fq":"常衍切","vol":"04","py":"shàn","duan":[{"e":"具食也。","n":"此與食部䉵字同義。具者、供置也。欲善其事也。鄭注周禮膳夫曰。膳之言善也。又云。膳羞之膳、牲肉也。"}]},"腬":{"expl":"嘉善肉也。从肉柔聲。","rad":"肉","fq":"耳由切","vol":"04","py":"róu","duan":[{"e":"嘉善肉也。","n":"謂肥美。小徐云。晉語曰。若克有成。無亦晉之柔嘉。是以甘食。偃之肉腥臊。將焉用之。"}]},"肴":{"expl":"啖也。从肉爻聲。","rad":"肉","fq":"胡茅切","vol":"04","py":"yáo","duan":[{"e":"啖也。","n":"折俎謂之肴。見左傳、國語。豆實謂之肴。見毛傳。凡非榖而食曰肴。見鄭箋。皆可啖者也。按許當云啖肉也。謂熟饋可啖之肉。今本有奪字。"}]},"腆":{"expl":"設膳腆腆多也。从肉典聲。","rad":"肉","fq":"他典切","vol":"04","py":"tiǎn","duan":[{"e":"設膳腆腆多也。","n":"士昏禮注、邶風箋皆曰。腆、善也。方言、公羊傳注皆曰。腆、厚也。此皆引伸之義也。禮古文以殄爲腆。"}]},"腯":{"expl":"牛羊曰𦘺，豕曰腯。从肉盾聲。","rad":"肉","fq":"他骨切","vol":"04","py":"tú","duan":[{"e":"牛羊曰肥。豕曰腯。","n":"按人曰肥。獸曰腯。此人物之大辨也。又析言之。則牛羊得偁肥、豕獨偁腯。曲禮。豕曰剛鬣。豚曰腞肥。注云。腞亦肥也。春秋傳作腯。腯、充皃也。按曲禮經注當如是。今本經文作腯則不可通矣。腞亦腯字也。釋文腯本亦作豚、乃本亦作腞之誤。郭注方言曰。腯腯、肥充也。音突。亦作腞。是其證。左傳。奉牲以吿曰。博碩肥腯。下文以謂民力溥存、釋博。以謂其畜之碩大蕃滋、釋碩。以謂其不疾瘯蠡、釋肥。以謂其備腯咸有、釋腯。曲禮專謂豚。左氏統言之。"}]},"䏟":{"expl":"𦘺肉也。从肉必聲。","rad":"肉","fq":"蒲結切","vol":"04","py":"bié","duan":[{"e":"肥肉也。","n":"廣韵曰。䏟、㚛肥也。㚛、肥狀也。"}]},"胡":{"expl":"牛𩔞垂也。从肉古聲。","rad":"肉","fq":"戶孤切","vol":"04","py":"hú","duan":[{"e":"牛𩔞𠂹也。","n":"玄應、司馬貞引皆作牛領。按此言？以包頸也。？、頤也。牛自頤至頸下垂肥者也。引伸之凡物皆曰胡。如老狼有胡、鴺胡、龍垂胡䫇是也。胡與矦音轉冣近。故周禮立當前矦注曰。車轅前胡下垂柱地者。經傳胡矦遐皆訓何。士冠禮。永受胡福。鄭曰。胡猶遐也。毛傳。胡、壽也。謚法。彌年壽考曰胡。𠈃民耆艾曰胡。皆謂壽命遐遠。"}]},"胘":{"expl":"牛百葉也。从肉，弦省聲。","rad":"肉","fq":"胡田切","vol":"04","py":"xián","duan":[{"e":"牛百葉也。","n":"廣雅。胃謂之胘。李時珍云。胘卽胃之厚處。齊民要術有牛胘炙。卽牛百葉也。公羊傳注。自左髀達於右胘。謂達於胃也。"}]},"膍":{"expl":"牛百葉也。从肉𣬉聲。一曰鳥膍胵。","rad":"肉","fq":"房脂切","vol":"04","py":"pí","duan":[{"e":"牛百葉也。","n":"周禮醢人、旣夕禮皆云脾析。周禮注。鄭司農云。脾析、牛百葉也。旣夕注云。脾讀爲雞脾𦚚之脾。脾析、百葉也。按𦚚從此聲。釋文尺之反。内則鴇奥注。奥、脾𦚚也。字亦作𦚚。釋文昌私反。今儀禮注、禮記釋文𦚚皆作肶。誤甚。𦚚與斯、斯與析音近。故釋脾析爲脾𦚚。雞鴇皆有脾𦚚。謂胃也。卽許所謂鳥膍胵也。鄭與許字異而音義同。謂之百葉者、胃薄如葉。碎切之。故云百葉。未切爲膍胵。旣切則謂之脾析、謂之百葉也。此胃也、而經注何以謂之脾。葢如今人俗語脾胃連言。故以脾之名加於胃也。經文脾析、說禮家容有讀爲膍者。故許從之。不欲與土藏同名也。莊子。臘者之有膍胲。司馬云。膍、牛百葉也。是也。大雅。加肴脾臄。脾葢亦謂百葉。許以牛百葉系諸"}]},"菦":{"expl":"菜，類蒿。从艸近聲。《周禮》有“菦菹”。","rad":"艸","fq":"巨巾切","vol":"01","py":"qín","duan":[{"e":"菜、類蒿。","n":"詩、禮皆作芹。小雅箋曰。芹、菜也。可以爲菹。魯頌箋曰。芹、水菜也。釋艸及周禮注曰。芹、楚葵也。按卽今人所食芹菜。今說文各本於艾蔁二字之下又出芹字。訓楚葵也。从艸斤聲。此恐不知菦卽芹者妄用爾雅增之。攷周禮音義曰。芹、說文作菦。則說文之有菦無芹明矣。且詩箋引周禮芹菹。說文引周禮菦菹。豈得云二物也。"}]},"胵":{"expl":"鳥胃也。从肉至聲。一曰胵，五藏緫名也。","rad":"肉","fq":"處脂切","vol":"04","py":"chī","duan":[{"e":"鳥膍胵也。","n":"依全書通例正。"}]},"膘":{"expl":"牛脅後髀前合革肉也。从肉𤐫聲。讀若繇。","rad":"肉","fq":"敷紹切","vol":"04","py":"piǎo","duan":[{"e":"牛脅後髀前合革肉也。","n":"合革肉者、他處革與肉可分剥。獨此處不可分剥也。七發所謂犓牛之腴。毛傳云。射左膘。三蒼云。膘、小腹兩邊肉也。"}]},"𦝭":{"expl":"血祭肉也。从肉帥聲。","rad":"肉","fq":"呂戌切","vol":"04","py":"lǜ","duan":[{"e":"血祭肉也。","n":"郊特牲曰。取膟膋燔燎升首。報陽也。鄭云。膟膋、腸閒脂也。朝事時。取牲膟膋燔於爐炭。至薦孰之時。又取膟膋與蕭合燒之。按此注謂膟膋、腸閒脂。二字一物。祭義注云。膟膋、血與腸閒脂也。則以血釋膟、以腸閒脂釋膋。略同許說。小雅。執其鸞刀。以啟其毛。取其血膋。正與祭義毛牛尚耳、鸞刀以刲取膟膋乃退語相合。毛云。毛以吿純也。膋、脂膏也。血以吿殺。膋以升臭。合之黍稷。實之於蕭。合馨香也。葢說禮家以膟當詩之血。故許云血祭。鄭注祭義同。考之郊特牲。血祭與燔膟膋各事。膟膋自是一物。郊特牲注爲長也。許云血祭肉者、肉是衍字。血祭不容有肉。祭義疏引說文、字林。膟、血祭。無肉字。釁字下亦云血祭。"}]},"膫":{"expl":"牛腸脂也。从肉尞聲。《詩》曰：“取其血膫。”","rad":"肉","fq":"洛蕭切","vol":"04","py":"liáo","duan":[{"e":"牛腸脂也。从肉。尞聲。","n":"洛蕭切。二部。"}]},"脯":{"expl":"乾肉也。从肉甫聲。","rad":"肉","fq":"方武切","vol":"04","py":"fǔ","duan":[{"e":"乾肉也。","n":"周禮腊人。掌乾肉。凡田獸之脯腊膴胖之事。注云。大物解肆乾之謂之乾肉。薄析曰脯。捶之而施薑桂曰段脩。腊、小物全乾也。許於脯、於日部之㫺統言之曰乾肉。鄭則以大物小物析言之。"}]},"脩":{"expl":"脯也。从肉攸聲。","rad":"肉","fq":"息流切","vol":"04","py":"xiū","duan":[{"e":"脯也。","n":"膳夫大鄭注曰。脩、脯也。按此統言之。析言之則薄析曰脯。捶而施薑桂曰段脩。後鄭注内饔云脩、鍛脯也是也。曲禮疏云。脯訓始。始作卽成也。脩訓治。治之乃成。修治之謂捶而施薑桂。經傳多假脩爲修治字。"}]},"膎":{"expl":"脯也。从肉奚聲。","rad":"肉","fq":"戶皆切","vol":"04","py":"xié","duan":[{"e":"脯也。","n":"太玄曰。多田不婁。費我膎功。"}]},"脼":{"expl":"膎肉也。从肉兩聲。","rad":"肉","fq":"良獎切","vol":"04","py":"liǎnɡ","duan":[{"e":"膎肉也。","n":"廣雅曰。膎、脼肉也。不列於脯類。鍇本膎脼二篆在膊篆之下。集韵曰。吳人謂腌魚膎脼。"}]},"膊":{"expl":"薄脯，膊之屋上。从肉尃聲。","rad":"肉","fq":"匹各切","vol":"04","py":"pò","duan":[{"e":"薄脯、脯之屋上。","n":"膊之屋上當作薄之屋上。薄、迫也。釋名。膊、迫也。薄㭬肉迫箸物使燥也。說與許同。方言。？、暴也。燕之外郊朝鮮洌水之閒。凡㬥肉、發人之私、披牛羊之五藏謂之膊。左傳。龍人囚盧蒲就魁。殺而膊諸城上。周禮。斬殺賊諜而膊之。皆謂去衣磔其人。如迫脯於屋上也。又儀禮兩胉。今文作迫。周禮豚拍。杜子春以拍爲膊。謂脅也。按脅之正字當從禮今文作迫。"}]},"脘":{"expl":"胃府也。从肉完聲。讀若患。舊云脯。","rad":"肉","fq":"古卵切","vol":"04","py":"wǎn","duan":[{"e":"胃脯也。","n":"胃脯見史、漢貨殖傳。晉灼曰。今大官常以十月作沸湯燖羊胃、以末椒薑坋之㬥使燥是也。廣雅曰。脘、脯也。鉉本胃脯作胃府、則與上下文言脯者不貫。脘篆應廁於胃篆下矣。素問胃脘、謂胃宛中可容受。脘葢宛之俗。大廣益㑹玉篇脘注古卵切。胃脘。非許意。"}]},"䖆":{"expl":"菜也。从艸釀聲。","rad":"艸","fq":"女亮切","vol":"01","py":"niànɡ","duan":[{"e":"菜也。","n":"方言曰。蘇、沅湘之南或謂之𦵯音車轄其小者謂之䖆葇。許所說未必此也。齊民要術以爲藏菹之䖆。人丈切。內則注菜釀。不从艸。"}]},"朐":{"expl":"脯挺也。从肉句聲。","rad":"肉","fq":"其俱切","vol":"04","py":"qú","duan":[]},"膴":{"expl":"無骨腊也。楊雄說：鳥腊也。从肉無聲。《周禮》有膴判。讀若謨。","rad":"肉","fq":"荒烏切","vol":"04","py":"hū","duan":[{"e":"無骨腊也。","n":"腊今字也。日部作㫺。腊人。掌乾肉。凡田獸之脯腊膴胖之事。脯腊皆謂乾肉。故許釋膴爲無骨腊。葢賈侍中周禮解詁說。與鄭司農云。膴、膺肉。杜子春云。膴、胖皆謂夾脊肉。後鄭云。公食大夫禮曰。庶羞皆有大。有司曰。主人亦一魚加膴祭于其上。内則曰。麋鹿田豕麕皆有胖。足相參正也。大者胾之大臠。膴者魚之反覆。膴又詁曰大。二者同矣。則是膴亦䐑肉大臠。胖宜爲脯而腥。胖之言片也。析肉意也。按依後鄭說。膴胖皆非腊也。趙商問腊人掌凡乾肉而有膴胖何。鄭荅雖鮮亦屬腊人。此可證膴胖之非腊。許說葢偏執耳。下文云周禮有膴判。易胖爲判。度許亦必釋爲腊屬。而今亡其說矣。無骨之腊、故其字從肉。無骨則肥美、故引伸爲凡美之偁。毛詩傳曰。膴膴、"}]},"胥":{"expl":"蟹醢也。从肉疋聲。","rad":"肉","fq":"相居切","vol":"04","py":"xū","duan":[{"e":"蟹醢也。","n":"庖人。共祭祀之好羞。注。謂四時所爲膳食。若今荆州之䱹魚。靑州之蟹胥。雖非常物。進之孝也。釋名曰。蟹胥、取蟹藏之。使骨肉解足胥胥然也。字林云。胥、蟹醬也。按鄭云作醢及臡。必先膊乾其肉。乃後莝之。襍以粱麴及鹽。漬以美酒。塗置甀中。百日則成。許云蟹醢。作之當同也。釋名所云則似今之醉蟹。似劉說長。蟹者多足之物。引伸假借爲相與之義。釋詁曰。胥、皆也。又曰。胥、相也。今音相分平去二音爲二義。古不分。公羊傳曰。胥命者、相命也。榖梁傳曰。胥之爲言猶相也。毛傳於聿來胥宇、于胥斯原皆曰。胥、相也。此可證相與、相視古同音同義也。小雅。君子樂胥。毛曰。胥、皆也。賈誼書引此詩云胥相。此爾雅皆與相同義之證也。方言又曰。胥"}]},"腒":{"expl":"北方謂鳥腊曰腒。从肉居聲。傳曰：堯如腊，舜如腒。","rad":"肉","fq":"九魚切","vol":"04","py":"jū","duan":[{"e":"北方謂鳥腊腒。","n":"周禮、内則注皆曰。腒、乾雉。士相見之禮。摯、冬用雉。夏用腒。注曰。備腐臭也。按鄭主謂乾雉、依士相見禮而言也。士相見禮腒謂雉。周禮、内則不必專謂雉。許槩言鳥腊爲長。"}]},"肍":{"expl":"孰肉醬也。从肉九聲。讀若舊。","rad":"肉","fq":"巨鳩切","vol":"04","py":"qiú","duan":[{"e":"孰肉醬也。","n":"用孰肉爲醬。孰廣韵作乾。疑乾是。下文云生肉醬者、鮮肉醬也。"}]},"䐹":{"expl":"乾魚尾䐹䐹也。从肉肅聲。《周禮》有“腒䐹”。","rad":"肉","fq":"所鳩切","vol":"04","py":"sōu","duan":[{"e":"乾魚尾肅肅也。","n":"肅肅各本作䐹䐹。今正。肅肅、乾皃。今俗尚有乾肅肅之語。風俗通說夏馬掉尾肅肅。古言也。庖人、内則注曰。鱐、乾魚。籩人注曰。鱐者、析乾之。出東海。"}]},"腝":{"expl":"有骨醢也。从肉耎聲。","rad":"肉","fq":"人移切","vol":"04","py":"ní","duan":[{"e":"有骨醢也。","n":"酉部曰。醢、肉醬也。釋器曰。肉謂之醢。有骨者謂之臡。醢人注曰。臡亦醢也。或曰。有骨爲臡。無骨爲醢。公食大夫禮注曰。醢有骨謂之臡。"}]},"脠":{"expl":"生肉醬也。从肉延聲。","rad":"肉","fq":"丑連切","vol":"04","py":"shān","duan":[{"e":"生肉醬也。","n":"廣韵曰。魚醢也。引說文云肉醬。釋名、齊民要術有生脠。"}]},"𦜟":{"expl":"豕肉醬也。从肉否聲。","rad":"肉","fq":"薄口切","vol":"04","py":"bù","duan":[{"e":"豕肉醬也。","n":"魚部曰。鮨、魚䏽醬也。是魚肉醬亦偁䏽。"}]},"胹":{"expl":"爛也。从肉而聲。","rad":"肉","fq":"如之切","vol":"04","py":"ér","duan":[{"e":"爛也。","n":"爛火部作爤。火孰也。左傳。宰夫胹熊蹯不孰。謂火孰之而未孰也。方言。胹、熟也。自關而西秦晉之郊曰胹。按内則作濡。"}]},"莧":{"expl":"莧菜也。从艸見聲。","rad":"艸","fq":"侯澗切","vol":"01","py":"xiàn","duan":[{"e":"莧菜也。","n":"菜上莧字乃複寫隷字𠜂之僅存者也。尋說文之例。云䒨菜、葵菜、䔃菜、𦼫菜、薇菜、蓶菜、菦菜、䖆菜、莧菜以釋篆文。𦮙者、字形。葵菜也者、字義。如水部<>（河）者、字形。河水也者、字義。若云此篆文是葵菜也、此篆文是河水也。槩以爲複字而𠜂之。此不學之過。周易音義引宋衷云。莧、莧菜也。此可以證矣。爾雅。蕢、赤莧。郭注。今人莧、赤莖者。按人莧、莧名。"}]},"䐣":{"expl":"切孰肉，内於血中和也。从肉員聲。讀若遜。","rad":"肉","fq":"穌本切","vol":"04","py":"sǔn","duan":[{"e":"切孰肉内於血中和也。","n":"釋名有肺𦠆。𦠆同䐣。五經文字曰。𦠆見禮經注。廣韵三十三線曰。𦠆同饌。見儀禮。士戀切。"}]},"胜":{"expl":"犬膏臭也。从肉生聲。一曰不孰也。","rad":"肉","fq":"桑經切","vol":"04","py":"xīnɡ","duan":[{"e":"犬膏臭也。","n":"庖人、内則。秋行犢麛膳膏腥。杜子春云。膏腥、豕膏也。後鄭云。膏腥、雞膏也。許云犬膏。葢本賈侍中。"}]},"臊":{"expl":"豕膏臭也。从肉喿聲。","rad":"肉","fq":"穌遭切","vol":"04","py":"sāo","duan":[{"e":"豕膏臭也。","n":"庖人、内則曰。夏行腒鱐膳膏臊。杜子春云。膏臊、犬膏。大鄭云。膏臊、豕膏。後鄭從杜說。許同大鄭。"}]},"膮":{"expl":"豕肉羹也。从肉堯聲。","rad":"肉","fq":"許幺切","vol":"04","py":"xiāo","duan":[{"e":"豕肉羹也。","n":"公食大夫禮注曰。膷臐膮、今時𦞦也。牛曰膷。羊曰臐。豕曰膮。皆香美之名也。古文膷作香。臐作熏。按許無膷臐二字。從古文不從今文也。内則同今文作膷臐。又按此庶羞豆實也。其謂之羹何。羹有實於鼎者、牛藿羊苦豕薇是也。有實於豆者、膷臐膮是也。鄭云𦞦也。許云𦞦肉羹也。說正同。𦞦亦謂之羹。而較乾於？羹。且？羹有菜芼。𦞦不云用菜芼也。"}]},"腥":{"expl":"星見食豕，令肉中生小息肉也。从肉从星，星亦聲。","rad":"肉","fq":"穌佞切","vol":"04","py":"xìnɡ","duan":[{"e":"星見食豕。令肉中生小息肉也。","n":"息當作瘜。？部曰。瘜、寄肉也。星見時飼豕。每致此疾。内饔曰。豕盲眡而交睫腥。盲眡、内則作望視。鄭云。腥當爲星。聲之誤也。肉有如米者似星。注内則同。按鄭意腥爲腥孰字。豕不可食者當作星。與經傳及今俗用字皆合。許則謂腥孰字正作胜。腥專謂豕不可食者。與鄭絕異。爾雅。米者謂之糪。郭云。飯中有腥。其用字與許同也。"}]},"脂":{"expl":"戴角者脂，無角者膏。从肉旨聲。","rad":"肉","fq":"旨夷切","vol":"04","py":"zhī","duan":[{"e":"戴角者脂。無角者膏。","n":"大戴易本命曰。戴角者無上齒。謂牛無上齒、觸而不噬也。無角者膏而無前齒。謂豕屬也。無前齒者、齒盛於後不用前。有羽者脂而無後齒。羽當爲角。謂羊屬也。齒盛於前不任後。考工記鄭注曰。脂者牛羊屬。膏者豕屬。内則注曰。肥凝者爲脂。釋者爲膏。按上文膏系之人。則脂系之禽。此人物之辨也。有角無角者各異其名。此物中之辨也。釋膏以脂。禽亦曰膏。周禮香臊腥羶皆曰膏。此皆統言不別也。"}]},"䐝":{"expl":"觷也。从肉𧴪聲。","rad":"肉","fq":"穌果切","vol":"04","py":"suò","duan":[{"e":"䑁也。","n":"䑁各本譌觷。說者以釋器角謂之觷釋之。誤甚。角部本無觷字。此上下文皆言脂膏。治角之義無從𨷻入也。玉篇。䐝、膏䑁也。䑁、膏䐝也。廣韵過韵。䐝、䑁膏也。䑁又見屋沃韵。是可據以正誤補缺矣。"}]},"膩":{"expl":"上𦘺也。从肉貳聲。","rad":"肉","fq":"女利切","vol":"04","py":"nì","duan":[{"e":"上肥也。","n":"謂在上者。釋器曰。冰脂也。郭云。莊子。肌膚若冰雪。冰雪、脂膏也。按此所謂上肥也。冰凝古今字。毛詩膚如凝脂同也。楚辭。靡顏膩理。膩、滑也。"}]},"膜":{"expl":"肉閒胲膜也。从肉莫聲。","rad":"肉","fq":"慕各切","vol":"04","py":"mó","duan":[{"e":"肉閒胲膜也。","n":"釋名。膜、幕也。幕絡一體也。廣雅。䐼䐞膜也。䐞與膜爲一。許意爲二。膜在肉裏也。許爲長。胲膜者、絫呼之。胲之言該也。按膜䐞皆人物所同。許專系之物者、在人者不可得見也。"}]},"䐞":{"expl":"肉表革裏也。从肉弱聲。","rad":"肉","fq":"而勺切","vol":"04","py":"ruò","duan":[{"e":"肉表革裏也。","n":"考工記注曰。今人謂蒲本在水中者爲弱。按蒻在莖之下、根之上。肉表革裏名䐞、亦猶是也。"}]},"祕":{"expl":"神也。从示必聲。","rad":"示","fq":"兵媚切","vol":"01","py":"mì","duan":[{"e":"神也。","n":"魯頌閟宫有侐箋曰。閟、神也。此謂假借閟爲祕也。"}]},"芋":{"expl":"大葉實根，駭人，故謂之芌也。从艸亏聲。","rad":"艸","fq":"王遇切","vol":"01","py":"yù","duan":[{"e":"大葉實根駭人。故謂之芌也。","n":"口部曰。吁、驚也。毛傳曰。訏、大也。凡于聲字多訓大。芋之爲物。葉大根實。二者皆堪駭人。故謂之芋。其字从艸于聲也小雅。君子攸芋。毛傳。芋、大也。謂居中以自光大。箋云。芋當作幠。"}]},"𦞦":{"expl":"肉羹也。从肉隺聲。","rad":"肉","fq":"呼各切","vol":"04","py":"hè","duan":[{"e":"肉羹也。","n":"䰜部曰。？、五味盉？也。釋器曰。肉謂之羹。羹有二。實於？者用菜、芼之謂之羹。實於庶羞之豆者不用芼。亦謂之羹。禮經牛膷羊臐豕膮。鄭云今時𦞦也。是今謂之𦞦、古謂之羹。𦞦字不見於古經而見於招䰟。王逸曰。有菜曰羹。無菜曰𦞦。王說與禮合。許不云羹也而云肉羹也者、亦無菜之謂。匡謬正俗駁叔師說。其言甚誤。"}]},"膹":{"expl":"𦞦也。从肉賁聲。","rad":"肉","fq":"房吻切","vol":"04","py":"fèn","duan":[{"e":"𦞦也。","n":"廣雅曰。臇膹䐣臛也。臛俗𦞦字。"}]},"臇":{"expl":"𦞦也。从肉雋聲。讀若纂。","rad":"肉","fq":"子沇切","vol":"04","py":"juǎn","duan":[{"e":"𦞦也。","n":"李善引蒼頡解詁曰。臇、少汁臛也。曹植七啟曰。臇漢南之鳴鶉。名都篇曰。膾鯉臇胎鰕。"}]},"胾":{"expl":"大臠也。从肉𢦔聲。","rad":"肉","fq":"側吏切","vol":"04","py":"zì","duan":[{"e":"大臠也。","n":"切肉之大者也。"}]},"䐑":{"expl":"薄切肉也。从肉枼聲。","rad":"肉","fq":"直葉切","vol":"04","py":"zhé","duan":[{"e":"薄切肉也。","n":"云薄者、取從枼之意。少儀曰。牛與羊魚之腥。聶而切之爲膾。注。聶之言䐑也。先藿葉切之、復報切之。則爲膾。醢人注引少儀聶皆作䐑。腊人注云。膴亦䐑肉大臠。按如許、鄭說。䐑者、大片肉也。鄭云。凡醢醬所和細切爲韲。全物若䐑爲菹。"}]},"膾":{"expl":"細切肉也。从肉會聲。","rad":"肉","fq":"古外切","vol":"04","py":"kuài","duan":[{"e":"細切肉也。","n":"所謂先藿葉切之、復報切之也。報者、俗語云急報。凡細切者必疾速下刀。少儀注云。報讀爲赴疾之赴。拔赴皆疾也。"}]},"腌":{"expl":"漬肉也。从肉奄聲。","rad":"肉","fq":"於業切","vol":"04","py":"yān","duan":[{"e":"漬肉也。","n":"今淹漬字當作此。淹行而腌廢矣。方言云。淹、敗也。水敗爲淹。皆腌之引伸之義也。腌猶瀸也。肉謂之腌。魚謂之饐。倉頡篇云。腌酢、淹肉也。"}]},"脃":{"expl":"小耎易斷也。从肉，从絕省。","rad":"肉","fq":"此芮切","vol":"04","py":"cuì","duan":[{"e":"小耎易𣃔也。","n":"七發曰。甘脃肥膿。魏都賦。稟質遳脃。作脆者、誤也。"}]},"膬":{"expl":"耎易破也。从肉毳聲。","rad":"肉","fq":"七絕切","vol":"04","py":"cuì","duan":[{"e":"耎易破也。","n":"耎七發注作腝。腝者、醢有骨者也。七發曰。飮食則溫淳甘膬。脭醲肥厚。"}]},"𢿱":{"expl":"雜肉也。从肉㪔聲。","rad":"肉","fq":"穌旰切","vol":"04","py":"sàn","duan":[{"e":"襍肉也。","n":"從𢽳者、㑹意也。𢽳、分離也。引伸凡𢽳皆作？。？行而𢽳廢矣。"}]},"莒":{"expl":"齊謂芌爲莒。从艸呂聲。","rad":"艸","fq":"居許切","vol":"01","py":"jǔ","duan":[{"e":"齊謂芋爲莒。","n":"所謂別國方言也。借爲國名。"}]},"膞":{"expl":"切肉也。从肉專聲。","rad":"肉","fq":"市沇切","vol":"04","py":"zhuǎn","duan":[{"e":"切肉也。","n":"膞與剸義近。儀禮說牲體前有肩臂臑。後有肫髀骼。髀不升於俎。故多言肫骼。肫亦作膞。經肫膞錯出。皆假借字也。經本應作腨。腨、腓腸也。以腓腸該全脛。假肫膞字爲之。"}]},"腏":{"expl":"挑取骨閒肉也。从肉叕聲。讀若《詩》曰“啜其泣矣”。","rad":"肉","fq":"陟劣切","vol":"04","py":"chuò","duan":[{"e":"挑取骨閒肉也。","n":"手部曰。抉、挑也。"}]},"𦚙":{"expl":"食所遺也。从肉仕聲。《易》曰：“噬乾𦚙。”","rad":"肉","fq":"阻史切","vol":"04","py":"zǐ","duan":[{"e":"食所遺也。","n":"馬融、陸績皆曰。肉有骨謂之？。說文、字林作？。訓爲食所遺。葢孟本孟說與。"}]},"䐄":{"expl":"食肉不猒也。从肉臽聲。讀若陷。","rad":"肉","fq":"戶𤟟切","vol":"04","py":"xiàn","duan":[{"e":"食肉不猒也。","n":"猒、飽也。"}]},"肰":{"expl":"犬肉也。从犬、肉。讀若然。","rad":"肉","fq":"如延切","vol":"04","py":"rán","duan":[{"e":"犬肉也。从肉犬。讀若然。","n":"如延切。十四部。"}]},"䐜":{"expl":"起也。从肉眞聲。","rad":"肉","fq":"昌眞切","vol":"04","py":"chēn","duan":[{"e":"起也。","n":"當云肉起也。素問曰。濁氣在上則生䐜脹。王砅注。䐜、脹起也。按許廁此、謂人所食肉。"}]},"䏙":{"expl":"肉汁滓也。从肉冘聲。","rad":"肉","fq":"他感切","vol":"04","py":"tǎn","duan":[{"e":"肉汁滓也。","n":"醢人。韭菹醓醢。注云。醓、肉汁也。公食大夫禮注曰。醓醢、醢有醓。釋名曰。醢多汁者曰醓。醓、瀋也。宋、魯人皆謂汁爲瀋。按合此三條。可見禮經醓醢正字當作䏙。謂多肉汁之醢也。許云汁滓者、謂醢不同湇也。合醢人注及血部？下觀之。䏙醢用牛乾脯莝之。襍以粱麴及鹽。漬以美酒。塗置甀中。百日則成。葢他醢及臡皆用此法。如蠃醢則用乾蠃肉、麋臡則用乾麋肉也。凡醢臡皆有汁、而牛乾脯獨得䏙名者、六畜不言牲名。他醢臡不言䏙。立文錯見之法。汁卽鹽酒所成。醢皆胜物。非有孰汁也。毛傳云。以肉曰醓醢。大鄭云。醓醢、肉醬也。皆言肉以包汁。不言何肉者、葢謂周禮六牲之肉。下文醢臡麋鹿麇兔鴈在六獸六禽内。可證也。許但言牛乾脯者、舉六牲之一"}]},"膠":{"expl":"昵也。作之以皮。从肉翏聲。","rad":"肉","fq":"古肴切","vol":"04","py":"jiāo","duan":[{"e":"昵也。","n":"弓人說膠曰。凡昵之類不能方。注故書昵或作樴。杜子春云。樴讀爲不義不昵之昵。或爲䵑。䵑、黏也。玄謂樴、脂膏䐈敗之䐈。䐈亦黏也。按此經杜作昵、又作䵑。後鄭作䐈。其意則同也。許從杜作昵。日部曰。暱、日近也。或作昵。是則昵亦訓黏也。一說此昵也、及周禮注不義不昵之昵。三昵字皆當作䵒。"}]},"𦟀":{"expl":"或曰：嘼名，象形。闕。","rad":"肉","fq":"郎果切","vol":"04","py":"luó","duan":[{"e":"或曰嘼名。","n":"或曰、不定之䛐。云嘼名、葢𣎆爲驘之古字。與驢驘皆可畜於家。則謂之畜宜也。"}]},"䏣":{"expl":"蠅乳肉中也。从肉且聲。","rad":"肉","fq":"七余切","vol":"04","py":"qū","duan":[{"e":"蠅乳肉中也。","n":"三蒼曰。蠅乳肉中曰䏣。通俗文云。肉中蟲曰䏣。周禮蜡氏注。蜡、骨肉腐臭蠅蟲所蜡也。蜡讀如狙司之狙。按狙司俗作覰伺。釋蟲。翥醜？。翥本作䘄。干據反。見廣韵。卽周禮所謂蜡。三蒼所謂乳肉中也。"}]},"蘧":{"expl":"蘧麥也。从艸遽聲。","rad":"艸","fq":"彊魚切","vol":"01","py":"qú","duan":[{"e":"蘧麥也。","n":"三字一句。𥼶艸曰。大菊蘧麥。本艸謂之瞿麥。一名巨句麥。廣雅謂之紫萎。一名麥句薑。俗謂之洛陽花。一名石竹。"}]},"肙":{"expl":"小蟲也。从肉囗聲。一曰空也。","rad":"肉","fq":"烏玄切","vol":"04","py":"yuàn","duan":[{"e":"小蟲也。","n":"蟲部蜎下曰。肙也。考工記注云。謂若井中蟲蜎蜎。按井中孑子、蟲之至小者也。不獨井中有之。字從肉者、狀其耎也。從□者、象其首尾相接之狀也。"}]},"腐":{"expl":"爛也。从肉府聲。","rad":"肉","fq":"扶雨切","vol":"04","py":"fǔ","duan":[{"e":"爛也。","n":"上文云胹、爛也。爛之正義。此云腐、爛也。歹部云殨、爛也。爛之引伸之義。"}]},"肎":{"expl":"骨閒肉肎肎箸也。从肉，从冎省。一曰骨無肉也。","rad":"肉","fq":"苦等切","vol":"04","py":"kěn","duan":[{"e":"骨閒肉肎肎箸也。","n":"肎肎、附箸難解之皃。莊子說庖丁解牛曰。技經肯綮之未嘗。肯、崔引此解釋之。綮音罄。司馬云。猶結處也。按肎之言可也。故心所願曰肎。得其窾郤曰中肎。引伸之義也。"}]},"肥":{"expl":"多肉也。从肉从卪。","rad":"肉","fq":"符非切","vol":"04","py":"féi","duan":[{"e":"多肉也。从肉卪。","n":"鉉等曰。肉不可過多。故從卪。符非切。十五部。按各本此篆在部末。葢因奪落而補綴之也。今考定文理。必當廁此。與下文少肉反對。"}]},"䏿":{"expl":"肥腸也。从肉，啓省聲。","rad":"肉","fq":"康禮切","vol":"04","py":"qǐ","duan":[]},"脧":{"expl":"赤子陰也。从肉夋聲。或从血。","rad":"肉","fq":"子回切","vol":"04","py":"zuī","duan":[{"e":"赤子陰也。","n":"老子。未知牝牡之合而朘作。河上本如是。"}]},"腔":{"expl":"内空也。从肉从空，空亦聲。","rad":"肉","fq":"苦江切","vol":"04","py":"qiānɡ","duan":[]},"𦚧":{"expl":"𦚧䏰，蟲名。漢中有𦚧䏰縣，地下多此蟲，因以爲名。从肉旬聲。考其義，當作潤蠢。","rad":"肉","fq":"如順切","vol":"04","py":"rùn","duan":[]},"䏰":{"expl":"𦚧䏰也。从肉忍聲。","rad":"肉","fq":"尺尹切","vol":"04","py":"chǔn","duan":[]},"筋":{"expl":"肉之力也。从力从肉从竹。竹，物之多筋者。凡筋之屬皆从筋。","rad":"筋","fq":"居銀切","vol":"04","py":"jīn","duan":[{"e":"肉之力也。","n":"力下曰筋也。筋力同物。今人殊之耳。考工記故書筋或作薊。"}]},"菊":{"expl":"大菊，蘧麥。从艸匊聲。","rad":"艸","fq":"居六切","vol":"01","py":"jú","duan":[{"e":"大菊、","n":"逗。"}]},"䇟":{"expl":"筋之本也。从筋，从夗省聲。","rad":"筋","fq":"渠建切","vol":"04","py":"jiàn","duan":[{"e":"筋之本也。","n":"内則注曰。餌、筋腱也。王逸注招䰟曰。腱、筋頭也。餌篇、韵作䏪。"}]},"𥭖":{"expl":"手足指節鳴也。从筋省，勺聲。","rad":"筋","fq":"北角切","vol":"04","py":"bó","duan":[{"e":"手足指節鳴也。","n":"其聲膊膊然。"}]},"刀":{"expl":"兵也。象形。凡刀之屬皆从刀。","rad":"刀","fq":"都牢切","vol":"04","py":"dāo","duan":[{"e":"兵也。","n":"刀者、兵之一也。衞風假借爲𦩍字。"}]},"㓡":{"expl":"刀握也。从刀缶聲。","rad":"刀","fq":"方九切","vol":"04","py":"fǒu","duan":[{"e":"刀握也。","n":"謂握持處也。篇、韵皆云。㓡同弣。按弓把曰弣。考工記、少儀弣作拊。刀把曰㓡。少儀亦作拊。刀卻刃授穎。削授拊。注。穎、鐶也。拊謂把也。按穎近拊。拊近刃。故削外削内異其授。拊與㓡音相近。"}]},"㓵":{"expl":"刀劒刃也。从刀㖾聲。","rad":"刀","fq":"五各切","vol":"04","py":"è","duan":[{"e":"刀劒刃也。","n":"淮南脩務訓。摩其鋒？。王子淵聖主得賢臣頌、漢書作越砥斂其咢。文𨕖作鍔。"}]},"削":{"expl":"鞞也。一曰析也。从刀肖聲。","rad":"刀","fq":"息約切","vol":"04","py":"xuē","duan":[{"e":"鞞也。","n":"革部曰。鞞、刀室也。少儀曰。削授拊。史、漢貨殖傳曰。洒削。方言。劒削、自河而北燕趙之閒謂之室。自關而東或謂之廓。或謂之削。自關而西謂之𩏂。廓卽郭。𩏂卽鞞。今字作鞘。玄應曰。小爾雅作韒。"}]},"𠛎":{"expl":"鎌也。从刀句聲。","rad":"刀","fq":"古矦切","vol":"04","py":"ɡōu","duan":[{"e":"鎌也。","n":"𠛎亦作鉤。周禮雉氏。夏日至而夷之。注云。以鉤鎌迫地芟之也。方言曰。刈鉤、江淮陳楚之閒謂之鉊。音昭。或謂之鐹。音果。亦作划。自關而西或謂之鉤。或謂之鎌。或謂之鍥。音結。按鎌之屬。見於金部。"}]},"剴":{"expl":"大鎌也。一曰摩也。从刀豈聲。","rad":"刀","fq":"五來切","vol":"04","py":"ɡāi","duan":[{"e":"大鎌也。","n":"謂可切地芟刈也。金部曰。鉊、大鎌也。"}]},"剞":{"expl":"剞𠜾，曲刀也。从刀奇聲。","rad":"刀","fq":"居綺切","vol":"04","py":"jī","duan":[{"e":"剞𠜾、","n":"逗。"}]},"𠜾":{"expl":"剞𠜾也。从刀屈聲。","rad":"刀","fq":"九勿切","vol":"04","py":"jué","duan":[{"e":"剞𠜾也。","n":"二字雙聲。"}]},"葷":{"expl":"臭菜也。从艸軍聲。","rad":"艸","fq":"許云切","vol":"01","py":"hūn","duan":[{"e":"臭菜也。","n":"謂有气之菜也。士相見禮。夜侍坐。問夜膳。葷。請退可也。注。葷、辛物。葱薤之屬。食之以止臥。古文葷作薰。玉藻。膳於君有葷桃茢。注。葷、薑及辛菜也。葷或作焄。按儀禮注謂葱薤之屬爲辛物。卽禮記注所謂辛菜也。禮記注先以薑者。薑辛而不葷。金辛之臭腥。葱薤之屬皆辛而葷。實與薑同類也。葷古作薰。或作焄者。殠得名薰。猶治曰亂。祭義注。焄謂香臭也。"}]},"利":{"expl":"銛也。从刀。和然後利，从和省。《易》曰：“利者，義之和也。”","rad":"刀","fq":"力至切","vol":"04","py":"lì","duan":[{"e":"銛也。","n":"銛者、臿屬。引伸爲銛利字。銛利引伸爲凡利害之利。"}]},"剡":{"expl":"銳利也。从刀炎聲。","rad":"刀","fq":"以冉切","vol":"04","py":"yǎn","duan":[{"e":"銳利也。","n":"釋詁曰。剡、利也。毛詩假借覃爲之。大田曰。以我覃耜。毛曰。覃、利也。釋詁文也。按此二篆古本當作利剡也、剡利也。二字互訓。"}]},"初":{"expl":"始也。从刀从衣。裁衣之始也。","rad":"刀","fq":"楚居切","vol":"04","py":"chū","duan":[{"e":"始也。","n":"見釋詁。"}]},"剪":{"expl":"齊斷也。从刀歬聲。","rad":"刀","fq":"子善切","vol":"04","py":"jiǎn","duan":[{"e":"齊𣃔也。","n":"釋言、魯頌傳皆曰。翦、齊也。士喪禮。馬不齊髦。注云。齊、翦也。二字互訓。許必云齊𣃔者、爲其從刀也。其始前爲刀名。因爲𣃔物之名。𣃔物必齊。因爲凡齊等之偁。如實始翦商謂周之氣象始與商齊等。語本甚明。戈部引此詩作戩商。字之假借。如竹箭之爲竹晉也。前古假借作翦。召南毛傳曰翦去也是也。禮經蚤揃。假借揃爲之。又或爲鬋。今字作剪。俗。"}]},"則":{"expl":"等畫物也。从刀从貝。貝，古之物貨也。","rad":"刀","fq":"子德切","vol":"04","py":"zé","duan":[{"e":"等畫物也。","n":"等畫物者、定其差等而各爲介畫也。今俗云科則是也。介畫之、故從刀。引伸之爲法則。假借之爲語䛐。"}]},"剛":{"expl":"彊斷也。从刀岡聲。","rad":"刀","fq":"古郎切","vol":"04","py":"ɡānɡ","duan":[{"e":"彊𣃔也。","n":"彊者、弓有力也。有力而𣃔之也。周書所謂剛剋。引伸凡有力曰剛。"}]},"剬":{"expl":"斷齊也。从刀耑聲。","rad":"刀","fq":"旨兖切","vol":"04","py":"duān","duan":[{"e":"𣃔齊也。","n":"齊字衍。"}]},"劊":{"expl":"斷也。从刀會聲。","rad":"刀","fq":"古外切","vol":"04","py":"ɡuì","duan":[{"e":"𣃔也。","n":"易困九五。劓刖。困于赤紱。京房本作劓劊。按刖絕、劊𣃔。義正相同。今俗云劊子手。"}]},"切":{"expl":"刌也。从刀七聲。","rad":"刀","fq":"千結切","vol":"04","py":"qiē","duan":[{"e":"刌也。","n":"二字雙聲同義。古文禮刌肺。今文刌爲切。引伸爲迫切。又爲一切。俗讀七計切。師古曰。一切者、權時之事。如以刀切物。苟取整齊。不顧長短縱橫。故言一切。"}]},"刌":{"expl":"切也。从刀寸聲。","rad":"刀","fq":"倉本切","vol":"04","py":"cǔn","duan":[{"e":"切也。","n":"玉藻瓜祭上環注曰。上環、頭刌也。元帝紀分刌節度。"}]},"蘘":{"expl":"蘘荷也。一名葍蒩。从艸襄聲。","rad":"艸","fq":"汝羊切","vol":"01","py":"ránɡ","duan":[{"e":"蘘荷也。","n":"三字句。蘘荷見上林賦、劉向九歎、張衡南都賦、潘岳閒居賦。"}]},"㔎":{"expl":"斷也。从刀嶭聲。","rad":"刀","fq":"私列切","vol":"04","py":"xiè","duan":[{"e":"𣃔也。从刀。辥聲。","n":"私列切。十五部。"}]},"刉":{"expl":"劃傷也。从刀气聲。一曰斷也。又讀若㱯。一曰刀不利，於瓦石上刏之。","rad":"刀","fq":"古外切","vol":"04","py":"jī","duan":[{"e":"劃傷也。","n":"錐刀畫曰劃。周禮士師職凡刉珥。小子職作珥祈。祈或爲刉。肆師職作祈珥。祈或作幾。按鄭讀珥皆爲衈。云作刉衈爲正字。刉衈者、釁禮之事。用牲、毛者曰刉。羽者曰衈。小子衈於社稷。刉於五祀。謂始成其宫兆時也。襍記。雍人舉羊升屋。中屋南面。刲羊。血流于前。門、夾室皆用雞。其衈皆于屋下。割雞。門、當門。夾室、中室。是刉衈之事也。許云劃傷者正謂此。禮不主於殺之。但得其血涂祭而已。血部無衈字。葢許依經作珥。襍記注曰。衈謂將刲割牲以釁。先搣耳旁毛薦之。周禮注引公羊傳。叩其鼻以衈社。今公羊作血社。山海經。䎶用魚。傳引叩其鼻以䎶社。字又不同。䎶葢從神省、從耳。"}]},"劌":{"expl":"利傷也。从刀歲聲。","rad":"刀","fq":"居衛切","vol":"04","py":"ɡuì","duan":[{"e":"利傷也。","n":"聘義。廉而不劌。義也。注云。劌、傷也。按玉部作廉而不忮。毛公曰。忮、害也。是其義同也。利傷者、以芒刃傷物。"}]},"刻":{"expl":"鏤也。从刀亥聲。","rad":"刀","fq":"苦得切","vol":"04","py":"kè","duan":[{"e":"鏤也。","n":"金部曰。鏤、剛鐵可以刻鏤也。釋器曰。金謂之鏤。木謂之刻。此析言之。統言則刻亦鏤也。引伸爲刻覈、刻薄之刻。"}]},"副":{"expl":"判也。从刀畐聲。《周禮》曰：“副辜祭。”","rad":"刀","fq":"芳逼切","vol":"04","py":"pì","duan":[{"e":"判也。","n":"毛詩大雅曰。不坼不副。曲禮曰。爲天子削瓜者副之。匡繆正俗曰。副貳之字本爲福。從衣畐聲。俗呼一襲爲一褔衣是也。書史假借。遂以副字代之。副本音普力反。義訓剖劈。學者不知有褔字。以副貳爲正體。詩不坼不副。乃以朱點發副字。按顏說未盡然也。副之則一物成二。因仍謂之副。因之凡分而合者皆謂之副。訓詁中如此者致多。流俗語音如付。由一部入三部。故韵書在宥韵。俗語又轉入遇韵也。沿襲旣久。其義其音遂皆忘其本始。褔字雖見於龜策傳、東京賦。然恐此字因副而製耳。鄭仲師注周禮云。貳、副也。貝部貳下因之。史記曰。藏之名山。副在京師。漢書曰。臧諸宗廟。副在有司。周人言貳。漢人言副。古今語也。豈容廢副用褔。"}]},"剖":{"expl":"判也。从刀咅聲。","rad":"刀","fq":"浦后切","vol":"04","py":"pōu","duan":[{"e":"判也。","n":"史記曰。騶衍稱引天地剖判以來。"}]},"辧":{"expl":"判也。从刀辡聲。","rad":"刀","fq":"蒲莧切","vol":"04","py":"biàn","duan":[{"e":"判也。","n":"小宰傅別。故書作傅辨。朝士判書。故書判爲辨。大鄭辨讀爲別。古辨判別三字義同也。辧從刀。俗作辨。爲辨別字。符蹇切。別作從力之辦。爲幹辦字。蒲莧切。古辧別、幹辧無二義。亦無二形二音也。"}]},"判":{"expl":"分也。从刀半聲。","rad":"刀","fq":"普半切","vol":"04","py":"pàn","duan":[{"e":"分也。","n":"媒氏掌萬民之判。注。判、半也。得耦爲合。主合其半成夫婦也。朝士有判書以治則聽。注。判、半分而合者。"}]},"剫":{"expl":"判也。从刀度聲。","rad":"刀","fq":"徒洛切","vol":"04","py":"duó","duan":[]},"刳":{"expl":"判也。从刀夸聲。","rad":"刀","fq":"苦孤切","vol":"04","py":"kū","duan":[{"e":"判也。","n":"内則云。刲之刳之。按刲謂刺殺之。刳謂空其腹。𣪠辭刳木爲舟。亦謂虛木之中。刳木一作挎木。鄉飮酒禮。相者二人。皆左何瑟。後首挎越内弦。賈公彥曰。瑟底有孔越。以指深入而持之也。手部無挎。"}]},"菁":{"expl":"韭華也。从艸青聲。","rad":"艸","fq":"子盈切","vol":"01","py":"jīnɡ","duan":[{"e":"韭華也。","n":"周禮。菁菹。先鄭曰。菁菹、韭華菹也。今各本脫華字。則何以別於上文之韭菹乎。廣雅曰。韭其華謂之菁。若南都賦曰秋韭冬菁、則是二物。史游所云老菁冬日藏也。"}]},"列":{"expl":"分解也。从刀𡿪聲。","rad":"刀","fq":"良薛切","vol":"04","py":"liè","duan":[{"e":"分解也。","n":"列之本義爲分解。故其字從刀。齒分骨之？從列。引伸爲行列之義。古假借烈爲列。如鄭風火烈具舉。毛曰烈、列也是也。羽獵賦。舉？烈火。烈亦與列同。"}]},"刊":{"expl":"剟也。从刀干聲。","rad":"刀","fq":"苦寒切","vol":"04","py":"kān","duan":[{"e":"剟也。","n":"柞氏。夏日至。令刊陽木而火之。注。刊謂斫去次地之皮也。按凡有所削去謂之刊。故刻石謂之刊石。此與木部栞音同義異。唐衞包乃改栞爲刊。誤認爲一字也。"}]},"剟":{"expl":"刊也。从刀叕聲。","rad":"刀","fq":"陟劣切","vol":"04","py":"zhuō","duan":[{"e":"刊也。","n":"商子曰。有敢剟定法令者死。賈誼傳曰。盜者剟寢戸之簾。"}]},"刪":{"expl":"剟也。从刀、冊。冊，書也。","rad":"刀","fq":"所姦切","vol":"04","py":"shān","duan":[{"e":"剟也。","n":"凡言刪剟者、有所去卽有所取。如史記司馬相如傳曰。故刪取其要。歸正道而論之。刪取猶節取也。謂去其侈靡過實。非義理所尚。取其天子芒然而思已下也。旣錄其全賦矣。謂之刪取何也。言錄賦之意在此不在彼也。藝文志曰。今刪其要以備篇籍。刪其要謂取其要也。不然。豈劉歆七略之要孟堅盡刪去之乎。詳言之則如律曆志曰刪其僞辭、取其義者箸於篇。約言之則如相如傳、藝文志。"}]},"劈":{"expl":"破也。从刀辟聲。","rad":"刀","fq":"普擊切","vol":"04","py":"pì","duan":[{"e":"破也。","n":"此字義與副近而不同。今字用劈爲副。劈行而副廢矣。劈與副古經有相通者。大宗伯疈辜祭。疈在一部。故書疈爲罷。大鄭釋爲披磔牲以祭。罷披破同十七部。劈在十六部。此其音義相通之證也。考工記假薜爲劈。注云。薜、破裂也。又或假擘爲之。張衡賦云分肌擘理是也。"}]},"剝":{"expl":"裂也。从刀从录。录，刻割也。录亦聲。","rad":"刀","fq":"北角切","vol":"04","py":"bō","duan":[{"e":"裂也。","n":"衣部曰。裂、繒餘也。謂？破也。夏小正。二月剝鱓。以爲𡔷也。八月剝瓜。畜瓜之時也。剝棗。剝也者、取也。栗零。零也者、降也。零而後取之。故不言剝也。按剝鱓者、謂殘其皮。剝瓜棗者、謂殘其實。其用一也。皮部曰。剝取獸革。與剝鱓合。孔子易傳曰。致飾。然後通則盡矣。故受之以剝。剝者、剝也。物不可以終盡。剝竆上反下。故受之以復也。按此是剝訓盡。裂則將盡矣。豳風假剝爲攴。八月剝棗。毛曰。剝、擊也。音義云。普⺊反。故知剝同攴也。小正傳云取。毛傳云擊。此後人訓詁必密於前人也。"}]},"割":{"expl":"剥也。从刀害聲。","rad":"刀","fq":"古達切","vol":"04","py":"ɡē","duan":[{"e":"剝也。","n":"蒙剝之弟二義互訓。割謂殘破之。釋言曰。葢割裂也。尚書多假借割爲害。古二字音同也。釋言舍人本葢作害。明害與割同也。鄭注緇衣曰。割之言葢也。明葢與割同也。"}]},"剺":{"expl":"剥也。劃也。从刀𠩺聲。","rad":"刀","fq":"里之切","vol":"04","py":"lí","duan":[{"e":"剝也。","n":"方言。劙、解也。劙與剺雙聲義近。"}]},"劃":{"expl":"錐刀曰劃。从刀从畫，畫亦聲。","rad":"刀","fq":"呼麥切","vol":"04","py":"huá","duan":[{"e":"錐刀畫曰劃。","n":"畫字各本無。今補。謂錐刀之末所畫謂之劃也。上文云刉劃傷也、剺劃也皆是也。"}]},"剈":{"expl":"挑取也。从刀肙聲。一曰窐也。","rad":"刀","fq":"烏玄切","vol":"04","py":"yuān","duan":[{"e":"挑取也。","n":"抉而取之也。挑、抉也。今俗云剜。許書無剜字。"}]},"蘆":{"expl":"蘆菔也。一曰薺根。从艸盧聲。","rad":"艸","fq":"落乎切","vol":"01","py":"lú","duan":[{"e":"蘆菔也。一曰薺根。","n":"此字義別說。謂薺根謂之蘆也。"}]},"劀":{"expl":"刮去惡創肉也。从刀矞聲。《周禮》曰：“劀殺之齊。”","rad":"刀","fq":"古鎋切","vol":"04","py":"ɡuā","duan":[{"e":"𠜜去惡創肉也。","n":"瘍醫。掌腫瘍、潰瘍、金瘍、㪿瘍之祝藥劀殺之齊。鄭云。劀、𠜜去膿血。殺謂以藥食其惡肉。與許異。𠜜劀爲曡韵。"}]},"劑":{"expl":"齊也。从刀从齊，齊亦聲。","rad":"刀","fq":"在詣切","vol":"04","py":"jì","duan":[{"e":"齊也。","n":"釋言。劑、翦齊也。按周禮或言質劑。或言約劑。鄭訓劑爲券書。大鄭曰。質劑謂市中平價。今時月平是也。鄭云長券曰質。短券曰劑。是劑所以齊物也。周禮又多用齊字。亨人注。齊多少之量。此與劑義不同。今人藥劑字乃周禮之齊字也。"}]},"刷":{"expl":"刮也。从刀，㕞省聲。《禮》：“布刷巾。”","rad":"刀","fq":"所劣切","vol":"04","py":"shuā","duan":[{"e":"𠜜也。","n":"刷與㕞別。又部曰。㕞、飾也。巾部曰。飾、㕞也。飾今拭字。拭用手用巾。故從又巾。刷者、掊杷也。掊杷必用除穢之器如刀然。故字從刀。艸部曰。䓛刷也是也。"}]},"刮":{"expl":"掊把也。从刀𠯑聲。","rad":"刀","fq":"古八切","vol":"04","py":"ɡuā","duan":[{"e":"掊杷也。","n":"杷各本作把。誤。手部曰。掊、杷也。木部曰。杷、收麥器。凡掊地如杷麥然。故絫言之曰掊杷。考工記故書捖摩之工。大鄭捖讀爲刮。"}]},"剽":{"expl":"砭刺也。从刀𤐫聲。一曰剽，劫人也。","rad":"刀","fq":"匹妙切","vol":"04","py":"piào","duan":[{"e":"砭刺也。","n":"謂砭之、刺之皆曰剽也。砭者、以石刺病也。刺者、直傷也。砭刺必用其器之末。因之凡末謂之剽。莊子謂本末爲本剽。素問有標本病傳論。標亦末也。"}]},"刲":{"expl":"刺也。从刀圭聲。《易》曰：“士刲羊。”","rad":"刀","fq":"苦圭切","vol":"04","py":"kuī","duan":[{"e":"刺也。","n":"馬、虞說易同。"}]},"剉":{"expl":"折傷也。从刀坐聲。","rad":"刀","fq":"麤臥切","vol":"04","py":"cuò","duan":[{"e":"折傷也。","n":"剉與手部挫音同義近。考工記。揉牙内不挫。注。挫、折也。是二字通用也。經史剉折字多作挫。按今俗謂䥨爲剉。乃錯之聲誤耳。說文作厝。"}]},"劋":{"expl":"絕也。从刀喿聲。《周書》曰：“天用劋絕其命。”","rad":"刀","fq":"子小切","vol":"04","py":"jiǎo","duan":[{"e":"絕也。","n":"夏書甘誓。天用劋絕其命。天寶巳前本如是。釋文曰劋子六反。玉篇子小反。馬本作剿。宋開寶巳前本如是。今玉篇劋子小切。絕也。剿同上。此顧希馮之舊也。自衞包改劋爲勦。以刀部訓絕之字。改爲力部訓勞之字。於是五經文字力部曰。勦見禮記。又見夏書。而刀部反無剿字。開寶中改釋文劋爲勦、剿爲巢。羣經音辨、集韵等皆云勦、絕也。重紕貤繆。莫能諟正。葢衞包當日改劋爲從刀之剿猶可說也。改爲從力之勦則不可說矣。王莽傳。郭欽封劋胡子。又詔曰。將遣大司空征伐劋絕之矣。此用夏書也。外戚傳。命樔絕而不長。此假借字也。說文水部？、讀若夏書天用勦絕。此必淺人以衞包本改之也。曲禮。毋剿說。字從刀、不從力。"}]},"刖":{"expl":"絕也。从刀月聲。","rad":"刀","fq":"魚厥切","vol":"04","py":"yuè","duan":[{"e":"絕也。","n":"凡絕皆偁刖。故㓷下云刖鼻也。刖足則爲跀。周禮刖者使守囿。此是假刖爲跀。困九五。劓刖。京房作劓劊。說文劊與刖義同。"}]},"刜":{"expl":"擊也。从刀弗聲。","rad":"刀","fq":"分勿切","vol":"04","py":"fú","duan":[{"e":"擊也。","n":"左傳。苑子刜林雍。𣃔其足。齊語。刜令支。"}]},"菔":{"expl":"蘆菔。似蕪菁，實如小尗者。从艸服聲。","rad":"艸","fq":"蒲北切","vol":"01","py":"fú","duan":[{"e":"蘆菔。佀蕪菁。實如小尗者。","n":"今之蘿蔔也。釋艸。葖蘆萉。郭云。萉當爲菔。蘆菔、蕪菁屬。紫花大根。一名葖。俗呼雹葖。按實根駭人。故呼突。或加艸耳。蕪菁卽蔓菁。"}]},"㓼":{"expl":"傷也。从刀桼聲。","rad":"刀","fq":"親結切","vol":"04","py":"chì","duan":[{"e":"傷也。","n":"？下曰蹏皮可以割桼。桼疑㓼之誤。割㓼絫言之也。廣雅曰。㓼、割也。測紀切。"}]},"劖":{"expl":"斷也。从刀毚聲。一曰剽也，釗也。","rad":"刀","fq":"鉏銜切","vol":"04","py":"chán","duan":[{"e":"𣃔也。","n":"與金部鑱義略近。"}]},"刓":{"expl":"剸也。从刀元聲。一曰齊也。","rad":"刀","fq":"五丸切","vol":"04","py":"wán","duan":[{"e":"剸也。","n":"剸當作團。團圜也。通俗文曰。𣃔𢧵曰剸。非其訓也。且許書本無剸字。韓信傳。刻印刓忍不能予。蘇林曰。刓音刓角之刓。與摶同。手弄角訛。不忍授也。按正文當本是同酈食其傳作玩。故蘇以手弄角訛釋之。訛當作鈋。見金部。刓、齊物論作园。"}]},"釗":{"expl":"刓也。从刀从金。周康王名。","rad":"刀","fq":"止遙切","vol":"04","py":"zhāo","duan":[{"e":"刓也。","n":"未聞。"}]},"制":{"expl":"裁也。从刀从未。未，物成有滋味，可裁斷。一曰止也。","rad":"刀","fq":"征例切","vol":"04","py":"zhì","duan":[{"e":"裁也。","n":"衣部曰。裁、製衣也。製、裁衣也。此裁之本義。此云制、裁也。裁之引伸之義。古多假折爲制。吕㓝。制以㓝。墨子引作折則㓝。魯論。片言可以制獄。古作折獄。羽獵賦。不制中以泉臺。制或爲折。又吕㓝。折民惟㓝。四八目引作制民。"}]},"㓠":{"expl":"缺也。从刀占聲。《詩》曰：“白圭之㓠。”","rad":"刀","fq":"丁念切","vol":"04","py":"diàn","duan":[{"e":"缺也。","n":"大雅抑詩。白圭之玷。毛曰。玷、缺也。箋云。玉之缺尚可磨鑢而平。按㓠玷古今字。"}]},"𠟟":{"expl":"辠之小者。从刀从詈。未以刀有所賊，但持刀罵詈，則應罰。","rad":"刀","fq":"房越切","vol":"04","py":"fá","duan":[{"e":"辠之小者。","n":"辠、犯法也。罰爲犯法之小者。㓝爲罰辠之重者。五罰輕於五㓝。"}]},"刵":{"expl":"斷耳也。从刀从耳。","rad":"刀","fq":"仍吏切","vol":"04","py":"èr","duan":[{"e":"𣃔耳也。","n":"刵見康誥、吕㓝。五㓝之外有刵。軍戰則不服者殺而獻其左耳曰聝。周禮田獵取禽左耳以效功曰珥。"}]},"㓷":{"expl":"刑鼻也。从刀臬聲。《易》曰：“天且㓷。”","rad":"刀","fq":"魚器切","vol":"04","py":"yì","duan":[{"e":"刖鼻也。","n":"刖、絕也。周禮注曰𢧵鼻。"}]},"刑":{"expl":"剄也。从刀幵聲。","rad":"刀","fq":"戶經切","vol":"04","py":"xínɡ","duan":[{"e":"剄也。","n":"按㓝者、五㓝也。凡㓝罰、典㓝、儀㓝皆用之。𠛬者、剄頸也。橫絕之也。此字本義少用。俗字乃用𠛬爲㓝罰、典㓝、儀㓝字。不知造字之恉旣殊。丼聲、幵聲各部。凡丼聲在十一部。凡幵聲在十二部也。"}]},"苹":{"expl":"蓱也。無根，浮水而生者。从艸平聲。","rad":"艸","fq":"符兵切","vol":"01","py":"pínɡ","duan":[{"e":"蓱也。無根浮水而生者。","n":"小雅。呦呦鹿鳴。食野之苹。傳曰。苹、蓱也。釋草苹字㒳出。一曰蓱。一曰藾蕭。鄭箋以水中之艸非鹿所食。易之曰苹、藾蕭也。於月令曰蓱、萍也。於周禮萍氏引爾雅萍蓱。似分別萍爲水艸、苹爲藾蕭。鄭所據爾雅自作萍蓱。而毛詩、夏小正以苹爲萍。皆屬叚借。許君則苹蓱萍三字同物。不謂苹爲叚借。○李善注高唐賦引說文。苹苹、艸皃。音平。"}]},"剄":{"expl":"刑也。从刀坙聲。","rad":"刀","fq":"古零切","vol":"04","py":"jǐnɡ","duan":[{"e":"𠛬也。","n":"耳部曰。小罪聅。中罪刖。大罪剄。剄謂𣃔頭也。左傳。越句踐使罪人三行。屬劒於頸而辭曰。臣不敢逃㓝。敢歸死。遂自剄也。吳師屬之目。剄、經典釋文宋刻作頸。非也。按許意剄謂𣃔頸。㓝之至重者也。"}]},"𠟃":{"expl":"減也。从刀尊聲。","rad":"刀","fq":"兹損切","vol":"04","py":"zǔn","duan":[{"e":"減也。","n":"𠟃撙古今字。葢？變也。曲禮。恭敬撙節退讓以明禮。注。撙猶趨也。按趨同趣、疾也。當音促。非趨走之趨。戰國策。伏軾撙銜。集韵曰。撙、挫也。"}]},"魝":{"expl":"楚人謂治魚也。从刀从魚。讀若鍥。","rad":"刀","fq":"古屑切","vol":"04","py":"jié","duan":[{"e":"楚人謂治魚也。","n":"楚語也。"}]},"券":{"expl":"契也。从刀𢍏聲。券別之書，以刀判契其旁，故曰契券。","rad":"刀","fq":"去願切","vol":"04","py":"quàn","duan":[{"e":"契也。","n":"小宰。官府之八成。大鄭曰。稱責謂貣予。傅別謂券書。聽訟責者以券書決之。傅、傅箸約束於文書。別、別爲兩。兩家各得一也。書契、符書也。質劑謂市中平價、今月平是也。後鄭曰。傅別謂爲大手書於一札。中字別之。書契謂出子受入之凡要。凡簿書之冣目、獄訟之要辭皆曰契。春秋傳曰。王叔氏不能舉其契。質劑謂兩書一札、同而別之。長曰質。短曰劑。質劑皆今之券書也。按云今之券書者、謂漢時名券書。其實券字自古有之也。大部曰。契、大約也。引易𣪠辭書契。"}]},"刺":{"expl":"君殺大夫曰刺。刺，直傷也。从刀从朿，朿亦聲。","rad":"刀","fq":"七賜切","vol":"04","py":"cì","duan":[{"e":"君殺大夫曰刺。刺、直傷也。","n":"刺篆疑非舊次。刺、直傷也。當爲正義。君殺大夫曰刺。當爲別一義。辭之先後今又倒亂矣。上文剽砭刺也、刲刺也皆直傷之義。然則刺篆當廁剽刲二篆下。禮經云刺草、大雅之刺訓責、史稱刺六經作王制、官稱刺史、鏚黹曰刺繡、用㰏曰刺船、盜取國家密事爲刺探尚書事皆其引伸之義也。一曰君殺大夫曰刺者、春秋僖二十八年。公子買戍衞。不卒戍。刺之。成十六年。刺公子偃。公羊傳曰。刺之者何。殺之也。内諱殺大夫。謂之刺之也。考諸周禮司刺。掌三刺之法。壹刺曰訊羣臣。再刺曰訊羣吏。三刺曰訊萬民。注。刺、殺也。訊而有罪則殺之。然則春秋於他國書殺其大夫。於魯國則兩書刺。諱魯之專殺而謂之刺。謂其當罪合於周禮。公羊内諱之說是矣。此云君殺大夫曰"}]},"剔":{"expl":"解骨也。从刀易聲。","rad":"刀","fq":"他歴切","vol":"04","py":"tī","duan":[]},"刎":{"expl":"剄也。从刀勿聲。","rad":"刀","fq":"武粉切","vol":"04","py":"wěn","duan":[]},"剜":{"expl":"削也。从刀宛聲。","rad":"刀","fq":"一丸切","vol":"04","py":"wān","duan":[]},"劇":{"expl":"尤甚也。从刀，未詳。豦聲。","rad":"刀","fq":"渠力切","vol":"04","py":"jí","duan":[]},"刹":{"expl":"柱也。从刀，未詳。殺省聲。","rad":"刀","fq":"初轄切","vol":"04","py":"chà","duan":[]},"齋":{"expl":"戒，潔也。从示，齊省聲。","rad":"示","fq":"側皆切","vol":"01","py":"zhāi","duan":[{"e":"戒絜也。","n":"祭統曰。齋之爲言齊也。齊不齊以致齊者也。齋戒或析言。如七日戒、三日齋是。此以戒訓齋者、統言則不別也。"}]},"茞":{"expl":"艸也。从艸臣聲。","rad":"艸","fq":"稹鄰切","vol":"01","py":"chén","duan":[{"e":"艸也。","n":"謂艸名。"}]},"刃":{"expl":"刀堅也。象刀有刃之形。凡刃之屬皆从刃。","rad":"刃","fq":"而振切","vol":"04","py":"rèn","duan":[{"e":"刀鋻也。","n":"鋻各本作堅。今正。刀部曰。？、刀劎刃也。金部曰。鋻、？也。郭璞三倉解詁曰。焠作刀鋻也。"}]},"刅":{"expl":"傷也。从刃从一。","rad":"刃","fq":"楚良切","vol":"04","py":"chuānɡ","duan":[{"e":"傷也。","n":"凡殺傷必以刃。"}]},"劒":{"expl":"人所帶兵也。从刃僉聲。","rad":"刃","fq":"居欠切","vol":"04","py":"jiàn","duan":[{"e":"人所帶兵也。","n":"桃氏爲劒。有上制。有中制。有下制。注云。此今之匕首也。人各以其形皃大小帶之。"}]},"㓞":{"expl":"巧㓞也。从刀丯聲。凡㓞之屬皆从㓞。","rad":"㓞","fq":"恪入切","vol":"04","py":"qià","duan":[{"e":"巧㓞也。","n":"巧㓞葢漢人語。"}]},"𠜵":{"expl":"齘𠜵，刮也。从㓞夬聲。一曰𠜵，畫堅也。","rad":"㓞","fq":"古黠切","vol":"04","py":"jiá","duan":[{"e":"齘𠜵、","n":"逗。曡韵。"}]},"栔":{"expl":"刻也。从㓞从木。","rad":"㓞","fq":"苦計切","vol":"04","py":"qì","duan":[{"e":"刻也。","n":"釋詁。契滅殄絕也。唐韵引作栔。郭云。今江東呼刻𣃔物爲栔𣃔。按古經多作契。假借字也。大雅。爰契我龜。毛曰。契、開也。周禮亦作契。左傳。盡借邑人之車。契其軸。爾雅音義所引如是。今左傳、荀子作鍥。漢書注引綿詩作挈。大戴禮。楔而舍之。朽木不折。皆假借字也。晉虞溥傳作㓶。俗字也。"}]},"丯":{"expl":"艸蔡也。象艸生之𢿱亂也。凡丯之屬皆从丯。讀若介。","rad":"丯","fq":"古拜切","vol":"04","py":"jiè","duan":[{"e":"艸蔡也。","n":"艸部曰。蔡、艸丯也。曡韵互訓。孟子曰。君之視臣如土芥。趙云。芥、草芥也。左傳。以民爲土芥。杜注同。方言。蘇芥草也。江淮南楚之閒曰蘇。自關而西或曰草、或曰芥。南楚江湘之閒謂之莽。按凡言艸芥皆丯之假借也。芥行而丯廢矣。"}]},"𠲱":{"expl":"枝𠲱也。从丯各聲。","rad":"丯","fq":"古百切","vol":"04","py":"ɡé","duan":[{"e":"枝𠲱也。","n":"枝𠲱者、遮禦之意。玉篇曰。𠲱、枝柯也。釋名。戟、格也。旁有枝格也。庾信賦。草樹溷淆。枝格相交。格行而𠲱廢矣。"}]},"耒":{"expl":"手耕曲木也。从木推丯。古者垂作耒㭒以振民也。凡耒之屬皆从耒。","rad":"耒","fq":"盧對切","vol":"04","py":"lěi","duan":[{"e":"耕曲木也。","n":"各本耕上有手。今依廣韵隊韵、周易音義正。下文云。耕、犁也。謂犁之曲木也。禮記音義引字林亦云耕曲木。考工記。車人爲耒。庛長尺有一寸。中直者三尺有三寸。上句者二尺有二寸。自其庛緣其外。以至於首。以弦其内。六尺有六寸。注云。庛讀爲棘刺之刺。刺耒下前曲接耜。緣外六尺有六寸。内弦六尺。應一步之尺數。按經多云耒耜。據鄭說耒以木。耜以金。沓於耒刺。京房云。耜、耒下耓也。耒、耜上句木也。許木部耜作枱。耒耑也。耕犁也。許說與京同。與鄭異。鄭本匠人。謂犁爲耜。統言之也。許分別金謂之犁。木謂之枱。析言之也。"}]},"耕":{"expl":"犂也。从耒井聲。一曰古者井田。","rad":"耒","fq":"古莖切","vol":"04","py":"ɡēnɡ","duan":[{"e":"𤛿也。","n":"牛部曰。𤛿、耕也。人用以發土。亦謂之耕。"}]},"薲":{"expl":"大蓱也。从艸賓聲。","rad":"艸","fq":"符眞切","vol":"01","py":"pín","duan":[{"e":"大蓱也。","n":"釋艸曰。苹、蓱、其大者蘋。毛傳曰。蘋、大蓱也。薲蘋古今字。"}]},"耦":{"expl":"耒廣五寸爲伐，二伐爲耦。从耒禺聲。","rad":"耒","fq":"五口切","vol":"04","py":"ǒu","duan":[{"e":"耕廣五寸爲伐。二伐爲耦。","n":"耕各本作耒。今依太平御覽正。匠人。耜廣五寸。二耜爲耦。一耦之伐。廣尺深尺。謂之𤰝。注。古者耜一金兩人倂發之。其壟中曰𤰝。𤰝土曰伐。伐之言發也。𤰝、畎也。今之耜岐頭兩金。象古之耦也。許與記文辭異義同。耕卽耜。謂犂之金其廣五寸也。不曰枱廣五寸者、許所枱乃耒本之耑。耕錔於枱。故必析言之。長沮、桀溺耦而耕。此兩人倂發之證。引伸爲凡人耦之偁。俗借偶。"}]},"耤":{"expl":"帝耤千畝也。古者使民如借，故謂之耤。从耒昔聲。","rad":"耒","fq":"秦昔切","vol":"04","py":"jí","duan":[{"e":"帝耤千畞也。","n":"帝耤見月令。周禮甸師。掌帥其屬而耕耨王藉。以時入之。以共？盛。禮記曰。天子爲藉千畞。冕而朱紘。躬秉耒以事天地山川社稷先古。"}]},"𦓯":{"expl":"冊又（段注作卌㕚），可以劃麥，河内用之。从耒圭聲。","rad":"耒","fq":"古攜切","vol":"04","py":"ɡuī","duan":[{"e":"卌㕚可㠯劃麥。河内用之。","n":"卌、今刻大徐本作？。鍇本及集韵皆作冊。集韵所據鉉本未誤也。冊當是卌之譌。今定作卌。卌者、數之積也。見？下。漢石經以爲四十字。㕚、鉉作叉。鍇作又。今定作㕚。㕚者、手甲也。今字作爪。卌㕚可以劃麥。卽今俗用麥杷也。木部曰。杷、收麥器也。謂之卌㕚者。言其多爪可掊杷也。廣韵曰。卌先立切。字統云。插糞杷。說文云數名。此卌字之證。插糞者、抹摋糞除之言。據廣韵則十部當有卌篆。方言曰。杷、宋魏之閒謂之渠挐。或謂之渠疏。釋名曰。齊魯閒謂四齒杷爲欋。然則河内謂之？也。"}]},"𦔐":{"expl":"除苗閒穢也。从耒員聲。","rad":"耒","fq":"羽文切","vol":"04","py":"yún","duan":[{"e":"除苗閒穢也。","n":"穢當作薉。艸部薉、蕪也。無穢字。小雅毛傳曰。耘、除草也。耔、雝本也。食貨志云。播種於畎中。苗生三葉以上。稍耨壠草。因？其土以附苗根。比成壠盡而根深。能風與旱。故薿薿而盛也。按此古者𦔐耔爲一事也。謂苗初生之始也。旣成已後仍有莠及童蓈生乎其閒。蓐下所云陳艸復生也。則又以槈薅之。薅者、披田艸也。亦謂之𦔐。吕覽云。其耨六寸。所以閒稼也。注云。耨所以耘苗。刃廣六寸。所以入苗閒。○又按吕覽云。六尺之耜。所以成畞也。謂六尺爲步。步百爲畞。卽車人爲耒。所謂弦其内與步相中也。又云。其博八寸。所以成畎也。八寸者、周之一尺。見夫部、尺部。卽匠人所謂一耦之伐廣尺也。又云。耨柄尺。此其度也。謂耨柄之尺寸以耒六尺爲度也。"}]},"耡":{"expl":"商人七十而耡。耡，耤稅也。从耒助聲。《周禮》曰：“以興耡利萌。”","rad":"耒","fq":"牀倨切","vol":"04","py":"chú","duan":[{"e":"殷人七十而耡。","n":"孟子滕文篇文。今孟子作助。周禮注引作莇。"}]},"角":{"expl":"獸角也。象形，角與刀、魚相似。凡角之屬皆从角。","rad":"角","fq":"古岳切","vol":"04","py":"jiǎo","duan":[{"e":"獸角也。","n":"人體有偁角者。如日月角、角犀豐盈之類。要是假借之辭耳。"}]},"䚭":{"expl":"揮角皃。从角雚聲。梁𨻳縣有䚭亭，又讀若𦄑。","rad":"角","fq":"況袁切","vol":"04","py":"xuān","duan":[{"e":"揮角皃。","n":"揮䚭𩀱聲。"}]},"觻":{"expl":"角也。从角樂聲。張掖有觻得縣。","rad":"角","fq":"盧谷切","vol":"04","py":"lù","duan":[{"e":"角也。","n":"按尋立文之例。角下當奪一字。廣韵、集韵錫韵皆曰。觻、角鋒也。"}]},"䚡":{"expl":"角中骨也。从角思聲。","rad":"角","fq":"穌來切","vol":"04","py":"sāi","duan":[{"e":"角中骨也。","n":"骨當作肉。字之誤也。鄭注樂記角觡生曰。無䚡曰觡。謂角中堅實無肉者。麋鹿是也。許亦解觡爲骨角。亦謂中無肉者也。本艸經。牛角䚡下閉血、瘀血、瘀痛、女人帶下血。此則謂角之中、角之本當中有肉之處。外有文理可觀。故陳藏器曰。久在糞土爛白者佳。玉部曰。䚡理自外可以知中。引伸謂凡物之文理也。"}]},"觠":{"expl":"曲角也。从角𢍏聲。","rad":"角","fq":"巨員切","vol":"04","py":"quán","duan":[{"e":"曲角也。","n":"釋嘼曰。角三觠羷。吕、郭音權。謝居轉反。"}]},"藍":{"expl":"染青艸也。从艸監聲。","rad":"艸","fq":"魯甘切","vol":"01","py":"lán","duan":[{"e":"染靑艸也。","n":"小雅傳曰。藍、染艸也。"}]},"觬":{"expl":"角觬曲也。从角兒聲。西河有觬氏縣。","rad":"角","fq":"斫啓切","vol":"04","py":"ní","duan":[{"e":"角觬曲也。","n":"篇、韵皆云角不正。"}]},"觢":{"expl":"一角仰也。从角㓞聲。《易》曰：“其牛觢。”","rad":"角","fq":"尺制切","vol":"04","py":"shì","duan":[{"e":"一角仰也。","n":"一當作二。釋嘼曰。角一俯一仰、觭。皆踊、觢。皆踊謂二角皆豎也。蒙上文一俯一仰故曰皆。許一俯一仰之云在下文。故云二角。俗譌爲一。則與觭無異。易音義引說文。以角一俯一仰系之觢。當時筆誤耳。睽六三。其牛掣。鄭作㸷。云牛角皆踊曰㸷。與爾雅、說文同。子夏作契。荀作觭。虞作掣。皆以一俯一仰爲訓。與許、鄭不同也。觢者、如有掣曳然。角本當邪展而乃聳直也。虞本當同荀作觭。李氏鼎祚正文作掣。遂比而同之耳。"}]},"䚦":{"expl":"角傾也。从角虒聲。","rad":"角","fq":"敕豕切","vol":"04","py":"zhì","duan":[{"e":"角傾也。从角。虒聲。","n":"敕豕切。十五部。"}]},"觭":{"expl":"角一俛一仰也。从角奇聲。","rad":"角","fq":"去奇切","vol":"04","py":"qī","duan":[{"e":"角一俛一仰也。","n":"荀易。其牛觭。按子夏傳作契。云一角仰也。虞作掣。云牛角一低一仰。是子夏、虞皆作觭也。觭者、奇也。奇者、異也。一曰不耦也。故其字從奇。公羊傳。匹馬𨾏輪無反者。榖梁作倚輪。漢五行志作觭輪。此不耦之義之引伸也。周禮觭夢。杜子春讀爲奇偉。此異義之引伸也。"}]},"觓":{"expl":"角皃。从角丩聲。《詩》曰：“兕觵其觓。”","rad":"角","fq":"渠幽切","vol":"04","py":"qiú","duan":[{"e":"角皃。","n":"周頌。有捄其角。傳云。社稷之牛角尺。箋云。捄、角皃。捄者、觓之假借字也。小雅桑扈。兕觥其觓。俗作觩。"}]},"𧤖":{"expl":"角曲中也。从角畏聲。","rad":"角","fq":"烏賄切","vol":"04","py":"wēi","duan":[{"e":"角曲中也。","n":"考工記曰。夫角之中。恆當弓之畏。畏也者必橈。杜子春讀畏爲威。威謂弓淵。鄭讀畏如秦師入隈之隈。按大射儀弓淵字作隈。鄭讀從之也。弓之中曰畏。角之中曰？。皆其曲處。而弓人必以？傅於畏。故記曰恆當。"}]},"𧢼":{"expl":"角長皃。从角爿聲。","rad":"角","fq":"士角切","vol":"04","py":"zhuó","duan":[{"e":"角長皃。","n":"按此字見於經史者皆譌爲觕。從牛角。公羊傳曰。觕者曰侵。精者曰伐。何曰觕、麤也。公羊隱元年注曰。用心尚麤觕。漢藝文志曰。庶得麤觕。以麤觕連文。則觕非麤字也。麤觕若今人曰粗糙。雙聲字也。𧢼從爿聲。古葢讀如倉。轉寫譌其形作觕。其音讀才古反。又或讀七奴反矣。其義則本訓角長。引伸之爲鹵莽之意。因之觕與精爲對文。月令。其器高以粗。吕覽粗作觕。"}]},"𧤼":{"expl":"角有所觸發也。从角厥聲。","rad":"角","fq":"居月切","vol":"04","py":"jué","duan":[{"e":"角有所觸發也。","n":"厂部曰。厥、發石也。此字從角厥。謂獸以角有所觸發。西都賦曰。竆虎奔突。狂兕觸蹷。蹷者、𧤼之假借。孟子曰。厥角稽首。趙曰。叩頭以頟角犀撅地也。按厥角二字皆假借之言。"}]},"觸":{"expl":"抵也。从角蜀聲。","rad":"角","fq":"尺玉切","vol":"04","py":"chù","duan":[{"e":"牴也。","n":"牛部曰。牴、觸也。"}]},"觲":{"expl":"用角低仰便也。从羊、牛、角。《詩》曰：“觲觲角弓。”","rad":"角","fq":"息營切","vol":"04","py":"xīnɡ","duan":[{"e":"用角低仰便也。","n":"小雅。騂騂角弓。毛曰。騂騂、調利也。按毛意謂角弓張弛便易。許意謂獸之舉角高下馴擾。毛說正許說之引伸也。"}]},"藼":{"expl":"令人忘憂艸也。从艸憲聲。《詩》曰：“安得藼艸？”","rad":"艸","fq":"況袁切","vol":"01","py":"xuān","duan":[{"e":"令人忘憂之艸也。","n":"見毛傳。藼之言諼也。諼、忘也。"}]},"䚗":{"expl":"舉角也。从角公聲。","rad":"角","fq":"古雙切","vol":"04","py":"ɡānɡ","duan":[{"e":"舉角也。","n":"假借爲扛字。魏大饗碑上索蹹高䚗鼎緣橦、西京賦烏獲？鼎是也。？亦䚗字。"}]},"觷":{"expl":"治角也。从角，學省聲。","rad":"角","fq":"胡角切","vol":"04","py":"xué","duan":[]},"衡":{"expl":"牛觸，橫大木其角。从角从大，行聲。《詩》曰：“設其楅衡。”","rad":"角","fq":"戶庚切","vol":"04","py":"hénɡ","duan":[{"e":"牛觸、橫大木。","n":"各本大木下有其角二字。今依韵㑹所據鍇本。按許於吿字下曰。牛觸、角箸橫木所以吿也。是設於角者謂之吿。此云牛觸橫大木。是闌閑之謂之衡。衡與吿異義。大木𣃔不可施於角。此易明者。魯頌傳曰。楅衡、設牛角以楅之也。箋云。楅衡其牛角。爲其觸觝人也。許說與毛、鄭不同。毛、鄭謂設於角。許不云設於角也。木部云。楅以木有所畐束也。亦不言角。云大木者、字從大也。古多假衡爲橫。玉人注曰。衡古文橫。假借字也。○鄭注周禮云。楅設於角。衡設於鼻。如椵狀。楅衡爲二。許於衡不言楅。於楅不言衡。葢亦二之。"}]},"𧤗":{"expl":"角𧤗，獸也。狀似豕，角善爲弓，出胡休多國。从角耑聲。","rad":"角","fq":"多官切","vol":"04","py":"duān","duan":[{"e":"角𧤗、","n":"逗。"}]},"觰":{"expl":"觰拏，獸也。从角者聲。一曰下大者也。","rad":"角","fq":"陟加切","vol":"04","py":"zhā","duan":[{"e":"觰拏、","n":"逗。曡韵字。"}]},"觤":{"expl":"羊角不齊也。从角危聲。","rad":"角","fq":"過委切","vol":"04","py":"ɡuǐ","duan":[{"e":"羊角不齊也。","n":"釋嘼曰。角不齊、觤。郭云。一短一長。按此依爾雅系之羊。上文觢觭不系之牛者、意以觢觭可凡獸通偁也。觤觟則專謂羊。"}]},"觟":{"expl":"牝牂羊生角者也。从角圭聲。","rad":"角","fq":"下瓦切","vol":"04","py":"huà","duan":[{"e":"牝羊角者也。","n":"各本作牝牂羊生角者也。今依韵㑹正。羊部曰。牂、牝羊也。然則此云牝羊者、牂也。羖、夏羊牡之偁。羖羊無無角者。故小雅云。俾出童羖。牂羊多無角。故其角者別之曰觟也。大雅云。彼童而角。傳云。童羊之無角者也。而角自用也。箋云。童羊謂皇后也。按童羊正謂牂羊。"}]},"觡":{"expl":"骨角之名也。从角各聲。","rad":"角","fq":"古百切","vol":"04","py":"ɡé","duan":[{"e":"骨角之名也。","n":"骨角、角之如骨者。猶石言玉石也。樂記。角觡生。注云。無䚡曰觡。無䚡者、其中無肉。其外無理。郭氏山海經傳云麋鹿角曰觡是也。牛羊角有肉有理。玉篇云。無枝曰角。有枝曰觡。此取枝？之意。惟麋鹿角有枝。則其說非異也。封禪文。犧雙觡共柢之獸。謂二角同本也。言觡者白麟。鹿之大者也。"}]},"觜":{"expl":"鴟舊頭上角觜也。一曰觜觿也。从角此聲。","rad":"角","fq":"遵爲切","vol":"04","py":"zuǐ","duan":[{"e":"鴟舊頭上角觜也。","n":"角觜、萑下云毛角是也。毛角、頭上毛有似角者也。觜猶？、銳詞也。毛角銳。凡羽族之咮銳。故鳥咮曰觜。俗語因之凡口皆曰觜。其實本鳥毛角之偁也。鳥口之觜。廣雅作？。郭爾雅注云。山鵲？脚赤。葉抄釋文不誤。"}]},"解":{"expl":"判也。从刀判牛角。一曰解𢊁，獸也。","rad":"角","fq":"佳買切","vol":"04","py":"jiě","duan":[{"e":"判也。从刀判牛角。","n":"㑹意。佳買切。又戸賣切。十六部。"}]},"𦵡":{"expl":"𦵡藭，香艸也。从艸宮聲。","rad":"艸","fq":"去弓切","vol":"01","py":"qiōnɡ","duan":[{"e":"𦵡竆、","n":"逗。"}]},"觿":{"expl":"佩角，銳耑可以解結。从角巂聲。《詩》曰：“童子佩觿。”","rad":"角","fq":"戶圭切","vol":"04","py":"xī","duan":[{"e":"佩角銳耑。可㠯解結。","n":"衞風傳曰。觿所以解結。成人之佩也。内則注曰。小觿、解小結也。觿皃如錐。以象骨爲之。周禮眡祲十煇。三曰鑴。鄭云。鑴讀如童子佩鑴之鑴。謂日旁氣刺日者。按此注當云讀爲童子佩觿之觿。轉寫誤也。周禮假鑴爲觿。"}]},"觵":{"expl":"兕牛角可以飲者也。从角黃聲。其狀觵觵，故謂之觵。","rad":"角","fq":"古横切","vol":"04","py":"ɡōnɡ","duan":[{"e":"兕牛角可㠯㱃者也。","n":"詩四言兕觵而傳不同。卷耳曰兕觵、角爵也。七月曰觵所以誓衆也。桑扈曰兕觵、罰爵也。絲衣箋曰。繹之旅士用兕觵。變於祭也。周禮閭胥注曰。觵撻者、失禮之罰也。小胥曰。觵、罰爵也。卷耳無罰義。故袛云角爵。七月因鄉飮酒而正齒位。故云誓。誓者示以失禮則受罰也。葢觵之用於罰多。而非專用以罰。故卷耳、絲衣竝用兕觥。此許不言罰爵、而言可以飮之意也。異義。韓詩說觥亦五升。所以罰不敬。觥、廓也。箸明之貌。君子有過廓然箸明。毛詩說觥大七升。許愼謹案。觥罰有過。一飮而盡。七升爲過多。許意當同韓詩說大五升也。五升亦恐非一飮能盡。故於說文不言升數。"}]},"觶":{"expl":"鄉飲酒角也。《禮》曰：“一人洗，舉觶。”觶受四升。从角單聲。","rad":"角","fq":"之義切","vol":"04","py":"zhì","duan":[{"e":"鄉飮酒觶。","n":"鄉當作禮。禮經十七篇用觶者多矣。非獨鄉飮酒也。因下文一人洗舉觶之文見鄉飮酒篇。淺人乃改鄉字。觶鉉本作角。非。當同觚下作爵。"}]},"觛":{"expl":"小觶也。从角旦聲。","rad":"角","fq":"徒旱切","vol":"04","py":"dàn","duan":[{"e":"巵也。","n":"各本作小觶也。廣韵同。玉篇作小巵也。御覽引說文亦作小巵也。今按巵下云圜器也。一名觛。則此當作巵也無疑。小徐本廁此。大徐本改廁於觶篆後。云小觶也。殊誤。巵非觶也。漢高紀。奉玉巵爲大上皇壽。應劭曰。飮酒禮器也。古以角作。受四升。古巵字作觗。許云觶、禮經作觗。則觗字非巵古字。應仲遠誤合爲一。三都賦序舊注因之。遂有改說文者矣。今更正。古者簠簋爵觶、禮器也。敦牟卮匜、常用器也。"}]},"觴":{"expl":"觶實曰觴，虚曰觶。从角，𥏻省聲。","rad":"角","fq":"式陽切","vol":"04","py":"shānɡ","duan":[{"e":"實曰觴。虛曰觶。","n":"投壷。命酌曰。請行觴。觴者、實酒於爵也。韓詩說爵觚觶角散五者緫名曰爵。其實曰觴。觴者、餉也。觥者罰爵。非所以餉。不得名觴。然投壷之請行觴固罰爵也。凡禮經曰實者皆得曰觴。獨於觶言者、觶之用多舉觶以該他也。下文云觴受三升者曰觚。"}]},"觚":{"expl":"鄉飮酒之爵也。一曰觴受三升者謂之觚。从角瓜聲。","rad":"角","fq":"古乎切","vol":"04","py":"ɡū","duan":[{"e":"鄉飮酒之爵也。","n":"鄉亦當作禮。鄉飮酒禮有爵觶無觚也。燕禮、大射、特牲皆用觚。"}]},"䚙":{"expl":"角匕也。从角亘聲。讀若讙。","rad":"角","fq":"況袁切","vol":"04","py":"xuān","duan":[{"e":"角匕也。","n":"匕下曰。匕所以比取飯。一名柶。柶下曰。匕也。按士冠禮有角柶。卽䚙也。"}]},"䚫":{"expl":"杖耑角也。从角敫聲。","rad":"角","fq":"胡狄切","vol":"04","py":"xí","duan":[{"e":"杖耑角也。","n":"杖耑謂杖首也。司馬彪禮儀志。仲秋之月。民始七十者。授之以玉杖。餔之糜粥。八十九十有加賜。玉杖長尺。端以鳩鳥爲飾。謂玉長尺飾杖首。玉之顚復爲鳩形也。廣韵曰。䚫、以角飾杖策頭。小徐謂飾拄地處。誤甚。"}]},"觼":{"expl":"環之有舌者。从角敻聲。","rad":"角","fq":"古穴切","vol":"04","py":"jué","duan":[{"e":"環之有舌者。","n":"秦風曰。沃以觼軜。爾雅。環謂之捐。捐者、觼之假借字。詩容有作捐者。通俗文曰。缺環曰鐍。許與服不同。服謂如玦。許謂環中有橫者以固系。"}]},"𧣚":{"expl":"調弓也。从角，弱省聲。","rad":"角","fq":"於角切","vol":"04","py":"nuò","duan":[{"e":"調弓也。","n":"手部云。搦、按也。鄭注矢人云。撓搦其幹。亦是調意。弓人曰。和弓𣪠摩。注和猶調也。將用弓。必先調之、拂之、摩之。引大射禮。大射正以袂順左右隈。上再下一。小雅。觲觲角弓。毛傳曰。觲觲、調利也。世說新語曰。輕在角䚥中。爲人作議論。角䚥、方俗語言也。"}]},"藭":{"expl":"𦵡藭也。从艸窮聲。","rad":"艸","fq":"渠弓切","vol":"01","py":"qiónɡ","duan":[{"e":"营藭也。从艸。竆聲。","n":"渠弓切。九部。营竆曡韵。"}]},"䚨":{"expl":"隿射收𦅾具也。从角發聲。","rad":"角","fq":"方肺切","vol":"04","py":"fèi","duan":[{"e":"隿射收𦅾具也。","n":"葢以角爲之。"}]},"𧤕":{"expl":"隿射收繳具。从角酋聲。讀若鰌。","rad":"角","fq":"字秋切","vol":"04","py":"qiú","duan":[{"e":"隿射收𦅾具。","n":"按兩字同義。葢其物名䚨𧤕。上字當云䚨𧤕、隿射收𦅾具也。下字當云䚨𧤕也。今本恐非舊。但無證據。未敢專輒。"}]},"觳":{"expl":"盛觵卮也。一曰射具。从角㱿聲。讀若斛。","rad":"角","fq":"胡谷切","vol":"04","py":"hú","duan":[{"e":"盛觵巵也。","n":"盛字當是衍文。觵巵謂大巵。觵者、酒器之大者也。韋注越語曰。觥、大也。瓬人曰。豆實三而成觳。鬲部曰。𣁬二升曰觳。鄭注考工記同。按簋庾鬲甗盆䰝量皆以觳計。小者曰巵。可以飮。大巵曰觳。可宁酒漿以待酌也。觵之大極於觳。故引伸之曰觳、盡也。見釋詁。禮經牲體之跗曰觳。謂牲體之盡也。"}]},"𧥑":{"expl":"羌人所吹角屠𧥑，以驚馬也。从角𢨋聲。𢨋，古文誖字。","rad":"角","fq":"卑吉切","vol":"04","py":"bì","duan":[{"e":"羌人所龡角屠𧥑。","n":"句。"}]},"竹":{"expl":"冬生艸也。象形。下垂者，箁箬也。凡竹之屬皆从竹。","rad":"竹","fq":"陟玉切","vol":"05","py":"zhú","duan":[{"e":"冬生艸也。","n":"云冬生者、謂竹胎生於冬。且枝葉不凋也。云竹者、爾雅竹在澤艸。山海經有云其艸多竹。故謂之冬生艸。戴凱之云。植物之中有艸木竹、猶動品之中有魚鳥獸也。"}]},"箭":{"expl":"矢也。从竹前聲。","rad":"竹","fq":"子賤切","vol":"05","py":"jiàn","duan":[{"e":"矢竹也。","n":"各本無竹。依藝文類聚補。矢竹者可以爲矢之竹也。周禮及釋地注皆曰。箭、篠也。方言。箭自關而東謂之矢。江淮之閒謂之𨩀。關西曰箭。郭云。箭者、竹名。因以爲號。按今天下語言皆謂矢爲箭。"}]},"箘":{"expl":"箘簬也。从竹囷聲。一曰博棊也。","rad":"竹","fq":"渠隕切","vol":"05","py":"jùn","duan":[{"e":"箘簬、","n":"逗。"}]},"簬":{"expl":"箘簬也。从竹路聲。《夏書》曰：“惟箘簬楛。”","rad":"竹","fq":"洛故切","vol":"05","py":"lù","duan":[{"e":"箘簬也。从竹。路聲。","n":"洛故切。五部。"}]},"筱":{"expl":"箭屬。小竹也。从竹攸聲。","rad":"竹","fq":"先杳切","vol":"05","py":"xiǎo","duan":[{"e":"箭屬。小竹也。","n":"釋草曰。篠、箭。周禮注曰。箭、篠也。二京賦解曰。篠、箭竹也。此云箭屬。小異。"}]},"簜":{"expl":"大竹也。从竹湯聲。《夏書》曰：“瑤琨筱簜。”簜可爲幹，筱可爲矢。","rad":"竹","fq":"徒朗切","vol":"05","py":"dànɡ","duan":[{"e":"大竹也。","n":"大射儀。簜在建𡔷之閒。注。蕩、竹也。笙簫之屬。按蕩者竹名。以竹成器亦曰簜。笙簫皆用小竹而云簜者、大之也。"}]},"蘭":{"expl":"香艸也。从艸闌聲。","rad":"艸","fq":"落干切","vol":"01","py":"lán","duan":[{"e":"香艸也。","n":"易曰。其臭如蘭。左傳曰。蘭有國香。說者謂似澤蘭也。"}]},"䉠":{"expl":"竹也。从竹微聲。","rad":"竹","fq":"無非切","vol":"05","py":"wéi","duan":[{"e":"竹也。","n":"竹名。按䉠篃古今字也。如禮經古文眉作微、爾雅湄作㵟之比。西山經英山其陽多箭多篃。今本作䉋。郭云。今漢中郡出。厚裏而長節。根㴱。筍冬生。戴凱之云。生非一處。江南山谷所饒也。故是箭竹類。一尺數節。葉大如履。可以作篷。莖中作矢。俗謂之䈛笴。按郭云長節、戴云穊節。不合。旣云中作矢。則一尺數節當作數尺一節也。"}]},"筍":{"expl":"竹胎也。从竹旬聲。","rad":"竹","fq":"思允切","vol":"05","py":"sǔn","duan":[{"e":"竹胎也。","n":"醢人注曰。筍、竹萌。按許與鄭稍異。胎言其含苞。萌言其已㩅也。吳都賦曰。苞筍抽節。引伸爲竹靑皮之偁。尙書云敷重筍席、禮器如竹箭之有筍、聘義浮筍旁達皆是。其音爲贇切。今字作筠。"}]},"䈚":{"expl":"竹萌也。从竹怠聲。","rad":"竹","fq":"徒哀切","vol":"05","py":"tái","duan":[{"e":"竹萌也。","n":"釋草曰。䈚、箭萌。醢人鄭注同。許意筍䈚不以大竹小竹分別。筍从旬。旬从勹。取褢妊之意。䈚从怠。與始同音。取始生之意。筍謂掘諸地中者、如今之冬筍。䈚謂已抽出者、如今之春筍。與鄭說不同也。按周禮箈菹本作菭菹。故大鄭云菭、水中魚衣也。與艸部菭水靑衣也合。後鄭讀菭爲䈚。用釋草箭萌之訓。故郭注爾雅引周禮䈚菹鴈醢也。今本周禮作箈。非菭非䈚。乃是譌字。注中亦奪菭當爲䈚四字。"}]},"箁":{"expl":"竹箬也。从竹咅聲。","rad":"竹","fq":"薄侯切","vol":"05","py":"póu","duan":[{"e":"竹箬也。从竹。咅聲。","n":"薄侯切。四部。"}]},"箬":{"expl":"楚謂竹皮曰箬。从竹若聲。","rad":"竹","fq":"而勺切","vol":"05","py":"ruò","duan":[{"e":"楚謂竹皮曰箬。","n":"今欲云筍籜、箬是也。毤而陊地。故竹篆下垂者像之。"}]},"節":{"expl":"竹約也。从竹即聲。","rad":"竹","fq":"子結切","vol":"05","py":"jié","duan":[{"e":"竹約也。","n":"約、纏束也。竹節如纏束之狀。吳都賦曰。苞筍抽節。引伸爲節省、節制、節義字。又假借爲符卪字。"}]},"筡":{"expl":"折竹笢也。从竹余聲。讀若絮。","rad":"竹","fq":"同都切","vol":"05","py":"tú","duan":[{"e":"析竹笢也。","n":"析各本譌折。今正。方言。荼、析也。析竹謂之荼。郭云。今江東呼蔑竹裏爲荼。亦名荼之也。按此注謂已析之蔑爲荼。人析之亦偁荼之。本無誤字。戴氏疏證改荼之二字爲笢字。非也。爾雅。簢、荼中。葢此義之引伸。肉薄好大者謂之筡中。如析去靑皮而薄也。醫方竹筎音如。卽此字。別録从竹。俗从艸。"}]},"𥵸":{"expl":"筡也。从竹𦤝聲。","rad":"竹","fq":"武移切","vol":"05","py":"mí","duan":[{"e":"筡也。","n":"謂筡之也。釋草。粼堅中。粼同磨磷之磷。謂堅中者必磨之也。簢筡中。簢同𥵨。謂空中者必析之也。"}]},"笢":{"expl":"竹膚也。从竹民聲。","rad":"竹","fq":"武盡切","vol":"05","py":"mǐn","duan":[{"e":"竹膚也。","n":"膚、皮也。竹膚曰笢。亦曰筍。見禮器。俗作筠。已析可用者曰蔑。禮注作䈼。士喪禮謂之靲。析之謂之筡。亦謂之𥵨。"}]},"笨":{"expl":"竹裏也。从竹本聲。","rad":"竹","fq":"布忖切","vol":"05","py":"bèn","duan":[{"e":"竹裏也。","n":"謂其內質白也。又有白如紙者。吳都賦注謂之竹孚俞。"}]},"葌":{"expl":"艸，出吳林山。从艸姦聲。","rad":"艸","fq":"古顔切","vol":"01","py":"jiān","duan":[{"e":"香艸也。","n":"依衆經音義補二字。"}]},"䈵":{"expl":"竹皃。从竹翁聲。","rad":"竹","fq":"烏紅切","vol":"05","py":"wēnɡ","duan":[{"e":"竹皃。","n":"南都賦。其竹阿𨙻䈵䇯。風靡云披。李善引說文。䈵、竹皃也。埤蒼。䇯、竹頭有文也。上烏孔反。下如湧反。按吳都賦云。翁䇯蕭瑟。謝靈運山居賦自注。修竦、便娟、蕭森、䈵蔚皆竹貌也。今三賦䈵皆誤从艸矣。"}]},"篸":{"expl":"差也。从竹𠻝聲。","rad":"竹","fq":"所今切","vol":"05","py":"chēn","duan":[{"e":"篸差也。","n":"各本差上無篸。此淺人謂爲複舉字而𠜂之也。集韵。篸差、竹皃。初簪切。又篸竹長皃。疏簪切。按木部槮、木長皃。引槮差䓷菜。葢物有長有短則參差不齊。竹木皆然。今人作參差。古則从竹、从木也。"}]},"篆":{"expl":"引書也。从竹彖聲。","rad":"竹","fq":"持兖切","vol":"05","py":"zhuàn","duan":[{"e":"引書也。","n":"引書者、引筆而箸於竹帛也。因之李斯所作曰篆書。而謂史籒所作曰大篆。旣又謂篆書曰小篆。其字之本義爲引書。如雕刻圭璧曰瑑。周禮注。五采畫轂約謂之夏篆。"}]},"籒":{"expl":"讀書也。从竹㩅聲。《春秋傳》曰“卜籒”云。","rad":"竹","fq":"直又切","vol":"05","py":"zhòu","duan":[{"e":"讀書也。","n":"言部曰。讀、籒書也。敘目曰。尉律。學僮十七已上始試。諷籒書九千字。乃得爲吏。試字句絶。諷籒連文。謂諷誦而抽釋之。滿九千字皆得六書之𢫾。乃得爲吏也。此籒字之本義。經傳尟用。周宣王時大史以爲名。因以名所箸大篆曰籒文。迄今學者絶少知其本義者。故於讀下籒書改爲誦書。於敘目釋爲籒文九千字。重悂貤繆。可勝歎哉。毛傳曰。讀抽也。方言曰。抽、讀也。抽皆籒之假借。籒者、抽也。讀者、續也。抽引其緒相續而不竆也。亦假紬字爲之。大史公自序。紬史記石室金匱之書。如淳云。抽徹舊書故事而次述之也。亦借繇字爲之。春秋傳卜筮繇辭。今皆作繇。又俗作繇。據許則作籒。服虔曰。繇、抽也。抽出吉凶也。"}]},"篇":{"expl":"書也。一曰關西謂榜曰篇。从竹扁聲。","rad":"竹","fq":"芳連切","vol":"05","py":"piān","duan":[{"e":"書也。","n":"書箸也。箸於箭𥳑牘者也。亦謂之篇。古曰篇。漢人亦曰卷。卷者、縑帛可捲也。"}]},"籍":{"expl":"簿書也。从竹𦔡聲。","rad":"竹","fq":"秦昔切","vol":"05","py":"jí","duan":[{"e":"簿也。","n":"簿當作薄。六寸薄、見寸部。引伸凡箸於竹帛皆謂之籍。"}]},"篁":{"expl":"竹田也。从竹皇聲。","rad":"竹","fq":"戶光切","vol":"05","py":"huánɡ","duan":[{"e":"竹田也。","n":"戰國策。薊丘之植。植於汶篁。西京賦。篠簜𢾭衍。編町成篁。漢書。篁竹之中。注。竹田曰篁。今人訓篁爲竹。而失其本義矣。"}]},"䉃":{"expl":"剖竹未去節謂之䉃。从竹將聲。","rad":"竹","fq":"即兩切","vol":"05","py":"jiǎnɡ","duan":[{"e":"剖竹未去節謂之䉃。","n":"謂未去中之相隔者。方言。所以隠櫂謂之𥷃。郭云。搖樐小橛也。按𥷃葢卽䉃字。其始以剖竹未去節爲之。後乃以木爲之。改其字作𥷃、作槳。後人又不以名橛而以名櫂矣。"}]},"䈎":{"expl":"籥也。从竹枼聲。","rad":"竹","fq":"與接切","vol":"05","py":"yè","duan":[{"e":"籥也。","n":"小兒所書寫。每一笘謂之一䈎。今書一紙謂之一頁。或作葉。其實當作此䈎。"}]},"籥":{"expl":"書僮竹笘也。从竹龠聲。","rad":"竹","fq":"以灼切","vol":"05","py":"yuè","duan":[{"e":"書僮竹笘也。","n":"笘下曰。潁川人名小兒所書寫爲笘。按笘謂之籥。亦謂之觚。葢以白墡染之可拭去再書者。其拭觚之布曰幡。"}]},"葰":{"expl":"䕬屬。可以香口。从艸俊聲。","rad":"艸","fq":"息遺切","vol":"01","py":"suī","duan":[{"e":"䕬屬。可㠯香口。","n":"旣夕禮實綏澤焉注。綏、廉薑。澤、澤蘭也。皆取其香且禦溼。按綏者、葰之叚借字。一名山辣。今藥中三柰也。吳都賦謂之薑彚。"}]},"䉧":{"expl":"竹聲也。从竹劉聲。","rad":"竹","fq":"力求切","vol":"05","py":"liú","duan":[{"e":"竹聲也。","n":"小徐曰。猶言𤄉然聲淸也。"}]},"簡":{"expl":"牒也。从竹閒聲。","rad":"竹","fq":"古限切","vol":"05","py":"jiǎn","duan":[{"e":"牒也。","n":"片部曰。牒、札也。木部曰。札、牒也。按𥳑、竹爲之。牘、木爲之。牒札其通語也。釋器曰。𥳑謂之畢。學記云呻其佔畢是也。等者、齊𥳑也。編者、次𥳑也。詳冊下。"}]},"笐":{"expl":"竹列也。从竹亢聲。","rad":"竹","fq":"古郎切","vol":"05","py":"ɡānɡ","duan":[{"e":"竹列也。","n":"列玄應書作次。竹列者、謂竹之生。疏數偃仰。不齊而齊。笐之言行也。行、列也。釋草。仲無笐。葢謂竹有行列如伯仲然也。無者、發聲也。引伸之取竹爲衣架亦曰笐。廣韵四十二宕曰笐、衣架是也。內則所謂楎椸。釋器所謂竿謂之箷也。其字亦作桁。古樂府云。還視桁下無懸衣是也。"}]},"篰":{"expl":"㒼爰也。从竹部聲。","rad":"竹","fq":"薄口切","vol":"05","py":"bù","duan":[{"e":"㒼爰也。","n":"廣雅曰。𥵥䈠、篰也。曹憲上音滿。下音緩。廣韵曰。𥵥䈠、𥳑也。篰、牘也。玉篇曰。篰、竹牘也。按㒼爰漢人語。俗字加竹。"}]},"等":{"expl":"齊簡也。从竹从寺。寺，官曹之等平也。","rad":"竹","fq":"多肯切","vol":"05","py":"děnɡ","duan":[{"e":"齊𥳑也。","n":"齊𥳑者、㬪𥳑𠕋齊之。如今人整齊書籍也。引伸爲凡齊之偁。凡物齊之。則高下歷歷。可見。故曰等級。刀部云。則、等畫物也。"}]},"笵":{"expl":"法也。从竹，竹，𥳑書也；氾聲。古法有竹刑。","rad":"竹","fq":"防𡕢切","vol":"05","py":"fàn","duan":[{"e":"法也。","n":"繫辭。範圍天地之化而不過。鄭曰。範、法也。考工記。軓前十尺。注云。書或作𨊠。𨊠、法也。按許無𨊠字。車部範爲範軷。則𣪠辭範圍、假借字也。"}]},"箋":{"expl":"表識書也。从竹戔聲。","rad":"竹","fq":"則前切","vol":"05","py":"jiān","duan":[{"e":"表識書也。","n":"鄭六藝論云。注詩宗毛爲主。毛義若隠略。則更表明。如有不同。卽下己意。按注詩偁箋。自說甚明。博物志云。毛爲北海相。鄭是郡人。故稱箋以爲敬。此泥魏晉時上書偁箋之例。絶非鄭意。"}]},"符":{"expl":"信也。漢制以竹，長六寸，分而相合。从竹付聲。","rad":"竹","fq":"防無切","vol":"05","py":"fú","duan":[{"e":"信也。漢制㠯竹。長六寸。分而相合。","n":"周禮。門關用符節。注曰。符節者、如今宫中諸官詔符也。小宰傅別、故書作傅辨。鄭大夫讀爲符別。漢孝文紀。始與郡國守相爲銅虎符、竹使符。應劭云。銅虎符一至五。國家當發兵。遣使至都合符符。符合乃聽受之。竹使符皆以竹箭五枚。長五寸。鐫刻篆書。第一至第五。張晏曰。符以代古之圭璋。从𥳑易也。按許云六寸。漢書注作五寸。未知孰是。"}]},"筮":{"expl":"《易》卦用蓍也。从竹从𢍮。𢍮，古文巫字。","rad":"竹","fq":"時制切","vol":"05","py":"shì","duan":[{"e":"易卦用蓍也。","n":"曲禮曰。龜爲卜。策爲筮。策者、蓍也。周禮策簭人注云。問蓍曰筮。其占易。艸部曰。蓍、易以爲數。"}]},"笄":{"expl":"簪也。从竹幵聲。","rad":"竹","fq":"古兮切","vol":"05","py":"jī","duan":[{"e":"兂也。","n":"各本作簪。今正。兂下曰。首筓也。俗作簪。戴氏曰。無冠筓而冕弁有筓。筓所以貫之於其左右。是以冠無之。凡無筓者纓。冕制。延前圓垂旒。後方。延有紐。自延左右垂。筓貫之以爲固。紘以組。自頤屈而上。左右屬之筓。垂其餘。凡冕弁筓。有筓者紘。記曰。天子冕而朱紘。諸矦冕而靑紘。士冠禮。皮弁筓。爵弁筓。朱組紘纁邊。"}]},"芄":{"expl":"芄蘭，莞也。从艸丸聲。《詩》曰：“芄蘭之枝。”","rad":"艸","fq":"胡官切","vol":"01","py":"wán","duan":[{"e":"芄蘭、","n":"逗。"}]},"䇫":{"expl":"取蟣比也。从竹𦣞聲。","rad":"竹","fq":"居之切","vol":"05","py":"jī","duan":[{"e":"取蟣比也。","n":"比篦古今字。比、密也。引伸爲櫛髮之比。釋名曰。梳言其齒疏也。數言比。比於梳其齒差數也。比言細相比也。木部曰。櫛者、梳比之緫名也。史記。遺單于比余一。漢書作比疎一。余、疎皆卽梳字。比梳一者、統言則比亦梳也。蟣者蝨子。云取蟣比者、此之至密者也。今江浙皆呼篦䇫。比當依俗音毗。漢書頻寐反。"}]},"籆":{"expl":"收絲者也。从竹蒦聲。","rad":"竹","fq":"王縛切","vol":"05","py":"yuè","duan":[{"e":"所㠯收絲者也。","n":"所以二字今補。方言曰。籆、榬也。兖豫河濟之閒謂之榬。郭云。所以絡絲也。音爰。按今俗謂之籆車。于縛切。字亦作籰。"}]},"筳":{"expl":"繀絲筦也。从竹廷聲。","rad":"竹","fq":"特丁切","vol":"05","py":"tínɡ","duan":[{"e":"繀絲筦也。","n":"系部曰。繀、箸絲於筟車也。按絡絲者必以絲耑箸於筳。今江浙尙呼筳。"}]},"筦":{"expl":"筟也。从竹完聲。","rad":"竹","fq":"古滿切","vol":"05","py":"ɡuǎn","duan":[{"e":"筟也。从竹。完聲。","n":"古滿切。十四部。"}]},"筟":{"expl":"筳也。从竹孚聲。讀若《春秋》魯公子彄。","rad":"竹","fq":"芳無切","vol":"05","py":"fū","duan":[{"e":"筳也。","n":"筵筦筟三名一物也。方言曰。繀車、趙魏之閒謂之轣轆車。東齊海岱之閒謂之道軌。按自其轉旋言之。謂之厤鹿。亦謂之道軌。亦謂之鹿車。自其箸絲之筳言之。謂之繀車。亦謂之筟車。實卽今之籆車也。"}]},"笮":{"expl":"迫也。在瓦之下，棼上。从竹乍聲。","rad":"竹","fq":"阻厄切","vol":"05","py":"zé","duan":[{"e":"迫也。","n":"㬪韵。說文無窄字。笮窄古今字也。屋笮者本義。引伸爲逼窄字。"}]},"簾":{"expl":"堂簾也。从竹廉聲。","rad":"竹","fq":"力鹽切","vol":"05","py":"lián","duan":[{"e":"堂簾也。","n":"小徐曰。此書及釋名簾帷皆作㡘。疑𢅏或與簾別。或者此簾字後人所加之乎。所不能決也。按巾部曰。㡘、帷也。又曰。在旁曰帷。周禮幕人。掌帷幙幄帟綬之事。注曰。王出宫則有是事。在旁曰帷。在上曰幕。帷幕皆以布爲之。四合象宫室曰幄。帟者、王在幕若幄中坐上承塵。幄帟皆以繒爲之。然則㡘施於次以蔽旁。簾施於堂之前以隔風日而通明。㡘以布爲之故从巾。簾析竹縷爲之故其字从竹。其用殊。其地殊。其質殊。學者可以無疑矣。"}]},"簀":{"expl":"牀棧也。从竹責聲。","rad":"竹","fq":"阻厄切","vol":"05","py":"zé","duan":[{"e":"牀棧也。","n":"衞風。綠竹如簀。毛曰。簀、積也。此言假借也。韓詩傳亦同。"}]},"笫":{"expl":"牀簀也。从竹𠂔聲。","rad":"竹","fq":"阻史切","vol":"05","py":"zǐ","duan":[{"e":"簀也。","n":"見釋器。左傳。牀笫之言不踰閾周易。噬乾胏。鄭曰。胏、簀也。此言假胏爲笫也。士喪禮古文笫爲茨。"}]},"筵":{"expl":"竹席也。从竹延聲。《周禮》曰：“度堂以筵。”筵一丈。","rad":"竹","fq":"以然切","vol":"05","py":"yán","duan":[{"e":"竹席也。","n":"周禮司幾筵注曰。筵亦席也。鋪陳曰筵。藉之曰席。然基言之筵席通矣。按司几筵掌五几五席之名物。筵席不別也。五席不用竹。惟後鄭說次席是桃枝席。又說顧命蔑席、厎席、豐席、筍席皆爲竹席。許釋筵爲竹席者、其字从竹也。"}]},"禋":{"expl":"潔祀也。一曰精意以享爲禋。从示垔聲。","rad":"示","fq":"於眞切","vol":"01","py":"yīn","duan":[{"e":"絜祀也。","n":"韋昭注周語同。釋詁。禋、祭也。孫炎曰。潔敬之祭也。各本作潔。依玉篇作絜。"}]},"虈":{"expl":"楚謂之蘺，晉謂之虈，齊謂之茝。从艸嚻聲。","rad":"艸","fq":"許嬌切","vol":"01","py":"xiāo","duan":[{"e":"楚謂之蘺。晉謂之䖀。齊謂之茝。","n":"此一物而方俗異名也。茝、本艸經謂之白芷。茝芷同字。茝聲止聲同在一部也。內則曰。佩帨茝蘭。掌禹錫曰。范子計然云。白芷出齊郡。王逸九思曰。芳䖀兮挫枯。埤蒼曰。齊茝一曰䖀。按屈原賦有茝有芷又有葯。王注曰。葯、白芷也。廣雅曰。白芷、其葉謂之葯。說文無葯字。䖀聲約聲同在二部。疑䖀葯同字耳。但又曰楚謂之蘺。下卽系以蘺篆。云江蘺蘪蕪。以茝、江蘺、蘪蕪爲一物。殊不可曉。離騷曰。扈江蘺於辟芷兮。非一物明矣。"}]},"簟":{"expl":"竹席也。从竹𪉷聲。","rad":"竹","fq":"徒念切","vol":"05","py":"diàn","duan":[{"e":"竹席也。","n":"毛詩箋曰。竹葦曰簟。"}]},"籧":{"expl":"籧篨，粗竹席也。从竹遽聲。","rad":"竹","fq":"彊魚切","vol":"05","py":"qú","duan":[{"e":"籧篨、","n":"逗。"}]},"篨":{"expl":"籧篨也。从竹除聲。","rad":"竹","fq":"直魚切","vol":"05","py":"chú","duan":[{"e":"籧篨也。从竹。除聲。","n":"直魚切。五部。"}]},"籭":{"expl":"竹器也。可以取粗去細。从竹麗聲。","rad":"竹","fq":"所宜切","vol":"05","py":"shāi","duan":[{"e":"竹器也。可㠯取麤去細。","n":"俗云簁籮是也。廣韵云。籭、𥂖也。能使麤者上存。細者𥂖下。籭簁古今字也。漢賈山傳作篩。"}]},"籓":{"expl":"大箕也。从竹潘聲。一曰蔽也。","rad":"竹","fq":"甫煩切","vol":"05","py":"fān","duan":[{"e":"大箕也。","n":"廣雅曰。籓籮箕也。"}]},"䉛":{"expl":"漉米籔也。从竹奥聲。","rad":"竹","fq":"於六切","vol":"05","py":"yù","duan":[{"e":"漉米籔也。","n":"方言曰。炊䉛謂之縮。或謂之𥰞。或謂之㔯。郭注。漉米䉛。江東呼淅籤。按史記索隠引纂要云。䉛、淅箕也。此注籤字正箕之誤。今江蘇人呼淘米具曰溲箕是也。"}]},"籔":{"expl":"炊䉛也。从竹數聲。","rad":"竹","fq":"蘇后切","vol":"05","py":"sǒu","duan":[{"e":"炊䉛也。","n":"本漉米具也。旣浚乾則可炊矣。故名炊䉛。方言𥰞同籔。縮卽籔之入聲也。毛詩伐木傳曰。以筐曰釃。以籔曰湑。籔卽今之溲箕也。今誤从艸作藪。筐者、盛飯之器。較細。籔者、滰淅之器。較麤。皆可以漉酒者。"}]},"箅":{"expl":"蔽也，所以蔽甑底。从竹𢌿聲。","rad":"竹","fq":"必至切","vol":"05","py":"bì","duan":[{"e":"蔽也。","n":"此戸護也、門聞也之例。"}]},"𥳓":{"expl":"飯筥也。受五升。从竹稍聲。秦謂筥曰𥳓。","rad":"竹","fq":"山樞切","vol":"05","py":"shāo","duan":[{"e":"飯筥也。受五升。","n":"方言曰。𥰠、南楚謂之筲。郭曰。盛𩚳筥也。按𥰠卽筥字。筲卽𥳓字也。論語。𣁬筲之人。鄭曰。筲、竹器。容𣁬二升。與許說受五升異。"}]},"䈰":{"expl":"陳畱謂飯帚曰䈰。从竹捎聲。一曰飯器，容五升。一曰宋魏謂箸筩爲䈰。","rad":"竹","fq":"所交切","vol":"05","py":"shāo","duan":[{"e":"陳畱謂飯帚曰䈰。","n":"飯帚者、所以埽𣧻餘之飯。"}]},"蘺":{"expl":"江蘺，蘼蕪。从艸離聲。","rad":"艸","fq":"呂之切","vol":"01","py":"lí","duan":[{"e":"江蘺、","n":"逗。"}]},"筥":{"expl":"䈰也。从竹呂聲。","rad":"竹","fq":"居許切","vol":"05","py":"jǔ","duan":[{"e":"䈰也。","n":"䈰當作𥳓。方言。𥰠、南楚謂之筲。趙魏之郊謂之𥬔𥰠。禮經鄭注云。笲形葢如今之筥𥬔籚。按𥬔籚卽𥬔𥰠也。"}]},"笥":{"expl":"飯及衣之器也。从竹司聲。","rad":"竹","fq":"相吏切","vol":"05","py":"sì","duan":[{"e":"从竹。","n":"大射儀曰。小射正奉決拾以笥。注。笥、萑葦器。按此葢笥之小者也。大者以竹爲之。"}]},"簞":{"expl":"笥也。从竹單聲。漢津令：簞，小筐也。《傳》曰：“簞食壺漿。”","rad":"竹","fq":"都寒切","vol":"05","py":"dān","duan":[{"e":"笥也。","n":"論語孔注同。皇侃曰。以竹爲之。如箱篋之屬。左傳。夫差以一簞珠問趙孟。葢亦簞之小者也。"}]},"簁":{"expl":"簁箄，竹器也。从竹徙聲。","rad":"竹","fq":"所綺切","vol":"05","py":"shāi","duan":[{"e":"簁箄、","n":"逗。"}]},"箄":{"expl":"簁箄也。从竹卑聲。","rad":"竹","fq":"并弭切","vol":"05","py":"bǐ","duan":[{"e":"簁箄也。","n":"絫呼曰簁箄。單呼曰箄。方言。箄簍籅䈱𥴧也。𥴧小者、自關而西秦晉之閒謂之箄。郭云。今江東呼小籠爲箄。按許意簁箄與𥴧各物。"}]},"篿":{"expl":"圜竹器也。从竹專聲。","rad":"竹","fq":"度官切","vol":"05","py":"tuán","duan":[{"e":"圜竹器也。","n":"盛物之器而圜者。篿與團音同也。離騷王注曰。楚人名結草折竹卜曰篿。別一義也。"}]},"箸":{"expl":"飯攲也。从竹者聲。","rad":"竹","fq":"陟慮切","vol":"05","py":"zhù","duan":[{"e":"飯㩻也","n":"㩻各本作攲。支部攲、持去也。危部㩻、䧢也。㩻者傾側意。箸必傾側用之。故曰飯㩻。宗廟宥座之器曰攲器。古亦當作㩻器也。箸、曲禮謂之梜。假借爲箸落、爲箸明。古無去入之別。字亦不从艸也。"}]},"簍":{"expl":"竹籠也。从竹婁聲。","rad":"竹","fq":"洛侯切","vol":"05","py":"lǒu","duan":[{"e":"竹籠也。","n":"方言。簍、𥴧也。𥴧小者、南楚謂之簍。"}]},"筤":{"expl":"籃也。从竹良聲。","rad":"竹","fq":"盧黨切","vol":"05","py":"lánɡ","duan":[{"e":"籃也。","n":"廣雅。筤謂之𥫵。廣韵曰。筤、車籃。一名𥫵。𥫵音替。按許不言車籃。泛言籠下之器耳。"}]},"籃":{"expl":"大篝也。从竹監聲。","rad":"竹","fq":"魯甘切","vol":"05","py":"lán","duan":[{"e":"大篝也。","n":"今俗謂熏篝曰烘籃是也。"}]},"茝":{"expl":"虈也。从艸𦣞聲。","rad":"艸","fq":"昌改切","vol":"01","py":"chǎi","duan":[{"e":"䖀也。从艸。𦣝（𦣞）聲。","n":"昌改切。一部。"}]},"篝":{"expl":"笿也。可熏衣。从竹冓聲。宋楚謂竹篝牆以居也。","rad":"竹","fq":"古侯切","vol":"05","py":"ɡōu","duan":[{"e":"笿也。可熏衣。","n":"按也字衍文。當云笿可熏衣者。廣韵曰。熏籠。"}]},"笿":{"expl":"桮笿也。从竹各聲。","rad":"竹","fq":"盧各切","vol":"05","py":"luò","duan":[{"e":"桮笿也。","n":"方言。桮𥯛、陳楚宋衞之閒謂之桮𥯛。又謂之豆筥。自關東西謂之桮𥯛。郭云。盛桮器籠也。按引伸爲籠絡字。今人作絡。古當作笿。亦作落。"}]},"䇨":{"expl":"桮笿也。从竹夅聲。或曰盛箸籠。","rad":"竹","fq":"古送切","vol":"05","py":"ɡònɡ","duan":[{"e":"桮笿也。","n":"廣雅曰。䇨、桮𥯛也。"}]},"籢":{"expl":"鏡籢也。从竹斂聲。","rad":"竹","fq":"力鹽切","vol":"05","py":"lián","duan":[{"e":"鏡籨也。","n":"玉篇引列女傳曰。置鏡籨中。別作匳。俗作奩。廣韵云。盛香器也。"}]},"籫":{"expl":"竹器也。从竹贊聲。讀若纂。一曰叢。","rad":"竹","fq":"作管切","vol":"05","py":"zuǎn","duan":[{"e":"竹器也。","n":"廣雅、方言注皆曰。籫、箸筩。"}]},"籯":{"expl":"笭也。从竹贏聲。","rad":"竹","fq":"以成切","vol":"05","py":"yínɡ","duan":[{"e":"笭也。","n":"笭字下曰。一曰籯也。漢書。遺子黃金滿籯。不如敎子一經。竹籠也。廣雅曰。籯、箸筩也。"}]},"𥮚":{"expl":"竹器也。从竹𠛹聲。","rad":"竹","fq":"蘇旰切","vol":"05","py":"sān","duan":[{"e":"竹器也。","n":"玉篇曰。似箱而麤。"}]},"簋":{"expl":"黍稷方器也。从竹从皿从皀。","rad":"竹","fq":"居洧切","vol":"05","py":"ɡuǐ","duan":[{"e":"黍稷方器也。","n":"周禮舍人注曰。方曰簠。圓曰簋。盛黍稷稻梁也。掌客注曰。簠、稻梁器也。簋、黍稷器也。秦風傳曰。四簋、黍稷稻粱也。按毛意言簋可以該簠。鄭注則據公食大夫禮分別所盛也。許云簋方簠圜。鄭則云簋圜簠方。不同者、師傳各異也。周易。二簋可用享。鄭注云。離爲日。日體圓。巽爲木。木器圓。簋象。聘禮竹簋方注云。竹簋方者、器名。以竹爲之。狀如簋而方。賈疏云。凡簋皆用木而圓。此則用竹而方。故云如簋而方。宋刻單行疏內簋字凡四見。今本依釋文改經注疏皆作簠字。非也。已上可證鄭確謂簋爲圓器。周禮疏云。孝經陳其簋簠注云。內圓外方受𣁬二升者。直據簠而言。若簋則內方外圓。孝經鄭注、說者謂鄭小同之注也。賈所引文亦不完。則無用㴱求矣。而"}]},"簠":{"expl":"黍稷圜器也。从竹从皿，甫聲。","rad":"竹","fq":"方矩切","vol":"05","py":"fǔ","duan":[{"e":"黍稷圜器也。","n":"簠盛稻梁。見公食大夫禮經文。云左擁簠梁是也。此云黍稷者。統言則不別也。如毛傳云四簋黍稷稻梁。亦是統言。云圜器。與鄭云方器互異。"}]},"𥸅":{"expl":"竹豆也。从竹邊聲。","rad":"竹","fq":"布玄切","vol":"05","py":"biān","duan":[{"e":"竹豆也。","n":"豆、古食肉器也。木豆謂之梪。竹豆謂之籩。周禮籩人。掌四籩之實。注曰。籩、竹器如豆者。其容實皆四升。"}]},"蘪":{"expl":"蘪蕪也。从艸麋聲。","rad":"艸","fq":"靡爲切","vol":"01","py":"méi","duan":[{"e":"蘪蕪也。","n":"三字句。蘪蕪雙聲。"}]},"𥫱":{"expl":"篅也。从竹屯聲。","rad":"竹","fq":"徒損切","vol":"05","py":"dùn","duan":[{"e":"篅也。","n":"廣韵。𥫱、籧也。按今俗謂盛穀高大之器曰土籧。"}]},"篅":{"expl":"以判竹圜以盛穀也。从竹耑聲。","rad":"竹","fq":"市緣切","vol":"05","py":"chuán","duan":[{"e":"㠯判竹。","n":"句。謂用析竹爲之也。"}]},"簏":{"expl":"竹高篋也。从竹鹿聲。","rad":"竹","fq":"盧谷切","vol":"05","py":"lù","duan":[{"e":"竹高匧也。","n":"匧之高者。竹爲之。"}]},"𥯕":{"expl":"大竹筩也。从竹昜聲。","rad":"竹","fq":"徒朗切","vol":"05","py":"dànɡ","duan":[{"e":"大竹筩也。","n":"大射儀。簜在建𡔷之閒。按當作𥯕。簜乃竹名。非其義也。笙簫之屬而謂之𥯕者、大之也。"}]},"筩":{"expl":"斷竹也。从竹甬聲。","rad":"竹","fq":"徒紅切","vol":"05","py":"tónɡ","duan":[{"e":"𣃔竹也。","n":"漢律曆志曰。制十二筩以聽鳳之鳴。此筩之一耑也。"}]},"箯":{"expl":"竹輿也。从竹便聲。","rad":"竹","fq":"旁連切","vol":"05","py":"biān","duan":[{"e":"竹輿也。","n":"公羊傳曰。脅我而歸之。筍將而來也。何曰。筍者、竹箯。一名編輿。齊魯以北名之曰筍。將、送也。釋文曰。筍音峻。史、漢張耳傳曰。貫高箯輿前。服虔曰。箯音編。編竹木如今峻。可以糞除也。韋昭曰。輿如今輿牀。人舁以行。按公羊、史記、說文輿皆去聲。亦作轝、作𣝑。"}]},"笯":{"expl":"鳥籠也。从竹奴聲。","rad":"竹","fq":"乃故切","vol":"05","py":"nú","duan":[{"e":"鳥籠也。","n":"方言。籠、南楚江沔之閒謂之篣。或謂之笯。懷沙曰。鳳皇在笯。洪興祖補注引說文。笯、籠也。南楚謂之笯。豈洪氏所見本異與。"}]},"竿":{"expl":"竹梃也。从竹干聲。","rad":"竹","fq":"古寒切","vol":"05","py":"ɡān","duan":[{"e":"竹梃也。","n":"木部曰。梃、一枚也。按梃之言挺也。謂直也。衞風曰。籊籊竹竿。引伸之木直者亦曰竿。凡干旄、干旟、干旌皆竿之假借。又莊子竿牘卽𥳑牘也。"}]},"籱":{"expl":"罩魚者也。从竹靃聲。","rad":"竹","fq":"竹角切","vol":"05","py":"zhuó","duan":[{"e":"𦋇魚者也。","n":"網部曰。𦋇、捕魚器也。小雅傳曰。𦋇、篧也。釋器曰。篧謂之𦋇。李巡云。篧、編細竹以爲𦋇、捕魚也。孫炎云。今楚篧也。"}]},"箇":{"expl":"竹枚也。从竹固聲。","rad":"竹","fq":"古賀切","vol":"05","py":"ɡè","duan":[{"e":"竹枚也。","n":"竹梃自其徑直言之。竹枚自其圜圍言之。一枚謂之一箇也。方言曰。箇、枚也。"}]},"薰":{"expl":"香艸也。从艸熏聲。","rad":"艸","fq":"許云切","vol":"01","py":"xūn","duan":[{"e":"香艸也。","n":"左傳曰。一薰一蕕。蜀都賦劉注曰。葉曰蕙。根曰薰。張揖注上林賦曰。蕙、薰艸也。陳藏器曰。薰卽是零陵香也。郭注西山經曰。蕙、蘭屬也。非薰葉。"}]},"筊":{"expl":"竹索也。从竹交聲。","rad":"竹","fq":"胡茅切","vol":"05","py":"jiǎo","duan":[{"e":"竹索也。","n":"謂用析竹皮爲繩索也。今之䈼纜也。漢溝洫志曰。搴長茭兮湛美玉。如淳曰。茭、草也。一曰竿也。臣瓚曰。竹索絙謂之茭。所以引置土石也。師古曰。瓚說是也。茭字宜从竹。風俗通、後漢禮儀志皆言葦筊。謂葦索也。"}]},"筰":{"expl":"筊也。从竹作聲。","rad":"竹","fq":"在各切","vol":"05","py":"zuó","duan":[{"e":"筊也。","n":"廣韵曰。笮筰二同。竹索也。西南夷尋之以渡水。按西南夷有筰縣。在越巂。其名本此。或从艸作筰。非也。"}]},"𥮒":{"expl":"蔽絮簀也。从竹沾聲。讀若錢。","rad":"竹","fq":"昨鹽切","vol":"05","py":"qián","duan":[{"e":"潎絮簀也。","n":"潎、各本作蔽。今正。廣韵曰。𥮒、漂絮簀也。漂與潎同義。水部曰。潎、於水中擊絮也。潎絮簀卽今做紙密緻竹簾也。潎絮莊子所謂洴澼纊。卽做紙之事。系部曰。紙、絮一𥮒也。謂絮一𥮒成一紙也。紙之初起用敝布魚网爲之。用水中擊絮之法成之。紙字、𥮒字載於說文。則紙之由來遠矣。"}]},"箑":{"expl":"扇也。从竹疌聲。","rad":"竹","fq":"山洽切","vol":"05","py":"shà","duan":[{"e":"扇也。","n":"戸部曰。扇、扉也。扉可開合。故箑亦名扇。方言。扇、自關而東謂之箑。自關而西謂之扇。郭曰。今江東亦通名扇爲箑。按今江東皆曰扇。無言箑者。凡江東方言見於郭注者今多不同。葢由時移世易。士民遷徒不常故也。士喪禮下注曰。翣、扇也。此言經文假翣爲箑也。"}]},"籠":{"expl":"舉土器也。一曰笭也。从竹龍聲。","rad":"竹","fq":"盧紅切","vol":"05","py":"lónɡ","duan":[{"e":"擧土器。","n":"木部曰。㭒一曰徒土輂。齊人語也。一作梩。手部曰捄、盛土於梩中也。是則籠卽梩也。"}]},"䉴":{"expl":"袌也。从竹襄聲。","rad":"竹","fq":"如兩切","vol":"05","py":"ránɡ","duan":[{"e":"袌也。","n":"衣部曰。袌、褱也。此謂竹器可以中藏一切者。音義如瓜瓤之瓤。篇、韵皆云。䉴䉛、𥂖米竹器。"}]},"䇘":{"expl":"可以收繩也。从竹，象形，中象人手所推握也。","rad":"竹","fq":"胡誤切","vol":"05","py":"hù","duan":[{"e":"可㠯收繩者也。","n":"者字今補。收當作糾。聲之誤也。糾、絞也。今絞繩者尙有此器。"}]},"簝":{"expl":"宗廟盛肉竹器也。从竹尞聲。《周禮》：“供盆簝以待事。”","rad":"竹","fq":"洛蕭切","vol":"05","py":"liáo","duan":[{"e":"宗廟盛肉竹器也。","n":"牛人。其盆簝以待事。注。盆所以盛血。簝受肉籠也。"}]},"𥴧":{"expl":"飲牛筐也。从竹豦聲。方曰筐，圜曰𥴧。","rad":"竹","fq":"居許切","vol":"05","py":"jǔ","duan":[{"e":"食牛匡也。","n":"食各本作飲。誤。韵會作飯。按萎下曰食牛。䬴下曰食馬。今正作食。匚部曰。匡、飯器、筥也。𥴧、匡之圜者。飯牛用之。今字通作筥。許𥴧與筥別。"}]},"篼":{"expl":"飲馬器也。从竹兜聲。","rad":"竹","fq":"當侯切","vol":"05","py":"dōu","duan":[{"e":"食馬器也。","n":"方言。飤馬橐、自關而西謂之裺囊。或謂之裺篼。或謂之㡞篼。燕齊之閒謂之帪。"}]},"𦺇":{"expl":"水萹茿。从艸从水，毒聲。讀若督。","rad":"艸","fq":"徒沃切","vol":"01","py":"dú","duan":[{"e":"水萹𦯋也。","n":"謂萹𦯋之生於水者、謂之𦺇也。統言則曰萹𦯋。析言則有水陸之異。異其名因異其字。詩衞風綠竹猗猗音義曰。竹、韓詩作𦺇。萹𦯋也。石經亦作𦺇。按石經者、葢漢一字石經。魯詩也。西京賦李注。引韓詩綠䓯如簀。玉篇曰。䓯同𦺇。"}]},"籚":{"expl":"積竹矛𢧢矜也。从竹盧聲。《春秋國語》曰：“朱儒扶籚。”","rad":"竹","fq":"洛乎切","vol":"05","py":"lú","duan":[{"e":"積竹予𢧢矝也。","n":"積竹見殳部。矜、柄也。考工記。攻木之工。輪輿弓廬匠車梓。注。廬、矛𢧢矜柲也。按廬者、籚之假借字也。釋文曰。廬本或作重籚。"}]},"箝":{"expl":"籋也。从竹拑聲。","rad":"竹","fq":"巨淹切","vol":"05","py":"qián","duan":[{"e":"籋也。","n":"拑、脅持也。以竹脅持之曰箝。以鐵有所劫束曰鉗。書史多通用。"}]},"籋":{"expl":"箝也。从竹爾聲。","rad":"竹","fq":"尼輒切","vol":"05","py":"niè","duan":[{"e":"箝也。","n":"二字雙聲。夾取之器曰籋。今人以銅鐵作之。謂之鑷子。"}]},"簦":{"expl":"笠蓋也。从竹登聲。","rad":"竹","fq":"都滕切","vol":"05","py":"dēnɡ","duan":[{"e":"笠葢也。","n":"笠而有柄如葢也。卽今之雨繖。史記。躡屩擔簦。按簦亦謂之笠。渾言不別也。士喪禮下篇。燕器杖笠翣。注曰。笠、竹𥱀葢也。云葢而簦也。又按疏云。𥱀、竹靑皮。恐非是。𥱀疑同箁。竹箬也。今人謂之箬帽。"}]},"笠":{"expl":"簦無柄也。从竹立聲。","rad":"竹","fq":"力入切","vol":"05","py":"lì","duan":[{"e":"簦無柄也。","n":"汪氏龍曰。笠本以御暑。亦可御雨。故良耜傳。笠所以禦御暑雨。無羊傳。蓑所以御雨。笠所以備暑。都人士傳。臺所以御雨。笠所以御暑。三傳相合。今都人士暑雨互譌。以南山有臺疏、文選注正。"}]},"箱":{"expl":"大車牝服也。从竹相聲。","rad":"竹","fq":"息良切","vol":"05","py":"xiānɡ","duan":[{"e":"大車牝服也。","n":"考工記。大車牝服二柯。又參分柯之二。注云。大車平地載任之車。牝服長八尺。謂較也。鄭司農云。牝服謂車箱。服讀爲負。小雅傳曰。服、牝服也。箱、大車之箱也。按許與大鄭同。箱卽謂大車之輿也。毛二之。大鄭一之。要無異義。後鄭云較者。以左右有㒳較。故名之曰箱。其實一也。假借爲篋笥之稱。又假借爲東西室之稱。禮經箱字俗改爲廂字。非也。"}]},"篚":{"expl":"車笭也。从竹匪聲。","rad":"竹","fq":"敷尾切","vol":"05","py":"fěi","duan":[{"e":"車笭也。","n":"釋器曰。輿、革前謂之鞎。後謂之笰。竹前謂之禦。後謂蔽。按此對文則別之。散文則不別。詩言簟笰。毛曰。簟、方文席也。笰、車之蔽也。周禮巾車。薄蔽棼蔽等。蔽卽笰也。故鄭引翟茀以朝作翟蔽以朝。竹前竹後、許所謂車笭也。廣雅曰。筤謂之𥫵。又曰。陽門、簈篂、雀目、蔽簹也。皆謂車笭。笭之言櫺也。言其昤曨也。茀、詩碩人从艸。鄭驅从竹。从竹者誤也。茀之言蔽也。篚是正字。茀是假借字。如儀禮今文作厞。古文作茀。厞茀同字。"}]},"笭":{"expl":"車笭也。从竹令聲。一曰笭，籯也。","rad":"竹","fq":"郎丁切","vol":"05","py":"línɡ","duan":[{"e":"車笭也。从竹。令聲。","n":"郎丁切。十一部。"}]},"𥰨":{"expl":"搔馬也。从竹剡聲。","rad":"竹","fq":"丑廉切","vol":"05","py":"tán","duan":[{"e":"所㠯搔馬也。","n":"所以二字今補。廣韵。刮馬篦也。"}]},"策":{"expl":"馬箠也。从竹朿聲。","rad":"竹","fq":"楚革切","vol":"05","py":"cè","duan":[{"e":"馬箠也。","n":"馬𥬲曰策。以策擊馬曰敇。經傳多假策爲𠕋。又計謀曰籌策者。策猶籌。籌猶筭。筭所以計曆數。謀而得之。猶用筭而得之也。故曰筭、曰籌、曰策、一也。張良借箸爲籌。"}]},"萹":{"expl":"萹茿也。从艸扁聲。","rad":"艸","fq":"方沔切","vol":"01","py":"biān","duan":[{"e":"萹𦯋也。","n":"三字句。釋艸云。竹萹蓄。按竹者釋毛詩衞風之竹也。韓、魯詩皆作𦺇。毛詩獨叚借作竹。爾雅與毛詩合。𦯋蓄曡韵、通用。本艸經亦作萹蓄。"}]},"箠":{"expl":"擊馬也。从竹𡍮聲。","rad":"竹","fq":"之壘切","vol":"05","py":"chuí","duan":[{"e":"所㠯擊馬也。","n":"所以二字今補。假借爲杖人之稱。漢書定箠令是也。周禮假𡍮爲箠。垂氏掌共燋契是也。"}]},"𥬲":{"expl":"箠也。从竹朵聲。","rad":"竹","fq":"陟瓜切","vol":"05","py":"zhuā","duan":[{"e":"𥴓也。","n":"𥬲檛古今字。亦作簻。左傳。繞朝贈之以策。杜預曰。馬檛也。檛婦翁字本从木。後人又改从手。"}]},"笍":{"expl":"羊車騶箠也。箸箴其耑，長半分。从竹内聲。","rad":"竹","fq":"陟衞切","vol":"05","py":"zhuì","duan":[{"e":"羊車騶箠也。箸箴其耑長半分。","n":"金部曰。𨫔、羊車箠也。耑有鐵。匸部曰。匿讀如羊車騶箠之𨫔。羊車見考工記。鄭曰。羊、善也。善車若今定張車。釋名曰。羊、祥也。祥、善也。羊車、善飾之車。今犢車是也。馬部曰。騶、𢋁御也。月令注曰。七騶謂趣馬。主爲諸官駕說者也。左傳。程鄭爲乗馬御。六騶屬焉。使訓羣騶知禮。按騶卽御。騶箠者、御車之馬箠也。箸箴其耑長半分。箴當作鍼。所謂耑有鐵可以䘏勿而椓刺之。善飾之車駕之以犢。馳驟不揮鞭策。惟用箴刺而促之。淮南道應訓字作錣。高曰。策馬捶端有鐵以刺馬謂之錣。錣與笍音義皆同。"}]},"籣":{"expl":"所以盛弩矢，人所負也。从竹闌聲。","rad":"竹","fq":"洛干切","vol":"05","py":"lán","duan":[{"e":"所㠯盛弩矢。人所負也。","n":"信陵君列傳曰。平原君負韊矢。韊卽籣字。字林作韊。玉篇作䪍。索隠曰。如今之胡鹿而短。胡鹿、廣韵作弧簶。箭室也。按西京、吳都、魏都賦皆云蘭錡。劉逵曰。受他兵曰蘭。受弩曰錡。蘭字皆當从竹。"}]},"箙":{"expl":"弩矢箙也。从竹服聲。《周禮》：“仲秋獻矢箙。”","rad":"竹","fq":"房六切","vol":"05","py":"fú","duan":[{"e":"弩矢箙也。","n":"司弓矢曰。中秋獻矢箙。注曰。箙、盛矢器也。以獸皮爲之。按本以竹木爲之。故字从竹。國語。檿弧萁服。韋昭曰。萁、木名。服、房也。小雅。象弭魚服。皆假服爲箙。"}]},"䇬":{"expl":"栙雙也。从竹朱聲。","rad":"竹","fq":"陟輸切","vol":"05","py":"zhū","duan":[{"e":"栙雙也。","n":"栙雙見木部。廣雅。栙雙謂之䇬。廣韵四江曰。栙䉶者、帆未張也。又曰。䉶者、帆也。按以䈼席爲帆曰栙雙。故字或皆从竹。今大船之帆多用䈼席是也。"}]},"笘":{"expl":"折竹箠也。从竹占聲。潁川人名小兒所書寫爲笘。","rad":"竹","fq":"失廉切","vol":"05","py":"shān","duan":[{"e":"折竹箠也。","n":"折竹爲箠。箠之便易者也。"}]},"笪":{"expl":"笞也。从竹旦聲。","rad":"竹","fq":"當割切","vol":"05","py":"dá","duan":[{"e":"笞也。","n":"笪者、可以撻人之物。"}]},"笞":{"expl":"擊也。从竹台聲。","rad":"竹","fq":"丑之切","vol":"05","py":"chī","duan":[{"e":"擊也。","n":"疑奪所㠯二字。笞所以擊人者。因之謂擊人爲笞也。方言引傳曰。慈母之怒子也。雖折葼笞之。其惠存焉。後世笞杖徒流大辟五㓝。制於隨唐。至於今日。笞有名無實。"}]},"籤":{"expl":"驗也。一曰銳也，貫也。从竹韱聲。","rad":"竹","fq":"七廉切","vol":"05","py":"qiān","duan":[{"e":"驗也。","n":"驗當作譣。占譣然不也。小徐曰。籤出其處爲驗也。"}]},"茿":{"expl":"萹茿也。从艸，筑省聲。","rad":"艸","fq":"陟玉切","vol":"01","py":"zhú","duan":[{"e":"萹筑也。从艸。𦯋省聲。","n":"陟玉切。三部。按此不云𢀜聲而云筑省聲者。以𢀜字、工聲。筑字、竹亦聲也。𦯋（茿）篆鍇本在後䓊下范上。"}]},"𥴫":{"expl":"㮄也。从竹殿聲。","rad":"竹","fq":"徒魂切","vol":"05","py":"tún","duan":[{"e":"榜也。","n":"木部曰。榜所以輔弓弩也。檢柙弓弩必攷擊之。故廣雅曰。榜、擊也。引伸之義也。史、漢多言榜笞、榜箠。"}]},"箴":{"expl":"綴衣箴也。从竹咸聲。","rad":"竹","fq":"職深切","vol":"05","py":"zhēn","duan":[{"e":"綴衣箴也。","n":"綴衣、聯綴之也。謂籤之使不散。若用以縫則从金之鍼也。尙書贅衣卽綴也。引伸之義爲箴規。古箴鍼通用。風俗通曰。衞大夫箴莊子。今左傳作鍼莊子。"}]},"箾":{"expl":"以竿擊人也。从竹削聲。虞舜樂曰箾韶。","rad":"竹","fq":"所角切","vol":"05","py":"shuò","duan":[{"e":"㠯竿擊人也。","n":"西京賦曰。飛䍐潚箾。薛曰。潚箾、䍐形也。按䍐者、网之以竿爲柄者也。左傳。舞象箾南籥。杜曰。象箾、舞所執。南籥、以籥舞也。箾不知何等器。豈以竿舞與。"}]},"竽":{"expl":"管三十六簧也。从竹亏聲。","rad":"竹","fq":"羽俱切","vol":"05","py":"yú","duan":[{"e":"管三十六簧也。","n":"管下當有樂字。凡竹爲者皆曰管樂。周禮笙師。掌敎龡竽。大鄭曰。竽三十六簧。按據廣雅竽三十六管。然則管皆有簧也。通卦驗、風俗通皆云長四尺二寸。竽與笙之管皆列於匏。宋書樂志曰。竽今亡。"}]},"笙":{"expl":"十三簧。象鳳之身也。笙，正月之音。物生，故謂之笙。大者謂之巢，小者謂之和。从竹生聲。古者隨作笙。","rad":"竹","fq":"所庚切","vol":"05","py":"shēnɡ","duan":[{"e":"十三簧。","n":"蒙上管樂而言。故不云管樂也。大鄭周禮注曰。笙十三簧。按廣雅云笙十三管。亦每管有簧也。"}]},"簧":{"expl":"笙中簧也。从竹黃聲。古者女媧作簧。","rad":"竹","fq":"戶光切","vol":"05","py":"huánɡ","duan":[{"e":"笙中簧也。","n":"小雅。吹笙𡔷簧。傳曰。簧、笙簧也。吹笙則簧𡔷矣。按經有單言簧者、謂笙也。王風左執簧傳曰。黃、笙也是也。"}]},"䈕":{"expl":"簧屬。从竹是聲。","rad":"竹","fq":"是支切","vol":"05","py":"shí","duan":[{"e":"簧屬。","n":"今之鎖。簧以張之。䈕以斂之。則启矣。其用與笙中黃同也。"}]},"簫":{"expl":"參差管樂。象鳳之翼。从竹肅聲。","rad":"竹","fq":"穌彫切","vol":"05","py":"xiāo","duan":[{"e":"參差管樂。","n":"言管樂之列管參差者。竽笙列管雖多而不參差也。周禮小師注。簫、編小竹管如今賣飴餳所吹者。周頌箋同。廣雅云。大者二十三管。小者十六管。王逸注楚辭云。參差洞簫也。"}]},"筒":{"expl":"通簫也。从竹同聲。","rad":"竹","fq":"徒弄切","vol":"05","py":"dònɡ","duan":[{"e":"通簫也。","n":"所謂洞簫也。廣雅云。大者二十三管無底是也。漢章帝紀。吹洞簫。如淳曰。洞者、通也。簫之無底者也。"}]},"籟":{"expl":"三孔龠也。大者謂之笙，其中謂之籟，小者謂之箹。从竹賴聲。","rad":"竹","fq":"洛帶切","vol":"05","py":"lài","duan":[{"e":"三孔龠也。","n":"龠部曰。龠、管樂。六孔。以和衆聲。按毛詩傳曰。龠六孔。許龠下從之。此云三孔龠者、謂龠之三孔者則名籟也。鄭注笙師、少儀、明掌位皆云。籥如笛、三孔。鄭專謂籟耳。今本說文龠下爲淺人所亂。然於此可以正彼。莊子人籟、地籟、天籟、引伸義也。"}]},"𦼰":{"expl":"芞輿也。从艸楬聲。","rad":"艸","fq":"去謁切","vol":"01","py":"qiè","duan":[{"e":"藒車、","n":"逗。"}]},"箹":{"expl":"小籟也。从竹約聲。","rad":"竹","fq":"於角切","vol":"05","py":"yuè","duan":[{"e":"小籟也。从竹。約聲。","n":"於角切。二部。"}]},"管":{"expl":"如篪，六孔。十二月之音。物開地牙，故謂之管。从竹官聲。","rad":"竹","fq":"古滿切","vol":"05","py":"ɡuǎn","duan":[{"e":"如篪。六孔。","n":"篪有七孔。見大鄭笙師注。管之異於篪者、孔六耳。賈逵、大鄭、許君、應劭風俗通、蔡邕月令章句、張揖廣雅皆云如篪六孔。惟後鄭周禮注。詩箋云如篴而小。倂㒳而吹之。今大予樂官有焉。"}]},"篎":{"expl":"小管謂之篎。从竹眇聲。","rad":"竹","fq":"亡沼切","vol":"05","py":"miǎo","duan":[{"e":"小管謂之篎。","n":"釋樂。大管謂之簥。其中謂之篞。小者謂之篎。許無簥篞字者。許所據不从竹。"}]},"笛":{"expl":"七孔筩也。从竹由聲。羌笛三孔。","rad":"竹","fq":"徒歴切","vol":"05","py":"dí","duan":[{"e":"七孔筩也。","n":"文選李注引說文。笛七孔。長一尺四寸。今人長笛是也。此葢以注家語益之。風俗通亦云。長尺四寸。七孔。周禮笙師字作篴。大鄭云。杜子春讀篴如蕩滌之滌。今人所吹五空竹笛。按篴笛古今字。大鄭注上作篴。下作笛。後人妄改一之。大鄭云五孔。馬融賦亦云。易京君明識音律。故本四孔加以一。君明所加孔後出。是謂商聲五音畢。然則漢時長笛五孔甚明。云七孔者、禮家說古笛也。許與大鄭異"}]},"筑":{"expl":"以竹曲五弦之樂也。从竹从𢀜。𢀜，持之也。竹亦聲。","rad":"竹","fq":"張六切","vol":"05","py":"zhú","duan":[{"e":"㠯竹曲五弦之樂也。","n":"以竹曲不可通。廣韵作以竹爲。亦繆。惟吳都賦。李注作似箏、五弦之樂也。近是。箏下云五弦{𥫗+(工丮[左右])}(筑)身。然則{𥫗+(工丮[左右])}(筑)似箏也。但高注淮南曰。{𥫗+(工丮[左右])}(筑)曲二十一弦。可見此器絫呼之名{𥫗+(工丮[左右])}曲。釋名。{𥫗+(工丮[左右])}(筑)以竹𡔷之也。御覽引樂書云。以竹尺擊之。如擊琴然。今審定其文。當云{𥫗+(工丮[左右])}(筑)曲以竹𡔷弦之樂也。高云二十一弦。樂書云十三弦。{𥫗+(工丮[左右])}(筑)弦數未審。古者箏五弦。說文殆{𥫗+(工丮[左右])}(筑)下𡔷弦與箏下五弦互譌耳。箏下云{𥫗+(工丮[左右])}(筑)身。則{𥫗+(工"}]},"箏":{"expl":"鼓弦竹身樂也。从竹爭聲。","rad":"竹","fq":"側莖切","vol":"05","py":"zhēnɡ","duan":[{"e":"五弦{𥫗+(工丮[左右])}(筑)身樂也。","n":"各本作𡔷弦竹身。不可通。今依太平御覽正。風俗通曰。箏、謹按樂記五弦{𥫗+(工丮[左右])}(筑)身也。今幷梁二州箏形如瑟。不知誰所改作也。或曰秦蒙恬所造。據此知古箏五弦。恬乃改十二弦。變形如瑟耳。魏晉以後。箏皆如瑟十二弦。唐至今十三弦。{𥫗+(工丮[左右])}(筑)似箏、細項。古{𥫗+(工丮[左右])}(筑)與箏相似不同瑟也。言{𥫗+(工丮[左右])}(筑)身者、以見形如瑟者之非古也。言五弦{𥫗+(工丮[左右])}(筑)身者、以見箏之弦少於{𥫗+(工丮[左右])}(筑)也。宋書樂志改{𥫗+(工丮[左右])}(筑)身爲瑟身。誤矣。"}]},"箛":{"expl":"吹鞭也。从竹孤聲。","rad":"竹","fq":"古乎切","vol":"05","py":"ɡū","duan":[{"e":"吹鞭也。","n":"風俗通曰。漢書舊注。箛者、吹鞭也。急就篇曰。箛篍起居課後先。師古曰。箛、吹鞭也。篍、吹筩也。起居謂晨起夜臥及休食時。督作之司以此二者爲之節度。宋書樂志晉先蠶注。吹小箛大箛。按云鞭者、如長笛賦云裁以當簻便易持也。"}]},"篍":{"expl":"吹筩也。从竹秋聲。","rad":"竹","fq":"七肖切","vol":"05","py":"qiū","duan":[{"e":"吹筩也。","n":"吹鞭葢葭爲之。吹筩葢竹爲之。風俗通曰。漢書注。篍、筩也。言其聲音篍篍。名自定也。"}]},"籌":{"expl":"壺矢也。从竹壽聲。","rad":"竹","fq":"直由切","vol":"05","py":"chóu","duan":[{"e":"壷矢也。","n":"禮記投壷篇曰。籌、室中五扶。堂上七扶。庭中九扶。注曰。籌、矢也。按引伸爲泛偁。又謂計筭爲籌度。"}]},"簺":{"expl":"行棊相塞謂之簺。从竹从塞，塞亦聲。","rad":"竹","fq":"先代切","vol":"05","py":"sài","duan":[{"e":"行棊相塞謂之簺。","n":"格五、見吾丘壽王傳。劉德曰。格五棊行塞法曰。簺自乗五。至五格不得行。故云格五。莊子作博塞。"}]},"䒗":{"expl":"芞輿也。从艸气聲。","rad":"艸","fq":"去訖切","vol":"01","py":"qì","duan":[{"e":"芞輿也。","n":"三字苟。"}]},"簙":{"expl":"局戲也。六箸十二棊也。从竹博聲。古者烏胄作簙。","rad":"竹","fq":"補各切","vol":"05","py":"bó","duan":[{"e":"局戲也。六箸十二棊也。","n":"古戲、今不得其實。箸、韓非所謂博箭。招䰟注云。箟簬作箸。故其字从竹。"}]},"篳":{"expl":"藩落也。从竹畢聲。《春秋傳》曰：“篳門圭窬。”","rad":"竹","fq":"卑吉切","vol":"05","py":"bì","duan":[{"e":"藩落也。","n":"藩落猶俗云籬落也。篳之言蔽也。"}]},"𥴨":{"expl":"蔽不見也。从竹愛聲。","rad":"竹","fq":"烏代切","vol":"05","py":"ài","duan":[{"e":"蔽不見也。","n":"爾雅。薆、隱也。方言。揜、翳、薆也。其字皆當从竹。竹善蔽。九歌曰。余處幽篁兮終不見天是也。大雅。愛莫助之。毛曰。愛、隱也。假借字也。邶風。愛而不見。郭注方言作薆而。"}]},"䉷":{"expl":"隿射所蔽者也。从竹嚴聲。","rad":"竹","fq":"語杴切","vol":"05","py":"yán","duan":[{"e":"隿射者所蔽者也。","n":"依晉灼補上者字。此卽射雉之翳也。亦謂之廩。廣雅廩作箖。"}]},"篽":{"expl":"禁苑也。从竹御聲。《春秋傳》曰：“澤之目篽。”","rad":"竹","fq":"魚舉切","vol":"05","py":"yǔ","duan":[{"e":"禁苑也。","n":"宣帝紀。詔池籞未御幸者。假與貧民。蘇林曰。折竹以繩綿連禁禦。使人不得往來。律名爲籞。應劭曰。籞者、禁苑也。按蘇、應說與許合。元帝紀。詔罷嚴籞池田。假與貧民。西京賦云。洪池淸籞。淸籞猶漢書云嚴篽也。晉灼釋嚴籞爲射苑。故引許䉷字之解。謂嚴與䉷同。可以訓射。亦迂曲矣。"}]},"筭":{"expl":"長六寸。計歷數者。从竹从弄。言常弄乃不誤也。","rad":"竹","fq":"蘇貫切","vol":"05","py":"suàn","duan":[{"e":"長六寸。所㠯計曆數者。","n":"所㠯二字今補。漢志云。筭法用竹徑一分、長六寸。二百七十一枚而成六觚。爲一握。此謂筭籌。與算數字各用。計之所謂算也。古書多不別。"}]},"算":{"expl":"數也。从竹从具。讀若筭。","rad":"竹","fq":"蘇管切","vol":"05","py":"suàn","duan":[{"e":"數也。","n":"論語。何足算也。鄭曰。算、數也。古假選爲算。如邶風不可選也。車攻序因田獵而選車徒。選皆訓數是也。又假撰爲算。如大司馬羣吏撰車徒。鄭曰。撰讀曰算。謂數擇之也是也。筭爲算之器。算爲筭之用。二字音同而義別。"}]},"笑":{"expl":"此字本闕。","rad":"竹","fq":"私妙切","vol":"05","py":"xiào","duan":[{"e":"喜也。从竹。从犬。","n":"徐鼎臣說孫愐唐韵引說文云。𥬇、喜也。从竹、从犬。而不述其義。攷孫愐唐韵序云。仍篆𣜩石經勒存正體。幸不譏煩。葢唐韵每字皆勒說文篆體。此字之从竹犬。孫親見其然。是以唐人無不从犬作者。干祿字書云。咲通、𥬇正。五經文字力尊說文者也。亦作𥬇喜也。从竹下犬。玉篇竹部亦作𥬇。廣韵因唐韵之舊亦作𥬇。此本無可疑者。自唐玄度九經字㨾始先笑後𥬇。引楊承慶字統異說云从竹从夭。竹爲樂器。君子樂然後笑。字統每與說文乖異。見玄應書。葢楊氏求从犬之故不得。是用改夭形聲。唐氏從之。李陽冰遂云竹得風。其體夭屈如人之笑。自後徐楚金缺此篆。鼎臣竟改說文𥬇作笑。而集韵、類篇乃有笑無𥬇。宋以後經籍無𥬇字矣。今以顧野王、孫愐、顏元孫、張參"}]},"簃":{"expl":"閣邊小屋也。从竹移聲。《說文》通用誃。","rad":"竹","fq":"弋支切","vol":"05","py":"yí","duan":[]},"筠":{"expl":"竹皮也。从竹均聲。","rad":"竹","fq":"王春切","vol":"05","py":"yún","duan":[]},"天":{"expl":"顚也。至高無上，从一、大。","rad":"一","fq":"他前切","vol":"01","py":"tiān","duan":[{"e":"顚也。","n":"此以同部曡韵爲訓也。凡門聞也、戸護也、尾微也、髮拔也皆此例。凡言元始也、天顚也、丕大也、吏治人者也皆於六書爲轉注而微有差別。元始可互言之。天顚不可倒言之。葢求義則轉移皆是。舉物則定名難假。然其爲訓詁則一也。顚者、人之頂也。以爲凡高之偁。始者、女之初也。以爲凡起之偁。然則天亦可爲凡顚之偁。臣於君、子於父、妻於夫、民於食皆曰天是也。"}]},"祭":{"expl":"祭祀也。从示，以手持肉。","rad":"示","fq":"子例切","vol":"01","py":"jì","duan":[{"e":"祭祀也。","n":"統言則祭祀不別也。"}]},"苺":{"expl":"馬苺也。从艸母聲。","rad":"艸","fq":"武辠切","vol":"01","py":"měi","duan":[{"e":"馬莓也。","n":"𦷱篆不廁於此。則非山莓也。"}]},"笏":{"expl":"公及士所搢也。从竹勿聲。案：籒文作𡇉，象形。義云佩也。古笏佩之。此字後人所加。","rad":"竹","fq":"呼骨切","vol":"05","py":"hù","duan":[]},"篦":{"expl":"導也。今俗謂之篦。从竹𣬉聲。","rad":"竹","fq":"邊兮切","vol":"05","py":"bì","duan":[]},"篙":{"expl":"所以進船也。从竹高聲。","rad":"竹","fq":"古牢切","vol":"05","py":"ɡāo","duan":[]},"箕":{"expl":"簸也。从竹；𠀠，象形；下其丌也。凡箕之屬皆从箕。","rad":"箕","fq":"居之切","vol":"05","py":"jī","duan":[{"e":"所㠯簸者也。","n":"所㠯者三字今補。全書中所㠯字爲淺人刪者多矣。小雅曰。維南有箕。不可以簸揚。廣韵引世本曰。箕帚、少康作。按簸揚與受𡊅皆用箕。"}]},"簸":{"expl":"揚米去糠也。从箕皮聲。","rad":"箕","fq":"布火切","vol":"05","py":"bǒ","duan":[{"e":"揚米去𥹺也。","n":"與播布之義相近。"}]},"丌":{"expl":"下基也。薦物之丌。象形。凡丌之屬皆从丌。讀若箕同。","rad":"丌","fq":"居之切","vol":"05","py":"jī","duan":[{"e":"下基也。","n":"字亦作六。古多用爲今渠之切之其。墨子書其字多作六。六與？同也。"}]},"䢋":{"expl":"古之遒人，以木鐸記詩言。从辵从丌，丌亦聲。讀與記同。","rad":"丌","fq":"居吏切","vol":"05","py":"jì","duan":[{"e":"古之遒人㠯木鐸記詩言。","n":"左傳襄十四年師曠引夏書曰。遒人以木鐸徇于路。官師相規。工執藝事以諫。正月孟春。於是乎有之。杜云。木鐸徇于路。采歌謠之言也。何注公羊曰。五榖畢入。民皆居宅。男女同巷。相從夜績。從十月盡、正月止。男女有所怨恨。相從而歌。飢者歌其食。勞者歌其事。男年六十、女年五十無子者。官衣食之。使之民閒求詩。鄉移於邑。邑移於國。國以聞於天子。故王者不出牖戸。盡知天下。食貨志曰。孟春之月。行人振木鐸徇於路。㠯采詩獻之大師。比其音律。以聞於天子。故曰王者不窺牖戸而知天下。遒人卽班之行人。以木鐸巡於路。使民閒出男女歌詠。記之𥳑牘。遞薦於天子。故其字從辵？。辵者、行也。？者、薦也。記與？㬪韵也。僞尙書襲左傳。而不言振木鐸"}]},"典":{"expl":"五帝之書也。从冊在丌上，尊閣之也。莊都說，典，大冊也。","rad":"丌","fq":"多殄切","vol":"05","py":"diǎn","duan":[{"e":"五帝之書也。","n":"三墳五典見左傳。"}]},"顨":{"expl":"巽也。从丌从𩔊 。此《易》顨卦“爲長女，爲風”者。","rad":"丌","fq":"蘇困切","vol":"05","py":"xùn","duan":[{"e":"巺也。","n":"具也。"}]},"畀":{"expl":"相付與之。約在閣上也。从丌甶聲。","rad":"丌","fq":"必至切","vol":"05","py":"bì","duan":[{"e":"相付与之約在閣上也。","n":"与舊作與。勺部曰。与與予同。予、推予也。與、黨與也。今正。約當作物。古者物相与必有藉。藉卽閣也。故其字从丌。疑此有奪文。當云相付与也。付与之物在閣上从？。祭統曰。夫祭有畀煇胞翟閽者。惠下之道也。畀之爲言與也。能以其餘畀其下者也。此謂上之与下。庋閣而命取之。"}]},"茖":{"expl":"艸也。从艸各聲。","rad":"艸","fq":"古額切","vol":"01","py":"ɡé","duan":[{"e":"艸也。","n":"釋艸。茖、山葱。按爾雅雖有此字。然許君果用爾雅。何以不云山葱而云艸也。凡所不知。寧從葢闕。"}]},"巽":{"expl":"具也。从丌𠨎聲。","rad":"丌","fq":"蘇困切","vol":"05","py":"xùn","duan":[{"e":"具也。","n":"孔子說易曰。巺、入也。巺乃愻之假借字。愻、順也。順故善入。許云具也者、巺之本義也。巺今作巽。"}]},"奠":{"expl":"置祭也。从酋。酋，酒也。下其丌也。《禮》有奠祭者。","rad":"丌","fq":"堂練切","vol":"05","py":"diàn","duan":[{"e":"置祭也。","n":"置祭者、置酒食而祭也。故从酋？。？者、所置物之質也。如置於席則席爲奠。引伸爲凡置之偁。又引伸爲奠高山大川之奠。定也。大玄天地㞟位。假㞟字爲之。"}]},"左":{"expl":"手相左助也。从𠂇、工。凡左之屬皆从左。","rad":"左","fq":"則箇切","vol":"05","py":"zuǒ","duan":[{"e":"𠂇手相左也。","n":"各本俱誤。今正。左者、今之佐字。說文無佐也。𠂇者、今之左字。𠂇部曰。左手也。謂左助之手也。以手助手是曰左。以口助手是曰右。"}]},"差":{"expl":"貳也。差不相值也。从左从𠂹。","rad":"左","fq":"初牙切","vol":"05","py":"chā","duan":[{"e":"貣也。左不相值也。","n":"貣各本作貳。左各本作差。今正。貣者、？之假借字。心部曰。？、失當也。失當卽所謂不相值也。釋言曰。爽、差也。爽、忒也。？與？葢本一字。尙書二衍忒。宋世家作貣。易四時不忒。京房作貣。管子全書皆以貣爲忒。貣與貳形易相誤。月令宿離不貸。釋文貸、他得切。徐音二。無有差貸。釋文貸、音二。又他得反。緇衣其儀不忒。釋文忒、他得反。又作貳、音二。漢費鳳碑貸與則德韵。婁氏釋作貳。皆貣之誤爲貳者也。貳與貣忒音旣脂之迥別。義則貳訓副也。副貳之解、何得同於差？乎。左氏傳其⺊貳圉。杜注貳、代也。按外傳作以代圉。謂用世次當立之圉。左傳作貳圉。謂副貳之圉。坊記注引之。此則當各依文爲釋。杜注左云貳、代也。似爲牽合。此云貣也者、"}]},"工":{"expl":"巧飾也。象人有規榘也。與巫同意。凡工之屬皆从工。","rad":"工","fq":"古紅切","vol":"05","py":"ɡōnɡ","duan":[{"e":"巧飾也。","n":"飾拭古今字。又部曰。㕞、飾也。巾部曰。飾、㕞也。聿部曰。𦘔、聿飾也。彡部曰。彡、毛飾畫文也。皆今之拭字也。此云巧飾也者。依古文作？爲訓。彡者飾畫文。巧飾者、謂如㡪人施廣領大袖以仰涂而領袖不污是也。惟孰於規榘乃能如是。引伸之凡善其事曰工。見小雅毛傳。"}]},"式":{"expl":"法也。从工弋聲。","rad":"工","fq":"賞職切","vol":"05","py":"shì","duan":[{"e":"法也。","n":"𢊁部法作灋。灋、㓝也。引伸之義爲式、用也。按周禮八灋八則九式異其文。注曰。則亦法也。式謂用財之節度。"}]},"巧":{"expl":"技也。从工丂聲。","rad":"工","fq":"苦絞切","vol":"05","py":"qiǎo","duan":[{"e":"技也。","n":"手部曰。技、巧也。"}]},"巨":{"expl":"規巨也。从工，象手持之。","rad":"工","fq":"其呂切","vol":"05","py":"jù","duan":[{"e":"規巨也。","n":"周髀筭經曰。圜出於方。方出於矩。矩出於九九八十一。故折矩以爲句廣三。股脩四。徑隅五。旣方其外。半之一矩。環而共盤。得成三四五。㒳矩共長二十有五。是謂積矩。用矩之道。平矩以正繩。偃矩以望高。覆矩以測湥。臥矩以知遠。環矩以爲圓。合矩以爲方。方屬地。圓屬天。天圓地方。方數爲典。以方出圓。按規矩二字猶言法度。古不分別。規圜矩方者、圜出於方。圜方皆出於矩也。夫部曰。規、有法度也。不言圜曰規。考工記。斬轂之道必矩其陰陽。注。矩謂刻識之也。凡識其廣長曰矩。故凡有所刻識皆謂之矩。"}]},"㠭":{"expl":"極巧視之也。从四工。凡㠭之屬皆从㠭。","rad":"㠭","fq":"知衍切","vol":"05","py":"zhǎn","duan":[{"e":"極巧視之也。","n":"工爲巧。故四工爲極巧。極巧視之、謂如離婁之明、公輸子之巧、旣竭目力也。凡展布字當用此。展行而㠭廢矣。玉篇曰。㠭今作展。"}]},"𡫳":{"expl":"窒也。从㠭从廾，窒宀中。㠭猶齊也。","rad":"㠭","fq":"穌則切","vol":"05","py":"sè","duan":[{"e":"窒也。","n":"穴部曰。窒、𡫳也。此與土部塞、音同義異。與心部㥶、音同義近。塞、隔也。隔、塞也。與𡫳窒訓別。㥶、實也。實、富也。與𡫳窒訓近。凡塡塞字皆當作𡫳。自塞行而𡫳㥶皆廢矣。"}]},"苷":{"expl":"甘艸也。从艸从甘。","rad":"艸","fq":"古三切","vol":"01","py":"ɡān","duan":[{"e":"甘艸也。","n":"所謂藥中國老。安和七十二種石、一千二百種艸者也。"}]},"巫":{"expl":"祝也。女能事無形，以舞降神者也。象人兩褎舞形。與工同意。古者巫咸初作巫。凡巫之屬皆从巫。","rad":"巫","fq":"武扶切","vol":"05","py":"wū","duan":[{"e":"巫祝也。","n":"依韵會本。三字一句。按祝乃覡之誤。巫覡皆巫也。故覡篆下緫言其義。示部曰。祝、祭主贊辭者。周禮祝與巫分職。二者雖相須爲用。不得以祝釋巫也。"}]},"覡":{"expl":"能齋肅事神明也。在男曰覡，在女曰巫。从巫从見。","rad":"巫","fq":"胡狄切","vol":"05","py":"xí","duan":[{"e":"能齊肅事神明者。","n":"楚語。民之精爽不𢤮貳者、而又能齊肅衷正。其知能上下比義。其聖能光遠宣朗。其明能光照之。其緫能聽徹之。如是則明神降之。在男曰覡。在女曰巫。是使制神之處位次主。而爲之牲器時服。韋注。齊、一也。肅、敬也。巫覡見鬼者。今說文齊作齋。非。國語神明作明神。非。"}]},"甘":{"expl":"美也。从口含一。一，道也。凡甘之屬皆从甘。","rad":"甘","fq":"古三切","vol":"05","py":"ɡān","duan":[{"e":"美也。","n":"羊部曰。美、甘也。甘爲五味之一。而五味之可口皆曰甘。"}]},"甛":{"expl":"美也。从甘从舌。舌，知甘者。","rad":"甘","fq":"徒兼切","vol":"05","py":"tián","duan":[{"e":"美也。","n":"周禮注恬酒。恬卽甛字。"}]},"𤯌":{"expl":"和也。从甘从麻。麻，調也。甘亦聲。讀若函。","rad":"甘","fq":"古三切","vol":"05","py":"ɡān","duan":[{"e":"和也。","n":"和當作盉。寫者亂之耳。皿部曰。盉、調味也。"}]},"猒":{"expl":"飽也。从甘从肰。","rad":"甘","fq":"於鹽切","vol":"05","py":"yān","duan":[{"e":"飽也。足也。","n":"足也二字依韵會增。淺人多改猒爲厭。厭專行而猒廢矣。猒與厭音同而義異。雒誥萬年猒于乃德。此古字當存者也。按飽足則人意倦矣。故引伸爲猒倦、猒憎。釋詁曰。豫射厭也是也。豫者、古以爲舒字。安也。亦緩也。洪範曰。豫曰急。豫猶怠也。猒厭古今字。猒饜正俗字。"}]},"甚":{"expl":"尤安樂也。从甘，从匹耦也。","rad":"甘","fq":"常枕切","vol":"05","py":"shèn","duan":[{"e":"尤安樂也。","n":"尤甘也。引伸凡殊尤皆曰甚。"}]},"曰":{"expl":"詞也。从口乙聲。亦象口气出也。凡曰之屬皆从曰。","rad":"曰","fq":"王代切","vol":"05","py":"yuè","duan":[{"e":"䛐也。","n":"䛐者、意內而言外也。有是意而有是言。亦謂之曰。亦謂之云。云曰、雙聲也。釋詁。粤于爰曰也。此謂詩書古文多有以曰爲爰者。故粤于爰曰四字可互相訓。以雙聲㬪韵相假借也。"}]},"𣆑":{"expl":"告也。从曰从冊，冊亦聲。","rad":"曰","fq":"楚革切","vol":"05","py":"cè","duan":[{"e":"吿也。","n":"按下云从曰从𠕋。會意。則當作𠕋吿也三字。𥳑牘曰𠕋。以𥳑吿誡曰？。𠕋行而？廢矣。"}]},"曷":{"expl":"何也。从曰匃聲。","rad":"曰","fq":"胡葛切","vol":"05","py":"hé","duan":[{"e":"何也。","n":"雙聲也。詩有言曷者。如曷不肅雝。箋云。曷、何也。有言害者。如害澣害不。傳云。害、何也。害者、曷之假借字。詩書多以害爲曷。釋詁。曷、止也。此以曷爲遏。釋言曰。曷、盍也。此亦假借。凡言何不者、急言之但云曷也。"}]},"芧":{"expl":"艸也。从艸予聲。可以爲繩。","rad":"艸","fq":"直呂切","vol":"01","py":"zhù","duan":[{"e":"艸也。","n":"上林賦蔣芧靑薠。張揖曰。芧三棱也。郭樸音杼。按三棱者、蘇頌圖經所謂葉似莎艸極長、莖三陵如削、高五六尺、莖端開花是也。江蘇蘆灘中極多。呼爲馬芧。音同宁。莖可繫物。亦可辮之爲索。南都賦。藨苧薠莞。李注引說文苧可以爲索。葢賦文本作芧。文𨕖上林賦亦作苧。苧者、芧之別字。"}]},"曶":{"expl":"出气詞也。从曰，象气出形。《春秋傳》曰：“鄭太子曶。”","rad":"曰","fq":"呼骨切","vol":"05","py":"hū","duan":[{"e":"出气䛐也。","n":"玉篇作？。出？者、其意也。？者、其言也。意內言外謂之䛐。此與心部忽音同義異。忽、忘也。若羽獵賦蠁曶如神、傳毅舞賦雲轉飄曶、漢樊敏碑奄曶滅形皆出气之意。倐之皃本當用此字。不當作忽忘字也。楊雄傳。於時人皆曶之。則假曶爲忽。古今人表仲忽作中曶。許云鄭大子曶。則未識名字取何義也。今則忽行而曶廢矣。"}]},"朁":{"expl":"曾也。从曰兓聲。《詩》曰：“朁不畏明。”","rad":"曰","fq":"七感切","vol":"05","py":"cǎn","duan":[{"e":"曾也。","n":"釋言、大雅傳、小雅箋同。八部曰。曾者、䛐之舒也。曾之言乃也。詳八部。"}]},"沓":{"expl":"語多沓沓也。从水从曰。遼東有沓縣。","rad":"曰","fq":"徒合切","vol":"05","py":"tà","duan":[{"e":"語多沓沓也。","n":"孟子、毛傳釋詩皆曰。泄泄猶沓沓也。引伸爲凡重沓字。假借爲達字。毛生民傳曰。達、達生也。先生、姜嫄之子先生者也。達生卽沓生。謂始生而如再生三生之易也。車攻傳曰。舄、達屨也。達屨卽沓屨。所謂複下曰舄也。板箋曰。女無憲憲然、無沓沓然。爲之制法度。達其意以成其惡。以達釋沓。是其理也。"}]},"曹":{"expl":"獄之兩曹也。在廷東。从㯥，治事者；从曰。","rad":"曰","fq":"昨牢切","vol":"05","py":"cáo","duan":[{"e":"獄㒳曹也。","n":"㒳曹、今俗所謂原吿被吿也。曹猶類也。史記曰。遣吏分曹逐捕。古文尙書。㒳造具備。史記㒳造一作㒳遭。㒳遭、㒳造卽㒳曹。古字多假借也。曹之引伸爲輩也。羣也。"}]},"乃":{"expl":"曳詞之難也。象气之出難。凡𠄎之屬皆从𠄎。","rad":"乃","fq":"奴亥切","vol":"05","py":"nǎi","duan":[{"e":"曳䛐之難也。","n":"玉篇䛐作離、非也。上當有者字。曳有矯拂之意。曳其言而轉之。若而、若乃皆是也。乃則其曳之難者也。春秋宣八年。日中而克葬。定十五年。日下昃乃克葬。公羊傳曰。而者何。難也。乃者何。難也。曷爲或言而、或言乃。乃難乎而也。何注。言乃者內而湥。言而者外而淺。按乃然而汝若、一語之轉。故乃又訓汝也。"}]},"𠧟":{"expl":"驚聲也。从乃省，西聲。籀文𠧟不省。或曰𠧟，往也。讀若仍。","rad":"乃","fq":"如乘切","vol":"05","py":"rénɡ","duan":[{"e":"驚聲也。从弓省。卤聲。","n":"卤聲宋本作西聲。不誤。趙鈔及俗刻作鹵聲。誤甚。从弓省者、从弓而未盡其曲折也。卤者、籒文西字。以西爲聲也。鍇本作从乃、卤省聲。非是。驚聲者、驚訝之聲。與乃字音義俱別。詩書史漢發語多用此字作迺。而流俗多改爲乃。按釋詁曰。仍迺侯乃也。以乃釋迺。則本非一字可知矣。西聲則古音當在十三部。古音西讀如詵。又讀如仙。"}]},"𠧴":{"expl":"气行皃。从乃𠧪聲。讀若攸。","rad":"乃","fq":"以周切","vol":"05","py":"yóu","duan":[{"e":"气行皃。","n":"𣜩作逌。禹貢。陽鳥攸居、豐水攸同、九州攸同。漢地理志攸皆作逌。逌之言于也。陽鳥于是南來得所也。與爰粤義同。劉歆書。逌人使者。謂行人之官也。"}]},"丂":{"expl":"气欲舒出。纸上礙於一也。丂，古文以爲亏字，又以爲巧字。凡丂之屬皆从丂。","rad":"丂","fq":"苦浩切","vol":"05","py":"kǎo","duan":[{"e":"气欲舒出？上礙於一也。","n":"？者、气欲舒出之象。一其上不能徑達。此釋字義而字形巳見。故不別言形也。苦浩切。古音在三部。"}]},"甹":{"expl":"亟詞也。从丂从由。或曰甹，俠也。三輔謂輕財者爲甹。","rad":"丂","fq":"普丁切","vol":"05","py":"pīnɡ","duan":[{"e":"亟䛐也。","n":"其意爲亟。其言爲甹。是曰意內言外。甹亦語䛐也。說文？？、爾雅作甹夆。假借字也。"}]},"寧":{"expl":"願詞也。从丂寍聲。","rad":"丂","fq":"奴丁切","vol":"05","py":"nínɡ","duan":[{"e":"願䛐也。","n":"其意爲願則其言爲寧。是曰意內言外。寍部曰。寍、安也。今字多假寧爲寍。寧行而寍廢矣。古文尙書葢有寍字。陸氏於大禹謨曰。寍、安也。說文安寍字如此。寧、願詞也。此陸氏依許分別二字。今本經宋開寶閒改竄。不可讀。"}]},"藎":{"expl":"艸也。从艸盡聲。","rad":"艸","fq":"徐刃切","vol":"01","py":"jìn","duan":[{"e":"艸也。","n":"蘇恭、掌禹錫皆云。俗名菉蓐艸。爾雅所謂王芻。詩淇澳之菉也。按說文有藎。又別有菉。則許意藎非菉矣。"}]},"𠀀":{"expl":"反丂也。讀若呵。","rad":"丂","fq":"虎何切","vol":"05","py":"hē","duan":[{"e":"反丂也。讀若呵。","n":"虎何切。十七部。"}]},"可":{"expl":"𦘫也。从口丂，丂亦聲。凡可之屬皆从可。","rad":"可","fq":"肯我切","vol":"05","py":"kě","duan":[{"e":"肎也。","n":"肎者、骨閒肉肎肎箸也。凡中其肎綮曰肎。可肎雙聲。"}]},"奇":{"expl":"異也。一曰不耦。从大从可。","rad":"可","fq":"渠羈切","vol":"05","py":"qí","duan":[{"e":"異也。","n":"不羣之謂。"}]},"哿":{"expl":"可也。从可加聲。《詩》曰：“哿矣富人。”","rad":"可","fq":"古我切","vol":"05","py":"ɡě","duan":[{"e":"可也。","n":"見小雅毛傳。"}]},"哥":{"expl":"聲也。从二可。古文以爲謌字。","rad":"可","fq":"古俄切","vol":"05","py":"ɡē","duan":[{"e":"聲也。","n":"此義未見用者。今呼兄爲哥。"}]},"叵":{"expl":"不可也。从反可。","rad":"可","fq":"普火切","vol":"05","py":"pǒ","duan":[]},"兮":{"expl":"語所稽也。从丂，八象气越亏也。凡兮之屬皆从兮。","rad":"兮","fq":"胡雞切","vol":"05","py":"xī","duan":[{"e":"語所稽也。","n":"兮稽㬪韵。稽部曰。畱止也。語於此少駐也。此與哉言之閒也相似。有假猗爲兮者。如詩河水淸且漣猗是也。"}]},"𠣬":{"expl":"驚辭也。从兮旬聲。","rad":"兮","fq":"思允切","vol":"05","py":"sǔn","duan":[{"e":"驚䛐也。","n":"䛐各本作辭。誤。今依篇、韵正。其意驚也。其言𠣤也。是爲意內言外。"}]},"羲":{"expl":"气也。从兮義聲。","rad":"兮","fq":"許羈切","vol":"05","py":"xī","duan":[{"e":"气也。","n":"謂气之吹噓也。按气下當有奪字。"}]},"乎":{"expl":"語之餘也。从兮，象聲上越揚之形也。","rad":"兮","fq":"戶吳切","vol":"05","py":"hū","duan":[{"e":"語之餘也。","n":"乎餘㬪韵。意不盡、故言乎以永之。班史多假虖爲乎。"}]},"蒁":{"expl":"艸也。从艸述聲。","rad":"艸","fq":"食聿切","vol":"01","py":"shù","duan":[{"e":"艸也。","n":"陳藏器本艸。蓬莪荗。旬律切一名蓬莪。二名蒁。三名波殺。徐鍇引之。未知是否。"}]},"号":{"expl":"痛聲也。从口在丂上。凡号之屬皆从号。","rad":"号","fq":"胡到切","vol":"05","py":"háo","duan":[{"e":"痛聲也。","n":"号、嗁也。凡嗁號字古作号。口部曰。嗁、号也。今字則號行而号廢矣。"}]},"號":{"expl":"呼也。从号从虎。","rad":"号","fq":"乎刀切","vol":"05","py":"háo","duan":[{"e":"嘑也。","n":"嘑各本作呼。今正。呼、外息也。與嘑義別。口部曰。嘑、號也。此二字互訓之證也。釋言曰。號、謼也。魏風傳曰。號、呼也。以說文律之。謼呼皆假借字。號嘑者、如今云高叫也。引伸爲名號、爲號令。"}]},"亏":{"expl":"於也。象气之舒亏。从丂从一。一者，其气平之也。凡亏之屬皆从亏。(今變隸作于。)","rad":"亏","fq":"羽俱切","vol":"05","py":"yú","duan":[{"e":"於也。","n":"於者、古文烏也。烏下云。孔子曰。烏亏呼也。取其助气。故以爲烏呼。然則以於釋亏、亦取其助气。釋詁、毛傳皆曰。亏、於也。凡詩、書用亏字。凡論語用於字。葢于於二字在周時爲古今字。故釋詁、毛傳以今字釋古字也。凡言於皆自此之彼之䛐。其气舒于。檀弓。易則易。于則于。論語。有是哉。子之于也。于皆廣大之義。左傳。于民生之不易。杜云。于、曰也。此謂假于爲曰。與釋詁于曰也合。"}]},"虧":{"expl":"气損也。从亏雐聲。","rad":"亏","fq":"去爲切","vol":"05","py":"kuī","duan":[{"e":"气損也。","n":"引伸凡損皆曰虧。小雅㒳言不騫不𡹔。魯頌作不虧不𡹔。毛曰。騫、虧也。"}]},"粵":{"expl":"亏也。審愼之詞者。从亏从宷。《周書》曰：“粤三日丁亥。”","rad":"亏","fq":"王伐切","vol":"05","py":"yuè","duan":[{"e":"亏也。","n":"釋詁曰。粤于爰曰也。爰粤于也。爰粤于那都繇於也。粤與于雙聲。而又从亏。則亦象气舒于也。詩書多假越爲粤。箋云。越、於也。又假曰爲粤。"}]},"𠮱":{"expl":"驚語也。从口从亏，亏亦聲。","rad":"亏","fq":"況于切","vol":"05","py":"xū","duan":[]},"平":{"expl":"語平舒也。从亏从八。八，分也。爰禮說。","rad":"亏","fq":"符兵切","vol":"05","py":"pínɡ","duan":[{"e":"語平舒也。","n":"引伸爲凡安舒之偁。"}]},"旨":{"expl":"美也。从甘匕聲。凡旨之屬皆从旨。","rad":"旨","fq":"職雉切","vol":"05","py":"zhǐ","duan":[{"e":"美也。","n":"㬪韵。今字以爲意恉字。"}]},"嘗":{"expl":"口味之也。从旨尚聲。","rad":"旨","fq":"市羊切","vol":"05","py":"chánɡ","duan":[{"e":"口味之也。","n":"引伸凡經過者爲嘗。未經過爲未嘗。"}]},"喜":{"expl":"樂也。从壴从口。凡喜之屬皆从喜。","rad":"喜","fq":"虚里切","vol":"05","py":"xǐ","duan":[{"e":"樂也。","n":"樂者、五聲八音緫名。樂記曰。樂者、樂也。古音樂與喜樂無二字。亦無二音。"}]},"荵":{"expl":"荵冬艸。从艸忍聲。","rad":"艸","fq":"而軫切","vol":"01","py":"rěn","duan":[{"e":"荵冬艸。","n":"三字句。名醫別錄作忍冬。今之金銀藤也。其花曰金銀花。"}]},"憙":{"expl":"說也。从心从喜，喜亦聲。","rad":"喜","fq":"許記切","vol":"05","py":"xǐ","duan":[{"e":"說也。","n":"說者、今之悅字。樂者、無所箸之䛐。悅者、有所箸之䛐。口部嗜下曰。憙欲之也。然則憙與嗜義同。與喜樂義異。淺人不能分別。認爲一字。喜行而憙廢矣。顏師古曰。喜下施心是好憙之意。音虛記切。"}]},"嚭":{"expl":"大也。从喜否聲。《春秋傳》：“吳有太宰嚭。”","rad":"喜","fq":"匹鄙切","vol":"05","py":"pǐ","duan":[{"e":"大也。从喜。否聲。","n":"按訓大則當从丕。集韵一作噽是也。匹鄙切。十五部。"}]},"壴":{"expl":"陳樂立而上見也。从屮从豆。凡壴之屬皆从壴。","rad":"壴","fq":"中句切","vol":"05","py":"zhù","duan":[{"e":"陳樂立而上見也。","n":"謂凡樂器有？者豎之。其顚上出可望見。如詩禮所謂崇牙、金部所謂鎛鱗也。厂部曰。屵、岸上見也。亦謂遠可望見。"}]},"尌":{"expl":"立也。从壴从寸，持之也。讀若駐。","rad":"壴","fq":"常句切","vol":"05","py":"shù","duan":[{"e":"立也。","n":"與人部侸音義同。今字通用樹爲之。樹行而尌廢矣。周禮注多用尌字。"}]},"𧒕":{"expl":"夜戒守鼓也。从壴蚤聲。《禮》：昬鼓四通爲大鼓，夜半三通爲戒晨，旦明五通爲發明。讀若戚。","rad":"壴","fq":"倉歴切","vol":"05","py":"qì","duan":[{"e":"夜戒守𡔷也。","n":"周禮𡔷人軍旅夜𡔷？注同此。鎛師。凡軍之夜三？皆𡔷之。守？亦如之。注曰。守？、備守𡔷也。𡔷之以鼖𡔷。"}]},"彭":{"expl":"鼓聲也。从壴彡聲。","rad":"壴","fq":"薄庚切","vol":"05","py":"pénɡ","duan":[{"e":"𡔷聲也。","n":"詩之言𡔷聲者惟鼉𡔷逢逢。毛曰。逢逢、和也。逢逢埤蒼、廣雅作韸韸。高注淮南吕覽、郭注山海經引詩皆作韸韸。許無韸字。彭卽韸也。東陽合韵也。毛詩。出車彭彭。又四牡彭彭。又駟騵彭彭。又以車彭彭。凡言彭彭皆謂馬。卽鄭風駟？旁旁之異文。彭旁皆假借。其正字則馬部之騯也。言馬而假𡔷聲之字者。其壯盛相似也。齊風。行人彭彭。傳曰。多皃。亦盛意。"}]},"嘉":{"expl":"美也。从壴加聲。","rad":"壴","fq":"古牙切","vol":"05","py":"jiā","duan":[{"e":"美也。","n":"見釋詁。又曰。嘉、善也。周禮。以嘉禮親萬民。鄭曰。嘉、善也。所以因人心所善者而爲之制。按誩部曰。譱、吉也。羊部曰。美與善同意。經有借假爲嘉者。如大雅、周頌毛傳皆曰假、嘉也是也。有借賀爲嘉者。覲禮古文余一人嘉之、今文嘉作賀是也。"}]},"鼛":{"expl":"大鼓也。从鼓咎聲。《詩》曰：“鼛鼓不勝。”","rad":"鼓","fq":"古勞切","vol":"05","py":"ɡāo","duan":[{"e":"大𡔷也。","n":"周禮作皐。古音同在三部也。𡔷人。以皐𡔷𡔷役事。韗人。爲皐𡔷。長尋有四尺。倨句磬折。毛傳。鼛、大𡔷也。長一丈二尺。"}]},"鼖":{"expl":"大鼓謂之鼖。鼖八尺而兩面，以鼓軍事。从鼓，賁省聲。","rad":"鼓","fq":"符分切","vol":"05","py":"fén","duan":[{"e":"大𡔷謂之鼖。","n":"凡賁聲字多訓大。如毛傳云。墳、大防也。頒、大首皃。汾、大也。皆是。卉聲與賁聲一也。"}]},"萇":{"expl":"萇楚，跳弋。一名羊桃。从艸長聲。","rad":"艸","fq":"直良切","vol":"01","py":"chánɡ","duan":[{"e":"萇楚、","n":"逗。"}]},"鼙":{"expl":"騎鼓也。从鼓卑聲。","rad":"鼓","fq":"部迷切","vol":"05","py":"pí","duan":[{"e":"騎𡔷也。","n":"戴先生曰。儀禮有朔鼙、應鼙。鼙者小𡔷。與大𡔷爲節。魯𡔷薛𡔷之圖。圜者擊鼙。方者擊𡔷。後世不別設鼙。以擊𡔷側當之。作堂下之樂。先擊朔鼙。應鼙應之。朔者、始也。所以引樂。故又謂之𣌾。𣌾之言引也。朔鼙在西。置𡔷北。應鼙在東。置𡔷南。東方諸縣西鄉。西方諸縣東鄉故也。按大司馬云。師帥執提。旅帥執鼙。大鄭曰。提謂馬上𡔷。有曲木提持𡔷立馬髦上者。然則騎𡔷謂提、非謂鼙也。許與大鄭異。"}]},"𪔳":{"expl":"鼓聲也。从鼓隆聲。","rad":"鼓","fq":"徒冬切","vol":"05","py":"lónɡ","duan":[{"e":"𡔷聲也。","n":"此當云？？𡔷聲也。篇、韵良弓切。其作？、讀徒東徒冬二切者。卽？？之變也。"}]},"鼘":{"expl":"鼓聲也。从鼓𣶒聲。《詩》曰：“鼗鼓鼘鼘。”","rad":"鼓","fq":"烏玄切","vol":"05","py":"yuān","duan":[{"e":"鼘鼘、𡔷聲也。","n":"各本無鼘鼘二字。今依韵會。詩小雅、商頌作淵淵。魯頌作咽咽。皆假借字也。魯頌音義曰。本又作鼝。譌字也。小雅傳曰。淵淵、𡔷聲也。魯頌傳曰。咽咽、𡔷節也。"}]},"鼞":{"expl":"鼔聲也。从鼓堂聲。《詩》曰：“擊鼓其鼞。”","rad":"鼓","fq":"土郎切","vol":"05","py":"tānɡ","duan":[{"e":"𡔷聲也。","n":"周禮注曰。司馬法云。𡔷聲不過閶。鼙聲不過闒。鐸聲不過琅。音義曰。閶吐剛反。然則閶卽鼞也。投壷音義曰。□、鄭呼爲𡔷。其聲高。其音鏜鏜然。鏜音吐郎反。是則鏜亦鼞也。上林賦。金𡔷迭起。鏗鎗闛鞈。顏曰。鏗鎗、金聲。闛鞈、𡔷音。闛亦鼞也。楊雄賦闛？卽閶？。堂聲昌聲古通用耳。"}]},"䶀":{"expl":"鼓聲也。从鼓合聲。","rad":"鼓","fq":"徒合切","vol":"05","py":"tà","duan":[{"e":"鼙聲也。","n":"鼙各本誤作𡔷。今正。司馬法曰。鼙聲不過闒。音義曰。闒吐臘反。劉湯荅反。臘今誤从犬闒卽䶀字也。投壷音義曰。○、鄭呼爲鼙也。其聲下。其音榻榻然。榻音吐臘反。榻亦卽䶀也。史記上林賦。鏗鎗鏜䶀。漢書、文選作闛鞈。郭璞曰。闛鞈、𡔷音也。此渾言之耳。鼙亦𡔷也。淮南兵略訓。若聲之與響。若鏜之與鞈。高注。鏜鞈、𡔷鼙聲。此謂鏜、𡔷聲。鞈、鼙聲也。"}]},"𪔪":{"expl":"鼓無聲也。从鼓咠聲。","rad":"鼓","fq":"他叶切","vol":"05","py":"qì","duan":[{"e":"𡔷無聲也。","n":"上文皆言聲。故以𡔷無聲廁於後。"}]},"𪔕":{"expl":"鼓鼙聲。从鼓缶聲。","rad":"鼓","fq":"土盍切","vol":"05","py":"tà","duan":[{"e":"𡔷鼙聲。从𡔷。缶聲。","n":"土盍切。按缶聲不得土盍切明矣。玉篇曰。䵽、𡔷聲也。七盍切。廣韵曰。䵽、𡔷聲也。倉雜切。皆卽其字。缶者、去之譌。去聲古或入侵部也。然皆䶀之誤字耳。今䶀之解說旣更正。則？篆可刪。"}]},"豈":{"expl":"還師振旅樂也。一曰欲也，登也。从豆，微省聲。凡豈之屬皆从豈。","rad":"豈","fq":"墟喜切","vol":"05","py":"qǐ","duan":[{"e":"還師振旅樂也。","n":"公羊傳曰。出曰祠兵。入曰振旅。周禮大司樂曰。王師大獻。則令奏愷樂。注曰。大獻、獻捷於祖。愷樂、獻功之樂。鄭司農說以春秋晉文公敗楚於城濮。傳曰。振旅愷以入於晉。按經傳豈皆作愷。"}]},"愷":{"expl":"康也。从心、豈，豈亦聲。","rad":"豈","fq":"苦亥切","vol":"05","py":"kǎi","duan":[{"e":"康也。","n":"愷康雙聲。釋詁曰。康、安也。毛傳釋豈弟曰。豈、樂也。弟、易也。按奏豈、經傳多作愷。愷樂、毛詩亦作豈。是二字互相假借也。愷不入心部而入此者。重以豈會意也。詩又作凱。俗字也。邶風傳曰。凱風謂之南風。樂夏之長養。凱亦訓樂。卽愷字也。"}]},"𧰙":{"expl":"㡮也，訖事之樂也。从豈幾聲。","rad":"豈","fq":"渠稀切","vol":"05","py":"qí","duan":[{"e":"汔也。","n":"汔各本作？。無此字。今正。釋詁曰。𧰙、汔也。孫炎曰。汔、近也。民勞箋云。汔、幾也。幾與𧰙同。汔與訖同。汔、水涸也。水涸則近於盡矣。故引爲凡近之䛐。木部杚、平也。亦摩近之義也。𢆶部曰。幾、微也。殆也。然則見幾、研幾、字當作幾。庶幾、幾近、字當作𧰙。幾行而𧰙廢矣。"}]},"薊":{"expl":"芺也。从艸魝聲。","rad":"艸","fq":"古詣切","vol":"01","py":"jì","duan":[{"e":"芺也。","n":"釋艸曰。芺、薊、其實荂。郭云。芺似薊。許以芺釋薊。則爲一物。而芺字又不類列於此。未聞。"}]},"豆":{"expl":"古食肉器也。从口，象形。凡豆之屬皆从豆。","rad":"豆","fq":"徒候切","vol":"05","py":"dòu","duan":[{"e":"古食肉器也。","n":"考工記曰。食一豆肉。中人之食也。左傳曰。四𦫵爲豆。周禮醢人。掌四豆之食。"}]},"梪":{"expl":"木豆謂之梪。从木、豆。","rad":"豆","fq":"徒候切","vol":"05","py":"dòu","duan":[{"e":"木豆謂之梪。","n":"𥼶器曰。木豆謂之梪。竹豆謂之籩。瓦豆謂之登。毛傳亦曰。木曰豆。所以薦菹醢也。瓦曰登。所以薦大羹也。毛詩豆當作梪。瓬人豆中縣。豆本瓦器。故木爲之則異其字。韓𠡠碑。爵鹿柤梪。僞古文武成有梪。"}]},"𧯷":{"expl":"蠡也。从豆，蒸省聲。","rad":"豆","fq":"居隱切","vol":"05","py":"jǐn","duan":[{"e":"蠡也。","n":"瓠部曰。瓢、蠡也。然則？、瓢也。蠡、說文三見。斗部曰。斡、蠡柄也。倂此及瓠部凡三見也。蠡之言離。方言曰。劙、解也。一瓠離爲二、故曰蠡。鄭注鬯人云。瓢謂瓢蠡也。漢書。以蠡測海。張晏曰。蠡、瓠瓢也。字皆借蠡。九歎。瓟㼖蠹於筐簏。急就篇。㼖𦫵參𦫵半巵觛。方言。㼖或謂之瓢。或謂之簞。或謂之𣟵。則字皆从瓜。王伯厚注急就云。皇象碑本作盠。李本作蠡。廣韵齊、薺韵皆有盠。士昏禮。四爵合巹。注云。合巹、破匏也。昏義亦作巹。正義云。以一瓠分爲㒳瓢。巹者、？之假借字。巹从丞聲。？从䒱聲。故同音假借。"}]},"𧯦":{"expl":"豆屬。从豆𢍏聲。","rad":"豆","fq":"居倦切","vol":"05","py":"juàn","duan":[{"e":"豆屬。","n":"此本艸經之大豆黃卷也。味甘平。主濕痹筋攣厀痛。唐本注云。以大豆爲芽櫱。生便乾之。名爲黃卷。靈樞曰。腎病者宜食。廣韵阮韵云。？、黃豆也。"}]},"𧯡":{"expl":"豆飴也。从豆夗聲。","rad":"豆","fq":"一丸切","vol":"05","py":"wān","duan":[{"e":"豆飴也。","n":"飴、米櫱煎也。糱、芽米也。然則豆飴者、芽豆煎爲飴也。黑部？下曰。讀若飴？之？。方言飴謂之䬵。𩜌謂之䭉。郭注以豆㞕襍餳也。𩜌卽？字。"}]},"𢍪":{"expl":"禮器也。从廾持肉在豆上。讀若鐙同。","rad":"豆","fq":"都縢切","vol":"05","py":"dēnɡ","duan":[{"e":"禮器也。","n":"生民曰。于豆于登。釋器、毛傳皆曰。瓦豆謂之登。毛云。登薦大羹。公食大夫禮。大羹湆不和實于鐙。登鐙皆假借字。劉氏台拱曰。詩、爾雅皆作登。釋文、唐石經、篇、韵皆無豋字。玉篇有？字。俗製豋字改經。非也。"}]},"豊":{"expl":"行禮之器也。从豆，象形。凡豊之屬皆从豊。讀與禮同。","rad":"豊","fq":"盧啓切","vol":"05","py":"lǐ","duan":[{"e":"行禮之器也。","n":"豐禮㬪韵。"}]},"豑":{"expl":"爵之次弟也。从豊从弟。《虞書》曰：“平豑東作。”","rad":"豊","fq":"直質切","vol":"05","py":"zhì","duan":[{"e":"爵之次弟也。","n":"爵者、行禮之器。故从豐。有次弟、故从弟。爵之次弟。若士虞禮主人廢爵、主婦足爵、賔長繶爵、祭統玉爵獻卿、瑤爵獻大夫、散爵獻士及羣有司是也。凡酒器皆曰爵。則如禮運云宗廟之爵、貴者獻以爵、賤者獻以散、尊者舉觶、卑者舉角、梓人云獻以爵而酬以觶是也。"}]},"豐":{"expl":"豆之豐滿者也。从豆，象形。一曰《鄉飲酒》有豐侯者。凡豐之屬皆从豐。","rad":"豐","fq":"敷戎切","vol":"05","py":"fēnɡ","duan":[{"e":"豆之豐滿也。","n":"謂豆之大者也。引伸之凡大皆曰豐。方言曰。豐大也。凡物之大皃曰豐。又曰。朦尨豐也。豐其通語也。趙魏之郊燕之北鄙几大人謂之豐。燕記豐人杼首。燕趙之閒言圍大謂之豐。許云豆之豐滿者、以其引伸之義明其本義也。周頌豐年傳曰。豐、大也。然則豐年亦此字引伸之義。而賈氏儀禮疏不得其解。"}]},"豔":{"expl":"好而長也。从豐。豐，大也。盇聲。《春秋傳》曰：“美而豔。”","rad":"豐","fq":"以贍切","vol":"05","py":"yàn","duan":[{"e":"好而長也。","n":"小雅毛傳曰。美色曰豓。方言。豓、美也。宋衞晉鄭之閒曰豓。美色爲豓。按今人但訓美好而巳。許必云好而長者、爲其从豐也。豐、大也。大與長義通。詩言莊姜之美、必先言碩人頎頎。言魯莊之美、必先言猗嗟昌兮、頎若長兮。所謂好而長也。左傳㒳言美而豓。此豓進於美之義。人固有美而不豐滿者也。毛傳及方言皆渾言之也。"}]},"荲":{"expl":"艸也。从艸里聲。讀若釐。","rad":"艸","fq":"里之切","vol":"01","py":"lí","duan":[{"e":"艸也。","n":"下文之苖也。本艸經曰。羊蹄、小雅謂之蓫。蓫卽苖字。亦作蓄。廣韵一屋。荲、許竹丑六二切。羊蹄菜也。"}]},"䖒":{"expl":"古陶器也。从豆虍聲。凡䖒之屬皆从䖒。","rad":"䖒","fq":"許羈切","vol":"05","py":"xī","duan":[{"e":"古陶器也。","n":"陶當作匋。書多通用。匋作瓦器也。"}]},"𧇼":{"expl":"土鍪也。从䖒号聲。讀若鎬。","rad":"䖒","fq":"胡到切","vol":"05","py":"hào","duan":[{"e":"土鍪也。","n":"金部曰。鍪、鍑屬也。鍑、釜大口者。廣雅。鍑鍪？鬴也。？卽？字。鍪金爲之。？則土爲之。鄭注周禮所謂黃堥也。堥卽鍪字。鬲部曰。秦名土釜曰？。"}]},"𧈚":{"expl":"器也。从䖒、㿾，㿾亦聲。闕。","rad":"䖒","fq":"直呂切","vol":"05","py":"zhù","duan":[{"e":"器也。从䖒㿾。㿾亦聲。","n":"直吕切。五部。"}]},"虍":{"expl":"虎文也。象形。凡虍之屬皆从虍。","rad":"虍","fq":"荒烏切","vol":"05","py":"hū","duan":[{"e":"虎文也。象形。","n":"小徐曰。象其文章屈曲也。荒烏切。五部。"}]},"虞":{"expl":"騶虞也。白虎黑文，尾長於身。仁獸，食自死之肉。从虍吳聲。《詩》曰：“于嗟乎，騶虞。”","rad":"虍","fq":"五俱切","vol":"05","py":"yú","duan":[{"e":"騶虞也。","n":"騶虞山海經、墨子作騶吾。漢東方朔傳作騶牙。皆同音假借字也。"}]},"虙":{"expl":"虎皃。从虍必聲。","rad":"虍","fq":"房六切","vol":"05","py":"fú","duan":[{"e":"虎皃。","n":"古伏羲字作虙。五經文字引論語釋文云。宓子賤姓虙。文字譌舛。轉而爲宓。故濟南伏生稱子賤之後也。"}]},"虔":{"expl":"虎行皃。从虍文聲。讀若矜。","rad":"虍","fq":"渠焉切","vol":"05","py":"qián","duan":[{"e":"虎行皃。","n":"釋詁、大雅商頌傳皆曰。虔、固也。商頌傳、魯語注皆曰。虔、敬也。左傳虔劉我邊陲注。虔劉皆殺也。方言。虔、慧也。虔、殺也。虔、謾也。按方言不可盡知其說。糾虔、虔劉皆卽釋詁虔固之義。堅固者必敬。堅固者乃能殺也。堅固者虎行之皃也。商頌箋。虔、椹也。亦取堅固之意。"}]},"虘":{"expl":"虎不柔不信也。从虍且聲。讀若䣜縣。","rad":"虍","fq":"昨何切","vol":"05","py":"cuó","duan":[{"e":"虎不柔不信也。","n":"剛暴矯詐。"}]},"虖":{"expl":"哮虖也。从虍𠀒聲。","rad":"虍","fq":"荒烏切","vol":"05","py":"hū","duan":[{"e":"哮虖也。","n":"口部曰。哮、豕驚聲也。唬、虎聲。通俗文曰。虎聲謂之哮唬。疑此哮虖當作哮唬。漢書多假虖爲乎字。"}]},"虐":{"expl":"殘也。从虍，虎足反爪人也。","rad":"虍","fq":"魚約切","vol":"05","py":"nüè","duan":[{"e":"殘也。","n":"歹部曰。殘、賊也。"}]},"祀":{"expl":"祭無已也。从示巳聲。","rad":"示","fq":"詳里切","vol":"01","py":"sì","duan":[{"e":"祭無巳也。","n":"析言則祭無巳曰祀。从巳而釋爲無巳。此如治曰亂、徂曰存。終則有始之義也。釋詁曰。祀祭也。"}]},"藋":{"expl":"釐艸也。一曰拜商藋。从艸翟聲。","rad":"艸","fq":"徒弔切","vol":"01","py":"diào","duan":[{"e":"堇艸也。","n":"依集韵、類篇、李仁甫本作堇。廣雅。堇、謹音藋也。名醫別錄。蒴藋一名蓳草。一名芨。按下籒文內有蓳字。云根如薺。葉如細桺。未知是一否。○凡物有異名同實者。釋艸曰。芨、堇艸。陸德明謂卽本艸之蒴藋。按郭釋以烏頭。烏頭名堇。見國語。而芨名無見。陸說爲長。鍇本堇作釐。"}]},"虨":{"expl":"虎文，彪也。从虍彬聲。","rad":"虍","fq":"布還切","vol":"05","py":"bīn","duan":[{"e":"虎文彪也。","n":"彪下曰。虎文也。二字雙聲。假借作班。漢書敘傳曰。楚人謂虎班。其子㠯爲號。上文旣曰楚人謂虎於檡矣。此正當作楚人謂虎文班。上林賦。被班文。史記作豳文。李善曰。班文、虎豹之皮。索隱引輿服志。虎賁騎被虎文單衣。按豳與虨、同部之假借也。班與虨、同類之假借也。錢氏大昕曰。易象傳。大人虎變。其文炳也。與下文蔚君爲韵。蔚讀如氳。轉移冣近。炳當爲虨。則音義皆近。"}]},"𧇽":{"expl":"鐘鼓之柎也。飾爲猛獸，从虍，異象其下足。","rad":"虍","fq":"其呂切","vol":"05","py":"jù","duan":[{"e":"鐘𡔷之柎也。","n":"木部曰。柎、咢足也。靈臺、有瞽傳皆曰。植者曰虡。橫者曰栒。考工記曰。梓人爲？虡。"}]},"虎":{"expl":"山獸之君。从虍，虎足象人足。象形。凡虎之屬皆从虎。","rad":"虎","fq":"呼古切","vol":"05","py":"hǔ","duan":[{"e":"山獸之君。从虍。从儿。","n":"會意。"}]},"𧈖":{"expl":"虎聲也。从虎毄聲。讀若隔。","rad":"虎","fq":"古覈切","vol":"05","py":"ɡé","duan":[{"e":"虎聲也。","n":"篇、韵作？。"}]},"䖑":{"expl":"白虎也。从虎，昔省聲。讀若鼏。","rad":"虎","fq":"莫狄切","vol":"05","py":"mì","duan":[{"e":"白虎也。从虎。㫺省聲。讀若鼏。","n":"昔當作冥。字之誤也。水部曰。汨、从水、冥省聲。玉篇曰。？俗䖑字、可證也。又按漢書金日磾、說者謂密低二音。然則日聲可同密。䖵部𧖅蜜同字。禮古文鼏皆爲密。則鼏密音同也。今音䖑莫狄切。"}]},"䖔":{"expl":"䖑屬。从虎去聲。","rad":"虎","fq":"呼濫切","vol":"05","py":"kǎn","duan":[{"e":"䖑屬。","n":"釋獸。甝、白虎。許無甝。䖔卽甝也。一說釋文云。甝、字林下甘反。又亡狄反。甘聲之字不能切亡狄。甝與甝當是以一譌二。未知孰是耳。"}]},"虪":{"expl":"黑虎也。从虎儵聲。","rad":"虎","fq":"式竹切","vol":"05","py":"shù","duan":[{"e":"黑虎也。","n":"釋獸曰。？、黑虎。釋文曰。？、今作虪。吳都賦曰。虣甝虪。"}]},"虦":{"expl":"虎竊毛謂之虦苗。从虎戔聲。竊，淺也。","rad":"虎","fq":"昨閑切","vol":"05","py":"zhàn","duan":[{"e":"虎竊毛謂之虦苗。","n":"苗今之貓字。許書以苗爲貓也。釋獸曰。虎竊毛謂之虥貓。按毛苗古同音。苗亦曰毛。如不毛之地是。竊虥淺亦同音也。具言之曰虦苗。急言之則但曰苗。詩言有貓有虎。記言迎貓迎虎是也。"}]},"彪":{"expl":"虎文也。从虎，彡象其文也。","rad":"虎","fq":"甫州切","vol":"05","py":"biāo","duan":[{"e":"虎文也。","n":"此與虨雙聲同義。虎皮、詩謂之虎。如虎韔是也。亦謂之文。如文茵是也。分別言之謂之淺。如淺幭是也。說文曰虍、曰虨、曰彪皆狀其文也。班彪字伯皮。此取虎文之義也。"}]},"䖊":{"expl":"虎皃。从虎乂聲。","rad":"虎","fq":"魚廢切","vol":"05","py":"yì","duan":[{"e":"虎皃。从虎。乂聲。","n":"魚廢切。十五部。"}]},"芨":{"expl":"堇艸也。从艸及聲。讀若急。","rad":"艸","fq":"居立切","vol":"01","py":"jī","duan":[{"e":"堇艸也。","n":"見上。"}]},"𧆦":{"expl":"虎皃。从虎气聲。","rad":"虎","fq":"魚迄切","vol":"05","py":"yì","duan":[{"e":"虎皃。","n":"篇、韵作？。"}]},"虓":{"expl":"虎鳴也。一曰師子。从虎九聲。","rad":"虎","fq":"許交切","vol":"05","py":"xiāo","duan":[{"e":"虎鳴也。","n":"大雅。闞如虓虎。毛曰。虓虎、虎之自怒虓然。按自怒猶盛怒也。口部曰。唬、虎聲也。虓與唬雙聲同義。"}]},"䖐":{"expl":"虎聲也。从虎斤聲。","rad":"虎","fq":"語斤切","vol":"05","py":"yín","duan":[{"e":"虎聲也。","n":"猶㹞爲犬吠聲。"}]},"虩":{"expl":"《易》：“履虎尾虩虩。”恐懼。一曰蠅虎也。从虎𡭴聲。","rad":"虎","fq":"許隙切","vol":"05","py":"xì","duan":[{"e":"易𡳐虎尾虩虩。","n":"𡳐九四爻辭。今易虩虩作愬愬。釋文曰。愬愬、子夏傳云恐懼貌。馬本作虩虩。云恐懼也。說文同。按震卦辭。震來虩虩。馬云。恐懼貌。鄭同馬。鄭用費易。許用孟易。而字同義同也。"}]},"虢":{"expl":"虎所攫畫明文也。从虎寽聲。","rad":"虎","fq":"古伯切","vol":"05","py":"ɡuó","duan":[{"e":"虎所攫畫明文也。","n":"攫者㕚所扟也。畫者㕚所劃。故有明文也。虢字本義久廢。罕有用者。"}]},"虒":{"expl":"委虒，虎之有角者也。从虎𠂆聲。","rad":"虎","fq":"息移切","vol":"05","py":"sī","duan":[{"e":"委虒、","n":"㬪韵。"}]},"𧈜":{"expl":"黑虎也。从虎騰聲。","rad":"虎","fq":"徒登切","vol":"05","py":"ténɡ","duan":[{"e":"黑虎也。从虎。騰聲。","n":"徒登切。六部。按此篆當與虪爲伍。今非其次。或轉寫失而補之。或後人羼綴。未可定也。"}]},"𧇒":{"expl":"虐也。急也。从虎从武。見《周禮》。","rad":"虎","fq":"薄報切","vol":"05","py":"bào","duan":[]},"䖘":{"expl":"楚人謂虎爲烏䖘。从虎兔聲。","rad":"虎","fq":"同都切","vol":"05","py":"tú","duan":[]},"虤":{"expl":"虎怒也。从二虎。凡虤之屬皆从虤。","rad":"虤","fq":"五閑切","vol":"05","py":"yán","duan":[{"e":"虎怒也。从二虎。","n":"此與㹜、㒳犬相齧也同意。五閑切。十四部。"}]},"葥":{"expl":"山苺也。从艸歬聲。","rad":"艸","fq":"子賤切","vol":"01","py":"jiàn","duan":[{"e":"山苺也。","n":"見釋艸。"}]},"䖜":{"expl":"兩虎爭聲。从虤从曰。讀若憖。","rad":"虤","fq":"語巾切","vol":"05","py":"yín","duan":[{"e":"㒳虎爭聲。从虤。从曰。","n":"會意。"}]},"贙":{"expl":"分別也。从虤對爭貝。讀若迴。","rad":"虤","fq":"胡畎切","vol":"05","py":"xuàn","duan":[{"e":"分別也。","n":"魏都賦。蒹葭贙。謂蒹葭茂密若爭地而生也。釋獸之贙、獸名也。"}]},"皿":{"expl":"飯食之用器也。象形。與豆同意。凡皿之屬皆从皿。讀若猛。","rad":"皿","fq":"武永切","vol":"05","py":"mǐn","duan":[{"e":"飯食之用器也。","n":"飯汲古閣作飮。誤。孟子。牲殺器皿。趙注。皿所以覆器者。此謂皿爲幎之假借。似非孟意。"}]},"盂":{"expl":"飯器也。从皿亏聲。","rad":"皿","fq":"羽俱切","vol":"05","py":"yú","duan":[{"e":"飮器也。","n":"飮大徐及篇、韵、急就篇注作飯。誤。小徐及後漢書注、御覽皆作飮。不誤。木部椲、木也。可屈爲杅者。杅卽盂之假借字。旣夕禮㒳敦㒳杅注。杅盛湯漿。公羊傳。古者杅不穿。何注。杅、飮水器。孫卿子曰。槃圓而水圓。杅方而水方。史記滑稽傳。操一豚蹏、酒一盂而祝。後漢書孝明紀。盂水脯糒而巳。方言。盂、宋楚魏之閒或謂之盌。又曰。盂謂之柯。又曰。盂謂之㯸。河濟之閒謂之䀂？。又曰。孟謂之銚銳。"}]},"盌":{"expl":"小盂也。从皿夗聲。","rad":"皿","fq":"烏管切","vol":"05","py":"wǎn","duan":[{"e":"小𥁄也。","n":"方言曰。盌謂之盂。或謂之銚銳。又曰。盌謂之櫂。又曰。椀謂之䀉。"}]},"盛":{"expl":"黍稷在器中以祀者也。从皿成聲。","rad":"皿","fq":"氏征切","vol":"05","py":"chénɡ","duan":[{"e":"黍稷在器中㠯祀者也。","n":"盛者、實於器中之名也。故亦𧦝器爲盛。如左傳旨酒一盛、喪大記食粥於盛是也。引伸爲凡豐滿之偁。今人分平去。古不分也。如左傳盛服將朝。盛音成。本亦作成。"}]},"齍":{"expl":"黍稷在器以祀者。从皿齊聲。","rad":"皿","fq":"卽夷切","vol":"05","py":"zī","duan":[{"e":"黍稷器。所㠯祀者。","n":"各本作黍稷在器以祀者。則與盛義不別。今从韵會本。按周禮一書。或兼言齍盛。或單言齍、單言盛。皆言祭祀之事。他事絕不言齍盛。故許皆云以祀者。兼言齍盛。若甸師、春人、肆師、小祝是也。單言齍。若大宗伯、小宗伯、大祝是也。單言盛。若饎人、廩人是也。小宗伯逆齍注云。受饎人之盛以入。然則齍盛可互偁也。甸師注云。秶、稷也。榖者稷爲長。是以名云。肆師注云。秶、六榖也。大祝注云。秶號謂黍稷皆有名號也。春人注云。齍盛謂黍稷稻粱之屬。可盛以爲簠簋實。經文齍字、注三易爲秶。而小宗伯六齍注云。齍讀爲秶。六秶謂六榖。黍稷稻粱麥苽。此則易齍爲秶之恉。謂齍秶古今字也。考毛詩甫田作齊、亦作齍。用古文。禮記作秶盛。用今文。是則齍秶"}]},"䀁":{"expl":"小甌也。从皿有聲。讀若灰。一曰若賄。","rad":"皿","fq":"于救切","vol":"05","py":"yòu","duan":[{"e":"小甌也。","n":"甌、小盆也。廣韵。䀁、抒水器也。"}]},"盧":{"expl":"飯器也。从皿𧇄聲。","rad":"皿","fq":"洛乎切","vol":"05","py":"lú","duan":[{"e":"盧、飯器也。","n":"？部曰。？盧、飯器。以桺爲之。士昏禮注曰。笲、竹器而衣者。如今之筥、𥬔籚矣。筥、𥬔籚二物相似。𥬔籚卽？盧也。方言。𥰠、趙魏之郊謂之去𥰠。注。盛飯筥也。錢氏大昕曰。去𥰠卽？盧也。"}]},"䀇":{"expl":"器也。从皿从缶，古聲。","rad":"皿","fq":"公戶切","vol":"05","py":"ɡǔ","duan":[{"e":"器也。从缶皿。古聲。","n":"公戸切。五部。"}]},"𦺒":{"expl":"毒艸也。从艸婺聲。","rad":"艸","fq":"莫候切","vol":"01","py":"mòu","duan":[]},"盄":{"expl":"器也。从皿弔聲。","rad":"皿","fq":"止遙切","vol":"05","py":"zhāo","duan":[{"e":"器也。从皿。弔聲。","n":"止遙切。二部。"}]},"盎":{"expl":"盆也。从皿央聲。","rad":"皿","fq":"烏浪切","vol":"05","py":"ànɡ","duan":[{"e":"盆也。","n":"釋器。盎謂之缶。注云。盆也。假借爲酒名。周禮盎齊注曰。盎猶翁也。成而翁翁然。葱白色。如今酇白矣。按翁者、滃之假借。滃滃猶泱泱也。酒之成似之。孟子。盎於背。趙曰。其背盎盎然。凡言盎然者、皆謂盛。以音假借也。"}]},"盆":{"expl":"盎也。从皿分聲。","rad":"皿","fq":"步奔切","vol":"05","py":"pén","duan":[{"e":"盎也。","n":"廣雅。盎謂之盆。考工記。盆實二鬴。"}]},"㿾":{"expl":"器也。从皿宁聲。","rad":"皿","fq":"直呂切","vol":"05","py":"zhù","duan":[{"e":"器也。从皿。宁聲。","n":"直吕切。五部。？字從此。"}]},"盨":{"expl":"㯯盨，負戴器也。从皿須聲。","rad":"皿","fq":"相庾切","vol":"05","py":"xǔ","duan":[{"e":"㯯盨、","n":"逗。"}]},"䀊":{"expl":"器也。从皿漻聲。","rad":"皿","fq":"古巧切","vol":"05","py":"jiǎo","duan":[{"e":"器也。","n":"廣韵古巧切。濁也。苦絞切。溫器也。"}]},"𥁑":{"expl":"械器也。从皿必聲。","rad":"皿","fq":"彌畢切","vol":"05","py":"mì","duan":[{"e":"拭器也。","n":"廣韵、集韵、類篇皆作拭。許書以飾爲拭。不出拭。此作拭者、說解中容不廢俗字、抑後人改也。可以㕞拭之器、若今㕞子之類。韓非所謂懷刷、其是歟。古㕞刷通用也。今各本作械器。非古本。"}]},"醯":{"expl":"酸也。作醯以𩱙以酒。从𩱙、酒並省，从皿。皿，器也。","rad":"皿","fq":"呼雞切","vol":"05","py":"xī","duan":[{"e":"酸也。","n":"酉部曰。酸、酢也。關東謂酢曰酸。周禮醯人。掌共醯物。"}]},"盉":{"expl":"調味也。从皿禾聲。","rad":"皿","fq":"戶戈切","vol":"05","py":"hé","duan":[{"e":"調味也。","n":"調聲曰龢。調味曰盉。今則和行而龢盉皆廢矣。𩰲部曰鬻、五味盉羹也。"}]},"益":{"expl":"饒也。从水、皿。皿，益之意也。","rad":"皿","fq":"伊昔切","vol":"05","py":"yì","duan":[{"e":"饒也。","n":"食部曰。饒、飽也。凡有餘曰饒。易象傳曰。風雷益。君子以見善則遷。有過則改。"}]},"蓩":{"expl":"卷耳也。从艸務聲。","rad":"艸","fq":"亡考切","vol":"01","py":"mǎo","duan":[{"e":"毒艸也。","n":"鉉、鍇本篆皆作？。從艸、？聲。鉉本？下又出蓩篆。云卷耳也、從艸、務聲。鍇本無蓩。張次立依鉉補之。攷後漢書劉聖公傳。戰於蓩鄉。注曰。蓩音莫老反。字林云。毒艸也。因以爲地名。廣韵。蓩、毒艸。武道切。又地名。據此則毒艸之字從力不從女明矣。玉篇云。蓩、莫屋莫老二切。毒艸也。此顧野王原本。而蓩下引說文卷耳也。又出？字。莫𠋫切。引說文毒艸也。此孫强、陳彭年輩據俗本說文增之。今改正篆文作蓩、毒艸也。而刪蓩卷耳也之云。卷耳果名蓩、則當與苓卷耳也同處矣。又按韵會引後漢書注作䓮鄉。說文有䓮字。云細艸叢生也。"}]},"盈":{"expl":"滿器也。从皿、夃。","rad":"皿","fq":"以成切","vol":"05","py":"yínɡ","duan":[{"e":"滿器也。","n":"滿器者、謂人滿宁之。如彉下云滿弩之滿。水部溢下云器滿也。則謂器中巳滿。滿下云盈溢也。則兼滿之、巳滿而言。許書之精嚴如此。"}]},"盡":{"expl":"器中空也。从皿㶳聲。","rad":"皿","fq":"慈刃切","vol":"05","py":"jìn","duan":[{"e":"器中空也。","n":"釋詁。觳悉卒泯忽滅罄空畢罊殲拔殄盡也。曲禮曰。虛坐盡後。實坐盡前。卽忍切。俗作儘。亦空義之引伸。"}]},"盅":{"expl":"器虛也。从皿中聲。《老子》曰：“道盅而用之。”","rad":"皿","fq":"直弓切","vol":"05","py":"chōnɡ","duan":[{"e":"器虛也。","n":"？部曰。虛、大？也。引伸爲虛落。今之墟字也。又引伸爲空虛。邶風。其虛其邪。毛曰。虛、虛也。是其義也。謂此虛字、乃虛中之虛也。盅虛字今作沖。水部曰。沖、涌繇也。則作沖非也。沖行而盅廢矣。"}]},"盦":{"expl":"覆蓋也。从皿酓聲。","rad":"皿","fq":"烏合切","vol":"05","py":"ān","duan":[{"e":"覆葢也。","n":"此與大部奄音義略同。此謂器之葢也。"}]},"𥁕":{"expl":"仁也。从皿，以食囚也。官溥說。","rad":"皿","fq":"烏渾切","vol":"05","py":"wēn","duan":[{"e":"仁也。从皿㠯食囚也。官溥說。","n":"凡云溫和、溫柔、溫暖者、皆當作此字。溫行而𥁕廢矣。水部溫篆下但云水名不云一曰煗者、許謂煗義自有囚皿字在也。用此知日部昫日出溫也、安㬮溫也、㫱溫溼也。火部煗溫也、？以微火溫肉也。金部銚溫器也、䥝溫器也。凡若此等皆作𥁕不作溫矣。官溥者、博訪通人之一也。烏渾切。十三部。"}]},"盥":{"expl":"澡手也。从𦥑水臨皿。《春秋傳》曰：“奉𠤷沃盥。”","rad":"皿","fq":"古玩切","vol":"05","py":"ɡuàn","duan":[{"e":"澡手也。","n":"水部曰。澡、洒手也。禮經多言盥。內則。每日進盥。五日請浴。三日具沐。其閒面垢請靧。足垢請洗。是則古人每旦必洒手。而洒面則不必旦旦爲之也。大學有湯之盤。卽特牲、內則之盥槃。故其銘曰日日新。凡洒手曰澡、曰盥。洒面曰頮。濯髮曰沐。洒身曰浴。洒足曰洗。"}]},"盪":{"expl":"滌器也。从皿湯聲。","rad":"皿","fq":"徒朗切","vol":"05","py":"dànɡ","duan":[{"e":"滌器也。","n":"水部曰。滌、洒也。洒、滌也。此字从皿。故訓滌器。凡貯水於器中。搖蕩之去滓或以磢垢瓦石和水吮？之。皆曰盪。盪者、滌之甚者也。易曰。八卦相盪。左傳。震盪播越。皆引伸之義。郊特牲曰。滌蕩其聲。注。滌蕩猶搖動也。蕩者、盪之假借。"}]},"盋":{"expl":"盋器。盂屬。从皿犮聲。或从金从本。","rad":"皿","fq":"北末切","vol":"05","py":"bō","duan":[]},"𠙴":{"expl":"𠙴盧，飯器，以柳爲之。象形。凡𠙴之屬皆从𠙴。","rad":"𠙴","fq":"去魚切","vol":"05","py":"qū","duan":[{"e":"𠙴盧、","n":"㬪韵爲名。"}]},"去":{"expl":"人相違也。从大凵聲。凡去之屬皆从去。","rad":"去","fq":"丘據切","vol":"05","py":"qù","duan":[{"e":"人相違也。","n":"違、離也。人離故从大。大者、人也。"}]},"蓡":{"expl":"人薓，藥艸，出上黨。从艸𣹰聲。","rad":"艸","fq":"山林切","vol":"01","py":"shēn","duan":[{"e":"人薓、","n":"逗。"}]},"朅":{"expl":"去也。从去曷聲。","rad":"去","fq":"丘竭切","vol":"05","py":"qiè","duan":[{"e":"去也。","n":"思玄賦舊注、劉逵蜀都賦注皆同。按古人文章多云朅來。猶往來也。"}]},"𡕮":{"expl":"去也。从去夌聲。讀若陵。","rad":"去","fq":"力膺切","vol":"05","py":"línɡ","duan":[{"e":"去也。从去。夌聲。讀若棘陵。","n":"力膺切。六部。按大徐刪棘字。今按玉篇曰居力切。又力膺切。廣韵、集韵皆兼入蒸、職二韵。一力膺切。一紀力切。葢許書本作讀若棘。夌聲而讀同棘。一部與六部之合也。或又讀若陵。註陵於旁。而小徐㒳存之。"}]},"血":{"expl":"祭所薦牲血也。从皿，一象血形。凡血之屬皆从血。","rad":"血","fq":"呼決切","vol":"05","py":"xuè","duan":[{"e":"祭所薦牲血也。","n":"肉部曰。？、血祭肉也。爨部曰。釁、血祭也。郊特牲曰。毛血吿幽全之物也。注。幽謂血也。毛詩血以吿殺。膋以𦫵臭。此皆血祭之事。按不言人血者、爲其字从皿。人血不可入於皿。故言祭所薦牲血。然則人何以亦名血也。以物之名加之人。古者茹毛飮血。用血報神。因製血字。而用加之人。"}]},"衁":{"expl":"血也。从血亡聲。《春秋傳》曰：“士刲羊，亦無𥁃也。”","rad":"血","fq":"呼光切","vol":"05","py":"huānɡ","duan":[{"e":"血也。","n":"易歸妹上六。女承筐無實。士刲羊無血。左傳。晉筮繇曰。士刲羊亦無衁也。女承筐亦無況也。正義曰。易言血而此言衁。故杜知衁是血也。"}]},"衃":{"expl":"凝血也。从血不聲。","rad":"血","fq":"芳桮切","vol":"05","py":"pēi","duan":[{"e":"凝血也。","n":"素問赤如衃血者死注。衃血、謂敗惡凝聚之血。色赤黑也。"}]},"𧗁":{"expl":"气液也。从血𦘔聲。","rad":"血","fq":"將鄰切","vol":"05","py":"jīn","duan":[{"e":"气液也。","n":"此字各書皆假津爲之。津行而？廢矣。水部曰。液、？也。"}]},"𧖨":{"expl":"定息也。从血，甹省聲。讀若亭。","rad":"血","fq":"特丁切","vol":"05","py":"tínɡ","duan":[{"e":"定息也。","n":"心部曰。息、喘也。喘定曰？。"}]},"衄":{"expl":"鼻出血也。从血丑聲。","rad":"血","fq":"女六切","vol":"05","py":"nǜ","duan":[{"e":"鼻出血也。","n":"素問曰。鼻衄。又脾移熱於肝則爲驚衄。按諸書用挫衄者、縮朒字之假借也。縮朒者、退卻之意也。"}]},"𧗕":{"expl":"腫血也。从血，䢉省聲。","rad":"血","fq":"奴冬切","vol":"05","py":"nónɡ","duan":[{"e":"腫血也。","n":"腫、癰也。停滯之血則爲？。周禮注曰。潰瘍癰而含膿血者。"}]},"𧖺":{"expl":"血醢也。从血䏙聲。《禮記》有𧖺醢，以牛乾脯、粱、𥶶、鹽、酒也。","rad":"血","fq":"他感切","vol":"05","py":"tǎn","duan":[{"e":"血醢也。","n":"以血爲醢。故字从血。"}]},"䖂":{"expl":"鳧葵也。从艸攣聲。","rad":"艸","fq":"洛官切","vol":"01","py":"luán","duan":[{"e":"鳧葵也。","n":"後又云𦯄、鳧葵也。二字不同處者、以小篆、籒文別之也。䖂𦯄雙聲。廣雅曰。䖂、𦯄、鳧葵也。按䖂蓴古今字。古作䖂。今作蓴作蒓。"}]},"𧗎":{"expl":"醢也。从血菹聲。","rad":"血","fq":"側余切","vol":"05","py":"zú","duan":[{"e":"醢也。从血。菹聲。","n":"醢人注曰。凡醯醬所和。細切爲韲。全物若䐑爲菹。少儀曰。麋鹿爲菹。野豕爲軒。皆䐑而不切。麇爲辟雞。兔爲宛脾。皆䐑而切之。切葱若薤。實之醯以柔之。由此言之。則韲菹之稱菜肉通。按菹亦爲肉稱。故其字又作？。从血菹會意也。从血猶从肉也。側余切。五部。"}]},"𧗓":{"expl":"以血有所刏涂祭也。从血幾聲。","rad":"血","fq":"渠稀切","vol":"05","py":"jī","duan":[{"e":"㠯血有所刏涂祭也。","n":"詳刀部刏下。𧗇葢亦刏字之異者。"}]},"卹":{"expl":"憂也。从血卩聲。一曰鮮少也。","rad":"血","fq":"辛聿切","vol":"05","py":"xù","duan":[{"e":"憂也。","n":"憂當作𢝊。𢝊、愁也。釋詁曰。恤、憂也。卹與心部恤音義皆同。古書多用卹字。後人多改爲恤。如比部引周書無毖于卹、潘岳藉田賦惟榖之卹、李注引書惟刑之卹、今尙書卹皆作恤是也。"}]},"衋":{"expl":"傷痛也。从血、聿，皕聲。《周書》曰：“民冈不衋傷心。”","rad":"血","fq":"許力切","vol":"05","py":"xì","duan":[{"e":"傷痛也。","n":"某氏注尙書亦云衋然痛傷其心。"}]},"䘓":{"expl":"羊凝血也。从血臽聲。","rad":"血","fq":"苦紺切","vol":"05","py":"kàn","duan":[{"e":"羊凝血也。","n":"釋名曰。血䐄、以血作之。䐄卽䘓字也。陶氏注本艸。宋帝時太官作血䘓。庖人削藕皮。誤落血中。遂皆散不凝。陶所云血䘓、卽劉之血䐄也。按必系諸羊者、惟羊血供飮食。前云衁血也、衃凝血也皆謂人。至？𧗇䘓三字乃言牲血。此許書嚴人物之辨也。"}]},"盇":{"expl":"覆也。从血、大。","rad":"血","fq":"胡臘切","vol":"05","py":"hé","duan":[{"e":"覆也。","n":"皿中有血而上覆之。覆必大於下。故从大。艸部之葢从盇會意。訓苫、覆之引伸耳。今則葢行而盇廢矣。曷、何也。凡言何不者、急言之亦曰何。是以釋言云曷、盇也。鄭注論語云。盇、何不也。盇古音在十五部。故爲曷之假借。又爲葢之諧聲。今入七八部。爲閉口音。非古也。"}]},"衊":{"expl":"污血也。从血蔑聲。","rad":"血","fq":"莫結切","vol":"05","py":"miè","duan":[{"e":"污血也。","n":"漢文三王傳。污衊宗室。孟康曰。衊音漫。"}]},"丶":{"expl":"有所絕止，丶而識之也。凡丶之屬皆从丶。","rad":"丶","fq":"知庾切","vol":"05","py":"zhǔ","duan":[{"e":"有所絕止。丶而識之也。","n":"按此於六書爲指事。凡物有分別、事有可不、意所存主、心識其處者皆是。非專謂讀書止、輒乙其處也。知庾切。古音在四部。"}]},"主":{"expl":"鐙中火主也。从纹，象形。从丶，丶亦聲。","rad":"丶","fq":"之庾切","vol":"05","py":"zhǔ","duan":[{"e":"鐙中火主也。","n":"釋器。瓦豆謂之登。郭曰。卽膏鐙也。膏鐙、說文金部之鐙錠二字也。其形如豆。今之鐙盞是也。上爲盌盛膏而？火是爲主。其形甚微而明照一室。引伸假借爲臣主、賔主之主。"}]},"咅":{"expl":"相與語，唾而不受也。从丶从否，否亦聲。","rad":"丶","fq":"天口切","vol":"05","py":"pǒu","duan":[{"e":"相與語唾而不受也。","n":"今俗有此。"}]},"䓞":{"expl":"艸也。可以染留黃。从艸戾聲。","rad":"艸","fq":"郎計切","vol":"01","py":"lì","duan":[{"e":"艸也。可㠯染畱黃。","n":"糸部綟下曰。帛、䓞艸染色也。畱黃、辭賦家多作流黃。皇侃禮記義疏作駵黃。土剋水。故中央駵黃。色黃黑也。漢諸矦王盭綬。晉灼曰。盭、艸名。出琅邪平昌縣。似艾。可染黃。因以爲綬名。玉裁按。盭、同音叚借字也。漢制盭綬在紫綬之上。其色黃而近綠。故徐廣云似綠。或云似紫綬、名緺綬者、非也。緺、紫靑色。與綟不同。"}]},"丹":{"expl":"巴越之赤石也。象采丹井，一象丹形。凡丹之屬皆从丹。","rad":"丹","fq":"都寒切","vol":"05","py":"dān","duan":[{"e":"巴越之赤石也。","n":"巴郡、南越皆出丹沙。蜀都賦。丹沙赩熾出其坂。謂巴也。吳都賦。赬丹明璣。謂越也。丹者、石之精。故凡藥物之精者曰丹。"}]},"雘":{"expl":"善丹也。从丹蒦聲。《周書》曰：“惟其𢾅丹雘。”讀若隺。","rad":"丹","fq":"烏郭切","vol":"05","py":"wò","duan":[{"e":"善丹也。","n":"按南山經曰。雞山、其下多丹雘。侖者之山、其下多靑雘。然則凡采色之善者皆偁雘。葢本善丹之名移而他施耳。亦猶白丹、靑丹、黑丹皆曰丹也。"}]},"彤":{"expl":"丹飾也。从丹从彡。彡，其畫也。","rad":"丹","fq":"徒冬切","vol":"05","py":"tónɡ","duan":[{"e":"丹飾也。","n":"春秋經曰。丹桓宫楹。"}]},"青":{"expl":"東方色也。木生火，从生、丹。丹青之信言象然。凡青之屬皆从青。","rad":"青","fq":"倉經切","vol":"05","py":"qīnɡ","duan":[{"e":"東方色也。","n":"考工記曰。東方謂之靑。"}]},"靜":{"expl":"審也。从青爭聲。","rad":"青","fq":"疾郢切","vol":"05","py":"jìnɡ","duan":[{"e":"宷也。","n":"上林賦靚糚。張揖注曰。謂粉白黛黑也。按靚者、靜字之假借。采色詳宷得其宐謂之靜。考工記言畫繢之事是也。分佈五色。疏密有章。則雖絢爛之極。而無淟涊不鮮。是曰靜。人心宷度得宐。一言一事必求理義之必然。則雖緐勞之極而無紛亂。亦曰靜。引伸假借之義也。安靜本字當从立部之竫。"}]},"井":{"expl":"八家一井，象構韓形。•，𦉥之象也。古者伯益初作井。凡井之屬皆从井。","rad":"井","fq":"子郢切","vol":"05","py":"jǐnɡ","duan":[{"e":"八家爲一丼。","n":"穀梁傳曰。古者公田爲居。井竈葱韭盡取焉。風俗通曰。古者二十畝爲一井。因爲市交易。故稱市井。皆謂八家𠔏一井也。孟子曰。方里而井。井九百畝。其中爲公田。此古井田之制。因象井𩏑而命之也。"}]},"𤌌":{"expl":"深池也。从井，瑩省聲。","rad":"井","fq":"烏迥切","vol":"05","py":"yǐnɡ","duan":[{"e":"𥥍池也。","n":"按玉篇作澤地。雖不言出說文。然恐說文古本如是。廣韵。汫濙、小水也。濙葢卽𤌌。"}]},"阱":{"expl":"陷也。从𨸏从井，井亦聲。","rad":"井","fq":"疾正切","vol":"05","py":"jǐnɡ","duan":[{"e":"陷也。","n":"穿地陷獸。"}]},"㓝":{"expl":"罰辠也。从井从刀。《易》曰：“井，法也。”井亦聲。","rad":"井","fq":"戶經切","vol":"05","py":"xínɡ","duan":[{"e":"罰辠也。","n":"假借爲典𡌁字。"}]},"刱":{"expl":"造法刱業也。从井刅聲。讀若創。","rad":"井","fq":"初亮切","vol":"05","py":"chuànɡ","duan":[{"e":"造法刱業也。","n":"蒙上文丼者法也而言。故云造法剏業。國語、孟子字皆作創。趙氏、韋氏皆曰。創、造也。假借字也。"}]},"荍":{"expl":"蚍𧉈也。从艸收聲。","rad":"艸","fq":"渠遙切","vol":"01","py":"qiáo","duan":[{"e":"蚍𧉈也。","n":"釋艸曰。荍、蚍衃。毛傳曰。荍、芘芣也。與說文皆字異音同。陸璣曰。一名荆葵。似蕪菁。華紫綠色。可食。微苦。蚍𧉈音毗浮。"}]},"皀":{"expl":"穀之馨香也。象嘉穀在裹中之形。匕，所以扱之。或說皀，一粒也。凡皀之屬皆从皀。又讀若香。","rad":"皀","fq":"皮及切","vol":"05","py":"bī","duan":[{"e":"穀之聲香也。","n":"禾部曰。穀、續也。續當作粟。粟者、嘉穀實也。曲禮曰。黍曰薌合。梁曰薌其。薌卽香字。左傳引周書曰。黍稷非馨。明德惟馨。馨者、香之遠聞者也。香者、芳也。"}]},"卽":{"expl":"即食也。从皀卪聲。","rad":"皀","fq":"子力切","vol":"05","py":"jí","duan":[{"e":"卽食也。","n":"卽當作節。周易所謂節飲食也。節食者、檢制之使不過。故凡止於是之䛐謂之卽。凡見於經史言卽皆是也。鄭風毛傳曰。卽就也。"}]},"旣":{"expl":"小食也。从皀旡聲。《論語》曰：“不使勝食旣。”","rad":"皀","fq":"居未切","vol":"05","py":"jì","duan":[{"e":"小食也。","n":"此與口部嘰音義皆同。玉藻、少儀作禨。假借字也。引伸之義爲盡也、已也。如春秋曰有食之旣。周本紀東西周皆入於秦。周旣不祀。正與小食相反。此如亂訓治、徂訓存。旣者、終也。終則有始。小食則必盡。盡則復生。"}]},"冟":{"expl":"飯剛柔不調相著。从皀冂聲。讀若適。","rad":"皀","fq":"施隻切","vol":"05","py":"shì","duan":[{"e":"飯剛柔不調相箸。","n":"按玉篇作飯堅柔調也。無不字。非也。堅與柔不龢。謂不純堅、不純柔。柔者與堅者㒳相附箸。飯之不美者也。米者謂之糪。則純有性者也。"}]},"鬯":{"expl":"以秬釀𩰪艸，芬芳攸服，以降神也。从凵，凵，器也；中象米；匕，所以扱之。《易》曰：“不喪匕鬯。”凡鬯之屬皆从鬯。","rad":"鬯","fq":"丑諒切","vol":"05","py":"chànɡ","duan":[{"e":"㠯𩰤釀𩰪艸。芬芳攸服㠯降神也。","n":"攸服當作條暢。周禮鬯人注、大雅江漢箋皆云芬香條暢。可證也。郊特牲云。周人尙臭。灌用鬯臭。鬱合鬯。臭陰達於淵泉。云鬱合鬯、與下文蕭合黍稷皆謂二物相合也。周禮鬱人職。凡祭祀賓客之祼事。和鬱鬯以實彝而陳之。注云。築鬱金煑之以和鬯酒。按此正所謂鬱合鬯也。鄭注序官鬱人云。鬱鬱金香草。宐以和鬯。注鬯人云。鬯、釀秬爲酒。芬香條暢於上下也。是鬯與鬱之分較然矣。秬釀爲鬯。芳艸築煑爲𩰪。二者攪和之爲𩰪鬯。許說略同。故於鬯言秬釀。於𩰪言芳艸。其鬯下兼言𩰪艸者、於分中見其合。謂用秬釀及築煑之𩰪艸合和之降神。鬯主於秬釀也。故說字形曰。中象米、匕所以扱之。又按江漢傳云。秬、黑黍也。鬯、香草也。築煑合而鬱之曰鬯。此鬱鬯不爲"}]},"𩰪":{"expl":"芳艸也。十葉爲貫，百廾貫築以煑之爲𩰪。从𦥑、冂、缶、鬯；彡，其飾也。一曰𩰪鬯，百艸之華，遠方𩰪人所貢芳艸，合釀之以降神。𩰪，今𩰪林郡也。","rad":"鬯","fq":"迂勿切","vol":"05","py":"yù","duan":[{"e":"芳艸也。十葉爲貫。","n":"十當作千。百字下曰。十百爲一貫是也。周禮注作十、亦誤。"}]},"爵":{"expl":"禮器也。象爵之形，中有鬯酒，又持之也。所以飲。器象爵者，取其鳴節節足足也。","rad":"鬯","fq":"即畧切","vol":"05","py":"jué","duan":[{"e":"禮器也。","n":"古說今說皆云爵一升。韓詩說。爵觚觶角散緫名曰爵。其實曰觴。"}]},"𩰤":{"expl":"黑黍也。一稃二米，以釀也。从鬯矩聲。","rad":"鬯","fq":"其呂切","vol":"05","py":"jù","duan":[{"e":"黑黍也。一稃二米㠯釀。","n":"生民曰。誕降嘉榖。維秬維秠。毛曰。秬、黑黍也。秠、一稃二米也。禾部稃、？也。秠、一稃二米。天賜后稷之嘉榖也。是則黑黍名？。自其一稃二米言之則謂之秠。以釀酒是曰？釀。經典曰？鬯。故其字从鬯也。黑黍容有不一稃二米者。"}]},"𩰢":{"expl":"列也。从鬯吏聲。讀若迅。","rad":"鬯","fq":"疏吏切","vol":"05","py":"shǐ","duan":[{"e":"列也。","n":"列當从玉篇作烈。字之誤也。烈、火猛也。引伸爲凡猛之偁。𩰢謂酒氣酷烈。左傳。嘉栗旨酒。栗讀爲烈。𩰢引伸爲迅疾之義。今俗用駛疾字當作此。"}]},"食":{"expl":"一米也。从皀亼聲。或說亼皀也。凡食之屬皆从食。","rad":"食","fq":"乘力切","vol":"05","py":"shí","duan":[{"e":"亼米也。","n":"各本作一米也。玉篇同。葢孫強時巳誤矣。韵會本作米也。亦未是。今定爲亼米也。由亼字俗罕用而誤也。以合下云亼口例之。則此當爲亼米信矣。亼、集也。集衆米而成食也。引伸之人用供口腹亦謂之食。此其相生之名義也。下文云。飯、食也。此食字引伸之義也。人食之曰飯。因之所食曰飯。猶之亼米曰食。因之用供口腹曰食也。食下不曰飯也者何也。食者自物言。飯者自人言。嫌其義不顯。故不以飯釋食也。飯下何以云食也。自䉵篆以下皆自人言。故不嫌也。周禮膳夫職注曰。食、飯也。曲禮食居人之左注。食、飯屬也。凡今人食分去入二聲。飯分上去二聲。古皆不如此分別。"}]},"𦳈":{"expl":"蒿也。从艸毗聲。","rad":"艸","fq":"房脂切","vol":"01","py":"pí","duan":[{"e":"蒿也。从艸。𣬈聲。","n":"房脂切。十五部。"}]},"𩞑":{"expl":"滫飯也。从食𠦪聲。","rad":"食","fq":"府文切","vol":"05","py":"fēn","duan":[{"e":"脩飯也。","n":"脩各本作滫。誤今依爾雅音義引正。脩倉頡篇作𩛢。脩之言溲也。水部曰。𣸈、？汏也。飯者、人所飯也。？爾雅作饙。釋言曰。饙餾稔也。孫云。蒸之曰饙。均之曰餾。郭申之云。今呼𩛢音脩。𩛢飯爲饙。饙均孰爲餾。詩釋文引字書云。饙、一蒸米也。劉熙云。饙、分也。衆粒各自分也。按大雅。泂酌行潦。挹彼注茲。可以？饎。箋云。酌取行潦。投大器之中。又挹之注之於此小器。而可以沃酒食之餴者。以有忠信之德、齊絜之誠以薦之故也。此謂以水𣸈熱飯。古語云𩛢飯。"}]},"𩞷":{"expl":"飯气蒸也。从食畱聲。","rad":"食","fq":"力救切","vol":"05","py":"liù","duan":[{"e":"飯气流也。","n":"流各本作蒸。今依泂酌正義引改。？下云。馬食榖多气流四下也。然則飯气流者、謂气液盛流也。據孫、郭爾雅注及詩釋文所引字書。似一蒸爲？。再蒸爲餾。然許不如此說。"}]},"飪":{"expl":"大孰也。从食壬聲。","rad":"食","fq":"如甚切","vol":"05","py":"rèn","duan":[{"e":"大孰也。","n":"特牲禮請期曰羹飪注。飪、孰也。飪亦假稔爲之。釋言。饙餾稔也。字又作餁。餁同飪。"}]},"𩟷":{"expl":"孰食也。从食雝聲。","rad":"食","fq":"於容切","vol":"05","py":"yōnɡ","duan":[{"e":"孰食也。","n":"巳孰可食者也。小雅毛傳曰。孰食曰饔。周禮注曰。饔、割亨煎和之稱。"}]},"飴":{"expl":"米糱煎也。从食台聲。","rad":"食","fq":"與之切","vol":"05","py":"yí","duan":[{"e":"米糱煎者也。","n":"者字今補。米部曰。糱、芽米也。火部曰。煎、𤎅也。以芽米𤎅之爲飴。今俗用大麥。釋名曰。餳、洋也。煑米消爛洋洋然也。飴、小弱於餳。形怡怡也。內則曰。飴蜜以甘之。"}]},"𩛿":{"expl":"飴和饊者也。从食易聲。","rad":"食","fq":"徐盈切","vol":"05","py":"xínɡ","duan":[{"e":"飴和饊者也。","n":"不和饊謂之飴。和饊謂之餳。故成國云飴弱於餳也。方言曰。凡飴謂之餳。自關而東、陳楚宋衞之閒通語也。楊子渾言之。許析言之。周禮小師注。管、如今賣飴餳所吹者。周頌箋亦云。"}]},"𩟴":{"expl":"熬稻粻䅣也。从食𢿱聲。","rad":"食","fq":"穌旱切","vol":"05","py":"sǎn","duan":[{"e":"熬稻粻餭也。","n":"餭依韵會从食。各本作䅣。葢因許書無餭改之耳。楚辭、方言皆作餦餭。古字葢當作張皇。招䰟。有餦餭些。王曰。餦餭、餳也。方言曰。餳謂之餦餭。郭云。卽乾飴也。諸家渾言之。許析言之。熬、乾煎也。稻、稌也。稌者、今之稬米。米之黏者。䰞稬米爲張皇。張皇者、肥美之意也。旣又乾煎之。若今煎粢飯然。是曰饊。飴者、熬米成液爲之。米謂禾黍之米也。饊者、謂乾熬稻米之張皇爲之。㒳者一濡一小乾、相盉合則曰餳。此許意也。楊、王、郭以餳飴釋餦餭。渾言之也。豆飴謂之？。見豆部。"}]},"餅":{"expl":"麪餈也。从食并聲。","rad":"食","fq":"必郢切","vol":"05","py":"bǐnɡ","duan":[{"e":"麪餈也。","n":"麥部曰。麪、麥末也。麪餈者、餠之本義也。方言曰。餠謂之飥、或謂之餦、或謂之餛是也。"}]},"餈":{"expl":"稻餅也。从食次聲。","rad":"食","fq":"疾資切","vol":"05","py":"cí","duan":[{"e":"稻餠也。","n":"方言曰。餌謂之餻。或謂之粢。或謂之？。或謂之餣。或謂之䬧。謂米餠也。周禮糗餌粉餈注曰。餌餈皆粉稻米、黍米所爲也。合蒸曰餌。餠之曰餈。糗者、擣粉熬大豆爲餌。餈之黏著以粉之耳。餌言糗、餈言粉、互相足。按許說與鄭不同。謂以稬米蒸孰餠之如麪餠曰餈。今江蘇之餈飯也。粉稬米而餠之而蒸之則曰餌。𩰲部云？、粉餠也是也。今江蘇之米粉餠、米粉團也。粉餠則傅之以熬米麥之乾者。故曰糗餌。米部云糗熬米麥也可證。餈則傅之以大豆之粉。米部曰粉傅面者也可證也。許不言何粉。大鄭云豆㞕。是也。"}]},"饘":{"expl":"糜也。从食亶聲。周謂之饘，宋謂之餬。","rad":"食","fq":"諸延切","vol":"05","py":"zhān","duan":[{"e":"糜也。","n":"米部曰。糜、糝也。糝、以米和羹也。按以米和羹者、鼎實也。故正考父鼎銘曰。饘於是。粥於是。以餬余口。詳䰜部。"}]},"祡":{"expl":"燒祡燓燎以祭天神。从示此聲。《虞書》曰：“至于岱宗，祡。”","rad":"示","fq":"仕皆切","vol":"01","py":"chái","duan":[{"e":"燒柴尞祭天也。","n":"此從爾雅音義。尞各本作燎。非也。火部曰。尞祡祭天也。此曰祡尞祭天也。是爲轉注冣較然者。柴與祡同此聲。故燒柴祭曰祡。釋天曰。祭天曰燔柴。祭法曰。燔柴於泰壇。祭天也。孝經說曰。封乎泰山。考績祡尞。郊特牲曰。天子適四方。先祡。注。所到必先燔柴。有事於上帝。"}]},"萭":{"expl":"艸也。从艸禹聲。","rad":"艸","fq":"王矩切","vol":"01","py":"yǔ","duan":[{"e":"艸也。从艸。禹聲。","n":"王矩切。五部。攷工記故書。禹之以眡其匡。先鄭讀爲萭。鄭云萭蔞。未詳何物。"}]},"𩝍":{"expl":"乾食也。从食矦聲。《周書》曰：“峙乃𩝍粻。”","rad":"食","fq":"乎溝切","vol":"05","py":"hóu","duan":[{"e":"乾食也。","n":"小雅。乾餱以愆。釋言、毛傳皆曰。餱、食也。大雅毛傳又云。餱、餱食也。凡乾者曰餱。故許曰乾食。無羊。或負其餱。亦必乾者乃可負也。小徐曰。今人謂飯乾爲餱。"}]},"餥":{"expl":"𩝍也。从食非聲。陳楚之閒相謁食麥飯曰餥。","rad":"食","fq":"非尾切","vol":"05","py":"fěi","duan":[{"e":"餱也。","n":"釋言曰。餥餱食也。"}]},"饎":{"expl":"酒食也。从食喜聲。《詩》曰：“可以饙饎。”","rad":"食","fq":"昌志切","vol":"05","py":"chì","duan":[{"e":"酒食也。","n":"大雅泂酌傳曰。饎、酒食也。七月、大田箋同。按酒食者、可喜之物也。故其字从食喜。商頌。大糦是承。傳曰。糦、黍稷也。周禮饎人。大鄭注云。饎人、主炊官也。特牲饋食禮注曰。炊黍稷曰饎。皆依文爲訓。由黍稷而炊之。爲酒爲食。其事相貫。饎本酒食之偁。因之名炊曰饎。因之名黍稷曰饎。引伸之義也。方言。糦、孰食也。氣孰曰糦。據毛詩箋則古文以喜爲饎。"}]},"籑":{"expl":"具食也。从食算聲。","rad":"食","fq":"士戀切","vol":"05","py":"zhuàn","duan":[{"e":"具食也。","n":"？部曰。具、共置也。禮經凡言饌注曰。陳也。陳與置義同。論語曰。有酒食。先生饌。"}]},"養":{"expl":"供養也。从食羊聲。","rad":"食","fq":"余兩切","vol":"05","py":"yǎnɡ","duan":[{"e":"供養也。","n":"今人分別上去。古無是也。"}]},"飯":{"expl":"食也。从食反聲。","rad":"食","fq":"符萬切","vol":"05","py":"fàn","duan":[{"e":"食也。","n":"自饎篆巳上皆自物言之。自䉵篆巳下皆自人言之。然則云食也者、謂食之也。此飯之本義也。引伸之所食爲飯。今人於本義讀上聲。於引伸之義讀去聲。古無是分別也。禮記音義云。依字書食旁作卞、扶万反。謂所食也。食旁作反、符晚反。謂食之也。二字不同。今則混之。故隨俗而音此字。陸語殊誤。古衹有飯字。後乃分別作？。俗又作飰。此正如汳水俗作汴也。唐以前書多作？字。後來多譌爲餠字。"}]},"𩚖":{"expl":"雜飯也。从食丑聲。","rad":"食","fq":"女久切","vol":"05","py":"niù","duan":[{"e":"襍飯也。从食。丑聲。","n":"女久切。三部。按米部曰。粈、襍飯也。此？篆葢俗增。故非其次。宐刪。"}]},"飤":{"expl":"糧也。从人、食。","rad":"食","fq":"祥吏切","vol":"05","py":"sì","duan":[{"e":"糧也。从人食。","n":"祥吏切。一部。按以食食人物。其字本作食。俗作飤。或作飼。經典無飤。許云。䬴、食馬榖也。不作飤馬。此篆淺人所增。故非其次。𥼶爲糧也。又非。宐刪。"}]},"饡":{"expl":"以羹澆飯也。从食贊聲。","rad":"食","fq":"則榦切","vol":"05","py":"zàn","duan":[{"e":"㠯羹澆飯也。","n":"此飯用引伸之義。謂以羹澆飯而食之也。考工記注曰。瓚讀𩜾𩛻之𩛻。𩛻卽饡字也。玉篇曰。䬤者、饡之古文。然則本作䬤。轉寫作𩛻耳。內則注曰。狼臅膏、臆中膏也。以煎稻米則似今膏𩛻矣。釋名曰。肺𦠆、𦠆饡也。以米糝之。如膏饡也。以羹澆飯者、饡之本義。膏饡者、漢人所爲。"}]},"𩞧":{"expl":"晝食也。从食象聲。","rad":"食","fq":"書兩切","vol":"05","py":"shǎnɡ","duan":[{"e":"晝食也。","n":"此猶朝曰饔、夕曰飱也。晝食曰𩞧。俗譌爲日西食曰𩞧。見廣韵。今俗謂日西爲晌午。頃刻爲半晌。猶𩞧之遺語也。"}]},"荑":{"expl":"艸也。从艸夷聲。","rad":"艸","fq":"杜兮切","vol":"01","py":"tí","duan":[]},"𩚏":{"expl":"餔也。从夕、食。","rad":"食","fq":"思魂切","vol":"05","py":"sūn","duan":[{"e":"餔也。","n":"小雅傳曰。孰食曰饔。魏風傳曰。孰食曰飧。然則饔飧皆謂孰食。分別之則謂朝食夕食。許於饔不言朝。於飧不言孰。互文錯見也。趙注孟子曰。朝食曰饔。夕曰飧。此析言之。公羊傳趙盾食魚飧。左傳僖負羈饋盤飧、趙衰以壷飧從。皆不必夕時。渾言之也。司儀注曰。小禮曰飧。大禮曰饔餼。掌客。上公飧五牢。饔餼九牢。侯伯飧四牢。饔餼七牢。子男飧三牢。饔餼五牢。此飧饔與常食不同。且多生腥。不皆孰物。"}]},"餔":{"expl":"日加申時食也。从食甫聲。","rad":"食","fq":"博狐切","vol":"05","py":"bū","duan":[{"e":"申時食也。","n":"各本申時上有日加二字。今依廣韵、類篇、韵會正。淮南書云。日至於悲谷是謂餔時。餔一作晡。引伸之義凡食皆曰餔。又以食食人謂之餔。"}]},"餐":{"expl":"吞也。从食𣦼聲。","rad":"食","fq":"七安切","vol":"05","py":"cān","duan":[{"e":"吞也。","n":"口部曰。吞、咽也。鄭風曰。使我不能餐兮。魏風曰。彼君子兮。不素餐兮。是則餐猶食也。鄭風。還、子授子之粲兮。釋言、毛傳皆曰。粲、餐也。謂粲爲餐之假借字也。餐訓吞。引伸之爲人食之。又引伸之爲人所食。故曰授餐。飧與餐、其義異。其音異。其形則飧或作飱、餐或作䬸。鄭風、釋言音義誤認餐爲飧字耳。而集韵、類篇竟謂飧餐一字。"}]},"䭑":{"expl":"嘰也。从食兼聲。讀若風溓溓。一曰廉潔也。","rad":"食","fq":"力鹽切","vol":"05","py":"lián","duan":[{"e":"嘰也。","n":"口部曰。嘰、小食也。"}]},"饁":{"expl":"餉田也。从食盍聲。《詩》曰：“饁彼南畝。”","rad":"食","fq":"筠輒切","vol":"05","py":"yè","duan":[{"e":"餉田也。","n":"釋詁、豳傳皆曰。饁、饋也。孫炎云。饁、野之餉。"}]},"饟":{"expl":"周人謂餉曰饟。从食襄聲。","rad":"食","fq":"人漾切","vol":"05","py":"xiǎnɡ","duan":[{"e":"周人謂餉曰饟。","n":"周頌曰。其饟伊黍。正周人語也。釋詁曰。饁饟饋也。"}]},"餉":{"expl":"饟也。从食向聲。","rad":"食","fq":"式亮切","vol":"05","py":"xiǎnɡ","duan":[{"e":"饋也。","n":"饋各本作饟。今依韵會本。孟子說葛伯仇餉云。老弱饋食。又云。有童子以黍肉餉。"}]},"饋":{"expl":"餉也。从食貴聲。","rad":"食","fq":"求位切","vol":"05","py":"kuì","duan":[{"e":"餉也。","n":"饋之言歸也。故饋多假歸爲之。論語詠而饋、饋孔子豚、齊人饋女樂。古文皆作饋。魯皆作歸。鄭皆从古文。聘禮。歸饔餼五牢。鄭云。今文歸或爲饋。今本集解陽貨、微子篇作歸。依集解引孔安國語、則當作饋也。"}]},"饗":{"expl":"鄉人飲酒也。从食从鄉，鄉亦聲。","rad":"食","fq":"許兩切","vol":"05","py":"xiǎnɡ","duan":[{"e":"鄉人㱃酒也。","n":"豳風。朋酒斯饗。曰殺羔羊。傳曰。饗、鄉人飮酒也。其牲、鄉人以狗。大夫加以羔羊。此傳各本譌奪。依正義攷定如是。許君所本也。饗字之本義也。孔沖遠曰。鄉人飮酒而謂之饗者。鄉飮酒禮尊事重故以饗言之。此不知亯燕之亯正作亯。亯、獻也。左傳作亯爲正字。周禮、禮記作饗爲同音假借字。猶之左傳作宴爲正字。宴、安也。禮經、周禮作燕爲同音假借字也。沖遠證之以用樂或上取。其說迂曲矣。至若毛詩云我將我亯。下文云旣右饗之。云以亯以祀。下文云神保是饗。云亯以騂犧。下文云是饗是宜。毛詩之例。凡獻於上曰亯。凡食其獻曰饗。左傳用字正同。凡左氏亯燕字皆作亯。惟用人其誰饗之、字作饗。"}]},"饛":{"expl":"盛器滿皃。从食蒙聲。《詩》曰：“有饛簋飧。”","rad":"食","fq":"莫紅切","vol":"05","py":"ménɡ","duan":[{"e":"盛器滿皃。","n":"小雅傳曰。饛、滿簋貌。許謂字之本義不專謂簋也。故易爲器。"}]},"𧀼":{"expl":"艸也。从艸辥聲。","rad":"艸","fq":"私列切","vol":"01","py":"xuē","duan":[{"e":"艸也。","n":"子虛賦。高燥生薛。張揖曰。薛、賴蒿也。按賴蒿、葢卽藾蕭。"}]},"飵":{"expl":"楚人相謁食麥曰飵。从食乍聲。","rad":"食","fq":"在各切","vol":"05","py":"zuò","duan":[{"e":"楚人相謁食麥曰飵。","n":"方言。餥飵食也。陳楚之內相謁而食麥饘謂之餥。楚曰飵。凡陳楚之郊南楚之外相謁而餐或曰酢、或曰䬯。秦晉之際、河陰之閒曰䭡䭓。此秦語也。"}]},"䬯":{"expl":"相謁食麥也。从食占聲。","rad":"食","fq":"奴兼切","vol":"05","py":"nián","duan":[{"e":"相謁食麥也。从𠊊。占聲。","n":"奴兼切。七部。"}]},"䭡":{"expl":"秦人謂相謁而食麥曰䭡䭓。从食㥯聲。","rad":"食","fq":"烏困切","vol":"05","py":"wèn","duan":[{"e":"秦人謂相謁而食麥曰䭡䭓。从𠊊。㥯聲。","n":"烏困切。十三部。"}]},"䭓":{"expl":"䭡䭓也。从食豈聲。","rad":"食","fq":"五困切","vol":"05","py":"wèn","duan":[{"e":"䭡䭓也。从𠊊。豈聲。","n":"五困切。十三部。豈聲在十五部。合音也。"}]},"餬":{"expl":"寄食也。从食胡聲。","rad":"食","fq":"戶吳切","vol":"05","py":"hú","duan":[{"e":"寄食也。","n":"左傳。餬其口於四方。方言曰。餬、寄也。寄食曰餬。引伸之義、釋言曰餬饘也是。"}]},"飶":{"expl":"食之香也。从食必聲。《詩》曰：“有飶其香。”","rad":"食","fq":"毗必切","vol":"05","py":"bì","duan":[{"e":"食之香也。","n":"周頌傳曰。飶、芬香皃。許云食之香、爲其字从食也。"}]},"𩜈":{"expl":"燕食也。从食芺聲。《詩》曰：“飲酒之𩜈。”","rad":"食","fq":"依據切","vol":"05","py":"yù","duan":[{"e":"燕食也。","n":"燕同宴。安也。安食者、無事之食也。無事食則充腹而巳。故語曰猒飫。釋言曰。飫、私也。私卽安食之謂。此非周語房烝立成之飫。亦非毛傳脫屨升堂之飫。其字下與飽䬼饒餘相屬。則其義略同也。"}]},"飽":{"expl":"猒也。从食包聲。","rad":"食","fq":"博巧切","vol":"05","py":"bǎo","duan":[{"e":"猒也。","n":"甘部曰。猒、飽也。是爲轉注。"}]},"䬼":{"expl":"猒也。从食肙聲。","rad":"食","fq":"烏玄切","vol":"05","py":"yuàn","duan":[{"e":"猒也。","n":"賈思勰齊民要術曰。食飽不䬼。按猒、飽也。䬼則有猒棄之意。皆猒中之義也。吕覽曰。甘而不噮。玉篇、集韵引同。噮卽䬼字。廣韵曰。噮、甘而猒也。是也。集韵鐸韵又引伊尹曰。甘而不䬼。肥而不？。"}]},"饒":{"expl":"飽也。从食堯聲。","rad":"食","fq":"如昭切","vol":"05","py":"ráo","duan":[{"e":"飽也。","n":"饒者、甚飽之䛐也。引以爲凡甚之偁。漢謠曰。今年尙可後年饒。謂後年更甚也。近人索饒、討饒之語。皆謂已甚而求巳也。"}]},"苦":{"expl":"大苦，苓也。从艸古聲。","rad":"艸","fq":"康杜切","vol":"01","py":"kǔ","duan":[{"e":"大苦、","n":"逗。"}]},"餘":{"expl":"饒也。从食余聲。","rad":"食","fq":"以諸切","vol":"05","py":"yú","duan":[{"e":"饒也。从食。余聲。","n":"以諸切。五部。"}]},"餀":{"expl":"食臭也。从食艾聲。《爾雅》曰：“餀謂之喙。”","rad":"食","fq":"呼艾切","vol":"05","py":"hài","duan":[{"e":"食臭也。","n":"食臭、謂殠而食之也。儀禮音義引孟子飯殠。"}]},"餞":{"expl":"送去也。从食戔聲。《詩》曰：“顯父餞之。”","rad":"食","fq":"才線切","vol":"05","py":"jiàn","duan":[{"e":"送去食也。","n":"各本少食字。今依左傳音義補。毛傳曰。祖而舍軷。飮酒於其側曰餞。"}]},"餫":{"expl":"野饋曰餫。从食軍聲。","rad":"食","fq":"王問切","vol":"05","py":"yùn","duan":[{"e":"野饋曰餫。","n":"左傳。晉荀首如齊逆女。宣伯餫諸榖。杜云。野饋曰餫。運糧饋之。敬大國也。按餫之言運也。遠䛐也。榖、齊地。魯之禮不當至此。是野饋也。犧象不出門。嘉樂不野合。傳書餫者譏之也。小雅黍苗箋云。營謝轉餫之役。有負任者。有輓輦者。有將車者。有牽徬牛者。可證餫爲運糧。"}]},"館":{"expl":"客舍也。从食官聲。《周禮》：五十里有市，市有館，館有積，以待朝聘之客。","rad":"食","fq":"古玩切","vol":"05","py":"ɡuǎn","duan":[{"e":"客舍也。","n":"鄭風、大雅傳曰。館、舍也。按館古假觀爲之。如白虎通引于邠斯觀。又引春秋築王姬觀于外。沈約宋書曰。陰館前漢作觀。後漢、晉作館。東觀餘論曰。漢書郊祀志作益壽延壽館。封禪書云。作益延壽觀。漢書衍一壽字耳。自唐以前六朝時。凡今道觀皆謂之某館。至唐始定謂之觀。"}]},"饕":{"expl":"貪也。从食號聲。","rad":"食","fq":"土刀切","vol":"05","py":"tāo","duan":[{"e":"貪也。从食。號聲。","n":"土刀切。二部。"}]},"飻":{"expl":"貪也。从食，殄省聲。《春秋傳》曰：“謂之饕飻。”","rad":"食","fq":"他結切","vol":"05","py":"tiè","duan":[{"e":"貪也。从食。㐱聲。","n":"鉉本作殄省聲。不明於平入一理。妄改之也。他結切。十二部。"}]},"饖":{"expl":"飯傷𤍠也。从食歲聲。","rad":"食","fq":"於廢切","vol":"05","py":"wèi","duan":[{"e":"飯傷熱也。","n":"周禮、禮記皆言食齊視春時。鄭皆曰。飯宐溫。按溫者、不寒不熱之謂也。曲禮曰。毋揚飯。注云。嫌欲疾也。按飯傷熱則或揚之矣。爾雅音義引倉頡篇。饖、食臭敗也。廣韵本之。與許異。玉篇無饖。"}]},"饐":{"expl":"飯傷溼也。从食壹聲。","rad":"食","fq":"乙冀切","vol":"05","py":"yì","duan":[{"e":"飯傷溼也。","n":"魚部曰。鮑、饐魚也。是引伸之凡淹漬皆曰饐也。字林云。饐、飯傷熱溼也。混饐於饖。葛洪云。饐、飯餿臭也。本論語孔注。而非許說。"}]},"餲":{"expl":"飯餲也。从食曷聲。《論語》曰：“食饐而餲。”","rad":"食","fq":"乙例切","vol":"05","py":"ài","duan":[{"e":"飯餲也。","n":"飯餲者、謂飯久而味變。餲之言？也。今江蘇俗云餲生。當作此字。鄉黨篇食饐而餲。孔曰。饐餲、臰味變也。皇侃云。饐謂飮食經久而腐臰也。餲謂經久而味惡也。是則孔注本作饐臭、餲味變也。今本誤倒耳。據論語及許說。饐餲是二事。析言之也。釋器云。食饐謂之餲。則統言之。李充云。皆飮食壞敗之名。是也。"}]},"菩":{"expl":"艸也。从艸咅聲。","rad":"艸","fq":"步乃切","vol":"01","py":"bèi","duan":[{"e":"艸也。","n":"周禮注。犯軷以菩芻棘柏爲神主。郭樸注穆天子傳云。萯今菩字。按許書則菩、萯各物各字也。"}]},"饑":{"expl":"穀不孰爲饑。从食幾聲。","rad":"食","fq":"居衣切","vol":"05","py":"jī","duan":[{"e":"榖不孰爲饑。","n":"釋天文。又曰。仍饑爲荐。按論語年饑、因之以饑饉。鄭本皆作飢。"}]},"饉":{"expl":"蔬不孰爲饉。从食堇聲。","rad":"食","fq":"渠吝切","vol":"05","py":"jǐn","duan":[{"e":"蔬不孰爲饉。","n":"釋天文。按許書無蔬字。此蔬當是本作疏。疏之言疋也。凡艸菜可食者、皆有根足而生也。"}]},"𩚬":{"expl":"飢也。从食戹聲。讀若楚人言恚人。","rad":"食","fq":"於革切","vol":"05","py":"è","duan":[{"e":"飢也。","n":"廣韵作飢皃。"}]},"餧":{"expl":"飢也。从食委聲。一曰魚敗曰餧。","rad":"食","fq":"奴罪切","vol":"05","py":"něi","duan":[]},"飢":{"expl":"餓也。从食几聲。","rad":"食","fq":"居夷切","vol":"05","py":"jī","duan":[{"e":"餓也。","n":"與饑分別。葢本古訓。諸書通用者多有。轉寫錯亂者亦有之。"}]},"餓":{"expl":"飢也。从食我聲。","rad":"食","fq":"五箇切","vol":"05","py":"è","duan":[{"e":"飢也。从食。我聲。","n":"五箇切。十七部。"}]},"餽":{"expl":"吳人謂祭曰餽。从食从鬼，鬼亦聲。","rad":"食","fq":"俱位切","vol":"05","py":"ɡuì","duan":[{"e":"吳人謂祭曰餽。","n":"方言。䭨餟餽也。三字皆謂祭。戰國策三十三。飮食餔餽。高注。吳謂祭鬼爲餽。古文通用。讀與饋同。按祭鬼者、餽之本義。不同饋也。以餽爲饋者、古文假借也。高說與楊、許同。今本高注淺人增竄。不可從。"}]},"餟":{"expl":"𥙊酹也。从食叕聲。","rad":"食","fq":"陟衞切","vol":"05","py":"zhuì","duan":[{"e":"祭酹也。","n":"酉部曰。酹、餟祭也。史記孝武帝紀。其下四方地爲餟食。封禪書作醊食。漢郊祀志作腏。方言。餟、餽也。"}]},"䬽":{"expl":"小餟也。从食兌聲。","rad":"食","fq":"輸芮切","vol":"05","py":"shuì","duan":[{"e":"小餟也。","n":"方言。鑴、餽也。玉篇云。䭨同䬽。廣雅。祱、祭也。祱亦同䬽。"}]},"𩜁":{"expl":"馬食穀多，气流四下也。从食夌聲。","rad":"食","fq":"里甑切","vol":"05","py":"línɡ","duan":[{"e":"馬食穀多。气流四下也。","n":"謂汗液前後左右四面流下也。？與淋雙聲義近。由於食榖多也。故从食。"}]},"𦺳":{"expl":"薏苢。从艸𠶷聲。一曰𦺳英。","rad":"艸","fq":"於力切","vol":"01","py":"yì","duan":[{"e":"𦺳苢。","n":"本艸經艸部上品有薏苡人。陶隱居云。生交阯者子冣大。彼土人呼爲𦼮音幹珠。馬援大取將還。人讒以爲珍珠也。按𦼮與？雙聲。"}]},"䬴":{"expl":"食馬穀也。从食末聲。","rad":"食","fq":"莫撥切","vol":"05","py":"mò","duan":[{"e":"食馬穀也。","n":"以榖飤馬也。周南傳曰。秣、養也。小雅。乘馬在廏。摧之秣之。傳曰。摧、挫也。秣、粟也。按挫謂以莝飤之、粟謂以粟飤之也。秣同䬴。"}]},"餕":{"expl":"食之餘也。从食夋聲。","rad":"食","fq":"子陖切","vol":"05","py":"jùn","duan":[]},"餻":{"expl":"餌屬。从食羔聲。","rad":"食","fq":"古牢切","vol":"05","py":"ɡāo","duan":[]},"亼":{"expl":"三合也。从入、一，象三合之形。凡亼之屬皆从亼。讀若集。","rad":"亼","fq":"秦入切","vol":"05","py":"jí","duan":[{"e":"三合也。从人一。象三合之形。","n":"許書通例。其成字者必曰从某。如此言从入一是也。从入一而非會意。則又足之曰。象三合之形。謂似會意而實象形也。"}]},"合":{"expl":"合口也。从亼从口。","rad":"亼","fq":"候閤切","vol":"05","py":"hé","duan":[{"e":"亼口也。","n":"各本亼作合。誤。此以其形釋其義也。三口相同是爲合。十口相傳是爲古。引伸爲几會合之偁。釋詁曰。㪉郃盍翕仇偶妃匹會合也。妃合會對也。"}]},"僉":{"expl":"皆也。从亼从吅从从。《虞書》曰：“僉曰伯夷。”","rad":"亼","fq":"七廉切","vol":"05","py":"qiān","duan":[{"e":"皆也。","n":"釋詁曰。僉咸胥皆也。"}]},"侖":{"expl":"思也。从亼从冊。","rad":"亼","fq":"力屯切","vol":"05","py":"lún","duan":[{"e":"思也。","n":"龠下曰。侖、理也。大雅毛傳曰。論、思也。按論者、侖之假借。思與理、義同也。思猶䚡也。凡人之思必依其理。倫論字皆以侖會意。"}]},"今":{"expl":"是時也。从亼从绁。绁，古文及。","rad":"亼","fq":"居音切","vol":"05","py":"jīn","duan":[{"e":"是時也。","n":"今者對古之偁。古不一其時。今亦不一其時也。云是時者。如言目前。則目前爲今。目前已上皆古。如言趙宋。則趙宋爲今。趙宋已上爲古。如言魏晉。則魏晉爲今。魏晉已上爲古。班固作古今人表。漢人不與焉。而謂之古今人者、謂近乎漢者爲今人。遠乎漢者爲古人也。作古今人表者所以補漢書之所無。存漢已前之厓略也。亦謂三皇至漢以前迭爲古今人也。古今人用字不同、謂之古今字。張揖作古今字詁是也。自張揖已後。其爲古今字又不知幾更也。古今音之不同近世言之冣詳。自商周至近世、不知凡幾古今也。故今者、無定之䛐。約之以是時則兼賅矣。召南傳曰。今、急辭也。今急㬪韵。"}]},"舍":{"expl":"市居曰舍。从亼、屮，象屋也。口象築也。","rad":"亼","fq":"始夜切","vol":"05","py":"shè","duan":[{"e":"市居曰舍。","n":"食部曰。館、客舍也。客舍者何也。謂巿居也。巿居者何也。周禮遺人曰。凡國野之道。十里有廬。廬有飮食。三十里有宿。宿有路室。路室有委。五十里有巿。巿有𠋫館。𠋫館有積。鄭云。一巿之閒。有三廬一宿。𠊱館及廬、宿皆所謂巿居曰舍也。此巿字非買賣所之。謂賔客所之也。舍可止。引伸之爲凡止之偁。釋詁曰。廢稅赦舍也。凡止於是曰舍。止而不爲亦曰舍。其義異而同也。猶置之而不用曰廢。置而用之亦曰廢也。論語。不舍晝夜。謂不放過晝夜也。不放過晝夜、卽是不停止於某一晝一夜。以今俗音讀之。上去無二理也。古音不分上去。舍捨二字義相同。"}]},"會":{"expl":"合也。从亼，从曾省。曾，益也。凡會之屬皆从會。","rad":"會","fq":"黃外切","vol":"05","py":"huì","duan":[{"e":"合也。","n":"見釋詁。禮經。器之葢曰會。爲其上下相合也。凡曰會計者、謂合計之也。皆非異義也。"}]},"茅":{"expl":"菅也。从艸矛聲。","rad":"艸","fq":"莫交切","vol":"01","py":"máo","duan":[{"e":"菅也。","n":"按統言則茅菅是一。析言則菅與茅殊。許菅茅互訓。此從統言也。陸璣曰。菅似茅而滑澤、無毛。根下當作上五寸中有白粉者、柔韌宜爲索。漚乃尤善矣。此析言也。"}]},"朇":{"expl":"益也。从會卑聲。","rad":"會","fq":"符支切","vol":"05","py":"pí","duan":[{"e":"益也。","n":"朇裨古今字。今字作裨益。古字作朇益。裨行而朇廢矣。"}]},"䢈":{"expl":"日月合宿从辰。从會从辰，辰亦聲。","rad":"會","fq":"植鄰切","vol":"05","py":"chén","duan":[{"e":"日月合宿爲䢈。","n":"各本作爲辰。今依廣韵、集韵、類篇訂。左傳。晉侯問伯瑕曰。何謂六物。對曰。歲時日月星辰是謂也。公曰。多語寡人辰而莫同。何謂辰。對曰。日月之會是謂辰。故以配日。按辰以配日者、謂以從子至亥配從甲至癸也。十日、十二辰見周禮馮相氏、？蔟氏。注云。日謂從甲至癸。辰謂從子至亥。從子至亥者、日月一歲十二會。所會之處謂之十二次。星紀之次爲丑、玄枵之次一名天黿爲子、豕韋之次一名娵訾爲亥、降婁之次爲戌、大梁之次爲酉、實沈之次爲申、鶉首之次爲未、鶉火之次爲午、鶉尾之次爲巳、壽星之次爲辰、大火之次爲卯、析木之次爲寅是也。據說文則日月之合宿謂之䢈。據周禮、左傳則日月䢈處謂之辰也。䢈者、卽左傳之會字。非左傳之辰字也。"}]},"倉":{"expl":"榖藏也。倉黃取而藏之，故謂之倉。从食省，口象倉形。凡倉之屬皆从倉。","rad":"倉","fq":"七岡切","vol":"05","py":"cānɡ","duan":[{"e":"穀藏也。","n":"藏當作臧。臧、善也。引伸之義、善而存之亦曰臧。臧之之府亦曰臧。俗皆作藏。分平去二音。榖臧者、謂榖所臧之處也。广部曰。府、文書藏。庫、兵車藏。廥、芻稾藏。今音皆徂浪切。"}]},"牄":{"expl":"鳥獸來食聲也。从倉爿聲。《虞書》曰：“鳥獸牄牄。”","rad":"倉","fq":"七羊切","vol":"05","py":"qiānɡ","duan":[{"e":"鳥獸來食聲也。","n":"牄葢壁中文如此。孔安國以今文字讀之易爲蹌蹌。鄭云。飛鳥走獸蹌蹌然而舞。僞孔說本之。許則徑從牄字。說爲鳥獸來食聲。與鄭異。鄭易字。許不易字也。鄭注大司樂亦引鳥獸牄牄。公羊春秋有頓子牄。"}]},"入":{"expl":"内也。象从上俱下也。凡入之屬皆从入。","rad":"入","fq":"人汁切","vol":"05","py":"rù","duan":[{"e":"內也。","n":"自外而中也。"}]},"內":{"expl":"入也。从口，自外而入也。","rad":"入","fq":"奴對切","vol":"05","py":"nèi","duan":[{"e":"入也。","n":"今人謂所入之処爲內。乃以其引伸之義爲本義也。互易之。故分別讀奴荅切。又多假納爲之矣。周禮注云。職內、主入也。內府、主良貨賄藏在內者。然則職內之內是本義。內府之內是引伸之義。"}]},"㞥":{"expl":"入山之深也。从山从入。闕。","rad":"入","fq":"鉏箴切","vol":"05","py":"cén","duan":[]},"糴":{"expl":"市穀也。从入从䊮。","rad":"入","fq":"徒歴切","vol":"05","py":"dí","duan":[{"e":"？榖也。从入䊮。","n":"米部曰。䊮、榖也。故巿榖从入䊮。䊮亦聲。今徒歷切。古音在三部。左傳晉大夫有糴茷。"}]},"仝":{"expl":"完也。从入从工。","rad":"入","fq":"疾緣切","vol":"05","py":"quán","duan":[{"e":"完也。","n":"宀部曰。完、全也。是爲轉注。"}]},"𠓜":{"expl":"二入也。兩从此。闕。","rad":"入","fq":"良獎切","vol":"05","py":"liǎnɡ","duan":[{"e":"二入也。","n":"以形爲義。"}]},"菅":{"expl":"茅也。从艸官聲。","rad":"艸","fq":"古顔切","vol":"01","py":"jiān","duan":[{"e":"茅也。","n":"詩。白華菅兮。釋艸曰。白華野菅。毛傳足之曰。已漚爲菅。按詩謂白華旣漚爲菅又以白茅收束之。菅別於茅。野菅又別於菅也。"}]},"缶":{"expl":"瓦器。所以盛酒𤖅。秦人鼓之以節謌。象形。凡缶之屬皆从缶。","rad":"缶","fq":"方九切","vol":"05","py":"fǒu","duan":[{"e":"瓦器所㠯盛酒𤖅。","n":"釋器、陳風傳皆云。盎謂之缶。許云。盎、盆也。罌、缶也。似許與爾雅說異。缶有小有大。如汲水之缶、葢小者也。如五獻之尊、門外缶大於一石之壷、五𣁬之瓦甒、其大者也。皆可以盛酒𤖅。"}]},"䍍":{"expl":"未燒瓦器也。从缶𣪊聲。读若筩莩。","rad":"缶","fq":"","vol":"05","py":"kòu","duan":[{"e":"未燒瓦器也。","n":"土部曰。瓦未燒曰坏。䍍與坏不但義同。而音冣相近。故集韵謂爲一字、披尤切也。"}]},"匋":{"expl":"瓦器也。从缶，包省聲。古者昆吾作匋。案：《史篇》讀與缶同。","rad":"缶","fq":"徒刀切","vol":"05","py":"táo","duan":[{"e":"作瓦器也。","n":"作字各本無。今依玉篇補。大雅。陶復陶穴。箋云。復穴皆如陶然。正義引說文。匋、瓦器竈也。按穴部云。窯、燒瓦竈也。瓦部云。甄、匋也。然則依玉篇爲長。作瓦器者。䍍之燒之。皆是其事。故匋之字次於䍍。今字作陶。陶行而匋廢矣。陶見𨸏部。再成丘也。"}]},"罌":{"expl":"缶也。从缶賏聲。","rad":"缶","fq":"烏莖切","vol":"05","py":"yīnɡ","duan":[{"e":"缶也。","n":"缶、太平御覽作？。今按作缶爲是。許意缶罌？一物也。方言。㼚瓭？䍃㽀㼻甀瓮瓿甊㽈。甖也。自關而西、晉之舊都、河汾之閒、其大者謂之甀。自關而東、趙魏之郊謂之瓮。或謂之甖。甖其通語也。甀卽？。甖卽罌。瓦部曰。罌謂之㼰。瓮、罌也。康瓠、破罌也。史、漢淮陰侯傳曰。信乃益爲疑兵。乘船欲渡臨晉。而伏兵從夏陽以木罌缻渡軍。襲安邑。木罌缶者、以木爲罌缶狀。實兵於其中。不欲人知。故不爲盆狀。韋昭云。以木爲器如罌缻以渡軍。無船、且尙密也。韋說是也。罌缶器之大者。"}]},"𦉈":{"expl":"小口罌也。从缶𠂹聲。","rad":"缶","fq":"池僞切","vol":"05","py":"chuí","duan":[{"e":"小口罌也。","n":"上文罌者、兼大口小口渾言之。此云小口罌、則析言之也。小口則宁物必垂下之。故曰？。凌人注云。鑑如甀。大口。以盛冰。謂如？而大口也。醢人注曰。塗置甀中。百日則成矣。方言。罃、周洛韓鄭之閒謂之甀。或謂之罃。按罃者、？之長頸者。？不長頸。方俗或同名。"}]},"䍌":{"expl":"小缶也。从缶咅聲。","rad":"缶","fq":"蒲候切","vol":"05","py":"bù","duan":[{"e":"小缶也。","n":"按方言曰。瓿甊、甖也。自關而西、晉之舊都、河汾之閒、其大者謂之甀。其中者謂之瓿甊。又曰。缶謂之瓿㼴。許意缶罌一物也。故云瓿、小缶也。卽楊之中者謂之瓿甊也。"}]},"缾":{"expl":"𦉥也。从缶幷聲。","rad":"缶","fq":"蒲經切","vol":"05","py":"pínɡ","duan":[{"e":"𦉥也。","n":"易井卦辭曰。羸其甁。左傳衞孫蒯飮馬於重丘。毀其甁。按甁亦𧦝缶。左傳具綆缶。此缶之小者。"}]},"𦉥":{"expl":"汲缾也。从缶雝聲。","rad":"缶","fq":"烏貢切","vol":"05","py":"wènɡ","duan":[{"e":"汲缾也。","n":"丼下曰。外象構？形。其罋也。井爻辭曰。甕敝漏。按缾罋之本義爲汲器。經傳所載不獨汲水者偁缾罋也。許云汲缾。分別言之。許固謂缾不專用汲矣。𦉥俗作甕。"}]},"䍇":{"expl":"下平缶也。从缶乏聲。讀若𦐇。","rad":"缶","fq":"土盍切","vol":"05","py":"tà","duan":[{"e":"下平缶也。","n":"下當作不。字之誤也。凡器無不下平者。以從乏之意求之。當是不平缶。反正爲乏也。又以讀若𦐇求之。𦐇與替雙聲。替者一偏下也。集韵、類篇皆引說文瓨也。二書引說文皆用大徐本。何以乖異若是。廣雅。䍇、甁也。"}]},"罃":{"expl":"備火，長頸缾也。从缶，熒省聲。","rad":"缶","fq":"烏莖切","vol":"05","py":"yīnɡ","duan":[{"e":"備火長頸缾也。","n":"左傳襄九年。宋災。具綆缶。備水器。杜曰。缶、汲器也。水器、盆㽉之屬也。是謂汲水貯水之分。師古注五行志則謂缶卽盎也。水器者、罃瓮之屬。引許氏說文解字。罃、備火、今之長頸甁也。按各本無今之二字。備火長頸缾者、備火之汲罋。則長其頸以多盛水。且免傾覆也。其說左傳者、杜爲長。"}]},"蘄":{"expl":"艸也。从艸纥聲。江夏有蘄春亭。","rad":"艸","fq":"渠支切","vol":"01","py":"qí","duan":[{"e":"艸也。","n":"釋艸蘄字四見。不識許所指何物也。"}]},"缸":{"expl":"瓦也。从缶工聲。","rad":"缶","fq":"下江切","vol":"05","py":"ɡānɡ","duan":[{"e":"瓨也。","n":"瓦部曰。瓨似罌。長頸。受十斗。缸與瓨音義皆同也。史、漢貨殖傳皆曰。醯？千瓨。"}]},"𦈸":{"expl":"瓦器也。从缶或聲。","rad":"缶","fq":"于逼切","vol":"05","py":"yù","duan":[{"e":"瓦器也。从缶。或聲。","n":"于逼切。一部。"}]},"䍎":{"expl":"瓦器也。从缶薦聲。","rad":"缶","fq":"作甸切","vol":"05","py":"cùn","duan":[{"e":"瓦器也。","n":"詩斯干。乃生女子。載弄之瓦。傳曰。瓦、紡專也。箋云。紡專、習其壹所有事也。案專同塼。紡專、正義不言何物。廣韵卄二霰云。䍎、紡錘。集韵霰韵云。䍎、一曰紡甎。然則婦人撚綫錘頭。古用塼爲之。婦人所重者紡績。故箋云習其壹意於所有事也。許云瓦器。渾言之。未及詳說耳。紡錘下垂。如戈鐏之在底。故其字亦七鈍切。"}]},"䍃":{"expl":"瓦器也。从缶肉聲。","rad":"缶","fq":"以周切","vol":"05","py":"yóu","duan":[{"e":"瓦器也。从缶。肉聲。","n":"以周切。三部。"}]},"𦉢":{"expl":"瓦器也。从缶霝聲。","rad":"缶","fq":"郎丁切","vol":"05","py":"línɡ","duan":[{"e":"瓦器也。","n":"篇、韵皆云似甁有耳。"}]},"䍄":{"expl":"缺也。从缶占聲。","rad":"缶","fq":"都念切","vol":"05","py":"diǎn","duan":[{"e":"缺也。","n":"刀缺謂之㓠。瓦器缺謂之䍄。詩云。白圭之㓠。引伸通用也。"}]},"缺":{"expl":"器破也。从缶，決省聲。","rad":"缶","fq":"傾雪切","vol":"05","py":"quē","duan":[{"e":"器破也。","n":"俗誤作𡙇。又通用闕。"}]},"罅":{"expl":"裂也。从缶虖聲。缶燒善裂也。","rad":"缶","fq":"呼迓切","vol":"05","py":"xià","duan":[{"e":"裂也。","n":"考工記瓬人所謂薜也。引伸爲凡裂之偁。"}]},"罄":{"expl":"器中空也。从缶殸聲。殸，古文磬字。《詩》云：“缾之罄矣。”","rad":"缶","fq":"苦定切","vol":"05","py":"qìnɡ","duan":[{"e":"器中空也。","n":"釋詁、毛傳皆曰。罄、盡也。引伸爲凡盡之偁。如韓詩磬天之妹、毛詩俔磬也、郭注爾雅云今人呼厭極爲罄皆是。古書罄磬多互相假借。"}]},"罊":{"expl":"器中盡也。从缶𣪠聲。","rad":"缶","fq":"苦計切","vol":"05","py":"qì","duan":[{"e":"器中盡也。","n":"釋詁曰。罊、盡也。皿部曰。盡、器中空也。"}]},"莞":{"expl":"艸也。可以作席。从艸完聲。","rad":"艸","fq":"胡官切","vol":"01","py":"ɡuān","duan":[{"e":"艸也。可㠯作席。","n":"小雅。下莞上簟。箋云。莞、小蒲之席也。司几筵。蒲筵加莞席。正義。以莞加蒲。麤者在下。美者在上也。列子。老韭之爲莞。殷敬順曰。莞音官。似蒲而圓。今之爲席者是也。楊承慶字統音關。玉裁謂。莞之言管也。凡莖中空者曰管。莞葢卽今席子艸。細莖。圓而中空。鄭謂之小蒲。實非蒲也。廣雅謂之葱蒲。"}]},"缿":{"expl":"受錢器也。从缶后聲。古以瓦，今以竹。","rad":"缶","fq":"大口切","vol":"05","py":"xiànɡ","duan":[{"e":"受錢器也。","n":"易入難出器也。史記酷吏列傳。惡少年投缿。漢書。趙廣漢敎吏爲缿筩。蘇林曰。缿如瓨。可受投書。師古曰。缿、若今盛錢藏甁。爲小孔。可入而不可出。"}]},"罐":{"expl":"器也。从缶雚聲。","rad":"缶","fq":"古玩切","vol":"05","py":"ɡuàn","duan":[]},"矢":{"expl":"弓弩矢也。从入，象鏑栝羽之形。古者夷牟初作矢。凡矢之屬皆从矢。","rad":"矢","fq":"式視切","vol":"05","py":"shǐ","duan":[{"e":"弓弩矢也。","n":"弓弩所用䠶之矢也。"}]},"䠶":{"expl":"弓弩發於身而中於遠也。从矢从身。","rad":"矢","fq":"食夜切","vol":"05","py":"shè","duan":[{"e":"弓弩發於身而中於遠也。","n":"謂用弓弩發矢於身而中於遠也。詩、禮記以射爲猒斁之斁。"}]},"矯":{"expl":"揉箭箝也。从矢喬聲。","rad":"矢","fq":"居夭切","vol":"05","py":"jiǎo","duan":[{"e":"揉箭箝也。","n":"揉當作柔。許無揉有柔煣也。箭者、矢竹所爲矢也。不言矢言箭者。矯施於笴、不施於鏑羽也。箝、籋也。柔箭之箝曰矯。引伸之爲凡矯枉之偁。凡云矯詔者、本不然而云然也。"}]},"矰":{"expl":"隿䠶矢也。从矢曾聲。","rad":"矢","fq":"作滕切","vol":"05","py":"zēnɡ","duan":[{"e":"隿射矢也。","n":"周禮司弓矢云。矰矢、茀矢、用諸弋射。注云。結繳於矢謂之矰。矰、高也。茀矢象焉。茀之言刜也。二者皆可以弋飛鳥刜羅之也。前於重又微輕、行不低也。詩云。弋鳧與鴈。"}]},"矦":{"expl":"春饗所䠶矦也。从人；从厂，象張布；矢在其下。天子䠶熊虎豹，服猛也；諸矦䠶熊豕虎；大夫射麋，麋，惑也；士射鹿豕，爲田除害也。其祝曰：“毋若不寕矦，不朝于王所，故伉而䠶汝也。”","rad":"矢","fq":"乎溝切","vol":"05","py":"hóu","duan":[{"e":"春饗所射矦也。","n":"饗者、鄉人㱃酒也。春饗所射矦、謂天子諸矦養老先行大射禮之矦也。天子諸矦養老皆如鄉飮酒之禮。故亦謂之饗。文王世子曰。設三老五更群老之席位。注云。三老如鄉飮酒禮之賔。五更如介。群老如衆賔。魯頌曰。魯矦戾止。在泮飮酒。箋云。徵先生君子與之行飮酒之禮。而因以謀事也。此天子諸矦養老卽鄉飮酒之證也。廱下曰。天子饗㱃辟廱也。泮下曰。諸矦饗射泮宮也。饗皆謂養老也。古者鄉飮鄉射必聨類而行。卿大夫士之射必先行鄉飮酒之禮。天子諸侯則先大射、後養老。天子諸矦賔射於朝。燕射於寢。大射於澤、於射宮。射宮者、大學也。行葦爲養老之詩。箋云。先王將養老、先與群臣行射禮。擇其可與者以爲賔。今我成王承先王之法度。亦旣序賔矣。有醇厚"}]},"𥏫":{"expl":"傷也。从矢昜聲。","rad":"矢","fq":"式陽切","vol":"05","py":"shānɡ","duan":[{"e":"傷也。","n":"謂矢之所傷也。引伸爲凡傷之偁。"}]},"短":{"expl":"有所長短，以矢爲正。从矢豆聲。","rad":"矢","fq":"都管切","vol":"05","py":"duǎn","duan":[{"e":"有所長短。㠯矢爲正。从矢。","n":"按此上當補不長也三字乃合。有所長短、以矢爲正。說从矢之意也。榘字下曰。矢者、其中正也。正直爲正。必正直如矢而刻識之。而後可裁其長短。故詩曰。其直如矢。韓詩曰。如矢斯朸。"}]},"矤":{"expl":"況也，詞也。从矢，引省聲。从矢，取詞之所之如矢也。","rad":"矢","fq":"式忍切","vol":"05","py":"shěn","duan":[{"e":"況䛐也。","n":"各本況下有也。誤。今刪。況當作兄。古今音殊。乃或假況。許書當本作兄也。兄長之兄引伸爲兄益。詩常棣傳曰。況、滋也。桑柔傳曰。兄、滋也。召旻傳曰。兄、茲也。兄況不同。以兄爲正。滋茲不同。許皆訓益。兄䛐者、增益之䛐。其意益。其言曰矤。是爲意內言外。今俗所云已如是。況又如是也。尙書多用矤字。俗作矧。"}]},"禷":{"expl":"以事類祭天神。从示類聲。","rad":"示","fq":"力遂切","vol":"01","py":"lèi","duan":[{"e":"㠯事類祭天神。","n":"五經異義曰。今尚書夏矦、歐陽說。禷、祭天名也。以禷祭天者、以事類祭之。以事類祭之何。天位在南方、就南郊祭之是也。古尚書說非時祭天謂之禷。言以事類吿也。肆禷于上帝。時舜吿攝。非常祭也。許君謹按。周禮郊天無言禷者。知禷非常祭。從古尚書說。玉裁按。郊天不言禷。而肆師類造上帝。王制天子將出。類於上帝。皆主軍旅言。凡經傳言禷者皆謂因事爲兆。依郊禮而爲之。說文亦从古尚書說。"}]},"藺":{"expl":"莞屬。从艸閵聲。","rad":"艸","fq":"良刃切","vol":"01","py":"lìn","duan":[{"e":"莞屬。可爲席。","n":"依韵會所引補三字。急就篇有藺席。"}]},"知":{"expl":"詞也。从口从矢。","rad":"矢","fq":"陟离切","vol":"05","py":"zhī","duan":[{"e":"䛐也。","n":"白部曰。？、識䛐也。从白、从亏、从知。按此䛐也之上亦當有識字。知？義同。故？作知。"}]},"矣":{"expl":"語已詞也。从矢以聲。","rad":"矢","fq":"于已切","vol":"05","py":"yǐ","duan":[{"e":"語巳䛐也。","n":"巳矣㬪韵。巳、止也。其意止、其言曰矣。是爲意內言外。論語或單言矣。或言巳矣。如學而、子張篇皆云。可謂好學也巳矣。公冶長篇。不可得而聞也巳矣。巳矣乎吾未見能見其過而內自訟者也。俗本句末刪矣者、非。淮南書說矣與也二字不同。"}]},"矮":{"expl":"短人也。从矢委聲。","rad":"矢","fq":"烏蟹切","vol":"05","py":"ǎi","duan":[]},"高":{"expl":"崇也。象臺觀高之形。从冂、口。與倉、舍同意。凡高之屬皆从高。","rad":"高","fq":"古牢切","vol":"05","py":"ɡāo","duan":[{"e":"崇也。","n":"山部曰。崇、嵬高也。"}]},"䯧":{"expl":"小堂也。从高省，冋聲。","rad":"高","fq":"去颍切","vol":"05","py":"qǐnɡ","duan":[{"e":"小堂也。","n":"集韵曰。傾敻切。瓜屋也。"}]},"亭":{"expl":"民所安定也。亭有樓，从高省，丁聲。","rad":"高","fq":"特丁切","vol":"05","py":"tínɡ","duan":[{"e":"民所安定也。","n":"亭定㬪韵。周禮。三十里有宿。鄭云。宿可止宿。若今亭有室矣。百官公卿表曰。縣道大率十里一亭。亭有長。十亭一鄉。鄉有三老。有秩嗇夫。後漢志曰。亭有長以禁盜賊。風俗通曰。亭、畱也。葢行旅宿會之所館。釋名曰。亭、停也。人所停集。按云民所安定者、謂居民於是備盜賊、行旅於是止宿也。亭定㬪韵。亭之引伸爲亭止。俗乃製停渟字。依釋名則漢時巳有停字。而許不收。徐氏鉉云。低債價停僦伺六字皆後人所加。是也。"}]},"亳":{"expl":"京兆杜陵亭也。从高省，乇聲。","rad":"高","fq":"㫄各切","vol":"05","py":"bó","duan":[{"e":"京兆杜陵亭也。","n":"六國表。湯起于亳。徐廣曰。京兆杜縣有亳亭。錢氏大昕史記攷異曰。殷本紀。湯始居亳。皇甫謐曰。梁國榖熟爲南亳。湯所都也。立政三亳。皆非京兆之亳亭。秦本紀。寧公二年遣兵伐蕩社。三年與亳戰。亳王奔戎。遂滅蕩社。徐廣云。蕩一作湯。社一作杜。皇甫謐以爲亳號湯。西夷之國。又云。周桓王時自有亳王號湯。非殷也。封禪書于杜亳有三杜主之祠。葢京兆之亳。乃戎王號湯者之邑。徐廣以爲殷湯所起。其不然乎。然此篇稱作事者必於東南。收功實者常於西北。乃述禹興西羌、周始豐鎬、而及湯之起亳。則史公固以關中之亳系之湯矣。按許不言三亳、而獨言杜陵亳亭者。正爲其字从高。則以此亭當之也。然十里一亭者秦制。亳亭之名秦漢乃有之。亳之字固不起於"}]},"冂":{"expl":"邑外謂之郊，郊外謂之野，野外謂之林，林外謂之冂。象遠界也。凡冂之屬皆从冂。","rad":"冂","fq":"古熒切","vol":"05","py":"jiōnɡ","duan":[{"e":"邑外謂之郊。郊外謂之野。野外謂之林。林外謂之冂。","n":"與魯頌毛傳同。邑、國也。歫國百里曰郊。野、郊外也。平土有叢木曰林。皆許說也。爾雅釋地。邑外謂之郊。郊外謂之牧。牧外謂之野。野外謂之林。林外謂之坰。多謂之牧牧外五字。依野有死麇燕燕干旄傳、叔于田箋𣃔之。淺人妄增也。牧、李巡作田。王砅注素問作邑外謂之郊。郊外謂之甸。甸外謂之牧。牧外謂之林。林外謂之坰。坰外謂之野。所偁更繆。"}]},"市":{"expl":"買賣所之也。市有垣，从冂从绁，绁，古文及，象物相及也。之省聲。","rad":"冂","fq":"時止切","vol":"05","py":"shì","duan":[{"e":"買賣所之也。","n":"釋詁曰。之、往也。古史考曰。神農作市。本𣪠辭說也。世本曰。祝融作市。"}]},"冘":{"expl":"淫淫，行皃。从人出冂。","rad":"冂","fq":"余箴切","vol":"05","py":"yín","duan":[{"e":"冘冘、","n":"逗。"}]},"蒢":{"expl":"黃蒢，職也。从艸除聲。","rad":"艸","fq":"直魚切","vol":"01","py":"chú","duan":[{"e":"黃蒢、職也。","n":"釋艸。職、黃除。"}]},"央":{"expl":"中央也。从大在冂之内。大，人也。央㫄同意。一曰久也。","rad":"冂","fq":"於良切","vol":"05","py":"yānɡ","duan":[{"e":"央、中也。","n":"央逗。複舉字之未刪者也。月令曰。中央土。詩箋云。夜未渠央。古樂府。調弦未詎央。顏氏家訓作未遽央。皆卽未渠央也。渠央者、中之謂也。詩言未央、謂未中也。毛傳。央、且也。且者、薦也。凡物薦之則有二。至於艾而爲三矣。下文夜未艾。艾者、久也。箋云。芟末曰艾。以言夜先雞鳴時。合初昏與艾言之。是央爲中也。"}]},"隺":{"expl":"高至也。从隹上欲出冂。《易》曰：“夫乾隺然。”","rad":"冂","fq":"胡沃切","vol":"05","py":"hú","duan":[{"e":"高至也。从隹上欲出冂。","n":"上翔欲遠行也。胡沃切。古音在二部。"}]},"𩫖":{"expl":"度也，民所度居也。从回，象城𩫖之重，兩亭相對也。或但从囗。(音韋。)凡𩫖之屬皆从𩫖。","rad":"𩫖","fq":"古博切","vol":"05","py":"ɡuō","duan":[{"e":"度也。","n":"此以音說義。與蒦度也、音義略同。"}]},"𩫠":{"expl":"缺也。古者城闕其南方謂之𩫠。从𩫖，缺省。讀若拔物爲決引也。","rad":"𩫖","fq":"傾雪切","vol":"05","py":"quē","duan":[{"e":"缺也。","n":"以㬪韵爲義。"}]},"京":{"expl":"人所爲絕高丘也。从高省，| 象高形。凡京之屬皆从京。","rad":"京","fq":"舉卿切","vol":"05","py":"jīnɡ","duan":[{"e":"人所爲絕高丘也。","n":"釋丘曰。絕高爲之京。非人爲之丘。郭云。爲之者、人力所作也。按釋詁云。京、大也。其引伸之義也。凡高者必大。"}]},"就":{"expl":"就，高也。从京从尤。尤，異於凡也。","rad":"京","fq":"疾僦切","vol":"05","py":"jiù","duan":[{"e":"就、","n":"此複舉字之未刪者。"}]},"亯":{"expl":"獻也。从高省，曰象進孰物形。《孝經》曰：“祭則鬼亯之。”凡亯之屬皆从亯。","rad":"亯","fq":"許兩切","vol":"05","py":"xiǎnɡ","duan":[{"e":"獻也。","n":"下進上之䛐也。按周禮用字之例。凡祭亯用亯字。凡饗燕用饗字。如大宗伯吉禮下六言亯先王。嘉禮下言以饗燕之禮親四方賓客。尤其明證也。禮經十七篇用字之例。聘禮內臣亯君字作亯。士虞禮、少牢饋食禮尙饗字作饗。小戴記用字之例。凡祭亯、饗燕字皆作饗。無作亯者。左傳則皆作亯。無作饗者。毛詩之例。則獻於神曰亯。神食其所亯曰饗。如楚茨以亯以祀。下云神保是饗。周頌我將我亯。下云旣右饗之。魯頌亯祀不忒、亯以騂犧。下云是饗是宜。商頌以假以亯。下云來假來饗。皆其明證也。鬼神來食曰饗、卽禮經尙饗之例也。獻於神曰亯、卽周禮祭亯作亯之例也。各經用字自各有例。周禮之饗燕、左傳皆作亯宴。此等葢本書固尒。非由後人改竄。"}]},"𦎫":{"expl":"孰也。从亯从羊。讀若純。一曰鬻也。","rad":"亯","fq":"常倫切","vol":"05","py":"chún","duan":[{"e":"孰也。","n":"今俗云純熟。當作此字。純醇行而？廢矣。周禮司裘注。假借爲？的字。"}]},"䈞":{"expl":"厚也。从亯竹聲。讀若篤。","rad":"亯","fq":"冬毒切","vol":"05","py":"dǔ","duan":[{"e":"𣆪也。","n":"㫗各本作厚。今正。㫗厚古今字。䈞篤亦古今字。䈞與二郭部竺音義皆同。今字篤行而䈞竺廢矣。公劉毛傳曰。篤、厚也。此謂篤卽竺䈞字也。"}]},"𦤘":{"expl":"用也。从亯从自。自知臭香所食也。讀若庸。","rad":"亯","fq":"余封切","vol":"05","py":"yōnɡ","duan":[{"e":"用也。","n":"此與用部庸音義皆同。玉篇曰。？、今作庸。廣韵曰。？者、庸之古文。"}]},"蒲":{"expl":"水艸也。可以作席。从艸浦聲。","rad":"艸","fq":"薄胡切","vol":"01","py":"pú","duan":[{"e":"水艸也。或㠯作席。","n":"周禮。祭祀席有蒲筵。"}]},"㫗":{"expl":"厚也。从反亯。凡𣆪之屬皆从𣆪。","rad":"㫗","fq":"胡口切","vol":"05","py":"hòu","duan":[{"e":"厚也。","n":"厚當作䈞。上文曰䈞、㫗也。此曰㫗、篤也。是爲轉注。今字厚行而㫗廢矣。凡經典㫗薄字皆作厚。"}]},"𪉷":{"expl":"長味也。从𣆪，鹹省聲。《詩》曰：“實覃實吁。”","rad":"㫗","fq":"徒含切","vol":"05","py":"tán","duan":[{"e":"長味也。","n":"此與酉部醰音同義近。醰以覃會意也。引伸之凡長皆曰覃。葛覃傳曰。覃、延也。凡言覃及、覃思義皆同。經典葛覃字亦假蕈爲之。"}]},"厚":{"expl":"山陵之厚也。从𣆪从厂。","rad":"㫗","fq":"胡口切","vol":"05","py":"hòu","duan":[{"e":"山陵之㫗也。","n":"㫗各本作厚。今正。山陵之厚故其字从厂。今字凡㫗薄字皆作此。"}]},"畗":{"expl":"滿也。从高省，象高厚之形。凡畗之屬皆从畗。讀若伏。","rad":"畗","fq":"芳逼切","vol":"05","py":"fú","duan":[{"e":"滿也。","n":"方言。悀偪滿也。凡以器盛而滿謂之悀。注言涌出也。腹滿曰偪。注言勅偪也。按廣雅悀愊滿也、本此。而玉篇云。腹滿謂之涌。腸滿謂之畐。與今本方言異。玄應書畐塞注曰。普逼切。引方言畐滿也。是則希馮、玄應所據方言皆作畐也。許書無偪、逼字。大徐附逼於辵部。今乃知逼仄、逼迫字當作畐。偪逼行而畐廢矣。荀卿子。充盈大宇而不窕。入卻穴而不偪。淮南兵略訓。入小而不偪。處大而不窕。凡云不偪者、皆謂不塞。淮南俶眞訓。處小隘而不塞。要略訓。置之尋常而不塞。氾論訓。內之尋常而不塞。齊俗訓。大則塞而不入。小則窕而不周。偪與塞義同。畐偪正俗字也。釋言曰。逼、迫也。本又作偪。二皆畐之俗字。"}]},"良":{"expl":"善也。从畗省，亡聲。","rad":"畗","fq":"呂張切","vol":"05","py":"liánɡ","duan":[{"e":"善也。从畗省。亾聲。","n":"吕張切。十部。"}]},"㐭":{"expl":"穀所振入。宗廟粢盛，倉黃㐭而取之，故謂之㐭。从入，回象屋形，中有戶牖。凡㐭之屬皆从㐭。","rad":"㐭","fq":"力甚切","vol":"05","py":"lǐn","duan":[{"e":"穀所振入也。","n":"穀者、百榖緫名。中庸注曰。振、猶收也。手部曰。振、舉也。周禮注曰。米藏曰廩。"}]},"稟":{"expl":"賜穀也。从㐭从禾。","rad":"㐭","fq":"筆錦切","vol":"05","py":"bǐnɡ","duan":[{"e":"賜榖也。","n":"賜榖曰稟。中庸。旣稟稱事。鄭注周禮宫正、內宰、廩人、掌固皆云。稍食、祿稟也。又司稼注云。賙、稟其艱阨。晉惠帝云。官鼃可給稟。凡若此類。今本多譌爲廩。卽有未譌者、亦皆讀爲力甚切矣。今之廩膳生員、於古當作稟膳。"}]},"亶":{"expl":"多穀也。从㐭旦聲。","rad":"㐭","fq":"多旱切","vol":"05","py":"dǎn","duan":[{"e":"多榖也。","n":"亶之本義爲多榖。故其字从㐭。引伸之義爲厚也、信也、誠也。見釋詁、毛傳。"}]},"啚":{"expl":"嗇也。从口、㐭。㐭，受也。","rad":"㐭","fq":"方美切","vol":"05","py":"bǐ","duan":[{"e":"嗇也。","n":"下文云。嗇、愛濇也。水部曰。濇、不滑也。凡鄙吝字當作此。鄙行而啚廢矣。論語鄙夫、周書鄙我周邦、皆當作此。"}]},"嗇":{"expl":"愛瀒也。从來从㐭。來者，㐭而藏之。故田夫謂之嗇夫。凡嗇之屬皆从嗇。","rad":"嗇","fq":"所力切","vol":"05","py":"sè","duan":[{"e":"愛濇也。","n":"嗇濇㬪韵。廣韵引作歰。歰與濇皆不滑也。大雅云。好是家嗇。力民代食。箋云。但好任用是居家之吝嗇、於聚斂作力之人。令代賢者處位食祿。又云家嗇維寶。代食維好。箋云。言王不尙賢。但貴吝嗇之人與愛代食者而巳。老子曰。治人事天莫若嗇。詩序云。其君儉嗇褊急。"}]},"蒻":{"expl":"蒲子。可以爲平席。从艸弱聲。","rad":"艸","fq":"而灼切","vol":"01","py":"ruò","duan":[{"e":"蒲子。","n":"句。"}]},"牆":{"expl":"垣蔽也。从嗇爿聲。","rad":"嗇","fq":"才良切","vol":"05","py":"qiánɡ","duan":[{"e":"垣蔽也。","n":"土部曰。垣、牆也。左傳曰。人之有牆。以蔽惡也。故曰垣蔽。釋宫曰。牆謂之墉。釋名曰。牆、障也。"}]},"來":{"expl":"周所受瑞麥來麰。一來二縫，象芒朿之形。天所來也，故爲行來之來。《詩》曰：“詒我來麰。”凡來之屬皆从來。","rad":"來","fq":"洛哀切","vol":"05","py":"lái","duan":[{"e":"周所受瑞麥來麰也。","n":"也字今補。詩正義此句作周受來牟也五字。周頌。詒我來麰。箋云。武王渡孟津。白魚躍入王舟。出涘以燎。後五日。火流爲烏。五至。以榖俱來。此謂遺我來牟。書說以榖俱來。云榖紀后稷之德。按鄭箋見尙書大誓、尙書旋機鈐合符后。詩云來牟、書云榖。其實一也。下文云。來麰、麥也。此云瑞麥來麰。然則來麰者、以二字爲名。毛詩傳曰。牟、麥也。當是本作來牟、麥也。爲許麰下所本。後人刪來字耳。古無謂來小麥、麰大麥者。至廣雅乃云麳小麥、𪍓大麥。非許說也。劉向傳作釐麰。文𨕖典引注引韓詩內傳。貽我嘉𪍓。薛君曰。𪍓、大麥也。與趙岐孟子注同。然韓傳未嘗云來小麥。"}]},"𥏳":{"expl":"《詩》曰：“不𥏳不來。”从來矣聲。","rad":"來","fq":"牀史切","vol":"05","py":"sì","duan":[{"e":"詩曰。不𥏳不來。","n":"毛詩無此語。釋訓曰。不？、不來也。爾雅多釋詩書。葢江有汜之詩不我以、古作不我？。？者、來之也。不我？者、不來我也。許葢兼偁詩、爾雅。當云詩曰不我？。不？不來也。轉寫譌奪。不可讀耳。？與以不同者。葢許兼偁三家詩也。"}]},"麥":{"expl":"芒穀，秋穜厚薶，故謂之麥。麥，金也。金王而生，火王而死。从來，有穗者；从夊。凡麥之屬皆从麥。","rad":"麥","fq":"莫獲切","vol":"05","py":"mài","duan":[{"e":"芒穀。","n":"有芒朿之穀也。稻亦有芒、不偁芒穀者。麥以周初二麥一鏠箸也。鄭注大誓引禮說曰。武王赤烏、芒穀應。許本禮說。"}]},"麰":{"expl":"來麰，麥也。从麥牟聲。","rad":"麥","fq":"莫浮切","vol":"05","py":"móu","duan":[{"e":"來麰、","n":"逗。"}]},"麧":{"expl":"堅麥也。从麥气聲。","rad":"麥","fq":"乎沒切","vol":"05","py":"hé","duan":[{"e":"堅麥也。","n":"謂麥之堅者也。史、漢皆云。亦食穅覈耳。孟康曰。覈、麥穅中不破者也。晉灼曰。覈音紇。京師人謂麤㞕爲紇頭。按廣韵引漢書食穅麧爲是。孟注、晉音、皆是麧字。後人妄改漢書耳。麧在𣳚韵。覈在麥韵。音不同也。孟注與許說合。"}]},"䵀":{"expl":"小麥㞕之覈。从麥𧴪聲。","rad":"麥","fq":"穌果切","vol":"05","py":"suǒ","duan":[{"e":"小麥㞕之覆。","n":"此晉灼所云京師人謂粗㞕爲麧頭也。上文堅麥、兼大小麥言。此單謂小麥。又堅麥謂㮯者。此謂㞕之而仍有核。覈同果中核之核。今所謂粗麪也。䵀與麧皆謂堅者。故類言之。"}]},"䴾":{"expl":"䃺麥也。从麥𢀩聲。一曰擣也。","rad":"麥","fq":"昨何切","vol":"05","py":"cuó","duan":[{"e":"䃺麥也。","n":"謂以石䃺䃺之。是曰䴾也。"}]},"麩":{"expl":"小麥㞕皮也。从麥夫聲。","rad":"麥","fq":"甫無切","vol":"05","py":"fū","duan":[{"e":"小麥㞕皮也。","n":"麩之言膚也。㞕小麥則其皮可飤嘼。大麥之皮不可食用。故無名。"}]},"麪":{"expl":"麥末也。从麥丏聲。","rad":"麥","fq":"弥箭切","vol":"05","py":"miàn","duan":[{"e":"麥㞕末也。","n":"㞕字依類篇補。末者、㞕之尤細者。齊民要術謂之勃。今人俗語亦云麪勃。勃、取蓬勃之意。非白字也。廣雅。？謂之麪。篇、韵皆云。䴲、麪也。䴲卽末也。末與麪爲雙聲。？與麪爲㬪韵。"}]},"𦸂":{"expl":"蒲蒻之類也。从艸深聲。","rad":"艸","fq":"式箴切","vol":"01","py":"shēn","duan":[{"e":"𦸂蒲、","n":"逗。各本脫𦸂字。今補。"}]},"䵂":{"expl":"麥覈㞕也。十斤爲三斗。从麥啻聲。","rad":"麥","fq":"直隻切","vol":"05","py":"zhí","duan":[{"e":"麥覈㞕也。","n":"上文云麥㞕之覈謂其堅。此云帶覈之㞕謂其䊳碎。䃺之尙未成末。麩與麪未分。是爲䵂。廣韵云。麩䵂。又云。䵂麩。皆謂麩未離析。九章筭術曰。小䵂之率十三半。大䵂之率五十四。麥八斗六升七分升之三得小䵂二斗五升一十四分升之一十三。麥一斗得大䵂一斗二升。李籍音義曰。細曰小䵂。粗曰大䵂。然則九章之小䵂、許所謂麪也。九章之大䵂、許所謂麩及䵀也。"}]},"麷":{"expl":"煑麥也。从麥豐聲。讀若馮。","rad":"麥","fq":"敷戎切","vol":"05","py":"fēnɡ","duan":[{"e":"䰞麥也。","n":"周禮。籩實有麷。大鄭云。𤎅麥曰麷。後鄭云。今河閒以北煑穜麥賣之名曰逢。後鄭謂逢卽麷之遺語也。穜、釋文直龍反。是穜稑之穜。程氏瑤田曰。𤎅煑葢通偁。𤎅、乾煎也。荀卿子。午其軍。取其將。若撥麷。葢麥乾煎則質輕。撥去之甚易。故以爲易之況。今南方蒸稬米爲飯。曝乾煼之。呼爲米蓬。與鄭云逢者合。籩食皆乾物。餌餈亦必以粉坌之。然則煑麥非麥粥也。今人通呼乾煎爲煼。說文。？、𤎅也。"}]},"麮":{"expl":"麥甘鬻也。从麥去聲。","rad":"麥","fq":"丘據切","vol":"05","py":"qù","duan":[{"e":"麥甘鬻也。","n":"荀卿書。冬日則爲之饘粥。夏日則與之瓜麮。釋名曰。煑麥曰麮。麮亦齲也。煑熟亦齲壞也。按麥甘鬻者、以麥爲粥。其味甜也。急就篇云。甘麮？美奏諸君是也。其法當用大麥爲之。或去皮、或粉之。皆可爲粥。其性淸虛。於夏日宜。大麥甘。故今煎飴餹亦用大麥。"}]},"𪍠":{"expl":"餅𥶶也。从麥㱿聲。讀若庫。","rad":"麥","fq":"空谷切","vol":"05","py":"kū","duan":[{"e":"餠𥶶也。","n":"餠𥶶者、堅築之成餠也。方言。？䴭䴳麰䴿麴也。自關而西秦豳之閒曰？。晉之舊都曰䴭。齊右河泲曰䴳。或曰麰。北鄙曰䴽。麴其通語也。"}]},"䴳":{"expl":"餅𥶶也。从麥穴聲。","rad":"麥","fq":"戶八切","vol":"05","py":"huá","duan":[{"e":"餠𥶶也。从麥。穴聲。","n":"戶八切。十五部。"}]},"䴭":{"expl":"餅𥶶也。从麥才聲。","rad":"麥","fq":"昨哉切","vol":"05","py":"cái","duan":[{"e":"餠𥶶也。从麥。才聲。","n":"昨哉切。一部。"}]},"夊":{"expl":"行遲曳夊夊，象人兩脛有所躧也。凡夊之屬皆从夊。","rad":"夊","fq":"楚危切","vol":"05","py":"suī","duan":[{"e":"行遟曳夊夊也。","n":"也字今補。曲禮曰。行不舉足。車輪曳踵。玉藻曰。圈豚行不舉足。齊如流。注云。孔子執圭、足縮縮如有循是也。玉篇曰。詩云雄狐夊夊。今作綏。"}]},"夋":{"expl":"行夋夋也。一曰倨也。从夊允聲。","rad":"夊","fq":"七倫切","vol":"05","py":"qūn","duan":[{"e":"行夋夋也。","n":"夋夋行皃。"}]},"𡕨":{"expl":"行故道也。从夊，畗省聲。","rad":"夊","fq":"房六切","vol":"05","py":"fú","duan":[{"e":"行故道也。","n":"彳部又有復。復行而复廢矣。疑彳部之復乃後增也。"}]},"夌":{"expl":"越也。从夊从𡴆。𡴆，高也。一曰夌约也。","rad":"夊","fq":"力膺切","vol":"05","py":"línɡ","duan":[{"e":"越也。","n":"凡夌越字當作此。今字或作淩、或作凌、而夌廢矣。檀弓。喪事雖遽。不陵節。鄭曰。陵、躐也。躐與越義同。廣韵陵下云。犯也。侮也。侵也。皆夌義之引伸。今字槪作陵矣。"}]},"蓷":{"expl":"萑也。从艸推聲。《詩》曰：“中谷有蓷。”","rad":"艸","fq":"他回切","vol":"01","py":"tuī","duan":[{"e":"隹也。","n":"隹各本作萑。誤。今正。王風。中谷有蓷。釋艸。萑、蓷。毛傳曰。蓷、鵻。葢爾雅本作隹。與毛傳鵻字同。後人輒加卄頭耳。菼亦一名鵻。皆謂其色似夫不也。陸機云。舊說及魏周元明皆云菴閭。韓詩及三蒼、說苑云益母。本艸云。益母、茺蔚也。劉歆云。蓷、臭穢。艸名臭穢卽茺蔚也。按臭茺雙聲。穢蔚曡韵。李、郭注爾雅亦云茺蔚。未知許意何屬。"}]},"致":{"expl":"送詣也。从夊从至。","rad":"夊","fq":"陟利切","vol":"05","py":"zhì","duan":[{"e":"送詣也。","n":"言部曰。詣、候至也。送詣者、送而必至其処也。引伸爲召致之致。又爲精致之致。月令必工致爲上是也。精致、漢人衹作致。糸部緻字、徐鉉所增。凡鄭注俗本乃有緻。"}]},"憂":{"expl":"和之行也。从夊𢚧聲。《詩》曰：“布政憂憂。”","rad":"夊","fq":"於求切","vol":"05","py":"yōu","duan":[{"e":"和之行也。","n":"商頌毛傳曰。優優、和也。廣雅釋訓。憂憂、行也。行之狀多。而憂憂爲龢之行。和、當作龢。憂今字作？。以憂爲𢝊愁字。"}]},"愛":{"expl":"行皃。从夊㤅聲。","rad":"夊","fq":"烏代切","vol":"05","py":"ài","duan":[]},"𡰿":{"expl":"行𡰿𡰿也。从夊，闕。讀若僕。","rad":"夊","fq":"又卜切","vol":"05","py":"pú","duan":[{"e":"行𡕡𡕡也。从夊。闕。讀若僕。","n":"各本篆作𡰿。今依廣韵作𡕡。與小徐注合。此闕謂形。上體作？不知其說也。讀若僕。則知𡕡𡕡、卽今俗語僕僕道途之謂。趙注孟子曰。僕僕、煩猥皃。皮⺊切。三部。"}]},"竷":{"expl":"繇也舞也。樂有章。从章从夅从夊。《詩》曰：“竷竷舞我。”","rad":"夊","fq":"苦感切","vol":"05","py":"kǎn","duan":[{"e":"繇也舞也。","n":"繇當作䚻。䚻、徒歌也。上也字衍。謠舞者、謠且舞也。詩序曰。維淸、奏象舞也。武、奏大武也。禮記文王世子、明堂位、祭統皆云。管象、舞大武。象與大武皆謂周頌武篇。鄭注祭統云。吹管而舞武象之樂也。樂記說武以咏歎淫液、發揚蹈厲竝言。則舞兼歌矣。故其字从章从夊。"}]},"𡕢":{"expl":"瑙蓋也。象皮包覆瑙，下有兩臂，而夊在下。讀若范。","rad":"夊","fq":"亡范切","vol":"05","py":"wǎn","duan":[{"e":"匘葢也。","n":"司馬彪輿服志。乗輿金錽。劉昭引蔡邕獨𣃔曰。金錽者、馬冠也。高廣各五寸。上如五華形。在馬髦前。薛綜注東京賦同。按在馬髦前、則正在馬之匘葢。其字本作金𡕢。或加金旁耳。馬融廣成頌。揚金𡕢而拖玉瓖。字正作𡕢可證。西京賦。璿弁玉纓。薛曰。弁、馬冠叉髦也。徐廣說金錽云。金爲馬叉髦。然則弁也叉髦也、𡕢也、一也。𡕢或誤作㚇。錽或誤作鍐。玉篇又誤作金騣。皆音子公反。非也。匘葢者、人𦥓也。見𦥓部。"}]},"夏":{"expl":"中國之人也。从夊从頁从𦥑。𦥑，兩手；夊，兩足也。","rad":"夊","fq":"胡雅切","vol":"05","py":"xià","duan":[{"e":"中國之人也。","n":"以別於北方狄、東北貉、南方蠻閩、西方羌、西南焦僥、東方夷也。夏、引伸之義爲大也。"}]},"畟":{"expl":"治稼畟畟進也。从田、人，从夊。《詩》曰：“畟畟良耜。”","rad":"夊","fq":"初力切","vol":"05","py":"cè","duan":[{"e":"治稼畟畟進也。","n":"釋訓曰。畟畟、耜也。周頌毛傳曰。畟畟、猶測測也。箋云。農人測測、以利善之耜熾菑是南𠭇也。按畟畟古語。測測今語。毛以今語釋古語。故曰猶。周禮雉氏注曰。耜之者、以耜測凍土剗之。然則畟、測皆進意。"}]},"㚇":{"expl":"斂足也。鵲鵙醜，其飛也㚇。从夊兇聲。","rad":"夊","fq":"子紅切","vol":"05","py":"zōnɡ","duan":[{"e":"斂足也。䧿𩀎醜。其飛也㚇。","n":"二句見釋鳥。今爾雅作翪。許所據異也。"}]},"夒":{"expl":"貪獸也。一曰母猴，似人。从頁，巳、止、夊，其手足。","rad":"夊","fq":"奴刀切","vol":"05","py":"náo","duan":[{"e":"貪獸也。一曰母㺅。","n":"謂夒一名母㺅。犬部曰。㺅、夒也。玃、大母猴也。甶部曰。禺、母㺅屬。爪部曰。爲、母㺅也。單𧦝㺅。絫𧦝母㺅。其實一也。母㺅與沐㺅、獼㺅、一語之轉。母非父母字。詩小雅作猱。毛曰。猱、猨屬。樂記作獶、𣜩之變。鄭曰。獶、彌矦也。"}]},"萑":{"expl":"艸多皃。从艸隹聲。","rad":"艸","fq":"職追切","vol":"01","py":"zhuī","duan":[{"e":"艸多皃。","n":"此從鍇本廁此。鉉本以萑廁蓷篆後。非也。詳蓷下。"}]},"夔":{"expl":"神魖也。如龍，一足，从夊；象有角、手、人面之形。","rad":"夊","fq":"渠追切","vol":"05","py":"kuí","duan":[{"e":"卽魖也。","n":"卽鉉作神。疑神是。鬼部曰。魖、耗鬼也。神魖、謂鬼之神者也。甘泉賦曰。捎夔魖而抶獝狂。東京賦曰。殘夔魖與㒺象。皆夔魖連文可證。國語。木石之怪夔㒺兩。韋注。或云夔一足。越人謂之山繅。或作？。富陽有之。人面㺅身。能言。廣韵曰。山魈出汀州。獨足鬼也。神魖、謂山繅之尤靈異者。若大荒東經云。有獸狀如牛。蒼身而無角。一足。出入水則必風雨。其光如日月。其聲如雷。名曰夔。黃帝得其皮爲𡔷。聲聞五百里。此獸也。非鬼也。薛注二京合而一之。恐非是。"}]},"夎":{"expl":"拜失容也。从夊坐聲。","rad":"夊","fq":"則卧切","vol":"05","py":"cuò","duan":[]},"舛":{"expl":"對臥也。从夊𡕒相背。凡舛之屬皆从舛。","rad":"舛","fq":"昌兖切","vol":"05","py":"chuǎn","duan":[{"e":"對臥也。","n":"謂人與人相對而休也。引伸之足與足相抵而臥亦曰舛。其字亦作僢。王制注釋交趾云浴則同川臥則僢足是也。又引伸之凡足相抵皆曰僢。典瑞兩圭有邸注云僢而同本是也。淮南書及周禮注多用僢字。"}]},"舞":{"expl":"樂也。用足相背，从舛；無聲。","rad":"舛","fq":"文撫切","vol":"05","py":"wǔ","duan":[{"e":"樂也。用足相背。","n":"說从舛之意。"}]},"舝":{"expl":"車軸耑鍵也。兩穿相背，从舛；𥜿省聲。𥜿，古文偰字。","rad":"舛","fq":"胡戛切","vol":"05","py":"xiá","duan":[{"e":"車軸耑鍵也。","n":"金部。鍵、一曰轄也。車部。轄、一曰鍵也。然則許意謂舝轄同也。以鐵豎貫軸頭而制轂如鍵閉然。邶風傳曰。脂是其車。小雅傳曰。閒關、設舝皃。皆謂舝必行而後設也。車軸耑謂之軎。軎、今字作轊。大馭。右祭兩軹。軹、故書作𨊻。杜子春云。𨊻謂㒳轊也。或讀𨊻爲簪筓之筓。按鐵貫軸、如筓貫弁然。軸耑名𨊻者、以鐵名之也。子春易爲軹。非也。"}]},"舜":{"expl":"艸也。楚謂之葍，秦謂之藑。蔓地連華。象形。从舛，舛亦聲。凡䑞之屬皆从䑞。(今隸變作舜。)","rad":"舜","fq":"舒閏切","vol":"05","py":"shùn","duan":[{"e":"䑞艸也。楚謂之葍。秦謂之藑。","n":"艸部曰。藑、茅葍也。一名䑞。是一物三名也。"}]},"𤯷":{"expl":"華榮也。从舜生聲。讀若皇。《爾雅》曰：“𤰀，華也。”","rad":"舜","fq":"戶光切","vol":"05","py":"huánɡ","duan":[]},"韋":{"expl":"相背也。从舛囗聲。獸皮之韋，可以束枉戾相韋背，故借以爲皮韋。凡韋之屬皆从韋。","rad":"韋","fq":"宇非切","vol":"05","py":"wéi","duan":[{"e":"相背也。","n":"故从舛。今字違行而韋之本義廢矣。酒誥。薄韋辳父。馬云。韋、違行也。據羣經音辨、則古文尙書當如是。"}]},"韠":{"expl":"韍也。所以蔽前，以韋。下廣二尺，上廣一尺，其頸五寸。一命縕韠，再命赤韠。从韋畢聲。","rad":"韋","fq":"卑吉切","vol":"05","py":"bì","duan":[{"e":"韍也。","n":"巿部曰。韠也。巿、小篆作韍。"}]},"韎":{"expl":"茅蒐𣑱韋也。一入曰韎。从韋末聲。","rad":"韋","fq":"莫佩切","vol":"05","py":"mèi","duan":[{"e":"茅蒐染韋也。","n":"左傳云韎韋。"}]},"茥":{"expl":"缺盆也。从艸圭聲。","rad":"艸","fq":"苦圭切","vol":"01","py":"ɡuī","duan":[{"e":"缺盆也。","n":"見釋艸。郭云覆盆也。實可食。"}]},"韢":{"expl":"櫜紐也。从韋惠聲。一曰盛虜頭橐也。","rad":"韋","fq":"胡計切","vol":"05","py":"suì","duan":[{"e":"櫜紐也。","n":"櫜、車上大橐也。紐、系也。一曰結而可解也。"}]},"韜":{"expl":"劒衣也。从韋舀聲。","rad":"韋","fq":"土刀切","vol":"05","py":"tāo","duan":[{"e":"劒衣也。","n":"少儀曰。劒則啟櫝葢襲之。加夫襓與劒焉。注曰。夫襓、劒衣也。夫或爲煩、皆發聲。按許書無襓字。襓與韜音相近。襓卽韜也。曹憲廣雅。衭襓䘤、劒衣也。䘤音陳律反。按熊氏安生義疏引廣雅。夫襓木劒衣也。木葢本作术。熊認爲艸木字。夫术、曹本乃作衭䘤。知今本廣雅多增益偏旁而不古矣。引伸爲凡包藏之偁。"}]},"韝":{"expl":"射臂決也。从韋冓聲。","rad":"韋","fq":"古矦切","vol":"05","py":"ɡōu","duan":[{"e":"臂衣也。","n":"各本作射臂決也。誤甚。決箸於右手大指。不箸於臂。今依文𨕖荅蘇武書注正。射韝者、詩之拾。禮經之遂。內則之捍也。毛傳曰。拾、遂也。大射注曰。遂、射韝也。以朱韋爲之。箸左臂。所以遂弦也。凡因射箸左臂謂之射韝。非射而㒳臂皆箸之以便於事謂之韝。許不言射韝者。言臂衣則射韝在其中矣。東方朔傳曰。綠幘傅靑韝。韋昭曰。韝形如射韝。以縛左右手。於事便也。崔豹古今注曰。攘衣、厮役之服。取其便於用耳。乗輿進食者服攘衣。按攘衣卽韝也。以繩纕臂謂之絭。以衣斂袖謂之韝。其字或作褠。見後漢書。或作㡚。見南都賦。"}]},"韘":{"expl":"射決也。所以拘弦，以象骨，韋系，著右巨指。从韋枼聲。《詩》曰：“童子佩韘。”","rad":"韋","fq":"失涉切","vol":"05","py":"shè","duan":[{"e":"射決也。所㠯拘弦。","n":"衞風。童子佩韘。毛曰。韘、決也。能射御則帶韘。小雅車攻傳曰。決、所以鉤弦也。鄭注周禮曰。抉、挾矢時所以持弦飾也。注鄉射禮、大射儀云。決猶闓也。以象骨爲之。箸右大巨指以鉤弦闓體。按卽今人之扳指也。經典多言決。少言韘。韘惟見詩。毛公釋爲決。而箋云。韘之言沓。所以彄沓手指。此以禮經之極釋韘也。大射云。朱極三。注云。極猶放也。所以韜指利放弦也。以朱韋爲之。食指將指無名指各一。小指短不用。鄭意以韘極沓三字雙聲。且極用韋爲之。故字从韋。決則用象骨爲之。故不从毛而易其義。許說从毛也。以字从韋論之。鄭爲長矣。內則言佩決。詩言佩韘。葢言一可以包二。"}]},"韣":{"expl":"弓衣也。从韋蜀聲。","rad":"韋","fq":"之欲切","vol":"05","py":"zhú","duan":[{"e":"弓衣也。","n":"月令。帶以弓韣。高誘曰。韣、弓韜也。按革部韇下曰。弓矢韇也。韇葢又在韣之外。容以木爲之。飾以皮耳。故服注左云。冰、櫝丸葢也。如劒衣在劒櫝之內。"}]},"韔":{"expl":"弓衣也。从韋長聲。《詩》曰：“交韔二弓。”","rad":"韋","fq":"丑亮切","vol":"05","py":"chànɡ","duan":[{"e":"弓衣也。","n":"秦風虎韔。毛曰。虎、虎皮也。韔、弓室也。又交韔二弓。毛曰。交韔、交二弓於韔中。鄭風作鬯。毛曰。鬯弓、弢弓。"}]},"䪗":{"expl":"履也。从韋叚聲。","rad":"韋","fq":"乎加切","vol":"05","py":"xiá","duan":[]},"𩏇":{"expl":"履後帖也。从韋段聲。","rad":"韋","fq":"徒玩切","vol":"05","py":"duàn","duan":[{"e":"履後帖也。","n":"帖、帛書署也。引伸爲今俗語帮貼之字。凡履跟必帮貼之。令堅厚。不則易敝。臣瓚曰。躡跟曰跕。按履緊曰跕屣也。跕與帖音同。急就篇。履舄鞜裒䋐緞紃。師古引說文爲注。"}]},"韤":{"expl":"足衣也。从韋蔑聲。","rad":"韋","fq":"望發切","vol":"05","py":"wà","duan":[{"e":"足衣也。","n":"左傳曰。褚師聲子韤而登席。謂燕禮宜跣也。"}]},"䪙":{"expl":"軶裹也。从韋尃聲。","rad":"韋","fq":"匹各切","vol":"05","py":"pò","duan":[{"e":"軶裹也。","n":"軶、轅前也。以皮裹之。"}]},"莙":{"expl":"井藻也。从艸君聲。讀若威。","rad":"艸","fq":"渠殞切","vol":"01","py":"jùn","duan":[{"e":"牛藻也。","n":"見釋艸。按藻之大者曰牛藻。凡艸類之大者多曰牛曰馬。郭云。江東呼馬薻矣。陸機云。藻二種。一種葉如雞蘇。莖大如箸。長四五尺。一種莖大如釵股。葉如蓬。謂之聚藻。扶風人謂之藻。聚爲發聲也。牛藻當是葉如雞蘇者。但析言則有別。統言則皆謂之藻。亦皆謂之莙。顏氏家訓云。莙艸細。細葉蓬茸水中。一節長數寸。細茸如絲。圓繞可愛。東宮舊事所云六色罽䋿者。凡寸𣃔五色絲。橫著線股閒。繞之以象莙艸。用以飾物。卽名爲莙。於時當縛六色罽。作此莙以飾緄帶。張敞因造糸㫄畏耳。據此、則莖如釵股者亦謂之莙也。"}]},"韏":{"expl":"革中辨謂之韏。从韋𢍏聲。","rad":"韋","fq":"九萬切","vol":"05","py":"quàn","duan":[{"e":"革中辨謂之韏。","n":"釋器。革中絕謂之辨。郭注。中𣃔皮也。革中辨謂之韏。注。復平分也。如郭說、則正文當云辨中絕!謂之韏。立文不當如是。今按當云。革辬謂之韏。中乃衍文。衣部襞下云。韏衣也。衣？、古曰韏。亦曰襞積。亦曰緛。然則皮之縐文蹙蹙者曰韏何疑。文部曰。辬、駁文也。許所據爾雅不同郭本。而淺人以郭本易之。"}]},"𩏷":{"expl":"收束也。从韋𥼚聲。讀若酋。","rad":"韋","fq":"即由切","vol":"05","py":"jiū","duan":[{"e":"收束也。","n":"漢律曆志曰。秋、？也。物？斂乃成孰。鄉飮酒義曰。西方者秋。秋之爲言揫也。"}]},"𩏑":{"expl":"井垣也。从韋，取其帀也；倝聲。","rad":"韋","fq":"胡安切","vol":"05","py":"hán","duan":[{"e":"井橋也。","n":"橋各本作垣。今依史記孝武本紀索隱正。井橋見曲禮、莊子、說苑、淮南子。曲禮。奉席如橋衡。注曰。橋、井上挈皋。衡上低昂者。莊子曰。鑿木爲機。後重前輕。挈水若抽。數如泆湯。其名爲橰。橰本又作橋。淮南書。今夫橋直植立而不動。俛仰取制焉。高曰。橋、桔皋上衡也。說苑曰。爲機重其後。輕其前。命曰橋。終日漑韭。百區不倦。橋、陸音義音居廟反。按其義當同撟。舉也。井？見史漢孝武紀、封禪書、郊祀志、枚乗傳、莊子秋水篇。其字多作井榦。司馬彪云。井榦、井闌也。崔譔云。井以四邊爲榦。猶築之有楨榦。晉灼曰。井上四交之榦。常爲汲者所契傷。是諸家皆說井榦爲井闌。按井？爲木架四圍。中其圍橫圜木爲橋。如字毋兩旁木。有軸可轉。中設鹿"}]},"韌":{"expl":"柔而固也。从韋刃聲。","rad":"韋","fq":"而進切","vol":"05","py":"rèn","duan":[]},"弟":{"expl":"韋束之次弟也。从古字之象。凡弟之屬皆从弟。","rad":"弟","fq":"特計切","vol":"05","py":"dì","duan":[{"e":"韋束之次弟也。","n":"以韋束物。如輈五束、衡三束之類。束之不一則有次弟也。引伸之爲凡次弟之弟、爲兄弟之弟、爲豈弟之弟。詩正義引說文有第字。"}]},"𥊽":{"expl":"周人謂兄曰𥊽。从弟从𥄳。","rad":"弟","fq":"古魂切","vol":"05","py":"kūn","duan":[{"e":"周人謂兄曰𥊽。","n":"昆弟字當作此。昆行而𥊽廢矣。釋親。晜、兄也。郭注。今江東通言曰晜。按晜者、𥊽之誤。男子先生爲兄。後生爲弟。此本定偁。謂兄𥊽者、周人語也。詩惟王風有昆字。此周人謂兄之證也。諸經皆言兄。如尙書乃寡兄勖、春秋衞侯之兄縶、周禮父之讎、兄弟之讎、從父兄弟之讎、詩瞻望兄兮皆是。惟禮喪服經傳。大功巳上皆曰昆弟。小功巳下同異姓皆曰兄弟。不相淆亂。葢禮經欲別服之親疏隆殺。遂以周人謂兄者、專系之同姓大功巳上。以爲立言之別也。戴先生曰。兄弟與昆弟在儀禮喪服、爾雅釋親𢧵然有辨。喪服傳曰。何如則可謂之兄弟。傳曰。小功巳下爲兄弟。此傳中引傳相證明也。爾雅曰。母與妻之黨爲兄弟。又曰。婦之黨爲婚兄弟。壻之黨爲姻兄弟。詩小雅。"}]},"夂":{"expl":"从後至也。象人兩脛後有致之者。凡夂之屬皆从夂。讀若黹。","rad":"夂","fq":"陟侈切","vol":"05","py":"zhǐ","duan":[{"e":"從後至也。","n":"至當作致。"}]},"𡕗":{"expl":"相遮要害也。从夂丯聲。南陽新野有𡕗亭。","rad":"夂","fq":"乎蓋切","vol":"05","py":"hài","duan":[{"e":"相遮要害也。","n":"要害猶險隘也。"}]},"夆":{"expl":"啎也。从夂𡴀聲。讀若縫。","rad":"夂","fq":"敷容切","vol":"05","py":"fēnɡ","duan":[{"e":"啎也。","n":"午部曰。啎、逆也。夆訓啎、猶逢迎逆遇遻互相爲訓。釋訓曰。甹夆、掣曳也。掣曳者、啎逆之意。夆、古亦借爲鏠峯字。"}]},"夅":{"expl":"服也。从夂、午，相承不敢竝也。","rad":"夂","fq":"下江切","vol":"05","py":"xiánɡ","duan":[{"e":"服也。从夂㐄。相承不敢竝也。","n":"上从夂。下从反夂。相承不敢竝、夅服之意也。凡降服字當作此。降行而夅廢矣。下江切。九部。"}]},"𦺊":{"expl":"夫蘺也。从艸睆聲。","rad":"艸","fq":"胡官切","vol":"01","py":"huán","duan":[{"e":"夫離也。","n":"見釋艸。？釋艸亦作莞、夫作苻。"}]},"夃":{"expl":"秦以市買多得爲夃。从𠄎从夂，益至也。从乃。《詩》曰：“我夃酌彼金罍。”","rad":"夂","fq":"古乎切","vol":"05","py":"ɡǔ","duan":[{"e":"秦人巿買多得爲夃。","n":"爲當作謂之二字。此秦人語也。方言不載。"}]},"𡕒":{"expl":"跨步也。从反夂。𩰫从此。","rad":"夂","fq":"苦瓦切","vol":"05","py":"kuǎ","duan":[{"e":"跨步也。","n":"跨當作夸。夸步謂大張其㒳服也。"}]},"久":{"expl":"以後灸之，象人兩脛後有距也。《周禮》曰：“久諸牆以觀其橈。”凡久之屬皆从久。","rad":"久","fq":"舉友切","vol":"05","py":"jiǔ","duan":[{"e":"從後灸之也。","n":"也字今補。久灸㬪韵。火部曰。灸、灼也。灼、灸也。灸有迫箸之義。故以灸訓久。士喪禮。鬲幎、用疏布久之。鄭曰。久讀爲灸。謂以葢塞鬲口也。旣夕。苞筲𦉥甒皆木桁久之。鄭曰。久讀爲灸。謂以葢案塞其口。此經二久字、本不必改讀。葢久本義訓從後歫之。引伸之則凡歫塞皆曰久。鄭以久多訓長久。故易爲灸以釋其義。考工記。灸諸牆以眡其橈之均。鄭曰。灸猶柱也。以柱㒳牆之閒。許所偁作久、與禮經用字正同。許葢因經義以推造字之意。因造字之意以推經義。無不合也。相歫則其𠊱必遟。故又引伸爲遟久。遟久之義行而本義廢矣。"}]},"桀":{"expl":"磔也。从舛在木上也。凡桀之屬皆从桀。","rad":"桀","fq":"渠列切","vol":"05","py":"jié","duan":[{"e":"磔也。","n":"裴駰引謚法曰。賊人多殺曰桀。故引伸爲桀黠字。"}]},"磔":{"expl":"辜也。从桀石聲。","rad":"桀","fq":"陟格切","vol":"05","py":"zhé","duan":[{"e":"辜也。","n":"辛部曰。辜、辠也。掌戮。殺王之親者辜之。注。辜之言枯也。謂磔之。鄭與也許合也。大宗伯。以疈辜祭四方百物。大鄭從故書作罷辜。云罷辜、披磔牲以祭。爾雅。祭風曰磔。郭云。今俗當大道中磔狗云以止風。按凡言磔者、開也。張也。刳其𦙄腹而張之。令其乾枯不收。字或作矺。見史記。"}]},"椉":{"expl":"覆也。从入、桀。桀，黠也。軍法曰乘。","rad":"桀","fq":"食陵切","vol":"05","py":"chénɡ","duan":[{"e":"覆也。","n":"加其上曰椉。人乗車、是其一耑也。"}]},"木":{"expl":"冒也。冒地而生。東方之行。从屮，下象其根。凡木之屬皆从木。","rad":"木","fq":"莫卜切","vol":"06","py":"mù","duan":[{"e":"冒也.","n":"以疊韵爲訓。冃部曰。冢{冡}而前也。"}]},"橘":{"expl":"果。出江南。从木矞聲。","rad":"木","fq":"居聿切","vol":"06","py":"jú","duan":[{"e":"橘果。出江南。","n":"禹貢。荊州厥苞橘柚。考工記曰。橘踰淮而北爲枳。屈原賦曰。受命不遷。生南國兮。許言出江南者、卽考工、屈賦所云也。王逸注云。言橘受天命。生於江南。"}]},"橙":{"expl":"橘屬。从木登聲。","rad":"木","fq":"丈庚切","vol":"06","py":"chénɡ","duan":[{"e":"橘屬。","n":"南都賦曰。穰橙鄧橘。蜀都賦劉注曰。蜀有給客橙。"}]},"柚":{"expl":"條也。似橙而酢。从木由聲。《夏書》曰：“厥包橘柚。”","rad":"木","fq":"余救切","vol":"06","py":"yòu","duan":[{"e":"條也。佀橙而酢。","n":"釋木柚條。郭云似橙、實酢。生江南。列子曰。吳楚之國有大木焉。其名爲櫾。碧樹而冬生。實丹而味酸。食其皮汁已憤厥之疾。按今橘橙柚三果。莫大於柚。莫酢於橙汁。而橙皮甘可食。本草經合橘柚爲一條。渾言之也。"}]},"祪":{"expl":"祔、祪，祖也。从示危聲。","rad":"示","fq":"過委切","vol":"01","py":"ɡuǐ","duan":[{"e":"祔祪祖也。","n":"見釋詁。祔謂新廟。祪謂毀廟。皆祖也。說文倂祔字連引之。故次之以祔。"}]},"蒚":{"expl":"夫蘺上也。从艸鬲聲。","rad":"艸","fq":"力的切","vol":"01","py":"lì","duan":[{"e":"夫離上也。","n":"見釋艸。"}]},"樝":{"expl":"果似棃而酢。从木虘聲。","rad":"木","fq":"側加切","vol":"06","py":"zhā","duan":[{"e":"樝果佀棃而酢。","n":"內則柤棃注曰。柤、棃之不臧者。爾雅郭注、山海經郭傳皆云。樝似棃而酢濇。按卽今棃之肉粗味酸者也。張揖注子虛賦云。樝似棃而甘。乃以同類而互易其名耳。陶隱居譏鄭公不識樝。恐誤。"}]},"棃":{"expl":"果名。从木𥝢聲。𥝢，古文利。","rad":"木","fq":"力脂切","vol":"06","py":"lí","duan":[{"e":"棃果也。","n":"各本作果名二字。淺人改也。釋木。棃山樆。謂棃之山生者曰樆也。樆本亦作離。子虛賦。檗離朱楊。裴駰引漢書音義云。離、山棃也。師古注急就篇云。棃一名山樆。非是。"}]},"梬":{"expl":"棗也，似柹。从木甹聲。","rad":"木","fq":"以整切","vol":"06","py":"yǐnɡ","duan":[{"e":"梬棗也。","n":"三字一句。梬棗、果名。非今俗所食棗也。南都賦曰。梬棗若畱。張揖注子虛曰。梬、梬棗也。李善引說文亦云。梬棗似𣐈。於此可以訂𠜂複字者之非矣。"}]},"柿":{"expl":"赤實果。从木市聲。","rad":"木","fq":"鉏里切","vol":"06","py":"shì","duan":[{"e":"赤實果。","n":"言果又言實者、實謂其中也。赤中、與外同色惟𣐈。內則曰。棗栗榛𣐈。"}]},"枏":{"expl":"梅也。从木冄聲。","rad":"木","fq":"汝閻切","vol":"06","py":"nán","duan":[{"e":"梅也。從木。冄聲。","n":"汝閻切。七部。"}]},"梅":{"expl":"枏也。可食。从木每聲。","rad":"木","fq":"莫桮切","vol":"06","py":"méi","duan":[{"e":"枏也。可食。從木。每聲。","n":"莫桮切。古音在一部。按釋木曰。梅、枏也。毛詩秦風、陳風傳皆曰。梅、枏也。與爾雅同。但爾雅、毛傳皆謂楩枏之枏。毛公於召南摽有梅、曹風其子在梅、小雅四月侯栗侯梅、無傳。而秦、陳乃訓爲枏。此以見召南等之梅與秦、陳之梅判然二物。召南之梅今之酸果也。秦陳之梅今之楠樹也。楠樹見於爾雅者也。酸果之梅不見於爾雅者也。樊光釋爾雅曰。荊州曰梅。楊州曰枏。益州曰赤楩。孫炎釋爾雅曰。荊州曰梅。楊州曰枏。陸機疏草木曰。梅樹皮葉似豫樟。皆謂楠樹也。枏亦名梅。後世取梅爲酸果之名。而梅之本義廢矣。郭釋爾雅乃云似杏、實酢。篇、韵襲之。轉謂酸果有枏名。此誤之甚者也。然則許以枏梅二篆廁諸果之閒。又云可食。豈非始誤與。曰此淺人所改竄"}]},"杏":{"expl":"果也。从木，可省聲。","rad":"木","fq":"何梗切","vol":"06","py":"xìnɡ","duan":[{"e":"杏果也。","n":"內則。桃李梅杏。"}]},"柰":{"expl":"果也。从木示聲。","rad":"木","fq":"奴帶切","vol":"06","py":"nài","duan":[{"e":"柰果也。","n":"假借爲柰何字。見尙書左傳。俗作奈。非。"}]},"李":{"expl":"果也。从木子聲。","rad":"木","fq":"良止切","vol":"06","py":"lǐ","duan":[{"e":"李果也。从木。子聲。","n":"良止切。一部。古李理同音通用。故行李與行理竝見。大李與大理不分。"}]},"桃":{"expl":"果也。从木兆聲。","rad":"木","fq":"徒刀切","vol":"06","py":"táo","duan":[{"e":"桃果也。从木。兆聲。","n":"徒刀切。二部。"}]},"苢":{"expl":"芣苢。一名馬舄。其實如李，令人宜子。从艸㠯聲。《周書》所說。","rad":"艸","fq":"羊止切","vol":"01","py":"yǐ","duan":[{"e":"芣苢、","n":"逗。"}]},"㮘":{"expl":"冬桃。从木敄聲。讀若髦。","rad":"木","fq":"莫𠊱切","vol":"06","py":"mào","duan":[{"e":"冬桃。","n":"釋木曰。旄、冬桃。郭云。子冬孰。按作旄者字之假借。二部三部合韵冣近也。釋文曰。字林作㮘。今本譌爲字林作㮘。"}]},"𣓀":{"expl":"果，實如小栗。从木辛聲。《春秋傳》曰：“女摯不過𣓀栗。”","rad":"木","fq":"側詵切","vol":"06","py":"zhēn","duan":[{"e":"𣓀實如小栗。","n":"韵會作木名實如小栗六字。周禮籩人、記曲禮內則、左傳、毛詩字皆作榛。假借字也。榛行而𣓀廢矣。鄭云。如栗而小。與許合。齊民要術引義疏云。榛栗有二種。"}]},"楷":{"expl":"木也。孔子冢蓋樹之者。从木皆聲。","rad":"木","fq":"苦駭切","vol":"06","py":"jiē","duan":[{"e":"楷木也。孔子冢葢樹之者。","n":"皇覽云。冢塋中樹以百數。皆異種。傳言弟子各持其方樹來穜之。按楷亦方樹之一也。儒行曰。今世行之。後世以爲楷。楷、法式也。楷之言稽。我稽古、而後世又於此焉稽也。"}]},"梫":{"expl":"桂也。从木，㑴省聲。","rad":"木","fq":"七荏切","vol":"06","py":"qǐn","duan":[{"e":"桂也。","n":"釋木。梫、木桂。郭曰。今南人呼桂厚皮者爲木桂。葉似枇杷而大。按南方草木狀云。桂有三種。葉似枇杷者爲牡桂。牡木音同。許言梫桂也者。梫爲桂之一。而桂不止於梫也。蜀都賦。其樹則有木蘭梫桂。劉逵曰。梫桂、木桂也。"}]},"桂":{"expl":"江南木，百藥之長。从木圭聲。","rad":"木","fq":"古惠切","vol":"06","py":"ɡuì","duan":[{"e":"江南木。","n":"本艸曰。桂生桂陽。牡桂生南海山谷。箘桂生交趾、桂林山谷。"}]},"棠":{"expl":"牡曰棠，牝曰杜。从木尚聲。","rad":"木","fq":"徒郎切","vol":"06","py":"tánɡ","duan":[{"e":"牡曰棠。牝曰杜。","n":"艸木有牡者、謂不實者也。小雅云。有杕之杜。有皖其實。此牝者曰杜之證也。陸機詩疏曰。赤棠與白棠同耳。但子有赤白美惡。子白色爲白棠、甘棠。少酢滑美。赤棠子澀而酢無味。俗語云。澀如杜是也。依陸說是棠杜皆有子。然種類甚多。今之海棠皆華而不實。葢所謂牡者曰棠也。"}]},"杜":{"expl":"甘棠也。从木土聲。","rad":"木","fq":"徒古切","vol":"06","py":"dù","duan":[{"e":"甘棠也。","n":"召南。蔽芾甘棠。毛曰。甘棠、杜也。釋木曰。杜甘棠。本無不合。棠不實。杜實而可食。則謂之甘棠。凡實者皆得謂之杜。則皆得謂之甘棠也。牡棠牝杜、析言之也。杜得偁甘棠、互言之也。釋木又曰。杜、赤棠。白者棠。魏風傳用之。此以其木色之異異其名。與杜甘棠說異。卽與分牡牝說異。爲許所不取。戴先生曰。爾雅謂杜甘曰棠。毛公失其句讀。葢依陸璣疏白棠卽甘棠、子美。赤棠卽杜、子澀。爲此說耳。非許意。亦非爾雅意也。先生又曰。棃山樆。謂棃山生曰樆。榆白枌。謂榆之白者曰枌。今按毛傳云。枌白榆也。誠當於白爲讀。漢書音義云。離山棃也。是爾雅當同意義乙其字矣。"}]},"槢":{"expl":"木也。从木習聲。","rad":"木","fq":"似入切","vol":"06","py":"xí","duan":[{"e":"槢木也。","n":"莊子、淮南有椄槢字。皆謂械楔。不爲木名。"}]},"樿":{"expl":"木也。可以爲櫛。从木單聲。","rad":"木","fq":"旨善切","vol":"06","py":"zhǎn","duan":[{"e":"樿木也。可㠯爲櫛。","n":"玉藻曰。櫛用樿櫛。髮晞用象櫛。禮器曰。樿勺。鄭曰。樿木白理。中山經曰。風雨之山。其木栘棷樿。郭曰。樿木白理。中櫛。"}]},"椲":{"expl":"木也。可屈爲杅者。从木韋聲。","rad":"木","fq":"于鬼切","vol":"06","py":"wěi","duan":[{"e":"椲木也。可屈爲杅者。","n":"屈當作詘。詰詘、紆曲也。系部云。紆詘也是也。杅當作盂。盂、飲器也。玉篇曰。椲木皮如韋。可屈以爲盂。"}]},"蕁":{"expl":"䒞藩也。从艸尋聲。","rad":"艸","fq":"徒含切","vol":"01","py":"tán","duan":[{"e":"䒞蕃也。","n":"今本篆文無彡。誤。䒞當是本作冘。俗加艸。本艸作沈直林切燔。說爾雅者謂卽今之知母。"}]},"楢":{"expl":"柔木也。工官以爲耎輪。从木酋聲。讀若糗。","rad":"木","fq":"以周切","vol":"06","py":"yóu","duan":[{"e":"柔木也。工官㠯爲耎輪。","n":"大鄭引鄹子書。秋取柞楢之火。工官若周之輪人、漢之考工室也。耎輪者安車之輪也。郭注山海經云。楢、剛木。中車材。剛木卽柔木。葢此木堅韌。故柔剛異偁而同實耳。"}]},"桏":{"expl":"级椐木也。从木邛聲。","rad":"木","fq":"渠容切","vol":"06","py":"qiónɡ","duan":[{"e":"椶椐木也。","n":"集韵作椶。類篇作𣞍。是宋初本不同也。宋刻鉉本及李氏五音韵譜作𣞍。毛刻初印同。斧季剜版作椶。按𣞍字無攷。椶椐木、合二木爲名。未知何木也。釋木曰。楥柜桏。郭注云。未詳。或曰桏當爲柳。柜柳似柳。皮可以煑作飲。郭易桏爲柳。而後釋柜柳。則篇、韵以柜柳釋桏。非也。說文葢取諸爾雅。椶與楥形似。椐與柜聲同。椶疑楥之誤。"}]},"棆":{"expl":"毋杶也。从木侖聲。讀若《易》卦屯。","rad":"木","fq":"陟倫切","vol":"06","py":"lún","duan":[{"e":"母杶也。","n":"按母杶當作毋疵。皆字之誤也。釋木。榆、無疵。古毋無通用。故許作毋。玉篇。棆、木名也。𣐑、無𣐑木也。二字爲伍。葢謂一物也。廣韵云。無𣐑木一名棆。是也。楊雄蜀都賦說木有𣐑。郭云。棆、楩屬。似豫章。"}]},"楈":{"expl":"木也。从木胥聲。讀若芟刈之芟。","rad":"木","fq":"私閭切","vol":"06","py":"xū","duan":[{"e":"楈木也。","n":"上林賦有胥邪。南都賦作楈枒。郭璞曰。胥邪似幷閭。皮可作索。按未審卽許所云楈木否也。"}]},"柍":{"expl":"梅也。从木央聲。一曰江南橦材，其實謂之柍。","rad":"木","fq":"於京切","vol":"06","py":"yǎnɡ","duan":[{"e":"柍梅也。","n":"柍梅合二字成木名。今各本𠜂去柍字。是柍卽枏矣。釋木。時英梅。齊民要術引郭注云。英梅未聞。今本注云。雀梅。殆非郭語。南都賦曰。柍柘檍檀。與櫻梅山𣐈等各爲一條。柍梅非今之梅類明矣。"}]},"楑":{"expl":"木也。从木癸聲。又，度也。","rad":"木","fq":"求癸切","vol":"06","py":"kuí","duan":[{"e":"楑木也。","n":"未詳。"}]},"𣓌":{"expl":"木也。从木咎聲。讀若皓。","rad":"木","fq":"古老切","vol":"06","py":"ɡǎo","duan":[{"e":"𣓌木也。","n":"六書故以烏臼當之。未知是否。"}]},"椆":{"expl":"木也。从木周聲。讀若丩。","rad":"木","fq":"職畱切","vol":"06","py":"chóu","duan":[{"e":"椆木也。","n":"中山經。虎首之山。多苴椆椐。郭曰。椆未詳也。音彫。"}]},"樕":{"expl":"樸樕，木。从木欶聲。","rad":"木","fq":"桑谷切","vol":"06","py":"sù","duan":[{"e":"樸樕、小木也。","n":"樸當作㯷。㯷樸正俗字也。各本無小字。今依五音韵譜、韵會、集韵類篇補。召南。林有樸樕。毛曰。樸樕、小木也。釋木云。樕樸心。樕樸卽詩之樸樕。俗書立心多同小。又艸書心似小。毛傳、說文當本作心木。譌爲小木耳。詩正義云。某氏曰樸樕斛樕也。有心能溼。江河閒以作柱。孫炎曰。樸樕一名心。據此及許立文之次弟。知樸樕乃木名。非凡小木之偁也。斛俗作槲。槲樕櫟之類。樸爾雅音義作㯷。廣韵曰。杺、木名。其心黃。杺卽爾雅心字。"}]},"㰘":{"expl":"木也。从木彞聲。","rad":"木","fq":"羊皮切","vol":"06","py":"yí","duan":[{"e":"㰘木也。","n":"未祥。"}]},"𦿓":{"expl":"艸也。从艸毄聲。","rad":"艸","fq":"古歴切","vol":"01","py":"jī","duan":[{"e":"艸也。从艸。毄聲。","n":"古歷切。十六部。"}]},"梣":{"expl":"青皮木。从木岑聲。","rad":"木","fq":"子林切","vol":"06","py":"cén","duan":[{"e":"靑皮木。","n":"淮南書曰。夫梣木色靑瘉翳。而蠃蝸瘉睆。此皆治目之藥也。高曰。梣木、苦歷木名也生於山。剝其皮以水浸之。正靑。用洗眼。瘉人目中膚翳。正文各本譌誤。今考定如是。按本艸經謂之秦皮。以一名岑皮而聲誤作秦耳。其木一名石檀。陶隱居云是樊槻木。槻音規。集韵云。江南樊雞木。其皮人水綠色。可解膠益墨。樊雞卽樊槻也。"}]},"棳":{"expl":"木也。从木叕聲。益州有棳縣。","rad":"木","fq":"職說切","vol":"06","py":"zhuō","duan":[{"e":"棳木也。","n":"未詳。俗以爲梁上楹之字。"}]},"𣘫":{"expl":"木也。从木，號省聲。","rad":"木","fq":"乎刀切","vol":"06","py":"háo","duan":[{"e":"𣘫木也。","n":"未詳。"}]},"棪":{"expl":"遬其也。从木炎聲。讀若三年導服之導。","rad":"木","fq":"以冉切","vol":"06","py":"yǎn","duan":[{"e":"遬其也。","n":"釋木。棪遬其。郭曰。棪實如柰。可食。南山經傳曰。棪別名速。其子似柰而赤。可食。按遬、籒文速字也。今爾雅作㯈。爲俗字。"}]},"𣛹":{"expl":"木也。从木遄聲。","rad":"木","fq":"市緣切","vol":"06","py":"chuán","duan":[{"e":"𣛹木也。","n":"未詳。"}]},"椋":{"expl":"卽來也。从木京聲。","rad":"木","fq":"呂張切","vol":"06","py":"liánɡ","duan":[{"e":"卽來也。","n":"釋木曰。椋卽棶。釋文曰。棶埤蒼、字林作來。本說文也。絫𧦝曰卽來。單𧦝曰來。唐本艸謂之椋子木。"}]},"檍":{"expl":"杶也。从木意聲。","rad":"木","fq":"於力切","vol":"06","py":"yì","duan":[]},"𣙿":{"expl":"木也。从木費聲。","rad":"木","fq":"房未切","vol":"06","py":"fèi","duan":[{"e":"𣙿木也。","n":"未詳。"}]},"㯉":{"expl":"木也。从木虖聲。","rad":"木","fq":"丑居切","vol":"06","py":"chū","duan":[{"e":"㯉木也。","n":"釋木。檴落。郭云。可以爲杯器素。按小雅薪是穫薪。箋云。穫落、木名也。陸云。依鄭則字宜木旁。㯉檴古今字也。司馬上林賦字作華。師古曰。華卽今之樺。皮貼弓者。莊子華冠、亦謂樺皮爲冠也。樺者俗字也。"}]},"楀":{"expl":"木也。从木禹聲。","rad":"木","fq":"王矩切","vol":"06","py":"yǔ","duan":[{"e":"楀木也。","n":"未詳。小雅。楀維師氏。箋云。楀、氏也。集韵、類篇皆云。楀、木名。𢯺、姓。引詩𢯺維師氏。唐石經初刻从手。後改从木。按篇、韵皆無𢯺字。釋文、五經文字、急就篇顔注皆從木。"}]},"蓲":{"expl":"艸也。从艸區聲。","rad":"艸","fq":"去鳩切","vol":"01","py":"qiū","duan":[{"e":"烏蓲、","n":"逗二字依爾雅音義補。"}]},"蘽":{"expl":"木也。从木藟聲。","rad":"木","fq":"力軌切","vol":"06","py":"lěi","duan":[{"e":"蘽木也。","n":"釋木。諸盧、山櫐。郭曰。今江東呼櫐爲藤。虎櫐、今虎豆。纏蔓林樹而生。中山經。畢山、其上多櫐。（依齊民要術藝文類聚）郭曰。今虎豆、貍豆之屬。櫐一名縢。音耒。按櫐者蘽之省。其物在艸木之閒。近於艸者則爲艸部之藟。詩之藟也。近於木者則爲木部之蘽。釋木之山櫐、虎櫐也。縢藤古今字。謂之縢者、可以爲緘縢也。蘽之屬不一。統名之曰蘽木。"}]},"桋":{"expl":"赤栜也。从木夷聲。《詩》曰：“隰有杞桋。”","rad":"木","fq":"以脂切","vol":"06","py":"yí","duan":[{"e":"赤栜也。","n":"釋木曰。桋、赤栜。白者栜。毛傳曰。桋、赤栜也。郭云。赤栜樹葉細而岐銳。白栜葉圓而岐、爲大木。按栜、釋文音山厄反。許書無栜字。葢古只作朿也。"}]},"栟":{"expl":"栟櫚也。从木并聲。","rad":"木","fq":"府盈切","vol":"06","py":"bīnɡ","duan":[{"e":"栟櫚、","n":"逗。"}]},"椶":{"expl":"栟櫚也。可作萆。从木㚇聲。","rad":"木","fq":"子紅切","vol":"06","py":"zōnɡ","duan":[{"e":"栟櫚也。","n":"互訓也。蜀都賦椶枒楔樅。四木名也。"}]},"檟":{"expl":"楸也。从木賈聲。《春秋傳》曰：“樹六檟於蒲圃。”","rad":"木","fq":"古雅切","vol":"06","py":"jiǎ","duan":[{"e":"楸也。","n":"釋木。槐小葉曰榎。郭云。槐當爲楸。楸細葉者爲榎。又大而皵、楸。小而皵、榎。郭云。老乃皮粗皵爲楸。小而皮粗皵者爲榎。又槄、山榎。郭云。今之山楸。按榎者檟之或字。左傳、孟子作檟。爾雅別言之。許渾言之。"}]},"椅":{"expl":"梓也。从木奇聲。","rad":"木","fq":"於离切","vol":"06","py":"yī","duan":[{"e":"梓也。","n":"釋木曰。椅、梓。渾言之也。衞風傳曰。椅、梓屬。析言之也。椅與梓有別。故詩言椅桐梓漆。其分別甚微也。故爾雅、說文渾言之。"}]},"梓":{"expl":"楸也。从木，宰省聲。","rad":"木","fq":"卽里切","vol":"06","py":"zǐ","duan":[{"e":"楸也。從木。宰省聲。","n":"卽裏切。一部。按許知宰省聲而非辛聲者、於或字知之也。或字、葢古文遺與。"}]},"楸":{"expl":"梓也。从木秋聲。","rad":"木","fq":"七由切","vol":"06","py":"qiū","duan":[{"e":"梓也。","n":"左傳、史漢以萩爲楸。如秦周伐雍門之萩、淮北常山巴南河濟之閒千樹萩、是也。左傳萩一作秋。"}]},"𣚍":{"expl":"梓屬。大者可爲棺椁，小者可爲弓材。从木𠶷聲。","rad":"木","fq":"於力切","vol":"06","py":"yì","duan":[{"e":"梓屬。大者可爲棺椁。小者可爲弓材。","n":"按𣚍檍古今字。心部𢡃、今作億。艸部𦺳、今作薏。水部𣽢、今作澺。人部𠐥、今作億。然則經典檍字卽說文之𣚍、何疑。考工記。取榦之道七。柘爲上。檍次之。此卽所謂小者可爲弓材也。唐風。隰有杻。釋木、毛傳皆曰。杻、檍也。許無杻字。豈其字正作紐、俗作杻與。大鄭云。檍讀如億萬之億。陸機云。今官園種之。正名曰萬嵗。取名於億萬。𠔏汲山下人或謂牛筋。或謂之檍。材可爲弓弩榦也。今各本椋𣙿二篆之閒有檍篆。云杶也。從木意聲。葢淺人謂不當闕檍字而增之。本云檍杻也。後又譌杻爲杶。不可通。考韵會云。說文作𣚍。今文作檍。則黃氏所據鍇本未誤也。今𠜂檍篆。"}]},"柀":{"expl":"檆也。从木皮聲。一曰折也。","rad":"木","fq":"甫委切","vol":"06","py":"bǐ","duan":[{"e":"黏也。","n":"黏各本作{木+黏[左右]}｛檆｝。徐鉉因增一{木+黏[左右]}篆。非也。今𠜂{木+黏[左右]}篆。依爾雅正{木+黏[左右]}爲黏。釋木曰。柀、黏。上音彼。下音所咸反。卽今之杉木也。黏與杉爲正俗字。郭云。黏生江南。可以爲船及棺。羅氏願爾雅翼曰。柀似杉而異。杉以材偁。柀又有美實。而材尤文采。其樹大連抱。高數仞。葉似杉。木如柏。作松理。肌理細輭。堪爲器用。古所謂文木也。其實有皮殼。大小如棗而短。去皮殼。可生食。本艸有彼子。卽柀子也。引蘇恭說。本艸誤入蟲部。陶隱居木部出之。按依羅氏說則柀與杉有別。今人恆用者皆杉。非柀也。爾雅、說文渾言之耳。南方艸木狀曰。杉一名柀黏。"}]},"䓢":{"expl":"艸也。从艸固聲。","rad":"艸","fq":"古慕切","vol":"01","py":"ɡù","duan":[{"e":"艸也。从艸。固聲。","n":"古慕切。五部。"}]},"檆":{"expl":"木也。从木煔聲。","rad":"木","fq":"所銜切","vol":"06","py":"shān","duan":[]},"榛":{"expl":"木也。从木秦聲。一曰菆也。","rad":"木","fq":"側詵切","vol":"06","py":"zhēn","duan":[{"e":"榛木也。","n":"邶風山有榛傳曰。榛、木也。小雅。營營靑蠅。止于榛。傳曰。榛所以爲藩也。衞風箋曰。樹榛栗椅桐梓漆六木於宮。可伐以爲琴瑟。"}]},"𣐊":{"expl":"山㯉也。从木尻聲。","rad":"木","fq":"苦浩切","vol":"06","py":"kǎo","duan":[{"e":"山樗也。","n":"樗舊作㯉。今改。釋木、唐風傳皆曰。栲、山樗。𣐊栲古今字。許所據作𣐊也。陸機云。山樗與下田樗無異。葉似差狹耳。方俗無名此爲栲者。今所云栲者。葉如櫟木。皮厚數寸。可爲車軸。或謂之栲。郭云。栲似樗。色小白。生山中。因名云。亦類漆樹。俗語曰。櫄樗栲漆。相似如一。按二說似許爲長。"}]},"杶":{"expl":"木也。从木屯聲。《夏書》曰：“杶榦栝柏。”","rad":"木","fq":"敕倫切","vol":"06","py":"chūn","duan":[{"e":"杶木也。","n":"禹貢。杶榦桰柏。釋文。杶本又作櫄。山海經。成侯之山。其上多櫄木。郭曰。似樗樹。材中車轅。吳人呼櫄音輴車。"}]},"橁":{"expl":"杶也。从木筍聲。","rad":"木","fq":"相倫切","vol":"06","py":"chūn","duan":[{"e":"杶也。","n":"此杶木別名。非卽杶字也。左傳。孟莊子斬雍門之橁。以爲公琴。"}]},"桵":{"expl":"白桵，棫。从木妥聲。","rad":"木","fq":"儒隹切","vol":"06","py":"ruí","duan":[{"e":"白桵、","n":"逗。"}]},"棫":{"expl":"白桵也。从木或聲。","rad":"木","fq":"于逼切","vol":"06","py":"yù","duan":[{"e":"白桵也。從木。或聲。","n":"于逼切。一部。"}]},"㮩":{"expl":"木也。从木息聲。","rad":"木","fq":"相卽切","vol":"06","py":"xī","duan":[{"e":"㮩木也。","n":"未詳。玉篇不載。"}]},"椐":{"expl":"樻也。从木居聲。","rad":"木","fq":"九魚切","vol":"06","py":"jū","duan":[{"e":"樻也。","n":"大雅。其檉其椐。釋木、毛傳皆云。椐、樻也。陸機云。節中腫。似扶老卽今𤫊壽是也。今人以爲馬鞭及杖。郭云。腫節。可以爲杖。按杖以木者曰𤫊壽。亦曰扶老。漢書孔光傳。賜𤫊壽杖。孟康曰。扶老杖也。服虔曰。𤫊壽、木名。郭注山海經亦云。𤫊壽、木名。似竹。有枝節。常璩云。朐忍縣有𤫊壽木。劉逵云。𤫊壽木出涪陵。楊雄作𤫊節銘。皆是也。以竹者名扶老杖。中山經其上多扶竹。郭云。卭竹也。高節實中。中杖。名之扶老竹。漢書之卭竹杖。王逸少以卭竹杖分贈老友。皆是也。𤫊壽木與卭竹皆以節勝。陸氏云。椐卽𤫊壽。然椐與𤫊壽俱見山海經。郭不云一物。若陶潛云。策扶老以流憩。則又未識其爲椐與𤫊壽也。"}]},"樻":{"expl":"椐也。从木貴聲。","rad":"木","fq":"求位切","vol":"06","py":"kuì","duan":[{"e":"椐也。從木。𧷈聲。","n":"求位切。十五部。詩音義曰。去塊反。何音匱。"}]},"𦾮":{"expl":"艸也。从艸榦聲。","rad":"艸","fq":"古案切","vol":"01","py":"ɡàn","duan":[{"e":"艸也。从艸。榦聲。","n":"古案切。十四部。"}]},"栩":{"expl":"柔也。从木羽聲。其皁，一曰様。","rad":"木","fq":"況羽切","vol":"06","py":"xǔ","duan":[{"e":"栩𣏗也。","n":"見唐風毛傳。陸機曰。栩、今柞櫟也。徐州人謂櫟爲杼。或謂之爲栩。按毛傳、說文皆栩𣏗樣爲一木。櫟下但云木也。不云卽栩也。然則陸機專據徐州語言合之耳。"}]},"𣏗":{"expl":"栩也。从木予聲。讀若杼。","rad":"木","fq":"直呂切","vol":"06","py":"zhù","duan":[{"e":"栩也。","n":"莊子。狙公賦芧。司馬云。芧、橡子也。芧卽𣏗字。橡卽樣字。𣏗本樹名。因用爲實名也。"}]},"様":{"expl":"栩實。从木羕聲。","rad":"木","fq":"徐兩切","vol":"06","py":"xiànɡ","duan":[{"e":"栩實也。","n":"樣橡正俗字。爾雅舊注曰。𣏗實爲橡子。以橡殼爲𣏗斗者以剜剜似斗故也。橡子、儉嵗可食以爲飯。豐年牧豬。飤之可以致肥也。見齊民要術。"}]},"杙":{"expl":"劉，劉杙。从木弋聲。","rad":"木","fq":"与職切","vol":"06","py":"yì","duan":[{"e":"劉劉、杙","n":"見釋木。當讀劉劉爲句。郭云。劉子生山中。實如棃。酢甜核堅。未知許意然否也。今人以杙爲橜弋字。乃以橜弋爲隿射字。"}]},"枇":{"expl":"枇杷，木也。从木比聲。","rad":"木","fq":"房脂切","vol":"06","py":"pí","duan":[{"e":"枇杷木也。","n":"四字句。"}]},"桔":{"expl":"桔梗，藥名。从木吉聲。一曰直木。","rad":"木","fq":"古㞕切","vol":"06","py":"jié","duan":[{"e":"桔梗、","n":"逗。"}]},"柞":{"expl":"木也。从木乍聲。","rad":"木","fq":"在各切","vol":"06","py":"zuò","duan":[{"e":"柞木也。","n":"詩有單言柞者。如維柞之枝、析其柞薪是也。有柞棫連言者。如皇矣、旱麓、緜是也。陸機引三蒼。棫卽柞也。與許不合。假令許謂棫卽柞、則二篆當聯屬之。且詩不當或單言棫。或單言柞。或柞棫竝言也。鄭詩箋云。柞、櫟也。孫炎爾雅注。櫟實、橡也。齊民要術援爾雅注合柞栩櫟爲一。亦皆非許意。"}]},"㭔":{"expl":"木。出橐山。从木乎聲。","rad":"木","fq":"他乎切","vol":"06","py":"lú","duan":[{"e":"㭔木。出橐山。","n":"中山經曰。傳山西五十里曰橐山。其木多樗。多𣖾木。按樗者㭔之誤。許所引山海經樜字今作柘、涻字今作涔、劦字今作䬅。其不同如此。廣韵十一模曰。黃㭔木可染。十姥曰。㭔、木名。可染繒。按周禮注曰。染艸、茅蒐橐盧豕首紫茢之屬。橐盧豈卽黃㭔與。抑字音相近、而艸木異類也。玉篇乃佚㭔字。"}]},"榗":{"expl":"木也。从木晉聲。書曰：竹箭如榗。","rad":"木","fq":"子善切","vol":"06","py":"jiàn","duan":[{"e":"榗木也。","n":"未詳。尙書大傳曰。南山之南有木名橋。高高然而上。父道也。南山之陰有木名梓。晉晉然而俯。子道也。高與橋、晉與梓、皆疊韵。梓字當是榗字。梓從宰省聲。不與晉同韵也。"}]},"𣔾":{"expl":"羅也。从木㒸聲。《詩》曰：“隰有樹𣔾。”","rad":"木","fq":"徐醉切","vol":"06","py":"suì","duan":[{"e":"𣔾、羅也。","n":"釋木。檖蘿。秦風毛傳曰。檖、赤羅也。陸機、郭璞皆云。今之楊檖也。實似棃而小。酢。可食。按蘿者羅之誤。"}]},"藷":{"expl":"藷蔗也。从艸諸聲。","rad":"艸","fq":"章魚切","vol":"01","py":"zhū","duan":[{"e":"藷蔗也。","n":"三字句。或作諸蔗、或都蔗。藷蔗二字曡韵也。或作竿蔗、或干蔗。象其形也。或作甘蔗。謂其味也。或作邯？。服䖍通俗文曰。荆州竿蔗。"}]},"椵":{"expl":"木。可作牀几。从木叚聲。讀若賈。","rad":"木","fq":"古雅切","vol":"06","py":"jiǎ","duan":[{"e":"椵木。可作牀几。","n":"牀鍇本作伏。疑誤。釋木曰。櫠椵。本艸陶隠居說人參曰。高麗人作人參讚曰。三椏五葉。背陽向陰。欲來求我。椵樹相尋。椵樹、葉似桐。甚大。陰廣。圖經亦言人參春生苗。多於深山背陰。近椵漆下潤涇處。是則椵爲大木。故材可牀几。郭云子大如盂者。未知是不也。"}]},"橞":{"expl":"木也。从木惠聲。","rad":"木","fq":"胡計切","vol":"06","py":"huì","duan":[{"e":"橞木也。","n":"未詳。"}]},"楛":{"expl":"木也。从木苦聲。《詩》曰：“榛楛濟濟。”","rad":"木","fq":"侯古切","vol":"06","py":"hù","duan":[{"e":"楛木也。","n":"大雅。榛楛濟濟。陸機曰。楛、其形似荊而赤。葉似蓍。上黨人蔑以爲筥箱。又屈以爲釵。按禹貢惟箘簬楛。楛不與上文杶榦桰相爲伍。而與箘簬爲伍。楛之用葢與箘簬同也。"}]},"櫅":{"expl":"木也。可以爲大車軸。从木齊聲。","rad":"木","fq":"祖雞切","vol":"06","py":"jī","duan":[{"e":"櫅木也。","n":"釋木曰。櫅白棗。按許不云白棗。與爾雅異。葢爾雅本作齊白棗。今人所食棗、白乃執是也。櫅乃別一木。廣韵曰。櫅榆堪作車轂。正與許合。轂軸異耳。楊雄蜀都賦。枇櫅㭈楬。章樵注云。櫅、榆屬。"}]},"㭁":{"expl":"木也。从木乃聲。讀若仍。","rad":"木","fq":"如乘切","vol":"06","py":"rénɡ","duan":[{"e":"㭁木也。","n":"未詳。"}]},"㰋":{"expl":"木也。从木𩔤聲。","rad":"木","fq":"符眞切","vol":"06","py":"pín","duan":[{"e":"㰋木也。","n":"未詳。疑卽仁頻也。上林賦有仁頻。孟康曰。仁頻、椶也。李善曰。仙藥錄云。㯽榔一名椶。然則仁頻卽㯽榔也。"}]},"樲":{"expl":"酸棗也。从木貳聲。","rad":"木","fq":"而至切","vol":"06","py":"èr","duan":[{"e":"酸棗也。","n":"釋木曰。樲、酸棗。孟子曰。舍其梧檟。養其樲棗。趙曰。樲棗、小棗。所謂酸棗也。按孟子本作樲棗。宋刻爾雅單行疏及玉篇、唐本艸、又本艸圖經皆可證。今本改作樲棘。非是。樲之言副貳也。爲棗之副貳。故曰樲棗。本艸經曰。酸棗味酸平。主心腹寒熱、邪結氣聚、四肢酸疼、溫痹、煩心不得眠。諸家皆云。似棗而味酸。"}]},"㯷":{"expl":"棗也。从木僕聲。","rad":"木","fq":"博木切","vol":"06","py":"pú","duan":[{"e":"㯷棗也。","n":"釋木言棗之名十有一。繼之言櫬梧。繼之言樸枹者。是今爾雅樸不謂棗也。疑許所據有不同。故云尒。宼宗奭曰。御棗甘美輕脃。今人所謂撲落酥者是。㯷棗豈卽御棗歟。㯷樸古今字。大雅毛傳曰。樸、枹木也。方言曰。㯷、盡也。南楚凡物盡生者曰㯷生。郭云。今種物皆生曰㯷地生也。又曰。㯷、聚也。楚謂之㯷。郭云。㯷屬、藂相箸皃。按詩、爾雅之樸。皆當同方言作㯷。㯷從僕、附也。考工記樸屬猶附蓍、文𨕖廛閈撲地字皆當作㯷。釋木、毛傳皆訓㯷爲枹。許以爲棗名則褊矣。"}]},"橪":{"expl":"酸小棗。从木然聲。一曰染也。","rad":"木","fq":"人善切","vol":"06","py":"rǎn","duan":[{"e":"酸小棗。","n":"此云酸小棗、則上文樲酸棗者與棗大小同矣。上林賦。枇把橪𣐈。按廁橪於枇杷𣐈之閒。然則皆果也。與許說合。淮南子。伐橪棗以爲矝。亦云橪棗。郭云。橪、橪支木。音煙。與許異。"}]},"柅":{"expl":"木也。實如棃。从木尼聲。","rad":"木","fq":"女履切","vol":"06","py":"nǐ","duan":[{"e":"柅木也。實如棃。","n":"今字以爲檷字。"}]},"蔗":{"expl":"藷蔗也。从艸庶聲。","rad":"艸","fq":"之夜切","vol":"01","py":"zhè","duan":[{"e":"藷蔗也。从艸。庶聲。","n":"之夜切。古音在三部。"}]},"梢":{"expl":"木也。从木肖聲。","rad":"木","fq":"所交切","vol":"06","py":"shāo","duan":[{"e":"梢木也。","n":"未詳。廣韵曰。梢、船舵尾也。又枝梢也。此今義也。釋木曰。梢、梢擢。郭云。梢音朔。按梢擢字、葢本從手作捎。"}]},"𣟌":{"expl":"木也。从木𨾀聲。","rad":"木","fq":"郎計切","vol":"06","py":"lì","duan":[{"e":"𣟌木也。","n":"未詳。"}]},"㭩":{"expl":"木也。从木寽聲。","rad":"木","fq":"力輟切","vol":"06","py":"liè","duan":[{"e":"㭩木也。","n":"未詳。"}]},"梭":{"expl":"木也。从木夋聲。","rad":"木","fq":"私閏切","vol":"06","py":"xùn","duan":[{"e":"梭木也。","n":"未詳。"}]},"㮿":{"expl":"木也。从木畢聲。","rad":"木","fq":"卑吉切","vol":"06","py":"bì","duan":[{"e":"㮿木也。","n":"未詳。"}]},"楋":{"expl":"木也。从木剌聲。","rad":"木","fq":"盧達切","vol":"06","py":"là","duan":[{"e":"楋木也。","n":"未詳。"}]},"枸":{"expl":"木也。可爲醬。出蜀。从木句聲。","rad":"木","fq":"俱羽切","vol":"06","py":"jǔ","duan":[{"e":"枸木也。可爲𤖕。出蜀。","n":"史、漢皆云枸𤖕。詳艸部蒟下。"}]},"樜":{"expl":"木。出發鳩山。从木庶聲。","rad":"木","fq":"之夜切","vol":"06","py":"zhè","duan":[{"e":"樜木。出發鳩山。","n":"北山經曰。發鳩之山、其上多柘木。許所據柘作樜也。發鳩山卽水部涷水所出之發包山。淮南書亦作發包。古音包鳩同在三部。許不言樜同柘。而廣韵謂一字。非許意也。"}]},"枋":{"expl":"木。可作車。从木方聲。","rad":"木","fq":"府良切","vol":"06","py":"fānɡ","duan":[{"e":"枋木。可作車。","n":"禮、周官皆以枋爲柄。古音方聲丙聲同在十部也。"}]},"橿":{"expl":"枋也。从木畺聲。一曰鉏柄名。","rad":"木","fq":"居良切","vol":"06","py":"jiānɡ","duan":[{"e":"枋也。","n":"謂一木二名。考工記注曰。今世轂用襍榆。輻以檀。牙以橿。郭注山海經曰。橿中車材。南都賦、吳都賦說木皆有橿。"}]},"𧃱":{"expl":"牂𧃱，可以作縻綆。从艸𤕦聲。","rad":"艸","fq":"女庚切","vol":"01","py":"nínɡ","duan":[{"e":"牂𧂘、","n":"逗。"}]},"樗":{"expl":"木也。以其皮裹松脂。从木雩聲。讀若華。","rad":"木","fq":"乎化切","vol":"06","py":"huà","duan":[{"e":"樗木也。","n":"各本樗與㯉二篆互譌。今正。毛詩音義、爾雅音義、五經文字可證也。假令許書與今互異。則陸氏、張氏當辨明之。如穜種之例矣。豳風、小雅毛傳皆曰。樗、惡木也。惟其惡木。故豳人祗以爲薪。小雅以儷惡菜。今之臭椿樹是也。所在有之。有一種葉香者可食。"}]},"檗":{"expl":"黃木也。从木辟聲。","rad":"木","fq":"博戹切","vol":"06","py":"bò","duan":[{"e":"黃木也。","n":"本艸經之檗木也。一名檀桓。"}]},"梤":{"expl":"香木也。从木㞣聲。","rad":"木","fq":"撫文切","vol":"06","py":"fēn","duan":[{"e":"香木也。","n":"㞣爲艸香。故梤爲香木。"}]},"榝":{"expl":"似茱萸。出淮南。从木殺聲。","rad":"木","fq":"所八切","vol":"06","py":"shā","duan":[{"e":"似茱萸。出淮南。","n":"釋木。茮榝醜莍。郭云。莍萸、子聚生成房皃。榝似茱萸而小。赤色。內則注曰。藙、煎茱萸也。漢律會稽獻焉。爾雅謂之榝。按鄭云藙卽榝。許於艸部有茱萸、有藙。此云似。與鄭說小異。本艸經木部云。吳茱萸。一名藙。是則一物異名。亦不待煎成始爲藙也。"}]},"槭":{"expl":"木。可作大車輮。从木戚聲。","rad":"木","fq":"子六切","vol":"06","py":"zú","duan":[{"e":"槭木。可作大車輮。","n":"未詳今何木。大車、牛車也。輮、車网。考工記之牙也。"}]},"楊":{"expl":"木也。从木昜聲。","rad":"木","fq":"与章切","vol":"06","py":"yánɡ","duan":[{"e":"蒲桺也。","n":"各木作木也二字。今依藝文類聚、初學記、本艸圖經、太平御覽所引正。釋木云。楊蒲桺。許所本也。按蒲。葢本作浦。浦、水瀕也。王風。不流束蒲。毛云。蒲艸也。箋云。蒲、蒲桺。孫毓云。蒲艸之聲不與戎許相協。箋義爲長。是則晉人讀蒲桺爲浦桺之明證。古今注曰。蒲桺生水邊。又曰。水楊、蒲楊也。枝勁細。任矢用。任矢用者、左傳云董澤之蒲是也。絫呼曰蒲桺。單𧦝曰蒲。音同浦。至唐而失其讀矣。"}]},"檉":{"expl":"河柳也。从木聖聲。","rad":"木","fq":"敕貞切","vol":"06","py":"chēnɡ","duan":[{"e":"河桺也。","n":"釋木、毛傳同。陸機云。生水旁。皮正赤如絳。一名雨師。羅願云。葉細如絲。天將雨。檉先起氣迎之。故曰雨師。按檉之言赬也。赤莖故曰檉。廣韻釋楊爲赤莖桺。非也。"}]},"桺":{"expl":"小楊也。从木戼聲。戼，古文酉。","rad":"木","fq":"力九切","vol":"06","py":"liǔ","duan":[{"e":"少楊也。","n":"各本作小楊。今依孟子正義。葢古本也。古多以少爲小。如少兒卽小兒之類。楊之細莖小葉者曰桺。周禮故書。及接橮之材。鄭司農讀爲歰桺。後鄭云。桺之言聚也。引書分命和仲。度西曰桺穀。按度西曰桺穀者、今文尙書也。宅西曰昧谷者、後鄭所讀之古文尙書也。詳見尙書撰異。"}]},"𣖼":{"expl":"大木。可爲鉏柄。从木𠣬聲。","rad":"木","fq":"詳遵切","vol":"06","py":"xún","duan":[{"e":"大木。可爲鉏柄。","n":"未詳。"}]},"欒":{"expl":"木。似欄。从木䜌聲。《禮》：天子樹松，諸侯柏，大夫欒，士楊。","rad":"木","fq":"洛官切","vol":"06","py":"luán","duan":[{"e":"欒木。似欄。","n":"欄者今之楝字。本艸經有欒華。未知是不。借爲圜曲之偁。如鐘角曰欒、屋曲枅曰欒是。"}]},"祔":{"expl":"後死者合食於先祖。从示付聲。","rad":"示","fq":"符遇切","vol":"01","py":"fù","duan":[{"e":"後死者合食於先祖。","n":"士虞禮。卒哭。明日以其班祔。春秋左氏傳曰。凡君薨。卒哭而祔。祔而作主。特祀於主。蒸嘗禘於廟。春秋榖梁傳曰。作主壞廟有時日於練焉。士虞禮注與穀梁同。"}]},"𧀩":{"expl":"艸也。从艸賜聲。","rad":"艸","fq":"斯義切","vol":"01","py":"sì","duan":[{"e":"艸也。从艸。賜聲。","n":"斯義切。十六部。"}]},"栘":{"expl":"棠棣也。从木多聲。","rad":"木","fq":"弋支切","vol":"06","py":"yí","duan":[{"e":"棠棣也。","n":"釋木曰。唐棣、栘常棣、棣。唐與常音同葢謂其花赤者爲唐棣。花白者爲棣。一類而錯舉故許云栘、棠棣也。棣、白棣也。改唐爲棠。改常爲白。以棠對白。則棠爲赤可知。皆卽今郁李之類。有子可食者。小雅常棣、論語逸詩唐棣、實一物也。郭注唐棣云。似白楊。江東呼夫栘。白楊、大樹也。古今注云。栘楊亦曰栘桺。亦曰蒲栘。圓葉弱蒂。微風善搖。此正今之白楊樹。安得有𩏬𩏬偏反之𠌶耶。因一栘字掍合之。"}]},"棣":{"expl":"白棣也。从木隶聲。","rad":"木","fq":"特計切","vol":"06","py":"dì","duan":[{"e":"白棣也。","n":"小雅傳曰。常棣、棣也。秦風傳曰。棣、唐棣也。常與唐同字可證矣。渾言之則白棣亦𧦝唐棣也。豳風傳云。鬱、棣屬。"}]},"枳":{"expl":"木。似橘。从木只聲。","rad":"木","fq":"諸氏切","vol":"06","py":"zhǐ","duan":[{"e":"枳木。似橘。","n":"考工記。橘踰淮而北爲枳。本艸經所謂枳實也。枳可爲籬。周書小開曰。德枳維大人。"}]},"楓":{"expl":"木也。厚葉弱枝，善搖。一名欇。从木風聲。","rad":"木","fq":"方戎切","vol":"06","py":"fēnɡ","duan":[{"e":"楓木也。厚葉弱枝。善榣。一名𣠞𣠞。","n":"各本榣作搖。今正。少一𣠞字。今依韵會補。釋木曰。楓、欇欇。犍爲舍人曰。楓爲樹。厚葉弱莖。大風則鳴。故曰欇欇。按𣠞、木葉榣白也。榣、樹動也。厚葉弱枝故善榣。善榣故名𣠞𣠞。嵇含南方艸木狀。分楓人楓香爲二條。實一木也。"}]},"權":{"expl":"黃華木。从木雚聲。一曰反常。","rad":"木","fq":"巨員切","vol":"06","py":"quán","duan":[{"e":"黃𦶎木。","n":"釋木曰。權、黃英。按英𦶎一也。郭云未詳。而釋艸亦云。權、黃𦶎。郭云。今謂牛芸艸爲黃𦶎。艸部英下一曰黃英。然則爾雅木曰黃英、艸曰黃𦶎。許則英𦶎字互易。"}]},"柜":{"expl":"木也。从木巨聲。","rad":"木","fq":"其呂切","vol":"06","py":"jǔ","duan":[{"e":"柜木也。","n":"趙注孟子曰。杞桺、柜桺也。郭注爾雅曰。柜桺似桺。皮可煑作飲。廣韵柜下云。柜桺。按柜今俗作櫸。又音譌爲鬼桺樹。未知許所言是此不。"}]},"槐":{"expl":"木也。从木鬼聲。","rad":"木","fq":"戶恢切","vol":"06","py":"huái","duan":[{"e":"槐木也。","n":"釋木曰。櫰槐、大葉而黑。守宮槐、葉晝聶宵炕。按此皆槐之異者。"}]},"榖":{"expl":"楮也。从木㱿聲。","rad":"木","fq":"古祿切","vol":"06","py":"ɡǔ","duan":[{"e":"楮也。","n":"此篆體依五經文字正。各本作<>者、從𥻳便也。小雅傳曰。榖、惡木也。陸機疏曰。江南以其皮擣爲紙。謂之榖皮紙。絜白光輝。按山海經傳曰。榖亦名構。此一語之輕重耳。"}]},"楮":{"expl":"榖也。从木者聲。","rad":"木","fq":"丑呂切","vol":"06","py":"chǔ","duan":[{"e":"榖也。從木。者聲。","n":"丑呂切。五部。"}]},"檵":{"expl":"枸杞也。从木，繼省聲。一曰監木也。","rad":"木","fq":"古詣切","vol":"06","py":"jì","duan":[{"e":"枸杞也。","n":"四牡、四月傳皆曰。杞、枸檵也。他杞字無傳。讀詩者有三杞之說焉。"}]},"𦬕":{"expl":"艸也。从艸中聲。","rad":"艸","fq":"陟宮切","vol":"01","py":"zhōnɡ","duan":[{"e":"艸也。从艸。中聲。","n":"陟宮切。九部。"}]},"杞":{"expl":"枸杞也。从木己聲。","rad":"木","fq":"墟里切","vol":"06","py":"qǐ","duan":[{"e":"枸杞也。","n":"按釋木、毛傳皆云。杞、枸檵。禮記鄭注亦云。芑、枸檵也。郭注爾雅云。今枸杞也。是則枸檵爲古名。枸杞雖見本艸經。而爲今名。許檵篆下當云。枸檵杞也。杞篆下當云。杞枸檵也。乃合。今本後人亂之耳。"}]},"枒":{"expl":"木也。从木牙聲。一曰車𨊾會也。","rad":"木","fq":"五加切","vol":"06","py":"yá","duan":[{"e":"枒木也。","n":"上林賦有胥邪。史記作胥餘。南都賦作楈枒。蜀都、吳都賦單𧦝之曰枒。艸木狀作㭨。其木葉在顚。略似椶樹。而實大如瓠。繫在顚。若挂物。今俗用㭨瓢是也。"}]},"檀":{"expl":"木也。从木亶聲。","rad":"木","fq":"徒乾切","vol":"06","py":"tán","duan":[{"e":"檀木也。","n":"鄭風傳曰。檀、彊刃之木。刃今韌字。榽醯似檀。齊人諺曰。上山斫檀。榽醯先殫。"}]},"櫟":{"expl":"木也。从木樂聲。","rad":"木","fq":"郎擊切","vol":"06","py":"lì","duan":[{"e":"櫟木也。","n":"秦風隰有苞櫟傳曰。櫟木也。陸機曰。苞櫟、秦人謂柞櫟爲櫟。河內人謂木蓼爲櫟。椒樧之屬。其子房生爲梂。木蓼子亦房生。故說者或曰柞櫟。或曰木蓼。機以爲此秦詩也。宜從其方土之言。柞櫟是也。按陸意謂秦詩當是柞櫟。今觀許櫟梂二篆連屬。正與陸所云木蓼子房生爲梂者合。然則許意謂木蓼也。艸部云。草𣁬、櫟實也。一曰樣𣁬。木部栩下云。𣏗也。其草一曰樣。此則謂草𣁬爲櫟實。正陸所謂秦人謂柞櫟爲櫟。又云。栩今柞櫟也。草下櫟實字非木部之櫟。許意栩𣏗、樣草爲一物。是名柞櫟。亦名櫟。而非柞也。亦非子梂生之櫟也。柞與棫爲類。櫟似椒榝。鄭箋大雅云。柞櫟也。則以柞與柞櫟合爲一耳。"}]},"梂":{"expl":"櫟實。一曰𨯳首。从木求聲。","rad":"木","fq":"巨鳩切","vol":"06","py":"qiú","duan":[{"e":"櫟實。","n":"此櫟實與草下櫟實各物。草下當云草𣁬、柞櫟實。損柞字耳。釋木曰。櫟、其實梂。陸機云。椒榝之屬。其子房生爲梂。木蓼子亦房生。然則許何爲以。梂字專系諸木蓼也。曰艸部以莍系諸茮榝矣。則以梂系諸櫟也。莍與梂皆謂聚生成房。橡𣁬不尒也。梂與莍古通用。椒𦕼箋云。一梂之實。蕃衍升。非其常也。此假梂爲莍也。今俗語謂緐多叢聚曰一梂。椒子每梂數十百顆。詩人言其盛。則曰每梂將盈升。不識正義何以不解也。木蓼、唐本艸謂之木天蓼。蘇頌云。木高二三丈。三四月開花。似柘花。五月採子。子作毬。"}]},"楝":{"expl":"木也。从木柬聲。","rad":"木","fq":"郎電切","vol":"06","py":"liàn","duan":[{"e":"欄木也。","n":"各木篆作楝。下文云柬聲。今改正。按考工記。以欄爲灰。字作欄。許於欒下云。木似欄。然則此當同考工記可知矣。廣韵廿五寒欄下云。木名。從古字古音也。欄俗作楝。乃用欄爲闌檻俗字。欄實曰金鈴子。可用浣衣。"}]},"檿":{"expl":"山桑也。从木厭聲。《詩》曰：“其檿其柘。”","rad":"木","fq":"於𤥎切","vol":"06","py":"yǎn","duan":[{"e":"山桑也。","n":"釋木曰。檿桑、山桑。大雅毛傳曰。檿、山桑也。禹貢檿絲。史記檿作酓。同音假借字也。"}]},"柘":{"expl":"桑也。从木石聲。","rad":"木","fq":"之夜切","vol":"06","py":"zhè","duan":[{"e":"柘桑也。","n":"三字句。各本無柘字。今補。山桑、柘桑皆桑之屬。古書竝言二者則曰桑柘。單言一者則曰桑。曰柘。柘亦曰柘桑。如淮南注烏號云柘桑其木堅勁、鳥峙其上是也。桑、柘相似而別。見胡氏通鑑釋文辨誤。"}]},"𣛺":{"expl":"木，可爲杖。从木厀聲。","rad":"木","fq":"親吉切","vol":"06","py":"qī","duan":[{"e":"𣛺木。可爲杖。","n":"小徐云。今楖栗之屬。"}]},"𣟳":{"expl":"𣟳味，稔棗。从木還聲。","rad":"木","fq":"似沿切","vol":"06","py":"xuán","duan":[{"e":"𣟳味、","n":"逗。"}]},"萯":{"expl":"王萯也。从艸負聲。","rad":"艸","fq":"房九切","vol":"01","py":"fù","duan":[{"e":"王萯也。","n":"夏小正。四月王萯秀。月令。四月王瓜生。注云。今月令云王萯秀。豳風四月秀葽箋。疑葽卽王萯。管子地員有萯。有大萯細萯。"}]},"梧":{"expl":"梧桐木。从木吾聲。一名櫬。","rad":"木","fq":"五胡切","vol":"06","py":"wú","duan":[{"e":"梧桐木。","n":"三字句。釋木曰。櫬梧。賈思勰曰。注云今梧桐皮靑者曰梧桐。案今人以其皮靑。號曰靑桐也。玉裁謂。此今人所植梧桐樹也。其華五出。子如珠。綴於瓢邊。瓢如羹匙。賈氏云靑桐九月收子、炒食甚美、如菱芡是也。"}]},"榮":{"expl":"桐木也。从木，熒省聲。一曰屋梠之兩頭起者爲榮。","rad":"木","fq":"永兵切","vol":"06","py":"rónɡ","duan":[{"e":"桐木也。","n":"見釋木。按梧下云。梧桐木。榮下曰。桐木。此卽賈思勰靑桐、白桐之別也。白桐華而不實。材中樂器。靑桐則不中用。毛詩。椅桐梓漆。爰伐琴瑟。其白桐與。又云。其桐其椅。其實離離。則靑桐亦𧦝桐。渾言之也。郭注爾雅。於榮桐木曰。卽梧桐。於櫬梧曰。今梧桐皮靑者。本不誤。今本𠜂節。乃不可通。"}]},"桐":{"expl":"榮也。从木同聲。","rad":"木","fq":"徒紅切","vol":"06","py":"tónɡ","duan":[{"e":"榮也。從木。同聲。","n":"徒紅切。九部。"}]},"橎":{"expl":"木也。从木番聲。讀若樊。","rad":"木","fq":"附轅切","vol":"06","py":"fán","duan":[{"e":"橎木也。","n":"未詳。"}]},"榆":{"expl":"榆，白枌。从木俞聲。","rad":"木","fq":"羊朱切","vol":"06","py":"yú","duan":[{"e":"榆白枌。","n":"見釋木。陳風東門之枌傳云。枌、白榆也。然則釋木榆白爲逗、枌爲句、顯然。許意亦如此讀。別榆一穜以起下也。榆莢可食。亦可爲𤖕。酉部所謂𨡭䤅也。"}]},"枌":{"expl":"榆也。从木分聲。","rad":"木","fq":"扶分切","vol":"06","py":"fén","duan":[{"e":"枌榆也。","n":"三字句。各本少枌。淺人以爲複字而誤𠜂之。枌榆者、榆之一穜。漢初有枌榆社是也。"}]},"梗":{"expl":"山枌榆。有朿，莢可爲蕪夷者。从木更聲。","rad":"木","fq":"古杏切","vol":"06","py":"ɡěnɡ","duan":[{"e":"山枌榆、有朿。","n":"山枌榆、又枌榆之一穜也。有朿。故名梗榆。卽齊民要術所謂刺榆者也。方言凡草木刺人、自關而東或謂之梗。郭注。今云梗榆是也。"}]},"樵":{"expl":"𢿱也。从木焦聲。","rad":"木","fq":"昨焦切","vol":"06","py":"qiáo","duan":[{"e":"𢿱木也。","n":"小雅。樵彼桑薪列子書以蕉爲樵。按上下文皆木名也。此字廁此。恐非其舊次。當與柴篆爲伍。"}]},"松":{"expl":"木也。从木公聲。","rad":"木","fq":"祥容切","vol":"06","py":"sōnɡ","duan":[{"e":"松木也。從木。公聲。","n":"祥容切。九部。集韵思恭切。關內語也。按俗皆從關內語惟徽州讀祥容切。"}]},"樠":{"expl":"松心木。从木㒼聲。","rad":"木","fq":"莫奔切","vol":"06","py":"mán","duan":[{"e":"松心木。","n":"疑有奪誤。當作松心也。一曰樠木也。廣韵廿二元注曰。松心。又木名也。所據古本也。蒙上文松木言之。故曰松心謂之樠。葢松心微赤。故與𣯩璊同音。又松心有脂。莊子所謂液樠。廣韵養韵釋𣓈曰。松脂。正樠爲松脂之誤也。一曰樠木也者、別有木名樠。如左傳卒於樠木之下、馬融廣成頌陵喬松履脩樠、漢書烏孫國山多松樠是也。小顏云。樠、木名。其心似松。是小顏所據已同今本矣。舊有樠𣓈二字。一㒼聲。一兩聲。左傳樠木音義云。郎蕩反。又莫昆、武元二反。馬援傳章懷注曰。水經注。武陵五溪。謂雄溪、樠溪、酉溪、潕溪、辰溪。蠻土俗雄作熊。樠作朗。潕作武。是皆認樠爲𣓈。未別其字。而强說其音也。"}]},"芺":{"expl":"艸也。味苦，江南食以下气。从艸夭聲。","rad":"艸","fq":"烏皓切","vol":"01","py":"ǎo","duan":[{"e":"艸也。味苦。江南食之㠯下气。","n":"名醫別錄云。苦芺主桼瘡。不云可下氣。漢人謂䂊章長沙爲江南。"}]},"檜":{"expl":"柏葉松身。从木會聲。","rad":"木","fq":"古外切","vol":"06","py":"ɡuì","duan":[{"e":"柏葉松身。","n":"釋木、衞風毛傳皆曰。檜、柏葉松身。禹貢作桰。"}]},"樅":{"expl":"松葉柏身。从木從聲。","rad":"木","fq":"七恭切","vol":"06","py":"cōnɡ","duan":[{"e":"松葉柏身。","n":"見釋木。郭引尸子曰。松柏之鼠。不知堂密之有美樅。按堂密、謂山如堂者。"}]},"柏":{"expl":"鞠也。从木白聲。","rad":"木","fq":"博陌切","vol":"06","py":"bǎi","duan":[{"e":"鞠也。","n":"釋木曰。柏、椈襍記。暢臼以椈。鄭曰。椈、柏也。按椈者鞠之俗。柏、古多假借爲伯仲之伯、促迫之迫。"}]},"机":{"expl":"木也。从木几聲。","rad":"木","fq":"居履切","vol":"06","py":"jī","duan":[{"e":"机木也。","n":"山海經。單狐之山多机木。族𥮐之山多松柏机桓。郭曰。机木似榆。可燒以糞稻田。音飢。按葢卽榿木也。今成都榿木樹。讀若豈平聲。楊雄蜀都賦曰。春机楊桺。机榿古今字。榿見杜詩。王安石詩以榿滋移爲韵。韵會音邱其切。與蜀語合。"}]},"枮":{"expl":"木也。从木占聲。","rad":"木","fq":"息廉切","vol":"06","py":"xiān","duan":[{"e":"枮木也。","n":"未詳。"}]},"梇":{"expl":"木也。从木弄聲。益州有梇棟縣。","rad":"木","fq":"盧貢切","vol":"06","py":"lònɡ","duan":[{"e":"梇木也。","n":"未詳。"}]},"楰":{"expl":"鼠梓木。从木臾聲。《詩》曰：“北山有楰。”","rad":"木","fq":"羊朱切","vol":"06","py":"yú","duan":[{"e":"鼠梓木。","n":"釋木、小雅毛傳皆曰。楰、鼠梓也。陸機、郭璞皆云楸屬。"}]},"桅":{"expl":"黃木，可染者。从木危聲。","rad":"木","fq":"過委切","vol":"06","py":"ɡuǐ","duan":[{"e":"黃木。可染者。","n":"各本篆文誤作桅。今依韵會所據本正。小徐云。史記貨殖傳千畞卮茜、又書記多言鮮支、皆此。是鍇本固作栀字。證一。玉篇列字次弟與說文同。而梇楰杒榙四字之閒字作栀。之移切。不作桅。桅字乃𡉈下文孫强等增竄之處。證二。水部染下引裴光遠曰從木。木者所以染。桅茜之屬也。此用史記栀茜。而亦譌作桅。證三。桅、今之栀子樹。實可染黃。相如賦謂之鮮之。史記假卮爲之。"}]},"杒":{"expl":"桎杒也。从木刃聲。","rad":"木","fq":"而震切","vol":"06","py":"rèn","duan":[{"e":"桎杒也。","n":"未詳何木。"}]},"𣝋":{"expl":"榙𣝋，木也。从木遝聲。","rad":"木","fq":"徒合切","vol":"06","py":"tà","duan":[{"e":"榙𣝋木也。從木。遝聲。","n":"徒合切。八部。"}]},"𦱁":{"expl":"艸也。从艸弦聲。","rad":"艸","fq":"胡田切","vol":"01","py":"xián","duan":[{"e":"艸也。从艸。弦聲。","n":"胡田切。十二部。"}]},"榙":{"expl":"榙𣝋。果似李。从木荅聲。讀若嚃。","rad":"木","fq":"土合切","vol":"06","py":"tā","duan":[{"e":"榙𣝋、","n":"逗。"}]},"某":{"expl":"酸果也。从木从甘。闕。","rad":"木","fq":"莫厚切","vol":"06","py":"méi","duan":[{"e":"酸果也。","n":"此是今梅子正字。說見梅下。"}]},"櫾":{"expl":"崐崘河隅之長木也。从木繇聲。","rad":"木","fq":"以周切","vol":"06","py":"yóu","duan":[{"e":"崐崘山河隅之長木也。","n":"崐崘當作昆侖。山字依類篇補。西山經曰。槐江之山。西望其大澤。其陰多榣木。郭曰。榣木、大木。引國語榣木不生危。按榣卽櫾字。韋注晉語亦云。榣木、大木也。晉語一本作拱木。非。許謂櫾爲長木。榣爲樹動。他書則櫾爲橘柚。榣爲長木。用字之不同也。穆天子傳曰。天子釣于河。以觀繇之木。郭云。姑繇大木。姑繇亦卽櫾也。"}]},"樹":{"expl":"生植之緫名。从木尌聲。","rad":"木","fq":"常句切","vol":"06","py":"shù","duan":[{"e":"木生植之緫名也。","n":"植、立也。假借爲尌竪字。"}]},"本":{"expl":"木下曰本。从木，一在其下。","rad":"木","fq":"布忖切","vol":"06","py":"běn","duan":[{"e":"木下曰本。從木。從丅。","n":"此篆各本作<>。解云。從木、一𡉈其下。今依六書故所引唐本正。本未皆於形得義。其形一從木丄。一從木丅。而意卽𡉈是。全書如此者多矣。一記其處之說。非物形也。大雅以{木+丅[上下]}奏爲奔走。假借也。布忖切。十三部。"}]},"柢":{"expl":"木根也。从木氐聲。","rad":"木","fq":"都禮切","vol":"06","py":"dǐ","duan":[{"e":"木根也。","n":"道德經。深其根。固其柢。長生久視之道。韓非解老曰。樹木有曼根。有直根。直根者、書之所謂柢也。柢也者、木之所以建生也。曼根者、木之所以持生也。按直者曰直根。橫者曰曼根。柢或借蒂字爲之。又借氐字爲之。節南山傳曰氐本也是。"}]},"朱":{"expl":"赤心木。松柏屬。从木，一在其中。","rad":"木","fq":"章俱切","vol":"06","py":"zhū","duan":[{"e":"赤心木。松柏屬。","n":"朱本木名。引伸假借爲純赤之字。糸部曰。絑、純赤也。是其本字也。"}]},"根":{"expl":"木株也。从木艮聲。","rad":"木","fq":"古痕切","vol":"06","py":"ɡēn","duan":[{"e":"木株也。從木。𥃩聲。","n":"古痕切。十三部。"}]},"株":{"expl":"木根也。从木朱聲。","rad":"木","fq":"陟輸切","vol":"06","py":"zhū","duan":[{"e":"木根也。","n":"莊、列皆有厥株駒。株今俗語云樁。"}]},"末":{"expl":"木上曰末。从木，一在其上。","rad":"木","fq":"莫撥切","vol":"06","py":"mò","duan":[{"e":"木上曰𠅅。從木。從丄。","n":"此篆各本作<>。解云從木、一𡉈其上。今依六書故所引唐本正。莫撥切。十五部。六書故曰。𠅅（末）、木之竆也。因之爲𠅅殺、𠅅減、略𠅅。又與蔑莫無聲義皆通。記曰。𠅅之卜也。語曰。吾𠅅如之何、𠅅由也已。"}]},"𧅲":{"expl":"艸也。从艸𡈹聲。𡈹，籀文囿。","rad":"艸","fq":"于救切","vol":"01","py":"yòu","duan":[{"e":"艸也。从艸。𡈹聲。","n":"于救切。古音在一部。"}]},"㮨":{"expl":"細理木也。从木畟聲。","rad":"木","fq":"子力切","vol":"06","py":"jì","duan":[{"e":"細理木也。","n":"㮨見西山經、南都賦。郭曰㮨似松。有刺。細理。劉淵林注蜀都賦曰。楔似松。有剌。按蜀都楔字葢㮨之譌。"}]},"果":{"expl":"木實也。从木，象果形在木之上。","rad":"木","fq":"古火切","vol":"06","py":"ɡuǒ","duan":[{"e":"木實也。","n":"上文言果多矣。故緫釋之。引伸假借爲誠實勇敢之偁。"}]},"𣚎":{"expl":"木實也。从木絫聲。","rad":"木","fq":"力追切","vol":"06","py":"léi","duan":[{"e":"木實也。","n":"絫者今之累積字。從絫、言其多也。假借則扁榼謂之樏。似盤、中有隔也。"}]},"杈":{"expl":"枝也。从木叉聲。","rad":"木","fq":"初牙切","vol":"06","py":"chā","duan":[{"e":"杈枝也。","n":"三字句。廣韵曰。方言云。江東言樹枝爲椏杈也。枝如手指相錯之形。故從叉。"}]},"枝":{"expl":"木别生條也。从木支聲。","rad":"木","fq":"章移切","vol":"06","py":"zhī","duan":[{"e":"木別生條也。","n":"艸部曰。莖、枝主也。榦與莖爲艸木之主。而別生條謂之枝。枝必岐出也。故古枝岐通用。"}]},"朴":{"expl":"木皮也。从木卜聲。","rad":"木","fq":"匹角切","vol":"06","py":"pò","duan":[{"e":"木皮也。","n":"洞蕭賦。秋蜩不食、抱朴以長吟。李注。抱音附。引蒼頡篇。朴、木皮也。顏注急就篇、上林賦厚朴曰。朴、木皮也。此樹以皮厚得名。按廣雅云。重皮、厚朴也。"}]},"條":{"expl":"小枝也。从木攸聲。","rad":"木","fq":"徒遼切","vol":"06","py":"tiáo","duan":[{"e":"小枝也。","n":"毛傳曰。枝曰條。渾言之也。條爲枝之小者。析言之也。"}]},"枚":{"expl":"榦也。可爲杖。从木从攴。《詩》曰：“施于條枚。”","rad":"木","fq":"莫桮切","vol":"06","py":"méi","duan":[{"e":"榦也。","n":"毛傳曰。榦曰枚。引伸爲銜枚之枚。爲枚數之枚。豳風傳曰。枚、微也。魯頌傳曰。枚枚、礱密也。皆謂枚爲微之假借也。"}]},"𣓁":{"expl":"槎識也。从木、纨。闕。《夏書》曰：“隨山𣓁木。”讀若刊。","rad":"木","fq":"苦寒切","vol":"06","py":"kān","duan":[{"e":"槎識也。","n":"槎、衺斫也。槎識者、衺斫以爲表志也。斫之以爲表識。如孫臏斫大樹白而書之曰龎涓死此樹下、是其意也。禹貢。隨山𣓁木。夏本紀作行山表木。此古說也。今尙書益稷、禹貢皆作隨山刊木、九山刊旅。周禮曰。刊陽木。左傳曰。井堙木刊。木非不言刊也。然刀部曰。刊、剟也。剟、刊也。刊者、除去之意。與𣓁訓槎識不同。葢壁中古文作𣓁。今文尙書作𣓁。則未知何時改爲刊也。據正義已作刊。則非衞包所改。"}]},"𣠞":{"expl":"木葉榣白也。从木聶聲。","rad":"木","fq":"之涉切","vol":"06","py":"zhé","duan":[{"e":"木葉榣白也。","n":"榣各本從手。今正。榣、樹動也。凡木葉面靑背白、爲風所攝則獵獵然背白盡露。故曰榣白。楓厚葉弱枝善榣。一名𣠞𣠞是也。釋木又有𣠞虎櫐。則未得其解。"}]},"莩":{"expl":"艸也。从艸孚聲。","rad":"艸","fq":"芳無切","vol":"01","py":"fú","duan":[{"e":"艸也。从艸。孚聲。","n":"芳無切。古音在三部。"}]},"栠":{"expl":"弱皃。从木任聲。","rad":"木","fq":"如甚切","vol":"06","py":"rěn","duan":[{"e":"弱皃。","n":"小雅、大雅皆言荏染柔木。毛曰。荏染、柔意也。論語。色厲而內荏。孔曰。荏、柔也。按此荏皆當作栠。桂荏謂蘇也。經典多假荏而栠廢矣。"}]},"枖":{"expl":"木少盛皃。从木夭聲。《詩》曰：“桃之枖枖。”","rad":"木","fq":"於喬切","vol":"06","py":"yāo","duan":[{"e":"木少盛皃。","n":"周南。桃之夭夭。毛曰。桃、有華之盛者。夭夭、其少壯也。邶風。棘心夭夭。毛曰。夭夭、盛皃。按夭下曰。屈也。屈者大之反。然屈者大之兆也。故枖字從夭。"}]},"槇":{"expl":"木頂也。从木眞聲。一曰仆木也。","rad":"木","fq":"都秊切","vol":"06","py":"diān","duan":[{"e":"木頂也。","n":"人頂曰顚。木頂曰槇。今顚行而槇廢矣。"}]},"梃":{"expl":"一枚也。从木廷聲。","rad":"木","fq":"徒頂切","vol":"06","py":"tǐnɡ","duan":[{"e":"一枚也。","n":"凡條直者曰梃。梃之言挺也。一枚、疑當作木枚。竹部曰。箇、竹枚。則梃當云木枚也。方言曰。箇、枚也。鄭注禮經云。个猶枚也。今俗或名枚曰個。音相近。按枚、榦也。一莖謂之一枚。因而凡物皆以枚數。左傳。以枚數闔。謂枚枚數之。猶云一一數之也。直者則曰梃。如孟子制梃、漢書白梃皆是。禮經脯梃字本作梃。亦作挺。俗作脡。誤也。詳肉部。"}]},"䯂":{"expl":"眾盛也。从木驫聲。《逸周書》曰：“疑沮事。”闕。","rad":"木","fq":"所臻切","vol":"06","py":"shēn","duan":[{"e":"衆盛也。","n":"焱部曰。焱、盛皃。䯂與燊同意。三馬、三火皆盛意也。"}]},"標":{"expl":"木杪末也。从木𤐫聲。","rad":"木","fq":"敷沼切","vol":"06","py":"biāo","duan":[{"e":"木杪𠅅也。","n":"杪𠅅（末）、謂𠅅（末）之細者也。古謂木未曰本標。如素問有標本病傳論是也。亦作本剽。如莊子云有長而無本剽者是也。標𡉈冣上。故引伸之義曰標舉。肆師。表齍盛告絜。注云。故書表爲剽。剽表皆謂微識也。按表剽皆同標。"}]},"杪":{"expl":"木標末也。从木少聲。","rad":"木","fq":"亡沼切","vol":"06","py":"miǎo","duan":[{"e":"木標𠅅也。","n":"方言曰。杪、小也。木細枝謂之杪。郭注。言杪捎也。按引伸之凡𠅅（末）皆曰杪。王制言嵗之杪是也。"}]},"朶":{"expl":"樹木垂朵朵也。从木，象形。此與𥝩同意。","rad":"木","fq":"丁果切","vol":"06","py":"duǒ","duan":[{"e":"樹木𠂹朵朵也。","n":"凡枝葉華實之𡍮者皆曰朵朵。今人但謂一華爲一朵。引伸爲易之朵頥。李鼎祚曰。朵、頤垂下動之皃也。"}]},"桹":{"expl":"高木也。从木良聲。","rad":"木","fq":"魯當切","vol":"06","py":"lánɡ","duan":[{"e":"高木也。","n":"此泛言高木謂之桹。非謂桄桹及檳榔也。門部閬訓門高。義相近。"}]},"橌":{"expl":"大木皃。从木閒聲。","rad":"木","fq":"古限切","vol":"06","py":"jiàn","duan":[{"e":"大木皃。","n":"未見其證。小徐說以左傳橌然授兵登陴。今左傳自唐石經而下皆從手。"}]},"蔩":{"expl":"兎苽也。从艸寅聲。","rad":"艸","fq":"翼眞切","vol":"01","py":"yín","duan":[{"e":"兔瓜也。","n":"見釋艸。"}]},"枵":{"expl":"木根也。从木号聲。《春秋傳》曰：“歲在玄枵。”玄枵，虛也。","rad":"木","fq":"許嬌切","vol":"06","py":"xiāo","duan":[{"e":"木皃。","n":"大徐本作木根。非也。木根則當廁於本柢根株四篆処矣。枵、木大皃。莊子所云呺然大也。木大則多空穴。莊子曰。大木百圍之竅穴。似枅似圈似臼。似洼者。似污者。故左氏釋玄枵云。枵、虛也。"}]},"柖":{"expl":"樹搖皃。从木召聲。","rad":"木","fq":"止搖切","vol":"06","py":"sháo","duan":[{"e":"樹榣皃。","n":"榣各本作搖。今正。柖之言招也。樹高大則如能招風者然。漢志郊祀歌。體招搖。若永望。注。招搖、申動之皃。按此招搖與柖榣同。師古音韶。猶玉篇柖、時昭切也。"}]},"榣":{"expl":"樹動也。从木䍃聲。","rad":"木","fq":"余昭切","vol":"06","py":"yáo","duan":[{"e":"樹動也。","n":"榣之言搖也。今俗語謂煽惑人爲招搖。當用此從木二字。謂能招致而搖動之也。"}]},"樛":{"expl":"下句曰樛。从木翏聲。","rad":"木","fq":"吉虯切","vol":"06","py":"jiū","duan":[]},"朻":{"expl":"高木也。从木丩聲。","rad":"木","fq":"吉虯切","vol":"06","py":"jiū","duan":[{"e":"高木下曲也。從木丩。丩亦聲。","n":"此韵會所據小徐本也。今二徐本皆分樛朻爲二篆。樛訓下曲。朻訓高木。乃張次立以鉉改鍇而然。鍇云。詩作樛。爾雅作朻。依詩爲正。鍇意許書作朻未是也。今考釋木曰。下句曰朻。南有樛木毛傳曰。木下曲曰樛。下曲卽下句也。樛卽朻也。一字而形聲不同。許則從丩聲者、容許當曰毛詩亦作朻也。玉篇分引詩、爾雅而云二同。甚爲明晢。丩者、相糾繚也。凡高木下句。垂枝必相糾繚。故曰從木丩。丩亦聲。吉虬切。三部。"}]},"枉":{"expl":"衺曲也。从木㞷聲。","rad":"木","fq":"迂往切","vol":"06","py":"wǎnɡ","duan":[{"e":"衺曲也。","n":"本謂木衺曲。因以爲凡衺曲之偁。"}]},"橈":{"expl":"曲木。从木堯聲。","rad":"木","fq":"女教切","vol":"06","py":"nào","duan":[{"e":"曲木也。","n":"引伸爲凡曲之偁。見周易、考工記、月令、左傳。古本無從手橈字。後人肊造之以別於橈。非也。"}]},"枎":{"expl":"枎疏，四布也。从木夫聲。","rad":"木","fq":"防無切","vol":"06","py":"fú","duan":[{"e":"枎疏。","n":"逗。"}]},"檹":{"expl":"木檹施。从木旖聲。賈侍中說，檹卽椅木，可作琴。","rad":"木","fq":"於离切","vol":"06","py":"yī","duan":[{"e":"木旖施也。","n":"旖各本作檹。施集韵類篇作柅。皆非也。㫃部旖下曰。旗旖施也。旗旖施、故字從㫃。木如旗之旖施、故字從木旖。九辨。紛旖旎乎都房。王注。旖旎、盛皃。引詩旖旎其華。九歎注同。然則今曹風猗儺。毛曰猗儺、柔順也。猗儺卽旖施。旎者施之俗也。柅者又旎之譌也。上林賦。旖旎從風。張揖云。旖旎猶阿𨙻。漢書、文𨕖皆作猗柅。韵書紙韵作猗狔、椅柅、旖旎。哿韵作㫊𣃽、𣘨橠。其實皆同字也。"}]},"㭂":{"expl":"相高也。从木小聲。","rad":"木","fq":"私兆切","vol":"06","py":"jiǎo","duan":[{"e":"𣒪也。","n":"𣒪各本作相高二字。今正。玉篇曰。㭂、木忽高也。以𣒪字之解解之。是㭂訓𣒪也。㭂者言其杪末之高。"}]},"荓":{"expl":"馬帚也。从艸并聲。","rad":"艸","fq":"薄經切","vol":"01","py":"pínɡ","duan":[{"e":"馬帚也。","n":"見釋艸。夏小正。七月荓秀，荓也者、馬帚也。廣雅曰。馬帚、屈馬荓也。"}]},"𣓗":{"expl":"高皃。从木曶聲。","rad":"木","fq":"呼骨切","vol":"06","py":"hū","duan":[{"e":"𡇆高皃。","n":"各本無𡇆字。今按玉篇㭂下云忽高者、正用𣒪之解也。倏忽字今作忽。許作𡇆。𡇆高者、忽然而高。如桑穀一暮大拱。西京賦神山崔巍倏從背見之類。"}]},"槮":{"expl":"木長皃。从木參聲。《詩》曰：“槮差荇菜。”","rad":"木","fq":"所今切","vol":"06","py":"shēn","duan":[{"e":"長木皃。","n":"本作木長。今正。九辨。萷櫹槮之可哀。卽許之橚槮二字也。王注。莖獨立也。上林賦。紛溶萷蔘。郭云。支竦擢也。蔘同槮。李善音森。"}]},"梴":{"expl":"長木也。从木延聲。《詩》曰：“松桷有梴。”","rad":"木","fq":"丑連切","vol":"06","py":"chān","duan":[{"e":"長木也。從木。㢟聲。","n":"丑連切。十四部。"}]},"橚":{"expl":"長木皃。从木肅聲。","rad":"木","fq":"山巧切","vol":"06","py":"sù","duan":[{"e":"長木皃。","n":"橚與槮同義聯文。淺人以梴梗其閒。非也。九辨櫹卽橚。淺人加艸耳。吳都賦說竹曰。橚矗森萃。史記上林賦。紛容蕭蔘。蕭同橚。"}]},"杕":{"expl":"樹皃。从木大聲。《詩》曰：“有杕之杜。”","rad":"木","fq":"特計切","vol":"06","py":"dì","duan":[{"e":"樹皃。","n":"樹當作特。字之誤也。𡉈顏黃門時已誤矣。唐風。有杕之杜。毛曰。杕、特皃。許所本也。引伸爲舟舵。高注淮南曰。杕、舟尾也。柁舵皆俗字。"}]},"𣗸":{"expl":"木葉陊也。从木㲋聲。讀若薄。","rad":"木","fq":"他各切","vol":"06","py":"tuò","duan":[{"e":"木葉陊也。","n":"陊、落也。小徐云此亦蘀字。按此與蘀義同。音不必同。相爲轉注。非一字也。言部訬讀若㲋。此𣔵讀如薄。然則㲋之𡉈二部或五部、難定也。玉篇云。𣔵同欃。則合㲋聲毚聲爲一。其誤甚矣。"}]},"格":{"expl":"木長皃。从木各聲。","rad":"木","fq":"古百切","vol":"06","py":"ɡé","duan":[{"e":"木長皃。","n":"以木長別於上文長木者。長木言木之美。木長言長之美也。木長皃者、格之本義。引伸之長必有所至。故釋詁曰。格、至也。抑詩傳亦曰。格、至也。凡尙書格于上下、格于藝祖、格于皇天、格于上帝是也。此接於彼曰至。彼接于此則曰來。鄭注大學曰。格、來也。凡尙書格爾衆庶、格汝衆是也。至則有摩杚之義焉。如云格君心之非是也。或借假爲之。如雲漢傳曰假至也、尙書格字今文尙書皆作假是也。有借格爲庋閣字者。亦有借格爲扞垎字者。"}]},"槷":{"expl":"木相摩也。从木埶聲。","rad":"木","fq":"魚祭切","vol":"06","py":"yì","duan":[{"e":"木相摩也。","n":"釋木曰。木相磨槸。按大雅。作之屛之。其菑其翳。脩之平之。其灌其栵。爾雅。立死、甾蔽者、翳。木相磨、槸除灌木叢木已見於上。則槸卽栵也。以文法論。栵必非木名。毛云。栵、栭也。栭謂之而小木相迫切。與爾雅義無不合也。栭爲小木。如鮞爲魚子。"}]},"枯":{"expl":"槀也。从木古聲。《夏書》曰：“唯箘輅枯。”木名也。","rad":"木","fq":"苦孤切","vol":"06","py":"kū","duan":[{"e":"槁也。從木。古聲。","n":"苦孤切。五部。"}]},"槀":{"expl":"木枯也。从木高聲。","rad":"木","fq":"苦浩切","vol":"06","py":"ɡǎo","duan":[{"e":"木枯也。","n":"枯槀、禾稾字古皆高𡉈上。今字高𡉈右。非也。凡潤其枯槀曰槀。如慰其勞苦曰勞。以膏潤物曰膏。尙書槀飫。周禮槀人。小行人若國師役則令槀禬之。義皆如是。鄭司農以漢字通之。於槀人曰。槀讀爲犒師之犒。主宂食者、故謂之犒。於小行人曰。槀當爲犒。謂犒師也。葢漢時盛行犒字。故大鄭以今字易古字。此漢人釋經之法也。左傳、國語皆有犒字。左傳服注曰。以師枯槀。故饋之飲食。韋注國語曰。犒、勞也。計左、國皆本作槀。今本作犒者。亦漢人所改。如牛人。軍事共其犒牛。此必後鄭從大鄭所易也。小行人經文從大鄭易爲犒、而注之曰。故書犒作槀。今本則譌舛難讀矣。何注公羊曰。牛酒曰犒。高注淮南曰。酒肉曰餉。牛羊曰犒。漢㡿彰長𥓓又作勞𨢓。許不錄"}]},"蕕":{"expl":"水邊艸也。从艸猶聲。","rad":"艸","fq":"以周切","vol":"01","py":"yóu","duan":[{"e":"水邊艸也。","n":"漢書子虛賦音義曰。軒于、蕕艸也。生水中。楊州有之。釋艸。莤、蔓于。莤卽蕕。蔓于卽軒于。"}]},"樸":{"expl":"木素也。从木菐聲。","rad":"木","fq":"匹角切","vol":"06","py":"pǔ","duan":[{"e":"木素也。","n":"素猶質也。以木爲質。未雕飾如瓦器之坯然。士喪禮、周禮槀人皆云。獻素獻成。注云。形法定爲素、飾治畢爲成是也。引伸爲凡物之偁。如石部云。磺銅𨮯樸是也。作璞者、俗字也。又引伸爲不奢之偁。凡云儉樸是也。漢書。以敦朴爲天下先。假朴爲樸也。"}]},"楨":{"expl":"剛木也。从木貞聲。上郡有楨林縣。","rad":"木","fq":"陟盈切","vol":"06","py":"zhēn","duan":[{"e":"剛木也。","n":"此謂木之剛者曰楨。非木名也。吳都賦之楨、廣韵之女楨、則爲木名。"}]},"柔":{"expl":"木曲直也。从木矛聲。","rad":"木","fq":"耳由切","vol":"06","py":"róu","duan":[{"e":"木曲直也。","n":"洪範曰。木曰曲直。凡木曲者可直。直者可曲曰柔。考工記多言揉。許作煣。云屈申木也。必木有可曲可直之性。而後以火屈之。申之。此柔與煣之分別次弟也。詩荏染柔木。則謂生木。柔之引伸爲凡耎弱之偁、凡撫安之偁。"}]},"柝":{"expl":"判也。从木㡿聲。《易》曰：“重門擊𣔳。”","rad":"木","fq":"他各切","vol":"06","py":"tuò","duan":[{"e":"判也。","n":"土裂曰𡍩。木判曰𣔳。二字今可用。今人从手作拆。甚無謂也。自專以𣔳爲擊𣔳字。而𣔳之本義廢矣。"}]},"朸":{"expl":"木之理也。从木力聲。平原有朸縣。","rad":"木","fq":"盧則切","vol":"06","py":"lè","duan":[{"e":"木之理也。","n":"考工記曰。陽木稹理而堅。陰木疏理而柔。毛詩傳曰。析薪必隨其理。毛詩如矢斯棘。韓詩棘作朸、毛曰。棘、棱廉也。韓曰。朸、隅也。學者皆不解。及觀抑詩維德之隅。毛曰。隅、廉也。箋申之云。如宮室之制。內有繩直。則外有廉隅然後知斯干詩謂如矢之下直、而外有廉隅也。韓朸爲正字。毛棘爲假借字。如矢之直、則得其理而廉隅整飭矣。毛、韓辭異而意一也。"}]},"材":{"expl":"木梃也。从木才聲。","rad":"木","fq":"昨哉切","vol":"06","py":"cái","duan":[{"e":"木梃也。","n":"梃、一枚也。材謂可用也。論語。無所取材。鄭曰。言無所取桴材也。貨殖傳曰。山居千章之材。服虔云。章、方也。孟康云。言任方章者千枚。按漢人曰章。唐人曰橦、音鍾。材方三尺五寸爲一橦。材引伸之義凡可用之具皆曰材。"}]},"柴":{"expl":"小木散材。从木此聲。","rad":"木","fq":"士佳切","vol":"06","py":"chái","duan":[{"e":"小木散材。","n":"月令。乃命四監。收秩薪柴以供郊廟及百祀之薪燎注云。大者可析謂之薪。小者合束謂之柴。薪施炊爨。柴以給燎。按尞、祡祭天也。燔柴曰祡。毛詩車攻假柴爲積字。"}]},"榑":{"expl":"榑桑，神木，日所出也。从木尃聲。","rad":"木","fq":"防無切","vol":"06","py":"fú","duan":[{"e":"榑桑、神木日所出也。","n":"叒下曰。日初出東方湯谷所登榑桑、叒木也。然則榑桑卽叒木也。東下曰。從日在木中。杲下曰。從日在木上。皆謂榑木也。淮南高注亦曰。榑桑、日所出也。"}]},"杲":{"expl":"明也。从日在木上。","rad":"木","fq":"古老切","vol":"06","py":"ɡǎo","duan":[{"e":"朙也。","n":"衞風。杲杲出日。毛曰。杲杲然日復出矣。"}]},"杳":{"expl":"冥也。从日在木下。","rad":"木","fq":"烏皎切","vol":"06","py":"yǎo","duan":[{"e":"冥也。","n":"冥、窈也。𦱤爲日月冥。杳則全冥矣。由𦱤而行地下、而至於榑桑之下也。引伸爲凡不見之偁。"}]},"祖":{"expl":"始廟也。从示且聲。","rad":"示","fq":"則古切","vol":"01","py":"zǔ","duan":[{"e":"始廟也。","n":"始兼兩義。新廟爲始。遠廟亦爲始。故祔祪皆曰祖也。釋詁曰。祖、始也。詩毛傳曰。祖、爲也。皆引伸之義。如初爲衣始、引伸爲凡始也。"}]},"荌":{"expl":"艸也。从艸安聲。","rad":"艸","fq":"烏旰切","vol":"01","py":"àn","duan":[{"e":"艸也。从艸。安聲。","n":"烏旰切。十四部。"}]},"㮝":{"expl":"角械也。从木卻聲。一曰木下白也。","rad":"木","fq":"其逆切","vol":"06","py":"hé","duan":[{"e":"角械也。","n":"角葢角鬭之角。"}]},"栽":{"expl":"築牆長版也。从木𢦔聲。《春秋傳》曰：“楚圍蔡，里而𣒭。”","rad":"木","fq":"昨代切","vol":"06","py":"zài","duan":[{"e":"築牆長版也。","n":"古築牆先引繩營其廣輪方制之正。詩曰俾立室家、其繩則直是也。繩直則豎楨榦。題曰楨、植於兩頭之長杙也。旁曰榦。植於兩邊之長杙也。植之謂之栽。栽之言立也。而後橫施版於兩邊榦內。以繩束榦。實土。用築築之。一版竣。則層絫而上。詩曰縮版以載、捄之仍仍、度之薨薨、築之登登是也。然則栽者、合楨榦與版而言。許云築牆長版爲栽者、以版該楨榦也。中庸。故栽者培之。鄭云。栽猶殖也。今時人名艸木之殖曰栽。築牆立版亦曰栽鄭同許說。長版者、五經異義曰。戴禮及韓詩說。八尺爲版。五版爲堵。五堵爲雉。版廣二尺。積高五版爲一丈。五堵爲雉。雉長四丈。古周禮及左氏說。一丈爲版。版廣二尺。五版爲堵。一堵之牆長丈。高丈。三堵爲雉。一雉之牆長"}]},"築":{"expl":"擣也。从木筑聲。","rad":"木","fq":"陟玉切","vol":"06","py":"zhù","duan":[{"e":"所㠯擣也。","n":"所㠯二字今補。此蒙上築牆言所用築者。謂器也。其器名築。因之人用之亦曰築。手部曰。擣築也是也。築者、直舂之器。鄭注周禮引司馬法云。輦一斧。一斤、一鑿、一梩、一鉏。周輦加二版二築。正義曰。築者、築杵也。"}]},"榦":{"expl":"築牆耑木也。从木倝聲。","rad":"木","fq":"古案切","vol":"06","py":"ɡàn","duan":[{"e":"築牆耑木也。","n":"耑謂兩頭也。假令版長丈。則牆長丈。其兩頭所植木曰榦。釋詁曰。楨、榦也。舍人曰。楨、正也。築牆所立兩木也。榦所以當嗇之兩邊鄣土者也。粊誓。注曰。題曰楨。㫄曰榦。正義云。題曰植、謂當牆兩端者。旁曰榦、謂在牆兩邊者也。然則舊說皆謂楨爲兩耑木。榦爲夾版兩邊木。許不尒者。舊說析言之。爾雅與許皆渾言之也。大雅傳亦以榦釋楨。許於楨下渾云剛木。"}]},"檥":{"expl":"榦也。从木義聲。","rad":"木","fq":"魚羈切","vol":"06","py":"yǐ","duan":[{"e":"榦也。","n":"釋詁曰。楨翰儀榦也。許所據爾雅作檥也。人儀表曰榦。木所立表亦爲榦。其義一也。史記。烏江亭長檥船待。檥船者、若今小船。兩頭植㰏爲系也。"}]},"構":{"expl":"蓋也。从木冓聲。杜林以爲椽桷字。","rad":"木","fq":"古后切","vol":"06","py":"ɡòu","duan":[{"e":"葢也。","n":"此與冓音同義近。冓、交積材也。凡覆葢必交積材。"}]},"模":{"expl":"法也。从木莫聲。讀若嫫母之嫫。","rad":"木","fq":"莫胡切","vol":"06","py":"mú","duan":[{"e":"法也。","n":"以木曰橫。以金曰鎔。以土曰𡌁。以竹曰笵。皆法也。漢書亦作橅。"}]},"桴":{"expl":"棟名。从木孚聲。","rad":"木","fq":"附柔切","vol":"06","py":"fú","duan":[{"e":"睂棟也。","n":"也各本作名。今正。釋宮。棟謂之桴。許云睂棟者。爾雅渾言之。許析言之。鄭注鄉射禮記曰。五架之屋。正中曰棟。次曰楣。前曰庪。注鄉飲酒禮曰。楣、前梁也。許之眉棟卽禮經之楣也。許厂部之厃卽禮經之庪也。許以屋櫋聯曰楣。則棟前曰睂棟。謂棟之近前若睂者也。豈許所據禮經楣作睂與。張載注靈光殿賦亦云睂梁。"}]},"棟":{"expl":"極也。从木東聲。","rad":"木","fq":"多貢切","vol":"06","py":"dònɡ","duan":[{"e":"極也。","n":"極者、謂屋至高之處。繫辭曰。上棟下宇。五架之屋、正中曰棟。釋名曰。棟、中也。居屋之中。"}]},"極":{"expl":"棟也。从木亟聲。","rad":"木","fq":"渠力切","vol":"06","py":"jí","duan":[{"e":"棟也。","n":"李奇注五行志、薛綜注西京賦皆曰。三輔名梁爲極。按此正名棟爲極耳。今俗語皆呼棟爲梁也。搜神記。漢蔡茂夢坐大殿。極上有禾三穗。主簿郭賀曰。極而有禾。人臣之上祿也。此則似謂梁。按喪大紀注曰。危、棟上也。引伸之義凡至高至遠皆謂之極。"}]},"藄":{"expl":"綦月爾也。从艸綦聲。","rad":"艸","fq":"渠之切","vol":"01","py":"qí","duan":[{"e":"土夫也。","n":"各本作藄月爾也。今依爾雅音義。攷今本釋艸。芏、夫王。郭云。芏艸生海邊。𦸀月爾。郭云。卽紫藄也。似蕨可食。陸德明曰。𦸀字亦作藄。紫藄菜也。說文云藄土夫也。其所據說文。必與爾雅殊異而偁之。不則何容偁也。今本說文恐是據爾雅郭本郭注改者。但許君爾雅之讀今不可知矣。"}]},"柱":{"expl":"楹也。从木主聲。","rad":"木","fq":"直主切","vol":"06","py":"zhù","duan":[{"e":"楹也。","n":"柱之言主也。屋之主也。"}]},"楹":{"expl":"柱也。从木盈聲。《春秋傳》曰：“丹桓宫楹。”","rad":"木","fq":"以成切","vol":"06","py":"yínɡ","duan":[{"e":"柱也。","n":"釋名曰。楹、亭也。亭亭然孤立、旁無所依也。按禮言東楹西楹。非孤立也。自其一言之耳。考工記。葢杠謂之桯。桯卽楹。如欒盈、史記作欒逞。其比也。"}]},"樘":{"expl":"衺柱也。从木堂聲。","rad":"木","fq":"丑庚切","vol":"06","py":"chēnɡ","duan":[{"e":"柱也。","n":"各本柱上有衺字。今𠜂。文𨕖、靈光殿賦、長笛賦李注皆引說文。柱也。長門賦李注引字林。柱也。皆無衺字。惟樘字或作牚、或作撐。皆俗字耳。玉篇云。樘、柱也。亦無衺。葢樘木柱名。如靈光。枝樘杈枒而斜據。枝樘與層櫨曲枅芝栭爲儷。然則訓爲柱無疑也。樘可借爲䟫歫。猶柱可借爲支柱。而支柱遂正釋樘。俗閒謂撐拄必用衺木。遂沾一衺字矣。"}]},"榰":{"expl":"柱砥。古用木，今以石。从木耆聲。《易》：“榰恒凶。”","rad":"木","fq":"章移切","vol":"06","py":"zhī","duan":[{"e":"柱氐也。","n":"氐各本作砥。誤。今正。日部昏下曰。氐者、下也。广部曰。底、一曰下也。氐底古今字。玄應書引作柱下。知本作柱氐矣。今之磉子也。釋言曰。搘、拄也。卽榰柱之譌。磉𡉈柱下而柱可立。因引伸爲凡支拄、拄寒之偁。"}]},"㮞":{"expl":"𣝍櫨也。从木咨聲。","rad":"木","fq":"子結切","vol":"06","py":"jié","duan":[{"e":"欂櫨也。","n":"明堂位注曰。山節、刻欂櫨爲山也。按㮞論語、禮器、明堂位、爾雅舊本皆作節。"}]},"𣝍":{"expl":"壁柱。从木，薄省聲。","rad":"木","fq":"弼𢧢切","vol":"06","py":"bì","duan":[{"e":"壁柱也。","n":"壁柱謂附壁之柱。柱之小者。此與欂櫨之欂各字。篇、韵皆兩存不混。"}]},"櫨":{"expl":"柱上柎也。从木盧聲。伊尹曰：“果之美者，箕山之東，青鳧之所，有櫨橘焉。夏孰也。”一曰宅櫨木，出弘農山也。","rad":"木","fq":"落胡切","vol":"06","py":"lú","duan":[{"e":"欂櫨也。","n":"依全書通例正。"}]},"枅":{"expl":"屋櫨也。从木幵聲。","rad":"木","fq":"古兮切","vol":"06","py":"jī","duan":[{"e":"屋欂櫨也。","n":"按有枅、有曲枅。枅者、蒼頡篇云柱上方木也。曲枅者、廣雅云曲枅謂之欒。薛綜西京賦注云。欒、柱上曲木。兩頭受櫨者。釋名。欒、攣也。其體上曲攣拳然也。然則曲枅謂之欒。欒以承欂櫨。故靈光殿賦曰。層櫨磥垝以岌峩。曲枅要紹而環句。二者竝言。景福殿賦亦櫨欒對舉。魏都賦亦云。欒櫨曡施。皆可證曲枅與枅爲二事。"}]},"栵":{"expl":"栭也。从木𠛱聲。《詩》曰：“其灌其𣔜。”","rad":"木","fq":"良辥切","vol":"06","py":"liè","duan":[{"e":"栭也。","n":"大雅。其灌其栵。毛曰。栵、栭也。栭與灌爲類。非木名。謂小木叢生者。如魚子名鯤鮞也。許云栵栭也者、字之本義。曲枅加於柱。枅加於曲枅。栭又加於枅。以次而小。故名之栭。毛取小木之義。故亦曰栵、栭也。"}]},"栭":{"expl":"屋枅上標。从木而聲。《爾雅》曰：“栭謂之㮞。”","rad":"木","fq":"如之切","vol":"06","py":"ér","duan":[{"e":"屋枅上標也。","n":"標、靈光殿賦、王命論二注皆作梁。今按作標爲長。標者、表也。高也。辥注西京賦曰。栭斗也。張載注靈光曰。栭方、小木爲之。栭在枅之上。枅者、柱上方木。斗又小於枅。亦方木也。然後乃抗梁焉。靈光層櫨曲枅之下曰。芝栭攢羅。景福蘭栭積重之下曰。櫼櫨各落。此可證栭與枅非一物。釋宮云。栭謂之㮞。合二事渾言之。許則析言之也。諸家襲爾雅者皆少分別。"}]},"莃":{"expl":"兎葵也。从艸，稀省聲。","rad":"艸","fq":"香衣切","vol":"01","py":"xī","duan":[{"e":"兔葵也。","n":"見釋艸。"}]},"檼":{"expl":"棼也。从木㥯聲。","rad":"木","fq":"於靳切","vol":"06","py":"yìn","duan":[{"e":"棼也。","n":"林部曰。棼、複屋棟也。注詳彼矣。釋名及郭璞謂棟爲檼。非也。"}]},"橑":{"expl":"椽也。从木𤋯聲。","rad":"木","fq":"盧浩切","vol":"06","py":"lǎo","duan":[{"e":"椽也。","n":"九歌曰。桂棟兮蘭橑。王云。以木蘭爲榱也。按西都賦。列棼橑以布翼。下又云。裁金璧以飾當。西京賦。結棼橑以相接。下又云。飾華榱與璧當。魏都賦。棼橑複結。下又云。朱桷森布而支離。橑必與棼連言。而別於榱桷。則榱桷爲屋椽。橑爲複屋之椽可知。簷𩅸在複屋。故廣韵曰。屋橑、簷前木。此檼橑二篆相屬亦此意也。當是本作橑、檼椽也。謂屬於檼之椽。"}]},"桷":{"expl":"榱也。椽方曰桷。从木角聲。《春秋傳》曰：“刻桓宫之桷。”","rad":"木","fq":"古岳切","vol":"06","py":"jué","duan":[{"e":"榱也。","n":"榱也者、渾言之。釋宮云桷謂之榱是也。下文椽方曰桷者、析言之。"}]},"椽":{"expl":"榱也。从木彖聲。","rad":"木","fq":"直專切","vol":"06","py":"chuán","duan":[{"e":"榱也。","n":"左傳。以大宫之椽歸爲盧門之椽。釋名曰。椽、傳也。相傳次而布列也。"}]},"榱":{"expl":"秦名爲屋椽，周謂之榱，齊魯謂之桷。从木衰聲。","rad":"木","fq":"所追切","vol":"06","py":"cuī","duan":[{"e":"椽也。","n":"二字依韵會補。"}]},"楣":{"expl":"秦名屋𣝼聯也。齊謂之檐，楚謂之梠。从木眉聲。","rad":"木","fq":"武悲切","vol":"06","py":"méi","duan":[{"e":"秦名屋𣝼䏈也。齊謂之厃。楚謂之梠。","n":"秦名屋櫋聯也者、秦人名屋櫋䏈曰楣也。與秦名屋椽曰榱同解。李善注文𨕖引說文曰。㮰梠、秦名屋櫋聯。失其義矣。齊謂之厃。各木厃作檐。今依厂部厃下正。厃、屋梠也。秦謂之楣。齊謂之厃。禮經正中曰棟。棟前曰楣又爾雅楣謂之梁。皆非許所謂楣者。"}]},"梠":{"expl":"楣也。从木呂聲。","rad":"木","fq":"力舉切","vol":"06","py":"lǚ","duan":[{"e":"楣也。","n":"釋名曰。梠、旅也。連旅之也。士喪禮注曰。宇、梠也。宀部曰。宇、屋邊也。"}]},"㮰":{"expl":"梠也。从木𣬉聲。讀若枇杷之枇。","rad":"木","fq":"房脂切","vol":"06","py":"pí","duan":[{"e":"梠也。","n":"㮰之言比敘也。西京賦曰。三階重軒。鏤檻文㮰。按此文㮰、謂軒檻之飾與屋梠相似者。"}]},"𣝼":{"expl":"屋𣝼聯也。从木，𨘢省聲。","rad":"木","fq":"武延切","vol":"06","py":"mián","duan":[{"e":"屋櫋䏈也。","n":"釋名曰。梠或謂之櫋。櫋、緜也。緜連榱頭使齊平也。上入曰爵頭。形似爵頭也。按郭云雀梠卽爵頭也。九歌曰。擘蕙櫋兮旣張。"}]},"檐":{"expl":"㮰也。从木詹聲。","rad":"木","fq":"余廉切","vol":"06","py":"yán","duan":[{"e":"㮰也。","n":"檐之言隒也。在屋邊也。明堂位重檐注云。重檐、重承壁材也。姚氏鼐云。漢時名檐爲承壁材。以其直垂而下如壁。"}]},"𦿏":{"expl":"灌渝。从艸夢聲。讀若萌。","rad":"艸","fq":"莫中切","vol":"01","py":"ménɡ","duan":[{"e":"灌渝。","n":"今釋艸。葭蘆菼薍其萌虇。郭云。今江東呼蘆筍爲虇。音繾綣。下文蕍芛葟華榮。郭別爲一條。許君所據爾雅𦿏灌渝。句字皆與今本大乖。今不可得其讀矣。"}]},"橝":{"expl":"屋梠前也。从木覃聲。一曰蠶槌。","rad":"木","fq":"徒含切","vol":"06","py":"tán","duan":[{"e":"屋梠前也。","n":"梠與𩅸之閒曰橝。"}]},"樀":{"expl":"戶樀也。从木啻聲。《爾雅》曰：“檐謂之樀。”讀若滴。","rad":"木","fq":"都歴切","vol":"06","py":"dí","duan":[{"e":"戸樀也。","n":"按戸樀謂門檐也。郭注爾雅及篇、韵皆云屋梠。則不專謂門。"}]},"植":{"expl":"戶植也。从木直聲。","rad":"木","fq":"常職切","vol":"06","py":"zhí","duan":[{"e":"戸植也。","n":"釋宮曰。植謂之傳。傳謂之突。郭曰。持戸鎖植也。見埤蒼。邵氏晉涵曰。墨子。爭門關決植。淮南云。縣䏈房植。高曰。植、戸植也。植當爲直立之木。徐鍇以爲横鍵。非也。按今豎直木而以鐵了鳥關之。可以加鎖。故曰持鎖植。植之引伸爲凡植物、植立之植。"}]},"樞":{"expl":"戶樞也。从木區聲。","rad":"木","fq":"昌朱切","vol":"06","py":"shū","duan":[{"e":"戸樞也。","n":"戸所以轉動開閉之樞機也。釋宮曰。樞謂之椳。"}]},"槏":{"expl":"戶也。从木兼聲。","rad":"木","fq":"苦減切","vol":"06","py":"qiǎn","duan":[{"e":"戸也。","n":"通俗文云。小戸曰㦿。口減反。集韵。槏㦿？三同。口減切。戸也。按許㦿爲古文戸。不爲槏。"}]},"樓":{"expl":"重屋也。从木婁聲。","rad":"木","fq":"洛矦切","vol":"06","py":"lóu","duan":[{"e":"重屋也。","n":"重屋與複屋不同。複屋不可居。重屋可居。考工記之重屋、謂複屋也。釋名曰。樓謂牖戸之閒諸射孔樓樓然也。樓樓當作婁婁。女部曰。婁、空也。囧下曰。窗牖麗廔開明。"}]},"㰍":{"expl":"房室之疏也。从木龍聲。","rad":"木","fq":"盧紅切","vol":"06","py":"lónɡ","duan":[{"e":"房室之疏也。","n":"按疏當作？。疏者、通也。？者、門戸疏窗也。房室之窗牖曰㰍。謂刻畫玲瓏也。"}]},"楯":{"expl":"闌楯也。从木盾聲。","rad":"木","fq":"食允切","vol":"06","py":"shǔn","duan":[{"e":"闌檻也。","n":"闌、門遮也。檻、櫳也。此云闌檻者、謂凡遮闌之檻。今之闌于是也。王逸楚辭注曰。檻、楯也。從曰檻。横曰楯。古亦用爲盾字。"}]},"櫺":{"expl":"楯閒子也。从木霝聲。","rad":"木","fq":"郎丁切","vol":"06","py":"línɡ","duan":[{"e":"楯閒子也。","n":"闌楯爲方格。又於其横直交處爲圜子。如綺文瓏玲。故曰櫺。左傳車曰怱靈。亦其意也。文𨕖注作窗閒子。"}]},"杗":{"expl":"棟也。从木亡聲。《爾雅》曰：“杗𢊺謂之梁。”","rad":"木","fq":"武方切","vol":"06","py":"mánɡ","duan":[{"e":"棟也。從木。亡聲。","n":"武方切。十部。"}]},"蕧":{"expl":"盜庚也。从艸復聲。","rad":"艸","fq":"房六切","vol":"01","py":"fù","duan":[{"e":"盜庚也。","n":"見釋艸。"}]},"梀":{"expl":"短椽也。从木束聲。","rad":"木","fq":"丑録切","vol":"06","py":"cù","duan":[{"e":"短椽也。","n":"此當與桷椽榱爲類。而廁此者、亦以補前也。廣雅。梀、椽也。"}]},"杇":{"expl":"所以涂也。秦謂之杇，關東謂之槾。从木亏聲。","rad":"木","fq":"哀都切","vol":"06","py":"wū","duan":[{"e":"所㠯涂也。","n":"涂塗古今字。涂者、飾牆也。土部曰。㙙、涂也。？、仰涂也。墀、涂地也。論語曰。糞土之牆。不可杇也。"}]},"槾":{"expl":"杇也。从木曼聲。","rad":"木","fq":"母官切","vol":"06","py":"màn","duan":[{"e":"杇也。","n":"釋宮曰。鏝謂之杇。釋文云。鏝本或作槾。按孟子作墁。"}]},"椳":{"expl":"門樞謂之椳。从木畏聲。","rad":"木","fq":"烏恢切","vol":"06","py":"wēi","duan":[{"e":"門樞謂之椳。","n":"見釋宮。謂樞所檃謂之椳也。椳猶淵也。宛中爲樞所居也。弓淵、大射儀作隈。考工記作畏。亦此意。與上文戸樞義互相足。其文則以戸與門區別之。實則戸與門制同。"}]},"𣔺":{"expl":"門樞之横梁。从木冒聲。","rad":"木","fq":"莫報切","vol":"06","py":"mào","duan":[{"e":"門樞之横梁。","n":"釋宮曰。𣔺謂之梁。郭曰。門戸上横梁。今本爾雅作楣。字之誤也。釋文。楣、亡悲反。或作𣔺。亡報反。埤蒼云。梁也。呂伯雍云。門戸之横梁也。說文曰。楣、秦名屋櫋聯也。陸引埤蒼、字林以證𣔺。引說文以證楣。謂𣔺楣義不同。今本脫誤不可讀。陸於𣔺不引說文者。隨繙閱所得也。椳言樞之下。𣔺言樞之上。門上爲横梁。鑿孔以貫樞。今江浙所謂門龍也。"}]},"梱":{"expl":"門橛也。从木困聲。","rad":"木","fq":"苦本切","vol":"06","py":"kǔn","duan":[{"e":"門橜也。","n":"橜下云。一曰門梱也。門部曰。闑、門梱也。然則門梱、門橜、闑、一物三名矣。謂當門中設木也。釋宮。橜謂之闑。廣雅。橜機闑𣏔也。𣏔同梱。史記孫叔敖傳曰。楚俗好庳車。王欲下令使高之。相敎閭里使高其梱。居半歲。民悉自高其車。史記張釋之馮唐傳曰。閫以內者、寡人制之。閫以外者、將軍制之。漢書閫作闑。韋昭曰。此郭門之梱也。門中橜曰梱。鄭注曲禮曰。梱、門限也。與許不合。"}]},"𣕋":{"expl":"限也。从木㞕聲。","rad":"木","fq":"先結切","vol":"06","py":"xiè","duan":[{"e":"限也。","n":"𨸏部限下云。一曰門？也。門部云。閾、門？也。亦一物三名矣。釋宮。柣謂之閾。柣、郭千結反。柣卽？字也。漢人多作切。考工記注云。眼讀如限切之限。限切、謂門限也。漢書外戚傳。切皆銅沓。黃金塗。師古曰。切、門限也。千結反。按西都賦。玄墀釦切。釦切卽漢書之切。皆銅沓黃金塗也。文𨕖切作砌。誤。西京賦云金戺。卽釦切也。西京賦又云。設切厓隒。卽西都賦之仍增厓而衡閾也。廣雅。柣戺橉切也。切今本亦譌砌。橉見淮南書。匡謬正俗云。俗謂門限爲門蒨者。爾雅。柣謂之閾。郭音切。今言門蒨是柣聲之轉耳。字當爲柣而作切音。玉裁謂。柣當爲？而作切音。如多方大淫泆有辭。泆又作佾。馬本作㞕。是其比也。"}]},"柤":{"expl":"木閑。从木且聲。","rad":"木","fq":"側加切","vol":"06","py":"zhā","duan":[{"e":"木閑也。","n":"門部曰。閑、闌也。廣雅曰。柤樘柱距也。距當作歫、止也。"}]},"槍":{"expl":"歫也。从木倉聲。一曰槍，欀也。","rad":"木","fq":"七羊切","vol":"06","py":"qiānɡ","duan":[{"e":"歫也。","n":"止部曰。歫、止也。一曰槍也。按槍有相迎鬬爭之意。通俗文曰。剡木傷盜曰槍。今俗作鎗。"}]},"楗":{"expl":"限門也。从木建聲。","rad":"木","fq":"其獻切","vol":"06","py":"jiàn","duan":[{"e":"歫門也。","n":"歫各本作限。非。今依南都賦注所引正。老子釋文亦作距門也。月令。脩鍵閉。愼管籥。注曰。鍵牡、閉牝也。管籥、搏鍵器也。周禮司門。掌授管鍵以啓閉國門。先鄭云。管謂籥也。鍵謂牡。按楗閉卽今木鎖也。諸經多借鍵爲楗。而周禮司門作管蹇。先鄭云。蹇讀爲鍵。今本乃互易蹇鍵字。"}]},"苓":{"expl":"卷耳也。从艸令聲。","rad":"艸","fq":"郎丁切","vol":"01","py":"línɡ","duan":[{"e":"苓耳、","n":"逗。二字各本脫。今補。說見苦字下。"}]},"櫼":{"expl":"楔也。从木韱聲。","rad":"木","fq":"子廉切","vol":"06","py":"jiān","duan":[{"e":"楔也。","n":"玄應書曰。說文櫼、子林切。今江南言櫼。中國言㞚。楔、通語也。㞚、側洽切。按子林切葢本說文音隱。今江浙語正作知林切。不作子林也。木工於鑿枘相入處有不固。則斫木札楔入固之。謂之櫼。櫼亦作鉆。戰國策。蘇秦謂趙王曰。柱山有兩木。一葢呼侣。一葢哭。問其故。曰吾苦夫匠人且以繩墨案規矩刻鏤我。一曰此非吾所苦也。是故吾事也。吾所苦夫鐵鉆然自入而出夫人者。今臣使於秦而三日不見。無有爲臣鐵鉆者乎。鉆自入而出、謂以大鐵鉆釘入大樹一邊。旣析破。乃取樹之一邊爲用。夫人者、言此人冣所苦也。今四川建昌山中取桫方。皆以楔釘入。取陽面一塊。而樹尚卓立。蘇秦以此喻離閒之人也。蘇秦謂鐵器。許謂木札。其用正同。周禮注飛鉆、當作此解。"}]},"楔":{"expl":"櫼也。从木契聲。","rad":"木","fq":"先結切","vol":"06","py":"xiè","duan":[{"e":"櫼也。","n":"今俗語曰楔子。先結切。考工記曰。牙得則無槷而固。注曰。鄭司農云。槷、榝也。蜀人言榝曰槷。玄謂槷讀如𣵀。從木、𤍽省聲。按槷榝皆假借字。榝卽楔之假借也。釋木。楔、荆桃。爲木名。南都、蜀都二賦皆有楔。"}]},"柵":{"expl":"編樹木也。从木从冊，冊亦聲。","rad":"木","fq":"楚革切","vol":"06","py":"zhà","duan":[{"e":"編豎木也。","n":"豎各本作樹。今依篇、韵正。臤部曰。豎、堅立也。通俗文曰。木垣曰柵。"}]},"杝":{"expl":"落也。从木也聲。讀若他。","rad":"木","fq":"池尒切","vol":"06","py":"lí","duan":[{"e":"落也。","n":"玄應書謂杝㰚籬三字同。引通俗文。柴垣曰杝、木垣曰柵。按釋名亦云。籬、離也。以柴竹作。疏離離也。柵、磧也。以木作之。上平磧然也。皆杝柵類舉。落廣雅作？。廣韵引音碰作？。齊民要術引仲長子曰。柂落不完。垣牆不牢。掃除不淨。笞之可也。施者杝之誤。小雅。析薪杝矣。傳曰。析薪者必隨其理。謂隨木理之迆衺而析之也。假杝爲迆也。凡笆籬多衺織之。故其義相通。"}]},"𣟄":{"expl":"夜行所擊者。从木橐聲。《易》曰：“重門擊𣟄。”","rad":"木","fq":"他各切","vol":"06","py":"tuò","duan":[{"e":"行夜所擊木。","n":"行夜各本譌夜行、木作者。今依衘覽正。行、去聲。巡也。周禮宮正。夕擊？而比之。注云。莫行夜以比直宿者。俢閭氏。比國中宿互𣝔者。先鄭云。𣝔、謂行夜擊𣝔。九家易曰。？者、兩木相擊以行夜也。孟子注云。？、行夜所擊木也。左傳。賓將掫。注云。掫、行夜也。"}]},"桓":{"expl":"亭郵表也。从木亘聲。","rad":"木","fq":"胡官切","vol":"06","py":"huán","duan":[{"e":"亭郵表也。","n":"檀弓注曰。四植謂之桓。按二植亦謂之桓。一柱上四出亦謂之桓。漢書。瘞寺門桓東。如淳曰。舊亭傳於四角面百步。築土四方。有屋。屋上有柱出高丈餘。有大板貫柱四出。名曰桓表。縣所治夾兩邊各一桓。陳宋之俗言桓聲如和。今猶謂之和表。師古曰。卽華表也。孝文紀。誹謗之木。服䖍曰。堯作之。橋梁交午柱。崔浩以爲木貫柱四出名桓。"}]},"楃":{"expl":"木帳也。从木屋聲。","rad":"木","fq":"於角切","vol":"06","py":"wò","duan":[{"e":"木帳也。","n":"周禮巾車翟車有楃。字從木。釋文及各木從手。非也。釋文云。握、劉音屋。賈馬皆作幄。攷幕人注曰。四合象宫室曰幄。許書無幄有楃。楃葢出巾車職。今本周禮轉寫誤耳。鄭云。有楃則此無葢。謂上四車皆有容有葢。翟車以楃當容。不云有葢也。釋名云。幄、屋也。以帛衣版施之。形如屋也。故許曰木帳。"}]},"橦":{"expl":"帳極也。从木童聲。","rad":"木","fq":"宅江切","vol":"06","py":"chuánɡ","duan":[{"e":"帳極也。","n":"極、棟也。帳屋高処也。宋本、葉鈔本、小徐本作帳柱。按西京賦。都盧尋橦。謂植者也。"}]},"杠":{"expl":"牀前橫木也。从木工聲。","rad":"木","fq":"古雙切","vol":"06","py":"ɡānɡ","duan":[{"e":"牀前横木也。","n":"方言曰。牀其杠、北燕朝鮮之閒謂之樹。自關而西秦晉之閒謂之杠。南楚之閒謂之趙。東齊海岱之閒謂之𣘘。按廣韵作牀前横。無木字。然則横讀古曠反。孟子徒杠。其引伸之義也。爾雅。素錦韜杠。丨部曰。？、旌旗杠兒。則謂直者也。"}]},"桯":{"expl":"牀前几。从木呈聲。","rad":"木","fq":"他丁切","vol":"06","py":"tīnɡ","duan":[{"e":"牀前几。","n":"方言曰。榻前几。江沔之閒曰桯。趙魏之閒謂之椸。按古者坐於牀而隱於几。孟子隱几而臥、內則少者執牀與坐、御者舉几是也。此牀前之几、與席前之几不同。謂之桯者、言其平也。考工記葢桯、則謂直杠。"}]},"𧆐":{"expl":"艸也。从艸𥫔聲。一曰薏苢。","rad":"艸","fq":"古送切","vol":"01","py":"ɡònɡ","duan":[{"e":"艸也。从艸。𥫔聲。","n":"古送切。又古禫切。古音在七八部。轉入九部。"}]},"桱":{"expl":"桱桯也，東方謂之蕩。从木坙聲。","rad":"木","fq":"古零切","vol":"06","py":"jīnɡ","duan":[{"e":"桱、","n":"此複舉字之未刪者。"}]},"牀":{"expl":"安身之坐者。从木爿聲。","rad":"木","fq":"仕莊切","vol":"06","py":"chuánɡ","duan":[{"e":"安身之几坐也。","n":"鉉本作安身之坐者五字。非是。牀之制略同几而庳於几。可坐。故曰安身之几坐。牀制同几。故有足有桄。牀可坐。故尻下曰。処也、從尸得几而止。引孝經仲尼凥而釋之曰。謂閒居如此。按得几而止者、謂得牀而止也。仲尼凥者、謂坐於牀也。上文曰。凭、依几也。乃謂手所馮之几。漢管寜常坐一木榻。積五十餘年未嘗箕股。其榻上當膝處皆穿。此皆古人坐於牀、而又不似今人垂足而坐之證也。牀亦可臥。古人之臥、隱几而已。牀前有几。孟子隱几而臥是也。孟子曰。舜在牀琴。葢尚書佚篇語也。而古坐於牀可見。琴必在几。則牀前有几亦可見。然則古人之臥無横陳者乎。曰有之。弟子職曰。先生將息。弟子皆起。敬奉枕席。問疋何止。內則曰。父母舅姑將衽。長者奉席"}]},"枕":{"expl":"臥所薦首者。从木冘聲。","rad":"木","fq":"章衽切","vol":"06","py":"zhěn","duan":[{"e":"臥所㠯薦首者。","n":"㠯字今補。警枕曰熲。見少儀。"}]},"楲":{"expl":"楲窬，褻器也。从木威聲。","rad":"木","fq":"於非切","vol":"06","py":"wēi","duan":[{"e":"楲窬、","n":"逗。"}]},"櫝":{"expl":"匱也。从木賣聲。一曰木名。又曰：大梡也。","rad":"木","fq":"徒谷切","vol":"06","py":"dú","duan":[{"e":"匱也。","n":"此與匚部匵音義皆同。匱、匣也。論語。韞匵而藏諸、作匵。龜玉毁於櫝中、作櫝。"}]},"櫛":{"expl":"梳比之總名也。从木節聲。","rad":"木","fq":"阻瑟切","vol":"06","py":"zhì","duan":[{"e":"梳比之總名也。","n":"比讀若毗。疏者爲梳。密者爲比。釋名曰。梳言其齒疏也。數言比。比於梳其齒差數也。比言細相比也。按比之尢細者曰䇫。見竹部。"}]},"梳":{"expl":"理髮也。从木，疏省聲。","rad":"木","fq":"所菹切","vol":"06","py":"shū","duan":[{"e":"所㠯理髮也。","n":"所㠯二字今補。器曰梳。用之理髮因亦曰梳。凡字之體用同稱如此。漢書亦作疏。"}]},"㭘":{"expl":"劒柙也。从木合聲。","rad":"木","fq":"胡甲切","vol":"06","py":"ɡé","duan":[{"e":"劒柙也。","n":"柙當作匣。聲之誤也。少儀所謂劒櫝也。廣雅。㭘室郭劒削也。"}]},"槈":{"expl":"薅器也。从木辱聲。","rad":"木","fq":"奴豆切","vol":"06","py":"nòu","duan":[{"e":"薅器也。","n":"蓐部曰。薅、披去田艸也。槈者、所以披去之器也。槈、刃廣六寸。柄長六尺。說詳𦔐下。"}]},"𣚏":{"expl":"㭉，臿也。从木；入，象形；䀠聲。","rad":"木","fq":"舉朱切","vol":"06","py":"xū","duan":[{"e":"㭉臿也。從木","n":"謂柄。"}]},"藑":{"expl":"茅，葍也。一名蕣。从艸夐聲。","rad":"艸","fq":"渠營切","vol":"01","py":"qiónɡ","duan":[{"e":"藑茅、","n":"逗。各本無藑字。此淺人不知其不可刪而刪之。如巂周、燕也。今本刪巂字。其誤正同。今補。"}]},"㭉":{"expl":"兩刃臿也。从木；绂，象形。宋魏曰㭉也。","rad":"木","fq":"互瓜切","vol":"06","py":"huá","duan":[{"e":"㒳刃臿也。","n":"兩刃臿者、謂臿之兩邊有刃者也。臿者、刺土之器。釋器曰。𣂁謂之疀。𣂁鍫、疀臿皆古今字。作臿者、就舂臼之義引伸之。俗作郭衣鍼之鍤。非也。金部曰。銛、鈂、䤥皆臿屬。鐅、河內謂臿頭金也。此云兩刃臿則又與凡臿不同。方言曰。臿、燕之東北朝鮮洌水之閒謂之𣂁。宋魏之閒謂之鏵。或謂之鍏。江淮南楚之閒謂之臿。沅湘之閒謂之畚。趙魏之閒謂之喿。東齊謂之梩。按㭉鏵古今字也。方言渾言之。許析言之耳。高注淮南曰。臿、鏵也。青州謂之鏵。有刃也。三輔謂之？。釋名。鍤、插也。掘地起土也。或曰銷。銷、削也。能有所穿削也。或曰鏵。鏵、刳也。刳地爲坎也。其板曰葉。象木葉也。高、劉皆作鏵。高云有刃。當作有兩刃。奪一字耳。㭉字亦作鋘。吳越"}]},"㭒":{"expl":"臿也。从木㠯聲。一曰徙土纪，齊人語也。","rad":"木","fq":"詳里切","vol":"06","py":"sì","duan":[{"e":"臿也。","n":"周禮注引司馬法曰。輦一斧、一斤、一鑿、一梩。疏云。梩、或解謂臿。或解謂鍬。鍬臿亦不殊。孟子。葢歸反虆梩而掩之。趙曰。虆梩、籠臿之屬。可以取土者也。按虆卽欙之假借字。可以舁土者。梩同㭒。可以臿地揠土者。趙以籠屬釋虆。以臿屬釋梩也。"}]},"枱":{"expl":"耒耑也。从木台聲。","rad":"木","fq":"弋之切","vol":"06","py":"yí","duan":[{"e":"耒耑也。","n":"枱、今經典之耜。耒下曰耕曲木也。此云耒耑也。與京房耜耒下耓也、耒耜上句上也、相合。曲木、考工記所謂上句者二尺有二寸也。耒耑、所謂庛長尺有一寸也。許意上曰耒。下曰枱。皆謂木材。錔於庛之金是曰耕曰？。鄭注周禮則云。耒爲木。枱爲金。故云古者耜一金。兩人倂發之。又云庛讀爲刺。刺、耒下前曲接耜。又注月令。於孟春云耒、耜之上曲也。於季冬云耜、耒之金也。說與許異。鄭本匠人耜廣五寸而云。許則謂記文枱？不分。渾言之。記云耜廣五寸者謂？也。故於耦下易之云耕廣五寸。"}]},"楎":{"expl":"六叉犂。一曰犂上曲木，犂轅。从木軍聲。讀若渾天之渾。","rad":"木","fq":"戶昆切","vol":"06","py":"hún","duan":[{"e":"六㕚𤛿。","n":"㕚各本誤叉、廣韻廿三䰟曰三爪犂曰禈。此謂一犂而三爪也。許云六爪犂者、謂爲三爪犂者二。而二牛竝行。如人耦耕也。一犂一牛。二犂則二牛。共用三人。食貨志所云趙過法用耦犂。二牛三人也。其上爲樓。貯穀下種。故亦名三腳耬。今陜甘人用之。"}]},"櫌":{"expl":"摩田器。从木憂聲。《論語》曰：“櫌而不輟。”","rad":"木","fq":"於求切","vol":"06","py":"yōu","duan":[{"e":"摩田器也。","n":"漢石經論語。櫌不輟。五經文字曰。經典及釋文皆作耰。鄭曰。耰、覆種也。與許合。許以物言。鄭以人用物言。齊語。深耕而疾耰之。以待時雨。韋曰。耰、摩平也。齊民要術曰。耕荒畢。以鐵齒𨫒𨨯再徧杷之。漫擲黍穄。勞亦再徧。按先云再徧杷之。卽國語所謂疾耰待時雨也。後云勞亦再徧。卽鄭所謂覆種也。許云摩田。當兼此二者。賈又曰。春耕尋手勞。秋耕待白背勞。古曰耰。今曰勞。勞郎到切。集韵作橯。若高誘云。櫌、椎也。如淳云。椎、塊椎也。服䖍、孟康云。櫌、鉏柄也。椎塊尚近之。鉏柄之說未可信矣。"}]},"欘":{"expl":"斫也，齊謂之鎡錤。一曰斤柄，性自曲者。从木屬聲。","rad":"木","fq":"陟玉切","vol":"06","py":"zhú","duan":[{"e":"斫也。齊謂之茲箕。","n":"各本作鎡錤。今依爾雅正。其實箕尚誤。當作其耳。斤部曰。斫、擊也。釋器曰。斪斸謂之定。釋文云。斸本或作欘。引說文齊謂之茲箕。一曰斤柄自曲。據陸氏以說文語系之或作欘之下。則說文有欘無斸可知。今本斤部出斪斸二篆。皆云斫也。夫爾雅斪斸本一物。安得二之。且考工記注引爾雅作句欘。又爾雅音義云。斪本或作拘。是則句拘皆訓曲。不爲別一器名也。句欘者、李巡云鉏也。郭璞云鉏屬。葢似鉏而健於鉏。似斤而不以斫木。專以斫田。其首如鉏然。句於矩。故謂句欘也。斤部斪斸二篆、淺人依爾雅俗本增之。今刪。管子曰。美金以鑄戈劒矛？。試諸狗馬。惡金以鑄斤斧鉏夷鋸欘。試諸木土。謂斤斧鋸試諸木者、鉏夷欘試諸土者也。韋曰。夷者所以削艸平地也"}]},"櫡":{"expl":"斫謂之櫡。从木箸聲。","rad":"木","fq":"張略切","vol":"06","py":"zhuó","duan":[{"e":"斫謂之櫡。","n":"見釋器。櫡一作鐯。俗字也。凡斫木之斤、斫地之欘皆謂之櫡。櫡之言箸也。箸直略反。郭云。钁也。金部云。钁、大鉏也。"}]},"杷":{"expl":"收麥器。从木巴聲。","rad":"木","fq":"蒲巴切","vol":"06","py":"pá","duan":[{"e":"收麥器。","n":"方言云。杷、宋魏之閒謂之渠挐。亦謂之渠疏。郭云。無齒爲朳。按耒部云。？、卌㕚也。可以劃麥。河內用之。？亦杷也。杷引伸之義爲引取。與掊捊義略同。"}]},"𣒃":{"expl":"穜樓也。一曰燒麥柃𣒃。从木役聲。","rad":"木","fq":"与辟切","vol":"06","py":"yì","duan":[{"e":"穜樓也。","n":"穜者今之種字。樓者今之耬字。廣韵曰。耬、種具也。今北方謂所以耩者曰耬。耩者、種也。小徐本樓作？。"}]},"柃":{"expl":"木也。从木令聲。","rad":"木","fq":"郎丁切","vol":"06","py":"línɡ","duan":[{"e":"木也。","n":"上林賦張揖注曰。櫧似柃。按云木也、非其次。當作柃？也三字。葢蒙上釋柃字耳。"}]},"䔰":{"expl":"葍也。从艸富聲。","rad":"艸","fq":"方布切","vol":"01","py":"fù","duan":[{"e":"葍也。从艸。富聲。","n":"方布切。古音在一部。布字依宋刻。"}]},"柫":{"expl":"擊禾連枷也。从木弗聲。","rad":"木","fq":"敷勿切","vol":"06","py":"fú","duan":[{"e":"擊禾連枷也。","n":"方言曰。僉、宋魏之間謂之欇殳。或謂之度。音量度。自關而西謂之棓。蒲項反。或謂之柫。音拂。齊楚江淮之閒謂之柍。音悵怏。亦音車鞅。或謂之桲。音勃。齊語。耒耜枷芟。韋云。枷、柫也。所以擊草也。草當作禾王莽傳。必躬載柫。釋名曰。枷、加也。加杖於柄頭、以撾穗而出其榖也。或曰羅枷。三杖而用之也。或曰了了。杖轉於頭。故以名之也。戴先生曰。羅連、語之轉。今連枷之制與古同。"}]},"枷":{"expl":"柫也。从木加聲。淮南謂之柍。","rad":"木","fq":"古牙切","vol":"06","py":"jiā","duan":[{"e":"柫也。從木。加聲。","n":"古牙切。十七部。"}]},"杵":{"expl":"舂杵也。从木午聲。","rad":"木","fq":"昌與切","vol":"06","py":"chǔ","duan":[{"e":"舂杵也。","n":"舂、擣粟也。其器曰杵。繫辭曰。𣃔木爲杵。掘地爲臼。臼杵之利。萬民以濟。"}]},"槩":{"expl":"𣏙斗斛。从木旣聲。","rad":"木","fq":"工代切","vol":"06","py":"ɡài","duan":[{"e":"所㠯𣏙斗斛也。","n":"所以二字今補。月令。正權㮣。鄭、高皆云。㮣、平斗斛者。㮣本器名。用之平斗斛亦曰㮣。許、鄭、高皆云其器也。凡平物曰？。所以？斗斛曰㮣。引伸之義爲節㮣、感㮣、挭㮣。"}]},"杚":{"expl":"平也。从木气聲。","rad":"木","fq":"古没切","vol":"06","py":"ɡài","duan":[{"e":"平也。","n":"𣏙非器也。廁於此者。因上文云𣏙斗斛而釋之也。按許書有𣏙無㧉。𣏙在入聲則古沒切。亦居乙切。去聲則古代切。亦古對切。無二字也。廣韵去入聲皆作扢。從手、皆從木之誤耳。集韵代沒二韵皆於𣏙字之外別出扢字。則由未知廣韵之爲字誤也。𣏙者平物之謂。平之必摩之。故廣雅曰。杚、摩也。廣韵摩之訓本此。古𣏙與槩二字通用。班固終南山賦。槩青宮。觸紫宸。曹植贈丁儀王粲詩。員闕出浮雲。承露槩泰淸。李善注云。西都賦。杚仙掌與承露。廣雅。杚、摩也。槩與杚同。古字通。今書籍此等杚字皆譌作扢。而今文𨕖、後漢書。抗仙掌以承露。又與李善所引迥異。几學古者、當優焉游焉以求其是。顔黃門云。觀天下書未徧。不可妄下雌黃。是也。"}]},"㮐":{"expl":"木參交以枝炊䉛者也。从木省聲。讀若驪駕。","rad":"木","fq":"所綆切","vol":"06","py":"shěnɡ","duan":[{"e":"木參交、㠯支炊䉛者也。","n":"支各本作枝。今依集韵、類篇正。竹部曰。䉛、漉米籔也。籔、炊䉛也。䉛籔二字爲一物。謂米旣淅將炊而漉之令乾。又以三交之木支此䉛。則𤁋乾尤易也。三交之木是爲㮐。"}]},"柶":{"expl":"《禮》有柶。柶，匕也。从木四聲。","rad":"木","fq":"息利切","vol":"06","py":"sì","duan":[{"e":"禮有柶。","n":"凡言禮者、謂禮經十七篇也。禮經多言柶。士冠禮注曰。柶狀如匕。以角爲之者欲滑也。"}]},"桮":{"expl":"㔶也。从木否聲。","rad":"木","fq":"布回切","vol":"06","py":"bēi","duan":[{"e":"㔶也。","n":"匚部曰。㔶、小桮也。析言之。此云。桮、㔶也。渾言之。方言。㿿椷盞䀀閜𥂸𥂓杯也。桮其通語也。古以桮盛羹。桮圈是也。"}]},"槃":{"expl":"承槃也。从木般聲。","rad":"木","fq":"薄官切","vol":"06","py":"pán","duan":[{"e":"承槃也。","n":"承槃者、承水器也。內則曰。進盥。少者奉槃。長者奉水。請沃盥。左傳曰。奉匜沃盥。特牲經曰。尸盥。匜水實于槃中。古之盥手者。以匜沃水。以槃承之。故曰承槃。內則注曰。槃、承盥水者。吳語注曰。槃、承盥器也。大學。湯之盤銘曰。苟日新。日日新。又日新。正謂刻戒於盥手之承槃。故云日日新也。古者晨必洒手。日日皆然。至於沐浴靧面。則不必日日皆然。據內則所云知之。槃引伸之義爲凡承受者之偁。如周禮珠槃、夷槃是也。"}]},"榹":{"expl":"槃也。从木虒聲。","rad":"木","fq":"息移切","vol":"06","py":"sī","duan":[{"e":"槃也。","n":"急就篇。槫椑榹。榹當與許訓同。釋木以爲榹桃字。夏小正作杝桃。"}]},"葍":{"expl":"䔰也。从艸畐聲。","rad":"艸","fq":"方六切","vol":"01","py":"fú","duan":[{"e":"䔰也。","n":"見釋艸。郭云。大葉白華。根如指。正白。可啖。按邶風箋云。葑菲。二菜、蔓菁與葍之類也。皆上下可食。此根可啖之證也。郭又云。葍華有赤者爲藑。藑、葍一種耳。亦猶蔆苕華黃白異名。陸機云。葍有兩種。一種莖葉細而香。一種莖赤有臭氣。按毛公云葍惡菜。殆因有臭氣與。"}]},"案":{"expl":"几屬。从木安聲。","rad":"木","fq":"烏旰切","vol":"06","py":"àn","duan":[{"e":"几屬。","n":"考工記。玉人之事。案十有二寸。棗栗十有二列。大鄭云。案、玉案也。後鄭云。案、玉飾案也。棗栗實於器。乃加於案。戴先生云。案者、棜禁之屬。儀禮注曰。棜之制。上有四周。下無足。禮器注曰。禁、如今方案。隋長。局足。高三寸。此以案承棗栗。宜有四周。漢制小方案局足。此亦宜有足。按許云几屬、則有足明矣。今之上食木槃近似。惟無足耳。楚漢春秋。淮陰侯謝武涉。漢王賜臣玉案之食。後漢書梁鴻傳。妻爲具食。不敢於鴻前仰視。舉案齊睂。方言曰。案、陳楚宋魏之閒謂之？。自關而東謂之案。後世謂所凭之几爲案。古今之變也。"}]},"檈":{"expl":"圜案也。从木瞏聲。","rad":"木","fq":"似沿切","vol":"06","py":"xuán","duan":[{"e":"圜案也。","n":"檈圜曡韵。"}]},"椷":{"expl":"钌也。从木咸聲。","rad":"木","fq":"古咸切","vol":"06","py":"jiān","duan":[{"e":"篋也。","n":"匚部曰。匧、笥也。竹部曰。笥、飯及衣之器也。方言。椷、杯也。與許異。漢天文志。閒可椷劒。蘇林曰。椷、音圅。容也。此假椷爲含也。"}]},"枓":{"expl":"勺也。从木从斗。","rad":"木","fq":"之庾切","vol":"06","py":"zhǔ","duan":[{"e":"勺也。","n":"勺下曰。所以挹取也。與此義相足。凡𦫵斗字作斗。枓勺字作枓。本不相謀。而古音同當口切。故枓多以斗爲之。小雅。維北有斗。不可以挹酒漿。維北有斗。西柄之揭。大雅。酌以大斗。皆以斗爲枓也。考工記注曰。勺、尊斗也。尊斗者、謂挹取於尊之勺。士冠禮注亦曰。勺、尊斗也。所以𣂏酒也。此等本皆假斗爲枓。而俗本譌爲尊𦫵。遂不可通。少宰注曰。凡設水用罍。沃盥有枓。此則用本字。趙世家。使𢊍人操銅枓。張儀傳說此事作金斗。喪大記。沃水用枓。周禮鬯人作斗。"}]},"杓":{"expl":"枓柄也。从木从勺。","rad":"木","fq":"甫搖切","vol":"06","py":"biāo","duan":[{"e":"枓柄也。","n":"枓柄者、勺柄也。勺謂之枓。勺柄謂之杓。小雅言西柄之揭。大雅傳曰。大斗長三尺。張儀傳。令工人作爲金斗。長其尾。令可以擊人。天官書、天文志皆云。杓攜龍角。魁枕參首。北斗一至四爲魁。𧰼羹枓。五至七爲杓。𧰼枓柄也。"}]},"櫑":{"expl":"龜目酒尊，刻木作雲雷象。象施不窮也。从木畾聲。","rad":"木","fq":"魯回切","vol":"06","py":"léi","duan":[{"e":"龜目酒尊。","n":"五經異義。韓詩說。金罍、大器也。天子以玉。諸侯、大夫以金。士以梓。古毛詩說。金罍、酒器也。諸臣之所酢。人君以黃金飾。尊大一碩。金飾龜目。葢刻爲雲靁之𧰼。許君曰。謹案韓詩說。天子以玉。經無明文。謂之罍者、取𧰼雲靁博施。故從人君下及諸臣同。按異義從古毛說。說文同也。故云龜目酒尊、刻本爲雲靁𧰼。爾雅。彝卣罍器也。小罍謂之坎。然則櫑有小大。燕禮。罍水在東。則罍亦以盛水。"}]},"椑":{"expl":"圜榼也。从木卑聲。","rad":"木","fq":"部迷切","vol":"06","py":"pí","duan":[{"e":"圜𣖁也。","n":"漢書曰。美酒一椑。椑見急就篇及廣雅。按考工記廬人。句兵椑。注云。椑、隋圜也。"}]},"榼":{"expl":"酒器也。从木盍聲。","rad":"木","fq":"枯蹋切","vol":"06","py":"kē","duan":[{"e":"酒器也。","n":"師古注急就篇曰。？盛酒之器。其形？？然也。孔叢子曰。子路㗐㗐。當飲十？。"}]},"橢":{"expl":"車笭中橢橢器也。从木隋聲。","rad":"木","fq":"徒果切","vol":"06","py":"tuǒ","duan":[{"e":"車笭中橢橢器也。","n":"橢橢當作隋隋。山部。嶞、山之隋隋者。今本亦譌作嶞嶞者。隋隋、狹長皃也。史記索隱引三蒼云。橢、盛鹽豉器。他果反。師古注急就篇云。楕、小桶也。所以盛鹽豉。廣韵曰。橢、器之狹長。"}]},"槌":{"expl":"關東謂之槌，關西謂之㭙。从木追聲。","rad":"木","fq":"直類切","vol":"06","py":"zhuì","duan":[{"e":"關東謂之槌。關西謂之㭙。","n":"方言。槌、宋魏陳楚江淮之閒謂之植。自關而西謂之样。郭云。槌、縣蠶薄柱也。度畏反。植音値。样音陽。按㭙與植葢一字。古音同在一部也。依方言當作關西謂之样。關東謂之㭙。容許所據不同耳。"}]},"𥛱":{"expl":"門内祭，先祖所以徬徨。从示彭聲。《詩》曰：“祝祭于𥛱。”","rad":"示","fq":"補盲切","vol":"01","py":"bēnɡ","duan":[{"e":"門內祭先祖所㫄皇也。","n":"舊所下有以。今依詩、爾雅音義。㫄或作𢔚𠊓彷。皇或作徨。皆俗。詩毛傳曰。祊、門内也。郊特牲曰。索祭祝於祊。不知神之所在。於彼乎。於此乎。或諸遠人乎。祭於祊、尚曰求諸遠者與。此㫄皇之說也。𥛱㫄皇三字曡韵。"}]},"蓨":{"expl":"苗也。从艸脩聲。","rad":"艸","fq":"徒聊切","vol":"01","py":"tiáo","duan":[{"e":"苖也。","n":"釋艸曰。苖、蓨也。管子。黑埴、其草宜苹蓨。按苹蓨二艸名。"}]},"㭙":{"expl":"槌也。从木，特省聲。","rad":"木","fq":"陟革切","vol":"06","py":"zhé","duan":[{"e":"槌也。從木。寺聲。","n":"各本作特省聲。淺人所改也。特又何聲耶。㭙卽方言之植。月令。具曲植。鄭曰。植、槌也。呂覽作具挾曲。高曰。挾讀曰朕。三輔謂之挾。關東謂之得。淮南書作具撲曲。高曰。薄、持也。三輔謂之撲。按高注持卽㭙之誤。得卽㭙之假借字也。篇、韵皆云。㭙一作棏。一作？。朕本謂横者。高注葢統言之耳。陟革切。古言在一部。"}]},"栚":{"expl":"槌之橫者也。關西謂之㯢。从木灷聲。","rad":"木","fq":"直衽切","vol":"06","py":"zhèn","duan":[{"e":"槌之横者也。關西謂之㯢。","n":"方言。槌、其横關西曰㮳。宋魏陳楚江淮之閒謂之㯂。音帶。齊海岱之閒謂之繏。相卞反。按栚㮳朕三同。關西謂之㯢。西當作東。㯢當同簨虡之簨。横者曰簨。方言作繏。亦同音也。呂覽注曰。挾讀曰朕。三輔謂之朕。正與方言關西曰㮳合。"}]},"槤":{"expl":"瑚槤也。从木連聲。","rad":"木","fq":"里典切","vol":"06","py":"liǎn","duan":[{"e":"胡槤也。","n":"胡各木作瑚。今正。瑚雖見論語、禮記。然依左傳作胡爲長。明堂位曰。有虞氏之兩郭。夏后氏之四璉。殷之六瑚。周之八簋。而苞注論語曰。瑚璉者、黍稷器也。夏曰瑚。商曰璉。周曰簠簋。杜注左云。夏曰瑚。周曰簋。孔沖遠云。包鄭等注論語、賈服等注左傳、皆云。夏曰瑚。杜亦同之。或別有所據。或相從而誤。按此非相從而誤。漢人所據戴記不同也。璉當依許從木。據明堂位音義本作四連。周禮、管子以連爲輦。韓勅禮器碑。胡賛器用。卽胡連也。司馬法。夏后氏謂輦曰余車。殷曰胡奴車。周曰輜輦。疑胡輦皆取車爲名。"}]},"櫎":{"expl":"所以几器。从木廣聲。一曰帷屏風之屬。","rad":"木","fq":"胡廣切","vol":"06","py":"huǎnɡ","duan":[{"e":"所㠯几器。","n":"謂所以庋閣物之器也。几可庋物。故凡庋曰几。廣韵曰。櫎、兵闌。"}]},"㮂":{"expl":"舉食者。从木具聲。","rad":"木","fq":"俱燭切","vol":"06","py":"jú","duan":[{"e":"所㠯舉食者。","n":"所㠯二字今補。按㮂梮二字同。㮂、四圍有周。無足。置食物其中。人舁以進。別於案者、案一人扛之。㮂二人對舉之也。漢書溝洫志。山行則梮。韋昭曰。梮、木器。如今轝牀。人轝以行也。左傳襄九年。陳畚梮。杜曰。梮、土轝也。梮同㮂。人轝、土轝與食轝形製則一。史記梮作檋。許則云山行乗欙。而盛土之梮孟子、毛傳皆謂之虆。虆卽欙字。梮卽㮂字。應劭注漢書曰。梮、或作欙。爲人所牽引也。此葢物重則舁之而又輓之。故曰欙。孔沖遠左傳正義作從手之挶。乃誤字也。"}]},"檕":{"expl":"繘耑木也。从木毄聲。","rad":"木","fq":"古詣切","vol":"06","py":"jì","duan":[{"e":"繘耑木也。","n":"繘、汲井綆也。綆耑木者、下耑有？。上耑有木以爲硾。檕之言系也。釋木以爲檕梅字。"}]},"檷":{"expl":"絡絲檷。从木爾聲。讀若柅。","rad":"木","fq":"奴礼切","vol":"06","py":"nǐ","duan":[{"e":"絡絲柎也。","n":"柎各本作檷。今依易釋文、玉篇、廣韵正。釋文作趺。柎趺右今字。柎、咢足也。絡絲柎者、若今絡絲架子。姤初六。繫於金柅。九家易曰。絲繫於柅。猶女繫於男。故以喻初宜繫二也。"}]},"機":{"expl":"主發謂之機。从木幾聲。","rad":"木","fq":"居衣切","vol":"06","py":"jī","duan":[{"e":"主發謂之機。","n":"下文云。機持經者。機持緯者。則機謂織具也。機之用主於發。故凡主發者皆謂之機。檃桰之辭。"}]},"榺":{"expl":"機持經者。从木朕聲。","rad":"木","fq":"詩證切","vol":"06","py":"shènɡ","duan":[{"e":"機持經者。","n":"三倉曰。經所居、機榺也。淮南氾論訓曰。後世爲之機杼勝複。以便其用。而民得以揜形御寒。勝者、榺之假借字。戴勝之鳥首有横文似榺。故鄭云織？之鳥。小雅云。杼軸其空。榺卽軸也。謂之軸者、如車軸也。俗作柚。謂之榺者、勝其任也。任正者也。"}]},"杼":{"expl":"機之持緯者。从木予聲。","rad":"木","fq":"直呂切","vol":"06","py":"zhù","duan":[{"e":"機持緯者。","n":"？梭皆俗字。"}]},"苖":{"expl":"蓨也。从艸由聲。","rad":"艸","fq":"徒歴切","vol":"01","py":"dí","duan":[{"e":"蓨也。","n":"按小徐本苖字在後𦯄下荼上。"}]},"椱":{"expl":"機持繒者。从木复聲。","rad":"木","fq":"扶富切","vol":"06","py":"fù","duan":[{"e":"機持繒者。","n":"繒字不可通。玉篇作繪。按當作會。會者、經與緯之合也。緯與經合慮其不緊。則有椱入經之間以緊之。魯季敬姜說織曰。持交而不失。出入不絕者。梱也。梱可以爲大行人也。持交、正許所云持會也。趙注孟子梱屨曰。梱、猶叩椓也。織屨欲堅。故叩之也。此與敬姜說梱義同。字皆當從木。孫氏孟子音義從手。誤。淮南氾論訓云。機杼勝複。複卽椱之假借字也。"}]},"楥":{"expl":"履法也。从木爰聲。讀若指撝。","rad":"木","fq":"吁劵切","vol":"06","py":"xuàn","duan":[{"e":"履法也。","n":"今鞋店之楦也。楥楦正俗字。"}]},"核":{"expl":"蠻夷以木皮爲篋，狀如籢尊。从木亥聲。","rad":"木","fq":"古哀切","vol":"06","py":"ɡāi","duan":[{"e":"蠻夷㠯木皮爲匧。狀如籢尊之形也。","n":"未詳所本。今字果實中曰核而本義廢矣。按許不以核爲果實中者。許意果實中之字當用覈也。小雅。肴核維旅。班固、蔡邕作肴覈。左思作肴槅。槅卽覈也。今本毛詩作核。非古也。周禮。其植物宜覈物。覈猶骨也。廣韵云。？、果子？也。出聲譜。戸骨切。此字近是。玉篇亦云。核戸骨切。果實中也。"}]},"棚":{"expl":"棧也。从木朋聲。","rad":"木","fq":"薄衡切","vol":"06","py":"pénɡ","duan":[{"e":"棧也。","n":"通俗文曰。板閣曰棧。連閣曰棚。析言之也。許云棚、棧也。渾言之也。今人謂架上以蔽下者皆曰棚。"}]},"棧":{"expl":"棚也。竹木之車曰棧。从木戔聲。","rad":"木","fq":"士限切","vol":"06","py":"zhàn","duan":[{"e":"棚也。竹木之車曰棧。","n":"不言一曰者、其義同也。小雅傳曰。棧車、役車。箋云。棧車、輦者。許云竹木之車者、謂以竹若木散材編之爲箱、如柵然。是曰棧車。棧者上下四㫄皆偁焉。公羊傳云。亡國之社。掩其上而柴其下。周禮喪祝注作奄其上而棧其下。棧其下、謂以竹木布於地也。"}]},"栫":{"expl":"以柴木𡓱也。从木存聲。","rad":"木","fq":"徂悶切","vol":"06","py":"jiàn","duan":[{"e":"㠯柴木雝也。","n":"雝者今之？字也。文𨕖注引以柴木壅水。玉篇、類篇同。然此不獨施於水。無水爲長也。上文棧云竹木謂竹木之整齊者。此云柴木、謂散材不整齊者。横直皆可云栫。左傳。吳囚邾子於樓臺。栫之以棘。杜曰。栫擁也。釋器。糝謂之涔。江賦。栫澱爲涔。此則聚積柴木於木中也。"}]},"槶":{"expl":"筐當也。从木國聲。","rad":"木","fq":"古悔切","vol":"06","py":"ɡuì","duan":[{"e":"匡當也。","n":"匡當、今俗有此語。謂物之腔子也。槶亦作簂。亦作蔮。士冠禮注云。滕薛名蔮爲頍。釋名曰。簂、恢也。恢廓覆髮上也。魯人曰頍齊人曰？。按鄭、劉所說槶之一耑耳。"}]},"梯":{"expl":"木階也。从木弟聲。","rad":"木","fq":"土雞切","vol":"06","py":"tī","duan":[{"e":"木階也。","n":"孟子。父母使舜完廩。捐階。趙曰。階、梯也。階以木爲之。便於登高。"}]},"棖":{"expl":"杖也。从木長聲。一曰法也。","rad":"木","fq":"宅耕切","vol":"06","py":"chénɡ","duan":[{"e":"杖也。","n":"未詳。"}]},"桊":{"expl":"牛鼻中環也。从木𢍏聲。","rad":"木","fq":"居倦切","vol":"06","py":"juàn","duan":[{"e":"牛鼻環也。","n":"各本環上有中字。今依玄應刪。玄應曰。桊、牛拘也。今江以北皆曰牛拘。以南皆曰桊。居院切。按呂氏春秋曰。使鳥獲疾引牛尾。尾絶力勯而牛不可行。逆也。使五尺童子引其棬。而牛恣所以之。順也。棬者、桊之譌字。"}]},"𦳝":{"expl":"艸。枝枝相値，葉葉相當。从艸昜聲。","rad":"艸","fq":"楮羊切","vol":"01","py":"tānɡ","duan":[{"e":"艸也。","n":"也字各本無。今補。按說文凡艸名篆文之下。皆複舉篆文某字曰某艸也。如葵篆下必云葵菜也。藎篆下必云藎艸也。篆文者其形。說解者其義。以義釋形。故說文爲小學家言形之書也。淺人不知。則盡以爲贅而剛之。不知葵菜也、藎艸也、河水也、江水也皆三字句。首字不逗。今雖未復其舊。爲舉其例於此。此𦳝篆之下。本云𦳝艸也。各本旣刪𦳝字。又去也字。則𦳝篆不爲艸名。似爲凡枝枝相值、葉葉相當之偁矣。玉篇𦳝下引說文謂卽蓫𦳝、馬尾、蔏陸也。薚同𦳝。攷本艸經曰。商陸一名𦳝。句根一名夜呼。陶隱居曰。其花名𦳝。是則絫呼曰蓫𦳝。單呼曰𦳝。或謂其花𦳝。或謂其莖葉𦳝也。"}]},"椯":{"expl":"箠也。从木耑聲。一曰椯度也。一曰剟也。","rad":"木","fq":"兜果切","vol":"06","py":"duǒ","duan":[{"e":"箠也。","n":"淮南氾論訓。是猶無鏑銜橜策錣而御馯馬也。高注錣、椯頭箴。注道應訓又曰。策、馬捶也。端有箴以刺馬謂之錣。按二注、是箠策椯一物也。竹部曰。策、馬箠也。"}]},"橜":{"expl":"弋也。从木厥聲。一曰門梱也。","rad":"木","fq":"瞿月切","vol":"06","py":"jué","duan":[{"e":"弋也。","n":"弋下曰。橜也。"}]},"樴":{"expl":"弋也。从木戠聲。","rad":"木","fq":"之弋切","vol":"06","py":"zhí","duan":[{"e":"弋也。","n":"釋宮曰。樴謂之杙。在牆者謂之楎。在地者謂之臬。大者謂之栱。長者謂之閣。弋杙古今字。樴周禮作職。牛人曰。祭祀共其享牛、求牛。以授職人而芻之。注云。職讀爲樴。樴謂之杙。可以繫牛。引伸凡物一枚曰一樴。鄉射禮記薦脯五樴。注云。樴、猶梃也。爲記者異耳。鄉飲酒禮記薦脯五梃。注云。梃、猶樴也。今本儀禮樴譌膱。梃譌挺及脡。今依張淳、葉林宗所據釋文正。"}]},"杖":{"expl":"持也。从木丈聲。","rad":"木","fq":"直兩切","vol":"06","py":"zhànɡ","duan":[{"e":"持也。","n":"杖持曡韵。凡可持及人持之皆曰杖。喪杖、齒杖、兵杖皆是也。兵杖字俗作仗。非。鬥下云。兵杖在後。欑下云。積竹杖。可證。"}]},"柭":{"expl":"棓也。从木犮聲。","rad":"木","fq":"北末切","vol":"06","py":"bā","duan":[{"e":"棓也。從木。犮聲。","n":"北末切。十五部。"}]},"棓":{"expl":"棁也。从木咅聲。","rad":"木","fq":"步項切","vol":"06","py":"bànɡ","duan":[{"e":"梲也。","n":"棓棒正俗字。天官書。紫宮左三星曰天槍。右五星曰天棓。淮南書。寒浞殺羿於桃棓。"}]},"椎":{"expl":"擊也。齊謂之終葵。从木隹聲。","rad":"木","fq":"直追切","vol":"06","py":"chuí","duan":[{"e":"所㠯擊也。","n":"所㠯二字今補。器曰椎。用之亦曰椎。方言曰。㧙抌椎也。南楚凡相椎搏曰㧙。或曰㧾。沅涌？幽之語或曰攩。郭云。今江東人亦名椎爲攩。按方言椎字、今本多誤從手作推。"}]},"柯":{"expl":"斧柄也。从木可聲。","rad":"木","fq":"古俄切","vol":"06","py":"kē","duan":[{"e":"斧柄也。","n":"見豳風毛傳。考工記曰。一欘有半謂之柯。注云。伐木之柯。柄長三尺。又廬人注曰。齊人謂柯斧柄爲椑。按柯斧者、大斧也。柯之假借爲枝柯。"}]},"棁":{"expl":"木杖也。从木兌聲。","rad":"木","fq":"他活切","vol":"06","py":"tuō","duan":[{"e":"木杖也。","n":"木一本作大。榖梁傳宣十八年曰。邾人戕繒子于繒。戕猶殘也。梲殺也。梲殺謂杖殺之。今本注疏釋文皆譌從手。而唐石經初從木作梲。後改從手。唐玄度之紕繆也。後漢禰衡傳。手持三尺梲杖。按經典用爲梁上短柱之棳。"}]},"柄":{"expl":"柯也。从木丙聲。","rad":"木","fq":"陂病切","vol":"06","py":"bǐnɡ","duan":[{"e":"柯也。","n":"柄之本義專謂斧柯。引伸爲凡柄之偁。周禮、禮經作枋。丙聲方聲同在十部也。"}]},"薁":{"expl":"嬰薁也。从艸奥聲。","rad":"艸","fq":"於六切","vol":"01","py":"yù","duan":[{"e":"嬰薁也。","n":"嬰鍇本作蘡。俗加艸頭耳。豳風。六月食鬱及薁。傳曰。鬱、棣屬。薁、蘡薁也。正義曰。劉稹毛詩義問云。鬱樹高五六尺。其實大如李。本艸。鬱一名棣。則與棣相類。蘡薁亦是鬱類。晉宮閣銘。車下李三百一十四株。車下李卽鬱也。薁李一株。薁李卽薁也。二者相類而同時熟。玉裁按。說文李棣皆在木部。薁在艸部。毛公但云鬱棣屬。未嘗云薁鬱屬。廣雅釋艸。燕薁、蘡舌也。釋木云。山李、雀李、二字今正未知是否鬱也。然則薁之非木實明矣。晉宮閣銘所謂車下李、薁李皆非毛許之嬰薁也。齊民要術引詩義疏曰。櫻薁、實大如龍眼。黑色。今車鞅藤實是。按賈氏凡引詩艸木蟲魚疏皆謂之詩義疏。陸璣本有釋薁云云。今本脫之耳。魏王花木志引詩疏亦同。"}]},"柲":{"expl":"欑也。从木必聲。","rad":"木","fq":"兵媚切","vol":"06","py":"bì","duan":[{"e":"欑也。","n":"欑各本誤從手。葉本誤從イ。今正。此卽下文積竹杖也。考工記。廬人爲廬器。戈柲六尺有六寸。殳長尋有四尺。車戟常。酋矛常有四尺。夷矛三尋。注云。柲猶柄也。按戈戟矛柄皆用積竹杖。不比他柄用木而已。殳則用積竹杖而無刃。柲之引伸爲凡柄之偁。左傳。剝圭以爲戚柲。戚柄不用積竹。"}]},"欑":{"expl":"積竹杖也。从木贊聲。一曰穿也。一曰叢木。","rad":"木","fq":"在丸切","vol":"06","py":"cuán","duan":[{"e":"積竹杖。","n":"詳竹部籚下、殳部殳下。鄭注考工記曰。矛戟柄竹欑柲。"}]},"杘":{"expl":"籆柄也。从木尸聲。","rad":"木","fq":"女履切","vol":"06","py":"chì","duan":[{"e":"篗柄也。","n":"竹部曰。篗、所以收絲者也。方言。篗、榬也。兖豫河濟之閒謂之榬。郭云。所以絡絲也。絡謂之格。郭云。所以轉篗絡車也。按注篗字葢衍。篗卽絡車也。所以轉絡車者、卽杘也。此與檷異物。"}]},"榜":{"expl":"所以輔弓弩。从木㫄聲。","rad":"木","fq":"補盲切","vol":"06","py":"bēnɡ","duan":[{"e":"所㠯輔弓弩也。","n":"經傳未見此義。竹部曰。？、㮄也。假借之義也。辭章家用㮄人、則舟部之舫人也。"}]},"㯳":{"expl":"㮄也。从木敬聲。","rad":"木","fq":"巨京切","vol":"06","py":"qínɡ","duan":[{"e":"㮄也。","n":"秦風。竹閉緄縢。毛曰。閉紲、緄繩、縢約也。小雅角弓傳曰。不善紲檠巧用則翩然而反。旣夕記說明器之弓有柲。注云。柲、弓檠也。弛則縛之於弓裏。僃損傷也。以竹爲之。引詩竹柲緄縢。考工記弓人注云。紲、弓䪐。弓有䪐者、爲發弦時僃頓傷。引詩竹䪐緄縢。合此言之。禮謂之柲。詩謂之閉。周禮注謂之䪐。禮古文作枈。四字一也。皆所謂㯳也。紲者繫㯳於弓之偁。緄則繫之之繩。謂之㯳者、正之也。謂之㮄者、以竹木異體從㫄傅合之之言。凡言㮄笞、㮄箠者、取義於縲紲。凡後世言標㮄者、取義於表見在外也。"}]},"𨽌":{"expl":"栝也。从木，隱省聲。","rad":"木","fq":"於謹切","vol":"06","py":"yǐn","duan":[{"e":"桰也。","n":"檃與栝互訓。檃亦作櫽。亦假借作隱。栝亦假借作括。尚書大傳。子贛曰。櫽栝之㫄多曲木。良醫之門多疾人。砥厲之㫄多頑鈍。荀卿大略篇。大山之木示諸櫽栝。櫽栝者、矯制衺曲之器也。方言。所以隱櫂謂之？。郭云。搖樐小橛也。按櫂以索繫於？而後可打。是？者所以檃其櫂也。如許云矢檃弦處謂之矢栝。矢栝所以檢弦也。般庚。尚皆隱哉。某氏注云。相隱括共爲善政。公羊傳何序云。隱括使就繩墨。孫卿書云。劫之以勢。隱之以阨。阨而用之。得而後功之。隱皆讀爲檃。漢㓝法志。隱之以勢。臣瓚注曰。秦政急峻。隱括其民於隘狹之法是也。凡古云安隱者、皆謂檃栝之而安也。俗作安穩。聲形皆變也。"}]},"桰":{"expl":"𨽌也。从木𠯑聲。一曰矢栝，築弦處。","rad":"木","fq":"古活切","vol":"06","py":"kuò","duan":[{"e":"檃也。從木。𠯑聲。","n":"古活切。十五部。"}]},"棊":{"expl":"博棊。从木其聲。","rad":"木","fq":"渠之切","vol":"06","py":"qí","duan":[{"e":"簙棊。","n":"竹部曰。簙、局戲也。六箸。十二棊。"}]},"椄":{"expl":"續木也。从木妾聲。","rad":"木","fq":"子葉切","vol":"06","py":"jiē","duan":[{"e":"續木也。","n":"今栽華植果者以彼枝移椄此樹而華果同彼樹矣。椄之言接也。今接行而椄廢。"}]},"栙":{"expl":"栙雙也。从木夅聲。讀若鴻。","rad":"木","fq":"下江切","vol":"06","py":"xiánɡ","duan":[{"e":"栙雙也。","n":"三字句。竹部曰。䇬、栙雙也。廣韵曰。栙䉶帆未張。又曰。䉶、帆也。按廣韵有䜶䝄、跭𨇯、舽艭。皆曡韵字。"}]},"葴":{"expl":"馬藍也。从艸咸聲。","rad":"艸","fq":"職深切","vol":"01","py":"zhēn","duan":[{"e":"馬藍也。","n":"見釋艸。郭云。今大葉冬藍也。釋艸又云。葴、寒漿。郭云。今酸漿艸。江東呼曰苦葴。子虛賦。葴析苞荔。張揖釋以馬藍。郭樸云。葴、酸漿、江東名烏葴。"}]},"栝":{"expl":"炊竈木。从木舌聲。","rad":"木","fq":"他念切","vol":"06","py":"tiǎn","duan":[{"e":"炊竈木。","n":"今俗語云竈㮇是也。廣韵云。㮇、火杖。？㮇古今字也。"}]},"槽":{"expl":"畜獸之食器。从木曹聲。","rad":"木","fq":"昨牢切","vol":"06","py":"cáo","duan":[{"e":"嘼之食器。","n":"嘼各本作畜獸二字。今正。嘼、六嘼也。馬櫪曰槽。方言。櫪、梁宋齊楚北燕之閒謂之樎皁。皁與槽音義同也。"}]},"臬":{"expl":"射凖的也。从木从自。李陽冰曰：“自非聲，从劓省。”","rad":"木","fq":"五結切","vol":"06","py":"niè","duan":[{"e":"射𡓑旳也。","n":"𡓑旳各本作準的。今正。土部曰。𡓑、射臬也。二字互訓。日部曰。旳、明也。𡓑準、旳的皆古今字。李善東京賦注引作𡓑。可證古本不作俗字矣。臬古假藝爲之。上林賦。弦矢分。藝殪仆。文穎曰。所射準的爲藝。左傳。陳之藝極。皆是也。臬之引伸爲凡標準法度之偁。釋宮曰。樴謂之杙。在牆者謂之臬。康誥曰。陳時臬事。考工記。匠人作槷。𨸏部曰。賈侍中說陧法度也。皆臬之假借字也。"}]},"桶":{"expl":"木方，受六升。从木甬聲。","rad":"木","fq":"他奉切","vol":"06","py":"tǒnɡ","duan":[{"e":"木方受六𦫵。","n":"疑當作方斛受六斗。廣雅曰。方斛謂之桶。月令。角斗甬。注曰。甬、今斛也。甬卽桶。今斛者、今時之斛。凡鄭言今者皆謂漢時。秦漢時有此六斗斛。與古十斗斛異。史記。商君平斗桶。呂不韋仲春紀。角斗桶。故知起於秦也。"}]},"櫓":{"expl":"大盾也。从木魯聲。","rad":"木","fq":"郎古切","vol":"06","py":"lǔ","duan":[{"e":"大盾也。","n":"盾、瞂也。？、盾也。秦風毛傳曰。伐、中干也。伐卽瞂。干卽？。櫓其大者也。釋名曰。盾大而平者曰吳魁。隆者曰須盾。櫓或假杵爲之。流血漂杵卽流血漂櫓也。"}]},"樂":{"expl":"五聲八音緫名。象鼓鞞。木，虡也。","rad":"木","fq":"玉角切","vol":"06","py":"yuè","duan":[{"e":"五聲八音總名。","n":"樂記曰。感於物而動。故形於聲。聲相應。故生變。變成方。謂之音。比音而樂之。及干戚羽旄謂之樂。音下曰。宮商角徵羽、聲也。絲竹金石匏土革木、音也。樂之引伸爲哀樂之樂。"}]},"柎":{"expl":"闌足也。从木付聲。","rad":"木","fq":"甫無切","vol":"06","py":"fū","duan":[{"e":"闌足也。","n":"柎蒙上文木？言之。阑字恐有誤。韵會本闌作鄂。柎跗正俗字也。凡器之足皆曰柎。小雅。鄂不？？。傳云。鄂猶鄂鄂然。言外發也。箋云。承華者曰鄂。不當作柎。柎、鄂足也。鄂足得華之光明則？？然盛。古聲不柎同。箋意鄂承華者也。柎又在鄂之下。以華與鄂喻兄弟相依。郭璞云。江東呼草木子房爲柎。草木子房如石橊房、蓮房之類。與花下鄂一理也。"}]},"枹":{"expl":"擊鼓杖也。从木包聲。","rad":"木","fq":"甫無切","vol":"06","py":"fú","duan":[{"e":"擊𡔷柄也。","n":"柄各本作杖。今依文𨕖注、玄應書正。左傳音義引字林亦作柄。左傳。右援桴而𡔷。禮運、明堂位皆云。凷桴土𡔷。玄應云。衞宏詔定古文官書。枹桴二字同體。音扶鳩切。𡔷椎也。按桴本訓棟。借爲𡔷柄字耳。"}]},"椌":{"expl":"柷樂也。从木空聲。","rad":"木","fq":"苦江切","vol":"06","py":"qiānɡ","duan":[{"e":"柷樂也。","n":"樂記注曰。椌楬、謂柷敔也。此釋椌爲柷、釋楬爲敔也。謂之椌者、其中空也。"}]},"柷":{"expl":"樂，木空也。所以止音爲節。从木，祝省聲。","rad":"木","fq":"昌六切","vol":"06","py":"zhù","duan":[{"e":"樂木椌也。","n":"樂上當有柷字。椌各本作空。誤。周頌毛傳曰。柷、木椌也。圉楬也。許所本也。今更正。"}]},"𧀦":{"expl":"艸也。可以束。从艸魯聲。","rad":"艸","fq":"郎古切","vol":"01","py":"lǔ","duan":[{"e":"艸也。可㠯束。从艸。魯聲。","n":"郞古切。五部。"}]},"槧":{"expl":"牘樸也。从木斬聲。","rad":"木","fq":"自𤥎切","vol":"06","py":"qiàn","duan":[{"e":"牘樸也。","n":"樸、素也。猶坏也。牘、書版也。槧謂書版之素、未書者也。論衡曰。𣃔木爲槧。釋名曰。槧、版之長三尺者也。槧漸也、言漸漸然長也。楊雄曰。天下上計孝廉及內郡衞卒會。雄常把三寸弱翰。齎油素四尺。以問其異語。歸、卽以鉛摘次之於槧。西京雜記曰。懷鉛提槧。"}]},"札":{"expl":"牒也。从木乙聲。","rad":"木","fq":"側八切","vol":"06","py":"zhá","duan":[{"e":"牒也。","n":"片部曰。牒、札也。二字互訓。長大者曰槧。薄小者曰札、曰牒。釋名曰。札、櫛也。編之如櫛齒相比也。司馬相如傳曰。上令尚書給筆札。師古曰。札、木𥳑之薄小者也。"}]},"檢":{"expl":"書署也。从木僉聲。","rad":"木","fq":"居奄切","vol":"06","py":"jiǎn","duan":[{"e":"書署也。","n":"書署謂表署書函也。後漢祭祀志曰。尚書令奉玉牒檢。皇帝㠯二分璽親封之訖。太常命人發壇上石。尚書令藏玉牒已。復石覆訖。尚書令以五寸印封石檢。按上云玉牒檢者、玉牒之玉函也。所謂玉檢也。下云石檢者、上文云石覆訖是也。檢以盛之。又加以璽印。周禮注曰。璽節、印章。如今斗檢封矣。廣韵云。書檢者、印窠封題也。則通謂印封爲檢矣。公孫瓚傳曰。袁紹矯刻金玉㠯爲印璽。每有所下。輒皁囊施檢。章懷曰。檢今俗謂之排。排如今言幖簽耳。"}]},"檄":{"expl":"二尺書。从木敫聲。","rad":"木","fq":"胡狄切","vol":"06","py":"xí","duan":[{"e":"尺二書。","n":"各本作二尺書。小徐繫傳已佚。見韵會者作尺二書。葢古本也。李賢注光武紀曰。說文以木𥳑爲書。長尺二寸。謂之檄。以徵召也。與前書高紀注同。此葢出演說文。故語加詳。云尺二寸與鍇本合。但漢人多言尺一。未知其分別之詳。後漢書、水經注皆曰。李雲上書云。孔子言帝者、諦也。今尺一拜用。不經御省。是帝欲不諦乎。又後漢書儒林傳云。詔曰。乞楊生師。卽尺一出𦫵。文𨕖注引蕭子良古今篆𣜩文體曰。鶴頭書、偃波書俱詔板所用。在漢時則謂之尺一𥳑。獨𣃔曰。策書長二尺。以命諸侯王三公。三公以罪免。亦賜策。以尺一木。"}]},"棨":{"expl":"傳，信也。从木，啟省聲。","rad":"木","fq":"康礼切","vol":"06","py":"qǐ","duan":[{"e":"傳信也。","n":"此字蒙上槧札檢檄爲次。若今之文書也。漢孝文紀。除關無用傳。張晏曰。傳、信也。若今過所也。如淳曰。兩行書繒帛。分持其一。出入關。合之乃得過。謂之傳也。李奇曰。傳、棨也。師古曰。古者或用棨。或用繒帛。棨者、刻木爲合符也。按用繒帛謂之繻。終軍傳曰。關吏予軍繻是也。用木謂之棨。此云傳信也是也。傳讀張戀反。釋名曰。棨、詣也。以啓語官司所至詣也。當謂此。今本譌舛不可讀。爲正之如此。"}]},"楘":{"expl":"車歴録束文也。从木敄聲。《詩》曰：“五楘梁輈。”","rad":"木","fq":"莫卜切","vol":"06","py":"mù","duan":[{"e":"車𠪱錄。","n":"句。"}]},"枑":{"expl":"行馬也。从木互聲。《周禮》曰：“設梐枑再重。”","rad":"木","fq":"胡誤切","vol":"06","py":"hù","duan":[{"e":"梐枑也。從木。互聲。","n":"胡誤切。五部。○按舊二篆先枑後梐。今正。又此二篆舊次、當與柤槍等篆爲伍。而楘槅橾楇當聯文。"}]},"梐":{"expl":"梐枑也。从木，陛省聲。","rad":"木","fq":"邊兮切","vol":"06","py":"bì","duan":[{"e":"梐枑、","n":"逗。"}]},"极":{"expl":"驢上負也。从木及聲。或讀若急。","rad":"木","fq":"其輒切","vol":"06","py":"jí","duan":[{"e":"驢上負也。","n":"當云驢上所以負也。淺人刪之耳。廣韵云。驢上負版。葢若今䭾鞍。或云負笈字當用此。非也。風土記曰。笈謂學士所以負書箱。如冠箱而卑者也。謝承後漢書曰。負笈隨師。然則笈者書箱。人所負以徒步者。不得合爲一也。"}]},"㭕":{"expl":"极也。从木去聲。","rad":"木","fq":"去魚切","vol":"06","py":"qū","duan":[{"e":"极也。","n":"廣韵曰。版置驢上負物。"}]},"𦳋":{"expl":"艸也。从艸㕟聲。","rad":"艸","fq":"苦怪切","vol":"01","py":"kuǎi","duan":[{"e":"艸也。","n":"左傳引詩曰。雖有絲麻。無棄菅蒯。李善引聲類曰。蒯艸中爲索。苦怪切。史記馮驩有一劔。蒯緱。裴駰曰。蒯、茅之類。可爲繩。其劔把無物可裝。以小繩纏之也。"}]},"槅":{"expl":"大車枙也。从木鬲聲。","rad":"木","fq":"古覈切","vol":"06","py":"ɡé","duan":[{"e":"大車枙。","n":"枙當作軶。𣜩省作軛。車部曰。軶、轅前也。槅考工記作鬲。大鄭云。鬲謂轅端厭牛領者。大車者、鄭云平地任載之車也。通曰軶。大車之軶曰槅。釋名曰。槅、扼也。所以扼牛頸也。馬曰烏啄。下向叉馬頸。似烏開口向下啄物時也。西京賦曰。五都貨殖。旣遷旣引。商旅聯槅。隱隱展展。此正謂大車也。下文云。冠帶交錯。方轅接軫。謂乗車也。"}]},"橾":{"expl":"車轂中空也。从木喿聲。讀若藪。","rad":"木","fq":"山樞切","vol":"06","py":"shū","duan":[{"e":"車轂中空也。","n":"考工記。以轂圍之阞梢其藪。注曰。梢、除也。阞、三分之一也。鄭司農云。梢讀如桑螵蛸之蛸。藪讀如蜂藪之藪。謂轂空壺中也。玄謂此藪徑三寸九分寸之五。壺中當輻葘者也。藪者猶言趨也。蜂藪者、衆輻之所趨也。舊本經注多誤字。今挍正之如是。按記文葢本作梢其橾。大鄭乃易爲藪。故云讀爲。後人直用大鄭說改記文耳。程氏瑤田通藝錄曰。阞與王制祭用數之仂同。十分之一也。藪謂鑿深。梢之以待置輻也。記曰。六分其輪崇。以其一爲之牙圍。參分其牙圍而漆其二。椁其漆內而中詘之。以爲轂長。是則轂長當三尺二寸五分四釐一豪六絲六不盡。由是以轂長爲圍。以圍之十一爲鑿深。十一當三寸二分五釐四豪一絲六忽六不盡。用其成數得三寸。輻廣亦三寸也。車人"}]},"楇":{"expl":"盛膏器。从木咼聲。讀若過。","rad":"木","fq":"乎臥切","vol":"06","py":"huò","duan":[{"e":"盛膏器。","n":"孟子荀卿列傳。談天衍。雕龍奭。炙轂過髨。劉伯莊云。轂字衍。裴駰云。劉向別錄。過字作輠。輠者、車之盛膏器。炙之雖盡。猶有餘流者。言淳于髠不盡如炙輠也。按方言。車釭、齊燕海岱之閒謂之鍋。或謂之錕。自關而西謂之釭。盛膏者乃謂之鍋。此謂關西謂盛膏者曰鍋也。脂施於車釭。故釭或得楇名。而楇自別有物。如今時御者亦系小油缾於車以僃用是也。過輠鍋三字同。"}]},"枊":{"expl":"馬柱。从木卬聲。一曰堅也。","rad":"木","fq":"吾浪切","vol":"06","py":"ànɡ","duan":[{"e":"馬柱也。","n":"謂系馬之柱也。蜀志。劉僃解綬縛督郵馬枊。華陽國志曰。建寧郡存䣖縣。雍闓反。結壘於縣山。繫馬枊柱生成林。"}]},"棝":{"expl":"棝斗，可射鼠。从木固聲。","rad":"木","fq":"古慕切","vol":"06","py":"ɡù","duan":[{"e":"棝𣁬、","n":"逗。"}]},"欙":{"expl":"山行所乘者。从木纍聲。《虞書》曰：“予乘四載。”水行乘舟，陸行乘車，山行乘欙，澤行乘䡅。","rad":"木","fq":"力追切","vol":"06","py":"léi","duan":[{"e":"山行所乗者。","n":"河渠書作橋。𠀌遙反。徐廣曰。一作輂。几玉反。輂、直轅車也。漢書作梮。韋昭曰。梮、木器也。如今轝牀。人轝以行也。應劭曰。梮或作欙。爲人所牽引也。尚書正義引尸子。山行乗欙。僞孔傳亦作欙。按輂梮橋三字同。以梮爲正。橋者、音近轉語也。欙與梮一物異名。梮自其盛載而言。欙自其輓引而言。纍、大索也。欙從纍。此聲義之皆相倚者也。應釋欙、韋釋梮、皆是。兼二說而後全。孟子虆梩。趙云。虆、籠屬。毛詩傳。捄、虆也。亦謂土籠。舁之曰梮。入引之而行則曰欙也。虆者欙之假借字。或省作樏者、非也。毛詩之捄亦梮之假借字也。"}]},"榷":{"expl":"水上橫木，所以渡者也。从木隺聲。","rad":"木","fq":"江岳切","vol":"06","py":"què","duan":[{"e":"水上横木。","n":"句。"}]},"橋":{"expl":"水梁也。从木喬聲。","rad":"木","fq":"巨驕切","vol":"06","py":"qiáo","duan":[{"e":"水梁也。","n":"水梁者、水中之梁也。梁者、宮室所以關舉南北者也。然其字本從水。則橋梁其本義而棟梁其假借也。凡獨木者曰杠。騈木者曰橋。大而爲陂陀者曰橋。古者挈臯曰井橋。曲禮。奉席如橋衡。讀若居廟反。取高舉之義也。"}]},"梁":{"expl":"水橋也。从木从水，刅聲。","rad":"木","fq":"呂張切","vol":"06","py":"liánɡ","duan":[{"e":"水橋也。","n":"梁之字用木跨水、則今之橋也。孟子。十一月輿梁成古本如是國語引夏令曰。九月除道。十月成梁。大雅。造舟爲梁。皆今之橋制。見於經傳者、言梁不言橋也。若爾雅。隄謂之梁。毛傳。石絶水曰梁。謂所以偃塞取魚者。亦取亙於水中之義謂之梁。凡毛詩自造舟爲梁外。多言魚梁。"}]},"𣔱":{"expl":"船緫名。从木叜聲。","rad":"木","fq":"穌遭切","vol":"06","py":"sōu","duan":[{"e":"船緫名。","n":"漢書溝洫志。漕船五百㮴。其字從木。古本從手。"}]},"蔞":{"expl":"艸也。可以亨魚。从艸婁聲。","rad":"艸","fq":"力朱切","vol":"01","py":"lóu","duan":[{"e":"艸也。可㠯亨魚。","n":"召南言刈其蔞。陸璣云。蔞、蔞蒿也。爾雅。購蔏蔞。郭云。蔞、蒿也。江東用羹魚。楚辭曰。吳酸芼蔞。按蔞蒿俗語耳。古衹呼蔞。釋艸古讀或於購蔏句絕。"}]},"橃":{"expl":"海中大船。从木發聲。","rad":"木","fq":"房越切","vol":"06","py":"fá","duan":[{"e":"海中大船。","n":"廣韵橃下曰。木橃、說文云海中大船。謂說文所說者古義。今義則同筏也。凡廣韵注以今義列於前。說文與今義不同者列於後。獨得訓詁之理。葢六朝之舊也。卽如此篆。玉篇注云。海中大船也。泭也。是爲古義今義襍糅。漢人注經固云大者曰筏、小者曰桴。是漢人自用筏字。後人以橃代筏。非漢人意也。"}]},"楫":{"expl":"舟櫂也。从木咠聲。","rad":"木","fq":"子葉切","vol":"06","py":"jí","duan":[{"e":"所㠯擢舟也。","n":"各本作舟櫂也。許無櫂字。手部曰。擢、引也。楫、所以引舟而行。故亦謂之擢。而漢書劉屈氂傳、外戚傳、百官表皆用輯濯爲楫擢。假借也。毛衞風傳曰。楫所以擢舟也。此許所本。今據以正。今毛詩擢譌櫂。淺人所改也。鄧通傳。以濯船爲黃頭郎。司馬相如傳。濯鷁牛首。皆擢舟之義也。詩爾雅音義引說文舟棹也。則其誤久矣。棹又櫂之俗。"}]},"欚":{"expl":"江中大船名。从木蠡聲。","rad":"木","fq":"盧啓切","vol":"06","py":"lǐ","duan":[{"e":"江中大船也。","n":"越絶書曰。欐溪城者闔廬所置船宫也。葢欐與欚古通用。"}]},"校":{"expl":"木囚也。从木交聲。","rad":"木","fq":"古孝切","vol":"06","py":"jiào","duan":[{"e":"木囚也。","n":"囚、繫也。木囚者、以木羈之也易曰。屨校滅趾。何校滅耳。屨校、若今軍流犯人新到箸木鞾。何校、若今犯人帶枷也。此字似當與下文械杽等篆爲伍矣。周禮校人注曰。校之言挍也。主馬者必仍挍視之。校人、馬官之長。按此引伸假借之義也。陸德明曰。比挍字當從手㫄。張參五經文字手部曰。挍、經典及釋文或以爲比挍字。案字書無文。張語正謂說文無從手之挍也。故唐石經考校字皆從木。用張說也。但訂以周禮鄭注。則漢時固有從手之挍矣。比挍字、古葢矣正文。較榷等皆可用。"}]},"樔":{"expl":"澤中守艸樓。从木巢聲。","rad":"木","fq":"鉏交切","vol":"06","py":"cháo","duan":[{"e":"澤中守艸樓。","n":"謂澤中守望之艸樓也。艸樓、葢以艸覆之。藝文類聚艸譌作竹。左傳成十六年正義引此文。樔譌爲櫓。"}]},"采":{"expl":"捋取也。从木从爪。","rad":"木","fq":"倉宰切","vol":"06","py":"cǎi","duan":[{"e":"捋取也。","n":"大雅曰。捋采其劉。周南芣苢傳曰。采、取也。又曰。捋、取也。是采捋同訓也。詩又多言采采。卷耳傳曰。采采、事采之也。此謂上采訓事、下采訓取。而芣苢傳曰。采采、非一辭也。曹風采采衣服傳曰。采采、衆多也。秦風蒹葭采采傳曰。采采猶萋萋也。此三傳義略同。皆謂可采者衆也。凡文采之義本此。俗字手采作採、五采作彩。皆非古也。釋詁曰。采、事也。此言假借。采事同在一部也。"}]},"杮":{"expl":"削木札樸也。从木巿聲。陳楚謂櫝爲杮。","rad":"木","fq":"芳吠切","vol":"06","py":"fèi","duan":[{"e":"削木朴也。","n":"各本作削木札樸也。今依玄應書卷十九正。朴者木皮也。樸者木素也。？安得有素。則作朴是矣。知札爲衍文者。玄應引倉頡篇曰。？、札也。此下文云陳楚謂之札？。玄應曰江南名？。中國曰札。山東名朴豆。廣䪨？注曰。斫木札。然則札非𥳑牒之札。乃？之一名耳。許以札？系諸陳楚方言。則此云削木朴已足。小雅。伐木許許。許書作所所。毛云。許許、？皃。泛謂伐木所斫之皮。許云削木猶斫木也。顏氏家訓必云削札牘之？。又廣爲之證。恐非許意。晉書。王濬造船。木？蔽江而下。？之證也。漢書中山靖王、劉向、田蚡傳多言肺附。謂斫木之杮札也。己於帝室親近猶杮札附於大木材也。此？之假借字也。後漢楊由傳。風吹削肺。亦？之假借也。一譌爲脯。再譌爲哺"}]},"横":{"expl":"闌木也。从木黃聲。","rad":"木","fq":"戶盲切","vol":"06","py":"hénɡ","duan":[{"e":"闌木也。","n":"闌、門遮也。引伸爲凡遮之偁。凡以木闌之皆謂之横也。古多以衡爲横。陳風傳曰。衡門、横木爲門也。考工記。衡四寸。注曰。衡古文横。假借字也。"}]},"梜":{"expl":"檢柙也。从木夾聲。","rad":"木","fq":"古洽切","vol":"06","py":"jiā","duan":[{"e":"檢柙也。","n":"檢柙皆函物之偁。然則梜亦謂函物之器也。曲禮。羹之有菜者用梜。謂箸爲梜。此引伸之義也。"}]},"桄":{"expl":"充也。从木光聲。","rad":"木","fq":"古曠切","vol":"06","py":"ɡuànɡ","duan":[{"e":"充也。","n":"見釋言。陸氏音義曰。桄、孫作光。按堯典光被四表。某氏傳曰光、充也。用爾雅爲訓也。桄讀古曠切。所以充拓之圻堮也。必外有桄、而後內可充拓之令滿。故曰桄、充也。不言所以者、仍爾雅文也。桄之字、古多假横爲之。且部曰。從几、足有二横。横卽桄字。今文尚書曰。横被四表。孔子閒居曰。以横於天下。鄭曰。横、充也。樂記曰。號以立横。横以立武。鄭曰。横、充也。皆卽釋言之桄充也。今文尚書作横被。故漢書王莽傳、王裦傳、後漢書馮異傳、崔駰傳、班固傳、魏都賦注所引東京賦皆作横被。古文尚書作光被。與孫叔然爾雅合。某氏傳光充也、不誤。鄭注釋以光耀。葢非。淮南書横四維、卽尙書之橫被四表也。玄應曰。桄音光。古文横？二形。聲類作輄。"}]},"藟":{"expl":"艸也。从艸畾聲。《詩》曰：“莫莫葛藟。”一曰秬鬯也。","rad":"艸","fq":"力軌切","vol":"01","py":"lěi","duan":[{"e":"艸也。","n":"詩七言葛藟。陸璣云。藟一名巨荒似燕薁。亦延蔓生。葉如艾。白色。其子赤。可食。酢而不美。幽州謂之椎藟。開寶本艸及圖經皆謂卽千歲虆也。按凡藤者謂之藟。系之艸則有藟字。系之木則有蘽字。其實一也。戴先生詩補注說葛藟猶言葛藤。爾雅山櫐虎櫐、山海經卑一作畢山多櫐古本從木皆是也。然鄭君周南箋云葛也、藟也。分爲二物。與許合。葛與藟皆藤生。故詩多類舉之。左氏亦云。葛藟猶能庇其木根。藤古衹作縢。謂可用緘縢也。山海經傳曰。櫐一名縢。"}]},"檇":{"expl":"以木有所擣也。从木雋聲。《春秋傳》曰：“越敗吳於檇李。”","rad":"木","fq":"遵爲切","vol":"06","py":"zuì","duan":[{"e":"㠯木有所擣也。","n":"宋永嘉戴侗曰。今人猶有此語。"}]},"椓":{"expl":"擊也。从木豖聲。","rad":"木","fq":"竹角切","vol":"06","py":"zhuó","duan":[{"e":"擊也。","n":"此與攴部？音義皆同。詩云。椓之丁丁。又云。椓之橐橐。吕㓝曰。爰始淫爲劓刵椓黥。"}]},"朾":{"expl":"橦也。从木丁聲。","rad":"木","fq":"宅耕切","vol":"06","py":"chénɡ","duan":[{"e":"撞也。","n":"撞從手。各本誤從木從禾。今正。通俗文曰。撞出曰朾。丈鞭丈莖二切。與說文合。謂以此物撞彼物使出也。三蒼作敞。周禮職金注作揨。他書作敞、作？。實一字也。朾之字、俗作打。音德冷都挺二切。近代讀德下切。而無語不用此字矣。"}]},"柧":{"expl":"棱也。从木瓜聲。又，柧棱，殿堂上最高之處也。","rad":"木","fq":"古胡切","vol":"06","py":"ɡū","duan":[{"e":"棱也。","n":"柧與棱二字互訓。殳以積竹八觚。觚當作柧。觚行而柧廢矣。史記酷吏傳曰。漢興。破觚而爲圜。應劭曰。觚八棱。有隅者。通俗文曰。木四方爲棱。八棱爲柧。按通俗文析言之。若渾言之。則急就奇觚、謂四方版也。"}]},"棱":{"expl":"柧也。从木夌聲。","rad":"木","fq":"魯登切","vol":"06","py":"lénɡ","duan":[{"e":"柧也。從木。夌聲。","n":"魯登切。六部。俗作楞。"}]},"𣡌":{"expl":"伐木餘也。从木獻聲。《商書》曰：“若顚木之有纫𣡌。”","rad":"木","fq":"五葛切","vol":"06","py":"niè","duan":[{"e":"伐木餘也。","n":"商頌傳曰。？、餘也。周南傳曰。肄、餘也。斬而復生曰肄。按肄者、？之假借字也。韋昭曰。以株生日櫱。方言。烈枿餘也。陳鄭之閒曰枿。晉衞之閒曰烈。秦晉之閒曰肄、或曰烈。枿者亦櫱之異文。"}]},"枰":{"expl":"平也。从木从平，平亦聲。","rad":"木","fq":"蒲兵切","vol":"06","py":"pínɡ","duan":[{"e":"平也。","n":"此門聞也、戸護也之例。謂木器之平偁枰。如今言棊枰是也。上林賦。華楓枰櫨。吳都賦。枰仲君遷。本皆作平。木名也。非許所說。"}]},"柆":{"expl":"折木也。从木立聲。","rad":"木","fq":"盧合切","vol":"06","py":"lā","duan":[{"e":"折木也。","n":"此與手部拉義殊。猶榣與摇之別也。"}]},"槎":{"expl":"衺斫也。从木差聲。《春秋傳》曰：“山不槎。”","rad":"木","fq":"側下切","vol":"06","py":"chá","duan":[{"e":"衺斫也。","n":"？下曰。槎識也。魯語。里革曰。山不槎櫱。李善注西京賦引賈逵解詁曰。槎、邪斫也。韋曰。槎、斫也。按賈云衺斫者、於字從差得之。周禮有柞氏。周頌曰。載芟載柞。毛云。除木曰柞。柞皆卽槎字。異部假借。魚歌合韵之理也。"}]},"柮":{"expl":"斷也。从木出聲。讀若《爾雅》“貀無前足”之“貀”。","rad":"木","fq":"女滑切","vol":"06","py":"duò","duan":[{"e":"檮柮也。","n":"舊作𣃔也二字。今更正。今人謂木頭爲榾柮。於古義未遠也。"}]},"蒬":{"expl":"棘蒬也。从艸冤聲。","rad":"艸","fq":"於元切","vol":"01","py":"yuān","duan":[{"e":"棘蒬也。","n":"見釋艸。本艸經云。遠志一名棘菀。一名葽繞。一名細艸。"}]},"檮":{"expl":"斷木也。从木𠷎聲。《春秋傳》曰：“𣚑柮。”","rad":"木","fq":"徒刀切","vol":"06","py":"táo","duan":[{"e":"𣚑柮、","n":"逗。二字今補。"}]},"析":{"expl":"破木也。一曰折也。从木从斤。","rad":"木","fq":"先激切","vol":"06","py":"xī","duan":[{"e":"破木也。","n":"斯下云析也。柀下云一曰析也。詩多言析薪。"}]},"棷":{"expl":"木薪也。从木取聲。","rad":"木","fq":"側鳩切","vol":"06","py":"zōu","duan":[{"e":"木薪也。","n":"按禮運假棷爲藪字。"}]},"梡":{"expl":"㮯，木薪也。从木完聲。","rad":"木","fq":"胡本切","vol":"06","py":"hùn","duan":[{"e":"㮯木薪也。","n":"對析言之。梡之言完也。"}]},"㮯":{"expl":"梡木未析也。从木圂聲。","rad":"木","fq":"胡昆切","vol":"06","py":"hún","duan":[{"e":"梡木未析也。","n":"此梡當作完。全也。通俗文曰。合心曰㮯。纂文曰。未判爲㮯。頁部頑下云。㮯頭也。凡全物渾大皆曰㮯。完㮯雙聲。完頑曡韵。"}]},"楄":{"expl":"楄部，方木也。从木扁聲。《春秋傳》曰：“楄部薦榦。”","rad":"木","fq":"部田切","vol":"06","py":"pián","duan":[{"e":"楄部、","n":"逗。"}]},"楅":{"expl":"以木有所逼束也。从木畐聲。《詩》曰：“夏而楅衡。”","rad":"木","fq":"彼即切","vol":"06","py":"bī","duan":[{"e":"㠯木有所畐束也。","n":"畐依韵會本。各本作逼者、後人以俗字改之也。泛云㠯木有所畐束則不專謂施於牛者。引詩特其一證耳。鄉射禮命弟子設楅注。楅猶幅也。所以承笴齊矢者。按記云。楅髤、横而拳之。南面坐而奠之。南北當洗。是以木有所畐束也。"}]},"枼":{"expl":"楄也。枼，薄也。从木丗聲。","rad":"木","fq":"与涉切","vol":"06","py":"yè","duan":[{"e":"楄也。","n":"方木也。"}]},"𤍕":{"expl":"積火燎之也。从木从火，酉聲。《詩》曰：“薪之槱之。”《周禮》：“以槱燎祠司中、司命。”","rad":"木","fq":"余救切","vol":"06","py":"yǒu","duan":[{"e":"積木燎之也。","n":"木各本作火。今依玉篇、五經文字正。大雅。芃芃棫樸。薪之？之。傳曰。？、積也。山木茂盛。萬民得而薪之。賢人衆多。國家得用蕃興。按如毛說則？謂積薪而巳。至鄭箋乃以煙祀？尞爲說。許不但云積木而兼云燎之者。爲其字之從火也。不云尞之而云燎之者。燎、放火也。尞、祡祭天也。毛曰。萬民薪之而巳。故但云燎。"}]},"休":{"expl":"息止也。从人依木。","rad":"木","fq":"許尤切","vol":"06","py":"xiū","duan":[{"e":"息止也。","n":"周南曰。南有喬木。不可休思。"}]},"祰":{"expl":"告祭也。从示从告聲。","rad":"示","fq":"苦浩切","vol":"01","py":"kǎo","duan":[{"e":"吿祭也。","n":"自祪以下六字皆主言祖廟。故知吿祭謂王制天子諸矦將出。造乎禰。曾子問諸矦適天子。必吿於祖。奠於禰。諸矦相見。必吿於禰。反必親吿於祖禰。伏生尚書歸假於祖禰。皆是也。周禮六祈二曰造。杜子春云。造祭於祖也。當許時。禮家造字容有作祰者。"}]},"茈":{"expl":"茈艸也。从艸此聲。","rad":"艸","fq":"將此切","vol":"01","py":"zǐ","duan":[{"e":"茈艸也。","n":"三字句。茈字僅得免刪。可以證𦳋下必云𦳋艸也、藟下必云藟艸也。皆淺人刪之。周禮注云。染艸。茅蒐、橐盧、豕首、紫茢之屬。按紫茢卽紫䓞也。紫䓞卽茈艸也。廣雅云。茈䓞、茈草也。古列戾同音。茈紫同音。本艸經云。紫草一名紫丹。一名紫芺。陶隱居云。卽是今染紫者。說文云。䓞艸可以染畱黃。謂之紫䓞者。以染紫之䓞別於染駵黃之䓞也。西山經曰。勞山多茈艸。司馬彪注上林賦曰。茈薑、紫色之薑。郭注南山經曰。茈？、紫色？。故知古紫茈通用。"}]},"㮓":{"expl":"竟也。从木恆聲。","rad":"木","fq":"古鄧切","vol":"06","py":"ɡèn","duan":[{"e":"竟也。","n":"弓人注曰。恆讀爲㮓。㮓、竟也大雅。恆之秬秠。毛云。恆、徧也。徧與竟義相足。"}]},"械":{"expl":"桎梏也。从木戒聲。一曰器之緫名。一曰持也。一曰有盛爲械，無盛爲器。","rad":"木","fq":"胡戒切","vol":"06","py":"xiè","duan":[{"e":"桎梏也。從木。戒聲。","n":"胡戒切。古音在一部。"}]},"杽":{"expl":"械也。从木从手，手亦聲。","rad":"木","fq":"敕九切","vol":"06","py":"chǒu","duan":[{"e":"械也。","n":"械當作梏。字從木手。則爲手械無疑也。廣雅曰。杽謂之梏。杽杻古今字。廣韵曰。抙、杻古文。"}]},"桎":{"expl":"足械也。从木至聲。","rad":"木","fq":"之日切","vol":"06","py":"zhì","duan":[{"e":"足械也。所㠯質地。","n":"所㠯質地四字依周禮音義補。桎質曡韵也。周禮掌囚注。鄭司農云。拲者、兩手共一木也。桎梏者、兩手各一木也。玄謂在手曰梏。在足曰桎。中罪不拲。手足各一木耳。按後鄭從許說也。韋昭云。兩手共一木曰拲。兩手各一木曰梏。"}]},"梏":{"expl":"手械也。从木告聲。","rad":"木","fq":"古沃切","vol":"06","py":"ɡù","duan":[{"e":"手械也。所㠯告天。","n":"所㠯告天四字依周禮音義補。梏吿曡韵也。"}]},"櫪":{"expl":"櫪㯕，椑指也。从木歴聲。","rad":"木","fq":"郎擊切","vol":"06","py":"lì","duan":[{"e":"櫪㯕、","n":"逗。"}]},"㯕":{"expl":"櫪㯕也。从木斯聲。","rad":"木","fq":"先稽切","vol":"06","py":"xī","duan":[{"e":"？㯕也。","n":"二字㬪韵。㯕讀同析。"}]},"檻":{"expl":"櫳也。从木監聲。一曰圈。","rad":"木","fq":"胡黯切","vol":"06","py":"jiàn","duan":[{"e":"櫳也。","n":"李善注長楊賦引釋名曰。檻車上施闌檻以格猛獸。亦囚禁罪人之車也。按許云檻櫳也者、謂罪人及虎豹所居。假借爲凡闌檻字。"}]},"櫳":{"expl":"檻也。从木龍聲。","rad":"木","fq":"盧紅切","vol":"06","py":"lónɡ","duan":[{"e":"檻也。從木。龍聲。","n":"字有偏旁稍移而爲二字者。柔栩也、杼機持緯者也、㰍房室之？也、櫳檻也、是也。竊有疑焉。㰍與櫳皆言横直爲窗櫺通明。不嫌同偁。如檻亦爲闌檻。許於楯下云闌檻是也。左木右龍之字恐淺人所增。盧紅切。九部。"}]},"柙":{"expl":"檻也。以藏虎兕。从木甲聲。","rad":"木","fq":"烏匣切","vol":"06","py":"xiá","duan":[{"e":"檻也。所㠯臧虎兕也。","n":"所、也二字依廣韵補。論語。虎兕出於柙。馬曰。柙、檻也。引伸爲凡檢柙之偁。如上文云柙指是也。"}]},"𧂀":{"expl":"茈艸也。从艸䫉聲。","rad":"艸","fq":"莫覺切","vol":"01","py":"mò","duan":[{"e":"茈艸也。","n":"見釋艸。"}]},"棺":{"expl":"關也。所以掩尸。从木官聲。","rad":"木","fq":"古丸切","vol":"06","py":"ɡuān","duan":[{"e":"關也。","n":"以㬪韵爲訓。門聞、戸護之例也。"}]},"櫬":{"expl":"棺也。从木親聲。《春秋傳》曰：“士輿櫬。”","rad":"木","fq":"初僅切","vol":"06","py":"chèn","duan":[{"e":"棺也。","n":"玉篇曰。親身棺也。按天子之棺四重。諸公三重。諸侯再重。大夫一重。士不重。天子水兕革棺冣在內。諸侯杝棺冣在內。檀弓。君卽位而爲椑。椑謂杝棺親屍者。椑、堅箸之言也。"}]},"槥":{"expl":"棺櫝也。从木彗聲。","rad":"木","fq":"祥歲切","vol":"06","py":"huì","duan":[{"e":"棺櫝也。","n":"櫝、匱也。棺之小者。故謂之棺櫝。急就篇。棺槨槥櫝。櫝卽槥也。高帝紀。令士卒從軍死者爲櫘。應劭曰。小棺也。今謂之櫝。臣瓚引金布令曰。不幸死。死所爲櫝。傳歸所居。縣賜以衣棺。"}]},"椁":{"expl":"葬有木𩫏也。从木𩫏聲。","rad":"木","fq":"古博切","vol":"06","py":"ɡuǒ","duan":[{"e":"葬有木𩫖也。","n":"木𩫖者。以木爲之。周於棺。如城之有𩫖也。檀弓曰。殷人棺椁。注。椁、大也。以木爲之。言郭大於棺也。"}]},"楬":{"expl":"楬桀也。从木曷聲。《春秋傳》曰：“楬而書之。”","rad":"木","fq":"其謁切","vol":"06","py":"jié","duan":[{"e":"楬櫫也。","n":"三字句。趙鈔本及近刻五音韵諩作楬櫫。宋本、葉本、類篇、集韵、宋刊五音韵諩皆作楬桀。葢宋時大徐本固有二。故同一五音韵諩而流傳不一也。今按作桀不可通。桀自訓磔。雖杙有𧦝榤者。然頗迂遠。楬櫫見周禮注。職金。楬而璽之。注曰。楬、書其數量以著其物也。今時之書有所表識。謂之楬櫫。廣雅曰。楬櫫、杙也。廣韵曰。楬櫫、有所表識也。楬櫫、漢人語。許以漢人常語爲訓。故出櫫字於說解。仍不大列櫫篆。漢酷吏傳曰。瘞寺門桓東。楬著其姓名。著櫫同字可證也。韵會楬下引說文曰。杙也。櫫也。此小徐眞本。而語似不完。師古注漢書曰。楬、杙也。椓杙於瘞處而書死者名也。師古杙也之云、葢本說文。但說文杙字當作弋。"}]},"梟":{"expl":"不孝鳥也。日至，捕梟磔之。从鳥頭在木上。","rad":"木","fq":"古堯切","vol":"06","py":"xiāo","duan":[{"e":"不孝鳥也。故日至捕梟磔之。","n":"漢儀。夏至賜百官梟羹。漢書音義。孟康曰。梟、鳥名。食母。破鏡、獸名。食父。黃帝欲絕其類。使百吏祠皆用之。如淳曰。漢使東郡送梟。五月五日作梟羹以賜百官。以其惡鳥故食之也。"}]},"棐":{"expl":"輔也。从木非聲。","rad":"木","fq":"敷尾切","vol":"06","py":"fěi","duan":[{"e":"輔也。","n":"尚書多言棐。釋詁曰。弼棐輔比俌也。按棐葢弓檠之類。"}]},"梔":{"expl":"木實可染。从木巵聲。","rad":"木","fq":"章移切","vol":"06","py":"zhī","duan":[{"e":"黃木。可染者。","n":"各本篆文誤作桅。今依韵會所據本正。小徐云。史記貨殖傳千畞卮茜、又書記多言鮮支、皆此。是鍇本固作栀字。證一。玉篇列字次弟與說文同。而梇楰杒榙四字之閒字作栀。之移切。不作桅。桅字乃𡉈下文孫强等增竄之處。證二。水部染下引裴光遠曰從木。木者所以染。桅茜之屬也。此用史記栀茜。而亦譌作桅。證三。桅、今之栀子樹。實可染黃。相如賦謂之鮮之。史記假卮爲之。"}]},"榭":{"expl":"臺有屋也。从木䠶聲。","rad":"木","fq":"詞夜切","vol":"06","py":"xiè","duan":[]},"槊":{"expl":"矛也。从木朔聲。","rad":"木","fq":"所角切","vol":"06","py":"shuò","duan":[]},"萴":{"expl":"烏喙也。从艸則聲。","rad":"艸","fq":"阻力切","vol":"01","py":"cè","duan":[{"e":"烏喙也。","n":"廣雅。？、奚毒、附子也。一歲爲萴子。二歲爲烏喙。三歲爲附子。四歲爲烏頭。五歲爲天雄。按本艸經有附子、烏頭、天雄三條。云烏頭一名奚毒。一名卽子。一名烏喙。卽子卽萴子、猶鰂鯽一字也。名醫別錄又沾側子一條。誤矣。"}]},"椸":{"expl":"衣架也。从木施聲。","rad":"木","fq":"以支切","vol":"06","py":"yí","duan":[]},"榻":{"expl":"牀也。从木𦐇聲。","rad":"木","fq":"土盍切","vol":"06","py":"tà","duan":[]},"櫍":{"expl":"柎也。从木質聲。","rad":"木","fq":"之日切","vol":"06","py":"zhì","duan":[]},"櫂":{"expl":"所以進舩也。从木翟聲。或从卓。《史記》通用濯。","rad":"木","fq":"直教切","vol":"06","py":"zhào","duan":[]},"槹":{"expl":"桔槹，汲水器也。从木臯聲。","rad":"木","fq":"古牢切","vol":"06","py":"ɡāo","duan":[]},"樁":{"expl":"橛杙也。从木舂聲。","rad":"木","fq":"啄江切","vol":"06","py":"zhuānɡ","duan":[]},"櫻":{"expl":"果也。从木嬰聲。","rad":"木","fq":"烏莖切","vol":"06","py":"yīnɡ","duan":[]},"栜":{"expl":"桋也。从木，策省聲。","rad":"木","fq":"所厄切","vol":"06","py":"sè","duan":[]},"東":{"expl":"動也。从木。官溥說：从日在木中。凡東之屬皆从東。","rad":"東","fq":"得紅切","vol":"06","py":"dōnɡ","duan":[{"e":"動也。","n":"見漢律曆志。"}]},"㯥":{"expl":"二東，曹从此。闕。","rad":"東","fq":"","vol":"06","py":"cáo","duan":[{"e":"二東。","n":"謂其形也。"}]},"蒐":{"expl":"茅蒐，茹藘。人血所生，可以染絳。从艸从鬼。","rad":"艸","fq":"所鳩切","vol":"01","py":"sōu","duan":[{"e":"茅蒐、","n":"逗。"}]},"林":{"expl":"平土有叢木曰林。从二木。凡林之屬皆从林。","rad":"林","fq":"力尋切","vol":"06","py":"lín","duan":[{"e":"平土有叢木曰林。","n":"周禮林衡注曰。竹木生平地曰林。小雅依彼平林傳曰。平林、林木之在平地者也。？部曰。野外謂之林。引伸之義也。釋詁、毛傳皆曰。林、君也。假借之義也。"}]},"𣞤":{"expl":"豐也。从林；𡘲。或說規模字。从大、𠦜，數之積也；林者，木之多也。𠦜與庶同意。《商書》曰：“庶草繁無。”","rad":"林","fq":"文甫切","vol":"06","py":"wú","duan":[{"e":"豐也。","n":"釋詁曰。蕪茂豐也。釋文云。蕪、古本作𣞤。"}]},"鬱":{"expl":"木叢生者。从林，𩰪省聲。","rad":"林","fq":"迂弗切","vol":"06","py":"yù","duan":[{"e":"木叢者。","n":"依韵會本。秦風。鬱彼北林。毛曰。鬱、積也。鄭司農注考工記曰。惌讀如宛彼北林之宛。菀桺傳曰。菀、茂林也。桑柔傳曰。菀、茂皃。按宛菀皆卽鬱字。"}]},"楚":{"expl":"叢木。一名荊也。从林疋聲。","rad":"林","fq":"創舉切","vol":"06","py":"chǔ","duan":[{"e":"叢木。","n":"小雅傳曰。楚楚、茨棘皃。小徐引小謝詩曰。寒城一以眺。平楚正蒼然。"}]},"棽":{"expl":"木枝條棽儷皃。从林今聲。","rad":"林","fq":"丑林切","vol":"06","py":"chēn","duan":[{"e":"木枝條棽儷也。","n":"也各本作皃。今依集韵、類篇正。人部儷下云。棽儷也。棽儷者、枝條茂密之皃。借爲上覆之皃。東都賦。鳳盇棽麗。李善注引七略。雨葢棽麗。麗與儷同力支切。張揖大人賦注曰。林離、摻攦也。摻攦、所林所宜二反。葢卽棽儷。"}]},"楙":{"expl":"木盛也。从林矛聲。","rad":"林","fq":"莫𠊱切","vol":"06","py":"mào","duan":[{"e":"木盛也。","n":"此與艸部茂音義皆同。分艸木耳。釋木。楙、木瓜。則專爲一物之名。"}]},"麓":{"expl":"守山林吏也。从林鹿聲。一曰林屬於山爲麓。《春秋傳》曰：“沙麓崩。”","rad":"林","fq":"盧谷切","vol":"06","py":"lù","duan":[{"e":"守山林吏也。","n":"左傳。山林之木。衡鹿守之。杜曰。衡鹿、官名也。按鹿者、麓之假借字。天子曰林衡。諸侯曰衡鹿。皆守山林吏也。晉語。史黯曰。主將適螻而麓不聞。韋曰。麓、主君苑囿者。"}]},"棼":{"expl":"複屋棟也。从林分聲。","rad":"林","fq":"符分切","vol":"06","py":"fén","duan":[{"e":"複屋棟也。","n":"複屋、考工記謂之重屋。木部曰。檼、棼也。是曰檼、曰棼者、複屋之棟也。曰橑者、複屋之椽也。竹部曰。笮者、在瓦之下棼上者也。姚氏鼐曰。椽棟旣重、軒版垂檐皆重矣。軒版卽屋笮。或木或竹異名。在瓦之下椽之上。檐垂椽端。椽亦謂之橑。考工記重屋。鄭以複笮釋之。而他書所稱曰重檐曰重橑曰重軒曰重、棟、曰重棼、各舉其一爲言爾。按左傳。治絲而棼之。假借爲紛亂字。"}]},"森":{"expl":"木多皃。从林从木。讀若曾參之參。","rad":"林","fq":"所今切","vol":"06","py":"sēn","duan":[{"e":"木多皃。從林。從木。","n":"按篇、韵皆云。森、長木皃。疑篇、韵所據爲長。從林從木正謂有木出平林之上也。"}]},"梵":{"expl":"出自西域釋書，未詳意義。","rad":"林","fq":"扶泛切","vol":"06","py":"fàn","duan":[]},"茜":{"expl":"茅蒐也。从艸西聲。","rad":"艸","fq":"倉見切","vol":"01","py":"qiàn","duan":[{"e":"茅蒐也。从艸。西聲。","n":"倉見切。古音在十三部。蒨卽茜字也。古音當在十一部。其音變適同耳。"}]},"才":{"expl":"艸木之初也。从丨上貫一，將生枝葉。一，地也。凡才之屬皆从才。","rad":"才","fq":"昨哉切","vol":"06","py":"cái","duan":[{"e":"艸木之初也。","n":"引伸爲凡始之偁。釋詁曰。初哉始也哉卽才。故哉生明亦作才生明。凡才材財裁纔字以同音通用。"}]},"叒":{"expl":"日初出東方湯谷，所登榑桑，叒木也。象形。凡叒之屬皆从叒。","rad":"叒","fq":"而灼切","vol":"06","py":"ruò","duan":[{"e":"日初出東方湯谷所登榑桑。","n":"句。"}]},"桑":{"expl":"蠶所食葉木。从叒、木。","rad":"叒","fq":"息郎切","vol":"06","py":"sānɡ","duan":[{"e":"蠶所食葉木。从叒木。","n":"榑桑者、桑之長也。故字从叒。桑不入木部而傳於叒者。所貴者也。息郎切。十部。"}]},"之":{"expl":"出也。象艸過屮，枝莖益大，有所之。一者，地也。凡之之屬皆从之。","rad":"之","fq":"止而切","vol":"06","py":"zhī","duan":[{"e":"出也。","n":"引伸之義爲往。釋詁曰之往是也。按之有訓爲此者。如之人也。之德也。之條條。之刀刀。左傳。鄭人醢之、三人也。召南毛傳曰。之事、祭事也。周南曰。之子、嫁子也。此等之字皆訓爲是。之有訓爲上出者。戴先生釋梓人曰。頰側上出者曰之。下垂者曰而。須鬣是也。"}]},"㞷":{"expl":"艸木妄生也。从之在土上。讀若皇。","rad":"之","fq":"戶光切","vol":"06","py":"huánɡ","duan":[{"e":"艸木妄生也。","n":"𡉚妄疊韵。妄生猶怒生也。"}]},"帀":{"expl":"周也。从反之而帀也。凡帀之屬皆从帀。周盛說。","rad":"帀","fq":"子荅切","vol":"06","py":"zā","duan":[{"e":"𠣘也。","n":"𠣘各本作周。誤。今正。勹部𠣘、帀徧也。是爲轉注。按古多假襍爲帀。"}]},"師":{"expl":"二千五百人爲師。从帀从𠂤。𠂤，四帀，眾意也。","rad":"帀","fq":"疎夷切","vol":"06","py":"shī","duan":[{"e":"二千五百人爲師。","n":"小司徒曰。五人爲伍。五伍爲㒳。五㒳爲卒。五卒爲旅。五旅爲師。師、衆也。京師者、大衆之稱。衆則必有主之者。周禮師氏注曰。師、敎人以道者之稱也。黨正旅師閭胥注曰。正師胥皆長也。師之言帥也。"}]},"出":{"expl":"進也。象艸木益滋，上出達也。凡出之屬皆从出。","rad":"出","fq":"尺律切","vol":"06","py":"chū","duan":[{"e":"進也。","n":"本謂艸木。引伸爲凡生長之偁。又凡言外出爲內入之反。"}]},"賣":{"expl":"出物貨也。从出从買。","rad":"出","fq":"莫邂切","vol":"06","py":"mài","duan":[{"e":"出物貨也。","n":"周禮多言賣儥、謂賣買也。"}]},"𧀳":{"expl":"赤𧀳也。从艸、𨽸。","rad":"艸","fq":"息利切","vol":"01","py":"sì","duan":[{"e":"赤蕼也。从艸。肆聲。","n":"息利切。十五部。"}]},"糶":{"expl":"出穀也。从出从䊮，䊮亦聲。","rad":"出","fq":"他弔切","vol":"06","py":"tiào","duan":[{"e":"出穀也。","n":"米部曰䊮、穀也。出穀之字从出䊮。市穀之字从入䊮。"}]},"𦤙":{"expl":"𣙗𦤙，不安也。从出臬聲。《易》曰：“𣙗𦤙。”","rad":"出","fq":"五結切","vol":"06","py":"niè","duan":[{"e":"槷𦤙、","n":"逗。"}]},"𣎵":{"expl":"艸木盛𣎵𣎵然。象形，八聲。凡𣎵之屬皆从𣎵。讀若輩。","rad":"𣎵","fq":"普活切","vol":"06","py":"pò","duan":[{"e":"艸木盛𣎵𣎵然。","n":"𣎵𣎵者、枝葉茂盛因風舒散之皃。小雅。萑葦淠淠。毛曰。淠淠、衆皃。淠淠者、𣎵𣎵之假借也。小雅。胡不旆旆。毛曰。旆旆、旒垂皃。旆旆者、亦𣎵𣎵之假借字。非繼旐之旆也。魯頌作伐伐。按玉篇<>作巿。引毛傳蔽巿小皃。玉裁謂。毛詩蔽巿字、恐是用蔽厀之巿字。經傳韍多作芾、作茀、可證也。"}]},"𢍚":{"expl":"艸木𢍚孛之皃。从𣎵𢌿聲。","rad":"𣎵","fq":"于貴切","vol":"06","py":"wèi","duan":[{"e":"艸木𢍚孛之皃。","n":"當作𢍚孛艸木之皃。周易。拔茅茹以其彙。征吉。釋文云。彙古文作𦳢。按𦳢卽𢍚字之異者。彙則假借字也。𢍚孛疊韵。"}]},"索":{"expl":"艸有莖葉，可作繩索。从𣎵、糸。杜林說：𣎵亦朱木字。","rad":"𣎵","fq":"蘇各切","vol":"06","py":"suǒ","duan":[{"e":"艸有莖葉可作繩索。","n":"當云索繩也。與糸部繩索也。爲轉注。而後以艸有莖葉可作繩索發明从𣎵之意。今本乃淺人所𠜂耳。爾雅曰。紼、繂也。謂大索。經史多假索爲𡩡字。又水部曰。澌、水索也。索訓盡。"}]},"孛":{"expl":"𢍚也，从𣎵；人色也，从子。《論語》曰：“色孛如也。”","rad":"𣎵","fq":"蒲妹切","vol":"06","py":"bèi","duan":[{"e":"𢍚孛也。","n":"依全書通例補孛字。春秋有星孛入于北斗。穀梁曰。孛之爲言猶茀也。茀者多艸。凡物盛則易亂。故星孛爲𢍚孛引伸之義。誖悖字从孛。"}]},"𠂔":{"expl":"止也。从𣎵盛而一橫止之也。","rad":"𣎵","fq":"卽里切","vol":"06","py":"zǐ","duan":[{"e":"止也。从𣎵盛而一橫止之也。","n":"會意。卽裏切。古音當在十五部。詩。萬億及秭。與醴妣禮皆韵、可證也。而𦚘、仕聲。楊雄作胏。又疑𠂔在一部。"}]},"南":{"expl":"艸木至南方，有枝任也。从𣎵𢆉聲。","rad":"𣎵","fq":"那含切","vol":"06","py":"nán","duan":[{"e":"艸木至南方有枝任也。","n":"此亦脫誤。當云南任也。與東動也一例。下乃云艸木至南方有枝任也、發明从𣎵之意。漢律曆志曰。大陽者南方。南任也。陽氣任養物。於時爲夏。云艸木至南方者、猶云艸木至夏也。有枝任者、謂夏時艸木畼楙丁壯、有所枝𠲱任載也。故从𣎵。按古南男二字相假借。"}]},"生":{"expl":"進也。象艸木生出土上。凡生之屬皆从生。","rad":"生","fq":"所庚切","vol":"06","py":"shēnɡ","duan":[{"e":"進也。象艸木生出土上。","n":"下象土。上象出。此與𡳿出𣎵以類相從。所庚切。十一部。"}]},"丰":{"expl":"艸盛𡴀𡴀也。从生，上下達也。","rad":"生","fq":"敷容切","vol":"06","py":"fēnɡ","duan":[{"e":"艸盛丰丰也。","n":"引伸爲凡豐盛之偁。鄭風。子之丰兮。毛曰。丰、豐滿也。鄭曰。面皃丰丰然豐滿。方言。好或謂之妦。妦卽丰字也。"}]},"薜":{"expl":"牡贊也。从艸辟聲。","rad":"艸","fq":"蒲計切","vol":"01","py":"bì","duan":[{"e":"牡贊也。","n":"見釋艸。"}]},"産":{"expl":"生也。从生，彥省聲。","rad":"生","fq":"所簡切","vol":"06","py":"chǎn","duan":[{"e":"生也。从生。彥省聲。","n":"所𥳑切。十四部。通用爲嘼㹌字。按今南北語言皆作楚𥳑切。"}]},"𨼇":{"expl":"豐大也。从生降聲。","rad":"生","fq":"力中切","vol":"06","py":"lónɡ","duan":[{"e":"豐大也。","n":"隆者、漢{歹+昜[左右]}帝之名。不云上諱而直書其字者。五經異義云。漢幼小諸帝皆不廟祭而祭於陵。旣不廟祭、似可不諱。然漢志河內郡隆慮。應劭曰。隆慮山在北。避{歹+昜[左右]}帝名。改曰林慮也。又郡國志。林慮故隆慮。{歹+昜[左右]}帝改。漢制生而諱。枚孝宣更名。此葢{歹+昜[左右]}帝在位時所改。而書成於和帝永元十二年。以前未及諱。至安帝建光元年許沖上書時不追改。故不云上諱。祐曰上諱者、今天子之名。又在開卷也。林與隆合韵。故毛詩臨衝、韓詩作隆衝。"}]},"甤":{"expl":"草木實甤甤也。从生，豨省聲。讀若綏。","rad":"生","fq":"儒隹切","vol":"06","py":"ruí","duan":[{"e":"艸木實甤甤也。","n":"甤與蕤音義皆同。甤之言垂也。"}]},"甡":{"expl":"眾生並立之兒。从二生。《詩》曰：“甡甡其鹿。”","rad":"生","fq":"所臻切","vol":"06","py":"shēn","duan":[{"e":"衆生竝立之皃。","n":"大雅毛傳曰。甡甡、衆多也。其字或作詵詵。或作駪駪。或作侁侁。或作莘莘。皆假借也。周南傳曰。詵詵、衆多也。小雅傳曰。駪駪、衆多之皃。"}]},"乇":{"expl":"艸葉也。从垂穗，上貫一，下有根。象形。凡乇之屬皆从乇。","rad":"乇","fq":"陟格切","vol":"06","py":"zhé","duan":[{"e":"艸葉也。","n":"當作艸華皃。下云垂𥝩、上貫一華則有𥝩。葉不當言𥝩也。"}]},"𠂹":{"expl":"艸木華葉𠂹。象形。凡𠂹之屬皆从𠂹。","rad":"𠂹","fq":"是爲切","vol":"06","py":"chuí","duan":[{"e":"艸木華葉𠂹。","n":"引伸爲凡下𠂹之偁。今字𡍮行而𠂹廢矣。"}]},"𠌶":{"expl":"艸木華也。从𠂹亏聲。凡𠌶之屬皆从𠌶。","rad":"𠌶","fq":"況于切","vol":"06","py":"huā","duan":[{"e":"艸木華也。","n":"此與下文𦾓音義皆同。𦾓、榮也。釋艸曰。𦾓、荂也。𦾓、荂、榮也。今字花行而𦾓廢矣。"}]},"𩏬":{"expl":"盛也。从𠌶韋聲。《詩》曰：“萼不𩏬𩏬。”","rad":"𠌶","fq":"于鬼切","vol":"06","py":"wěi","duan":[{"e":"盛也。","n":"小雅傳曰。韡韡、光明也。"}]},"華":{"expl":"榮也。从艸从𠌶。凡華之屬皆从華。","rad":"華","fq":"戶瓜切","vol":"06","py":"huā","duan":[{"e":"榮也。","n":"見釋艸。艸部曰。葩、華也。䑞部曰。𤰀、華榮也。按釋艸曰。蕍芛葟華榮。渾言之也。又曰。木謂之華。艸謂之榮。榮而實者謂之秀。榮而不實者謂之英。析言之也。引伸爲曲禮削瓜爲國君華之之字。又爲光華、華夏字。"}]},"皣":{"expl":"艸木白華也。从華从白。","rad":"華","fq":"筠輒切","vol":"06","py":"yè","duan":[{"e":"艸木白華皃。","n":"皃各本作也。今依文𨕖西都賦注正。賦曰。蘭茝發色。皣皣猗猗。"}]},"莣":{"expl":"杜榮也。从艸忘聲。","rad":"艸","fq":"武方切","vol":"01","py":"wánɡ","duan":[{"e":"杜榮也。","n":"見釋艸。郭云。今芒艸也。似茅。皮可以爲繩索履屩也。按太平御覽引襍字解詁。芒、杜榮。而芒譌作芸。"}]},"𥝌":{"expl":"木之曲頭止不能上也。凡𥝌之屬皆从𥝌。","rad":"𥝌","fq":"古兮切","vol":"06","py":"jī","duan":[{"e":"木之曲頭止不能上也。","n":"此字古少用者。玉篇曰。亦作礙。非是。礙在一部。𥝌當在十五、十六部。古兮切。玉篇古漑古兮二切。"}]},"䅩":{"expl":"多小意而止也。从𥝌从支，只聲。一曰木也。","rad":"𥝌","fq":"職雉切","vol":"06","py":"zhǐ","duan":[{"e":"䅩䅓、","n":"逗。二字各本無。今補。"}]},"䅓":{"expl":"䅩䅓也。从𥝌从又，句聲。又者，从丑省。一曰木名。","rad":"𥝌","fq":"俱羽切","vol":"06","py":"jǔ","duan":[{"e":"䅩䅓也。","n":"上篆下釋䅩䅓之義。此祗云䅩䅓也。全書例如此。"}]},"稽":{"expl":"畱止也。从𥝌从尤，旨聲。凡稽之屬皆从稽。","rad":"稽","fq":"古兮切","vol":"06","py":"jī","duan":[{"e":"畱止也。","n":"玄應書引畱止曰𥠻。高注戰國策曰。畱其日、𥠻畱其日也。凡𥠻畱則有審愼求詳之意。故爲𥠻攷。禹會諸矦於會𥠻。𥠻、計也。稽攷則求其同異。故說尙書稽古爲同天。𥠻、同也。如流求也之例。"}]},"𥢔":{"expl":"特止也。从稽省，卓聲。","rad":"稽","fq":"竹角切","vol":"06","py":"zhuó","duan":[{"e":"特止也。","n":"鍇曰。特止、卓立也。按如有所立卓爾、當用此字。"}]},"𥢑":{"expl":"𥢑䅓而止也。从稽省，咎聲。讀若皓。賈侍中說：稽、𥢔、𥢑三字皆木名。","rad":"稽","fq":"古老切","vol":"06","py":"ɡǎo","duan":[{"e":"𥢑䅓而止也。","n":"䅩䅓謂之雙聲。𥢑䅓謂之疊韵。"}]},"巢":{"expl":"鳥在木上曰巢，在穴曰窠。从木，象形。凡巢之屬皆从巢。","rad":"巢","fq":"鉏交切","vol":"06","py":"cháo","duan":[{"e":"鳥在木上曰巢。在穴曰窠。","n":"穴部曰。穴中曰窠。樹上曰巢。巢之言高也。窠之言空也。在穴之鳥、如鴝鵒之屬。今江蘇語言通名禽獸所止曰窠。"}]},"𡬯":{"expl":"傾覆也。从寸，𦥑覆之。寸，人手也。从巢省。杜林說：以爲貶損之貶。","rad":"巢","fq":"方斂切","vol":"06","py":"biǎn","duan":[{"e":"傾覆也。","n":"周禮𥓊蔟氏。掌覆夭鳥之巢。"}]},"桼":{"expl":"木汁。可以䰍物。象形。桼如水滴而下。凡桼之屬皆从桼。","rad":"桼","fq":"親吉切","vol":"06","py":"qī","duan":[{"e":"木汁。可㠯䰍物。","n":"木汁名桼。因名其木曰桼。今字作漆而桼廢矣。漆、水名也。非木汁也。詩書梓桼、桼絲皆作漆。俗以今字易之也。周禮載師。桼林之征二十而五。大鄭曰。故書桼林爲漆林。杜子春云。當爲桼林。是則漢人分別二字之嚴。今注疏譌舛。爲正之如此。周禮巾車注髤桼字皆作桼。不作漆。漢人多假桼爲七字。史記六律五聲八音來始。來始正桼始之誤。尙書大傳、漢律曆志皆作七始。史、漢同用今文尙書也。"}]},"䰍":{"expl":"桼也。从桼髟聲。","rad":"桼","fq":"許由切","vol":"06","py":"xiū","duan":[{"e":"桼也。","n":"韋昭曰。㕞桼曰䰍。師古曰。以桼桼物謂之髤。今關東俗謂之捎桼。捎卽髤聲之轉耳。髤或作䰍。按以桼桼物皆謂之䰍。不限何色也。鄉射禮記曰。楅髤。注云。赤黑桼也。巾車注云。髤謂赤多黑少之色韋也。漢書。中庭彤朱。殿上髤桼。西都賦謂之彤庭玄墀。然則或赤、或黑、或赤黑兼、或赤多黑少、皆得云䰍。"}]},"苞":{"expl":"艸也。南陽以爲麤履。从艸包聲。","rad":"艸","fq":"布交切","vol":"01","py":"bāo","duan":[{"e":"艸也。","n":"曲禮苞屨不入公門注。苞、藨也。齊衰藨𦳋之菲也。子虛賦。葴析苞荔。張揖曰。苞、藨也。玉裁按。當是藨是正字。苞是叚借。故喪服作藨𦳋之菲。曲禮作苞屨。南都賦說艸有藨。卽子虛之苞也。斯干、生民傳曰。苞、本也。此苞字之本義。凡詩云苞櫟苞棣、書云艸木蔪苞者皆此字。叚借爲包裹。凡詩言白茅苞之、書言厥苞橘柚、禮言苞苴、易言苞蒙苞荒苞承苞羞苞桑苞瓜、春秋傳言苞茅不入皆用此字。近時經典凡訓包裹者皆徑改爲包字。郭忠恕之說誤之也。許君立文當云苞本也、從艸、包聲。若不謂爲叚借。則當云苞、藨也。下文卽云藨、𦳋屬。使讀者知曲禮之苞卽喪服之藨。葢艸木旣難多識。文字古今屢變。雖曰至精。豈能無誤。善學古者不泥於古可也。"}]},"㯡":{"expl":"桼垸巳，復桼之。从桼包聲。","rad":"桼","fq":"匹皃切","vol":"06","py":"pào","duan":[{"e":"桼垸巳。","n":"句。"}]},"束":{"expl":"縛也。从囗、木。凡束之屬皆从束。","rad":"束","fq":"書玉切","vol":"06","py":"shù","duan":[{"e":"縛也。","n":"糸部曰。縛、束也。是爲轉注。襍記曰。納幣一束。束五兩。兩五尋。"}]},"柬":{"expl":"分別𥳑之也。从束从八。八，分別也。","rad":"束","fq":"古限切","vol":"06","py":"jiǎn","duan":[{"e":"分別𥳑之也。","n":"釋詁曰。流差柬擇也。韵會無𥳑字爲長。凡言𥳑練、𥳑擇、𥳑少者、皆借𥳑爲柬也。柬訓分別、故其字從八。一說當作分別䉍之。䉍、在也。在、存也。"}]},"𢆞":{"expl":"小束也。从束幵聲。讀若繭。","rad":"束","fq":"古典切","vol":"06","py":"jiǎn","duan":[{"e":"小束也。","n":"齊民要術曰。麻𢆞欲小、縛欲薄。爲其易乾。"}]},"剌":{"expl":"戾也。从束从刀。刀者，剌之也。","rad":"束","fq":"盧達切","vol":"06","py":"là","duan":[{"e":"戾也。","n":"戾者、韋背之意。凡言乖剌、剌謬字如此。謚法愎很遂過曰剌。"}]},"㯻":{"expl":"橐也。从束圂聲。凡㯻之屬皆从㯻。","rad":"㯻","fq":"胡本切","vol":"06","py":"ɡǔn","duan":[{"e":"橐也。","n":"廣韵曰。㯻、大束。"}]},"橐":{"expl":"囊也。从㯻省，石聲。","rad":"㯻","fq":"他各切","vol":"06","py":"tuó","duan":[{"e":"囊也。","n":"按許云。橐囊也。囊橐也。渾言之也。大雅毛傳曰。小曰橐。大曰囊。高誘注戰國策曰。無底曰囊。有底曰橐。皆析言之也。囊者、言實其中如瓜瓤也。橐者、言虛其中以待如木𣝔也。玄應書引蒼頡篇云。橐、囊之無底者。則與高注互異。許多用毛傳。疑當云橐、小囊也。囊、橐也。則同異皆見。全書之例如此。此葢有奪字。又詩釋文引說文。無底曰囊。有底曰橐。與今本絶異。"}]},"囊":{"expl":"橐也。从㯻省，襄省聲。","rad":"㯻","fq":"奴當切","vol":"06","py":"nánɡ","duan":[{"e":"橐也。从㯻省。𤕦聲。","n":"𤕦各本作襄省二字。淺人改也。今正。奴郎切。十部。"}]},"櫜":{"expl":"車上大橐。从㯻省，咎聲。《詩》曰：“載櫜弓矢。”","rad":"㯻","fq":"古勞切","vol":"06","py":"ɡāo","duan":[{"e":"車上大橐。","n":"云車上大橐者、謂可藏任器載之於車也。樂記注曰。兵甲之衣曰櫜。鍵櫜言閉藏兵甲也。大雅、周頌毛傳曰。櫜、韜也。齊語。垂櫜而入。韋曰。櫜、囊也。引伸之義凡韜於外者皆爲櫜。周禮膏物注云。膏當爲櫜。蓮芡之實有櫜韜。"}]},"㯱":{"expl":"囊張大皃。从㯻省，匋省聲。","rad":"㯻","fq":"符宵切","vol":"06","py":"pāo","duan":[{"e":"囊張大皃。","n":"石𡔷文。其魚隹可。隹鱮隹鯉。可以㯱之。隹楊及桺。㯱讀如苞苴之苞。蘇軾詩作貫。非也。"}]},"艾":{"expl":"冰臺也。从艸乂聲。","rad":"艸","fq":"五蓋切","vol":"01","py":"ài","duan":[{"e":"仌臺也。","n":"見釋艸。張華博物志曰。削冰令圓。舉以向日。以艾於後承其影、則得火。"}]},"囗":{"expl":"回也。象回帀之形。凡囗之屬皆从囗。","rad":"囗","fq":"羽非切","vol":"06","py":"wéi","duan":[{"e":"回也。","n":"回、轉也。按圍繞、週圍、字當用此。圍行而囗廢矣。"}]},"圜":{"expl":"天體也。从囗瞏聲。","rad":"囗","fq":"王權切","vol":"06","py":"yuán","duan":[{"e":"天體也。","n":"圜、環也。呂氏春秋曰。何以說天道之圜也。精氣一上一下。圜周復襍。（高曰襍猶帀）無所𥠻畱。故曰天道圜。何以說地道之方也。萬物殊類殊形。皆有分職。不能相爲。故曰地道方。按天體不渾圜如丸。故大戴禮云。參嘗聞之夫子曰。天道曰圓。地道曰方。盧云。道曰方圓耳。非形也。淮南子曰。天之圓不中規。地之方不中矩。白虎通曰。天、鎭也。其道曰圓。地、諦也。其道曰方。許言天體、亦謂其體一氣循環。無終無始。非謂其形渾圜也。下文云。圓、圜全也。斯爲渾圜。許書圓圜㘣三字不同。今字多作方圓、方員、方圜、而㘣字廢矣。依許則言天當作圜。言平㘣當作㘣。言渾圓當作圓。"}]},"團":{"expl":"圜也。从囗專聲。","rad":"囗","fq":"度官切","vol":"06","py":"tuán","duan":[{"e":"圜也。","n":"鄭風霝露團兮。周禮假專爲團。大司徒注曰。專、圜也。"}]},"㘣":{"expl":"規也。从囗肙聲。","rad":"囗","fq":"似沿切","vol":"06","py":"xuán","duan":[{"e":"規也。","n":"規、有法度也。"}]},"囩":{"expl":"回也。从囗云聲。","rad":"囗","fq":"羽巾切","vol":"06","py":"yún","duan":[{"e":"回也。","n":"二字疊韵。雲字下曰。象雲回轉形。沄字下曰。轉流也。凡從云之字皆有回轉之義。"}]},"圓":{"expl":"圜全也。从囗員聲。讀若員。","rad":"囗","fq":"王問切","vol":"06","py":"yuán","duan":[{"e":"圜全也。","n":"全集韵、類篇作合。誤字也。圜者天體。天屈西北而不全。圜而全、則上下四旁如一。是爲渾圜之物。商頌。幅隕旣長。毛曰。隕、均也。按玄烏傳亦曰。員、均也。是則毛謂員隕皆圓之假借字。渾圜則無不均之処也。箋申之曰。隕當作圓。圓謂周也。此申毛、非易毛。"}]},"回":{"expl":"轉也。从囗，中象回轉形。","rad":"囗","fq":"戶恢切","vol":"06","py":"huí","duan":[{"e":"轉也。","n":"淵、回水也。故顏回字子淵。毛詩傳曰。回、邪也。言回爲𠆎之假借也。又曰。回、違也。亦謂假借也。𠆎、衺也。見交部。"}]},"圖":{"expl":"畫計難也。从囗从啚。啚，難意也。","rad":"囗","fq":"同都切","vol":"06","py":"tú","duan":[{"e":"畫計難也。","n":"左傳曰。咨難爲謀。畫計難者、謀之而苦其難也。國語曰。夫謀必素見成事焉而後履之。謂先規畫其事之始終曲折。歷歴可見。出於萬全。而後行之也。故引伸之義謂繪畫爲圖。聘禮曰。君與𨜮圖事。釋詁曰。圖、謀也。小雅傳曰。慮、圖皆謀也。"}]},"圛":{"expl":"回行也。从囗睪聲。《尚書》：“曰圛。” 圛，升雲半有半無。讀若驛。","rad":"囗","fq":"羊益切","vol":"06","py":"yì","duan":[{"e":"回行也。","n":"謂回曲而行。"}]},"國":{"expl":"邦也。从囗从或。","rad":"囗","fq":"古惑切","vol":"06","py":"ɡuó","duan":[{"e":"邦也。","n":"邑部曰。邦、國也。按邦國互訓。渾言之也。周禮注曰。大曰邦。小曰國。邦之所居亦曰國。析言之也。"}]},"祏":{"expl":"宗廟主也。《周禮》有郊、宗、石室。一曰大夫以石爲主。从示从石，石亦聲。","rad":"示","fq":"常隻切","vol":"01","py":"shí","duan":[{"e":"宗廟主也。","n":"五經異義。今春秋公羊說。祭有主者。孝子以主繫心。夏后氏以松。殷人以柏。周人以栗。今論語說。哀公問主於宰我。宰我對曰。夏后氏以松。夏人都河東。河東宜松也。殷人以柏。殷人都亳。亳宜柏也。周人以栗。周人都豐鎬。豐鎬宜栗也。古周禮說。虞主用桑。練主用栗。無夏后氏以松爲主之事。許君謹按。從周禮說。論語所云、謂社主也。鄭君無駁。五經要義曰。木主之狀四方。穿中央以達四方。天子長尺二寸。諸矦長尺。皆刻謚於其背。春秋左氏傳。典司宗祏。又曰。使祝史徙主祏於周廟。又曰。反祏於西圃。皆謂木主也。主當同宀部作宔。宔字下曰。宗廟宔祏也。祏字下曰。宗廟宔也。是爲轉注。蓺文類聚引作宗廟之木主曰祏。"}]},"蔁":{"expl":"艸也。从艸章聲。","rad":"艸","fq":"諸良切","vol":"01","py":"zhānɡ","duan":[{"e":"艸也。","n":"玉篇曰。蔁、桺根。卽蔏陸也。此非許意。"}]},"𡈋":{"expl":"宮中道。从囗，象宮垣、道、上之形。《詩》曰：“室家之壼。”","rad":"囗","fq":"苦本切","vol":"06","py":"kǔn","duan":[{"e":"宫中道。","n":"釋宫曰。宫中衖謂之壼。郭云。巷、閤門道也。按大雅。室家之壼。毛曰。壼、廣也。箋云。壼之言梱也。室家相梱致。皆引伸假借之義。"}]},"囷":{"expl":"廩之圜者。从禾在囗中。圜謂之囷，方謂之京。","rad":"囗","fq":"去倫切","vol":"06","py":"qūn","duan":[{"e":"廩之圜者。从禾在囗中。","n":"去倫切。十二部。"}]},"圈":{"expl":"養畜之閑也。从囗卷聲。","rad":"囗","fq":"渠篆切","vol":"06","py":"juàn","duan":[{"e":"養畜之閑也。","n":"畜當作嘼。轉寫改之耳。閑、闌也。牛部曰。牢、閑養牛馬圈也。是牢與圈得通偁也。"}]},"囿":{"expl":"苑有垣也。从囗有聲。一曰禽獸曰囿。","rad":"囗","fq":"于救切","vol":"06","py":"yòu","duan":[{"e":"苑有垣也。","n":"高注淮南曰。有牆曰苑。無牆曰囿。與許互異。葢有無互譌耳。魏都賦曰。繚垣開囿。繚垣、西京賦作繚亙。繚亙綿聮、卽西都賦之繚以周牆也。周禮注曰。囿、今之苑。按古今異名。許析言之、鄭渾言之也。引伸之凡淵奧處曰囿。夏小正。正月囿有見韭。囿也者、轅之燕者也。四月囿有見杏。囿也者、山之燕者也。又引伸之凡分別區域曰囿。常道將引洛書曰。人皇始出。分理九州爲九囿。九囿卽毛詩之九有、韓詩之九域也。域同或。古或與有與囿通用。"}]},"園":{"expl":"所以樹果也。从囗袁聲。","rad":"囗","fq":"羽元切","vol":"06","py":"yuán","duan":[{"e":"所㠯樹果也。","n":"鄭風傳曰。園所以樹木也。按毛言木、許言果者。毛詩檀穀桃棘皆系諸園。木可以包果。故周禮云。園圃毓草木。許意凡云苑囿已必有艸木。故以樹果系諸園。"}]},"圃":{"expl":"穜菜曰圃。从囗甫聲。","rad":"囗","fq":"博古切","vol":"06","py":"pǔ","duan":[{"e":"所㠯穜菜曰圃。","n":"所㠯二字今補。齊風毛傳曰。圃、菜園也。馬融論語注曰。樹菜蔬曰圃。玄應引倉頡解詁云。種樹曰園。種菜曰圃。"}]},"因":{"expl":"就也。从囗、大。","rad":"囗","fq":"於眞切","vol":"06","py":"yīn","duan":[{"e":"就也。","n":"就下曰。就、高也。爲高必因丘陵。爲大必就基阯。故因從囗大。就其區域而擴充之也。中庸曰。天之生物。必因其材而篤焉。左傳曰。植有禮。因重固。人部曰。仍、因也。論語。因不失其親。謂所就者不失其親。"}]},"㘝":{"expl":"下取物縮藏之。从囗从又。讀若聶。","rad":"囗","fq":"女洽切","vol":"06","py":"nà","duan":[{"e":"下取物縮臧之。","n":"謂攝取也。今農人罱泥。罱卽㘝之俗字。"}]},"囹":{"expl":"獄也。从囗令聲。","rad":"囗","fq":"郎丁切","vol":"06","py":"línɡ","duan":[{"e":"獄也。","n":"獄上當有囹圉二字。幸部曰。囹圉所㠯拘罪人。葢許作囹圉。與他書囹圄不同也。月令鄭注曰。囹圄所以禁守繫者。若今別獄矣。蔡邕云。囹、牢也。圄、止也。所以止出入。皆罪人所舍也。鄭志。崇精問曰。囹圄、何代之獄。焦氏荅曰。月令、秦書。則秦獄名也。漢曰若盧。魏曰司空。"}]},"圄":{"expl":"守之也。从囗吾聲。","rad":"囗","fq":"魚舉切","vol":"06","py":"yǔ","duan":[{"e":"守之也。从囗。吾聲。","n":"魚舉切。五部。按韵會云。圄、說文本作圉。葢小徐本有圉無圄。左傳。圄伯嬴於轑陽而殺之。"}]},"芹":{"expl":"楚葵也。从艸斤聲。","rad":"艸","fq":"巨巾切","vol":"01","py":"qín","duan":[{"e":"楚葵也。从艸。斤聲。","n":"詳菦字下。巨巾切。古音在十三部。"}]},"囚":{"expl":"繫也。从人在囗中。","rad":"囗","fq":"似由切","vol":"06","py":"qiú","duan":[{"e":"繫也。从人在囗中。","n":"似由切。三部。"}]},"固":{"expl":"四塞也。从囗古聲。","rad":"囗","fq":"古慕切","vol":"06","py":"ɡù","duan":[{"e":"四塞也。","n":"四塞者無罅漏之謂。周禮夏官掌固注云。固、國所依阻者也。國曰固。野曰險。按凡堅牢曰固。又事之已然者曰固。卽故之假借字也。漢官掌故、唐官多作掌固。"}]},"圍":{"expl":"守也。从囗韋聲。","rad":"囗","fq":"羽非切","vol":"06","py":"wéi","duan":[{"e":"守也。从囗。韋聲。","n":"羽非切。十五部。"}]},"困":{"expl":"故廬也。从木在囗中。","rad":"囗","fq":"苦悶切","vol":"06","py":"kùn","duan":[{"e":"故廬也。","n":"廬者、二畞半一家之居。居必有木。樹牆下以桑是也。故字從囗木。謂之困者、疏廣所謂自有舊田廬令子孫勤力其中也。困之本義爲止而不過。引伸之爲極盡。論語。四海困竆。謂君德充塞宇宙。與橫被四表之義略同。苞注曰。言爲政信執其中、則能竆極四海。天祿所以長終也。凡言困勉、困苦皆極盡之義。"}]},"圂":{"expl":"廁也。从囗，象豕在囗中也。會意。","rad":"囗","fq":"胡困切","vol":"06","py":"hùn","duan":[{"e":"豕廁也。","n":"少儀。君子不食圂腴。注云。周禮圂作豢。謂犬豕之屬食米穀者也。腴有似於人穢。按云周禮圂作豢者、槀人掌豢祭祀之犬是也。豢從豕𢍏聲。圂從囗豕會意。據許說本非一字。豢以人之萎養而言。圂以牢中溷濁而言。少儀圂腴不煩改字。謂豕廁爲圂。因謂豕犬爲圂耳。引伸之義人廁或曰圂。俗作溷。或曰淸。俗作圊。或曰軒。皆見釋名。"}]},"囮":{"expl":"譯也。从囗、化。率鳥者繫生鳥以來之，名曰囮。讀若譌。又音由。","rad":"囗","fq":"五禾切","vol":"06","py":"é","duan":[{"e":"譯也。","n":"譯、疑當作誘。一說周禮貉隷掌與獸言。夷隷掌與鳥言。是其事也。"}]},"員":{"expl":"物數也。从貝囗聲。凡員之屬皆从員。","rad":"員","fq":"王權切","vol":"06","py":"yuán","duan":[{"e":"物數也。","n":"本爲物數引伸爲人數。俗偁官員。漢百官公𨜮表曰。吏員、自佐史至丞相十二萬二百八十五人是也。數木曰枚、曰梃。數竹曰箇。數絲曰紽、曰緫。數物曰員。小雅。員于爾輻。毛曰。員、益也。此引伸之義也。又假借爲云字。如秦誓若弗員來、鄭風𦕼樂我員、商頌景員維河。箋云。員、古文云。"}]},"𧶊":{"expl":"物數紛𧶊亂也。从員云聲。讀若《春秋傳》曰“宋皇鄖”。","rad":"員","fq":"羽文切","vol":"06","py":"yún","duan":[{"e":"物數紛𧶊亂也。","n":"𧶊今字作紜。紜行而𧶊廢矣。紛𧶊謂多。多則亂也。古假芸爲𧶊。老子。夫物芸芸。各歸其根。"}]},"貝":{"expl":"海介蟲也。居陸名猋，在水名蜬。象形。古者貨貝而寶龜，周而有泉，至秦廢貝行錢。凡貝之屬皆从貝。","rad":"貝","fq":"博蓋切","vol":"06","py":"bèi","duan":[{"e":"海介蟲也。","n":"介蟲之生於海者。"}]},"𧴪":{"expl":"貝聲也。从小、貝。","rad":"貝","fq":"酥果切","vol":"06","py":"suǒ","duan":[{"e":"貝聲也。从小貝。","n":"聚小貝則多聲。故其字從小貝。引伸爲細碎之偁。今俗瑣㞕字當作此。琑行而𧴪廢矣。周易旅初六。旅瑣瑣。陸績曰。瑣瑣、小也。艮爲小石。故曰旅瑣瑣也。按瑣者、𧴪之假借字。玉部瑣謂玉聲。穌果切。十七部。"}]},"薽":{"expl":"豕首也。从艸甄聲。","rad":"艸","fq":"側鄰切","vol":"01","py":"zhēn","duan":[{"e":"豕首也。","n":"釋艸曰。茢薽、豕首。許無茢字者。攷太平御覽引爾雅蔩土瓜。孫炎曰。一名列也。按叔然以茢上屬。許君讀葢與孫同。鄭注周禮豕首爲染艸之屬。呂氏春秋曰。豨首生而麥無葉。本艸經曰。天名精一名豕首。"}]},"賄":{"expl":"財也。从貝有聲。","rad":"貝","fq":"呼罪切","vol":"06","py":"huì","duan":[{"e":"財也。","n":"周禮注曰。金玉曰貨。布帛曰賄。析言之也。許渾言之。貨賄皆釋曰財。"}]},"財":{"expl":"人所寶也。从貝才聲。","rad":"貝","fq":"昨哉切","vol":"06","py":"cái","duan":[{"e":"人所寶也。","n":"寶、珍也。周禮注曰。財、泉穀也。？下云。小雨財？也。以爲今之纔字。"}]},"貨":{"expl":"財也。从貝化聲。","rad":"貝","fq":"呼臥切","vol":"06","py":"huò","duan":[{"e":"財也。","n":"廣韵引蔡氏化淸經曰。貨者、化也。變化反易之物、故字从化。"}]},"䞈":{"expl":"資也。从貝爲聲。或曰：此古貨字。讀若貴。","rad":"貝","fq":"詭僞切","vol":"06","py":"ɡuì","duan":[{"e":"資也。","n":"按篇、韵皆云賭也。許無賭字。"}]},"資":{"expl":"貨也。从貝次聲。","rad":"貝","fq":"卽夷切","vol":"06","py":"zī","duan":[{"e":"貨也。","n":"貨者、化也。資者、積也。旱則資舟。水則資車。夏則資皮。冬則資絺綌。皆居積之謂。資者、人之所藉也。周禮注曰。資、取也。老子曰。善人、不善人之師。不善人、善人之資。"}]},"贎":{"expl":"貨也。从貝萬聲。","rad":"貝","fq":"無販切","vol":"06","py":"wàn","duan":[{"e":"貨也。","n":"廣韵云。贈貨。"}]},"賑":{"expl":"富也。从貝辰聲。","rad":"貝","fq":"之忍切","vol":"06","py":"zhèn","duan":[{"e":"富也。","n":"見釋言。郭曰。謂隱賑富有。西京賦。鄉邑殷賑。薛曰。謂富饒也。匡謬正俗曰。振給、振貸字皆作振。振、舉救也。俗作賑。非。"}]},"賢":{"expl":"多才也。从貝臤聲。","rad":"貝","fq":"胡田切","vol":"06","py":"xián","duan":[{"e":"多財也。","n":"財各本作才。今正。賢本多財之偁。引伸之凡多皆曰賢。人偁賢能、因習其引伸之義而廢其本義矣。小雅。大夫不均。我從事獨賢。傳曰。賢、勞也。謂事多而勞也。故孟子說之曰。我獨賢勞。戴先生曰。投壷。某賢於某若干純。賢、多也。"}]},"賁":{"expl":"飾也。从貝卉聲。","rad":"貝","fq":"彼義切","vol":"06","py":"bì","duan":[{"e":"飾也。","n":"易象傳曰。山下有火賁。序卦傳曰。賁、飾也。按古假賁爲奔。"}]},"賀":{"expl":"以禮相奉慶也。从貝加聲。","rad":"貝","fq":"胡箇切","vol":"06","py":"hè","duan":[{"e":"㠯禮物相奉慶也。","n":"物字依韵會、玉篇補。相奉慶、玉篇作相慶加、爲長。心部曰。慶行賀人也。是慶與賀二字互訓。賀之言加也。猶贈之言增也。古假賀爲嘉。覲禮。余一人嘉之。今文嘉作賀是也。廣韵曰。賀、擔也。勞也。此謂或假賀爲儋何字也。儋何、俗作擔荷。"}]},"蔦":{"expl":"寄生也。从艸鳥聲。《詩》曰：“蔦與女蘿。”","rad":"艸","fq":"都了切","vol":"01","py":"niǎo","duan":[{"e":"寄生艸也。","n":"艸字各本脫。依毛詩音義及韵會補。小雅傳曰。蔦、寄生也。陸璣曰。蔦一名寄生。葉似當盧。子如覆盆子。本艸經。桑上寄生。一名寓木。一名宛童。按寓木、宛童見釋木。"}]},"貢":{"expl":"獻功也。从貝工聲。","rad":"貝","fq":"古送切","vol":"06","py":"ɡònɡ","duan":[{"e":"獻功也。","n":"貢功曡韵。魯語曰。社而賦事。烝而獻功。韋注。社、春分祭社也。事、農桑之屬也。冬祭曰烝。烝而獻五榖布帛之屬也。周禮八則治都鄙。六曰賦貢以馭其用。注云。貢、功也。九職之功所税也。按大宰以九貢致邦國之用。凡其所貢皆民所有事也。故職方氏曰。制其貢。各以其所有。"}]},"贊":{"expl":"見也。从貝从兟。","rad":"貝","fq":"則旰切","vol":"06","py":"zàn","duan":[{"e":"見也。","n":"此以疊韵爲訓。疑當作所以見也。謂彼此相見必資贊者。士冠禮贊冠者、士昏禮贊者、注皆曰。贊、佐也。周禮大宰注曰。贊、助也。是則凡行禮必有贊。非獨相見也。"}]},"賮":{"expl":"會禮也。从貝纬聲。","rad":"貝","fq":"徐刃切","vol":"06","py":"jìn","duan":[{"e":"會禮也。","n":"以財貨爲會合之禮也。蒼頡篇曰。賮、財貨也。張載注魏都賦曰。賮禮贄也。又孟子曰。行者必以賮。辭曰餽賮。或假進爲之。如漢高紀曰簫何爲主吏、主進是也。"}]},"齎":{"expl":"持遺也。从貝齊聲。","rad":"貝","fq":"祖雞切","vol":"06","py":"jī","duan":[{"e":"持遺也。","n":"周禮掌皮。歲終則會其財齎。注。予人以物曰齎。今時詔書或曰齎計吏。鄭司農云。齎或爲資。外府。共其財用之幣齎。注。齎、行道之財用也。聘禮曰。問幾月之齎。鄭司農云。齎或爲資。今禮家定齎作資。玄謂齎資同耳。其字以齊次爲聲。從貝變易。古字亦多或。玉裁按。此鄭君不用許書說。謂齎資一字。聲義皆同也。許則釋資爲貨。釋齎爲持而予之。其義分別。不爲一字。近人則訓齎爲持矣。"}]},"貸":{"expl":"施也。从貝代聲。","rad":"貝","fq":"他代切","vol":"06","py":"dài","duan":[{"e":"施也。","n":"謂我施人曰貸也。"}]},"貣":{"expl":"从人求物也。从貝弋聲。","rad":"貝","fq":"他得切","vol":"06","py":"tè","duan":[{"e":"從人求物也。","n":"從人猶向人也。謂向人求物曰貣也。按代弋同聲。古無去入之別。求人施人。古無貣貸之分。由貣字或作貸。因分其義。又分其聲。如求人曰乞。給人之求亦曰乞。今分去訖、去旣二音。又如假借二字、皆爲求者予者之通名。唐人亦有求讀上入、予讀兩去之說。古皆未必有是。貣別爲貸。又以改竄許書。尤爲異耳。經史內貣貸錯出。恐皆俗增人旁。？字經典釋文、五經文字皆作？。俗作？。亦其證也。周禮泉府。凡民之貸者。注云。貸者謂從官借本賈也。廣韵卄五德云。貣謂從官借本賈也。其所據周禮正作貣。而周禮注中借者予者同用一字。釋文別其音。亦可知本無二字矣。"}]},"賂":{"expl":"遺也。从貝各聲。","rad":"貝","fq":"洛故切","vol":"06","py":"lù","duan":[{"e":"遺也。","n":"見魯頌大賂傳。箋云。大猶廣也。廣賂者、賂君及卿大夫也。按以此遺彼曰賂。如道路之可往來也。貨賂皆謂物。其用之則有公私衺正之不同。"}]},"賸":{"expl":"物相增加也。从貝朕聲。一曰送也，副也。","rad":"貝","fq":"以證切","vol":"06","py":"shènɡ","duan":[{"e":"物相增加也。","n":"賸增曡韵。以物相益曰賸。字之本義也。今義訓爲贅疣。與古義小異、而實古義之引伸也。改其字作剩而形異矣。"}]},"贈":{"expl":"玩好相送也。从貝曾聲。","rad":"貝","fq":"昨鄧切","vol":"06","py":"zènɡ","duan":[{"e":"玩好相送也。","n":"贈送曡韵。秦風渭陽、大雅韓奕皆云何以贈之。毛傳、鄭箋皆云。贈、送也。崧高云。以贈申伯。傳云。贈、增也。增與送義異而同。猶賸之訓增亦訓送也。旣夕禮云。知死者贈。知生者賻。何休云。知死者賵賻。知生者贈襚。按以玩好送死者亦贈之一端也。今人以物贈人曰送。送亦古語也。"}]},"貱":{"expl":"迻予也。从貝皮聲。","rad":"貝","fq":"彼義切","vol":"06","py":"bì","duan":[{"e":"迻予也。","n":"迻、遷徙也。展轉寫之曰迻書。展轉予人曰迻予。貱迻曡韵。"}]},"芸":{"expl":"艸也。似目宿。从艸云聲。《淮南子》說：“芸艸可以死復生。”","rad":"艸","fq":"王分切","vol":"01","py":"yún","duan":[{"e":"艸也。佀目宿。","n":"夏小正。正月采芸。爲廟采也。二月榮芸。月令。仲冬芸始生。注。芸、香艸。高注淮南、呂覽皆曰。芸、芸蒿。菜名也。呂覽曰。菜之美者、陽華之芸。注。芸、芳菜也。賈思勰引倉頡解詁曰。芸蒿似斜蒿。可食。沈括曰。今謂之七里香者是也。葉類豌豆。其葉極芬香。古人用以藏書辟蠧。採置席下。能去蚤蝨。"}]},"𥫔":{"expl":"賜也。从貝，竷省聲。","rad":"貝","fq":"古送切","vol":"06","py":"ɡònɡ","duan":[{"e":"賜也。","n":"釋詁曰。𥫔、賜也。據釋文本作𥫔。後人改作貢耳。端木賜字子𥫔。凡作子貢者、亦皆後人所改。淮南道應、要略二訓注皆云。𥫔、賜也。"}]},"賚":{"expl":"賜也。从貝來聲。《周書》曰：“賚尒秬鬯。”","rad":"貝","fq":"洛帶切","vol":"06","py":"lài","duan":[{"e":"賜也。","n":"釋詁。賚貢錫畀予況賜也。又曰。賚予也。小雅毛傳云。賚、予也。大雅傳云。釐、賜也。釐者、賚之假借也。"}]},"賞":{"expl":"賜有功也。从貝尚聲。","rad":"貝","fq":"書兩切","vol":"06","py":"shǎnɡ","duan":[{"e":"賜有功也。","n":"鍇曰。賞之言尚也。尚其功也。"}]},"賜":{"expl":"予也。从貝易聲。","rad":"貝","fq":"斯義切","vol":"06","py":"cì","duan":[{"e":"予也。","n":"釋詁。賚貢錫畀予況賜也。七字轉注。凡經傳云錫者、賜之假借也。公羊傳曰。錫者何。賜也。賜者、與之通稱。禹貢。納錫大龜。乃下與上之詞。又玉藻言賜君子、與小人者、別言之。統言則不別也。方言曰。賜、盡也。此借賜爲澌。澌、盡也。盡之字俗作儩。"}]},"貤":{"expl":"重次弟物也。从貝也聲。","rad":"貝","fq":"以豉切","vol":"06","py":"yì","duan":[{"e":"重次弟物也。","n":"漢書注引作物之重次弟也。重次弟者、旣次弟之又因而重之也。漢武帝詔曰。受爵賞而欲移賣者、無所流貤。應劭訓貤爲移。上林賦說果樹曰。貤丘陵。下平原。郭樸曰。貤、猶延也。按賣爵者展轉與人。蔓莚丘陵者層曡茲長。皆重次弟之意也。毛詩施于中谷、施于孫子、皆當作貤。"}]},"贏":{"expl":"有餘、賈利也。从貝𦝠聲。","rad":"貝","fq":"以成切","vol":"06","py":"yínɡ","duan":[{"e":"賈有餘利也。","n":"依韵會本訂。左傳曰。賈而欲贏。而惡囂乎。俗語謂贏者輸之對。"}]},"賴":{"expl":"贏也。从貝剌聲。","rad":"貝","fq":"洛帶切","vol":"06","py":"lài","duan":[{"e":"贏也。","n":"高帝紀。始大人常㠯臣亡賴。應曰。賴者、恃也。晉曰。許愼云賴、利也。無利入於家也。或曰。江淮之閒謂小兒多詐狡獪爲亡賴。按今人云無賴者、謂其無衣食致然耳。方言云。賴、讎也。南楚之外曰賴。賴、取也。"}]},"負":{"expl":"恃也。从人守貝，有所恃也。一曰受貸不償。","rad":"貝","fq":"房九切","vol":"06","py":"fù","duan":[{"e":"恃也。","n":"左傳曰。昔秦人負恃其衆。貪於土地。逐我諸戎。孟子曰。虎負隅。莫之敢攖。"}]},"貯":{"expl":"積也。从貝宁聲。","rad":"貝","fq":"直呂切","vol":"06","py":"zhù","duan":[{"e":"積也。","n":"此與宁音義皆同。今字專用貯矣。周禮注作？。俗字也。"}]},"貳":{"expl":"副、益也。从貝弍聲。弍，古文二。","rad":"貝","fq":"而至切","vol":"06","py":"èr","duan":[{"e":"副益也。","n":"當云副也。益也。周禮注。副、貳也。說詳刀部。"}]},"䔴":{"expl":"艸也。从艸𠭥聲。","rad":"艸","fq":"麤最切","vol":"01","py":"cè","duan":[{"e":"艸也。从艸。𠭥聲。","n":"麤最切。十五部。"}]},"賓":{"expl":"所敬也。从貝𡧍聲。","rad":"貝","fq":"必鄰切","vol":"06","py":"bīn","duan":[{"e":"所敬也。","n":"大宰。八統。八曰禮賔。大宗伯。以賔禮親邦國賔客。渾言之也。析言者之則賔客異義。又賔謂所敬之人。因之敬其人亦曰賔。又君爲主。臣爲賔。故老子曰。樸雖小、天下莫能臣也。矦王若能守之。萬物將自賔。司馬相如引詩。率土之賔。莫非王臣。"}]},"賖":{"expl":"貰買也。从貝余聲。","rad":"貝","fq":"式車切","vol":"06","py":"shē","duan":[{"e":"貰買也。","n":"貰買者、在彼爲貰。在我則爲賖也。周禮泉府。凡賖者祭祀無過旬日。喪紀無過三月。鄭司農云賖、貰也。"}]},"貰":{"expl":"貸也。从貝丗聲。","rad":"貝","fq":"神夜切","vol":"06","py":"shì","duan":[{"e":"貸也。","n":"泉府以凡賖者與凡民之貸者竝言。然則賖與貸有別。賖、貰也。若今人云賖是也。貸、借也。若今人云借是也。其事相類。故許渾言之曰貰、貸也。高祖本紀。常從武負王媪貰酒。韋昭曰。貰、賖也。按賖貰皆紓緩之詞。"}]},"贅":{"expl":"以物質錢。从敖、貝。敖者，猶放；貝，當復取之也。","rad":"貝","fq":"之芮切","vol":"06","py":"zhuì","duan":[{"e":"㠯物質錢。","n":"若今人之抵押也。漢嚴助傳。賣爵贅子。以接衣食。如淳曰。淮南俗賣子與人作奴婢名爲贅子。三年不能贖遂爲奴婢。按大雅傳曰。贅、屬也。謂贅爲綴之假借也。孟子。屬其耆老。大傳作贅其耆老。公羊傳云。君若贅旒。史、漢云。贅壻。此爲䏈屬之偁。又莊子云。附贅縣肬。老子云。餘食贅行。此爲餘賸之偁。皆綴字之假借。"}]},"質":{"expl":"以物相贅。从貝从斦。闕。","rad":"貝","fq":"之日切","vol":"06","py":"zhì","duan":[{"e":"㠯物相贅。","n":"質贅雙聲。以物相贅、如春秋交質子是也。引伸其義爲樸也、地也。如有質有文是。小雅毛傳云旳質也、周禮射則充椹質、左傳策名委質、皆是。又緜詩、抑詩傳曰。質、成也。禮謂平明爲質明。"}]},"貿":{"expl":"易財也。从貝戼聲。","rad":"貝","fq":"莫𠊱切","vol":"06","py":"mào","duan":[{"e":"易財也。","n":"衞風。抱布貿絲。咎繇謨。貿遷有無化居。"}]},"贖":{"expl":"貿也。从貝𧸇聲。","rad":"貝","fq":"殊六切","vol":"06","py":"shú","duan":[{"e":"貿也。","n":"堯典。金作贖㓝。"}]},"費":{"expl":"𢿱財用也。从貝弗聲。","rad":"貝","fq":"房未切","vol":"06","py":"fèi","duan":[{"e":"散財用也。","n":"論語曰。君子惠而不費。"}]},"責":{"expl":"求也。从貝朿聲。","rad":"貝","fq":"側革切","vol":"06","py":"zé","duan":[{"e":"求也。","n":"引伸爲誅責、責任。周禮小宰。聽稱責以傅別。稱責、卽今之舉債。古無債字。俗作債。則聲形皆異矣。"}]},"賈":{"expl":"賈市也。从貝襾聲。一曰坐賣售也。","rad":"貝","fq":"公戶切","vol":"06","py":"ɡǔ","duan":[{"e":"賈、","n":"此複舉字之未刪者。"}]},"葎":{"expl":"艸也。从艸律聲。","rad":"艸","fq":"呂戌切","vol":"01","py":"lǜ","duan":[{"e":"艸也。","n":"唐本艸曰。葛葎蔓。宋本艸曰。葛勒蔓。似葛有刺。"}]},"𧶜":{"expl":"行賈也。从貝，商省聲。","rad":"貝","fq":"式陽切","vol":"06","py":"shānɡ","duan":[{"e":"行賈也。","n":"白虎通曰。商賈何謂也。商之爲言章也。章其遠近。度其有亡。通四方之物。故謂之商也。賈之爲言固也。固其有用之物。以待民來。以求其利者也。通物曰商、居賣曰賈。按白虎通古本如是。漢律曆志。商、章也。物成？可章度也。尚書。我商賚女。徐邈商音章。㕯部商從章聲。皆可證。？俗作？。經傳皆作商。商行而？廢矣。渾言之則？賈可互偁。析言之則行賈曰？。行賈者、通四方之珍異以資之。"}]},"販":{"expl":"買賤賣貴者。从貝反聲。","rad":"貝","fq":"方願切","vol":"06","py":"fàn","duan":[{"e":"買賤賣貴者。","n":"司市曰。夕市、夕時而市。販夫販婦爲主。注云。販夫販婦朝資夕賣。按資猶取也。"}]},"買":{"expl":"市也。从网、貝。《孟子》曰：“登壟斷而网市利。”","rad":"貝","fq":"莫蟹切","vol":"06","py":"mǎi","duan":[{"e":"市也。","n":"市者、買物之所。因之買物亦言市。論語。沽酒市脯。"}]},"賤":{"expl":"賈少也。从貝戔聲。","rad":"貝","fq":"才線切","vol":"06","py":"jiàn","duan":[{"e":"賈少也。","n":"賈、今之價字。"}]},"賦":{"expl":"斂也。从貝武聲。","rad":"貝","fq":"方遇切","vol":"06","py":"fù","duan":[{"e":"斂也。","n":"周禮大宰。以九賦斂財賄。斂之曰賦。班之亦曰賦。經傳中凡言以物班布與人曰賦。"}]},"貪":{"expl":"欲物也。从貝今聲。","rad":"貝","fq":"他含切","vol":"06","py":"tān","duan":[{"e":"欲物也。","n":"心部惏、女部婪皆訓貪。"}]},"貶":{"expl":"損也。从貝从乏。","rad":"貝","fq":"方斂切","vol":"06","py":"biǎn","duan":[{"e":"損也。从貝。𠂜聲。","n":"形聲包會意也。鉉本作從貝從乏。方斂切。杜林作𦥘。"}]},"貧":{"expl":"財分少也。从貝从分，分亦聲。","rad":"貝","fq":"符巾切","vol":"06","py":"pín","duan":[{"e":"財分少也。","n":"謂財分而少也。合則見多。分則見少。富、備也、厚也。則貧者、不備、不厚之謂。"}]},"賃":{"expl":"庸也。从貝任聲。","rad":"貝","fq":"尼禁切","vol":"06","py":"lìn","duan":[{"e":"庸也。","n":"庸者今之傭字。廣韵曰。傭、餘封切。傭、賃也。凡僱僦皆曰庸、曰賃。"}]},"賕":{"expl":"以財物枉法相謝也。从貝求聲。一曰戴質也。","rad":"貝","fq":"巨畱切","vol":"06","py":"qiú","duan":[{"e":"㠯財物枉法相謝也。","n":"枉法者、違法也。法當有罪、而以財求免、是曰賕。受之者亦曰賕。吕㓝。五過之疵惟來。馬本作惟求。云有請賕也。按上文惟貨者、今之不枉法贓也。惟求者、今之枉法贓也。"}]},"茦":{"expl":"莿也。从艸朿聲。","rad":"艸","fq":"楚革切","vol":"01","py":"cì","duan":[{"e":"莿也。","n":"茦刺見釋艸。刺不從艸。方言曰。凡艸木刺人。北燕朝鮮之閒謂之策。或謂之壯。按木𦬆曰朿。艸𦬆曰茦。因木𦬆之字爲義與聲也。但許君上下文皆係艸名。不當泛釋凡艸之刺。或因上文葎艸有刺聯及之。或自有艸名茦。一名莿。與方言異義。未可定也。"}]},"購":{"expl":"以財有所求也。从貝冓聲。","rad":"貝","fq":"古𠊱切","vol":"06","py":"ɡòu","duan":[{"e":"㠯財有所求也。","n":"縣重價以求得其物也。漢律。能捕豺貀、購錢百。"}]},"䝪":{"expl":"齎財卜問爲䝪。从貝疋聲。讀若所。","rad":"貝","fq":"疏舉切","vol":"06","py":"shǔ","duan":[{"e":"齎財⺊問爲䝪。","n":"卜問、廣韵作問⺊。史記貨殖傳。毉方諸食技術之人。焦神竭能。爲重糈也。日者傳。⺊而有不審。不見奪糈。按糈皆當作䝪。同音假借。䝪所以讎⺊者也。祭神米曰糈。卜者必禮神。故其字亦作糈。"}]},"貲":{"expl":"小罰以財自贖也。从貝此聲。漢律：民不繇，貲錢二十二。","rad":"貝","fq":"卽夷切","vol":"06","py":"zī","duan":[{"e":"小罰㠯財自贖也。","n":"貲字本義如是。引伸爲凡財貨之偁。"}]},"賨":{"expl":"南蠻賦也。从貝宗聲。","rad":"貝","fq":"徂紅切","vol":"06","py":"cónɡ","duan":[{"e":"南蠻賦也。","n":"後漢書南蠻西南夷傳曰。槃瓠之傳蠻夷。秦置黔中郡。漢改爲武陵。歲令大人輸布一匹。小口二丈。是謂賨布。魏都賦曰。賨幏積墆。幏見巾部。"}]},"𧸇":{"expl":"衒也。从貝𡍬聲。𡍬，古文睦。讀若育。","rad":"貝","fq":"余六切","vol":"06","py":"yù","duan":[{"e":"𧗳也。","n":"𧗳、行且賣也。𧸇字不見經傳。周禮多言儥。儥訓買。亦訓賣。胥師飾行儥慝。賈師貴儥者。葢卽說文之賣字。而說文人部儥、見也。則今之覿字也。玉篇云。賣或作粥鬻。是賣鬻爲古今字矣。按𧸇𣜩變作賣。易與賣相混。"}]},"貴":{"expl":"物不賤也。从貝臾聲。臾，古文蕢。","rad":"貝","fq":"居胃切","vol":"06","py":"ɡuì","duan":[{"e":"物不賤也。从貝。臾聲。","n":"居胃切。十五部。"}]},"賏":{"expl":"頸飾也。从二貝。","rad":"貝","fq":"烏莖切","vol":"06","py":"yīnɡ","duan":[{"e":"頸飾也。从二貝。","n":"騈貝爲飾也。烏莖切。十一部。"}]},"貺":{"expl":"賜也。从貝兄聲。","rad":"貝","fq":"許訪切","vol":"06","py":"kuànɡ","duan":[]},"賵":{"expl":"贈死者。从貝从冒。冒者，衣衾覆冒之意。","rad":"貝","fq":"撫鳳切","vol":"06","py":"fènɡ","duan":[]},"賭":{"expl":"博簺也。从貝者聲。","rad":"貝","fq":"當古切","vol":"06","py":"dǔ","duan":[]},"䒷":{"expl":"䒷婁，果蓏也。从艸𠯑聲。","rad":"艸","fq":"古活切","vol":"01","py":"ɡuā","duan":[{"e":"䒷蔞、","n":"逗。"}]},"貼":{"expl":"以物爲質也。从貝占聲。","rad":"貝","fq":"他叶切","vol":"06","py":"tiē","duan":[]},"貽":{"expl":"贈遺也。从貝台聲。經典通用詒。","rad":"貝","fq":"與之切","vol":"06","py":"yí","duan":[]},"𧸖":{"expl":"重買也，錯也。从貝廉聲。","rad":"貝","fq":"佇陷切","vol":"06","py":"zhuàn","duan":[]},"賽":{"expl":"報也。从貝，塞省聲。","rad":"貝","fq":"先代切","vol":"06","py":"sài","duan":[]},"賻":{"expl":"助也。从貝尃聲。","rad":"貝","fq":"符遇切","vol":"06","py":"fù","duan":[]},"贍":{"expl":"給也。从貝詹聲。","rad":"貝","fq":"時豔切","vol":"06","py":"shàn","duan":[]},"邑":{"expl":"國也。从囗；先王之制，尊卑有大小，从卪。凡邑之屬皆从邑。","rad":"邑","fq":"於汲切","vol":"06","py":"yì","duan":[{"e":"國也。","n":"鄭莊公曰。吾先君新邑於此。左傳凡偁人曰大國。凡自偁曰敝邑。古國邑通偁。白虎通曰。夏曰夏邑。商曰商邑。周曰京師。尚書曰西邑夏、曰天邑商、曰作新大邑於東國雒皆是。周禮。四井爲邑。左傳。凡邑有宗廟先君之主曰都、無曰邑。此又在一國中分析言之。"}]},"邦":{"expl":"國也。从邑丰聲。","rad":"邑","fq":"博江切","vol":"06","py":"bānɡ","duan":[{"e":"國也。","n":"周禮注曰。大曰邦、小曰國。析言之也。許云。邦、國也。國、邦也。統言之也。周禮注又云。邦之所居亦曰國。此謂統言則封竟之內曰國曰邑。析言則國野對偁。周禮體國經野是也。古者城？所在曰國、曰邑。而不曰邦。邦之言封也。古邦封通用。書序云。邦康叔。邦諸矦。論語云。在邦域之中。皆封字也。周禮故書。乃分地邦而辨其守地。邦謂土畍。杜子春改邦爲域。非也。"}]},"郡":{"expl":"周制：天子地方千里，分爲百縣，縣有四郡。故《春秋傳》曰“上大夫受郡”是也。至秦初置三十六郡，以監其縣。从邑君聲。","rad":"邑","fq":"渠運切","vol":"06","py":"jùn","duan":[{"e":"周制。天子地方千里。分爲百縣。縣有四郡。","n":"逸周書作雒篇曰。千里百縣。縣有四郡。高注六月紀云。周制。天子畿內方千里。分爲百縣。縣有四郡。郡有監。故春秋傳曰。上大夫受縣。下大夫受郡。周時縣大郡小。至秦始皇兼天下。初置三十六郡以監縣耳。按作雒篇與周禮不合。鄭注月令但云。四監、主山林川澤之官。百縣、鄉遂之屬。是不從作雒說也。"}]},"都":{"expl":"有先君之舊宗廟曰都。从邑者聲。周禮：距國五百里爲都。","rad":"邑","fq":"當孤切","vol":"06","py":"dū","duan":[{"e":"有先君之舊宗廟曰都。","n":"左傳曰。凡邑有宗廟先君之主曰都、無曰邑。周禮大司徒注曰。都鄙者、王子弟公卿大夫采地。其畍曰都。鄙、所居也。載師注曰。家邑、大夫之采地。小都、卿之采地。大都、公之采地。王子弟所食邑也。大宰八則注曰。都鄙、公卿大夫之采邑。王子弟所食邑。周召毛耼畢原之屬在畿內者。祭祀者其先君社稷五祀。按據杜氏釋例。大曰都。小曰邑。雖小而有宗廟先君之主曰都。尊其所居而大之也。又按左氏言有宗廟先君之主曰都。許改云有先君之舊宗廟。則必如晉之曲沃故絳而後可偁都。恐非左氏意也。左氏與周官合。"}]},"葑":{"expl":"須從也。从艸封聲。","rad":"艸","fq":"府容切","vol":"01","py":"fēnɡ","duan":[{"e":"須從也。","n":"邶風。采葑采菲。毛傳曰。葑、須也。釋艸曰。須、逗葑蓯。說文曰。葑、須從也。三家互異而皆不誤。葑須爲雙聲。葑從爲曡韵。單𧦝之爲葑。絫𧦝之爲葑從。單𧦝之爲須。絫𧦝之爲須從。語言之不同也。或許所據爾雅與今本異矣。坊記注云。葑、蔓菁也。陳宋之閒謂之葑。方言云。蘴蕘、蕪菁也。陳、楚之郊謂之蘴。郭注。蘴舊音蜂。今江東音嵩。字作菘也。玉裁按。蘴菘皆卽葑字。音讀稍異耳。須從正切菘字。陸佃、嚴粲、羅願皆言在南爲菘。在北爲蕪菁、蔓菁。若菰葑讀去聲。別是一物。"}]},"鄰":{"expl":"五家爲鄰。从邑粦聲。","rad":"邑","fq":"力珍切","vol":"06","py":"lín","duan":[{"e":"五家爲鄰。","n":"見遂人職。按引伸爲凡親密之偁。"}]},"酇":{"expl":"百家爲酇。酇，聚也。从邑贊聲。南陽有酇縣。","rad":"邑","fq":"作管切","vol":"06","py":"zuǎn","duan":[{"e":"百家爲酇。","n":"遂人。五家爲鄰。五鄰爲里。四里爲酇。五酇爲鄙。五鄙爲縣。五縣爲遂。"}]},"鄙":{"expl":"五酇爲鄙。从邑啚聲。","rad":"邑","fq":"兵美切","vol":"06","py":"bǐ","duan":[{"e":"五酇爲鄙。","n":"見遂人。五百家也。又周禮都鄙、王子弟公卿大夫采地。其畍曰都。鄙、所居也。按大司徒以邦國、都鄙對言。鄭注以邦之所居曰國、都之所居曰鄙對言。春秋經傳鄙字多訓爲邊者。葢周禮都鄙歫國五百里。在王畿之邊。故鄙可釋爲邊。又引伸爲輕薄之偁。而鄙夫字古作啚。冣目云俗儒啚夫翫其所習、可證也。今則鄙行而啚廢矣。"}]},"郊":{"expl":"距國百里爲郊。从邑交聲。","rad":"邑","fq":"古肴切","vol":"06","py":"jiāo","duan":[{"e":"歫國百里爲郊。","n":"杜子春注周禮曰。五十里爲近郊。百里爲遠郊。玉藻說郊祭曰。於郊、故謂之郊。"}]},"邸":{"expl":"屬國舍。从邑氐聲。","rad":"邑","fq":"都禮切","vol":"06","py":"dǐ","duan":[{"e":"屬國舍也。","n":"文帝紀曰。入代邸。顏注曰。郡國朝宿之舍在京師者率名邸。邸、至也。言所歸至也。按今俗謂旅舍爲邸。經典假借邸爲柢。如典瑞四圭有邸是也。釋器。邸謂之柢。當作秪謂之邸。釋言曰。柢、本也。鄭司農引作邸本也可證。爾雅皆釋經之辭。"}]},"郛":{"expl":"郭也。从邑孚聲。","rad":"邑","fq":"甫無切","vol":"06","py":"fú","duan":[{"e":"𩫏也。","n":"𩫏各本作郭。今正。公羊傳入其郛注。郛、恢郭也。城外大郭也。"}]},"郵":{"expl":"境上行書舍。从邑、垂。垂，邊也。","rad":"邑","fq":"羽求切","vol":"06","py":"yóu","duan":[{"e":"竟上行書舍。","n":"孟子。德之流行。速於置郵而傳命。釋言。郵、過也。按經過與過失、古不分平去。故經過曰郵。過失亦曰郵。爲尤訧之假借字。"}]},"𨛍":{"expl":"國甸，大夫稍。稍，所食邑。从邑肖聲。《周禮》曰：“任𨛍地。”在天子三百里之内。","rad":"邑","fq":"所教切","vol":"06","py":"shào","duan":[{"e":"國甸。大夫稍稍所食邑。","n":"載師注曰。故書稍或作削。按削當是𨛍之誤。許所據正故書或本也。太宰家削之賦當作家𨛍。釋文曰。家削本又作𨛍是也。按國甸之下疑有奪文。大宰曰。三曰邦甸之賦。四曰家𨛍之賦。載師曰。以公邑之田任甸地。以家邑之田任𨛍地。此云國甸、卽經之邦甸也。邦甸去國二百里。家𨛍三百里。此當云國甸之外曰家𨛍。大夫稍稍所食邑。鄭曰。家邑、大夫之采地也。稍與𨛍曡韵。"}]},"鄯":{"expl":"鄯善，西胡國也。从邑从善，善亦聲。","rad":"邑","fq":"時戰切","vol":"06","py":"shàn","duan":[{"e":"鄯善、","n":"逗。"}]},"𥨪":{"expl":"夏后時諸矦夷羿國也。从邑，窮省聲。","rad":"邑","fq":"渠弓切","vol":"06","py":"qiónɡ","duan":[{"e":"夏后時諸矦夷羿國也。","n":"弓部曰。𢏗、帝嚳䠶官。夏少康滅之。羽部曰。𦐧、羽之𦐧風。亦古諸矦也。按𢏗𦐧古通用。云帝嚳射官而夏少康滅之。則夏之夷羿卽帝嚳䠶官之後裔明矣。夷羿見左傳虞箴。左傳。魏絳云。夏訓有之曰。有竆后羿。昔有夏方衰。后羿自鉏遷於窮石。因夏民以代夏政。寒浞殺羿。靡滅浞。立少康。有窮由是遂亡。今左傳作窮。許所據作𥨪。今古字也。左氏之𥨪石。杜不言其地所在。葢非山海經、離騷、淮南子所云弱水所出之窮石也。地理志、說文皆云弱水出張掖山丹。則山海經、離騷、淮南子所云竆石當在山丹。漢山丹今爲甘州府山丹縣。歫夏都安邑甚遠。然許鄯善之下卽出𥨪字。固謂西北邊地。"}]},"丕":{"expl":"大也。从一不聲。","rad":"一","fq":"敷悲切","vol":"01","py":"pī","duan":[{"e":"大也。","n":"見釋詁。"}]},"䃾":{"expl":"以豚祠司命。从示比聲。漢律曰：“祠䃾司命。”","rad":"示","fq":"卑履切","vol":"01","py":"bǐ","duan":[{"e":"㠯豚祠司命也。","n":"鄭注周禮曰。求福曰禱。得求曰祠。此祠與春祭之祠異。祭法注曰。司命小神、居人之閒。司察小過。作讉吿者。主督察三命。今時民家或春秋祀司命。風俗通義曰。周禮。司命、文昌也。今民閒祀司命。刻木長尺二寸爲人像。行者擔篋中。居者別作小屋。齊地大尊重之。汝南餘郡亦多有。皆祠以䐗。率以春秋之月。按䐗同豬。許所謂豚也。應說司命爲文昌。鄭說人閒小神。未知許意何居也。許君𥨫字下說周禮以𥨫祀祝融。用賈逵句𦬆祀於戸、祝融祀於𥨫、蓐收祀於門、玄冥祀於井、后土祀於中𩅸之說。鄭則云老婦之祭報先炊之義。𣃔非祝融。然則許不必同鄭也。"}]},"薺":{"expl":"蒺棃也。从艸齊聲。《詩》曰：“牆有薺。”","rad":"艸","fq":"疾咨切","vol":"01","py":"cí","duan":[{"e":"疾黎也。","n":"今詩鄘風、小雅皆作茨。釋艸、傳、箋皆曰。茨、蒺藜也。易曰。據于蒺藜。陶隱居曰。子有刺。軍家鑄鐵作之。以布敵路。亦呼蒺藜。"}]},"𨜒":{"expl":"周封黃帝之後於𨜒也。从邑契聲。讀若薊。上谷有𨜒縣。","rad":"邑","fq":"古詣切","vol":"06","py":"jì","duan":[{"e":"周封黃帝之後於𨜒也。","n":"樂記曰。武王克殷及商未及下車而封黃帝之後於薊。按𨜒薊古今字也。薊行而𨜒廢矣。漢地理志、郡國志皆作薊。則其字假借久矣。陸德明曰。薊、今涿郡薊縣是也。卽燕國之都也。孔安國司馬遷及鄭皆云。燕召皆與周同姓。案黃帝姓姬。君奭葢其後也。或黃帝之後封薊者滅絕。而更封燕召公乎。疑不能明也。而皇甫謐以召公爲文王之庶子。記傳更無所出。又左傳富辰言文王之昭亦無燕。玉裁按。地理志曰。廣陽國薊、燕召公所封。然則班意謂封黃帝之後卽召公也。而周本紀以封堯後於薊、封召公奭於燕竝言。張守節疑薊爲燕所幷。未知其審。"}]},"邰":{"expl":"炎帝之後，姜姓所封，周棄外家國。从邑台聲。右扶風斄縣是也。《詩》曰：“有邰家室。”","rad":"邑","fq":"土來切","vol":"06","py":"tái","duan":[{"e":"炎帝之後姜姓所封。周棄外家國。","n":"大雅。有邰家室。毛傳曰。邰、姜嫄之國也。堯見天因邰而生后稷。故國后稷於邰。使事天以顯神、順天命。是則邰本后稷外家之國名。炎帝之後姜姓所封也。國后稷於邰時、葢國姜姓於他處矣。至武王克殷。興滅國。繼絕世。乃封神農之後於焦。"}]},"𨙸":{"expl":"周文王所封。在右扶風美陽中水鄉。从邑支聲。","rad":"邑","fq":"巨支切","vol":"06","py":"qí","duan":[{"e":"周文王所封。在右扶風美陽中水鄉。","n":"經典有岐無𨙸。惟漢地理志曰。大王徙𨙸。文王作酆。匈奴傳曰。秦襄公伐戎至𨙸。師古曰。𨙸古岐字。岐專行而𨙸廢矣。許所見豳岐作𨙸。猶所見薊作𨜒也。地理志曰。右扶風美陽、禹貢岐山在西北。中水鄉、周大王所邑。魯頌箋曰。大王自豳徙居岐山之陽。按此云文王所封。要其終而言。皇矣詩曰。度其鮮原。居岐之陽。箋云。乃始謀居善原廣平之地。亦在岐山之南也。文王自𨙸遷酆。非文王始國𨙸也。下云酆、周文王所都。則此當云大王矣。戴先生曰。美陽今爲陜西鳳翔府岐山、扶風二縣。漢志。美陽。岐山在西北。今岐山縣東七十里岐山是。"}]},"邠":{"expl":"周太王國。在右扶風美陽。从邑分聲。","rad":"邑","fq":"補巾切","vol":"06","py":"bīn","duan":[{"e":"周大王國。在右扶風美陽。从邑。分聲。","n":"補巾切。十三部。"}]},"郿":{"expl":"右扶風縣。从邑眉聲。","rad":"邑","fq":"武悲切","vol":"06","py":"méi","duan":[{"e":"右扶風縣。","n":"前後二志同。大雅。申伯信邁。王餞于郿。毛云。郿地。箋云。時王葢省岐周。故于郿云。正義云。申在鎬京之東南。自鎬適申。塗不經郿。時宣王葢省視岐周。申伯從王至岐。自岐餞之。按今鳳翔府郿縣縣東北十五里渭水之北有故郿城。"}]},"郁":{"expl":"右扶風郁夷也。从邑有聲。","rad":"邑","fq":"於六切","vol":"06","py":"yù","duan":[{"e":"右扶風郁夷也。","n":"見地理志。班引詩。周道郁夷。師古曰。毛詩周道倭遟。韓詩作郁夷字。言使臣乗馬行於此道。按古假借爲𢒰字。如論語郁郁乎文哉是也。𢒰、有文章也。其始借彧爲𢒰。其後又借郁爲彧。今陜西鳳翔府隴州州西五十里有故郁夷城。後漢建武二年。鄧禹遣兵擊赤眉於郁夷。在此處也。"}]},"鄠":{"expl":"右扶風縣名。从邑雩聲。","rad":"邑","fq":"胡古切","vol":"06","py":"hù","duan":[{"e":"右扶風縣也。","n":"前後二志同。今陜西西安府鄠縣縣北二里有故鄠城。卽古扈國也。"}]},"扈":{"expl":"夏后同姓所封，戰於甘者。在鄠，有扈谷、甘亭。从邑戶聲。","rad":"邑","fq":"胡古切","vol":"06","py":"hù","duan":[{"e":"夏后同姓所封戰於甘者。","n":"尙書序曰。啟與有扈戰於甘之野。作甘誓。馬融曰。有扈、姒姓之國。爲無道。又曰。甘、有扈南郊地名也。左傳曰。夏有觀扈。五觀與扈皆夏同姓也。"}]},"䣙":{"expl":"右扶風鄠鄉。从邑崩聲。沛城父有䣙鄉。讀若陪。","rad":"邑","fq":"薄回切","vol":"06","py":"péi","duan":[{"e":"右扶風鄠鄉。","n":"謂右扶風鄠縣有䣙鄉也。下仿此。漢䣙成矦周緤。服虔音菅蒯之蒯。蘇林音簿催反。小顏、小司馬皆云。字從崩從邑。功臣表。剻成在長沙。張守節引輿地志云。䣙成縣、故陳倉縣之故鄉聚名也。周緤所封。與漢表說文皆乖異。而穆天子傳天子西征至于䣙。又未詳其地。"}]},"䢸":{"expl":"右扶風鄠鄉。从邑且聲。","rad":"邑","fq":"子余切","vol":"06","py":"jū","duan":[{"e":"右扶風鄠鄉。从邑。且聲。","n":"子余切。五部。"}]},"莿":{"expl":"茦也。从艸刺聲。","rad":"艸","fq":"七賜切","vol":"01","py":"cì","duan":[{"e":"茦也。","n":"按方言衹作刺。卽從艸亦當與茦篆相屬。恐後人增之。"}]},"郝":{"expl":"右扶風鄠、盩厔鄉。从邑赤聲。","rad":"邑","fq":"呼各切","vol":"06","py":"hǎo","duan":[{"e":"右扶風鄠盩庢鄉。","n":"鉉本如此。謂右扶風之鄠縣、盩庢縣皆有郝鄉也。玉篇作右扶風盩庢鄉。無鄠字。而鍇本作右扶風鄠鄉盩庢縣。脫落不完。汲古毛扆乃取以改舊本。可𥬇也。前志曰。右扶風盩庢。按在今陜西西安府盩庢縣。"}]},"酆":{"expl":"周文王所都。在京兆杜陵西南。从邑豐聲。","rad":"邑","fq":"敷戎切","vol":"06","py":"fēnɡ","duan":[{"e":"周文王所都。","n":"詩書皆作豐。左傳。酆、文之昭也。字從邑。前後二志亦作酆。大雅曰。旣伐于崇。作邑于豐。杜預曰。酆在鄠縣。後志曰。酆在京兆杜陵西南。"}]},"鄭":{"expl":"京兆縣。周厲王子友所封。从邑奠聲。宗周之滅，鄭徙潧洧之上，今新鄭是也。","rad":"邑","fq":"直正切","vol":"06","py":"zhènɡ","duan":[{"e":"京兆縣。","n":"二志同。今陜西同州府華州州城北有故鄭城。"}]},"郃":{"expl":"左馮翊郃陽縣。从邑合聲。《詩》曰：“在郃之陽。”","rad":"邑","fq":"𠊱閤切","vol":"06","py":"hé","duan":[{"e":"左馮翊郃陽縣。","n":"二志同。應邵曰。在邰水之陽也。按今陜西同州府郃陽縣卽其地。"}]},"𨙫":{"expl":"京兆藍田鄉。从邑口聲。","rad":"邑","fq":"苦后切","vol":"06","py":"kǒu","duan":[{"e":"京兆藍田鄉。","n":"二志皆云。京兆尹藍田。今陜西西安府藍田縣縣治西十一里有藍田故城。叩者、鄉名。今人叩擊字从卩。不當作𨙫。"}]},"𨟄":{"expl":"京兆杜陵鄉。从邑樊聲。","rad":"邑","fq":"附袁切","vol":"06","py":"fán","duan":[{"e":"京兆杜陵鄉。","n":"水經注渭水篇。泬水上承皇子陂於樊川。其地卽杜之樊鄉也。漢祖至櫟陽。以將軍樊噲灌廢？最。賜邑於此鄉。按樊鄉見史、漢樊噲傳。索隱引三秦記曰。長安正南。山名秦嶺。谷名子午。一名樊川。一名御宿。樊鄉卽樊川也。宋敏求長安志曰。樊川在萬年縣南三十五里。引十道志云。其地卽杜陵之樊鄉。凡言樊鄉、卽許之？鄉也。在今西安府府南三十里之樊川。周語。樊仲山父諫。韋曰。仲山父、王卿士。食采於樊。毛傳曰。仲山甫、樊矦也。按周襄王賜晉文公陽樊之田。陽樊、一名樊。一名陽。國語。陽人不服。而曰陽有樊仲之官守焉。然則仲山甫之樊非此？也。陽樊、方輿紀要云。或曰在今河南懷慶府濟源縣。"}]},"𨞻":{"expl":"左馮翊縣。从邑麃聲。","rad":"邑","fq":"甫無切","vol":"06","py":"fū","duan":[{"e":"左馮翊縣。","n":"見地理志。按封禪書秦文公作鄜畤。今陜西鄜州洛川縣縣東南七十里有鄜城廢縣。"}]},"䣝":{"expl":"左馮翊䣝陽亭。从邑屠聲。","rad":"邑","fq":"同都切","vol":"06","py":"tú","duan":[{"e":"左馮翊郃陽亭。","n":"謂左馮翊郃陽有䣝亭也。各本作䣝陽亭。誤。今依集韵、類篇、王伯厚詩地理考、正。伯厚困學紀聞亦作䣝陽亭。則宋時本固是。非錯出也。大雅韓奕。出宿于屠。毛曰。屠、地名。宋潏水李氏謂地在同州䣝谷。是也。按屠䣝古今字。顧氏祖禹讀史方輿紀要作荼谷渡。云在今陜西同州府郃陽縣東河西故城南。"}]},"邮":{"expl":"左馮翊高陵。从邑由聲。","rad":"邑","fq":"徒歴切","vol":"06","py":"yóu","duan":[{"e":"左馮翊高陵亭。","n":"各本無亭字。今依廣韵尤韵及玉篇補。錫韵又曰。邮、鄉名。在高陵。按左馮翊高陵、二志同。今陜西西安府高陵縣卽其地。"}]},"𨛲":{"expl":"左馮翊谷口鄉。从邑秊聲。讀若寕。","rad":"邑","fq":"奴顛切","vol":"06","py":"nián","duan":[{"e":"左馮翊谷口鄉。","n":"左馮翊谷口、見地理志。今陜西西安府醴泉縣東北七十里有故谷口城。"}]},"蕫":{"expl":"鼎蕫也。从艸童聲。杜林曰：藕根。","rad":"艸","fq":"多動切","vol":"01","py":"dǒnɡ","duan":[{"e":"鼎蕫也。","n":"釋艸曰。蘱、薡蕫。郭云。似蒲而細。按說文無蘱字者、葢許所據衹作類。"}]},"邽":{"expl":"隴西上邽也。从邑圭聲。","rad":"邑","fq":"古畦切","vol":"06","py":"ɡuī","duan":[{"e":"隴西上邽也。","n":"見地理志。郡國志曰。漢陽郡上邽故屬隴西。胡氏三省云。秦本紀。武公伐邽冀戎。初縣之。上邽縣、故邽戎地也。此爲上邽。京兆有下邽。今甘肅秦州州西六十里有故上邽城。"}]},"部":{"expl":"天水狄部。从邑咅聲。","rad":"邑","fq":"蒲口切","vol":"06","py":"bù","duan":[{"e":"天水狄部。","n":"地理志天水無狄部。未詳。顧氏祖禹曰。漢天水郡、今陜西鞏昌府以東秦州之境是其地。"}]},"郖":{"expl":"弘農縣庾地。从邑豆聲。","rad":"邑","fq":"當侯切","vol":"06","py":"dòu","duan":[{"e":"弘農縣庾地。","n":"二志弘農郡首弘農縣。郡縣同名。故但言弘農縣也。庾當作渡。字之誤也。水經注河水篇曰。門水又北徑弘農縣故城東。城卽故函谷關。門水側城北流而注於河。河水於此有浢津。以河北有浢水南入於河。故有浢津之名也。穆天子傳。天子自窴軨乃次於浢水之陽。丁亥入於南鄭。考其沿歷所踵。路直斯津。是知袁豹之徒竇津之說非矣。按浢郖同字。魏志杜畿傳。畿遂詭道從郖津渡。陳壽用字合許書也。宋元嘉二十九年。北魏將封禮自郖津南渡赴弘農。拒桺元景。在今河南陜州靈寶縣縣西十里。"}]},"鄏":{"expl":"河南縣直城門官陌地也。从邑辱聲。《春秋傳》曰：“成王定鼎于郟鄏。”","rad":"邑","fq":"而蜀切","vol":"06","py":"rǔ","duan":[{"e":"郟鄏、","n":"逗。二字依韵會補。"}]},"鄻":{"expl":"周邑也。从邑輦聲。","rad":"邑","fq":"力展切","vol":"06","py":"liǎn","duan":[{"e":"周邑也。","n":"左傳昭卄九年。王子趙車入于鄻以叛。杜云。鄻、周邑。"}]},"𨝋":{"expl":"周邑也。从邑祭聲。","rad":"邑","fq":"側介切","vol":"06","py":"zhài","duan":[{"e":"周邑也。","n":"左傳曰。凡蔣邢茅胙祭。周公之胤也。按春秋經、左傳、國語、史記、逸周書、竹書紀年。凡云祭伯、祭公謀父、字皆作祭。惟穆天子傳云𨝋父。注云。𨝋父、𨝋公謀父。𨝋者本字。祭者假借字。韋注國語云。祭、畿內之國。周公之後也。爲王卿士。謀父字也。是則𨝋本西都畿內邑名。至東周時。隱元年祭伯來。莊卄三年祭叔來聘。尚仍其西都舊偁。許云周邑、系諸河南河內之閒。其諸東都亦有𨝋與。抑如鄭之仍舊偁與。"}]},"邙":{"expl":"河南洛陽北亡山上邑。从邑亡聲。","rad":"邑","fq":"莫郎切","vol":"06","py":"mánɡ","duan":[{"e":"河南雒陽北","n":"雒各本作洛。誤。今正。河南雒陽、二志同。"}]},"鄩":{"expl":"周邑也。从邑尋聲。","rad":"邑","fq":"徐林切","vol":"06","py":"xún","duan":[{"e":"周邑也。","n":"左傳昭廿二年。郊鄩潰。杜曰。河南鞏縣西南有地名鄩中。水經注洛水篇曰。鄩水於訾城西北東入洛水。京相璠云。有鄩城。葢周大夫鄩肸之邑也。按鄩肸、鄩羅皆子朝之黨。見左傳。今河南河南府鞏縣縣西南五十八里有故鄩城。"}]},"郗":{"expl":"周邑也。在河内。从邑希聲。","rad":"邑","fq":"丑脂切","vol":"06","py":"chī","duan":[{"e":"周邑也。在河內。","n":"左傳隱十一年。王與鄭人蘇忿生之田。溫、原、絺、樊、隰郕、欑茅、向、盟、州、陘、隤、懷。杜曰。絺在野王縣西南。按郗者本字。絺者古文假借字也。前志河內郡波縣。孟康云有絺城。後志亦云河內波有絺城。按許但云河內、不云某縣者。有所未審也。"}]},"鄆":{"expl":"河内沁水鄉。从邑軍聲。魯有鄆地。","rad":"邑","fq":"王問切","vol":"06","py":"yùn","duan":[{"e":"河內沁水鄉。","n":"河內郡沁水、二志同。今河南懷慶府濟源縣縣東北有故沁水城是也。沁水縣有鄆鄉。"}]},"蘻":{"expl":"狗毒也。从艸繫聲。","rad":"艸","fq":"古詣切","vol":"01","py":"jì","duan":[{"e":"狗毒也。","n":"見釋艸。樊光云。俗語苦如蘻。"}]},"邶":{"expl":"故商邑。自河内朝歌以北是也。从邑北聲。","rad":"邑","fq":"補妹切","vol":"06","py":"bèi","duan":[{"e":"故商邑。","n":"商、畿內之地也。邑、國也。商頌曰。商邑翼翼。"}]},"邘":{"expl":"周武王子所封。在河内野王是也。从邑于聲。又讀若區。","rad":"邑","fq":"況于切","vol":"06","py":"yú","duan":[{"e":"周武王子所封。","n":"左傳曰。邘、晉、應、韓。武之穆也。"}]},"𨛫":{"expl":"殷諸侯國。在上黨東北。从邑𥝢聲。𥝢，古文利。《商書》：“西伯戡𨛫。”","rad":"邑","fq":"郎奚切","vol":"06","py":"lí","duan":[{"e":"殷諸矦國。","n":"今商書西伯戡黎。今文尚書作耆。尚書大傳文王受命五年伐耆、周本紀明年敗耆國、是也。或作？。或作飢。皆假借字也。許所據古文尚書作𨛫。戈部作黎。葢俗改也。左傳曰。赤狄奪黎氏地。詩序曰。狄人迫逐黎矦。未知卽商諸矦之後與否。"}]},"邵":{"expl":"晉邑也。从邑召聲。","rad":"邑","fq":"寔照切","vol":"06","py":"shào","duan":[{"e":"晉邑也。","n":"左傳襄二十三年。齊矦伐衞。遂伐晉。入孟門。登大行。張武軍於熒庭。戍郫邵。杜曰。取晉邑而守之。杜不言郫邵二邑名。據許則當是二邑也。文六年。賈季召公子樂於陳。趙孟使殺諸郫。此單言郫也。後志。河東垣縣有邵亭。注引博物記。縣東九十里有郫邵之阨。趙孟殺公子樂於郫邵。豈張華所見左傳有異歟。按今山西絳州垣曲縣東有邵城。後魏之邵郡、後周之邵州皆此也。依許則經典獨此字從邑召。凡周召字作邵者俗也。後儒或謂垣曲邵城爲周召分陜之所。其說不經。"}]},"鄍":{"expl":"晉邑也。从邑冥聲。《春秋傳》曰：“伐鄍三門。”","rad":"邑","fq":"莫經切","vol":"06","py":"mínɡ","duan":[{"e":"晉邑也。","n":"左傳僖二年。荀息假道於虞曰。冀爲不道。入自顚軨。伐鄍三門。服虔曰。謂冀伐晉也。下文冀之旣病。亦唯君故。謂虞助晉也。將欲假道稱前恩以誘之。按服說是也。杜云鄍、虞邑。非也。許同服說。"}]},"鄐":{"expl":"晉邢矦邑。从邑畜聲。","rad":"邑","fq":"丑六切","vol":"06","py":"chù","duan":[{"e":"晉郉矦邑。","n":"按當云晉雍子邑。許筆誤也。左傳襄卄六年。聲子曰。雍子奔晉。晉人與之鄐。子靈卽申公巫臣。奔晉。晉人與之郉。昭十四年。晉郉矦與雍子爭鄐田。杜曰。郉矦。巫臣之子也。"}]},"𨜫":{"expl":"晉之溫地。从邑侯聲。《春秋傳》曰：“爭𨜫田。”","rad":"邑","fq":"胡遘切","vol":"06","py":"hòu","duan":[{"e":"晉之溫地。","n":"左傳成十一年。晉郤至與周爭鄇田。郤至曰。溫、吾故也。杜曰。鄇、溫別邑。今河內懷縣西南有𠊱人亭。按鄇田今在河南懷慶府武陟縣。劉歆遂初賦。越矦田而長驅兮。釋叔向之飛患。巳下皆述叔向事。則矦田正謂郉矦。雍子所爭者也。章樵以鄇田說之。疑非。"}]},"邲":{"expl":"晉邑也。从邑必聲。《春秋傳》曰：“晋楚戰于邲。”","rad":"邑","fq":"毗必切","vol":"06","py":"bì","duan":[{"e":"晉邑也。","n":"杜曰。邲、鄭地。按水經注濟水篇曰。次東得宿胥水口。濟水與河渾濤東注濟水於此。又兼邲目。春秋宣公十三年。晉楚之戰。楚軍於邲。卽是水也。顧氏祖禹曰。其地葢卽熒口受河之處。今在河陰縣西。"}]},"郤":{"expl":"晉大夫叔虎邑也。从邑谷聲。","rad":"邑","fq":"綺𢧢切","vol":"06","py":"xì","duan":[{"e":"晉大夫叔虎邑也。","n":"叔虎之子曰郤芮。以邑爲氏。"}]},"𨛬":{"expl":"河東聞喜縣。从邑非聲。","rad":"邑","fq":"薄回切","vol":"06","py":"péi","duan":[{"e":"河東聞喜鄉。","n":"鄉各本作縣。今依廣韵正。河東郡聞喜、二志同。今山西絳州聞喜縣、漢縣地也。廣韵曰。𨛬、鄉名。在聞喜。伯益之後封於𨛬鄉。因以爲氏。後徙封解邑。乃去邑從衣。按今字裴行而𨛬廢矣。"}]},"𦺋":{"expl":"艸也。从艸嫂聲。","rad":"艸","fq":"蘇老切","vol":"01","py":"sǎo","duan":[{"e":"艸也。","n":"釋艸曰。？、𦺋𧃒。未知許𣃔句如此否。"}]},"𨜻":{"expl":"河東聞喜聚。从邑虔聲。","rad":"邑","fq":"渠焉切","vol":"06","py":"qián","duan":[{"e":"河東聞喜聚。","n":"？部曰。邑落曰聚。舜所居、一年成聚。二年成邑。三年成都。聚、小於邑也。"}]},"邼":{"expl":"河東聞喜鄉。从邑匡聲。","rad":"邑","fq":"去王切","vol":"06","py":"kuānɡ","duan":[{"e":"河東聞喜鄉。从邑。匩聲。","n":"去王切。十部。"}]},"鄈":{"expl":"河東臨汾地，即漢之所祭后土處。从邑癸聲。","rad":"邑","fq":"揆唯切","vol":"06","py":"kuí","duan":[{"e":"河東臨汾地。","n":"河東郡臨汾、二志同。今山西平陽府太平縣縣南二十五里臨汾故城是也。漢武帝紀。元鼎四年。立后土祠於汾陰脽上。如淳曰。脽者、河之東岸特堆崛。長四五里。廣二里餘。高十餘丈。汾陰縣治脽之上。后土祠在縣西。汾在脽之北。西流與河合也。師古曰。以其形高起如人尻脽。故以名云。一說地臨汾水之上。地本名鄈。音與葵同。彼鄉人呼鄈音如誰。因轉而爲脽字耳。故漢舊儀云葵上。玉裁按。水經。汾水又西過皮氏縣。注曰。汾水徑鄈𠀌北。故漢氏之方澤也。賈逵云、漢法。三年祭地汾陰方澤。澤中有方𠀌。故謂之方澤。㐀卽鄈㐀也。經又曰。又西至汾陰縣北。西注於河。注曰。水南有長阜。背汾帶河。阜長四五里。廣二里餘。高十丈。汾水歷其陰。西入河。漢書謂"}]},"郉":{"expl":"周公子所封，地近河内懷。从邑幵聲。","rad":"邑","fq":"戶經切","vol":"06","py":"xínɡ","duan":[{"e":"周公子所封。","n":"左傳。富辰曰。凡蔣郉茅胙祭、周公之胤也。杜曰。郉國在廣平襄國縣。"}]},"鄔":{"expl":"太原縣。从邑烏聲。","rad":"邑","fq":"安古切","vol":"06","py":"wū","duan":[{"e":"大原縣。","n":"二志同。前志曰。晉大夫司馬彌牟邑。按彌牟爲鄔大夫。見昭二十八年左傳。前此有鄔臧。以邑爲氏。戴先生曰。今山西汾州府介休縣縣東三十五里有故鄔城、漢縣也。其北魏之鄔城、在今介休縣東四十五里。俗譌武城。"}]},"祁":{"expl":"太原縣。从邑示聲。","rad":"邑","fq":"巨支切","vol":"06","py":"qí","duan":[{"e":"大原縣。","n":"二志同。前志曰。晉大夫賈辛邑。按賈辛爲祁大夫。見左傳昭廿八年。前此巳有祁奚、祁午、祁盈、祁勝、以邑爲氏今山西太原府祁縣縣東南七里有故祁城、漢縣治也。毛傳於吉日云。祁大也。於采？、大田云、祁祁、舒遟也。祁祁、徐皃也。於七月云。祁祁、衆多也。皆與本義不相關。"}]},"鄴":{"expl":"魏郡縣。从邑業聲。","rad":"邑","fq":"魚怯切","vol":"06","py":"yè","duan":[{"e":"魏郡縣。","n":"二志同。漢魏郡治鄴縣。今河南彰德府臨漳縣縣西二十里有故鄴城。"}]},"𨙷":{"expl":"鄭地𨙷亭。从邑井聲。","rad":"邑","fq":"戶經切","vol":"06","py":"jǐnɡ","duan":[{"e":"鄭地有𨙷亭。从邑。井聲。","n":"云鄭地恐誤。葢京兆之鄭、則篆文宜次於鄭之後。若河南之新鄭、則宜次於下文鄶邧郔之伍。此上下文皆河內地。不宜忽羼以河南地名也。疑卽二志常山郡之井陘縣、趙地也。？井葢古今字。井陘山、穆天子傳作？山。地理志上黨郡下謂之石研關。師古曰。硏、音形。玉篇？子省切。廣韵子郢切。大徐戸經切。十一部。"}]},"邯":{"expl":"趙邯鄲縣。从邑甘聲。","rad":"邑","fq":"胡安切","vol":"06","py":"hán","duan":[{"e":"趙邯鄲縣。","n":"趙國邯鄲、二志同。左傳有邯鄲午。秦始皇置邯鄲郡。漢趙國、故邯鄲郡也。張晏曰。邯山在東城下。單、盡也。城郭從邑、故加邑。按今直𣜩廣平府邯鄲縣縣西南二十里有故邯鄲城。"}]},"鄲":{"expl":"邯鄲縣。从邑單聲。","rad":"邑","fq":"都寒切","vol":"06","py":"dān","duan":[{"e":"邯鄲也。","n":"依張晏古字本作單。後人加邑耳。"}]},"芐":{"expl":"地黃也。从艸下聲。《禮記》“鈃毛：牛、藿；羊、芐；豕、薇。”是。","rad":"艸","fq":"侯古切","vol":"01","py":"hù","duan":[{"e":"地黃也。","n":"見釋艸。本艸經謂之乾地黃。"}]},"郇":{"expl":"周武王子所封國，在晉地。从邑旬聲。讀若泓。","rad":"邑","fq":"相倫切","vol":"06","py":"xún","duan":[{"e":"周文王子所封國。","n":"文各本作武。誤。今依篇韵正。左傳。富辰曰。郇、文之昭也。毛傳曰。郇伯、郇矦也。左傳曰軍於郇、曰盟於郇、曰必居郇瑕氏之地、皆是也。郇國爲晉所幷。"}]},"鄃":{"expl":"清河縣。从邑俞聲。","rad":"邑","fq":"式朱切","vol":"06","py":"shū","duan":[{"e":"淸河縣。","n":"前志淸河郡鄃。後志淸河國鄃。史記河渠書曰。田蚡奉邑食鄃。又吕嬰、欒布皆封俞矦。俞卽鄃。今山東臨淸州夏津縣東北三十里有故鄃縣城。"}]},"鄗":{"expl":"常山縣。丗祖所卽位，今爲高邑。从邑高聲。","rad":"邑","fq":"呼各切","vol":"06","py":"hào","duan":[{"e":"常山縣也。从邑。高聲。","n":"呼各切。古音在二部。"}]},"鄡":{"expl":"鉅鹿縣。从邑梟聲。","rad":"邑","fq":"牽遙切","vol":"06","py":"qiāo","duan":[{"e":"鉅鹿縣也。","n":"二志同。前志作？。？與梟一字。但前志鉅鹿？縣、豫章鄡陽縣。玉篇、廣韵皆？與鄡陽二縣字別。然則許書此字作鄡及後志二縣字皆作鄡非是。許書當是淺人改之。如𥄉首之改爲梟首也。盧氏文弨云。仲尼弟子列傳鄡單、鄡當作？。？單葢卽檀弓縣亶。縣乃字之誤。按漢鉅鹿縣城卽今直𣜩順德府平鄉縣城。唐通典曰。漢鄡城在深州鹿城縣東。"}]},"鄚":{"expl":"涿郡縣。从邑莫聲。","rad":"邑","fq":"慕各切","vol":"06","py":"mò","duan":[{"e":"涿郡縣。","n":"見前志。後志曰。河閒郡鄚、故屬涿。史記曰。扁鵲者、勃海郡鄭人。徐廣云。鄭當爲鄚。按司馬以鄚系勃海者、境相際也。扁鵲、漢以前人。不當覈以漢制耳。今直𣜩河閒府任𠀌縣縣北十三里有莫州城。往來孔道也。唐開元十三年改鄚爲莫。見通典、舊唐書。"}]},"郅":{"expl":"北地郁郅縣。从邑至聲。","rad":"邑","fq":"之日切","vol":"06","py":"zhì","duan":[{"e":"北地郁郅縣。","n":"見前志。漢北地郡。今甘肅慶陽府北至寧夏衞是其境。慶陽府附郭安化縣府城東有故郁郅城。水經注謂之尉李城。聲之誤也。"}]},"𨜛":{"expl":"北方長狄國也。在夏爲防風氏，在殷爲汪茫氏。从邑叜聲。《春秋傳》曰：“𨜛瞞侵齊。”","rad":"邑","fq":"所鳩切","vol":"06","py":"sōu","duan":[{"e":"北方長狄國也。","n":"春秋文公十一年左傳。鄋瞞侵齊。遂伐我。叔孫得臣獲長狄僑如。榖梁傳曰。身横九畞。"}]},"鄦":{"expl":"炎帝太嶽之胤，甫矦所封，在潁川。从邑無聲。讀若許。","rad":"邑","fq":"虚呂切","vol":"06","py":"xǔ","duan":[{"e":"炎帝大嶽之胤甫矦所封。","n":"炎帝神農氏之裔子爲大嶽。詳吕部下。大嶽封於吕。其裔子甫矦又封於鄦。鄦許古今字。前志曰。潁川郡、許故國。姜姓。四岳後。大叔所封。大叔、左傳隱十一年正義作文叔。說文敘目云。吕叔作藩。俾矦於許。然則封鄦者文叔、非甫矦也。鄭注吕㓝曰。吕矦受王命入爲三公。引尚書㓝德放云。周穆王以吕矦爲相。古文尚書吕㓝、今文尚書作甫㓝。且據國語、毛傳、史記、潛夫論諸書。吕甫許皆姜姓封國。詩王風申甫許三國竝言。武王旣封文叔於許矣。豈待穆王封甫矦於許。叔重言甫矦所封者、甫矦卽謂吕叔。吕叔卽謂文叔。無二人也。"}]},"邟":{"expl":"潁川縣。从邑亢聲。","rad":"邑","fq":"苦浪切","vol":"06","py":"kànɡ","duan":[{"e":"潁川縣。","n":"見前志。今地理志云。潁川郡、周承休矦國。元帝置。元始二年更名鄭公。攷後漢書黃瓊傳封邟鄉矦。注引前書周承休矦國、元始二年更名曰邟。與顏本絕異。今按李本、顏本皆非事實。志文當是邟字大書。周承休矦國五字小書注於下。此矦國不與他矦國同。故不以縣名爲國名也。元始二年更名曰鄭公。二年當依平帝紀、外戚恩澤矦表作四年。字之誤也。郡國志無邟縣者、幷省也。幷省之、故有邟鄉矣。漢封殷周之後可攷者。武帝紀。元鼎四年巡省豫州。封周孼子嘉爲周子南君。此史記封禪書所謂以三十里封周後。外戚恩澤矦表所謂初得周後、復加爵邑也。元帝紀。初元五年以周子南君爲周承休矦。此地理志所謂周承休矦國、元帝時置也。成帝紀。綏和元年二月封孔吉爲殷"}]},"郾":{"expl":"潁川縣。从邑匽聲。","rad":"邑","fq":"於建切","vol":"06","py":"yǎn","duan":[{"e":"潁川縣。","n":"二志同。前志曰。南陽郡雉衡山。澧水所出。東至郾入汝。郾今本譌作𨜘。全氏祖望勘以水經正之。今河南許州郾城縣是其地。"}]},"薟":{"expl":"白薟也。从艸僉聲。","rad":"艸","fq":"良冉切","vol":"01","py":"liǎn","duan":[{"e":"白薟也。","n":"本艸經作白斂。"}]},"郟":{"expl":"潁川縣。从邑夾聲。","rad":"邑","fq":"工洽切","vol":"06","py":"jiá","duan":[{"e":"潁川縣。","n":"見前志。故楚郟邑也。左傳昭元年。楚公子圍使公子黑肱城郟。十九年。令尹子瑕城郟。秦二世元年。陳勝將鄧寵將兵居郟。在今河南汝州郟縣。"}]},"郪":{"expl":"新郪，汝南縣。从邑妻聲。","rad":"邑","fq":"七稽切","vol":"06","py":"qī","duan":[{"e":"新郪、","n":"逗。"}]},"鄎":{"expl":"姬姓之國，在淮北。从邑息聲。今汝南新鄎。","rad":"邑","fq":"相卽切","vol":"06","py":"xī","duan":[{"e":"姬姓之國。在淮北。","n":"左傳隱十一年。鄭息有違言。杜曰。鄎國、汝南新息縣。按此經作息、注作鄎國也。釋文云。鄎音息。一本作息。此爲注作音也。自墨書朱字不分、而學者惑矣。左傳用古文假借字。杜解用說文本字。不與經同。此鄭氏注經之例也。左正義引世本曰。息國、姬姓。許云姬姓之國。本世本也。息矦伐鄭。君子謂其不親親。以其同姓也。左傳云息嬀者、謂息所娶之陳嬀也。今河南光州息縣。淮水在縣南五里。故息城在縣北三十里。"}]},"郋":{"expl":"汝南邵陵里。从邑自聲。讀若奚。","rad":"邑","fq":"胡雞切","vol":"06","py":"xí","duan":[{"e":"汝南召陵里。","n":"召各本作邵。誤。今正。汝南郡召陵、二志同。闞駰曰。召者、高也。左傳僖四年。楚屈完來盟于師。盟于召陵。又見昭十四年、定四年傳。杜曰。召陵、潁川縣也。晉改屬潁川也。按今河南許州郾城縣縣東四十五里有故召陵城。郋者、召陵里名。召陵又有萬歲里。許君、召陵萬歲里人也。"}]},"𨜷":{"expl":"汝南鮦陽亭。从邑㫄聲。","rad":"邑","fq":"步光切","vol":"06","py":"pánɡ","duan":[{"e":"汝南鮦陽亭。","n":"汝南郡鮦陽、二志同。鮦、孟康音紂。此方言如是。或云當作紂紅反者非也。今河南汝寧府新蔡縣縣北有鮦陽故城。又有鮦陽渠。鮦者、水名。水經注、葛陂東出爲鮦水。俗謂之三丈陂是也。？者、鮦陽亭名。疑卽左傳襄四年、定四年之䋣陽也。"}]},"郹":{"expl":"蔡邑也。从邑狊聲。《春秋傳》曰：“郹陽封人之女奔之。”","rad":"邑","fq":"古闃切","vol":"06","py":"jú","duan":[{"e":"蔡邑也。","n":"地理志。汝南郡有新蔡上蔡二縣。沛郡有下蔡縣。上蔡縣故蔡國、周武王弟叔度所封。度放。成王封其子胡。十八世徙新蔡。新蔡縣、蔡平矦自蔡徙此。後二世徙下蔡。下蔡縣、故州來國。爲楚所滅。吳取之。至夫差遷昭矦於此。後四世矦齊。竟爲楚所滅。按杜預說同。上蔡、新蔡、下蔡、漢時用以名縣。非周時有此名也。上蔡、新蔡、漢時同在汝南郡。今二縣皆屬汝寧府。相歫不遠。若下蔡則歫上蔡新蔡遠矣。昭十九年左傳云。楚子之在蔡也。郹陽封人之女奔之。生大子建。平王爲蔡公時。蔡方滅。尚未遷新蔡。則郹陽當在上蔡矣。左傳又云。齊矦衞矦次于垂葭。實郹氏。則衞地非蔡地也。"}]},"鄧":{"expl":"曼姓之國。今屬南陽。从邑登聲。","rad":"邑","fq":"徒亙切","vol":"06","py":"dènɡ","duan":[{"e":"曼姓之國。","n":"左傳。楚武王夫人曰鄧曼。則知鄧國曼姓也。前志曰。鄧縣故國。"}]},"鄾":{"expl":"鄧國地也。从邑憂聲。《春秋傳》曰：“鄧南鄙鄾人攻之。”","rad":"邑","fq":"於求切","vol":"06","py":"yōu","duan":[{"e":"鄧國地也。","n":"左傳桓九年。楚子使道朔將巴客以聘於鄧。鄧南鄙鄾人攻而奪之幣。杜曰。鄾在今鄧縣南、沔水之北。後志曰。鄧有鄾聚。水經注曰。淯水又南徑鄧塞東。又徑鄾城東。古鄾子國也。葢鄧之南鄙也。"}]},"𨚙":{"expl":"南陽淯陽鄉。从邑号聲。","rad":"邑","fq":"乎刀切","vol":"06","py":"háo","duan":[{"e":"南陽淯陽鄉。","n":"淯二志作育。南陽郡育陽、二志同。今河南南陽府東育陽故城是也。？者、漢時鄉名。"}]},"鄛":{"expl":"南陽棗陽鄉。从邑巢聲。","rad":"邑","fq":"鉏交切","vol":"06","py":"cháo","duan":[{"e":"南陽棘陽鄉。","n":"棘各本作棗。誤。今依後漢書宦者傳注及玉篇正。南陽郡棘陽、二志同。今河南南陽府新野縣東北七十里有棘陽城是也。鄛其鄉名也。"}]},"菳":{"expl":"黃菳也。从艸金聲。","rad":"艸","fq":"具今切","vol":"01","py":"qín","duan":[{"e":"黃菳也。","n":"本艸經廣雅皆作黃芩。今藥中黃芩也。"}]},"𨟚":{"expl":"今南陽穰縣是。从邑襄聲。","rad":"邑","fq":"汝羊切","vol":"06","py":"ránɡ","duan":[{"e":"今南陽穰縣。","n":"南陽穰、二志同。今河南南陽府鄧州東南二里穰縣故城是也。本楚地。後爲韓邑。史記。韓襄王十一年。秦取我穰。又秦武王封魏冄於此爲穰矦。？者古字。穰者漢字。如𨜒薊、鄦許、鄎息、邰斄之例。葢許所見古籍作？。漢時縣名字從禾也。"}]},"䣚":{"expl":"南陽穰鄉。从邑婁聲。","rad":"邑","fq":"力朱切","vol":"06","py":"lú","duan":[{"e":"南陽穰鄉。","n":"穰縣鄉名也。"}]},"𨛋":{"expl":"南陽西鄂亭。从邑里聲。","rad":"邑","fq":"良止切","vol":"06","py":"lǐ","duan":[{"e":"南陽西鄂亭。","n":"南陽郡西鄂、二志同。今河南南陽府北五十里故西鄂城是也。？者、漢時亭名。"}]},"䣁":{"expl":"南陽舞陰亭。从邑羽聲。","rad":"邑","fq":"王榘切","vol":"06","py":"yǔ","duan":[{"e":"南陽舞陰亭。","n":"南陽郡舞陰、二志同。水經曰。潕水出潕陰縣西北扶予山。東過其縣南。凡水之南爲陰。當因水在縣西北、縣卽在水東南而名舞陰矣。水作潕縣作舞者、漢時縣字作舞也。水經注作潕陰者、依水改字也。䣁者、漢時亭名。庾信賦曰栩陽亭有離別之賦。漢藝文志之別栩陽賦也。栩陽亭豈卽䣁亭與。"}]},"郢":{"expl":"故楚都。在南郡江陵北十里。从邑呈聲。","rad":"邑","fq":"以整切","vol":"06","py":"yǐnɡ","duan":[{"e":"故楚都。","n":"楚芈姓。楚熊繹始居丹陽。顧氏輿地志。？歸縣東有丹陽城。周迴八里。熊繹始封也。按今湖北宜昌府歸州州東七里丹陽城是。至文王熊貲始都郢。"}]},"鄢":{"expl":"南郡縣。孝惠三年改名宜城。从邑焉聲。","rad":"邑","fq":"於乾切","vol":"06","py":"yān","duan":[{"e":"南郡縣。孝惠三年改名宜城。","n":"南郡宜城、二志同。前志曰。宜城、故鄢。惠帝三年更名。按今湖北襄陽府宜城縣縣西南九里故鄢城、亦謂之宜城廢縣是也。左傳昭十三年。王沿夏。將欲入鄢。杜曰。夏、漢別名。順流爲沿。順漢水南至鄢也。秦昭襄王卄八年。白起攻楚取鄢鄧。二十九年。白起攻楚取郢爲南郡。高誘曰。秦兵出武關則臨鄢。下黔中則臨郢也。"}]},"鄳":{"expl":"江夏縣。从邑𪓑聲。","rad":"邑","fq":"莫杏切","vol":"06","py":"ménɡ","duan":[{"e":"江夏縣。","n":"二志同。地當在南陽、江夏二郡之閒。今河南信陽州、湖北德安府應山縣之閒。縣葢以黽阨得名也。左傳定四年。楚司馬戌云。塞大隧、直轅、冥阨。三者漢東之隘道。緫名曰城口。魏晉以後。義陽有三關之塞。三關者、一曰平靖關。亦名西關。卽左傳之㝠阨也。今在信陽州東南九十里、應山縣北六十五里。一曰武陽關。亦名東關。卽左傳之大隧也。在信陽州東南一百五十里、西南至應山縣一百三十里。一曰黃峴關。卽左傳之直轅也。在信陽州南九十里、南至應山縣亦九十里。吕氏春秋、淮南鴻烈皆云。天下九塞。冥阨其一。戰國策、史記二書或云黽阨、或云黽塞、或云黽阨之塞、或云鄳隘、或云冥阨之塞。其實黽冥鄳一字、阨隘一字。而魏策無忌謂魏王作危隘之塞。危卽"}]},"𨞛":{"expl":"南陽陰鄉。从邑葛聲。","rad":"邑","fq":"古達切","vol":"06","py":"ɡé","duan":[{"e":"南陽陰鄉。","n":"南陽郡陰、二志同。師古曰。左傳所云遷陰於下陰者也。？者、其鄉名。"}]},"鄂":{"expl":"江夏縣。从邑㖾聲。","rad":"邑","fq":"五各切","vol":"06","py":"è","duan":[{"e":"江夏縣。","n":"二志同。今湖北武昌府武昌縣縣西南二里故鄂城是也。江夏有鄂縣。故南陽之縣曰西鄂。顧氏祖禹曰。史記熊渠當周夷王時興兵伐庸楊？至於鄂。又封中子紅爲鄂王。孔氏以爲南陽之鄂誤矣。時楚兵未能逾漢而北也。"}]},"邔":{"expl":"南陽縣。从邑己聲。","rad":"邑","fq":"居擬切","vol":"06","py":"qǐ","duan":[{"e":"南郡縣也。","n":"郡各本誤陽。今正。南郡邔、二志同。後志俗本譌作印。水經曰。禹貢三澨沱。在南郡邔縣北。今湖北襄陽府宜城縣縣北五十里有故邔城。"}]},"芩":{"expl":"艸也。从艸今聲。《詩》曰：“食野之芩。”","rad":"艸","fq":"巨今切","vol":"01","py":"qín","duan":[{"e":"艸也。","n":"小雅。呦呦鹿鳴。食野之芩。傳曰。芩艸也。陸璣云。芩艸莖如釵股。葉如竹。蔓生澤中下地鹹處。爲艸眞實。牛馬皆喜食之。按如陸說。則非黃芩藥也。許君黃菳字從金聲。詩野芩字從今聲。𢧵然分別。他書亂之。非也。毛詩音義引說文云。蒿也。以別於毛公之艸也。甚爲可據。但訓蒿則與弟二章不別。且說文當以芩與蒿篆類廁。恐是一本作蒿屬。釋文也字或屬字之誤。又按集韵、類篇皆曰荶䕾芩三字同、魚音切。菜名。似蒜。生水中。攷字林、齊民要術皆云荶似蒜。生水中。此則別是一物。"}]},"邾":{"expl":"江夏縣。从邑朱聲。","rad":"邑","fq":"陟輸切","vol":"06","py":"zhū","duan":[{"e":"江夏縣。","n":"二志同。前志曰。衡山王吳芮都。按芮都邾、見項羽本紀。今湖北黃州府城去故邾城二里許是也。今大江東流徑黃州府城南。隔江相望者曰武昌縣。水經曰。又東過邾縣南鄂縣北是也。酈善長曰。楚宣王滅邾。徙居於此。王隱地道記、劉昭郡國志注皆有此說。但此事不見楚世家。時楚之强。未必滅此彈丸而尚以地居之。葢此地古名邾。魯附庸國古名邾婁。依許所說。本不相謀。無庸牽合。"}]},"鄖":{"expl":"漢南之國。从邑員聲。漢中有鄖關。","rad":"邑","fq":"羽文切","vol":"06","py":"yún","duan":[{"e":"漢南之國。","n":"左傳桓十一年。鄖人軍於蒲騷。宣四年。若敖娶於鄖。字或作䢵。杜曰。鄖國在江夏雲杜縣東南有鄖城。按二志江夏皆有雲杜。今湖北德安府府城卽故鄖都也。漢水自西北而東南。德安在漢水北而云漢南者。漢之下游地勢處南也。春秋時楚滅鄖。故有鄖公辛。"}]},"鄘":{"expl":"南夷國。从邑庸聲。","rad":"邑","fq":"余封切","vol":"06","py":"yōnɡ","duan":[{"e":"南夷國。","n":"牧誓有庸蜀。左傳文十六年。庸人率羣蠻以叛楚。楚滅之。杜曰。庸今上庸縣。屬楚之小國。按二志漢中郡皆有上庸縣。今湖北鄖陽府竹山縣東四十里有故上庸城。尚書庸地在漢水之南。南至江尚遠。僞傳云在江南、非也。今字庸行而鄘廢。於詩風之邶庸作鄘。皆非也。又按南夷國當作漢南國。"}]},"郫":{"expl":"蜀縣也。从邑卑聲。","rad":"邑","fq":"符支切","vol":"06","py":"pí","duan":[{"e":"蜀縣也。","n":"二志同。今四川成都府郫縣縣北故郫城是。"}]},"𨞪":{"expl":"蜀江原地。从邑壽聲。","rad":"邑","fq":"市流切","vol":"06","py":"chóu","duan":[{"e":"蜀江原地。","n":"蜀郡江原、二志同。故城當在今灌縣竟。華陽國志曰。縣在郡西。渡大江。濵文井江。去郡一百二十里是也。鄭注梁州之沱曰。江原有𨞪江。首出江南。至犍爲武陽又入江。豈沱之類與。前志曰。𨞪水首受江。南至武陽入江。水經注亦云。江原縣、𨞪江水出焉。葢有𨞪地而以名江也。今則無𨞪地、𨞪江之偁矣。"}]},"䣢":{"expl":"蜀地也。从邑耤聲。","rad":"邑","fq":"秦昔切","vol":"06","py":"jí","duan":[{"e":"蜀地也。","n":"鍇曰。按字書鄉名。在臨邛。"}]},"𨞼":{"expl":"蜀廣漢鄉也。从邑蔓聲。讀若蔓。","rad":"邑","fq":"無販切","vol":"06","py":"wàn","duan":[{"e":"蜀廣漢鄉也。","n":"按蜀字衍。漢有蜀郡、有廣漢郡。此云廣漢鄉。上文云蜀地。皆不舉縣名者、未審也。"}]},"邡":{"expl":"什邡，廣漢縣。从邑方聲。","rad":"邑","fq":"府良切","vol":"06","py":"fānɡ","duan":[{"e":"汁邡、","n":"逗。"}]},"䣕":{"expl":"存䣕，犍爲縣。从邑馬聲。","rad":"邑","fq":"莫駕切","vol":"06","py":"mà","duan":[{"e":"存䣕、","n":"逗。"}]},"鄨":{"expl":"䍧牱縣。从邑敝聲。讀若鷩雉之鷩。","rad":"邑","fq":"必袂切","vol":"06","py":"bì","duan":[{"e":"羘柯縣。","n":"二志同。前志曰。不狼山、鄨水所出。東入沅。過郡二。行七百三十里。按犍爲郡、武帝建元六年開。牂柯郡、武帝元鼎六年開。則䣕字、鄨字必其時所製。今貴州遵義府府城西有鄨縣故城是也。方輿紀要曰。雲南陸涼州州北有廢鄨縣。非是。"}]},"藨":{"expl":"鹿藿也。从艸麃聲。讀若剽。一曰𦳋屬。","rad":"艸","fq":"平表切","vol":"01","py":"biāo","duan":[{"e":"鹿𧆑也。","n":"前莥篆訓鹿藿之實。此藨訓鹿藿。則當類處。徐鍇曰。釋艸。蔨、鹿藿。藨、麃。二者各物。疑字形之誤。以藨麃爲鹿藿也。玉裁按。葢麃誤爲鹿。淺人因妄增藿字耳。"}]},"𨚔":{"expl":"地名。从邑包聲。","rad":"邑","fq":"布交切","vol":"06","py":"bāo","duan":[{"e":"地名。","n":"按字廁於此。當是西南夷之地。"}]},"𨙻":{"expl":"西夷國。从邑冄聲。安定有朝𨙻縣。","rad":"邑","fq":"諾何切","vol":"06","py":"nuó","duan":[{"e":"西夷國。","n":"其地當在今四川之西。史記。自筰以東北。君長以什數。冄駹冣大。在蜀之西。又謂牂柯爲南夷。邛筰爲西夷。𨙻葢卽冄駹之冄字。古今字也。按文王之子耼季。賈逵、韋昭皆云。耼、國名。但其地闕。史記作冄。索隱云。冄或作𨙻。終莫詳其地也。左傳。莊十八年有𨙻處。杜云。𨙻處、楚地。凡若此等異地同名者。今皆不引以茲䋣蕪。"}]},"鄱":{"expl":"鄱陽，豫章縣。从邑番聲。","rad":"邑","fq":"薄波切","vol":"06","py":"pó","duan":[{"e":"鄱陽、","n":"逗。"}]},"酃":{"expl":"長沙縣。从邑霝聲。","rad":"邑","fq":"郎丁切","vol":"06","py":"línɡ","duan":[{"e":"長沙縣。","n":"前志長沙國酃。後志長沙郡酃。今湖南衡州府治衡陽縣府東卄五里有故酃縣城是也。有酃湖。卽荆州記、水經注所云。湖水釀酒甚美、謂之酃酒者也。"}]},"郴":{"expl":"桂陽縣。从邑林聲。","rad":"邑","fq":"丑林切","vol":"06","py":"chēn","duan":[{"e":"桂陽縣。","n":"二志同。今湖南直𣜩郴州卽古郴縣。漢桂陽郡治也。"}]},"䣂":{"expl":"今桂陽䣂陽縣。从邑耒聲。","rad":"邑","fq":"盧對切","vol":"06","py":"lèi","duan":[{"e":"今桂陽耒陽縣。","n":"耒各本作䣂。今正。許謂䣂卽今之耒陽縣。如言鄎卽今之新息、？卽今之穰縣也。其字旣異。其地則一。故言今以說之。桂陽郡耒陽、二志同。今湖南衡州府耒陽縣縣東四十五里有耒陽廢城。耒陽以耒水得名。"}]},"鄮":{"expl":"會稽縣。从邑貿聲。","rad":"邑","fq":"莫𠊱切","vol":"06","py":"mào","duan":[{"e":"會稽縣。","n":"二志同。今浙江寧波府治鄞縣府治東三十里故鄮城是也。陸士龍曰。秦始皇身在鄮縣三十餘日。"}]},"鄞":{"expl":"會稽縣。从邑堇聲。","rad":"邑","fq":"語斤切","vol":"06","py":"yín","duan":[{"e":"會稽縣。","n":"二志同。今浙江寧波府奉化縣有故鄞城是也。說者謂以亦堇山得名。越絕書所謂赤堇之山破而出錫是也。葢其字初作堇。後乃加邑。越語曰。句踐之地東至於鄞。韋曰今鄞縣是也。"}]},"𨙶":{"expl":"沛郡。从邑巿聲。","rad":"邑","fq":"博蓋切","vol":"06","py":"pèi","duan":[{"e":"沛國也。","n":"鉉本作沛郡。鍇本作沛國郡。按當作沛國沛郡也。謂後漢之沛國、前漢之沛郡、皆此？也。不言沛縣者、言郡而縣可知矣。二志字皆作沛。？沛古今字。如鄎息、？穰、䣂耒之比。今江蘇徐州府漢沛郡地。"}]},"邴":{"expl":"宋下邑。从邑丙聲。","rad":"邑","fq":"兵永切","vol":"06","py":"bǐnɡ","duan":[{"e":"宋下邑。","n":"下邑猶言小邑。左傳邴歜、邴意茲、邴泄、邴夏皆非宋人。公羊隱八年歸邴、入邴、九年會齊矦于邴皆非宋地。十年取防。防者、宋地。疑當作邴。"}]},"祠":{"expl":"春祭曰祠。品物少，多文詞也。从示司聲。仲春之月，祠不用犧牲，用圭璧及皮幣。","rad":"示","fq":"似兹切","vol":"01","py":"cí","duan":[{"e":"春祭曰祠。品物少。多文辭也。","n":"上言祠司命。故次以祠。辭與祠曡韵。周禮。以祠春享先王。公羊傳曰。春曰祠。注。祠猶食也。猶繼嗣也。"}]},"𧅖":{"expl":"綬也。从艸鶪聲。《詩》曰“邛有旨𧅖”是。","rad":"艸","fq":"五狄切","vol":"01","py":"yì","duan":[{"e":"綬艸也。","n":"艸字依韵會補。陳風邛有旨鷊傳曰。鷊、綬艸也。釋艸曰。虉綬。按毛詩作鷊。叚借字也。今爾雅作虉、與說文作𧅖不同者。鷊鶪同在十六部也。陸璣曰。鷊五色。作綬文。故曰綬艸。"}]},"䣜":{"expl":"沛國縣。从邑虘聲。","rad":"邑","fq":"昨何切","vol":"06","py":"cuó","duan":[{"e":"沛國縣。","n":"前志沛郡酇。後志沛國酇。陳勝攻銍酇苦柘譙。謂此酇也。今河南歸德府永城縣縣西南有故酇縣城。"}]},"𨙹":{"expl":"地名。从邑少聲。","rad":"邑","fq":"書沼切","vol":"06","py":"shǎo","duan":[{"e":"地名。从邑。少聲。","n":"書沼切。二部。"}]},"䢻":{"expl":"地名。从邑臣聲。","rad":"邑","fq":"植鄰切","vol":"06","py":"chén","duan":[{"e":"地名。从邑。臣聲。","n":"植鄰切。十二部。"}]},"酁":{"expl":"宋地也。从邑毚聲。讀若讒。","rad":"邑","fq":"士咸切","vol":"06","py":"chán","duan":[{"e":"宋地也。","n":"左傳哀十七年。宋皇瑗之子麇。有友曰田丙。而奪其兄酁般邑以與之。酁般猶祁午、盂丙。酁者、般之邑也。不詳其地在漢之何郡縣。故但曰宋地。"}]},"鄑":{"expl":"宋魯閒地。从邑晉聲。","rad":"邑","fq":"卽移切","vol":"06","py":"zī","duan":[{"e":"宋魯閒地。","n":"左傳莊元年。齊師遷紀？、鄑、郚。杜曰三邑也。北海都昌縣有訾城。杜意訾卽鄑也。許於下文郚曰東海縣。故紀矦之邑。此不云紀邑而云宋魯閒地者、據莊十一年公敗宋師于鄑而言。不謂紀邑也。"}]},"郜":{"expl":"周文王子所封國。从邑告聲。","rad":"邑","fq":"古到切","vol":"06","py":"ɡào","duan":[{"e":"周文王子所封國。","n":"左傳。富辰曰。郜雍曹滕、文之昭也。杜云。濟陰成武縣東南有郜城。隱十年。敗宋師。取郜。葢郜附庸於宋。魯隱取其地。桓又取郜鼎於宋。僖二十年。郜子來朝。則魯未滅之也。許不云在成武者。許意以爲未寀也。今山東兖州府城武縣縣東南二十里有故郜城。"}]},"鄄":{"expl":"衞地。今濟陰鄄城。从邑垔聲。","rad":"邑","fq":"吉掾切","vol":"06","py":"juàn","duan":[{"e":"衞地。","n":"春秋莊十四年。單伯會齊矦、宋公、衞矦、鄭伯于鄄。十五年。復會于鄄。十九年。公子吉及齊矦、宋公盟于鄄。襄十四年。衞獻公如鄄出奔齊。哀十七年。晉伐衞。衞人出莊公而與晉平。旣而衞矦自鄄入。杜曰。鄄、衞地。今東郡甄城是也。"}]},"邛":{"expl":"邛地。在濟陰縣。从邑工聲。","rad":"邑","fq":"渠容切","vol":"06","py":"qiónɡ","duan":[{"e":"邛成、","n":"逗。成各本作地。今正。"}]},"鄶":{"expl":"祝融之後，妘姓所封。潧洧之間。鄭滅之。从邑會聲。","rad":"邑","fq":"古外切","vol":"06","py":"kuài","duan":[{"e":"祝融之後妘姓所封潧洧之閒。鄭滅之。","n":"鄭詩諩曰。檜者、古高辛氏火正祝融之墟。檜國在禹貢豫州外方之北。熒播之南。居溱洧之閒。祝融氏名黎。其後八姓。惟妘姓檜者處其地焉。後爲鄭桓公之子武公所滅。按鄶在外方之東。非外方之北也。熒播、依小顏地理志注引作播。鄭語云祝融其後八姓。妘姓鄢、鄶、路、偪陽也。鄶以祝融之後仍封祝融之墟。左傳黎爲祝融。大戴禮、世本皆云祝融之弟吳回。吳回生陸終。陸終弟四子萊言是爲妘鄶人。卽鄶之祖也。萊亦作求。妘亦作云。鄶亦作會。今河南許州密縣、古鄶地。"}]},"邧":{"expl":"鄭邑也。从邑元聲。","rad":"邑","fq":"虞遠切","vol":"06","py":"yuán","duan":[{"e":"鄭邑也。","n":"左傳文四年。晉矦伐秦。圍邧新城。以報王官之役。廣韵云。秦邑名。是也。今左傳鄭地無名邧者。"}]},"蔆":{"expl":"芰也。从艸淩聲。楚謂之芰，秦謂之薢茩。","rad":"艸","fq":"力膺切","vol":"01","py":"línɡ","duan":[{"e":"芰也。","n":"周禮加籩之實有蔆注。蔆、芰也。子虛賦應劭注同。"}]},"郔":{"expl":"鄭地。从邑延聲。","rad":"邑","fq":"以然切","vol":"06","py":"yán","duan":[{"e":"鄭地。","n":"左傳宣三年。晉矦伐鄭及郔。杜曰。郔、鄭地。釋文。郔、音延。宋淳化本及明人補刻石經作延皆誤字也。又宣十二年。楚子北。師次于郔。實一地也。若隱元年。大叔收貳以爲己邑。至於廩延。當別是一地。字不從邑。"}]},"郠":{"expl":"琅邪莒邑。从邑更聲。《春秋傳》曰：“取郠。”","rad":"邑","fq":"古杏切","vol":"06","py":"ɡěnɡ","duan":[{"e":"琅邪莒邑。","n":"按當云莒邑也、在琅邪。如郗周邑也、在河內之例。"}]},"鄅":{"expl":"妘姓之國。从邑禹聲。《春秋傳》曰：“鄅人籍稻。”讀若規榘之榘。","rad":"邑","fq":"王榘切","vol":"06","py":"yǔ","duan":[{"e":"妘姓之國。","n":"春秋昭十八年。邾人入鄅。左傳云。鄅人藉稻。杜云。鄅、妘姓國也。正義云。鄅爲妘姓。世本文。按韋昭曰。陸終弟四子求言爲妘姓。杜曰。鄅今琅邪開陽縣。前志曰。東海郡開陽、故鄅國。後志開陽屬琅邪。開陽卽春秋經哀三年之啟陽也。魯有鄅地、爲啟陽。荀卿則云襄賁開陽。今山東沂州府府北十五里有故開陽城。"}]},"鄒":{"expl":"魯縣，古邾國，帝顓頊之後所封。从邑芻聲。","rad":"邑","fq":"側鳩切","vol":"06","py":"zōu","duan":[{"e":"魯縣。古邾婁國。帝顓頊之後所封。","n":"魯國騶、二志同。二志作騶、許作鄒者。葢許本作魯騶縣。如今汝南新息、今南陽穰縣之比。淺者乃刪去騶字耳。周時或云鄒、或云邾婁者。語言緩急之殊也。周時作鄒、漢時作騶者。古今字之異也。邾婁各本無婁。今依韵會所據正。左、榖作邾。公羊、檀弓作邾婁。婁如字。邾又夷也。邾婁之合聲爲鄒。夷語也。國語、孟子作鄒。三者鄒爲正。邾則省文。故邾篆下不言春秋邾國。此必依公羊作邾婁國也。漢時縣名作騶。如韓勑碑陰騶韋仲卿足證。鄭語曰。曹姓鄒莒。韋云。陸終第五子曰安。爲曹姓。封於鄒。杜諩云。邾、曹姓。顓頊之後。有六終。產六子。其弟五子曰安。邾卽安之後也。周武王封其苗裔俠爲附庸。居邾。前志曰。騶故邾國。曹姓。二十九世爲楚所滅。按"}]},"䣄":{"expl":"邾下邑地。从邑余聲。魯東有䣄城。讀若塗。","rad":"邑","fq":"同都切","vol":"06","py":"tú","duan":[{"e":"邾下邑地。","n":"邾當作鄒。如鄾篆與鄧篆相聮之例。地當作也。周禮雍氏注。伯禽以王師征徐戎。劉本徐作䣄、音徐。按魯世家。頃公十九年。楚伐我。取徐州。徐廣曰。徐州在魯東。今薛縣。引後志曰。魯國薛縣。本國。六國時曰徐州。玉裁謂。楚所取之徐州卽䣄地。疑非薛。齊涽王三年巳封田嬰於薛。不能至魯頃公十九年魯尚有薛也。齊世家。田常執𥳑公於俆州。亦非此徐州。"}]},"邿":{"expl":"附庸國。在東平亢父邿亭。从邑寺聲。《春秋傳》曰：“取邿。”","rad":"邑","fq":"書之切","vol":"06","py":"shī","duan":[{"e":"附庸國。","n":"王制曰。不能五十里者。不合於天子。附於諸矦曰附庸。鄭云。不合、謂不朝會也。小城曰附庸。附庸者、以國事附於大國。不能以名通也。春秋襄十三年夏。取邿。邿者、魯附庸也。"}]},"郰":{"expl":"魯下邑。孔子之鄉。从邑取聲。","rad":"邑","fq":"側鳩切","vol":"06","py":"zōu","duan":[{"e":"魯下邑。孔子之鄉。","n":"論語孔注曰。鄹、孔子父叔梁紇所治邑也。左傳杜注曰。紇、郰邑大夫仲尼父叔梁紇也。檀弓郰曼父之母。鄭云。曼父之母與徵在爲鄰。相善。孔子世家曰。孔子生魯昌平鄉郰邑。杜曰。郰邑、魯縣東南莝城是也。張守節曰。夫子生在鄒之闕里。長徙曲阜。仍號闕里。按杜云莝城者、今不得其詳。說者以爲今鄒縣西北之東鄒村西鄒集是也。孔子世家言郰人輓父。檀弓言郰曼父。鄭注言郰叔梁紇。葢孔子之父、魯人以郰人紇呼之。如周禮之鄉以州名、野以邑名。非郰爲所治邑也。論語云郰人之子者、孔子弟子爲師諱紇字也。郰大夫之文始見於王肅私定家語。而孔氏論語注乃肅輩僞托者。"}]},"郕":{"expl":"魯孟氏邑。从邑成聲。","rad":"邑","fq":"氏征切","vol":"06","py":"chénɡ","duan":[{"e":"魯孟氏邑。","n":"今春秋三經三傳皆作成。郕成古今字也。左傳昭七年。晉人來治杞田。季孫將以成與之。杜云。成、孟氏邑。本杞田。定十二年。將墮成。公斂處父曰。墮成。齊人必至于北門。杜云。成在魯北竟。按孟氏邑非姬姓郕國之地也。今左傳隱五年衞人入郕。文十二年郕伯來奔。僖卄四年管蔡郕霍。文之昭也。字皆正作郕。而許不云姬姓之國者。葢許所據左氏郕成字互易。不可以今所據繩許也。公羊郕國之字則作盛。古郕國在今兖州府汶上縣北二十里故郕城。不在魯北竟。"}]},"䣍":{"expl":"周公所誅䣍國。在魯。从邑奄聲。","rad":"邑","fq":"依檢切","vol":"06","py":"yǎn","duan":[{"e":"周公所誅䣍國。在魯。","n":"玉篇作周公所誅叛國商奄。是也。奄䣍二字周時竝行。今則奄行而䣍廢矣。單呼曰奄。絫呼曰商奄。書序、孟子、左傳皆云奄。如踐奄、歸自奄、伐奄、昭元年周有徐奄、是也。左傳又云商奄。如昭九年蒲姑商奄吾東土也、定四年因商奄之民命以伯禽而封於少暭之虛、是也。大部曰。奄、覆也。爾雅。弇、葢也。故商奄亦呼商葢。墨子曰。周公旦非關叔辭三公。東處於商葢。韓非子曰。周公旦將攻商葢。辛公甲曰。不如服衆小以劫大。乃攻九夷。而商葢服矣。商葢卽商奄也。奄在淮北。近魯。故許云在魯。鄭注書序云。奄在淮夷之北、注多方云奄在淮夷旁、是也。祝鮀說因商奄之民封魯者、杜云或逬散在魯是也。今山東兖州府曲阜縣縣城東二里有奄城、云故奄國。卽？地志"}]},"酄":{"expl":"魯下邑。从邑雚聲。《春秋傳》曰：“齊人來㱕酄。”","rad":"邑","fq":"呼官切","vol":"06","py":"huān","duan":[{"e":"魯下邑。","n":"春秋經定十年。齊人來歸鄆、讙、龜陰之田。鄆、公羊作運。讙、三經三傳皆同。許作酄。容許所據異也。應劭注前志引春秋哀八年取酄及闡。字亦作酄。賈、服云。鄆讙二邑名。左傳桓三年杜注曰。讙、魯地。濟北蛇丘縣西有下讙亭。"}]},"芰":{"expl":"蔆也。从艸支聲。","rad":"艸","fq":"奇記切","vol":"01","py":"jì","duan":[{"e":"蔆也。","n":"是謂轉注。"}]},"郎":{"expl":"魯亭也。从邑良聲。","rad":"邑","fq":"魯當切","vol":"06","py":"lánɡ","duan":[{"e":"魯亭也。","n":"春秋隱元年。費伯率師城郎。桓四年。公狩于郎。十年。齊矦衞矦鄭伯來戰于郎。莊八年。師次于郎。以俟陳人蔡人。三十一年。築臺于郎。哀十一年。戰于郊。檀弓作戰於郎。鄭曰。郎、魯近邑也。杜云。郎、魯邑。高平方與縣東南有郁郎亭。按以郎爲男子之偁及官名者、皆良之假借字也。"}]},"邳":{"expl":"奚仲之後，湯左相仲虺所封國。在魯辥縣。从邑丕聲。","rad":"邑","fq":"敷悲切","vol":"06","py":"pī","duan":[{"e":"奚仲之後湯左相仲虺所封國。","n":"左傳定元年。薛宰曰。薛之皇祖奚仲居薛。以爲夏車正。奚仲遷於邳。仲虺居薛。以爲湯左相。諩云。薛、任姓。黃帝之苗裔奚仲封爲薛矦。今魯國薛縣是也。奚仲遷於邳。仲虺居薛。以爲湯左相。武王復以其冑爲薛矦。齊桓黜爲伯。小國無記。世不可知。亦不知爲誰所滅。按杜亦云仲虺、奚仲之後。與許合。邳者、所封國名。如？𨜒邰扈邘𨛫郉？鄎鄧郜鄶鄅等字之例。左傳昭元年云。虞有三苗。夏有觀扈。商有姺邳。周有徐奄。皆國名也。杜云。姺邳二國、商諸矦。按葢謂仲虺之後爲亂者也。"}]},"鄣":{"expl":"紀邑也。从邑章聲。","rad":"邑","fq":"諸良切","vol":"06","py":"zhānɡ","duan":[{"e":"紀邑也。","n":"春秋經莊三十年。齊人降鄣。公羊、榖梁皆曰。鄣、紀之遺邑也。劉歆、賈逵依之。許說同。杜云。紀附庸國。東平無鹽縣東北有鄣城。歫紀太遠。非許意也。古紀國在今山東青州府壽光縣西南三十里紀城。鄣邑當附近。卽昭十九年左傳之紀鄣也。紀鄣者、本紀國之鄣邑。猶齊語紀酅謂本紀國之酅邑也。公、榖云鄣、紀之遺邑。與左傳云紀鄣合。杜云。紀鄣在東海贛榆。是也。莊三十年之鄣卽此。杜分爲兩地。非。今江蘇海州贛榆縣縣北七十五里有故紀鄣城。亦曰紀城。"}]},"邗":{"expl":"國也，今屬臨淮。从邑干聲。一曰邗本屬吳。","rad":"邑","fq":"胡安切","vol":"06","py":"hán","duan":[{"e":"國也。今屬臨淮。","n":"左傳哀九年。吳城邗。溝通江淮。杜云。於邗江築城穿溝。東北通射陽湖。西北至末口入淮。通糧道也。今廣陵邗江是。按左傳吳城邗爲句。溝通江淮爲句。曰城邗、則知邗地名。許云國者、許必有所據矣。本是邗國。其地漢屬臨淮郡。不言何縣者、有未審也。此與鄦在潁川、鄧屬南陽一例。地理志曰。廣陵國江都。有渠水首受江。北至射陽入湖。水經注曰。邗城下掘深溝、謂之韓江。亦曰邗溟溝。自江東北通射陽湖。地理志所謂渠水也。西北至末口入淮。江都縣、前志屬廣陵郡。許云今屬臨淮者、許意邗國地當在前漢臨淮郡。不在廣陵也。"}]},"䣡":{"expl":"臨淮徐地。从邑義聲。《春秋傳》曰：“徐䣡楚。”","rad":"邑","fq":"魚羈切","vol":"06","py":"yí","duan":[{"e":"臨淮徐地。","n":"前志曰。臨淮郡、徐故國。盈姓。春秋時徐子章禹爲楚所滅。後志曰。下邳國、徐本國。後志之下邳國、卽前志之臨淮郡也。今安徽泗州州北五十里有故徐城廢縣。䣡者、徐縣地名也。"}]},"郈":{"expl":"東平無鹽鄉。从邑后聲。","rad":"邑","fq":"胡口切","vol":"06","py":"hòu","duan":[{"e":"東平無鹽鄉。","n":"東平國無鹽、二志同。杜預曰。故宿國。今山東東平州州東二十里有故無鹽城。前志曰。無鹽有郈鄉。左傳昭二十五年。臧會逸奔郈。杜曰。東平無鹽縣東南有郈鄉亭。左正義曰。此時尚爲公邑。後爲叔孫私邑。"}]},"郯":{"expl":"東海縣。帝少昊之後所封。从邑炎聲。","rad":"邑","fq":"徒甘切","vol":"06","py":"tán","duan":[{"e":"東海縣。","n":"東海郡郯、二志同。今山東沂州府郯城縣縣西南百里有故郯城。"}]},"郚":{"expl":"東海縣。故紀矦之邑也。从邑吾聲。","rad":"邑","fq":"五乎切","vol":"06","py":"wú","duan":[{"e":"東海縣。","n":"前志云。東海郡郚鄉。疑此當云郚鄉東海縣。"}]},"酅":{"expl":"東海之邑。从邑巂聲。","rad":"邑","fq":"戶圭切","vol":"06","py":"xī","duan":[{"e":"東海之邑。","n":"春秋經莊三年。紀季以酅入于齊。前志甾川國、東安平。孟康注曰。春秋之酅、今酅亭是也。後志東安平屬北海國。有酅亭。按前志云甾川國。後幷北海。疑許當云北海之邑。酅亭在今山東青州府臨淄縣縣東。齊語曰。正封疆地東至于紀酅。紀酅猶言紀鄣。謂故紀國之酅也。"}]},"鄫":{"expl":"姒姓國。在東海。从邑曾聲。","rad":"邑","fq":"疾陵切","vol":"06","py":"cénɡ","duan":[{"e":"姒姓國。","n":"按許書無姒字。漢碑姒作似。左傳。衞成公命祀夏后相。甯武子不可。曰杞鄫何事。國語韋注曰。杞繒二國姒姓。夏禹之後。"}]},"薢":{"expl":"薢茩也。从艸解聲。","rad":"艸","fq":"胡買切","vol":"01","py":"xiè","duan":[{"e":"薢茩也。","n":"不云蔆也者、已見上矣。王注離騷曰。芰、䔖也。秦人曰薢茩。按薢與芰同在十六部。徐言之則云薢茩。"}]},"邪":{"expl":"琅邪郡。从邑牙聲。","rad":"邑","fq":"以遮切","vol":"06","py":"yé","duan":[{"e":"琅邪郡也。","n":"謂琅邪郡之字如此作也。前志曰。琅邪郡、秦置。屬徐州。後志曰。琅邪國、屬徐州刺史部。許從前漢之制、故曰郡。前志。郡領東武等五十一縣。今山東兖州府東境、沂州府及青州府南境、莒州、萊州府南境、膠州一帶皆是其地。今兖州府諸城縣縣東南百四十里有故琅邪城。古齊琅邪邑也。其地有琅邪山。管子。齊桓公將東遊。南至琅邪。孟子。齊景公欲遵海而南。放於琅邪。蘇秦說齊宣王曰。齊南有泰山。東有琅邪。史記。秦始皇屢竝海至琅邪。子虚賦曰。齊東陼鉅海。南有琅邪。皆謂今諸城縣。山海經云琅邪臺在渤海郡閒。非也。趙岐曰。琅邪、齊東南境上邑。越？書。句踐旣滅吳。欲霸中國。徙都琅邪。立觀臺於山上。周七里。以望東海。始皇立琅邪郡、爲三十六"}]},"邞":{"expl":"琅邪縣。一名純德。从邑夫聲。","rad":"邑","fq":"甫無切","vol":"06","py":"fū","duan":[{"e":"琅邪縣也。","n":"前志。琅邪郡、邞。後志無。幷省也。漢孝文元年。封吕平爲矦國。"}]},"䣛":{"expl":"齊地也。从邑桼聲。","rad":"邑","fq":"親吉切","vol":"06","py":"qī","duan":[{"e":"齊地也。从邑。桼聲。","n":"親吉切。十二部。"}]},"郭":{"expl":"齊之郭氏虚。善善不能進，惡惡不能退，是以亡國也。从邑𩫏聲。","rad":"邑","fq":"古博切","vol":"06","py":"ɡuō","duan":[{"e":"齊之郭氏虛。","n":"謂此篆乃齊郭氏虚之字也。郭本國名。虚墟古今字。郭國旣亡謂之郭氏虛。如左傳言少昊之虛、昆吾之虚、大曍之虚、祝融之虚也。郭氏虛在齊境內。"}]},"郳":{"expl":"齊地。从邑兒聲。《春秋傳》曰：“齊高厚定郳田。”","rad":"邑","fq":"五雞切","vol":"06","py":"ní","duan":[{"e":"齊地。从邑。兒聲。","n":"五雞切。十六部。"}]},"郣":{"expl":"郣海地。从邑孛聲。一曰地之起者曰郣。","rad":"邑","fq":"蒲沒切","vol":"06","py":"bó","duan":[{"e":"郣地。","n":"此從鍇本。鉉作郣海地。非是。郣是複舉字之未刪者。地謂有地名郣也。今其地未聞。葢春秋時齊地也。若漢二志之勃海郡。今直隷河閒、天津二府地。其謂之勃海者。師古曰。在勃海之濵。因以爲名也。水部澥下曰。勃澥、海之別也。漢書子虚賦音義曰。勃澥。海別枝也。勃澥、史記河渠書謂之勃海。今靜海縣之海與山東遼東接境者、卽勃澥。司馬相如賦所以自琅邪觀成山。射之罘而浮勃澥。始皇所以竝勃海以東。過黃腄。窮成山。登之罘。而南登琅邪也。齊都賦注曰。海旁曰勃。𣃔水曰澥。勃與郣似可通。然勃海郡、勃澥、字皆不作郣。假令勃海郡字可作郣。則許當云郣海郡也。而不曰地。"}]},"𨝸":{"expl":"國也。齊桓公之所滅。从邑覃聲。","rad":"邑","fq":"徒含切","vol":"06","py":"tán","duan":[{"e":"國也。齊桓公之所滅。","n":"衞風曰。譚公維私。小雅曰。東國困於役而傷於讒。譚大夫作大東以告病。左傳莊十年曰。齊師滅譚。譚無禮也。譚子奔莒。同盟故也。今濟南府府東南七十里有故譚城。在二志濟南郡之東平陵縣。東平陵故城在今濟南府府東七十五里。"}]},"邭":{"expl":"地名。从邑句聲。","rad":"邑","fq":"其俱切","vol":"06","py":"qú","duan":[{"e":"地名。","n":"左傳注多不言名。如毛傳云水也、山也、地也、皆是。許君亦不言名。如郣地也、邭地也、以及邑也、國也、皆是。凡言名者、後人所改。"}]},"郂":{"expl":"陳畱鄉。从邑亥聲。","rad":"邑","fq":"古哀切","vol":"06","py":"ɡāi","duan":[{"e":"陳畱鄉。","n":"陳畱郡、二志同。今河南開封府東至歸德府西皆是其境。陳畱郡屬有陳畱縣。此不云陳畱縣鄉、但云陳畱鄉。則是舉郡名不箸某縣也。曷爲不箸。有未審也。郖下曰弘農縣。鄏下曰河南縣。是舉郡縣同名之例。"}]},"𨚵":{"expl":"故國。在陳畱。从邑𢦔聲。","rad":"邑","fq":"作代切","vol":"06","py":"zài","duan":[{"e":"故國在陳畱。","n":"春秋經隱十年。宋人蔡人衞人伐載。三經皆作載。惟榖梁音義曰。載本或作戴。而前志作戴。古載戴同音通用耳。許作？。左氏音義引字林亦作？。吕本許。許所據從邑也。前志云。梁國甾、故戴國。後志云。陳畱郡考城、故葘。注引陳畱志云。古戴國。今河南衞輝府考城縣縣東南五里有考城故城。漢之甾縣。古之？國也。甾與？古音同。？古字。甾漢字。許云在陳畱者、章帝改名考城屬陳畱也。水經注汳水篇曰。陳畱風俗傳曰。秦之榖縣。後遭漢兵起。邑多災年。故改曰葘縣。王莽更名嘉榖。章帝東巡。詔曰。葘縣名不善。其改曰考城。按莽、章帝不達同音譌字之源委。故不能正爲？字。而風俗傳云秦之榖縣、則更無稽之言耳。"}]},"茩":{"expl":"薢茩也。从艸后聲。","rad":"艸","fq":"胡口切","vol":"01","py":"ɡòu","duan":[{"e":"薢茩也。从艸。后聲。","n":"蔆以角得名。蔆之言棱也。茩之言角也。茩角雙聲。同在第三部。唐韵胡口切。薢茩雙聲。"}]},"酀":{"expl":"地名。从邑燕聲。","rad":"邑","fq":"烏前切","vol":"06","py":"yān","duan":[{"e":"地名。从邑。燕聲。","n":"烏前切。十四部。齊有高酀、卽高偃。高傒之玄孫。左傳曰敬仲之曾孫者。古人立文、後裔統云曾孫。"}]},"邱":{"expl":"地名。从邑丘聲。","rad":"邑","fq":"去鳩切","vol":"06","py":"qiū","duan":[{"e":"地名。从邑。丠聲。","n":"去鳩切。古音在一部。今制、諱孔子名之字曰邱。"}]},"𨚴":{"expl":"地名。从邑如聲。","rad":"邑","fq":"人諸切","vol":"06","py":"rú","duan":[{"e":"地名。从邑。如聲。","n":"人諸切。五部。"}]},"𨙺":{"expl":"地名。从邑丑聲。","rad":"邑","fq":"女九切","vol":"06","py":"niǔ","duan":[{"e":"地名。从邑。丑聲。","n":"女九切。三部。"}]},"䢳":{"expl":"地名。从邑几聲。","rad":"邑","fq":"居履切","vol":"06","py":"jǐ","duan":[{"e":"地名。从邑。几聲。","n":"居履切。十五部。按西伯？𨛫。周本紀作耆。徐廣曰。一作？。？葢卽䢳字。"}]},"𨝫":{"expl":"地名。从邑翕聲。","rad":"邑","fq":"希立切","vol":"06","py":"xì","duan":[{"e":"地名。从邑。翕聲。","n":"希立切。七部。"}]},"䣇":{"expl":"地名。从邑求聲。","rad":"邑","fq":"巨鳩切","vol":"06","py":"qiú","duan":[{"e":"地名。","n":"玉篇曰。䣇鄉在陳畱。"}]},"𨟙":{"expl":"地名。从邑嬰聲。","rad":"邑","fq":"於郢切","vol":"06","py":"yīnɡ","duan":[{"e":"地名。从邑。嬰聲。","n":"於郢切。十一部。"}]},"𨜂":{"expl":"地名。从邑尚聲。","rad":"邑","fq":"多朗切","vol":"06","py":"dǎnɡ","duan":[{"e":"地名。","n":"廣韵曰。䣣、地名。說文作䣊。"}]},"郱":{"expl":"地名。从邑并聲。","rad":"邑","fq":"薄經切","vol":"06","py":"pínɡ","duan":[{"e":"地名。从邑。幷聲。","n":"薄經切。十一部。前志。齊郡臨胊。應劭云。有伯氏騈邑。後志。齊國臨胊。有古郱邑。按春秋莊元年。齊師遷紀郱、鄑、郚。杜云。郱在東莞臨胊縣東南。齊取其地。然則伯氏騈邑卽此地。騈卽郱字。今山東靑州府臨胊縣東南有郱城是也。未知許意然不。"}]},"芡":{"expl":"雞頭也。从艸欠聲。","rad":"艸","fq":"巨險切","vol":"01","py":"qiàn","duan":[{"e":"雞頭也。","n":"周禮加籩之實有芡注同此。方言䓈、芡、雞頭也。北燕謂之䓈。靑徐淮泗之閒謂之芡。南楚江湘之閒謂之雞頭。或謂之鴈頭。或謂之烏頭。"}]},"𨝘":{"expl":"地名。从邑虖聲。","rad":"邑","fq":"呼古切","vol":"06","py":"hǔ","duan":[{"e":"地名。","n":"玉篇云。魯地名。"}]},"邩":{"expl":"地名。从邑火聲。","rad":"邑","fq":"呼果切","vol":"06","py":"huǒ","duan":[{"e":"地名。从邑。火聲。","n":"呼果切。十七部。"}]},"鄝":{"expl":"地名。从邑翏聲。","rad":"邑","fq":"盧鳥切","vol":"06","py":"liǎo","duan":[{"e":"地名。从邑。翏聲。","n":"盧鳥切。三部。左傳文公五年。楚滅蓼。釋文云。字或作鄝。榖梁宣八年經。楚人滅舒鄝。釋文云。本又作蓼。小雅。漸漸之石。詩序注云。舒、舒鳩舒鄝舒庸之屬。釋文云。鄝又作蓼。按坊記陽矦繆矦卽淮南氾論訓之陽矦蓼矦。繆者、字誤耳。前志六安國。後志廬江郡。皆作蓼。許不謂此也。"}]},"鄬":{"expl":"地名。从邑爲聲。","rad":"邑","fq":"居爲切","vol":"06","py":"ɡuī","duan":[{"e":"地名。从邑。爲聲。","n":"居爲切。十七部。春秋經襄七年。公會晉矦、宋公、陳矦、衞矦、曹伯、莒子、邾子于鄬。杜云。鄬、鄭地。"}]},"邨":{"expl":"地名。从邑屯聲。","rad":"邑","fq":"此尊切","vol":"06","py":"cūn","duan":[{"e":"地名。从邑。屯聲。","n":"此尊切。十二部。按本音豚。屯聚之意也。俗讀此尊切。又變字爲村。"}]},"𨛭":{"expl":"地名。从邑舍聲。","rad":"邑","fq":"式車切","vol":"06","py":"shū","duan":[{"e":"地名。从邑。舍聲。","n":"式車切。五部。按玉篇引春秋。徐人取？。杜預云。今廬江舒縣。按僖三年三經皆作舒。魯頌亦作舒。二志廬江舒縣、亦皆作舒。未審希馮所據。"}]},"𨜴":{"expl":"地名。从邑盍聲。","rad":"邑","fq":"胡蠟切","vol":"06","py":"hé","duan":[{"e":"地名。从邑。盇聲。","n":"胡蠟切。八部。二志泰山郡皆有葢縣。孟子有葢大夫。廣韵蓋姓。字書作𨜴。古盍切。"}]},"𨝌":{"expl":"地名。从邑乾聲。","rad":"邑","fq":"古寒切","vol":"06","py":"ɡān","duan":[{"e":"地名。从邑。乾聲。","n":"古寒切。十四部。"}]},"𨟏":{"expl":"地名。从邑𤎭聲。讀若淫。","rad":"邑","fq":"力荏切","vol":"06","py":"yín","duan":[{"e":"地名。从邑。𤎭聲。讀若淫。","n":"力荏切。七部。"}]},"邖":{"expl":"地名。从邑山聲。","rad":"邑","fq":"所間切","vol":"06","py":"shān","duan":[{"e":"地名。从邑。山聲。","n":"所閒切。十四部。"}]},"䕮":{"expl":"日精也。以秋華。从艸，𥶶省聲。居六切。","rad":"艸","fq":"居六切","vol":"01","py":"jú","duan":[{"e":"日精也。㠯秋華。","n":"以各本作似。今依宋本及韵會正。本艸經。菊花一名節花。又曰。一名日精。按一名節花、卽許所謂以秋華也。一名日精與許合。夏小正。九月榮鞠。鞠艸也。鞠榮而樹麥。時之急也。月令。鞠有黃華。離騷。夕餐秋菊之落英。字或作菊、或作鞠。以說文繩之。皆叚借也。釋艸。蘜、治牆。郭云。今之秋華菊。郭意蘜菊爲古今字玉裁謂。許君剖析菊爲大菊、蘧麥。蘜爲治牆。蘜爲日精。分廁三所。又恐學者以其同音易溷也。著之曰以秋華、言此䕮字乃小正、月令之布華玄月者也。然則許意治牆別是一物。種類甚殊。如大菊之非䕮。郭注爾雅與許全乖。攷郭氏所注小學三書。今存者二。有時涉及字林、而絶未嘗偁用說文也本艸經、名毉別錄秋華有九名而無治牆。則治牆之非秋"}]},"𨟐":{"expl":"地名。从邑㙶聲。㙶，古堂字。","rad":"邑","fq":"徒郎切","vol":"06","py":"tánɡ","duan":[{"e":"地名。从邑。㙶聲。","n":"徒郞切。十部。玉篇䣘𨟐二同。引續漢書云。廣陵䣘邑也。按續漢書謂司馬彪郡國志也。今志作堂邑。云故屬臨淮。春秋時曰堂。考左傳襄十四年楚子囊師于棠以伐吳。昭二十年棠君五尚。字皆從木。而廣韵引風俗通。堂、楚邑。大夫五尚爲之。其後氏焉。字從土。葢今左傳從木、或誤。堂邑今江蘇江寧府六合縣是也。許但云地名。未知謂此地與否。"}]},"𨝭":{"expl":"姬姓之國。从邑馮聲。","rad":"邑","fq":"房成切","vol":"06","py":"fénɡ","duan":[{"e":"姬姓之國。","n":"廣韵曰。馮、姓也。畢公高之後。食采於馮城。因而命氏。左傳云。畢者文之昭。王肅注尚書云。畢毛、文王庶子。然則𨝭爲姬姓國。其後以國氏。省作馮也。師古云馮歸姓。恐非。字廁於此者、許不審𨝭地所在。"}]},"𨛖":{"expl":"汝南安陽鄉。从邑，𦳋省聲。","rad":"邑","fq":"苦怪切","vol":"06","py":"kuài","duan":[{"e":"汝南安陽鄉。","n":"汝南郡安陽、二志同。今河南汝寧府眞陽縣縣東故安陽城是也。有鄉名𨛖。"}]},"郙":{"expl":"汝南上蔡亭。从邑甫聲。","rad":"邑","fq":"方矩切","vol":"06","py":"fǔ","duan":[{"e":"汝南上蔡亭。","n":"汝南郡上蔡、二志同。今河南汝寧府上蔡縣縣西南十里故蔡城是也。有亭名郙。"}]},"酈":{"expl":"南陽縣。从邑麗聲。","rad":"邑","fq":"郎擊切","vol":"06","py":"lì","duan":[{"e":"南陽縣。","n":"南陽郡酈、二志同。秦二世二年。沛公攻析酈皆下之。則是秦所置縣。今河南南陽府内鄉縣縣東北有故酈縣城。"}]},"𨟦":{"expl":"地名。从邑𠨧聲。","rad":"邑","fq":"七然切","vol":"06","py":"qiān","duan":[{"e":"地名。从邑。𠨧聲。","n":"七然切。十四部。"}]},"𨙨":{"expl":"从反邑。𨛜字从此。闕。","rad":"邑","fq":"","vol":"06","py":"yì","duan":[{"e":"从反邑。𨛜字从此。闕。","n":"闕謂其音闕也。"}]},"𨛜":{"expl":"鄰道也。从邑从𨙨。凡𨛜之屬皆从𨛜。闕。(今隷變作𨙵。)","rad":"𨛜","fq":"胡絳切","vol":"06","py":"xiànɡ","duan":[{"e":"鄰道也。","n":"道當爲邑。字之誤也。其字從二邑會意。"}]},"𨞰":{"expl":"國離邑，民所封鄉也。嗇夫別治。封圻之内六鄉，六鄉治之。从𨛜皀聲。","rad":"𨛜","fq":"許良切","vol":"06","py":"xiānɡ","duan":[{"e":"國離邑。","n":"離邑、如言離宫別館。國與邑名可互偁。析言之則國大邑小。一國中離析爲若干邑。"}]},"𨞠":{"expl":"里中道。从𨛜从共。皆在邑中所共也。","rad":"𨛜","fq":"胡絳切","vol":"06","py":"xiànɡ","duan":[{"e":"里中道也。","n":"不言邑中道、言里中道者。言邑不該里。言里可該邑也。析言之國大邑小、邑大里少。渾言之則國邑通偁、邑里通偁。載師注曰。今人云邑居里。此邑里通偁也。高祖紀云。沛豐邑中陽里人。此邑里析言也。應劭曰。沛縣也。豐其鄉也。然則鄉可偁邑矣。周禮。五家爲鄰。五鄰爲里。此周制也。齊語。五家爲軌。十軌爲里。此齊制也。百官志曰。里魁掌一里百家。什主十家。伍主五家。以相檢察。此漢制也。里中之道曰巷。古文作。𨞠雅作衖。引伸之凡夾而長者皆曰巷。宫中衖謂之壷是也。十七史言弄者、皆卽巷字。語言之異也。今江蘇俗尚云弄。"}]},"蘥":{"expl":"爵麥也。从艸龠聲。","rad":"艸","fq":"以勺切","vol":"01","py":"yuè","duan":[{"e":"爵麥也。","n":"見釋艸。爵當依今釋艸作雀。許君從所據耳。郭云。卽燕麥也。生故墟野林下。苗實俱似麥。或云爵麥卽穱麥。誤也。招䰟、七發皆云穱麥。穱卽𥼚字之異者。古爵焦聲同在弟二部。許云𥼚、早取穀也。招魂王注云。擇麥中先熟者也。義正同。"}]},"日":{"expl":"實也。太陽之精不虧。从囗一。象形。凡日之屬皆从日。","rad":"日","fq":"人質切","vol":"07","py":"rì","duan":[{"e":"實也。","n":"以疊韵爲訓。月令正義引春秋元命包云。日之爲言實也。釋名曰。日、實也。光明盛實也。"}]},"旻":{"expl":"秋天也。从日文聲。《虞書》曰：“仁閔覆下，則稱旻天。”","rad":"日","fq":"武巾切","vol":"07","py":"mín","duan":[{"e":"秋天也。","n":"此爾雅釋天及歐陽尙書說也。釋天曰。春爲昊天。夏爲蒼天。秋爲旻天。冬爲上天。許、鄭本如是。孫炎、郭樸本乃作春蒼夏昊。"}]},"時":{"expl":"四時也。从日寺聲。","rad":"日","fq":"市之切","vol":"07","py":"shí","duan":[{"e":"四時也。","n":"本春秋冬夏之稱。引伸之爲凡嵗月日刻之用。釋詁曰。時、是也。此時之本義。言時則無有不是者也。廣雅曰。時伺也。此引伸之義。如不能辰夜、遠猶辰告傳皆云辰時也是也。"}]},"早":{"expl":"晨也。从日在甲上。","rad":"日","fq":"子浩切","vol":"07","py":"zǎo","duan":[{"e":"䢅也。","n":"䢅者、早昧爽也。二字互訓。引伸爲凡爭先之偁。周禮大司徒早物。叚早爲草。"}]},"昒":{"expl":"尚冥也。从日勿聲。","rad":"日","fq":"呼骨切","vol":"07","py":"hū","duan":[{"e":"尙冥也。","n":"冥者、窈也。幽也。自日入至於此。尙未日出也。司馬相如傳。曶爽暗昧。得燿乎光明。然則曶尙未明也。按漢人曶昧通用不分。故幽通賦昒昕寤而仰思。曹大家曰。昒昕、晨旦明也。韋昭曰。昒、昧忽㒳音。郭樸注三倉解詁云。曶、旦明也。然則獨許分別曶爲未明。昧爽爲且明。以其時相際。故說之者異。"}]},"昧":{"expl":"爽，旦明也。从日未聲。一曰闇也。","rad":"日","fq":"莫佩切","vol":"07","py":"mèi","duan":[{"e":"昧爽、","n":"逗。昧字舊奪。今補。"}]},"暏":{"expl":"旦明也。从日者聲。","rad":"日","fq":"當古切","vol":"07","py":"dǔ","duan":[{"e":"且朙也。","n":"各本作旦明。誤。今正作且明。暏與昧爽同義。許書有暏無曙。而文選魏都賦、謝康樂溪行詩李注竝引作曙。古今字形異耳。許本作暏。後乃變爲曙。署亦者聲也。玉篇曶昧二文間出曙字。市據切。此顧希馮以今字易古字也。後出暏字。丁古切。此孫強、陳彭年輩所據說文妄增者也。呂覽謂一朝爲一曙。廣韵曰。暏、詰朝欲明也。"}]},"晢":{"expl":"昭晣，明也。从日折聲。《禮》曰：“晣明行事。”","rad":"日","fq":"旨熱切","vol":"07","py":"zhé","duan":[{"e":"昭晢、","n":"逗。"}]},"昭":{"expl":"日明也。从日召聲。","rad":"日","fq":"止遙切","vol":"07","py":"zhāo","duan":[{"e":"日朙也。","n":"引伸爲凡明之偁。廟有昭穆。昭取陽明。穆取陰幽。皆本無正字。叚此二字爲之。自晉避司馬昭諱。不敢正讀。一切讀上饒反。而陸氏乃以入經典釋文。陋矣。又別製佋字。注云。廟昭穆。父爲佋南面。子爲穆北面。从人召聲。此冣爲不通。昭穆乃鬼神之偁。其字當从示。而从人何也。無識者又取以竄入說文人部中。其亂名改作有如此者。今人部𠜂佋。"}]},"晤":{"expl":"明也。从日吾聲。《詩》曰：“晤辟有摽。”","rad":"日","fq":"五故切","vol":"07","py":"wù","duan":[{"e":"朙也。","n":"晤旳晄曠四篆不必專謂日之明。然莫明于日。故四字皆从日而廁于此也。晤者、启之明也。心部之悟、㝱部之寤皆訓覺。覺亦明也。同聲之義必相近。"}]},"藗":{"expl":"牡茅也。从艸遬聲。遬，籀文速。","rad":"艸","fq":"桑谷切","vol":"01","py":"sù","duan":[{"e":"牡茅也。","n":"見釋艸。此當與菅茅二篆類廁而不爾者、葢其種類殊也。"}]},"旳":{"expl":"明也。从日勺聲。《易》曰：“爲旳顙。”","rad":"日","fq":"都歴切","vol":"07","py":"dì","duan":[{"e":"朙也。","n":"旳者、白之明也。故俗字作的。漢魯峻碑曰。永傳𠶷齡。㬇矣旳旳。引伸爲䠶的。"}]},"晄":{"expl":"明也。从日光聲。","rad":"日","fq":"胡廣切","vol":"07","py":"huǎnɡ","duan":[{"e":"朙也。","n":"各本篆作晄。篇、韵皆云。晃正、晄同。今正。晃者、動之明也。凡光必動。會意兼形聲字也。楊雄賦。北熿幽都。李善云。熿與晃音義同。"}]},"曠":{"expl":"明也。从日廣聲。","rad":"日","fq":"苦謗切","vol":"07","py":"kuànɡ","duan":[{"e":"朙也。","n":"廣大之明也。會意兼形聲字也。引伸爲虛空之偁。"}]},"旭":{"expl":"日旦出皃。从日九聲。若勖。一曰明也。","rad":"日","fq":"許玉切","vol":"07","py":"xù","duan":[{"e":"日旦出皃。","n":"邶風。旭日始旦。傳曰。旭者、日始出。謂大昕之時。旭與曉雙聲。釋訓曰。旭旭、蹻蹻、憍也。郭云。皆小人得志憍蹇之皃。此其引伸叚借之義也。今詩旭旭作好好。同音叚借字也。"}]},"晉":{"expl":"進也。日出萬物進。从日从臸。《易》曰：“明出地上，㬜。”","rad":"日","fq":"卽刀切","vol":"07","py":"jìn","duan":[{"e":"進也。","n":"周易彖傳曰。晉、進也。以疊韵爲訓。凡進皆曰晉。難進亦曰晉。周禮。凡田。王提馬而走。諸矦晉。是也。禮古文、周禮故書皆叚晉爲箭。"}]},"暘":{"expl":"日出也。从日昜聲。《虞書》曰：“暘谷。”","rad":"日","fq":"與章切","vol":"07","py":"yánɡ","duan":[{"e":"日出也。","n":"洪範。八、庶徵。曰雨、曰暘。某氏云。雨以潤物。暘以乾物。祭義。夏后氏祭其闇。殷人祭其陽。周人祭曰以朝及闇。鄭云闇、昏時也。陽讀爲曰雨曰暘之暘。謂日中時也。朝、日出時也。暘之義當从鄭。孟子。秋陽以㬥之。亦當作秋暘。"}]},"晵":{"expl":"雨而晝夝也。从日，啓省聲。","rad":"日","fq":"康禮切","vol":"07","py":"qǐ","duan":[{"e":"雨而晝夝也。","n":"晵之言闓也。夝者、雨而夜除星見也。雨而晝除見日則謂之晵。晵亦謂之夝。"}]},"晹":{"expl":"日覆雲暫見也。从日易聲。","rad":"日","fq":"羊益切","vol":"07","py":"yì","duan":[{"e":"日覆雲暫見也。","n":"覆云者、揜於雲。暫見者、倏見也。此與目部䁑{睗?}義畧同。"}]},"昫":{"expl":"日出溫也。从日句聲。北地有昫衍縣。","rad":"日","fq":"火于切","vol":"07","py":"xū","duan":[{"e":"日出𥁕也。","n":"𥁕各本作溫。今正。詳水部。昫與火部煦義畧同。樂記煦嫗。淮南書作昫嫗。廣韵直以爲一字。周禮注曰。司馬法。旦明𡔷五通爲發昫。是知主初日出言也。"}]},"晛":{"expl":"日見也。从日从見，見亦聲。《詩》曰：“見晛曰消。”","rad":"日","fq":"胡甸切","vol":"07","py":"xiàn","duan":[{"e":"日見也。","n":"毛詩。見晛曰消。毛云。晛、日氣也。韓詩。曣晛聿消。韓云。曣晛、日出也。二解義相足。日出必有溫氣也。廣雅釋詁云。曣㬗、煗也。曣㬗卽韓詩之曣晛。煗卽毛日氣之說。荀卿非相篇引詩作宴然。宴然。卽曣㬗也。宴晏曣古通用。玉篇曰。㬗同晛。"}]},"𦮺":{"expl":"茅秀也。从艸私聲。","rad":"艸","fq":"息夷切","vol":"01","py":"sī","duan":[{"e":"茅秀也。","n":"廣雅曰。䔑、𦮺、茅穗也。䔑卽荼字之變。周禮儀禮注、鄭風箋、吳語注皆云。荼、茅秀。當是荼爲茅之秀。𦮺爲藗之秀。統言之則曰茅秀而已。其色正白。"}]},"晏":{"expl":"天清也。从日安聲。","rad":"日","fq":"烏諫切","vol":"07","py":"yàn","duan":[{"e":"天淸也。","n":"楊雄羽獵賦曰。天淸日晏。李引許淮南子注曰。晏、無雲之處也。漢天文志曰。日餔時天星晏。星卽今之晴字。淮南書。鶤日知晏。陰蠟知雨。晏對陰而言。如淳注郊祀志云。三輔謂日出淸濟爲晏。按郊祀之晏溫。封禪書作曣㬈。猶氤氳也。郊祀志字異而義同。如淳以日出淸霽釋之。謂晏而溫是爲異。非是。晏之言安也。古晏安通用。故今文堯典晏晏。古文作安安。左傳安孺子。古今人表作晏孺子。"}]},"㬫":{"expl":"星無雲也。从日燕聲。","rad":"日","fq":"於甸切","vol":"07","py":"yàn","duan":[{"e":"星無雲也。","n":"姚氏鼐曰。星卽夝字。按日閒雨除亦曰夝。無雲謂晴而無雲也。晴容有有雲者。其字亦作曣。毛詩見晛曰消。韓詩作曣晛聿消。劉向上封事引之。師古注云。曣、無雲也。今漢書譌舛不可讀。韓詩釋曣晛爲日氣。許注淮南釋晏爲無雲。此以天淸釋晏。以晴無雲釋㬫。言各有當。不以音義相近而淆之也。一說星無雲。謂星而無雲。如雨部云風雨土。謂風而雨土也。詩。星言夙駕。韓云。星、晴也。卽許星而無雲之說。"}]},"景":{"expl":"光也。从日京聲。","rad":"日","fq":"居影切","vol":"07","py":"jǐnɡ","duan":[{"e":"日灮也。","n":"日字各本無依文選張孟、陽七哀詩注訂。火部曰。光者、明也。左傳曰。光者遠而自他有燿者也。日月皆外光。而光所在處物皆有陰。光如鏡故謂之景。車牽箋云。景、明也。後人名陽日光。名光中之陰曰影。別製一字。異義異音。斯爲過矣。爾雅、毛詩皆曰。景、大也。其引伸之義也。"}]},"晧":{"expl":"日出皃。从日告聲。","rad":"日","fq":"胡老切","vol":"07","py":"hào","duan":[{"e":"日出皃。","n":"謂光明之皃也。天下惟絜白者冣光明。故引伸爲凡白之偁。又改其字从白作皓矣。"}]},"暤":{"expl":"晧旰也。从日臯聲。","rad":"日","fq":"胡老切","vol":"07","py":"hào","duan":[{"e":"晧旰也。","n":"晧鍇本作暤。集韵、類篇从之。晧旰謂絜白光明之皃。旰同日出光倝倝之倝。非下文訓晚之旰也。漢書上林賦。采色澔旰。史記作澔旰。靈光殿賦。㵆㵆涆涆。曹植七啟云。丹旗燿野。戈殳晧旰。此可證晧旰之爲古語。古者大暤、少暤葢皆以德之明得偁。俗作大昊、少昊。晧旰雙聲字。"}]},"𣋌":{"expl":"光也。从日从𠌶。","rad":"日","fq":"筠輒切","vol":"07","py":"yè","duan":[{"e":"灮也。","n":"也當作皃。字之誤。思玄賦舊注云。曄、光皃。漢書敘傳云。世宗曄曄。吳都賦云。飾赤烏之韡曄。"}]},"暉":{"expl":"光也。从日軍聲。","rad":"日","fq":"許歸切","vol":"07","py":"huī","duan":[{"e":"灮也。","n":"按光也二字當作日光氣也四字。篆體暉當作暈。周禮暈作煇。古文叚借字。眡𥛆掌十煇之法。以觀妖祥。辨吉凶。一曰𥛆。二曰象。三曰鑴。四曰監。五曰闇。六曰瞢。七曰彌。八曰敘。九曰隮。十曰想。鄭司農云。煇謂日光炁也。按日光氣謂日光捲結之氣。釋名曰。暈、捲也。氣在外捲結之也。日月皆然。孟康曰。暈、日旁氣也。篆體日在上。或移之在旁。此篆遂改爲暉。改其訓曰光。與火部之煇不別。葢淺者爲之。乃致鉉以暈爲新附篆矣。"}]},"旰":{"expl":"晚也。从日干聲。《春秋傳》曰：“日旰君勞。”","rad":"日","fq":"古案切","vol":"07","py":"ɡàn","duan":[{"e":"晚也。","n":"襄十四年左傳杜注曰。旰、晏也。"}]},"暆":{"expl":"日行暆暆也。从日施聲。樂浪有東暆縣。讀若酏。","rad":"日","fq":"弋支切","vol":"07","py":"yí","duan":[{"e":"日行暆暆也。","n":"史記屈原賈生列傳曰。庚子日施兮。服集予舍。施卽說文暆字也。暆暆、迤邐徐行之意。暆暆猶施施。詩毛傳曰。施施、難進之意。"}]},"晷":{"expl":"日景也。从日咎聲。","rad":"日","fq":"居洧切","vol":"07","py":"ɡuǐ","duan":[{"e":"日景也。","n":"上文云景、光也。渾言之。此云晷、日景也。不云日光。析言之也。以其陰別於陽。卽今之影字也。左傳謂之蔭。云趙孟視蔭。釋名曰。晷、規也。如規畫也。此謂以表度日。大雅。旣景乃罔。傳云。考於日景。參之高罔。"}]},"礿":{"expl":"夏祭也。从示勺聲。","rad":"示","fq":"以灼切","vol":"01","py":"yuè","duan":[{"e":"夏祭也。","n":"周禮。以禴夏享先王。公羊傳曰。夏曰礿。注。始熟可汋。故曰礿。釋天曰。春祭曰祠。夏祭曰礿。秋祭曰嘗。冬祭曰蒸。孫炎曰。祠之言食。礿、新菜可汋。嘗、嘗新穀。蒸、進品物也。汋與礿曡韵。汋卽說文𩱲字。王制。春曰礿。夏曰禘。與周禮異。"}]},"蒹":{"expl":"雚之未秀者。从艸兼聲。","rad":"艸","fq":"古恬切","vol":"01","py":"jiān","duan":[{"e":"？之未秀者。","n":"蒙上茅秀而及？之秀與未秀也。凡經言？葦、言蒹葭、言葭菼皆竝舉二物。蒹、菼、？一也。今人所謂荻也。葭、葦一也。今人所謂蘆也。？一名薍、一名鵻、一名蒹。葦一名華。釋艸曰。葭華、蒹薕。每二字爲一物。又曰。葭藘、菼薍。亦每二字爲一物。葭蘆卽葭華也。菼薍卽蒹薕也。夏小正傳、毛公、許君說皆同此。舍人、李巡、樊光則云蘆薍爲一艸。陸璣、郭樸則又蒹葭菼爲三矣。夏小正七月秀？葦傳曰。未秀則不爲？葦。秀然後爲？葦。又曰。？未秀爲菼。葦未秀爲蘆。按已秀曰？。未秀則曰蒹、曰薍、曰菼也。於此不列？篆者。以小篆大篆隔之也。"}]},"昃":{"expl":"日在西方時。側也。从日仄聲。《易》曰：“日𣅛之離。”","rad":"日","fq":"阻力切","vol":"07","py":"zè","duan":[{"e":"日在西方時側也。","n":"蒙上日景言之。日在西方則景側也。易曰。日中則昃。孟氏易作稷。穀梁春秋經。戊午日下稷。古文叚借字。"}]},"晚":{"expl":"莫也。从日免聲。","rad":"日","fq":"無遠切","vol":"07","py":"wǎn","duan":[{"e":"𦱤也。","n":"莫者、日且冥也。从日在茻中。見茻部。引伸爲凡後之偁。"}]},"昏":{"expl":"日冥也。从日氐省。氐者，下也。一曰民聲。","rad":"日","fq":"呼昆切","vol":"07","py":"hūn","duan":[{"e":"日冥也。","n":"冥者、窈也。窈者、深遠也。鄭目錄云。士娶妻之禮。以昏爲期。因以名焉。必以昏者、陽往而陰來。日入三商爲昏。引伸爲凡闇之偁。"}]},"曫":{"expl":"日旦昏時。从日䜌聲。讀若新城䜌中。","rad":"日","fq":"洛官切","vol":"07","py":"luán","duan":[{"e":"日且昏時也。","n":"且各本作旦。今正。昏訓冥。莫訓曰且冥。則曫卽𦱤也。曫之言蠻也。蠻者、文皃。日將入而色。有異也。"}]},"晻":{"expl":"不明也。从日奄聲。","rad":"日","fq":"烏感切","vol":"07","py":"àn","duan":[{"e":"不朙也。","n":"北征賦。日晻晻其將暮。漢書元帝紀。三光晻昧。南都賦。晻曖蓊蔚。吳都賦。旭曰晻㫲。凡言晻藹、謂陰翳也。蜀都賦作菴藹。"}]},"暗":{"expl":"日無光也。从日音聲。","rad":"日","fq":"烏紺切","vol":"07","py":"àn","duan":[{"e":"日無光也。","n":"集韵、類篇皆以晻暗爲一字。依許則義各殊。明之反當用晻。暗主謂日無光。眡𥛆掌十煇之灋。五曰闇。鄭司農云。闇、日月食也。暗者正字。闇者叚借字也。引伸爲凡深沈不明之偁。"}]},"晦":{"expl":"月盡也。从日每聲。","rad":"日","fq":"荒內切","vol":"07","py":"huì","duan":[{"e":"月盡也。","n":"朔者、月一日始蘇。朢者、月滿與日相朢似朝君。字皆从月。月盡之字獨从日者、明月盡而日如故也。日如故則月盡而不盡也。引伸爲凡光盡之偁。僖十五年春秋經。晦。震夷伯之廟。公羊曰。晦、晝冥也。穀梁曰。晦、冥也。杜注左云。與凡書晦同。爾雅曰。霿謂之晦。"}]},"𣉘":{"expl":"埃𣉘，日無光也。从日能聲。","rad":"日","fq":"奴代切","vol":"07","py":"nài","duan":[{"e":"埃𣉘、","n":"逗。疊韵字。"}]},"曀":{"expl":"陰而風也。从日壹聲。《詩》曰：“終風且曀。”","rad":"日","fq":"於計切","vol":"07","py":"yì","duan":[{"e":"天陰沈也。","n":"各本作陰而風也。今正。攷開元占經引作天地陰沈也。大平御覽引作天陰沈也。邶風曰。終風且曀。爾雅、毛傳皆云。陰而風曰曀。釋名。曀、翳也。言雲氣晻翳日光使不明也。小爾雅。曀、冥也。曀主謂不明。爾雅、毛傳因詩句兼風言耳。故許易之。陰沈當作𩃬霃。"}]},"旱":{"expl":"不雨也。从日干聲。","rad":"日","fq":"乎旰切","vol":"07","py":"hàn","duan":[{"e":"不雨也。从日。干聲。","n":"乎旰切。十四部。"}]},"薍":{"expl":"𦵹也。从艸亂聲。八月薍爲葦也。","rad":"艸","fq":"五患切","vol":"01","py":"wàn","duan":[{"e":"𦵹也。从艸。亂聲。","n":"五患切。十四部。"}]},"㫐":{"expl":"望遠合也。从日、匕。匕，合也。讀若窈窕之窈。","rad":"日","fq":"烏皎切","vol":"07","py":"yǎo","duan":[{"e":"望遠合也。","n":"合者、朢遠則其形不分、其色不分、其小大高下不分是也。與杳字義略相近。"}]},"昴":{"expl":"白虎宿星。从日卯聲。","rad":"日","fq":"莫飽切","vol":"07","py":"mǎo","duan":[{"e":"白虎宿星。","n":"召南傳曰。昴、畱也。古謂之昴。漢人謂之畱。故天官書言昴。律書直言畱。毛以漢人語釋古語也。元命包云。昴六星。昴之言畱。物成就繫畱。此昴亦𧦝畱之義也。"}]},"曏":{"expl":"不久也。从日鄉聲。《春秋傳》曰：“曏役之三月。”","rad":"日","fq":"許兩切","vol":"07","py":"xiànɡ","duan":[{"e":"不久也。","n":"士相見禮曰。曏者吾子辱使某見。請還贄於將命者。注云。曏、曩也。按禮注曏字或作鄉。今人語曰向年、向時。向者卽曏字也。又曰一晌、曰半晌皆是曏字之俗。"}]},"曩":{"expl":"曏也。从日襄聲。","rad":"日","fq":"奴朗切","vol":"07","py":"nǎnɡ","duan":[{"e":"曏也。","n":"釋言文。左傳曰。曩者志入而已。今則怯也。晉語曰。曩而言戲乎。莊子曰。曩子行。今子止。"}]},"昨":{"expl":"壘日也。从日乍聲。","rad":"日","fq":"在各切","vol":"07","py":"zuó","duan":[{"e":"絫日也。","n":"絫鉉本作疊。誤。鍇本作累。絫累正俗字。古書積累字皆作絫。厽部云。絫者、增也。絫日謂重絫其日也。廣韵云。昨日、隔一宵也。周禮司尊彜叚昨爲酬酢字。"}]},"暇":{"expl":"閑也。从日叚聲。","rad":"日","fq":"胡嫁切","vol":"07","py":"xiá","duan":[{"e":"閒也。","n":"各本作閑。俗字也。今正。酒誥曰。不敢自暇自逸。古多借假爲暇。周書多方。天惟須夏之子孫。鄭云。夏之言假。大雅皇矣。周頌武二箋皆作須假。而孔本作暇。孫卿子。其爲人也多假日。其出人不遠也。賈逵國語注。假、閒也。登樓賦。𦕼假日以銷憂。李善云。假或爲暇。引楚辭𦕼暇日以消時。可見古假暇通用。假訓大。故包閒暇之義。匡謬正俗似未識此意。"}]},"暫":{"expl":"不久也。从日斬聲。","rad":"日","fq":"藏濫切","vol":"07","py":"zàn","duan":[{"e":"不久也。","n":"左傳。婦人暫而免諸國。今俗語云霎時閒、卽此字也。"}]},"昪":{"expl":"喜樂皃。从日弁聲。","rad":"日","fq":"皮變切","vol":"07","py":"biàn","duan":[{"e":"喜樂皃。","n":"小雅。弁彼鸒斯。傳曰。弁、樂也。此昪之假借也。釋詁、詩序皆云。般、樂也。般亦昪之假借也。古三字同音盤。故相叚借如此。昪其正字而尠用之者。"}]},"昌":{"expl":"美言也。从日从曰。一曰日光也。《詩》曰：“東方昌矣。”","rad":"日","fq":"尺良切","vol":"07","py":"chānɡ","duan":[{"e":"美言也。","n":"咎繇謨曰。禹拜昌言。今文尙書作黨。趙注孟子引尙書。禹拜黨言。逸周書祭公解。拜手稽首黨言。張平子碑。黨言允諧。劉寬碑。對策嘉黨。皆昌言字之叚借也。至於讜言。亦見漢人文字。字林。讜言、美言也。此又因黨言而爲之言傍。謂之正俗字可。"}]},"暀":{"expl":"光美也。从日往聲。","rad":"日","fq":"于放切","vol":"07","py":"wànɡ","duan":[{"e":"光美也。","n":"釋詁。曰暀暀、皇皇、美也。按暀見爾雅而不見他經。泮水箋云。皇皇當作暀暀。暀暀猶往往也。此易皇爲暀。復訓暀爲往。以作暀而後可訓往也。少儀。祭祀之儀。齋齋皇皇。注云。皇皇讀爲歸往之往。皇氏云。謂心所繫往。此處鄭不讀爲暀。徐先民於況反。非是。"}]},"𦵹":{"expl":"雚之初生。一曰薍。一曰鵻。从艸剡聲。","rad":"艸","fq":"土敢切","vol":"01","py":"tǎn","duan":[{"e":"？之之初生。一曰薍。一曰騅。","n":"騅各本作鵻。今依爾雅。兩一曰、謂𦵹之一名也。釋言云。菼、騅也。菼、薍也王風傳云。菼鵻也。蘆之初生者也。箋云。菼、薍也。按毛釋爲鵻。恐其與蓷無別也。故又申之曰。蘆之初生者也。菼別於蘆。析言之也。統言之則菼亦偁蘆。鄭恐？葦無別也。故又申之曰薍也。𦵹與騅皆言其靑色。薍言其形。細莖稹密。許云？之初生。亦以正毛也。"}]},"昄":{"expl":"大也。从日反聲。","rad":"日","fq":"補綰切","vol":"07","py":"bǎn","duan":[{"e":"大也。","n":"大雅。土宇昄章。釋詁、毛傳皆曰。昄、大也。"}]},"昱":{"expl":"明日也。从日立聲。","rad":"日","fq":"余六切","vol":"07","py":"yù","duan":[{"e":"日朙也。","n":"日明各本作明日。今依衆經音義及玉篇訂。大玄曰。日以昱乎畫。月以昱乎夜。注云。昱、明也。日無日不明。故自今日言下一日謂之明日。亦謂之昱日。昱之字古多叚借翌字爲之。釋言曰。翌、明也是也。凡經傳子史翌日字皆昱日之叚借。翌與昱同立聲。故相叚借。本皆在緝韵。音轉又皆入屋韵。劉昌宗讀周禮翌日乙丑音育是也。俗人以翌與翼形相似。謂翌卽翼。同入職韵。唐衞包改尙書六翌皆爲翼。而昱日之義廢矣。明部朚下曰。翌也。翌當爲昱。朚从亡明。畫夜之道亡明而明復矣。昱之義引伸爲凡明之偁。故顧命翌室。某氏曰明室。三補決錄注釋左馮翊曰。馮、盛也。翊、明也。翊卽翌。"}]},"㫱":{"expl":"溫溼也。从日，赧省聲。讀與赧同。","rad":"日","fq":"女版切","vol":"07","py":"nǎn","duan":[{"e":"𥁕溼也。","n":"𥁕各本作溫。今正。說詳水部。溫而生溼。故其字从日。"}]},"暍":{"expl":"傷暑也。从日曷聲。","rad":"日","fq":"於歇切","vol":"07","py":"yē","duan":[{"e":"傷暑也。","n":"北山經。北嚻之山。鳥名𪄀𪃑。食之已暍。按今俗語謂𩰪蒸之曰暍。聲如遏。卽此字。"}]},"暑":{"expl":"熱也。从日者聲。","rad":"日","fq":"舒呂切","vol":"07","py":"shǔ","duan":[{"e":"𤍽也。","n":"暑與熱渾言則一。故許以熱訓暑。析言則二。故大雅。溫隆蟲蟲。毛云。溫溫而暑。隆隆而雷。蟲蟲而熱也。暑之義主謂溼。熱之義主謂燥。故溽暑謂溼暑也。釋名曰。暑、煑也。如水煑物也。熱、爇也。如火所燒爇也。"}]},"㬮":{"expl":"安㬮，温也。从日難聲。","rad":"日","fq":"奴案切","vol":"07","py":"nàn","duan":[{"e":"安㬮、","n":"逗。疊韵字也。"}]},"㬎":{"expl":"衆微杪也。从日中視絲。古文以爲顯字。或曰衆口皃。讀若唫唫。或以爲繭；繭者，絮中往往有小繭也。","rad":"日","fq":"五合切","vol":"07","py":"xiǎn","duan":[{"e":"衆微杪也。从日中視絲。","n":"此九字廣韵作衆明也、微妙也、从日中視絲十一字。疑當作衆明也、从日中見絲、絲𢼸眇也。𢼸者今之微字。眇者今之妙字。玉篇亦作妙。日中視絲。衆明察及微妙之意。"}]},"㬥":{"expl":"晞也。从日从出，从𠬞从米。","rad":"日","fq":"薄報切","vol":"07","py":"pù","duan":[{"e":"晞也。","n":"攷工記。晝㬥諸日。孟子。一日㬥之。引伸爲表㬥、㬥露之義。與𠦍部𣋦義別。凡𣋦疾、𣋦虐、𣋦虎皆𠦍部字也。而今隷一之。經典皆作暴。難於諟正。"}]},"曬":{"expl":"㬥也。从日麗聲。","rad":"日","fq":"所智切","vol":"07","py":"shài","duan":[{"e":"㬥也。","n":"漢中山靖王傳。白日曬光。幽隠皆照。"}]},"暵":{"expl":"乾也。耕㬥田曰暵。从日堇聲。《易》曰：“燥萬物者莫暵于離。”","rad":"日","fq":"呼旰切","vol":"07","py":"hàn","duan":[{"e":"乾也。","n":"乾上當有日字。乾者、上出也。凡物乾者必上。溼者必下。王風傳曰。暵菸皃。周禮旱暵之事。鄭云。暵、熱氣也。皆引伸之義也。"}]},"薕":{"expl":"蒹也。从艸廉聲。","rad":"艸","fq":"力鹽切","vol":"01","py":"lián","duan":[{"e":"蒹也。","n":"二字曡韵。"}]},"晞":{"expl":"乾也。从日希聲。","rad":"日","fq":"香衣切","vol":"07","py":"xī","duan":[{"e":"乾也。","n":"玄應書引作日乾曰晞。小雅。湛湛露斯。匪陽不晞。傳曰。陽、日也。晞、乾也。陽日也者、謂陽卽暘之叚借也。方言。膊曬晞㬥也。㬥五穀之類。秦晉之閒謂之曬。東齋北燕海岱之郊謂之晞。又曰。晞、燥也。"}]},"昔":{"expl":"乾肉也。从殘肉，日以晞之。與俎同意。","rad":"日","fq":"思積切","vol":"07","py":"xī","duan":[{"e":"乾肉也。","n":"周禮臘人。掌乾肉。凡田獸之脯腊膴胖之事。鄭云。大物解肆乾之謂之乾肉。若今涼州烏翅矣。腊、小物全乾者。鄭意大曰乾肉。小曰啦。然官名腊人。則大物亦偁臘也。故許渾言之。"}]},"暱":{"expl":"日近也。从日匿聲。《春秋傳》曰：“私降暱燕。”","rad":"日","fq":"尼質切","vol":"07","py":"nì","duan":[{"e":"日近也。","n":"日謂日日也。皆日之引伸之義也。釋詁、小雅傳皆云。暱、近也。左傳。不義不暱。非其私暱。誰敢任之。"}]},"𣊓":{"expl":"日狎習相慢也。从日執聲。","rad":"日","fq":"私列切","vol":"07","py":"xiè","duan":[{"e":"日狎習相嫚也。","n":"嫚者、侮易也。小雅。曾我暬御。傳云。暬御、侍御也。楚語。居寢有暬御之箴。韋云。暬、近也。暬與褻音同義異。今則褻行而暬廢矣。"}]},"㫘":{"expl":"不見也。从日，否省聲。","rad":"日","fq":"美畢切","vol":"07","py":"mì","duan":[{"e":"不見也。从日。否省聲。","n":"此字古籍中未見。其訓云不見也。則於从日無涉。其音云否省聲。則與自來相傳密音不合。且何不云不聲也。以理求之。當爲不日也。从不日。王風曰。不日不月。謂不知其旋反之何日何月。卽上章之不知其期也。大雅。不日成之。箋云。不設期日。今俗謂不遠而不定何日亦曰不日。卽形卽義許書有此例。如止戈爲武、日見爲晛是也。其音美畢切者、葢謂遠不可期則讀如蔑。近不可期則讀如密也。自讀許書者不解。而妄改其字。或改作㸓。廣韵改作𥄃。意欲與𧠨之俗字作覓者比附爲一。十一部。"}]},"昆":{"expl":"同也。从日从比。","rad":"日","fq":"古渾切","vol":"07","py":"kūn","duan":[{"e":"同也。","n":"夏小正。昆小蟲。傳曰。昆者、衆也。由䰟（由同猶）䰟也者、動也。小蟲動也。王制。昆蟲未蟄。鄭曰。昆、明也。明蟲者得陽而生。得陰而藏。以上數說兼之而義乃備。惟明斯動。動斯衆。衆斯同。同而或先或後。是以昆義或爲先。如昆弟是也。或爲後。如昆命元龜、釋言昆後也是也。羽獵賦。噍噍昆鳴。"}]},"晐":{"expl":"兼晐也。从日亥聲。","rad":"日","fq":"古哀切","vol":"07","py":"ɡāi","duan":[{"e":"兼晐也。","n":"吳語。一介嫡女。執箕帚以晐姓於王宫。韋云。晐、僃也。姓、庶姓。引曲禮納女於天子曰僃百姓。廣雅。晐、皆咸也。按此晐僃正字。今字則該賅行而晐廢矣。莊子、淮南作賅。今多作該。"}]},"普":{"expl":"日無色也。从日从並。","rad":"日","fq":"滂古切","vol":"07","py":"pǔ","duan":[{"e":"日無色也。","n":"此義古籍。少用。衣部袢下曰。無色也。讀若暜。㒳無色同讀。是則暜之本義實訓日無色。今字借爲溥大字耳。今詩溥天之下。孟子及漢人引詩皆作普天。趙岐曰。普、徧也。"}]},"曉":{"expl":"明也。从日堯聲。","rad":"日","fq":"呼鳥切","vol":"07","py":"xiǎo","duan":[{"e":"朙也。","n":"此亦謂旦也。俗云天曉是也。引伸爲凡明之偁。方言。黨曉哲知也。楚謂之黨。或曰曉。齊宋之閒謂之哲。"}]},"昕":{"expl":"旦明，日將出也。从日斤聲。讀若希。","rad":"日","fq":"許斤切","vol":"07","py":"xīn","duan":[{"e":"且朙也。","n":"小徐本作旦也。明也。韵會作旦明也。今正爲且明。文王世子。大昕。鄭云。早昧爽也。是昕卽䢅而未旦也。士昏禮記曰。凡行事必用昏昕。齊風。東方未晞。顚倒裳衣。傳曰。晞、明之始升。按蒹葭、湛露傳皆云。晞、乾也。此云明之始升則當作昕無疑。昕與晞各形各義。而昕讀同希。因誤爲晞耳。"}]},"薠":{"expl":"青薠，似莎者。从艸煩聲。","rad":"艸","fq":"附袁切","vol":"01","py":"fán","duan":[{"e":"靑薠。","n":"句。"}]},"曈":{"expl":"曈曨，日欲明也。从日童聲。","rad":"日","fq":"徒紅切","vol":"07","py":"tónɡ","duan":[]},"曨":{"expl":"曈曨也。从日龍聲。","rad":"日","fq":"盧紅切","vol":"07","py":"lónɡ","duan":[]},"昈":{"expl":"明也。从日戶聲。","rad":"日","fq":"矦古切","vol":"07","py":"hù","duan":[]},"昉":{"expl":"明也。从日方聲。","rad":"日","fq":"分兩切","vol":"07","py":"fǎnɡ","duan":[]},"晙":{"expl":"明也。从日夋聲。","rad":"日","fq":"子峻切","vol":"07","py":"jùn","duan":[]},"晟":{"expl":"明也。从日成聲。","rad":"日","fq":"承正切","vol":"07","py":"shènɡ","duan":[]},"昶":{"expl":"日長也。从日、永。會意。","rad":"日","fq":"丑兩切","vol":"07","py":"chǎnɡ","duan":[]},"暈":{"expl":"日月气也。从日軍聲。","rad":"日","fq":"王問切","vol":"07","py":"yùn","duan":[{"e":"灮也。","n":"按光也二字當作日光氣也四字。篆體暉當作暈。周禮暈作煇。古文叚借字。眡？掌十煇之法。以觀妖祥。辨吉凶。一曰？。二曰象。三曰鑴。四曰監。五曰闇。六曰瞢。七曰彌。八曰敘。九曰隮。十曰想。鄭司農云。煇謂日光炁也。按日光氣謂日光捲結之氣。釋名曰。暈、捲也。氣在外捲結之也。日月皆然。孟康曰。暈、日旁氣也。篆體日在上。或移之在旁。此篆遂改爲暉。改其訓曰光。與火部之煇不別。葢淺者爲之。乃致鉉以暈爲新附篆矣。"}]},"晬":{"expl":"周年也。从日、卒，卒亦聲。","rad":"日","fq":"子內切","vol":"07","py":"zuì","duan":[]},"映":{"expl":"明也。隱也。从日央聲。","rad":"日","fq":"於敬切","vol":"07","py":"yìnɡ","duan":[]},"䒢":{"expl":"昌蒲也。从艸卬聲。益州云。","rad":"艸","fq":"五剛切","vol":"01","py":"ánɡ","duan":[{"e":"䒢䓉、","n":"逗。二字各本脫。今依全書通例補之。"}]},"曙":{"expl":"曉也。从日署聲。","rad":"日","fq":"常恕切","vol":"07","py":"shǔ","duan":[]},"昳":{"expl":"日𣅦也。从日失聲。","rad":"日","fq":"徒結切","vol":"07","py":"dié","duan":[]},"曇":{"expl":"雲布也。从日、雲。會意。","rad":"日","fq":"徒含切","vol":"07","py":"tán","duan":[]},"曆":{"expl":"厤象也。从日厤聲。《史記》通用歷。","rad":"日","fq":"郎擊切","vol":"07","py":"lì","duan":[]},"昂":{"expl":"舉也。从日卬聲。","rad":"日","fq":"五岡切","vol":"07","py":"ánɡ","duan":[]},"昇":{"expl":"日上也。从日升聲。古只用升。","rad":"日","fq":"識蒸切","vol":"07","py":"shēnɡ","duan":[]},"旦":{"expl":"明也。从日見一上。一，地也。凡旦之屬皆从旦。","rad":"旦","fq":"得案切","vol":"07","py":"dàn","duan":[{"e":"朙也。","n":"明當作朝。下文云。朝者、旦也。二字互訓。大雅板毛傳曰。旦、明也。此旦引伸之義。非其本義。衞風。信誓旦旦。傳曰。信誓旦旦然。謂明明然也。"}]},"暨":{"expl":"日頗見也。从旦旣聲。","rad":"旦","fq":"其異切","vol":"07","py":"jì","duan":[{"e":"日頗見也。","n":"頗、頭偏也。頭偏則不能全其面。故謂事之略然者曰頗。日頗見者、見而不全也。釋訓曰。暨、不及也。此其引伸之義。乑部曰。臮者、衆與詞也。引唐書臮咎繇。臮之叚借多作洎、作暨。公羊傳曰。會及暨、皆與也。暨猶暨暨也。按暨暨猶幾幾。爾雅所謂不及也。"}]},"倝":{"expl":"日始出，光倝倝也。从旦㫃聲。凡倝之屬皆从倝。","rad":"倝","fq":"古案切","vol":"07","py":"ɡàn","duan":[{"e":"日始出。","n":"始式吏切。"}]},"𠐱":{"expl":"闕。","rad":"倝","fq":"","vol":"07","py":"ɡàn","duan":[{"e":"闕且。从三日在㫃中。","n":"按此葢倝籒文也。汗𥳑朝作{(大(日日)日丂[上下])+(入月[上下])[左右]}。翰作{(大(日日)日丂[上下])+(入毛[上下])[左右]}。亦可證矣。闕且二字當作籒文二字。从三日在㫃中。則篆體{(日日)+日[上下]}下不當有一也。"}]},"䓉":{"expl":"䒢䓉也。从艸邪聲。","rad":"艸","fq":"以遮切","vol":"01","py":"yé","duan":[{"e":"䒢䓉也。从艸。邪聲。","n":"以遮切。古音在五部。"}]},"𦩻":{"expl":"旦也。从倝舟聲。","rad":"倝","fq":"陟遙切","vol":"07","py":"zhāo","duan":[{"e":"旦也。","n":"旦者、朝也。以形聲會意分別。庸風。崇朝其雨。傳云。崇、終也。從至食時爲終朝。此謂至食時乃終其朝。其實朝之義主謂日出地時也。周禮。春見曰朝。注曰。朝猶朝也。欲其來之早。毛詩叚輖爲朝。周南。惄如輖飢。傳云。輖、朝也。此謂叚借也。"}]},"㫃":{"expl":"旌旗之游，㫃蹇之皃。从屮，曲而下，垂㫃相出入也。讀若偃。古人名㫃，字子游。凡㫃人之屬皆从㫃。","rad":"㫃","fq":"於幰切","vol":"07","py":"yǎn","duan":[{"e":"旌旗之游㫃蹇之皃。","n":"旌旗者、旗之通偁。旌有羽者。其未有羽者。各舉其一該九旗也。王逸九歌注云。偃蹇、舞皃。大人賦說旌旗曰。掉拮撟以偃蹇。張揖曰。偃蹇、高皃。"}]},"旐":{"expl":"龜蛇四游，以象營室，游游而長。从㫃兆聲。《周禮》曰：“縣鄙建旐。”","rad":"㫃","fq":"治小切","vol":"07","py":"zhào","duan":[{"e":"龜蛇四游。㠯象營室。","n":"攷工記文也。司常掌九旗之物名。龜蛇爲旐。鄭云。畫龜蛇者象其扞難避害也。爾雅曰。緇廣充幅長尋曰旐。是則九旗之帛皆用絳。惟旐用緇。攷工記注曰。營室、玄武宿。與東辟連體而四星。故旐四游。營室一名水。左傳云。水昏正而栽是。一名定。詩定之方中是也。"}]},"旗":{"expl":"熊旗五游，以象罰星，士卒以爲期。从㫃其聲。《周禮》曰：“率都建旗。”","rad":"㫃","fq":"渠之切","vol":"07","py":"qí","duan":[{"e":"熊旗五游。㠯象伐星。","n":"五鄭本攷工記作六。熊旗六游。以象代也。司常職曰。熊虎爲旗。注曰。畫熊虎者。鄉遂出軍賦。象其守猛莫敢犯也。伐屬白虎宿。與參連體而六星。按記不言虎者。舉熊以包虎。"}]},"旆":{"expl":"繼旐之旗也，沛然而垂。从㫃𣎵聲。","rad":"㫃","fq":"蒲蓋切","vol":"07","py":"pèi","duan":[{"e":"繼旐之旗也。","n":"旗者、旌旗之總名。下文云旗有衆鈐、旗曲柄、旗旖施皆是。爾雅。繼旐曰旆。郭云。帛續旐末爲燕尾者。何休注公羊云。繼旐如燕尾曰旆。釋名云。旆、以帛繼旐末也。小雅。帛旆央央。毛曰。帛旆、經旐者也。按帛葢用絳。"}]},"旌":{"expl":"游車載旌，析羽注旄首，所以精進士卒。从㫃生聲。","rad":"㫃","fq":"子盈切","vol":"07","py":"jīnɡ","duan":[{"e":"遊車載旌。","n":"司常職文。注云。遊車木路也。王以田以鄙。"}]},"旟":{"expl":"錯革畫鳥其上，所以進士衆。旟旟，衆也。从㫃與聲。《周禮》曰：“州里建旟。”","rad":"㫃","fq":"以諸切","vol":"07","py":"yú","duan":[{"e":"錯革鳥其上。","n":"鳥上各本有畫字。妄人所增。攷韵會所據小徐本無此字。今𠜂。司常職曰。鳥隼爲旟。爾雅曰。錯革鳥曰旟。小雅毛傳曰。鳥章、錯革鳥爲章也。李巡云。錯革鳥者、以革爲之。置於旐端。孫炎云。錯、置也。革、急也。言畫急疾之鳥於縿。周官所謂鳥隼爲旟者矣。郭云。此謂合剝鳥皮毛置之竿頭。卽禮記云載鴻及鳴鳶。三人釋革各不同。許仍爾雅原文。許意大約於孫說無異。鄭注周禮云。畫日月。畫交龍。畫熊虎鳥隼龜蛇。是則鄭之說錯革鳥。謂畫鳥隼。孫說所本也。許云其上者、謂畫於正幅高處。"}]},"旂":{"expl":"旗有衆鈴，以令衆也。从㫃斤聲。","rad":"㫃","fq":"渠希切","vol":"07","py":"qí","duan":[{"e":"旗有衆鈐。","n":"爾雅曰。有鈐曰旂。司常職曰。交龍爲旂。許偁爾雅不偁周禮者、錯見其說。欲學者互攷也。畫交龍於正幅。一升一降。象諸侯升朝下復也。周頌曰。龍旂陽陽。和鈐央央。傳云。鈐在旂上。李巡云。以鈐著旐端。郭樸云。縣鈐於竿頭。按李說近是。惟羽旄注竿首。鈐非注竿首之物也。左傳。錫鸞和鈐。昭其聲也。杜云。鈐在旂。李云。以鈐著旐端。公羊疏、左傳疏同。周頌疏旐作旒。誤。云旐者、旐亦旗正幅之通偁。"}]},"旞":{"expl":"導車所以載。全羽以爲允。允，進也。从㫃遂聲。","rad":"㫃","fq":"徐醉切","vol":"07","py":"suì","duan":[{"e":"導車所載。","n":"各本作所以載。今依御覽訂。司常職曰。道畫載旞。斿車載旌。注云。道車、象路也。王以朝夕燕出入。按道導字異。許、鄭所據不同。金氏榜曰。九旗。王建大常。諸侯建旂。孤𨜮建旜。大夫士建物。師都建旗。州里建旟。縣鄙建旐。此七旗葢無羽。賓祭之所用也。其曰旞、曰旌。則以有羽爲異。道車謂象路。斿車謂革路、木路。變路言車。關孤𨜮、大夫士也。旞、旌皆張縿幅屬旒焉。畫於縿如日月以下。旜與物不畫。夏采。以乘車建𧞸復於四郊。𧞸當爲旞。說文旞亦作𣄧。因譌而爲𧞸。復者、求之平生常所有事之處。故以道車朝夕燕出入者建旞以復。襍記。諸侯列於道。以其綏復。又曰。大夫士死於道。以其綏復。綏皆旞之譌。言其旞者、明異物。天子以大常。諸侯以"}]},"旝":{"expl":"建大木，置石其上，發以機，以追敵也。从㫃會聲。《春秋傳》曰：“旝動而鼓。”《詩》曰：“其旝如林。”","rad":"㫃","fq":"古外切","vol":"07","py":"kuài","duan":[{"e":"旌旗也。","n":"旌旗有名旝者。下文所偁詩及左傳皆是也。"}]},"芀":{"expl":"葦華也。从艸刀聲。","rad":"艸","fq":"徒聊切","vol":"01","py":"tiáo","duan":[{"e":"葦華也。","n":"釋艸曰。葦、醜芀。顏注漢書云蒹錐者是也。取其脫穎秀出故曰芀。方言。錐謂之鍣。音苕因此凡言芀秀者、多借苕字爲之。韓詩葦䓟字作䓟。釋艸。蔈荂荼猋藨芀。皆謂艸之秀。豳風傳曰。荼、？苕也。夏小正傳曰。荼、？葦之秀。是與茅秀同名荼矣。葦華大於？華。故葭一名華。"}]},"旃":{"expl":"旗曲柄也。所以旃表士衆。从㫃丹聲。《周禮》曰：“通帛爲旃。”","rad":"㫃","fq":"諸延切","vol":"07","py":"zhān","duan":[{"e":"旗典柄也。","n":"漢田蚡傳曰。前堂羅鐘𡔷。列曲旃。蘇林云。禮、大夫立曲旃。曲旃、柄上曲也。按蘇林所據禮正與周禮司常孤𨜮建旜、大司馬帥都載旜合。帥都、遂大夫也。左傳曰。昔我先君之田也。旃以招大夫。正謂大夫用旃也。庸風傳曰。干旄、大夫之旃。子虛賦。靡魚須之橈旃。張揖曰。以魚須爲柄。師古曰。橈旃卽曲旃也。"}]},"㫍":{"expl":"旌旗之流也。从㫃攸聲。","rad":"㫃","fq":"以周切","vol":"07","py":"yóu","duan":[{"e":"旌旗之流也。","n":"宋刊本皆作流。作旒者俗。"}]},"㫏":{"expl":"旗屬。从㫃要聲。","rad":"㫃","fq":"烏皎切","vol":"07","py":"yǎo","duan":[{"e":"旗屬。从㫃。要聲。","n":"烏皎切。二部。"}]},"施":{"expl":"旗皃。从㫃也聲。亝欒施字子旗，知施者旗也。","rad":"㫃","fq":"式支切","vol":"07","py":"shī","duan":[{"e":"旗旖施也。","n":"大人賦說旌旗曰。又旖旎以招搖。施字俗改爲旎。从尼聲。殊失音理。"}]},"旖":{"expl":"旗旖施也。从㫃奇聲。","rad":"㫃","fq":"於离切","vol":"07","py":"yǐ","duan":[{"e":"旖施、","n":"逗。"}]},"旚":{"expl":"旌旗旚繇也。从㫃票聲。","rad":"㫃","fq":"匹招切","vol":"07","py":"piāo","duan":[{"e":"旌旗旚繇也。","n":"繇今之搖字。小徐作搖。旚今字作飄。飄搖行而旚繇廢矣。廣成頌曰。羽旄紛其髟鼬。髟鼬卽旚搖之叚借字也。"}]},"𣄠":{"expl":"旌旗飛揚皃。从㫃猋聲。","rad":"㫃","fq":"甫遙切","vol":"07","py":"biāo","duan":[{"e":"旌旗飛揚皃.","n":"扶搖風曰飈。義略相近。"}]},"游":{"expl":"旌旗之流也。从㫃汓聲。","rad":"㫃","fq":"以周切","vol":"07","py":"yóu","duan":[{"e":"旌旗之流也。","n":"流宋刊本皆同。集韵、類篇乃作旒。俗字耳。旗之游如水之流。故得偁流也。大常十有二游。旂九游。旟七游。旗六游。旐四游。周禮。王建大常。十有二游。上公建旂。九游。侯伯七游。子男五游。孤卿建旜。大夫士建物。其游各視其命之數。禮緯含文嘉云。天子之旗九仞十二旒曳地。諸侯七仞九旒齊軫。卿大夫五仞七旒齊較。士三仞五旒齊首。皆不言其命數。未可信。旗之正幅爲縿。游則屬焉。節服氏。六人維王之大常。注。王旌十二旒。㒳㒳以縷綴連。旁三人持之。然則旗之制。游屬於㒳旁。十二游者、一旁六游。九游、則㒳旁一四一五。已下可知也。曳地、齊軫皆謂游。其正幅之長。爾雅曰。旐長尋。餘未聞。游亦曰旓。楊雄賦有此字。大人賦作髾游。周禮省作斿"}]},"旇":{"expl":"旌旗披靡也。从㫃皮聲。","rad":"㫃","fq":"敷羈切","vol":"07","py":"pī","duan":[{"e":"旌旗披靡也。","n":"披靡當是𢫾𪎮之誤。淺人所改也。爾雅曰。旄謂之藣。集韵、類篇皆作麾謂之旇。爾雅藣字卽許之旇字。大人賦張揖注云。𢫾橋、隨風指𪎮也。今𪎮誤靡。"}]},"旋":{"expl":"周旋，旌旗之指麾也。从㫃从疋。疋，足也。","rad":"㫃","fq":"似沿切","vol":"07","py":"xuán","duan":[{"e":"周旋、","n":"逗。"}]},"茢":{"expl":"芀也。从艸𠛱聲。","rad":"艸","fq":"良辥切","vol":"01","py":"liè","duan":[{"e":"芀也。","n":"檀弓。君臨臣喪。以巫祝桃茢執戈。注。茢、？苕。可埽不祥。玉藻。膳於君有葷桃茢。注。茢、菼帚也。按許云葦。鄭云？菼者。此統言不別也。芀帚、花退用穎爲之。芀一名茢。故帚一名茢。"}]},"旄":{"expl":"幢也。从㫃从毛，毛亦聲。","rad":"㫃","fq":"莫袍切","vol":"07","py":"máo","duan":[{"e":"幢也。","n":"劉熙曰。幢、童也。其皃童童也。廣雅曰。幢謂之𦒛。爾雅曰。翢、𦇨也。毛傳曰。翿者、𦇨也。翳也。羽部曰。𦒇者、翳也。所以舞也。人部曰。儔者、翳也。按或用羽。或用氂牛尾。或兼用二者。翢儔翿實一字。𦇨俗作纛。亦卽𦒇字。爾雅、毛傳皆以今字釋古字耳。幢亦卽𦒇字。古𢏚聲、周聲與童聲轉移。如詩以調韵同、漢縣鮦陽讀如紂之比。其始衹有𦒇字。繼乃有𦇨。繼乃有幢。皆後出。故許書不列𦇨幢二篆。此釋旄必云幢、不云𦒇者。𦒇嫌舞者所持。旄是旌旗之名。漢之羽葆幢。以氂牛尾爲之。如斗。在乘輿左騑馬頭上。用此知古以犛牛尾注竿首。如斗童童然。故詩言干旄、言建旄、言設旄。有旄則亦有羽。羽或全或析。言旄不言羽者舉一以晐。二其字从㫃从毛。"}]},"旛":{"expl":"幅胡也。从㫃番聲。","rad":"㫃","fq":"孚袁切","vol":"07","py":"fān","duan":[{"e":"旛胡也。","n":"各本作幅胡也。今依葉石林抄宋本及韵會所據本訂。韵會作幡胡。幡卽旛之俗。序例。所以書幡信。字亦从俗。叚巾部之幡爲旛而旛廢矣。旛胡葢古語。如㼾磚之名㽃瓳。見廣雅。漢堯廟碑作墦𡎁。玉曰璠璵。艸木盛曰緐廡。皆雙聲字。凡旗正幅謂之縿亦謂之旛胡。廣韵云。旛者、旗旐總名。古通謂凡旗正幅曰旐。是則凡旗幅皆曰旛胡也。吳語。建肥胡。韋注。肥胡、幡也。幡卽旛字。與許互相發明。旛胡卽肥胡。謂大也。吳都賦作祀姑誤。"}]},"旅":{"expl":"軍之五百人爲旅。从㫃从从。从，俱也。","rad":"㫃","fq":"力舉切","vol":"07","py":"lǚ","duan":[{"e":"軍之五百人。","n":"大司徒。五人爲伍。五伍爲兩。四兩爲卒。五卒爲旅。五旅爲師。五師爲軍。以起軍旅。注云。此皆先王所因農事而定軍令者也。欲其恩足相恤。義足相救。服容相別。音聲相識。引伸爲凡衆之偁。小雅。旅力方剛。傳云。旅、衆也。又引伸之義爲陳。小雅。殽核維旅。傳云。旅、陳也。又凡言羈旅。義取乎廬。廬、寄也。故大雅廬旅猶處處、言言、語語也。又古叚爲盧弓之盧。俗乃製玈字。"}]},"族":{"expl":"矢鋒也。束之族族也。从㫃从矢。","rad":"㫃","fq":"昨木切","vol":"07","py":"zú","duan":[{"e":"矢鏠也。","n":"今字用鏃。古字用族。金部曰。鏃者、利也。則不以爲矢族字矣。"}]},"冥":{"expl":"幽也。从日从六， 冖聲。日數十。十六日而月始虧幽也。凡冥之屬皆从冥。","rad":"冥","fq":"莫經切","vol":"07","py":"mínɡ","duan":[{"e":"窈也。","n":"窈各本作幽。唐玄應同。而李善思玄賦、歎逝賦陶淵明赴假還江陵詩三注皆作窈。許書多宗爾雅、毛傳。釋言曰。冥、窈也。孫炎云。深闇之窈也。郭本作幼。釋云。幼稚者多冥昧。頗紆洄。小雅斯干傳曰。正、長也。冥、窈也。正謂宫室之寬長深窈處。王肅本作幼。其說以人之長幼對文。與下君子攸寧不相屬。然則三者互相證。知皆當作窈。穴部曰。窈、深遠也。窈與杳音義同。故杳之訓曰冥也。莫之訓曰日且冥也。昏之訓曰日冥也。鄭箋斯干曰。正晝也。冥夜也。引伸爲凡闇昧之偁。"}]},"鼆":{"expl":"冥也。从冥黽聲。讀若黽蛙之黽。","rad":"冥","fq":"武庚切","vol":"07","py":"ménɡ","duan":[{"e":"冥也。从冥。黽聲。讀若黽蛙之黽。","n":"黽蛙卽黽部之鼃黽。武庚切。古音在十部。讀如芒。此字見於經者。文十五年左傳曰。一人門於句鼆。杜云。魯邑名。"}]},"晶":{"expl":"精光也。从三日。凡晶之屬皆从晶。","rad":"晶","fq":"子盈切","vol":"07","py":"jīnɡ","duan":[{"e":"精光也。","n":"凡言物之盛。皆三其文。日可三者。所謂絫日也。"}]},"曐":{"expl":"萬物之精，上爲列星。从晶生聲。一曰象形。从口，古口復注中，故與日同。","rad":"晶","fq":"桑經切","vol":"07","py":"xīnɡ","duan":[{"e":"萬物之精。上爲列星。","n":"管子云。凡物之精。此則爲生。下生五穀。上爲列星。流於天地之閒謂之鬼神。藏於胷中謂之聖人。星之言散也。引伸爲碎散之偁。"}]},"曑":{"expl":"商星也。从晶㐱聲。","rad":"晶","fq":"所今切","vol":"07","py":"shēn","duan":[{"e":"商星也。","n":"商當作晉。許氏記憶之誤也。左傳。子産曰。后帝遷閼伯於商丘。主辰。商人是因。故辰爲商星。遷實沈於大夏。主參。唐人是因。以服事夏商。及成王滅唐而封叔虞。故參爲晉星。依此則商當爲晉明矣。或云此以篆文曑連商句絶。釋爲星也。夫苟氾釋爲星。安用商字。參商之云。起於漢時辭章。聯綴不倫。許君何取。此於曟舉國語農祥釋之。於參舉晉星釋之。一重民事。一重分野也。召南傳曰。參、伐也。漢人參伐統𧦝伐。故毛以伐釋參。"}]},"曟":{"expl":"房星；爲民田時者。从晶辰聲。","rad":"晶","fq":"植鄰切","vol":"07","py":"chén","duan":[{"e":"房星。","n":"爾雅曰。天駟、房也。大辰、房心尾也。於天官爲東官蒼龍。"}]},"䓿":{"expl":"䓿𧂄也。从艸圅聲。","rad":"艸","fq":"胡感切","vol":"01","py":"hàn","duan":[{"e":"䓿𧂄也。从艸。圅聲。","n":"胡感切。八部。"}]},"曡":{"expl":"楊雄說：以爲古理官決罪，三日得其宜乃行之。从晶从宜。亡新以爲曡从三日太盛，改爲三田。","rad":"晶","fq":"徒叶切","vol":"07","py":"dié","duan":[{"e":"楊雄說㠯爲古理官決罪。三日得其宐乃行之。从晶宐。","n":"已上楊雄說也。理官、士也。詩莫不震㬪。韓詩薛君傳曰。震、動也。㬪、應也。天下無不動而應其政敎。李固曰。此言動之於內而應之於外者也。按㬪爲應、卽得其宐乃行之之說也。毛詩傳曰。㬪、慴也。今毛義行而韓義廢矣。抑楊子所說者本義也。故許述之。毛詩之云、謂㬪卽慴之叚借字也。故許不偁。从晶宐會意。徒叶切。八部。"}]},"月":{"expl":"闕也。大陰之精。象形。凡月之屬皆从月。","rad":"月","fq":"魚厥切","vol":"07","py":"yuè","duan":[{"e":"闕也。大侌之精。","n":"月闕㬪韵。釋名曰。月、缺也。滿則缺也。"}]},"朔":{"expl":"月一日始蘇也。从月屰聲。","rad":"月","fq":"所角切","vol":"07","py":"shuò","duan":[{"e":"月一日始蘇也。","n":"朔蘇㬪韵。日部曰。晦者、月盡也。盡而蘇矣。樂記注曰。更息曰蘇。息、止也。生也。止而生矣。引伸爲凡始之偁。北方曰朔方。亦始之義也。朔方始萬物者也。"}]},"朏":{"expl":"月未盛之明。从月、出。《周書》曰：“丙午朏。”","rad":"月","fq":"普乃切","vol":"07","py":"pěi","duan":[{"e":"月未盛之朙也。","n":"律歷志曰。召誥曰。惟三月丙午朏。周公七年復子明辟之嵗三月甲辰朔之三曰也。畢命豐㓝曰。惟十有二年六月庚午朏。王命作策豐㓝。康王十二年六月戊辰朔之三日也。志引古文月采篇曰。三日曰朏。按尙書正義曰。周書月令云。三日粵朏。疑卽取諸漢志。而月采作月令。未知孰是。逸周書月令弟五十三。據牛弘傳。蔡邕、王肅時已亡。孟堅時未亡也。小顔漢書采字當从孔沖遠作令。小顔讀孟注而不察耳。"}]},"霸":{"expl":"月始生，霸然也。承大月，二日；承小月，三日。从月䨣聲。《周書》曰：“哉生霸。”","rad":"月","fq":"普伯切","vol":"07","py":"pò","duan":[{"e":"月始生魄然也。","n":"霸魄㬪韵。"}]},"朗":{"expl":"明也。从月良聲。","rad":"月","fq":"盧黨切","vol":"07","py":"lǎnɡ","duan":[{"e":"朙也。","n":"大雅。高朗令終。傳曰。朗、明也。釋言曰。明、朗也。"}]},"肭":{"expl":"朔而月見東方謂之縮肭。从月内聲。","rad":"月","fq":"女六切","vol":"07","py":"nǜ","duan":[{"e":"朔而月見東方謂之縮朒。","n":"尙書五行傳。朔而月見東方謂之側匿。側匿則侯王其肅。注云。側匿猶縮縮行遲皃。肅急也。君政緩則日行徐。月行疾。臣放恣也。按鄭注譌奪。側匿與縮朒㬪韵雙聲。"}]},"期":{"expl":"會也。从月其聲。","rad":"月","fq":"渠之切","vol":"07","py":"qī","duan":[{"e":"會也。","n":"會者、合也。期者、要約之意。所以爲會合也。叚借爲期年、期月字。其本字作稘。期行而稘廢矣。周禮質人、士虞禮古文期年字作基。"}]},"朦":{"expl":"月朦朧也。从月蒙聲。","rad":"月","fq":"莫工切","vol":"07","py":"ménɡ","duan":[]},"禘":{"expl":"諦祭也。从示帝聲。《周禮》曰：“五歲一禘。”","rad":"示","fq":"特計切","vol":"01","py":"dì","duan":[{"e":"諦祭也。","n":"言部曰。諦者、審也。諦祭者、祭之審諦者也。何言乎審諦。自來說者皆云審諦昭穆也。諦有三。有時諦。有殷禘。有大禘。時禘者。王制春曰礿、夏曰禘、秋曰嘗、冬曰蒸、是也。夏商之禮也。殷禘者。周春祠、夏禴、卽礿字秋嘗、冬蒸。以禘爲殷祭。殷者、盛也。禘與祫皆合羣廟之主祭於大祖廟也。大禘者。大傳、小記皆曰王者禘其祖之所自出。以其祖配之。謂王者之先祖皆感大微五帝之精以生。皆用正歲之正月郊祭之。孝經郊祀后稷以配天。配靈威仰也。毛詩言禘者二。曰雝、禘大祖也。大祖謂文王。此言殷祭也。曰長發、大禘也。此言商郊祭感生帝汁光紀以玄王配也。云大禘者、葢謂其事大於宗廟之禘。春秋經言諸矦之禮。僖八年禘于太廟。太廟謂周公廟。魯之太"}]},"𧂄":{"expl":"䓿𧂄。芙蓉華未發爲䓿𧂄，已發爲芙蓉。从艸閻聲。","rad":"艸","fq":"徒感切","vol":"01","py":"dàn","duan":[{"e":"䓿𧂄、","n":"逗。"}]},"朧":{"expl":"朦朧也。从月龍聲。","rad":"月","fq":"盧紅切","vol":"07","py":"lónɡ","duan":[]},"有":{"expl":"不宜有也。《春秋傳》曰：“日月有食之。”从月又聲。凡有之屬皆从有。","rad":"有","fq":"云九切","vol":"07","py":"yǒu","duan":[{"e":"不宜有也。","n":"謂本是不當有而有之偁。引伸遂爲凡有之偁。凡春秋書有者、皆有字之本義也。"}]},"㦽":{"expl":"有文章也。从有𡿿聲。","rad":"有","fq":"於六切","vol":"07","py":"yù","duan":[{"e":"有彣彰也。","n":"彣彰各本作文章。誤。今正。彣下曰。𢒰也。是其轉注也。𢒰古多叚彧字爲之。彧者𡿿之隸變。今本論語郁郁乎文哉。古多作彧彧。是以荀彧字文若。宋書王彧字景文。大戴公冠篇。遵並大道邠或。邠或卽彬彧。謂彬彬彧彧也。小雅。黍稷彧彧。傳云。彧彧、茂盛皃。卽有彣彰之義之引伸也。"}]},"龓":{"expl":"兼有也。从有龍聲。讀若聾。","rad":"有","fq":"盧紅切","vol":"07","py":"lónɡ","duan":[{"e":"兼有也。","n":"今牢籠字當作此。籠行而龓廢矣。吳都賦曰。沈虎潛鹿。{馬：換灬爲中}（馽）龓僒束。按{馬：換灬爲中}（馽）龓者、縶而籠其頭也。玉篇曰馬龓頭。說文鞥下云龓頭繞者、亦取兼包之意。"}]},"朙":{"expl":"照也。从月从囧。凡朙之屬皆从朙。","rad":"朙","fq":"武兵切","vol":"07","py":"mínɡ","duan":[{"e":"照也。","n":"火部曰。照明也。小徐作昭。日部曰。昭、明也。大雅。皇矣傳曰。照臨四方曰明。凡明之至則曰明明。明明猶昭昭也。大雅大明、常武傳皆云。明明、察也。詩言明明者五。堯典言朙朙者一。禮記大學篇曰。大學之道。在明明德。鄭云。明明德、謂顯明其至德也。有駜。在公明明。鄭箋云。在於公之所但明明德也。引禮記大學之道在明明德夫由微而著。由著而極。光被四表。是謂明明德於天下。自孔穎達不得其讀而經義隠矣。"}]},"𦟁":{"expl":"翌也。从明亡聲。","rad":"朙","fq":"呼光切","vol":"07","py":"huānɡ","duan":[{"e":"翌也。","n":"翌也未聞。當作昱。昱、朙也。朚卽今之忙字。亦作茫。俗作忙。玄應書曰。茫又作朚。遽也。朚人晝夜作。無日用月。無月用火。常思明。故从明。或云朚人思天曉。故字从明也。按方言、通俗文皆作茫。方言。茫、遽也。通俗文時務曰。茫、許書則有朚。"}]},"囧":{"expl":"窻牖麗廔闓明。象形。凡囧之屬皆从囧。讀若獷。賈侍中說：讀與明同。","rad":"囧","fq":"俱永切","vol":"07","py":"jiǒnɡ","duan":[{"e":"窗牖麗廔闓朙也。","n":"麗廔雙聲。讀如離婁。謂交𤕟玲瓏也。闓明謂開明也。"}]},"𥁰":{"expl":"《周禮》曰：“國有疑則盟。”諸侯再相與會，十二歲一𥁰。北面詔天之司愼司命。𥁰，殺牲歃血，朱盤玉敦，以立牛耳。从囧从血。","rad":"囧","fq":"武兵切","vol":"07","py":"ménɡ","duan":[{"e":"周禮曰。國有疑則𥁰。","n":"周禮司盟職。掌盟載之法。凡邦國有疑會同。則掌其盟約之載及其禮儀。鄭云。有疑不協也。"}]},"夕":{"expl":"莫也。从月半見。凡夕之屬皆从夕。","rad":"夕","fq":"祥易切","vol":"07","py":"xī","duan":[{"e":"𦱤也。","n":"𦱤者、日且冥也。日且冥而月且生矣。故字从月半見。旦者、日全見地上。𦱤者、日在茻中。夕者、月半見。皆會意象形也。"}]},"夜":{"expl":"舍也。天下休舍也。从夕，亦省聲。","rad":"夕","fq":"羊謝切","vol":"07","py":"yè","duan":[{"e":"舍也。","n":"以曡韵爲訓。"}]},"蓮":{"expl":"芙蕖之實也。从艸連聲。","rad":"艸","fq":"洛賢切","vol":"01","py":"lián","duan":[{"e":"扶渠之實也。","n":"陳風。有蒲與蕑。箋云。蕑當作蓮。蓮、夫渠實也。鄭意欲合三章爲一物耳。本艸經謂之藕實。一名水芝丹。"}]},"夢":{"expl":"不明也。从夕，瞢省聲。","rad":"夕","fq":"莫忠切","vol":"07","py":"ménɡ","duan":[{"e":"不朙也。","n":"小雅。民今方殆。視天夢夢。傳曰。王者爲亂夢夢然。釋訓曰。夢夢、亂也。按故訓釋爲亂。許云不明者、由不明而亂也。以其字从夕。故釋爲不明也。夢之本義爲不明。今字叚爲㝱寐字。夢行而㝱廢矣。"}]},"夗":{"expl":"轉臥也。从夕从卪。臥有卪也。","rad":"夕","fq":"於阮切","vol":"07","py":"yuàn","duan":[{"e":"轉臥也。","n":"謂轉身臥也。詩曰。展轉反側。凡夗聲、宛聲字皆取委曲意。"}]},"夤":{"expl":"敬惕也。从夕寅聲。《易》曰：“夕惕若夤。”","rad":"夕","fq":"翼眞切","vol":"07","py":"yín","duan":[{"e":"敬惕也。","n":"此與十二辰之寅義各不同。釋詁云。寅、敬也。凡尙書寅字皆叚寅爲夤也。漢唐碑多作夤者。凡云夤緣者卽延緣。云八夤者卽八埏。皆雙聲叚借也。"}]},"夝":{"expl":"雨而夜除星見也。从夕生聲。","rad":"夕","fq":"疾盈切","vol":"07","py":"qínɡ","duan":[{"e":"雨而夜除星見也。","n":"衞風。靈雨旣零。命彼倌人。星言夙駕。韓詩曰。星者、精也。按精者今晴字。史記天精而見景星。漢書作天暒。孟康曰。暒者、精明也。漢書亦作精。韋昭曰。精者、淸郎也。郭樸注三倉云。暒者、雨止無云也。古夝暒精皆今之晴。而詩作星。韓非子曰。荆伐陳。吳救之。軍閒三十里。雨十日。夜星。夜星卽夜夝也。雨夜止星見謂之夝。夝星曡韵。引伸爲晝晴之偁。故其字又作暒。○按漢書亦作精。故孟康曰。精、暒明也。今本係後人所改。史漢之天精卽晶之叚借。"}]},"外":{"expl":"遠也。卜尚平旦，今夕卜，於事外矣。","rad":"夕","fq":"五會切","vol":"07","py":"wài","duan":[{"e":"遠也。","n":"此下當有从夕卜三字。"}]},"𡖊":{"expl":"早敬也。从丮，持事；雖夕不休：早敬者也。","rad":"夕","fq":"息逐切","vol":"07","py":"sù","duan":[{"e":"早敬也。","n":"召南毛傳曰。夙、早也。此言早敬者、以字从丮。故䢅下曰。臼辰爲䢅。丮夕爲夙。皆同意。是也。大雅。載震載夙。毛云。夙早也。箋云。夙之言肅也。惟夙有敬意。故鄭云爾。"}]},"𡖶":{"expl":"𡧯也。从夕莫聲。","rad":"夕","fq":"莫白切","vol":"07","py":"mò","duan":[{"e":"𡧯也。","n":"當云𡧯𡖶也。轉寫佚字耳。𡧯𡖶者、夕之靜也。𠴫嗼者、口之靜也。𡧯㱳者、死之靜也。"}]},"多":{"expl":"重也。从重夕。夕者，相繹也，故爲多。重夕爲多，重日爲曡。凡多之屬皆从多。","rad":"多","fq":"得何切","vol":"07","py":"duō","duan":[{"e":"緟也。","n":"緟者、增益也。故爲多。多者勝少者。故引伸爲勝之偁。戰功曰多。言勝於人也。"}]},"夥":{"expl":"齊謂多爲夥。从多果聲。","rad":"多","fq":"乎果切","vol":"07","py":"huǒ","duan":[{"e":"齋謂多也。","n":"方言曰。大物盛多。齋宋之郊、楚魏之際曰夥。許𣄸字下曰。讀若楚人名多夥。此云齋語。皆本方言也。史記陳勝世家曰。楚人謂多爲夥。陳勝楚人。在楚言楚也。"}]},"𡌪":{"expl":"大也。从多圣聲。","rad":"多","fq":"苦回切","vol":"07","py":"ɡuài","duan":[{"e":"大也。","n":"與恢音義皆同。"}]},"茄":{"expl":"芙蕖莖。从艸加聲。","rad":"艸","fq":"古牙切","vol":"01","py":"jiā","duan":[{"e":"扶渠莖。","n":"謂華與葉之莖皆名茄也。？之言柯也。古與荷通用。陳風。有蒲與荷。鄭箋。夫渠之莖曰荷。樊光注爾雅引詩有蒲與茄。屈原曰。製芰荷以爲衣。雧芙蓉以爲裳。楊雄則曰。衿芰茄之綠衣。被芙蓉之朱裳。漢樂府鷺何食。食茄下。亦謂葉下。"}]},"㗬":{"expl":"厚脣皃。从多从尚。","rad":"多","fq":"陟加切","vol":"07","py":"zhā","duan":[{"e":"厚脣皃。从多尙。","n":"陟加切。按鍇本云尙聲。而注云从多尙會意。則聲字衍也。依今音則當云多亦聲。十七部。"}]},"毌":{"expl":"穿物持之也。从一橫貫，象寶貨之形。凡毌之屬皆从毌。讀若冠。","rad":"毌","fq":"古丸切","vol":"07","py":"ɡuàn","duan":[{"e":"穿物持之也。从一橫{日：橫置}。","n":"各本{日：橫置}作貫。淺人所改也。今正。"}]},"貫":{"expl":"錢貝之貫。从毌、貝。","rad":"毌","fq":"古玩切","vol":"07","py":"ɡuàn","duan":[{"e":"錢貝之毌也。","n":"毌各本作貫。今正。錢貝之毌。故其字从毌貝會意也。漢書。都內之錢貫朽而不可挍。其本義也。齋風。射則貫兮。傳云。貫、中也。詩。及爾如貫。易。貫魚以宫人寵。左傳。使疾其民以盈其貫。皆其引伸之義也。其字皆可作毌。叚借爲摜字。習也。如孟子我不貫與小人乘是也。亦借爲宦字。事也。如毛詩三嵗貫女。魯詩作宦是也。毛詩串夷傳云。串、習也。串卽毌之隷變。傳謂卽慣字。箋謂卽昆字。皆於音求之。"}]},"虜":{"expl":"獲也。从毌从力，虍聲。","rad":"毌","fq":"郎古切","vol":"07","py":"lǔ","duan":[{"e":"獲也。","n":"公羊傳。爾虜焉。故凡虜囚亦曰纍臣。謂拘之以索也。於毌義相近。故从毌。"}]},"𢎘":{"expl":"嘾也。艸木之華未發圅然。象形。凡𢎘之屬皆从𢎘。讀若含。","rad":"𢎘","fq":"乎感切","vol":"07","py":"hàn","duan":[{"e":"嘾也。","n":"口部曰。嘾者、含深也。"}]},"圅":{"expl":"舌也。象形。舌體𢎘。𢎘从𢎘，𢎘亦聲。","rad":"𢎘","fq":"胡男切","vol":"07","py":"hán","duan":[{"e":"舌也。","n":"舌在口。所以言別味也。圅之言含也。含於口中也。按大雅毛傳曰。臄者、圅也。通俗文云。口上曰臄。口下曰圅。毛服之圅皆卽說文之𩔞字。𩔞、賾也。故服云口下。毛則渾言之。口上口下不分耳。陸氏音義引許圅舌也之云以釋毛。去之遠矣。許圅與𩔞各字各義。毛、服用圅爲𩔞。圅借爲含。如席閒圅丈圅人爲甲是也。周頌。實圅斯活。傳曰。圅、含也。謂叚借也。"}]},"㽕":{"expl":"木生條也。从𢎘由聲。《商書》曰：“若顚木之有织枿。”古文言由枿。","rad":"𢎘","fq":"以州切","vol":"07","py":"yóu","duan":[{"e":"木生條也。","n":"條者、小枝也。"}]},"甬":{"expl":"艸木華甬甬然也。从𢎘用聲。","rad":"𢎘","fq":"余隴切","vol":"07","py":"yǒnɡ","duan":[{"e":"艸木𠌶甬甬然也。","n":"小徐曰。甬之言湧也。若水湧出也。周禮。鐘柄爲甬。按凡从甬聲之字皆興起之意。"}]},"𢎙":{"expl":"艸木𢎘盛也。从二𢎘。","rad":"𢎘","fq":"胡先切","vol":"07","py":"xián","duan":[]},"𣐺":{"expl":"木垂華實。从木、𢎘，𢎘亦聲。凡𣐺之屬皆从𣐺。","rad":"𣐺","fq":"胡感切","vol":"07","py":"hàn","duan":[{"e":"艸木𡍮𠌶實也。","n":"艸字依玉篇補。"}]},"荷":{"expl":"芙蕖葉。从艸何聲。","rad":"艸","fq":"胡哥切","vol":"01","py":"hé","duan":[{"e":"扶渠葉。","n":"今爾雅曰。其葉蕸。音義云。衆家無此句。惟郭有。就郭本中或復無此句。亦竝闕讀。玉裁按。無者是也。高注淮南云。荷夫渠也。其莖曰茄。其本曰蔤。其根曰藕。其華曰夫容。其秀曰䓿萏。其實蓮。蓮之藏者菂。菂之中心曰薏。大致與爾雅同。亦無其葉蕸三字、葢大葉駭人。故謂之荷。大葉扶搖而起。渠央寬大。故曰夫渠。爾雅假葉名其通體。故分別莖華實根各名而冠以荷夫渠三字。則不必更言其葉也。荷夫渠之華爲䓿萏。䓿萏之葉爲荷夫渠。省文互見之法也。或疑闕葉而補之。亦必當曰其葉荷。不嫌重複。無庸肊造蕸字。又案屈原、宋玉、楊雄皆以芙蓉與芰荷對文。然則芰者蔆之葉。蔆者芰之實。蔆之言棱角也。芰之言支起也。"}]},"𩏏":{"expl":"束也。从𣐺韋聲。","rad":"𣐺","fq":"千非切","vol":"07","py":"wéi","duan":[{"e":"束也。","n":"束之訓於从韋得之。"}]},"𠧪":{"expl":"艸木實垂𠧪𠧪然。象形。凡𠧪之屬皆从𠧪。讀若調。","rad":"𠧪","fq":"徒遼切","vol":"07","py":"tiáo","duan":[{"e":"艸木實𡍮𠧪𠧪然。","n":"𠧪𠧪、𡍮皃。莊子曰。之調調。之刀刀。之、此也。調調謂長者。刀刀謂短者。調調卽𠧪𠧪也。𠧪之隸變爲卣。周書雒詰曰。秬鬯二卣。大雅江漢曰。秬鬯一卣。毛云。卣、器也。鄭注周禮廟用修曰。修讀曰卣。卣中尊。凡彜爲上尊。卣爲中尊。罍爲下尊。中尊謂獻象之屬。按如許說則木實𡍮者其本義。叚借爲中尊字也。"}]},"㮚":{"expl":"木也。从木，其實下垂，故从𠧪。","rad":"𠧪","fq":"力質切","vol":"07","py":"lì","duan":[{"e":"栗木也。","n":"三字句。舊𠜂栗字。非也。叚借爲戰栗。"}]},"𥻆":{"expl":"嘉穀實也。从𠧪从米。孔子曰：“𥻆之爲言續也。”","rad":"𠧪","fq":"相玉切","vol":"07","py":"sù","duan":[{"e":"嘉穀實也。","n":"禾下曰。嘉穀也。黍下曰。禾屬而黏者也。然則嘉穀謂禾黍也。大雅曰。誕降嘉穀。惟秬惟秠。惟虋惟芑。秬秠謂黍。虋芑謂禾。許於秠下曰。秬秠者、天賜后稷之嘉穀也。虋下曰。赤苗嘉穀也。芑下曰。白苗嘉穀也。毛魏風傳釋苗爲嘉穀。苗者、禾也。生民傳釋黃爲嘉穀。黃者、黃梁。謂禾也。古者民食莫重於禾黍。故謂之嘉穀。穀者、百穀之總名。嘉者、美也。嘉穀字見詩生民。許書及典引注可據。改爲嘉種者、非。嘉穀之實曰粟。粟之皮曰穅。中曰米。"}]},"齊":{"expl":"禾麥吐穗上平也。象形。凡亝之屬皆从亝。","rad":"齊","fq":"徂兮切","vol":"07","py":"qí","duan":[{"e":"禾麥吐穗上平也。象形。","n":"从二者、象地有高下也。禾麥隨地之高下爲高下。似不齋而實齊。參差其上者、葢明其不齊而齊也。引伸爲凡齊等之義。古叚爲臍字。亦估爲𥚪字。徂兮切。十五部。"}]},"𪗍":{"expl":"等也。从亝妻聲。","rad":"齊","fq":"徂兮切","vol":"07","py":"qí","duan":[{"e":"等也。","n":"齊等字當作此。齊行而𪗍廢矣。"}]},"朿":{"expl":"木芒也。象形。凡朿之屬皆从朿。讀若刺。","rad":"朿","fq":"七賜切","vol":"07","py":"cì","duan":[{"e":"木芒也。","n":"芒者、艸耑也。引伸爲凡鑯銳之偁。今俗用鋒鋩字古衹作芒。朿今字作刺。刺行而朿廢矣。方言曰。凡草木刺人。北燕朝鮮之閒謂之茦。或謂之壯。自關而東或謂之梗。或謂之劌。自關而西謂之刺。江湘之閒謂之棘。"}]},"棗":{"expl":"羊棗也。从重朿。","rad":"朿","fq":"子皓切","vol":"07","py":"zǎo","duan":[{"e":"羊棗也。","n":"羊葢衍文。羊棗卽木部之梬。爾雅諸棗中之一。與常棗絶殊。不當專取以爲訓。益此當云棗木也。棗樹隨地有之。盡人所識。赤心而外朿。非羊棗也。必轉寫妄改之誤。"}]},"棘":{"expl":"小棗叢生者。从並朿。","rad":"朿","fq":"已力切","vol":"07","py":"jí","duan":[{"e":"小棗叢生者。","n":"此言小棗則上文謂常棗可知。小棗樹叢生。今亦隨在有之。未成則爲棘而不實。已成則爲棗。魏風。園有棘。其實之食。唐風。肅肅鴇翼。集於苞棘。小雅。有捄棘匕。毛傳曰。棘、棗也。此謂統言不別也。邶風。吹彼棘心。吹彼棘薪。左傳。除翦其荆棘。此則主謂未成者。古多叚棘爲亟字。如棘人欒欒兮、我是用棘、匪棘其欲皆是。棘亟同音。皆謂急也。"}]},"片":{"expl":"判木也。从半木。凡片之屬皆从片。","rad":"片","fq":"匹見切","vol":"07","py":"piàn","duan":[{"e":"判木也。","n":"謂一分爲二之木。片判以曡韵爲訓。判者、分也。周禮媒氏。掌萬民之判。喪服傳曰。夫妻胖合也。牉當作片。片卽媒氏判字。鄭注周禮云。判、半也。得耦爲合。主合其半成夫婦也。按夫婦各半而合。故取象於合𧯷。漢書一半冰。亦叚半爲片字。"}]},"蔤":{"expl":"芙蕖本。从艸密聲。","rad":"艸","fq":"美必切","vol":"01","py":"mì","duan":[{"e":"扶渠本。","n":"釋艸。其本蔤。郭云。莖下白蒻在泥中者。按蔤之言入水深密也。蒲本亦偁蔤。周書？席。今作蔑席。纖蒻席也。檀弓。子蒲卒。哭者呼滅。注曰。滅葢子蒲名。哭呼名。故子臯非之。？滅皆蔤之叚借也。名蔤。故字蒲。"}]},"版":{"expl":"判也。从片反聲。","rad":"片","fq":"布綰切","vol":"07","py":"bǎn","duan":[{"e":"片也。","n":"舊作判也。淺人所改。今正。凡施於宫室器用者皆曰版。今字作板。古叚爲反字。大雅。上帝板板。傳云。板板、反也。謂版卽反之叚借也。"}]},"𤗚":{"expl":"判也。从片畐聲。","rad":"片","fq":"芳逼切","vol":"07","py":"bì","duan":[{"e":"片也。","n":"片各本作判。今正。副者、判也。𤗚則判木也。廣韵曰。𤗚版、出通俗文。"}]},"牘":{"expl":"書版也。从片賣聲。","rad":"片","fq":"徒谷切","vol":"07","py":"dú","duan":[{"e":"書版也。","n":"牘專謂用於書者。然則周禮之版、禮經之方皆牘也。小宰注曰。版、戸籍也。宫正注曰。版、其人之名籍也。聘禮注曰。策、簡也。方、版也。李賢蔡邕傳注引說文而曰長一尺。按漢人多云尺牘。史記。緹縈通尺牘。此臣得用於君也。漢書。陳遵與人尺牘。主皆藏去。此施於儕輩者也。木部云。槧、牘樸也。然則粗者爲槧。精者爲牘。顏師古曰。形若今之木笏。但不挫其角耳。"}]},"牒":{"expl":"札也。从片枼聲。","rad":"片","fq":"徒叶切","vol":"07","py":"dié","duan":[{"e":"札也。","n":"木部云。札、牒也。左傳曰。右師不敢對。受牒而退。司馬貞曰。牒、小木札也。按厚者爲牘。薄者爲牒。牒之言枼也。葉也。竹部䈎義略同。史記叚諜爲牒。"}]},"牑":{"expl":"牀版也。从片扁聲。讀若邊。","rad":"片","fq":"方田切","vol":"07","py":"biān","duan":[{"e":"牀版也。","n":"方言曰。牀其上版。衛之北郊趙魏之閒謂之牒。或曰牑。按左傳楄柎藉榦。義與牑近。"}]},"牖":{"expl":"穿壁以木爲交窻也。从片、戶、甫。譚長以爲：甫上日也，非戶也。牖，所以見日。","rad":"片","fq":"與久切","vol":"07","py":"yǒu","duan":[{"e":"穿壁㠯木爲交窗也。","n":"交窗者、以木横直爲之。卽今之窗也。在牆曰牖。在屋曰窗。此則互明之。必言以木者、字从片也。古者室必有戶有牖。牖東戶西。皆南鄉。毛詩曰。向、北出牖也。北或有穴通明。至冬塞之。然士虞禮祝啓牖鄉注云。鄉、牖一名。明堂位達鄉注。牖屬。是南牖亦名向。士喪禮。寢東首於墉下。喪大記作北墉下。今本墉皆譌牖。非也。牖所以通明。故叚爲誘。召南吉士誘之、大雅天之牖民傳皆訓曰。道也。道卽導。"}]},"牏":{"expl":"築牆短版也。从片俞聲。讀若俞。一曰若紐。","rad":"片","fq":"度矦切","vol":"07","py":"tóu","duan":[{"e":"築牆短版也。","n":"木部栽下曰。築牆長版也。長版用於㒳邊。短版用於㒳耑。一縮一横也。此牏之本義。史、漢萬石君傳。石建取親中裙廁牏。身自浣滌。蘇林曰。牏音投。賈逵解周官云。牏、行淸也。孟康曰廁、行淸。牏、行淸中受糞函者也。東南人謂鑿木空中如曹謂之牏。依蘇、孟說則史、漢之牏卽窬之叚借字。穴部曰。窬、空中也。徐廣謂讀牏爲竇。是也。至若晉灼云。今世謂反閉小袖衫爲侯牏。則尤爲叚借字。釋名曰。齊人謂如衫而小袖曰侯頭。侯頭猶言解瀆。？直通之言。是則其語本無正字。"}]},"鼎":{"expl":"三足兩耳，和五味之寶器也。昔禹收九牧之金，鑄鼎荆山之下，入山林川澤，螭魅蝄蜽，莫能逢之，以協承天休。《易》卦：巽木於下者爲鼎，象析木以炊也。籒文以鼎爲貞字。凡鼎之屬皆从鼎。","rad":"鼎","fq":"都挺切","vol":"07","py":"dǐnɡ","duan":[{"e":"三足㒳耳。和五味之寶器也。","n":"三足㒳耳謂器形。非謂字形也。九家易曰。鼎三足以象三台也。易曰。鼎黃耳。和當作盉。許亦從俗通用。"}]},"鼒":{"expl":"鼎之圜掩上者。从鼎才聲。《詩》曰：“鼐鼎及鼒。”","rad":"鼎","fq":"子之切","vol":"07","py":"zī","duan":[{"e":"鼎之圜掩上者。","n":"周頌。鼐鼎及鼒。釋器曰。圜弇上謂之鼒。手部曰。掩、斂也。小上曰掩。？部曰。弇、葢也。然則此依許作掩爲正字。"}]},"鼐":{"expl":"鼎之絕大者。从鼎乃聲。《魯詩》說：鼐，小鼎。","rad":"鼎","fq":"奴代切","vol":"07","py":"nài","duan":[{"e":"鼎之絕大者。","n":"釋器曰。鼎絕大謂之鼐。周頌傳曰。大鼎謂之鼐。小鼎謂之鼒。傳與爾雅說鼒異。說鼐則略同。絕大謂函牛之鼎也。九家易曰。牛鼎受一斛。羊鼎五斗。豕鼎三斗。乃者、詞之難也。故从乃爲大。才者、艸木之初也。故从才爲小。"}]},"蕅":{"expl":"芙蕖根。从艸、水，禺聲。","rad":"艸","fq":"五厚切","vol":"01","py":"ǒu","duan":[{"e":"扶渠根。","n":"釋艸。其根耦。按釋艸以其本蔤系於荷扶渠其莖茄之下者、謂此乃全荷之本。今俗所謂藕者是也。蔤之言滅𣳚於泥中也。以其根藕系於其華䓿𧂄其實蓮之下者、謂此乃花實之根。凡花實之莖必偕葉一莖同出。似有耦然。故下近蔤、上近花莖之根曰藕。本言其全。根言其偏。本在下。根上於本。下文的薏仍冡花實言之。此作爾雅之精意也。叔重列字次弟。未得其解矣。"}]},"鼏":{"expl":"以木橫貫鼎耳而舉之。从鼎冂聲。《周禮》：“廟門容大鼏七箇。” 即《易》“玉鉉大吉”也。","rad":"鼎","fq":"莫狄切","vol":"07","py":"mì","duan":[{"e":"㠯木橫貫鼎耳舉之。","n":"貫當作毌。許亦從俗也。禮經十七篇多言扃、鼏。注多言今文扃爲鉉、古文𪔃爲密。按扃者、叚借字。𪔃者、正字。鉉者、音近義同字也。以木横毌鼎耳是曰𪔃。㒳手舉其木之耑是曰扛鼎。𪔃橫於鼎葢之上。故禮經必。先言抽扃。乃後取鼏。猶扃爲戶外閉之關。故或以扃代之也。"}]},"克":{"expl":"肩也。象屋下刻木之形。凡克之屬皆从克。","rad":"克","fq":"苦得切","vol":"07","py":"kè","duan":[{"e":"肩也。","n":"周頌傳曰。仔肩、克也。人部曰。仔、克也。此曰。克、肩也。然則周頌仔肩絫言之。毛謂二字皆訓克也。肩謂任。任事以肩。故任謂之肩。亦謂之克。釋詁云。肩、克也。又曰。肩、勝也。鄭箋云。仔肩、任也。許云。勝、任也。任、保也。保、當也。凡物壓於上謂之克。今蘇常俗語如是。釋言曰。克、能也。其引伸之義。左傳曰。凡師得儁曰克。於鄭伯克段於鄢曰。如二君。故曰克。卽得儁之說也。穀梁曰。克者何。能也。何能也。能殺也。此釋言之說也。公羊曰。克之者何。殺之也。此以相勝爲義。大雅毛傳云。掊克、自伐而好勝人也。俗作剋。"}]},"彔":{"expl":"刻木录录也。象形。凡录之屬皆从录。","rad":"彔","fq":"盧谷切","vol":"07","py":"lù","duan":[{"e":"刻木彔彔也。","n":"小徐曰。彔彔猶歷歷也。一一可數之皃。按剝下曰。彔、刻割也。彔彔、麗廔嵌空之皃。毛詩車歷錄亦當作歷彔。"}]},"禾":{"expl":"嘉穀也。二月始生，八月而孰，得時之中，故謂之禾。禾，木也。木王而生，金王而死。从木，从𠂹省。𠂹象其穗。凡禾之屬皆从禾。","rad":"禾","fq":"戶戈切","vol":"07","py":"hé","duan":[{"e":"嘉穀也。","n":"嘉禾曡韵。生民詩曰。天降嘉穀。維虋維芑。虋芑、爾雅謂之赤苗、白苗。許艸部皆謂之嘉穀。皆謂禾也。公羊何注曰。未秀爲苗。巳秀爲禾。魏風。無食我黍。無食我麥。無食我苗。毛曰。苗、嘉穀也。嘉穀謂禾也。生民傳曰。黃、嘉穀也。嘉穀亦謂禾。民食莫重於禾。故謂之嘉穀。嘉穀之連稿者曰禾。實曰𥻆。𥻆之人曰米。米曰梁。今俗云小米是也。"}]},"秀":{"expl":"上諱。漢光武帝名也。","rad":"禾","fq":"息救切","vol":"07","py":"xiù","duan":[]},"稼":{"expl":"禾之秀實爲稼，莖節爲禾。从禾家聲。一曰稼，家事也。一曰在野曰稼。","rad":"禾","fq":"古訝切","vol":"07","py":"jià","duan":[{"e":"禾之秀實爲稼。","n":"旣言秀又言實者、論語說也。謂禾𥝩之成曰稼也。甫田。曾孫之稼。箋云。稼、禾也。謂有稿者也。"}]},"𥣱":{"expl":"穀可收曰穡。从禾𠾂聲。","rad":"禾","fq":"所力切","vol":"07","py":"sè","duan":[{"e":"穀可收曰穡。","n":"毛傳曰。斂之曰穡。許不云斂之云可收者、許主謂在野成孰。不言禾言穀者、晐百穀言之。不獨謂禾也。古多叚嗇爲穡。"}]},"穜":{"expl":"埶也。从禾童聲。","rad":"禾","fq":"之用切","vol":"07","py":"zhònɡ","duan":[{"e":"埶也。","n":"丮部曰。埶、穜也。小篆埶爲穜。之用切。種爲先穜後孰。直容切。而隸書互易之。詳張氏五經文字。種者以穀播於土。因之名穀可種者曰種。凡物可種者皆曰種。別其音之隴切。生民曰。種之黃茂。又曰。實種實褎。箋云。種生不雜也。"}]},"稙":{"expl":"早穜也。从禾直聲。《詩》曰：“稙稚尗麥。”","rad":"禾","fq":"常職切","vol":"07","py":"zhí","duan":[{"e":"早穜也。","n":"此謂凡穀皆有早種者。魯頌傳曰。先種曰稙。謂先種先孰也。釋名曰。靑徐人謂長婦曰稙長。禾苗先生者曰稙。取名於此也。"}]},"種":{"expl":"先穜後孰也。从禾重聲。","rad":"禾","fq":"直容切","vol":"07","py":"chónɡ","duan":[{"e":"先穜後孰也。","n":"此謂凡穀有如此者。邠風傳曰。後孰曰重。周禮內宰注。鄭司農云。先種後孰謂之穜。按毛詩作重。叚借字也。周禮作穜。轉寫以今字易之也。"}]},"蘢":{"expl":"天蘥也。从艸龍聲。","rad":"艸","fq":"盧紅切","vol":"01","py":"lónɡ","duan":[{"e":"天蘥也。","n":"見釋艸。"}]},"稑":{"expl":"疾孰也。从禾坴聲。《詩》曰：“黍稷種稑。”","rad":"禾","fq":"力竹切","vol":"07","py":"lù","duan":[{"e":"疾孰也。","n":"謂凡穀有如此者。邠風傳曰。先孰曰穋。周禮內宰注。鄭司農云。後種先孰謂之稑。按土宜物性卽同一種而有不同。故大司徒必辨十有二壤之物而知其種。司稼掌巡邦野之稼而辨穜穋之種也。"}]},"稺":{"expl":"幼禾也。从禾屖聲。","rad":"禾","fq":"直利切","vol":"07","py":"zhì","duan":[{"e":"幼禾也。","n":"魯頌毛傳曰。後種曰稺。許不言後種者、後種固小於先種。卽先種者當其未長亦稺也。先種而中有遟長者亦稺也。故惟魯頌稙稺對言、毛釋之。小雅。無害我田稺、彼有不穫稺。毛不釋者、亦謂槩言幼禾。引伸爲凡幼之偁。今字作稚。"}]},"稹":{"expl":"穜穊也。从禾眞聲。《周禮》曰：“稹理而堅。”","rad":"禾","fq":"之忍切","vol":"07","py":"zhěn","duan":[{"e":"穜穊也。","n":"此與鬒爲稠髮同也。引伸爲凡密緻之偁。"}]},"稠":{"expl":"多也。从禾周聲。","rad":"禾","fq":"直由切","vol":"07","py":"chóu","duan":[{"e":"多也。","n":"本謂禾也。引伸爲凡多之偁。小雅。綢直如髮。叚綢爲稠也。"}]},"穊":{"expl":"稠也。从禾旣聲。","rad":"禾","fq":"几利切","vol":"07","py":"jì","duan":[{"e":"稠也。","n":"漢書。劉章言耕田曰。深耕穊種。立苗欲疏。非其種者。鉏而去之。引伸爲凡稠之偁。"}]},"稀":{"expl":"䟽也。从禾希聲。","rad":"禾","fq":"香依切","vol":"07","py":"xī","duan":[{"e":"疏也。","n":"？部曰。疏、通也。稀與穊爲反對之辭。所謂立苗欲疏也。引伸爲凡疏之偁。"}]},"𥣫":{"expl":"禾也。从禾蔑聲。","rad":"禾","fq":"莫結切","vol":"07","py":"miè","duan":[{"e":"禾也。","n":"葢禾有名𥣫者也。廣韵曰。莊子謂之禾也。"}]},"穆":{"expl":"禾也。从禾㣎聲。","rad":"禾","fq":"莫卜切","vol":"07","py":"mù","duan":[{"e":"禾也。","n":"葢禾有名穆者也。凡經傳所用穆字。皆叚穆爲㣎。㣎者、細文也。从彡、𡭴省。彡言文。𡭴言細。凡言穆穆、於穆、昭穆皆取幽微之義。釋訓曰。穆穆、敬也。大雅文王傳曰。穆穆、美也。"}]},"私":{"expl":"禾也。从禾厶聲。北道名禾主人曰私主人。","rad":"禾","fq":"息夷切","vol":"07","py":"sī","duan":[{"e":"禾也。","n":"葢禾有名私者也。今則叚私爲公厶。倉頡作字。自營爲厶。背厶爲公。然則古衹作厶。不作私。"}]},"䆏":{"expl":"稻紫莖不黏也。从禾糞聲。讀若靡。","rad":"禾","fq":"扶沸切","vol":"07","py":"fèi","duan":[{"e":"稻紫莖不粘者也。","n":"者字今補。"}]},"蓍":{"expl":"蒿屬。生十歲，百莖。《易》以爲𢿙。天子蓍九尺，諸侯七尺，大夫五尺，士三尺。从艸耆聲。","rad":"艸","fq":"式脂切","vol":"01","py":"shī","duan":[{"e":"蒿屬。","n":"謂似蒿而非蒿也。陸機曰。似藾蕭。靑色。"}]},"稷":{"expl":"𪗉也。五穀之長。从禾畟聲。","rad":"禾","fq":"子力切","vol":"07","py":"jì","duan":[{"e":"𪗉斉也。","n":"程氏瑤田九穀攷曰。稷、𪗉、大名也。粘者爲秫。北方謂之高粱。通謂之秫秫。又謂之蜀黍。高大似蘆。月令。首種不入。鄭云。首種謂稷。今以北方諸穀播種先後攷之。高粱冣先。管子書。日至七十日。陰凍釋而蓺稷。百日不蓺稷。日至七十日。今之正月也。今南北皆以正月蓺高粱是也。凡經言疏食者、稷食也。稷形大。故得疏偁。按程氏九穀攷至爲精析。學者必讀此而後能正名其言。漢人皆冒粱爲稷。而稷爲秫秫。鄙人能通其語者。士大夫不能舉其字。眞可謂撥雲霧而覩靑天矣。"}]},"𪗉":{"expl":"稷也。从禾亝聲。","rad":"禾","fq":"卽夷切","vol":"07","py":"zī","duan":[{"e":"稷也。","n":"釋艸曰。秶、稷也。周禮甸師齍盛注云。秶者、稷也。穀者稷爲長。按經作？。注作秶。此經用古字、注用今字之例。周禮？盛字鄭易爲秶者三。甸師、肆師、大祝也。小宗伯六？注云。？讀爲秶。六秶謂六穀。黍稷稻粱麥苽。云？讀爲秶。此易？爲秶之證也。秶本謂稷。何以六穀統名秶。則以稷爲穀之長。故得槩之。甸師注是其恉也。米本謂禾。凡穀皆得名米。秶盛之秶猶是矣。甫田作齊。亦作？。毛曰。器實曰？。而左傳、禮記皆作秶盛。是可證？秶之同字。穀名曰秶。用以祭祀則曰？。別之者、貴之也。今經典秶皆譌粢。而？字且不見於經典矣。廣韵曰。𪗉、祭飯也。玉篇曰。黍稷在器曰𪗉。知舊本經典故作𪗉盛。"}]},"秫":{"expl":"稷之黏者。从禾；术，象形。","rad":"禾","fq":"食聿切","vol":"07","py":"shú","duan":[{"e":"稷之粘者。","n":"九穀攷曰。稷、北方謂之高粱。或謂之紅梁。其粘者黃白二種。所謂秫也。秫爲黏稷。而不黏者亦通𧦝爲秫秫。而他穀之黏者亦叚借通偁之曰秫。陶淵明使公田二頃。五十畝種秫。稻之黏者也。崔豹古今注所謂秫爲黏稻是也。"}]},"穄":{"expl":"𪎭也。从禾祭聲。","rad":"禾","fq":"子例切","vol":"07","py":"jì","duan":[{"e":"𪎭也。","n":"此謂黍之不粘者也。黍部曰。𪎭者、穄也。吕氏春秋。飯之美者。陽山之穄。高注云。關西謂之𪎭。冀州謂之䵖。廣雅。䵛、𪎭、穄也。九穀攷曰。據說文。禾屬而黏者黍。則禾屬而不黏者𪎭。對文異。散文則通偁黍。內則。飯黍稷稻梁。白黍黃梁。鄭注。黍、黃黍也。黃黍者、𪎭也。穄也。飯用之。黏者、釀酒及爲餌餈酏粥之屬。不黏者、𧦝𪎭𧦝穄。而黏者乃專得黍名矣。今北方皆𧦝黍子、𪎭子、穄子。穄與稷雙聲。故俗誤認爲稷。其誤自唐之蘇恭始。"}]},"稻":{"expl":"稌也。从禾舀聲。","rad":"禾","fq":"徒皓切","vol":"07","py":"dào","duan":[{"e":"稌也。","n":"今俗㮣謂黏者不黏者。未去穅曰稻。稬稻、秈稻、秔稻皆未去穅之偁也。旣去穅則曰稬米、曰秈米、曰秔米。古謂黏者爲稻。謂黏米爲稻。九穀攷曰。七月詩。十月穫稻。爲此春酒。月令。乃命大酋。秫稻必齊。內則、襍記並有稻醴。左傳。進稻醴粱糗。是以稻爲黏者之名。黏者以釀也。內則。糝酏用稻米。籩人職之餌餈。注亦以爲用稻米。皆取其黏耳。而食醫之職。牛宜稌。鄭司農說稌、稉也。是又以稉釋稻。稉其不黏者也。孔子曰。食夫稻。亦不必專指黏者言。職方氏揚荆諸州亦但云其穀宜稻。吾是以知稌稻之爲大名也。玉裁謂。稻其渾言之偁。秔與稻對爲析言之偁。稻宜水。故周禮稻人掌稼下地。"}]},"稌":{"expl":"稻也。从禾余聲。《周禮》曰：“牛宜稌。”","rad":"禾","fq":"徒古切","vol":"07","py":"tú","duan":[{"e":"稻也。","n":"釋艸曰。稌、稻。周頌毛傳同。許曰。沛國𧦝稬。而郭樸曰。今沛國呼稌。然則稌稬本一語。而稍分輕重耳。"}]},"稬":{"expl":"沛國謂稻曰稬。从禾耎聲。","rad":"禾","fq":"奴亂切","vol":"07","py":"nuò","duan":[{"e":"沛國謂稻曰稬。","n":"襄五年穀梁傳。仲孫蔑、衛孫林父會吳於善稻。吳謂善、伊。謂稻、緩。按謂善爲伊者、古合韵也。謂稻爲緩者、卽沛國謂稻曰稬之理也。緩古亦讀如暖。昭五年。狄人謂賁泉矢胎。謂賁爲矢者、卽今俗語謂糞爲矢也。今矢胎作失台者、誤。"}]},"稴":{"expl":"稻不黏者。从禾兼聲。讀若風廉之廉。","rad":"禾","fq":"力兼切","vol":"07","py":"xián","duan":[{"e":"稻不黏者。","n":"凡穀皆有黏者有不黏者。秫則稷之？者也。穄則黍之不黏者也。稻有不黏者、則稴是也。今俗通謂不黏者爲秈米。集韵、類篇皆云。方言江南呼稉爲秈。亦作籼、作粞。按說文、玉篇皆有稴無秈。葢秈卽稴字音變而字異耳。廣雅曰。秈、稉也。渾言不別也。"}]},"秔":{"expl":"稻屬。从禾亢聲。","rad":"禾","fq":"古行切","vol":"07","py":"jīnɡ","duan":[{"e":"稻屬。","n":"凡言屬者、以屬見別也。言別者、以別見屬也。重其同則言屬。秔爲稻屬是也。重其異則言別。稗爲禾別是也。周禮注曰。州黨族閭比鄉之屬別。介次市亭之屬別。小者屬別並言。分合並見也。稻有至黏者、稬是也。有次黏者、稉是也。有不黏者、稴是也。稉比於稬則爲不黏。比於稴則尙爲黏。稉與稴爲飯。稬以釀酒、爲餌餈。今與古同矣。散文稉亦偁稻。對文則別。魏都賦。水澍稉稌。陸蒔稷黍。蜀都賦。黍稷油油。稉稻莫莫。皆稉稻並舉。本艸經秔米稻米殊用。陶貞白乃不能分別。其亦異矣。"}]},"秏":{"expl":"稻屬。从禾毛聲。伊尹曰：“飯之美者，玄山之禾，南海之秏。”","rad":"禾","fq":"呼到切","vol":"07","py":"hào","duan":[{"e":"稻屬。","n":"漢書曰。訖於孝武後元之年。靡有孑遺秏矣。孟康曰。秏音毛。無有秏米在者也。秏米、米名。卽所謂稻屬也。今本作毛米。誤。孟意若今言無有一粒存者。水經注曰。燕人謂無爲毛。故有用毛爲無者。又有用秏者。初讀莫報切。旣又讀呼到切。改禾旁爲耒旁。罕知其本音本義本形矣。大雅。秏斁下土。秏者、乏無之謂。故韓詩云惡也。"}]},"菣":{"expl":"香蒿也。从艸臤聲。","rad":"艸","fq":"去刃切","vol":"01","py":"qìn","duan":[{"e":"香蒿也。","n":"詩。食野之蒿。爾雅、毛傳皆云。蒿、菣也。郭樸云。今人呼爲靑蒿。香中炙啖者爲菣。"}]},"穬":{"expl":"芒粟也。从禾廣聲。","rad":"禾","fq":"百猛切","vol":"07","py":"kuànɡ","duan":[{"e":"芒粟也。","n":"周禮稻人。澤草所生。種之芒種。鄭司農云。芒種、稻麥也。按凡穀之芒。稻麥爲大。芒粟次於此。麥下曰芒穀。然則許意同先鄭也。稻麥得𧦝粟者、從嘉穀之名也。"}]},"秜":{"expl":"稻今秊落，來秊自生，謂之秜。从禾尼聲。","rad":"禾","fq":"里之切","vol":"07","py":"lí","duan":[{"e":"稻今年落來年自生謂之秜。","n":"淮南書。離先稻孰。而農夫耨之。不以小利傷大穫也。注云。離與稻相似。耨之爲其少實。疑離卽秜。玉篇、廣韵秜皆力脂切。則音同也。他書皆作穭。力與切。埤蒼。穭、自生也。亦作稆。後漢書獻帝紀。尙書郎以下。自出采稆。古作旅。史漢皆云。觜觿主？旅事。晉灼曰。？、采也。野生曰旅。今之飢民采旅生。按離秜旅一聲之轉。皆謂不種而自生者也。"}]},"稗":{"expl":"禾別也。从禾卑聲。琅邪有稗縣。","rad":"禾","fq":"㫄卦切","vol":"07","py":"bài","duan":[{"e":"禾別也。","n":"謂禾類而別於禾也。孟子曰。苟爲不孰。不如荑稗。左傳云。用秕稗也。杜云。稗、草之似穀者。稗有米似禾。可食。故亦種之。如淳曰。細米爲稗。故小說謂之稗官。小販謂之稗販。"}]},"移":{"expl":"禾相倚移也。从禾多聲。一曰禾名。","rad":"禾","fq":"弋支切","vol":"07","py":"yí","duan":[{"e":"禾相倚移也。","n":"相倚移者、猶言虚而與之委蛇也。吕氏春秋曰。苗其弱也欲孤。其長也欲相與俱。其熟也欲相扶。倚移、連緜字。曡韵。讀若阿那。攷工記鄭司農注兩引倚移從風。今上林賦作旖旎從風。說文於禾曰倚移。於旗曰旖施。於木曰檹施。皆謂阿那也。毛傳曰。猗儺、柔順也。猗儺卽阿那。表記。衣服以移之。注。移讀如禾氾移之移。移猶廣大也。禾氾移葢謂禾蕃多。郊特牲。其蜡乃通以移民也。鄭曰。移之言羨也。古叚移爲侈。如攷工記飾車欲侈。故書侈爲移。少牢饋食禮移袂。皆是。今人但讀爲遷移。據說文則自此之彼字當作迻。"}]},"穎":{"expl":"禾末也。从禾頃聲。《詩》曰：“禾穎穟穟。”","rad":"禾","fq":"余頃切","vol":"07","py":"yǐnɡ","duan":[{"e":"禾末也。","n":"穎之言莖也。頸也。近於𥝩及貫於𥝩者皆是也。大雅。實穎實栗。毛曰。穎、垂穎也。禹貢鄭注曰。百里賦入總。謂入刈禾也。二百里銍。銍、𣃔去稿也。三百里秸。秸、又去穎也。四百里入粟、五百里入米者、遠彌輕也。禮器。稾鞂之設。鄭注。穗去實曰鞂。鞂與秸同物。鄭注尙書曰。去穎、謂用其𥝩也。注禮器曰。去實、謂用其穎也。史記曰。錐處囊中。穎脫而出。非特其末見而巳。少儀。刀卻刃授穎。是則穎在錐則卻於末。在刀則卻於刃。在禾則卻於𥝩也。渾言之則穎爲禾末。析言之則禾芒乃爲秒。"}]},"䅘":{"expl":"齊謂麥䅘也。从禾來聲。","rad":"禾","fq":"洛哀切","vol":"","py":"lái","duan":[{"e":"齊謂麥䅘也。","n":"來之本義訓麥。然則加禾旁作。來俗字而巳。葢齊字也。據廣韵則埤蒼來？字作䅘。"}]},"𥝩":{"expl":"禾成秀也，人所以收。从爪、禾。","rad":"禾","fq":"徐醉切","vol":"07","py":"suì","duan":[{"e":"禾成秀人所收者也。","n":"依爾雅音義及玄應書訂。𥝩與秀古互訓。如月令注。黍秀舒散。卽謂黍𥝩也。人所收。故从爪。"}]},"䄪":{"expl":"禾危穗也。从禾勺聲。","rad":"禾","fq":"都了切","vol":"07","py":"diǎo","duan":[{"e":"禾危𥝩也。","n":"危𥝩謂穎欲𣃔落也。齊民要術云。刈晚則穗折。遇風則收減。玉篇云。䄪亦懸物也。則䄪同方言之？。方言曰。？、縣也。趙魏之閒曰？。燕趙之郊縣物於臺之上謂之？。郭樸曰。了？、縣物皃。丁小反。按玄應書及集韵所引方言皆如是。今本方言作佻。妄人所改耳。王延壽王孫賦。？瓜懸而瓠垂。？者象形字。䄪者諧聲字。"}]},"穟":{"expl":"禾𥝩之皃。从禾遂聲。《詩》曰：“禾穎穟穟。”","rad":"禾","fq":"徐醉切","vol":"07","py":"suì","duan":[{"e":"禾𥝩之皃。","n":"大雅生民曰。禾役穟穟。釋訓曰。穟穟、苗也。毛傳曰。穟穟、苗好美也。按公羊傳注。生曰苗。秀曰禾。苗禾一也。釋訓、毛傳與許說一也。許以經言禾穎。則穟穟指𥝩。言成就之皃。"}]},"𥠄":{"expl":"禾垂皃。从禾耑聲。讀若端。","rad":"禾","fq":"丁果切","vol":"07","py":"duān","duan":[{"e":"禾𠂹皃。","n":"禾𥝩必𡍮。𥝩重則秆𡍮。"}]},"莪":{"expl":"蘿莪，蒿屬。从艸我聲。","rad":"艸","fq":"五何切","vol":"01","py":"é","duan":[{"e":"莪、","n":"逗。"}]},"䅥":{"expl":"禾舉出苗也。从禾曷聲。","rad":"禾","fq":"居謁切","vol":"07","py":"jié","duan":[{"e":"禾舉出苗也。","n":"何休曰。生曰苗。秀曰禾。禾𥝩初挺出於苗是曰䅥。旣成則屈而下？矣。周頌曰。驛驛其達。有厭其傑。毛云。達、射也。有厭其傑。言傑苗厭然特美也。毛、鄭釋詩皆謂苗。許云。禾舉出苗則謂𥝩。手部揭者、高舉也。音義略同。"}]},"秒":{"expl":"禾芒也。从禾少聲。","rad":"禾","fq":"亡沼切","vol":"07","py":"miǎo","duan":[{"e":"禾芒也。","n":"下文云。禾有秒。秋分而秒定。淮南書。秒作蔈。亦作䅺。按艸部云。蔈、末也。禾芒曰秒。猶木末曰杪。九穀攷曰。粟之孚甲無芒。芒生於粟𥝩之莖。"}]},"穖":{"expl":"禾穖也。从禾幾聲。","rad":"禾","fq":"居狶切","vol":"07","py":"jǐ","duan":[{"e":"禾穖也。","n":"九穀攷曰。禾𥝩成實離離若聚珠相聯貫者、謂之穖。與珠璣之璣同意。吕氏春秋。得時之禾。疏穖而穗大。得時之稻。長秱疏穖。高注云。穖、禾穗果？。是也。玉裁謂。穖貴疏者。禾𥝩緊密。每顆皆綻而後能疏也。穖疏而穗乃大。"}]},"秠":{"expl":"一稃二米。从禾丕聲。《詩》曰：“誕降嘉穀，惟秬惟秠。”天賜后稷之嘉穀也。","rad":"禾","fq":"敷悲切","vol":"07","py":"pī","duan":[{"e":"一稃二米。从禾。丕聲。詩曰。誕降嘉穀。惟秬惟秠。天賜后稷之嘉穀也。","n":"按此解當云稃也。从禾。丕聲。詩曰。誕降嘉穀。惟秬惟秠。黑黍、一稃二米。天賜后稷之嘉穀也。爲淺人改竄之耳。詩生民。惟秬惟秠。釋艸曰。秬、黑黍。秠、一稃二米。毛傳正同。葢黑黍一稃二米曰秬。言秬而一稃二米巳見。經文以惟秠足句。見黑黍之稃有異。不比下文惟虋惟芑。畫然二物。故釋訓者以黑黍系秬。以一稃二米系秠。分屬之。鄭志。張逸問云。鬯人職注。秬如黑黍。一秠二米。按爾雅。秠、一稃二米。未知二者同異。荅曰。秠卽其皮。稃亦皮也。爾雅重言以曉人。更無異偁也。據此知秠卽稃。凡稃皆曰秠。非必二米一桴也。許於鬯部？下云。黑黍也。一稃二米。是可見一稃二米者謂秬。非、謂凡秠也。此必偁經文惟秬惟秠。而後總釋之曰黑黍、一稃二"}]},"秨":{"expl":"禾搖皃。从禾乍聲。讀若昨。","rad":"禾","fq":"在各切","vol":"07","py":"zuó","duan":[{"e":"禾繇皃。","n":"繇今搖字。今俗語說動搖之皃曰秨。卽此字也。"}]},"穮":{"expl":"耕禾閒也。从禾麃聲。《春秋傳》曰：“是穮是衮。”","rad":"禾","fq":"甫嬌切","vol":"07","py":"biāo","duan":[{"e":"槈鉏田也。","n":"各本作耕禾閒也。今正。周頌釋文引說文。穮、槈鉏田也。表嬌反。字林。穮、耕禾閒也。方遙反。然則今本說文淺人用字林改之。穮者、𦓷也。非耕也。周頌。緜緜其麃。毛傳曰。麃、耘也。釋訓曰。緜緜、麃也。孫炎云。緜緜言詳密也。郭樸云。芸不息也。左傳。是穮是蔉。杜云。穮、耘也。許云槈鉏田者。槈、薅器也。鉏、立薅斫也。薅者、披田艸也。或槈其田。或鉏其田。皆曰穮。今吳下俗語說用鉏曰暴。卽此字也。"}]},"䅁":{"expl":"轢禾也。从禾安聲。","rad":"禾","fq":"烏旰切","vol":"07","py":"àn","duan":[{"e":"轢禾也。","n":"轢者、車所踐也。此轢讀如勞。卽齊民要術所謂勞也。郞到切。賈思勰曰。古曰耰。今曰勞。說文。櫌、摩田器。今人鄙語曰摩勞。種穀之法。苗旣出壟。每一經雨白背時。輒以鐵齒𨫒楱縱横杷而勞之。杷法。令人坐上數以手𣃔去艸。如此令地輭。易鉏。省力。中鋒止。苗高一尺。鋒之。按賈云鋒之、謂鉏之也。勞之而後鋒之。然則案之而後穮之矣。"}]},"秄":{"expl":"壅禾本。从禾子聲。","rad":"禾","fq":"卽里切","vol":"07","py":"zǐ","duan":[{"e":"雝禾本。","n":"雝俗作壅。小雅。或耘或耔。毛曰。耘、除艸也。耔、雝本也。食貨志。后稷始畎田。以二耜爲耦。廣尺深尺曰畎。長終畝。一畝三畎。一夫三百畎。而播種於畎中。苗生三葉以上。稍耨隴艸。因壝其土以附苗根。故其詩曰。或芸或芓。黍稷儗儗。芸、除艸也。秄、附根也。言苗稍壯。每耨輒附根。比盛暑。隴盡而根深。能風與旱。故儗儗而盛也。按班所據詩作芓。古文叚借字。說詩作秄。小篆字。詩言耘秄。左傳言穮袞。袞者、畎也。隤壟艸壅於畎中也。耔蔉皆俗字。"}]},"穧":{"expl":"穫刈也。一曰撮也。从禾齊聲。","rad":"禾","fq":"在詣切","vol":"07","py":"jì","duan":[{"e":"穫刈也。","n":"穫刈謂穫而芟之也。刈同乂。芟艸也。刈之必齊。故从？。小雅曰。此有不斂穧。謂巳刈而遺於田未斂者也。上文不穫稺。謂幼禾留於田未刈者也。釋詁曰。馘、穧、穫也。鄭注周禮云。四秉曰筥。謂一穧也。"}]},"穫":{"expl":"刈穀也。从禾蒦聲。","rad":"禾","fq":"胡郭切","vol":"07","py":"huò","duan":[{"e":"刈穀也。","n":"穫之言獲也。刈穀者、以銍以鎌。"}]},"祫":{"expl":"大合祭先祖親疏遠近也。从示、合。《周禮》曰：“三歲一祫。”","rad":"示","fq":"侯夾切","vol":"01","py":"xiá","duan":[{"e":"大合祭先祖親疏遠近也。","n":"春秋文二年八月丁卯。大事于大廟。公羊傳曰。大事者何。大祫也。大祫者何。合祭也。毀廟之主陳於大祖。未毀廟之主皆升。句合食於大祖。兼上二者五年而再殷祭。鄭康成曰。魯禮三年喪畢而祫於大祖。明年春禘於羣廟。自此之後。五年而再殷祭。一祫一禘。春秋經書祫謂之大事。書禘謂之有事。商頌玄鳥、祀高宗也。鄭云。祀當爲祫。高宗崩而始合祭於契之廟。歌是詩焉。曾子問。祫祭於祖。則祝迎四廟之主。許言合祭先祖親疏遠近。正用公羊大事傳。禘之合食蓋同。而以審禘、會合分別其名。亦分別其歲有三年五年之殊。分別其時有夏秋之殊。禘卽周禮之肆獻祼追亯。祫卽周禮之饋食朝亯。夏殷有時禘、有時祫。周禮禘祫皆爲殷祭。非四時祭。毛公傳曰。諸矦夏禘"}]},"蘿":{"expl":"莪也。从艸羅聲。","rad":"艸","fq":"魯何切","vol":"01","py":"luó","duan":[{"e":"莪也。","n":"是謂轉注。"}]},"䆅":{"expl":"積禾也。从禾資聲。《詩》曰：“䆅之秩秩。”","rad":"禾","fq":"卽夷切","vol":"07","py":"zī","duan":[{"e":"積禾也。","n":"䆅積雙聲。廣雅曰。䆅、積也。"}]},"積":{"expl":"聚也。从禾責聲。","rad":"禾","fq":"則歴切","vol":"07","py":"jī","duan":[{"e":"聚也。","n":"禾與粟皆得偁積。引伸爲凡聚之偁。淇奧詩叚簀爲積。"}]},"秩":{"expl":"積也。从禾失聲。《詩》曰：“䆅之秩秩。”","rad":"禾","fq":"直質切","vol":"07","py":"zhì","duan":[{"e":"積皃。","n":"皃各本作也。今正。積之必有次敘成文理。是曰秩。詩叚樂傳曰。秩秩、有常也。斯干傳曰。秩秩、流行也。巧言傳曰。秩秩、進知也。賓之初筵傳曰。秩秩然肅敬也。釋訓曰。條條、秩秩、智也。又曰。秩秩、淸也。皆引伸之義也。"}]},"稛":{"expl":"絭束也。从禾囷聲。","rad":"禾","fq":"苦本切","vol":"07","py":"kǔn","duan":[{"e":"絭束也。","n":"絭束謂以繩束之。國語。垂櫜而入。稇載而歸。韋注。稇、絭也。古亦叚麇爲之。如左傳羅無勇麇之、及潞麇之是也。方言。稇、就也。注。稇稇、成就皃。廣韵作成熟。葢禾熟而刈之。而絭束之。其義相因也。"}]},"稞":{"expl":"穀之善者。从禾果聲。一曰無皮穀。","rad":"禾","fq":"胡瓦切","vol":"07","py":"huà","duan":[{"e":"穀之善者。","n":"謂凡穀顆粒俱佳者。廣韵云。淨穀。"}]},"秳":{"expl":"舂𥻆不漬也。从禾𠯑聲。","rad":"禾","fq":"戶括切","vol":"07","py":"huó","duan":[{"e":"春粟不潰也。","n":"水部曰。潰、漏也。春粟不潰者、謂無散於臼外者也。葢春之用力重則或潰。用力輕則不。是曰？。今俗謂輕春曰桄。古曠切。卽？之轉語也。"}]},"𥝖":{"expl":"𥞸也。从禾气聲。","rad":"禾","fq":"居气切","vol":"07","py":"hé","duan":[{"e":"𥞸也。从禾。气聲。","n":"居气切。十五部。篇、韵皆下𣳚切。"}]},"稃":{"expl":"𥢶也。从禾孚聲。","rad":"禾","fq":"芳無切","vol":"07","py":"fū","duan":[{"e":"𥢶也。","n":"小徐本此篆與秠篆相屬。古本也。玉篇次苐正同。自淺人不知秠解而改竄之。乃又移易篆之次第矣。甫田箋曰。方、房也。謂孚甲始生而未合時也。古借孚爲稃。"}]},"𥢶":{"expl":"穅也。从禾會聲。","rad":"禾","fq":"苦會切","vol":"07","py":"kuài","duan":[{"e":"穅也。从禾。會聲。讀若裹。","n":"苦會切。十五部。玉篇公臥公外二切。公臥卽讀若裹之云。會聲而讀若裹者、合音也。"}]},"穅":{"expl":"榖皮也。从禾从米，庚聲。","rad":"禾","fq":"苦岡切","vol":"07","py":"kānɡ","duan":[{"e":"穀之皮也。","n":"云穀者、晐黍稷稻梁麥而言。穀猶粟也。今人謂巳脫於米者爲穅。古人不爾。穅之言空也。空其中以含米也。凡康寧、康樂皆本義空中之引伸。今字分別。乃以本義从禾。引伸義不从禾。"}]},"菻":{"expl":"蒿屬。从艸林聲。","rad":"艸","fq":"力稔切","vol":"01","py":"lǐn","duan":[{"e":"蒿屬。","n":"郭樸曰。莪蒿亦曰䕲蒿。按䕲同菻。許不言莪菻一物也。"}]},"䅵":{"expl":"禾皮也。从禾羔聲。","rad":"禾","fq":"之若切","vol":"07","py":"zhuó","duan":[{"e":"禾皮也。","n":"禾皮者、禾稿之皮也。吕氏春秋曰。得時之麥。薄䅵而赤色。本謂稿皮。因以𧦝䅌皮。羔聲勺聲古音同在二部。故䅵音灼。下文曰禾若秧穰、曰把取禾若。若卽䅵。今音相近。又改其字耳。"}]},"稭":{"expl":"禾稾去其皮，祭天以爲席。从禾皆聲。","rad":"禾","fq":"古黠切","vol":"07","py":"jiá","duan":[{"e":"禾稾去其皮。祭天㠯爲席也。","n":"禮器曰。莞簟之安而稾鞂之設。鄭注。穗去實曰鞂。引禹貢三百里納鞂服。禹貢釋文。秸本或作稭。然則稭秸鞂三形同。又或作䕸。亦同。謂禾莖旣刈之。上去其穗。外去其皮。存其淨莖。是曰稭。鄭云穗去實。猶云穎去穗也。穎謂莖之近穗者。鄭注禹貢云。銍謂刈穗𣃔去稾也。稭又去其穎也。是謂下𢧵爲稾。近穗爲穎。故三百里納秸者、不惟去稾。又去穎而納穗。其注禮器云。穗去實者。正謂去穗用近穗之穎。與許云稾去皮者少異。許云稾者、兼穎而言。言稾得兼穎。言穎不兼稾也。"}]},"稈":{"expl":"禾莖也。从禾旱聲。《春秋傳》曰：“或投一秉稈。”","rad":"禾","fq":"古旱切","vol":"07","py":"ɡǎn","duan":[{"e":"禾莖也。","n":"謂自根之上至貫於穗者是也。"}]},"稾":{"expl":"稈也。从禾高聲。","rad":"禾","fq":"古老切","vol":"07","py":"ɡǎo","duan":[{"e":"稈也。","n":"廣雅、左傳注皆云。秆、稾也。叚借爲矢榦之稾、屈平屬艸稾之稾。"}]},"秕":{"expl":"不成粟也。从禾比聲。","rad":"禾","fq":"卑履切","vol":"07","py":"bǐ","duan":[{"e":"不成粟也。","n":"按不成粟之字从禾。惡米之字从米。而皆比聲。此其別也。左傳。若其不具。用秕粺也。杜云。秕、穀不成者。僞古文云。若粟之有秕。吕覽云。凡禾之患。不俱生而俱死。是以先生者美米。後生者多秕。是故其耨也。長其兄而去其弟。按今俗𧦝穀之不充者曰？。補結切。卽秕之俗音俗字也。引伸之凡敗者曰秕。漢書曰。秕我王度。"}]},"䅌":{"expl":"麥莖也。从禾肙聲。","rad":"禾","fq":"古玄切","vol":"07","py":"juān","duan":[{"e":"麥莖也。","n":"麥莖光澤娟好。故曰䅌。一作？。潘岳射雉賦曰闚䦓？葉是。"}]},"𥞥":{"expl":"黍穰也。从禾𠛱聲。","rad":"禾","fq":"良薛切","vol":"07","py":"liè","duan":[{"e":"黍穰也。","n":"廣雅。黍穰謂之䅀。左傳。使巫以桃茢先祓殯。杜注云。茢黍穰。檀弓。以巫祝桃茢執戈。鄭注云。茢、萑苕。按二物皆可爲彗。二字可通用。故注不同。許說其本義也。詩生民。禾役穟穟。毛傳。役、列也。列葢？之叚借。禾穰亦得謂之？也。"}]},"穰":{"expl":"黍𥟜已治者。从禾襄聲。","rad":"禾","fq":"汝羊切","vol":"07","py":"ránɡ","duan":[{"e":"黍𥞥巳治者。","n":"巳治、謂巳治去其𥬡皮也。謂之穰者、莖在皮中如瓜瓤在瓜皮中也。周頌傳曰。穰穰、衆也。此叚借也。"}]},"秧":{"expl":"禾若秧穰也。从禾央聲。","rad":"禾","fq":"於良切","vol":"07","py":"yānɡ","duan":[{"e":"禾若秧穰也。","n":"若卽上文之䅵也。若者、擇菜也。擇菜者必去其邊皮。因之凡可去之皮曰若。竹皮亦曰？。漢書。印絫絫。綬若若。絫絫、重積也。若若、如蘀若之多也。秧穰曡韵字。集韵曰。禾下葉多也。今俗謂稻之初生者曰秧。凡艸木之幼可移栽者皆曰秧。此與古義別。"}]},"䅭":{"expl":"䅭䅣，穀名。从禾㫄聲。","rad":"禾","fq":"蒲庚切","vol":"07","py":"pánɡ","duan":[{"e":"䅭䅣。穀名。","n":"廣雅曰。䅭䅣、穄也。按許但云穀名。不與穄篆爲伍。則與張說異。"}]},"蔚":{"expl":"牡蒿也。从艸𤈫聲。","rad":"艸","fq":"於胃切","vol":"01","py":"wèi","duan":[{"e":"牡蒿也。","n":"小雅。匪莪伊蔚。釋艸、山傳皆云。牡菣。按牡菣猶牡蒿也。郭云。無子者。陸璣云。牡蒿、七月華。八月角。一名馬薪蒿。與郭異。名醫別錄有牡蒿一條。唐人注曰。齊頭蒿也。"}]},"䅣":{"expl":"䅭䅣也。从禾皇聲。","rad":"禾","fq":"戶光切","vol":"07","py":"huánɡ","duan":[{"e":"䅭䅣也。","n":"二字曡韵。"}]},"秊":{"expl":"穀孰也。从禾千聲。《春秋傳》曰：“大有秊。”","rad":"禾","fq":"奴顛切","vol":"07","py":"nián","duan":[{"e":"穀孰也。","n":"爾雅曰。夏曰歲。商曰祀。周曰年。唐虞曰載。年者、取禾一孰也。"}]},"穀":{"expl":"續也。百穀之緫名。从禾𣪊聲。","rad":"禾","fq":"古祿切","vol":"07","py":"ɡǔ","duan":[{"e":"續也。","n":"穀與粟同義。引伸爲善也。釋詁、毛傳皆曰。穀、善也。又大雅傳曰。穀、祿也。"}]},"稔":{"expl":"穀孰也。从禾念聲。《春秋傳》曰：“鮮不五稔。”","rad":"禾","fq":"而甚切","vol":"07","py":"rěn","duan":[{"e":"穀孰也。","n":"稔之言飪也。"}]},"租":{"expl":"田賦也。从禾且聲。","rad":"禾","fq":"則吾切","vol":"07","py":"zū","duan":[{"e":"田賦也。从禾。且聲。","n":"則吾切。五部。"}]},"稅":{"expl":"租也。从禾兌聲。","rad":"禾","fq":"輸芮切","vol":"07","py":"shuì","duan":[{"e":"租也。从禾。兌聲。","n":"輸芮切。十五部。"}]},"䆃":{"expl":"禾也。从禾道聲。司馬相如曰：“䆃，一莖六穗。”","rad":"禾","fq":"徒到切","vol":"07","py":"dào","duan":[{"e":"䆃米也。","n":"三字句。各本刪䆃字。改米爲禾。自吕氏字林、顔氏家訓時巳然。今正。䆃、擇也。擇米曰䆃米。漢人語如此。雅俗共知者。漢書百官表、後書殤帝和帝紀皆有䆃官。注皆云。䆃官主擇米。鄧后詔曰。減大官䆃官。自非共陵廟稻粱米。不得䆃擇。光武詔曰。郡國異味。有豫養䆃擇之勞。凡作導者譌字也。䆃米是常語。故以䆃米釋䆃篆。如河下云河水、巂下云巂周之比。淺人槩謂複字而刪之。又改米爲禾。吕忱、徐廣、顔之推、司馬貞皆執誤本說文。謂䆃是禾名。豈知䆃果禾名則許書之例當與？穆私三篆爲伍。而不廁於此。"}]},"𥡃":{"expl":"虛無食也。从禾荒聲。","rad":"禾","fq":"呼光切","vol":"07","py":"huānɡ","duan":[{"e":"虛無食也。","n":"爾雅。果不孰爲荒。周禮疏曰。疏穀皆不孰爲大荒。按荒年字當作𥡃。荒行而𥡃廢矣。"}]},"穌":{"expl":"把取禾若也。从禾魚聲。","rad":"禾","fq":"素孤切","vol":"07","py":"sū","duan":[{"e":"杷取禾若也。","n":"杷各本作把。今正。禾若散亂。杷而取之。不當言把也。離騷。蘇糞壤以充幃兮。謂申椒其不芳。王逸曰。蘇、取也。韓信傳曰。樵蘇後爨。師不宿飽。漢書音義曰。樵、取薪也。蘇、取草也。此皆假蘇爲穌也。蘇、桂荏也。蘇行而穌廢矣。樂記。蟄蟲昭蘇。注云。更息曰蘇。據玉篇云。穌、息也。死而更生也。然則希馮所據樂記作穌。"}]},"稍":{"expl":"出物有漸也。从禾肖聲。","rad":"禾","fq":"所教切","vol":"07","py":"shāo","duan":[{"e":"出物有漸也。","n":"漸依許當作？。漸行而？廢矣。稍之言小也、少也。凡古言稍稍者皆漸進之謂。周禮。稍食、祿稟也。云稍者、謂祿之小者也。"}]},"蕭":{"expl":"艾蒿也。从艸肅聲。","rad":"艸","fq":"蘇彫切","vol":"01","py":"xiāo","duan":[{"e":"艾蒿也。","n":"大雅。取蕭祭脂。郊特牲。焫蕭合馨香。故毛公曰。蕭所以共祭祀。鄭君曰。蕭、薌蒿也。陸璣曰。今人所謂萩蒿也。或云牛尾蒿。許愼以爲艾蒿。非也。按陸語非是。此物蒿類而似艾。一名艾蒿。許非謂艾爲蕭也。齊高帝云。蕭卽艾也。乃爲誤耳。○又按曹風傳曰。蕭、蒿也。此統言之。諸家云薌蒿艾蒿者、析言之。"}]},"秋":{"expl":"禾穀孰也。从禾，𤒅省聲。","rad":"禾","fq":"七由切","vol":"07","py":"qiū","duan":[{"e":"禾穀孰也。","n":"其時萬物皆老。而莫貴於禾穀。故从禾。言禾復言穀者、晐百穀也。禮記曰。西方者秋。秋之爲言揫也。"}]},"秦":{"expl":"伯益之後所封國。地宜禾。从禾，舂省。一曰秦，禾名。","rad":"禾","fq":"匠鄰切","vol":"07","py":"qín","duan":[{"e":"伯益之後所封國。","n":"鄭詩諩曰。秦者、隴西谷名。於禹貢近雍州鳥鼠之山。堯時有伯翳者。實臯陶之子。佐禹治水。水土旣平。舜命作虞官。掌上下草木鳥獸。賜姓曰嬴。歷夏商興衰。亦世有人焉。周孝王使其末孫非子養馬於汧渭之間。孝王封非子爲附庸。邑之於秦谷。至曾孫秦仲。宣王又命作大夫。始有車馬禮樂侍御之好。國人美之。秦之變風始作。按伯益、伯翳實一人。臯陶之子也。今甘肅秦州淸水縣有故秦城。漢地理志之隴西秦亭、秦谷也。"}]},"稱":{"expl":"銓也。从禾爯聲。春分而禾生。日夏至，晷景可度。禾有秒，秋分而秒定。律數：十二秒而當一分，十分而寸。其以爲重：十二粟爲一分，十二分爲一銖。故諸程品皆从禾。","rad":"禾","fq":"處陵切","vol":"07","py":"chēnɡ","duan":[{"e":"銓也。","n":"銓者、衡也。聲類曰。銓所以稱物也。稱俗作秤。按爾、幷舉也。偁、揚也。今皆用稱。稱行而爾偁廢矣。"}]},"科":{"expl":"程也。从禾从斗。斗者，量也。","rad":"禾","fq":"苦禾切","vol":"07","py":"kē","duan":[{"e":"程也。","n":"廣韵曰。程也。條也。本也。品也。又科、𣃔也。按實一義之引伸耳。論語曰。爲力不同科。孟子曰。盈科而後進。趙岐曰。科、坎也。按盈科爲盈等也。"}]},"程":{"expl":"品也。十髮爲程，十程爲分，十分爲寸。从禾呈聲。","rad":"禾","fq":"直貞切","vol":"07","py":"chénɡ","duan":[{"e":"程品也。","n":"大徐無程字。按此三字爲句。與䆃米也一例。淺人槩謂複字而刪之。品者、衆庶也。因衆庶而立之法則。斯謂之程品。上文言諸程品可證矣。荀卿曰。程者、物之準也。月令。陳祭器。按度程。注。程謂器所容也。漢書。張蒼定章程。如淳云。章、曆數之章術也。程者、權衡丈尺斗斛之平法也。"}]},"稯":{"expl":"布之八十縷爲稯。从禾㚇聲。","rad":"禾","fq":"子紅切","vol":"07","py":"zōnɡ","duan":[{"e":"布之八十縷爲稯。","n":"按此當有奪文。聘禮記曰。禾四秉曰筥。十筥曰稯。十稯曰秅。許下文五稯爲？。二？爲秅。正本記文。若先之曰布八十縷爲稯。則下文不爲四百縷爲？、八百縷爲秅乎。知其𣃔不然矣。葢必云。禾四十秉爲稯。从禾。㚇聲。一曰布之八十縷爲稯。轉寫奪漏而亂之耳。秉見又部。云禾把也。从又持禾。云四十秉爲稯。則上下相屬成文。鄭注周禮云。禾、稾實幷刈者也。秉、手把也。稯猶束也。國語。其歲。收田一井。出稯禾、秉芻、缶米。不是過也。稯禾謂禾四十秉。秉芻謂芻一把。韋注殊誤。布八十縷爲稯者。史記孝景本紀。令徒𨽻衣七稯布。索隱、正義皆云。葢七𦫵布用五百六十縷。漢書王莽傳。一月之祿。十緵布二匹。孟康云。緵、八十縷也。攷鄭注喪服曰。八十縷"}]},"秭":{"expl":"五稯爲秭。从禾𠂔聲。一曰數億至萬曰秭。","rad":"禾","fq":"將几切","vol":"07","py":"zǐ","duan":[{"e":"五稯爲秭。","n":"禾二百秉也。周禮掌客注有秅秭麻荅之文。秅秭連文。則非詩之秭也。謂五稯也。"}]},"秅":{"expl":"二秭爲秅。从禾乇聲。《周禮》曰：“二百四十斤爲秉。四秉曰筥，十筥曰稯，十稯曰秅，四百秉爲一秅。”","rad":"禾","fq":"宅加切","vol":"07","py":"chá","duan":[{"e":"二秭爲秅。","n":"禾四百秉也。周禮掌客曰。上公車禾眡死牢。牢十車。車三秅。注云。禾、？實幷刈者也。聘禮。四秉曰筥。十筥曰稯。十稯曰秅。每車三秅。則三十稯也。聘禮注云。一車之禾三秅。爲千二百秉、三百筥、三十稯也。○按小徐本作秭也。廣韵從之。是則秅卽秭、爲今數。二秭爲秅、爲古數也。小徐本非奪字。仍記於此。"}]},"䄷":{"expl":"百二十斤也。稻一䄷爲粟二十升，禾黍一䄷爲粟十六升大半升。从禾石聲。","rad":"禾","fq":"常隻切","vol":"07","py":"shí","duan":[{"e":"百二十斤也。","n":"律厤志曰。五權之制。銖者、物繇忽微至於成著。可殊異也。本起於黃鐘之重。一龠容千二百黍。重十二銖。兩者、兩黃鐘律之重也。二十四銖而成兩。斤者、明也。十六兩成斤。鈞者、均也。三十斤成鈞。石者、大也。權之大者也。四鈞爲石。古多叚石爲䄷。月令鈞衡石是也。有假䄷爲山石者。楚辭悲任䄷之何益是也。"}]},"稘":{"expl":"復其時也。从禾其聲。《虞書》曰：“稘三百有六旬。”","rad":"禾","fq":"居之切","vol":"07","py":"jī","duan":[{"e":"復其時也。","n":"言帀也。十二月帀爲期年。中庸一月帀爲期月。左傳旦至旦亦爲期。今皆假期爲之。期行而稘廢矣。"}]},"萩":{"expl":"蕭也。从艸秋聲。","rad":"艸","fq":"七由切","vol":"01","py":"qiū","duan":[{"e":"蕭也。从艸。秌聲。","n":"七由切。三部。古多以萩爲楸。如左氏傳伐雍門之萩、史漢河濟之閒千樹萩是也。"}]},"穩":{"expl":"蹂榖聚也。一曰安也。从禾，隱省。古通用安隱。","rad":"禾","fq":"烏本切","vol":"07","py":"wěn","duan":[]},"稕":{"expl":"束稈也。从禾𦎫聲。","rad":"禾","fq":"之閏切","vol":"07","py":"zhùn","duan":[]},"秝":{"expl":"稀疏適也。从二禾。凡秝之屬皆从秝。讀若歷。","rad":"秝","fq":"郎擊切","vol":"07","py":"lì","duan":[{"e":"稀疏適秝也。","n":"各本無秝字。今依江氏聲、王氏念孫說補。適秝。上音的。下音歷。曡韵字也。玉篇曰。稀疏厤厤然。葢凡言歷歷可數、歷錄束文皆當作秝。歷行而秝廢矣。周禮遂師。及窆抱磿。鄭云。磿者、適歷。執綍者名也。遂人主陳之。而遂師以名行挍之。賈公彦云。天子千人分布於六綍之上。稀疏得所。名爲適歷也。王氏念孫廣雅疏證云。子虚賦、七發、楊雄蜀都賦、南都賦、論衡譴告篇、嵇康聲無哀樂論皆云勺藥。伏儼、文穎、晉灼、李善皆說是調和之名。上丁削反。下旅酌反。勺藥之言適歷也。周禮注及說文皆云適歷。說文厤字下云治也。？字下云調也。凡均調謂之適歷。"}]},"兼":{"expl":"并也。从又持秝。兼持二禾，秉持一禾。","rad":"秝","fq":"古甜切","vol":"07","py":"jiān","duan":[{"e":"幷也。","n":"幷、相從也。"}]},"黍":{"expl":"禾屬而黏者也。以大暑而穜，故謂之黍。从禾，雨省聲。孔子曰：“黍可爲酒，禾入水也。”凡黍之屬皆从黍。","rad":"黍","fq":"舒呂切","vol":"07","py":"shǔ","duan":[{"e":"禾屬而黏者也。","n":"九穀攷曰。以禾況黍。謂黍爲禾屬而黏者。非謂禾爲黍屬而不黏者也。禾屬而黏者黍。禾屬而不黏者𪎭。對文異。散文則通偁黍。謂之禾屬。要之皆非禾也。今山西人無論黏與不黏統呼之曰𪎭黍。太原以東則呼黏者爲黍子。不黏者爲𪎭子。黍宜爲酒、爲羞籩之餌餈、爲酏粥。𪎭宜爲飯。禾黍稻稷各有黏不黏二種。按黍爲禾屬者。其米之大小相等也。其𥝩異。禾穗下垂如椎而粒聚。黍𥝩略如稻而舒散。"}]},"𪎭":{"expl":"穄也。从黍麻聲。","rad":"黍","fq":"靡爲切","vol":"07","py":"méi","duan":[{"e":"穄也。","n":"穄見禾部。𪎭、黍之不黏者。如稴爲稻之不黏者、稷爲秫之不黏者也。高注吕氏春秋曰。穄、關西謂之𪎭。冀州謂之䵖。九穀攷曰。特牲饋食禮。尸嘏主人有摶黍之儀。必是炊𪎭爲飯。不相黏著。故令佐食者摶之而後授尸。按周禮上訓注云。荆揚地宜稻。幽幷地宜麻。依李氏、聶氏皆忙皮反。則麻本作𪎭。九穀攷云。鄭據職方氏爲說也。幽州宜三種。幷州宜五種。內皆有黍。"}]},"𪐄":{"expl":"黍屬。从黍卑聲。","rad":"黍","fq":"并弭切","vol":"07","py":"bǐ","duan":[{"e":"黍屬也。","n":"禾之別爲稗。黍之屬爲𪐄。言別而屬見。言屬而別亦見。𪐄之於黍猶稗之於禾也。九穀攷曰。余目騐之。𥝩與穀皆如黍。農人謂之野稗。亦曰水稗。"}]},"黏":{"expl":"相箸也。从黍占聲。","rad":"黍","fq":"女廉切","vol":"07","py":"nián","duan":[{"e":"相箸也。","n":"有叚溓爲黏者。如攷工記雖有深泥亦弗之溓也是。"}]},"𪏻":{"expl":"黏也。从黍古聲。","rad":"黍","fq":"戶吳切","vol":"07","py":"hú","duan":[{"e":"黏也。从黍。古聲。","n":"戶吳切。五部。俗作糊。"}]},"䵒":{"expl":"黏也。从黍日聲。《春秋傳》曰：“不義不䵒。”","rad":"黍","fq":"尼質切","vol":"07","py":"nì","duan":[{"e":"黏也。从黍。日聲。","n":"尼質切。十二部。"}]},"芍":{"expl":"鳧茈也。从艸勺聲。","rad":"艸","fq":"胡了切","vol":"01","py":"xiào","duan":[{"e":"鳧茈也。","n":"見釋艸。今人謂之葧臍。卽鳧茈之轉語。郭樸云。苗似龍須。根可食。黑色。是也。廣雅云。葃姑、水芋、烏芋也。名醫別錄云。烏芋一名藉姑。一名水萍。藉與葃同音。萍必芋之誤。此專謂茨菰。不必因烏字牽合鳧茈也。茈徂咨切。"}]},"黎":{"expl":"履黏也。从黍，𥝢省聲。𥝢，古文利。作履黏以黍米。","rad":"黍","fq":"郎奚切","vol":"07","py":"lí","duan":[{"e":"履黏也。","n":"釋詁曰。黎、衆也。衆之義行而履黏之義廢矣。古亦以爲黧黑字。"}]},"䵗":{"expl":"治黍、禾、豆下潰葉。从黍畐聲。","rad":"黍","fq":"蒲北切","vol":"07","py":"bó","duan":[{"e":"治黍禾豆下潰葉也。","n":"潰葉菸𣨙。恐其傷穀。故必治之。治之者當以杷以鉏。此今農人所當知也。"}]},"香":{"expl":"芳也。从黍从甘。《春秋傳》曰：“黍稷馨香。”凡香之屬皆从香。","rad":"香","fq":"許良切","vol":"07","py":"xiānɡ","duan":[{"e":"芳也。","n":"艸部曰。芳、艸香也。芳謂艸。香則氾言之。大雅曰。其香始𦫵。"}]},"馨":{"expl":"香之遠聞者。从香殸聲。殸，籒文磬。","rad":"香","fq":"呼形切","vol":"07","py":"xīn","duan":[{"e":"𪏽之遠聞也。","n":"同大雅鳬鷖傳。按唐風椒𦕼一章曰。椒𦕼且。遠脩且。傳曰。脩、長也。二章。椒𦕼且。遠條且。傳曰。條言馨之遠聞也。今本前後章皆作條。則毛不應別爲傳矣。而足利古本尙可證。經言脩者、枝條之長。條者、芬香條鬯之謂。傳馨字今譌聲。"}]},"馥":{"expl":"香气芬馥也。从香复聲。","rad":"香","fq":"房六切","vol":"07","py":"fù","duan":[]},"米":{"expl":"粟實也。象禾實之形。凡米之屬皆从米。","rad":"米","fq":"莫禮切","vol":"07","py":"mǐ","duan":[{"e":"粟實也。","n":"𠧪部曰。粟、嘉穀實也。嘉穀者、禾黍也。實當作人。粟舉連秠者言之。米則秠中之人。如果實之有人也。果人之字古書皆作人。金刻本艸尙無作仁者。至明刻乃盡改爲仁。鄭注冢宰職。九穀不言粟。注倉人掌粟入之藏云。九穀盡藏焉。以粟爲主。粟正謂禾黍也。禾者、民食之大同。黍者、食之所貴。故皆曰嘉穀。其去秠存人曰米。因以爲凡穀人之名。是故禾黍曰米。稻稷麥苽亦曰米。舍人注所謂六米也。六米卽膳夫、食醫之食用六穀也。賓客之車米、筥米。喪紀之飯米。不外黍粱稻稷四者。凡穀必中有人而後謂之秀。故秀从禾人。"}]},"粱":{"expl":"米名也。从米，梁省聲。","rad":"米","fq":"呂張切","vol":"07","py":"liánɡ","duan":[{"e":"禾米也。","n":"各本作米名也。今正。古訓詁多不言某名。如毛傳但言水也、山也、艸也、木也皆是。上文粟與米皆兼禾黍言。粱則專爲禾米。故別言之。淺人不得其解。乃刪禾字矣。生曰苗。秀曰禾。？實幷刈曰禾。其實曰粟。粟中人曰米。米可食曰粱。禮經。簠陳稻粱。簋陳黍稷。聘禮。米百筥。設於中庭。十以爲列。黍粱稻皆二行。稷四行。內則。飯黍、稷、稻、粱、白黍、黃粱。食醫。六食。犬宜粱。喪大記。君用粱。大夫用稷。士用粱。凡黍稷稻之米無別名。禾之米則曰粱。自䊪以至於侍御皆粱也。小雅黃鳥。無啄我粟。兼禾黍言之。二章言粱。三章言黍。其目也。粟言連秠。粱黍言米。又其別也。"}]},"𥼚":{"expl":"早取穀也。从米焦聲。一曰小。","rad":"米","fq":"側角切","vol":"07","py":"zhuō","duan":[{"e":"早取穀也。","n":"內則稰穛注云。孰穫曰稰。生穫曰穛。正義曰。穛是斂縮之名。明以生穫。故其物縮斂也。按穛卽𥼚字。亦作穱。古爵與焦同音通用也。大招、七發皆云穱麥。王逸云。擇麥中先孰者也。大招以爲飯。七發以飤馬。吳都賦云。穱秀苽穗。廣韵云。穱者、稻處種麥。皆與早取之義合。凡早取穀皆得名穱。不獨麥也。"}]},"粲":{"expl":"稻重一䄷，爲粟二十斗，爲米十斗，曰毇；爲米六斗太半斗，曰粲。从米𣦼聲。","rad":"米","fq":"倉案切","vol":"07","py":"càn","duan":[{"e":"稻重一䄷。爲粟二十斗。","n":"見禾部。"}]},"䊪":{"expl":"粟重一䄷，爲十六斗太半斗，舂爲米一斛曰䊪。从米萬聲。","rad":"米","fq":"洛帶切","vol":"07","py":"lì","duan":[{"e":"粟重一䄷。爲十六斗大半斗。","n":"見禾部。不言禾黍者。粟本禾黍實之名。稻𧦝粟則借辭也。"}]},"𦺍":{"expl":"王彗也。从艸𣾅聲。","rad":"艸","fq":"昨先切","vol":"01","py":"jiǎn","duan":[{"e":"王彗也。","n":"釋艸字作葥。郭云。似藜可爲彗。按凡物呼王者皆謂大。"}]},"精":{"expl":"擇也。从米青聲。","rad":"米","fq":"子盈切","vol":"07","py":"jīnɡ","duan":[{"e":"擇米也。","n":"米字各本奪。今補。擇米謂䆃擇之米也。莊子人閒世曰。𡔷筴播精。司馬云。簡米曰精。簡卽柬。俗作揀者是也。引伸爲凡冣好之偁。撥雲霧而見靑天亦曰精。韓詩於定之方中云。星、精也。"}]},"粺":{"expl":"毇也。从米卑聲。","rad":"米","fq":"㫄卦切","vol":"07","py":"bài","duan":[{"e":"毇也。","n":"粺者、糲米一斛春爲九斗也。大雅。彼疏斯粺。傳云。彼宜食疏。今反食精粺。箋云。米之率糲十、粺九、鑿八、侍御七。按漢九章筭術云。糲米三十。粺米二十七。糳米二十四。御米二十一。卽鄭說所本。粺謂禾黍米。毇謂稻米。而可互偁。故以毇釋粺。"}]},"粗":{"expl":"疏也。从米且聲。","rad":"米","fq":"徂古切","vol":"07","py":"cū","duan":[{"e":"疏也。","n":"大雅。彼疏斯粺。箋云。疏、麤也。謂糲米也。麤卽粗。正與許書互相證。疏者、通也。引伸之猶大也。故粗米曰疏。糲米與粺米挍。則糲爲粗。稷與黍稻粱挍。則稷爲粗。九穀攷云。凡經言疏食者、稷食也。論語。疏食菜羹。卽玉藻之稷食菜羹。左傳。粱則無矣。麤則有之。麤對粱而言。稷之謂也。儀禮昏禮。婦饋舅姑。有黍無稷。特著其文。葢婦道成以孝養。不進疏食也。按引伸叚借之凡物不精者皆謂之粗。"}]},"䉾":{"expl":"惡米也。从米北聲。《周書》有《䉾誓》。","rad":"米","fq":"兵媚切","vol":"07","py":"bì","duan":[{"e":"惡米也。","n":"粟之不成者曰秕。米之惡者曰粊。其音同也。莊子。塵垢粃康。粃卽粊字。"}]},"糱":{"expl":"牙米也。从米辥聲。","rad":"米","fq":"魚列切","vol":"07","py":"niè","duan":[{"e":"牙米也。","n":"牙同芽。芽米者、生芽之米也。凡黍稷稻粱米巳出於穅者不牙。麥豆亦得云米。本無穅。故能芽。芽米謂之糵猶伐木餘謂之櫱、庶子謂之孼也。按許云芽米、葢容穀言之。散文則粟得偁米。月令。乃命大酋。秫稻必齊。？糵必時。注云。古者穫稻而漬米麴。至春而爲酒。按漬米、漬麴是二事。漬米卽大酋之糵也。此糵不必有芽。以凡穀漬之則有芽。故名漬米曰糵。"}]},"粒":{"expl":"糂也。从米立聲。","rad":"米","fq":"力入切","vol":"07","py":"lì","duan":[{"e":"糂也。","n":"按此當作米粒也。米粒是常語。故訓釋之例如此。與䆃篆下云䆃米也正同。玉篇、廣韵粒下皆云米粒。可證。淺人不得其解。乃妄改之。以與糂下一曰粒也相合。不知粒乃糂之別義。正謂米粒。如妄改之文。則粒爲以米和羹矣。而一曰粒也何解乎。今俗語謂米一顆曰一粒。孟子。樂歲粒米狼戾。趙注云。粒米、粟米之粒也。臯陶謨。烝民乃粒。周頌。立我烝民。鄭箋。立當作粒。詩書之粒皆王制所謂粒食。始食艱食、鱻食、至此乃粒食也。"}]},"𥼶":{"expl":"潰米也。从米睪聲。","rad":"米","fq":"施隻切","vol":"07","py":"shì","duan":[{"e":"漬米也。","n":"大雅曰。釋之叜叜。傳曰。釋、淅米也。叜叜、聲也。按漬米、淅米也。漬者初湛諸水。淅則淘汏之。大雅作釋。釋之叚借字也。"}]},"糂":{"expl":"以米和羹也。一曰粒也。从米甚聲。","rad":"米","fq":"桑感切","vol":"07","py":"sǎn","duan":[{"e":"㠯米和羹也。","n":"古之羹必和以米。墨子。藜羹不糂十日。吕覽作藜羹不斟。七日不粒。不斟正不糂之誤。內則注曰。凡羹齊宜五味之和。米屑之糝。"}]},"糪":{"expl":"炊，米者謂之糪。从米辟聲。","rad":"米","fq":"博戹切","vol":"07","py":"bò","duan":[{"e":"炊。","n":"句。"}]},"糜":{"expl":"糝也。从米麻聲。","rad":"米","fq":"靡爲切","vol":"07","py":"mí","duan":[{"e":"糝糜也。","n":"各本無糜字。淺人所刪。今補。以米和羹謂之糝。專用米粒爲之謂之糝。糜亦謂之鬻。亦謂之饘。食部曰。饘、糜也。釋名曰。糜、煑米使糜爛也。粥淖於糜。粥粥然也。引伸爲糜爛字。"}]},"蔿":{"expl":"艸也。从艸爲聲。","rad":"艸","fq":"于鬼切","vol":"01","py":"wěi","duan":[{"e":"艸也。","n":"晉有士蔿。楚有蔿姓。"}]},"䊤":{"expl":"糜和也。从米覃聲。讀若𨝸。","rad":"米","fq":"徒感切","vol":"07","py":"tán","duan":[{"e":"糜和也。","n":"糜和謂菜屬也。凡羹以米和之曰糝糜。或以菜和之曰䊤。"}]},"𥹆":{"expl":"潰米也。从米尼聲。交阯有𥹆泠縣。","rad":"米","fq":"武夷切","vol":"07","py":"mí","duan":[{"e":"潰米也。","n":"潰、屚也。謂米之棄於地者也。禾部曰。𥞸、舂粟不潰也。不抛散謂之不潰。"}]},"𥶶":{"expl":"酒母也。从米，𥷚省聲。","rad":"米","fq":"馳六切","vol":"07","py":"qū","duan":[{"e":"酒母也。从米。𥷤省聲。","n":"𥷤或作？。則亦可云？聲也。駈六切。三部。"}]},"糟":{"expl":"酒滓也。从米曹聲。","rad":"米","fq":"作曹切","vol":"07","py":"zāo","duan":[{"e":"酒滓也。","n":"內則曰。重醴。稻醴淸糟。黍醴淸糟。粱醴淸糟。注云。重、陪也。糟、醇也。淸、泲也。致飮有醇者。有泲者。陪飮之也。周禮酒正。共后之致飮於賓客之禮。醫酏糟。注云。糟、醫酏不泲者。泲曰淸。不泲曰糟。按今之酒但用泲者。直謂巳漉之粕爲糟。古則未泲帶滓之酒謂之糟。泛齊、醴齊、滓浮尤濁。盎齊、緹齊、沈齊、差淸。莊子音義、玄應書皆引許君淮南注曰。粕、巳漉粗糟也。然則糟謂未漉者。"}]},"𥼓":{"expl":"乾也。从米𤰈聲。","rad":"米","fq":"平祕切","vol":"07","py":"bèi","duan":[{"e":"乾飯也。","n":"飯字各本奪。今依李賢明帝紀注、隗嚻傳注、李善文𨕖注、玄應書補。乾音干。釋名曰。干飯、飯而㬥乾之也。周禮廩人注曰。行道曰糧。謂？也。止居曰食。謂米也。按干飯今多爲之者。"}]},"糗":{"expl":"𤎅米麥也。从米臭聲。","rad":"米","fq":"去九切","vol":"07","py":"qiǔ","duan":[{"e":"𤎅米麥也。","n":"周禮。羞籩之實。糗餌粉餈。鄭司農云。糗、𤎅大豆與米也。粉、豆屑也。玄謂糗者、擣粉𤎅大豆爲餌餈之黏著以坋之耳。按先鄭云。熬大豆及米。後鄭但云熬大豆。注內則又云。擣熬穀。不同者、黍粱尗麥皆可爲糗。故或言大豆以包米。或言穀以包米豆。而許云熬米麥。又非不可包大豆也。熬者、乾煎也。乾煎者、鬻也。鬻米豆舂爲粉。以坋餌餈之上。故曰糗餌粉餈。鄭云擣粉之。許但云熬。不云擣粉者、鄭釋經故釋粉字之義。許解字則糗但爲熬米麥。必待䊆之而後成粉也。粊誓。歭乃糗糧。某氏云。糗糒之糧。孟子曰。舜之飯糗茹草。趙云。糗、飯乾糒也。左傳爲稻醴、粱糗。廣韵曰。糗、乾飯屑也。此皆謂熬穀未粉者也。"}]},"䊆":{"expl":"舂糗也。从臼、米。","rad":"米","fq":"其九切","vol":"07","py":"jiù","duan":[{"e":"舂糗也。","n":"米麥巳熬。乃舂之而簁之成勃。鄭所謂擣粉也。而後可以施諸餌餈。"}]},"糈":{"expl":"糧也。从米胥聲。","rad":"米","fq":"私呂切","vol":"07","py":"xǔ","duan":[{"e":"糧也。","n":"凡糧皆曰糈。離騷王注曰。糈、精米。所以享神。其一耑耳。"}]},"糧":{"expl":"穀也。从米量聲。","rad":"米","fq":"呂張切","vol":"07","py":"liánɡ","duan":[{"e":"穀食也。","n":"周禮廩人。凡邦有會同師役之事。則治其糧與其食。鄭云。行道曰糧。按詩云。乃裹餱糧。莊子云。適百里者宿舂糧。適千里者三月聚糧。皆謂行道也。許云穀食。則兼居者行者言。糧本是統名。故不爲分析也。"}]},"粈":{"expl":"雜飯也。从米丑聲。","rad":"米","fq":"女久切","vol":"07","py":"róu","duan":[{"e":"襍飯也。","n":"食部曰。？、襍飯也。廣韵曰。？亦作粈。然則？粈一字。今之糅襍字也。"}]},"䒞":{"expl":"艸也。从艸冘聲。","rad":"艸","fq":"直深切","vol":"01","py":"chén","duan":[{"e":"艸也。","n":"此與䒞蕃各物。"}]},"䊮":{"expl":"穀也。从米翟聲。","rad":"米","fq":"他弔切","vol":"07","py":"dí","duan":[{"e":"穀也。","n":"䊮者、穀也。故？字从入䊮會意。楊雄蜀都賦。䊮米？䐗。言食穀米之？䐗也。轉寫作？米。誤矣。"}]},"𥽘":{"expl":"麩也。从米蔑聲。","rad":"米","fq":"莫撥切","vol":"07","py":"mò","duan":[{"e":"末也。","n":"末小徐本作䴲。據玉篇云。𥽘或作䴲。則𥽘䴲一字。大徐作麩。麩乃䴲之誤。汲古後人又依小徐改作䴲矣。今正作末。凡䊳而粉之曰末。麥部曰。麪、麥末也是也。麪專謂麥末。𥽘則統謂凡米之末。廣雅。𥽘謂之麪。此謂麪亦𥽘之一耳。𥽘者、自其細蔑言之。今之米粉、麪勃皆是。"}]},"粹":{"expl":"不雜也。从米卒聲。","rad":"米","fq":"雖遂切","vol":"07","py":"cuì","duan":[{"e":"不襍也。","n":"劉逵引班固云。不變曰醇。不襍曰粹。按粹本是精米之偁。引伸爲凡純美之偁。"}]},"氣":{"expl":"饋客芻米也。从米气聲。《春秋傳》曰：“齊人來氣諸矦。”","rad":"米","fq":"許旣切","vol":"07","py":"xì","duan":[{"e":"饋客之芻米也。","n":"聘禮殺曰饔。生曰餼。餼有牛羊豕黍粱稻稷禾薪芻等。不言牛羊豕者、以其字从米也。言芻米不言禾者、舉芻米可以該禾也。經典謂生物曰餼。論語。告朔之餼羊。"}]},"䉺":{"expl":"陳臭米也。从米工聲。","rad":"米","fq":"戶工切","vol":"07","py":"hónɡ","duan":[{"e":"陳臭米。","n":"賈捐之傳。太倉之粟。紅腐而不可食。師古曰。粟久腐壞。則色紅赤也。按紅卽䉺之叚借字。"}]},"粉":{"expl":"傅面者也。从米分聲。","rad":"米","fq":"方吻切","vol":"07","py":"fěn","duan":[{"e":"所以傅面者也。","n":"所㠯字舊奪。今補。小徐曰。古傅面亦用米粉。故齊民要術有傅面粉英。按據賈氏說。粉英僅堪妝摩身體耳。傅人面者固胡粉也。許所云傅面者、凡外曰面。周禮傅於餌餈之上者是也。引伸爲凡細末之偁。"}]},"䊎":{"expl":"粉也。从米卷聲。","rad":"米","fq":"去阮切","vol":"07","py":"quǎn","duan":[{"e":"粉也。从米。卷聲。","n":"去阮切。十四部。玉篇曰。？同。"}]},"䊝":{"expl":"𥻦也。从米悉聲。","rad":"米","fq":"私列切","vol":"07","py":"xiè","duan":[{"e":"䊝𥻦也。","n":"䊝𥻦雙聲字。今俗語尙如此。言之斂曰䊝。言之侈曰𥻦。皆單𧦝也。絫𧦝之曰䊝𥻦。"}]},"𥻦":{"expl":"䊝𥻦，𢿱之也。从米殺聲。","rad":"米","fq":"桑割切","vol":"07","py":"sà","duan":[{"e":"䊝𥻦、散之也。","n":"𥻦者複舉字。䊝者衍字。左傳正義兩引說文𥻦、散之也。可證。左傳昭元年曰。周公殺管叔而蔡蔡叔。釋文曰。上蔡字音素葛反。說文作𥻦。正義曰。說文𥻦爲放散之義。故訓爲放。隷書改作。巳失字體。𥻦字不可復識。寫者全類蔡字。至有爲一蔡字重㸃以讀之者。定四年正義同。是𥻦本謂散米。引伸之凡放散皆曰𥻦。字譌作蔡耳。亦省作殺。齊民要術凡云殺米者皆𥻦米也。孟子曰。殺三苗於三危。卽𥻦三苗也。"}]},"䊳":{"expl":"碎也。从米靡聲。","rad":"米","fq":"摸臥切","vol":"07","py":"mí","duan":[{"e":"碎也。","n":"石部云。碎、䊳也。二字互訓。王逸注離騷瓊爢云。爢、？也。爢卽䊳字。廣雅糜字二見。曰糜、饘也。與說文同。曰糜、糏也。卽說文之䊳碎也。糜與䊳音同義少別。凡言粉碎之義當作䊳。"}]},"蘜":{"expl":"治牆也。从艸鞠聲。","rad":"艸","fq":"居六切","vol":"01","py":"jú","duan":[{"e":"治牆也。","n":"未詳何物。集韵七之曰。菭蘠、艸名。"}]},"𥩓":{"expl":"盜自中出曰竊。从穴从米，𥜽、廿皆聲。廿，古文疾。𥜽，古文偰。","rad":"米","fq":"千結切","vol":"07","py":"qiè","duan":[{"e":"盜自中出曰竊。","n":"小徐曰。所謂亂在內爲宄也。按春秋曰。盜竊寶玉大弓。盜自中出也。虎部曰。竊、淺也。此於雙聲曡韵得之。"}]},"粻":{"expl":"食米也。从米長聲。","rad":"米","fq":"陟良切","vol":"07","py":"zhānɡ","duan":[]},"粕":{"expl":"糟粕，酒滓也。从米白聲。","rad":"米","fq":"匹各切","vol":"07","py":"pò","duan":[]},"粔":{"expl":"粔籹，膏環也。从米巨聲。","rad":"米","fq":"其呂切","vol":"07","py":"jù","duan":[]},"籹":{"expl":"粔籹也。从米女聲。","rad":"米","fq":"人渚切","vol":"07","py":"nǚ","duan":[]},"糉":{"expl":"蘆葉裹米也。从米㚇聲。","rad":"米","fq":"作弄切","vol":"07","py":"zònɡ","duan":[]},"糖":{"expl":"飴也。从米唐聲。","rad":"米","fq":"徒郎切","vol":"07","py":"tánɡ","duan":[]},"毇":{"expl":"米一斛舂爲八斗也。从䊆从殳。凡毇之屬皆从毇。","rad":"毇","fq":"許委切","vol":"07","py":"huǐ","duan":[{"e":"䊪米一斛舂爲九斗也。","n":"九斗各本譌八斗。糳下八斗各本譌九斗。今皆正。九章筭術曰。糲米率三十。粺米二十七。糳米二十四。御米二十一。毛詩鄭箋。米之率。糲十、粺九、糳八、侍御七。米部曰。粺、毇也。是則毇與粺皆一斛舂爲九斗明甚。毇見粲下。謂稻米也。稻米之始亦得云糲。此云糲米者、兼稻米、粟米言也。"}]},"糳":{"expl":"䊪米一斛舂爲九斗曰糳。从毇丵聲。","rad":"毇","fq":"則各切","vol":"07","py":"zuò","duan":[{"e":"䊪米一斛舂爲八斗曰糳。","n":"此䊪米亦兼粟米、稻米言也。詩生民召旻音義、左傳桓二年音義皆引字林糳子沃反。糲米一斛舂爲八斗也。與九章筭術、毛詩鄭箋皆合。然則許在張蒼之後、鄭吕之前。𣃔無乖、異。各本八斗譌九斗。繆誤顯然。經傳多叚鑿爲糳。"}]},"臼":{"expl":"舂也。古者掘地爲臼，其後穿木石。象形。中，米也。凡臼之屬皆从臼。","rad":"臼","fq":"其九切","vol":"07","py":"jiù","duan":[{"e":"舂臼也。","n":"各本無臼字。今補。杵下云。舂杵也。則此當云舂臼也明矣。引伸凡凹者曰臼。"}]},"祼":{"expl":"灌祭也。从示果聲。","rad":"示","fq":"古玩切","vol":"01","py":"ɡuàn","duan":[{"e":"灌祭也。","n":"詩毛傳曰。祼、灌鬯也。周禮注曰。祼之言灌。灌以鬱鬯。謂始獻尸求神時。周人先求諸陰也。"}]},"蘠":{"expl":"蘠靡，虋冬也。从艸牆聲。","rad":"艸","fq":"賤羊切","vol":"01","py":"qiánɡ","duan":[{"e":"蘠靡、","n":"逗。"}]},"舂":{"expl":"擣粟也。从廾持杵臨臼上。午，杵省也。古者雝父初作舂。","rad":"臼","fq":"書容切","vol":"07","py":"chōnɡ","duan":[{"e":"擣粟也。","n":"言粟以晐他穀。亦言粟以晐米。小徐本粟作米。周禮有舂人。廣雅曰。臿䑘昁䑗糳捶？？㯔䂿舂也。"}]},"𦥭":{"expl":"齊謂舂曰𦥭。从臼屰聲。讀若膊。","rad":"臼","fq":"匹各切","vol":"07","py":"pò","duan":[{"e":"齊謂舂曰𦥭。","n":"按廣雅獨不載此字。疑其臿卽𦥭之誤。而其㯔卽許之臿也。"}]},"臿":{"expl":"舂去麥皮也。从臼，干所以臿之。","rad":"臼","fq":"楚洽切","vol":"07","py":"chā","duan":[{"e":"舂去麥皮也。","n":"示部䄟下曰。讀若舂麥爲㯔之㯔。臿㯔古今字也。許於說解中用今字耳。周禮廩人。大祭祀則共其接盛。接卽臿之叚借。凡穀皆得云臿也。引伸爲凡刺入之偁。如農器刺地者曰鍫臿。"}]},"舀":{"expl":"抒臼也。从爪、臼。《詩》曰：“或簸或舀。”","rad":"臼","fq":"以沼切","vol":"07","py":"yǎo","duan":[{"e":"抒臼也。","n":"生民詩曰。或舂或揄。或簸或蹂。毛云。揄、抒臼也。然則揄者、舀之叚借字也。抒、挹也。旣舂之。乃於臼中挹出之。今人凡酌彼注此皆曰舀。其引伸之語也。"}]},"臽":{"expl":"小阱也。从人在臼上。","rad":"臼","fq":"戶𤟟切","vol":"07","py":"xiàn","duan":[{"e":"小阱也。","n":"阱者、陷也。臽謂阱之小者。"}]},"凶":{"expl":"惡也。象地穿交陷其中也。凡凶之屬皆从凶。","rad":"凶","fq":"許容切","vol":"07","py":"xiōnɡ","duan":[{"e":"惡也。","n":"凶者、吉之反。"}]},"兇":{"expl":"擾恐也。从人在凶下。《春秋傳》曰：“曹人兇懼。”","rad":"凶","fq":"許拱切","vol":"07","py":"xiōnɡ","duan":[{"e":"𢺕恐也。","n":"杜注左曰。兇、恐懼聲。"}]},"朩":{"expl":"分枲莖皮也。从屮，八象枲之皮莖也。凡朩之屬皆从朩。讀若髕。","rad":"朩","fq":"匹刃切","vol":"07","py":"pìn","duan":[{"e":"分枲莖皮也。","n":"謂分擘枲莖之皮也。"}]},"枲":{"expl":"麻也。从朩台聲。","rad":"朩","fq":"胥里切","vol":"07","py":"xǐ","duan":[{"e":"麻也。","n":"鍇本作麻子也。非。玉篇云。有子曰苴。無子曰枲。廣韵互易之。誤也。喪服傳曰。苴、麻之有蕡者也。牡麻者、枲麻也。艸部曰。萉、枲實也。萉者、蕡之本字。枲旣無實之牡麻。何以言枲實也。枲亦爲母麻、牡麻之大名。猶麻之爲大名也。芓者、母麻。一曰芓卽枲也。是苴可呼枲之證也。周禮但言枲以晐麻艸之物。九穀攷曰。閒傳曰。苴、惡貌也。斬衰貌若苴。齊衰貌若枲。以今日北方種麻事目驗之。牡麻俗呼花麻。夏至開花。所謂榮而不實謂之英者。花落卽拔而漚之。剝取其皮。是爲夏麻。夏麻之色白。苴麻俗呼子麻。夏至不作花而放勃。勃卽麻實。所謂不榮而實謂之秀者。八九月閒子熟則落。搖而取之。子盡乃刈。漚其皮而剝之。是爲秋麻。色靑而黯。不潔白。閒"}]},"𣏟":{"expl":"葩之總名也。𣏟之爲言微也，微纖爲功。象形。凡𣏟之屬皆从𣏟。","rad":"𣏟","fq":"匹卦切","vol":"07","py":"pài","duan":[{"e":"萉之總名也。","n":"各本萉作葩。字之誤也。與吕覽季冬紀注誤同。今正。艸部曰。萉、枲實也。𪎰、或萉字也。萉本謂麻實。因以爲苴麻之名。此句疑尙有奪字。當云治萉枲之總名。下文云麻、人所治也。可證。萉枲則合有實無實言之也。趙岐、劉熙注孟子妻辟纑皆云。緝績其麻曰辟。按辟音劈。今俗語緝麻析其絲曰劈。卽𣏟也。"}]},"芪":{"expl":"芪母也。从艸氏聲。","rad":"艸","fq":"常之切","vol":"01","py":"qí","duan":[{"e":"芪母也。","n":"三字一句。按前已有？、不與芪字爲伍。則說爾雅者謂？卽芪母。非許意也。"}]},"檾":{"expl":"枲屬。从𣏟，熒省。《詩》曰：“衣錦檾衣。”","rad":"𣏟","fq":"去穎切","vol":"07","py":"qǐnɡ","duan":[{"e":"枲屬。","n":"類枲而非枲。言屬而別見也。檾者、草名也。周禮典枲。掌布絲縷紵之麻草之物注云。草、葛䔛之屬。掌葛。徵草貢之材於澤農。注云。草貢出澤。䔛紵之屬。可緝績者。䔛卽檾字之異者。䔛紵出於澤。與葛出於山不同。又作顈。襍記。如三年之喪。則旣顈。其練祥皆行。鄭云。顈、草名。無葛之鄉。去麻則用顈。詩兩言褧衣。許於此偁檾衣。於衣部偁褧衣。而云褧、檾也。示反古。然則褧衣者、以檾所績爲之。葢士昏禮所謂景也。今之檾麻本草作莔麻。其皮不及枲麻之堅韌。今俗爲麤繩索多用之。"}]},"㪔":{"expl":"分離也。从攴从𣏟。𣏟，分㪔之意也。","rad":"𣏟","fq":"穌旰切","vol":"07","py":"sàn","duan":[{"e":"分離也。","n":"𢿱潸字以爲聲。𢿱行而𢽳廢矣。"}]},"麻":{"expl":"與𣏟同。人所治，在屋下。从广从𣏟。凡麻之屬皆从麻。","rad":"麻","fq":"莫遐切","vol":"07","py":"má","duan":[{"e":"枲也。","n":"麻與枲互訓。皆兼苴麻、牡麻言之。"}]},"䵈":{"expl":"未練治纑也。从麻後聲。","rad":"麻","fq":"空谷切","vol":"07","py":"kù","duan":[{"e":"未練治纑也。","n":"糸部曰。纑、布縷也。劉熙孟子注曰。緝績其麻曰辟。練絲曰纑。練絲謂取所緝之縷湅治之也。練者、湅也。湅者、𤄒也。汏諸水漂敝之也。已湅曰纑。未湅曰䵈。廣雅曰。䵈、綃也。綃是生絲未湅之縷。如生絲然。故曰綃也。如成國謂已湅曰練絲。"}]},"黀":{"expl":"麻䕸也。从麻取聲。","rad":"麻","fq":"側鳩切","vol":"07","py":"zōu","duan":[{"e":"麻䕸也。从麻。取聲。","n":"東方朔七諫曰。菎蕗襍於黀蒸。王注云。枲翮曰黀。煏竹曰篜。按䕸卽稭字之俗。黀麻䕸卽艸部之菆麻蒸。此部此篆葢淺人所增。側鳩切。四部。"}]},"𪎨":{"expl":"檾屬。从麻俞聲。","rad":"麻","fq":"度矦切","vol":"07","py":"tóu","duan":[{"e":"檾屬。","n":"檾爲枲類。𪎨又檾類也。廣韵引字書云。𪎨麻一絜也。"}]},"尗":{"expl":"豆也。象尗豆生之形也。凡尗之屬皆从尗。","rad":"尗","fq":"式竹切","vol":"07","py":"shú","duan":[{"e":"豆也。","n":"尗豆古今語。亦古今字。此以漢時語釋古語也。戰國策。韓地五穀所生。非麥而豆。民之所食。大抵豆飯藿羹。史記豆作菽。"}]},"敊":{"expl":"配鹽幽尗也。从尗支聲。","rad":"尗","fq":"是義切","vol":"07","py":"chǐ","duan":[{"e":"配鹽幽尗也。","n":"廣雅說飲食曰。寑、䤁、鬱、𠪮、幽也。幽與鬱同義。以豆鬱之。其味苦。招䰟曰。大苦鹹酸。辛甘行些。王云。大苦、豉也。辛謂椒薑也。甘謂飴密也。言取豉汁調和以椒薑鹹酢。和以飴蜜。則辛甘之味皆發而行也。釋名曰。豉、嗜也。五味調和。須之而成。乃可甘嗜。故齊人謂豉聲同嗜也。按齊民要術說作豉必室中溫煖。所謂幽尗也。云食徑作豉法。用鹽五升。所謂配鹽也。"}]},"耑":{"expl":"物初生之題也。上象生形，下象其根也。凡耑之屬皆从耑。","rad":"耑","fq":"多官切","vol":"07","py":"duān","duan":[{"e":"物初生之題也。","n":"題者、頟也。人體頟爲冣上。物之初見卽其頟也。古發端字作此。今則端行而耑廢。乃多用耑爲專矣。周禮。磬氏已下則摩其耑。耑之本義也。左傳。履端於始。假端爲耑也。"}]},"韭":{"expl":"菜名。一穜而久者，故謂之韭。象形，在一之上。一，地也。此與耑同意。凡韭之屬皆从韭。","rad":"韭","fq":"舉友切","vol":"07","py":"jiǔ","duan":[{"e":"韭菜也。","n":"三字一句。"}]},"菀":{"expl":"茈菀，出漢中房陵。从艸宛聲。","rad":"艸","fq":"於阮切","vol":"01","py":"wǎn","duan":[{"e":"茈菀。","n":"句。本艸經作紫菀。古紫通用茈。見上。唐本艸注云。白菀謂之女菀。急就篇。牡蒙甘艸菀藜蘆。師古曰。菀謂紫菀、女菀之屬也。"}]},"𩐌":{"expl":"齏也。从韭隊聲。","rad":"韭","fq":"徒對切","vol":"07","py":"duì","duan":[{"e":"韲也。","n":"廣雅。𩐌、𦯓也。"}]},"䪢":{"expl":"墜也。从韭，次、𠂔皆聲。","rad":"韭","fq":"祖雞切","vol":"07","py":"jī","duan":[{"e":"𩐌也。","n":"周禮醢人。王舉則共醢六十罋。以五齊七醢七菹三臡實之。注。齊當爲齏。凡醢醬所和。細切爲齏。全物若䐑爲菹。王氏念孫曰。䪣者、細碎之名。莊子言䪣粉是也。按艸部曰。菹、酢菜也。酢菜之細切者曰䪣。通俗文曰。淹韭曰䪠。淹薤曰𩐌。葢其名起於淹韭、淹䪥。故从韭。"}]},"䪥":{"expl":"菜也。葉似韭。从韭㕢聲。","rad":"韭","fq":"胡戒切","vol":"07","py":"xiè","duan":[{"e":"䪥菜也。","n":"內則多言䪥。釋草曰。䪥鴻薈。"}]},"韱":{"expl":"山韭也。从韭㦰聲。","rad":"韭","fq":"息廉切","vol":"07","py":"xiān","duan":[{"e":"山韭也。","n":"山韭謂山中自生者。按夏小正。正月囿有韭、與四月囿有見杏皆謂自生者也。釋草作蒮、山韭。蒮見艸部。不云山韭。然則許所據爾雅作韱、山韭與。"}]},"䪤":{"expl":"小蒜也。从韭番聲。","rad":"韭","fq":"附袁切","vol":"07","py":"fán","duan":[{"e":"小蒜。","n":"艸部曰。蒜、葷菜也。南都賦曰。其園圃則有藷蔗薑䪤。李善引字書。䪤、小蒜也。玉篇、廣韵皆云。百合蒜也。按卽齊民要術所云百子蒜。"}]},"瓜":{"expl":"㼌也。象形。凡瓜之屬皆从瓜。","rad":"瓜","fq":"古華切","vol":"07","py":"ɡuā","duan":[{"e":"蓏也。","n":"蓏大徐作㼌。誤。艸部曰。在木曰果。在地曰蓏。瓜者、縢生布於地者也。"}]},"㼎":{"expl":"小瓜也。从瓜交聲。","rad":"瓜","fq":"蒲角切","vol":"07","py":"bó","duan":[{"e":"小瓜也。","n":"謂有一種小瓜名㼎。一名瓞。"}]},"瓞":{"expl":"㼎也。从瓜失聲。《詩》曰：“緜緜瓜瓞。”","rad":"瓜","fq":"徒結切","vol":"07","py":"dié","duan":[{"e":"㼎也。","n":"釋草曰。瓞瓝、其紹瓞。按瓞瓝者、一種艸結小瓜名瓞。卽瓝瓜也。云其紹瓞者、瓝瓜之近本繼先嵗之實謂之瓞也。上云瓞瓝渾言之。此析言之也。大雅。緜緜瓜瓞。傳云。瓜瓞、瓜紹也。瓞、瓝也。今本傳奪瓜瓞二字。乃不可讀矣。云瓜瓞、瓜紹也者、言瓜之近本繼先嵗之實必小。如瓝瓜之近本繼先嵗之實亦小。故亦謂之瓞也。瓜紹不云瓞。以瓝紹之名名之。故曰瓜瓞。又引爾雅瓞瓝說其本義也。毛傳襲爾雅而文義不同。詩言瓜瓞者、興其先小後大。陸氏佃曰。今驗近本之瓜常小。末則復大。戴先生謂於詩意物理皆得之。"}]},"𤬐":{"expl":"小瓜也。从瓜，熒省聲。","rad":"瓜","fq":"戶扃切","vol":"07","py":"xínɡ","duan":[{"e":"小瓜也。","n":"亦一種小瓜之名。齊民要術引作小瓜瓞也。"}]},"𤬖":{"expl":"瓜也。从瓜，繇省聲。","rad":"瓜","fq":"余昭切","vol":"07","py":"yáo","duan":[{"e":"瓜也。","n":"有瓜名𤬖也。"}]},"莔":{"expl":"貝母也。从艸，明省聲。","rad":"艸","fq":"武庚切","vol":"01","py":"ménɡ","duan":[{"e":"貝母也。","n":"詩。言采其蝱。毛傳曰。蝱、貝母。釋艸、說文作莔。莔正字。蝱假借字也。根下子如聚小貝。韵㑹引作貝母艸、療蛇毒六字。"}]},"瓣":{"expl":"瓜中實。从瓜辡聲。","rad":"瓜","fq":"蒲莧切","vol":"07","py":"bàn","duan":[{"e":"瓜中實也。","n":"衞風。齒如瓠棲。釋草及毛傳曰。瓠棲、瓠瓣也。瓜中之實曰瓣。實中之可食者當曰人。如桃杏之人。"}]},"㼌":{"expl":"本不勝末，微弱也。从二瓜。讀若庾。","rad":"瓜","fq":"以主切","vol":"07","py":"yǔ","duan":[{"e":"本不勝末。微弱也。从二瓜。","n":"本者、蔓也。末者、瓜也。蔓一而瓜多。則本微弱矣。故污窬之窳、惰嬾之窳皆从此。"}]},"瓠":{"expl":"匏也。从瓜夸聲。凡瓠之屬皆从瓠。","rad":"瓠","fq":"胡誤切","vol":"07","py":"hù","duan":[{"e":"匏也。","n":"包部曰。匏、瓠也。二篆左右轉注。七月傳曰。壼、瓠也。此謂叚借也。"}]},"瓢":{"expl":"蠡也。从瓠省，㶾聲。","rad":"瓠","fq":"符宵切","vol":"07","py":"piáo","duan":[{"e":"蠡也。","n":"蠡者、𧯷也。豆部曰。𧯷者、蠡也。以一瓠劙爲二曰瓢。亦曰蠡。亦曰𧯷。蠡一作㼖。見九歎、方言。一作盠。見皇象書急就碑本。其作蠡者、見周禮鬯人注、漢書東方朔傳。詳豆部。"}]},"宀":{"expl":"交覆深屋也。象形。凡宀之屬皆从宀。","rad":"宀","fq":"武延切","vol":"07","py":"mián","duan":[{"e":"交覆𥥍屋也。","n":"古者屋四注。東西與南北皆交覆也。有堂有室是爲深屋。自部𦤝下曰。宀宀、不見也。是則宀宀謂深也。"}]},"家":{"expl":"居也。从宀，豭省聲。","rad":"宀","fq":"古牙切","vol":"07","py":"jiā","duan":[{"e":"凥也。","n":"凥各本作居。今正。凥、處也。處、止也。釋宫。牖戸之閒謂之扆。其內謂之家。引伸之天子諸侯曰國。大夫曰家。凡古曰家人者、猶今曰人家也。家人字見哀四年左傳、夏小正傳及史記、漢書。家凥曡韵。"}]},"宅":{"expl":"所託也。从宀乇聲。","rad":"宀","fq":"場伯切","vol":"07","py":"zhái","duan":[{"e":"人所託凥也。","n":"依御覽補字。託者、寄也。人部亦曰。侂、寄也。引伸之凡物所安皆曰宅。宅託曡韵。釋名曰。宅、擇也。擇揀吉處而營之。"}]},"室":{"expl":"實也。从宀从至。至，所止也。","rad":"宀","fq":"式質切","vol":"07","py":"shì","duan":[{"e":"實也。","n":"以曡韵爲訓。古者前堂後室。釋名曰。室、實也。人物實滿其中也。引伸之則凡所居皆曰室。釋宮曰。宫謂之室、室謂之宫是也。"}]},"宣":{"expl":"天子宣室也。从宀𠄢聲。","rad":"宀","fq":"須緣切","vol":"07","py":"xuān","duan":[{"e":"天子宣室也。","n":"葢謂大室。如璧大謂之瑄也。賈誼傳。孝文受釐坐宣室。蘇林曰。宣室、未央前正室也。天子宣室。葢禮家相傳古語。引伸爲布也。明也。徧也。通也。緩也。散也。"}]},"向":{"expl":"北出牖也。从宀从口。《詩》曰：“塞向墐戶。”","rad":"宀","fq":"許諒切","vol":"07","py":"xiànɡ","duan":[{"e":"北出牖也。","n":"豳風。塞向墐戸。毛曰。向北出牖也。按士虞禮。祝啓牖鄉。注云。鄉、牖一名。明堂位達鄉注云。鄉、牖屬。是渾言不別。毛公以在冬曰可塞。故定爲北出者。引伸爲向背字。經傳皆假鄉爲之。"}]},"𦬸":{"expl":"山薊也。从艸术聲。","rad":"艸","fq":"直律切","vol":"01","py":"zhú","duan":[{"e":"山薊也。","n":"見釋艸、本艸經。"}]},"宧":{"expl":"養也。室之東北隅，食所居。从宀𦣞聲。","rad":"宀","fq":"與之切","vol":"07","py":"yí","duan":[{"e":"養也。","n":"以雙聲爲訓。周易賾卦亦訓爲養。釋詁曰。頤、養也。"}]},"𡧮":{"expl":"戶樞聲也。室之東南隅。从宀㫐聲。","rad":"宀","fq":"烏皎切","vol":"07","py":"yǎo","duan":[{"e":"戶樞聲也。室之東南隅。","n":"二句一義。古者戸東牖西。故以戸樞聲名東南隅也。釋宫曰。東南隅謂之𡧮。按釋名曰。㝔、幽也。非許意。許𡧮䆞義殊。爾雅釋文引說文。䆞深皃。誤以䆞爲𡧮也。"}]},"奥":{"expl":"宛也。室之西南隅。从宀𢍏聲。","rad":"宀","fq":"烏到切","vol":"07","py":"ào","duan":[{"e":"宛也。","n":"宛奧雙聲。宛者、委曲也。室之西南隅。宛然深藏。室之尊處也。"}]},"宛":{"expl":"屈草自覆也。从宀夗聲。","rad":"宀","fq":"於阮切","vol":"07","py":"wǎn","duan":[{"e":"屈艸自覆也。","n":"上文曰奥、宛也。宛之引伸義也。此曰屈艸自覆者、宛之本義也。引伸爲宛曲、宛轉。如爾雅宛中宛丘、周禮琬圭皆宛曲之義也。凡狀皃可見者皆曰宛然。如魏風傳曰宛辟皃、唐風傳曰宛死皃、攷工記注惌小孔皃皆是。宛與薀。薀與？。聲義皆通。故方言曰宛蓄也、禮記曰兔爲宛脾、春秋䋣露曰鶴無宛氣皆是。"}]},"宸":{"expl":"屋宇也。从宀辰聲。","rad":"宀","fq":"植鄰切","vol":"07","py":"chén","duan":[{"e":"屋宇也。","n":"屋者、以宫室上覆言之。宸謂屋邊。故古書言柍桭者、卽楝宇也。甘泉賦。日月纔經於柍桭。伏虔曰。柍、中央也。桭、屋梠也。魏都賦。旅楹閑列。暉鑒柍桭。張載曰。柍、中央也。桭、宇檼也。是知柍桭卽上棟下宇之謂。柍卽央字。桭卽宸字。西京賦。消氛埃於中宸。集重陽之精微。中宸卽柍桭。韋昭注國語云。宸、屋𩅸也。宇、邊也。若玉篇引賈逵云宸屋之奧者、當亦是國語注。而其說異矣。"}]},"宇":{"expl":"屋邊也。从宀于聲。《易》曰：“上棟下宇。”","rad":"宀","fq":"王榘切","vol":"07","py":"yǔ","duan":[{"e":"屋邊也。","n":"幽風。八月在宇。陸德明曰。屋四垂爲宇。引韓詩宇、屋𩅸也。高誘注淮南曰。宇、屋簷也。引伸之凡邊謂之宇。如輪人爲葢上欲尊而宇欲卑、左傳云在君之字下、又云失其守宇皆是也。宇者、言其邊。故引伸之義又爲大。文子及三蒼云。上下四方謂之宇。往古來今謂之宙。上下四方者、大之所際也。莊子云。有實而無乎處者、宇也。有長而無本剽者、宙也。有實而無乎處、謂四方上下實有所際。而所際之處不可得到。"}]},"寷":{"expl":"大屋也。从宀豐聲。《易》曰：“寷其屋。”","rad":"宀","fq":"敷戎切","vol":"07","py":"fēnɡ","duan":[{"e":"大屋也。从宀。豐聲。","n":"此以形聲包會意。當云从宀豐、豐亦聲也。敷戎切。九部。"}]},"寏":{"expl":"周垣也。从宀奐聲。","rad":"宀","fq":"胡官切","vol":"07","py":"huán","duan":[{"e":"周垣也。","n":"寏之言完也。西京賦曰。鐐亙綿聯。四百餘裏。薛注曰。苑之周圍也。善曰。西都賦之繚以周牆也。"}]},"宏":{"expl":"屋深響也。从宀厷聲。","rad":"宀","fq":"戶萌切","vol":"07","py":"hónɡ","duan":[{"e":"屋𥥍也。","n":"各本深下衍響字。此因下文屋響而誤。今依韵會、集韵、類篇正。大小徐本皆不誤也。或曰厷弘本一聲。谷部曰。𧮯、谷中響也。弓部曰。弘、弓聲也。水部曰。泓、下深大也。參伍求之。葢宏訓屋深響。宖其重文。愚按此說近是。但江賦以泓汯成文。不妨宏宖各字也。屋深者、其內深廣也。法言曰。其中弘深。其外肅括。此宏字之義。假弘爲宏耳。攷工記。其聲大而宏。大而宏者、其聲外大而中宏也。月令。其器圜以閎。鄭云。閎謂中寬。象土含物。圜以閎、吕氏春秋作圜以揜。葢宏者深廣其中。揜其外。故禮記、吕覽可互相足。揜者、斂也。閎亦宏之叚借字。"}]},"宖":{"expl":"屋響也。从宀弘聲。","rad":"宀","fq":"戶萌切","vol":"07","py":"hónɡ","duan":[{"e":"屋響也。","n":"長門賦曰。擠玉戸以撼金鋪兮。聲噌吰而似鐘音。甘泉賦。帷弸彋其拂汩兮。稍暗暗而靚深。皆屋響之意。魯靈光殿賦曰。隱陰夏以中處。宖寥窲以崢嶸。今文選宖字皆誤。惟韵會所據不誤。"}]},"蓂":{"expl":"析蓂，大薺也。从艸冥聲。","rad":"艸","fq":"莫歴切","vol":"01","py":"mì","duan":[{"e":"析蓂、","n":"二字逗。"}]},"寪":{"expl":"屋皃。从宀爲聲。","rad":"宀","fq":"韋委切","vol":"07","py":"wěi","duan":[{"e":"屋皃。","n":"王逸注招隱士曰。崎嶇閜寪。"}]},"㝩":{"expl":"屋㝩㝗也。从宀康聲。","rad":"宀","fq":"苦岡切","vol":"07","py":"kānɡ","duan":[{"e":"屋㝩㝗也。","n":"方言。㝩、空也。郭注。漮㝗、空皃。"}]},"㝗":{"expl":"㝩也。从宀良聲。","rad":"宀","fq":"良","vol":"07","py":"lánɡ","duan":[{"e":"㝩㝗也。","n":"各本刪㝗字。今補。㝩㝗以疊韵成文。"}]},"宬":{"expl":"屋所容受也。从宀成聲。","rad":"宀","fq":"氏征切","vol":"07","py":"chénɡ","duan":[{"e":"屋所容受也。","n":"宬之言盛也。廣韵無所字。"}]},"寍":{"expl":"安也。从宀，心在皿上。人之飲食器，所以安人。","rad":"宀","fq":"奴丁切","vol":"07","py":"nínɡ","duan":[{"e":"安也。","n":"此安寧正字。今則寧行而寍廢矣。僞古文。萬邦咸寍。音義曰。寍、安也。說文安寧字如此。寧、願詞也。語甚分明。自衛包改正文。李昉、陳鄂又改釋文。今人不可讀矣。"}]},"定":{"expl":"安也。从宀从正。","rad":"宀","fq":"徒徑切","vol":"07","py":"dìnɡ","duan":[{"e":"安也。","n":"古亦叚奠字爲之。"}]},"寔":{"expl":"止也。从宀是聲。","rad":"宀","fq":"常隻切","vol":"07","py":"shí","duan":[{"e":"正也。","n":"正各本作止。今正。召南毛傳曰。寔、是也。韓奕鄭箋亦曰。寔、是也。春秋桓六年。寔來。公羊傳曰。寔來者何。猶云是人來也。穀梁傳曰。寔來者、是來也。按許云正者、是也。然則正與是互訓。寔與是音義皆同。此云寔、正也。卽公、穀、毛、鄭之寔、是也。詩。湜湜其止。鄭箋尙以持正釋湜。而古多有以實爲寔者。韓詩。實命不猶。卽寔命不猶也。大雅韓奕。實墉實壑。卽寔墉寔壑也。周語。咨於故實。卽故寔。故韋云故事之是者也。實寔音義皆殊。由趙魏之閒實寔同聲。故相叚借耳。若杜預注春秋寔來曰寔、實也。則非是也。"}]},"安":{"expl":"靜也。从女在宀下。","rad":"宀","fq":"烏寒切","vol":"07","py":"ān","duan":[{"e":"竫也。","n":"竫各本作靜。今正。立部曰。竫者、亭安也。與此爲轉注。靑部靜者、審也。非其義。方言曰。安、靜也。以許書律之。叚靜爲竫耳。安亦用爲語詞。"}]},"宓":{"expl":"安也。从宀必聲。","rad":"宀","fq":"美畢切","vol":"07","py":"mì","duan":[{"e":"安也。","n":"此字經典作密。密行而宓廢矣。大雅。止旅乃密。傳曰。密、安也。正義曰。釋詁曰。密、康、靜也。康、安也。轉以相訓。是密得爲安。按上林賦宓汨、去疾也。義似異而實同。孔子弟子子賤姓宓。"}]},"㝣":{"expl":"靜也。从宀契聲。","rad":"宀","fq":"於計切","vol":"07","py":"yì","duan":[{"e":"竫也。","n":"玉篇引蒼頡篇云。安也。"}]},"菋":{"expl":"荎藸也。从艸味聲。","rad":"艸","fq":"无沸切","vol":"01","py":"wèi","duan":[{"e":"荎藸也。","n":"見釋艸。郭云。五味也。"}]},"宴":{"expl":"安也。从宀妟聲。","rad":"宀","fq":"於甸切","vol":"07","py":"yàn","duan":[{"e":"安也。","n":"引伸爲宴饗。經典多叚燕爲之。"}]},"𡧯":{"expl":"無人聲。从宀尗聲。","rad":"宀","fq":"前厯切","vol":"07","py":"jì","duan":[{"e":"無人聲也。从宀。尗聲。","n":"前歷切。古音在三部。口部作？。𡧯今字作寂。方言作？。云靜也。江湘九嶷之郊謂之？。"}]},"察":{"expl":"覆也。从宀、祭。","rad":"宀","fq":"初八切","vol":"07","py":"chá","duan":[{"e":"覆審也。","n":"？部云。？、覆也。覈、从？敫聲。實也。攷事？笮邀遮其辭得實曰覈。然則察與覈同意。釋訓曰。明明、斤斤、察也。"}]},"寴":{"expl":"至也。从宀親聲。","rad":"宀","fq":"初僅切","vol":"07","py":"qīn","duan":[{"e":"至也。","n":"至者、親密無閒之意。見部曰。親者、至也。然則寴與親音義皆同。故秦碑以寴䡅爲親巡。廣韵眞韵曰。寴古文親也。震韵曰。寴、屋空皃。此今義。非古義。凡廣韵之例。今義與說文義異者、必先舉今義而後偁說文。故震韵先云屋空皃。而後云說文至也。"}]},"完":{"expl":"全也。从宀元聲。古文以爲寬字。","rad":"宀","fq":"胡官切","vol":"07","py":"wán","duan":[{"e":"全也。","n":"入部全作仝。仝、完也。是二字互訓。"}]},"富":{"expl":"備也。一曰厚也。从宀畐聲。","rad":"宀","fq":"方副切","vol":"07","py":"fù","duan":[{"e":"僃也。","n":"富與福音義皆同。釋名曰。福、富也。"}]},"實":{"expl":"富也。从宀从貫。貫，貨貝也。","rad":"宀","fq":"神質切","vol":"07","py":"shí","duan":[{"e":"富也。","n":"引伸之爲艸木之實。"}]},"𡧖":{"expl":"藏也。从宀𡥀聲。𡥀，古文𠈃。《周書》曰：“陳𡧖赤刀。”","rad":"宀","fq":"博袌切","vol":"07","py":"bǎo","duan":[{"e":"藏也。","n":"藏當作臧。宲與保音同義近。"}]},"容":{"expl":"盛也。从宀、谷。","rad":"宀","fq":"余封切","vol":"07","py":"rónɡ","duan":[{"e":"盛也。","n":"今字叚借爲頌皃之頌。"}]},"宂":{"expl":"㪔也。从宀，人在屋下，無田事。《周書》曰：“宮中之穴食。”","rad":"宀","fq":"而隴切","vol":"07","py":"rǒnɡ","duan":[{"e":"𢽳也。从宀儿。","n":"各本奪儿。今補。儿卽人也。會意。而隴切。九部。"}]},"荎":{"expl":"荎藸，艸也。从艸至聲。","rad":"艸","fq":"直尼切","vol":"01","py":"chí","duan":[{"e":"荎藸艸也。","n":"四字句。釋艸有味荎藸。釋木有味荎著。實一物也。春初生苗。引赤蔓於高木。長六七尺。故又入釋木。"}]},"𡫛":{"expl":"𦤝𦤝，不見也。一曰𦤝𦤝，不見省人。从宀𦤝聲。","rad":"宀","fq":"武延切","vol":"07","py":"mián","duan":[{"e":"㝰㝰不見也。","n":"㝰與臱音義皆同。毛詩綿綿。韓詩作民民。按綿綿、民民皆謂密也。卽㝰㝰不見之意。莊子。窅然喪其天下焉。郭象音武騈反。是郭本作㝰然也。"}]},"寶":{"expl":"珍也。从宀从王从貝，缶聲。","rad":"宀","fq":"博皓切","vol":"07","py":"bǎo","duan":[{"e":"珍也。","n":"玉部曰。珍、寶也。二字互訓。史記多假葆爲寶。"}]},"宭":{"expl":"羣居也。从宀君聲。","rad":"宀","fq":"渠云切","vol":"07","py":"qún","duan":[{"e":"羣凥也。","n":"以曡韵爲訓。論語曰。羣居終日。"}]},"宦":{"expl":"仕也。从宀从臣。","rad":"宀","fq":"胡慣切","vol":"07","py":"huàn","duan":[{"e":"仕也。","n":"人部曰。仕者、學也。左傳。宦三年矣。服虔云。宦、學也。曲禮。宦學事師。注云。宦、仕也。熊氏云。宦謂學官事。學謂習六藝。二者俱是事師。襍記。宦於大夫。左傳。妾爲宦女。按仕者、習所事也。古事士仕通用。貫宦通用。故魏風三歲貫女。魯詩作宦女。"}]},"宰":{"expl":"辠人在屋下執事者。从宀从辛。辛，辠也。","rad":"宀","fq":"作亥切","vol":"07","py":"zǎi","duan":[{"e":"辠人在屋下執事者。","n":"此宰之本義也。引伸爲宰制。"}]},"守":{"expl":"守官也。从宀从寸。寺府之事者。从寸。寸，法度也。","rad":"宀","fq":"書九切","vol":"07","py":"shǒu","duan":[{"e":"守官也。","n":"左傳曰。守道不如守官。孟子曰。有官守者。不得其職則去。"}]},"寵":{"expl":"尊居也。从宀龍聲。","rad":"宀","fq":"丑壟切","vol":"07","py":"chǒnɡ","duan":[{"e":"尊凥也。","n":"引伸爲榮竉。"}]},"宥":{"expl":"寬也。从宀有聲。","rad":"宀","fq":"于救切","vol":"07","py":"yòu","duan":[{"e":"寬也。","n":"周頌。夙夜基命宥密。叔向、毛公皆曰。宥、寬也。宥爲寬。故貰罪曰宥。周禮大司樂假宥爲侑。王制假又爲宥。"}]},"宐":{"expl":"所安也。从宀之下，一之上，多省聲。","rad":"宀","fq":"魚羈切","vol":"07","py":"yí","duan":[{"e":"所安也。","n":"周南。宜其室家。傳曰。宜以有室家無踰時者。"}]},"寫":{"expl":"置物也。从宀舄聲。","rad":"宀","fq":"悉也切","vol":"07","py":"xiě","duan":[{"e":"置物也。","n":"謂去此注彼也。曲禮曰。器之漑者不寫。其餘皆寫。注云。寫者、傳己器中乃食之也。小雅曰。我心寫兮。傳云。輸寫其心也。按凡傾吐曰寫。故作字作畫皆曰寫。俗作瀉者、寫之俗字。周禮以澮寫水。不作瀉。"}]},"藸":{"expl":"荎藸也。从艸豬聲。","rad":"艸","fq":"直魚切","vol":"01","py":"chú","duan":[{"e":"艸也。从艸。豬聲。","n":"直魚切。五部。鉉本移此字於荎篆下。以荎藸二字當類列。而不知許意單呼藸者、別是一物也。"}]},"宵":{"expl":"夜也。从宀，宀下冥也；肖聲。","rad":"宀","fq":"相邀切","vol":"07","py":"xiāo","duan":[{"e":"夜也。","n":"釋言、毛傳皆曰。宵、夜也。周禮司寤。禁宵行夜游者。鄭云。宵、定昏也。按此因經文以宵別於夜爲言。若渾言則宵卽夜也。有假宵爲小者。學記之宵雅是也。有假宵爲肖者。漢志人宵天地之貌是也。"}]},"宿":{"expl":"止也。从宀𠈇聲。𠈇，古文夙。","rad":"宀","fq":"息逐切","vol":"07","py":"sù","duan":[{"e":"止也。","n":"凡止曰宿。夜止、其一耑也。毛傳。一宿曰宿。再宿曰信。卽左傳之凡師一宿曰舍、再宿曰信、過信曰次也。止之義引伸之則爲素。如史記云宿將、宿學是也。先期亦曰宿。周禮世婦掌女宫之宿戒、祭統宫宰宿夫人、禮經宿尸皆謂先期戒飭。鄭云。宿讀爲肅。"}]},"寑":{"expl":"臥也。从宀钅聲鲞。","rad":"宀","fq":"七荏切","vol":"07","py":"qǐn","duan":[{"e":"臥也。","n":"李善引論語鄭注。寝、臥息也。臥必於室。故其字从宀。引伸爲宫室之偁。周禮宮人。掌王之六寢之脩。釋宫曰。室有東西箱曰廟。無東西箱有室曰寢。又引伸之凡事止亦曰寢。"}]},"𡧍":{"expl":"冥合也。从宀丏聲。讀若《周書》“若藥不眄眩”。","rad":"宀","fq":"莫甸切","vol":"07","py":"miàn","duan":[{"e":"冥合也。","n":"冥合者、合之泯然無迹。今俗云吻合者當用此字。"}]},"寬":{"expl":"屋寬大也。从宀萈聲。","rad":"宀","fq":"苦官切","vol":"07","py":"kuān","duan":[{"e":"屋寬大也。","n":"廣韵曰。裕也。緩也。其引伸之義也。古文假完字爲之。"}]},"𡨂":{"expl":"寤也。从宀吾聲。","rad":"宀","fq":"五故切","vol":"07","py":"wù","duan":[{"e":"寤也。","n":"寐覺而有言曰寤。𡨂之音義皆同也。"}]},"寁":{"expl":"居之速也。从宀疌聲。","rad":"宀","fq":"子感切","vol":"07","py":"zǎn","duan":[{"e":"凥之速也。","n":"止部疌、疾也。疌爲凡速之詞。从宀則爲居之速也。鄭風。不寁故也。毛曰。寁、速也。用寁以言凡速耳。周易。朋盍簪。晁氏說之曰。簪京本、蜀才本作撍。陰弘道案張揖古今字詁。𢈻作撍。埤蒼云。撍、疾也。撍與簪同。王元叔謂卽詩不寁字。祖感反。玉裁按。𢈻卽寁。古宀广通用。葢古今字詁今字作𢈻。古字作撍也。"}]},"寡":{"expl":"少也。从宀从頒。頒，分賦也，故爲少。","rad":"宀","fq":"古瓦切","vol":"07","py":"ɡuǎ","duan":[{"e":"少也。","n":"引伸之凡倮然、單獨皆曰寡。"}]},"客":{"expl":"寄也。从宀各聲。","rad":"宀","fq":"苦格切","vol":"07","py":"kè","duan":[{"e":"寄也。","n":"字从各。各、異詞也。故自此託彼曰客。引伸之曰賓客。賓、所敬也。客、寄也。故周禮大行人大賓大客別其辭。諸侯謂之大賓。其孤卿謂之大客。司儀曰。諸公諸侯諸伯諸子諸男相爲賓、諸公之臣侯伯子男之臣相爲客是也。統言則不別耳。論語。寢不尸。居不客。謂生不可似死。主不可似客也。今本誤作不容。"}]},"寄":{"expl":"託也。从宀奇聲。","rad":"宀","fq":"居義切","vol":"07","py":"jì","duan":[{"e":"託也。","n":"字从奇。奇、異也。一曰不耦也。言部曰。託、寄也。方言曰。餬託庇寓媵寄也。"}]},"葛":{"expl":"絺綌艸也。从艸曷聲。","rad":"艸","fq":"古達切","vol":"01","py":"ɡé","duan":[{"e":"絺綌艸也。","n":"周南。葛之覃兮。爲絺爲綌。"}]},"寓":{"expl":"寄也。从宀禺聲。","rad":"宀","fq":"牛具切","vol":"07","py":"yù","duan":[{"e":"寄也。","n":"方言曰。寓、寄也。左傳曰寓書。史記曰木禺、龍禺者、寓之叚借也。"}]},"寠":{"expl":"無禮居也。从宀婁聲。","rad":"宀","fq":"其榘切","vol":"07","py":"jù","duan":[{"e":"無禮凥也。","n":"邶風。終寠且貧。傳曰。寠者、無禮也。貧者困於財。箋云。君於己祿薄。終不足以爲禮。又近困於財。按無禮因於祿薄。故釋言云。寠、貧也。然倉頡篇云。無財曰貧。無財？禮曰寠。則貧寠有別。小雅云。佌佌彼有屋。蔌蔌方穀。箋云。小人富而寠陋將貴也。然則有富而寠陋者矣。許從毛。益以居字者、以其字从宀也。無禮居、謂宫室不中禮。"}]},"㝌":{"expl":"貧病也。从宀久聲。《詩》曰：“煢煢在㝌。”","rad":"宀","fq":"居又切","vol":"07","py":"jiù","duan":[{"e":"貧病也。","n":"貧病者、貧之病也。"}]},"寒":{"expl":"凍也。从人在宀下，以茻薦覆之，下有仌。","rad":"宀","fq":"胡安切","vol":"07","py":"hán","duan":[{"e":"凍也。","n":"凍當作冷。十一篇曰。凍、仌也。冷、寒也。此可證矣。釋名曰。寒、捍也。捍、格也。左傳寒盟。寒者、尋之反。尋卽燅字。"}]},"害":{"expl":"傷也。从宀从口。宀、口，言从家起也。丯聲。","rad":"宀","fq":"胡蓋切","vol":"07","py":"hài","duan":[{"e":"傷也。","n":"人部曰。傷、創也。刀部曰。創、傷也。詩書多假害爲曷。故周南毛傳曰。害、何也。俗本改爲曷、何也。非是。今人分別害去、曷入。古無去入之分也。"}]},"𡩡":{"expl":"入家𢯱也。从宀索聲。","rad":"宀","fq":"所責切","vol":"07","py":"suǒ","duan":[{"e":"入家𢯱也。","n":"𢯱、求也。顔氏家訓曰。通俗文云。入室求曰搜。按當作入室求曰𡩡。今俗語云搜𡩡是也。𡩡、經典多假索爲之。如探嘖索隱是。"}]},"𡫬":{"expl":"窮也。从宀𥱩聲。𥱩與𥷤同。","rad":"宀","fq":"居六切","vol":"07","py":"jū","duan":[{"e":"竆也。","n":"𡫬竆雙聲。毛傳於谷風、南山、小弁皆曰。鞫、竆也。鞫皆𡫬之叚借也。㚔部曰。𥱩、竆治罪人也。其字俗作鞫。然則詩谷風、南山、小弁鞫字皆𡫬之叚借也。毛傳於公劉曰。鞫、究也。於節南山曰。鞫、盈也。究與盈皆與竆義近。若蓼莪傳曰鞫、養也。則就竆義而變之。所謂相反而相成也。若菜芑傳云鞫、告也。則謂鞫卽告之叚借。自淺人不得其義例。多所改？。唐石經鞫鞠錯出。至近日而盡改爲鞠矣。鞠者、革部蹋鞠之字。其義相去遠。詩借鞫爲𡫬。義相近也。鞫行而𡫬廢矣。"}]},"宄":{"expl":"姦也。外爲盜，内爲宄。从宀九聲。讀若軌。","rad":"宀","fq":"居洧切","vol":"07","py":"ɡuǐ","duan":[{"e":"姦也。","n":"姦宄者、通偁。內外者、析言之也。"}]},"㝮":{"expl":"塞也。从宀𠭥聲。讀若《虞書》曰“㝮三苗”之“㝮”。","rad":"宀","fq":"麤最切","vol":"07","py":"cuì","duan":[{"e":"塞也。","n":"廣雅㝮塞也本此。陸䞇關中事狀。倘有賊臣盗㝮。"}]},"宕":{"expl":"過也。一曰洞屋。从宀，碭省聲。汝南項有宕鄉。","rad":"宀","fq":"徒浪切","vol":"07","py":"dànɡ","duan":[{"e":"過也。","n":"宕之言放蕩也。穀梁傳引傳曰。長狄兄弟三人。佚宕中國。"}]},"䄟":{"expl":"數祭也。从示毳聲。讀若舂麥爲䄟之䄟。","rad":"示","fq":"此芮切","vol":"01","py":"cuì","duan":[{"e":"䄟數祭也。","n":"廣雅釋詁曰。䄟、謝也。釋天曰。䄟、祭也。數讀數罟之數。雙聲也。"}]},"蔓":{"expl":"葛屬。从艸曼聲。","rad":"艸","fq":"無販切","vol":"01","py":"màn","duan":[{"e":"葛屬也。","n":"此專謂葛屬、則知滋蔓字古衹作曼。正如蔓延字多作莚。"}]},"宋":{"expl":"居也。从宀从木。讀若送。","rad":"宀","fq":"蘇統切","vol":"07","py":"sònɡ","duan":[{"e":"凥也。","n":"此義未見經傳。名子者不以國。而魯定公名宋。則必取其本義也。"}]},"𡪐":{"expl":"屋傾下也。从宀執聲。","rad":"宀","fq":"都念切","vol":"07","py":"diàn","duan":[{"e":"屋傾下也。","n":"謂屋欹傾下陷也。與墊音義同。"}]},"宗":{"expl":"尊祖廟也。从宀从示。","rad":"宀","fq":"作冬切","vol":"07","py":"zōnɡ","duan":[{"e":"尊祖廟也。","n":"宗尊雙聲。按當云尊也、祖廟也。今本奪上也字。大雅。公尸來燕來宗。傳曰。宗、尊也。凡尊者謂之宗。尊之則曰宗之。大雅。君之宗之。箋云。宗、尊也。禮記。別子爲祖。繼別爲宗。繼禰者爲小宗。凡言大宗小宗皆謂同所出之兄弟所尊也。尊莫尊於祖廟。故謂之宗廟。宗从宀从示。示謂神也。宀謂屋也。"}]},"宔":{"expl":"宗廟宔祏。从宀主聲。","rad":"宀","fq":"之庾切","vol":"07","py":"zhǔ","duan":[{"e":"宗廟宔祏也。","n":"五經異義及鄭駁詳示部祏下。經典作主。小篆作宔。主者古文也。祏猶主也。左傳使祝史、徙主祏於周廟是也。鄭說卿大夫無宔。許說大夫以石爲宔。"}]},"宙":{"expl":"舟輿所極覆也。从宀由聲。","rad":"宀","fq":"直又切","vol":"07","py":"zhòu","duan":[{"e":"舟輿所極覆也。","n":"覆者、反也。與復同。往來也。舟輿所極覆者、謂舟車自此至彼而復還此如循環然。故其字从由。如軸字从由也。訓詁家皆言上下四方曰宇。往古來今曰宙。由今溯古。復由古沿今。此正如舟車自此至彼、復自彼至此皆如循環然。莊周書云。有實而無乎處者宇也。有長而無本剽者宙也。本剽卽本末。莊子說正與上下四方曰宇、往古來今曰宙同。亦謂其大無極、其長如循環也。許言其本義。他書言其引伸之義。其字从宀者、宙不出乎宇也。韋昭曰。天宇所受曰宙。"}]},"钍":{"expl":"置也。从宀眞聲。","rad":"宀","fq":"支義切","vol":"07","py":"zhì","duan":[]},"寰":{"expl":"王者封畿内縣也。从宀瞏聲。","rad":"宀","fq":"戶關切","vol":"07","py":"huán","duan":[]},"寀":{"expl":"同地爲寀。从宀采聲。","rad":"宀","fq":"倉宰切","vol":"07","py":"cǎi","duan":[]},"宮":{"expl":"室也。从宀，躳省聲。凡宮之屬皆从宮。","rad":"宮","fq":"居戎切","vol":"07","py":"ɡōnɡ","duan":[{"e":"室也。","n":"釋宫曰。宫謂之室。室謂之宫。郭云。皆所以通古今之異語。明同實而兩名。按宫言其外之圍繞。室言其內。析言則殊。統言不別也。毛詩。作于楚宫。作于楚室。傳曰。室猶宫也。此統言也。宫自其圍繞言之。則居中謂之宫。五音宫商角徵羽。劉歆云。宫、中也。居中央。唱四方。唱始施生。爲四聲綱也。"}]},"營":{"expl":"市居也。从宮，熒省聲。","rad":"宮","fq":"余傾切","vol":"07","py":"yínɡ","duan":[{"e":"帀居也。","n":"帀各本作市。今依葉抄宋本及韵會本訂。攷集韵作市。類篇、韵會作匝。葢由古本作帀。故有譌爲市者。帀居謂圍繞而居。如市營曰闤、軍壘曰營皆是也。西京賦。通闤帶闠。薛注。闤、市營也。闠、中隔門也。崔豹曰。市牆曰闤。市門曰闠。孫氏星衍曰。營闤音近。如自營曰厶今本韓非子作自環、煢煢在疚亦作嬛嬛是也。諸葛孔明表云。營中之事。謂軍壘也。引伸之爲經營、營治。凡有所規度皆謂之營。"}]},"䔌":{"expl":"葛屬。白華。从艸皐聲。","rad":"艸","fq":"古勞切","vol":"01","py":"ɡāo","duan":[{"e":"葛屬也。白華。","n":"南山經。其名曰白䓘。廣雅曰。䔌蘇、白䓘也。按未知卽此物與否。"}]},"呂":{"expl":"𦟝骨也。象形。昔太嶽爲禹心呂之臣，故封呂矦。凡呂之屬皆从呂。","rad":"呂","fq":"力舉切","vol":"07","py":"lǚ","duan":[{"e":"𦟝骨也。象形。","n":"吕象顆顆相承。中象其系聯也。沈氏彤釋骨曰。項大椎之下二十一椎通曰脊骨、曰脊椎、曰膂骨。或以上七節曰背骨。第八節以下乃曰膂骨。力舉切。五部。"}]},"躳":{"expl":"身也。从身从呂。","rad":"呂","fq":"居戎切","vol":"07","py":"ɡōnɡ","duan":[{"e":"身也。","n":"廣雅同。"}]},"穴":{"expl":"土室也。从宀八聲。凡穴之屬皆从穴。","rad":"穴","fq":"胡決切","vol":"07","py":"xué","duan":[{"e":"土室也。","n":"引伸之凡空竅皆爲穴。"}]},"𥥊":{"expl":"北方謂地空，因以爲土穴，爲𥥊戶。从穴皿聲。讀若猛。","rad":"穴","fq":"武永切","vol":"07","py":"mǐnɡ","duan":[{"e":"北方謂地空因㠯爲土穴爲𥥊戶。","n":"因地之孔爲土屋也。廣雅𥥊、窟也。"}]},"窨":{"expl":"地室。从穴音聲。","rad":"穴","fq":"於禁切","vol":"07","py":"yìn","duan":[{"e":"地室也。","n":"今俗語以酒水等埋藏地下曰窨。讀陰去聲。"}]},"窯":{"expl":"燒瓦竈也。从穴羔聲。","rad":"穴","fq":"余招切","vol":"07","py":"yáo","duan":[{"e":"燒瓦窯𫁘也。","n":"窯似𫁘。故曰窯𫁘。韵會本作燒瓦窯也。無𫁘字。大徐本作燒瓦竈也。非是。緜詩鄭箋云。復穴皆如陶然。是謂經之陶卽窯字之叚借也。緜正義引說文。陶、瓦器𫁘也。葢其所據乃缶部匋下語。匋窯葢古今字。"}]},"𥨍":{"expl":"地室也。从穴復聲。《詩》曰：“陶𥨍陶穴。”","rad":"穴","fq":"芳福切","vol":"07","py":"fù","duan":[{"e":"地室也。","n":"大雅正義引作覆於地也四字。按詩大雅陶復陶穴箋云。復者、復於土上。鑿地曰穴。皆如陶然。庾蔚之云。複謂地上累土爲之。穴則穿地也。鄭、庾之云與許云覆於地合。覆於地者、謂旁穿之。則地覆於上。穴則正穿之。上爲中𩅸。毛傳云。陶其土而復之。陶其壤而穴之。土謂堅者。堅則不患𡹔壓。故旁穿之。使上有覆。葢陶其土、旁穿之也。壤謂柔者。柔則恐𡹔。故正鑿之。陶其壤、謂正鑿之。直穴之中爲中𩅸也。鄭注月令云。中𩅸猶中室也。古者複穴。是以名室爲𩅸云。連複言之者、文勢使然也。毛之陶其土、陶其壤。葢讀陶爲掏。鄭則云皆如窯然。特此爲異耳。漢時陵墓築封土謂之復土。義與此復土小異。要亦上覆之言耳。"}]},"竈":{"expl":"炊竈也。从穴，鼀省聲。","rad":"穴","fq":"則到切","vol":"07","py":"zào","duan":[]},"窐":{"expl":"甑空也。从穴圭聲。","rad":"穴","fq":"烏瓜切","vol":"07","py":"wā","duan":[{"e":"空也。","n":"楚辭曰。圭璋襍於甑窐。此甑下空也。攷工記鳧氏爲鐘注。隧在𡔷中。窐而生光。高注淮南曰。靨輔者、頰上窐也。然則凡空穴皆謂之窐矣。"}]},"𥥍":{"expl":"深也。一曰竈突。从穴从火，从求省。","rad":"穴","fq":"式鍼切","vol":"07","py":"shēn","duan":[{"e":"深也。","n":"此以今字釋古字也。？？古今字。篆作？？。？變作罙深。水部？下但云水名。不言淺之反。是知古深淺字作罙。深行而罙廢矣。有穴而後有淺深。故字从穴。毛詩。罙入其阻。傳曰。罙、深也。此罙字見六經者。毛公以今字釋古字。而許襲之。此罙之音義原流也。鄭箋易罙爲䍘。訓爲冒也。葢以字形相似易之。罙在侵韵。䍘在脂韵。鄭注經有易字之例。他經云某讀爲某。箋詩不尒。讀經者誤謂毛、鄭同字。作音義者當各字各音分別載之云。毛作罙。式針反。深也。鄭作䍘。面規反。冒也。說文罙作？。䍘作？。乃爲明析。而陸釋文則曰。罙、面規反。毛深也。鄭冒也。說文作？。从网米。云冒也。此條之𡚁有七。以罙切面規。絕非毛音。一也。以鄭箋作罙。非鄭所易字。"}]},"莕":{"expl":"菨餘也。从艸杏聲。","rad":"艸","fq":"何梗切","vol":"01","py":"xìnɡ","duan":[{"e":"菨餘也。","n":"周南。參差荇菜。毛傳。荇、接余也。釋艸荇作莕。"}]},"穿":{"expl":"通也。从牙在穴中。","rad":"穴","fq":"昌緣切","vol":"07","py":"chuān","duan":[{"e":"通也。从牙在穴中。","n":"召南曰。誰謂鼠無牙。何以穿我墉。昌緣切。十四部。"}]},"竂":{"expl":"穿也。从穴尞聲。《論語》有公伯竂。","rad":"穴","fq":"洛蕭切","vol":"07","py":"liáo","duan":[{"e":"穿也。","n":"倉頡篇曰。寮、小空也。西京賦曰。交綺豁以疏寮。薛曰。疏、刻穿之也。善曰。倉頡篇云。寮、小窗。魏都賦。皦日籠光於綺寮。按大雅。及爾同寮。左傳曰。同官爲寮。毛傳曰。寮、官也。箋云。與汝同官。俱爲卿士。葢同官者同居一域。如俗云同學一處爲同窗也。亦假僚字爲之。左傳。泉丘人女奔孟僖子。其僚從之。杜注。鄰女爲僚友。"}]},"䆕":{"expl":"穿也。从穴，決省聲。","rad":"穴","fq":"於決切","vol":"07","py":"yuè","duan":[{"e":"穿也。从穴。叏聲。","n":"大徐作決省聲。此不知古音者爲之也。於決切。十五部。"}]},"䆢":{"expl":"深抉也。从穴从抉。","rad":"穴","fq":"於決切","vol":"07","py":"yuè","duan":[{"e":"㴱抉也。","n":"抉之深故从穴。"}]},"竇":{"expl":"空也。从穴，瀆省聲。","rad":"穴","fq":"徒奏切","vol":"07","py":"dòu","duan":[{"e":"空也。","n":"空孔古今語。凡孔皆謂之竇。古亦借瀆爲之。如周禮注四竇卽四瀆、左傳襄三十年墓門之瀆徐音豆是也。"}]},"䆷":{"expl":"空皃。从穴矞聲。","rad":"穴","fq":"呼決切","vol":"07","py":"xuè","duan":[{"e":"空皃。","n":"孔之皃也。"}]},"窠":{"expl":"空也。穴中曰窠，樹上曰巢。从穴果聲。","rad":"穴","fq":"苦禾切","vol":"07","py":"kē","duan":[{"e":"空也。","n":"雙聲爲訓。其字亦作窾。高誘曰窾空也是。或借科爲之。孟子盈科而後進是。或借薖爲之。如衛風碩人之薖。毛云寬大皃、鄭云飢意皆是。"}]},"窻":{"expl":"通孔也。从穴怱聲。","rad":"穴","fq":"楚江切","vol":"07","py":"chuānɡ","duan":[{"e":"通孔也。从穴。悤聲。","n":"楚江切。九部。按此篆淺人所增。古本所無。當刪。十篇囱下曰。在牆曰牖。在屋曰囱。囱或从穴作窗。古衹有囱字。窗巳爲或體。何取乎更取悤聲作窻字哉。自東江韵分。淺人多所僞𢰅。據廣韵四江䆫下云。說文作窗。通孔也。則篆體之不當有心明矣。依廣韵宜囱部去窗篆。此窻篆改爲窗。然囱窗本一字。宜囱部仍舊而此從刪也。許但作空不作孔。此云通孔也。則非許氏原文。"}]},"窊":{"expl":"污衺，下也。从穴瓜聲。","rad":"穴","fq":"烏瓜切","vol":"07","py":"wā","duan":[{"e":"污衺、","n":"逗。"}]},"竅":{"expl":"空也。从穴敫聲。","rad":"穴","fq":"牽料切","vol":"07","py":"qiào","duan":[{"e":"空也。","n":"空孔古今字。老子。常有欲以觀其竅。"}]},"菨":{"expl":"菨餘也。从艸妾聲。","rad":"艸","fq":"子葉切","vol":"01","py":"jiē","duan":[{"e":"菨餘也。","n":"三字句。毛傳、陸疏作接余。按莕菜、今江浙池沼閒多有。葉不正圜。花黃六出。北方以人莧當之。南方以蓴絲當之。皆非也。"}]},"空":{"expl":"竅也。从穴工聲。","rad":"穴","fq":"苦紅切","vol":"07","py":"kōnɡ","duan":[{"e":"竅也。","n":"今俗語所謂孔也。天地之閒亦一孔耳。古者司空主土。尙書大傳曰。城郭不繕。溝池不修。水泉不修。水爲民害。責於地公。司馬彪曰。司空公一人。掌水土事。凡營城、起邑、浚溝洫、修墳防之事。則議其利、建其功。是則司空以治水土爲職。禹作司空。治水而後晉百揆也。治水者必通其瀆。故曰司空猶司孔也。"}]},"𥥻":{"expl":"空也。从穴巠聲。《詩》曰：“瓶之𥥻矣。”","rad":"穴","fq":"去徑切","vol":"07","py":"qìnɡ","duan":[{"e":"空也。","n":"空虚、孔穴本無二義。但有孔穴則是空虚也。"}]},"穵":{"expl":"空大也。从穴乙聲。","rad":"穴","fq":"烏黠切","vol":"07","py":"yà","duan":[{"e":"空也。","n":"鉉本作空大也。非是。廣韵引同。亦誤本耳。今依小徐及玉篇。今俗謂盜賊穴牆曰穵是也。"}]},"窳":{"expl":"污窬也。从穴㼌聲。朔方有窳渾縣。","rad":"穴","fq":"以主切","vol":"07","py":"yǔ","duan":[{"e":"污窬也。","n":"污窬、葢與污衺同。亦謂下也。以衺與窊同韵。窬與窳同韵。故分別其辭也。史記。舜陶河濱。器不苦窳。裴駰曰。窳、病也。按器窳者、低陷之謂。亦汙窬之意也。釋詁曰。窳、勞也。郭云。勞苦者多惰窳。大雅毛傳曰。訿訿、窳不供事也。史記。啙窳偷生。晉灼曰。啙、病也。窳、惰也。許於此部啙下亦云窳也。葢卽用毛傳。毛詩訿、卽啙也。此等窳皆訓惰嬾。亦皆污窬引伸之義。釋玄應屢引揚承慶字統說。懶者不能自起。如瓜瓠在地不能自立。故字从㼌。又嬾人恒在室中。故从穴。夫穴訓土室。不必从宀而後爲室也。而召旻正義曰。艸木皆自豎立。惟瓜瓠之屬臥而不起。似若嬾人常臥室。故字从宀。宀音眠。此亦用字統說。而與玄應所據有異。且陸氏釋文、孔氏正義"}]},"窞":{"expl":"坎中小坎也。从穴从臽，臽亦聲。《易》曰：“入于坎窞。”一曰㫄入也。","rad":"穴","fq":"徒感切","vol":"07","py":"dàn","duan":[{"e":"坎中㪅有坎也。","n":"各本作坎中小坎。今依易釋文訂。易坎初六曰。入於坎窞。虞翻曰。坎中小穴稱窞。釋文引說文。坎中更有坎也。字林。坎中小坎也。然則今文爲後人以呂改許明矣。"}]},"窌":{"expl":"窖也。从穴卯聲。","rad":"穴","fq":"匹皃切","vol":"07","py":"jiào","duan":[{"e":"窖也。","n":"攷工記匠人注曰。穿地曰𥥺。呂覽。穿竇𥥹。月令、淮南皆作窖。"}]},"窖":{"expl":"地藏也。从穴告聲。","rad":"穴","fq":"古孝切","vol":"07","py":"jiào","duan":[{"e":"地臧也。","n":"月令。穿竇窖。注曰。入地隋曰竇。方曰窖。通俗文曰。藏穀麥曰窖。"}]},"窬":{"expl":"穿木戶也。从穴俞聲。一曰空中也。","rad":"穴","fq":"羊朱切","vol":"07","py":"yú","duan":[{"e":"穿木戶也。","n":"淮南氾論訓。古者爲窬木方版。以爲舟航。高誘曰。窬、空也。方、並也。舟相連爲航也。按窬木爲舟。卽易𣪠辭刳木爲舟也。儒行。篳門圭竇。鄭云。門旁窬也。穿牆爲之如圭矣。左傳。篳門圭竇。杜曰。竇、小戶也。穿壁爲戶。狀如圭形。郭樸三蒼解詁云。窬、門旁小竇也。是則於門旁穿壁。以木衺直居之。令如圭形。謂之圭窬。若論語本作穿踰。釋爲穿壁踰牆。似無煩與此牽混。"}]},"窵":{"expl":"窵窅，深也。从穴鳥聲。","rad":"穴","fq":"多嘯切","vol":"07","py":"diào","duan":[{"e":"窵窅、","n":"逗。"}]},"窺":{"expl":"小視也。从穴規聲。","rad":"穴","fq":"去隓切","vol":"07","py":"kuī","duan":[{"e":"小視也。从穴。規聲。","n":"去隓切。十六部。"}]},"𧃣":{"expl":"艸也。从艸𥊽聲。","rad":"艸","fq":"古渾切","vol":"01","py":"kūn","duan":[{"e":"艸也。从艸。𥊽聲。","n":"古渾切。十三部。"}]},"竀":{"expl":"正視也。从穴中正見也，正亦聲。","rad":"穴","fq":"救貞切","vol":"07","py":"chēnɡ","duan":[{"e":"正視也。从穴中正見。正亦聲。","n":"敕貞切。十一部。"}]},"窡":{"expl":"穴中見也。从穴叕聲。","rad":"穴","fq":"丁滑切","vol":"07","py":"zhuó","duan":[{"e":"穴中見也。从穴。叕聲。","n":"丁滑切。十五部。"}]},"窋":{"expl":"物在穴中皃。从穴中出。","rad":"穴","fq":"丁滑切","vol":"07","py":"zhuó","duan":[{"e":"物在穴中皃。","n":"靈光殿賦曰。綠房紫菂。窋䆛垂珠。謂蓮房之實窋䆛然見於房外如垂珠也。上文云。反植荷蕖。故曰垂珠。"}]},"窴":{"expl":"塞也。从穴眞聲。","rad":"穴","fq":"待秊切","vol":"07","py":"tián","duan":[{"e":"𡫳也。","n":"𡫳各本譌作塞。今正。玉篇曰。窴、今作塡。按窴塡同義。塡行而窴廢矣。"}]},"窒":{"expl":"塞也。从穴至聲。","rad":"穴","fq":"陟栗切","vol":"07","py":"zhì","duan":[{"e":"𡫳也。","n":"各本𡫳譌塞。今正。𡫳、窒也。見㠭部。此二字互訓也。𡫳之隷體爲𡨄。土部曰。塞、隔也。𨸏部曰。隔、塞也。塞於義不爲窒。邊塞其本義也。自用塞爲塡𡨄字。而𡨄廢矣。且有讀𡨄爲罅者。則𡨄愈失其本音本義矣。說詳㠭部。釋言、豳傳皆曰。窒、塞也。"}]},"突":{"expl":"犬从穴中暫出也。从犬在穴中。一曰滑也。","rad":"穴","fq":"徒骨切","vol":"07","py":"tū","duan":[{"e":"犬從穴中暫出也。","n":"引伸爲凡猝乍之稱。"}]},"竄":{"expl":"匿也。从鼠在穴中。","rad":"穴","fq":"七亂切","vol":"07","py":"cuàn","duan":[{"e":"匿也。","n":"周易逋竄、左氏無所伏竄是也。堯典？三苗于三危。與言流、言放、言極一例。謂放之令自匿。故孟子作殺三苗。卽左傳𥻦蔡叔之𥻦。𥻦爲正字。竄殺爲同音叚借。"}]},"窣":{"expl":"从穴中卒出。从穴卒聲。","rad":"穴","fq":"蘇骨切","vol":"07","py":"sū","duan":[{"e":"從穴中卒出。","n":"卒猝古今字。子虚賦。媻姍㪍𡨧。上乎金隄。韋昭曰。媻姍㪍𡨧、匍匐上也。按媻姍謂徐行。勃窣謂急行。"}]},"窘":{"expl":"迫也。从穴君聲。","rad":"穴","fq":"渠隕切","vol":"07","py":"jiǒnɡ","duan":[{"e":"迫也。","n":"小雅。又窘陰雨。毛傳。窘、困也。按箋云。窘、仍也。仍者、仍其舊而不能變。亦是困意。"}]},"窕":{"expl":"深肆極也。从穴兆聲。讀若挑。","rad":"穴","fq":"徒了切","vol":"07","py":"tiǎo","duan":[{"e":"𥥍肆極也。","n":"窕與窘爲反對之辭。釋言曰。窕、肆也。大戴禮王言。七者布諸天下而不窕。內諸尋常之室而不塞。淮南俶眞訓。處小隘而不塞。橫扃天地之閒而不窕。要略訓。置之㝷常而不塞。布之天下而不窕。氾論訓。舒之天下而不窕。內之尋常而不塞。齊俗訓。大則塞而不入。小則窕而不周。兵略訓。入小而不偪。處大而不窕。墨子尙賢中。此道也。大用之天下則不窕。小用之則不困。尙同下。大用之治天下不窕。小用之治一國一家而不橫。荀卿子曰。充盈大宇而不窕。入郤穴而不偪。管子宙合曰。夫成軸之多也。其處大也不窕。其入小也不塞。司馬法曰。凡戰之道。位欲嚴。政欲栗。力欲窕。氣欲閑。又曰。擊其勞倦。避其閑窕。凡此皆可證窕之訓寬肆。凡言在小不塞、在大不窕"}]},"芫":{"expl":"魚毒也。从艸元聲。","rad":"艸","fq":"愚袁切","vol":"01","py":"yuán","duan":[{"e":"魚毒也。","n":"爾雅釋木。杬、魚毒。郭云。大木。皮厚。汁赤。堪藏卵果。顏師古注急就篇芫華曰。景純所說。乃左思吳都賦所謂緜杬杶櫨者耳。非魚毒也。芫草一名魚毒。煑之以投水中。魚則死而浮出。故以爲名。其華可以爲藥。芫字或作杬。玉裁按。爾雅杬字本或作芫。入於釋木。本艸及許君皆入艸部。"}]},"穹":{"expl":"窮也。从穴弓聲。","rad":"穴","fq":"去弓切","vol":"07","py":"qiónɡ","duan":[{"e":"竆也。","n":"竆者、極也。豳風。穹窒熏鼠。毛傳曰。穹窮、窒塞也。穹窮雙聲。大雅。以念穹蒼。釋天、毛傳皆曰。穹蒼、蒼天也。按穹蒼者、謂蒼天難窮極也。韗人爲臯陶。穹者三之一。注謂𡔷木腹穹隆。居𡔷三之一。今人皆謂高爲穹隆。"}]},"究":{"expl":"窮也。从穴九聲。","rad":"穴","fq":"居又切","vol":"07","py":"jiù","duan":[{"e":"竆也。","n":"釋言同。小雅常棣傳曰。究、深也。釋詁及大雅皇矣傳曰。究、謀也。皆窮義之引伸也。"}]},"竆":{"expl":"極也。从穴躳聲。","rad":"穴","fq":"渠弓切","vol":"07","py":"qiónɡ","duan":[{"e":"極也。从穴。躳聲。","n":"渠弓切。九部。或假爲躳字。如鞠躬古作鞠窮。"}]},"䆞":{"expl":"冥也。从穴㫐聲。","rad":"穴","fq":"烏皎切","vol":"07","py":"yǎo","duan":[{"e":"冥也。","n":"冥者、窈也。"}]},"窔":{"expl":"䆞窔，深也。从穴交聲。","rad":"穴","fq":"烏叫切","vol":"07","py":"yào","duan":[{"e":"䆞窔、","n":"逗。"}]},"邃":{"expl":"深遠也。从穴遂聲。","rad":"穴","fq":"雖遂切","vol":"07","py":"suì","duan":[{"e":"𥥍遠也。从穴。遂聲。","n":"雖遂切。十五部。"}]},"窈":{"expl":"深遠也。从穴幼聲。","rad":"穴","fq":"烏皎切","vol":"07","py":"yǎo","duan":[{"e":"𥥍遠也。","n":"周南毛傳曰。窈窕、幽閒也。以幽釋窈。以閒釋窕。方言曰。美心爲窈。美狀爲窕。陳風傳又曰。窈糾、舒之姿也。舒、遅也。"}]},"窱":{"expl":"杳窱也。从穴條聲。","rad":"穴","fq":"徒弔切","vol":"07","py":"tiǎo","duan":[{"e":"杳窱也。","n":"廣雅曰。窈窱、深也。西京賦曰。望䆗窱以徑廷。薛曰。過度之義也。集韵曰。䆗同窈。"}]},"竁":{"expl":"穿地也。从穴毳聲。一曰小鼠。《周禮》曰：“大喪，甫竁。”","rad":"穴","fq":"充芮切","vol":"07","py":"cuì","duan":[{"e":"穿地也。","n":"周禮小宗伯、冢人皆曰甫竁。注曰。甫、始也。鄭大夫讀竁皆爲穿。杜子春讀竁如毳。皆謂葬穿壙也。今南陽名穿地爲竁。聲如腐脆之脆。按此注讀竁爲穿者、易其字也。讀竁如毳者、擬其音也。下文鄭伸子春之說。以南陽語證子春說之不誤。"}]},"窆":{"expl":"葬下棺也。从穴乏聲。《周禮》曰：“及窆執斧。”","rad":"穴","fq":"方驗切","vol":"07","py":"biǎn","duan":[{"e":"葬下棺也。","n":"土部曰。堋、葬下土也。春秋傳朝而堋。禮謂之封。周官謂之窆。按禮謂十七篇也。士喪禮下篇曰。及窆。主人哭踊無筭。注。窆、下棺也。今文窆爲封。然則許十七篇從今文。鄭從古文而曡今文也。凡戴記皆作封。戴記從今文也。周官謂之窆者、周禮鄉師云及窆執斧以涖匠師。先鄭云。窆謂葬下棺。春秋傳所謂傰。禮記所謂封也。按堋窆封三字分蒸侵東三韵。而一聲之轉。"}]},"蘦":{"expl":"大苦也。从艸霝聲。","rad":"艸","fq":"郎丁切","vol":"01","py":"línɡ","duan":[{"e":"大苦也。","n":"此與前大苦苓也相乖刺。說詳苦字下。"}]},"窀":{"expl":"葬之厚夕。从穴屯聲。《春秋傳》曰：“窀穸从先君於地下。”","rad":"穴","fq":"陟倫切","vol":"07","py":"zhūn","duan":[{"e":"窀穸、","n":"逗。各本刪此二字。今依全書例補。厚釋窀。夕釋穸。"}]},"穸":{"expl":"窀穸也。从穴夕聲。","rad":"穴","fq":"詞亦切","vol":"07","py":"xī","duan":[{"e":"窀穸也。从穴。夕聲。","n":"孔宙碑作窀夕。乃蒙上穴而省耳。詞亦切。古音在五部。"}]},"䆘":{"expl":"入衇剌穴謂之䆘。从穴甲聲。","rad":"穴","fq":"烏狎切","vol":"07","py":"yā","duan":[{"e":"入衇刺穴謂之䆘。","n":"葢古醫經之言。齊民要術說相牛有䆘字。"}]},"㝱":{"expl":"寐而有覺也。从宀从疒，夢聲。《周禮》：“以日月星辰占六㝱之吉凶：一曰正㝱，二曰㖾㝱，三曰思㝱，四曰悟㝱，五曰喜㝱，六曰懼㝱。”凡㝱之屬皆从㝱。","rad":"㝱","fq":"莫鳳切","vol":"07","py":"mènɡ","duan":[{"e":"寐而覺者也。","n":"寐而覺、與酲字下醉而覺同意。今字叚夢爲之。夢行而㝱廢矣。"}]},"㝲":{"expl":"病臥也。从㝱省，练省聲。","rad":"㝱","fq":"七荏切","vol":"07","py":"qǐn","duan":[{"e":"病臥也。","n":"𡪢者、臥也。㝲者、病臥也。此二字之別。今字槩作寢矣。"}]},"寐":{"expl":"臥也。从㝱省，未聲。","rad":"㝱","fq":"蜜二切","vol":"07","py":"mèi","duan":[{"e":"臥也。","n":"俗所謂睡著也。周南毛傳曰。寐、寢也。"}]},"寤":{"expl":"寐覺而有信曰寤。从㝱省，吾聲。一曰晝見而夜㝱也。","rad":"㝱","fq":"五故切","vol":"07","py":"wù","duan":[{"e":"寐覺而有言曰寤。","n":"有言、今鍇本作省信。鉉本作有信。皆誤。今依韵會所據鍇本。釋玄應引倉頡篇。覺而有言曰寤。左傳季寤字子言是其證。按周南毛傳曰。窹、覺也。衛風鄭箋同。言其大略而巳。鄭釋周禮寤夢云。覺時道之而夢。亦與倉頡篇同也。古書多叚寤爲悟。"}]},"𡫽":{"expl":"楚人謂寐曰𡫽。从㝱省，女聲。","rad":"㝱","fq":"依倨切","vol":"07","py":"rǔ","duan":[{"e":"楚人謂寐曰𡫽。","n":"𡫽猶𪏮也。𪏮、黏也。"}]},"㝥":{"expl":"寐而未厭。从㝱省，米聲。","rad":"㝱","fq":"莫禮切","vol":"07","py":"mǐ","duan":[{"e":"寐而厭也。","n":"鉉本作未厭。誤甚。胡身之通鑑釋文辨誤引作米厭。米卽㝥之譌。葢古本作寐。而㝥厭一譌作米。再譌作未。要不若小徐本爲長。廣雅曰。？、㝪、厭也。按厭魘正俗字。大徐於鬼部妄增魘字。云夢驚也。由不解此處厭字故耳。倉頡篇曰。伏合人心曰厭。字苑曰。厭、眠內不祥也。皆見玄應書。廣韵五十？厭注厭魅。二十九葉厭注惡夢。可見魘字之晚出冣俗矣。西山經。翼望之山。鳥名鵸䳜。服之使人不厭。此用厭字之冣古者。？古多叚借眯爲之。郭注山海經引周書服之不眯。爲不厭之證。莊子天運。彼不得夢。必且數眯焉。司馬彪曰。眯、厭也。通鑑。劉曄曰。臣得與聞大謀。常恐眯夢漏泄。以益臣罪。語本裴松之引傅子。胡身之引說文㝥字解之。"}]},"𡬄":{"expl":"孰寐也。从㝱省，水聲。讀若悸。","rad":"㝱","fq":"求癸切","vol":"07","py":"jì","duan":[{"e":"孰寐也。从㝱省。水聲。讀若悸。","n":"求癸切。十五部。按大徐用唐韵也。玉篇、廣韵、集韵、類篇皆衹渠季切一音。"}]},"蕛":{"expl":"蕛苵也。从艸稊聲。","rad":"艸","fq":"大兮切","vol":"01","py":"tí","duan":[{"e":"蕛苵也。","n":"見釋艸。郭云。蕛似稗。布地生。邵氏晉涵云。孟子之荑稗、莊子之？稗皆是也。"}]},"寎":{"expl":"臥驚病也。从㝱省，丙聲。","rad":"㝱","fq":"皮命切","vol":"07","py":"bìnɡ","duan":[{"e":"臥驚病也。","n":"以曡韵爲訓。爾雅三月爲寎月。作此字。"}]},"寱":{"expl":"瞑言也。从㝱省，臬聲。","rad":"㝱","fq":"牛例切","vol":"07","py":"yì","duan":[{"e":"瞑言也。","n":"瞑、目翕也。瞑言者、寐中有言也。寱亦作？。俗作？。"}]},"寣":{"expl":"臥驚也。一曰小兒號寣寣。一曰河内相𧦝也。从㝱省，从言。","rad":"㝱","fq":"火滑切","vol":"07","py":"hū","duan":[{"e":"臥驚也。","n":"廣雅曰。寣、覺也。義相近。今江蘇俗語曰睡一寣。"}]},"疒":{"expl":"倚也。人有疾病，象倚箸之形。凡疒之屬皆从疒。","rad":"疒","fq":"女戹切","vol":"07","py":"nè","duan":[{"e":"倚也。","n":"倚與𤕫音相近。"}]},"疾":{"expl":"病也。从疒矢聲。","rad":"疒","fq":"秦悉切","vol":"07","py":"jí","duan":[{"e":"病也。","n":"析言之則病爲疾加。渾言之則疾亦病也。按經傳多訓爲急也。速也。此引伸之義。如病之來多無期無迹也。止部曰。疌、疾也。"}]},"痛":{"expl":"病也。从疒甬聲。","rad":"疒","fq":"他貢切","vol":"07","py":"tònɡ","duan":[{"e":"病也。从𤕫。甬聲。","n":"他貢切。九部。"}]},"病":{"expl":"疾加也。从疒丙聲。","rad":"疒","fq":"皮命切","vol":"07","py":"bìnɡ","duan":[{"e":"疾加也。","n":"苞咸注論語曰。疾甚曰病。"}]},"瘣":{"expl":"病也。从疒鬼聲。《詩》曰：“譬彼瘣木。”一曰腫㫄出也。","rad":"疒","fq":"胡罪切","vol":"07","py":"huì","duan":[{"e":"病也。从𤕫。鬼聲。","n":"胡罪切。十五部。"}]},"疴":{"expl":"病也。从疒可聲。《五行傳》曰：“時卽有口痾。”","rad":"疒","fq":"烏何切","vol":"07","py":"kē","duan":[{"e":"病也。","n":"鴻範五行傳鄭注同。"}]},"痡":{"expl":"病也。从疒甫聲。《詩》曰：“我僕痡矣。”","rad":"疒","fq":"普胡切","vol":"07","py":"pū","duan":[{"e":"病也。","n":"釋詁、毛傳同。"}]},"苵":{"expl":"蕛苵也。从艸失聲。","rad":"艸","fq":"徒結切","vol":"01","py":"dié","duan":[{"e":"蕛苵也。","n":"郭於蕛字逗。以苵釋蕛。許合蕛苵二字爲艸名。凡爾雅固有舉其名而無訓釋者。不當強爲句絕也。"}]},"瘽":{"expl":"病也。从疒堇聲。","rad":"疒","fq":"巨斤切","vol":"07","py":"qín","duan":[{"e":"病也。","n":"釋詁曰。瘽、病也。字亦作懃。"}]},"瘵":{"expl":"病也。从疒祭聲。","rad":"疒","fq":"側介切","vol":"07","py":"zhài","duan":[{"e":"病也。","n":"釋詁曰。瘵、病也。小雅菀桺毛傳同。箋云。瘵、接也。則謂詩叚瘵爲際也。"}]},"瘨":{"expl":"病也。从疒眞聲。一曰腹張。","rad":"疒","fq":"都秊切","vol":"07","py":"diān","duan":[{"e":"病也。","n":"大雅雲漢傳同。按今之顚狂字也。廣雅。瘨、狂也。急就篇作顚疾。"}]},"瘼":{"expl":"病也。从疒莫聲。","rad":"疒","fq":"慕各切","vol":"07","py":"mò","duan":[{"e":"病也。","n":"小雅曰。亂離瘼矣。釋詁、毛傳皆云。瘼、病也。方言曰。瘼、病也。東齊海岱之閒曰瘼。"}]},"㽱":{"expl":"腹中急也。从疒丩聲。","rad":"疒","fq":"古巧切","vol":"07","py":"jiǎo","duan":[{"e":"腹中急痛也。","n":"痛字依小徐及廣韵補。今吳俗語云。絞腸刮肚痛。其字當作㽱也。古音讀如糾。釋詁云。咎、病也。咎葢㽱之古文叚借字。"}]},"㾓":{"expl":"病也。从疒員聲。","rad":"疒","fq":"王問切","vol":"07","py":"yùn","duan":[{"e":"病也。从𤕫。員聲。","n":"王問切。十三部。"}]},"癎":{"expl":"病也。从疒閒聲。","rad":"疒","fq":"戶閒切","vol":"07","py":"xián","duan":[{"e":"病也。从𤕫。閒聲。","n":"戶閒切。十四部。按今俗語皆呼閒切。方書小兒有五癇。王符貴忠篇云。哺乳多則生癇病。玄應引聲類云。今謂小兒瘨曰癇也。"}]},"㽾":{"expl":"病也。从疒出聲。","rad":"疒","fq":"五忽切","vol":"07","py":"wù","duan":[{"e":"病也。从𤕫。出聲。","n":"五忽切。十五部。"}]},"疵":{"expl":"病也。从疒此聲。","rad":"疒","fq":"疾咨切","vol":"07","py":"cī","duan":[{"e":"病也。","n":"古亦叚玼爲之。"}]},"癈":{"expl":"固病也。从疒發聲。","rad":"疒","fq":"方肺切","vol":"07","py":"fèi","duan":[{"e":"固病也。","n":"按此當云癈固、病也。癈固爲逗。淺人刪癈字耳。下文痼爲久病。癈固則經傳所云廢疾也。其義不同。鍇本作痼疾也。則尤誤矣。癈猶廢。固猶錮。如瘖、聾、跛、躃、𣃔者、侏儒皆是。癈爲正字。廢爲叚借字。亦有叚癈疾字爲興廢字者。"}]},"艼":{"expl":"艼熒，朐也。从艸丁聲。","rad":"艸","fq":"天經切","vol":"01","py":"tīnɡ","duan":[{"e":"艼熒胊也。","n":"釋艸曰。葋艼熒。未知許於熒字逗。抑以艼逗熒胊也句、與今爾雅異也。"}]},"瘏":{"expl":"病也。从疒者聲。《詩》曰：“我馬瘏矣。”","rad":"疒","fq":"同都切","vol":"07","py":"tú","duan":[{"e":"病也。","n":"周南卷耳曰。我馬瘏矣。釋詁、毛傳皆曰。瘏、病也。豳風鴟鴞傳同。"}]},"瘲":{"expl":"病也。从疒從聲。","rad":"疒","fq":"卽容切","vol":"07","py":"zònɡ","duan":[{"e":"病也。从𤕫。𨑹聲。","n":"將容切。九部。按廣韵、集韵將容切內皆不收此字。葢與瘛瘲爲二病。"}]},"㾕":{"expl":"寒病也。从疒辛聲。","rad":"疒","fq":"所臻切","vol":"07","py":"shěn","duan":[{"e":"寒病也。","n":"古多借洒爲㾕。晉語。狐突曰。玦之以金銑。寒之甚矣。韋注。玦猶離也。銑猶洒也。洒洒、寒皃。唐人舊音云。洒或爲洗。本艸。爲色洗洗是寒皃。玉裁謂。凡素問、靈樞、本艸言洒洒、洗洗者其訓皆寒。皆㾕之叚借。古辛聲、先聲、西聲同在眞文一類。國語注洒音銑。不誤。"}]},"𤷇":{"expl":"頭痛也。从疒或聲。讀若溝洫之洫。","rad":"疒","fq":"吁逼切","vol":"07","py":"xù","duan":[{"e":"頭痛也。从𤕫。或聲。","n":"吁逼切。一部。"}]},"痟":{"expl":"酸痟，頭痛。从疒肖聲。《周禮》曰：“春時有痟首疾。”","rad":"疒","fq":"相邀切","vol":"07","py":"xiāo","duan":[{"e":"酸痟、","n":"逗。"}]},"疕":{"expl":"頭瘍也。从疒匕聲。","rad":"疒","fq":"卑履切","vol":"07","py":"bǐ","duan":[{"e":"頭瘍也。","n":"周禮醫師。凡邦之有疾病疕瘍者造焉。則使醫分而治之。注云。庀、頭瘍。亦謂秃也。"}]},"瘍":{"expl":"頭創也。从疒昜聲。","rad":"疒","fq":"與章切","vol":"07","py":"yánɡ","duan":[{"e":"頭創也。","n":"按頭字葢賸。上文疕下曰頭痬。則見瘍不專在頭矣。鄭注周禮云。身傷曰瘍。以別於頭瘍曰疕。許則曡韵爲訓。疕得𧦝瘍。他瘍不得𧦝疕也。檀弓曰。居喪之禮。身有瘍則浴。"}]},"痒":{"expl":"瘍也。从疒羊聲。","rad":"疒","fq":"似陽切","vol":"07","py":"yánɡ","duan":[{"e":"瘍也。","n":"小雅。癙憂以痒。傳曰。癙、痒、皆病也。釋詁亦曰。痒、病也。按今字以痒爲癢字。非也。癢之正字說文作蛘。"}]},"㾺":{"expl":"目病。一曰惡气箸身也。一曰蝕創。从疒馬聲。","rad":"疒","fq":"莫駕切","vol":"07","py":"mà","duan":[{"e":"目病。一曰惡气箸身也。一曰蝕創。","n":"凡三義。蝕者、敗創也。"}]},"𤺊":{"expl":"散聲。从疒斯聲。","rad":"疒","fq":"先稽切","vol":"07","py":"xī","duan":[{"e":"𢿱聲也。","n":"方言。𤺊、㘆也。楚曰𤺊。又曰。𤺊、散也。東齊聲散曰𤺊。秦晉聲變曰𤺊。器破而不殊、其音亦謂之𤺊。按與斯澌字義相通。馬嘶字亦當作此。"}]},"祝":{"expl":"祭主贊詞者。从示从人口。一曰从兌省。《易》曰：“兌爲口爲巫。”。","rad":"示","fq":"之六切","vol":"01","py":"zhù","duan":[{"e":"祭主贊䛐者。从示。从儿口。","n":"此以三字㑹意。謂以人口交神也。"}]},"蔣":{"expl":"苽蔣也。从艸將聲。","rad":"艸","fq":"子良切","vol":"01","py":"jiānɡ","duan":[{"e":"𤓰也。","n":"各本作𤓰蔣也。此蔣𤓰也之誤倒耳。今依御覽正。蜀都賦曰。攢蔣叢蒲。"}]},"𤺉":{"expl":"口咼也。从疒爲聲。","rad":"疒","fq":"韋委切","vol":"07","py":"wěi","duan":[{"e":"口咼也。","n":"口部曰。咼、口戾不正也。此亦曡韵爲訓。"}]},"疦":{"expl":"𤺉也。从疒，決省聲。","rad":"疒","fq":"古穴切","vol":"07","py":"jué","duan":[{"e":"𤺉也。","n":"廣韵云。瘡裏空也。今義也。"}]},"瘖":{"expl":"不能言也。从疒音聲。","rad":"疒","fq":"於今切","vol":"07","py":"yīn","duan":[{"e":"不能言也。从𤕫。音聲。","n":"於今切。七部。"}]},"癭":{"expl":"頸癅也。从疒嬰聲。","rad":"疒","fq":"於郢切","vol":"07","py":"yǐnɡ","duan":[{"e":"頸癅也。","n":"下文云。癅、腫也。此以頸癅與頸腫別言者、頸癅則如囊者也。頸腫則謂暫時腫脹之疾。故異其辭。釋名曰。癭、嬰也。嬰在頣纓理之中也。靑徐謂之脰。博物志曰。山居多癭。飮水之不流者也。凡楠樹樹根贅肬甚大。析之。中有山川花木之文。可爲器械。吳都賦所謂楠癅之木。三國張昭作楠癅枕賦。今人謂之癭木是也。癭木俗作影木。楠癅俗本作楠橊。皆誤字耳。"}]},"瘻":{"expl":"頸腫也。从疒婁聲。","rad":"疒","fq":"力豆切","vol":"07","py":"lòu","duan":[{"e":"頸腫也。","n":"淮南說山訓。雞頭巳瘻。高注。瘻、頸腫疾也。雞頭、水中芡也。鍇本作頭腫。葢淺人恐與頸癅不別而改之。腫、癰也。頸腫卽釋名之癰㗋。"}]},"𤴨":{"expl":"顫也。从疒又聲。","rad":"疒","fq":"于救切","vol":"07","py":"yòu","duan":[{"e":"顫也。","n":"與頁部？、疣音義同。"}]},"瘀":{"expl":"積血也。从疒於聲。","rad":"疒","fq":"依倨切","vol":"07","py":"yū","duan":[{"e":"積血也。","n":"血積於中之病也。九辯曰。形銷鑠而瘀傷。"}]},"疝":{"expl":"腹痛也。从疒山聲。","rad":"疒","fq":"所妟切","vol":"07","py":"shàn","duan":[{"e":"腹痛也。","n":"釋名曰。心痛曰疝。疝、詵也。氣詵詵然上而痛也。陰腫曰隤。氣下隤也。又曰。疝亦言詵也。詵詵引小腹急痛也。"}]},"疛":{"expl":"小腹病。从疒，肘省聲。","rad":"疒","fq":"陟柳切","vol":"07","py":"zhǒu","duan":[{"e":"小腹病。","n":"小當作心。字之誤也。隷書心或作小。因譌爲小耳。玉篇云。疛、心腹疾也。仍古本也。小雅曰。我心憂傷。惄焉如擣。傳曰。擣、心疾也。釋文。擣本或作㿒。韓詩作疛。義同。按疛其正字。㿒其或體。擣其譌字也。玉篇引呂氏春秋曰。身盡疛腫。今本呂覽作身盡府種。二字皆誤。高誘曰。疛、腹疾也。"}]},"𤼤":{"expl":"滿也。从疒𡚤聲。","rad":"疒","fq":"平祕切","vol":"07","py":"pì","duan":[{"e":"滿也。","n":"毛詩傳曰。不醉而怒曰？。然則？謂氣滿。舉形聲包會意也。"}]},"苽":{"expl":"雕苽。一名蔣。从艸瓜聲。","rad":"艸","fq":"古胡切","vol":"01","py":"ɡū","duan":[{"e":"雕胡。一名蔣。","n":"各本胡字作𤓰。今依御覽正。食醫、内則皆有𤓰食。鄭云。𤓰、彫胡也。廣雅曰。菰、蔣也。其米謂之彫胡。然則猶扶渠實名蓮。亦因以爲華葉名也。彫胡、枚乘七發謂之安胡。其葉曰𤓰、曰蔣。俗曰茭。其中臺如小兒臂。可食。曰𤓰手。其根曰葑。封去聲"}]},"㾈":{"expl":"俛病也。从疒付聲。","rad":"疒","fq":"方榘切","vol":"07","py":"fù","duan":[{"e":"俛病也。","n":"方言曰。短、東陽之閒謂之㾈。按俛者多庳。方言與許義相近。"}]},"痀":{"expl":"曲𦟝也。从疒句聲。","rad":"疒","fq":"其俱切","vol":"07","py":"jū","duan":[{"e":"曲𦟝也。","n":"玉部玖下曰。讀若人句脊之句。二句字皆痀之誤也。"}]},"瘚":{"expl":"屰气也。从疒从屰从欠。","rad":"疒","fq":"居月切","vol":"07","py":"jué","duan":[{"e":"屰气也。","n":"釋名曰。厥、逆氣。從下蹷起。上行入心脅也。高誘呂覽注曰。蹷逆、寒疾也。"}]},"痵":{"expl":"气不定也。从疒季聲。","rad":"疒","fq":"其季切","vol":"07","py":"jì","duan":[{"e":"气不定也。","n":"心部曰。悸、心動也。義相近。玉篇曰。痵亦作悸。"}]},"痱":{"expl":"風病也。从疒非聲。","rad":"疒","fq":"蒲罪切","vol":"07","py":"féi","duan":[{"e":"風病也。","n":"非風雙聲。釋詁曰。痱、病也。郭注見詩。按小雅。百卉具腓。李善注文𨕖戲馬臺詩云。韓詩云百卉具腓。薛君曰。腓、變也。毛萇曰。痱、病也。今本作腓。據李則毛詩本作痱。與釋詁合。"}]},"癅":{"expl":"腫也。从疒畱聲。","rad":"疒","fq":"力求切","vol":"07","py":"liú","duan":[{"e":"腫也。","n":"釋名曰。癅、流也。流聚而生腫也。"}]},"痤":{"expl":"小腫也。从疒坐聲。一曰族絫。","rad":"疒","fq":"昨禾切","vol":"07","py":"cuó","duan":[{"e":"小腫也。","n":"玉篇曰。癤也。"}]},"疽":{"expl":"癰也。从疒且聲。","rad":"疒","fq":"七余切","vol":"07","py":"jū","duan":[{"e":"久癰也。","n":"後漢書劉焉傳注、玄應一切經音義皆引久癰。與小徐合。癰久而潰沮？然也。"}]},"㿛":{"expl":"癰也。从疒麗聲。一曰𤸃黑。讀若隸。","rad":"疒","fq":"郎計切","vol":"07","py":"lì","duan":[{"e":"癰也。从𤕫。麗聲。","n":"郎計切。十六部。"}]},"癰":{"expl":"腫也。从疒雝聲。","rad":"疒","fq":"於容切","vol":"07","py":"yōnɡ","duan":[{"e":"腫也。","n":"肉部曰。腫、癰也。按腫之本義謂癰。引伸之爲凡墳起之名。如上文癅、腫也。痤、小腫也。則非謂癰也。釋名曰。癰、壅也。氣壅否結裏而潰也。"}]},"𦱀":{"expl":"艸也。从艸育聲。","rad":"艸","fq":"余六切","vol":"01","py":"yù","duan":[{"e":"艸也。从艸。育聲。","n":"余六切。三部。"}]},"瘜":{"expl":"寄肉也。从疒息聲。","rad":"疒","fq":"相卽切","vol":"07","py":"xī","duan":[{"e":"寄肉也。","n":"肉部腥下曰。星見食豕。令肉中生小息肉也。息肉卽瘜肉。廣韵曰。惡肉。"}]},"癬":{"expl":"乾瘍也。从疒鮮聲。","rad":"疒","fq":"息淺切","vol":"07","py":"xuǎn","duan":[{"e":"乾瘍也。","n":"乾音干。瘍之乾者也。釋名曰。癬、徙也。浸淫移徙處日廣也。故靑徐謂癬爲徙也。"}]},"疥":{"expl":"搔也。从疒介聲。","rad":"疒","fq":"古拜切","vol":"07","py":"jiè","duan":[{"e":"搔也。","n":"搔音穌到切。疥急於搔。因謂之搔。俗作瘙。或作㿋。穌到切。今四川人語如此。禮記釋文引說文疥、瘙瘍也。文𨕖登徒子好色賦注引疥、瘙也。皆以俗字改正字耳。後漢書烏桓傳曰。手足之蚧搔。章懷音新到反。蚧同疥。釋名曰。疥、齘也。癢搔之齒䫴齘也。"}]},"痂":{"expl":"疥也。从疒加聲。","rad":"疒","fq":"古牙切","vol":"07","py":"jiā","duan":[{"e":"疥也。","n":"按痂本謂疥。後人乃謂瘡所蛻鱗爲痂。此古義今義之不同也。葢瘡鱗可曰介。介與痂雙聲之故耳。南史。劉邕嗜食瘡痂。謂有蝮魚味。"}]},"瘕":{"expl":"女病也。从疒叚聲。","rad":"疒","fq":"乎加切","vol":"07","py":"xiá","duan":[{"e":"女病也。","n":"按女字必是衍字。詩。厲假不瑕。箋云。厲、假、皆病也。正義引說文。癘疫、病也。或作癩瘕、病也。是唐初本無女字也。倉公傳曰。潘滿如小腹痛。臣意診其脈曰。遺積瘕也。女子薄吾病甚。臣意診其脈曰。蟯瘕也。瘕葢腹中病。"}]},"癘":{"expl":"惡疾也。从疒，蠆省聲。","rad":"疒","fq":"洛帶切","vol":"07","py":"lì","duan":[{"e":"惡疾也。","n":"按古義謂惡病包內外言之。今義別製癩字訓爲惡瘡。訓癘爲癘疫。古多借厲爲癘。公羊傳作㾐。何注云。㾐者、民疾疫也。大戴禮及公羊何注說七出皆云。惡疾出。何休曰。惡疾棄者不可以奉宗廟也。論語。伯牛有疾。苞氏曰。牛有惡疾。不欲見人。故孔子從牖執其手也。韓詩曰。芣苢、傷夫有惡疾也。薛君曰。芣苢、澤瀉也。臭惡之草。詩人傷其君子有惡疾。人道不通。求己不得。發憤而作。以事興。芣苢雖臭惡乎。我猶采采而不巳者。以興君子雖有惡疾。我猶守而不離去也。"}]},"瘧":{"expl":"熱寒休作。从疒从虐，虐亦聲。","rad":"疒","fq":"魚約切","vol":"07","py":"nüè","duan":[{"e":"寒𤍽休作病。","n":"謂寒與𤍽一休一作相代也。釋名曰。瘧、酷虐也。凡疾或寒或、𤍽耳。而此疾先寒後𤍽。兩疾似酷虐者。周禮曰。秋時有瘧寒疾。"}]},"痁":{"expl":"有熱瘧。从疒占聲。《春秋傳》曰：“齊侯疥，遂痁。”","rad":"疒","fq":"失廉切","vol":"07","py":"shān","duan":[{"e":"有𤍽瘧。","n":"有𤍠無寒之瘧也。"}]},"痎":{"expl":"二日一發瘧。从疒亥聲。","rad":"疒","fq":"古諧切","vol":"07","py":"jiē","duan":[{"e":"二日一發瘧也。","n":"今人謂閒二日一發爲大瘧。顔之推云。兩日一發之瘧。今北方猶呼痎瘧。音皆。"}]},"痳":{"expl":"疝病。从疒林聲。","rad":"疒","fq":"力尋切","vol":"07","py":"lín","duan":[{"e":"疝病也。","n":"釋名曰。淋、懍也。小便難懍懍然也。按痳篆不與疝伍者、以有疝痛而不痳者也。"}]},"藣":{"expl":"艸也。从艸罷聲。","rad":"艸","fq":"符羈切","vol":"01","py":"bēi","duan":[{"e":"艸也。","n":"爾雅釋器。旄謂之藣、作此字。假借爲麾字也。"}]},"痔":{"expl":"後病也。从疒寺聲。","rad":"疒","fq":"直里切","vol":"07","py":"zhì","duan":[{"e":"後病也。从𤕫。寺聲。","n":"直理切。一部。"}]},"痿":{"expl":"痹也。从疒委聲。","rad":"疒","fq":"儒隹切","vol":"07","py":"wěi","duan":[{"e":"痹也。","n":"如淳曰。痿音𨆌踒弩。病兩足不能相過曰痿。張揖曰。痿不能行。師古曰。𨆌踒、弩名。見晉令。煩蕤二音。按古多痿？聯言。因？而痿也。素問曰。有漸於濕。肌肉濡潰。？而不仁。發爲肉痿。"}]},"痹":{"expl":"溼病也。从疒𢌿聲。","rad":"疒","fq":"必至切","vol":"07","py":"bì","duan":[{"e":"溼病也。","n":"素問痹論、痿論各爲篇。岐伯曰。風寒溼三氣襍至。合而爲？也。"}]},"𤹝":{"expl":"足气不至也。从疒畢聲。","rad":"疒","fq":"钎至切","vol":"07","py":"bì","duan":[{"e":"足氣不至也。","n":"玉篇云。足氣不至、轉筋也。"}]},"瘃":{"expl":"中寒腫覈。从疒豖聲。","rad":"疒","fq":"陟玉切","vol":"07","py":"zhú","duan":[{"e":"中寒腫覈。","n":"趙充國傳。手足皸瘃。文穎曰。、寒創也。按腫覈者、腫而肉中鞕如果中有覈也。覈核古今字。"}]},"㾫":{"expl":"半枯也。从疒扁聲。","rad":"疒","fq":"匹連切","vol":"07","py":"piān","duan":[{"e":"半枯也。","n":"尙書大傳。禹其跳。湯扁。其跳者、踦也。鄭注云。其、發聲也。踦、步足不能相過也。扁者、枯也。注言湯體半小扁枯。按扁卽㾫字之叚借。㾫之言偏也。"}]},"𤺄":{"expl":"脛气足腫。从疒童聲。《詩》曰：“旣微且𤺄。”","rad":"疒","fq":"時重切","vol":"07","py":"zhǒnɡ","duan":[{"e":"脛气腫。","n":"小雅巧言。旣微且尰。釋訓、毛傳皆曰。骭瘍爲微。腫足爲尰。按云脛氣腫卽足腫也。大徐本云脛氣足腫。非。"}]},"𤸱":{"expl":"跛病也。从疒盍聲。讀若脅，又讀若掩。","rad":"疒","fq":"烏盍切","vol":"07","py":"è","duan":[{"e":"跛病也。","n":"廣韵曰。𤸱、短氣也。此今義也。"}]},"疻":{"expl":"毆傷也。从疒只聲。","rad":"疒","fq":"諸氏切","vol":"07","py":"zhǐ","duan":[{"e":"疻痏、","n":"逗。"}]},"痏":{"expl":"疻痏也。从疒有聲。","rad":"疒","fq":"榮美切","vol":"07","py":"wěi","duan":[{"e":"疻痏也。","n":"按依許全書之例。則疻下云疻痏、毆傷也。此但云疻痏也。而義巳足。此等往往爲淺人妄刪。致文理不可讀矣。或曰依應仲遠則疻痏異事。何爲合之也。曰。應析言之。許渾言之。許曰毆傷。則固兼無創瘢、有創瘢者言之。文𨕖注引倉頡篇。痏、毆傷也。與許正合。"}]},"䕼":{"expl":"艸也。从艸難聲。","rad":"艸","fq":"如延切","vol":"01","py":"rán","duan":[{"e":"艸也。从艸。難聲。","n":"如延切。十四部。火部？以爲聲。"}]},"𤼒":{"expl":"創裂也。一曰疾𤼒。从疒巂聲。","rad":"疒","fq":"以水切","vol":"07","py":"wěi","duan":[{"e":"創裂也。一曰疾𤼒。","n":"玉篇作一曰疾也。"}]},"𤴿":{"expl":"皮剥也。从疒冄聲。","rad":"疒","fq":"赤占切","vol":"07","py":"chān","duan":[{"e":"皮剝也。","n":"剝、裂也。"}]},"癑":{"expl":"痛也。从疒䢉聲。","rad":"疒","fq":"奴動切","vol":"07","py":"nònɡ","duan":[{"e":"痛也。从𤕫。䢉聲。","n":"奴動切。九部。"}]},"痍":{"expl":"傷也。从疒夷聲。","rad":"疒","fq":"以脂切","vol":"07","py":"yí","duan":[{"e":"傷也。","n":"成十六年。晉矦及楚子、鄭伯戰于鄢陵。楚子、鄭師敗績。公羊傳曰。敗者稱師。楚何以不稱師。王痍也。王痍者何。傷乎矢也。按周易夷傷也、左傳察夷傷皆假夷字爲之。"}]},"瘢":{"expl":"痍也。从疒般聲。","rad":"疒","fq":"薄官切","vol":"07","py":"bān","duan":[{"e":"痍也。","n":"長楊賦。𠵷鋋瘢耆。孟康曰。瘢耆、馬脊耆創瘢處。按古義傷處曰瘢。今義則少異。"}]},"痕":{"expl":"胝瘢也。从疒艮聲。","rad":"疒","fq":"戶恩切","vol":"07","py":"hén","duan":[{"e":"胝瘢也。","n":"胝瘢謂胝之傷。肉部腄下云。瘢胝也。與此同義。胝下云。腄也。則不必傷者也。按今義與此亦異。皆逐末而忘本也。韵會無胝字。"}]},"痙":{"expl":"彊急也。从疒巠聲。","rad":"疒","fq":"其頸切","vol":"07","py":"jìnɡ","duan":[{"e":"彊急也。","n":"本艸經曰。术主痙疸。廣韵曰。風强病也。按急就篇。癰疽瘛瘲痿？？。？卽痙。顔云。體强急。難用屈伸也。"}]},"痋":{"expl":"動病也。从疒，蟲省聲。","rad":"疒","fq":"徒冬切","vol":"07","py":"tónɡ","duan":[{"e":"動病也。","n":"痋卽疼字。釋名曰。疼、旱氣疼疼然煩也。按詩。旱旣太甚。蘊隆蟲蟲。韓詩作鬱隆烔烔。劉成國作疼疼。皆旱熱人不安之皃也。今義疼訓痛。"}]},"𤸃":{"expl":"臞也。从疒叜聲。","rad":"疒","fq":"所又切","vol":"07","py":"shòu","duan":[{"e":"臞也。","n":"肉部曰。臞、少肉也。"}]},"疢":{"expl":"熱病也。从疒从火。","rad":"疒","fq":"丑刃切","vol":"07","py":"chèn","duan":[{"e":"熱病也。","n":"其字从火。故知爲熱病。小雅。疢如疾首。箋云。疢猶病也。此以疢爲煩熱之偁。"}]},"莨":{"expl":"艸也。从艸良聲。","rad":"艸","fq":"魯當切","vol":"01","py":"lánɡ","duan":[{"e":"艸也。","n":"子虛賦。卑溼則生藏莨。漢書音義曰。莨、莨尾艸也。按釋艸曰。孟狼尾。狼與莨同音。狼尾似狗尾而麤壯者也。孟作盂者譌。"}]},"癉":{"expl":"勞病也。从疒單聲。","rad":"疒","fq":"丁榦切","vol":"07","py":"dàn","duan":[{"e":"勞病也。","n":"大雅。下民卒癉。釋詁、毛傳皆云。癉、病也。小雅。哀我癉人。釋詁、毛傳曰。癉、勞也。許合云勞病者、如嘽訓喘息皃、幝訓車敝皃皆單聲字也。癉與疸音同而義別。如郭注山海經、師古注漢書皆云。癉、黃病。王砅注素問黃疸云。疸、勞也。則二字互相假而淆惑矣。癉或假憚。或作𤺺。"}]},"疸":{"expl":"黃病也。从疒旦聲。","rad":"疒","fq":"丁榦切","vol":"07","py":"dǎn","duan":[{"e":"黃病也。","n":"素問曰。溺黃赤安臥者黃疸。目黃者曰黃疸。"}]},"㾜":{"expl":"病息也。从疒夾聲。","rad":"疒","fq":"苦叶切","vol":"07","py":"qiè","duan":[{"e":"病息也。","n":"病息謂病之鼻息也。心部瘱从此。"}]},"痞":{"expl":"痛也。从疒否聲。","rad":"疒","fq":"符鄙切","vol":"07","py":"pǐ","duan":[{"e":"痛也。","n":"廣韵曰。腹內結痛。"}]},"痬":{"expl":"脈痬也。从疒易聲。","rad":"疒","fq":"羊益切","vol":"07","py":"yì","duan":[{"e":"脈痬也。","n":"脈痬曡韵字。脈痬者、善驚之病也。方言曰。脈痬、欺漫也。又曰。衇、慧也。郭注。今名黠爲鬼衇。又曰。慧、自關而東趙魏之閒謂之黠。或謂之鬼。郭注。言鬼脈也。潘岳賦。靡聞而驚。無見自脈。徐爰注言雉性驚鬼黠。按蜥蜴跂跂脈脈亦是此意。漢書所云易病者、當是痬之叚借。王子矦表樂平矦訢病狂易。"}]},"㾁":{"expl":"狂走也。从疒术聲。讀若欻。","rad":"疒","fq":"食聿切","vol":"07","py":"shù","duan":[{"e":"狂走也。","n":"春秋經。甲戍、已丑。陳疾鮑卒。公羊傳曰。曷爲以二日卒之。㤜也。注曰。㤜者、狂也。齊人語。甲戍之日亡。己丑之日死。而得。君子疑焉。故以二日卒之也。按？㤜葢同字。"}]},"疲":{"expl":"勞也。从疒皮聲。","rad":"疒","fq":"符羈切","vol":"07","py":"pí","duan":[{"e":"勞也。","n":"經傳多假罷爲之。"}]},"㾅":{"expl":"瑕也。从疒𠂔聲。","rad":"疒","fq":"側史切","vol":"07","py":"zǐ","duan":[{"e":"瑕也。","n":"古本皆作瑕。惟小徐及毛本及集韵作瘕。恐是譌字耳。？之言疵也。"}]},"疧":{"expl":"病也。从疒氏聲。","rad":"疒","fq":"渠支切","vol":"07","py":"qí","duan":[{"e":"病不翅也。","n":"翅同啻。口部啻下曰。語時不啻也。倉頡篇曰。不啻、多也。古語不啻、如楚人言夥頤之類。世說新語云。王文度弟阿至惡乃不翅。晉宋閒人尙作此語。帝聲、支聲、氏聲同在十六部。故疧以病不翅釋之。取曡韵爲訓也。爾雅釋詁、詩無將大車白華傳皆云。疧、病也。何人斯叚借祇爲疧。故毛傳曰。祇、病也。言假借也。又按古書或言不啻。或言奚啻。啻皆或作翅。國語曰。奚啻其聞之也。韋注云。奚、何也。何啻、言所聞非一也。孟子。奚翅食重。奚翅色重。趙注。翅、辭也。若言何其重也。今刻本作何其不重也。乃大誤。"}]},"㽺":{"expl":"病劣也。从疒及聲。","rad":"疒","fq":"呼合切","vol":"07","py":"jí","duan":[{"e":"病劣也。","n":"劣猶危也。"}]},"葽":{"expl":"艸也。从艸要聲。《詩》曰：“四月秀葽。”劉向說：此味苦，苦葽也。","rad":"艸","fq":"於消切","vol":"01","py":"yāo","duan":[{"e":"艸也。从艸。要聲。","n":"於消切。二部。"}]},"㿄":{"expl":"劇聲也。从疒殹聲。","rad":"疒","fq":"於賣切","vol":"07","py":"ài","duan":[{"e":"劇聲也。","n":"劇者、病甚也。㿄者、病甚呻吟之聲。酉部醫下曰。殹、病聲也。殹葢㿄之省。"}]},"癃":{"expl":"罷病也。从疒隆聲。","rad":"疒","fq":"力中切","vol":"07","py":"lónɡ","duan":[{"e":"罷病也。","n":"病當作癃。罷者、廢置之意。凡廢置不能事事曰罷癃。平原君傳。躄者自言不幸有罷癃之病。然則凡廢疾皆得謂之罷癃也。師古注漢書。改罷病作疲病。非許意。"}]},"疫":{"expl":"民皆疾也。从疒，役省聲。","rad":"疒","fq":"營隻切","vol":"07","py":"yì","duan":[{"e":"民皆疾也。","n":"鄭注周禮兩言疫癘之鬼。"}]},"瘛":{"expl":"小兒瘛瘲病也。从疒恝聲。","rad":"疒","fq":"尺制切","vol":"07","py":"chì","duan":[{"e":"小兒瘛瘲病也。","n":"急就篇亦云瘛瘲。師古云。卽今癇病。按今小兒驚病也。瘛之言掣也。瘲之言縱也。蓺文志有瘛瘲方。"}]},"痑":{"expl":"馬病也。从疒多聲。《詩》曰：“痑痑駱馬。”","rad":"疒","fq":"丁可切","vol":"07","py":"duò","duan":[{"e":"馬病也。从𤕫。多聲。","n":"丁可切。十七部。"}]},"痥":{"expl":"馬脛瘍也。从疒兌聲。一曰將傷。","rad":"疒","fq":"徒活切","vol":"07","py":"duó","duan":[{"e":"馬脛瘍也。","n":"痬廣韵作傷。"}]},"𤻲":{"expl":"治也。从疒樂聲。","rad":"疒","fq":"力照切","vol":"07","py":"liáo","duan":[{"e":"治也。","n":"方言曰。療、治也。周禮注云。止病曰療。詩陳風。泌之洋洋。可以樂饑。傳云。可以樂道忘饑。箋云。可飮以𤻲饑。是鄭讀樂爲𤻲也。經文本作樂。唐石經依鄭改爲𤻲。誤矣。"}]},"㽽":{"expl":"久病也。从疒古聲。","rad":"疒","fq":"古慕切","vol":"07","py":"ɡù","duan":[{"e":"久病也。","n":"多假固爲之。月令。十二月行春令。則國多固疾。注曰。生不充其性。有久疾。癈疾爲錮疾。痼謂久疾。故許異其義。"}]},"瘌":{"expl":"楚人謂藥毒曰痛瘌。从疒剌聲。","rad":"疒","fq":"盧達切","vol":"07","py":"là","duan":[{"e":"楚人謂藥毒曰痛瘌。","n":"方言曰。凡飮藥傅藥而毒、南楚之外謂之剌。北燕朝鮮之閒謂之癆。東齊海岱之閒謂之眠。或謂之眩。自關而西謂之毒瘌。痛也。郭云。癆、瘌皆辛螫也。按瘌如俗語言辛辣。"}]},"癆":{"expl":"朝鮮謂藥毒曰癆。从疒勞聲。","rad":"疒","fq":"郎到切","vol":"07","py":"lào","duan":[{"e":"朝鮮謂藥毒曰癆。从𤕫。勞聲。","n":"郎到切。二部。郭音𦕼。"}]},"薖":{"expl":"艸也。从艸過聲。","rad":"艸","fq":"苦禾切","vol":"01","py":"kē","duan":[{"e":"艸也。","n":"衞風碩人之薖。假借此字。毛云。寬大皃。鄭云饑意。按毛、鄭意謂薖爲款之假借。爾雅款足者謂之鬲。漢志作空足曰鬲。楊王孫傳。窾木爲匵。服虔曰。窾、空也。淮南書窾者主浮注。窾、空也。讀如科條之科。然則薖款古同音。許君亦曰。窠、空也。毛、鄭說皆取空中之意。"}]},"瘥":{"expl":"瘉也。从疒𢀩聲。","rad":"疒","fq":"楚懈切","vol":"07","py":"chài","duan":[{"e":"瘉也。","n":"通作差。凡等差字皆引伸於瘥。"}]},"𤸬":{"expl":"減也。从疒衰聲。一曰耗也。","rad":"疒","fq":"楚追切","vol":"07","py":"shuāi","duan":[{"e":"減也。","n":"減亦謂病減於常也。凡盛衰字引伸於？。凡等衰字亦引伸於？。凡喪服曰衰者、謂其有等衰也。皆？之叚借。"}]},"瘉":{"expl":"病瘳也。从疒俞聲。","rad":"疒","fq":"以主切","vol":"07","py":"yù","duan":[{"e":"病瘳也。","n":"釋詁及小雅角弓毛傳皆曰。瘉、病也。渾言之謂瘳而尙病也。許則析言之謂雖病而瘳也。凡訓勝、訓賢之愈皆引伸於瘉。愈卽瘉字也。"}]},"瘳":{"expl":"疾瘉也。从疒翏聲。","rad":"疒","fq":"敕鳩切","vol":"07","py":"chōu","duan":[{"e":"疾瘉也。","n":"二字互訓也。"}]},"癡":{"expl":"不慧也。从疒疑聲。","rad":"疒","fq":"丑之切","vol":"07","py":"chī","duan":[{"e":"不慧也。","n":"心部曰。慧者、獧也。犬部曰。獧者、急也。癡者、遅鈍之意。故與慧正相反。此非疾病也。而亦疾病之類也。故以是終焉。"}]},"冖":{"expl":"覆也。从一下垂也。凡冖之屬皆从冖。","rad":"冖","fq":"莫狄切","vol":"07","py":"mì","duan":[{"e":"覆也。","n":"覆者、葢也。"}]},"冠":{"expl":"絭也。所以絭髮，弁冕之緫名也。从冂从元，元亦聲。冠有法制，从寸。","rad":"冖","fq":"古丸切","vol":"07","py":"ɡuān","duan":[{"e":"絭也。","n":"曡韵爲訓。"}]},"冣":{"expl":"積也。从冂从取，取亦聲。","rad":"冖","fq":"才句切","vol":"07","py":"jù","duan":[{"e":"積也。","n":"冣與聚音義皆同。與冃部之最音義皆別。公羊傳曰。會猶冣也。何云。冣之爲言聚。周禮太宰注曰。凡簿書之冣目。劉歆與楊雄書𡩡方言曰。欲得其冣目。又曰。頗願與其冣目。得使入錄。按凡言冣目者、猶今言摠目也。史記殷本紀。大冣樂戲於沙丘。冣一作聚。張釋之馮唐列傳。誅李牧。令顔聚代之。漢書聚作冣。爾雅。灌木、叢木也。毛傳叢木作冣木。說文凡字下曰冣桰也。儹字下曰冣也。史記周本紀周冣。文𨕖過秦論周冣。今各書此等冣字皆譌作最。讀祖會反。音義俱非。葢字林固有冣字。音才句反。見李善𨕖注。至乎南北朝。冣最不分。是以周續之、劉昌宗、陸德明輩皆不能知毛傳之本作冣木。顧野王玉篇冖部無冣。而冃部有最。云齊也。聚也。廣韵本唐韵。而廣"}]},"㓃":{"expl":"奠爵酒也。从冂託聲。《周書》曰：“王三㝛三祭三㓃。”","rad":"冖","fq":"當故切","vol":"07","py":"dù","duan":[{"e":"奠酒爵也。","n":"大徐作奠爵酒。今依韵會所據訂。周書顧命曰。王三宿三祭三㓃。某氏注曰。酌者實三爵於王。王三進爵。三祭酒。三奠爵。？部曰。奠、置也。"}]},"𠔼":{"expl":"重覆也。从冂、一。凡𠔼之屬皆从𠔼。讀若艸苺苺。","rad":"𠔼","fq":"莫𠈃切","vol":"07","py":"mǎo","duan":[{"e":"重覆也。","n":"下一覆也。上又加冖。是爲重覆。"}]},"菌":{"expl":"地蕈也。从艸囷聲。","rad":"艸","fq":"渠殞切","vol":"01","py":"jùn","duan":[{"e":"地蕈也。","n":"屮部所謂菌圥也。"}]},"同":{"expl":"合會也。从𠔼从口。","rad":"𠔼","fq":"徒紅切","vol":"07","py":"tónɡ","duan":[{"e":"合會也。从𠔼口。","n":"口皆在所覆之下。是同之意也。徒紅切。九部。"}]},"𡉉":{"expl":"幬帳之象。从𠔼；㞢，其飾也。","rad":"𠔼","fq":"苦江切","vol":"07","py":"què","duan":[{"e":"𢅂帳之象。","n":"巾部曰。𢅂、襌帳也。帳、張也。"}]},"冡":{"expl":"覆也。从𠔼、豕。","rad":"𠔼","fq":"莫紅切","vol":"07","py":"ménɡ","duan":[{"e":"覆也。","n":"凡蒙覆、僮蒙之字今字皆作蒙。依古當作冡。蒙行而冡廢矣。艸部蒙、艸名也。"}]},"冃":{"expl":"小兒蠻夷頭衣也。从冂；二，其飾也。凡冃之屬皆从冃。","rad":"冃","fq":"莫報切","vol":"07","py":"mào","duan":[{"e":"小兒及蠻夷頭衣也。","n":"謂此二種人之頭衣也。小兒未冠。夷狄未能言冠。故不冠而冃。荀卿曰。古之王者有務而拘領者矣。楊注。務讀爲冒。拘與勾同。淮南書曰。古者有鍪而綣領以王天下者。高注。古者、葢三？以前也。鍪著兜鍪帽。言未知制冠。按高注兜鍪二字葢淺人所加。務與鍪皆讀爲冃。冃卽今之帽字也。後聖有作。因冃以制冠冕。而冃遂爲小兒蠻夷頭衣。"}]},"冕":{"expl":"大夫以上冠也。邃延、垂瑬、紞纊。从冃免聲。古者黃帝初作冕。","rad":"冃","fq":"亡辡切","vol":"07","py":"miǎn","duan":[{"e":"大夫㠯上冠也。","n":"冠下曰。弁冕之摠名。渾言之也。此云冕者、大夫以上冠。析言之也。大夫㠯上有冕則士無冕可知矣。周禮。王之五冕皆玄冕朱裏延紐。五采繅十有二就。皆五采玉十有二。玉筓朱紘。諸侯之繅斿九就。琘玉三采。其餘如王之事。繅斿皆就。戴先生曰。實六冕而曰五冕者、陳采就玉之數止於五也。亦以見服自十二章至一章而六。冕璪自十二旒至三旒而五。其天子大裘之冕無旒也。槩舉諸侯又申之曰繅斿皆就者、明九旒至於三旒。其就數九。公侯伯子男無降差同也。"}]},"冒":{"expl":"冡而前也。从冃从目。","rad":"冃","fq":"莫報切","vol":"07","py":"mào","duan":[{"e":"冡而前也。","n":"冡者、覆也。引伸之有所干犯而不顧亦曰冒。如假冒、如冒白刃、如貪冒是也。邶風。下土是冒。傳曰。冒、覆也。此假冒爲冃也。"}]},"最":{"expl":"犯而取也。从冃从取。","rad":"冃","fq":"祖外切","vol":"07","py":"zuì","duan":[{"e":"犯取也。","n":"鍇曰。犯而取也。按犯而取猶冡而前。冣之字訓積。最之字訓犯取。二字義殊而音亦殊。顔氏家訓謂冣爲古聚字。手部撮字从最爲音義。皆可證也。今小徐本此下多又曰會三字。係淺人增之。韵會無之。是也。最、俗作㝡。六朝如此作。○莊子秋水。鴟鵂夜撮蚤。察毫末。晝出。瞋目而不見丘山。釋文。撮、崔本作最。此可證最撮古音同。蚤謂齧人跳蟲也。或誤爲聚爪。云夜入人家。𡩡人指甲。可𥬇也。"}]},"㒳":{"expl":"再也。从冂，闕。《易》曰：“參天㒳地。”凡㒳之屬皆从㒳。","rad":"㒳","fq":"良奬切","vol":"07","py":"liǎnɡ","duan":[{"e":"再也。","n":"爯部曰。再者、一舉而二也。凡物有二。其字作㒳不作兩。兩者、二十四銖之偁也。今字兩行而㒳廢矣。"}]},"兩":{"expl":"二十四銖爲一兩。从一；㒳，平分，亦聲。","rad":"㒳","fq":"良奬切","vol":"07","py":"liǎnɡ","duan":[{"e":"二十四銖爲一兩。","n":"一字衍。禾部曰。十二粟爲一分。十二分爲一銖。律曆志曰。衡權本起於黃鍾之重。一龠容千二百黍。重十二銖。兩之爲兩。二十四銖爲兩。按兩者、㒳黃鍾之重。故从㒳也。"}]},"蕈":{"expl":"桑䓴。从艸覃聲。","rad":"艸","fq":"慈衽切","vol":"01","py":"xùn","duan":[{"e":"桑䓴也。","n":"䓴之生於桑者曰蕈。蕈之生於田中者曰菌圥。鄭司農注周禮云深蒲。或曰桑耳。"}]},"㒼":{"expl":"平也。从廿，五行之數，二十分爲一辰。㒳，㒼平也。讀若蠻。","rad":"㒳","fq":"母官切","vol":"07","py":"mán","duan":[{"e":"平也。","n":"廣韵曰。無穿孔狀。按周禮鼈人。掌取互物。注云。互物謂有甲䓣胡。龜鼈之屬。"}]},"网":{"expl":"庖犧所結繩以漁。从冂，下象网交文。凡网之屬皆从网。(今經典變隸作䍏。)","rad":"网","fq":"文紡切","vol":"07","py":"wǎnɡ","duan":[{"e":"庖犧氏所結繩㠯田㠯漁也。","n":"以田二字依廣韵太平御覽補。周易𣪠辭傳文。"}]},"罨":{"expl":"䍑也。从网奄聲。","rad":"网","fq":"於業切","vol":"07","py":"yǎn","duan":[{"e":"䍐也。","n":"蜀都賦曰。？翡翠。"}]},"䍑":{"expl":"网也。从网干聲。","rad":"网","fq":"呼旱切","vol":"07","py":"hǎn","duan":[{"e":"网也。","n":"謂网之一也。吳都賦注曰。罼、䍐皆鳥網也。按䍐之制葢似畢。小网長柄。故天官書畢曰䍐車。經傳叚爲尟字。故釋、詁云。希、寡、鮮、䍐也。"}]},"𦌾":{"expl":"网也。从网、繯，繯亦聲。一曰綰也。","rad":"网","fq":"古眩切","vol":"07","py":"juàn","duan":[{"e":"网也。","n":"网之一也。"}]},"䍙":{"expl":"网也。从网𣫭聲。","rad":"网","fq":"莫桮切","vol":"07","py":"méi","duan":[{"e":"网也。","n":"网之一也。篇、韵皆曰雉网。"}]},"𦌔":{"expl":"网也。从网巽聲。","rad":"网","fq":"思沇切","vol":"07","py":"xuǎn","duan":[{"e":"网也。","n":"网之一也。"}]},"䍘":{"expl":"周行也。从网米聲。《詩》曰：“𦊮入其阻。”","rad":"网","fq":"武移切","vol":"07","py":"mí","duan":[{"e":"网也。","n":"各本作周行也。詩釋文引作冒也。乃涉鄭箋而誤。今尋上下文皆网名。篇、韵皆云。䍘、罟也。更正。葢䍘亦网名。其用主自上冒下。故鄭氏箋詩殷武。改毛之？入其阻爲䍘入。云冒也。就字本義引伸之。此鄭箋之易舊。非經本有作䍘者也。各本米聲下有詩曰䍘入其阻六字。似許用鄭本。恐後人所增。今刪。"}]},"罩":{"expl":"捕魚器也。从网卓聲。","rad":"网","fq":"都教切","vol":"07","py":"zhào","duan":[{"e":"捕魚器也。","n":"小雅南有嘉魚。烝然罩罩。釋器曰。籗謂之罩。毛傳曰。罩、籗也。劉逵吳都賦注曰。罩、籗也。編竹籠魚者也。按竹部曰。籱、罩魚者也。"}]},"罾":{"expl":"魚网也。从网曾聲。","rad":"网","fq":"作騰切","vol":"07","py":"zēnɡ","duan":[{"e":"魚网也。","n":"文穎曰。罾、魚網也。師古曰。形如仰繖。葢四維而舉之。"}]},"𥛽":{"expl":"祝𥛽也。从示畱聲。","rad":"示","fq":"力救切","vol":"01","py":"liù","duan":[{"e":"祝𥛽也。","n":"惠氏士奇曰。素問黃帝曰。古之治病、可祝由而已。祝由、卽祝𥛽也。已、止也。玉裁按。玉篇曰。古文作䄂。"}]},"䓴":{"expl":"木耳也。从艸耎聲。一曰萮茈。","rad":"艸","fq":"而兖切","vol":"01","py":"ruǎn","duan":[{"e":"木耳也。","n":"内則記燕食所加庶羞有芝栭。正義曰。盧植云。芝、木芝也。王肅云。無華而實者名栭。按芝栭猶攷工記之之而。鄭君謂芝栭爲一物。栭卽䓴字也。今人謂光滑者木耳。皴者蕈。許意謂蕈爲木耳。"}]},"罪":{"expl":"捕魚竹网。从网、非。秦以罪爲辠字。","rad":"网","fq":"徂賄切","vol":"07","py":"zuì","duan":[{"e":"捕魚竹网。","n":"竹字葢衍。小徐無竹网二字。"}]},"罽":{"expl":"魚网也。从网㓹聲。㓹，籒文銳。","rad":"网","fq":"居例切","vol":"07","py":"jì","duan":[{"e":"魚网也。","n":"廣雅。罽、罔也。"}]},"罛":{"expl":"魚罟也。从网瓜聲。《詩》曰：“施罛濊濊。”","rad":"网","fq":"古胡切","vol":"07","py":"ɡū","duan":[{"e":"魚罟也。","n":"衛風碩人曰。施罟濊濊。釋器、毛傳皆曰。罛、魚罟。"}]},"罟":{"expl":"网也。从网古聲。","rad":"网","fq":"公戶切","vol":"07","py":"ɡǔ","duan":[{"e":"网也。","n":"小雅小明傳曰。罟、网也。按不言魚网者。易曰。作結繩而爲网罟。以田以漁。是网罟皆非專施於漁也。罟實魚网。而鳥獸亦用之。故下文有鳥罟、兔罟。"}]},"羀":{"expl":"曲梁寡婦之笱。魚所畱也。从网、畱，畱亦聲。","rad":"网","fq":"力九切","vol":"07","py":"liǔ","duan":[{"e":"曲梁寡婦之笱。魚所畱也。","n":"釋訓曰。凡曲者爲？。釋器曰。嫠婦之笱謂之？。小雅魚麗、苕華傳合之曰。？、曲梁也。寡婦之笱也。許說本之。按邶風傳云。梁、魚梁。衛風傳曰。石絕水曰梁。曹風傳云。梁、水中之梁。邶風傳云。笱所以捕魚也。句部云。笱、曲竹捕魚也。葢曲梁別於凡梁。寡婦之笱別於凡笱。曲梁者、僅以薄爲之。寡婦之笱、笱之敝者也。魚麗、美物盛多能？禮也。故言此曲梁寡婦之笱。而魚之多如是。苕之華、大夫閔時也。師旅並起。因之以飢饉。言三星在？。則無魚可知也。梁與笱相爲用。故詩云敝笱在梁。言逝梁必言發笱。若魯語曰。古者大寒降。土蟄發。水虞於是乎講罛？。取名魚。則非止曲梁寡婦之笱矣。"}]},"罜":{"expl":"罜䍡，魚罟也。从网主聲。","rad":"网","fq":"之庾切","vol":"07","py":"zhǔ","duan":[{"e":"罜䍡、","n":"逗。"}]},"䍡":{"expl":"罜䍡也。从网鹿聲。","rad":"网","fq":"盧谷切","vol":"07","py":"lù","duan":[{"e":"罜䍡也。从网。鹿聲。","n":"盧谷切。三部。"}]},"罧":{"expl":"積柴水中以聚魚也。从网林聲。","rad":"网","fq":"所今切","vol":"07","py":"shèn","duan":[{"e":"積柴水中㠯聚魚也。从网。林聲。","n":"毛詩。潛有多魚。韓詩潛作涔。釋器曰。糝謂之涔。毛傳曰。潛、糝也。爾雅、毛傳糝本从米。舍人、李巡皆云。以米投水中養魚曰涔。从米是也。自小爾雅改作槮。改米爲木云橬、改水爲木槮也。積柴水中而魚舍焉。郭景純因之云。今之作槮者。聚積柴木於水。魚得寒入其裏藏隱。因以薄圍捕取之。槮非古字。至若罧字。雖見淮南鴻烈。然與槮皆俗字也。毛詩、爾雅音義皆云字林作罧。不云出說文。疑或取字林羼入許書。古本當無此篆。所今切。七部。按舊皆山沁反。"}]},"罠":{"expl":"釣也。从网民聲。","rad":"网","fq":"武巾切","vol":"07","py":"mín","duan":[{"e":"所㠯釣也。","n":"所以二字今補。召南曰。其釣維何。維絲伊緍。傳曰。緍、綸也。箋云。以絲爲之綸。則是善釣也。按糸部曰。緍、釣魚？也。此曰罠、所以釣也。然則緍罠古今字。一古文、一小篆也。吳都賦注曰。罠、麋網。廣韵曰。罠、？網。則又古今義殊。○釋器。？罟謂之羉。本或作罠。張載七命。布飛羉。張修罠。則羉與罠非一字也。"}]},"羅":{"expl":"以絲罟鳥也。从网从維。古者芒氏初作羅。","rad":"网","fq":"魯何切","vol":"07","py":"luó","duan":[{"e":"㠯絲罟鳥也。","n":"釋器。鳥罟謂之羅。王風傳曰。鳥網爲羅。"}]},"葚":{"expl":"桑實也。从艸甚聲。","rad":"艸","fq":"常衽切","vol":"01","py":"shèn","duan":[{"e":"桑實也。","n":"見詩。"}]},"罬":{"expl":"捕鳥覆車也。从网叕聲。","rad":"网","fq":"陟劣切","vol":"07","py":"zhuó","duan":[{"e":"捕鳥覆車也。","n":"釋器曰。繴謂之罿。罿、罬也。罬謂之罦。罦、覆車也。郭云。今之翻車也。有兩轅。中施？。以捕鳥。展轉相解。廣異語。按又見糸部。"}]},"罿":{"expl":"罬也。从网童聲。","rad":"网","fq":"尺容切","vol":"07","py":"chōnɡ","duan":[{"e":"罬也。","n":"王風毛傳同。"}]},"䍖":{"expl":"覆車也。从网包聲。《詩》曰：“雉離于䍖。”","rad":"网","fq":"縛牟切","vol":"07","py":"fú","duan":[{"e":"覆車也。","n":"王風。雉離于罦。傳曰。罦、覆車也。"}]},"罻":{"expl":"捕鳥网也。从网𤈫聲。","rad":"网","fq":"於位切","vol":"07","py":"wèi","duan":[{"e":"捕鳥网也。","n":"王制注曰。罻、小網也。"}]},"𦊾":{"expl":"兔罟也。从网否聲。","rad":"网","fq":"縛牟切","vol":"07","py":"fú","duan":[{"e":"兔罟也。","n":"郭璞注子虚賦曰。罘、罝也。"}]},"𦊍":{"expl":"罟也。从网互聲。","rad":"网","fq":"胡誤切","vol":"07","py":"hù","duan":[{"e":"罟也。","n":"廣韵曰。兔網。"}]},"罝":{"expl":"兔网也。从网且聲。","rad":"网","fq":"子邪切","vol":"07","py":"jiē","duan":[{"e":"兔网也。","n":"周南。肅肅兔罝。釋器、毛傳皆曰。兔罟也。"}]},"𦌬":{"expl":"牖中网也。从网舞聲。","rad":"网","fq":"文甫切","vol":"07","py":"wǔ","duan":[{"e":"牖中网也。","n":"中字賸。或曰當作戶牖网。如招䰟之网戶。王逸曰。网戶、綺紋鏤也。此似网。非眞网也。故次於此。"}]},"署":{"expl":"部署，有所网屬。从网者聲。","rad":"网","fq":"常恕切","vol":"07","py":"shǔ","duan":[{"e":"部署也。","n":"部署猶處分。疑本作罘署。後改部署也。項羽本紀曰。梁部署吳中豪傑爲校尉𠊱司馬。急就篇曰。分別部居不雜廁。魯語。孟文子曰。夫位、政之建也。署、位之表也。署所以朝夕虔君命也。按官署字起於此。"}]},"罷":{"expl":"遣有辠也。从网、能。言有賢能而入网，而貫遣之。《周禮》曰：“議能之辟。”","rad":"网","fq":"薄蟹切","vol":"07","py":"bà","duan":[{"e":"遣有辠也。","n":"引伸之爲止也。休也。周易。或𡔷或罷。論語。欲罷不能。周禮有罷民。鄭曰。民不愍作勞。有似於罷。齊語有罷士、罷女。韋曰罷、病也。無作曰病。按罷民、罷士謂偷惰之人。罷之音亦讀如疲。而與疲義殊。少儀。師役曰罷。鄭曰。罷之言疲勞也。凡曰之言者、皆轉其義之詞。"}]},"蒟":{"expl":"果也。从艸竘聲。","rad":"艸","fq":"俱羽切","vol":"01","py":"jǔ","duan":[{"e":"果也。","n":"史記、漢書有枸酱。左思蜀都賦、常璩華陽國志作蒟。史記亦或作蒟。據劉逵、顧微、宋祁諸家說。卽扶畱藤也。葉可用食㯽榔。實如桑葚而長。名蒟。可爲醬。巴志曰。樹有荔支。蔓有辛蒟。然則此物縢生緣木。故作蒟、從艸。亦作枸、從木。要必一物也。許君木部有枸字。云可爲醬。於艸部又有蒟字。葢不能定而兩存之。次於葚者、以其實似葚也。其實名蒟。故云果也。果、木實也。當云蒟果也、爲三字句。"}]},"置":{"expl":"赦也。从网、直。","rad":"网","fq":"陟吏切","vol":"07","py":"zhì","duan":[{"e":"赦也。","n":"？部曰。赦、置也。二字互訓。置之本義爲貰遣。轉之爲建立。所謂變則通也。周禮。廢置以馭其吏。與廢對文。古借爲植字。如攷工記置而搖之卽植而搖之、論語植其杖卽置其杖也。"}]},"罯":{"expl":"覆也。从网音聲。","rad":"网","fq":"烏感切","vol":"07","py":"ǎn","duan":[{"e":"覆也。从网。音聲。","n":"烏感切。七部。"}]},"詈":{"expl":"罵也。从网从言。网辠人。","rad":"网","fq":"力智切","vol":"07","py":"lì","duan":[{"e":"罵也。从网言。","n":"力智切。十六部。"}]},"罵":{"expl":"詈也。从网馬聲。","rad":"网","fq":"莫駕切","vol":"07","py":"mà","duan":[{"e":"詈也。从网。馬聲。","n":"莫駕切。古音在五部。"}]},"𦌭":{"expl":"馬絡頭也。从网从𩡧。𩡧，馬絆也。","rad":"网","fq":"居宜切","vol":"07","py":"jī","duan":[{"e":"馬落頭也。","n":"落絡古今字。許書古本必是作落。引伸之爲羈旅。"}]},"罭":{"expl":"魚網也。从网或聲。","rad":"网","fq":"于逼切","vol":"07","py":"yù","duan":[]},"罳":{"expl":"罘罳，屏也。从网思聲。","rad":"网","fq":"息兹切","vol":"07","py":"sī","duan":[]},"罹":{"expl":"心憂也。从网。未詳。古多通用離。","rad":"网","fq":"呂支切","vol":"07","py":"lí","duan":[]},"襾":{"expl":"覆也。从冂，上下覆之。凡襾之屬皆从襾。讀若𣇩。","rad":"襾","fq":"呼訝切","vol":"07","py":"yà","duan":[{"e":"覆也。从冂上下覆之。","n":"下字賸。冂者自上而下也。？者自下而上也。故曰上覆之。覆者、？也。从一者、天也。上覆而不外乎天也。"}]},"覂":{"expl":"反覆也。从襾乏聲。","rad":"襾","fq":"方勇切","vol":"07","py":"fěnɡ","duan":[{"e":"覆也。","n":"武帝紀。泛駕之馬。師古曰。泛、覆也。音方勇反。字本作覂。後通用耳。廣韵正作覂駕之馬。食貨志。大命將泛。孟康曰。泛音方勇反。玉篇正作大命將覂。"}]},"芘":{"expl":"艸也。一曰芘茮木。从艸比聲。","rad":"艸","fq":"房脂切","vol":"01","py":"pí","duan":[{"e":"艸也。一曰芘尗木。","n":"尗鉉作茮。芘尗木未聞。王氏念孫曰。芘茮木三字當是芘芣二字之譌。玉裁謂。說文荍字下作蚍𧉈。不當此作芘芣。葢木名也。"}]},"覈":{"expl":"實也。考事，襾笮邀遮，其辤得實曰覈。从襾敫聲。","rad":"襾","fq":"下革切","vol":"07","py":"hé","duan":[{"e":"實也。","n":"凡有骨之偁也。骨下曰。肉之覈也。蔡邕注典引曰。有骨曰覈。周禮。其植物曰覈物。謂梅李之屬。按詩小雅。肴覈維旅。典引及注不誤。蜀都賦作槅。叚借字也。今本作核。傳譌也。周禮經作覈。注作核。葢漢人巳用核爲覈矣。"}]},"覆":{"expl":"覂也。一曰蓋也。从襾復聲。","rad":"襾","fq":"敷救切","vol":"07","py":"fù","duan":[{"e":"覂也。","n":"反也。覆覂反三字雙聲。又部反下曰。覆也。反覆者、倒易其上下。如？从冂而反之爲？也。覆與復義相通。復者、往來也。"}]},"巾":{"expl":"佩巾也。从冂，丨象糸也。凡巾之屬皆从巾。","rad":"巾","fq":"居銀切","vol":"07","py":"jīn","duan":[{"e":"佩巾也。","n":"帶下云。佩必有巾。佩巾、禮之紛帨也。鄭曰。紛帨、𢂑物之佩巾也。按以巾拭物曰巾。如以帨拭手曰帨。周禮。巾車之官。鄭注。巾猶衣也。然吳都賦。吳王乃巾玉路。陶淵明文曰。或巾柴車。或櫂孤舟。皆謂拂拭用之。不同鄭說也。陶句見文𨕖江淹雜體詩注。今本作或命巾車。不可通矣。玉篇曰。本以拭物。後人著之於頭。"}]},"𢁥":{"expl":"楚謂大巾曰𢁥。从巾分聲。","rad":"巾","fq":"撫文切","vol":"07","py":"fēn","duan":[{"e":"楚謂大巾曰𢁥。","n":"方言。大巾謂之𢁥。內則曰。左佩紛帨。鄭云。紛帨、拭物之佩巾。今齊人有言紛者。釋文曰。紛或作帉。按紛者叚借字也。𢁥帉同。"}]},"帥":{"expl":"佩巾也。从巾、𠂤。","rad":"巾","fq":"所律切","vol":"07","py":"shuài","duan":[{"e":"佩巾也。从巾。𠂤聲。","n":"聲字大徐奪。所律切。十五部。"}]},"𢄢":{"expl":"禮巾也。从巾从執。","rad":"巾","fq":"輸芮切","vol":"07","py":"shuì","duan":[{"e":"禮巾也。从巾。埶聲。","n":"篆體二徐皆作𢄢。大徐曰从執。小徐曰執聲。皆誤。今正。𢄢輸芮切。十五部。今不見經典。恐亦帨之或體。然廣雅巳兼載帨𢄢矣。"}]},"帗":{"expl":"一幅巾也。从巾犮聲。讀若撥。","rad":"巾","fq":"北末切","vol":"07","py":"bō","duan":[{"e":"一幅巾也。","n":"幅、布帛廣也。一幅巾者、巾廣二尺二寸。其長當亦同也。此與鄭注周禮帗舞義絕殊。葢許君周禮作翇舞。與鄭司農說同。見羽部。"}]},"㠴":{"expl":"枕巾也。从巾刃聲。","rad":"巾","fq":"而振切","vol":"07","py":"rèn","duan":[{"e":"枕巾也。","n":"葢加枕以藉首爲易污也。今俗所謂枕頭衣。廣雅亦曰。㠴、巾也。"}]},"幋":{"expl":"覆衣大巾。从巾般聲。或以爲首鞶。","rad":"巾","fq":"薄官切","vol":"07","py":"pán","duan":[{"e":"覆衣大巾也。从巾。般聲。","n":"薄官切。十四部。"}]},"帤":{"expl":"巾帤也。从巾如聲。一曰幣巾。","rad":"巾","fq":"女余切","vol":"07","py":"rú","duan":[{"e":"巾帤也。","n":"方言。𢄐、巾也。大巾謂之𢁥。嵩嶽之南陳潁之閒謂之帤巾。亦謂之𢄐。按巾帤葢方俗語。"}]},"蕣":{"expl":"木堇，朝華暮落者。从艸䑞聲。《詩》曰：“顔如蕣華。”","rad":"艸","fq":"舒閏切","vol":"01","py":"shùn","duan":[{"e":"木堇。","n":"句。"}]},"幣":{"expl":"帛也。从巾敝聲。","rad":"巾","fq":"毗祭切","vol":"07","py":"bì","duan":[{"e":"帛也。","n":"帛者、繒也。聘禮注曰。幣、人所造成以自覆蔽。作幣者誤謂束帛也。愛之斯欲飮食之。君子之情也。是以享用幣。所以副忠信。"}]},"幅":{"expl":"布帛廣也。从巾畐聲。","rad":"巾","fq":"方六切","vol":"07","py":"fú","duan":[{"e":"布帛廣也。","n":"凡布帛廣二尺二寸。其邊曰幅。左傳曰。夫富如布帛之有幅焉。爲之制度。使無遷也。引伸爲邪幅。小雅。邪幅在下。傳曰。幅、偪也。所以自偪束也。"}]},"㡆":{"expl":"設色之工，治絲練者。从巾𡿬聲。一曰𢂩隔。讀若荒。","rad":"巾","fq":"呼光切","vol":"07","py":"huānɡ","duan":[{"e":"設色之工治絲練者。","n":"攷工記。設色之工。㡆氏。掌湅絲、湅帛。此云治絲、謂湅絲。云治練、謂湅帛也。糸部曰。練、湅繒也。此謂帛爲練者、渾言之也。湅見水部。"}]},"帶":{"expl":"紳也。男子鞶帶，婦人帶絲。象繫佩之形。佩必有巾，从巾。","rad":"巾","fq":"當蓋切","vol":"07","py":"dài","duan":[{"e":"紳也。","n":"糸部曰。紳、大帶也。"}]},"幘":{"expl":"髮有巾曰幘。从巾責聲。","rad":"巾","fq":"側革切","vol":"07","py":"zé","duan":[{"e":"髮有巾曰幘。","n":"方言曰。覆髻謂之幘巾。或謂之承露。或謂之覆？。獨𣃔曰。幘、古者卑賤執事不冠者之所服也。漢以後服之。其制日詳。詳見司馬氏輿服志。"}]},"㡄":{"expl":"領耑也。从巾旬聲。","rad":"巾","fq":"相倫切","vol":"07","py":"xún","duan":[{"e":"領耑也。从巾。旬聲。","n":"相倫切。十二部。篇、韵皆無此字。"}]},"帔":{"expl":"弘農謂帬帔也。从巾皮聲。","rad":"巾","fq":"披義切","vol":"07","py":"pèi","duan":[{"e":"弘農謂帬帔也。","n":"謂帬曰帔也。方言曰。帬、陳魏之閒謂之帔。自關而東謂之襬。"}]},"常":{"expl":"下帬也。从巾尚聲。","rad":"巾","fq":"市羊切","vol":"07","py":"chánɡ","duan":[{"e":"下帬也。","n":"釋名曰。上曰衣。下曰裳。裳、障也。以自障蔽也。士冠禮。爵弁。服纁裳。皮弁。服素積。玄端。玄裳、黃裳、襍裳可也。禮記深衣。續衽鉤邊。要縫半下。今字裳行而常廢矣。"}]},"帬":{"expl":"下裳也。从巾君聲。","rad":"巾","fq":"渠云切","vol":"07","py":"qún","duan":[{"e":"繞領也。","n":"方言。繞袊謂之帬。廣雅本之。曰繞領。句帔。句帬也。袊領今古字。領者、劉熙云總領衣體爲端首也。然則繞領者、圍繞於領。今男子婦人披肩其遺意。劉熙曰。帔、披也。披之肩背。不及下也。葢古名帬。弘農方言曰帔。若常則曰下帬。言帬之在下者。亦集眾幅爲之。如帬之集眾幅被身也。如李善引梁典。任昉諸子冬月著葛巾、帔、練裙。自是上下三物。水經注。淮南王廟。安及八士像皆羽扇、裙帔、巾壺、枕物一如常居。亦帬帔竝言。自釋名裙系下、帔系上。後人乃不知帔帬之別。擅改說文矣。"}]},"帴":{"expl":"帬也。一曰帗也。一曰婦人脅衣。从巾戔聲。讀若末殺之殺。","rad":"巾","fq":"所八切","vol":"07","py":"sàn","duan":[{"e":"帬也。","n":"衣部褿下曰。帴也。"}]},"萸":{"expl":"茱萸也。从艸臾聲。","rad":"艸","fq":"羊朱切","vol":"01","py":"yú","duan":[{"e":"茱萸也。从艸臾聲。","n":"羊朱切。古音在四部。"}]},"㡓":{"expl":"𢃭也。从巾軍聲。","rad":"巾","fq":"古渾切","vol":"07","py":"kūn","duan":[{"e":"幒也。","n":"方言。褌、陳楚江淮之閒謂之䘴。釋名。褌、貫也。貫兩腳上繫腰中也。按今之套褲、古之絝也。今之滿襠褲、古之褌也。自其渾合近身言曰㡓。自其兩襱孔穴言曰幒。方言。無？之袴謂之襣。郭云。卽犢鼻褌。"}]},"𢃭":{"expl":"㡓也。从巾怱聲。一曰帙。","rad":"巾","fq":"職茸切","vol":"07","py":"zhōnɡ","duan":[{"e":"㡓也。从巾。悤聲。","n":"職茸切。九部。方言錯勇反。"}]},"𢅡":{"expl":"楚謂無緣衣也。从巾監聲。","rad":"巾","fq":"魯甘切","vol":"07","py":"lán","duan":[{"e":"楚謂無緣衣也。","n":"方言。無緣之衣謂之襤。又曰。裯謂之襤。又云。楚謂無緣之衣曰襤。紩衣謂之褸。又曰。襜褕以布而無緣。敝而紩之謂之襤褸。"}]},"幎":{"expl":"幔也。从巾冥聲。《周禮》有“幎人”。","rad":"巾","fq":"莫狄切","vol":"07","py":"mì","duan":[{"e":"幔也。","n":"謂冡其上也。周禮注曰。以巾覆物曰幎。禮經。鼎有鼏。尊𢑴有幎。其字亦作幂。俗作？。筭家幎積是此字。魏都賦注引左傳。幂館宫室。塗曁曰幂者、亦謂冡其上也。今本作塓乃俗字。"}]},"幔":{"expl":"幕也。从巾曼聲。","rad":"巾","fq":"莫半切","vol":"07","py":"màn","duan":[{"e":"幎也。","n":"幎各本作幕。由作幂而誤耳。今正。凡以物冡其上曰幔。與幎雙聲而互訓。釋名、玉篇、廣韵以帷幔釋之。今義非古義也。"}]},"幬":{"expl":"禪帳也。从巾𠷎聲。","rad":"巾","fq":"直由切","vol":"07","py":"chóu","duan":[{"e":"襌帳也。","n":"襌、不重也。古樂府。紅羅複斗帳。則帳多複者。召南抱衾與裯傳。禪被也。箋云。裯、牀帳也。按鄭謂裯爲？之叚借也。不言襌者、統辭也。釋訓曰。幬謂之帳。引伸爲覆幬。見左傳及中庸。中庸注曰。幬或作燾。"}]},"㡘":{"expl":"帷也。从巾兼聲。","rad":"巾","fq":"力鹽切","vol":"07","py":"lián","duan":[{"e":"帷也。","n":"釋名曰。㡘、廉也。自障蔽爲廉恥也。戶㡘、施之於戶外也。按與竹部簾異物。㡘以布爲之。簾以竹爲之。"}]},"帷":{"expl":"在㫄曰帷。从巾隹聲。","rad":"巾","fq":"洧悲切","vol":"07","py":"wéi","duan":[{"e":"在旁曰帷。","n":"周禮注同。釋名曰。帷、圍也。所以自障圍也。"}]},"帳":{"expl":"張也。从巾長聲。","rad":"巾","fq":"知諒切","vol":"07","py":"zhànɡ","duan":[{"e":"張也。","n":"以曡韵爲訓。釋名曰。帳、張也。張施於牀上也。小帳曰斗帳。形如覆斗也。古亦借張字爲之。"}]},"幕":{"expl":"帷在上曰幕，覆食案亦曰幕。从巾莫聲。","rad":"巾","fq":"慕各切","vol":"07","py":"mù","duan":[{"e":"帷在上曰幕。","n":"周禮注曰。在上曰幕。幕或在地。展陳於上。疏云。聘禮布幕。官陳幣。史展幣。皆於幕下。又賓入境至館皆展幕。是幕在地。展陳於上也。按大徐本此下有覆食案亦曰幕六字。葢淺人所增。"}]},"茱":{"expl":"茱萸，茮屬。从艸朱聲。","rad":"艸","fq":"市朱切","vol":"01","py":"zhū","duan":[{"e":"茱萸、","n":"逗。"}]},"㠲":{"expl":"㡜裂也。从巾匕聲。","rad":"巾","fq":"卑履切","vol":"07","py":"bǐ","duan":[{"e":"㡜裂也。","n":"謂殘帛裂也。急就篇曰。㠲敝囊橐不直錢。方言。器破而未離、南楚之閒謂之𢻹。聲同義近。亦作？。"}]},"㡜":{"expl":"殘帛也。从巾祭聲。","rad":"巾","fq":"先列切","vol":"07","py":"xiè","duan":[{"e":"殘帛也。","n":"廣韵曰。㡜縷桃花。類篇曰。今時剪繒爲華者。按與碎音義略相近。"}]},"㡏":{"expl":"正耑裂也。从巾俞聲。","rad":"巾","fq":"山樞切","vol":"07","py":"shū","duan":[{"e":"正褍裂也。","n":"褍各本作耑。今正。衣部曰。褍、衣正幅也。此謂帛之正褍。以別於上文㠲謂殘帛之裂。"}]},"帖":{"expl":"帛書署也。从巾占聲。","rad":"巾","fq":"他叶切","vol":"07","py":"tiè","duan":[{"e":"帛書署也。","n":"木部曰。檢、書署也。木爲之謂之檢。帛爲之則謂之帖。皆謂幖題。今人所謂籤也。帛署必黏？。引伸爲帖服、爲帖妥。俗製貼字爲相附之義。製怗字爲安服之義。"}]},"帙":{"expl":"書衣也。从巾失聲。","rad":"巾","fq":"直質切","vol":"07","py":"zhí","duan":[{"e":"書衣也。","n":"書衣謂用裹書者。亦謂之幒。陸德明𢰅經典釋文三十卷。合爲三袟。今人曰函。"}]},"㡐":{"expl":"幡幟也。从巾前聲。","rad":"巾","fq":"則前切","vol":"07","py":"jiān","duan":[{"e":"幡幟也。","n":"幡幟、旛識之俗字也。古有旛無幡。有識無幟。許書本作旛識。淺人易之。旛識者、旗有幅可爲表識。？之言箋也。箋謂表識。"}]},"幑":{"expl":"幟也，以絳幑帛，箸於背。从巾，微省聲。《春秋傳》曰：“揚幑者公徒。”","rad":"巾","fq":"許歸切","vol":"07","py":"huī","duan":[{"e":"幑識也。","n":"三字一句。各本刪幑字。識作幟。今正。"}]},"幖":{"expl":"幟也。从巾𤐫聲。","rad":"巾","fq":"方招切","vol":"07","py":"biāo","duan":[{"e":"𢅽識也。","n":"亦三字一句。各本作幟也二字。今正。通俗文曰。幑号曰幖。私記曰幟。周禮肆師。表？盛告絜。鄭注。故書表爲剽。剽表皆謂幑識也。按剽表皆叚借字。幖其本字也。凡物之幖識亦曰幑識。今字多作標牓。標行而幖廢矣。"}]},"㠾":{"expl":"幡也。从巾夗聲。","rad":"巾","fq":"於袁切","vol":"07","py":"yuān","duan":[{"e":"幡也。","n":"幡者、下文云書兒抵觚布也。與上文？下云幡幟迴別。許書㫃部旛下曰。旛、胡也。謂旗幅之下垂者。與幡各義。自俗書從便。旗旛字皆作幡。冣目曰。鳥蟲書所以書旛信也。今本亦改爲幡信。而此部？之幡識。鮮知其當作旛矣。？與幑幖伍。旌旗類也。㠾與幡同物。拭觚布也。廣韵繙字下云。繙㠾、亂取。此今義。非許義。"}]},"幡":{"expl":"書兒拭觚布也。从巾番聲。","rad":"巾","fq":"甫煩切","vol":"07","py":"fān","duan":[{"e":"書兒拭觚布也。","n":"拭本作飾。淺人所改也。飾拭正俗字。許書有飾無拭。顔師古曰。觚者學書之牘。或以記事。削木爲之。其形或六面。或八面。皆可書。觚者、棱也。以有棱角。故謂之觚。卽孔子所歎也。按觚以學書或記事。若今書童及貿易人所用粉版。旣書、可拭去？書。楊雄齎油素四尺。亦謂素之可拭者也。拭觚之布謂之幡。亦謂之㠾。反覆可用之意。"}]},"茮":{"expl":"茮莍。从艸尗聲。","rad":"艸","fq":"子寮切","vol":"01","py":"jiāo","duan":[{"e":"茮莍也。","n":"此三字句。茮莍葢古語。猶詩之椒𦕼也。單呼曰茮。絫呼曰茮莍、茮𦕼。唐風。椒𦕼之實。毛曰。椒𦕼、椒也。釋木曰。椒、榝、醜莍、檓、大椒。神農本艸經有蜀椒。又有秦椒。"}]},"𢃴":{"expl":"刜也。从巾剌聲。","rad":"巾","fq":"盧達切","vol":"07","py":"là","duan":[{"e":"刜也。","n":"刜當作拂。字之誤也。刀部曰。刜、擊也。手部曰。拂、過擊也。過擊者、所過而擊箸。與拭之義近。上下文皆言拭。可證必當作拂矣。玉篇注作拂也。廣韵注作拂箸。"}]},"㡨":{"expl":"拭也。从巾韱聲。","rad":"巾","fq":"精廉切","vol":"07","py":"jiān","duan":[{"e":"拭也。","n":"其義少見。字林。幖㡨記。則音義同籤。"}]},"幝":{"expl":"車弊皃。从巾單聲。《詩》曰：“檀車幝幝。”","rad":"巾","fq":"昌善切","vol":"07","py":"chǎn","duan":[{"e":"車敝皃。","n":"敝各譌作弊。今正。皃、釋文引作也。小雅杕杜曰。檀車幝幝。傳曰。檀車、役車也。幝幝、敝貌。釋文曰。幝韓詩作𦅗。糸部曰。𦅗、偏緩也。○按古本當是巾敝皃。故从巾。詩以爲車敝字則其引伸之義也。釋文引說文。巾敝也。从巾單。今本釋文乃巾譌車。殊失陸意。"}]},"𢄐":{"expl":"蓋衣也。从巾冡聲。","rad":"巾","fq":"莫紅切","vol":"07","py":"ménɡ","duan":[{"e":"葢衣也。","n":"覆葢物之衣也。法言。震風凌雨。然後知夏屋之爲帲？也。？卽𢄐之俗。尙書大傳。下㓝墨𢄐。方言。𢄐、巾也。與許義稍異。大雅。麻麥？？。傳曰。？？然茂盛也。按此亦引伸之義。謂徧覆於地也。"}]},"幭":{"expl":"蓋幭也。从巾蔑聲。一曰襌被。","rad":"巾","fq":"莫結切","vol":"07","py":"miè","duan":[{"e":"葢幭也。","n":"幭之言幎也。大雅淺幭傳曰。淺、虎皮淺毛也。幭、覆式也。按幭之本義不專爲覆軾。而覆軾其一端也。司馬彪、徐廣曰。乘輿車文虎伏軾。龍首衡軛。文虎伏軾卽經之淺幭。龍首衡軛卽經之金厄也。說詳詩經小學。曲禮素簚注。簚、覆笭也。釋文。簚、本又作幭。者正字。簚者叚借字也。篇、韵皆以帊幞釋幭。今義也。"}]},"幠":{"expl":"覆也。从巾無聲。","rad":"巾","fq":"荒烏切","vol":"07","py":"hū","duan":[{"e":"覆也。","n":"喪大記。幠用斂衾。釋詁。幠、大也。幠、有也。皆覆義之引伸也。投壷曰。無幠無敖。注曰。幠、敖皆慢也。又其引伸也。斯干以芋爲幠。"}]},"飾":{"expl":"㕞也。从巾从人，食聲。讀若式。一曰襐飾。","rad":"巾","fq":"賞隻切","vol":"07","py":"shì","duan":[{"e":"㕞也。","n":"又部曰。㕞、飾也。二篆爲轉注。飾拭古今字。許有飾無拭。凡說解中拭字皆淺人改飾爲之。而彡下云。毛飾畫文也。聿下云。聿飾也。皆卽拭字。淺人不解而不之改。若㕞下云。飾也。則五經文字所據尙不誤。周禮司尊彝注云。涗酌者、挩飾勺而酌也。釋文作飾。今本作拭。實無二義。凡物去其塵垢卽所以增其光采。故㕞者飾之本義。而凡踵事增華皆謂之飾。則其引伸之義也。若席下云純飾、𤪌下云弁飾、縟下云緐采飾是也。凡許書之義例。依此求之。無不可得者。聘禮拭圭字今作拭。葢古經必作飾。鄭云。拭、淸也。此必經文作飾而以淸訓之。倘經本作拭又何用此注乎。釋詁云。拭、淸也。爾雅少古字。故往往與經典不合。古本當不作拭耳。管子輕重曰。桓公使八使者"}]},"幃":{"expl":"囊也。从巾韋聲。","rad":"巾","fq":"許歸切","vol":"07","py":"wéi","duan":[{"e":"囊也。","n":"離騷。蘇糞壤以充幃。王逸曰。幃謂之幐。幐、香囊也。按凡囊皆曰幃、曰幐。王依文爲說則謂之香囊耳。或曰爾雅婦人之褘亦作幃。是許所云幃也。今按此與爾雅之褘無渉。釋器曰。婦人之褘謂之縭。縭、緌也。郭云。卽今之香纓。女子旣嫁之所著。示繫屬於人。義見禮記。攷士昏禮注曰。婦人十五許嫁。筓而禮之。因著纓。明有繫也。葢以五采爲之。其制未聞。內則。婦事舅姑衿纓。注曰。婦人有纓。示繫屬也。詩。親結其縭。毛云。縭、婦人之褘也。母戒女施衿結帨。孫炎釋爾雅婦人之褘云。帨巾也。禮之纓必以采繩。詩、爾雅之褘縭乃帨巾。其不相涉明甚。景純注非。許以囊釋幃。亦𣃔非釋器及毛詩之褘也。"}]},"帣":{"expl":"囊也。今鹽官三斛爲一帣。从巾𢍏聲。","rad":"巾","fq":"居倦切","vol":"07","py":"juàn","duan":[{"e":"囊也。","n":"集韵曰。囊有底曰帣。或借爲絭字。史記。淳于髡帣韝鞠𦜕。帣韝謂以韝約袖。糸部曰。絭、纕臂繩也。"}]},"帚":{"expl":"糞也。从又持巾埽冂内。古者少康初作箕、帚、秫酒。少康，杜康也，葬長垣。","rad":"巾","fq":"支手切","vol":"07","py":"zhǒu","duan":[{"e":"所㠯糞也。","n":"所㠯二字淺人刪之。今補。糞當作𡊅。土部曰。𡊅、埽除也。不言埽言𡊅者、𡊅亦埽也。曲禮言糞。少儀曰。氾埽曰埽。埽度前曰拚。拚卽𡊅之叚借字。𡊅與埽對文則二。散文則一。帚亦謂之鬣。"}]},"莍":{"expl":"茮樧實裏如表者。从艸求聲。","rad":"艸","fq":"巨鳩切","vol":"01","py":"qiú","duan":[{"e":"榝茮實裹如𧚍也。","n":"依爾雅音義正誤。𧚍莍同音也。郭云。莍、萸子聚生成房皃詩箋作捄。釋木。櫟其實梂。皆卽莍字也。"}]},"席":{"expl":"籍也。《禮》：天子、諸侯席，有黼繡純飾。从巾，庶省。","rad":"巾","fq":"祥易切","vol":"07","py":"xí","duan":[{"e":"藉也。","n":"此以曡韵爲訓。戶護、門聞之例也。藉本祭藉。引伸爲凡藉之偁。竹部曰。竹席曰筵。實通偁耳。"}]},"幐":{"expl":"囊也。从巾朕聲。","rad":"巾","fq":"徒登切","vol":"07","py":"ténɡ","duan":[{"e":"囊也。","n":"離騷。蘇糞壤以充幃。王注。幃謂幐。幐、香囊也。按凡囊皆曰幐。王望文爲說耳。玉篇曰。兩頭有物謂之幐擔。廣韵曰。囊可帶者。或借縢爲之。"}]},"𢅯":{"expl":"以囊盛穀，大滿而裂也。从巾奮聲。","rad":"巾","fq":"方吻切","vol":"07","py":"fèn","duan":[{"e":"㠯囊盛穀大滿而裂也。","n":"？之言璺也。璺者、隙也。玉篇曰。又弓筋起。"}]},"㡒":{"expl":"載米𤲑也。从巾盾聲。讀若《易》屯卦之屯。","rad":"巾","fq":"陟倫切","vol":"07","py":"zhūn","duan":[{"e":"載米𤲑也。","n":"宁部曰。𤲑、㡒也。所以盛米也。二字相轉注。"}]},"㠷":{"expl":"蒲席𤲑也。从巾及聲。讀若蛤。","rad":"巾","fq":"古沓切","vol":"07","py":"ɡé","duan":[{"e":"蒲席𤳊也。","n":"𠚋部曰。𤳊者、㠷也。楊雄以爲蒲器。然則𤳊與㠷一物也。"}]},"幩":{"expl":"馬纏鑣扇汗也。从巾賁聲。《詩》曰：“朱幩鑣鑣。”","rad":"巾","fq":"符分切","vol":"07","py":"fén","duan":[{"e":"馬纏鑣扇汗也。","n":"衛風碩人曰。朱幩儦儦。傳曰。幩、飾也。人君以朱纏鑣扇汗。且以爲飾。儦儦、盛皃。金部曰。鑣者、馬銜也。以朱㡜縷纏馬銜之上而垂之。可以因風扇汗。故謂之扇汗。亦名排沬。以其用㡜也。故从巾。"}]},"𢅼":{"expl":"𡎰地，以巾𢵢之。从巾夒聲。讀若水溫㬮也。一曰箸也。","rad":"巾","fq":"乃昆切","vol":"07","py":"néi","duan":[{"e":"𡎰地也。","n":"也字今補。土部曰。墀者、涂地也。然則？地卽涂地也。漢書楊雄傳曰。？人亡則匠石輟斤而不敢妄斲。服虔曰。㡪、古之善塗墍者。施廣領大袖以仰塗。而領袖不污。按服注不言涂地。然仰涂如此其善。則涂地更可知矣。㡪人卽莊子郢人。"}]},"帑":{"expl":"金幣所藏也。从巾奴聲。","rad":"巾","fq":"乃都切","vol":"07","py":"tǎnɡ","duan":[{"e":"金幣所藏也。","n":"此與府庫廥等一律。帑讀如奴。帑之言囊也。以幣帛所藏。故从巾。"}]},"布":{"expl":"枲織也。从巾父聲。","rad":"巾","fq":"博故切","vol":"07","py":"bù","duan":[{"e":"枲織也。","n":"其艸曰枲、曰萉。析其皮曰林、曰木。屋下治之曰麻。緝而績之曰綫、曰縷、曰纑。織而成之曰布。布之屬曰紨、曰？、曰絟、曰緦、曰緆、曰緰貲、曰㡉、曰幏。古者無今之木綿布。但有麻布及葛布而巳。引伸之凡散之曰布。取義於可卷舒也。外府注曰。布、泉也。其藏曰泉。其行曰布。泉者今之錢也。衛風。抱布貿絲。傳曰。布、幣也。箋云。幣者所以貿買物也。此幣爲凡貨之偁。布帛金錢皆是也。"}]},"幏":{"expl":"南郡蠻夷賨布。从巾家聲。","rad":"巾","fq":"古訝切","vol":"07","py":"jià","duan":[{"e":"南郡蠻夷賨布也。","n":"貝部曰。賨者、南蠻賦也。文𨕖魏都賦注引風俗通曰。？瓠之後。輸布一匹。小口二丈。後漢書少小口二字是爲賨布。廩君之巴氏出幏布八丈。後漢書云八丈二尺幏亦賨也。故統謂之賨布。"}]},"荆":{"expl":"楚木也。从艸刑聲。","rad":"艸","fq":"舉卿切","vol":"01","py":"jīnɡ","duan":[{"e":"楚木也。","n":"林部曰。楚、叢木。一名荆。是爲轉注。"}]},"㡉":{"expl":"布。出東萊。从巾弦聲。","rad":"巾","fq":"胡田切","vol":"07","py":"xián","duan":[{"e":"㡉布也。","n":"各本刪㡉字。今補。布名也。"}]},"㡔":{"expl":"䰍布也。一曰車上衡衣。从巾敄聲。讀若頊。","rad":"巾","fq":"莫卜切","vol":"07","py":"mù","duan":[{"e":"䰍布也。","n":"䰍者、桼也。廣韵、集韵十遇作髮巾。"}]},"幦":{"expl":"䰍布也。从巾辟聲。《周禮》曰：“駹車大幦。”","rad":"巾","fq":"莫狄切","vol":"07","py":"mì","duan":[{"e":"䰍布也。","n":"旣夕禮玉藻少儀鄭注、公羊傳昭卄五年何注皆曰。幦、覆笭也。按車覆笭與車笭是二事。車笭者、周禮之蔽。毛詩、爾雅之笰。說文之篚。鄭曰。車旁禦風塵者也。覆笭者、禮經、周禮、禮記、公羊傳之幦。大雅、曲禮之幭。今周禮之幎。葢乎軾上者也。以禦旁之名名之也。車笭多以竹。故字从竹。覆笭不用竹、用皮。巾車曰。王喪之車。犬𧜀、鹿淺𧜀、然𧜀、豻𧜀。各用其皮也。大雅之淺幭、虎皮也。與玉藻之羔幦、鹿幦皆諸矦大夫士之吉禮也。曲禮之素幭卽士喪禮之白狗幦。大夫士之凶禮也。然則車覆笭古無用桼布者。許以䰍布釋幦。幦之本義也。經典用爲車覆笭之字也。"}]},"㡇":{"expl":"領耑也。从巾𦔮聲。","rad":"巾","fq":"陟葉切","vol":"07","py":"zhé","duan":[{"e":"領耑也。从巾。耴聲。","n":"陟葉切。八部。按此篆與㡄篆同義。篇、韵皆有㡇無㡄。集韵乃兼有之。葢此書當刪㡄。而存㡇於㡄處。"}]},"幢":{"expl":"旌旗之屬。从巾童聲。","rad":"巾","fq":"宅江切","vol":"07","py":"chuánɡ","duan":[]},"幟":{"expl":"旌旗之屬。从巾戠聲。","rad":"巾","fq":"昌志切","vol":"07","py":"zhì","duan":[]},"帟":{"expl":"在上曰帟。从巾亦聲。","rad":"巾","fq":"羊益切","vol":"07","py":"yì","duan":[]},"幗":{"expl":"婦人首飾。从巾國聲。","rad":"巾","fq":"古對切","vol":"07","py":"ɡuó","duan":[]},"幧":{"expl":"歛髮也。从巾喿聲。","rad":"巾","fq":"七搖切","vol":"07","py":"qiāo","duan":[]},"帒":{"expl":"囊也。从巾代聲。或从衣。","rad":"巾","fq":"徒耐切","vol":"07","py":"dài","duan":[]},"祓":{"expl":"除惡祭也。从示犮聲。","rad":"示","fq":"敷勿切","vol":"01","py":"fú","duan":[{"e":"除惡祭也。从示。犮聲。","n":"𢾭勿切。十五部。"}]},"菭":{"expl":"水衣。从艸治聲。","rad":"艸","fq":"徒哀切","vol":"01","py":"tái","duan":[{"e":"水靑衣也。","n":"依爾雅音義補靑字。醢人箈菹。鄭司農曰。箈。水中魚衣。玄謂箈、箭萌。玉裁按。先、後鄭異字。先鄭作菭、從艸。許說正同。後鄭作䈚、從竹。郭注爾雅引䈚菹鴈醢。從後鄭也。後鄭注當有菭當爲䈚四字、而佚。今本周禮作箈。混誤不成字。所當正者也。吳都賦注曰。海苔生海水中。正靑。狀如亂髮。乾之赤。鹽藏有汁。名曰濡苔。"}]},"帊":{"expl":"帛三幅曰帊。从巾巴聲。","rad":"巾","fq":"普駕切","vol":"07","py":"pà","duan":[]},"幞":{"expl":"帊也。从巾菐聲。","rad":"巾","fq":"房玉切","vol":"07","py":"fú","duan":[]},"幰":{"expl":"車幔也。从巾憲聲。","rad":"巾","fq":"虚偃切","vol":"07","py":"xiǎn","duan":[]},"巿":{"expl":"韠也。上古衣蔽前而已，巿以象之。天子朱巿，諸矦赤巿，大夫葱衡。从巾，象連帶之形。凡巿之屬皆从巿。","rad":"巿","fq":"分勿切","vol":"07","py":"fú","duan":[{"e":"韠也。","n":"韋部曰。韠、韍也。二字相轉注也。鄭曰。韠之言蔽也。韍之言亦蔽也。祭服偁韍。玄端服偁韠。"}]},"𢂷":{"expl":"士無巿有𢂷。制如榼，缺四角。爵弁服，其色韎。賤不得與裳同。司農曰：“裳，纁色。”从巿合聲。","rad":"巿","fq":"古洽切","vol":"07","py":"jiá","duan":[{"e":"士無巿有𢂷。","n":"大夫以上祭服用玄冕爵弁服。其韠曰韍。士與君祭之服用爵弁服。其韠曰𢂷。不曰韍。故曰士無韍有𢂷也。玉藻之縕韍卽韎韐。則非不可偁韍也。"}]},"帛":{"expl":"繒也。从巾白聲。凡帛之屬皆从帛。","rad":"帛","fq":"㫄陌切","vol":"07","py":"bó","duan":[{"e":"繒也。","n":"糸部曰。繒、帛也。聘禮、大宗伯注皆云。帛、今之璧色繒也。"}]},"錦":{"expl":"襄邑織文。从帛金聲。","rad":"帛","fq":"居飲切","vol":"07","py":"jǐn","duan":[{"e":"襄邑織文也。","n":"漢地理志、郡國志陳畱郡屬縣有襄邑。今河南歸德府睢州治卽故縣地。地理志云。縣有服官。李善引陳畱記云。襄邑渙水出其南。睢水經其北。傳云。睢渙之閒出文章。故其黼黻絺繡。日月華蟲。以奉宗廟御服焉。司馬彪輿服志云。襄邑歲獻織成虎文。按許以漢法釋古。謂若今之襄邑織文卽經典之錦文也。毛傳。貝、逗錦文也。禹貢。厥匪織貝。鄭注云。貝、錦名也。凡爲織者。先染其絲。乃織之。則成文矣。禮記云。士不衣織。"}]},"白":{"expl":"西方色也。陰用事，物色白。从入合二。二，陰數。凡白之屬皆从白。","rad":"白","fq":"㫄陌切","vol":"07","py":"bái","duan":[{"e":"西方色也。侌用事。物色白。从入合二。","n":"出者陽也。入者陰也。故从入。"}]},"皎":{"expl":"月之白也。从白交聲。《詩》曰：“月出皎兮。”","rad":"白","fq":"古了切","vol":"07","py":"jiǎo","duan":[{"e":"月之白也。","n":"上文云。物色白。不一其物則不一其白。故皆爲分別之䛐。"}]},"皢":{"expl":"日之白也。从白堯聲。","rad":"白","fq":"呼鳥切","vol":"07","py":"xiǎo","duan":[{"e":"日之白也。","n":"先月後日者、月陰日陽。月之白其正色也。"}]},"芽":{"expl":"萌芽也。从艸牙聲。","rad":"艸","fq":"五加切","vol":"01","py":"yá","duan":[{"e":"芽、","n":"逗。"}]},"皙":{"expl":"人色白也。从白析聲。","rad":"白","fq":"旡撃切","vol":"07","py":"xī","duan":[{"e":"人色白也。","n":"鄘風。揚且之皙也。傳曰。晳、白晳也。"}]},"皤":{"expl":"老人白也。从白番聲。《易》曰：“賁如皤如。”","rad":"白","fq":"薄波切","vol":"07","py":"pó","duan":[{"e":"老人白也。","n":"易釋文、文𨕖兩都賦注皆作老人皃。非是。老人之色白與少壯之白晳不同。故以次於晳。兩都賦曰。皤皤國老。周易。賁六四。賁如皤如。引伸爲凡白素之偁也。"}]},"㿥":{"expl":"鳥之白也。从白隺聲。","rad":"白","fq":"胡沃切","vol":"07","py":"hé","duan":[{"e":"鳥之白也。","n":"景福殿賦曰。㿥㿥白鳥。李善曰。㿥與翯音義同。"}]},"皚":{"expl":"霜雪之白也。从白豈聲。","rad":"白","fq":"五來切","vol":"07","py":"ái","duan":[{"e":"霜雪之白也。","n":"辭賦家多用皚皚字。"}]},"皅":{"expl":"艸華之白也。从白巴聲。","rad":"白","fq":"普巴切","vol":"07","py":"pā","duan":[{"e":"艸𦾓之白也。","n":"葩字从此。靈樞經曰。紛紛皅皅。終而復始。紛紛皅皅、葢言多也。"}]},"皦":{"expl":"玉石之白也。从白敫聲。","rad":"白","fq":"古了切","vol":"07","py":"jiǎo","duan":[{"e":"玉石之白也。","n":"王風。有如皦日。傳曰。皦、白也。按此叚皦爲皢也。論語。皦如也。何曰。言樂之音節分明也。此其引伸之義也。"}]},"𡭴":{"expl":"際見之白也。从白，上下小見。","rad":"白","fq":"起戟切","vol":"07","py":"xì","duan":[{"e":"際見之白也。","n":"際者、壁會也。壁會者、隙也。見讀如現。壁隙之光一綫而巳。故从二小。"}]},"皛":{"expl":"顯也。从三白。讀若皎。","rad":"白","fq":"烏皎切","vol":"07","py":"xiào","duan":[{"e":"顯也。","n":"顯當作㬎。顯、頭明飾也。㬎、衆明也。顯行而㬎廢矣。許云古文以㬎爲顯。則小篆以顯爲㬎久矣。倉頡篇曰。皛、明也。按蜀都賦。皛貙氓於葽艸。貙氓、貙人也。江漢有貙人。能化爲虎。然則皛者、謂顯其形也。李善云當爲拍。誤。"}]},"㡀":{"expl":"敗衣也。从巾，象衣敗之形。凡㡀之屬皆从㡀。","rad":"㡀","fq":"毗祭切","vol":"07","py":"bì","duan":[{"e":"敗衣也。","n":"此敗衣正字。自敝專行而㡀廢矣。"}]},"敝":{"expl":"帗也。一曰敗衣。从攴从㡀，㡀亦聲。","rad":"㡀","fq":"毗祭切","vol":"07","py":"bì","duan":[{"e":"帗也。","n":"帗者、一幅巾也。"}]},"萌":{"expl":"艸芽也。从艸明聲。","rad":"艸","fq":"武庚切","vol":"01","py":"ménɡ","duan":[{"e":"艸木芽也。","n":"木字依玉篇補。說文以艸木芽、艸木榦、艸木葉聮綴成文。？芽析言則有別。尚書大傳。周以至動、殷以萌、夏以牙是也。統言則不別。故曰？、艸木芽也。月令。句者畢出。？者盡達。注。句、屈生者。𦬆而直曰？。樂記作區？。"}]},"黹":{"expl":"箴縷所紩衣。从㡀，丵省。凡黹之屬皆从黹。","rad":"黹","fq":"陟几切","vol":"07","py":"zhǐ","duan":[{"e":"箴縷所紩衣也。","n":"箴當作鍼。箴所以綴衣。鍼所以縫也。紩、縫也。縷、綫也。絲亦可爲綫矣。以鍼貫縷紩衣曰黹。釋言曰。黹、紩也。臯陶謨曰。絺繡。鄭本作希。注曰。希讀爲黹。黹、紩也。周禮司服希冕。鄭注引書希繡。又云。希讀爲黹。或作絺。字之誤也。今本周禮注疏傳寫倒亂。今俗語云鍼黹是此字。按許多云希聲而無希篆。疑希者古文黹也。从巾。上象繡形。"}]},"𪓐":{"expl":"合五采鮮色。从黹虘聲。《詩》曰：“衣裳𪓐𪓐。”","rad":"黹","fq":"創舉切","vol":"07","py":"chǔ","duan":[{"e":"會五采鮮皃。","n":"本作合五采鮮色。今依廣䪨、韵會訂。曹風蜉蝣曰。衣裳楚楚。傳曰。楚楚、鮮明皃。許所本也。𪓐其正字。楚其叚借字也。葢三家詩有作𪓐𪓐者。如毛革、韓𦑜之比。"}]},"黼":{"expl":"白與黑相次文。从黹甫聲。","rad":"黹","fq":"方榘切","vol":"07","py":"fǔ","duan":[{"e":"白與黑相次文。","n":"攷工記文。鄭曰。文章黼黻繡五者。言刺繡采所用也。繡以爲裳。"}]},"黻":{"expl":"黑與青相次文。从黹犮聲。","rad":"黹","fq":"分勿切","vol":"07","py":"fú","duan":[{"e":"黑與靑相次文。","n":"攷工記文。"}]},"𪓌":{"expl":"會五采繒色。从黹，綷省聲。","rad":"黹","fq":"子對切","vol":"07","py":"zuì","duan":[{"e":"會五采繒也。","n":"也本作色。今依廣韵訂。五采繒者、五采帛也。大人賦。綷雲葢。如淳云。葢有五色也。吳都賦。孔雀綷羽以翱翔。按綷者、或𪓌字。"}]},"黺":{"expl":"衮衣山龍華蟲。黺，畫粉也。从黹，从粉省。衞宏說。","rad":"黹","fq":"方吻切","vol":"07","py":"fěn","duan":[{"e":"袞衣山龍華蟲黺畫粉也。","n":"皋陶謨曰。日、月、星、辰、山龍、蕐蟲作繪。宗𢑴、藻、火、粉米、黼、黻絺繡。鄭注云。畫者爲繪。刺者爲繡。繡與繪各有六。衣用繪。裳用繡。許書繪下云。會五采繡也。藻作璪。粉作黺。米作䋛。鄭粉米爲一事。許黺䋛爲二事。鄭說粉米爲繡。許說黺爲畫紛。䋛爲繡文如聚米。葢許時鄭說未出。許以說黺系諸衞宏。但今缺有閒矣。且尙書山龍華蟲不與粉相屬。許書恐轉寫有奪誤。畫粉葢何晏賦所謂分閒布白。"}]},"人":{"expl":"天地之性最貴者也。此籒文。象臂脛之形。凡人之屬皆从人。","rad":"人","fq":"如鄰切","vol":"08","py":"rén","duan":[{"e":"天地之性冣貴者也。","n":"冣本作最。性古文以爲生字。左傳。正德利用厚生。國語作厚性是也。許偁古語不改其字。禮運曰。人者、其天地之德。陰陽之交。鬼神之會。五行之秀氣也。又曰。人者、天地之心也。五行之端也。食味別聲被色而生者也。按禽獸艸木皆天地所生。而不得爲天地之心。惟人爲天地之心。故天地之生此爲極貴。天地之心謂之人。能與天地合德。果實之心亦謂之人。能復生艸木而成果實。皆至微而具全體也。果人之字、自宋元以前本艸方書詩歌紀載無不作人字。自明成化重刊本艸乃盡改爲仁字。於理不通。學者所當知也。○仁者、人之德也。不可謂人曰仁。其可謂果人曰果仁哉。金泰和閒所刊本艸皆作人。藏袁廷檮所。"}]},"僮":{"expl":"未冠也。从人童聲。","rad":"人","fq":"徒紅切","vol":"08","py":"tónɡ","duan":[{"e":"未冠也。","n":"辛部曰。男有辠曰奴。奴曰童。按說文僮童之訓與後人所用正相反。如穜種二篆之比。今經傳僮子字皆作童子。非古也。襍記注曰。童、未成人之稱。學記注曰。成童、十五以上。引伸爲僮蒙。玉篇引詩。狂僮之狂也且。傳曰。狂行、僮昏所化也。廣雅曰。僮、癡也。若召南僮僮、竦敬也。則又如愚之義也。"}]},"保":{"expl":"養也。从人，从𤓽省。𤓽，古文孚。","rad":"人","fq":"博袌切","vol":"08","py":"bǎo","duan":[{"e":"養也。","n":"宣帝紀阿𠈃之功。臣瓚曰。阿倚、𠈃養也。賈誼說大師大傳大𠈃曰。𠈃者、𠈃其身體。按𠈃全、𠈃守皆其引伸之義。南山有臺傳曰。𠈃、安也。"}]},"仁":{"expl":"親也。从人从二。","rad":"人","fq":"如鄰切","vol":"08","py":"rén","duan":[{"e":"親也。","n":"見部曰。親者、密至也。"}]},"茁":{"expl":"艸初生出地皃。从艸出聲。《詩》曰：“彼茁者葭。”","rad":"艸","fq":"鄒滑切","vol":"01","py":"zhuó","duan":[{"e":"艸初生地皃。从艸出。","n":"依韵㑹所引。鄒滑切。十五部。言㑹意以包形聲也。"}]},"企":{"expl":"舉踵也。从人止聲。","rad":"人","fq":"去智切","vol":"08","py":"qì","duan":[{"e":"舉歱也。","n":"歱各本作踵。非。今正。歱者、跟也。企或作跂。衞風曰。跂予望之。檀弓曰。先王之制禮也。過之者俯而就之。不至焉者跂而及之。方言。跂、登也。梁益之閒語。"}]},"仞":{"expl":"伸臂一尋，八尺。从人刃聲。","rad":"人","fq":"而震切","vol":"08","py":"rèn","duan":[{"e":"伸臂一尋八尺。","n":"按此解疑非許之舊。恐後人改竄爲之。尺部下云。周制寸尺咫尋常仞諸度量。皆以人之體爲法。假令尋仞同物。許不當㒳舉之矣。諸家之說仞也。王肅、趙岐、王逸、曹操、李筌、顏師古、房玄齡、鮑彪諸人並曰八尺。而鄭周禮儀禮注、包咸論語注、高誘注呂氏春秋、王逸注大招招䰟、李謐明堂制度論、郭璞注司馬相如賦用司馬彪之說、陸德明莊子釋文則皆謂七尺。淮南子原道訓注八尺。而覽冥訓注則云七尺。百仞者七百尺。證以呂氏春秋注則原道注可疑。近歙程氏瑤田通藝錄有說曰。言七尺者是也。楊雄方言云。度廣曰尋。杜預左傳仞溝洫注。度深曰仞。二書皆言人伸㒳手以度物之名。而尋爲八尺、仞必七尺者、何也。同一伸手度物。而廣深用之。其勢自不得不異。人長"}]},"仕":{"expl":"學也。从人从士。","rad":"人","fq":"鉏里切","vol":"08","py":"shì","duan":[{"e":"學也。","n":"訓仕爲入官。此今義也。古義宧訓仕。仕訓學。故毛詩傳五言士、事也。而文王有聲傳亦言仕、事也。是仕與士皆事其事之謂。學者、覚悟也。事其事則日就於覚悟也。若論語子張篇。子夏曰。仕而優則學。學而優則仕。公冶長篇。子使漆雕開仕。注云。仕、仕於朝也。以仕學分出處。起於此時矣。許說其故訓。"}]},"佼":{"expl":"交也。从人从交。","rad":"人","fq":"下巧切","vol":"08","py":"jiāo","duan":[{"e":"交也。","n":"佼見管子明法解。曰。羣臣皆㤀主而趨私佼。又曰。養所與佼而不以官爲務。又曰。小臣持祿養佼。不以官爲事。其訓皆交也。而韵會引小徐本作好也。鍇引史記後有長姣美人。按小徐本女部。姣、好也。引史記長姣美人。韵會移入此。甚誤。"}]},"僎":{"expl":"具也。从人巽聲。","rad":"人","fq":"士勉切","vol":"08","py":"zhuàn","duan":[{"e":"具也。","n":"具者、共置也。論語有公叔文子之臣大夫僎。𨜮飲酒禮。遵者降席。注曰。今文遵爲僎。或爲全。禮記從今文禮作僎。"}]},"俅":{"expl":"冠飾皃。从人求聲。《詩》曰：“弁服俅俅。”","rad":"人","fq":"巨鳩切","vol":"08","py":"qiú","duan":[{"e":"冠飾皃。","n":"周頌絲衣曰。載弁俅俅。釋訓曰。俅俅、服也。傳曰。俅俅、恭順（玉篇作愼）皃。按許以上文紑屬衣言之。則俅俅亦當屬冠言之。故此用爾雅、易傳義。而紑下不易傳也。"}]},"佩":{"expl":"大帶佩也。从人从凡从巾。佩必有巾，巾謂之飾。","rad":"人","fq":"蒲妹切","vol":"08","py":"pèi","duan":[{"e":"大帶佩也。","n":"大帶佩者、謂佩必系於大帶也。古者有大帶、有革帶。佩系於革帶。不在大帶。何以言大帶佩也。革帶統於大帶也。許於糸部之紳、革部之鞶皆曰大帶。實則紳爲大帶、鞶爲革帶也。佩者、內則左右佩用是。"}]},"儒":{"expl":"柔也。術士之偁。从人需聲。","rad":"人","fq":"人朱切","vol":"08","py":"rú","duan":[{"e":"柔也。","n":"以疊韵爲訓。鄭目錄云。儒行者、以其記有道德所行。儒之言優也、柔也。能安人。能服人。又儒者、濡也。以先王之道能濡其身。玉藻注曰。舒儒者、所畏在前也。"}]},"俊":{"expl":"材千人也。从人夋聲。","rad":"人","fq":"子峻切","vol":"08","py":"jùn","duan":[{"e":"材過千人也。","n":"大徐本無過字。尹文子曰。千人才曰俊。萬人曰傑。淮南泰俗訓曰。智過萬人者謂之英。千人者謂之俊。百人者謂之豪。十人者謂之傑。春秋繁露曰。萬人者曰英。千人者曰俊。百人者曰傑。十人者曰豪。皋陶謨鄭注。曰才德過千人爲俊。百人爲乂。呂氏春秋孟秋紀高注曰。才過萬人曰桀。千人曰俊。王逸注懷沙曰。千人才爲俊。一國高爲桀。諸家說俊皆同。惟月令正義引蔡氏辨名記云。十人曰𨕖。倍𨕖曰俊。萬人曰桀。其說不同。方言曰。𡤼、俊也。遵、俊也。○又按月令疏蔡氏下奪引字。辨名記卽白虎通之別名記。古文記二百十四篇之一也。禮運及左傳宣十五年疏皆引辨名記云。倍人曰茂。十人曰𨕖。倍𨕖曰俊。千人曰英。倍英曰賢。萬人曰桀。倍桀曰聖。語較完。而"}]},"傑":{"expl":"傲也。从人桀聲。","rad":"人","fq":"渠列切","vol":"08","py":"jié","duan":[{"e":"埶也。","n":"以疊韵爲訓。埶本穜埶字。引伸爲勢力字。傑者言其勢傑然也。衞風毛傳曰。桀、特立也。"}]},"莖":{"expl":"枝柱也。从艸巠聲。","rad":"艸","fq":"戶耕切","vol":"01","py":"jīnɡ","duan":[{"e":"艸木榦也。","n":"依玉篇所引。此言艸而兼言木。今本作枝柱。考字林作枝主。謂爲衆枝之主也。葢或用字林改說文。而主又譌柱。"}]},"㑮":{"expl":"人姓。从人軍聲。","rad":"人","fq":"吾昆切","vol":"08","py":"wén","duan":[{"e":"人姓。从人。軍聲。","n":"吾昆切。十三部。按此篆必淺人所增。許書自女部外。䍐有言人姓者。且廣韵此字䰟韵㒳見。云女字。又姓。出纂文。此姓旣出何氏之書。安得云出許書乎。"}]},"伋":{"expl":"人名。从人及聲。","rad":"人","fq":"居立切","vol":"08","py":"jí","duan":[{"e":"人名。","n":"以引爲解。亦非例也。古人名字相應。孔伋字子思。仲尼弟子燕伋字子思。然則伋字非無義矣。人名二字非許書之舊也。荀𨜮曰。空石之中有人焉。其名曰觙。其爲人也。善射。以好思闢耳目之欲。遠蚊䖟之聲。閑居靜思則通。思仁若是。可謂微乎。此葢設言善思之人。名之以觙乎。觙與伋音義葢相近。"}]},"伉":{"expl":"人名。从人亢聲。《論語》有陳伉。","rad":"人","fq":"苦浪切","vol":"08","py":"kànɡ","duan":[{"e":"人名。","n":"非例也。左傳。施氏婦曰。不能庇其伉儷。杜注曰。伉、敵也。儷偶也。"}]},"伯":{"expl":"長也。从人白聲。","rad":"人","fq":"博陌切","vol":"08","py":"bó","duan":[{"e":"長也。","n":"釋詁、正月傳同。載芟傳云。伯、長子也。伯兮傳云。伯、州伯也。一義之引伸也。凡爲長者皆曰伯。古多假柏爲之。"}]},"仲":{"expl":"中也。从人从中，中亦聲。","rad":"人","fq":"直衆切","vol":"08","py":"zhònɡ","duan":[{"e":"中也。","n":"白虎通同。伯仲叔季爲長少之次。伯仲見於此。子部曰。季、少偁也。叔則少之假借字也。古者幼名、冠字。冠字者、爲之且字也。且字也者、若尼甫嘉甫是也。五十以伯仲。乃偁伯某甫、仲某甫。以伯仲而後成字。伯仲之下一字爲且字。且者、薦也。爲伯仲之薦也。伯仲生而已定。故士冠禮字辭曰。伯某甫。雖定此字。而五十以前但偁某甫也。女子筓而字。則曰伯姬、曰仲姬。毛傳於大明曰。仲、中女也。於燕燕曰。仲、字也。皆言婦人也。二傳其實一也。古中仲二字互通。"}]},"伊":{"expl":"殷聖人阿衡，尹治天下者。从人从尹。","rad":"人","fq":"於脂切","vol":"08","py":"yī","duan":[{"e":"殷聖人阿衡也。","n":"殷聖人之上當有伊尹二字。傳寫奪之。阿衡見商頌。毛傳曰。阿衡、伊尹也。箋云。阿倚、衡平也。伊尹、湯所依倚而取平。故以爲官名。伊與阿、尹與衡皆雙聲。然則一語之轉也。許云伊尹、殷聖人阿衡也。本毛說。不言伊尹爲姓名也。諸家或云伊氏尹字。或云名摯。皆所傳聞異辭耳。禮記所偁古文尙書㒳言尹躬。則尹實其名。"}]},"偰":{"expl":"高辛氏之子，堯司徒，殷之先。从人契聲。","rad":"人","fq":"私列切","vol":"08","py":"xiè","duan":[{"e":"高辛氏之子。爲堯司徒。殷之先也。","n":"爲字依玉篇補。左傳曰。高辛氏有才子八人。伯奮、仲堪、叔獻、季仲、伯虎、仲熊、叔豹、季貍。舜臣堯。舉八元。使布五教於四方。父義、母慈、兄友、弟恭、子孝。內平外成。偰卽八元之一人也。毛詩傳曰。玄王契也。經傳多作契。古亦假禼爲之。米部曰。禼古文偰。言古文假借字也。"}]},"倩":{"expl":"人字。从人青聲。東齊壻謂之倩。","rad":"人","fq":"倉見切","vol":"08","py":"qiàn","duan":[{"e":"人美字也。","n":"依韵會本訂。朱邑傳。陳平雖賢。須魏倩而後進。師古曰。倩、士之美稱也。葢本說文。而改人爲士。改字爲稱。其實可無改也。倩猶甫也。穀梁傳曰。父（同甫）猶傅也。男子之美稱也。男子之字有稱甫者。儀甫、嘉甫是。有偁倩者。蕭長倩、東方曼倩、韋昭云倩魏無知字也皆是。倩、好也。毛傳說倩曰。好口輔。以詩言巧笑。故知爲口輔好也。"}]},"伃":{"expl":"婦官也。从人予聲。","rad":"人","fq":"以諸切","vol":"08","py":"yú","duan":[{"e":"婦官也。","n":"漢書外戚傳。婦官十四等。昭儀位視丞相。比諸侯王。倢伃視上卿比列矦韋昭曰倢承伃助也漢舊儀云皇后爲倢伃下輿禮比丞相按婦官上當有倢抒二字淺人𠜂之倢之本訓佽也見下"}]},"伀":{"expl":"志及眾也。从人公聲。","rad":"人","fq":"職茸切","vol":"08","py":"zhōnɡ","duan":[{"e":"志及眾也。","n":"與公同義。其音當同。引伸爲夫兄曰兄伀之字。或作妐。若方言、廣雅之佂伀。卽今怔忪字也。"}]},"莛":{"expl":"莖也。从艸廷聲。","rad":"艸","fq":"特丁切","vol":"01","py":"tínɡ","duan":[{"e":"莖也。","n":"說苑。建天下之鳴鐘。撞之以莛。"}]},"儇":{"expl":"慧也。从人瞏聲。","rad":"人","fq":"許緣切","vol":"08","py":"xuān","duan":[{"e":"慧也。","n":"心部慧下曰。儇也。是二字互訓也。齊風。揖我謂我儇兮。傳曰。儇、利也。此言慧者多便利也。方言。儇、慧也。荀𨜮子曰。鄉曲之儇子。"}]},"倓":{"expl":"安也。从人炎聲。讀若談。","rad":"人","fq":"徒甘切","vol":"08","py":"tán","duan":[{"e":"安也。","n":"倉頡篇曰。倓、恬也。荀𨜮子曰。桓公倓然管仲之能足以託國也。洞簫賦。時恬倓以綏肆。按蠻夷贖罪貨曰倓。此夷語耳。字亦作賧。"}]},"侚":{"expl":"疾也。从人旬聲。","rad":"人","fq":"辤閏切","vol":"08","py":"xùn","duan":[{"e":"疾也。","n":"五帝本紀。黃帝幼而侚齊。裴駰曰。侚疾、齊速也。素問上古天眞論。黃帝幼而侚齊。長而敦敏。王注。侚、疾也。按侚今本譌作徇。司馬貞乃云未見所出矣。釋言。宣、徇、徧也。徇本又作侚。墨子。年踰五十。則聰明思慮不徇通矣。徇亦當作侚。史記侚齊、大戴禮作叡齊。亦作慧齊。"}]},"傛":{"expl":"不安也。从人容聲。一曰華。","rad":"人","fq":"余隴切","vol":"08","py":"yǒnɡ","duan":[{"e":"不安也。","n":"與水波溶溶意義略同。皆動湯皃也。"}]},"僷":{"expl":"宋衞之間謂華僷僷。从人葉聲。","rad":"人","fq":"與涉切","vol":"08","py":"yè","duan":[{"e":"宋衞之閒謂華僷僷。","n":"華、容華也。僷僷、好皃。方言曰。奕、僷、容也。凡美容謂之奕。或謂之僷。宋衞曰僷。陳楚汝潁之閒謂之奕。按僷亦作偞。廣韵曰。偞偞、輕薄美好皃。"}]},"佳":{"expl":"善也。从人圭聲。","rad":"人","fq":"古膎切","vol":"08","py":"jiā","duan":[{"e":"善也。","n":"廣韵曰。佳、善也。又曰。好也。又曰。大也。老子。佳兵者不祥。淮南說林訓曰。佳人不同體。美人不同面。而皆說於目。"}]},"侅":{"expl":"奇侅，非常也。从人亥聲。","rad":"人","fq":"古哀切","vol":"08","py":"ɡāi","duan":[{"e":"奇侅、","n":"逗"}]},"傀":{"expl":"偉也。从人鬼聲。《周禮》曰：“大傀異。”","rad":"人","fq":"公回切","vol":"08","py":"ɡuī","duan":[{"e":"偉也。","n":"方言𠐤、盛也。注言瓌瑋也。廣雅。傀、盛也。司馬注莊子曰。傀、大也。字林。傀、偉也。"}]},"偉":{"expl":"奇也。从人韋聲。","rad":"人","fq":"于鬼切","vol":"08","py":"wěi","duan":[{"e":"奇也。","n":"莊子曰。偉哉夫造物者。"}]},"份":{"expl":"文質僣也。从人分聲。《論語》曰：“文質份份。”","rad":"人","fq":"府巾切","vol":"08","py":"bīn","duan":[{"e":"文質僃也。","n":"僃當作𤰈。許訓𤰈曰具。訓僃曰愼。說解內字多自亂其例。葢許時所用固與古不同。許以後人又多竄改。二者皆有之矣。論語雍也篇。文質彬彬。然後君子。包咸注曰。彬彬、文質相襍之皃也。鄭注曰。彬彬、襍半皃也。按古謂集爲襍。集、聚也。"}]},"葉":{"expl":"艸木之葉也。从艸枼聲。","rad":"艸","fq":"与涉切","vol":"01","py":"yè","duan":[{"e":"艸木之葉也。","n":"凡物之薄者、皆得以葉名。"}]},"僚":{"expl":"好皃。从人尞聲。","rad":"人","fq":"力小切","vol":"08","py":"liǎo","duan":[{"e":"好皃。","n":"陳風。皎人僚兮。傳曰。僚、好皃。此僚之本義也。自借爲同寮字而本義廢矣。"}]},"佖":{"expl":"威儀也。从人必聲。《詩》曰：“威儀佖佖。”","rad":"人","fq":"毗必切","vol":"08","py":"bì","duan":[{"e":"威儀也。","n":"按此當作威儀媟嫚也。小雅賓之初筵曰。威儀怭怭。傳曰。怭怭、媟嫚也。許所據作佖佖。自奪媟嫚字。韵會、廣韵徑注云有威儀矣。"}]},"𠊩":{"expl":"具也。从人孨聲。讀若汝南𣹏水。《虞書》曰：“㫄救𠊩功。”","rad":"人","fq":"士戀切","vol":"08","py":"zhuàn","duan":[{"e":"具也。","n":"馬注尙書同。五帝本紀曰。旁聚布功。釋以布也。"}]},"儠":{"expl":"長壯儠巤也。从人巤聲。《春秋傳》曰：“長儠者相之。”","rad":"人","fq":"良涉切","vol":"08","py":"liè","duan":[{"e":"長壯儠儠也。","n":"左傳昭七年十七年、國語楚語皆云長鬣。鬣者、儠之假借字也。韋昭、杜預釋爲美須䫇。誤。廣雅曰。儠、長也。按儠儠、長壯皃。辭賦家用獵獵字。葢當作儠儠。"}]},"儦":{"expl":"行皃。从人麃聲。《詩》曰：“行人儦儦。”","rad":"人","fq":"甫嬌切","vol":"08","py":"biāo","duan":[{"e":"行皃","n":"齊風載驅曰。行人儦儦。傳曰。儦儦、衆皃。許曰行皃者、義得互相足也。廣雅亦曰。儦儦、行也。玉篇曰。儦儦、盛皃也。"}]},"儺":{"expl":"行人節也。从人難聲。《詩》曰：“佩玉之儺。”","rad":"人","fq":"諾何切","vol":"08","py":"nuó","duan":[{"e":"行有節也。","n":"衞風竹竿曰。佩玉之儺。傳曰。儺、行有節度。按此字之本義也。其𢿛疫字本作難。自假儺爲𢿛疫字。而儺之本義廢矣。其曹風之猗儺。則說文之旖施也。"}]},"倭":{"expl":"順皃。从人委聲。《詩》曰：“周道倭遟。”","rad":"人","fq":"於爲切","vol":"08","py":"wēi","duan":[{"e":"順皃。","n":"倭與委義略同。委、隨也。隨、從也。廣韵作愼皃。乃梁時避諱所改耳。"}]},"僓":{"expl":"嫺也。从人貴聲。一曰長皃。","rad":"人","fq":"吐猥切","vol":"08","py":"tuǐ","duan":[{"e":"嫺也。","n":"嫺者、雅也。"}]},"僑":{"expl":"高也。从人喬聲。","rad":"人","fq":"巨嬌切","vol":"08","py":"qiáo","duan":[{"e":"高也。","n":"僑與喬義略同。喬者、高而曲也。自用爲㝯寓字。而僑之本義廢矣。字林始有㝯字。云寄客爲㝯。按春秋有叔孫僑如、有公孫僑字子產。皆取高之義也。"}]},"俟":{"expl":"大也。从人矣聲。《詩》曰：“伾伾俟俟。”","rad":"人","fq":"牀史切","vol":"08","py":"sì","duan":[{"e":"大也。","n":"此俟之本義也。自經傳假爲竢字。而俟之本義廢矣。立部曰。竢、待也。廢竢而用俟。則竢俟爲古今字矣。"}]},"𦺶":{"expl":"艸之小者。从艸㓹聲。㓹，古文銳字。讀若芮。","rad":"艸","fq":"居例切","vol":"01","py":"jì","duan":[{"e":"艸之小者。从艸。㓹聲。㓹、古文銳字。","n":"按金部、网部皆云。㓹、籒文銳。則此古字誤也。當改籒。"}]},"侗":{"expl":"大皃。从人同聲。《詩》曰：“神罔時侗。”","rad":"人","fq":"他紅切","vol":"08","py":"tōnɡ","duan":[{"e":"大皃。","n":"此義未見其證。然同義近大。則侗得爲大皃矣。論語。侗而不愿。孔注曰。侗、未成器之人。按此大義之引伸。猶言渾沌未鑿也。"}]},"佶":{"expl":"正也。从人吉聲。《詩》曰：“旣佶且閑。”","rad":"人","fq":"巨乙切","vol":"08","py":"jí","duan":[{"e":"正也。","n":"小雅六月傳曰。佶、正也。箋云。佶、壯健之皃。按鄭以言壯健乃可皃馬。但毛言正自可含壯健也。"}]},"俁":{"expl":"大也。从人吳聲。《詩》曰：“碩人俁俁。”","rad":"人","fq":"魚禹切","vol":"08","py":"yǔ","duan":[{"e":"大也。","n":"邶風𥳑兮曰。碩人俁俁。傳曰。俁俁、容皃大也。"}]},"仜":{"expl":"大腹也。从人工聲。讀若紅。","rad":"人","fq":"戶工切","vol":"08","py":"hónɡ","duan":[{"e":"大腹也。","n":"與𨾊音義略同。廣韵曰。身肥大也。廣雅曰。仜、有也。"}]},"僤":{"expl":"疾也。从人單聲。《周禮》曰：“句兵欲無僤。”","rad":"人","fq":"徒案切","vol":"08","py":"dàn","duan":[{"e":"疾也。","n":"速疾。"}]},"健":{"expl":"伉也。从人建聲。","rad":"人","fq":"渠建切","vol":"08","py":"jiàn","duan":[{"e":"伉也。","n":"伉下曰人名。而不言其義。以此云伉也證之。則知人名二字非許書之舊矣。周易曰。乾、健也。"}]},"倞":{"expl":"彊也。从人京聲。","rad":"人","fq":"渠竟切","vol":"08","py":"jìnɡ","duan":[{"e":"彊也。","n":"廣雅。倞、強也。按大雅無競維人傳曰。無競、競也。箋云。競、彊也。秉心無競傳曰。競、彊也。周頌無競維人傳曰。競、彊也。執競武王傳曰。執競、競也。箋云。競、彊也。按傳、箋皆謂競爲倞之假借字也。郊特牲。祊之爲言倞也。注。倞、猶索也。倞不訓索。而與水部之滰音同。滰者、浚乾漬米也。索求神似之。"}]},"傲":{"expl":"倨也。从人敖聲。","rad":"人","fq":"五到切","vol":"08","py":"ào","duan":[{"e":"倨也。","n":"按此當與下倨不遜也連屬。仡篆當與健倞二篆相屬。葢此部經傳寫旣久失其舊者多矣。古多假敖爲傲。女部又出嫯字。侮㑥也。"}]},"仡":{"expl":"勇壯也。从人气聲。《周書》曰：“㐹㐹勇夫。”","rad":"人","fq":"魚訖切","vol":"08","py":"yì","duan":[{"e":"勇壯也。","n":"秦誓曰。仡仡勇夫。某氏曰。仡仡壯勇之夫。公羊傳。趙盾之車右祁彌明者。國之力士也。仡然從乎趙盾而入。何云。仡然、壯勇皃。若詩崇墉仡仡。毛曰。高大也。引伸之義也。土部引作圪圪。"}]},"倨":{"expl":"不遜也。从人居聲。","rad":"人","fq":"居御切","vol":"08","py":"jù","duan":[{"e":"不遜也。","n":"遜當是本作孫。說詳辵部。孫者、逡循恭敬之意。戰國策曰。何前倨而後恭。引伸之凡侈曰倨。凡斂曰句。（音鈎）大戴禮。與其倨也寧句。樂記。倨中矩。句中鉤。左傳。直而不倨。曲而不屈。准南子。句爪倨牙。凡言侈斂之度</p><p class=\"chinese\" style=\"color: #000; line-height: 20px; font-size: 17px; padding-bottom: 4px;\">昂當是本作卬淺人所改也卬者朢欲有所庶及也陳風碩大且儼傳曰儼矜莊皃曲禮注同古借嚴爲之謂之倨句。𦒱工記曰。倨句一矩有半。又曰。倨句磬折。卽謂一矩有半也。又曰。倨句外博。謂侈於一矩而不及一矩有半也。又曰"}]},"芣":{"expl":"華盛。从艸不聲。一曰芣苢。","rad":"艸","fq":"縛牟切","vol":"01","py":"fú","duan":[{"e":"華盛。","n":"詩言江漢浮浮、雨雪浮浮皆盛皃。芣與浮聲相近。"}]},"儼":{"expl":"昂頭也。从人嚴聲。一曰好皃。","rad":"人","fq":"魚儉切","vol":"08","py":"yǎn","duan":[{"e":"昂頭也。","n":"昂當是本作卬。淺人所改也。卬者、望欲有所庶、及也。陳風。碩大且儼。傳曰。儼、矜莊皃。曲禮注同。古借嚴爲之。"}]},"傪":{"expl":"好皃。从人參聲。","rad":"人","fq":"倉含切","vol":"08","py":"cān","duan":[{"e":"好皃。","n":"未見其證。方言曰。傪、㥢也。㥢、惡也。此假傪爲慘也。"}]},"俚":{"expl":"聊也。从人里聲。","rad":"人","fq":"良止切","vol":"08","py":"lǐ","duan":[{"e":"賴也。","n":"賴各本作𦕼。此用方言改許書也。今依漢書季布傳晉灼注所引正。方言。俚、𦕼也。語之轉、字之假借耳。漢書曰。其畫無俚之至。無俚卽今所謂無賴。亦語之轉。古叚理爲之。孟子。稽大不理於口。趙注。理、賴也。大不賴人之口。"}]},"伴":{"expl":"大皃。从人半聲。","rad":"人","fq":"薄滿切","vol":"08","py":"bàn","duan":[{"e":"大皃。","n":"大雅。伴奐爾游矣。傳曰。伴奐、廣大有文章也。箋云。伴奐、自縱弛之意。𠬞部奐下一曰大也。故伴奐皆有大義。大學注。胖猶大也。胖不訓大。云猶者正謂胖卽伴之假借也。方言、廣雅、孟子注皆曰。般、大也。亦謂般卽伴。廣韵云。侶也。依也。今義也。夫部㚘下曰。讀若伴侶之伴。知漢時非無伴侶之語。許於俗語不之取耳。至聲類乃云伴侶。"}]},"俺":{"expl":"大也。从人奄聲。","rad":"人","fq":"於業切","vol":"08","py":"yàn","duan":[{"e":"大也。","n":"與𡘹義略同。𡘹大有餘也。其音當亦同。"}]},"僩":{"expl":"武皃。从人閒聲。《詩》曰：“瑟兮僩兮。”","rad":"人","fq":"下簡切","vol":"08","py":"xiàn","duan":[{"e":"武皃。","n":"衞風淇奧傳。瑟、矜莊皃。僩、寬大也。許言僩、武皃。與毛異者、以爾雅及大學皆曰瑟兮僩兮者恂栗也。恂或作峻。讀如嚴峻之峻。言其容皃嚴栗。與寬大不相應。故易之。僩左傳、方言、廣雅皆作撊。左傳。撊然授兵登陴。服注。撊然、猛皃也。杜注。撊然勁忿皃。方言。撊、猛也。晉魏之閒曰撊。廣雅亦曰。撊、猛也。而荀卿子塞者俄且通也。陋者俄且僩也。愚者俄且知也。則以陋陿與寬大反對。與毛合。葢大毛公固受詩於孫卿子者。"}]},"伾":{"expl":"有力也。从人丕聲。《詩》曰：“以車伾伾。”","rad":"人","fq":"敷悲切","vol":"08","py":"pī","duan":[{"e":"有力也。","n":"魯頌駉曰。以車伾伾。傳曰。伾伾、有力也。俟下引詩伾伾俟俟。"}]},"偲":{"expl":"彊力也。从人思聲。《詩》曰：“其人美且偲。”","rad":"人","fq":"倉才切","vol":"08","py":"cāi","duan":[{"e":"彊力也。","n":"齊風盧令曰。其人美且偲。傳曰。偲、才也。箋云。才、多才也。許云彊力者、亦取才之義申之。才之本義、艸木之初也。故用其引伸之義。若論語朋友切切偲偲。馬曰。相切責之皃。毛傳作切切節節。"}]},"倬":{"expl":"箸大也。从人㔬聲。《詩》曰：“倬彼雲漢。”","rad":"人","fq":"竹角切","vol":"08","py":"zhuō","duan":[{"e":"箸大也。","n":"箸大者、箸明之大也。小雅。倬彼甫田。傳曰。倬、明皃。大雅棫樸。倬彼云漢傳曰。倬、大也。許兼取之曰箸大。韓詩。菿彼甫田。音義同也。假菿爲倬也。"}]},"侹":{"expl":"長皃。一曰箸地。一曰代也。从人廷聲。","rad":"人","fq":"他鼎切","vol":"08","py":"tǐnɡ","duan":[{"e":"長皃。","n":"與挺音義略同。"}]},"葩":{"expl":"華也。从艸皅聲。","rad":"艸","fq":"普巴切","vol":"01","py":"pā","duan":[{"e":"華也。","n":"古光華字與花實字同義同音。葩之訓華者、艸木花也。亦華麗也。艸木花冣麗。故凡物盛麗皆曰華。韓愈曰。詩正而葩。謂正而文也。葩亦散也。通作皅。靈樞經曰。紛紛皅皅。終而復始。"}]},"倗":{"expl":"輔也。从人朋聲。讀若陪位。","rad":"人","fq":"步崩切","vol":"08","py":"pénɡ","duan":[{"e":"輔也。","n":"周禮士師。掌士之八成。七曰爲邦朋。注曰。朋黨相阿。使政不平者。故書朋作傰。鄭司農讀爲朋友之朋。按管子亦曰。練之以散羣傰署。皆卽倗字也。鳥部朋下曰。鳳飛、羣鳥從以萬數。故以爲朋黨字。葢朋黨字正作倗。而朋其假借字。然許云讀若陪。則似有別矣。"}]},"傓":{"expl":"熾盛也。从人扇聲。《詩》曰：“豔妻傓方處。”","rad":"人","fq":"式戰切","vol":"08","py":"shàn","duan":[{"e":"熾盛也。","n":"小雅十月之交曰。豓妻煽方處。傳曰。豓妻、褒姒。美色曰豓。煽熾也。按詩本作傓。後人以訓熾之故肊造煽字耳。古通作扇。魯詩。閻妻扇方處。方言。扇、助也。廣雅。扇、疾也。"}]},"儆":{"expl":"戒也。从人敬聲。《春秋傳》曰：“儆宮。”","rad":"人","fq":"居影切","vol":"08","py":"jǐnɡ","duan":[{"e":"戒也。","n":"與驚音義同。孟子引書。洚水儆予。用儆字。左傳國語亦用儆。毛詩。徒御不驚。周禮。驚戒羣吏。皆用警。鄭注周禮曰。警、勅戒之言也。韋注國語曰。儆、戒也。"}]},"俶":{"expl":"善也。从人叔聲。《詩》曰：“令終有俶。”一曰始也。","rad":"人","fq":"昌六切","vol":"08","py":"chù","duan":[{"e":"善也。","n":"按釋詁、毛傳皆曰。淑、善也。葢假借之字其正字則俶也。淑者、水之淸湛也。自淑行而俶之本義廢矣。"}]},"傭":{"expl":"均直也。从人庸聲。","rad":"人","fq":"余封切","vol":"08","py":"chōnɡ","duan":[{"e":"均也。直也。","n":"各本少上也字。今補。玉篇、廣韵皆曰。均也。直也。所據古本也。均之義有未盡。故更言直也。直謂無枉曲也。小雅。昊天不傭。釋言、毛傳皆曰。傭、均也。周禮典同。正聲緩。先鄭云。正者、不高不下。鐘形上下正傭。考工。摶身而鴻。注云。鴻、傭也。此謂鴻卽傭之假借字也。若廣雅云。傭、役也。謂役力受直曰傭。此今義也。"}]},"僾":{"expl":"仿佛也。从人愛聲。《詩》曰：“僾而不見。”","rad":"人","fq":"烏代切","vol":"08","py":"ài","duan":[{"e":"仿佛也。","n":"祭義曰。祭之日。入室僾然必有。見乎其位。正義云。僾、髣髴見也。見、如見親之在神位也。按僾與爾雅之薆隱也、烝民傳之愛隱也、竹部之𥴨蔽不見也、義相近。若大雅亦孔之僾。釋言及傳云僾、唈也。此謂僾爲<>之假借字。<>飲食屰氣。不得息也。"}]},"仿":{"expl":"相似也。从人方聲。","rad":"人","fq":"妃罔切","vol":"08","py":"fǎnɡ","duan":[{"e":"仿佛、","n":"逗。"}]},"佛":{"expl":"見不審也。从人弗聲。","rad":"人","fq":"敷勿切","vol":"08","py":"fú","duan":[{"e":"仿佛也。","n":"依玉篇。與全書例合。按髟部有髴解云。髴、若似也。卽佛之或字。"}]},"僁":{"expl":"聲也。从人悉聲。讀若㞕。","rad":"人","fq":"私列切","vol":"08","py":"xiè","duan":[{"e":"聲也。","n":"見釋言。謂聲之小者也。動作屑㞕聲也。廣韵曰。動草聲。又鷙鳥之聲。又僁僁、呻吟也。"}]},"僟":{"expl":"精謹也。从人幾聲。《明堂月令》：“數將僟終。”","rad":"人","fq":"巨衣切","vol":"08","py":"jī","duan":[{"e":"精謹也。","n":"僟謹雙聲。凜凜庶幾之意也。"}]},"吏":{"expl":"治人者也。从一从史，史亦聲。","rad":"一","fq":"力置切","vol":"01","py":"lì","duan":[{"e":"治人者也。","n":"治與吏同在第一部。此亦以同部曡韵爲訓也。"}]},"祈":{"expl":"求福也。从示斤聲。","rad":"示","fq":"渠稀切","vol":"01","py":"qí","duan":[{"e":"求福也。","n":"祈求雙聲。"}]},"芛":{"expl":"艸之葟榮也。从艸尹聲。","rad":"艸","fq":"羊捶切","vol":"01","py":"wěi","duan":[{"e":"艸之皇榮也。","n":"皇當作葟。或？字。釋艸曰。蕍芛葟華榮郭曰。今俗呼艸木華初生者爲芛。音䝐豬之䝐。"}]},"佗":{"expl":"負何也。从人它聲。","rad":"人","fq":"徒何切","vol":"08","py":"tuó","duan":[{"e":"負何也。","n":"負字葢淺人增之耳。小雅。舍彼有罪。予之佗矣。傳曰。佗、加也。此佗本義之見於經者也。佗之俗字爲駝、爲馱。𥻳變佗爲他。用爲彼之偁。古相問無它乎。衹作它。又君子偕老。委委佗佗。卽羔羊之委蛇委蛇也。傳云。委委者、行可委曲從迹也。佗佗者、德平易也。羔羊傳云。委蛇者、行可從迹也。語詳略不同。"}]},"何":{"expl":"儋也。从人可聲。","rad":"人","fq":"胡歌切","vol":"08","py":"hè","duan":[{"e":"儋也。","n":"何俗作荷。猶佗之俗作駝。儋之俗作擔也。商頌。百祿是何。何天之休。何天之龍。傳曰。何、任也。箋云。謂擔負。周易。何天之衢。虞翻曰。何、當也。何校滅耳。王肅云。何、荷擔也。又詩。何戈與祋。何蓑何笠。傳皆云。揭也。揭者、舉也。戈祋手舉之。蓑笠身舉之。皆擔義之引伸也。凡經曲作荷者皆後人所竄改。"}]},"儋":{"expl":"何也。从人詹聲。","rad":"人","fq":"都甘切","vol":"08","py":"dān","duan":[{"e":"何也。","n":"儋俗作擔。古書或假檐爲之。疑又擔之誤耳。韋昭齊語注曰。背曰負。肩曰儋。任、抱也。何、揭也。按統言之則以肩以手以背以首皆得云儋也。"}]},"供":{"expl":"設也。从人共聲。一曰供給。","rad":"人","fq":"俱容切","vol":"08","py":"ɡònɡ","duan":[{"e":"設也。","n":"設者、施陳也。釋詁。供、歭、𠔏、具也。按歭卽儲偫字。𠔏卽供之假借字。凡周禮皆以𠔏爲供。尙書一經訓奉訓待者皆作𠔏。其恭敬字皆作恭。衞包乃盡改𠔏爲恭。毛詩亦𠔏恭分別。總之。古經用𠔏爲供之假借。不用𠔏爲恭之假借。惟左傳三命茲益𠔏、其𠔏也如是、君命以𠔏、則借𠔏爲恭。鄭君箋詩所謂古之恭字或作𠔏者乎。詳古文尙書𢰅異。"}]},"偫":{"expl":"待也。从人从待。","rad":"人","fq":"直里切","vol":"08","py":"zhì","duan":[{"e":"待也。","n":"以疊韵爲訓。謂儲物以待用也。偫經典或作歭。或作庤。周頌臣工傳曰。庤、具也。庤、儲置屋下也。義本同。若崧高以歭其粻、粊誓歭乃糗糧、某氏傳云儲歭、則假借峙䠧不前字爲之。俗乃改从止爲从山、作峙。訓云山立、以附合之矣。釋詁云。供、歭、𠔏、具也。歭在說文爲偫。"}]},"儲":{"expl":"偫也。从人諸聲。","rad":"人","fq":"直魚切","vol":"08","py":"chǔ","duan":[{"e":"偫也。","n":"文𨕖注引作蓄也。或作具也。或作積也。又引謂蓄積之以待無也。葢兼舉演說文語。古者太子謂之儲君。"}]},"備":{"expl":"愼也。从人𤰈聲。","rad":"人","fq":"平祕切","vol":"08","py":"bèi","duan":[{"e":"愼也。","n":"心部曰。愼者、謹也。言部曰。謹者、愼也。得僃而三字同訓。或疑僃訓愼未盡其義。不知用部曰𤰈、具也。此今之僃字。僃行而𤰈廢矣。𤰈廢而僃訓具。尟知其古訓愼者。今義行而古義廢矣。凡許之書所以存古形古音古義也。方言曰。僃、咸也。此具之義也。又曰。藏、敕、戒、僃也。此愼之義也。"}]},"位":{"expl":"列中庭之左右謂之位。从人、立。","rad":"人","fq":"于備切","vol":"08","py":"wèi","duan":[{"e":"列中庭之左右。","n":"當作𠂇又。"}]},"儐":{"expl":"導也。从人賓聲。","rad":"人","fq":"必刃切","vol":"08","py":"bìn","duan":[{"e":"導也。","n":"導者、導引也。周禮與儀注曰。出接賓曰擯。聘禮。𨜮爲上擯。大夫爲承擯。士爲紹擯。注曰。擯謂主國之君所使出接賓者也。士冠禮。擯者請期。注曰。擯者、有司佐禮者。在主人曰擯。按擯經典多作擯。史記作賓。廉蘭列傳。設九賓於廷是也。○聘禮。賓用束錦儐勞者。又儐之如初。又儐之兩馬束錦。又無儐。凡言儐者九。鄭曰。上於下曰禮。敵者曰儐。上於下曰禮、謂如主國之禮聘賓是也。敵者曰儐、謂如儐勞者、儐歸饔餼者等是也。鄭據禮經字作儐。是以周禮司儀賓亦如之、賓使者如初之儀皆云賓當爲儐。易賓爲儐。取賓禮相待之義。非擯相之義也。然則合二禮訂之。擯相字當从手。賓禮字當从人。許儐擯合而一。云導也。與二禮及鄭說不合。劉昌宗說聘禮儐與擯"}]},"偓":{"expl":"佺也。从人屋聲。","rad":"人","fq":"於角切","vol":"08","py":"wò","duan":[{"e":"偓佺、","n":"逗。"}]},"蘳":{"expl":"黃華。从艸黊聲。讀若壞。","rad":"艸","fq":"乎瓦切","vol":"01","py":"huà","duan":[{"e":"黃華。","n":"後漢書馬融傳曰。蓶扈黊榮。黊或作蘳。"}]},"佺":{"expl":"偓佺，仙人也。从人全聲。","rad":"人","fq":"此緣切","vol":"08","py":"quán","duan":[{"e":"偓佺也。从人。全聲。","n":"此緣切。十四部。"}]},"㒤":{"expl":"心服也。从人聶聲。","rad":"人","fq":"齒涉切","vol":"08","py":"chè","duan":[{"e":"心服也。","n":"心部懾下一曰心服也。然則二字音義同。廣韵無㒤。"}]},"仢":{"expl":"約也。从人勺聲。","rad":"人","fq":"徒歴切","vol":"08","py":"dí","duan":[{"e":"約也。","n":"疊韵爲訓。釋天曰。奔星爲仢約。舊作彴約。佩觿辨證曰。字从人。不从彳。或云許本作仢約也。三字爲句。"}]},"儕":{"expl":"等輩也。从人齊聲。《春秋傳》曰：“吾儕小人。”","rad":"人","fq":"仕皆切","vol":"08","py":"chái","duan":[{"e":"等輩也。","n":"等、齊𥳑也。故凡齊皆曰等。樂記曰。先王之喜怒。皆得其儕焉。喜則天下和之。怒則暴亂者畏之。注。儕猶輩類。"}]},"倫":{"expl":"輩也。从人侖聲。一曰道也。","rad":"人","fq":"田屯切","vol":"08","py":"lún","duan":[{"e":"輩也。","n":"軍發車百兩爲輩。引伸之同類之次曰輩。鄭注曲禮、樂記曰。倫猶類也。注卽夕曰。比也。注中庸曰。猶比也。"}]},"侔":{"expl":"齊等也。从人牟聲。","rad":"人","fq":"莫浮切","vol":"08","py":"móu","duan":[{"e":"齊等也。","n":"輪人注曰。侔、上下等。又曰。侔、等也。弓人注曰。侔猶均也。又曰。侔猶等也。"}]},"偕":{"expl":"彊也。从人皆聲。《詩》曰：“偕偕士子。”一曰俱也。","rad":"人","fq":"古諧切","vol":"08","py":"xié","duan":[{"e":"彊也。","n":"小雅北山。偕偕士子。傳曰。偕偕、強壯皃。"}]},"俱":{"expl":"偕也。从人具聲。","rad":"人","fq":"舉朱切","vol":"08","py":"jū","duan":[{"e":"皆也。","n":"皆各本作偕。字之誤也。今正。白部曰。皆、俱䛐也。與此爲互訓。詩有假具爲俱者。如大叔于田火烈具舉是也。"}]},"儹":{"expl":"最也。从人贊聲。","rad":"人","fq":"作管切","vol":"08","py":"zǎn","duan":[{"e":"冣也","n":"冣才句切。各本誤作最。今正。廣韵曰。儹、聚也。冣、聚古通用。木部欑、竹部籫、義皆相近。李善引楊雄覈靈賦曰。文王之始起。浸仁漸義。會賢儹智。儹音攢。"}]},"併":{"expl":"並也。从人并聲。","rad":"人","fq":"卑正切","vol":"08","py":"bìnɡ","duan":[{"e":"竝也。","n":"十篇曰。竝者、倂也。與此爲互訓。並古音在十部。讀如旁。倂古音在十一部。讀如幷。竝倂義有別。許互訓者、禮經注曰古文並今文作倂。是古二字同也。"}]},"蔈":{"expl":"苕之黃華也。从艸𤐫聲。一曰末也。","rad":"艸","fq":"方小切","vol":"01","py":"biāo","duan":[{"e":"苕之黃華也。","n":"釋艸。苕、陵苕。黃華蔈。白華茇。郭云。苕華色異。名亦不同。玉裁按許君茇字下云。一曰艸之白華爲茇。不云苕之白華。則蔈字下亦當云艸之黃華。不當如郭說也。今本苕字恐是後人用郭說改之。許於苕下云艸也。亦不云陵苕。"}]},"傅":{"expl":"相也。从人尃聲。","rad":"人","fq":"方遇切","vol":"08","py":"fù","duan":[{"e":"相也。","n":"左傳。鄭伯傳王。注曰。傳、相也。賈子曰。傳、傳之德義。古假爲敷字。如禹敷土、亦作禹傳士是也。亦爲今之附近字。如凡言附箸是也。"}]},"侙":{"expl":"惕也。从人式聲。《春秋國語》曰：“於其心侙然。”","rad":"人","fq":"恥力切","vol":"08","py":"chì","duan":[{"e":"惕也。","n":"惕者、敬也。"}]},"俌":{"expl":"輔也。从人甫聲。讀若撫。","rad":"人","fq":"芳武切","vol":"08","py":"fǔ","duan":[{"e":"輔也。","n":"謂人之俌猶車之輔也。"}]},"倚":{"expl":"依也。从人奇聲。","rad":"人","fq":"於綺切","vol":"08","py":"yǐ","duan":[{"e":"依也。从人。奇聲。","n":"於綺切。古音在十七部。"}]},"依":{"expl":"倚也。从人衣聲。","rad":"人","fq":"於稀切","vol":"08","py":"yī","duan":[{"e":"倚也。从人。衣聲。","n":"於稀切。十五部。"}]},"仍":{"expl":"因也。从人乃聲。","rad":"人","fq":"如乘切","vol":"08","py":"rénɡ","duan":[{"e":"因也。","n":"釋詁曰。攘仍因也。大雅常武傳曰。仍、就也。就與因義一也。周禮故書仍爲乃。"}]},"佽":{"expl":"便利也。从人次聲。《詩》曰：“決拾旣佽。”一曰遞也。","rad":"人","fq":"七四切","vol":"08","py":"cì","duan":[{"e":"便利也。","n":"小雅車攻。決拾旣佽。傳曰。佽、利也。按百官公𨜮表。更名左弋爲佽飛。葢取便利之意。"}]},"佴":{"expl":"佽也。从人耳聲。","rad":"人","fq":"仍吏切","vol":"08","py":"èr","duan":[{"e":"佽也。","n":"此冡遞訓言。司馬遷傳曰。僕又佴之蠶室。如淳曰。佴、次也。若人相次也。一本佴作茸。蘇林云。茸、次也。若人相俾次。蘇以謂茸當作佴耳。佴之蠶室、猶云副貳之以蠶室也。小顏乃欲讀爲搑。云推致蠶室中。殊非文義。"}]},"倢":{"expl":"佽也。从人疌聲。","rad":"人","fq":"子葉切","vol":"08","py":"jié","duan":[{"e":"佽也。","n":"按上解冡遞訓。此解冡便利之訓。廣雅曰。倢、疾也。廣韵曰。倢、斜出也。便也。利也。玉篇曰。詩云征夫倢倢。倢倢、樂事也。本亦作捷。按倢伃、婦官也。亦作婕妤。葢言敏倢而又安舒與。"}]},"侍":{"expl":"承也。从人寺聲。","rad":"人","fq":"時吏切","vol":"08","py":"shì","duan":[{"e":"承也。","n":"承者、奉也。受也。凡言侍者皆敬恭承奉之義。"}]},"英":{"expl":"艸榮而不實者。一曰黃英。从艸央聲。","rad":"艸","fq":"於京切","vol":"01","py":"yīnɡ","duan":[{"e":"艸榮而不實者。","n":"見釋艸。"}]},"傾":{"expl":"仄也。从人从頃，頃亦聲。","rad":"人","fq":"去營切","vol":"08","py":"qīnɡ","duan":[{"e":"仄也。","n":"仄部曰。仄傾也。二字互訓。古多用頃爲之。又按仄當作夨。夨下曰。傾頭也。引申謂凡夨皆曰傾。夨與仄義小異。"}]},"側":{"expl":"㫄也。从人則聲。","rad":"人","fq":"阻力切","vol":"08","py":"cè","duan":[{"e":"旁也。","n":"不正曰仄。不中曰側。二義有別。而經傳多通用。如反側當爲反仄。仄者、未全反也。"}]},"侒":{"expl":"宴也。从人安聲。","rad":"人","fq":"烏寒切","vol":"08","py":"ān","duan":[{"e":"宴也。","n":"宀部曰。宴、安也。侒與安音義同。"}]},"侐":{"expl":"靜也。从人血聲。《詩》曰：“閟宮有侐。”","rad":"人","fq":"況逼切","vol":"08","py":"xù","duan":[{"e":"靜也。","n":"靜者、審也。悉也。知審諦也。魯頌曰。閟宮有侐。傳曰。侐、淸淨也。淨乃靜之字誤。周頌。假以溢我。傳曰。溢、愼也。許作誐以謐我。謐、靜語也。一曰無聲也。左傳作何以恤我。尙書。惟㓝之恤。伏生尙書作惟㓝之謐。史記作惟㓝之靜。爾雅。溢、愼、謐、靜也。溢者、恤之字誤。莊子書云。以言其老洫也。近死之心。莫使復陽也。老洫者、枯靜之意。莊子洫本亦作溢。周頌之恤、莊子之洫皆侐之假借。侐與謐古音同部。"}]},"付":{"expl":"與也。从寸持物對人。","rad":"人","fq":"方遇切","vol":"08","py":"fù","duan":[{"e":"予也。","n":"予者、推予也。尙書。天旣孚命正厥德。今文尙書作天旣付命正厥德。"}]},"俜":{"expl":"使也。从人甹聲。","rad":"人","fq":"普丁切","vol":"08","py":"pīnɡ","duan":[{"e":"俠也。","n":"丂部曰。甹、俠也。三輔謂輕財者爲甹。然則俜甹音義皆同。"}]},"俠":{"expl":"俜也。从人夾聲。","rad":"人","fq":"胡頰切","vol":"08","py":"xiá","duan":[{"e":"俜也。","n":"荀悅曰。立氣齊、作威福、結私交、以立彊於世者、謂之游俠。如淳曰。相與信爲任、同是非爲俠。所謂權行州里、力折公侯者也。或曰。任、氣力也。俠、甹也。按俠之言夾也。夾者、持也。經傳多假俠爲夾。凡夾皆用俠。"}]},"儃":{"expl":"儃何也。从人亶聲。","rad":"人","fq":"徒干切","vol":"08","py":"chán","duan":[{"e":"儃何也。","n":"未聞。假令訓爲儋何。則又不當析廁於此。或當作儃回。九章曰。欲儃佪以干傺。又曰。入漵浦余儃佪。王逸曰。儃佪猶低佪也。洪興祖曰。儃知然切。"}]},"侁":{"expl":"行皃。从人先聲。","rad":"人","fq":"所臻切","vol":"08","py":"shēn","duan":[{"e":"行皃。","n":"招䰟曰。豺狼從目。往來侁侁。王逸曰。侁侁、往來聲也。詩曰。侁侁征夫。"}]},"仰":{"expl":"舉也。从人从卬。","rad":"人","fq":"魚兩切","vol":"08","py":"yǎnɡ","duan":[{"e":"舉也。","n":"與卬音同義近。古卬仰多互用。"}]},"薾":{"expl":"華盛。从艸爾聲。《詩》曰：“彼薾惟何？”","rad":"艸","fq":"兒氏切","vol":"01","py":"ěr","duan":[{"e":"華盛。","n":"㸚部曰。麗爾猶靡麗也。薾與爾音義同。"}]},"侸":{"expl":"立也。从人豆聲。讀若樹。","rad":"人","fq":"常句切","vol":"08","py":"shù","duan":[{"e":"立也。","n":"十篇曰。立、侸也。與此爲互訓。今本立下改爲住也。則不可通矣。侸讀若樹。與尌豎音義同。不當作住。今俗用住字。乃駐逗二字之俗。非侸字之俗也。"}]},"儽":{"expl":"垂皃。从人纍聲。一曰嬾解。","rad":"人","fq":"落猥切","vol":"08","py":"lěi","duan":[{"e":"𠂹皃。","n":"老子曰。儽儽兮若無所歸。王弼、陸希聲本同。今按此㒍㒍之誤。河上公本作乗乗。㒍從積絫之絫。與乗義相近。樂記。纍纍乎端如貫珠。音義云。本又作累。卽絫字。㒍㒍爲垂皃。則與絫絫同也。"}]},"侳":{"expl":"安也。从人坐聲。","rad":"人","fq":"則臥切","vol":"08","py":"zuò","duan":[{"e":"安也。从人。坐聲。","n":"則臥切。十七部。"}]},"偁":{"expl":"揚也。从人爯聲。","rad":"人","fq":"處陵切","vol":"08","py":"chēnɡ","duan":[{"e":"揚也。","n":"揚者、飛舉也。釋言曰。偁、舉也。郭注引尙書。偁爾戈。玉篇引左傳。禹偁善人。凡古偁舉、偁謂字皆如些作。自序云。其偁易孟氏、書孔氏。子篆下云。人以爲偁。自稱行而偁廢矣。稱者、今之秤字。"}]},"伍":{"expl":"相參伍也。从人从五。","rad":"人","fq":"疑古切","vol":"08","py":"wǔ","duan":[{"e":"相參伍也。","n":"參、三也。伍、五也。周禮曰。五人爲伍。凡言參伍者、皆謂錯綜以求之。易繫辭曰。參伍以變。荀𨜮曰。窺敵制勝。欲伍以參。韓非曰。省同異之言。以知朋黨之分。偶參伍之驗。以責陳言之實。又曰。參之以比物。伍之以合參。史記曰。必參而伍之。漢書曰。參伍其價。以類相準。此皆引伸之義也。"}]},"什":{"expl":"相什保也。从人、十。","rad":"人","fq":"是執切","vol":"08","py":"shí","duan":[{"e":"相什𠈃也。","n":"族師職曰。五家爲比。十家爲聯。五人爲伍。十人爲聯。使之相𠈃相受。鄭云。𠈃猶任也。宮正注。五人爲伍。二伍爲什。雅頌以十篇爲一什。按後世曰什物、古曰任器。古今語也。任急言之曰什。如唐人詩十可讀如諶也。周禮牛人、司𥻳皆有任器。鄭云。任猶用也。"}]},"佰":{"expl":"相什伯也。从人、百。","rad":"人","fq":"博陌切","vol":"08","py":"bǎi","duan":[{"e":"相什佰也。","n":"佰汲古閣作伯。誤。佰連什言者、猶伍連參言也。佰之言百也。廣韵一百爲一佰。過秦論曰。俛起什佰之中。漢書音義云。首出十長、百長之中。此謂十人之長爲什。百人之長爲佰也。食貨志。無農夫之苦。有仟佰之得。師古云。仟、千錢也。佰、百錢也。佰莫白反。今俗猶謂百錢爲一佰。按仟字罕見。廣韵、集韵、類篇皆曰。千人之長曰仟。毛晁云出文字音義。食貨志語意謂兼十倍百倍之利耳。顏注非。仟疑本作什。顏不音千可證。"}]},"佸":{"expl":"會也。从人𠯑聲。《詩》曰：“曷其有𠈲？”一曰𠈲𠈲，力皃。","rad":"人","fq":"古活切","vol":"08","py":"huó","duan":[{"e":"會也。","n":"王風君子于役曰。曷其有佸。傳曰。佸、會也。此以疊韵爲訓。"}]},"佮":{"expl":"合也。从人合聲。","rad":"人","fq":"古沓切","vol":"08","py":"ɡé","duan":[{"e":"合也。从人。合聲。","n":"古沓切。七部。"}]},"𢼸":{"expl":"妙也。从人从攴，豈省聲。","rad":"人","fq":"無非切","vol":"08","py":"wéi","duan":[{"e":"眇也。","n":"眇各本作妙。今正。凡古言𢼸眇者、卽今之微妙字。眇者、小也。引伸爲凡細之偁。微者、隠行也。微行而𢼸廢矣。玉篇有𠌝字。引書虞舜側𠌝。亦𢼸之俗體也。"}]},"萋":{"expl":"艸盛。从艸妻聲。《詩》曰：“菶菶萋萋。”","rad":"艸","fq":"七稽切","vol":"01","py":"qī","duan":[{"e":"艸盛。从艸。妻聲。","n":"七稽切。十五部。"}]},"傆":{"expl":"黠也。从人原聲。","rad":"人","fq":"魚怨切","vol":"08","py":"yuàn","duan":[{"e":"黠也。","n":"黠史記所謂桀黠也。傆葢謂鄉原。"}]},"作":{"expl":"起也。从人从乍。","rad":"人","fq":"則洛切","vol":"08","py":"zuò","duan":[{"e":"起也。","n":"秦風無衣傳曰。作、起也。釋言、穀梁傳曰。作、爲也。魯頌駉傳曰。作、始也。周頌天作傳曰。作、生也。其義別而略同。別者所因之文不同。同者其字義一也。有一句中同字而別之者。如小雅作而作詩箋云。上作、起也。下作、爲也。辵部曰。迮迮、起也。然則作迮二篆音義同。古文假借乍爲作。"}]},"假":{"expl":"非眞也。从人叚聲。一曰至也。《虞書》曰：“假于上下。”","rad":"人","fq":"古疋切","vol":"08","py":"jiǎ","duan":[{"e":"非眞也。","n":"又部曰。假叚、借也。然則假與叚義略同。六憶六曰假借。謂本無其字。依聲託事也。"}]},"借":{"expl":"假也。从人昔聲。","rad":"人","fq":"資昔切","vol":"08","py":"jiè","duan":[{"e":"假也。从人。昔聲。","n":"資昔切。古音在五部。按小徐本無此字。張次立乃依大徐增之。故曰資昔切。而不曰資昔反也。大徐依音義序例偏㫄所有而補正文者十九字。借其一也。序曰。六書六曰假借。又部叚下曰。借也。此處當有借篆可知矣。爾雅音義。釋鳥唶唶下曰。說文云借字也。按云當作之。唶乃諎之或體。今許書諎下無叚諎之訓。豈通作借而遂𠜂之與。聞疑載疑。孰理而董之矣。古多用藉爲借。如言藉令卽假令也。"}]},"侵":{"expl":"漸進也。从人、又持帚，若埽之進。又，手也。","rad":"人","fq":"七林切","vol":"08","py":"qīn","duan":[{"e":"漸進也。","n":"漸當作𧽯。𧽯、進也。侵之言駸駸也。水部。浸淫、隨理也。浸淫亦作侵淫。又侵陵亦漸逼之意。左傳曰。無鐘𡔷曰侵。穀梁傳曰。苞人民、毆牛馬曰侵。公羊傳曰。觕者曰侵。精者曰伐。又穀梁傳曰。五穀不升謂之大侵。"}]},"儥":{"expl":"賣也。从人𧷏聲。","rad":"人","fq":"余六切","vol":"08","py":"yù","duan":[{"e":"見也。","n":"貝部𧷗下曰𧗳也。𧗳者、行且𧶠也。𧷗卽周禮之儥字。今之鬻字。儥訓見。卽今之覿字也。釋詁曰。覿、見也。公羊傳。穀梁傳、士昏禮、聘禮、論語鄭注、國語韋注皆同。按經傳今皆作覿。覿行而儥廢矣。許書無覿字。獨存古形古義於此也。以他字例之。葢禮經古文作儥。今文作覿。許從古文。不從今文歟。大徐本竊取周禮。改見爲𧶠。非是。周禮儥訓買。玉篇作儥、買也。今又作賣。則誤之中又有誤焉。"}]},"𠊱":{"expl":"伺望也。从人矦聲。","rad":"人","fq":"胡遘切","vol":"08","py":"hòu","duan":[{"e":"司望也。","n":"司各本作伺。非。今正。司者今之伺字也。曹風𠋫人傳云。𠋫人、道路送賓客者。周禮𠋫人注云。𠋫、𠋫迎賓客之來者。按凡覰伺皆曰𠋫。因之謂時爲𠋫。"}]},"償":{"expl":"還也。从人賞聲。","rad":"人","fq":"食章切","vol":"08","py":"chánɡ","duan":[{"e":"還也。","n":"廣雅曰。復也。左傳。西鄰責言。不可償也。杜云。不可報償。"}]},"僅":{"expl":"材能也。从人堇聲。","rad":"人","fq":"渠吝切","vol":"08","py":"jǐn","duan":[{"e":"材能也。","n":"材今俗用之纔字也。三蒼及漢書作纔。鄭注禮記周禮、賈逵注國語、東觀漢記及諸史並作裁。許書水部、雨部、叀部作財。此作材。材能言僅能也。公羊傅僖十六年曰。是月者何。僅逮是月也。何注。在月之幾盡、故曰劣及是月。定八年曰。公斂處父帥師而至。慬然後得免。慬葢僅之譌字。射義。葢㢙有存者。言存者甚少。㢙卽僅字。广部廑下曰。少劣之居也。與僅義略同。唐人文字僅多訓庶幾之幾。如杜詩。山城僅百層。韓文初守雎陽時。士卒僅萬人又家累僅三十口。桺文。自古賢人才士被謗議不能自明者。僅以百數。元微之文。封章諫草。緐委箱笥。僅逾百軸。此等皆李涪所謂以僅爲近遠者。於多見少。於僅之本義未隔也。今人文字皆訓僅爲但。"}]},"代":{"expl":"更也。从人弋聲。","rad":"人","fq":"徒耐切","vol":"08","py":"dài","duan":[{"e":"㪅也。","n":"㪅者、改也。士喪禮、喪大記注同。凡以此易彼謂之代。次第相易謂之遞代。凡以異語相易謂之代語。假代字爲世字。起於唐人避諱。世與代義不同也。唐諱言世。故有代宗。明旣有世宗。又有代宗。斯失之矣。"}]},"菶":{"expl":"艸盛。从艸奉聲。","rad":"艸","fq":"補蠓切","vol":"01","py":"běnɡ","duan":[{"e":"艸盛。","n":"毛曰。菶菶萋萋。梧桐盛也。"}]},"儀":{"expl":"度也。从人義聲。","rad":"人","fq":"魚羈切","vol":"08","py":"yí","duan":[{"e":"度也。","n":"度、法制也。毛傳曰。儀、善也。又曰。儀、宜也。又曰。儀、匹也。其義相引伸。肆師職曰。古書儀但爲義。今時所謂義、古書爲誼。按如文王傳曰義、善也。此與釋詁及我將傳儀、善也正同。謂此義爲儀之假借字也。"}]},"傍":{"expl":"近也。从人㫄聲。","rad":"人","fq":"步光切","vol":"08","py":"bànɡ","duan":[{"e":"近也。","n":"古多假並爲之。如史記始皇紀並河以東、武帝紀並海是也。亦假旁爲之。見溝洫志、食貨志。"}]},"佀":{"expl":"象也。从人㠯聲。","rad":"人","fq":"詳里切","vol":"08","py":"sì","duan":[{"e":"像也。","n":"各本作象也。小徐作象肖也。皆非。今正。像下曰佀也。與此互訓。是爲轉注。度古本二篆必相屬不知何時轉寫遠隔。又皆改其說解耳。相像曰相似。古今無異䛐。緣俗閒用象爲像。乃致𡚶改許書。廣雅曰。似、類也。又曰。似、像也。又曰。似、若也。皆似之本義也。詩斯干、裳裳者華、卷阿、江漢傳皆曰。似、嗣也。此謂似爲嗣之假借字也。斯干似續妣祖箋云。似讀爲巳午之巳。巳續妣祖者、謂巳成其宮廟也。此謂似爲巳之假借字也。"}]},"便":{"expl":"安也。人有不便，更之。从人、更。","rad":"人","fq":"房連切","vol":"08","py":"pián","duan":[{"e":"安也。","n":"古與平辨通用。如史記便章百姓。古文尙書作平。今文尙書作辨。毛詩平平左右。左傳作便蕃左右。"}]},"任":{"expl":"符也。从人壬聲。","rad":"人","fq":"如林切","vol":"08","py":"rén","duan":[{"e":"𠈃也。","n":"按上文云𠈃、養也。此云任、𠈃也。二篆不相屬者、𠈃之本義尙書所謂𠈃抱。任之訓𠈃則𠈃引伸之義。如今言𠈃舉是也。周禮。五家爲比。使之相𠈃。注云。𠈃猶任也。又孝友睦婣任恤。注云。任、信於友道也。引伸之凡儋何曰任。小雅。我任我輦。我車我牛。傳云。任者、輦者、車者、牛者。四云者者皆謂人也。邶風傳。任、大也。卽釋詁之壬、大也。"}]},"俔":{"expl":"譬諭也。一曰間見。从人从見。《詩》曰：“俔天之妺。”","rad":"人","fq":"苦甸切","vol":"08","py":"qiàn","duan":[{"e":"諭也。","n":"各本作譬諭。今依詩正義訂。言部曰。譬者、諭也。則言諭已足矣。大雅大明曰。俔天之妹。傳曰。俔、磬也。此以今語釋古語。俔者古語。磬者今語。二字雙聲。是以毛詩作俔。韓詩作磬。如十七篇之有古今文。孔穎達云。如今俗語譬喻云磬作然。許不依傳云磬而云諭者。磬非正字。以六書言之。乃俔之假借耳。不得以假借字釋正字也。磬罄古通用。爾雅。罄、盡也。猶言竟是天之妹也。"}]},"優":{"expl":"饒也。从人憂聲。一曰倡也。","rad":"人","fq":"於求切","vol":"08","py":"yōu","duan":[{"e":"饒也。","n":"食部饒下曰、飽也。引伸之凡有餘皆曰饒。詩瞻卬傳曰。優、渥也。箋云。寬也。周語注曰。優、饒也。魯語注曰。優、裕也。其義一也。引伸之爲優游、爲優柔、爲俳優。商頌。布政憂憂。小雅。旣瀀旣渥。今本皆假優爲之。"}]},"僖":{"expl":"樂也。从人喜聲。","rad":"人","fq":"許其切","vol":"08","py":"xī","duan":[{"e":"樂也。","n":"此字之本義少用。其𥻳變爲嬉。李注洞簫賦引說文。嬉、樂也。卽謂此也。謚法有釐、有僖。周書二謚並出。而春秋三傳僖公。史漢皆作釐公。殆史漢假釐爲僖乎。謚法曰。小心畏忌曰僖。"}]},"偆":{"expl":"富也。从人春聲。","rad":"人","fq":"尺允切","vol":"08","py":"chǔn","duan":[{"e":"富也。","n":"廣韵曰。厚也。富也。若白虎通曰。春之爲言偆。偆、動也。春秋繁露曰。偆偆者、喜樂之貌也。葢皆蠢之假借字。"}]},"俒":{"expl":"完也。《逸周書》曰：“朕實不明，以俒伯父。”从人从完。","rad":"人","fq":"胡困切","vol":"08","py":"hùn","duan":[{"e":"完也。","n":"以疊韵爲訓。"}]},"薿":{"expl":"茂也。从艸疑聲。《詩》曰：“黍稷薿薿。”","rad":"艸","fq":"魚己切","vol":"01","py":"nǐ","duan":[{"e":"茂也。从艸。疑聲。","n":"魚己切。一部。"}]},"儉":{"expl":"約也。从人僉聲。","rad":"人","fq":"巨險切","vol":"08","py":"jiǎn","duan":[{"e":"約也。","n":"約者、纏束也。儉者、不敢放侈之意。古假險爲儉。易。儉德辟難。或作險。"}]},"偭":{"expl":"鄉也。从人面聲。《少儀》曰：“尊壺者偭其鼻。”","rad":"人","fq":"彌箭切","vol":"08","py":"miǎn","duan":[{"e":"鄉也。","n":"鄉、今人所用之向字也。漢人無作向者。少儀。尊壼者面其鼻。注云。鼻在面中。言鄉人也。按許所據作偭。說與鄭同。偭訓鄉。亦訓背。此竆則變、變則通之理。如廢置、徂存、苦快之例。離騷、偭規矩而改錯。王逸曰。偭、背也。賈誼吊屈原曰。偭蟂獺以隱處。應劭曰。偭、背也。項羽傳。馬童面之。張晏曰。背之也。張敺傳。上具獄事不可卻者。爲涕泣面而封之。師古曰。謂偝之也。惠氏定宇左傳補注曰。面縛之。謂反背而縛之。𦒱工記。審曲面勢。先鄭釋以陰陽之面背。許言鄉不言背者、述其本義也。古通作面。"}]},"俗":{"expl":"習也。从人谷聲。","rad":"人","fq":"似足切","vol":"08","py":"sú","duan":[{"e":"習也。","n":"以雙聲爲訓。習者、數飛也。引伸之凡相效謂之習。周禮大宰。禮俗以馭其民。注云。禮俗、昏姻喪紀。舊所行也。大司徒以俗敎安。注。俗謂士地所生習也。曲禮。入國而問俗。注。俗謂常所行與所惡也。漢地理志曰。凡民函五常之性。其剛柔緩急。音聲不同。繫水土之風氣。故謂之風。好惡取舍。動靜無常。隨君上之情欲。謂之俗。"}]},"俾":{"expl":"益也。从人卑聲。一曰俾，門侍人。","rad":"人","fq":"并弭切","vol":"08","py":"bǐ","duan":[{"e":"益也。","n":"俾與埤朇裨音義皆同。今裨行而埤朇俾皆廢矣。經傳之俾皆訓使也。無異解。葢卽益義之引伸。釋詁。俾、從也。釋言。俾、職也。亦皆引伸之義。手部挾下曰。俾持。亦部㚒下曰。蔽人俾夾。古或假卑爲俾。"}]},"倪":{"expl":"俾也。从人兒聲。","rad":"人","fq":"五雞切","vol":"08","py":"ní","duan":[{"e":"俾也。","n":"然則倪亦訓益也。若孟子反其旄倪。借爲嫛婗之婗也。爾雅。左倪不類。右倪不若。左傳注。城上僻倪。借倪爲睨也。莊子。不知端倪。借端爲耑。借倪爲題也。題者、物初生之題也。"}]},"億":{"expl":"安也。从人𢡃聲。","rad":"人","fq":"於力切","vol":"08","py":"yì","duan":[{"e":"安也。","n":"晉語億寧百神注。億、安也。吳語億負晉衆庶注曰。億、安也。左傳曰不能供億。曰心億則樂。曰我葢姑億吾鬼神。而寧吾族姓。杜注皆曰。安也。此億字之本義也。今則本義廢矣。或假爲萬𢡃字。諸經所用皆是也。或假爲意字。如論語不億不信、億則屢中是也。億則屢中、漢書貨殖傳作意。毋意、毋必諸家偁作億必。是可證矣。"}]},"使":{"expl":"伶也。从人吏聲。","rad":"人","fq":"疏士切","vol":"08","py":"shǐ","duan":[{"e":"令也。","n":"大徐令作伶。誤。令者、發號也。釋詁。使、從也。其引伸之義也。按許書無駛𩢲字。左傳。吏走問諸朝。本作使起問諸朝。古注。使、速疾之意也。又鬯部𩰢、烈也。讀若迅。葢此二字卽今之駛𩢲字乎。水部沑、水吏也。吏同使。謂水疾。"}]},"𠊾":{"expl":"𠊾 ，左右兩視。从人癸聲。","rad":"人","fq":"其季切","vol":"08","py":"kuí","duan":[{"e":"𠊾、","n":"此複舉字之未𠜂僅存者。"}]},"伶":{"expl":"弄也。从人令聲。益州有建伶縣。","rad":"人","fq":"郎丁切","vol":"08","py":"línɡ","duan":[{"e":"弄也。","n":"徐鍇曰。伶人者、弄臣也。毛詩寺人之令。釋文曰。令韓詩作伶。云使伶。古伶人字本作泠。泠人、樂官也。"}]},"儷":{"expl":"棽儷也。从人麗聲。","rad":"人","fq":"呂支切","vol":"08","py":"lí","duan":[{"e":"棽儷也。","n":"林部棽下曰。木枝條棽儷也。義已見彼。故此但云棽儷也。與同部偓下云偓佺、仙人也。佺下但云偓佺也例同。按左傳伉儷。杜云。儷、偶也。士冠禮、聘禮儷皮。鄭云。儷猶㒳也。古文儷爲離。月令。宿離不貣。鄭云。離讀爲儷偶之儷。許但取枝條棽儷之訓。不及其他。於从人之意未合。於全書大例未符。恐非許書之舊。"}]},"蕤":{"expl":"艸木華垂皃。从艸甤聲。","rad":"艸","fq":"儒隹切","vol":"01","py":"ruí","duan":[{"e":"艸木華𠂹皃。","n":"引伸凡物之垂者皆曰蕤冠緌系於纓而垂者也。禮家定爲蕤字。夏采建綏。王制大綏小綏。明堂位夏后氏之綏。襍記以其綏復。鄭君皆改爲緌字。謂旄牛尾之垂於杠者也。讀如冠蕤、蕤賔之蕤。白虎通說蕤賔曰。蕤者、下也。賔者、敬也。"}]},"傳":{"expl":"遽也。从人專聲。","rad":"人","fq":"直戀切","vol":"08","py":"zhuàn","duan":[{"e":"遽也。","n":"辵部曰。遽、傳也。與此爲互訓。此二篆之本義也。周禮行夫。掌邦國傳遽。注云。傳遽、若今時乗傳騎驛而使者也。玉藻。士曰傳遽之臣。注云。傳遽、以車馬給使者也。左傳、國語皆曰。以傳召伯宗。注皆云。傳、驛也。漢有置傳、馳傳、乗傳之不同。按傳者如今之驛馬。驛必有舍。故曰傳舍。又文書亦謂之傳。司關注云。傳如今移過所文書是也。引伸傳遽之義。則凡展轉引伸之偁皆曰傅。而傳注、流傳皆是也。後儒分別爲知戀、直戀、直攣三切。實一語之轉。"}]},"倌":{"expl":"小臣也。从人从官。《詩》曰：“命彼倌人。”","rad":"人","fq":"古患切","vol":"08","py":"ɡuān","duan":[{"e":"小臣也。","n":"庸風定之方中曰。命彼倌人。傳曰。倌人、主駕者。按許說異毛。小臣葢謂周禮小臣上士四人。大僕之佐也。一云左傳所謂巾車脂舝也。"}]},"价":{"expl":"善也。从人介聲。《詩》曰：“价人惟藩。”","rad":"人","fq":"古拜切","vol":"08","py":"jiè","duan":[{"e":"善也。","n":"大雅板曰。价人維藩。釋詁及傳曰。价、善也。箋云。价、甲也。被甲之人、謂卿士掌軍事者。葢鄭易價爲介也。詩正義引爾雅作价。今爾雅作介善也。葢非善本。"}]},"仔":{"expl":"克也。从人子聲。","rad":"人","fq":"子之切","vol":"08","py":"zī","duan":[{"e":"克也。","n":"周頌曰。佛時仔肩。克也。箋云。仔肩、任也。按克、勝也。勝與任義似異而同。許云仔、克也。釋詁云肩、克也。許云克、肩也。然則仔肩絫言之耳。"}]},"㑞":{"expl":"送也。从人灷聲。呂不韋曰：有侁氏以伊尹𠈖女。古文以爲訓字。","rad":"人","fq":"以證切","vol":"08","py":"yìnɡ","duan":[{"e":"送也。","n":"𠈪今之媵字。釋言曰。媵、將、送也。周易。媵口說也。虞曰。媵、送也。燕禮。大射。媵觚于賓。鄭注。媵、送也。九歌曰。魚隣隣兮。媵予。王注。媵、送也。送爲媵之本義。以姪娣送女乃其一耑耳。公羊傳曰。媵者何。諸侯娶一國。則二國往媵之。以姪娣從。是也。今義則一耑行而全者廢矣。"}]},"俆":{"expl":"緩也。从人余聲。","rad":"人","fq":"似魚切","vol":"08","py":"xú","duan":[{"e":"緩也。","n":"與徐義略同。齊世家。田常執𥳑公於俆州。索隱曰。徐廣音舒。其字从人。左氏作舒。說文作䣄。按魯世家作徐。"}]},"偋":{"expl":"僻寠也。从人屏聲。","rad":"人","fq":"防正切","vol":"08","py":"bìnɡ","duan":[{"e":"僻寠也。","n":"寠者、無禮之居也。廣韵曰。偋、隱僻也。無人處。引字統云。廁也。按偋與屛庰義略同。"}]},"伸":{"expl":"屈伸。从人申聲。","rad":"人","fq":"失人切","vol":"08","py":"shēn","duan":[{"e":"屈伸。","n":"屈者、無尾也。伸之反也。屈伸、謠、俗共知之語。故以爲訓。屈亦作詘。所謂隨體詰詘也。伸、古經傳皆作信。周易。詘信相感而利生焉。又尺蠖之詘。以求信也。又引而信之。韋昭漢書音義云。信古伸字。謂古文假借字。許書冣目曰。近而申之。以究萬原。古文申作信。又蟲部。尺蠖、屈𦥔蟲也。太平御覽引作曲信蟲。"}]},"伹":{"expl":"拙也。从人且聲。","rad":"人","fq":"似魚切","vol":"08","py":"qū","duan":[{"e":"拙也。","n":"廣韵作拙人。當是說文古本。拙者、不巧也。廣雅曰。伹、鈍也。玉篇引之。集韵、類篇皆引之。云千余切。今廣雅乃譌爲但度滿切矣。按此字千余切。與粗同紐。卽今粗笨字也。廣韵衹有七余一切。玉篇七閭祥閭二切。"}]},"㒄":{"expl":"意膬也。从人然聲。","rad":"人","fq":"人善切","vol":"08","py":"rǎn","duan":[{"e":"意膬也。","n":"意者、志也。膬者、耎易破也。意膬謂有此意而不堅。玉篇云。意急而懼。葢說說文之語也。或曰。當作膬意。○通俗文曰。痛聲曰痏。警聲曰㒄。㒄于𥳑切。"}]},"葼":{"expl":"青齊沇冀謂木細枝曰葼。从艸㚇聲。","rad":"艸","fq":"子紅切","vol":"01","py":"zōnɡ","duan":[{"e":"靑齊兗冀謂木細枝曰葼。","n":"見方言。引傳曰。慈母之怒子也。雖折葼笞之。其惠存焉。"}]},"偄":{"expl":"弱也。从人从耎。","rad":"人","fq":"奴亂切","vol":"08","py":"ruǎn","duan":[{"e":"弱也。","n":"此與懦儒二字義略同而音形異。懦儒皆需聲。偄、耎聲也。二聲轉寫多淆。所當覈正矣。偄从人亦或从心。左傳、穀梁傳皆曰。宮之奇之爲人也偄。注皆云。弱也。左傳音義曰。偄本又作耎。乃亂反。又乃貨反。弱也。字林。愞音乃亂反。懦音讓夫反。云弱也。按左傳此音義今本譌甚。𦒱正之如此。古者耎聲本在元寒部。而入歌戈部。需聲本在侯部。而人虞部。分別劃然。古假耎爲偄。𦒱工記。馬不契耎。鄭云。耎讀爲畏偄之偄。自唐初耎已譌需。"}]},"倍":{"expl":"反也。从人咅聲。","rad":"人","fq":"薄亥切","vol":"08","py":"bèi","duan":[{"e":"反也。","n":"此倍之本義。中庸。爲下不倍。緇衣信以結之。則民不倍。論語。斯遠鄙倍。皆是也。引伸之爲倍文之倍。大司樂注曰。倍文曰諷。不面其文而讀之也。又引伸之爲加倍之倍。以反者覆也。覆之則有二面。故二之曰倍。俗人䤨析。乃謂此專爲加倍字。而倍上、倍文則皆用背。餘義行而本義廢矣。倍之或體作偝。見坊記、投壼、荀𨜮子。"}]},"傿":{"expl":"引爲賈也。从人焉聲。","rad":"人","fq":"於建切","vol":"08","py":"yàn","duan":[{"e":"引爲賈也。","n":"引猶張大之。賈者今之價字。引爲價、所謂豫價也。後漢書。崔烈入錢五百萬。得爲司徒。及拜。靈帝顧謂親倖曰。悔不小傿。可至千萬。"}]},"僭":{"expl":"假也。从人朁聲。","rad":"人","fq":"子念切","vol":"08","py":"jiàn","duan":[{"e":"儗也。","n":"各本作假也。今依玉篇所引正。廣韵亦云擬也。以僭似二篆相聯互訓。知作假之非矣。以下儗上。僭之本義也。引伸之則訓差。大雅不僭不賊傳是也。又訓不信。小雅覆謂我僭箋是也。其小雅巧言傳曰。僭、𢿙也。則謂僭卽譖之假借也。詩亦假譖爲僭。如大雅桑柔瞻卬箋是也。"}]},"儗":{"expl":"僭也。一曰相疑。从人从疑。","rad":"人","fq":"魚已切","vol":"08","py":"nǐ","duan":[{"e":"僭也。","n":"以下僭上。此儗之本義。如史記說卓王孫田池射獵之樂儗於人君是也。與手部擬訓度不同。曲禮。儗人必於其倫。注。儗猶比也。此引伸之義也。漢書食貨志假疑爲儗。又假儗爲黍稷薿薿。"}]},"偏":{"expl":"頗也。从人扁聲。","rad":"人","fq":"芳連切","vol":"08","py":"piān","duan":[{"e":"頗也。","n":"頗、頭偏也。引伸爲凡偏之偁。故以頗釋偏。二字雙聲。尙書。無偏無頗。絫言之也。周易翩翩。古文作偏偏。"}]},"倀":{"expl":"狂也。从人長聲。一曰什也。","rad":"人","fq":"楮羊切","vol":"08","py":"chānɡ","duan":[{"e":"𤝵也。","n":"𤝵者、狾犬也。假借爲人狂之偁。仲尼燕居曰。譬猶瞽之無相。倀倀乎其何之。廣韵四十三映曰。朚倀、失道皃。"}]},"𠐿":{"expl":"惽也。从人薨聲。","rad":"人","fq":"呼肱切","vol":"08","py":"hōnɡ","duan":[{"e":"惛也。","n":"惛者、不憭也。釋訓曰。儚儚、洄洄、惛也。儚當作𠐿與夢夢、亂也義別。"}]},"儔":{"expl":"翳也。从人壽聲。","rad":"人","fq":"直由切","vol":"08","py":"dào","duan":[{"e":"翳也。","n":"翳者、華葢也。引伸爲凡覆蔽之偁。按玉篇儔直流切。侣也。又大到切。翳、隠蔽也。廣韵尤韵。儔侣也。直由切。号韵。儔、隠也。徒到切。是儔有隠蔽之訓。而其音與疇侣絶不同。與翿𦇨音同。由其義相近也。翳義廢而侣義獨行矣。然自唐以前用儔侣皆作疇。絶無作儔者。葢由古者一井爲疇。並畔爲疇。是以釋詁曰。疇、誰也。注易注國策漢書者曰。疇、類也。注國語者曰。疇、匹也。下逮六朝辭賦皆不作儔。玄應之書曰。王逸云二人爲匹。四人爲疇。疇亦類也。今或作儔矣。然則用儔者起唐初。以至於今。"}]},"侜":{"expl":"有廱蔽也。从人舟聲。《詩》曰：“誰侜予美？”","rad":"人","fq":"張流切","vol":"08","py":"zhōu","duan":[{"e":"有廱蔽也。","n":"廱今之壅字。陳風防有鵲巢曰。誰侜予美。爾雅及傳曰。侜張、誑也。誑亦壅蔽之意耳。許不用毛傳者、許以侜張乃尙書譸張之假借字。非侜之本義。故易之。"}]},"禱":{"expl":"告事求福也。从示壽聲。","rad":"示","fq":"都浩切","vol":"01","py":"dǎo","duan":[{"e":"吿事求福也。","n":"禱吿求三字曡韵。"}]},"䔟":{"expl":"艸萎䔟。从艸移聲。","rad":"艸","fq":"弋支切","vol":"01","py":"yí","duan":[{"e":"艸萎䔟。","n":"萎䔟曡韵。萎平聲。"}]},"俴":{"expl":"淺也。从人戔聲。","rad":"人","fq":"慈衍切","vol":"08","py":"jiàn","duan":[{"e":"淺也。","n":"秦風。小戎俴收。釋言、毛傳皆曰。俴、淺也。"}]},"佃":{"expl":"中也。从人田聲。《春秋傳》曰：“乘中佃。”一轅車。","rad":"人","fq":"堂練切","vol":"08","py":"diàn","duan":[{"e":"中也。","n":"廣韵曰。營田。玉篇曰。作田。今義非古義也。許攴部自有畋字。不必用佃爲之。許所說者、相傳古義。"}]},"𠈈":{"expl":"小皃。从人囟聲。《詩》曰：“𠈈𠈈彼有屋。”","rad":"人","fq":"斯氏切","vol":"08","py":"cǐ","duan":[{"e":"小皃。","n":"小雅正月曰。佌佌彼有屋。傳曰。佌佌、小也。許所據作{亻+𦥓}。或作𢇌。"}]},"侊":{"expl":"小皃。从人光聲。《春秋國語》曰：“侊飯不及一食。”","rad":"人","fq":"古橫切","vol":"08","py":"ɡuānɡ","duan":[{"e":"小兒｛皃｝。","n":"小當作大。字之誤也。凡光聲之字多訓光大。無訓小者。越語。句踐曰。諺有之曰。觥飯不及壼飱。韋云。觥、大也。大飯謂盛饌。盛饌未具。不能以虛待之。不及壼飱之救飢疾也。言己欲滅吳。取快意得之而已。不能待有餘力。韓詩云。觥、廓也。許所據國語作侊侊。與觥音義同。廣韵十一唐曰。侊、盛皃。用韋注十二庚曰。侊、小皃。用說文。葢說文之譌久矣。"}]},"佻":{"expl":"愉也。从人兆聲。《詩》曰：“視民不佻。”","rad":"人","fq":"土彫切","vol":"08","py":"tiāo","duan":[{"e":"愉也。","n":"古本皆作愉。汲古閣作偷。誤也。心部曰。愉、薄也。小雅鹿鳴曰。視民不恌。許所據作佻。是。毛傳曰。恌、愉也。按釋言。佻、偷也。偷者愉之俗字。今人曰偷薄、曰偷盜皆从人作偷。他侯切。而愉字訓爲愉悅。羊朱切。此今義今音今形。非古義古音古形也。古無从人之偷。愉訓薄。音他矦切。愉愉者、和氣之薄發於色也。盜者、澆薄之至也。偷盜字古只作愉也。凡古字之末流䤨析。類如是矣。周禮曰。以俗敎安。則民不愉。注曰。愉謂朝不謀夕。服注左傳禮民不佻云。示民不愉薄。唐風。他人是愉。傳曰。愉、樂也。箋云。愉讀曰偷。猶取也。此同字而各舉一義釋之。愉讀曰偷。如注周禮主以利得民云讀如上思利民之利耳。然可見漢未已有从人之偷。許不之取。"}]},"僻":{"expl":"避也。从人辟聲。《詩》曰：“宛如左僻。”一曰从㫄牽也。","rad":"人","fq":"普擊切","vol":"08","py":"pì","duan":[{"e":"辟也。","n":"辟大徐本作避。非是。辟者、法也。引伸爲辟人之辟。辟人而人避之亦曰辟。若周禮閽人。凡外內命婦出入。則爲之辟。孟子。行辟人可也。曲禮。若主人拜。則客還辟辟拜。郊特牲。有由辟焉。包咸論語注。躩盤辟皃也。投壼。主人盤旋曰辟。賓盤旋曰辟。大射儀。賓辟。注曰。辟、逡遁不敢當盛。他書辟人、辟邪、辟寒、辟塵之類。語意大略相似。自屛之者言。則閽、人離𡝤篇、郊特牲是也。自退者言。則曲禮、投壼、論語注所云是也。舟部般、辟也。卽旋辟、盤辟之謂。辟之言邊也。屛於一邊也。僻之本義如是。廣韵曰。誤也。邪僻也。此引伸之義。今義行而古義廢矣。詩曰。民之多僻。"}]},"伭":{"expl":"很也。从人，弦省聲。","rad":"人","fq":"胡田切","vol":"08","py":"xián","duan":[{"e":"很也。","n":"心部曰𢛆、急也。義略同。"}]},"伎":{"expl":"與也。从人支聲。《詩》曰：“𥷤人伎忒。”","rad":"人","fq":"渠綺切","vol":"08","py":"jì","duan":[{"e":"與也。","n":"舁部曰。與者、黨與也。此伎之本義也。廣韵曰。侣也。不違本義。俗用爲技巧之技。○小弁。鹿斯之奔。維足伎伎。傳云。伎伎、舒皃。按此伎伎葢與徥徥音義皆同。"}]},"侈":{"expl":"掩脅也。从人多聲。一曰奢也。","rad":"人","fq":"尺氏切","vol":"08","py":"chǐ","duan":[{"e":"掩脅也。","n":"掩者、掩葢其上。脅者、脅制其旁。凡自多以陵人曰侈。此侈之本義也。吳語。㚒溝而㢋我。其字則㢋也。其義則掩脅也。"}]},"佁":{"expl":"癡皃。从人台聲。讀若騃。","rad":"人","fq":"夷在切","vol":"08","py":"ǎi","duan":[{"e":"癡皃。","n":"大人賦。沛艾赳螑仡以佁儗兮。張揖曰。佁儗、不前也。此癡意也。吕氏春秋。出輿入輦。命曰佁蹷之機。高誘曰。佁、至也。此別一義也。"}]},"蒝":{"expl":"艸木形。从艸原聲。","rad":"艸","fq":"愚袁切","vol":"01","py":"yuán","duan":[{"e":"艸木形。从艸原聲。","n":"愚袁切。十四部。"}]},"𠋺":{"expl":"𠋺，驕也。从人蚤聲。","rad":"人","fq":"鮮遭切","vol":"08","py":"sāo","duan":[{"e":"𠋺、","n":"此複舉字之未𠜂者。"}]},"僞":{"expl":"詐也。从人爲聲。","rad":"人","fq":"危睡切","vol":"08","py":"wěi","duan":[{"e":"詐也。","n":"詐者、欺也。釋詁曰。詐、僞也。按經傳多假爲爲僞。如詩。人之爲言。卽僞言。月令。作爲淫巧。今月令云詐僞淫巧。古文尙書南僞。史記作南爲。左傳爲讀僞者不一。葢字涉於作爲則曰僞。徐鍇曰。僞者、人爲之。非天眞也。故人爲爲僞是也。荀𨜮曰。桀紂、性也。堯舜、僞也。人之性惡。其善者僞也。不可學、不可事而在人者謂之性。可學而能可事而成之在人者謂之僞。又曰。生之所以然者謂之性。心慮而能爲之動謂之僞。慮積焉、能習焉而後成謂之僞。荀𨜮之意謂堯舜不能無待於人爲耳。玉裁昔爲謝侍郎墉作荀𨜮補注。曾言之。"}]},"伿":{"expl":"隋也。从人只聲。","rad":"人","fq":"以豉切","vol":"08","py":"yì","duan":[{"e":"惰也。","n":"惰者、不敬也。醫經解㑊之{㑊當作此字。"}]},"佝":{"expl":"務也。从人句聲。","rad":"人","fq":"苦候切","vol":"08","py":"kòu","duan":[{"e":"佝瞀也。","n":"各本作務也二字。小徐作覆也。皆誤。今正。佝瞀也三字爲句。佝音寇。瞀音茂。疊韵字。二字多有或體。子部㝅下作㝅瞀。荀𨜮儒效作溝瞀。漢五行志作區霿。又作傋霿。楚辭九辨作怐愗。玉篇引作佝愗。應劭注漢書作瞉霿。郭景純注山海經作穀瞀。其音同。其義皆謂愚蒙也。山海經注穀字葢有誤。"}]},"僄":{"expl":"輕也。从人㶾聲。","rad":"人","fq":"匹妙切","vol":"08","py":"piào","duan":[{"e":"輕也。","n":"方言曰𠆩、僄、輕也。楚凡相輕薄或謂之𠆩或謂之僄也。班固賦曰。雖輕迅與僄狡。按古或假剽爲之。僄亦作嫖。霍嫖姚是也。"}]},"倡":{"expl":"樂也。从人昌聲。","rad":"人","fq":"尺亮切","vol":"08","py":"chānɡ","duan":[{"e":"樂也。","n":"漢有黃門名倡、常從倡、秦倡。皆鄭聲也。東方朔傳。有幸倡郭舍人。則倡卽俳也。經傳皆用爲唱字。周禮樂師。凡軍大獻。敎愷歌遂倡之。故書倡爲昌。鄭司農云。樂師、主倡也。昌當爲倡。按當云昌當爲唱。"}]},"俳":{"expl":"戲也。从人非聲。","rad":"人","fq":"步皆切","vol":"08","py":"pái","duan":[{"e":"戲也。","n":"以其戲言之謂之俳。以其音樂言之謂之倡。亦謂之優。其實一物也。"}]},"僐":{"expl":"作姿也。从人善聲。","rad":"人","fq":"堂演切","vol":"08","py":"shàn","duan":[{"e":"作姿也。","n":"廣雅曰。僐、態也。"}]},"儳":{"expl":"儳互，不齊也。从人毚聲。","rad":"人","fq":"士咸切","vol":"08","py":"chán","duan":[{"e":"儳互、","n":"逗。"}]},"佚":{"expl":"佚民也。从人失聲。一曰佚，忽也。","rad":"人","fq":"夷質切","vol":"08","py":"yì","duan":[{"e":"佚民也。","n":"三字句。論語微子篇。逸民。伯夷、叔齊、虞仲、夷逸、朱張、桺下惠、少連。按許作佚民。正字也。作逸民者假借字。佚从人。故爲佚民字也。孟子曰。遺佚而不怨。又以爲勞逸字。如以佚道使民是也。古失佚逸泆字多通用。石經今文尙書毋逸字作劮。則許所不取。廣雅錄之。"}]},"荚":{"expl":"艸實。从艸夾聲。","rad":"艸","fq":"古叶切","vol":"01","py":"jiá","duan":[{"e":"艸實。","n":"周禮曰。墳衍植物宜莢物。按莢物兼艸木言。"}]},"俄":{"expl":"行頃也。从人我聲。《詩》曰：“仄弁之俄。”","rad":"人","fq":"五何切","vol":"08","py":"é","duan":[{"e":"頃也。","n":"各本作行頃。乃妄加行耳。今正。玉篇曰。俄頃、須臾也。廣韵曰。俄頃、速也。此今義也。尋今義之所由。以俄頃皆偏側之意。小有偏側。爲時幾何。故因謂倏忽爲俄頃。許說其本義。以晐今義。凡讀許書當心知其意矣。匕部曰。頃、頭不正也。小雅賓之初筵箋云。俄、傾皃。廣雅。俄、衺也。皆本義也。若公羊傳曰。俄而可以爲其有矣。何云。俄者、謂須臾之閒。制得之頃也。此今義也。有假蛾爲俄者。如漢書。始爲少使。蛾而大幸。如淳曰。蛾、無幾之頃也。單言之或曰俄、或曰頃。絫言之曰俄頃。"}]},"㑾":{"expl":"喜也。从人䚻聲。自關以西，物大小不同謂之㑾。","rad":"人","fq":"余招切","vol":"08","py":"yáo","duan":[{"e":"喜也。","n":"喜下曰。樂也。王風。君子陶陶。傳曰。陶陶、和樂皃也。陶陶卽㑾㑾之假借也。凡言遙遙、𣣳𣣳皆疊字。則和可作㑾㑾矣。釋詁曰。繇、喜也。繇亦卽㑾。郭注以檀弓咏斯猶釋繇。殊誤。鄭云。猶當爲搖。謂身動搖也。"}]},"𠊬":{"expl":"徼𠊬受屈也。从人卻聲。","rad":"人","fq":"其虐切","vol":"08","py":"jué","duan":[{"e":"徼𠊬受屈也。","n":"子虛賦曰。徼谻受詘。郭璞曰。谻、疲極也。司馬彪云。徼、遮也。谻、倦也。謂遮其倦者。按長𨜮用假借字作谻。許用正字作𠊬。蘇林注漢曰。谻音倦谻之谻。當作音倦𠊬之𠊬也。方言曰。𠊬、𠉮也。𠍠同𠊬。𠉮同倦。心部𢜭者、勞也。與𠊬音義同。史記匈奴傳、漢書趙充國傳皆云徼極。與徼𠊬音異義同。"}]},"傞":{"expl":"醉舞皃。从人差聲。《詩》曰：“屢舞傞傞。”","rad":"人","fq":"素何切","vol":"08","py":"suō","duan":[{"e":"醉舞皃。","n":"小雅賓之初筵曰。𡝤舞傞傞。傳曰。傞傞、不止也。"}]},"僛":{"expl":"醉舞皃。从人欺聲。《詩》曰：“屢舞僛僛。”","rad":"人","fq":"去其切","vol":"08","py":"qī","duan":[{"e":"醉舞皃。","n":"賓之初筵曰。𡝤舞僛僛。傳曰。僛僛、舞不能自止也。"}]},"侮":{"expl":"傷也。从人𣫭聲。","rad":"人","fq":"文甫切","vol":"08","py":"wǔ","duan":[{"e":"㑥也。","n":"㑥各本作傷。誤。今正。鍇曰。㑥、慢易字也。鍇作注時未誤也。小雅常棣假務爲侮。"}]},"㑵":{"expl":"妎也。从人疾聲。一曰毒也。","rad":"人","fq":"秦悉切","vol":"08","py":"jí","duan":[{"e":"妎也。","n":"妎者、妬也。離騷注。害賢曰嫉。害色曰妬。如曰女無美惡。入宮見妬。士無賢不肖。入朝見嫉是也。渾言則不別。古亦假疾。"}]},"㑥":{"expl":"輕也。从人易聲。一曰交㑥。","rad":"人","fq":"以豉切","vol":"08","py":"yì","duan":[{"e":"輕也。","n":"此依小徐。侮㑥相屬。蒼頡篇曰。㑥、慢也。廣韵曰。㑥、相輕慢也。自易專行而㑥廢矣。禮記。易慢之心入之矣。注。易、輕易也。國語。貴貨而易土。注。易、輕也。國策注、呂覽注、漢書注皆同。凡皆㑥之假借字也。"}]},"俙":{"expl":"訟面相是。从人希聲。","rad":"人","fq":"喜皆切","vol":"08","py":"xī","duan":[{"e":"訟面相是也。","n":"謂內爭而外順也。皋陶謨所謂面從。今俗閒俚語猶有之。篇、韵皆注云訟也。失之遠矣。"}]},"僨":{"expl":"僵也。从人賁聲。","rad":"人","fq":"匹問切","vol":"08","py":"fèn","duan":[{"e":"僵也。","n":"引伸之爲凡倒敗之偁。大學曰。一人僨事。注云。僨猶覆敗也。射義假賁爲僨。左傳。象有齒以焚其身。假焚爲僨。"}]},"𦬆":{"expl":"艸耑。从艸亾聲。","rad":"艸","fq":"武方切","vol":"01","py":"mánɡ","duan":[{"e":"艸耑也。","n":"說文無？字。此卽鋒？字也。"}]},"僵":{"expl":"僨也。从人畺聲。","rad":"人","fq":"居良切","vol":"08","py":"jiānɡ","duan":[{"e":"偃也。","n":"小徐及爾雅釋文皆作偃。大徐作僨。非是。玄應引僵、却偃也。仆、前覆也。按僵謂仰倒。如莊子推而僵之、漢書觸寶瑟僵皆是。今人語言乃謂不動不㱙爲僵。廣韵作殭、死不㱙也。"}]},"仆":{"expl":"頓也。从人卜聲。","rad":"人","fq":"芳遇切","vol":"08","py":"pū","duan":[{"e":"頓也。","n":"頓者、下首也。以首叩地謂之頓首。引伸爲前覆之辭。左氏音義引孫炎曰。前覆曰仆。玄應三引說文。仆、頓也。謂前覆也。偃謂却偃。仆謂前覆。葢演說文者語。若論語注云。偃、仆也。則渾言不別矣。"}]},"偃":{"expl":"僵也。从人匽聲。","rad":"人","fq":"於幰切","vol":"08","py":"yǎn","duan":[{"e":"僵也。","n":"小雅。或棲遟偃仰。論語。寢不尸。苞注曰。不偃臥布展手足似死人。左傳。偃且射子鉏。晉語。籧篨不可使俛。韋注。籧篨、偃人。參同契曰。男生而伏。女偃其軀。及其死也。乃復效之。水經注曰。徐偃王生而偃。故以爲號。凡仰仆曰偃。引伸爲凡仰之偁。"}]},"傷":{"expl":"創也。从人，𥏻省聲。","rad":"人","fq":"少羊切","vol":"08","py":"shānɡ","duan":[{"e":"創也。","n":"刃部曰。刅、傷也。二字爲轉注。山海經謂木朿爲傷。"}]},"倄":{"expl":"剌也。从人肴聲。一曰痛聲。","rad":"人","fq":"胡茅切","vol":"08","py":"yáo","duan":[{"e":"剌也。","n":"剌者、戾也。盧𨔶切。"}]},"侉":{"expl":"𢞎詞。从人夸聲。","rad":"人","fq":"苦瓜切","vol":"08","py":"kuā","duan":[{"e":"𢟡詞也。","n":"古本皆作𢟡。惟類篇誤作僃耳。心部曰。𢟡者、𢢞也。𢢞者、𢟡也。𢟡今𥻳作𢣍。䛐者、意內而言外也。按爾雅、毛傳皆曰。夸毗、體多柔。然則侉卽夸毗字乎。夸毗亦作䠸𨈚。"}]},"催":{"expl":"相儔也。从人崔聲。《詩》曰：“室人交徧催我。”","rad":"人","fq":"倉回切","vol":"08","py":"cuī","duan":[{"e":"相擣也。","n":"猶相迫也。邶風北門曰。室人交徧摧我。傳曰。摧、沮也。音義曰。摧或作催。據許則催是也。不從傳者、傳取沮壞之義。與摧訓擠、訓折義同。葢當時字作催。而毛釋爲摧之假借。許則釋其本義也。"}]},"俑":{"expl":"痛也。从人甬聲。","rad":"人","fq":"他紅切","vol":"08","py":"yǒnɡ","duan":[{"e":"痛也。","n":"此與心部恫音義同。禮記孟子之俑、偶人也。俑卽偶之假借字。如喁亦禺聲而讀魚容切也。假借之義行而本義廢矣。廣韵引埤蒼說。木人送葬。設關而能跳踊。故名之俑。乃不知音理者強爲之說耳。"}]},"伏":{"expl":"司也。从人从犬。","rad":"人","fq":"房六切","vol":"08","py":"fú","duan":[{"e":"司也。","n":"司者、臣司事於外者也。司今之伺字。凡有所司者必專守之。伏伺卽服事也。引伸之爲俯伏。又引伸之爲隱伏。"}]},"促":{"expl":"迫也。从人足聲。","rad":"人","fq":"七玉切","vol":"08","py":"cù","duan":[{"e":"迫也。","n":"與𧼈音義皆略同。"}]},"䔺":{"expl":"藍蓼秀。从艸，隨省聲。","rad":"艸","fq":"羊捶切","vol":"01","py":"wéi","duan":[{"e":"藍蓼秀。从艸。隋聲。","n":"羊捶切。古音在十七部。按䔺與芛字皆切羊捶。葢卽芛字之異者。且當與芣葩芛蘳蔈英薾七字類列。此非其次、疑後人所沾也。"}]},"例":{"expl":"比也。从人𠛱聲。","rad":"人","fq":"力制切","vol":"08","py":"lì","duan":[{"e":"比也。","n":"此篆葢晚出。漢人少言例者。杜氏說左傳乃云發凡言例。例之言迾也。迾者、遮迾以爲禁。經皆作列、作厲。不作迾。周禮司𣜩注。厲、遮例也。釋文。例本作列。葢古比例字衹作列。"}]},"係":{"expl":"絜束也。从人从系，系亦聲。","rad":"人","fq":"胡計切","vol":"08","py":"xì","duan":[{"e":"絜束也。","n":"絜者、麻一耑也。絜束者、圍而束之。左傳。係輿人。又以朱絲係玉二？。束之義也。束之則縷與物相連。故凡相聯屬謂之係。周易係遯、係丈夫、係小子。釋詁曰。係、繼也。"}]},"伐":{"expl":"擊也。从人持戈。一曰敗也。","rad":"人","fq":"房越切","vol":"08","py":"fá","duan":[{"e":"擊也。","n":"詩勿翦勿伐傳、鉦人伐𡔷傳皆曰。伐、擊也。禮記郊特牲。二日伐𡔷何居。鄭曰。伐猶擊也。尙書。不愆于四伐五伐。鄭曰。一擊一刺曰伐。詩是伐是肆箋云。伐謂擊刺之。按此伐之本義也。引伸之乃爲征伐。周禮九伐注云。諸侯之於國。如樹木之有根。是以言伐云"}]},"俘":{"expl":"軍所獲也。从人孚聲。《春秋傳》曰：“以爲俘聝。”","rad":"人","fq":"芳無切","vol":"08","py":"fū","duan":[{"e":"軍所獲也。","n":"春秋左氏經。齊人來歸衞俘。傳作衞寶。公羊、穀梁經傳皆作衞寶。杜曰。疑左氏經誤。按非誤也。俘、孚聲。寶、缶聲。古音同在尢幽部。經用假借字。傳用正字。又如經曰。莒人弒其君密州。左氏傳云。書曰莒人弒其君買朱鉏。買卽密。如㵋水卽汨水。朱鉏卽州。如邾婁卽鄒。亦是字異實同。不得疑經誤。亦不得謂傳誤。"}]},"但":{"expl":"裼也。从人旦聲。","rad":"人","fq":"徒旱切","vol":"08","py":"dàn","duan":[{"e":"裼也。","n":"衣部曰。裼者、但也。二篆爲轉注。古但裼字如此。袒則訓衣縫解。今之綻裂字也。今之經典。凡但裼字皆改爲袒裼矣。衣部又曰。？者、但也。裎者、但也。釋訓、毛傳皆曰。袒裼、肉袒也。肉袒者、肉外見無衣也。引伸爲徒也。凡曰但、曰徒、曰唐皆一聲之轉。空也。今人但謂爲語辭。而尟知其本義。因以袒爲其本義之字。古今字之不同類如此。"}]},"傴":{"expl":"僂也。从人區聲。","rad":"人","fq":"於武切","vol":"08","py":"yǔ","duan":[{"e":"僂也。","n":"問䘮注曰。傴、背曲也。通俗文。曲脊謂之傴僂。引伸爲鞫窮。恭敬之意。又莊子。以下傴拊人之民。借爲煦嫗字。左傳曰。一命而僂。再命而傴。三命而俯。析言之實無二義。"}]},"僂":{"expl":"尫也。从人婁聲。周公韈僂，或言背僂。","rad":"人","fq":"力主切","vol":"08","py":"lóu","duan":[{"e":"厄也。","n":"大徐本作尩也。非是。尩與僂異疾。小徐本作厄也。近是。科厄、木節也。厄與僂雙聲。人背之僂。有似木之科厄。晉語注曰。戚施、僂人也。左傳昭四年注。僂、肩傴也。穀梁傳跛僂並言。管子云。苦水所。多尩與傴人。然僂不得訓尩明矣。公羊傳。夫人不僂。不可使入。何云。僂、疾也。齊人語。夫人稽畱。不肎疾順公。荀卿書亦兩言僂訓疾。按此爲婁之假借字。婁卽屢。與驟通。驟訓數。亦訓疾。○又按大徐作？也。葢？是曲脛之名。引伸爲曲脊之名。所以？必釋爲？曲脛者。由其字作？。从大而偏曲其足。故二疾不妨同名。下文曰周公韤僂。葢？者亦得謂之僂。周公之脛不無少曲。疑大徐本爲長。甲戌二月重訂。"}]},"僇":{"expl":"癡行僇僇也。从人翏聲。讀若雡。一曰且也。","rad":"人","fq":"力救切","vol":"08","py":"lù","duan":[{"e":"癡行僇僇也。","n":"未聞。大學借爲戮字。荀卿書同。"}]},"仇":{"expl":"讎也。从人九聲。","rad":"人","fq":"巨鳩切","vol":"08","py":"qiú","duan":[{"e":"讎也。","n":"讎猶應也。左傳曰。嘉偶曰妃。怨偶曰仇。按仇與逑古通用。辵部怨匹曰逑。卽怨偶曰仇也。仇爲怨匹。亦爲嘉偶。如亂之爲治。苦之爲快也。周南君子好逑與公侯好仇義同。"}]},"儡":{"expl":"相敗也。从人畾聲。讀若雷。","rad":"人","fq":"魯回切","vol":"08","py":"léi","duan":[{"e":"相敗也。","n":"西征賦注引作壞敗之皃。寡婦賦注引作敗也。無相字。道德經傅奕本。儡儡兮其不足以無所歸。陸氏釋文曰。儽一本作儡。敗也。欺也。說文音雷。西征賦曰。寮位儡其隆替。寡婦賦。容貌儡以頓顇。注引禮記䘮容儡儡。今禮記作纍纍。非也。"}]},"蔕":{"expl":"瓜當也。从艸帶聲。","rad":"艸","fq":"都計切","vol":"01","py":"dì","duan":[{"e":"𤓰當也。","n":"曲禮。削𤓰、土疐之。釋木、棗李曰疐之疐者、蔕之假借字。聲類曰。蔕、果鼻也。𤓰當、果鼻正同類。老子。深根固柢。柢亦作蔕。西京賦。蔕倒茄於藻井。皆假借爲柢字。"}]},"咎":{"expl":"災也。从人从各。各者，相違也。","rad":"人","fq":"其久切","vol":"08","py":"jiù","duan":[{"e":"災也。","n":"災當是本作烖。天火曰災。引伸之凡失意自天而至曰災。釋詁曰。咎、病也。小雅伐木傳曰。咎、過也。北山箋云。咎猶罪過也。西伯戡𥠖鄭注。咎、惡也。吕覽移樂篇注。咎、殃也。方言。咎、謗也。"}]},"仳":{"expl":"別也。从人比聲。《詩》曰：“有女仳離。”","rad":"人","fq":"芳比切","vol":"08","py":"pǐ","duan":[{"e":"別也。","n":"王風中谷有蓷傳云爾。"}]},"倃":{"expl":"毀也。从人咎聲。","rad":"人","fq":"其久切","vol":"08","py":"jiù","duan":[{"e":"毀也。","n":"疑咎字可以包之。但廣韵引已如此。"}]},"倠":{"expl":"仳倠，醜面。从人隹聲。","rad":"人","fq":"許惟切","vol":"08","py":"suī","duan":[{"e":"仳倠、","n":"逗。"}]},"値":{"expl":"措也。从人直聲。","rad":"人","fq":"直吏切","vol":"08","py":"zhí","duan":[{"e":"持也。","n":"持各本作措。措者、置也。非其義。今依韵會所據正。韵會雖譌待。然轉刻之失耳。陳風。値其鷺羽。傳曰。値、持也。引伸爲當也。凡彼此相遇、相當曰値。亦持之意也。史、漢多用直爲之。姚察云。古字例以直爲値。是也。價値亦是相當意。"}]},"侂":{"expl":"寄也。从人㡯聲。㡯，古文宅。","rad":"人","fq":"他各切","vol":"08","py":"tuō","duan":[{"e":"寄也。","n":"此與託音義皆同。俗作托。非也。玉篇引論語。可以侂六尺之孤。"}]},"僔":{"expl":"聚也。从人尊聲。《詩》曰：“僔沓背僧。”","rad":"人","fq":"慈損切","vol":"08","py":"zǔn","duan":[{"e":"聚也。","n":"小雅十月之交曰。噂沓背憎。傳曰。噂猶噂噂。沓猶沓沓。箋云。噂噂沓沓、相對談語。許於口部旣引之云聚語矣。此復引詩。字从人。云聚也。謂聚人非聚語。葢三家詩駁文。兼引之耳。廣雅。僔僔、衆也。叢艸亦曰䔿䔿。"}]},"像":{"expl":"象也。从人从象，象亦聲。讀若養。","rad":"人","fq":"徐兩切","vol":"08","py":"xiànɡ","duan":[{"e":"佀也。","n":"各本作象也。今依韵會所據本正。象者、南越大獸之名。於義無取。雖韓非曰。人希見生象也。而案其圖以想其生。故諸人之所以意想者皆謂之象。然韓非以前或衹有象字。無像字。韓非以後小篆旣作像。則許𣃔不以象釋似。復以象釋像矣。𣪠辭曰。爻也者、效此者也。象也者、像此者也。又曰。象也者、像也。爻也者、效天下之動者也。葢象爲古文。聖人以像釋之。雖他本像亦作象。然鄭康成王輔嗣本非不可信也。凡形像圖像想像字皆當从人。而學者多作象。象行而像廢矣。許書二曰象形。度許固必作像形。招䰟云。像設君室。"}]},"倦":{"expl":"罷也。从人卷聲。","rad":"人","fq":"渠眷切","vol":"08","py":"juàn","duan":[{"e":"罷也。","n":"罷者、遣有罪也。引伸爲休息之偁。倦與力部劵義少別。鉉等於劵下注曰。今俗作倦、義同。葢不檢人部固有倦耳。"}]},"傮":{"expl":"終也。从人曹聲。","rad":"人","fq":"作曹切","vol":"08","py":"zāo","duan":[{"e":"終也。","n":"大雅。似先公酋矣。釋詁、毛詩傳皆曰。酋、終也。酋卽遒字。正義作遒。遒訓迫。亦訓終。如亂亦訓治也。傮之古音與遒同。亦訓終。葢古遒傮通用。"}]},"荄":{"expl":"艸根也。从艸亥聲。","rad":"艸","fq":"古哀切","vol":"01","py":"ɡāi","duan":[{"e":"艸根也。","n":"見釋艸及方言。郭曰。今俗謂韭根爲荄。"}]},"偶":{"expl":"桐人也。从人禺聲。","rad":"人","fq":"五口切","vol":"08","py":"ǒu","duan":[{"e":"桐人也。","n":"偶者、寓也。寓於木之人也。字亦作寓。亦作禺。同音假借耳。按木偶之偶與二枱並耕之耦義迥別。凡言人耦、射耦、嘉耦、怨耦皆取耦耕之意。而無取桐人之意也。今皆作偶則失古意矣。又俗言偶然者、當是俄字之聲誤。"}]},"弔":{"expl":"問終也。古之葬者，厚衣之以薪。从人持弓，會敺禽。","rad":"人","fq":"多嘯切","vol":"08","py":"diào","duan":[{"e":"問終也。","n":"謂有死䘮而問之也。襍記曰。弔者東面致命曰。寡君聞君之䘮。寡君使某。如何不淑。曲禮。知死者傷。鄭注曰。說者有弔辭曰。皇天降灾。子遭罹之。如何不淑。曾子問。父䘮稱父。母䘮稱母。鄭注云。父使人弔之辭云。某子聞某之䘮。某子使某。如何不淑。母則若云。宋蕩伯姬聞姜氏之䘮。伯姬使某。如何不淑。此皆問終之辭。淑、善也。如何不善者、欲其善也。故引伸之謂善爲弔。魯莊公使人弔宋大水云。若之何不弔。卽如何不淑也。左傳。哀公誄孔子。昊天不弔。先鄭注周禮大祝引作昊天不淑。此弔淑通用之徵。應劭、王肅皆訓弔爲善。粊誓。無敢不弔。卽無敢不善也。凡書大誥多士君奭、詩節南山瞻卬、逸周書祭公解、左傳莊十一年襄十三年十四年二十三年昭二"}]},"佋":{"expl":"廟佋穆。父爲佋，南面。子爲穆，北面。从人召聲。","rad":"人","fq":"市招切","vol":"08","py":"zhāo","duan":[{"e":"廟佋穆。父爲佋南面。子爲穆北面。从人。召聲。","n":"市招切。按此篆雖經典釋文時偁之。然必晉人所竄入。晉人以凡昭字可易爲曜。而昭穆不可易也。乃讀爲上招切。且又製此篆竄入說文。使天下皆作此。是猶漢人改蘭臺漆書以合己也。且生曰父、曰母。死曰𦒱、曰妣。考妣則字當从鬼、人示也。从人何居。當刪去。"}]},"㑗":{"expl":"神也。从人身聲。","rad":"人","fq":"失人切","vol":"08","py":"shēn","duan":[{"e":"神也。","n":"按神當作身。聲之誤也。廣雅曰。孕重妊娠身媰㑗也。玉篇曰。㑗、妊身也。大雅曰。大任有身。傳曰。身、重也。箋云。重謂懷孕也。身者古字。㑗者今字。一說許云神也。葢許所據古義。今不可詳。"}]},"僊":{"expl":"長生僊去。从人从䙴，䙴亦聲。","rad":"人","fq":"相然切","vol":"08","py":"xiān","duan":[{"e":"長生僊去。","n":"僊去疑當爲䙴去。莊子曰。千歲猒世。去而上僊。小雅。婁舞僊僊。傳曰。婁、數也。數舞僊僊然。按僊僊、舞袖飛揚之意。正引伸假借之義也。"}]},"僰":{"expl":"犍爲蠻夷。从人棘聲。","rad":"人","fq":"蒲北切","vol":"08","py":"bó","duan":[{"e":"楗爲蠻夷也。","n":"楗各本作犍。今依漢碑从木。司馬相如傳曰。唐蒙使略通夜郞西僰中。文穎曰。夜郞、僰中皆西南夷。後以爲牂柯、楗爲二郡。按楗爲郡有僰道縣。卽今四川敘州府治也。其人民曰僰。王制。屛之遠方。西方曰僰。東方曰寄。鄭注。僰當爲棘。棘之言逼。使之逼寄於夷戎。按記文僰字、鄭不以爲西南夷。故易爲棘。經傳之棘多訓亟也。故曰棘之言逼。使與寄字一例。釋文云。棘又作僰。於此知記本作僰。鄭易爲棘也。唐初本已誤。"}]},"仚":{"expl":"人在山上。从人从山。","rad":"人","fq":"呼堅切","vol":"08","py":"xiān","duan":[{"e":"人在山上皃。","n":"引伸爲高舉皃。顏元孫引鮑明遠書勢云。鳥仚魚躍。"}]},"僥":{"expl":"南方有焦僥。人長三尺，短之極。从人堯聲。","rad":"人","fq":"五聊切","vol":"08","py":"yáo","duan":[{"e":"南方有焦僥人長三尺。短之極也。","n":"見魯語。焦魯語作僬。以說文及山海經正之。則从人非是。人當作民。魯語作氏。民之誤也。據郭注山海經。兩引魯語。一作民。一作人。人皆唐避諱改耳。韋曰。僬僥、西南蠻之別名。海外南經曰。焦僥國在三首東。大荒南經曰。有小人。名曰焦僥之國。許系之南方。葢本山海經。"}]},"𠏮":{"expl":"帀也。从人對聲。","rad":"人","fq":"都隊切","vol":"08","py":"duì","duan":[{"e":"市也。","n":"汲古閣及集韵、類篇皆作帀。宋刻葉抄及廣韵作市。今按市爲長。其字从對則無囗匝意。葢卽今之兌換字也。"}]},"俇":{"expl":"遠行也。从人狂聲。","rad":"人","fq":"居況切","vol":"08","py":"ɡuànɡ","duan":[{"e":"遠行也。","n":"楚辭曰。䰟俇俇而南征。注。俇俇、遑遽貌。按王注是也。"}]},"荺":{"expl":"茇也。茅根也。从艸均聲。","rad":"艸","fq":"于敏切","vol":"01","py":"yǔn","duan":[{"e":"茇也。茅根也。","n":"荺見釋艸。荺者、茇也。茇者、艸根也文相承。顧廣圻曰。依許君所說。是爾雅本云荺、茇、荄根。郭誤茇爲茭。遂以荺茭爲一義。荄根爲一義。茅根也之上當有一曰二字。此別一義。以荺專屬茅根也。"}]},"件":{"expl":"分也。从人从牛。牛大物，故可分。","rad":"人","fq":"其輦切","vol":"08","py":"jiàn","duan":[]},"侶":{"expl":"徒侶也。从人呂聲。","rad":"人","fq":"力舉切","vol":"08","py":"lǚ","duan":[]},"侲":{"expl":"僮子也。从人辰聲。","rad":"人","fq":"章刃切","vol":"08","py":"zhèn","duan":[]},"倅":{"expl":"副也。从人卒聲。","rad":"人","fq":"七內切","vol":"08","py":"cuì","duan":[]},"傔":{"expl":"從也。从人兼聲。","rad":"人","fq":"苦念切","vol":"08","py":"qiàn","duan":[]},"倜":{"expl":"倜儻，不羈也。从人从周。未詳。","rad":"人","fq":"他歴切","vol":"08","py":"tì","duan":[]},"儻":{"expl":"倜儻也。从人黨聲。","rad":"人","fq":"他朖切","vol":"08","py":"tǎnɡ","duan":[]},"佾":{"expl":"舞行列也。从人䏌聲。","rad":"人","fq":"夷質切","vol":"08","py":"yì","duan":[]},"倒":{"expl":"仆也。从人到聲。","rad":"人","fq":"當老切","vol":"08","py":"dǎo","duan":[]},"儈":{"expl":"合市也。从人、會，會亦聲。","rad":"人","fq":"古外切","vol":"08","py":"ɡuì","duan":[]},"茇":{"expl":"艸根也。从艸犮聲。春艸根枯，引之而發土爲撥，故謂之茇。一曰艸之白華爲茇。","rad":"艸","fq":"北末切","vol":"01","py":"bá","duan":[{"e":"艸根也。从艸。犮聲。","n":"北末切。十五部。"}]},"低":{"expl":"下也。从人、氐，氐亦聲。","rad":"人","fq":"都兮切","vol":"08","py":"dī","duan":[]},"債":{"expl":"債負也。从人、責，責亦聲。","rad":"人","fq":"側賣切","vol":"08","py":"zhài","duan":[]},"價":{"expl":"物直也。从人、賈，賈亦聲。","rad":"人","fq":"古訝切","vol":"08","py":"jià","duan":[]},"停":{"expl":"止也。从人亭聲。","rad":"人","fq":"特丁切","vol":"08","py":"tínɡ","duan":[]},"僦":{"expl":"賃也。从人、就，就亦聲。","rad":"人","fq":"卽就切","vol":"08","py":"jiù","duan":[]},"伺":{"expl":"𠊱望也。从人司聲。自低已下六字，从人，皆後人所加。","rad":"人","fq":"相吏切","vol":"08","py":"sì","duan":[]},"僧":{"expl":"浮屠道人也。从人曾聲。","rad":"人","fq":"穌曾切","vol":"08","py":"sēnɡ","duan":[]},"佇":{"expl":"久立也。从人从宁。","rad":"人","fq":"直呂切","vol":"08","py":"zhù","duan":[]},"偵":{"expl":"問也。从人貞聲。","rad":"人","fq":"丑鄭切","vol":"08","py":"zhēn","duan":[]},"𠤎":{"expl":"變也。从到人。凡𠤎之屬皆从𠤎。","rad":"𠤎","fq":"呼跨切","vol":"08","py":"huà","duan":[{"e":"變也。","n":"變者、？也。凡變𠤎當作匕。教化當作化。許氏之字指也。今變匕字盡作化。化行而匕廢矣。大宗伯。以禮樂合天地之化。百物之產。注曰。能生非類曰化。生其種曰產。按虞、荀注易。分別天變地化。陽變陰化。析言之也。許以匕釋變者、渾言之也。"}]},"芃":{"expl":"艸盛也。从艸凡聲。《詩》曰：“芃芃黍苗。”","rad":"艸","fq":"房戎切","vol":"01","py":"pénɡ","duan":[{"e":"艸盛皃。","n":"皃字依韵㑹。鄘風。芃芃其麥。毛曰。芃芃然方盛長。"}]},"𠤗":{"expl":"未定也。从𠤎𥎨聲。𥎨，古文矢字。","rad":"𠤎","fq":"語期切","vol":"08","py":"yí","duan":[{"e":"未定也。","n":"按未、衍字也。大雅。靡所止疑。傳云。疑、定也。箋云。止、息。禮十七篇多云疑立。鄭於士昏禮云。疑、止。句絕作正者誤立、自定之皃。於鄉飮酒禮云。疑讀如作爲者誤仡然從於趙孟之仡。疑、止。句立、自定之皃。於鄉射禮云。疑、止也。有矜莊之色。釋言。疑、休戾也。郭云。戾、止也。疑者亦止。按已上疑字卽說文之𠤗字。非說文訓惑之疑也。疑𠤗字相似。學者識疑不識𠤗。於是經典無𠤗。於許書定也之上增之未字矣。𠤗从矢聲。其字在古音十五部。故桑柔以與資維階爲韵。鄭注禮讀如仡。若疑字古音在一部。其字从子、从止、从𠤗省。會意。非矢聲也。"}]},"眞":{"expl":"僊人變形而登天也。从𠤎从目从乚；(音隱。)八，所乘載也。","rad":"𠤎","fq":"側鄰切","vol":"08","py":"zhēn","duan":[{"e":"僊人變形而登天也。","n":"此眞之本義也。經典但言誠實。無言眞實者。諸子百家乃有眞字耳。然其字古矣。古文作？。非倉頡以前已有眞人乎。引伸爲眞誠。凡稹鎭瞋謓䐜塡窴闐嗔滇鬒瑱？愼字皆以眞爲聲。多取充實之意。其顚槇字以頂爲義者、亦充實上𦫵之意也。愼字今訓謹。古則訓誠。小雅愼爾優游、予愼無罪傳皆云。誠也。又愼爾言也、大雅考愼其相箋皆云。誠也。愼訓誠者、其字从眞。人必誠而後敬。不誠未有能敬者也。敬者愼之弟二義。誠者愼之弟一義。學者沿其流而不溯其原矣。故若詩傳、箋所說諸愼字、謂卽眞之假借字可也。"}]},"化":{"expl":"教行也。从𠤎从人，𠤎亦聲。","rad":"𠤎","fq":"呼跨切","vol":"08","py":"huà","duan":[{"e":"教行也。","n":"教行於上。則化成於下。賈生曰。此五學者旣成於上。則百姓黎民化輯於下矣。老子曰。我無爲而民自化。"}]},"匕":{"expl":"相與比敘也。从反人。匕，亦所以用比取飯，一名柶。凡匕之屬皆从匕。","rad":"匕","fq":"卑履切","vol":"08","py":"bǐ","duan":[{"e":"相與比敘也。","n":"比者、密也。敘者、次弟也。以妣籒作？、䃾或作？、秕或作？等求之。則比亦可作？也。此製字之本義。今則取飯器之義行而本義廢矣。"}]},"匙":{"expl":"匕也。从匕是聲。","rad":"匕","fq":"是支切","vol":"08","py":"chí","duan":[{"e":"匕也。","n":"方言曰。匕謂之匙。蘇林注漢書曰。北方人名匕曰匙。玄應曰。匕或謂之匙。今江蘇所謂𣘻匙、湯匙也。亦謂之調羹。實則古人取飯、載牲之具。其首葢銳而薄。故左傳矢族曰匕。昭卄六年傳是也。劍曰匕首。周禮桃氏注是也。亦作鍉。玄應曰。方言作㮛。"}]},"𠤏":{"expl":"相次也。从匕从十。鴇从此。","rad":"匕","fq":"博抱切","vol":"08","py":"bǎo","duan":[{"e":"相次也。从匕十。","n":"十者、數之具也。比敘之則必有其次矣。博抱切。鴇亦作䳈。包聲。古音在三部。則鴇古音亦在三部也。"}]},"𢺵":{"expl":"頃也。从匕支聲。匕，頭頃也。《詩》曰：“𢺵彼織女。”","rad":"匕","fq":"去智切","vol":"08","py":"qì","duan":[{"e":"頃也。","n":"頃者、頭不正也。小雅大東。跂彼織女。傳曰。跂、隅皃。按隅者、陬隅不正。而角織女三星成三角。言不正也。許所據作？。今本乃改爲俗企字。音同而義不同矣。"}]},"頃":{"expl":"頭不正也。从匕从頁。","rad":"匕","fq":"去營切","vol":"08","py":"qīnɡ","duan":[{"e":"頭不正也。","n":"匕頭角而不正方。故頭不正从匕曰頃。引伸爲凡傾仄不正之偁。今則傾行而頃廢。專爲俄頃、頃畝之用矣。謚法。敏以敬愼曰頃。甄心動懼曰頃。祗勤追懼曰？。"}]},"匘":{"expl":"頭𩪦也。从匕；匕，相匕著也。巛象髮，囟象匘形。","rad":"匕","fq":"奴皓切","vol":"08","py":"nǎo","duan":[{"e":"頭𩪦也。","n":"𩪄者、骨中脂也。頭𩪦者、頭骨中脂也。左傳。晉侯夢與楚子搏。楚子伏己而盬其腦。服注。如俗語相駡云啑汝腦矣。服語正謂吸其頭髓也。"}]},"𠨐":{"expl":"望，欲有所庶及也。从匕从卪。《詩》曰：“高山卬止。”","rad":"匕","fq":"伍岡切","vol":"08","py":"yǎnɡ","duan":[{"e":"望也。","n":"鉉無也。非。卬與仰義別。仰訓舉。卬訓望。今則仰行而卬廢。且多改卬爲仰矣。小雅車舝曰。高山卬止。箋云。卬慕。過秦論。常以十倍之地。百萬之衆。卬關而攻秦。俗本作叩、作仰。皆字誤、聲誤耳。晉語。如川然。有原。以御浦而後大。孔晁本作卬浦。牛亮反。言川仰浦而大。人仰教而成。廣雅。仰、恃也。仰亦卬之誤。大雅傳曰。顒顒卬卬、盛皃。引伸之義也。釋詁、毛傳皆曰。卬、我也。語言之叚借也。"}]},"禜":{"expl":"設緜蕝爲營，以禳風雨、雪霜、水旱、癘疫於日月星辰山川也。从示，榮省聲。一曰禜、衞，使灾不生。《禮記》曰：“雩，禜。祭水旱。”","rad":"示","fq":"爲命切","vol":"01","py":"yǒnɡ","duan":[{"e":"設緜蕝爲營。㠯禳風雨雪霜水旱厲疫于日月星辰山川也。","n":"史記、漢書叔孫通傳。皆云爲緜蕞。野外習之。韋昭云。引繩爲緜。立表爲蕞。蕞卽蕝也。詳艸部。凡環帀爲營。禜營曡韵。左氏傳。子産曰。山川之神。則水旱癘疫之災。於是乎禜之。日月星辰之神。則雪霜風雨之不時。於是乎禜之。許與鄭司農周禮注引皆先日月星辰。與今本不同也。"}]},"𦺉":{"expl":"華葉布。从艸傅聲。讀若傅。","rad":"艸","fq":"方遇切","vol":"01","py":"fū","duan":[{"e":"華葉布也。","n":"與尃？字義通。從艸、故訓華葉布。"}]},"卓":{"expl":"高也。早匕爲㔬，匕卪爲卬，皆同義。","rad":"匕","fq":"竹角切","vol":"08","py":"zhuō","duan":[{"e":"高也。","n":"論語。如有所立。卓爾。凡言卓犖、謂殊絕也。亦作卓躒。按稽部？、特止也。辵部逴、遠也。人部倬、箸大也。皆一義之引伸。覲禮。匹馬卓上。九馬隨之。注。卓讀如卓王孫之卓。卓猶旳也。以素旳一馬爲上。素旳一馬、謂白馬也。鄭意白馬出衆故謂之卓。史記多叚淖爲卓。"}]},"艮":{"expl":"很也。从匕、目。匕目，猶目相匕，不相下也。《易》曰：“𥃩其限。”匕目爲𥃩，𠤎目爲眞也。","rad":"匕","fq":"古恨切","vol":"08","py":"ɡèn","duan":[{"e":"很也。","n":"很者、不聽從也。一曰行難也。一曰盭也。易傳曰。艮、止也。止可兼很三義。許不依孔子訓止者。止、下基也。足也。孔子取其引伸之義。許說字之書。嫌云止則義不明審。故易之。此字書與說經有不同。實無二義也。方言曰。艮、堅也。釋名曰。艮、限也。"}]},"从":{"expl":"相聽也。从二人。凡从之屬皆从从。","rad":"从","fq":"疾容切","vol":"08","py":"cónɡ","duan":[{"e":"相聽也。","n":"聽者、聆也。引伸爲相許之偁。言部曰。許、聽也。按从者今之從字。從行而从廢矣。周禮司儀。客？拜辱於朝。陸德明本如此。許書凡云从某。大徐作从。小徐作從。江氏聲曰。作从者是也。以類相與曰从。"}]},"從":{"expl":"隨行也。从辵、从，从亦聲。","rad":"从","fq":"慈用切","vol":"08","py":"cónɡ","duan":[{"e":"隨行也。","n":"以从辵。故云隨行。齊風。並驅從兩肩兮。傳曰。從、逐也。逐亦隨也。釋詁曰。從、自也。其引伸之義也。又引伸訓順。春秋經從祀先公。左傳曰順祀先公。是從訓順也。左傳。使亂大從。王肅曰。從、順也。左傳。大伯不從。是以不嗣。謂不肎順其長幼之次也。引伸爲主從、爲從横、爲操從。亦假縱爲之。"}]},"幷":{"expl":"相從也。从从幵聲。一曰从持二爲并。","rad":"从","fq":"府盈切","vol":"08","py":"bìnɡ","duan":[{"e":"相从也。","n":"从舊作從。今正。合也。兼也。"}]},"比":{"expl":"密也。二人爲从，反从爲比。凡比之屬皆从比。","rad":"比","fq":"毗至切","vol":"08","py":"bǐ","duan":[{"e":"密也。","n":"今韵平上去入四聲皆錄此字。要宻義足以？之。其本義謂相親密也。餘義俌也、及也、次也、校也、例也、類也、頻也、擇善而從之也、阿黨也。皆其所引伸。許書無篦字。古衹作比。見蒼頡篇、釋名、漢書匈奴傳。周禮或叚比爲庀。"}]},"毖":{"expl":"愼也。从比必聲。《周書》曰：“無毖于卹。”","rad":"比","fq":"兵媚切","vol":"08","py":"bì","duan":[{"e":"愼也。","n":"釋詁曰。毖、愼也。大雅。爲謀爲毖。傳曰。毖、愼也。"}]},"北":{"expl":"𦮃也。从二人相背。凡北之屬皆从北。","rad":"北","fq":"博墨切","vol":"08","py":"bèi","duan":[{"e":"𦮃也。","n":"乖者、戾也。此於其形得其義也。軍奔曰北。其引伸之義也。謂背而走也。韋昭注國語曰。北者、古之背字。又引伸之爲北方。尙書大傳、白虎通、漢律曆志皆言北方、伏方也。陽氣在下。萬物伏藏。亦乖之義也。"}]},"冀":{"expl":"北方州也。从北異聲。","rad":"北","fq":"几利切","vol":"08","py":"jì","duan":[{"e":"北方州也。","n":"周禮曰。河內曰冀州。爾雅曰。兩河閒曰冀州。據許說是北方名冀。而因以名其州也。叚借爲望也、幸也。葢以冀同覬也。覬者、𣢆幸也。"}]},"丘":{"expl":"土之高也，非人所爲也。从北从一。一，地也，人居在丘南，故从北。中邦之居，在崐崘東南。一曰四方高，中央下爲丘。象形。凡丘之屬皆从丘。(今隷變作丘。)","rad":"丘","fq":"去鳩切","vol":"08","py":"qiū","duan":[{"e":"土之高也。","n":"大司徒注曰。土高曰丘。"}]},"蓻":{"expl":"艸木不生也。一曰茅芽。从艸執聲。","rad":"艸","fq":"姊入切","vol":"01","py":"zí","duan":[{"e":"艸木不生也。","n":"蓻之言蟄也。與？反對成文。玉篇云艸木生皃。未知？是。"}]},"虛":{"expl":"大丘也。崐崘丘謂之崐崘虛。古者九夫爲井，四井爲邑，四邑爲丘。丘謂之虛。从丘虍聲。","rad":"丘","fq":"丘如切","vol":"08","py":"xū","duan":[{"e":"大丠也。昆侖丠謂之昆侖虚。","n":"昆侖丘、丘之至大者也。釋水曰。河出昆侖虚。海內西經曰。海內昆侖之虚在西北。帝之下都。卽西山經昆侖之丘。實惟帝之下都也。水部曰。泑津在昆侖虚下。按虚者、今之墟字。猶昆侖今之崐崘字也。虚本謂大丘。大則空曠。故引伸之爲空虚。如魯、少皞之虚。衛、顓頊之虚。陳、大皞之虚。鄭、祝融之虚。皆本帝都。故謂之虚。又引伸之爲凡不實之稱。邶風。其虚其邪。毛曰。虚、虚也。謂此虚字乃謂空虚。非丘虚也。一字有數義數音。則訓詁有此例。如許書巳、巳也。謂此辰巳之字。其義爲巳甚也。虚訓空。故丘亦訓空。如漢書丘亭是。自學者䍐能會通。乃分用墟虚字。別休居邱於二切。而虚之本義廢矣。"}]},"屔":{"expl":"反頂受水丘。从丘，泥省聲。","rad":"丘","fq":"奴低切","vol":"08","py":"ní","duan":[{"e":"反頂受水丠也。","n":"釋丘曰。水潦所止、泥丘。釋文曰。依字又作屔。郭云。頂上洿下者。孔子世家。叔梁紇與顏氏女禱於尼丘。得孔子。生而首上圩頂。故因名曰丘。字仲尼。按白虎通曰。孔子反宇。是謂尼丘。德澤所興。藏元通流。葢頂似尼丘。故以類命爲象。屔是正字。泥是古通用字。尼是假借字。水潦所止是爲泥淖。儀禮注曰。淖者、和也。劉瓛述張禹之說。仲者、中也。尼者、和也。孔子有中和之德。故曰仲尼。張固從泥淖得解。顏氏家訓乃曰。至如仲尼居三字之中。兩字非體。三蒼尼旁益丘。說文尸下施几。如此之類。何由可從。玉裁謂。若言駭俗則難依。若言古義則不可不知也。又漢碑有作仲泥者。淺人深非之。豈知其合古義哉。"}]},"㐺":{"expl":"眾立也。从三人。凡乑之屬皆从乑。讀若欽崟。","rad":"㐺","fq":"魚音切","vol":"08","py":"yín","duan":[{"e":"眾立也。","n":"玉篇作衆也。"}]},"眾":{"expl":"多也。从乑、目，衆意。","rad":"㐺","fq":"之仲切","vol":"08","py":"zhònɡ","duan":[{"e":"多也。从㐺目。衆意。","n":"之仲切。九部。古平聲。"}]},"聚":{"expl":"會也。从乑取聲。邑落云聚。","rad":"㐺","fq":"才句切","vol":"08","py":"jù","duan":[{"e":"會也。","n":"公羊傳曰。會猶冣也。注云。冣、聚也。按冖部曰。冣、積也。積以物言。聚以人言。其義通也。古亦叚埾爲聚。"}]},"臮":{"expl":"眾詞與也。从乑自聲。《虞書》曰：“臮咎繇。”","rad":"㐺","fq":"其冀切","vol":"08","py":"jì","duan":[{"e":"衆與䛐也。","n":"與詞各本誤倒。今依廣韵正。衆與者、多與也。所與非一人也。詞者、意內言外之謂。或假洎爲之。如鄭詩諩偁無逸爰洎小人是也。亦假曁爲之。如公羊傳及者何。與也。會及曁、皆與也。曁猶曁曁也。釋詁曰。曁、與也。釋訓曰。曁、不及也。按不及、及也。卽公羊所謂猶曁曁也。"}]},"𡈼":{"expl":"善也。从人、士。士，事也。一曰象物出地挺生也。凡𡈼之屬皆从𡈼。","rad":"𡈼","fq":"他鼎切","vol":"08","py":"tǐnɡ","duan":[{"e":"善也。从人士。","n":"會意。他鼎切。十一部。"}]},"徵":{"expl":"召也。从微省，壬爲徵。行於微而文達者，即徵之。","rad":"𡈼","fq":"陟陵切","vol":"08","py":"zhēnɡ","duan":[{"e":"召也。","n":"召者、𧦝也。周禮司市典祀注、鄉飮酒禮注、鄉射禮注皆曰。徵、召也。按徵者、證也。驗也。有證驗、斯有感召。有感召、而事以成。故士昏禮注、禮運注又曰。徵、成也。依文各解。義則相通。"}]},"朢":{"expl":"月滿與日相朢，以朝君也。从月从臣从𡈼。𡈼，朝廷也。","rad":"𡈼","fq":"無放切","vol":"08","py":"wànɡ","duan":[{"e":"月滿也。","n":"此與望各字。望从朢省聲。今則望專行而朢廢矣。"}]},"㸒":{"expl":"近求也。从爪、𡈼。𡈼，徼幸也。","rad":"𡈼","fq":"余箴切","vol":"08","py":"yín","duan":[{"e":"近求也。","n":"近求、浸淫之意也。小徐無近字。廣韵曰。貪也。"}]},"䓄":{"expl":"艸多皃。从艸㹞聲。江夏平春有䓄亭。","rad":"艸","fq":"語斤切","vol":"01","py":"yín","duan":[{"e":"艸多皃。从艸。㹞聲。","n":"語斤切。十三部。"}]},"重":{"expl":"厚也。从壬東聲。凡重之屬皆从重。","rad":"重","fq":"柱用切","vol":"08","py":"zhònɡ","duan":[{"e":"厚也。","n":"？者、？也。厚斯重矣。引伸之爲鄭重、重曡。古衹平聲。無去聲。"}]},"量":{"expl":"稱輕重也。从重省，曏省聲。","rad":"重","fq":"呂張切","vol":"08","py":"liánɡ","duan":[{"e":"稱輕重也。","n":"稱者、銓也。漢志曰。量者、所以量多少也。衡權者、所以均物平輕重也。此訓量爲稱輕重者。有多少斯有輕重。視其多少可辜搉其重輕也。其字之所以从重也。引伸之凡料理曰量。凡所容受曰量。"}]},"臥":{"expl":"休也。从人、臣，取其伏也。凡臥之屬皆从臥。","rad":"臥","fq":"吾貨切","vol":"08","py":"wò","duan":[{"e":"伏也。","n":"伏大徐作休。誤。臥與寑異。寑於牀。論語寢不尸是也。臥於几。孟子隱几而臥是也。臥於几。故曰伏。尸篆下曰象臥之形是也。此析言之耳。統言之則不別。故宀部曰寑者臥也。曲禮云。寢毋伏。則謂寢於牀者毋得俯伏也。引伸爲凡休息之偁。"}]},"監":{"expl":"臨下也。从臥，䘓省聲。","rad":"臥","fq":"古銜切","vol":"08","py":"jiān","duan":[{"e":"臨下也。","n":"小雅毛傳。監、視也。許書。𥌈、視也。監、臨下也。古字少而義晐。今字多而義別。監與鑒互相假。"}]},"臨":{"expl":"監臨也。从臥品聲。","rad":"臥","fq":"力尋切","vol":"08","py":"lín","duan":[{"e":"監也。","n":"各本作監臨也。乃複字未刪而又倒之。今正。"}]},"䭆":{"expl":"楚謂小兒嬾䭆。从臥、食。","rad":"臥","fq":"尼見切","vol":"08","py":"nè","duan":[{"e":"楚謂小兒嬾䭆。","n":"玉篇作楚人謂小嬾曰䭆。此有兒。衍字也。"}]},"身":{"expl":"躳也。象人之身。从人𠂆聲。凡身之屬皆从身。","rad":"身","fq":"失人切","vol":"08","py":"shēn","duan":[{"e":"躳也。","n":"呂部曰。躳、身也。二字爲互訓。躳必入呂部者。躳謂身之傴。主於脊骨也。"}]},"軀":{"expl":"體也。从身區聲。","rad":"身","fq":"豈俱切","vol":"08","py":"qū","duan":[{"e":"體也。","n":"體者、十二屬之總名也。可區而別之。故曰軀。"}]},"㐆":{"expl":"歸也。从反身。凡㐆之屬皆从㐆。","rad":"㐆","fq":"於機切","vol":"08","py":"yī","duan":[{"e":"歸也。","n":"曡韵爲訓。"}]},"殷":{"expl":"作樂之盛稱殷。从㐆从殳。《易》曰：“殷薦之上帝。”","rad":"㐆","fq":"於身切","vol":"08","py":"yīn","duan":[{"e":"作樂之盛偁殷。","n":"此殷之本義也。如易豫象傳是。引伸之爲凡盛之偁。又引伸之爲大也。又引伸之爲衆也。又引伸之爲正也、中也。"}]},"茂":{"expl":"艸豐盛。从艸戊聲。","rad":"艸","fq":"莫候切","vol":"01","py":"mào","duan":[{"e":"艸木盛皃。","n":"依韵㑹訂。茂之引伸借爲懋勉字。"}]},"衣":{"expl":"依也。上曰衣，下曰裳。象覆二人之形。凡衣之屬皆从衣。","rad":"衣","fq":"於稀切","vol":"08","py":"yī","duan":[{"e":"依也。","n":"曡韵爲訓。依者、倚也。衣者、人所倚以蔽體者也。"}]},"裁":{"expl":"制衣也。从衣𢦔聲。","rad":"衣","fq":"昨哉切","vol":"08","py":"cái","duan":[{"e":"制衣也。","n":"刀部曰。制者、裁也。二字爲轉注。韓非子曰。管仲善制割。賓胥無善削縫。隰朋善純緣。制割者、前裁之謂也。裁者、衣之始也。引伸爲裁度、風裁。"}]},"衮":{"expl":"天子享先王，卷龍繡於下幅，一龍蟠阿上鄉。从衣公聲。","rad":"衣","fq":"古本切","vol":"08","py":"ɡǔn","duan":[{"e":"天子亯先王。","n":"句。"}]},"𧝑":{"expl":"丹縠衣。从衣㠭聲。","rad":"衣","fq":"知扇切","vol":"08","py":"zhàn","duan":[{"e":"丹縠衣也。","n":"縠、細絹也。庸風。瑳兮瑳兮。其之展也。毛詩傳。禮有展衣者。以丹縠爲衣。馬融從之。許說同。先後鄭注周禮及劉氏釋名皆云。展衣白。後鄭云。展衣以禮見王及賔客之服。字當爲襢。襢之言亶。亶、誠也。按詩、周禮作展。叚借字也。玉藻、襍記作襢。後鄭從之。許作？。漢禮家文字不同如此。"}]},"褕":{"expl":"翟，羽飾衣。从衣俞聲。一曰直裾謂之襜褕。","rad":"衣","fq":"羊朱切","vol":"08","py":"yú","duan":[{"e":"褕翟、","n":"逗。二字舊刪褕字。今依毛詩補。"}]},"袗":{"expl":"玄服。从衣㐱聲。","rad":"衣","fq":"之忍切","vol":"08","py":"zhěn","duan":[{"e":"襌衣也。","n":"各本作玄服也。今按論語。當暑紾絺綌。陸云。本又作袗。下曲禮注引論語作袗。孔安國曰。暑則單服。玉藻。振絺綌。不入公門。鄭云。振讀爲袗。袗、襌也。依此二注定其解。"}]},"𧘝":{"expl":"上衣也。从衣从毛。古者衣𧚍，以毛爲表。","rad":"衣","fq":"陂矯切","vol":"08","py":"biǎo","duan":[{"e":"上衣也。","n":"上衣者、衣之在外者也。論語。當暑袗絺綌。必表而出之。孔曰。加上衣也。皇云。若在家則裘葛之上亦無別加衣。若出行接賓客皆加上衣。當暑絺綌可單。若出不可單。則必加上衣也。嫌暑熱不加。故特明之。玉藻。表裘不入公門。鄭曰。表裘、外裘也。外裘今本作外衣誤禪絺綌、外裘二者形且褻。皆當表之乃出。引伸爲凡外箸之稱。"}]},"裏":{"expl":"衣内也。从衣里聲。","rad":"衣","fq":"良止切","vol":"08","py":"lǐ","duan":[{"e":"衣內也。","n":"引伸爲凡在內之偁。"}]},"襁":{"expl":"負兒衣。从衣强聲。","rad":"衣","fq":"居兩切","vol":"08","py":"qiǎnɡ","duan":[{"e":"負兒衣。从衣。強聲。","n":"居㒳切。按古繈緥字从糸不从衣。淺人不得其解。而增襁篆於此。叚令許有此字。當與𧝐篆爲類矣。當刪。說詳糸部。"}]},"襋":{"expl":"衣領也。从衣棘聲。《詩》曰：“要之襋之。”","rad":"衣","fq":"己力切","vol":"08","py":"jí","duan":[{"e":"衣領也。","n":"領者、頸項也。因以爲衣在頸之名。魏風。要之襋之。毛傳曰。要、要也。襋、領也。按裳之上曰要。衣之上曰領。皆以人體名之也。士喪禮云。襚者左執領。右執要。"}]},"𧀄":{"expl":"艸茂也。从艸畼聲。","rad":"艸","fq":"丑亮切","vol":"01","py":"chànɡ","duan":[{"e":"艸茂也。","n":"孟子、史記艸木畼茂字皆作畼。俗又作暢。"}]},"襮":{"expl":"黼領也。从衣㬥聲。《詩》曰：“素衣朱𧟊。”","rad":"衣","fq":"蒲沃切","vol":"08","py":"bó","duan":[{"e":"黼領也。","n":"白與黑相次文謂之黼。黼領、刺黼文於領也。唐風。素衣朱襮。釋器曰。黼領謂之襮。毛傳曰。襮、領也。諸矦繡黼丹朱中衣。箋云。繡當爲綃。綃黼丹朱中衣。中衣以綃黼爲領、丹朱爲純也。按或借爲表㬥字云表襮。"}]},"衽":{"expl":"衣䘳也。从衣壬聲。","rad":"衣","fq":"如甚切","vol":"08","py":"rèn","duan":[{"e":"衣䘳也。","n":"凡朝祭䘮服。衣與裳殊。深衣不殊。䘮服記曰。衽二尺有五寸。鄭曰。衽所以掩裳際也。上正一尺。燕尾一尺五寸。凡用布三尺五寸。玉裁按。朝祭服同。玉藻注所謂或殺而下屬衣。則垂而放之者也。玉藻。衽當旁。鄭曰。謂裳幅所交裂也。江氏永曰。以布四幅正裁爲八幅。上下皆廣一尺一寸。各邊削幅一寸。得七尺二寸。旣足要中之數矣。下齊倍於要。又以布二幅斜裁爲四幅。狹頭二寸在上。寛頭二尺在下。各邊削幅一寸。亦得七尺二寸。共得一丈四尺四寸。此四幅連屬於裳之㒳旁。所謂衽當旁也。玉裁按。此注所謂或殺而上屬裳。則縫之以合前後者也。此二者皆謂之衽。凡言衽者、皆謂裳之兩旁。鄭曰。凡衽者或殺而下。或殺而上。是以小要取名焉。小要者、䘮大記云"}]},"褸":{"expl":"衽也。从衣婁聲。","rad":"衣","fq":"力主切","vol":"08","py":"lǚ","duan":[{"e":"衽也。","n":"方言曰。褸謂之衽。注。衣襟也。或曰。裳際也。又曰。褸謂之袩。注。卽衣衽也。按郭云衣襟者、謂正幅。云裳際者、謂旁幅。謂衽爲正幅者、今義非古義也。衽者、殺而下者也。故引伸之衣被醜弊。或謂之褸裂。或謂之襤褸。或謂之緻。"}]},"𧛽":{"expl":"衽也。从衣叞聲。","rad":"衣","fq":"於胃切","vol":"08","py":"wèi","duan":[{"e":"衽也。","n":"此衽當訓衽席。左傳。歸國子之元。寘之新篋。褽之以玄纁。加組帶焉。杜曰。褽、薦也。與許云衽也義同。"}]},"𧚨":{"expl":"䘳緣也。从衣疌聲。","rad":"衣","fq":"七入切","vol":"08","py":"qì","duan":[{"e":"䘳緣也。","n":"緣、衣純也。純之允切。深衣曰。具父母、大父母。衣純以績。具父母。衣純以靑。如孤子。衣純以素。純、袂。緣。純邊。廣各寸半。詩。靑靑子衿。毛曰。靑衿、靑領也。正謂緣以靑也。葢古者深衣。右自領及衽。左自袼亦及衽。皆緣之。故曰䘳緣。"}]},"䘳":{"expl":"交衽也。从衣金聲。","rad":"衣","fq":"居音切","vol":"08","py":"jīn","duan":[{"e":"交衽也。","n":"釋器曰。衣皆謂之襟。孫、郭皆曰。襟、交領也。鄭風。靑靑子衿。毛曰。靑衿、靑領也。方言。衿謂之交。按䘳之字一變爲衿。再變爲襟。字一耳。而爾雅之襟。毛傳、方言之衿。皆非許所謂䘳也。爾雅、詩傳、方言皆自領言之。深衣。曲袷如矩以應方。注。袷、交領也。占者方領。如今小兒衣領。玉藻。袷二寸。注。曲領也。曲禮。天子視不上於袷。玉藻。侍於君。視帶以及袷。注皆云交領也。袷者、交領之正字。其字从合。左傳作襘。从會與从合一也。交領宜作袷。而毛詩、爾雅、方言作衿。殆以衿袷爲古今字與。若許云䘳、交衽也。此則謂掩裳際之衽。當前幅後幅相交之處。故曰交衽。䘳本衽之偁。因以爲正幅之偁。正幅統於領。因以爲領之偁。此其推移之漸。許"}]},"褘":{"expl":"蔽厀也。从衣韋聲。《周禮》曰：“王后之服褘衣。”謂畫袍。","rad":"衣","fq":"許㱕切","vol":"08","py":"huī","duan":[{"e":"蔽厀也。","n":"按蔽厀非韠也。許釋韠、市皆云所以蔽前。鄭注禮同。韠以蔽前、而非專蔽厀也。方言曰。蔽厀、江淮之閒謂之褘。或謂之袚。魏宋南楚之閒謂之大巾。自關東西謂之蔽厀。齊魯之郊謂之衻。許不云褘者、韠也。則知許不謂一物也。釋名曰。褘所以蔽厀前也。婦人蔽厀亦如之。亦不以爲一物。而已與許異。"}]},"衭":{"expl":"襲衭也。从衣夫聲。","rad":"衣","fq":"甫無切","vol":"08","py":"fū","duan":[{"e":"襲衭也。","n":"襲衭葢古語。或曰。當作衭逗、襲也句。廣韵曰。衭、衣前襟。鍇曰。今俗猶言之。少儀。劔則啟櫝葢襲之。加夫襓與劔焉。鄭曰。夫襓、劔衣也。夫或爲煩。皆發聲。按鄭旣謂夫襓是劔衣。又云夫是發聲。葢不能定其說也。而廣雅曰。衭襓、䘤、劔衣也。夫加衣旁。卽許此字。亦是韜藏意。韋部曰。韜、劔衣也。"}]},"襲":{"expl":"左衽袍。从衣，龖省聲。","rad":"衣","fq":"似入切","vol":"08","py":"xí","duan":[{"e":"𠂇衽袍。","n":"小斂大斂之前衣死者謂之襲。士䘮禮。乃襲三稱。注曰。遷尸於襲上而衣之。凡衣死者。左衽不紐。按喪大記。小斂大斂。祭服不倒。皆左衽結絞不紐。襲亦左衽不紐也。袍、褻衣也。記曰。纊爲繭。緼爲袍也。許曰。袍、襺也。士喪禮。襲衣有爵弁服、皮弁服、褖衣。注。褖衣所以表袍者。子羔之襲繭衣裳與稅衣爲一是也。斂始於襲。襲始於袍。故單言袍也。襲字引申爲凡揜襲之用。若記曰帛爲褶。士喪禮古文作襲。叚借字也。喪大記、玉藻用禮今文作褶。注曰。褶、袷也。有表裏而無著。許依古文禮。故不收褶字。凡經典重襲之義。如筮襲于夢。武王所用。祥襲則行。不襲則增。修德而改⺊。皆當作褶。褶義之引申。"}]},"袍":{"expl":"襺也。从衣包聲。《論語》曰：“衣弊緼袍。”","rad":"衣","fq":"薄襃切","vol":"08","py":"páo","duan":[{"e":"襺也。","n":"秦風。與子同袍。釋言、毛傳皆曰。袍、襺也。玉藻曰。纊爲繭。緼爲袍。注曰。衣有著同褚之異名也。記文袍襺有別。析言之。渾言不別也。古者袍必有表。後代爲外衣之偁。釋名曰。袍、丈夫箸。下至跗者也。袍、苞也。苞、内衣也。婦人以絳作。義亦然也。"}]},"蔭":{"expl":"艸陰地。从艸陰聲。","rad":"艸","fq":"於禁切","vol":"01","py":"yìn","duan":[{"e":"艸陰地。","n":"左氏傳曰。若去枝葉。則本根無所庇蔭矣。楚語。玉足以庇蔭嘉穀。引伸爲凡覆庇之義也。釋言曰。庇茠蔭也。說文曰。庇、蔭也。休、止息也。"}]},"襺":{"expl":"袍衣也。从衣繭聲。以絮曰襺，以緼曰袍。《春秋傳》曰：“盛夏重襺。”","rad":"衣","fq":"古典切","vol":"08","py":"jiǎn","duan":[{"e":"袍衣也。从衣。繭聲。","n":"古典切。十二部。玉藻作繭者、字之叚借也。絮中往往有小繭。故絮得名繭。"}]},"𧝵":{"expl":"南楚謂襌衣曰𧝵。从衣枼聲。","rad":"衣","fq":"徒叶切","vol":"08","py":"dié","duan":[{"e":"南楚謂襌衣曰褋。","n":"九歌曰。遺余褋兮醴浦。方言曰。襌衣、江淮南楚之間謂之褋。關之東西謂之襌衣。按屈原賦當用南楚語。王逸云襜襦。殆非也。"}]},"袤":{"expl":"衣帶以上。从衣矛聲。一曰南北曰袤，東西曰廣。","rad":"衣","fq":"莫候切","vol":"08","py":"mào","duan":[{"e":"衣帶㠯上。","n":"此古義也。少得其證。今則後義行而古義廢矣。帶者、上衣下常之介也。"}]},"襘":{"expl":"帶所結也。从衣會聲。《春秋傳》曰：“衣有襘。”","rad":"衣","fq":"古外切","vol":"08","py":"ɡuì","duan":[{"e":"帶所結也。","n":"昭十一年左傳。叔向曰。衣有襘。帶有結。視不過結襘之中。所以道容貌也。杜注。襘、領會。結、帶結也。玉藻、曲禮、深衣皆謂交領曰袷。襘卽袷。會合同義。且叔向視不過結襘之中。卽曲禮視天子不上於袷。不下於帶。玉藻侍君視帶以及袷也。然則杜注得之。許合繪結二者爲一。似誤矣。杜注當仍賈、服之舊。"}]},"褧":{"expl":"檾也。《詩》曰：“衣錦褧衣。”示反古。从衣耿聲。","rad":"衣","fq":"去潁切","vol":"08","py":"jiǒnɡ","duan":[{"e":"檾衣也。","n":"衣字舊無。今補。檾者、枲屬。績檾爲衣。是爲褧也。許意如是。若鄭箋衞風云。褧、襌也。不言襌用何物。鄭風箋云。褧、襌也。葢以襌縠爲之。與許說異。縠者、細絹也。以絲而非以枲矣。鄭說本玉藻。玉藻、中庸作絅。禮經作顈。皆假借字也。"}]},"袛":{"expl":"袛裯，短衣。从衣氐聲。","rad":"衣","fq":"都兮切","vol":"08","py":"dī","duan":[{"e":"袛裯、","n":"逗。"}]},"裯":{"expl":"衣袂，袛裯。从衣周聲。","rad":"衣","fq":"都牢切","vol":"08","py":"dāo","duan":[{"e":"衣袂袛裯。","n":"依全書之例。此當云袛裯也。衣袂二字葢誤衍。召南。抱衾與裯。毛曰。裯、襌被也。"}]},"襤":{"expl":"裯謂之襤褸。襤，無緣也。从衣監聲。","rad":"衣","fq":"魯甘切","vol":"08","py":"lán","duan":[{"e":"裯謂之襤褸。","n":"裯謂袛裯。九辨。被荷裯之晏晏。王曰。裯、祗裯也。方言曰。裯謂之襤。郭注。袛裯、敝衣。亦謂襤褸。按說文褸字疑衍。袛裯亦名襤耳。不如郭說也。"}]},"䙃":{"expl":"無袂衣謂之䙃。从衣，惰省聲。","rad":"衣","fq":"徙臥切","vol":"08","py":"duò","duan":[{"e":"無袂衣謂之䙃。","n":"方言文。"}]},"𧛔":{"expl":"衣躬縫。从衣毒聲。讀若督。","rad":"衣","fq":"冬毒切","vol":"08","py":"dú","duan":[{"e":"衣躳縫。","n":"躳从吕。自後言身也。躳與𧛔雙聲。下文曰裻、背縫。亦卽此字也。方言作𧞶。繞循謂之𧞶裺。郭云。衣督脊也。莊子作督。緣督以爲經。李云。緣、順也。督、中也。衣躳縫者、深衣云負繩及踝以應直是也。"}]},"䔏":{"expl":"艸皃。从艸造聲。","rad":"艸","fq":"初救切","vol":"01","py":"chòu","duan":[{"e":"艸皃。从艸。造聲。","n":"初救切。三部。玉裁按。左氏傳。僖子使助薳氏之簉。杜注。簉、副倅也。釋文曰。說文簉從艸。五經文字艸部曰。䔏、倅也。春秋傳從竹。攷李善注長笛賦簉弄曰。說文簉倅字如此。注江淹詩步櫩簉瓊弁曰。說文簉襍字如此。然則左傳、文選從竹之簉。皆從艸之䔏之譌。而說文艸皃之下。本有一曰䔏襍也五字。今人言集。漢人多言襍。倅周禮作萃、作倅。亦湊集意也。小徐注䔏字云。艸相次也。葢識此意。"}]},"袪":{"expl":"衣袂也。从衣去聲。一曰袪，褱也。褱者，袌也。袪，尺二寸。《春秋傳》曰：“披斬其袪。”","rad":"衣","fq":"去魚切","vol":"08","py":"qū","duan":[{"e":"衣袂也。","n":"鄭風遵大路、唐風羔裘傳皆曰。袪、袂也。按袪有與袂析言之者。深衣注曰。袪、袂口也。喪服記注曰。袪、袖口也。檀弓注曰。袪、袖緣口也。深衣喪服且袂與袪並言。葢袂上下徑二尺二寸。至袪則上下徑尺二寸。其義當分別也。若詩之兩言袪。則無庸分別。定本唐風傳曰。袪、袂末也。此非是。傳下文言本末。本謂羔裘。末謂豹袖。非謂袂本袪末也。"}]},"褎":{"expl":"袂也。从衣𥝩聲。","rad":"衣","fq":"似又切","vol":"08","py":"xiù","duan":[{"e":"袂也。","n":"唐風羔裘傳曰。褎猶袪也。蒙上章言之。褎引伸爲盛飾皃。邶風傳曰。褎如、盛服皃。董仲舒傳曰。褎然爲舉首。序傳曰。樂安褏褏。生民傳曰。褎、長也。箋云。枝葉長也。皆其義也。"}]},"袂":{"expl":"袖也。从衣夬聲。","rad":"衣","fq":"彌弊切","vol":"08","py":"mèi","duan":[{"e":"褎也。从衣。夬聲。","n":"彌弊切。十五部。郭景純云。？卽袂字。"}]},"褢":{"expl":"袖也。一曰藏也。从衣鬼聲。","rad":"衣","fq":"戶乖切","vol":"08","py":"huái","duan":[{"e":"褎也。","n":"褢之爲言回也。袼之高下。可以運肘。袂之長短。反詘之及肘。"}]},"褱":{"expl":"俠也。从衣眔聲。一曰橐。","rad":"衣","fq":"戶乖切","vol":"08","py":"huái","duan":[{"e":"俠也。","n":"俠當作㚒。轉寫之誤。亦部曰。㚒、盜竊褱物也。从亦有所持。俗謂蔽人俾㚒是也。腋有所持。褱藏之義也。在衣曰褱。在手曰握。今人用懷挾字。古作褱㚒。"}]},"袌":{"expl":"褱也。从衣包聲。","rad":"衣","fq":"薄保切","vol":"08","py":"bào","duan":[{"e":"褱也。","n":"論語。子生三年。然後免於父母之懷。馬融釋以懷抱。卽褱袌也。今字抱行而袌廢矣。抱者、引埾也。"}]},"襜":{"expl":"衣蔽前。从衣詹聲。","rad":"衣","fq":"處占切","vol":"08","py":"chān","duan":[{"e":"衣蔽歬。","n":"釋器曰。衣蔽前謂之襜。此謂衣。非謂蔽厀也。引伸之凡衣或曰襜褕。或曰襜襦。皆取蔽義。又引伸之凡所用蔽謂之襜。巾車皆有容葢。大鄭曰。容謂幨車。山東謂之裳幃。或曰潼容。幨卽襜字也。詩毛傳曰。帷裳、婦人之車。帷裳卽裳幃也。士昏禮。婦車有裧。襍記。其輤有裧。裧亦卽襜字。"}]},"袥":{"expl":"衣衸。从衣石聲。","rad":"衣","fq":"他各切","vol":"08","py":"tuō","duan":[{"e":"衣衸。","n":"廣雅。衩、衸、袥、？膝也。玉篇。？膝、裠衸也。按？膝者、裠衩在正中者也。故謂之袥。言其開拓也。亦謂之衸。言其中分也。袥之引伸爲推廣之義。玄瑩曰。天他開闢。宇宙袥坦。廣雅釋詁曰。袥、大也。今字作開拓。拓行而袥廢矣。㡿與袥音義同。"}]},"衸":{"expl":"袥也。从衣介聲。","rad":"衣","fq":"胡介切","vol":"08","py":"xiè","duan":[{"e":"袥也。","n":"廣韵十六怪云。補膝裙也。乃？膝裙衸也五字之誤。"}]},"襗":{"expl":"絝也。从衣睪聲。","rad":"衣","fq":"徒各切","vol":"08","py":"duó","duan":[{"e":"絝也。","n":"絝者、脛衣也。按周禮玉府注云。燕衣服者、巾絮寢衣袍襗之屬。論語。紅紫不以爲褻服。鄭注云。褻衣、袍襗。秦風。與子同澤。傳曰。澤、潤澤也。箋云。襗、褻衣。近汗垢。釋名曰。汗衣、近身受汗垢之衣也。詩謂之澤。受汗澤。廣韵此字三見。一曰褻衣。一曰袗襗。一曰衣襦。亦皆不云絝。○又按毛云。潤澤也。箋云。襗、褻衣。此葢毛作潤襗。故箋冡襗而釋之。潤襗、衣名也。"}]},"茲":{"expl":"艸木多益。从艸，兹省聲。","rad":"艸","fq":"子之切","vol":"01","py":"zī","duan":[{"e":"艸木多益。","n":"詩小雅。兄也永歎。毛曰。兄、茲也。戴先生毛鄭詩考正曰。茲今通用滋。說文茲字說云。艸木多益。滋字說云。益也。韋注國語云。兄、益也。詩之辭意言不能如兄弟相救、空滋之長歎而已。按大雅職兄斯引傳亦云兄、茲也。"}]},"袉":{"expl":"裾也。从衣它聲。《論語》曰：“朝服，袉紳。”","rad":"衣","fq":"唐左切","vol":"08","py":"tuó","duan":[{"e":"裾也。","n":"士昏禮。主人爵弁纁裳緇袘。注曰。纁裳者衣緇衣。不言衣與帶而言袘者、空其文。明其與衣皆用緇。袘謂緣。緣之言施。以緇緣裳。象陽氣下施。按袘卽袉之𣜩變。鄭云裳緣。許云裾者、許謂衣袌曰袉。經言緇袉。則緇衣可知也。緇衣未有無袌者也。"}]},"裾":{"expl":"衣袍也。从衣居聲。讀與居同。","rad":"衣","fq":"九魚切","vol":"08","py":"jū","duan":[{"e":"衣袌也。","n":"袌各本作袍。今依韵會正。上文云袌、褱也。褱物謂之袌。因之衣前䘳謂之袌。方言。襌衣有袌者。趙魏之間謂之袏衣。郭云。前施袌囊也。房報切。按前施袌囊卽謂右外䘳。方言。無袌者謂之裎衣。則今之對䘳衣。無右外䘳者也。褻衣無袌。禮服必有袌。上文之袥、衸謂無袌者。唐、宋人所謂衩衣也。公羊傳曰。反袂拭面。涕沾袍。此袍當作袌。何注曰。衣前襟也。釋器。衣皆謂之襟。衱謂之裾。衱同袷。謂交領。袌連於交領。故曰衱謂之裾。郭景純曰。衣後襟。非也。釋名裾在後之說。非是。"}]},"衧":{"expl":"諸𧘚也。从衣于聲。","rad":"衣","fq":"羽俱切","vol":"08","py":"yú","duan":[{"e":"諸𧘎也。","n":"按當云諸𧘎衣袌也。篇、韵可證。後漢書光武帝紀。皆冠幘而服婦人衣。諸于繡镼。注引前書音義曰。諸于、大掖衣。如婦人之袿衣。按大掖謂大其袌也。方言。袿謂之裾。于者、𧘘之假借字。"}]},"褰":{"expl":"絝也。从衣，寒省聲。《春秋傳》曰：“徵褰與襦。”","rad":"衣","fq":"去虔切","vol":"08","py":"qiān","duan":[{"e":"絝也。","n":"昭卄五年左傳曰。公在乾侯。徵褰與襦。杜曰。褰、絝也。方言曰。絝、齊魯之間謂之䙭。按今方言作䙭。俗字也。褰之本義謂絝。俗乃假爲騫衣字。騫、虧也。古騫衣字作騫。今假褰而褰之本義廢矣。"}]},"襱":{"expl":"絝踦也。从衣龍聲。","rad":"衣","fq":"丈冢切","vol":"08","py":"lónɡ","duan":[{"e":"絝踦也。","n":"方言曰。袴、齊魯之間謂之䙭。或謂之襱。郭注。今俗呼袴踦爲襱。音鮦魚。按絝踦對下文絝上言。袴之近足狹處也。"}]},"袑":{"expl":"絝上也。从衣召聲。","rad":"衣","fq":"市沼切","vol":"08","py":"shào","duan":[{"e":"絝上也。","n":"漢朱博傳。功曹官屬多裦衣大袑。不中節度。絝上對上絝踦言。股所居也。大之則寛緩。"}]},"襑":{"expl":"衣博大。从衣尋聲。","rad":"衣","fq":"他感切","vol":"08","py":"tǎn","duan":[{"e":"衣博大也。从衣。𢒫聲。","n":"他感切。古音在七部。篇、韵皆亦似林切。"}]},"襃":{"expl":"衣博裾。从衣，𠊻省聲。𠊻，古文𠈃。","rad":"衣","fq":"博毛切","vol":"08","py":"bāo","duan":[{"e":"衣博裾。","n":"博裾謂大其袌囊也。漢書。褒衣大袑。謂大其衣絝之上也。引伸之爲凡大之偁。爲褒美。"}]},"𧝐":{"expl":"緥也。从衣啻聲。《詩》曰：“載衣之𧝐。”","rad":"衣","fq":"他計切","vol":"08","py":"tì","duan":[{"e":"緥也。","n":"小雅？干曰。載衣之裼。傳曰。裼、？也。此謂裼卽𧝐之假借字也。易聲啻聲古音同在十六部。故借但裼字爲𧝐字。釋文曰。韓詩作褅。褅、集韵云或𧝐字。韓詩用正字。毛詩用假借字也。緥者、小兒衣也。"}]},"褍":{"expl":"衣正幅。从衣耑聲。","rad":"衣","fq":"多官切","vol":"08","py":"duān","duan":[{"e":"衣正幅。","n":"凡衣及裳不衺殺之幅曰褍。左傳端委。杜注。禮衣端正無殺故曰端。周禮。士有玄端、素端。鄭云。端者、取其正也。按褍者、正幅之名。非衣名。巾部㡏下曰。正褍裂。"}]},"𦵦":{"expl":"艸旱盡也。从艸俶聲。《詩》曰：“𦵦𦵦山川。”","rad":"艸","fq":"徒歴切","vol":"01","py":"dí","duan":[{"e":"艸旱盡也。","n":"此與艸木多益反對成文。"}]},"䙟":{"expl":"重衣皃。从衣圍聲。《爾雅》曰：“䙟䙟䙡䙡。”","rad":"衣","fq":"羽非切","vol":"08","py":"wéi","duan":[{"e":"重衣皃。从衣。圍聲。","n":"羽非切。十五部。"}]},"複":{"expl":"重衣皃。从衣复聲。一曰褚衣。","rad":"衣","fq":"方六切","vol":"08","py":"fù","duan":[{"e":"重衣也。","n":"也作皃者誤。凡古書也皃二字互譌者多矣。引伸爲凡重之偁。複與復義近。故書多用復爲複。吕覽。水澤復。注曰。復或作複。凍重累也。詩。？復？穴。鄭注月令曰。古者複穴。"}]},"褆":{"expl":"衣厚褆褆。从衣是聲。","rad":"衣","fq":"杜兮切","vol":"08","py":"tí","duan":[{"e":"衣厚褆褆。","n":"褆褆與媞媞義略同。爾雅曰。媞媞、安也。篇、韵又曰。衣服端正皃。"}]},"襛":{"expl":"衣厚皃。从衣農聲。《詩》曰：“何彼襛矣。”","rad":"衣","fq":"汝容切","vol":"08","py":"nónɡ","duan":[{"e":"衣厚皃。","n":"凡農聲之字皆訓厚。醲、酒厚也。濃、露多也。襛、衣厚皃也。引伸爲凡多厚之偁。召南曰。何彼襛矣。唐棣之華傳曰。襛猶戎戎也。按韓詩作茙茙。卽戎戎之俗字耳。戎取同聲得其義。"}]},"裻":{"expl":"新衣聲。一曰背縫。从衣叔聲。","rad":"衣","fq":"冬毒切","vol":"08","py":"dú","duan":[{"e":"新衣聲。","n":"此當依玉篇先鵠切。子虚賦。翕呷萃蔡。張揖曰。萃蔡、衣聲也。萃蔡讀如碎？二音。裻亦雙聲字。"}]},"袳":{"expl":"衣張也。从衣多聲。《春秋傳》曰：“公會齊矦于袳。”","rad":"衣","fq":"尺氏切","vol":"08","py":"chǐ","duan":[{"e":"衣張也。","n":"張篇、韵皆作長。非。按袳之言侈也。經典？用袳字者。多作移、作侈。表記曰。衣服以移之。注云。讀如禾氾移之移。猶廣大也。周禮注曰。大夫已上移袂。少牢饋食禮曰。主婦被錫衣移袂。注云。移者、葢半士妻之袂以益之。"}]},"裔":{"expl":"衣裾也。从衣㕯聲。","rad":"衣","fq":"余制切","vol":"08","py":"yì","duan":[{"e":"衣裙也。","n":"裙各本及篇、韵皆作裾。今正。玄應書卷十四曰。說文云。裔、衣裙也。以子孫爲苗裔者。取下垂義也。按帔曰裠。裳曰下裠。此衣裠謂下裠。故方言、離騷注皆曰。裔、末也。方言又曰。裔、祖也。亦謂其遠也。方言又曰。裔夷狄之總名。郭云。邊地爲裔。按左傳。衞侯⺊繇曰。裔焉大國。言邊於大國也。裔之義如此。言衣裙得以通之。若言衣裾則何以解焉。小徐云。裾、衣邊。葢小徐作注時本作裙。"}]},"衯":{"expl":"長衣皃。从衣分聲。","rad":"衣","fq":"撫文切","vol":"08","py":"fēn","duan":[{"e":"長衣皃。","n":"子虚賦。衯衯裶裶。郭璞曰。皆衣長貌也。集韵曰。或書作？。疑作？者是。"}]},"袁":{"expl":"長衣皃。从衣，叀省聲。","rad":"衣","fq":"羽元切","vol":"08","py":"yuán","duan":[{"e":"長衣皃。","n":"此字之本義。今衹謂爲姓。而本義廢矣。古與爰通用。如袁盎、漢書作爰盎是也。王風。有兔爰爰。傳曰。爰爰、緩意。遠轅等字以袁爲聲。亦取其意也。"}]},"𧜣":{"expl":"短衣也。从衣鳥聲。《春秋傳》曰：“有空𧜣。”","rad":"衣","fq":"都僚切","vol":"08","py":"diāo","duan":[{"e":"短衣也。","n":"釋名曰。三百斛曰𦩍。𦩍、䂏也。䂏、短也。今俗語尙呼短尾曰䂏尾。許書無䂏。當作𧜣。以短衣之義引伸也。"}]},"藃":{"expl":"艸皃。从艸歊聲。《周禮》曰：“轂𡚁不藃。”","rad":"艸","fq":"許嬌切","vol":"01","py":"xiāo","duan":[{"e":"艸皃。从艸。歊聲。","n":"許嬌切。二部。"}]},"䙝":{"expl":"重衣也。从衣執聲。巴郡有褺虹縣。","rad":"衣","fq":"徒叶切","vol":"08","py":"dié","duan":[{"e":"重衣也。","n":"凡古云衣一襲者、皆一褺之假借。褺讀如重㬪之㬪。文𨕖王命論。思有短褐之襲。李注引說文。襲、重衣也。王命論本作褺。李注時不誤。淺人妄改文選耳。漢書敘傳作短褐之褻。師古釋以親身之衣。不知爲褺字之誤也。古書之難讀如此。"}]},"裵":{"expl":"長衣皃。从衣非聲。","rad":"衣","fq":"薄回切","vol":"08","py":"péi","duan":[{"e":"長衣皃。","n":"此卽子虚賦裶字也。若史記子虚賦。弭節裵回。漢郊祀志。神裴回若畱放。乃長衣引伸之義。後漢書蘇竟傳注云。裴回謂縈繞淹畱是也。俗乃作俳佪、徘徊矣。"}]},"襡":{"expl":"短衣也。从衣蜀聲。讀若蜀。","rad":"衣","fq":"市玉切","vol":"08","py":"shǔ","duan":[{"e":"短衣也。","n":"篇、韵皆襡與襡爲二字。義別。韵會合而一之。非是。晉書夏統傳。使妓女服袿襡。"}]},"𧞐":{"expl":"衣至地也。从衣斲聲。","rad":"衣","fq":"竹角切","vol":"08","py":"zhuó","duan":[{"e":"衣至地也。从衣。斲聲。","n":"竹角切。三部。"}]},"襦":{"expl":"短衣也。从衣需聲。一曰㬮衣。","rad":"衣","fq":"人朱切","vol":"08","py":"rú","duan":[{"e":"短衣也。","n":"方言。襦、西南蜀漢之閒謂之曲領。或謂之襦。釋名有反閉襦、有單襦、有要襦。顔注急就篇曰。短衣曰襦。自膝以上。按襦若今襖之短者。袍若今襖之長者。"}]},"褊":{"expl":"衣小也。从衣扁聲。","rad":"衣","fq":"方沔切","vol":"08","py":"biǎn","duan":[{"e":"衣小也。","n":"引伸爲凡小之偁。"}]},"袷":{"expl":"衣無絮。从衣合聲。","rad":"衣","fq":"古洽切","vol":"08","py":"jiā","duan":[{"e":"衣無絮。","n":"此對以絮曰襺、以縕曰袍言也。"}]},"襌":{"expl":"衣不重。从衣單聲。","rad":"衣","fq":"都寒切","vol":"08","py":"dān","duan":[{"e":"衣不重。","n":"此與重衣曰複爲對。"}]},"襄":{"expl":"漢令：解衣耕謂之襄。从衣𤕦聲。","rad":"衣","fq":"息良切","vol":"08","py":"xiānɡ","duan":[{"e":"漢令。解衣而耕謂之𧞻。","n":"而字依韵會補。此襄字所以从衣之本義。惟見於漢令也。引伸之爲除去。爾雅釋言、詩牆有茨出車傳皆曰。襄、除也。周書謚法云。辟地有德曰襄。凡云攘地、攘夷狄皆襄之假借字也。又引伸之爲反復。大東傳云。襄、反也。謂除此而復乎彼也。釋言又曰。襄、駕也。此驤之假借字。凡云襄上也、襄舉也皆同。又馬注皋陶謨曰。襄、因也。謚法因事有功曰襄。此又攘之假借字。有因而盜曰攘。故凡因皆曰攘也。今人用襄爲輔佐之義。古義未嘗有此。"}]},"被":{"expl":"𡪢衣，長一身有半。从衣皮聲。","rad":"衣","fq":"平義切","vol":"08","py":"bèi","duan":[{"e":"𡪢衣。長一身有半。","n":"論語鄉黨篇曰。必有寢衣。長一身有半。孔安國曰。今被也。鄭注曰。今小臥被是也。引伸爲橫被四表之被。"}]},"禳":{"expl":"磔禳祀，除癘殃也。古者燧人禜子所造。从示襄聲。","rad":"示","fq":"汝羊切","vol":"01","py":"ránɡ","duan":[{"e":"磔禳、","n":"逗。"}]},"蔇":{"expl":"艸多皃。从艸旣聲。","rad":"艸","fq":"居味切","vol":"01","py":"jì","duan":[{"e":"艸多皃。","n":"木部。穊、稠也。音義同。"}]},"衾":{"expl":"大被。从衣今聲。","rad":"衣","fq":"去音切","vol":"08","py":"qīn","duan":[{"e":"大被。","n":"釋名曰。衾、广也。其下廣大如广受人也。？衣爲小被。則衾是大被。"}]},"襐":{"expl":"飾也。从衣象聲。","rad":"衣","fq":"徐兩切","vol":"08","py":"xiànɡ","duan":[{"e":"襐飾也。","n":"各本作飾也。奪襐。今補。此三字爲句。如偓佺、離黃之類。淺人泛謂爲複字可刪而刪之耳。巾部飾字下云。襐飾也。亦三字爲句。廣韵曰。襐、未筓冠者之首飾也。"}]},"衵":{"expl":"日日所常衣。从衣从日，日亦聲。","rad":"衣","fq":"人質切","vol":"08","py":"yì","duan":[{"e":"日日所常衣。","n":"衵服見宣九年左傳。"}]},"褻":{"expl":"私服。从衣埶聲。《詩》曰：“是褻袢也。”","rad":"衣","fq":"私列切","vol":"08","py":"xiè","duan":[{"e":"私服。","n":"私褻㬪韵。論語曰。紅紫不以爲褻服。引伸爲凡昵狎之偁。假借爲媟字。"}]},"衷":{"expl":"裏䙝衣。从衣中聲。《春秋傳》曰：“皆衷其衵服。”","rad":"衣","fq":"陟弓切","vol":"08","py":"zhōnɡ","duan":[{"e":"裏褻衣。","n":"褻衣有在外者。衷則在內者也。引伸爲折衷。假借爲中字。"}]},"袾":{"expl":"好佳也。从衣朱聲。《詩》曰：“靜女其袾。”","rad":"衣","fq":"昌朱切","vol":"08","py":"zhū","duan":[{"e":"好佳也。","n":"好下奪也字。好者、美也。佳者、善也。廣韵曰。朱衣也。按廣韵葢用說文古本。故其字从朱衣。所引詩則假袾爲姝也。"}]},"袓":{"expl":"事好也。从衣且聲。","rad":"衣","fq":"才與切","vol":"08","py":"jù","duan":[{"e":"事好也。","n":"事好猶言學好也。黹部引詩衣裳？？。方言曰。珇、好也。珇、美也。然則袓與？珇音義略同。"}]},"裨":{"expl":"接益也。从衣卑聲。","rad":"衣","fq":"府移切","vol":"08","py":"bì","duan":[{"e":"接也。","n":"此也字依玉篇補。手部曰。接、交也。"}]},"袢":{"expl":"無色也。从衣半聲。一曰《詩》曰：“是紲袢也。”讀若普。","rad":"衣","fq":"博幔切","vol":"08","py":"fán","duan":[{"e":"衣無色也。","n":"衣字依玉篇補。日部曰。暜、日無色也。袢讀若暜則音義皆同。女部曰。姅、婦人汚也。義亦相近。"}]},"雜":{"expl":"五彩相會。从衣集聲。","rad":"衣","fq":"徂合切","vol":"08","py":"zá","duan":[{"e":"五采相合也。","n":"與？字義略同。所謂五采彰施於五色作服也。引伸爲凡參錯之偁。亦借爲聚集字。詩言襍佩。謂集玉與石爲佩也。漢書凡言襍治之。猶今云會審也。"}]},"薋":{"expl":"艸多皃。从艸資聲。","rad":"艸","fq":"疾兹切","vol":"01","py":"cí","duan":[{"e":"艸多皃。","n":"離騷曰。薋菉葹以盈室。王注。薋、蒺蔾也。菉、王芻也。葹、枲耳也。詩楚楚者薋。三者皆惡艸也。據許君說、正謂多積菉葹盈室。薋非艸名。禾部曰。？、積禾也。音義同。蒺䔧之字說文作薺。今詩作茨、叔師所據詩作薋皆假借字耳。"}]},"裕":{"expl":"衣物饒也。从衣谷聲。《易》曰：“有孚，裕無咎。”","rad":"衣","fq":"羊孺切","vol":"08","py":"yù","duan":[{"e":"衣物饒也。","n":"引伸爲凡寛足之偁。方言。裕、道也。東齊曰裕。"}]},"襞":{"expl":"韏衣也。从衣辟聲。","rad":"衣","fq":"必益切","vol":"08","py":"bì","duan":[{"e":"韏衣也。","n":"韋部曰。革中辨謂之韏。革中辨者、取革中分其廣摺曡之。廣雅曰。韏、曲也。又曰。韏、詘也。衣之襵如革之襵。故曰韏衣。士冠禮。皮弁服素積。注曰。積猶辟也。以素爲裳。辟蹙其要中。子虚賦。襞積褰縐。張揖曰。襞積、簡齰也。襞、經傳作辟。積、俗作襀。簡、俗作襇。襞亦謂之襵。襵之涉反。"}]},"衦":{"expl":"摩展衣。从衣干聲。","rad":"衣","fq":"古案切","vol":"08","py":"ɡǎn","duan":[{"e":"摩展衣也。","n":"摩展者、摩其襵縐而展之也。石部硟下曰。以石衦繒也。衦之用與熨略同而異。"}]},"裂":{"expl":"繒餘也。从衣𠛱聲。","rad":"衣","fq":"良辥切","vol":"08","py":"liè","duan":[{"e":"繒餘也。","n":"巾部曰。㠲、㡜裂也。㡜、殘帛也。㡏、繒端裂也。內則曰。衣裳綻裂。方言曰。南楚凡人貧衣被醜敝。或謂之褸裂。皆繒餘之意。引伸爲凡分散殘餘之偁。或假烈爲之。方言曰。烈、餘也。晉衛之閒曰烈。齊語。戎車待游車之裂。韋注云。裂、殘也。古作？。通作列。"}]},"𧘽":{"expl":"弊衣。从衣奴聲。","rad":"衣","fq":"女加切","vol":"08","py":"ná","duan":[{"e":"敝衣。","n":"敝各本作弊。誤。今正。袽者敝衣。帤者敝巾。䋈者敝絮。各依所从而解之。易旣濟六四。繻有衣袽。虞翻曰。袽、敗衣也。然則袽卽𧘽字。糸部引易需有衣䋈。又見𧘽與䋈可通用也。晁說之曰。袽又作䘫。玉裁謂。袽䘫皆𧘽之誤字耳。"}]},"袒":{"expl":"衣縫解也。从衣旦聲。","rad":"衣","fq":"丈莧切","vol":"08","py":"zhàn","duan":[{"e":"衣縫解也。","n":"許書無綻字。此卽綻字也。許書但裼字作但。不作袒。今人以袒爲袒裼字。而但袒二篆本義俱廢矣。內則曰。衣裳綻裂。綻或作䘺。鄭曰。綻猶解也。綻尙未解而近於解。故曰猶。俗語引伸爲飽滿？裂之偁。按袒爲衣縫解。故从衣。䋎爲補縫。故从糸。音同而義相因也。"}]},"補":{"expl":"完衣也。从衣甫聲。","rad":"衣","fq":"博古切","vol":"08","py":"bǔ","duan":[{"e":"完衣也。","n":"旣袒則宜補之。故次之以補。引伸爲凡相益之偁。"}]},"𧝉":{"expl":"紩衣也。从衣、黹，黹亦聲。","rad":"衣","fq":"豬几切","vol":"08","py":"zhǐ","duan":[{"e":"紩衣也。","n":"糸部曰。紩者、縫也。縫者、以鍼紩衣也。方言曰。襜褕、其敝者謂之緻。注云。緻、縫納敝故之名也。丁履反。按緻卽𧝉字。黹爲鍼刺。𧝉爲縫敝衣。與補䋎二字義略同。"}]},"褫":{"expl":"奪衣也。从衣虒聲。讀若池。","rad":"衣","fq":"直离切","vol":"08","py":"chǐ","duan":[{"e":"奪衣也。","n":"奪當作敓。許訓奪爲遺失。訓敓爲彊取也。此等恐非許原文。後人以今字改古字耳。周易訟上九。或錫之鞶帶。終朝三褫之。侯果曰。褫、解也。鄭玄、荀爽、翟元皆作三拕之。荀、翟訓拕爲奪。淮南書曰。秦牛缺遇盜拕其衣。高注。拕、奪也。拕者、褫之假借字。十七十六二部音冣近也。引伸爲凡敓之偁。"}]},"𧝹":{"expl":"袒也。从衣𣎆聲。","rad":"衣","fq":"郎果切","vol":"08","py":"luǒ","duan":[{"e":"但也。","n":"但各本作袒。今正。左傳。欲觀其裸。正義曰。裸謂赤體無衣也。大戴禮曰。倮蟲三百六十。聖人爲之長。王制。？股肱。注曰。㩊衣出其臂脛也。按人部曰。但、裼也。謂免上衣。露裼衣。此裸裎皆訓但者。裸裎者、但之尢甚者也。"}]},"蓁":{"expl":"艸盛皃。从艸秦聲。","rad":"艸","fq":"側詵切","vol":"01","py":"zhēn","duan":[{"e":"艸盛皃。","n":"毛詩傳曰。蓁蓁至盛皃。"}]},"裎":{"expl":"袒也。从衣呈聲。","rad":"衣","fq":"丑郢切","vol":"08","py":"chénɡ","duan":[{"e":"但也。","n":"但各本作袒。今正。裎之言呈也、逞也。孟子。袒裼裸裎。亦作程。土喪禮注。倮程。"}]},"裼":{"expl":"袒也。从衣易聲。","rad":"衣","fq":"先擊切","vol":"08","py":"xī","duan":[{"e":"但也。","n":"但各本作袒。今正。人部曰。但者、裼也。故此云裼者、但也。是爲轉注。序云。五曰轉注。建類一首。同意相受。𦒱老是也。老部曰。老者、考也。考者、老也。是之謂建類一首。同意相受。凡全書中異部而互訓者視此。裼訓但。但訓裼。其一耑也。在許當時確知訓裼之字作但不作袒。自許至今。經傳子史皆爲袒裼。不爲但裼。賴許書僅存。可識字之本形本義。又以今字改之。則古形古義不傳。且上文云袒、衣縫解也。裸裎裼下皆云袒也。不皆爲衣縫解乎。是許之不通甚矣。𦒱諸經傳。凡中衣之外上衣。裘則有裼衣。裼衣之外上衣。玉藻。裘之裼也。見美也。服之襲也。充美也。鄭曰。裼者、免上衣。見裼衣。凡當盛禮者以充美爲敬。非盛禮者以見美爲敬。禮尙相變也。"}]},"衺":{"expl":"𠆎也。从衣牙聲。","rad":"衣","fq":"似嗟切","vol":"08","py":"xié","duan":[{"e":"𩎮也。","n":"交部曰。𩎮者。衺也。二篆爲互訓。小徐本作紕也。非是。𩎮今字作回。衺今字作邪。毛詩傳曰。回、邪也。"}]},"襭":{"expl":"以衣衽扱物謂之襭。从衣頡聲。","rad":"衣","fq":"胡結切","vol":"08","py":"xié","duan":[{"e":"㠯衣衽扱物謂之襭。","n":"扱、收也。周南。采采芣苢。薄言襭之。爾雅曰。扱衽謂之襭。毛傳同。"}]},"袺":{"expl":"執衽謂之袺。从衣吉聲。","rad":"衣","fq":"格八切","vol":"08","py":"jié","duan":[{"e":"執衽謂之袺。","n":"周南。采采芣苢。薄言袺之。爾雅曰。執衽謂之袺。毛傳同。"}]},"褿":{"expl":"帴也。从衣曹聲。","rad":"衣","fq":"昨牢切","vol":"08","py":"cáo","duan":[{"e":"帴也。","n":"巾部曰。帴、帬也。一曰祓也。一曰婦人脅衣。"}]},"裝":{"expl":"裹也。从衣壯聲。","rad":"衣","fq":"側羊切","vol":"08","py":"zhuānɡ","duan":[{"e":"裹也。","n":"束其外曰裝。故著絮於衣亦曰裝。"}]},"裹":{"expl":"纏也。从衣果聲。","rad":"衣","fq":"古火切","vol":"08","py":"ɡuǒ","duan":[{"e":"纏也。","n":"纏者、繞也。"}]},"裛":{"expl":"書囊也。从衣邑聲。","rad":"衣","fq":"於業切","vol":"08","py":"yè","duan":[{"e":"纏也。","n":"各本作書囊也。今依西都賦琴賦注、後漢書班固傳注所引正。巾部曰。帙、書衣也。帙亦作袠。廣雅。裛謂之袠。今本殆據廣雅改耳。若依今本則當云帙也。"}]},"𪗋":{"expl":"緶也。从衣齊聲。","rad":"衣","fq":"卽夷切","vol":"08","py":"zī","duan":[{"e":"緶也。裳下緝。","n":"各本無裳下緝三字。今依韵會補。依釋名當作緝下。緝下、橫縫緝其下也。綆者、緁衣也。緝同緁。漢時通用。論語鄉黨孔注曰。衣下曰齊。玉藻。縫𪗋倍要。正義曰。𪗋謂裳之下畔。深衣。下𪗋如權衡以應平。注曰。𪗋、緝也。禮喪服疏衰裳齊疏云。衰裳旣就。乃始緝之。故言齊在衰裳下。不比言斬在衰上也。按經傳多假齊爲之。亦省作𪗋。"}]},"莦":{"expl":"惡艸皃。从艸肖聲。","rad":"艸","fq":"所交切","vol":"01","py":"shāo","duan":[{"e":"惡艸皃。从艸。肖聲。","n":"所交切。二部。"}]},"裋":{"expl":"豎使布長襦。从衣豆聲。","rad":"衣","fq":"常句切","vol":"08","py":"shù","duan":[{"e":"豎使布長襦。","n":"豎與裋㬪韵。豎使謂僮豎也。淮南高注曰。豎、小使也。顏注貢禹傳曰。裋褐謂僮豎所著布長襦也。方言曰。襜褕、其短者謂之裋褕。韋昭注王命論云。裋謂短襦也。本方言。"}]},"䙔":{"expl":"編枲衣。从衣區聲。一曰頭䙔。一曰㳄裹衣。","rad":"衣","fq":"於武切","vol":"08","py":"yǔ","duan":[{"e":"編枲衣。","n":"謂取未績之麻編之爲衣。與艸雨衣相類。衣之至賤者也。"}]},"褐":{"expl":"編枲韤。一曰粗衣。从衣曷聲。","rad":"衣","fq":"胡葛切","vol":"08","py":"hè","duan":[{"e":"編枲韤。","n":"取未績之麻編之爲足衣。如今艸鞵之類。"}]},"褗":{"expl":"䙔領也。从衣匽聲。","rad":"衣","fq":"於幰切","vol":"08","py":"yǎn","duan":[{"e":"褗領也。","n":"三字句。褗領各本譌䙔領。字之誤也。今正。方言曰。衱謂之褗。郭曰。卽衣領也。戴先生云。衱卽玉藻、深衣、曲禮之袷字。交領也。爾雅。黼領謂之襮。孫炎曰。繡刺黼文以褗領也。士昏禮注。卿大夫之妻刺黼以爲領。如今偃領矣。偃卽褗字。褗領古有此語。廣韵曰。褗、衣領也。"}]},"裺":{"expl":"褗謂之裺。从衣奄聲。","rad":"衣","fq":"依檢切","vol":"08","py":"yǎn","duan":[{"e":"褗謂之裺。","n":"葢奄覆之義。方言曰。裺謂之襦。又曰。懸裺謂之緣。又曰。繞循謂之？裺。皆不與許同。"}]},"衰":{"expl":"艸雨衣。秦謂之萆。从衣，象形。","rad":"衣","fq":"穌禾切","vol":"08","py":"suō","duan":[{"e":"艸雨衣。","n":"雨衣有不艸者。左傳。成子衣製杖戈。杜曰。製、雨衣。按言製則非艸爲。若今油布衣。"}]},"卒":{"expl":"隸人給事者衣爲卒。卒，衣有題識者。","rad":"衣","fq":"臧沒切","vol":"08","py":"zú","duan":[{"e":"𣜩人給事者爲卒。","n":"俗本者下有衣字。宋本及御覽、韵會、玉篇皆無。此謂人也。非謂衣也。方言。楚東海之閒亭父謂之亭公。卒謂之弩父。或謂之褚。注曰。卒者、主擔幔弩導幨。因名。"}]},"褚":{"expl":"卒也。从衣者聲。一曰製衣。","rad":"衣","fq":"丑呂切","vol":"08","py":"chǔ","duan":[{"e":"卒也。","n":"方言云。卒或謂之褚是也。郭云。言衣赤褚。音赭。"}]},"製":{"expl":"裁也。从衣从制。","rad":"衣","fq":"征例切","vol":"08","py":"zhì","duan":[{"e":"裁衣也。从衣。制聲。","n":"征例切。十五部。按此篆處非其次。當本在裁篆之下。"}]},"袚":{"expl":"蠻夷衣。从衣犮聲。一曰蔽厀。","rad":"衣","fq":"北末切","vol":"08","py":"bō","duan":[{"e":"蠻夷衣。","n":"左衽衣。"}]},"芮":{"expl":"芮芮，艸生皃。从艸内聲。讀若汭。","rad":"艸","fq":"而銳切","vol":"01","py":"ruì","duan":[{"e":"芮芮、","n":"㬪字。"}]},"襚":{"expl":"衣死人也。从衣遂聲。《春秋傳》曰：“楚使公親襚。”","rad":"衣","fq":"徐醉切","vol":"08","py":"suì","duan":[{"e":"衣死人也。","n":"士喪禮。君使人襚。注。襚之言遺也。公羊傳曰。車馬曰？。貨財曰賻。衣被曰襚。注。襚猶遺也。遺是助死之禮。知生者？賻。知死者贈襚。"}]},"䘟":{"expl":"棺中縑裏。从衣、弔。讀若雕。","rad":"衣","fq":"都僚切","vol":"08","py":"diāo","duan":[{"e":"棺中縑裏也。","n":"喪大記曰。君裏棺用朱綠。用雜金鐕。大夫裏棺用玄綠。用牛骨鐕。士不綠。正義云。君用朱繒貼四面。綠繒貼四角。大夫四面玄。四角綠。士不綠。悉用玄。按如其說則當云士玄。不當云不綠也。且顔師古定本綠皆作琢。謂鐕琢繒則著於棺。則士不琢。尤爲不辭。葢綠與琢皆字之誤。古本三綠皆正作䘟。以縑裏棺曰䘟。縑幷絲繒也。君朱䘟。以三色金鐕椓著之。大夫玄䘟。以牛骨鐕椓著之。士賤。不䘟。則不用鐕。士喪禮纖悉畢載。而不言裏棺。可證也。鄭曰。鐕所以椓著裏。金部曰。鐕所以綴著物者。與鄭合。鐕與䘟皆據喪大記而言。"}]},"裞":{"expl":"贈終者衣被曰裞。从衣兌聲。","rad":"衣","fq":"輸芮切","vol":"08","py":"shuì","duan":[{"e":"贈終者衣被曰裞。从衣。兌聲。","n":"輸芮切。十五部。按此字僅見漢書朱建傳。葢襚之或字。淺人所增。非許本書所有也。"}]},"褮":{"expl":"鬼衣。从衣，熒省聲。讀若《詩》曰“葛藟縈之”。一曰若“靜女其袾”之袾。","rad":"衣","fq":"於營切","vol":"08","py":"yínɡ","duan":[{"e":"鬼衣也。","n":"鬼衣猶䰟衣。明器之屬也。鬼部曰。鬾、鬼服也。引韓詩傳鄭交甫逢二女鬾服。釋器曰。袕謂之褮。郭云。衣開孔。非許義也。"}]},"䘰":{"expl":"車溫也。从衣延聲。","rad":"衣","fq":"式連切","vol":"08","py":"shān","duan":[{"e":"車溫也。","n":"車溫玉篇作車？䘰。廣韵曰㠾䘰、牛領上衣。葢當作車溫䘰。如㠾幡、襎裷、詩傳袢延之比。皆重曡字也。今本奪一字。"}]},"褭":{"expl":"以組帶馬也。从衣从馬。","rad":"衣","fq":"奴鳥切","vol":"08","py":"niǎo","duan":[{"e":"㠯組帶馬也。","n":"百官志注曰。秦爵二十等。三曰簪褭。御駟馬者。按於本義引伸之。因以爲馬名。要褭、古之駿馬也。"}]},"袨":{"expl":"盛服也。从衣玄聲。","rad":"衣","fq":"黃絢切","vol":"08","py":"xuàn","duan":[]},"衫":{"expl":"衣也。从衣彡聲。","rad":"衣","fq":"所銜切","vol":"08","py":"shān","duan":[]},"襖":{"expl":"𧚍屬。从衣奥聲。","rad":"衣","fq":"烏皓切","vol":"08","py":"ǎo","duan":[]},"裘":{"expl":"皮衣也。从衣求聲。一曰象形，與衰同意。凡裘之屬皆从裘。","rad":"裘","fq":"巨鳩切","vol":"08","py":"qiú","duan":[{"e":"皮衣也。从衣。象形。","n":"各本作从衣求聲、一曰象形。淺人𡚶增之也。裘之制毛在外。故象毛文。"}]},"茬":{"expl":"艸皃。从艸在聲。濟北有茬平縣。","rad":"艸","fq":"仕甾切","vol":"01","py":"chí","duan":[{"e":"艸皃。从艸。在聲。","n":"仕甾切。一部。"}]},"𩱘":{"expl":"裘裏也。从裘鬲聲。讀若擊。","rad":"裘","fq":"楷革切","vol":"08","py":"kè","duan":[{"e":"𧚍裏也。","n":"表其毛而爲之裏附於革也。詩曰。羔羊之皮。素絲五它。皮言其表也。羔羊之革。素絲五緎。革言其裏也。羔羊之縫。素絲五總。合言其表裏也。其裏之所用未詳。"}]},"老":{"expl":"考也。七十曰老。从人、毛、匕。言須髮變白也。凡老之屬皆从老。","rad":"老","fq":"盧皓切","vol":"08","py":"lǎo","duan":[{"e":"考也。","n":"序曰。五曰轉注。建類一首。同意相受。考老是也。學者多不解。戴先生曰。老下云考也。考下云老也。此許氏之恉。爲異字同義舉例也。一其義類。皆謂建類一首也。互其訓詁。所謂同意相受也。考老適於許書同部。凡許書異部而彼此二篆互相釋者視此。如？窒也、窒？也、但裼也、裼但也之類。老考以曡韵爲訓。"}]},"耊":{"expl":"年八十曰耊。从老省，从至。","rad":"老","fq":"徒結切","vol":"08","py":"dié","duan":[{"e":"年八十曰耊。","n":"釋言。耊、老也。毛傳云。耊、老也。八十曰耊。按馬融注易、服䖍注左傳皆云。七十曰耊。葢耊訓老。故七十八十皆得偁也。"}]},"𦽡":{"expl":"年九十曰𦽡。从老，从蒿省。","rad":"老","fq":"莫報切","vol":"08","py":"mào","duan":[{"e":"年九十曰𦽡。","n":"今作耄。从老省、毛聲。秏今音讀蒿去聲。葢蒿聲、毛聲古可通用也。曲禮。八十九十曰耄。注云。耄惛忘。引左傳。老將知耄又及之。按其字亦作眊。亦作旄。"}]},"耆":{"expl":"老也。从老省，旨聲。","rad":"老","fq":"渠脂切","vol":"08","py":"qí","duan":[{"e":"老也。","n":"曲禮。六十曰耆。許不言者、許以耆爲七十已上之通偁也。鄭注䠶義云。耆耊皆老也。古多假借爲嗜字。又按士喪禮。士虞禮魚進鬐注。鬐、脊也。古文鬐爲耆。許書髟部無鬐字。依古文禮。故不錄今文禮之字也。徐鉉沾附。未識此意。許於禮經古文今文之字依一則廢一。"}]},"耇":{"expl":"老人面凍黎若垢。从老省，句聲。","rad":"老","fq":"古厚切","vol":"08","py":"ɡǒu","duan":[{"e":"老人面凍黎若垢。","n":"釋詁曰。耇、老、壽也。小雅毛傳曰。耇、壽也。孫炎曰。耇、面凍黎色如浮垢。老人壽徵也。儀禮注曰。耇、凍梨也。方言曰。東齊曰眉。燕代之北郊曰梨。秦晉之郊陳兖之會曰耇鮐。按方言又曰。麋黎、老也。麋黎卽卷一之眉梨。凍黎謂凍而黑色。或假梨爲之。尚書黎老作犁老。亦假借也。孫炎注本作面凍梨。見南山有臺、大誓二正義。本無如字。釋名及方言注乃云如凍梨。非也。"}]},"𦒻":{"expl":"老人面如點也。从老省，占聲。讀若耿介之耿。","rad":"老","fq":"丁念切","vol":"08","py":"diàn","duan":[{"e":"老人面如㸃處。","n":"謂老人面有黑瘢處也。㸃者、小黑也。"}]},"𦒶":{"expl":"老人行才相逮。从老省，易省，行象。讀若樹。","rad":"老","fq":"常句切","vol":"08","py":"shù","duan":[{"e":"老人行才相逮。","n":"才、僅也。今字作纔。纔相逮者、兩足僅能相及。言其行遲步小也。"}]},"壽":{"expl":"久也。从老省，𠷎聲。","rad":"老","fq":"殖酉切","vol":"08","py":"shòu","duan":[{"e":"久也。","n":"久者、從後灸之也。引伸爲長久。此用長久之義也。"}]},"考":{"expl":"老也。从老省，丂聲。","rad":"老","fq":"苦浩切","vol":"08","py":"kǎo","duan":[{"e":"老也。","n":"凡言壽考者、此字之本義也。引伸之爲成也。考槃、江漢、載芟、絲衣毛傳是也。凡禮記皇考、春秋考仲子之宫皆是也。又假借爲攷字。山有櫙弗𡔷弗考傳曰考、擊也是也。凡言考挍、考問字皆爲攷之假借也。"}]},"薈":{"expl":"艸多皃。从艸會聲。《詩》曰：“薈兮蔚兮。”","rad":"艸","fq":"烏外切","vol":"01","py":"huì","duan":[{"e":"艸多皃。","n":"引伸爲凡物㑹萃之義。"}]},"孝":{"expl":"善事父母者。从老省，从子。子承老也。","rad":"老","fq":"呼教切","vol":"08","py":"xiào","duan":[{"e":"善事父母者。","n":"禮記。孝者、畜也。順於道。不逆於倫。是之謂畜。"}]},"毛":{"expl":"眉髮之屬及獸毛也。象形。凡毛之屬皆从毛。","rad":"毛","fq":"莫袍切","vol":"08","py":"máo","duan":[{"e":"睂髮之屬及獸毛也。","n":"眉者、目上毛也。髮者、首上毛也。而者、須也。須者、而也。𦣞下之毛也。𩓾者、頰須也。頾、口上須也。及獸毛者、貴人賤畜也。"}]},"𣯍":{"expl":"毛盛也。从毛隼聲。《虞書》曰：“鳥獸𣯍髦。”","rad":"毛","fq":"而尹切","vol":"08","py":"rǔn","duan":[{"e":"毛盛也。从毛。隼聲。","n":"而尹切。又人勇切。按而尹卽玉篇之而允也。書釋文氄徐而允反。又如兖反。俗本允兖字皆譌作充。而集韵、類篇因有而融如容兩切矣。古音當在十五部。如隼之在十五十三兩部也。"}]},"㲦":{"expl":"獸豪也。从毛倝聲。","rad":"毛","fq":"侯幹切","vol":"08","py":"hàn","duan":[{"e":"獸豪也。","n":"豪者、豕鬣如筆管者也。引伸爲毛之長者之偁。㲦、古書多作翰。尙書大傳之西海之濱取白狐靑翰。鄭曰。翰、長毛也。長楊賦。藉翰林以爲主人。韋昭曰。翰、筆也。善曰。說文云毛長者曰翰。按翰當作㲦。葢說文古本有毛長者曰㲦五字。在獸豪也之下。曲禮。雞曰翰音。注。翰猶長也。其引伸之義也。"}]},"毨":{"expl":"仲秋，鳥獸毛盛，可選取以爲器用。从毛先聲。讀若選。","rad":"毛","fq":"穌典切","vol":"08","py":"xiǎn","duan":[{"e":"𨕖也。","n":"二字依韵會。"}]},"𣯩":{"expl":"以毳爲𦇧，色如虋。故謂之𣯩。虋，禾之赤苗也。从毛㒼聲。《詩》曰：“毳衣如𣯩。”","rad":"毛","fq":"莫奔切","vol":"08","py":"mén","duan":[{"e":"㠯毳爲𦇧。","n":"毳、獸細毛也。𦇧、西胡毳布也。"}]},"氊":{"expl":"撚毛也。从毛亶聲。","rad":"毛","fq":"諸延切","vol":"08","py":"zhān","duan":[{"e":"撚毛也。","n":"手部曰。撚者、蹂也。撚毛者、蹂毛成氈也。周禮掌皮曰。共其毳毛爲氈。古多假旃字。"}]},"毦":{"expl":"羽毛飾也。从毛耳聲。","rad":"毛","fq":"仍吏切","vol":"08","py":"ěr","duan":[]},"氍":{"expl":"氍毹、毾㲪，皆氊緂之屬，蓋方言也。从毛瞿聲。","rad":"毛","fq":"其俱切","vol":"08","py":"qú","duan":[]},"毹":{"expl":"氍毹也。从毛俞聲。","rad":"毛","fq":"羊朱切","vol":"08","py":"yú","duan":[]},"䓮":{"expl":"細草叢生也。从艸敄聲。","rad":"艸","fq":"莫候切","vol":"01","py":"mào","duan":[{"e":"細艸叢生也。","n":"䓮與茂音義同。廣雅曰。蓩蓩、茂也。蓩卽蓩之譌。"}]},"毾":{"expl":"毾㲪也。从毛𦐇聲。","rad":"毛","fq":"土盍切","vol":"08","py":"tà","duan":[]},"㲪":{"expl":"毾㲪也。从毛登聲。","rad":"毛","fq":"都滕切","vol":"08","py":"dēnɡ","duan":[]},"毬":{"expl":"鞠丸也。从毛求聲。","rad":"毛","fq":"巨鳩切","vol":"08","py":"qiú","duan":[]},"氅":{"expl":"析鳥羽爲旗纛之屬。从毛敞聲。","rad":"毛","fq":"昌兩切","vol":"08","py":"chǎnɡ","duan":[]},"毳":{"expl":"獸細毛也。从三毛。凡毳之屬皆从毳。","rad":"毳","fq":"此芮切","vol":"08","py":"cuì","duan":[{"e":"獸細毛也。","n":"掌皮注曰。毳毛、毛細縟者。"}]},"䩁":{"expl":"毛紛紛也。从毳非聲。","rad":"毳","fq":"甫微切","vol":"08","py":"fēi","duan":[{"e":"毛紛紛也。","n":"紛紛者、多也。非分雙聲。䩁䩁猶紛紛也。廣韵曰細毛。"}]},"尸":{"expl":"陳也。象臥之形。凡尸之屬皆从尸。","rad":"尸","fq":"式脂切","vol":"08","py":"shī","duan":[{"e":"陳也。","n":"陳當作敶。攴部曰。敶、列也。小雅祈父傳曰。尸、陳也。按凡祭祀之尸訓主。郊特牲曰。尸、陳也。注曰。此尸神象。當從主訓之。言陳非也。玉裁謂。祭祀之尸本象神而陳之。而祭者因主之。二義實相因而生也。故許但言陳。至於在牀曰屍。其字从尸从死。別爲一字。而經籍多借尸爲之。"}]},"㞟":{"expl":"偫也。从尸奠聲。","rad":"尸","fq":"堂練切","vol":"08","py":"diàn","duan":[{"e":"偫也。","n":"偫者、儲偫也。大玄假爲天地奠位之奠。"}]},"居":{"expl":"蹲也。从尸古者，居从古。","rad":"尸","fq":"九魚切","vol":"08","py":"jū","duan":[{"e":"蹲也。","n":"足部曰蹲、居也。二字爲轉注。今足部改居爲踞。又𡚶添踞篆。訓云蹲也。總由不究許書條理。㒺知古形古義耳。立部竣下亦曰居也。亦同義而譌爲偓竣也。葢俗本之紛亂如此。說文有凥、有居。凥、處也。从尸得几而止。凡今人居處字古衹作凥處。居、蹲也。凡今人蹲踞字古衹作居。廣雅釋詁二凥也一條。釋詁三踞也一條。畫然分别。曹憲曰。按說文今居字乃箕居字。近之矣。但古人有坐、有跪、有蹲、有箕踞。跪與坐皆厀著於席。而跪聳其體。坐下其𦞠。詩所謂啟處。四牡傳曰。啟、跪也。處、居也。四牡不遑啟處。采薇、出車作不遑啟居。居皆當作凥。許凥下云處也。正本毛傳引伸之爲凡凥處字也。若蹲則足底著地。而下其𦞠、聳其厀曰蹲。其字亦作竣。原壤夷俟。"}]},"㞒":{"expl":"臥息也。从尸、自。","rad":"尸","fq":"許介切","vol":"08","py":"xiè","duan":[{"e":"臥息也。","n":"西京賦、吳都賦皆用奰㞒字。說者謂作力之皃也。奰見大部。奰俗譌贔。㞒俗譌屓。又譌屭。今學者罕知其本字矣。㞒之本義爲臥息。鼻部所謂鼾也。用力者必𡔷其息。故引伸之爲作力之皃。呬、息也。音義略同。"}]},"芼":{"expl":"艸覆蔓。从艸毛聲。《詩》曰：“左右芼之。”","rad":"艸","fq":"莫抱切","vol":"01","py":"mào","duan":[{"e":"艸覆蔓。","n":"覆地曼莚。"}]},"㞕":{"expl":"動作切切也。从尸䏌聲。","rad":"尸","fq":"私列切","vol":"08","py":"xiè","duan":[{"e":"動作切切也。","n":"方言曰。㞕㞕、不安也。秦晉謂之㞕㞕。又曰。㞕、勞也。㞕、獪也。邶風。不我㞕以。毛傳曰。㞕、潔也。"}]},"展":{"expl":"轉也。从尸，𧝑省聲。","rad":"尸","fq":"知衍切","vol":"08","py":"zhǎn","duan":[{"e":"轉也。","n":"展者、未轉而將轉也。陸德明云。字林作輾。然則周南作輾轉。非古也。毛傳曰。展、誠也。方言曰。展、信也。此因展與眞音近假借。"}]},"屆":{"expl":"行不便也。一曰極也。从尸凷聲。","rad":"尸","fq":"古拜切","vol":"08","py":"jiè","duan":[{"e":"行不便也。","n":"此與艐義相近。艐、船著沙不行也。"}]},"尻":{"expl":"𦞠也。从尸九聲。","rad":"尸","fq":"苦刀切","vol":"08","py":"kāo","duan":[{"e":"𦞠也。","n":"按釋名以尻與臀別爲二。漢書。結股腳。連脽尻。每句皆合二物也。尻今俗云溝子是也。𦞠今俗云屁股是也。析言是二。統言是一。故許云尻、𦞠也。通俗文、埤蒼皆云。尻骨謂之八髎。釋名曰。尻、廖也。所在廖牢深也。"}]},"𡱂":{"expl":"髀也。从尸下丌居几。","rad":"尸","fq":"徒魂切","vol":"08","py":"tún","duan":[{"e":"髀也。","n":"髀者、股外也。此云髀者。專言股後。"}]},"㞓":{"expl":"尻也。从尸旨聲。","rad":"尸","fq":"詰利切","vol":"08","py":"qì","duan":[{"e":"凥也。从尸。㫖聲。","n":"詰利切。十五部。"}]},"尼":{"expl":"從後近之。从尸匕聲。","rad":"尸","fq":"女夷切","vol":"08","py":"ní","duan":[{"e":"從後近之。","n":"尼訓近。故古以爲親暱字。高宗肜日曰。典祀無豐于尼。釋文。尼女乙反。尸子云。不避遠尼。尼、近也。正義。釋詁云。卽、尼也。孫炎云。卽猶今也。尼、近也。郭璞引尸子。悅尼而來遠。自天寶閒衞包改經尼爲昵。開寶閒陳諤又改釋文尼爲昵。而賈氏羣經音辨所載猶未誤也。尼之本義從後近之。若尼山乃取於圩頂水澇所止。屔之假借字也。孟子。止或尼之。尼、止也。與致遠恐泥同。泥濘之假借字也。"}]},"㞚":{"expl":"從後相臿也。从尸从臿。","rad":"尸","fq":"楚洽切","vol":"08","py":"qì","duan":[{"e":"㞚㞏。","n":"二字各本無。今依全書通例補。"}]},"㞏":{"expl":"㞚㞏也。从尸乏聲。","rad":"尸","fq":"直立切","vol":"08","py":"zhé","duan":[{"e":"㞚㞏也。从尸。乏聲。","n":"直立切。七部。"}]},"𡰫":{"expl":"柔皮也。从申尸之後。尸或从又。","rad":"尸","fq":"人善切","vol":"08","py":"niǎn","duan":[{"e":"柔皮也。","n":"周禮所謂攻皮也。函人職曰。革欲其柔滑。而腛脂之。則耎。廣雅曰。㞋、弱也。是與耎音義同。"}]},"蒼":{"expl":"艸色也。从艸倉聲。","rad":"艸","fq":"七岡切","vol":"01","py":"cānɡ","duan":[{"e":"艸色也。","n":"引伸爲凡靑黑色之偁。"}]},"屒":{"expl":"伏皃。从尸辰聲。一曰屋宇。","rad":"尸","fq":"珍忍切","vol":"08","py":"zhěn","duan":[{"e":"伏皃。","n":"未聞。"}]},"屖":{"expl":"屖遟也。从尸辛聲。","rad":"尸","fq":"先稽切","vol":"08","py":"xī","duan":[{"e":"屖遟也。","n":"三字爲句。玉篇曰。屖今作栖。然則屖遟、卽陳風之棲遟也。毛傳曰。棲遟、遊息也。"}]},"屝":{"expl":"履也。从尸非聲。","rad":"尸","fq":"扶沸切","vol":"08","py":"fèi","duan":[{"e":"𡳐屬。","n":"𡳐者、屨也。足所依也。云屬者、屨之麤者曰屝也。方言曰。屝、麄𡳐也。釋名曰。齊人謂草𡳐曰屝。按喪服傳。菅屨者、菅菲也。杜注左傳曰。屝、草屨也。菲者屝之假借字。"}]},"屍":{"expl":"終主。从尸从死。","rad":"尸","fq":"式脂切","vol":"08","py":"shī","duan":[{"e":"終主也。","n":"終主者、方死無所主。以是爲主也。曲禮曰。在牀曰屍。今經傳字多作尸。同音假借也。亦尙有作屍者。"}]},"屠":{"expl":"刳也。从尸者聲。","rad":"尸","fq":"同都切","vol":"08","py":"tú","duan":[{"e":"刳也。","n":"刳、判也。"}]},"屟":{"expl":"履中薦也。从尸枼聲。","rad":"尸","fq":"穌叶切","vol":"08","py":"xiè","duan":[{"e":"𡳐之荐也。","n":"之各本作中。今依玄應所引訂。此藉於𡳐下。非同𡳐中苴也。荐者、藉也。吳宮有響屟廊。東宮舊事有絳地文𡳐屟百副。卽今婦女鞵下所施高底。其字本音他頰切。轉爲他計切。今籢匱有抽屜。本卽屟字。"}]},"屋":{"expl":"居也。从尸。尸，所主也。一曰尸，象屋形。从至。至，所至止。室、屋皆从至。","rad":"尸","fq":"烏谷切","vol":"08","py":"wū","duan":[{"e":"凥也。","n":"凥各本作居。誤。今正。凡凥處、於尸得几之字引伸。不當用蹲居字也。屋者、室之覆也。引申之凡覆於上者皆曰屋。天子車有黃屋。詩箋。屋、小帳也。"}]},"屏":{"expl":"屏蔽也。从尸幷聲。","rad":"尸","fq":"必郢切","vol":"08","py":"pínɡ","duan":[{"e":"屛、","n":"此複舉字之未刪者。"}]},"層":{"expl":"重屋也。从尸曾聲。","rad":"尸","fq":"昨稜切","vol":"08","py":"cénɡ","duan":[{"e":"重屋也。","n":"曾之言重也。曾祖、曾孫皆是也。故从曾之層爲重屋。𦒱工記。四阿重屋。注曰。重屋、複笮也。後人因之作樓。木部曰。樓、重屋也。引伸爲凡重曡之偁。古亦假增爲之。"}]},"屢":{"expl":"數也。案：今之婁字本是屢空字，此字後人所加。从尸，未詳。","rad":"尸","fq":"丘羽切","vol":"08","py":"lǚ","duan":[]},"禬":{"expl":"會福祭也。从示从會，會亦聲。《周禮》曰：“禬之祝號。”","rad":"示","fq":"古外切","vol":"01","py":"ɡuì","duan":[{"e":"會福祭也。","n":"周禮注曰。除災害曰禬。禬、𠜜去也。與許異。"}]},"葻":{"expl":"艸得風皃。从艸、風。讀若婪。","rad":"艸","fq":"盧含切","vol":"01","py":"lán","duan":[{"e":"艸得風皃。从艸風。風亦聲。讀若婪。","n":"盧含切。古音在七部。"}]},"尺":{"expl":"十寸也。人手卻十分動脈爲寸口。十寸爲尺。尺，所以指尺䂓榘事也。从尸从乙。乙，所識也。周制，寸、尺、咫、尋、常、仞諸度量，皆以人之體爲法。凡尺之屬皆从尺。","rad":"尺","fq":"昌石切","vol":"08","py":"chǐ","duan":[{"e":"十寸也。","n":"寸、十分也。禾部曰。十髮爲程。一程爲分。十分爲寸。又曰。律數十二。十二禾秒而當一分。十分而寸。漢志曰。九十分黃鍾之長。一爲一分。十分爲寸。十寸爲尺。十尺爲丈。十丈爲引。而五度審矣。"}]},"咫":{"expl":"中婦人手長八寸，謂之咫。周尺也。从尺只聲。","rad":"尺","fq":"諸氏切","vol":"08","py":"zhǐ","duan":[{"e":"中婦人手長八寸謂之咫。","n":"賈逵韋昭注國語、杜預注左傳說皆同。案咫之言猶近也。晉語。吾不能行也咫。楚語。是知天咫。周書大子晉。視道如咫。"}]},"尾":{"expl":"微也。从到毛在尸後。古人或飾系尾，西南夷亦然。凡尾之屬皆从尾。(今隸變作尾。)","rad":"尾","fq":"無斐切","vol":"08","py":"wěi","duan":[{"e":"微也。","n":"微當作𢼸。𢼸、細也。此以㬪韵爲訓。如門捫也、戸護也之例。方言曰。尾、盡也。尾、梢也。引伸訓爲後。如晉語歲之二七。其靡有微兮。古亦叚微爲尾。"}]},"屬":{"expl":"連也。从尾蜀聲。","rad":"尾","fq":"之欲切","vol":"08","py":"zhǔ","duan":[{"e":"連也。","n":"連者、負車也。今字以爲聯字。屬、今韵分之欲市玉二切。其義實通也。凡異而同者曰屬。鄭注司徒序官云。州黨族閭此者、鄉之屬別。注司市云。介次市亭之屬別小者也。凡言屬而別在其中。如秔曰稻屬、秏曰稻屬是也。言別而屬在其中。如稗曰禾別是也。"}]},"屈":{"expl":"無尾也。从尾出聲。","rad":"尾","fq":"九勿切","vol":"08","py":"qū","duan":[{"e":"無尾也。","n":"韓非子曰。鳥有翢。翢者、重首而屈尾。高注淮南云。屈讀如秋雞無尾屈之屈。郭注方言隆屈云。屈尾。淮南屈奇之服。許注云。屈、短也。奇、長也。凡短尾曰屈。玉篇巨律切。玄應書、廣韵衢勿切。今俗語尙如是。引伸爲凡短之偁。山短高曰崛。其類也。今人屈伸字古作詘申。不用屈字。此古今字之異也。鈍筆曰掘筆。短頭船曰撅頭。皆字之假借也。"}]},"尿":{"expl":"人小便也。从尾从水。","rad":"尾","fq":"奴弔切","vol":"08","py":"niào","duan":[{"e":"人小𠊳也。从尾水。","n":"會意。古書多假溺爲之。奴弔切。二部。"}]},"履":{"expl":"足所依也。从尸从彳从夊，舟象履形。一曰尸聲。凡履之屬皆从履。","rad":"履","fq":"良止切","vol":"08","py":"lǚ","duan":[{"e":"足所依也。","n":"𡳐依㬪韵。古曰屨。今曰𡳐。古曰𡳐。今曰鞵。名之隨時不同者也。引伸之訓踐。如君子所𡳐是也。又引伸之訓祿。詩福𡳐綏之。毛傳曰。𡳐、祿也。又引伸之訓禮。序封傳、詩長髮傳是也。𡳐禮爲㬪韵。𡳐祿爲雙聲。"}]},"屨":{"expl":"履也。从履省，婁聲。一曰鞮也。","rad":"履","fq":"九遇切","vol":"08","py":"jù","duan":[{"e":"𡳐也。","n":"晉蔡謨曰。今時所謂𡳐者、自漢以前皆名屨。左傳。踴貴屨賤。不言𡳐賤。禮記。戸外有二屨。不言二𡳐。賈𧧼曰。冠雖敝。不以苴𡳐。亦不言苴屨。詩曰。糾糾葛屨。可以𡳐霜。屨、舄者一物之別名。𡳐者足踐之通稱。按蔡說極精。易、詩三禮、春秋傳、孟子皆言屨。不言𡳐。周末諸子、漢人書乃言𡳐。詩、易凡三𡳐。皆謂踐也。然則𡳐本訓踐。後以爲屨名。古今語異耳。許以今釋古。故云古之屨卽今之𡳐也。周禮屨人。掌爲舄屨。鄭云。複下曰舄。禪下曰屨。古人言屨以通於複。今世言屨以通於禪。俗易語反與。方言。屝屨麤𡳐也。𡳐其通語也。"}]},"𡳸":{"expl":"履下也。从履省，歴聲。","rad":"履","fq":"郎擊切","vol":"08","py":"lì","duan":[{"e":"𡳐下也。","n":"謂𡳐之之底也。行地經歷者。今人言𡳐歷當用此字。"}]},"𡱣":{"expl":"履屬。从履省，予聲。","rad":"履","fq":"徐呂切","vol":"08","py":"xù","duan":[{"e":"𡳐屬。从𡳐省。予聲。","n":"徐吕切。五部。廣韵徐預切。"}]},"萃":{"expl":"艸皃。从艸卒聲。讀若瘁。","rad":"艸","fq":"秦醉切","vol":"01","py":"cuì","duan":[{"e":"艸皃。","n":"易彖傳曰。萃、聚也。此引伸之義。"}]},"屩":{"expl":"屐也。从履省，喬聲。","rad":"履","fq":"居勺切","vol":"08","py":"juē","duan":[{"e":"𡳐也。","n":"𡳐大徐作屐。非也。今依小徐。史記孟嘗君傳躡屩。虞𨜮傳及漢書王裦傳作蹻。假借字也。釋名曰。屩、蹻也。出行著之。蹻蹻輕𠊳。因以爲名。應劭曰。木蹻。臣瓚曰。以繩爲屩。徐廣曰。蹻、草𡳐也。按屩葢輕𠊳可遠行之𡳐。非法服之𡳐也。臣瓚、徐廣說是。"}]},"屐":{"expl":"屩也。从履省，支聲。","rad":"履","fq":"奇逆切","vol":"08","py":"jī","duan":[{"e":"屩也。从𡳐省。支聲。","n":"奇逆反。古音在十六部。按釋名云。屐、搘也。爲兩足搘以踐泥也。又云。屩、不可踐泥也。屐、踐泥者也。然則屐與屩有別。"}]},"舟":{"expl":"船也。古者，共鼓、貨狄，刳木爲舟，剡木爲楫，以濟不通。象形。凡舟之屬皆从舟。","rad":"舟","fq":"職流切","vol":"08","py":"zhōu","duan":[{"e":"船也。","n":"邶風。方之舟之。傳曰。舟、船也。古人言舟。漢人言船。毛以今語釋古。故云舟卽今之船也。不傳於柏舟而傳於此者、以見方之爲泭而非船也。"}]},"俞":{"expl":"空中木爲舟也。从亼从舟从巜。巜，水也。","rad":"舟","fq":"羊朱切","vol":"08","py":"yú","duan":[{"e":"空中木爲舟也。","n":"淮南氾論訓。古者爲窬木方版以爲舟航。高曰。窬、空也。方、並也。舟相連爲航也。按窬同兪。空中木者、舟之始。並板者、航之始。如椎輪爲大路之始。其始見本空之木用爲舟。其後因刳木以爲舟。凡穿窬廁牏皆取義於兪。中孚傳曰。利涉大川。乘木舟虛也。"}]},"船":{"expl":"舟也。从舟，鉛省聲。","rad":"舟","fq":"食川切","vol":"08","py":"chuán","duan":[{"e":"舟也。","n":"二篆爲轉注。古言舟、今言船。如古言屨。今言鞋。舟之言周旋也。船之言𣴔沿也。"}]},"䑣":{"expl":"船行也。从舟彡聲。","rad":"舟","fq":"丑林切","vol":"08","py":"chēn","duan":[{"e":"船行也。","n":"夏曰復胙。商曰肜。周曰繹。卽此字。取舟行延長之意也。其音以戎切。其字毛詩箋作融。"}]},"舳":{"expl":"艫也。从舟由聲。漢律名船方長爲舳艫。一曰舟尾。","rad":"舟","fq":"直六切","vol":"08","py":"zhú","duan":[{"e":"舳艫也。","n":"各本艫上𠜂舳字。今補。引三字爲句。非以艫釋舳也。韵會所據本不誤。"}]},"艫":{"expl":"舳艫也。一曰船頭。从舟盧聲。","rad":"舟","fq":"洛乎切","vol":"08","py":"lú","duan":[{"e":"舳艫也。","n":"此二字不分析之說也。"}]},"𦨉":{"expl":"船行不安也。从舟，从刖省。讀若兀。","rad":"舟","fq":"五忽切","vol":"08","py":"wù","duan":[{"e":"船行不安也。","n":"方言說舟曰。儰謂之扤。扤、不安也。郭云。儰音訛。船動搖之皃也。扤吾㪍反。按𦨉者、正字。扤者、假借字也。書阢隉、易臲𡰈皆不安也。"}]},"艐":{"expl":"船著不行也。从舟㚇聲。讀若䔂。","rad":"舟","fq":"子紅切","vol":"08","py":"zōnɡ","duan":[{"e":"船箸沙不行也。","n":"沙字各本奪。今依廣韵一東、三十三箇所引補。大人賦張揖注曰。艐、箸也。尸部屆、行不𠊳也。郭注方言云。艐古屆字。按釋詁、方言皆曰。艐、至也。不行之義之引伸也。"}]},"蒔":{"expl":"更別種。从艸時聲。","rad":"艸","fq":"時吏切","vol":"01","py":"shì","duan":[{"e":"更別種。","n":"方言曰蒔、立也。蒔、更也。堯典。播時百穀。鄭讀時爲蒔。今江蘇人移秧插田中曰蒔秧。"}]},"朕":{"expl":"我也。闕。","rad":"舟","fq":"直禁切","vol":"08","py":"zhèn","duan":[{"e":"我也。闕。","n":"此說解旣闕。而𡚶人補我也二字。未知許說字之例也。按朕在舟部。其解當曰舟縫也。从舟、灷聲。何以知爲舟縫也。考工記函人曰。視其朕。欲其直也。戴先生曰。舟之縫理曰朕。故札續之縫亦謂之朕。所以補許書之佚文也。本訓舟縫。引伸爲凡縫之偁。凡言朕兆者、謂其幾甚微。如舟之縫、如龜之{土+𢇛}也。目部瞽字下云。目但有朕也。謂目但有縫也。釋詁曰。朕、我也。此如卬吾台余之爲我、皆取其音。不取其義。趙高之於二世。乃曰天子所以貴者、但以聞聲。羣臣莫得見其面。故號曰朕。比傳朕字本義而言之。遂以亡國。凡說文字不得其理者。害必及於天下。趙高、王安石是也。云从舟灷聲者、人部𠈪字亦云灷聲。今說文雖無灷字。然論例當有之。凡勝騰滕螣"}]},"舫":{"expl":"船師也。《明堂月令》曰“舫人”。習水者。从舟方聲。","rad":"舟","fq":"甫妄切","vol":"08","py":"fǎnɡ","duan":[{"e":"船也。","n":"各本作船師也。今依韵會所據本。舫衹訓船。舫人乃訓習水者。觀張揖之訓榜人、可得其理矣。篇、韵皆曰。並兩船。是認船爲方也。舫行而方之本義廢矣。舫之本義亦廢矣。爾雅釋言曰。舫、舟也。其字作舫不誤。又曰。舫、泭也。其字當作方。俗本作舫。釋水。大夫方舟。亦或作舫。則與毛詩方泭也不相應。愚嘗謂爾雅一書多俗字。與古經不相應。由習之者多率肊改之也。"}]},"般":{"expl":"辟也。象舟之旋，从舟。从殳，殳，所以旋也。","rad":"舟","fq":"北潘切","vol":"08","py":"pán","duan":[{"e":"辟也。","n":"人部僻下曰。辟也。此辟字義同。投壺曰。賓再拜受。主人般旋曰。辟。主人阼階上拜送。賓般旋曰。辟。般干反。還音旋。辟、徐扶亦反。論語包氏注。足躩如、盤辟皃也。盤當作般。般辟、漢人語。謂退縮旋轉之皃也。大射儀賓辟注曰。辟、逡遁不敢當盛。釋言曰。般、還也。還者今之環字。旋也。荀爽注易曰。盤桓者、動而退也。般之本義如是。引伸爲般遊、般樂。"}]},"服":{"expl":"用也。一曰車右騑，所以舟旋。从舟𠬝聲。","rad":"舟","fq":"房六切","vol":"08","py":"fú","duan":[{"e":"用也。","n":"關雎箋曰。服、事也。"}]},"舸":{"expl":"舟也。从舟可聲。","rad":"舟","fq":"古我切","vol":"08","py":"ɡě","duan":[]},"艇":{"expl":"小舟也。从舟廷聲。","rad":"舟","fq":"徒鼎切","vol":"08","py":"tǐnɡ","duan":[]},"艅":{"expl":"艅艎，舟名。从舟余聲。經典通用餘皇。","rad":"舟","fq":"以諸切","vol":"08","py":"yú","duan":[]},"艎":{"expl":"艅艎也。从舟皇聲。","rad":"舟","fq":"胡光切","vol":"08","py":"huánɡ","duan":[]},"方":{"expl":"併船也。象兩舟省、緫頭形。凡方之屬皆从方。","rad":"方","fq":"府良切","vol":"08","py":"fānɡ","duan":[{"e":"倂船也。","n":"周南。不可方思。邶風。方之舟之。釋言及毛傳皆曰。方、泭也。今爾雅改方爲舫。非其義矣。倂船者、並兩船爲一。釋水曰。大夫方舟。謂倂兩船也。泭者、編木以爲渡。與倂船異事。何以毛公釋方、不曰倂船而曰泭也。曰倂船、編木其用略同。故俱得名方。方舟爲大夫之禮。詩所言不必大夫。則釋以泭可矣。若許說字。則見下从舟省而上有竝頭之象。故知倂船爲本義。編木爲引伸之義。又引伸之爲比方。子貢方人是也。秦風。西夫之防。毛曰。防、比也。謂防卽方之假借也。又引伸之爲方圓、爲方正、爲方向。又假借爲旁。丄部曰。旁、溥也。凡今文尙書作旁者、古文尙書作方。爲大也。生民。實方實苞。毛曰。方、極畝也。極畝、大之意也。又假借爲甫。召南。維鳩"}]},"𣃚":{"expl":"方舟也。从方亢聲。《禮》：天子造舟，諸矦維舟，大夫方舟，士特舟。","rad":"方","fq":"胡郎切","vol":"08","py":"hánɡ","duan":[{"e":"方舟也。","n":"舟字葢衍。衞風。一葦杭之。毛曰。杭、渡也。杭卽𣃚字。詩謂一葦可以爲之舟也。舟所以渡。故謂渡爲𣃚。始皇臨浙江。水波惡。乃西百二十里從狹中渡。其地因有餘杭縣。杜篤論都賦。造舟於渭。北杭涇流。章懷後漢書作北𣃚。注云。說文𣃚字在方部。今流俗不解。遂與杭字相亂者、誤也。是說誠然。然𣃚之作杭久矣。章懷偶一正之。而不能盡正也。李南傳。向度宛陵浦里。𣃚馬踠足。亦係章懷改杭爲𣃚。而地理、郡國二志餘杭縣未之或改也。𣃚亦作舫。方言曰。舟或謂之航。杭者說文或抗字。"}]},"苗":{"expl":"艸生於田者。从艸从田。","rad":"艸","fq":"武鑣切","vol":"01","py":"miáo","duan":[{"e":"艸生於田者。从艸田。","n":"武鑣切。二部。按苗之故訓禾也。禾者、今之小米。詩。誕降嘉穀。維秬維秠。維虋維芑。爾雅、毛傳、說文皆曰虋、赤苗。芑、白苗。魏風。無食我苗。毛曰。苗、嘉榖也。此本生民詩。首章言黍。二章言麥。三章則言禾。春秋經莊七年。秋、大水。無麥苗。卄八年。冬、大無麥禾。麥苗卽麥禾。秋言苗。冬言禾。何休曰。苗者、禾也。生曰苗。秀曰禾。倉頡篇曰。苗者、禾之未秀者也。孔子曰。惡莠恐其亂苗。魏文矦曰。幽莠似禾。明禾與苗同物。苗本禾未秀之名。因以爲凡艸木初生之名。詩言稷之苗。稷之穗、稷之實、是也。說文立文當以苗字次虋字之前。云禾也。嘉榖也。則虋爲赤苗。籒文芑爲白苗。言之有序。艸生於田。皮傅字形爲說而已。○古或假苗爲茅。如"}]},"儿":{"expl":"仁人也。古文奇字人也。象形。孔子曰：“在人下，故詰屈。”凡儿之屬皆从儿。","rad":"儿","fq":"如鄰切","vol":"08","py":"rén","duan":[{"e":"古文奇字<人>也。","n":"此冡人部而言。<人>者、天地之性冣貴者也。此籒文象臂脛之形。其作<儿>者、則古文奇字之<人>也。如<大>下曰天大地大人亦大。故<大>象人形。古文<亣>也。<亣>下曰。籒文<大>。則例正同。<亣>與<儿>之義已見於<大>與<人>之下。故皆不必㪅言其義。今俗本古文奇字之上𡚶添仁人也二字。是爲蛇足。同字而必異部者、異其从之之字也。"}]},"兀":{"expl":"高而上平也。从一在人上。讀若敻。茂陵有兀桑里。","rad":"儿","fq":"五忽切","vol":"08","py":"wù","duan":[{"e":"高而上平也。从一在儿上。","n":"儿各本作人。今正。一在儿上。高而平之意也。凡从兀聲之字多取孤高之意。"}]},"兒":{"expl":"孺子也。从儿，象小兒頭囟未合。","rad":"儿","fq":"汝移切","vol":"08","py":"ér","duan":[{"e":"孺子也。","n":"子部曰。孺、乳子也。乳子、乳下子也。襍記謂之嬰兒。女部謂之嫛婗。兒孺雙聲。引伸爲凡幼小之偁。"}]},"允":{"expl":"信也。从儿㠯聲。","rad":"儿","fq":"樂準切","vol":"08","py":"yǔn","duan":[{"e":"信也。","n":"釋詁、毛傳皆曰。允、信也。詩仲允、漢表作中術。"}]},"兌":{"expl":"說也。从儿㕣聲。","rad":"儿","fq":"大外切","vol":"08","py":"duì","duan":[{"e":"說也。","n":"說者今之悅字。其義見易。大雅。行道兌矣。傳曰。兌成蹊也。松柏斯兌。傳曰。兌、易直也。此引伸之義。老子。塞其兌。閉其門。借爲閱字。閱同穴。"}]},"充":{"expl":"長也。高也。从儿，育省聲。","rad":"儿","fq":"昌終切","vol":"08","py":"chōnɡ","duan":[{"e":"長也。高也。","n":"廣韵曰。美也。塞也。行也。滿也。"}]},"兄":{"expl":"長也。从儿从口。凡兄之屬皆从兄。","rad":"兄","fq":"許榮切","vol":"08","py":"xiōnɡ","duan":[{"e":"長也。","n":"古長不分平上。其音義一也。長短、滋長、長幼皆無二義。兄之爲長。以曡韵爲訓也。小雅。兄也永歎。傳曰。兄、茲也。大雅。倉兄塡兮。傳曰。兄、滋也。職兄斯引。職兄斯弘。傳曰。兄、茲也。又小雅。僕夫兄瘁。箋云。兄、茲也。又大雅。亂兄斯削。箋云。而亂茲甚。茲與滋義同。茲者、草木多益也。滋者、益也。凡此等、毛詩本皆作兄。俗人乃改作从水之況。又譌作况。陸氏音義不能諟正畫一。正僞錯出。且於常棣云作兄者非。由未知茲益乃兄之本義故耳。兄之本義訓益。許所謂長也。許不云茲者、許意言長則可晐長幼之義也。矢部矤下曰。兄䛐也。謂加益之䛐。此滋長之義也。無逸。無皇曰。今文尙書作毋兄曰。王肅本皇作況。注曰況滋。韋昭注國語云。況、"}]},"𠓆":{"expl":"競也。从二兄。二兄，競意。从丯聲。讀若矜。一曰兢，敬也。","rad":"兄","fq":"居陵切","vol":"08","py":"jīnɡ","duan":[{"e":"競也。","n":"競者、彊語也。小雅無羊傳曰。矝矝兢兢、以言堅彊也。釋文此義其冰反。"}]},"兂":{"expl":"首笄也。从人，匕象簪形。凡兂之屬皆从兂。","rad":"兂","fq":"側岑切","vol":"08","py":"zēn","duan":[{"e":"首筓也。","n":"竹部曰。筓、簪也。二字爲轉注。古言筓。漢言兂。此謂今之兂卽古之筓也。古經無簪字。惟易豫九四。朋盇簪。鄭云。速也。實寁之假借字。張揖古今字詁、𢈻作撍。埤蒼云。撍、疾也。寁𢈻撍同字。京作撍。經文之簪、古無。釋爲筓者。又士喪禮。復者一人。以爵弁服簪衣于裳。注云。簪、連也。然則此實鐕之假借字。金部曰。鐕可以衣箸物者。凡經典此二簪字外、無言簪者。"}]},"兓":{"expl":"朁朁，銳意也。从二兂。","rad":"兂","fq":"子林切","vol":"08","py":"jīn","duan":[{"e":"兓兓、","n":"各本譌朁朁。今依玉篇、集韵正。"}]},"苛":{"expl":"小艸也。从艸可聲。","rad":"艸","fq":"乎哥切","vol":"01","py":"kē","duan":[{"e":"小艸也。","n":"引伸爲凡瑣碎之稱。"}]},"皃":{"expl":"頌儀也。从人，白象人面形。凡皃之屬皆从皃。","rad":"皃","fq":"莫教切","vol":"08","py":"mào","duan":[{"e":"頌儀也。","n":"頁部曰。頌、皃也。此曰皃、頌儀也。是爲轉注。頌者今之容字。必言儀者、謂頌之儀度可皃象也。凡容言其內。皃言其外。引伸之、凡得其狀曰皃。析言則容皃各有當。如叔向曰貌不道容是也。絫言則曰容貌。如動容貌斯遠暴慢是也。"}]},"覍":{"expl":"冕也。周曰覍，殷曰吁，夏曰收。从皃，象形。","rad":"皃","fq":"皮變切","vol":"08","py":"biàn","duan":[{"e":"冕也。","n":"按當云冕屬。轉寫奪屬字耳。冠下云。弁冕之總名也。云總名、則弁與冕固有分矣。冕下云。大夫以上冠也。云大夫以上冠、則士無冕可知。士有爵弁、非冕也。依禮器、則夏殷之士有冕。周之士爵弁、亦冕之亞也。周禮掌弁冕之官、但曰弁師。"}]},"𠑹":{"expl":"廱蔽也。从人，象左右皆蔽形。凡𠑹之屬皆从𠑹。讀若瞽。","rad":"𠑹","fq":"公戶切","vol":"08","py":"ɡǔ","duan":[{"e":"廱蔽也。","n":"廱當作邕。俗作壅。此字經傳罕見。音與蠱同。則亦蠱惑之意也。晉語曰。在列者獻詩。使勿兜疑。兜或當爲𠑹。韋曰。兜、惑也。"}]},"兜":{"expl":"兜鍪，首鎧也。从𠑹，从皃省。皃象人頭也。","rad":"𠑹","fq":"當侯切","vol":"08","py":"dōu","duan":[{"e":"兜鍪、","n":"逗。"}]},"先":{"expl":"前進也。从儿从之。凡先之屬皆从先。","rad":"先","fq":"穌前切","vol":"08","py":"xiān","duan":[{"e":"前進也。","n":"前當作歬。不行而進曰歬。凡言歬者緩詞。凡言先者急詞也。其爲進一也。"}]},"兟":{"expl":"進也。从二先。贊从此。闕。","rad":"先","fq":"所臻切","vol":"08","py":"shēn","duan":[{"e":"進也。","n":"五經文字儿部曰。兟色巾反。見詩。按此謂大雅甡甡其鹿也。今大雅作甡。傳曰。甡甡、衆多也。但玉篇云。𨐔、多也。亦作詵。駪{羽+先[左右]}兟甡字同是衆多之義。可作兟。據五經文字、則張參所據大雅作兟。葢並先爲衆進之意。今石刻五經文字此字已泐。而馬刻本乃誤爲{先+(先+先[左右])[上下]}。葢因宋榻糢糊而譌耳。"}]},"禿":{"expl":"無髮也。从人，上象禾粟之形，取其聲。凡禿之屬皆从禿。王育說：蒼頡出見禿人伏禾中，因以制字。未知其審。","rad":"禿","fq":"他谷切","vol":"08","py":"tū","duan":[{"e":"無髮也。","n":"喪服四制曰。禿者、不髽。明堂位注曰。齊人謂無髮爲禿楬。周禮醫師注曰。庀、頭痬。亦謂禿也。引伸之、凡不銳者曰禿。釋名曰。沐、禿皆無上皃之稱。沐者、管子云沐塗樹之枝。謂刊落之也。"}]},"𥤒":{"expl":"禿皃。从禿貴聲。","rad":"禿","fq":"杜回切","vol":"08","py":"tuí","duan":[{"e":"禿皃。","n":"周南曰。我馬虺頹。釋詁及毛傳曰。虺頹、病也。禿者、病之狀也。此與𨸏部之隤迴別。今毛詩作隤。誤字也。又小雅。維風及頹毛傳曰。頹、風之焚輪者也。與釋天同。"}]},"見":{"expl":"視也。从儿从目。凡見之屬皆从見。","rad":"見","fq":"古甸切","vol":"08","py":"jiàn","duan":[{"e":"視也。","n":"析言之有視而不見者、聽而不聞者。渾言之則視與見、聞與聽一也。耳部曰。聽、聆也。聞、知聲也。此析方之。"}]},"視":{"expl":"瞻也。从見、示。","rad":"見","fq":"神至切","vol":"08","py":"shì","duan":[{"e":"瞻也。","n":"目部曰。瞻、臨視也。視不必皆臨。則瞻與視小別矣。渾言不別也。引伸之義、凡我所爲使人見之亦曰視。士昏禮。視諸衿鞶。注曰。視乃正字。今文作示。俗誤行之。曲禮。童子常視母誑。注曰。視今之示字。小雅。視民不恌。箋云。視古示字也。按此三注一也。古作視。漢人作示。是爲古今字。示下曰。天𡍮象見吉凶、所以示人也。許書當本作視人。以㬪韵爲訓。經淺人改之耳。"}]},"蕪":{"expl":"薉也。从艸無聲。","rad":"艸","fq":"武扶切","vol":"01","py":"wú","duan":[{"e":"薉也。从艸。無聲。","n":"武扶切。五部。"}]},"䚕":{"expl":"求也。从見麗聲。讀若池。","rad":"見","fq":"郎計切","vol":"08","py":"lì","duan":[{"e":"求視也。","n":"視字各本奪。今補。求視者、求𡩡之視也。李善注吳都賦引倉頡篇曰。䚕、索視之皃也。亦作矖。"}]},"覣":{"expl":"好視也。从見委聲。","rad":"見","fq":"於爲切","vol":"08","py":"wēi","duan":[{"e":"好視也。","n":"和好之視也。"}]},"𧡎":{"expl":"㫄視也。从見兒聲。","rad":"見","fq":"五計切","vol":"08","py":"nì","duan":[{"e":"旁視也。","n":"目部曰。睨、衺視也。二字音義皆同。"}]},"覶":{"expl":"好視也。从見𤔔聲。","rad":"見","fq":"洛戈切","vol":"08","py":"luó","duan":[{"e":"好視也。","n":"女部曰。𡡗、順也。覶與𡡗義近。玉篇曰。覶縷、委曲也。古書亦作覼縷。詳言之意。"}]},"䚄":{"expl":"笑視也。从見录聲。","rad":"見","fq":"力玉切","vol":"08","py":"lù","duan":[{"e":"笑視也。","n":"嬉笑之視也。目部曰。睩、目睞謹也。廣韵曰。䚄、眼曲䚄也。"}]},"𧡩":{"expl":"大視也。从見爰聲。","rad":"見","fq":"況晚切","vol":"08","py":"xuǎn","duan":[{"e":"大視也。","n":"目部曰。䁔、大目也。故𧡩爲大視。"}]},"覝":{"expl":"察視也。从見㶣聲。讀若鎌。","rad":"見","fq":"力鹽切","vol":"08","py":"lián","duan":[{"e":"察視也。","n":"密察之視也。高帝紀廉問。師古注曰。廉、察也。字本作覝。其音同耳。按史所謂廉察皆當作覝。廉行而覝廢矣。"}]},"䚋":{"expl":"外博眾多視也。从見員聲。讀若運。","rad":"見","fq":"王問切","vol":"08","py":"yùn","duan":[{"e":"外博眾視也。","n":"舊視上有多字。今依廣韵𠜂。衆多之視。所視者衆也。貟、物數也。𧶀、物數紛𧶀亂也。䚋同音而義近。博、大通也。外大通而多所視也。"}]},"觀":{"expl":"諦視也。从見雚聲。","rad":"見","fq":"古玩切","vol":"08","py":"ɡuān","duan":[{"e":"諦視也。","n":"宷諦之視也。穀梁傳曰。常事曰視。非常曰觀。凡以我諦視物曰觀。使人得以諦視我亦曰觀。猶之以我見人、使人見我皆曰視。一義之轉移。本無二音也。而學者強爲分別。乃使周易一卦而平去錯出。支離殆不可讀。不亦固哉。小雅采綠傳曰。觀、多也。此亦引伸之義。物多而後可觀。故曰觀、多也。猶灌木之爲藂木也。"}]},"䙷":{"expl":"取也。从見从寸。寸，度之，亦手也。","rad":"見","fq":"多則切","vol":"08","py":"dé","duan":[{"e":"取也。从見寸。","n":"會意。多則切。一部。"}]},"薉":{"expl":"蕪也。从艸歲聲。","rad":"艸","fq":"於癈切","vol":"01","py":"huì","duan":[{"e":"蕪也。从艸。歲聲。","n":"於廢切。十五部。今作穢。"}]},"覽":{"expl":"觀也。从見、監，監亦聲。","rad":"見","fq":"盧敢切","vol":"08","py":"lǎn","duan":[{"e":"觀也。","n":"以我觀物曰覽。引伸之使物觀我亦曰覽。史記孟荀列傳。爲開第康莊之衢。高門大屋尊寵之。覽天下諸矦賓客。言齊能致天下賢士也。此覽字無讀去聲者。則觀字何必䤨析其音乎。"}]},"䚅":{"expl":"内視也。从見來聲。","rad":"見","fq":"洛代切","vol":"08","py":"lài","duan":[{"e":"內視也。","n":"史記。趙良曰。內視之謂明。於从來取意。"}]},"𧡨":{"expl":"顯也。从見是聲。","rad":"見","fq":"杜兮切","vol":"08","py":"tí","duan":[{"e":"顯也。","n":"顯當作㬎。㬎顯古今字。㬎者、衆明也。从曰中見𢇁。然則𧡨之爲言亦察及微杪也。小雅。題彼脊令。傳曰。題、視也。題者、𧡨之假借字。毛云視、許云㬎者、此葢轉寫奪字。當云㬎視。如䚕下求視、亦奪視字。察及飛鳥是爲明㬎之視。鄭箋云。題之爲言睇也。則謂題同睇。非許意。睇者、小邪視也。與題音義皆不同。"}]},"𧢄":{"expl":"目有察省見也。从見票聲。","rad":"見","fq":"方小切","vol":"08","py":"piǎo","duan":[{"e":"目有察省見也。","n":"目偶有所見也。伺者有意。𧢄者無心。今俗語尙云𧢄。與目部之瞟、音義皆同。"}]},"𧠥":{"expl":"𧠥覰，闚觀也。从見𠂔聲。","rad":"見","fq":"七四切","vol":"08","py":"cī","duan":[{"e":"𧠥覰、","n":"逗。雙聲字也。"}]},"覰":{"expl":"拘覰，未致密也。从見虘聲。","rad":"見","fq":"七句切","vol":"08","py":"qù","duan":[{"e":"𧠥覰也。","n":"三字依全書通例補。淺人𠜂之耳。覰古多假狙爲之。周禮蜡氏注曰。蜡讀如狙司之狙。狙司卽覰伺也。史、漢狙擊秦皇帝。應劭云。狙、伏伺也。方言自關而西曰𡩡。或曰狙。三倉。狙、伺也。通俗文。伏伺曰狙。是則覰狙古今字。如今本少此三字。則覰之本義隱也。"}]},"覭":{"expl":"小見也。从見冥聲。《爾雅》曰：“覭髳，弗離。”","rad":"見","fq":"莫經切","vol":"08","py":"mínɡ","duan":[{"e":"小見也。","n":"如溟之爲小雨、皆於冥取意。釋言曰。冥、幼也。"}]},"𧡪":{"expl":"内視也。从見甚聲。","rad":"見","fq":"丁含切","vol":"08","py":"dān","duan":[{"e":"內視也。","n":"𥻳釋。張壽碑。𧡪𧡪虎視。不折其節。𧡪與眈音義皆同。眈下曰視近。此曰內視。"}]},"覯":{"expl":"遇見也。从見冓聲。","rad":"見","fq":"古后切","vol":"08","py":"ɡòu","duan":[{"e":"遇見也。","n":"覯與遇㬪韵。辵部曰。遘、遇也。覯从見、則爲逢遇之見。召南草蟲曰。亦旣見止。亦旣覯止。傳曰。覯、遇也。此謂覯同遘。鄭箋云。旣覯謂已昏也。引易男女覯精。萬物化生。鄭意以覯卽見。無俟重言。毛云。遇也。實含會合之義。故引而伸之。必俟脫纓燭出。昏禮旣成。乃自信可以寧父母心。此申毛、非異毛也。鄭所據易作覯精。今皆作構。葢失之矣。"}]},"𧢦":{"expl":"注目視也。从見歸聲。","rad":"見","fq":"渠追切","vol":"08","py":"kuī","duan":[{"e":"注目視也。","n":"專注之視也。於从歸取義。"}]},"荒":{"expl":"蕪也。从艸㠩聲。一曰艸淹地也。","rad":"艸","fq":"呼光切","vol":"01","py":"huānɡ","duan":[{"e":"蕪也。","n":"荒之言尨也。故爲蕪薉。"}]},"覘":{"expl":"窺也。从見占聲。《春秋傳》曰：“公使覘之，信。”","rad":"見","fq":"救豔切","vol":"08","py":"chān","duan":[{"e":"闚視也。","n":"闚各本作窺。今依廣韵訂。左傳。公使覘之。杜曰。覘、視也。檀弓。晉人之覘宋者。鄭曰。覘、闚視也。國語。公使覘之。韋曰。覘、微視也。檀弓。我喪也斯沾。假沾爲覘。"}]},"覹":{"expl":"司也。从見微聲。","rad":"見","fq":"無非切","vol":"08","py":"wéi","duan":[{"e":"司也。","n":"司者今之伺字。許書無伺。司下當有視字。廣韵曰。矀、伺視也。於从微取意。矀同覹。"}]},"覢":{"expl":"暫見也。从見炎聲。《春秋公羊傳》曰：“覢然公子陽生。”","rad":"見","fq":"失冉切","vol":"08","py":"shǎn","duan":[{"e":"暫見也。","n":"猝乍之見也。倉頡篇云。覢覢、視皃。按與目部之睒、音義皆同。"}]},"䚔":{"expl":"暫見也。从見賓聲。","rad":"見","fq":"必刃切","vol":"08","py":"bìn","duan":[{"e":"䚔𧢜、","n":"各本佚此二字。今依全書通例補。集韵十七眞曰。䚔𧢜、暫見。"}]},"𧢜":{"expl":"䚔𧢜也。从見樊聲。讀若幡。","rad":"見","fq":"附袁切","vol":"08","py":"fán","duan":[{"e":"䚔𧢜也。从見。樊聲。讀若幡。","n":"附袁切。十四部。小徐本篆作𧢎。"}]},"𧠟":{"expl":"病人視也。从見氐聲。讀若迷。","rad":"見","fq":"莫兮切","vol":"08","py":"mí","duan":[{"e":"病人視也。从見民聲。讀若迷。","n":"按各本篆作𧠟。解作氐聲。氐聲則應讀若低。與讀若迷不協。攷廣韵十二齊曰。𧠠、病人視皃。集韵曰。𧠠𧠟二同。類篇曰。𧠟𧠠二同。集韵、類篇𧠠又民堅切。訓病視。葢古作作𧠠、民聲。讀若眠者、其音變。讀若迷者、雙聲合音也。唐人諱民。偏㫄省一畫。多似氏字。始作{氏+見[左右]}。繼又譌作𧠟。乃至正譌並存矣。今改从正體。莫兮切。古音在十一部。"}]},"𧡹":{"expl":"下視深也。从見𠧴聲。讀若攸。","rad":"見","fq":"以周切","vol":"08","py":"yóu","duan":[{"e":"下視𥥍也。","n":"曲禮曰。凡視下於帶則憂。左傳曰。單子視下言徐。按云下視㴱者、謂下視㴱窈之處。"}]},"𧡬":{"expl":"私出頭視也。从見䑣聲。讀若郴。","rad":"見","fq":"丑林切","vol":"08","py":"chēn","duan":[{"e":"私出頭視也。","n":"閃下曰。闚頭門中也。闖下曰。馬出門皃也。音義皆略同。"}]},"𧠊":{"expl":"突前也。从見、𠔼。","rad":"見","fq":"莫紅切","vol":"08","py":"mào","duan":[{"e":"突前也。","n":"前當作歬。與冡音義略同。冡重𠔼、故入𠔼部。此重突前、故入見部。"}]},"覬":{"expl":"㰟𡴘也。从見豈聲。","rad":"見","fq":"几利切","vol":"08","py":"jì","duan":[{"e":"𣢆𡴘也。","n":"欠部𣢆下曰。𣢆、𡴘也。覬𣢆𤴁韵。古多作幾。漢人或作𩥉。亦作冀。於从豈取意。豈下曰。欲也。"}]},"𦺝":{"expl":"艸亂也。从艸寍聲。杜林說：艸𦱊𦺝皃。","rad":"艸","fq":"女庚切","vol":"01","py":"nínɡ","duan":[{"e":"𦱊𦺝也。从艸。寧聲。","n":"女庚切。十一部。此二篆及解舊譌舛。今依全書通例正。"}]},"覦":{"expl":"欲也。从見俞聲。","rad":"見","fq":"羊朱切","vol":"08","py":"yú","duan":[{"e":"欲也。","n":"覦欲𤴁韵。廣韵曰。覬覦、欲得也。"}]},"䚎":{"expl":"視不明也。一曰直視。从見舂聲。","rad":"見","fq":"丑尨切","vol":"08","py":"chuānɡ","duan":[{"e":"視不朙也。","n":"此與心部憃愚也、音義同。"}]},"𧢢":{"expl":"視誤也。从見龠聲。","rad":"見","fq":"弋笑切","vol":"08","py":"yào","duan":[{"e":"視誤也。从見。龠聲。","n":"弋笑切。二部。"}]},"覺":{"expl":"寤也。从見，學省聲。一曰發也。","rad":"見","fq":"古岳切","vol":"08","py":"jué","duan":[{"e":"悟也。","n":"悟各本作寤。今正。心部曰。悟者、覺也。二字爲轉注。㝱部曰。寐覺而有言曰寤。非其義也。何注公羊、趙注孟子皆曰。覺、悟也。左傳。以覺報宴。杜曰。覺、明也。引伸之、抑傳曰覺、直也。此因覺與斠𣖀𤴁韵聲而言。又引伸之、斯干傳曰有覺、言高大也。"}]},"䚐":{"expl":"目赤也。从見，𥏼省聲。","rad":"見","fq":"才的切","vol":"08","py":"jí","duan":[{"e":"目赤也。从見。{智+于[左右]}省聲。","n":"{智+于[左右]}毛刻作智。誤。今依宋本。才的切。十六部。"}]},"靚":{"expl":"召也。从見青聲。","rad":"見","fq":"疾正切","vol":"08","py":"jìnɡ","duan":[{"e":"召也。","n":"廣雅釋言曰。令、召、靚也。曹憲云。恥敬反。亦爲靚妝之靚。似政反。恥敬、則召靚之靚也。今多云靚師僧則其字矣。廣韵曰。古奉朝請亦作此字。按史記、漢書皆作朝請。徐廣云。律、諸矦春朝曰朝、秋曰請。郭注上林賦云。靚糚、粉白黛黑也。"}]},"親":{"expl":"至也。从見亲聲。","rad":"見","fq":"七人切","vol":"08","py":"qīn","duan":[{"e":"至也。","n":"至部曰。到者、至也。到其地曰至。情意懇到曰至。父母者、情之冣至者也。故謂之親。"}]},"覲":{"expl":"諸矦秋朝曰覲，勞王事。从見堇聲。","rad":"見","fq":"渠吝切","vol":"08","py":"jìn","duan":[{"e":"諸矦秋朝曰覲。勤勞王事也。","n":"勤也二字舊奪。今補。大宗伯。以賓禮親邦國。春見曰朝。秋見曰覲。鄭曰。覲之言勤也。欲其勤王之事。按鄭與許合。㬪韵爲訓。異義。朝名。公羊說。諸矦四時見天子及相聘皆曰朝。以朝時行禮卒而相逢於路曰遇。古周禮說。春曰朝。夏曰宗。秋曰覲。冬曰遇。謹案。禮有覲經。詩曰。韓矦入覲。書曰。江漢朝宗于海。知其朝覲宗遇之禮。從周禮說。鄭駁曰。此皆有似不爲古昔覲禮。諸矦前朝皆受舍於朝。朝通名也。秋之言覲。據時所用。按此條許鄭本無異。不得云駁也。鄭目錄云。朝宗禮僃。覲遇禮省。是以亨獻不見焉。是鄭謂周禮四者、名殊禮異也。"}]},"覜":{"expl":"諸矦三年大相聘曰頫。頫，視也。从見兆聲。","rad":"見","fq":"他弔切","vol":"08","py":"tiào","duan":[{"e":"諸矦三年大相聘曰覜。","n":"王制曰。諸矦之於天子也。比年一小聘。三年一大聘。五年一朝。鄭曰。此大聘與朝。晉文霸時所制也。異義云。公羊說。諸矦比年一小聘。三年一大聘。五年一朝天子。左氏說。十二年之閒。八聘四朝。再會一盟。許愼謹案。公羊說夏制。左氏說周禮。傳曰。三代不同物。明古今異說。鄭駁之云。三年聘。五年朝。文襄之霸制。周禮大行人。各以服數來朝。其諸矦歲聘閒朝之屬。說無所出。晉文公強威諸矦耳。非所謂三代異物也。按大宗伯。時聘曰問。殷覜曰視。鄭注。殷覜、謂一服朝之歲。以朝者少。諸矦乃使𨜮以大禮衆聘焉。一服朝在元年、七年、十一年。鄭說殷覜。不用三年大聘之說。許則以周禮之覜卽三年大聘。故大行人曰。王之所以撫邦國諸矦者。歲徧存。三"}]},"覒":{"expl":"擇也。从見毛聲。讀若苗。","rad":"見","fq":"莫袍切","vol":"08","py":"máo","duan":[{"e":"擇也。","n":"玉篇引詩。左右覒之。按毛詩作芼。擇也。葢三家詩有作覒者。廣韵。邪視也。"}]},"𦱊":{"expl":"𦱊𦺝皃。从艸爭聲。","rad":"艸","fq":"側莖切","vol":"01","py":"zhēnɡ","duan":[{"e":"𦱊薴、","n":"逗。"}]},"覕":{"expl":"蔽不相見也。从見必聲。","rad":"見","fq":"莫結切","vol":"08","py":"miè","duan":[{"e":"蔽不相見也。","n":"覕之言閟也。祕也。蔽覕雙聲。"}]},"䙾":{"expl":"司人也。从見它聲。讀若馳。","rad":"見","fq":"式支切","vol":"08","py":"shī","duan":[{"e":"司人也。","n":"司者、今之伺字。釋訓曰。戚施、面柔也。郭云。戚施之疾不能仰。面柔之人常俯。似之。亦以名云。釋文云。戚施字書作𧠪䙾同。按面柔之人。不敢專輒。必伺人顏色。故云爾。但許無𧠪字。許義不必同爾雅。"}]},"𧡸":{"expl":"目蔽垢也。从見𠁁聲。讀若钙。","rad":"見","fq":"當矦切","vol":"08","py":"dōu","duan":[{"e":"目蔽垢也。","n":"目部所謂𥋚兜也。兜卽𧡸字。"}]},"覿":{"expl":"見也。从見𧸇聲。","rad":"見","fq":"徒歴切","vol":"08","py":"dí","duan":[]},"覞":{"expl":"竝視也。从二見。凡覞之屬皆从覞。","rad":"覞","fq":"弋笑切","vol":"08","py":"yào","duan":[{"e":"竝視也。","n":"廣韵曰。普視。此今義也。"}]},"𧢞":{"expl":"很視也。从覞肩聲。齊景公之勇臣有成𧢞者。","rad":"覞","fq":"苦閑切","vol":"08","py":"qiān","duan":[{"e":"很視也。","n":"很者、不聽從也。"}]},"䨳":{"expl":"見雨而比息。从覞从雨。讀若欷。","rad":"覞","fq":"虚器切","vol":"08","py":"xì","duan":[{"e":"見雨而比息。","n":"比下曰密也。密息者、謂鼻息數速也。道途遇雨急行、則息必頻喘矣。此字讀如欷。正與齂爲卧息、㞒爲卧息、呬爲息、㕧爲呻皆讀虛器切同。各本比作止。篇、韵同。或又作上。似不若宋刊、葉抄二本作比爲長。"}]},"欠":{"expl":"張口气悟也。象气从人上出之形。凡欠之屬皆从欠。","rad":"欠","fq":"去劒切","vol":"08","py":"qiàn","duan":[{"e":"張口气悟也。","n":"悟、覺也。引伸爲解散之意。口部嚏下曰。悟、解气也。鄭注周易草木皆甲宅曰。皆讀如人倦解之解。人倦解、所謂張口气悟也。謂之欠、亦謂之嚏。曲禮。君子欠伸。正義云志疲則欠。體疲則伸。通俗文曰。張口運氣謂之欠㰦。按詩願言則疐傳曰。疐、劫也。孫毓同。崔靈恩集注云。毛訓疐爲㰦。今俗人云欠欠㰦㰦是也。不作劫字。人體倦則伸。志倦則㰦。玉裁謂。許說多宗毛。許釋嚏爲悟解气。葢用毛說也。㰦音邱據切。欠㰦古有此語。今俗曰呵欠。又欠者、气不足也。故引伸爲欠少字。"}]},"欽":{"expl":"欠皃。从欠金聲。","rad":"欠","fq":"去音切","vol":"08","py":"qīn","duan":[{"e":"欠皃。","n":"凡气不足而後欠。欽者、倦而張口之皃也。引伸之、乃欿然如不足謂之欽。詩晨風。憂心欽欽。傳曰。思望之心中欽欽然。小雅。𡔷鍾欽欽。傳曰。欽欽言使人樂。進也。皆言沖虛之意。尙書欽哉。皆令其惟恐失之也。釋詁曰。欽、敬也。攷虞夏商書言欽。周書則言敬。虞夏商書皆欽敬錯見。上曰欽若昊天、下曰敬授民時。又欽哉、不曰敬哉。葢欽與敬意略同而䛐有別也。周書言敬哉、不曰欽哉。惟多方曰。有夏之民。叨懫日欽。劓割夏邑。立政。帝欽罰之。欽字兩見。某氏傳皆訓爲敬。未知合書意否。"}]},"㱍":{"expl":"欠皃。从欠䜌聲。","rad":"欠","fq":"洛官切","vol":"08","py":"luán","duan":[{"e":"欠皃。","n":"廣韵曰。迷惑不解理。此今義也。"}]},"禪":{"expl":"祭天也。从示單聲。","rad":"示","fq":"時戰切","vol":"01","py":"shàn","duan":[{"e":"祭天也。从示。單聲。","n":"凡封土爲壇。除地爲墠。古封禪字葢衹作墠。項威曰。除地爲墠。後改墠曰禪。神之矣。服虔曰。封者、增天之高。歸功於天。禪者、廣土地。應劭亦云。封爲增高。禪爲祀地。惟張晏云。天高不可及。於泰山上立封。又禪而祭之。冀近神靈也。元鼎二年紀云。望見泰一。修天文䄠。䄠卽古禪字。是可證禪亦祭天之名。但禪訓祭天。似當與祡爲伍。不當廁此。時戰切。十四部。"}]},"落":{"expl":"凡艸曰零，木曰落。从艸洛聲。","rad":"艸","fq":"盧各切","vol":"01","py":"luò","duan":[{"e":"凡艸曰零。木曰落。","n":"零爾雅音義作苓。落亦爲籬落、纏絡字。木部杝落也、糸部繯落也、是也。"}]},"欯":{"expl":"喜也。从欠吉聲。","rad":"欠","fq":"許吉切","vol":"08","py":"xì","duan":[{"e":"喜也。","n":"廣韵曰。笑也。"}]},"吹":{"expl":"出气也。从欠从口。","rad":"欠","fq":"昌垂切","vol":"08","py":"chuī","duan":[{"e":"出气也。从欠。从口。","n":"昌𡍮切。古音在十七部。按吹已見口部。宐刪此。"}]},"欨":{"expl":"吹也。一曰笑意。从欠句聲。","rad":"欠","fq":"況于切","vol":"08","py":"xū","duan":[{"e":"吹也。一曰笑意。从欠。句聲。","n":"況于切。古音在四部。"}]},"歑":{"expl":"溫吹也。从欠虖聲。","rad":"欠","fq":"虎烏切","vol":"08","py":"hū","duan":[{"e":"温吹也。","n":"與呼音同義異。"}]},"㰲":{"expl":"吹气也。从欠或聲。","rad":"欠","fq":"於六切","vol":"08","py":"yù","duan":[{"e":"吹气也。从欠。或聲。","n":"於六切。古音在一部。玉篇火麥切。是也。"}]},"歟":{"expl":"安气也。从欠與聲。","rad":"欠","fq":"以諸切","vol":"08","py":"yú","duan":[{"e":"安气也。","n":"如𧾚爲安行。𩦡爲馬行疾而徐。音同義相近也。今用爲語未之辭。亦取安舒之意。通作與。論語。與與如也。"}]},"𣣲":{"expl":"翕气也。从欠脅聲。","rad":"欠","fq":"虚業切","vol":"08","py":"xié","duan":[{"e":"翕气也。","n":"翕、合也。廣韵作𣣲氣。"}]},"歕":{"expl":"吹气也。从欠賁聲。","rad":"欠","fq":"普魂切","vol":"08","py":"pēn","duan":[{"e":"吹气也。","n":"𣣲歕與口部之吸噴、義相似而異。"}]},"歇":{"expl":"息也。一曰气越泄。从欠曷聲。","rad":"欠","fq":"許謁切","vol":"08","py":"xiē","duan":[{"e":"息也。","n":"息者、鼻息也。息之義引伸爲休息。故歇之義引伸爲止歇。"}]},"歡":{"expl":"喜樂也。从欠雚聲。","rad":"欠","fq":"呼官切","vol":"08","py":"huān","duan":[{"e":"喜樂也。从欠。雚聲。","n":"呼官切。十四部。孟子借驩爲歡。"}]},"蔽":{"expl":"蔽蔽，小艸也。从艸敝聲。","rad":"艸","fq":"必袂切","vol":"01","py":"bì","duan":[{"e":"蔽蔽、","n":"曡字。"}]},"欣":{"expl":"笑喜也。从欠斤聲。","rad":"欠","fq":"許斤切","vol":"08","py":"xīn","duan":[{"e":"𥬇喜也。","n":"言部訢下曰。喜也。義略同。按萬石君傳。僮僕訢訢如也。晉灼云。訢、許愼曰古欣字。晉所據說文似與今本不同。"}]},"弞":{"expl":"笑不壞顔曰弞。从欠，引省聲。","rad":"欠","fq":"式忍切","vol":"08","py":"shěn","duan":[{"e":"𥬇不壞顏曰𣢇。","n":"各本篆作弞。今正。𦒱廣韵。弞式忍切。𥬇不壞顏也。集韵、類篇同。今按曲禮。𥬇不至矧。注云。齒本曰矧。大𥬇則見此。然則𥬇見齒本曰矧、大𥬇也。不壞顏曰𣢇、小𥬇也。二義不當同音。淺人因己與弓略相似。𡚶合之耳。玉篇於𣢑欣二文下曰。𣢇呼來切。𥬇不壞顏也。此希馮時所據說文也。於歛歈二文之閒曰。弞式忍切。𥬇不壞顏也。此孫強、陳彭年所據誤本說文也。學者可以悟矣。廣雅。𣢇、𥬇也。楚辭吳都賦作咍。〇齒本曰矧。謂矧卽齗之假借也。大戴。高柴執親之喪。未嘗見齒。盧注曰。哂則齒見。𥬇則矧見。按論語。夫子哂之。馬曰。哂、𥬇也。葢哂卽矧。盧語未覈。說文無哂。後人因哂矧造弞耳。"}]},"款":{"expl":"意有所欲也。从欠，𡪡省。","rad":"欠","fq":"苦管切","vol":"08","py":"kuǎn","duan":[{"e":"意有所欲也。","n":"屈原賦曰。悃悃㱁㱁。王注。心志純也。按古款與窾通用。窾者、空也。款亦訓空。空中則有所欲也。釋器。款足者謂之鬲。小司馬引舊說款足謂空足也。又引申子款言無成。"}]},"𣢆":{"expl":"𡴘也。从欠气聲。一曰口不便言。","rad":"欠","fq":"居气切","vol":"08","py":"jì","duan":[{"e":"𡴘也。","n":"𡴘者、吉而免凶也。覬下曰。𣢆、𡴘也。𣢆與覬音義皆同。今字作冀。古音不同。"}]},"欲":{"expl":"貪欲也。从欠谷聲。","rad":"欠","fq":"余蜀切","vol":"08","py":"yù","duan":[{"e":"貪欲也。","n":"欲者衍字。貝部貪下云。欲也。二篆爲轉注。今貪下作欲物也。亦是淺人增字。凡此書經後人𡚶竄。葢不可數計。獨其義例精密。迄今將二千年。猶可推尋。以複其舊。是以冣目云後有達者、理而董之也。感於物而動。性之欲也。欲而當於理。則爲天理。欲而不當於理。則爲人欲。欲求適可斯已矣。非欲之外有理也。古有欲字、無慾字。後人分別之、製慾字。殊乖古義。論語申棖之欲、克伐怨欲之欲。一从心、一不从心。可徵改古者之未能畫一矣。欲从欠者、取慕液之意。从谷者、取虛受之意。易曰。君子以徵忿窒欲。陸德明曰。欲、孟作谷。晁說之曰。谷、古文欲字。晁氏所據釋文不誤。今本改爲孟作浴。非也。"}]},"歌":{"expl":"詠也。从欠哥聲。","rad":"欠","fq":"古俄切","vol":"08","py":"ɡē","duan":[{"e":"詠也。","n":"言部曰。詠、歌也。二字爲轉注。"}]},"歂":{"expl":"口气引也。从欠耑聲。讀若車輇。","rad":"欠","fq":"市緣切","vol":"08","py":"chuǎn","duan":[{"e":"口气引也。","n":"廣韵引字林同。左傳多有名歂者。"}]},"歍":{"expl":"心有所惡，若吐也。从欠烏聲。一曰口相就。","rad":"欠","fq":"哀都切","vol":"08","py":"wū","duan":[{"e":"心有所惡若吐也。","n":"心有所惡。若欲吐而實非吐也。山海經曰。其所歍所尼。郭曰。歍嘔猶噴吒。范注太玄曰。歐歍、逆吐之聲也。按此所謂喑噁。噁卽歍之或字也。喑於鴆切。噁鳥路切。喑噁言其未發也。叱吒言其已發也。太玄則歐歍之歐謂吐。歍謂欲吐未吐。"}]},"𣤶":{"expl":"歍𣤶也。从欠鼀聲。","rad":"欠","fq":"才六切","vol":"08","py":"zú","duan":[{"e":"歍𣤶也。","n":"其義已在上文。故但曰歍𣤶而已。此全書之通例。"}]},"𣢰":{"expl":"惄然也。从欠尗聲。《孟子》曰：“曾西𣢰然。”","rad":"欠","fq":"才六切","vol":"08","py":"zú","duan":[{"e":"惄然也。","n":"此以㬪韵爲訓。心部曰。惄、憂也。𣢰然心口不安之皃也。"}]},"蘀":{"expl":"艸木凡皮葉落陊地爲蘀。从艸擇聲。《詩》曰：“十月隕蘀。”","rad":"艸","fq":"它各切","vol":"01","py":"tuò","duan":[{"e":"艸木凡皮葉落陊地爲蘀。","n":"陊、落也。鍇本作墮。"}]},"欦":{"expl":"含笑也。从欠今聲。","rad":"欠","fq":"丘嚴切","vol":"08","py":"qiān","duan":[{"e":"含𥬇也。","n":"欦含㬪韵。"}]},"歋":{"expl":"人相笑相歋瘉。从欠虒聲。","rad":"欠","fq":"以支切","vol":"08","py":"yí","duan":[{"e":"人相𥬇相歋瘉。","n":"後漢書王霸傳。市人皆大𥬇。舉手邪揄之。李注。說文曰。歋𢋅、手相𥬇也。歋音弋支反。𢋅音踰。或音由。按據此注。似許書本有𢋅篆。然許本無㢏。則無从欠㢏聲之字可知。方言本無正字。不妨下字作瘉。瘉之或从歈、或作𢋅、或作揄、或作𢶖。猶歋之或作擨、或作邪、或作捓、或作搋耳。此謂人相𥬇。故字从欠。李注引手相𥬇。恐是因正文而誤。"}]},"歊":{"expl":"歊歊，气出皃。从欠、高，高亦聲。","rad":"欠","fq":"許嬌切","vol":"08","py":"xiāo","duan":[{"e":"歊歊、","n":"鍇本衹一歊。複舉字之未刪者耳。"}]},"欻":{"expl":"有所吹起。从欠炎聲。讀若忽。","rad":"欠","fq":"許物切","vol":"08","py":"xū","duan":[{"e":"有所吹起。从欠。炎聲。讀若忽。","n":"西京賦。欻從背見。薛注。欻之言忽也。按此篆久譌。从炎非聲。葢本从𠦪聲。譌而爲炎。莫能諟正。倘去聲字、說以从炎會意。亦恐非也。許勿切。十五部。"}]},"𣢑":{"expl":"𣢑𣢑，戲笑皃。从欠之聲。","rad":"欠","fq":"許其切","vol":"08","py":"xī","duan":[{"e":"𣢑𣢑、戲𥬇皃。","n":"此今之嗤𥬇字也。廣韵畫𣢑嗤爲二字。殊誤。其云嗤又作𣣷、不知皆𣢑之俗耳。文賦曰。𨿽𤂓發於巧心。或受𣢑於拙目。李善曰。𣢑、𥬇也。與嗤同。今本轉寫乖謬。"}]},"钐":{"expl":"钐钐，气出皃。从欠䍃聲。","rad":"欠","fq":"余招切","vol":"08","py":"yáo","duan":[{"e":"𣣳𣣳、气出皃。","n":"按詩君子陶陶傳曰。陶陶、和樂皃。疑正字當作𣣳。又郁陶字亦當作此。"}]},"歗":{"expl":"吟也。从欠肅聲。《詩》曰：“其歗也謌。”","rad":"欠","fq":"穌弔切","vol":"08","py":"xiào","duan":[{"e":"吹也。","n":"吹大徐作吟。"}]},"歎":{"expl":"吟也。从欠，𪅀省聲。","rad":"欠","fq":"池案切","vol":"08","py":"tàn","duan":[{"e":"吟也。謂情有所悅。吟歎而歌詠。","n":"悅當作說。謂情已下十字各本無。今依李善注盧諶覽古詩所引補。葢演說文語也。古歎與嘆義別。歎與喜樂爲類。嘆與怒哀爲類。如樂記云一唱而三歎。有遺音者矣。又云長言之不足。故嗟歎之。嗟歎之不足。故不知手之舞之。足之蹈之。論語喟然歎曰。皆是此歎字。檀弓曰戚斯嘆。嘆斯擗。詩云而無永嘆。嘅其嘆矣。愾我寤嘆。皆是嘆字。"}]},"歖":{"expl":"卒喜也。从欠从喜。","rad":"欠","fq":"許其切","vol":"08","py":"xī","duan":[{"e":"卒喜也。","n":"卒疑當作猝。"}]},"欸":{"expl":"訾也。从欠矣聲。","rad":"欠","fq":"凶戒切","vol":"08","py":"xiè","duan":[{"e":"訾也。","n":"按訾者、呰之字誤。訾者、思稱意也。呰者、訶也。分見言部、口部。玉篇。欸者、呰也。可正訾字之譌。廣韵十六怪曰。怒聲。十六咍曰。歎也。玉篇曰。恚聲。正與訶義合。口部有唉字。譍也。與欸義別。項羽本紀。亞父受玉斗。拔劒撞而破之。曰唉。孺子不足與謀。此正怒聲字。當作欸。方言。欸、然也。南楚凡言然者曰欸。或曰𧫦。此正訓譍字。當作唉。"}]},"蕰":{"expl":"積也。从艸温聲。《春秋傳》曰：“蕰利生孽。”","rad":"艸","fq":"於粉切","vol":"01","py":"yùn","duan":[{"e":"積也。","n":"左傳。芟夷薀崇。杜注。薀、積也。又蘋？薀藻之菜注。薀藻、聚藻也。小雅都人士、禮記禮運、借菀苑字爲之。"}]},"㰣":{"expl":"歐也。从欠此聲。","rad":"欠","fq":"前智切","vol":"08","py":"zì","duan":[{"e":"歐也。从欠。此聲。","n":"前智切。十五十六部。"}]},"歐":{"expl":"吐也。从欠區聲。","rad":"欠","fq":"烏后切","vol":"08","py":"ǒu","duan":[{"e":"吐也。","n":"海外經。歐絲之野。一女子跪據樹歐絲。"}]},"歔":{"expl":"欷也。从欠虚聲。一曰出气也。","rad":"欠","fq":"朽居切","vol":"08","py":"xū","duan":[{"e":"欷也。","n":"二字雙聲。"}]},"欷":{"expl":"歔也。从欠，稀省聲。","rad":"欠","fq":"香衣切","vol":"08","py":"xī","duan":[{"e":"歔也。","n":"欷亦作唏。史記。紂爲象箸而箕子唏。"}]},"歜":{"expl":"盛气怒也。从欠蜀聲。","rad":"欠","fq":"尺玉切","vol":"08","py":"chù","duan":[{"e":"盛气怒也。","n":"引伸爲凡氣盛之偁。左傳。饗有昌歜。杜注曰。昌歜、昌蒲葅也。孔氏沖遠云。相傳昌歜之音爲在感反。徧檢書傳。昌蒲之草無此別名。玉裁謂。此非草名也。乃葅名也。周禮昌本、言取其根。左傳昌歜、言昌陽氣辛香以爲菹。其氣觸鼻。故名昌歜。歜之讀在敢反者、語之轉也。𣤶與歜同在三部。音轉皆可入八部。是以玉篇云。𣤶亦徂感切。昌薄葅也。葢古本左傳有作昌𣤶者。二字可相假借。皆可讀屋沃本韵之音。非必定當在敢反也。"}]},"𣣸":{"expl":"言意也。从欠从𠧴，𠧴亦聲。讀若酉。","rad":"欠","fq":"與久切","vol":"08","py":"yǒu","duan":[{"e":"言意也。","n":"有所言之意也。意內言外之意。"}]},"㵣":{"expl":"欲歠歠。从欠渴聲。","rad":"欠","fq":"苦葛切","vol":"08","py":"kě","duan":[{"e":"欲㱃歠。从欠。渴聲。","n":"此舉形聲包會意。渴者、水盡也。音同竭。水渴則欲水。人㵣則欲飮。其意一也。今則用竭爲水渴字。用渴爲飢㵣字。而㵣字廢矣。渴之本義廢矣。晉語。忨日而㵣歲。心部引春秋。忨歲而㵣日。韋昭曰。㵣、遟也。遟讀爲遟久之遟。急待之意也。苦葛切。十五部。"}]},"㱇":{"expl":"悲意。从欠嗇聲。","rad":"欠","fq":"火力切","vol":"08","py":"xì","duan":[{"e":"悲意。","n":"意內言外之意。玄應書云。通俗文。小怖曰㱇。公羊傳㱇然而駭是也。按今公羊作色然。"}]},"𣤹":{"expl":"盡酒也。从欠𥼚聲。","rad":"欠","fq":"子肖切","vol":"08","py":"jiào","duan":[{"e":"盡酒也。","n":"此與酉部釂音義皆同。"}]},"蔫":{"expl":"菸也。从艸焉聲。","rad":"艸","fq":"於乾切","vol":"01","py":"yān","duan":[{"e":"菸也。","n":"不鮮也。"}]},"𣤭":{"expl":"監持意。口閉也。从欠緘聲。","rad":"欠","fq":"古咸切","vol":"08","py":"jiān","duan":[{"e":"堅持意。","n":"堅各本作監。今依篇、韵正。从緘者、三緘其口之意。"}]},"㰮":{"expl":"指而笑也。从欠辰聲。讀若蜃。","rad":"欠","fq":"時忍切","vol":"08","py":"shèn","duan":[{"e":"指而𥬇也。","n":"吕覽。舜爲天子。𨌈𨌈敐敐。莫不載悅。高注曰。敐敐、動而喜也。又作陳陳殷殷。無二切。皆譌字耳。敐葢卽㰮字。轉寫从攵。吳都賦。東吳王孫。辴然而咍。劉注云。辴、大𥬇皃。引莊周齊桓公辴然而𥬇。辴卽㰮字之異者。俗譌作辴。"}]},"𣤿":{"expl":"昆干，不可知也。从欠鰥聲。","rad":"欠","fq":"古渾切","vol":"08","py":"kūn","duan":[{"e":"𣤿干、","n":"逗。"}]},"歃":{"expl":"歠也。从欠臿聲。《春秋傳》曰：“歃而忘。”","rad":"欠","fq":"山洽切","vol":"08","py":"shà","duan":[{"e":"歠也。","n":"歠者、㱃也。凡盟者歃血。"}]},"欶":{"expl":"吮也。从欠束聲。","rad":"欠","fq":"所角切","vol":"08","py":"shuò","duan":[{"e":"吮也。","n":"口部曰。吮、欶也。二篆爲轉注。通俗文含吸曰欶。"}]},"歁":{"expl":"食不滿也。从欠甚聲。讀若坎。","rad":"欠","fq":"苦感切","vol":"08","py":"kǎn","duan":[{"e":"食不滿也。从欠。甚聲。讀若坎。","n":"苦感切。七部。"}]},"欿":{"expl":"欲得也。从欠臽聲。讀若貪。","rad":"欠","fq":"他含切","vol":"08","py":"kǎn","duan":[{"e":"欲得也。","n":"孟子。附之以韓魏之家。如其自視欿然。則過人遠矣。張鎰曰。欿音坎。內顧不足而有所欲也。玉裁按。孟子假欿爲坎。謂視盈若虛也。大玄。雷推欿𥨎.卽坎窞也。今本大玄欿字譌不可識。"}]},"欱":{"expl":"歠也。从欠合聲。","rad":"欠","fq":"呼合切","vol":"08","py":"hē","duan":[{"e":"歠也。","n":"欱與吸意相近。與歕爲反對。東都賦曰。欱野歕山。"}]},"歉":{"expl":"歉食不滿。从欠兼聲。","rad":"欠","fq":"苦簟切","vol":"08","py":"qiàn","duan":[{"e":"歉食不滿也。","n":"歉疑當作嗛。謂口銜食不滿也。引伸爲凡未滿之偁。穀梁傳曰。一穀不升謂之歉。古多假嗛爲歉。"}]},"䯉":{"expl":"咽中息不利也。从欠骨聲。","rad":"欠","fq":"烏八切","vol":"08","py":"wā","duan":[{"e":"咽中息不利也。","n":"玄應本作气息不利。多气字。咽者、嗌也。咽中息不利、若骾而非𩩹也。通俗文。大咽曰䯉。咽讀去聲。與許義不合。"}]},"菸":{"expl":"鬱也。从艸於聲。一曰𣨙也。","rad":"艸","fq":"央居切","vol":"01","py":"yū","duan":[{"e":"𩰪也。","n":"𩰪各本作鬱。誤。蔫菸𩰪三字雙聲。𩰪者如釀𩰪也。王風。中谷有蓷。暵其乾矣。毛曰。暵、菸皃。陸艸生於谷中。傷於水。玉裁按。暵卽蔫字之假借。故旣云暵其乾。又云暵其溼。乾溼文互相足。"}]},"欭":{"expl":"嚘也。从欠因聲。","rad":"欠","fq":"乙冀切","vol":"08","py":"yì","duan":[{"e":"嚘也。","n":"口部曰。嚘者、語未定皃。欭嚘爲雙聲。王風。中心如噎。傳曰。噎謂噎憂不能息也。（玉篇如此）噎憂卽欭嚘之假借字。不能息、謂气息不利也。鄭風傳曰。不能息、憂不能息也。憂亦卽嚘字。老子。終日號而不嗄。玉篇作不嚘。云嚘、气屰也。大玄柔兒于號。三歲不嚘。皆謂气窒𡨄不利。廣韵。喑、欭歎也。"}]},"欬":{"expl":"屰气也。从欠亥聲。","rad":"欠","fq":"苦蓋切","vol":"08","py":"kài","duan":[{"e":"屰气也。","n":"周禮疾醫。冬時有嗽上氣疾。注曰。嗽、欬也。上氣逆喘也。按嗽本亦作欶。欶者、含吸也。含吸之欲其下而气乃逆上是曰欬。許書以欶包嗽。口部無嗽。俗又作瘶。倉頡篇齊部謂瘶曰欬。"}]},"𣤢":{"expl":"且唾聲。一曰小笑。从欠毄聲。","rad":"欠","fq":"許壁切","vol":"08","py":"xì","duan":[{"e":"且唾聲。","n":"且唾者、𦕼唾也。"}]},"歙":{"expl":"縮鼻也。从欠翕聲。丹陽有歙縣。","rad":"欠","fq":"許及切","vol":"08","py":"xī","duan":[{"e":"縮鼻也。","n":"糸部曰。縮者、蹴也。歙之言攝也。"}]},"㰶":{"expl":"蹴鼻也。从欠咎聲。讀若《爾雅》曰“麔豭短脰”。","rad":"欠","fq":"於糾切","vol":"08","py":"yǒu","duan":[{"e":"蹴鼻也。","n":"蹴鼻卽縮鼻也。廣雅曰。㰶、吐也。此謂㰶卽歐之假借字。左傳。吾伏弢嘔血。杜曰。嘔、吐也。本又作𠴰。按嘔𠴰卽歐㰶字。"}]},"𣢜":{"expl":"愁皃。从欠幼聲。","rad":"欠","fq":"於虯切","vol":"08","py":"yǒu","duan":[{"e":"愁皃。从欠。幼聲。","n":"於虯切。三部。按口部云。呦之或字。篇、韵此義上聲。於糾切。"}]},"欪":{"expl":"咄欪，無慙。一曰無腸意。从欠出聲。讀若卉。","rad":"欠","fq":"丑律切","vol":"08","py":"chù","duan":[{"e":"咄欪、","n":"逗。此㬪韵。古語也。"}]},"欥":{"expl":"詮詞也。从欠从曰，曰亦聲。《詩》曰：“欥求厥寕。”","rad":"欠","fq":"余律切","vol":"08","py":"yù","duan":[{"e":"詮䛐也。","n":"詮具也。淮南詮言訓。高注曰。詮、就也。就萬物之指以言其徵。事之所謂。道之所依也。詮䛐者、凡詮解以爲䛐。如欥求厥寧、欥中和爲庶幾是也。釋言。遹、述也。毛詩悉蟀傳曰。聿、遂也。文王傳曰。聿、述也。古聿遹同字。述遂同字。爾雅言述而遂在其中。毛公或言遂、或言述。因文分別也。毛詩多言聿。獨文王有聲四言遹。而毛無傳。毛意遹卽聿。聿訓遂。故鄭箋以述別之。遂者、因事之詞。亦專䛐。韓詩及曹大家注幽通賦及杜注左傳皆云。聿、惟也。此專䛐也。欥其正字。聿、遹、曰皆其假借字也。因䛐、專䛐皆詮䛐也。"}]},"次":{"expl":"不前，不精也。从欠二聲。","rad":"欠","fq":"七四切","vol":"08","py":"cì","duan":[{"e":"不前不精也","n":"前當作歬。不歬不精皆居次之意也。"}]},"㱂":{"expl":"飢虚也。从欠康聲。","rad":"欠","fq":"苦岡切","vol":"08","py":"kānɡ","duan":[{"e":"飢虛也。","n":"飢者、餓也。漮者、水之虛。㝩者、屋之虛。㱂者、餓腹之虛。"}]},"𦾵":{"expl":"艸旋皃也。从艸榮聲。《詩》曰：“葛纍𦾵之。”","rad":"艸","fq":"於營切","vol":"01","py":"yínɡ","duan":[{"e":"艸旋皃也。","n":"𦾵與縈音義同。"}]},"欺":{"expl":"詐欺也。从欠其聲。","rad":"欠","fq":"去其切","vol":"08","py":"qī","duan":[{"e":"詐也。","n":"大徐作詐欺也。今依韵會正。言部曰詐者、欺也。此曰欺者、詐也。是爲轉注。从欠者、猶从言之意。"}]},"歆":{"expl":"神食气也。从欠音聲。","rad":"欠","fq":"許今切","vol":"08","py":"xīn","duan":[{"e":"神食气也。","n":"大雅曰。𡳐帝武敏歆。傳曰。歆、饗也。許用毛義而不云饗也者、嫌食部以鄉飲酒釋饗。故易其文神食气。故其字从欠也。引伸爲憙悅之意。皇矣。無然歆羨。傳釋爲貪羨。楚語曰。楚必歆之。賈逵曰。歆、貪也。韋曰。歆猶貪也。周語。民歆而德之。韋曰。歆猶欣欣喜服也。按鄭箋生民首章云。心體歆歆然。亦是以欣釋歆。"}]},"歈":{"expl":"歌也。从欠俞聲。《切韻》云：“巴歈，歌也。”案：《史記》：渝水之人善歌舞，漢高祖采其聲。後人因加此字。","rad":"欠","fq":"羊朱切","vol":"08","py":"yú","duan":[]},"㱃":{"expl":"歠也。从欠酓聲。凡㱃之屬皆从㱃。","rad":"㱃","fq":"於錦切","vol":"08","py":"yǐn","duan":[{"e":"歠也。","n":"易蒙封虞注曰。水流入口爲飲。引伸之、可飲之物謂之飲。如周禮四飲是也。與人飲之謂之飲。俗讀去聲。如左傳飲之酒是也。又消納無迹謂之飲。漢書朱家傳飲其德猶隱其德也。"}]},"歠":{"expl":"㱃也。从㱃省，叕聲。","rad":"㱃","fq":"昌說切","vol":"08","py":"chuò","duan":[{"e":"㱃也。","n":"二篆爲轉注。與口部啜義異。"}]},"㳄":{"expl":"慕欲口液也。从欠从水。凡㳄之屬皆从㳄。","rad":"㳄","fq":"叙連切","vol":"08","py":"xián","duan":[{"e":"慕欲口液也。","n":"有所慕欲而口生液也。故其其字从欠水。"}]},"羨":{"expl":"貪欲也。从㳄，从羑省。羑呼之羑，文王所拘羑里。","rad":"㳄","fq":"似面切","vol":"08","py":"xiàn","duan":[{"e":"貪欲也。","n":"大雅。無然歆羨。毛傳云。無是貪羨。此羨之本義也。假借爲衍字。如大雅。及爾游羨。傳曰。羨、溢也。周禮。以其餘爲羨。鄭司農云。羨、饒也。皆是。亦假借爲延字。典瑞璧羨注云。長也。玉人注云。徑也。皆由延訓長。假此爲延也。墓中道曰羨道音延。亦取㴱長之義。若江夏郡沙羨縣、音夷。則係方語。"}]},"𠩗":{"expl":"歠也。从㳄厂聲。讀若移。","rad":"㳄","fq":"以支切","vol":"08","py":"yí","duan":[{"e":"歠也。从㳄。厂聲。","n":"厂、抴也。朙也。見十二篇。"}]},"盜":{"expl":"私利物也。从㳄，㳄欲皿者。","rad":"㳄","fq":"徒到切","vol":"08","py":"dào","duan":[{"e":"厶利物也。","n":"周公曰。竊賄爲盜。盜器爲姦。米部曰。盜自中出曰竊。"}]},"旡":{"expl":"㱃食气屰不得息曰㒫。从反欠。凡㒫之屬皆从㒫。(今變隸作旡。)","rad":"旡","fq":"居未切","vol":"08","py":"jì","duan":[{"e":"㱃食屰气不得息曰兂{旡}。","n":"屰气各本作气屰。今依篇、韵正。不得息者、咽中息不利。毛傳於王、鄭皆曰嚘不得息是也。屰气、故从反欠。旡之字經傳無徵。大雅桑柔曰。如彼遡風。亦恐之僾。傳曰。僾、唈也。釋言同。箋云。使人唈然如鄉疾風不能息也。今觀許書。則知旡乃正字。僾乃假借字。凡云不得息者。如䯉字、欭字、嚘字、噎字、唈字皆雙聲像意。然則旡必讀於未切也。僾之訓仿佛見也。毛、鄭何從知其訓唈然不能息。則以有旡字在也。𠎹从𢜤聲。𢜤从㤅聲。㤅从兂{旡}聲。可得其同音假借之理矣。凡古文字之可𦒱者如此。或問釋言、毛詩傳唈字當作何字。曰此卽㒫字也。於唈、古多作邑。如史記商君傳、漢書杜鄴師丹傳可證。古音七八部。與十五部關通相假之理也。毛謂僾㒫也。此卽"}]},"蔡":{"expl":"艸也。从艸祭聲。","rad":"艸","fq":"蒼大切","vol":"01","py":"cài","duan":[{"e":"艸丯也。","n":"丯讀若介。丯字本無。今補。四篇曰。丯、艸蔡也。此曰。蔡、艸丯也。是爲轉注。艸生之散亂也。丯蔡曡韵。猶𦱊𦺝。此無丯字。則蔡當爲艸名。不廁此處矣。"}]},"旤":{"expl":"屰惡驚詞也。从㒫咼聲。讀若楚人名多夥。","rad":"旡","fq":"乎果切","vol":"08","py":"huò","duan":[{"e":"屰惡驚䛐也。","n":"玉篇無惡字。誤。遇惡驚駭之䛐曰𣄸。猶見鬼驚駭之𣄸曰𩴓也。假借爲禍字。史記、漢書多假旤爲禍。旤卽𣄸也。"}]},"𣄴":{"expl":"事有不善言𣄴也。《爾雅》：“𣄴，薄也。”从㒫京聲。","rad":"旡","fq":"力讓切","vol":"08","py":"liànɡ","duan":[{"e":"事有不譱言𣄴也。","n":"故从㒫。按水部曰。涼、薄也。紬繹上下文。乃周禮六飲之涼。當作薄酒也。𣄴則爲事有不善之言。若亮則爲朙也。諒則爲信也。四字在說文義別。而古經傳多相假。"}]},"頁":{"expl":"頭也。从𦣻从几。古文䭫首如此。凡頁之屬皆从頁。𦣻者，䭫首字也。","rad":"頁","fq":"胡結切","vol":"09","py":"xié","duan":[{"e":"頭也。从𦣻。从儿。古文䭫首如此。","n":"按此十二字葢後人所改竄。非許氏原文。原文當云。𩑋、古文䭬𩠐字如此。从𦣻。从儿。共十一字。䭬字見下文𩠐部。䭬者、小篆依常例。當於䭬下出𩑋。解云。古文䭬。而以如是立文。則从𩑋之九十三文無所附。故別出𩑋爲部首。正如儿卽古文奇字人。亣卽籒文大。而皆必別出之爲部首。云儿古文奇字人也。云亣籒文大改古文也。皆不必再釋儿字亣字𩑋字之義。後人乃於儿下贅之云仁人也。𩑋下贅之云頭也。而倒亂其文。皆由不知許氏立言之變例故爾。𩑋部不廁𩠐部後而列於前者、蒙八篇从儿之字爲次也。小篆𦣻、古文作𩠐。小篆䭬、古文作𩑋。今隷則𦣻用古文。䭬用稽字。而𦣻𩑋䭬皆不行矣。从𦣻儿爲𩑋首字。如从气儿爲欠、从目儿爲見。會意。字本與䭬同音。康禮切"}]},"頭":{"expl":"首也。从頁豆聲。","rad":"頁","fq":"度矦切","vol":"09","py":"tóu","duan":[{"e":"𦣻也。","n":"𦣻各本作𩠐。今正。小篆作𦣻。說文據小篆爲書。故敘曰今敘篆文合以古籒也。漢人多用𩠐不用𦣻者、自係一時相習而然。許造字書則有定體。𦣻下曰。頭也。頭下曰。𦣻也。是曰轉注。禮記曰。頭容直。頭頸必中。"}]},"顔":{"expl":"眉目之閒也。从頁彥聲。","rad":"頁","fq":"五姦切","vol":"09","py":"yán","duan":[{"e":"睂之閒也。","n":"各本作睂目之閒。淺人妄增字耳。今正。睂與目之間不名顔。釋言曰。猗嗟名兮。目上名。郭注云。眉眼之閒。西京賦名作眳。薛注曰。睂睫之閒。是不謂之顔也。若云㒳睂間、㒳目間。則㒳目閒已是鼻莖、謂之頞。又非顔也。面下曰。顔前也。色下曰。顔氣也。是可證顔爲眉間。醫經之所謂闕。道書所謂上丹田。相書所謂中正印堂也。按庸風。揚且之皙也。子之淸揚。揚且之顔也。傳曰。揚睂上廣也。淸、視淸明也。揚且之顔者、廣揚而顔角豐滿也。毛云顔角。葢𢫾全頟而言。中謂之顔。旁謂之角。由㒳睂閒以直上皆得謂之顔。醫經頟曰顔曰庭是也。國語。角犀豐盈。亦角謂旁、犀謂中。犀牛一角在鼻、一角在頂。故相法有骨自印堂至頂者曰伏犀貫頂。若方言云。𩔣頟顔"}]},"頌":{"expl":"皃也。从頁公聲。","rad":"頁","fq":"余封切","vol":"09","py":"rónɡ","duan":[{"e":"皃也。","n":"皃下曰。頌儀也。與此爲轉注。不曰頌也而曰頌儀也者、其義小別也。於此同之。於彼別之也。古作頌皃。今作容皃。古今字之異也。容者、盛也。與頌義別。六詩、一曰頌。周禮注云。頌之言誦也、容也。誦今之德廣以美之。詩諩曰。頌之言容。天子之德。光被四表。格於上下。無不覆燾。無不持載。此之謂容。於是和樂興焉。頌聲乃作。此皆以容受釋頌。似頌爲容之假借字矣。而毛詩序曰。頌者、美盛德之形容。以其成功告於神明者也。此與鄭義無異而相成。鄭謂德能包容故作頌。序謂頌以形容其德。但以形容釋頌而不作形頌。則知假容爲頌其來已久。以頌字專系之六詩。而頌之本義廢矣。漢書曰徐生善爲頌、曰頌禮甚嚴、其本義也。曰有罪當盜械者皆頌繫、此假頌爲"}]},"𩑒":{"expl":"顱也。从頁乇聲。","rad":"頁","fq":"徒谷切","vol":"09","py":"duó","duan":[{"e":"𩑒顱、首骨也。","n":"此五字各本作顱也。二字。今依全書通例正。骨部曰。髑髏、頂也。𩑒顱卽髑髏。語之轉也。𩑒顱亦曡韵。玉篇引博雅、聲類作頊顱。恐有誤。戰國策云。頭顱僵仆。相朢於竟。"}]},"顱":{"expl":"𩑒顱，首骨也。从頁盧聲。","rad":"頁","fq":"洛乎切","vol":"09","py":"lú","duan":[{"e":"𩑒顱也。","n":"各本作𩑒顱首骨也五字。今依全通通例正。漢書武五子傳作盧。"}]},"𩕾":{"expl":"顚頂也。从頁𡚇聲。","rad":"頁","fq":"魚怨切","vol":"09","py":"yuàn","duan":[{"e":"顚頂也。","n":"篇、韵皆云。𩕾願二同。按說文義異。"}]},"顚":{"expl":"頂也。从頁眞聲。","rad":"頁","fq":"都秊切","vol":"09","py":"diān","duan":[{"e":"頂也。","n":"見釋言。國語班序顚毛注同。引伸爲凡物之頂。如秦風有馬白顚。傳曰。白顚、旳顙也。馬以顙爲頂也。唐風首陽之顚。山頂亦曰顚也。顚爲冣上。倒之則爲冣下。故大雅顚沛之揭。傳曰。顚、僕也。論語顚沛。馬注曰。僵仆也。離騷注曰。自上下曰顚。廣雅曰。顚、末也。"}]},"茷":{"expl":"艸葉多。从艸伐聲。《春秋傳》曰：“晉糴茷。”","rad":"艸","fq":"符發切","vol":"01","py":"fá","duan":[{"e":"艸葉多。","n":"詩。白斾央央。本又作筏。泮水之其旂筏筏卽出車之旟旐旆旆、采菽之其旂淠淠也。然則小弁？葦淠淠亦當云？葦茷茷。本言艸葉之多、而引伸之狀旌旗也。"}]},"頂":{"expl":"顚也。从頁丁聲。","rad":"頁","fq":"都挺切","vol":"09","py":"dǐnɡ","duan":[{"e":"顚也。","n":"頂顚異部曡韵字。故顚倒樂府或作丁倒。引伸爲凡在冣上之偁。故廣雅云。頂、上也。按頂之假借字作定。詩周南。麟之定釋言、毛傳皆曰。定、題也。毛傳一本作顚也。亦與爾雅無不合。葢禽獸橫生。以頟爲頂。故秦風白顚傳曰旳顙。亦以顙釋顚。"}]},"顙":{"expl":"頟也。从頁桑聲。","rad":"頁","fq":"蘇朗切","vol":"09","py":"sǎnɡ","duan":[{"e":"頟也。","n":"方言。中夏謂之頟。東齊謂之顙。九拜中之頓首必重用其顙。故凡言稽顙者、皆謂頓首。非稽首也。公羊傳曰再拜顙者、卽拜而後稽顙也。何曰。顙者猶今叩頭。按叩頭者、經之頓首也。"}]},"題":{"expl":"頟也。从頁是聲。","rad":"頁","fq":"杜兮切","vol":"09","py":"tí","duan":[{"e":"頟也。","n":"釋言、毛傳曰。定、題也。引伸爲凡居前之偁。"}]},"頟":{"expl":"顙也。从頁各聲。","rad":"頁","fq":"五陌切","vol":"09","py":"é","duan":[{"e":"顙也。","n":"釋名曰。額、鄂也。有垠鄂也。引伸爲凡有垠鄂之偁。如喪服疏引大戴禮云。大功已上唯唯。小功已下額額然。臯陶𠻚。畫夜額額。釋各云。額額然憚之。韓碑云。額額蔡城。"}]},"頞":{"expl":"鼻莖也。从頁安聲。","rad":"頁","fq":"烏割切","vol":"09","py":"è","duan":[{"e":"鼻莖也。","n":"鼻謂之準。鼻直莖謂之頞。史記唐舉相蔡澤曰。先生曷鼻、巨肩、魋顔、蹙齃。旣言鼻又言頞者。曷同遏。遏鼻、言其內不通而齆。蹙齃則言其外鼻莖也。鼻有中𣃔者。蔡澤、諸葛恪之相是也。有憂愁而蹴縮者。孟子言蹙頞是也。有病而辛頞者。此言其內酸辛、素問所言是也。"}]},"頯":{"expl":"權也。从頁𢌳聲。","rad":"頁","fq":"渠追切","vol":"09","py":"kuí","duan":[{"e":"權也。","n":"權者今之顴字。戰國策。眉目準頞權衡。犀角偃月。其字正作權。易夬九三。壯于頄。王云。面權也。翟云。面顴、頰間骨也。鄭作頯。頯、夾面也。王與許說同。國策謂之權衡者、象其平也。按大玄視次四頯須姝爲韵。今本頯作䪻。誤。肉部曰。肫者、面頯也。儀禮釋文引說文肫章允反。漢高祖隆準。準與肫音同。故應劭曰。隆、高也。準、頰、權準也。入聲、音拙。則字又作䪼。"}]},"頰":{"expl":"面㫄也。从頁夾聲。","rad":"頁","fq":"古叶切","vol":"09","py":"jiá","duan":[{"e":"面旁也。","n":"面者、顔前也。顔前者、㒳眉閒㒳目閒已下至頰閒也。其旁曰頰。面部曰。䩉、頰也。易咸上六。咸其圃頰舌。輔卽䩉之假借字也。凡言頰車者、今俗謂牙牀骨。牙所載也。與單言頰不同。"}]},"𩓓":{"expl":"頰後也。从頁𥃩聲。","rad":"頁","fq":"古恨切","vol":"09","py":"ɡěn","duan":[{"e":"頰後也。","n":"頰後謂近耳及耳下也。"}]},"頜":{"expl":"𩔞也。从頁合聲。","rad":"頁","fq":"胡感切","vol":"09","py":"hàn","duan":[{"e":"顄也。","n":"公羊傳。呼獒而屬之。獒亦躇階而從之。祁彌明、逆而踆之。絕其頷。何云。以足逆躢曰踆。頷、口也。按玉篇引作絕其頜。此謂以足迎蹋之。遂使獒之頤不能噬也。方言。頷頤頜也。南楚謂之頷。秦晉謂之頜。頤其通語也。"}]},"𩔞":{"expl":"頤也。从頁圅聲。","rad":"頁","fq":"胡男切","vol":"09","py":"hán","duan":[{"e":"頤也。","n":"𦣝下曰。𩔞也。𦣝者古文頤。與此爲轉注。王莽傳作顄。正字也。方言作頷。於說文爲假借字。"}]},"菜":{"expl":"艸之可食者。从艸采聲。","rad":"艸","fq":"蒼代切","vol":"01","py":"cài","duan":[{"e":"艸之可食者。","n":"菜字當冠於芑葵等字之上。"}]},"頸":{"expl":"頭莖也。从頁坙聲。","rad":"頁","fq":"居郢切","vol":"09","py":"jǐnɡ","duan":[{"e":"頭莖也。从𩑋。巠聲。","n":"居郢切。十一部。"}]},"領":{"expl":"項也。从頁令聲。","rad":"頁","fq":"良郢切","vol":"09","py":"lǐnɡ","duan":[{"e":"項也。","n":"按項當作頸。碩人、桑扈傳曰。領、頸也。此許所本也。釋名、國語注同。領字以全頸言之。不當釋以頭後。若廣雅領、頸、項也。合宜分別者渾言之。其全書之例類皆然矣。衣之曲袷謂之領、亦不謂衣後也。仲尼燕居注。領猶治也。淮南書高注。領、理也。皆引伸之義。謂得其首領也。龜策傳用領爲蓮。異部假借。"}]},"項":{"expl":"頭後也。从頁工聲。","rad":"頁","fq":"胡講切","vol":"09","py":"xiànɡ","duan":[{"e":"頭後也。","n":"頭後者、在頭之後。後項雙聲。故項槖亦曰後槖也。肉部曰。脰、項也。公羊傳。搏閔公這脰。何云。脰、頸也。齊人語。此當曰項而曰頸者、渾言則不別。小雅。四牡項領。傳曰。項、大也。此謂項與𨾊同。"}]},"䪴":{"expl":"項枕也。从頁冘聲。","rad":"頁","fq":"章衽切","vol":"09","py":"zhěn","duan":[{"e":"玉枕也。","n":"玉枕、各本作項䪴。小徐作項枕。廣韵作頊䪴。云頊魚欲切。醫、經本作玉枕。許說同。一譌爲頊䪴。再譌爲項䪴。皆非也。沈氏彤詳攷內經甲乙經、作釋骨曰。顚之後橫起者、曰頭橫骨。曰枕骨。其㒳旁尤起者、曰玉枕骨。玉枕骨卽偃臥箸枕之處。單𧦝曰䪴。玉篇引蒼頡云。垂頭之皃。此別一義。"}]},"顀":{"expl":"出頟也。从頁隹聲。","rad":"頁","fq":"直追切","vol":"09","py":"chuí","duan":[{"e":"出頟也。","n":"謂頟胅出向前也。玄應曰。今江南言顀頭胅額。乃以顀爲後枕之名。按後枕卽上文之䪴也。"}]},"𩑢":{"expl":"曲頤也。从頁不聲。","rad":"頁","fq":"薄回切","vol":"09","py":"péi","duan":[{"e":"曲頤也。","n":"曲頤者、頤曲而微向前也。揚雄傳顉頤。師古曰。曲頤也。按廣頤曰巸。曲頤曰𩑢。頤狀之不同也。"}]},"顩":{"expl":"𪙊皃。从頁僉聲。","rad":"頁","fq":"魚檢切","vol":"09","py":"yǎn","duan":[{"e":"𪙊皃也。","n":"𪙊者、齒差也。篇、韵皆云。𩑳顩、不平也。𩑳邱檢切。字當作{𢆉+頁[左右]}。𢆉聲。按許說顩之本義。文選解嘲顩頤、乃假顩爲䫡也。"}]},"䪳":{"expl":"面目不正皃。从頁尹聲。","rad":"頁","fq":"余準切","vol":"09","py":"yǔn","duan":[{"e":"面目不正皃。","n":"玉篇曰。面不平。廣韵曰。面斜。"}]},"頵":{"expl":"頭頵頵大也。从頁君聲。","rad":"頁","fq":"於倫切","vol":"09","py":"yūn","duan":[{"e":"頭頵頵大也。","n":"按鍇本作頭頵也。與文選注合。然恐有奪字耳。文選長笛賦。重巘增石。𥳑積頵砡。春秋楚君有名頵者。"}]},"䫟":{"expl":"面色顚䫟皃。从頁員聲。讀若隕。","rad":"頁","fq":"于閔切","vol":"09","py":"hùn","duan":[{"e":"面色䫟䫟皃。","n":"皃當依玉篇作也。"}]},"禦":{"expl":"祀也。从示御聲。","rad":"示","fq":"魚舉切","vol":"01","py":"yù","duan":[{"e":"祀也。从示。御聲。","n":"後人用此爲禁禦字。疑舉切。五部。古只用御字。"}]},"荋":{"expl":"艸多葉皃。从艸而聲。沛城父有楊荋亭。","rad":"艸","fq":"如之切","vol":"01","py":"ér","duan":[{"e":"艸多葉皃。","n":"荋之言之而也。如鱗屬之之而。"}]},"䫡":{"expl":"頭頰長也。从頁兼聲。","rad":"頁","fq":"五咸切","vol":"09","py":"yán","duan":[{"e":"頭頰長也。","n":"四字當作頭陝面長皃、五字。玉篇云。頭頰面長皃。頰亦譌字。廣韵。面長皃。則少頭陝二字。文選解嘲。顩頤折頞。韋昭曰。面長曰顩。欺甚切。玉篇引蒼頡云。顩、面長銳頤之皃。葢解嘲及蒼頡皆以顩爲䫡也。"}]},"碩":{"expl":"頭大也。从頁石聲。","rad":"頁","fq":"常隻切","vol":"09","py":"shuò","duan":[{"e":"頭大也。","n":"引伸爲凡大之偁。釋詁、毛傳皆曰。碩、大也。𥳑兮傳曰。碩人、大德也。碩與石二字互相借。"}]},"頒":{"expl":"大頭也。从頁分聲。一曰鬢也。《詩》曰：“有頒其首。”","rad":"頁","fq":"布還切","vol":"09","py":"bān","duan":[{"e":"大頭也。","n":"小雅魚藻曰。魚在在藻。有頒其首。傳曰。頒大首皃。苕之華。牂羊墳首。傳曰。墳、大也。此假墳爲頒也。孟子。頒白者不負戴於道路。此假頒爲𩔾也。周禮。匪頒之式。鄭司農云。匪、分也。頒讀爲班布之班。謂班賜也。此假頒爲班也。"}]},"顒":{"expl":"大頭也。从頁禺聲。《詩》曰：“其大有顒。”","rad":"頁","fq":"魚容切","vol":"09","py":"yónɡ","duan":[{"e":"大頭也。","n":"引伸之凡大皆有是偁。小雅六月。其大有顒。傳曰。顒、大皃。大雅卷阿傳曰。顒顒、溫皃。卬卬、盛皃。釋訓曰。顒顒、卬卬、君之德也。又其引伸之義也。"}]},"䫞":{"expl":"大頭也。从頁羔聲。","rad":"頁","fq":"口幺切","vol":"09","py":"qiāo","duan":[{"e":"大頭也。","n":"玉篇引蒼頡云。頭大也。廣雅曰。䫞、大也。"}]},"顝":{"expl":"大頭也。从頁骨聲。讀若魁。","rad":"頁","fq":"苦骨切","vol":"09","py":"kuī","duan":[{"e":"大頭也。","n":"廣雅曰。顝、大也。思玄賦。顝羈旅而無友。舊注。顝、獨也。此與九辨塊獨守此無澤之塊同。皆於音求之。玉篇引蒼頡云。相抵觸。廣雅云。醜也。皆引伸之義。"}]},"願":{"expl":"大頭也。从頁原聲。","rad":"頁","fq":"魚怨切","vol":"09","py":"yuàn","duan":[{"e":"大頭也。","n":"本義如此。故从頁。今則本義廢矣。邶風。願言思子。中心養養。傳曰。願、每也。此每如春秋外傳懷私爲每懷、賈誼賦品庶每生之每。按毛詩願字首見於終風願言則疐、而無傳。則毛意謂與今人語同耳。釋詁曰。願、思也。方言曰。願、欲思也。邶風鄭箋曰。願、念也。皆與今語合。丂部曰。寧、願䛐也。用部曰。甯、所願也。心部曰。憖、肎也。凡言願者、葢寧甯憖三字語聲之轉。自詩所用已如是。而二子乘舟語意尤深。故傳別言之。實非異也。"}]},"顤":{"expl":"高長頭。从頁堯聲。","rad":"頁","fq":"五弔切","vol":"09","py":"yáo","duan":[{"e":"高長頭。","n":"玉篇下有皃字。靈光殿賦李注。䫜顤顟、大首深目之皃。"}]},"𩕀":{"expl":"𩕀顤，高也。从頁敖聲。","rad":"頁","fq":"五到切","vol":"09","py":"ào","duan":[{"e":"𩕀顤高也。","n":"當云頭高也。廣韵云。頭長。"}]},"𩓥":{"expl":"面前岳岳也。从頁岳聲。","rad":"頁","fq":"五角切","vol":"09","py":"yuè","duan":[{"e":"前面岳岳也。","n":"前當作歬。歬面猶俗云當面。李白詩。山從人面起。靈光殿賦。神仙岳岳於棟間。李注。岳岳、立皃。"}]},"䒦":{"expl":"艸浮水中皃。从艸乏聲。","rad":"艸","fq":"匹凡切","vol":"01","py":"fàn","duan":[{"e":"艸浮水中皃。","n":"芝與氾音義同。"}]},"𩒳":{"expl":"昧前也。从頁𡿯聲。讀若昧。","rad":"頁","fq":"莫佩切","vol":"09","py":"mèi","duan":[{"e":"昧前也。","n":"前當作歬。昧當作眛。眛於當歬、論語所謂正牆面而立也。"}]},"𩖊":{"expl":"面瘦淺𩖊𩖊也。从頁霝聲。","rad":"頁","fq":"郎丁切","vol":"09","py":"línɡ","duan":[{"e":"面𤸃淺𩖊𩖊也。从𩑋。霝聲。","n":"郞丁切。十一部。"}]},"𩔀":{"expl":"頭蔽𩔀也。从頁㒸聲。","rad":"頁","fq":"五怪切","vol":"09","py":"wài","duan":[{"e":"頭𦳋𩔀也。","n":"𦳋𩔀曡韵字。葢古語也。集韵曰。謂頭癡。錢氏大昕曰。春秋戰國人名有蒯聵者。疑卽此𦳋𩔀字。"}]},"頑":{"expl":"㮯頭也。从頁元聲。","rad":"頁","fq":"五還切","vol":"09","py":"wán","duan":[{"e":"㮯頭也。","n":"木部曰。㮯、梡木未析也。梡、㮯木薪也。凡物渾淪未破者皆得曰㮯。凡物之頭渾全者皆曰㮯頭。㮯頑雙聲。析者銳。㮯者鈍。故以爲愚魯之偁。左傳曰。心不則德義之經爲頑。"}]},"𩓸":{"expl":"小頭𩓸𩓸也。从頁枝聲。讀若規。","rad":"頁","fq":"","vol":"09","py":"ɡuī","duan":[{"e":"小頭𩓸𩓸也。","n":"𩓸之言嫢也。嫢者、細也。"}]},"顆":{"expl":"小頭也。从頁果聲。","rad":"頁","fq":"苦惰切","vol":"09","py":"kě","duan":[{"e":"小頭也。","n":"引伸爲凡小物一枚之偁。珠子曰顆、米粒曰顆是也。賈山傳。蓬顆蔽𠣥。晉灼曰。東北人名土塊爲蓬顆。按此卽淮南書、宋玉風賦之堁字。許注淮南曰。堁、塵塺也。"}]},"頢":{"expl":"短面也。从頁𠯑聲。","rad":"頁","fq":"五活切","vol":"09","py":"kuò","duan":[{"e":"短面也。","n":"廣韵曰。小頭皃。"}]},"頲":{"expl":"狹頭頲也。从頁廷聲。","rad":"頁","fq":"他挺切","vol":"09","py":"tǐnɡ","duan":[{"e":"狹頭頲也。","n":"疑當作頲頲也。假借爲挺直之挺。釋詁曰。頲、直也。"}]},"頠":{"expl":"頭閑習也。从頁危聲。","rad":"頁","fq":"語委切","vol":"09","py":"wěi","duan":[{"e":"頭閑習也。","n":"閑當作嫺。字之誤也。引伸爲凡嫺習之偁。釋詁曰。頠、靜也。頠與女部之姽義略同。"}]},"頷":{"expl":"面黃也。从頁含聲。","rad":"頁","fq":"胡感切","vol":"09","py":"hàn","duan":[{"e":"面黃也。","n":"離騷。苟余情其信姱以練要兮。長顑頷亦何傷。王注。顑頷、不飽皃。本部顑字下云。飯不飽面黃起行也。義得相足。今則頷訓爲頤。古今字之不同也。"}]},"薄":{"expl":"林薄也。一曰蠶薄。从艸溥聲。","rad":"艸","fq":"旁各切","vol":"01","py":"bó","duan":[{"e":"林薄也。","n":"吳都賦。傾藪薄。劉注曰。薄、不入之叢也。按林木相迫不可入曰薄。引伸凡相迫皆曰薄。如外薄四海、日月薄蝕皆是。傍各補各二切同也。相迫則無閒可入。凡物之單薄不厚者亦無閒可入。故引伸爲厚薄之薄。曹憲云。必當作䙏。非也。"}]},"𩔃":{"expl":"面不正也。从頁爰聲。","rad":"頁","fq":"于反切","vol":"09","py":"yuǎn","duan":[{"e":"面不正也。从𩑋。爰聲。","n":"于反切。十四部。"}]},"頍":{"expl":"舉頭也。从頁支聲。《詩》曰：“有頍者弁。”","rad":"頁","fq":"丘弭切","vol":"09","py":"kuǐ","duan":[{"e":"舉頭也。","n":"此頍之本義也。故？字从頁。士冠禮。緇布冠缺項。注。缺讀爲頍。頍圍髪際。結項中。隅爲四綴以固冠。今未冠筓者箸冠卷。頍象之所生也。滕薛名簂爲頍。如鄭說則頍所以支冠。舉頭之義之引伸也。小雅。有頍者弁。傳曰。頍、弁皃。弁、皮弁也。惟舉頭曰頍。故載弁亦曰頍。義之相因而引伸者也。"}]},"𩑦":{"expl":"内頭水中也。从頁、𠬸，𠬸亦聲。","rad":"頁","fq":"烏没切","vol":"09","py":"mò","duan":[{"e":"內頭水中也。","n":"內者、入也。入頭水中。故字从𩑋𠬸。與水部之𣳚義同而別。今則？？廢而𣳚專行矣。"}]},"顧":{"expl":"還視也。从頁雇聲。","rad":"頁","fq":"古慕切","vol":"09","py":"ɡù","duan":[{"e":"還視也。","n":"還視者、返而視也。檜風箋云。迴首曰顧。析言之爲凡視之偁。鄉黨。賓不顧矣。謂還視也。車中內顧。苞氏謂前視不過衡軛。旁視不過輢較。則顧猶視也。又引伸爲臨終之命曰顧命。又引伸爲語將轉之詞。"}]},"順":{"expl":"理也。从頁从巛。","rad":"頁","fq":"食閏切","vol":"09","py":"shùn","duan":[{"e":"理也。","n":"理者、治玉也。玉得其治之方謂之理。凡物得其治之方皆謂之理。理之而後天理見焉。條理形焉。非謂空中有理。非謂性卽理也。順者、理也。順之所以理之。未有不順民情而能理者。凡訓詁家曰從、順也。曰愻、順也。曰馴、順也。此六書之轉注。曰訓、順也。此六書之假借。凡順愼互用者、字之譌。"}]},"䪾":{"expl":"顔色䪾䫰，愼事也。从頁㐱聲。","rad":"頁","fq":"之忍切","vol":"09","py":"zhěn","duan":[{"e":"顏色䪾䫰愼事也。","n":"愼事玉篇、廣韵作順事。疑南宋改耳。"}]},"䫰":{"expl":"䪾䫰也。从頁粦聲。一曰頭少髮。","rad":"頁","fq":"良忍切","vol":"09","py":"lǐn","duan":[{"e":"䪾䫰也。从𩑋。粦聲。","n":"良刄切。玉篇來軫切。二篆今作？？。十二部。"}]},"顓":{"expl":"頭顓顓謹皃。从頁耑聲。","rad":"頁","fq":"職緣切","vol":"09","py":"zhuān","duan":[{"e":"頭顓顓謹皃。","n":"此本義也。故从𩑋。白虎通曰。謂之顓頊何。顓者、專也。頊者、正也。言能專正天之道也。按叀者、小謹也。今字作專。亦假顓作專。如淮南云顓民、法言云顓蒙、漢書言顓顓獨居一海之中皆是。"}]},"頊":{"expl":"頭頊頊謹皃。从頁玉聲。","rad":"頁","fq":"許玉切","vol":"09","py":"xū","duan":[{"e":"頭頊頊謹皃。","n":"此本義也。故从𩑋。引伸爲正也。白虎通又曰。冬、其帝顓頊。顓頊者、寒縮也。"}]},"顉":{"expl":"低頭也。从頁金聲。《春秋傳》曰：“迎于門，顉之而巳。”","rad":"頁","fq":"五感切","vol":"09","py":"ǎn","duan":[{"e":"低頭也。","n":"低當作氐氐者、說文之低字也。左傳襄卄六年。衞獻公反國。大夫逆於竟者。執其手而與之言。道逆者。自車揖之。逆於門者。頷之而巳。釋文。頷本又作頜。按依許則頷頜皆非也。杜注搖頭亦非。旣不執手而言。又不自車揖之。則在車首肎而巳。不至搖頭也。釋文本又作頜、正是本又作顉之譌。列子湯問曰。顉其頤則歌合律。郭璞游仙詩。洪厓頷其頤。注引列子亦作頷。引廣雅頷、動也。頷皆顉之譌。故云五感反。若本頷字、則當云胡感反也。顉其頤者、開口則低其頤。靈光殿賦。顉若動而躨跜。今本亦譌頷。"}]},"苑":{"expl":"所以養禽獸也。从艸夗聲。","rad":"艸","fq":"於阮切","vol":"01","py":"yuàn","duan":[{"e":"所㠯養禽獸。","n":"周禮地官囿人注。囿、今之苑。是古謂之囿、漢謂之苑也。西都賦上囿禁苑。西京賦作上林禁苑。"}]},"頓":{"expl":"下首也。从頁屯聲。","rad":"頁","fq":"都困切","vol":"09","py":"dùn","duan":[{"e":"下首也。","n":"按當作頓首也。三字爲句。周禮太祝九？。一曰䭬首。二曰頓首。三曰空首。三者分別劃然。不當頓䭫二字皆訓之曰下首、明矣。鄭曰。稽首、拜頭至地也。頓首、拜頭叩地也。空手、拜頭至手。所謂拜手也。吉拜、拜而後稽顙。謂齊衰不杖以下者。凶拜、稽顙而後拜。謂三年服者。玉裁按。九拜、以前三者爲體。後六者爲用。如六書以指事、象形、形聲、會意四者爲體。轉注、假借二者爲用也。凡經言拜手、言拜皆周禮之空首。手部？字下曰首至手、何注公羊傳曰頭至手曰拜手皆與周禮空首注合。凡經言稽首、小篆作䭫。古文作？。經傳無異偁。何注公羊云頭至地曰稽首、與周禮注合。凡經傳言頓首、言稽顙或單言顙皆九拜之頓首。何注公羊曰顙猶今叩頭、檀弓稽顙注曰"}]},"頫":{"expl":"低頭也。从頁，逃省。太史卜書，頫仰字如此。楊雄曰：人面頫。","rad":"頁","fq":"方矩切","vol":"09","py":"fǔ","duan":[{"e":"低頭也。","n":"低當作氐。西京賦。伏櫺檻而頫聽。聞雷霆之相激。薛綜曰。頫、低頭也。上林賦頫杳眇而無見。李善引聲類。頫古文俯字。"}]},"頣":{"expl":"舉目視人皃。从頁臣聲。","rad":"頁","fq":"式忍切","vol":"09","py":"shěn","duan":[{"e":"舉目視人皃。","n":"目當依廣韵作眉。舉眉、揚眉也。"}]},"𩕊":{"expl":"倨視人也。从頁善聲。","rad":"頁","fq":"旨善切","vol":"09","py":"zhǎn","duan":[{"e":"倨視人也。","n":"倨者、不愻也。"}]},"頡":{"expl":"直項也。从頁吉聲。","rad":"頁","fq":"胡結切","vol":"09","py":"xié","duan":[{"e":"直項也。","n":"淮南修務訓。王公大人有嚴志頡頏之行者。無不憛悇癢心而悅其色矣。此頡頏正謂強項也。亢部？下曰。直項莽？。淮南之頏。卽說文之？也。直項者、頡之本義。若邶風。燕燕于飛。頡之頏之。傳曰。飛而下曰頡。飛而上曰頏。此其引伸之義。直項爲頡頏。故引伸之直下直上曰頡頏。"}]},"䪼":{"expl":"頭頡䪼也。从頁出聲。讀又若骨。","rad":"頁","fq":"之出切","vol":"09","py":"zhuō","duan":[{"e":"頭頡䪼也。","n":"頡䪼曡韵。古語頭菌蠢皃。若高祖隆準。服䖍準音拙。應劭曰。頰權準也。師古曰。䪼權䪼字豈當借準爲之。按服但云準音拙耳。權䪼之名又出漢後也。"}]},"顥":{"expl":"白皃。从頁从景。《楚詞》曰：“天白顥顥。”南山四顥，白首人也。","rad":"頁","fq":"胡老切","vol":"09","py":"hào","duan":[{"e":"白皃。","n":"漢郊祀歌曰。西顥沆碭。西都賦曰。鮮顥氣之淸英。顥與㚖音義略同。"}]},"䫶":{"expl":"大醜皃。从頁樊聲。","rad":"頁","fq":"附袁切","vol":"09","py":"fán","duan":[{"e":"大醜皃。","n":"醜、可惡也。"}]},"𩓞":{"expl":"好皃。从頁爭聲。《詩》所謂“𩓞首”。","rad":"頁","fq":"疾正切","vol":"09","py":"jìnɡ","duan":[{"e":"好皃。","n":"頭好也。"}]},"頨":{"expl":"頭妍也。从頁，翩省聲。讀若翩。","rad":"頁","fq":"王矩切","vol":"09","py":"yǔ","duan":[{"e":"頨姸也。","n":"三字爲句。頨姸曡韵。大徐改爲頭姸。此卽改頓首爲下首之比。姸、安也。頨義如周易之翩翩。東都賦。翩翩巍巍。顯顯翼翼。"}]},"藪":{"expl":"大澤也。从艸𢿙聲。九州之藪：楊州具區，荆州雲夢，豫州甫田，青州孟諸，沇州大野，雝州弦圃，幽州奚養，冀州楊紆，并州昭餘祁是也。","rad":"艸","fq":"蘇后切","vol":"01","py":"sǒu","duan":[{"e":"大澤也。","n":"地官澤虞曰。每大澤大藪。中澤中藪。小澤小藪。注。澤水所鍾也。水希曰藪。此析言則澤藪殊也。職方氏云。其澤藪曰某。毛詩傳曰。藪澤。此統言則不別也。職方氏注曰。大澤曰藪。與說文合。葢藪實兼水鍾、水希而言。爾雅十藪𣪠釋地。不𣪠釋水。正謂地多水少。艸木所聚。"}]},"顗":{"expl":"謹莊皃。从頁豈聲。","rad":"頁","fq":"魚豈切","vol":"09","py":"yǐ","duan":[{"e":"謹莊皃。","n":"莊者、壯盛字之假借也。釋詁曰。顗、靜也。義相足。"}]},"顅":{"expl":"頭鬢少髮也。从頁肩聲。《周禮》：“數目顅脰。”","rad":"頁","fq":"苦閒切","vol":"09","py":"qiān","duan":[{"e":"頭鬢少髮也。","n":"髟部曰。鬜者、鬢禿也。此音義皆同。葢實一字矣。而以顅从頁、故云頭鬢。謂頭上及鬢夾也。鬜从髟、故單言鬢。考工記。數目顅脰。故書顅或作牼。鄭司農曰。牼讀爲鬜頭無髮之鬜。司農意謂鳥頭毛短也。鄭注明堂位曰。齊人謂無髮爲禿楬。釋名曰。禿、無髮沐秃也。毼頭生瘡曰瘕。毼亦然也。楬與毼皆卽鬜字。許說周禮與先鄭同。後鄭易之曰顅、長脰也。非許義。證以荘子其脰肩肩、則後鄭是也。肩卽顅。"}]},"𩓽":{"expl":"無髮也。一曰耳門也。从頁囷聲。","rad":"頁","fq":"苦昆切","vol":"09","py":"kūn","duan":[{"e":"無髮也。","n":"廣韵曰。𩓽者、𩓽顐也。顐者、禿也。五困切。"}]},"𩑔":{"expl":"秃也。从頁气聲。","rad":"頁","fq":"苦骨切","vol":"09","py":"kū","duan":[{"e":"禿也。","n":"禿本訓無髮。此則用其引伸之義也。考工記。作其鱗之而。注曰。之而、頰𩑔也。按頰謂鱗屬之面旁。𩑔謂鱗屬之頤？。圓潤光滑故謂之禿。古語如是。魚游泳必動其頰與？。所謂作其之而也。玉篇。頹者、頰下也。是其字可作頹。而淺者謂爲穨字。"}]},"頛":{"expl":"頭不正也。从頁从耒。耒，頭傾也。讀又若《春秋》陳夏齧之齧。","rad":"頁","fq":"盧對切","vol":"09","py":"lèi","duan":[{"e":"頭不正也。","n":"釋魚。左倪不類。周禮類作靁。葢皆頛之假借字也。"}]},"䫌":{"expl":"傾首也。从頁卑聲。","rad":"頁","fq":"匹米切","vol":"09","py":"pǐ","duan":[{"e":"傾首也。","n":"首玄應引作頭。玄應引蒼頡篇云。頭不正也。又引淮南子。左䫌右倪。按釋魚。左倪右倪。郭注。行頭左俾右俾。俾亦作庳。皆非是。其字正當作䫌。故釋文暜計反也。"}]},"䫔":{"expl":"司人也。一曰恐也。从頁契聲。讀若褉。","rad":"頁","fq":"胡計切","vol":"09","py":"qì","duan":[{"e":"司人也。","n":"司者、今之伺字。"}]},"䫥":{"expl":"頭不正也。从頁鬼聲。","rad":"頁","fq":"口猥切","vol":"09","py":"kuǐ","duan":[{"e":"頭不正也。从𩑋。鬼聲。","n":"口猥切。十五部。"}]},"頗":{"expl":"頭偏也。从頁皮聲。","rad":"頁","fq":"滂禾切","vol":"09","py":"pō","duan":[{"e":"頭偏也。","n":"引伸爲凡偏之偁。洪範曰。無偏無頗。遵王之義。人部曰。偏者、頗也。以頗引伸之義釋偏也。俗語曰頗多頗久頗有、猶言偏多偏久偏有也。古借陂爲頗。如洪範古本作無偏無陂。顏師古匡謬正俗、李善文選注所引皆作陂。可證。迄乎天寶。乃據其時所用本作頗、而詔改爲陂。一若古無作陂者。不學而作聰之過也。陂義古皆在歌戈部。則又不知古音之過耳。"}]},"𩑣":{"expl":"顫也。从頁尤聲。","rad":"頁","fq":"于救切","vol":"09","py":"yòu","duan":[{"e":"顫也。从𩑋。尢聲。","n":"按玄應書㒳引說文皆作？。是其字从𩑋、又聲。今本說文作？、尤聲。非古也。篇、韵皆沿俗本之誤耳。玄應引說文云。謂掉動不定也。葢演說文語。通俗文曰。四支寒動謂之顫？。于救切。古音在一部。"}]},"菑":{"expl":"不耕田也。从艸、甾。《易》曰：“不菑畬。”","rad":"艸","fq":"側詞切","vol":"01","py":"zī","duan":[{"e":"不耕田也。","n":"海寧陳氏鱣曰。不、當爲才。才耕田、謂始耕田也。才財材皆訓始。玉裁按。不當爲反。字之誤也。爾雅田一歲曰葘。毛詩傳、馬融虞翻易注皆用之。韓詩、董遇易章句皆曰。葘、反艸也。與田一歲義相成。詩大田箋曰。俶載讀爲熾葘。時至。民以其利耜熾葘。發所受之地。趨農急也。攷諸經傳。凡入之深而植立者皆曰葘。如攷工記輪人葘訓建輻。弓人葘訓以鋸副析。公羊傳以人爲葘。漢書楗石葘。鄭仲師云。泰山平原所樹立物爲葘。聲如？。博、立䲷棊亦爲葘。其他若毛傳木立死曰葘。漢書事刃公之腹中。急就篇。分別部居不襍廁。漢太學石經以人爲側。皆此字之引伸假借。又假爲烖害字。"}]},"顫":{"expl":"頭不正也。从頁亶聲。","rad":"頁","fq":"之繕切","vol":"09","py":"chàn","duan":[{"e":"頭不定也。","n":"不定各本作不正。今正。顫？皆不寧之皃。上文頛䫌䫥頗四篆、言頭不正。此則義別。頭不定、故从𩑋。引伸爲凡不定之偁。"}]},"顑":{"expl":"飯不飽，面黃起行也。从頁咸聲。讀若戇。","rad":"頁","fq":"下感切","vol":"09","py":"kǎn","duan":[{"e":"顑顲、","n":"逗。二字各本無。今依全書通例補。曡韵字。"}]},"顲":{"expl":"面䫲顲皃。从頁𤎭聲。","rad":"頁","fq":"盧感切","vol":"09","py":"lǎn","duan":[{"e":"顑顲也。","n":"各本作面顑顲皃。今依全書通例正。"}]},"煩":{"expl":"熱頭痛也。从頁从火。一曰焚省聲。","rad":"頁","fq":"附袁切","vol":"09","py":"fán","duan":[{"e":"𤍽頭痛也。","n":"詩曰。如炎如焚。陸機詩云。身𤍽頭且痛。"}]},"𩕺":{"expl":"癡，不聦明也。从頁𧱏聲。","rad":"頁","fq":"五怪切","vol":"09","py":"wài","duan":[{"e":"癡顡、","n":"逗。各本奪顡字。今依玉篇、廣韵補。"}]},"頪":{"expl":"難曉也。从頁、米。一曰鮮白皃。从粉省。","rad":"頁","fq":"盧對切","vol":"09","py":"lèi","duan":[{"e":"難曉也。","n":"謂相佀難分別也。頪類古今字。類本專謂犬。後乃類行而頪廢矣。廣雅云。頪、疾也。"}]},"顦":{"expl":"顦顇也。从頁焦聲。","rad":"頁","fq":"昨焦切","vol":"09","py":"qiáo","duan":[]},"顇":{"expl":"顦顇也。从頁卒聲。","rad":"頁","fq":"秦醉切","vol":"09","py":"cuì","duan":[{"e":"顦顇也。","n":"許書無顦篆。大徐增之。非也。錢氏大昕曰。面部之䩌、當是正字。小雅。或盡瘁事國。傳云。盡力勞病以從國事。左傳引詩曰。雖有姬姜。無棄蕉萃。杜曰。蕉萃、陋賤之人。楚辭漁父。顏色憔悴。王曰。皯黴黑也。班固荅賓戲。朝而榮華。夕而焦瘁。其字各不同。今人多用憔悴字。許書無憔篆。悴則訓憂也。"}]},"䫒":{"expl":"繫頭殟也。从頁昏聲。","rad":"頁","fq":"莫奔切","vol":"09","py":"mén","duan":[{"e":"繫頭殟也。","n":"歹部曰。殟者、暴無知也。今本譌作胎敗。則此以殟釋䫒、遂不可通。集韵、類篇引此條有謂頭被繫無知也七字。當是古注語。玉篇引莊子云。問焉則䫒然。䫒、不曉也。按與心部之惛音義略同。"}]},"頦":{"expl":"醜也。从頁亥聲。","rad":"頁","fq":"戶來切","vol":"09","py":"hái","duan":[{"e":"醜也。","n":"廣雅同。篇、韵云。頤下。非許義。"}]},"𧄎":{"expl":"艸盛皃。从艸繇聲。《夏書》曰：“厥艸惟𧄎。”","rad":"艸","fq":"余招切","vol":"01","py":"yáo","duan":[{"e":"艸盛皃。从艸。䌛聲。","n":"此以形聲包㑹意。䌛、隨從也。他書凡䌛皆作䌛。？作？。余招切。古音在三部。"}]},"䫏":{"expl":"醜也。从頁其聲。今逐疫有䫏頭。","rad":"頁","fq":"去其切","vol":"09","py":"qī","duan":[{"e":"醜也。","n":"此䫏之本義。"}]},"𥸤":{"expl":"呼也。从頁籥聲。讀與籥同。《商書》曰：“率𥸤眾戚。”","rad":"頁","fq":"羊戍切","vol":"09","py":"yù","duan":[{"e":"呼也。","n":"呼當作𧦝。言部曰。𧦝者、召也。口部曰。召者、𧦝也。周書。乃有室大競。籲俊尊上帝。某氏曰。招呼賢俊與共尊事上天。商書。率籲衆戚。出矢言。某氏曰。籲、和也。率和衆憂之人。出正直之言。按和之訓未知何出。葢謂籲同龠。龠以和衆聲也。夫下文自我王來、至底綏四方皆民不欲徙之言。姚氏鼐之說是也。籲衆戚、出矢言。正謂不欲徙之民相𧦝急出誓言。爲盤庚斆民命衆張本。注疏殊繆。"}]},"顯":{"expl":"頭明飾也。从頁㬎聲。","rad":"頁","fq":"呼典切","vol":"09","py":"xiǎn","duan":[{"e":"頭朙飾也。","n":"故字从頁。飾者、妝也。女部曰妝、飾也是也。頭明飾者、冕弁充耳之類。引伸爲凡明之偁。按㬎謂衆明。顯本主謂頭明飾。乃顯專行而㬎廢矣。日部㬎下曰。古文以爲顯字。由今字假顯爲㬎。乃謂古文假㬎爲顯也。此古今字之變遷。所必當深究也。"}]},"𩔊":{"expl":"選具也。从二頁。","rad":"頁","fq":"士戀切","vol":"09","py":"zhuàn","duan":[{"e":"𨕖具也。","n":"𨕖擇而共置之也。𩔊𨕖㬪韵。？部曰。㢲、具也。𩕧、具也。人部曰。𠊨、具也。是㢲𩔊𩕧𠊨四字義同。玉篇曰。𩔊古文作𨕖。"}]},"預":{"expl":"安也。案：經典通用豫。从頁，未詳。","rad":"頁","fq":"羊洳切","vol":"09","py":"yù","duan":[]},"𦣻":{"expl":"頭也。象形。凡𦣻之屬皆从𦣻。","rad":"𦣻","fq":"書九切","vol":"09","py":"shǒu","duan":[]},"脜":{"expl":"面和也。从𦣻从肉。讀若柔。","rad":"𦣻","fq":"耳由切","vol":"09","py":"róu","duan":[{"e":"面和也。","n":"和當作龢。龢、調也。咊、相應也。許書分別畫然。今人淆之。抑詩。輯柔爾顏。傳曰。輯、和也。泮水。載色載笑。傳曰。色、温潤也。玉篇曰。野王案柔色以蕰之。是以今爲柔字。按今字柔行而脜廢矣。"}]},"面":{"expl":"顔前也。从𦣻，象人面形。凡面之屬皆从面。","rad":"面","fq":"彌箭切","vol":"09","py":"miàn","duan":[{"e":"顏前也。","n":"顏者、兩眉之中閒也。顏前者謂自此而前則爲目、爲鼻、爲目下、爲頰之閒、乃正鄉人者。故與背爲反對之偁。引伸之爲相鄉之偁。又引伸之爲相背之偁。易窮則變。變則通也。凡言面縛者、謂反背而縛之。偭从面。"}]},"靦":{"expl":"面見也。从面、見，見亦聲。《詩》曰：“有靦面目。”","rad":"面","fq":"他典切","vol":"09","py":"tiǎn","duan":[{"e":"面見人也。","n":"各本無人。今依毛詩正義補。面見人、謂但有面相對自覺可憎也。小雅何人斯。有靦面目。傳曰。靦、？也。女部曰。？、面靦也。按心部曰。青徐謂慙曰㥏。音義皆同。而一从心者、慙在中。一从面者、媿在外。韋注國語曰。靦、面目之皃也。"}]},"䩉":{"expl":"頰也。从面甫聲。","rad":"面","fq":"符遇切","vol":"09","py":"fǔ","duan":[{"e":"頰也。","n":"頰者、面旁也。面旁者、顏前之兩旁。大招。靨輔奇牙。宜笑嫣只。王注。言美頰有靨䩉。口有奇牙。嘕然而笑。尤媚好也。淮南書。奇牙出。靨輔搖。高注。靨輔、頰邊文。婦人之媚也。又曰。靨輔在頰則好。在顙則醜。注。靨䩉者、頰上窐也。由此言之。靨䩉在頰。故䩉與頰可互偁。古多借輔爲䩉。如毛詩傳曰。倩、好口輔也。此正謂靨䩉。咸上六。咸其輔頰舌。艮六五。艮其輔。其字皆當作䩉。葢自外言曰䩉、曰頰、曰靨䩉。自裏言則上下持牙之骨謂之䩉車、亦謂牙車、亦謂頷車、亦謂頰車、亦謂鼸車、亦謂之䩉、亦謂之頰。許言䩉頰也者、言其外也。易言䩉頰、言䩉、言其裏也。䩉車非外之䩉。頰車非外之頰。此名之當辨者也。諸家說左傳輔車相依、用牙車爲訓。"}]},"薙":{"expl":"除艸也。《明堂月令》曰：“季夏燒薙。”从艸雉聲。","rad":"艸","fq":"他計切","vol":"01","py":"tì","duan":[{"e":"除艸也。明堂月令曰。季夏燒薙。从艸。雉聲。","n":"他計切。案周禮雉氏掌殺草。雉或作夷。古雉音同夷。故鄭云字從類。類謂聲類也。大鄭從夷。後鄭從雉。而讀爲鬀。作薙者乃俗字。猶稻人芟夷字俗作芟荑也。月令燒薙。葢亦本作燒雉。許君說文本無薙字。淺人所羼入也。"}]},"䩌":{"expl":"面焦枯小也。从面、焦。","rad":"面","fq":"即消切","vol":"09","py":"jiāo","duan":[{"e":"面焦枯小也。","n":"玉篇引楚辭云。顏色䩌顇。希馮所據古本也。漢外戚傳。嫶姸大息。歎稚子兮。晉灼曰。三輔謂幽愁面省瘦曰嫶冥嫶姸猶嫶冥也。按嫶卽䩌字。省同㾪。"}]},"靨":{"expl":"姿也。从面厭聲。","rad":"面","fq":"於叶切","vol":"09","py":"yè","duan":[]},"丏":{"expl":"不見也。象壅蔽之形。凡丏之屬皆从丏。","rad":"丏","fq":"彌兖切","vol":"09","py":"miǎn","duan":[{"e":"不見也。象雝蔽之形。","n":"雝各本作壅。今正。其實許書當作邕也。禮經。乏參侯道。居侯黨之一。西五步。鄭曰。容謂之乏。所以爲獲者御矢也。周禮鄭司農注云。容者、乏也。待𫉬者所蔽。按之與丏篆文相似。義取蔽矢。豈禮經本作丏與。彌兖切。古音在十二部。以𡧍賓字知之。"}]},"首":{"expl":"𦣻同。古文𦣻也。巛象髪，謂之鬊，鬊卽巛也。凡𩠐之屬皆从𩠐。","rad":"首","fq":"書九切","vol":"09","py":"shǒu","duan":[{"e":"古文𦣻也。","n":"各本古文上有𦣻同二字。妄人所增也。許書絶無此例。惟麻下云與林同。亦妄人所增也。今刪。正義巳見上矣。故衹言古文𦣻。如儿下曰古文奇字人。？下曰籒文大。？下曰古文䭫。皆此例也。不見𩠐於𦣻篆之次者、以有从𩠐之篆。不得不出之爲部首也。今字則古文行而小篆廢矣。"}]},"䭬":{"expl":"下首也。从𩠐旨聲。","rad":"首","fq":"康禮切","vol":"09","py":"qǐ","duan":[{"e":"䭬首也。","n":"三字句。各本作下首也。亦由妄人不知三字句之例而改之。今正。頓首䭫首爲周禮九拜之二大耑。在漢末時。上書言事者必分別其辭。則二者形狀之不同。所用行禮之分別。許時人人知之。故小雅、大雅稽首。毛皆無傳。許亦但曰此篆謂䭫首、此篆謂頓首而巳。周禮䭫首、本又作稽。許沖上書。前作稽首。後作䭫首。恐今之經典轉寫譌亂者多矣。鄭曰。䭫首、句拜頭至地也。頓首、拜頭叩地也。葢䭫首者、拱手至地。頭亦至於地。而顙不必觸地。與頓首之必以顙叩地異矣。䭫首者、稽遲其首也。頓首亦曰䭫顙。䭫顙者、稽遲其顙也。此吉凶之大辨也。今人作名刺必曰頓首拜。是以凶禮施於賓禮、嘉禮。且頓首而拜、非卽䘮禮之稽顙而後拜乎。亦議禮者所當知矣。詳見？部、"}]},"𩠹":{"expl":"戳也。从𩠐从斷。","rad":"首","fq":"大丸切","vol":"09","py":"tuán","duan":[{"e":"𢧵𩠐也。","n":"首字各本奪。今補。斤部曰。斷者、𢧵也。戈部曰。𢧵者、斷也。𢧵首則字从斷首會意。集韵、類篇皆云斷首是也。廣雅。？、𣃔也。此引伸爲凡𢧵之偁也。"}]},"𥄉":{"expl":"到首也。賈侍中說：此斷首到縣𥄉字。凡𥄉之屬皆从𥄉。","rad":"𥄉","fq":"古堯切","vol":"09","py":"jiāo","duan":[{"e":"到𩠐也。","n":"到者今之倒字。此亦以形爲義之例。"}]},"縣":{"expl":"繫也。从系持𥄉。","rad":"𥄉","fq":"胡涓切","vol":"09","py":"xuán","duan":[{"e":"繫也。","n":"繫當作系。繫者繫𦃇也。一名惡絮。許書本非此字明矣。許自序云。據形系聯、不作繫也。系篆下云繫也。當卽縣也之譌。二篆爲轉注。古懸挂字皆如此作。引伸之、則爲所系之偁。周禮。縣系於遂。邑部曰。周制。天子地方千里。分爲百縣則系於國。秦漢縣系於郡。釋名曰。縣、縣也。縣係於郡也。自專以縣爲州縣字。乃別製从心之懸挂。別其音縣去懸平。古無二形二音也。顏師古云。古縣邑字作寰。亦爲臆說。"}]},"須":{"expl":"面毛也。从頁从彡。凡須之屬皆从須。","rad":"須","fq":"相俞切","vol":"09","py":"xū","duan":[{"e":"頤下毛也。","n":"各本譌作面毛也三字。今正。禮記禮運正義曰。案說文云耐者、鬚也。鬚謂頤下之毛象形字也。今本而篆下云頰毛也。須篆下云面毛也。語皆不通。毛？下云眉髮之屬。故眉解目上毛。須解頤下毛。須在頰者謂之䫇、不謂之而。釋須爲面毛則尢無理。須在頤下。頾在口上。䫇在頰。其名分別有定。釋名亦曰。口上曰髭。口下曰承漿。頤下曰鬚。在頰耳旁曰髥。與許說合。易賁六二。賁其須。侯果曰。自三至上、有頤之象。二在頤下、須之象也。引伸爲凡下垂之偁。凡上林賦之鶡蘇、吳都賦之流蘇、今俗云蘇頭皆卽須字也。俗假須爲需。別製䰅鬚字。"}]},"頿":{"expl":"口上須也。从須此聲。","rad":"須","fq":"即移切","vol":"09","py":"zī","duan":[{"e":"口上須也。","n":"在口上、在頰亦得名須。而正名百物則曰頾、曰？。左傳曰。至於靈王。生而有頾。是爲頾王。釋名曰。髭、姿也。爲姿容之美也。"}]},"䒹":{"expl":"耕多艸。从艸、耒，耒亦聲。","rad":"艸","fq":"盧對切","vol":"01","py":"lèi","duan":[{"e":"耕多艸。从艸耒。","n":"耒所以耕也。從耒艸㑹意。"}]},"䫇":{"expl":"頰須也。从須从冄，冄亦聲。","rad":"須","fq":"汝鹽切","vol":"09","py":"rán","duan":[{"e":"頰須也。","n":"頰、面旁也。釋名曰。隨口動搖。冄冄然也。封禪書有龍垂胡髥。下迎黃帝。詳文意乃泛謂須。"}]},"𩔹":{"expl":"須髮半白也。从須卑聲。","rad":"須","fq":"府移切","vol":"09","py":"bēi","duan":[{"e":"須髮半白也。","n":"兼言髮者、類也。此孟子頒白之正字也。趙注曰。頒者、斑也。頭半白斑斑者也。卑與斑雙聲。是以漢地理志卑水縣、孟康音斑。葢古？讀如斑。故亦假大頭之頒。藉田賦。士女頒斌。李注。頒斌、相襍之皃也。其引伸之義也。王制。諸侯曰頖宫。頖、葢？字之異體。故假爲泮水之泮。廣韵又借臥髻之䰉爲？。"}]},"䫠":{"expl":"短須髮皃。从須否聲。","rad":"須","fq":"敷悲切","vol":"09","py":"pī","duan":[{"e":"短須髮皃。","n":"西京賦說猛獸髬髵。薛曰。髬髵、作毛鬛也。髬卽？字。須髮短則植。猛獸毛鬛植。"}]},"彡":{"expl":"毛飾畫文也。象形。凡彡之屬皆从彡。","rad":"彡","fq":"所銜切","vol":"09","py":"shān","duan":[{"e":"毛飾畫文也。","n":"巾部曰。飾者、㕞也。飾畫者、㕞而畫之。毛者、聿也。亦謂之不律。亦謂之弗。亦謂之筆。所以畫者也。其文則爲彡。手之列多略不過三。故以彡象之也。毛所飾畫之文成彡。須髮皆毛屬也。故皆以爲彡之屬而从彡。"}]},"形":{"expl":"象形也。从彡幵聲。","rad":"彡","fq":"戶經切","vol":"09","py":"xínɡ","duan":[{"e":"象也。","n":"各本作𧰼形也。今依韵會本正。𧰼當作像。謂像似可見者也。人部曰。像、似也。似、像也。形容謂之形。因而形容之亦謂之形。六書二曰像形者謂形其形也。四曰形聲者、謂形其聲之形也。易曰。在天成象。在地成形。分偁之、實可互偁也。左傳。形民之力。假爲型模字也。易。其形渥。假爲㓝罰字也。"}]},"㐱":{"expl":"稠髮也。从彡从人。《詩》曰：“㐱髮如雲。”","rad":"彡","fq":"之忍切","vol":"09","py":"zhěn","duan":[{"e":"稠髮也。","n":"稠者多也。禾稠、曰稹。髮稠曰㐱。其意一也。"}]},"修":{"expl":"飾也。从彡攸聲。","rad":"彡","fq":"息流切","vol":"09","py":"xiū","duan":[{"e":"飾也。","n":"巾部曰。飾者、㕞也。又部曰。㕞者、飾也。二篆爲轉注。飾卽今之拭字。拂拭之則發其光采。故引伸爲文飾。女部曰。妝者、飾也。用飾引伸之義。此云修飾也者、合本義引伸義而兼舉之。不去其塵垢。不可謂之修。不加以縟采。不可謂之修。修之从彡者、洒㕞之也。藻繪之也。修者、治也。引伸爲凡治之偁。匡衡曰。治性之道。必審己之所有餘。而強其所不足。"}]},"彰":{"expl":"文彰也。从彡从章，章亦聲。","rad":"彡","fq":"諸良切","vol":"09","py":"zhānɡ","duan":[{"e":"彣彰也。","n":"彣各本作文。今正。文、逪畫也。與彣義別。古人作彣彰。今人作文章、非古也。尚書某氏傳、呂覽注、淮南注、廣雅皆曰。彰、朙也。通作章。"}]},"彫":{"expl":"琢文也。从彡周聲。","rad":"彡","fq":"都僚切","vol":"09","py":"diāo","duan":[{"e":"𤥨文也。","n":"𤥨者、治玉也。玉部有琱、亦治玉也。大雅。追琢其章。傳曰。追、彫也。金曰彫。玉曰𤥨。毛傳字當作琱。凡琱琢之成文曰彫。故字从彡。今則彫雕行而琱廢矣。"}]},"𩇕":{"expl":"清飾也。从彡青聲。","rad":"彡","fq":"疾郢切","vol":"09","py":"jìnɡ","duan":[{"e":"淸飾也。","n":"淸飾者、謂淸素之飾也。上林賦。靚莊刻飾。郭璞曰。靚莊、粉白黛黑也。刻飾、刻畫鬋鬢也。按靚莊卽𩇕妝之假借字。𩇕與水部之瀞義略同。"}]},"𦳙":{"expl":"艸大也。从艸致聲。","rad":"艸","fq":"陟利切","vol":"01","py":"zhì","duan":[]},"㣎":{"expl":"細文也。从彡，𡭴省聲。","rad":"彡","fq":"莫卜切","vol":"09","py":"mù","duan":[{"e":"細文也。","n":"細文、文之細者。故字从彡。彡者、文也。者、際見之白。際者、壁隙也。璺之細者也。引伸爲凡精美之偁。周頌曰。維天之命。於穆不已。傳曰。穆、美也。大雅傳曰。穆穆、美也。釋訓曰。穆穆、肅肅、敬也。皆其義也。古本作㣎。今皆从禾作穆。假借字也。古昭穆亦當用㣎。"}]},"弱":{"expl":"橈也。上象橈曲，彡象毛氂橈弱也。弱物并，故从二𢎥。","rad":"彡","fq":"而勺切","vol":"09","py":"ruò","duan":[{"e":"橈也。","n":"橈者曲木也。引伸爲凡曲之偁。直者多強。曲者多弱。易曰。棟橈。本末弱也。弱與橈㬪韵。"}]},"彩":{"expl":"文章也。从彡采聲。","rad":"彡","fq":"倉宰切","vol":"09","py":"cǎi","duan":[]},"彣":{"expl":"㦽也。从彡从文。凡彣之屬皆从彣。","rad":"彣","fq":"無分切","vol":"09","py":"wén","duan":[{"e":"𢒰也。","n":"有部曰。戫有彣彰也。是則有彣彰謂之彣。彣與文義別。凡言文章皆當作彣彰。作文章者、省也。文訓逪畫。與彣義別。"}]},"彥":{"expl":"美士有文，人所言也。从彣厂聲。","rad":"彣","fq":"魚變切","vol":"09","py":"yàn","duan":[{"e":"美士有彣。","n":"彣作文。非是。今正。"}]},"文":{"expl":"錯畫也。象交文。凡文之屬皆从文。","rad":"文","fq":"無分切","vol":"09","py":"wén","duan":[{"e":"錯畫也。","n":"錯當作逪、逪畫者䢒逪之畫也𦒱工記曰。靑與赤謂之文。逪畫之一耑也逪畫者、文之本義。彣彰者、彣之本義。義不同也。黃帝之史倉頡見鳥獸蹏迒之迹。知分理之可相別異也。初造書契。依類象形、故謂之文。"}]},"斐":{"expl":"分別文也。从文非聲。《易》曰：“君子豹變，其文斐也。”","rad":"文","fq":"敷尾切","vol":"09","py":"fěi","duan":[{"e":"分別文也。","n":"謂分別之文曰婓。衞風。有匪君子傳曰。匪文章皃。小雅。萋兮婓兮。傳曰。萋斐文章相錯也。𦒱工記注曰。匪采貌也。皆不言分別。許云分別者、渾言之則爲文。析言之則爲分別之文。以字从非知之也。非、違也。凡从非之屬。䨽、別也。靠、相違也。"}]},"辬":{"expl":"駁文也。从文辡聲。","rad":"文","fq":"布還切","vol":"09","py":"bān","duan":[{"e":"駁文也。","n":"謂駁襍之文曰辬也。馬色不純曰駁。引伸爲凡不純之偁。辬之字多或體。易卦之賁字、上林賦之斒字、史記璸斒、漢書文𨕖玢豳、俗用之斑字皆是。斑者、辬之俗。今乃斑行而辬廢矣。又或假班爲之。如孟堅之得氏以楚人謂虎文曰斑。卽虍部虨字也。作辬斑近是。而漢書作班。頭黑白半曰頒。亦辬之假借字。許知爲不純之文、以从辡知之。辦辯字皆从辡。"}]},"𣁟":{"expl":"微畫也。从文𠩺聲。","rad":"文","fq":"里之切","vol":"09","py":"lí","duan":[{"e":"微畫文也。","n":"文各本奪、今補。此謂微畫之文曰嫠也。凡今人用豪釐、當作此字。經解曰。差若豪氂謬以千里。乃是假借字。知爲微畫之文者、以从𠩺知之。𠩺者、坼也。微之意也。"}]},"髟":{"expl":"長髮猋猋也。从長从彡。凡髟之屬皆从髟。","rad":"髟","fq":"必凋切","vol":"09","py":"biāo","duan":[{"e":"長髮猋猋也。","n":"猋與髟曡韵。猋猋當依玉篇作髟髟。通俗文曰。髮垂曰髟。潘岳秋興賦。斑鬢髟以承弁。按馬融長笛賦。特麚昏髟。注。髟、長髦。廣成頌曰。羽旄紛其髟鼬。旚繇之假借字也。"}]},"䄆":{"expl":"祀也。从示𠯑聲。","rad":"示","fq":"古末切","vol":"01","py":"huó","duan":[{"e":"祀也。从示。𠯑聲。","n":"古末切。周禮注。禬、刮去也。疑𥙱乃禬字之或體也。十五部。已上三篆疑後人所增。"}]},"蔪":{"expl":"艸相蔪苞也。从艸斬聲。《書》曰：“艸木蔪苞。”","rad":"艸","fq":"慈冉切","vol":"01","py":"jiàn","duan":[{"e":"艸相蔪苞也。","n":"蔪苞卽今禹貢之漸包。釋文曰。漸本又作蔪。字林才冄反。艸之相包裹也。包或作苞。叢生也。馬云。相苞裹也。按叢生之義字作苞者是。"}]},"髮":{"expl":"根也。从髟犮聲。","rad":"髟","fq":"方伐切","vol":"09","py":"fà","duan":[{"e":"頭上毛也。","n":"各本作根也。廣韵巳然。以釋名廣雅正之。乃拔也之誤。要此二字可不必有耳。毛部曰。毛者、眉髮之屬。故眉下曰目上毛。須下曰頤下毛。則髮下必當有頭上毛也四字。且下文云鬢者、頰髮。不先言頭上、何以別其在頰者乎。今依玉篇、廣韵語正。"}]},"鬢":{"expl":"頰髮也。从髟賓聲。","rad":"髟","fq":"必刃切","vol":"09","py":"bìn","duan":[{"e":"頰髮也。","n":"謂髮之在面旁者也。晉語。美鬢長大則賢。韋昭曰。鬢、髮穎也。明道本如是。他本穎作類。非。髮穎者、穎禾末。近於𥝩。似人頸。故錐刀皆有穎。髮亦有穎。髮以項爲下。上至於頂。至於堖葢。而旁至於頰則謂之鬢。鬢者、髮之濱也。似禾穎之在末。禾之老、先𥝩而後莖。髮之老而白也、先鬢而餘髮繼之。項髮冣後。韋語俗多不解。故詳說之。釋名曰。在頰耳旁曰髥。其上連髮曰鬢。鬢曲頭曰距。"}]},"鬗":{"expl":"髮長也。从髟㒼聲。讀若蔓。","rad":"髟","fq":"母官切","vol":"09","py":"mán","duan":[{"e":"髮長皃。","n":"皃字依玉篇訂。引伸爲凡長之偁。如郊祀歌曰。掩回轅。鬗長馳。鬗猶今言道里曼曼也。如淳曰。音樠。"}]},"䰐":{"expl":"髮長也。从髟監聲。讀若《春秋》“黑肱以濫來奔”。","rad":"髟","fq":"魯甘切","vol":"09","py":"lán","duan":[{"e":"髮長也。","n":"集韵曰。䰐鬖、髮長皃。廣韵曰。䰐、鬢髮疎皃。"}]},"䰈":{"expl":"髮好也。从髟、差。","rad":"髟","fq":"千可切","vol":"09","py":"cuǒ","duan":[{"e":"髮好也。","n":"廣韵有皃字。"}]},"鬈":{"expl":"髮好也。从髟卷聲。《詩》曰：“其人美且鬈。”","rad":"髟","fq":"衢員切","vol":"09","py":"quán","duan":[{"e":"髮好也。","n":"也廣韵作皃。齊風盧令曰。其人美且鬈。傳曰。鬈、好皃。傳不言髮者、傳用其引伸之義。許用其本義也。本義謂髮好。引伸爲凡好之偁。凡說字必用其本義。凡說經必因文求義。則於字或取本義、或取引伸假借、有不可得而必者矣。故許於毛傳有直用其文者。凡毛、許說同是也。有相近而不同者。如毛曰鬈好皃、許曰髮好皃、毛曰飛而下曰頡、許曰直項也是也。此引伸之說也。有全違者。如毛曰匪文章皃、許曰器似竹匧、毛曰干澗也、許曰犯也是也。此假借之說也。經傳有假借。字書無假借。"}]},"髦":{"expl":"髮也。从髟从毛。","rad":"髟","fq":"莫袍切","vol":"09","py":"máo","duan":[{"e":"髦髮也。","n":"三字句。各本刪髦字、作髮也二字。此如巂下之刪雟作周燕也、離下之刪離、偓下之刪偓、江河等下之刪江河等字皆不可通。今補。玄應佛書音義卷二引說文。髦髮也。謂髮中之髦也。卷五引說文。髦髮也。髮中豪者也。下句乃古注語。上句亦奪一髦字、不可讀。髮中之秀出者、謂之髦髮。漢書謂之壯髮。馬鬣偁髦、亦其意也。詩三言髦士。爾雅、毛傳皆曰。髦、俊也。釋文云。毛中之長豪曰髦。士之俊傑者借譬爲名。此引伸之義也。古亦假髦爲毛字。旣夕禮注曰。今文髦爲毛。是今文禮叚毛爲髦也。"}]},"䰓":{"expl":"髮皃。从髟臱聲。讀若宀。","rad":"髟","fq":"莫賢切","vol":"09","py":"mián","duan":[{"e":"髮皃。","n":"玄應曰。凡鬘字皆當作䰓。"}]},"䯾":{"expl":"髮多也。从髟周聲。","rad":"髟","fq":"直由切","vol":"09","py":"tiáo","duan":[{"e":"髮多也。","n":"彡部曰。㐱者、稠髮也。稠髮當作䯾。此則說䯾之義。小雅曰。彼君子女。綢直如髮。傳曰。密直如髮也。是則綢乃䯾之假借字。"}]},"𩯨":{"expl":"髮皃。从髟爾聲。讀若江南謂酢母爲𩯨。","rad":"髟","fq":"奴礼切","vol":"09","py":"nǐ","duan":[{"e":"髮皃。从髟。爾聲。","n":"此字亦取爾會意。如華盛之字作薾。皆取麗爾之意也。"}]},"茀":{"expl":"道多艸，不可行。从艸弗聲。","rad":"艸","fq":"分勿切","vol":"01","py":"fú","duan":[{"e":"道多艸不可行。","n":"周語。火朝覿矣。道茀不可行也。注。草穢塞路爲茀。"}]},"䯽":{"expl":"髮皃。从髟咅聲。","rad":"髟","fq":"步矛切","vol":"09","py":"póu","duan":[{"e":"髮皃。从髟。咅聲。","n":"步矛切。四部。"}]},"𩭾":{"expl":"髮至眉也。从髟敄聲。《詩》曰：“紞彼兩𩭾。”","rad":"髟","fq":"亡牢切","vol":"09","py":"máo","duan":[{"e":"髮至眉也。","n":"庸風。髧彼兩髦。傳曰。髧、兩髦之皃。髦者、髮至眉。子事父母之飾。許所本也。內則拂髦注云。髦用髮爲之。象幼時鬌。其制未聞。旣夕禮曰。旣殯。主人說髦。注云。兒生三月。翦髮爲鬌。男角女羈。否則男左女右。長大猶爲之飾。存之謂之髦。所以順父母幼小之心。至此屍柩不見。䘮無飾。可以去之。髦之形象未聞。玉藻。親𣳚不髦。注云。去爲子之飾。按鄭旣言𩭾之用而云其制未聞者、謂其狀不可詳也。毛云髮至眉。葢以髮兩綹下垂至眉。像嬰兒夾冈之角髮下垂。父母在、不失其嬰兒之素也。依禮經曰脫。依內則注曰拂。髦振去塵箸之。是假他髮爲之。許引毛詩作𩭾。今則詩禮皆作髦。或由音近假借。𩭾與髦義古畫然不同。"}]},"鬋":{"expl":"女鬢垂皃。从髟前聲。","rad":"髟","fq":"作踐切","vol":"09","py":"jiǎn","duan":[{"e":"女鬢垂皃也。","n":"招䰟曰。盛鬋不同制。王云。鬋、鬢也。制、法也。言九侯之女。裝飾兩結。垂鬢下髮。形貌詭異。又長髮曼鬋。𧰟陸離些。注。曼、澤也。言美人長髮工結。鬢鬋滑澤。其狀𧰟美。儀皃陸離而難形也。按張揖注上林賦亦云。刻畫鬋鬢。鬋主謂女鬢。不施於男子。曲禮不蚤鬋。士虞禮蚤翦。翦或爲鬋。鬋皆翦之假借字也。喪大記爪手翦須、可證。曲禮注翦鬚。釋文作翦鬢。非是。"}]},"鬑":{"expl":"鬋也。一曰長皃。从髟兼聲。讀若慊。","rad":"髟","fq":"力鹽切","vol":"09","py":"lián","duan":[{"e":"鬋也。一曰長皃。","n":"此別一義。謂須髮之長。古陌上桑曰。爲人絜白晳。鬑鬑頗有鬚。"}]},"𩯰":{"expl":"束髮少也。从髟截聲。","rad":"髟","fq":"子結切","vol":"09","py":"jié","duan":[{"e":"束髮尐小也。","n":"尐小二字各本作少。廣韵十六㞕、十七薛引作少小二字。少乃尐之誤。今正。尐與？曡韵。面小亦謂之䩏尐。通俗文曰。露髻曰？。露髻者、士䘮禮婦人髽于室注云。旣去纚而以髮爲大紒、如今婦人露紒其象也。注䘮服亦云。髽、露紒也。然則露髻、漢人語。謂不用韜髮之縰、露髮爲髻也。今乃婦人無不露髻者矣。二京賦解訓？亦云露頭髻。按鄭云大髻、許云尐小者。其辭異、其爲粗率之意一也。"}]},"鬄":{"expl":"髲也。从髟易聲。","rad":"髟","fq":"先彳切","vol":"09","py":"xī","duan":[{"e":"髲也。","n":"庸風。不㞕髢也。箋云。髢、髲也。不絜者不用髲爲善。左傳。衞莊公見己氏之妻髮美。使髡之。以爲呂姜髢。按鬄與𩮜義別。音亦有異。"}]},"髲":{"expl":"鬄也。从髟皮聲。","rad":"髟","fq":"平義切","vol":"09","py":"bì","duan":[{"e":"益髮也。","n":"各本作鬄也二字。今正。庸風正義引說文云。髲、益髮也。言人髮少、聚他人髮益之。下十字古注語。髲字不見於經傳。假被字爲之。召南。被之僮僮。傳曰。被、首飾也。箋云。禮主婦髲𩮜。少牢饋食禮。主婦被錫。注曰。被錫讀爲髲𩮜。古者或𩮜賤者、㓝者之髮。以髲婦人之紒爲飾。因名髲𩮜焉。周禮所謂次也。按如鄭說、則詩禮之被皆卽髲也。以𩮜爲髲、卽是以𩮜爲鬄。許云益髮。不謂爲禮服。鄭說不同者、髲本髮少裨益之名。因用爲禮服之名。庸風不㞕髢也、自謂髮䯾。不假益髮爲髻。要燕居則縰筓總而巳。禮服筓總之後、必分別加副編次於上爲飾。副編次皆假他髮爲之也。周禮追師之次。禮經曰髲𩮜。詩曰被。"}]},"䯸":{"expl":"用梳比也。从髟次聲。","rad":"髟","fq":"七四切","vol":"09","py":"cì","duan":[{"e":"用梳比也。","n":"比者今之篦字。古衹作比。用梳比謂之䯸者、次第施之也。凡理髮先用梳。梳之言疏也。次用比。比之言宻也。周禮追師。爲副編次。注云。次者、次第髮長短爲之。疑次卽䯸。"}]},"髺":{"expl":"潔髮也。从髟𠯑聲。","rad":"髟","fq":"古活切","vol":"09","py":"kuò","duan":[{"e":"絜髮也。","n":"絜各本譌作潔。今依玉篇、韵會正。絜、麻一耑也。引伸爲圍束之偁。絜髮指束髮也。按士䘮禮主人髺髮。戴記作括髮。謂小斂訖、去纚爲露髻也。婦人之髽亦是去纚而髻。與男子之髺髮相等。則髺爲凶禮矣。然許於髽曰䘮髻、於髺不云䘮髻者、髺髮猶云束髮。內則䘮服之總、深衣之束髮、士䘮禮之鬠、同爲一事。鬠卽髺字之異者。髺非䘮服之專偁也。故士䘮禮之用組。以組束髮也。深衣之用錦。以錦束髮也。䘮服小記之始死括髮以麻。以麻束髮也。䘮服之布總。以布束髮也。其他縞總、素總。以縞、素束髮也。是皆得謂之髺。非凶禮之專辭也。士䘮禮注曰。髺古文作括。鬠古文作括。禮經髺髮、戴禮皆作括髮。則用古文與。周禮注引鬠用組、作𢶒。"}]},"䰉":{"expl":"臥結也。从髟般聲。讀若槃。","rad":"髟","fq":"薄官切","vol":"09","py":"pán","duan":[{"e":"臥結也。","n":"結今之髻字也。士冠禮采衣紒注云。古文紒爲結。按許書皆作結。鄭注經皆作紒。鄭依今文禮。許依古文禮。故系部有結無紒也。臥髻者葢謂寑時盤髮爲之。令可不𢽳。"}]},"苾":{"expl":"馨香也。从艸必聲。","rad":"艸","fq":"毗必切","vol":"01","py":"bì","duan":[{"e":"馨香也。","n":"見小雅。韓詩作馥。許君香部無馥字。從毛不從韓也。"}]},"𩬙":{"expl":"結也。从髟付聲。","rad":"髟","fq":"方遇切","vol":"09","py":"fù","duan":[{"e":"結也。","n":"廣韵云。露髻。"}]},"鬕":{"expl":"帶結飾也。从髟莫聲。","rad":"髟","fq":"莫駕切","vol":"09","py":"mà","duan":[{"e":"鬕帶、","n":"逗。"}]},"䰎":{"expl":"屈髮也。从髟貴聲。","rad":"髟","fq":"丘媿切","vol":"09","py":"kuì","duan":[{"e":"屈髮也。","n":"當依廣韵屈上有髻字。屈者、無尾也。引伸爲凡短之偁。方言。絡頭、帞頭也。紗繢、䰎帶䰂帶、𢂺、㡋、幧頭也。自關而西秦晉之郊曰絡頭。南楚江湘之閒曰帞頭。自河以北趙魏之閒曰幧頭。或謂之𢂺。或謂之㡋。其偏者謂之䰎帶。或謂之䰂帶。按䰎者、髻短髮之偁。方言之䰎帶謂帞頭帶於髻上也。帞頭之制、自項中而前交於額卻繞髻。"}]},"䯰":{"expl":"簪結也。从髟介聲。","rad":"髟","fq":"古拜切","vol":"09","py":"jiè","duan":[{"e":"簪結也。","n":"簪結者、旣簪之髻也。許以筓與兓互訓。而筓有固冕弁之筓、有固髮之筓。子事父母。櫛、縰筓、總、拂髦。此固髮爲髻之筓也。縰者、所以韜髮。韜之而後髻之。髻之而後簪之。旣簪之髻曰䯰。按䯰葢卽今文禮之紒。"}]},"鬣":{"expl":"髮鬣鬣也。从髟巤聲。","rad":"髟","fq":"良涉切","vol":"09","py":"liè","duan":[{"e":"髮鬣鬣也。","n":"？部巤下曰。毛巤也。象髮在？上及髦髮鬣鬣之形。鬛鬣、動而直上皃。所謂頭髮上指、髮上衝冠也。辭賦家言旌旗獵獵。是其假借字也。許意巤爲今馬鬣字。鬣爲顫動之字。今則鬣行而巤廢矣。人部曰。儠者、長壯儠儠也。字意略同。今左氏傳長儠作長鬛。杜以多須釋之。殊誤。須下垂、不偁鬣。凡上指者偁鬣。"}]},"䰕":{"expl":"鬣也。从髟盧聲。","rad":"髟","fq":"洛乎切","vol":"09","py":"lú","duan":[{"e":"鬣也。","n":"亦謂髮鬣鬣也。二篆雙聲。"}]},"髴":{"expl":"髴，若似也。从髟弗聲。","rad":"髟","fq":"敷勿切","vol":"09","py":"fú","duan":[{"e":"髴、","n":"此複舉字之未刪者。"}]},"髶":{"expl":"亂髮也。从髟，茸省聲。","rad":"髟","fq":"而容切","vol":"09","py":"rónɡ","duan":[{"e":"亂髮也。","n":"此與艸部茸義略同。"}]},"鬌":{"expl":"髮隋也。从髟，隋省。","rad":"髟","fq":"直追切","vol":"09","py":"chuí","duan":[{"e":"髮墮也。","n":"鉉本墮作隋。廣韵云。髮落是也。內則曰。三月之末。擇日翦髮爲鬌。男角女羈。鬌本髮落之名。因以爲存髮不翦者之名。故鄭注云。鬌、所遺髮也。方言、廣雅有毻字。江賦注所引字書有？字。皆謂落毛。與鬌義相近。"}]},"鬊":{"expl":"鬢髮也。从髟春聲。","rad":"髟","fq":"舒閏切","vol":"09","py":"shùn","duan":[{"e":"鬌髮也。","n":"士䘮禮曰。巾柶鬊爪埋于坎。䘮大記。君大夫鬊爪實于緣中。注曰。鬊、亂髮也。漢書曰。黑雲如猋風亂鬊。按鬊爲墮髮。而𩠐字下曰。髮謂之鬊。巛卽鬊也。則髮在頭者、亦非不可云鬊矣。"}]},"蔎":{"expl":"香艸也。从艸設聲。","rad":"艸","fq":"識列切","vol":"01","py":"shè","duan":[{"e":"香艸也。","n":"香艸當作艸香。前文菅芎已下十二字皆。說香艸。蔎芳蕡不與同列。而廁苾下。是非艸名可知也。劉向九歎。懷椒𦕼之蔎蔎。王注。椒𦕼、香草也。蔎蔎、香貌。"}]},"鬝":{"expl":"鬢秃也。从髟閒聲。","rad":"髟","fq":"苦閑切","vol":"09","py":"qiān","duan":[{"e":"鬢禿也。","n":"𦒱工記顅脰注曰。顅故書或作牼。鄭司農云。牼讀爲鬜頭無髮之鬜。按大鄭改牼爲鬜。而今書作顅。頁部云。顅、頭鬢少髮也。是鬜顅音義皆同。顅卽鬜也。明堂位注曰。齊人謂無髮爲禿楬。釋名曰。禿、無髮沐禿也。毼頭生瘡曰瘕。毼亦然也。毼與楬皆卽鬜也。"}]},"𩮜":{"expl":"鬀髮也。从髟从刀，易聲。","rad":"髟","fq":"他歴切","vol":"09","py":"tì","duan":[{"e":"鬀髮也。","n":"此篆今經典不見。而五經文字曰。𩮜聽亦反。見詩風注。所云詩風注、謂采蘩箋也。今箋云。禮記主婦髲髢。髢釋文作鬄。張參所見作𩮜爲是。葢鄭旣注禮、乃箋詩。自用其禮經注之說也。少牢饋食禮曰。主婦被錫。注云。被錫讀爲髲𩮜。古者或𩮜賤者、㓝者之髮。以髲婦人之紒爲飾。因名髲𩮜焉。周禮所謂次也。周禮追師注引少牢饋食禮主婦髲𩮜與詩箋皆自用其改易之字。而俗人多識鬄、少識𩮜。且誤認爲一字。於是二禮及詩注皆改𩮜爲鬄、爲髢。夫鬄髢同字、訓髲。髲者、益髮也。今俗所謂頭髲也。𩮜者、鬀髮也。然則鄭云𩮜髮以髲婦人之紒、卽𩮜髮以鬄婦人之紒也。倘經云髲鬄、直重字而己。於義安乎。推詳召南正義。孔沖遠所見禮注、詩箋不誤。而顏師古毛詩定本"}]},"髡":{"expl":"𩮜髮也。从髟兀聲。","rad":"髟","fq":"苦昆切","vol":"09","py":"kūn","duan":[{"e":"𩮜髮也。","n":"楚辭涉江。接輿髡首。王注云。髡、剔也。剔者、俗𩮜字。周禮。髡者使守積。注云。此必王之同族不宮者。宮之爲翦其類。髡之而巳。而部曰。罪不至髡。完其而鬢曰耏。"}]},"鬀":{"expl":"𩮜髮也。从髟弟聲。大人曰髡，小人曰鬀，盡及身毛曰𩮜。","rad":"髟","fq":"他計切","vol":"09","py":"tì","duan":[{"e":"𩮜髮也。","n":"鬀俗作剃。"}]},"𩮗":{"expl":"䰁也。从髟竝聲。","rad":"髟","fq":"蒲浪切","vol":"09","py":"bànɡ","duan":[{"e":"䰁也。从髟。竝聲。","n":"蒲浪切。十部。按竝聲本在十部。今俗謂卒然相遇曰掽。如滂去聲。字當作？也。"}]},"䰁":{"expl":"𩮗也。忽見也。从髟录聲。录，籒文魅，亦忽見意。","rad":"髟","fq":"芳未切","vol":"09","py":"fèi","duan":[{"e":"𩮗也。忽見也。","n":"按𩮗也二字衍文。集韵、類篇增一曰二字於忽見之上。尤非是。"}]},"髽":{"expl":"喪結。《禮》：女子髽衰，弔則不髽。魯臧武仲與齊戰于狐鮐，魯人迎喪者，始髽。从髟坐聲。","rad":"髟","fq":"莊華切","vol":"09","py":"zhuā","duan":[{"e":"喪結也。","n":"鄭注喪服曰。髽、露紒也。猶男子之括髮。斬衰括髮以麻。則髽亦用麻也。葢以麻自項而前交於額卻繞紒。如箸幧頭焉。注奔喪曰。去纚大紒曰髽。注檀弓曰。去纚而紒曰髽。戴先生曰。婦人當男子括髮。免則髽。齊斬之髽皆布總。"}]},"鬐":{"expl":"馬鬣也。从髟耆聲。","rad":"髟","fq":"渠脂切","vol":"09","py":"qí","duan":[]},"髫":{"expl":"小兒垂結也。从髟召聲。","rad":"髟","fq":"徒聊切","vol":"09","py":"tiáo","duan":[]},"髻":{"expl":"緫髮也。从髟吉聲。古通用結。","rad":"髟","fq":"古詣切","vol":"09","py":"jì","duan":[]},"芳":{"expl":"香艸也。从艸方聲。","rad":"艸","fq":"敷方切","vol":"01","py":"fānɡ","duan":[{"e":"香艸也。","n":"香艸當作艸香。"}]},"鬟":{"expl":"緫髮也。从髟睘聲。案：古婦人首飾，琢玉爲兩環。此二字皆後人所加。","rad":"髟","fq":"户關切","vol":"09","py":"huán","duan":[]},"后":{"expl":"繼體君也。象人之形。施令以告四方，故厂之。从一、口。發號者，君后也。凡后之屬皆从后。","rad":"后","fq":"胡口切","vol":"09","py":"hòu","duan":[{"e":"繼體君也。","n":"釋詁、毛傳皆曰。后、君也。許知爲繼體君者、后之言後也。開刱之君在先。繼體之君在後也。析言之如是。渾言之則不別矣。易象下傳曰。后以施命誥四方。虞云。后、繼體之君也。此許說也。葢同用孟易。經傳多假后爲後。大射注引孝經說曰。后者、後也。此謂后卽後之假借。"}]},"㖃":{"expl":"厚怒聲。从口、后，后亦聲。","rad":"后","fq":"呼后切","vol":"09","py":"hǒu","duan":[{"e":"厚怒聲。","n":"厚當作𣆪。𣆪與㖃㬪韵。諸書用呴字、卽此字也。聲類曰。呴、嗥也。俗作吼。"}]},"司":{"expl":"臣司事於外者。从反后。凡司之屬皆从司。","rad":"司","fq":"息兹切","vol":"09","py":"sī","duan":[{"e":"臣司事於外者。","n":"外對君而言。君在內也。臣宣力四方在外。故从反后。鄭風。邦之司直。傳曰。司、主也。凡主其事必伺察恐後。故古別無伺字。司卽伺字。見部曰。覹、司也。䙾、司人也。人部曰。伏、司也。𠊱司望也。頁部曰。䫔、司人也。㹜部曰。䫔、司也。豸下曰。欲有所司殺。皆卽今之伺字。周禮師氏、媒氏、禁殺戮之注皆云。司猶察也。俗又作覗。凡司其事者皆得曰有司。"}]},"詞":{"expl":"意内而言外也。从司从言。","rad":"司","fq":"似兹切","vol":"09","py":"cí","duan":[{"e":"意內而言外也。","n":"有是意於內、因有是言於外謂之䛐。此語爲全書之凡例。全書有言意者。如？言意、欪無腸意、㱇悲意、㒄膬意之類是也。有言䛐者。如欥詮䛐也、者別事䛐也、皆俱䛐也、？䛐也、魯鈍䛐也、？識䛐也、曾䛐之舒也、乃䛐之難也、尒䛐之必然也、矣語巳䛐也、矤兄䛐也、𠣤驚䛐也、？屰惡驚䛐也、？屰鬼警䛐也、臮衆與䛐也之類是也。意卽意內。䛐卽言外。言意而䛐見。言䛐而意見。意者、文字之義也。言者、文字之聲也。䛐者、文字形聲之合也。凡許之說字義皆意內也。凡許之說形、說聲皆言外也。有義而後有聲。有聲而後有形。造字之本也。形在而聲在焉。形聲在而義在焉。六藝之學也。䛐與辛部之辭、其義迥別。辭者、說也。从𤔔辛。𤔔辛猶理辜。謂文辭足以排難"}]},"卮":{"expl":"圜器也。一名觛。所以節飲食。象人，卪在其下也。《易》曰：“君子節飲食。”凡巵之屬皆从巵。","rad":"卮","fq":"章移切","vol":"09","py":"zhī","duan":[{"e":"圜器也。","n":"內則注曰。卮匜、酒漿器。"}]},"𡭐":{"expl":"小巵有耳蓋者。从巵專聲。","rad":"卮","fq":"市沇切","vol":"09","py":"shuàn","duan":[{"e":"小卮有耳葢者。","n":"急就篇皇象本槫榼椑榹。槫卽？也。有耳葢、謂有耳有葢也。"}]},"𦓚":{"expl":"小巵也。从巵耑聲。讀若捶擊之捶。","rad":"卮","fq":"旨沇切","vol":"09","py":"zhuǎn","duan":[{"e":"小卮也。","n":"顏師古急就篇椯榼椑榹。椯卽？也。"}]},"卩":{"expl":"瑞信也。守國者用玉卪，守都鄙者用角卪，使山邦者用虎卪，士邦者用人卪，澤邦者用龍卪，門關者用符卪，貨賄用璽卪，道路用旌卪。象相合之形。凡卪之屬皆从卪。","rad":"卩","fq":"子結切","vol":"09","py":"jié","duan":[{"e":"瑞信也。","n":"瑞者、以玉爲信也。周禮典瑞注曰。瑞、節信也。典瑞若今符璽郞。掌節注曰。節猶信也。行者所執之信。邦節者、珍圭、牙璋、榖圭、琬圭、？圭也。按是五玉者皆王使之瑞卪。引伸之凡使所執以爲信、而非用玉者皆曰卪。下文是也。"}]},"令":{"expl":"發號也。从亼、卪。","rad":"卩","fq":"力正切","vol":"09","py":"lìnɡ","duan":[{"e":"發號也。","n":"号部曰。號者、嘑也。口部曰。嘑者、號也。發號者、發其號嘑以使人也。是曰令。人部曰。使者。令也。義相轉注。引伸爲律令、爲時令。詩箋曰。令、善也。按詩多言令。毛無傳。古文尚書言靈。見般庚、多士、多方。般庚正義引釋詁。靈、善也。葢今本爾雅作令、非古也。凡令訓善者、靈之假借字也。"}]},"蕡":{"expl":"雜香艸。从艸賁聲。","rad":"艸","fq":"浮分切","vol":"01","py":"fén","duan":[{"e":"襍香艸。","n":"當作襍艸香。葢此字之本義。若有蕡其實。特假借爲墳大字耳。"}]},"𠨒":{"expl":"輔信也。从卪比聲。《虞書》曰：“𠨒成五服。”","rad":"卩","fq":"毗必切","vol":"09","py":"bì","duan":[]},"卶":{"expl":"有大度也。从卪多聲。讀若侈。","rad":"卩","fq":"充豉切","vol":"09","py":"chǐ","duan":[{"e":"有大慶也。","n":"慶各本作度。今依廣韵正。慶者、行賀人也。大慶、謂大可賀之事也。凡从多之字訓大。釋言曰。庶、侈也。是其義。"}]},"𠨘":{"expl":"宰之也。从卪必聲。","rad":"卩","fq":"兵媚切","vol":"09","py":"bì","duan":[{"e":"宰之也。","n":"未聞。葢謂主宰之也。主宰之則制其必然故从必。按衞風。有斐君子。釋文云。韓詩作𠨘、美皃。葢卽此字。而今本釋文及廣韵皆誤从邑、作邲。廣韵六至云。邲、好皃。五質云。邲地名。在鄭。又美皃。其誤甚矣。"}]},"卲":{"expl":"高也。从卪召聲。","rad":"卩","fq":"寔照切","vol":"09","py":"shào","duan":[{"e":"高也。","n":"廣雅釋詁同。法言曰。公儀子、董仲舒之才之卲也。又曰。賢皆不足卲也。"}]},"厄":{"expl":"科厄，木節也。从卪厂聲。賈侍中說，以爲厄，裹也。一曰厄，蓋也。","rad":"卩","fq":"五果切","vol":"09","py":"ě","duan":[{"e":"科厄、","n":"逗曡韵字。"}]},"厀":{"expl":"脛頭卪也。从卪桼聲。","rad":"卩","fq":"息七切","vol":"09","py":"xī","duan":[{"e":"脛頭卪也。","n":"肉部曰。腳、脛也。脛。胻也。厀者在脛之首。股與腳閒之卪也。故从卪。"}]},"卷":{"expl":"厀曲也。从卪𢍏聲。","rad":"卩","fq":"居轉切","vol":"09","py":"juǎn","duan":[{"e":"厀曲也。","n":"卷之本義也。引伸爲凡曲之偁。大雅。有卷者阿。傳曰。卷、曲也。又引伸爲舒卷。論語。邦無道。則可卷而懷之。卽手部之捲收字也。又中庸。一卷石之多。注曰。卷猶區也。又陳風。碩大且卷。傳曰。卷、好皃。此與齊風傳鬈、好皃同。謂卽一字也。檀弓。女手卷然。亦謂好皃。"}]},"卻":{"expl":"節欲也。从卪谷聲。","rad":"卩","fq":"去約切","vol":"09","py":"què","duan":[{"e":"卪卻也。","n":"各本作節欲也。誤。今依玉篇欲爲卻。又改節爲卪。卪卻者、節制而卻退之也。"}]},"卸":{"expl":"舍車解馬也。从卪、止、午。讀若汝南人寫書之寫。","rad":"卩","fq":"司夜切","vol":"09","py":"xiè","duan":[{"e":"舍車解馬也。","n":"舍、止也。馬以駕車。止車則解馬矣。一說解馬謂騎解鞌。方言曰。發、舍車也。東齊海岱之閒謂之發。宋趙陳魏之閒謂之稅。郭注。今通言發寫。按發寫卽發缷也。寫者卸之假借字。曲禮曰。器之漑者不寫。其餘皆寫。義正同卸。今卸爲通用俗語。"}]},"𠨖":{"expl":"二卪也。巽从此。闕。","rad":"卩","fq":"士戀切","vol":"09","py":"zhuàn","duan":[{"e":"二卪也。","n":"義取於形。"}]},"藥":{"expl":"治病艸。从艸樂聲。","rad":"艸","fq":"以勺切","vol":"01","py":"yào","duan":[{"e":"治病艸。","n":"玉篇引作治疾病之艸緫名。"}]},"㔿":{"expl":"卪也。闕。","rad":"卩","fq":"則𠊱切","vol":"09","py":"zòu","duan":[{"e":"卪也。闕","n":"按玉篇曰。說文云闕。葢本衹有闕字。其形反卪。其義其音則葢闕。今本說其義云卪也。說其音云則𠊱切。皆肊爲之。非許意。"}]},"印":{"expl":"執政所持信也。从爪从卪。凡印之屬皆从印。","rad":"印","fq":"於刃切","vol":"09","py":"yìn","duan":[{"e":"執政所持信也。","n":"凡有官守者皆曰執政。其所持之卪信曰印。古上下通曰璽。周禮壐節注曰。今之印章。按周禮。守邦國者用玉節。守都鄙者用角節。謂諸侯於其國中、公卿大夫於其采邑用之。是卽用印之始也。季武子於周禮爲守都鄙者、而以璽書、達於魯君。是古有印明矣。葢以𥳑書之。而寓書於遠必用布帛檢之。以璽泥？之。至用縑素爲書、而印之用更廣。漢官儀。諸侯王黃金槖駝鈕、文曰璽。列侯黃金龜紐、文曰章。御史大夫金印紫綬、文曰章。中二千石銀印龜紐、文曰章。千石至四百石皆銅印、文曰印。"}]},"𢑏":{"expl":"按也。从反印。","rad":"印","fq":"於棘切","vol":"09","py":"yì","duan":[{"e":"按也。","n":"按當作按印也。淺人刪去印字耳。按者、下也。用印必向下按之。故字从反印。淮南齊俗訓曰。若璽之抑埴。正與之正。傾與之傾。璽之抑埴卽今俗云以印印泥也。此抑之本義也。引伸之爲凡按之偁。内則。而敬抑搔之。注曰。抑、按也。又引伸之爲凡謙下之偁。賓筵傳曰。抑抑、愼密也。假樂傳曰。抑抑、美也。抑傳曰。抑抑、密也。猗嗟傳曰。抑、美色。論語三用抑字皆轉語䛐。於按下之意相近。抑詩、國語作懿戒。懿同抑抑此皇父。懿厥哲婦。懿亦同抑、鄭云。抑之言噫。有所痛傷之聲也。"}]},"色":{"expl":"顔气也。从人从卪。凡色之屬皆从色。","rad":"色","fq":"所力切","vol":"09","py":"sè","duan":[{"e":"顏气也","n":"顏者兩眉之閒也心達於气。气達於眉閒是之謂色。顏气與心若合符卪。故其字从人卪。記曰。孝子之有深愛者、必有和气。有和气者必有愉色。有愉色者、必有婉容、又曰。戎容。盛氣闐實陽休。玉色。孟子曰。仁義理智根於心、其生色也。睟然見於面。此皆从人卪之理也。主色而後見於面。所謂陽氣浸淫。幾滿大宅、許曰。面顏前也是也。魯頌。載色載笑。傳曰。色色温潤也。大雅。令儀令色。箋云。善威儀、善顏色也。內則曰。柔色以温之。玉藻曰。色容莊。色容顚顚。色容厲肅。論語曰。色難。色思温。色勃如也。正顏色。引伸之爲凡有形可見之偁。"}]},"艴":{"expl":"色艴如也。从色弗聲。《論語》曰：“色艴如也。”","rad":"色","fq":"蒲没切","vol":"09","py":"bó","duan":[{"e":"色艴如也。","n":"按此當作艴怒色也。孟子。曾西艴然不悅。趙曰。艴、愠怒色也。"}]},"艵":{"expl":"縹色也。从色并聲。","rad":"色","fq":"普丁切","vol":"09","py":"pīnɡ","duan":[{"e":"縹色也。","n":"縹者、帛靑白色也。李善注神女賦。頩薄怒以自持。引方言。頩怒色靑皃。今方言無此語。玉篇引楚辭。玉色艵以脕顏。今遠遊作頩。頩與艵同也。按許不云怒色縹、但云縹色者、人或色靑不必怒也。遠遊。玉色艵以脕顏。謂光澤鮮好。不謂怒色。大招說美人亦云。靑色直眉。"}]},"𠨍":{"expl":"事之制也。从卩、㔿。凡𠨍之屬皆从𠨍。闕。","rad":"𠨍","fq":"去京切","vol":"09","py":"qīnɡ","duan":[]},"卿":{"expl":"章也。六卿：天官冢宰、地官司徒、春官宗伯、夏官司馬、秋官司寇、冬官司空。从𠨍皀聲。","rad":"𠨍","fq":"去京切","vol":"09","py":"qīnɡ","duan":[{"e":"章也。","n":"此以曡韵爲訓。白虎通曰。卿之爲言章也。章善明理也。"}]},"辟":{"expl":"法也。从卩从辛，節制其辠也；从口，用法者也。凡辟之屬皆从辟。","rad":"辟","fq":"必益切","vol":"09","py":"bì","duan":[{"e":"法也。","n":"法當作灋。小雅。辟言不信。大雅。無自立辟。傳皆曰。辟、法也。又文王有聲箋、抑箋、周禮鄉師注、戎右注、小司寇注、曲禮下注皆同。引伸之爲罪也。見釋詁。謂犯法者、則執法以罪之也。又引伸之爲辟除。如周禮閽人爲之辟、孟子行辟人、以及辟寒、辟惡之類是也。又引伸之爲盤辟。如禮經之辟、鄭注逡遁是也。又引伸爲一邊之義。如左傳曰闕西辟是也。或借爲僻。或借爲避。或借爲譬。或借爲闢。或借爲壁。或借爲襞。"}]},"𨐨":{"expl":"治也。从辟从井。《周書》曰：“我之不𨐨。”","rad":"辟","fq":"必益切","vol":"09","py":"bì","duan":[{"e":"法也。","n":"各本作治也。今依尙書釋文正。金縢云。我之弗辟。某氏云。治也。馬鄭音避。謂避居東都。說文作𨐨。云必亦反。法也。"}]},"䕻":{"expl":"艸木相附䕻土而生。从艸麗聲。《易》曰：“百榖艸木䕻於地。”","rad":"艸","fq":"呂支切","vol":"01","py":"lí","duan":[{"e":"艸木生箸土。","n":"箸丈略切。此依韵㑹引。"}]},"䢃":{"expl":"治也。从辟乂聲。《虞書》曰：“有能俾䢃。”","rad":"辟","fq":"魚廢切","vol":"09","py":"yì","duan":[{"e":"治也。","n":"丿部曰。乂、芟艸也。今則乂訓治而䢃廢矣。詩作艾。小雅小旻傳曰。艾、治也。"}]},"勹":{"expl":"裹也。象人曲形，有所包裹。凡勹之屬皆从勹。","rad":"勹","fq":"布交切","vol":"09","py":"bāo","duan":[{"e":"裹也。","n":"今字包行而勹廢矣。"}]},"𠤄":{"expl":"曲𦟝也。从勹，𥷚省聲。","rad":"勹","fq":"巨六切","vol":"09","py":"jū","duan":[{"e":"曲𦟝也。","n":"此論語鄉黨、聘禮記鞠躬之正字也。聘禮鞠躬亦作鞠窮。史記魯世家作匑？。徐廣云。見三蒼。謹敬皃也。音穹窮。廣雅亦曰。匑？、謹敬也。漢書注曰。鞠躬、謹敬也。葢上字丘弓切、下字巨弓切、爲曡韵。如左傳鞠窮之卽？藭耳。上字亦讀丘六切。仍是聯綿字。孔注論語曰斂身。許曰曲脊。葢未有謹敬而不傴僂者也。許無匑？字者、以？躬爲正字。鞠則？之假借字也。鞠躬行而？廢矣。"}]},"匍":{"expl":"手行也。从勹甫聲。","rad":"勹","fq":"簿乎切","vol":"09","py":"pú","duan":[{"e":"手行也。","n":"今人以手摸𡩡。其語薄乎切。當作此字。"}]},"匐":{"expl":"伏地也。从勹畐聲。","rad":"勹","fq":"蒲北切","vol":"09","py":"fú","duan":[{"e":"伏地也。","n":"匐伏曡韵。釋名曰。匍匐、小兒時也。匍猶捕也。藉索可執取之言也。匐、伏也。伏地行也。人雖長、大。及其求事盡力之勤、猶亦稱之。詩曰凡民有䘮、匍匐救之是也。按二篆可、合用、可析言。"}]},"匊":{"expl":"在手曰匊。从勹、米。","rad":"勹","fq":"居六切","vol":"09","py":"jū","duan":[{"e":"在手曰匊。","n":"唐風。椒聊之實。蕃衍盈匊。小雅。終朝采綠。不盈一匊。毛皆云。兩手曰匊。此云在手。恐傳寫之誤。手部曰。持、握也。握、搤持也。搤、捉也。捉、搤也。把握也。然則在手曰捉、曰搤、曰握、曰持、曰把。不曰匊也。據篇、韵所言則許書之譌久矣。玉篇曰。古文作臼。此語尤誤。臼者、叉手也。叉者、手指相錯也。廣韵以兩手奉物訓臼、誤矣。方言曰。掬、離也。燕之外郊朝鮮洌水之閒曰掬。此方俗殊語。不係乎本字也。"}]},"勻":{"expl":"少也。从勹、二。","rad":"勹","fq":"羊倫切","vol":"09","py":"yún","duan":[{"e":"少也。","n":"少當作帀。字之誤也。帀者、？也。？者、帀徧也。徧者、帀也。是可以得勻之義矣。廣韵曰。勻、徧也。齊也。作少必譌。"}]},"勼":{"expl":"聚也。从勹九聲。讀若鳩。","rad":"勹","fq":"居求切","vol":"09","py":"jiū","duan":[{"e":"聚也。","n":"釋詁曰。鳩、聚也。左傳作鳩。古文尙書作逑。辵部曰。逑、斂聚也。莊子作九。今字則鳩行而勼廢矣。"}]},"旬":{"expl":"徧也。十日爲旬。从勹、日。","rad":"勹","fq":"詳遵切","vol":"09","py":"xún","duan":[{"e":"徧也。","n":"小徐無也字。非是。大雅。王命召虎。來旬來宣。傳曰。旬、徧也。菀彼桑柔。其下侯旬。傳曰。旬言陰均也。周禮均人。豐年則公旬用三日焉。注曰。旬均也。讀如㽦㽦原隰之㽦。易。坤爲均。今書亦有作旬者。內則。旬而見。注曰。旬當爲均。嫡、妾同時生子。以生先後見之也。易說卦。坤爲均。今亦或作旬。按旬與均音義皆略同。土部曰。均、平徧也。又按許書古文鈞作銞。儀禮今文絢作？。知古旬勻二篆、相假爲用。"}]},"勽":{"expl":"覆也。从勹覆人。","rad":"勹","fq":"薄皓切","vol":"09","py":"bào","duan":[{"e":"覆也。","n":"此當爲抱子、抱孫之正字。今俗作抱、乃或捊字也。衣部之袌、則訓裏也。"}]},"蓆":{"expl":"廣多也。从艸席聲。","rad":"艸","fq":"祥易切","vol":"01","py":"xí","duan":[{"e":"廣多也。","n":"鄭風。緇衣之蓆兮。釋故、毛傳皆云。蓆、大也。韓詩云。儲也。廣義與大近。多義與儲近。"}]},"匈":{"expl":"聲也。从勹凶聲。","rad":"勹","fq":"許容切","vol":"09","py":"xiōnɡ","duan":[{"e":"膺也。","n":"肉部曰。膺、匈也。二篆爲轉注。膺自其外言之無不當也。匈自其中言之、無不容也。無不容、故从勹。"}]},"𠣘":{"expl":"帀徧也。从勹舟聲。","rad":"勹","fq":"職流切","vol":"09","py":"zhōu","duan":[{"e":"帀徧也。","n":"徧衍文。當刪。帀下曰。？也。與此爲轉注。帀則無不徧者。不待言徧也。？與周義別。口部曰。周者、密也。周自其中之密言之。？自其外之極復言之。凡圜周、方周、周而復始、其字當作？。謂其極而復也。凡圜幂、方幂、幂積謂之周。謂其至密無疏罅也。左傳以周疏對文、是其義。今字周行而？廢。槩用周字。或又作週。殊爲乖舛。名之當正者也。有帀而不密者。有密而不帀者。故其字宜辨也。宙者、舟輿所極復。？與宙音義皆相近。易曰。周流六虚。葢自古叚周爲？矣。"}]},"匌":{"expl":"帀也。从勹从合，合亦聲。","rad":"勹","fq":"矦閣切","vol":"09","py":"ɡé","duan":[{"e":"帀也。","n":"匌之言合也。帀而與朔合矣。海賦曰。磊匒匌而相虺。按釋詁曰。㪉、郃、合也。郃乃地名。於義無取。當爲匌字之假借也。"}]},"𠣿":{"expl":"飽也。从勹㲃聲。民祭，祝曰：“厭𠣿。”","rad":"勹","fq":"己又切","vol":"09","py":"jiù","duan":[{"e":"飽也。从勹。","n":"象腹。"}]},"𠣾":{"expl":"重也。从勹復聲。","rad":"勹","fq":"扶富切","vol":"09","py":"fù","duan":[{"e":"重也。","n":"今則複行而？廢矣。"}]},"冢":{"expl":"高墳也。从勹豖聲。","rad":"勹","fq":"知隴切","vol":"09","py":"zhǒnɡ","duan":[{"e":"高墳也。","n":"土部曰。墳者、墓也。墓之高者曰冢。周禮冢人掌公墓之地是也。按釋山云。山頂曰冢。鄭注冢人云。冢、封土爲丘壟。象冢而爲之。此從爾雅說也。許以冢爲高墳之正偁。則不用爾雅說。引伸之凡高大曰冢。釋山及十月之交傳。山頂曰冢。乃借冢偁耳。釋詁曰。冢、大也。太子曰冢子。太宰曰冢宰。"}]},"包":{"expl":"象人褢妊，巳在中，象子未成形也。元气起於子。子，人所生也。男左行三十，女右行二十，俱立於巳，爲夫婦。褢妊於巳，巳爲子，十月而生。男起巳至寅，女起巳至申。故男秊始寅，女秊始申也。凡包之屬皆从包。","rad":"包","fq":"布交切","vol":"09","py":"bāo","duan":[{"e":"妊也。","n":"二字各本無。今推文意補。下文十三字乃說字形、非說義。則必當有說義之文矣。女部曰。妊者、孕也。子部曰。孕者、褢子也。引伸之爲凡外裹之偁。亦作苞。皆假借字。凡經傳言苞苴者、裹之曰苞。藉之曰苴。"}]},"胞":{"expl":"兒生裹也。从肉从包。","rad":"包","fq":"匹交切","vol":"09","py":"bāo","duan":[{"e":"兒生裹也。","n":"包謂母腹。胞謂胎衣。小雅。不屬于毛。不離于裏。箋云。今我獨不得父皮膚之氣乎。獨不處母之胞胎乎。釋文胞音包。今俗語同胞是也。其借爲脬字、則讀匹交切。脬者、旁光也。腹中水府也。"}]},"匏":{"expl":"瓠也。从包，从夸聲。包，取其可包藏物也。","rad":"包","fq":"薄交切","vol":"09","py":"páo","duan":[{"e":"瓠也。","n":"瓠下曰。匏也。與此爲轉注。匏判之曰蠡、曰瓢、曰？。邶風傳曰。匏謂之瓠。謂異名同實也。豳風傳曰。壺、瓠也。此謂壺卽瓠之假借字也。"}]},"茍":{"expl":"自急敕也。从羊省，从包省。从口，口猶愼言也。从羊，羊與義、善、美同意。凡茍之屬皆从茍。","rad":"茍","fq":"己力切","vol":"09","py":"jì","duan":[{"e":"自急敕也。","n":"急與苟雙聲。敕與苟曡韵。急者、褊也。敕者、誡也。此字不見經典。惟釋詁。寁駿肅亟遄速也。釋文云。亟字又作苟、同。居力反。經典亦作棘、同。是其證。可謂一字千金矣。而通志堂刻乃改爲急字。葢誤仭爲从艸之苟也。急不得反居力。與亟棘音大殊。幸抱經堂刻正之。或欲易禮經之苟敬爲苟、則又繆。○小雅六月、古作我是用戒。亦作我是用棘。俗本改作急。與飭服國不韵。正同此。"}]},"芟":{"expl":"刈艸也。从艸从殳。","rad":"艸","fq":"所銜切","vol":"01","py":"shān","duan":[{"e":"刈艸也。","n":"見周頌、周禮。毛云。除艸曰芟。"}]},"敬":{"expl":"肅也。从攴、茍。","rad":"茍","fq":"居慶切","vol":"09","py":"jìnɡ","duan":[{"e":"肅也。","n":"肅部曰。肅者持事振敬也。與此爲轉注。心部曰。忠、敬也。戁、敬也。憼、敬也。恭肅也。憜不敬也。義皆相足。後儒或云主一無適爲敬。夫主一與敬義無渉。且文子曰。一也者、無適之道。淮南詮言曰。一者、萬物之本也。無敵之道也。適卽敵字、非他往之謂。"}]},"鬼":{"expl":"人所歸爲鬼。从人，象鬼頭。鬼陰气賊害，从厶。凡鬼之屬皆从鬼。","rad":"鬼","fq":"居偉切","vol":"09","py":"ɡuǐ","duan":[{"e":"人所歸爲鬼。","n":"以曡韵爲訓。釋言曰。鬼之爲言歸也。郭注引尸子。古者謂死人爲歸人。左傳。子產曰。鬼有所歸。乃不爲厲。禮運曰。䰟氣歸於天。形魄歸於地。"}]},"䰠":{"expl":"神也。从鬼申聲。","rad":"鬼","fq":"食鄰切","vol":"09","py":"shén","duan":[{"e":"神也。","n":"當作神鬼也。神鬼者、鬼之神者也。故字从鬼申。老子曰。其鬼不神。封禪書曰。秦中冣小鬼之神者。中山經。靑要之山。䰠武羅司之。郭云。䰠卽神字。許意非一字也。"}]},"魂":{"expl":"陽气也。从鬼云聲。","rad":"鬼","fq":"戶昆切","vol":"09","py":"hún","duan":[{"e":"陽气也。","n":"陽當作昜。白虎通曰。䰟者、沄也。猶沄沄行不休也。淮南子曰。天气爲䰟。左傳。子產曰。人生始化曰魄。旣生魄。陽曰䰟。用物精多。則䰟魄強。"}]},"魄":{"expl":"陰神也。从鬼白聲。","rad":"鬼","fq":"普百切","vol":"09","py":"pò","duan":[{"e":"陰神也。","n":"陰當作侌。陽言气、陰言神者、陰中有陽也。白虎通曰。魄者、迫也。猶迫迫然箸於人也。淮南子曰。地氣爲魄。祭義曰。氣也者、神之盛也。魄也者、鬼之盛也。鄭云。氣謂嘘吸出入者也。耳目之聰明爲魄。郊特牲曰。䰟氣歸於天。形魄歸於地。祭義曰。死必歸土。此之謂鬼。其氣發揚於上。神之箸也。是以聖人尊名之曰鬼神。按䰟魄皆生而有之而字皆从鬼者、䰟魄不離形質而非形質也。形質亡而䰟魄存。是人所歸也。故从鬼。"}]},"䰡":{"expl":"厲鬼也。从鬼失聲。","rad":"鬼","fq":"丑利切","vol":"09","py":"chì","duan":[{"e":"厲鬼也。","n":"厲之言烈也。厲鬼謂虐厲之鬼。厲或作癘。非。左傳曰。其何厲鬼也。月令注曰。昴有大陵積尸之氣。氣佚則厲鬼隨而出行。虚危有墳墓四司之氣。爲厲鬼、將隨強陰出害人。西山經。剛山是多神？。？卽此䰡字。郭云。离魅之類也。恥二反。或作？。今本山海經傳譌舛。依集韵、類篇正。"}]},"魖":{"expl":"耗神也。从鬼虚聲。","rad":"鬼","fq":"朽居切","vol":"09","py":"xū","duan":[{"e":"秏鬼也。","n":"秏舊作耗。今正。秏者、乏無之言。東京賦曰。殘䕫魖與㒺象。䕫、木石之怪也。㒺象、水之怪也。與魖爲三物。"}]},"魃":{"expl":"旱鬼也。从鬼犮聲。《周禮》有赤魃氏，除牆屋之物也。《詩》曰：“旱魃爲虐。”","rad":"鬼","fq":"蒲撥切","vol":"09","py":"bá","duan":[{"e":"旱鬼也。","n":"大雅雲漢曰。旱魃爲虐。傳曰。魃、旱神也。此言旱鬼、以字从鬼也。神鬼統言之則一耳。山海經曰。大荒之中。有山名曰不句。有黃帝女妭。本天女也。黃帝下之殺蚩尢。不得復上。所居不雨。妭卽魃也。詩正義不引此而引神異經。神異經乃不知何人假託東方朔者。郭傳山海經不云妭卽詩之旱魃、而云音如旱魃之魃。疏矣。女部曰。妭、婦人美皃。然則山海經爲假借字。"}]},"鬽":{"expl":"老精物也。从鬼、彡。彡，鬼毛。","rad":"鬼","fq":"密祕切","vol":"09","py":"mèi","duan":[{"e":"老物精也。","n":"各本作精物。今依蕪城賦王莽傳二注正。論衡曰。鬼者、老物之精也。漢藝文志有神鬼精物之語。則作精物亦通。周禮。以夏日至致地示物鬽。注曰。百物之神曰鬽。引春秋傳。螭鬽魍魎。按今左傳作魅。釋文。本作鬽。服䖍注云。魅、怪物。或云魅人面獸身而四足。好惑人。山林異氣所生。"}]},"鬾":{"expl":"鬼服也。一曰小兒鬼。从鬼支聲。《韓詩傳》曰：“鄭交甫逢二女，鬾服。”","rad":"鬼","fq":"奇寄切","vol":"09","py":"jì","duan":[{"e":"鬼服也。","n":"衣部曰。褮、鬼衣也。周禮。大喪廞裘。注曰。廞、興也。若詩之興。謂象似而作之。凡爲神之偶衣物必沽而小耳。"}]},"禖":{"expl":"祭也。从示某聲。","rad":"示","fq":"莫桮切","vol":"01","py":"méi","duan":[{"e":"祭也。","n":"謂祭名也。商頌傳曰。春分玄鳥降。湯之先祖。有娀氏女𥳑狄配高辛氏帝。帝率與之祈於郊禖而生契。故本其爲天所命。以玄鳥至而生焉。大雅傳曰。古者必立郊禖焉。玄鳥至之日。以大牢祀於郊禖。天子親往。后妃率九𡣕御。乃禮天子所御。帶以弓韣。授以弓矢。於郊媒之前。玉裁按。據此則禖神之祀不始於高辛明矣。鄭注月令云。玄鳥、媒氏之官以爲𠋫。高辛氏之世。玄鳥遺卵。娀𥳑吞之而生契。後王以爲媒官嘉祥而立其祠焉。變媒言禖。神之也。注禮記時未專信毛詩。故說鉏鋙爾。鄭志焦喬之荅。回護鄭公。殊爲詞費。"}]},"荐":{"expl":"薦蓆也。从艸存聲。","rad":"艸","fq":"在甸切","vol":"01","py":"jiàn","duan":[{"e":"薦席也。","n":"薦見廌部。艸也。不云艸席、云薦席者。取音近也。席各本誤蓆。薦席爲承藉。與所藉者爲二。故釋言云。荐、原、再也。如且爲爼几。故亦爲加增之䛐。易作洊。"}]},"䰧":{"expl":"鬼皃。从鬼虎聲。","rad":"鬼","fq":"虎烏切","vol":"09","py":"hū","duan":[{"e":"鬼皃。从鬼。虎聲。","n":"虎烏切。五部。"}]},"𩴪":{"expl":"鬼俗也。从鬼幾聲。《淮南傳》曰：“吳人鬼，越人𩴪。”","rad":"鬼","fq":"居衣切","vol":"09","py":"qí","duan":[{"e":"鬼俗也。","n":"謂好事鬼成俗也。淮南人閒訓曰。荆人鬼。越人禨。高云。鬼、好事鬼也。禨、禨祥也。景十三王傳。治宮室禨祥。伏䖍曰。禨祥、求福也。史記正義引顧野王云。禨祥、吉凶之先見也。按伏讀禨同祈。顧讀爲知幾其神之幾。皆好事鬼之意耳。玉藻、少儀二篇禨字乃旣嘰之假借。小食也。"}]},"䰰":{"expl":"鬼鬽聲，䰰䰰不止也。从鬼需聲。","rad":"鬼","fq":"奴豆切","vol":"09","py":"rú","duan":[{"e":"鬼鬽聲䰰䰰不止也。从鬼。需聲。","n":"奴豆切。四部。當依廣韵人朱乃侯二切。"}]},"𩲏":{"expl":"鬼變也。从鬼化聲。","rad":"鬼","fq":"呼駕切","vol":"09","py":"huà","duan":[{"e":"鬼變也。","n":"鬼之變匕也。"}]},"𩴴":{"expl":"見鬼驚詞。从鬼，難省聲。讀若《詩》“受福不儺”。","rad":"鬼","fq":"諾何切","vol":"09","py":"nuó","duan":[{"e":"見鬼驚䛐。","n":"見鬼而驚駭。其䛐曰？也。？爲奈何之合聲。凡驚䛐曰那者、卽？字。如公是韓伯休那是也。左傳棄甲則那、亦是奈何之合聲。"}]},"𩴱":{"expl":"鬼皃。从鬼賓聲。","rad":"鬼","fq":"符眞切","vol":"09","py":"pín","duan":[{"e":"鬼皃。","n":"此葢與䚔𧢜之義相近。"}]},"醜":{"expl":"可惡也。从鬼酉聲。","rad":"鬼","fq":"昌九切","vol":"09","py":"chǒu","duan":[{"e":"可惡也。","n":"鄭風。無我魗兮。鄭云。魗亦惡也。是魗卽醜字也。凡云醜類也者、皆謂醜卽疇之假借字。疇者、今俗之儔類字也。內則曰。龞去醜。鄭云。醜謂龞竅也。謂卽爾雅白州驠之州字也。"}]},"魋":{"expl":"神獸也。从鬼隹聲。","rad":"鬼","fq":"杜回切","vol":"09","py":"tuí","duan":[{"e":"如小熊。赤毛而黃。从隹。鬼聲。","n":"各本無此篆。據言部？篆下曰。从言魋聲。必當有此篆。但大徐補入鬼部。未當。今依爾雅補入隹部。獸可言隹也。杜回切。十五部。"}]},"魑":{"expl":"鬼屬。从鬼从离，离亦聲。","rad":"鬼","fq":"丑知切","vol":"09","py":"chī","duan":[]},"魔":{"expl":"鬼也。从鬼麻聲。","rad":"鬼","fq":"莫波切","vol":"09","py":"mó","duan":[]},"藉":{"expl":"祭藉也。一曰艸不編，狼藉。从艸耤聲。","rad":"艸","fq":"慈夜切","vol":"01","py":"jiè","duan":[{"e":"祭藉也。","n":"稭字下禾？去其皮。祭天以爲藉也。引伸爲凡承藉、蘊藉之義。又爲假藉之義。"}]},"魘":{"expl":"㝱驚也。从鬼厭聲。","rad":"鬼","fq":"於𤥎切","vol":"09","py":"yǎn","duan":[]},"甶":{"expl":"鬼頭也。象形。凡甶之屬皆从甶。","rad":"甶","fq":"敷勿切","vol":"09","py":"fú","duan":[{"e":"鬼頭也。象形。","n":"敷勿切。十五部。"}]},"畏":{"expl":"惡也。从甶，虎省。鬼頭而虎爪，可畏也。","rad":"甶","fq":"於胃切","vol":"09","py":"wèi","duan":[{"e":"惡也。从甶、虎省。","n":"虎上體省而儿不省。儿者、似人足而有爪也。於貴切。十五部。"}]},"禺":{"expl":"母猴屬。頭似鬼。从甶从禸。","rad":"甶","fq":"牛具切","vol":"09","py":"yù","duan":[{"e":"母猴屬。","n":"爪部曰。爲者、母猴也。又部曰。夔、一曰母猴也。郭氏山海經傳曰。禺似獼猴而大。赤目長尾。今江南山中多有。說者不了。乃作牛字。按左傳魯公爲。檀弓作公叔禺人。可證爲、禺是一物也。"}]},"厶":{"expl":"姦衺也。韓非曰：“蒼頡作字，自營爲厶。”凡厶之屬皆从厶。","rad":"厶","fq":"息夷切","vol":"09","py":"sī","duan":[{"e":"姦衺也。","n":"衺字淺人所增。當刪。女部曰。姦者、厶也。二篆爲轉注。若衺者、？也。？者、衺也。亦二篆爲轉注。不與姦厶相淆也。公私字本如此。今字私行而厶廢矣。私者、禾名也。"}]},"篡":{"expl":"屰而奪取曰篡。从厶算聲。","rad":"厶","fq":"初官切","vol":"09","py":"cuàn","duan":[{"e":"屰而奪取曰篡。","n":"奪當作敓。奪者、手持隹失之也。引伸爲凡遺失之偁。今吳語云奪落是也。敓者、彊取也。今字奪行敓廢。但許造說文時。畫然分別。書中不應自相剌謬。凡讀許書當先校正、有如此者。屰而敓者、下取上也。"}]},"㕗":{"expl":"相訹呼也。从厶从羑。","rad":"厶","fq":"與久切","vol":"09","py":"yòu","duan":[{"e":"相訹呼也。","n":"呼當作𧦝。𧦝、召也。言部曰。訹者、㕗也。㕗與訹二篆爲轉注。今人以手相招而口言㕗、正當作此字。今則誘行而㕗廢矣。"}]},"嵬":{"expl":"高不平也。从山鬼聲。凡嵬之屬皆从嵬。","rad":"嵬","fq":"五灰切","vol":"09","py":"wéi","duan":[{"e":"山石崔嵬。高而不平也。","n":"各本作高不平也四字。今依南都賦李注訂。有高而上平者。兀下曰高而上平、爾雅曰夷上洒下曰漘是也。周南。陟彼崔嵬。釋山曰。石戴土謂之崔嵬。毛傳曰。崔嵬、土山之戴石者。說似互異。依許云高不平、則毛傳是矣。惟土山戴石、故高而不平也。岨下云。石山戴土。亦與毛同。"}]},"巍":{"expl":"高也。从嵬委聲。","rad":"嵬","fq":"牛威切","vol":"09","py":"wēi","duan":[{"e":"高也。","n":"高者必大。故論語注曰。巍巍、高大之稱也。左傳。卜偃曰。萬、盈數也。巍犬名也。雉門外闕高巍巍然。謂之象巍。按本無二字。後人省山作魏。分別其義與音。不古之甚。"}]},"山":{"expl":"宣也。宣气𢿱，生萬物，有石而高。象形。凡山之屬皆从山。","rad":"山","fq":"所閒切","vol":"09","py":"shān","duan":[{"e":"宣也。謂能宣𢿱气。生萬物也。","n":"九字依莊子釋文訂。𢿱當作𢽳。"}]},"蒩":{"expl":"茅藉也。从艸租聲。《禮》曰：“封諸侯以土，蒩以白茅。”","rad":"艸","fq":"子余切","vol":"01","py":"zū","duan":[{"e":"茅藉也。","n":"司巫。祭祀共鉏館。杜子春云。鉏讀爲蒩。蒩、藉也。玄謂蒩之言藉也。祭食有當藉者。館所以承蒩。士虞禮。苴刌茅長五寸。實于筐。按鄭謂儀禮之苴。卽周禮之蒩也。"}]},"嶽":{"expl":"東，岱；南，靃；西，華；北，恆；中，泰室。王者之所以巡狩所至。从山獄聲。","rad":"山","fq":"五角切","vol":"09","py":"yuè","duan":[{"e":"東岱、","n":"見下。"}]},"岱":{"expl":"太山也。从山代聲。","rad":"山","fq":"徒耐切","vol":"09","py":"dài","duan":[{"e":"大山也。","n":"大作太者、俗改也。域中冣大之山、故曰大山。作太、作泰皆俗。釋山曰。泰山爲東嶽。毛傳曰。東嶽、岱。堯典。至于岱宗。封禪書、郊祀志曰。岱宗、泰山也。禹貢、職方皆曰岱。在今山東泰安府泰安縣北。"}]},"㠀":{"expl":"海中往往有山可依止，曰㠀。从山鳥聲。讀若《詩》曰“蔦與女蘿”。","rad":"山","fq":"都皓切","vol":"09","py":"dǎo","duan":[{"e":"海中往往有山可依止曰㠀。","n":"禹貢。鳥夷皮服。某氏傳讀爲㠀。與馬、鄭注如字不同。衛包徑改經爲㠀字。非也。"}]},"峱":{"expl":"山，在齊地。从山狃聲。《詩》曰：“遭我于峱之間兮。”","rad":"山","fq":"奴刀切","vol":"09","py":"náo","duan":[{"e":"峱山也。","n":"舊奪峱字、也字。今補。三字句。"}]},"嶧":{"expl":"葛嶧山，在東海下邳。从山睪聲。《夏書》曰：“嶧陽孤桐。”","rad":"山","fq":"羊益切","vol":"09","py":"yì","duan":[{"e":"葛嶧山也。","n":"地理志。東海郡下邳。葛嶧山在西。古文以爲嶧陽。郡國志。下邳國下邳縣葛嶧山。本嶧陽山。按今在江蘇省淮安府邳州西北六里。非山東兖州府鄒縣東南二十五里之繹山也。魯頌。𠈃有鳧繹。傳曰。繹、繹山也。左傳。邾文公卜遷于繹。杜云。繹、邾邑。魯國鄒縣北有繹山。哀七年。邾衆𠈃于繹。杜云。繹、邾山也。史記。秦始皇上鄒嶧山。刻石頌功德。地理志。魯國騶縣。嶧山在北。此山字作繹。从糸不从山。與東海葛嶧山字从山不同。史記作鄒嶧。漢志作嶧山。乃譌字也。秦時石刻字作繹。"}]},"嵎":{"expl":"封嵎之山，在吳楚之閒，汪芒之國。从山禺聲。","rad":"山","fq":"噳俱切","vol":"09","py":"yú","duan":[{"e":"封嵎之山也。在吳楚之閒𣳫芒之國。","n":"魯語。孔子曰。防風氏者、汪芒氏之君也。守封嵎之山者也。韋云。封、封山。嵎、嵎山。在今吳郡永安縣。按據許則封嵎乃一山名耳。今封、嵎二山在浙江省湖州府武康縣東。實一山也。楚當依玉篇作越。邑部曰。在夏爲防風氏。在殷爲汪芒氏。孔子謂防風氏爲汪芒氏之君者、以今釋古之例。謂夏之防風氏其國在殷之汪芒氏也。"}]},"嶷":{"expl":"九嶷山，舜所葬，在零陵營道。从山疑聲。","rad":"山","fq":"語其切","vol":"09","py":"yí","duan":[{"e":"九嶷山也。舜所葬。","n":"海內經。南方蒼梧之丘。蒼梧之淵。其中有九嶷山。舜之所葬。在長沙零陵畍中。郭云。山今在零陵營道縣南。其山九溪皆相似。故云九疑。古者總名其地爲蒼梧也。"}]},"𡼐":{"expl":"山，在蜀湔氐西徼外。从山𢽹聲。","rad":"山","fq":"武巾切","vol":"09","py":"mín","duan":[{"e":"𡼐山也。","n":"禹貢。岷山道江。夏本紀作汶山。封禪書曰。瀆山、蜀之汶山也。"}]},"㞦":{"expl":"山也。或曰弱水之所出。从山几聲。","rad":"山","fq":"居履切","vol":"09","py":"jǐ","duan":[{"e":"㞦山也。","n":"三字句。各本無㞦字。淺人所𠜂。乃使文理不完。許書之例。以說解釋文字。若㞦篆爲文字、㞦山也爲說解。淺人往往氾謂複字而𠜂之。如髦篆下云髦髮也、巂篆下云巂周、河篆江篆下云河水江水皆𠜂一字。今皆補正。玉篇、廣韵皆曰。女㞦、山名。按中山經曰。中次九經岷山之首曰女几之山。凡岷山之首自女几之山至于賈超之山、凡十六山。許立文𡼐㞦系聯、與山經合。豈古本作女㞦山與。"}]},"巀":{"expl":"巀𡾦山，在馮翊池陽。从山𢧵聲。","rad":"山","fq":"才葛切","vol":"09","py":"jié","duan":[{"e":"巀𡾦山也。","n":"四字句。"}]},"蕝":{"expl":"朝會束茅表位曰蕝。从艸絕聲。《春秋國語》曰：“致茅蕝，表坐。”","rad":"艸","fq":"子說切","vol":"01","py":"jué","duan":[{"e":"朝㑹束茅表位曰蕝。","n":"晉語。昔成王盟諸侯於岐陽。置茅蕝。設望表。與鮮卑守燎。故不與盟。司馬貞引賈逵云。束茅以表位爲蕝。許用賈侍中說也。史記、漢書叔孫通傳字作蕞。如淳曰。蕞謂以茅翦樹地。爲纂位尊卑之次也。"}]},"𡾦":{"expl":"巀𡾦山也。从山辥聲。","rad":"山","fq":"五葛切","vol":"09","py":"niè","duan":[{"e":"巀𡾦山也。从山。辥聲。","n":"五曷切。十五部。按語轉爲峩。"}]},"𡼀":{"expl":"山，在弘農華陰。从山，華省聲。","rad":"山","fq":"胡化切","vol":"09","py":"huà","duan":[{"e":"崋山也。在弘農華陰。","n":"地理志。京兆尹華陰。大華山在南。豫州山。郡國志。弘農郡華陰。故屬京兆。有大華山。漢之華陰、今陝西同州府華陰縣是其地。泰華山在縣南十里。卽西嶽也。"}]},"崞":{"expl":"山，在鴈門。从山𩫖聲。","rad":"山","fq":"古博切","vol":"09","py":"ɡuō","duan":[{"e":"𡾘山也。在鴈門。","n":"地理志。鴈門郡領縣十四。有崞縣。葢以山名縣也。不言某縣者、略也。今崞縣故城在山西直𥻳代州崞縣。西三十五里。崞山在縣西南四十里。"}]},"崵":{"expl":"崵山，在遼西。从山昜聲。一曰嵎鐵崵谷也。","rad":"山","fq":"與章切","vol":"09","py":"yánɡ","duan":[{"e":"首崵山也。在遼西。","n":"各本無首字。今依玉篇及伯夷列傳正義、王貢兩龔鮑傳注所引正。地理志。遼西郡令支有孤竹城。郡國志同。應劭曰。故伯夷國。按許意首崵山卽伯夷叔齊餓於首崵之下也。馬融注論語、曹大家注幽通賦、戴延之西征記說夷齊首陽各不同。"}]},"岵":{"expl":"山有草木也。从山古聲。《詩》曰：“陟彼岵兮。”","rad":"山","fq":"矦古切","vol":"09","py":"hù","duan":[{"e":"山有艸木也。","n":"艸舊作草。誤。今正。有當作無。釋山曰。多草木、岵。無草木、峐。釋名曰。山有草木曰岵。岵、怙也。人所怙取以爲事用也。山無草木曰屺。屺、圮也。無所出生也。許書同爾雅、釋名。吳都賦岡岵童、用字亦宗爾雅。而毛詩魏風傳曰。山無草木曰岵。山有草木曰屺。與爾雅互異。竊謂毛詩所據爲長。岵之言瓠落也。屺之言荄滋也。岵有陽道。故以言父。無父何怙也。屺有陰道。故以言母。無母何恃也。毛又曰。父尙義。母尙恩。則屬辭之意可見矣。許宗毛者也。疑有無字本同毛。後人易之。"}]},"屺":{"expl":"山無草木也。从山己聲。《詩》曰：“陟彼屺兮。”","rad":"山","fq":"墟里切","vol":"09","py":"qǐ","duan":[{"e":"山無艸木也。","n":"無當作有。"}]},"嶨":{"expl":"山多大石也。从山，學省聲。","rad":"山","fq":"胡角切","vol":"09","py":"xué","duan":[{"e":"山多大石也。","n":"釋山曰。多大石、嶨。許所據字从山也。廣韵引爾雅字亦从山。許石部有礐。訓石聲。與此義別。"}]},"嶅":{"expl":"山多小石也。从山敖聲。","rad":"山","fq":"五交切","vol":"09","py":"áo","duan":[{"e":"山多小石也。","n":"釋山曰。多小石、磝。許所據字从山也。魯有具、敖二山。晉師在敖、鄗二山之閒。敖葢卽嶅字。以多小石得名。"}]},"岨":{"expl":"石戴土也。从山且聲。《詩》曰：“陟彼岨矣。”","rad":"山","fq":"七余切","vol":"09","py":"qū","duan":[{"e":"石戴土也。","n":"周南卷耳曰。陟彼𥕅矣。本亦作砠。釋山曰。石戴土謂之崔嵬。土戴石爲岨。毛傳云。崔嵬、土山之戴石者。石山戴土曰砠。二文互異而義則一。戴者、增益也。釋山謂用石戴於土上。毛謂土而戴之以石。釋山謂用土戴於石上。毛謂石而戴之以土。以絲衣戴弁例之。則毛之立文爲善矣。石在上則高不平。故曰崔嵬。土在上則雨水沮洳。故曰岨。許於嵬下同毛。此岨下亦同毛也。詩、爾雅作砠。許作岨。主謂山、故字从山。重土、故不从石。"}]},"岡":{"expl":"山骨也。从山网聲。","rad":"山","fq":"古郎切","vol":"09","py":"ɡānɡ","duan":[{"e":"山脊也。","n":"釋山曰。山脊岡。周南傳曰。山脊曰岡。"}]},"茨":{"expl":"以茅葦蓋屋。从艸次聲。","rad":"艸","fq":"疾兹切","vol":"01","py":"cí","duan":[{"e":"茅葢屋。","n":"俗本作以茅葦葢屋。見甫田鄭箋。釋名曰。屋以艸葢曰茨。茨、次也。次艸爲之也。"}]},"岑":{"expl":"山小而高。从山今聲。","rad":"山","fq":"鉏箴切","vol":"09","py":"cén","duan":[{"e":"山小而高。","n":"釋山曰。山小而高曰岑。釋名曰。岑、嶃也。嶃然也。"}]},"崟":{"expl":"山之岑崟也。从山金聲。","rad":"山","fq":"魚音切","vol":"09","py":"yín","duan":[{"e":"山之岑崟也。","n":"子虛賦。岑崟參差。日月蔽虧。又楊雄蜀都賦。張衡南都賦。皆有嶜岑字。李善讀爲岑崟。"}]},"崒":{"expl":"崒，危高也。从山卒聲。","rad":"山","fq":"醉綏切","vol":"09","py":"zú","duan":[{"e":"崒、","n":"此複舉字之未𠜂者。"}]},"巒":{"expl":"山小而銳。从山䜌聲。","rad":"山","fq":"洛官切","vol":"09","py":"luán","duan":[{"e":"山小而銳。","n":"釋山曰。巒山墮。說者謂爲一條。許於巒墮別爲二條。毛公釋墮亦不云巒也。葢爾雅巒墮二物。許云山小而銳、巒之解也。毛云山之隋隋小者、嶞之解也。後儒合爲一者、非是。劉淵林注蜀都賦曰。巒、山長而狹也。一曰山小而銳也。兼用爾雅。說文。而爾雅之讀與毛許異矣。"}]},"密":{"expl":"山如堂者。从山宓聲。","rad":"山","fq":"美畢切","vol":"09","py":"mì","duan":[{"e":"山如堂者。","n":"土部曰。堂、殿也。釋山曰。山如堂者、密。郭引尸子。松栢之鼠不知堂密之有美樅。按密主。謂山。假爲精密字而本義廢矣。"}]},"岫":{"expl":"山穴也。从山由聲。","rad":"山","fq":"似又切","vol":"09","py":"xiù","duan":[{"e":"山有穴也。","n":"有字各本奪。今依文選張景陽襍詩注補。有穴之山謂之岫。非山穴謂之岫也。東京賦。王鮪岫居。薛解云。山有穴曰岫。然則岫居、言居有穴之山。"}]},"𡺲":{"expl":"高也。从山陖聲。","rad":"山","fq":"私閏切","vol":"09","py":"jùn","duan":[{"e":"高也。","n":"高上當有陖字。轉寫奪之耳。高者、崇也。陖者、陗高也。凡斗上曰陗。𡺲从陖、則義與陖同。同一高而有危高、陖高、尤高、短而高、巍高、大而高之別。大雅。崧高維嶽。駿極于天。傳曰。駿、大也。中庸、孔子閒居注皆曰。峻高大也。然則大雅之駿、用假借字。"}]},"嶞":{"expl":"山之墮墮者。从山，从憜省聲。讀若相推落之憜。","rad":"山","fq":"徒果切","vol":"09","py":"duò","duan":[{"e":"山之嶞嶞者。","n":"周頌曰。嶞山喬嶽。毛傳曰。嶞山、山之嶞嶞小者也。嶞嶞、狹長之皃。凡圜而長者謂之隋。圜方而長者謂之隋方。字或作橢。毛傳。方銎曰斨。隋銎曰斧。鄭注月令曰。隋曰竇。方曰窖。注禮器曰。棜禁、如今方案隋長。隋長皆用隋字。爾雅。鰿貝小而橢。平準書、食貨志三曰復小橢之。皆用橢字。此說山則用嶞字。疑當同毛傳作嶞嶞小者。今奪小字耳。嶞嶞疑當作隋隋。隋卽墮字。詩釋文曰。嶞字又作墮。"}]},"嶘":{"expl":"尤高也。从山棧聲。","rad":"山","fq":"士限切","vol":"09","py":"zhàn","duan":[{"e":"尢高也。","n":"乙部曰。尢者、異也。京部曰。尤者、異於凡也。尢高謂之嶘。今字作㟞。"}]},"崛":{"expl":"山短高也。从山屈聲。","rad":"山","fq":"衢勿切","vol":"09","py":"jué","duan":[{"e":"山短而高也。","n":"而字舊無。今依廣韵補。短高者、不長而高也。不長故从𡲬。𡲬者、無尾也。無尾之物則短。張揖上林賦注曰。崛崎、斗絕也。"}]},"葺":{"expl":"茨也。从艸咠聲。","rad":"艸","fq":"七入切","vol":"01","py":"qì","duan":[{"e":"茨也。从艸。咠聲。","n":"七入切。七部。"}]},"𡿋":{"expl":"巍高也。从山蠆聲。讀若厲。","rad":"山","fq":"力制切","vol":"09","py":"lì","duan":[{"e":"巍高也。从山蠆聲。","n":"虫部作𦹌。毒蟲也。从虫。上象形。依𥻳體从虫从萬則誤。"}]},"峯":{"expl":"山耑也。从山夆聲。","rad":"山","fq":"敷容切","vol":"09","py":"fēnɡ","duan":[]},"巖":{"expl":"岸也。从山嚴聲。","rad":"山","fq":"五緘切","vol":"09","py":"yán","duan":[{"e":"厓也。","n":"各本作岸也。今依太平御覽所引正。厂部曰。厓者、山邊也。厓亦謂之巖。故厂下云。山石之厓巖。人可居也。戰國策。巖下有貫珠者。漢書。遊於巖廊之上。皆謂殿下小屋。如厓巖之下可居也。天子之堂九尺。諸侯七尺。其上曰巖廊。其下曰巖下。"}]},"𡼊":{"expl":"𡽕也。从山絫聲。","rad":"山","fq":"落猥切","vol":"09","py":"lěi","duan":[{"e":"𡼊𡽕、","n":"逗。曡韵字也。"}]},"𡽕":{"expl":"山皃。从山辠聲。","rad":"山","fq":"徂賄切","vol":"09","py":"zuì","duan":[{"e":"𡼊𡽕也。从山辠。","n":"徂賄切。十五部。文選、篇、韵皆作㠑。"}]},"峼":{"expl":"山皃。一曰山名。从山告聲。","rad":"山","fq":"古到切","vol":"09","py":"ɡào","duan":[{"e":"山皃。一曰山名。从山。告聲。","n":"古到切。篇、韵皆口沃切。三部。"}]},"𡽃":{"expl":"山皃。从山隓聲。","rad":"山","fq":"徒果切","vol":"09","py":"duò","duan":[{"e":"山皃。从山。隓聲。","n":"徒果切。十七部。按隓者、小篆文之𡐦也。嶞从隋者、从𡐦之省也。是則嶞𡽃葢一字。不當爲二。"}]},"嵯":{"expl":"山皃。从山𢀩聲。","rad":"山","fq":"昨何切","vol":"09","py":"cuó","duan":[{"e":"𡾑峨、","n":"逗。二字各本無。今依全書通例補。"}]},"峨":{"expl":"嵯峨也。从山我聲。","rad":"山","fq":"五何切","vol":"09","py":"é","duan":[{"e":"嵯峨也。从山。我聲。","n":"五何切。十七部。"}]},"葢":{"expl":"苫也。从艸盇聲。","rad":"艸","fq":"古太切","vol":"01","py":"ɡài","duan":[{"e":"苫也。","n":"引伸之爲發端語詞。又不知者不言、論語謂之葢闕。漢書謂之丘葢。"}]},"崝":{"expl":"嶸也。从山青聲。","rad":"山","fq":"七耕切","vol":"09","py":"zhēnɡ","duan":[{"e":"崝嶸、","n":"逗。"}]},"嶸":{"expl":"崝嶸也。从山榮聲。","rad":"山","fq":"戶萌切","vol":"09","py":"rónɡ","duan":[{"e":"崝嶸也。从山。榮聲。","n":"戸萌切。十二部。亦作嵤。"}]},"𡷨":{"expl":"谷也。从山坙聲。","rad":"山","fq":"戶經切","vol":"09","py":"kēnɡ","duan":[{"e":"𡷨谷也。","n":"三字句。各本𠜂𡷨字。今補。廣韵曰。𡷨口莖切。或作硎。谷名。在麗山。昔秦密種瓜處。按秦冬月種瓜谷中溫處。瓜實。因使諸生往視。說之。發機阬諸生。事見尙書正義所引衞宏詔定古文官書序。漢書儒林傳注、藝文類聚卷八十七同。而師古作阬谷。正義及類聚作硎谷。實則𡷨谷也。"}]},"𡹔":{"expl":"山壞也。从山朋聲。","rad":"山","fq":"北滕切","vol":"09","py":"bēnɡ","duan":[{"e":"山壞也。","n":"引伸之天子死曰𡹔。"}]},"岪":{"expl":"山脅道也。从山弗聲。","rad":"山","fq":"𢾭勿切","vol":"09","py":"fú","duan":[{"e":"山脅道也。","n":"脅者、㒳𦜶也。山如人體、其㒳㫄曰脅。水經注曰。江水又東逕赤岬城。引淮南子。𢔚徨於山岬之㫄。注云。岬、山脅也。楚辭招隠士云。坱兮圠山曲𡶒。王注云。盤結屈也。結屈、許書作詰詘。山脅之道然也。"}]},"嵍":{"expl":"山名。从山敄聲。","rad":"山","fq":"亡遇切","vol":"09","py":"wù","duan":[{"e":"山名。","n":"按此篆許書本無。後人增之。許書果有是山。則當廁於山名之類矣。顔氏家訓。柏人城東有山。世或呼爲宣務山。予讀柏人城內漢桓帝時所立碑銘云。上有巏嵍。王喬所仙。巏字遂無所出。嵍字依諸字書卽旄丘之旄也。嵍字、字林一音忘付反。今依附俗名當音權務。經典釋文曰。字林有嵍亡周反、一音毛。嵍丘也。又有嵍亡附反、一音毛。亦云嵍丘也。據顔、陸之書、字林乃有嵍字。則許書之本無此顯然矣。旄丘見詩。爾雅曰。前高曰旄丘。劉成國曰。如馬舉頭垂髦。依字林、嵍丘卽旄丘。乃丘名、非山名也。"}]},"嶢":{"expl":"焦嶢，山高皃。从山堯聲。","rad":"山","fq":"古僚切","vol":"09","py":"yáo","duan":[{"e":"焦嶢、山高皃。","n":"楊雄傳曰。泰山之高。不嶕嶢則不能浡滃雲而散歊蒸。嶕古祗作焦。"}]},"𡸤":{"expl":"山𡺲也。从山戕聲。","rad":"山","fq":"慈良切","vol":"09","py":"qiánɡ","duan":[{"e":"山𡺲也。从山。戕聲。","n":"慈良切。十部。"}]},"嵏":{"expl":"九嵏山，在馮翊谷口。从山㚇聲。","rad":"山","fq":"子紅切","vol":"09","py":"zōnɡ","duan":[{"e":"九嵏山也。在左馮翊谷口。","n":"左字各本無。今補。地理志曰。左馮翊穀口。九嵏山在西。谷口故城今在西安府醴泉縣東北七十里。九嵏山今在縣東北五十里。有九夆、俱峻。"}]},"𡴹":{"expl":"陬隅，高山之節。从山从卪。","rad":"山","fq":"子結切","vol":"09","py":"jié","duan":[{"e":"陬隅。","n":"𨸏部曰。隅者、陬也。陬者、隅也。孟子。虎負嵎。是知隅者、高山之卪也。嵎卽隅字。趙注曰。虎依陬而怒。"}]},"苫":{"expl":"蓋也。从艸占聲。","rad":"艸","fq":"失廉切","vol":"01","py":"shān","duan":[{"e":"葢也。从艸。占聲。","n":"失廉切。今俗語舒贍切。古音在七部。"}]},"崇":{"expl":"嵬高也。从山宗聲。","rad":"山","fq":"鉏弓切","vol":"09","py":"chónɡ","duan":[{"e":"山大而高也。","n":"各本作巍高也三字。今正。大雅。崧高維嶽。釋山、毛傳皆曰。山大而高曰崧。孔子閒居引詩崧作嵩。釋名作山大而高曰嵩。崧嵩二形皆卽崇之異體。韋注國語云。古通用崇字。太平御覽及徐鉉皆引其語。詩序曰。崇丘、萬物得極其高大也。此崇之故訓也。河東賦。瞰帝唐之嵩高。眽隆周之大寧。嵩高卽崇高也。漢碑曰。如山如岳。嵩如不傾。謂崇而不傾也。中嶽、禹貢謂之外方。秦名大室。漢武帝始謂之崇高山。因以山下戸三百爲之奉邑。名曰崇高縣。武帝紀、郊祀志、地理志、封禪書可證。崇字地裏志作崈。體之小異耳。史、漢或崇嵩錯出。要無礙爲一字。惟後漢書靈帝紀。熹平五年復崇高山爲嵩高山。語大可疑。證以東觀紀。堂谿典請雨。因上言改之。名爲嵩高山。"}]},"崔":{"expl":"大高也。从山隹聲。","rad":"山","fq":"胙回切","vol":"09","py":"cuī","duan":[{"e":"大高也。","n":"齊風。南山崔崔。傳曰。崔崔、高大也。此云大高。未知孰是。嵬下曰。山石崔嵬。高而不平也。亦卽毛傳之土山戴石曰崔嵬也。"}]},"嶙":{"expl":"嶙峋，深崖皃。从山粦聲。","rad":"山","fq":"力珍切","vol":"09","py":"lín","duan":[]},"峋":{"expl":"嶙峋也。从山旬聲。","rad":"山","fq":"相倫切","vol":"09","py":"xún","duan":[]},"岌":{"expl":"山高皃。从山及聲。","rad":"山","fq":"魚汲切","vol":"09","py":"jí","duan":[]},"嶠":{"expl":"山銳而高也。从山喬聲。古通用喬。","rad":"山","fq":"渠廟切","vol":"09","py":"jiào","duan":[]},"嵌":{"expl":"山深皃。从山，歁省聲。","rad":"山","fq":"口銜切","vol":"09","py":"qiān","duan":[]},"嶼":{"expl":"㠀也。从山與聲。","rad":"山","fq":"徐呂切","vol":"09","py":"yǔ","duan":[]},"嶺":{"expl":"山道也。从山領聲。","rad":"山","fq":"良郢切","vol":"09","py":"lǐnɡ","duan":[]},"嵐":{"expl":"山名。从山，葻省聲。","rad":"山","fq":"盧含切","vol":"09","py":"lán","duan":[]},"䔽":{"expl":"蓋也。从艸渴聲。","rad":"艸","fq":"於蓋切","vol":"01","py":"ài","duan":[{"e":"葢也。","n":"今人靄字當用此。"}]},"嵩":{"expl":"中岳，嵩高山也。从山从高，亦从松。韋昭《國語》注云：“古通用崇字。”","rad":"山","fq":"息弓切","vol":"09","py":"sōnɡ","duan":[]},"崑":{"expl":"崑崙，山名。从山昆聲。《漢書》楊雄文通用昆侖。","rad":"山","fq":"古渾切","vol":"09","py":"kūn","duan":[]},"崙":{"expl":"崑崙也。从山侖聲。","rad":"山","fq":"盧昆切","vol":"09","py":"lún","duan":[]},"嵇":{"expl":"山名。从山，稽省聲。奚氏避難特造此字，非古。","rad":"山","fq":"胡雞切","vol":"09","py":"xí","duan":[]},"屾":{"expl":"二山也。凡屾之屬皆从屾。","rad":"屾","fq":"所臻切","vol":"09","py":"shēn","duan":[{"e":"二山也。","n":"此說義而形在是。如𤤴之例。"}]},"嵞":{"expl":"會稽山。一曰九江當嵞也。民以辛壬癸甲之日嫁娶。从屾余聲。《虞書》曰：“予娶嵞山。”","rad":"屾","fq":"同都切","vol":"09","py":"tú","duan":[{"e":"會稽山也。","n":"左傳。禹會諸矦於塗山。執玉帛者萬國。魯語。昔禹致羣神於會稽之山。防風氏後至。禹殺而戮之二傳所說正是一事。故云嵞山卽會稽山。嵞塗古今字。故今左傳作塗。封禪書云。管仲曰。禹封泰山。禪會稽。吳越春秋曰。禹登茅山以朝羣臣。乃大會計。更名茅山爲會稽。封禪書又云。秦幷天下。自殽以東名山五。大室、恒山、太山、會稽、湘山。劉向上封事曰。禹葬會稽。葢大禹以前名嵞山。大禹以後則名會稽山。故許以今名釋古名也。杜注左傳云。塗山左壽春東北。非古說也。會稽山在今浙江省紹興府治東南十二里。"}]},"屵":{"expl":"岸高也。从山、厂，厂亦聲。凡屵之屬皆从屵。","rad":"屵","fq":"五葛切","vol":"09","py":"è","duan":[{"e":"岸高也。","n":"屵之言䡾䡾然也。廣韵。高山狀。"}]},"岸":{"expl":"水厓而高者。从屵干聲。","rad":"屵","fq":"五旰切","vol":"09","py":"àn","duan":[{"e":"水厓洒而高者。","n":"各本無洒字。今依爾雅補。釋丘曰。望厓洒而高岸。夷上洒下不漘。李巡曰。夷上、平上。洒下、陗下。故名漘。孫炎曰。平上陗下故名曰漘。不者、葢衍字。據李孫之釋漘、則知李孫之釋岸亦必曰陗下而高上也。陗下者、謂其體斗陗平上。高上者、謂其顚有崔嵬平坦之不同。嵬下曰。高不平也。對夷上言也。洒釋爲陗者。洒卽陖之假借。二字古音同。𨸏部曰。陖者、陗高也。陗者、陖也。凡斗立不可上曰陗。詩新臺有洒傳曰。洒、高峻也。峻同陖。郭景純昧於其義。乃釋高曰陖。陖非高之謂也。釋洒曰水深。水之深淺、何與於厓。不得冠以望厓矣。爾雅言厓、許言水厓者、申爾雅之說。別於山邊之厓也。衞風。淇則有岸。小雅。高岸爲谷。其本義也。大雅。誕先登于岸。"}]},"崖":{"expl":"高邊也。从屵圭聲。","rad":"屵","fq":"五佳切","vol":"09","py":"yá","duan":[{"e":"高邊也。","n":"辵部曰。邊行垂崖也。土部曰。垂者、遠邊也。按垂爲遠邊。崖爲高邊。邊之義謂行於此二者、此二者因名邊矣。其字从屵也。故爲高邊。"}]},"嵟":{"expl":"高也。从屵隹聲。","rad":"屵","fq":"都回切","vol":"09","py":"duī","duan":[{"e":"高也。","n":"玉篇曰。亦作陮。按𨸏部曰。陮隗、高也。義同字異。"}]},"䓛":{"expl":"刷也。从艸屈聲。","rad":"艸","fq":"區勿切","vol":"01","py":"qū","duan":[{"e":"㕞也。","n":"㕞當作刷。字之誤也。㕞、拭也。刷、掊杷也。䓛之言掘也。與掊杷義近。今人謂以鈍帚去薉物曰䓛。正是此字。廣雅釋器。䓛謂之刷。"}]},"𡺮":{"expl":"崩也。从屵肥聲。","rad":"屵","fq":"符鄙切","vol":"09","py":"pǐ","duan":[{"e":"𡹔也。","n":"列子黃帝篇。目所偏視。晉國爵之。口所偏肥。晉國黜之。殷敬順釋文云。肥皮美切。說文、字林皆作𡺮。又作圮。皆毀也。按古肥與非通。口所偏肥、猶云口所偏非耳。不必援此也。𡺮與圮亦非一字。"}]},"嶏":{"expl":"崩聲。从屵配聲。讀若費。","rad":"屵","fq":"蒲没切","vol":"09","py":"pèi","duan":[{"e":"𡹔聲。从屵。配聲。讀若費。","n":"蒲沒切。十五部。按此葢卽𡺮之或體耳。玉篇有𡺮無嶏、可證廣韵𠊓佩切。"}]},"广":{"expl":"因广爲屋，象對剌高屋之形。凡广之屬皆从广。讀若儼然之儼。","rad":"广","fq":"魚儉切","vol":"09","py":"yǎn","duan":[{"e":"因厂爲屋也。","n":"厂各本作广。誤。今正。厂者、山石之厓巖。因之爲屋、是曰广。廣韵琰儼二韵及昌黎集注皆作因巖、可證。因巖卽因厂也。"}]},"府":{"expl":"文書藏也。从广付聲。","rad":"广","fq":"方矩切","vol":"09","py":"fǔ","duan":[{"e":"文書臧也。","n":"文書所藏之處曰府。引伸之爲府史胥徒之府。周禮。府六人。史十有二人。注云。府治藏、史掌書者。又大宰。以八法治官府。注云。百官所居曰府。"}]},"廱":{"expl":"天子饗飲辟廱。从广雝聲。","rad":"广","fq":"於容切","vol":"09","py":"yōnɡ","duan":[{"e":"天子饗㱃辟廱。","n":"饗飲謂鄉飲酒也。食部曰。饗者、鄉人飲酒也。辟廱者、天子之學也。在郊。禮記文王世子曰。凡大合樂。必遂養老。天子視學。設三老五更羣老之席位焉。注云。以鄉飲酒禮言之。席位之處。則三老如賔、五更如介、羣老如衆賔必也。又云遂養老者、用大合樂之明日也。鄉飲酒、鄉射之禮明日乃息。司正徵唯所欲。以告於先生君子可也。是養老之象類。是則天子養老之禮、卽鄉飲酒之禮。水部泮下曰。諸侯鄉射之宫。鄉謂鄉飲酒。射謂鄉射。魯頌泮宫箋云。在泮飲酒者、徵先生君子與之行飲酒之禮。而因以謀事也。永錫難老者、長賜之冣壽考。如王制所云。八十月告存。九十日有秩也。是則天子諸侯養老、皆用鄉飲酒禮。韓詩說。辟廱、所以敎天下。春射秋饗。尊事三老"}]},"庠":{"expl":"禮官養老。夏曰校，殷曰庠，周曰序。从广羊聲。","rad":"广","fq":"似陽切","vol":"09","py":"xiánɡ","duan":[{"e":"禮官養老。夏曰校。殷曰庠。周曰序。","n":"孟子滕文公篇曰。夏曰校。殷曰序。周曰庠。史記儒林傳同。漢書儒林傳則云。夏曰校。殷曰庠。周曰序。許同漢書。疑今孟子、史記有誤。孟子曰。庠者、養也。"}]},"廬":{"expl":"寄也。秋冬去，春夏居。从广盧聲。","rad":"广","fq":"力居切","vol":"09","py":"lú","duan":[{"e":"从广。盧聲。","n":"古亦與盧相假借。力居切。五部。"}]},"庭":{"expl":"宮中也。从广廷聲。","rad":"广","fq":"特丁切","vol":"09","py":"tínɡ","duan":[{"e":"宮中也。","n":"下文曰中庭。則此當曰中宮。俗倒之耳。中宮、宮之中。如詩之中林、林中也。廴部曰。廷、中朝也。朝不屋、故不从广。宮者、室也。室之中曰庭。詩曰殖殖。其庭。曰子有廷內。曰洒掃庭內。檀弓。孔子哭子路於中庭。注曰。寢中庭也。凡經有謂堂下爲庭者。如三分庭一在南。正當作廷。爲義相近。爾雅釋詁、詩大田韓奕閔予小子傳曰。庭、直也。引伸之義也。庭者、正直之處也。"}]},"𢊺":{"expl":"中庭也。从广畱聲。","rad":"广","fq":"力救切","vol":"09","py":"liù","duan":[{"e":"中庭也。","n":"中庭者、庭之中也。月令。中央土。其祀中𩅸。注曰。中𩅸、猶中室也。古者複穴。是以名室爲𩅸。正義引庾蔚之云。複者、謂地上累土爲之。穴則穿地也。複穴皆開其上取明。故雨𩅸之。是以後因名室爲中𩅸也。按釋名曰。室之中央曰中𩅸。古者𥨍穴後室之。（句）𩅸當今之棟下。直室之中。古者𩅸下之處也。月令、呂覽、鄭、劉皆作中𩅸。許則𩅸謂屋水流。𢊺謂中室。畫分二字。葢旣有宮室以後、則𩅸在屋垂。而屋中謂之𢊺以存古。釋宮曰。杗𢊺謂之梁。葢言室內之制。賦家所謂藻井其是與。"}]},"庉":{"expl":"樓牆也。从广屯聲。","rad":"广","fq":"徒損切","vol":"09","py":"dùn","duan":[{"e":"樓牆也。","n":"樓者、重屋也。"}]},"𥚩":{"expl":"祭具也。从示胥聲。","rad":"示","fq":"私呂切","vol":"01","py":"xǔ","duan":[{"e":"祭具也。","n":"山海經、離騷經皆作糈。王逸曰。糈、精米。所以享神。郭璞曰。糈、祭神之米名。疑許君所據二書作𥚩。"}]},"藩":{"expl":"屏也。从艸潘聲。","rad":"艸","fq":"甫煩切","vol":"01","py":"fān","duan":[{"e":"屛也。","n":"屛蔽也。"}]},"庌":{"expl":"廡也。从广牙聲。《周禮》曰：“夏庌馬。”","rad":"广","fq":"五下切","vol":"09","py":"yǎ","duan":[{"e":"廡也。从广。牙聲。","n":"五下切。古音在五部。"}]},"廡":{"expl":"堂下周屋。从广無聲。","rad":"广","fq":"文甫切","vol":"09","py":"wǔ","duan":[{"e":"堂周屋也。","n":"各本作堂下。玄應引作堂周屋曰廡。今从之。釋名曰。大屋曰廡。幽冀人謂之庌。說與許異。許謂堂之四𠣘爲屋也。洪範、晉語蕃廡皆假廡爲𣞤也。"}]},"㢚":{"expl":"廡也。从广虜聲。讀若鹵。","rad":"广","fq":"郎古切","vol":"09","py":"lǔ","duan":[{"e":"廡也。从广。虜聲。讀若鹵。","n":"郎古切。五部。"}]},"庖":{"expl":"廚也。从广包聲。","rad":"广","fq":"薄交切","vol":"09","py":"páo","duan":[{"e":"廚也。","n":"王制。三爲充君之庖。注曰。庖今之廚也。周禮庖人注曰。庖之言苞也。苞裹肉曰苞苴。"}]},"廚":{"expl":"庖屋也。从广尌聲。","rad":"广","fq":"直株切","vol":"09","py":"chú","duan":[{"e":"庖室也。","n":"室各本作屋。今依御覽。"}]},"庫":{"expl":"兵車藏也。从車在广下。","rad":"广","fq":"苦故切","vol":"09","py":"kù","duan":[{"e":"兵車藏也。","n":"此庫之本義也。引伸之、凡貯物舍皆曰庫。"}]},"廏":{"expl":"馬舍也。从广㲃聲。《周禮》曰：“馬有二百十四匹爲廏，廏有僕夫。”","rad":"广","fq":"居又切","vol":"09","py":"jiù","duan":[{"e":"馬舍也。从广。㲃聲。","n":"居又切。三部。"}]},"序":{"expl":"東西牆也。从广予聲。","rad":"广","fq":"徐呂切","vol":"09","py":"xù","duan":[{"e":"東西牆也。","n":"釋宮曰。東西牆謂之序。按堂上以東西牆爲介。禮經謂階上序端之南曰序南。謂正堂近序之處曰東序、西序。古假杼爲序。尙書大傳。天子賁庸。諸侯疏杼。鄭注云。牆謂之庸。杼亦牆也。李善文選注引雒書天準聽。天球河圖在東杼。又夂部曰。次弟謂之敘。經傳多假序爲敘。周禮、儀禮序字注多釋爲次弟是也。又周頌。繼序思不㤀。傳曰。序、緒也。此謂序爲緒之假借字。"}]},"廦":{"expl":"牆也。从广辟聲。","rad":"广","fq":"比激切","vol":"09","py":"bì","duan":[{"e":"牆也。","n":"與土部之壁音義同。"}]},"廣":{"expl":"殿之大屋也。从广黃聲。","rad":"广","fq":"古晃切","vol":"09","py":"ɡuǎnɡ","duan":[{"e":"殿之大屋也。","n":"土部曰。堂、殿也。倉頡篇曰。殿、大堂也。廣雅曰。堂堭、合殿也。殿謂堂無四壁。漢書胡建傳注無四壁曰堂皇是也。覆乎上者曰屋。無四壁而上有大覆葢。其所通者宏遠矣。是曰廣。引伸之爲凡大之偁。詩六月、雝傳皆曰。廣、大也。"}]},"菹":{"expl":"酢菜也。从艸沮聲。","rad":"艸","fq":"側魚切","vol":"01","py":"zū","duan":[{"e":"酢菜也。","n":"酢今之醋字。菹須醯成味。周禮七菹。韭菁𦯄葵芹䈚筍也。鄭曰。凡醯酱所和。細切爲韲。全物若䐑爲菹。少儀麋鹿爲菹。則菹之稱菜肉通。玉裁謂。韲菹皆本菜稱。用爲肉稱也。"}]},"廥":{"expl":"芻藁之藏。从广會聲。","rad":"广","fq":"古外切","vol":"09","py":"kuài","duan":[{"e":"芻稾之藏也。","n":"天官書。其南衆星曰廥積。如淳漢書注曰。芻稾積爲廥也。史記正義曰。芻稾六星在天苑西。主積稾草者。"}]},"庾":{"expl":"水槽倉也。从广臾聲。一曰倉無屋者。","rad":"广","fq":"以主切","vol":"09","py":"yǔ","duan":[{"e":"水漕倉也。","n":"漢書孝父紀應劭注同。謂水轉穀至而倉之也。"}]},"庰":{"expl":"蔽也。从广幷聲。","rad":"广","fq":"必郢切","vol":"09","py":"bìnɡ","duan":[{"e":"蔽也。","n":"此與尸部之屏義同、而所謂各異。此字从广。謂屋之隱蔽者也。廣雅曰。圊圂庰廁也。急就篇曰。屏廁淸溷糞土壤。屏與庰通。溷與圂通。圊與淸通。下文云廁、淸也。則庰亦謂廁。戰國策云。宋王鑄諸侯之象。使侍屏匽。周禮注云。匽、路廁也。"}]},"廁":{"expl":"清也。从广則聲。","rad":"广","fq":"初吏切","vol":"09","py":"cì","duan":[{"e":"淸也。","n":"淸圊古今字。釋名曰。廁言人雜廁在上非一也。或曰溷言溷濁也。或曰圊言至穢之處。宜常修治使潔淸也。按凡云雜廁者、猶云溷雜。急就篇、說文敘皆曰分別部居不雜廁是也。古多假廁爲側。如史記張釋之傳北臨廁、漢書汲黯傳上踞廁視之是也。"}]},"廛":{"expl":"一畝半，一家之居。从广、里、八、土。","rad":"广","fq":"直連切","vol":"09","py":"chán","duan":[{"e":"二畝半也。一家之凥。","n":"二各本作一。凥各本作居。今正。按說已廬篆注。合漢食貨志、公羊傳何注、詩南山箋孟子梁惠王篇趙注、知古者在野曰廬。在邑曰里。各二畝半。趙注尤明。里卽廛也。詩伐檀毛傳曰。一夫之居曰廛。遂人。夫一廛。先鄭云。廛、居也。後鄭云。廛城邑之居。載師。以廛里任國中之地。後鄭云。廛里者、若今云邑居。廛、民居之區域也。里、居也。毛、鄭皆未明言二畝半。要其意同也。許於廬不曰二畝半。於廛曰二畝半。以錯見互足。"}]},"㡲":{"expl":"屋牝瓦下。一曰維綱也。从广，𨳮省聲。讀若環。","rad":"广","fq":"戶關切","vol":"09","py":"huán","duan":[{"e":"屋牡瓦也。","n":"牡各本作牝。也各本作下。今正。廣韵二十七𠜂曰。屋牡瓦名。是也。屋瓦下載者曰牝。昌邑王傳之版瓦也。上覆者曰牡。玉篇。㼧、牡瓦也。㼧廣雅作㼿。今俗猶以圓而上覆之瓦曰𤭁。㡲之言似環也。㼧之言似筩也。"}]},"𢊕":{"expl":"屋階中會也。从广怱聲。","rad":"广","fq":"倉紅切","vol":"09","py":"cōnɡ","duan":[{"e":"屋階中會也。","n":"謂㒳階之中湊也。西京賦曰。刊層平堂。設切厓隒。今之階隒石必長石居中。㒳邊鬬合。篇、韵皆作屋中會。無階字。非是。"}]},"㢋":{"expl":"廣也。从广侈聲。《春秋國語》曰：“俠溝而㢋我。”","rad":"广","fq":"尺氏切","vol":"09","py":"chǐ","duan":[{"e":"廣也。","n":"上文殿之大屋曰廣矣。此廣則其引伸之義也。凡讀說文者必知斯例而後無所庢。廣雅曰。㢋、大也。今人曰侈斂、古字作㢋廉。"}]},"廉":{"expl":"庂也。从广兼聲。","rad":"广","fq":"力兼切","vol":"09","py":"lián","duan":[{"e":"仄也。","n":"此與廣爲對文。謂偪仄也。廉之言斂也。堂之邊曰廉。天子之堂九尺。諸侯七尺。大夫五尺。士三尺。堂邊皆如其高。賈子曰廉遠地則堂高、廉近地則堂卑是也。堂邊有隅有棱。故曰廉。廉、隅也。又曰廉、棱也。引伸之爲淸也、儉也、嚴利也。許以仄晐之。仄者、圻咢陖陗之謂。今之筭法謂邊曰廉。謂角曰隅。"}]},"㢉":{"expl":"開張屋也。从广秅聲。濟陰有㢉縣。","rad":"广","fq":"宅加切","vol":"09","py":"chá","duan":[{"e":"開張屋也。","n":"謂屋之開張者也。"}]},"荃":{"expl":"芥脃也。从艸全聲。","rad":"艸","fq":"此緣切","vol":"01","py":"quán","duan":[{"e":"芥脃也。","n":"黑部曰。以芥爲韲名曰芥荃。云芥脃者、謂芥韲鬆脃可口也。此字據上下文則非楚詞荃字也。"}]},"龐":{"expl":"高屋也。从广龍聲。","rad":"广","fq":"薄江切","vol":"09","py":"pánɡ","duan":[{"e":"高屋也。","n":"謂屋之高者也。故字从广。引伸之爲凡高大之偁。小雅。四牡龐龐。傳曰。龐龐、充實也。"}]},"底":{"expl":"山居也。一曰下也。从广氐聲。","rad":"广","fq":"都礼切","vol":"09","py":"dǐ","duan":[{"e":"山凥也。","n":"凥各本譌作居。今正。山當作止。字之誤也。字从广、故曰止凥。玉篇曰。底、止也、下也。廣韵曰。底、下也、止也。皆本說文。釋詁曰。底、止也。又曰。底、止、徯、待也。晉語。戾久將疧。注曰。詆、止也。左傳昭元年。勿使有所壅閉湫底。服注。底、止也。杜注。底、滯也。楚語。夫民氣縱則底。底則滯。注曰。底、箸也。按底訓止、與厂部厎訓柔石、引伸之訓致也、至也迥別。俗書多亂之。小雅。伊于胡厎。箋云。厎、至也。俗本多作胡底。"}]},"庢":{"expl":"礙止也。从广至聲。","rad":"广","fq":"陟栗切","vol":"09","py":"zhì","duan":[{"e":"礙止也。","n":"石部曰。礙者、止也。凡庢礙當作此字。今俗作窒礙。非也。七發曰。發怒庢沓。言水初發怒、礙止而湧沸也。又右扶風有盩庢縣。山曲曰盩。水曲曰庢。"}]},"廮":{"expl":"安止也。从广嬰聲。鉅鹿有廮陶縣。","rad":"广","fq":"於郢切","vol":"09","py":"yǐnɡ","duan":[{"e":"安止也。从广。嬰聲。","n":"於郢切。十一部。"}]},"𢇷":{"expl":"舍也。从广犮聲。《詩》曰：“召伯所𢇷。”","rad":"广","fq":"蒱撥切","vol":"09","py":"bá","duan":[{"e":"舍也。","n":"詩召南甘棠曰。召伯所茇。傳曰。茇、草舍也。周禮大司馬。中夏敎茇舍。注云。茇讀如萊沛之沛。茇舍、草止之也。軍有草止之法。按許書艸部茇、艸根也。此𢇷訓舍也。與毛、鄭說異。以其字从艸从广別之耳。同音故義相因。茇𢇷實古今字也。毛傳又云。草行曰跋。跋卽茇之假借字。漢禮樂志。拔蘭堂。拔、舍止也。卽𢇷之假借字。"}]},"庳":{"expl":"中伏舍。从广卑聲。一曰屋庳。或讀若逋。","rad":"广","fq":"便俾切","vol":"09","py":"bì","duan":[{"e":"中伏舍。","n":"謂高其兩㫄而中低伏之舍也。"}]},"庇":{"expl":"蔭也。从广比聲。","rad":"广","fq":"必至切","vol":"09","py":"bì","duan":[{"e":"蔭也。","n":"蔭、艸侌也。引伸之爲凡覆庇之偁。釋言曰。庇、休、蔭也。"}]},"庶":{"expl":"屋下眾也。从广、炗。炗，古文光字。","rad":"广","fq":"商署切","vol":"09","py":"shù","duan":[{"e":"屋下眾也。","n":"諸家皆曰。庶、眾也。許獨云屋下衆者、以其字从广也。釋言曰。庶、侈也。侈鄭箋作䏧。此引伸之義。又引伸之。釋言曰。庶、幸也。詩素冠傳同。又釋言曰。庶幾、尙也。"}]},"庤":{"expl":"儲置屋下也。从广寺聲。","rad":"广","fq":"直里切","vol":"09","py":"zhì","duan":[{"e":"儲置屋下也。","n":"庤與偫音義同。云置屋下者、以其字从广也。周頌。庤乃錢鎛。傳曰。庤、具也。"}]},"廙":{"expl":"行屋也。从广異聲。","rad":"广","fq":"與職切","vol":"09","py":"yì","duan":[{"e":"行屋也。","n":"行屋、所謂幄也。許書巾部無幄篆。周禮。帷幕幄帟。注云。四合象宮室曰幄。王所居之帳也。疏引顔延之纂要四合象官曰幄。巾部曰。帳、張也。木部曰。橦者、帳柱也。帳有樑柱可移徙。如今之蒙古包之類。廙字本義如是。魏晉後用爲翼字。如魏丁廙字敬禮。是用爲小心翼翼字也。篇、韵皆曰。廙、敬也。"}]},"䔯":{"expl":"韭鬱也。从艸酤聲。","rad":"艸","fq":"苦步切","vol":"01","py":"kù","duan":[{"e":"韭鬱也。","n":"鬱同？。廣雅。寑䤁鬱？幽也。皆謂飲食也。此許君酤訓韭鬱、豉訓幽尗之證。"}]},"廔":{"expl":"屋麗廔也。从广婁聲。一曰穜也。","rad":"广","fq":"洛侯切","vol":"09","py":"lóu","duan":[{"e":"屋麗廔也。","n":"麗廔讀如離婁二音。囧字下曰。窗牖麗廔闓明也。長門賦、靈光殿賦皆作離樓。謂在屋在牆囪牖穿通之皃。玉篇作蠡廔。"}]},"㢈":{"expl":"屋从上傾下也。从广隹聲。","rad":"广","fq":"都回切","vol":"09","py":"tuí","duan":[{"e":"屋从上傾下也。","n":"㢈之下推也。"}]},"廢":{"expl":"屋頓也。从广發聲。","rad":"广","fq":"方肺切","vol":"09","py":"fèi","duan":[{"e":"屋頓也。","n":"頓之言鈍。謂屋鈍置無居之者也。引伸之、凡鈍置皆曰廢。淮南覽冥訓。四極廢。高注。廢、頓也。古謂存之爲置。棄之爲廢。亦謂存之爲廢。棄之爲置。公羊傳曰。去其有聲者。廢其無聲者。鄭曰。廢、置也。于去聲者爲廢。謂廢畱不去也。左傳。廢六關。王肅家語作置六關。淮南子。舜葬蒼梧。不變其肆。高注。不煩市井之所廢。莊子曰。廢一於堂。廢一於室。仲尼弟子列傳。子貢好廢居。與時轉貨。貨殖列傳作廢箸鬻財。徐廣曰。箸猶居也。讀如貯。廢之爲置如徂之爲存、苦之爲快、亂之爲治、去之爲藏。"}]},"庮":{"expl":"久屋朽木。从广酉聲。《周禮》曰：“牛夜鳴則𢉷。”臭如朽木。","rad":"广","fq":"與久切","vol":"09","py":"yǒu","duan":[{"e":"久屋朽木。","n":"朽同㱙。見歹部。周禮內饔。牛夜鳴則庮。先鄭云。庮、朽木臭也。內則鄭注云。庮、惡臭也。引春秋傳一薰一庮。許說同先鄭。久屋而後有朽木。故字从广。"}]},"廑":{"expl":"少劣之居。从广堇聲。","rad":"广","fq":"巨斤切","vol":"09","py":"jǐn","duan":[{"e":"少劣之凥。","n":"凥舊作居。誤。今正。少劣之居、故从广。引伸之義與人部之僅同。古多用廑爲僅。亦用爲勤字。文選長楊賦注引古今字詁曰。厪今勤字。"}]},"廟":{"expl":"尊先祖皃也。从广朝聲。","rad":"广","fq":"眉召切","vol":"09","py":"miào","duan":[{"e":"尊先祖皃也。","n":"尊其先祖而以是儀皃之。故曰宗廟。諸書皆曰。廟、皃也。祭法注云。廟之言皃也。宗廟者、先祖之尊皃也。古者廟以祀先祖。凡神不爲廟也。爲神立廟者、始三代以後。"}]},"㡹":{"expl":"人相依㡹也。从广且聲。","rad":"广","fq":"子余切","vol":"09","py":"jū","duan":[{"e":"人相依㡹也。从广。且聲。","n":"子余切。五部。按篇、韵皆七賜切。則與且聲不相應。廣雅無㡹有㢀。音七賜切。玉篇㡹字亦不次於援引說文之處。疑許本無㡹。"}]},"𢉥":{"expl":"屋迫也。从广曷聲。","rad":"广","fq":"於歇切","vol":"09","py":"yè","duan":[{"e":"屋迫也。","n":"𢉥之言遏也。"}]},"㡿":{"expl":"郤屋也。从广屰聲。","rad":"广","fq":"昌石切","vol":"09","py":"chì","duan":[{"e":"卻屋也。","n":"卻屋者、謂開拓其屋使廣也。與上屋迫成反對。廣韵引作卻行也。非是。卻屋之義引伸之爲𢇛逐、爲充𢇛。魏都賦注引倉頡曰。𢇛、廣也。又引伸爲𢫾𢇛。穀梁僖五年傳曰目晉矦𢇛殺是也。"}]},"廞":{"expl":"陳輿服於庭也。从广欽聲。讀若歆。","rad":"广","fq":"許今切","vol":"09","py":"xīn","duan":[{"e":"陳輿服於庭也。","n":"周禮故書廞爲淫。鄭司農云。淫讀爲廞。廞、陳也。許說同先鄭。釋詁曰。廞、興也。後鄭注周禮云。廞、興也。興作之說同爾雅。按易淫爲廞、古音同在七部也。釋廞爲興、古六部七部合音也。"}]},"蘫":{"expl":"瓜菹也。从艸監聲。","rad":"艸","fq":"魯甘切","vol":"01","py":"lán","duan":[{"e":"𤓰菹也。从艸。濫聲。","n":"各本篆作藍。解誤作監聲。今依廣韵、集韵訂。魯甘切。八部。"}]},"廫":{"expl":"空虚也。从广膠聲。","rad":"广","fq":"洛蕭切","vol":"09","py":"liáo","duan":[{"e":"空虛也。从广。膠聲。","n":"此今之寥字。洛蕭切。古音在三部。"}]},"廈":{"expl":"屋也。从广夏聲。","rad":"广","fq":"胡雅切","vol":"09","py":"xià","duan":[]},"廊":{"expl":"東西序也。从广郎聲。《漢書》通用郎。","rad":"广","fq":"魯當切","vol":"09","py":"lánɡ","duan":[]},"廂":{"expl":"廊也。从广相聲。","rad":"广","fq":"息良切","vol":"09","py":"xiānɡ","duan":[]},"庪":{"expl":"祭山曰庪縣。从广技聲。","rad":"广","fq":"過委切","vol":"09","py":"ɡuǐ","duan":[]},"庱":{"expl":"地名。从广，未詳。","rad":"广","fq":"丑抍切","vol":"09","py":"chěnɡ","duan":[]},"廖":{"expl":"人姓。从广，未詳。當是省廫字尔。","rad":"广","fq":"力救切","vol":"09","py":"liào","duan":[]},"厂":{"expl":"山石之厓巖，人可居。象形。凡厂之屬皆从厂。","rad":"厂","fq":"呼旱切","vol":"09","py":"hǎn","duan":[{"e":"山石之厓巗。人可凥。","n":"凥舊作居。今正。厓、山邊也。巗者、厓也。人可居者、謂其下可居也。屋其上則謂之广。"}]},"厓":{"expl":"山邊也。从厂圭聲。","rad":"厂","fq":"五佳切","vol":"09","py":"yá","duan":[{"e":"山邊也","n":"高邊則曰崖。"}]},"厜":{"expl":"厜㕒，山顚也。从厂垂聲。","rad":"厂","fq":"姉宜切","vol":"09","py":"zuī","duan":[{"e":"𠪪㕒、","n":"逗。"}]},"䓜":{"expl":"菹也。从艸泜聲。","rad":"艸","fq":"直宜切","vol":"01","py":"zhī","duan":[{"e":"菹也。从艸。泜聲。","n":"纏伊切。十五部。"}]},"㕒":{"expl":"厜㕒也。从厂義聲。","rad":"厂","fq":"魚爲切","vol":"09","py":"wēi","duan":[{"e":"𠪪㕒也。从厂。義聲。","n":"魚爲切。古音在十七部。"}]},"𠪚":{"expl":"崟也。一曰地名。从厂敢聲。","rad":"厂","fq":"魚音切","vol":"09","py":"yín","duan":[{"e":"崟也。","n":"崟者、山之岑崟也。"}]},"厬":{"expl":"仄出泉也。从厂晷聲。讀若軌。","rad":"厂","fq":"居洧切","vol":"09","py":"ɡuǐ","duan":[{"e":"仄出泉也。","n":"小雅。有洌氿泉。釋水曰。氿泉穴出。穴出、仄出也。毛傳。側出曰氿泉。按側出泉之字詩、爾雅作氿。許作厬。水醮之字今爾雅作厬、許作氿。正互相易。水部氿篆下引爾雅水醮曰氿。則知許所據與今本絕異。水厓枯土爲氿字。側出泉當作厬字矣。"}]},"厎":{"expl":"柔石也。从厂氐聲。","rad":"厂","fq":"職雉切","vol":"09","py":"dǐ","duan":[{"e":"柔石也。","n":"柔石、石之精細者。鄭注禹貢曰。厲摩刀刃石也。精者曰砥。尙書大傳。其桷、天子斲其材而礱之。加密石焉。注曰。礱、厲之也。密石、砥之也。按厎者、砥之正字。後人乃謂砥爲正字。厎與砥異用。強爲分別之過也。厎之引伸之義爲致也、至也、平也。有假借耆字爲之者。如周頌耆定爾功傳曰耆、致也是也。"}]},"厥":{"expl":"發石也。从厂欮聲。","rad":"厂","fq":"俱月切","vol":"09","py":"jué","duan":[{"e":"發石也。","n":"發石、故从厂。引伸之凡有撅發皆曰厥。山海經曰。相桺之所抵厥。郭云。抵觸。厥掘也。孟子。若𡹔厥角稽首。趙云。厥角者、叩頭以額角犀撅地也。晉灼注漢書曰。厥猶豎也。叩頭則額角豎。按厥角者、謂額角如有所發。角部{厥+角[上下]}(𧤼)下云角有所觸發是也。以上皆厥之本義。若釋言曰。厥、其也。此假借也。假借盛行而本義廢矣。"}]},"厲":{"expl":"旱石也。从厂，蠆省聲。","rad":"厂","fq":"力制切","vol":"09","py":"lì","duan":[{"e":"旱石也。","n":"旱石者、剛於柔石者也。禹貢。厲砥砮丹。大雅。取厲取鍛。引伸之義爲作也。見釋詁。又危也。見大雅民勞傳、虞注周易。又烈也。見招䰟王注。俗以義異、異其形。凡砥厲字作礪。凡勸勉字作勵。惟嚴厲字作厲。而古引伸假借之法隠矣。凡經傳中有訓爲惡、訓爲病、訓爲鬼者、謂厲卽癘之假借也。訓爲遮列者、謂厲卽迾之假借也。周禮之厲禁是也。有訓爲涉水者、謂厲卽濿之假借。如詩深則厲是也。有訓爲帶之𡍮者、如都人士垂帶而厲。傳謂厲卽烈之假借也。烈、餘也。"}]},"厱":{"expl":"厱諸，治玉石也。从厂僉聲。讀若藍。","rad":"厂","fq":"魯甘切","vol":"09","py":"lán","duan":[{"e":"厱諸、","n":"逗。"}]},"厤":{"expl":"治也。从厂秝聲。","rad":"厂","fq":"郎擊切","vol":"09","py":"lì","duan":[{"e":"治也。","n":"甘部曆下云。从甘厤。厤者、調也。按調和卽治之義也。厤从秝。秝者、稀疏適秝也。"}]},"𠪙":{"expl":"石利也。从厂異聲。讀若枲。","rad":"厂","fq":"胥里切","vol":"09","py":"xǐ","duan":[{"e":"石利也。","n":"謂石銳也。漢書馮奉世傳。器不犀利。如淳曰。今俗刀兵利爲犀。後漢張衡傳犀舟注同。按石之利、如砮砭厎厲厝是也。犀與𠪙雙聲。假借石利之義。引伸之、凡利皆曰𠪙。犀宋本漢書作屖。"}]},"㕆":{"expl":"美石也。从厂古聲。","rad":"厂","fq":"矦古切","vol":"09","py":"hù","duan":[{"e":"美石也。从厂。古聲。","n":"矦古切。五部。廣韵又當古切。"}]},"䕩":{"expl":"乾梅之屬。从艸橑聲。《周禮》曰：“饋食之籩，其實乾䕩。”後漢長沙王始煑艸爲䕩。","rad":"艸","fq":"盧皓切","vol":"01","py":"lǎo","duan":[{"e":"乾梅之屬。","n":"鄭注周禮云。乾䕩、乾梅也。有桃諸梅諸、是其乾者。按鄭意周禮上文桃是濡者。此著乾以別之。"}]},"厗":{"expl":"唐厗，石也。从厂，屖省聲。","rad":"厂","fq":"杜兮切","vol":"09","py":"tí","duan":[{"e":"唐厗石也。","n":"四字句。唐厗雙聲字。石名也。廣韵、齊韵、唐韵皆作磄厗。又曰。鎕銻、火齊也。玉篇曰。厗古銻字。"}]},"㕇":{"expl":"石聲也。从厂立聲。","rad":"厂","fq":"盧荅切","vol":"09","py":"lā","duan":[{"e":"石聲也。","n":"謂石𡹔之聲。吳都賦曰。拉擸雷硍。崩巒弛岑。拉卽㕇字也。玉篇曰。㕇亦拉字。拉者、折也。柆、木折也。"}]},"𠩫":{"expl":"石地惡也。从厂兒聲。","rad":"厂","fq":"五歴切","vol":"09","py":"yì","duan":[{"e":"石地惡也。","n":"集韵、類篇皆曰。䃒𠩫、石地。按石部曰。䃒石地惡也。二篆曡韵。"}]},"㕋":{"expl":"石地也。从厂金聲。讀若紟。","rad":"厂","fq":"巨今切","vol":"09","py":"qín","duan":[{"e":"石地也。","n":"㕋者、堅閉之意。"}]},"㕊":{"expl":"石閒見。从厂甫聲。讀若敷。","rad":"厂","fq":"芳無切","vol":"09","py":"fū","duan":[{"e":"石閒見也。","n":"閒讀去聲。閒見、謂突兀忽見。人部俔下云閒見是也。㕊、史假逋字爲之。魏書、北史溫子昇傳皆云。子昇詣梁客館。不修容止。謂人曰。詩章易作。逋峭難爲。字當作㕊。廣韵引字林云。峬峭、好形皃也。峬卽㕊之隸隷變。凡字書因時而作。故說文㕊、字林作峬。說文祗有殷、字林有黫。近世波俏之語、又音字之遷移也。"}]},"厝":{"expl":"厲石也。从厂㫺聲。《詩》曰：“他山之石，可以爲𠪞。”","rad":"厂","fq":"倉各切","vol":"09","py":"cuò","duan":[{"e":"厝石也。","n":"各本作厲石。今正。小雅鶴鳴曰。他山之石。可以爲錯。傳曰。錯、錯石也。（今本少一錯字）可以琢玉。舉賢用滯、則可以治國。下章曰。他山之石。可以攻玉。傳曰。攻、錯也。錯古作厝。厝石、謂石之可以攻玉者。爾雅。玉曰琢之。玉至堅。厝石如今之金剛鑽之類。非厲石也。假令是厲石。則當次厎厲二篆之下、而不當次此矣。金部鑢下云。錯銅鐵也。錯亦當作厝。謂剗磢之。"}]},"厖":{"expl":"石大也。从厂尨聲。","rad":"厂","fq":"莫江切","vol":"09","py":"mánɡ","duan":[{"e":"石大也。","n":"石大其本義也。引伸之爲凡大之偁。釋詁曰。厖、大也。左傳民生敦厖、周語敦厖純固是也。又引伸之爲厚也。商頌爲下國駿厖毛傳是也。或假此厖爲尨襍字。荀𨜮引商頌厖作蒙。"}]},"𠨲":{"expl":"岸上見也。从厂，从之省。讀若躍。","rad":"厂","fq":"以灼切","vol":"09","py":"yuè","duan":[{"e":"岸上見也。","n":"岸者、厓陖而高也。岸上見、故从厂屮會意。上見者、朢之而見於上也。"}]},"𠩘":{"expl":"𠪮也。从厂夾聲。","rad":"厂","fq":"胡甲切","vol":"09","py":"xiá","duan":[{"e":"𠪮也。","n":"𠩘與陜音同義近。"}]},"仄":{"expl":"側傾也。从人在厂下。","rad":"厂","fq":"阻力切","vol":"09","py":"zè","duan":[{"e":"側傾也。","n":"傾下曰。仄也。此仄下云。傾也。是之謂轉注。古與側昃字相假借。"}]},"𧆈":{"expl":"煎茱萸。从艸𩕺聲。漢津：會稽獻𧆈一斗。","rad":"艸","fq":"魚旣切","vol":"01","py":"yì","duan":[{"e":"煎茱萸。","n":"内則。三牲用藙。鄭云。藙、煎茱萸也。漢律㑹稽獻焉。爾雅謂之榝。玉裁謂。許君云榝似茱萸、出淮南。則與鄭說異。皇侃義疏曰。煎茱萸、今蜀郡作之。九月九日取茱萸。折其枝。連其實。廣長四五寸。一升實可和十升膏。名之藙也。本艸圖經曰。食茱萸。蜀人呼其子爲艾子。按艾卽藙字。"}]},"𠪮":{"expl":"仄也。从厂辟聲。","rad":"厂","fq":"普擊切","vol":"09","py":"pì","duan":[{"e":"仄也。","n":"仄俗本譌作反。今依篇、韵正。今人言偪仄、乃當作𠪮仄。"}]},"厞":{"expl":"隱也。从厂非聲。","rad":"厂","fq":"扶沸切","vol":"09","py":"fèi","duan":[{"e":"隠也。","n":"隠者、蔽也。特牲饋食禮。佐食徹尸薦俎。敦于西北隅。几在南厞。有司徹。有司官徹饋。饌于室中西北隅。設右几厞。鄭云。厞、隠也。喪大記。甸人取所徹廟之西北厞薪用爨之。按室西北隅曰屋漏。厞者、又西北隅隠蔽之處也。屈原賦。隠思君兮陫側。陫葢同厞。禮注曰。古文厞作茀。"}]},"厭":{"expl":"笮也。从厂猒聲。一曰合也。","rad":"厂","fq":"於輒切","vol":"09","py":"yā","duan":[{"e":"笮也。","n":"竹部曰。笮者、迫也。此義今人字作壓。乃古今字之殊。土部壓訓壞也、𡨄也。無笮義。凡喪服言尊之所厭、皆笮義。喪冠謂之厭冠。謂冠出武下也。周禮巾車。王后厭翟。注云。次其羽使相迫也。禮經。推手曰揖。引手曰厭。厭卽尙書大傳、家語之葉拱。家語注云。兩手薄其心。古文禮揖、厭分別。今文禮厭皆爲揖。鄭不之從。而禮經有厭譌作撎者。周禮大祝疏竟作引手曰撎。斷不可從。撎爲跪而舉頭下手、與厭爲立而引手箸𦙄不相涉也。檀弓。死而不弔者厭。注。行止危險之下。已上皆笮之義。其音於輒切。"}]},"厃":{"expl":"仰也。从人在厂上。一曰屋梠也，秦謂之桷，齊謂之厃。","rad":"厂","fq":"魚毀切","vol":"09","py":"wěi","duan":[{"e":"仰也。从人在厂上。","n":"會意。魚毀切。十六部。危字从厃卪會意。"}]},"丸":{"expl":"圜，傾側而轉者。从反仄。凡丸之屬皆从丸。","rad":"丸","fq":"胡官切","vol":"09","py":"wán","duan":[{"e":"圜也。","n":"也字各本無。今依韵會補。以曡韵爲訓也。今丸藥其一耑也。商頌。松栢丸丸。傳曰。丸丸、易直也。按謂其滑易而調直也。丸義之引伸也。大雅。松柏斯兌。傳亦云。兌、易直也。兌與丸、古葢音同而義同矣。"}]},"𠷏":{"expl":"鷙鳥食已，吐其皮毛如丸。从丸咼聲。讀若骫。","rad":"丸","fq":"於跪切","vol":"09","py":"wěi","duan":[{"e":"鷙鳥食已吐其皮毛如丸。","n":"玉裁昔宰巫山縣。親見鴟鳥所吐皮毛如丸。"}]},"䎠":{"expl":"丸之孰也。从丸而聲。","rad":"丸","fq":"奴禾切","vol":"09","py":"nuó","duan":[{"e":"丸之孰也。","n":"俗所謂圜熟。言旋轉之易也。"}]},"奿":{"expl":"闕。","rad":"丸","fq":"芳萬切","vol":"09","py":"fàn","duan":[{"e":"闕。","n":"謂其義、其形、其音說皆闕也。廣韵入二十五願。芳万切。引說文。其義闕。其義二字、乃廣韵所增耳。玉篇同。○芳萬切。則與𡢎娩二字同音。集韵云。于願切。引李舟云說文闕。"}]},"危":{"expl":"在高而懼也。从厃，自卪止之。凡危之屬皆从危。","rad":"危","fq":"魚爲切","vol":"09","py":"wēi","duan":[{"e":"在高而懼也。","n":"引伸爲凡可懼之偁。喪大記注。危、棟上也。"}]},"㩻":{"expl":"㩻䧢也。从危支聲。","rad":"危","fq":"去其切","vol":"09","py":"qī","duan":[{"e":"㩻、","n":"此複舉字之未𠜂者。"}]},"䔂":{"expl":"羹菜也。从艸宰聲。","rad":"艸","fq":"阻史切","vol":"01","py":"zǐ","duan":[{"e":"羹菜也。","n":"謂取菜羹之也。集韵有？字、烹也。卽此字。"}]},"石":{"expl":"山石也。在厂之下；囗，象形。凡石之屬皆从石。","rad":"石","fq":"常隻切","vol":"09","py":"shí","duan":[{"e":"山石也。","n":"或借爲碩大字。或借爲䄷字。䄷、百二十斤也。"}]},"磺":{"expl":"銅鐵樸石也。从石黃聲。讀若穬。","rad":"石","fq":"古猛切","vol":"09","py":"kuànɡ","duan":[{"e":"銅鐵樸石也。","n":"文選注二引及玉篇無石字。樸、木素也。因以爲凡素之偁。銅鐵樸者、在石與銅鐵之閒。可爲銅鐵而未成者也。不言金玉者、舉觕以該精也。周禮卝人掌。金玉錫石之地。而爲之厲禁以守之。注云。卝之言礦也。金玉未成噐曰礦。未成噐、謂未成金玉。"}]},"碭":{"expl":"文石也。从石昜聲。","rad":"石","fq":"徒浪切","vol":"09","py":"dànɡ","duan":[{"e":"文石也。","n":"地理志。梁國碭縣。山出文石。應劭云。碭山在東。師古云。山出文石、故以名縣也。按以碭名山。又以碭名縣。本爲文石之名。"}]},"碝":{"expl":"石次玉者。从石耎聲。","rad":"石","fq":"而沇切","vol":"09","py":"ruǎn","duan":[{"e":"石次玉者。","n":"子虛賦。碝石武夫。張揖曰。皆石之次玉者。碝石白如冰半。有赤色。武夫赤地白采。蔥蘢白黑不分。按此注有奪誤。如冰半、謂如冰片也。有赤色宜依山海經注作有赤色者。蔥蘢白黑不分、亦宜依山海經注作色蔥蘢不分了。西都賦曰。碝磩采致。"}]},"砮":{"expl":"石，可以爲矢鏃。从石奴聲。《夏書》曰：“梁州貢砮丹。”《春秋國語》曰：“肅愼氏貢楛矢石砮。”","rad":"石","fq":"乃都切","vol":"09","py":"nú","duan":[{"e":"砮石可㠯爲矢鏃。","n":"砮石之名、淺人以爲複字。𠜂之則不完。鏃當作族族、矢鋒也。禹貢荆州梁州皆貢砮。賈逵注國語曰。砮、矢鏃之石也。按砮本石名。韋昭注石砮云。砮、鏃也。以石爲之。乃少誤。"}]},"礜":{"expl":"毒石也。出漢中。从石與聲。","rad":"石","fq":"羊茹切","vol":"09","py":"yù","duan":[{"e":"毒石也。","n":"疑本作礜石也。三字爲句。後人改之。嚳石、石名。周禮注曰。今醫方有五毒之藥。作之。合黃堥。置石膽、丹沙雄黃、礜石、慈石其中。燒之三日三夜。其煙上箸。以雞羽埽取之。以注創。惡肉破。骨則盡出。本艸經曰。礜石、味辛有毒。西山經曰。礜可以毒鼠。郭云。蠶食之而肥。按今世無此物。"}]},"碣":{"expl":"特立之石。東海有碣石山。从石曷聲。","rad":"石","fq":"渠列切","vol":"09","py":"jié","duan":[{"e":"特立之石也。","n":"碣之言傑也。"}]},"磏":{"expl":"厲石也。一曰赤色。从石兼聲。讀若鎌。","rad":"石","fq":"力鹽切","vol":"09","py":"lián","duan":[{"e":"厲石也。","n":"與厱音義略同。"}]},"碬":{"expl":"厲石也。从石叚聲。《春秋傳》曰：“鄭公孫碬字子石。”","rad":"石","fq":"乎加切","vol":"09","py":"xiá","duan":[{"e":"碫石也。","n":"碫篆舊作碬。九經字㨾所引說文已然。今依詩釋文及玉篇正。碫石本作萬石。自詩釋文所引已然。今正。大雅。取厲取碫。今本作取鍛。當依釋文本又作碫。毛傳曰。碫、（逗）碫石也。（今本奪一字）箋云。碫石、（此釋傳）所以爲鍛質也。箋意、此石可爲椎段之椹質。是則碫石者、石名。椎段字今多用鍛。古祗作段。𦒱工段氏爲鎛噐、禮經段脩、字皆作段是也。段與厲絕然二事。碫石、厲石必是二物。尙書粊誓。段乃戈矛。厲乃鋒刃。段之欲其質之堅也。厲之欲其刃之利也。詩取厲取鍛。亦明明分別言之。毛傳亦旣確𢫾云碫石矣。豈許君於此乃忽溷淆之、訓碫爲厲石乎。揆厥所由。由許依傳云碫石也三字爲句。而𠜂複字者乃妄改爲厲字。猶上礜篆下本云礜石也。而𠜂複"}]},"礫":{"expl":"小石也。从石樂聲。","rad":"石","fq":"郎擊切","vol":"09","py":"lì","duan":[{"e":"小石也。","n":"釋名。小石曰礫。礫、料也。小石相枝柱其閒。料料然出內氣也。楚辭王逸注兩云。小石爲礫。西京賦薛注。石細者曰礫。"}]},"若":{"expl":"擇菜也。从艸、右。右，手也。一曰杜若，香艸。","rad":"艸","fq":"而灼切","vol":"01","py":"ruò","duan":[{"e":"擇菜也。","n":"晉語。秦穆公曰。夫晉國之亂。吾誰使先若夫二公子而立之。以爲朝夕之急。此謂使誰先擇二公子而立之。若正訓擇。擇菜引伸之義也。"}]},"䂬":{"expl":"水邊石。从石巩聲。《春秋傳》曰：“闕䂬之甲。”","rad":"石","fq":"居竦切","vol":"09","py":"ɡǒnɡ","duan":[{"e":"水邊石也。从石。𢀜聲。","n":"居竦切。古音在三部。"}]},"磧":{"expl":"水陼有石者。从石責聲。","rad":"石","fq":"七迹切","vol":"09","py":"qì","duan":[{"e":"水陼有石者。","n":"陼丘、水中高者也。三蒼曰。磧、水中沙堆也。吳都賦劉注曰。磧礫、淺水見沙石之皃。"}]},"碑":{"expl":"豎石也。从石卑聲。","rad":"石","fq":"府眉切","vol":"09","py":"bēi","duan":[{"e":"豎石也。","n":"聘禮鄭注曰。宮必有𥓓。所以識日景、引陰陽也。凡𥓓引物者。宗廟則麗牲焉。其材、宮廟以石。窆用木。檀弓。公室視豐𥓓。三家視。桓楹。注曰。豐𥓓、斲大木爲之。形如石𥓓。於椁前後四角豎之。穿中於閒爲鹿盧。下棺以繂繞。天子六繂四𥓓。前後各重鹿盧也。諸矦四繂二𥓓。大夫二繂二𥓓。士二繂無𥓓。按此檀弓注卽聘禮注所謂窆用木也。非石而亦曰𥓓、假借之偁也。秦人但曰刻石、不曰𥓓。後此凡刻石皆曰𥓓矣。始皇本紀。上鄒嶧山立石。上泰山立石。下皆云刻所立石。其書法之詳也。凡刻石必先立石。故知豎石者𥓓之本義。宮廟識日影者是。"}]},"䃍":{"expl":"陖也。从石㒸聲。","rad":"石","fq":"徒對切","vol":"09","py":"zhuì","duan":[{"e":"陊也。","n":"陊者、落也。䃍與隊音義同。隊者、从高隊也。廣韵曰。礧䃍、物墜也。"}]},"磒":{"expl":"落也。从石員聲。《春秋傳》曰：“磒石于宋五。”","rad":"石","fq":"于敏切","vol":"09","py":"yǔn","duan":[{"e":"落也。","n":"磒與隕音義同。隕者、從高下也。春秋經僖公十有六年。隕石于宋五。左、穀作霣。許所據左傳作磒。釋詁。隕、磒、落也。郭云。磒猶隕也。"}]},"䂹":{"expl":"碎石磒聲。从石炙聲。","rad":"石","fq":"所責切","vol":"09","py":"suǒ","duan":[{"e":"碎石磒聲。","n":"磒舊作隕。今正。其聲䂹䂹然。"}]},"硞":{"expl":"石聲。从石告聲。","rad":"石","fq":"苦角切","vol":"09","py":"què","duan":[{"e":"石聲。","n":"今爾雅釋言。硈、𩊳也。郭云。硈然堅固。邢昺曰。硈苦學切。當从告。說文別有硈。苦八切。石堅也。按邢語剖別甚精。釋文苦角切。故邢曰苦學切。四覺韵字多從屋韵轉入。如四江韵字多從東韵轉。入。告聲在古音三部屋韵。是以硞轉入覺韵。據陸氏反語。則知陸本作硞不作硈。廣韵、玉篇皆曰。硞苦角切。硈恪八切。集韵、類篇克角一切內亦有硞無硈。皆河證。而釋文、注、疏、唐石經皆譌作硈。則與陸氏苦角之音不合矣。且硞之與鞏音切近。以九韵與東韵切近。而硈與鞏不相關也。硈斷無苦學之音。硞斷無苦八之音。此一定之音理。學者不知古音不可與讀古者此也。江賦曰。幽𧯎積岨。礐硞䃕確。礐硞當上音學、下音角。○或問何不正音之苦角爲苦八。而謂正文字"}]},"硠":{"expl":"石聲。从石良聲。","rad":"石","fq":"魯當切","vol":"09","py":"lánɡ","duan":[{"e":"石聲。从石。𥃩聲。","n":"此篆各本作硠(篆)。从石、良聲。魯當切。今正。按今子虛賦。礧石相擊。硍硍礚礚。史記、文選皆同。漢書且作琅。以音求義、則當爲硍硍。而決非硠硠。何以明之。此賦言水蟲駭波鴻沸。湧泉起奔揚會。礧石相擊。硍硍礚礚。若雷霆之聲。聞乎數百里之外。謂水波大至動摇山石。石聲磤天。硍硍者、石旋運之聲也。礚礚者、石相觸大聲也。硍篇、韵音諧眼切。古音讀如痕。可以皃石旋運大聲。而硠硠字衹可皃淸朗小聲。非其狀也。音不足以皃義。則斷知其字之誤矣。江賦曰。巨石硉矹以前却。又曰。觸由崖以縈繞。駭奔浪而相礧。皆卽此賦之意。漢柱陽太守周憬𥓓。𢐀水之邪性。順導其經脈。斷硍濭之電波。弱陽矦之汹湧。此用子虛賦也。而硠作硍。可證予說之不繆"}]},"礐":{"expl":"石聲。从石，學省聲。","rad":"石","fq":"胡角切","vol":"09","py":"què","duan":[{"e":"石聲也。","n":"此與山部嶨義別。爾雅假礐爲嶨耳。江賦曰。幽㵎積岨。礐硞䃕確。注云。皆水激石險峻不平之皃。按當云水激石聲也。"}]},"硈":{"expl":"石堅也。从石吉聲。一曰突也。","rad":"石","fq":"格八切","vol":"09","py":"qià","duan":[{"e":"石堅也。从石。吉聲。","n":"格八切。古音在十二部。按廣韵恪八切。"}]},"丄":{"expl":"高也。此古文上，指事也。凡丄之屬皆从丄。","rad":"丄","fq":"時掌切","vol":"01","py":"shànɡ","duan":[{"e":"高也。此古文丄。","n":"古文上作𠄞。故帝下㫄下示下皆云从古文上。可以證古文本作𠄞。篆作丄。各本誤以丄爲古文。則不得不改篆文之上爲<>。而用上爲部首。使下文从𠄞之字皆無所統。示次於𠄞之恉亦晦矣。今正丄爲𠄞、[上竖为弓曲]爲丄。觀者勿疑怪可也。凡說文一書。以小篆爲質。必先舉小篆。後言古文作某。此獨先舉古文後言小篆作某。變例也。以其屬皆从古文上、不从小篆上。故出變例而別白言之。"}]},"祳":{"expl":"社肉，盛以蜃，故謂之祳。天子所以親遺同姓。从示辰聲。《春秋傳》曰：“石尚來歸祳。”","rad":"示","fq":"時忍切","vol":"01","py":"shèn","duan":[{"e":"社肉。盛之㠯蜃。故謂之祳。","n":"五經異義曰。古左氏說。脤、祭社之肉。盛之以蜃。鄭注掌蜃、杜注左傳皆同。蜃祳曡韵。經典祳多从肉作脤。詩緜箋、掌蜃注徑用蜃爲祳字。"}]},"蓴":{"expl":"蒲叢也。从艸專聲。","rad":"艸","fq":"常倫切","vol":"01","py":"tuán","duan":[{"e":"蒲叢也。","n":"本艸圖經引西京襍記曰。太液池邊皆是彫胡、紫籜、綠節、蒲叢之類。廣雅釋艸曰。蒲穗謂之蓴。大丸切。謝靈運詩。新蒲含紫茸。亦謂蒲穗。"}]},"磕":{"expl":"石聲。从石盍聲。","rad":"石","fq":"口太切","vol":"09","py":"kài","duan":[{"e":"石聲也。","n":"高唐賦曰。礫磥磥而相摩兮。巆震天之礚礚。子虛賦曰。礧石相擊。硍硍礚礚。甘泉賦曰。登長平兮雷𡔷礚。今俗用爲磕破、磕𨼦字。讀苦盍切。"}]},"硻":{"expl":"餘堅者。从石，堅省。","rad":"石","fq":"口莖切","vol":"09","py":"kēnɡ","duan":[{"e":"餘堅也。","n":"也各本作者。今依廣韵、集韵、類篇正。按硈下當云石堅聲。硻下當云餘堅聲。皆轉寫之譌。葢自䂹至磿八篆、皆皃石聲。下文訓堅之礊與此訓堅聲之硻硈義固別也。論語曰。鄙哉硜硜乎。又云。硜硜然小人哉。其字皆當作硻堅。叚借古文磬字耳。硜者、古文磬字也。鏗爾舍琴、亦當爲硻爾。又樂記石聲磬磬、當爲硻。釋名。磬者、磬也。其聲磬然堅緻。當作硻硻然堅緻。"}]},"磿":{"expl":"石聲也。从石厤聲。","rad":"石","fq":"郎擊切","vol":"09","py":"lì","duan":[{"e":"石聲也。","n":"左思蜀都賦原稾。鬼單飛丸以䃒礰。集韵曰。礰卽磿字。磿爲石聲者、謂其聲歷歷然。玉篇曰。石小聲是也。周禮遂師。抱磿。後鄭云。磿者、適歷執紼者名也。是叚磿爲歷。史記樂毅傳。故鼎反乎磿室。戰國策作歷室。○蜀都賦語見太平御覽。世說新語注引左思別傳作鬼彈飛丸以礌礉。按鬼彈見水經注若水篇。非佳物也。故改定之本無此語。"}]},"磛":{"expl":"礹，石也。从石斬聲。","rad":"石","fq":"鉅銜切","vol":"09","py":"chán","duan":[{"e":"礹石也。","n":"按磛礹二篆之解、似當依玉篇更正。磛下云。磛礹、山石皃也。礹下云。磛礹也。乃合全書之例。今本乃爲淺人所亂耳。葢磛礹古多用爲連綿字。上林賦。嶄巖嵾嵳。郭云。皆峯嶺之皃。高堂賦。登巉巖而下望。西都賦。蹷嶄巖。皆卽此二篆也。古二篆分用者。小雅。漸漸之石傳曰。漸漸、山石高峻。此磛之假借字也。節南山傳曰。節、高峻皃。嚴嚴、積石皃。此礹之假借字也。嚴詩音義作巖。謂嚴爲或本。今按許書則巖者、厓也。礹者、山石皃。音同而義別。詩當作嚴爲長。"}]},"礹":{"expl":"石山也。从石嚴聲。","rad":"石","fq":"五銜切","vol":"09","py":"yán","duan":[{"e":"石山也。从石。","n":"巖主謂山。故从山。礹主謂石。故从石。詩曰。維石嚴嚴。"}]},"礊":{"expl":"堅也。从石毄聲。","rad":"石","fq":"楷革切","vol":"09","py":"kè","duan":[{"e":"堅也。从石。毄聲。","n":"楷革切。十六部。"}]},"确":{"expl":"礊石也。从石角聲。","rad":"石","fq":"胡角切","vol":"09","py":"què","duan":[{"e":"礊也。","n":"依韵會訂。确卽今之埆字。與土部之墧音義同。丘中有麻傳曰。丘中、墝埆之處也。墝埆、謂多石瘠薄。㹜部曰。獄、确也。召南傳曰。獄、埆也。謂堅剛相訟。其引伸之義也。鉉等曰。今俗作確。"}]},"磽":{"expl":"礊石也。从石堯聲。","rad":"石","fq":"口交切","vol":"09","py":"qiāo","duan":[{"e":"礊也。","n":"與土部之墽音義同。墽下曰。磽也。孟子。地有肥磽。趙曰。磽、薄也。"}]},"硪":{"expl":"石巖也。从石我聲。","rad":"石","fq":"五何切","vol":"09","py":"é","duan":[{"e":"石巖也。","n":"巖、厓也。石巖、石厓也。玉篇作礒。"}]},"碞":{"expl":"磛嵒也。从石、品。《周書》曰：“畏于民碞。”讀與巖同。","rad":"石","fq":"五銜切","vol":"09","py":"yán","duan":[{"e":"磛碞也。","n":"磛碞各本作磛嵒。非是。今依集韵、類篇。正磛碞猶上文之磛礹。積石高峻皃也。周書召誥。畏于民碞。某氏曰。碞、僭也。葢謂碞卽僭之假借字耳。"}]},"𦭮":{"expl":"以艸補缺。从艸㐁聲。讀若陸。或以爲綴。一曰約空也。","rad":"艸","fq":"直例切","vol":"01","py":"zhì","duan":[{"e":"㠯艸補缺。","n":"廣雅釋詁四。𦭮、補也。丈例反。"}]},"磬":{"expl":"樂石也。从石、殸。象縣虡之形。殳，擊之也。古者母句氏作磬。","rad":"石","fq":"苦定切","vol":"09","py":"qìnɡ","duan":[{"e":"石樂也。","n":"石樂各本作樂石。誤。今正。樂下云。五聲八音總名也。瑟下云。弦樂也。簫、䶵下皆云。管樂也。則此當云石樂信矣。匡謬正俗所引已作樂石。其誤已久。或疑樂石字見秦繹山刻石。不知與此無涉也。彼謂可樂之石。此謂製石之樂。白虎通曰。磬者、夷則之氣也。"}]},"礙":{"expl":"止也。从石疑聲。","rad":"石","fq":"五漑切","vol":"09","py":"ài","duan":[{"e":"止也。","n":"列子黃帝篇作硋。"}]},"硩":{"expl":"上摘巖空青、珊瑚墮之。从石折聲。《周禮》有硩蔟氏。","rad":"石","fq":"丑列切","vol":"09","py":"chè","duan":[{"e":"上擿山巖空靑。珊瑚陊之。","n":"擿各本作摘。今按手部擿、搔也。搔、刮也。當正作擿。陊各本作墮。今按吳都賦。𥓊陊山谷。正用許語。當正作陊。空靑見本艸經。珊瑚見玉部。陊、落也。周禮𥓊蔟氏。掌覆妖鳥之巢。鄭司農云。𥓊讀爲擿。蔟讀爲爵蔟之蔟。謂巢也。先鄭擿音剔。謂如今人以竿毀鳥巢也。後鄭申其說曰。玄謂𥓊古字。从石、析聲。𥓊古字者、謂𥓊擿爲古今字也。从石析聲者、謂古人以石上擲毀物、故从石析會意而析亦聲也。許意空靑、珊瑚皆石也。取石、故其字从石。而覆巢用此字、乃引伸之義也。"}]},"硟":{"expl":"以石扞繒也。从石延聲。","rad":"石","fq":"尺戰切","vol":"09","py":"chàn","duan":[{"e":"㠯石衦繒也。","n":"衦各本作扞。今正。衣部衦下曰。衦、摩展衣也。廣韵二仙曰。硟、衦繒石也。急就篇有硟字。注曰。硟以石𨋚繒。色尢光澤也。今俗謂之砑。"}]},"碎":{"expl":"䃺也。从石卒聲。","rad":"石","fq":"蘇對切","vol":"09","py":"suì","duan":[{"e":"䊳也。","n":"䊳各本作䃺。其義迥殊矣。䃺所以碎物而非碎也。今正。米部曰。䊳、碎也。二篆爲轉注。䊳各書假靡爲之。孟子假糜爲之。碎者、破也。䊳者、破之甚也。義少別而可互訓。瓦部曰。𤭢者、破也。音義同。"}]},"破":{"expl":"石碎也。从石皮聲。","rad":"石","fq":"普過切","vol":"09","py":"pò","duan":[{"e":"石碎也。","n":"瓦部曰𤭢者、破也。然則碎𤭢䊳三篆同義。引伸爲碎之偁。古有假破爲坡者。如衞風傳云。泮、坡也。亦作陂。亦作破。"}]},"礱":{"expl":"䃺也。从石龍聲。天子之桷，椓而礱之。","rad":"石","fq":"盧紅切","vol":"09","py":"lónɡ","duan":[{"e":"䃺也。","n":"下文云䃺者、石磑也。此云䃺也者、其引伸之義。謂以石䃺物曰礱也。今俗謂磨穀取米曰礱。"}]},"研":{"expl":"䃺也。从石幵聲。","rad":"石","fq":"五堅切","vol":"09","py":"yán","duan":[{"e":"䃺也。","n":"亦謂以石䃺物曰硏也。手部曰摩者揅也、揅者摩也。爲轉注。此亦硏與䃺爲轉注。揅摩以手、故从手。硏䃺以石、故从石。"}]},"䃺":{"expl":"石磑也。从石靡聲。","rad":"石","fq":"模臥切","vol":"09","py":"mò","duan":[{"e":"石磑也。","n":"䃺今字省作磨。引伸之義爲硏磨。俗乃分別其音。石磑則去聲、模臥切。硏磨則平聲、莫婆切。其始則皆平聲耳。按詩。如琢如磨。釋噐、毛傳皆曰。玉謂之琢。石謂之磨。詩釋文。磨本又作摩。詩、爾雅皆言治石。非謂以石治物。然則作摩是矣。釋玄應引爾雅作石謂之摩。乃善本。"}]},"磑":{"expl":"䃺也。从石豈聲。古者公輸班作磑。","rad":"石","fq":"五對切","vol":"09","py":"wèi","duan":[{"e":"䃺也。从石。豈聲。","n":"五對切。十五部。"}]},"䔿":{"expl":"叢艸也。从艸尊聲。","rad":"艸","fq":"慈損切","vol":"01","py":"zǔn","duan":[{"e":"叢艸也。","n":"䔿䔿見魏都賦。茂盛皃。"}]},"碓":{"expl":"舂也。从石隹聲。","rad":"石","fq":"都隊切","vol":"09","py":"duì","duan":[{"e":"所㠯舂也。","n":"所㠯二字各本無。今補。舂者、擣粟也。杵臼所以舂。本斷本掘地爲之。師其意者又皆以石爲之。不用手而用足、謂之碓。桓譚新論。宓犧制杵臼之利。後世加巧。借身踐碓。按其又巧者、則水碓水磑。失聖人勞其民而生其善心之意矣。"}]},"䂿":{"expl":"舂已，復擣之曰䂿。从石沓聲。","rad":"石","fq":"徒合切","vol":"09","py":"tà","duan":[{"e":"舂已複擣之曰䂿。","n":"䂿之言沓也。取重沓之意。廣雅。䂿、舂也。"}]},"磻":{"expl":"以石箸隿𦅾也。从石番聲。","rad":"石","fq":"博禾切","vol":"09","py":"bō","duan":[{"e":"㠯石箸隿𦅾也。","n":"隿者、𦅾射飛鳥也。𦅾者、生絲縷系矰矢而以隿射也。以石箸於𦅾謂之磻。戰國策。被礛磻。引微𦅾。折淸風而抎矣。"}]},"𥗁":{"expl":"斫也。从石箸聲。","rad":"石","fq":"張略切","vol":"09","py":"zhuó","duan":[{"e":"斫也。","n":"斫者、其噐所以斫地。因謂之斫也。釋噐曰。斫謂之鐯。鐯字又作𣛰。依許則當作𥗁。郭云。钁也。金部。钁者、大鉏也。然則必以金爲之。安得从石。葢上古始爲之用石。如砮、砭之類。或以其可斫地撅石、故从石歟。"}]},"硯":{"expl":"石滑也。从石見聲。","rad":"石","fq":"五甸切","vol":"09","py":"yàn","duan":[{"e":"石滑也。","n":"謂石性滑利也。江賦曰。綠苔鬖髿乎硏上。李注。硏與硯同。按字之本義謂石滑不澀。今人硏墨者曰硯。其引伸之義也。"}]},"砭":{"expl":"以石刺病也。从石乏聲。","rad":"石","fq":"方纰切","vol":"09","py":"biān","duan":[{"e":"㠯石刺病也。","n":"以石刺病曰砭。因之名其石曰砭石。東山經。高氏之山。其下多箴石。郭云。可以爲砭針治癰腫者。素問異法方宜論。東方其治宜砭石。王云。砭石、謂以石爲鍼。按此篇以東方砭石。南方九鍼並論。知古金石並用也。後世乃無此石矣。"}]},"䃒":{"expl":"石也。惡也。从石鬲聲。","rad":"石","fq":"下革切","vol":"09","py":"hé","duan":[{"e":"石地惡也。","n":"此與厂部之𠩫音義略同。類篇曰。䃒𠩫、石地。管子沙上之次曰五塥。塥疑同䃒。"}]},"砢":{"expl":"磊砢也。从石可聲。","rad":"石","fq":"來可切","vol":"09","py":"luǒ","duan":[{"e":"磊砢也。","n":"磊砢二字雙聲。上林賦曰。永玉磊砢。張揖云。磊砢、魁礨皃也。又說樹曰。坑衡閜砢。郭璞云。閜砢、相扶持也。世說新語曰。其人磊砢而英多。"}]},"磊":{"expl":"眾石也。从三石。","rad":"石","fq":"落猥切","vol":"09","py":"lěi","duan":[{"e":"眾石皃。","n":"皃各本作也。今依廣韵訂。石三爲磊。猶人三爲衆。磊之言參也。古音在十六部。楚辭。石磊磊兮葛蔓蔓。"}]},"礪":{"expl":"䃺也。从石厲聲。經典通用厲。","rad":"石","fq":"力制切","vol":"09","py":"lì","duan":[]},"莜":{"expl":"艸田器。从艸，條省聲。《論語》曰：“以杖荷莜。”今作蓧。","rad":"艸","fq":"徒弔切","vol":"01","py":"diào","duan":[{"e":"？田器。","n":"舊作艸田器。今依韵㑹。論語疏作芸田噐。毛傳曰。芸、除艸也。孔安國曰。除艸曰芸。故其字從艸。？部有？字。金部有銚字。皆云田噐。疑皆此字之古文也。"}]},"碏":{"expl":"《左氏傳》：“衞大夫石碏。”《唐韻》云：敬也。从石，未詳。昔聲。","rad":"石","fq":"七削切","vol":"09","py":"què","duan":[]},"磯":{"expl":"大石激水也。从石幾聲。","rad":"石","fq":"居衣切","vol":"09","py":"jī","duan":[]},"碌":{"expl":"石皃。从石彔聲。","rad":"石","fq":"盧谷切","vol":"09","py":"lù","duan":[]},"砧":{"expl":"石柎也。从石占聲。","rad":"石","fq":"知林切","vol":"09","py":"zhēn","duan":[]},"砌":{"expl":"階甃也。从石切聲。","rad":"石","fq":"千計切","vol":"09","py":"qì","duan":[]},"礩":{"expl":"柱下石也。从石質聲。","rad":"石","fq":"之日切","vol":"09","py":"zhì","duan":[]},"礎":{"expl":"礩也。从石楚聲。","rad":"石","fq":"創舉切","vol":"09","py":"chǔ","duan":[]},"硾":{"expl":"擣也。从石垂聲。","rad":"石","fq":"直類切","vol":"09","py":"zhuì","duan":[]},"長":{"expl":"久遠也。从兀从匕。兀者，高遠意也。久則變化。亾聲。纼者，倒亾也。凡長之屬皆从長。","rad":"長","fq":"直良切","vol":"09","py":"chánɡ","duan":[{"e":"久遠也。","n":"久者、不暫也。遠者、不近也。引伸之爲滋長、長幼之長。今音知丈切。又爲多餘之。長、度長之長皆今音直亮切。兄下曰。長也。是滋長、長幼之長也。"}]},"𨽸":{"expl":"極、陳也。从長隶聲。","rad":"長","fq":"息利切","vol":"09","py":"sì","duan":[{"e":"極陳也。","n":"陳當作敶。敶、列也。極陳者、窮極而列之也。傳注有但言陳者。如楚茨或肆或將傳、行葦或肆之筵傳、鄉飲酒禮鄉射禮燕禮注是也。經傳有專取極意者。凡言縱恣者皆是也。釋言曰。肆、力也。毛傳大明、皇矣傳曰。肆、疾也。皆極陳之義之引伸也。又釋詁曰。肆、故也。肆、今也。毛詩緜傳、思齊傳曰。肆、故今也。此以爲語䛐也。其他或以肆爲遂。或以肆爲𩮜。或以肆爲肄。葢皆假借。"}]},"萆":{"expl":"雨衣。一曰衰衣。从艸卑聲。一曰萆藨，似烏韭。","rad":"艸","fq":"扶歴切","vol":"01","py":"pì","duan":[{"e":"雨衣。一曰衰衣。","n":"謂萆一名衰也。韋昭注齊語曰。襏襫、蓑薜衣也。薜或作襞。皆卽萆字。廣雅釋器曰。萆謂之衰。"}]},"镾":{"expl":"久長也。从長爾聲。","rad":"長","fq":"武夷切","vol":"09","py":"mí","duan":[{"e":"久長也。","n":"镾今作彌。葢用弓部之㣆代镾而又省王也。彌行而镾廢矣。漢碑多作𢑃、可證。镾之本義爲久長。其引伸之義曰大也、遠也、益也、深也、滿也、徧也、合也、縫也、竟也。其見於詩者。大雅生民、卷阿傳皆曰。彌、終也。周禮小祝假爲敉。史記禮書假爲𦗕。"}]},"镻":{"expl":"蛇惡毒長也。从長失聲。","rad":"長","fq":"徒結切","vol":"09","py":"dié","duan":[{"e":"蝁也。","n":"各本誤。今正。此用釋魚文也。虫部曰。蝁、镻也。二篆爲轉注。今各本镻篆下作虺屬者。非是。"}]},"勿":{"expl":"州里所建旗。象其柄，有三游。雜帛，幅半異。所以趣民，故遽，稱勿勿。凡勿之屬皆从勿。","rad":"勿","fq":"文弗切","vol":"09","py":"wù","duan":[{"e":"州里所建旗。","n":"九旗之一也。州里當作大夫士。周禮司常。大夫士建物。帥都建旗。州里建旟。許於旟下旣偁州里。建旟矣。則此偁大夫士建勿、必也。葢亦一時筆誤耳。大司馬。鄉家載物。注云。鄉家、鄉大夫也。鄉射禮。旌各以其物。注。襍帛爲物。大夫士之所建也。士喪禮。爲銘各以其物。注。襍帛爲物。大夫之所建也。文弗切。十五部。經傳多作物、而假借勿爲毋字。亦有借爲沒字者。禮記。勿勿乎其欲其饗之。勿勿卽沒沒、猶勉勉也。"}]},"昜":{"expl":"開也。从日、一、勿。一曰飛揚。一曰長也。一曰彊者眾皃。","rad":"勿","fq":"與章切","vol":"09","py":"yánɡ","duan":[{"e":"開也。","n":"此陰陽正字也。陰陽行而侌昜廢矣。闢戸謂之乾。故曰開也。"}]},"冄":{"expl":"毛冄冄也。象形。凡冄之屬皆从冄。","rad":"冄","fq":"而𤥎切","vol":"09","py":"rǎn","duan":[{"e":"毛冄冄也。","n":"冄冄者、柔弱下垂之皃。須部之𩓾、取下垂意。女部之㚩、取弱意。離騷。老冄冄其將至。此借冄冄爲冘冘。詩。荏染柔木。傳曰。荏染、柔意也。染卽冄之假借。凡言冄、言㚩皆謂弱。"}]},"而":{"expl":"頰毛也。象毛之形。《周禮》曰：“作其鱗之而。”凡而之屬皆从而。","rad":"而","fq":"如之切","vol":"09","py":"ér","duan":[{"e":"須也。象形。","n":"各本作頰毛也、象毛之形。今正。頰毛者、須部所謂？須之類耳。禮運正義引說文曰。而、須也。須謂頤下之毛。象形字也。知唐初本須篆下頤毛也。而篆下云須也。二篆相爲轉注。其象形、則首畫象鼻耑。次象人中。次象口上之頾。次象承漿及頤下者。葢而爲口上口下之總名。分之則口上爲頾。口下爲須。須本頤下之專偁。頾與承漿與頰？皆得偁須。是以而之訓曰須也象形。引伸假借之爲語䛐。或在發端。或在句中。或在句末。或可釋爲然。或可釋爲如。或可釋爲汝。或釋爲能者、古音能與而同。叚而爲能。亦叚耐爲能。如之切。一部。"}]},"耏":{"expl":"罪不至髡也。从而从彡。","rad":"而","fq":"奴代切","vol":"09","py":"nài","duan":[{"e":"罪不至髡也。","n":"罪當作辠。高帝紀。令郞中有罪耐以上請之。應劭曰。輕罪不至於髡。完其耏鬢。故曰耏。古耏字从彡。髮膚之意也。杜林以爲法度之字皆从寸。後改如是。言耐罪以上皆當先請也。耐音若能。按耐之罪輕於髡。髡者、𩮜髮也。不𩮜其髮。僅去須鬢。是曰耐。亦曰完。謂之完者、言完其髮也。㓝法志曰。當髡者完爲城旦舂。王粲詩。許歴爲完士。一言猶敗秦。江遂曰。漢令謂完而不髡曰耐。然則應仲遠言完其耏鬢、正謂去而鬢而完其髮耳。"}]},"豕":{"expl":"彘也。竭其尾，故謂之豕。象毛足而後有尾。讀與豨同。(桉：今丗字，誤以豕爲彘，以彘爲豕。何以明之？爲啄琢从豕，蟸从彘。皆取其聲，以是明之。)凡豕之屬皆从豕。","rad":"豕","fq":"式視切","vol":"09","py":"shǐ","duan":[{"e":"彘也。","n":"彑部。彘、豕也。是二篆爲轉注。小雅傳曰。豕、豬也。毛渾言之。許分別言名豕、名彘、名豬之故。"}]},"豬":{"expl":"豕而三毛叢居者。从豕者聲。","rad":"豕","fq":"陟魚切","vol":"09","py":"zhū","duan":[{"e":"豕而三毛叢凥者。","n":"凥舊作居。今正。三毛叢凥、謂一孔生三毛也。說見蘇頌本艸圖經犀下。今之豕皆然。"}]},"豰":{"expl":"小豚也。从豕𣪎聲。","rad":"豕","fq":"步角切","vol":"09","py":"bó","duan":[{"e":"小豚也。","n":"豚者、小豕也。左傳晉有先縠字彘子。葢縠卽字。釋獸曰。貔、白狐。其子豰。異物而同名也。"}]},"𦳚":{"expl":"艸也。从艸是聲。","rad":"艸","fq":"是支切","vol":"01","py":"chí","duan":[{"e":"艸也。","n":"芪母前已見。則此非芪母也。"}]},"豯":{"expl":"生三月豚，腹豯豯皃也。从豕奚聲。","rad":"豕","fq":"胡雞切","vol":"09","py":"xī","duan":[{"e":"生三月豚。","n":"此當句。下當有一曰二字。爲別一義。"}]},"豵":{"expl":"生六月豚。从豕從聲。一曰一歲豵，尚叢聚也。","rad":"豕","fq":"子紅切","vol":"09","py":"zōnɡ","duan":[{"e":"生六月豚。从豕。從聲。","n":"子紅切。九部。"}]},"豝":{"expl":"牝豕也。从豕巴聲。一曰一歲，能相把拏也。《詩》曰：“一發五豝。”","rad":"豕","fq":"伯加切","vol":"09","py":"bā","duan":[{"e":"牝豕也。","n":"釋獸、召南傳皆曰。豕、牝曰豝。"}]},"豣":{"expl":"三歲豕，肩相及者。从豕幵聲。《詩》曰：“並驅从兩豣兮。”","rad":"豕","fq":"古賢切","vol":"09","py":"jiān","duan":[{"e":"三歲豕。","n":"齊風還曰。並驅從兩肩兮。傳云。獸三歲曰肩。邠七月。獻豣于公。傳曰。三歲曰豣。豣肩一物。豣本字、肩假借也。大司馬先鄭注云。四歲爲肩。"}]},"豶":{"expl":"羠豕也。从豕賁聲。","rad":"豕","fq":"符分切","vol":"09","py":"fén","duan":[{"e":"羠豕也。","n":"羠、騬羊也。騬、犗馬也。犗、騬牛也。皆去勢之謂也。或謂之㓺。亦謂之犍。許書無此二字。周易大畜。六五。豶豕之牙。虞翻曰。㓺豕稱豶。今俗本㓺譌作劇。"}]},"豭":{"expl":"牡豕也。从豕叚聲。","rad":"豕","fq":"古牙切","vol":"09","py":"jiā","duan":[{"e":"牡豕也。","n":"左傳。野人歌曰。旣定爾婁豬。盍歸吾艾豭。此豭爲牡豕之證也。方言曰。豬、北燕朝鮮之間謂之豭。郭云。猶云豭斗也。"}]},"豛":{"expl":"上谷名豬豭。从豕，役省聲。","rad":"豕","fq":"營隻切","vol":"09","py":"yì","duan":[{"e":"上谷名豬豛。","n":"謂上谷𧦝豬曰豛也上谷、漢郡名。領沮陽等縣十五。沮陽在今直隷保安州。"}]},"䝐":{"expl":"豶也。从豕隋聲。","rad":"豕","fq":"以水切","vol":"09","py":"wéi","duan":[{"e":"豶也。","n":"䝐豶、釋獸文。郭云。俗呼小豶豬爲䝐子。按葢羠豕之小者也。"}]},"豤":{"expl":"齧也。从豕𥃩聲。","rad":"豕","fq":"康很切","vol":"09","py":"kěn","duan":[{"e":"豕齧也。","n":"豕字今補。人之齧曰齦。字見齒部。豕之齧曰豤。音同而字異也。𦒱工記。？豤薜暴不入市。注云。豤、頓傷也。此引伸假借字。今本作？。非。"}]},"豷":{"expl":"豕息也。从豕壹聲。《春秋傳》曰：“生敖及豷。”","rad":"豕","fq":"許利切","vol":"09","py":"yì","duan":[{"e":"豕息也。","n":"息者、喘也。豷與㞒呬䨳音義皆同。而有人豕之別。"}]},"苴":{"expl":"履中艸。从艸且聲。","rad":"艸","fq":"子余切","vol":"01","py":"jū","duan":[{"e":"履中艸。","n":"賈誼傳。冠雖敝。不以苴履。引伸爲苞苴。"}]},"豧":{"expl":"豕息也。从豕甫聲。","rad":"豕","fq":"芳無切","vol":"09","py":"fū","duan":[{"e":"豕息也。从豕。甫聲。","n":"芳無切。五部。"}]},"豢":{"expl":"以穀圈養豕也。从豕𢍏聲。","rad":"豕","fq":"胡慣切","vol":"09","py":"huàn","duan":[{"e":"㠯穀圏養豕也。","n":"圏者、養嘼之閑。圏養者、圏而養之。圏豢㬪韵。樂記注曰。以穀食犬豕曰豢。月令注曰。養牛羊曰芻。犬豕曰豢。少儀假圂爲豢。"}]},"豠":{"expl":"豕屬。从豕且聲。","rad":"豕","fq":"疾余切","vol":"09","py":"chú","duan":[{"e":"豕屬。","n":"凡言屬者、類而別也。別而類也。廣雅曰。豠、豕也。"}]},"豲":{"expl":"逸也。从豕原聲。《周書》曰：“豲有爪而不敢以撅。”讀若桓。","rad":"豕","fq":"胡官切","vol":"09","py":"huán","duan":[{"e":"豕屬也。","n":"三字依戴氏侗六書故所偁唐本。葢晁氏說之所據也。篇、韵皆云。豲、豕屬。則爲唐本信矣。二徐本皆云逸也。乃以下文逸周書割一字爲之。韵會又增之云豕之逸也。更可笑矣。廣雅說豕屬有豲豲非𩫕豬也。或以𩫕豬說之。殊誤。"}]},"豨":{"expl":"豕走豨豨。从豕希聲。古有封豨脩虵之害。","rad":"豕","fq":"虚豈切","vol":"09","py":"xī","duan":[{"e":"豕走豨豨也。","n":"豨豨、走皃。以其走皃名之曰豨。方言。豬、北燕朝鮮之間謂之豭。關東西謂之彘。或謂之豕。南楚謂之豨。許說其本義。故次於此。方言說其引伸之義也。下文言封豨、則亦引伸之義。"}]},"豖":{"expl":"豕絆足行豖豖。从豕繫二足。","rad":"豕","fq":"丑六切","vol":"09","py":"chù","duan":[{"e":"豕絆足行豖豖也。","n":"豖豖、艱行之皃。孟子曰。如追放豚。旣入其苙。又從而招之。趙曰。招、罥也。按罥之謂絆其足。經文招字與豖古音相近。招之卽豖之也。此猶州吁卽祝吁。"}]},"豦":{"expl":"鬬相丮不解也。从豕、虍。豕、虍之鬬，不解也。讀若蘮蒘草之蘮。司馬相如說：豦，封豕之屬。一曰虎兩足舉。","rad":"豕","fq":"强魚切","vol":"09","py":"qú","duan":[{"e":"鬬相丮不解也。","n":"鬬當作鬥。兩丮相對也。丮、持也。不言持言丮者、以曡韵爲訓也。"}]},"𧱏":{"expl":"豕怒毛豎。一曰殘艾也。从豕、辛。","rad":"豕","fq":"魚旣切","vol":"09","py":"yì","duan":[{"e":"豕怒毛豎也。","n":"毅、妄怒也。从此。會意兼形聲。"}]},"豩":{"expl":"二豕也。豳从此。闕。","rad":"豕","fq":"伯貧切","vol":"09","py":"huān","duan":[{"e":"二豕也。豳从此。","n":"許書豳、燹二篆皆用豩爲聲也。然則其讀若尚略可識矣。古音當在十三部。"}]},"㣇":{"expl":"脩豪獸。一曰河内名豕也。从彑，下象毛足。凡㣇之屬皆从㣇。讀若弟。","rad":"㣇","fq":"羊至切","vol":"09","py":"yì","duan":[{"e":"脩豪獸。","n":"毛詩六月、韓奕傳曰。脩、長也。周秦之文。攸訓爲長。其後乃叚脩爲攸而訓爲長矣。豪、豕鬛如筆管者。因之凡髦鬛皆曰豪。釋獸曰。𧳙脩豪。㣇者正字。𧳙者俗字。或作肆者、叚借字也。按此言獸、與下文𩫚豕非一物。顏氏注漢書曰。豪豬一名㣇。非也。"}]},"𧆓":{"expl":"艸履也。从艸麤聲。","rad":"艸","fq":"倉胡切","vol":"01","py":"cū","duan":[{"e":"艸履也。","n":"方言曰。以絲作之者謂之履。以麻作之者謂之不借。麤者謂之屨。東北朝鮮洌水之閒謂之䩕角。南楚江沔之閒緫謂之麤。急就篇。屐屩𦂌麤。儀禮喪服傳疏屨注云。疏猶麤也。按禮注、方言、急就之麤字皆？字之省。疏屨者、藨蒯之菲。則是艸爲之。"}]},"𢑢":{"expl":"豕屬。从㣇曶聲。","rad":"㣇","fq":"呼骨切","vol":"09","py":"hū","duan":[{"e":"豕屬。从㣇。𡇆聲。","n":"呼骨切。十五部。"}]},"𩫚":{"expl":"豕，鬣如筆管者。出南郡。从㣇高聲。","rad":"㣇","fq":"乎刀切","vol":"09","py":"háo","duan":[{"e":"𩫚豕、","n":"逗。"}]},"𢑭":{"expl":"蟲，似豪豬者。从㣇，胃省聲。","rad":"㣇","fq":"于貴切","vol":"09","py":"wèi","duan":[{"e":"彙蟲也。","n":"彙字各本無。今補。也字依廣韵補。釋獸曰。彙，毛刺。其字俗作蝟，作猬。周易。拔茅茹以其彙。鄭云。勤也。以爲謂之叚借也。王弼云。類也。以爲會之叚借也。"}]},"㣈":{"expl":"㣇屬。从二㣇。","rad":"㣇","fq":"息利切","vol":"09","py":"sì","duan":[{"e":"㣇屬。从二㣇。","n":"息利切。十五部。"}]},"彑":{"expl":"豕之頭。象其銳，而上見也。凡彑之屬皆从彑。讀若罽。","rad":"彑","fq":"居例切","vol":"09","py":"jì","duan":[{"e":"豕之頭。","n":"篇、韵曰。彚類。今義也。"}]},"彘":{"expl":"豕也。後蹏廢謂之彘。从彑矢聲；从二匕，彘足與鹿足同。","rad":"彑","fq":"直例切","vol":"09","py":"zhì","duan":[{"e":"豕也。","n":"與豕篆下彘也爲轉注。"}]},"𧰲":{"expl":"豕也。从彑从豕。讀若弛。","rad":"彑","fq":"式視切","vol":"09","py":"chǐ","duan":[{"e":"豕也。从彑。从豕。讀若弛。","n":"式視切。按古音在十六十七部閒。廣韵尺氏切。是也。蠡从䖵、彖聲。㥟从心、彖聲。古音皆在十六部。今韵蠡入薺、㥟入佳皆不誤。而字形从彖則誤。"}]},"𢑓":{"expl":"豕也。从彑，下象其足。讀若瑕。","rad":"彑","fq":"乎加切","vol":"09","py":"xiá","duan":[{"e":"豕也。从彑。下象其足。讀若瑕。","n":"乎加切。按小徐本此爲彖之古文。篇、韵皆無此字。"}]},"豚":{"expl":"小豕也。从彖省，象形。从又持肉，以給祠祀。凡豚之屬皆从豚。","rad":"豚","fq":"徒魂切","vol":"09","py":"tún","duan":[{"e":"小豕也。","n":"方言。豬、其子或謂之豚。或謂之豯。"}]},"蕢":{"expl":"艸器也。从艸䝿聲。","rad":"艸","fq":"求位切","vol":"01","py":"kuì","duan":[{"e":"艸器也。","n":"孟子曰。不知足而爲屨。我知其不爲蕢也。知蕢是盛物之器。"}]},"𧲝":{"expl":"豚屬。从豚衞聲。讀若罽。","rad":"豚","fq":"于歲切","vol":"09","py":"wèi","duan":[{"e":"豚屬。从𢄉。衞聲。讀若罽。","n":"于歲切。十五部。"}]},"豸":{"expl":"獸長𦟝，行豸豸然，欲有所司殺形。凡豸之屬皆从豸。(司殺讀若伺候之伺。)","rad":"豸","fq":"池爾切","vol":"09","py":"zhì","duan":[{"e":"獸長𦟝行豸豸然。欲有所司殺形。","n":"緫言其義其形。故不更言象形也。或曰此下當有象形二字。司今之伺字。許書無伺。凡獸欲有所伺殺、則行步詳宷。其脊若加長。豸豸然、長皃。文象其形也。周禮射人。以貍步張三侯。注云。貍、善搏者也。行則止而儗度焉。其發必𫉬。是以量矦道法之也。許言獸者、謂凡殺物之獸也。釋蟲曰。有足謂之蟲。無足謂之豸。按凡無足之蟲體多長。如蛇蚓之類。正長脊義之引伸也。上林賦曰。陂池貏豸。卽子虛賦之罷池陂陀。西京賦曰。增嬋娟以此豸。按貏豸謂迆邐之長。此豸謂婀娜之長。亦皆長義之引伸。古多叚豸爲解廌之廌。以二字古同音也。廌與解古音同部。是以廌訓解。方言曰。廌、解也。左傳。庶有豸乎。釋文作廌。引方言廌、解也。正義作豸。引方言豸、解也。"}]},"豹":{"expl":"似虎，圜文。从豸勺聲。","rad":"豸","fq":"北教切","vol":"09","py":"bào","duan":[{"e":"佀虎。圜文。","n":"豹文圜。易曰。君子豹變。其文蔚也。豹一名程。"}]},"貙":{"expl":"貙獌，似貍者。从豸區聲。","rad":"豸","fq":"敕俱切","vol":"09","py":"chū","duan":[{"e":"貙獌、似貍。","n":"各本下有者字。今刪正。貍篆下曰。似貙。其狀互見也。釋獸。貙似貍。又曰。貙獌、似貍。犬部獌下曰。狼屬。引爾雅貙獌似貍。然則此襲爾雅。貙似貍。獌衍文耳。貙常以立秋日祭獸。吳都賦注曰。虎屬。"}]},"貚":{"expl":"貙屬也。从豸單聲。","rad":"豸","fq":"徒干切","vol":"09","py":"tán","duan":[{"e":"貙屬也。从豸。單聲。","n":"徒干切。十四部。"}]},"貔":{"expl":"豹屬，出貉國。从豸𣬉聲。《詩》曰：“獻其貔皮。”《周書》曰：“如虎如貔。”貔，猛獸。","rad":"豸","fq":"房脂切","vol":"09","py":"pí","duan":[{"e":"豹屬。","n":"大雅韓奕傳曰。貔、猛獸也。尚書某氏傳曰。貔、執夷、虎屬也。釋獸曰。貔、白狐。舍人曰。名白狐也。按方言曰。貔、陳楚江淮之間謂之猍。北燕朝鮮之閒謂之𧳏。關西謂之狸。郭云。貔未聞語所出。玉裁謂。方言所說貍也。非貔也。爾雅所說白狐、葢亦貍類。非貔也。而皆得貔名者、俗𧦝之相混也。說文、毛傳、尚書傳則皆貔之本義也。"}]},"豺":{"expl":"狼屬，狗聲。从豸才聲。","rad":"豸","fq":"士皆切","vol":"09","py":"chái","duan":[{"e":"狼屬。狗聲。","n":"釋獸曰。豺、狗足。許云狗聲。似許長。其聲如犬。俗𧦝豺狗。"}]},"貐":{"expl":"猰貐，似貙，虎爪，食人，迅走。从豸俞聲。","rad":"豸","fq":"以主切","vol":"09","py":"yǔ","duan":[{"e":"䝟貐。","n":"䝟大徐作猰。廣韵引許作䝟。無䝟篆者、疑、許本作契。無豸㫄。後人加之。"}]},"貘":{"expl":"似熊而黃黑色，出蜀中。从豸莫聲。","rad":"豸","fq":"莫白切","vol":"09","py":"mò","duan":[{"e":"佀熊而黃黑色。出蜀中。","n":"卽諸書所謂食鐵之獸也。見爾雅、上林賦蜀都賦注、後漢書。爾雅謂之白豹。山海經謂之猛豹。今四川川東有此獸。薪采攜鐵飯甑入山。每爲所齧。其齒則奸民用爲僞佛齒。"}]},"𧴄":{"expl":"猛獸也。从豸庸聲。","rad":"豸","fq":"余封切","vol":"09","py":"yōnɡ","duan":[{"e":"猛獸也。","n":"猛當作㺎。三字爲句。㺎見上林賦。郭璞曰。㺎似牛。領有肉堆。卽犎牛也。按卽爾雅之犦牛也。字亦作㺎。亦作𤛑。漢書作庸。"}]},"𦯈":{"expl":"覆也。从艸，㑴省聲。","rad":"艸","fq":"七朕切","vol":"01","py":"qǐn","duan":[{"e":"覆也。从艸。侵省聲。","n":"七朕切。七部。"}]},"貜":{"expl":"纱玃也。从豸矍聲。","rad":"豸","fq":"王縛切","vol":"09","py":"jué","duan":[{"e":"㺉貜也。","n":"㺉廣韵引作豰。未知孰是。葢合二字爲獸名。與犬部玃字義別。"}]},"貀":{"expl":"獸，無前足。从豸出聲。《漢律》：“能捕豺貀，購百錢。”","rad":"豸","fq":"女滑切","vol":"09","py":"nà","duan":[{"e":"貀獸。","n":"貀字各本無。今補。"}]},"貈":{"expl":"似狐，善睡獸。从豸舟聲。《論語》曰：“狐貈之厚以居。”","rad":"豸","fq":"下各切","vol":"09","py":"hé","duan":[{"e":"似狐。善睡獸也。","n":"凡狐貉連文者、皆當作此貈字。今字乃皆假貉爲貈。造貊爲貉矣。"}]},"豻":{"expl":"胡地野狗。从豸干聲。","rad":"豸","fq":"五旰切","vol":"09","py":"àn","duan":[{"e":"胡地野狗。","n":"禮記玉藻、周禮巾車注皆云。豻、胡犬也。正義皆云。胡當作狐。與犬合所生。按犬有名狼、名狐者。見廣雅。但此注胡犬。證以說文、高誘淮南注、熊安生禮記正義云胡地野狗。則其字不當作狐宷矣。"}]},"貂":{"expl":"鼠屬。大而黃黑，出胡丁零國。从豸召聲。","rad":"豸","fq":"都僚切","vol":"09","py":"diāo","duan":[{"e":"鼠屬。大而黃黑。出胡丁零國。","n":"郭氏山海經注曰。今扶餘國、卽濊貃故地。在長城北。去玄兔千里。出名馬、赤玉、大珠如酸棗也。"}]},"貉":{"expl":"北方豸穜。从豸各聲。孔子曰：“貉之爲言惡也。”","rad":"豸","fq":"莫白切","vol":"09","py":"mò","duan":[{"e":"北方貉。","n":"各本奪貉字。今補。此與西方羌从羊、北方狄从犬、南方蠻从虫、東南閩越从虫、東方夷从大、參合觀之。鄭司農云。北方曰貉、曰狄。周禮大甸。獵祭表貉。注云。貉讀爲十百之百。"}]},"貆":{"expl":"貉之類。从豸亘聲。","rad":"豸","fq":"胡官切","vol":"09","py":"huán","duan":[{"e":"貈之類。从豸。𠄢聲。","n":"按此篆舊系貉篆下。云貉之類。然則亦必人而豸種者。而經傳不言有貆人。則知轉寫譌舛耳。釋獸曰。貈子貆。可援以證許書矣。今更正而移其次於此。胡官切。十四部。"}]},"貍":{"expl":"伏獸，似貙。从豸里聲。","rad":"豸","fq":"里之切","vol":"09","py":"lí","duan":[{"e":"伏獸。似貙。","n":"伏獸、謂善伏之獸。鄭注大射云。貍首、逸詩。貍之言不來也。其詩有射諸侯首不朝者之言。因以名篇。皇偘以爲舊解云。貍之取物、則伏下其頭。然後必得。言射亦必中。如貍之取物矣。上文云貙似貍。此云貍似貙。言二物相似。卽俗所謂野貓。"}]},"貒":{"expl":"獸也。从豸耑聲。讀若湍。","rad":"豸","fq":"他耑切","vol":"09","py":"tuān","duan":[{"e":"貒獸也。","n":"各本無貒字。今補。三字爲一句。釋獸曰。狐貍貒貈醜。其足蹯。其跡𠘯。貒子貗。"}]},"貛":{"expl":"野豕也。从豸雚聲。","rad":"豸","fq":"呼官切","vol":"09","py":"huān","duan":[{"e":"野豕也。从豸。雚聲。","n":"呼官切。十四部。按𠘯部引爾雅。狐貍貒貈醜。貒作貛。葢貒貛本一字。貛乃貒之或體。淺人刪去上文似豕而肥四字。乃注野豕也三字於此以分別之耳。其物非有二。集韵、類篇亦合爲一字。宜正之曰。貒或从雚聲。"}]},"祴":{"expl":"宗廟奏祴樂。从示戒聲。","rad":"示","fq":"古哀切","vol":"01","py":"ɡāi","duan":[{"e":"宗廟奏祴樂。","n":"宗廟中賔醉而出。奏祴夏。故字從示。"}]},"茵":{"expl":"車重席。从艸因聲。","rad":"艸","fq":"於眞切","vol":"01","py":"yīn","duan":[{"e":"車重席也。","n":"秦風文茵。文、虎皮也。以虎皮爲茵也。"}]},"貁":{"expl":"鼠屬。善旋。从豸穴聲。","rad":"豸","fq":"余救切","vol":"09","py":"yòu","duan":[{"e":"鼠屬。善旋。","n":"按當作禺屬、善倒縣。周禮、爾雅、山海經有蜼字。許無蜼。貁卽蜼。廣雅曰。狖、蜼也。是也。釋獸曰。蜼、卬鼻而長尾。周禮注曰。蜼、禺屬。卬鼻而長尾。郭景純曰。蜼似獼猴而大。黃黑色。尾長數尺。末有㒳岐。雨則自縣於樹。以尾塞鼻。零陵南康人呼之音餘。建平人呼之音相贈遺之遺。又音余救反。皆土俗輕重不同耳。淮南覽冥注曰。狖、猨屬。長尾而卬鼻。吳都賦劉注引異物志曰。狖、猿類。露鼻。尾長四五尺。居樹上。雨則以尾塞鼻。是以狖者、貁之俗省。蜼貁爲古今字。許不取蜼。用今字也。與鼠部之𪕏鼬分別爲三物。"}]},"貓":{"expl":"貍屬。从豸苗聲。","rad":"豸","fq":"莫交切","vol":"09","py":"māo","duan":[]},"𤉡":{"expl":"如野牛而青。象形。與禽、离頭同。凡𤉡之屬皆从𤉡。","rad":"𤉡","fq":"徐姊切","vol":"09","py":"sì","duan":[{"e":"如野牛。靑色。其皮堅厚可制鎧。","n":"靑色各本作而靑。其皮堅厚可制鎧各本無此七字。今補。論語季氏疏、爾雅釋獸疏、詩何草不黃正義、春秋左傳宣二年正義皆有此七字。皆作靑色。或作靑毛。釋獸曰。兕、似牛。許云如野牛者、其義一也。野牛卽今水牛。與黃牛別。古謂之野牛。爾雅云似牛者、似此也。郭注山海經曰。犀似水牛。豬頭庳腳。兕亦似水牛。靑色一角。重三千斤。𦒱工記。函人爲甲。犀甲七屬。兕甲六屬。犀甲壽百年。兕甲壽二百年。"}]},"易":{"expl":"蜥易，蝘蜓，守宮也。象形。《祕書》說：日月爲易，象陰陽也。一曰从勿。凡易之屬皆从易。","rad":"易","fq":"羊益切","vol":"09","py":"yì","duan":[{"e":"蜥易、蝘蜓、守宫也。","n":"虫部蜥下曰。蜥易也。蝘下曰。在壁曰蝘蜓。在艸曰蜥易。釋魚曰。榮螈、蜥蜴。蜥蜴、蝘蜓。蝘蜓、守宫也。郭云。轉相解。博異語、別四名也。方言曰。守宫、秦晉西夏謂之守宫。或謂之蠦𧓋。或謂之蜥蜴。其在澤中者謂之易蜴。南楚謂之蛇醫。或謂之蠑螈。東齊海岱謂之螔？。北燕謂之祝蜒。桂林之中守宫大者而能鳴。謂之蛤解。按許舉其三者、略也。易本蜥易。語言假借而難易之義出焉。鄭氏贊易曰。易之爲名也。一言而函三義。簡易一也。變易二也。不易三也。按易彖二字皆古以語言假借立名。如象卽像似之像也。故許先言本義。而後引祕書說。云祕書者、明其未必然也。"}]},"象":{"expl":"長鼻牙，南越大獸，三秊一乳，象耳牙四足之形。凡象之屬皆从象。","rad":"象","fq":"徐兩切","vol":"09","py":"xiànɡ","duan":[{"e":"南越大獸。","n":"獸之冣大者。而出南越。"}]},"豫":{"expl":"象之大者。賈侍中說：不害於物。从象予聲。","rad":"象","fq":"羊茹切","vol":"09","py":"yù","duan":[{"e":"象之大者。","n":"此豫之本義、故其字从象也。引伸之、凡大皆偁豫。故淮南子、史記循吏傳、魏都賦皆云。市不豫價。周禮司市注云。防誑豫。皆謂賣物者大其價以愚人也。大必寬裕。故先事而備謂之豫。寬裕之意也。寬大則樂。故釋詁曰。豫、樂也。易鄭注曰。豫喜豫說樂之皃也。亦借爲舒字。如洪範。豫、恒燠若。卽舒、恒燠若也。亦借爲與字。如儀禮古文與作豫是也。"}]},"馬":{"expl":"怒也。武也。象馬頭髦尾四足之形。凡馬之屬皆从馬。","rad":"馬","fq":"莫下切","vol":"10","py":"mǎ","duan":[{"e":"怒也。武也。","n":"以曡韵爲訓。亦門聞也、戸護也之例也。釋名曰。大司馬。馬、武也。大揔武事也。"}]},"𨽥":{"expl":"牡馬也。从馬陟聲。讀若郅。","rad":"馬","fq":"之日切","vol":"10","py":"zhì","duan":[{"e":"牡馬也。","n":"釋嘼曰。牡曰騭。牝曰騇。郭云。今江東呼䭸馬爲騭。按騭古叚陟爲之。小正。四月執陟攻駒。陟騭古今字。謂之騭者、陟升也。牡能乘牝。月令所謂累牛騰馬。皆乘匹之名。月令三月遊牝。小正四月執騭。事實相因也。若釋詁曰。騭、陞也。郭注引方言。魯衛之閒曰騭。洪範。惟天陰騭下民。馬融曰。騭、升也。升猶舉也。舉猶生也。漢五行志引經。服虔曰。騭音陟。應劭曰。騭、升也。此等騭字皆登陟字之假借。爾雅以釋詩書者也。故陟騭並列。而統曰陞也。方言。躡郅跂𢓜躋䠯登也。魯衛曰郅。郭注爾雅引之。郅作騭。葢郭當日所見不誤。後人或用其音、改其本字耳。方言與爾雅同義。"}]},"𩡧":{"expl":"馬一歲也。从馬；一，絆其足。讀若弦。一曰若環。","rad":"馬","fq":"戶關切","vol":"10","py":"huán","duan":[{"e":"馬一歲也。从馬一。絆其足。","n":"絆其足三字、葢衍文。衹當云从馬一而已。一說。馵下云从馬二其足。此當作一其足。絆字賸。韵書、字書皆作䭴。疑非是。不當从十也。"}]},"駒":{"expl":"馬二歲曰駒，三歲曰駣。从馬句聲。","rad":"馬","fq":"舉朱切","vol":"10","py":"jū","duan":[{"e":"馬二歲曰駒。三歲曰駣。","n":"周禮廋人。敎駣攻駒。鄭司農云。馬三歲曰駣。二歲曰駒。月令曰。犧牲駒犢。舉書其數。犢爲牛子。則駒、馬子也。小雅。老馬反爲駒。言已老矣而孩童慢之也。按詩駒四見。而漢廣、株林、皇皇者華於義皆當作驕。乃與毛傳說文合。不當作駒。依韵讀之則又當作駒。乃入韵。不當作驕。深思其故。葢角弓用字之本義。南有喬木、株林、皇皇者華則皆讀者求其韵不得。改驕爲駒也。駒未可駕車。故三詩斷非用駒本義。駣字旣見周禮。何以連類言之、不錄此篆也。曰疑周禮故書本作兆。或借羊部䍮爲之。許解中駣字葢非許君原文。後人依周禮改之耳。不當如玉篇擅增也。"}]},"芻":{"expl":"刈艸也。象包束艸之形。","rad":"艸","fq":"叉愚切","vol":"01","py":"chú","duan":[{"e":"刈艸也。","n":"謂可飤牛馬者。"}]},"𩡩":{"expl":"馬八歲也。从馬从八。","rad":"馬","fq":"博拔切","vol":"10","py":"bā","duan":[{"e":"馬八歲也。","n":"初學記引何承天纂文同。"}]},"𩦂":{"expl":"馬一目白曰𩦂，二目白曰魚。从馬閒聲。","rad":"馬","fq":"戶閒切","vol":"10","py":"xián","duan":[{"e":"馬一目白曰𩦂。","n":"一字賸。目部曰。瞯、戴目也。爾雅釋文引倉頡篇𥊺、目病也。廣韵曰。瞯、人目多白也。是則人目白曰瞯。馬目白曰𩦂。𩦂卽从瞯省。爾雅釋嘼𩦂作瞯。"}]},"騏":{"expl":"馬青驪，文如博棊也。从馬其聲。","rad":"馬","fq":"渠之切","vol":"10","py":"qí","duan":[{"e":"馬靑驪文如綦也。","n":"如綦各本作如博棊。不通。今依李善七發注、玄應書卷二卷四卷八正。凡馬言色者、如下文深黑色、淺黑色。全體之色也。其言某處黑、某處白、發白色、發赤色。一耑之色也。言襍毛者、謂其毛異色相錯。非比異色成片段者也。其曰文者、獨此而已。謂異色成枝條相交。如文之錯畫然。下文靑驪馬爲駽、謂其全體靑黑色。此云靑驪文如綦、謂白馬而有靑黑紋路相交如綦也。綦糸部作𦁰、白蒼文也。綦者、靑而近黑。秦風傳曰。騏、綦文也。魯頌傳曰。蒼騏曰騏。蒼騏卽蒼綦。謂蒼文如綦也。曹風其弁伊騏傳曰。騏、騏文也。正義作綦文。顧命騏弁。鄭注曰。靑黑曰騏。本作綦弁。古多叚騏爲綦。"}]},"驪":{"expl":"馬深黑色。从馬麗聲。","rad":"馬","fq":"呂支切","vol":"10","py":"lí","duan":[{"e":"馬深黑色。","n":"魯頌、傳曰。純黑曰驪。按引伸爲凡黑之偁。亦叚黎棃爲之。"}]},"駽":{"expl":"青驪馬。从馬肙聲。《詩》曰：“駜彼乘駽。”","rad":"馬","fq":"火玄切","vol":"10","py":"xuān","duan":[{"e":"靑驪馬。","n":"謂深黑色而戴靑色也。魯頌有駜曰。駜彼乘駽。釋嘼、毛傳皆曰。靑驪曰駽。"}]},"騩":{"expl":"馬淺黑色。从馬鬼聲。","rad":"馬","fq":"俱位切","vol":"10","py":"ɡuī","duan":[{"e":"馬淺黑色。","n":"漢舊儀。有天地大變。丞相上病。使者奉策書。駕騩駱馬。卽時布衣步出府。免爲庶人。丞相有他過。使者奉策書。駕騅騩馬。卽時步出府。乘棧車牝馬歸。按乘騩者、取無色之意。"}]},"驑":{"expl":"赤馬黑毛尾也。从馬畱聲。","rad":"馬","fq":"力求切","vol":"10","py":"liú","duan":[{"e":"赤馬黑髦尾也。","n":"髦各本作毛。今依廣韵正。髦者、髦髮也。髮之長者偁髦。因之馬鬣曰髦。魯頌傳曰。赤身黑鬣曰駵。"}]},"騢":{"expl":"馬赤白雜毛。从馬叚聲。謂色似鰕魚也。","rad":"馬","fq":"乎加切","vol":"10","py":"xiá","duan":[{"e":"馬赤白襍毛。","n":"襍毛者、謂異色之毛襍亂相厠也。或作襍色。非是。魯頌有騢。釋嘼、毛傳皆曰。彤白襍毛曰騢。"}]},"騅":{"expl":"馬蒼黑雜毛。从馬隹聲。","rad":"馬","fq":"職追切","vol":"10","py":"zhuī","duan":[{"e":"馬蒼黑襍毛。","n":"黑當作白。釋嘼、毛傳皆云。蒼白襍毛曰騅。蒼者、靑之近黑者也。白毛與蒼毛相閒而生、是爲靑馬。雖深於靑白襍毛之騘、未黑也。若黑毛與蒼毛相閒而生、則幾深黑矣。釋言曰。菼騅也。王風傳曰。菼、薍也。萑之初生者。艸部曰。𦵹者、萑之初生。一曰騅。此以同色名之。觀萑葦之初生之色。則知蒼白之不可易矣。○六書故云。徐本作白。正謂唐本不作白也。"}]},"駱":{"expl":"馬白色黑鬣尾也。从馬各聲。","rad":"馬","fq":"盧各切","vol":"10","py":"luò","duan":[{"e":"馬白色黑鬣尾也。","n":"釋嘼曰。白馬黑鬣駱。詩音義曰。樊、孫爾雅並作白馬黑髦鬣尾也。然則許正同樊。孫本矣。魯頌毛傳亦曰。白馬黑髦曰駱。按今毛詩有驒有駱。有駵有雒。毛曰。黑身白鬣曰雒。正與白身黑鬣曰駱互異。正義曰。定本、集注及徐音皆作駱。釋文亦云。雒本或作駱。然則本二物相似而同名。淺人惑之。乃妄改字。"}]},"茭":{"expl":"乾芻。从艸交聲。一曰牛蘄艸。","rad":"艸","fq":"古肴切","vol":"01","py":"jiāo","duan":[{"e":"乾芻。","n":"粊誓曰。峙乃芻茭。鄭注同。"}]},"駰":{"expl":"馬陰白雜毛。黑。从馬因聲。《詩》曰：“有駰有騢。”","rad":"馬","fq":"於眞切","vol":"10","py":"yīn","duan":[{"e":"馬陰白襍毛黑。","n":"黑字宋本、舊本皆同。汲古毛氏改黑作也。以合爾雅、毛傳。然而非是。釋嘼、魯頌傳皆云。陰白襍毛曰駰。郭云。陰、淺黑也。今之泥騘。或云目下白。或云白陰。皆非也。陰淺黑、本叔然說。然則許葢襍毛之下、釋云陰淺黑也。如虦下虎竊毛謂之虦苗、竊淺也正是一例。旣說者惑於白陰之說。謂馬私處白而襍、黑毛。因致漏奪不可讀。苟求其故。由不解陰之爲淺黑耳。廣韵曰。駰馬陰淺黑色。有脫。"}]},"驄":{"expl":"馬青白雜毛也。从馬悤聲。","rad":"馬","fq":"倉紅切","vol":"10","py":"cōnɡ","duan":[{"e":"馬靑白襍毛也。","n":"白毛與靑毛相閒則爲淺靑。俗所謂葱白色。詩曰。有瑲葱衡。釋器曰。靑謂之葱。"}]},"驈":{"expl":"驪馬白胯也。从馬矞聲。《詩》曰：“有驈有騜。”","rad":"馬","fq":"食聿切","vol":"10","py":"yù","duan":[{"e":"驪馬白跨也。","n":"跨者、兩股之閒也。釋嘼、毛傳皆曰。驪馬白跨曰驈。"}]},"駹":{"expl":"馬面顙皆白也。从馬尨聲。","rad":"馬","fq":"莫江切","vol":"10","py":"mánɡ","duan":[{"e":"馬面顙皆白也。","n":"面者、顏前也。釋嘼曰。面顙皆白惟駹。按言惟者、以別於上文的顙、白顚、白達、素縣也。面顙白、其他非白也。故从尨。周禮駹車。借爲尨襍字也。"}]},"騧":{"expl":"黃馬，黑喙。从馬咼聲。","rad":"馬","fq":"古華切","vol":"10","py":"ɡuā","duan":[{"e":"黃馬黑喙。","n":"釋嘼曰。白馬黑脣駩。黑喙騧。如爾雅之文、則是白馬黑喙也。秦風傳曰。黃馬黑喙曰騧。許本之。豈今爾雅奪黃馬二字與。郭云。今之淺黃色者爲騧馬。"}]},"驃":{"expl":"黃馬發白色。一曰白髦尾也。从馬𤐫聲。","rad":"馬","fq":"毗召切","vol":"10","py":"piào","duan":[{"e":"黃馬發白色。","n":"發白色者、起白㸃斑駁也。釋嘼曰。黃白曰騜。毛詩祗作皇。然則皇卽驃與。牛部犥下曰。牛黃白色。與驃音正同也。"}]},"駓":{"expl":"黃馬白毛也。从馬丕聲。","rad":"馬","fq":"𢾭悲切","vol":"10","py":"pī","duan":[{"e":"黃白襍毛也。","n":"各本作黃馬白毛。今正。六書通引唐本作黃馬白襍毛。此唐本衍馬字。淺人不刪馬字而刪襍字耳。釋嘼、毛傳皆曰黃白襍毛曰駓。字林作駓。"}]},"𩧀":{"expl":"馬赤黑色。从馬𢧜聲。《詩》曰：“四𩧀孔阜。”","rad":"馬","fq":"他結切","vol":"10","py":"tiě","duan":[{"e":"馬赤黑色。","n":"此與靑驪馬句法同。謂黑色而帶赤色也。驖不見爾雅。秦風駟驖孔阜傳曰。驖、驪也。驪者、深黑色。許說小異。漢人或叚鐵爲之。前書地理志叚𢧤爲之。"}]},"䮗":{"expl":"馬頭有發赤色者。从馬岸聲。","rad":"馬","fq":"五旰切","vol":"10","py":"àn","duan":[{"e":"馬頭有白發色。","n":"大徐作馬頭有發赤色者。非是。篇、韵皆云。\n馬白頟至脣。集韵曰。馬流星貫脣。則爲馬頭發白色矣。廣韵曰。𩢔䮗、馬行。此今義也。按東京賦作半漢。"}]},"馰":{"expl":"馬白頟也。从馬，的省聲。一曰駿也。《易》曰：“爲的顙。”","rad":"馬","fq":"都歴切","vol":"10","py":"dí","duan":[{"e":"馬白頟也。","n":"秦風有馬白顚傳曰。白顚、昀顙也。釋嘼曰。昀顙白顚。郭云。戴星馬也。說卦傳曰。爲昀顙。虞翻曰。昀、白。顙、頟也。按昀顙之馬謂之馰。易釋文云。昀、說文作馰。"}]},"荹":{"expl":"亂艸。从艸步聲。","rad":"艸","fq":"薄故切","vol":"01","py":"bù","duan":[{"e":"亂艸。","n":"玉篇曰。牛馬艸。亂？也。"}]},"駁":{"expl":"馬色不純。从馬爻聲。","rad":"馬","fq":"北角切","vol":"10","py":"bó","duan":[{"e":"馬色不純。","n":"純同𨣶。崔覲曰。不襍曰純。釋嘼曰。駵白駁。邠風毛傳同。謂駵馬發白色也。許說不同者、許意馬異色成片段者皆得曰駁。引伸之爲凡色不純之偁。"}]},"馵":{"expl":"馬後左足白也。从馬，二其足。讀若注。","rad":"馬","fq":"之戍切","vol":"10","py":"zhù","duan":[{"e":"馬後左足白也。","n":"左當作𠂇。釋嘼、毛傳皆曰。後左足白曰馵。說卦傳曰。震爲馵足。"}]},"驔":{"expl":"驪馬黃𦟝。从馬覃聲。讀若簟。","rad":"馬","fq":"徒玷切","vol":"10","py":"diàn","duan":[{"e":"驪馬黃𦟝。","n":"魯頌。有驔有魚。釋嘼曰。驪馬黃脊曰騽。爾雅音義云。騽說文作驔。音簟。是則爾雅之騽卽驔之異禮。許於此篆用爾雅、不用毛傳也。毛傳曰。豪骭曰驔。此卽驔之異說。詩音義引字林云。驔又音覃。豪骭曰驔。是則字林豪骭一義不作騽也。今說文乃別有騽篆。訓云豪骭。前與毛詩不合。後與字林不合。此葢必非許原文。許原文或驔下有一曰豪骭之文。或驔篆後有重文作騽之篆。皆不可定。後人乃以兩義分配兩形耳。"}]},"驠":{"expl":"馬白州也。从馬燕聲。","rad":"馬","fq":"於甸切","vol":"10","py":"yàn","duan":[{"e":"馬白州也。","n":"山海經曰。乾山有嘼。其州在尾上。今本譌作川。廣雅曰。州、豚、臀也。郭注爾雅、山海經皆云。州、竅也。按州豚同字。俗作𡰪。國語之龍𧱦、史漢貨殖傳之馬噭皆此也。蜀志周羣傳。諸毛繞涿居。署曰潞涿君。語相戲謔。涿亦州豚同音字也。釋嘼曰。白州驠。"}]},"騽":{"expl":"馬豪骭也。从馬習聲。","rad":"馬","fq":"似入切","vol":"10","py":"xí","duan":[{"e":"馬豪骭也。","n":"骭者、骹也。骹者、脛也。高誘注淮南曰。骭、膝以下脛以上也。豪骭謂骭上有脩豪也。魯頌傳曰。豪骭曰驔。正義本作豪骭白。白衍。"}]},"䮧":{"expl":"馬毛長也。从馬倝聲。","rad":"馬","fq":"矦旰切","vol":"10","py":"hàn","duan":[{"e":"馬毛長者也。","n":"者字依文選長楊賦注補。此謂馬毛長者名䮧也。多借翰字爲之。翰行而䮧廢矣。尙書大傳。之西海之濱。取白狐靑翰。注曰。長毛也。文選長楊賦翰林主人注引說文。毛長者曰翰。曲禮。雞曰翰音。注曰。翰猶長也。常武詩。如飛如翰。箋云。鳥中豪俊。葢其字皆當作䮧。引伸假借之字也。"}]},"騛":{"expl":"馬逸足也。从馬从飛。《司馬法》曰：“飛衞斯輿。”","rad":"馬","fq":"甫微切","vol":"10","py":"fēi","duan":[{"e":"馬逸足者也。","n":"者字今補。逸當作兔。廣韵曰。騛兔、馬而兔走。玉篇曰。騛兔、古之駿馬也。呂氏春秋高注曰。飛兔、要褭皆馬名也。日行萬里。馳若兔之飛。因以爲名也。"}]},"驁":{"expl":"駿馬。以壬申日死，乘馬忌之。从馬敖聲。","rad":"馬","fq":"五到切","vol":"10","py":"ào","duan":[{"e":"駿馬。","n":"句絕。謂駿馬之名也。大射禮。公入驁。注曰。驁夏、亦樂章也。以鍾𡔷奏之。按驁夏、葢取翶翔之意。凡奇士偁豪俊者可作驁俊。如尙書獒可爲酋豪字也。"}]},"驥":{"expl":"千里馬也，孫陽所相者。从馬冀聲。天水有驥縣。","rad":"馬","fq":"几利切","vol":"10","py":"jì","duan":[{"e":"千里馬也。孫陽所相者。","n":"孫陽字伯樂。秦穆公時人。其所與有九方臯。卽九方歅。戰國策汗明說春申君、是伯樂相驥事。按小徐說伯樂卽王良、卽郵無恤。大繆。"}]},"駿":{"expl":"馬之良材者。从馬夋聲。","rad":"馬","fq":"子峻切","vol":"10","py":"jùn","duan":[{"e":"馬之良材者。","n":"引伸爲凡大之偁。釋詁、毛傳皆曰。駿、大也。毛傳見文王、崧高、噫嘻。"}]},"茹":{"expl":"飤馬也。从艸如聲。","rad":"艸","fq":"人庶切","vol":"01","py":"rú","duan":[{"e":"飤馬也。从艸。如聲。","n":"人庶切。五部。"}]},"驍":{"expl":"良馬也。从馬堯聲。","rad":"馬","fq":"古堯切","vol":"10","py":"xiāo","duan":[{"e":"良馬也。","n":"周禮良馬與駑馬爲對文。良馬兼上文種馬、戎馬、齋馬、道馬、田馬言也。周易曰。良馬逐逐。左傳云。以其良爲二。亦精駿之偁。按上文云駿、馬之良材者。此云良馬、卽蒙上文而言也。魯頌傳曰。駉駉、良馬腹榦肥張也。引伸爲勇捷之偁。"}]},"䮔":{"expl":"馬小皃。从馬垂聲。讀若箠。","rad":"馬","fq":"之壘切","vol":"10","py":"zuī","duan":[{"e":"馬小皃。从馬。𡍮聲。讀若箠。","n":"之壘切。按當依廣韵之累切。十六十七部。辵部{辶+{馬+垂[左右]}}（𨙦）以爲聲。"}]},"驕":{"expl":"馬高六尺爲驕。从馬喬聲。《詩》曰：“我馬唯驕。”一曰野馬。","rad":"馬","fq":"舉喬切","vol":"10","py":"jiāo","duan":[{"e":"馬高六尺爲驕。","n":"漢廣言秣其馬。言秣其駒。傳曰。六尺以上爲馬。五就以上爲駒。按此駒字釋文不爲音。陳風。乘我乘駒。傳曰。大夫乘駒。箋云。馬六尺以下曰駒。此駒字釋文作驕。引沈重云或作駒。後人改之。皇皇者華篇內同。小雅。我馬維駒。釋文云。本亦作驕。據陳風、小雅則知周南本亦作驕也。葢六尺以下五尺以上謂之驕。與駒義迥別。三詩義皆當作驕而俗人多改作駒者、以駒與蔞株濡諏爲韵。驕則非韵。抑知驕其本字音在二部。於四部合韵。不必易字就韵而乖義乎。陸氏於三詩無定說。彼此互異。由不知古義也。毛云。大夫乘驕。以此推之。當是天子乘龍。諸侯乘騋。𨜮乘馬。"}]},"騋":{"expl":"馬七尺爲騋，八尺爲龍。从馬來聲。《詩》曰：“騋牝驪牡。”","rad":"馬","fq":"洛哀切","vol":"10","py":"lái","duan":[{"e":"馬七尺爲騋。八尺爲龍。","n":"周禮廀人曰。馬八尺以上爲龍。七尺以上爲騋。六尺以上爲馬。庸風。騋牝三千。毛傳。馬七尺以上曰騋。鄭司農以月令駕蒼龍說周禮。龍俗作駥。"}]},"驩":{"expl":"馬名。从馬雚聲。","rad":"馬","fq":"呼官切","vol":"10","py":"huān","duan":[{"e":"馬名。","n":"古叚爲歡字。"}]},"驗":{"expl":"馬名。从馬僉聲。","rad":"馬","fq":"魚窆切","vol":"10","py":"yàn","duan":[{"e":"馬名。","n":"今用爲譣字。證也、徵也、效也。不知其何自始。驗行而譣廢矣。"}]},"𩢑":{"expl":"馬名。从馬此聲。","rad":"馬","fq":"雌氏切","vol":"10","py":"cǐ","duan":[{"e":"馬名。从馬。此聲。","n":"雌氏切。十六部。"}]},"𩢮":{"expl":"馬名。从馬休聲。","rad":"馬","fq":"許尤切","vol":"10","py":"xiū","duan":[{"e":"馬名。从馬。休聲。","n":"許尤切。三部。"}]},"馼":{"expl":"馬赤鬣縞身，目若黃金，名曰𩢌。吉皇之乘，周文王時，犬戎獻之。从馬从文，文亦聲。《春秋傳》曰：“𩢌馬百駟。”畫馬也。西伯獻紂，以全其身。","rad":"馬","fq":"無分切","vol":"10","py":"wén","duan":[{"e":"𩢌馬、","n":"𩢌字今補。"}]},"馶":{"expl":"馬彊也。从馬支聲。","rad":"馬","fq":"章移切","vol":"10","py":"zhī","duan":[{"e":"馬彊也。从馬。支聲。","n":"章移切。十六部。"}]},"莝":{"expl":"斬芻。从艸坐聲。","rad":"艸","fq":"麤臥切","vol":"01","py":"cuò","duan":[{"e":"斬芻。","n":"謂以鈇斬𣃔之芻。"}]},"駜":{"expl":"馬飽也。从馬必聲。《詩》云：“有駜有駜。”","rad":"馬","fq":"毗必切","vol":"10","py":"bì","duan":[{"e":"馬鮑也。","n":"魯頌有駜曰。有駜有駜。傳曰。駜、馬肥彊皃。馬肥彊則能升高進遠。臣彊力則能安國。按許義小別。鄭箋亦云。此言僖公用臣、必先致其祿食。祿食足而臣莫不盡其忠也。"}]},"駫":{"expl":"馬盛肥也。从馬光聲。《詩》曰：“四牡駫駫。”","rad":"馬","fq":"古熒切","vol":"10","py":"jiōnɡ","duan":[{"e":"馬肥盛也。","n":"各本作盛肥。今依廣韵訂。"}]},"騯":{"expl":"馬盛也。从馬㫄聲。《詩》曰：“四牡𩤐𩤐。”","rad":"馬","fq":"薄庚切","vol":"10","py":"pénɡ","duan":[{"e":"馬盛也。","n":"也當作皃。"}]},"䭹":{"expl":"䭹䭹，馬怒皃。从馬卬聲。","rad":"馬","fq":"吾浪切","vol":"10","py":"ànɡ","duan":[{"e":"䭹䭹、馬怒皃。从馬。卬聲。","n":"吾郎切。十部。廣韵平聲。"}]},"驤":{"expl":"馬之低仰也。从馬襄聲。","rad":"馬","fq":"息良切","vol":"10","py":"xiānɡ","duan":[{"e":"馬之低仰也。","n":"低當作氐。馬之或俛或仰謂之驤。吳都賦。四騏龍驤。古多叚襄爲驤。"}]},"驀":{"expl":"上馬也。从馬莫聲。","rad":"馬","fq":"莫白切","vol":"10","py":"mò","duan":[{"e":"上馬也。","n":"吳都賦曰。驀六駮。上馬必捷。故引伸爲猝乍之偁。"}]},"騎":{"expl":"跨馬也。从馬奇聲。","rad":"馬","fq":"渠羈切","vol":"10","py":"qí","duan":[{"e":"跨馬也。","n":"兩髀跨馬謂之騎。因之人在馬上謂之騎。今分平去二音。曲禮曰。前有車騎。正義曰。古人不騎馬。故經典無言騎者。今言騎、當是周末時禮。按左傳。左師展將以昭公乘而歸。此必謂騎也。然則古人非無騎矣。趙旃以其良馬二。濟其兄與叔父非單騎乎。"}]},"駕":{"expl":"馬在軛中。从馬加聲。","rad":"馬","fq":"古訝切","vol":"10","py":"jià","duan":[{"e":"馬在軛中也。","n":"毛傳曰。軛、烏噣也。烏噣卽釋名之烏啄。轅有衡。衡、橫也。橫馬頸上。其扼馬頸者曰烏啄。下向叉馬頸。似烏開口向下啄物時也。駕之言以車加於馬也。"}]},"騑":{"expl":"驂，㫄馬。从馬非聲。","rad":"馬","fq":"甫微切","vol":"10","py":"fēi","duan":[{"e":"驂也。旁馬也。","n":"各本無上也字。不可通。今補。攷禮記正義、文選注引說文。或作旁馬也三字。或作驂旁馬也四字。正由有二也字而奪一耳。騑馬、經典皆謂之驂。故曰驂也。下文云駕三馬曰驂。許意古爲駕三馬之名。後乃駕四駕六、其旁馬皆得驂名矣。故又申之曰旁馬。旁者、冡上在軛中言之。不當衡下者謂之驂。亦謂之騑。駕三駕四所同也。若小雅傳曰。騑騑、行不止之皃。別爲一義。"}]},"駢":{"expl":"駕二馬也。从馬并聲。","rad":"馬","fq":"部田切","vol":"10","py":"pián","duan":[{"e":"駕二馬也。","n":"平帝本紀曰。詔光祿大夫劉歆等襍定婚禮。四輔、公𨜮、大夫、士、郎、吏家屬皆以禮娶。立軺倂馬。服虔曰。立軺、小車也。倂馬、驪駕也。按驪讀同伉儷、非馬深黑色。木部㮐下曰。讀若驪駕是也。倂馬謂之儷駕。亦謂之騈。倂騈皆从幷、謂並二馬也。左傳。渾良夫乘中佃兩牡。葢是駕二。毛詩說士駕二。禮王度記亦言士駕二。王肅云。夏后氏駕兩謂之麗。騈之引伸、凡二物幷曰騈。"}]},"萎":{"expl":"食牛也。从艸委聲。","rad":"艸","fq":"於僞切","vol":"01","py":"wèi","duan":[{"e":"食牛也。","n":"下文云。以穀萎馬。則牛馬通偁萎。"}]},"驂":{"expl":"駕三馬也。从馬參聲。","rad":"馬","fq":"倉含切","vol":"10","py":"cān","duan":[{"e":"駕三馬也。","n":"驂三曡韵爲訓。詩干旄。良馬四之。良馬五之。良馬六之。傳曰。四之、御四馬也。五之、驂馬五轡也。六之、四馬六轡也。然則毛公有駕三之說矣。王肅云。古者一轅之車駕三馬。則五轡。其大夫皆一轅車。夏后氏駕兩謂之麗。殷益以一騑謂之驂。周人又益以一騑謂之駟。本從一驂而來。亦謂之驂。經言驂、則三馬之名。五經異義。天子駕數。易孟京、春秋公羊說天子駕六。詩毛說天子至大夫同四。士駕二。詩云四騵彭彭。武王所乘。龍旂承祀。六轡耳耳。魯僖所乘。四牡騑騑。周道倭遲。大夫所乘。謹按禮王度記曰。天子駕六。諸侯與𨜮同駕四。大夫駕三。士駕二。庶人駕一。說與易、春秋同。駁曰。玄之聞也。周禮校人。掌王馬之政。凡頒良馬而養乘之。乘馬一師四"}]},"駟":{"expl":"一乘也。从馬四聲。","rad":"馬","fq":"息利切","vol":"10","py":"sì","duan":[{"e":"一乘也。","n":"周禮校人。鄭司農注云。四匹爲乘。按乘者覆也。車軛駕乎馬上曰乘。馬必四。故四馬爲一乘。不必已駕者也。引俾之、凡物四曰乘。如乘矢、乘皮、乘韋、乘壺皆是。駟者、馬一乘之名。鄭淸人箋云。駟、四馬也。按詩言四牡、言四騏、言四驖、言四騵、言四駱、言四黃皆作四。下一字皆馬名也。言駟介、言俴駟皆作駟。謂有所以加乎駟者也。今詩作駟驖、駟騵。而干旄疏引異義、公羊隱元年疏、說文驖字下皆不誤。"}]},"駙":{"expl":"副馬也。从馬付聲。一曰近也。一曰疾也。","rad":"馬","fq":"符遇切","vol":"10","py":"fù","duan":[{"e":"副馬也。","n":"副者、貳也。漢百官公𨜮表。奉車都尉掌御乘輿車。駙馬都尉掌駙馬。皆武帝初置。晉尙公主者、並加之師古曰。駙、副馬也。非正駕車皆爲副馬。"}]},"𩤠":{"expl":"馬和也。从馬皆聲。","rad":"馬","fq":"戶皆切","vol":"10","py":"xié","duan":[{"e":"馬和也。","n":"和當作龢。孫𨜮曰。六馬不和則造父不能以致遠。"}]},"騀":{"expl":"馬搖頭也。从馬我聲。","rad":"馬","fq":"五可切","vol":"10","py":"ě","duan":[{"e":"駊騀也。从馬。我聲。","n":"五可切。十七部。此二篆倂解。各本譌舛。今依全書通例及玉篇所載訂正。"}]},"駊":{"expl":"駊騀也。从馬皮聲。","rad":"馬","fq":"普火切","vol":"10","py":"pǒ","duan":[{"e":"駊騀、","n":"逗。二字曡韵。"}]},"𩥅":{"expl":"馬行皃。从馬舀聲。","rad":"馬","fq":"土刀切","vol":"10","py":"tāo","duan":[{"e":"馬行皃。","n":"此當曰𩥅𩥅、馬行皃。淺人刪之也。牛徐行曰𤘸𤘸。馬徐行曰𩥅𩥅。今人俗語如是矣。"}]},"篤":{"expl":"馬行頓遟。从馬竹聲。","rad":"馬","fq":"冬毒切","vol":"10","py":"dǔ","duan":[{"e":"馬行頓遟也。","n":"頓如頓首。以頭觸地也。馬行箸實而遟緩也。古假借篤爲竺字。以皆竹聲也。二部曰。竺、厚也。篤行而竺廢矣。釋詁曰。篤、固也。又曰。篤、厚也。毛詩椒𦕼、大明、公劉傳皆曰。篤、厚也。凡經傳。篤字、固厚二訓足包之。釋詁篤竺並列。皆訓厚。釋名曰。篤、築也。築、堅實稱也。厚、後也。有終後也。葢篤字之代竺久矣。"}]},"騤":{"expl":"馬行威儀也。从馬癸聲。《詩》曰：“四牡騤騤。”","rad":"馬","fq":"渠追切","vol":"10","py":"kuí","duan":[{"e":"馬行威儀也。","n":"馬行上當有騤騤二字。詩三言四牡騤騤。采薇傳曰。彊也。桑柔傳曰。不息也。烝民傳曰。猶彭彭也。各隨文解之。許檃栝之云馬行威儀皃。於曡韵取義也。"}]},"䮸":{"expl":"馬行徐而疾也。从馬，學省聲。","rad":"馬","fq":"於角切","vol":"10","py":"wò","duan":[{"e":"𩦡𩦡、","n":"二字今補。"}]},"蓛":{"expl":"以榖萎馬，置莝中。从艸敇聲。","rad":"艸","fq":"楚革切","vol":"01","py":"cè","duan":[]},"駸":{"expl":"馬行疾也。从馬，㑴省聲。《詩》曰：“載驟𩤿𩤿。”","rad":"馬","fq":"子林切","vol":"10","py":"qīn","duan":[{"e":"馬行疾皃。","n":"馬行上當本有駸駸字。皃各本作也。今依篇、韵正。小雅四牡傳曰。駸駸、驟皃。驟者、馬捷步也。"}]},"馺":{"expl":"馬行相及也。从馬从及。讀若《爾雅》“小山馺，大山峘”。","rad":"馬","fq":"蘇荅切","vol":"10","py":"sà","duan":[{"e":"馬行相及也。","n":"以曡韵爲訓。西京賦薛解曰。馺娑、駘盪、枍詣、承光皆臺名。按馺娑、駘盪皆以馬行皃皃台之高也。"}]},"馮":{"expl":"馬行疾也。从馬冫聲。","rad":"馬","fq":"房戎切","vol":"10","py":"pínɡ","duan":[{"e":"馬行疾也。从馬仌聲。","n":"皮冰切。六部。按馬行疾馮馮然、此馮之本義也。展轉他用而馮之本義廢矣。馮者、馬蹏箸地堅實之皃。因之引伸其義爲盛也、大也、滿也、懣也。如左傳之馮怒、離騷之馮心、以及天問之馮翼惟象、淮南書之馮馮翼翼、地理志之左馮翊皆謂充盛。皆畐字之合音假借。畐者、滿也。或叚爲凭字。凡經傳云馮依、其字皆當作凭。或叚爲淜字。如易、詩、論語之馮河皆當作淜也。俗作憑。非是。"}]},"𩣘":{"expl":"馬步疾也。从馬耴聲。","rad":"馬","fq":"尼輒切","vol":"10","py":"niè","duan":[{"e":"馬步疾也。","n":"按今人專輒字作輒。似當作𩣘爲近之。"}]},"騃":{"expl":"馬行㐹㐹也。从馬矣聲。","rad":"馬","fq":"五駭切","vol":"10","py":"sì","duan":[{"e":"馬行㐹㐹也。","n":"人部曰。㐹、勇壯也。吉日。儦儦俟俟。人部作伾伾俟俟。韓詩作𩣚𩣚騃騃。李賢注馬融傳引韓詩。駓駓騃騃。或羣或友。李善注西京賦引韓詩章句曰。趨曰𩣚。行曰騃。按毛傳亦曰。趨則伾伾。行則俟俟。毛用假借字。韓乃正字也。騃騃與俟俟音義同。俟、大也。皆鉏里切。方言曰。癡、騃也。乃讀五駭切。俗語借用之字耳。"}]},"驟":{"expl":"馬疾步也。从馬聚聲。","rad":"馬","fq":"鉏又切","vol":"10","py":"zhòu","duan":[{"e":"馬疾步也。","n":"步下曰。行也。走下曰。趨也。行下曰。人之步趨也。然則行兼步與趨言之。此馬行、馬步、馬走之別也。小雅曰。載驟駸駸。按今字驟爲暴疾之詞。古則爲屢然之詞。凡左傳、國語言驟者皆與屢同義。如宣子驟諫、公子商人驟施於國是也。左傳言驟。詩書言屢。論語言屢、亦言亟。其意一也。亟之本義敏疾也。讀去吏切、爲數數然。數數然卽是敏疾。驟之用同此矣。數之本義計也。讀所角切、爲數數然。乃又引伸爲凡迫促之意。好學者必心知其意。於此可見也。馳驟字曲禮叚騶爲之。"}]},"𩢛":{"expl":"馬疾走也。从馬匃聲。","rad":"馬","fq":"古達切","vol":"10","py":"ɡě","duan":[{"e":"馬疾走也。","n":"廣韵作走疾。"}]},"颿":{"expl":"馬疾步也。从馬風聲。","rad":"馬","fq":"符嚴切","vol":"10","py":"fān","duan":[{"e":"馬疾步也。","n":"馬之行疾於風。故曰追奔電、逐遺風。"}]},"驅":{"expl":"馬馳也。从馬區聲。","rad":"馬","fq":"豈俱切","vol":"10","py":"qū","duan":[{"e":"驅馬也。","n":"各本作馬馳也。今正。此三字爲一句。<驅>爲篆文。此三字言其義。許之例如此。驅馬常言耳。盡人所知。故不必易字以注之也。驅馬、自人策馬言之。革部曰。鞭、驅也。是其義也。"}]},"馳":{"expl":"大驅也。从馬也聲。","rad":"馬","fq":"直离切","vol":"10","py":"chí","duan":[{"e":"大驅也。","n":"詩每以馳驅並言。許穆夫人首言載馳載驅。下言驅馬悠悠。馳亦驅也。較大而疾耳。"}]},"䒼":{"expl":"蠶薄也。从艸曲聲。","rad":"艸","fq":"丘玉切","vol":"01","py":"qū","duan":[{"e":"蠶薄也。","n":"幽風毛傳曰。豫畜萑葦。可以爲曲也。月令。季春、具曲植筥筐。注曰。曲、薄也。方言。薄、宋魏陳楚江淮之閒謂之䒼。或謂之麴。自關而西謂之薄。南楚謂之蓬薄。案曲與䒼同。曲部云。或說曲、蠶薄也。是許兼用此二形。"}]},"騖":{"expl":"亂馳也。从馬敄聲。","rad":"馬","fq":"亡遇切","vol":"10","py":"wù","duan":[{"e":"亂馳也。从馬。敄聲。","n":"亡遇切。古音在三部。"}]},"𩢾":{"expl":"次弟馳也。从馬𠛱聲。","rad":"馬","fq":"力制切","vol":"10","py":"liè","duan":[{"e":"次弟馳也。","n":"次弟成行列之馳也。故从𠛱。"}]},"騁":{"expl":"直馳也。从馬甹聲。","rad":"馬","fq":"丑郢切","vol":"10","py":"chěnɡ","duan":[{"e":"直馳也。","n":"節南山傳曰。騁、極也。"}]},"駾":{"expl":"馬行疾來皃。从馬兌聲。《詩》曰：“昆夷駾矣。”","rad":"馬","fq":"他外切","vol":"10","py":"tuì","duan":[{"e":"馬行疾來皃也。","n":"大雅緜曰。混夷駾矣。傳曰。駾、突也。箋云。混夷惶、怖驚走奔突入柞棫之中。"}]},"䭿":{"expl":"馬有疾足。从馬失聲。","rad":"馬","fq":"大結切","vol":"10","py":"yì","duan":[{"e":"馬有疾足也。","n":"奔軼絕塵字當作䭿。今人用俊逸字當作䭿。於此知騛篆下馬逸足之斷爲譌字矣。"}]},"駻":{"expl":"馬突也。从馬旱聲。","rad":"馬","fq":"矦旰切","vol":"10","py":"hàn","duan":[{"e":"馬突也。","n":"駻之言悍也。淮南書作馯。高曰。馯馬、突馬也。"}]},"駧":{"expl":"馳馬洞去也。从馬同聲。","rad":"馬","fq":"徒弄切","vol":"10","py":"dònɡ","duan":[{"e":"馳馬洞去也。","n":"洞者、疾流也。以曡韵爲訓。"}]},"驚":{"expl":"馬駭也。从馬敬聲。","rad":"馬","fq":"舉卿切","vol":"10","py":"jīnɡ","duan":[{"e":"馬駭也。","n":"驚與警義別。小雅。徒御不警。傳曰。不警、警也。俗多譌驚。"}]},"駭":{"expl":"驚也。从馬亥聲。","rad":"馬","fq":"矦楷切","vol":"10","py":"hài","duan":[{"e":"驚也。从馬。亥聲。","n":"侯楷切。古音在一部。經典亦作駴。戒聲亥聲同在一部也。"}]},"𩢯":{"expl":"馬奔也。从馬巟聲。","rad":"馬","fq":"呼光切","vol":"10","py":"huānɡ","duan":[{"e":"馬𢍃也。","n":"奔者、走也。"}]},"蔟":{"expl":"行蠶蓐。从艸族聲。","rad":"艸","fq":"千木切","vol":"01","py":"cù","duan":[{"e":"行蠶蓐。从艸。族聲。","n":"千木切。三部。引伸爲六律大蔟字。七豆切。"}]},"騫":{"expl":"馬腹縶也。从馬，寒省聲。","rad":"馬","fq":"去虔切","vol":"10","py":"qiān","duan":[{"e":"馬腹墊也。","n":"墊各本作縶。自篇、韵己然。小徐作𤍠、則更誤。今正。土部曰。墊者、下也。引春秋傳。墊隘馬腹。墊、正俗所云肚腹低陷也。仲尼弟子列傳閔損字子騫。是其義矣。考工記。小體騫腹謂之羽屬。詩無羊、天保傳皆曰。騫、虧也。干部曰。虧者、气損也。按詩騫裳字本用此。見詩、左傳釋文。謂摳衣不使盈滿也。俗借褰絝字爲之。習者不知其非矣。"}]},"駐":{"expl":"馬立也。从馬主聲。","rad":"馬","fq":"中句切","vol":"10","py":"zhù","duan":[{"e":"馬立也。","n":"人立曰侸、俗作住。馬立曰駐。"}]},"馴":{"expl":"馬順也。从馬川聲。","rad":"馬","fq":"詳遵切","vol":"10","py":"xún","duan":[{"e":"馬順也。","n":"古馴訓順三字互相假借。皆川聲也。古文尙書。五品不愻。史記殷本紀及兩漢書及周禮地官注愻皆作訓。而五帝本紀作五品不馴。馴之本義爲馬順。引伸爲凡順之偁。"}]},"駗":{"expl":"馬載重難也。从馬㐱聲。","rad":"馬","fq":"張人切","vol":"10","py":"zhēn","duan":[{"e":"駗驙、","n":"二字雙聲。各本皆刪。今依玉篇補。"}]},"驙":{"expl":"駗驙也。从馬亶聲。《易》曰：“乘馬驙如。”","rad":"馬","fq":"張連切","vol":"10","py":"zhān","duan":[{"e":"駗驙也。从馬。亶聲。","n":"張連切。十四部。"}]},"騺":{"expl":"馬重皃。从馬執聲。","rad":"馬","fq":"陟利切","vol":"10","py":"zhì","duan":[{"e":"馬重皃也。","n":"晉世家。惠公馬騺不行。卽左傳晉戎馬還濘而止。今本史記作鷙。譌字也。而秦本紀作馬驇不誤。𡴂部曰。𤕩驇不行也。今本亦譌騺。莊子馬蹄篇。闉枙驇曼。崔云。拒枙頓遲也。今刻釋文亦譌从鳥。而集韵、類篇不誤。車之前重曰𨎐。馬重曰驇。其音義一也。廣雅。𩧅駤、止也。駤卽驇。"}]},"驧":{"expl":"馬曲𦟝也。从馬鞠聲。","rad":"馬","fq":"巨六切","vol":"10","py":"jú","duan":[{"e":"馬曲𦟝也。","n":"勹部曰。𠤄者、曲脊也。音義皆同。"}]},"騬":{"expl":"犗馬也。从馬乘聲。","rad":"馬","fq":"食陵切","vol":"10","py":"chénɡ","duan":[{"e":"犗馬也。","n":"牛部曰。犗者、騬牛也。其事一、故其訓互通。"}]},"𩡺":{"expl":"系馬尾也。从馬介聲。","rad":"馬","fq":"古拜切","vol":"10","py":"jiè","duan":[{"e":"系馬尾也。","n":"此當依玉篇作結馬尾。廣韵作馬尾結也。結卽今之髻字。大玄曰。車軨馬𩡺可以周天下。范注。軨、轄繫。𩡺、尾結也。釋文𩡺音介。馬尾髻也。按遠行必髻其馬尾。𩡺與䯰音義同。詩曰駟介。左傳曰不介馬而馳。疑介卽古文𩡺。"}]},"騷":{"expl":"擾也。一曰摩馬。从馬蚤聲。","rad":"馬","fq":"穌遭切","vol":"10","py":"sāo","duan":[{"e":"摩馬也。","n":"各本摩馬上有「擾也一曰」四字，淺人所增也。今刪正。人曰搔。馬曰騷。其意一也。摩馬如今人之刷馬。引伸之義爲騷動。大雅常武傳曰騷、動也是也。檀弓注曰。騷騷爾、大疾。若屈原列傳曰離騷者猶離憂也。此於騷古音與憂同部得之。騷本不訓憂。而擾動則生憂也。故曰猶。"}]},"禡":{"expl":"師行所止，恐有慢其神，下而祀之曰禡。从示馬聲。《周禮》曰：“禡於所征之地。”","rad":"示","fq":"莫駕切","vol":"01","py":"mà","duan":[{"e":"師行所止。恐有慢其神。下而祀之曰禡。","n":"釋天曰。是禷是禡。師祭也。王制注云。爲兵禱。周禮肆師、甸祝皆作貉。杜、鄭讀貉爲十百之百。云爲師祭造軍法者。禱氣勢之十百增倍。許說不同者。許時古今說具在。五經異義今已亾。又賈氏周禮解詁亦亾。不詳其所本也。"}]},"苣":{"expl":"束葦燒。从艸巨聲。","rad":"艸","fq":"其呂切","vol":"01","py":"jù","duan":[{"e":"束葦燒也。","n":"後漢書皇甫嵩傳。束苣乘城。俗作炬。以此爲苣蕂、萵苣字。"}]},"馽":{"expl":"絆馬也。从馬，囗其足。《春秋傳》曰：“韓厥執馽前。”讀若輒。","rad":"馬","fq":"陟立切","vol":"10","py":"zhí","duan":[{"e":"絆馬足也。","n":"足字依韵會補。糸部曰。絆者、馬繫也。是爲轉注。小雅白駒傳曰。縶、絆也。周頌有客箋同。莊子連之以羈馽。卽此字。"}]},"駘":{"expl":"馬銜脫也。从馬台聲。","rad":"馬","fq":"徒哀切","vol":"10","py":"tái","duan":[{"e":"馬銜脫也。","n":"銜者、馬勒口中者也。脫當作挩、解也。馬銜不在馬口中、則無以控制其馬。崔實政論曰馬駘其銜是也。銜脫則行遲鈍。廣雅曰駑駘也是也。又引伸爲寛大之意。漢有臺名駘盪及春色駘盪是也。"}]},"駔":{"expl":"牡馬也。从馬且聲。一曰馬蹲駔也。","rad":"馬","fq":"子朗切","vol":"10","py":"zǎnɡ","duan":[{"e":"壯馬也。","n":"壯各本作牡。今正。李善文選注引皆作壯。戴仲達引唐本說文作奘馬也。皆可證。此猶牙下壯齒譌牡齒耳。士部曰。壯者、大也。介{亣}部。奘者、駔大也。釋言曰。奘、駔也。郭云。今江東呼爲大駔而猶麤也。按駔本大馬之偁。引伸爲凡大之偁。故駔篆下云奘馬、而奘篆下但云駔大。許書義例之精密如此。"}]},"騶":{"expl":"廏御也。从馬芻聲。","rad":"馬","fq":"側鳩切","vol":"10","py":"zōu","duan":[{"e":"廏御也。","n":"按騶之假借作趣。周禮、詩周書之趣馬。月令、左傳謂之騶。一用假借、一用本字也。周禮。乘馬一師四圉。三乘爲皁。皁一趣馬。三皁爲𣪠。𣪠一馭夫。六𣪠爲廏。廏一僕夫。趣馬掌贊正良馬。而齊其飲食。掌駕馬之頒。鄭曰。趣馬、趣養馬者也。按趣者、疾也。掌疾養馬故曰騶。其字从芻馬、正謂養馬也。左傳。程鄭爲乘馬御。六騶屬焉。使訓羣騶知禮。杜注云。六騶、六閑之騶。月令。季秋。命僕及七騶咸駕。鄭云。七騶謂趣馬主爲諸官駕說者也。周禮趣馬統於馭夫。馭夫統於廏之僕夫。故約言之曰廏馭。漢書。材官騶發。蘇林讀爲驟。如淳讀爲菆。"}]},"驛":{"expl":"置騎也。从馬睪聲。","rad":"馬","fq":"羊益切","vol":"10","py":"yì","duan":[{"e":"置騎也。","n":"言騎以別於車也。馹爲傳車。驛爲置騎。二字之別也。周禮傳遽注曰。傳遽若今傳遽、以車馬給使者也。葢傳乘謂車。騎驛謂馬。玉藻注云。傳遽、以車馬給使者也。車謂傳。馬謂遽。渾言則傳遽無二。析言則傳遽分車馬。亦可證單騎從古而有。非經典所無。許傳下云遽也。遽下云傳也。此渾言也。驛下云置騎也。馹下云傳也。此析言也。置騎猶孟子言置郵。俗用駱驛。"}]},"馹":{"expl":"驛傳也。从馬日聲。","rad":"馬","fq":"人質切","vol":"10","py":"rì","duan":[{"e":"傳也。","n":"各本傳上有驛字。淺人所增。今刪正。辵部曰。遽者、傳也。人部曰。傳者、遽也。釋言曰。馹、傳遽也。許用釋言文。左傳文十六年襄廿一年昭五年、國語晉語韋、杜注皆曰。馹、傳也。爾雅舍人注曰。馹、尊者之傳也。呂覽注曰。馹、傳車也。按馹爲尊者之傳用車、則遽爲卑者之傳用騎可知。舍人說與許合。俗字用馹爲驛。故左傳文十六年傳、注馹字皆譌驛。成五年以傳召伯宗。注曰。傳、驛也。驛亦馹之譌。"}]},"騰":{"expl":"傳也。从馬朕聲。一曰騰，犗馬也。","rad":"馬","fq":"徒登切","vol":"10","py":"ténɡ","duan":[{"e":"傳也。","n":"傳與上文傳同。皆張戀切。引伸爲馳也。爲躍也。"}]},"䮤":{"expl":"苑名。一曰馬白頟。从馬隺聲。","rad":"馬","fq":"下各切","vol":"10","py":"hé","duan":[{"e":"苑名也。","n":"苑見下文。䮤苑、葢漢苑三十六所之一也。"}]},"駉":{"expl":"牧馬苑也。从馬冋聲。《詩》曰：“在駉之野。”","rad":"馬","fq":"古熒切","vol":"10","py":"jiōnɡ","duan":[{"e":"牧馬苑也。","n":"苑所以養禽獸也。景帝紀。匈奴入上郡。取苑馬。武帝紀。罷苑馬。百官公𨜮表曰。大僕。邊郡六牧師菀令。各三丞屬焉。如淳曰。漢儀注。大僕、牧師諸苑三十六所。分布北邊西邊。以郎爲苑監官。養馬三十萬匹。地理志。北地郡靈州有河奇苑、號非苑。歸德有堵苑、白馬苑。郁郅有牧師苑。師古曰。苑謂馬牧也。駉之義葢同閑。牧馬之處謂之閑。亦謂之駉。"}]},"駪":{"expl":"馬眾多皃。从馬先聲。","rad":"馬","fq":"所臻切","vol":"10","py":"shēn","duan":[{"e":"馬衆多皃。","n":"皇皇者華云。駪駪征夫。傳曰。駪駪、衆多之皃。按毛不曰馬者、以詩言人也。其引伸之義也。許言馬者、字之本義也。以其字从馬。焱部引詩莘莘征夫。"}]},"蕘":{"expl":"薪也。从艸堯聲。","rad":"艸","fq":"如昭切","vol":"01","py":"ráo","duan":[{"e":"艸薪也。","n":"艸字依詩釋文補。大雅。詢于芻蕘。毛曰。芻蕘、薪采者。按說文謂物。詩義謂人。"}]},"駮":{"expl":"獸，如馬，倨牙，食虎豹。从馬交聲。","rad":"馬","fq":"北角切","vol":"10","py":"bó","duan":[{"e":"駮獸、","n":"駮字今補。"}]},"駃":{"expl":"駃騠，馬父驘子也。从馬夬聲。","rad":"馬","fq":"古穴切","vol":"10","py":"jué","duan":[{"e":"駃騠、","n":"逗。"}]},"騠":{"expl":"駃騠也。从馬是聲。","rad":"馬","fq":"杜兮切","vol":"10","py":"tí","duan":[{"e":"駃騠也。从馬。是聲。","n":"杜兮切。十六部。"}]},"驘":{"expl":"驢父馬母。从馬𦝠聲。","rad":"馬","fq":"洛戈切","vol":"10","py":"luó","duan":[{"e":"驢父馬母者也。","n":"者字今補。崔豹曰。驢爲牡。馬爲牝。卽生騾。馬爲牡。驢爲牝。生駏驉。抱朴子曰。世不信騾乃驢馬所生。云各自有種。況乎仙者難知之事哉。"}]},"驢":{"expl":"似馬，長耳。从馬盧聲。","rad":"馬","fq":"力居切","vol":"10","py":"lǘ","duan":[{"e":"驢獸、","n":"二字今補。"}]},"𩥃":{"expl":"驢子也。从馬冡聲。","rad":"馬","fq":"莫紅切","vol":"10","py":"ménɡ","duan":[{"e":"驢子也。","n":"何承天纂文同。"}]},"驒":{"expl":"驒騱，野馬也。从馬單聲。一曰青驪白鱗，文如鼉魚。","rad":"馬","fq":"代何切","vol":"10","py":"tuó","duan":[{"e":"驒騱、","n":"逗。"}]},"騱":{"expl":"驒騱馬也。从馬奚聲。","rad":"馬","fq":"胡雞切","vol":"10","py":"xī","duan":[{"e":"驒騱也。","n":"依韵會訂。"}]},"騊":{"expl":"騊駼，北野之良馬。从馬匋聲。","rad":"馬","fq":"徒刀切","vol":"10","py":"táo","duan":[{"e":"騊駼、","n":"逗。"}]},"駼":{"expl":"騊駼也。从馬余聲。","rad":"馬","fq":"同都切","vol":"10","py":"tú","duan":[{"e":"騊駼也。从馬。余聲。","n":"同都切。五部。"}]},"薪":{"expl":"蕘也。从艸新聲。","rad":"艸","fq":"息鄰切","vol":"01","py":"xīn","duan":[{"e":"蕘也。从艸。新聲。","n":"息鄰切。十二部。"}]},"驫":{"expl":"眾馬也。从三馬。","rad":"馬","fq":"甫虬切","vol":"10","py":"biāo","duan":[{"e":"衆馬也。","n":"廣雅曰。驫驫、走皃也。吳都賦。驫䮅飍矞。善曰。衆馬走皃也。"}]},"𩢲":{"expl":"疾也。从馬吏聲。","rad":"馬","fq":"疏吏切","vol":"10","py":"shì","duan":[]},"駥":{"expl":"馬高八尺。从馬戎聲。","rad":"馬","fq":"如融切","vol":"10","py":"rónɡ","duan":[]},"騣":{"expl":"馬鬣也。从馬㚇聲。","rad":"馬","fq":"子红切","vol":"10","py":"zōnɡ","duan":[]},"馱":{"expl":"負物也。从馬大聲。此俗語也。","rad":"馬","fq":"唐佐切","vol":"10","py":"duò","duan":[]},"𩥍":{"expl":"馬赤色也。从馬，觲省聲。","rad":"馬","fq":"息營切","vol":"10","py":"xīnɡ","duan":[]},"𢊁":{"expl":"解𢊁，獸也，似山牛，一角。古者決訟，令觸不直。象形，从豸省。凡𢊁之屬皆从𢊁。","rad":"𢊁","fq":"宅買切","vol":"10","py":"zhì","duan":[{"e":"解𢊁獸也。","n":"四字一句。"}]},"𡦳":{"expl":"解𢊁屬。从𢊁孝聲。闕。","rad":"𢊁","fq":"古孝切","vol":"10","py":"xiào","duan":[{"e":"解𢊁屬也。","n":"葢亦神獸。"}]},"薦":{"expl":"獸之所食艸。从𢊁从艸。古者神人以𢊁遺黃帝。帝曰：“何食？何處？”曰：“食薦；夏處水澤，冬處松柏。”","rad":"𢊁","fq":"作甸切","vol":"10","py":"jiàn","duan":[{"e":"獸之所食艸。","n":"艸部曰。荐、艸席也。與此義別。而古相假借。左氏傳。戎狄荐居。服虔云。荐、艸也。言狄人逐水艸而居徙無常處。是則子愼謂荐卽薦之假借字也。莊子。麋鹿食薦。釋文引三蒼注曰。六蓄所食曰薦。凡注家云薦進也者、皆荐之假借字。荐者、藉也。故引伸之義爲進也、陳也。"}]},"灋":{"expl":"刑也。平之如水，从水；𢊁，所以觸不直者；去之，从去。","rad":"𢊁","fq":"方乏切","vol":"10","py":"fǎ","duan":[{"e":"㓝也。","n":"㓝者、罰辠也。易曰。利用㓝人。以正法也。引伸爲凡模範之偁。木部曰。模者、法也。竹部曰。範者、法也。土部曰。𡌒者、鑄器之法也。"}]},"蒸":{"expl":"折麻中榦也。从艸烝聲。","rad":"艸","fq":"煑仍切","vol":"01","py":"zhēnɡ","duan":[{"e":"析麻中榦也。","n":"析各本作折。誤。謂木音匹刃切其皮爲麻。其中莖謂之蒸。亦謂之菆。今俗所謂麻骨棓也。潘岳西征賦李注云。菆井卽渭城賣麻蒸市也。毛詩傳曰。粗曰薪。細曰蒸。周禮甸師注云。大曰薪。小曰蒸。是凡言薪蒸者、皆不必專謂麻骨。古凡燭用蒸。弟子職云。蒸閒容蒸。毛詩傳云。蒸盡摍屋而繼之是也。"}]},"鹿":{"expl":"獸也。象頭角四足之形。鳥鹿足相似，从匕。凡鹿之屬皆从鹿。","rad":"鹿","fq":"盧谷切","vol":"10","py":"lù","duan":[{"e":"鹿獸也。","n":"鹿字今補。三字句。韵會作山獸。"}]},"麚":{"expl":"牡鹿。从鹿叚聲。以夏至解角。","rad":"鹿","fq":"古牙切","vol":"10","py":"jiā","duan":[{"e":"牡鹿也。","n":"釋嘼曰。鹿、牡麚。"}]},"麟":{"expl":"大牝鹿也。从鹿粦聲。","rad":"鹿","fq":"力珍切","vol":"10","py":"lín","duan":[{"e":"大牡鹿也。","n":"牡各本及集韵、類篇皆譌牝。今正。玉篇曰。麟、大麚也。是也。子虛賦射麋腳麟、謂此。按許此篆爲大麚。麐篆爲麒麐。經典用仁獸字多作麟。葢同音假借。"}]},"𪋐":{"expl":"鹿麛也。从鹿耎聲。讀若偄弱之偄。","rad":"鹿","fq":"奴亂切","vol":"10","py":"nuàn","duan":[{"e":"麛也。","n":"各本麛上有鹿字。今依李善刪。吳都賦。翳薈無𪋯鷚。李善𪋯音須。引說文麛也。按廣韵𪋯入十一虞。𪋐入二十九換。以許讀若偄訂之。是許本从耎。而从需者。乃轉寫譌俗也。古音需聲在五部。耎聲在十四部。"}]},"𪋝":{"expl":"鹿迹也。从鹿速聲。","rad":"鹿","fq":"桑谷切","vol":"10","py":"sù","duan":[]},"麛":{"expl":"鹿子也。从鹿弭聲。","rad":"鹿","fq":"莫兮切","vol":"10","py":"mí","duan":[{"e":"鹿子也。","n":"釋嘼曰。鹿子麛。字亦作麑。論語麑裘、卽麛裘。國語注曰。鹿子曰麑。麋子曰䴠。按䴠、王制只作夭。注云。少長曰夭。"}]},"麉":{"expl":"鹿之絕有力者。从鹿幵聲。","rad":"鹿","fq":"古賢切","vol":"10","py":"jiān","duan":[{"e":"鹿之絕有力者。","n":"釋獸文。"}]},"麒":{"expl":"仁獸也。麋身牛尾，一角。从鹿其聲。","rad":"鹿","fq":"渠之切","vol":"10","py":"qí","duan":[{"e":"麒麟、仁獸也。","n":"各本無麒麟二字。今依初學記補。公羊傳曰。麟者、仁獸也。何注。狀如麕。一角而戴肉。設武備而不爲害。所以爲仁也。麟者木精。毛詩傳曰。麟信而應禮。左傳服虔注。麟、中央土獸。土爲信。信禮之子。修其母致其子。視明禮修而麟至。思睿信立而白虎擾。言從乂成而神龜在沼聽聦知正而名川出龍。貌恭性仁則鳳皇來儀。此左氏、毛氏說與公羊說不同也。五經異義。許愼謹案。禮運云。麟鳳龜龍。謂之四靈。龍、東方也。虎、西方也。鳳、南方也。龜、北方也。麟、中央也。是異義謂麟爲信獸。從左、毛說矣。而此云仁獸何也。異義早成。說文解字晚定。此云仁獸。用公羊說。以其角端戴肉。不履生蟲。不折生艸也。鄭駁異義曰。五事。言作從。從作乂。言於五事屬"}]},"麐":{"expl":"牝麒也。从鹿吝聲。","rad":"鹿","fq":"力珍切","vol":"10","py":"lín","duan":[{"e":"牝麒也。","n":"張揖注上林賦曰。雄曰麒。雌曰麟。其狀麇身牛尾狼題。郭璞曰。麒似麟而無角。"}]},"麋":{"expl":"鹿屬。从鹿米聲。麋冬至解其角。","rad":"鹿","fq":"武悲切","vol":"10","py":"mí","duan":[{"e":"鹿屬。从鹿。米聲。","n":"武悲切。十五部。"}]},"蕉":{"expl":"生枲也。从艸焦聲。","rad":"艸","fq":"卽消切","vol":"01","py":"jiāo","duan":[{"e":"生枲也。","n":"枲麻也。生枲謂未漚治者。今俗以此爲芭蕉字。楚金引吳都賦。蕉葛竹越。按本艸圖經云。閩人灰理芭蕉皮令錫滑。緝以爲布。如古之錫衰焉。左賦之蕉、正謂芭蕉。非生枲也。"}]},"麎":{"expl":"牝麋也。从鹿辰聲。","rad":"鹿","fq":"植鄰切","vol":"10","py":"chén","duan":[{"e":"牝麋也。","n":"釋獸曰。麋、牡麔。牝麎。吉日其祁孔有箋云。祁當作麎。麎、麎牝也。大司馬注。鄭司農曰。五歲爲愼。後鄭云。愼讀爲麎。麋牝曰麎。按麎在漢時必讀與祁音同。故後鄭得定詩之祁爲麎。字林麎讀上尸反。徐音同。沈市尸反。皆本古說也。爾雅音義引字林上尸反。宋本不誤。俗改爲上刃反。葢古書之難讀如此。"}]},"𪊨":{"expl":"大麋也。狗足。从鹿旨聲。","rad":"鹿","fq":"居履切","vol":"10","py":"jǐ","duan":[{"e":"大麇也。","n":"麇各本誤麋。今正。釋獸曰。𪊨、大麕。旄毛狗足。郭云。旄毛者、㺜長也。山海經注曰。麂似獐而大。㺜毛狗腳。"}]},"麇":{"expl":"麞也。从鹿，囷省聲。","rad":"鹿","fq":"居筠切","vol":"10","py":"jūn","duan":[{"e":"麞也。","n":"釋獸曰。麕、牡麌。牝麜。其子麆。許書皆無其字。葢鹿旁皆後人所箸也。"}]},"麞":{"expl":"麋屬。从鹿章聲。","rad":"鹿","fq":"諸良切","vol":"10","py":"zhānɡ","duan":[{"e":"麋屬也。","n":"伏侯古今注曰。麞有牙而不能噬。考工記。繢人山以章。鄭云。章讀爲獐。獐、山物也。齊人謂麇爲獐。陸機詩疏云。麏、麞也。靑州人謂之麏。按麞異於麋者、無角。"}]},"麔":{"expl":"麋牝者。从鹿咎聲。","rad":"鹿","fq":"其久切","vol":"10","py":"jiù","duan":[{"e":"麋牡者。","n":"見釋獸。"}]},"麠":{"expl":"大鹿也。牛尾一角。从鹿畺聲。","rad":"鹿","fq":"舉卿切","vol":"10","py":"jīnɡ","duan":[{"e":"大麃也。牛尾、一角。","n":"麃各本作鹿。誤。今正。釋獸云。麠、大麃。牛尾、一角。許所本也。史武帝紀、漢郊祀志皆曰。郊雍。獲一角獸。若麃然。武帝所獲正是麠。葢麃似麞無角。大麃有一角則謂之麠。當時有司因一角附會爲麟也。"}]},"麃":{"expl":"麠屬。从鹿，㶾省聲。","rad":"鹿","fq":"薄交切","vol":"10","py":"páo","duan":[{"e":"麞屬。","n":"鉉本作麠屬。鍇本作麋屬。今依韵會本。麃者、麞屬也。麞者、麋屬也。韋昭曰。楚人謂麋爲麃。葢麃似麋而無角。陸機詩疏曰。四足之美有麃。㒳足之美有鷮。"}]},"麈":{"expl":"麋屬。从鹿主聲。","rad":"鹿","fq":"之庾切","vol":"10","py":"zhǔ","duan":[{"e":"麋屬。","n":"說文自麋至麈皆說麋屬。乾隆三十一年。純皇帝目驗御園麈角於冬至皆解。而麋角不解。敕改時憲書麋角解之麋爲麈。臣因知今所謂麈、正古所謂麋也。吳都賦注云。旄麈有尾。故翦之。"}]},"麑":{"expl":"狻麑，獸也。从鹿兒聲。","rad":"鹿","fq":"五雞切","vol":"10","py":"ní","duan":[{"e":"狻麑獸也。","n":"釋獸曰。狻麑如虦貓。食虎豹。"}]},"麙":{"expl":"山羊而大者，細角。从鹿咸聲。","rad":"鹿","fq":"胡毚切","vol":"10","py":"xián","duan":[{"e":"山羊而大者細角。","n":"此七字文理不順。疑有誤。當作山羊而大角者。"}]},"𦳊":{"expl":"糞也。从艸，胃省。","rad":"艸","fq":"式視切","vol":"01","py":"shǐ","duan":[{"e":"糞也。从艸。胃省。","n":"㑹意也。式視切。十五部。左氏傳、史記假借矢字爲之。官溥說？字之上佀米而非米者、矢字。是漢人多用矢也。"}]},"麢":{"expl":"大羊而細角。从鹿霝聲。","rad":"鹿","fq":"郎丁切","vol":"10","py":"línɡ","duan":[{"e":"大羊而細角。","n":"釋獸曰。麢大羊。山海經作麢。本艸作羚羊。"}]},"𪊧":{"expl":"鹿屬。从鹿圭聲。","rad":"鹿","fq":"古攜切","vol":"10","py":"ɡuī","duan":[{"e":"鹿屬。从鹿。圭聲。","n":"古攜切。十六部。"}]},"𪋧":{"expl":"如小麋，臍有香。从鹿䠶聲。","rad":"鹿","fq":"神夜切","vol":"10","py":"shè","duan":[{"e":"如小麋。臍有香。","n":"釋獸曰。麝父麕足。郭云。腳似麇。"}]},"𪋮":{"expl":"似鹿而大也。从鹿與聲。","rad":"鹿","fq":"羊茹切","vol":"10","py":"yù","duan":[{"e":"佀鹿而大。","n":"楊雄蜀都賦。麢𪋮鹿麝。"}]},"麗":{"expl":"旅行也。鹿之性，見食急則必旅行。从鹿丽聲。《禮》：麗皮納聘。蓋鹿皮也。","rad":"鹿","fq":"郎計切","vol":"10","py":"lì","duan":[{"e":"旅行也。","n":"此麗之本義。其字本作丽。旅行之象也。後乃加鹿耳。周禮。麗馬一圉。八麗一師。注曰。麗、耦也。禮之儷皮、左傳之伉儷、說文之驪駕皆其義也。㒳相附則爲麗。易曰。離、麗也。日月麗乎天。百穀艸木麗乎土。是其義也。麗則有耦可觀。㸚部曰。麗？猶靡麗也。是其義也。㒳而介其間亦曰麗。離卦之一陰麗二陽是也。"}]},"麀":{"expl":"牝鹿也。从鹿，从牝省。","rad":"鹿","fq":"於虯切","vol":"10","py":"yōu","duan":[{"e":"牝鹿也。","n":"釋嘼曰。鹿、牝麀。小雅吉日傳曰。鹿牝曰麀。按引伸爲凡牝之偁。大雅靈臺傳曰。麀、牝也。左傳。思其麀牡。曲禮。父子聚麀。皆謂卽牝字也。詩一言騋牝。三言麀鹿。皆取生息蕃多之意。"}]},"麤":{"expl":"行超遠也。从三鹿。凡麤之屬皆从麤。","rad":"麤","fq":"倉胡切","vol":"10","py":"cū","duan":[{"e":"行超遠也。","n":"鹿善驚躍。故从三鹿。引伸之爲鹵莽之偁。篇、韵云。不精也、大也、疏也。皆今義也。俗作麁。今人槩用粗。粗行而麤廢矣。粗音徂古切。"}]},"𪋻":{"expl":"鹿行揚土也。从麤从土。","rad":"麤","fq":"直珍切","vol":"10","py":"chén","duan":[{"e":"鹿行揚土也。","n":"羣行則揚土甚。引伸爲凡揚土之偁。土部曰。埃、塵也。塺、塵也。坋、塵也。釋詁。塵、久也。卽桑柔傳之塡、久也。東山傳。烝、窴也。箋云。古者聲窴塡塵同也。又甫田傳曰。尊者食新。農夫食陳。按窴塡塵陳四字同音。皆訓久。當是塡爲正字。塡者、？也。？則安定。窴鎭與塡同。塵陳皆叚借字也。"}]},"㲋":{"expl":"獸也。似兔，青色而大。象形。頭與兔同，足與鹿同。凡㲋之屬皆从㲋。","rad":"㲋","fq":"丑略切","vol":"10","py":"chuò","duan":[{"e":"㲋獸也。","n":"㲋字今補。三字句。"}]},"毚":{"expl":"狡兔也，兔之駿者。从㲋、兔。","rad":"㲋","fq":"士咸切","vol":"10","py":"chán","duan":[{"e":"狡兔也。","n":"小雅巧言傳曰。毚兔、狡兔也。按狡者、少壯之意。"}]},"薶":{"expl":"瘞也。从艸貍聲。","rad":"艸","fq":"莫皆切","vol":"01","py":"mái","duan":[{"e":"瘞也。","n":"土部曰。瘞、幽薶也。"}]},"𣬕":{"expl":"獸名。从㲋吾聲。讀若寫。","rad":"㲋","fq":"司夜切","vol":"10","py":"xiě","duan":[{"e":"獸名。从㲋。吾聲。讀若寫。","n":"司夜切。古音在五部。"}]},"𣬎":{"expl":"獸也。似牲牲。从㲋夬聲。","rad":"㲋","fq":"古穴切","vol":"10","py":"jué","duan":[{"e":"𣬎獸也。","n":"三字句。"}]},"兔":{"expl":"獸名。象踞，後其尾形。兔頭與㲋頭同。凡兔之屬皆从兔。","rad":"兔","fq":"湯故切","vol":"10","py":"tù","duan":[{"e":"兔獸也。","n":"各本作獸名。今正。三字句。"}]},"逸":{"expl":"失也。从辵、兔。兔謾訑善逃也。","rad":"兔","fq":"夷質切","vol":"10","py":"yì","duan":[{"e":"失也。","n":"此以曡韵爲訓。亡逸者、本義也。引伸之爲逸游、爲暇逸。"}]},"冤":{"expl":"屈也。从兔从冂。兔在冂下，不得走，益屈折也。","rad":"兔","fq":"於袁切","vol":"10","py":"yuān","duan":[{"e":"屈也。","n":"屈、不伸也。古亦叚宛爲冤。"}]},"婏":{"expl":"兔子也。婏，疾也。从女、兔。","rad":"兔","fq":"芳萬切","vol":"10","py":"fàn","duan":[{"e":"兔子也。","n":"釋獸曰。兔子婏。本或作嬔。按女部曰嬔、生子齊均也。此云婏、兔子也。則二字義別矣。郭云。俗𧦝曰䨲。"}]},"𠓗":{"expl":"疾也。从三兔。闕。","rad":"兔","fq":"芳遇切","vol":"10","py":"fù","duan":[{"e":"疾也。","n":"玉篇、廣韵皆曰。急疾也。今作䞯。少儀曰。毋拔來。毋報往。注云。報讀爲赴疾之赴。拔、赴皆疾也。按赴、䞯皆卽？字。今字？、䞯皆廢矣。"}]},"㕙":{"expl":"狡兔也。从兔夋聲。","rad":"兔","fq":"七旬切","vol":"10","py":"jùn","duan":[]},"萈":{"expl":"山羊細角者。从兔足，𥄕聲。凡萈之屬皆从萈。讀若丸。寬字从此。","rad":"萈","fq":"胡官切","vol":"10","py":"huán","duan":[{"e":"山羊細角者。从兔足。从𥄕聲。","n":"𥄕部下曰。从、从目。萈从𥄕。胡官切。十四部。𥄕在十五部。合音冣近。俗作羱。"}]},"犬":{"expl":"狗之有縣蹏者也。象形。孔子曰：“視犬之字如畫狗也。”凡犬之屬皆从犬。","rad":"犬","fq":"苦泫切","vol":"10","py":"quǎn","duan":[{"e":"狗之有縣蹏者也。","n":"有縣蹏謂之犬。叩氣吠謂之狗。皆於音得義。此與後蹄廢謂之彘。三毛聚居謂之豬。竭尾謂之豕。同明一物異名之所由也。莊子曰。狗非犬。司馬彪曰。同實異名。夫異名必由實異。君子必貴游藝也。"}]},"葠":{"expl":"喪藉也。从艸㑴聲。","rad":"艸","fq":"失廉切","vol":"01","py":"shān","duan":[{"e":"喪藉也。从艸。侵聲。","n":"按此字可疑。上文曰。？、覆也。從艸、侵省聲。不得以一省一不省畫爲二字二義、明矣。且鉉曰失廉切。則與苫音義同。苫固凶服覆席也。且以次第求之。不當廁此。"}]},"狗":{"expl":"孔子曰：“狗，叩也。叩气吠以守。”从犬句聲。","rad":"犬","fq":"古厚切","vol":"10","py":"ɡǒu","duan":[{"e":"孔子曰。狗、叩也。叩气吠㠯守。","n":"吠以當作以吠。許書有扣無叩。扣訓牽馬也。疑古本有叩字、而許逸之。叩、觸也。从卩、口聲。叩气者、出其气也。一說叩卽敂之俗。敂者、擊也。几以此擊彼皆曰敂。犬敂气吠亦是以內禦外。鴻範五行傳注曰。犬、畜之以口吠守者也。屬言。按釋獸云。未成豪、狗。與馬二歲曰駒、熊虎之子曰豿同義。皆謂稚也。"}]},"獀":{"expl":"南趙名犬獿獀。从犬叜聲。","rad":"犬","fq":"所鳩切","vol":"10","py":"sōu","duan":[{"e":"南越名犬獿獀也。","n":"獿獀曡韵字。南越人名犬如是。今江浙尚有此語。"}]},"尨":{"expl":"犬之多毛者。从犬从彡。《詩》曰：“無使尨也吠。”","rad":"犬","fq":"莫江切","vol":"10","py":"mánɡ","duan":[{"e":"犬之多毛者。","n":"釋嘼、毛傳皆曰。尨、狗也。此渾言之。許就字分別言之也。引伸爲襍亂之偁。小戎箋曰䝉尨是也。牛白黑襍毛曰牻。襍語曰哤。皆取以會意。"}]},"狡":{"expl":"少狗也。从犬交聲。匃奴地有狡犬，巨口而黑身。","rad":"犬","fq":"古巧切","vol":"10","py":"jiǎo","duan":[{"e":"少犬也。","n":"犬各本作狗。今依急就篇注、事類賦注作犬。淮南俶眞訓。狡狗之死也。割之有濡。高注。狡、少也。引伸爲狂也、滑也、疾也、健也。"}]},"獪":{"expl":"狡獪也。从犬會聲。","rad":"犬","fq":"古外切","vol":"10","py":"kuài","duan":[{"e":"狡獪也。从犬會聲","n":"方言。劋蹶獪也。秦晉之間曰獪。楚謂之劋。或曰蹶。鄭曰蔿。或曰婚。又曰。央亡、嚜杘、婚、獪也。又曰。㞕？、獪也。郭云。獪古狡㹟字。"}]},"㺜":{"expl":"犬惡毛也。从犬農聲。","rad":"犬","fq":"奴刀切","vol":"10","py":"nónɡ","duan":[{"e":"犬惡毛也。","n":"爾雅。旄毛。郭云。㺜長也。"}]},"猲":{"expl":"短喙犬也。从犬曷聲。《詩》曰：“載獫猲獢。”《爾雅》曰：“短喙犬謂之猲獢。”","rad":"犬","fq":"許謁切","vol":"10","py":"xiē","duan":[{"e":"猲獢、","n":"各本奪此二字。今依全書通例補。雙聲字也。"}]},"獢":{"expl":"猲獢也。从犬喬聲。","rad":"犬","fq":"許喬切","vol":"10","py":"xiāo","duan":[{"e":"猲獢也。从犬。喬聲。","n":"許驕切。二部。毛詩又作驕。"}]},"獫":{"expl":"長喙犬。一曰黑犬黃頭。从犬僉聲。","rad":"犬","fq":"虚檢切","vol":"10","py":"xiǎn","duan":[{"e":"長喙犬也。","n":"見釋嘼、毛詩傳。"}]},"㹥":{"expl":"黃犬黑頭。从犬主聲。讀若注。","rad":"犬","fq":"之戍切","vol":"10","py":"zhù","duan":[{"e":"黃犬黑頭。","n":"廣雅說犬屬有㹥。"}]},"㪿":{"expl":"斷也。从斤斷艸。譚長說。","rad":"艸","fq":"食列切","vol":"01","py":"shé","duan":[{"e":"𣃔也。从斤𣃔艸。譚長說。","n":"㑹意也。食列切。十五部。周禮折瘍。劉昌宗本作㪿。此漢人之舊也。"}]},"猈":{"expl":"短脛狗。从犬卑聲。","rad":"犬","fq":"薄蟹切","vol":"10","py":"bài","duan":[{"e":"短脛犬。","n":"犬舊作狗。今正。說解中例云犬也。猈之言卑也。言矲？也。"}]},"猗":{"expl":"犗犬也。从犬奇聲。","rad":"犬","fq":"於离切","vol":"10","py":"yī","duan":[{"e":"犗犬也。","n":"犬曰猗。如馬曰騬牛曰犗、羊曰羠。言之不妨通互耳。有用爲歎䛐者。齊風傳曰猗嗟歎辭、商頌傳曰猗歎辭是也。衞風傳曰。猗猗、美盛皃。檜風傳曰。猗儺、柔順也。節南山傳曰。猗、長也。皆以音叚借也。有叚爲兮字者。魏風淸且漣猗、淸且直猗、淸且淪猗是也。有叚爲加字者。小雅猗于𤱔丘是也。有叚爲倚字者。小雅有實其猗是也。"}]},"狊":{"expl":"犬視皃。从犬、目。","rad":"犬","fq":"古闃切","vol":"10","py":"jú","duan":[{"e":"犬視皃。从犬目。","n":"古闃切。古十六部。按爾雅須屬。鳥曰狊。此謂鳥振其毛羽如犬張目也。釁、撟、須、狊皆謂須眉、髦鬛、之而、毛觜之鼓動也。故槩之曰須屬。"}]},"𤟟":{"expl":"竇中犬聲。从犬从音，音亦聲。","rad":"犬","fq":"乙咸切","vol":"10","py":"yān","duan":[{"e":"竇中犬聲。","n":"犬鳴竇中聲𤟟𤟟然也。"}]},"默":{"expl":"犬暫逐人也。从犬黑聲。讀若墨。","rad":"犬","fq":"莫北切","vol":"10","py":"mò","duan":[{"e":"犬暫逐人也。","n":"叚借爲人靜穆之偁。亦作嘿。"}]},"猝":{"expl":"犬从艸暴出逐人也。从犬卒聲。","rad":"犬","fq":"麤没切","vol":"10","py":"cù","duan":[{"e":"犬从艸曓出逐人也。","n":"叚借爲凡猝乍之偁。古多叚卒字爲之。"}]},"猩":{"expl":"猩猩，犬吠聲。从犬星聲。","rad":"犬","fq":"桑經切","vol":"10","py":"xīnɡ","duan":[{"e":"猩猩、犬吠聲。","n":"遠聞犬吠聲猩猩然也。"}]},"㺌":{"expl":"犬吠不止也。从犬兼聲。讀若檻。一曰兩犬爭也。","rad":"犬","fq":"胡黯切","vol":"10","py":"xiàn","duan":[{"e":"犬吠不止也。从犬。兼聲。讀若檻。","n":"胡黯切。七部。"}]},"㺖":{"expl":"小犬吠。从犬敢聲。南陽新亭有㺖鄉。","rad":"犬","fq":"荒檻切","vol":"10","py":"hǎn","duan":[{"e":"小犬吠。从犬。𣪏聲。","n":"荒檻切。八部。"}]},"猥":{"expl":"犬吠聲。从犬畏聲。","rad":"犬","fq":"烏賄切","vol":"10","py":"wěi","duan":[{"e":"犬吠聲。","n":"此本義也。廣韵曰。鄙也。今義也。"}]},"卉":{"expl":"艸之緫名也。从艸、屮。","rad":"艸","fq":"許偉切","vol":"01","py":"huì","duan":[{"e":"艸之緫名也。","n":"方言曰。卉、艸也。東越楊州之閒曰卉。"}]},"獿":{"expl":"獿㺒也。从犬、夒。","rad":"犬","fq":"女交切","vol":"10","py":"nǎo","duan":[{"e":"獿、","n":"逗。此複舉字之未删者。"}]},"㺒":{"expl":"犬獿獿咳吠也。从犬翏聲。","rad":"犬","fq":"火包切","vol":"10","py":"xiāo","duan":[{"e":"犬獿獿咳吠也。","n":"廣雅曰。擾也。"}]},"㺑":{"expl":"犬容頭進也。从犬參聲。一曰賊疾也。","rad":"犬","fq":"山檻切","vol":"10","py":"shǎn","duan":[{"e":"犬容頭進也。","n":"也當作皃。漢書曰。容頭過身。"}]},"𤟌":{"expl":"嗾犬厲之也。从犬，將省聲。","rad":"犬","fq":"即兩切","vol":"10","py":"jiǎnɡ","duan":[{"e":"嗾犬厲之也。","n":"口部曰。嗾、使犬聲也。厲之猶勉之也。引伸爲凡勸勉之偁。方言曰。自關而西秦晉之間相勸曰聳。或曰奬。中心不欲而由旁人之勸語亦曰聳。凡相被飾亦曰奬。"}]},"㹽":{"expl":"齧也。从犬戔聲。","rad":"犬","fq":"初版切","vol":"10","py":"chǎn","duan":[{"e":"犬齧也。","n":"犬字今補。"}]},"狦":{"expl":"惡健犬也。从犬，𠛹省聲。","rad":"犬","fq":"所晏切","vol":"10","py":"shàn","duan":[{"e":"惡健犬也。","n":"廣雅曰。狼也。"}]},"狠":{"expl":"吠鬬聲。从犬艮聲。","rad":"犬","fq":"五還切","vol":"10","py":"yán","duan":[{"e":"犬鬥聲。","n":"犬各本作吠。今依宋本及集韵正。鬥各本作鬬。今正。今俗用狠爲很。許書很狠義別。"}]},"㺕":{"expl":"犬鬬聲。从犬番聲。","rad":"犬","fq":"附袁切","vol":"10","py":"fán","duan":[{"e":"犬鬥聲。","n":"鬥字今正。"}]},"狋":{"expl":"犬怒皃。从犬示聲。一曰犬難得。代郡有狋氏縣。讀又若銀。","rad":"犬","fq":"語其切","vol":"10","py":"yí","duan":[{"e":"犬怒皃。","n":"漢書東方、朔傳曰。狋吽牙者、兩犬爭也。"}]},"㹞":{"expl":"犬吠聲。从犬斤聲。","rad":"犬","fq":"語斤切","vol":"10","py":"yín","duan":[{"e":"犬吠聲。","n":"九辨。猛犬狺狺而迎吠。王注。讒佞讙呼而在側也。狺卽㹞字。"}]},"禂":{"expl":"禱牲馬祭也。从示周聲。《詩》曰：“旣禡旣禂。”","rad":"示","fq":"都皓切","vol":"01","py":"dǎo","duan":[{"e":"禱牲馬祭也。","n":"甸祝。禂牲禂馬。杜子春云。禂、禱也。爲馬禱無疾。爲田禱多獲禽牲。詩云。旣伯旣禱。爾雅曰。旣伯旣禱。伯、馬祭也。王裁按。此許說所本。杜引詩者、以伯證禱馬。毛傳云。伯、馬祖也。重物愼微。將用馬力。必先爲之禱其祖。此周禮之禂馬也。又云。禱、禱獲也。此釋旣禱。周禮之禂牲也。杜本毛說。鄭君易杜說云。禂讀如伏誅之誅。今侏大字也。爲牲祭求肥充。爲馬祭求肥健。鄭以上文旣有表貉釋爲禱氣勢之十百。而多獲不當禂牲。又云禱多獲禽牲。故必易爲侏大而後安。今本爾雅、周禮注馬祭之上皆脫伯字。"}]},"艽":{"expl":"逺荒也。从艸九聲。《詩》曰：“至于艽野。”","rad":"艸","fq":"巨鳩切","vol":"01","py":"qiú","duan":[{"e":"遠荒也。","n":"艽之言究也。竆也。"}]},"獡":{"expl":"犬獡獡不附人也。从犬舄聲。南楚謂相驚曰獡。讀若愬。","rad":"犬","fq":"式略切","vol":"10","py":"shuò","duan":[{"e":"犬獡獡不附人也。","n":"良犬宋獡、以此得名。亦作猎、作㹱。"}]},"獷":{"expl":"犬獷獷不可附也。从犬廣聲。漁陽有獷平縣。","rad":"犬","fq":"古猛切","vol":"10","py":"ɡuǎnɡ","duan":[{"e":"犬獷獷不可附也。","n":"呂氏春秋。荊文王得茹黃之狗。說苑作如黃。廣雅犬屬有楚黃。廣韵作楚獚。經典釋文作楚獷。實一字也。引伸爲凡麤惡皃之偁。漢書曰。獷獷亡秦。"}]},"狀":{"expl":"犬形也。从犬爿聲。","rad":"犬","fq":"盈亮切","vol":"10","py":"zhuànɡ","duan":[{"e":"犬形也。","n":"引伸爲形狀。如類之引伸爲同類也。"}]},"𤞛":{"expl":"妄彊犬也。从犬从壯，壯亦聲。","rad":"犬","fq":"徂朗切","vol":"10","py":"zànɡ","duan":[{"e":"妄彊犬也。从犬壯。壯亦聲。","n":"徂朗切。十部。"}]},"獒":{"expl":"犬如人心可使者。从犬敖聲。《春秋傳》曰：“公嗾夫獒。”","rad":"犬","fq":"五牢切","vol":"10","py":"áo","duan":[{"e":"犬知人心可使者。","n":"知一作如。公羊傳曰。靈公有周狗謂之獒。何注。周狗、可以比周之狗。所指如意者。按周狗爾雅注及博物志或譌作害狗。不可爲據也。釋嘼曰。犬高四尺曰獒。"}]},"獳":{"expl":"怒犬皃。从犬需聲。讀若槈。","rad":"犬","fq":"奴豆切","vol":"10","py":"nóu","duan":[{"e":"怒犬皃。从犬。需聲。讀若槈。","n":"奴豆切。又乃矦切。四部。或作𤟦者、譌字也。"}]},"狧":{"expl":"犬食也。从犬从舌。讀若比目魚鲽之鲽。","rad":"犬","fq":"他合切","vol":"10","py":"tà","duan":[{"e":"犬食也。","n":"爾雅。牛曰齝。羊曰？。麋鹿曰齸。鳥曰嗉。寓鼠曰嗛。當補之曰犬曰狧。犬食主舌。他物主喉也。漢吳王濞傳曰。狧穅及米。史記作𦧇。𦧇見舌部。以舌取食也。食爾反。狧讀如答。異字異音而同義。顏注云狧古𦧇字。乃大誤。"}]},"狎":{"expl":"犬可習也。从犬甲聲。","rad":"犬","fq":"胡甲切","vol":"10","py":"xiá","duan":[{"e":"犬可習也。","n":"引伸爲凡相習之偁。古叚甲爲之。衞風傳曰。甲、狎也。此言叚借也。"}]},"狃":{"expl":"犬性驕也。从犬丑聲。","rad":"犬","fq":"女久切","vol":"10","py":"niǔ","duan":[{"e":"犬性忕也。","n":"忕大徐作驕。非。忕、習也。余制切。心部作𢘽。習也。𢘽卽忕之譌也。狃本謂犬性之忕。引伸叚借爲凡忕習之偁。鄭風傳曰。狃、習也。國語韋注、左傳杜注皆曰。狃、忕也。"}]},"犯":{"expl":"侵也。从犬巳（段註改為㔾）聲。","rad":"犬","fq":"防險切","vol":"10","py":"fàn","duan":[{"e":"㑴也。","n":"本謂犬。叚借之謂人。"}]},"蒜":{"expl":"葷菜。从艸祘聲。","rad":"艸","fq":"蘇貫切","vol":"01","py":"suàn","duan":[{"e":"葷菜也。菜之美者雲夢之葷菜。","n":"爾雅音義、齊民要術、太平御覽引皆作此九字。音義云。一本如是。今兩存之。大戴禮夏小正。十二月納卵蒜。卵蒜者何。本如卵者也。納者何。納之君也。案經之卵蒜、今之小蒜也。凡物之小者偁卵。禮之卵醬、卽鯤醬。詩之緫角卝兮、謂幼稚也。卝者、說文卵字也。陶貞白云。小蒜名薍子。薍音亂。卽小正卵字。其大蒜乃張騫始得自西域者。本艸。大蒜名葫。小蒜名蒜。葢始以大蒜別於蒜。後復以小蒜別於大蒜。古衹有蒜而已。"}]},"猜":{"expl":"恨賊也。从犬青聲。","rad":"犬","fq":"倉才切","vol":"10","py":"cāi","duan":[{"e":"恨賊也。","n":"本謂犬。叚借之謂人。"}]},"猛":{"expl":"健犬也。从犬孟聲。","rad":"犬","fq":"莫杏切","vol":"10","py":"měnɡ","duan":[{"e":"健犬也。","n":"叚借爲凡健之偁。"}]},"犺":{"expl":"健犬也。从犬亢聲。","rad":"犬","fq":"苦浪切","vol":"10","py":"kànɡ","duan":[{"e":"健犬也。","n":"本謂犬。引伸謂人。廣韵曰。猰犺不順。"}]},"㹤":{"expl":"多畏也。从犬去聲。","rad":"犬","fq":"去劫切","vol":"10","py":"qiè","duan":[{"e":"多畏也。","n":"本謂犬。叚借謂人。"}]},"獜":{"expl":"健也。从犬粦聲。《詩》曰：“盧獜獜。”","rad":"犬","fq":"力珍切","vol":"10","py":"lín","duan":[{"e":"健也。","n":"廣韵引犬健也。今本奪犬字。"}]},"獧":{"expl":"疾跳也。一曰急也。从犬瞏聲。","rad":"犬","fq":"古縣切","vol":"10","py":"juàn","duan":[{"e":"疾跳也。","n":"跳者、躍也。"}]},"倏":{"expl":"走也。从犬攸聲。讀若叔。","rad":"犬","fq":"式竹切","vol":"10","py":"shū","duan":[{"e":"犬𧺆疾也。","n":"依韵會本訂。引伸爲凡忽然之詞。或叚儵字爲之。"}]},"狟":{"expl":"犬行也。从犬亘聲。《周禮》曰：“尚狟狟。”","rad":"犬","fq":"胡官切","vol":"10","py":"huán","duan":[{"e":"犬行也。","n":"廣韵作大犬也。"}]},"犻":{"expl":"過弗取也。从犬巿聲。讀若孛。","rad":"犬","fq":"蒲没切","vol":"10","py":"bó","duan":[{"e":"過弗取也。","n":"此有誤字。玉篇但云犬過。廣韵但云拂取。疑當合之曰犬過拂取。"}]},"𤟍":{"expl":"犬張耳皃。从犬易聲。","rad":"犬","fq":"陟革切","vol":"10","py":"zhé","duan":[{"e":"犬張耳皃。从犬。易聲。","n":"陟革切。十六部。"}]},"芥":{"expl":"菜也。从艸介聲。","rad":"艸","fq":"古拜切","vol":"01","py":"jiè","duan":[{"e":"菜也。","n":"借爲艸芥、纖芥字。"}]},"猌":{"expl":"犬張齗怒也。从犬來聲。讀又若銀。","rad":"犬","fq":"魚僅切","vol":"10","py":"yìn","duan":[{"e":"犬張齗怒也。","n":"齗、齒本也。"}]},"犮":{"expl":"走犬皃。从犬而丿之。曳其足，則剌犮也。","rad":"犬","fq":"蒲撥切","vol":"10","py":"bá","duan":[{"e":"犬走皃。","n":"依篇。韵訂。"}]},"戾":{"expl":"曲也。从犬出戶下。戾者，身曲戾也。","rad":"犬","fq":"郎計切","vol":"10","py":"lì","duan":[{"e":"曲也。","n":"了戾、乖戾、很戾皆其義也。引伸之訓爲罪。見釋詁、詩毛傳。又訓爲至、訓爲來、訓爲止、訓爲待、訓爲定。皆見釋詁、毛傳。皆於曲引伸之。曲必有所至。故其引伸如是。釋言曰。疑休戾也。"}]},"獨":{"expl":"犬相得而鬬也。从犬蜀聲。羊爲羣，犬爲獨也。一曰北嚻山有獨𤞞獸，如虎，白身，豕鬣，尾如馬。","rad":"犬","fq":"徒谷切","vol":"10","py":"dú","duan":[{"e":"犬相得而鬥也。","n":"鬥各本作鬬。今正。凡爭鬥字許作鬥。鬬者、遇也。其義各殊。今人乃謂鬬正、鬥俗。非也。"}]},"𤞞":{"expl":"獨𤞞，獸也。从犬谷聲。","rad":"犬","fq":"余蜀切","vol":"10","py":"yù","duan":[{"e":"獨𤞞獸也。从犬。谷聲。","n":"此蒙上文言獨𤞞而終之。依全書之例則當次於狻玃以下。余蜀切。三部。郭音谷。"}]},"𤣔":{"expl":"秋田也。从犬璽聲。","rad":"犬","fq":"息淺切","vol":"10","py":"xiǎn","duan":[{"e":"秌田也。","n":"釋天曰。秋獵爲獮。鄭君、韋昭、薛綜、杜預皆曰。獮、殺也。釋獮爲殺者、以曡韵爲訓。古音獮與璽同也。若明堂位叚省爲獮、取其雙聲耳。"}]},"獵":{"expl":"放獵逐禽也。从犬巤聲。","rad":"犬","fq":"良涉切","vol":"10","py":"liè","duan":[{"e":"放獵、逐禽也。","n":"放小徐作畋。畋、平田也。非許義。韵會作效。效疑校之譌。校獵見吳都賦。葢卽孟子之獵較也。校獵二字逗。以逐禽釋之。蔡邕月令章句曰。獵、捷也。白虎通曰。四時之田緫名爲獵。毛詩。不狩不獵。箋云。冬獵曰狩。宵田曰獵。此因經文重言而分別之也。引伸爲凌獵。爲捷獵。"}]},"獠":{"expl":"獵也。从犬尞聲。","rad":"犬","fq":"力昭切","vol":"10","py":"liáo","duan":[{"e":"獵也。","n":"許渾言之。釋天析言之曰。宵田爲獠。管子四稱篇。獠獵畢弋。"}]},"狩":{"expl":"犬田也。从犬守聲。《易》曰：“明夷于南狩。”","rad":"犬","fq":"書究切","vol":"10","py":"shòu","duan":[{"e":"火田也。","n":"火各本作犬。不可通。今依韵會正。釋天曰。冬獵爲狩。周禮、左傳、公羊、穀梁、夏小正傳、毛詩傳皆同。又釋天曰。火田爲狩。許不偁冬獵而偁火田者、火田必於冬。王制曰。昆蟲未蟄。不以火田。故言火以該冬也。孟子曰。天子適諸矦曰巡狩。巡狩者巡所守也。此謂六書叚借以守爲狩。有叚守爲狩者。如明夷于南狩、天王狩于河陽皆或作守是也。"}]},"臭":{"expl":"禽走，臭而知其迹者，犬也。从犬从自。","rad":"犬","fq":"尺救切","vol":"10","py":"xiù","duan":[{"e":"禽走臭而知其迹者犬也。","n":"走臭猶言逐氣。犬能行路蹤迹前犬之所至。於其气知之也。故其字从犬自。自者、鼻也。引伸叚借爲凡气息芳臭之偁。"}]},"蔥":{"expl":"菜也。从艸悤聲。","rad":"艸","fq":"倉紅切","vol":"01","py":"cōnɡ","duan":[{"e":"菜也。","n":"爾雅。茖、山蔥。管子冬蔥。皆蔥之屬。"}]},"獲":{"expl":"獵所獲也。从犬蒦聲。","rad":"犬","fq":"胡伯切","vol":"10","py":"huò","duan":[{"e":"獵所獲也。","n":"故从犬。引伸爲凡得之偁。"}]},"獘":{"expl":"頓仆也。从犬敝聲。《春秋傳》曰：“與犬，犬獘。”","rad":"犬","fq":"毗祭切","vol":"10","py":"bì","duan":[{"e":"頓仆也。","n":"人部曰。仆者、頓也。謂前覆也。人前仆若頓首然。故曰頓仆。"}]},"獻":{"expl":"宗廟犬名羹獻。犬肥者以獻之。从犬鬳聲。","rad":"犬","fq":"許建切","vol":"10","py":"xiàn","duan":[{"e":"宗廟犬名羹獻。犬肥者以獻。","n":"此說从犬之意也。曲禮曰。凡祭宗廟之禮。犬曰羹獻。按羹之言良也。獻本祭祀奉犬牲之偁。引伸之爲凡薦進之偁。按論語鄭注曰。獻猶賢也。獻得訓賢者、周禮注獻讀爲儀。是以伏生尙書民儀有十夫、古文尙書作民獻。咎繇誤古文萬邦黎獻、漢孔宙碑費鳳碑斥彰長田君碑皆用黎儀字。皆用伏生尙書也。班固北征頌亦用民儀字。"}]},"𤜵":{"expl":"獟犬也。从犬幵聲。一曰逐虎犬也。","rad":"犬","fq":"五甸切","vol":"10","py":"yàn","duan":[{"e":"獟犬也。从犬。幵聲。","n":"五甸切。十四部。"}]},"獟":{"expl":"𤜵犬也。从犬堯聲。","rad":"犬","fq":"五弔切","vol":"10","py":"yào","duan":[{"e":"𤜵犬也。","n":"二篆爲轉注。"}]},"狾":{"expl":"狂犬也。从犬折聲。《春秋傳》曰：“狾犬入華臣氏之門。”","rad":"犬","fq":"征例切","vol":"10","py":"zhì","duan":[{"e":"𤝵犬也。","n":"左傳哀十二年。國狗之瘈。無不噬也。杜云。瘈、狂也。按今左傳作瘈。非古也。許所見作狾。"}]},"狂":{"expl":"狾犬也。从犬㞷聲。","rad":"犬","fq":"巨王切","vol":"10","py":"kuánɡ","duan":[{"e":"狾犬也。","n":"二篆爲轉注。叚借之爲人病之偁。"}]},"類":{"expl":"種類相似，唯犬爲甚。从犬頪聲。","rad":"犬","fq":"力遂切","vol":"10","py":"lèi","duan":[{"e":"穜類相佀。唯犬爲甚。","n":"說从犬之意也。類本謂犬相佀。引伸叚借爲凡相佀之偁。釋詁、毛傳皆曰。類、善也。釋類爲善、猶釋不肖爲不善也。左傳。𠛬之頗類。叚類爲纇。"}]},"狄":{"expl":"赤狄，本犬種。狄之爲言淫辟也。从犬，亦省聲。","rad":"犬","fq":"徒歴切","vol":"10","py":"dí","duan":[{"e":"北狄也。","n":"北各本作赤。誤。今正。赤狄乃錯居中國狄之一種耳。許書蟲部曰南蠻、曰東南閩越。大部曰東方夷。羊部曰西方羌。豸部曰北方貉。則此必言北狄。狄與貉皆在北。而貉在東北。狄在正北。釋地曰。九夷、八狄、七戎、六蠻、謂之四海。八蠻在南方。六戎在西方。五狄在北方。李巡云。五狄者、一曰月支。二曰穢貊。三曰匈奴。四曰箄于。五曰白屋。王制、明堂位皆言東夷、南蠻、西戎、北狄。"}]},"狻":{"expl":"狻麑，如虦貓，食虎豹者。从犬夋聲。見《爾雅》。","rad":"犬","fq":"素官切","vol":"10","py":"suān","duan":[{"e":"狻麑、","n":"逗。"}]},"蒮":{"expl":"艸也。从艸隺聲。《詩》曰：“食鬱及蒮。”","rad":"艸","fq":"余六切","vol":"01","py":"yù","duan":[{"e":"艸也。","n":"爾雅、蒮、山韭。郭注謂山中多有此菜。如人家所種者。故許不謂之菜與。"}]},"玃":{"expl":"母猴也。从犬矍聲。《爾雅》云：“玃父善顧。”攫持人也。","rad":"犬","fq":"俱縛切","vol":"10","py":"jué","duan":[{"e":"大母猴也。","n":"各本無大。今依爾雅釋文、玄應書、廣韵補。釋獸曰。貜父善顧。郭云。貑貜也。似獮猴而大。色蒼黑。能攫持人。善顧盼。按張揖注上林賦曰。玃似獮猴而大。"}]},"猶":{"expl":"玃屬。从犬酋聲。一曰隴西謂犬子爲猷。","rad":"犬","fq":"以周切","vol":"10","py":"yóu","duan":[{"e":"玃屬。","n":"釋獸曰。猶如麂。善登木。許所說謂此也。曲禮曰。使民決嫌疑。定猶豫。正義云。說文。猶、玃屬。豫、𧰼屬。此二獸皆進退多疑。人多疑惑者似之。故謂之猶豫。按古有以聲不以義者。如猶豫雙聲。亦作猶與。亦作冘豫。皆遲疑之皃。老子。豫兮如冬涉川。猶兮若畏四鄰。離騷。心猶豫而狐疑。以猶豫二字皃其狐疑耳。李善注洛神賦乃以猶獸多豫、狐獸多疑對說。王逸注離騷絶不如此。禮記正義則又以猶與豫二獸對說。皆郢書燕說也。如九歌君不行兮夷猶。王逸卽以猶豫解之。要亦是雙聲字。春秋經猶三望、猶朝于廟、猶繹今。謂可已而不已者曰猶。卽猶豫、夷猶之意也。釋詁曰。猷、謀也。釋言曰。猷、圖也。召南傳曰。猶、若也。說文。圖者、畫也。計難也。謀者"}]},"狙":{"expl":"玃屬。从犬且聲。一曰狙，犬也，暫齧人者。一曰犬不齧人也。","rad":"犬","fq":"親去切","vol":"10","py":"jū","duan":[{"e":"玃屬。","n":"莊子。狙公賦芧。司馬彪云。狙、一名獦牂。似猨而狗頭。喜與雌猨交。崔譔、向秀謂之猵狙。釋文。狙七餘反。"}]},"猴":{"expl":"夒也。从犬矦聲。","rad":"犬","fq":"乎溝切","vol":"10","py":"hóu","duan":[{"e":"夒也。","n":"夒上當有母猴二字。夒下曰。獸也。一名母猴。爲下曰。母猴也。玃下曰。大母猴也。禺下曰。母猴屬也。夒下曰。食母猴。母猴乃此獸名。非謂牝者。沐猴、獮猴皆語之轉。字之譌也。陸佃據桺子厚之言曰。蝯靜而猴躁。其性迥殊。按許書亦猴與蝯別。析言之也。若蝯下曰禺屬。禺下曰母猴屬。毛傳曰。猱、猿屬。猱卽說文之夒字。是二者可相爲屬而非一物也。爾雅曰。猱蝯善援。謂二者一類。"}]},"㺉":{"expl":"犬屬。𦝫已上黃，𦝫已下黑，食母猴。从犬𣪊聲。讀若構。或曰㺉似牂羊，出蜀北嚻山中，犬首而馬尾。","rad":"犬","fq":"火屋切","vol":"10","py":"hù","duan":[{"e":"犬屬。","n":"疑犬屬之上當有？貜二字。淺人妄删之。詳於此、故豸部但曰？貜也。"}]},"狼":{"expl":"似犬，銳頭，白頰，高前，廣後。从犬良聲。","rad":"犬","fq":"魯當切","vol":"10","py":"lánɡ","duan":[{"e":"佀犬。銳頭白頰。高歬廣後。","n":"詳其狀可識別也。毛傳曰。狼、獸名。釋獸曰。狼、牡貛。許謂貛卽貒。"}]},"狛":{"expl":"如狼，善驅羊。从犬白聲。讀若蘗。甯嚴讀之若淺泊。","rad":"犬","fq":"匹各切","vol":"10","py":"bó","duan":[{"e":"如狼。善驅羊。从犬。白聲。讀若檗。","n":"當言柏。今人黃檗字作黃柏。正雙聲之轉也。"}]},"獌":{"expl":"狼屬。从犬曼聲。《爾雅》曰：“貙獌，似貍。”","rad":"犬","fq":"舞販切","vol":"10","py":"màn","duan":[{"e":"狼屬。从犬。曼聲。","n":"舞販切。十四部。"}]},"狐":{"expl":"䄏獸也。鬼所乘之。有三徳：其色中和，小前大後，死則丘首。从犬瓜聲。","rad":"犬","fq":"戶吳切","vol":"10","py":"hú","duan":[{"e":"䄏獸也。鬼所乘之。","n":"爾雅音義無之字。"}]},"獺":{"expl":"如小狗也。水居食魚。从犬賴聲。","rad":"犬","fq":"他達切","vol":"10","py":"tǎ","duan":[{"e":"水狗也。","n":"小徐作小狗。大徐作如小狗。今依廣韵訂。"}]},"蕇":{"expl":"亭歴也。从艸單聲。","rad":"艸","fq":"多殄切","vol":"01","py":"diǎn","duan":[{"e":"亭歷也。","n":"釋艸文。月令靡艸之一也。"}]},"猵":{"expl":"獺屬。从犬扁聲。","rad":"犬","fq":"布兹切","vol":"10","py":"biān","duan":[{"e":"獺屬。","n":"楊雄蜀都賦作猵。羽獵賦、江賦作獱。郭樸三蒼解詁云。獱似狐。靑色。居水中。食魚。"}]},"猋":{"expl":"犬走皃。从三犬。","rad":"犬","fq":"甫遙切","vol":"10","py":"biāo","duan":[{"e":"犬走皃。","n":"引伸爲凡走之偁。九歌。猋遠舉兮雲中。王注。猋、去疾皃。爾雅。扶搖謂之猋。作此字。"}]},"狘":{"expl":"獸走皃。从犬戉聲。","rad":"犬","fq":"許月切","vol":"10","py":"xuè","duan":[]},"𤟤":{"expl":"獸名。从犬軍聲。","rad":"犬","fq":"許韋切","vol":"10","py":"huī","duan":[]},"狷":{"expl":"褊急也。从犬肙聲。","rad":"犬","fq":"古縣切","vol":"10","py":"juàn","duan":[]},"猰":{"expl":"猰㺄，獸名。从犬契聲。","rad":"犬","fq":"烏黠切","vol":"10","py":"yà","duan":[]},"㹜":{"expl":"兩犬相齧也。从二犬。凡㹜之屬皆从㹜。","rad":"㹜","fq":"語斤切","vol":"10","py":"yín","duan":[{"e":"㒳犬相齧也。","n":"㒳各本作兩。今正。"}]},"㺇":{"expl":"司空也。从㹜𦣞聲。復說獄司空。","rad":"㹜","fq":"息兹切","vol":"10","py":"sī","duan":[{"e":"司空也。","n":"此空字衍。司者今之伺字。以司釋㺇。以曡韵爲訓也。許書無伺字。以司爲之。玉篇㺇注云。察也。今作伺、覗。按希馮直以㺇爲伺、覗之古字。葢用許說也。其字从㹜。葢謂㒳犬吠守、伺察之意。"}]},"獄":{"expl":"确也。从㹜从言。二犬，所以守也。","rad":"㹜","fq":"魚欲切","vol":"10","py":"yù","duan":[{"e":"确也。","n":"召南傳曰。獄、埆也。埆同确。堅剛相持之意。"}]},"鼠":{"expl":"穴蟲之緫名也。象形。凡鼠之屬皆从鼠。","rad":"鼠","fq":"書呂切","vol":"10","py":"shǔ","duan":[{"e":"穴蟲之緫名也。","n":"其類不同而皆謂之鼠。引伸之爲病也。見釋詁。毛詩正月作癙。雨無正作鼠。實一字也。"}]},"苟":{"expl":"艸也。从艸句聲。","rad":"艸","fq":"古厚切","vol":"01","py":"ɡǒu","duan":[{"e":"艸也。","n":"孔注論語云。苟、誠也。鄭注燕禮云。苟、且也。假也。皆假借也。"}]},"𪖇":{"expl":"鼠也。从鼠番聲。讀若樊。或曰鼠婦。","rad":"鼠","fq":"附袁切","vol":"10","py":"fán","duan":[{"e":"𪖇鼠也。","n":"三字爲句。各本皆删一字。淺人所爲也。以下皆同。廣雅謂之白？。王氏念孫曰。？之言皤也。"}]},"䶅":{"expl":"鼠，出胡地，皮可作裘。从鼠各聲。","rad":"鼠","fq":"下各切","vol":"10","py":"hé","duan":[{"e":"䶅鼠。出胡地。皮可作裘。从鼠。各聲。","n":"下各切。五部。"}]},"鼢":{"expl":"地行鼠，伯勞所作也。一曰偃鼠。从鼠分聲。","rad":"鼠","fq":"芳吻切","vol":"10","py":"fén","duan":[{"e":"地中行鼠。伯勞所化也。","n":"中字依爾雅䧽文補。化各本作作。今依廣韵所引字林正。釋獸有鼢鼠。郭云。地中行者。陶隱居云。鼹鼠、一名隱鼠。一名鼢鼠。常穿耕地中。討掘卽得。蘇頌圖經曰。卽化爲鴽者也。按依許氏說。百勞化田鼠。而田鼠化鴽。物類遞嬗。有如斯矣。方言謂之䵓鼠。䵓卽犁字。自其場起若耕言之則曰犁鼠。"}]},"䶄":{"expl":"䶄令鼠。从鼠平聲。","rad":"鼠","fq":"薄經切","vol":"10","py":"pínɡ","duan":[{"e":"䶄令鼠也。","n":"四字句。令平聲。䶄令曡韵字。"}]},"鼶":{"expl":"鼠也。从鼠虒聲。","rad":"鼠","fq":"息移切","vol":"10","py":"sī","duan":[{"e":"鼶鼠也。","n":"三字句。見小正九月。"}]},"𪕚":{"expl":"竹鼠也。如大。从鼠，畱省聲。","rad":"鼠","fq":"力求切","vol":"10","py":"liú","duan":[{"e":"竹鼠也。如犬。","n":"後世所謂竹？也。莊子作畱。又作？。"}]},"鼫":{"expl":"五技鼠也。能飛，不能過屋；能緣，不能窮木；能游，不能渡谷；能穴，不能掩身；能走，不能先人。从鼠石聲。","rad":"鼠","fq":"常隻切","vol":"10","py":"shí","duan":[{"e":"五技鼠也。能飛不能過屋。能緣不能竆木。能游不能渡谷。","n":"三句一韵。"}]},"鼨":{"expl":"豹文鼠也。从鼠冬聲。","rad":"鼠","fq":"職戎切","vol":"10","py":"zhōnɡ","duan":[{"e":"豹文鼠也。","n":"釋獸曰。鼨鼠豹文鼮鼠。郭讀以豹文下屬。云鼠文采如豹者。漢武帝時得此鼠。孝廉郞終軍知之。賜絹百匹。按文𨕖注、藝文類聚皆引竇氏家傳載此事。系之光武時竇攸。以豹文爲鼮鼠則同。惟唐書盧若虚傳云。時有𫉬異鼠者。豹首虎臆。大如拳。職方辛怡諫謂之鼮鼠而賦之。若虚曰。非也。此許愼所謂鼨鼠。豹文而形小。一坐盡驚。玉裁謂。他人讀爾雅皆豹文鼮鼠爲句。終軍、竇攸、辛怡諫從之。許讀爾雅鼨鼠豹文爲句。盧若虚從之。其是非訖難定也。許有鼨無鼮。疑爾雅六字爲一物。"}]},"𪕶":{"expl":"鼠屬。从鼠益聲。","rad":"鼠","fq":"於革切","vol":"10","py":"è","duan":[{"e":"鼠屬。从鼠。益聲。","n":"於革切。十六部。"}]},"鼷":{"expl":"小鼠也。从鼠奚聲。","rad":"鼠","fq":"胡雞切","vol":"10","py":"xī","duan":[{"e":"小鼠也。","n":"何休公羊傳注云。鼷鼠、鼠中之微者。玉篇云。有螫毒。食人及鳥獸皆不痛。今之甘口鼠也。"}]},"蕨":{"expl":"鼈也。从艸厥聲。","rad":"艸","fq":"居月切","vol":"01","py":"jué","duan":[{"e":"鼈也。","n":"釋艸、毛傳同。陸機云。周秦曰蕨。齊魯曰鼈。鼈俗從艸。"}]},"鼩":{"expl":"精鼩鼠也。从鼠句聲。","rad":"鼠","fq":"其俱切","vol":"10","py":"qú","duan":[{"e":"精鼩鼠也。","n":"四字一句。爾雅謂之鼩鼠。郭注。小鼱鼩也。亦名？鼩。漢書東方朔傳如淳注曰。鼱鼩、小鼠也。音精劬。據爾雅釋文、字林有鼱字。"}]},"鼸":{"expl":"䶃也。从鼠兼聲。","rad":"鼠","fq":"丘檢切","vol":"10","py":"xiàn","duan":[{"e":"䶃也。","n":"爾雅鼸鼠。郭云。以頰裹藏食者。"}]},"䶃":{"expl":"鼠屬。从鼠今聲。讀若含。","rad":"鼠","fq":"胡男切","vol":"10","py":"hán","duan":[{"e":"鼠屬。","n":"廣韵謂之？鼠。"}]},"鼬":{"expl":"如鼠，赤黃而大，食鼠者。从鼠由聲。","rad":"鼠","fq":"余救切","vol":"10","py":"yòu","duan":[{"e":"如鼠。","n":"如鼠小徐作如鼦。鼦乃俗貂字。貂、鼠屬也。"}]},"䶂":{"expl":"胡地風鼠。从鼠勺聲。","rad":"鼠","fq":"之若切","vol":"10","py":"zhuó","duan":[{"e":"胡地風鼠。","n":"郭注爾雅鼫鼠云。形大如鼠。頭似兔。尾有毛。靑黃色。好在田中食粟豆。關西呼爲䶂鼠。見廣雅。音雀。按廣雅云䶂鼠、鼫鼠。與景純皆合䶂、鼫爲一物。以說文正之。鼫與䶂迥非一物也。葢俗語有移易其名者耳。"}]},"𪕎":{"expl":"鼠屬。从鼠宂聲。","rad":"鼠","fq":"而隴切","vol":"10","py":"rǒnɡ","duan":[{"e":"鼠屬。从鼠。宂聲。","n":"而隴切。九部。按此字或讀余救切。要與鼬非一物。"}]},"𪕊":{"expl":"鼠，似雞，鼠尾。从鼠此聲。","rad":"鼠","fq":"即移切","vol":"10","py":"zī","duan":[{"e":"𪕊鼠。佀雞。鼠尾。从鼠。此聲。","n":"卽移切。十五十六部。"}]},"鼲":{"expl":"鼠。出丁零胡，皮可作𧚍。从鼠軍聲。","rad":"鼠","fq":"乎昆切","vol":"10","py":"hún","duan":[{"e":"鼲鼠。出丁零胡。皮可作裘。","n":"魏志注引魏略云。丁零國出名鼠皮。靑昆子、白昆子皮。王氏引之云。昆子卽鼲子也。後漢書鮮卑傳云。鮮卑有貂、豽、鼲子。皮毛柔輭。天下以爲名裘。按今俗語通曰灰鼠。聲之轉也。如揮翬皆本軍聲。"}]},"𪕮":{"expl":"斬𪕮鼠。黑身，白腰若帶；手有長白毛，似握版之狀；類蝯蜼之屬。从鼠胡聲。","rad":"鼠","fq":"戶吳切","vol":"10","py":"hú","duan":[{"e":"斬𪕮鼠。黑身白𦝫若帶。手有長白毛。佀握版之狀。類蝯蜼之屬。","n":"見上林、西京賦。諸家說其狀乖異不同。其字或作螹胡。或作獑胡。或作獑猢。或作𪖎𪕱。"}]},"能":{"expl":"熊屬。足似鹿。从肉㠯聲。能獸堅中，故稱賢能；而彊壯，稱能傑也。凡能之屬皆从能。","rad":"能","fq":"奴登切","vol":"10","py":"nénɡ","duan":[{"e":"熊屬。","n":"左傳、國語皆云晉侯夢黃能入於寝門。韋注曰。能似熊。凡左傳、國語能作熊者、皆淺人所改也。"}]},"莎":{"expl":"鎬侯也。从艸沙聲。","rad":"艸","fq":"蘇禾切","vol":"01","py":"suō","duan":[{"e":"鎬矦也。","n":"夏小正。正月緹縞。縞也者、莎隨也。緹也者、其實也。先言緹而後言縞者、何也。緹先見者也。釋艸。薃矦、莎。其實媞。按縞薃鎬同字。許讀爾雅鎬矦爲句。鎬矦雙聲。莎隨㬪韵。皆絫呼也。單呼則曰縞、曰莎。其根卽今香附子。"}]},"熊":{"expl":"獸似豕。山居，冬蟄。从能，炎省聲。凡熊之屬皆从熊。","rad":"熊","fq":"羽弓切","vol":"10","py":"xiónɡ","duan":[{"e":"熊獸、佀豕。山凥。","n":"俗作居。"}]},"羆":{"expl":"如熊，黃白文。从熊，罷省聲。","rad":"熊","fq":"彼爲切","vol":"10","py":"pí","duan":[{"e":"如熊。黃白文。","n":"見釋獸。"}]},"火":{"expl":"燬也。南方之行，炎而上。象形。凡火之屬皆从火。","rad":"火","fq":"呼果切","vol":"10","py":"huǒ","duan":[{"e":"𤈦也。","n":"𤈦各本作燬。今正。下文曰𤈦、火也。爲轉注。"}]},"炟":{"expl":"上諱。","rad":"火","fq":"當割切","vol":"10","py":"dá","duan":[{"e":"上諱。","n":"漢章帝名也。伏侯古今注曰。炟之字曰著。按許書本不書其篆。但曰上諱。後人補書之。次於此者、尊上也。玉篇曰。爆也。廣韵曰。火起也。其字从火、旦聲。當割切。十四十五部。"}]},"𤈦":{"expl":"火也。从火尾聲。《詩》曰：“王室如𤈦。”","rad":"火","fq":"許偉切","vol":"10","py":"huǐ","duan":[{"e":"火也。从火。尾聲。","n":"許偉切。十五部。"}]},"燬":{"expl":"火也。从火毀聲。《春秋傳》曰：“衞矦燬。”","rad":"火","fq":"許偉切","vol":"10","py":"huǐ","duan":[{"e":"火也。从火。毀聲。春秋傳曰。衞侯燬。","n":"許偉切。按此篆許所本無。當刪。"}]},"燹":{"expl":"火也。从火豩聲。","rad":"火","fq":"穌典切","vol":"10","py":"xiǎn","duan":[{"e":"火也。","n":"韵會引字林曰。逆燒也。"}]},"焌":{"expl":"然火也。从火夋聲。《周禮》曰：“遂䶴其焌。”焌火在前，以焞焯龜。","rad":"火","fq":"子寸切","vol":"10","py":"jùn","duan":[{"e":"然火也。","n":"以火燒物曰然。"}]},"尞":{"expl":"柴祭天也。从火从眘。眘，古文愼字。祭天所以愼也。","rad":"火","fq":"力照切","vol":"10","py":"liào","duan":[{"e":"祡祭天也。","n":"示部祡下曰。燒柴尞祭天也。是祡尞二篆爲轉注也。燒柴而祭謂之祡。亦謂之尞。亦謂之？。木部曰。？、祡祭天神。周禮？燎字當作？尞。凡祡尞作柴燎者皆誤字。"}]},"然":{"expl":"燒也。从火肰聲。","rad":"火","fq":"如延切","vol":"10","py":"rán","duan":[{"e":"燒也。","n":"通叚爲語䛐。訓爲如此。爾之轉語也。"}]},"蓱":{"expl":"苹也。从艸洴聲。","rad":"艸","fq":"薄經切","vol":"01","py":"pínɡ","duan":[{"e":"苹也。","n":"此與前苹字互訓。而不類廁者、以字體篆籒別之也。小正於七月言苹生。月令於三月言生蓱。郭璞云。江東謂之薸。"}]},"爇":{"expl":"燒也。从火蓺聲。《春秋傳》曰：“爇僖負覉。”","rad":"火","fq":"如劣切","vol":"10","py":"ruò","duan":[{"e":"燒也。从火。蓺聲。","n":"徐鉉等曰。說文無蓺字。當从火、从艸、𤍽省聲。按埶卽聲。不必云𤍽省。如劣切。十五部。"}]},"燔":{"expl":"爇也。从火番聲。","rad":"火","fq":"附袁切","vol":"10","py":"fán","duan":[{"e":"𤑔也。","n":"按許㸋與燔字別。㸋者、宗廟火炙肉也。此因一从火一从炙而別之。毛於瓠葉傳曰。加火曰燔。於生民傳曰。傅火曰燔。古文多作燔。不分別也。"}]},"燒":{"expl":"爇也。从火堯聲。","rad":"火","fq":"式昭切","vol":"10","py":"shāo","duan":[{"e":"𤑔也。","n":"二篆爲轉注。"}]},"烈":{"expl":"火猛也。从火𠛱聲。","rad":"火","fq":"良嶭切","vol":"10","py":"liè","duan":[{"e":"火猛也。","n":"大雅曰。載燔載烈。傳曰。傅火曰燔。貫之加于火曰烈。商頌曰。如火烈烈。引伸爲光也、業也。又方言曰。餘也。按烈訓餘者、盛則必盡。盡則必有所餘也。又鄭風。火烈具舉。傳曰。烈、列也。此謂烈卽列之叚借字。列者、古迾字也。"}]},"炪":{"expl":"火光也。从火出聲。《商書》曰：“予亦炪謀。”讀若巧拙之拙。","rad":"火","fq":"職悅切","vol":"10","py":"zhuō","duan":[{"e":"火光也。","n":"類篇作火不光。集韵六術曰。炪爩、煙皃。類篇同。又九迄曰。炪爩、煙出也。煙盛則光微。此葢與上火猛作反對語。"}]},"熚":{"expl":"熚𤒓，火皃。从火畢聲。","rad":"火","fq":"卑吉切","vol":"10","py":"bì","duan":[{"e":"熚𤒓、火皃。","n":"熚？曡韵字。如水部之畢沸。"}]},"𤒓":{"expl":"熚𤒓也。从火𢨋聲。𢨋，籒文悖字。","rad":"火","fq":"敷勿切","vol":"10","py":"fú","duan":[{"e":"熚𤒓也。","n":"玉篇云。火盛皃。廣韵云。鬼火。"}]},"烝":{"expl":"火气上行也。从火丞聲。","rad":"火","fq":"煑仍切","vol":"10","py":"zhēnɡ","duan":[{"e":"火气上行也。","n":"此烝之本義。引申之則烝、進也。如詩信南山甫田傳、泮水箋是也。又引申之則久也、衆也。久之義如釋詁曰烝塵也、東山傳曰烝窴也、常棣傳曰烝塡也皆是。鄭云古聲窴塡塵同。是也。衆之義如東山烝在栗薪傳、烝民傳是也。又引申之則君也。釋詁及文王有聲傳是也。又厚也。泮水傳曰烝烝、厚也是也。左傳凡下婬上謂之烝。"}]},"烰":{"expl":"烝也。从火孚聲。《詩》曰：“烝之烰烰。”","rad":"火","fq":"縛牟切","vol":"10","py":"fú","duan":[{"e":"烝也。","n":"詩生民。烝之浮浮。釋訓曰。烰烰、烝也。毛傳曰。浮浮、氣也。按爾雅不偁詩全句、故曰烝也而巳。毛釋詩全句、故曰浮浮氣也。許於此當合二古訓爲解曰烰烰、烝皃。謂火氣上行之皃也。或轉寫者刪之耳。"}]},"煦":{"expl":"烝也。一曰赤皃。一曰溫潤也。从火昫聲。","rad":"火","fq":"香句切","vol":"10","py":"xù","duan":[{"e":"烝也。","n":"方言。煦煆、熱也。乾也。吳越曰煦煆。按熱廣雅作𤑔。誤。樂記注曰。以氣曰煦。"}]},"社":{"expl":"地主也。从示、土。《春秋傳》曰：“共工之子句龍爲社神。”《周禮》：“二十五家爲社，各樹其土所宜之木。”","rad":"示","fq":"常者切","vol":"01","py":"shè","duan":[{"e":"地主也。","n":"五經異義。今孝經說曰。社者土地之主。土地廣博。不可徧敬。封五土以爲社。古左氏說。共工爲后土、爲社。許君謹案曰。春秋稱公社。今人謂社神爲社公。故知社是上公。非地祇。鄭駁之云。社祭土而主陰氣。又云。社者神地之道。謂社神但言上公。失之矣。人亦謂雷曰雷公、天曰天公。豈上公也。宗伯以血祭祭社稷五祀五嶽。社稷之神若是句龍、柱、棄。不得先五嶽而食。又引司徒五土名。又引大司樂五變而致介物及土示。土示五土之緫神。卽謂社也。六樂於五地無原隰而有土祇。則土祇與原隰同用樂也。玉裁按。許訓社爲地主。此用今孝經說。而以地主也、从示土之云、先於左氏傳。則與異義从左氏說者不符。葢許君異義先成。說文晚定。往往有說文之說早同於鄭"}]},"蓳":{"expl":"艸也。根如薺，葉如細桺，蒸食之甘。从艸堇聲。","rad":"艸","fq":"居隱切","vol":"01","py":"jǐn","duan":[{"e":"艸也。根如薺。葉如細桺。蒸食之甘。","n":"大雅蓳荼如飴傳曰。堇、菜也。夏小正。二月榮堇。采？傳曰。皆豆實也。堇、采也。内則堇荁注曰。荁、堇類也。冬用堇。夏用荁。按釋艸堇有二。齧、苦堇。詩禮之堇也。芨、堇艸。晉語之置堇於肉。卽今附子也。"}]},"熯":{"expl":"乾皃。从火，漢省聲。《詩》曰：“我孔熯矣。”","rad":"火","fq":"人善切","vol":"10","py":"hàn","duan":[{"e":"乾皃。","n":"乾讀如干。此與日部。暵同音同義。从火猶从日也。易說卦傳王肅、王弼本作燥萬物者莫熯乎火。說文日部及徐邈本作莫暵。字有分見而實同者、此類是也。"}]},"炥":{"expl":"火皃。从火弗聲。","rad":"火","fq":"普活切","vol":"10","py":"fú","duan":[{"e":"火皃。","n":"按此篆當是？之或體。"}]},"熮":{"expl":"火皃。从火翏聲。《逸周書》曰：“味辛而不熮。”","rad":"火","fq":"洛蕭切","vol":"10","py":"liáo","duan":[{"e":"火皃。从火。翏聲。","n":"烙蕭切。古音在三部。"}]},"焛":{"expl":"火皃。从火，𨳌省聲。讀若粦。","rad":"火","fq":"良刃切","vol":"10","py":"lìn","duan":[{"e":"火皃。从火。𨳏省聲。","n":"𨳏見門部。作𨳌者誤。"}]},"㷳":{"expl":"火色也。从火雁聲。讀若鴈。","rad":"火","fq":"五妟切","vol":"10","py":"yàn","duan":[{"e":"火色也。","n":"韓子。齊伐魯。索䜛鼎。以其鴈往。齊人曰。鴈也。魯人曰。眞也。鴈、葢卽㷳之叚借字。如今之作、僞古物曰燒瘢貨是也。俗作眞贗。"}]},"熲":{"expl":"火光也。从火頃聲。","rad":"火","fq":"古迥切","vol":"10","py":"jiǒnɡ","duan":[{"e":"火光也。","n":"小雅。不出於熲。傳曰。熲、光也。箋云。不得出於光明之道。按火光者、字之本義。傳不言火但言光者、其引申之義也。"}]},"爚":{"expl":"火飛也。从火龠聲。一曰爇也。","rad":"火","fq":"以灼切","vol":"10","py":"yuè","duan":[{"e":"火光也。","n":"光各本作飛。今依文𨕖琴賦景福殿賦注、玄應書卷九正。西都賦。震震爚爚。雷奔電激。震震謂雷、爚爚謂電也。李善引字指曰。儵爚、電光也。按此字或借爲燿字。或借爲鑠字。或作爍者、俗體也。"}]},"熛":{"expl":"火飛也。从火㶾聲。讀若摽。","rad":"火","fq":"甫遙切","vol":"10","py":"biāo","duan":[{"e":"火飛也。","n":"玄應引三蒼云。熛、迸火也。吕氏春秋云。突泄一熛。焚宮燒𧂐。班固答賓戯借猋爲之。"}]},"熇":{"expl":"火熱也。从火高聲。《詩》曰：“多將熇熇。”","rad":"火","fq":"火屋切","vol":"10","py":"hè","duan":[{"e":"火𤍽也。","n":"大雅板傳曰。熇熇然熾盛也。易。家人嗃嗃。鄭云。苦𤍽之意。是嗃卽熇字也。釋文曰。劉作熇熇。"}]},"烄":{"expl":"交木然也。从火交聲。","rad":"火","fq":"古巧切","vol":"10","py":"jiǎo","duan":[{"e":"交木然也。","n":"交烄曡韵。玉篇曰。交木然之。以尞祡天也。"}]},"菲":{"expl":"芴也。从艸非聲。","rad":"艸","fq":"芳尾切","vol":"01","py":"fěi","duan":[{"e":"芴也。","n":"釋艸、毛傳皆同。釋艸又云。菲、蒠菜也。"}]},"㶣":{"expl":"小熱也。从火干聲。《詩》曰：“憂心㶣㶣。”","rad":"火","fq":"直廉切","vol":"10","py":"chán","duan":[{"e":"小𤑔也。","n":"𤑔或作熱。誤。節南山釋文正義引作？。亦誤。節南山曰。憂心如惔。古本毛詩作如？。故毛傳曰。？、燔也。瓠葉傳曰。加火曰燔。許曰。燔、𤑔也。𤑔、加火也。是毛訓作𤑔。許則別之云小𤑔耳。方言、廣雅曰。？、明也。此引伸之別一義。"}]},"燋":{"expl":"所以然持火也。从火焦聲。《周禮》曰：“以明火爇燋也。”","rad":"火","fq":"即消切","vol":"10","py":"jiāo","duan":[{"e":"所㠯然持火也。","n":"持火者、人所持之火也。少儀。執燭抱燋。凡執之曰燭。未𤑔曰燋。燋卽燭也。士喪禮注曰。燎大燋。大燋卽大燭也。大燭樹於地。燭則執於手。人所持之火。以燋然之。燋者、苣爲之。卜之用燋。其一耑也。士喪禮。楚？置於燋。在龜東。注云。楚、荊也。荊？所以鑽灼龜者。燋、炬也。所以然火者也。周禮垂氏。凡卜、以明火𤑔燋。遂炊其焌契。以授卜師。杜子春云。明火、以陽燧取火於日也。按以苣然契。契卽楚？。以楚？灼龜而作其兆。是卜之次弟也。"}]},"炭":{"expl":"燒木餘也。从火，岸省聲。","rad":"火","fq":"他案切","vol":"10","py":"tàn","duan":[{"e":"燒木未灰","n":"未灰大徐作餘。"}]},"𤈩":{"expl":"束炭也。从火，差省聲。讀若齹。","rad":"火","fq":"楚宜切","vol":"10","py":"zhǎ","duan":[{"e":"束炭也。从火。𢀩省聲。讀若齹。","n":"齹齒部作？。恐誤。楚宜切。古音在十七部。"}]},"𤉧":{"expl":"交灼木也。从火，教省聲。讀若狡。","rad":"火","fq":"古巧切","vol":"10","py":"jiǎo","duan":[{"e":"交灼木也。从火。敎省聲。讀若狡。","n":"按玉篇、廣韵皆曰。？同烄。必本諸說文。不知今本說文何以析爲二。交灼之語亦不可通。上文炭下曰燒木未灰。則灰篆必上聯炭？二篆。間以？炦。決非古本。"}]},"炦":{"expl":"火气也。从火犮聲。","rad":"火","fq":"蒲撥切","vol":"10","py":"bá","duan":[{"e":"火气也。从火。犮聲。","n":"蒲撥切。十五部。"}]},"灰":{"expl":"死火餘㶳也。从火从又。又，手也。火旣滅，可以執持。","rad":"火","fq":"呼恢切","vol":"10","py":"huī","duan":[{"e":"死火餘㶳也。","n":"漢書曰。死灰獨不復然乎。"}]},"炱":{"expl":"灰，炱煤也。从火台聲。","rad":"火","fq":"徒哀切","vol":"10","py":"tái","duan":[{"e":"灰炱煤也。","n":"通俗文曰。積煙曰炱煤。玉篇曰。炱煤、煙塵也。廣韵曰。炱煤、灰入屋也。"}]},"煨":{"expl":"盆中火。从火畏聲。","rad":"火","fq":"烏灰切","vol":"10","py":"wēi","duan":[{"e":"盆中火。","n":"玉篇作盆中火𤏶。廣韵曰。𤏶者、埋物灰中令熟也。通俗文曰。𤍽灰謂之煻煨。許無煻字。今俗謂以火溫出冬閒花曰唐花。卽煻字也。"}]},"熄":{"expl":"畜火也。从火息聲。亦曰滅火。","rad":"火","fq":"相即切","vol":"10","py":"xī","duan":[{"e":"畜火也。","n":"畜當从艸。積也。熄取滋息之意。"}]},"芴":{"expl":"菲也。从艸勿聲。","rad":"艸","fq":"文弗切","vol":"01","py":"wù","duan":[{"e":"菲也。","n":"音義皆同。"}]},"烓":{"expl":"行竈也。从火圭聲。讀若冋。","rad":"火","fq":"口迥切","vol":"10","py":"wēi","duan":[{"e":"行竈也。从火。圭聲。","n":"古支淸合韵。"}]},"煁":{"expl":"烓也。从火甚聲。","rad":"火","fq":"氏任切","vol":"10","py":"chén","duan":[{"e":"烓也。","n":"小雅白華曰。樵彼桑薪。卬烘于煁。釋言曰。煁、烓也。毛傳曰。煁、烓竈也。郭璞云。今之三隅竈。按鄭箋云。桑薪、薪之善者。不以炊爨養人。反以燎於烓竈。用炤事物而巳。然則行竈非爲飲食之竈。若今火鑪。僅可炤物。自古名之曰烓。亦名之曰煁。或叚諶爲之。春秋傳碑諶字竈。知諶卽煁字也。漢書人表又作卑湛。"}]},"燀":{"expl":"炊也。从火單聲。《春秋傳》曰：“燀之以薪。”","rad":"火","fq":"充善切","vol":"10","py":"chǎn","duan":[{"e":"炊也。从火。單聲。","n":"充善切。十四部。"}]},"炊":{"expl":"爨也。从火，吹省聲。","rad":"火","fq":"昌垂切","vol":"10","py":"chuī","duan":[{"e":"爨也。","n":"爨下曰。炊也。齊謂炊也爨。"}]},"烘":{"expl":"尞也。从火共聲。《詩》曰：“卭烘于煁。”","rad":"火","fq":"呼東切","vol":"10","py":"hōnɡ","duan":[{"e":"尞也。","n":"云尞者、燔柴之義之引伸也。小雅白華。卬烘于煁。毛傳及釋言皆曰。烘、燎也。"}]},"齌":{"expl":"炊餔疾也。从火齊聲。","rad":"火","fq":"在詣切","vol":"10","py":"jì","duan":[{"e":"炊餔疾也。","n":"餔、日加申時食也。晚飯恐遲。炊之疾速。故字从火。引伸爲凡疾之用。離騷曰。反信䜛而齌怒。王注云。疾怒。"}]},"熹":{"expl":"炙也。从火喜聲。","rad":"火","fq":"許其切","vol":"10","py":"xī","duan":[{"e":"炙也。","n":"炙者、抗火炙肉也。此熹之本義。引申爲𤍽也。左傳。或叫于宋大廟曰。譆譆出出。杜曰。譆譆、熱也。此同音叚借也。又與𤌇相叚借。"}]},"煎":{"expl":"熬也。从火前聲。","rad":"火","fq":"子仙切","vol":"10","py":"jiān","duan":[{"e":"𤎅也。","n":"方言。熬、㷅、煎、㷶、鞏、火乾也。凡有汁而乾謂之煎。東齊謂之鞏。"}]},"熬":{"expl":"乾煎也。从火敖聲。","rad":"火","fq":"五牢切","vol":"10","py":"áo","duan":[{"e":"乾𤋎也。","n":"方言。𤎅、火乾也。凡以火而乾五榖之類、自山而東齊楚以往謂之𤎅。"}]},"炮":{"expl":"毛炙肉也。从火包聲。","rad":"火","fq":"薄交切","vol":"10","py":"páo","duan":[{"e":"毛炙肉也。","n":"炙肉者、貫之加於火。毛炙肉、謂肉不去毛炙之也。瓠葉傳曰。毛曰炮。加火曰燔。閟宫傳曰。毛炰豚也。周禮封人。毛炰之豚。鄭注。毛炮豚者、爓去其毛而炮之。內則注曰。炮者、以塗燒之爲名也。禮運注曰。炮、裹燒之也。按裹燒之卽內則之塗燒。鄭意詩禮言毛炮者、毛謂燎毛。炮謂裹燒。毛公則謂連毛燒之曰炮。爲許所本。六月、韓奕皆曰炰鼈。箋云。炰、以火孰之也。鼈無毛而亦曰炰。則毛與炮二事。鄭說爲長矣。炰與缹皆炮之或體也。韓奕之炰徐仙民音甫九反。大射篇注炮鼈或作缹、或作？。是知炰缹爲古今字。通俗文曰。燥煑曰缹。燥煑謂不過濡也。裹燒曰炮。燥煑亦曰炮。漢人燥煑多用缹字。缶聲包聲古音同在三部。"}]},"𧅻":{"expl":"艸也。从艸𪅀聲。","rad":"艸","fq":"呼旰切","vol":"01","py":"hàn","duan":[{"e":"艸也。从艸。𪅀聲。","n":"呼旰切。十四部。籒文作𧆚。按鳥部𪅀？一字也。而艸部䕿䕿各字。恐有誤。"}]},"𤇯":{"expl":"炮肉，以微火溫肉也。从火衣聲。","rad":"火","fq":"烏痕切","vol":"10","py":"ēn","duan":[{"e":"炮炙也。","n":"炮炙異義皆得曰？也。"}]},"𤎯":{"expl":"置魚筩中炙也。从火曾聲。","rad":"火","fq":"作滕切","vol":"10","py":"zēnɡ","duan":[{"e":"置魚筩中炙也。","n":"筩、𣃔竹也。置魚筩中而乾炙之。事與烝相類。"}]},"𤐸":{"expl":"以火乾肉。从火稫聲。","rad":"火","fq":"符逼切","vol":"10","py":"bì","duan":[{"e":"㠯火乾肉也。","n":"周禮籩人注曰。鮑者於楅室中糗榦之。出於江淮也。此當作𤐧室中𤐧乾之。漢書貨殖傳注引作於煏室乾之。可證。煏卽𤐧字。小顏不解糗字。故刪之耳。糗者、熬米麥也。引申爲凡熬之偁。語亦可通。𤐧室、漢時有此制。賈公彥云。楅土爲室。非也。陸德明云。皮逼反。與周禮、毛詩楅音福音逼不同。與師古煏音蒲北反合。然則陸本當亦作煏。今釋文乃轉寫作楅。非是。𤐧方言作？。凡以火而乾五榖之類、自山而東齊楚以往謂之熬。關西隴冀以往謂之㷅。秦晉之閒或謂之㷅。省作煏。又或作焙。而異其音。玉篇作煏。無𤐧。"}]},"爆":{"expl":"灼也。从火暴聲。","rad":"火","fq":"蒲木切","vol":"10","py":"bào","duan":[{"e":"灼也。","n":"謂火飛所灸也。"}]},"煬":{"expl":"炙燥也。从火昜聲。","rad":"火","fq":"余亮切","vol":"10","py":"yànɡ","duan":[{"e":"炙燥也。从火。昜聲。","n":"余亮切。十部。謚法。好內遠禮煬。去禮遠衆煬。"}]},"𤌍":{"expl":"灼也。从火隺聲。","rad":"火","fq":"胡沃切","vol":"10","py":"hú","duan":[{"e":"灼也。从火。隺聲。","n":"胡沃切。古音在二部。"}]},"爤":{"expl":"孰也。从火蘭聲。","rad":"火","fq":"郎旰切","vol":"10","py":"làn","duan":[{"e":"火𦏧也。","n":"此火字依節南山生民二正義補。方言。自河以北趙魏之閒火𠅩曰爛。𠅩者、食飪也。飪者、大𠅩也。𠅩則火候到矣。引伸之、凡淹久不堅皆曰爛。𠅩則可燦然陳列。故又引伸爲粲爛。"}]},"𤓒":{"expl":"爛也。从火靡聲。","rad":"火","fq":"靡爲切","vol":"10","py":"mí","duan":[{"e":"爤也。","n":"古多叚糜爲之。糜訓糝。㸏訓爛。義各有當矣。孟子。糜爛其民而戰之。文𨕖答客難。至則糜耳。皆用叚借字也。"}]},"㷉":{"expl":"从上案下也。从𡰥；又持火，以尉申繒也。","rad":"火","fq":"於胃切","vol":"10","py":"wèi","duan":[{"e":"从上按下也。","n":"按者、抑也。百官公卿表應劭注曰。自上安下曰尉。武官悉以爲偁。張釋之傳曰。廷尉、天下之平也。車千秋傳。尉安黎庶。師古曰。慰安之字本無心。後俗所加。"}]},"𤒅":{"expl":"灼龜不兆也。从火从龜。《春秋傳》曰：“龜𤒅不兆。”讀若焦。","rad":"火","fq":"即消切","vol":"10","py":"jiāo","duan":[{"e":"灼龜不兆也。从龜火。","n":"从韵會。此會意也。"}]},"𦼉":{"expl":"薍也。从艸萑聲。","rad":"艸","fq":"胡官切","vol":"01","py":"huán","duan":[{"e":"薍也。","n":"薍之已秀者也。薍已見前。此以篆籒分別異處。"}]},"灸":{"expl":"灼也。从火久聲。","rad":"火","fq":"舉友切","vol":"10","py":"jiǔ","duan":[{"e":"灼也。","n":"今以艾約體曰灸。是其一耑也。引伸凡柱？曰灸。考工記廬人。灸諸牆。注云。灸猶塞也。以柱兩牆之閒。輓而內之。本末勝負可知也。古文作久。許引周禮久諸牆。士喪禮。皆木桁久之。注云。久當爲灸。灸謂以葢案塞其口。按久灸皆取附箸相拒之意。凡附箸相拒曰久。用火則曰灸。鄭用方言。許說造字本意。"}]},"灼":{"expl":"炙也。从火勺聲。","rad":"火","fq":"之若切","vol":"10","py":"zhuó","duan":[{"e":"灸也。","n":"灸各本作炙。誤。今正。此與上灸篆爲轉注。炙謂炮肉。灼謂凡物以火附箸之。如以楚焞柱龜曰灼龜。其一耑也。七諫注曰。㸃、汚也。灼、灸也。猶身有病、人㸃灸之。醫書以艾灸體謂之壯。壯者、灼之語轉也。淮南注曰。然也。廣雅曰。爇也。素問注曰。燒也。其義皆相近。几訓灼爲明者、皆由經傳叚灼爲焯。桃夭傳曰灼灼、華之盛也。謂灼爲焯之叚借字也。周書。焯見三有俊心。今本作灼見。"}]},"煉":{"expl":"鑠治金也。从火柬聲。","rad":"火","fq":"郎電切","vol":"10","py":"liàn","duan":[{"e":"鑠治金也。","n":"治毛本作冶。誤。今依宋本。鑠治者、鑠而治之。愈消則愈精。高注戰國策曰。練、濯治絲也。正與此文法同。金部曰。鍊、治金也。此加鑠者、正爲字从火。"}]},"燭":{"expl":"庭燎，火燭也。从火蜀聲。","rad":"火","fq":"之欲切","vol":"10","py":"zhú","duan":[{"e":"庭燎、大燭也。","n":"燎當作尞。大各本譌作火。今正。若韵會庭燎燭也尤善。小雅毛傳曰。庭燎、大燭也。燕禮。宵則庶子執燭於阼階上。司宫執燭於西階上。甸人執大燭於庭。閽人爲大燭於門外。周禮司烜氏。凡邦之大事。共墳燭、庭燎。鄭云。墳、大也。郊特牲曰。庭燎之百。由齊桓公始也。鄭云。庭燎之差。公葢五十。侯伯子男皆三十。文出大戴禮。按未爇曰燋。執之曰燭。在地曰燎。廣設之則曰大燭、曰庭燎。大燭與庭燎非有二也。周禮絫言墳燭、庭燎。故鄭注以門外門内別之。周禮故書作蕡燭。先鄭云。蕡燭、麻燭也。賈公彥曰。古者未有麻燭。故鄭從墳訓大。古庭燎、依慕容所爲。以葦爲中心。以布纏之。飴蜜灌之。若今蠟燭。玉裁謂。古燭葢以薪蒸爲之。麻蒸亦其一端。麻蒸、"}]},"熜":{"expl":"然麻蒸也。从火悤聲。","rad":"火","fq":"作孔切","vol":"10","py":"zǒnɡ","duan":[{"e":"然麻蒸也。","n":"麻蒸、析麻中榦也。亦曰菆。菆一作黀。古者燭多用葦。鄭注周禮曰。燋、炬也。許曰。苣、束葦燒之也。亦用麻。故先鄭注周禮曰。蕡燭、麻燭也。先鄭意蕡卽？字。鄭注士喪禮曰。燭用蒸。蒸卽謂麻榦。弟子職曰。䒱閒容蒸。"}]},"灺":{"expl":"燭㶳也。从火也聲。","rad":"火","fq":"徐野切","vol":"10","py":"xiè","duan":[{"e":"燭㶳也。","n":"曲禮所謂燭跋。弟子職所謂燭？。跋者、謂近手皆餘。？者、謂燒過之燼。"}]},"㶳":{"expl":"火餘也。从火聿聲。一曰薪也。","rad":"火","fq":"徐刃切","vol":"10","py":"jìn","duan":[{"e":"火之餘木也。","n":"各本作火餘也。今依唐初玄應本。火之餘木曰㶳。死火之㶳曰灰。引伸爲凡餘之偁。左傳。收合餘燼。大雅箋。災餘曰燼。方言。藎、餘也。周鄭之閒曰藎。或曰孑。藎者、叚借字也。"}]},"焠":{"expl":"堅刀刃也。从火卒聲。","rad":"火","fq":"七內切","vol":"10","py":"cuì","duan":[{"e":"堅刀刃也。","n":"王裦傳。淸水焠其鋒。郭樸三倉解詁曰。焠、作刀鋻也。焠子妹切。鋻工練切。師古云。焠謂燒而內水中以堅之也。按火而堅之曰焠。與水部淬義別。文𨕖譌作淬。非也。天官書曰。火與水合曰焠。"}]},"煣":{"expl":"屈申木也。从火、柔，柔亦聲。","rad":"火","fq":"人久切","vol":"10","py":"rǒu","duan":[{"e":"屈申木也。","n":"謂曲直之也。今𣪠辭傳、考工記皆作揉。葢非古也。手部無揉字。漢書食貨志。煣木爲耒。"}]},"燓":{"expl":"燒田也。从火、棥，棥亦聲。","rad":"火","fq":"附袁切","vol":"10","py":"fán","duan":[{"e":"燒田也。从火林。","n":"各本篆作樊。解作从火棥。棥亦聲。今正。按玉篇、廣韵有焚無燓。焚符分切。至集韵、類篇乃合焚燓爲一字。而集韵廿二元固單出燓字、符袁切。竊謂棥聲在十四部。焚聲在十三部。份古文作彬。解云焚省聲。是許書當有焚字。況經傳焚字不可枚舉。而未見有燓。知火部燓卽焚之譌。玄應書引說文焚、燒田也。字从火。燒林意也。凡四見。然則唐初本有焚無燓。不獨篇、韵可證也。"}]},"葦":{"expl":"大葭也。从艸韋聲。","rad":"艸","fq":"于鬼切","vol":"01","py":"wěi","duan":[{"e":"大葭也。","n":"夏小正曰。未秀則不爲？葦。秀然後爲？葦。毛傳曰。八月薍爲？、葭爲葦。許云大葭、猶言葭之已秀者。"}]},"熑":{"expl":"火煣車網絕也。从火兼聲。《周禮》曰：“煣牙，外不熑。”","rad":"火","fq":"力鹽切","vol":"10","py":"lián","duan":[{"e":"火煣車网絕也。","n":"此爲考工記作注也。輪人曰。凡揉牙。外不廉而內不挫、旁不腫。謂之用火之善。注曰。廉、絕也。挫、折也。腫、瘣也。按廉者、熑之叚借。絕謂火絕。記文之外謂火。內謂正當火處。旁謂不當火處。煣之不善、則當火處橈減、而不當火處起。畏此二病。或絕火而更煣。假令火未嘗少絕而無此二病、是眞善用火也。車网卽牙也。牙木部作枒。玉篇曰。燫、熪火不絕。此義與火絕相輔。"}]},"燎":{"expl":"放火也。从火尞聲。","rad":"火","fq":"力小切","vol":"10","py":"liǎo","duan":[{"e":"放火也。","n":"此與尞義別。盤庚曰。若火之燎于原。大雅曰。瑟彼柞棫。民所燎矣。箋云。人熂燎除其旁草。小雅。燎之方揚。箋云。火田曰燎。玄應引說文有火田爲燎。王制曰。昆蟲未蟄。不以火田。"}]},"𤐫":{"expl":"火飛也。从火，纳與𠨧同意。","rad":"火","fq":"方昭切","vol":"10","py":"biāo","duan":[{"e":"火飛也。","n":"此與熛音義皆同。玉篇、廣韵亦然。引申爲凡輕銳之偁。周禮草人。輕𤐫用犬。注謂地之輕脃者也。漢有票姚校尉、票騎將軍。票姚、荀悅漢紀作票鷂。服䖍音飄搖。小顏二字皆去聲。非古也。平聲者古音。去聲者今音耳。今俗閒信券曰票。亦尙存古義。凡从票爲聲者、多取會意。"}]},"㷮":{"expl":"焦也。从火曹聲。","rad":"火","fq":"作曹切","vol":"10","py":"zāo","duan":[{"e":"𤓪也。","n":"今俗語謂燒壞曰㷮。凡物壞亦曰㷮。"}]},"𤓪":{"expl":"火所傷也。从火雥聲。","rad":"火","fq":"即消切","vol":"10","py":"jiāo","duan":[{"e":"火所傷也。从火。雥聲。","n":"卽消切。二部。按廣韵雥徂合切。玉篇才帀走合二切。今以許書焦字从雥聲訂之。則知雥之古音讀如揫、如椒。雧者會意字。非用雥聲。後人昧其本音。乃以襍字之反語爲雥之反語。非也。戴氏侗乃疑作㸈乃得聲矣。"}]},"烖":{"expl":"天火曰烖。从火𢦏聲。","rad":"火","fq":"祖才切","vol":"10","py":"zāi","duan":[{"e":"天火曰烖。","n":"春秋宣十六年。夏。成周宣謝火。左傳曰。人火之也。凡火、人火曰火。天火曰災。按經多言災。惟此言火耳。引申爲凡害之偁。十五年傳曰。天反時爲災。地反物爲妖。民反德爲亂。亂則妖災生。"}]},"煙":{"expl":"火气也。从火垔聲。","rad":"火","fq":"烏前切","vol":"10","py":"yān","duan":[{"e":"火气也。","n":"陸璣連珠曰。火壯則煙㣲。"}]},"焆":{"expl":"焆焆，煙皃。从火肙聲。","rad":"火","fq":"因悅切","vol":"10","py":"yè","duan":[{"e":"焆焆、煙皃。从火。䏍聲。","n":"因悅切。古音在十四部。"}]},"煴":{"expl":"鬱煙也。从火昷聲。","rad":"火","fq":"於云切","vol":"10","py":"yūn","duan":[{"e":"鬱煙也。","n":"鬱當作？。？與煴聲義皆同。煙煴猶壹？也。"}]},"𤈥":{"expl":"望火皃。从火皀聲。讀若馰顙之馰。","rad":"火","fq":"都歴切","vol":"10","py":"dí","duan":[{"e":"望見火皃。","n":"依篇、韵補見字。？然猶旳然也。"}]},"葭":{"expl":"葦之未秀者。从艸叚聲。","rad":"艸","fq":"古牙切","vol":"01","py":"jiā","duan":[{"e":"葦之未秀者。从艸。叚聲。","n":"古牙切。古音在五部。籒文作？。"}]},"燂":{"expl":"火熱也。从火覃聲。","rad":"火","fq":"火甘切","vol":"10","py":"tán","duan":[{"e":"火熱也。","n":"廣雅。燂、煗也。攷工記弓人。撟角、欲？於火而無燂。注云。燂、炙爛也。故書燂或作朕。"}]},"焞":{"expl":"明也。从火𦎫聲。《春秋傳》曰：“焞燿天地。”","rad":"火","fq":"他昆切","vol":"10","py":"tūn","duan":[{"e":"朙也。","n":"鄭語。史伯曰。黎爲高辛氏火正。以淳燿敦大。天明地德。光照四海。故命之曰祝融。崔瑗河閒相張平子碑云。遷大史令。實掌重黎厤紀之度。亦能焞燿敦大。天明地德。光照有漢。今本國語作淳。漢碑作焞、與許所據合。韋云。淳、大也。燿、明也。下文云。敦大則焞燿。自皆當訓明。士喪禮楚焞。所以鑽灼龜者。楚、荊也。焞、葢亦取明火之意。引申之又訓盛。采芑傳曰。焞焞、盛也。漢時有敦煌郡。應劭地理風俗記曰。敦、大也。煌、盛也。唐時乃作燉煌。見元和郡縣志。燉乃唐人俗字。非焞之異體也。"}]},"炳":{"expl":"明也。从火丙聲。","rad":"火","fq":"兵永切","vol":"10","py":"bǐnɡ","duan":[{"e":"朙也。","n":"易曰。大人虎變。其文炳也。"}]},"焯":{"expl":"明也。从火卓聲。《周書》曰：“焯見三有俊心。”","rad":"火","fq":"之若切","vol":"10","py":"zhuó","duan":[{"e":"朙也。从火。卓聲。","n":"之若切。二部。"}]},"照":{"expl":"明也。从火昭聲。","rad":"火","fq":"之少切","vol":"10","py":"zhào","duan":[{"e":"朙也。","n":"與昭音義同。"}]},"煒":{"expl":"盛赤也。从火韋聲。《詩》曰：“彤管有煒。”","rad":"火","fq":"于鬼切","vol":"10","py":"wěi","duan":[{"e":"盛朙皃也。","n":"各本作盛赤也。今依玄應書正。詩靜女。彤管有煒。傳曰。煒、赤皃。此毛就彤訓之。盛明之一耑也。王莽傳。靑煒登平。赤煒頌平。白煒𧰼平。玄煒和平。服䖍曰。煒、音暉。如淳曰。靑煒、靑氣之光輝也。"}]},"㶴":{"expl":"盛火也。从火从多。","rad":"火","fq":"昌氏切","vol":"10","py":"chǐ","duan":[{"e":"盛火也。","n":"凡言盛之字从多。"}]},"熠":{"expl":"盛光也。从火習聲。《詩》曰：“熠熠宵行。”","rad":"火","fq":"羊入切","vol":"10","py":"yì","duan":[{"e":"盛光也。","n":"詩。熠燿宵行。傳曰。熠燿、粦也。粦、熒火也。又倉庚于飛。熠燿其羽。箋云。羽鮮明也。"}]},"煜":{"expl":"熠也。从火昱聲。","rad":"火","fq":"余六切","vol":"10","py":"yù","duan":[{"e":"燿也。","n":"此以雙聲爲訓。"}]},"燿":{"expl":"照也。从火翟聲。","rad":"火","fq":"弋笑切","vol":"10","py":"yào","duan":[{"e":"照也。从火。翟聲。","n":"弋𥬇切。二部。"}]},"萊":{"expl":"蔓華也。从艸來聲。","rad":"艸","fq":"洛哀切","vol":"01","py":"lái","duan":[{"e":"蔓華也。","n":"今釋艸作釐、蔓華。許所見作萊。小雅北山有萊之萊。未知卽此與不也。經典多用爲艸萊字。"}]},"煇":{"expl":"光也。从火軍聲。","rad":"火","fq":"況韋切","vol":"10","py":"huī","duan":[{"e":"光也。","n":"小雅庭燎傳曰。煇、光也。日部曰。暉、光也。二字音義皆同。煇與光互訓。如易𧰼傳君子之光、其暉吉也是也。析言之則煇光有別、如管輅荅劉邠云不同之名。朝旦爲輝。日中爲光。玉藻揖私朝、煇如也。登車則有光是也。史記。𣃔戚夫人手足。去眼煇耳。此叚煇爲熏也。"}]},"煌":{"expl":"煌，煇也。从火皇聲。","rad":"火","fq":"胡光切","vol":"10","py":"huánɡ","duan":[{"e":"煌煌、煇也。","n":"此依韵會本。今大、小徐本各奪一字。非也。皇皇者華傳曰。皇皇猶煌煌也。朱芾斯皇傳曰。皇猶煌煌也。"}]},"焜":{"expl":"煌也。从火昆聲。","rad":"火","fq":"孤本切","vol":"10","py":"kūn","duan":[{"e":"煌也。","n":"甘泉賦。樵蒸焜上。李善引字書焜燿火皃。"}]},"炯":{"expl":"光也。从火冋聲。","rad":"火","fq":"古迥切","vol":"10","py":"jiǒnɡ","duan":[{"e":"光也。从火。冋聲。","n":"古迥切。十一部。"}]},"爗":{"expl":"盛也。从火曅聲。《詩》曰：“爗爗震電。”","rad":"火","fq":"筠輒切","vol":"10","py":"yè","duan":[{"e":"盛也。","n":"十月之交曰。𤑼𤑼震電。傳曰。𤑼𤑼、震電皃。按凡光之盛曰𤑼。"}]},"爓":{"expl":"火門也。从火閻聲。","rad":"火","fq":"余廉切","vol":"10","py":"yàn","duan":[{"e":"火爓也。","n":"各本作火門也。門乃爓之壞字耳。今正。文𨕖蜀都賦。高爓飛煽於天垂。善引說文。爓、火焰也。音豔。焰卽爓之省。六書故引唐本說文。火爓爓也。較李善所據多一爓字。今人云光燄者、作此字爲正。古多叚炎爲之。如左傳其氣炎以取之、司馬相如傳末光絕炎、楊雄傳景炎炘炘皆是。又郊祀歌。長離前掞光耀明。晉灼曰。掞卽光炎字。亦叚借也。爓與燄篆義別。"}]},"炫":{"expl":"燿燿也。从火玄聲。","rad":"火","fq":"胡畎切","vol":"10","py":"xuàn","duan":[{"e":"爓燿也。","n":"爓燿謂光爓燿明也。封禪文叚玄爲之。"}]},"光":{"expl":"明也。从火在人上，光明意也。","rad":"火","fq":"古皇切","vol":"10","py":"ɡuānɡ","duan":[{"e":"朙也。","n":"左傳周內史釋易觀國之光曰。光、逗遠而自他有燿者也。"}]},"熱":{"expl":"溫也。从火埶聲。","rad":"火","fq":"如列切","vol":"10","py":"rè","duan":[{"e":"𥁕也。","n":"𥁕各本作溫。今正。許意溫爲水名。凡𥁕煗字皆當作𥁕。𥁕、仁也。从皿飼囚。引申之則爲𥁕煖。毛詩傳曰。蕰蕰而暑。爞爞而𤍽。"}]},"熾":{"expl":"盛也。从火戠聲。","rad":"火","fq":"昌志切","vol":"10","py":"chì","duan":[{"e":"盛也。从火。戠聲。","n":"昌志切。一部。"}]},"荔":{"expl":"艸也。似蒲而小，根可作㕞。从艸劦聲。","rad":"艸","fq":"郎計切","vol":"01","py":"lì","duan":[{"e":"艸也。佀蒲而小。根可作刷。","n":"月令。十一月、荔挺出。鄭云。荔挺、馬薤也。鄭以荔挺爲艸名。蔡邕章句云。荔佀挺。高注吕覽云。荔艸挺出。則以挺下屬。歙程氏瑶田曰。荔、今北方束其根以刮鍋。李時珍以馬帚之荓當之。誤也。按刷各本作㕞。今依顏氏家訓正。上文曰䓛、刷也。"}]},"燠":{"expl":"熱在中也。从火奥聲。","rad":"火","fq":"烏到切","vol":"10","py":"ào","duan":[{"e":"𤍽在中也。","n":"洪範庶徵曰燠、曰寒。古多叚奥爲之。小雅。日月方奥。傳曰。奥、煖也。"}]},"煖":{"expl":"溫也。从火爰聲。","rad":"火","fq":"況袁切","vol":"10","py":"xuān","duan":[{"e":"𥁕也。","n":"𥁕各本作温。今正。說卦傳。日以晅之。晅亦作烜。葢卽煖字也。"}]},"煗":{"expl":"溫也。从火耎聲。","rad":"火","fq":"乃管切","vol":"10","py":"nuǎn","duan":[{"e":"𥁕也。","n":"𥁕各本作温。今正。"}]},"炅":{"expl":"見也。从火、日。","rad":"火","fq":"古迥切","vol":"10","py":"jiǒnɡ","duan":[{"e":"見也。从火日。","n":"古迴切。按此篆義不可知。廣韵作光也。似近之。从日火、亦不可曉。葢後人羼入。如西部有䙵之比。廣韵十二霽曰。後漢大尉陳球碑有城陽炅橫。漢末被誅。有四子。一姓炅。一姓昋。一姓桂。一姓炔。四字皆九畫。集韵。桂氏譜曰。桂貞爲秦博士。始皇阬儒。改姓昋。其孫改爲炅。弟四子改爲炔。是則有肊製炅爲姓者。恥其不古。羼入許書。非無證也。廣韵云四字皆九畫。按桂字十畫。其三字皆八畫。葢六朝木旁多作才。圭作五畫。然則當云四字皆八畫也。"}]},"炕":{"expl":"乾也。从火亢聲。","rad":"火","fq":"苦浪切","vol":"10","py":"kànɡ","duan":[{"e":"乾也。","n":"謂以火乾之也。五行志曰。君炕陽而暴虐。師古曰。凡言炕陽者、枯涸之意。謂無惠澤於下也。釋木曰。守宫槐、葉晝聶宵炕。郭云。晝日聶合而夜炕布。"}]},"燥":{"expl":"乾也。从火喿聲。","rad":"火","fq":"穌到切","vol":"10","py":"zào","duan":[{"e":"乾也。","n":"易曰。水流溼。火就燥。"}]},"𤇳":{"expl":"滅也。从火、戌。火死於戌，陽氣至戌而盡。《詩》曰：“赫赫宗周，褒似𤇳之。”","rad":"火","fq":"許劣切","vol":"10","py":"miè","duan":[{"e":"滅也。","n":"小雅正月曰。赫赫宗周。褎姒烕之。傳曰。烕、㓕也。"}]},"焅":{"expl":"旱气也。从火告聲。","rad":"火","fq":"苦沃切","vol":"10","py":"kù","duan":[{"e":"旱气也。","n":"與酷音義略同。"}]},"燽":{"expl":"溥覆照也。从火壽聲。","rad":"火","fq":"徒到切","vol":"10","py":"dào","duan":[{"e":"溥覆照也。","n":"中庸曰。辟如天地之無不持載。無不覆幬。注云。幬或作燾。按左傳亦云。如天之無不幬。杜注。幬、覆也。葢幬是叚借字。？訓襌帳。帳主覆也。？从火。故訓爲溥覆照。周禮司几筵注。敦讀曰燾。燾、覆也。"}]},"爟":{"expl":"取火於日官名，舉火曰爟。《周禮》曰：“司爟，掌行火之政令。”从火雚聲。","rad":"火","fq":"古玩切","vol":"10","py":"ɡuàn","duan":[{"e":"取火於日官名。","n":"日當作木。周禮夏官司爟。掌行火之政令。四時變國火。以救時疾。季春出火。季秋內火。鄭司農說以鄹子曰。春取榆桺之火。夏取棗杏之火。季夏取桑柘之火。秋取柞楢之火。冬取槐檀之火。是取火於木之事也。若秋官司烜氏。以夫遂取明火於日。以鑒取明水於月。與司爟所職不同。淮南子氾論訓注。爟火、取火於日之官也。引周禮司爟云云。是高注亦當爲譌字。"}]},"蒙":{"expl":"王女也。从艸冡聲。","rad":"艸","fq":"莫紅切","vol":"01","py":"ménɡ","duan":[{"e":"王女也。","n":"王或作玉。誤。釋艸云。蒙、王女。又云。唐蒙、女蘿。女蘿、兔絲。孫炎曰。別三名。按衞風爰采唐矣傳云。唐蒙、菜名。小雅蔦與女蘿傳云。女蘿、兔絲松蘿也。疑爾雅、毛傳此二條皆不謂一物。"}]},"㷭":{"expl":"燧，𠊱表也。邊有警則舉火。从火逢聲。","rad":"火","fq":"𢾭容切","vol":"10","py":"fēnɡ","duan":[{"e":"㷭𤎩、","n":"各本無㷭字。今依文𨕖注補。𤎩各本作燧。今正。"}]},"爝":{"expl":"苣火，祓也。从火爵聲。呂不韋曰：湯得伊尹，爝以爟火，釁以犧豭。","rad":"火","fq":"子肖切","vol":"10","py":"jiào","duan":[{"e":"苣火祓也。","n":"苣、束葦燒之也。祓、除惡之祭也。吕覽本味篇。湯得伊尹。祓之於廟。爝以爟火。贊能篇。桓公迎管仲。祓以爟火。"}]},"熭":{"expl":"暴乾火也。从火彗聲。","rad":"火","fq":"于歲切","vol":"10","py":"wèi","duan":[{"e":"㬥乾也。","n":"也上大徐衍火字。乾音干。賈誼傳曰。日中必熭。顏之推云。此語出大公六韜。言日中時、必須㬥曬。不爾者失其時也。㬥與㬥疾字異。"}]},"熙":{"expl":"燥也。从火巸聲。","rad":"火","fq":"許其切","vol":"10","py":"xī","duan":[{"e":"燥也。","n":"文𨕖劉琨贈盧諶詩注引此。下有謂㬥燥也四字。蓋庾儼黙注語。釋詁又曰。熙、興也。周語叔向釋昊天有成命之詩曰。緝、明。熙、廣也。毛傳本之。箋據釋詁熙、光也。云廣當爲光。按文王傳曰。緝熙、光明也。敬之傳曰。光、廣也。是古光廣義通。燥者、熙之本義。又訓興、訓光者、引申之義也。"}]},"爞":{"expl":"旱气也。从火蟲聲。","rad":"火","fq":"直弓切","vol":"10","py":"chónɡ","duan":[]},"煽":{"expl":"熾盛也。从火扇聲。","rad":"火","fq":"式戰切","vol":"10","py":"shàn","duan":[]},"烙":{"expl":"灼也。从火各聲。","rad":"火","fq":"盧各切","vol":"10","py":"luò","duan":[]},"爍":{"expl":"灼爍，光也。从火樂聲。","rad":"火","fq":"書藥切","vol":"10","py":"shuò","duan":[]},"燦":{"expl":"燦爤，明瀞皃。从火粲聲。","rad":"火","fq":"倉案切","vol":"10","py":"càn","duan":[]},"煥":{"expl":"火光也。从火奐聲。","rad":"火","fq":"呼貫切","vol":"10","py":"huàn","duan":[]},"禓":{"expl":"道上祭。从示昜聲。","rad":"示","fq":"與章切","vol":"01","py":"yánɡ","duan":[{"e":"道上祭。","n":"史游急就篇曰。謁禓塞。王伯厚曰。周禮注。衍祭、羨之道中。如今祭殤。"}]},"薻":{"expl":"水艸也。从艸从水，巢聲。《詩》曰：“于以采薻？”","rad":"艸","fq":"子皓切","vol":"01","py":"zǎo","duan":[{"e":"水艸也。","n":"今水中莖大如釵股、葉蒙茸深綠色、莖寸許有節者是。左氏謂之薀藻。"}]},"炎":{"expl":"火光上也。从重火。凡炎之屬皆从炎。","rad":"炎","fq":"于廉切","vol":"10","py":"yán","duan":[{"e":"火光上也。","n":"洪範曰。火曰炎上。其本義也。雲漢傳曰。炎炎、熱氣也。大田傳曰。炎、火盛陽也。皆引申之義也。"}]},"燄":{"expl":"火行微燄燄也。从炎臽聲。","rad":"炎","fq":"以冉切","vol":"10","py":"yàn","duan":[{"e":"火行微燄燄也。","n":"微當作？。雒誥曰。無若火始燄燄。廣韵曰。燄、火初著也。左傳注引書作燄燄。漢書梅福傳引書作庸庸。此篆與光爓字別。焰者、俗爓字也。"}]},"𦧡":{"expl":"火光也。从炎舌聲。","rad":"炎","fq":"以冉切","vol":"10","py":"yǎn","duan":[]},"𤎭":{"expl":"㑴火也。从炎㐭聲。讀若桑葚之葚。","rad":"炎","fq":"力荏切","vol":"10","py":"lǐn","duan":[{"e":"㑴火也。","n":"曡韵爲訓也。近火者有畏意。"}]},"煔":{"expl":"火行也。从炎占聲。","rad":"炎","fq":"舒贍切","vol":"10","py":"shǎn","duan":[{"e":"火行也。","n":"廣韵也作皃。"}]},"燅":{"expl":"於湯中爚肉。从炎，从熱省。","rad":"炎","fq":"徐鹽切","vol":"10","py":"xián","duan":[{"e":"於湯中爚肉也。","n":"爚當作？。玉篇、韵會作瀹。則俗用字也。？者、內。肉及菜湯中薄出之。瀹、漬也。禮有司徹。乃燅尸俎。鄭注。燅、溫也。古文燅皆作尋。記或作尋。春秋傳。若可尋也。亦可寒也。按燅者正字。尋者同音叚借字。云記或作尋者、郊特牲血腥爓祭注云爓或爲尋是也。爓亦叚借字也。所引春秋傳哀公十二年左傳文。賈注云。尋、溫也。服注云。尋之言重也、溫也。寒、歇也。郊特牲之注云爓或爲尋。見有司徹疏。今本禮記作爓或爲䐲。誤也。有司徹注中尋字、唐人譌作燖。亦非也。論語注。溫、尋也。又中庸溫故而知新注曰。溫讀如尋溫之溫。尋本皆無火旁。"}]},"𤏻":{"expl":"大熟也。从又持炎、辛。辛者，物熟味也。","rad":"炎","fq":"蘇俠切","vol":"10","py":"xiè","duan":[{"e":"大𦏧也。","n":"此與又部燮篆義別。"}]},"粦":{"expl":"兵死及牛馬之血爲粦。粦，鬼火也。从炎、舛。","rad":"炎","fq":"良刃切","vol":"10","py":"lín","duan":[{"e":"兵死及牛馬之血爲㷠。","n":"列子天瑞曰。馬血之爲轉鄰也。人血之爲野火也。張注。此皆一形之內自變化也。淮南氾論訓曰。老槐生火。久血爲燐。許注。兵死之士血爲鬼火。見詩正義。高注。血精在地暴露百日則爲燐。遥望炯炯若然火也。又說林訓曰。抽簪招燐。有何爲驚。高注。燐血似野火。招之。應聲而至。血灑汙人。以簪招則不至。博物志。戰鬥死亡之處有人馬血。積年化爲粦。粦著地入草木皆如霜露不可見。有觸者。著人體便有光。拂拭便散無數。又有吒聲如煼豆。"}]},"黑":{"expl":"火所熏之色也。从炎，上出𡆧。𡆧，古窻字。凡黑之屬皆从黑。","rad":"黑","fq":"呼北切","vol":"10","py":"hēi","duan":[{"e":"北方色也。","n":"四字各本無。依青赤白三部下云東方色、南方色、西方色。黃下亦云地之色。則當有此四字明矣。今補。"}]},"黸":{"expl":"齊謂黑爲黸。从黑盧聲。","rad":"黑","fq":"洛乎切","vol":"10","py":"lú","duan":[{"e":"齊謂黑爲黸。","n":"經傳或借盧爲之。或借旅爲之。皆同音叚借也。旅弓旅矢、見尙書左傳。俗字改爲？。"}]},"菉":{"expl":"王芻也。从艸录聲。《詩》曰：“菉竹猗猗。”","rad":"艸","fq":"力玉切","vol":"01","py":"lù","duan":[{"e":"王芻也。","n":"見釋艸、毛傳。"}]},"䵳":{"expl":"沃黑色。从黑會聲。","rad":"黑","fq":"惡外切","vol":"10","py":"wèi","duan":[{"e":"𣵽黑色也。","n":"𣵽引申之義爲肥美。沃黑者、光潤之黑也。女部曰。嬒、女黑色也。按沃黑玉篇、廣韵皆作淺黑。疑沃字誤、淺字長。"}]},"黯":{"expl":"深黑也。从黑音聲。","rad":"黑","fq":"乙減切","vol":"10","py":"àn","duan":[{"e":"深黑也。","n":"別賦黯然銷魂、其引申之義。"}]},"黶":{"expl":"申黑也。从黑厭聲。","rad":"黑","fq":"於𤥎切","vol":"10","py":"yǎn","duan":[{"e":"中黑也。","n":"謂黑在中也。大學注。厭讀爲黶。黶者、閉藏皃也。其引申之義也。"}]},"黳":{"expl":"小黑子。从黑殹聲。","rad":"黑","fq":"烏雞切","vol":"10","py":"yī","duan":[{"e":"小黑子。","n":"師古漢書注曰。黑子今中國通呼爲魘子。吳楚謂之誌。誌、記也。按魘黳雙聲。"}]},"䵣":{"expl":"白而有黑也。从黑旦聲。五原有莫䵣縣。","rad":"黑","fq":"當割切","vol":"10","py":"dá","duan":[{"e":"白而有黑也。从黑。旦聲。","n":"當割切。十四十五部。"}]},"𪒹":{"expl":"雖皙而黑也。从黑箴聲。古人名𪒹字皙。","rad":"黑","fq":"古咸切","vol":"10","py":"jiān","duan":[{"e":"雖皙而黑也。","n":"晳者、人色白也。則𪒹專謂人面。"}]},"䵮":{"expl":"赤黑也。从黑昜聲。讀若煬。","rad":"黑","fq":"餘亮切","vol":"10","py":"yànɡ","duan":[{"e":"赤黑也。从黑。昜聲。讀若煬。","n":"餘亮切。十部。"}]},"黲":{"expl":"淺青黑也。从黑參聲。","rad":"黑","fq":"七感切","vol":"10","py":"cǎn","duan":[{"e":"淺靑黑色也。","n":"淺靑之黑也。通俗文曰。暗色曰黲。玉篇曰。今謂物將敗時顏色黲也。"}]},"黤":{"expl":"青黑也。从黑奄聲。","rad":"黑","fq":"於檻切","vol":"10","py":"yǎn","duan":[{"e":"靑黑色也。","n":"謂靑色之黑也。"}]},"黝":{"expl":"微青黑色。从黑幼聲。《爾雅》曰：“地謂之黝。”","rad":"黑","fq":"於糾切","vol":"10","py":"yǒu","duan":[{"e":"微靑黑色也。","n":"謂微靑之黑也。微輕於淺矣。黝古多叚幽爲之。小雅。隰桑有阿。其葉有幽。傳曰。幽、黑色也。周禮牧人。陰祀用幽牲。先鄭云。幽讀爲黝。黑也。守祧。其祧。則守祧幽堊之。先鄭亦云。幽讀爲黝。黝、黑也。今本皆轉寫幽黝誤譌矣。玉藻。一命縕韍幽衡。再命赤韍幽衡。鄭云。幽讀爲黝。黑謂之黝。"}]},"蓸":{"expl":"艸也。从艸曹聲。","rad":"艸","fq":"昨牢切","vol":"01","py":"cáo","duan":[{"e":"艸也。从艸。曹聲。","n":"昨牢切。古音在三部。籒文作？。"}]},"黗":{"expl":"黃濁黑。从黑屯聲。","rad":"黑","fq":"他衮切","vol":"10","py":"tūn","duan":[{"e":"黃濁黑也。","n":"謂黃濁之黑也。廣雅云。黗、黑也。？、黃也。葢二字音義同。偏旁異耳。檀弓有？字。廣韵曰。魯公子名。亦黃色也。然則？字亦同。"}]},"點":{"expl":"小黑也。从黑占聲。","rad":"黑","fq":"多忝切","vol":"10","py":"diǎn","duan":[{"e":"小黑也。","n":"今俗所謂㸃涴是也。或作玷。"}]},"黚":{"expl":"淺黃黑也。从黑甘聲。讀若染繒中束緅黚。","rad":"黑","fq":"巨淹切","vol":"10","py":"qián","duan":[{"e":"淺黃黑也。","n":"淺黃之黑與黃濁之黑相對成文。地理志犍爲郡黚水作此字。許水部作黔水。音同故也。"}]},"𪑙":{"expl":"黃黑也。从黑金聲。","rad":"黑","fq":"古咸切","vol":"10","py":"jiān","duan":[{"e":"黃黑也。","n":"謂黃色之黑。玉篇曰。記林切。黃色如金也。廣韵。居吟切。淺黃色也。"}]},"𪑲":{"expl":"黑有文也。从黑冤聲。讀若飴𧯡字。","rad":"黑","fq":"於月切","vol":"10","py":"yuè","duan":[{"e":"黑有文也。从黑。冤聲。讀若飴𧯡字。","n":"豆部曰。登、豆飴也。食部曰。飴、米櫱煎也。於月切。十四十五部。亦作黦。按周禮染人夏纁。玄注云。故書纁作䵫。䵫卽？也。唐宋人詩詞多用黦字。如韋莊淚沾紅袖黦之類。王氏念孫曰。淮南時則訓。天子衣苑黃。高注云。苑讀？飴之？。春秋緐露。民病心腹宛黃。皆字異而義同。"}]},"䵵":{"expl":"黃黑而白也。从黑算聲。一曰短黑。讀若以芥爲齏，名曰芥荃也。","rad":"黑","fq":"初刮切","vol":"10","py":"chuā","duan":[{"e":"黃黑而白也。","n":"謂黃黑而發白色也。"}]},"䵤":{"expl":"黑皴也。从黑幵聲。","rad":"黑","fq":"古典切","vol":"10","py":"jiǎn","duan":[{"e":"黑皴也。","n":"皮部無皴字。見於此、戰國策。墨子百舍重繭。往見公輸般。淮南書。申包胥累繭重胝。七日七夜至於秦庭。皆借繭爲？也。"}]},"黠":{"expl":"堅黑也。从黑吉聲。","rad":"黑","fq":"胡八切","vol":"10","py":"xiá","duan":[{"e":"堅黑也。","n":"黑之堅者也。石部曰。硈石堅也。亦吉聲也。引申爲奸巧之偁。貨殖列傳云。桀黠奴。謂其性堅而善藏也。方言曰。慧、自關而東趙魏之閒謂之黠。或謂之鬼。"}]},"黔":{"expl":"黎也。从黑今聲。秦謂民爲黔首，謂黑色也。周謂之黎民。《易》曰：“爲黔喙。”","rad":"黑","fq":"巨淹切","vol":"10","py":"qián","duan":[{"e":"黎也。","n":"黎、履黏也。與驪？字同音。故借爲黑義。耇下曰。老人面凍黎若垢。謂凍黑也。俗作黧。小徐本作黧。乃用俗字改許也。"}]},"黕":{"expl":"滓垢也。从黑冘聲。","rad":"黑","fq":"都感切","vol":"10","py":"dǎn","duan":[{"e":"滓垢也。","n":"滓者、澱也。垢者、濁也。荀卿曰。人心譬如槃水。正錯而勿動。則湛濁在下而淸明在上。楊倞曰。湛濁謂沈泥滓也。按湛卽黕之叚借字。文𨕖注引魏文帝愁霖賦曰。玄雲黕其四塞。借黕爲黑皃。引申之義也。"}]},"𦵵":{"expl":"艸也。从艸𠧴聲。","rad":"艸","fq":"以周切","vol":"01","py":"yóu","duan":[{"e":"艸也。从艸。𠧴聲。","n":"以周切。三部。籒文作𦿥。"}]},"黨":{"expl":"不鮮也。从黑尚聲。","rad":"黑","fq":"多朗切","vol":"10","py":"dǎnɡ","duan":[{"e":"不鮮也。","n":"新鮮字當作鱻。屈賦遠遊篇。時曖瞹其曭莽。王注曰。日月晻黮而無光也。然則黨曭古今字。方言曰。黨、知也。楚謂之黨。郭注。黨朗。解寤皃。此義之相反而成者也。釋名曰。五百家爲黨。黨長也。一聚所尊長也。此謂黨同尙。"}]},"黷":{"expl":"握持垢也。从黑賣聲。《易》曰：“再三黷。”","rad":"黑","fq":"徒谷切","vol":"10","py":"dú","duan":[{"e":"握持垢也。","n":"垢非可握持之物。而入於握持。是辱也。古凡言辱者皆卽黷。故鄭注昏禮曰。以白造緇曰辱。字書辱亦作？。"}]},"黵":{"expl":"大污也。从黑詹聲。","rad":"黑","fq":"當敢切","vol":"10","py":"dǎn","duan":[{"e":"大汚也。从黑。詹聲。","n":"當敢切。八部。"}]},"黴":{"expl":"中久雨青黑。从黑，微省聲。","rad":"黑","fq":"武悲切","vol":"10","py":"méi","duan":[{"e":"中久雨靑黑也。","n":"楚辭九歌。顏黴黎以沮敗。淮南說山訓曰。晉文公棄荏席。後黴黑。"}]},"黜":{"expl":"貶下也。从黑出聲。","rad":"黑","fq":"丑律切","vol":"10","py":"chù","duan":[{"e":"貶下也。","n":"玉篇云。貶也、下也。按當作貶也下色也五字。貶也者、黜陟之義也。下色也者、爲从黑張本也。古或叚詘、絀爲之。"}]},"𪒀":{"expl":"𪒀𡜜，下哂。从黑般聲。","rad":"黑","fq":"薄官切","vol":"10","py":"pán","duan":[{"e":"𪒀姍、","n":"逗。"}]},"黱":{"expl":"畫眉也。从黑朕聲。","rad":"黑","fq":"徒耐切","vol":"10","py":"dài","duan":[{"e":"畫睂墨也。","n":"依小徐有墨字。玉篇作黑。黱者、婦人畫睂之黑物也。釋名曰。黛、代也。滅睂毛去之。以此畫代其處也。通俗文曰。㸃靑石謂之㸃黛。服䖍、劉熙字皆作黛。不與許同。漢人用字不同之徵也。黛者、黱之俗。楚辭、國策遂無作黱者。"}]},"儵":{"expl":"青黑繒縫白色也。从黑攸聲。","rad":"黑","fq":"式竹切","vol":"10","py":"shū","duan":[{"e":"靑黑繒發白色也。","n":"古亦叚爲倐忽字。又釋訓。儵儵、嘒嘒、罹禍毒也。釋小弁踧踧周道、鳴蜩嘒嘒也。"}]},"𪑝":{"expl":"羔裘之縫。从黑或聲。","rad":"黑","fq":"于逼切","vol":"10","py":"yù","duan":[{"e":"羔裘之縫也。","n":"召南。羔羊之革。素絲五緎。傳曰。革猶皮也。緎、縫也。許所據詩作？。"}]},"𪑩":{"expl":"𪑍謂之垽。垽，滓也。从黑，殿省聲。","rad":"黑","fq":"堂練切","vol":"10","py":"diàn","duan":[{"e":"𪑩謂之垽。","n":"土部曰。垽、澱也。水部曰。滓、澱也。澱、滓垽也。是澱𪑩二篆異部而實一字也。故爾雅釋器作澱謂之垽。"}]},"菬":{"expl":"艸也。从艸沼聲。","rad":"艸","fq":"昨焦切","vol":"01","py":"qiáo","duan":[{"e":"艸也。从艸。沼聲。","n":"昨焦切。二部。籒文作？。"}]},"黮":{"expl":"桑葚之黑也。从黑甚聲。","rad":"黑","fq":"他感切","vol":"10","py":"dǎn","duan":[{"e":"桑葚之黑也。","n":"桑葚見艸部。葚黑曰黮。故泮水卽以其色名之。毛傳曰。黮、桑實也。謂黮卽葚之叚借字也。許與毛小別矣。廣雅。黑也。則引申爲凡黑之偁。方言云。私也。亦引申之義也。"}]},"黭":{"expl":"果實黭黯黑也。从黑弇聲。","rad":"黑","fq":"烏感切","vol":"10","py":"yǎn","duan":[{"e":"果實黭黯黑也。","n":"荀卿子。黭然而雷擊之。注。黭然、卒至之皃。此叚借字也。"}]},"黥":{"expl":"墨刑在面也。从黑京聲。","rad":"黑","fq":"渠京切","vol":"10","py":"qínɡ","duan":[{"e":"墨㓝在面也。","n":"此㓝亦謂之墨。周禮司㓝注曰。墨、黥也。先刻其面。以墨窒之。"}]},"𪒠":{"expl":"𪒠者忘而息也。从黑敢聲。","rad":"黑","fq":"於檻切","vol":"10","py":"yǎn","duan":[{"e":"𪒠者忘而息也。","n":"方言、廣雅皆曰。𪒠、忘也。忘而息、宋人所謂黑甜也。故从黑。今人所用憨字卽此字之變也。"}]},"黟":{"expl":"黑木也。从黑多聲。丹陽有黟縣。","rad":"黑","fq":"烏雞切","vol":"10","py":"yī","duan":[{"e":"黑木也。","n":"周書王會篇夷用？木。古今注。烏文木、出波斯國。南方艸木狀。文木樹高七八丈。色正黑。如水牛角。"}]},"囪":{"expl":"在牆曰牖，在屋曰囪。象形。凡囪之屬皆从囪。","rad":"囪","fq":"楚江切","vol":"10","py":"chuānɡ","duan":[{"e":"在牆曰牖。","n":"片部曰。牖、穿壁以木爲交窗也。"}]},"悤":{"expl":"多遽悤悤也。从心、囪，囪亦聲。","rad":"囪","fq":"倉紅切","vol":"10","py":"cōnɡ","duan":[{"e":"多遽恖恖也。从囱从心。","n":"各本作从心囱。今正。从囱从心者、謂孔隙旣多而心亂也。故其字入囱部會意。不入心部形聲。叚令入心部。則當爲心了悟之解矣。"}]},"焱":{"expl":"火華也。从三火。凡焱之屬皆从焱。","rad":"焱","fq":"以冄切","vol":"10","py":"yàn","duan":[{"e":"火𦾓也。","n":"古書焱與猋二字多互譌。如曹植七啟風厲猋舉、當作焱舉。班固東都賦焱焱炎炎、當作猋猋炎炎。王逸曰。猋、去疾皃也。李善注幾不別二字。"}]},"熒":{"expl":"屋下鐙燭之光。从焱、冂。","rad":"焱","fq":"戶扃切","vol":"10","py":"yínɡ","duan":[{"e":"屋下鐙燭之光也。","n":"鐙者、錠也。鐙以膏助然之。燭以麻蒸然之。其光熒熒然在屋之下。故其字从冖。冖者、覆也。熒者、光不定之皃。今江東人俗語如役。高注淮南每云熒惑是也。泲水出𣳚不常。故尙書泆爲熒作此字。周禮其川熒雒。左傳閔二年、宣十二年、杜預後序熒澤。庸風箋熒澤。左傳杜注熒陽。玉篇熒字下曰亦熒陽縣。漢韓勑後碑、劉寬碑陰、鄭烈碑皆云熒陽。唐慮藏用紀信碑亦作熒陽。隨書王劭傳上表言符命曰龍鬭於熒陽者。熒字三火。明火德之盛也。然則熒澤、熒陽古無作滎者。尙書禹貢釋文經宋開寶中妄改熒爲滎。而經典、史記、漢書、水經注皆爲淺人任意竄易。以爲水名當作滎。不知泲水名熒。自有本義。於絕小水之義無涉也。"}]},"燊":{"expl":"盛皃。从焱在木上。讀若《詩》“莘莘征夫”。一曰伇也。","rad":"焱","fq":"所臻切","vol":"10","py":"shēn","duan":[{"e":"盛皃。","n":"木部䯂字下曰.衆盛也。此與同意。"}]},"䓊":{"expl":"艸也。从艸吾聲。《楚詞》有䓊蕭艸。","rad":"艸","fq":"吾乎切","vol":"01","py":"wú","duan":[{"e":"艸也。","n":"廣韵云。似艾。郭注方言云。今江東人呼荏爲䓊。音魚。"}]},"炙":{"expl":"炮肉也。从肉在火上。凡炙之屬皆从炙。","rad":"炙","fq":"之石切","vol":"10","py":"zhì","duan":[{"e":"炙肉也。","n":"炙肉各本作炮肉。今依楚茨傳正。小雅楚茨傳曰。炙、炙肉也。瓠葉傳曰。炕火曰炙。正義云。炕、舉也。謂以物貫之而舉於火上以炙之。按炕者俗字。古當作抗。手部曰。抗扞也。方言曰抗縣也。是也。瓠葉言炮、言燔、言炙。傳云。毛曰炮。加火曰燔。抗火曰炙。燔炙不必毛也。抗火不同加火之逼近也。此毛意也。箋云。凡治兔之首宜。鮮者毛炮之。柔者炙之。乾者燔之。此申毛意也。然則鳧鷖、楚茨、行葦燔炙並言。皆必異義。生民傳曰。傅火曰燔。貫之加於火曰烈。貫之加於火、卽抗火也。生民之烈、卽炙也。禮運注曰。炮、裹燒之也。燔加於火上也。炙、貫之火上也。三者正與瓠葉傳相合。然則炙與炮之別異又可知矣。許宗毛義。故炙下云炙肉也。用楚茨傳爲文"}]},"㸋":{"expl":"宗廟火孰肉。从炙番聲。《春秋傳》曰：“天子有事㸋焉，以饋同姓諸矦。”","rad":"炙","fq":"附袁切","vol":"10","py":"fán","duan":[{"e":"宗廟火{(𦎧+丸[左右]}肉。","n":"今世經傳多作燔、作膰。惟許書作㸋。火部燔下云𤑔也。是詩作燔爲假借字。他經作膰乃俗耳。許稱左傳作㸋。左傳釋文云。膰周禮又作㸋。皆古文之存焉者也。異義。左氏說。脤、社祭之肉。盛之以蜃。宗廟之肉名曰膰。說文作祳㸋。用左氏說。祳下曰。社肉盛以蜃。故曰祳。天子所以親遺同姓。㸋下云。宗廟火孰肉也。天子所以饋同姓。古本當如此。今本爲寫者舛誤耳。必云炙孰者、爲其字从火。"}]},"爒":{"expl":"炙也。从炙尞聲。讀若𤒅燎。","rad":"炙","fq":"力照切","vol":"10","py":"liǎo","duan":[{"e":"炙也。","n":"其義同炙。其音同燎。"}]},"赤":{"expl":"南方色也。从大从火。凡赤之屬皆从赤。","rad":"赤","fq":"昌石切","vol":"10","py":"chì","duan":[{"e":"南方色也。","n":"爾雅。一染謂之縓。再染謂之竀。三染謂之纁。鄭注士冠禮云。朱則四入與。按是四者皆赤類也。鄭注易曰。朱深於赤。按赤色至明。引申之、凡洞然昭著皆曰赤。如赤體謂不衣也。赤地謂不毛也。"}]},"赨":{"expl":"赤色也。从赤，蟲省聲。","rad":"赤","fq":"徒冬切","vol":"10","py":"tónɡ","duan":[{"e":"赤色也。","n":"管子地員篇。其種大苗細苗。赨莖黑秀箭長。尹注。赨卽赤也。"}]},"𧹲":{"expl":"日出之赤。从赤，穀省聲。","rad":"赤","fq":"火沃切","vol":"10","py":"hù","duan":[{"e":"日出之赤也。从赤𣪊聲。","n":"按古本篆文當是上體从𣪊。下體从赤。火沃切。三部。篇、韵皆呼木切。"}]},"赧":{"expl":"面慙赤也。从赤𠬝聲。周失天下於赧王。","rad":"赤","fq":"女版切","vol":"10","py":"nǎn","duan":[{"e":"面慙而赤也。","n":"而字依韵會。趙注孟子曰。赧赧、面赤心不正皃也。司馬貞引小爾雅曰。面慙曰赧。"}]},"䞓":{"expl":"赤色也。从赤坙聲。《詩》曰：“魴魚䞓尾。”","rad":"赤","fq":"敕貞切","vol":"10","py":"chēnɡ","duan":[{"e":"赤色也。","n":"周南傳曰。赬、赤也。爾雅釋器。一染謂之縓。再染謂之赬。三染謂之纁。郭曰。縓、今之紅也。赬、染赤也。纁、絳也。按糸部云。縓、帛赤黃色也。絳、大赤也。糸部引爾雅正作䞓。周禮注引爾雅、又哀十七年左傳作竀。假借字也。士喪禮經作䞓。"}]},"浾":{"expl":"䞓，棠棗之汁，或从水。","rad":"赤","fq":"","vol":"10","py":"chēnɡ","duan":[{"e":"棠棗之汁也。从赤水。","n":"各本轉寫舛誤。今正。浾與䞓音雖同而義異。別爲一字。非卽䞓字也。棠棗汁皆赤。故从赤水會意。勅貞切。十一部。"}]},"赭":{"expl":"赤土也。从赤者聲。","rad":"赤","fq":"之也切","vol":"10","py":"zhě","duan":[{"e":"赤土也。","n":"邶風赫如渥赭、卽秦風之顏如渥丹。故箋訓赭爲丹。古秦風。毛亦作渥赭。是以韓詩作沰。沰與赭音義皆同也。管子地𢿙篇云。上有赭者下有𨮯。是赭之本義爲赤土也。引申爲凡赤。"}]},"范":{"expl":"艸也。从艸氾聲。","rad":"艸","fq":"房𡕢切","vol":"01","py":"fàn","duan":[{"e":"艸也。从艸。氾聲。","n":"房？切。八部。籒文作？。"}]},"𧹳":{"expl":"赤色也。从赤倝聲。讀若浣。","rad":"赤","fq":"胡玩切","vol":"10","py":"ɡàn","duan":[{"e":"赤色也。从赤。倝聲。讀若浣。","n":"胡玩切。十四部。"}]},"赫":{"expl":"火赤皃。从二赤。","rad":"赤","fq":"呼格切","vol":"10","py":"hè","duan":[{"e":"大赤皃。","n":"大各本作火。今正。此謂赤。非謂火也。赤之盛、故从二赤。邶風。赫如渥赭。傳曰。赫、赤皃。此赫之本義也。若生民傳曰赫、顯也。出車傳赫赫、盛皃。常武傳㒳云赫赫然、盛也。節南山傳赫赫、顯盛也。淇奧傳赫、有明德赫赫然。以及雲漢傳赫赫、旱氣也。桑柔傳赫、炙也。皆引申之義也。又按皕部曰奭、盛也。是詩中凡訓盛者、皆叚奭爲赫。而采芑、瞻彼洛矣二傳曰奭、赤皃。卽𥳑兮傳之赫、赤皃。正謂奭卽赫之假借也。爾雅釋訓奭奭、本作赫赫。二字古音同矣。或作赩。如白虎通引韎韐有赩、李注文𨕖亦引毛傳赩、赤皃。"}]},"赩":{"expl":"大赤也。从赤、色，色亦聲。","rad":"赤","fq":"許力切","vol":"10","py":"xì","duan":[]},"赮":{"expl":"赤色也。从赤叚聲。","rad":"赤","fq":"乎加切","vol":"10","py":"xiá","duan":[]},"大":{"expl":"天大，地大，人亦大。故大象人形。古文大(他達切)也。凡大之屬皆从大。","rad":"大","fq":"徒蓋切","vol":"10","py":"dà","duan":[{"e":"天大。地大。人亦大焉。","n":"依韵會訂。"}]},"奎":{"expl":"兩髀之閒。从大圭聲。","rad":"大","fq":"苦圭切","vol":"10","py":"kuí","duan":[{"e":"㒳髀之閒。","n":"奎與胯雙聲。奎宿十六星以像似得名。"}]},"夾":{"expl":"持也。从大俠二人。","rad":"大","fq":"古狎切","vol":"10","py":"jiā","duan":[{"e":"持也。","n":"持者、握也。握者、搤也。搤者、捉也。捉物必以兩手。故凡持曰㚒。左傳曰。㚒輔成王。古多叚俠爲㚒。公羊注曰。滕薛俠轂。"}]},"奄":{"expl":"覆也。大有餘也。又，欠也。从大从申。申，展也。","rad":"大","fq":"依檢切","vol":"10","py":"yǎn","duan":[{"e":"覆也。大有餘也。","n":"釋言曰。荒奄也。弇、同也。弇、葢也。古奄弇同用。覆葢同義。詩皇矣傳曰。奄、大也。執競傳曰。奄、同也。鄭箋詩奄皆訓覆。許云覆也。大有餘也。二義實相因也。覆乎上者、往往大乎下。故字从大。周官經謂宦者爲奄。以精氣閉藏名之。覆葢義之引申也。"}]},"夸":{"expl":"奢也。从大于聲。","rad":"大","fq":"苦瓜切","vol":"","py":"kuā","duan":[{"e":"奢也。","n":"奢者、張也。曡韵同義。"}]},"𡘍":{"expl":"奢𡘍也。从大亘聲。","rad":"大","fq":"胡官切","vol":"10","py":"huán","duan":[{"e":"奢𡘍也。","n":"當是本作𡘍、奢也。𡘍字爲逗。轉寫倒之。今經傳都無𡘍字。有桓字。商頌長發傳曰。桓、大也。撥、治也。箋云。廣大其政治。此可以證桓卽𡘍之叚借字。檀弓桓楹。注亦云大楹。周禮桓圭同解。周書謚法。辟土服遠曰桓。辟土兼國曰桓。皆是大義。釋訓曰。桓桓、威也。泮水傳曰。桓桓、威武皃。詩序曰。桓、講武類禡也。葢此等桓字亦𡘍之叚借字。大之義可以兼武也。桓之本義爲亭郵表。自經傳皆借爲𡘍字。乃致桓行𡘍廢矣。非許書尙存、孰能識其本始。非長發傳尙存。何以觀其會通。淺人乃易長發傳云。桓、武撥治。是謂桓必無訓大之理。而不知周公之六書有叚借也。又按淇奧傳曰。咺、威儀容止宣著也。亦謂咺卽𡘍之叚借。宣著者、光大之意也。許書口部咺有本"}]},"艿":{"expl":"艸也。从艸乃聲。","rad":"艸","fq":"如乘切","vol":"01","py":"rénɡ","duan":[{"e":"艸也。","n":"按許謂艿爲艸名也。廣韵云。陳根艸不芟。新艸又生。相因仍。所謂燒火艿。此別一義。其字亦作芿。列子。趙襄子狩於中山、藉芿燔林是也。今玉篇以舊艸不芟、新艸又生曰艿、係之說文。此孫強、陳彭年輩之誤也。"}]},"𡗷":{"expl":"𡗷，大也。从大瓜聲。","rad":"大","fq":"烏瓜切","vol":"10","py":"ɡū","duan":[{"e":"𡗷大也。","n":"此謂窊之大也。"}]},"奯":{"expl":"空大也。从大歲聲。讀若《詩》“施罟泧泧”。","rad":"大","fq":"呼括切","vol":"10","py":"huò","duan":[{"e":"空大也。","n":"此謂空中之大。與豁義略同。篇、韵云。大目也。"}]},"𢧜":{"expl":"大也。从大𢧄聲。讀若《詩》“𢧜𢧜大猷”。","rad":"大","fq":"直質切","vol":"10","py":"zhì","duan":[{"e":"大也。","n":"此謂秩秩然之大也。地理志四驖作四𢧤。"}]},"奅":{"expl":"大也。从大卯聲。","rad":"大","fq":"匹貌切","vol":"10","py":"pào","duan":[{"e":"大也。","n":"此謂虛張之大。廣韵曰。起釀也。"}]},"夽":{"expl":"大也。从大云聲。","rad":"大","fq":"魚吻切","vol":"10","py":"yǔn","duan":[{"e":"大也。","n":"此謂㮯物之大。"}]},"奃":{"expl":"大也。从大氐聲。讀若氐。","rad":"大","fq":"都兮切","vol":"10","py":"dī","duan":[{"e":"大也。","n":"此謂根柢之大。"}]},"𡗦":{"expl":"大也。从大介聲。讀若蓋。","rad":"大","fq":"古拜切","vol":"10","py":"jiè","duan":[{"e":"大也。","n":"此謂分畫之大。方言曰。𡗦、大也。東齊海岱之閒曰𡗦。或曰幠。按經傳多叚介爲之。釋詁曰。介、大也。詩生民小明傳皆曰。介、大也。士冠禮注、易晉虞注、左傳貴介弟介麋注、吳語介福注、孟子不以三公易其介。離騷堯舜耿介注同。"}]},"𡗼":{"expl":"瞋大也。从大此聲。","rad":"大","fq":"火戒切","vol":"10","py":"xiè","duan":[{"e":"瞋大聲也。","n":"各本無聲字。今依玉篇、廣韵補。瞋大聲者、謂張目而大聲。若言喑噁叱咤、千人皆廢也。疑瞋下奪目字。又按瞋、張目也。瞋大、史所謂目眥盡裂也。聲誤衍。"}]},"㚕":{"expl":"大也。从大弗聲。讀若“予違，汝弼”。","rad":"大","fq":"房密切","vol":"10","py":"bì","duan":[{"e":"大也。","n":"此謂矯拂之大。周頌。佛時仔肩。傳曰。佛、大也。此謂佛卽㚕之叚借也。小雅。廢爲殘賊。毛傳一本廢、大也。釋詁云。廢、大也。此謂廢卽㚕之叚借字也。"}]},"𡗥":{"expl":"大也。从大屯聲。讀若鶉。","rad":"大","fq":"常倫切","vol":"10","py":"chún","duan":[{"e":"大也。","n":"此謂敦厚之大。"}]},"䒸":{"expl":"艸也。从艸血聲。","rad":"艸","fq":"呼決切","vol":"01","py":"xuè","duan":[{"e":"艸也。","n":"蒨或謂之地䒸。許不云茜也。則許意非一物也。"}]},"契":{"expl":"大約也。从大从㓞。《易》曰：“後代聖人易之以書契。”","rad":"大","fq":"苦計切","vol":"10","py":"qì","duan":[{"e":"大約也。","n":"約取纏束之義。周禮有司約。大約劑。書於宗彝。小宰。聽取予以書契。大鄭云。書契、符書也。後鄭云。書契謂出予受入之凡要。凡簿書之冣目。獄訟之要辭。皆曰契。引春秋傳王叔氏不能舉其契。按今人但於賈賣曰文契。經傳或叚契爲栔。如爰契我龜傳曰契、開也是也。又叚爲挈字。如死生契闊傳曰契闊、勤苦也。又契契寤歎傳曰契契、憂苦也。皆取提挈勤苦之意也。"}]},"夷":{"expl":"平也。从大从弓。東方之人也。","rad":"大","fq":"以脂切","vol":"10","py":"yí","duan":[{"e":"東方之人也。从大。从弓。","n":"各本作平也。从大从弓、東方之人也。淺人所改耳。今正。韵會正如是。羊部曰。南方蠻閩从虫。北方狄从犬。東方貉从豸。西方羌从羊。西南僰人、焦僥从人。葢在坤地頗有順理之性。惟東夷从大。大、人也。夷俗仁。仁者壽。有君子不死之國。按天大、地大、人亦大。大象人形。而夷篆从大。則與夏不殊。夏者、中國之人也。从弓者、肅愼氏貢楛矢石砮之類也。以脂切。十五部。出車、節南山、桑柔、召旻傳皆曰。夷、平也。此與君子如夷、有夷之行、降福孔夷傳夷易也同意。夷卽易之叚借也。易亦訓平。故叚夷爲易也。節南山一詩中平易分釋者、各依其義所近也。風雨傳曰夷悅也者、平之意也。皇矣傳曰夷常也者、謂夷卽彝之叚借也。凡注家云夷傷也者、謂夷卽痍之"}]},"亦":{"expl":"人之臂亦也。从大，象兩亦之形。凡亦之屬皆从亦。","rad":"亦","fq":"羊益切","vol":"10","py":"yì","duan":[{"e":"人之臂亦也。","n":"玉篇今作掖。按手部掖者、以手持人臂投地也。一曰臂下也。一曰臂下之語、葢淺人據俗字增之耳。徐鉉等曰。亦今別作腋。按廣韵肘腋作此字。俗用亦爲語䛐。乃別造此。肉部曰。胳、亦下也。胠、亦下也。今禮記深衣袼之高下注云。袼、衣袂當腋之縫。袼、腋乃皆俗字。人臂㒳垂。臂與身之閒則謂之臂亦。臂與身有重曡之意。故引申爲重累之䛐。公羊傳。大火爲大辰。伐爲大辰。北辰亦爲大辰。何注云。亦者、㒳相須之意。按經傳之亦、有上有所蒙者。有上無所蒙者。論語不亦說乎、亦可宗也。亦可以弗畔、亦可以爲成人矣。皆上無所蒙。皇侃曰。亦猶重也。此等皆申重贊美之䛐。亦之言猶大也、甚也。若周頌亦有高廩、亦服爾耕。鄭箋云。亦、大也。是謂亦卽奕奕之"}]},"㚒":{"expl":"盜竊褱物也。从亦，有所持。俗謂蔽人俾夾是也。弘農陝字从此。","rad":"亦","fq":"失冄切","vol":"10","py":"shǎn","duan":[{"e":"盜竊褱物也。从亦。有所持。","n":"㒳亦下有物。盜竊而褱之意。失冉切。七部。"}]},"夨":{"expl":"傾頭也。从大，象形。凡夨之屬皆从夨。","rad":"夨","fq":"阻力切","vol":"10","py":"zè","duan":[{"e":"傾頭也。","n":"人部曰。傾者、夨也。夨象頭傾。因以爲凡傾之偁。"}]},"𡔢":{"expl":"頭傾也。从夨吉聲。讀若孑。","rad":"夨","fq":"古㞕切","vol":"10","py":"jié","duan":[{"e":"从夨。吉聲。讀若𡤼。","n":"古㞕切。十二部。"}]},"奊":{"expl":"頭衺、骩奊態也。从夨圭聲。","rad":"夨","fq":"胡結切","vol":"10","py":"xié","duan":[{"e":"頭衺骫奊態也。。","n":"頭衺者、頭不正。骫奊者、頭不正之皃也。左傳。齊有慶奊。卽慶繩。葢以頭邪爲名。以繩直爲字。名字相應也。賈誼傳。奊詬無節。叚奊爲謑。"}]},"吳":{"expl":"姓也。亦郡也。一曰吳，大言也。从夨、口。","rad":"夨","fq":"五乎切","vol":"10","py":"wú","duan":[{"e":"大言也。","n":"大言之上各本有姓也亦郡也一曰吳八字。乃妄人所增。今𠜂正。檢韵會本正如是。周頌絲衣、魯頌泮水皆曰不吳。傳箋皆云吳、譁也。言部曰。譁者、讙也。然則大言卽謂譁也。孔沖遠詩正義作不娛。史記孝武本紀作不虞。皆叚借字。大言者、吳字之本義也。引伸之爲凡大之偁。方言曰。吳、大也。九章。齊吳榜以擊汏。王注。齊舉大櫂。"}]},"夭":{"expl":"屈也。从大，象形。凡夭之屬皆从夭。","rad":"夭","fq":"於兆切","vol":"10","py":"yāo","duan":[{"e":"屈也。从大。象形。","n":"象首夭屈之形也。隰有萇楚得曰。夭、少也。桃夭傳曰。夭夭、桃之少壯也。凱風傳曰。夭夭、盛皃也。月令注曰。少長曰夭。此皆謂物初長可觀也。物初長者尙屈而未申。叚令不成遂、則終於夭而已矣。故左傳、國語注曰。短折曰夭。國語注又曰。不終曰夭。又曰。夭折也。孟康注五行志曰。用人不以次弟爲夭。皆其引申之義也。論語。子之燕居。申申如也。夭夭如也。上句謂其申。下句謂其屈。不屈不申之閒、其斯爲聖人之容乎。於兆切。二部。按亦於喬切。古平上無異義。後人乃別之。"}]},"喬":{"expl":"高而曲也。从夭，从高省。《詩》曰：“南有喬木。”","rad":"夭","fq":"巨嬌切","vol":"10","py":"qiáo","duan":[{"e":"高而曲也。","n":"爾雅釋詁、詩伐木時邁傳皆曰。喬、高也。釋木曰。上句曰喬。句如羽喬。漢廣傳曰。喬、上竦也。按喬不專謂木。淺人以說木則作橋。如鄭風山有橋松是也。以說山則作嶠。釋山銳而高嶠是也。皆俗字耳。許云高而曲、卽爾雅之上句如羽。木有如是者、他物亦有如是者。"}]},"萄":{"expl":"艸也。从艸匋聲。","rad":"艸","fq":"徒刀切","vol":"01","py":"táo","duan":[{"e":"艸也。","n":"今人爲蒲萄字。"}]},"𡴘":{"expl":"吉而免凶也。从屰从夭。夭，死之事。故死謂之不𡴘。","rad":"夭","fq":"胡耿切","vol":"10","py":"xìnɡ","duan":[{"e":"吉而免凶也。","n":"吉者、善也。凶者、惡也。得免於惡是爲幸。"}]},"奔":{"expl":"走也。从夭，賁省聲。與走同意，俱从夭。","rad":"夭","fq":"博昆切","vol":"10","py":"bēn","duan":[{"e":"𧺆也。","n":"𧺆者、趨也。釋宫曰。室中謂之時。堂上謂之行。堂下謂之步。門外謂之趨。中庭謂之走。大路謂之奔。此析言之耳。渾言之則奔走趨不別也。引申之、凡赴急曰奔。凡出亡曰奔。其字古或叚賁、或叚本。毛詩予曰有本走、陸德明本如是。"}]},"交":{"expl":"交脛也。从大，象交形。凡交之屬皆从交。","rad":"交","fq":"古爻切","vol":"10","py":"jiāo","duan":[{"e":"交脛也。","n":"交脛謂之交。引申之爲凡交之偁。故爻下曰。交也。烄下曰。交木然也。𤉧下曰交灼本也。㮐下曰。木參交以枝炊䉛者也。衿下曰。交衽也。凡㒳者相合曰交。皆此義之引申叚借耳。楚茨傳。東西曰交。邪行曰逪。䢒逪字之叚借也。小雅。交交桑扈。箋云。交交猶佼佼。飛往來皃。而黃鳥、小宛傳皆曰。交交、小皃。則與本義不同。葢方語有謂小交交者。"}]},"𠆎":{"expl":"衺也。从交韋聲。","rad":"交","fq":"羽非切","vol":"10","py":"wéi","duan":[{"e":"衺也。","n":"衣部衺下曰。𩎮也。二篆爲轉注。經典叚回字爲之。小旻。謀猶回遹。傳曰。回、邪也。大明。厥德不回。傳曰。回、違也。回皆𩎮之叚借字。小旻言其轉注。大明言其叚借。故傳語不同。大明傳違卽𩎮字。𩎮久不行。俗乃作違。經典多作回。口部曰。回、轉也。乃回之本義。必有許書而後知回衺之本字作𩎮。桓大之本宇作𡘍。僾唈之本字作{兂：左右反}。倘不能觀其會通。則許書徒存而已矣。"}]},"絞":{"expl":"縊也。从交从糸。","rad":"交","fq":"古巧切","vol":"10","py":"jiǎo","duan":[{"e":"縊也。","n":"糸部縊下曰。縊、絞也。二篆爲轉注。古曰絞曰縊者、謂㒳繩相交。非獨謂經死。禮喪服絞帶者、繩帶也。㒳繩相交而緊謂之絞。論語。直而無禮則絞。好直不好學。其蔽也絞。馬融曰。絞、剌也。鄭云。急也。剌盧達切。乖剌也。與鄭義無異。急則無不乖剌者也。皇侃、陸德明乃讀爲譏剌。七賜反。其繆甚矣。"}]},"尣":{"expl":"𤿑，曲脛也。从大，象偏曲之形。凡𡯂之屬皆从𡯂。","rad":"尣","fq":"烏光切","vol":"10","py":"wānɡ","duan":[{"e":"㝿也。","n":"各本少也字。遂不可讀。今補。㝿者、蹇也。尢本曲脛之偁。引申之爲曲脊之偁。故人部僂下曰。𡯭也。"}]},"尳":{"expl":"厀病也。从尣从骨，骨亦聲。","rad":"尣","fq":"戶骨切","vol":"10","py":"hú","duan":[{"e":"厀病也。从尢骨。骨亦聲。","n":"戶骨切。十五部。按此篆當是本在部末。與𡰠爲類。而尢㝿也。㝿蹇也、乃正相屬。"}]},"㝿":{"expl":"蹇也。从𡯂皮聲。","rad":"尣","fq":"布火切","vol":"10","py":"bǒ","duan":[{"e":"蹇也。","n":"足部曰。蹇者、㝿也。二篆爲轉注。㝿俗作跛。或以沾入足部。致正俗複出。非也。今之經傳有跛無㝿。王制公羊、穀梁傳皆作跛。"}]},"㝾":{"expl":"𡯛𡯛，行不正。从𡯂左聲。","rad":"尣","fq":"則箇切","vol":"10","py":"zuǒ","duan":[{"e":"㝾㝾、","n":"各本作㝿㝾。今依宋本說文、宋刻集韵三十八箇正。"}]},"𡯣":{"expl":"行不正也。从𡯂艮聲。讀若燿。","rad":"尣","fq":"弋笑切","vol":"10","py":"yào","duan":[{"e":"行不正也。从尢。㫐聲。讀若燿。","n":"弋𥬇切。二部。"}]},"祲":{"expl":"精氣感祥。从示，㑴省聲。《春秋傳》曰：“見赤黑之𥛆。”","rad":"示","fq":"子林切","vol":"01","py":"jìn","duan":[{"e":"精气感祥。","n":"气氣古今字。周禮眡祲注。祲、陰陽氣相侵漸成祥者。魏志高堂隆傳。孔子曰。災者修類應行。精祲相感。"}]},"芑":{"expl":"白苗嘉榖。从艸己聲。","rad":"艸","fq":"驅里切","vol":"01","py":"qǐ","duan":[{"e":"白苗。","n":"句。"}]},"尲":{"expl":"不正也。从尣兼聲。","rad":"尣","fq":"古咸切","vol":"10","py":"ɡān","duan":[{"e":"尲尬、行不正也。","n":"各本奪尲尬二字。今依全書通例補。又補行字。集韵二十五沾、廣韵二十六咸皆云。尲尬、行不正也。可證。今蘇州俗語謂事乖剌者曰尲尬。"}]},"尬":{"expl":"𡰉𡯗也。从尣介聲。","rad":"尣","fq":"公八切","vol":"10","py":"jiè","duan":[{"e":"尲尬也。","n":"雙聲字。"}]},"尥":{"expl":"行脛相交也。从尣勺聲。牛行腳相交爲尦。","rad":"尣","fq":"力弔切","vol":"10","py":"liào","duan":[{"e":"行脛相交也。","n":"行而脛相交、則行不便利。高注淮南、郭注方言、王注素問皆曰了戾。謂纏繞不適。集韵五爻曰。尥、牛行足外出也。是其意也。今俗語有此。"}]},"𡰖":{"expl":"𤿑不能行，爲人所引，曰𡰖𡰡。从尣从爪，是聲。","rad":"尣","fq":"都兮切","vol":"10","py":"dī","duan":[{"e":"㝿不能行。爲人所引曰𡰖𡰡。","n":"曡韵字也。與提攜義相近。"}]},"𡰢":{"expl":"𡰖𡰡也。从尣从爪，巂聲。","rad":"尣","fq":"戶圭切","vol":"10","py":"xié","duan":[{"e":"𡰖𡰢也。从尢。从爪。巂聲。","n":"戶圭切。十六部。"}]},"㝼":{"expl":"股㝼也。从尣于聲。","rad":"尣","fq":"乙于切","vol":"10","py":"yū","duan":[{"e":"股㝼也。","n":"㝼之言紆也。紆者、詘也。"}]},"𡰠":{"expl":"厀中病也。从尣从羸。","rad":"尣","fq":"郎果切","vol":"10","py":"léi","duan":[{"e":"厀中病也。从尢。羸聲。","n":"郎果切。十七部。廣韵去聲。"}]},"壺":{"expl":"昆吾圜器也。象形。从大，象其蓋也。凡壷之屬皆从壷。","rad":"壺","fq":"戶吳切","vol":"10","py":"hú","duan":[{"e":"昆吾圜器也。","n":"缶部曰。古者昆吾作匋。壷者、昆吾始爲之。聘禮注曰。壷、酒尊也。公羊傳注曰。壺、禮器。腹方口圓曰壷。反之曰方壷。有爵飾。又喪大記狄人出壷、大小戴記投壺、皆壷之屬也。"}]},"㚃":{"expl":"壹㚃也。从凶从壺。不得泄，凶也。《易》曰：“天地壹㚃。”","rad":"壺","fq":"於云切","vol":"10","py":"yūn","duan":[{"e":"𡔹㚃也从凶。从壷。壷不得渫也。","n":"虞翻以否之閉塞釋絪縕。趙岐亦以閉塞釋志壹、氣壹。於云切。十三部。"}]},"壹":{"expl":"專壹也。从壺吉聲。凡壹之屬皆从壹。","rad":"壹","fq":"於悉切","vol":"10","py":"yī","duan":[{"e":"嫥𡔹也。","n":"嫥各本作專。今正。嫥下云。壹也。與此爲轉注。"}]},"藚":{"expl":"水舄也。从艸賣聲。《詩》曰：“言采其藚。”","rad":"艸","fq":"似足切","vol":"01","py":"xù","duan":[{"e":"水舄也。","n":"魏風毛傳同。釋艸。藚、牛脣。"}]},"懿":{"expl":"專久而美也。从壹，从恣省聲。","rad":"壹","fq":"乙冀切","vol":"10","py":"yì","duan":[{"e":"嫥久而美也。","n":"嫥者、壹也。釋詁、詩烝民傳皆曰。懿、美也。周書謚法曰。柔克爲懿。温柔聖善曰懿。許益之以專久者、爲其字从壹也。專壹而後可久。可久而後美。小爾雅及楚辭注。懿、深也。詩七月傳曰。懿、深筐也。深卽專壹之意也。"}]},"㚔":{"expl":"所以驚人也。从大从𢆉。一曰大聲也。凡㚔之屬皆从㚔。一曰讀若瓠。一曰俗語以盜不止爲㚔，㚔讀若籋。","rad":"㚔","fq":"尼輒切","vol":"10","py":"niè","duan":[{"e":"所㠯驚人也。从大。从{丷丅[上下]}。","n":"各本作从𢆉。五經文字曰。說文从大从{丷丅[上下]}。{丷丅[上下]}音干。今依漢石經作幸。又曰。{大丷丅[上下]+丸}{𡘺}者說文。執者、經典相承。凡報之類同是。則張氏所據說文與今本迥異如是。今隷用石經體。且改說文此部皆作幸。非也。今皆正。干者、犯也。其人有大干犯而觸罪。故其義曰所以驚人。其形从大干會意。"}]},"睪":{"expl":"目視也。从橫目，从㚔。令吏將目捕罪人也。","rad":"㚔","fq":"羊益切","vol":"10","py":"yì","duan":[{"e":"司視也。","n":"司者、今之伺字。廣韵作伺。"}]},"執":{"expl":"捕罪人也。从丮从㚔，㚔亦聲。","rad":"㚔","fq":"之入切","vol":"10","py":"zhí","duan":[{"e":"捕辠人也。","n":"辠各本作罪。今依廣韵。手部曰。捕者、取也。引申之爲凡持守之偁。"}]},"圉":{"expl":"囹圄，所以拘罪人。从㚔从囗。一曰圉，垂也。一曰圉人，掌馬者。","rad":"㚔","fq":"魚舉切","vol":"10","py":"yǔ","duan":[{"e":"囹圉、","n":"逗。"}]},"盩":{"expl":"引擊也。从㚔、攴，見血也。扶風有盩厔縣。","rad":"㚔","fq":"張流切","vol":"10","py":"zhōu","duan":[{"e":"引擊也。","n":"引而擊之也。"}]},"報":{"expl":"當罪人也。从㚔从𠬝。𠬝，服罪也。","rad":"㚔","fq":"博号切","vol":"10","py":"bào","duan":[{"e":"當辠人也。","n":"司馬彪百官志曰。廷尉掌平獄。奏當所應。凡郡國讞疑罪。皆處當以報。史記張釋之列傳曰。廷尉奏當。一人犯蹕。當罰金。又曰。廷尉當。是也。又路溫舒上書曰。奏當之成。司馬貞引崔浩云。當謂處其罪也。按當者、漢人語。報、亦漢人語。漢書張湯傳曰。訊鞫論報。蘇林注蘇建傳曰。報、論也。斷獄爲報。是則處分其罪以上聞曰奏當。亦曰報也。引申爲報白、爲報復。又叚爲赴疾之赴。見少儀喪服小記。今俗云急報是也。"}]},"𥷚":{"expl":"窮理罪人也。从㚔从人从言，竹聲。","rad":"㚔","fq":"居六切","vol":"10","py":"jū","duan":[{"e":"竆治辠人也","n":"治各本作理。唐人所改也。今依篇、韵正。辠各本作罪。今依廣韵正。文王世子注曰。讀書論法曰鞠。正義云。讀書、讀囚人之所犯罪狀之書。用法、謂以法律平斷其罪周禮小司寇。讀書用法。先鄭云。如今讀鞫已乃論之。漢書功臣侯表。坐鞠獄不實。如淳云。鞠者、以其辭決罪也。張湯傳。訊鞫論報。張晏云。鞫、一吏爲讀狀論其報行也。㓝法志。遣廷史與郡鞫獄。如淳云。以囚辭決獄爲鞫。謂疑獄也。按鞫者、俗𥷚字。譌作鞠。古言鞫。今言供。語之轉也。今法具犯人口供於前。具勘語擬罪於後。卽周之讀書用法。漢之以辭決罪也。鞫與竆一語之轉。故以竆治罪人釋鞫。引申爲凡竆之偁。谷風、南山、小弁傳曰。竆也。公劉傳曰。究也。節南山傳曰。盈也。究、盈亦竆"}]},"奢":{"expl":"張也。从大者聲。凡奢之屬皆从奢。","rad":"奢","fq":"式車切","vol":"10","py":"shē","duan":[{"e":"張也。","n":"張者、施弓弦也。引伸凡充㡿之偁。侈下曰。一曰奢也。"}]},"奲":{"expl":"富奲奲皃。从奢單聲。","rad":"奢","fq":"丁可切","vol":"10","py":"duǒ","duan":[{"e":"富奲奲皃。","n":"當作奲奲富皃。按此字單聲而入十七部。丁可切。正如鼉、驒亦單聲也。篇、韵昌者一切殆非是。與朶同音、故小徐云謂重而垂也。毛詩桑扈、𨙻二傳皆曰。𨙻、多也。釋詁同。國語。富都𨙻豎。韋注。𨙻、美也。𨙻不知其本字。以許書折衷之、則奲爲本字。𨙻爲叚借字耳。俗用嚲字、訓垂下皃。亦疑奲之變也。"}]},"苳":{"expl":"艸也。从艸冬聲。","rad":"艸","fq":"都宗切","vol":"01","py":"dōnɡ","duan":[{"e":"艸也。从艸。冬聲。","n":"都宗切。九部。籒文作？。"}]},"亢":{"expl":"人頸也。从大省，象頸脈形。凡亢之屬皆从亢。","rad":"亢","fq":"古郎切","vol":"10","py":"ɡānɡ","duan":[{"e":"人頸也。","n":"史、漢張耳。列傳乃仰絕亢而死。韋昭曰。亢、咽也。蘇林云。肮、頸大脈也。俗所謂胡脈。𡝤敬傳。搤其亢。張晏曰。亢、喉嚨也。按釋鳥曰。亢、鳥嚨。此以人頸之偁爲鳥頸之偁也。亢之引申爲高也、舉也、當也。"}]},"𠅣":{"expl":"直項莽𠅣皃。从亢从夋。夋，倨也。亢亦聲。","rad":"亢","fq":"岡朗切","vol":"10","py":"ɡǎnɡ","duan":[{"e":"直項莽𡕬皃。","n":"當作莽𡕬直項皃。或曰淮南書有嚴志頡頏之行。頏卽𡕬字也。頁部曰。頡、直項。"}]},"夲":{"expl":"進趣也。从大从十。大十，猶兼十人也。凡𠦍之屬皆从𠦍。讀若滔。","rad":"夲","fq":"土刀切","vol":"10","py":"tāo","duan":[{"e":"進趣也。","n":"趣者、疾也。"}]},"𠦪":{"expl":"疾也。从𠦍卉聲。拜从此。","rad":"夲","fq":"呼骨切","vol":"10","py":"hū","duan":[{"e":"疾也。","n":"上林賦。藰蒞卉歙。又卉然興道而遷義。郭璞曰。卉猶勃也。西京賦。奮隼歸鳧。沸卉{𠦝+幷[左右]}訇。薛綜曰。奮、迅聲也。卉皆𠦪之叚借。"}]},"曓":{"expl":"疾有所趣也。从日出𠦍廾之。","rad":"夲","fq":"薄報切","vol":"10","py":"bào","duan":[{"e":"疾有所趣也。","n":"趣當作趨。引申爲凡疾之偁。"}]},"𡴞":{"expl":"進也。从𠦍从屮，允聲。《易》曰：“𡴞升大吉。”","rad":"夲","fq":"余準切","vol":"10","py":"yǔn","duan":[{"e":"進也。","n":"㫃部旞下曰。導車所載全羽以爲允。句允、進也。許意謂卽𡴞之省也。"}]},"奏":{"expl":"奏進也。从𠦍从廾从屮。屮，上進之義。","rad":"夲","fq":"則候切","vol":"10","py":"zòu","duan":[{"e":"奏、","n":"此複舉字之未𠜂者。"}]},"皋":{"expl":"气皐白之進也。从𠦍从白。《禮》：祝曰臯，登謌曰奏。故臯奏皆从夲。《周禮》曰：“詔來鼓皐舞。”皐，告之也。","rad":"夲","fq":"古勞切","vol":"10","py":"ɡāo","duan":[{"e":"气皋白之進也。","n":"當作皋气白之進也。皋者、複舉字之未𠜂者也。皋謂气白之進。故其字从白夲。气白之進者、謂進之見於白气滃然者也。皋與㚖同音。㚖訓大白。日部暤訓晧旰。晧旰者、白皃也。暤晧字俗寫多从白。頁部顥訓白皃。皋有訓澤者。小雅鶴鳴傳曰。皋、澤也。澤與皋析言則二。統言則一。如左傳鳩藪澤、牧隰皋並舉。析言也。鶴鳴傳則皋卽澤。澤藪之地。極望數百。沆瀁皛溔。皆白气也。故曰皋。又引申爲凡進之偁。則如禮祝曰皋是也。或叚皋爲櫜。如伏注左傳皋比、卽樂記之建櫜。或叚爲高。如明堂位皋門注云皋之言高也。"}]},"夰":{"expl":"放也。从大而八分也。凡夰之屬皆从夰。","rad":"夰","fq":"古老切","vol":"10","py":"ɡǎo","duan":[{"e":"放也。","n":"放者、逐也。"}]},"𥉁":{"expl":"舉目驚𥉁然也。从夰从䀠，䀠亦聲。","rad":"夰","fq":"九遇切","vol":"10","py":"jù","duan":[{"e":"舉目驚𥉁然也。","n":"廣韵引埤蒼。目驚𥉁𥉁然。襍記下曰。免喪之外。行於道路。見似目瞿。聞名心瞿。二瞿當作𥉁。詩齊風。狂夫瞿瞿。傳曰。無守之皃。唐風。良士瞿瞿。傳曰。瞿瞿然顧禮義也。亦當作𥉁𥉁。"}]},"薔":{"expl":"薔虞，蓼。从艸嗇聲。","rad":"艸","fq":"所力切","vol":"01","py":"sè","duan":[{"e":"薔虞。","n":"句。"}]},"奡":{"expl":"嫚也。从𦣻从夰，夰亦聲。《虞書》曰：“若丹朱奡。”讀若傲。《論語》：“奡湯舟。”","rad":"夰","fq":"五到切","vol":"10","py":"ào","duan":[{"e":"嫚也。","n":"嫚者、侮傷也。傲者、倨也。奡與傲音義皆同。引伸爲排奡。多力皃。"}]},"昦":{"expl":"春爲昦天，元气昦昦。从日、夰，夰亦聲。","rad":"夰","fq":"胡老切","vol":"10","py":"hào","duan":[{"e":"春爲昦天。元气昦昦也。","n":"春爲昦天。釋天文。元气昦昦者、釋昦字之義。黍離毛傳曰。蒼天、以體言之。元氣廣大則偁昊天。仁覆閔下則偁旻天。自上降鑒則偁上天。據遠視之蒼蒼然則偁蒼天。李巡、孫炎、郭璞本爾雅及劉熙釋名皆作春蒼夏昊。許君五經異義、鄭君駁異義所據爾雅及歐陽尙書皆作春昊夏蒼。鄭君云。春氣博施。故以廣大言之。許君尙書堯典羲和以昊天緫勅四時。故知昊天不獨春也。許君作異義時、是毛傳。非爾雅歐陽尙書。鄭君駁之。而許造說文於昊下、旻下皆用爾雅。參合毛傳。略同鄭說。說文解字爲定說也。"}]},"臩":{"expl":"驚走也。一曰往來也。从夰、臦。《周書》曰：“伯臩。”古文臦，古文囧字。","rad":"夰","fq":"具往切","vol":"10","py":"ɡuǎnɡ","duan":[{"e":"驚走也。一曰往來皃。","n":"皃大徐作也。非。"}]},"亣":{"expl":"籒文亣，改古文。亦象人形。凡亣之屬皆从亣。","rad":"亣","fq":"他達切","vol":"10","py":"dà","duan":[{"e":"亦象人形。","n":"亦者、亦古文也。<大>象人形。此亦象人形。其字同、則其音同也。而大徐云<大>徒葢切、<亦>他達切。分別殊誤。古去入不分。凡今去聲之字、古皆入聲。大讀入聲者、今惟有會稽大末縣。獨存古語耳。實則凡大皆可入。非古文去、籒文入之謂。"}]},"奕":{"expl":"大也。从亣亦聲。《詩》曰：“奕奕梁山。”","rad":"亣","fq":"羊益切","vol":"10","py":"yì","duan":[{"e":"大也。","n":"大雅。奕奕梁山。傳曰。奕奕、大也。詩周頌箋云。亦、大也。叚亦爲奕。"}]},"奘":{"expl":"駔大也。从亣从壯，壯亦聲。","rad":"亣","fq":"徂朗切","vol":"10","py":"zànɡ","duan":[{"e":"駔大也。","n":"馬部駔下曰。壯馬也。士部壯下曰。大也。奘與壯音同。與駔義同。釋言曰。奘、駔也。此許所本也。孫、樊本作將且也。"}]},"㚖":{"expl":"大白、澤也。从亣从白。古文以爲澤字。","rad":"亣","fq":"古老切","vol":"10","py":"ɡǎo","duan":[{"e":"大白也。","n":"各本白下有澤字。其誤不知始於何時。獸名白澤。故非經典卽有此物。孰別其大小乎。全書之例。於形得義之字不可勝計。㚖以白大會意。則訓之曰大白也。猶下文大在一上則爲立耳。淺人𡚶增。玉篇、唐韵仍之。說石𡔷文者又引爲證。古來郢書燕說類多如此。"}]},"奚":{"expl":"大腹也。从亣，𦃟省聲。𦃟，籒文系字。","rad":"亣","fq":"胡雞切","vol":"10","py":"xī","duan":[{"e":"大腹也。","n":"豕部豯下曰。豚生三月、腹豯豯皃。古奚豯通用。周禮職方氏豯養。杜子春讀豯爲奚。許艸部作奚養。"}]},"耎":{"expl":"稍前大也。从亣而聲。讀若畏偄。","rad":"亣","fq":"而沇切","vol":"10","py":"ruǎn","duan":[{"e":"稍歬大也。","n":"稍者、出物有漸也。稍前大者、前較大於後也。"}]},"𡚇":{"expl":"大皃。从亣𥆞聲。或曰拳勇字。一曰讀若傿。","rad":"亣","fq":"乙獻切","vol":"10","py":"yàn","duan":[{"e":"大皃。从亣。{𥆞+一[上下]}聲。","n":"{𥆞+一[上下]}讀若書卷之卷。見四篇。"}]},"苕":{"expl":"艸也。从艸召聲。","rad":"艸","fq":"徒聊切","vol":"01","py":"tiáo","duan":[{"e":"艸也。","n":"詩苕之華。"}]},"𡚤":{"expl":"壯大也。从三大三目。二目爲𥆞，三目爲𡚤，益大也。一曰迫也。讀若《易》虙羲氏。《詩》曰：“不醉而怒謂之𡚤。”","rad":"亣","fq":"平祕切","vol":"10","py":"bì","duan":[{"e":"壯大也。从三大三目。","n":"會意。"}]},"夫":{"expl":"丈夫也。从大，一以象簪也。周制以八寸爲尺，十尺爲丈。人長八尺，故曰丈夫。凡夫之屬皆从夫。","rad":"夫","fq":"甫無切","vol":"10","py":"fū","duan":[{"e":"丈夫也。从<亣>一。","n":"从一大則爲天。从大一則爲夫。於此見人與天同也。天之一、冒大上。爲會意。夫之一、毌大首。爲象形。亦爲會意。"}]},"規":{"expl":"有法度也。从夫从見。","rad":"夫","fq":"居隨切","vol":"10","py":"ɡuī","duan":[{"e":"規巨、有灋度也。","n":"各本無規巨二字。今補於此。說規矩二字之義。故工部巨下但云規巨也。此許全書之通例也。𦥓部𣬈下曰。𣬈𪗌、人𪗌也。故肉部𪗌下曰。𣬈𪗌也。正同此。圜出於方。方出於矩。古規矩二字不分用。猶威儀二字不分用也。凡規巨、威儀有分用者皆互文見意。非圜不必矩、方不必規也。灋者、㓝也。度者、灋制也。規矩者、有灋度之謂也。萑部曰。規蒦、商也。一曰蒦、度也。凡有所圖度匡正皆曰規。左傳。規求無度。陶淵明文。欣然規往。左傳曰。大夫規誨。詩序曰。沔水、規宣王也。"}]},"㚘":{"expl":"竝行也。从二夫。輦字从此。讀若伴侶之伴。","rad":"夫","fq":"薄旱切","vol":"10","py":"bàn","duan":[{"e":"竝行也。从二夫。","n":"會意。"}]},"立":{"expl":"住也。从大立一之上。凡立之屬皆从立。","rad":"立","fq":"力入切","vol":"10","py":"lì","duan":[{"e":"侸也。","n":"侸各本作住。今正。人部曰。侸者、立也。與此爲互訓。淺人易爲住字。亦許書之所無。"}]},"䇐":{"expl":"臨也。从立从隶。","rad":"立","fq":"力至切","vol":"10","py":"lì","duan":[{"e":"臨也。","n":"臨者、監也。經典蒞字或作涖。注家皆曰臨也。道德經釋文云。古無莅字。說文作䇐。按莅行而䇐廢矣。凡有正字而爲叚借字所敚敓者類此。"}]},"䇏":{"expl":"磊䇏，重聚也。从立𦎫聲。","rad":"立","fq":"丁罪切","vol":"10","py":"duì","duan":[{"e":"磊𥫉、","n":"曡韵字。今俗語猶有之。"}]},"端":{"expl":"直也。从立耑聲。","rad":"立","fq":"多官切","vol":"10","py":"duān","duan":[{"e":"直也。","n":"用爲發耑、耑緒字者叚借也。"}]},"竱":{"expl":"等也。从立專聲。《春秋國語》曰：“竱本肇末。”","rad":"立","fq":"旨兖切","vol":"10","py":"zhuǎn","duan":[{"e":"等也。","n":"等者、齊𥳑也。故凡齊皆曰等。齊語。竱本肈末。韋注。竱、等也。肈、正也。謂先等其本以正其末。按孟子曰。不揣其本而齊其末。揣葢竱之叚借字。耑聲、專聲同部。趙注云揣量。似失之。木部椯下曰。一曰度也。孟子正當从木作椯。韵書謂偁量曰故敪。丁兼丁括切。卽竱語之轉也。"}]},"竦":{"expl":"敬也。从立从束。束，自申束也。","rad":"立","fq":"息拱切","vol":"10","py":"sǒnɡ","duan":[{"e":"敬也。","n":"敬者、肅也。商頌傳曰。竦、懼也。此謂叚竦爲愯也。愯者、懼也。𠬞下曰。竦手。謂手容之恭上其手也。周南毛傳曰。喬上竦也。"}]},"𦼪":{"expl":"艸也。从艸楙聲。","rad":"艸","fq":"莫厚切","vol":"01","py":"mào","duan":[{"e":"艸也。从艸。楙聲。","n":"莫厚切。三部。籒文作𧃺。"}]},"竫":{"expl":"亭安也。从立爭聲。","rad":"立","fq":"疾郢切","vol":"10","py":"jìnɡ","duan":[{"e":"亭安也。","n":"亭者民所安定也。故安定曰亭安。其字俗作停、作渟。亭與竫曡韵。凡安靜字宜作竫、靜其叚借字也。靜者、審也。"}]},"靖":{"expl":"立竫也。从立青聲。一曰細皃。","rad":"立","fq":"疾郢切","vol":"10","py":"jìnɡ","duan":[{"e":"立竫也。","n":"謂立容安竫也。安而後能慮。故釋詁、毛傳皆曰靖、謀也。"}]},"竢":{"expl":"待也。从立矣聲。","rad":"立","fq":"牀史切","vol":"10","py":"sì","duan":[{"e":"待也。","n":"彳部曰。待、竢也。是爲轉注。經傳多叚俟爲之。俟行而竢廢矣。俟、大也。"}]},"竘":{"expl":"健也。一曰匠也。从立句聲。讀若齲。《逸周書》有竘匠。","rad":"立","fq":"丘羽切","vol":"10","py":"qǔ","duan":[{"e":"健也。","n":"淮南人閒訓。室始成。竘然善也。高注。竘、高壯皃。此與健之訓合。"}]},"竵":{"expl":"不正也。从立𩰬聲。","rad":"立","fq":"火鼃切","vol":"10","py":"huā","duan":[{"e":"不正也。从立。𩰫聲。","n":"火鼃切古音在十六部俗字作歪"}]},"竭":{"expl":"負舉也。从立曷聲。","rad":"立","fq":"渠列切","vol":"10","py":"jié","duan":[{"e":"負舉也。","n":"凡手不能舉者、負而舉之。禮運。五行之動。迭相竭也。注。竭猶負戴也。豕部曰。竭其尾。李尤翰林論云。木氏海賦。壯則壯矣。然首尾負竭。狀若文章。亦將由未成而然也。"}]},"𩓣":{"expl":"待也。从立須聲。","rad":"立","fq":"相俞切","vol":"10","py":"xū","duan":[{"e":"立而待也。","n":"依韵會補立而二字。今字多作需、作須、而䇓廢矣。雨部曰。需、䇓也。遇雨不進止䇓也。引易云上於天需。需與䇓音義皆同。樊遲名須。須者、䇓之叚借。䇓字僅見漢書翟方進傳。"}]},"䇔":{"expl":"痿也。从立𣎆聲。","rad":"立","fq":"力臥切","vol":"10","py":"luò","duan":[{"e":"痿也。","n":"痿者痹也。"}]},"竣":{"expl":"偓竣也。从立夋聲。《國語》曰：“有司巳事而竣。”","rad":"立","fq":"七倫切","vol":"10","py":"jùn","duan":[{"e":"居也。","n":"各本作偓竣也。說者謂卽偓佺。今正。𡰣部曰。居、蹲也。足部曰。居、蹲也。郭注山海經、徐廣史記音義皆曰。踆古蹲字。許書之竣、葢與蹲音義皆同也。居譌倨。倨譌偓。竣乃複舉字。倒於下、遂爲偓竣矣。古書之譌舛可正者類如此。固在好學深思。心知其意也。廣韵曰。倨也。此居譌倨之證。"}]},"𥪋":{"expl":"見鬼鬽皃。从立从录。录，籒文鬽字。讀若虙羲氏之虙。","rad":"立","fq":"房六切","vol":"10","py":"fú","duan":[{"e":"見鬼鬽皃。从立。从彔。","n":"會意。"}]},"萺":{"expl":"艸也。从艸冒聲。","rad":"艸","fq":"莫報切","vol":"01","py":"mào","duan":[{"e":"艸也。从艸。冒聲。","n":"莫報切。古音在三部。籒文作？。"}]},"䇎":{"expl":"驚皃。从立昔聲。","rad":"立","fq":"七雀切","vol":"10","py":"què","duan":[{"e":"驚皃。","n":"與獡音義同。獡見方言。"}]},"䇑":{"expl":"短人立䇑䇑皃。从立卑聲。","rad":"立","fq":"傍下切","vol":"10","py":"bà","duan":[{"e":"短人立䇑䇑皃。","n":"䇑䇑、短皃。䇑之字或作罷。周禮典同注。陂讀爲人短罷之罷。司弓矢庳矢注。鄭司農讀爲人罷短之罷。或作矲。方言曰。啙、矲、短也。桂林之中謂短矲。郭注言矲雉也。按矲皮買反。雉苦買反。今本方言雉譌作𥏪。典同繹文雉譌作矮。依集韵、類篇、宋余仁仲周禮所載釋文、明葉林宗所寫釋文正之。雉从矢、佳聲。非雉字也。"}]},"竲":{"expl":"北地高樓無屋者。从立曾聲。","rad":"立","fq":"七耕切","vol":"10","py":"cénɡ","duan":[{"e":"北地高樓無屋者。","n":"此地郡也。高樓上不爲覆曰竲。禮運曰。夏則居曾巢。鄭曰。暑則聚薪柴居其上也。此竲之始也。禮運本又作竲。"}]},"竝":{"expl":"併也。从二立。凡竝之屬皆从竝。","rad":"竝","fq":"蒲迥切","vol":"10","py":"bìnɡ","duan":[{"e":"倂也。","n":"人部倂下曰。竝也。二篆爲轉注。鄭注禮經古文竝今文多作倂。是二字音義皆同之故也。古書亦多用爲傍字者。傍、附也。"}]},"𤾕":{"expl":"廢，一偏下也。从竝白聲。","rad":"竝","fq":"他計切","vol":"10","py":"tì","duan":[{"e":"廢也。","n":"各本奪也字。不可讀。今補。廢者、卻屋也。卻屋言空屋。人所不居。故𤾕廢同義。"}]},"囟":{"expl":"頭會，匘蓋也。象形。凡囟之屬皆从囟。","rad":"囟","fq":"息進切","vol":"10","py":"xìn","duan":[{"e":"頭會匘葢也。","n":"首之會合處。頭𩪦之覆葢。玄應引葢下有頟空二字。頟空、謂頟腔也。內則注曰。夾𦥓曰角。"}]},"巤":{"expl":"毛巤也。象髮在囟上及毛髮巤巤之形。此與籒文子字同。","rad":"囟","fq":"良涉切","vol":"10","py":"liè","duan":[{"e":"毛巤也。象髮在𦥓上。","n":"謂𡿺也。𩠐下曰。巛象髮。髮謂之鬊。鬊卽巛也。"}]},"𣬈":{"expl":"人臍也。从囟，囟，取气通也；从比聲。","rad":"囟","fq":"房脂切","vol":"10","py":"pí","duan":[{"e":"𣬈𠬐、","n":"逗。各本奪此二字。今訂補。玄應引許𣬈𪗌、人𪗌也。按肉部𪗌下曰。𣬈𪗌也。正以𣬈𪗌之解已見𦥓部。全書之大例如此。"}]},"思":{"expl":"容也。从心囟聲。凡思之屬皆从思。","rad":"思","fq":"息兹切","vol":"10","py":"sī","duan":[{"e":"䜭也。","n":"䜭也各本作容也。或以伏生尙書思心曰容說之。今正。皃曰恭、言曰從、視曰明、聽曰聰、思心曰容、謂五者之德。非可以恭釋皃、以從釋言、以明聰釋視聽也。谷部曰。䜭者、深通川也。引䜭畎澮歫川。引申之、凡深通皆曰䜭。思與䜭雙聲。此亦門捫也。戸護也、髮拔也之例。謂之思者、以其能深通也。至若尙書大傳次五事曰思心。思心之不容。是謂不聖。劉向、董仲舒、班固皆以寬釋容。與古文尙書作五曰思、思曰䜭爲異本。詳子所述尙書𢰅異。"}]},"慮":{"expl":"謀思也。从思虍聲。","rad":"思","fq":"良據切","vol":"10","py":"lǜ","duan":[{"e":"謀思也。","n":"心部曰。念、常思也。惟、凡思也。懷、念思也。想、覬、思也。𢣢、同思之和也。同一思而分別如此。言部曰。慮難曰謀。與此爲轉注。囗部曰。圖者、畫也。計難也。然則謀慮圖三篆義同。左傳曰慮無他。書曰無慮。皆謂計畫之纖悉必周。有不周者非慮也。"}]},"𦯆":{"expl":"鳧葵也。从艸戼聲。《詩》曰：“言采其𦯆。”","rad":"艸","fq":"力久切","vol":"01","py":"mǎo","duan":[{"e":"鳧葵也。","n":"魯頌毛傳同。周禮醢人茆菹。鄭大夫讀爲茅。或曰。茆、水艸。杜子春讀爲𦯄。後鄭曰。𦯄、鳧葵也。今周禮轉寫多譌誤。爲正之如此。漢時有茆、𦯄二字。經文作茆。兩鄭皆易字爲𦯄也。鳧葵名𦯄。亦名䖂。今之蒓菜也。𦯄不與䖂類廁者、以篆籒別之。"}]},"心":{"expl":"人心，土藏，在身之中。象形。博士說以爲火藏。凡心之屬皆从心。","rad":"心","fq":"息林切","vol":"10","py":"xīn","duan":[{"e":"人心。土臧也。","n":"也字補。"}]},"息":{"expl":"喘也。从心从自，自亦聲。","rad":"心","fq":"相即切","vol":"10","py":"xī","duan":[{"e":"喘也。","n":"口部曰。喘、疾息也。喘爲息之疾者析言之。此云息者喘也、渾言之。人之氣急曰喘。舒曰息。引伸爲休息之偁。又引伸爲生長之偁。引伸之義行而鼻息之義廢矣。詩曰。使我不能息兮。傳曰。憂不能息也。黍離傳曰。噎憂不能息也。此息之本義也。其他詩息字皆引伸之義也。許書齂、臥息也。呬、息也。㞒、臥息也。䯉、咽中息不利也。<欠>、飲食屰气不得息也。覞部䨳、見雨而比息也。皆本義也。"}]},"情":{"expl":"人之陰气有欲者。从心青聲。","rad":"心","fq":"疾盈切","vol":"10","py":"qínɡ","duan":[{"e":"人之侌气有欲者。","n":"董仲舒曰。情者、人之欲也。人欲之謂情。情非制度不節。禮記曰。何謂人情喜怒哀懼愛惡欲。七者不學而能。左傳曰。民有好惡喜怒哀樂。生於六氣。孝經援神契曰。性生於陽以理執。情生於陰以繫念。"}]},"性":{"expl":"人之陽气性善者也。从心生聲。","rad":"心","fq":"息正切","vol":"10","py":"xìnɡ","duan":[{"e":"人之昜气性。","n":"句。"}]},"𢖽":{"expl":"意也。从心之聲。","rad":"心","fq":"職吏切","vol":"10","py":"zhì","duan":[{"e":"意也。从心𡳿。𡳿亦聲。","n":"按此篆小徐本無。大徐以意下曰志也補此爲十九文之一。原作从心之聲。今又增二字。依大徐次於此。志所以不錄者、周禮保章氏注云。志古文識。葢古文有志無識。小篆乃有識字。保章注曰。志古文識。識、記也。哀公問注曰。志讀爲識。識、知也。今之識字、志韵與職韵分二解。而古不分二音。則二解義亦相通。古文作志。則志者、記也、知也。惠定宇曰。論語賢者識其大者、蔡邕石經作志。多見而識之、白虎通作志。左傳曰以志吾過。又曰且曰志之。又曰歲聘以志業。又曰吾志其目也。尙書曰若射之有志。士喪禮志矢注云志猶擬也。今人分志向一字。識記一字。知識一字。古衹有一字一音。又旗幟亦卽用識字。則亦可用志字。詩序曰。詩者、志之所之也。在心爲志。"}]},"意":{"expl":"志也。从心察言而知意也。从心从音。","rad":"心","fq":"於記切","vol":"10","py":"yì","duan":[{"e":"志也。","n":"志卽識。心所識也。意之訓爲測度、爲記。訓測者、如論語毋意毋必、不逆詐、不億不信、億則屢中。其字俗作億。訓記者、如今人云記憶是也。其字俗作憶。大學曰。欲正其心者。先誠其意。誠謂實其心之所識也。如惡惡臭。如好好色。此之謂自謙。鄭云謙讀爲慊。慊之言厭也。按厭當爲猒。猒者、足也。"}]},"恉":{"expl":"意也。从心旨聲。","rad":"心","fq":"職雉切","vol":"10","py":"zhǐ","duan":[{"e":"意也。","n":"今字或作旨、或作指。皆非本字也。許序曰。曉學者達神恉。"}]},"悳":{"expl":"外得於人，内得於己也。从直从心。","rad":"心","fq":"多則切","vol":"10","py":"dé","duan":[{"e":"外得於人。內得於己也。","n":"此當依小徐通論作內得於己。外得於人。內得於己、謂身心所自得也。外得於人、謂惠澤使人得之也。俗字叚德爲之。德者、升也。古字或叚得爲之。"}]},"應":{"expl":"當也。从心𤸰聲。","rad":"心","fq":"於陵切","vol":"10","py":"yīnɡ","duan":[{"e":"當也。","n":"當、田相值也。引伸爲凡相對之偁。凡言語應對之字卽用此。大徐言部增譍字。非也。諾下、讎下、唉下、對下譍字皆當改正。"}]},"愼":{"expl":"謹也。从心眞聲。","rad":"心","fq":"時刃切","vol":"10","py":"shèn","duan":[{"e":"謹也。","n":"言部曰。謹者、愼也。二篆爲轉注。未有不誠而能謹者。故其字从眞。小雅。愼爾優游。予愼無罪。傳皆曰。誠也。詳八篇眞下。"}]},"荼":{"expl":"苦荼也。从艸余聲。","rad":"艸","fq":"同都切","vol":"01","py":"tú","duan":[{"e":"苦荼也。","n":"釋艸、邶毛傳皆云。荼、苦菜。唐風采苦采苦傳云。苦、苦菜。然則苦與荼正一物也。儀禮。鈃芼。牛藿、羊苦、豕薇。記内則。濡豚包苦。亦謂之苦。月令、本艸、易通卦驗皆謂之苦菜。"}]},"忠":{"expl":"敬也。从心中聲。","rad":"心","fq":"陟弓切","vol":"10","py":"zhōnɡ","duan":[{"e":"敬也。","n":"敬者、肅也。未有盡心而不敬者。此與愼訓謹同義。"}]},"愨":{"expl":"謹也。从心𣪊聲。","rad":"心","fq":"苦角切","vol":"10","py":"què","duan":[{"e":"謹也。","n":"廣韵曰。謹也、善也、願也、誠也。據韵會、大司寇注。願、殼愼也。用叚借字。殼者、𣪊之俗字也。"}]},"𢤧":{"expl":"美也。从心䫉聲。","rad":"心","fq":"莫角切","vol":"10","py":"miǎo","duan":[{"e":"美也。从心。䫉聲。","n":"莫角切。二部。"}]},"快":{"expl":"喜也。从心夬聲。","rad":"心","fq":"苦夬切","vol":"10","py":"kuài","duan":[{"e":"喜也。","n":"引申之義爲疾速。俗字作駃。"}]},"㥦":{"expl":"快心。从心匧聲。","rad":"心","fq":"苦叶切","vol":"10","py":"qiè","duan":[{"e":"快也。","n":"漢文帝紀曰。未有㥦志。"}]},"念":{"expl":"常思也。从心今聲。","rad":"心","fq":"奴店切","vol":"10","py":"niàn","duan":[{"e":"常思也。","n":"方言曰。念、思也。又曰。念、常思也。許云。懷、念思也。左傳引夏書曰。念茲在茲。釋茲在茲。名言茲在茲。允出茲在茲。惟帝念功。"}]},"怤":{"expl":"思也。从心付聲。","rad":"心","fq":"甫無切","vol":"10","py":"fū","duan":[{"e":"思也。从心。付聲。","n":"甫無切。五部。"}]},"憲":{"expl":"敏也。从心从目，害省聲。","rad":"心","fq":"許建切","vol":"10","py":"xiàn","duan":[{"e":"敏也。","n":"敏者、疾也。謚法。博聞多能爲憲。引申之義爲法也。又中庸引詩憲憲令德。以憲憲爲顯顯。又大雅。天之方難。無然憲憲。傳曰。憲憲猶欣欣也。皆叚借也。"}]},"憕":{"expl":"平也。从心登聲。","rad":"心","fq":"直陵切","vol":"10","py":"chénɡ","duan":[{"e":"平也。从心。登聲。","n":"直陵切。六部。"}]},"𦾴":{"expl":"白蒿也。从艸繁聲。","rad":"艸","fq":"附袁切","vol":"01","py":"fán","duan":[{"e":"白蒿也。","n":"釋艸、豳毛傳同。召南傳曰。皤蒿也。皤亦白也。夏小正曰。繁、由胡。由胡者、繁母也。繁、旁勃也。豆實也。故記之。"}]},"戁":{"expl":"敬也。从心難聲。","rad":"心","fq":"女版切","vol":"10","py":"nǎn","duan":[{"e":"敬也。","n":"敬者、肅也。商頌。不戁不竦。傳曰。戁恐。竦、懼也。敬則必恐懼。故傳說其引申之義。若小雅我恐熯矣傳曰熯、敬也。此謂詩叚熯爲戁。"}]},"忻":{"expl":"闓也。从心斤聲。《司馬法》曰：“善者，忻民之善，閉民之惡。”","rad":"心","fq":"許斤切","vol":"10","py":"xīn","duan":[{"e":"闓也。","n":"闓者、開也。言闓不言開者、闓與忻音近。如昕讀若𢁫之類也。忻謂心之開發。與欠部欣謂笑喜也異義。廣韵合爲一字。今義非古義也。"}]},"𢝆":{"expl":"遟也。从心重聲。","rad":"心","fq":"直隴切","vol":"10","py":"zhònɡ","duan":[{"e":"遲也。","n":"遲重之字當作此。今皆叚重字爲之。今字也。"}]},"惲":{"expl":"重厚也。从心軍聲。","rad":"心","fq":"於粉切","vol":"10","py":"yùn","duan":[{"e":"重厚也。","n":"厚當作𣆪。惲厚字當如此。今皆作渾厚。非是。渾者、混流聲也。今俗云水渾。"}]},"惇":{"expl":"厚也。从心𦎫聲。","rad":"心","fq":"都昆切","vol":"10","py":"dūn","duan":[{"e":"厚也。","n":"厚當作𣆪。凡𢤈厚字當作此。今多作𣀦厚。叚借。非本字。𣀦者、怒也。詆也。一曰誰何也。雒誥。𢤈大成裕。"}]},"忼":{"expl":"慨也。从心亢聲。一曰《易》“忼龍有悔”。","rad":"心","fq":"苦浪切","vol":"10","py":"kànɡ","duan":[{"e":"忼慨也。","n":"各本奪忼。字今補。"}]},"慨":{"expl":"忼慨，壯士不得志也。从心旣聲。","rad":"心","fq":"古溉切","vol":"10","py":"kǎi","duan":[{"e":"忼慨也。","n":"依全書通例正。忼慨雙聲也。他書亦叚愾爲之。作忼愾。"}]},"悃":{"expl":"愊也。从心困聲。","rad":"心","fq":"苦本切","vol":"10","py":"kǔn","duan":[{"e":"𢛕愊、","n":"逗。"}]},"愊":{"expl":"誠志也。从心畐聲。","rad":"心","fq":"芳逼切","vol":"10","py":"bì","duan":[{"e":"𢛕愊也。","n":"各本作誠志也。今依全書通例訂。"}]},"愿":{"expl":"謹也。从心原聲。","rad":"心","fq":"魚怨切","vol":"10","py":"yuàn","duan":[{"e":"謹也。","n":"咎繇謨曰。愿而恭。"}]},"禍":{"expl":"害也，神不福也。从示咼聲。","rad":"示","fq":"胡果切","vol":"01","py":"huò","duan":[{"e":"害也。","n":"禍害雙聲。"}]},"蒿":{"expl":"菣也。从艸高聲。","rad":"艸","fq":"呼毛切","vol":"01","py":"hāo","duan":[{"e":"菣也。","n":"釋艸、小雅毛傳同。陸璣曰。靑蒿也。"}]},"慧":{"expl":"儇也。从心彗聲。","rad":"心","fq":"胡桂切","vol":"10","py":"huì","duan":[{"e":"儇也。","n":"人部曰。儇、慧也。二篆爲轉注。慧古多叚惠爲之。"}]},"憭":{"expl":"慧也。从心尞聲。","rad":"心","fq":"力小切","vol":"10","py":"liǎo","duan":[{"e":"慧也。","n":"方言。愈或謂之慧。或謂之憭。郭云。慧憭皆意精明。按廣韵曰。了者、慧也。葢今字叚了爲憭。故郭注方言已云慧了。他書皆云了了。若論字之本義。則了爲尦也。尦者、行脛相交也。"}]},"恔":{"expl":"憭也。从心交聲。","rad":"心","fq":"下交切","vol":"10","py":"xiáo","duan":[{"e":"憭也。","n":"曡韵互訓。按方言。恔、快也。東齊海岱之閒曰恔。孟子。放人心獨無恔乎。趙注。恔、快也。快卽憭義之引申。凡明憭者、必快於心也。"}]},"瘱":{"expl":"靜也。从心㾜聲。","rad":"心","fq":"於計切","vol":"10","py":"yì","duan":[{"e":"靜也。","n":"靜當作竫。亭安也。此篆或作嫕。見後漢書。傳寫誤爲嬺。洞簫賦曰。淸靜厭瘱。神女賦曰。澹淸靜其愔瘱。李善引韓詩曰。瘱、悅也。引蒼頡篇曰。瘱、密也。引曹大家列女傳注曰。瘱、深邃也。"}]},"悊":{"expl":"敬也。从心折聲。","rad":"心","fq":"陟列切","vol":"10","py":"zhé","duan":[{"e":"敬也。","n":"口部哲下曰。知也。悊與哲義殊。口部云。哲或从心作悊。葢淺人妄增之。因古書聖哲字或从心而合之也。"}]},"悰":{"expl":"樂也。从心宗聲。","rad":"心","fq":"藏宗切","vol":"10","py":"cónɡ","duan":[{"e":"樂也。","n":"此哀樂字也。𨕖詩。戚戚苦無悰。"}]},"恬":{"expl":"安也。从心，甛省聲。","rad":"心","fq":"徒兼切","vol":"10","py":"tián","duan":[{"e":"安也。","n":"莊子曰。以恬養知。以知養恬。"}]},"恢":{"expl":"大也。从心灰聲。","rad":"心","fq":"苦回切","vol":"10","py":"huī","duan":[{"e":"大也。从心。灰聲。","n":"苦回切。十五部。"}]},"恭":{"expl":"肅也。从心共聲。","rad":"心","fq":"俱容切","vol":"10","py":"ɡōnɡ","duan":[{"e":"肅也。","n":"肅者、持事振敬也。尙書曰。恭作肅。此以肅釋恭者、析言則分別。渾言則互明也。論語每恭敬析言。如居處恭執事敬、貌思恭、事思敬皆是。"}]},"憼":{"expl":"敬也。从心从敬，敬亦聲。","rad":"心","fq":"居影切","vol":"10","py":"jǐnɡ","duan":[{"e":"敬也。","n":"敬之在心者也。"}]},"蓬":{"expl":"蒿也。从艸逢聲。","rad":"艸","fq":"薄紅切","vol":"01","py":"pénɡ","duan":[{"e":"蒿也。从艸。逢聲。","n":"薄紅切。九部。籒文作？。"}]},"恕":{"expl":"仁也。从心如聲。","rad":"心","fq":"商署切","vol":"10","py":"shù","duan":[{"e":"仁也。","n":"孔子曰。能近取譬。可謂仁之方也矣。孟子曰。彊恕而行。求仁莫近焉。是則爲仁不外於恕。析言之則有別。渾言之則不別也。仁者、親也。"}]},"怡":{"expl":"和也。从心台聲。","rad":"心","fq":"與之切","vol":"10","py":"yí","duan":[{"e":"龢也。","n":"各本作和。今正。龢者、調也。玉篇曰。怡者、悅也。樂也。古多叚台字。禹貢。祗台德先。鄭注云。敬和。"}]},"慈":{"expl":"愛也。从心兹聲。","rad":"心","fq":"疾之切","vol":"10","py":"cí","duan":[{"e":"㤅也。","n":"㤅各本作愛。今正。下文曰。㤅、惠也。軎部曰。惠、仁也。人部曰。仁、親也。"}]},"忯":{"expl":"愛也。从心氏聲。","rad":"心","fq":"巨支切","vol":"10","py":"qí","duan":[{"e":"㤅也。","n":"㤅各本作𢜤。今正。釋訓曰。忯忯、𢜤也。按忯忯字不見於詩書。"}]},"㥴":{"expl":"忯㥴，不憂事也。从心虒聲。讀若移。","rad":"心","fq":"移尔切","vol":"10","py":"yǐ","duan":[{"e":"忯㥴、","n":"逗。曡韵字。"}]},"恮":{"expl":"謹也。从心全聲。","rad":"心","fq":"此緣切","vol":"10","py":"quān","duan":[{"e":"謹也。","n":"廣韵也作皃。"}]},"恩":{"expl":"惠也。从心因聲。","rad":"心","fq":"烏痕切","vol":"10","py":"ēn","duan":[{"e":"惠也。从心因。因亦聲。","n":"依韵會訂。烏㾗切。十三部。"}]},"慸":{"expl":"高也。一曰極也。一曰困劣也。从心帶聲。","rad":"心","fq":"特計切","vol":"10","py":"dì","duan":[{"e":"高也。","n":"集韵曰。岹嵽、山形。音義同。"}]},"憖":{"expl":"問也。謹敬也。从心猌聲。一曰說也。一曰甘也。《春秋傳》曰：“昊天不憖。”又曰：“兩君之士皆未憖。”","rad":"心","fq":"魚覲切","vol":"10","py":"yìn","duan":[{"e":"肎也。","n":"各本作問也。玉篇作閒也。左傳音義引字林閒也。閒者、肎之誤。問者、閒之誤。十月正義引憖、肯從心也。當是引憖、肎也。从心、猌聲。誤以也字倒於从心之下。不成文理耳。今依肎字。小爾雅曰。憖、願也。晉語。伯宗妻曰。憖庇州犁焉。韋注曰。憖願也。願與肯義略同。用部曰。甯、所願也。丂部曰。寧、願詞也。皆與憖雙聲。"}]},"懬":{"expl":"闊也。一曰廣也，大也。一曰寬也。从心从廣，廣亦聲。","rad":"心","fq":"苦謗切","vol":"10","py":"kuànɡ","duan":[{"e":"闊也。廣大也。","n":"各本作廣也、大也。今依詩泮水釋文訂。魯頌泮水曰。憬彼淮夷。釋文云。憬說文作懬。按許闊也、一曰廣大也。此懬之本義。毛云。遠行也。卽其引伸之義也。由其廣大。故必遠行。然則毛詩自作懬。今作憬者、或以三家詩改之也。元帝紀。眾僚久懬。未得其人。假懬爲曠字。"}]},"藜":{"expl":"艸也。从艸黎聲。","rad":"艸","fq":"郎奚切","vol":"01","py":"lí","duan":[{"e":"艸也。","n":"左傳。斬之蓬蒿藜藋。藜初生可食。故曰蒸藜不孰。小雅。北山有萊。陸機云。萊、兗州人蒸以爲茹。謂之萊蒸。按萊蒸葢卽蒸藜。如詩騋牝訓驪牝也。"}]},"悈":{"expl":"飾也。从心戒聲。《司馬法》曰：“有虞氏悈於中國。”","rad":"心","fq":"古拜切","vol":"10","py":"jiè","duan":[{"e":"飭也。","n":"飭各本作飾。古書飾飭多互譌。不可勝正。力部曰。飭、致堅也。悈與戒義同。警也。釋言曰。悈褊急也。許言部諽字下曰。飭也。讀若悈。葢悈音紀力反。與茍、戒、棘、亟音義皆同。而方言曰。悈、革、老也。此又因揫斂之義而引伸之也。"}]},"㥯":{"expl":"謹也。从心𤔌聲。","rad":"心","fq":"於靳切","vol":"10","py":"yǐn","duan":[{"e":"謹也。从心。𤔌聲。","n":"於靳切。十三部。"}]},"慶":{"expl":"行賀人也。从心从夂。吉禮以鹿皮爲贄，故从鹿省。","rad":"心","fq":"丘竟切","vol":"10","py":"qìnɡ","duan":[{"e":"行賀人也。","n":"賀下曰。以禮相奉慶也。是二篆爲轉注也。賀从貝。故云以以禮相奉。慶从夊。故云行賀人。"}]},"愃":{"expl":"寬嫺心腹皃。从心宣聲。《詩》曰：“赫兮愃兮。”","rad":"心","fq":"況晚切","vol":"10","py":"xuǎn","duan":[{"e":"从心。宣聲。","n":"況晚切。十四部。"}]},"愻":{"expl":"順也。从心孫聲。《唐書》曰：“五品不愻。”","rad":"心","fq":"蘇困切","vol":"10","py":"xùn","duan":[{"e":"順也。","n":"訓順之字作愻。古書用字如此。凡愻順字从心。凡遜循字从辵。今人遜專行而愻廢矣。學記。不陵節而施之謂遜。劉向書作愻。此未經改竄之字也。論語。孫以出之。惡不孫以爲勇者。皆愻之叚借。"}]},"𢥛":{"expl":"實也。从心，塞省聲。《虞書》曰：“剛而𢥛。”","rad":"心","fq":"先則切","vol":"10","py":"sè","duan":[{"e":"實也。","n":"邶風。其心塞淵。毛傳。塞、瘞也。崔集注本作實也。今以許書繩之。作實爲是矣。詩秉心塞淵、王猷允塞皆同。鄭箋云。塞、充實也。今文尙書。文塞晏晏。鄭注考靈耀云。道德純僃謂之塞。道德純僃、充實之意也。咎繇謨。剛而塞。夏本紀作剛而實。按㠭部曰𡫳、窒也。穴部曰。窒、𡫳也。𥧑、𡫳也。𡫳廢而俗多用塞。塞、隔也。非其義也。至若燕燕、定之方中、堯典、咎繇謨諸塞字又皆當作𢥛。卽曰假借。亦當叚𡫳。而不當叚𡫼也。"}]},"恂":{"expl":"信心也。从心旬聲。","rad":"心","fq":"相倫切","vol":"10","py":"xún","duan":[{"e":"信心也。","n":"毛詩叚洵字爲之。如洵美且都、洵訏且樂。鄭箋皆云。洵、信也。釋詁曰。詢、信也。注引方言宋衞曰詢。皆叚詢爲恂也。至若論語恂恂如也。王肅注温恭皃。漢書李將軍恂恂如鄙人。史記作悛悛如鄙人。此皆逡巡字之叚借。而非正字也。"}]},"忱":{"expl":"誠也。从心冘聲。《詩》曰：“天命匪忱。”","rad":"心","fq":"氏任切","vol":"10","py":"chén","duan":[{"e":"誠也。","n":"誠者、信也。詩大朙曰。天難忱斯。毛曰。忱、信也。言部諶下曰。誠、諦也。引詩天難諶斯。古忱與諶義近通用。"}]},"惟":{"expl":"凡思也。从心隹聲。","rad":"心","fq":"以追切","vol":"10","py":"wéi","duan":[{"e":"凡思也。","n":"方言曰。惟、思也。又曰。惟、凡思也。慮、謀思也。願、欲思也。念、常思也。許本之曰。惟、凡思也。念、常思也。懷、念思也。想、冀思也。思部慮、謀思也。凡許書分部遠隔、而文理參五可以合觀者視此。凡思、謂浮泛之思。生民。載謀載惟。箋云。諏謀其日。思念其禮。按經傳多用爲發語之詞。毛詩皆作維。論語皆作唯。古文尙書皆作惟。今文尙書皆作維。古文尙書作惟者、唐石經之類可證也。今文尙書作維者、漢石經殘字可證也。俗本匡謬正俗乃互易之。大誤。又魯詩作惟、與毛詩作維不同。亦見漢石經殘字。"}]},"懷":{"expl":"念思也。从心褱聲。","rad":"心","fq":"戶乖切","vol":"10","py":"huái","duan":[{"e":"念思也。","n":"念思者、不忘之思也。釋詁、方言皆曰。懷、思也。詩卷耳、野有死麕、常棣傳同。若終風傳曰。懷、傷也。釋詁曰。至也。匪風、皇矣傳曰。歸也。皇皇者華、板傳皆曰。和也。皆引申之義。可以意會者也。古文又多叚懷爲褱者。"}]},"蘬":{"expl":"薺實也。从艸歸聲。","rad":"艸","fq":"驅歸切","vol":"01","py":"kuī","duan":[{"e":"薺實也。","n":"今釋艸。紅、龍古。其大者蘬。蒫、薺實。許所據絕不同。"}]},"惀":{"expl":"欲知之皃。从心侖聲。","rad":"心","fq":"盧昆切","vol":"10","py":"lún","duan":[{"e":"欲知之皃。","n":"廣韵混韵注曰。心思求曉事。"}]},"想":{"expl":"冀思也。从心相聲。","rad":"心","fq":"息兩切","vol":"10","py":"xiǎnɡ","duan":[{"e":"覬思也。","n":"覬各本作冀。今正。欠部曰。𣢆、𡴘也。見部曰。覬、𣢆𡴘也。覬思者、覬望之思也。周禮眡祲。十曰想。"}]},"㥞":{"expl":"深也。从心㒸聲。","rad":"心","fq":"徐醉切","vol":"10","py":"suì","duan":[{"e":"深也。","n":"深當作𥥍。許書深爲水名。𥥍爲𥥍淺字。穴部𥥍下曰。深也。言𥥍深古今字。以今字釋古字也。㥞與邃音義皆同。从穴者、爲室之深。从心者、爲意思之深。"}]},"慉":{"expl":"起也。从心畜聲。《詩》曰：“能不我慉。”","rad":"心","fq":"許六切","vol":"10","py":"xù","duan":[{"e":"起也。","n":"邶風谷風傳曰。慉、興也。起與興義同。今本傳作養者、非也。小雅蓼莪箋云。畜、起也。此謂拊我畜我之畜。乃慉之叚借。"}]},"𢡃":{"expl":"滿也。从心𠶷聲。一曰十萬曰𠶷。","rad":"心","fq":"於力切","vol":"10","py":"yì","duan":[{"e":"滿也。","n":"方言曰。臆、滿也。廣雅曰。臆、滿也。漢蔣君碑。餘悲馮億。皆意之叚借字也。"}]},"悹":{"expl":"憂也。从心官聲。","rad":"心","fq":"古玩切","vol":"10","py":"ɡuàn","duan":[{"e":"𢝊也。","n":"𢝊各本作憂。今正。廣韵卄四緩引詩傳悹悹無所依。今大雅板傳作管管。又篇、韵皆云。悹悹、憂無告也。今詩板、釋訓皆作灌灌。按憂無告之訓正字作懽。見下文。不當作悹。"}]},"憀":{"expl":"憀然也。从心翏聲。","rad":"心","fq":"洛蕭切","vol":"10","py":"liáo","duan":[{"e":"憀然也。","n":"三字句。憀然猶了然也。類篇曰。力求切。賴也。且也。按𦕼者、憀之叚借字。方言。俚𦕼也。漢書。其畫無俚之至耳。戰國策。民無所𦕼。凡𦕼賴可作憀賴。"}]},"愙":{"expl":"敬也。从心客聲。《春秋傳》曰：“以陳備三愙。”","rad":"心","fq":"苦各切","vol":"10","py":"kè","duan":[{"e":"敬也。","n":"釋詁、商頌毛傳皆曰。恪敬也。"}]},"愯":{"expl":"懼也。从心，雙省聲。《春秋傳》曰：“駟氏愯。”","rad":"心","fq":"息拱切","vol":"10","py":"sǒnɡ","duan":[{"e":"懼也。","n":"與竦音義略相近。"}]},"懼":{"expl":"恐也。从心瞿聲。","rad":"心","fq":"其遇切","vol":"10","py":"jù","duan":[{"e":"恐也。","n":"恐下曰。懼也。是爲轉注。"}]},"葆":{"expl":"艸盛皃。从艸𠈃聲。","rad":"艸","fq":"博袌切","vol":"01","py":"bǎo","duan":[{"e":"艸盛皃。","n":"漢書武五子傳曰。當此之時。頭如蓬葆。師古曰。草叢生曰葆。引伸爲羽葆幢之葆。史記以爲寶字。"}]},"怙":{"expl":"恃也。从心古聲。","rad":"心","fq":"矦古切","vol":"10","py":"hù","duan":[{"e":"恃也。","n":"韓詩云。怙、賴也。"}]},"恃":{"expl":"賴也。从心寺聲。","rad":"心","fq":"時止切","vol":"10","py":"shì","duan":[{"e":"賴也。","n":"韓詩云。恃、負也。"}]},"慒":{"expl":"慮也。从心曹聲。","rad":"心","fq":"藏宗切","vol":"10","py":"cónɡ","duan":[{"e":"慮也。","n":"見釋言。"}]},"悟":{"expl":"覺也。从心吾聲。","rad":"心","fq":"五故切","vol":"10","py":"wù","duan":[{"e":"覺也。","n":"見部覺下曰。悟也。是爲轉注。按古書多用寤爲之。"}]},"憮":{"expl":"愛也。韓鄭曰憮。一曰不動。从心無聲。","rad":"心","fq":"文甫切","vol":"10","py":"wǔ","duan":[{"e":"㤅也。","n":"㤅各本作𢜤。今正。"}]},"㤅":{"expl":"惠也。从心先聲。","rad":"心","fq":"烏代切","vol":"10","py":"ài","duan":[{"e":"惠也。","n":"叀部曰。惠、仁也。仁者、親也。"}]},"㥠":{"expl":"知也。从心胥聲。","rad":"心","fq":"私呂切","vol":"10","py":"xǔ","duan":[{"e":"知也。","n":"此與言部諝音義皆同。"}]},"慰":{"expl":"安也。从心尉聲。一曰恚怒也。","rad":"心","fq":"於胃切","vol":"10","py":"wèi","duan":[{"e":"安也。","n":"方言。慰、凥也。江淮靑徐之閒曰慰。"}]},"𢡈":{"expl":"謹也。从心𠭥聲。讀若毳。","rad":"心","fq":"此芮切","vol":"10","py":"cuì","duan":[{"e":"謹也。从心。𠭥聲。讀若毳。","n":"此芮切。十五部。"}]},"𥲅":{"expl":"𥲅箸也。从心钇聲。","rad":"心","fq":"直由切","vol":"10","py":"chóu","duan":[{"e":"𥲅箸也。","n":"按箸必是譌字。不可解。疑當作足部之䠧。𥲅䠧猶今人所用躊躇也。皆裵回不決之皃。故从心。"}]},"蕃":{"expl":"艸茂也。从艸番聲。","rad":"艸","fq":"甫煩切","vol":"01","py":"fán","duan":[{"e":"艸茂也。","n":"左氏傳曰。其必蕃昌。"}]},"怞":{"expl":"朗也。从心由聲。《詩》曰：“憂心且怞。”","rad":"心","fq":"直又切","vol":"10","py":"chóu","duan":[{"e":"朖也。","n":"未聞。疑是恨也之誤。檜傳云。悼、動也。鼓鍾傳云。妯、動也。菀柳傳云。蹈、動也。三字音義略同。"}]},"𢜮":{"expl":"𢜮，撫也。从心某聲。讀若侮。","rad":"心","fq":"亡甫切","vol":"10","py":"wǔ","duan":[{"e":"𢜮、憮也。","n":"𢜮乃複字未刪者。憮各本作撫。今正。方言。𢜮、憐也。上文憮、㤅也。㤅與憐同義。"}]},"忞":{"expl":"彊也。从心文聲。《周書》曰：“在受德忞。”讀若旻。","rad":"心","fq":"武巾切","vol":"10","py":"mín","duan":[{"e":"自勉彊也。","n":"各本少自勉二字。韵會有之。與篇、韵合。大雅。亹亹文王。毛傳曰。亹亹、勉也。亹卽釁之俗。釁从分聲。釁釁卽忞之叚借也。"}]},"慔":{"expl":"勉也。从心莫聲。","rad":"心","fq":"莫故切","vol":"10","py":"mù","duan":[{"e":"勉也。","n":"勉者、彊也。釋訓曰。懋懋、慔慔、勉也。"}]},"愐":{"expl":"勉也。从心面聲。","rad":"心","fq":"弥殄切","vol":"10","py":"miǎn","duan":[{"e":"勉也。","n":"釋詁曰。蠠𣳚、勔勉也。方言曰。釗、薄、勉也。南楚之外曰薄努。自關而東周鄭之閒曰勔釗。按毛詩黽勉亦作僶俛。韓詩作密勿。爾雅作蠠𣳚。蠠本或作？。？卽蜜。然則韓詩正作蜜勿。轉寫誤作密耳。爾雅釋文云。勔本作僶。又作黽。是則說文之愐爲正字。而作勔、作蠠、作？、作蜜、作密、作黽、作僶皆其別字也。今則不知有愐字、而愐字廢矣。"}]},"𢘽":{"expl":"習也。从心曳聲。","rad":"心","fq":"余制切","vol":"10","py":"yì","duan":[]},"懋":{"expl":"勉也。从心楙聲。《虞書》曰：“時惟懋哉。”","rad":"心","fq":"莫候切","vol":"10","py":"mào","duan":[{"e":"勉也。","n":"古多叚茂字爲之。"}]},"𢟽":{"expl":"習也。从心莫聲。","rad":"心","fq":"莫故切","vol":"10","py":"mù","duan":[{"e":"習也。","n":"習其事者、必中心好之。"}]},"悛":{"expl":"止也。从心夋聲。","rad":"心","fq":"此緣切","vol":"10","py":"quān","duan":[{"e":"止也。","n":"方言。悛、改也。自山而東或曰悛。或曰懌。"}]},"㥆":{"expl":"肆也。从心隶聲。","rad":"心","fq":"他骨切","vol":"10","py":"tuì","duan":[{"e":"肆也。","n":"廣雅曰。？也。忘也。"}]},"茸":{"expl":"艸茸茸皃。从艸，聦省聲。","rad":"艸","fq":"而容切","vol":"01","py":"rónɡ","duan":[{"e":"艸茸茸皃。","n":"茸之言茙也。召南毛傳曰。襛猶戎戎也。韓詩。何彼茙矣。左氏傳。狐裘尨茸。卽詩之狐裘蒙戎。"}]},"㦛":{"expl":"趣步㦛㦛也。从心與聲。","rad":"心","fq":"余呂切","vol":"10","py":"yǔ","duan":[{"e":"趣步㦛㦛也。","n":"趣、疾走也。趣步㦛㦛、謂疾而舒也。馬部？下曰。馬行徐而疾。義正相類。漢書。長倩懙懙。蘇林曰。懙懙、行步安舒也。論語。與與如也。馬注曰。與與、威儀中適之皃。與與卽㦛㦛之叚借。欠部曰。歟、安气也。"}]},"慆":{"expl":"說也。从心舀聲。","rad":"心","fq":"土刀切","vol":"10","py":"tāo","duan":[{"e":"說也。","n":"說今之悅字。尙書大傳。師乃慆。注曰。慆、喜也。可證許說。悉蟀傳曰。慆、過也。東山傳曰。慆慆、言久也。皆引申之義也。古與滔互叚借。"}]},"懕":{"expl":"安也。从心厭聲。《詩》曰：“懕懕夜飲。”","rad":"心","fq":"於鹽切","vol":"10","py":"yān","duan":[{"e":"安也。","n":"小戎傳曰。厭厭、安靜也。湛露傳曰。厭厭、安也。釋文及魏都賦注引韓詩愔愔、和悅之皃。按愔見左傳祈招之詩。葢愔卽懕之或體。厭乃懕之叚借。載芟。有厭其傑。厭厭其苗。亦懕之叚借。廣韵。䅧䅧、苗美也。用載芟傳也。"}]},"憺":{"expl":"安也。从心詹聲。","rad":"心","fq":"徒敢切","vol":"10","py":"dàn","duan":[{"e":"安也。","n":"子虚賦曰。憺乎自持。按人部曰。倓、安也。音義皆同。"}]},"怕":{"expl":"無爲也。从心白聲。","rad":"心","fq":"匹白切","vol":"10","py":"bó","duan":[{"e":"無僞也。","n":"僞各本作爲。今按許以爲訓母猴、僞訓作也。是許書作爲字皆當作作僞也。今本人部僞下曰詐也。淺人所改耳。子虛賦曰。怕乎無爲。憺怕、俗用澹泊爲之。叚借也。澹作淡。尤俗。"}]},"恤":{"expl":"憂也。收也。从心血聲。","rad":"心","fq":"辛聿切","vol":"10","py":"xù","duan":[{"e":"𢝊也。","n":"𢝊各本作憂。今正。釋詁及小雅杕杜、祈父傳皆曰。恤。憂也。按卪部曰。卹、𢝊也。比部引周書無毖于卹。今尙書作恤。恤與卹音義皆同。又疑古衹有卹。恤其或體。"}]},"忓":{"expl":"極也。从心干聲。","rad":"心","fq":"古寒切","vol":"10","py":"ɡān","duan":[{"e":"極也。","n":"極者、屋之高處。干者、犯也。忓者、以下犯上之意。"}]},"懽":{"expl":"喜𠭥也。从心雚聲。《爾雅》曰：“懽懽愮愮，憂無告也。”","rad":"心","fq":"古玩切","vol":"10","py":"ɡuàn","duan":[{"e":"喜㱁也。","n":"懽㱁㬪韵。㱁者、意有所欲也。欠部曰。歡者、喜樂也。懽與歡音義皆略同。"}]},"㥥":{"expl":"懽也。琅邪朱虛有㥥亭。从心禺聲。","rad":"心","fq":"噳俱切","vol":"10","py":"yú","duan":[{"e":"懽也。","n":"懽讀如歡。冡上懽篆而云也。"}]},"惄":{"expl":"飢餓也。一曰憂也。从心叔聲。《詩》曰：“惄如朝飢。”","rad":"心","fq":"奴歴切","vol":"10","py":"nì","duan":[{"e":"飢餓也。","n":"餓當作意。釋言曰。惄、飢也。李巡云。惄、宿不食之飢也。周南傳曰。惄、飢意也。爲許所本。"}]},"葏":{"expl":"艸皃。从艸津聲。","rad":"艸","fq":"子僊切","vol":"01","py":"jiān","duan":[{"e":"艸皃。","n":"集韵一先曰。詩葏葏者莪。李舟說。"}]},"𢜭":{"expl":"勞也。从心卻聲。","rad":"心","fq":"其虐切","vol":"10","py":"jǐ","duan":[{"e":"勞也。","n":"此與人部𠊬音義皆同。本一字耳。詳彼注。"}]},"憸":{"expl":"憸詖也。憸利於上，佞人也。从心僉聲。","rad":"心","fq":"息廉切","vol":"10","py":"xiān","duan":[{"e":"憸詖也。","n":"憸葢險之字誤。詖同頗。古文以詖爲頗也。"}]},"愒":{"expl":"息也。从心曷聲。","rad":"心","fq":"去例切","vol":"10","py":"qì","duan":[{"e":"息也。","n":"此休息之息。上文息篆訓喘息、其本義。凡訓休息者。引申之義也。釋詁及甘棠傳皆曰。憩息也。憩者、愒之俗體。民勞傳又曰。愒、息也。非有二字也。又釋言曰。愒貪也。此愒字乃㵣之叚借。如左傳玩歲而愒日、許引作忨歲而㵣日。公羊傳不及時而葬曰愒。愒、急也。亦卽㵣字也。"}]},"㦌":{"expl":"精戇也。从心毳聲。","rad":"心","fq":"千短切","vol":"10","py":"hū","duan":[{"e":"精戇也。","n":"未聞。玉篇、廣韵云。寢熟也。"}]},"𢘁":{"expl":"疾利口也。从心从冊。《詩》曰：“相時𢘁民。”","rad":"心","fq":"息廉切","vol":"10","py":"xiān","duan":[{"e":"疾利口也。","n":"疾、惡也。謂疾惡利口之人也。般庚。相時？民。猶胥顧于箴言。謂惟憎惡利口之人尙能相與稍顧淸議。女部姍訓誹也。漢書姍笑、與𢘁義略同。"}]},"急":{"expl":"褊也。从心及聲。","rad":"心","fq":"居立切","vol":"10","py":"jí","duan":[{"e":"褊也。","n":"褊者、衣小也。故凡窄陿謂之褊。釋言曰。褊、急也。"}]},"㦚":{"expl":"憂也。从心辡聲。一曰急也。","rad":"心","fq":"方沔切","vol":"10","py":"biǎn","duan":[{"e":"𢝊也。","n":"𢝊各本作憂。今正。"}]},"㥛":{"expl":"疾也。从心亟聲。一曰謹重皃。","rad":"心","fq":"己力切","vol":"10","py":"jí","duan":[{"e":"㤂性也。","n":"各本作疾也。今依韵會正。釋言曰。悈、褊、急也。釋文。悈本或作極。又作亟、同。紀力反。按極正㥛之誤。㥛與急雙聲同義。㥛字不見於經。有叚亟爲之者。如詩經始勿亟箋云亟、急也是也。有叚戒爲之者。如鹽鐵論引六月我是用戒、謝靈運𢰅征賦作用棘是也。有叚悈爲之者。如釋言悈、急也是也。有叚棘爲之者。如素冠傳、六月出車文王有聲箋皆曰棘、急也是也。有叚革爲之者、如禮器非革其猶、檀弓夫子之病革矣注皆曰急也是也。傳、箋、注以叚借法釋經。"}]},"懁":{"expl":"急也。从心瞏聲。讀若絹。","rad":"心","fq":"古縣切","vol":"10","py":"juàn","duan":[{"e":"㤂也。","n":"獧下曰。一曰急也。此與義音同。論語狷、孟子作獧。其實當作懁。齊風。子之還兮。傳曰。還、便捷之皃。走部曰。？、疾也。其義皆近。"}]},"𢙼":{"expl":"恨也。从心坙聲。","rad":"心","fq":"胡頂切","vol":"10","py":"xìnɡ","duan":[{"e":"恨也。","n":"𢙼卽孟子悻字也。孟子。則怒悻悻然見於其面。趙以恚怒釋之。又引論語悻悻然小人哉。今論語作硜硜。"}]},"䕺":{"expl":"艸叢生皃。从艸叢聲。","rad":"艸","fq":"徂紅切","vol":"01","py":"cónɡ","duan":[{"e":"艸叢生皃。","n":"叢、聚也。槩言之。䕺則專謂艸。今人但知用叢字而已。爾雅釋魚音義引說文。䕺、艸衆生也。"}]},"𢛆":{"expl":"急也。从心从弦，弦亦聲。河南密縣有𢛆亭。","rad":"心","fq":"胡田切","vol":"10","py":"xián","duan":[{"e":"㤂也。","n":"按人性急也。"}]},"慓":{"expl":"疾也。从心票聲。","rad":"心","fq":"𢾭沼切","vol":"10","py":"piào","duan":[{"e":"疾也。","n":"廣雅。急也。弓人曰。於挺臂中有柎焉。故剽。注云。剽、疾也。此謂剽卽慓之叚借也。"}]},"懦":{"expl":"駑弱者也。从心需聲。","rad":"心","fq":"人朱切","vol":"10","py":"nuò","duan":[]},"恁":{"expl":"下齎也。从心任聲。","rad":"心","fq":"如甚切","vol":"10","py":"rèn","duan":[{"e":"下齎也。","n":"未聞。按後漢書班固典引曰。亦宜勤恁旅力。李賢注引說文恁、念也。當用以訂正。廣雅曰。恁、思也。廣韵、玉篇亦曰。念也。恁念爲曡韵。廣雅又云。恁、弱也。則與詩荏染同音通用耳。"}]},"𢘋":{"expl":"失常也。从心代聲。","rad":"心","fq":"他得切","vol":"10","py":"tè","duan":[{"e":"失常也。从心。代聲。","n":"他得切。一部。此字不古。說見下。"}]},"怚":{"expl":"驕也。从心且聲。","rad":"心","fq":"子去切","vol":"10","py":"jù","duan":[{"e":"驕也。","n":"此與女部㜘驕也音義同。㜘下今本作嬌。乃驕之俗字耳。"}]},"悒":{"expl":"不安也。从心邑聲。","rad":"心","fq":"於汲切","vol":"10","py":"yì","duan":[{"e":"不安也。","n":"大戴禮曰。君子終身守此悒悒。盧注。憂念也。蒼頡篇曰。悒悒、不畼之皃也。其字古通作邑。俗作唈。爾雅云。僾、唈也。謂憂而不得息也。"}]},"悆":{"expl":"忘也。嘾也。从心余聲。《周書》曰：“有疾不悆。”悆，喜也。","rad":"心","fq":"羊茹切","vol":"10","py":"yù","duan":[{"e":"忘也。","n":"此義未聞。恐有譌字。"}]},"忒":{"expl":"更也。从心弋聲。","rad":"心","fq":"他得切","vol":"10","py":"tè","duan":[{"e":"㪅也。从心。弋聲。","n":"他得切。一部。按人部代、㪅也。弋聲。忒與音義同。尸鳩傳曰。忒、疑也。瞻卬傳曰。忒、差也。皆一義之區別也。左部曰。𢀩者、忒也。參𢀩、不相值也。不相值卽更改之意。凡人有過失改常謂之忒。本無？字。各本有？篆。注云。失常也。从心、代聲。代亦弋聲。則音義皆同。此葢淺人妄增。如貝部貣外沾貸、虫部？改爲蟘皆其類。？篆宜刪。廣韵無？爲是也。忒之引申爲巳甚。俗語用之。或曰大。他佐切。或曰太。或曰忒。俗語曰忒殺。忒之叚借或作貣。"}]},"憪":{"expl":"愉也。从心閒聲。","rad":"心","fq":"戶閒切","vol":"10","py":"xián","duan":[{"e":"愉也。","n":"廣韵曰。憪、心靜。然則今人所用閒靜字當作此字。許云愉者、卽下文愉愉如也之愉。謂憺怕之樂也。"}]},"草":{"expl":"草斗，櫟實也。一曰象斗子。从艸早聲。","rad":"艸","fq":"自保切","vol":"01","py":"zào","duan":[{"e":"草𣁬、","n":"逗。"}]},"愉":{"expl":"薄也。从心俞聲。《論語》曰：“私覿，愉愉如也。”","rad":"心","fq":"羊朱切","vol":"10","py":"yú","duan":[{"e":"薄也。","n":"薄本訓林薄、蠶薄。而叚爲淺泊字。泊水部作洦。凡言厚薄皆？泊之叚借也。此薄也當作薄樂也。轉寫奪樂字。謂淺薄之樂也。引申之、凡薄皆云愉。唐風。他人是愉。傳曰。愉、樂也。禮記曰。有和氣者。必有愉色。此愉之本義也。毛不言薄者、重樂不重薄也。鹿鳴。視民不恌。傳曰。恌、愉也。許書人部作佻、愉也。周禮。以俗敎安。則民不愉。鄭注。愉謂朝不謀夕。此引申之義也。淺人分別之。別製偷字、从人。訓爲偷薄。訓爲苟且。訓爲偷盜。絕非古字。許書所無。然自山有樞鄭箋云愉讀曰偷。偷、取也。則不可謂其字不古矣。"}]},"懱":{"expl":"輕易也。从心蔑聲。《商書》曰：“以相陵懱。”","rad":"心","fq":"莫結切","vol":"10","py":"miè","duan":[{"e":"輕易也。","n":"易當作㑥。人部曰。㑥、輕也。懱者、輕易人蔑視之也。剥之初六曰。蔑貞凶。馬云。蔑、無也。鄭云。輕慢。鄭謂蔑卽懱之叚借字也。"}]},"愚":{"expl":"戇也。从心从禺。禺，猴屬，獸之愚者。","rad":"心","fq":"麌俱切","vol":"10","py":"yú","duan":[{"e":"戇也。","n":"愚者、智之反也。"}]},"戇":{"expl":"愚也。从心𥫔聲。","rad":"心","fq":"陟絳切","vol":"10","py":"zhuànɡ","duan":[{"e":"愚也。","n":"與上篆互訓。"}]},"㥒":{"expl":"姦也。从心采聲。","rad":"心","fq":"倉宰切","vol":"10","py":"cǎi","duan":[{"e":"姦也。","n":"篇、韵皆云。恨也。"}]},"憃":{"expl":"愚也。从心舂聲。","rad":"心","fq":"丑江切","vol":"10","py":"chōnɡ","duan":[{"e":"愚也。","n":"見哀公問、表記。"}]},"懝":{"expl":"騃也。从心从疑，疑亦聲。一曰惶也。","rad":"心","fq":"五漑切","vol":"10","py":"ài","duan":[{"e":"騃也。","n":"騃本訓馬行㐹㐹。引申爲疑立之狀。又引申之、則方言曰癡、騃也。懝騃卽方言之癡騃。疒部曰。癡、不慧也。"}]},"忮":{"expl":"很也。从心支聲。","rad":"心","fq":"之義切","vol":"10","py":"zhì","duan":[{"e":"𢓼也。","n":"很者、不聽从也。雄雉、瞻卬傳皆曰。忮、害也。害卽很義之引申也。或叚伎爲之。伎之本義爲與。許人部伎下引詩？人伎忒。言叚借也。"}]},"悍":{"expl":"勇也。从心旱聲。","rad":"心","fq":"侯旰切","vol":"10","py":"hàn","duan":[{"e":"勇也。从心。旱聲。","n":"侯旰切。十四部。"}]},"態":{"expl":"意也。从心从能。","rad":"心","fq":"他代切","vol":"10","py":"tài","duan":[{"e":"意態也。","n":"各本作意也。少一字。今補。意態者、有是意因有是狀。故曰意態。猶䛐者意内而言外。有是意因有是言也。意者、識也。"}]},"祟":{"expl":"神禍也。从示从出。","rad":"示","fq":"雖遂切","vol":"01","py":"suì","duan":[{"e":"神禍也。","n":"釋玄應衆經音義曰。謂鬼神作災禍也。"}]},"菆":{"expl":"麻蒸也。从艸取聲。一曰蓐也。","rad":"艸","fq":"側鳩切","vol":"01","py":"zōu","duan":[{"e":"麻蒸也。","n":"此不與上文蒸字類廁者、以篆籒別之。西征賦曰。感市閭之菆井。東方朔七諫曰。菎蕗襍於黀蒸。王逸注枲翮曰。黀一作菆。按枲翮、枲莖也。麻部出黀字云麻？也。鍇本無之。俗添之耳。"}]},"怪":{"expl":"異也。从心圣聲。","rad":"心","fq":"古壞切","vol":"10","py":"ɡuài","duan":[{"e":"異也。从心。圣聲。","n":"古壞切。一部。"}]},"𢠽":{"expl":"放也。从心象聲。","rad":"心","fq":"徒朗切","vol":"10","py":"dànɡ","duan":[{"e":"放也。从心。象聲。","n":"徒朗切。十部。"}]},"慢":{"expl":"惰也。从心曼聲。一曰慢，不畏也。","rad":"心","fq":"謀晏切","vol":"10","py":"màn","duan":[{"e":"憜也。从心。曼聲。","n":"謀晏切。十四部。"}]},"怠":{"expl":"慢也。从心台聲。","rad":"心","fq":"徒亥切","vol":"10","py":"dài","duan":[{"e":"慢也。从心。台聲。","n":"徒亥切。一部。"}]},"懈":{"expl":"怠也。从心解聲。","rad":"心","fq":"古隘切","vol":"10","py":"xiè","duan":[{"e":"怠也。","n":"古多叚解爲之。"}]},"憜":{"expl":"不敬也。从心，𡐦省。《春秋傳》曰：“執玉憜。”","rad":"心","fq":"徒果切","vol":"10","py":"duò","duan":[{"e":"不敬也。","n":"今書皆作惰。韋玄成傳。供事靡憜。師古曰。憜古惰字。"}]},"𢠰":{"expl":"驚也。从心從聲。讀若悚。","rad":"心","fq":"息拱切","vol":"10","py":"sǒnɡ","duan":[{"e":"驚也。从心。從聲。讀若悚。","n":"悚當作竦。許書有愯無悚。息拱切。九部。"}]},"怫":{"expl":"鬱也。从心弗聲。","rad":"心","fq":"符弗切","vol":"10","py":"fú","duan":[{"e":"𩰪也。","n":"𩰪各本作鬱。誤。𩰪者、芳艸築以煑之。引申爲凡抑𩰪之偁。瓠子歌曰。魚弗鬱兮柏冬日。弗者、怫之借字。"}]},"𢗊":{"expl":"忽也。从心介聲。《孟子》曰：“孝子之心不若是𢗊。”","rad":"心","fq":"呼介切","vol":"10","py":"xiè","duan":[{"e":"忽也。从心。介聲。","n":"呼介切。十五部。"}]},"忽":{"expl":"忘也。从心勿聲。","rad":"心","fq":"呼骨切","vol":"10","py":"hū","duan":[{"e":"忘也。","n":"古多叚？爲之。？俗作曶。"}]},"蓄":{"expl":"積也。从艸畜聲。","rad":"艸","fq":"丑六切","vol":"01","py":"xù","duan":[{"e":"積也。从艸。畜聲。","n":"丑六切。三部。籒文作？。"}]},"忘":{"expl":"不識也。从心从亡，亡亦聲。","rad":"心","fq":"武方切","vol":"10","py":"wànɡ","duan":[{"e":"不識也。","n":"識者、意也。今所謂知識。所謂記憶也。"}]},"慲":{"expl":"忘也。慲兜也。从心㒼聲。","rad":"心","fq":"毋官切","vol":"10","py":"mán","duan":[{"e":"忘也。慲兜也。","n":"疑當作慲兜、忘也。慲兜葢古語。忘之皃也。猶今人曰糊塗不省事。"}]},"恣":{"expl":"縱也。从心次聲。","rad":"心","fq":"資四切","vol":"10","py":"zì","duan":[{"e":"縱也。","n":"縱者、緩也。一曰捨也。"}]},"愓":{"expl":"放也。从心昜聲。一曰平也。","rad":"心","fq":"徒朗切","vol":"10","py":"dànɡ","duan":[{"e":"放也。","n":"與？音義同。方言。婬、愓、遊也。江沅之閒謂戲爲婬。或謂之愓。按廣韵作婸。"}]},"憧":{"expl":"意不定也。从心童聲。","rad":"心","fq":"尺容切","vol":"10","py":"chōnɡ","duan":[{"e":"意不定也。","n":"咸九四曰。憧憧往來。劉表章句曰。憧憧、意未定也。說與許同。"}]},"悝":{"expl":"啁也。从心里聲。《春秋傳》有孔悝。一曰病也。","rad":"心","fq":"苦回切","vol":"10","py":"kuī","duan":[{"e":"啁也。","n":"口部曰。啁、嘐也。啁卽今之嘲字。悝卽今之詼字。謂詼諧啁調也。今則詼嘲行而悝啁廢矣。東京賦曰。悝繆公於公室。李注。悝猶嘲也。"}]},"憰":{"expl":"權詐也。从心矞聲。","rad":"心","fq":"古穴切","vol":"10","py":"jué","duan":[{"e":"權詐也。","n":"此與言部譎音義皆同。葢彼以言、此以心。"}]},"㤮":{"expl":"誤也。从心狂聲。","rad":"心","fq":"居況切","vol":"10","py":"ɡuànɡ","duan":[{"e":"誤也。","n":"廣韵曰。㤮、惑也。又曰。誤人也。"}]},"怳":{"expl":"狂之皃。从心，況省聲。","rad":"心","fq":"許往切","vol":"10","py":"huǎnɡ","duan":[{"e":"狂之皃。","n":"廣韵曰。𢠵怳。"}]},"恑":{"expl":"變也。从心危聲。","rad":"心","fq":"過委切","vol":"10","py":"ɡuǐ","duan":[{"e":"變也。","n":"今此義多用詭。非也。詭訓責。"}]},"萅":{"expl":"推也。从艸从日，艸春時生也；屯聲。","rad":"艸","fq":"昌純切","vol":"01","py":"chūn","duan":[{"e":"推也。","n":"此於雙聲求之。鄉飮酒義曰。東方者春。春之爲言蠢也。尚書大傳曰。春、出也。萬物之出也。"}]},"𢥘":{"expl":"有二心也。从心巂聲。","rad":"心","fq":"戶圭切","vol":"10","py":"xié","duan":[{"e":"有二心也。","n":"古多叚借攜爲之。"}]},"悸":{"expl":"心動也。从心季聲。","rad":"心","fq":"其季切","vol":"10","py":"jì","duan":[{"e":"心動也。","n":"衞風。垂帶悸兮。傳曰。垂其紳帶、悸悸然有節度也。此未知以悸爲何字之叚借。凡若此類思而未得者、可姑置之。但心知其必是叚借斯可矣。"}]},"憿":{"expl":"幸也。从心敫聲。","rad":"心","fq":"古堯切","vol":"10","py":"jiāo","duan":[{"e":"𡴘也。","n":"𡴘者、吉而免凶也。引申之曰𣢆幸。亦曰憿幸。俗作僥倖、儌倖、徼倖皆非也。凡傳言徼福者、皆當作憿福爲正。"}]},"懖":{"expl":"善自用之意也。从心銛聲。《商書》曰：“今汝懖懖。”","rad":"心","fq":"古活切","vol":"10","py":"kuò","duan":[{"e":"歫善自用之意也。","n":"歫字各本無。依尙書音義所引補。許書無拒。歫卽今拒字。"}]},"忨":{"expl":"貪也。从心元聲。《春秋傳》曰：“忨歲而㵣日。”","rad":"心","fq":"五換切","vol":"10","py":"wán","duan":[{"e":"貪也。","n":"貪者、欲物也。忨與玩翫義皆略同。"}]},"惏":{"expl":"河内之北謂貪曰惏。从心林聲。","rad":"心","fq":"盧含切","vol":"10","py":"lán","duan":[{"e":"河内之北謂貪曰惏。","n":"内字衍。小徐作河之北。卽河内也。惏與女部婪音義同。賈注左傳曰。惏、嗜也。方言曰。惏、殘也。陳楚曰惏。"}]},"懜":{"expl":"不明也。从心夢聲。","rad":"心","fq":"武亘切","vol":"10","py":"mènɡ","duan":[{"e":"不朙也。从心。夢聲。","n":"夕部夢、不朙也。此舉形聲包會意。武亙切。六部。"}]},"愆":{"expl":"過也。从心衍聲。","rad":"心","fq":"去虔切","vol":"10","py":"qiān","duan":[{"e":"實也。","n":"邶風。其心塞淵。毛傳。塞、瘞也。崔集注本作實也。今以許書繩之。作實爲是矣。詩秉心塞淵、王猷允塞皆同。鄭箋云。塞、充實也。今文尙書。文塞晏晏。鄭注考靈耀云。道德純僃謂之塞。道德純僃、充實之意也。咎繇謨。剛而塞。夏本紀作剛而實。按㠭部曰。𡫳、窒也。穴部曰。窒、𡫳也。窴、𡫳也。𡫳廢而俗多用塞。塞、隔也。非其義也。至若燕燕、定之方中、堯典、咎繇謨諸塞字又皆當作𢥛。卽曰叚借。亦當叚𡫳。而不當叚𡫼也。"}]},"慊":{"expl":"疑也。从心兼聲。","rad":"心","fq":"戶兼切","vol":"10","py":"xián","duan":[{"e":"疑也。","n":"疑者、惑也。故下文受之以惑。今字多作嫌。按女部嫌者、不平於心也。一曰疑也。不平於心爲嫌之正義。則嫌疑字作慊爲正。今則嫌行而慊廢。且用慊爲歉。非是。又或用慊爲㥦。尤非是。大學。此之謂自謙。注曰。謙讀爲慊。慊之言猒也。凡云之言者、皆就字之本音本義而轉之。猒足、非慊之本義也。至若鄭本周易爲其慊於陽。故偁龍焉。鄭注云。慊讀爲羣公溓之溓。古書篆作立心與水相近。讀者失之。故作慊。溓、襍也。陰謂此上六也。陽謂今消息用事乾也。上六爲蛇。得乾氣襍似龍。此鄭注則易慊爲溓。皆不用字之本義也。"}]},"惑":{"expl":"亂也。从心或聲。","rad":"心","fq":"胡國切","vol":"10","py":"huò","duan":[{"e":"亂也。","n":"亂者、治也。疑則當治之。古多叚或爲惑。"}]},"𦱄":{"expl":"艸多皃。从艸狐聲。江夏平春有𦱄亭。","rad":"艸","fq":"古狐切","vol":"01","py":"ɡū","duan":[]},"怋":{"expl":"怓也。从心民聲。","rad":"心","fq":"呼昆切","vol":"10","py":"mín","duan":[{"e":"怓也。从心。民聲。","n":"呼昆切。按古音當在十二部。讀若民。如今音則與惛無別矣。"}]},"怓":{"expl":"亂也。从心奴聲。《詩》曰：“以謹惽怓。”","rad":"心","fq":"女交切","vol":"10","py":"náo","duan":[{"e":"亂也。","n":"大雅民勞毛傳曰。惽怓、大亂也。惽當作怋。"}]},"惷":{"expl":"亂也。从心春聲。《春秋傳》曰：“王室日惷惷焉。”一曰厚也。","rad":"心","fq":"尺允切","vol":"10","py":"chǔn","duan":[{"e":"亂也。从心。萅聲。","n":"尺允切。十三部。"}]},"惛":{"expl":"不憭也。从心昬聲。","rad":"心","fq":"呼昆切","vol":"10","py":"hūn","duan":[{"e":"不憭也。","n":"憭、慧也。"}]},"忥":{"expl":"癡皃。从心气聲。","rad":"心","fq":"許旣切","vol":"10","py":"xì","duan":[{"e":"癡皃。","n":"癡、不慧也。故忥與惛爲伍。"}]},"㦣":{"expl":"㝱言不慧也。从心衞聲。","rad":"心","fq":"于歲切","vol":"10","py":"wèi","duan":[{"e":"㝱言不慧也。","n":"哀二十四年左傳曰。是躗言也。釋文曰。字林作㦣。云夢言意不慧也。按左傳作躗。是叚借字。"}]},"憒":{"expl":"亂也。从心貴聲。","rad":"心","fq":"胡對切","vol":"10","py":"kuì","duan":[{"e":"亂也。","n":"大雅召旻。潰潰回遹。傳曰。潰潰、亂也。按潰潰者、憒憒之叚借也。後人皆用憒憒。"}]},"忌":{"expl":"憎惡也。从心己聲。","rad":"心","fq":"渠記切","vol":"10","py":"jì","duan":[{"e":"憎惡也。从心。己聲。","n":"渠記切。一部。"}]},"忿":{"expl":"悁也。从心分聲。","rad":"心","fq":"𢾭粉切","vol":"10","py":"fèn","duan":[{"e":"悁也。","n":"忿與憤義不同。憤以气盈爲義。忿以狷急爲義。"}]},"悁":{"expl":"忿也。从心肙聲。一曰憂也。","rad":"心","fq":"於緣切","vol":"10","py":"yuān","duan":[{"e":"忿也。","n":"悁之言獧也。獧、急也。澤陂曰。中心悁悁。傳曰。悁悁猶悒悒也。"}]},"菿":{"expl":"艸木倒。从艸到聲。","rad":"艸","fq":"都盜切","vol":"01","py":"dào","duan":[{"e":"艸大也。","n":"毛詩。倬彼甫田。韓詩作菿彼圃田。釋古曰。菿、大也。卓聲到聲古同在弟二部。"}]},"𢤂":{"expl":"恨也。从心𪏯聲。一曰怠也。","rad":"心","fq":"郎尸切","vol":"10","py":"lí","duan":[{"e":"𢚉也。从心。黎聲。","n":"郞尸切。十五部。"}]},"恚":{"expl":"恨也。从心圭聲。","rad":"心","fq":"於避切","vol":"10","py":"huì","duan":[{"e":"怒也。","n":"怒各本作怨。今依大雅綿正義正。下文曰。怒者、恚也。二篆互訓。"}]},"怨":{"expl":"恚也。从心夗聲。","rad":"心","fq":"於願切","vol":"10","py":"yuàn","duan":[{"e":"恚也。从心。夗聲。","n":"於願切。十四部。"}]},"怒":{"expl":"恚也。从心奴聲。","rad":"心","fq":"乃故切","vol":"10","py":"nù","duan":[{"e":"恚也。从心。奴聲。","n":"乃故切。五部。按古無努字。衹用怒。"}]},"憝":{"expl":"怨也。从心敦聲。《周書》曰：“凡民罔不憝。”","rad":"心","fq":"徒對切","vol":"10","py":"duì","duan":[{"e":"怨也。从心。𣀦聲。","n":"徒對切。古音在十三部。"}]},"慍":{"expl":"怒也。从心𥁕聲。","rad":"心","fq":"於問切","vol":"10","py":"yùn","duan":[{"e":"怨也。","n":"怨各本作怒。大雅緜傳曰。愠、恚也。正義云。說文愠、怨也。恚、怒也。有怨者必怒之。故以愠爲恚。然則唐初本作怨甚明。車舝。以慰我心。韓詩作以愠我心。愠、恚也。與毛緜傳合。毛閒關傳曰。慰、怨也。葢毛詩亦作愠。後人譌爲慰耳。"}]},"惡":{"expl":"過也。从心亞聲。","rad":"心","fq":"烏各切","vol":"10","py":"è","duan":[{"e":"過也。","n":"人有過曰惡。有過而人憎之亦曰惡。本無去入之別。後人強分之。"}]},"憎":{"expl":"惡也。从心曾聲。","rad":"心","fq":"作滕切","vol":"10","py":"zēnɡ","duan":[{"e":"惡也。从心。曾聲。","n":"作滕切。六部。"}]},"㤄":{"expl":"恨怒也。从心巿聲。《詩》曰：“視我㤄㤄。”","rad":"心","fq":"蒲昧切","vol":"10","py":"pèi","duan":[{"e":"𢚉怒也。","n":"小雅白華。念子懆懆。視我邁邁。毛傳曰。邁邁、不悅也。釋文云。韓詩及說文皆作㤄㤄。韓詩云。意不悅好也。許云。很怒也。今說文作恨。似宜依很。邁者、㤄之叚借。非有韓、許、則毛詩不可通矣。許宗毛而不廢三家詩。"}]},"𢖫":{"expl":"怒也。从心刀聲。讀若𩕺。李陽冰曰：“刀非聲，当从刈省。”","rad":"心","fq":"魚旣切","vol":"10","py":"yì","duan":[{"e":"怒也。从心刀。","n":"各本作刀聲。今删正。从心刀、謂心中含怒如懷刃也。李陽氷云。當从刈省聲。非是。本部固有㣻篆矣。"}]},"芙":{"expl":"芙蓉也。从艸夫聲。","rad":"艸","fq":"方無切","vol":"01","py":"fú","duan":[]},"㥟":{"expl":"怨恨也。从心彖聲。讀若膎。","rad":"心","fq":"戶佳切","vol":"10","py":"xié","duan":[{"e":"怨𢚉也。","n":"廣雅。㥟、恨也。本此。"}]},"恨":{"expl":"怨也。从心艮聲。","rad":"心","fq":"胡艮切","vol":"10","py":"hèn","duan":[{"e":"怨也。从心。𥃩聲。","n":"胡艮切。十三部。"}]},"懟":{"expl":"怨也。从心對聲。","rad":"心","fq":"丈淚切","vol":"10","py":"duì","duan":[{"e":"怨也。","n":"今與憝音義皆同。謂爲一字。許不尒者、敦聲古在十三部。"}]},"悔":{"expl":"悔恨也。从心𣫭聲。","rad":"心","fq":"荒內切","vol":"10","py":"huǐ","duan":[{"e":"悔𢚉也。","n":"按悔乃複舉字之未刪者。韵會無。當从之。悔者、自恨之意。"}]},"𢜳":{"expl":"小怒也。从心喜聲。","rad":"心","fq":"充世切","vol":"10","py":"chì","duan":[{"e":"小怒也。从心。豈聲。","n":"充世切。按廣韵？在十三祭。引說文小怒也。尺制切。㤱在四十四有、四十九宥。小怒也。芳否敷救二切。集韵則祭韵有？。有韵？㥉二同。匹九切。類篇從之、而無㤱字。葢㤱？㥉三字同。以說文咅或作㰯及說文侸字廣韵作？求之。定爲一字異體。古音？尌樹豎皆讀近受。？斷不讀充世切也。咅者、相與語唾而不受也。天口切。與小怒義亦相近。"}]},"怏":{"expl":"不服，懟也。从心央聲。","rad":"心","fq":"於亮切","vol":"10","py":"yànɡ","duan":[{"e":"不服懟也。","n":"按當作不服也。懟也。奪一也字。遂不可解矣。集韵作不服對也。尢非。怏葢倔强之意。方言曰。鞅、侼、懟也。集韵於陽韵曰。怏然自大之意。攷王逸少蘭亭序曰。怏然自足。自來石刻如是。本非快字。而學者尟知之。或叚鞅爲之。方言是也。周亞夫傳曰。此鞅鞅非少主臣。"}]},"懣":{"expl":"煩也。从心从滿。","rad":"心","fq":"莫困切","vol":"10","py":"mèn","duan":[{"e":"煩也。","n":"煩者、熱頭痛也。引申之、凡心悶皆爲煩。問䘮曰。悲哀志懣氣盛。古亦叚滿爲之。"}]},"憤":{"expl":"懣也。从心賁聲。","rad":"心","fq":"房吻切","vol":"10","py":"fèn","duan":[{"e":"懣也。从心。賁聲。","n":"房吻切。十三部。"}]},"悶":{"expl":"懣也。从心門聲。","rad":"心","fq":"莫困切","vol":"10","py":"mèn","duan":[{"e":"懣也。从心。門聲。","n":"莫困切。十三部。"}]},"惆":{"expl":"失意也。从心周聲。","rad":"心","fq":"敕鳩切","vol":"10","py":"chóu","duan":[{"e":"失意也。","n":"荀卿子。惆然不嗛。陸機歎逝賦。心惆焉而自傷。廣雅曰。惆、痛也。"}]},"蓉":{"expl":"芙蓉也。从艸容聲。","rad":"艸","fq":"余封切","vol":"01","py":"rónɡ","duan":[]},"悵":{"expl":"望恨也。从心長聲。","rad":"心","fq":"丑亮切","vol":"10","py":"chànɡ","duan":[{"e":"望𢚉也。","n":"望其還而不至爲恨也。"}]},"愾":{"expl":"大息也。从心从氣，氣亦聲。《詩》曰：“愾我寤歎。”","rad":"心","fq":"許旣切","vol":"10","py":"xì","duan":[{"e":"大息皃。","n":"大各本作太。皃各本作也。皆誤。今正。古無太息連文者。淺人爲之也。口部嘆下曰。大息也。大息者、呼吸之大者也。呼、外息也。吸、内息也。曹風下泉。愾我寤嘆。嘆或作歎者、誤。箋云。愾、嘆息之意。許云大息者謂嘆。云皃者謂愾也。祭義曰入戸而聽、愾然必有聞乎其嘆息之聲是也。若哀公問則愾乎天下矣注云。愾、至也。此叚愾爲訖。"}]},"懆":{"expl":"愁不安也。从心喿聲。《詩》曰：“念子懆懆。”","rad":"心","fq":"七早切","vol":"10","py":"cǎo","duan":[{"e":"愁不安也。","n":"當依韵會本作懆懆、愁也。懆訓愁。慘訓毒。音義皆殊。而寫者多亂之。白華作懆。見於許書。月出、正月、抑皆作懆。人韵。且毛傳曰。懆懆、憂不樂也。懆懆、猶戚戚也。正爲許說所本。而陸氏三者皆云七感反。其憒亂有如此者。"}]},"愴":{"expl":"傷也。从心倉聲。","rad":"心","fq":"初亮切","vol":"10","py":"chuànɡ","duan":[{"e":"傷也。","n":"愴訓傷、猶創訓傷也。祭義曰。必有悽愴之心。"}]},"怛":{"expl":"憯也。从心旦聲。","rad":"心","fq":"得案切","vol":"10","py":"dá","duan":[{"e":"㦧也。","n":"匪風。中心怛兮。傳曰。怛、傷也。甫田。勞心怛怛。傳曰。怛怛猶忉忉也。按上章傳曰。㣼㣼、憂勞也。此因其義相同、故曰猶。"}]},"憯":{"expl":"痛也。从心朁聲。","rad":"心","fq":"七感切","vol":"10","py":"cǎn","duan":[{"e":"痛也。从心。朁聲。","n":"七感切。古音在七部。"}]},"慘":{"expl":"毒也。从心參聲。","rad":"心","fq":"七感切","vol":"10","py":"cǎn","duan":[{"e":"毒也。","n":"毒、害也。"}]},"悽":{"expl":"痛也。从心妻聲。","rad":"心","fq":"七稽切","vol":"10","py":"qī","duan":[{"e":"痛也。从心。妻聲。","n":"七稽切。十五部。"}]},"恫":{"expl":"痛也。一曰呻吟也。从心同聲。","rad":"心","fq":"他紅切","vol":"10","py":"tōnɡ","duan":[{"e":"痛也。","n":"大雅思齊傳曰。恫。痛也。康誥。恫鰥乃身。"}]},"悲":{"expl":"痛也。从心非聲。","rad":"心","fq":"府眉切","vol":"10","py":"bēi","duan":[{"e":"痛也。","n":"按憯者、痛之深者也。恫者、痛之專者也。悲者、痛之上騰者也。各從其聲而得之。"}]},"薳":{"expl":"艸也。《左氏傳》：“楚大夫薳子馮。”从艸逺聲。","rad":"艸","fq":"韋委切","vol":"01","py":"wěi","duan":[]},"惻":{"expl":"痛也。从心則聲。","rad":"心","fq":"初力切","vol":"10","py":"cè","duan":[{"e":"痛也。从心。則聲。","n":"初力切。一部。"}]},"惜":{"expl":"痛也。从心㫺聲。","rad":"心","fq":"思積切","vol":"10","py":"xī","duan":[{"e":"痛也。从心。㫺聲。","n":"思積切。古音在五部。"}]},"愍":{"expl":"痛也。从心敃聲。","rad":"心","fq":"眉殞切","vol":"10","py":"mǐn","duan":[{"e":"痛也。","n":"與閔義殊。"}]},"慇":{"expl":"痛也。从心殷聲。","rad":"心","fq":"於巾切","vol":"10","py":"yīn","duan":[{"e":"痛也。","n":"柏舟。耿耿不寐。如有隱憂。傳曰。隱、痛也。此謂隱卽慇之叚借。痛憂猶重憂也。桑柔。憂心慇慇。釋訓。慇慇、憂也。謂憂之切者也。凡經傳隱訓痛者、皆柏舟詩之例。"}]},"㥋":{"expl":"痛聲也。从心依聲。《孝經》曰：“哭不㥋。”","rad":"心","fq":"於豈切","vol":"10","py":"yī","duan":[{"e":"痛聲也。","n":"閒傳。斬衰之哭。若往而不反。齊衰之哭。若往而反。大功之哭。三曲而偯。注曰。一舉聲而三折也。偯聲餘從容。孝經。哭不偯。鄭注云。氣竭而息聲不委曲。按音義皆云說文作㥋。然則許云痛聲者、委曲自見其痛於聲。非痛之至者也。"}]},"䉍":{"expl":"䉍，存也。从心，簡省聲。讀若簡。","rad":"心","fq":"古限切","vol":"10","py":"jiǎn","duan":[{"e":"䉍䉍、在也。","n":"各本作䉍存也三字。今正。釋訓曰。存存、䉍䉍、在也。許本之。今爾雅作存存、萌萌、在也。郭云。未見所出。音武庚反。可謂疏於𦒱覈矣。釋文曰。施亡朋反。字或作蕄。廣韵引爾雅存存、蕄蕄、在也。音武登切。玉篇艸部引爾雅存存、蕄蕄、在也。音莫耕切。又曰𢡗同蕄。或作萌。玉裁按。蕄與䉍相似。而竹艸不同。又後人音切與讀簡大異。葢蕄者、䉍之譌。竹誤而爲艸也。𢡗者、蕄之譌。門誤而爲明也。又誤而去心作萌。而郭反以武庚。玉篇從之。又誤而以萌爲萠。而陳博士施乾反以莫登。廣韵本之。此展轉貤繆之故。叚令景純解讀許書。何難正其形、說其音義也。論語。簡在帝心。卽䉍字之叚借。"}]},"慅":{"expl":"動也。从心蚤聲。一曰起也。","rad":"心","fq":"穌遭切","vol":"10","py":"sāo","duan":[{"e":"動也。","n":"月出。勞心慅兮。常武。徐方繹騷。傳曰。騷、動也。此謂騷卽慅之叚借字也。二字義相近。騷行而慅廢矣。"}]},"感":{"expl":"動人心也。从心咸聲。","rad":"心","fq":"古禫切","vol":"10","py":"ɡǎn","duan":[{"e":"動人心也。","n":"許書有感無憾。左傳、漢書憾多作感。葢憾淺於怨怒、才有動於心而已。"}]},"忧":{"expl":"不動也。从心尤聲。讀若祐。","rad":"心","fq":"于救切","vol":"10","py":"yòu","duan":[{"e":"心動也。","n":"各本作不動也。今正。玉篇曰。心動也。廣韵曰。動也。與頁部之？義近。"}]},"𢛃":{"expl":"怨仇也。从心咎聲。","rad":"心","fq":"其久切","vol":"10","py":"qiú","duan":[{"e":"怨𢛃也。","n":"各本作怨仇也。今正。廣韵亦作怨𢛃。謂怨惡之也。𢛃與咎音同義別。古書多叚咎字爲之。咎行而𢛃廢矣。"}]},"荀":{"expl":"艸也。从艸旬聲。","rad":"艸","fq":"相倫切","vol":"01","py":"xún","duan":[]},"愪":{"expl":"憂皃。从心員聲。","rad":"心","fq":"王分切","vol":"10","py":"yún","duan":[{"e":"𢝊皃。","n":"以下𢝊字卄二見。倂上文四見。各本皆作憂。淺人用俗行字改之也。許造此書。依形立解。斷非此形彼義。牛頭馬脯。以自爲矛盾者。𢝊者、愁也。憂者、和行也。如今本、則此卄餘篆將訓爲和行乎。他書可用叚借。許自爲書不可用叚借。"}]},"怮":{"expl":"憂皃。从心幼聲。","rad":"心","fq":"於虯切","vol":"10","py":"yōu","duan":[{"e":"𢝊皃。从心。幼聲。","n":"於虯切。三部。"}]},"忦":{"expl":"憂也。从心介聲。","rad":"心","fq":"五介切","vol":"10","py":"jiá","duan":[{"e":"𢝊也。从心。介聲。","n":"此與上介下心之字義別。五介切。十五部。"}]},"恙":{"expl":"憂也。从心羊聲。","rad":"心","fq":"余亮切","vol":"10","py":"yànɡ","duan":[{"e":"𢝊也。","n":"古相問曰不恙、曰無恙皆謂無憂也。"}]},"惴":{"expl":"憂懼也。从心耑聲。《詩》曰：“惴惴其慄。”","rad":"心","fq":"之瑞切","vol":"10","py":"zhuì","duan":[{"e":"𢝊懼也。","n":"釋訓、毛傳皆曰。惴惴、懼也。許意懼不足以盡之。故增𢝊字。"}]},"憌":{"expl":"憂也。从心鈞聲。","rad":"心","fq":"常倫切","vol":"10","py":"qiónɡ","duan":[{"e":"𢝊也。从心。鈞聲。","n":"常倫切。十二部。廣韵作？。"}]},"怲":{"expl":"憂也。从心丙聲。《詩》曰：“憂心怲怲。”","rad":"心","fq":"兵永切","vol":"10","py":"bǐnɡ","duan":[{"e":"𢝊也。","n":"釋訓曰。怲怲、憂也。毛傳曰。怲怲、憂盛滿也。怲怲與彭彭音義同。故云憂盛滿。"}]},"惔":{"expl":"憂也。从心炎聲。《詩》曰：“憂心如惔。”","rad":"心","fq":"徒甘切","vol":"10","py":"tán","duan":[{"e":"𢝊也。从心。炎聲。","n":"此以形聲賅會意。徒甘切。八部。"}]},"惙":{"expl":"憂也。从心叕聲。《詩》曰：“憂心惙惙。”一曰意不定也。","rad":"心","fq":"陟劣切","vol":"10","py":"chuò","duan":[{"e":"𢝊也。","n":"釋詁、毛傳同。"}]},"慯":{"expl":"憂也。从心，殤省聲。","rad":"心","fq":"式亮切","vol":"10","py":"shānɡ","duan":[{"e":"𢝊也。","n":"周南卷耳傳曰。傷、思也。此傷卽慯之叚借。思與憂義相近也。方言傷、廣雅作慯。"}]},"莋":{"expl":"越嶲縣名，見《史記》。从艸作聲。","rad":"艸","fq":"在各切","vol":"01","py":"zuó","duan":[]},"愁":{"expl":"憂也。从心秋聲。","rad":"心","fq":"士尤切","vol":"10","py":"chóu","duan":[{"e":"𢝊也。","n":"或借爲揫字。鄉飲酒義曰秋之爲言揫也是。"}]},"愵":{"expl":"憂皃。从心弱聲。讀與惄同。","rad":"心","fq":"奴歴切","vol":"10","py":"nì","duan":[{"e":"𢝊皃。","n":"毛詩。惄如輈飢。韓詩作愵如。方言。愵、憂也。自關而西秦晉之閒或曰惄。葢古惄愵通用。"}]},"惂":{"expl":"憂困也。从心臽聲。","rad":"心","fq":"苦感切","vol":"10","py":"kǎn","duan":[{"e":"𢝊困也。从心。臽聲。","n":"苦感切。八部。"}]},"悠":{"expl":"憂也。从心攸聲。","rad":"心","fq":"以周切","vol":"10","py":"yōu","duan":[{"e":"𢝊也。","n":"釋訓曰。悠悠、洋洋、思也。小雅。悠悠我里。傳曰。悠悠、憂也。按此傳乃悠之本義。渭陽。悠悠我思。無傳。葢同釋訓。若黍離悠悠蒼天傳曰。悠悠、遠意。此謂悠同攸。攸同脩。古多叚攸爲脩。長也、遠也。"}]},"悴":{"expl":"憂也。从心卒聲。讀與《易》萃卦同。","rad":"心","fq":"秦醉切","vol":"10","py":"cuì","duan":[{"e":"𢝊也。","n":"方言。悴、傷也。傷卽慯字。"}]},"慁":{"expl":"憂也。从心圂聲。一曰擾也。","rad":"心","fq":"胡困切","vol":"10","py":"hùn","duan":[{"e":"𢝊也。","n":"昭六年左傳曰。主不慁賓。杜云。慁、患也。"}]},"𢟤":{"expl":"楚潁之閒謂憂曰𢟤。从心𠩺聲。","rad":"心","fq":"力至切","vol":"10","py":"lí","duan":[{"e":"楚潁之閒謂𢝊曰𢟤。从心。𠩺聲。","n":"力至切。按古音在一部。玉篇、廣韵皆力之切。至韵本無此字。至集韵乃並見之至二韵。大徐力至二字、乃力之之誤也。"}]},"𢖳":{"expl":"憂也。从心于聲。讀若吁。","rad":"心","fq":"況于切","vol":"10","py":"xū","duan":[{"e":"𢝊也。","n":"卷耳。云何吁矣。傳曰。吁、𢝊也。此謂吁卽𢖳之叚借也。于部曰。吁、驚詞也。本義不訓憂。何人斯曰。云何其盱。都人士曰。云何𥃳矣。𥃳亦𢖳之叚借。毛無傳。疑卷耳本亦作盱也。盱、張目也。釋詁。盱、憂也。盱本或作𢖳。"}]},"忡":{"expl":"憂也。从心中聲。《詩》曰：“憂心忡忡。”","rad":"心","fq":"敕中切","vol":"10","py":"chōnɡ","duan":[{"e":"𢝊也。","n":"按也當作皃。釋訓曰。忡忡、憂也。毛傳曰。忡忡猶衝衝也。"}]},"悄":{"expl":"憂也。从心肖聲。《詩》曰：“憂心悄悄。”","rad":"心","fq":"親小切","vol":"10","py":"qiǎo","duan":[{"e":"𢝊也。","n":"按也當作皃。釋訓曰。悄悄、憂也。毛傳曰。悄悄、憂皃。"}]},"䄏":{"expl":"地反物爲䄏也。从示芺聲。","rad":"示","fq":"於喬切","vol":"01","py":"yāo","duan":[{"e":"地反物爲䄏也。","n":"左氏傳。伯宗曰。天反時爲災。地反物爲妖。民反德爲亂。亂則妖災生。釋例曰。此傳地反物惟言妖耳。洪範五行傳則妖孽禍痾眚祥六者。以積漸爲義。按虫部云。衣服歌䚻艸木之怪謂之䄏。禽獸蟲蝗之怪謂之𧕏。此葢統言皆謂之䄏。析言則䄏𧕏異也。䄏省作祅。經傳通作妖。"}]},"蓀":{"expl":"香艸也。从艸孫聲。","rad":"艸","fq":"思渾切","vol":"01","py":"sūn","duan":[]},"慽":{"expl":"憂也。从心戚聲。","rad":"心","fq":"倉歴切","vol":"10","py":"qī","duan":[{"e":"𢝊也。","n":"小明曰。政事愈戚。傳曰。戚、迫也。又曰。自詒伊戚。傳曰。戚、憂也。按下傳謂戚卽慽之叚借字也。戚者、戉也。"}]},"𢝊":{"expl":"愁也。从心从頁。","rad":"心","fq":"於求切","vol":"10","py":"yōu","duan":[{"e":"愁也。","n":"上文云愁、𢝊也。此云𢝊、愁也。二篆互訓。不知何時淺人盡易許書𢝊字。許於夊部曰。憂、和行也。从夊、𢝊聲。非和行則不得从夊矣。又引詩布政憂憂。於此知許所據詩惟此作憂。其他訓愁者皆作𢝊。自叚憂代𢝊。則不得不叚憂代憂。而商頌乃作布政優優。優者、饒也。一曰倡也。"}]},"患":{"expl":"憂也。从心上貫吅，吅亦聲。","rad":"心","fq":"胡丱切","vol":"10","py":"huàn","duan":[{"e":"𢝊也。从心上貫吅。吅亦聲。","n":"此八字乃淺人所改竄。古本當作从心毌聲四字。毌貫古今字。古形横直無一定。如目字偏旁皆作？。患字上从毌。或横之作申。而又析爲二中之形。葢恐類於？也。春秋繁露曰。心止於一中者謂之忠。持二中者謂之患。患、人之中不一者也。董氏所說固非字之本形矣。古毌多作串。廣韵曰。串、穿也。親串卽親毌。貫、習也。大雅。串夷載路。傳曰。串、習也。葢其字本作毌。爲慣摜字之叚。借也。廣韵又謂炙肉之器爲丳。初限切。亦毌字之變體也。患胡丱切。十四部。舊多讀平聲。"}]},"恇":{"expl":"怯也。从心、匡，匡亦聲。","rad":"心","fq":"去王切","vol":"10","py":"kuānɡ","duan":[{"e":"㹤也。","n":"犬部曰。㹤、多畏也。杜林作怯。素問。尺虚者行歩恇然。王注。恇然不足。樂記。衆不匡懼。此叚匡爲恇也。"}]},"㤲":{"expl":"思皃。从心夾聲。","rad":"心","fq":"苦叶切","vol":"10","py":"qiè","duan":[{"e":"思皃。从心。夾聲。","n":"苦叶切。八部。"}]},"懾":{"expl":"失气也。从心聶聲。一曰服也。","rad":"心","fq":"之涉切","vol":"10","py":"shè","duan":[{"e":"失气也。","n":"失气言則曰讋。"}]},"憚":{"expl":"忌難也。从心單聲。一曰難也。","rad":"心","fq":"徒案切","vol":"10","py":"dàn","duan":[{"e":"忌難也。","n":"憎惡而難之也。詩亦叚爲癉字。大東哀我憚人是也。"}]},"悼":{"expl":"懼也。陳楚謂懼曰悼。从心卓聲。","rad":"心","fq":"徒到切","vol":"10","py":"dào","duan":[{"e":"懼也。陳楚謂懼曰悼。","n":"方言。㥄、憮、矜、悼、憐、哀也。齊魯之閒曰矜。陳楚之閒曰悼。趙魏燕代之閒曰㥄。自楚之北郊曰憮。秦晉之閒或曰矜。或曰悼。按方言甚明了。許易哀爲懼。未詳。方言又曰。悼、傷也。秦謂之悼。皆不訓懼。檜風。中心是悼。傳曰。悼、動也。於懼義相合。小雅。上帝甚蹈。傳曰。蹈、動也。謂蹈卽悼之叚借也。故鄭申之云蹈讀曰悼。"}]},"恐":{"expl":"懼也。从心𢀜聲。","rad":"心","fq":"丘隴切","vol":"10","py":"kǒnɡ","duan":[{"e":"懼也。从心。𢀜聲。","n":"丘隴切。九部。"}]},"慴":{"expl":"懼也。从心習聲。讀若疊。","rad":"心","fq":"之涉切","vol":"10","py":"zhé","duan":[{"e":"懼也。从心。習聲。讀若㬪。","n":"之涉切。七部。"}]},"蔬":{"expl":"菜也。从艸疏聲。","rad":"艸","fq":"所菹切","vol":"01","py":"shū","duan":[]},"怵":{"expl":"恐也。从心术聲。","rad":"心","fq":"丑律切","vol":"10","py":"chù","duan":[{"e":"恐也。","n":"孟子云怵惕。"}]},"惕":{"expl":"敬也。从心易聲。","rad":"心","fq":"他歴切","vol":"10","py":"tì","duan":[{"e":"敬也。从心。易聲。","n":"他歷切。十六部。"}]},"㤨":{"expl":"戰慄也。从心共聲。","rad":"心","fq":"戶工切","vol":"10","py":"ɡǒnɡ","duan":[{"e":"戰栗也。","n":"栗舊作慄。今正。大學曰。恂栗也。戰國策曰。戰戰栗栗。日愼一日。方言。蛩㤨、戰慄也。荆吳曰蛩㤨。蛩㤨又恐也。注。鞏、恭兩音。"}]},"㤥":{"expl":"苦也。从心亥聲。","rad":"心","fq":"胡槩切","vol":"10","py":"hài","duan":[{"e":"苦也","n":"通俗文。思愁曰㤥。廣雅。㤥、痛也。"}]},"惶":{"expl":"恐也。从心皇聲。","rad":"心","fq":"胡光切","vol":"10","py":"huánɡ","duan":[{"e":"恐也。从心。皇聲。","n":"胡光切。十部。"}]},"悑":{"expl":"惶也。从心甫聲。","rad":"心","fq":"普故切","vol":"10","py":"bù","duan":[{"e":"惶也。从心。甫聲。","n":"普故切。五部。"}]},"慹":{"expl":"悑也。从心執聲。","rad":"心","fq":"之入切","vol":"10","py":"zhí","duan":[{"e":"悑也。","n":"莊子齊物論。哀樂慮歎變慹。司馬彪云。慹、不動皃。桂馥曰。不、當作心。"}]},"𢢞":{"expl":"悑也。从心毄聲。","rad":"心","fq":"苦計切","vol":"10","py":"qì","duan":[{"e":"𢟡也。","n":"此與𢟡篆轉注。"}]},"𢟡":{"expl":"𢢞也。从心𤰈聲。","rad":"心","fq":"蒲拜切","vol":"10","py":"bèi","duan":[{"e":"𢢞也。","n":"通俗文。疲極曰𢣍。"}]},"惎":{"expl":"毒也。从心其聲。《周書》曰：“來就惎惎。”","rad":"心","fq":"渠記切","vol":"10","py":"jì","duan":[{"e":"毒也。","n":"左傳用此字。有用其本義者。如定四年。惎閒王室。哀元年。惎澆能戒之。注云。惎、毒也。此用其本義也。宣十二年。晉人惎之脫扃。注云。惎、教也。此叚惎爲誋也。誋、誡也。"}]},"芊":{"expl":"艸盛也。从艸千聲。","rad":"艸","fq":"倉先切","vol":"01","py":"qiān","duan":[]},"恥":{"expl":"辱也。从心耳聲。","rad":"心","fq":"敕里切","vol":"10","py":"chǐ","duan":[{"e":"辱也。","n":"辰部曰。辱、恥也。二篆爲轉注。"}]},"㥏":{"expl":"青徐謂慙曰㥏。从心典聲。","rad":"心","fq":"他典切","vol":"10","py":"tiǎn","duan":[{"e":"靑徐謂慙曰㥏。","n":"方言。㥏、恧、慙也。荆揚青徐之閒曰㥏。若梁益秦晉之閒言心内慙矣。山之東西自愧曰恧。"}]},"㤁":{"expl":"辱也。从心天聲。","rad":"心","fq":"他點切","vol":"10","py":"tiǎn","duan":[{"e":"辱也。","n":"小雅小宛曰。無忝爾所生。傳云。忝、辱也。"}]},"慙":{"expl":"媿也。从心斬聲。","rad":"心","fq":"昨甘切","vol":"10","py":"cán","duan":[{"e":"媿也。","n":"女部曰。媿、慙也。二篆爲轉注。"}]},"恧":{"expl":"慙也。从心而聲。","rad":"心","fq":"女六切","vol":"10","py":"nǜ","duan":[{"e":"慙也。从心。而聲。","n":"女六切。古音在一部。音轉入三部。屋韵。"}]},"怍":{"expl":"慙也。从心，作省聲。","rad":"心","fq":"在各切","vol":"10","py":"zuò","duan":[{"e":"慙也。从心。乍聲。","n":"依小徐本。在各切。五部。"}]},"憐":{"expl":"哀也。从心粦聲。","rad":"心","fq":"落賢切","vol":"10","py":"lián","duan":[{"e":"哀也。从心。㷠聲。","n":"落賢切。十二部。"}]},"㦁":{"expl":"泣下也。从心連聲。《易》曰：“泣涕㦁如。”","rad":"心","fq":"力延切","vol":"10","py":"lián","duan":[{"e":"泣下也。","n":"無聲出涕曰泣。"}]},"忍":{"expl":"能也。从心刃聲。","rad":"心","fq":"而軫切","vol":"10","py":"rěn","duan":[{"e":"能也。","n":"能者、熊屬。能獸堅中。故賢者偁能。而彊壯偁能傑。凡敢於行曰能。今俗所謂能榦也。敢於止亦曰能。今俗所謂能耐也。能耐本一字。俗殊其音。忍之義亦兼行止。敢於殺人謂之忍。俗所謂忍害也。敢於不殺人亦謂之忍。俗所謂忍耐也。其爲能一也。仁義本無二事。先王不忍人之心、不忍人之政中皆必兼斯二者。"}]},"㥝":{"expl":"厲也。一曰止也。从心弭聲。讀若沔。","rad":"心","fq":"弥兖切","vol":"10","py":"mǐ","duan":[{"e":"厲也。","n":"葢淬厲之意。"}]},"茗":{"expl":"荼芽也。从艸名聲。","rad":"艸","fq":"莫迥切","vol":"01","py":"mínɡ","duan":[]},"㣻":{"expl":"懲也。从心乂聲。","rad":"心","fq":"魚胏切","vol":"10","py":"yì","duan":[{"e":"懲也。","n":"古多用乂、艾爲之而㣻廢矣。"}]},"懲":{"expl":"㣻也。从心徵聲。","rad":"心","fq":"直陵切","vol":"10","py":"chénɡ","duan":[{"e":"㣻也。","n":"二篆爲轉注。古亦叚徵爲懲。"}]},"憬":{"expl":"覺寤也。从心景聲。《詩》曰：“憬彼淮夷。”","rad":"心","fq":"俱永切","vol":"10","py":"jǐnɡ","duan":[{"e":"覺悟也。从心。景聲。","n":"俱永切。"}]},"慵":{"expl":"嬾也。从心庸聲。","rad":"心","fq":"蜀容切","vol":"10","py":"yōnɡ","duan":[]},"悱":{"expl":"口悱悱也。从心非聲。","rad":"心","fq":"𢾭尾切","vol":"10","py":"fěi","duan":[]},"怩":{"expl":"衂怩，慙也。从心尼聲。","rad":"心","fq":"女夷切","vol":"10","py":"ní","duan":[]},"惉":{"expl":"惉懘，煩聲也。从心沾聲。","rad":"心","fq":"尺詹切","vol":"10","py":"zhān","duan":[]},"懘":{"expl":"惉懘也。从心滞聲。","rad":"心","fq":"尺制切","vol":"10","py":"chì","duan":[]},"懇":{"expl":"悃也。从心豤聲。","rad":"心","fq":"康恨切","vol":"10","py":"kěn","duan":[]},"忖":{"expl":"度也。从心寸聲。","rad":"心","fq":"倉本切","vol":"10","py":"cǔn","duan":[]},"薌":{"expl":"榖气也。从艸鄉聲。","rad":"艸","fq":"許良切","vol":"01","py":"xiānɡ","duan":[]},"怊":{"expl":"悲也。从心召聲。","rad":"心","fq":"敕宵切","vol":"10","py":"chāo","duan":[]},"慟":{"expl":"大哭也。从心動聲。","rad":"心","fq":"徒弄切","vol":"10","py":"tònɡ","duan":[]},"惹":{"expl":"亂也。从心若聲。","rad":"心","fq":"人者切","vol":"10","py":"rě","duan":[]},"恰":{"expl":"用心也。从心合聲。","rad":"心","fq":"苦狹切","vol":"10","py":"qià","duan":[]},"悌":{"expl":"善兄弟也。从心弟聲。經典通用弟。","rad":"心","fq":"特計切","vol":"10","py":"tì","duan":[]},"懌":{"expl":"說也。从心睪聲。經典通用釋。","rad":"心","fq":"羊益切","vol":"10","py":"yì","duan":[]},"惢":{"expl":"心疑也。从三心。凡惢之屬皆从惢。讀若《易》“旅瑣瑣”。","rad":"惢","fq":"","vol":"10","py":"suǒ","duan":[{"e":"心疑也。","n":"魏都賦曰。神惢形茹。"}]},"繠":{"expl":"垂也。从惢糸聲。","rad":"惢","fq":"如壘切","vol":"10","py":"ruǐ","duan":[{"e":"𠂹也。","n":"𠂹各本作？。誤。今正。左傳曰。佩玉繠兮。余無所繫之。旨酒一盛兮。余與褐之父睨之。注云。繠然、服飾僃也。按繠然、垂意。左氏繠繫睨爲韵。古音十六部也。"}]},"水":{"expl":"凖也。北方之行。象眾水並流，中有微陽之气也。凡水之屬皆从水。","rad":"水","fq":"式軌切","vol":"11","py":"shuǐ","duan":[{"e":"準也。","n":"準古音追。上聲。此以曡韵爲訓。如戸護、尾微之例。釋名曰。水、準也。準、平也。天下莫平於水。故匠人建國必水地。"}]},"汃":{"expl":"西極之水也。从水八聲。《爾雅》曰：“西至汃國，謂四極。”","rad":"水","fq":"府巾切","vol":"11","py":"bīn","duan":[{"e":"西極之水也。从水。八聲。","n":"府巾切。十二部。"}]},"藏":{"expl":"匿也。","rad":"艸","fq":"昨郎切","vol":"01","py":"cánɡ","duan":[]},"河":{"expl":"水。出焞煌塞外昆侖山，發原注海。从水可聲。","rad":"水","fq":"乎哥切","vol":"11","py":"hé","duan":[{"e":"河水。","n":"各本水上無河字。由盡𠜂篆下複舉隸字。因幷不可𠜂者而𠜂之也。許君原本當作河水也三字。河(篆)者、篆文也。河水也者、其義也。此以義釋形之例。毛傳云。洽、水也。渭、水也。此繹經之例。"}]},"泑":{"expl":"澤。在昆侖下。从水幼聲。讀與𣢜同。","rad":"水","fq":"於糾切","vol":"11","py":"yōu","duan":[{"e":"泑澤。","n":"澤上補一字。"}]},"涷":{"expl":"水。出發鳩山，入於河。从水東聲。","rad":"水","fq":"德紅切","vol":"11","py":"dōnɡ","duan":[{"e":"涷水。","n":"水上補涷字。以下皆同。"}]},"涪":{"expl":"水。出廣漢剛邑道徼外，南入漢。从水咅聲。","rad":"水","fq":"縛牟切","vol":"11","py":"fú","duan":[{"e":"涪水。","n":"句。以下同。"}]},"潼":{"expl":"水。出廣漢梓潼北界，南入墊江。从水童聲。","rad":"水","fq":"徒紅切","vol":"11","py":"tónɡ","duan":[{"e":"潼水。出廣漢梓潼北畍。南入褺江。","n":"褺各本作墊。今正。廣漢郡梓潼、前後二志同。前志曰。樟潼五婦山、馳水所出。南入涪。行五百五十里。應劭注云。潼水所出。南入墊江。水經曰。樟潼水出其縣北畍。西南入於涪。又西南至小廣魏南。入於墊江。按馳水、潼水、梓潼水異名同實。五婦山卽今四川保寧府劒州州西北五十里之五子山。今劒州及綿州之梓潼縣、葢漢梓潼地。潼水出五子山之西大山。東南流、經今梓潼縣。又經潼川府之鹽亭縣。又至射洪縣東南之獨坐山。入涪江。今謂之潼江、射江、瀰江。許云南入褺江。卽謂今射洪東南入涪江。涪江下流至重慶府之合州、合嘉陵江也。漢志墊江、應劭音徒浹反。孟康音重曡之曡。許書衣部云褺、重衣也。巴郡有褺江縣。此縣爲嘉陵江、渠江、涪江會合之地。"}]},"江":{"expl":"水。出蜀湔氐徼外崏山，入海。从水工聲。","rad":"水","fq":"古雙切","vol":"11","py":"jiānɡ","duan":[{"e":"江水。出蜀湔氏徼外崏山。入海。","n":"蜀郡湔氐道、二志同。前志曰。湔氐道、禹貢崏山𡉈西徼外。江水所出。東南至江都入海。過郡九。行七千二百六十里。今本九作七。行七千作行二千。今依徐鍇所引正。過郡九者、蜀郡、犍爲、巴郡、南郡、長沙、江夏、廬江、丹陽、廣陵國也。湔氐徼外崏山、卽禹貢岷山。封禪書謂之瀆山。李膺益州記詞之羊膊嶺。今四川龍安府松潘㕔卽松潘衞衞北二百三十里大分水嶺是也。流經茂州、成都府、眉州、嘉定府、敘州府、瀘州、重慶府、忠州、夔州府、湖廣之宜昌府、荆州府、岳州府、武昌府、漢陽府、黃州府、江西之九江府、江南之安慶府、池州府、太平府、江甯府、鎭江府、常州府諸境。至北岸通州、南岸蘇州府昭文縣境入海。此禹貢漢志所謂北江入海也。"}]},"沱":{"expl":"江別流也。出㟭山東，別爲沱。从水它聲。","rad":"水","fq":"徒何切","vol":"11","py":"tuó","duan":[{"e":"江別流也。","n":"召南曰。江有沱。釋水曰。水自江出爲沱。毛傳曰。沱、江之別者。按今說文衍流字。宜𠜂。沱爲江之別。如勃澥爲海之別。立文正同。禹貢某氏。注云。沱、江別名。江別名、謂江之別出者之名也。別皆彼列切。"}]},"浙":{"expl":"江。水東至會稽山陰爲浙江。从水折聲。","rad":"水","fq":"旨熱切","vol":"11","py":"zhè","duan":[{"e":"江水東至會稽山陰爲浙江。","n":"會稽郡山陰、二志同。今浙江省紹興府山陰縣是其地。今俗皆謂錢唐江爲浙江。不知錢唐江、地理志水經皆謂之漸江。江至會稽山陰古曰浙江。說文浙漸二篆分舉劃然。後人乃以浙名冒漸。葢由二水相合。如吳越春秋越王至浙江之上、史記楚威王盡取故吳地至浙江、始皇至錢唐臨浙江皆謂是也。今則江故道不可攷矣。歙金氏榜禮箋曰。班志南江、𡉈會稽吳縣南。東入海。楊州川。北江、𡉈毗陵北。東入海。楊州川。中江、出丹陽蕪湖西南。東至陽羨入海。楊州川。毗陵之北江卽今大江。其蕪湖之中江、吳縣之南江逕流湮廢。據班志丹陽石城下云。分江水、首受江。東至餘姚入海。過郡二。行千二百里。說文江水至會稽山陰爲浙江。闞駰十三州志曰。江水至會稽與浙江合。晉"}]},"涐":{"expl":"水。出蜀汶江徼外，東南入江。从水我聲。","rad":"水","fq":"五何切","vol":"11","py":"é","duan":[{"e":"𣴮水。出蜀汶江徼外。東南入江。","n":"蜀郡汶江、見前志。後志云。蜀郡汶江道。前志蜀郡靑衣下云。大渡水東南至南安入渽。汶江下云。渽水出徼外。南至南安東入江。過郡三。行三千四十里。水經曰。大江又東南過犍爲武陽縣。靑衣水、沫水從西南來合而注之。又曰。靑衣水出靑衣縣西蒙山。東與沫水合。至犍爲南安縣入江。沫水出廣柔徼外。東南過旄牛縣北。又東至越巂靈道縣。出蒙山南。東北與靑衣水合。東入於江。注曰。江水又東南徑南安縣西。縣治靑衣水會。衿帶二水矣。縣南有峨眉山。有濛水。卽大渡水也。水發蒙谿。東南與渽水合。渽水出徼外。徑汶江道南。至南安入大渡水。大渡水、又東入江。按經曰武陽。注曰南安。二縣壤接。犍爲南安者、今四川嘉定府治附郭縣曰樂山是也。蜀郡汶江縣"}]},"湔":{"expl":"水。出蜀郡緜虒玉壘山，東南入江。从水前聲。一曰手𤃬之。","rad":"水","fq":"子仙切","vol":"11","py":"jiān","duan":[{"e":"湔水。出蜀郡緜虒玉壘山。東南入江。","n":"郡字衍。前志曰。蜀郡緜虒。後志曰。蜀郡緜虒道。有蠻夷曰道。前志省文耳。前志曰。緜虒玉壘山、湔水所出。東南至江陽入江。過郡三。行千八百九十里。又曰。廣漢郡緜竹縣紫巖山、緜水所出。東至新都北入雒。廣漢郡雒縣章山、雒水所出。南至新都谷（字誤）入湔。過郡三者、蜀郡廣漢犍爲也。湔水、緜水、雒水三水互受通偁。水經云。又東過江陽縣南。雒水從三危山東過廣魏雒縣南。東南注之。是卽漢志之湔水兼緜雒至江陽入江者也。三危山、葢卽漢志之玉壘山。水經以雒爲湔也。江陽今四川瀘州緜虒玉壘山當𡉈松潘衞境內。蜀都賦曰。廓靈關以爲門。包玉壘而爲字。劉逵注。玉壘、山名。湔水出焉。𡉈成都西北。岷山畍𡉈後。故曰字。靈關𡉈前。故曰門也。今"}]},"蕆":{"expl":"《左氏傳》：“以蕆陳事。”杜預注云：蕆，敕也。从艸未详。","rad":"艸","fq":"丑善切","vol":"01","py":"chǎn","duan":[]},"沫":{"expl":"水。出蜀西徼外，東南入江。从水末聲。","rad":"水","fq":"莫割切","vol":"11","py":"mò","duan":[{"e":"沫水。出蜀西南徼外。東南入江。","n":"蜀謂蜀郡也。不言何縣者、未審也。沫水卽𣴮水。兩列之、葢許有未審。"}]},"溫":{"expl":"水。出犍爲涪，南入黔水。从水𥁕聲。","rad":"水","fq":"烏魂切","vol":"11","py":"wēn","duan":[{"e":"溫水。出楗爲符。","n":"句。"}]},"灊":{"expl":"水。出巴郡宕渠，西南入江。从水鬵聲。","rad":"水","fq":"昨鹽切","vol":"11","py":"qián","duan":[{"e":"灊水。出巴郡宕渠。西南入江。","n":"巴郡宕渠、二志同。今順慶府渠縣縣東北七十里有宕渠城是也。前志宕渠下曰。灊水西南入江。不曹水出東北南入灊。水經於江水曰。又東北至巴郡江州縣東。強水、涪水、漢水、白水、宕渠水五水合南流注之。酈云。宕渠水卽潛水渝水矣。水經又曰。潛水出巴郡宕渠縣。又南入於江。按許云西南入江。則此水必合嘉陵江至合州入江。未詳今之何水。鄭注禹貢梁州曰。漢別爲潛。其穴本小。水積成澤。流與漢合。蜀都賦。演以潛沫。劉逵云。禹貢梁州沲潛旣道。有水從漢中沔陽縣南流。至梓潼漢壽縣入穴中。通岡山下。西南潛出。今名伏水。舊說云禹貢潛水也。劉澄之、酈道元說與逵略同。或以今保寧府廣元縣之由七盤關經神宣驛又經龍洞口至朝天驛北穿穴而出入嘉陵之水"}]},"沮":{"expl":"水。出漢中房陵，東入江。从水且聲。","rad":"水","fq":"子余切","vol":"11","py":"jū","duan":[{"e":"沮水。出漢中房陵。東入江。","n":"漢中郡房陵、二志同。左傳之麇國。成大心敗麇師於防渚、闞駰曰。防卽房陵也。今湖北鄖縣府房縣是其地。左傳定四年。吳人敗楚及郢。楚子出涉雎。哀六年。昭王曰。江漢雎漳、楚之望也。前志房陵下曰。東山、沮水所出。東至郢入江。應劭南郡臨沮注曰。沮水、出漢中房陵。東入江。水經曰。沮水、出漢中房陵縣東山。東南過臨沮縣畍。又東南過枝江縣。東南入於江。今此水出房縣西南二百里之景山。經當陽縣合南漳水。至荊州府城西南周寅店入江。顧景範曰。其字正作沮。左傳作雎。皆七餘反。後譌爲柤。讀曰租。字與音俱變矣。今襄陽沮水左右地皆曰沮中。亦謂之柤中。襄陽記。柤中𡉈上黃畍。吳志赤烏四年諸葛瑾取柤中。魏志正始四年諸葛瑾攻沮中。正是一事"}]},"滇":{"expl":"益州池名。从水眞聲。","rad":"水","fq":"都年切","vol":"11","py":"diān","duan":[{"e":"益州池也。","n":"二志皆云益州郡滇池縣。前志滇池縣下。滇池澤𡉈西北。南中志曰。有澤水周迴二百里。所出深廣。下流淺狹。如倒流。故曰滇池。今云南云南府附郭昆明縣府城南之滇池是也。城西南八十里爲海口大河、卽滇池導流之處也。下流至武定府注於金沙江。金沙江𡉈四川敘州府入江。"}]},"涂":{"expl":"水。出益州牧靡南山，西北入澠。从水余聲。","rad":"水","fq":"同都切","vol":"11","py":"tú","duan":[{"e":"涂水。出益州牧靡南山。西北入繩。","n":"繩各本譌作澠。今正。牧前志作收。後志作牧。華陽國志竟作升。李奇曰。靡音麻。收靡卽升麻。常璩曰。升麻縣山出好升麻。收升牧三字皆同紐。𥻳釋益州太守碑牧靡字三見。晉書亦作牧矣。益州郡牧靡、二志同。前志曰。南山臘、涂水所出。西北至越巂入繩。過郡二。行千二十里。水經注若水篇曰。若水、又東。涂水注之。水出建寧郡之收靡縣南山。縣山竝卽草以立名。山𡉈縣東烏句山南五百里。山生收靡。可以解毒。涂水導源臘谷。西北流至越巂入若水。按涂水出臘谷。故漢志謂之臘。涂水、漢志說文皆云入繩。而水經注云入若水者。善長云若水、又逕越巂大莋縣入繩。繩水出徼外。南逕旄牛道。至大莋與若水合。自下亦通謂之繩水矣。諸書錄記羣水。或言入若。又"}]},"沅":{"expl":"水。出牂牁故且蘭，東北入江。从水元聲。","rad":"水","fq":"愚袁切","vol":"11","py":"yuán","duan":[{"e":"沅水。出牂柯故且蘭。東北入江。","n":"牂柯郡故且蘭、二志同。且音苴。子閭反。前志故且蘭下曰。沅水、東南至益陽入江。過郡二。行二千五百三十里。按益陽屬長沙國。漢志東南、以進朢準之、當從說文作東北。過郡二、當作三。謂牂柯、武陵、長沙國也。水經曰。沅水、出牂柯故且蘭縣。爲旁溝水。又東至鐔成縣爲沅水。東過無陽縣。又東北過臨沅縣南。又東至長沙下雋縣西北入于江。水道提綱曰。沅水數源。一曰鎭陽江。出貴州平越府東北之黃平州南金鳳山。一曰淸水江。其源有二。北曰平越府西北之豬染江。南曰都勻府西南之馬尾河。古稱沅水出故且蘭、必𢫾豬梁江及豬梁所納之卞龍河也。淸水江與鎭陽江合於黔陽縣。西經常德府治武陵縣西南而入洞庭湖。源流實二千三百餘里。古稱辰酉敘无漸五溪"}]},"淹":{"expl":"水。出越巂徼外，東入若水。从水奄聲。","rad":"水","fq":"英廉切","vol":"11","py":"yān","duan":[{"e":"淹水。出越巂徼外。東入若水。","n":"越巂郡屬益州、二志同。巂音先蘂反。今四川語言讀如西上聲。佩觿謂字作嶲與巂不同者、謬說也。同字異音耳。不言何縣徼外者、未審也。水經曰。淹水、出越巂遂久縣徼外。東南至靑蛉縣。又東過姑複縣南。東入於若水。然則淹水亦合金沙江以入江者也。越巂郡今四川寧遠府是其地。"}]},"溺":{"expl":"水。自張掖𠛹丹西，至酒泉合黎，餘波入于流沙。从水弱聲。桑欽所說。","rad":"水","fq":"而灼切","vol":"11","py":"ruò","duan":[{"e":"溺水。自張掖𠜂丹西至酒泉合黎。餘波入于流沙。","n":"禹貢曰。弱水旣西。又曰。道弱水至于合黎。餘波入于流沙。張掖郡𠜂丹、二志同。前志𠜂丹下曰。桑欽以爲道弱水自此、西至酒泉合黎。又張掖郡居延下曰。居延澤𡉈東北。古文以爲流沙。水經曰。合離山𡉈酒泉會水縣東北。流沙地𡉈張掖居延縣東北。今甘肅舊山丹衞卽𠜂丹廢縣。舊甘州衞西北千二百里有故居延城。故居延城東北有居延海。衞西北四十里有合黎山。衞西有弱水。胡氏渭禹貢錐𢫾曰。溺水正流入居延海。其餘波則入流沙。流沙非居延也。"}]},"洮":{"expl":"水。出隴西臨洮，東北入河。从水兆聲。","rad":"水","fq":"土刀切","vol":"11","py":"táo","duan":[{"e":"洮水。出隴西臨洮。東北入河。","n":"隴西郡臨洮、二志同。前志臨洮下曰。洮水出西羌中。北至枸罕。東入西。枹罕屬金城郡。東入西、西字誤。當依水經注作東入河。水經曰。河水又東入塞。過敦煌酒泉張掖郡南。又東過隴西河關縣北。洮水從東南來流注之。酈注引段國沙州記曰。洮水與墊江水俱出嵹臺山。山南卽墊江源。山東卽洮水源。按嵹臺山卽西頃山也。墊江卽入西漢水之白水也。今甘肅蘭州府狄道州州西南二百二十里有臨洮城、漢縣也。今洮河出洮州衞西南邊外之西傾山東麓。東北流經狄道州南。至蘭州府西境入河。曰洮口。行八百餘里。"}]},"蘸":{"expl":"以物没水也。此蓋俗語。从艸未详。","rad":"艸","fq":"斬陷切","vol":"01","py":"zhàn","duan":[]},"涇":{"expl":"水。出安定涇陽幵頭山，東南入渭。雝州之川也。从水坙聲。","rad":"水","fq":"古靈切","vol":"11","py":"jīnɡ","duan":[{"e":"涇水。出安定涇陽幵頭山。東南入渭。","n":"禹貢雍州曰。涇屬渭汭。周禮職方氏曰。雍州、其川涇。前志曰。安定郡涇陽、幵頭山在西。禹貢涇水所出。東南至陽陵入渭。過郡三。行千六十里。雍州川。陽陵屬左馮翊。過郡三者、安定扶風馮翊也。今甘肅平涼府附郭平涼縣府西南有故涇陽城。漢縣也。幵頭山亦作筓頭山。始皇紀作雞頭山。在今平涼府西南四十里。今涇水出山之涇谷。經涇州。又經陝西邠州長武縣。至西安府高陵縣西南二十里入渭。曰涇口。大致東南流也。涇濁渭淸。故詩曰涇以渭濁。涇水漑田之利。自秦漢鄭國白公而後。迄於唐宋元明。皆修復白渠。"}]},"渭":{"expl":"水。出隴西首陽渭首亭南谷，東入河。从水胃聲。杜林說。《夏書》以爲出鳥鼠山。雝州浸也。","rad":"水","fq":"云貴切","vol":"11","py":"wèi","duan":[{"e":"渭水。出隴西首陽渭首亭南谷。東南入河。","n":"隴西郡首陽、二志同。首陽縣。今甘肅蘭州府渭源縣當是其地。禹貢曰。道渭自鳥鼠同穴。入于河。前志首陽下曰。禹貢鳥鼠同穴山在西南。渭水所出。東至船司空入河。過郡四。行千八百七十里。雍州寖。過郡四者、天水扶風京兆馮翊也。水經曰。渭水出隴西首陽縣渭谷亭南鳥鼠山。注曰。渭水出隴西首陽縣首陽山渭首亭南谷。山在鳥鼠山西北。縣有高城嶺。嶺上有城。號渭源城。渭水出焉。東北流逕首陽縣西與別源合。別源出鳥鼠山渭水谷。禹貢所謂渭出鳥鼠者也。按酈注葢本說文。較說文多首陽山三字。疑今說文奪去。酈依說文、故以首陽山南谷與鳥鼠山爲二。以今地志言之。皆在渭源縣西。相歫甚近。今渭水出此。經鞏昌府及寧遠縣、伏羌縣、秦安縣、秦州、淸水"}]},"漾":{"expl":"水。出隴西相道，東至武都爲漢。从水羕聲。","rad":"水","fq":"余亮切","vol":"11","py":"yànɡ","duan":[{"e":"漾水。出隴西豲道。東至武都爲漢。","n":"豲、各本作柏。字之誤也。今依水經注所引說文正。前志豲道屬天水。後志屬漢陽。漢陽卽天水也。豲道不屬隴西。當作氐道。乃典漢志合。水經注漾水篇曰。許愼、吕忱、闞駰竝言漾水出隴西豲道。東至武都爲漢水。不言氐道。然豲道在冀之西北。又隔諸川。無水南入。疑出豲道之爲謬矣。按禹貢曰。嶓冢道漾。東流爲漢。又東爲滄浪之水。前志隴西郡氐道下曰。禹貢養水所出。至武都爲漢。武都郡武都下曰。東漢水受氐道水。一名沔。過江夏謂之夏水。二條相屬爲辭。隴西郡西下又曰。禹貢嶓冢山、西漢所出。南入廣漢白水。東南至江州入江。鄭注尙書道漾引地理志漾水出隴西氐道。至武都爲漢。至江夏謂之夏水。注梁州沱潛云潛葢西漢。出嶓冢。東南至巴郡江州入江"}]},"漢":{"expl":"漾也。東爲滄浪水。从水，難省聲。","rad":"水","fq":"呼旰切","vol":"11","py":"hàn","duan":[{"e":"漾也。","n":"尙書某氏傳曰。泉始出山爲漾。按漾言其微、漢言其盛也。蕭何曰。語曰天漢。其名甚美。"}]},"浪":{"expl":"滄浪水也。南入江。从水良聲。","rad":"水","fq":"來宕切","vol":"11","py":"lànɡ","duan":[{"e":"滄浪水也。","n":"按據此解可證前後某篆下皆當云某水也。淺人𠜂之。存一水字。非是。"}]},"沔":{"expl":"水。出武都沮縣東狼谷，東南入江。或曰入夏水。从水丏聲。","rad":"水","fq":"彌兖切","vol":"11","py":"miǎn","duan":[{"e":"沔水。出武都沮縣東狼谷。東南入江。","n":"武都沮縣、二志同。今陝西漢中府略陽縣是其地。有沮水出焉。前志沮縣下曰。沮水出東狼谷。後志沮縣下曰。沔水出東狼谷。水經曰。沔水出武都沮縣東狼谷中。酈注曰。沔水一名沮水。引闞駰云以其初出沮洳然。故曰沮水。是則前志之沮水。水經、說文之沔水。皆云出沮縣東狼谷。實一水也。前志曰。南至沙羨南入江。過郡五。行四千里。過郡五者、武都漢中南陽南郡江夏也。水經亦歷敘沔水所過之縣。而曰又南至江夏沙羨縣南入於江。許說沔與漢志、水經同。此漢時漢水之道與禹貢時其源不同。其委則一。常璩云。始源曰沔。玉裁謂漢言其盛。沮與沔皆言其微。沔者、發源緬然之謂尙書周官、春秋傳曰漢。漢時曰沮水、曰沔水。是爲古今異名。水經且謂西漢水曰漢水"}]},"湟":{"expl":"水。出金城臨羌塞外，東入河。从水皇聲。","rad":"水","fq":"乎光切","vol":"11","py":"huánɡ","duan":[{"e":"湟水。出金城臨羌塞外。東入河。","n":"金城郡臨羌、二志同。舊西寧衞西二百八十里有故臨羌城。前志臨羌下曰。西北至塞外有西王母石室、僊海、鹽池。北則湟水所出。東至允吾入河。允吾下曰。逆水、出參街谷。東至枝陽入湟。浩亹下曰。浩亹水、出西塞外。東至允吾入湟。按水經河水、又東過金城允吾縣北。注言湟水、浩亹水、逆水源流皆甚詳。水道提綱曰。靑海在今西寧府邊西五百餘里。古名西海。卽鮮水也。今爲厄魯特等二十三旗地。靑海東卽湟水。古所謂湟中地。北卽大通河。古所謂浩亹水東南會湟水入黃河也。湟水卽洛都水。源出今西寧府西北邊外。至今蘭州西境入黃河。按允吾音鉛牙。今甘肅蘭州府府西北三百里有故鉛吾城是也。浩亹音閤門。僊海卽西海。古音西讀如仙。"}]},"汧":{"expl":"水。出扶風汧縣西北，入渭。从水幵聲。","rad":"水","fq":"苦堅切","vol":"11","py":"qiān","duan":[{"e":"汧水。出右扶風汧縣西北。","n":"句。"}]},"澇":{"expl":"水。出扶風鄠，北入渭。从水勞聲。","rad":"水","fq":"魯刀切","vol":"11","py":"láo","duan":[{"e":"澇水。出右扶風鄠。北入渭。","n":"右扶風鄠、見邑部。上林賦曰。終始灞滻。出入涇渭。酆鎬潦潏。紆餘委蛇。經營乎其內。蕩蕩乎八川。分流相背而異態。潘岳關中記曰。涇、渭、灞、滻、酆、鎬、潦、潏、所謂八川。李善曰。潦卽澇水也。水經曰。渭水、又東過槐里縣南。又東、澇水從南來注之。今陝西西安府鄠縣縣西三里、澇水出南山澇谷。北流經故萯陽宫。西入長安縣畍。入渭。故曰北入渭。水道提綱曰。渭水東經鄠縣北境、咸陽縣城東南。又東北有豐水自西來。合諸水北流注之。諸水者、澇水、滈水、潏水。"}]},"漆":{"expl":"水。出右扶風杜陵岐山，東入渭。一曰入洛。从水桼聲。","rad":"水","fq":"親吉切","vol":"11","py":"qī","duan":[{"e":"漆水。出右扶風杜陵岐山。東入渭。","n":"二志皆杜陵屬京兆尹、杜陽屬右扶風。此杜陵當作杜陽。杜陽、今陝西鳳翔府麟遊縣是其地。周公劉居豳、今陝西邠州是其地。漢之漆。栒邑二縣也。太王遷𨙸、今鳳翔府岐山夫風二縣是其地。漢之杜陽南、美陽北也。大雅曰。民之初生。自土漆沮。傳曰。漆、漆水。沮、沮水也。又曰。周原、漆沮之閒也。周頌潛傳又曰。漆沮、岐州之二水也。據毛說則漆沮二水、實在岐周之地。小雅吉日傳但云漆沮之水。麀鹿所生。其解必同大雅、周頌。許云漆水出杜陽。正岐周地也。此漆沮在涇西。禹貢道渭又東過漆沮、則在涇東。與岐周無涉。玉裁謂水經曰。漆水出扶風杜陽縣俞山。東北入於渭。正與說文合。惟岐作俞耳。酈氏引開山圖曰。岐山在杜陽北、長安西。有渠謂之漆渠。"}]},"蓐":{"expl":"陳艸復生也。从艸辱聲。一曰蔟也。凡蓐之屬皆从蓐。","rad":"蓐","fq":"而蜀切","vol":"01","py":"rù","duan":[{"e":"陳艸復生也。从艸。辱聲。","n":"而蜀切。三部。"}]},"滻":{"expl":"水。出京兆藍田谷，入霸。从水產聲。","rad":"水","fq":"所簡切","vol":"11","py":"chǎn","duan":[{"e":"滻水。出京兆藍田谷。入霸。","n":"霸宋本、汲古閣初印皆同。霸灞古今正俗字。許書無灞。史、漢皆作霸水。京兆尹藍田、二志同。故城在今陝西西安府藍田縣縣治西十一里。前志京兆尹南陵下曰。文帝七年置。沂水出藍田谷。北至霸陵入霸水。霸水亦出藍田谷。北入渭。師古曰。沂音先歷反。按此乃大謬。沂者、滻字之誤。水經注引志可證。張揖注上林賦亦曰。霸出藍田西北而入渭。滻亦出藍田谷。北至霸陵入霸。水經曰。渭水、又東過長安縣北、又東過霸陵縣北。霸水從縣西北流注之。注云。霸者、水上地名也。古曰滋水。秦穆公霸世。更名滋水爲霸水。以顯霸功。水出藍田縣藍田谷。逕藍田縣東。又左合滻水。又北、辰水注之。又北、會兩川。又北、左納漕渠。又東、逕新豐縣。右會故渠。故渠卽經"}]},"洛":{"expl":"水。出左馮翊歸德北夷界中，東南入渭。从水各聲。","rad":"水","fq":"盧各切","vol":"11","py":"luò","duan":[{"e":"洛水。出左馮翊歸德北夷畍中。東南入渭。","n":"左馮翊三字、當作北地二字。前志北地郡歸德下。洛水出北蠻夷中。入河。入河者、入渭以入河也。此揔舉其源委也。左馮翊褱德下曰。洛水東南入渭。此言其入渭之處也。許之例。舉源地、不舉委地。然則當云出北地歸德無疑矣。今甘肅慶陽府安化合水二縣、漢歸德地也。今陝西同州府朝邑縣有懷德城、漢縣也。括地志云。洛水源出慶州洛源縣白於山。方輿紀要曰。洛水出慶陽府合水縣北二十里白於山。東北流經廢洛源縣。又經保安縣、安塞縣、甘泉縣、鄜州。又南經洛川縣南、中部縣東、而沮水入焉。沮水自中部縣子午嶺東南流而入於洛水。卽說文𣻐水、出北地直路西、東入洛也。自是洛水亦兼沮水之稱。又南流經宜君縣。過耀州。合漆水。歷三原縣、富平縣、白水縣"}]},"淯":{"expl":"水。出弘農盧氏山，東南入海。从水育聲。或曰出酈山西。","rad":"水","fq":"余六切","vol":"11","py":"yù","duan":[{"e":"淯水。出弘農盧氏山。東南入沔。","n":"弘農郡盧氏、二志同。今河南河南府盧氏縣是其地。前志盧氏下曰。有育水。南至順陽入沔。順陽者、南陽之博山也。中山經曰。攻離之山。淯水出焉。南流注于漢。（依文𨕖注）水經曰。淯水、出弘農盧氏縣攻離山。東南過南陽西、鄂縣西北。又東過宛縣南。又屈南過淯陽縣東。又南過新野縣西。又南過鄧縣東南。入於沔。今河南南陽府府城東三里俗名白河者是。由南陽達於新野、府境諸水悉會焉。又南至湖廣光化縣。又東經故鄧城東南而入漢水。水道提綱云。漢水經襄陽府城北。樊城南。有白河唐河。東北自河南新野合南陽府諸縣及鄧州水南流。又合西來之淸河。東來棗陽之滚河來會。齊氏所謂白河、卽淯水也。南陽之水淯冣大。水經注云。合魯陽關水、洱水、梅谿水"}]},"汝":{"expl":"水。出弘農盧氏還歸山，東入淮。从水女聲。","rad":"水","fq":"人渚切","vol":"11","py":"rǔ","duan":[{"e":"汝水。出弘農盧氏還歸山。東入淮。","n":"弘農盧氏見上。前志汝南郡定陵下曰。高陵山、汝水出東南。至新蔡入淮。過郡四。行千三百四十里。水經曰。汝水、出河南梁縣勉鄉天息山。酈云。地理志日出高陵山。卽猛山也。亦言出南陽魯陽縣之大盂山。又言出弘農盧氏縣還歸山。博物志曰。汝出燕泉山。竝異名也。余以永平中除魯陽太守。旣在遘見。不容不述。今汝水出魯陽縣之大盂山蒙柏谷西。卽盧氏畍也。其水東北流。逕太和城西、城北。又東屆堯山西嶺下。水流兩分。一東逕堯山南爲滍水。一東北出爲汝水。東流至原鹿縣。入於淮。所謂汝口。據酈說得諸親見。大盂山之西卽慮氏畍。此許云出慮氏還歸山所由也。凡言水源者、或數源竝合而偏舉其一。或遠源罕見而劣舉其近。是以每多乖異。前志云出定陵。"}]},"潩":{"expl":"水。出河南密縣大隗山，南入潁。从水異聲。","rad":"水","fq":"与職切","vol":"11","py":"yì","duan":[{"e":"潩水。出河南密縣大隗山。南入潁。","n":"河南郡密、二志同。今河南開封府密縣縣東南三十里有故密城。大騩山卽具茨山。在今河南開封府新鄭縣縣西南四十里。葢山與密接畍。前志密下曰。有大騩山。潩水所出。南至臨潁入潁。水經曰。潩水、出河南密縣大騩山。東南入於潁。今潩水自新鄭大騩山南流。經許州長葛縣流入許州北二里。又南經許州臨潁縣而合於潁。一名魯固河。又名淸流河是也。"}]},"汾":{"expl":"水。出太原晉陽山，西南入河。从水分聲。或曰出汾陽北山，冀州浸。","rad":"水","fq":"符分切","vol":"11","py":"fén","duan":[{"e":"汾水。出大原晉陽山。西南入河。","n":"太原郡晉陽、二志同。今山西太原府太原縣縣治東北有太原舊城。城中舊有三城。一曰大明城。古晉陽城也。左傳有六名。曰大夏、曰大原、曰大鹵、曰夏墟、曰晉陽、曰鄂。其實一也。周禮河內曰冀州。其浸汾、潞。左傳曰新田有汾澮以流其惡。又曰宣汾洮。前志曰。大原郡晉陽。晉水所出。東入汾。汾陽。汾水所出。西南至汾陰入河。水經曰。汾水、出大原汾陽縣北管涔山。至汾陰縣北。西注於河。按許云出晉陽山與志水經不合者、志水經舉其遠源。許舉其近源也。汾出管涔山。東南過晉陽縣東。晉水從縣南東流注之。許意謂晉水卽汾水之源。所謂晉陽山者、葢卽縣甕山。在今太原縣西南十里。晉水所出也。杜注左傳曰。汾水出太原。與許合。今汾水出靜樂縣管涔山。"}]},"澮":{"expl":"水。出靃山，西南入汾。从水會聲。","rad":"水","fq":"古外切","vol":"11","py":"ɡuì","duan":[{"e":"澮水。出河東彘靃山。西南入汾。","n":"河東彘三字、鉉奪。鍇本誤作河西二字。今正。前志。河東郡彘。後志曰。永安、故彘。前志彘下曰。霍大山、在東。冀州山。今山西霍州州東南霍山、禹貢之大岳也。水經曰。澮水、出河東絳縣東澮交東、高山。西至王澤。注於汾水。不言出霍山者、水經舉其近源。許舉其遠源也。水道提綱曰。澮河、源出翼城縣東南山。西流經中衞鎭。又西稍北至城南。又西經曲沃縣南。又西至絳州城南入汾。方輿紀要。翼城縣有澮高山。有澮水入曲沃縣畍。至絳州南入汾。"}]},"沁":{"expl":"水。出上黨羊頭山，東南入河。从水心聲。","rad":"水","fq":"七鴆切","vol":"11","py":"qìn","duan":[{"e":"沁水。出上黨穀遠羊頭山。東南入河。","n":"上黨郡穀遠、二志同。今山西沁洲沁源縣縣城南故穀遠城、漢縣也。前志穀遠下曰。羊頭山世靡谷。沁水所出。東南至熒陽入河。過郡三。行九百七十里。三郡、上黨河內河南也。水經曰。沁水出上黨涅縣謁戾山。南過穀遠縣東。至熒陽縣北。東入於河。按水經及注皆云至熒陽入河。師古據唐時在懷州武陟入河。疑轉寫錯誤。非也。古水道與唐時不同耳。山海經水經舉涅謁戾山、班許舉穀遠羊頭山者、羊頭卽謁戾也。戴先生曰。山在今武鄉縣西百二十里。西北接祁縣平遙縣。西南接沁源縣。一名麓臺山。迆邐而西爲綿山。其北爲介休縣。西爲靈石縣。皆謁戾山也。今沁水出沁州沁源縣西北百里之綿山東谷。西南流經平陽府岳陽縣東。又折而東南經澤州府沁水縣東。又南經陽"}]},"沾":{"expl":"水。出壺關，東入淇。一曰沾，益也。从水占聲。","rad":"水","fq":"他兼切","vol":"11","py":"zhān","duan":[{"e":"沾水。出上黨壺關。東入淇。","n":"上黨壺關、二志同。今山西潞安府附郭長治縣府治、卽漢壺關地。前志壺關下曰。有羊腸坂。沾水東至朝歌入淇。水經注淇水篇曰。淇水、出沮洳山。衝激橫山。又東北、沾水注之。水出壺關縣東沾臺下。東流注淇水。今山西潞安府壺關縣東南有沾水是。"}]},"潞":{"expl":"冀州浸也。上黨有潞縣。从水路聲。","rad":"水","fq":"洛故切","vol":"11","py":"lù","duan":[{"e":"冀州浸也。","n":"周禮職方氏曰。冀州、其浸汾、潞。鄭云。潞出歸德。此謂潞卽洛耳。按班、許皆云洛出。歸德北夷畍中。漢歸德在今甘肅慶陽府境。洛水在今陝西同州府境入河。非冀州地也。且雍州旣曰其浸洛矣。安得又爲冀浸。鄭注於雍州云。洛出懷德。冀州云潞出歸德。葢由株守地理志而未思志歸德下言其源、懷德下言其委。一水兩言。不當改洛爲潞。以屬冀州。自雍入冀。古無此水以當之。許但云冀州浸。不言何出何入。不欲強爲之說。葢此浸自周初迄漢。湮𣳚不彰。古今變遷。大類如斯。如大河故瀆。泲水枯絕。沔水不出嶓冢。皆無可疑者。班、許皆不言潞之源流。此可以正鄭注矣。闞駰曰。潞縣有潞水、爲冀州浸。卽漳水也。善長亦謂無他大川可以爲浸。惟漳水耳。此非許意"}]},"薅":{"expl":"拔去田艸也。从蓐，好省聲。","rad":"蓐","fq":"呼毛切","vol":"01","py":"hāo","duan":[{"e":"披田艸也。","n":"大徐作拔去田艸。衆經音義作除田艸。經典釋文、王篇、五經文字作拔田艸。惟繫傳舊本作披、不誤。披者、迫地削去之也。木部曰。槈、薅器也。"}]},"漳":{"expl":"濁漳，出上黨長子鹿谷山，東入清漳。清漳，出沾山大要谷，北入河。南漳，出南郡臨沮。从水章聲。","rad":"水","fq":"諸良切","vol":"11","py":"zhānɡ","duan":[{"e":"水名。从水。章聲。","n":"韵會所據鍇本如此。諸良切。十部。水名二字、古本當作漳水也三字。"}]},"淇":{"expl":"水。出河内共北山，東入河。或曰出隆慮西山。从水其聲。","rad":"水","fq":"渠之切","vol":"11","py":"qí","duan":[{"e":"淇水。出河內𠔏北山。東入河。","n":"韵會引作東至黎陽入河。此用漢書增三字也。說文之例。舉所出之郡縣。不舉入河入江之郡縣。所出之地不變者多。下流古今多變。故略之也。河內郡𠔏、二志同。𠔏音恭。今河南衞輝府輝縣治、古𠔏城也。前志𠔏下曰。北山、淇水所出。東至黎陽入河。北山、今輝縣西北蘇門山。其別阜曰𠔏山是也。詩曰。毖彼泉水。亦流於淇。又曰。泉源在左。淇水在右。泉謂淇之源也。今淇水自彰德府林縣流入衞輝府淇縣境、入衞河而入海。與古入河者迥異。"}]},"𣿴":{"expl":"水。出河内蕩陰，東入黃澤。从水𦳝聲。","rad":"水","fq":"徒朗切","vol":"11","py":"dànɡ","duan":[{"e":"𣿴水。出河內𣿴陰。東入黃澤。","n":"河內郡𣿴陰、二志同。𣿴音湯。古音也。後人省艸。古有羑里城、西伯所拘也。今河南彰德府湯陰縣西南有故𣿴陰城。前志𣿴陰下曰。𣿴水、東至內黃入黃澤。今本奪入黃二字。水經曰。𣿴水、出河內𣿴陰縣西山東。東北至內黃縣。入於黃澤。注云。𣿴水合羑水、長沙溝。逕內黃城南。東注白溝。按內黃黃澤在今直𥻳內黃縣。水道提綱曰。衞河經湯陰縣東畍。湯河出湯陰縣西山中。東流經縣城北。東入衞河。則與古水道大異。"}]},"沇":{"expl":"水。出河東東垣王屋山，東爲泲。从水允聲。","rad":"水","fq":"以轉切","vol":"11","py":"yǎn","duan":[{"e":"沇水。出河東垣東王屋山。","n":"謂垣縣東之王屋山。水經云垣縣東王屋山是也。"}]},"泲":{"expl":"沇也。東入于海。从水𠂔聲。","rad":"水","fq":"子礼切","vol":"11","py":"jǐ","duan":[{"e":"沇也。東入于海。","n":"按沇泲二篆之解、文體與漾漢浪三篆同。皆用禹貢文也。禹貢曰。道沇水東流爲濟。入于河。泆爲熒。東出於陶丘北。又東至于菏。又東北會于汶。又北東人于海。今泲水不特入河以後經文所謂不可致詳。考郡國志曰。河東垣有王屋山。兖水出。河內溫。濟水所出。王莽時大旱。遂枯絕。水經注曰。濟水故瀆在溫。當王莽之世。川瀆枯竭。其後水流徑通。津渠勢改。尋梁脈水。不與昔同。是在西漢已後所謂東流爲濟入于河者、已非禹蹟之舊矣。許云東入于海。此謂禹時故道。獨行達海。故謂之瀆。今之大淸河、小淸河非泲水在其閒。而混淆莫辨。漢水之源、今與經絕殊。泲水之流、軼出地中而爲巨川。今又與經絕殊也。"}]},"洈":{"expl":"水。出南郡高城洈山，東入繇。从水危聲。","rad":"水","fq":"過委切","vol":"11","py":"wéi","duan":[{"e":"洈水。出南郡高城洈山。東入繇。","n":"城前志作成。水經注作城。南郡高成下曰。洈山、洈水所出。東入繇。繇水南至華容入江。過郡二。行五百里。水經江水篇曰。又東南當華容縣南。濔水入焉。又東南油水從西南來注之。油水篇曰。油水出武陵孱陵縣西畍。東過其縣北。又東北入於江。油水卽說文下文之油水。非漢志之繇水也。漢志洈入繇。繇入江。此在江北、而南入。南郡高城、華容在江北也。油水入江在江南、而北入。孱陵在江南也。然則繇、油同音而絶不相涉。酈注油水篇乃云孱陵縣白石山、油水所出。東逕其縣西與洈水合。洈出高城縣洈山。東逕其縣下。東至孱陵縣入油水。殊爲襲志語而謬誤。葢江北之洈水、繇水不可攷。乃以江南之油水當之也。山海經曰。宜諸之山、洈水出焉。南流注於漳。"}]},"溠":{"expl":"水。在漢南。从水差聲。荆州浸也。《春秋傳》曰：“脩涂梁溠。”","rad":"水","fq":"側駕切","vol":"11","py":"zhā","duan":[{"e":"溠水。在漢南。","n":"職方氏曰。豫州、其浸波、溠。注云。春秋傳曰。楚子除道梁溠。營軍臨。隨則溠宜屬荆州。在此非也。按傳文見莊四年。職方荆州浸潁、湛。豫州浸波、溠。許書於湛曰浸。於溠曰荆浸。葢正經文之誤。與鄭說溠正同也。杜預曰。溠水在義。陽厥縣西。東南入鄖水。釋例曰。厥縣西有漈水。源出縣北。從縣西、南至隨縣。入鄖水。水經注曰。溠水、出隨縣西北黃山。南逕㵐西縣西。又東南、㵐水入焉。又東南逕隨縣故城西。又南流、注於溳。溳入夏水。方輿紀要曰。今溠水出德安府隨州西北二百里之栲栳山。東南流。至州北百十里。有魯城河流合焉。至安貢鎭入溳。水道提要曰。漢水至漢川縣溳口塘北。有溠溳諸水、北自隨州南流。會德安府雲夢應城縣水來注之。源流長"}]},"洭":{"expl":"水。出桂陽縣盧聚，山洭浦關爲桂水。从水匡聲。","rad":"水","fq":"去王切","vol":"11","py":"kuānɡ","duan":[{"e":"洭水。出桂陽縣盧聚。南出洭浦關爲桂水。","n":"縣字依韵會補。此水出桂陽郡桂陽縣。郡縣同名。故曰桂陽縣。如邑部鄏下云河南縣之例。南出二字、各本作山字。今依水經正。桂陽郡桂陽、二志同。今廣東廣州府連州州治、卽漢縣地也。前志桂陽下曰。洭水南至四會入鬱。過郡二。行九百里。二郡、桂陽南海也。水經曰。洭水、出桂陽縣盧聚。東南過含洭縣南。出洭浦關爲桂水。按前志南海中宿縣有洭浦關。酈注亦云尒。今志文關作官。桂陽下洭作匯。皆譌字也。今洭水出連山縣。東南流。經連州、英德縣、淸遠縣。合湞水。經三水縣至廣州府城西。入西江以入海。班所謂入鬱。今廣東之北江也。其出洭浦關、在今淸遠縣。酈氏曰。桂水者、洭之別名也。"}]},"潓":{"expl":"水。出廬江，入淮。从水惠聲。","rad":"水","fq":"胡計切","vol":"11","py":"huì","duan":[{"e":"潓水。出盧江。入淮。","n":"出疑當作在。漢盧江郡、今安徽盧州府南至安慶府之境是其地。潓水未詳。"}]},"灌":{"expl":"水。出廬江雩婁，北入淮。从水雚聲。","rad":"水","fq":"古玩切","vol":"11","py":"ɡuàn","duan":[{"e":"灌水。出盧江雩婁。北入淮。","n":"盧江郡雩婁、二志同。前志雩婁下曰。決水、北至蓼入淮。灌水、亦北至蓼入決。過郡二。行五百一十里。過郡二者、盧江六安國也。水經注。決水自安豐縣故城西北逕蓼縣故城東。又西北、灌水注之。水導源盧江金蘭縣西北東陵鄉大蘇山。東北逕蓼縣故城西而注決水。決水、又北入於淮。按前志盧江郡下云。金蘭西北有東陵鄉。淮水出。依酈注、則金蘭者縣名。而志無此縣。志云淮水出、乃灌水出之誤。葢出金蘭東陵鄉逕雩婁至蓼入決也。酈云。灌水俗謂之澮水。又云。決水北入於淮。俗謂之澮口。葢灌澮聲相倫。習俗害眞尒。酈時已與古名全違。今則更難詳矣。方輿紀要曰。雩婁、今安徽潁州府霍丘縣西南八十里有雩婁故城。左傳襄卄六年。楚人侵吳及雩婁。昭五年。"}]},"帝":{"expl":"諦也。王天下之號也。从丄朿聲。","rad":"丄","fq":"都計切","vol":"01","py":"dì","duan":[{"e":"諦也。","n":"見春秋元命苞、春秋運斗樞。毛詩故訓傳曰。審諦如帝。"}]},"祘":{"expl":"明視以筭之。从二示。《逸周書》曰：“士分民之祘。均分以祘之也。”读若筭。","rad":"示","fq":"蘇貫切","vol":"01","py":"suàn","duan":[{"e":"明視㠯筭之。从二示。","n":"示與視、筭與祘皆曡韵也。明視故从二示。"}]},"茻":{"expl":"眾艸也。从四屮。凡茻之屬皆从茻。讀與冈同。","rad":"茻","fq":"模朗切","vol":"01","py":"mǎnɡ","duan":[{"e":"眾艸也。","n":"按經傳艸莽字當用此。"}]},"漸":{"expl":"水。出丹陽黟南蠻中，東入海。从水斬聲。","rad":"水","fq":"慈冉切","vol":"11","py":"jiàn","duan":[{"e":"漸水。出丹陽黟南蠻中。東入海。","n":"丹陽郡黟、二志同。今安徽徽州府黟縣是其地。云漸水出黟南之蠻夷中、則今錢塘江之北源南源皆見矣。前志黟下曰。漸江水出南蠻夷中。東入海。水經曰。漸江水、出三天子都。北過餘杭。東入於海。按班、許、水經皆曰漸江水。酈氏注則曰浙江。葢水經以後無稱漸江者。其前則山海經、吳越春秋、史記皆曰浙江。山海經有出於漢人者。漢人之書地理志、說文爲謹嚴。據許立文。曰江至會𥠻山陰爲浙江、謂崏江也。曰漸江水出丹陽黟南蠻中、謂今錢唐東也。分別畫然。葢浙江者、崏江之委。漸江者、錢唐江源流之緫稱。二水古於山陰相合。故河統名之曰浙江。後世水道絕不相通。而錢唐江猶冒浙江之名。失其本號耳。水道提綱曰。浙水有南北二源。北曰徽港。卽新安江。"}]},"泠":{"expl":"水。出丹陽宛陵，西北入江。从水令聲。","rad":"水","fq":"郎丁切","vol":"11","py":"línɡ","duan":[{"e":"泠水。出丹陽宛陵。西北入江。","n":"丹陽郡宛陵、二志同。今安徽寧國府附郭宣城縣、漢故縣也。前志宛陵下曰。淸水、西北至蕪湖入江。按許之泠水、卽班之淸水。慶劭零陵泠道下注引說文此條。則應氏未知淸、泠異名同實也。泠水卽今宣城縣西六十里之靑弋江。元和郡縣志。靑弋水在宣州西九十九里。水道提綱曰。江水又東北爲蕪湖縣西北之魯港口。魯明江南匯旌德、太平、石埭、涇縣諸水。東北流。經宣城西北境曰靑弋江。折而西北流。經蕪湖城南而西北注之。是爲魯港口。此水三源。東南源出旌德南。南源出太平南。西南源出石埭西北。"}]},"㵺":{"expl":"水。在丹陽。从水箄聲。","rad":"水","fq":"匹卦切","vol":"11","py":"pài","duan":[{"e":"㵺水。在丹陽。","n":"未聞。"}]},"溧":{"expl":"水。出丹陽溧陽縣。从水栗聲。","rad":"水","fq":"力質切","vol":"11","py":"lì","duan":[{"e":"溧水。出丹陽溧陽縣。","n":"縣字俗所沾。丹陽郡溧陽、二志同。據舊志、漢縣葢在今江蘇江甯府高淳縣南十五里之固城。前志溧陽下應劭曰。溧水所出南湖也。方輿紀要曰。今溧水在今溧陽縣北四十里、卽永陽江也。祥符圖經。溧水承丹陽湖。東入長蕩湖。丹陽湖卽應劭之南湖也。張𨮯曰。溧水卽永陽江之上源。大江之水南會於此。江上有渚曰瀨渚。又謂之陵水。范雎說秦昭王、子胥出昭關至陵水是也。自瀨渚東流爲瀨溪。鄉民誤曰爛溪。入長蕩湖。又分流東行。爲吳王漕。葢五代時楊行密漕運所經也。自東壩築、而丹陽湖之水不復入於溧水。永陽江之源流亦滋晦矣。水利攷。永陽江一名穎陽江。古名中江。按中江者、前志丹陽郡蕪湖下云中江出西南。東至陽羨入海。楊州川。謂禹貢、職方三江之一"}]},"湘":{"expl":"水。出零陵陽海山，北入江。从水相聲。","rad":"水","fq":"息良切","vol":"11","py":"xiānɡ","duan":[{"e":"湘水。出零陵縣陽海山。北入江。","n":"縣字今補。凡郡縣同名、則言縣以該之也。零陵郡零陵、二志同。前志零陵下曰。陽海山、湘水所出。北至酃入江。過郡二。行二千五百三十里。過郡二者、零陵長沙也。又有離水。東南至廣信入鬱。（下衍林字非）行九百八十里。水經曰。湘水、出零陵始安縣陽海山。東北流過下雋縣西。又北至巴丘山。入於江。酈曰。陽海山卽陽朔山。山在始安縣北。縣故零陵之南部也。湘灕同源。南爲灕水。北則湘川。今廣西桂林府與安縣南九十里。俗謂之海陽山、卽陽海山也。湘水出焉。北流經全州入湖南畍。經東安縣、零陵縣、祁陽縣、常寧縣、衡陽縣、衡山縣、湘潭縣、善化縣。至喬口。資水來會。又經湘陰縣。至磊石山分爲二派。又合入洞庭湖曰湘口。漢志云至酃入江。未詳"}]},"汨":{"expl":"長沙汨羅淵，屈原所沈之水。从水，冥省聲。","rad":"水","fq":"莫狄切","vol":"11","py":"mì","duan":[{"e":"長沙汨羅淵也。","n":"長沙下葢奪羅字。許例郡縣兼書。前志長沙國羅。後志長沙郡羅。應劭曰。楚文王徙羅子自枝江居此。今湖南長沙府湘陰縣縣東北六十里有羅縣城是也。岳州府平江縣縣南三十里亦有羅城、云古羅子國也。水經注湘水篇曰。湘水、又北。汨水注之。汨水、出豫章艾縣桓山。西南逕吳昌縣北。又西逕羅縣北。謂之羅水。又西逕玉笥山。又西爲屈潭。卽汨羅淵也。屈原懷沙自沈於此。又西逕汨羅戍南。西南注於湘。春秋之羅汭、世謂之汨羅口。按今湘陰縣北七十里汨羅江是也。"}]},"溱":{"expl":"水。出桂陽臨武，入匯。从水秦聲。","rad":"水","fq":"側詵切","vol":"11","py":"zhēn","duan":[{"e":"溱水。出桂陽臨武。入洭。","n":"洭各本作匯。今正。桂陽郡臨武、二志同。今湖南桂陽州臨武縣縣五十里臨武故城是也。前志臨武下曰。秦水東南至湞陽入洭。行七百里。水經曰。溱水、出桂陽臨武縣南。繞城西北屈、東流。東到曲江縣安聶縣邑。東屈、西南流。過湞陽縣。出洭浦關與桂水合。東入於海。志之秦水、卽溱水也。經之出洭浦關與桂水合、桂水卽洭水。許云洭水出洭浦關爲桂水是也。班、許皆云溱入洭。酈注則云洭入溱。酈葢本山海經。經曰。肄水出臨武（武作晉誤）西南。而東南注海。入畨禺西。湟水出桂陽西北山。東而注肄水。入郭浦西。酈曰肄水、葢溱水之別名也。今人謂湞水出南雄保昌縣西南。經始興縣曲江縣、英德縣。而翁江洭水入之。此正漢志、水經、說文之溱水。乃誤謂之湞"}]},"深":{"expl":"水。出桂陽南平，西入營道。从水罙聲。","rad":"水","fq":"式針切","vol":"11","py":"shēn","duan":[{"e":"深水。出桂陽南平。西入營道。","n":"桂陽郡南平、零陵郡營道、二志同。今湖南桂陽州藍山縣縣東五里有南平城。水經曰。深水出桂陽盧聚。西北過零陵營道縣、營浦縣、泉陵縣。至燕室。邪入於湘。酈云。桂陽縣本𥻳桂陽郡。後割屬始興縣。有盧溪。盧聚山在南平縣之南、九疑山之東。玉裁謂盧聚山在南平之南。經舉其遠源。許舉其近源。洭出慮聚。南流入海。深出盧聚。西北流入湘、以入江。是分馳不同也。湘水篇經、注皆不言深水。葢吕忱言深水導源盧溪。西入營水。亂流營波。同注湘津。故湘水篇言營不言深耳。今深營二水源委未聞。漢營道、營浦縣皆氏於水。以字林訂說文、則當作入營。不必有道字。泉陵縣卽今湖南永州府零陵縣。今瀟水合諸水於此入湘。深水營水在其中也。"}]},"潭":{"expl":"水。出武陵鐔成玉山，東入鬱林。从水覃聲。","rad":"水","fq":"徒含切","vol":"11","py":"tán","duan":[{"e":"潭水。出武陵鐔成王山。東入鬱林。","n":"林字賸。當𠜂。俗人不知鬱爲水名。漢志洭水入鬱、離水入鬱、亦皆沾林矣。王、集韵引作玉。韵會引作五。漢志作玉。未審當何從。武陵郡鐔成、二志同。前志鐔成下曰。玉山、潭水所出。東至阿林入鬱。過郡二。行七百二十里。過郡二者、武陵鬱林也。今廣西潯州府阿林廢縣、漢縣也。鬱林郡廣鬱下曰。鬱水首受夜郎豚水。東至番禺郡四會入海。過郡四。行四千三十里。過郡四者、牂柯蒼梧鬱林南海也。潭水卽今福祿江。源出苗地。東南至今貴州黎平府西爲古州江。東至永從縣南。合彩江爲福祿江。入廣西畍。至桺城縣爲桺江。又東南經象州。至潯州府城北曰潯江。此爲廣西之右江。亦曰北江。合廣西左江。亦曰南江。卽所謂入鬱也。唐始置潯州。以北潯江爲名。潯江"}]},"油":{"expl":"水。出武陵孱陵西，東南入江。从水由聲。","rad":"水","fq":"以周切","vol":"11","py":"yóu","duan":[{"e":"油水。出武陵孱陵西。東南入江。","n":"武陵郡孱陵、二志同。今湖北荆州府公安縣縣西二十五里有孱陵故城是也。水經曰。油水、出武陵孱陵縣西畍。東過其縣北。又東北入於江。注云。逕公安縣、西北流、注於大江。然則許云東南入江。南當作北明矣。江水篇經云。江水、又東南、當華容縣。湧水入焉。又東南、油水從西南來注之。注云。右合油口油水。東有景口。景口東、有淪口。淪水南與景水合。又東通灃水及諸陂湖。按今荆州府虎渡口北。江之南岸有支津。南通公安諸湖水。古油水必在其閒。江表傳曰。劉備爲荆州牧。立營油口。五代梁開平四年。馬殷遣將侵荆南。軍於油口。今公安縣北。舊有油口巡司。是其水今雖湮𣳚。非無可考也。"}]},"莫":{"expl":"日且冥也。从日在茻中。","rad":"茻","fq":"莫故切","vol":"01","py":"mù","duan":[{"e":"日且冥也。","n":"且冥者、將冥也。木部曰。杳者、冥也。夕部曰。夕、莫也。引伸之義爲有無之無。"}]},"㵋":{"expl":"水。出豫章艾縣，西入湘。从水買聲。","rad":"水","fq":"莫蟹切","vol":"11","py":"mì","duan":[{"e":"㵋水。出豫章艾縣。","n":"凡縣字皆後人所增。古本必無也。"}]},"湞":{"expl":"水。出南海龍川，西入溱。从水貞聲。","rad":"水","fq":"陟盈切","vol":"11","py":"zhēn","duan":[{"e":"湞水。出南海龍川。西入溱。","n":"南海郡龍川、二志同。今廣東惠州府龍川縣是其地。應劭注漢書曰。湞水出南海龍川。西入秦。水經溱水注曰。溱水出峽、左側湞水注之。水出南海龍川縣。西逕湞陽縣南。右注溱水。故應劭曰。湞水西入秦。按此正今之翁江也。出韶州府翁源縣。西南流。至英德縣城東南。合溱水。今俗謂之合湞水。齊氏召南曰。此水源流三百餘里受巨溪甚多。漢書所謂下湞水。"}]},"澑":{"expl":"水。出鬱林郡。从水畱聲。","rad":"水","fq":"力救切","vol":"11","py":"liù","duan":[{"e":"澑水。出鬱林郡。","n":"不言縣者、有未審也。鬱林郡在今廣西。前志有中畱縣。師古曰。畱、力救反。水名。葢中畱、潭中皆以水得名也。後志及宋書州郡志作中澑。字從水。疑前志亦當從水。元和郡縣志曰。貞觀八年改南昆州爲桺州。因桺江爲名。桺州卽今桺州府。桺江出苗地。至今貴州古州永從縣生苗畍中。東南入廣西。至桺城縣曰桺江。至象州會於盤江。桺江卽古澑水。後世譌其字耳。"}]},"瀷":{"expl":"水。出河南密縣，東入潁。从水翼聲。","rad":"水","fq":"與職切","vol":"11","py":"yì","duan":[{"e":"瀷水。出河南密縣。東入潁。从水翼聲。","n":"與職切。一部。按此潩字之異體。後人收入。如㵋汨之實一字也。淮南書曰。澤受瀷而無源。許愼云。瀷、湊漏之流也。見文𨕖注。但造說文不收瀷字。"}]},"潕":{"expl":"水。出南陽舞陽，東入潁。从水無聲。","rad":"水","fq":"文甫切","vol":"11","py":"wǔ","duan":[{"e":"潕水。出南陽舞陰。東入潁。","n":"南陽郡舞陰、二志同。今河南南陽府泌陽縣縣北十里有舞陰故城。水經曰。潕水、出潕陰西北扶子山。東過其縣南。又東過西平縣北。又東過郾縣南。又東過定潁縣北。東入於汝。酈云。潕水過潕陰縣北。不出其南。又去郾縣遠。不得過。今水道提綱敘汝水、不言潕水源流。惟方輿紀要引舊志云。潕水、出泌陽縣北。自平地湧出。如飛舞然。東北流達舞陽縣東南爲三里河。又東入於汝。未知今水道然否。水經入汝。許云入潁。乖異俟攷。"}]},"滶":{"expl":"水。出南陽魯陽，入城父。从水敖聲。","rad":"水","fq":"五勞切","vol":"11","py":"áo","duan":[{"e":"滶水。出南陽魯陽。入父城。","n":"南陽郡魯陽、二志同。今河南汝州魯山縣有魯陽故城是。父城、大徐作城父。誤。潁川郡父城。二志同。今河南汝州郟縣西四十里有父城故城是也。城父縣、前志屬沛郡。後志屬汝南郡。今安徽潁州府毫州東南七十里有城父故城是也。左傳昭十九年。楚大城城父。大子建居之。哀十六年。大子建自城父奔宋。服注及吕覽愼行篇高注、闞駰十三州志、史記楚世家正義皆說此事作城父。杜注及酈氏汝水篇注、裴駰注五子胥傳、李吉甫元和郡縣志說此事皆作父城。未審何從。而此條滶入父城、與水經注所引合。則𣃔非城父也。汝水篇注曰。汝水又逕郟縣故城南。滶水注之。水出魯陽縣之將孤山。至父城、與出魯陽北山之桓水會。亂流東北至郟入汝。按今汝水由嵩縣天息山東經伊陽"}]},"瀙":{"expl":"水。出南陽舞陽中陽山，入潁。从水親聲。","rad":"水","fq":"七吝切","vol":"11","py":"qìn","duan":[{"e":"瀙水。出南陽舞陰中陽山入潁。","n":"舞陰二徐皆作舞陽。今正。前志舞陰下曰。中陰山、瀙水所出。東至蔡入汝。水經曰。瀙水、出潕陰縣東上畍山。東過吳房縣南。又東過灈陽縣南。又東過上蔡縣南。東入於汝。酈云。山海經謂之視水。郭注。視當爲瀙。出葴山、許愼云。出中陽山。皆山之殊目也。按志云中陰。許云中陽。乖異。雖酈注引作陽。然中陰二字正葴之反語。與中山經云出葴山者合。疑作陰是也。方輿紀要曰。瀙水自唐縣東北流。達舞陽縣南。又東南經泌陽縣東北。又東經泌陽之象河關。入汝寜府遂平縣境。未知今水道然否也。齊氏召南曰。汝水舊從舞陽縣北而南入西平畍。自元末於渦河堨𣃔其流。使東歸潁。於是西平雲莊、諸石二山之水。明時亦塞。今水道與古全異。卽名稱亦隨時不同。所謂"}]},"淮":{"expl":"水。出南陽平氏桐柏大復山，東南入海。从水隹聲。","rad":"水","fq":"戶乖切","vol":"11","py":"huái","duan":[{"e":"淮水。出南陽平氏桐柏大復山。東南入海。","n":"南陽郡平氏、二志同。今河南南陽府桐柏縣縣西北四十里有故平氏城。前志平氏下曰。禹貢桐柏大復山在東南。淮水所出。至淮陵入海。過郡四。行三千二百四十里。水經曰。淮水、出南陽平氏縣胎簪山。東北過桐柏山。東過江夏、盧江、九江、下邳諸郡。至廣陵淮浦縣入於海。按桐柏大復、以四字爲山名。漢志、說文、風俗通、酈注皆云桐柏大復山。應劭注地理志云。復陽縣在桐柏大復山之陽是也。後世地志析爲二山。乃非是。禹貢祇云桐柏、省言之也。古經史所舉之山皆舉其全勢。後人乃以一支一節當之。若水經所謂胎簪、亦卽桐柏耳。作水經者別爲二。亦非也。今淮水出河南桐柏縣桐柏山。東流經羅山縣、眞陽縣、息縣、固始縣、光州。又入江南畍。經潁州府、霍邱"}]},"滍":{"expl":"水。出南陽魯陽堯山，東北入汝。从水蚩聲。","rad":"水","fq":"直几切","vol":"11","py":"zhì","duan":[{"e":"滍水。出南陽魯陽堯山。東北入汝。","n":"南陽魯陽、見上。前志魯陽下曰。魯山、滍水所出。東北至定陵入女。水經曰。滍水、出南陽魯陽縣西之堯山。東北過潁川定陵縣西北。東入於汝。今沙河源出魯山縣西境之堯山。東經寶豐縣、葉縣、舞陽縣。汝水西北自襄城來會。俗曰沙河。卽古滍水也。左傳。僖三十三年。楚人與晉師夾泜水而軍。杜云。泜水出魯陽縣。東經襄城、定陵入汝。杜謂泜卽滍也。又襄十八年。楚伐鄭。涉於魚齒之下。杜、酈皆謂所涉卽滍水也。"}]},"澧":{"expl":"水。出南陽雉衡山，東入汝。从水豊聲。","rad":"水","fq":"盧啓切","vol":"11","py":"lǐ","duan":[{"e":"澧水。出南陽雉衡山。東入汝。","n":"南陽郡雉、二志同。雉音弋爾反。今河南南陽府治南陽縣府北八十里有故雉城、漢縣也。前志雉下曰。衡山、澧水所出。東至郾入汝。郾、顏本譌作𨜘云音屋。非也。水經注曰。汝水、又東南逕郾縣故城北。又東得醴水口。醴水、出南陽雉縣衡山。卽山海經中山經之衡山。馬融廣成頌曰。面據衡陰。在雉縣畍。故世謂之雉衡山。東南流逕葉縣故城北。又東注葉陂。又東逕郾縣故城南。左入汝。按馬融傳注引中山經。又東三十里曰雉山。澧水出焉。又東五十里曰宣山。又東四十五里曰衡山。然則分之爲雉衡二山。合之則單𧦝衡山。李賢曰。衡山在今鄧州向城縣北。杜佑曰。北重山在向城縣北。卽是三鵶之第一。又北分嶺山嶺北。卽三鵶之第二鵶也。其第三鵶入臨汝郡魯山縣畍"}]},"莽":{"expl":"南昌謂犬善逐菟艸中爲莽。从犬从茻，茻亦聲。","rad":"茻","fq":"謀朗切","vol":"01","py":"mǎnɡ","duan":[{"e":"南昌謂犬善逐兔艸中爲莽。从犬茻。","n":"此字犬在茻中。故偁南昌方言、說其㑹意之恉也。引伸爲鹵莽。"}]},"溳":{"expl":"水。出南陽蔡陽，東入夏水。从水員聲。","rad":"水","fq":"王分切","vol":"11","py":"yún","duan":[{"e":"溳水。出南陽蔡陽。東入夏水。","n":"南陽郡蔡陽、二志同。故城當在今湖北德安府隨州境內。夏水見上文沔字下。水經曰。溳水、出蔡陽縣。東南過隨縣西。又南過江夏安陸縣西。又東南入於夏。酈云。溳水、出縣東南大洪山。山在隨郡之西南。竟陵之東北。槃基所跨、廣員百餘里。今溳水出大洪山之陰。東南經隨州應山縣、安陸縣、雲夢縣、應城縣。至漢川縣溳口塘入漢。源流長五百里。入漢、卽古之入夏水也。今漢夏不分。"}]},"淠":{"expl":"水。出汝南弋陽垂山，東入淮。从水𢌿聲。","rad":"水","fq":"匹備切","vol":"11","py":"pèi","duan":[{"e":"淠水。出汝南弋陽垂山。東入淮。","n":"汝南郡弋陽、二志同。今河南光州州東北有故弋陽城。水經淮水篇曰。淮水、東過期思縣北。又東北淠水注之。水出弋陽南垂山。西北流、歷陰山關西北出山。又東北流逕新城戍東。又東北得詔虞水口。又東北注淮。俗曰白鷺水。按今之白露河也。出光州南三十里之南岳山。北流。又東入固始縣界。合春河注於淮。春河卽水經注之詔虞水也。水經注曰。沘水、字或作淠。但說文有淠無沘。前志有沘無淠。不得混爲一水。"}]},"澺":{"expl":"水。出汝南上蔡黑閭澗，入汝。从水意聲。","rad":"水","fq":"於力切","vol":"11","py":"yì","duan":[{"e":"𣽢水。出汝南上蔡黑閭㵎。入汝。","n":"汝南上蔡縣、二志同。今河南汝寧府上蔡縣縣西南十里故蔡城是。水經注汝水篇曰。汝水、又東南逕新蔡縣故城南。又東南左會澺水。水上承汝水。別流於奇雒城北爲黃陂。東流於上蔡岡東爲蔡塘。又東逕平輿縣故城南爲澺水。又東南左迆爲葛陂。又東出爲鮦水。俗謂之三丈陂。陂東注爲富水。澺水正流自葛陂東南逕新蔡縣故城東而東南流。注於汝。方輿紀要曰。澺水在汝寧府東四十里。俗名洪河。源出西平縣。水道提綱曰。南汝水至新蔡縣之東南。有洪河自西北來會。洪河出舞陽縣東南之筆尖山。經西平縣、上蔡縣、汝陽縣。至新蔡縣南入汝。大致東南流也。按於古水道不改。"}]},"𣳦":{"expl":"水。出汝南新郪，入潁。从水囟聲。","rad":"水","fq":"穌計切","vol":"11","py":"xì","duan":[{"e":"𣳦水。出汝南新郪。入潁。","n":"汝南郡新郪、見前志。後志曰。汝南郡、宋公國。周名郪丘。漢改爲新郪。章帝建初四年。徙宋公於此。今安徽潁州府治阜陽縣縣東八里有新郪城。水經注潁水篇曰。細水、上承陽都阪陂水。枝分東南出爲細水。東逕新陽縣故城北。又東南逕宋縣故城北。縣卽所謂郪丘者也。又南逕細陽縣。又東南逕細陽縣故城南。引地理志細水出細陽縣東南入潁。按今𣳦水不得其詳。"}]},"灈":{"expl":"水。出汝南吳房，入瀙。从水瞿聲。","rad":"水","fq":"其俱切","vol":"11","py":"qú","duan":[{"e":"灈水。出汝南吳房。入瀙。","n":"汝南郡吳房、二志同。孟康曰。本房子國。楚靈王遷房於楚吳王闔閭弟夫槩奔楚。封於此。爲棠谿氏。以封吳。故曰吳房。今吳房城棠谿亭是。按昭十三年杜注。房滅於楚。後平王遷之於荆山。今河南汝寧府遂平縣治、故吳房城也。水經曰。灈水、出汝南吳房縣西北奧山。東過其縣北入於汝。酈云。灈水東逕灈陽故城西。東流入瀙水。逕其縣南。又東入於汝。今遂平縣縣西七十里奧來山、葢水經之奧山也。方輿紀要曰。灈水在遂平縣南。東北流入汝。水道提綱曰。灈水今難確鑿𢫾證。"}]},"潁":{"expl":"水。出潁川陽城乾山，東入淮。从水頃聲。豫州浸。","rad":"水","fq":"余頃切","vol":"11","py":"yǐnɡ","duan":[{"e":"潁水。出潁川陽城乾山。東入淮。","n":"各本作乾山。韵會引作耿山。晉書音義引作陽城少室陽乾山。則兼用水經。漢志改說文也。爾雅音義引字林作陽城乾山。與今說文合。潁川以水名郡。字當從水。而漢碑郡名多從禾。葢漢時相習如此寫。如女陽、女陰、舞陽、舞陰以水名縣。而不作汝潕字也。恐漢志、說文古本郡名亦當從禾耳。潁川郡陽城、二志同。今河南河南府登封縣縣東南四十里有陽城廢縣。前志陽城下曰。陽乾山、潁水所出。東至下蔡入淮。過郡三。行千五百里。荆州浸。過郡三者、潁川淮陽沛郡也。水經曰。潁水、出潁川陽城縣西北少室山。東南至愼縣東南入於淮。水道提綱曰。今潁水源出登封縣北嵩山西南之少室山。東南經密縣、禹州。分爲二派。一經新鄭縣至臨潁縣。一經襄城縣。至臨潁縣。"}]},"洧":{"expl":"水。出潁川陽城山，東南入潁。从水有聲。","rad":"水","fq":"榮美切","vol":"11","py":"wěi","duan":[{"e":"洧水。出潁川陽城山。東南入潁。","n":"前志陽城下曰。陽城山、洧水所出。東南至長平入潁。過郡三。行五百里。過郡三者、潁川南陽汝南也。按據志則陽城縣有陽城山。許不複言陽城。如河南縣、弘農縣之例。水經曰。洧水、出河南密縣西南馬領山。東南至習城西折入於潁。酈曰。亦言出陽城山。葢馬領山之統目焉。習城西折入潁、卽地理志至長平縣入潁者也。方輿紀要曰。今洧水出登封縣陽城山。經密縣至禹州新鄭縣。合溱水爲雙泊河。又經長葛縣、洧川縣、鄢陵縣、扶溝縣。至西華縣入潁。大致東南流也。一統志曰。洧水本至西華入潁。宋時導之自扶溝入蔡。左傳襄十一年濟隧。九年陰坂。廿六年涉於樂氏。說者云皆謂洧津也。"}]},"濦":{"expl":"水。出潁川陽城少室山，東入潁。从水㥯聲。","rad":"水","fq":"於謹切","vol":"11","py":"yīn","duan":[{"e":"濦水。出潁川陽城少室山。東入潁。","n":"水經曰。㶏水、出㶏强縣南澤中。東入潁。酈云。㶏水、出潁川陽城縣少室山。東流注於潁而亂流。東南逕臨潁縣西北。又東逕㶏陽城北。又東逕㶏强縣故城南。汝水於奇雒城西別東派。時人謂之大㶏水。左合小㶏水。東逕西華縣故城南。至女陽縣故城北。東注於潁。按前志汝南郡㶏强、以㶏水得名。今大溵水在郾城縣南。至商水縣東二十里合潁水。小溵水在臨潁縣西南。東流合於潁水。"}]},"濄":{"expl":"水。受淮陽扶溝浪湯渠，東入淮。从水過聲。","rad":"水","fq":"古禾切","vol":"11","py":"ɡuō","duan":[{"e":"濄水。受淮陽扶溝浪湯渠。東入淮。","n":"湯韵會作蕩。前志作狼湯。師古上音浪、下音徒浪反。水經注作蒗𦿆渠。集韵作蒗蕩渠。皆音同字異耳。淮陽國扶溝、見前志。淮陽國、孝明帝更名陳國。而扶溝改屬陳畱置。扶樂縣、屬陳國。今河南開封府扶溝縣、漢縣地也。前志扶溝下曰。渦水首受狼湯渠。東至沛郡向入淮。過郡三。行千里。水經曰。淮水、又東過當塗縣北。濄水從西北來注之。又曰。陰溝水、出河南陽武縣蒗𦿆渠。東南至沛爲濄水。又東南至下邳淮陵縣入於淮。酈云。淮水於荆山北。濄水東南注之。注言下邳淮陵入淮。誤矣按淮水篇酈注曰。淮水逕當塗縣故城北。又東北。又北、沙水注之。經所謂蒗𦿆渠也。於荆山北。濄水東南注之。據酈所云、是渠水濄水以次入淮也。今渦水在安徽鳳陽府懷遠縣入"}]},"泄":{"expl":"水。受九江博安洵波，北入氐。从水丗聲。","rad":"水","fq":"余制切","vol":"11","py":"yì","duan":[{"e":"泄水。受九江博安洵波。北入氐。","n":"前志九江郡博鄉。此云博安、與水經合。洵波當作芍陂。氐當作比。水經曰。泄水、出博安縣。北過芍陂西。與沘水合。西北入於淮。注云。博安縣、地理志之博鄉縣也。泄水自縣上承沘水於麻步川。西北出歴濡谿。謂之濡水。自濡谿逕安豐縣。北流注於淠。亦謂之濡須口。按淠卽沘字。見沘水篇注。洵波無考。疑作芍陂。水經云過芍陂、則非受也。疑當作水受九江博安洵爲句。洵卽濄水出者。下四字當作過芍陂北入比六字。然無左證。與酈云上承沘者不合。亦所謂聞疑載疑而已。"}]},"葬":{"expl":"藏也。从死在茻中；一其中，所以薦之。《易》曰：“古之葬者，厚衣之以薪。”","rad":"茻","fq":"則浪切","vol":"01","py":"zànɡ","duan":[{"e":"臧也。","n":"見檀弓。"}]},"汳":{"expl":"水。受陳畱浚儀陰溝，至蒙爲雝水，東入于泗。从水反聲。","rad":"水","fq":"皮變切","vol":"11","py":"biàn","duan":[{"e":"汳水。受陳畱浚儀陰溝。至蒙爲雝水。東入於泗。","n":"雝當作獲。字之誤也。陳畱郡浚儀、二志同。晉地道記云。衛之儀邑。蘇林曰故大梁城。梁惠王始都此。今河南開封府祥符縣縣城西北浚儀廢縣是也。蒙、二志皆屬梁國。春秋左傳宋有蒙門、蒙澤。今河南歸德府治商邱縣府東北四十里有蒙城是也。前志河南郡熒陽下曰。卞水、在西南梁國。蒙下曰。獲水、首受甾獲渠。東北至彭城入泗。水經曰。汳水、出陰溝於浚儀縣北。又東至梁郡蒙縣爲獲水。餘波南入睢陽城中。獲水、出汳水於梁郡蒙縣北。又東過蕭縣南。睢水北流注之。又東至彭城縣北。東入於泗。按水經至蒙爲獲水。許書當同。不當云爲雝水也。下文灉篆下云。河灉水也。用爾雅河出爲灉語。然則自河出卽爲灉。非自河出爲汳、旣而爲灉也。且許言汳受陰溝、則非"}]},"潧":{"expl":"水。出鄭國。从水曾聲。《詩》曰：“潧與洧，方渙渙兮。”","rad":"水","fq":"側詵切","vol":"11","py":"zhēn","duan":[{"e":"潧水。出鄭國。","n":"鄭國謂周之鄭國、卽漢之新鄭也。鄭語曰。前華後河。右洛左濟。主芣騩而食溱洧。水經曰。潧水、出鄭縣西北平地。酈云。出鄶城西北雞絡隖下。東南流、左合𣸢水。又南、左會承雲山水。又東南、逕鄶城西。謂之桺泉水。又南、注於洧。世亦謂之爲鄶水也。今溱水在河南開封府密縣。東北流經新鄭縣西北。南流合洧水爲雙泊河。而洧盛溱涸矣。"}]},"淩":{"expl":"水。在臨淮。从水夌聲。","rad":"水","fq":"力膺切","vol":"11","py":"línɡ","duan":[{"e":"淩水。在臨淮。","n":"前志臨淮郡。後志爲下邳國。前志泗水國淩。應劭曰。淩水所出。入淮南。後志淩屬廣陵郡。水經注淮水篇。淮水、左逕泗水國南。淩水、出淩縣。東流、逕其縣故城東。而東南流、注於淮。是曰淩口。今江蘇徐州府宿遷縣縣東南五十里有淩城。淩水未詳。"}]},"濮":{"expl":"水。出東郡濮陽，南入鉅野。从水僕聲。","rad":"水","fq":"博木切","vol":"11","py":"pú","duan":[{"e":"濮水。出東郡濮陽。南入鉅野。","n":"東郡濮陽、二志同。前志濮陽下曰。衞成公自楚丘徙此。故帝丘。顓頊虛。杜預曰。帝丘、昆吾氏因之。故曰昆吾之虛。今直𣜩大名府開州西南濮陽故城是也。鉅野、二志屬山陽郡。前志鉅壄下曰。大壄澤在北。兖州藪。卽西狩獲麟之所。爾雅十藪之一。今山東曹州府鉅野縣、漢舊縣也。自隨以後。濟流枯竭。大野漸微。元末爲河所決。河徙後遂涸爲平陸。濮水者、殷紂時師延作靡靡之樂。已而自沈之水也。前志陳畱郡封丘下曰。濮渠水首受？。東北至都關入羊里水。水經注濟水篇言濮渠故瀆、自濟東北流爲高梁陂。又東逕匡城北。又東北逕酸棗縣故城南。又東逕蒲城北。又東逕韋城南。又東逕長垣縣故城北。又東分爲二瀆。北濮出焉。濮渠又東逕須城北。又東逕濮陽故城"}]},"濼":{"expl":"齊魯閒水也。从水樂聲。《春秋傳》曰：“公會齊侯于濼。”","rad":"水","fq":"盧谷切","vol":"11","py":"luò","duan":[{"e":"齊魯閒水也。","n":"春秋桓十八年。公會齊侯於濼。三經三傳皆同。杜曰。濼水在濟南歴城縣。西北入濟。水經注濟水篇曰。濟水、又逕盧縣故城北。又逕什城北。又東北、右會玉水。又東北、濼水入焉。水出歴城縣故城西南。春秋桓公十八年公會齊侯於濼是也。俗謂之娥英水。合大明湖、歴水北流注於濟。齊乘曰。小淸河之在歴城者、卽古濼水。按今山東濟南府歴城縣小淸河源出縣西。東經章邱、鄒平、長山、新城。入靑州府高苑縣。至博興縣合時水入海。而章邱以下淤塞。濼水東北入大淸河。"}]},"漷":{"expl":"水。在魯。从水郭聲。","rad":"水","fq":"苦郭切","vol":"11","py":"kuò","duan":[{"e":"漷水。在魯。","n":"春秋經襄十九年。取邾田、自漷水。公羊傳曰。其言自漷水何。以漷爲竟也。何言乎以漷爲竟。漷移也。何云。魯本與邾婁以漷爲竟。漷移入邾婁畍。魯隨而有之。諸侯土地本有度數。不得隨水。隨水有之。當坐取邑。水經注泗水篇曰。漷水、出東海合鄉縣。西南流入邾。又逕魯國鄒山東南而西南流。左傳所謂嶧山。詩所謂保有鳧嶧者也。又西南逕蕃縣故城南。又西逕薛縣故城北。夏車正奚仲之國也。又西至湖陸縣入於泗。按合鄉、蕃、薛故城皆在今山東滕縣。不云在魯邾婁之閒、徑云水在魯者、邾婁魯附庸。非敵。故立文如是。一統志曰。漷水源出滕縣東北百里述山。西流會諸泉水。逕縣南。又西會南梁河。入運河。舊名南沙河。西南流入泗。不與南梁會。自漕河東徙。"}]},"淨":{"expl":"魯北城門池也。从水爭聲。","rad":"水","fq":"士耕切","vol":"11","py":"chénɡ","duan":[{"e":"魯北城門池也。","n":"公羊傳閔二年。桓公使高子將南陽之甲。立僖公而城魯。或曰。自鹿門至于爭門者是也。或曰。自爭門至于吏門者是也。魯人至今以爲美談。曰。猶望高子也。鹿門者、魯南城之東門。爭門者、魯北城之門。天子十二門。通十二子。諸侯大國當是九門。俟攷。淨者、北城門之池。其門曰爭門。則其池曰淨。从爭旁水也。廣韵曰。埩七耕切。魯城北門池也。說文作淨。蓋古書有作埩門者矣。城北誤倒。"}]},"濕":{"expl":"水。出東郡東武陽，入海。从水㬎聲。桑欽云：出平原高唐。","rad":"水","fq":"他合切","vol":"11","py":"tà","duan":[{"e":"濕水。出東郡東武陽。入海。","n":"東郡東武陽、二志同。今山東曹州府朝城縣縣東南有東武陽城是也。前志東武陽下曰。禹治漯水。東北至千乘入海。過郡三。行千二十里。過郡三者、東郡平原千乘也。水經曰。河水、又東北過高唐縣東。注云。河水於縣漯水注之。漯水上承河水於東武陽縣東南、而北逕武陽新城東。又逕東武陽故城南。又北逕陽平縣故城東。又北絶莘道城之西北。又東北逕樂平縣故城東。又北逕𦕼城縣故城西。又東北逕淸河縣故城北。又東北逕文鄉城東南。又東北逕博平縣故城南。又東北逕瑗縣故城西。又東北逕高唐縣故城東。又東北逕濕陰縣故城北。又東北逕著縣故城南。又東北逕崔氏城北。又東逕鄒平縣故城北。又東北逕建信縣故城北。又東北逕千乘縣二城閒。又東北爲馬常坈。亂河"}]},"泡":{"expl":"水。出山陽平樂，東北入泗。从水包聲。","rad":"水","fq":"匹交切","vol":"11","py":"pāo","duan":[{"e":"泡水。出山陽平樂。東北入泗。","n":"山陽郡平樂、見前志。志云侯國。泡水、東北至沛入泗。水經注泗水篇曰。黃溝、又東逕平樂縣。又東、右合泡水。卽豐水之上源也。水上承大薺陂。東逕貰城北。又東逕已氏縣故城南。又東逕卭城縣故城南。又東逕單父縣故城南。又東逕平樂縣。右合泡水。自下豐、泡竝得通稱。故地理志曰。平樂、泡水所出。又東逕豐縣故城南。又東逕沛縣故城南。於城南東注泗。地理志曰。泡水自平樂東北至沛入泗者也。按今泡河自今山東單縣流逕江蘇豐縣北。又東逕沛縣畍。循城東南。至泗亭驛而合於泗。"}]},"菏":{"expl":"菏澤水。在山陽胡陵。《禹貢》：“浮于淮泗，達于菏。”从水苛聲。","rad":"水","fq":"古俄切","vol":"11","py":"ɡē","duan":[{"e":"渮水。在山陽湖陵南。","n":"各本水上衍澤字、陵下奪南字。今依尙書音義正。前志山陽湖陵下曰。禹貢荷水在南。濟陰郡下曰。禹貢荷澤在定陶東。水經曰。荷水、在山陽湖陸縣南。荷澤在濟陰定陶縣東。是豫州渮澤、徐州渮水、畫然二事。依水經及注。渮水雖源於渮澤。而與渮澤迥別。釋文於徐州引說文水出山陽湖陵南、非渮澤也。今本說文淺人增澤。大誤矣。山陽郡湖陵、見前志。王莽改曰湖陸。光武仍曰湖陸。至章帝復湖陸之號。今山東兖州府魚臺縣縣東南六十里有湖陵故城。與江南沛縣接畍。前志湖陵下曰。禹貢浮於淮泗。通於荷。荷水在南。不但言荷水在南而必舉此禹貢文者、明此荷水非豫州及道沇水之荷澤也。水經曰。濟水、又東至乘氏縣西。分爲二。其一東南流者、過乘氏縣南。又東"}]},"小":{"expl":"物之微也。从八，丨見而分之。凡小之屬皆从小。","rad":"小","fq":"私兆切","vol":"02","py":"xiǎo","duan":[{"e":"物之微也。从八丨見而八分之。","n":"八、別也。象分別之形。故解从八爲分之。丨才見而輒分之。會意也。凡㮯物分之則小。私兆切。二部。"}]},"泗":{"expl":"受泲水，東入淮。从水四聲。","rad":"水","fq":"息利切","vol":"11","py":"sì","duan":[{"e":"泗水。受泲水。東入淮","n":"地理志濟陰乘氏下曰。泗水東南至睢陵入淮。過郡六。行千一百一十里。又魯國卞縣下曰。泗水、出縣北。三字依水經注補西南至方與入泲。過郡三。行五百里。靑州川。出乘氏者、其遠源。出卞者、其近源。過郡三當作過郡二。過郡二者、魯山陽也。水經曰。泗水、出魯卞縣北山。西南過魯縣北。又西過瑕丘縣。東屈。從縣東南流。漷水從東來注之。又南過平陽縣西。又南過高平縣西。洸水從西北來流注之。又南過方與縣東。渮水從西來注之。又屈。東南過湖陸縣南。涓涓水從東北來流注之。又東過沛縣東。又東南過彭城縣東北。又東南過呂縣南。又東南過下邳縣西。又東南入於淮。此舉卞縣以下所經二郡也。卞縣、今山東兖州府泗水縣縣東五十里卞故城是也。許不言水"}]},"洹":{"expl":"水。在齊魯閒。从水亘聲。","rad":"水","fq":"羽元切","vol":"11","py":"huán","duan":[{"e":"𣵨水。在齊魯閒。","n":"齊當依水經注所引說文、字林作晉。左傳成七年。聲伯夢涉洹。杜曰。洹水出汲郡林慮縣。東北至魏郡長樂縣入淸水。水經曰。洹水、出上黨泫氏縣。東過隆慮縣北。又東北出山。過鄴縣南。又東過內黃縣北。東入於白溝。林慮縣卽隆慮縣。今河南彰德府林縣是其地也。今洹水自山西長子縣流入。經林縣東北流。經安陽縣北。又東流經內黃縣西北入衞河。水道提綱曰。衞河又東北經彰德府治安陽縣東南畍。有洹河自西北來會。其南岸卽內黃縣西境也。水經之白溝、今衞河在內黃者皆卽淇水。許當云在晉衞之閒。云在晉魯閒者、魯衞相近。以魯聲伯夢渉而云也。"}]},"灉":{"expl":"河灉水。在宋。从水雝聲。","rad":"水","fq":"於容切","vol":"11","py":"yōnɡ","duan":[{"e":"河灉水也。","n":"也字依水經注補。水經曰。瓠子河、出東郡濮陽縣北河。酈云。尙書雝沮會同。爾雅曰水自河出爲灉。許愼曰雝者、河雝水也。是酈意以瓠子河爲尙書之雝也。按自河出爲灉、濟爲濋、汶爲灛、洛爲波、漢爲濳、淮爲滸、江爲沱、濄爲洵、潁爲沙、汝爲濆、見於釋水。其見於說文者、則沱也、濳也、灉也、洵也。河之別爲灉、如江之別爲沱。沱非一沱、則灉亦非一灉。凡首受河之水皆可名之矣。"}]},"澶":{"expl":"澶淵水。在宋。从水亶聲。","rad":"水","fq":"市連切","vol":"11","py":"chán","duan":[{"e":"澶淵水也。","n":"也字今補。"}]},"洙":{"expl":"水。出泰山蓋臨樂山，北入泗。从水朱聲。","rad":"水","fq":"市朱切","vol":"11","py":"shū","duan":[{"e":"洙水。出泰山葢臨樂山。北入泗。","n":"泰山郡葢、二志同。今山東沂州府沂水縣縣西北七十里有葢城是也。前志葢下曰。臨樂于山、洙水所出。西北至葢入池水。水經曰。洙水、出泰山葢縣臨樂山。西南至卞縣入於泗。按此條水經與志迥殊。志云臨樂于山者、謂勃海郡臨樂縣之于山也。泝其源而言。故下文云至葢。非謂洙出葢也。而經、注皆刪于字。謂臨樂爲葢縣山名。其亦誤矣。池、注引作泗。云或作池。葢字誤。夫經、注皆云泗水出卞縣。不云出葢縣。又皆云洙水至卞入泗。不云至葢入泗。然則卽改池爲泗、亦於水道不合。安知班時無池水。抑或不知何字之誤、而竟作泗字也。杜預釋例云。出魯國東北。西南入沇水。下合泗。乃作沇字。俟攷。葢洙水在班時已非古道。故其書法不同他水。至桑、酈時更昧於"}]},"沭":{"expl":"水。出青州浸。从水术聲。","rad":"水","fq":"食聿切","vol":"11","py":"shù","duan":[{"e":"沭水。出靑州浸。","n":"出下有奪文。集韵、類篇徑刪浸字。非是。當補琅邪東莞南入泗七字。周禮。靑州。其浸沂、沭。注云。沭出東莞。前志琅邪郡東莞。術水南至下邳入泗。過郡三。行七百一十里。靑州浸。東莞、今山東沂州府沂水縣治西北東莞故城是也。水經曰。沭水、出琅邪東莞縣西北大弁山。東南過其縣東。又東南過莒縣東。又南過陽都縣東。入於沂。酈曰。舊瀆入泗。非入沂也。今沭水出沂水縣北臨胊縣南之沂山。東南流徑莒州東。又西南流徑蘭山縣東。又南徑郯城縣東。又西南流、入江南沭陽縣畍。分爲二派。下流入海。迥非舊道矣。"}]},"沂":{"expl":"水。出東海費東，西入泗。从水斤聲。一曰沂水，出泰山蓋青州浸。","rad":"水","fq":"魚衣切","vol":"11","py":"yí","duan":[{"e":"沂水。出東海費東。西入泗。","n":"東海郡費、見前志。春秋魯季氏邑。今山東沂州府費縣縣西北二十里費故城是也。職方氏曰。靑州、其山鎭曰沂山。其浸沂、沭。鄭曰。沂山、沂水所出也。在葢。前志泰山郡葢下曰。沂水出。水經曰。沂水、出泰山葢縣艾山。許云出東海費東。說乖異者、葢沂山卽東泰山。是山盤回數縣。今沂水出沂水縣之雕厓山。卽沂山西峯也。又西北接大弁山。卽沭水所出也。前志曰。沂水南至下邳入泗。水經曰。沂水、出泰山葢縣艾山。南過琅邪臨沂縣東。又南過開陽縣東。又東過襄賁縣東。屈從縣南、西流。又屈南過郯縣西。又南過良成縣西。又南過下邳縣西南。入於泗。許云西入泗、疑當作南入。然酈善長所據已作西矣。今沂水出雕厓山。東南流逕沂水縣西。又南流逕蘭山縣東"}]},"洋":{"expl":"水。出齊臨朐高山，東北入鉅定。从水羊聲。","rad":"水","fq":"似羊切","vol":"11","py":"xiánɡ","duan":[{"e":"𣴱水。出齊臨胊高山。東北入鉅定。","n":"齊郡臨胊、後志作齊國臨胊。今山東靑州府臨胊縣其地也。前志臨胊下曰。石膏山、洋水所出。東北至廣饒入鉅定。水經注巨洋水篇曰。巨洋水、又逕臨胊縣故城東。又東北逕委粟山。又東北、洋水注之。水西出石膏山西北石澗口。東南逕逢山祠西。又東南歴逢山下。卽石膏山也。巨洋水、又東北逕劇縣故城西。又東北逕益縣故城東。又東北積而爲潭。枝津出焉。謂之百尺溝。西北流注於巨淀。又東北逕壽光縣故城西。又東北注於海。按班、許曰洋水。卽水經及注之巨洋水也。班、許以出臨胊石膏山者爲正源耳。許云高山、卽石膏山也。前志齊郡有廣饒、鉅定二縣。馬車瀆水首受鉅定。然則鉅定本水名。因以爲縣名。定淀古今字。魏都賦張注曰淀者、如淵而淺是也。廣饒、"}]},"濁":{"expl":"水。出齊郡厲嬀山，東北入鉅定。从水蜀聲。","rad":"水","fq":"直角切","vol":"11","py":"zhuó","duan":[{"e":"濁水。出齊郡","n":"上文不言郡。此字葢淺人增之。"}]},"漑":{"expl":"水。出東海桑瀆覆甑山，東北入海。一曰灌注也。从水旣聲。","rad":"水","fq":"古代切","vol":"11","py":"ɡài","duan":[{"e":"漑水。出東海桑瀆覆甑山。東北入海。","n":"東當作北。瀆當作犢。皆字之誤也。北海郡桑犢、見前志。今山東萊州府濰縣有桑犢故城。水經注之桑犢亭也。前志桑犢下云。覆甑山、漑水所出。東北至都昌入海。今濰縣東南四十里漑源山。卽覆甑山也。水經注亦謂之塔山。寰宇記曰。天寶六載勅改爲漑源山。今漑水自漑源山北流至昌邑縣境入海。卽東虞河也。亦曰東丹河。"}]},"少":{"expl":"不多也。从小丿聲。","rad":"小","fq":"書沼切","vol":"02","py":"shǎo","duan":[{"e":"不多也。","n":"不多則小。故古少小、互訓通用。"}]},"濰":{"expl":"水。出琅邪箕屋山，東入海。徐州浸。《夏書》曰：“濰、淄其道。”从水維聲。","rad":"水","fq":"以追切","vol":"11","py":"wéi","duan":[{"e":"濰水。出琅邪箕屋山。東入海。","n":"琅邪郡箕、見前志。故城當在今山東沂州府莒州境。前志箕下云。禹貢維水、北至都昌入海。過郡三。行五百二十里。兖州？也。水經曰。濰水、出琅邪箕縣濰山。東北過東武縣西。又北過平昌縣東。又北過高密縣西。又北過淳于縣東。又東北過都昌縣東。又東北入於海。按屋山在今莒州西北九十里。水經注曰。濰山屋山及淮南子云出覆舟山、實一山也。今濰水出莒州西東北箕屋山。東南流、入靑州府諸城縣畍。逕萊州府高密縣畍。又北逕安邱縣東。又北流、入萊州府昌邑縣畍。又東北入海。曰淮河口。與古水道合。漢都昌城在今昌邑縣西。"}]},"浯":{"expl":"水。出琅邪靈門壺山，東北入濰。从水吾聲。","rad":"水","fq":"五乎切","vol":"11","py":"wú","duan":[{"e":"浯水。出琅邪靈門壷山。東北入濰。","n":"琅邪郡靈門、見前志。今山東沂州府莒州州北百二十里有靈門城。前志靈門下曰。壷山、浯水所出。東北入淮。淮當作維。字之誤也。水經注曰。濰水、又北逕平昌縣故城東。又北浯水注之。水出浯山。世謂之巨平山。許愼言水出靈門山。世謂之浯汶矣。其水東北逕姑幕縣故城東。又東北逕平昌縣故城北。又東北流、注於濰水。今浯水自莒州流入渚城縣畍。東北流、逕安丘縣東南入濰水。"}]},"汶":{"expl":"水。出琅邪朱虛東泰山，東入濰。从水文聲。桑欽說：汶水出泰山萊蕪，西南入泲。","rad":"水","fq":"亡運切","vol":"11","py":"wèn","duan":[{"e":"汶水。出琅邪朱虚東泰山。東入濰","n":"琅邪郡朱虛、見前志。後志屬北海國。今山東靑州府臨胊縣東六十里有朱虛故城。前志朱虛下云。東泰山、汶水所出。東至安丘入維。水經曰。汶水、出朱虛縣泰山。北過其縣東。又北過淳于縣西。又東北入於濰。謂之東汶水。以別於禹貢汶水也。按東泰山卽封禪書黃帝封東泰山、今沂山是也。今東汶河源出臨胊縣南沂山東北谷。東流近穆陵關。折東北流數十里。折東流百五十里。至安邱縣西南境。折東北流經縣城西北。又東流數十里與濰水會。"}]},"治":{"expl":"水。出東萊曲城陽丘山，南入海。从水台聲。","rad":"水","fq":"直之切","vol":"11","py":"chí","duan":[{"e":"治水。出東萊曲城陽丘山。南入海。","n":"城當作成。字之誤也。東萊郡曲成、二志同。今山東萊州府掖縣東北六十里有曲成故城。前志曲成下曰。陽丘山、治水所出。南至沂入海。按沂字疑誤。一本作至臨沂尤誤。當作計斤二字。今掖縣東南三十里有陽邱山。亦名馬鞍山。今治水名小沽河。自掖縣馬鞍山南流至平度州東南。與出登州府黃縣之大沽河合流。逕卽墨。至膠州之麻灣口入海。一統志曰。左傳昭二十年。姑尤以西。杜注。姑水、尤水皆在城陽郡。東南入海。齊乘。姑卽大沽河。尤卽小沽河。玉裁謂尤古音讀如貽。與治同在第一部。齊乘之言可信也。"}]},"寖":{"expl":"水。出魏郡武安，東北入呼沱水。从水𡩠聲。𡩠，籒文𡪢字。","rad":"水","fq":"子鴆切","vol":"11","py":"jìn","duan":[{"e":"濅水。出魏郡武安。東北入呼沱水。","n":"魏郡武安、二志同。今河南彰德府武安縣縣西南五十里有武安城。前志武安下曰。？水東北至信都國東昌入虖池河。過郡五。行六百一十里。"}]},"湡":{"expl":"水。出趙國襄國之西山，東北入寖。从水禺聲。","rad":"水","fq":"噳俱切","vol":"11","py":"yú","duan":[{"e":"湡水。出趙國襄國之西山。東北入濅。","n":"趙國襄國、二志同。今直隷順德府郉臺縣西南有襄國故城。商祖乙遷於郉、周時郉國皆在此。前志襄國下曰。西山、渠水所出。東北至廣平國任縣入？。按渠水當是湡水之譌。一統志曰。灃河源出郉臺縣東南。東流逕南和縣西南。又東北逕任縣東。至隆平縣入胡盧河。卽百泉水也。方輿紀要曰。百泉水、葢卽灃河之上源。引志云百泉水、一名湡水。又名鴛鴦水。隋志以爲㴲水也。鴛鴦水在南和縣西。見魏都賦注。"}]},"㴲":{"expl":"水。出趙國襄國，東入湡。从水虒聲。","rad":"水","fq":"息移切","vol":"11","py":"sī","duan":[{"e":"㴲水。出趙國襄國。東入湡。","n":"前志襄國下云。又有蓼水、馮水。皆東至廣平國朝平入湡。按馮水當是㴲水之譌。字之誤也。廣平國南和下云。列葭水東入㴲。葢湡㴲二水今不可別矣。㴲入湡。湡入浸。浸入虖沱。虖沱移徙不常。故道今不可攷。水經注虖沱篇佚。"}]},"渚":{"expl":"水。在常山中丘逢山，東入湡。从水者聲。《爾雅》曰：“小洲曰渚。”","rad":"水","fq":"章与切","vol":"11","py":"zhǔ","duan":[{"e":"渚水。在常山中丘逢山。東入湡。","n":"常山郡中丘、見前志。中丘下云。逢山長谷、諸水所出。東至張邑入濁。按諸當作渚。濁當作湡。皆字之誤也。張邑卽廣平國之張也。中丘、渚水俟攷。"}]},"洨":{"expl":"水。出常山石邑井陘，東南入于泜。从水交聲。𨙶國有洨縣。","rad":"水","fq":"下交反","vol":"11","py":"xiáo","duan":[{"e":"洨水。出常山石邑井陘。東南入于泜。","n":"于、衍字也。常山郡石邑、見前志。井陘、謂石邑之井陘山也。今直隷正定府獲鹿縣縣西南有石邑城、戰國時趙邑也。前志石邑下曰。井陘山在西。洨水所出。東南至廮陶入泜。井陘縣下應劭注曰。井陘山在南。然則井陘縣在石邑之西。井陘山在石邑西南、井陘縣南也。井陘山之東南則石邑地也。今洨河出獲鹿縣南。東流逕樂城縣西。又南入趙州畍。舊志云。下流至寧晉縣。注於胡盧河。上源四泉交合。故謂之洨也。"}]},"濟":{"expl":"水。出常山房子贊皇山，東入泜。从水齊聲。","rad":"水","fq":"子礼切","vol":"11","py":"jǐ","duan":[{"e":"𣺴水。出常山房子贊皇山。東入泜。","n":"常山郡房子、見前志。後志云。常山國房子。今直隷正定府贊皇縣是其地。前志房子下曰。贊皇山、石濟水所出。東至廮陶入泜。後志曰。贊皇山在縣西南六十里。濟水所出。按此水名與四瀆之？字各不同。而經傳皆作濟。風俗通遂誤以常山房子之水列入四瀆。而云廟在東郡臨邑縣。豈知班志臨邑下云有？廟、字固作？乎。今本前志石濟水、石字疑衍。以說文、風俗通、後志正之。皆不當有石字。一統志曰。舊志云槐水出黃沙嶺。流經贊皇縣西北十里。入元氏縣畍。合泜水。又東南歷高邑、柏鄉、達寧、晉縣。入胡盧河。卽古大陸澤。玉裁謂槐水卽古濟水也。贊皇山在今贊皇縣西南。"}]},"尐":{"expl":"少也。从小乀聲。讀若輟。","rad":"小","fq":"子結切","vol":"02","py":"jié","duan":[{"e":"少也。","n":"方言曰。尐杪小也。孟子。力不能勝一尐雛。趙注尐爲小。與方言同。孫宣公音義得之。作匹者非。髟部曰。䰏、束髮尐小也。廣韵十六㞕曰。䩏尐、小也。方言懱爵。注言懱𢧵也。懱𢧵卽䩏尐。"}]},"泜":{"expl":"水。在常山。从水氐聲。","rad":"水","fq":"直尼切","vol":"11","py":"chí","duan":[{"e":"泜水。在常山。","n":"前志常山郡元氏下曰。沮水首受中丘西山窮泉谷。至堂陽入黃河。按沮當作泜。北山經注云。今泜水出中丘縣西窮泉谷。東注於堂陽縣。入於漳水。以郭正班。知沮爲字之誤。風俗通云。濟水出常山房子贊皇山。東入沮。此亦泜譌作沮也。由書氐作互。遂譌且耳。班志入黃河亦當依郭作濁漳。攷水經注濁漳過堂陽縣。而河水不徑堂陽。元和志曰。泜水在贊皇縣西南二十五里。卽韓信斬陳餘處。今泜水在元氏縣。源出封龍山。東南流經縣西南六十里紙屯村。入槐河。泜與濟互受通稱。"}]},"濡":{"expl":"水。出涿郡故安，東入漆涑。从水需聲。","rad":"水","fq":"人朱切","vol":"11","py":"rú","duan":[{"e":"濡水。出涿郡故安。東入淶。","n":"淶各本作漆涑二字。今正。戴先生曰。易水篇注云。許愼曰。濡水入淶。淶卽巨馬之異名。與巨馬河注巨馬河卽淶水也正合。今水經注淶譌深。說文淶譌漆涑二字。皆字之誤耳。涿郡故安、二志同。今直隷易州州東南有故安故城是。戰國時燕與趙易土。燕以武陽與趙。卽此也。前志故安下曰。閻鄉、易水所出。東至范陽入濡。并州寖。濡水亦至范陽入淶。今本漢志脫濡字。師古謬爲之注。非也。水經注易水篇曰。易水、逕范陽縣故城南。又東與濡水合。水出故安縣西北窮獨山南谷。東流與源泉水合。又東南流逕樊於、期館西、荆軻館北。又東逕武陽城西北。又東逕紫池堡。又東得白楊水口。又東合檀水。又東南流於容城縣西北、大利亭東南合易水。而注巨馬水也。故地理志"}]},"灅":{"expl":"水。出右北平浚靡，東南入庚。从水壘聲。","rad":"水","fq":"力軌切","vol":"11","py":"lěi","duan":[{"e":"灅水。出右北平俊靡。東南入庚。","n":"俊各本作浚。今依二志作俊。右北平俊靡、二志同。今直隷順天府遵化州州西北有俊靡故城是。前志右北平無終下曰。浭水、西至雍奴入海。俊靡下曰。灅水、南至無終。東入庚。浭與庚、一字也。水經注鮑丘水篇曰。鮑丘水、北逕雍奴縣東。又東庚水注之。水出右北平徐無縣北塞中。而南流得黑牛谷水。又西南流、灅水注之。水出右北平俊靡縣。東南流與溫泉水合。又東南逕石門峽。又東南流、謂之北黃水。又屈而南爲南黃水。又西南逕無終山。藍水注之。又西南入於庚水。庚水又南逕北平城西。而南入鮑丘水。鮑丘水又東。巨梁水注之。鮑丘水至雍奴縣北屈。東入海。歙程氏瑶田通藝錄曰。今灅水自遵化州西北四十五里鮎魚石關外入口。東經溫泉。酈所謂與溫泉水合也"}]},"沽":{"expl":"水。出漁陽塞外，東入海。从水古聲。","rad":"水","fq":"古胡切","vol":"11","py":"ɡū","duan":[{"e":"沽水出漁陽塞外。東入海。","n":"漁陽下當有縣字。說見邑部。漁陽郡漁陽、二志同。今直隷順天府密雲縣縣西南三十里漁陽故城是也。前志漁陽下曰。沽水出塞外。東南至泉州入海。行七百五十里。水經曰。沽河從塞外來。南過漁陽狐奴縣北。西南與濕餘水合爲潞河。又東南至雍奴縣西爲笥溝。又東南至泉州縣與淸河合。東入於海。淸河者、派河尾也。按凡曰出某縣塞外、某縣徼外、某縣某方蠻夷中者、皆言其來之遠。不可得其地名。故系之某縣也。此云漁陽塞外、則非出漁陽矣。今直隷之白河、卽沽河也。白河遠出宣化府獨石口之獨石水。合赤城水、龍門水東南流。逕宻雲縣西。與潮河合。潮河古鮑丘水也。旣得潮河。西南逕懷柔縣東南。南經順義縣東。至通州城北東南三面。俗稱古潞水。又南逕舊漷"}]},"沛":{"expl":"水。出遼東番汗塞外，西南入海。从水巿聲。","rad":"水","fq":"普蓋切","vol":"11","py":"pèi","duan":[{"e":"沛水。出遼東番汗塞外。西南入海。","n":"番音盤。汗音寒。遼東郡番汗。二志同。今奉天府遼陽州、漢遼東郡治也。番汗未聞。前志番汗下曰。沛水出塞外。西南入海。沛水亦未聞。"}]},"浿":{"expl":"水。出樂浪鏤方，東入海。从水貝聲。一曰出浿水縣。","rad":"水","fq":"普拜切","vol":"11","py":"pèi","duan":[{"e":"浿水。出樂浪鏤方。東入海。","n":"樂浪音洛郞。樂浪郡鏤方、二志同。鏤方未聞。前志樂浪郡浿水縣下曰。浿水西至增地入海。水經曰。浿水出樂浪鏤方。東南過臨浿縣。東入於海。酈按漢志是。說文及水經非也。酈云其水西流。逕故樂浪朝鮮縣、卽樂浪郡治。而西北流。故地理志曰。浿水西至增地縣入海。浿水今朝鮮國之大通江。在平壤城北。平壤城卽古王險城。漢之朝鮮縣也。隋書曰。平壤城南臨浿水。"}]},"瀤":{"expl":"北方水也。从水褱聲。","rad":"水","fq":"戶乖切","vol":"11","py":"huái","duan":[{"e":"北方水也。","n":"北山經曰。獄法之山、瀤津之水出焉。"}]},"㶟":{"expl":"水。出鴈門陰館累頭山，東入海。或曰治水也。从水纍聲。","rad":"水","fq":"力追切","vol":"11","py":"lěi","duan":[{"e":"㶟水。出鴈門陰館絫頭山。東入海。","n":"沈約宋書曰。陰館、前漢作觀。後漢、晉作館。按今前書不作觀。葢淺人改也。鴈門郡陰館、二志同。今山西代州州北四十里陰館城是。在句注陘北。絫頭山在今朔州代州之閒。前志陰館下曰。絫頭山、治水所出。東至泉州入海。過郡六。行千一百里。水經曰。㶟水、出鴈門陰館縣。東北過代郡桑乾縣南。又東過涿鹿縣北。又東過出山。過廣陽薊縣北。又東至漁陽雍奴縣西入笥溝。按治水、㶟水異名同實。武五子傳作台水。台卽治也。前志代郡且如下。于延水出塞外。東至廣寧入治。今本無廣平舒下。祁夷水北至桑乾入治。小顔本治皆譌沽。姑故二音。其繆甚矣。酈云。地理志于延水東至廣寧入治、非是。謂于延逕廣寧故城南。又逕茹縣故城北。又逕鳴雞山西。又逕且居縣"}]},"𣻐":{"expl":"水。出北地直路西，東入洛。从水虘聲。","rad":"水","fq":"側加切","vol":"11","py":"jū","duan":[{"e":"𣻐水。出北地直路西。東入洛。","n":"北地郡直路、見前志。今未聞。前志直路下曰。沮水出東。西入洛。水經曰。沮水、出北地直路縣。東過馮翊祋祤縣北。東入於洛。按前志當云出西、東入。今本誤倒。洛者、上文出北地歸德北夷界中東南入渭之水也。酈注謂沮水下流合銅官。注鄭渠。而東入洛。自鄭渠湮廢。沮水故道難考矣。今沮水出陝西鄜州中部縣西北子午山。東流經駱駝岡翟道山南。俗曰沮水。有子午河自西來會。又東有慈烏河西南來會。東南流經縣城南。又東稍北三十餘里入洛河。葢非班、許、水經所謂也。禹貢。道渭自鳥鼠同穴。東會于灃。又東會于涇。又東過漆沮。入于河。尙書某氏傳云。漆沮、一水名。亦曰洛水。水經。渭水又東過華陰縣北。注云。洛水入焉。闞駰以爲漆沮之水也。是則洛"}]},"泒":{"expl":"水。起雁門葰人戍夫山，東北入海。从水瓜聲。","rad":"水","fq":"古胡切","vol":"11","py":"ɡū","duan":[{"e":"泒水。起鴈門葰人戍夫山。東北入海。","n":"葰人縣、後志無。前志屬太原郡。此屬鴈門者、二郡境相接。容有改屬也。葰如淳音瑣。師古音山寡反。史記周勃、樊噲二傳作靃人。左傳襄十年之霍人也。今山西代州繁峙縣縣南有葰人故城。戍夫山、卽泰戲之山也。北山經曰。泰戲之山、虖沱之水出焉。而東流注於漊水。郭云。今虖沱水出鴈門鹵城縣南武夫山。李吉甫曰。泰戲山、一名武夫山。在繁峙縣東南。虖沱水出焉。通典。虖沱水出繁？縣東南泒阜山。明統志謂之小泒山、大泒山。然則戍夫卽武夫、卽泰戲也。？水卽虖沱之源也。"}]},"八":{"expl":"別也。象分別相背之形。凡八之屬皆从八。","rad":"八","fq":"博拔切","vol":"02","py":"bā","duan":[{"e":"別也。","n":"此以雙聲𤴁{疊}韵說其義。今江浙俗語以物與人謂之八。與人則分別矣。"}]},"滱":{"expl":"水。起北地靈丘，東入河。从水寇聲。滱水卽漚夷水，并州川也。","rad":"水","fq":"苦候切","vol":"11","py":"kòu","duan":[{"e":"滱水。起北地靈丘。東入河。","n":"北地當作代郡。前志曰。代郡靈丘。今山西大同府靈邱縣東有靈丘故城。靈丘下曰。滱水東至文安入大河。過郡五。行九百四十里。水經曰。滱水、出代郡靈丘縣高氏山。東南過廣昌縣南。又東南過中山上曲陽縣北。恒水從西來注之。又東過唐縣南。又東過安憙縣南。又東過安國縣北。又東過博陵縣南。又東北注於易。今直隷唐河、卽古滱水也。出大同府渾源州南。今翠屏山、卽古高氏山。東南流入靈邱縣。又東南流入直隷易州廣昌縣界。由倒馬關流入。逕完縣西北、唐縣西南界。又東南過定州。入慶都縣南界。又逕祁州南。會沙滋二水。又東北逕博野、蠡二縣南。又東北逕高陽縣東。又北逕安州東。入白洋淀。一統志曰。據水經注。葢滱水故道本由今淸苑縣東南與濡博諸"}]},"淶":{"expl":"水。起北地廣昌，東入河。从水來聲。幷州浸。","rad":"水","fq":"洛哀切","vol":"11","py":"lái","duan":[{"e":"淶水。起北地廣昌。東入河。","n":"北地當作代郡。代郡廣昌、見前志。後志屬中山國。今直隷易州廣昌縣縣北有廣昌故城。職方氏曰。幷州、其浸淶、易。鄭云。淶出廣昌。前志廣昌下曰。淶水東南至容城入河。過郡三。行五百里。幷州浸。水經曰。巨馬河、出代郡廣昌縣淶山。巨馬河卽淶水也。東過逎縣北。又東南過容城縣北。又東過勃海東平舒縣東。入於海。酈云。巨馬水於東平舒北。南入於滹沱。而同歸於海也。今淶水一名巨馬河。源出廣昌縣南東。流轉南。逕易州淶水縣東。又南入保定府定興縣畍。至縣南爲白溝河。又東南逕容城縣東北。又東逕新城縣南。又東南逕雄縣西。又東入保定縣界。非酈注舊迹也。"}]},"泥":{"expl":"水。出北地郁郅北蠻中。从水尼聲。","rad":"水","fq":"奴低切","vol":"11","py":"ní","duan":[{"e":"泥水。出北地郁郅北蠻中。","n":"北地郡郁郅、見前志。今甘肅慶陽府安化縣治、卽郁郅故城也。前志郁郅下曰。泥水、出北蠻夷中。泥陽下應注曰。泥水、出郁郅北蠻中。一統志曰。東河在安化縣東。卽白馬水也。元和志。延慶縣西臨白馬州。寰宇記。白馬水、出北塞夷中。引水經注云洛川南逕尉李城東北。合馬嶺水。號白馬水。明統志。東河來自沙漠。至安化城北。合懷安及靈溝水南流。至合水縣爲馬蓮河。東河及下流馬蓮河皆卽古泥水也。按馬蓮、卽馬嶺之轉語。"}]},"湳":{"expl":"西河美稷𠈃東北水。从水南聲。","rad":"水","fq":"乃感切","vol":"11","py":"nǎn","duan":[{"e":"西河美稷保東北水。","n":"宋本及集韵、類篇皆同。一本無北字。西河郡美稷、見前志。今蒙古鄂爾多斯左翼中旗東南有漢美稷故城。在故勝州之西南也。檀弓注曰。保、縣邑小城。保堡古今字。水經注河水篇曰。河水、又南。樹頽水注之。河水、又左。得湳水口。水出西河郡美稷縣。東南流。又東南流入長城東。鹹水入之。又東南渾波水注之。又東逕西河富昌縣故城南。又東流入於河。按漢富昌城在鄂爾多斯左翼前旗界。湳水、未審今鄂爾多斯何水也。"}]},"漹":{"expl":"水。出西河中陽北沙，南入河。从水焉聲。","rad":"水","fq":"乙乾切","vol":"11","py":"yān","duan":[{"e":"漹水。出西河中陽北沙。南入河。","n":"北沙、水經注引作之西。西河郡中陽、二志同。戴先生曰。水經。河水、南過西河圁陽縣東。又南過離石縣西。又南過中陽縣西。又南過土軍縣西。據地望考之。中陽西濵河。當在今汾州府寧鄉縣境。趙世家秦取我西都及中陽是也。道元乃云中陽故城在東。東翼汾水。不濵於河也。元和志於孝義縣下云。魏移西河郡中陽於今理。此條可證明水經之中陽其所本之書。道元偶失檢。道元汾水篇注所言鄔澤北起大陵。南接鄔。正今平遙之西、孝義之東、介休之北、最爲洿下。汾川轉徙不常之地。說文之漹水乃入河。非入汾。漢中陽西濱黃河、說文亦一證。道元就漹字與鄔字牽合。謂漹水卽鄔澤。謬矣。玉裁按漹水今未得其證。"}]},"涶":{"expl":"河津也。在西河西。从水𡍮聲。","rad":"水","fq":"土禾切","vol":"11","py":"tuō","duan":[]},"㶛":{"expl":"水也。从水旟聲。","rad":"水","fq":"以諸切","vol":"11","py":"yú","duan":[{"e":"㶛水也。","n":"未詳。"}]},"洵":{"expl":"過水中也。从水旬聲。","rad":"水","fq":"相倫切","vol":"11","py":"xún","duan":[{"e":"濄水出也。","n":"各本誤作過水中也。今正。釋水曰。水自濄出爲洵。大水溢出別爲小水之名也。水經注引字林曰。洵、濄水也。經有假借洵爲均者。如洵直且侯是也。有假爲恂者。如洵美且都、洵訏且樂是也。有假爲敻者、如于嗟洵兮、卽韓詩之于嗟敻兮是也。有假爲泫者。國語無洵涕是也。"}]},"涻":{"expl":"水。出北嚻山，入邙澤。从水舍聲。","rad":"水","fq":"始夜切","vol":"11","py":"shè","duan":[{"e":"涻水。","n":"水名。"}]},"㲽":{"expl":"水也。从水刃聲。","rad":"水","fq":"乃見切","vol":"11","py":"niàn","duan":[{"e":"㲽水也。","n":"集韵、類篇引說文有出上黨三字。又沴㲽與淟涊同。沴涊、溼相箸也。亦垢濁也。"}]},"分":{"expl":"別也。从八从刀，刀以分別物也。","rad":"八","fq":"甫文切","vol":"02","py":"fēn","duan":[{"e":"別也。从八刀。","n":"會意。"}]},"淔":{"expl":"水也。从水直聲。","rad":"水","fq":"恥力切","vol":"11","py":"chì","duan":[{"e":"淔水也。","n":"集韵、類篇曰。出潁川。"}]},"淁":{"expl":"水也。从水妾聲。","rad":"水","fq":"七接切","vol":"11","py":"qiè","duan":[{"e":"淁水也。从水。妾聲。","n":"七接切。八部。"}]},"涺":{"expl":"水也。从水居聲。","rad":"水","fq":"九魚切","vol":"11","py":"jū","duan":[{"e":"涺水也。从水。居聲。","n":"九魚切。五部。"}]},"𣽍":{"expl":"水也。从水臮聲。","rad":"水","fq":"其冀切","vol":"11","py":"jì","duan":[{"e":"𣾄水也。从水。臮聲。","n":"其冀切。十五部。"}]},"沋":{"expl":"水也。从水尤聲。","rad":"水","fq":"羽求切","vol":"11","py":"yóu","duan":[{"e":"沋水也。","n":"廣韵曰。在高密。按葢卽左傳尤水。上文之治水也。"}]},"洇":{"expl":"水也。从水因聲。","rad":"水","fq":"於眞切","vol":"11","py":"yīn","duan":[{"e":"洇水也。从水。因聲。","n":"此字玉篇及小徐皆作涃、困聲。廣韵洇涃竝收。集韵、類篇引說文互異。而今存宋本皆作洇。因聲、於眞切。毛斧季改爲困聲、苦頓切。非是。十一部。"}]},"淉":{"expl":"水也。从水果聲。","rad":"水","fq":"古火切","vol":"11","py":"ɡuǒ","duan":[{"e":"淉水也。从水。果聲。","n":"古火切。十七部。"}]},"溑":{"expl":"水也。从水𧴪聲。讀若瑣。","rad":"水","fq":"穌果切","vol":"11","py":"suǒ","duan":[{"e":"溑水也。从水。𧴪聲。讀若瑣。","n":"穌果切。在十七部。"}]},"浝":{"expl":"水也。从水尨聲。","rad":"水","fq":"莫江切","vol":"11","py":"mánɡ","duan":[{"e":"浝水也。从水。尨聲。","n":"莫江切。九部。"}]},"㳶":{"expl":"水也。从水乳聲。","rad":"水","fq":"乃后切","vol":"11","py":"nǒu","duan":[{"e":"㳶水也。从水。乳聲。","n":"乃后切。四部。或以爲酒醴維醹之醹。"}]},"尒":{"expl":"詞之必然也。从入、|、八。八象气之分散。","rad":"八","fq":"兒氏切","vol":"02","py":"ěr","duan":[{"e":"䛐之必然也。","n":"䛐今作詞。說文字體本作䛐。尒之言如此也。後世多以爾字爲之。凡曰果爾、不爾、云爾、莞爾、鏗爾、卓爾、鼎鼎爾、猶猶爾、聊復爾耳、故人心尚爾皆訓如此。亦有單訓此者。如公羊焉爾之爲於此孟子然而無乎爾、則亦有乎爾是也。語助有用耳者。與爾絶殊。三國志云生女耳是也。耳之言而已也。近人爾耳不分。如論語女得人焉爾乎。唐石經譌爲焉耳。詩陳風箋梅之樹善惡自爾。宋本譌爲善惡自耳。皆是也。古書尒字。淺人多改爲爾。如手部引論語鏗尒、考工記揱尒、小徐本不誤。是也。"}]},"汷":{"expl":"水也。从水夂聲。夂，古文終。","rad":"水","fq":"職戎切","vol":"11","py":"zhōnɡ","duan":[{"e":"⿰氵𠂂水也。","n":"廣韵、集韵皆曰在襄陽。"}]},"洦":{"expl":"淺水也。从水百聲。","rad":"水","fq":"匹白切","vol":"11","py":"pò","duan":[{"e":"淺水也。","n":"顔氏家訓曰。遊趙州。見栢人城北有一小水。土人亦不知名。後讀城西門徐整碑云。洦流東指。案說文此字古泊字也。泊、淺水貌。此水無名。直以淺貌目之。或當卽以洦爲名乎。玉裁按顔書今本譌誤。爲正之、可讀如此。說文作洦。隷作泊。亦古今字也。犬部狛字下云。讀若淺泊。淺水易停。故泊又爲停泊。淺作薄。故泊亦爲厚薄字。又以爲憺怕字。今韵以泊入鐸。以洦入陌。由不知古音耳。但上下文皆水名。此字次第不應在此。葢轉寫者以從百從千類之。"}]},"汘":{"expl":"水也。从水千聲。","rad":"水","fq":"倉先切","vol":"11","py":"qiān","duan":[{"e":"汘水也。从水。千聲。","n":"倉先切。十二部。"}]},"洍":{"expl":"水也。从水𦣞聲。《詩》曰：“江有洍。”","rad":"水","fq":"詳里切","vol":"11","py":"sì","duan":[{"e":"洍水也。从水。𦣞聲。","n":"詳里切。一部。"}]},"澥":{"expl":"郣澥，海之別也。从水解聲。一說：澥即澥谷也。","rad":"水","fq":"胡買切","vol":"11","py":"xiè","duan":[{"e":"勃澥、海之別也。","n":"宋本作郣。今本及集韵、類篇皆作勃。別下宋本、葉本、趙本、五音韵譜、類篇、集韵皆無名字。毛斧季妄增之。然文選注已誤多矣。毛詩傳曰。沱、江之別者也。海之別猶江之別。勃澥屬於海、而非大海。猶沱屬於江、而非大江也。說文或言屬。或言別。言屬而別在其中。言別而屬在其中。此與稗下云禾別正同。周禮注。州黨族閭比者、鄉之屬別。則屬別竝言也。漢書子虛賦音義曰。勃澥、海別枝也。齊都賦注曰。海旁曰勃。斷水曰澥。潛丘箚記曰。今海自山東登州成山折而西。逕寧海州、福山、蓬萊、招遠縣。又西逕萊州、掖縣、昌邑、濰縣。又西逕靑州、壽光、樂安、諸城縣北界。折而西北。逕濟南、利津、霑化、海豐縣。又北逕直隷、河閒、鹽山、滄北、靜海縣東"}]},"漠":{"expl":"北方流沙也。一曰清也。从水莫聲。","rad":"水","fq":"慕各切","vol":"11","py":"mò","duan":[{"e":"北方流沙也。","n":"漢書亦假幕爲漠。"}]},"海":{"expl":"天池也。以納百川者。从水每聲。","rad":"水","fq":"呼改切","vol":"11","py":"hǎi","duan":[{"e":"天池也。","n":"見莊子消搖游。"}]},"溥":{"expl":"大也。从水尃聲。","rad":"水","fq":"滂古切","vol":"11","py":"pǔ","duan":[{"e":"大也。","n":"見釋詁。"}]},"𤃷":{"expl":"水大至也。从水闇聲。","rad":"水","fq":"乙感切","vol":"11","py":"ǎn","duan":[{"e":"水大至也。","n":"水大廣韵作大水。"}]},"洪":{"expl":"洚水也。从水共聲。","rad":"水","fq":"戶工切","vol":"11","py":"hónɡ","duan":[{"e":"洚水也。","n":"堯典、咎繇謨皆言洪水。釋詁曰。洪、大也。引伸之義也。孟子以洪釋洚。許以洚釋洪。是曰轉注。大壑曰谼。字亦作洪。"}]},"禁":{"expl":"吉凶之忌也。从示林聲。","rad":"示","fq":"居蔭切","vol":"01","py":"jìn","duan":[{"e":"吉凶之忌也。","n":"禁忌雙聲。忌古亦讀如記也。曲禮曰。入竟而問禁。"}]},"曾":{"expl":"詞之舒也。从八从曰，𡆧聲。","rad":"八","fq":"昨稜切","vol":"02","py":"zēnɡ","duan":[{"e":"䛐之舒也。","n":"曰部曰。朁曾也。詩朁不畏明胡朁莫懲。毛鄭皆曰。朁、曾也。按曾之言乃也。詩曾是不意、曾是在位、曾是在服、曾是莫聽、論語曾是以爲孝乎、曾謂泰山不如林放乎、孟子爾何曾比予於管仲、皆訓爲乃則合語氣。趙注孟子曰。何曾猶何乃也。是也。是以朁訓爲曾。朁不畏明者、乃不畏明也。皇侃論語疏曰。曾猶嘗也。嘗是以爲孝乎。絶非語氣、葢曾字古訓乃。子登切。後世用爲曾經之義。讀才登切。此今義今音。非古義古音也。至如曾祖、曾孫、取增益層絫之意。則曾層皆可讀矣。"}]},"洚":{"expl":"水不遵道。一曰下也。从水夅聲。","rad":"水","fq":"戶工切","vol":"11","py":"jiànɡ","duan":[{"e":"水不遵道。","n":"孟子滕文公篇。書曰。洚水警予。洚水者、洪水也。吿子篇。水逆行謂之洚水。洚水者、洪水也。水不遵道、正謂逆行。惟其逆行。是以絕大。洚洪二字義實相因。"}]},"衍":{"expl":"水朝宗于海也。从水从行。","rad":"水","fq":"以淺切","vol":"11","py":"yǎn","duan":[{"e":"水朝宗于海皃也。","n":"鉉無皃字。非。海淖之來。旁推曲暢。兩厓渚涘之閒不辨牛馬。故曰衍。引伸爲凡有餘之義。假羨字爲之。"}]},"𣶃":{"expl":"水朝宗于海。从水，朝省。","rad":"水","fq":"直遙切","vol":"11","py":"cháo","duan":[{"e":"水朝宗于海也.","n":"禹貢。荆州、江漢朝宗于海。鄭以周禮春見曰朝。夏見曰宗釋之。古說則謂潮也。論衡書虛篇辨子胥驅水爲濤事曰。天地之性。上古有之。經江漢朝宗于海。唐虞之前也。又曰濤之起也。隨月盛衰。小大、滿損不齊同。虞翻注易習坎有孚曰。水行往來。朝宗于海。不失其時。如月行天。注行險而不失其信曰。水性有常。消息與月相應。皆與許說合。朝宗于海者、謂彼此相迎受。洚水之時。江漢不順軌。不與海通。海𣶃不上。至禹治之。江漢始與海通。於楊州曰。三江旣入。謂江漢之入海也。於荆州曰。江漢朝宗于海。謂海𣶃上達、直至荆州也。江漢之水下赴。海𣶃上迎。呼吸相通。恩禮相受。二州之文相爲表裏。古說如是。朝宗于海、謂海水來朝見尊禮也。"}]},"濥":{"expl":"水脈行地中濥濥也。从水夤聲。","rad":"水","fq":"弋刃切","vol":"11","py":"yǐn","duan":[{"e":"水脈行地中濥濥也。","n":"濥濥、動貌。寅下曰。正月陽氣動。泉欲上出。髕寅於下也。淮南天文訓曰。指寅則萬物螾。注。螾、動生貌。皆其義也。江賦曰。潛演之所汨淈。蜀都賦曰。濥以潛沫。劉注。水潛行曰濥。此二水伏流。故曰濥。按今文選作演。誤。"}]},"滔":{"expl":"水漫漫大皃。从水舀聲。","rad":"水","fq":"土刀切","vol":"11","py":"tāo","duan":[{"e":"水漫漫大皃。","n":"堯典。浩浩滔天。按漫漫當作曼曼。許書無漫字。"}]},"涓":{"expl":"小流也。从水肙聲。《爾雅》曰：“汝爲涓。”","rad":"水","fq":"古玄切","vol":"11","py":"juān","duan":[{"e":"小流也。","n":"凡言涓涓者、皆謂細小之流。"}]},"混":{"expl":"豐流也。从水昆聲。","rad":"水","fq":"胡本切","vol":"11","py":"hùn","duan":[{"e":"豐流也。","n":"盛滿之流也。孟子曰。源泉混混。古音讀如衮。俗字作滚。山海經曰。其源渾渾泡泡。郭云。水濆湧也。衮咆二音。渾渾者、假借渾爲混也。今俗讀戸衮胡困二切。訓爲水濁。訓爲雜亂。此用混爲溷也。說文混、溷義別。"}]},"潒":{"expl":"水潒瀁也。从水象聲。讀若蕩。","rad":"水","fq":"徒朗切","vol":"11","py":"dànɡ","duan":[{"e":"水潒瀁也。","n":"瀁者古文爲漾水字。隸爲潒瀁字。是亦古今字也。潒瀁曡韵字。搖動之流也。今字作蕩漾。"}]},"漦":{"expl":"順流也。一曰水名。从水𠩺聲。","rad":"水","fq":"俟甾切","vol":"11","py":"chí","duan":[{"e":"順流也。","n":"順下之流也。釋言曰。漦、盝也。盝同漉酒之漉。國語、史記龍漦。韋昭曰。漦、龍所吐沫。按龍沫必徐徐漉下。故亦謂之漦。"}]},"汭":{"expl":"水相入也。从水从内，内亦聲。","rad":"水","fq":"而銳切","vol":"11","py":"ruì","duan":[{"e":"水相入皃。","n":"皃各本作也。今依玉篇、廣韵正。上下文皆水皃。則皃字是也。水相入皃者、汭之本義也。周禮職方之汭、卽漢志右扶風汧縣之芮。水名也。大雅之汭、亦作芮。毛云。水厓也。鄭云。汭之言內也。尙書嬀汭、渭汭。某氏釋爲水北。雒汭。某氏釋爲雒入河處。左傳漢汭、渭汭、雒汭、滑汭。杜氏或云水內也、或云水之隈曲曰汭。大意與大雅鄭箋相近。鄭箋之言云者、謂汭卽內也。凡云某之言某、皆𡉈轉注假借閒。"}]},"尚":{"expl":"曾也。庶幾也。从八向聲。","rad":"八","fq":"時亮切","vol":"02","py":"shànɡ","duan":[{"e":"曾也。","n":"尚之䛐亦舒。故釋尚爲曾。曾、重也。尚、上也。皆積絫加高之意。義亦相通也。"}]},"潚":{"expl":"深清也。从水肅聲。","rad":"水","fq":"子叔切","vol":"11","py":"sù","duan":[{"e":"深淸也。","n":"謂深而淸也。中山經曰。灃沅之風交潚湘之浦。水經注湘水篇曰。二妃出入潚湘之浦。潚者、水淸深也。湘中記云。湘川淸照五六丈。下見底石。如摴蒲矢。五色鮮明。是納潚湘之名矣。據善長說、則潚湘者猶云淸湘。其字讀如肅、亦讀如蕭。自景純注中山經云潚水今所𡉈未詳。始別潚湘爲二水。俗又改潚爲瀟。其謬日𠥄矣。詩鄭風。風雨潚潚。毛云。暴疾也。羽獵賦。風廉雲師。吸嚊潚率。二京賦。飛䍐箾。思玄賦。迅猋潚其媵我。義皆與毛傳同。水之淸者多駛。方言云。淸、急也。是則說文、毛傳二義相因。"}]},"演":{"expl":"長流也。一曰水名。从水寅聲。","rad":"水","fq":"以淺切","vol":"11","py":"yǎn","duan":[{"e":"長流也。","n":"演之言引也。故爲長遠之流。周語注曰。水土氣通爲演。引伸之義也。"}]},"渙":{"expl":"流𢿱也。从水奐聲。","rad":"水","fq":"呼貫切","vol":"11","py":"huàn","duan":[{"e":"𢿨流也。","n":"各本作流散。今正。分散之流也。毛詩曰。渙渙、春水盛也。周易曰。風行水上渙。又曰。說而後散之。故受之以渙。渙者、離也。"}]},"泌":{"expl":"俠流也。从水必聲。","rad":"水","fq":"兵媚切","vol":"11","py":"bì","duan":[{"e":"俠流也。","n":"俠者、甹也。三輔謂輕財者爲甹。俠流者、輕快之流。如俠士然。魏都賦李注引作駃流。非善本。陳風。泌之洋洋。毛曰。泌、泉水也。上林賦曰。偪側泌瀄。司馬彪曰。泌瀄、相楔也。邶風。毖彼泉水。毛曰。泉水始出毖然流也。毖卽泌之假借字。"}]},"活":{"expl":"水流聲。从水𠯑聲。","rad":"水","fq":"古活切","vol":"11","py":"ɡuō","duan":[{"e":"流聲也。","n":"衛風。北流𣴠𣴠。毛傳曰。𣴠𣴠、流也。按傳當作流貌。其音戶括切。引伸爲凡不死之稱。邶風不我活兮、孟子民非水火不生活是也。許書當亦本作流貌。淺人妄改竄之耳。"}]},"湝":{"expl":"水流湝湝也。从水皆聲。一曰湝湝，寒也。《詩》曰：“風雨湝湝。”","rad":"水","fq":"古諧切","vol":"11","py":"jiē","duan":[{"e":"水流湝湝也。","n":"小雅。淮、水湝湝。毛曰湝湝、猶上文湯湯也。廣雅曰。湝湝、流也。"}]},"泫":{"expl":"湝流也。从水玄聲。上黨有泫氏縣。","rad":"水","fq":"胡畎切","vol":"11","py":"xuàn","duan":[{"e":"湝流也。","n":"湝當作潛。字之誤也。檀弓曰。孔子泫然流涕。魯語。無洵涕。韋曰。無聲涕出爲洵涕。按洵者、泫之假借字也。文選詩曰。花上露猶泫。"}]},"淲":{"expl":"水流皃。从水，彪省聲。《詩》曰：“淲沱北流。”","rad":"水","fq":"皮彪切","vol":"11","py":"biāo","duan":[{"e":"水流貌。","n":"小雅。滮池北流。毛曰。滮、流貌。"}]},"淢":{"expl":"疾流也。从水或聲。","rad":"水","fq":"子逼切","vol":"11","py":"yù","duan":[{"e":"疾流也。","n":"急疾之流也。江賦。測淢濜溳。是其義也。毛詩。築城伊淢。假借淢爲洫也。"}]},"瀏":{"expl":"流清皃。从水劉聲。《詩》曰：“𤄉其清矣。”","rad":"水","fq":"力久切","vol":"11","py":"liú","duan":[{"e":"流淸貌。","n":"鄭風曰。潧與洧。𤄉其淸矣。毛曰。𤄉、深貌。謂深而淸也。釋名曰。綠𤄉也。荆泉之水、於上視之𤄉然綠色。此似之也。"}]},"㒸":{"expl":"从意也。从八豕聲。","rad":"八","fq":"徐醉切","vol":"02","py":"suì","duan":[{"e":"从意也。","n":"从、相聽也。㒸者、聽从之意。司部曰。䛐者、意内而言外也。凡全書說解。或言䛐。或言意、義或錯見。言从意、則知㒸者从䛐也。言䛐之必然、則知尒者必然意也。隨从字當作㒸。後世皆以遂心為㒸矣。"}]},"𤃴":{"expl":"礙流也。从水薉聲。《詩》云：“施罟𤃴𤃴。”","rad":"水","fq":"呼括切","vol":"11","py":"huò","duan":[{"e":"礙流也。","n":"有礙之流也。衛風。施罛濊濊。毛曰。罛、魚罟。濊濊、施之水中。按施罟而水仍流。故曰礙流。礙流者、言礙而不礙也。韓詩云流貌。與毛許一也。濊又訓多水貌。司馬相如傳。湛恩汪濊。"}]},"滂":{"expl":"沛也。从水㫄聲。","rad":"水","fq":"普郎切","vol":"11","py":"pānɡ","duan":[{"e":"沛也。","n":"小雅曰。俾滂沱矣。"}]},"汪":{"expl":"深廣也。从水王聲。一曰汪，池也。","rad":"水","fq":"烏光切","vol":"11","py":"wānɡ","duan":[{"e":"深廣也。","n":"謂深而又廣也。後漢書。叔度汪汪若千頃陂。江賦。澄澹汪洸。晉語曰。汪是土也。韋云。汪、大貌。"}]},"漻":{"expl":"清深也。从水翏聲。","rad":"水","fq":"洛蕭切","vol":"11","py":"liáo","duan":[{"e":"淸深也。","n":"謂淸而深也。南都賦曰。漻淚淢汩。按李善引韓詩內傳漻、淸貌也。葢鄭風毛作𤄉、韓作漻。許謂二字義別。今文選注內字譌外。"}]},"泚":{"expl":"清也。从水此聲。","rad":"水","fq":"千礼切","vol":"11","py":"cǐ","duan":[{"e":"淸也。","n":"此本義也。今詩新臺有泚。毛曰。泚、鮮明貌。此假泚爲玭也。"}]},"況":{"expl":"寒水也。从水兄聲。","rad":"水","fq":"許訪切","vol":"11","py":"kuànɡ","duan":[{"e":"寒水也。","n":"未得其證。毛詩常棣、桑柔、召旻皆曰。兄、滋也。矢部矤下曰。兄詞也。古矧兄、比兄皆用兄字。後乃用況字。後又改作况、作况（二+兄[左右]）。"}]},"沖":{"expl":"涌搖也。从水、中。讀若動。","rad":"水","fq":"直弓切","vol":"11","py":"chōnɡ","duan":[{"e":"湧繇也。","n":"繇搖古今字。湧、上湧也。搖、旁搖也。小雅曰。攸革沖沖。毛云。沖沖、垂飾貌。此湧搖之義。豳風傳曰。沖沖、鑿冰之意。義亦相近。召南傳曰。忡忡、猶衝衝也。忡與沖聲義皆略同也。凡用沖虛字者、皆盅之假借。老子。道盅而用之。今本作沖是也。尙書沖人。亦空虛無所知之意。"}]},"汎":{"expl":"浮皃。从水凡聲。","rad":"水","fq":"孚梵切","vol":"11","py":"fàn","duan":[{"e":"浮皃。","n":"皃當作也。邶風。汎彼栢舟。毛曰。汎、流貌。廣雅曰。汎汎、氾氾、浮也。"}]},"沄":{"expl":"轉流也。从水云聲。讀若混。","rad":"水","fq":"王分切","vol":"11","py":"yún","duan":[{"e":"轉流也。","n":"回轉之流、沄沄然也。釋言曰。沄、沆也。郭云。水流漭沆。"}]},"浩":{"expl":"澆也。从水告聲。《虞書》曰：“洪水浩浩。”","rad":"水","fq":"胡老切","vol":"11","py":"hào","duan":[{"e":"澆也。","n":"按澆當作沆。字之誤也。澆者、𣵽也.𣵽非浩義。沄浩沆同義。而又雙聲。故三篆相聯。"}]},"詹":{"expl":"多言也。从言从八从厃。","rad":"八","fq":"職廉切","vol":"02","py":"zhān","duan":[{"e":"多言也。","n":"莊子曰。小言詹詹。"}]},"沆":{"expl":"莽沆，大水也。从水亢聲。一曰大澤皃。","rad":"水","fq":"胡朗切","vol":"11","py":"hànɡ","duan":[{"e":"莽沆，","n":"逗。"}]},"泬":{"expl":"水从孔穴疾出也。从水从穴，穴亦聲。","rad":"水","fq":"呼穴切","vol":"11","py":"jué","duan":[{"e":"水從孔穴疾出也。从水穴。","n":"釋水曰。氿泉穴出。按此會意字。其韓詩之回泬、楚辭之泬寥皆假借也。"}]},"濞":{"expl":"水暴至聲。从水鼻聲。","rad":"水","fq":"匹備切","vol":"11","py":"pì","duan":[{"e":"水暴至聲。","n":"上林賦。滂濞沆漑。司馬彪曰。滂濞、水聲也。洞蕭賦。澎濞慷漑。一何壯土。高唐賦。濞洶洶其無聲。按滂濞雙聲。澎與滂同。"}]},"灂":{"expl":"水小聲。从水爵聲。","rad":"水","fq":"士角切","vol":"11","py":"zhuó","duan":[{"e":"水之小聲也。","n":"古書多瀺灂連文。瀺士湛反。灂士卓反。雙聲字。高唐賦。巨石溺溺之瀺灂。注引埤蒼瀺灂、水流聲貌。上林賦。瀺灂霄隊。司馬貞引說文水之小聲也。李善引字林瀺灂、小水聲也。疑說文本有二篆。上云水之小聲也。从水、毚聲。下云瀺灂也。从水、爵聲。全書之例如此。單用灂字者、江賦漰湱澩灂。謂大波相激之聲。"}]},"潝":{"expl":"水疾聲。从水翕聲。","rad":"水","fq":"許及切","vol":"11","py":"xī","duan":[{"e":"水流疾聲。","n":"上林賦。汩㴔漂疾。㴔、郭音許立反。然則卽潝字也。小雅。潝潝訿訿。釋訓云。莫供職也。"}]},"滕":{"expl":"水超涌也。从水朕聲。","rad":"水","fq":"徒登切","vol":"11","py":"ténɡ","duan":[{"e":"水超踊也。","n":"踊依韵會本从足。超、踴皆跳也。跳、躍也。小雅。百川沸騰。毛曰。沸、出。騰、乘也。騰者、滕之假借。玉篇引百川沸滕。周易滕口說。引伸之義。"}]},"潏":{"expl":"涌出也。一曰水中坻，人所爲，爲潏。一曰潏，水名，在京兆杜陵。从水矞聲。","rad":"水","fq":"古穴切","vol":"11","py":"jué","duan":[{"e":"湧出也。","n":"上林賦。潏潏淈淈。李善皆引說文證之。應劭、晉灼注上林賦云。潏、湧出聲也。江賦。潏湟淴泱。南都賦。𣳚滑瀎潏。潛㕎洞出。"}]},"洸":{"expl":"水涌光也。从水从光，光亦聲。《詩》曰：“有洸有潰。”","rad":"水","fq":"古黃切","vol":"11","py":"ɡuānɡ","duan":[{"e":"水涌光也。","n":"江賦曰。澄澹汪洸。又曰。流映揚焆。謂湧而有光也。邶風曰。有洸有潰。毛曰。洸洸、武也。潰潰、怒也。大雅。武夫洸洸。毛曰。洸洸、武貌。此引伸假借之義。"}]},"波":{"expl":"水涌流也。从水皮聲。","rad":"水","fq":"博禾切","vol":"11","py":"bō","duan":[{"e":"水涌流也。","n":"左傳。其波及晉國者。莊子。夫孰能不波。皆引伸之義也。又假借爲陂字。見漢書。"}]},"澐":{"expl":"江水大波謂之澐。从水雲聲。","rad":"水","fq":"王分切","vol":"11","py":"yún","duan":[{"e":"江水大波謂之澐。","n":"專謂江水也。玉裁昔署理四川南谿縣。攷故碑。大江在縣。有揚澐灘。"}]},"介":{"expl":"畫也。从八从人。人各有介。","rad":"八","fq":"古拜切","vol":"02","py":"jiè","duan":[{"e":"畫也。","n":"畫部曰。畫、畍也。按畍也當是本作介也。介與畫互訓。田部畍字葢後人增之耳。介畍古今字。分介則必有閒。故介又訓閒。禮擯介、左傳介人之寵皆其引伸之義也。一則云介特。兩則云閒介。"}]},"瀾":{"expl":"大波爲瀾。从水闌聲。","rad":"水","fq":"洛干切","vol":"11","py":"lán","duan":[{"e":"大波爲瀾。","n":"魏風。河水淸且漣猗。釋水引作灡、云大波爲灡。毛傳云。風行水成文曰漣。按傳下文云。淪、小風水成文。則瀾爲大可知。與爾雅無二義也。凡瀾漫當作此瀾字。"}]},"淪":{"expl":"小波爲淪。从水侖聲。《詩》曰：“河水清且淪漪。”一曰没也。","rad":"水","fq":"力迍切","vol":"11","py":"lún","duan":[{"e":"小波爲淪。","n":"魏風。河水淸且淪猗。釋水曰。小波爲淪。毛傳曰。小風水成文。轉如輪也。韓詩曰。從流而風曰淪。釋名曰。淪、倫也。水文相次、有倫理也。"}]},"漂":{"expl":"浮也。从水票聲。","rad":"水","fq":"匹消切","vol":"11","py":"piāo","duan":[{"e":"浮也。","n":"謂浮於水也。鄭風。風其漂女。毛曰。漂猶吹也。按上章言吹。因吹而浮、故曰猶吹。凡言猶之例視此。漂潎、水中擊絮也。莊子曰洴澼。"}]},"浮":{"expl":"氾也。从水孚聲。","rad":"水","fq":"縛牟切","vol":"11","py":"fú","duan":[{"e":"汎也。","n":"各本汎作氾。今正。木華海賦。浮天無岸。李注引說文浮、汎也。按上文云汎、浮也。是汎浮二字互訓、與氾濫二字互訓義別。汎浮二篆當類廁。今本多非許之舊。"}]},"濫":{"expl":"氾也。从水監聲。一曰濡上及下也。《詩》曰：“𧥑沸濫泉。”一曰清也。","rad":"水","fq":"盧瞰切","vol":"11","py":"làn","duan":[{"e":"氾也。","n":"謂廣延也。商頌、左傳皆云。賞不僭。㓝不濫。魯語。濫於泗淵。皆其引伸之義。"}]},"氾":{"expl":"濫也。从水㔾聲。","rad":"水","fq":"孚梵切","vol":"11","py":"fàn","duan":[{"e":"濫也。","n":"玄應引此下有謂普博也四字。楚辭卜居。將氾氾若水中之鳬乎。王逸云。氾氾、普愛衆也。若水中之鳬、羣戲遊也。論語。汎愛衆。此假汎爲氾。"}]},"泓":{"expl":"下深皃。从水弘聲。","rad":"水","fq":"烏宏切","vol":"11","py":"hónɡ","duan":[{"e":"下深貌。","n":"下深謂其上似淺陿、其下深廣也。楊子。其中宏深。其外肅括。月令。其器閎。鄭云。閎謂中寬。象土含物。泓之義略同。"}]},"湋":{"expl":"回也。从水韋聲。","rad":"水","fq":"羽非切","vol":"11","py":"wéi","duan":[{"e":"回也。","n":"以曡韵爲訓。"}]},"測":{"expl":"深所至也。从水則聲。","rad":"水","fq":"初側切","vol":"11","py":"cè","duan":[{"e":"深所至也。","n":"深所至謂之測。度其深所至亦謂之測。猶不淺曰深。度深亦曰深也。今則引伸之義行而本義隱矣。呂覽。昏乎其深而不測。高云。測、盡也。此本義也。考工記。桼欲測。鄭云。測猶淸也。此引伸之義也。"}]},"湍":{"expl":"疾瀨也。从水耑聲。","rad":"水","fq":"他耑切","vol":"11","py":"tuān","duan":[{"e":"疾瀨也。","n":"瀨、水流沙上也。疾瀨、瀨之急者也。趙注孟子曰。湍者、圜也。謂湍湍縈水也。趙語爲下文決東決西張本。"}]},"𠔁":{"expl":"分也。从重八。八，別也。亦聲。《孝經說》曰：“故上下有別。”","rad":"八","fq":"兵列切","vol":"02","py":"bié","duan":[{"e":"分也。","n":"此卽今之兆字也。廣韵兆治小切。引說文分也。此可證孫愐以前𠔁卽兆矣。又云。𠧞、灼龜坼也。出文字指歸。文字指歸者曹憲所作。此可證孫愐以前卜部無兆𠧞字矣。顧野王玉篇八部有？。兵列切。卜部之後出兆部。又云。𠧞同兆。此可證顧氏始不謂？卽兆字矣。虞翻說尙書分北三苗云。北、古別字。不知其所本。要與重八之？無涉。豈希馮始牽合而岐誤與。治說文者乃於卜部增𠧞爲小篆。兆爲古文。於？下增之云。八別也、亦聲。兵列切。以證其非兆字。而說文之面目全非矣。？从重八者、分之甚也。龜兆其一也。凡言朕兆者、如舟之縫。如龜之坼。"}]},"淙":{"expl":"水聲也。从水宗聲。","rad":"水","fq":"藏宗切","vol":"11","py":"cónɡ","duan":[{"e":"水聲也。","n":"水聲淙淙然。"}]},"激":{"expl":"水礙衺疾波也。从水敫聲。一曰半遮也。","rad":"水","fq":"古歴切","vol":"11","py":"jī","duan":[{"e":"水礙衺疾波也。","n":"當依衆經音義作水流礙邪急曰激也。水流不礙則不衺行。不衺行則不疾急。孟子。激而行之。可使在山。賈子曰。水激則旱兮。矢激則遠。"}]},"洞":{"expl":"疾流也。从水同聲。","rad":"水","fq":"徒弄切","vol":"11","py":"dònɡ","duan":[{"e":"疾流也。","n":"此與辵部迵。馬部駧音義同。引伸爲洞達、爲洞壑。"}]},"𤄫":{"expl":"大波也。从水旛聲。","rad":"水","fq":"孚袁切","vol":"11","py":"fān","duan":[{"e":"大波也。从水。旛聲。","n":"孚袁切。十四部。"}]},"洶":{"expl":"涌也。从水匈聲。","rad":"水","fq":"許拱切","vol":"11","py":"xiōnɡ","duan":[{"e":"洶洶涌也。","n":"各本無洶洶字。今依高唐賦注補。相如賦曰。洶涌滂㵒。左思賦曰。濞焉洶洶。楊雄賦曰。洶洶旭旭。天動地岋。"}]},"涌":{"expl":"滕也。从水甬聲。一曰涌水，在楚國。","rad":"水","fq":"余隴切","vol":"11","py":"yǒnɡ","duan":[{"e":"滕也。","n":"滕、水超踊也。二篆宜相連。今本葢非古也。"}]},"湁":{"expl":"湁湒，𩰾也。从水拾聲。","rad":"水","fq":"丑入切","vol":"11","py":"chì","duan":[{"e":"湁湒、","n":"逗。"}]},"涳":{"expl":"直流也。从水空聲。","rad":"水","fq":"苦江切","vol":"11","py":"kōnɡ","duan":[{"e":"直流也。从水。空聲。","n":"哭江切。又苦江切。九部。"}]},"汋":{"expl":"激水聲也。从水勺聲。井一有水、一無水，謂之瀱汋。","rad":"水","fq":"市若切","vol":"11","py":"zhuó","duan":[{"e":"激水聲也。从水。勺聲。","n":"市若切。古音𡉈二部。釋名。汋、澤也。有潤澤也。自臍以下曰水腹。水汋所聚也。胞主以虛承汋也。葢皆借爲液字。又楚詞灼約、卽莊子淖約。"}]},"瀱":{"expl":"井一有水、一無水，謂之瀱汋。从水罽聲。","rad":"水","fq":"居例切","vol":"11","py":"jì","duan":[{"e":"井一有水、一無水。謂之瀱汋也。从水。罽聲。","n":"居例切。十五部。按釋水文已見上文此但云瀱汋也已足。不當複舉。攷釋名作罽、不从水。說文當同之。瀱篆乃淺人所增耳。爾雅作瀱、亦非古本。罽訓竭。於音得之。"}]},"公":{"expl":"平分也。从八从厶。(音司。)八猶背也。韓非曰：背厶爲公。","rad":"八","fq":"古紅切","vol":"02","py":"ɡōnɡ","duan":[{"e":"平分也。从八厶。","n":"八厶、背私也。今本从八从厶。凡此等从字皆淺人所增。"}]},"渾":{"expl":"混流聲也。从水軍聲。一曰洿下皃。","rad":"水","fq":"戶昆切","vol":"11","py":"hún","duan":[{"e":"溷流聲也。","n":"溷作混者誤。溷、亂也。酈善長謂二水合流爲渾濤。今人謂水濁爲渾。"}]},"洌":{"expl":"水清也。从水列聲。《易》曰：“井𣸟，寒泉，食。”","rad":"水","fq":"良辥切","vol":"11","py":"liè","duan":[{"e":"水淸也。","n":"案許書有洌冽二篆。毛詩有冽無洌。冽彼下泉傳云。冽、寒也。有冽氿泉傳云。冽、寒意。二之日凓冽傳云。凓冽、寒氣也。皆不从水。東京賦。玄泉洌淸。薛曰。洌、淸澄皃。"}]},"淑":{"expl":"清湛也。从水叔聲。","rad":"水","fq":"殊六切","vol":"11","py":"shū","duan":[{"e":"淸湛也。","n":"湛、𣳚也。湛沈古今字。今俗云深沈是也。釋詁曰。淑善也。此引伸之義。"}]},"溶":{"expl":"水盛也。从水容聲。","rad":"水","fq":"余隴切","vol":"11","py":"yǒnɡ","duan":[{"e":"水盛也。","n":"甘泉賦。溶方皇於西淸。善曰。溶、盛皃也。按今人謂水盛曰溶溶。"}]},"澂":{"expl":"清也。从水，徵省聲。","rad":"水","fq":"直陵切","vol":"11","py":"chénɡ","duan":[{"e":"淸也。","n":"澂之言持也。持之而後淸。方言曰。澂、淸也。澂澄古今字。禮運。澄酒𡉈下。字作澄。鄭云。澄酒與周禮沈齊字雖異。葢同物也。周易。君子以徵忿。徵者、澂之假借字。蜀才作登。鄭云。徵猶淸也。必云猶者、正謂澂不訓淸。澂之斯淸。故王弼訓止也。"}]},"清":{"expl":"朖也。澂水之皃。从水青聲。","rad":"水","fq":"七情切","vol":"11","py":"qīnɡ","duan":[{"e":"朖也。澂水之皃。","n":"朖者、明也。澂而後明。故云澂水之皃。引伸之、凡潔曰淸。凡人潔之亦曰淸。同瀞。"}]},"湜":{"expl":"水清底見也。从水是聲。《詩》曰：“湜湜其止。”","rad":"水","fq":"常職切","vol":"11","py":"shí","duan":[{"e":"水淸見底也。","n":"各本作底見。依詩釋文正。邶風曰。涇以渭濁。湜湜其止。毛云。涇渭相入而淸濁異。按毛本作止。鄭乃作沚。毛意涇以入渭而形己濁。且以己形渭之湜湜然淸澂。喻君子以新昏而不潔己。且以己而益見新昏之可安。止者、水之澂定也。鄭易止爲沚。云小渚曰沚。湜湜、持正皃。喻君子得新昏。故謂己惡。己之持正守初。如沚然不動搖。是其訓湜字、比傅是字之解爲之。非水淸見底之謂矣。"}]},"潣":{"expl":"水流浼浼皃。从水閔聲。","rad":"水","fq":"眉殞切","vol":"11","py":"mǐn","duan":[{"e":"水流浼浼皃。","n":"浼浼當作潣潣。淺人所改也。一說潣浼古今字。故以浼浼釋潣潣。河水浼浼。見邶風。浼之本義訓污。邶風之浼浼卽潣潣之假借。免聲古讀如門。與潣音近。毛傳曰。浼浼、平地也。卽潣潣之義也。"}]},"滲":{"expl":"下漉也。从水參聲。","rad":"水","fq":"所禁切","vol":"11","py":"shèn","duan":[{"e":"下漉也。","n":"司馬相如封禪文。滋液滲漉。楊雄河東賦。澤滲灕而下降。今俗云滲屚。"}]},"潿":{"expl":"不流濁也。从水圍聲。","rad":"水","fq":"羽非切","vol":"11","py":"wéi","duan":[{"e":"不流濁也。","n":"謂薉濁不流去也。左傳曰。有汾澮以流其惡。"}]},"必":{"expl":"分極也。从八、弋，弋亦聲。","rad":"八","fq":"卑吉切","vol":"02","py":"bì","duan":[{"e":"分極也。","n":"極猶凖也。木部棟極二字互訓。橦字下云。帪極也。凡高處謂之極。立表爲分判之準。故云分極。引伸爲䛐之必然。"}]},"溷":{"expl":"亂也。一曰水濁皃。从水圂聲。","rad":"水","fq":"胡困切","vol":"11","py":"hùn","duan":[{"e":"亂也。","n":"離騷。世溷濁而不分兮。王曰。溷、亂也。濁、貪也。"}]},"淈":{"expl":"濁也。从水屈聲。一曰滒泥。一曰水出皃。","rad":"水","fq":"古忽切","vol":"11","py":"ɡǔ","duan":[{"e":"濁也。","n":"今人汩亂字當作此。按洪範汩陳其五行。某氏曰。汩、亂也。書序汩作。汩、治也。屈賦汩鴻。謂治洪水。治亂正一義。卽釋詁之淈、治也。某氏注爾雅引詩淈此羣醜。其勿反。"}]},"㳬":{"expl":"回泉也。从水，旋省聲。","rad":"水","fq":"似沿切","vol":"11","py":"xuán","duan":[{"e":"回泉也。","n":"杜詩。撇漩捎濆無險阻。漩、夔州土人讀去聲。謂峽中回流大者。其深不測。舟遇之則旋轉而入。江賦所謂盤渦谷轉也。濆、上人讀如瀵。謂峽中回流漸平。則突湧如山。江賦所謂渨㵽濆瀑也。斯二者必撇之捎之而行。不可正犯。杜用峽中語言入詩。"}]},"漼":{"expl":"深也。从水崔聲。《詩》曰：“有漼者淵。”","rad":"水","fq":"七罪切","vol":"11","py":"cuǐ","duan":[{"e":"深也。","n":"小雅。有漼者淵。毛傳曰。漼、深皃。"}]},"淵":{"expl":"回水也。从水，象形。左右，岸也。中象水皃。","rad":"水","fq":"烏玄切","vol":"11","py":"yuān","duan":[{"e":"回水也。","n":"顏回字子淵。"}]},"濔":{"expl":"滿也。从水爾聲。","rad":"水","fq":"奴礼切","vol":"11","py":"mǐ","duan":[{"e":"水滿也。","n":"依詩釋文補水字。邶風曰。河水瀰瀰。毛云。瀰瀰、盛貌。玉篇曰。𣴱亦瀰字。按盧氏文弨曰。漢地理志邶詩云河水𣴱𣴱。字从𦍋姓爲聲。謂新臺也。俗譌爲洋洋。師古謂邶無此句。"}]},"澹":{"expl":"水搖也。从水詹聲。","rad":"水","fq":"徒濫切","vol":"11","py":"dàn","duan":[{"e":"澹澹水繇皃也。","n":"東京賦注、高唐賦注引皆有澹澹字。皃字亦依東京賦注補。高唐賦曰。水澹澹而盤紆。東京賦曰。淥水澹澹。俗借爲淡泊字。繇當作搖。"}]},"潯":{"expl":"㫄深也。从水尋聲。","rad":"水","fq":"徐林切","vol":"11","py":"xún","duan":[{"e":"旁深也。","n":"今人用此字、取義於旁而已。"}]},"泙":{"expl":"谷也。从水平聲。","rad":"水","fq":"符兵切","vol":"11","py":"pínɡ","duan":[{"e":"谷也。","n":"廣韵曰。水名。三篇曰。谷名。"}]},"泏":{"expl":"水皃。从水出聲。讀若窋。","rad":"水","fq":"竹律切","vol":"11","py":"zhú","duan":[{"e":"水兒。","n":"廣韵曰。水出皃。文子曰。原流泏泏。沖而不盈。"}]},"余":{"expl":"語之舒也。从八，舍省聲。","rad":"八","fq":"以諸切","vol":"02","py":"yú","duan":[{"e":"語之舒也。","n":"語、匡謬正俗引作䛐。左氏傳。小白余敢貪天子之命。無下拜。此正䛐之舒。亏部曰。亏、於也。象气之舒亏。然則余亏異字而同音義。釋詁云。余、我也。余、身也。孫炎曰。余舒遟之身也。然則余之引伸訓爲我。詩書用予不用余。左傳用余不用予。曲禮下篇。朝諸矦分職授政任功。曰予一人。注云。覲禮曰伯父寔來。余一人嘉之。余予古今字。凡言古今字者、主謂同音、而古用彼今用此異字。若禮經古文用余一人。禮記用予一人。余予本異字異義。非謂予余本卽一字也。顏師古匡謬正俗不達斯恉。且又以予上聲余平聲爲分別。又不知古音平上不甚區分。重悂貤繆。儀禮漢讀攷糾之詳矣。"}]},"瀳":{"expl":"水至也。从水薦聲。讀若尊。","rad":"水","fq":"","vol":"11","py":"jiàn","duan":[{"e":"水至也。","n":"至疑去作巟。巟、大也。廣韵曰。水荒曰洊。洊者、瀳之異文。周易曰。水洊至、習坎。洊雷震。釋言。荐、再也。荐同洊。"}]},"𤁰":{"expl":"土得水沮也。从水𥏼聲。讀若䵂。","rad":"水","fq":"竹隻切","vol":"11","py":"zhí","duan":[{"e":"土得水沮也。","n":"魏風毛詩云。沮洳、其漸洳者。衆經音義引倉頡篇云。沮者、漸也。許君沮字下未舉此義。今俗謂水稍稍侵物入其內曰𤂥。當作此字。"}]},"滿":{"expl":"盈溢也。从水㒼聲。","rad":"水","fq":"莫旱切","vol":"11","py":"mǎn","duan":[{"e":"盈溢也。从水。㒼聲。","n":"莫旱切。十四部。"}]},"滑":{"expl":"利也。从水骨聲。","rad":"水","fq":"戶八切","vol":"11","py":"huá","duan":[{"e":"利也。","n":"古多借爲汩亂之汩。"}]},"濇":{"expl":"不滑也。从水嗇聲。","rad":"水","fq":"色立切","vol":"11","py":"sè","duan":[{"e":"不滑也。","n":"止部曰。歰、不滑也。然則二字雙聲同義。七發。邪氣襲逆。中若結轖。此假轖爲濇也。"}]},"澤":{"expl":"光潤也。从水睪聲。","rad":"水","fq":"丈伯切","vol":"11","py":"zé","duan":[{"e":"光潤也。","n":"又水艸交厝曰澤。又借爲釋字。"}]},"淫":{"expl":"侵淫隨理也。从水㸒聲。一曰久雨爲淫。","rad":"水","fq":"余箴切","vol":"11","py":"yín","duan":[{"e":"浸淫隨理也。","n":"浸淫者、以漸而入也。司馬相如難蜀父老曰。六合之內。八方之外。浸淫衍溢。史記作浸潯。"}]},"瀸":{"expl":"漬也。从水韱聲。《爾雅》曰：“泉一見一否爲瀸。”","rad":"水","fq":"子廉切","vol":"11","py":"jiān","duan":[{"e":"漬也。","n":"公羊傳莊十七年。齊人瀸于遂。瀸者何。瀸、積也。衆殺戍者也。積本又作漬。何曰。積死非一之辭。按傳文及說文皆當作積爲長。許云漬、漚也。瀸篆不與漬篆聯。可以知許說矣。"}]},"泆":{"expl":"水所蕩泆也。从水失聲。","rad":"水","fq":"夷質切","vol":"11","py":"yì","duan":[{"e":"水所蕩泆也。","n":"蕩泆者、動盪奔突而出。禹貢。道沇水入于河。泆爲熒。本作泆。周禮疏、師古漢書注所引不誤。且史記、水經注皆作泆。惟漢地理志作軼。軼、車相出也。正與泆義同。左傳。彼徒我車。懼其侵軼我。又曰。迭我殽地。迭卽泆軼之假借也。凡言淫泆者、皆謂太過。其引伸之義也。衛包改禹貢之泆爲溢。淺人以滿釋之。固可歎矣。"}]},"潰":{"expl":"漏也。从水貴聲。","rad":"水","fq":"胡對切","vol":"11","py":"kuì","duan":[{"e":"漏也。","n":"漏當作屚。屋穿水下也。左傳。凡民逃其上曰潰。此引伸之義。小雅、大雅毛傳皆曰。潰、遂也。此皆謂假潰爲遂。"}]},"釆":{"expl":"辨別也。象獸指爪分別也。凡釆之屬皆从釆。讀若辨。","rad":"釆","fq":"蒲莧切","vol":"02","py":"biàn","duan":[{"e":"辨別也。象獸指爪分別也。","n":"倉頡見鳥獸蹏迒之迹。知文理之可相別異也。遂造書契。釆字取獸指爪分別之形。"}]},"沴":{"expl":"水不利也。从水㐱聲。《五行傳》曰：“若其沴作。”","rad":"水","fq":"郎計切","vol":"11","py":"lì","duan":[{"e":"水不利也。","n":"河東賦。秦神下讋。跖魂負沴。服虔曰。沴、河岸之坻也。晉灼申之曰。沴、渚也。按坻礙水。令水不行。故謂之沴。"}]},"淺":{"expl":"不深也。从水戔聲。","rad":"水","fq":"七衍切","vol":"11","py":"qiǎn","duan":[{"e":"不深也。","n":"許於深下但云水名。不云不淺。而測下淺下𥥍下可以補足其義。是亦一例。按不深曰淺。不廣亦曰淺。故考工記曰。以博爲帴。帴者、淺之假借。又馬、鄭古文尚書夤淺納日。馬云。淺、滅也。馬意讀爲戩滅之戩。謂伺日入也。"}]},"洔":{"expl":"水暫益且止，未減也。从水寺聲。","rad":"水","fq":"直里切","vol":"11","py":"zhǐ","duan":[{"e":"水暫益且止未減也。","n":"此義未見。葢與待偫峙字義相近。爾雅釋水亦借爲沚字。"}]},"渻":{"expl":"少減也。一曰水門。又，水出丘前謂之渻丘。从水省聲。","rad":"水","fq":"息并切","vol":"11","py":"shěnɡ","duan":[{"e":"少減也。","n":"今減省之字當作渻。古今字也。女部又曰。𡞞者、減也。𡞞渻音義皆同。左傳有渻竈、人姓名也。"}]},"淖":{"expl":"泥也。从水卓聲。","rad":"水","fq":"奴教切","vol":"11","py":"nào","duan":[{"e":"泥也。","n":"左傳曰。有淖於前。乃皆左右相違於淖。杜注同。倉頡篇云。深泥也。字林云。濡甚曰淖。按泥淖以土與水合和爲之。故淖引伸之義訓和。儀禮。嘉薦暜淖。注曰。暜淖、黍稷也。暜、大淖、和也。德能大和、乃有黍稷也。劉瓛述張禹之義曰。仲者、中也。尼者、和也。言孔子有中和之德。故曰仲尼。葢漢人尼與泥通用。故漢碑仲尼字或作泥。又按許泥爲水名。不箸塗泥之解。於此補見。是與深同例也。魏晉以後。泥淖字作埿。"}]},"濢":{"expl":"小溼也。从水翠聲。","rad":"水","fq":"遵誄切","vol":"11","py":"zuǐ","duan":[{"e":"小溼也。","n":"小葢下之誤。篇、韵皆云下溼。從古本也。"}]},"溽":{"expl":"溼暑也。从水辱聲。","rad":"水","fq":"而蜀切","vol":"11","py":"rù","duan":[{"e":"溽暑、溼暑也。","n":"溽暑二字依李善注悼亡詩補。月令。季夏、土潤褥暑。鄭曰。潤褥、謂塗溼也。潤褥雙聲字。記言土塗溼而暑上烝也。塗讀如雨雪載塗之塗。許以溼暑釋記溽暑。後人妄𠜂。非是。大雅雲漢傳曰。蕰蕰而暑。隆隆而雷。蟲蟲而𤍽。此暑𤍽之別。暑言下溼。𤍽言上燥也。謂之溽者、濃也。厚也。儒行注曰。恣滋味爲溽。月令溽本或作辱。"}]},"涅":{"expl":"黑土在水中也。从水从土，日聲。","rad":"水","fq":"奴結切","vol":"11","py":"niè","duan":[{"e":"黑土𡉈水中者也。","n":"者字依論語釋文補。論語孔注。涅可以染皁者。按水部曰。澱者、滓垽也。滓者、澱也。土部曰。垽者、澱也。黑部曰。𪑩謂之垽。垽、滓也。皆與涅義近。"}]},"滋":{"expl":"益也。从水兹聲。一曰滋水，出牛飲山白陘谷，東入呼沱。","rad":"水","fq":"子之切","vol":"11","py":"zī","duan":[{"e":"益也。","n":"艸部茲下曰。艸木多益也。此字从水茲。爲水益也。凡經傳增益之義多用此字。亦有用茲者。如常棣、召旻傳云。兄、茲也。桑柔傳云。兄、茲也。衹是一義。"}]},"㳷":{"expl":"青黑色。从水曶聲。","rad":"水","fq":"呼骨切","vol":"11","py":"hū","duan":[{"e":"靑黑皃。","n":"皃字依廣韵訂。"}]},"禫":{"expl":"除服祭也。从示覃聲。","rad":"示","fq":"徒感切","vol":"01","py":"dàn","duan":[{"e":"除服祭也。","n":"士虞禮記曰。中月而禫。注。中猶閒也。禫、祭名也。與大祥閒一月。自喪至此凡二十七月。禫之言澹。澹然平安意也。"}]},"番":{"expl":"獸足謂之番。从釆；田，象其掌。","rad":"釆","fq":"附袁切","vol":"02","py":"fán","duan":[{"e":"獸足謂之番。从釆、田象其掌。","n":"下象掌。上象指爪。是爲象形。許意先有釆字。乃後从釆而象其形。則非獨體之象形、而爲合體之象形也。附袁切。十四部。"}]},"浥":{"expl":"溼也。从水邑聲。","rad":"水","fq":"於及切","vol":"11","py":"yì","duan":[{"e":"溼也。","n":"召南毛傳曰。厭浥、溼意也。"}]},"沙":{"expl":"水𢿱石也。从水从少。水少沙見。楚東有沙水。","rad":"水","fq":"所加切","vol":"11","py":"shā","duan":[{"e":"水𢿱石也。","n":"詩正義作水中散石。非是。水經注引與今本同。凡古人所引古書有是有非。不容偏信。大雅傳云。沙水旁也。許云。水散石。與毛不異。石散碎謂之沙。引伸之、凡生澁皆爲沙。如內則鳥沙鳴是。"}]},"瀨":{"expl":"水流沙上也。从水賴聲。","rad":"水","fq":"洛帶切","vol":"11","py":"lài","duan":[{"e":"水流沙上也。","n":"九歌。石瀨兮淺淺。伍子胥書有下瀨船。漢有下瀨將軍。應劭漢書注曰。瀨、水流沙上也。臣瓚曰。瀨、湍也。吳越謂之瀨。中國謂之磧。按瀨之言𤃀也。水在沙上、渧𤃀而下滲也。埤倉云。渧𤃀、漉也。"}]},"濆":{"expl":"水厓也。从水賁聲。《詩》曰：“敦彼淮濆。”","rad":"水","fq":"符分切","vol":"11","py":"fén","duan":[{"e":"水厓也。","n":"詩大雅。鋪敦淮濆。傳曰。濆、厓也。周南。遵彼汝墳。傳曰。墳、大防也。畫然分別。周禮大司徒職。丘陵墳衍原隰。注曰。水涯曰墳。而常武箋亦釋濆爲大防。是鄭謂古經假借通用也。許則謹守毛傳。"}]},"涘":{"expl":"水厓也。从水矣聲。《周書》曰：“王出涘。”","rad":"水","fq":"牀史切","vol":"11","py":"sì","duan":[{"e":"水厓也。","n":"爾雅釋丘、王風秦風傳皆曰。涘、厓也。"}]},"汻":{"expl":"水厓也。从水午聲。","rad":"水","fq":"呼古切","vol":"11","py":"hǔ","duan":[{"e":"水厓也。","n":"大雅。率西水滸。傳曰。滸、水厓也。釋丘曰。岸上、滸。"}]},"氿":{"expl":"水厓枯土也。从水九聲。《爾雅》曰：“水醮曰氿。”","rad":"水","fq":"居洧切","vol":"11","py":"ɡuǐ","duan":[{"e":"水厓枯土也。","n":"按今爾雅水醮曰厬。仄出泉曰氿。許書仄出泉曰厬。水厓枯土曰氿。與今爾雅正互易。依毛詩有冽氿泉。似今爾雅不誤也。"}]},"漘":{"expl":"水厓也。从水脣聲。《詩》曰：“寘河之漘。”","rad":"水","fq":"常倫切","vol":"11","py":"chún","duan":[{"e":"水厓也。","n":"魏風傳。漘、厓也。爾雅曰。厓、夷上洒下漘。按互夷上平也。洒下謂側水邊者斗峭。"}]},"浦":{"expl":"瀕也。从水甫聲。","rad":"水","fq":"滂古切","vol":"11","py":"pǔ","duan":[{"e":"水瀕也。","n":"瀕下曰水厓、人所賓附也。大雅。率彼淮浦。傳曰。浦、厓也。"}]},"沚":{"expl":"小渚曰沚。从水止聲。《詩》曰：“于沼于沚。”","rad":"水","fq":"諸市切","vol":"11","py":"zhǐ","duan":[{"e":"小渚曰沚。","n":"召南傳曰。沚、渚也。此渾言之。秦風傳、爾雅釋水曰。小渚曰沚。此析言之也。"}]},"宷":{"expl":"悉也。知宷諦也。从宀从釆。徐锴曰：“宀，覆也。釆，别也。包覆而深别之。宷，悉也。”","rad":"釆","fq":"式荏切","vol":"02","py":"shěn","duan":[{"e":"悉也。知寀諦也。","n":"諦廣韵引作諟。古同部假借也。"}]},"沸":{"expl":"滭沸，濫泉。从水弗聲。","rad":"水","fq":"分勿切","vol":"11","py":"fèi","duan":[{"e":"畢沸、","n":"逗。"}]},"潨":{"expl":"小水入大水曰潨。从水从眾。《詩》曰：“鳧鷖在潨。”","rad":"水","fq":"徂紅切","vol":"11","py":"cónɡ","duan":[{"e":"小水入大水曰潀。","n":"大雅傳曰。潀、水會也。按許說申毛。若鄭箋云潀、水外之高者也。有瘞埋之象。則謂潀與崇同。恐非詩意。"}]},"派":{"expl":"別水也。从水从𠂢，𠂢亦聲。","rad":"水","fq":"匹賣切","vol":"11","py":"pài","duan":[{"e":"別水也。","n":"吳都賦。百川派別。劉逵注引字說曰。水別流爲派。"}]},"汜":{"expl":"水別復入水也。一曰汜，窮瀆也。从水巳聲。《詩》曰：“江有汜。”","rad":"水","fq":"詳里切","vol":"11","py":"sì","duan":[{"e":"水別復入水也。","n":"上水字衍文。召南傳曰。決復入水也。謂旣決而復入之水也。自其水出而不復入者、釋水自河出爲灉已下是也。決而復入者、汜是也。釋名曰。汜、巳也。如出有所爲畢巳而復入也。按古以無巳釋巳。如祀之解曰祭無巳是也。故汜之字从巳。"}]},"湀":{"expl":"湀辟，深水處也。从水癸聲。","rad":"水","fq":"求癸切","vol":"11","py":"ɡuǐ","duan":[{"e":"湀辟、","n":"逗。"}]},"濘":{"expl":"滎濘也。从水寕聲。","rad":"水","fq":"乃定切","vol":"11","py":"nìnɡ","duan":[{"e":"滎濘也。从水。寧聲。","n":"乃定切。十一部。按濴濘曡韵。此當依七命注奴泠切。後人謂淖爲泥濘。讀乃定切。義與音皆非古矣。"}]},"滎":{"expl":"絕小水也。从水，熒省聲。","rad":"水","fq":"戶扃切","vol":"11","py":"xínɡ","duan":[{"e":"滎濘、","n":"逗。"}]},"洼":{"expl":"深池也。从水圭聲。","rad":"水","fq":"一佳切","vol":"11","py":"wā","duan":[{"e":"深池也。","n":"史漢皆云得神馬渥洼水中。莊子齊物論云似洼者。"}]},"漥":{"expl":"清水也。一曰窊也。从水窐聲。","rad":"水","fq":"一穎切","vol":"11","py":"yǐnɡ","duan":[{"e":"淸水也。","n":"未詳。"}]},"潢":{"expl":"積水池。从水黃聲。","rad":"水","fq":"乎光切","vol":"11","py":"huánɡ","duan":[{"e":"積水池也。","n":"左傳。潢污行潦之水。服虔曰。畜小水謂之潢。水不流謂之污。行潦、道路之水。"}]},"悉":{"expl":"詳盡也。从心从釆。","rad":"釆","fq":"息七切","vol":"02","py":"xī","duan":[{"e":"詳盡也。从心釆。","n":"會意。息七切。十二部。"}]},"沼":{"expl":"池水。从水召聲。","rad":"水","fq":"之少切","vol":"11","py":"zhǎo","duan":[{"e":"池也。","n":"召南傳曰。沼、池也。張揖廣雅同。按衆經音義兩引作小池也。"}]},"湖":{"expl":"大陂也。从水胡聲。揚州浸，有五湖。浸，川澤所仰以灌漑也。","rad":"水","fq":"戶吳切","vol":"11","py":"hú","duan":[{"e":"大陂也。","n":"𨸏部曰。陂、一曰池也。然則大陂謂大池也。古言鴻隙大陂、言汪汪若千頃陂皆謂大池也。池以鍾水。湖特鍾水之大者耳。"}]},"汥":{"expl":"水都也。从水支聲。","rad":"水","fq":"章移切","vol":"11","py":"zhī","duan":[{"e":"水都也。","n":"水都者、水所聚也。民所聚曰都。汥之證未詳。"}]},"洫":{"expl":"十里爲成。成閒廣八尺、深八尺謂之洫。从水血聲。《論語》曰：“盡力于溝洫。”","rad":"水","fq":"況逼切","vol":"11","py":"xù","duan":[{"e":"十里爲成。成閒廣八尺、深八尺謂之洫。","n":"考工記匠人文也。匠人溝洫之制、惟歙程氏瑤田通藝錄能發明之。洫亦作淢。韓詩築城伊洫。毛詩作淢。傳曰。淢、成溝也。箋云。方十里曰成。淢其溝也。按門閥之字、古文作𨵨。是或與血異部而音通也。溝洫對文則異。散文則通。故毛曰成溝。"}]},"溝":{"expl":"水瀆。廣四尺、深四尺。从水冓聲。","rad":"水","fq":"古矦切","vol":"11","py":"ɡōu","duan":[{"e":"水瀆也。","n":"也字依玄應補。"}]},"瀆":{"expl":"溝也。从水賣聲。一曰邑中溝。","rad":"水","fq":"徒谷切","vol":"11","py":"dú","duan":[{"e":"溝也。","n":"謂井閒廣四尺、深四尺者也。"}]},"渠":{"expl":"水所居。从水，榘省聲。","rad":"水","fq":"彊魚切","vol":"11","py":"qú","duan":[{"e":"水所居也。","n":"渠居曡韵。風俗通亦云。渠者、水所居也。"}]},"瀶":{"expl":"谷也。从水臨聲。讀若林。一曰寒也。","rad":"水","fq":"力尋切","vol":"11","py":"lín","duan":[{"e":"谷也。","n":"泉出通川爲谷。谷亦稱瀶也。"}]},"湄":{"expl":"水艸交爲湄。从水眉聲。","rad":"水","fq":"武悲切","vol":"11","py":"méi","duan":[{"e":"水艸交爲湄。","n":"小雅。居河之湄。釋水、毛傳皆曰。水草交爲湄。"}]},"洐":{"expl":"溝水行也。从水从行。","rad":"水","fq":"戶庚切","vol":"11","py":"xínɡ","duan":[{"e":"溝行水也。从水行。","n":"此以會意包形聲。戶庚切。古音𡉈十部。"}]},"釋":{"expl":"解也。从釆；釆，取其分別物也。从睪聲。","rad":"釆","fq":"賞職切","vol":"02","py":"shì","duan":[{"e":"解也。","n":"廣韵曰。捨也。解也。散也。消也。廢也。服也。按其實一解字足以包之。"}]},"澗":{"expl":"山夾水也。从水閒聲。一曰澗水，出弘農新安，東南入洛。","rad":"水","fq":"古萈切","vol":"11","py":"jiàn","duan":[{"e":"山夾水也。","n":"釋山、毛傳皆云。小雅。秩秩斯干。毛云。干、㵎也。此謂詩假借干爲㵎也。"}]},"澳":{"expl":"隈，厓也。其内曰澳，其外曰隈。从水奥聲。","rad":"水","fq":"於六切","vol":"11","py":"yù","duan":[{"e":"隈厓也。其內曰澳。其外曰鞫。","n":"鞫舊作隈。今正。爾雅說厓岸曰。隩隈厓。內爲隩。外爲鞫。郭以隈字上屬。厓字下屬。以許訂之。郭非是。𨸏部隈下曰。水曲隩也。隩下曰。水隈厓也。亦隈厓聯文。隩與澳字異而音義同。今毛詩瞻彼淇奧字作奧。古文假借也。毛詩曰。奧、隈也。此言水曲之裏淵奧然也。大雅。芮鞫之卽。箋云。水之內曰澳。水之外曰鞫。鞫謂水曲之表圜穹然也。鞫之雙聲爲居窮切。故傴僂之狀曰鞠竆、曰匑窮。水曲之表如弓。故曰鞫。韓詩、漢志作𨸰。字林作㘲。俗本爾雅改鞫爲隈。因或取以改說文耳。"}]},"澩":{"expl":"夏有水，冬無水，曰澩。从水，學省聲。讀若學。","rad":"水","fq":"胡角切","vol":"11","py":"xué","duan":[{"e":"夏有水、冬無水曰澩。","n":"釋山曰。山上有水埒。夏有水、冬無水澩。謂山上夏有停潦、冬則乾也。"}]},"𤅩":{"expl":"水濡而乾也。从水𪄿聲。《詩》曰：“𤅩其乾矣。”","rad":"水","fq":"呼旰切","vol":"11","py":"tān","duan":[{"e":"水濡而乾也。","n":"𤅩字古義如此。後人用爲沙灘。此之謂古今字也。沙灘字亦或作潬。"}]},"汕":{"expl":"魚游水皃。从水山聲。《詩》曰：“蒸然汕汕。”","rad":"水","fq":"所妟切","vol":"11","py":"shàn","duan":[{"e":"魚游水皃。","n":"小雅。南有嘉魚。烝然汕汕。傳曰。汕、樔也。詩不从毛。葢三家之說。"}]},"決":{"expl":"行流也。从水从夬。廬江有決水，出於大別山。","rad":"水","fq":"古穴切","vol":"11","py":"jué","duan":[{"e":"下流也。","n":"各本作行流。衆經音義三引皆作下流。下讀自上下下之下。胡駕切。決水之義引伸爲決𣃔。"}]},"灓":{"expl":"漏流也。从水䜌聲。","rad":"水","fq":"洛官切","vol":"11","py":"luán","duan":[{"e":"屚流也。","n":"宋姚宏曰。戰國策王季歷葬於楚山之尾。灓水齧其墓。謂墓爲山尾屚流所沮敗也。孔衍春秋後語改爲蠻水。注云。宜都縣有蠻水。誤甚。王季葬鄠南。"}]},"滴":{"expl":"水注也。从水啻聲。","rad":"水","fq":"都歴切","vol":"11","py":"dī","duan":[{"e":"水注也。","n":"埤倉有渧字。讀去聲。卽滴字也。"}]},"注":{"expl":"灌也。从水主聲。","rad":"水","fq":"之戍切","vol":"11","py":"zhù","duan":[{"e":"灌也。","n":"大雅曰。挹彼注茲。引伸爲傳注、爲六書轉注。注之云者、引之有所適也。故釋經以明其義曰注。交互之而其義相輸曰轉注。釋故、釋言、釋訓皆轉注也。有假注爲咮者。如注星卽咮星是也。"}]},"𣵽":{"expl":"漑灌也。从水芺聲。","rad":"水","fq":"烏鵠切","vol":"11","py":"wò","duan":[{"e":"漑灌也。","n":"自上澆下曰沃。故下文云澆者、沃也。周禮、左傳皆言沃盥是也。水沃則土肥。故云沃土。水沃則有光澤。故毛傳云沃沃、壯佼也。又云沃、柔也。"}]},"半":{"expl":"物中分也。从八从牛。牛爲物大，可以分也。凡半之屬皆从半。","rad":"半","fq":"博幔切","vol":"02","py":"bàn","duan":[{"e":"物中分也。从八牛。牛爲物大。可㠯分也。","n":"故取牛會意。"}]},"㳻":{"expl":"所以𢹬水也。从水昔聲。《漢律》曰：“及其門首洒㳻。”","rad":"水","fq":"所責切","vol":"11","py":"zé","duan":[{"e":"所㠯𢹬水也。","n":"𢹬當作雝。塞也。廣雅曰。㳻、隁也。"}]},"澨":{"expl":"埤增水邊土。人所止者。从水筮聲。《夏書》曰：“過三澨。”","rad":"水","fq":"時制切","vol":"11","py":"shì","duan":[{"e":"埤增水邊土、人所止者。","n":"土部曰。埤、增也。增、益也。酈善長曰。左傳文十六年。楚軍次於句澨。定四年。左司馬戍敗吳師於雍澨。昭二十三年。司馬薳越縊於薳澨。服虔或謂之邑、又謂之地。京相璠、杜預亦云。水際及邊地名也。今南陽淯陽二縣之閒淯水之濱、有南澨北澨矣。"}]},"津":{"expl":"水渡也。从水𦘔聲。","rad":"水","fq":"將鄰切","vol":"11","py":"jīn","duan":[{"e":"水渡也。","n":"商書微子曰。若涉大水其無津。俗本妄增涯字。按經傳多假借津爲𧗃潤字。周禮其民黑而津是。"}]},"淜":{"expl":"無舟渡河也。从水朋聲。","rad":"水","fq":"皮冰切","vol":"11","py":"pínɡ","duan":[{"e":"無舟渡河也。","n":"小雅傳曰。徒涉曰馮河。徒搏曰暴虎。爾雅釋訓、論語孔注同。淜正字。馮假借字。"}]},"㶇":{"expl":"小津也。从水橫聲。一曰以船渡也。","rad":"水","fq":"戶孟切","vol":"11","py":"hénɡ","duan":[{"e":"小津也。","n":"謂渡之小者也。非地大人衆之所。小一作水。非。"}]},"泭":{"expl":"編木以渡也。从水付聲。","rad":"水","fq":"芳無切","vol":"11","py":"fū","duan":[{"e":"編木㠯渡也。","n":"周南。江之永矣。不可方思。傳曰。方、泭也。卽釋言之舫、泭也。爾雅字多從俗耳。釋水曰。大夫方舟。士特舟。庶人乘泭。方言曰。泭謂之𥴖.𥴖謂之筏。筏、秦晉之通語也。廣韵曰。大曰𥱼、曰筏。小曰泭。按論語乘桴于海。假桴爲泭也。凡竹木蘆葦皆可編爲之。今江蘇、四川之語曰𥴖。"}]},"渡":{"expl":"濟也。从水度聲。","rad":"水","fq":"徒故切","vol":"11","py":"dù","duan":[{"e":"濟也。","n":"上文濟篆下無此義。此補見。邶風傳曰。濟、渡也。方言曰。過度謂之涉濟。凡過其處皆曰渡。假借多作度。天體三百六十五度。謂所過者三百六十五也。"}]},"沿":{"expl":"緣水而下也。从水㕣聲。《春秋傳》曰：“王沿夏。”","rad":"水","fq":"与專切","vol":"11","py":"yán","duan":[{"e":"緣水而下也。","n":"禹貢。沿于江海。達于淮泗。鄭本沿作松。字之誤也。馬本作均。依今文尙書也。均者、沿之假借字。如三年問反巡過其故鄉、荀卿巡作鉛。假鉛爲巡。其理一也。"}]},"泝":{"expl":"逆流而上曰㴑洄。㴑，向也。水欲下違之而上也。从水㡿聲。","rad":"水","fq":"桑故切","vol":"11","py":"sù","duan":[{"e":"逆流而上曰㴑洄。","n":"秦風傳曰。逆流而上曰遡洄。順流而涉曰遡游。釋水同。涉作下。"}]},"洄":{"expl":"㴑洄也。从水从回。","rad":"水","fq":"戶灰切","vol":"11","py":"huí","duan":[{"e":"㴑洄也。从水。回聲。","n":"以形聲包會意。戶灰切。十五部。"}]},"胖":{"expl":"半體肉也。一曰廣肉。从半从肉，半亦聲。","rad":"半","fq":"普半切","vol":"02","py":"pàn","duan":[{"e":"半體也。","n":"各本半體肉也。今依玄應訂。周官經腊人注曰。鄭大夫云。胖讀爲判。杜子春讀胖爲版。又云。膴、胖、皆謂夾脊肉。又云。禮家以胖爲半體。元謂胖宜如脯而腥。胖之言片也。析肉意也。按許用禮家說。"}]},"泳":{"expl":"潛行水中也。从水永聲。","rad":"水","fq":"爲命切","vol":"11","py":"yǒnɡ","duan":[{"e":"潛行水中也。","n":"周南。不可泳思。釋水、毛傳皆曰。潛行爲泳。下文云潛、涉水也。涉、徒行厲水也。"}]},"潛":{"expl":"涉水也。一曰藏也。一曰漢水爲潛。从水朁聲。","rad":"水","fq":"昨鹽切","vol":"11","py":"qián","duan":[{"e":"涉水也。","n":"上文云潛行水中。對下文浮行水上言之。邶風傳云。由厀以上爲涉。然則言潛者、自其厀以下𣳚於水言之。所謂泳也。左傳哀十七年。越子以三軍潛涉。又按潛汓等字、後人不甚分明。若水經注江水篇云。有潛客泳而視之。見水下有兩石牛。此則謂潛全𣳚水中矣。"}]},"淦":{"expl":"水入船中也。一曰泥也。从水金聲。","rad":"水","fq":"古暗切","vol":"11","py":"ɡàn","duan":[{"e":"水入船中也。","n":"水入船中、必由朕而入。淦者、浸淫隨理之意。"}]},"泛":{"expl":"浮也。从水乏聲。","rad":"水","fq":"孚梵切","vol":"11","py":"fàn","duan":[{"e":"浮也。","n":"邶風曰。汎彼柏舟。亦汎其流。上汎謂汎汎、浮皃也。下汎當作泛、浮也。汎泛古同音、而字有區別如此。左傳僖十三年。汎舟之役。亦當作泛。"}]},"汓":{"expl":"浮行水上也。从水从子。古或以汓爲没。","rad":"水","fq":"似由切","vol":"11","py":"qiú","duan":[{"e":"浮行水上也。","n":"若今人能划水者是也。列子曰。習於水、勇於泅。"}]},"砅":{"expl":"履石渡水也。从水从石。《詩》曰：“深則砅。”","rad":"水","fq":"力制切","vol":"11","py":"lì","duan":[{"e":"履石渡水也。","n":"謂若今有水汪、㼭甎石而過。水之至小至淺者也。"}]},"湊":{"expl":"水上人所會也。从水奏聲。","rad":"水","fq":"倉奏切","vol":"11","py":"còu","duan":[{"e":"水上人所會也。","n":"引伸爲凡聚集之偁。"}]},"湛":{"expl":"没也。从水甚聲。一曰湛水，豫章浸。","rad":"水","fq":"宅減切","vol":"11","py":"chén","duan":[{"e":"𣳚也。","n":"古書浮沈字多作湛。湛沈古今字。沉又沈之俗也。下文云。𣳚、湛也。二字轉注。"}]},"湮":{"expl":"没也。从水垔聲。","rad":"水","fq":"於眞切","vol":"11","py":"yīn","duan":[{"e":"𣳚也。","n":"釋詁。湮、落也。落與𣳚義相近。"}]},"㲻":{"expl":"没也。从水从人。","rad":"水","fq":"奴歴切","vol":"11","py":"nì","duan":[{"e":"𣳚也。","n":"此沈溺之本字也。今人多用溺水水名字爲之。古今異字耳。玉篇引孔子曰。君子㲻於口。小人㲻於水。顧希馮所見禮記尙作㲻。"}]},"叛":{"expl":"半也。从半反聲。","rad":"半","fq":"薄半切","vol":"02","py":"pàn","duan":[{"e":"半反也。","n":"反、覆也。反者叛之全。叛者反之半。以半反釋叛。如以是少釋尟。"}]},"沒":{"expl":"沈也。从水从𠬸。","rad":"水","fq":"莫勃切","vol":"11","py":"mò","duan":[{"e":"湛也。","n":"湛各本作沈。淺人以今字改之也。今正。𣳚者全入於水。故引伸之義訓盡。小雅。曷其𣳚矣。傳云。𣳚、盡也。論語𣳚階。孔安國曰。𣳚、盡也。凡貪𣳚、乾𣳚皆沈溺之引伸。"}]},"渨":{"expl":"没也。从水畏聲。","rad":"水","fq":"烏恢切","vol":"11","py":"wēi","duan":[{"e":"𣳚也。从水。畏聲。","n":"烏恢切。十五部。按此字疑後人所增。"}]},"滃":{"expl":"雲气起也。从水翁聲。","rad":"水","fq":"烏孔切","vol":"11","py":"wěnɡ","duan":[{"e":"雲气起也。","n":"易林。潼滃蔚薈。扶首來會。謂雲起也。江賦。氣滃渤以霧杳。有假翁爲滃者。周禮醴齊注。盎猶翁也。成而翁翁然葱白色。"}]},"泱":{"expl":"滃也。从水央聲。","rad":"水","fq":"於良切","vol":"11","py":"yānɡ","duan":[{"e":"滃也。","n":"射雉賦。天泱泱以垂雲。善曰。毛詩英英白雲。毛萇曰英英、白雲皃。泱與英古字通。按泱滃雙聲。"}]},"淒":{"expl":"雲雨起也。从水妻聲。《詩》曰：“有渰淒淒。”","rad":"水","fq":"七稽切","vol":"11","py":"qī","duan":[{"e":"雨雲起也。","n":"各本作雲雨。誤。今依初學記、太平御覽正。雨雲、謂欲雨之雲。唐人詩晴雲、雨雲是也。按詩曰。淒其以風。毛傳。淒、寒風皃。又曰。風雨淒淒。葢淒有陰寒之意。小雅。有渰淒淒。皃急雨欲來之狀。未嘗不兼風言之。許以字從水。但謂之雨雲。"}]},"渰":{"expl":"雲雨皃。从水弇聲。","rad":"水","fq":"衣檢切","vol":"11","py":"yǎn","duan":[{"e":"雨雲皃。","n":"各本作雲雨皃。今依初學記、太平御覽正。毛傳曰。渰、雲興皃。顏氏家訓、定本、集注作陰雲。恐許所據徑作雨雲。渰漢書作黤。按有渰淒淒、謂黑雲如鬊。淒風怒生。此山雨欲來風滿樓之象也。旣而白雲彌漫。風定雨甚。則興雲祁祁、雨我公田也。詩之體物𤄉亮如是。"}]},"溟":{"expl":"小雨溟溟也。从水冥聲。","rad":"水","fq":"莫經切","vol":"11","py":"mínɡ","duan":[{"e":"小雨溟溟也。","n":"太玄經。密雨溟沐。玉篇曰。溟濛小雨。莊子南溟北溟、其字當是本作冥。"}]},"洓":{"expl":"小雨零皃。从水朿聲。","rad":"水","fq":"所責切","vol":"11","py":"sè","duan":[{"e":"小雨霝皃。","n":"霝各本作零。今正。洓洓亦雨聲。"}]},"瀑":{"expl":"疾雨也。一曰沫也。一曰瀑，資也。从水暴聲。《詩》曰：“終風且瀑。”","rad":"水","fq":"平到切","vol":"11","py":"bào","duan":[{"e":"疾雨也。","n":"曓疾有所趣也。故从水、从曓、爲疾雨。"}]},"澍":{"expl":"時雨，澍生萬物。从水尌聲。","rad":"水","fq":"常句切","vol":"11","py":"shù","duan":[{"e":"時雨也。所㠯樹生萬物者也。","n":"依魏都賦注、後漢明帝紀注補五字。樹舊譌澍。今正。樹澍以壘韵爲訓。難蜀父老曰。羣生澍濡。"}]},"牛":{"expl":"大牲也。牛，件也；件，事理也。象角頭三、封㞑之形。凡牛之屬皆从牛。","rad":"牛","fq":"語求切","vol":"02","py":"niú","duan":[{"e":"事也。理也。","n":"事也者、謂能事其事也牛任耕理也者、謂其文理可分析也。庖丁解牛。依乎天理。批大卻道大窾牛事理三字同在古音第一部。此與羊祥也、馬怒也、武也、一例。自淺人不知此義。乃改之云大牲也。牛件也。件事理也。與吳字下𡚶增之曰姓也。亦郡也。同一紕繆。"}]},"湒":{"expl":"雨下也。从水咠聲。一曰沸涌皃。","rad":"水","fq":"姊入切","vol":"11","py":"jí","duan":[{"e":"雨下也。","n":"廣雅云。湒湒、雨也。毛詩。其角湒湒。宋本釋文如是。假借爲角皃。"}]},"澬":{"expl":"久雨涔資也。一曰水名。从水資聲。","rad":"水","fq":"才私切","vol":"11","py":"cí","duan":[{"e":"久雨涔澬也。","n":"亦作涔𩆂。"}]},"潦":{"expl":"雨水大皃。从水尞聲。","rad":"水","fq":"盧皓切","vol":"11","py":"lǎo","duan":[{"e":"雨水也。","n":"各本作雨水大皃。今依詩采蘋正義、文選陸機贈顧彥先詩注、衆經音義卷一訂。曲禮釋文亦曰。雨水謂之潦。雨水、謂雨下之水也。左傳曰。水潦將降。召南。于彼行潦。傳曰。行潦、流潦也。按傳以流釋行。服注左傳乃云道路之水。趙注孟子乃云道旁流潦。以道釋行、似非。潦水流而聚焉。故曰行潦。不必在道旁也。"}]},"濩":{"expl":"雨流霤下。从水蒦聲。","rad":"水","fq":"胡郭切","vol":"11","py":"huò","duan":[{"e":"雨流𩅸下皃。","n":"皃宋本無。非。𩅸、屋水流下也。今俗語𧦝簷水澑下曰滴濩。乃古語也。或假濩爲鑊。如詩是刈是濩是也。或假爲護。如湯樂名大濩是也。"}]},"涿":{"expl":"流下滴也。从水豖聲。上谷有涿縣。","rad":"水","fq":"竹角切","vol":"11","py":"zhuó","duan":[{"e":"流下滴也。","n":"周禮壺涿氏注。壺、瓦𡔷也。涿、擊之也。按擊瓦𡔷之聲如滴然。故曰壺涿。今俗謂一滴曰一涿。音如篤。卽此字也。又作沰。音當洛反。廣雅。沰、磓也。崔寔書。上火不落。下火滴沰。周禮掌舍注云。柜受居澑水涑橐者也。橐卽沰之假借。"}]},"瀧":{"expl":"雨瀧瀧皃。从水龍聲。","rad":"水","fq":"力公切","vol":"11","py":"lónɡ","duan":[{"e":"雨瀧瀧也。","n":"也大徐作皃。今依小徐及廣韵。瀧瀧、雨滴皃也。音轉讀爲浪浪。平聲。方言曰。瀧涿謂之霑漬。郭云。瀧涿猶瀨滯也。瀨滯當作𤃀渧。埤倉云。渧𤃀、漉也。通俗文云。霝滴謂之𤃀渧。又廣韵、集韵皆云。瀧涷、沾漬也。瀧涷卽瀧涿也。荀𨜮書。東籠而退。楊倞云。東籠卽瀧涷。"}]},"渿":{"expl":"沛之也。从水柰聲。","rad":"水","fq":"奴帶切","vol":"11","py":"nài","duan":[{"e":"㴎沛也。","n":"玉篇同。未聞。一本作沛之。廣韵、集韵、類篇同。亦未聞。按㴎沛當係𤃀渧之字誤。又佚渧篆耳。與上文三篆同義。故廁於此。"}]},"滈":{"expl":"久雨也。从水高聲。","rad":"水","fq":"乎老切","vol":"11","py":"hào","duan":[{"e":"久雨也。","n":"引伸爲水皃。上林賦。翯乎滈滈。吳都賦。滈汗六州之域。借爲京兆鎬水字。"}]},"漊":{"expl":"雨漊漊也。从水婁聲。一曰汝南謂飲酒習之不醉爲漊。","rad":"水","fq":"力主切","vol":"11","py":"lǚ","duan":[{"e":"雨漊漊也。","n":"漊漊猶縷縷也。不絕之皃。"}]},"溦":{"expl":"小雨也。从水，微省聲。","rad":"水","fq":"無非切","vol":"11","py":"wēi","duan":[{"e":"小雨也。","n":"今人槩作微。廣韵、集韵皆曰。浽溦、小雨。按爾雅。谷者、溦。假借字也。"}]},"牡":{"expl":"畜父也。从牛土聲。","rad":"牛","fq":"莫厚切","vol":"02","py":"mǔ","duan":[{"e":"畜父也。从牛。土聲。","n":"按土聲、求之㬪韵雙聲皆非是。葢當是从土。取土爲水牡之意。或曰。土當作士。士者夫也。之韵尤韵合音冣近。从士則爲會意兼形聲。莫厚切。古音在三部。"}]},"濛":{"expl":"微雨也。从水蒙聲。","rad":"水","fq":"莫紅切","vol":"11","py":"ménɡ","duan":[{"e":"溦雨皃。","n":"溦各本作微。今正。皃葉本作也。今依玉篇正。溦溟濛三字、一聲之轉。豳風曰。零雨其濛。傳云。濛、雨皃。廣韵。空濛、小雨。廣雅作靀。靀、俗字也。"}]},"沈":{"expl":"陵上滈水也。从水冘聲。一曰濁黕也。","rad":"水","fq":"直深切","vol":"11","py":"chén","duan":[{"e":"陵上滈水也。","n":"謂陵上雨積停潦也。古多假借爲湛𣳚之湛。如小雅載沈載浮是。又或借爲瀋字。檀弓爲榆沈是也。"}]},"洅":{"expl":"雷震洅洅也。从水再聲。","rad":"水","fq":"作代切","vol":"11","py":"zài","duan":[{"e":"靁震洅洅也。从水。","n":"靁震雨中、故从水。"}]},"淊":{"expl":"泥水淊淊也。一曰繅絲湯也。从水臽聲。","rad":"水","fq":"胡感切","vol":"11","py":"hàn","duan":[{"e":"泥水淊淊也。从水。臽聲。","n":"胡感切。八部。"}]},"𣹢":{"expl":"水澤多也。从水圅聲。《詩》曰：“僭始旣𣹢。”","rad":"水","fq":"胡男切","vol":"11","py":"hán","duan":[{"e":"水澤多也。","n":"所受潤澤多也。"}]},"𣹤":{"expl":"漸溼也。从水挐聲。","rad":"水","fq":"人庶切","vol":"11","py":"rù","duan":[{"e":"漸溼也。","n":"魏風。彼汾沮洳。傳曰。汾汾水也。沮洳、其漸洳者。洳𣹤同字。沮子預反。猶潪也。"}]},"瀀":{"expl":"澤多也。从水憂聲。《詩》曰：“旣瀀旣渥。”","rad":"水","fq":"於求切","vol":"11","py":"yōu","duan":[{"e":"澤多也。","n":"與優。義近。瞻卬傳曰。優、渥也。優卽瀀之假借矣。"}]},"涔":{"expl":"潰也。一曰涔陽渚，在郢中。从水岑聲。","rad":"水","fq":"鉏箴切","vol":"11","py":"cén","duan":[{"e":"漬也。","n":"淮南書。牛蹄之涔。謂水覺察漬於牛跡中者也。毛詩。潛有多魚。韓詩作涔。爾雅曰。糝謂之涔。毛傳曰。潛、糝也。說者云糝卽罧字。韓詩曰。涔、魚池也。此皆涔之別義。"}]},"漬":{"expl":"漚也。从水責聲。","rad":"水","fq":"前智切","vol":"11","py":"zì","duan":[{"e":"漚也。","n":"謂浸漬也。古多假爲骴字。公羊傳大瘠。禮記注引作大漬。公羊傳。瀸者何。漬也。衆殺戍者也。周禮蜡氏。掌除骴。故書骴作脊。鄭司農云。脊讀爲漬。謂死人骨也。漢志。國亡捐瘠。孟康曰。肉腐爲瘠。按骴漬脊瘠四字、古同音通用。當是骴爲正字也。"}]},"漚":{"expl":"久漬也。从水區聲。","rad":"水","fq":"烏候切","vol":"11","py":"òu","duan":[{"e":"久漬也。","n":"言久漬者、略別於漬也。上統言。此析言。互相足也。陳風。可以漚麻。傳曰。漚、柔也。考工記。漚其絲。注曰。楚人曰漚。齊人曰涹。或假渥字爲之。如左傳繒人漚菅者、周禮注引作繒人渥菅是也。"}]},"犅":{"expl":"特牛也。从牛岡聲。","rad":"牛","fq":"古郎切","vol":"02","py":"ɡānɡ","duan":[{"e":"特也。","n":"今本作特牛也。依詩正義訂。公羊傳曰。魯祭周公。何以爲牲。周公用白牡。魯公用騂犅。羣公不毛。何休云騂犅赤脊。按說文岡訓山脊。故何謂犅爲牛脊。但毛詩衹作剛。許說犅同特。與何異。"}]},"浞":{"expl":"濡也。从水足聲。","rad":"水","fq":"士角切","vol":"11","py":"zhuó","duan":[{"e":"小濡皃也。","n":"濡者、霑也。上文濡篆下未舉此義。故此及雨部補見。小雅曰。旣霑旣足。蓋足卽浞之假借也。"}]},"渥":{"expl":"霑也。从水屋聲。","rad":"水","fq":"於角切","vol":"11","py":"wò","duan":[{"e":"霑也。","n":"小雅。旣優旣渥。考工記。俗其柔滑而腛脂之。注。腛讀如沾渥之渥。按渥之言厚也。濡之深厚也。邶風傳曰。渥、厚漬也。"}]},"㴶":{"expl":"灌也。从水隺聲。","rad":"水","fq":"口角切","vol":"11","py":"què","duan":[{"e":"灌也。","n":"㴶與𣵽義同。"}]},"洽":{"expl":"霑也。从水合聲。","rad":"水","fq":"矦夾切","vol":"11","py":"qià","duan":[{"e":"霑也。","n":"大雅。民之洽矣。傳曰。洽、合也。此謂毛詩假洽爲合也。釋詁曰。郃、合也。郃卽洽。毛詩在洽之陽、稱引者多作在郃之陽是也。"}]},"濃":{"expl":"露多也。从水農聲。《詩》曰：“零露濃濃。”","rad":"水","fq":"女容切","vol":"11","py":"nónɡ","duan":[{"e":"露多也。","n":"小雅蓼蕭傳曰。濃濃、厚皃。按酉部曰。醲、厚酒也。衣部曰。襛、衣厚皃。凡農聲字皆訓厚。"}]},"瀌":{"expl":"雨雪瀌瀌。从水麃聲。","rad":"水","fq":"甫嬌切","vol":"11","py":"biāo","duan":[{"e":"瀌瀌、雨雪皃。","n":"依韵會所據小徐本訂。小雅角弓曰。雨雪瀌瀌。見晛曰消。廣雅。瀌瀌、雪也。劉向傳作麃。"}]},"溓":{"expl":"薄水也。一曰中絕小水。从水兼聲。","rad":"水","fq":"力鹽切","vol":"11","py":"lián","duan":[{"e":"溓溓、薄仌也。","n":"溓溓二字依文選注補。潘岳寡婦賦曰。水溓溓以微凝。按食部䭑下云。讀若風溓溓。葢當云讀若風溓之溓。風溓、謂風之蹙淩也。"}]},"泐":{"expl":"水石之理也。从水从阞。《周禮》曰：“石有時而泐。”","rad":"水","fq":"盧則切","vol":"11","py":"lè","duan":[{"e":"水之理也。","n":"各本水下有石字。今刪。𨸏部曰。阞、地理也。从𨸏。木部曰。朸、木之理也。从木。然則泐訓水之理、从水無疑矣。淺人不知水有理。又見下文引周禮說石。乃妄增一字。水理如地理、木理可尋。其字皆从力。力者、人身之理也。"}]},"滯":{"expl":"凝也。从水帶聲。","rad":"水","fq":"直例切","vol":"11","py":"zhì","duan":[{"e":"凝也。","n":"凝俗冰字。周禮廛人。凡珍異之有滯者。鄭司農云。貨物沈滯於廛中不決、泉府貨之滯於民用者。故書滯爲癉。杜子春云。癉當爲滯。"}]},"汦":{"expl":"著止也。从水氏聲。","rad":"水","fq":"直尼切","vol":"11","py":"zhǐ","duan":[{"e":"箸止也。","n":"箸直略切。箸止、有所箸而止也。土部坁下曰。箸也。與此字皆从氏。徐楚金引左傳物乃汦伏。按左傳自作坻伏。杜曰。坻、止也。尋其義當作坁。與汦義略同。葢唐宋以來。氏氐溷淆多矣。"}]},"禰":{"expl":"親廟也。从示爾聲。一本云古文𥜬也。","rad":"示","fq":"泥米切","vol":"01","py":"nǐ","duan":[]},"特":{"expl":"朴特，牛父也。从牛寺聲。","rad":"牛","fq":"徒得切","vol":"02","py":"tè","duan":[{"e":"特牛也。","n":"鉉本云。朴特牛父也。按天問。焉得夫朴牛。洪氏引說文。特牛、牛父也。言其朴特。皆與鍇本異。葢言其朴特、乃注說文者語。鉉本改竄上移耳。王逸、張揖皆云。朴、大也。玉篇㹒訓特牛。廣韵㹒訓牛未㓺。此因古有朴特之語而製㹒字。特本訓牡。陽數奇。引伸之爲凡單獨之偁。一與一爲耦。故實維我特、求爾新特。毛云。特、匹也。"}]},"𤂆":{"expl":"水裂去也。从水虢聲。","rad":"水","fq":"古伯切","vol":"11","py":"ɡuó","duan":[{"e":"水裂去也。","n":"謂水分裂而去也。韓愈文用㶁㶁字。"}]},"澌":{"expl":"水索也。从水斯聲。","rad":"水","fq":"息移切","vol":"11","py":"sī","duan":[{"e":"水索也。","n":"方言曰。澌、索也。郭注云。盡也。按許說其本義。楊說其引伸之義也。索訓盡者、索乃𡩡之假借字。入室搜𡩡、有盡意也。方言曰。鋌、賜也。賜者、澌之假借。亦作儩。"}]},"汔":{"expl":"水涸也。或曰泣下。从水气聲。《詩》曰：“汽可小康。”","rad":"水","fq":"許訖切","vol":"11","py":"qì","duan":[{"e":"水涸也。","n":"大雅民勞傳曰。汔、危也。周易。汔至亦未繘井。小狐汔濟。虞翻曰。汔、幾也。皆引伸之義。水固爲將盡之時。故引伸之義曰危、曰幾也。"}]},"涸":{"expl":"渴也。从水固聲。讀若狐貈之貈。","rad":"水","fq":"下各切","vol":"11","py":"hé","duan":[{"e":"渴也。","n":"渴、盡也。渠列切。釋詁曰。涸、渴也。俗本作竭。月令。仲秋之月。水始涸。"}]},"消":{"expl":"盡也。从水肖聲。","rad":"水","fq":"相幺切","vol":"11","py":"xiāo","duan":[{"e":"盡也。","n":"未盡而將盡也。"}]},"潐":{"expl":"盡也。从水焦聲。","rad":"水","fq":"子肖切","vol":"11","py":"jiào","duan":[{"e":"盡也。","n":"荀𨜮書。其誰能以己之潐潐。受人之掝掝者哉。楊倞曰。潐、盡也。潐潐、謂窮盡明於事。猶楚辭之察察。"}]},"渴":{"expl":"盡也。从水曷聲。","rad":"水","fq":"苦葛切","vol":"11","py":"kě","duan":[{"e":"盡也。","n":"渴竭古今字。古水竭字多用渴。今則用渴爲㵣字矣。"}]},"漮":{"expl":"水虛也。从水康聲。","rad":"水","fq":"苦岡切","vol":"11","py":"kānɡ","duan":[{"e":"水虛也。","n":"爾雅音義引作水之空也。葢許用釋爾雅舊說。故爲分別之詞。釋詁曰。漮、虛也。虛、師古引作空。康者、穀皮中空之謂。故从康之字皆訓爲虛。㱂下曰。饑虛也。㝩下曰。屋㝩㝗也。詩。酌彼康爵。箋云。康、虛也。方言曰。㝩、空也。長門賦槺梁、虛梁也。急就篇顏注曰。𨎍謂輿中空處。所用載物也。水之空、謂水之中心有空處。"}]},"溼":{"expl":"幽溼也。从水；一，所以覆也，覆而有土，故溼也。㬎省聲。","rad":"水","fq":"失入切","vol":"11","py":"shī","duan":[{"e":"幽溼也。从一。","n":"句。"}]},"湆":{"expl":"幽溼也。从水音聲。","rad":"水","fq":"去急切","vol":"11","py":"qì","duan":[{"e":"幽溼也。从水。音聲。","n":"去急切。七部。五經文字云。湇從泣下月。大羹也。湆從泣下日。幽深也。今禮經大羹相承多作下字。或傳寫久譌。不敢改正。按湇字不見於說文。則未知張說何本。儀禮音義引字林云。湆、羹汁也。玉篇、廣韵同。然則本無異字。肉之精液如幽溼生水也。廣雅。羹謂之䏠。皆字之或體耳。"}]},"牝":{"expl":"畜母也。从牛匕聲。《易》曰：“畜牝牛，吉。”","rad":"牛","fq":"毗忍切","vol":"02","py":"pìn","duan":[{"e":"畜母也。从牛。匕聲。","n":"毗忍切。古音在十五部。經典舊音多云扶死反。是也。"}]},"洿":{"expl":"濁水不流也。一曰窳下也。从水夸聲。","rad":"水","fq":"哀都切","vol":"11","py":"wū","duan":[{"e":"濁水不流也。","n":"服虔注左傳云。水不流謂之汙。按汙卽洿之假借字。孟子梁惠王作洿。滕文公用汙。玄應引說文濁水不流池也。引字林濁水不流曰洿。宜有池爲長。"}]},"浼":{"expl":"汙也。从水免聲。《詩》曰：“河水浼浼。”《孟子》曰：“汝安能浼我？”","rad":"水","fq":"武辠切","vol":"11","py":"měi","duan":[{"e":"污也。","n":"孟子公孫丑篇曰。爾焉能浼我哉。趙注。惡人何能污我也。"}]},"汙":{"expl":"薉也。一曰小池爲汙。一曰涂也。从水于聲。","rad":"水","fq":"烏故切","vol":"11","py":"wū","duan":[{"e":"薉也。","n":"艸部曰。薉者、蕪也。地云蕪薉。水云汙薉。皆謂其不潔淸也。此冡上濁水不流池類言之。大徐本移浼篆於汙篆前。不知下文㶄灒浼類列。略同方言。廁於此、則非其次矣。"}]},"湫":{"expl":"隘。下也。一曰有湫水，在周地。《春秋傳》曰：“晏子之宅秋隘。”安定朝𨙻有湫泉。从水秋聲。","rad":"水","fq":"子了切","vol":"11","py":"jiǎo","duan":[{"e":"隘下也。","n":"當作湫隘湫下也。此舉左傳湫隘字而釋湫如。毛傳云文茵文虎皮也之例。杜預亦云湫下、隘小。下文塏訓高燥。爲湫之反。昭三年左傳服注。湫、箸也。十二年杜注。湫、愁隘也。皆引伸之義。"}]},"潤":{"expl":"水曰潤下。从水閏聲。","rad":"水","fq":"如順切","vol":"11","py":"rùn","duan":[{"e":"水曰潤下。","n":"語見洪範。"}]},"準":{"expl":"平也。从水隼聲。","rad":"水","fq":"之允切","vol":"11","py":"zhǔn","duan":[{"e":"平也。","n":"謂水之平也。天下莫平於水。水平謂之準。因之製平物之器亦謂之準。漢志。繩直生準。準者、所以揆平取正是也。因之凡平均皆謂之準。考工記準之然後量之、易繫辭易與天地準是也。"}]},"汀":{"expl":"平也。从水丁聲。","rad":"水","fq":"他丁切","vol":"11","py":"tīnɡ","duan":[{"e":"平也。","n":"謂水之平也。水平謂之汀。因之洲渚之平謂之汀。李善引文字集略云。水際平沙也。乃引伸之義耳。"}]},"沑":{"expl":"水吏也。又，溫也。从水丑聲。","rad":"水","fq":"人九切","vol":"11","py":"nǜ","duan":[{"e":"水吏也。","n":"謂水駛也。駛、疾也。其字在說文作𩰢。不解者譌爲吏耳。一本作利。義同。錢氏大昕云。吏當作文。海賦踧沑注云。蹵聚也。廣韵云。蹜沑、水文聚。踧蹜同。按廣韵上聲人九切。引說文同。入聲女六切。云水文聚。"}]},"瀵":{"expl":"水浸也。从水糞聲。《爾雅》曰：“瀵，大出尾下。”","rad":"水","fq":"方問切","vol":"11","py":"fèn","duan":[{"e":"水漫也。","n":"漫各本作浸。今依集韵訂。說文水部無漫。當作曼。曼者、引也。瀵者、水之引而愈出也。曼瀵聲類相近。"}]},"𣿒":{"expl":"新也。从水辠聲。","rad":"水","fq":"七辠切","vol":"11","py":"cuǐ","duan":[{"e":"新也。","n":"謂水色新也。如玉色鮮曰玼。廣韵曰。新水狀也。"}]},"犢":{"expl":"牛子也。从牛，瀆省聲。","rad":"牛","fq":"徒谷切","vol":"02","py":"dú","duan":[{"e":"牛子也。","n":"見釋？。"}]},"瀞":{"expl":"無垢薉也。从水靜聲。","rad":"水","fq":"疾正切","vol":"11","py":"jìnɡ","duan":[{"e":"無垢薉也。","n":"此今之淨字也。古瀞今淨、是之謂古今字。古籍少見。韵會云。楚辭收潦而水淸。注作瀞。按今文選本作百川靜。洪興祖本作百川淸。皆與黃氏所見異。古書多假淸爲瀞。"}]},"瀎":{"expl":"拭滅皃。从水蔑聲。","rad":"水","fq":"莫達切","vol":"11","py":"mò","duan":[{"e":"瀎泧。","n":"二字各本奪。今依全書例補。"}]},"泧":{"expl":"瀎泧也。从水戉聲。讀若椒樧之樧。","rad":"水","fq":"","vol":"11","py":"sà","duan":[{"e":"瀎泧也。从水。戉聲。讀若椒樧之樧。","n":"按音所八切。十五部。大徐云火活切。非也。"}]},"洎":{"expl":"灌釜也。从水自聲。","rad":"水","fq":"其冀切","vol":"11","py":"jì","duan":[{"e":"灌釡也。","n":"灌者、沃也。沃今江蘇俗云燠。烏到切。廣韵三十七號云。燠釡、以水添釡也。周禮士師。洎鑊水。注云。洎、謂增其沃汁。呂覽。多洎之。少洎之。左傳去其肉而以其洎饋。正義云。洎者、添釡之名。添釡以爲肉汁。遂名肉汁爲洎。"}]},"湯":{"expl":"熱水也。从水昜聲。","rad":"水","fq":"土郎切","vol":"11","py":"tānɡ","duan":[{"e":"𤍽水也。从水。昜聲。","n":"土郎切。十部。又始陽切。湯湯水盛。"}]},"渜":{"expl":"湯也。从水耎聲。","rad":"水","fq":"乃管切","vol":"11","py":"nuǎn","duan":[{"e":"湯也。","n":"士喪禮。渜濯棄于坎。注。沐浴餘潘水。渜作湪作湪。荆沔之閒語。疏。潘水旣經溫煑謂之渜。已將沐浴謂之濯。○今北方灤河、漢志水經作濡水。乃官切。正渜之誤耳。耎多譌需。詳手部。渜洝古皆平聲。猶安㬮。"}]},"洝":{"expl":"渜水也。从水安聲。","rad":"水","fq":"烏旰切","vol":"11","py":"àn","duan":[{"e":"渜水也。","n":"日部曰。安㬮、溫也。然則洝渜猶安㬮。皆曡韵字。"}]},"洏":{"expl":"洝也。一曰煑孰也。从水而聲。","rad":"水","fq":"如之切","vol":"11","py":"ér","duan":[{"e":"洝也。","n":"洏與渜音近。耎從而聲也。"}]},"涗":{"expl":"財溫水也。从水兌聲。《周禮》曰：“以涗漚其絲。”","rad":"水","fq":"輸芮切","vol":"11","py":"shuì","duan":[{"e":"財𥁕水也。","n":"考工記曰。以涗水漚其絲。注云。故書涗作湄。鄭司農云。湄水、溫水也。玄謂涗水、以灰所泲水也。玉裁按湄當作渜。集韵云渜或作湄是也。大鄭從渜。故釋之曰溫水。鄭從涗。故依禮記涗齊貴新之涗。釋爲以灰所泲水。其說殊矣。許則字從涗。而釋從大鄭。依許說則內則、祭統涗字不可解。"}]},"涫":{"expl":"𩰾也。从水官聲。酒泉有樂涫縣。","rad":"水","fq":"古丸切","vol":"11","py":"ɡuàn","duan":[{"e":"𩰾也。","n":"春秋繁露。燔以涫湯。韓詩外傳作沸湯。然則涫𩰾一也。周禮注曰。今燕俗名湯𤍠爲觀。觀卽涫。今江蘇俗語𩰾水曰滾水。滾水卽涫。語之轉也。"}]},"㸬":{"expl":"二歲牛。从牛巿聲。","rad":"牛","fq":"博蓋切","vol":"02","py":"bèi","duan":[{"e":"二歲牛。","n":"？字見爾雅釋畜。牛體長也。許君則曰二歲牛。按？字从參。故爲三歲牛。牭字从四。故爲四歲牛。則㹑字从貳。當爲二歲牛矣。而謂㹑爲籒文牭字。二四旣不同數。且四之籒文作亖。則牭之籒文當作？。凡此乖剌。當由轉寫脫繆。如鼎部鼏鼏、馬部？䮸、衣部袗袀、今皆奪其一。其明譣也。宜易之曰？、牛體長也。㹑、二歲牛。慘、三歲牛。牭、四歲牛。？、籒文牭。則可讀矣。而非可無徵專輒也。"}]},"涾":{"expl":"涫溢也。今河朔方言謂沸溢爲涾。从水沓聲。","rad":"水","fq":"徒合切","vol":"11","py":"tà","duan":[{"e":"涫溢也。今河朔方言謂𩰾溢爲涾。","n":"河朔、河北也。"}]},"汏":{"expl":"淅𤃦也。从水大聲。","rad":"水","fq":"代何切","vol":"11","py":"tài","duan":[{"e":"淅㵎也。","n":"淅字賸。文選注王元長舉秀才文注引無淅字、可證。士䘮禮。祝淅米于堂。注。淅、汏也。釋詁曰。汏、墜也。汏之則沙礫去矣。故曰墜也。九章。齊吳榜以擊汏。吳、大也。榜、楫也。言齊同用大楫擊水而行。如汏洒於水中也。凡舟子之用櫓。振力擊之。乃徐拕之。如汏然。今蘇州人謂搖曳洒之曰汏。音如俗語之大。在禡韵。"}]},"㶕":{"expl":"浙也。从水簡聲。","rad":"水","fq":"古限切","vol":"11","py":"jiǎn","duan":[{"e":"淅也。","n":"從𥳑者、柬擇之意。從析者、分別之意。故二字轉注。"}]},"淅":{"expl":"汏米也。从水析聲。","rad":"水","fq":"先擊切","vol":"11","py":"xī","duan":[{"e":"汏米也。","n":"毛詩傳曰。釋、淅米也。爾雅。溞溞、淅也。孟子注曰。淅、漬米也。凡釋米、淅米、漬米、汏米、？米、淘米、洮米、漉米、異稱而同事。淅箕謂之䉛。"}]},"滰":{"expl":"浚乾漬米也。从水竟聲。《孟子》曰：“夫子去齊，滰淅而行。”","rad":"水","fq":"其兩切","vol":"11","py":"jiànɡ","duan":[{"e":"浚乾漬米也。","n":"自其方漚未淘言之曰漬。米不及淘抒而起之曰滰。乾音干。"}]},"𣸈":{"expl":"浸𣵽也。从水叜聲。","rad":"水","fq":"疏有切","vol":"11","py":"sǒu","duan":[{"e":"𣵽汏也。","n":"𣵽汏各本作浸沃。今依國語補音宋刋本訂。沃汏者、澆沃而汏酒之。若今人言𣸈麪是也。士虞禮。明齊溲酒。注。明齊、新水也。言以新水溲釀此酒也。此溲卽沃汏之義。"}]},"浚":{"expl":"杼也。从水夋聲。","rad":"水","fq":"私閏切","vol":"11","py":"jùn","duan":[{"e":"抒也。","n":"抒者、挹也。取諸水中也。春秋經浚洙、孟子使浚井、左傳浚我以生、義皆同。浚之則深。故小弁傳曰。浚、深也。"}]},"瀝":{"expl":"浚也。从水歷聲。一曰水下滴瀝。","rad":"水","fq":"郎擊切","vol":"11","py":"lì","duan":[{"e":"漉也。从水。歷聲。","n":"郎擊切。十六部。"}]},"漉":{"expl":"浚也。从水鹿聲。","rad":"水","fq":"盧谷切","vol":"11","py":"lù","duan":[{"e":"浚也。","n":"月令。仲春。毋竭川澤。毋漉陂池。注。順陽養物也。"}]},"潘":{"expl":"淅米汁也。一曰水名，在河南滎陽。从水番聲。","rad":"水","fq":"普官切","vol":"11","py":"pān","duan":[{"e":"淅米汁也。","n":"內則曰。其閒面垢。燂潘請靧。鄭云。潘、米瀾也。按瀾者、灡之省。力旦反。"}]},"犙":{"expl":"三歲牛。从牛參聲。","rad":"牛","fq":"穌含切","vol":"02","py":"sān","duan":[{"e":"三歲牛。从牛。參聲。","n":"穌含切。古音在七部。"}]},"灡":{"expl":"潘也。从水蘭聲。","rad":"水","fq":"洛干切","vol":"11","py":"lán","duan":[{"e":"潘也。","n":"此字以從蘭、與大波之瀾別。而古書通用。周禮？人注。雖其潘灡戔餘不可䙝。內則注。潘、米瀾也。"}]},"泔":{"expl":"周謂潘曰泔。从水甘聲。","rad":"水","fq":"古三切","vol":"11","py":"ɡān","duan":[{"e":"周謂潘曰泔。","n":"今各處語言同此。荀卿子曰。曾子食魚有餘曰泔之。"}]},"滫":{"expl":"久泔也。从水脩聲。","rad":"水","fq":"息流切","vol":"11","py":"xiū","duan":[{"e":"久泔也。","n":"荀卿子。蘭槐之根是爲芷。其漸之滫。君子不近。庶人不服。其質非不美也。所漸者然也。大戴禮同。謂久泔臰薉也。內則滫𤅵注。秦人溲曰滫。此則別是湯液之類。與久泔異實同名。秦人方言也。"}]},"澱":{"expl":"滓滋也。从水殿聲。","rad":"水","fq":"堂練切","vol":"11","py":"diàn","duan":[{"e":"滓垽也。","n":"釋器曰。澱謂之垽。土部曰。垽、澱也。黑部曰。？謂之垽。按𪑩與澱異字而音義同。實則一字也。"}]},"淤":{"expl":"澱滓，濁泥。从水於聲。","rad":"水","fq":"依據切","vol":"11","py":"yū","duan":[{"e":"澱滓濁泥也。","n":"方言。水中可居爲洲。三輔謂之淤。其引伸之義也。"}]},"滓":{"expl":"澱也。从水宰聲。","rad":"水","fq":"阻史切","vol":"11","py":"zǐ","duan":[{"e":"澱也。","n":"釋名曰。緇、滓也。泥之黑者曰滓。此色然也。廣雅曰。澱謂之滓。按古亦假滓爲緇。"}]},"淰":{"expl":"濁也。从水念聲。","rad":"水","fq":"乃忝切","vol":"11","py":"niǎn","duan":[{"e":"濁也。","n":"義與澱淤滓相類。禮運曰。龍以爲畜。故魚鮪不淰。注。淰之言閃也。凡云之言者、皆假其音以得其義。葢濁其本義、閃其引伸假借之義也。衆經音義引埤倉淰、水無波也。杜詩。山霧戎戎溼。溪雲淰淰寒。戎戎言其流動。淰淰言其凝滯。水無波之義之引伸也。"}]},"瀹":{"expl":"漬也。从水龠聲。","rad":"水","fq":"以灼切","vol":"11","py":"yuè","duan":[{"e":"漬也。","n":"此葢謂納於汚濁也。故廁於此。孟子。瀹濟漯。言浚治其污濁也。瀹與？同音而義近。故皆假瀹爲？。今人曰煠。助甲切。古人曰瀹。亦作汋。詳𩰲部。"}]},"𤃭":{"expl":"釃酒也。一曰浚也。从网从水，焦聲。讀若《夏書》“天用勦絕”。","rad":"水","fq":"子小切","vol":"11","py":"jiǎo","duan":[{"e":"釃酒也。","n":"釃、下酒也。卽今之漉酒也。以筐曰釃。"}]},"漀":{"expl":"側出泉也。从水殸聲。殸，籒文磬字。","rad":"水","fq":"去挺切","vol":"11","py":"qǐnɡ","duan":[{"e":"側出泉也。","n":"側出者、旁出。如醡出然。故其字與？湑爲類。爾雅釋水曰。氿泉穴出。穴出、仄出也。毛傳。側出曰氿泉。許厂部曰。晷、仄出泉也。厬與氿音同字異。漀者、厬之一名也。"}]},"牭":{"expl":"四歲牛。从牛从四，四亦聲。","rad":"牛","fq":"息利切","vol":"02","py":"sì","duan":[{"e":"四歲牛。从牛四。四亦聲。","n":"息利切。十五部。"}]},"湑":{"expl":"莤酒也。一曰浚也。一曰露皃。从水胥聲。《詩》曰：“有酒湑我。” 又曰：“零露湑兮。”","rad":"水","fq":"私呂切","vol":"11","py":"xǔ","duan":[{"e":"莤酒也。","n":"小雅伐木云。釃酒有藇。傳曰。以筐曰釃。以藪曰湑。又云。有酒湑我。傳曰。湑、莤之也。按毛、許釃莤皆有別。酉部云。莤者、禮祭束茅加於祼圭而灌鬯酒。是爲莤。與鄭大夫甸師注合。是則毛傳湑訓以藪莤之藪。謂艸如祭之用茅也。故亦曰莤。"}]},"湎":{"expl":"沈於酒也。从水面聲。《周書》曰：“罔敢湎于酒。”","rad":"水","fq":"彌兖切","vol":"11","py":"miǎn","duan":[{"e":"湛於酒也。","n":"湛各本作沈。此等皆後人以習用改之耳。沈㲻於酒、周易所謂飲酒濡首、亦不知節也。韓詩云。飲酒閉門不出客曰湎。樂記。流湎以忘本。其引伸之義也。"}]},"𤖅":{"expl":"酢𤖅也。从水，將省聲。","rad":"水","fq":"卽良切","vol":"11","py":"jiānɡ","duan":[{"e":"酢𤖅也。","n":"周禮酒正四飲。漿人掌共王之六飲。皆有漿。注云。漿、今之酨漿也。內則注云。漿、酢酨也。按酉部云。酨、酢漿也。則漿酨二字互訓。"}]},"涼":{"expl":"薄也。从水京聲。","rad":"水","fq":"呂張切","vol":"11","py":"liánɡ","duan":[{"e":"薄也。","n":"涼廁於此者、謂六飲之涼與漿爲類也。鄭司農云。涼、以水和酒也。玄謂涼、今寒粥若糗飯襍水也。許云薄也。葢薄下奪一酒字。以水和酒。故爲薄酒。此用大鄭說也。引伸之爲凡薄之稱。如職涼善背、虢多涼徳。毛、杜皆云涼薄是也。薄則生寒。又引伸爲寒。如北風其涼是也。至字林乃云涼、微寒也。唐殷敬順引之。廣韵、玉篇皆云。凉俗涼字。至集韵乃特出凉字。注云。薄寒曰凉。"}]},"淡":{"expl":"薄味也。从水炎聲。","rad":"水","fq":"徒敢切","vol":"11","py":"dàn","duan":[{"e":"薄味也。","n":"醲之反也。酉部曰。醲、厚酒也。又澹淡亦作淊淡。水滿皃。楊雄賦。秬鬯泔淡。應劭曰。泔淡、滿也。按泔淡訓滿、謂淡爲贍之假借。"}]},"涒":{"expl":"食已而復吐之。从水君聲。《爾雅》曰：“太歲在申曰涒灘。”","rad":"水","fq":"他昆切","vol":"11","py":"tūn","duan":[{"e":"食巳而復吐之。","n":"未聞。江賦涒粼、謂水皃。"}]},"澆":{"expl":"𣵽也。从水堯聲。","rad":"水","fq":"古堯切","vol":"11","py":"jiāo","duan":[{"e":"𣵽也。","n":"沃爲澆之大。澆爲沃之細。故不類廁。凡醲者、澆之則薄。故其引伸之義爲薄。漢書循吏傳。澆淳散樸。"}]},"液":{"expl":"𧗁也。从水夜聲。","rad":"水","fq":"羊益切","vol":"11","py":"yè","duan":[{"e":"𧗃也。","n":"血部曰。𧗃、气液也。按樂記注曰。永歎淫液歌遲之也。考工記春液角。鄭司農液讀爲醳。謂重繹治之。此皆引伸之義也。"}]},"汁":{"expl":"液也。从水十聲。","rad":"水","fq":"之入切","vol":"11","py":"zhī","duan":[{"e":"液也。","n":"古經傳多假汁爲叶。方言曰。斟、協、汁也。北燕朝鮮洌水之閒曰斟。自關而東曰協。關西曰汁。此兼瀋汁和叶而言。如台朕賚畀卜陽予也之例。汁液必出於和協。故其音義通也。"}]},"滒":{"expl":"多汁也。从水哥聲。讀若哥。","rad":"水","fq":"古俄切","vol":"11","py":"ɡē","duan":[{"e":"多汁也。","n":"淮南原道訓曰。甚淖而滒。高云。滒亦淖也。饘粥多瀋者曰滒。讀歌謳之歌。按今江蘇俗語謂之稠也。"}]},"犗":{"expl":"騬牛也。从牛害聲。","rad":"牛","fq":"古拜切","vol":"02","py":"jiè","duan":[{"e":"騬牛也。","n":"馬部曰。騬、犗馬也。謂今之騸馬。"}]},"灝":{"expl":"豆汁也。从水顥聲。","rad":"水","fq":"乎老切","vol":"11","py":"hào","duan":[{"e":"豆汁也。","n":"豆者、尗也。"}]},"溢":{"expl":"器滿也。从水益聲。","rad":"水","fq":"夷質切","vol":"11","py":"yì","duan":[{"e":"器滿也。","n":"禮經一溢米注。二十兩曰溢。按謂二十兩溢者、謂滿於一斤、十六兩之外也。後人因製鎰字。"}]},"洒":{"expl":"滌也。从水西聲。古文爲灑埽字。","rad":"水","fq":"先禮切","vol":"11","py":"xǐ","duan":[{"e":"滌也。","n":"下文云沬、洒面也。浴、洒身也。澡、洒手也。洗、洒足也。今人假洗爲洒。非古字。按古有假洒爲峻陗之峻者。如詩新臺有洒。爾雅望厓洒而高岸。夷上洒下漘。毛詩洒、高峻也。"}]},"滌":{"expl":"洒也。从水條聲。","rad":"水","fq":"徙歴切","vol":"11","py":"dí","duan":[{"e":"洒也。","n":"皿部曰。盪、滌器也。引伸爲凡淸瀞之䛐。如七月傳曰。滌場、埽地。雲漢傳曰。滌滌、旱氣也。山無木、川無水是。"}]},"濈":{"expl":"和也。从水戢聲。","rad":"水","fq":"阻立切","vol":"11","py":"jí","duan":[{"e":"和也。","n":"小雅。爾羊來思。其角濈濈。傳曰。聚其角而息、濈濈然也。按毛意言角之多。葢言聚而和也。如輯之訓聚、兼訓和。"}]},"瀋":{"expl":"汁也。从水審聲。《春秋傳》曰：“猶拾瀋。”","rad":"水","fq":"昌枕切","vol":"11","py":"shěn","duan":[{"e":"汁也。","n":"左傳哀三年曰。無備而官辦者。猶拾瀋也。杜云。瀋、汁也。陸徳明云。北土呼汁爲瀋。按禮記檀弓爲榆沈、假沈爲瀋。"}]},"渳":{"expl":"飲也。从水弭聲。","rad":"水","fq":"緜婢切","vol":"11","py":"mǐ","duan":[{"e":"飲歃也。","n":"周禮。王𡹔大肆。以秬鬯渳。杜子春讀渳爲泯。以秬鬯浴屍也。按浴屍則釁屍口鼻。與飲歃義相近。"}]},"𤀤":{"expl":"飲歃也。一曰吮也。从水算聲。","rad":"水","fq":"衫洽切","vol":"11","py":"shà","duan":[{"e":"飲歃也。","n":"歃、歠也。"}]},"漱":{"expl":"盪口也。从水欶聲。","rad":"水","fq":"所右切","vol":"11","py":"shù","duan":[{"e":"盪口也。","n":"漱者、欶之大也。盪口者、吮刷其口中也。曲禮。諸母不潄裳。假漱爲涑也。"}]},"泂":{"expl":"滄也。从水冋聲。","rad":"水","fq":"戶褧切","vol":"11","py":"jiǒnɡ","duan":[{"e":"滄也。","n":"此義俗从仌作？。篇、韵？皆訓冷是也。大雅。泂酌彼行潦。毛曰。泂、遠也。此謂泂卽迥之假借也。江賦？漲𢧵泂、同。"}]},"牻":{"expl":"白黑雜毛牛。从牛尨聲。","rad":"牛","fq":"莫江切","vol":"02","py":"mánɡ","duan":[{"e":"白黑襍毛牛。","n":"古謂襍色不純爲尨。亦作駹。古文假借作龍。亦作蒙。周易說卦傳、毛詩小戎、周禮牧人巾車玉人皆可證也。牻訓爲白黑襍毛。然則凡謂襍色不純亦可用牻字。"}]},"滄":{"expl":"寒也。从水倉聲。","rad":"水","fq":"七岡切","vol":"11","py":"cānɡ","duan":[{"e":"寒也。","n":"周書周祝解曰。天地之閒有滄𤍽。列子湯問。一兒曰。日初出、滄滄涼涼。仌部凔字音義同。"}]},"㵾":{"expl":"冷寒也。从水靚聲。","rad":"水","fq":"七定切","vol":"11","py":"qìnɡ","duan":[{"e":"冷寒也。","n":"冷寒者、冷之寒同寒而有別也。世說新語曰。劉眞長始見王丞相。時盛暑之月。丞相以腹熨彈棋局曰。何乃渹。劉旣出。人問見王公云何。劉曰。未見他異。惟聞作吳語耳。注云。吳人以冷爲渹。大平御覽引此事、渹作㵾。集韵、類篇皆云㵾渹二同。楚慶切。吳人謂冷也。今吳俗謂冷物附他物、其語如鄭國之鄭。卽㵾字也。"}]},"淬":{"expl":"滅火器也。从水卒聲。","rad":"水","fq":"七內切","vol":"11","py":"cuì","duan":[{"e":"滅火器也。","n":"滅火器者、葢以器盛水濡火使滅。其器謂之淬。與火部之焠義略相近。故焠通作淬。"}]},"沐":{"expl":"濯髮也。从水木聲。","rad":"水","fq":"莫卜切","vol":"11","py":"mù","duan":[{"e":"濯髮也。","n":"引伸爲芟除之義。如管子云沐涂樹之枝。釋名云沐秃無上皃之稱。"}]},"沬":{"expl":"洒面也。从水未聲。","rad":"水","fq":"荒內切","vol":"11","py":"huì","duan":[{"e":"洒面也。","n":"律歷志引顧命曰。王乃洮沬水。師古曰。沬、洗面也。禮樂志。霑赤汗。沬流赭。晉灼曰。沬、古靧字。檀弓。瓦不成味。鄭云。味當作沬。沬、靧也。按此沬謂瓦器之釉、如洗面之光澤也。"}]},"浴":{"expl":"洒身也。从水谷聲。","rad":"水","fq":"余蜀切","vol":"11","py":"yù","duan":[{"e":"洒身也。","n":"老子。浴神不死。河上公曰。浴、養也。夏小正。黑鳥浴。浴也者、飛乍高乍下也。皆引伸之義也。"}]},"澡":{"expl":"洒手也。从水喿聲。","rad":"水","fq":"子皓切","vol":"11","py":"zǎo","duan":[{"e":"洒手也。","n":"皿部曰。盥、澡手也。儒行篇曰。澡身而浴徳。其引伸之義。按或假繰爲澡。如禮記緦冠繰纓是。荀卿又作慅纓。"}]},"洗":{"expl":"洒足也。从水先聲。","rad":"水","fq":"穌典切","vol":"11","py":"xiǎn","duan":[{"e":"洒足也。","n":"洒俗本作灑。誤。今依宋本正。內則曰。面垢。燂潘請靧。足垢。燂湯請洗。此洒面曰靧、洒足曰洗之證也。洗讀如跣足之跣。自後人以洗代洒滌字。讀先禮切。沿至近日以洒代灑、轉同詩禮之用矣。"}]},"汲":{"expl":"引水於井也。从水从及，及亦聲。","rad":"水","fq":"居立切","vol":"11","py":"jí","duan":[{"e":"引水也。","n":"各本有於井二字。今依玄應引及玉篇訂。其器曰缾、曰罋。其引罋之繩曰綆、曰繘。井九三曰。可以汲。引伸之、凡擢引皆曰汲。廣雅曰。汲、取也。古書多用汲汲爲彶彶。同音假借。"}]},"淳":{"expl":"渌也。从水𦎫聲。","rad":"水","fq":"常倫切","vol":"11","py":"chún","duan":[{"e":"淥也。","n":"上文曰。淥、或漉字。似？淋二篆宜類廁。恐轉寫者亂之也。內則、考工記注皆曰。淳、沃也。按㡆氏而沃之。卽上文之渥淳其帛也。內則淳熬、淳模之名。因沃之以膏也。然則許云淥也、謂淥之後一義。"}]},"㹁":{"expl":"牻牛也。从牛京聲。《春秋傳》曰：“牻㹁。”","rad":"牛","fq":"呂張切","vol":"02","py":"liánɡ","duan":[{"e":"牻牛也。从牛。京聲。","n":"吕張切。十部。"}]},"淋":{"expl":"以水𣵽也。从水林聲。一曰淋淋，山下水皃。","rad":"水","fq":"力尋切","vol":"11","py":"lín","duan":[{"e":"㠯水𣵽也。","n":"今俗語皆爾。郭樸注三倉曰。淋、漉水下也。"}]},"渫":{"expl":"除去也。从水枼聲。","rad":"水","fq":"私列切","vol":"11","py":"xiè","duan":[{"e":"除去也。","n":"井九三曰。井渫不食。荀爽曰。渫去穢濁。淸潔之意也。按凡言泄漏者、卽此義之引伸。變其字爲泄耳。"}]},"𤃬":{"expl":"濯衣垢也。从水𧹳聲。","rad":"水","fq":"胡玩切","vol":"11","py":"huàn","duan":[{"e":"濯衣垢也。","n":"周南箋云。澣謂濯之。半澣曰湔。見上文。"}]},"濯":{"expl":"𤃬也。从水翟聲。","rad":"水","fq":"直角切","vol":"11","py":"zhuó","duan":[{"e":"𤃬也。","n":"崧高傳曰。濯濯、光明也。靈臺傳曰。濯濯、娱遊也。皆引伸之義也。有假洮爲濯者。如鄭注顧命之洮爲澣衣成事是也。周禮故書以濯爲祧。爾雅以濯爲珧。史、漢以輯濯爲楫櫂。皆古文假借。"}]},"涑":{"expl":"𤃬也。从水束聲。河東有涑水。","rad":"水","fq":"速矦切","vol":"11","py":"sōu","duan":[{"e":"𤃬也。","n":"涑、亦假漱爲之。公羊傳。臨民之所漱浣也。何曰。無垢加功曰漱。去垢曰浣。齊人語。解云。無垢加功、謂但用手斗漱。去垢葢用足物。故內則云。冠帶垢、和灰請漱。衣裳垢、和灰請澣。鄭云手曰漱、足曰澣是也。若然則涑與澣別。而許不別者、許渾言、何析言也。毛詩周南箋云。汙、煩也。煩撋之用功深。澣謂濯之耳。是則澣對汙言、又分深淺。實則何之去垢、卽毛詩之汙。何之無垢加功、卽毛詩之澣。古人因義立文。後人當因文攷義耳。上文湔篆下云。一曰手澣。巳依水經注訂手爲半。依諸家用手曰涑之云則作手固未嘗非是。"}]},"潎":{"expl":"於水中擊絮也。从水敝聲。","rad":"水","fq":"匹蔽切","vol":"11","py":"pì","duan":[{"e":"於水中擊絮也。","n":"擊當爲撆。撆潎同音。手部曰。撆、㕞也。一曰擊也。似㕞義於此爲近。考工記注曰湖漂絮。荘子曰汧澼絖。皆謂於水面漂撆之。竹部曰。𥮒、潎絮簀也。糸部曰。紙、絮一𥮒也。然則撆絮乃造紙之先聲。亦謂之漂。史記。韓信釣於城下。諸母漂。漂與潎雙聲爲轉注。漂孚妙切。玉篇及曹憲注廣雅乃合潎漂爲一字。同切孚妙。誤矣。"}]},"㙙":{"expl":"涂也。从水从土，尨聲。讀若隴。","rad":"水","fq":"","vol":"11","py":"lǒnɡ","duan":[]},"灑":{"expl":"汛也。从水麗聲。","rad":"水","fq":"山豉切","vol":"11","py":"sǎ","duan":[{"e":"𣲌也。","n":"凡埽者先灑。弟子職云。實水於盤。攘臂袂及肘。堂上則播灑。室中握手是也。引伸爲凡散之稱。"}]},"汛":{"expl":"灑也。从水卂聲。","rad":"水","fq":"息晉切","vol":"11","py":"xùn","duan":[{"e":"灑也。","n":"卂、疾飛也。水之散如飛。此以形聲包會意也。楊雄劇秦美新云。况盡𣲌埽前聖數千載功業。𣲌埽、卽灑埽也。俗用爲潮𣲌字。"}]},"染":{"expl":"以繒染爲色。从水杂聲。","rad":"水","fq":"而𤥎切","vol":"11","py":"rǎn","duan":[{"e":"㠯繪染爲色。","n":"此據周禮染人言也。染人掌染絲帛。繪者、帛也。不言絲者、舉帛以該絲也。夏纁玄。秋染夏。"}]},"犡":{"expl":"牛白𦟝也。从牛厲聲。","rad":"牛","fq":"洛帶切","vol":"02","py":"lì","duan":[{"e":"牛白脊也。从牛。厲聲。","n":"洛帶切。十五部。"}]},"泰":{"expl":"滑也。从廾从水，大聲。","rad":"水","fq":"他蓋切","vol":"11","py":"tài","duan":[{"e":"滑也。","n":"此以曡韵爲訓。字从𠬞水。水在手中。下澑甚利也。與辵部達字義近。皆他達切。周易泰、通也。否、塞也。左傳汏輈及鼓跗著于丁寧、汏輈以貫笠轂。皆滑之意也。滑則寛裕自如。故引伸爲縱泰。如論語泰而不驕是也。又引伸爲泰侈。如左傳之汏侈、西京賦之心奓體泰是也。汏卽泰之隸省。隸變而與淅米之汏同形。作汰者誤字。"}]},"㶄":{"expl":"海岱之閒謂相汙曰㶄。从水閻聲。","rad":"水","fq":"余廉切","vol":"11","py":"yán","duan":[{"e":"海岱之閒謂相污曰㶄。","n":"方言。氾浼㶄洼洿也。自關而東或曰洼。或曰氾。東濟海岱之閒或曰浼。或曰㶄、按洿污古通用。子雲義取污薉。許說及廣雅皆从之。郭注以洿池釋之。非也。"}]},"灒":{"expl":"汙灑也。一曰水中人。从水贊聲。","rad":"水","fq":"則旰切","vol":"11","py":"zàn","duan":[{"e":"污灑也。","n":"謂用污水揮灑也。釋玄應曰。江南言灒、子旦反。山東言湔、子見反。史記廉藺傳作濺。楊泉物理論作？。皆音于旦反。"}]},"㵞":{"expl":"腹中有水气也。从水从愁，愁亦聲。","rad":"水","fq":"士尤切","vol":"11","py":"chóu","duan":[{"e":"腹中有水气也。从水。愁聲。","n":"士尤切。三部。"}]},"湩":{"expl":"乳汁也。从水重聲。","rad":"水","fq":"多貢切","vol":"11","py":"dònɡ","duan":[{"e":"乳汁也。","n":"見列子、穆天子傳。或借重字爲之。漢書匈奴傳重酪之便美是也。管子。湩然擊皷士忿怒。借湩爲？也。周禮注湩容、卽毛詩傳之童容也。"}]},"洟":{"expl":"鼻液也。从水夷聲。","rad":"水","fq":"他計切","vol":"11","py":"tì","duan":[{"e":"鼻液也。","n":"易萃上六。齎咨涕洟。鄭注。自目曰涕。自鼻曰洟。檀弓。垂涕洟。正義。目垂涕。鼻垂洟。詩陳風。涕泗滂沱。毛傳。自目曰涕。自鼻曰泗。泗卽洟之假借字也。古書弟夷二字多相亂。於是謂自鼻出者曰涕。而自目出者別製淚字。皆許不取也。素問謂目之水爲淚。謂腦滲爲涕。王襃童約。目淚下落。鼻涕長一尺。曹娥碑。泣淚掩涕。驚動國都。漢魏所用已如此。"}]},"潸":{"expl":"涕流皃。从水，𢿱省聲。《詩》曰：“潸焉出涕。”","rad":"水","fq":"所姦切","vol":"11","py":"shān","duan":[{"e":"涕流皃。","n":"小雅大東曰。潸焉出涕。毛云。潸、涕下皃。"}]},"汗":{"expl":"人液也。从水干聲。","rad":"水","fq":"矦旰切","vol":"11","py":"hàn","duan":[{"e":"身液也。","n":"身各本作人。今依太平御覽訂。易。渙汗其大號。劉向說曰。汗出而不反者也。"}]},"泣":{"expl":"無聲出涕曰泣。从水立聲。","rad":"水","fq":"去急切","vol":"11","py":"qì","duan":[{"e":"無聲出涕者曰泣。","n":"依韵會所據小徐本訂。者、別事䛐也。哭下曰。哀聲也。其出涕不待言。其無聲出涕者爲泣。此哭泣之別也尚書大傳曰。微子將往朝周。過殷之故墟。志動心悲。欲哭則爲朝周。俯泣則近婦人。推而廣之作雅聲。謂之麥秀歌。"}]},"涕":{"expl":"泣也。从水弟聲。","rad":"水","fq":"他禮切","vol":"11","py":"tì","duan":[{"e":"泣也。","n":"按泣也二字、當作目液也三字。轉寫之誤也。毛傳皆云。自目出曰涕。篇、韵皆云。目汁。泣非其義。"}]},"祧":{"expl":"遷廟也。从示兆聲。","rad":"示","fq":"他彫切","vol":"01","py":"tiāo","duan":[]},"𤙛":{"expl":"黃牛虎文。从牛余聲。讀若塗。","rad":"牛","fq":"同都切","vol":"02","py":"tú","duan":[{"e":"黃牛虎文。从牛。余聲。讀若塗。","n":"塗當作涂。同都切。五部。"}]},"湅":{"expl":"㶕也。从水柬聲。","rad":"水","fq":"郎甸切","vol":"11","py":"liàn","duan":[{"e":"𤄒也。","n":"周禮染人。凡染、春暴練。注云。暴練、練其素而暴之。按此練當作湅。湅其素。素者、質也。卽㡆氏之湅絲、練帛也。已湅之帛曰練。糸部練下云湅繒也是也。㡆氏如法湅之、暴之。而後絲帛之質精。而後染人可加染。湅之以去其瑕。如㶕米之去康粊。其用一也。故許以㶕釋湅。戰國䇿。蘇秦得大公陰符之謀。伏而誦之。簡練以爲揣磨。簡練者、㶕湅之假借也。高誘曰。簡、汏也。練、濯治也。正與許云㶕淅也、淅汏米也、湅㶕也相符合。許不以湅㶕二篆爲伍者、㶕謂米、湅謂絲帛也。金部治金曰鍊。猶治絲帛曰湅。"}]},"𤅊":{"expl":"議辠也。从水、獻。與法同意。","rad":"水","fq":"魚列切","vol":"11","py":"niè","duan":[{"e":"議辠也。","n":"文王世子。獄成。有司讞於公。其死罪。則曰某之罪在大辟。其㓝罪。則曰某之罪在小辟。鄭曰。成、平也。讞、言白也。按今本注作讞之言白也。之字衍。以徐邈云言也、正義云言白也正之。當是本作言也、白也。正義省一也字耳。言與讞雙聲曡韵。王制。百官各以其成質於三官。大司徒、大司馬、大司空以百官之成質於天子。此云以成讞於公、猶以成質於天子也。故其字从水獻。其議如水之平而獻於上也。所質旣下爲受質。所讞不當而上更議之亦爲讞。葢本下獻上之詞、又轉爲上平下之詞矣。漢書云諸獄疑於人心不厭者輒讞之是。"}]},"渝":{"expl":"變汙也。从水俞聲。一曰渝水，在遼西臨俞，東出塞。","rad":"水","fq":"羊朱切","vol":"11","py":"yū","duan":[{"e":"變污也。","n":"釋言曰。渝、變也。鄭風傳、虞翻注易、杜注左傳皆同。許謂瀞而變污。"}]},"減":{"expl":"損也。从水咸聲。","rad":"水","fq":"古斬切","vol":"11","py":"jiǎn","duan":[{"e":"損也。","n":"古書多假咸爲減。"}]},"滅":{"expl":"盡也。从水𤇳聲。","rad":"水","fq":"亡列切","vol":"11","py":"miè","duan":[{"e":"盡也。从水。烕聲。","n":"此舉形聲包會意。亡列切。十五部。"}]},"漕":{"expl":"水轉轂也。一曰人之所乘及船也。从水曹聲。","rad":"水","fq":"在到切","vol":"11","py":"cáo","duan":[{"e":"水轉穀也。","n":"穀各本譌轂。今依韵會、平準書索隱、蕪城賦注訂。如淳漢書注曰。水轉曰漕。百官志曰。大倉令主受郡國傳漕穀。"}]},"泮":{"expl":"諸矦鄉射之宮，西南爲水，東北爲牆。从水从半，半亦聲。","rad":"水","fq":"普半切","vol":"11","py":"pàn","duan":[{"e":"諸矦饗射之宫。","n":"諸矦上當有泮宫二字。饗大徐作鄉。今依小徐。饗者、謂鄉飲酒也。詩行葦、泮水皆言諸矦鄉飲酒之禮。見鄭箋。古者養老之禮、卽鄉飲酒之禮也。公劉先射而後養老。故曰饗射。廱篆下曰。天子饗飲辟廱。亦謂鄉飲酒。不言射者、言饗以關射。五經異義引韓詩說。辟雍所以教天下。春射秋饗。尊事三老五更。魯頌曰。思樂泮水。又曰。旣作泮宫。毛曰。泮水、泮宫之水也。天子辟廱。諸矦泮宫。王制曰。天子曰辟廱。諸矦曰頖宫。鄭云。辟、明也。廱、和也。所以明和天下。頖之言班也。所以班政教也。許書無頖字。葢禮家製頖字、許不取也。小戴三云頖官。"}]},"漏":{"expl":"以銅受水，刻節，晝夜百刻。从水屚聲。","rad":"水","fq":"盧后切","vol":"11","py":"lòu","duan":[{"e":"㠯銅受水。刻節。晝夜百節。","n":"百節各本作百刻。今依韵會所據小徐本訂。晝夜以百節之。故爲刻者百。因𧦝百刻矣。周禮挈壼氏。凡喪、縣壼以百代哭者。皆以水火守之。分以日夜。注云。以水守壼者、爲沃漏也。以火守壼者、夜則視刻數也。分以日夜者、異晝夜漏也。漏之箭、晝夜共百刻。冬夏之閒有長短焉。文選注引司馬彪曰。孔壼爲漏。浮箭爲刻。下漏數刻。以考中星、昏明星焉。按晝夜百刻。每刻爲六小刻。每小刻又十分之。故晝夜六千分。每大刻六十分也。其散於十二辰。每一辰八大刻、二小刻。共得五百分也。此是古法。樂記。百度得數而有常。注云。百度、百刻也。靈樞經。漏水下百刻。以分晝夜。"}]},"澒":{"expl":"丹沙所化，爲水銀也。从水項聲。","rad":"水","fq":"呼孔切","vol":"11","py":"hònɡ","duan":[{"e":"丹沙所化爲水銀也。","n":"本艸經曰。鎔化還復爲丹。然則本丹之所化明矣。後代燒煅麄次朱砂爲之。淮南書高注曰。白澒、水銀也。廣雅曰。水銀謂之澒。字一作汞。說者分別之云。汞、水銀滓。"}]},"萍":{"expl":"苹也。水艸也。从水、苹，苹亦聲。","rad":"水","fq":"薄經切","vol":"11","py":"pínɡ","duan":[{"e":"苹也。","n":"苹蓱二篆見艸部。篇、韵皆云。萍蓱同字。疑許書本有萍無蓱。小正、毛詩、爾雅皆作苹。爾雅、毛傳皆曰蓱也。蓱卽萍之別字。周禮萍氏、疑本作苹氏。然則說文艸部苹下曰萍也、與水部萍下曰苹也爲轉注。不當有蓱篆。"}]},"犖":{"expl":"駁牛也。从牛，勞省聲。","rad":"牛","fq":"呂角切","vol":"02","py":"luò","duan":[{"e":"駁牛也。","n":"馬色不純曰駁。駁犖同部㬪韵。廣雅牛屬。郭㸨、丁犖、桓譚新論作郭椒、丁櫟。㸨椒、犖櫟皆同韵也。"}]},"濊":{"expl":"水多皃。从水歲聲。","rad":"水","fq":"呼會切","vol":"11","py":"huì","duan":[{"e":"礙流也。","n":"有礙之流也。衛風。施罛濊濊。毛曰。罛、魚罟。濊濊、施之水中。按施罟而水仍流。故曰礙流。礙流者、言礙而不礙也。韓詩云流貌。與毛許一也。濊又訓多水貌。司馬相如傳。湛恩汪濊。"}]},"汩":{"expl":"治水也。从水曰聲。","rad":"水","fq":"于筆切","vol":"11","py":"ɡǔ","duan":[{"e":"治水也。","n":"天問。不任汩鴻。師何以尚之。王云。汩、治也。鴻、大水也。引伸之、凡治皆謂汩。書序汨作。汩、治也。汩本訓亂。如亂之訓治。故洪範汩陳其五行。汩、亂也。上文淈訓濁。而釋詁云。淈、治也。郭景純云。淈汩同。"}]},"瀼":{"expl":"露濃皃。从水襄聲。","rad":"水","fq":"汝羊切","vol":"11","py":"ránɡ","duan":[]},"漙":{"expl":"露皃。从水專聲。","rad":"水","fq":"度官切","vol":"11","py":"tuán","duan":[]},"汍":{"expl":"泣淚皃。从水丸聲。","rad":"水","fq":"胡官切","vol":"11","py":"wán","duan":[]},"泯":{"expl":"滅也。从水民聲。","rad":"水","fq":"武盡切","vol":"11","py":"mǐn","duan":[]},"瀣":{"expl":"沆韰，气也。从水，䪥省聲。","rad":"水","fq":"胡介切","vol":"11","py":"xiè","duan":[]},"瀘":{"expl":"水名。从水盧聲。","rad":"水","fq":"洛乎切","vol":"11","py":"lú","duan":[]},"瀟":{"expl":"水名。从水蕭聲。","rad":"水","fq":"相邀切","vol":"11","py":"xiāo","duan":[]},"瀛":{"expl":"水名。从水嬴聲。","rad":"水","fq":"以成切","vol":"11","py":"yínɡ","duan":[]},"㸹":{"expl":"牛白𦟝也。从牛寽聲。","rad":"牛","fq":"力輟切","vol":"02","py":"liè","duan":[{"e":"牛白脊也。","n":"牛惟脊白。是亦駁屬。廣韵曰。㸹出字林。不言出說文何也。"}]},"滁":{"expl":"水名。从水除聲。","rad":"水","fq":"直魚切","vol":"11","py":"chú","duan":[]},"洺":{"expl":"水名。从水名聲。","rad":"水","fq":"武幷切","vol":"11","py":"mínɡ","duan":[]},"潺":{"expl":"水聲。从水孱聲。","rad":"水","fq":"昨閑切","vol":"11","py":"chán","duan":[]},"湲":{"expl":"潺湲，水聲。从水爰聲。","rad":"水","fq":"王權切","vol":"11","py":"yuán","duan":[]},"濤":{"expl":"大波也。从水壽聲。","rad":"水","fq":"徒刀切","vol":"11","py":"tāo","duan":[]},"漵":{"expl":"水浦也。从水敘聲。","rad":"水","fq":"徐吕切","vol":"11","py":"xù","duan":[]},"港":{"expl":"水派也。从水䢽聲。","rad":"水","fq":"古項切","vol":"11","py":"ɡǎnɡ","duan":[]},"瀦":{"expl":"水所亭也。从水豬聲。","rad":"水","fq":"陟魚切","vol":"11","py":"zhū","duan":[]},"𤅤":{"expl":"大水也。从水镾聲。","rad":"水","fq":"武移切","vol":"11","py":"mí","duan":[]},"淼":{"expl":"大水也。从三水。或作渺。","rad":"水","fq":"亡沼切","vol":"11","py":"miǎo","duan":[]},"𤘾":{"expl":"牛駁如星。从牛平聲。","rad":"牛","fq":"普耕切","vol":"02","py":"pēnɡ","duan":[{"e":"牛駁如星。","n":"駁文似星㸃。"}]},"潔":{"expl":"瀞也。从水絜聲。","rad":"水","fq":"古屑切","vol":"11","py":"jié","duan":[]},"浹":{"expl":"洽也。从也。从水夾聲。","rad":"水","fq":"子協切","vol":"11","py":"jiā","duan":[]},"溘":{"expl":"奄忽也。从水盍聲。","rad":"水","fq":"口荅切","vol":"11","py":"kè","duan":[]},"潠":{"expl":"含水噴也。从水巽聲。","rad":"水","fq":"穌困切","vol":"11","py":"xùn","duan":[]},"涯":{"expl":"水邊也。从水从厓，厓亦聲。","rad":"水","fq":"魚羈切","vol":"11","py":"yá","duan":[]},"沝":{"expl":"二水也。闕。凡沝之屬皆从沝。","rad":"沝","fq":"之壘切","vol":"11","py":"zhuǐ","duan":[{"e":"二水也。","n":"卽形而義在焉。"}]},"𣹭":{"expl":"水行也。从沝、㐬。㐬，突忽也。","rad":"沝","fq":"力求切","vol":"11","py":"liú","duan":[{"e":"水行也。从沝㐬。","n":"會意。力求切。三部。"}]},"𣻣":{"expl":"徒行厲水也。从沝从步。","rad":"沝","fq":"時攝切","vol":"11","py":"shè","duan":[{"e":"徒行濿水也。","n":"濿各本作厲。誤。濿、或砅字也。砅本履石渡水之偁。引申爲凡渡水之偁。釋水曰。繇膝以上爲涉。毛傳同。許云徒行者、以別於以車及方之、舟之也。許意詩所言揭、厲皆徒行也。皆涉也。故字从步。"}]},"瀕":{"expl":"水厓。人所賓附，頻蹙不前而止。从頁从涉。凡頻之屬皆从頻。","rad":"瀕","fq":"符眞切","vol":"11","py":"pín","duan":[{"e":"水厓、人所賔附也。","n":"厓今之涯字。附當作駙。馬部曰。駙、近也。瀕賔以㬪韵爲訓。瀕今字作濵。召旻傳曰。瀕、厓也。采蘋、北山傳皆曰。濵、厓也。今字用頻訓數。攷桑柔傳曰頻、急也。廣雅曰頻頻、比也。此從附近之義引申之。本無二字二音。而今字妄爲分別。積習生常矣。"}]},"顰":{"expl":"涉水顰蹙。从頻卑聲。","rad":"瀕","fq":"符眞切","vol":"11","py":"pín","duan":[{"e":"涉水𩖓戚也。","n":"戚古音同蹴。迫也。各本作蹙。誤。顰戚、謂顰眉蹙頞也。許必言涉水者、爲其字之从瀕也。"}]},"犥":{"expl":"牛黃白色。从牛麃聲。","rad":"牛","fq":"補嬌切","vol":"02","py":"piāo","duan":[{"e":"牛黃白色。","n":"黃馬發白色曰驃。票？同聲然則犥者、黃牛發白色也。內則鳥皫色、亦謂發白色。"}]},"𡿨":{"expl":"水小流也。《周禮》：“匠人爲溝洫，㭒廣五寸，二㭒爲耦；一耦之伐，廣尺、深尺，謂之𡿨。”倍𡿨謂之遂；倍遂曰溝；倍溝曰洫；倍洫曰巜。凡𡿨之屬皆从𡿨。","rad":"𡿨","fq":"姑泫切","vol":"11","py":"quǎn","duan":[{"e":"水小流也。","n":"水部曰。涓、小流也。𡿨與涓音義同。釋名曰。山下根之受𩅸處曰甽。甽、吮也。吮得山之肥潤也。按此爲禹貢羽畎、岱畎之說解。亦卽小流之義。"}]},"巜":{"expl":"水流澮澮也。方百里爲巜，廣二尋，深二仞。凡巜之屬皆从巜。","rad":"巜","fq":"古外切","vol":"11","py":"kuài","duan":[{"e":"水流澮澮也。","n":"澮澮當作？？。毛傳曰。？？、流也。水部曰。？？、水流聲也。古𠯑聲會聲多通用。水流涓涓然曰𡿨。？？然則曰巜。巜大於𡿨矣。此字之本義也。因以名井田之制。"}]},"粼":{"expl":"水生厓石閒粼粼也。从巜粦聲。","rad":"巜","fq":"力珍切","vol":"11","py":"lín","duan":[{"e":"水生厓石閒粼粼也。","n":"厓者、山邊也。"}]},"川":{"expl":"貫穿通流水也。《虞書》曰：“濬く巜，距川。”言深く巜之水會爲川也。凡川之屬皆从川。","rad":"川","fq":"昌緣切","vol":"11","py":"chuān","duan":[{"e":"毌穿通流水也。","n":"毌各本作貫。毌、穿物持之也。穿、通也。巛則毌穿通流。又大於巜矣。水有始出謂川者。如爾雅水注川曰谿、許云泉出通川爲谷是也。有絕大乃謂川者。如皋陶謨𡿨巜距川、攷工記澮達於川是也。本小水之名、因以爲大水之名。"}]},"坙":{"expl":"水脈也。从川在一下。一，地也。壬省聲。一曰水冥坙也。","rad":"川","fq":"古靈切","vol":"11","py":"jīnɡ","duan":[{"e":"水𧖴也。","n":"巠之言濥也。濥者、水𧖴行地中濥濥也。故从川在地下。"}]},"巟":{"expl":"水廣也。从川亡聲。《易》曰：“包巟用馮河。”","rad":"川","fq":"呼光切","vol":"11","py":"huānɡ","duan":[{"e":"水廣也。","n":"引申爲凡廣大之偁。周頌。天作高山。大王荒之。傳曰。荒、大也。凡此等皆叚荒爲巟也。荒、蕪也。荒行而巟廢矣。"}]},"𡿿":{"expl":"水流也。从川或聲。","rad":"川","fq":"于逼切","vol":"11","py":"huò","duan":[{"e":"水流皃。","n":"皃舊作也。今依篇、韵正。江賦。溭淢濜溳。李云。參差相次也。淢卽？。詩。黍稷彧彧。彧者、𡿿之變。叚𡿿爲㦽也。"}]},"𡿯":{"expl":"水流也。从川曰聲。","rad":"川","fq":"于筆切","vol":"11","py":"yù","duan":[{"e":"水流也。","n":"此與水部汩義異。汩、治水也。上林賦曰。汩乎混流。又曰。汩㴔漂疾。方言。汩、疾行也。注云。汩汩、急皃。于筆切。此用汩爲？也。廣韵合爲一。非。"}]},"𡿪":{"expl":"水流𡿪𡿪也。从川，列省聲。","rad":"川","fq":"良辥切","vol":"11","py":"liè","duan":[{"e":"水流𡿪𡿪也。从巛。列省聲。","n":"大徐曰。𠛱字从𡿪。此疑誤。當是从𣦵省。小徐本作𣦵省聲。良薛切。十五部。"}]},"邕":{"expl":"四方有水，自邕城池者。从川从邑。","rad":"川","fq":"於容切","vol":"11","py":"yōnɡ","duan":[{"e":"邑四方有水自邕成池者是也。","n":"邑各本無。依韵會補。成各本作城。誤。依廣韵、韵會正。自邕當作自𢹬。轉寫之誤。𢹬者、抱也。池沼多由人工所爲。惟邑之四旁有水來自擁抱旋繞成池者、是爲邕。以擁釋邕、以㬪韵爲訓也。故其字从川邑。引申之、凡四面有水皆曰邕。周頌曰。于彼西雝。傳曰。雝、澤也。大雅曰。於樂辟雝。鎬京辟雝。傳曰。水旋丘如璧曰辟雝。水經注釋漁陽郡雍奴曰。四方有水爲雍。不流爲奴。皆邕字之叚借也。"}]},"犉":{"expl":"黃牛黑脣也。从牛𦎫聲。《詩》曰：“九十其犉。”","rad":"牛","fq":"如均切","vol":"02","py":"rún","duan":[{"e":"黃牛黑脣也。","n":"釋畜云。黑脣犉。毛傳云。黃牛黑脣曰犉。按爾雅不言黃牛者、牛以黃爲正色。凡不言何色皆謂黃牛也。"}]},"𡿧":{"expl":"害也。从一雝川。《春秋傳》曰：“川雝爲澤，凶。”","rad":"川","fq":"祖才切","vol":"11","py":"zāi","duan":[{"e":"害也。","n":"害者、傷也。？害字本如此作。玉篇云。天反時爲？。今凡作灾、？、葘皆叚借字也。？行而？廢矣。周語曰。陽塞而在陰。川原必塞。原塞、國必亡。以一塞川、是爲害川。故字从一雝川。"}]},"侃":{"expl":"剛直也。从㐰，㐰，古文信；从川，取其不舍晝夜。《論語》曰：“子路𠈉𠈉如也。”","rad":"川","fq":"空旱切","vol":"11","py":"kǎn","duan":[{"e":"剛直也。","n":"論語鄕黨。與下大夫言。侃侃如也。孔曰。侃侃、和樂皃也。葢謂卽衎衎之叚借字。"}]},"州":{"expl":"水中可居曰州，周遶其㫄，从重川。昔堯遭洪水，民居水中高土，或曰九州。《詩》曰：“在河之州。”一曰州，疇也。各疇其土而生之。","rad":"川","fq":"職流切","vol":"11","py":"zhōu","duan":[{"e":"水中可凥者曰州。","n":"凥各本作居。今正。者字今補。周南。在河之州。釋水、毛傳皆曰。水中可居者曰州。"}]},"泉":{"expl":"水原也。象水流出成川形。凡泉之屬皆从泉。","rad":"泉","fq":"疾緣切","vol":"11","py":"quán","duan":[{"e":"水厡也。","n":"釋水曰。濫泉正出。正出、涌出也。沃泉縣出。縣出、下出也。氿泉穴出。穴出、仄出也。毛傳亦云。檻泉正出。側出曰氿泉。許作濫泉、？泉。召旻曰。泉之竭矣。不云自中。傳曰。泉水從中以益者也。引申之、古者謂錢曰泉布。許云。古者貨貝而寶龜。周而有泉。至秦廢貝行錢。"}]},"㶗":{"expl":"泉水也。从泉緐聲。讀若飯。","rad":"泉","fq":"符萬切","vol":"11","py":"fàn","duan":[{"e":"泉水也。","n":"泉水者、泉出之水也。淮南書云。莫鑒於流？。而鑒於澄水。許注云。楚人謂水暴溢爲？。？卽㶗字。泉水暴溢曰㶗也。"}]},"灥":{"expl":"三泉也。闕。凡灥之屬皆从灥。","rad":"灥","fq":"詳遵切","vol":"11","py":"xún","duan":[{"e":"三泉也。","n":"凡積三爲一者、皆謂其多也。不言从三泉者、不待言也。"}]},"𠫐":{"expl":"水泉夲也。从灥出厂下。","rad":"灥","fq":"愚袁切","vol":"11","py":"yuán","duan":[{"e":"水本也。","n":"各本作水泉本也。今刪正。月令百源注曰。衆水始所出爲百源。單𧦝曰原。絫𧦝曰原泉。孟子原泉混混是也。"}]},"永":{"expl":"長也。象水坙理之長。《詩》曰：“江之永矣。”凡永之屬皆从永。","rad":"永","fq":"于憬切","vol":"11","py":"yǒnɡ","duan":[{"e":"水長也。","n":"引申之、凡長皆曰永。釋詁、毛傳曰。永、長也。方言曰。施於衆長謂之永。"}]},"羕":{"expl":"水長也。从永羊聲。《詩》曰：“江之羕矣。”","rad":"永","fq":"余亮切","vol":"11","py":"yànɡ","duan":[{"e":"水長也。","n":"引申之爲凡長之偁。釋詁曰。羕、長也。"}]},"𠂢":{"expl":"水之衺流，別也。从反永。凡𠂢之屬皆从𠂢。讀若稗縣。","rad":"𠂢","fq":"匹卦切","vol":"11","py":"pài","duan":[{"e":"水之衺流別也。","n":"流別者、一水岐分之謂。禹貢曰。漾東流爲漢。沇東流爲？。江東別爲沱。此言流別之始。釋水詳之。自河出爲灉、濟爲濋已下是也。流別則其勢必衺行。故曰衺流別。𠂢與水部派音義皆同。派葢後出耳。衺流別、則正流之長者較短而巠理同也。故其字从反永。"}]},"㹊":{"expl":"白牛也。从牛隺聲。","rad":"牛","fq":"五角切","vol":"02","py":"yuè","duan":[{"e":"白牛也。","n":"白部曰。㿥、鳥之白也。此同聲同義。"}]},"𧖴":{"expl":"血理分衺行體者。从𠂢从血。","rad":"𠂢","fq":"莫獲切","vol":"11","py":"mài","duan":[{"e":"血理分衺行體中者。","n":"理分猶分理。序曰。見鳥獸蹏迒之迹。知分理之可相別異。衺行體中、而大𠋫在寸口。人手卻十分動脈爲寸口也。"}]},"覛":{"expl":"衺視也。从𠂢从見。","rad":"𠂢","fq":"莫狄切","vol":"11","py":"mì","duan":[{"e":"衺視也。","n":"釋詁曰。覛、胥、相也。郭云。覛謂相視也。按覛與目部眽通用。古詩。眽眽不得語。李善引爾雅及注作眽。今文選譌作脈。非也。覛不入見部者、重𠂢也。"}]},"谷":{"expl":"泉出通川爲谷。从水半見，出於口。凡谷之屬皆从谷。","rad":"谷","fq":"古禄切","vol":"11","py":"ɡǔ","duan":[]},"谿":{"expl":"山瀆无所通者。从谷奚聲。","rad":"谷","fq":"苦兮切","vol":"11","py":"xī","duan":[{"e":"山𨽍無所通者。","n":"𨽍各本作瀆。今正。𨸏部曰。𨽍、通溝也。讀若洞。古文作豄。釋山曰。山豄無所通、谿。然則許作𨽍明矣。"}]},"𧯆":{"expl":"通谷也。从谷害聲。","rad":"谷","fq":"呼括切","vol":"11","py":"huò","duan":[{"e":"通谷也。","n":"通迵之谷也。文選注曰。華延洛陽記云。城南五十里有大谷。舊名通谷。引申爲凡疏達之偁。"}]},"豂":{"expl":"空谷也。从谷翏聲。","rad":"谷","fq":"洛蕭切","vol":"11","py":"liáo","duan":[{"e":"空谷也。","n":"虛廫之谷也。大雅曰。大風有隧。有空大谷。"}]},"豅":{"expl":"大長谷也。从谷龍聲。讀若聾。","rad":"谷","fq":"盧紅切","vol":"11","py":"lónɡ","duan":[{"e":"大長谷也。","n":"司馬相如傳曰。巖巖深山之谾谾兮。晉灼曰。谾音籠。古豅字。蕭該曰。谾或作豅。長大皃也。徐廣谾音力工反。與晉說同。白駒傳曰。空谷、大谷也。"}]},"𧮯":{"expl":"谷中響也。从谷厷聲。","rad":"谷","fq":"戶萌切","vol":"11","py":"hónɡ","duan":[{"e":"谷中響也。","n":"此與宖、屋響也義近。攷工記。其聲大而宏。司農注。謂聲音大也。引申爲凡大之偁。史記司馬相如傳。必將崇論谹議。"}]},"䜭":{"expl":"深通川也。从谷从𣦵。𣦵，殘地；阬坎意也。《虞書》曰：“䜭畎澮距川。”","rad":"谷","fq":"私閏切","vol":"11","py":"jùn","duan":[{"e":"深通川也。","n":"深之使通也。䜭與叡睿音義皆相近。故今文洪範曰。思心曰䜭。䜭作聖。古文曰。思曰睿。睿作聖。"}]},"谸":{"expl":"望山谷谸谸青也。从谷千聲。","rad":"谷","fq":"倉絢切","vol":"11","py":"qiān","duan":[{"e":"望山谷千千靑也。","n":"各本千千作谸谸。今正。高唐賦。仰視山顚。肅何芊芊。李注云。說文曰。谸、望山谷千千靑也。千與芊、古字通。按千芊爲古今字。俗用芊改千。楚詞及陸機文賦皆用千眠字。南都賦作䀒瞑。謝朓詩。遠樹曖阡阡。廣雅乃有芊芊字耳。"}]},"㹔":{"expl":"牛長𦟝也。从牛畺聲。","rad":"牛","fq":"居良切","vol":"02","py":"jiānɡ","duan":[{"e":"牛長脊。","n":"廣韵。㹔、牛長脊。一曰白脊牛。按一曰五字疑亦出說文。今佚。"}]},"仌":{"expl":"凍也。象水凝之形。凡仌之屬皆从仌。","rad":"仌","fq":"筆陵切","vol":"11","py":"bīnɡ","duan":[{"e":"凍也。","n":"仌凍二篆爲轉注。絫𧦝之曰仌凍。如月令冰凍消釋是也。"}]},"冰":{"expl":"水堅也。从仌从水。","rad":"仌","fq":"魚陵切","vol":"11","py":"nínɡ","duan":[{"e":"水堅也。","n":"易象傳。初六履霜。陰始凝也。馴致其道。至堅冰也。古本當作陰始冰也。至堅仌也。釋器。冰脂也。孫本冰作凝。按此可證詩膚如凝脂、本作冰脂。以冰代仌、乃別製凝字。經典凡凝字皆冰之變也。"}]},"癛":{"expl":"寒也。从仌廩聲。","rad":"仌","fq":"力稔切","vol":"11","py":"lǐn","duan":[{"e":"𠘡𠘡、","n":"依文賦注補二字。"}]},"凊":{"expl":"寒也。从仌青聲。","rad":"仌","fq":"七正切","vol":"11","py":"qìnɡ","duan":[{"e":"寒也。","n":"曲禮曰。凡爲人子之禮。冬溫而夏凊。"}]},"凍":{"expl":"仌也。从仌東聲。","rad":"仌","fq":"多貢切","vol":"11","py":"dònɡ","duan":[{"e":"仌也。","n":"初凝曰仌。仌壯曰凍。又於水曰冰。於他物曰凍。故月令曰。水始冰。地始凍。"}]},"𠗲":{"expl":"仌出也。从仌朕聲。《詩》曰：“納于𠗲陰。”","rad":"仌","fq":"力膺切","vol":"11","py":"línɡ","duan":[{"e":"仌出也。","n":"仌出者、謂仌之出水文棱棱然。輕讀爲力膺切。重讀則里孕切。今俗語猶尒。豳詩。三之日納于凌陰。傳曰。凌陰、冰室也。此以冰釋凌、以室釋陰。非謂？爲仌室也。鄭注周禮凌人徑云凌、冰室也。似失之。"}]},"凘":{"expl":"流仌也。从仌斯聲。","rad":"仌","fq":"息移切","vol":"11","py":"sī","duan":[{"e":"流仌也。","n":"謂仌初結及已釋時隨流而行也。"}]},"凋":{"expl":"半傷也。从仌周聲。","rad":"仌","fq":"都僚切","vol":"11","py":"diāo","duan":[{"e":"半傷也。","n":"傷、創也。半傷、未全傷也。"}]},"冬":{"expl":"四時盡也。从仌从夂。夂，古文終字。","rad":"仌","fq":"都宗切","vol":"11","py":"dōnɡ","duan":[{"e":"四時盡也。","n":"冬之爲言終也。考工記曰。水有時而凝。有時而釋。故冬从仌。"}]},"冶":{"expl":"銷也。从仌台聲。","rad":"仌","fq":"羊者切","vol":"11","py":"yě","duan":[{"e":"銷也。","n":"銷者、鑠金也。仌之融如鑠金然。故鑪鑄亦曰冶。易。野容誨淫。陸德明本作冶容。按野、冶皆蠱之叚借也。張衡賦言妖蠱。今言妖冶。"}]},"𤘸":{"expl":"牛徐行也。从牛𠬢聲。讀若滔。","rad":"牛","fq":"土刀切","vol":"02","py":"tāo","duan":[{"e":"牛徐行也。","n":"俗謂舒遟曰𤘸𤘸。"}]},"凔":{"expl":"寒也。从仌倉聲。","rad":"仌","fq":"初亮切","vol":"11","py":"cānɡ","duan":[{"e":"寒也。","n":"此與水部滄音義皆同。枚乘上書曰。欲湯之凔。絕薪止火而已。按方言曰漺淨也、二字當从冫。？卽凔字。凈卽凊字。"}]},"冷":{"expl":"寒也。从仌令聲。","rad":"仌","fq":"魯打切","vol":"11","py":"lěnɡ","duan":[{"e":"寒也。从仌。令聲。","n":"魯打切。十一部。"}]},"𠗙":{"expl":"寒也。从仌圅聲。","rad":"仌","fq":"胡男切","vol":"11","py":"hán","duan":[{"e":"寒也。从仌。圅聲。","n":"胡男切。八部。"}]},"㓖":{"expl":"風寒也。从仌畢聲。","rad":"仌","fq":"卑吉切","vol":"11","py":"bì","duan":[{"e":"㓖冹、","n":"二字今補。"}]},"冹":{"expl":"一之日㓖冹。从仌犮聲。","rad":"仌","fq":"分勿切","vol":"11","py":"fú","duan":[{"e":"㓖冹也。","n":"三字今正。"}]},"凓":{"expl":"寒也。从仌栗聲。","rad":"仌","fq":"力質切","vol":"11","py":"lì","duan":[{"e":"凓冽、","n":"二字今補。"}]},"𠘝":{"expl":"寒也。从仌賴聲。","rad":"仌","fq":"洛帶切","vol":"11","py":"lài","duan":[]},"雨":{"expl":"水从雲下也。一象天，冂象雲，水霝其閒也。凡雨之屬皆从雨。","rad":"雨","fq":"王矩切","vol":"11","py":"yǔ","duan":[{"e":"水從雲下也。","n":"引申之凡自上而下者偁雨。"}]},"靁":{"expl":"陰陽薄動靁雨，生物者也。从雨，畾象回轉形。","rad":"雨","fq":"魯回切","vol":"11","py":"léi","duan":[{"e":"𩃬昜薄動生物者也。","n":"各本作陰陽。今正。動下各本有靁雨二字。不辭。今依韵會本正。薄音博。迫也。陰陽迫動、卽謂靁也。迫動下文所謂回轉也。所以回生萬物者也。"}]},"霣":{"expl":"雨也。齊人謂靁爲霣。从雨員聲。一曰雲轉起也。","rad":"雨","fq":"于敏切","vol":"11","py":"yǔn","duan":[{"e":"齊人謂靁爲霣。","n":"各本齊上有雨也二字。按自靁篆至震篆皆言雷電。自霝篆至霩篆皆言雨。叚令霣之正義爲雨。則當次於彼閒。今刪。韵會本亦無此二字。齊人謂靁曰霣。方俗語言如此。靁、古讀如回。回與員語之轉。公羊傳。星霣如雨。叚爲隕字。"}]},"犨":{"expl":"牛息聲。从牛雔聲。一曰牛名。","rad":"牛","fq":"赤周切","vol":"02","py":"chōu","duan":[{"e":"牛息聲。","n":"心部曰息喘也。"}]},"霆":{"expl":"雷餘聲也鈴鈴。所以挺出萬物。从雨廷聲。","rad":"雨","fq":"特丁切","vol":"11","py":"tínɡ","duan":[{"e":"靁餘聲鈴鈴。","n":"句。"}]},"霅":{"expl":"霅霅，震電皃。一曰眾言也。从雨，譶省聲。","rad":"雨","fq":"丈甲切","vol":"11","py":"zhá","duan":[{"e":"霅霅靁𩃓皃。","n":"靁各本作震。今依韵會本。霅霅、聲光襍沓之皃。按馬融廣成頌霅爾雹落。霅音素洽反。今俗語云霎時閒。霎卽霅之俗字。"}]},"電":{"expl":"陰陽激燿也。从雨从申。","rad":"雨","fq":"堂練切","vol":"11","py":"diàn","duan":[{"e":"䨧昜激燿也。","n":"孔沖遠引河圖云。陰陽相薄爲靁。陰激陽爲電。電是靁光。按易震爲靁。離爲電。月令靁乃發聲。始電。詩十月之交。春秋隱九年言震電。詩采芑、常武、雲漢言靁霆。震靁一也。電霆一也。穀梁傳曰。電、霆也。古義霆電不別。許意則統言之謂之靁。自其振物言之謂之震。自其餘聲言之謂之霆。自其光燿言之謂之電。分析較古而㥦心。靁電者、一而二者也。"}]},"震":{"expl":"劈歴，振物者。从雨辰聲。《春秋傳》曰：“震夷伯之廟。”","rad":"雨","fq":"章刃切","vol":"11","py":"zhèn","duan":[{"e":"劈歷振物者。","n":"劈歷、疾雷之名。釋天曰。疾靁爲霆。倉頡篇曰。霆、霹靂也。然則古謂之霆。許謂之震。詩十月之交。春秋隱九年。僖十五年皆言震。振與震曡韵。春秋正義引作震物爲長。以能震物而謂之震也。引申之、凡動謂之震。辰下曰。震也。"}]},"䨮":{"expl":"凝雨，說物者。从雨彗聲。","rad":"雨","fq":"相絕切","vol":"11","py":"xuě","duan":[{"e":"冰雨說物者也。","n":"冰各本作凝。今正。凝者、冰之俗也。釋名曰。雪、綏也。水下遇寒氣而凝。綏綏然下也。故許謂之冰雨。說今之悅字。物無不喜雪者。說與雪曡韵。"}]},"霄":{"expl":"雨䨘爲霄。从雨肖聲。齊語也。","rad":"雨","fq":"相邀切","vol":"11","py":"xiāo","duan":[{"e":"雨霰爲霄。","n":"雨猶𩂣也。釋天曰。雨䨘爲霄雪。此霄字本義。若淮南書上游於霄雿之野。高讀如紺綃之綃。此則別爲一義。乃今義行而古義䍐用矣。霄亦叚消。"}]},"䨷":{"expl":"稷雪也。从雨𢿱聲。","rad":"雨","fq":"穌甸切","vol":"11","py":"xiàn","duan":[{"e":"稷䨮也。","n":"謂雪之如稷者。毛詩傳曰。霰、暴雪也。暴當是黍之字誤。俗謂米雪、或謂粒雪皆是也。曾子曰。陽之專氣爲霰。詩箋云。將大雨雪。始必微溫。雪自上下。遇溫氣而團。謂之霰。久之寒勝則大雪矣。"}]},"雹":{"expl":"雨冰也。从雨包聲。","rad":"雨","fq":"蒲角切","vol":"11","py":"báo","duan":[{"e":"雨仌也。","n":"仌舊作冰。今正。雨仌、謂自上而下之仌也。曾子曰。陰之專氣爲雹。劉向曰。盛陽雨水。溫暖而湯𤍽。陰氣脅之不相入。則轉而爲雹。故沸湯之在閉器而湛於甘泉則爲冰。此其驗也。左氏傳曰。聖人在上。無雹。雖有、不爲災。"}]},"霝":{"expl":"雨零也。从雨，𠱠象𩂣形。《詩》曰：“霝雨其濛。”","rad":"雨","fq":"郎丁切","vol":"11","py":"línɡ","duan":[{"e":"雨𩂣也。","n":"𩂣各本作零。今依廣韵正。霝與零義殊。許引東山霝雨。今作零雨、譌字也。定之方中。靈雨既零。傳曰。零、落也。零亦當作霝。霝亦叚靈爲之。鄭風。零露漙兮。正義本作靈。箋云。靈、落也。靈落卽霝落。雨曰霝𩂣。艸木曰零落。"}]},"𩂣":{"expl":"雨零也。从雨各聲。","rad":"雨","fq":"盧各切","vol":"11","py":"luò","duan":[{"e":"雨𩂣也。","n":"此下雨本字。今則落行而𩂣廢矣。"}]},"祆":{"expl":"胡神也。从示天聲。","rad":"示","fq":"火千切","vol":"01","py":"xiān","duan":[]},"牟":{"expl":"牛鳴也。从牛，象其聲气从口出。","rad":"牛","fq":"莫浮切","vol":"02","py":"móu","duan":[{"e":"牛鳴也。从牛。厶象其聲气從口出。","n":"此合體象形。與？同意。韓愈詩曰。椎肥牛呼牟。桺宗元賦曰。牟然而鳴。黃鍾滿脰。莫浮切。三部。"}]},"零":{"expl":"餘雨也。从雨令聲。","rad":"雨","fq":"郎丁切","vol":"11","py":"línɡ","duan":[{"e":"徐雨也。","n":"徐各本作餘。今依玉篇、廣韵及太平御覽所引纂要訂。謂徐徐而下之雨。小雅。興雲祁祁。傳曰。祁祁、徐也。箋云。古者陰陽和。風雨時。其來祁祁然而不曓疾。引申之義爲零星、爲凋零。"}]},"𩆵":{"expl":"小雨財𩂣也。从雨鮮聲。讀若斯。","rad":"雨","fq":"息移切","vol":"11","py":"sī","duan":[{"e":"小雨財𩂣也。","n":"財當作才。取初始之義。今字作纔。"}]},"霢":{"expl":"霢霂，小雨也。从雨脈聲。","rad":"雨","fq":"莫獲切","vol":"11","py":"mài","duan":[{"e":"霢霂。","n":"句。"}]},"霂":{"expl":"霢霂也。从雨沐聲。","rad":"雨","fq":"莫卜切","vol":"11","py":"mù","duan":[{"e":"霢霂也。","n":"此雙聲字。"}]},"𩆑":{"expl":"小雨也。从雨酸聲。","rad":"雨","fq":"素官切","vol":"11","py":"suān","duan":[{"e":"小雨也。从雨。酸聲。","n":"素官切。十四部。"}]},"𩃔":{"expl":"微雨也。从雨㦰聲。又讀若芟。","rad":"雨","fq":"子廉切","vol":"11","py":"jiān","duan":[{"e":"溦雨也。","n":"溦各本作微。今正。水部曰。溦、小雨也。今人謂小雨曰廉纖。卽𩃔也。"}]},"𩅉":{"expl":"小雨也。从雨眾聲。《明堂月令》曰：“𩅉雨。”","rad":"雨","fq":"職戎切","vol":"11","py":"zhōnɡ","duan":[{"e":"小雨也。从雨。衆聲。","n":"職戎切。九部。"}]},"霃":{"expl":"久陰也。从雨沈聲。","rad":"雨","fq":"直深切","vol":"11","py":"chén","duan":[{"e":"久䨧也。","n":"月令。季春行秋令。則天多沈陰。沈卽霃之叚借也。沈行而霃廢矣。"}]},"𩄡":{"expl":"久雨也。从雨兼聲。","rad":"雨","fq":"力鹽切","vol":"11","py":"lián","duan":[{"e":"久雨也。","n":"𩄡之言連也。"}]},"𩄙":{"expl":"久雨也。从雨圅聲。","rad":"雨","fq":"胡男切","vol":"11","py":"hán","duan":[{"e":"久雨也。从雨。圅聲。","n":"胡男切。八部。"}]},"㹌":{"expl":"畜牷也。从牛産聲。","rad":"牛","fq":"所簡切","vol":"02","py":"chǎn","duan":[{"e":"畜㹌、畜牲也。","n":"依廣韵、手鑑訂。左傳、內則皆云。名子不以畜牲。"}]},"霖":{"expl":"雨三日已往。从雨林聲。","rad":"雨","fq":"力尋切","vol":"11","py":"lín","duan":[{"e":"凡雨三日已往爲霖。","n":"左傳隱九年。春王三月癸酉。大雨霖以震。書始也。庚辰。大雨雪。亦如之。書時失也。凡雨自三日以往爲霖。平地尺爲大雪。按許直用傳文爲說也。已當作以。自三日以往、謂雨三日又不止。不定其日數也。雨三日止、不得謂霖矣。韋注國語亦曰。雨三日以上爲霖。若宋人注尚書云三日雨爲霖。失古義矣。釋天。久雨謂之淫。淫謂之霖。"}]},"𩂢":{"expl":"霖雨也。南陽謂霖𩂢。从雨㐺聲。","rad":"雨","fq":"銀箴切","vol":"11","py":"yín","duan":[{"e":"霖雨也。南陽謂霖𩂢。","n":"俗本作謂霖雨曰𩂢。全書多類此者。今不可盡正矣。其字从㐺。㐺者、衆立也。故雨多取之。是可以證𩂢雨之爲霖而非小雨矣。淫雨卽𩂢雨之叚借。"}]},"𩄚":{"expl":"雨聲。从雨眞聲。讀若資。","rad":"雨","fq":"卽夷切","vol":"11","py":"zī","duan":[{"e":"雨聲。从雨。眞聲。讀若資。","n":"眞聲而讀若資者、合音也。故廣韵作𩆂。卽夷切。十五部。"}]},"䨞":{"expl":"雨皃。方語也。从雨禹聲。讀若禹。","rad":"雨","fq":"王矩切","vol":"11","py":"yǔ","duan":[{"e":"雨皃。方語也。","n":"方上葢奪北字。集韵曰。䨞火五切。北方謂雨曰䨞。呂靜說。按呂氏韵集所據說文爲完善。"}]},"𩅼":{"expl":"小雨也。从雨僉聲。","rad":"雨","fq":"子廉切","vol":"11","py":"jiān","duan":[{"e":"小雨也。从雨。僉聲。","n":"子廉切。七部。"}]},"霑":{"expl":"雨𩃵也。从雨沾聲。","rad":"雨","fq":"張廉切","vol":"11","py":"zhān","duan":[{"e":"雨𩃵也。","n":"小雅。旣霑旣足。"}]},"𩃵":{"expl":"濡也。从雨染聲。","rad":"雨","fq":"而𤥎切","vol":"11","py":"rǎn","duan":[{"e":"濡也。","n":"濡此義水部失載。於此見之。今人多用霑染、濡染。染行而？廢矣。染者、以繪染爲色。非霑義。"}]},"𩅸":{"expl":"屋水流也。从雨畱聲。","rad":"雨","fq":"力救切","vol":"11","py":"liù","duan":[{"e":"屋水流也。","n":"水部曰。濩、𩅸下皃也。釋名曰。中央曰中𩅸。古者𥨍穴後室之𩅸。當今之棟下直室之中。古者𩅸下之處也。"}]},"屚":{"expl":"屋穿水下也。从雨在尸下。尸者，屋也。","rad":"雨","fq":"盧后切","vol":"11","py":"lòu","duan":[{"e":"屋穿水入也。","n":"今字作漏。漏行而屚廢矣。漏者、以銅受水刻節也。"}]},"䨣":{"expl":"雨濡革也。从雨从革。讀若膊。","rad":"雨","fq":"匹各切","vol":"11","py":"ɡé","duan":[{"e":"雨濡革也。","n":"雨濡革則虛起。今俗語若朴。"}]},"牲":{"expl":"牛完全。从牛生聲。","rad":"牛","fq":"所庚切","vol":"02","py":"shēnɡ","duan":[{"e":"牛完全也。","n":"引伸爲凡畜之偁。周禮庖人注。始養之曰畜。將用之曰牲。按如鼷鼠食郊牛角、則非完全。"}]},"霽":{"expl":"雨止也。从雨齊聲。","rad":"雨","fq":"子計切","vol":"11","py":"jì","duan":[{"e":"雨止也。","n":"釋天。雨濟謂之霽。濟、古多訓止者。如厲風濟則衆竅爲虛是也。許云雨止者、以詁訓字易其本字也。凡止曰濟。雨止則有霽字。洪範曰。雨曰濟。今古文皆如是。是尙書用濟爲霽也。"}]},"霋":{"expl":"霽謂之霋。从雨妻聲。","rad":"雨","fq":"七稽切","vol":"11","py":"qī","duan":[{"e":"霽謂之霋。从雨。妻聲。","n":"七稽切。十五部。"}]},"霩":{"expl":"雨止雲罷皃。从雨郭聲。","rad":"雨","fq":"苦郭切","vol":"11","py":"kuò","duan":[{"e":"雨止雲罷皃。","n":"淮南天文訓。道生於虛霩。虛霩生宇宙。今俗字作廓。廓行而霩廢矣。"}]},"露":{"expl":"潤澤也。从雨路聲。","rad":"雨","fq":"洛故切","vol":"11","py":"lù","duan":[{"e":"潤澤也。","n":"澤與露㬪韵。五經通義曰。和氣津凝爲露。蔡邕月令曰。露者、陰之液也。按露之言臚也。故凡陳列表見於外曰露。亦叚路爲之。如孟子神農章羸露字作路是也。"}]},"霜":{"expl":"喪也。成物者。从雨相聲。","rad":"雨","fq":"所莊切","vol":"11","py":"shuānɡ","duan":[{"e":"喪也。","n":"以㬪韵爲訓。"}]},"霚":{"expl":"地气發，天不應。从雨敄聲。","rad":"雨","fq":"亡遇切","vol":"11","py":"wù","duan":[{"e":"地气發、天不應曰霚。","n":"曰霚二字今補。霚今之霧字。釋天曰。地氣發、天不應曰霧。霧者俗字。霧一本作霿。非也。釋名曰。霧、冒也。氣蒙冒覆地之物也。開元占經引元命包陰陽亂爲霧。"}]},"霾":{"expl":"風雨土也。从雨貍聲。《詩》曰：“終風且霾。”","rad":"雨","fq":"莫皆切","vol":"11","py":"mái","duan":[{"e":"風而雨土爲霾。","n":"依釋天補三字。邶風。終風且霾。釋天曰。風而雨土爲霾。傳曰。霾、雨土也。釋名曰。霾、晦也。"}]},"霿":{"expl":"天气下，地不應，曰霿。霿，晦也。从雨瞀聲。","rad":"雨","fq":"莫弄切","vol":"11","py":"ménɡ","duan":[{"e":"天氣下、地不應曰霿。","n":"釋天曰。天氣下、地不應曰霿。今本作曰雺。或作曰霧。皆非也。霿、釋名作蒙。開元占經作濛。釋名曰。蒙、日光不明蒙蒙然也。開元占經引郗萌曰。在天爲濛。在人爲霧。日月不見爲濛。前後人不相見爲霧。按霚與霿之別、以郗所言爲確。許以霿系天气。以霚系地气。亦分別井然。大氐霚下霿上。霚溼霿乾。霚讀如務。霿讀如蒙。霚之或體作霧。霿之或體作蒙。不可亂也。而爾雅自陸氏不能諟正。譌舛不可讀。如玉篇云霚、天氣下地不應也。霿、地氣發天不應也。葢本爾雅而與說文互易。則又在陸氏前矣。其他經史雺霿霧三字往往淆譌。要當以許書爲正。○開元占經引月令仲冬行夏令。氛濛冥冥。今月令作氛霧。霧乃霿之誤也。○衞包尙書曰。蒙、恒風若。漢五行志作"}]},"霓":{"expl":"屈虹，青赤，或白色，陰气也。从雨兒聲。","rad":"雨","fq":"五雞切","vol":"11","py":"ní","duan":[{"e":"屈虹靑赤或白色。","n":"或字陸德明作也一曰三字。非也。韵會白下無色字。是也。屈當作詘。許書云詰詘者、謂詘曲。屈非其義。許意詘曲之虹多靑赤。或有白色者。皆謂之霓。釋天曰。螮蝀、虹也。霓爲挈貳。郭云。雙出色鮮盛者爲雄、曰虹。闇者爲雌、曰霓。據此、似靑赤爲虹。白色爲霓。然析言有分。渾言不別。故趙注孟子曰。霓、虹也。虹見則雨。楚辭有白霓。"}]},"𩅀":{"expl":"寒也。从雨執聲。或曰：早霜。讀若《春秋傳》“墊阨”。","rad":"雨","fq":"都念切","vol":"11","py":"diàn","duan":[{"e":"寒也。从雨。𡙕聲。","n":"都念切。七部。"}]},"牷":{"expl":"牛純色。从牛全聲。","rad":"牛","fq":"疾緣切","vol":"02","py":"quán","duan":[{"e":"牛純色。","n":"牧人注。鄭司農曰。牷、純也。按凡時事之牲用牷物。凡外祭毀事用尨。以尨與牷對舉。則牷爲純色天知也。大鄭注釋牷爲純也。爲許所本。後鄭則訓犧爲純毛。牷爲體完具。與許異。"}]},"雩":{"expl":"夏祭，樂于赤帝，以祈甘雨也。从雨于聲。","rad":"雨","fq":"羽俱切","vol":"11","py":"yú","duan":[{"e":"夏祭樂於赤帝以祈甘雨也。","n":"公羊傳曰。大雩者何。旱祭也。月令。仲夏之月。大雩帝。用盛樂。乃命百縣。雩祀百辟卿士有益於民者。以祈穀實。注曰雩、吁嗟求雨之祭也。雩帝、謂爲壇南郊之旁。雩五精之帝。配以先帝也。自鞀鞞至柷敔皆作曰盛樂。凡他雩用歌舞而已。春秋傳曰。龍見而雩。雩之正當以四月。按鄭言五精之帝。高誘注時則訓曰。帝、上帝也。許獨云赤帝者、以其爲夏祭而言也。以祈甘雨、故字从雨。以于？而求、故从亏。服䖍曰。雩、遠也。亦於从于得義也。"}]},"需":{"expl":"𩓣也。遇雨不進，止𩓣也。从雨而聲。《易》曰：“雲上於天，需。”","rad":"雨","fq":"相俞切","vol":"11","py":"xū","duan":[{"e":"䇓也。","n":"䇓者、待也。以㬪韵爲訓。易彖傳曰。需、須也。須卽䇓之叚借也。左傳曰。需、事之賊也。又曰。需、事之下也。皆待之義也。凡相待而成曰需。"}]},"䨒":{"expl":"水音也。从雨羽聲。","rad":"雨","fq":"王矩切","vol":"11","py":"yù","duan":[{"e":"水音也。","n":"江氏聲曰。五聲羽屬水。許字作䨒、與各書不同。今按此當謂流水之音耳。"}]},"霞":{"expl":"赤雲气也。从雨叚聲。","rad":"雨","fq":"胡加切","vol":"11","py":"xiá","duan":[]},"霏":{"expl":"雨雲皃。从雨非聲。","rad":"雨","fq":"芳非切","vol":"11","py":"fēi","duan":[]},"霎":{"expl":"小雨也。从雨妾聲。","rad":"雨","fq":"山洽切","vol":"11","py":"shà","duan":[]},"䨴":{"expl":"黮䨴雲黑皃。从雨對聲。","rad":"雨","fq":"徒對切","vol":"11","py":"duì","duan":[]},"靄":{"expl":"雲皃。从雨，藹省聲。","rad":"雨","fq":"於蓋切","vol":"11","py":"ǎi","duan":[]},"雲":{"expl":"山川气也。从雨，云象雲回轉形。凡雲之屬皆从雲。","rad":"雲","fq":"王分切","vol":"11","py":"yún","duan":[{"e":"山川气也。","n":"天降時雨。山川出雲。"}]},"𩃬":{"expl":"雲覆日也。从雲今聲。","rad":"雲","fq":"於今切","vol":"11","py":"yīn","duan":[{"e":"雲覆日也。","n":"今人陰陽字小篆作𩃬昜。𩃬者、雲覆日。昜者、旗開見日。引申爲㒳儀字之用。今人作陰陽、乃其中之一耑而已。𩃬字今僅見大戴禮記文王官人篇、素問五帝政大論。"}]},"牽":{"expl":"引前也。从牛，象引牛之縻也。玄聲。","rad":"牛","fq":"苦堅切","vol":"02","py":"qiān","duan":[{"e":"引而前也。","n":"牽引㬪韵。引伸之、輓牛之具曰牽。牛人牽徬是也。牲、腥曰餼。生曰牽。又凡聮貫之䛐曰牽。"}]},"魚":{"expl":"水蟲也。象形。魚尾與燕尾相似。凡魚之屬皆从魚。","rad":"魚","fq":"語居切","vol":"11","py":"yú","duan":[{"e":"水蟲也。象形。魚尾與燕尾相佀。","n":"其尾皆枝。故象枝形。非从火也。語居切。五部。"}]},"䲊":{"expl":"魚子已生者。从魚，憜省聲。","rad":"魚","fq":"徒果切","vol":"11","py":"duò","duan":[{"e":"魚子已生者也。","n":"謂魚卵生於水艸閒、初孚有魚形者。云已生、對未生言之。魚子未生者曰鯤。鯤卽卵字。卵說文作卝。古音讀如關。亦可讀如昆。內則。濡魚卵醬。卵、鄭讀鯤。或作？。鯤醬者、魚卵醬也。內則讀卵如字。未嘗不協。凡未出者爲卵。已出者爲子。鯤卽魚卵。故說文以卝包之。而魚部無鯤字。䲊則已出於卵者也。"}]},"鮞":{"expl":"魚子也。一曰魚之美者，東海之鮞。从魚而聲。讀若而。","rad":"魚","fq":"如之切","vol":"11","py":"ér","duan":[{"e":"魚子也。","n":"魚子、謂成細魚者。上文曰魚子已生者、謂初出卵。此云魚子、則成細魚矣。凡細者偁子。魯語曰。魚禁鯤鮞。韋注曰。鯤、魚子也。鮞、未成魚也。韋意鯤是卵未孚者。鮞是已孚而尙未成魚者。許則就已孚又別爲䲊鮞二形。○按爾雅曰鯤、魚子也。鱦、小魚也。爲韋所本。許無鯤字者、以卝包之。據內則之卵醬也。許有鮞無鱦者、鱦从繩省聲。之與蒸合音冣近。鱦者、鮞之俗字也。爾雅、鄭皆云。鯤、魚子。爾雅意魚子卽魚卵。今人俗語猶如是。若西京賦摷鯤鮞。薛注。鯤、魚子也。鮞、細魚族類也。此與鄭內則注鯤魚子也皆謂出卵者爲魚子。失爾雅本義。若莊子𧦝絕大之魚爲鯤。此則齊物之寓言。所謂汪洋自恣以適已者。"}]},"魼":{"expl":"魚也。从魚去聲。","rad":"魚","fq":"去魚切","vol":"11","py":"qū","duan":[{"e":"魼魚也。","n":"舊刪魼字。今補。此如河篆下云河水也之例。漢書上林賦。禺禺魼鰨。郭樸注云。比目魚也。按郭說未知其審。犬部狧字下有比目魚鰈。同爾雅。而魚部無鰈字。玉篇、廣韵合魼鰈爲一字。非也。"}]},"𩹾":{"expl":"魚。似鼈，無甲，有尾，無足，口在腹下。从魚納聲。","rad":"魚","fq":"奴荅切","vol":"11","py":"nà","duan":[{"e":"𩹾魚。佀鼈無甲。有尾無足。口在腹下。从魚。納聲。","n":"按此篆玉篇作𩹾。廣韵作魶。史記上林賦有魶字。云魶一作鰨。奴荅切。八部。"}]},"鰨":{"expl":"虛鰨也。从魚𦐇聲。","rad":"魚","fq":"土盍切","vol":"11","py":"tǎ","duan":[{"e":"虛鰨也。","n":"漢書上林賦魼鰨、史記作鱋魶。魶一作鰨。注家皆以魼鰨爲二魚。許亦別魼與虛鰨爲二。虛非魼鱋之異文也。郭注云。鰨、鯢魚也。似鮎。有四足。聲如嬰兒。按許下文云鯢、剌魚也。不類列一處。則鰨之非鯢明矣。"}]},"鱒":{"expl":"赤目魚。从魚尊聲。","rad":"魚","fq":"慈損切","vol":"11","py":"zùn","duan":[{"e":"赤目魚也。","n":"見豳風。釋魚曰。鮅鱒。毛傳曰。鱒、大魚也。陸璣、郭樸皆云。鱒似鯶。赤眼。"}]},"𩻜":{"expl":"魚也。从魚猌聲。","rad":"魚","fq":"力珍切","vol":"11","py":"lín","duan":[{"e":"𩻜魚也。","n":"亦三字句。周禮。其動物宜鱗物。劉本作𩻜。音鱗。按劉本叚𩻜爲鱗耳。非川澤衹生此魚也。集韵曰。鱗通作𩻜。本劉。"}]},"鰫":{"expl":"魚也。从魚容聲。","rad":"魚","fq":"余封切","vol":"11","py":"yónɡ","duan":[{"e":"鰫魚也。","n":"鄭注內則云。今東海鰫魚有骨。名乙。在目旁。狀如篆乙。食之鯁人不可出。"}]},"䱬":{"expl":"魚也。从魚胥聲。","rad":"魚","fq":"相居切","vol":"11","py":"xū","duan":[{"e":"䱬魚也。从魚。胥聲。","n":"相居切。五部。"}]},"牿":{"expl":"牛馬牢也。从牛告聲。《周書》曰：“今惟牿牛馬。”","rad":"牛","fq":"古屋切","vol":"02","py":"ɡù","duan":[{"e":"牛馬牢也。从牛。告聲。","n":"古屋切。三部。"}]},"鮪":{"expl":"鮥也。《周禮》：“春獻王鮪。”从魚有聲。","rad":"魚","fq":"榮美切","vol":"11","py":"wěi","duan":[{"e":"鮥也。","n":"毛詩衞風傳曰。鮪、鮥也。許本之。陸璣疏曰。鮪魚形似鱣而靑黑。頭小而尖。似鐵兜鍪。口亦在頷下。其甲可以摩薑。大者不過七八尺。益州人謂之䱍䲛。大者爲王鮪。小者爲鮛鮪。一名鮥。肉色白。味不如鱣也。郭氏山海經傳曰。鮪卽鱏也。似鱣而長鼻。體無鱗甲。按卽今之鱘魚也。"}]},"䱭":{"expl":"鯍也。《周禮》謂之䱴。从魚恆聲。","rad":"魚","fq":"古恒切","vol":"11","py":"ɡènɡ","duan":[{"e":"䱭鯍、","n":"逗。䱭字淺人刪之。今補。"}]},"𩶡":{"expl":"䱴𩶡也。从魚巟聲。","rad":"魚","fq":"武登切","vol":"11","py":"ménɡ","duan":[]},"鮥":{"expl":"叔鮪也。从魚各聲。","rad":"魚","fq":"盧各切","vol":"11","py":"luò","duan":[{"e":"叔鮪也。","n":"此見釋魚。許本之。叔鮪者、鮪之小者也。對王鮪爲辭。江賦亦以叔鮪王鱣儷句。叔字林作鮛。俗字也。郭注爾雅曰。鮪、鱣屬也。今宜都郡自京門以上江中通出鱏鱣之魚。有一魚狀似鱣。建平人呼鮥子。卽爾雅之鮥也。按今川江中尙有鮥子魚。昔在南溪縣、巫山縣食之。叔鮪名鮥。則王鮪不名鮥。而以鮥注鮪者何也。渾言析言不同。故互注而又別其大小也。"}]},"鯀":{"expl":"魚也。从魚系聲。","rad":"魚","fq":"古本切","vol":"11","py":"ɡǔn","duan":[{"e":"鯀魚也。从魚。系聲。","n":"此未詳爲何魚。系聲讀古本切、亦未詳所以。恐古音不同今讀也。禹父之字古多作𩩌、作𩨬。禮記及釋文作鰥。廣韵曰。禹父𩩌。尙書本作？。按？乃鯀譌。"}]},"鰥":{"expl":"魚也。从魚眔聲。李陽冰曰：“當从𥊽省。”","rad":"魚","fq":"古頑切","vol":"11","py":"ɡuān","duan":[{"e":"鰥魚也。","n":"見齊風。毛傳曰。大魚也。謂鰥與魴皆大魚之名也。鄭箋乃讀鰥爲爾雅鯤魚子之鯤。殆非是。鰥多叚借爲鰥寡字。鰥寡字葢古衹作矝。矝卽憐之叚借。"}]},"鯉":{"expl":"鱣也。从魚里聲。","rad":"魚","fq":"良止切","vol":"11","py":"lǐ","duan":[{"e":"鱣也。","n":"此見釋魚。毛傳於鱣云鯉。於鯉不云鱣者。鯉者俗通行之語不待注也。舍人云。鯉一名鱣。毛云。鱣、鯉也。爾雅古說如此。自陸璣說鱣身形似龍。銳頭口在頷下。背上腹下皆有甲。縱廣四五尺。今於孟津東石磧上钓取之。大者千餘斤。而郭注乃分鯉鱣爲二。云鱣、大魚。似鱏而短鼻。口在頷下。體有邪行甲。無鱗。肉黃。大者長二三丈。此卽今江中及關東之黃魚也。如其言、則鱣絕非鯉矣。周頌。有鱣有鮪。鰷鱨鰋鯉。鱣鯉並言。似非一物。而箋云鱣、大鯉也。然則凡鯉曰鯉。大鯉曰鱣。猶小鮪曰鮥。大鮪曰鮪。謂鱣與鯉、鮥與鮪不必同形。而要各爲類也。許意當亦如是。○按他家說鱣鮪同類。而有短鼻長鼻、肉黃肉白之分。爾雅、毛、鄭、許則短鼻長鼻肉黃肉白者統以"}]},"鱣":{"expl":"鯉也。从魚亶聲。","rad":"魚","fq":"張連切","vol":"11","py":"zhān","duan":[{"e":"鯉也。","n":"衞風毛傳曰。鱣、鯉也。許本之。以鮪鮥例之。此當同鄭曰大鯉也。葢鯉與鱣同類而別異。猶鮥與鮪同類而別異。"}]},"鱄":{"expl":"魚也。从魚專聲。","rad":"魚","fq":"旨兖切","vol":"11","py":"zhuǎn","duan":[{"e":"鱄魚也。","n":"士喪禮。魚鱄鮒九。鱄、鮒皆常用之魚也。故春秋有名鱄字子魚者。呂覽曰。魚之美者、洞庭之鱄。今本作𩹲。非也。廣韵。鱄出洞庭湖。山海經曰。鱄魚、其狀如鮒而彘尾。江賦亦有𧐕。𧐕與鱄葢非一物。"}]},"鮦":{"expl":"魚名。从魚同聲。一曰𩽵也。讀若絝襱。","rad":"魚","fq":"直隴切","vol":"11","py":"tónɡ","duan":[{"e":"鮦魚。","n":"舊作魚名。今正。許書之例。不言某名也。釋魚曰。鰹、大者鮦。小者鮵。許無鰹鮵字。"}]},"牢":{"expl":"閑，養牛馬圈也。从牛，冬省。取其四周帀也。","rad":"牛","fq":"魯刀切","vol":"02","py":"láo","duan":[{"e":"閑也。","n":"也字今補。"}]},"𩽵":{"expl":"鮦也。从魚蠡聲。","rad":"魚","fq":"盧啓切","vol":"11","py":"lǐ","duan":[{"e":"鮦也。","n":"正與鮦篆轉注。本艸作蠡魚。省作䗍。陶貞白云。今皆作鱧字。按此名之所以不正也。"}]},"䱾":{"expl":"魚名。一名鯉，一名鰜。从魚婁聲。","rad":"魚","fq":"洛侯切","vol":"11","py":"lóu","duan":[{"e":"䱾魚也。","n":"三字今正。"}]},"鰜":{"expl":"魚名。从魚兼聲。","rad":"魚","fq":"古甜切","vol":"11","py":"qiàn","duan":[{"e":"鰜魚也。","n":"三字今正。按當作䱾魚也。玉篇曰。䱾、大靑魚。類篇曰。鰜魚大而靑。是爲一物也。廣韵云。比目魚。因鳥有鶼皮傅耳。"}]},"鯈":{"expl":"魚名。从魚攸聲。","rad":"魚","fq":"直由切","vol":"11","py":"chóu","duan":[{"e":"鯈魚也。","n":"周頌箋云。鰷、白鰷也。爾雅。鮂、黑鰦。郭云。卽白鯈魚。江東呼爲鮂。莊子。鯈魚出游從容。按白鯈卽今白鯈條。山海經北山篇。彭水鯈魚。其狀如雞而赤毛。三尾、六足、四首。其音如鵲。此異物非常有者也。晉水鮆魚。其狀如鯈。鯈者、白鯈魚也。玉篇合二物爲一。疏矣。"}]},"䱏":{"expl":"魚名。从魚豆聲。","rad":"魚","fq":"天口切","vol":"11","py":"tǒu","duan":[{"e":"䱏魚也。从魚。豆聲。","n":"天口切。四部。亦作？。"}]},"鯾":{"expl":"魚名。从魚便聲。","rad":"魚","fq":"房連切","vol":"11","py":"biān","duan":[{"e":"鯾魚也。","n":"爾雅郭注曰。江東呼魴魚爲鯿。海內北經。大鯾居海中。郭曰。鯾卽魴也。"}]},"魴":{"expl":"赤尾魚。从魚方聲。","rad":"魚","fq":"符方切","vol":"11","py":"fánɡ","duan":[{"e":"赤尾魚也。","n":"周南曰。魴魚赬尾。釋魚曰。魴、魾。傳曰。魚勞則尾赤。按此傳當有魴魚也三字。以魴勞赤尾興如𤈦。非謂魴必赬尾也。左傳。如魚竀尾。衡流而方羊。亦謂其困頓。許以赤尾魚釋魴。殆失之。魴卽鯿魚也。許列字亦二篆相比近。而不言爲一。"}]},"鱮":{"expl":"魚名。从魚與聲。","rad":"魚","fq":"徐呂切","vol":"11","py":"xù","duan":[{"e":"鱮魚也。","n":"齊風。其魚魴鱮。傳曰。魴鱮、大魚。箋云。鱮似魴而弱鱗。陸疏曰。鱮似魴厚而頭大。其頭尤大而肥者、徐州人謂之鰱。廣雅曰。鱮、鰱也。"}]},"鰱":{"expl":"魚名。从魚連聲。","rad":"魚","fq":"力延切","vol":"11","py":"lián","duan":[{"e":"鰱魚也。","n":"按許列字亦二篆相比近。而不言爲一。"}]},"鮍":{"expl":"魚名。从魚皮聲。","rad":"魚","fq":"𢾭羈切","vol":"11","py":"pī","duan":[{"e":"鮍魚也。从魚。皮聲。","n":"敷羈切。古音在十七部。"}]},"犓":{"expl":"以芻莖養牛也。从牛、芻，芻亦聲。《春秋國語》曰：“犓豢幾何。”","rad":"牛","fq":"測愚切","vol":"02","py":"chú","duan":[{"e":"㠯芻莝養圈牛也。","n":"今本莝誤莖、脫圈字。依文𨕖注訂。莝、斬芻也。趙岐注孟子曰。艸生曰芻。穀養曰豢。韋注國語曰。艸食曰芻。穀食曰豢。孟子正義引說文。牛馬曰芻。犬豕曰豢。今說文無此語。經傳犓豢字、今皆作芻豢。"}]},"䱂":{"expl":"魚名。从魚幼聲。讀若幽。","rad":"魚","fq":"於糾切","vol":"11","py":"yǒu","duan":[{"e":"䱂魚也。","n":"廣雅。䱂、𩼈也。謂䱂亦名𩼈。鰌之類也。"}]},"鮒":{"expl":"魚名。从魚付聲。","rad":"魚","fq":"符遇切","vol":"11","py":"fù","duan":[{"e":"鮒魚也。","n":"鮒見易、禮。鄭注易曰。鮒魚微小。虞翻曰。鮒、小鮮也。王逸注大招及廣雅皆云。𩺀、鮒也。"}]},"𩷏":{"expl":"魚名。从魚坙聲。","rad":"魚","fq":"仇成切","vol":"11","py":"qínɡ","duan":[{"e":"𩷏魚也。","n":"尚書大傳曰。大都𩷏魚。鄭注。大都、明都。𩷏魚、今江南以爲鮑。"}]},"𩺀":{"expl":"魚名。从魚𦟝聲。","rad":"魚","fq":"資昔切","vol":"11","py":"jì","duan":[{"e":"𩺀魚也。","n":"今人所常食也。"}]},"鱺":{"expl":"魚名。从魚麗聲。","rad":"魚","fq":"郎兮切","vol":"11","py":"lí","duan":[{"e":"鱺魚也。","n":"此卽今人謂鰻爲鰻鱺之字也。與鱧𩽵鯉皆不同。類篇云。小鮦也。此用郭注爾雅語。"}]},"鰻":{"expl":"魚名。从魚曼聲。","rad":"魚","fq":"母官切","vol":"11","py":"mán","duan":[{"e":"鰻魚也。","n":"亦二篆相比近。而不言爲一。葢許於此等在疑信之閒。"}]},"鳠":{"expl":"魚名。从魚蒦聲。","rad":"魚","fq":"胡化切","vol":"11","py":"huà","duan":[{"e":"鱯魚也。","n":"郭注釋魚曰。鱯佀鮎而大。白色。按今江中多有之。俗譌爲回魚。聲之誤耳。水經注。沔陽縣度口水有二源。一曰淸檢。一曰濁檢。淸水出鱯。濁水出鮒。常以二月八月取。華陽國志鱯譌爲𩼈。"}]},"魾":{"expl":"大鳠也。其小者名鮡。从魚丕聲。","rad":"魚","fq":"𢾭悲切","vol":"11","py":"pī","duan":[{"e":"大鱯也。其小者名鮡。","n":"見釋魚。丕訓大。此會意兼形聲也。爾雅魴魾、亦謂魴之大者爲魾。"}]},"鱧":{"expl":"鳠也。从魚豊聲。","rad":"魚","fq":"盧啓切","vol":"11","py":"lǐ","duan":[{"e":"鱯也。","n":"釋魚、毛傳鱧鯇爲一。許鱧鱯爲一。各有所受之也。"}]},"𩸄":{"expl":"鱧也。从魚果聲。","rad":"魚","fq":"胡瓦切","vol":"11","py":"huà","duan":[{"e":"鱧也。","n":"廣韵曰。𩸄似鮎。與說文合。"}]},"㹛":{"expl":"牛柔謹也。从牛夒聲。","rad":"牛","fq":"而沼切","vol":"02","py":"rǎo","duan":[{"e":"牛柔謹也。","n":"玉篇曰。尙書犪而毅字如此。按凡馴擾字當作此。𣜩作𤛾。廣雅。㹛、柔也。善也。"}]},"鱨":{"expl":"揚也。从魚嘗聲。","rad":"魚","fq":"市羊切","vol":"11","py":"chánɡ","duan":[{"e":"揚也。","n":"揚各本从木者、誤。魚麗傳曰。鱨、揚也。陸疏曰。今黃頰魚也。似燕頭魚身。形厚而長大。頰骨正黃。魚之大而有力解飛者。徐州人謂之揚。按山海經之鱤、郭云黃頰魚也。"}]},"鱏":{"expl":"魚名。从魚覃聲。傳曰：“伯牙鼓琴，鱏魚出聽。”","rad":"魚","fq":"余箴切","vol":"11","py":"xún","duan":[{"e":"鱏魚也。","n":"郭景純說。鮪卽鱏也。許意不尒。故二篆割分異處。劉注蜀都賦曰。鱏魚出江中。頭與身正半。口在腹下。亦與陸璣所說鮪狀正同。鱏今字作鱘。見陳藏器本艸。"}]},"鯢":{"expl":"剌魚也。从魚兒聲。","rad":"魚","fq":"五雞切","vol":"11","py":"ní","duan":[{"e":"剌魚也。","n":"剌盧達切。或作刺者、誤。剌魚者、乖剌之魚。謂其如小皃能緣木。史、漢謂之人魚。釋魚曰。鯢大者謂之鰕。郭云。今鯢魚似鮎。四腳。前似彌猴。後似狗。聲如小兒啼。大者長八九尺。別名鰕。按此魚見書傳者不下數十處。而人不之信。少見則多怪也。余在雅州親見之。廣雅。魶、鯢也。亦謂此。集韵有䱫字。剌之俗。"}]},"鰼":{"expl":"鰌也。从魚習聲。","rad":"魚","fq":"似入切","vol":"11","py":"xí","duan":[{"e":"鰌也。","n":"見釋魚。郭云。今泥鰌。按山海經之鰼魚、別是一物。"}]},"鰌":{"expl":"鰼也。从魚酋聲。","rad":"魚","fq":"七由切","vol":"11","py":"qiū","duan":[{"e":"鰼也。从魚。酋聲。","n":"七由切。三部。"}]},"鯇":{"expl":"魚名。从魚完聲。","rad":"魚","fq":"戶版切","vol":"11","py":"huàn","duan":[{"e":"鯇魚也。","n":"釋魚。鱧鯇也。毛傳同。許於鮮下云鱯也。不云鯇也。故鯇篆割分異處。蓋其所傳不同。鯇鯶古今字。今人曰鯶子。讀如混。多食之。"}]},"魠":{"expl":"哆口魚也。从魚乇聲。","rad":"魚","fq":"他各切","vol":"11","py":"tuō","duan":[{"e":"哆口魚也。","n":"哆者、張口也。上林賦。鰅鰫鰬魠。郭注。魠、鱤也。一名黃頰。郭語恐非許意。儻是黃頰。則當與鱨爲伍。廣雅曰。魧、𩹶、魠也。以魠爲名。取開袥之意。"}]},"鮆":{"expl":"飲而不食，刀魚也。九江有之。从魚此聲。","rad":"魚","fq":"徂礼切","vol":"11","py":"jì","duan":[{"e":"刀魚也。㱃而不食。","n":"各本作飲而不食刀魚也。今依韵會本。漢書貨殖傳顔注正如此。下多者字。刀魚、今人語尚如此。以其形像刀也。俗字作魛。尚書大傳有魚刀。蓋卽此。飲而不食、故其形纖削而味淸雋。春出江中。人多食之。山海經云。苕水注於具區。其中多鮆魚。郭云。鮆魚狹薄而長頭。大者尺餘。太湖中今饒之。郭不係江係太湖者、以經云具區也。今太湖中尚時有之。又按釋魚鮤鱴刀。郭云。今之鮆魚。亦呼爲魛魚。郭說蓋非。鄭注周禮薶物爲鱴刀、含漿之屬。鱴刀、含漿必皆蚌蛤之類。故謂之薶物。不得因一刀字附會也。〇周禮正義云。孫注爾雅刀魚與鱴別。然則孫鮤鱴爲逗。刀爲句。郭蓋同"}]},"鮀":{"expl":"鮎也。从魚它聲。","rad":"魚","fq":"徒何切","vol":"11","py":"tuó","duan":[{"e":"鮎也。","n":"釋魚、毛傳皆曰。鯊、鮀也。許以魦系樂浪潘國。釋鮀爲鮎。於古說不同。蓋有所受之也。春秋傳名鮀者字子魚。玉裁又按鯊見於詩。爾雅、毛傳皆曰。鯊、鮀也。許當無異說。不當訓爲鮎、而以鯊爲出樂浪潘國。蓋鮎、𩷑也。𩷑、鮎也。許同爾雅、毛傳。而鮀下訓沙也。亦與古同。毛詩鯊本作沙。故說文無鯊字。鮀下云沙也。淺人以爲怪。遂竄改錯亂如此。諸書紀載雖有魦字、从沙省聲。此樂浪潘國之魚。非詩之沙也。故不相牽混。許書之精嚴如此。〇邠風莎雞、古衹作沙。〇釋魚開卷鯉鱣爲一。鰋點爲一。鯊鮀爲一。許說皆同。惟鱧鯇爲一。許說不同。〇舍人云。鯊、石鮀也。郭云。今吹沙小魚也。體圓而有點文。"}]},"鮎":{"expl":"𩷑也。从魚占聲。","rad":"魚","fq":"奴兼切","vol":"11","py":"nián","duan":[{"e":"𩷑也。","n":"釋魚及魚麗傳曰。鰋、鮎也。孫炎云。鰋一名鮎。郭別鰋鮎爲二。非也。"}]},"𤛟":{"expl":"《易》曰：“𤛟牛乘馬。”从牛𤰈聲。","rad":"牛","fq":"平祕切","vol":"02","py":"bèi","duan":[{"e":"易曰。犕牛乘馬。","n":"此葢與革部之鞁同義。鞁、車駕具也。故玉篇云。犕、服也。以鞍裝馬也。"}]},"𩷑":{"expl":"鮀也。从魚妟聲。","rad":"魚","fq":"於幰切","vol":"11","py":"yǎn","duan":[{"e":"鮀也。","n":"謂之𩷑者、以其偃頟也。偃者、仰也。玉裁按鮀也乃鮎也之誤。妄人所改也。"}]},"鮷":{"expl":"大鮎也。从魚弟聲。","rad":"魚","fq":"杜兮切","vol":"11","py":"tí","duan":[{"e":"大鮎也。从魚。弟聲。","n":"此字詩爾雅釋文、廣韵作鮧。从夷。文選蜀都賦及玉篇作鮷。未知孰是。以夷弟篆體易譌也。山海經傳曰。今亦呼鮎爲䱱。字林曰。靑州人呼鮎鯷、郭注爾雅曰。鮎別名鯷。江東通呼鮎爲鮧。蓋鮷鯷䱱三形一字。同大兮反。而鮧則別一字、別一音。不當合而一之。杜兮切。十五部。"}]},"䲚":{"expl":"魚名。从魚賴聲。","rad":"魚","fq":"洛帶切","vol":"11","py":"lài","duan":[{"e":"䲚魚也。从魚。賴聲。","n":"洛帶切。十五部。"}]},"𩻛":{"expl":"魚名。从魚朁聲。","rad":"魚","fq":"鉏箴切","vol":"11","py":"cén","duan":[{"e":"𩻛魚也。","n":"此是魚名。類篇謂卽小魚爲䰼之䰼。非也。"}]},"䱵":{"expl":"魚名。从魚翁聲。","rad":"魚","fq":"烏紅切","vol":"11","py":"wēnɡ","duan":[{"e":"䱵魚也。从魚。翁聲。","n":"鳥紅切。九部。"}]},"䱤":{"expl":"魚名。从魚臽聲。","rad":"魚","fq":"尸𧸖切","vol":"11","py":"xiàn","duan":[{"e":"䱤魚也。从魚。臽聲。","n":"戸賺切。八部。"}]},"鱖":{"expl":"魚名。从魚厥聲。","rad":"魚","fq":"居衞切","vol":"11","py":"ɡuì","duan":[{"e":"鱖魚也。","n":"篇、韵皆曰。大口細鱗有斑文。卽今人所食之鱖魚也。而釋魚鱊鮬、鱖鯞。郭云。小魚也。似鮒子而黑。俗呼爲魚婢。江東呼爲妾魚。羅端良以今之彭皮當之。玉裁謂鯞音同婦。鱊鱖音近。鮬鯞音近。鱖婦卽今俗謂之鬼婆子是也。非別有細魚。鯞音章酉反。非。"}]},"鯫":{"expl":"白魚也。从魚取聲。","rad":"魚","fq":"士垢切","vol":"11","py":"zōu","duan":[{"e":"白魚也。","n":"白而小之魚也。史記、鯫千石。徐廣曰。鯫、鯫魚也。張守節曰。襍小魚也。按鯫是小魚之名。故小人謂之鯫生。師古於漢書作鮿字。音輒。蓋未然。"}]},"鱓":{"expl":"魚名。皮可爲鼓。从魚單聲。","rad":"魚","fq":"常演切","vol":"11","py":"shàn","duan":[{"e":"鱓魚也。","n":"今人所食之黃鱔也。黃質黑文。似蛇。異苑云。死人髪化。其字亦作䱇。俗作鱔。或叚鮮字爲之。如蠏篆下云非蛇鮮之穴無所庇是也。或叚鱣爲之。如楊震傳鳥銜三鱣是也。各本此下有皮可爲鼓四字。由古以鼉皮冒鼓。鼉鱓皆从單聲。古書如呂覽等皆叚鱓爲鼉。淺人𧢼讀古書。率尒妄增。不知字各有本義。許書但言本義。則此四字可增於黽部、而不可贅於此也。今𠜂正。"}]},"鮸":{"expl":"魚名。出薉邪頭國。从魚免聲。","rad":"魚","fq":"亡辨切","vol":"11","py":"miǎn","duan":[{"e":"鮸魚也。","n":"隋煬責貢四方。海錯幾盡。首曰鮸魚。按今江浙人所食海中黃花魚。乾之爲白鯗。卽此魚也。一名石首魚。首中有二石。許云出薉邪頭國者。蓋許據所見載籍言之。江賦。鯼鮆順時而往還。注云。字林曰。鯼魚、出南海。頭中有石。一名石首。然則此魚又名鯼。南海亦有之。"}]},"祚":{"expl":"福也。从示乍聲。","rad":"示","fq":"徂故切","vol":"01","py":"zuò","duan":[]},"𤛿":{"expl":"耕也。从牛黎聲。","rad":"牛","fq":"郎奚切","vol":"02","py":"lí","duan":[{"e":"耕也。","n":"山海經曰。后稷之孫曰叔均、是始作牛耕。郭傳。始用牛犂也。按耒部耕訓？。是？耕二字互訓。皆謂田器。今人分別。誤也。仲尼弟子列傳。冉耕、字伯牛。司馬耕、字子牛。論語。司馬牛。孔注曰。宋司馬犂也。此可證司馬牛名耕、一名犂也。葢其始人耕者謂之耕。牛耕者謂之犂。其後互名之。"}]},"魵":{"expl":"魚名。出薉邪頭國。从魚分聲。","rad":"魚","fq":"符分切","vol":"11","py":"fén","duan":[{"e":"魵魚也。","n":"釋魚曰。魵、鰕。謂魵魚一名鰕魚也。"}]},"䲐":{"expl":"魚名。出樂浪潘國。从魚虜聲。","rad":"魚","fq":"郎古切","vol":"11","py":"lǔ","duan":[{"e":"䲐魚也。出樂浪潘國。","n":"樂音洛。浪音郎。樂浪潘國眞番也。番音潘。"}]},"鰸":{"expl":"魚名。狀似蝦，無足，長寸，大如叉股，出遼東。从魚區聲。","rad":"魚","fq":"豈俱切","vol":"11","py":"qū","duan":[{"e":"鰸魚也。狀佀鰕。","n":"各本作蝦。誤。"}]},"鯜":{"expl":"魚名。出樂浪潘國。从魚妾聲。","rad":"魚","fq":"七接切","vol":"11","py":"qiè","duan":[{"e":"鯜魚也。出樂浪潘國。从魚。妾聲。","n":"七接切。八部。"}]},"䰽":{"expl":"魚名。出樂浪潘國。从魚巿聲。","rad":"魚","fq":"博蓋切","vol":"11","py":"bèi","duan":[{"e":"𩶚魚也。出樂浪潘國。从魚。𣎵聲。","n":"博葢切。十五部。"}]},"䱡":{"expl":"魚名。出樂浪潘國。从魚匊聲。一曰䱡魚出江東，有兩乳。","rad":"魚","fq":"居六切","vol":"11","py":"jú","duan":[{"e":"䱡魚也。出樂浪潘國。从魚。匊聲。","n":"居六切。三部。"}]},"魦":{"expl":"魚名。出樂浪潘國。从魚，沙省聲。","rad":"魚","fq":"所加切","vol":"11","py":"shā","duan":[{"e":"魦魚也。出樂浪潘國。从魚。沙省聲。","n":"詩小雅有鯊。則爲中夏之魚。非遠方外國之魚明甚。葢詩自作沙字。吹沙小魚也。樂浪潘國之魚必出於海。自作魦字。其狀不可得而言也。或云卽鮫魚。然魦鮫二篆不相連屬也。所加切。十七部。"}]},"鱳":{"expl":"魚名。出樂浪潘國。从魚樂聲。","rad":"魚","fq":"盧谷切","vol":"11","py":"lì","duan":[{"e":"鱳魚也。出樂浪潘國。从魚。樂聲。","n":"盧各切。古音在二部。"}]},"鮮":{"expl":"魚名。出貉國。从魚，羴省聲。","rad":"魚","fq":"相然切","vol":"11","py":"xiān","duan":[{"e":"鮮魚也。出貉國。","n":"按此乃魚名。經傳乃叚爲新鱻字。又叚爲尟少字。而本義廢矣。"}]},"鰅":{"expl":"魚名。皮有文，出樂浪東暆。神爵四年，初捕收輸考工。周成王時，揚州獻鰅。从魚禺聲。","rad":"魚","fq":"魚容切","vol":"11","py":"yónɡ","duan":[{"e":"鰅魚也。皮有文。","n":"上林賦郭注曰。鰅魚有文彩。按長卿謂八川之中有之。侈靡過其實也。據下文樂浪乃有之。然平子賦南都亦曰鱏鱣鰅鱅。是南陽有之。"}]},"㹃":{"expl":"兩壁耕也。从牛非聲。一曰覆耕穜也。讀若匪。","rad":"牛","fq":"非尾切","vol":"02","py":"fèi","duan":[{"e":"㒳壁耕也。","n":"壁當作辟。辟是旁側之語。莊卄一年左傳。鄭伯享王子闕西辟。服䖍云。西辟、西偏也。㒳辟耕謂一田中兩牛耕。一從東往、一從西來也。此耕字自人牛言之。與木部六叉犂自器言之不同。"}]},"鱅":{"expl":"魚名。从魚庸聲。","rad":"魚","fq":"蜀容切","vol":"11","py":"yōnɡ","duan":[{"e":"鱅魚也。","n":"史記上林賦。鰅鱅鰬魠。漢書、文選鱅皆作鰫。非是。據許書鰫鱅劃然二物。且郭注上林云鱅常容反。與慵字音正同。叚令从容聲、則不得反以常容矣。郭云。鱅似鰱而黑。陸璣云。鱮、徐州人謂之鰱。或謂之鱅。"}]},"鰂":{"expl":"烏鰂，魚名。从魚則聲。","rad":"魚","fq":"昨則切","vol":"11","py":"zéi","duan":[{"e":"烏鰂魚也。","n":"四字句。烏俗本作鰞。今正。陶貞白云。是𪇰烏所化。其口腹猶相似。腹中有墨。能吸波潠墨。令水溷黑自衞。劉淵林云。腹中有藥。謂其背骨。今名海鰾鮹是也。"}]},"鮐":{"expl":"海魚名。从魚台聲。","rad":"魚","fq":"徒哀切","vol":"11","py":"tái","duan":[{"e":"海魚也。","n":"各本也作名。今依史記正義、漢書注、文選七命注正。鮐亦名侯鮐。卽今之河豚也。吳都賦。王鮪侯鮐。以王侯相儷。改作鯸者、非。貨殖傳。鮐鮆千斤。鮐狀如科斗。背上靑黑。有黃文。詩。黃髮台背。毛曰。台背、大老也。箋云。台之言鮐也。大老則背有鮐文。是謂台爲鮐之叚借字。今爾雅作鮐背。"}]},"鮊":{"expl":"海魚名。从魚白聲。","rad":"魚","fq":"旁陌切","vol":"11","py":"bà","duan":[{"e":"海魚也。从魚。白聲。","n":"旁陌切。古音在五部。玉篇讀平亞切。廣韵𧜗韵作𩹏。"}]},"鰒":{"expl":"海魚名。从魚复聲。","rad":"魚","fq":"蒲角切","vol":"11","py":"fù","duan":[{"e":"海魚也。","n":"郭注三倉曰。鰒似蛤。一偏著石。廣志曰。鰒無鱗有𣪊。一面附石。細孔襍襍。或七或九。本艸曰。石決明、一名鰒魚。李時珍云。與石決明同類殊種。"}]},"鮫":{"expl":"海魚，皮可飾刀。从魚交聲。","rad":"魚","fq":"古肴切","vol":"11","py":"jiāo","duan":[{"e":"海魚也。皮可飾刀。","n":"今所謂沙魚。所謂沙魚皮也。許有魦字、云从沙省。葢卽此魚。陳藏器曰。沙魚狀皃非一。皆皮上有沙。堪揩木。如木賊。蘇頌曰。其皮可飾刀靶。按其皮可磨錯。故通謂之䱜魚。音措各切。有鐇䱜、有横骨在鼻前如斤斧形者也。有出入䱜、子朝出求食暮還入母腹中者也。淮南子。鮫革犀兕爲甲冑。中山經有鮫魚。郭云。卽此魚。中庸。黿鼉鮫龍。本又作蛟。"}]},"䲔":{"expl":"海大魚也。从魚畺聲。《春秋傳》曰：“取其䲔鯢。”","rad":"魚","fq":"渠京切","vol":"11","py":"jīnɡ","duan":[{"e":"海大魚也。","n":"此海中魚冣大者。字亦作鯨。羽獵賦作京。京、大也。"}]},"鯁":{"expl":"魚骨也。从魚更聲。","rad":"魚","fq":"古杏切","vol":"11","py":"ɡěnɡ","duan":[{"e":"魚骨也。","n":"故其字从魚。與骨部骾字別。而骨骾字亦多借鯁爲之。爾雅曰。魚枕謂之丁。魚腸謂之乙。魚尾謂之丙。今益之曰魚骨謂之鯁、魚甲謂之鱗。魚臭謂之鮏。"}]},"鱗":{"expl":"魚甲也。从魚粦聲。","rad":"魚","fq":"力珍切","vol":"11","py":"lín","duan":[{"e":"魚甲也。","n":"甲者、鎧也。魚鱗似鎧。亦有無鱗有甲之魚。鱣是也。"}]},"鮏":{"expl":"魚臭也。从魚生聲。","rad":"魚","fq":"桑經切","vol":"11","py":"xīnɡ","duan":[{"e":"魚臭也。","n":"魚气也。與肉部胜義別。字俗作鯹。"}]},"㹗":{"expl":"牛羊無子也。从牛𠷎聲。讀若糗糧之糗。","rad":"牛","fq":"徒刀切","vol":"02","py":"tāo","duan":[{"e":"牛羊無子也。从牛。𠷎聲。讀若糗糧之糗。","n":"糗糧見粊誓。徒刀切。古音在三部。"}]},"鱢":{"expl":"鮏臭也。从魚喿聲。《周禮》曰：“膳膏鱢。”","rad":"魚","fq":"穌遭切","vol":"11","py":"sāo","duan":[{"e":"鮏臭也。从魚。喿聲。","n":"穌遭切。二部。"}]},"鮨":{"expl":"魚䏽醬也。出蜀中。从魚旨聲。一曰鮪魚名。","rad":"魚","fq":"旨夷切","vol":"11","py":"qí","duan":[{"e":"魚䏽𤖕也。","n":"醬字衍。䏽者、豕肉醬也。引申爲魚肉醬。則偁魚䏽可矣。公食大夫禮牛鮨注曰。內則鮨爲膾。然則膾用鮨。謂此經之醢牛鮨、卽內則之醢牛膾也。聶而切之爲膾。更細切之、則成醬爲鮨矣。鮨者、膾之冣細者也。牛得名鮨、猶魚得名䏽也。鄭曰。今文鮨作鰭。按鰭是叚借字。說文有耆無鰭。"}]},"鮺":{"expl":"藏魚也。南方謂之䰼，北方謂之鮺。从魚，差省聲。","rad":"魚","fq":"側下切","vol":"11","py":"zhǎ","duan":[{"e":"臧魚也。","n":"釋名曰。鮓、菹也。以鹽米釀魚爲菹。孰而食之也。按古作鮺之法。令魚不㱙壞。故陶士行遠遺其母。卽內則之魚膾、聶而切之者也。"}]},"䰼":{"expl":"鮺也。一曰大魚爲鮺，小魚爲䰼。从魚今聲。","rad":"魚","fq":"徂慘切","vol":"11","py":"qín","duan":[{"e":"鮺也。","n":"渾言不別。析言則別之。"}]},"鮑":{"expl":"饐魚也。从魚包聲。","rad":"魚","fq":"薄巧切","vol":"11","py":"bào","duan":[{"e":"饐魚也。","n":"饐、飯傷溼也。故鹽魚溼者爲饐魚。周禮籩人有鮑。注云。鮑者、於𤐧室中𤐧乾之。出於江淮。師古注漢書曰。鮑、今之䱒魚也。鄭以爲於煏室乾之。非也。秦始皇載鮑亂臭、則是䱒魚耳。而煏室乾者、本不臭也。䱒於業反。按玉篇作裛魚。皆當作浥耳。浥、溼也。釋名曰。鲍、腐也。埋藏淹使腐臭也。"}]},"魿":{"expl":"蟲連行紆行者。从魚令聲。","rad":"魚","fq":"郎丁切","vol":"11","py":"línɡ","duan":[{"e":"蟲連行紆行者。","n":"考工記梓人注曰。連行、魚屬。紆行、蛇屬。按紆者、詘也。縈也。蛇行必縈曲。"}]},"鰕":{"expl":"魵也。从魚叚聲。","rad":"魚","fq":"乎加切","vol":"11","py":"xiā","duan":[{"e":"鰕魚也。","n":"三字句。各本作魵也。今正。鰕者、今之蝦字。古謂之鰕魚。如鼉曰鼉魚。馬部騢下云。色似鰕魚。驒下云。文如鼉魚。郭注爾雅云。今靑州呼鰕魚爲鰝。皆其證。鰕篆是此物正字。不訓以鰕魚、則騢之似鰕魚、鰸之狀似鰕爲似何物乎。況鰕篆之下緊接鰝篆。釋云大鰕。鰝爲今之大蝦無可疑者。若如各本、則鰝不爲大魵乎。由釋魚有魵鰕之文。郭曰出穢邪頭國、與說文魵解同。淺人遂改鰕篆之解爲魵也。不知許立文之例以類相從。鰕果是魵、則鰕篆必次魵篆後。不次鰝篆前。至於物有同名異實者。如爾雅鰕三見。鰝大鰕、則今之蝦也。魵鰕、則穢邪頭之魚也。鯢大者謂之鰕、則今有四腳之魚也。而皆謂之鰕。豈可合而一之乎。鰕篆者、長須水蟲之正字。古亦借瑕爲之。凡叚"}]},"鰝":{"expl":"大鰕也。从魚高聲。","rad":"魚","fq":"胡到切","vol":"11","py":"hào","duan":[{"e":"大鰕也。","n":"見釋魚。郭云。鰕大者出海中。長二三丈。鬚長數丈。今靑州呼鰕魚大者爲鰝鰕。吳都賦曰。罺鰝鰕。"}]},"鯦":{"expl":"當互也。从魚咎聲。","rad":"魚","fq":"其久切","vol":"11","py":"jiù","duan":[{"e":"當互也。","n":"見釋魚。今爾雅互作魱。郭云。海魚也。似鯿而大鱗。肥美多鯁。今江東呼其冣大長三尺者爲當魱。魱音胡。按集韵、類篇模韵魱字注云。吳人以爲珍。卽今時魚。尋繹郭注、誠謂時魚也。時魚、七之作鰣。或作？。廣韵亦曰。鰣魚似魴。肥美。江東四月有之。但依許氏立文之例求其義。自鰕至鮚六字皆字从魚而實非魚者。故殿於魚部之末。如蠅？鼄鼂必居黽尾、驘驢騱駼必廁馬後也。然則許說爲何物不可知。而必與郭說異。亦猶鱴刀、鄭云薶物。郭乃云薺魚。互俗作魱。葢非是。當是？之省。？者、罟也。見网部。"}]},"魧":{"expl":"大貝也。一曰魚膏。从魚亢聲。讀若岡。","rad":"魚","fq":"古郎切","vol":"11","py":"hánɡ","duan":[{"e":"大貝也。","n":"貝、海介蟲也。居陸名猋。在水名函。釋魚曰。大者魧。尙書大傳曰。散宜生得大貝。如車渠。車渠、車网也。車网者、輮也。江賦字作蚢。"}]},"牴":{"expl":"觸也。从牛氐聲。","rad":"牛","fq":"都禮切","vol":"02","py":"dǐ","duan":[{"e":"觸也。","n":"角部曰。觸、牴也。亦作抵觝。"}]},"𩶁":{"expl":"蚌也。从魚丙聲。","rad":"魚","fq":"兵永切","vol":"11","py":"bǐnɡ","duan":[{"e":"蚌也。","n":"蚌者、辱屬。亦名𩶁。"}]},"鮚":{"expl":"蚌也。从魚吉聲。漢律：會稽郡獻鮚𤖕。","rad":"魚","fq":"巨乙切","vol":"11","py":"jí","duan":[{"e":"蚌也。","n":"地理志。會稽鄞縣有鮚埼亭。師古曰。鮚、蚌也。長一寸。廣二分。有一小蟹在其腹中。埼、曲岸也。其中多鮚。故以名亭。按此名瑣鮚。瑣者、小也。鮚之小者。江賦。瑣蛣腹蟹。注引南越志曰。瑣蛣長寸餘。大者長二三寸。腹中有蟹子。如榆莢。合體共生。皆爲蛣取食。"}]},"鮅":{"expl":"魚名。从魚必聲。","rad":"魚","fq":"毗必切","vol":"11","py":"bì","duan":[{"e":"魚名。从魚。必聲。","n":"毗必切。按自鮅至？十篆葢皆非許書所本有。以魚部䲊鮞爲魚子。自魼至䲔皆魚名。自鯁至鮑皆泛言魚之體、魚之用。自魿至鮚皆字从魚而實非魚者。至此而魚部畢矣。不當又舉魚名及魚之狀皃。故知必淺人所增也。釋魚云。鮅鱒。系一魚二名。儻許錄鮅字、便當與鱒相聯。由許時爾雅本無鮅字、但作必。必則例不錄。"}]},"𩽩":{"expl":"魚名。从魚瞿聲。","rad":"魚","fq":"九遇切","vol":"11","py":"qú","duan":[{"e":"魚名。从魚。瞿聲。","n":"九遇切。"}]},"鯸":{"expl":"魚名。从魚侯聲。","rad":"魚","fq":"乎鉤切","vol":"11","py":"hóu","duan":[{"e":"魚名。从魚。矦聲。","n":"乎鉤切。按吳都賦？鮐、當是本作矦鮐。故與王鮪相儷。廣雅？䱌、卽矦鮐之俗字也。叚令許錄？字、則當厠於鮐篆之上。"}]},"鯛":{"expl":"骨耑脃也。从魚周聲。","rad":"魚","fq":"都僚切","vol":"11","py":"diāo","duan":[{"e":"骨耑脃也。从魚。周聲。","n":"都僚切。如其義、則當與鯁篆相屬。篇、韵皆曰魚名、何也。"}]},"𩷹":{"expl":"烝然𩷹𩷹。从魚卓聲。","rad":"魚","fq":"都教切","vol":"11","py":"zhuó","duan":[{"e":"烝然𩷹𩷹。从魚。卓聲。","n":"都敎切。按詩南有嘉魚、烝然罩罩傳曰。罩、籗也。音義罩張敎反。此偁詩作？？、不言其義。篇、韵皆不載其字。大徐云都敎切者、非唐韵有此字此音。乃傳合毛詩音義爲此音耳。集韵、類篇效韵亦無此字。惟覺韵有此字。訓曰魚名。葢其可疑如此。"}]},"鮁":{"expl":"鱣鮪鮁鮁。从魚犮聲。","rad":"魚","fq":"北末切","vol":"11","py":"bō","duan":[{"e":"鱣鮪鮁鮁。从魚。犮聲。","n":"北末切。按毛詩鱣鮪發發傳曰。發發、盛皃。音義云。補末反。韓詩作鱍。是作鮁者非毛、非韓。不可信。又不言其義篇、韵皆無鮁字。其可疑如此。"}]},"𩽺":{"expl":"鯕魚。出東萊。从魚夫聲。","rad":"魚","fq":"甫無切","vol":"11","py":"fū","duan":[{"e":"鯕魚。出東萊。从魚。夫聲。","n":"甫無切。依玉篇當作𩵩鯕魚。"}]},"鯕":{"expl":"魚名。从魚其聲。","rad":"魚","fq":"渠之切","vol":"11","py":"qí","duan":[{"e":"魚名。从魚。其聲。","n":"渠之切。按其訓當云𩵩鯕也。廣韵七之又單出鯕字。云鯿魚。"}]},"𤜂":{"expl":"牛踶𤜂也。从牛衞聲。","rad":"牛","fq":"于歲切","vol":"02","py":"wèi","duan":[{"e":"牛踶𤜂也。","n":"廣韵曰。踶𤜂、牛展足。按展足二字乃𨃨字之誤。𨃨同跈。足部曰。踶者、躛也。𤜂與躛互訓。踶𤜂猶踐蹋也。"}]},"鮡":{"expl":"魚名。从魚兆聲。","rad":"魚","fq":"治小切","vol":"11","py":"zhào","duan":[{"e":"魚名。从魚。兆聲。","n":"治小切。按字見爾雅。鱯之小者也。叚令許錄此字。當與鱯篆相屬。"}]},"𩵏":{"expl":"魚名。从魚匕聲。","rad":"魚","fq":"呼跨切","vol":"11","py":"huà","duan":[{"e":"魚名。从魚。匕聲。","n":"呼跨切。"}]},"鱻":{"expl":"新魚精也。从三魚。不變魚。","rad":"魚","fq":"相然切","vol":"11","py":"xiān","duan":[{"e":"新魚精也。","n":"云精者、卽今之鯖字。廣韵云。煑魚煎食曰五矦鯖。煎食作煎肉者、誤。謂以新魚爲肴也。周禮䱷人。辨魚物爲鱻薧。鄭司農曰。鮮、生也。薧、乾也。詩思文正義引鄭注尙書曰。衆鱻食、謂魚鼈也。引申爲凡物新者之偁。獸人六畜六獸六禽亦偁鱻薧。史言數見不鮮。許書玼下云新玉色鮮也、黨下云不鮮也。其字葢皆本作鱻。凡鮮明、鮮新字皆當作鱻。自漢人始以鮮代鱻。如周禮經作鱻、注作鮮是其證。至說文全書不用叚借字。而玼下黨下亦皆爲淺人所改。今則鮮行而鱻廢矣。"}]},"鰈":{"expl":"比目魚也。从魚枼聲。","rad":"魚","fq":"土盍切","vol":"11","py":"tà","duan":[]},"魮":{"expl":"文魮，魚名。从魚比聲。","rad":"魚","fq":"房脂切","vol":"11","py":"bǐ","duan":[]},"鰩":{"expl":"文鰩，魚名。从魚䍃聲。","rad":"魚","fq":"余招切","vol":"11","py":"yáo","duan":[]},"𩺰":{"expl":"二魚也。凡𩺰之屬皆从𩺰。","rad":"𩺰","fq":"語居切","vol":"11","py":"yú","duan":[{"e":"二魚也。","n":"此卽形爲義。故不言从二魚。二魚重而不竝。易所謂貫魚也。魚行必相隨也。晉語。暇䂊之吾吾。不如鳥烏。韋注。吾讀如魚。韓文公詩用魚魚雅雅。豈卽本國語乎。从二魚與从三魚不同。三魚謂不變其新。二魚謂連行可觀。語居切。五部。"}]},"𩼪":{"expl":"捕魚也。从𩺰从水。","rad":"𩺰","fq":"語居切","vol":"11","py":"yú","duan":[{"e":"搏魚也。","n":"搏舊作捕。今正。搏、𡩡持也。漢人用搏字多如此。捕魚字古多作魚。如周禮䱷人、本作魚。此與取鼈者曰鼈人、取獸者曰獸人同也。左傳。公將如棠觀魚者。魚者、謂捕魚者也。呂氏春秋、淮南鴻烈高注每云。漁讀如論語之語、讀如相語之語。尋其文義皆由本文作魚。故爲讀若以別諸水蟲。周禮音義。𤣏本作魚。又音御。御音卽高氏之語音也。然則古文本作魚、作𩺰。？其籒文乎。至小篆則𡞞爲漁矣。周禮當从古作魚人。作䰻者、次之。作䱷者、非也。"}]},"燕":{"expl":"玄鳥也。籋口，布翄，枝尾。象形。凡燕之屬皆从燕。","rad":"燕","fq":"於甸切","vol":"11","py":"yàn","duan":[{"e":"燕燕、玄鳥也。","n":"各本無燕燕二字。今補。𠃉下曰。燕燕也。齊魯謂之𠃉。隹部巂下曰。巂周者、燕也。邶風傳曰。燕燕、𠃉也。商頌傳曰。玄鳥、𠃉也。釋鳥曰。巂周、燕燕、𠃉也。古多叚燕爲宴安、宴享。"}]},"龍":{"expl":"鱗蟲之長。能幽，能明，能細，能巨，能短，能長；春分而登天，秋分而潛淵。从肉，飛之形，童省聲。凡龍之屬皆从龍。","rad":"龍","fq":"力鍾切","vol":"11","py":"lónɡ","duan":[{"e":"𩼩蟲之長。能幽能朙。能細能巨。能短能長。","n":"四句一韵。"}]},"㹂":{"expl":"牛很不從引也。从牛从臤，臤亦聲。一曰大皃。讀若賢。","rad":"牛","fq":"喫善切","vol":"02","py":"qiǎn","duan":[{"e":"牛很不從牽也。从牛臤。","n":"臤者、堅也。故从牛臤。會意。"}]},"龗":{"expl":"龍也。从龍霝聲。","rad":"龍","fq":"郎丁切","vol":"11","py":"línɡ","duan":[{"e":"龍也。","n":"雙聲轉注。"}]},"龕":{"expl":"龍皃。从龍合聲。","rad":"龍","fq":"口含切","vol":"11","py":"kān","duan":[]},"䶬":{"expl":"龍耆𦟝上䶬䶬。从龍幵聲。","rad":"龍","fq":"古賢切","vol":"11","py":"jiān","duan":[{"e":"龍者脊上䶬䶬也。","n":"士喪禮。載魚左首進鬐。注曰。鬐、脊也。古文鬐爲耆。按此鄭从今文、而㬪古文於注也。許髟部無鬐。此出耆者、許於此字從禮古文。不從禮今文也。耆者、老也。老則脊隆。故凡脊曰耆。或作鬐。因馬鬣爲此字也。龍魚之脊上出者、如馬鬣然。上林賦曰。揵鰭掉尾。郭云。鰭、背上鬣也。鰭亦耆之今字。渾言之耆卽脊。析言耆在脊上。䶬䶬、龍耆皃。"}]},"龖":{"expl":"飛龍也。从二龍。讀若沓。","rad":"龍","fq":"徒合切","vol":"11","py":"tà","duan":[{"e":"飛龍也。","n":"廣韵曰。龍飛之狀。"}]},"飛":{"expl":"鳥翥也。象形。凡飛之屬皆从飛。","rad":"飛","fq":"甫微切","vol":"11","py":"fēi","duan":[{"e":"鳥翥也。","n":"羽部曰。翥者、飛舉也。古或叚蜚爲飛。"}]},"𩙺":{"expl":"翄也。从飛異聲。","rad":"飛","fq":"與職切","vol":"11","py":"yì","duan":[{"e":"翄也。","n":"羽部曰。翄者、翼也。二篆爲轉注。翼必兩相輔。故引申爲輔翼。卷阿傳曰。道可馮依以爲輔翼也。行葦鄭箋云。在前曰引。在旁曰翼。又凡敬者、必如兩翼之整齊。故毛傳曰。翼、敬也。鄭箋云。小心翼翼、恭愼皃。"}]},"非":{"expl":"違也。从飛下翄，取其相背。凡非之屬皆从非。","rad":"非","fq":"甫微切","vol":"11","py":"fēi","duan":[{"e":"韋也。","n":"韋各本作違。今正。違者、離也。韋者、相背也。自違行韋廢。盡改韋爲違。此其一也。非以相背爲義。不以離爲義。"}]},"䨽":{"expl":"別也。从非己聲。","rad":"非","fq":"非尾切","vol":"11","py":"fěi","duan":[{"e":"別也。","n":"別者、分解也。"}]},"靡":{"expl":"披靡也。从非麻聲。","rad":"非","fq":"文彼切","vol":"11","py":"mǐ","duan":[{"e":"柀靡也。","n":"柀各本作披。今正。柀靡、㬪韵字。旇下曰。旌旗柀靡也。項羽傳。漢軍皆柀靡。顔師古、張守節皆普彼反。葢其字本作柀。从木。析也。寫者譌从手。柀靡、分散下垂之皃。易中孚九二曰。吾與爾靡之。孟、王皆曰。散也。凡物分散則微細。引申之謂精細可喜曰靡麗。爾下曰麗爾猶靡麗也是也。又與亡字、無字皆雙聲。故謂無曰靡。"}]},"靠":{"expl":"相違也。从非告聲。","rad":"非","fq":"苦到切","vol":"11","py":"kào","duan":[{"e":"相韋也。","n":"韋各本作違。今正。相韋者、相背也。故从非。今俗謂相依曰靠。古人謂相背曰靠。其義一也。猶分之合之皆曰離。"}]},"牼":{"expl":"牛厀下骨也。从牛巠聲。《春秋傳》曰：“宋司馬牼字牛。”","rad":"牛","fq":"口莖切","vol":"02","py":"kēnɡ","duan":[{"e":"牛厀下骨也。","n":"牛脛也。脛者、骹也。"}]},"𨻼":{"expl":"牢也。所以拘非也。从非，陛省聲。","rad":"非","fq":"邊兮切","vol":"11","py":"bī","duan":[{"e":"𨻼牢謂之獄。","n":"五字句。各本作牢也二字。今依韵會本訂。牛部曰。牢者、閑養牛馬圏也。引申之、凡閑罪人者曰𨻼牢。卽夏均臺、殷羑里、周圜土、秦囹圄、漢若盧也。法言曰。狴犴使人多禮。字作狴。猶鄉亭之繫曰犴、朝廷曰獄。字皆从犬。"}]},"卂":{"expl":"疾飛也。从飛而羽不見。凡卂之屬皆从卂。","rad":"卂","fq":"息晉切","vol":"11","py":"xùn","duan":[{"e":"疾飛也。","n":"引申爲凡疾之偁。故撞下曰卂擣也。辵部迅、从卂。"}]},"煢":{"expl":"回疾也。从卂，營省聲。","rad":"卂","fq":"渠營切","vol":"11","py":"qiónɡ","duan":[{"e":"回疾也。","n":"回轉之疾飛也。引申爲煢獨，取裵回無所依之意。或作𢞛，作睘，作嬛。毛傳曰：睘睘，無所依也。"}]},"𠃉":{"expl":"玄鳥也。齊魯謂之𠃉。取其鳴自呼。象形。凡𠃉之屬借从𠃉。","rad":"𠃉","fq":"烏轄切","vol":"12","py":"yǐ","duan":[{"e":"燕燕。𠃉鳥也。","n":"燕燕見前篇。玄鳥二字淺人所增。"}]},"孔":{"expl":"通也。从𠃉从子。𠃉，請子之候鳥也。𠃉至而得子，嘉美之也。古人名嘉字子孔。","rad":"𠃉","fq":"康董切","vol":"12","py":"kǒnɡ","duan":[{"e":"通也。","n":"通者達也。於易卦爲泰。孔訓通、故俗作空穴字多作孔。其實空者、竅也。作孔爲叚借。"}]},"乳":{"expl":"人及鳥生子曰乳，獸曰産。从孚从𠃉。𠃉者，玄鳥也。《明堂月令》：“玄鳥至之日，祠于高禖，以請子。”故乳从𠃉。請子必以𠃉至之日者，𠃉，春分來，秋分去，開生之候鳥，帝少昊司分之官也。","rad":"𠃉","fq":"而主切","vol":"12","py":"rǔ","duan":[{"e":"人及鳥生子曰乳。獸曰產。","n":"生部曰。生、進也。產、生也。渾言之。此復析言之。孺下曰。乳子也。按古書之文多通偁。"}]},"不":{"expl":"鳥飛上翔不下來也。从一，一猶天也。象形。凡不之屬皆从不。","rad":"不","fq":"方久切","vol":"12","py":"fǒu","duan":[{"e":"鳥飛上翔不下來也。","n":"凡云不然者。皆於此義引申叚借。其音古在一部。讀如德韵之北。音轉入尤、有韵讀甫鳩、甫九切。與弗字音義皆殊。音之殊、則弗在十五部也。義之殊。則不輕弗重。如嘉肴弗食不知其旨、至道弗學、不知其善之類可見。公羊傳曰。弗者、不之深也。俗韵書謂不同弗。非是。又詩鄂不？？箋云。不當作柎。柎、鄂足也。古聲不柎同。"}]},"否":{"expl":"不也。从口从不，不亦聲。","rad":"不","fq":"方久切","vol":"12","py":"fǒu","duan":[]},"至":{"expl":"鳥飛从高下至地也。从一，一猶地也。象形。不，上去；而至，下來也。凡至之屬皆从至。","rad":"至","fq":"脂利切","vol":"12","py":"zhì","duan":[{"e":"鳥飛從高下至地也。","n":"凡云來至者、皆於此義引申叚借。引申之爲𢡆至、爲極至。許云到、至也。臻、至也。徦、至也。此本義之引申也。又云親、至也。寴、至也。此餘義之引申也。"}]},"到":{"expl":"至也。从至刀聲。","rad":"至","fq":"都悼切","vol":"12","py":"dào","duan":[{"e":"至也。","n":"大雅曰。靡國不到。論語兩言民到于今。釋詁曰。到、至也。"}]},"𤘡":{"expl":"牛舌病也。从牛今聲。","rad":"牛","fq":"巨禁切","vol":"02","py":"jìn","duan":[{"e":"牛舌病也。","n":"廣韵作牛舌下病。舌病則噤閉不成聲。亦作𦧈。"}]},"臻":{"expl":"至也。从至秦聲。","rad":"至","fq":"側詵切","vol":"12","py":"zhēn","duan":[{"e":"至也。","n":"見釋詁。古亦叚溱爲之。"}]},"𦥊":{"expl":"忿戾也。从至，至而復遜。遜，遁也。《周書》曰：“有夏氏之民叨𦥊。”𦥊，讀若摯。","rad":"至","fq":"丑利切","vol":"12","py":"chì","duan":[{"e":"忿戾也。从至。至而復孫。","n":"會意也。"}]},"臺":{"expl":"觀，四方而高者。从至从之，从高省。與室屋同意。","rad":"至","fq":"徒哀切","vol":"12","py":"tái","duan":[{"e":"觀四方而高者也。","n":"釋名曰。觀、觀也。於上觀望也。觀不必四方。其四方獨出而高者、則謂之臺。大雅。經始靈臺。釋宮、毛傳曰。四方而高曰臺。傳意高而不四方者則謂之觀、謂之闕也。釋名。臺、持也。築土堅高能自勝持也。古臺讀同持。心曰靈臺。謂能持物。淮南子。其所居神者、臺𥳑以游大淸。注。臺、持也。又臺無所鑒、謂之狂生。注。臺、持也。此皆作臺自可通。或作古文握。古文握與臺形相似。"}]},"臸":{"expl":"到也。从二至。","rad":"至","fq":"人質切","vol":"12","py":"rì","duan":[{"e":"到也。","n":"不言至言到者、到者至之得地者也。辵部曰。𨖹、近也。从聲。然則二至當重不當竝。"}]},"西":{"expl":"鳥在巢上。象形。日在西方而鳥棲，故因以爲東西之西。凡西之屬皆从西。","rad":"西","fq":"先稽切","vol":"12","py":"xī","duan":[{"e":"鳥在巢上也。象形。","n":"下象巢。上象鳥。會意。上下皆非字也。故不曰會意而曰象形。鳥在巢上者、此篆之本義。今音先稽切。古音讀如詵、讀如𠎣。如西施亦作先施。漢書曰。西、遷也。古音在十二十三部。"}]},"䙵":{"expl":"姓也。从西圭聲。","rad":"西","fq":"户圭切","vol":"12","py":"xī","duan":[{"e":"姓也。从㢴。圭聲。","n":"户圭切。按許書自女部姬姜等十二字而外。未有云姓者。古之神聖、母感天而生。故字从女。是以姬姜等十二字皆从女。其他繼別爲氏。或以字、或以官、或以邑。雖亦可謂之姓。而其字不容列於說文。黃帝姬姓。而黃帝之子十二姓者。除姬姞字外。酉祁已滕箴任苟僖儇依十字、許皆不云姓是也。惟夨部吳下云姓也、郡也。爲妄人所增。而此䙵篆解云姓也。雖篆文亦屬僞羼。葢必有妄人以許書無其姓爲恥而竄入之。傳寫遂莫之察。許果有此篆、必釋其本義。不徒云姓也。小徐云。張說梁四公子記有䙵闖。依廣韵梁四公子字作罣。與䙵各字。"}]},"鹵":{"expl":"西方鹹地也。从西省，象鹽形。安定有鹵縣。東方謂之㡿，西方謂之鹵。凡鹵之屬皆从鹵。","rad":"鹵","fq":"郎古切","vol":"12","py":"lǔ","duan":[{"e":"西方鹹地也。从㢴省。","n":"省字衍。此承上文㢴部从㢴之籒文也。謂卤也。"}]},"𪉤":{"expl":"鹹也。从鹵，差省聲。河内謂之𪉤，沛人言若虘。","rad":"鹵","fq":"昨河切","vol":"12","py":"cuó","duan":[{"e":"鹹𪊁也。","n":"𪊁字各本缺。淺人謂複字而刪之也。今補。曲禮。凡祭宗廟之禮。鹽曰鹹鹺。鄭注。大鹹曰鹺。今河東云。按鹹𪊁古語、不容刪字。"}]},"鹹":{"expl":"銜也。北方味也。从鹵咸聲。","rad":"鹵","fq":"胡毚切","vol":"12","py":"xián","duan":[{"e":"銜也。","n":"以㬪韵爲訓。"}]},"鹽":{"expl":"鹹也。从鹵監聲。古者，宿沙初作煑海鹽。凡鹽之屬皆从鹽。","rad":"鹽","fq":"余廉切","vol":"12","py":"yán","duan":[{"e":"鹵也。天生曰鹵。人生曰鹽。","n":"十字各本作鹹也二字。今正。鹽之味鹹。鹽不訓爲鹹。玄應書三引說文天生曰鹵。人生曰鹽。當在此處。上冠以鹵也二字。則渾言、析言者備矣。周禮。鹽人掌鹽之政令。有出鹽直用不湅治者。有湅治者。"}]},"犀":{"expl":"南徼外牛。一角在鼻，一角在頂，似豕。从牛㞑聲。","rad":"牛","fq":"先稽切","vol":"02","py":"xī","duan":[{"e":"徼外牛。","n":"各本有南字。今依韵會。楚語曰。巴浦之犀犛兕象。其可盡乎。後漢章帝紀。蠻夷獻生犀、白雉。"}]},"盬":{"expl":"河東鹽池。袤五十一里，廣七里，周百十六里。从鹽省，古聲。","rad":"鹽","fq":"公户切","vol":"12","py":"ɡǔ","duan":[{"e":"河東鹽池也。","n":"地理志。河東郡安邑。鹽池在西南。郡國志亦云。安邑有鹽池。左氏傳曰。郇瑕氏之地。沃饒而近盬。服䖍注云。盬、鹽池也。土俗裂水沃麻。分灌川野。畦水秏竭。土自成鹽。卽所謂鹹鹺也。而味苦。號曰？田。杜注左氏、郭注穆天子傳皆曰。盬者、鹽池。然則鹽池古者謂之盬。亦曰盬田。周禮因以爲鹽不湅治之偁。又引申之、詩以爲不堅固之偁。周禮苦良。苦讀爲盬。謂物之不佳者也。"}]},"鹼":{"expl":"鹵也。从鹽省，僉聲。","rad":"鹽","fq":"魚欠切","vol":"12","py":"jiǎn","duan":[{"e":"鹵也。","n":"廣韵千廉切。水和鹽也。"}]},"戶":{"expl":"護也。半門曰戶。象形。凡戶之屬皆从戶。","rad":"戶","fq":"矦古切","vol":"12","py":"hù","duan":[{"e":"護也。","n":"以㬪韵爲訓。"}]},"扉":{"expl":"戶扇也。从戶非聲。","rad":"戶","fq":"甫微切","vol":"12","py":"fēi","duan":[{"e":"戶扇也。","n":"釋宮曰。？謂之扉。門？、門扇也。然則門戶一也。"}]},"扇":{"expl":"扉也。从戶，从翄聲。","rad":"戶","fq":"式戰切","vol":"12","py":"shàn","duan":[{"e":"扉也。","n":"月令。乃脩？扇。注云。用木曰？。用竹葦曰扇。案析言如此。渾言之則不拘。"}]},"房":{"expl":"室在㫄也。从戶方聲。","rad":"戶","fq":"符方切","vol":"12","py":"fánɡ","duan":[{"e":"室在旁也。","n":"凡堂之內、中爲正室。左右爲房。所謂東房西房也。引申之俎亦有房。"}]},"戻":{"expl":"輜車㫄推戶也。从戶大聲。讀與釱同。","rad":"戶","fq":"徒蓋切","vol":"12","py":"tì","duan":[{"e":"輺車旁推戶也。","n":"輺車者、衣車也。前後有蔽。旁有可開之戶。"}]},"戹":{"expl":"隘也。从戶乙聲。","rad":"戶","fq":"於革切","vol":"12","py":"è","duan":[{"e":"隘也。","n":"隘者、陋也。陋者、阸陜也。陜者、隘也。"}]},"肁":{"expl":"始開也。从戶从聿。","rad":"戶","fq":"治矯切","vol":"12","py":"zhào","duan":[{"e":"始開也。","n":"引申爲凡姶之偁。凡經傳言肈始者、皆肁之叚借。肈行而肁廢矣。釋詁、毛詩傳皆曰。肈、始也。戈部曰。肈、擊也。"}]},"扆":{"expl":"戶牖之閒謂之扆。从戶衣聲。","rad":"戶","fq":"於豈切","vol":"12","py":"yǐ","duan":[{"e":"戶牖之閒謂之扆。","n":"釋宫曰。牖戶之閒謂之扆。凡室、戶東牖西。戶牖之中閒是曰扆。詩、禮多叚依爲之。"}]},"牣":{"expl":"牣，滿也。从牛刃聲。《詩》曰：“於牣魚躍。”","rad":"牛","fq":"而震切","vol":"02","py":"rèn","duan":[{"e":"牣、","n":"此複字刪之未盡者。"}]},"㧁":{"expl":"閉也。从戶，劫省聲。","rad":"戶","fq":"口盍切","vol":"12","py":"qù","duan":[{"e":"閉也。","n":"士喪禮注曰。徹帷㧁之事畢、則下之襍記注曰。旣出、則施其㧁。鬼神尙幽闇也。據此二注、㧁爲褰舉之義。與東都賦袪黼帷同。疑閉當作開。一說、㧁在開閉之閒。故兼此二義。"}]},"扃":{"expl":"外閉之關也。从戶冋聲。","rad":"戶","fq":"古熒切","vol":"12","py":"jiōnɡ","duan":[{"e":"外閉之關也。","n":"關者、以木横持門戶也。曲禮。入戶奉扃。注曰。奉扃、敬也。孔疏曰。奉扃之說多家。今謂禮有鼎扃。所以關鼎。今關戶之木與關鼎相似。凡常奉扃之時。必兩手向心而奉之。今入戶雖不奉扃木。其手若奉扃然。以其手對戶若奉扃、言恭敬也。玉裁謂下文言戶開亦開。戶？亦？。知戶？而入、用兩手推戶爲奉扃。若戶開而入、則兩手不偏可矣。戶扃、葢以木横著於戶爲之機。令外可閉者。鼎關字正作鼏。禮古文叚扃爲之。車上所以止旗者亦曰扃。"}]},"門":{"expl":"聞也。从二戶。象形。凡門之屬皆从門。","rad":"門","fq":"莫奔切","vol":"12","py":"mén","duan":[{"e":"聞也。","n":"以㬪韵爲訓。聞者、謂外可聞於內。內可聞於外也。"}]},"閶":{"expl":"天門也。从門昌聲。楚人名門曰閶闔。","rad":"門","fq":"尺量切","vol":"12","py":"chānɡ","duan":[{"e":"閶𨵵、","n":"二字今補。離騷、大人賦、淮南子、西京賦、靈光殿賦、大象賦皆云閶？。王逸、高誘、薛綜、韋昭、李善注皆曰。閶？、天門也。八風、西方曰閶？風。"}]},"闈":{"expl":"宮中之門也。从門韋聲。","rad":"門","fq":"羽非切","vol":"12","py":"wéi","duan":[{"e":"宮中之門也。","n":"釋宮曰。宮中之門謂之闈。周禮保氏。使其屬守王闈。注。闈、宮中之巷門。"}]},"䦲":{"expl":"䦲謂之樀。樀，廟門也。从門詹聲。","rad":"門","fq":"余廉切","vol":"12","py":"yán","duan":[{"e":"䦲謂之樀。","n":"今釋宮檐也之樀。許所據爾雅有異。本作䦲。"}]},"閎":{"expl":"䢽門也。从門厷聲。","rad":"門","fq":"戶萌切","vol":"12","py":"hónɡ","duan":[{"e":"䢽門也。","n":"䢽者、里中道也。然則閎猶閭也。釋宮。衖門謂之閎。郭引左傳盟諸僖閎。云閎、衖頭門。"}]},"閨":{"expl":"特立之戶，上圜下方，有似圭。从門圭聲。","rad":"門","fq":"古攜切","vol":"12","py":"ɡuī","duan":[{"e":"特立之戶。","n":"釋宮曰。宮中門謂之闈。其小者謂之閨。"}]},"閤":{"expl":"門㫄戶也。从門合聲。","rad":"門","fq":"古沓切","vol":"12","py":"ɡé","duan":[{"e":"門旁戶也。","n":"釋宮曰。小閨謂之閤。按漢人所謂閤者、皆門旁戶也。皆於正門之㚈爲之。前書注曰。閨閤、內中小門也。公孫弘傳。起客館。開東閤以延賢人。師古云。閤者、小門也。東向開之。避當庭門而引賓客。以別於掾史官屬也。亦有云南閤者。如許沖云臣父故大尉南閤祭酒是也。有云西閤者。如晉書衞玠爲太傅西閤祭酒是也。唐時不臨前殿。御便殿。謂之入閤。謂立仗於前殿。喚仗、則自東西閤入也。凡上書於達官曰閤下、猶言執事也。今人乃譌爲閣下。"}]},"闒":{"expl":"樓上戶也。从門𦐇聲。","rad":"門","fq":"徒盍切","vol":"12","py":"tà","duan":[{"e":"樓上戶也。","n":"齊風傳曰。闥、門內也。許書無闥。闒卽今闥字。西京賦說神明臺曰。上飛闥而仰眺。西都賦說井榦樓曰。排飛闥而上出。此二闥皆樓上戶。在高處故名之曰飛。"}]},"三":{"expl":"天地人之道也。从三數。凡三之屬皆从三。","rad":"三","fq":"穌甘切","vol":"01","py":"sān","duan":[{"e":"數名。天地人之道也。","n":"陳煥曰。數者、易數也。三兼陰陽之數言。一下曰道立於一。二下曰地之數。王下曰三者、天地人也。老子曰。一生二。二生三。三生萬物。此釋三之義。下釋三之形。故以於文二字別言之。"}]},"物":{"expl":"萬物也。牛爲大物；天地之𢿙，起於牽牛，故从牛。勿聲。","rad":"牛","fq":"文弗切","vol":"02","py":"wù","duan":[{"e":"萬物也。牛爲大物。","n":"牛爲物之大者。故物从牛。與半同意。"}]},"閈":{"expl":"門也。从門干聲。汝南平輿里門曰閈。","rad":"門","fq":"侯旰切","vol":"12","py":"hàn","duan":[{"e":"閭也。","n":"左傳爾雅釋文、左傳正義、蕪城注、玉篇、廣韵引皆作閭。至爾雅疏乃譌爲門。今正。下文曰閭、里門也。漢書。綰自同閈。應注。楚名里門曰閈。招魂。去君之恒榦。王注。或作恒閈。閈、里也。楚人名里曰閈。按惟左傳高其閈閣用爲凡門之偁。"}]},"閭":{"expl":"里門也。从門呂聲。《周禮》：“五家爲比，五比爲閭。”閭，侶也，二十五家相羣侶也。","rad":"門","fq":"力居切","vol":"12","py":"lǘ","duan":[{"e":"里門也。","n":"周制、二十五家爲里。其後則人所聚居爲里。不限二十五家也。里部曰。里、凥也。里門曰閭。"}]},"閻":{"expl":"里中門也。从門臽聲。","rad":"門","fq":"余廉切","vol":"12","py":"yán","duan":[{"e":"里中門也。","n":"別於閭閈爲里外門也。"}]},"闠":{"expl":"市外門也。从門貴聲。","rad":"門","fq":"胡對切","vol":"12","py":"huì","duan":[{"e":"市外門也。","n":"薛綜西京賦注曰。闤、市營也。闠、中隔門也。劉逵蜀都賦注曰。闤、市巷也。闠、市行內門也。崔豹古今注曰。市牆曰闤。市門曰闤。李善引倉頡篇曰。闤、市門也。按諸家皆有闤字、而許不錄。葢以還環包之。巿之營域曰環。其外門曰闠。"}]},"闉":{"expl":"城内重門也。从門垔聲。《詩》曰：“出其闉闍。”","rad":"門","fq":"於眞切","vol":"12","py":"yīn","duan":[{"e":"闉闍、","n":"二字今依詩正義補。"}]},"闍":{"expl":"闉闍也。从門者聲。","rad":"門","fq":"當孤切","vol":"12","py":"dū","duan":[{"e":"闉闍也。从門。者聲。","n":"當孤切。五部。"}]},"闕":{"expl":"門觀也。从門欮聲。","rad":"門","fq":"去月切","vol":"12","py":"què","duan":[{"e":"門。觀也。","n":"釋宮曰。觀謂之闕。此觀上必加門者、觀有不在門上者也。凡觀與臺在於平地、則四方而高者曰臺。不必四方者曰觀。其在門上者、則中央闕然、左右爲觀曰兩觀。周禮之象魏、春秋經之兩觀、左傳僖五年之觀臺也。若中央不闕、則跨門爲臺。禮器謂之臺門、左傳謂之門臺是也。此云闕門觀也者、謂門有兩觀者偁闕。"}]},"閞":{"expl":"門欂櫨也。从門弁聲。","rad":"門","fq":"皮變切","vol":"12","py":"biàn","duan":[{"e":"門欂櫨也。","n":"欂櫨、柱上枅也。枅、屋欂櫨也。閞則門柱上枅之名。"}]},"䦏":{"expl":"門扇也。从門介聲。","rad":"門","fq":"胡介切","vol":"12","py":"xiè","duan":[{"e":"門扉也。从門。介聲。","n":"胡介切。十五部。"}]},"闔":{"expl":"門扇也。一曰閉也。从門盍聲。","rad":"門","fq":"胡臘切","vol":"12","py":"hé","duan":[{"e":"門扉也。","n":"月令。乃脩？扇。公羊傳。齒箸乎門？。釋宮。？謂之扉。"}]},"犧":{"expl":"宗廟之牲也。从牛羲聲。賈侍中說：此非古字。","rad":"牛","fq":"許羈切","vol":"02","py":"xī","duan":[{"e":"宗廟之牲也。","n":"魯頌。享以騂犧。毛傳。犧、純也。曲禮。天子以犧牛。鄭云。犧、純毛也。牧人。祭祀共其犧牲。鄭云。犧牲、毛羽完具也。僞孔注微子云。色純曰犧。體完曰牷。杜注左傳又云。牷、純色完全也。說犧皆與許異。"}]},"闑":{"expl":"門梱也。从門臬聲。","rad":"門","fq":"魚列切","vol":"12","py":"niè","duan":[{"e":"門梱也。","n":"木部曰。梱、門橜也。相合爲一義。釋宮。橜謂之闑。古者門有二闑。二闑之閒謂之中門。惟君行中門。臣由闑外。賈公彥聘禮疏所言是也。禮古文闑作槷。"}]},"閾":{"expl":"門榍也。从門或聲。《論語》曰：“行不履閾。”","rad":"門","fq":"于逼切","vol":"12","py":"yù","duan":[{"e":"門榍也。","n":"木部曰。？者、門限也。相合爲一義。釋宮曰。柣謂之閾。柣、郭干結反。卽？字也。禮古文閾作戚。此皆叚借字也。"}]},"閬":{"expl":"門高也。从門良聲。巴郡有閬中縣。","rad":"門","fq":"來宕切","vol":"12","py":"lànɡ","duan":[{"e":"門高也。","n":"文選甘泉賦注引作門高大之皃也。𨸏部曰。阬、閬也。此曰閬、門高皃。相合爲一義。凡許書異部合讀之例如此。大雅。迺立皋門。皋門有伉。傳曰。王之郭門曰皋門。伉、高皃。按詩伉當是阬之譌。甘泉賦。閌閬閬其寥郭兮。閌亦卽阬字。許書無閌。"}]},"闢":{"expl":"開也。从門辟聲。","rad":"門","fq":"房益切","vol":"12","py":"pì","duan":[{"e":"開也。","n":"引申爲凡開袥之偁。古多叚借辟字。"}]},"䦱":{"expl":"闢門也。从門爲聲。《國語》曰：“䦱門而與之言。”","rad":"門","fq":"韋委切","vol":"12","py":"wěi","duan":[{"e":"闢門也。","n":"魯語。䦱門與之言。皆不踰閾。韋注。䦱、闢也。"}]},"闡":{"expl":"開也。从門單聲。《易》曰：“闡幽。”","rad":"門","fq":"昌善切","vol":"12","py":"chǎn","duan":[{"e":"開也。从門。單聲。","n":"昌善切。十四部。"}]},"開":{"expl":"張也。从門从幵。","rad":"門","fq":"苦哀切","vol":"12","py":"kāi","duan":[{"e":"張也。","n":"張者、施弓弦也。門之開如弓之張。門之閉如弓之弛。"}]},"闓":{"expl":"開也。从門豈聲。","rad":"門","fq":"苦亥切","vol":"12","py":"kǎi","duan":[{"e":"開也。","n":"本義爲開門。引申爲凡启導之偁。心部曰。忻者、闓也。"}]},"閜":{"expl":"大開也。从門可聲。大杯亦爲閜。","rad":"門","fq":"火下切","vol":"12","py":"xiǎ","duan":[{"e":"大開也。","n":"引申爲凡大之偁。上林賦曰。谽呀豁閜。司馬彪云。谽呀、大皃。豁閜、空虛也。方言。閜、桮也。其大者謂之閜。"}]},"閘":{"expl":"開閉門也。从門甲聲。","rad":"門","fq":"烏甲切","vol":"12","py":"yā","duan":[{"e":"開閉門也。","n":"謂樞轉軋軋有聲。"}]},"犍":{"expl":"犗牛也。从牛建聲。亦郡名。","rad":"牛","fq":"居言切","vol":"02","py":"jiān","duan":[]},"閟":{"expl":"閉門也。从門必聲。《春秋傳》曰：“閟門而與之言。”","rad":"門","fq":"兵媚切","vol":"12","py":"bì","duan":[{"e":"閉門也。","n":"引申爲凡閉之偁。載馳、閟宮傳曰。閟、閉也。又叚爲祕字。閟宮箋曰。閟、神也。此謂閟卽祕之叚借也。示部曰。祕、神也。"}]},"閣":{"expl":"所以止扉也。从門各聲。","rad":"門","fq":"古洛切","vol":"12","py":"ɡé","duan":[{"e":"所㠯止扉者。","n":"釋宮曰。所以止扉謂之閣。郭注。門辟旁長橜也。引左傳高其閈閣。而又云閣長杙、卽門橜也。按郭云門辟旁長橜者、謂門開則邊旁有兩長橜。使其止而不過也。云卽門橜者、謂左傳之閣卽他經之闑。兩扉中之橜也。是二者皆所以止扉。皆謂之閣。但左傳主謂中門者耳。許闑訓門橜。閣訓所以止扉。則畫然二義。許本諸釋宮。今本釋宮譌爲閎。陸氏音義不辯是非。云本亦作閣。音各。郭注本無此字。不知郭氏於衖門謂之閎下引左盟諸僖閎。於所以止扉謂之閣下引左高其閈閣。郭作注時閣絶未誤爲閎。注亦絶無誤也。顔師古匡謬正俗分別閎閣二字不同。所引左傳作閈閣、所引爾雅及注皆作閣。今雅雨堂刻本譌亂不可讀。左傳。高其閈閣。閈猶門也。高其門則所以止扉亦必高。"}]},"閒":{"expl":"隟也。从門从月。","rad":"門","fq":"古閑切","vol":"12","py":"jiàn","duan":[{"e":"隙也。","n":"隙者、壁際也。引申之、凡有兩邊有中者皆謂之隙。隙謂之閒。閒者、門開則中爲際。凡罅縫皆曰閒。其爲有兩有中一也。攷工記說鐘銑與銑之閒曰銑閒。篆與篆、𡔷與𡔷、鉦與鉦之閒曰篆閒𡔷閒鉦閒。病與瘳之閒曰病閒。語之小止曰言之閒。閒者、稍暇也。故曰閒暇。今人分別其音爲戶閑切。或以閑代之。閒者、隙之可尋者也。故曰閒廁、曰閒迭、曰閒隔、曰閒諜。今人分別其音爲古莧切。釋詁、毛傳曰。閒、代也。釋言曰。閒、俔也。人部曰。俔、閒見也。厂部曰。㕊、石閒見也。今音皆去聲。凡自其單出言之曰閒。"}]},"𨵌":{"expl":"門傾也。从門阿聲。","rad":"門","fq":"烏可切","vol":"12","py":"ě","duan":[{"e":"門傾也。","n":"此與上閜篆各字各義。或合爲一。非也。上林賦說大木之。阬衡閜砢。索隱引郭樸云。阬衡閜砢者揭蘖傾敵皃也。按此閜字當作？。與谽呀豁閜義不同。？砢讀惡可來可二反。玉篇引賦正作？。"}]},"閼":{"expl":"遮𢹬也。从門於聲。","rad":"門","fq":"烏割切","vol":"12","py":"è","duan":[{"e":"遮𢹬也。","n":"遮者、遏也。𢹬者、袌也。古書壅遏字多作𢹬閼。如許所說則同義異字也。"}]},"𨷱":{"expl":"開閉門利也。从門繇聲。一曰縷十紘也。","rad":"門","fq":"旨沇切","vol":"12","py":"zhuǎn","duan":[{"e":"開閉門利也。","n":"今俗語云自由自便當作此字。"}]},"䦪":{"expl":"門聲也。从門曷聲。","rad":"門","fq":"乙鎋切","vol":"12","py":"yà","duan":[{"e":"門聲也。从門。曷聲。","n":"乙鎋切。十五部。按駱駝鳴聲𡇼字當作䦪。"}]},"䦳":{"expl":"門響也。从門郷聲。","rad":"門","fq":"許亮切","vol":"12","py":"xiànɡ","duan":[{"e":"門響也。","n":"響疑當作鄉。鄉者、今之向字。門鄉者、謂門所向。釋宮。兩階閒謂之鄉。集韵四十一漾引作謂之䦳。"}]},"闌":{"expl":"門遮也。从門柬聲。","rad":"門","fq":"洛干切","vol":"12","py":"lán","duan":[{"e":"門遮也。","n":"謂門之遮蔽也。俗謂㰍檻爲闌。引申爲酒闌字。於遮止之義演之也。"}]},"閑":{"expl":"闌也。从門中有木。","rad":"門","fq":"戶閒切","vol":"12","py":"xián","duan":[{"e":"闌也。","n":"引申爲防閑。古多借爲淸閒字。又借爲嫻習字。"}]},"犝":{"expl":"無角牛也。从牛童聲。古通用僮。","rad":"牛","fq":"徒紅切","vol":"02","py":"tónɡ","duan":[]},"閉":{"expl":"闔門也。从門；才，所以歫門也。","rad":"門","fq":"博計切","vol":"12","py":"bì","duan":[{"e":"𨵵門也。","n":"𨵵下曰。閉也。與此爲轉注。又閟下曰。閉門也。按左傳高其閈閣。疑閈乃閉字之誤。"}]},"閡":{"expl":"外閉也。从門亥聲。","rad":"門","fq":"五漑切","vol":"12","py":"ài","duan":[{"e":"外閉也。","n":"有外閉則爲礙。"}]},"闇":{"expl":"閉門也。从門音聲。","rad":"門","fq":"烏紺切","vol":"12","py":"àn","duan":[{"e":"閉門也。","n":"借以爲幽暗字。"}]},"關":{"expl":"以木橫持門戶也。从門𢇅聲。","rad":"門","fq":"古還切","vol":"12","py":"ɡuān","duan":[{"e":"以木横持門戶也。","n":"通俗文作𣟴。引申之、周禮注曰關、畍上之門。又引申之、凡曰關閉、曰機關、曰關白、曰關藏皆是。凡立乎此而交彼曰關。毛詩傳曰。關關、和聲也。又曰。閒關、設舝皃。皆於音得義者也。"}]},"𨷲":{"expl":"關下牡也。从門龠聲。","rad":"門","fq":"以灼切","vol":"12","py":"yuè","duan":[{"e":"關下牡也。","n":"關者、横物。卽今之門𣟴。關下牡者、謂以直木上貫關。下插地。是與關有牝牡之別。漢書所謂牡飛牡亡者、謂此也。月令曰。脩鍵閉。愼管籥。注曰。鍵、牡。閉、牝也。管籥、搏鍵器也。然則關下牡謂之鍵。亦謂之籥。籥、卽𨷲之叚借字。析言之、則鍵與𨷲有二。渾言之、則一物也。金縢啓籥見書、亦謂關閉兆書者。古無鎖鑰字。葢古袛用木爲。不用金鐵。故說文鍵下袛云鉉、不云門牡。"}]},"闐":{"expl":"盛皃。从門眞聲。","rad":"門","fq":"待秊切","vol":"12","py":"tián","duan":[{"e":"盛皃也。","n":"謂盛滿於門中之皃也。詩曰。振旅闐闐。孟子作塡。玉藻。盛氣顚實。叚顚爲闐也。"}]},"闛":{"expl":"闛闛，盛皃。从門堂聲。","rad":"門","fq":"徒郎切","vol":"12","py":"tánɡ","duan":[{"e":"闛闛、盛皃也。","n":"謂盛滿於門中之皃也。楊雄賦。西馳闛？。此叚闛爲閶也。大司馬注。𡔷聲不過閶。此叚閶爲闛。闛卽𡔷部之鼞也。鼙聲不過闒。闒卽𡔷部之䶀也。"}]},"閹":{"expl":"豎也。宮中奄閽閉門者。从門奄聲。","rad":"門","fq":"英廉切","vol":"12","py":"yān","duan":[{"e":"門豎也。","n":"門字今依御覽補。豎猶孺也。周禮注曰。豎、未冠者之官名。凡文王世子之內豎、左傳之使牛爲豎皆是。司門則曰門豎。故从門。"}]},"閽":{"expl":"常以昏閉門隸也。从門从昏，昏亦聲。","rad":"門","fq":"呼昆切","vol":"12","py":"hūn","duan":[{"e":"常㠯昏𨳲門隸也。","n":"周禮注曰。隸、給勞辱之役者。周禮閽人。王宮每門四人。囿游亦如之。注云。閽人、司昏䢅以啓？者。㓝人墨者使守門。按古閽與勲音同。易。厲閽心。馬作熏。荀以熏爲勳、而易爲動。漢光祿勲卿一人。胡廣曰。勲猶閽也。主殿宫門戶之職。"}]},"闚":{"expl":"閃也。从門規聲。","rad":"門","fq":"去隓切","vol":"12","py":"kuī","duan":[{"e":"閃也。","n":"此與窺義別。窺、小視也。"}]},"犛":{"expl":"西南夷長髦牛也。从牛𠩺聲。凡犛之屬皆从犛。","rad":"犛","fq":"莫交切（當作里之切）","vol":"02","py":"lí","duan":[{"e":"西南夷長髦牛也。","n":"今四川雅州府淸谿縣大相嶺之外有地名旄牛。產旄牛。而淸谿縣南抵寧遠府、西抵打箭鑪。古西南夷之地。皆產旄牛。如郭樸注山海經所云。背、厀及胡、尾皆有長毛者。小角。其體純黑。土俗用爲菜。其尾腊之可爲拂子。云長髦者、謂背䣛胡尾皆有長毛。下文氂字乃專謂尾也。此牛名犛牛。音如貍。楚語。巴浦之犀犛。上林賦。㺎旄貘犛。以其長髦也。故史記西南夷傳謂之髦牛。以其尾名氂也。故周禮樂師注謂之氂牛。以氂可飾旄也。故禮注、爾雅注、北山經、上林賦注、漢書西南夷傳皆謂之旄牛。氂髦旄三字音同。因之讀犛如毛。非也。據上林賦則旄犛異物。中山經。荆山多犛牛。郭曰。旄牛屬。"}]},"𨷻":{"expl":"妄入宮掖也。从門䜌聲。讀若闌。","rad":"門","fq":"洛干切","vol":"12","py":"lán","duan":[{"e":"妄入宮亦也。","n":"亦舊作掖。師古注漢曰。掖門在兩旁。如人臂掖。依許字例、當作亦也。漢書以闌爲？字之叚借。成帝紀。闌入尙方掖門。應劭曰。無符籍妄入宮曰闌。又或作蘭。列子。宋有蘭子。張湛注曰。凡物不知生之主曰蘭。殷敬順曰。史記無符傳出入謂之闌。此蘭子、謂以技妄遊。"}]},"𨳌":{"expl":"登也。从門、𠄟。𠄟，古文下字。讀若軍敶之敶。","rad":"門","fq":"直刃切","vol":"12","py":"zhèn","duan":[{"e":"登也。","n":"登、上車也。凡有所上皆曰登。"}]},"閃":{"expl":"闚頭門中也。从人在門中。","rad":"門","fq":"失冉切","vol":"12","py":"shǎn","duan":[{"e":"闚頭門中也。","n":"禮運。魚鮪不淰。注云。淰之言閃也。"}]},"閱":{"expl":"具數於門中也。从門，說省聲。","rad":"門","fq":"弋雪切","vol":"12","py":"yuè","duan":[{"e":"具數於門中也。","n":"具者、供置也。數者、計也。計者、會也。筭也。云於門中者、以其字从門也。周禮大閱。注曰。𥳑軍實也。左氏春秋大閱。傳曰。簡車馬也。引申爲閱歴。又引申爲明其等曰閥、積其功曰閱。手部揲下曰。閱持也。易。揲之以四。謂者四更迭數之也。古叚閱爲穴。詩。蜉蝣堀閱。傳曰。堀閱、容閱也。閱卽穴。宋玉賦。空穴來風。莊子作空閱來風。司馬彪云。門戶孔空。風善從之。道德經。塞其兌。閉其門。兌卽閱之省。詩。我躳不閱。傳云。閱、容也。言我躳不能見容。如無空穴以自處也。"}]},"闋":{"expl":"事巳，閉門也。从門癸聲。","rad":"門","fq":"倾雪切","vol":"12","py":"què","duan":[{"e":"事已𨳲門也。","n":"引申爲凡事已之偁。詩。俾民心闋。傳曰。闋、息也。禮記。有司告以樂闋。"}]},"闞":{"expl":"望也。从門敢聲。","rad":"門","fq":"苦濫切","vol":"12","py":"kàn","duan":[{"e":"望也。","n":"望者、出亡在外、望其還也。望有倚門、倚閭者。故从門。大雅。闞如虓虎。謂其怒視。"}]},"闊":{"expl":"䟽也。从門𣴠聲。","rad":"門","fq":"苦括切","vol":"12","py":"kuò","duan":[{"e":"疏也。","n":"云部曰。疏、通也。闊之本義如是。不若今義訓爲廣也。"}]},"閔":{"expl":"弔者在門也。从門文聲。","rad":"門","fq":"眉殞切","vol":"12","py":"mǐn","duan":[{"e":"弔者在門也。","n":"引申爲凡痛惜之辭。俗作憫。邶風。覯閔旣多。豳風。鬻子之閔斯。傳曰。閔、病也。"}]},"闖":{"expl":"馬出門皃。从馬在門中。讀若郴。","rad":"門","fq":"丑禁切","vol":"12","py":"chèn","duan":[{"e":"馬出門皃。","n":"引申爲突兀驚人之辭。公羊傳曰。開之則闖然公子陽生也。何云。闖、出頭皃。韓退之詩曰。喁喁魚闖萍。"}]},"闤":{"expl":"市垣也。从門瞏聲。","rad":"門","fq":"戶關切","vol":"12","py":"huán","duan":[]},"氂":{"expl":"犛牛尾也。从犛省，从毛。","rad":"犛","fq":"里之切（當作莫交切）","vol":"02","py":"máo","duan":[{"e":"犛牛尾也。","n":"凡經云干旄、建旄、設旄、右秉白旄、羽旄、齒革干戚羽旄、今字或有誤作毛者。古注皆云旄牛尾也。旄牛卽犛牛。犛牛之尾名氂。以㲠爲幢曰旄。因之呼氂爲旄。凡云注旄干首者是也。呼犛牛爲旄牛。凡云旄牛尾者是也。"}]},"闥":{"expl":"門也。从門達聲。","rad":"門","fq":"他達切","vol":"12","py":"tà","duan":[]},"閌":{"expl":"閌閬，高門也。从門亢聲。","rad":"門","fq":"苦浪切","vol":"12","py":"kānɡ","duan":[]},"閥":{"expl":"閥閱，自序也。从門伐聲。義當通用伐。","rad":"門","fq":"房越切","vol":"12","py":"fá","duan":[]},"闃":{"expl":"靜也。从門狊聲。","rad":"門","fq":"苦狊切","vol":"12","py":"qù","duan":[]},"耳":{"expl":"主聽也。象形。凡耳之屬皆从耳。","rad":"耳","fq":"而止切","vol":"12","py":"ěr","duan":[{"e":"主聽者也。","n":"者字今補。凡語云而已者、急言之曰耳。在古音一部。凡云如此者、急言之曰爾。在古音十五部。如世說云聊復爾耳。謂且如此而已是也。二字音義。絶不容相混。而唐人至今譌亂至不可言。於古經傳亦任意塡寫。致多難讀。卽如論語一經。言云爾者、謂如此也。言謹爾、率爾、鏗爾者、爾猶然也。言無隱乎爾、一日長乎爾、爾猶汝也。言汝得人焉爾乎、言得人於此否也。公羊傳三年問焉爾、皆訓於此也。全經惟有前言戲之耳、乃而已之訓。今俗刻作汝得人焉耳乎。乃極爲可笑。曹操曰。俗語云生女耳。耳是不足之詞。此古說之存者也。音轉讀爲仍。如耳孫亦曰仍孫是也。"}]},"𦔮":{"expl":"耳垂也。从耳下垂。象形。《春秋傳》曰“秦公子輒”者，其耳下垂，故以爲名。","rad":"耳","fq":"陟葉切","vol":"12","py":"zhé","duan":[{"e":"耳𠂹也。","n":"𠂹各本作垂。今正。"}]},"𦕒":{"expl":"小垂耳也。从耳占聲。","rad":"耳","fq":"丁兼切","vol":"12","py":"diān","duan":[{"e":"小𠂹耳也。从耳。占聲。","n":"丁兼切。七部。"}]},"耽":{"expl":"耳大垂也。从耳冘聲。《詩》曰：“士之耽兮。”","rad":"耳","fq":"丁含切","vol":"12","py":"dān","duan":[{"e":"耳大𠂹也。","n":"淮南墜形訓。夸父耽耳在其北。高注。耽耳、耳垂在肩上。耽讀衣褶之褶。或作攝。以兩手攝其肩之耳也。按許書本無聸字。耽卽聸也。今本於耽篆之外沾一聸篆。誤矣。"}]},"耼":{"expl":"耳曼也。从耳冉聲。","rad":"耳","fq":"他甘切","vol":"12","py":"dān","duan":[{"e":"耳曼也。","n":"曼者、引也。耳曼者、耳如引之而大也。如曼膚、曼䎼之曼。史記老子列傳曰。姓李氏、名耳、字耼。史記索隱、老子音義、後漢書桓帝紀注、文選遊天台山賦注所引皆如此。今本史記作名耳、字伯陽、謚曰耼。淺人妄改者也。字伯陽、見唐固國語注。"}]},"聸":{"expl":"垂耳也。从耳詹聲。南方聸耳之國。","rad":"耳","fq":"都甘切","vol":"12","py":"dān","duan":[{"e":"𠂹耳也。从耳。詹聲。","n":"都甘切。八部。"}]},"斄":{"expl":"彊曲毛，可以箸起衣。从犛省，來聲。","rad":"犛","fq":"洛哀切","vol":"02","py":"lái","duan":[{"e":"彊曲毛也。","n":"也依廣韵補。"}]},"耿":{"expl":"耳箸頰也。从耳，烓省聲。杜林說：耿，光也。从光，聖省。凡字皆左形右聲。杜林非也。","rad":"耳","fq":"古杏切","vol":"12","py":"ɡěnɡ","duan":[{"e":"耳箸頰也。","n":"頰者、面旁也。耳箸於頰曰耿。耿之言黏也。黏於頰也。邶風。耿耿不寐。傳曰。耿耿猶儆儆也。憂之聯綴於心。取義於此。凡云耿者、謂專壹也。杜林說皮傳耿光。而非字義。"}]},"聯":{"expl":"連也。从耳，耳連於頰也；从絲，絲連不絕也。","rad":"耳","fq":"力延切","vol":"12","py":"lián","duan":[{"e":"連也。","n":"連者、負車也。負車者、以人輓車。人與車相屬。因以爲凡相連屬之偁。周人用䏈字。漢人用連字。古今字也。周禮。官䏈以會官治。鄭注。䏈讀爲連。古書連作䏈。此以今字釋古字之例。"}]},"聊":{"expl":"耳鳴也。从耳卯聲。","rad":"耳","fq":"洛蕭切","vol":"12","py":"liáo","duan":[{"e":"耳鳴也。","n":"楚辭曰。耳𦕼啾而戃慌。王注云。𦕼啾、耳鳴也。此𦕼之本義。故字从耳。若詩泉水傳云。𦕼、願也。箋云。𦕼、且略之辭也。方言曰。俚、𦕼也。戰國策。民無所𦕼。此等義相近。皆叚𦕼爲憀也。憀者、憀賴也。又詩傳。椒𦕼、椒也。不言𦕼爲語詞。葢單𧦝曰椒。絫𧦝曰椒𦕼。楚詞亦云。懷椒𦕼之蔎蔎。爾雅曰。朻者𦕼。朻卽莍。椒榝實成莍彚。"}]},"聖":{"expl":"通也。从耳呈聲。","rad":"耳","fq":"式正切","vol":"12","py":"shènɡ","duan":[{"e":"通也。","n":"邶風。母氏聖善。傳云。聖、叡也。小雅。或聖或不。傳云。人有通聖者。有不能者。周禮。六德敎萬民。智仁聖義忠和。注云。聖通而先識。洪範曰。睿作聖。凡一事精通、亦得謂之聖。"}]},"聰":{"expl":"察也。从耳怱聲。","rad":"耳","fq":"倉紅切","vol":"12","py":"cōnɡ","duan":[{"e":"察也。","n":"察者、覈也。聰察以雙聲爲訓。"}]},"聽":{"expl":"聆也。从耳、㥁，壬聲。","rad":"耳","fq":"他定切","vol":"12","py":"tīnɡ","duan":[{"e":"聆也。","n":"凡目所及者云視。如視朝、視事是也。凡目不能徧而耳所及者云聽。如聽天下、聽事是也。"}]},"聆":{"expl":"聽也。从耳令聲。","rad":"耳","fq":"郎丁切","vol":"12","py":"línɡ","duan":[{"e":"聽也。","n":"二篆轉注。匡謬正俗載俗語云。聆瓦。聆者、聽之知微者也。文王世子曰。夢帝與我九聆。此叚聆爲鈴。夢天以九个鈴與己也。"}]},"職":{"expl":"記微也。从耳戠聲。","rad":"耳","fq":"之弋切","vol":"12","py":"zhí","duan":[{"e":"記𢼸也。","n":"𢼸舊作微。今正。記猶識也。纖微必識是曰職。周禮太宰之職、大司徒之職皆謂其所司。凡言司者、謂其善伺也。凡言職者、謂其善聽也。釋詁曰。職、主也。毛傳同。見詩悉蟀、十月之交。周禮職方、亦作識方。"}]},"聒":{"expl":"驩語也。从耳𠯑聲。","rad":"耳","fq":"古活切","vol":"12","py":"ɡuō","duan":[{"e":"讙語也。","n":"讙者、譁也。"}]},"聥":{"expl":"張耳有所聞也。从耳禹聲。","rad":"耳","fq":"王矩切","vol":"12","py":"jǔ","duan":[{"e":"張耳有所聞也。","n":"廣雅。驚也。"}]},"告":{"expl":"牛觸人，角箸橫木，所以告人也。从口从牛。《易》曰：“僮牛之告。”凡告之屬皆从告。","rad":"告","fq":"古奧切","vol":"02","py":"ɡào","duan":[{"e":"牛觸人。角箸橫木。所㠯吿人也。从口。从牛。","n":"如許說則告卽楅衡也。於牛之角寓人之口爲會意。然牛與人口非一體。牛口爲文。未見告義。且字形中無木。則告意未㬎。且如所云是未嘗用口。是告可不用口也。何以爲一切告字見義哉。愚謂此許因童牛之告而曲爲之說。非字意。故木部楅下不與此爲轉注。此字當入口部。从口、牛聲。牛可入聲讀玉也。廣韵。吿上曰告。發下曰誥。古沃切。三部。音轉古到切。○又汪氏龍曰。此因嚳字。故立吿部。愚謂誠然。嚳从斆省。斆亦教也。教之故急急吿之。吿亦聲。然則當立斆部。嚳屬焉。不當有告部。"}]},"聲":{"expl":"音也。从耳殸聲。殸，籒文磬。","rad":"耳","fq":"書盈切","vol":"12","py":"shēnɡ","duan":[{"e":"音也。","n":"音下曰。聲也。二篆爲轉注。此渾言之也。析言之、則曰生於心有節於外謂之音。宮商角徵羽、聲也。絲竹金石匏土革木、音也。樂記曰。知聲而不知音者、禽獸是也。"}]},"聞":{"expl":"知聞也。从耳門聲。","rad":"耳","fq":"無分切","vol":"12","py":"wén","duan":[{"e":"知聲也。","n":"往曰聽。來曰聞。大學曰。心不在焉。聽而不聞。引申之爲令聞廣譽。"}]},"聘":{"expl":"訪也。从耳甹聲。","rad":"耳","fq":"匹正切","vol":"12","py":"pìn","duan":[{"e":"訪也。","n":"汎謀曰訪。按女部曰娉、問也。二字義略同。"}]},"聾":{"expl":"無聞也。从耳龍聲。","rad":"耳","fq":"虚紅切","vol":"12","py":"lónɡ","duan":[{"e":"無聞也。从耳。龍聲。","n":"盧紅切。九部。"}]},"𢕈":{"expl":"生而聾曰聳。从耳，從省聲。","rad":"耳","fq":"息拱切","vol":"12","py":"sǒnɡ","duan":[{"e":"生而聾曰𢕈。","n":"方言。聳、聾也。生而聾、陳楚江淮之閒謂之聳。荆揚之閒及山之東西雙聾者謂之聳。又古多叚聳爲𢥠。方言曰。聳、悚也。又曰。聳、欲也。荆吳之閒曰聳。自關而西秦晉之閒相勸曰聳。中心不欲而由旁人之勸語亦謂之聳。"}]},"䏁":{"expl":"益梁之州謂聾爲䏁，秦晉聽而不聞，聞而不達謂之䏁。从耳宰聲。","rad":"耳","fq":"作亥切","vol":"12","py":"zǎi","duan":[{"e":"益梁之州謂聾爲䏁。秦晉聽而不聰、聞而不𨔶謂之䏁。","n":"方言曰。䏁、聾也。梁益之閒謂之䏁。秦晉之閒聽而不聰、聞而不𨔶謂之䏁。"}]},"聵":{"expl":"聾也。从耳貴聲。","rad":"耳","fq":"五怪切","vol":"12","py":"kuì","duan":[{"e":"聾也。","n":"國語曰。聾聵不可使聽。韋云。耳不別五聲之和曰聾。生而聾曰聵。"}]},"聉":{"expl":"無知意也。从耳出聲。讀若孽。","rad":"耳","fq":"五滑切","vol":"12","py":"wà","duan":[{"e":"無知意也。","n":"此意內言外之意。無知者其意、聉者其䛐也。方言曰。聾之甚、秦晉之閒謂之𦘍。注曰。言聉無所聞知也。疑方言之正文本作謂之聉。今本譌。"}]},"𦘍":{"expl":"吳楚之外，凡無耳者謂之𦘍。言若斷耳爲盟。从耳闋聲。","rad":"耳","fq":"五滑切","vol":"12","py":"wà","duan":[{"e":"吳楚之外凡無耳者謂之𦘍。","n":"方言曰。吳楚之外郊、凡無有耳者謂之𦘍。其言𦘍者、若秦晉中土謂墮耳者䎳也。"}]},"聅":{"expl":"軍法以矢貫耳也。从耳从矢。《司馬法》曰：“小罪聅，中罪刖，大罪剄。”","rad":"耳","fq":"恥列切","vol":"12","py":"chè","duan":[{"e":"軍法㠯矢毌耳也。从耳矢。","n":"會意。恥列切。十五部。"}]},"嚳":{"expl":"急告之甚也。从告，學省聲。","rad":"告","fq":"苦沃切","vol":"02","py":"kù","duan":[{"e":"急告之甚也。","n":"急吿猶吿急也。告急之甚、謂急而又急也。釋玄應說嚳與酷音義皆同。按白虎通云。謂之帝嚳者何也。嚳者、極也。敎令竆極也。竆極、卽急吿引伸之義。"}]},"聝":{"expl":"軍戰斷耳也。《春秋傳》曰：“以爲俘聝。”从耳或聲。","rad":"耳","fq":"古獲切","vol":"12","py":"ɡuó","duan":[{"e":"軍戰𣃔耳也。","n":"大雅。攸馘安安。傳曰。馘、獲也。不服者殺而獻其左耳曰馘。魯頌。在泮獻馘。箋云。馘所格者之左耳。"}]},"䎳":{"expl":"𡐦耳也。从耳月聲。","rad":"耳","fq":"魚厥切","vol":"12","py":"wà","duan":[{"e":"𡐦耳也。","n":"見方言。"}]},"𦗕":{"expl":"乘輿金馬耳也。从耳麻聲。讀若渳水。一曰若《月令》靡草之靡。","rad":"耳","fq":"亡彼切","vol":"12","py":"mǐ","duan":[{"e":"乘輿金耳也。","n":"金耳俗本作金飾馬耳。舊本作金馬耳。玉篇同。今依廣韵五支、四紙作乘輿金耳訂正。乘輿者、天子之車也。金耳者、金飾車耳也。西京賦。戴翠帽。倚金較。薛注。金較、黃金以飾較也。崔豹古今注曰。車耳重較也。史記禮書彌龍。徐廣曰。乘輿車金薄繆龍爲輿倚較。繆者、交錯之形。車耳刻交錯之龍、飾以金。惟乘輿爲然。與文虎伏軾、龍首衡軛。畫爲三事。史記之彌卽許之𦗕。𦗕者本字。彌者同音叚借字。淺人不得其解。乃妄改而不可通矣。𦗕非人耳也。故其字殿焉。"}]},"耹":{"expl":"《國語》曰：“回禄信於耹遂。”闕。","rad":"耳","fq":"巨今切","vol":"12","py":"qín","duan":[{"e":"國語曰。回祿信於耹遂。闕。","n":"國語今見周語。闕者、謂其義其音其形皆闕也。韋注。耹遂、地名。宋庠音禽。後漢書楊賜傳引作黔遂。黔亦今聲也。而說苑引國語作亭遂。竹書帝癸三十年作聆隧災。是其字从令从今不可定。而許書此篆或後人所偶記註於此者。"}]},"聑":{"expl":"安也。从二耳。","rad":"耳","fq":"丁帖切","vol":"12","py":"tiē","duan":[{"e":"安也。","n":"長笛賦曰。瓠巴聑柱。"}]},"聶":{"expl":"附耳私小語也。从三耳。","rad":"耳","fq":"尼輒切","vol":"12","py":"niè","duan":[{"e":"駙耳私小語也。","n":"口部咠下曰。聶語也。按二篆皆會意。以口就耳則爲咠。咠者己二耳在旁、彼一耳居閒則爲聶。史記魏其武安傳曰。乃效女兒呫聶耳語。韋曰。呫聶、附耳小語聲。"}]},"聱":{"expl":"不聽也。从耳敖聲。","rad":"耳","fq":"五交切","vol":"12","py":"áo","duan":[]},"𦣞":{"expl":"𩔞也。象形。凡𦣞之屬皆从𦣞。","rad":"𦣞","fq":"與之切","vol":"12","py":"yí","duan":[{"e":"𩔞也。","n":"頁部曰。𩔞、頥也。二篆爲轉注。𦣝者、古文頥也。鄭易注曰。頥中。句口車輔之名也。震動於下。艮止於上。口車動而上。因輔嚼物以養人。故謂之頥。頥、養也。按鄭意謂口下爲車。口上爲輔。合口車輔三者爲頥。左氏云。輔車相依。車部云。輔、人頰車也。序卦傳曰。頥者、養也。古名頥字眞。晉枚頥字仲眞。李頥字景眞。枚頥或作梅𦣱。誤也。"}]},"巸":{"expl":"廣𦣞也。从𦣞巳聲。","rad":"𦣞","fq":"與之切","vol":"12","py":"yí","duan":[{"e":"廣頥也。","n":"巸各本作𦣝。今正。許書主篆文也。廣頥曰巸。引申爲凡廣之偁。周頌昊天有成命傳曰。緝、明也。熙、廣也。熙乃巸之叚借字也。熙从火。其義訓燥。不訓廣也。毛傳於文王曰。緝熙、光明也。與昊天有成命傳不同。而敬之傳曰。光、廣也。然則光卽廣。二傳義本同。不得如鄭箋云廣爲光字之誤。周內史說周易曰。光、逗遠而自他有耀者也。然則光卽廣可知。大戴禮。積厚者流光。卽流廣也。釋詁。緝、熙、光也。卽周語叔向所云緝、明。熙、廣也。毛公兼取之爲傳。學者宐觀其會通。凡詁訓有析之至細者。有通之甚寛者。非好學深思。心知其意。不能盡其理也。熙訓廣、而熙乃巸之叚借。然則古經熙字可作巸者多矣。○文王毛傳曰。緝熙、光明也。此係釋詁而必兼言明"}]},"手":{"expl":"拳也。象形。凡手之屬皆从手。","rad":"手","fq":"書九切","vol":"12","py":"shǒu","duan":[{"e":"拳也。","n":"今人舒之爲手。卷之爲拳。其實一也。故以手與拳二篆互訓。"}]},"口":{"expl":"人所以言食也。象形。凡口之屬皆从口。","rad":"口","fq":"苦后切","vol":"02","py":"kǒu","duan":[{"e":"人所㠯言食也。","n":"言語、飮食者口之㒳大耑。舌下亦曰。口所以言別味也。頤象傳曰。君子以愼言語。節飮食。"}]},"掌":{"expl":"手中也。从手尚聲。","rad":"手","fq":"諸兩切","vol":"12","py":"zhǎnɡ","duan":[{"e":"手中也。","n":"手有面有背。背在外則面在中。故曰手中。左傳云有文在手者、在掌也。釋名云。水泆出所爲澤曰掌。水渟處如手掌中也。詩。或王事鞅掌。傳曰。鞅掌、失容也。箋云。鞅猶何也。掌謂捧之也。玉裁按凡周禮官名掌某者、皆捧持之義。"}]},"拇":{"expl":"將指也。从手母聲。","rad":"手","fq":"莫厚切","vol":"12","py":"mǔ","duan":[{"e":"將指也。","n":"將指、謂手中指也。大射禮。右巨指鉤弦。注云。右巨指、右手大擘也。又設決朱極三。注云。三者、食指將指無名指。小指短、不用。左傳定十四年。？廬傷將指。取其一屨。注云。其足大指見斬。遂失屨。易咸。初六。咸其拇。馬、鄭、薛、虞皆云。拇、足大指也。合三經而言之。手以中指爲將指爲拇。足以大指爲將指爲拇。此手足不同偁也。許謂手中指。易拇、荀作母。"}]},"指":{"expl":"手指也。从手旨聲。","rad":"手","fq":"職雉切","vol":"12","py":"zhǐ","duan":[{"e":"手指也。","n":"手非指不爲用。大指曰巨指、曰巨擘。次曰食指、曰啑鹽指。中曰將指。次曰無名指。次曰小指。叚借爲恉心部曰。恉、意也。"}]},"拳":{"expl":"手也。从手聲。","rad":"手","fq":"巨員切","vol":"12","py":"quán","duan":[{"e":"手也。","n":"合掌指而爲手。故掌指二篆廁手拳二篆之閒。卷之爲拳。故檀弓曰。執女手之拳然。"}]},"𢯲":{"expl":"手𢯲也。楊雄曰：“𢯲，握也。”从手𥄗聲。","rad":"手","fq":"烏貫切","vol":"12","py":"wàn","duan":[{"e":"手𢯲也。","n":"各本作手掔。今正。𢯲者、手上臂下也。肉部曰。臂者、手上也。肘者、臂節也。又部曰。厷者、臂上也。是則肘以下手以上、渾言之曰臂。析言之、則近手處曰𢯲。士喪禮。設決麗于𢯲。注云。𢯲、手後節中也。云後節中者、肘以上爲前節。則肘以下爲後節。後節之中以上爲臂、則以下爲𢯲也。俗作捥。左傳。涉佗捘衞矦之手及捥。非古字也。"}]},"攕":{"expl":"好手皃。《詩》曰：“攕攕女手。”从手韱聲。","rad":"手","fq":"所咸切","vol":"12","py":"xiān","duan":[{"e":"好手皃。","n":"魏風葛屨曰。摻摻女手。可以縫裳。傳曰。摻摻猶纖纖也。漢人言手之好曰纖纖。如古詩云。纖纖擢素手。傳以今喻古故曰猶。其字本作攕。俗改爲摻。非是。遵大路傳曰。摻、擥也。是摻字自有本義。孔氏正義引說文。摻、參此音反聲、訓爲斂。操、喿七遙反聲、訓爲奉也。是唐初說文確有摻字之證。自淺人摻操不分而奪摻篆。亦猶？鼏不分而奪？篆、袀袗不分而奪袀篆也。知摻之有本義、則知用爲攕字之非矣。"}]},"揱":{"expl":"人臂皃。从手削聲。《周禮》曰：“輻欲其揱。”","rad":"手","fq":"所角切","vol":"12","py":"shuò","duan":[{"e":"人臂皃。","n":"考工記輪人曰。望其輻。欲其揱爾而纖也。注云。揱、纖殺小皃也。鄭司農讀爲紛容揱參之揱。謂如桑螵蛸之蛸。按紛容揱參、出上林賦。"}]},"摳":{"expl":"繑也。一曰摳衣升堂。从手區聲。","rad":"手","fq":"口矦切","vol":"12","py":"kōu","duan":[{"e":"繑也。","n":"按糸部曰。繑、絝紐也。與摳義絕遠。疑是矯字之譌。矢部曰。矯、柔箭箝也。摳之義爲矯枉。"}]},"攐":{"expl":"摳衣也。从手褰聲。","rad":"手","fq":"去虔切","vol":"12","py":"qiān","duan":[{"e":"摳衣也。","n":"高注淮南曰。攐、縮也。按詩言褰裳、當作此篆。褰訓絝、非其義也。亦有作騫者。謂𧇾其下體之衣。較作褰爲長。"}]},"撎":{"expl":"舉手下手也。从手壹聲。","rad":"手","fq":"於計切","vol":"12","py":"yì","duan":[{"e":"𢷎舉首下手也。","n":"六字各本作舉手下手也五字。今正。西征賦注、玉篇引說文有拜字。左傳成十六年釋文引字林舉首下手。皆是也。凡不跪不爲拜。跪而舉其首惟下其手是曰肅拜。漢人曰撎。周禮九拜。九曰肅拜。先鄭注云。肅拜、但俯下手。今時撎是也。鄭注少儀曰。肅拜、拜不低頭也。云但俯下手、云不低頭、正與舉首下手合。今本說文旣譌。而少儀注又刪不字、作拜低頭。乃終古昧其禮矣。程氏瑤田曰。言舉首者、以別於䭫首頓首空首三拜皆必下其首也。按此婦人之拜也。婦人以肅拜當男子之空首。少儀云婦人吉事、雖有君賜肅拜是也。以手拜當男子之稽首。少儀之手拜、士昏禮之拜扱地是也。以稽顙當男子之頓首。喪服小記之爲夫與長子稽顙是也。肅拜與成十六年之肅不同。肅不連"}]},"王":{"expl":"天下所歸往也。董仲舒曰：“古之造文者，三畫而連其中謂之王。三者，天、地、人也，而參通之者王也。”孔子曰：“一貫三爲王。”凡王之屬皆从王。[李陽冰曰：“中畫近上。王者，則天之義。”]","rad":"王","fq":"雨方切","vol":"01","py":"wánɡ","duan":[{"e":"天下所歸往也。","n":"見白虎通。王往曡韵。"}]},"噭":{"expl":"吼也。从口敫聲。一曰噭，呼也。","rad":"口","fq":"古弔切","vol":"02","py":"jiào","duan":[{"e":"口也。","n":"口俗本譌吼。今正。史、漢貨殖傳皆云。馬蹄噭千。徐廣曰。噭、馬八髎也。小顏云。噭、口也。蹄與口共千則爲馬二百也。按以口釋噭。此必本說文。說文以口建首。下噭噣喙吻字皆與口字轉注相接。此全書之例也。通俗文、埤倉皆曰。尻骨謂之八髎。惟史記噭字從口。故徐以八髎釋之。尻亦得謂之口也。各本史記作躈。乃誤字耳。噭與竅音義相同。俗本說文作吼者、葢或識孔字於口字之旁。因誤倂爲一字。"}]},"揖":{"expl":"攘也。从手咠聲。一曰手箸胷曰揖。","rad":"手","fq":"伊入切","vol":"12","py":"yī","duan":[{"e":"攘也。","n":"攘汲古閣改作讓。誤。此與下文攘推也相聯爲文。鄭禮注云。推手曰揖。凡拱其手使前曰揖。凡推手小下之爲土揖。推手小舉之爲天揖。推手平之爲時揖也。成十六年。敢肅使者。則若今人之長揖。"}]},"攘":{"expl":"推也。从手襄聲。","rad":"手","fq":"汝羊切","vol":"12","py":"rànɡ","duan":[{"e":"推也。","n":"推手使前也。古推讓字如此作。上曲禮注曰。攘古讓字。許云。讓者、相責讓也。攘者、推也。从古也。漢書禮樂志。盛揖攘之容。藝文志。堯之克攘。司馬遷傳。小子何敢攘。皆用古字。凡退讓用此字。引申之使人退讓亦用此字。如攘寇、攘夷狄是也。"}]},"拱":{"expl":"斂手也。从手共聲。","rad":"手","fq":"居竦切","vol":"12","py":"ɡǒnɡ","duan":[{"e":"斂手也。","n":"斂當作撿。與下篆相聯爲文。尙書大傳曰。拱則抱鼓。皇侃論語疏曰。拱、沓手也。九拜皆必拱手而至地。立時敬則拱手。如檀弓孔子與門人立拱、論語子路拱而立、玉藻臣侍於君垂拱是也。行而張拱曰翔。凡拱不必皆如抱鼓也。推手曰揖、則如抱鼓。拜手、則斂於抱鼓。稽首頓首、則以其斂於抱鼓者下之。引手曰厭、則又較斂於拜手。凡沓手、右手在內。左手在外。是謂尙左手。男拜如是。男之吉拜如是。喪拜反是。左手在內。右手在外。是謂尙右手。女拜如是。女之吉拜如是。喪拜反是。喪服記。袪尺二寸。注曰。袪、袖口也。尺二寸足以容中人之倂兩手也。吉時拱尙左手。喪時拱尙右手。合內則、奔喪、檀弓尙左尙右之文繹之。可以知拱時沓手之宐矣。拱古文叚借作"}]},"撿":{"expl":"拱也。从手僉聲。","rad":"手","fq":"良冉切","vol":"12","py":"liǎn","duan":[{"e":"拱也。","n":"凡斂手宐作此字。"}]},"𢳎":{"expl":"首至地也。从手、𠦪。𠦪音忽。","rad":"手","fq":"博怪切","vol":"12","py":"bài","duan":[]},"捾":{"expl":"搯捾也。从手官聲。一曰援也。","rad":"手","fq":"烏括切","vol":"12","py":"wò","duan":[{"e":"搯捾也。","n":"捾乃複舉字。誤移搯下耳。義理與抉略同。今人剜字當作此。大徐附剜於刀部。非也。"}]},"搯":{"expl":"捾也。从手舀聲。《周書》曰：“師乃搯。”搯者，拔兵刃以習擊刺。《詩》曰：“左旋右搯。”","rad":"手","fq":"土刀切","vol":"12","py":"tāo","duan":[{"e":"捾也。","n":"魯語。公父文伯母戒文伯之妾曰。無洵涕。無搯膺。韋注。搯、叩也。膺、胷也。按韋注卽俗所謂椎心。喪禮有擗拊心也。則叩胷亦未爲失。此正謂哀之甚。如欲挑出心肝者然。韋衹言其大致而已。今人俗語亦云搯出。文選長笛賦。搯膺擗摽。李善引國語及韋注而云苦洽反。殊誤。苦洽切當是掐字。从臽聲。爪刺也。下引魏書程昱傳。昱於魏武前忿爭。聲氣忿高。邊人掐之乃止。是則从臽之掐。於搯膺豪不相涉也。韓子文搯擢胃腎、亦是用搯膺字。通俗文。捾出曰掏。爪按曰掐。掏卽搯也。許不錄掐。"}]},"㧬":{"expl":"𢹬也。从手𢀜聲。","rad":"手","fq":"居竦切","vol":"12","py":"ɡǒnɡ","duan":[]},"推":{"expl":"排也。从手隹聲。","rad":"手","fq":"他回切","vol":"12","py":"tuī","duan":[{"e":"排也。","n":"今六脂、十五灰殊其音義。古無二音二義也。"}]},"捘":{"expl":"推也。从手夋聲。《春秋傳》曰：“捘衞侯之手。”","rad":"手","fq":"子寸切","vol":"12","py":"zùn","duan":[{"e":"推也。","n":"謂排擠也。"}]},"噣":{"expl":"喙也。从口蜀聲。","rad":"口","fq":"陟救切","vol":"02","py":"zhòu","duan":[{"e":"喙也。","n":"曹風。不濡其咮。毛曰。咮、喙也。玉篇引不濡其噣。咮噣二同。朱聲蜀聲同部也。亦假借作注。爾雅咮星。史記、考工記注作注是也。亦作啄。詩韓奕傳。厄、烏噣也。厄同軛。烏噣、釋名小爾雅作烏啄。"}]},"排":{"expl":"擠也。从手非聲。","rad":"手","fq":"步皆切","vol":"12","py":"pái","duan":[{"e":"擠也。","n":"今義列也。"}]},"擠":{"expl":"排也。从手齊聲。","rad":"手","fq":"子計切","vol":"12","py":"jǐ","duan":[{"e":"排也。","n":"左傳。知擠于溝壑矣。杜云。隊也。隊今之墜字。謂排而墜之也。商書微子作隮。引左傳亦作隮。隮者、躋之俗。"}]},"抵":{"expl":"擠也。从手氐聲。","rad":"手","fq":"丁礼切","vol":"12","py":"dǐ","duan":[{"e":"擠也。","n":"排而相歫也。"}]},"摧":{"expl":"擠也。从手崔聲。一曰挏也，一曰折也。","rad":"手","fq":"昨回切","vol":"12","py":"cuī","duan":[{"e":"擠也。","n":"釋詁、毛傳皆曰。摧、至也。卽抵之義也。自推至摧六篆同義。"}]},"拉":{"expl":"摧也。从手立聲。","rad":"手","fq":"盧合切","vol":"12","py":"lā","duan":[{"e":"摧也。","n":"公羊傳。拹榦而殺之。何曰。拹、折聲也。按拹亦作拉。此上文摧一曰折也之義。"}]},"挫":{"expl":"摧也。从手𡋲聲。","rad":"手","fq":"則臥切","vol":"12","py":"cuò","duan":[{"e":"摧也。","n":"此亦上文摧一曰折也之義。考工記。揉牙內不挫。注云。挫、折也。詩。乘馬在廏。摧之秣之。傳曰。摧、挫也。箋云。挫今莝字也。傳、箋今本譌舛。今正之如是。"}]},"扶":{"expl":"左也。从手夫聲。","rad":"手","fq":"防無切","vol":"12","py":"fú","duan":[{"e":"左也。","n":"左俗本改作佐。非。左下曰。手相助也。"}]},"𢪇":{"expl":"扶也。从手爿聲。","rad":"手","fq":"七良切","vol":"12","py":"jiānɡ","duan":[{"e":"扶也。","n":"古詩。好事相扶將。當作扶？。字之叚借也。凡云將順其美、當作？順。詩。百兩將之。傳曰。將、送也。天不我將。箋云。將猶養也。皆於？義爲近。玉篇曰。？今作將。摪同。"}]},"持":{"expl":"握也。从手寺聲。","rad":"手","fq":"直之切","vol":"12","py":"chí","duan":[{"e":"握也。从手。寺聲。","n":"直之切。一部。"}]},"挈":{"expl":"縣持也。从手㓞聲。","rad":"手","fq":"苦結切","vol":"12","py":"qiè","duan":[{"e":"縣持也。","n":"縣者、系也。胡㳙切。下文云。提、挈也。則提與挈皆謂縣而持之也。今俗語云挈帶。古叚借爲契栔字。如爰挈我龜。傳云。挈、開也。又如？字下云。樂浪挈令。"}]},"喙":{"expl":"口也。从口彖聲。","rad":"口","fq":"許穢切","vol":"02","py":"huì","duan":[{"e":"口也。","n":"說卦傳。爲黔喙。左傳。㴱目而豭喙。叚借爲困極之義。廣韵引昆夷𤸁矣。今詩作喙矣。郭注方言引外傳余病𣨶矣。今外傳作余病喙。郭云。江東呼極爲𣨶。亦作𤸁。"}]},"拑":{"expl":"脅持也。从手甘聲。","rad":"手","fq":"巨淹切","vol":"12","py":"qián","duan":[{"e":"脅持也。","n":"謂脅制而持之也。凡脅之爲制、猶膺之爲當也。鬼谷子有飛鉆。鉆卽拑字。"}]},"揲":{"expl":"閱持也。从手枼聲。","rad":"手","fq":"今折切","vol":"12","py":"shé","duan":[{"e":"閱持也。","n":"閱者、具數也。更迭數之也。匹下曰。四丈也。从八匚。八揲一匹。按八揲一匹、則五五數之也。五五者、由一五二五數之至於八五、則四丈矣。𣪠辭傳曰。揲之以四。以象四時。謂四四數之也。四四者、由一四二四數之至若干四、則得其餘矣。凡傳云三三、兩兩、十十、五五者皆放此。閱持者旣得其數而持之。故其字从手。"}]},"摯":{"expl":"握持也。从手从執。","rad":"手","fq":"脂利切","vol":"12","py":"zhì","duan":[{"e":"握持也。","n":"握持者搤持也。周禮六贄字、許書作𡠗。又鳥部鷙鳥字皆或叚摯爲之。"}]},"操":{"expl":"把持也。从手喿聲。","rad":"手","fq":"七刀切","vol":"12","py":"cāo","duan":[{"e":"把持也。","n":"把者、握也。操重讀之曰節操、曰琴操。皆去聲。"}]},"㩴":{"expl":"爪持也。从手瞿聲。","rad":"手","fq":"居玉切","vol":"12","py":"jú","duan":[{"e":"爪持也。","n":"覆手曰爪。謂覆手持之也。徐鉉等曰。今俗別作掬。今按本部自有？篆。掬其俗體耳。其義訓兩指撮。非訓爪持。"}]},"捦":{"expl":"急持衣䘳也。从手金聲。","rad":"手","fq":"巨今切","vol":"12","py":"qín","duan":[{"e":"急持衣䘳也。","n":"此篆古叚借作禽。俗作擒、作捦。走獸總名曰禽者、以其爲人所捦也。又按此解五字、當作急持也一曰持衣䘳也九字乃合。必轉寫有譌奪矣。"}]},"搏":{"expl":"索持也。一曰至也。从手尃聲。","rad":"手","fq":"補各切","vol":"12","py":"bó","duan":[{"e":"𡩡持也。","n":"𡩡各本作索。今正。入室𢯱曰𡩡。𡩡持、謂摸索而持之。周禮環人。搏諜賊。釋文云。搏音博。又房布反。劉音付。射人注。貍、善搏者也。行則止而擬度焉。其發必獲。釋文云。搏音博。劉音付。士師注。胥讀爲宿偦之偦。偦謂司搏盜賊也。釋文云。搏音博。劉音付。小雅車攻箋。獸、田獵搏獸也。釋文云。搏音博。舊音付。按小司徒注之伺捕盜賊、卽士師注之司搏盜賊也。一用今字。一用古字。古捕盜字作搏。而房布反、又音付。猶後人所謂捫搎、摸𢱢也。本部搏捕二篆皆收。捕訓取也。又部取下云捕也。是與𡩡持義迥別。今則捕行而搏廢。但訓爲搏擊。又按搏擊與𡩡取無二義。凡搏擊者未有不乘其虛怯、扼其要害者。猶執盜賊必得其巢穴也。本無二義二音。至若考工"}]},"據":{"expl":"杖持也。从手豦聲。","rad":"手","fq":"居御切","vol":"12","py":"jù","duan":[{"e":"杖持也。","n":"謂倚杖而持之也。杖者人所據。則凡所據皆曰杖。據或作据。楊雄傳。三摹九据。晉灼曰。据今據字也。按何氏公羊傳注據亦皆作据。是叚借拮据字。"}]},"攝":{"expl":"引持也。从手聶聲。","rad":"手","fq":"書涉切","vol":"12","py":"shè","duan":[{"e":"引持也。","n":"謂引進而持之也。凡云攝者皆整飭之意。論語攝𪗋。史記。矦生攝弊衣冠。襄十四年左傳曰。不書者惰也。書者攝也。注云。能自攝整。詩。攝以威儀。傳曰。言相攝佐者以威儀也。論語。官事不攝。注云。攝猶兼也。皆引持之意。"}]},"𢪈":{"expl":"并持也。从手冄聲。","rad":"手","fq":"他含切","vol":"12","py":"nán","duan":[{"e":"幷持也。","n":"謂兼二物而持之也。秝部曰。秉持一禾。兼持二禾。兼者、會意字。？者、形聲字。？與兼音略同。"}]},"吻":{"expl":"口邊也。从口勿聲。","rad":"口","fq":"武粉切","vol":"02","py":"wěn","duan":[{"e":"口邊也。","n":"曲禮注云。口旁曰咡。廣雅云。咡謂之吻。考工記。銳喙、決吻。鄭曰。吻、口腃也。釋名曰。吻、免也。抆也。卷也。"}]},"抪":{"expl":"捫持也。从手布聲。","rad":"手","fq":"普胡切","vol":"12","py":"bù","duan":[{"e":"捫持也。","n":"謂捫按而持之也。金部鋪下云。箸門抪首也。抪首者、人所捫摸處也。"}]},"挾":{"expl":"俾持也。从手夾聲。","rad":"手","fq":"胡頰切","vol":"12","py":"xié","duan":[{"e":"俾持也。","n":"俾持、謂俾夾而持之也。亦部夾下曰。盜𥨸褱物也。俗謂蔽人俾夾。然則俾持正謂藏匿之持。如今人言懷挾也。孟子挾貴、挾賢、挾長、挾有勳勞、挾故。此皆本義之引申。音胡頰切。若詩禮之挾矢、周禮之挾日。音皆子協反。挾日、干本作帀日。左傳作浹。謂十日徧也。禮注。方持弦矢曰挾。謂矢與弦成十字形也。皆自其交會處言之。古文禮挾皆作接。然則接矢爲本字。挾矢爲叚借字與。"}]},"捫":{"expl":"撫持也。从手門聲。《詩》曰：“莫捫朕舌。”","rad":"手","fq":"莫奔切","vol":"12","py":"mén","duan":[{"e":"撫持也。","n":"撫、安也。一曰揗也。謂安揗而持之也。大雅。莫捫朕舌。傳曰。捫、持也。渾言不分析也。若王猛捫蝨之類。又專謂摩挲。"}]},"㩜":{"expl":"撮持也。从手監聲。","rad":"手","fq":"盧敢切","vol":"12","py":"lǎn","duan":[{"e":"撮持也。","n":"謂總撮而持之也。"}]},"擸":{"expl":"理持也。从手巤聲。","rad":"手","fq":"良涉切","vol":"12","py":"liè","duan":[{"e":"理持也。","n":"謂分理而持之也。"}]},"握":{"expl":"搤持也。从手屋聲。","rad":"手","fq":"於角切","vol":"12","py":"wò","duan":[{"e":"搤持也。","n":"按下文云搤、一曰握也。"}]},"撣":{"expl":"提持也。从手單聲。讀若行遟驒驒。","rad":"手","fq":"徒旱切","vol":"12","py":"dàn","duan":[{"e":"提持也。","n":"提持猶縣持也。太玄撣繫其名。撣訓觸。別一義。"}]},"把":{"expl":"握也。从手巴聲。","rad":"手","fq":"搏下切","vol":"12","py":"bǎ","duan":[{"e":"握也。","n":"握者、搤持也。孟子注曰。拱、合㒳手也。把、以一手把之也。"}]},"搹":{"expl":"把也。从手鬲聲。","rad":"手","fq":"於革切","vol":"12","py":"è","duan":[{"e":"把也。","n":"喪服。苴絰大搹。注曰。搹、扼也。中人之扼圍九寸。此言中人滿手把之。其圍九寸。則其徑約計三寸也。喪服傳。朝一溢米。夕一溢米。王肅、劉逵皆云。滿手曰溢。與鄭異。按此謂溢爲搹之叚借字也。然搹溢字見一章數行內、不應異用。則知鄭說爲長。"}]},"拏":{"expl":"牽引也。从手奴聲。","rad":"手","fq":"女加切","vol":"12","py":"ná","duan":[{"e":"持也。从手。奴聲。","n":"各本篆作挐。解作如聲。此與前文訓牽引之挐互譌也。今正。煩挐、紛挐字當从如。女居切。拏攫字當从奴。女加切。古音同在五部而形異。猶糸部有絮䋈二篆也。"}]},"嚨":{"expl":"喉也。从口龍聲。","rad":"口","fq":"盧紅切","vol":"02","py":"lónɡ","duan":[{"e":"㗋也。","n":"釋鳥曰。亢、鳥嚨。郭曰。謂㗋嚨。"}]},"攜":{"expl":"提也。从手雟聲。","rad":"手","fq":"户圭切","vol":"12","py":"xié","duan":[{"e":"提也。","n":"古多叚爲？字。"}]},"提":{"expl":"挈也。从手是聲。","rad":"手","fq":"杜兮切","vol":"12","py":"tí","duan":[{"e":"挈也。","n":"挈者、縣持也。攜則相竝。提則有高下。而互相訓者、渾言之也。"}]},"𢬴":{"expl":"拈也。从手𦔮聲。","rad":"手","fq":"丁惬切","vol":"12","py":"zhé","duan":[{"e":"拈也。从手。耴聲。","n":"丁愜切。八部。"}]},"拈":{"expl":"𢬴也。从手占聲。","rad":"手","fq":"奴兼切","vol":"12","py":"niān","duan":[{"e":"𢬴也。","n":"篇、韵皆云。𢫾取也。"}]},"摛":{"expl":"舒也。从手离聲。","rad":"手","fq":"丑知切","vol":"12","py":"chī","duan":[{"e":"舒也。","n":"蜀都賦。摛藻𢴵天庭。魏都賦。摛翰則華縱春葩。太玄經。幽攡萬類。字作攡。"}]},"捨":{"expl":"釋也。从手舍聲。","rad":"手","fq":"書冶切","vol":"12","py":"shě","duan":[{"e":"釋也。","n":"釋者、解也。按經傳多叚舍爲之。"}]},"擪":{"expl":"一指按也。从手厭聲。","rad":"手","fq":"於協切","vol":"12","py":"yè","duan":[{"e":"一指按也。","n":"洞簫賦。挹抐㩎㩶。李注。言中制也。莊子。外物擪其噦。一作壓。南都賦。彈琴擫籥。李注引說文。按㩎、擫皆同擪。"}]},"按":{"expl":"下也。从手安聲。","rad":"手","fq":"烏旰切","vol":"12","py":"àn","duan":[{"e":"下也。","n":"以手抑之使下也。印部曰。抑者、按也。"}]},"控":{"expl":"引也。从手空聲。《詩》曰：“控于大邦。”匈奴名引弓控弦。","rad":"手","fq":"苦貢切","vol":"12","py":"kònɡ","duan":[{"e":"引也。","n":"引者、開弓也。引申之爲凡引遠使近之偁。詩。控於大邦。傳曰。控、引也。此卽左傳所謂控吿也。又抑磬控忌。傳曰。騁馬曰磬。止馬曰控。按騁馬曰磬者、如大明傳之俔、磬也。極辭也。止馬曰控者、是亦引之使近之意也。"}]},"揗":{"expl":"摩也。从手盾聲。","rad":"手","fq":"食尹切","vol":"12","py":"shǔn","duan":[{"e":"摩也。","n":"廣雅曰。揗、順也。廣韵曰。手相安慰也。今人撫循字、古葢作揗。循者、行順也。淮南曰。引揗萬物。高注。引揗、拔擢也。讀允恭之允。"}]},"㗋":{"expl":"咽也。从口侯聲。","rad":"口","fq":"乎鉤切","vol":"02","py":"hóu","duan":[{"e":"咽也。从口。矦聲。","n":"乎鉤切。四部。"}]},"掾":{"expl":"緣也。从手彖聲。","rad":"手","fq":"以絹切","vol":"12","py":"yuàn","duan":[{"e":"緣也。","n":"緣者、衣純也。旣夕禮注。飾衣領袂口曰純。引申爲凡夤緣邊際之偁。掾者、緣其邊際而陳掾也。陳掾猶經營也。易卦辭曰彖。謂文王緣卦以得其義。然則彖者、掾之叚借字與。漢官有掾屬。正曰掾。副曰屬。漢舊注。東西曹掾比四百石。餘掾比三百石。屬比二百石。此等皆翼輔其旁者也。故曰掾。"}]},"𢫦":{"expl":"拊也。从手百聲。","rad":"手","fq":"普百切","vol":"12","py":"pāi","duan":[{"e":"拊也。","n":"釋名曰。拍、搏也。手搏其上也。按許釋搏曰𡩡持。則古經搏訓拍者、字之叚借。考工記。搏埴之工。注曰。搏之言拍也。云之言者、見其義本不同也。"}]},"拊":{"expl":"揗也。从手付聲。","rad":"手","fq":"芳武切","vol":"12","py":"fǔ","duan":[{"e":"揗也。","n":"揗者、摩也。古作拊揗。今作撫循。古今字也。堯典曰。擊石拊石。拊輕擊重。故分言之。又臯陶謨搏拊、樂器名。明堂位作拊搏。"}]},"掊":{"expl":"把也。今鹽官入水取鹽爲掊。从手咅聲。","rad":"手","fq":"父溝切","vol":"12","py":"póu","duan":[{"e":"杷也。","n":"杷各本作把。今正。木部曰。杷者、收麥器也。引申爲凡用手之偁。掊者、五指杷之。如杷之杷物也。史、漢皆言掊視得鼎。師古曰。掊、手杷土也。杷音蒲巴反。其字从木。按今俗用之刨字也。大雅曰。曾是掊克。傳曰。掊克、自伐而好勝人也。以自伐釋掊、以好勝人釋克。未得其解。定本掊作倍。正義謂己兼倍於人而自矜伐。似定本爲是矣。然孟子書亦作掊克。趙注但云不良也。知詩本不作掊。毛意謂掊爲倍之叚借字。掊有聚意。與捊音義近。有深取意。則不同捊也。毛詩釋文云。掊克、聚斂也。此謂同捊也。方言曰。掊、深也。郭注云。掊尅、深能。以深釋掊、以能釋尅。此亦必古說。但皆非毛義。方言掊訓深、與許說合。○六書故引唐本作捊也。不若顔氏本作杷。"}]},"捋":{"expl":"取易也。从手寽聲。","rad":"手","fq":"郎括切","vol":"12","py":"luō","duan":[{"e":"取易也。","n":"按捋與寽二篆義別。寽見𠬪部。云五指寽也。五指寽者、如用指取禾𥝩之榖是也。捋則訓取易而義不同。詩。薄言捋之。捋采其劉。傳曰。捋、取也。此捋之本義也。若董逌詩詁曰。以指歴取也。朱子詩集傳曰。捋取其子也。此於今之俗語求其義。而不知今之俗語、許書自有本字。凡訓詁之宐審愼如此。○寽下云五指捋也。宋本云五指持也。皆未是。廣韵六術云。寽、持取。今寽禾是。是則許當本作五指持取也。五指持而取之。於義乃合。"}]},"撩":{"expl":"理也。从手尞聲。","rad":"手","fq":"洛蕭切","vol":"12","py":"liáo","duan":[{"e":"理之也。","n":"之字依玄應書卷十五補。下云謂撩捋整理也。今多作料量之料。通俗文曰。理亂謂之撩理。"}]},"措":{"expl":"置也。从手昔聲。","rad":"手","fq":"倉故切","vol":"12","py":"cuò","duan":[{"e":"置也。","n":"置者、赦也。立之爲置。捨之亦爲置。措之義亦如是。經傳多叚錯爲之。賈誼傳叚厝爲之。"}]},"插":{"expl":"刺肉也。从手从臿。","rad":"手","fq":"楚洽切","vol":"12","py":"chā","duan":[{"e":"刺內也。","n":"內各本作肉。今正。內者、入也。刺內者、刺入也。漢人注經多叚捷字、扱字爲之。"}]},"掄":{"expl":"擇也。从手侖聲。","rad":"手","fq":"盧昆切","vol":"12","py":"lún","duan":[{"e":"擇也。","n":"晉語。君掄賢人之後有常位於國者而立之。韋注。掄、擇也。周禮。凡邦工入山林而掄材。不禁。鄭注。掄猶擇也。按鄭意掄之本訓不爲擇。故曰猶。"}]},"擇":{"expl":"柬選也。从手睪聲。","rad":"手","fq":"丈伯切","vol":"12","py":"zé","duan":[{"e":"柬選也。","n":"柬者、分別䉍之也。䉍者、存也。今小徐本作𥳑選、乃是譌字。韵會作揀、乃是俗字。辵部選下曰。一曰選擇也。"}]},"噲":{"expl":"咽也。从口會聲。讀若快。一曰嚵，噲也。","rad":"口","fq":"苦夬切","vol":"02","py":"kuài","duan":[{"e":"咽也。","n":"噲者、會也。聲氣所會也。"}]},"捉":{"expl":"搤也。从手足聲。一曰握也。","rad":"手","fq":"側角切","vol":"12","py":"zhuō","duan":[{"e":"搤也。从手。足聲。","n":"側角切。三部。"}]},"搤":{"expl":"捉也。从手益聲。","rad":"手","fq":"於革切","vol":"12","py":"è","duan":[{"e":"捉也。","n":"婁敬傳曰。搤其亢。拊其背。楊雄傳曰。搤熊羆。拕豪豬。搤其咽。炕其氣。皆謂捉持之。師古云。搤與㧖同。依許則搤㧖音雖同、而義迥別也。"}]},"挻":{"expl":"長也。从手从延，延亦聲。","rad":"手","fq":"式連切","vol":"12","py":"shān","duan":[{"e":"長也。","n":"商頌。松桷有挻。傳曰。挻、長皃。此許所本也。字林云。挻、長也。丑連反。此又本許也。自寫詩者譌从木作梴。又以梴竄入說文木部。而終古長誤矣。此義丑連反。若老子挻埴以爲器、其訓和也。柔也。其音始然反、音羶。其俗字作埏。見於詩、老子音義甚明。而今本譌舛。又方言挻、取也。凡取物而逆謂之篡。楚部或謂之挻。此義音羊羶反。"}]},"揃":{"expl":"搣也。从手前聲。","rad":"手","fq":"卽淺切","vol":"12","py":"jiǎn","duan":[{"e":"搣也。","n":"搣之訓見下。揃謂搣也。急就篇。沐浴揃搣寡合同。莊子。眥𡟬可以休老。本亦作揃搣。揃搣者、道家修養之法。故莊云可以休老。史游與沐俗寡合同類言。寡合同、卽嗇精寡慾之說也。若士喪禮、士虞禮之蚤揃。蚤讀爲爪。謂𣃔爪。揃讀爲翦。許作？。謂？須也。士虞禮揃或爲鬋。曲禮亦作蚤鬋。注云。鬋鬢也。釋鬋爲？理鬢髮。是禮經揃字爲？若鬋之叚借。而不用揃之本義。顔師古注急就曰。揃搣、謂𩮜拔眉髮也。葢去其不齊整者。顔氏誤以禮經之揃釋莊史之揃搣。是誤以叚借爲本義也。訓詁不通其源、斯誤有如此者。○莊子釋文引三倉云。揃猶翦也。云猶翦、則翦非本義。三倉不妨言叚借。惟說文解字不言叚借。"}]},"搣":{"expl":"㧗也。从手烕聲。","rad":"手","fq":"亡列切","vol":"12","py":"miè","duan":[{"e":"㧘也。","n":"㧘各本作㧗。小徐本及集韵、類篇、廣韵作批。今正。批者、㧗之譌。㧗者、㧘之譌也。手部㧘㧗二篆義別。㧘下云。一曰㧘搣頰旁也。與此曰搣㧘也相爲轉注。廣韵、玉篇皆曰。搣者、摩也。然則搣頰旁者、謂摩其頰旁。養生家之一法。故莊子曰靜黙可以補病。眥𡟬可以休老。眥𡟬卽㧘搣之叚借字。一本作揃搣。釋文引字林搣、㧗也。千米反。㧗亦㧘之誤。若作批、則𢱧之俗字。訓反手擊也。尢誤。○按廣韵、玉篇云。摩也。此字本義。廣韵又曰。批也。批卽㧗之誤。又曰。捽也。捽卽㧗之解也。又云。手拔也。玉篇云。莊子云揃搣、拔除也。是皆用師古急就篇注而誤。葢訓詁之難如此。"}]},"㧗":{"expl":"捽也。从手此聲。","rad":"手","fq":"側氏切","vol":"12","py":"zǐ","duan":[{"e":"捽也。","n":"捽之訓在下。按玄應書㒳引說文㧗、撠也。撠居逆反。謂撠、撮取也。又引通俗文掣挽曰㧗。按玄應本較今本爲長。但許本無撠。衹用㦸。是亦以俗字改許書也。"}]},"揤":{"expl":"捽也。从手卽聲。魏郡有揤裴侯國。","rad":"手","fq":"子力切","vol":"12","py":"jí","duan":[{"e":"捽也。从手。卽聲。","n":"子力切。古音在十二部。"}]},"捽":{"expl":"持頭髮也。从手卒聲。","rad":"手","fq":"昨没切","vol":"12","py":"zuó","duan":[{"e":"持頭髮也。","n":"金日磾傳。日磾捽胡、投何羅殿下。孟康曰。胡音互。捽胡、若今相僻臥輪之類也。晉灼曰。胡、頸也。捽其頸而投殿下也。"}]},"撮":{"expl":"四圭也。一曰兩指撮也。从手最聲。","rad":"手","fq":"倉括切","vol":"12","py":"cuō","duan":[{"e":"四圭也。","n":"漢律厤志曰。量多少者不失圭撮。孟康曰。六十四黍爲圭。按廣韵圭下云。孟子曰六十四黍爲一圭。十圭爲一合。孟子卽孟康。經典釋文序錄有孟子注老子二卷。或曰孟康也。康字公休。孫子筭經。六粟爲一圭。十圭爲一撮。十撮爲一抄。十抄爲一勺。十勺爲一合。說與孟異。本艸序例曰。凡散藥有云刀圭者。十分方寸匕之一。准如梧桐子大也。一撮者、四刀圭也。十撮爲一勺。十勺爲一合。此葢醫家用四圭爲撮之說。可相發明。"}]},"𡙳":{"expl":"撮也。从手，𥷤省聲。","rad":"手","fq":"居六切","vol":"12","py":"jú","duan":[{"e":"撮也。","n":"此蒙三指撮而言。不蒙四圭也。"}]},"吞":{"expl":"咽也。从口天聲。","rad":"口","fq":"土根切","vol":"02","py":"tūn","duan":[{"e":"咽也。","n":"今人以吞吐對舉。據此則咽㗋本名吞。俗云㗋吞是也。猶之㗋本名咽。平聲。今人以爲下咽字。一見切。"}]},"摕":{"expl":"撮取也。从手帶聲。讀若《詩》曰“螮蝀在東”。","rad":"手","fq":"都計切","vol":"12","py":"dì","duan":[{"e":"撮取也。","n":"謂撮而取之。亦蒙三指撮言也。有司徹。乃摭于魚腊俎。俎釋三个。其餘皆取之。古文摭爲摕。儀禮宋本、嘉靖本、單行疏本、釋文宋本皆如是。俗本作今文摭爲揲者、非也。凡言撮者皆謂少取。禮經依古文爲是。西京賦。摕飛鼯。亦謂撮取。薛解云。捎取之也。文賦。意徘徊而不能揥。揥當是摕之誤。今俗語云捎帶者、當作摕。"}]},"捊":{"expl":"引取也。从手孚聲。","rad":"手","fq":"步矦切","vol":"12","py":"póu","duan":[{"e":"引埾也。","n":"埾各本作取。今正。詩釋文作埾。今本譌爲取土二字。非也。埾義同聚。引埾者、引使聚也。玉篇正作引聚也。大雅。捄之陑陑。傳曰。捄、虆也。陑陑、眔也。箋云。捄、捊也。度、投也。築牆者捊聚壤土。盛之以虆。而投諸版中。此引聚之正義。箋與傳互相足。賓筵之仇、鄭讀爲𣂏。此捄、鄭釋爲捊。皆於其音之相近得其義也。常棣。原隰裒矣。傳云。裒、聚也。此重聚不重引、故不言引但言聚也。裒者、捊之俗。易。君子以裒多益寡。鄭、荀、董、蜀才作捊。云取也。此重引、故但言取也。"}]},"揜":{"expl":"自關以東謂取曰揜。一曰覆也。从手弇聲。","rad":"手","fq":"衣檢切","vol":"12","py":"yǎn","duan":[{"e":"自關以東取曰揜。","n":"取上俗本有謂字。今依宋本。方言曰。掩、𡩡、取也。自關而東曰掩。自關而西曰𡩡。或曰抯。按許所據方言葢作揜。李善注子虛、上林賦引方言亦作揜也。今廣雅掩、取也。字作掩。"}]},"授":{"expl":"予也。从手从受，受亦聲。","rad":"手","fq":"殖酉切","vol":"12","py":"shòu","duan":[{"e":"予也。","n":"予者、推予也。象相予之形。"}]},"承":{"expl":"奉也。受也。从手从卪从𠬞。","rad":"手","fq":"署陵切","vol":"12","py":"chénɡ","duan":[{"e":"奉也。受也。","n":"？部曰。奉者、承也。是二篆爲轉注也。𠬪部曰。受者、相付也。凡言承受、承順、承繼、又魯頌傳曰承止也皆奉之訓也。凡言或承之羞、承之以劒皆相付之訓也。左傳曰。蔡大夫恐昭矦之又遷也。承。此叚承爲懲也。"}]},"挋":{"expl":"給也。从手臣聲。一曰約也。","rad":"手","fq":"章刃切","vol":"12","py":"zhèn","duan":[{"e":"給也。","n":"給者、相足也。士喪禮曰。乃沐櫛。挋用巾。又曰。浴用巾。挋用浴衣。注曰。挋、晞也。淸也。按晞者、乾之也。洛用巾、旣以巾拭之矣。而復以浴衣挋之。謂抑按之使乾。此乾彼溼。可互相足。故曰給也。爾雅曰。挋、拭、刷、淸也。渾言之也。析言之、則挋與拭不同。故許書㕞飾也、㨷飾也爲一義。挋給也又爲一義也。"}]},"㨷":{"expl":"拭也。从手堇聲。","rad":"手","fq":"居焮切","vol":"12","py":"jìn","duan":[{"e":"飾也。","n":"飾各本作拭。今正。又部曰。㕞者、飾也。巾部曰。飾者、㕞也。飾拭正俗字。自淺人盡改許書之飾爲拭、而字例晦矣。㨷與挋爲伍、則非妝飾也。周禮遺人。以恤民之囏阨。注云。故書囏阨作㨷阨。按此古文叚借字也。"}]},"攩":{"expl":"朋羣也。从手黨聲。","rad":"手","fq":"多朗切","vol":"12","py":"dǎnɡ","duan":[{"e":"朋羣也。","n":"此鄉黨、黨與本字。俗用黨者、叚借字也。鳥部朋下曰。古文鳳也。鳳飛、羣鳥從以萬數。故以爲朋攩字。儒林傳。唯京氏爲異黨。師古曰。黨讀曰儻。按儻當作攩。"}]},"接":{"expl":"交也。从手妾聲。","rad":"手","fq":"子葉切","vol":"12","py":"jiē","duan":[{"e":"交也。","n":"交者、交脛也。引申爲凡相接之偁。周禮廩人接盛、讀爲一扱再祭之扱。"}]},"㧊":{"expl":"㨷也。从手巿聲。","rad":"手","fq":"普活切","vol":"12","py":"pō","duan":[{"e":"㨷也。","n":"今人用拂拭字當作此㧊。許作㧊飾也。拂者、過擊也。非其義。"}]},"咽":{"expl":"嗌也。从口因聲。","rad":"口","fq":"烏前切","vol":"02","py":"yān","duan":[{"e":"嗌也。","n":"咽者、因也。言食因於是以上下也。"}]},"挏":{"expl":"𢹬引也。漢有挏馬官，作馬酒。从手同聲。","rad":"手","fq":"徒緫切","vol":"12","py":"dònɡ","duan":[{"e":"推引也。","n":"推各本作𢹬。今依廣韵、韵會本。推讀如或推或輓之推。謂推之使前也。"}]},"招":{"expl":"手呼也。从手、召。","rad":"手","fq":"止搖切","vol":"12","py":"zhāo","duan":[{"e":"手𧦝也。","n":"𧦝各本作呼。今正。呼者、外息也。𧦝者、召也。不以口而以手。是手𧦝也。匏有苦葉傳曰。招招、號召之皃。按許書召者、𧦝也。號者、嘑也。是用手用口通得云招也。"}]},"撫":{"expl":"安也。从手無聲。一曰循也。","rad":"手","fq":"芳武切","vol":"12","py":"fǔ","duan":[{"e":"安也。从手。𣞤聲。","n":"芳武切。五部。"}]},"捪":{"expl":"撫也。从手昏聲。一曰摹也。","rad":"手","fq":"武巾切","vol":"12","py":"mín","duan":[{"e":"撫也。","n":"此冡上訓揗之撫而言。今人所用抆字、許土部墀下所用？字皆卽捪字也。"}]},"揣":{"expl":"量也。从手耑聲。度高曰揣。一曰捶之。","rad":"手","fq":"初委切","vol":"12","py":"chuǎi","duan":[{"e":"量也。","n":"量者、稱輕重也。稱者、銓也。銓者、衡也。"}]},"抧":{"expl":"開也。从手只聲。讀若抵掌之抵。","rad":"手","fq":"諸氏切","vol":"12","py":"zhǐ","duan":[{"e":"開也。从手。只聲。讀若扺掌之扺。","n":"扺各本作抵。今正。扺、側手擊也。扺掌者、側此手擊彼手掌也。諸氏切。十六部。"}]},"摜":{"expl":"習也。从手貫聲。《春秋傳》曰：“摜瀆鬼神。”","rad":"手","fq":"古患切","vol":"12","py":"ɡuàn","duan":[{"e":"習也。","n":"此與辵部遦音義皆同。古多叚貫爲之。"}]},"投":{"expl":"擿也。从手从殳。","rad":"手","fq":"度矦切","vol":"12","py":"tóu","duan":[{"e":"擿也。","n":"下文云。擿、投也。二篆爲轉注。巷伯傳曰。投、棄也。"}]},"擿":{"expl":"搔也。从手適聲。一曰投也。","rad":"手","fq":"直隻切","vol":"12","py":"zhì","duan":[{"e":"搔也。","n":"此義音剔。詩。象之揥也。傳曰。揥所以摘髮也。釋文云。揥勑帝反。摘他狄反。本又作擿。非也。擿音直戟反。按以許說繩之、則作擿爲是。擿正音他狄反也。以象骨搔首。因以爲飾。名之曰揥。故云所以擿髮。卽後人玉導、玉搔頭之類也。廣韵十二霽曰。揥者、揥枝整髮釵。許書無揥。"}]},"搔":{"expl":"括也。从手蚤聲。","rad":"手","fq":"穌遭切","vol":"12","py":"sāo","duan":[{"e":"𠜜也。","n":"𠜜各本作𢬸。今正。𢬸者、絜也。非其義。𠜜者、掊杷也。掊杷、正搔之訓也。內則。疾痛苛養。敬抑搔之。注曰。抑、按。搔、摩也。摩馬曰騷。其聲同也。又𤕫部疥、搔瘍也。瘍之需手搔者、謂之搔瘍。俗作瘙瘍。釋文、正義巳如此。"}]},"嗌":{"expl":"咽也。从口益聲。","rad":"口","fq":"伊昔切","vol":"02","py":"yì","duan":[{"e":"咽也。","n":"嗌者、扼也。扼要之處也。咽嗌雙聲。漢書。昌邑王嗌痛。爾雅注云。江東名咽爲嗌。"}]},"扴":{"expl":"刮也。从手介聲。","rad":"手","fq":"古黠切","vol":"12","py":"jiá","duan":[{"e":"𠜜也。","n":"此與？義同。𠜜小徐作？。譌。大徐不誤。廣韵曰。扴者、揩扴物也。易。介于石。馬本作扴。云觸小石聲。按扴于石、謂摩磢于石也。"}]},"摽":{"expl":"擊也。从手票聲。一曰挈門壯也。","rad":"手","fq":"符少切","vol":"12","py":"piāo","duan":[{"e":"擊也。","n":"左傳。長木之斃。無不摽也。杜云。摽、擊也。柏舟傳曰。摽、拊心皃。"}]},"挑":{"expl":"撓也。从手兆聲。一曰摷也。《國語》曰：“卻至挑夭。”","rad":"手","fq":"土凋切","vol":"12","py":"tiāo","duan":[{"e":"撓也。","n":"下文云。撓者、擾也。擾者、煩也。挑者、謂撥動之。左傳云挑戰是也。"}]},"抉":{"expl":"挑也。从手夬聲。","rad":"手","fq":"於說切","vol":"12","py":"jué","duan":[{"e":"挑也。","n":"抉者、有所入以出之也。"}]},"撓":{"expl":"擾也。从手堯聲。一曰捄也。","rad":"手","fq":"奴巧切","vol":"12","py":"náo","duan":[{"e":"𢺕也。","n":"此與女部嬈字音義皆同。"}]},"𢹎":{"expl":"煩也。从手夒聲。","rad":"手","fq":"而沼切","vol":"12","py":"rǎo","duan":[{"e":"煩也。","n":"煩者，熱頭痛也。引申為煩亂之偁。訓馴之字，依許作㹛，而古書多𢹎。葢𢹎得訓馴，猶亂得訓治，徂得訓存，苦得訓快，皆窮則變，變則通之理也。周禮注曰：𢹎猶馴也。言猶者，字本不訓馴。"}]},"挶":{"expl":"𢧢持也。从手局聲。","rad":"手","fq":"居玉切","vol":"12","py":"jū","duan":[{"e":"𢧢持也。","n":"𢧢持者、手如𢧢而持之也。左傳。褚師出。公𢧢其手。杜云。扺徒手屈肘如𢧢形。鄭注斯干如矢斯棘云。如人挾弓矢𢧢其肘。按古者𢧢之制。其鋒謂之援。援體斜横出。故人下其肘、臂卩翹其捥與手似之。亦謂之𢧢。鴟鴞傳曰。拮据、𢧢挶也。字本作𢧢。俗加手旁。非是。謂有所操作、曲其肘如𢧢而持之也。"}]},"据":{"expl":"𢧢挶也。从手居聲。","rad":"手","fq":"九魚切","vol":"12","py":"jū","duan":[{"e":"𢧢挶也。","n":"鴟鴞。予手拮据。傳曰。拮据、𢧢挶也。公羊注叚据爲據。"}]},"擖":{"expl":"刮也。从手葛聲。一曰撻也。","rad":"手","fq":"口八切","vol":"12","py":"qià","duan":[{"e":"𠜜也。","n":"此與扴音義略同。"}]},"摘":{"expl":"拓果樹實也。从手啻聲。一曰指近之也。","rad":"手","fq":"他歴切","vol":"12","py":"zhāi","duan":[{"e":"拓果樹實也。","n":"拓者、拾也。拾者、掇也。掇者、拾取也。果樹實者、有果之樹之實也。拓之、謂之摘。引申之、凡他取亦曰摘。此篆與擿音義殊。"}]},"閏":{"expl":"餘分之月，五歲再閏，告朔之禮，天子居宗廟，閏月居門中。从王在門中。《周禮》曰：“閏月，王居門中，終月也。”","rad":"王","fq":"如順切","vol":"01","py":"rùn","duan":[{"e":"餘分之月。五歲再閏也。","n":"戴先生原象曰。日循黃道右旋。邪絡乎赤道而南北。凡三百六十五日。小餘不滿四分日之一。日發斂一終。月道邪交乎黃道。凡二十七日。小餘過日之半。月逡其道一終。日月之㑹。凡二十九日。小餘過日之半以起朔。十二朔凡三百五十四日有奇分而近。歲終積其差數置閏月。然後時序之從乎日行發斂者以正。故堯典曰。朞三百有六旬有六日。以閏月正四時成歲。言六日者舉成數。玉裁按。五歲再閏而無餘日。"}]},"喗":{"expl":"大口也。从口軍聲。","rad":"口","fq":"牛殞切","vol":"02","py":"yǔn","duan":[{"e":"大口也。从口。軍聲。","n":"牛殞切。十三部。"}]},"搳":{"expl":"擖也。从手害聲。","rad":"手","fq":"胡秸切","vol":"12","py":"xiá","duan":[{"e":"擖也。","n":"與擖篆宐聯綴。"}]},"摲":{"expl":"暫也。从手斬聲。","rad":"手","fq":"昨甘切","vol":"12","py":"cán","duan":[{"e":"斬取也。","n":"各本取二字作暫。今正。斬者、𢧵也。謂𣃔物也。暫非其義。禮器。有摲而播也。長楊賦。麾城摲邑。蒼頡篇曰。摲、拍取也。鄭曰。摲之言芟也。按芟、刈艸也。㨻本訓芟夷。禮器注謂於此少與、得分以與彼。是爲芟殺有所與。摲殺上貴之分以布徧於賤者、謂之摲而播。故廣雅本之爲說曰。㨻者、次也。是鄭注禮之義。而非摲之本義也。"}]},"拹":{"expl":"摺也。从手劦聲。一曰拉也。","rad":"手","fq":"虚業切","vol":"12","py":"xié","duan":[{"e":"摺也。","n":"公羊傳曰。使公子彭生送桓公。於其乘焉。拹幹而殺之。幹者、脅骨也。何曰。拹者、折聲也。拹或作搚者、或體也。或作拉者、叚借字也。"}]},"摺":{"expl":"敗也。从手習聲。","rad":"手","fq":"之涉切","vol":"12","py":"zhé","duan":[{"e":"敗也。","n":"敗者、毁也。今義爲摺㬪。"}]},"揫":{"expl":"束也。从手秋聲。《詩》曰：“百祿是揫。”","rad":"手","fq":"卽由切","vol":"12","py":"jiū","duan":[]},"摟":{"expl":"曳、聚也。从手婁聲。","rad":"手","fq":"洛侯切","vol":"12","py":"lōu","duan":[{"e":"曳聚也。","n":"此當作曳也、聚也。各本奪上也字。山有樞曰。弗曳弗摟。傳曰。摟亦曳也。此曳訓所本也。曳者、臾曳也。釋詁曰。摟、聚也。此聚訓所本也。趙注孟子曰。摟、牽也。此曳義之引申也。"}]},"抎":{"expl":"有所失也。《春秋傳》曰：“抎子，辱矣。”从手云聲。","rad":"手","fq":"于敏切","vol":"12","py":"yǔn","duan":[{"e":"有所失也。","n":"成公二年左傳。石稷謂孫良夫曰。子國卿也。隕子辱矣。許所據作抎。正謂失也。戰國策。被礛磻。引微？。折淸風而抎矣。此叚抎爲隕也。史記東粤列傳。不戰而耘。利莫大焉。謂閩粤不戰而失其王頭。此叚耘爲抎也。"}]},"披":{"expl":"从㫄持曰披。从手皮聲。","rad":"手","fq":"𢾭羈切","vol":"12","py":"pī","duan":[{"e":"從旁持曰披。","n":"士喪禮設披。注曰。披、絡桺棺上。貫結於戴。人君旁牽之以備傾𧇾。又執披者旁四人。注曰。前後左右各二人。此從旁持之義也。五帝本紀。黃帝披山通道。徐廣曰。披、他本亦作陂字。葢當音詖。陂者、旁其邊之謂也。按披陂皆有旁其邊之意。中散能知之。而索隱云披音如字。謂披山林艸木而行、以通道也。此則司馬貞不知古義之言。葢俗解訓披爲開。廣韵云披、開也。分也。散也。木部柀訓析也。柀靡字如此作。而淺人以披訓析。改柀靡爲披靡。莫有能諟正者。"}]},"𤸪":{"expl":"引縱曰𤸪。从手，瘛省聲。","rad":"手","fq":"尺制切","vol":"12","py":"chì","duan":[{"e":"引縱曰𤸪。","n":"爾雅釋文作引而縱之曰𤸪。引、開弓也。縱、緩也。一曰舍也。按引縱者、謂宐遠而引之使近。宐近而縱之使遠。皆爲牽掣也。不必如釋文所據爾雅曰甹夆、掣曳也。俗字作撦、作扯。聲形皆異矣。"}]},"㧘":{"expl":"積也。《詩》曰：“助我舉㧘。”搣頰㫄也。从手此聲。","rad":"手","fq":"前智切","vol":"12","py":"zì","duan":[{"e":"積也。","n":"小雅車攻曰。助我舉柴。傳曰。柴、積也。箋云。雖不中、必助中者舉積禽也。柴、許所據作㧘。此聲責聲古同在十六部。以㬪韵爲訓。"}]},"哆":{"expl":"張口也。从口多聲。","rad":"口","fq":"丁可切","vol":"02","py":"chǐ","duan":[{"e":"張口也。","n":"小雅。哆兮侈兮。毛曰。哆、大皃。"}]},"掉":{"expl":"搖也。从手卓聲。《春秋傳》曰：“尾大不掉。”","rad":"手","fq":"徒弔切","vol":"12","py":"diào","duan":[{"e":"搖也。","n":"掉者、搖之過也。搖者、掉之不及也。許渾言之。"}]},"搖":{"expl":"動也。从手䍃聲。","rad":"手","fq":"余招切","vol":"12","py":"yáo","duan":[{"e":"動也。从手。䍃聲。","n":"余招切。二部。"}]},"搈":{"expl":"動搈也。从手容聲。","rad":"手","fq":"余隴切","vol":"12","py":"rónɡ","duan":[{"e":"動搈也。","n":"動搈、漢時語。廣雅曰。搈、動也。"}]},"𢴧":{"expl":"當也。从手貳聲。","rad":"手","fq":"直異切","vol":"12","py":"zhì","duan":[{"e":"當也。","n":"廣雅曰。？、當也。"}]},"揂":{"expl":"聚也。从手酋聲。","rad":"手","fq":"卽由切","vol":"12","py":"jiū","duan":[{"e":"聚也。","n":"商頌。百祿是遒。傳曰。遒、聚也。按傳謂此遒爲揂之叚借字。"}]},"掔":{"expl":"固也。从手臤聲。讀若《詩》“赤舃掔掔”。","rad":"手","fq":"苦閑切","vol":"12","py":"qiān","duan":[{"e":"固也。","n":"掔之言堅也、緊也。謂手持之固也。或叚借爲牽字。如史記鄭襄公肉袒掔羊、卽左傳之牽羊也。俗用慳吝字。亦爲掔之俗。"}]},"捀":{"expl":"奉也。从手夆聲。","rad":"手","fq":"𢾭容切","vol":"12","py":"fénɡ","duan":[{"e":"奉也。","n":"奉者、承也。"}]},"𢹏":{"expl":"對舉也。从手輿聲。","rad":"手","fq":"以諸切","vol":"12","py":"yú","duan":[]},"揚":{"expl":"飛舉也。从手昜聲。","rad":"手","fq":"與章切","vol":"12","py":"yánɡ","duan":[{"e":"飛舉也。从手。昜聲。","n":"與章切。十部。"}]},"擧":{"expl":"對舉也。从手與聲。","rad":"手","fq":"居許切","vol":"12","py":"jǔ","duan":[{"e":"對舉也。","n":"對舉謂以兩手舉之。故其字从手與。𠂇手與又手也。"}]},"呱":{"expl":"小兒嗁聲。从口瓜聲。《詩》曰：“后稷呱矣。”","rad":"口","fq":"古乎切","vol":"02","py":"ɡū","duan":[{"e":"小兒嗁聲。","n":"咎繇謨。啟呱呱而泣。"}]},"掀":{"expl":"舉出也。从手欣聲。《春秋傳》曰：“掀公出於淖。”","rad":"手","fq":"虚言切","vol":"12","py":"xiān","duan":[{"e":"舉出也。","n":"掀之言軒也。"}]},"揭":{"expl":"高舉也。从手曷聲。","rad":"手","fq":"去例切","vol":"12","py":"qì","duan":[{"e":"高舉也。","n":"見於詩者、匏有苦葉傳曰。揭、褰裳也。碩人傳曰。揭揭、長也。蕩傳曰。揭、見根皃。"}]},"抍":{"expl":"上舉也。从手升聲。《易》曰：“抍馬，壯，吉。”","rad":"手","fq":"蒸上切","vol":"12","py":"zhěnɡ","duan":[]},"振":{"expl":"舉救也。从手辰聲。一曰奮也。","rad":"手","fq":"章刃切","vol":"12","py":"zhèn","duan":[{"e":"舉救之也。","n":"之字依韵會補。諸史籍所云振給、振貣是其義也。凡振濟當作此字。俗作賑、非也。匡謬正俗言之詳矣。"}]},"扛":{"expl":"橫關對舉也。从手工聲。","rad":"手","fq":"古雙切","vol":"12","py":"ɡānɡ","duan":[{"e":"横關對舉也。","n":"以木横持門戶曰關凡大物而兩手對舉之曰扛。項羽力能扛鼎。謂鼎有？、以木横貫鼎耳而舉其㒳耑也。卽無横木而兩手舉之亦曰扛。卽兩人以横木對舉一物亦曰扛。字林。捎、掆、舁也。匡謬正俗曰。音譌。故謂扛爲剛。有造掆字者。故爲穿鑿也。西京賦作？鼎。？卽䚗。魏大饗碑作䚗鼎。䚗者、扛之叚借字也。"}]},"扮":{"expl":"握也。从手分聲。讀若粉。","rad":"手","fq":"房吻切","vol":"12","py":"fěn","duan":[{"e":"握也。","n":"大玄曰。地則虛三以扮天之十八也。扮猶幷也。"}]},"撟":{"expl":"舉手也。从手喬聲。一曰撟，擅也。","rad":"手","fq":"居少切","vol":"12","py":"jiǎo","duan":[{"e":"舉手也。","n":"引申之、凡舉皆曰撟。古多叚矯爲之。陶淵明曰。時矯首而遐觀。王逸注楚辭曰。矯、舉也。"}]},"捎":{"expl":"自關巳西，凡取物之上者爲撟捎。从手肖聲。","rad":"手","fq":"所交切","vol":"12","py":"shāo","duan":[{"e":"自關巳西凡取物之上者爲撟捎。","n":"取物之上、謂取物之顚也。捎之言梢也。方言曰。撟捎、選也。自關而西秦晉之閒凡取物之上謂之撟捎。按今俗語云捎帶是也。西京賦注曰。摕者、捎取之。𦒱工記捎其藪、捎溝。注曰。捎、除也。其引申之義。"}]},"𢹬":{"expl":"抱也。从手雝聲。","rad":"手","fq":"於隴切","vol":"12","py":"yǒnɡ","duan":[{"e":"袌也。","n":"各本作抱也。今正。抱者、說文之或捊字也。袌見衣部。褱也。改袌爲抱、大失許例。公食大夫禮。？簠粱。注云。擁、抱也。吳語。官帥擁鐸。注云。擁、抱也。漢書注曰、南方謂抱小兒爲雍樹。雍者、擁之叚借字。"}]},"擩":{"expl":"染也。从手需聲。《周禮》：“六曰擩祭。”","rad":"手","fq":"而主切","vol":"12","py":"rǔ","duan":[]},"啾":{"expl":"小兒聲也。从口秋聲。","rad":"口","fq":"卽由切","vol":"02","py":"jiū","duan":[{"e":"小兒聲也。","n":"倉頡篇。啾、衆聲也。三年問。啁噍之頃。此假噍爲啾也。"}]},"揄":{"expl":"引也。从手俞聲。","rad":"手","fq":"羊朱切","vol":"12","py":"yú","duan":[{"e":"引也。","n":"漢郊祀歌曰。神之揄。臨壇宇。師古云。揄、引也。史記。揄長袂。廣韵。揄揚、詭言也。皆其引申之義。大雅。或春或揄。叚揄爲舀也。"}]},"搫":{"expl":"搫擭，不正也。从手般聲。","rad":"手","fq":"薄官切","vol":"12","py":"pán","duan":[{"e":"搫擭、","n":"逗。"}]},"擭":{"expl":"搫擭也。一曰布擭也，一曰握也。从手蒦聲。","rad":"手","fq":"一虢切","vol":"12","py":"wò","duan":[{"e":"搫擭也。从手。蒦聲。","n":"一虢切。古音在五部。"}]},"拚":{"expl":"拊手也。从手弁聲。","rad":"手","fq":"皮變切","vol":"12","py":"biàn","duan":[{"e":"拊手也。","n":"拊、揗也。？、拊也。此不但言拊、言拊手者、謂兩手相？也。今人謂歡拚是也。漢書、吳都賦皆云拚射。孟康曰。手搏爲拚。此則謂兩人手相搏也。"}]},"擅":{"expl":"專也。从手亶聲。","rad":"手","fq":"時戰切","vol":"12","py":"shàn","duan":[{"e":"專也。","n":"專當作嫥。嫥者、壹也。"}]},"揆":{"expl":"葵也。从手癸聲。","rad":"手","fq":"求癸切","vol":"12","py":"kuí","duan":[{"e":"度也。","n":"各本作葵也。今依六書故所據唐本正。度者、法制也。因以爲揆度之度。今音分去入。古無二也。小雅。天子葵之。傳曰。葵、揆也。謂叚葵爲揆也。"}]},"擬":{"expl":"度也。从手疑聲。","rad":"手","fq":"魚已切","vol":"12","py":"nǐ","duan":[{"e":"度也。","n":"今所謂揣度也。"}]},"損":{"expl":"減也。从手員聲。","rad":"手","fq":"穌本切","vol":"12","py":"sǔn","duan":[{"e":"減也。","n":"水部曰。減者、損也。二篆爲轉注。"}]},"失":{"expl":"縱也。从手乙聲。","rad":"手","fq":"式質切","vol":"12","py":"shī","duan":[{"e":"縱也。","n":"縱者、緩也。一曰捨也。在手而逸去爲失。兔部曰。逸、失也。古多叚爲逸去之逸。亦叚爲淫泆之泆。"}]},"捝":{"expl":"解捝也。从手兌聲。","rad":"手","fq":"他括切","vol":"12","py":"tuō","duan":[{"e":"解挩也。","n":"今人多用脫。古則用挩。是則古今字之異也。今脫行而挩廢矣。"}]},"喤":{"expl":"小兒聲。从口皇聲。《詩》曰：“其泣喤喤。”","rad":"口","fq":"乎光切","vol":"02","py":"huánɡ","duan":[{"e":"小兒聲。","n":"啾謂小兒小聲。喤謂小兒大聲也。如離騷鳴玉鑾之啾啾、詩鍾𡔷喤喤、喤喤厥聲、則泛謂小聲大聲。"}]},"撥":{"expl":"治也。从手發聲。","rad":"手","fq":"北末切","vol":"12","py":"bō","duan":[{"e":"治也。","n":"公羊傳。撥亂世。反諸正。何注曰。撥猶治也。何言猶者、何意撥之本義非治。撥之所以爲治也。許則直云治。"}]},"挹":{"expl":"抒也。从手邑聲。","rad":"手","fq":"於汲切","vol":"12","py":"yì","duan":[{"e":"抒也。","n":"大雅曰。泂酌彼行潦。挹彼注茲。"}]},"抒":{"expl":"挹也。从手予聲。","rad":"手","fq":"神與切","vol":"12","py":"shū","duan":[{"e":"挹也。","n":"凡挹彼注茲曰抒。斗部曰。斜、抒也。㪻、抒屚也。𣂏、挹也。水部曰。浚、抒也。漉、浚也。？、抒井？也。左傳。難必抒矣。此叚抒爲紓。紓者、緩也。服䖍本正作紓。"}]},"抯":{"expl":"挹也。从手且聲。讀若樝棃之樝。","rad":"手","fq":"側加切","vol":"12","py":"zhā","duan":[{"e":"挹也。","n":"方言曰。抯、摣、取也。南楚之閒凡取物溝泥中謂之抯。亦謂之摣。"}]},"攫":{"expl":"扟也。从手矍聲。","rad":"手","fq":"居縛切","vol":"12","py":"jué","duan":[{"e":"扟也。","n":"蒼頡篇曰。攫、搏也。通俗文曰。手把曰攫。淮南子曰。鳥窮則搏。獸窮則攫。按衆經音義卷五卷十二引說文同。而注之曰。扟居逆切。是其所據說文作丮。轉寫譌作扟耳。丮者、持也。"}]},"扟":{"expl":"从上挹也。从手卂聲。讀若莘。","rad":"手","fq":"所臻切","vol":"12","py":"shēn","duan":[{"e":"從上挹取也。","n":"取字各本無。依玄應補。通俗文云。從上取曰扟。"}]},"拓":{"expl":"拾也。陳、宋語。从手石聲。","rad":"手","fq":"之石切","vol":"12","py":"zhí","duan":[{"e":"拾也。","n":"有司徹篇。乃摭于魚腊俎。俎釋三个。其餘皆取之。摘下云。拓果樹實也。儀禮摭古文作摕。此實非一字。因雙聲而異。"}]},"攈":{"expl":"拾也。从手麇聲。","rad":"手","fq":"居運切","vol":"12","py":"jùn","duan":[{"e":"拾也。","n":"魯語。收攟而烝。韋云。攟、拾也。漢㓝法志。蕭何攈摭秦法。取其宐於時者。作律九章。"}]},"拾":{"expl":"掇也。从手合聲。","rad":"手","fq":"是執切","vol":"12","py":"shí","duan":[{"e":"掇也。","n":"史記貨殖傳曰。俯有拾。仰有取。射有決拾。毛傳曰。決、所以鉤弦也。拾、遂也。拾韜左臂。卽俗所謂收拾也。曲禮。拾級聚足。鄭曰。拾讀爲涉。聲之誤也。"}]},"掇":{"expl":"拾取也。从手叕聲。","rad":"手","fq":"都括切","vol":"12","py":"duó","duan":[{"e":"拾取也。","n":"周南傳曰。掇、拾也。"}]},"咺":{"expl":"朝鮮謂兒泣不止曰咺。从口，宣省聲。","rad":"口","fq":"況晚切","vol":"02","py":"xuǎn","duan":[{"e":"朝鮮謂兒泣不止曰咺。","n":"方言。咺、痛也。凡哀泣而不止曰咺。朝鮮洌水之閒少兒泣而不止曰咺。"}]},"擐":{"expl":"貫也。从手瞏聲。《春秋傳》曰：“擐甲執兵。”","rad":"手","fq":"胡慣切","vol":"12","py":"huàn","duan":[{"e":"毌也。","n":"毌各本作貫。今正。毌、穿物持之也。今人廢毌而專用貫矣。杜注左傳、韋注國語皆曰。擐、貫也。"}]},"揯":{"expl":"引、急也。从手恆聲。","rad":"手","fq":"古恒切","vol":"12","py":"ɡēnɡ","duan":[{"e":"引急也。","n":"淮南書曰。大弦搄則小弦絶。"}]},"摍":{"expl":"蹴引也。从手宿聲。","rad":"手","fq":"所六切","vol":"12","py":"suō","duan":[{"e":"蹴引也。","n":"蹴猶迫也。古多叚戚爲之。蹴引者、蹴迫而引取之。摍古叚縮爲之。毛詩傳曰。鄰之釐婦。夜曓風雨室壞。趨而至。顔叔子納之。而使執燭。放乎旦而蒸盡。縮屋而繼之。釋文云。縮又作摍、同。按武梁祠堂碑云摍笮是也。戰國策。淖齒管齊之權。縮閔王之筋。縣之廟梁。宿昔而死。亦卽摍字。摍屋、卽左傳所謂抽屋也。"}]},"㨜":{"expl":"相援也。从手虔聲。","rad":"手","fq":"巨言切","vol":"12","py":"qián","duan":[{"e":"相援也。从手。虔聲。","n":"巨言切。十四部。"}]},"援":{"expl":"引也。从手爰聲。","rad":"手","fq":"雨元切","vol":"12","py":"yuán","duan":[{"e":"引也。","n":"大雅。以爾鉤援。毛傳。鉤援、鉤、鉤梯也。所以鉤引上城者。又無然畔援。傳曰。無是畔道。無是援取。"}]},"㩅":{"expl":"引也。从手畱聲。","rad":"手","fq":"敕鳩切","vol":"12","py":"chōu","duan":[{"e":"引也。","n":"鄭風。左旋右抽。傳曰。左旋、講兵。右抽、抽矢以䠶。竹部曰。籒、讀書也。牆有茨傳曰。讀、抽也。方言曰。抽、讀也。尙書。克由繹之。大史公自序。紬史記石室金匱之書。紬卽籒也。籒之言抽也。"}]},"擢":{"expl":"引也。从手翟聲。","rad":"手","fq":"直角切","vol":"12","py":"zhuó","duan":[{"e":"引也。","n":"毛傳曰。楫所以擢舟也。擢舟、謂引舟也。"}]},"拔":{"expl":"擢也。从手犮聲。","rad":"手","fq":"蒲八切","vol":"12","py":"bá","duan":[{"e":"擢也。从手。犮聲。","n":"蒲八切。十五部。"}]},"揠":{"expl":"拔也。从手匽聲。","rad":"手","fq":"烏黠切","vol":"12","py":"yà","duan":[{"e":"拔也。","n":"孟子。宋人有閔其苗之不長而揠之者。趙云。揠、挺拔之欲亟長也。方言。揠、擢、拂、戎、拔也。自關而西或曰拔。東齊海岱之閒曰揠。"}]},"擣":{"expl":"手推也。一曰築也。从手𠷎聲。","rad":"手","fq":"都皓切","vol":"12","py":"dǎo","duan":[{"e":"手椎也。","n":"以手爲椎而椎之。"}]},"唴":{"expl":"秦晉謂兒泣不止曰唴。从口羌聲。","rad":"口","fq":"丘尚切","vol":"02","py":"qiànɡ","duan":[{"e":"秦晉調兒泣不止曰唴。","n":"方言。自關而西秦晉之閒。凡大人少兒泣而不止謂之唴。哭極音絶亦謂之唴。平原謂啼極無聲謂之唴哴。"}]},"攣":{"expl":"係也。从手䜌聲。","rad":"手","fq":"呂員切","vol":"12","py":"luán","duan":[{"e":"係也。","n":"係者、絜束也。易小畜。有孚攣如。馬曰。連也。虞曰。引也。攣者、係而引之。其義近擢。"}]},"挺":{"expl":"拔也。从手廷聲。","rad":"手","fq":"徒鼎切","vol":"12","py":"tǐnɡ","duan":[{"e":"拔也。","n":"左傳。周道挺挺。直也。月令。挺重囚。寛也。皆引申之義。"}]},"㩃":{"expl":"拔取也。南楚語。从手寒聲。《楚詞》曰：“朝㩃批之木蘭。”","rad":"手","fq":"九輦切","vol":"12","py":"qiān","duan":[{"e":"拔取也。南楚語。","n":"莊子至樂篇。攓蓬而取之。司馬注曰。攓、拔也。方言曰。攓、取也。南楚曰攓。又曰。楚謂之攓。"}]},"探":{"expl":"遠取之也。从手罙聲。","rad":"手","fq":"他含切","vol":"12","py":"tān","duan":[{"e":"遠取之也。","n":"探之言深也。易曰。探嘖索隱。"}]},"撢":{"expl":"探也。从手覃聲。","rad":"手","fq":"他紺切","vol":"12","py":"tàn","duan":[{"e":"揬也。","n":"周禮撢人。掌撢序王意以語天下。釋文曰。與探同。按許書、則義同而各自爲字。"}]},"捼":{"expl":"推也。从手委聲。一曰兩手相切摩也。","rad":"手","fq":"奴禾切","vol":"12","py":"ruó","duan":[]},"撆":{"expl":"別也。一曰擊也。从手敝聲。","rad":"手","fq":"芳滅切","vol":"12","py":"piē","duan":[{"e":"飾也。","n":"各本作別也。不可通。今正。文選洞簫賦注引撆、飾也。飾者、㕞也。見巾部。飾者、今之拭字。葢一本作㕞。其義一也。而字形一譌爲刷。再譌遂爲別矣。此攷覈者所宐知也。拭與拂義略同。蔡邕篆勢曰。揚波振撆。文選。撇波而濟。撇同撆。又史記荆軻傳跪而蔽席、孟荀傳襒席皆謂拭席。皆撆之異體也。"}]},"㨔":{"expl":"搖也。从手咸聲。","rad":"手","fq":"胡感切","vol":"12","py":"hàn","duan":[{"e":"搖也。","n":"搖宋本作㩅。誤。"}]},"搦":{"expl":"按也。从手弱聲。","rad":"手","fq":"尼革切","vol":"12","py":"nuò","duan":[{"e":"按也。","n":"按者、抑也。周禮矢人。橈之以眡其鴻殺之稱。注曰。橈搦其榦。謂按下之令曲。則强弱見矣。玄應書曰。搦猶捉也。此今義、非古義也。古義搦同橈。"}]},"掎":{"expl":"偏引也。从手奇聲。","rad":"手","fq":"居綺切","vol":"12","py":"jǐ","duan":[{"e":"偏引也。","n":"一本作偏引一足也。見李賢、司馬貞所引。此依左傳注增二字耳。左傳曰。譬如捕鹿。晉人角之。諸戎掎之。杜注云。掎之、掎其足也。國語。掎止晏萊。韋云。從後曰掎。子虛賦腳麟。司馬彪云。腳、掎也。詩。伐木掎矣。傳曰。伐木者掎其顚。"}]},"咷":{"expl":"楚謂兒泣不止曰噭咷。从口兆聲。","rad":"口","fq":"徒刀切","vol":"02","py":"táo","duan":[{"e":"楚謂兒泣不止曰噭咷。","n":"方言。楚謂之噭咷。按噭字見上。"}]},"揮":{"expl":"奮也。从手軍聲。","rad":"手","fq":"許歸切","vol":"12","py":"huī","duan":[{"e":"奮也。","n":"按奞部奮下曰。翬也。翬下曰。大飛也。此云奮也。揮與翬義略同。玄應引此下有謂奮訊振去之也七字。葢庾儼黙注語。"}]},"摩":{"expl":"研也。从手麻聲。","rad":"手","fq":"莫婆切","vol":"12","py":"mó","duan":[{"e":"揅也。","n":"揅各本作硏。今正。此以揅與摩互訓。石部硏之訓䃺也。手部揅之訓摩也。義各有屬。無容淆之。摩揅之功、精於䃺硏。挼下曰。兩手相切摩也。學記曰。相觀而善之謂摩。凡毛詩爾雅如琢如摩、周禮刮摩字多从手。俗从石作磨。不可通。"}]},"𢱧":{"expl":"反手擊也。从手𣬉聲。","rad":"手","fq":"匹齊切","vol":"12","py":"pī","duan":[{"e":"反手擊也。","n":"左傳曰。宋萬遇仇牧于門。𢱧而殺之。玉篇所引如是。今左傳作批。俗字也。"}]},"攪":{"expl":"亂也。从手覺聲。《詩》曰：“祇攪我心。”","rad":"手","fq":"古巧切","vol":"12","py":"jiǎo","duan":[{"e":"亂也。","n":"毛傳同。"}]},"搑":{"expl":"推擣也。从手茸聲。","rad":"手","fq":"而隴切","vol":"12","py":"rǒnɡ","duan":[{"e":"推擣也。","n":"漢書。而僕又茸以蠶室。師古曰。茸音人勇反。推也。謂推致蠶室之中也。如顔說、則茸者搑之叚借字。"}]},"撞":{"expl":"卂擣也。从手童聲。","rad":"手","fq":"宅江切","vol":"12","py":"zhuànɡ","duan":[{"e":"卂擣也。","n":"卂者、疾也。"}]},"㧢":{"expl":"就也。从手因聲。","rad":"手","fq":"於眞切","vol":"12","py":"yīn","duan":[{"e":"就也。","n":"㧢與因音義同。今則因行而㧢廢矣。"}]},"扔":{"expl":"因也。从手乃聲。","rad":"手","fq":"如乘切","vol":"12","py":"rēnɡ","duan":[{"e":"㧢也。","n":"㧢各本作因。今正。扔與仍音義同老子曰。爲之而莫之應。則攘臂而扔之。"}]},"括":{"expl":"絜也。从手𠯑聲。","rad":"手","fq":"古活切","vol":"12","py":"kuò","duan":[{"e":"絜也。","n":"絜者、麻一耑也。引申爲絜束之絜。凡物圍度之曰絜。賈子度長絜大是也。束之亦曰絜。凡經言？髮者、皆謂束髮也。髟部曰。䯺者、絜髮也。然則束髮曰䯺。？爲凡物緫會之偁。毛詩傳曰。？、至也。其引申之義也。易？囊、借爲𠯑字也。"}]},"抲":{"expl":"抲撝也。从手可聲。《周書》曰：“盡執，抲。”","rad":"手","fq":"虎何切","vol":"12","py":"hē","duan":[{"e":"抲、","n":"此複舉字之未刪者。"}]},"喑":{"expl":"宋齊謂兒泣不止曰喑。从口音聲。","rad":"口","fq":"於今切","vol":"02","py":"yīn","duan":[{"e":"宋齊謂兒泣不止曰喑。","n":"方言。齊宋之閒謂之喑。或謂之惄。按喑之言瘖也。謂啼極無聲。"}]},"擘":{"expl":"撝也。从手辟聲。","rad":"手","fq":"博戹切","vol":"12","py":"bò","duan":[{"e":"撝也。","n":"禮記。燔黍捭豚。釋文云。捭？麥反。注作擗。又作擘。皆同。按卑聲辟聲皆在十六部。故記作捭。注作擘。今注亦作捭矣。擘豚、謂手裂豚肉也。又周禮瓬人注曰。薜讀如藥黃檗之檗。破裂也。按薜乃擘之叚借。西京賦云。剖析豪釐。擘肌分理。李善引周禮注作擘。豈其所據與今不同歟。內則曰。塗皆乾擘之。喪大記。絞一幅不辟。內則。麕爲辟雞。皆假辟爲擘也。若孟子以仲子爲巨擘。巨擘、謂手大指也。凡大指主開。餘四指主合。故謂之巨擘。"}]},"撝":{"expl":"裂也。从手爲聲。一曰手指也。","rad":"手","fq":"許歸切","vol":"12","py":"huī","duan":[{"e":"裂也。","n":"易。撝謙。馬曰。撝猶離也。按撝謙者、溥散其謙。無所往而不用謙。裂義之引申也。曲禮。爲國君削瓜者華之。注曰。華、中裂之也。華音如花。撝古音如呵。故知華卽撝之叚借也。"}]},"捇":{"expl":"裂也。从手赤聲。","rad":"手","fq":"呼麥切","vol":"12","py":"huò","duan":[{"e":"裂也。","n":"周禮有赤犮氏。注云。赤犮猶捇拔也。捇拔、葢漢時有此語。"}]},"扐":{"expl":"《易》筮，再扐而後卦。从手力聲。","rad":"手","fq":"盧則切","vol":"12","py":"lè","duan":[{"e":"易𥷂再扐而後卦。","n":"易繫辭傳文也。卦今易作掛。釋文云。京作卦。云再扐而後布卦。葢許同京也。大衍之數五十。其用四十有九。分而爲二以象兩。掛一以象三。揲之以四以象四時。歸奇於扐以象閏。五歲再閏。故再扐而後掛。虞翻曰。奇、所掛一策。扐、所揲之餘。不一則二。不三則四。取奇以歸扐。扐幷合掛左手之小指。爲一扐、則似閏月定四時成歲。故歸奇於扐以象閏者也。巳一扐、復分掛如初揲之。歸奇於初扐。幷掛左手次小指閒。爲再扐、則再閏也。又分扐揲之如初。而掛左手苐三指閒。成一變、則布卦之一爻。謂巳二扐、又加一爲三。幷重合前二扐爲五歲。故五歲再閏。再扐而後掛。據虞則字作掛者、謂再爲分二掛一。或作卦者、謂於此起卦爻。皆可通也。凡數之餘曰扐。王制"}]},"技":{"expl":"巧也。从手支聲。","rad":"手","fq":"渠綺切","vol":"12","py":"jì","duan":[{"e":"巧也。","n":"工部曰。巧者、技也。二篆爲轉注。古多叚伎爲技能字。人部曰。伎、與也。"}]},"摹":{"expl":"規也。从手莫聲。","rad":"手","fq":"莫胡切","vol":"12","py":"mó","duan":[{"e":"規也。","n":"規者、有法度也。以注度度之亦曰規。廣韵曰。摹者、以手摹也。楊雄傳。參摹而四分之。三摹九据。或手在旁作摸。今人謂之摸𢱢。讀入聲。實一字。摹與模義略同。韵會此下有謂所規倣也五字。葢庾儼黙注語之存者。倣當作放。"}]},"拙":{"expl":"不巧也。从手出聲。","rad":"手","fq":"職說切","vol":"12","py":"zhuō","duan":[{"e":"不巧也。","n":"不能爲技巧也。"}]},"㧺":{"expl":"縫指㧺也。一曰韜也。从手沓聲。讀若眔。","rad":"手","fq":"徒合切","vol":"12","py":"tà","duan":[{"e":"縫指㧺也。","n":"縫指㧺者、謂以鍼紩衣之人恐鍼之栔其指。用韋爲箍韜於指以藉之也。㧺之言重沓也。射韝亦謂之臂㧺。"}]},"摶":{"expl":"圜也。从手專聲。","rad":"手","fq":"度官切","vol":"12","py":"tuán","duan":[{"e":"㠯手圜之也。","n":"各本作圜也。語不完。今依韵會所據補。以手圜之者、此篆之本義。如禮經云摶黍、曲禮云摶飯是也。因而凡物之圜者曰摶。如考工記摶以行石、摶身而鴻、相笴欲生而摶是也。俗字作團。古亦借爲專壹字。左傳云若琴瑟之摶壹、秦瑯邪臺刻石曰摶心揖志是也。專壹、許女部作嫥壹。"}]},"㨡":{"expl":"手推之也。从手圂聲。","rad":"手","fq":"戶骨切","vol":"12","py":"hú","duan":[{"e":"手推之也。从手。圂聲。","n":"戶骨切。十三十五部。"}]},"㘈":{"expl":"小兒有知也。从口疑聲。《詩》曰：“克岐克㘈。”","rad":"口","fq":"魚力切","vol":"02","py":"yì","duan":[{"e":"小兒有知也。","n":"大雅。克岐克嶷。毛曰。岐、知意也。嶷、識也。按此由俗人不識㘈字。蒙上岐字改从山旁耳。高注淮南曰。軫？之？、讀如克岐克㘈之㘈。太玄作懝。釋文懝牛力切。又音擬。擬然有所識別也。"}]},"捄":{"expl":"盛土於梩中也。一曰擾也。《詩》曰：“捄之陾陾。”从手求聲。","rad":"手","fq":"舉朱切","vol":"12","py":"jū","duan":[{"e":"盛土於梩中也。","n":"木部曰。㭒者、徙土輂也。或作梩。大雅。捄之陑陑。傳曰。捄、虆也。陑陑、眔也。箋云。築牆者捊聚壤土。盛之以虆而投諸版中。孟子虆梩竝言。趙曰。虆梩、籠臿之屬。可以取土者也。許說專爲釋大雅而言。"}]},"拮":{"expl":"手口共有所作也。从手吉聲。《詩》曰：“予手拮据。”","rad":"手","fq":"古屑切","vol":"12","py":"jié","duan":[{"e":"口手共有所作也。","n":"豳風。予手拮据。傳曰。拮据、撠挶也。手病口病故能免於大鳥之難。韓詩曰。口足爲事曰拮据。韓之足、卽毛之手也。許葢合毛韓爲此訓。"}]},"搰":{"expl":"掘也。从手骨聲。","rad":"手","fq":"戶骨切","vol":"12","py":"hú","duan":[{"e":"掘也。","n":"吳語。夫諺曰。狐埋之而狐搰之。是以無成功。韋注。搰、發也。玉篇云。左傳搰褚師定子之墓。本亦作掘。"}]},"掘":{"expl":"搰也。从手屈聲。","rad":"手","fq":"衢勿切","vol":"12","py":"jué","duan":[{"e":"搰也。","n":"二篆㬪韵轉注。按凡字書、韵書謂掘亦作闕者、似是而非也。左傳。闕地及泉。闕地下冰而牀焉。國語。闕爲深溝。通於商魯之閒。韋云。闕、穿也。凡云闕者、皆謂空之。與掘義別。"}]},"掩":{"expl":"斂也。小上曰掩。从手奄聲。","rad":"手","fq":"衣檢切","vol":"12","py":"yǎn","duan":[{"e":"斂也小上曰掩","n":"釋器。圜弇上謂之鼒。弇上當作掩上。"}]},"摡":{"expl":"滌也。从手旣聲。《詩》曰：“摡之釜鬵。”","rad":"手","fq":"古代切","vol":"12","py":"ɡài","duan":[{"e":"滌也。","n":"滌者、洒也。洒先禮切。詩。摡之釡鬵。傳曰。摡、滌也。今本作溉者、非。凡周禮、禮經摡字本皆从手。釋文不誤。而俗本多譌。"}]},"揟":{"expl":"取水沮也。从手胥聲。武威有揟次縣。","rad":"手","fq":"相居切","vol":"12","py":"xū","duan":[{"e":"取水沮也。","n":"沮玉篇、廣韵作具非也。取水之具或以木、或以瓦缶。則製字不當从手矣。沮今之渣字。集韵九麻曰。？、滓也。亦作渣。取水渣者、必浚之漉之。如釃酒然。然則揟與水部之湑音義皆同。今所謂濾水也。周禮謂伺捕盜賊爲胥、亦此意。淺人不得其解。遂改沮爲具。非製字之意。"}]},"播":{"expl":"穜也。一曰布也。从手番聲。","rad":"手","fq":"補過切","vol":"12","py":"bō","duan":[{"e":"穜也。","n":"穜者、𡎐也。𡎐者、穜也。堯典曰。播時百榖。"}]},"挃":{"expl":"穫禾聲也。从手至聲。《詩》曰：“穫之挃挃。”","rad":"手","fq":"陟栗切","vol":"12","py":"zhì","duan":[{"e":"穫禾聲也。","n":"周頌良耜曰。擭之挃挃。傳曰。挃挃、穫聲也。"}]},"㨖":{"expl":"剌也。从手致聲。一曰剌之財至也。","rad":"手","fq":"陟利切","vol":"12","py":"zhì","duan":[{"e":"刺也。","n":"刺者、直傷也。方言曰。㨖、到也。廣雅曰。㨖、至也。"}]},"旁":{"expl":"溥也。从二，闕；方聲。","rad":"丄","fq":"步光切","vol":"01","py":"pánɡ","duan":[{"e":"溥也。","n":"司馬相如封禪文曰。㫄魄四塞。張揖曰。㫄、衍也。廣雅曰。㫄、大也。按㫄讀如𣶢。與溥雙聲。後人訓側。其義偏矣。"}]},"皇":{"expl":"大也。从自。自，始也。始皇者，三皇，大君也。自，讀若鼻，今俗以始生子爲鼻子。","rad":"王","fq":"胡光切","vol":"01","py":"huánɡ","duan":[{"e":"大也。","n":"見詩毛傳。"}]},"咳":{"expl":"小兒笑也。从口亥聲。","rad":"口","fq":"戶來切","vol":"02","py":"hái","duan":[{"e":"小兒𥬇也。","n":"內則云。孩而名之。爲作小兒𥬇而名之也。"}]},"扤":{"expl":"動也。从手兀聲。","rad":"手","fq":"五忽切","vol":"12","py":"wù","duan":[{"e":"動也。","n":"詩正月。天之扤我。傳曰。扤、動也。考工記。是以大扤。"}]},"抈":{"expl":"折也。从手月聲。","rad":"手","fq":"魚厥切","vol":"12","py":"yuè","duan":[{"e":"㪿也。","n":"晉語。其爲本也固矣。故不可抈也。韋云。抈、動也。按依韋注、是謂此抈爲扤之叚借字也。其本義則訓折。舊音云抈音月。又五？反。"}]},"摎":{"expl":"縛殺也。从手翏聲。","rad":"手","fq":"居求切","vol":"12","py":"jiū","duan":[{"e":"縛殺也。","n":"縳殺者、以束縛殺之也。凡縣死者曰縊。亦曰雉經。凡以繩帛等物殺人者曰縛殺。亦曰摎。亦曰絞。廣韵曰。摎者、絞縛殺也。多絞字爲長。今之絞罪、卽古所謂摎也。引申之、凡繩帛等物二股互交皆得曰摎、曰絞。亦曰糾。喪服曰。絞帶。又曰。殤之絰、不摎垂。注云。不絞其帶之垂者。周禮、襍記注皆云。環絰者一股纏而不糾。丩部曰。糾、三合繩也。檀弓作繆絰。繆卽摎之叚借。故注云繆讀爲不摎垂之摎也。喪服及檀弓注摎垂字、今本譌爲樛木之樛。遂不可通矣。惟玉篇不誤。"}]},"撻":{"expl":"鄉飲酒，罰不敬，撻其背。从手達聲。","rad":"手","fq":"他達切","vol":"12","py":"tà","duan":[{"e":"鄉㱃酒罰不敬。撻其背。","n":"周禮閭胥。凡事掌其比。觵撻罰之事。故書或言觵撻之罰事。鄭云。觵撻者、失禮之罰。觵用酒。其爵以兕角爲之。撻、扑也。按鄭但云失禮。許必系之鄉飲酒者、禮莫大於此。惟此可登時行觵撻也。"}]},"掕":{"expl":"止馬也。从手夌聲。","rad":"手","fq":"里甑切","vol":"12","py":"línɡ","duan":[{"e":"止馬也。","n":"掕馬、猶勒馬也。疑易拯馬壯、拯乃掕之叚借。"}]},"抨":{"expl":"撣也。从手平聲。","rad":"手","fq":"普耕切","vol":"12","py":"pēnɡ","duan":[{"e":"彈也。","n":"彈大徐誤作撣。今依小徐及玄應正。彈者、開弓也。開弓者、弦必反於直。故凡有所糾正謂之彈。廣雅曰。彈、拼也。拼卽抨。布莖切。玄應曰。抨彈、繩墨也。補耕切。又普耕切。江南音也。按孟康漢書注曰。引繩以抨彈。"}]},"捲":{"expl":"气勢也。从手卷聲。《國語》曰：“有捲勇。”一曰捲，收也。","rad":"手","fq":"巨員切","vol":"12","py":"quán","duan":[{"e":"气埶也。","n":"謂作气有勢也。此與拳音同而義異。小雅巧言。無拳無勇。毛傳曰。拳、力也。齊語。桓公問曰。於子之鄉。有拳勇股肱之力秀出於衆者。韋云。大勇爲拳。此皆叚拳爲捲。葢與古本字異。齊風箋云。㩲、勇壯也。㩲者、捲之異體。"}]},"扱":{"expl":"收也。从手及聲。","rad":"手","fq":"楚洽切","vol":"12","py":"xī","duan":[{"e":"收也。","n":"收者、捕也。曲禮。以箕自鄉而扱之。此扱之本義也。儀禮注云。扱柶。此插之叚借字也。"}]},"摷":{"expl":"拘擊也。从手巢聲。","rad":"手","fq":"子小切","vol":"12","py":"jiǎo","duan":[{"e":"拘擊也。","n":"拘止而擊之也。集韵、類篇作擊也。拘也。非是。又謂此卽鈔之別體。亦非許意也。以下十七篆皆言擊、而冣後釋擊曰扑也。許書文法往往如是。"}]},"挨":{"expl":"擊背也。从手矣聲。","rad":"手","fq":"於駴切","vol":"12","py":"āi","duan":[{"e":"擊背也。","n":"列子。攩㧙挨抌。張注曰。烏駭反。推也。"}]},"嗛":{"expl":"口有所銜也。从口兼聲。","rad":"口","fq":"戶監切","vol":"02","py":"xián","duan":[{"e":"口有所銜也。","n":"夏小正曰。田鼠者、嗛鼠也。爾雅鼸鼠。古本亦作嗛。故孫叔然云。嗛者、頰裏也。廣韵曰。嗛、蝯藏食處也。嗛鼠食積於頰。人食似之。故頰車或曰鼸車。假借爲銜字。如佞幸傳大后由此嗛韓嫣是也。亦假借爲歉字。商銘嗛嗛之食、嗛嗛之德是也。亦假借爲謙字。如子夏周易、漢藝文志謙卦作嗛是也。志云。合於易之嗛嗛。一嗛而四益。轉寫下句从言。遂滋異說。"}]},"撲":{"expl":"挨也。从手菐聲。","rad":"手","fq":"蒲角切","vol":"12","py":"pū","duan":[{"e":"挨也。","n":"撲與扑㯷、義皆別。今人溷之。廣韵一屋云。拂箸。今義也。"}]},"𢶡":{"expl":"㫄擊也。从手敫聲。","rad":"手","fq":"苦弔切","vol":"12","py":"qiào","duan":[{"e":"旁擊也。","n":"公羊傳曰。公怒。以斗摮而殺之。注。摮猶？也。𢶡謂旁擊頭項。莊子。撽以馬捶。"}]},"扚":{"expl":"疾擊也。从手勺聲。","rad":"手","fq":"都了切","vol":"12","py":"diǎo","duan":[{"e":"疾擊也。","n":"疾速擊之也。史記天官書扚雲。索隱曰。劉氏音時酌反。說文音丁了反。許愼注淮南云。扚、引也。按扚雲从手。今本譌从木。"}]},"抶":{"expl":"笞擊也。从手失聲。","rad":"手","fq":"勑栗切","vol":"12","py":"chì","duan":[{"e":"笞擊也。","n":"笞所以擊也。抶之見左傳者多矣。"}]},"扺":{"expl":"側擊也。从手氏聲。","rad":"手","fq":"諸氏切","vol":"12","py":"zhǐ","duan":[{"e":"側擊也。","n":"戰國策。扺掌而談。東京賦。扺璧於谷。解嘲。介涇陽。扺穰矦。按扺字今多譌作抵。其音義皆殊。國策。夏無且以藥囊提荆軻。史記。薄太后以冒絮提文帝。提皆扺之叚借字也。"}]},"抰":{"expl":"以車鞅擊也。从手央聲。","rad":"手","fq":"於兩切","vol":"12","py":"yǎnɡ","duan":[{"e":"㠯車鞅擊也。","n":"鞅者、馬頸靼也。鞅抰㬪韵。"}]},"㨐":{"expl":"衣上擊也。从手𠈃聲。","rad":"手","fq":"方苟切","vol":"12","py":"bǔ","duan":[{"e":"衣上擊也。","n":"擊集韵、類篇皆作攴。攴者、小擊也。"}]},"捭":{"expl":"兩手擊也。从手卑聲。","rad":"手","fq":"北買切","vol":"12","py":"bǎi","duan":[{"e":"㒳手擊也。","n":"謂左右㒳手橫開旁擊也。引申之爲鬼谷子之捭？。捭之者、開也。？之者、閉也。禮記。燔黍捭豚。叚捭爲擘字。"}]},"捶":{"expl":"以杖擊也。从手垂聲。","rad":"手","fq":"之壘切","vol":"12","py":"chuí","duan":[{"e":"㠯杖擊也。","n":"內則注曰。捶、擣之也。引申之、杖得名捶。猶小擊之曰扑、因而擊之之物得曰扑也。擊馬者曰箠。"}]},"搉":{"expl":"敲擊也。从手隺聲。","rad":"手","fq":"苦角切","vol":"12","py":"què","duan":[{"e":"㪣擊也。","n":"㪣、横撾也。撾卽？之？變。㩁與㪣㬪韵。又雙聲也。廣雅曰。揚搉、都凡也。別一義。"}]},"咀":{"expl":"含味也。从口且聲。","rad":"口","fq":"慈呂切","vol":"02","py":"jǔ","duan":[{"e":"含味也。","n":"含而味之。凡湯酒膏藥舊方皆云㕮咀。廣韵九麌云。㕮咀、嚼也。按㕮卽哺字。古父甫通用。後人不知爲一字矣。含味之上似當有哺咀二字。"}]},"摬":{"expl":"中擊也。从手竟聲。","rad":"手","fq":"一敬切","vol":"12","py":"yǐnɡ","duan":[{"e":"中擊也。","n":"擊之而中也。中玉篇作傷。"}]},"拂":{"expl":"過擊也。从手弗聲。","rad":"手","fq":"𢾭物切","vol":"12","py":"fú","duan":[{"e":"過擊也。","n":"徐鍇曰。擊而過之也。刀部曰。刜、擊也。與拂義同。"}]},"摼":{"expl":"擣頭也。从手堅聲。讀若“鏗尔舍瑟而作”。","rad":"手","fq":"口莖切","vol":"12","py":"kēnɡ","duan":[{"e":"擣頭也。","n":"廣韵曰。撞也。"}]},"抌":{"expl":"深擊也。从手冘聲。讀若告言不正曰抌。","rad":"手","fq":"竹甚切","vol":"12","py":"dǎn","duan":[{"e":"𥥍擊也。","n":"深淺字許作𥥍。抌深㬪韵字。刺客列傳。左手把其袖。右手揕其匈。揕卽抌字。徐廣曰。一作抗。按抗乃抌之譌耳。"}]},"㩓":{"expl":"傷擊也。从手、毀，毀亦聲。","rad":"手","fq":"許委切","vol":"12","py":"huǐ","duan":[{"e":"傷擊也。","n":"傷擊者、擊之而傷也。故其字从手毁。"}]},"擊":{"expl":"攴也。从手毄聲。","rad":"手","fq":"古歴切","vol":"12","py":"jī","duan":[{"e":"攴也。","n":"攴下曰。小擊也。二篆爲轉注。攴訓小擊。擊則兼大小言之。而但云攴也者、於攴下見析言之理。於擊下見渾言之理。互相足也。攴之？變爲扑。手卽又也。又下曰手也。因之鞭箠等物皆謂之扑。此經典扑字之義也。咎繇謨古文戛擊、今文尙書擊爲隔。同音叚借。"}]},"扞":{"expl":"忮也。从手干聲。","rad":"手","fq":"矦旰切","vol":"12","py":"hàn","duan":[{"e":"忮也。","n":"忮當作枝。枝持字古書用枝、亦用支。許之字例則當作榰。許之榰柱、他書之搘拄也。攴部？下云。止也。扞義當略同。忮訓很、非其義。周南干城傳曰。干、扞也。左傳亦以扞城其民釋干城。孫炎以自蔽扞釋爾雅扞字。許盾下云。所以扞身蔽目。然則扞字之訓可定矣。廣韵扞下曰。以手扞。又衞也。玉篇亦曰。扞、衞也。字亦作捍。祭法。能禦大災。能捍大患。則祀之。魯語作扞。"}]},"抗":{"expl":"扞也。从手亢聲。","rad":"手","fq":"苦浪切","vol":"12","py":"kànɡ","duan":[{"e":"扞也。","n":"旣夕禮注曰。抗、禦也。左傳曰。以亢其讎。注云。亢猶當也。亢爲抗之叚借字。周禮。綱惡馬。注云。綱讀爲以亢其讎之亢。書亦或爲亢。亢、禦也。禁也。綱亦亢之、叚借字也。引申之義爲高抗。旣夕注曰。抗、舉也。"}]},"捕":{"expl":"取也。从手甫聲。","rad":"手","fq":"薄故切","vol":"12","py":"bǔ","duan":[{"e":"取也。","n":"此與搏義別。"}]},"簎":{"expl":"剌也。从手，籍省聲。《周禮》曰：“簎魚鼈。”","rad":"手","fq":"士革切","vol":"12","py":"cè","duan":[{"e":"刺也。","n":"刺者、直傷也。周禮鼈人。以時簎魚鼈龜蜃。鄭司農云。簎謂以杈刺泥中搏取之。魯語。里革曰。鳥獸孕。水蟲成。獸虞於是乎禁罝羅。矠魚鼈以爲夏槁。韋云。矠、𢳇也。𢳇刺魚鼈。按矠本矛屬。此叚借矠爲簎也。許所據國語作簎。與周禮同。"}]},"啜":{"expl":"嘗也。从口叕聲。一曰喙也。","rad":"口","fq":"昌說切","vol":"02","py":"chuò","duan":[{"e":"嘗也。","n":"孟子。徒餔啜也。"}]},"撚":{"expl":"執也。从手然聲。一曰蹂也。","rad":"手","fq":"乃殄切","vol":"12","py":"niǎn","duan":[{"e":"𡙕也。","n":"執者、捕罪人也。引申爲凡持取之偁。廣韵曰。撚者、以手撚物也。"}]},"挂":{"expl":"畫也。从手圭聲。","rad":"手","fq":"古賣切","vol":"12","py":"ɡuà","duan":[{"e":"畫也。","n":"畫葉本作宣。李文仲字鑑亦作宣。六書故云唐本作縣。玉篇亦作懸也。特牲禮曰。實于左袂。挂于季指。卒角。鄭云。挂袪以小指者、便卒角也。易毄辭傳。分而爲二以象㒳。掛一以象三。孔疏曰。掛其一於冣小指閒。皆有縣義合。古本多作畫者。此等皆有分別畫出之意。陸德明云。掛、別也。後人乃云懸挂。俗製掛字耳。許訓畫者、古義㬪韵爲訓。唐本訓縣、非古也。禮注云。古文掛作卦。"}]},"拕":{"expl":"曳也。从手它聲。","rad":"手","fq":"託何切","vol":"12","py":"tuō","duan":[{"e":"曳也。","n":"申部曰。束縛捽抴爲臾。又曰。曳者、臾曳也。然則曳之義略同抴。一說曳本作抴。後人避諱改之。南越傳。拕舟而入水。論語。加朝服扡紳。易。終朝三褫之。鄭本作拕。叚拕爲褫也。高誘注淮南遇盜拕其衣云。拕、奪也。"}]},"捈":{"expl":"臥引也。从手余聲。","rad":"手","fq":"同都切","vol":"12","py":"tú","duan":[{"e":"臥引也。","n":"臥引謂横而引之也。廣雅曰。捈、舒也。"}]},"抴":{"expl":"捈也。从手世聲。","rad":"手","fq":"余制切","vol":"12","py":"yè","duan":[{"e":"捈也。","n":"？下曰。抴也。臾下曰。束縛捽抴也。抴與曳音義皆同。檀弓。負手曳杖。釋文。曳作抴。俗刻誤从木。非也。九歌。桂擢兮蘭抴。王逸曰。擢、楫也。抴、船旁板也。按毛詩傳云。楫所以擢舟也。故因謂楫爲擢。擢者、引也。船旁板曳於水中。故因謂之抴。俗字作櫂、作枻。皆非是也。"}]},"揙":{"expl":"撫也。从手扁聲。","rad":"手","fq":"婢沔切","vol":"12","py":"biàn","duan":[{"e":"搏也。从手。扁聲。","n":"婢沔切。古音在十二部。"}]},"撅":{"expl":"从手有所把也。从手厥聲。","rad":"手","fq":"居月切","vol":"12","py":"juē","duan":[{"e":"㠯手有所杷也。","n":"以各本誤从。杷各本誤把。今正。杷本訓收麥器。引申之用手捊聚亦曰杷。通俗文曰。手杷曰掊。手把曰攫。此杷與把之別也。內則。不涉不撅。撅、揭衣也。撅之義與掘不同。韵書淆之。非也。"}]},"攎":{"expl":"挐持也。从手盧聲。","rad":"手","fq":"洛乎切","vol":"12","py":"lú","duan":[{"e":"拏持也。","n":"拏各本作挐。誤。廣韵攎下云。攎、斂。"}]},"挐":{"expl":"持也。从手如聲。","rad":"手","fq":"女加切","vol":"12","py":"ná","duan":[{"e":"牽引也。从手。如聲。","n":"按各本篆作拏。解作奴聲。別有挐篆。解云持也。从手如聲。女加切。二篆形體互譌。今正。挐字見於經者、僖元年𫉬莒挐。三傳之經所同也。其義則宋玉九辯曰。枝煩挐而交横。王注。柯條糾錯而崱嶷。招䰟。稻秶穱麥。挐黃𥹭些。王注。挐、糅也。王逸九思殽亂兮紛挐注。君任佞巧。競疾忠信。交亂紛挐也。左思吳都賦。攢柯挐莖。李注曰。許愼注淮南子云。挐、亂也。凡若此等皆於牽引義爲近。而漢霍去病傳。昏、漢匈奴相紛挐。此與九思紛挐同。謂漢與虜相亂也。而師古注乃云。紛挐、亂相持搏也。以亂釋紛。以相持搏釋挐。大非語意。竊意其時說文已同今本。故顔從而傅會耳。葢其字本如聲。讀女居切。其義爲牽引。廣韵九魚挐注牽引。未嘗作拏。說文拏訓持。"}]},"搵":{"expl":"没也。从手𥁕聲。","rad":"手","fq":"烏困切","vol":"12","py":"wèn","duan":[{"e":"𣳚也。","n":"𣳚者、湛也。謂湛浸於中也。集韵引字林搵抐、𣳚也。抐奴困切。"}]},"㗱":{"expl":"噍也。从口集聲。讀若集。","rad":"口","fq":"子入切","vol":"02","py":"jí","duan":[{"e":"噍也。","n":"也當作皃。"}]},"搒":{"expl":"掩也。从手㫄聲。","rad":"手","fq":"北孟切","vol":"12","py":"pénɡ","duan":[{"e":"掩也。","n":"廣韵曰。笞打。今義也。"}]},"挌":{"expl":"擊也。从手各聲。","rad":"手","fq":"古覈切","vol":"12","py":"ɡé","duan":[{"e":"擊也。","n":"凡今用格鬥字當作此。後漢陳寵傳。𣃔獄者急於篣挌酷烈之痛。注引此說文。周禮注曰。若今時無故入人室宅廬舍、上人車船、牽引人欲犯法者。其時格殺之。無罪。公羊定四年注曰。挾弓者、懷格意也。莊卅一年注。古者方伯征伐不道。諸矦交格而戰者。誅絕其國。此等格字皆當从手。"}]},"拲":{"expl":"兩手同械也。从手从共，共亦聲。《周禮》：“上辠，梏拲而桎。”","rad":"手","fq":"居竦切","vol":"12","py":"ɡǒnɡ","duan":[{"e":"㒳手共同械也。","n":"周禮掌囚。上罪梏拲而桎。鄭司農云。拲者、㒳手共一木也。"}]},"掫":{"expl":"夜戒守，有所擊。从手取聲。《春秋傳》曰：“賓將掫。”","rad":"手","fq":"子矦切","vol":"12","py":"zōu","duan":[{"e":"夜戒守有所擊也。","n":"一本無守字。有所擊、謂𡔷類也。襄廿五年左傳。陪臣干掫有淫者。杜云。干掫、行夜也。昭廿年傳。賓將掫。杜云。掫、行夜也。周禮鎛師、當固皆云。夜三？。杜子春云。謂擊𡔷行夜戒守也。春秋傳所謂賓將趣。趣與？音相近。許不云擊𡔷、而云有所擊者、凡有聲可警覺者皆是。若？、亦行夜所擊者也。"}]},"捐":{"expl":"棄也。从手肙聲。","rad":"手","fq":"與專切","vol":"12","py":"juān","duan":[{"e":"棄也。","n":"𠦒部曰。棄、捐也。二篆爲轉注。"}]},"掤":{"expl":"所以覆矢也。从手朋聲。《詩》曰：“抑釋掤忌。”","rad":"手","fq":"筆陵切","vol":"12","py":"bīnɡ","duan":[{"e":"所㠯覆矢也。","n":"鄭大叔于田傳曰。掤、所以覆矢也。左傳。公徒釋甲執冰而踞。冰者、掤之叚借字。賈逵、服䖍皆曰。冰、犢丸葢也。杜預云。或說犢丸是箭筩。其葢可以取飲。"}]},"扜":{"expl":"指麾也。从手亏聲。","rad":"手","fq":"億俱切","vol":"12","py":"yū","duan":[{"e":"𢫾𪎮也。","n":"𪎮各本作麾。俗。今正。扜𪎮爲雙聲。山海經曰。有人方扜弓射黃虵。"}]},"𪎮":{"expl":"旌旗，所以指麾也。从手靡聲。","rad":"手","fq":"許爲切","vol":"12","py":"huī","duan":[{"e":"旌旗。","n":"巾車曰。木路建大麾。鄭云。大麾不在九旗中。以正色言之則黑。夏后氏所建。按凡旌旗皆得曰？。故許以旌旗釋？。叚借之字作戲。淮陰矦傳、項羽本紀皆曰戲下是也。"}]},"捷":{"expl":"獵也。軍獲得也。从手疌聲。《春秋傳》曰：“齊人來獻戎捷。”","rad":"手","fq":"疾葉切","vol":"12","py":"jié","duan":[{"e":"獵也。","n":"以㬪韵爲訓。謂如逐禽而得之也。"}]},"扣":{"expl":"牽馬也。从手口聲。","rad":"手","fq":"丘后切","vol":"12","py":"kòu","duan":[{"e":"牽馬也。","n":"周禮田僕。凡田、王提馬而走。諸矦晉。大夫馳。注曰。提猶舉也。晉猶抑也。使人扣而舉之抑之皆止奔也。馳放不扣。史記。伯夷、叔齊扣馬而諫。"}]},"嚌":{"expl":"嘗也。从口齊聲。《周書》曰：“大保受同祭嚌。”","rad":"口","fq":"在詣切","vol":"02","py":"jì","duan":[{"e":"嘗也。","n":"見儀禮。"}]},"掍":{"expl":"同也。从手昆聲。","rad":"手","fq":"古本切","vol":"12","py":"hùn","duan":[{"e":"同也。","n":"方言。掍、同也。宋衞之閒或曰掍。漢人賦多用掍字。"}]},"𢯱":{"expl":"眾意也。一曰求也。从手叜聲。《詩》曰：“束矢其𢯱。”","rad":"手","fq":"所鳩切","vol":"12","py":"sōu","duan":[{"e":"衆意也。","n":"其意爲衆。其言爲𢯱也。魯頌泮水曰。束矢其搜。傳曰。五十矢爲束搜。衆意也。此古義也。與考工記注之藪略同。鄭司農云。藪讀爲蜂藪之藪。後鄭云。蜂藪者、衆輻之所趨也。"}]},"換":{"expl":"易也。从手奐聲。","rad":"手","fq":"胡玩切","vol":"12","py":"huàn","duan":[{"e":"易也。从手。奐聲。","n":"胡玩切。十四部。"}]},"掖":{"expl":"以手持人臂投地也。从手夜聲。一曰臂下也。","rad":"手","fq":"羊益切","vol":"12","py":"yè","duan":[{"e":"㠯手持人臂也。","n":"各本臂下有投地二字。今依左傳音義刪正。左傳。衛人伐邢。二禮從國子巡城。掖以赴外。殺之。赴當是仆之誤。正義曰。說文云。掖、持臂也。謂執持其臂投之城外也。釋文曰。說文云以手持人臂曰掖。陸孔所據皆無投地二字。淺人傅合左文增之。不知掖人者不必皆投地也。詩衡門序曰。僖公愿而無立志。故作是詩以誘掖其君。鄭云。掖、扶持也。是可證矣。"}]},"摦":{"expl":"橫大也。从手瓠聲。","rad":"手","fq":"胡化切","vol":"12","py":"huà","duan":[]},"攙":{"expl":"剌也。从手毚聲。","rad":"手","fq":"楚銜切","vol":"12","py":"chān","duan":[]},"搢":{"expl":"插也。从手晉聲。搢紳前史皆作薦紳。","rad":"手","fq":"卽刃切","vol":"12","py":"jìn","duan":[]},"掠":{"expl":"奪取也。从手京聲。本音亮。《唐韻》或作擽。","rad":"手","fq":"離灼切","vol":"12","py":"lüè","duan":[]},"掐":{"expl":"爪刺也。从手臽聲。","rad":"手","fq":"苦洽切","vol":"12","py":"qiā","duan":[]},"捻":{"expl":"指捻也。从手念聲。","rad":"手","fq":"奴協切","vol":"12","py":"niē","duan":[]},"噍":{"expl":"齧也。从口焦聲。","rad":"口","fq":"才肖切","vol":"02","py":"jiào","duan":[{"e":"齧也。","n":"少儀。侍食於君子。小飯而亟之。數噍。按數噍句絶。所謂亟之也。"}]},"拗":{"expl":"手拉也。从手幼聲。","rad":"手","fq":"於絞切","vol":"12","py":"ǎo","duan":[]},"摵":{"expl":"捎也。从手戚聲。","rad":"手","fq":"沙劃切","vol":"12","py":"shè","duan":[]},"捌":{"expl":"方言云：無齒杷。从手別聲。","rad":"手","fq":"百轄切","vol":"12","py":"bā","duan":[]},"攤":{"expl":"開也。从手難聲。","rad":"手","fq":"他干切","vol":"12","py":"tān","duan":[]},"抛":{"expl":"棄也。从手从尤从力，或从手𠠵聲。案：《左氏傳》通用摽。《詩》：“摽有梅。”摽，落也。義亦同。","rad":"手","fq":"匹交切","vol":"12","py":"pāo","duan":[]},"摴":{"expl":"舒也。又，摴蒲，戲也。从手雩聲。","rad":"手","fq":"丑居切","vol":"12","py":"chū","duan":[]},"打":{"expl":"擊也。从手丁聲。","rad":"手","fq":"都挺切","vol":"12","py":"dǎ","duan":[]},"𠦬":{"expl":"背呂也。象脅肋也。凡𠦬之屬皆从𠦬。","rad":"𠦬","fq":"古懷切","vol":"12","py":"ɡuāi","duan":[{"e":"背呂也。","n":"呂下曰。脊骨也。脊兼骨肉言之。呂則其骨。析言之如是。渾言之、則統曰背呂。猶俗云背脊也。"}]},"脊":{"expl":"背呂也。从𠦬从肉。","rad":"𠦬","fq":"資昔切","vol":"12","py":"jǐ","duan":[{"e":"背呂也。","n":"釋名曰。脊、積也。積續骨節脈絡上下也。"}]},"女":{"expl":"婦人也。象形。王育說。凡女之屬皆从女。","rad":"女","fq":"尼呂切","vol":"12","py":"nǚ","duan":[{"e":"婦人也。","n":"男、丈夫也。女、婦人也。立文相對。喪服經每以丈夫婦人連文。渾言之女亦婦人。析言之適人乃言婦人也。左傳曰。君子謂宋共姬女而不婦。女待人。婦義事也。此可以知女道婦道之有不同者矣。言女子者對男子而言。子皆美偁也。曰女子子者、系父母而言也。集韵曰。吳人謂女爲娪。牛居切。靑州呼女曰娪。五故切。楚人謂女曰女。奴解切。皆方語也。"}]},"吮":{"expl":"欶也。从口允聲。","rad":"口","fq":"徂沇切","vol":"02","py":"shǔn","duan":[{"e":"欶也。","n":"欠部云。欶、吮也。"}]},"姓":{"expl":"人所生也。古之神聖母，感天而生子，故稱天子。从女从生，生亦聲。《春秋傳》曰：“天子因生以賜姓。”","rad":"女","fq":"息正切","vol":"12","py":"xìnɡ","duan":[{"e":"人所生也。","n":"白虎通曰。姓者、生也。人所稟天氣所以生者也。吹律定姓。故姓有百。按詩振振公姓傳曰。公姓、公生也。不如我同姓傳曰。同姓、同祖也。昭四年左傳。問其姓。釋文云。女生曰姓。姓謂子也。定四年蔡大夫公孫生、公穀皆作公孫姓。"}]},"姜":{"expl":"神農居姜水，以爲姓。从女羊聲。","rad":"女","fq":"居良切","vol":"12","py":"jiānɡ","duan":[{"e":"神農凥姜水。因㠯爲姓。","n":"晉語。司空季子曰。昔少典娶于有蟜氏。生黃帝、炎帝。黃帝以姬水成。炎帝以姜水成。成而異德。故黃帝爲姬。炎帝爲姜。韋注。成、謂所生長以成功也。渭水篇注曰。岐水又東逕姜氏城南爲姜水。引帝王世紀炎帝神農氏姜姓。母女登遊華陽。感神而生炎帝。長於姜水是其地。按姜姬字、葢後所製。"}]},"姬":{"expl":"黃帝居姬水，以爲姓。从女𦣞聲。","rad":"女","fq":"居之切","vol":"12","py":"jī","duan":[{"e":"黃帝凥姬水。因水爲姓。从女。𦣞聲。","n":"居之切。一部。"}]},"姞":{"expl":"黃帝之後百䱔姓，后稷妃家也。从女吉聲。","rad":"女","fq":"巨乙切","vol":"12","py":"jí","duan":[{"e":"黃帝之後伯䱔姓也。","n":"國語。晉胥臣臼季曰。黃帝之子、得姓者十四人爲十二姓。姞其一也。詩都人士作吉。南燕、密須、姞姓國也。"}]},"嬴":{"expl":"少昊氏之姓也。从女，羸省聲。","rad":"女","fq":"以成切","vol":"12","py":"yínɡ","duan":[{"e":"帝少暤之姓也。","n":"按秦、徐、江、黃、郯、莒皆嬴姓也。嬴地理志作盈。又按伯翳嬴姓。其子皋陶偃姓。偃嬴、語之轉耳。如娥皇女英、世本作女瑩。大戴禮作女匽。亦一語之轉。"}]},"姚":{"expl":"虞舜居姚虛，因以爲姓。从女兆聲。或爲姚，嬈也。《史篇》以爲：姚，易也。","rad":"女","fq":"余招切","vol":"12","py":"yáo","duan":[{"e":"虞舜凥姚虛。因㠯爲姓。","n":"帝王世紀云。舜母名握登。生舜於姚墟。因姓姚氏也。世本。舜姓姚氏。"}]},"嬀":{"expl":"虞舜居嬀汭，因以爲氏。从女爲聲。","rad":"女","fq":"居爲切","vol":"12","py":"ɡuī","duan":[{"e":"虞舜凥嬀汭。因㠯爲氏。","n":"氏各舊本及集韵、類篇皆同。毛斧季剜改爲姓。非也。舜旣姚姓、則嬀爲舜後之氏可知。按依史記當云因以爲氏姓。尋姓氏之禮。姓統於上。氏別於下。鄭駁五經異義曰。天子賜姓命氏。諸侯命族。族者氏之別名。姓者所以統繫百世不別也。氏者所以別子孫之所出。故世本之篇言姓則在上。言氏則在下也。此由姓而氏之說也。旣別爲氏、則謂之氏姓。故風俗通、潛夫論皆以氏姓名篇。諸書多言氏姓。氏姓之見於經者、春秋隱九年天王使南季來聘。穀梁傳曰。南、氏姓也。季字也。南爲逗。氏姓也三字爲句。此氏姓之明文也。史記陳杞世家。舜爲庶人時。堯妻之二女。居於嬀汭。其後因爲氏姓。姓嬀氏。五帝本紀曰。自黃帝至舜禹皆同姓。帝禹爲夏后而別氏姓。姓姒氏。今史"}]},"妘":{"expl":"祝融之後姓也。从女云聲。","rad":"女","fq":"王分切","vol":"12","py":"yún","duan":[{"e":"祝融之後姓也。","n":"祝融者、顓頊之子黎也。國語曰。其後八姓。已、董、彭、秃、妘、曹、斟、芈也。妘姓鄔、鄶、路、偪陽是也。又世本曰。鄅、妘姓也。大戴禮云鄶人。云卽妘字。"}]},"姺":{"expl":"殷諸侯爲亂，疑姓也。从女先聲。《春秋傳》曰：“商有姺邳。”","rad":"女","fq":"所臻切","vol":"12","py":"shēn","duan":[{"e":"殷諸侯爲亂。","n":"昭元年左傳曰。王伯之令也。猶不可壹。於是乎虞有三苗。夏有觀、扈。商有姺、邳。周有徐、奄。皆謂當時作亂之諸侯也。"}]},"㜣":{"expl":"人姓也。从女然聲。","rad":"女","fq":"奴見切","vol":"12","py":"niàn","duan":[{"e":"人姓也。","n":"廣韵曰。㜣、姓也。"}]},"𠻜":{"expl":"小㱃也。从口率聲。讀若㕞。","rad":"口","fq":"所劣切","vol":"02","py":"shuì","duan":[{"e":"小㱃也。","n":"士冠禮注曰。古文啐爲呼。按呼與啐音義皆隔。必是誤字。當是古文啐爲𠻜之誤。如古文酳作𨟴。今禮𨟴皆誤酌也。"}]},"𡚽":{"expl":"人姓也。从女丑聲。《商書》曰：“無有作𡚽。”","rad":"女","fq":"呼到切","vol":"12","py":"hào","duan":[{"e":"人姓也。","n":"廣韵、玉篇皆曰。妞、姓也。"}]},"娸":{"expl":"人姓也。从女其聲。杜林說：娸，醜也。","rad":"女","fq":"去其切","vol":"12","py":"qī","duan":[{"e":"人姓也。从女。其聲。","n":"去其切。一部。"}]},"奼":{"expl":"少女也。从女乇聲。","rad":"女","fq":"坼下切","vol":"12","py":"chà","duan":[{"e":"少女也。","n":"廣韵曰。美女。"}]},"媒":{"expl":"謀也，謀合二姓。从女某聲。","rad":"女","fq":"莫桮切","vol":"12","py":"méi","duan":[{"e":"謀也。","n":"以㬪韵爲訓。"}]},"妁":{"expl":"酌也，斟酌二姓也。从女勺聲。","rad":"女","fq":"市勺切","vol":"12","py":"shuò","duan":[{"e":"酌也。斟酌二姓者也。","n":"斟者、酌也。酌者、盛酒行觴也。斟酌二姓者、如挹彼注茲欲其調適也。孟子曰。不待父母之命。媒妁之言。"}]},"嫁":{"expl":"女適人也。从女家聲。","rad":"女","fq":"古訝切","vol":"12","py":"jià","duan":[{"e":"女適人也。","n":"白虎通曰。嫁者、家也。婦人外成以出適人爲家。按自家而出謂之嫁。至夫之家曰歸。喪服經謂嫁於大夫曰嫁。適士庶人曰適。此析言之也。渾言之皆可曰適。皆可曰嫁。"}]},"娶":{"expl":"取婦也。从女从取，取亦聲。","rad":"女","fq":"七句切","vol":"12","py":"qǔ","duan":[{"e":"取婦也。","n":"取彼之女爲我之婦也。經典多叚取爲娶。"}]},"婚":{"expl":"婦家也。《禮》：娶婦以昏時，婦人陰也，故曰婚。从女从昏，昏亦聲。","rad":"女","fq":"呼昆切","vol":"12","py":"hūn","duan":[{"e":"婦家也。","n":"釋親曰。婦之父爲婚。婦之黨爲婚兄弟。"}]},"姻":{"expl":"壻家也。女之所因，故曰姻。从女从因，因亦聲。","rad":"女","fq":"於眞切","vol":"12","py":"yīn","duan":[{"e":"壻家也。","n":"釋親曰。壻之父爲姻。婦之父母、壻之父母相謂爲婚姻。壻之黨爲姻兄弟。周禮。六行、孝友睦婣任恤。注云。婣者、親於外親。引申之義也。"}]},"妻":{"expl":"婦與夫齊者也。从女从屮从又。又，持事，妻職也。","rad":"女","fq":"七稽切","vol":"12","py":"qī","duan":[{"e":"婦與己齊者也。","n":"妻齊以㬪韵爲訓。此渾言之也。曲禮曰。庶人曰妻。析言之也。"}]},"嚵":{"expl":"小𠻜也。从口毚聲。一曰喙也。","rad":"口","fq":"士咸切","vol":"02","py":"chán","duan":[{"e":"小𠻜也。从口。毚聲。","n":"士或切。八部。"}]},"婦":{"expl":"服也。从女持帚灑掃也。","rad":"女","fq":"房九切","vol":"12","py":"fù","duan":[{"e":"服也。","n":"亦以㬪韵爲訓。婦主服事人者也。大戴禮本命曰。女子者、言如男子之敎而長其義理者也。故謂之婦人。婦人、伏於人也。是故無專制之義。有三從之道。曲禮曰。士之妃曰婦人。析言之也。"}]},"妃":{"expl":"匹也。从女己聲。","rad":"女","fq":"芳非切","vol":"12","py":"fēi","duan":[{"e":"匹也。","n":"匹者、四丈也。禮記。納幣一束。束五兩。兩五尋。注云。十箇爲束。兩兩合其卷、是謂五兩。八尺曰尋。按四丈而兩之、各得二丈。夫婦之片合如帛之判合矣。故帛四丈曰兩、曰匹。人之配耦亦曰匹。妃本上下通偁。後人以爲貴偁耳。釋詁曰。妃、媲也。引申爲凡相耦之偁。左傳曰。嘉耦曰妃、其字亦叚配爲之。太玄作？。其云？㐜者、卽左傳之嘉耦曰妃、怨耦曰仇也。"}]},"媲":{"expl":"妃也。从女𣬉聲。","rad":"女","fq":"匹計切","vol":"12","py":"pì","duan":[{"e":"妃也。","n":"釋詁曰。妃、媲也。此云媲、妃也。見相爲轉注。"}]},"妊":{"expl":"孕也。从女从壬，壬亦聲。","rad":"女","fq":"如甚切","vol":"12","py":"rèn","duan":[{"e":"孕也。","n":"孕者、裹子也。"}]},"娠":{"expl":"女妊身動也。从女辰聲。《春秋傳》曰：“后緡方娠。”一曰宮婢女隸謂之娠。","rad":"女","fq":"失人切","vol":"12","py":"shēn","duan":[{"e":"女妊身動也。","n":"凡从辰之字皆有動意。震振是也。妊而身動曰娠。別䛐也。渾言之則妊娠不別。詩。大任有身。生此文王。傳曰。身、重也。葢妊而後重。重而後動。動而後生。"}]},"媰":{"expl":"婦人妊身也。从女芻聲。《周書》曰：“至于媰婦。”","rad":"女","fq":"側鳩切","vol":"12","py":"chú","duan":[{"e":"婦人妊娠也。","n":"娠各本作身。今依廣韵十虞正。廣雅曰。媰、㑗也。"}]},"𡢎":{"expl":"生子齊均也。从女从生，免聲。","rad":"女","fq":"芳萬切","vol":"12","py":"fàn","duan":[{"e":"生子齊均也。","n":"謂生子多而如一也。玄應書曰。今中國謂蕃息爲嬎息。音芳萬切。周成難字云。嬎、息也。按依列篆次弟求之。則此篆爲免身。當云从女免生。"}]},"嫛":{"expl":"婗也。从女殹聲。","rad":"女","fq":"烏雞切","vol":"12","py":"yī","duan":[{"e":"嫛婗也。","n":"各本婗上刪嫛字。今補。此三字句。嫛婗合二字爲名。不容分裂。釋名。人始生曰嬰兒。或曰嫛婗。嫛、是也。言是人也。婗其啼聲也。襍記曰。中路嬰兒失其母焉。注。嬰猶鷖彌也。按鷖彌卽嫛婗。語同而字異耳。"}]},"婗":{"expl":"嫛婗也。从女兒聲。一曰婦人惡皃。","rad":"女","fq":"五雞切","vol":"12","py":"ní","duan":[{"e":"嫛婗也。从女。兒聲。","n":"五雞切。十六部。"}]},"母":{"expl":"牧也。从女，象褱子形。一曰象乳子也。","rad":"女","fq":"莫后切","vol":"12","py":"mǔ","duan":[{"e":"牧也。","n":"以㬪韵爲訓。牧者、養牛人也。以譬人之乳子。引伸之、凡能生之以啓後者皆曰母。"}]},"玉":{"expl":"石之美。有五德：潤澤以溫，仁之方也；䚡理自外，可以知中，義之方也；其聲舒揚，尃以遠聞，智之方也；不橈而折，勇之方也；銳廉而不技，絜之方也。象三玉之連。|，其貫也。凡玉之屬皆从玉。[陽冰曰：“三畫正均如貫玉也。”]","rad":"玉","fq":"魚欲切","vol":"01","py":"yù","duan":[{"e":"石之美有五德者。","n":"者字新補。"}]},"噬":{"expl":"啗也。喙也。从口筮聲。","rad":"口","fq":"時制切","vol":"02","py":"shì","duan":[]},"嫗":{"expl":"母也。从女區聲。","rad":"女","fq":"衣遇切","vol":"12","py":"yù","duan":[{"e":"母也。","n":"樂記。煦嫗覆育萬物。鄭曰。以氣曰煦。以體曰嫗。詩毛傳。桺下惠嫗不逮門之女。亦以體曰嫗之意。不逮門者、不及入門。荀卿所謂與後門者同衣卽此也。凡人及鳥生子曰乳。皆必以體嫗之。方言。伏雞曰抱。郭云。江東呼蓲。央富反。按蓲卽嫗也。母之呼嫗由此。高帝本紀曰。有一老嫗夜哭。"}]},"媼":{"expl":"女老偁也。从女𥁕聲。讀若奥。","rad":"女","fq":"烏皓切","vol":"12","py":"ǎo","duan":[{"e":"母老偁也。","n":"母大徐作女。非也。高帝母曰劉媼。文穎曰。幽州及漢中皆謂老嫗爲媼。孟康曰。長老尊稱也。左師謂太后曰。媼愛燕后賢於長安君。禮樂志。媼神蕃釐。后土富媼。張晏曰。媼、老母偁也。坤爲母。故偁媼。"}]},"姁":{"expl":"嫗也。从女句聲。","rad":"女","fq":"況羽切","vol":"12","py":"xǔ","duan":[{"e":"嫗也。","n":"然則姁亦母偁也。師古曰。呂后名雉。字娥姁。"}]},"姐":{"expl":"蜀謂母曰姐，淮南謂之社。从女且聲。","rad":"女","fq":"兹也切","vol":"12","py":"jiě","duan":[{"e":"蜀人謂母曰姐。","n":"方言也。其字當蜀人所製。"}]},"姑":{"expl":"夫母也。从女古聲。","rad":"女","fq":"古胡切","vol":"12","py":"ɡū","duan":[{"e":"夫母也。","n":"釋親曰。婦偁夫之父曰舅。稱夫之母曰姑。姑舅在則曰君舅君姑。𣳚則曰先舅先姑。按聖人正名之義。名有可叚借通用者。有不可叚借通用者。可叚借者舅姑是也。故母之晜弟爲舅。夫之父亦曰舅。妻之父曰外舅。夫之母曰姑。男子偁父之姊妹亦曰姑。偁妻之母曰外姑。葢白虎通云。舅者、舊也。姑者、故也。舊故之者、老人之偁也。故其偁可氾用之。不可叚借者父母是也。故同姓有父母。異姓無父母。夫之父母未聞偁父母也。姑之夫未聞偁父也。姑未聞偁母也。母之兄弟未聞偁父也。母之兄弟之妻未聞偁母也。從母之夫未聞偁父也。惟外祖父外祖母則以父之父母例之而得偁。從母則以父之昆弟偁從父例之而得偁。從母之子亦以從父昆弟例之而得偁。凡同姓五服之外及異姓"}]},"威":{"expl":"姑也。从女从戌。漢律曰：“婦告威姑。”","rad":"女","fq":"於非切","vol":"12","py":"wēi","duan":[{"e":"姑也。","n":"引伸爲有威可畏。"}]},"妣":{"expl":"殁母也。从女比聲。","rad":"女","fq":"卑履切","vol":"12","py":"bǐ","duan":[{"e":"殁母也。","n":"殁正作歾、終也。曲禮曰。生曰父、曰母、曰妻。死曰考、曰妣、曰嬪。析言之也。釋親曰。父曰考。母曰妣。渾言之也。"}]},"姊":{"expl":"女兄也。从女𠂔聲。","rad":"女","fq":"將几切","vol":"12","py":"zǐ","duan":[{"e":"女兄也。","n":"釋親曰。男子謂先生爲姊。後生爲妹。邶詩。問我諸姑。遂及伯姊。傳曰。父之姊妹稱姑。先生曰姊。"}]},"妹":{"expl":"女弟也。从女未聲。","rad":"女","fq":"莫佩切","vol":"12","py":"mèi","duan":[{"e":"女弟也。","n":"衞風。東宮之妹。傳曰。女子後生曰妹。"}]},"娣":{"expl":"女弟也。从女从弟，弟亦聲。","rad":"女","fq":"徒禮切","vol":"12","py":"dì","duan":[{"e":"同夫之女弟也。","n":"小徐本有夫之二字、而尙少同字。今補。同夫者、女子同事一夫也。釋親曰。女子同出謂先生爲姒。後生爲娣。孫郭皆云。同出、謂俱嫁事一夫。王度記曰。諸侯娶一國。則二國往媵之。公羊傳、白虎通皆曰。諸侯娶一國。則二國往媵之。以姪娣從。姪者何。兄之子也。娣者何。女弟也。大雅韓奕傳曰。諸侯一娶九女。二國媵之。諸娣、衆妾也。按女子謂女兄弟曰姊妹。與男子同。而惟媵己之妹則謂之娣。葢別於在母家之偁。以明同心事一君之義也。禮喪服經皆言妹無言娣者。今大徐本作女弟也。非是。小徐本又妹娣二篆互譌。而娣下曰女弟也。妹下曰夫之女弟也。楚金以班昭女誡㛮妹之偁注之。夫夫之姊呼女妐。夫之妹呼女叔。見鄭氏昏義注。夫之妹呼女叔、猶夫之弟呼"}]},"啗":{"expl":"食也。从口臽聲。讀與含同。","rad":"口","fq":"徒濫切","vol":"02","py":"dàn","duan":[{"e":"食也。从口。臽聲。","n":"徒濫切。八部。"}]},"媦":{"expl":"楚人謂女弟曰媦。从女胃聲。《公羊傳》曰：“楚王之妻媦。”","rad":"女","fq":"云貴切","vol":"12","py":"wèi","duan":[{"e":"楚人謂女弟曰媦。","n":"方言之不同也。"}]},"㛮":{"expl":"兄妻也。从女叜聲。","rad":"女","fq":"穌老切","vol":"12","py":"sǎo","duan":[{"e":"兄妻也。","n":"鄭注喪服曰。㛮者尊嚴之。㛮猶叟也。叟、老人之偁也。按古者重男女之別。故於兄之妻尊嚴之。於弟之妻卑遠之。而皆不爲服。男子不爲兄弟之妻服。猶女子不爲夫之兄弟服也。女子於夫之姊妹則相服小功者、相與居室之親也。"}]},"姪":{"expl":"兄之女也。从女至聲。","rad":"女","fq":"徒結切","vol":"12","py":"zhí","duan":[{"e":"女子謂兄弟之子也。","n":"各本作兄之女也。不完。今依爾雅正。釋親曰。女子謂晜弟之子爲姪。喪服大功章曰。女子子適人者、爲衆昆弟姪丈夫婦人報。傳曰。姪者何也。謂吾姑者吾謂之姪。經言丈夫婦人同謂之姪。則非專謂女也。公羊傳曰。二國往媵。以姪娣從。謂婦人也。左傳曰。姪其從姑。謂丈夫也。不謂之猶子者、女外成別於男也。今世俗男子謂兄弟之子爲姪。是名之不正也。"}]},"姨":{"expl":"妻之女弟同出爲姨。从女夷聲。","rad":"女","fq":"以脂切","vol":"12","py":"yí","duan":[{"e":"妻之女弟同出爲姨。","n":"釋親曰。妻之姊妹同出爲姨。孫曰。同出、俱已嫁也。此獨言女弟者、以弟姨㬪韵也。釋名曰。妻之姊妹曰姨。姨、弟也。言與己妻相長弟也。按長弟謂次弟也。後世謂母之姊妹曰姨母。"}]},"妿":{"expl":"女師也。从女加聲。杜林說：加教於女也。讀若阿。","rad":"女","fq":"烏何切","vol":"12","py":"ē","duan":[{"e":"女師也。","n":"詩。言吿師氏。毛傳。師、女師也。古者女師敎以婦徳、婦言、婦容、婦功。李善引漢書音義曰。婦人年五十無子者爲傅。"}]},"娒":{"expl":"女師也。从女𣫭聲。讀若母。","rad":"女","fq":"莫后切","vol":"12","py":"mǔ","duan":[{"e":"女師也。","n":"士昏禮注曰。娒、婦人年五十無子。出而不復嫁。能以婦道敎人者。左傳。宋大？。宋伯姬卒。待姆也。何注公羊曰。禮、后夫人必有傅母。所以輔正其行、衞其身也。𨕖老大夫爲傅。𨕖老大夫妻爲母。按母卽娒也。"}]},"媾":{"expl":"重㛰也。从女冓聲。《易》曰：“匪寇，㛰媾。”","rad":"女","fq":"古候切","vol":"12","py":"ɡòu","duan":[{"e":"重婚也。","n":"重婚者、重㬪交互爲婚姻也。杜注左傳曰。重婚曰媾。按字从冓者、謂若交積材也。曹風。不遂其媾。毛傳曰。媾、厚也。引伸之義也。"}]},"姼":{"expl":"美女也。从女多聲。","rad":"女","fq":"尺氏切","vol":"12","py":"chǐ","duan":[{"e":"美女也。","n":"廣韵曰。姑姼、輕薄皃。此今義也。方言曰。謂父妣曰母姼。稱父考曰父姼。音多。此方俗里語也。"}]},"妭":{"expl":"婦人美也。从女犮聲。","rad":"女","fq":"蒲撥切","vol":"12","py":"bá","duan":[{"e":"美婦也。","n":"廣韵引婦人美皃。大徐作婦人美也。按廣韵曰妭、鬼婦。引文字指歸云。女妭、秃無髮。所居之處天不雨。此謂旱魃也。魃在鬼部。與此各字。而俗亂之。"}]},"㜎":{"expl":"女隸也。从女奚聲。","rad":"女","fq":"胡雞切","vol":"12","py":"xī","duan":[{"e":"女隷也。","n":"周禮作奚。叚借字也。酒人。女酒三十人。奚三百人。鄭注。古者從坐男女、𣳚入縣官爲奴。其少才智者者字今增以爲奚。今之侍史官婢、或曰奚宦女。守祧。女祧每廟二人。奚四人。鄭曰。奚、女奴也。"}]},"嘰":{"expl":"小食也。从口幾聲。","rad":"口","fq":"居衣切","vol":"02","py":"jī","duan":[{"e":"小食也。","n":"大人賦曰。嘰瓊華。按皀部有旣字。云小食也。嘰與旣音義皆同而各字。玉藻進禨、少儀注曰已沐飲曰禨皆當作此嘰。"}]},"婢":{"expl":"女之卑者也。从女从卑，卑亦聲。","rad":"女","fq":"便俾切","vol":"12","py":"bì","duan":[{"e":"女之卑者也。","n":"內則。父母有婢子。鄭曰。所通賤人之子。是婢爲賤人也。有曲禮自世婦以下、自偁曰婢子。左傳秦穆姬言晉君朝以入、則婢子夕以死。是貴者以婢子自謙。婢亦稱婢子、與內則婢子不同也。鄭注曲禮曰。婢之言卑也。"}]},"奴":{"expl":"奴、婢，皆古之辠人也。《周禮》曰：“其奴，男子入于辠隸，女子入于舂藁。”从女从又。","rad":"女","fq":"乃都切","vol":"12","py":"nú","duan":[{"e":"奴婢皆古辠人。周禮曰。其奴男子入于辠隷。女子入于舂稾。","n":"秋官司厲文。鄭司農云。謂坐爲盜賊而爲奴者。輸於罪隷、舂人、稾人之官也。由是觀之。令之爲奴婢、古之罪人也。故書曰。予則奴戮汝。論語曰。箕子爲之奴。春秋傳曰。斐豹隷也。著於丹書。玄謂奴從坐而𣳚入縣官者、男女同名。按許用仲師說。入罪隷者奴。入舂稾者可呼婢。引伸之、凡水不流曰奴。木之類近根者奴。毛傳曰。帑、子也。左傳鳥帑、鳥尾也。駑馬、下乘也。其字皆當作奴。皆引伸之義也。"}]},"㚤":{"expl":"婦官也。从女弋聲。","rad":"女","fq":"與職切","vol":"12","py":"yì","duan":[{"e":"婦官也。","n":"廣韵曰。漢有鉤㚤夫人。居鉤弋宮。漢書亦作弋。玉裁按如淳曰。姬音怡。衆妾之總稱也。引漢官姬妾數百。瓚曰。漢祿秩令及茂陵書。姬、內官也。位次婕妤下。瓚說、淳音皆是也。婦官字當作㚤。漢時借姬爲之。音怡。如姒姓本作以。春秋亦用弋爲之。皆一聲之轉然也。音怡而用爲衆妾之偁、則又方俗語言如是。"}]},"媊":{"expl":"甘氏《星經》曰：“太白上公，妻曰女媊。女媊居南斗，食厲，天下祭之。曰明星。”从女前聲。","rad":"女","fq":"昨先切","vol":"12","py":"qián","duan":[{"e":"甘氏星經曰。","n":"天官書曰。昔之傳天數者在齊甘公。徐廣曰。或曰甘公名德也。本是魯人。按藝文志無甘氏星經。有甘德長桺占夢十一卷。云楚人。"}]},"媧":{"expl":"古之神聖女，化萬物者也。从女咼聲。","rad":"女","fq":"古蛙切","vol":"12","py":"wā","duan":[{"e":"古之神聖女化萬物者也。","n":"媧化㬪韵。司馬貞三皇本紀曰。三皇、說者不同。譙周以燧人爲皇。宋均以祝融爲皇。鄭康成依春秋緯注禮記云女媧三皇承伏羲者。皇甫謐亦同。"}]},"娀":{"expl":"帝高辛之妃，偰母號也。从女戎聲。《詩》曰：“有娀方將。”","rad":"女","fq":"息弓切","vol":"12","py":"sōnɡ","duan":[{"e":"帝高辛之妃、偰母號也。","n":"偰見人部。高辛氏之子。堯司徒。殷之先也。商頌。天命玄鳥。降而生商。傳曰。春分玄鳥降。湯之先祖有娀氏女𥳑狄。配高辛氏帝。帝率與之祈於郊禖而生契。故本其爲天所命。以玄鳥至而生焉。按有娀、諸家說爲國名。長發鄭箋云。有娀氏之國亦始廣大。許氏偰母號者、以其國名爲之號。故長發傳曰有娀、契母也。是亦以爲號也。"}]},"娥":{"expl":"帝堯之女，舜妻娥皇字也。秦晉謂好曰娙娥。从女我聲。","rad":"女","fq":"五何切","vol":"12","py":"é","duan":[{"e":"帝堯之女。舜妻娥皇字也。","n":"曲禮曰。男子二十冠而字。女子許嫁笄而字。"}]},"嫄":{"expl":"台國之女，周棄母字也。从女原聲。","rad":"女","fq":"愚袁切","vol":"12","py":"yuán","duan":[{"e":"邰國之女、周棄母字也。","n":"邰舊作台。誤。今正。邑部曰。邰者、炎帝之後。姜姓所封。周棄外家國也。裴駰引韓詩章句曰。姜、姓。原、字。按史記作原。"}]},"嬿":{"expl":"女字也。从女燕聲。","rad":"女","fq":"於甸切","vol":"12","py":"yàn","duan":[{"e":"女字也。","n":"毛詩。燕婉之求。傳曰。燕、安。婉、順也。韓詩作嬿婉。嬿婉、好皃。見西京賦注。"}]},"妸":{"expl":"女字也。从女可聲。讀若阿。","rad":"女","fq":"烏何切","vol":"12","py":"ē","duan":[{"e":"女字也。从女。可聲。讀若阿。","n":"烏何切。十七部。"}]},"㗘":{"expl":"噍皃。从口尃聲。","rad":"口","fq":"補各切","vol":"02","py":"bó","duan":[{"e":"噍皃。","n":"按釋玄應書三引說文皆云。㗘㗱噍皃也。廣韵十九鐸卄六緝皆云。㗘㗱、噍皃。釋行均書同。說文古本當先㗘字。云㗘㗱、噍皃也。次㗱字。云㗘㗱也。今㗘字㗱字廁㒳處。無㗘㗱之語。葢口部脫誤多矣。"}]},"𡡓":{"expl":"女字也。《楚詞》曰：“女𡡓之嬋媛。”賈侍中說：楚人謂姊爲𡡓。从女須聲。","rad":"女","fq":"相俞切","vol":"12","py":"xū","duan":[{"e":"女字也。","n":"樊噲以呂后女弟呂須爲婦。須卽嬃字也。周易。歸妹以須。鄭云。須、有才智之稱。天文有須女。按鄭意須與諝胥同音通用。諝者、有才智也。"}]},"婕":{"expl":"女字也。从女疌聲。","rad":"女","fq":"子葉切","vol":"12","py":"jié","duan":[{"e":"女字也。","n":"師古漢書注曰。倢伃字或从女。其音同耳。"}]},"嬩":{"expl":"女字也。从女與聲。讀若余。","rad":"女","fq":"以諸切","vol":"12","py":"yú","duan":[{"e":"女字也。","n":"倢伃之伃、葢亦可用此。人部曰。伃、婦官也。"}]},"孁":{"expl":"女字也。从女霝聲。","rad":"女","fq":"郎丁切","vol":"12","py":"línɡ","duan":[{"e":"女字也。","n":"漢婦官十四等中有娱𤫊。𤫊葢可作孁。"}]},"嫽":{"expl":"女字也。从女尞聲。","rad":"女","fq":"洛蕭切","vol":"12","py":"liáo","duan":[{"e":"女字也。","n":"廣韵。相嫽戲也。此今義也。按毛詩傳及許人部曰。僚、好皃。葢亦可用此字。方言。釥、嫽、好也。"}]},"㛄":{"expl":"女字也。从女衣聲。讀若衣。","rad":"女","fq":"於稀切","vol":"12","py":"yī","duan":[{"e":"女字也。","n":"十四等中充依。依葢可用此字。"}]},"婤":{"expl":"女字也。从女周聲。","rad":"女","fq":"職流切","vol":"12","py":"zhōu","duan":[{"e":"女字也。从女。周聲。","n":"職流切。三部。"}]},"姶":{"expl":"女字也。从女合聲。《春秋傳》曰：“嬖人婤姶。”一曰無聲。","rad":"女","fq":"烏合切","vol":"12","py":"è","duan":[{"e":"女字也。从女。合聲。","n":"烏合切。七部。"}]},"妀":{"expl":"女字也。从女己聲。","rad":"女","fq":"居擬切","vol":"12","py":"jǐ","duan":[{"e":"女字也。","n":"玉篇云。妲妀。"}]},"妵":{"expl":"女字也。从女主聲。","rad":"女","fq":"天口切","vol":"12","py":"tǒu","duan":[{"e":"女字也。","n":"昭廿一年左氏傳。宋華妵居於公里。"}]},"含":{"expl":"嗛也。从口今聲。","rad":"口","fq":"胡男切","vol":"02","py":"hán","duan":[{"e":"嗛也。从口。今聲。","n":"胡男切。古音在七部。禮樂志。吟靑黃。以吟爲含。"}]},"𡚮":{"expl":"女字也。从女久聲。","rad":"女","fq":"舉友切","vol":"12","py":"jiǔ","duan":[{"e":"女字也。从女。久聲。","n":"舉友切。古音在一部。小徐本作奺。廣韵曰亦作奺。"}]},"㛅":{"expl":"女號也。从女耳聲。","rad":"女","fq":"仍吏切","vol":"12","py":"èr","duan":[{"e":"女字也。","n":"字各本作號。今依玉篇、廣韵。"}]},"始":{"expl":"女之初也。从女台聲。","rad":"女","fq":"詩止切","vol":"12","py":"shǐ","duan":[{"e":"女之初也。","n":"釋詁曰。初、始也。此與爲互訓。初、裁皆衣之始也。基者、牆之始也。凡言之者皆分別之䛐。有叚殆爲始者。七月毛傳云殆始也是也。"}]},"媚":{"expl":"說也。从女眉聲。","rad":"女","fq":"美祕切","vol":"12","py":"mèi","duan":[{"e":"說也。","n":"說今悅字也。大雅毛傳曰。媚、愛也。"}]},"嫵":{"expl":"𡡾也。从女無聲。","rad":"女","fq":"文甫切","vol":"12","py":"wǔ","duan":[{"e":"媚也。","n":"上林賦。嫵媚纖弱。李善引埤倉曰。嫵媚、悅也。按嫵媚可分用。張敞傳。長安中傳京兆眉憮。憮卽嫵字。蘇林曰。憮音嫵。北方人謂眉好爲詡畜。"}]},"媄":{"expl":"色好也。从女从美，美亦聲。","rad":"女","fq":"無鄙切","vol":"12","py":"měi","duan":[{"e":"色好也。","n":"按凡美惡字可作此。周禮作媺。葢其古文。"}]},"㜅":{"expl":"𡡾也。从女畜聲。","rad":"女","fq":"丑六切","vol":"12","py":"xù","duan":[{"e":"媚也。","n":"㜅有媚悅之義。凡古經傳用畜字多有爲㜅之叚借者。蘇林曰。北方人謂睂好爲詡畜。又如禮記。孝者畜也。順於道不逆於倫是之謂畜。孟子曰。詩曰畜君何尤。畜君者、好君也。呂覽曰。周書曰民善之則畜也。不善則讎也。高注。畜、好也。說苑。尹逸對成王曰。夫民善之則畜也。不善則讎也。又孔子曰。夫通達之國皆人也。以道導之、則吾畜也。不以道導之、則吾讎也。此等皆以好惡對言。畜字皆取㜅媚之義。今則無有用㜅者矣。"}]},"嫷":{"expl":"南楚之外謂好曰嫷。从女隋聲。","rad":"女","fq":"徒果切","vol":"12","py":"duò","duan":[{"e":"南楚之外謂好曰嫷。","n":"方言曰。嫷、美也。南楚之外曰？。郭注。言婑？也。曹植七啓。形媠服兮揚幽若。媠卽嫷之省。心部之古文憜也。張敞傳。被輕媠之名。皆引伸之義也。"}]},"姝":{"expl":"好也。从女朱聲。","rad":"女","fq":"昌朱切","vol":"12","py":"shū","duan":[{"e":"好也。","n":"邶風傳曰。姝、美色也。衞風傳曰。姝、順皃。齊風傳曰。姝、初昏之皃。各隨文爲訓也。"}]},"好":{"expl":"美也。从女、子。","rad":"女","fq":"呼皓切","vol":"12","py":"hǎo","duan":[{"e":"媄也。","n":"各本作美也。今正。與上文媄爲轉注也。好本謂女子。引伸爲凡美之偁。凡物之好惡、引伸爲人情之好惡。本無二音。而俗強別其音。"}]},"哺":{"expl":"哺咀也。从口甫聲。","rad":"口","fq":"薄故切","vol":"02","py":"bǔ","duan":[{"e":"哺咀也。","n":"哺咀葢㬪韵字。釋玄應引許淮南注曰。哺、口中嚼食也。又引字林。哺咀、食也。凡含物以飼曰哺。爾雅。生哺鷇。"}]},"嬹":{"expl":"說也。从女興聲。","rad":"女","fq":"許應切","vol":"12","py":"xìnɡ","duan":[{"e":"說也。","n":"說今之悅字。李善注潘岳關中詩、顏延年和謝靈運詩皆引說文興、悅也。謂興與嬹古同也。今惟漢功臣表有甘泉侯嬹。許孕反。"}]},"嬮":{"expl":"好也。从女厭聲。","rad":"女","fq":"於鹽切","vol":"12","py":"yān","duan":[{"e":"好也。","n":"謂懕懕也。"}]},"𡚾":{"expl":"好也。从女殳聲。《詩》曰：“靜女其𡚾。”","rad":"女","fq":"昌朱切","vol":"12","py":"shū","duan":[{"e":"好也。","n":"此與姝音義皆同。"}]},"姣":{"expl":"好也。从女交聲。","rad":"女","fq":"胡茅切","vol":"12","py":"jiǎo","duan":[{"e":"好也。","n":"姣謂容體壯大之好也。史記。長姣美人。按古多借佼爲姣。如月令養壯佼、陳風澤陂箋佼大皆姣字也。小雅白華箋云。姣大之人。陳風佼人字又作姣。方言云。自關而東河泲之閒凡好謂之姣。"}]},"嬽":{"expl":"好也。从女𡚇聲。讀若蜀郡布名。","rad":"女","fq":"委員切","vol":"12","py":"yuān","duan":[{"e":"好也。","n":"上林賦。柔嬈嬽嬽。郭樸曰。皆骨體耎弱長豔皃也。今文選譌作嫚嫚。漢書不誤。史記作嬛嬛、則是別本。按今人所用娟字當卽此。"}]},"娧":{"expl":"好也。从女兌聲。","rad":"女","fq":"杜外切","vol":"12","py":"tuì","duan":[{"e":"好也。","n":"召南。舒而脫脫兮。傳曰。脫脫、舒皃。按脫葢卽娧之叚借。此謂舒徐之好也。"}]},"媌":{"expl":"目裏好也。从女苗聲。","rad":"女","fq":"莫交切","vol":"12","py":"miáo","duan":[{"e":"目裏好也。","n":"目裏好者、謂好在匡之裏也。凡方言言順、言𥌣、言鑠、言盱、言揚皆謂目之好外見也。惟媌狀目裏。方言曰。媌、好也。自關而東河濟之閒謂之媌。按此謂纖細之好也。"}]},"嫿":{"expl":"靜好也。从女畫聲。","rad":"女","fq":"呼麥切","vol":"12","py":"huà","duan":[{"e":"靜好也。","n":"靜者、審也。廣韵曰。嫿、分明好皃。神女賦曰。旣姽嫿於幽靜。魏都賦曰。風俗以韰果爲嫿。"}]},"婠":{"expl":"體德好也。从女官聲。讀若楚卻宛。","rad":"女","fq":"一完切","vol":"12","py":"wān","duan":[{"e":"體德好也。从女。官聲。","n":"一完切。十四部。"}]},"娙":{"expl":"長好也。从女坙聲。","rad":"女","fq":"五莖切","vol":"12","py":"xínɡ","duan":[{"e":"長好也。","n":"體長之好也。故其字从巠。上文曰秦晉謂好爲娙娥。漢婦官十四等有娙娥。武帝郉夫人號娙娥。"}]},"味":{"expl":"滋味也。从口未聲。","rad":"口","fq":"無沸切","vol":"02","py":"wèi","duan":[{"e":"滋味也。","n":"滋言多也。"}]},"㜺":{"expl":"白好也。从女贊聲。","rad":"女","fq":"則旰切","vol":"12","py":"zàn","duan":[{"e":"白好也。","n":"色白之好也。通俗文。服飾鮮盛、謂之㜖㜺。聲類。㜺、綺也。皆引伸之義也。"}]},"𡡗":{"expl":"順也。从女𤔔聲。《詩》曰：“婉兮𡡗兮。”","rad":"女","fq":"力沇切","vol":"12","py":"luǎn","duan":[{"e":"順也。","n":"邶風傳曰。孌、好皃。齊風傳曰。婉孌、少好皃。義與許互相足。"}]},"妴":{"expl":"婉也。从女夗聲。","rad":"女","fq":"於阮切","vol":"12","py":"wǎn","duan":[{"e":"婉也。从女。夗聲。","n":"於阮切。十四部。"}]},"婉":{"expl":"順也。从女宛聲。《春秋傳》曰：“太子痤婉。”","rad":"女","fq":"於阮切","vol":"12","py":"wǎn","duan":[{"e":"順也。","n":"鄭風傳曰。婉然美也。齊風傳曰。婉、好眉目也。"}]},"𡜝":{"expl":"直項皃。从女同聲。","rad":"女","fq":"他孔切","vol":"12","py":"dònɡ","duan":[{"e":"直項皃。从女。同聲。","n":"他孔切。廣韵徒揔切。九部。"}]},"嫣":{"expl":"長皃。从女焉聲。","rad":"女","fq":"於建切","vol":"12","py":"yān","duan":[{"e":"長皃。","n":"詩毛傳。頎頎、長皃。頎與嫣聲相近也。文選。嫣然一笑。注引王逸云。嫣、笑皃。然大招字作嘕。許書無嘕字。"}]},"㚩":{"expl":"弱長皃。从女冄聲。","rad":"女","fq":"而琰切","vol":"12","py":"rǎn","duan":[{"e":"弱長皃。","n":"上林賦。嫵媚㚩嫋。郭樸曰。㚩嫋、細弱也。小顏云。謂骨體。按毛詩曰。荏染、柔意也。荏染卽㚩也。"}]},"嫋":{"expl":"㚩也。从女从弱。","rad":"女","fq":"奴鳥切","vol":"12","py":"niǎo","duan":[{"e":"㚩也。","n":"九歌。嫋嫋兮秋風。王曰。嫋嫋、秋風搖木皃。按楚辭讀上聲。上林賦讀入聲。實無二義也。"}]},"孅":{"expl":"銳細也。从女韱聲。","rad":"女","fq":"息廉切","vol":"12","py":"xiān","duan":[{"e":"兌細也。","n":"兌各本作銳。集韵、類篇皆作兌。兌者、悅也。漢書曰。古之治天下。至孅至悉也。孅與纖音義皆同。古通用。"}]},"嫇":{"expl":"嬰嫇也。从女冥聲。一曰嫇嫇，小人皃。","rad":"女","fq":"莫經切","vol":"12","py":"mínɡ","duan":[{"e":"嬰嫇也。","n":"廣韵嫈下作嫈嫇。玄應引字林嫈嫇、心態也。卽許書嫈下之小心態也。九思作瑩嫇。疑今本說文有舛誤。"}]},"嚛":{"expl":"食辛嚛也。从口樂聲。","rad":"口","fq":"火沃切","vol":"02","py":"hù","duan":[{"e":"食辛嚛也。","n":"嚛謂辛螫。火部引周書。味辛而不熮。吕覽本味。味辛而不烈。嚛與熮烈同義。玉篇云。伊尹曰。酸而不嚛。此古伊尹書之僅存者。酸疑當作辛。辛而不嚛。卽本味之辛而不烈也。"}]},"媱":{"expl":"曲肩行皃。从女䍃聲。","rad":"女","fq":"余招切","vol":"12","py":"yáo","duan":[{"e":"曲肩行皃。","n":"九思。音案衍兮要媱。舞容也。廣韵曰。媱、美好。"}]},"嬛":{"expl":"材緊也。从女瞏聲。《春秋傳》曰：“嬛嬛在疚。”","rad":"女","fq":"許緣切","vol":"12","py":"xuān","duan":[{"e":"材緊也。","n":"材緊、謂材質堅緻也。緊者、纏絲急也。上林賦。便嬛綽約。郭樸曰。便嬛、輕利也。"}]},"姽":{"expl":"閑體，行姽姽也。从女危聲。","rad":"女","fq":"過委切","vol":"12","py":"ɡuǐ","duan":[{"e":"閒體行姽姽也。","n":"閒各本作閑。今正。閒者、幽閒也。神女賦。志解泰而體閒。旣姽嫿於幽靜。李引說文曰。姽、靖好皃。五累切。與今本異。"}]},"委":{"expl":"委隨也。从女从禾。","rad":"女","fq":"於詭切","vol":"12","py":"wěi","duan":[{"e":"委、","n":"逗。"}]},"婐":{"expl":"㛂也。一曰女侍曰婐。讀若騧，或若委。从女果聲。孟軻曰：“舜爲天子，二女婐。”","rad":"女","fq":"烏果切","vol":"12","py":"wǒ","duan":[{"e":"婐㛂也。","n":"三字句。今本刪婐字。非也。婐㛂與旖施音義皆同。俗作婀娜。"}]},"㛂":{"expl":"婐㛂也。一曰弱也。从女𠂬聲。","rad":"女","fq":"五果切","vol":"12","py":"nuǒ","duan":[{"e":"婐㛂也。","n":"㬪韵字。"}]},"㚲":{"expl":"小弱也。一曰女輕薄善走也。一曰多技藝也。从女占聲。或讀若占。","rad":"女","fq":"齒懾切","vol":"12","py":"chān","duan":[{"e":"小弱也。从女。占聲。一曰女輕薄善走也。讀若占。一曰多技埶也。","n":"齒懾切。七部。"}]},"𡝫":{"expl":"妗也。从女沾聲。","rad":"女","fq":"丑廉切","vol":"12","py":"chān","duan":[{"e":"𡝫妗也。","n":"依玉篇補𡝫字。三字句也。廣韵作妗𡝫。"}]},"妗":{"expl":"𡝫妗也。一曰善笑皃。从女今聲。","rad":"女","fq":"火占切","vol":"12","py":"xiān","duan":[{"e":"？妗也。","n":"㬪韵字。"}]},"孂":{"expl":"竦身也。从女簋聲。讀若《詩》“糾糾葛屨”。","rad":"女","fq":"居夭切","vol":"12","py":"jiǎo","duan":[{"e":"竦身也。","n":"竦者、敬也。从立束。自申束也。竦身取自申之意。凡言夭矯者、當用此字。"}]},"𠿡":{"expl":"口滿食。从口窡聲。","rad":"口","fq":"丁滑切","vol":"02","py":"zhuó","duan":[{"e":"口滿食。从口。窡聲。","n":"丁滑切。十五部。"}]},"婧":{"expl":"竦立也。从女青聲。一曰有才也。讀若韭菁。","rad":"女","fq":"七正切","vol":"12","py":"jìnɡ","duan":[{"e":"竦立也。","n":"女有字婧者。列女傳曰。妾婧者、齊相管仲之妾也。"}]},"妌":{"expl":"靜也。从女井聲。","rad":"女","fq":"疾正切","vol":"12","py":"jìnɡ","duan":[{"e":"靜也。从女。井聲。","n":"疾正切。十一部。"}]},"姂":{"expl":"婦人皃。从女乏聲。","rad":"女","fq":"房法切","vol":"12","py":"fá","duan":[{"e":"婦人皃。从女。𣥄聲。","n":"房法切。七部。"}]},"嫙":{"expl":"好也。从女旋聲。","rad":"女","fq":"似沿切","vol":"12","py":"xuán","duan":[{"e":"好也。","n":"齊風。子之還兮。韓詩作嫙。嫙、好皃。"}]},"䶒":{"expl":"材也。从女齊聲。","rad":"女","fq":"祖雞切","vol":"12","py":"qí","duan":[{"e":"材也。","n":"廣雅。䶒、好也。玉篇引詩有䶒季女。引說文材也。按毛詩作齊、敬也。顧氏或取諸三家詩。取人材整齊之意。"}]},"姡":{"expl":"面醜也。从女𠯑聲。","rad":"女","fq":"古活切","vol":"12","py":"huá","duan":[{"e":"面靦也。","n":"各本作面醜。今正。醜者、可惡也。與愧恥義隔。面靦者、詩云有靦面目是也。面部靦下曰。面見人也。面見人、如今人言無面目相見。其義彼此相成。此許例也。爾雅、毛傳皆云靦、𡜶也。此云𡜶、靦也。是之謂轉注。今人亦尙有羞𡜶𡜶之語。"}]},"嬥":{"expl":"直好皃。一曰嬈也。从女翟聲。","rad":"女","fq":"徒了切","vol":"12","py":"tiǎo","duan":[{"e":"直好皃。","n":"直好、直而好也。嬥之言擢也。詩。佻佻公子。魏都賦注云。佻或作嬥。廣韵曰。嬥嬥、往來皃。韓詩云。嬥歌、巴人歌也。按韓詩云三字當在嬥嬥之上。其下六字乃張載注左語也。此皆別義。"}]},"嫢":{"expl":"媞也。从女規聲。讀若癸。秦晉謂細爲嫢。","rad":"女","fq":"居隨切","vol":"12","py":"ɡuī","duan":[{"e":"媞也。","n":"媞者、諦也。諦者、審也。"}]},"媞":{"expl":"諦也。一曰妍黠也。一曰江淮之閒謂母曰媞。从女是聲。","rad":"女","fq":"承旨切","vol":"12","py":"shì","duan":[{"e":"諦也。","n":"諦者、審也。審者、悉也。詩。好人提提。傳云。提提、安諦也。釋訓。媞媞、安也。孫炎曰。行步之安也。檀弓。吉事欲其折折爾。注云。安舒貌。按折者、提之譌。提者、媞之叚借字也。"}]},"婺":{"expl":"不繇也。从女敄聲。","rad":"女","fq":"亡遇切","vol":"12","py":"wù","duan":[{"e":"不䌛也。","n":"䌛者、隨從也。不䌛者、不隨從也。今此字無用者矣。惟婺女、星名。婺州、地名。"}]},"噫":{"expl":"飽食息也。从口意聲。","rad":"口","fq":"於介切","vol":"02","py":"ǎi","duan":[{"e":"飽出息也。","n":"各本作飽食。今依玉篇、衆經音義訂。息、鼻息也。內則。在父母舅姑之所。不敢噦噫。莊子。大塊噫氣。其名曰風。靈樞經曰。五藏氣心主噫。按噫字亦作餩。見廣雅。玉篇、廣韵於北烏克二反。高注淮南書曰。垓讀如人飮食太多、以思下垓之垓。以思下垓之垓、乃以息上餩之餩之誤。高注多言心中滿該。亦謂此也。"}]},"嫺":{"expl":"雅也。从女閒聲。","rad":"女","fq":"戶閒切","vol":"12","py":"xián","duan":[{"e":"嫺雅也。","n":"三字句。各本刪嫺字。非也。依玉篇、廣韵本作嫺雅。相如傳。雍容嫺雅。雅之叚借之義爲素也。嫺雅、今所謂嫺習也。嫺古多借閒爲之。邶風棣棣。毛傳曰。棣棣、富而閒也。今本作閒習。杜注左所引無習字。葢古本也。習則能暇。故其字从閒。"}]},"媐":{"expl":"說樂也。从女巸聲。","rad":"女","fq":"許其切","vol":"12","py":"yí","duan":[{"e":"說樂也。","n":"說者、今之悅字。按老子、史記天下熙熙字皆當爲媐媐。今熙行而媐廢矣。熙者、燥也。謂㬥燥也。其義別。"}]},"婜":{"expl":"美也。从女臤聲。","rad":"女","fq":"苦閑切","vol":"12","py":"qiān","duan":[{"e":"美也。从女。臤聲。","n":"苦閒切。古音在十二部。"}]},"娛":{"expl":"樂也。从女吳聲。","rad":"女","fq":"噳俱切","vol":"12","py":"yú","duan":[{"e":"樂也。","n":"古多借虞爲之。"}]},"娭":{"expl":"戲也。从女矣聲。一曰卑賤名也。","rad":"女","fq":"遏在切","vol":"12","py":"xī","duan":[{"e":"戲也。","n":"戲者、三軍之偏也。一曰兵也。嬉戲、則其餘義也。左傳。子玉曰。請與君之士戲。固以戰爲戲矣。上林賦。娭遊往來。善曰。娭許其切。然則今之嬉字也。今嬉行而娭廢矣。"}]},"媅":{"expl":"樂也。从女甚聲。","rad":"女","fq":"丁含切","vol":"12","py":"dān","duan":[{"e":"樂也。","n":"衞風。無與士耽。傳曰。耽、樂也。小雅。和樂且湛。傳曰。湛、樂之久也。耽湛皆叚借字。媅其眞字也。叚借行而眞字廢矣。"}]},"娓":{"expl":"順也。从女尾聲。讀若𡡾。","rad":"女","fq":"無匪切","vol":"12","py":"wěi","duan":[{"e":"順也。","n":"順者、理也。尾主於順。故其字从尾。按此篆不見於經傳。詩、易用？？字。學者每不解其何以會意形聲。徐鉉等乃妄云當作娓。而近者惠定字氏從之。挍李氏易集解及自爲周易述皆用娓娓。抑思毛、鄭釋詩皆云勉勉。康成注易亦言𣳚𣳚。釁之古音讀如門。勉、𣳚皆㬪韵字。然則？爲釁之譌體。釁爲勉之叚借。古音古義於今未泯。不當以無知妄說、擅改宣聖大經。"}]},"嫡":{"expl":"孎也。从女啻聲。","rad":"女","fq":"都歴切","vol":"12","py":"dí","duan":[{"e":"孎也。从女。啻聲。","n":"都𠪱切。十六部。按俗以此爲嫡庶字、而許書不尒。葢嫡庶字古衹作適。適者、之也。所之必有一定也。詩。天位殷適。傳曰。紂居天位、而殷之正適也。凡今經傳作嫡者、葢皆不古。"}]},"孎":{"expl":"謹也。从女屬聲。讀若人不孫爲孎。","rad":"女","fq":"之欲切","vol":"12","py":"zhú","duan":[{"e":"謹也。","n":"謹者、愼也。祭義。洞洞乎、屬屬乎如弗勝。廣雅。洞洞、屬屬、敬也。屬葢孎之省。"}]},"𡟰":{"expl":"宴𡟰也。从女冤聲。","rad":"女","fq":"於願切","vol":"12","py":"wǎn","duan":[{"e":"宴也。","n":"邶風。燕婉之求。傳曰。宴、安。婉、順也。西京賦曰。嬿婉、美好之皃。按古宛冤通用。婉音義皆同。"}]},"璙":{"expl":"玉也。从玉尞聲。","rad":"玉","fq":"洛簫切","vol":"01","py":"liáo","duan":[{"e":"玉也。","n":"謂玉名也。如毛傳鳧山也、繹山也之例。不言山名也。古傳注多不言名。"}]},"嘽":{"expl":"喘息也。一曰喜也。从口單聲。《詩》曰：“嘽嘽駱馬。”","rad":"口","fq":"他干切","vol":"02","py":"tān","duan":[{"e":"喘息也。","n":"小雅傳曰。嘽嘽、喘息也。馬勞則喘息。"}]},"媕":{"expl":"女有心媕媕也。从女弇聲。","rad":"女","fq":"衣檢切","vol":"12","py":"yǎn","duan":[{"e":"女有心媕媕也。从女。弇聲。","n":"衣檢切。七部。"}]},"媣":{"expl":"諟也。从女染聲。","rad":"女","fq":"而琰切","vol":"12","py":"rǎn","duan":[{"e":"諟也。","n":"諟者、理也。"}]},"嫥":{"expl":"壹也。从女專聲。一曰嫥嫥。","rad":"女","fq":"職緣切","vol":"12","py":"zhuān","duan":[{"e":"壹也。","n":"壹下云。嫥也。與此爲轉注。凡嫥壹字古如此作。今則專行而嫥廢矣。專者、六寸薄也。紡專也。"}]},"如":{"expl":"从隨也。从女从口。","rad":"女","fq":"人諸切","vol":"12","py":"rú","duan":[{"e":"從隨也。","n":"從隨卽隨從也。隨從必以口。从女者、女子從人者也。幼從父兄。嫁從夫。夫死從子。故白虎通曰。女者、如也。引伸之、凡相似曰如。凡有所往曰如。皆從隨之引伸也。"}]},"嫧":{"expl":"齊也。从女責聲。","rad":"女","fq":"側革切","vol":"12","py":"zé","duan":[{"e":"齊也。","n":"謂整齊也。方言。婩、嫧鮮、好也。南楚之外通語也。"}]},"娕":{"expl":"謹也。从女束聲。讀若謹敕數數。","rad":"女","fq":"測角切","vol":"12","py":"chuò","duan":[{"e":"謹也。","n":"謹者、愼也。按史記申屠嘉傳。娖娖廉謹。說者多云娖卽娕字。玉篇、廣韵皆不謂一字也。"}]},"嬐":{"expl":"敏疾也。一曰莊敬皃。从女僉聲。","rad":"女","fq":"息廉切","vol":"12","py":"xiān","duan":[{"e":"敏疾也。从女。僉聲。","n":"息廉切。七部。"}]},"嬪":{"expl":"服也。从女賓聲。","rad":"女","fq":"符眞切","vol":"12","py":"pín","duan":[{"e":"服也。","n":"堯典曰。釐降二女于嬀汭。嬪于虞。大雅曰。摰仲女任。自彼殷商。來嫁于周。曰嬪于京。傳曰。嬪、婦也。按婦者、服也。故釋嬪亦曰服也。老子賓與臣同義。故詩曰率土之賓。莫非王臣。嬪與婦同義、亦其理也。"}]},"𡠗":{"expl":"至也。从女執聲。《周書》曰：“大命不𡠗。”讀若摯同。一曰《虞書》雉𡠗。","rad":"女","fq":"脂利切","vol":"12","py":"zhì","duan":[{"e":"至也。","n":"以雙聲㬪韵釋之。"}]},"㛥":{"expl":"俛伏也。从女沓聲。一曰伏意。","rad":"女","fq":"他合切","vol":"12","py":"tà","duan":[{"e":"俛伏也。","n":"俛者、低頭也。伏者、伺也。"}]},"唾":{"expl":"口液也。从口𡍮聲。","rad":"口","fq":"湯臥切","vol":"02","py":"tuò","duan":[{"e":"口液也。","n":"曲禮。讓食不唾。內則。不敢唾洟。"}]},"妟":{"expl":"安也。从女、日。《詩》曰：“以妟父母。”","rad":"女","fq":"烏諫切","vol":"12","py":"yàn","duan":[{"e":"安也。","n":"安者、竫也。今經傳無妟字。"}]},"嬗":{"expl":"緩也。从女亶聲。一曰傳也。","rad":"女","fq":"時戰切","vol":"12","py":"shàn","duan":[{"e":"𦅻也。","n":"今人用嬋字亦作此。"}]},"嫴":{"expl":"𠈃任也。从女辜聲。","rad":"女","fq":"古胡切","vol":"12","py":"ɡū","duan":[{"e":"保任也。","n":"急就篇。疻痏保辜謕呼號。師古曰。保辜者、各隨其輕重。令毆者以日數保之。限內致死則坐重辜也。按保辜、唐律今律皆有之。辜者、嫴之省。嫴與保同義㬪字。師古以坐重辜解之。誤矣。春秋公羊傳注曰。古者保辜。鄭伯髡原爲大夫所傷。以傷辜死。君親無將見辜者、辜內當以弑君論之。辜外當以傷君論之。辜皆當作嫴。原許君之義。實不專謂罪人保嫴。謂凡事之估計豫圖耳。廣雅曰。嫴搉、都凡也。是其理也。"}]},"媻":{"expl":"奢也。从女般聲。","rad":"女","fq":"薄波切","vol":"12","py":"pó","duan":[{"e":"奢也。","n":"奢者、張也。趙注孟子、廣雅釋詁皆曰。般、大也。媻之从般、亦取大意。子虛賦。媻姍勃窣。借用此爲蹣跚字。"}]},"娑":{"expl":"舞也。从女沙聲。《詩》曰：“市也媻娑。”","rad":"女","fq":"素何切","vol":"12","py":"suō","duan":[{"e":"舞也。","n":"陳風東門之枌曰。婆娑其下。市也婆娑。爾雅及毛傳皆曰。婆娑。舞也。詩音義曰。婆步波反。說文作媻。爾雅音義但云娑素何反。不爲婆字作音。葢陸所據爾雅固作娑娑。魯頌傳曰。犧尊有沙飾也。鄭志。張逸曰。犧讀爲沙。沙、鳯皇也。不解鳯皇何以爲沙。答曰。刻畫鳯皇之象於尊。其形娑娑然。按今經傳娑娑字皆改作婆娑。詩爾雅卽以媻娑連文。恐尙非古也。然古書中用婆娑字者不少。存愚說以俟攷訂可耳。"}]},"姷":{"expl":"耦也。从女有聲。讀若祐。","rad":"女","fq":"于救切","vol":"12","py":"yòu","duan":[{"e":"耦也。","n":"耕有耦者、取相助也。故引伸之、凡相助曰耦。姷之義取乎此。周禮宮正。以樂侑食。鄭曰。侑猶勸也。按勸卽助。左傳。王享醴。命晉侯宥。杜云。旣饗又命晉侯助以束帛。以助釋宥。古經多叚宥爲侑。毛詩則叚右爲之。傳曰。右、勸也。"}]},"姰":{"expl":"鈞適也。男女併也。从女旬聲。","rad":"女","fq":"居勻切","vol":"12","py":"jūn","duan":[{"e":"均適也。","n":"均舊作鈞。今正。"}]},"姕":{"expl":"婦人小物也。从女此聲。《詩》曰：“屢舞姕姕。”","rad":"女","fq":"卽移切","vol":"12","py":"zī","duan":[{"e":"婦人小物也。","n":"小物謂用物之瑣屑者。今人用些字取𣁋細之意。卽姕之俗體也。"}]},"妓":{"expl":"婦人小物也。从女支聲。讀若跂行。","rad":"女","fq":"渠綺切","vol":"12","py":"jì","duan":[{"e":"婦人小物也。","n":"今俗用爲女伎字。"}]},"嬰":{"expl":"頸飾也。从女、賏。賏，其連也。","rad":"女","fq":"於盈切","vol":"12","py":"yīnɡ","duan":[{"e":"繞也。","n":"各本作頸飾也。今正。貝部賏、頸飾也。嬰與賏非一字。則解不應同。孫綽天台山賦。方解纓絡。李引說文嬰、繞也。纓與嬰通。陸機赴洛中道作詩。世纲嬰我身。李引說文嬰、繞也。唐初本可據。繞者、纏也。一切纏繞如賏之纏頸。故其字从賏。越絕書。嬰榮楯以白璧。司馬法。大夫嬰弓。山海經。嬰以百圭百璧。謂陳之以環祭也。又燕山多嬰石。言石似玉。有符采嬰帶也。凡史言嬰城自守、皆謂以城圍繞而守也。凡言嬰兒、則嫛婗之轉語。"}]},"咦":{"expl":"南陽謂大呼曰咦。从口夷聲。","rad":"口","fq":"以之切","vol":"02","py":"yí","duan":[{"e":"南陽謂大呼曰咦。","n":"呼、外息也。大呼、大息也。"}]},"𡛝":{"expl":"三女爲𡛝。𡛝，美也。从女，𣦼省聲。","rad":"女","fq":"倉案切","vol":"12","py":"càn","duan":[{"e":"三女爲𡛝。","n":"唐風綢繆曰。今夕何夕。見此粲者。毛傳。三女爲粲。大夫一妻二妾。"}]},"媛":{"expl":"美女也。人所援也。从女从爰。爰，引也。《詩》曰：“邦之媛兮。”","rad":"女","fq":"玉眷切","vol":"12","py":"yuàn","duan":[{"e":"美女也。人所欲援也。","n":"庸風。邦之媛也。傳曰。美女爲媛。援者、引也。謂人所欲引爲己助者也。鄭箋詩云。邦人所依倚以爲援助也。援媛以㬪韵爲訓。"}]},"娉":{"expl":"問也。从女甹聲。","rad":"女","fq":"匹正切","vol":"12","py":"pìn","duan":[{"e":"問也。","n":"凡娉女及聘問之禮古皆用此字。娉者、專詞也。聘者、氾詞也。耳部曰。聘者、訪也。言部曰。氾謀曰訪。故知聘爲氾詞也。若夫禮經大曰聘。小曰問。渾言之皆曰聘。此必有所專適。非氾詞也。至於聘則爲妻。則又造字所以从女之故。而經傳槩以聘代之。聘行而娉廢矣。"}]},"娽":{"expl":"隨從也。从女彔聲。","rad":"女","fq":"力玉切","vol":"12","py":"lù","duan":[{"e":"隨從也。","n":"史記平原君列傳曰。公等錄錄。因人成事。王卲云。錄錄、借字。說文娽娽、隨從之皃也。依王本多四字。"}]},"妝":{"expl":"飾也。从女，牀省聲。","rad":"女","fq":"側羊切","vol":"12","py":"zhuānɡ","duan":[{"e":"飾也。","n":"此飾篆引伸之義也。宋玉賦曰。體美容冶。不待飾裝。上林賦。靘䊋刻飾。䊋者、俗字。裝者、叚借字。"}]},"孌":{"expl":"慕也。从女䜌聲。","rad":"女","fq":"力沇切","vol":"12","py":"liàn","duan":[]},"媟":{"expl":"嬻也。从女枼聲。","rad":"女","fq":"私列切","vol":"12","py":"xiè","duan":[{"e":"嬻也。","n":"與下篆爲轉注。媟與日部暬義似同而實異。宋人合爲一字。非也。方言曰。媟、狎也。漢枚乘傳曰。以故得媟黷貴幸。今人以褻衣字爲之。褻行而媟廢矣。"}]},"嬻":{"expl":"媟嬻也。从女賣聲。","rad":"女","fq":"徒谷切","vol":"12","py":"dú","duan":[{"e":"媟嬻也。","n":"單言之曰媟、曰嬻。絫言之曰媟嬻。國語。陳侯淫於夏氏。不亦嬻姓矣乎。惟明道本不誤。今人以溝瀆字爲之。瀆行而嬻廢矣。黑部有黷。握持垢也。義亦與嬻別。"}]},"䆯":{"expl":"短面也。从女窡聲。","rad":"女","fq":"丁滑切","vol":"12","py":"zhuó","duan":[{"e":"短面也。","n":"淮南書曰。聖人之思脩。愚人之思叕。高注。叕、短也。方言。𠭴、短也。注。蹶𠭴、短小皃。䆯篆葢形聲兼會意。"}]},"嬖":{"expl":"便嬖、愛也。从女辟聲。","rad":"女","fq":"博計切","vol":"12","py":"bì","duan":[{"e":"𠊳嬖、","n":"逗。"}]},"呬":{"expl":"東夷謂息爲呬。从口四聲。《詩》曰：“犬夷呬矣。”","rad":"口","fq":"虚器切","vol":"02","py":"xì","duan":[{"e":"東夷謂息爲呬。","n":"方言。呬、息也。東齊曰呬。釋詁郭注亦云。今東齊謂息爲呬。疑許襲方言。東夷當作東齊。字之誤也。"}]},"𡢖":{"expl":"難也。从女毄聲。","rad":"女","fq":"苦賣切","vol":"12","py":"qì","duan":[{"e":"難也。","n":"大東傳曰。契契、憂苦也。擊𡔷傳曰。契濶、勤苦也。按契與？音近。廣韵？音契。"}]},"妎":{"expl":"妒也。从女介聲。","rad":"女","fq":"胡蓋切","vol":"12","py":"hài","duan":[{"e":"妬也。","n":"字林亦云。疾妎、妬也。按楚語弭其百苛。殄其䜛慝。韋注曰。弭、止也。殄、覆也。明道本不誤。謂解除之也。今本譌作妎其䜛慝。文理不可通。"}]},"妒":{"expl":"婦妒夫也。从女戶聲。","rad":"女","fq":"當故切","vol":"12","py":"dù","duan":[{"e":"婦妬夫也。从女。石聲。","n":"各本作戶聲。篆亦作妒。今正。此如柘槖蠧等字皆以石爲聲。戶非聲也。當故切。五部。"}]},"媢":{"expl":"夫妒婦也。从女冒聲。一曰相視也。","rad":"女","fq":"莫報切","vol":"12","py":"mào","duan":[{"e":"夫妬婦也。","n":"大學曰。媢疾以惡之。鄭曰。媢、妬也。顏氏家訓曰。太史公論英布曰。禍之興自愛姬。生於妬媚。漢書外戚傳亦云。成結寵妾妬媚之誅。此二媚字竝當作媢。五宗世家亦云。常山憲王后妬媢。王充論衡云。妬夫媢婦生則忿怒鬬訟。按顏所舉、惟英布傳是此字本義。其餘皆與妬不分別。尙書衹作冒。"}]},"𡝩":{"expl":"巧也。一曰女子笑皃。《詩》曰：“桃之𡝩𡝩。”从女芺聲。","rad":"女","fq":"於喬切","vol":"12","py":"yāo","duan":[{"e":"巧也。","n":"此與䄏各字。今用𡝩爲䄏。非也。"}]},"佞":{"expl":"巧讇高材也。从女，信省。","rad":"女","fq":"乃定切","vol":"12","py":"nìnɡ","duan":[{"e":"巧讇高材也。","n":"巧者、技也。讇者、諛也。"}]},"嫈":{"expl":"小心態也。从女，熒省聲。","rad":"女","fq":"烏莖切","vol":"12","py":"yīnɡ","duan":[{"e":"小心態也。","n":"見嫇篆下。"}]},"嫪":{"expl":"婟也。从女翏聲。","rad":"女","fq":"郎到切","vol":"12","py":"lào","duan":[{"e":"婟也。","n":"聲類云。婟嫪、戀惜也。"}]},"婟":{"expl":"嫪也。从女固聲。","rad":"女","fq":"胡誤切","vol":"12","py":"hù","duan":[{"e":"嫪也。","n":"爾雅。鶭、澤虞。郭注。今婟澤鳥。常在澤中。見人輒鳴喚不去。按此二篆爲轉注。"}]},"姿":{"expl":"態也。从女次聲。","rad":"女","fq":"卽夷切","vol":"12","py":"zī","duan":[{"e":"態也。","n":"態者、意也。姿謂意態也。"}]},"喘":{"expl":"疾息也。从口耑聲。","rad":"口","fq":"昌沇切","vol":"02","py":"chuǎn","duan":[{"e":"疾息也。","n":"此分別言之。息下曰。喘也。渾言之也。"}]},"㜘":{"expl":"嬌也。从女虘聲。","rad":"女","fq":"將預切","vol":"12","py":"jù","duan":[{"e":"驕也。","n":"驕俗本作嬌。小徐不誤。古無嬌字。凡云嬌卽驕也。文選琴賦。或怨㜘而躊躇。幽憤詩。恃愛肆姐姐。卽㜘之省。李善皆引說文㜘、嬌也。與魏文帝箋。蹇姐名昌。姐亦㜘字。按心部怚、驕也。音義皆同。"}]},"妨":{"expl":"害也。从女方聲。","rad":"女","fq":"𢾭方切","vol":"12","py":"fánɡ","duan":[{"e":"害也。","n":"害者、傷也。"}]},"妄":{"expl":"亂也。从女亡聲。","rad":"女","fq":"巫放切","vol":"12","py":"wànɡ","duan":[{"e":"亂也。从女。亡聲。","n":"巫放切。十部。"}]},"媮":{"expl":"巧黠也。从女俞聲。","rad":"女","fq":"託矦切","vol":"12","py":"tōu","duan":[{"e":"巧黠也。","n":"按偷盜字當作此媮。"}]},"𡜂":{"expl":"𡜂鹵，貪也。从女污聲。","rad":"女","fq":"胡古切","vol":"12","py":"hù","duan":[{"e":"𡜡鹵、","n":"逗。㬪韵字。"}]},"娋":{"expl":"小小侵也。从女肖聲。","rad":"女","fq":"息約切","vol":"12","py":"shào","duan":[{"e":"小小㑴也。","n":"侵者、漸進也。凡用稍稍字、謂出物有漸。凡用娋娋字、謂以漸侵物也。方言。娋、姊也。方俗語也。"}]},"㛆":{"expl":"量也。从女朶聲。","rad":"女","fq":"丁果切","vol":"12","py":"duò","duan":[{"e":"量也。","n":"廣韵作挆。云稱量。"}]},"妯":{"expl":"動也。从女由聲。","rad":"女","fq":"徒歴切","vol":"12","py":"chōu","duan":[{"e":"動也。","n":"小雅。憂心且妯。釋詁、毛傳皆曰。妯、動也。箋云。妯之言悼也。方言。妯、擾也。人不靜曰妯。按心部引詩憂心且怞。"}]},"嫌":{"expl":"不平於心也。一曰疑也。从女兼聲。","rad":"女","fq":"戶兼切","vol":"12","py":"xián","duan":[{"e":"不平於心也。","n":"心部曰。慊、疑也。嫌與慊義別。"}]},"𡞞":{"expl":"減也。从女省聲。","rad":"女","fq":"所景切","vol":"12","py":"shěnɡ","duan":[{"e":"減也。","n":"減者、損也。按水部又曰。渻、少減也。然則𡞞渻音義皆同。作省者叚借字也。省行而𡞞渻廢矣。許書凡云省改皆作省。應以𡞞正之。"}]},"呼":{"expl":"外息也。从口乎聲。","rad":"口","fq":"荒烏切","vol":"02","py":"hū","duan":[{"e":"外息也。","n":"外息、出其息也。"}]},"婼":{"expl":"不順也。从女若聲。《春秋傳》曰：“叔孫婼。”","rad":"女","fq":"丑略切","vol":"12","py":"chuò","duan":[{"e":"不順也。","n":"毛詩傳曰。若、順也。此字从若則當訓順。而云不順也。此猶祀从巳、而訓祭無巳也。"}]},"婞":{"expl":"很也。从女幸聲。《楚詞》曰：“鯀婞直。”","rad":"女","fq":"胡頂切","vol":"12","py":"xìnɡ","duan":[{"e":"很也。","n":"很者、不聽從也。王逸離騷注同。"}]},"嫳":{"expl":"易使怒也。从女敝聲。讀若擊撆。","rad":"女","fq":"匹滅切","vol":"12","py":"piè","duan":[{"e":"易使怒也。","n":"廣韵。嫳、輕薄之皃。"}]},"嫸":{"expl":"好枝格人語也。一曰靳也。从女善聲。","rad":"女","fq":"旨善切","vol":"12","py":"zhǎn","duan":[{"e":"好枝𠲱人語也。","n":"枝𠲱見丯部。謂不欲人語、而言他以枝格之也。廣韵曰。嫸、偏忮。"}]},"娺":{"expl":"疾悍也。从女叕聲。讀若唾。","rad":"女","fq":"丁滑切","vol":"12","py":"zhuó","duan":[{"e":"疾悍也。","n":"敏疾而勇也。廣韵曰。婠娺、好皃。"}]},"㜝":{"expl":"含怒也。一曰難知也。从女酓聲。《詩》曰：“碩大且㜝。”","rad":"女","fq":"五感切","vol":"12","py":"ǎn","duan":[{"e":"含怒也。一曰難知也。从女。酓聲。","n":"五感切。七部。"}]},"娿":{"expl":"媕娿也。从女阿聲。","rad":"女","fq":"烏何切","vol":"12","py":"ē","duan":[{"e":"媕娿也。","n":"媕娿雙聲字。韵會作陰阿。李燾本作陰娿。集韵、類篇同。廣韵曰。媕娿不決。媕音庵。"}]},"姸":{"expl":"技也。一曰不省録事。一曰難侵也。一曰惠也。一曰安也。 从女幵聲。讀若研。","rad":"女","fq":"五堅切","vol":"12","py":"yán","duan":[{"e":"技也。","n":"技者、巧也。釋名曰。姸、硏也。硏精於事宜則無蚩繆也。蚩、癡也。按此爲今用姸媸字所本。方言。自關而西秦晉之故都謂好曰姸。"}]},"娃":{"expl":"圜深目皃。或曰吳楚之閒謂好曰娃。从女圭聲。","rad":"女","fq":"於佳切","vol":"12","py":"wā","duan":[{"e":"圜深目皃也。","n":"洼、深池也。窐、甑空也。凡圭聲字義略相似。"}]},"𨻤":{"expl":"不𡡾，前却𨻤𨻤也。从女陝聲。","rad":"女","fq":"失冉切","vol":"12","py":"shǎn","duan":[{"e":"不媚。歬卻𨻤𨻤也。","n":"後漢書。班昭女誡曰。動靜輕脫。視聽陜輸。陜輸、不定皃。"}]},"吸":{"expl":"内息也。从口及聲。","rad":"口","fq":"許及切","vol":"02","py":"xī","duan":[{"e":"內息也。","n":"內息、納其息也。"}]},"妜":{"expl":"鼻目閒皃。讀若煙火炔炔。从女，決省聲。","rad":"女","fq":"於說切","vol":"12","py":"yuè","duan":[{"e":"鼻目閒皃。","n":"謂若眉語目成然也。"}]},"孈":{"expl":"愚戇多態也。从女巂聲。讀若隓。","rad":"女","fq":"式吹切","vol":"12","py":"huì","duan":[{"e":"愚戇多態也。","n":"戇者、愚也。愚者、戇也。"}]},"㜇":{"expl":"不說也。从女恚聲。","rad":"女","fq":"於避切","vol":"12","py":"huì","duan":[{"e":"不說也。","n":"說者、今之悅字。心部曰。恚者、恨也。㜇从恚聲。形聲中有會意。"}]},"嫼":{"expl":"怒皃。从女黑聲。","rad":"女","fq":"呼北切","vol":"12","py":"mò","duan":[{"e":"怒皃。从女。黑聲。","n":"呼北切。一部。按此字廣韵烏黠切。嫉怒也。則黑非聲矣。玉篇莫勒切。奴也。奴者怒之誤。"}]},"𡛟":{"expl":"輕也。从女戉聲。","rad":"女","fq":"王伐切","vol":"12","py":"yuè","duan":[{"e":"輕也。从女。戉聲。","n":"王伐切。十五部。"}]},"嫖":{"expl":"輕也。从女𤐫聲。","rad":"女","fq":"匹招切","vol":"12","py":"piào","duan":[{"e":"輕也。","n":"與人部僄音義皆同。漢霍去病票姚校尉。票姚讀如飄搖。謂輕疾也。荀悅漢紀作票鷂。音亦同耳。古多平聲。後代乃多改爲去聲。師古讀頻妙羊召二切。殊失古意。證以杜子美詩。益可見矣。"}]},"㛗":{"expl":"訬疾也。从女𡋲聲。","rad":"女","fq":"昨禾切","vol":"12","py":"qiē","duan":[{"e":"訬疾也。","n":"訬者、訬擾也。漢書述曰。江都輕訬。謂輕薄爲訬也。㛗與訬雙聲。又女字也。穆天子傳。盛姬之喪。叔㛗爲主。"}]},"姎":{"expl":"女人自偁，我也。从女央聲。","rad":"女","fq":"烏浪切","vol":"12","py":"yānɡ","duan":[{"e":"女人自偁姎我也。","n":"各本我上奪姎。今補。後漢書西夷傳注、廣韵三十三蕩皆引女人自偁姎我。姎我聯文。如吳人自偁阿儂耳。"}]},"媁":{"expl":"不說皃。从女韋聲。","rad":"女","fq":"羽非切","vol":"12","py":"wéi","duan":[{"e":"不說皃。","n":"說今悅字。"}]},"婎":{"expl":"姿婎，姿也。从女隹也。一曰醜也。","rad":"女","fq":"許惟切","vol":"12","py":"huī","duan":[{"e":"姿婎、","n":"逗。㬪韵字。"}]},"噓":{"expl":"吹也。从口虛聲。","rad":"口","fq":"朽居切","vol":"02","py":"xū","duan":[]},"娹":{"expl":"有守也。从女弦聲。","rad":"女","fq":"胡田切","vol":"12","py":"xián","duan":[{"e":"有守也。从女。弦聲。","n":"胡田切。十二部。"}]},"媥":{"expl":"輕皃。从女扁聲。","rad":"女","fq":"芳連切","vol":"12","py":"piān","duan":[{"e":"輕皃。从女。扁聲。","n":"芳連切。十二部。"}]},"嫚":{"expl":"侮易也。从女曼聲。","rad":"女","fq":"謀患切","vol":"12","py":"màn","duan":[{"e":"侮㑥也。","n":"㑥各本作易。今正。人部曰。侮者、㑥也。㑥者、輕也。嫚與心部之慢音同義別。凡嫚人當用此字。"}]},"㛼":{"expl":"疾言失次也。从女臿聲。讀若懾。","rad":"女","fq":"丑聶切","vol":"12","py":"chā","duan":[{"e":"疾言失次也。","n":"所謂儳言。"}]},"嬬":{"expl":"弱也。一曰下妻也。从女需聲。","rad":"女","fq":"相俞切","vol":"12","py":"rú","duan":[{"e":"弱也。","n":"嬬之言濡也。濡、柔也。"}]},"娝":{"expl":"不肖也。从女否聲。讀若竹皮箁。","rad":"女","fq":"匹才切","vol":"12","py":"pōu","duan":[{"e":"不肖也。从女。否聲。讀若竹皮箁。","n":"箁、竹箬也。見竹部。匹才切。一部。篇、韵布美切。"}]},"嬯":{"expl":"遟鈍也。从女臺聲。闒嬯亦如之。","rad":"女","fq":"徒哀切","vol":"12","py":"tái","duan":[{"e":"遲鈍也。","n":"集韵。㦉當來切。卽此字也。今人謂癡如是。"}]},"㜤":{"expl":"下志貪頑也。从女覃聲。讀若深。","rad":"女","fq":"乃忝切","vol":"12","py":"niǎn","duan":[{"e":"下志貪頑也。从女。𪉷聲。讀如深。","n":"乃忝切。七部。篇、韵式荏切。"}]},"㜗":{"expl":"婪也。从女參聲。","rad":"女","fq":"七感切","vol":"12","py":"cǎn","duan":[{"e":"婪也。从女。參聲。","n":"七感切。七部。"}]},"婪":{"expl":"貪也。从女林聲。杜林說：卜者黨相詐驗爲婪。讀若潭。","rad":"女","fq":"盧含切","vol":"12","py":"lán","duan":[{"e":"貪也。","n":"此與心部之惏音義皆同。"}]},"嬾":{"expl":"懈也，怠也。一曰臥也。从女賴聲。","rad":"女","fq":"洛旱切","vol":"12","py":"lǎn","duan":[{"e":"懈也。","n":"懈者、怠也。集韵、類篇作懈也。怠也。非是。"}]},"婁":{"expl":"空也。从母、中、女，空之意也。一曰婁，務也。","rad":"女","fq":"洛矦切","vol":"12","py":"lóu","duan":[{"e":"空也。","n":"凡中空曰婁。今俗語尙如是。凡一實一虛、層見㬪出曰婁。人曰離婁。窗牖曰麗廔。是其意也。故婁之義又爲數也。此正如窗牖。麗廔之多孔也。而轉其音爲力住切。俗乃加尸旁爲屢字。古有婁無屢也。毛詩婁豐年傳曰。婁、亟也。亟者、數也。角弓式居婁驕箋云。婁、斂也。此則謂爲摟之叚借也。"}]},"娎":{"expl":"娎㛍也。从女折聲。","rad":"女","fq":"許列切","vol":"12","py":"xiè","duan":[{"e":"娎、㛍也。","n":"娎當是複舉字。玉篇云。娎、喜也。廣韵云。娎、喜皃。"}]},"㛍":{"expl":"得志㛍㛍。一曰㛍息也，一曰少气也。从女夾聲。","rad":"女","fq":"呼帖切","vol":"12","py":"qiè","duan":[{"e":"得志㛍㛍也。","n":"篇、韵皆云此義。邱協切。是與㥦音義皆同也。"}]},"嬈":{"expl":"苛也。一曰擾、戲弄也，一曰嬥也。从女堯聲。","rad":"女","fq":"奴鳥切","vol":"12","py":"niǎo","duan":[{"e":"苛也。","n":"苛者、小艸也。引申爲瑣碎之偁。玄應曰。苛、煩也。擾也。嬈亦惱也。苛音何可切。"}]},"𡢕":{"expl":"惡也。一曰人皃。从女毀聲。","rad":"女","fq":"許委切","vol":"12","py":"huǐ","duan":[{"e":"惡也。","n":"許意葢謂毁物爲毁。謗人爲？。"}]},"姍":{"expl":"誹也。一曰翼便也。从女，𠛹省聲。","rad":"女","fq":"所晏切","vol":"12","py":"shān","duan":[{"e":"誹也。","n":"漢書。姍笑三代。說者謂卽訕字也。"}]},"𡞜":{"expl":"醜也。一曰老嫗也。从女酋聲。讀若蹴。","rad":"女","fq":"七宿切","vol":"12","py":"cù","duan":[{"e":"醜也。","n":"醜者、可惡也。"}]},"𡠜":{"expl":"𡠜母，都醜也。从女莫聲。","rad":"女","fq":"莫胡切","vol":"12","py":"mó","duan":[{"e":"𡠜母、","n":"逗。母莫后切。"}]},"婓":{"expl":"往來婓婓也。一曰醜皃。从女非聲。","rad":"女","fq":"芳非切","vol":"12","py":"fēi","duan":[{"e":"往來婓婓也。","n":"當依廣韵作婓婓、往來皃。玉篇也亦作皃。小雅毛傳曰。騑騑、行不止之皃。與婓音義皆同。"}]},"喟":{"expl":"大息也。从口胃聲。","rad":"口","fq":"丘貴切","vol":"02","py":"kuì","duan":[{"e":"大息也。","n":"論語㒳云喟然歎曰。謂大息而吟歎也。何晏云。喟然、歎聲也。殊非是。"}]},"孃":{"expl":"煩擾也。一曰肥大也。从女襄聲。","rad":"女","fq":"女良切","vol":"12","py":"ránɡ","duan":[{"e":"煩𢺕也。","n":"煩、熱頭痛也。𢺕、煩也。今人用擾攘字、古用孃。賈誼傳作搶攘。莊子在宥作傖囊。楚詞作恇攘。俗作劻勷。皆用叚借字耳。今攘行而孃廢矣。又按廣韵孃女良切、母稱。娘亦女良切、少女之号。唐人此二字分用畫然。故耶孃字斷無有作娘者。今人乃罕知之矣。"}]},"嬒":{"expl":"女黑色也。从女會聲。《詩》曰：“嬒兮蔚兮。”","rad":"女","fq":"古外切","vol":"12","py":"huì","duan":[{"e":"女黑色也。","n":"黑部曰。䵳、沃黑色也。音同義近。"}]},"媆":{"expl":"好皃。从女耎聲。","rad":"女","fq":"而沇切","vol":"12","py":"ruǎn","duan":[{"e":"好皃。","n":"此謂柔耎之好也。補前文諸好所未備。"}]},"㛪":{"expl":"誣挐也。从女奄聲。","rad":"女","fq":"依劎切","vol":"12","py":"yàn","duan":[{"e":"誣挐也。","n":"方言。挐、揚州會稽之語也。或謂之惹。或謂之䛳。注言誣䛳也。又曰。誣、䛳、與也。吳越曰誣。荆齊曰䛳。與猶秦晉言阿與也。按㛪䛳同字。挐上从如。李仁甫本如是。廣韵同。"}]},"㜮":{"expl":"過差也。从女監聲。《論語》曰：“小人窮斯㜮矣。”","rad":"女","fq":"盧瞰切","vol":"12","py":"làn","duan":[{"e":"過差也。","n":"差忒者、不相值也。凡不得其當曰過差。亦曰㜮。今字多以濫爲之。商頌。不僭不濫。傳曰。賞不僭、㓝不濫也。左氏曰。賞僭則懼及淫人。㓝濫則懼及善人。其字皆可作㜮。濫行而㜮廢矣。"}]},"嫯":{"expl":"侮易也。从女敖聲。","rad":"女","fq":"五到切","vol":"12","py":"ào","duan":[{"e":"侮㑥也。","n":"㑥各本作易。非是。前文曰嫚、侮㑥也。字與慢別。此云嫯、侮㑥也。字與傲別。今則傲行而嫯廢矣。"}]},"婬":{"expl":"私逸也。从女㸒聲。","rad":"女","fq":"余箴切","vol":"12","py":"yín","duan":[{"e":"厶逸也。","n":"厶作私。非也。今正。厶音私。姦衺也。逸者、失也。失者、緃逸也。婬之字今多以淫代之。淫行而婬廢矣。"}]},"姘":{"expl":"除也。漢律：“齊人予妻婢姦曰姘。”从女幷聲。","rad":"女","fq":"普耕切","vol":"12","py":"pīn","duan":[{"e":"除也。","n":"按詩作之屛之。其葘其翳。論語曰。屛四惡。屛皆謂除也。依許則屛、蔽也。姘、除也。義各有當。經傳皆用屛。屛行而姸廢矣。莊子。至貴國爵幷焉。注。幷、棄除也。是又叚幷爲之。"}]},"奸":{"expl":"犯婬也。从女从干，干亦聲。","rad":"女","fq":"古寒切","vol":"12","py":"jiān","duan":[{"e":"犯婬也。","n":"此字謂犯姦婬之罪。非卽姦字也。今人用奸爲姦、失之。引申爲凡有所犯之偁。左傳多用此字。如二君有事、臣奸旗𡔷之類。"}]},"姅":{"expl":"婦人汚也。从女半聲。漢律：“見姅變，不得侍祠。”","rad":"女","fq":"博幔切","vol":"12","py":"bàn","duan":[{"e":"婦人污也。","n":"謂月事及免身及傷孕皆是也。廣韵曰。姅、傷孕也。傷孕者、懷子傷也。"}]},"瓘":{"expl":"玉也。从玉雚聲。《春秋傳》曰：“瓘斚。”","rad":"玉","fq":"工玩切","vol":"01","py":"ɡuàn","duan":[{"e":"玉也。","n":"左氏傳。齊有陳瓘。字子玉。"}]},"啍":{"expl":"口气也。从口𦎫聲。《詩》曰：“大車啍啍。”","rad":"口","fq":"他昆切","vol":"02","py":"tūn","duan":[{"e":"口气也。从口。𦎧聲。","n":"他昆切。十三部。"}]},"娗":{"expl":"女出病也。从女廷聲。","rad":"女","fq":"徒鼎切","vol":"12","py":"tǐnɡ","duan":[{"e":"女出病也。","n":"按病下當有容字。廣雅曰。娗娫、容也。然則謂女出而病容娗娗然也。廣韵有娗無婷。唐喬知之、杜甫詩皆用娉婷字。娉婷皆讀平聲。疑娗婷同字。長好皃。"}]},"婥":{"expl":"女病也。从女卓聲。","rad":"女","fq":"奴教切","vol":"12","py":"nào","duan":[{"e":"女病也。","n":"廣韵曰。婥約、美皃。此今字今義也。"}]},"娷":{"expl":"諉也。从女垂聲。","rad":"女","fq":"竹恚切","vol":"12","py":"zhuì","duan":[{"e":"諉也。","n":"言部曰。諈諉、絫也。又曰。諉、絫也。按絫者、若今言以此累人也。娷與諈音義皆同。可附見於言部。"}]},"㛴":{"expl":"有所恨也。从女纴聲。今汝南人有所恨曰㛴。","rad":"女","fq":"奴皓切","vol":"12","py":"nǎo","duan":[{"e":"有所𢚉痛也。","n":"𢚉者、怨也。痛者、病也。"}]},"媿":{"expl":"慙也。从女鬼聲。","rad":"女","fq":"俱位切","vol":"12","py":"kuì","duan":[{"e":"慙也。","n":"慙下曰。媿也。二篆爲轉注。亦考老之例。"}]},"奻":{"expl":"訟也。从二女。","rad":"女","fq":"女還切","vol":"12","py":"nuán","duan":[{"e":"訟也。从二女。","n":"訟者、爭也。周易睽傳曰。二女同居。其志不同行。革傳曰。二女同居。其志不相得。此奻从二女之意也。女還切。十四部。"}]},"姦":{"expl":"私也。从三女。","rad":"女","fq":"古顔切","vol":"12","py":"jiān","duan":[{"e":"厶也。","n":"厶下曰。姦衺也。二篆爲轉注。引申爲凡姦宄之偁。俗作姧。其後竟用奸字。"}]},"嬙":{"expl":"婦官也。从女，牆省聲。","rad":"女","fq":"才良切","vol":"12","py":"qiánɡ","duan":[]},"妲":{"expl":"女字。妲己，紂妃。从女旦聲。","rad":"女","fq":"當割切","vol":"12","py":"dá","duan":[]},"嬌":{"expl":"姿也。从女喬聲。","rad":"女","fq":"舉喬切","vol":"12","py":"jiāo","duan":[]},"嚏":{"expl":"悟解气也。从口疐聲。《詩》曰：“願言則嚏。”","rad":"口","fq":"都計切","vol":"02","py":"tì","duan":[{"e":"悟解气也。","n":"悟解气者，欠字下云張口气悟是也。悟，覺也。解，散也。通俗文曰。張口運气謂之欠。鄭注周易百果艸木皆甲坼曰。皆，讀爲人倦解之解。郭注方言蛤解曰。解，讀解悟聲之解。皆是許意。嚔與欠異音同義。玉裁按。許說嚔義非是。不必曲侚。嚔之見於月令，內則者各一。鄭氏終風箋曰。疐讀當爲不敢嚔咳之嚔。今俗人嚔云人道我。此古之遺語也。月令。民多鼽嚔。謂鼻塞而妨嚔。說文噴下一曰𡔷鼻。而釋嚔爲欠。直以其字从口不从鼻故耳。殊不思內則旣云不敢嚔。又云不敢欠。其爲二事憭然。素問說五气所病。腎爲欠爲嚔。亦分二事。倘云嚔卽是欠。則內則，素問皆不可通矣。故嚔解當改云歕鼻也爲安。口與鼻同時气出。此字之所以从口也。至若詩願言則疐。毛傳云。"}]},"嬋":{"expl":"嬋娟，態也。从女單聲。","rad":"女","fq":"市連切","vol":"12","py":"chán","duan":[]},"娟":{"expl":"嬋娟也。从女肙聲。","rad":"女","fq":"於緣切","vol":"12","py":"juān","duan":[]},"嫠":{"expl":"無夫也。从女𠩺聲。","rad":"女","fq":"里之切","vol":"12","py":"lí","duan":[]},"姤":{"expl":"偶也。从女后聲。","rad":"女","fq":"古候切","vol":"12","py":"ɡòu","duan":[]},"毋":{"expl":"止之也。从女，有奸之者。凡毋之屬皆从毋。","rad":"毋","fq":"武扶切","vol":"12","py":"wú","duan":[{"e":"止之䛐也。","n":"䛐依禮記釋文補。䛐者、意內而言外也。其意禁止、其言曰毋也。古通用無。詩書皆用無。士昏禮。夙夜毋違命。注曰。古文毋爲無。是古文禮作無、今文禮作毋也。漢人多用毋。故小戴禮記、今文尙書皆用毋。史記則竟用毋爲有無字。○又按詩毋敎猱𦫵木。字作毋。鄭箋。毋、禁辭。"}]},"毐":{"expl":"人無行也。从士从毋。賈侍中說：秦始皇母與嫪毐淫，坐誅，故世罵淫曰嫪毐。讀若娭。","rad":"毋","fq":"遏在切","vol":"12","py":"ǎi","duan":[{"e":"士之無行者。","n":"各本作人無行也。今依顏氏五行志注所引正。士之無行者、故其字从士毋。古多叚毋爲有無字。毋卽無。婁之訓空也、亦从毋會意。毐之本義如此。非爲嫪毐造此字也。"}]},"民":{"expl":"眾萌也。从古文之象。凡民之屬皆从民。","rad":"民","fq":"彌鄰切","vol":"12","py":"mín","duan":[{"e":"眾𦹩也。","n":"萌古本皆不誤。毛本作氓。非。古謂民曰萌。漢人所用不可枚數。今周禮以興耡利甿。許耒部引以興耡利萌。愚謂鄭本亦作萌。故注云變民言萌、異外內也。萌猶懵懵無知皃也。鄭本亦斷非甿字。大氐漢人萌字、淺人多改爲氓。如周禮音義此節摘致氓是也。繼又改氓爲甿。則今之周禮是也。說詳漢讀攷、民萌異者、析言之也。以萌釋民者、渾言之也。"}]},"氓":{"expl":"民也。从民亡聲。讀若盲。","rad":"民","fq":"武庚切","vol":"12","py":"ménɡ","duan":[{"e":"民也。","n":"詩。氓之蚩蚩。傳曰。氓、民也。方言亦曰。氓、民也。孟子。則天下之民皆悅而願爲之氓矣。趙注。氓者、謂其民也。按此則氓與民小別。葢自他歸往之民則謂之氓。故字从民亡。"}]},"丿":{"expl":"右戾也。象左引之形。凡丿之屬皆从丿。","rad":"丿","fq":"房密切","vol":"12","py":"piě","duan":[{"e":"又戾也。象𠂇引之形。","n":"又𠂇各本作右左。今正。戾者、曲也。右戾者、自右而曲於左也。故其字象自左方引之。丿音義略同撆、書家八法謂之掠。房密切。又匹蔑切。十五部。"}]},"乂":{"expl":"芟艸也。从丿从乀，相交。","rad":"丿","fq":"魚廢切","vol":"12","py":"yì","duan":[{"e":"芟艸也。","n":"艸部曰。芟、㐅艸也。二篆爲轉注。周南曰。是刈是濩。周頌曰。奄觀銍艾。艾者、㐅之叚借字。銍者、所以㐅也。禾部曰。穫、㐅榖也。是則芟艸穫榖總謂之㐅。鄭箋詩云。芟末曰艾。刀部有𠛎。金部有鎌、有鍥。所以芟艸也。銍則穫禾短鎌也。引申之、㐅訓治也。見諸經傳。許辟部云。䢃、治也。引唐書有能俾䢃。則䢃爲正字。"}]},"𡂒":{"expl":"野人言之。从口質聲。","rad":"口","fq":"之日切","vol":"02","py":"zhì","duan":[{"e":"野人之言。","n":"論語曰。質勝文則野。此字會意兼形聲。"}]},"弗":{"expl":"撟也。从丿从乀，从韋省。","rad":"丿","fq":"分勿切","vol":"12","py":"fú","duan":[{"e":"矯也。","n":"矯各本作撟。今正。撟者、舉手也。引申爲高舉之用。矯者、揉箭箝也。引申爲矯拂之用。今人不能辯者久矣。弗之訓矯也。今人矯、弗皆作拂。而用弗爲不。其誤葢亦久矣。公羊傳曰。弗者、不之深也。固是矯義。凡經傳言不者其文直。言弗者其文曲。如春秋公孫敖如京師、不至而復。晉人納捷葘于邾、弗克納。弗與不之異也。禮記。雖有嘉肴。弗食不知其旨也。雖有至道。弗學不知其善也。弗與不不可互易。"}]},"乀":{"expl":"左戾也。从反丿。讀與弗同。","rad":"丿","fq":"分勿切","vol":"12","py":"fú","duan":[{"e":"𠂇戾也。从反丿。讀與弗同。","n":"自左而曲於右。故其字象自右方引之。丶音義略同拂。書家八法謂之磔。分勿切。十五部。或問丶篆何以不次㐅弗之前也。曰此以丿爲部首。故必从丿字列畢而後列皮背之形。㐅弗皆系之从丿也。"}]},"𠂆":{"expl":"抴也。明也。象抴引之形。凡𠂆之屬皆从𠂆。虒字从此。","rad":"𠂆","fq":"余制切","vol":"12","py":"yì","duan":[{"e":"抴也。","n":"抴者、捈也。捈者、臥引也。臥引者、横引之。"}]},"弋":{"expl":"橜也。象折木衺銳著形。从𠂆，象物挂之也。","rad":"𠂆","fq":"與職切","vol":"12","py":"yì","duan":[{"e":"橜也。","n":"木部橜下曰。弋也。二篆爲轉注。爾雅曰。橜謂之杙。按俗用杙爲弋。顧用弋爲隿射字。其誤久矣。杙者、劉劉杙也。不爲橜弋字。弋象形。故不从木也。"}]},"乁":{"expl":"流也。从反𠂆。讀若移。凡乁之屬皆从乁。","rad":"乁","fq":"弋支切","vol":"12","py":"yí","duan":[{"e":"流也。从反厂。讀若移。","n":"移从多聲。在十七部。亦用於十六部。乁與𠂆古音同在十六部也。弋支切。"}]},"也":{"expl":"女陰也。象形。","rad":"乁","fq":"羊者切","vol":"12","py":"yě","duan":[{"e":"女侌也。","n":"此篆女陰是本義。叚借爲語䛐。本無可疑者。而淺人妄疑之。許在當時必有所受之。不容以少見多怪之心測之也。"}]},"氏":{"expl":"巴蜀山名岸脅之㫄箸欲落𡐦者曰氏，氏崩，聞數百里。象形，乀聲。凡氏之屬皆从氏。楊雄賦：響若氏隤。","rad":"氏","fq":"承旨切","vol":"12","py":"shì","duan":[{"e":"巴蜀名山岸脅之𠂤旁箸欲落𡐦者曰氏。","n":"十六字爲一句。此謂巴蜀方語也。𠂤大徐無。小徐作堆。俗字耳。今正。𠂤、小𨸏也。箸直略切。小𨸏之旁箸於山岸脅、而狀欲落墮者曰氏。其字亦作坁。亦作？。𨸏部曰。秦謂陵阪曰？。？與氏音義皆同。楊雄解嘲曰。響若坁隤。應劭曰。天水有大坂。名曰隴坁。其山堆傍箸崩落作聲聞數百里。故曰坁隤。韋昭曰。坁音若是理之是。以上見文選注。今本漢書作？隤。師古曰。？音氏。巴蜀名山旁堆欲墮落曰氏。應劭以爲天水隴氐。失之矣。氐音丁禮反。玉裁按顏說殊非古。隴？亦作隴坁。與巴蜀之氏形小異、而音義皆同。？坁字同氏聲。或从氐聲而丁禮切者、字之誤也。劉逵注吳都賦坁頹曰。天水之大阪。名曰隴坁。因爲隴坁之曲說。與應仲遠同。坁、韋音是。？、顏音"}]},"氒":{"expl":"木本。从氏。大於末。讀若厥。","rad":"氏","fq":"居月切","vol":"12","py":"jué","duan":[{"e":"木本也。","n":"木部曰。木下曰本。本亦曰？。？者、言其？然大也。古多用橜弋字爲之。列子曰。吾處也若橜株駒。株駒、木？也。殷敬順曰。橜、說文作身。按玉篇亦作身。𣜩變也。"}]},"氐":{"expl":"至也。从氏下箸一。一，地也。凡氐之屬皆从氐。","rad":"氐","fq":"丁礼切","vol":"12","py":"dǐ","duan":[{"e":"至也。","n":"氐之言抵也。凡言大氐、猶大都也。"}]},"𣱐":{"expl":"臥也。从氐垔聲。","rad":"氐","fq":"於進切","vol":"12","py":"yìn","duan":[{"e":"臥也。","n":"按篇、韵皆音印。又音致。仆也。疑認爲氐聲而易其音耳。"}]},"唫":{"expl":"口急也。从口金聲。","rad":"口","fq":"巨錦切","vol":"02","py":"jìn","duan":[{"e":"口急也。从口。金聲。","n":"巨錦切。七部。"}]},"㲳":{"expl":"觸也。从氐失聲。","rad":"氐","fq":"徒結切","vol":"12","py":"dié","duan":[{"e":"觸也。","n":"廣韵。陟栗切。手拔物也"}]},"𣱓":{"expl":"闕。","rad":"氐","fq":"","vol":"12","py":"xiào","duan":[{"e":"闕。","n":"小徐作家本無注。鍇云。一本無此篆。此云家本無注、疑許沖之言也。按廣雅釋詁云。？、誤也。曹憲乎孝反。然則其字从氐、學省聲。形音義皆可攷。篇、韵音晧。古音在三部。"}]},"戈":{"expl":"平頭𢧢也。从弋，一橫之。象形。凡戈之屬皆从戈。","rad":"戈","fq":"古禾切","vol":"12","py":"ɡē","duan":[{"e":"平頭𢧢也。","n":"攷工記。冶氏爲戈。廣二寸。內倍之。胡三之。援四之。倨句外博。重三鋝。鄭曰。戈、今句孑戟也。或謂之雞鳴。或謂之擁頸。內謂胡以內接柲者也。長四寸。胡六寸。援八寸。戈、句兵也。主於胡也。俗謂之曼胡以此。鄭司農云。援、直刃也。胡其孑。按依先鄭戈有直刃、則非平頭也。宋黃氏伯思始疑鄭注。近程氏瑤田攷戈刃如劔横出而稍倨。所謂援八寸也。援之下近柲爲胡。連上爲刃。所謂胡六寸也。其横毌於柲而外出者凡四寸。所謂內倍之也。戈戟之金非冒於柲之首。皆爲之內。横毌外出。且於胡之近柲處爲三孔。纏縛於柲以固之。古戈戟時有存者。覈之可知也。說詳通藝錄。按許說戈爲平頭戟。从戈以一象之。然則戈刃之横出無疑也。横出故謂之援。援、引也。"}]},"肈":{"expl":"上諱。","rad":"戈","fq":"直小切","vol":"12","py":"zhào","duan":[{"e":"上諱。","n":"按許原書無篆體。但言上諱。後人乃補此篆。說詳示部。上諱者、漢和帝諱也。後漢書作肈。李賢引伏無忌古今注曰。肈之字曰始。音兆。許愼說文肈音大小反。上諱也。伏、許竝漢時人。而帝諱不同。葢應別有所據。玉裁按古有肈無肇。从戈之肈、漢碑或从殳。俗乃从攵作肇。而淺人以竄入許書攴部中。玉篇曰。肇俗肈字。五經文字戈部曰。肈作肇、訛。廣韵有肈無肇。伏侯作古今注時𣃔無从攵之肇。李賢注後漢書亦𣃔不至認肈肇爲二字。葢伏侯作肁、與許作肈不同。和帝命名之義取始。肁者、始開也。引申爲凡始。故伏云諱肁、而易之之字作始。實則漢人肁字不行。衹用肈字訓始。如詩生民傳、夏小正傳可證。外閒所諱者肈也。故許云諱肈此則伏、許不同之由。章懷之"}]},"𢦦":{"expl":"兵也。从戈从甲。","rad":"戈","fq":"如融切","vol":"12","py":"rónɡ","duan":[{"e":"兵也。","n":"兵者、械也。月令。乃敎於田獵。以習五戎。注。五戎謂五兵。弓矢、殳、矛、戈、戟也。按周禮司兵掌五兵。鄭司農云。戈、殳、戟、酋矛、夷矛。後鄭云。此車之五兵也。步卒之五兵、則無夷矛而有弓矢。兵之引申爲車卒、步卒。故戎之引申亦爲卒旅。兵可相助。故引申之義、小雅丞也無戎傳曰戎、相也。又引申爲戎狄之戎。又民勞傳。戎、大也。方言。戎、大也。宋魯陳衞之閒語。又鄭詩箋云。戎猶女也。猶之云者、以戎汝雙聲而通之也。戎有讀若汝者、常武之詩是也。又有讀若輮者、常棣之詩是也。"}]},"戣":{"expl":"《周禮》：侍臣執戣，立于東垂。兵也。从戈癸聲。","rad":"戈","fq":"渠追切","vol":"12","py":"kuí","duan":[{"e":"周制。侍臣執戣。立於東𡍮。兵也。","n":"見周書顧命。某氏傳曰。戣瞿皆戟屬。鄭云。戣瞿葢今三鋒矛。王肅則曰。皆平器之名。許不言何兵。略同子雍也。"}]},"𢧀":{"expl":"盾也。从戈旱聲。","rad":"戈","fq":"矦旰切","vol":"12","py":"ɡān","duan":[{"e":"盾也。","n":"盾下曰。瞂也。按瞂字必淺人所改。循全書之例、必當云？也。二篆爲轉注。淺人不識？爲干戈字。讀侯旰切。乃改爲瞂。瞂見毛詩。非常語。不當以瞂釋盾。干戈字本作？。干、犯也。？、盾也。俗多用干代？。干行而？廢矣。方言。盾、自關而東或謂之瞂。或謂之干。關西謂之盾。孔安國論語注云。干、盾也。？本讀如干。淺人以其旱聲。乃讀與？同。而不知旱？？等字古音皆讀同干也。毛詩兔罝、采𦬊傳云。干、扞也。謂干爲扞之叚借。干非不可去聲。"}]},"𢧢":{"expl":"有枝兵也。从戈、倝。《周禮》：“𢧢，長丈六尺。”讀若棘。","rad":"戈","fq":"紀逆切","vol":"12","py":"jǐ","duan":[{"e":"有枝兵也。","n":"兵者、械也。枝者、木別生條也。戟爲有枝之兵。則非若戈之平頭。而亦非直刃似木枝之衺出也。戈刃之倨句平而稍侈、故曰外博。戟則大侈倨句一矩有半、故可刺可句。攷工記冶氏。戟廣寸有半寸。內三之。胡四之。援五之。倨句中矩。與刺重三鋝。鄭曰。戟、今三鋒戟也。內長四寸半。胡長六寸。援長七寸半。三鋒者胡直中矩言正方也。鄭司農云。刺謂援也。玄謂刺者、箸柲直前如鐏者也。戟胡横貫之。胡中矩、則援之外句磬折與。通藝錄曰。內三之、謂戟柄横出柲外者四寸有半也。胡四之、謂上連刃直而下垂者長六寸也。援五之、謂衺上之刃長七寸半也。刺者、謂横出之內有鋒也。倨句中矩者、謂刺横胡直正方之形也。不言援之倨句言刺之倨句者、戟爲句兵。中矩者"}]},"戛":{"expl":"𢧢也。从戈从𦣻。讀若棘。","rad":"戈","fq":"古黠切","vol":"12","py":"jiá","duan":[{"e":"𢧢也。","n":"廣雅曰。戛、戟也。本此。西京賦。立戈迆戛。薛解云。戈謂句孑戟也。戛、長矛也。與許不合。康誥。不率大戛。釋詁。戛、常也。此謂戛同楷。皋陶暮。戛擊鳴球。明堂位作揩擊。揚雄賦作拮隔。此謂戛同扴。皆六書中之叚借。"}]},"賊":{"expl":"敗也。从戈則聲。","rad":"戈","fq":"昨則切","vol":"12","py":"zéi","duan":[{"e":"敗也。","n":"敗者、毁也。毁者、缺也。左傳。周公作誓命曰。毁則爲賊。又叔向曰。殺人不忌爲賊。"}]},"噤":{"expl":"口閉也。从口禁聲。","rad":"口","fq":"巨禁切","vol":"02","py":"jìn","duan":[{"e":"口閉也。","n":"史淮陰矦傳。雖有舜禹之智。吟而不言。此假吟爲噤也。吟噤義相似。"}]},"戍":{"expl":"守邊也。从人持戈。","rad":"戈","fq":"傷遇切","vol":"12","py":"shù","duan":[{"e":"守邊也。","n":"春秋曰。公子買戍衞。"}]},"戰":{"expl":"鬬也。从戈單聲。","rad":"戈","fq":"之扇切","vol":"12","py":"zhàn","duan":[{"e":"鬥也。","n":"鬥各本作鬬。今正。鬥者、㒳士相對。兵杖在後也。左傳曰。皆陳曰戰。戰者、聖人所愼也。故引申爲戰懼。"}]},"戲":{"expl":"三軍之偏也。一曰兵也。从戈䖒聲。","rad":"戈","fq":"香義切","vol":"12","py":"xì","duan":[{"e":"三軍之偏也。","n":"偏若先偏後伍、偏爲前拒之偏。謂軍所駐之一面也。史漢項羽紀、高帝紀皆曰。諸侯罷戲下。各就國。師古曰。戲、軍之旌旗也。音許宜反。亦讀曰麾。又竇田灌韓傳。灌夫率壯士兩人。及從奴十餘騎。馳入吳軍。至戲下。所殺傷數十人。師古曰。戲、大將之麾也。讀與麾同。又音許宜反。按顏說必本舊音義。似與許說小異。然相去不遠。度舊音義必有用許說者矣。"}]},"𢧄":{"expl":"利也。一曰剔也。从戈呈聲。","rad":"戈","fq":"徒結切","vol":"12","py":"dié","duan":[{"e":"利也。","n":"利者、銛也。"}]},"或":{"expl":"邦也。从囗从戈，以守一。一，地也。","rad":"戈","fq":"于逼切","vol":"12","py":"yù","duan":[{"e":"邦也。","n":"邑部曰。邦者、國也。葢或國在周時爲古今字。古文衹有或字。旣乃復製國字。以凡人各有所守。皆得謂之或。各守其守、不能不相疑。故孔子曰。或之者、疑之也。而封建日廣。以爲凡人所守之或字未足盡之。乃又加囗而爲國。又加心爲惑。以爲疑惑當別於或。此孶乳寖多之理也。旣有國字。則國訓邦、而或但訓有。漢人多以有釋或。毛公之傳詩商頌也。曰域、有也。傳大雅也。曰囿、所以域養禽獸也。域卽或。攷工記梓人注。或、有也。小雅天保箋、鄭論語注皆云。或之言有也。高誘注淮南屢言或、有也。毛詩九有、韓詩作九域。緯書作九囿。葢有、古音如以。或、古音同域。相爲平入。"}]},"𢧵":{"expl":"斷也。从戈雀聲。","rad":"戈","fq":"昨結切","vol":"12","py":"jié","duan":[{"e":"𣃔也。","n":"斤部曰。𣃔者、𢧵也。二篆爲轉注。商頌。九有有𢧵。箋云。九州齊壹𢧵然。大雅。𢧵彼淮浦。傳云。𢧵、治也。"}]},"𢦟":{"expl":"殺也。从戈今聲。《商書》曰：“西伯旣𢦟黎。”","rad":"戈","fq":"口含切","vol":"12","py":"kān","duan":[{"e":"殺也。","n":"殺者、戮也。按漢、魏、六朝人𢦟堪戡龕四字不甚區別。左傳王心弗堪、漢五行志作王心弗𢦟。勝也。"}]},"戕":{"expl":"搶也。他國臣來弑君曰戕。从戈爿聲。","rad":"戈","fq":"士良切","vol":"12","py":"qiānɡ","duan":[{"e":"槍也。","n":"槍者、歫也。歫謂相抵爲害。小雅。曰子不戕。傳曰。戕、殘也。此戕之正義。下又稱左氏例、爲別一義。"}]},"戮":{"expl":"殺也。从戈翏聲。","rad":"戈","fq":"力六切","vol":"12","py":"lù","duan":[{"e":"殺也。","n":"殺下曰。戮也。二篆爲轉注。古文或叚翏爲之。又勠力字亦叚戮爲勠。"}]},"戡":{"expl":"刺也。从戈甚聲。","rad":"戈","fq":"竹甚切","vol":"12","py":"kān","duan":[{"e":"刺也。","n":"刺者、直傷也。平直皆得云刺。經史多叚此爲堪勝字。"}]},"名":{"expl":"自命也。从口从夕。夕者，冥也。冥不相見，故以口自名。","rad":"口","fq":"武并切","vol":"02","py":"mínɡ","duan":[{"e":"自命也。","n":"祭統曰。夫鼎有銘。銘者、自名也。此許所本也。周禮小祝故書作銘。今書或作名。士喪禮古文作銘。今文皆爲名。按死者之銘。以緇長半幅。緽末長終幅。廣三寸。書名于末曰。某氏某之柩。此正所謂自名。其作器刻銘。亦謂稱揚其先祖之德。著己名於下。皆衹云名已足。不必加金旁。故許君於金部不錄銘字。從周宫今書、禮今文也。許意凡經傳銘字皆當作名矣。鄭君注經乃釋銘爲刻。劉熙乃云。銘、名也。記名其功也。吕忱乃云。銘、題勒也。不用許說。"}]},"戭":{"expl":"長搶也。从戈寅聲。《春秋傳》有擣戭。","rad":"戈","fq":"弋刃切","vol":"12","py":"yǎn","duan":[{"e":"長槍也。","n":"槍者、歫也。謂以長物相刺。通俗文曰。剡木傷盗曰槍。按槍非古兵器。戭亦非器名。取槍歫之義耳。今之用金曰槍者、則古之矛也。故戭字廁於此。不與器物爲伍。"}]},"𢦔":{"expl":"傷也。从戈才聲。","rad":"戈","fq":"祖才切","vol":"12","py":"zāi","duan":[{"e":"傷也。","n":"傷者、刅也。此篆與烖葘音同而義相近。謂受刅也。"}]},"戩":{"expl":"滅也。从戈晉聲。《詩》曰：“實始戩商。”","rad":"戈","fq":"卽淺切","vol":"12","py":"jiǎn","duan":[{"e":"滅也。","n":"滅者、盡也。盡之義兼美惡。故滅之義亦兼美惡。凡盡皆得云滅。亦皆得云戩也。天保曰。俾爾戩穀。朱子曰。戩、盡也。穀、善也。此注甚合古義。爾雅。履、戩、祓、福也。此謂樛木之福履、天保之戩穀、卷阿之祓祿皆得訓福。履本不訓福。與福連文、則可訓福矣。戩祓本不訓福。與穀祿連文、則亦可訓福矣。皆於㒳字摘一字以釋㒳字之義。毛公仍之曰戩、福也。而履祿也、茀小也、則不相襲矣。古人之文、貴善讀之。所謂不以文害辭、不以辭害志。許於戩不襲爾雅、毛傳。斯善讀爾雅、毛傳者也。今之能善讀者葢尟矣。"}]},"㦰":{"expl":"絕也。一曰田器。从从持戈。古文讀若咸。讀若《詩》云“攕攕女手”。","rad":"戈","fq":"子廉切","vol":"12","py":"jiān","duan":[{"e":"絕也。","n":"絕者、刀𣃔絲也。引申爲凡𣃔之稱。𣃔之亦曰㦰。與殲義相近。"}]},"武":{"expl":"楚莊王曰：“夫武，定功戢兵。故止戈爲武。”","rad":"戈","fq":"文甫切","vol":"12","py":"wǔ","duan":[{"e":"楚莊王曰。","n":"莊、上諱也。不當用。古莊壯通用。謚法固取壯非取艸。周書。兵甲亟作、莊。睿圉克服、莊。勝敵志強、莊。武而不遂、莊。皆壯字也。後人以莊代之耳。此莊王必本作壯。若諱莊之字曰嚴、乃漢法。許則從左氏古文。典下云。莊都說。亦當作壯。晉語有壯馳茲。葢古姓本作壯。後乃盡改爲莊。"}]},"戢":{"expl":"藏兵也。从戈咠聲。《詩》曰：“載戢干戈。”","rad":"戈","fq":"阻立切","vol":"12","py":"jí","duan":[{"e":"臧兵也。","n":"周頌時邁曰。載戢干戈。載櫜弓矢。傳曰。戢、聚也。櫜、韜也。聚與藏義相成。聚而藏之也。戢與輯音同。輯者、車輿也。可聚諸物。故毛訓戢爲聚。周南傳亦云。揖揖、會聚也。周語。夫兵戢而時動。動則威。觀則玩。玩則無震。戢與觀正相對。故許易毛曰藏。以其字从戈。故曰藏兵。"}]},"戠":{"expl":"闕。从戈从音。","rad":"戈","fq":"之弋切","vol":"12","py":"zhī","duan":[{"e":"闕。从戈从音。","n":"大徐如此。小徐無从戈从音。有職從此古職字古之職役皆執干戈十四字。葢後人箋記之語。非許語也。其義其音皆葢闕矣。攷周易朋盍簪。虞翻本簪作戠。云戠、聚會也。舊讀作撍、作宗。釋文云。荀作撍。京作宗。陰弘道云。張揖字詁𢈻撍同字。按此戠當以音爲聲。故與朁聲疌聲爲伍。然尙書厥土赤埴、古文作赤戠。是戠固在古音弟一部也。一部內意亦从音。音未必非聲。葢七部與一部合韵之理。之弋切。一部。"}]},"戔":{"expl":"賊也。从二戈。《周書》曰：“戔戔巧言。”","rad":"戈","fq":"昨千切","vol":"12","py":"cán","duan":[{"e":"賊也。","n":"此與殘音義皆同。故殘用以會意。今則殘行而戔廢矣。篇、韵皆云傷也。殘與？通。故周禮注曰。雖其潘灡戔餘不可褻也。周易。束帛戔戔。子夏傳作殘殘。皆？餘之意也。"}]},"戉":{"expl":"斧也。从戈𠄌聲。《司馬法》曰：“夏執玄戉，殷執白戚，周左杖黃戉，右秉白髦。”凡戉之屬皆从戉。”","rad":"戉","fq":"王伐切","vol":"12","py":"yuè","duan":[{"e":"大斧也。","n":"一本奪大字。非。斧所以斫也。"}]},"戚":{"expl":"戉也。从戉尗聲。","rad":"戉","fq":"倉歴切","vol":"12","py":"qī","duan":[{"e":"戉也。","n":"大雅曰。干戈戚揚。傳云。戚、斧也。揚、鉞也。依毛傳戚小於戉。揚乃得戉名。左傳。戚鉞秬鬯。文公受之。戚鉞亦分二物。許則渾言之耳。戚之引伸之義爲促迫。而古書用戚者、俗多改爲蹙。試思親戚亦取切近爲言、非有異義也。大雅。戚戚兄弟。傳曰。戚戚、內相親也。小雅。戚戚靡所逞。箋云。戚戚、縮小之貌。其義本相通。而淺人於節南山必易其形與音矣。戚訓促迫。故又引申訓憂。小明。自詒伊戚。傳曰。戚、憂也。度古衹有戚。後乃別製慽字。"}]},"吾":{"expl":"我，自稱也。从口五聲。","rad":"口","fq":"五乎切","vol":"02","py":"wú","duan":[{"e":"我自偁也。","n":"偁各本作稱。誤。釋詁曰。吾、我也。"}]},"我":{"expl":"施身自謂也。或說我，頃頓也。从戈从𠄒。𠄒，或說古垂字。一曰古殺字。凡我之屬皆从我。","rad":"我","fq":"五可切","vol":"12","py":"wǒ","duan":[{"e":"施身自謂也。","n":"不但云自謂而云施身自謂者、取施與我古爲㬪韵。施讀施捨之施。謂用己廁於衆中、而自稱則爲我也。施者、旗貌也。引申爲施捨者、取義於旗流下𠂹也。釋詁曰。卬吾台予朕身甫余言我也。又曰。朕子躬身也。又曰。台朕賚畀⺊陽予也。或以賚畀卜予不同義。愚謂有我則必及人。故賚畀卜亦在施身自謂之內也。口部曰。吾、我自稱也。女部曰。姎、女人自稱姎我也。毛詩傳曰。言、我也。卬、我也。論語二句而我吾互用。毛詩一句而卬我襍稱。葢同一我義而語音輕重緩急不同。施之於文若自其口出。"}]},"義":{"expl":"己之威儀也。從我、羊。","rad":"我","fq":"宜寄切","vol":"12","py":"yí","duan":[{"e":"己之威義也。","n":"言己者、以字之从我也。己、中宮。象人腹。故謂身曰己。義各本作儀。今正。古者威儀字作義。今仁義字用之。儀者、度也。今威儀字用之。誼者、人所宜也。今情誼字用之。鄭司農注周禮肆師。古者書儀但爲義。今時所謂義爲誼。是謂義爲古文威儀字。誼爲古文仁義字。故許各仍古訓。而訓儀爲度。凡儀象、儀匹、引申於此。非威儀字也。古經轉寫旣久。肴襍難辨。據鄭、許之言可以知其意。威義古分言之者、如北宮文子云有威而可畏謂之威、有儀而可象謂之義、詩言令義令色、無非無義是也。威義連文不分者、則隨處而是。但今無不作儀矣。毛詩。威義棣棣。不可選也。傳曰。君子望之儼然可畏。禮容俯仰各有宜耳。棣棣、富而閒習也。不可選、物有其容不可數也。"}]},"亅":{"expl":"鉤逆者謂之亅。象形。凡亅之屬皆从亅。读若橜。","rad":"亅","fq":"衢月切","vol":"12","py":"jué","duan":[{"e":"鉤逆者謂之亅。","n":"鉤者、曲金也。司馬相如列傳。猶時有銜橜之變。集解引徐廣云。鉤逆者謂之橜。索隱引周遷輿服志云。鉤逆者爲橜。皆謂橜爲亅之叚借字也。淸道而行。中路而馳。𣃔無枯木朽株之難。故知必謂鉤也。"}]},"𠄌":{"expl":"鉤識也。从反亅。讀若捕鳥罬。","rad":"亅","fq":"居月切","vol":"12","py":"jué","duan":[{"e":"鉤識也。","n":"鉤識者、用鉤表識其處也。褚先生補滑稽傳。東方朔上書。凡用三千奏牘。人主從上方讀之。止、輒乙其處。二月乃盡。此非甲乙字。乃正𠄌字也。今人讀書有所鉤勒卽此。內則。魚去乙。鄭曰。乙、魚體中害人者名也。今東海鰫魚有骨名乙。在目。狀如篆乙。食之鯁人不可出。此亦非甲乙字。乃狀如篆𠄌也。魚腸名乙耳。不當別有乙也。戉斧之字从𠄌爲聲。"}]},"珡":{"expl":"禁也。神農所作。洞越。練朱五弦，周加二弦。象形。凡珡之屬皆从珡。","rad":"珡","fq":"巨今切","vol":"12","py":"qín","duan":[{"e":"禁也。","n":"禁者、吉凶之忌也。引申爲禁止。白虎通曰。琴、禁也。以禁止淫邪、正人心也。此㬪韵爲訓。"}]},"瑟":{"expl":"庖犧所作弦樂也。从珡必聲。","rad":"珡","fq":"所櫛切","vol":"12","py":"sè","duan":[{"e":"庖犧所作弦樂也。","n":"弦樂、猶磬曰石樂。淸廟之瑟亦練朱弦。凡弦樂以絲爲之。象弓弦、故曰弦。淇奥傳曰。瑟、矜莊貌。旱麓箋曰。瑟、絜鮮貌。皆因聲叚借也。瑟之言肅也。楚辭言秋氣蕭瑟。"}]},"琵":{"expl":"琵琶，樂器。从珡比聲。","rad":"珡","fq":"房脂切","vol":"12","py":"pí","duan":[]},"琶":{"expl":"琵琶也。从珡巴聲。義當用枇杷。","rad":"珡","fq":"蒲巴切","vol":"12","py":"pá","duan":[]},"𠃊":{"expl":"匿也，象𨒅曲隱蔽形。凡𠃊之屬皆从𠃊。讀若隱。","rad":"𠃊","fq":"於謹切","vol":"12","py":"yǐn","duan":[{"e":"匿也。","n":"匿者、亡也。"}]},"直":{"expl":"正見也。从𠃊从十从目。","rad":"𠃊","fq":"除力切","vol":"12","py":"zhí","duan":[{"e":"正見也。","n":"左傳曰。正直爲正。正曲爲直。其引申之義也。見之審則必能矯其枉。故曰正曲爲直。"}]},"哲":{"expl":"知也。从口折聲。","rad":"口","fq":"陟列切","vol":"02","py":"zhé","duan":[{"e":"知也。","n":"釋言曰。哲、智也。方言曰。哲、知也。古智知通用。"}]},"亾":{"expl":"逃也。从入从𠃊。凡亾之屬皆从亾。","rad":"亾","fq":"武方切","vol":"12","py":"wánɡ","duan":[{"e":"逃也。","n":"逃者、亡也。二篆爲轉注。亡之本義爲逃。今人但謂亡爲死。非也。引申之則謂失爲亡。亦謂死爲亡。孝子不忍死其親。但疑親之出亡耳。故喪篆从哭亡。亦叚爲有無之無。雙聲相借也。"}]},"乍":{"expl":"止也，一曰亡也。从亾从一。","rad":"亾","fq":"鉏駕切","vol":"12","py":"zhà","duan":[{"e":"止亡䛐也。","n":"各本作止也一曰亡也六字。今正。乍無亡義。淺人離析所改耳。補䛐字者、如母下云止䛐也。亦本有䛐而後人刪之。乍與母同意。母者、有人姦女而一止之。其言曰母。？者、有人逃亡而一止之。其言曰乍。皆咄咄逼人之語也。亡與止亡者皆必在倉猝。故引申爲倉猝之稱。廣雅曰。暫也。孟子。今人乍見孺子將入於井。左傳。桓子乍謂林楚。文意正同。而左傳俗本改乍爲咋。"}]},"望":{"expl":"出亡在外，望其還也。从亾，朢省聲。","rad":"亾","fq":"巫放切","vol":"12","py":"wànɡ","duan":[{"e":"出亡在外。望其還也。","n":"還者、復也。本義。引申之爲令聞令望之望。"}]},"無":{"expl":"亡也。从亾𣞤聲。","rad":"亾","fq":"武扶切","vol":"12","py":"wú","duan":[{"e":"亡也。","n":"凡所失者、所未有者皆如逃亡然也。此有無字之正體。而俗作無。無乃𣞤之隷變。𣞤之訓豐也。與無義正相反。然則隷變之時。昧於亡爲其義。𣞤爲其聲。有聲無義。殊爲乖繆。古有叚𣞤爲𣠮者。要不得云本無二字。漢隷多作𣠮可證也。或叚亡爲無者、其義同。其音則雙聲也。"}]},"匃":{"expl":"气也。逯安說：亡人爲匄。","rad":"亾","fq":"古代切","vol":"12","py":"ɡài","duan":[{"e":"气也。","n":"气者、雲气也。用其聲叚借爲气求、气與字。俗以气求爲入聲。以气與爲去聲。匄訓气、亦分二義二音。西域傳。气匄亡所得。此气求之義也。當去聲。又曰。我匄若馬。此气與之義也。當入聲。要皆強爲分別耳。左傳。公子棄疾不強匄。又子產曰。世有盟誓。母或匄奪。皆言气求也。通俗文曰。求願曰匄。則是求之曰气匄。因而與之亦曰气匄也。今人以物與人曰給。其實當用匄字。廣韵古達切。其字俗作丐。與丏不同。廣韵曰。二字同。非是。"}]},"匸":{"expl":"衺徯，有所俠藏也。从乚，上有一覆之。凡匸之屬皆从匸。讀與傒同。","rad":"匸","fq":"胡礼切","vol":"12","py":"xì","duan":[{"e":"衺徯有所㚒臧也。","n":"㚒各本作俠。今正。衺者、？也。徯者、待也。㚒者、盜竊褱物也。迆衺相待有所竊臧。故其字从？。而上復有一覆之。"}]},"區":{"expl":"踦區，藏匿也。从品在匸中。品，眾也。","rad":"匸","fq":"豈俱切","vol":"12","py":"qū","duan":[{"e":"踦區、","n":"逗。㬪韵。"}]},"匿":{"expl":"亡也。从匸若聲。讀如羊騶箠。","rad":"匸","fq":"女力切","vol":"12","py":"nì","duan":[{"e":"亡也。","n":"廣韵曰。藏也。微也。亡也。陰姦也。"}]},"㔷":{"expl":"側逃也。从匸丙聲。一曰箕屬。","rad":"匸","fq":"盧候切","vol":"12","py":"lòu","duan":[{"e":"側㔷也。","n":"各本作側逃也。今依玉篇逃作㔷。玉篇曰。又作？。是知側㔷卽堯典之側？。謂隱藏不出者也。"}]},"匽":{"expl":"匿也。从匸妟聲。","rad":"匸","fq":"於蹇切","vol":"12","py":"yǎn","duan":[{"e":"匿也。","n":"匽之言隱也。周禮宮人。爲之井匽。鄭司農云。匽、路廁也。後鄭云。匽豬謂𩅸下之池畜水而流之者。按二說皆謂隱蔽之地也。"}]},"君":{"expl":"尊也。从尹。發號，故从口。","rad":"口","fq":"舉云切","vol":"02","py":"jūn","duan":[{"e":"尊也。","n":"此羊祥也、門聞也、戶護也、髮拔也之例。"}]},"医":{"expl":"盛弓弩矢器也。从匸从矢。《國語》曰：“兵不解医。”","rad":"匸","fq":"於計切","vol":"12","py":"yì","duan":[{"e":"臧弓弩矢器也。","n":"臧各本作盛。今依廣韵。此器可隱藏兵器也。"}]},"匹":{"expl":"四丈也。从八、匸。八揲一匹，八亦聲。","rad":"匸","fq":"普吉切","vol":"12","py":"pǐ","duan":[{"e":"四丈也。","n":"按四丈之上當有布帛二字。襍記曰。納幣一束。束五兩。兩五尋。鄭曰。納幣謂昏禮納徴也。十箇爲束。貴成數。兩兩合其卷。是謂五兩。八尺曰尋。五兩、兩五尋、謂每兩五尋則每卷二丈也。合之則四十尺。今謂之匹。猶匹偶之云與。周禮。凡嫁子、娶妻。入幣䊷帛無過五兩。鄭曰。五兩、十端也。每端二丈。按二丈爲一端。二端爲兩。每兩爲一匹。長四丈。五兩則五匹爲一束也。凡古言束帛者、皆此制。凡言匹敵、匹耦者、皆於二端成兩取意。凡言匹夫、匹婦者、於一兩成匹取意。兩而成匹。判合之理也。雖其半亦得云匹也。馬稱匹者、亦以一牝一牡離之而云匹。猶人言匹夫也。○按字之本義有難定者。如襍記注今謂之匹、猶匹偶之云與。是以匹偶爲本義。而帛二兩爲"}]},"匚":{"expl":"受物之器。象形。凡匚之屬皆从匚。讀若方。","rad":"匚","fq":"府良切","vol":"12","py":"fānɡ","duan":[{"e":"受物之器。","n":"此其器葢正方。文如此作者、横視之耳。直者其底。横者其四圍。右其口也。廣韵曰。或曰受一斗曰匚。按囗部云。囿、規也。今人皆作圜、作圓。方、本無正字。故自古叚方爲之。依字、匚有榘形。固可叚作方也。"}]},"匠":{"expl":"木工也。从匚从斤。斤，所以作器也。","rad":"匚","fq":"疾亮切","vol":"12","py":"jiànɡ","duan":[{"e":"木工也。","n":"工者、巧飭也。百工皆稱工、稱匠。獨舉木工者、其字从斤也。以木工之偁引申爲凡工之偁也。"}]},"匧":{"expl":"藏也。从匚夾聲。","rad":"匚","fq":"苦叶切","vol":"12","py":"qiè","duan":[{"e":"椷臧也。","n":"小徐本如是。大徐無椷字。木部椷下曰。匧也。是二篆爲轉注。臧字似衍。玉篇作緘也。乃椷之誤。若文選應璩百一詩、任昉哭范僕射詩李注皆引說文篋、笥也。此則所據本不同。自當以小徐本爲善耳。戰國策。乃夜發書。陳篋數十。"}]},"匡":{"expl":"飲器，筥也。从匚㞷聲。","rad":"匚","fq":"去王切","vol":"12","py":"kuānɡ","duan":[{"e":"飯器。","n":"句。小徐有也字。"}]},"匜":{"expl":"似羹魁，柄中有道，可以注水。从匚也聲。","rad":"匚","fq":"移尔切","vol":"12","py":"yí","duan":[{"e":"佀羹魁。","n":"斗部曰。魁、羹枓也。枓、勺也。匜之狀似羹勺。亦所以挹取也。"}]},"匴":{"expl":"渌米籔也。从匚算聲。","rad":"匚","fq":"穌管切","vol":"12","py":"suǎn","duan":[{"e":"淥米籔也。","n":"淥者、浚也。浚者、抒也。抒者、挹也。籔者、䉛也。䉛者、漉米籔也。然則匴與、䉛二字一物也。謂淅米訖、則移於此器內浚乾之而待炊。所謂滰淅也。士冠禮。爵弁、皮弁、緇布冠各一匴。注。匴、竹器名。今之冠箱也。古文匴爲篹。按淥米之籔𣃔非可盛冠。此必異物同名。或別有正字。俟考。"}]},"㔶":{"expl":"小桮也。从匚𥫔聲。","rad":"匚","fq":"古送切","vol":"12","py":"ɡònɡ","duan":[{"e":"小桮也。","n":"木部曰。桮、㔶也。二篆爲轉注。而桮下見渾言之義。此見析言之義。㒳處互相足而後義全。此許立文之例也。㔶下亦可云桮也。桮下亦可云大㔶也。是互相足之謂也。門部云。大桮爲閜。故小桮爲㔶矣。方言曰。㿿椷盞䀀閜𥂸𥂓桮也。自關而東趙魏之閒曰椷。或曰盞。或曰䀀。按椷葢卽許之㔶。音同字異。許則椷訓匧。各有本義也。"}]},"匪":{"expl":"器，似竹筐。从匚非聲。《逸周書》曰：“實玄黃于匪。”","rad":"匚","fq":"非尾切","vol":"12","py":"fěi","duan":[{"e":"器佀竹匧。","n":"小徐衹云如篋。小雅。承筐是將。傳曰。筐、篚屬。所以行幣帛也。按此筐與飯器之筐。異名同實。故毛訓之曰。匪屬也。小雅言匡。禹貢、禮記言匪。應劭漢書注曰。漢書作棐。應劭曰。棐、竹器也。方曰箱。隋曰棐。隋者、方而長也。他果反。古盛幣帛必以匪。匪篚古今字。有借匪爲斐者。如詩有匪君子是也。有借爲分者。周禮匪朌、鄭司農云匪分也是也。有借爲非者。如詩我心匪鑒、我心匪石是也。有借爲彼者。如左傳引詩如匪行邁謀杜曰匪彼也、荀子引匪交匪舒卽詩彼交匪紓是也。"}]},"命":{"expl":"使也。从口从令。","rad":"口","fq":"眉病切","vol":"02","py":"mìnɡ","duan":[{"e":"使也。从口令。","n":"令者、發號也。君事也。非君而口使之。是亦令也。故曰命者、天之令也。眉病切。古音在十二部。令亦聲。"}]},"𠥐":{"expl":"古器也。从匚倉聲。","rad":"匚","fq":"七岡切","vol":"12","py":"cānɡ","duan":[{"e":"古器也。","n":"古器有名？者。"}]},"𠤼":{"expl":"田器也。从匚攸聲。","rad":"匚","fq":"徒聊切","vol":"12","py":"tiáo","duan":[{"e":"田器也。","n":"艸部曰。莜、？田器也。？與莜音義皆同。葢一物也。"}]},"㔴":{"expl":"田器也。从匚異聲。","rad":"匚","fq":"與職切","vol":"12","py":"yì","duan":[{"e":"田器也。","n":"玉篇云。大鼎也。廣韵？訓大鼎。"}]},"匫":{"expl":"古器也。从匚曶聲。","rad":"匚","fq":"呼骨切","vol":"12","py":"hū","duan":[{"e":"古器也。","n":"畢尙書沅得曶鼎。豈其器卽匫與。"}]},"匬":{"expl":"甌，器也。从匚俞聲。","rad":"匚","fq":"度矦切","vol":"12","py":"yǔ","duan":[{"e":"甌匬器也。","n":"大徐無匬字。非是。甌者、小盆也。甌匬二字爲名、則非甌也。玉篇云。余主切。器受十六斗。按玉篇葢謂卽論語與之庾之庾。苞注。十六斗爲庾也。然禮經作十六斗爲籔。今文籔作逾。"}]},"匱":{"expl":"匣也。从匚貴聲。","rad":"匚","fq":"求位切","vol":"12","py":"ɡuì","duan":[{"e":"匣也。","n":"匱之義引申爲竭。大雅。孝子不匱。永錫爾類。傳曰。匱、竭也。凡物淥藏之則有若無、實若虛。故匱之引申爲竭、爲乏。竭、水渴也。乏、反其正也。"}]},"匵":{"expl":"匱也。从匚賣聲。","rad":"匚","fq":"徒谷切","vol":"12","py":"dú","duan":[{"e":"匱也。","n":"木部曰。櫝、匱也。是則匵與櫝音義皆同。實一物也。論語曰。韞匵而？諸。又曰。龜玉毁櫝中。其實一字也。引申之亦爲小棺。"}]},"匣":{"expl":"匱也。从匚甲聲。","rad":"匚","fq":"胡甲切","vol":"12","py":"xiá","duan":[{"e":"匱也。","n":"廣韵曰。箱、匣也。古亦借柙爲之。柙、檻也。"}]},"匯":{"expl":"器也。从匚淮聲。","rad":"匚","fq":"胡罪切","vol":"12","py":"huì","duan":[{"e":"器也。","n":"謂有器名匯也。禹貢曰。東匯澤爲彭蠡。又曰。北會于匯。舊說匯者、回也。此匯之別一義。依許圛？垐之例、此亦可稱禹貢而釋之曰匯回也。今按匯之言圍也。大澤外必有陂圍之。如器之圍物。古人說淮水曰。淮、圍也。匯从淮、則亦圍也。尙書。東匯澤爲彭蠡。謂東有圍受衆水之彭蠡。非謂漢水回而成澤也。東爲北江。謂漢水合江、又東合彭蠡爲北江也。"}]},"柩":{"expl":"棺也。从匚从木，久聲。","rad":"匚","fq":"日救切","vol":"12","py":"jiù","duan":[]},"璥":{"expl":"玉也。从玉敬聲。","rad":"玉","fq":"居領切","vol":"01","py":"jǐnɡ","duan":[{"e":"玉也。从王。敬聲。","n":"居領切。十一部。"}]},"咨":{"expl":"謀事曰咨。从口次聲。","rad":"口","fq":"卽夷切","vol":"02","py":"zī","duan":[{"e":"謀事曰咨。","n":"左傳曰。訪問於善爲咨。毛傳同。"}]},"匰":{"expl":"宗廟盛主器也。《周禮》曰：“祭祀共匰主。”从匚單聲。","rad":"匚","fq":"都寒切","vol":"12","py":"dān","duan":[{"e":"宗廟盛宔器也。","n":"周禮司巫。祭祀共匰主。杜子春云。匰、器名。主、木主也。許云宗廟盛宔器。亦用杜說。"}]},"曲":{"expl":"象器曲受物之形。或說曲，蠶薄也。凡曲之屬皆从曲。","rad":"曲","fq":"丘玉切","vol":"12","py":"qū","duan":[{"e":"象器曲受物之形也。","n":"匚象方器受物之形、側視之。曲象圜其中受物之形、正視之。引申之爲凡委曲之稱。不直曰曲。詩曰。子髮曲局。又曰。亂我心曲。箋云。心曲、心之委曲也。又樂章爲曲。謂音宛曲而成章也。周語曰、士獻詩。瞽獻曲。韋云。曲、樂曲也。毛詩傳曰。曲合樂曰歌。徒歌曰謠。韓詩曰。有章曲曰歌。無章曲曰謠。按曲合樂者、合於樂器也。行葦傳曰。歌者、比於琴瑟也。卽曲合樂曰歌也。區玉切。三部。"}]},"㻃":{"expl":"骫曲也。从曲玉聲。","rad":"曲","fq":"丘玉切","vol":"12","py":"qū","duan":[{"e":"骫曲也。","n":"骫者、骨耑骫奊也。曲當作𠚖。今人用委曲字、古用𩨥𠚖。其字从骨从玉。謂如骨玉之堅而柔之使橈也。廣韵作匤匣也。"}]},"𤔱":{"expl":"古器也。从曲舀聲。","rad":"曲","fq":"土刀切","vol":"12","py":"tāo","duan":[{"e":"古器也。从曲。舀聲。","n":"土刀切。古音在三部。"}]},"甾":{"expl":"東楚名缶曰甾。象形。凡甾之屬皆从甾。","rad":"甾","fq":"側詞切","vol":"12","py":"zī","duan":[{"e":"東楚名缶曰𠙹。","n":"太史公曰。自彭城以東。東海、吳、廣陵、此東楚也。缶下曰。瓦器、所以盛酒漿。秦人𡔷之以節歌。象形。然則缶旣象形矣。𠙹復象形。實一物而語言不同。且實一字而書法少異耳。玉篇作𠙹近之。若廣韵謂卽艸部之甾字。風馬牛不相及也。甾上从一雝川。此象缶之頸少殺。安得云同字。今𣜩當作甾。"}]},"疀":{"expl":"𣂀也，古田器也。从甾疌聲。","rad":"甾","fq":"楚洽切","vol":"12","py":"chā","duan":[{"e":"𣂁也。","n":"𣂁者、斛旁有庣也。𠙹之類。故其字从𠙹。"}]},"𤲙":{"expl":"𤳊屬，蒲器也，所以盛穜。从甾弁聲。","rad":"甾","fq":"布忖切","vol":"12","py":"běn","duan":[{"e":"蒲器也。𢆟屬。所㠯盛糧。","n":"糧各本作穜。今正。周禮挈壺氏。挈畚以令糧。大鄭云。縣畚於稟假之處。後鄭云。畚所以盛糧之器。故以畚表稟。左傳宣二年正義引說文蒲器可以盛糧。左傳釋文、詩正義引艸器所以盛種。種字葢非。果爲種字。則當云榖種。不得但言種也。何休注公羊云。畚、草器。杜注左傳。以草索爲之。蒲與艸不相妨。糧者、榖也。"}]},"𤳊":{"expl":"㠷也。从甾并聲。杜林以爲竹筥，楊雄以爲蒲器。讀若軿。","rad":"甾","fq":"薄經切","vol":"12","py":"pínɡ","duan":[{"e":"㠷也。","n":"㠷者、蒲席㡒也。㡒下曰。載米？也。㡒下曰。㡒也。所以盛米。然則四篆一物也。"}]},"𧇄":{"expl":"𦉈也。从甾虍聲。讀若盧同。","rad":"甾","fq":"洛乎切","vol":"12","py":"lú","duan":[{"e":"𦉈也。","n":"𦉈者、小口罌也。"}]},"瓦":{"expl":"土器已燒之總名。象形。凡瓦之屬皆从瓦。","rad":"瓦","fq":"五寡切","vol":"12","py":"wǎ","duan":[{"e":"土器巳燒之總名。","n":"土部坏下曰。一曰瓦未燒。互謂巳燒者也。凡土器未燒之素皆謂之坏。已燒皆謂之瓦。毛詩斯干傳曰。瓦、紡專也。此瓦中之一也。古史攷曰。夏時昆吾氏作瓦。按有虞氏上陶。瓦之不起於夏時可知也。許書缶部曰。古者昆吾作匋。壺系之昆吾圜器。韋昭云。昆吾祝融之孫。陸終第二子。名黎。爲己姓。封於昆吾衞是也。然則昆吾作匋、謂始封之昆吾。非夏桀之昆吾也。廣韵引周書神農作瓦器。當得其實。說詳缶部。凡燒瓦器之竈曰窯。"}]},"召":{"expl":"𧦝也。从口刀聲。","rad":"口","fq":"直少切","vol":"02","py":"zhào","duan":[{"e":"𧦝也。","n":"言部曰。𧦝、召也。"}]},"瓬":{"expl":"周家搏埴之工也。从瓦方聲。讀若㧚破之㧚。","rad":"瓦","fq":"分兩切","vol":"12","py":"fǎnɡ","duan":[{"e":"周家搏埴之工也。","n":"搏作摶者誤。今正。考工記曰。搏埴之工陶瓬。鄭曰。搏之言拍也。埴、黏土也。按手部搏、索持也。拍、拊也。是搏之本義不訓拍。故鄭以之言通之。"}]},"甄":{"expl":"匋也。从瓦垔聲。","rad":"瓦","fq":"居延切","vol":"12","py":"zhēn","duan":[{"e":"匋也。","n":"匋者、作瓦器也。董仲舒曰。如泥之在鈞。惟甄者之所爲。陳畱風俗傳曰。舜陶甄河濱。其引申之義爲察也、勉也。考工記叚借爲震掉字。"}]},"甍":{"expl":"屋棟也。从瓦，夢省聲。","rad":"瓦","fq":"莫耕切","vol":"12","py":"ménɡ","duan":[{"e":"屋棟也。","n":"棟者、極也。屋之高處也。方言。？謂之？。廣雅作甍謂之？。每夢一聲之轉。之蒸合韵之理。棟自屋中言之、故从木。甍自屋表言之、故从瓦。爾雅、方言謂之？者、屋極爲分水之脊。雨水各從高𩅸瓦而下也。釋名曰。甍、蒙也。在上覆蒙屋也。左傳子之援廟桷、動於甍。未詳其說。"}]},"甑":{"expl":"甗也。从瓦曾聲。","rad":"瓦","fq":"子孕切","vol":"12","py":"zènɡ","duan":[{"e":"甗也。","n":"考工記。陶人爲甑。實二鬴。厚半寸。脣寸。七穿。按甑所以炊烝米爲飯者。其底七穿。故必以箅蔽甑底。而加米於上。而？之、而？之。"}]},"甗":{"expl":"甑也。一曰穿也。从瓦鬳聲。讀若言。","rad":"瓦","fq":"魚蹇切","vol":"12","py":"yǎn","duan":[{"e":"甑也。一穿。","n":"各本作一曰穿也。小徐本在鬳聲之下。今正。按甑空名窐。見穴部。不得云又名甗也。陶人爲甗。實二鬴。厚半寸。脣寸。鄭司農云。甗、無底甑。無底、卽所謂一穿。葢甑七穿而小。甗一穿而大。一穿而大則無底矣。甑下曰甗也、渾言之。此曰甑也一穿、析言之。渾言見甗亦評甑。析言見甑非止一穿。參差互見。使文義相足。此許訓詁之一例也。或曰當依小徐鬳聲之下作一曰甑一穿也六字。山之似甗者曰甗。詩。陟則在甗。傳曰。甗、小山別於大山也。釋名曰。甗、甑也。甑一孔者。甗形孤出處似之也。按此謂似甑體而巳。鬲部曰。鼎大上小下若甑曰鬵。然則甑形大上小下。山名甗者亦爾。俗作巘。非。爾雅。小山別。大山曰鮮。詩皇矣同。字作鮮者、甗之叚借。文選吳"}]},"瓵":{"expl":"甌瓿謂之瓵。从瓦台聲。","rad":"瓦","fq":"與之切","vol":"12","py":"yí","duan":[{"e":"甌瓿謂之瓵。","n":"爾雅釋器文。史記貨殖傳。糱麴鹽豉干合。徐廣曰。或作台。器名有瓵。孫叔然云。瓵、瓦器。受斗六𦫵。台當爲瓵。音貽。按今史記譌舛。爲正之如此。所引孫叔然者、爾雅注也。"}]},"瓽":{"expl":"大盆也。从瓦尚聲。","rad":"瓦","fq":"丁浪切","vol":"12","py":"dànɡ","duan":[{"e":"大盆也。","n":"盆者、盎也。瓽其大者也。漢書楊雄酒箴曰。爲瓽所轠。"}]},"甌":{"expl":"小盆也。从瓦區聲。","rad":"瓦","fq":"烏矦切","vol":"12","py":"ōu","duan":[{"e":"小盆也。","n":"方言。罃甈謂之盎。自關而西或謂之盆。或謂之盎。其小者謂之升甌。又曰。甂、陳魏宋楚之閒謂之㼵。自關而西謂之甂。其大者謂之甌。按許亦同。方言謂甌爲盆。而郭景純疑方言與爾雅說甈不合。"}]},"瓮":{"expl":"罌也。从瓦公聲。","rad":"瓦","fq":"烏貢切","vol":"12","py":"wènɡ","duan":[{"e":"罌也。","n":"罌者、？也。？者、小口罌也。然則瓮者、罌之大口者也。方言曰。甀、瓮、瓿甊、甖也。自關而西晉之舊都河汾之閒其大者謂之甀。其中者謂之瓿甊。自關而東趙魏之郊謂之瓮。或謂之甖。甖卽罌字。"}]},"瓨":{"expl":"似罌，長頸。受十升。讀若洪。从瓦工聲。","rad":"瓦","fq":"古雙切","vol":"12","py":"xiánɡ","duan":[{"e":"佀罌。長頸。受十升。","n":"史、漢貨殖傳皆曰。醯醬千瓨。按醯醬者、今之醋也。別於下文之醬。升當作斗。漢書注。古本有作斗者。"}]},"問":{"expl":"訊也。从口門聲。","rad":"口","fq":"亡運切","vol":"02","py":"wèn","duan":[{"e":"訊也。","n":"言部曰。訊、問也。引伸爲禮之聘問。"}]},"㼝":{"expl":"小盂也。从瓦夗聲。","rad":"瓦","fq":"烏管切","vol":"12","py":"wǎn","duan":[{"e":"小盂也。","n":"盂者、飲器也。方言曰。盂、宋楚魏之閒或謂之盌。"}]},"瓴":{"expl":"瓮，似瓶也。从瓦令聲。","rad":"瓦","fq":"郎丁切","vol":"12","py":"línɡ","duan":[{"e":"𦉥也。佀缾者。","n":"罋大徐瓮。葢非。高祖本紀曰。譬猶居高屋建瓴水。如淳曰。瓴、盛水甁也。居高屋之上而幡瓴水。言其向之勢易也。建音蹇。晉灼曰。許愼云。瓴、罋似甁者也。按缶部云。𦉥、汲？也。瓴同物而非罌瓮。"}]},"㼰":{"expl":"罌謂之㼰。从瓦卑聲。","rad":"瓦","fq":"部迷切","vol":"12","py":"pí","duan":[{"e":"罌謂之㼰。","n":"方言、廣雅罌皆作甇。"}]},"甂":{"expl":"似小瓿。大口而卑。用食。从瓦扁聲。","rad":"瓦","fq":"芳連切","vol":"12","py":"biān","duan":[{"e":"佀小瓿。大口而卑。用食。","n":"方言。甂、陳魏宋楚之閒謂之㼵。自關而西謂之甂。淮南書曰。狗彘不擇甂甌而食。玉篇曰。小盆大口而卑下。"}]},"瓿":{"expl":"甂也。从瓦咅聲。","rad":"瓦","fq":"蒲口切","vol":"12","py":"bù","duan":[{"e":"甂也。","n":"玉篇。瓿甊、小罌也。廣韵同。"}]},"㼸":{"expl":"器也。从瓦容聲。","rad":"瓦","fq":"與封切","vol":"12","py":"rónɡ","duan":[{"e":"器也。","n":"廣韵罌也。"}]},"甓":{"expl":"瓴甓也。从瓦辟聲。《詩》曰：“中唐有甓。”","rad":"瓦","fq":"扶歴切","vol":"12","py":"pì","duan":[{"e":"令適也。","n":"大徐適作甓。陳風。中唐有甓。傳曰。甓、令適也。釋宮同。郎丁都歴二反。爾雅作瓴甋。俗字也。土部墼字解亦云令適。考工記注作令甓。實一物也。詳墼字注。"}]},"甃":{"expl":"井壁也。从瓦秋聲。","rad":"瓦","fq":"側救切","vol":"12","py":"zhòu","duan":[{"e":"井壁也。","n":"井壁者、謂用塼爲井垣也。周易井九四、曰。井甃无咎。又上六。井收。荀作井甃。莊子曰。缺甃之涯。"}]},"甈":{"expl":"康瓠，破罌。从瓦臬聲。","rad":"瓦","fq":"魚例切","vol":"12","py":"qì","duan":[{"e":"康瓠。","n":"句。按當有謂之甈三字。"}]},"㼽":{"expl":"瑳垢瓦石。从瓦爽聲。","rad":"瓦","fq":"初兩切","vol":"12","py":"chuǎnɡ","duan":[{"e":"瑳垢瓦石也。","n":"瑳俗作磋。今依宋本作瑳。亦叚借字耳。其字當用厝。厝、厲石也。詩曰。它山之石。可以爲厝。用瓦石去垢曰㼽。方言注曰。漺、錯也。漺與磢同。海賦曰。飛澇相磢。江賦曰。奔澑之所磢錯。磢卽㼽。"}]},"唯":{"expl":"諾也。从口隹聲。","rad":"口","fq":"以水切","vol":"02","py":"wěi","duan":[{"e":"諾也。","n":"此渾言之。玉藻曰。父命呼。唯而不諾。析言之也。"}]},"㼲":{"expl":"蹈瓦聲。从瓦耎聲。","rad":"瓦","fq":"零帖切","vol":"12","py":"liè","duan":[{"e":"蹈瓦聲㼲㼲也。","n":"大徐無㼲㼲也三字。小徐作蹈瓦㼲也。玄應作蹈瓦聲躐躐也。今按躐躐當作㼲㼲。通俗文。瓦破聲曰㼲。玉篇。㼲㼲、蹋瓦聲。"}]},"𤬯":{"expl":"治橐榦也。从瓦今聲。","rad":"瓦","fq":"胡男切","vol":"12","py":"hán","duan":[{"e":"冶槖榦也。","n":"冶各本作治。今正。冶槖、謂排囊。排讀普拜切。其字或作韛。或作？。冶者以韋囊鼓火。老子之所謂槖也。其所執之柄曰𤬯。榦猶柄也。𤬯或譌作肣。而廣韵以排囊柄釋之。玉篇以似甁有耳釋𤬯。引許者冶皆譌治。而其義湛薶終古矣。排囊之柄、古用瓦爲之。故字从瓦。後乃以木爲之。故集韵作？。从木。"}]},"𤭢":{"expl":"破也。从瓦卒聲。","rad":"瓦","fq":"穌對切","vol":"12","py":"suì","duan":[{"e":"破也。","n":"破上當有瓦字。破下曰石𤭢也。此曰瓦破也。是二篆爲轉注。而形各有所从。𤭢與碎音同義異。碎者、䊳也。𤭢則破而巳。不必䊳也。今則碎行而𤭢廢矣。"}]},"瓪":{"expl":"敗也。从瓦反聲。","rad":"瓦","fq":"布綰切","vol":"12","py":"bǎn","duan":[{"e":"敗瓦也。","n":"依小徐有瓦字。今俗所謂瓦瓪、是此字也。今人語如辦之平聲耳。玉篇、廣韵皆曰。瓪、牝瓦也。此今義。非許義。广部曰。㡲、屋牝瓦也。牡瓦牝瓦、見九章算經及漢書。說詳㡲下。"}]},"瓷":{"expl":"瓦器。从瓦次聲。","rad":"瓦","fq":"疾資切","vol":"12","py":"cí","duan":[]},"瓻":{"expl":"酒器。从瓦，稀省聲。","rad":"瓦","fq":"丑脂切","vol":"12","py":"chī","duan":[]},"弓":{"expl":"以近窮遠。象形。古者揮作弓。《周禮》六弓：王弓、弧弓以射甲革甚質；夾弓、庾弓以射干矦鳥獸；唐弓、大弓以授學射者。凡弓之屬皆从弓。","rad":"弓","fq":"居戎切","vol":"12","py":"ɡōnɡ","duan":[{"e":"竆也。","n":"補此二字。以㬪韵爲訓之例也。"}]},"弴":{"expl":"畫弓也。从弓𦎫聲。","rad":"弓","fq":"都昆切","vol":"12","py":"dūn","duan":[{"e":"畫弓也。","n":"大雅。敦弓旣堅。傳曰。敦弓、畫弓也。天子畫弓。按荀卿子天子彫弓。諸侯彤弓。大夫黑弓。禮也。公羊傳何注曰。禮、天子雕弓。諸侯彤弓。大夫嬰弓。士盧弓。盧？卽玈弓。黑弓也。嬰弓、陸德明云見司馬法。按嬰卽江賦之䙬字。葢朱黑相閒而嬰繞也。彤弓、毛傳曰朱弓也。以講德習射。彫弓者、葢五采畫之。凡經傳言彫有謂刻鏤者。如玉謂之彫、金謂之鏤、禮記玉豆彫篹、論語朽木不可彫是也。有謂繪畫者。如此彫弓是也。彡部曰。彫、𤥨文也。古繪畫與刻畫無二字。諸侯彤弓、則天子當五采。石𡔷詩有秀弓。秀卽繡。五采備謂之繡。或曰天子之弓但刻畫爲文也。兩京賦。彫弓斯彀。薛云。彫弓謂有刻畫也。弴與彫語之轉。敦弓者、弴之叚借字。詩、禮又叚追爲之"}]},"弭":{"expl":"弓無緣，可以解轡紛者。从弓耳聲。","rad":"弓","fq":"緜婢切","vol":"12","py":"mǐ","duan":[{"e":"弓無緣可㠯解𦆕紛者。","n":"釋器曰。弓有緣者謂之弓。無緣者謂之弭。孫云。緣謂𦅾束而漆之。弭謂不以𦅾束、骨飾兩頭者也。小雅。象弭魚服。傳曰。象弭、弓反末也。所以解紛者。箋云。弓反末彆者、以象骨爲之。以助御者解轡紛宜骨也。按紛猶亂。今詩作紒、亦通。紒者、今之結字。許合爾雅、毛詩爲說也。弭可以解紛。故引申之訓止。凡云弭兵、弭亂者是也。"}]},"弲":{"expl":"角弓也，洛陽名弩曰弲。从弓肙聲。","rad":"弓","fq":"烏玄切","vol":"12","py":"xuān","duan":[{"e":"角弓也。","n":"角弓謂弓之傅角者也。詩曰。觲觲角弓。相角居角之法、詳於弓人。按今詩騂騂角弓釋文曰。騂、說文作？。音火全反。此陸氏之偶誤。葢角部稱觲觲角弓。陸當云說文作觲。而誤云作？也。？自謂角弓。不謂弓調利。"}]},"唱":{"expl":"導也。从口昌聲。","rad":"口","fq":"尺亮切","vol":"02","py":"chànɡ","duan":[{"e":"導也。","n":"鄭風曰。唱予和女。"}]},"弧":{"expl":"木弓也。从弓瓜聲。一曰往體寡，來體多曰弧。","rad":"弓","fq":"戶吳切","vol":"12","py":"hú","duan":[{"e":"木弓也。","n":"易曰。弦木爲弧。考工記。凡爲弓。冬析榦。凡榦。柘爲上。檍次之。檿桑次之。橘次之。木瓜次之。荆次之。竹爲下。按木弓、謂弓之不傅以角者也。弓有專用木不傅角者。後世聖人初造弓矢之遺法也。引申之爲凡曲之稱。輈人曰。凡揉輈欲其孫而無弧深。"}]},"弨":{"expl":"弓反也。从弓召聲。《詩》曰：“彤弓弨兮。”","rad":"弓","fq":"尺招切","vol":"12","py":"chāo","duan":[{"e":"弓反也。","n":"小雅。彤弓弨兮。傳曰。弨、弛皃。按詩正義引說文有謂弛之而弓反六字。葢出庾儼默說。弛者、弓解也。弓反者、詩所云翩其反也。弓反爲弨之本義。弛之則亦反矣。"}]},"𢑆":{"expl":"弓曲也。从弓雚聲。","rad":"弓","fq":"九院切","vol":"12","py":"quán","duan":[{"e":"弓曲也。","n":"陸德明云。說文音權。然則與拳曲音義略同。爾雅曰。菼薍其萌虇。陸云。本或作？。非。？、說文云弓曲也。按偏旁多後人所加。作？者、正是古本艸初生句曲也。"}]},"彄":{"expl":"弓弩耑，弦所居也。从弓區聲。","rad":"弓","fq":"恪矦切","vol":"12","py":"kōu","duan":[{"e":"弓弩耑。所凥也。","n":"耑者、頭也。㒳頭隱弦處曰彄。亦引申他用。詩箋云。韘所以彄沓手指。"}]},"𢑈":{"expl":"弓便利也。从弓䌛聲。讀若燒。","rad":"弓","fq":"火招切","vol":"12","py":"yáo","duan":[{"e":"弓𠊳利也。","n":"？之言由也。所謂自由自便也。"}]},"張":{"expl":"施弓弦也。从弓長聲。","rad":"弓","fq":"陟良切","vol":"12","py":"zhānɡ","duan":[{"e":"𢻱弓弦也。","n":"𢻱各本作施。今正。𢻱、敷也。張弛、本謂弓施弦解弦。引申爲凡作輟之稱。禮記曰。張而不弛。文武弗能也。弛而不張。文武弗爲也。一張一弛。文武之道也。"}]},"彏":{"expl":"弓急張也。从弓矍聲。","rad":"弓","fq":"許縛切","vol":"12","py":"jué","duan":[{"e":"弓急張也。","n":"廣韵曰。弓弦急皃。"}]},"弸":{"expl":"弓彊皃。从弓朋聲。","rad":"弓","fq":"父耕切","vol":"12","py":"pénɡ","duan":[{"e":"弓彊皃。","n":"法言。弸中彪外。引申之義也。"}]},"彊":{"expl":"弓有力也。从弓畺聲。","rad":"弓","fq":"巨良切","vol":"12","py":"qiánɡ","duan":[{"e":"弓有力也。","n":"引申爲凡有力之稱。又叚爲勥迫之勥。"}]},"彎":{"expl":"持弓關矢也。从弓䜌聲。","rad":"弓","fq":"烏關切","vol":"12","py":"wān","duan":[{"e":"持弓關矢也。","n":"凡㒳相交曰關。如以木横持㒳扉也。矢桰檃於弦、而鏑出弓背外。是兩耑相交也。孟子曰。越人關弓而射之。左傳。將注。豹則關矣。皆謂引弓將滿、是之謂彎。或叚貫爲關。"}]},"和":{"expl":"相譍也。从口禾聲。","rad":"口","fq":"戶戈切","vol":"02","py":"hè","duan":[{"e":"相應也。从口。禾聲。","n":"古唱和字不讀去聲。戶戈切。十七部。"}]},"引":{"expl":"開弓也。从弓、丨。","rad":"弓","fq":"余忍切","vol":"12","py":"yǐn","duan":[{"e":"開弓也。","n":"開下曰張也。是門可曰張。弓可曰開。相爲轉注也。施弦於弓曰張。鉤弦使滿、以竟矢之長亦曰張。是謂之引。凡延長之偁、開導之偁皆引申於此。小雅楚茨、大雅召旻毛傳皆曰。引、長也。"}]},"弙":{"expl":"滿弓有所鄉也。从弓于聲。","rad":"弓","fq":"哀都切","vol":"12","py":"wū","duan":[{"e":"滿弓有所鄉也。","n":"鄉今向字。漢人無用向者。廣雅曰。弙、張也。大荒南經。有人方扜弓射黃蛇。郭曰。扜、挽也。音紆。按此叚扜爲弙也。弙與彎雙聲。"}]},"弘":{"expl":"弓聲也。从弓厶聲。厶，古文肱字。","rad":"弓","fq":"胡肱切","vol":"12","py":"hónɡ","duan":[{"e":"弓聲也。","n":"集韵曰。弸㢬、？聲也。或作彋。按㢬彋皆卽此篆也。甘泉賦曰。帷弸彋其拂汨兮。蘇林云。弸音石墮井弸爾之弸。彋音宏。李善曰。弸彋、風吹帷帳之聲也。是則弓聲之義引申爲他聲。經傳多叚此篆爲宏大字。宏者屋深。故爾雅曰。宏、大也。"}]},"瓕":{"expl":"弛弓也。从弓璽聲。","rad":"弓","fq":"斯氏切","vol":"12","py":"mí","duan":[{"e":"弛弓也。","n":"弛弓者、瓕之義。瓕非弛字也。玉篇以爲今之彌字。廣韵以爲玉名。皆非是。"}]},"弛":{"expl":"弓解也。从弓从也。","rad":"弓","fq":"施氏切","vol":"12","py":"chí","duan":[{"e":"弓解弦也。","n":"弦字各本無。今補。引申爲凡懈廢之稱。"}]},"弢":{"expl":"弓衣也。从弓从𠬢。𠬢，垂飾，與𡔷同意。","rad":"弓","fq":"土刀切","vol":"12","py":"tāo","duan":[{"e":"弓衣也。","n":"左傳多言弢。詩言韔。秦風傳曰。韔、弓室也。鄭風作鬯。傳曰。鬯弓、弢弓也。然則弢與韔與韣同物。故許皆以弓衣釋之。月令曰。帶以弓韣。少儀曰。弓則以左手屈韣執拊。是又名韣而可屈。則以韋爲之也。革部又曰。鞬、所以戢弓矢。方言曰。弓謂之鞬。或謂之？丸。廣雅。鞬、弓藏也。皾㿪、矢藏也。合三書言之。鞬？丸乃藏弓矢所通稱也。"}]},"弩":{"expl":"弓有臂者。《周禮》四弩：夾弩、庾弩、唐弩、大弩。从弓奴聲。","rad":"弓","fq":"奴古切","vol":"12","py":"nǔ","duan":[{"e":"弓有臂者。从弓。奴聲。","n":"奴古切。五部。"}]},"彀":{"expl":"張弩也。从弓𣪊聲。","rad":"弓","fq":"古候切","vol":"12","py":"ɡòu","duan":[{"e":"張弩也。","n":"射雉賦注引作張弓弩也。詩釋文正義作張弓。皆非。孟子趙注亦但云張弩。葢本謂弩、引申移之弓耳。射雉賦。捧黃閒以密彀。亦謂弩也。孟子曰。羿之敎人射。必志於彀。學者亦必志於彀。趙云。彀、張也。張弩向的者用思專時也。又曰。羿不爲拙射變其彀率。趙云。彀、弩張向表率之正體。望之極思用巧之時。不可變也。按趙注本謂用巧。如朱注云弓滿也、則專謂用力。而非必中矣。大雅。敦弓旣句。句讀倨句之句。毛傳曰。天子之弓合九而成規。是此？倨多句少。言句以見其倨也。不得云句卽彀。"}]},"彉":{"expl":"弩滿也。从弓黃聲。讀若郭。","rad":"弓","fq":"苦郭切","vol":"12","py":"ɡuō","duan":[{"e":"滿弩也。","n":"滿弩者、張而滿之。或作弩滿。非也。吾丘壽王傳曰。十賊彍弩。百吏不敢前。師古云。引滿曰彍。晉語韋注云。張羅闉。去壘五十步而陳。周軍之前後左右。彍弩注矢以誰何。謂之羅闉。唐開元中變府兵置？騎十萬人。彍同彉。"}]},"彃":{"expl":"䠶也。从弓畢聲。《楚詞》曰：“𢏗焉彃日。”","rad":"弓","fq":"卑吉切","vol":"12","py":"bì","duan":[{"e":"䠶也。","n":"䠶者、弓弩發於身而中於遠也。亦謂之彃。"}]},"咥":{"expl":"大笑也。从口至聲。《詩》曰：“咥其笑矣。”","rad":"口","fq":"許旣切","vol":"02","py":"xì","duan":[{"e":"大𥬇也。","n":"衞風毛傳曰。咥咥然𥬇。周易。𡳐虎尾。不咥人。馬云。齕也。此別一義。"}]},"彈":{"expl":"行丸也。从弓單聲。","rad":"弓","fq":"徒案切","vol":"12","py":"dàn","duan":[{"e":"行丸也。","n":"左傳。晉靈公從臺上彈人。而觀其避丸也。引申爲凡抨彈、糾彈之偁。"}]},"發":{"expl":"䠶發也。从弓癹聲。","rad":"弓","fq":"方伐切","vol":"12","py":"fā","duan":[{"e":"䠶發也。","n":"詩曰。壹發五豝。引申爲凡作起之偁。"}]},"𢏗":{"expl":"帝嚳䠶官，夏少康滅之。从弓幵聲。《論語》曰：“𢏗善䠶。”","rad":"弓","fq":"五計切","vol":"12","py":"yì","duan":[{"e":"帝嚳䠶官。夏少康滅之。","n":"云夏少康滅之、則邑部？下云夏后時諸侯夷羿國也。羽部羿下云亦古諸侯也。皆卽此。？、帝嚳射官。爲諸侯。自鉏遷於竆石。所謂有竆后羿也。滅夏后相而篡其位。寒浞殺而代之。浞生奡及豷。少康及后杼滅之。有竆由是遂亡。？與羿古葢同字。而堯時射師彃十日者、高誘云此堯時羿。非有竆后羿。"}]},"弜":{"expl":"彊也。从二弓。凡弜之屬皆从弜。","rad":"弜","fq":"其兩切","vol":"12","py":"jiànɡ","duan":[{"e":"彊也。重也。","n":"重當作緟。見糸部。重弓者、彊之意也。緟、曡之意也。詩交韔二弓傳曰。交二弓於韔中也。"}]},"弼":{"expl":"輔也。重也。从弜㐁聲。","rad":"弜","fq":"房密切","vol":"12","py":"bì","duan":[{"e":"輔也。","n":"輔者、車之輔也。引申爲凡左右之偁。釋詁曰。弼、俌也。人部曰。俌、輔也。俌輔音義皆同也。詩曰。交韔二弓。竹閉緄縢。傳云。交韔、交二弓於韔中也。閉、紲。緄、繩。縢、約也。小雅。騂騂角弓。翩其反矣。傳曰。騂騂、調利皃。不善紲檠巧用則翩然而反也。士喪禮注曰。柲、弓檠。弛則縛之於弓裏備？傷。以竹爲之。詩所謂竹柲緄縢。木部曰。榜、所以輔弓弩檠榜也。然則曰檠、曰榜、曰柲、曰閉者、竹木爲之。曰紲、曰縢者、縛之於弛弓以定其體也。弓必有輔而後正。人亦然。故輔謂之弼。"}]},"弦":{"expl":"弓弦也。从弓，象絲軫之形。凡弦之屬皆从弦。","rad":"弦","fq":"胡田切","vol":"12","py":"xián","duan":[{"e":"弓弦也。","n":"弓弦以絲爲之。張於弓。因之張於琴瑟者亦曰弦。俗別作絃。非也。弦有急意。故董安于性緩、佩弦以自急。心部曰。？、急也。"}]},"盭":{"expl":"弻戾也。从弦省，从盩。讀若戾。","rad":"弦","fq":"郎計切","vol":"12","py":"lì","duan":[{"e":"𢐀戾也。","n":"按此乖戾正字。今則戾行而？廢矣。戾謂犬出戶下而身曲戾。其意略近。故以戾釋？。史記、漢書多用？字。"}]},"玅":{"expl":"急戾也。从弦省，少聲。","rad":"弦","fq":"於霄切","vol":"12","py":"yāo","duan":[{"e":"急戾也。","n":"陸機賦。弦幺徽急。疑當作弦？。"}]},"𤣨":{"expl":"不成，遂急戾也。从弦省，曷聲。讀若瘞葬。","rad":"弦","fq":"於罽切","vol":"12","py":"yì","duan":[{"e":"不成遂急戾也。","n":"不成遂者、不成就也。因之急戾是曰㡫。"}]},"系":{"expl":"繋也。从糸丿聲。凡系之屬皆从系。","rad":"系","fq":"胡計切","vol":"12","py":"xì","duan":[{"e":"縣也。","n":"縣各本作繫。非其義。今正。𥄉部曰。縣者、系也。引申爲凡總持之偁。故系與縣二篆爲轉注。系者、垂統於上而承於下也。系與係可通用。然經傳係多謂束縛。故係下曰絜束也。其義不同。系之義引申爲世系。周禮瞽朦。世帝繫。小史。奠繫世。皆謂帝繫世本之屬。其字借繫爲之。當作系。大傳。繫之以姓而弗別。亦系之叚借。"}]},"啞":{"expl":"笑也。从口亞聲。《易》曰：“笑言啞啞。”","rad":"口","fq":"於革切","vol":"02","py":"è","duan":[{"e":"𥬇也。","n":"馬融曰。啞啞、𥬇聲。鄭云。樂也。"}]},"孫":{"expl":"子之子曰孫。从子从系。系，續也。","rad":"系","fq":"思魂切","vol":"12","py":"sūn","duan":[{"e":"子之子曰孫。","n":"爾雅釋親文也。子卑於父。孫更卑焉。故引申之義爲孫順、爲孫遁。字本皆作孫。經傳中作遜者皆非古也。至部？下解曰。从至。至而復孫。孫、遁也。字作孫不作遜。此許書無遜之證。春秋經。夫人孫于齊。公孫于齊。公羊傳曰。孫猶孫也。內諱奔謂之孫。穀梁傳曰。孫之爲言猶孫也。諱奔也。云猶孫者、謂如孫之退然自處於眇小。詩公孫碩膚箋云。孫讀當如公孫于齊之孫。孫之言孫遁也。周公孫遁。辟此成功之大美。書序。帝堯將孫于位。亦謂遜遁。此等字今皆俗改爲遜。絕非古字古義。惟孫順字唐書作愻。見心部。而俗亦以遜爲之。"}]},"緜":{"expl":"聮微也。从系从帛。","rad":"系","fq":"武延切","vol":"12","py":"mián","duan":[{"e":"聯𣁋也。","n":"聯者、連也。𣁋者、眇也。其相連者甚𣁋眇、是曰緜。引申爲凡聯屬之偁。大雅。緜緜瓜瓞。傳曰。緜緜、不絕皃。又引申爲絲絮之偁。因其媆弱而名之。如糸部絮下云敝緜也、鄭注禮記云纊新緜也是也。又引申爲薄弱之偁。如淮南王安諫伐閩粤曰粤人緜力薄材、不能陸戰是也。"}]},"䌛":{"expl":"隨從也。从系䚻聲。","rad":"系","fq":"余招切","vol":"12","py":"yáo","duan":[{"e":"隨從也。","n":"辵部曰。從、隨行也。隨、從也。䌛與隨、從三篆爲轉注。从系者、謂引之而往也。爾雅釋故曰。䌛、道也。詩書䌛作猷。叚借字。小雅。匪大猶是經。大雅。遠猶辰吿。傳皆曰。猶、道也。書大誥。猷爾多邦。猷亦道也。道路及導引、古同作道。皆隨從之義也。䌛之譌體作䌛。亦用爲？役字。？役者、隨從而爲之者也。"}]},"糸":{"expl":"細絲也。象束絲之形。凡糸之屬皆从糸。讀若覛。","rad":"糸","fq":"莫狄切","vol":"13","py":"mì","duan":[{"e":"細絲也。","n":"絲者。蠶所吐也。細者、微也。細絲曰糸。糸之言蔑也。蔑之言無也。"}]},"繭":{"expl":"蠶衣也。从糸从虫，黹省。","rad":"糸","fq":"古典切","vol":"13","py":"jiǎn","duan":[{"e":"蠶衣也。","n":"衣者、依也。蠶所依曰蠶衣。蠶不自其衣。而以其衣衣天下。此聖人之所取法也。"}]},"繅":{"expl":"繹繭爲絲也。从糸巢聲。","rad":"糸","fq":"穌遭切","vol":"13","py":"sāo","duan":[{"e":"繹繭爲絲也。从糸。巢聲。","n":"穌遭切。二部。俗作繰。乃帛如紺色之字。"}]},"繹":{"expl":"抽絲也。从糸睪聲。","rad":"糸","fq":"羊益切","vol":"13","py":"yì","duan":[{"e":"㩅絲也。","n":"㩅者、引也。引申爲凡駱驛、温尋之稱。駧傳曰。繹繹、善走也。"}]},"緒":{"expl":"絲耑也。从糸者聲。","rad":"糸","fq":"徐呂切","vol":"13","py":"xù","duan":[{"e":"絲耑也。","n":"耑者、艸木初生之題也。因爲凡首之稱。抽絲者得緒而可引。引申之、凡事皆有緒可纘。"}]},"緬":{"expl":"微絲也。从糸面聲。","rad":"糸","fq":"弭沇切","vol":"13","py":"miǎn","duan":[{"e":"𣁋絲也。","n":"𣁋各本作微。今正。緬之引申爲凡緜邈之稱。穀梁莊三年傳曰。改葬之禮緦。舉下、緬也。"}]},"純":{"expl":"絲也。从糸屯聲。《論語》曰：“今也純，儉。”","rad":"糸","fq":"常倫切","vol":"13","py":"chún","duan":[{"e":"絲也。","n":"論語。麻冕、禮也。今也純。孔安國曰。純、絲也。此純之本義也。故其字从糸。按純與？音同。醇者、不澆酒也。叚純爲醇字。故班固曰。不變曰醇。不襍曰粹。崔覲說易曰。不襍曰純。不變曰粹。其意一也。美絲美酒、其不襍同也。不襍則壹、壹則大。故釋詁、毛傳、鄭箋皆曰。純、大也。文王純亦不巳。卽周易之純粹也。詩之純束讀如屯。國語之稛、左傳之？皆其字也。禮之純釋爲緣。實卽緣之音近叚借也。"}]},"噱":{"expl":"大笑也。从口豦聲。","rad":"口","fq":"其虐切","vol":"02","py":"jué","duan":[{"e":"大𥬇也。从口。豦聲。","n":"其虐切。五部。"}]},"綃":{"expl":"生絲也。从糸肖聲。","rad":"糸","fq":"相幺切","vol":"13","py":"xiāo","duan":[{"e":"生絲也。","n":"韵會作生絲繒也。今按言繒名則非其次。依鄭君則實繒名。當云生絲也、一曰繒名。生絲、未湅之絲也。巳湅之繒曰練。未湅之絲曰綃。以生絲之繒爲衣、則曰綃衣。古經多作宵、作繡。特牲禮。主婦纚筓宵衣。注曰。宵衣染之以黑、其繒本名曰綃。詩有素衣朱綃。記有玄綃衣。凡婦人助祭者同服也。少牢禮注曰大夫妻尊亦衣綃衣。而侈其袂。玉藻曰。君子狐青裘豹褎。玄綃衣以裼之。注曰。綃、綺屬也。郊特牲。繡黼丹朱中衣。注曰。繡讀爲綃。綃、繒名也。引詩素衣朱綃。合此數條知宵、繡皆叚借字。以此生絲織繒曰綃。仍從絲得名也。故或云繒名。或云綺屬。綺卽文繒也。"}]},"𦂄":{"expl":"大絲也。从糸皆聲。","rad":"糸","fq":"口皆切","vol":"13","py":"kāi","duan":[{"e":"大絲也。从糸。皆聲。","n":"口皆切。十五部。"}]},"𥿪":{"expl":"絲曼延也。从糸巟聲。","rad":"糸","fq":"呼光切","vol":"13","py":"huānɡ","duan":[{"e":"絲曼延也。","n":"曼延曡韵字。曼、引也。延、行也。？之言网也。巾部有㡃。㡃氏湅絲。㡃？古葢一字。"}]},"紇":{"expl":"絲下也。从糸气聲。《春秋傳》有臧孫紇。","rad":"糸","fq":"下沒切","vol":"13","py":"hé","duan":[{"e":"絲下也。","n":"謂絲之下、者也。"}]},"𥿄":{"expl":"絲滓也。从糸氐聲。","rad":"糸","fq":"都兮切","vol":"13","py":"dī","duan":[{"e":"絲滓也。","n":"滓者、澱也。因以爲凡物渣滓之稱。"}]},"絓":{"expl":"繭滓絓頭也。一曰以囊絮練也。从糸圭聲。","rad":"糸","fq":"胡卦切","vol":"13","py":"huà","duan":[{"e":"繭滓絓頭也。","n":"謂繅時繭絲成結。有所絓礙。工女蠶功畢後。别理之爲用也。引申爲挂礙之稱。按集韵、類篇皆作繭滓也、一曰絓頭。此古本也。一曰絓頭者、一名絓頭也。"}]},"纅":{"expl":"絲色也。从糸樂聲。","rad":"糸","fq":"以灼切","vol":"13","py":"yào","duan":[{"e":"絲色也。","n":"謂絲之色光采灼然也。考工記曰。絲欲沈。注云。如在水中時色。今人謂之漂亮。"}]},"繀":{"expl":"著絲於筟車也。从糸崔聲。","rad":"糸","fq":"穌對切","vol":"13","py":"suì","duan":[{"e":"箸絲於筟車也。","n":"竹部曰。筟、筳也。筳、繀絲筦也。筟車亦曰繀車。方言曰。繀車、趙魏之閒謂之轣轆。車齊海岱之閒謂之道軌。箸絲於筳謂之繀。"}]},"經":{"expl":"織也。从糸巠聲。","rad":"糸","fq":"九丁切","vol":"13","py":"jīnɡ","duan":[{"e":"織從絲也。","n":"從絲二字依太平御覽卷八百二十六補。古謂橫直爲衡從。毛詩云衡從其畝是也。字本不作縱。後人妄以代之。分别其音有慈容、足容之不同。韓詩作橫由其畝。其說曰東西耕曰橫。南北耕曰由。由卽從也。何必讀如？乎。織之從絲謂之經。必先有經而後有緯。是故三綱五常六藝謂之天地之常經。大戴禮曰。南北曰經。東西曰緯。抑許云絞、縊也。縊、經也。縊死何言經死也。謂以繩直縣而死。從絲之義之引申也。平者、立者皆得謂之從。按獨言從絲者、蒙上文專言帛。以謂布之有從縷同也。"}]},"織":{"expl":"作布帛之緫名也。从糸戠聲。","rad":"糸","fq":"之弋切","vol":"13","py":"zhī","duan":[{"e":"作布帛之總名也。","n":"布者麻縷所成。帛者絲所成。作之皆謂之織。許此部别布於絲。自緝篆至絣篆二十六字皆言布也。而有不可分者、如織篆是也。經與緯相成曰織。古叚爲識字。如詩之織文、微識也。"}]},"唏":{"expl":"笑也。从口，稀省聲。一曰哀痛不泣曰唏。","rad":"口","fq":"虚豈切","vol":"02","py":"xī","duan":[{"e":"𥬇也。","n":"廣雅。唏唏、𥬇也。"}]},"𥿮":{"expl":"樂浪挈令織。从糸从式。","rad":"糸","fq":"","vol":"13","py":"zhì","duan":[{"e":"樂浪挈令。織从糸、从式。","n":"樂浪、漢幽州郡名也。挈令者、漢張湯傳有廷尉挈令。韋昭曰。在板挈也。後書應劭傳作廷尉板令。史記又作絜令。漢燕王旦傳又有光祿挈令。挈當作栔。栔、刻也。樂浪郡栔於板之令也。其織字如此。錄之者、明字合於六書之法則無不可用也。如錄漢令之鬲作㽁。"}]},"紝":{"expl":"機縷也。从糸壬聲。","rad":"糸","fq":"如甚切","vol":"13","py":"rèn","duan":[{"e":"機縷也。","n":"蠶曰絲。麻曰縷。縷者、綫也。綫者、縷也。喪服言縷若干升。孟子以麻縷絲絮竝言。皆謂麻也。然亦有麻絲竝言縷者。機縷是也。機縷、今之機頭。內則曰。執麻枲。治絲繭。織紝組紃。紝合麻枲絲繭言之。左傳魯賂楚以執？、執鍼、織紝皆百人。杜曰。織紝、織繒布者。"}]},"綜":{"expl":"機縷也。从糸宗聲。","rad":"糸","fq":"子宋切","vol":"13","py":"zònɡ","duan":[{"e":"機縷也。","n":"此亦兼布帛言之也。玄應書引說文機縷也。謂機縷持絲交者也。下八字葢庾儼默注。又引三倉綜理經也。謂機縷持絲交者也。屈繩制經令得開合也。按今尚謂之綜。引申之義爲兼綜、爲錯綜。太玄經曰。乃綜于名。"}]},"綹":{"expl":"緯十縷爲綹。从糸咎聲。讀若柳。","rad":"糸","fq":"力久切","vol":"13","py":"liǔ","duan":[{"e":"緯十縷爲綹。","n":"此亦兼布帛言之也。故篇、韵曰。緯十絲曰綹。文互相足也。許言縷不言絲者、言縷可以包絲。言絲不可以包縷也。"}]},"緯":{"expl":"織橫絲也。从糸韋聲。","rad":"糸","fq":"云貴切","vol":"13","py":"wěi","duan":[{"e":"織衡絲也。","n":"衡各本作橫。今正。凡漢人用字皆作從衡。許曰。橫、闌足也。不對植者言也。云織衡絲者、對上文織從絲爲言。故言絲以見縷。經在軸。緯在杼。木部曰。杼、機之持緯者也。引申爲凡交會之稱。漢人左右六經之書謂之祕緯。"}]},"緷":{"expl":"緯也。从糸軍聲。","rad":"糸","fq":"王問切","vol":"13","py":"yùn","duan":[{"e":"緯也。","n":"此亦兼布帛言之也。緯亦稱緷者、語之轉也。微文二部每互轉。爾雅。百羽謂之緷。古本反。按此緷字正許書㯻字之叚借。玉篇云緷、大束也是也。"}]},"繢":{"expl":"織餘也。从糸貴聲。","rad":"糸","fq":"胡對切","vol":"13","py":"huì","duan":[{"e":"織餘也。","n":"此亦兼布帛言之也。上文機縷爲機頭。此織餘爲機尾。繢之言遺也。故訓爲織餘。織餘、今亦呼爲機頭。可用系物及飾物。急就篇絛繢總爲一類。是也。顔、王注未諦。今則此義廢矣。"}]},"統":{"expl":"紀也。从糸充聲。","rad":"糸","fq":"他綜切","vol":"13","py":"tǒnɡ","duan":[{"e":"紀也。","n":"淮南泰族訓曰。繭之性爲絲。然非得女工煑以熱湯而抽其統紀、則不能成絲。按此其本義也。引申爲凡綱記之稱。周易。乃統天。鄭注云。統、本也。公羊傳。大一統也。何注。統、始也。"}]},"紀":{"expl":"絲別也。从糸己聲。","rad":"糸","fq":"居擬切","vol":"13","py":"jì","duan":[{"e":"别絲也。","n":"别絲各本作絲别。棫樸正義引紀、别絲也。又云。紀者、别理絲縷。今依以正。别絲者、一絲必有其首、别之是爲紀。衆絲皆得其首、是爲統。統與紀義互相足也。故許不析言之。禮器曰。衆之紀也。紀散而衆亂。注曰。紀者、絲縷之數有紀也。此紀之本義也。引申之爲凡經理之稱。詩。網紀四方。箋云。以罔罟喻爲政。張之爲綱。理之爲紀。洪範九疇。四、五紀。斗牽牛爲星紀。史記每帝爲本紀、謂本其事而分别紀之也。詩。滔滔江漢。南國之紀。毛傳曰。其神足以綱紀一方。箋云。南國之大川。紀理衆水。使不壅滯。"}]},"繈":{"expl":"觕纇也。从糸强聲。","rad":"糸","fq":"居兩切","vol":"13","py":"qiǎnɡ","duan":[{"e":"𧢼纇也。","n":"𧢼見角部。各本作觕。非也。今正。𧢼訓角長。引申爲凡粗長之稱。絲節粗長謂之繦。孟康曰。繦、錢貫也。其引申之義也。又引申爲繦緥。呂覽明理篇。道多繦緥。高注。緥、小兒被也。繦、褸格上繩也。又直諫篇繦緥注。繦、褸格繩。緥、小兒𧝐也。褸卽縷。格卽絡。織縷爲絡、以負之於背。其繩謂之繦。高說冣分明。博物志云。織縷爲之。廣八寸。長二尺。乃謂其絡。未及其繩也。凡繩韌者謂之繦。"}]},"琠":{"expl":"玉也。从玉典聲。","rad":"玉","fq":"多殄切","vol":"01","py":"tiǎn","duan":[{"e":"玉也。从王。典聲。","n":"多殄切。古音在十三部。玉篇曰。古文作𤩴。"}]},"听":{"expl":"笑皃。从口斤聲。","rad":"口","fq":"宜引切","vol":"02","py":"yǐn","duan":[{"e":"𥬇兒也。","n":"司馬相如賦。亾是公听然而𥬇。"}]},"纇":{"expl":"絲節也。从糸頪聲。","rad":"糸","fq":"盧對切","vol":"13","py":"lèi","duan":[{"e":"絲節也。","n":"節者、竹約也。引申爲凡約結之稱。絲之約結不解者曰纇。引申之、凡人之愆尤皆曰纇。左傳忿纇無期是也。亦叚類爲之。昭十六年傳曰。㓝之頗類。服虔讀類爲纇。解云。纇、不平也。"}]},"紿":{"expl":"絲勞卽紿。从糸台聲。","rad":"糸","fq":"徒亥切","vol":"13","py":"dài","duan":[{"e":"絲勞卽紿。","n":"卽當爲則。古書卽則多互譌。絲勞敝則爲紿。紿之言怠也。如人之劵怠然。古多叚爲詒字。言部曰。詒者、相欺詒也。"}]},"納":{"expl":"絲溼納納也。从糸内聲。","rad":"糸","fq":"奴荅切","vol":"13","py":"nà","duan":[{"e":"絲溼納納也。","n":"納納、溼意。劉向九歎。衣納納而掩露。王逸注。納納、濡溼貌。漢酷吏傳。阿邑人主。蘇林曰。邑音人相悒納之悒。按悒納當作浥納。媕阿之狀。於濡溼義近也。古多叚納爲內字。內者、入也。"}]},"紡":{"expl":"網絲也。从糸方聲。","rad":"糸","fq":"妃兩切","vol":"13","py":"fǎnɡ","duan":[{"e":"紡絲也。","n":"紡各本作網。不可通。唐本作拗。尤誤。今定爲紡絲也三字句。乃今人常語耳。凡不必以他字爲訓者、其例如此。絲之紡、猶布縷之績緝也。左傳。莒婦人紡焉以度而去之。葢緝布縷爲繩、亦用紡名也。晉語。執而紡於廷之槐。亦謂以紡縷繩縛之也。聘禮。賓裼迎大夫。賄用束紡。鄭曰。紡、紡絲爲之。今之縳也。縳見下文。白鮮支也。據此、是紡絲專用作絹也。"}]},"絕":{"expl":"斷絲也。从糸从刀从卩。","rad":"糸","fq":"情雪切","vol":"13","py":"jué","duan":[{"e":"𣃔絲也。","n":"𣃔之則爲二、是曰絕。引申之、凡横越之曰絕。如絕河而渡是也。又絕則窮。故引申爲極。如言絕美、絕妙是也。許書𨸏部云。陘、山絕坎也。是中𣃔之義也。水部曰。榮、絕小水也。是極至之義也。閻氏百詩乃以絕河釋滎、以釋禹貢。不知禹貢熒澤自古作从三火之熒。後人乃譌爲滎。"}]},"繼":{"expl":"續也。从糸、㡭。一曰反𢇍爲繼。","rad":"糸","fq":"古詣切","vol":"13","py":"jì","duan":[{"e":"續也。","n":"虞翻注易曰。繼、統也。"}]},"續":{"expl":"連也。从糸賣聲。","rad":"糸","fq":"似足切","vol":"13","py":"xù","duan":[{"e":"連也。","n":"連者、負車也。聯者、連也。皆其義也。釋詁曰。繼也。"}]},"纘":{"expl":"繼也。从糸贊聲。","rad":"糸","fq":"作管切","vol":"13","py":"zuǎn","duan":[{"e":"𦇓也。","n":"豳風。載纘武功。傳曰。纘、繼也。中庸。武王纘大王、王季、文王之緒。注曰。纘、繼也。或叚纂爲之。"}]},"紹":{"expl":"繼也。从糸召聲。一曰紹，緊糾也。","rad":"糸","fq":"市沼切","vol":"13","py":"shào","duan":[{"e":"𦇓也。","n":"同釋詁。"}]},"𦅗":{"expl":"偏緩也。从糸羨聲。","rad":"糸","fq":"昌善切","vol":"13","py":"chǎn","duan":[{"e":"偏緩也。","n":"緩正作？。繛也。毛詩。檀車幝幝。毛曰。幝幝、敝皃。釋文云。韓詩作𦅗𦅗。葢物敝則緩。其義相通。"}]},"呭":{"expl":"多言也。从口世聲。《詩》曰：“無然呭呭。”","rad":"口","fq":"余制切","vol":"02","py":"yì","duan":[{"e":"多言也。","n":"孟子、毛傳皆曰。泄泄猶沓沓也。曰部云。沓、語多沓沓也。言部又云。詍、多言也。引詩無然詍詍。"}]},"䋼":{"expl":"緩也。从糸盈聲。讀與聽同。","rad":"糸","fq":"他丁切","vol":"13","py":"tīnɡ","duan":[{"e":"緩也。","n":"䋼之言挺也。挺有緩意。䋼與綎義别。韵會誤合爲一字。"}]},"縱":{"expl":"緩也。一曰舍也。从糸從聲。","rad":"糸","fq":"足用切","vol":"13","py":"zònɡ","duan":[{"e":"緩也。一曰捨也。","n":"各本作舍也。由俗以舍捨通用也。今正。捨者、釋也。"}]},"紓":{"expl":"緩也。从糸予聲。","rad":"糸","fq":"傷魚切","vol":"13","py":"shū","duan":[{"e":"緩也。","n":"小雅。彼交匪紓。傳曰。紓、緩也。左傳多用紓字。其義皆同。亦叚抒爲之。"}]},"繎":{"expl":"絲勞也。从糸然聲。","rad":"糸","fq":"如延切","vol":"13","py":"rán","duan":[{"e":"絲勞也。","n":"勞玉篇作縈。葢玉篇爲是。與下文紆義近也。或曰縈篆何以不次此。曰後文？縈等篆皆統於繩。繎紆則謂絲也。廣韵作絲勞皃。"}]},"紆":{"expl":"詘也。从糸于聲。一曰縈也。","rad":"糸","fq":"億俱切","vol":"13","py":"yū","duan":[{"e":"詘也。","n":"詘者、詰詘也。今人用屈曲字。古人用詰詘。亦單用詘字。易曰。往者詘也。來者信也。詘謂之紆。考工記。連行紆行。亦或叚汙爲之。左傳曰。盡而不汙。"}]},"緈":{"expl":"直也。从糸㚔聲。讀若陘。","rad":"糸","fq":"胡頂切","vol":"13","py":"xìnɡ","duan":[{"e":"直也。","n":"廣韵云。絓婞。"}]},"纖":{"expl":"細也。从糸韱聲。","rad":"糸","fq":"息廉切","vol":"13","py":"xiān","duan":[{"e":"𥿳也。","n":"細者、𣁋也。魏風。摻摻女手。韓詩作纖纖女手。毛傳曰。摻摻猶纖纖也。尙書。厥篚玄纖縞。鄭注。纖、細也。漢文紀。遺詔纖七日、釋服。服虔注。纖、細布。凡細謂之纖。其字或作孅。漢食貨志如此。荀卿子纖驪、列子作盜驪。穆天子傳盜驪。郭注爲馬細頸。驪、黑色也。廣雅作駣𩧋。駣者、镺？脩長之謂。盜駣同聲。纖駣同義也。"}]},"細":{"expl":"微也。从糸囟聲。","rad":"糸","fq":"穌計切","vol":"13","py":"xì","duan":[{"e":"𣁋也。","n":"𣁋者、眇也。眇今之妙字。"}]},"緢":{"expl":"旄絲也。从糸苗聲。《周書》曰：“惟緢有稽。”","rad":"糸","fq":"武儦切","vol":"13","py":"miáo","duan":[{"e":"氂絲也。","n":"氂各本作旄。俗所改也。氂者、犛牛尾也。凡羽旄古當作羽氂。氂絲者、犛牛尾之絲至細者也。故次於纖細二篆後。賈子容經。跘旋之容。旄如濯絲。旄同緢。言細如濯絲也。"}]},"縒":{"expl":"參縒也。从糸差聲。","rad":"糸","fq":"楚宜切","vol":"13","py":"cī","duan":[{"e":"參縒也。","n":"參或曑字。此曰參差。木部曰槮差。竹部曰篸差。又曰參差管樂。皆長短不齊皃也。皆雙聲字。集韵、類篇皆引說文參縒也。謂絲亂皃。韵會於差字下引說文參差絲亂皃。葢古本有此三字。"}]},"𡂢":{"expl":"聲𡂢𡂢也。从口䲷聲。","rad":"口","fq":"古堯切","vol":"02","py":"jiāo","duan":[{"e":"聲𡂢𡂢也。","n":"周禮大祝注。祈𡂢也。謂爲有災變。號呼告神以求福。𡂢、陸音叫。"}]},"繙":{"expl":"冕也。从糸番聲。","rad":"糸","fq":"附袁切","vol":"13","py":"fán","duan":[{"e":"繙冤也。","n":"三字句。各本無繙字。冤作冕。今補正。玉篇繙下曰冤也。集韵引說文同。葢謂繙字爲複字而刪之。不知繙冤爲曡韵。古語。集韵、類篇皆曰繙？、亂也。是冤俗作？也。巾部有幡㠾二篆。亦是曡韵。小兒拭觚布也。此謂亂也。仍當補亂字。下文二篆皆訓亂。"}]},"縮":{"expl":"亂也。从糸宿聲。一曰蹴也。","rad":"糸","fq":"所六切","vol":"13","py":"suō","duan":[{"e":"亂也。","n":"釋詁曰。縮、亂也。通俗文云。物不申曰縮。不申則亂。故曰亂也。不申者申之則直。禮記。古者冠縮縫。孟子。自反而縮。皆謂直也。亂者治之。詩曰。縮版以載。爾雅、毛傳皆曰。繩之謂之縮之。治縮曰縮、猶治亂曰亂也。"}]},"紊":{"expl":"亂也。从糸文聲。《商書》曰：“有條而不紊。”","rad":"糸","fq":"亡運切","vol":"13","py":"wèn","duan":[{"e":"亂也。从糸。文聲。","n":"亡運切。十三部。"}]},"級":{"expl":"絲次弟也。从糸及聲。","rad":"糸","fq":"居立切","vol":"13","py":"jí","duan":[{"e":"絲次弟也。","n":"本謂絲之次弟。故其字从糸。引申爲凡次弟之偁。階之次弟。曲禮云拾級聚足連步以上是也。尊卑之次弟。賈生云等級分明而天子加焉、故其尊不可及是也。後漢書注。秦法斬首多者進爵一級。因謂斬首爲級。"}]},"總":{"expl":"聚束也。从糸悤聲。","rad":"糸","fq":"作孔切","vol":"13","py":"zǒnɡ","duan":[{"e":"聚束也。","n":"謂聚而縛之也。悤有散意。糸以束之。禮經之總、束髮也。禹貢之總、禾束也。引申之爲凡兼綜之偁。"}]},"䋰":{"expl":"約也。从糸具聲。","rad":"糸","fq":"居玉切","vol":"13","py":"jú","duan":[{"e":"約也。","n":"革部曰。直轅䡞縛。䡞當爲䋰。大車之衡、約之而巳。不必三束。"}]},"約":{"expl":"纏束也。从糸勺聲。","rad":"糸","fq":"於略切","vol":"13","py":"yuē","duan":[{"e":"纏束也。","n":"束者、縛也。引申爲儉約。"}]},"繚":{"expl":"纏也。从糸𤋯聲。","rad":"糸","fq":"盧鳥切","vol":"13","py":"liǎo","duan":[{"e":"纏也。从糸。尞聲。","n":"盧鳥切。二部。"}]},"纏":{"expl":"繞也。从糸廛聲。","rad":"糸","fq":"直連切","vol":"13","py":"chán","duan":[{"e":"繞也。从糸。廛聲。","n":"直連切。十四部。"}]},"繞":{"expl":"纏也。从糸堯聲。","rad":"糸","fq":"而沼切","vol":"13","py":"rǎo","duan":[{"e":"纏也。从糸。堯聲。","n":"而沼切。二部。"}]},"咄":{"expl":"相謂也。从口出聲。","rad":"口","fq":"當沒切","vol":"02","py":"duō","duan":[{"e":"相謂也。","n":"謂欲相語而先驚之之䛐。凡言咄嗟、咄唶、咄咄怪事者皆取猝乍相驚之意。倉頡篇曰。咄、啐也。說文。啐、驚也。李善注曹植贈彪詩引說文。咄、叱也。"}]},"紾":{"expl":"轉也。从糸㐱聲。","rad":"糸","fq":"之忍切","vol":"13","py":"zhěn","duan":[{"e":"紾轉也。","n":"紾字各本無。今補。此三字句。與上文繙冤也一例。淺人刪之。如離黃倉庚也之刪離、巂周燕也之刪巂耳。紾轉葢古語。鄭司農考工記注之抮縳、卽紾轉二字也。凡了戾曰紾轉。亦單𧦝曰紾。亦曰軫？。牛力反考工記老牛之角紾而昔。鄭司農云。紾讀爲抮轉之抮。孟子㒳云紾兄之臂。趙注皆云。戾也。淮南原道訓抮抱。高注。了戾也。抮抱、廣雅作軫？。云轉戾也。方言曰。軫、戾也。郭注。相了戾也。江東音善。"}]},"缳":{"expl":"落也。从糸瞏聲。","rad":"糸","fq":"胡畎切","vol":"13","py":"xuàn","duan":[{"e":"落也。","n":"落者、今之絡字。古叚落。不作絡。謂包絡也。莊子落馬首、漢書虎落皆作落。木落乃物成之象。故曰落成、曰包落。皆取成就之意也。馬融傳曰。繯橐四野之飛征。李注引說文。又引國語繯於山有牢。賈逵注云。繯、還也。按還環古今字。古用還不用環。國語繯於山有牢、今本譌作環山於有牢。韋注曰。環、繞也。山於誤倒。環爲俗字。葢非韋氏之誤、而淺人轉寫所致也。知古書之貤繆不可知者多矣。"}]},"辮":{"expl":"交也。从糸辡聲。","rad":"糸","fq":"頻犬切","vol":"13","py":"biàn","duan":[{"e":"交也。","n":"玄應引作交織之也。終軍傳曰。解辮髮、削左衽。三蒼叚編爲之。"}]},"結":{"expl":"締也。从糸吉聲。","rad":"糸","fq":"古㞕切","vol":"13","py":"jié","duan":[{"e":"締也。从糸。吉聲。","n":"古屑切。十二部。古無髻字。卽用此。見髟部。"}]},"縎":{"expl":"結也。从糸骨聲。","rad":"糸","fq":"古忽切","vol":"13","py":"ɡǔ","duan":[{"e":"結也。","n":"玉篇云。結不解。"}]},"締":{"expl":"結不解也。从糸帝聲。","rad":"糸","fq":"特計切","vol":"13","py":"dì","duan":[{"e":"結不解也。","n":"解者、判也。下文曰。紐結而可解也。故結而不可解者曰締。"}]},"縛":{"expl":"束也。从糸尃聲。","rad":"糸","fq":"符钁切","vol":"13","py":"fù","duan":[{"e":"束也。","n":"束下曰縛也。與此爲轉注。引申之、所以縛。之之物亦曰縛。"}]},"繃":{"expl":"束也。从糸崩聲。《墨子》曰：“禹葬會稽，桐棺三寸，葛以繃之。”","rad":"糸","fq":"補盲切","vol":"13","py":"bēnɡ","duan":[{"e":"束也。从糸。崩聲。","n":"補盲切。古音在六部。"}]},"絿":{"expl":"急也。从糸求聲。《詩》曰：“不競不絿。”","rad":"糸","fq":"巨鳩切","vol":"13","py":"qiú","duan":[{"e":"急也。","n":"毛詩傳曰。絿、急也。左傳杜注從之。後儒好異乃以緩釋絿。字義於字音不洽矣。絿之言糾也。"}]},"絅":{"expl":"急引也。从糸冋聲。","rad":"糸","fq":"古熒切","vol":"13","py":"jiōnɡ","duan":[{"e":"急引也。","n":"此本義也。中庸。詩曰衣錦尙絅。此叚借爲褧字也。"}]},"唉":{"expl":"譍也。从口矣聲。讀若埃。","rad":"口","fq":"烏開切","vol":"02","py":"āi","duan":[{"e":"應也。","n":"方言。欸、然也。南楚凡言然者曰欸。或曰𧫦。按廣雅欸𧫦然譍也。本方言。許以唉訓應。欠部欸訓訾。與方言異。葢唉欸古通用也。玄應書引作？聲也。"}]},"𥿯":{"expl":"散絲也。从糸𠂢聲。","rad":"糸","fq":"匹卦切","vol":"13","py":"pài","duan":[{"e":"㪔絲也。","n":"𢽳各本作？、今正。𢽳、分離也。水之衺流別曰𠂢。別水曰派。血理之分曰？。？絲曰？。廣韵曰。未緝麻也。"}]},"䌴":{"expl":"不均也。从糸羸聲。","rad":"糸","fq":"力臥切","vol":"13","py":"luò","duan":[{"e":"不均也。","n":"此與纇雙聲。其義亦相近。"}]},"給":{"expl":"相足也。从糸合聲。","rad":"糸","fq":"居立切","vol":"13","py":"jǐ","duan":[{"e":"相足也。","n":"足居人下。人必有足而後體全。故引申爲完足。相足者、彼不足此足之也。故从合。"}]},"綝":{"expl":"止也。从糸林聲。讀若郴。","rad":"糸","fq":"丑林切","vol":"13","py":"chēn","duan":[{"e":"止也。","n":"葢古以綝爲禁字。釋詁曰。綝、善也。"}]},"縪":{"expl":"止也。从糸畢聲。","rad":"糸","fq":"卑吉切","vol":"13","py":"bì","duan":[{"e":"止也。","n":"考工記玉人曰。天子圭中必。注曰。必讀如鹿車縪之縪。謂以組約其中央、爲執之以備失隊。按鹿車卽繀車。東齊海岱之閒謂之道軌。廣雅曰。道軌謂之鹿車。鹿車下鉄、陳宋淮楚之閒謂之畢。所謂鹿車縪也。與用組約圭中央皆所以止者。又詳革部䩛下。"}]},"紈":{"expl":"素也。从糸丸聲。","rad":"糸","fq":"胡官切","vol":"13","py":"wán","duan":[{"e":"𦃃也。","n":"𦃃者、白致繒也。紈卽𦃃也。故从丸、言其滑易也。商頌毛傳曰。丸丸、易直也。釋名曰。紈、渙也。細澤有光渙渙然也。"}]},"終":{"expl":"絿絲也。从糸冬聲。","rad":"糸","fq":"職戎切","vol":"13","py":"zhōnɡ","duan":[{"e":"絿絲也。","n":"按絿字恐誤。疑下文䌖字之譌。取其相屬也。廣韵云。終、極也。竆也。竟也。其義皆當作冬。冬者、四時盡也。故其引申之義如此。俗分別冬爲四時盡、終爲極也竆也竟也。乃使冬失其引申之義、終失其本義矣。有？而後有？、冬而後有終。此造字之先後也。其音義則先有終之古文也。"}]},"䌖":{"expl":"合也。从糸从集。讀若捷。","rad":"糸","fq":"姊入切","vol":"13","py":"jié","duan":[{"e":"合也。","n":"合者、亼口也。因爲凡㒳合之偁。衆絲之合曰䌖。如衣部五采相合曰襍也。"}]},"繒":{"expl":"帛也。从糸曾聲。","rad":"糸","fq":"疾陵切","vol":"13","py":"zēnɡ","duan":[{"e":"帛也。","n":"七篇帛下曰繒也。是爲轉注。春秋傳叚爲鄫字。"}]},"緭":{"expl":"繒也。从糸胃聲。","rad":"糸","fq":"云貴切","vol":"13","py":"wèi","duan":[{"e":"繒也。从糸。胃聲。","n":"云貴切。十五部。"}]},"哉":{"expl":"言之閒也。从口𢦔聲。","rad":"口","fq":"祖才切","vol":"02","py":"zāi","duan":[{"e":"言之閒也。","n":"釋詁。孔𩲸哉延虛無之言閒也。許分別釋之曰。哉爲言之閒。鍇云。若左傳遠哉遙遙、論語君子哉若人是。哉爲閒隔之䛐。按如鍇說。則必句中乃爲言之閒。豈句末者非耶。句中哉字皆可𣃔句。凡㒳者之際曰閒。一者之竟亦曰閒。一之竟卽㒳之際也。言之閒歇多用哉字。若哉生明、初哉首基、則又訓哉爲始。凡竟卽爲始。"}]},"絩":{"expl":"綺絲之數也。《漢律》曰：“綺絲數謂之絩，布謂之總，綬組謂之首。”从糸兆聲。","rad":"糸","fq":"治小切","vol":"13","py":"tiào","duan":[{"e":"綺絲之數也。","n":"言綺以見凡繒也。綺者、文繒也。文繒絲尙有數、則餘繒可知。其若干絲爲一絩、未聞。"}]},"綺":{"expl":"文繒也。从糸奇聲。","rad":"糸","fq":"袪彼切","vol":"13","py":"qǐ","duan":[{"e":"文繒也。","n":"謂繒之有文者也。文者、錯畫也。錯畫謂䢒逪其介畫。繒爲䢒逪方文、謂之文綺。引申之曰交？結綺窗。曰疆場綺分。皆謂似綺文。"}]},"縠":{"expl":"細縛也。从糸𣪊聲。","rad":"糸","fq":"胡谷切","vol":"13","py":"hú","duan":[{"e":"細縳也。","n":"縳之細者也。詩。玼兮玼兮。其之展也。蒙彼縐絺。是紲袢也。傳曰。禮有展衣者。以丹縠爲衣。蒙、覆也。絺之靡者爲縐。靡謂如䊳碎然。細之至也。箋云。縐絺、絺之蹙蹙者是也。此謂裏衣縐絺。外服丹縠衣。縠與縐絺正一類也。今之縐紗、古之縠也。周禮謂之沙。注謂之沙縠。疏云輕者爲沙。縐者爲縠。按古衹作沙。無紗字。"}]},"縳":{"expl":"白鮮色也。从糸專聲。","rad":"糸","fq":"持沇切","vol":"13","py":"juàn","duan":[{"e":"白鮮𠨗也。","n":"𠨗各本作色。今正。下文云。縞、鮮𠨗也。今本譌鮮色。則此色誤亦同。𠨗與支音同。縞爲鮮支。縳爲鮮支之白者。聘禮束紡注曰。紡、紡絲爲之。今之縳也。周禮素沙注曰。素沙者、今之白縳也。釋文皆引說文居掾反。聲類以爲今正絹字。按據許則縳與絹各物。音近而義殊。二禮之鄭注。自謂縳不謂絹也。縳以其質堅名之。字从專。絹以色如麥䅌名之。字从䏍。李登作聲類時巳失其傳矣。若羽人十摶爲縳、左傳縳一如瑱、又皆卷縛之義。非字之本義。"}]},"縑":{"expl":"幷絲繒也。从糸兼聲。","rad":"糸","fq":"古甛切","vol":"13","py":"jiān","duan":[{"e":"幷絲繒也。","n":"謂騈絲爲之。雙絲繒也。呂氏春秋。昔吾所亡者紡緇也。今子之衣襌緇也。以襌緇當紡緇。子豈有不得哉。任氏大椿曰。襌緇卽單緇也。余謂此紡卽方也。竝絲曰方、猶倂船曰方。此紡非紡之本義。後漢輿服志及古今注竝云。合單紡爲一系者同。此方絲所謂兼絲也。"}]},"綈":{"expl":"厚繒也。从糸弟聲。","rad":"糸","fq":"杜兮切","vol":"13","py":"tí","duan":[{"e":"𣆪繒也。","n":"𣆪各本作厚。今正。管子輕重戊篇。管子對桓公。魯梁之民俗爲綈。公服綈。旣又對桓公。宜服帛去綈。然則帛薄綈厚可知也。史記范雎傳索隱曰。葢今之絁。按非也。絁卽許之䌳字。"}]},"練":{"expl":"湅繒也。从糸柬聲。","rad":"糸","fq":"郎甸切","vol":"13","py":"liàn","duan":[{"e":"湅繒也。","n":"湅者、？也。？者、淅也。淅者、汏米也。湅繒汏諸水中。如汏米然。考工記所謂湅帛也。巳湅之帛曰練。引、申爲精𥳑之偁。如漢書練時日、練章程是也。"}]},"縞":{"expl":"鮮色也。从糸高聲。","rad":"糸","fq":"古老切","vol":"13","py":"ɡǎo","duan":[{"e":"鮮𠨗也。","n":"各本作鮮色。今正。漢地理志師古注。縞、鮮支也。司馬相如傳正同。顔語多本說文。彼時未誤。葢支亦作？。因譌色也。廣雅。䋷緫、鮮支、縠、絹也。許謂縞卽鮮支。鄭風。縞衣綦巾。毛曰。縞衣、白色男服也。王逸曰。縞、素也。任氏大椿釋繒曰。孰帛曰練。生帛曰縞。"}]},"䌳":{"expl":"粗緒也。从糸璽聲。","rad":"糸","fq":"式支切","vol":"13","py":"shī","duan":[{"e":"粗緒也。","n":"粗者、疏也。粗緒葢亦繒名。廣韵云。繒似布。俗作絁。玉裁按葢今之綿紬。"}]},"紬":{"expl":"大絲繒也。从糸由聲。","rad":"糸","fq":"直由切","vol":"13","py":"chóu","duan":[{"e":"大絲繒也。","n":"大絲較常絲爲大也。左傳。衞文公大帛之冠。大帛謂大絲繒。後漢書大練亦謂大絲練也。獨𣃔說飛軨以緹紬廣八尺。長拄地。今繒帛通呼爲紬。不必大絲也。叚借爲抽字。史記。紬石室金匱之書。徐廣音抽。師古漢書音冑。皆是也。音胄謂同籒也。籒者、讀書也。釋名曰。紬、抽也。抽引絲耑出細緒也。與許說迥異。"}]},"噂":{"expl":"聚語也。从口尊聲。《詩》曰：“噂沓背憎。”","rad":"口","fq":"子損切","vol":"02","py":"zǔn","duan":[{"e":"聚語也。","n":"小雅傳曰。噂猶噂噂。沓猶沓沓。"}]},"綮":{"expl":"㨖繒也。一曰幑幟，信也，有齒。从糸𢼄聲。","rad":"糸","fq":"康礼切","vol":"13","py":"qǐ","duan":[{"e":"致繒也。","n":"致、送詣也。凡細膩曰致。今之緻字也。漢人多用致、不作緻。致繒曰綮。未聞其證。"}]},"綾":{"expl":"東齊謂布帛之細曰綾。从糸夌聲。","rad":"糸","fq":"力膺切","vol":"13","py":"línɡ","duan":[{"e":"東齊謂布帛之細者曰綾。","n":"同方言。"}]},"縵":{"expl":"繒無文也。从糸曼聲。《漢律》曰：“賜衣者縵表白裏。”","rad":"糸","fq":"莫半切","vol":"13","py":"màn","duan":[{"e":"繒無文也。","n":"春秋䋣露。庶人衣縵。引申之、凡無文皆曰縵。左傳乘縵注。車無文者也。漢食貨志縵田注。謂不𤰝者也。"}]},"繡":{"expl":"五采備也。从糸肅聲。","rad":"糸","fq":"息救切","vol":"13","py":"xiù","duan":[{"e":"五采備也。","n":"考工記。畫繪之事襍五采。五采備謂之繡。鄭氏古文尙書曰。子欲觀古人之象。日、月、星辰、山、龍、華蟲作繢。宗彝、藻、火、粉米、黼、黻希繡。此古天子冕服十二章。希讀爲黹。或作絺、字之誤也。按今人以鍼縷所紩者謂之繡。與畫爲二事。如考工記則繡亦系之畫繪。同爲設色之工也。畫繪與文字又爲一事。故許以觀古人之象說遵修舊文也。"}]},"絢":{"expl":"《詩》云：“素以爲絢兮。”从糸旬聲。","rad":"糸","fq":"許掾切","vol":"13","py":"xuàn","duan":[{"e":"詩云。𦃃㠯爲絢兮。","n":"逸詩。見論語八佾篇。馬融曰。絢、文貌也。鄭康成禮注曰。采成文曰絢。注論語曰。文成章曰絢。許次此篆於繡繪閒者、亦謂五采成文章。與鄭義略同也。鄭注繪事後素云。畫繪先布衆采。然後以素分其閒。以成其文。朱子則云。後素、後於素也。謂先以粉地爲質。而後施五采。據許絢在繡繪閒。繡繪皆五采也。葢許用白受采之恉與。"}]},"繪":{"expl":"會五采繡也。《虞書》曰：“山龍華蟲作繪。”《論語》曰：“繪事後素。”从糸會聲。","rad":"糸","fq":"黃外切","vol":"13","py":"huì","duan":[{"e":"會五采繡也。","n":"會繪㬪韵。今人分咎繇謨繪繡爲二事。古者二事不分。統謂之設色之工而巳。古者繢訓畫、繪訓繡。說見繢下。"}]},"緀":{"expl":"白文皃。《詩》曰：“緀兮斐兮，成是貝錦。”从糸妻聲。","rad":"糸","fq":"七稽切","vol":"13","py":"qī","duan":[{"e":"帛文皃。","n":"帛各本作白。今依韵會正。韵會用小徐本也。"}]},"䋛":{"expl":"繡文如聚細米也。从糸从米，米亦聲。","rad":"糸","fq":"莫礼切","vol":"13","py":"mǐ","duan":[{"e":"繡文如聚細米也。","n":"繡謂畫也。米䋛曡韵。今咎陶謨作粉米。許所見壁中古文作黺䋛。黹部云。黺、畫粉也。此云䋛、繡文如聚細米也。皆古文尙書說也。此不言虞書者、經文巳見於七篇矣。畫粉爲衞宏說。此葢亦衞說與。"}]},"絹":{"expl":"繒如麥䅌。从糸肙聲。","rad":"糸","fq":"吉掾切","vol":"13","py":"juàn","duan":[{"e":"繒如麥䅌色。","n":"色字今補。色譌也、而俗刪之耳。自絹至綟卄三篆皆言繒帛之色。而此色字先之。聲類溷縳絹爲一字。由不考其義之殊也。䅌者、麥莖也。繒色如麥莖靑色也。射雉賦曰。麥漸漸以擢芒。又曰。闚䦓？葉。四月時也。繒色似之曰絹。漢人叚爲？字。"}]},"緑":{"expl":"帛青黃色也。从糸彔聲。","rad":"糸","fq":"力玉切","vol":"13","py":"lǜ","duan":[{"e":"帛靑黃色也。","n":"綠衣毛傳曰。綠、閒色。玉藻正義曰。五方閒色。綠、紅、碧、紫、駵黃是也。木靑剋土黃。東方閒色爲綠。綠色靑黃也。火赤剋金白。南方閒色爲紅。紅色赤白也。金白剋木靑。西方閒色碧。碧色白靑也。水黑剋火赤。北方閒色紫。紫色黑赤也。土黃剋水黑。中央閒色駵黃。駵黃色黃黑也。"}]},"咠":{"expl":"聶語也。从口从耳。《詩》曰：“咠咠幡幡。”","rad":"口","fq":"七入切","vol":"02","py":"qì","duan":[{"e":"聶語也。","n":"耳部曰。聶、附耳私小語也。按聶取㒳耳附一耳。咠取口附耳也。"}]},"縹":{"expl":"帛青白色也。从糸㶾聲。","rad":"糸","fq":"敷沼切","vol":"13","py":"piǎo","duan":[{"e":"帛白靑色也。","n":"白靑各本作靑白。今正。此金剋木之色。所剋當在下也。縹、禮記正義謂之碧。釋名曰。縹猶漂。漂、淺靑色也。有碧縹、有天縹、有骨縹。各以其色所象言之也。"}]},"䋭":{"expl":"帛青經縹緯。一曰育陽染也。从糸育聲。","rad":"糸","fq":"余六切","vol":"13","py":"yù","duan":[{"e":"帛靑經縹緯。","n":"經者從絲。緯者衡絲。"}]},"絑":{"expl":"純赤也。《虞書》“丹朱”如此。从糸朱聲。","rad":"糸","fq":"章俱切","vol":"13","py":"zhū","duan":[{"e":"純赤也。","n":"純同𨣶。厚也。赤、南方色也。按市下云。天子朱市。諸侯赤市。然則朱與赤深淺不同。豳風。我朱孔陽。傳曰。朱、深纁也。陽、明也。許云。纁者淺絳。絳者大赤。葢純赤、大赤其異者微矣。鄭注禮經曰。凡染絳一入謂之縓。再入謂之赬。三入謂之纁。朱則四入與。是朱爲深纁之說也。凡經傳言朱皆當作絑。朱其叚借字也。朱者、赤心木也。"}]},"纁":{"expl":"淺絳也。从糸熏聲。","rad":"糸","fq":"許云切","vol":"13","py":"xūn","duan":[{"e":"淺絳也。","n":"考工記。鍾氏三入爲纁。爾雅。一染謂之縓。再染謂之赬。三染謂之纁。鄭注禮曰。纁裳、淺絳裳也。"}]},"絀":{"expl":"絳也。从糸出聲。","rad":"糸","fq":"丑律切","vol":"13","py":"chù","duan":[{"e":"絳也。","n":"此絀之本義、而廢不行矣。韵會絳作縫。非也。古多叚絀爲黜。"}]},"絳":{"expl":"大赤也。从糸夅聲。","rad":"糸","fq":"古巷切","vol":"13","py":"jiànɡ","duan":[{"e":"大赤也。","n":"大赤者、今俗所謂大紅也。上文純赤者、今俗所謂朱紅也。朱紅淡、大紅濃。大紅如日出之色。朱紅如日中之色。日中貴於日出。故天子朱市。諸侯赤市。赤卽絳也。"}]},"綰":{"expl":"惡也，絳也。从糸官聲。一曰綃也。讀若雞卵。","rad":"糸","fq":"烏版切","vol":"13","py":"wǎn","duan":[{"e":"惡絳也。","n":"惡下各本衍也。今刪。此如粊下云惡米也、繫下云惡絮也。謂絳色之惡者也。"}]},"縉":{"expl":"帛赤色也。《春秋傳》“縉雲氏”，《禮》有“縉緣”。从糸晉聲。","rad":"糸","fq":"即刃切","vol":"13","py":"jìn","duan":[{"e":"帛赤色也。","n":"南都賦引臣瓚云赤白色。玉篇亦云帛赤白。皆誤。赤白則爲下文之紅矣。"}]},"綪":{"expl":"赤繒也。从茜染，故謂之綪。从糸青聲。","rad":"糸","fq":"倉絢切","vol":"13","py":"qiàn","duan":[{"e":"赤繒也。","n":"定四年左傳。分康叔以綪茷。茷卽旆也。杜曰。綪、大赤。取染草名也。襍記注作蒨旆。蒨卽莤也。"}]},"緹":{"expl":"帛丹黃色。从糸是聲。","rad":"糸","fq":"他禮切","vol":"13","py":"tǐ","duan":[{"e":"帛丹黃色也。","n":"謂丹而黃也下文云。縓、帛赤黃色。丹與赤不同者、丹者如丹沙。與赤異。其分甚微。故鄭注草人曰。赤緹、縓色也。酒正五齊。四曰緹齊。注曰。緹者、成而紅赤。若今下酒矣。按紅赤者、赤而白。緹齊不純赤。故謂之紅赤。緹齊俗作醍。見禮運。"}]},"呷":{"expl":"吸呷也。从口甲聲。","rad":"口","fq":"呼甲切","vol":"02","py":"xiā","duan":[{"e":"吸呷也。","n":"司馬相如賦曰。翕呷萃蔡張揖曰。翕呷、衣起張也。海賦、猶尙呀呷。餘波獨湧。李善曰。呀呷、波相吞之皃。吳都賦曰。諠譁喤呷。廣韵。喤呷、衆聲也。"}]},"縓":{"expl":"帛赤黃色。一染謂之縓，再染謂之䞓，三染謂之纁。从糸原聲。","rad":"糸","fq":"七絹切","vol":"13","py":"quàn","duan":[{"e":"帛赤黃色也。","n":"赤黃者、赤而黃也。禮喪服注曰。縓、淺絳也。練冠而麻衣縓緣。三年練之受飾也。檀弓注曰。縓、纁之類。"}]},"紫":{"expl":"帛青赤色。从糸此聲。","rad":"糸","fq":"將此切","vol":"13","py":"zǐ","duan":[{"e":"帛靑赤色也。","n":"靑當作黑。穎容春秋釋例曰。火畏於水。以赤入於黑。故北閒色紫也。論語皇疏、玉藻正義略同。此作靑者、葢如禮器注所云秦二世時語。民言從之。至漢末猶存與。許說必無誤。轉寫亂之耳。"}]},"紅":{"expl":"帛赤白色。从糸工聲。","rad":"糸","fq":"戶公切","vol":"13","py":"hónɡ","duan":[{"e":"帛赤白色也。","n":"春秋釋例曰。金畏於火。以白入於赤。故南方閒色紅也。論語曰。紅紫不以爲褻服。按此今人所謂粉紅、桃紅也。"}]},"𦇎":{"expl":"帛青色。从糸蔥聲。","rad":"糸","fq":"倉紅切","vol":"13","py":"cōnɡ","duan":[{"e":"帛靑色也。","n":"爾雅。靑謂之蔥。蔥卽𦇎也。謂其色蔥。蔥淺靑也。深青則爲藍矣。巿部曰。大夫赤巿。蔥衡。用玉藻文也。潘岳耤田賦。𦇎犗服於縹軛。廣雅。絹一名總。作𦇎者誤。"}]},"紺":{"expl":"帛深青揚赤色。从糸甘聲。","rad":"糸","fq":"古暗切","vol":"13","py":"ɡàn","duan":[{"e":"帛深靑而揚赤色也。","n":"而字依文選注補。揚當作陽。猶言表也。釋名曰。绀、含也。靑而含赤色也。按此今之天靑。亦謂之紅靑。許言陽。劉言含。其意一也。以纁入深靑、而赤見於表是爲紺。賈氏考工疏云。纁入赤汁則爲朱。不入赤汁而入黑汁則爲绀。賈說非也。入深靑乃爲绀。入黑乃爲緅矣。"}]},"綥":{"expl":"帛蒼艾色。从糸𢌿聲。《詩》：“縞衣綥巾。”未嫁女所服。一曰不借綥。","rad":"糸","fq":"渠之切","vol":"13","py":"qí","duan":[{"e":"帛蒼艾色也。","n":"蒼者、艸色也。艾者、仌臺也。蒼艾色、謂蒼然如艾色是爲𦁰。毛傳曰。綦巾、蒼艾色。許所本也。鄭箋則云。綦、綦文也。綦文者、文錯畫也。象交文。今作紋是也。不純綦而紋路蒼畫爲十字相交。是爲綦文。曹風。其弁伊騏。傳曰。騏、騏文也。秦風傳曰。騏、綦文也。魯頌傳。蒼騏曰騏。顧命騏弁。鄭注曰。靑黑曰騏。玉藻綦組綬。注曰。綦文襍色也。皆謂蒼文也。"}]},"繰":{"expl":"帛如紺色。或曰：深繒。从糸喿聲。讀若喿。","rad":"糸","fq":"親小切","vol":"13","py":"zǎo","duan":[{"e":"帛如紺色。","n":"如绀色者、如绀而別於绀也。廣雅系諸靑類。葢比绀色之靑更深矣。禮記用爲澡治字。他書用爲繅絲字。"}]},"緇":{"expl":"帛黑色。从糸甾聲。","rad":"糸","fq":"側持切","vol":"13","py":"zī","duan":[{"e":"帛黑色也。","n":"黑者、北方色也。火所熏之色也。考工記。三入爲纁。五入爲緅。七入爲緇。鄭注曰。玄色者、在緅緇之閒。其六入者與。"}]},"纔":{"expl":"帛雀頭色。一曰微黑色，如紺。纔，淺也。讀若讒。从糸毚聲。","rad":"糸","fq":"七咸切","vol":"13","py":"shān","duan":[{"e":"帛雀頭色也。","n":"今經典緅字許無。纔卽緅字也。考工記。三入爲纁。五入爲緅。七入爲緇。注。染纁者三入而成。又再染以黑則爲緅。緅、今禮俗文作爵。言如爵頭色也。又復再染以黑、乃成緇矣。士冠禮爵弁服注。爵弁者、冕之次。其色赤而微黑。如爵頭然。或謂之緅。依鄭則爵緅纔三字一也。三字雙聲。巾車雀飾注曰。雀、黑多赤少之色。玉裁按今目驗雀頭色赤而微黑。"}]},"𦃖":{"expl":"帛騅色也。从糸剡聲。《詩》曰：“毳衣如𦃖。”","rad":"糸","fq":"土敢切","vol":"13","py":"tǎn","duan":[{"e":"帛騅色也。","n":"騅者、蒼白色也。詳馬部。釋言曰。菼、騅也。王風毛傳曰。菼、騅也。蘆之初生者也。艸部曰。𦵹者、萑之初生。一曰騅帛色如𦵹、故謂之騅色。謂之𦃖也。取其與𦵹同音也。"}]},"嘒":{"expl":"小聲也。从口彗聲。《詩》曰：“嘒彼小星。”","rad":"口","fq":"呼惠切","vol":"02","py":"huì","duan":[{"e":"小聲也。","n":"小雅。鳴蜩嘒嘒。毛曰。嘒嘒、聲也。按商頌。嘒嘒管聲。毛曰。嘒嘒、和也。"}]},"綟":{"expl":"帛戾艸染色。从糸戾聲。","rad":"糸","fq":"郎計切","vol":"13","py":"lì","duan":[{"e":"帛䓞艸染色也。","n":"䓞各本譌戾。韵會譌艾。今正。艸部䓞艸可以染畱黃。染成是爲綟。綟與䓞曡韵。與畱雙聲。畱黃或作駵黃。或作流黃。皇侃作緇黃。葢卽？黃之色。其色黎黑而黃也。漢百官公卿表。諸侯王金壐盭綬。如淳曰。盭音戾。綠盭也。以綠爲質。晉灼曰。盭、艸名也。似艾可染綠。因以爲綬名。按綠近黃。綠爲質而染黑。故曰駵黃。中央之閒色。何承天纂文云。綟、紫色。非也。漢制。綠綟綬在紫綬之上。紫綬一名緺綬。其色靑紫。"}]},"紑":{"expl":"白鮮衣皃。从糸不聲。《詩》曰：“素衣其紑。”","rad":"糸","fq":"匹丘切","vol":"13","py":"fóu","duan":[{"e":"白鱻衣皃。","n":"鱻各本作鮮。今正。許例新鮮字如此作也。毛詩傳曰。絲衣、祭服也。紑、絜鮮皃。"}]},"緂":{"expl":"白鮮衣皃。从糸炎聲。謂衣采色鮮也。","rad":"糸","fq":"充三切","vol":"13","py":"tān","duan":[{"e":"白鱻衣皃。从糸。炎聲。","n":"充彡切。八部。廣韵他甘切。"}]},"繻":{"expl":"繒采色。从糸需聲。讀若《易》“繻有衣”。","rad":"糸","fq":"相俞切","vol":"13","py":"xū","duan":[{"e":"繒采色也。","n":"此本義也。左傳紀裂繻。大夫以裂繻爲名。此繻乃㡏之叚借。巾部曰㡏、繒耑裂也是也。終軍傳。關吏與軍繻。蘇林曰。繻、帛邊也。舊關出入皆以傳。傳因裂繻頭。合以爲符信也。卽左氏裂繻字。正當作㡏。是以二傳作緰。"}]},"縟":{"expl":"繁采色也。从糸辱聲。","rad":"糸","fq":"而蜀切","vol":"13","py":"rù","duan":[{"e":"緐采飾也。","n":"飾各本作色。今依文選西京賦、月賦、景福殿賦、劉越石荅盧諶詩注正。緐本訓馬髦飾。引申之爲緐多。飾本訓㕞也。引申之爲文飾。喪服傳曰。喪成人者其文縟。喪未成人者其文不縟。注曰。縟猶數也。按數如數罟之數。"}]},"纚":{"expl":"冠織也。从糸麗聲。","rad":"糸","fq":"所綺切","vol":"13","py":"xǐ","duan":[{"e":"冠織也。","n":"冠織者、爲冠而設之織成也。凡繒布不䇓翦裁而成者謂之織成。內則注曰。縱、韜髮者也。士冠禮曰。纚廣終幅長六尺。注曰。纚、今之幘。終、充也。纚一幅長六尺。足以韜髮而結之矣。禮經贊者奠纚而後設纚。賓正纚乃加冠。是以纚韜髮而後冠也。此纚葢織成。緇帛廣二尺二寸、長衹六尺。不待翦裁。故曰冠織。漢制。齊三服冠獻冠幘縰。正是織成者。注云。如方目紗。按引申之、网有名纚者。薜綜曰。纚網如箕形。狹後廣前。西京賦曰。纚鰋鮋。吴都賦曰。纚鱨魦。○釋名。纚以韜髮者也。以纚爲之。因以爲之名。按劉語似誤。本爲韜髮之偁。繼乃以爲帛偁。如劉語乃倒其先後矣。"}]},"紘":{"expl":"冠卷也。从糸厷聲。","rad":"糸","fq":"戶萌切","vol":"13","py":"hónɡ","duan":[{"e":"冠卷維也。","n":"維字今依玉篇補。卷經典釋文起權反。玉藻。縞冠玄武。注曰。武、冠卷也。古者冠與卷殊。襍記注曰。秦人曰委。齊東曰武。喪大記注曰。武、吉冠之卷也。冠卷不得偁紘。故知冠卷下有維字。必爲古本矣。周禮弁師注。朱紘、以朱組爲紘也。紘一條屬㒳端於武。又曰。紐小鼻在武上、筓所貫也。士冠禮注曰。有筓者屈組爲紘、垂爲飾。無筓者纓而結其絛。按有筓者謂冕弁。無筓者謂冠。許冖部冠下曰。弁冕之總名也。則此云冠卷維者、謂冕弁之紘以一組自頤下而上屬㒳耑於武者也。葢筓貫於武。紘實屬於筓首耳。許以筓統於卷、故曰冠卷維。許、鄭說略同。戴先生說冠無筓有武。冕弁有筓無武。紘屬於筓。說更明了。○引申之、凡中寛者曰紘。如月令其器圜以閎。閎讀"}]},"紞":{"expl":"冕冠塞耳者。从糸冘聲。","rad":"糸","fq":"都感切","vol":"13","py":"dǎn","duan":[{"e":"冕冠𡫳耳者。","n":"魯語。王后親織玄紞。韋曰。紞所以縣瑱當耳者。齊風。充耳以素乎而。充耳以青乎而。充耳以黄乎而。箋云。素、靑、黄、謂所以縣瑱者。或名爲紞。織之。人君五色。臣則三色而巳。瓊華、瓊瑩、瓊英、謂縣紞之末。所謂瑱也。玉裁按紞所以縣瑱。瑱所以塞耳。紞非塞耳者也。大戴禮。黈絖塞耳。所以揜聰。黈、黃色也。絖同纊。薛綜東京賦注曰。黈纊、言以黃綿大如丸縣冠㒳邊當耳。不欲妄聞不急之言。此薛氏緣辭生訓。大戴絖字乃紞之譌。形之誤也。黃色之紞下垂充耳。人君紞五色。故或單舉玄。或單舉黃。以該他色。自紞譌爲絖。漢初諸儒不能辨證。禮緯、客難、東京賦諸書又改作纊。因起薜氏繆說。而呂忱、顔師古從之。用黃綿塞耳、禮之所無。士喪禮曰。瑱"}]},"纓":{"expl":"冠系也。从糸嬰聲。","rad":"糸","fq":"於盈切","vol":"13","py":"yīnɡ","duan":[{"e":"冠系也。","n":"冠系、可以系冠者也。系者、係也。以二組系於冠卷結頣下是謂纓。與紘之自下而上系於筓者不同。冠用纓。冕弁用紘。纓以固武。卽以固冠。故曰冠系。玉藻之記曰。玄冠朱組纓。天子之冠也。緇布冠繢緌。諸侯之冠也。玄冠丹組纓。諸侯之齊冠也。玄冠綦組纓。士之齊冠也。許此冠字專謂冠、不該冕弁。"}]},"紻":{"expl":"纓卷也。从糸央聲。","rad":"糸","fq":"於兩切","vol":"13","py":"yǎnɡ","duan":[{"e":"纓卷也。","n":"此卷亦起權反。卷本訓厀曲。引申爲凡曲之偁。纓卷、謂纓之曲繞也。是爲紻。"}]},"𤫕":{"expl":"玉也。从玉夒聲。讀若柔。","rad":"玉","fq":"耳由切","vol":"01","py":"náo","duan":[{"e":"玉也。从王。夒聲。讀若柔。","n":"耳尤切。三部。"}]},"嘫":{"expl":"語聲也。从口然聲。","rad":"口","fq":"如延切","vol":"02","py":"rán","duan":[{"e":"語聲也。","n":"方言。欸、然也。廣雅。欸𧫦然譍也。按然卽嘫。應聲也。"}]},"緌":{"expl":"系冠纓也。从糸委聲。","rad":"糸","fq":"儒隹切","vol":"13","py":"ruí","duan":[{"e":"系冠纓𠂹者。","n":"各本作系冠纓也。韵會無也字。皆非。今正。緌與纓無異材。垂其餘則爲緌。不垂則臿於纓卷閒。內則冠緌纓注曰。緌者、纓之餘也。正義曰。結纓頷下以固冠。結之餘者散而下垂謂之緌。按玉藻曰。有事然後緌。檀弓曰。喪冠不緌。扱其餘也。引申之爲旌旂之緌。以旄牛尾爲之。古字或作蕤。或叚綏爲之。"}]},"緄":{"expl":"織帶也。从系昆聲。","rad":"糸","fq":"古本切","vol":"13","py":"ɡǔn","duan":[{"e":"織成帶也。","n":"各本無成字。依文選七啓注、後漢南匈奴傳注補。玉篇帶誤章。凡不待翦裁者曰織成。緄帶見後漢書。葢非三代時物也。詩小戎。竹秘緄縢。毛傳曰。緄、繩也。此古義也。而許不取之。過矣。漢碑用爲衮字。"}]},"紳":{"expl":"大帶也。从糸申聲。","rad":"糸","fq":"失人切","vol":"13","py":"shēn","duan":[{"e":"大帶也。","n":"巾部帶下曰。紳也。與此爲轉注。革部鞶下云。大帶也。男子帶鞶。婦人帶絲。帶下云。紳也。男子鞶帶。婦人帶絲。皆於古大帶革帶不分别。是其疏也。古有革帶以系佩。而後加之大帶。紳則大帶之垂者也。玉藻曰。紳長制士三尺。子游曰。參分帶下、紳居二焉。注云。紳、帶之垂者也。言其屈而重也。許但云大帶。亦是渾言不析言。葢許意以革帶統於大帶。以帶之垂者統於帶。立言不分别也。"}]},"繟":{"expl":"帶緩也。从糸單聲。","rad":"糸","fq":"昌善切","vol":"13","py":"chǎn","duan":[{"e":"帶緩也。","n":"繟之言𦅗也。韓詩。檀車𦅗𦅗。毛詩作幝幝。"}]},"綬":{"expl":"韍維也。从糸受聲。","rad":"糸","fq":"植酉切","vol":"13","py":"shòu","duan":[{"e":"韍維也。","n":"韍古文作市、韠也。韍維、謂所以維韍者。釋器曰。璲、瑞也。此謂玉瑞也。又曰。璲、綬也。郭云。卽佩玉之組。所以連繫瑞者。因通謂之璲。今本字誤古者韍佩皆系於革帶。佩玉之系謂之璲。俗字爲繸。又謂之綬。韍之系亦謂之綬。爾雅渾言之。許析言之。言韍可以該佩也。謂之綬者、韍佩與革帶之閒有聯而受之者。故曰綬。玉藻曰。天子佩白玉而玄組綬。公侯佩山玄玉而朱組綬。大夫佩水蒼玉而純組綬。世子佩瑜玉而綦組綬。士佩瑌玟而縕組綬。孔子佩象環五寸而綦組綬。是其制也。司馬氏輿服志曰。五伯迭興。戰兵不息。於是解去韍佩。畱其係璲。以爲章表。故詩曰。㻆㻆佩璲。此之謂也。至秦乃以采組連結於璲。光明章表。轉相結受。故謂之綬。漢承不改。夫大"}]},"組":{"expl":"綬屬。其小者以爲冕纓。从糸且聲。","rad":"糸","fq":"則古切","vol":"13","py":"zǔ","duan":[{"e":"綬屬也。","n":"屬當作織。淺人所改也。組可以爲綬。組非綬類也。綬織猶冠織。織成之幘梁謂之纚。織成之綬材謂之組。玉藻綬必連組。曰玄組綬、朱組綬是也。內則曰。織紝組紃。周禮典絲掌組。詩曰。執轡如組。傳曰。組、織組也。執轡如組、御衆有文章。言能制衆。動於近、成於遠也。按詩意非謂如組之柔。謂如織組之經緯成文。御衆縷而不亂。自始至終秩然。能御衆者如之也。織成之後所用韍佩之系、其大者也。"}]},"緺":{"expl":"綬紫青也。从糸咼聲。","rad":"糸","fq":"古蛙切","vol":"13","py":"ɡuā","duan":[{"e":"綬紫靑色也。","n":"各本無色。今依後漢南匈奴傳、大平御覽正。百官公卿表曰。丞相、金印紫綬。高帝十一年更名相國、綟綬。徐廣曰。似紫。紫綬名緺綬。其色靑紫。何承天云。緺、靑紫色也。按紫者、水剋火之閒色。又因水生木而色靑。是爲紫靑色。"}]},"縌":{"expl":"綬維也。从糸逆聲。","rad":"糸","fq":"宜戟切","vol":"13","py":"nì","duan":[{"e":"綬維也。","n":"此綬謂漢之綬也。乘輿長丈九尺九寸、至四百石。三百石二百石長丈五尺、百石長丈二尺者是也。綬維謂之縌。乘輿至二千石皆長三尺二寸、千石至二百石皆長三尺者是也。司馬彪曰。縌者、古佩璲也。佩綬相迎受故曰縌。按當曰與綬相迎受故曰縌。縌之言逆也。漢之縌、古之綬也。漢之綬、猶古之韍佩也。縌篆其創於李斯輩與。"}]},"纂":{"expl":"似組而赤。从糸算聲。","rad":"糸","fq":"作管切","vol":"13","py":"zuǎn","duan":[{"e":"佀組而赤。","n":"漢景帝紀曰。錦繡纂組、害女紅者也。臣瓚引此爲注。按組之色不同。似組而赤者、則謂之纂。釋詁曰。纂、繼也。此謂纂卽纘之叚借也。近人用爲撰集之偁。"}]},"紐":{"expl":"系也。一曰結而可解。从糸丑聲。","rad":"糸","fq":"女久切","vol":"13","py":"niǔ","duan":[{"e":"系也。","n":"今本系下曰。係也。係者、結束也。"}]},"唪":{"expl":"大笑也。从口奉聲。讀若《詩》曰“瓜瓞菶菶”。","rad":"口","fq":"方蠓切","vol":"02","py":"běnɡ","duan":[{"e":"大𥬇也。","n":"玉篇、手鑑皆作大聲。"}]},"綸":{"expl":"青絲綬也。从糸侖聲。","rad":"糸","fq":"古還切","vol":"13","py":"lún","duan":[{"e":"糾靑絲綬也。","n":"各本無糾字。今依西都賦李注、急就篇顏注補。糾、三合繩也。糾靑絲成綬、是爲綸。郭璞賦云。靑綸競糾。正用此語。緇衣注曰。綸、今有秩、嗇夫所佩也。釋艸。綸似綸。郭曰。今有秩、嗇夫所帶糾靑絲綸。法言。五㒳之綸。李軌云。綸、糾靑絲綬也。今本法言改糾爲如。不可通矣。攷輿服志。乘輿黃赤綬。諸侯王赤綬。諸國貴人相國皆綠綟綬。公侯將軍紫綬。九卿、中二千石、二千石靑綬。千石、六百石黑綬。四百石、三百石、二百石黃綬。百石靑绀綸。一采宛轉繆織。長丈二尺。按繆卽糾字。自黃綬以上、綬之廣皆尺六寸。皆計其首。首多者系細。首少者系粗。皆必經緯織成。至百石而不計其首。合靑絲繩辮織之。有經無緯。謂之宛轉繩。若今人用絲繩如箸粗爲帶"}]},"綎":{"expl":"系綬也。从糸廷聲。","rad":"糸","fq":"他丁切","vol":"13","py":"tīnɡ","duan":[{"e":"系綬也。","n":"系當作絲。廣韵曰。絲綬、帶綎。玉篇曰。絲綎、綬也。按此綬葢綬之類而巳。非印綬之綬。"}]},"絙":{"expl":"緩也。从糸亘聲。","rad":"糸","fq":"胡官切","vol":"13","py":"huán","duan":[{"e":"緩也。","n":"緩當作綬。玉篇絙下曰。絙、綬也。此亦綬之類也。"}]},"繐":{"expl":"細疏布也。从糸惠聲。","rad":"糸","fq":"私銳切","vol":"13","py":"suì","duan":[{"e":"細疏布也。","n":"禮經曰。繐衰裳牡麻絰。旣葬除之者。傳曰。繐衰者何。以小功之縷也。注云。治其縷如小功、而成布四升半。細其縷者、以恩輕也。升數少者、以服至尊也。凡布細而疏者謂之繐。今南陽有鄧繐。按小功十升若十一升成布。而此用小功之縷四升半成布。是爲縷細而布疏。其名曰繐者、布本有一種細而疏者曰繐。但不若繐衰之大疏。而繐衰之名繐、實用其意。故鄭舉凡布以名之。劉氏釋名說繐衰亦曰細而疏如繐也。許云細疏布、亦謂凡布。不主繐衰。與緆本爲細布名、而錫衰之錫取以爲名正同。故皆不引禮傳。"}]},"㬧":{"expl":"頸連也。从糸，暴省聲。","rad":"糸","fq":"補各切","vol":"13","py":"bó","duan":[{"e":"頸連也。","n":"頸當作領。玉篇作領連。是也。謂聯領於衣也。衣部曰。襮、黼領也。毛傳曰。襮、領也。領謂之襮。連領謂之？。玉篇以爲同字也。"}]},"紟":{"expl":"衣系也。从糸今聲。","rad":"糸","fq":"居音切","vol":"13","py":"jīn","duan":[{"e":"衣系也。","n":"聯合衣襟之帶也。今人用銅鈕。非古也。凡結帶皆曰紟。玉藻。紳韠結三齊。注云。結、約餘也。結或爲紟。宋本如此韋注國語曰。帶甲者紟鎧也。紟、今本譌衿。荀卿非十二子曰。其纓禁緩。叚禁爲紟也。按襟、交衽也。俗作衿。今人衿紟不別。又喪禮紟、單被也。乃紟之別一義。亦因可以固結之義引申之。"}]},"緣":{"expl":"衣純也。从糸彖聲。","rad":"糸","fq":"以絹切","vol":"13","py":"yuàn","duan":[{"e":"衣純也。","n":"此以古釋今也。古者曰衣純。見經典。今曰衣緣。緣其本字。純其叚借字也。緣者、沿其邊而飾之也。深衣曰。純袂緣。純邊廣各寸半。袂緣猶袂口也。廣各寸半者、表裏共三寸也。旣夕禮注曰。飾裳在幅曰綼。在下曰緆。緣之義引申爲因緣、夤緣。而俗遂分別其音矣。"}]},"纀":{"expl":"裳削幅謂之纀。从糸僕聲。","rad":"糸","fq":"博木切","vol":"13","py":"pú","duan":[{"e":"常削幅謂之纀。","n":"爾雅釋器文也。郭云。削殺其幅、深衣之裳也。按許書之削當作消。纀之言僕也。僕之言附也。"}]},"絝":{"expl":"脛衣也。从糸夸聲。","rad":"糸","fq":"苦故切","vol":"13","py":"kù","duan":[{"e":"脛衣也。","n":"今所謂套袴也。左右各一。分衣㒳脛。古之所謂絝。亦謂之褰。亦謂之襗。見衣部。若今之滿當袴、則古謂之㡓。亦謂之幒。見巾部。此名之宜別者也。"}]},"繑":{"expl":"絝紐也。从糸喬聲。","rad":"糸","fq":"牽搖切","vol":"13","py":"qiāo","duan":[{"e":"絝紐也。","n":"紐者、系也。脛衣上有系。系於㡓帶曰繑。"}]},"嗔":{"expl":"盛气也。从口眞聲。《詩》曰：“振旅嗔嗔。”","rad":"口","fq":"待年切","vol":"02","py":"tián","duan":[{"e":"盛气也。","n":"門部曰。闐、盛皃。聲義與此同。今毛詩振旅闐闐。許所據作嗔嗔。玉藻。盛氣顚實。注云。顚讀爲闐。盛身中之氣使之闐滿。孟子。塡然𡔷之。是則聲同得相假借也。古音陳。今俗以爲謓恚字。"}]},"緥":{"expl":"小兒衣也。从糸𠈃聲。","rad":"糸","fq":"博抱切","vol":"13","py":"bǎo","duan":[{"e":"小兒衣也。","n":"衣部曰。𧝐、緥也。斯干。載衣之裼。傳曰。裼、褓也。褓、緥之俗字。古多云小皃被也。李奇曰。小皃大藉。師古曰。卽今小兒繃。古多叚借保葆字。"}]},"繜":{"expl":"薉貉中，女子無絝，以帛爲脛空，用絮補核，名曰繜衣，狀如襜褕。从糸尊聲。","rad":"糸","fq":"子昆切","vol":"13","py":"zūn","duan":[{"e":"薉貉中女子無絝。㠯帛爲脛空。用絮補核。名曰繜衣。狀如襜褕。","n":"無絝者、無左右各一之絝也。帛、依急就篇當作布。空腔古今字。核當作覈。果覈之引申也。帛爲脛腔。褚以絮而裹之。若今江東婦之卷胖。胖音如滂去聲。是名繜衣。亦曰母繜。急就篇曰。襌衣蔽膝布母繜。葢蔽厀、繜衣、襜三者相似。故曰狀如襜。衣部曰。襜、衣蔽前也。又曰。直裾謂之襜褕。此當曰狀如襜。不當有褕字。"}]},"紴":{"expl":"絛屬。从糸皮聲。讀若被，或讀若水波之波。","rad":"糸","fq":"博禾切","vol":"13","py":"bō","duan":[{"e":"絛屬。","n":"按急就篇䋐緞紃三字相聯。必三者爲一類也。緞葢本作紴。篆形皮叚相似而譌。縀乃又譌緞。說者因以𡳐後帖解耳。未知是否。"}]},"絛":{"expl":"扁緒也。从糸攸聲。","rad":"糸","fq":"土刀切","vol":"13","py":"tāo","duan":[{"e":"扁緒也。","n":"廣雅作編緒。漢書及賈生新書作偏諸。葢上字作編、下字作諸爲是。諸者謂合衆采也。賈誼傳曰。今民賣僮者。爲之繡衣絲𡳐偏諸緣。服虔曰。偏諸如牙條。以作𡳐緣。又白縠之表。薄紈之裏。緁以偏諸。晉灼曰。以偏諸緁著衣。然則偏諸之爲絛明矣。雜記注曰。紃、若今時絛也。毛詩、左傳正義曰。王后親織玄紞。卽今之絛繩。必用雜采線織之。按紴、䋐葢其闊者。絛其陿者。紃其圜者。"}]},"䋐":{"expl":"采彰也。一曰車馬飾。从糸戉聲。","rad":"糸","fq":"王伐切","vol":"13","py":"yuè","duan":[{"e":"采彰也。","n":"彰者、彣彰也。爲五采彣彰可以緣飾之物也。"}]},"緃":{"expl":"䋐屬。从糸，从從省聲。","rad":"糸","fq":"足容切","vol":"13","py":"zōnɡ","duan":[{"e":"䋐屬。","n":"急就篇絛繢總爲類。師古曰。總一作縱。說文作緃。按羔羊。素絲五總。傳曰。總、數也。豈卽緃與。"}]},"紃":{"expl":"圜采也。从糸川聲。","rad":"糸","fq":"詳遵切","vol":"13","py":"xún","duan":[{"e":"圜采也。","n":"采彰、扁諸、圜采、葢古有是名。而漢語猶然。圜采以采線辮之。其體圜也。內則。織紝組紃。注曰。紃、絛也。襍記。紃以五采。注曰。紃、施諸縫中。若今時絛也。孔穎達曰。似繩者爲紃。"}]},"緟":{"expl":"增益也。从糸重聲。","rad":"糸","fq":"直容切","vol":"13","py":"chónɡ","duan":[{"e":"增益也。","n":"增益之曰緟。經傳統叚重爲之。非字之本。如易之重卦、象傳言重巽。又言洊雷震、習坎、明㒳作離、兼山艮、麗澤兌皆謂緟之也。今則重行而緟廢矣。增益之則加重。故其字从重。許書重文若干皆當作緟文。"}]},"纕":{"expl":"援臂也。从糸襄聲。","rad":"糸","fq":"汝羊切","vol":"13","py":"rǎnɡ","duan":[{"e":"援臂也。","n":"援臂者、㩊衣出其臂也。王制。四方。臝股肱。注云。謂擐衣出其臂脛。蕭該云。擐當作㩊。擐是穿著之名。非出臂之義。陸德明曰。擐舊音患。今宜音宣。依字作㩊。字林云。㩊、㩊臂也。先全反。玉裁按援㩊古今字。㩊、俗又作揎。鄭作擐猶許作援。二聲古同耳。字書、韵書有从？聲之字。今以詛楚文石刻攷之。其云亦應？皇天上帝及大沈久湫之幾靈德賜？劑楚師。釋爲爰、釋爲援皆可。董云古受字。非也。援臂者、援引也。引褎而上之也。是爲纕臂。襄訓解衣。故其字从襄糸。今則攘臂行而纕臂廢矣。攘乃揖讓字。"}]},"纗":{"expl":"維綱，中繩。从糸巂聲。讀若畫，或讀若維。","rad":"糸","fq":"戶圭切","vol":"13","py":"zuī","duan":[{"e":"維綱中繩也。","n":"綱者、网之紘也。又用繩維之。左右皆有繩、而中繩居要。是曰纗。思玄賦舊注云。纗、系也。葢引申之爲凡系之偁。思玄賦曰。纗幽蘭之秋華。李善引通俗文曰。繫幃曰纗。幃者、今之香囊也。通俗文各本作說文。今以意改。"}]},"嘌":{"expl":"疾也。从口𤐫聲。《詩》曰：“匪車嘌兮。”","rad":"口","fq":"撫招切","vol":"02","py":"piāo","duan":[{"e":"疾也。","n":"檜風。匪車嘌兮。毛曰。嘌嘌、無節度也。按無節度者、卽上章所云疾驅。非有道之車也。"}]},"綱":{"expl":"維紘繩也。从糸岡聲。","rad":"糸","fq":"古郎切","vol":"13","py":"ɡānɡ","duan":[{"e":"网紘也。","n":"各本作維紘繩也。今依棫樸正義正。紘者、冠維也。引申之爲凡維系之偁。孔穎達云。紘者、网之大繩。商書曰。若罔在綱。有條而不紊。詩曰。綱紀四方。箋云。以罔罟喻之。張之爲綱。理之爲紀。"}]},"縜":{"expl":"持綱紐也。从糸員聲。《周禮》曰：“縜寸。”","rad":"糸","fq":"爲贇切","vol":"13","py":"yún","duan":[{"e":"綱紐也。","n":"紐者、結而可解也。大曰系。小曰紐。綱之系网也。必以小繩毌大繩而結於网。是曰縜。引申爲凡紐之偁。梓人爲侯。上綱與下綱出舌尋。縜寸焉。注云。綱、所以繫侯於植者也。縜、籠綱者。按綱繩麤大。故以小繩毌大繩爲紐連於侯。其用與网一也。"}]},"綅":{"expl":"絳綫也。从糸，侵省聲。《詩》曰：“貝胄朱綅。”","rad":"糸","fq":"子林切","vol":"13","py":"qīn","duan":[{"e":"綫也。","n":"各本綫上有絳字。今依閟宮釋文、正義正。以綫訓綅。不言色也。綅旣爲絳綫。則經不必言朱矣。閒傳。禫而綅。襍記注。禫旣祭、乃服禫服。朝服綅冠。鄭曰。黑經白緯曰綅。别一義。"}]},"縷":{"expl":"綫也。从糸婁聲。","rad":"糸","fq":"力主切","vol":"13","py":"lǚ","duan":[{"e":"綫也。","n":"此本謂布縷。引申之絲亦名縷。"}]},"綫":{"expl":"縷也。从糸戔聲。","rad":"糸","fq":"私箭切","vol":"13","py":"xiàn","duan":[{"e":"縷也。","n":"鄭司農周禮注曰。線、縷也。此本謂布綫。引申之絲亦偁綫。"}]},"䋉":{"expl":"縷一枚也。从糸穴聲。","rad":"糸","fq":"乎決切","vol":"13","py":"xué","duan":[{"e":"縷一枚也。","n":"一枚猶一箇也。"}]},"縫":{"expl":"以鍼紩衣也。从糸逢聲。","rad":"糸","fq":"符容切","vol":"13","py":"fénɡ","duan":[{"e":"㠯鍼紩衣也。","n":"鍼下曰。所㠯縫也。召南。羔羊之縫。傳曰。縫言縫殺之大小得其宜。引申之義也。"}]},"緁":{"expl":"緶衣也。从糸疌聲。","rad":"糸","fq":"七接切","vol":"13","py":"qiè","duan":[{"e":"𦄱衣也。","n":"下文緶下曰。緁衣也。與此爲轉注。衣部曰。𪗋者、緶也。喪服傳曰。斬者何。不緝也。齊者何。緝也。齊卽𪗋。緝卽緁。叚借字也。緁者、緶其邊也。"}]},"紩":{"expl":"縫也。从糸失聲。","rad":"糸","fq":"直質切","vol":"13","py":"zhì","duan":[{"e":"縫也。","n":"與上文縫爲轉注。黹下曰。鍼縷所紩衣也。凡鍼功曰紩。"}]},"緛":{"expl":"衣戚也。从糸耎聲。","rad":"糸","fq":"而沇切","vol":"13","py":"ruǎn","duan":[{"e":"衣戚也。","n":"戚今之蹙字也。古多用戚、無蹙字。考工記曰。不微至無以爲戚速。詩鄭箋云。縐絺、絺之戚戚者。今俗改作蹙。衣戚、衣部所謂襞。韋部所謂韏。子虛賦。襞積褰縐。紆徐委曲。鬱橈谿谷。張揖注曰。襞積、𥳑齰也。褰、縮也。縐、戚也。其縐中文理。岪鬱迴曲。有似於谿谷也。按𥳑古字。？襉皆今字。縐訓戚、與鄭箋合。俗本譌裁。而小顔、小司馬皆不得其解。甚矣古書之難讀也。衣戚亦曰韏衣。是爲緛。引申之爲凡戚之偁。素問曰。大筋緛短。小筋弛長。緛短謂戚而短也。緛以衣喻。弛以弓喻。"}]},"嘑":{"expl":"唬也。从口虖聲。","rad":"口","fq":"荒烏切","vol":"02","py":"hū","duan":[{"e":"號也。","n":"号部曰。號、嘑也。是爲轉注。雞人夜嘑旦以嘂百官。此嘑字之僅存者也。若銜枚氏嘂呼歎嗚、大雅式號式呼、以及諸書云叫呼者其字皆當作嘑。不當用外息之字。嘑或作謼。崔靈恩毛詩。式號式謼。"}]},"䋎":{"expl":"補縫也。从糸旦聲。","rad":"糸","fq":"丈莧切","vol":"13","py":"zhàn","duan":[{"e":"補縫也。","n":"補者、完衣也。古者衣縫解曰袒。見衣部。今俗所謂綻也。以鍼補之曰䋎。內則云衣裳綻裂、紉鍼請補綴是也。引申之、不必故衣亦曰縫䋎。古豔歌行曰。故衣誰當補。新衣誰當綻。賴得賢主人。覽取爲我䋎。謂故衣誰則補之。新衣誰則縫之。賴有賢主婦見而爲補縫之也。綻字古亦作䋎。淺人改之。"}]},"繕":{"expl":"補也。从糸善聲。","rad":"糸","fq":"時戰切","vol":"13","py":"shàn","duan":[{"e":"補也。","n":"周禮繕人注曰。繕之言勁也、善也。叔于田序注云。繕之言善也。曲禮。招搖在上。急繕其怒。注曰。急猶堅也。繕讀曰勁。按許言補、其本義也。而中含善勁二義。故鄭云之言。不必如曲禮注之改讀也。"}]},"絬":{"expl":"《論語》曰：“絬衣長，短右袂。”从糸舌聲。","rad":"糸","fq":"私列切","vol":"13","py":"xiè","duan":[{"e":"衣堅也。","n":"各本無此三字。以論語曰絬衣長短右袂、冠於从糸之上。今補正。玉篇注曰。堅也。廣韵注曰。堅絬。皆本諸說文古本。非能杜撰也。自淺人不知許有引經說叚借之例。則訓論語絬衣爲堅衣而不可通。乃刪其本義。徑引論語使絬爲䙝之或體。殊不思絬果䙝或字、則當於衣部䙝篆之下出一絬篆。云䙝或从舌聲。不得憒憒如是。且上文云補縫也。下文云綴得理也。堅義正與補綴相合。列字之次弟可攷者如是。衣堅者、今蘇州人所謂勩箸也。"}]},"纍":{"expl":"綴得理也。一曰大索也。从糸畾聲。","rad":"糸","fq":"力追切","vol":"13","py":"léi","duan":[{"e":"綴得理也。","n":"綴者、合箸也。合箸得其理、則有條不紊。是曰纍。樂記曰。纍纍乎端如貫珠。此其證也。"}]},"縭":{"expl":"以絲介履也。从糸离聲。","rad":"糸","fq":"力知切","vol":"13","py":"lí","duan":[{"e":"㠯絲介𡳐也。","n":"介者、畫也。謂以絲介畫𡳐閒爲飾也。葢卽周禮之繶絇。"}]},"𦂐":{"expl":"刀劒緱也。从糸矦聲。","rad":"糸","fq":"古矦切","vol":"13","py":"ɡōu","duan":[{"e":"刀劒𦂐也。","n":"廣韵曰。刀劒頭纏絲爲緱也。按謂人所把處如人之喉然。"}]},"繄":{"expl":"𢧢衣也。从糸殹聲。一曰赤黑色繒。","rad":"糸","fq":"烏雞切","vol":"13","py":"yī","duan":[{"e":"𢧢衣也。","n":"所以韜𢧢者。猶盛弓弩矢器曰医也。叚借爲語䛐。左傳。王室之不壞。繄伯舅是賴。民不易物。惟德繄物。毛詩。伊可懷也。箋云。伊當作繄。繄猶是也。"}]},"縿":{"expl":"旌旗之斿也。从糸參聲。","rad":"糸","fq":"所銜切","vol":"13","py":"shān","duan":[{"e":"旌旗之游所屬也。","n":"各本失所屬二字。今補。㫃部曰。游、旌旗之流也。周禮巾車注云。正幅爲縿。游則屬焉。正義曰。正幅爲縿、爾雅文。又覲禮正義。爾雅說旌旗正幅爲縿。唐後爾雅奪正幅爲縿四字。郉疏不能攷補。縿是旌旗之體。游則屬焉。故孫炎注曰。爲旒於縿。郭璞曰。縿、衆旒所箸。戴先生曰。游箸縿垂者也。交龍鳥隼之屬皆畫於縿。爾雅曰。纁帛縿。鄭本之。曰九旗之帛皆用絳。上有弧以張縿之幅。見覲禮、明堂位、考工記。下以人維之。周禮節服氏六人維王之太常、爾雅維以縷是也。所以太常必維之者、正恐其游長曳地。毛詩。素絲紕之。大夫旌旗之游亦維持之也。游屬於縿而統於縿。然㫃部游下不云旌旗之縿也。則知縿下𣃔不云旌旗之游。理合析言、不得渾言矣。"}]},"徽":{"expl":"衺幅也。一曰三糾繩也。从糸，微省聲。","rad":"糸","fq":"許歸切","vol":"13","py":"huī","duan":[{"e":"衺幅也。","n":"卽詩之邪幅也。傳曰。邪幅、偪也。所以自偪束也。箋云。邪幅、如今行縢也。偪束其脛。自足至厀。按內則謂之偪。許云謂之徽。未見所出。葢猶蔽厀謂之褘與。釋詁曰。徽、善也。止也。大雅箋云。美也。自偪束之義之引申也。"}]},"䋢":{"expl":"扁緒也。一曰弩𦝫鉤帶。从糸折聲。","rad":"糸","fq":"并列切","vol":"13","py":"biē","duan":[{"e":"扁緒也。","n":"見絛下。"}]},"喅":{"expl":"音聲喅喅然。从口昱聲。","rad":"口","fq":"余六切","vol":"02","py":"yù","duan":[{"e":"音聲喅喅然。从口。昱聲。","n":"余六切。古音在七部。"}]},"紉":{"expl":"繟繩也。从糸刃聲。","rad":"糸","fq":"女鄰切","vol":"13","py":"rèn","duan":[{"e":"單繩也。","n":"單各本及集韵作繟。非其義。李文仲字鑒作繹。今依廣韵、佩觿作單。太平御覽引通俗文曰。合繩曰糾。單展曰紉。織繩曰辮。大繩曰絚。釋玄應引字林單繩曰紉。單對合言之。凡言綸言糾皆合三股二股爲之。紉則單股爲之。玉篇曰。紉、繩縷也。展而續之。方言曰。䌪、𠟪、續也。楚謂之紉。葢單股必以他股連接而成。離騷曰。紉秋蘭以爲佩。注。紉、索也。內則。紉鍼請補綴。亦謂綫接於鍼曰紉。"}]},"繩":{"expl":"索也。从糸，蠅省聲。","rad":"糸","fq":"食陵切","vol":"13","py":"shénɡ","duan":[{"e":"索也。","n":"索下云。繩也。艸有莖葉、可作繩索也。故从？糸。繩可以縣、可以束、可以爲閑。故釋訓曰。兢兢、繩繩、戒也。周南傳曰。繩繩、戒愼也。"}]},"䋫":{"expl":"䊸未縈繩。一曰急弦之聲。从糸爭聲。讀若旌。","rad":"糸","fq":"側莖切","vol":"13","py":"zhēnɡ","duan":[{"e":"䊸未縈繩。","n":"未縈繩、謂未重曡繞之如環者。紆者、詘也。少少詘曲之而巳。將縈繩先詘曲之。引申爲凡紆曲之偁。士喪禮。陳襲事于房中。西領南上不綪。注云。綪讀爲䋫。䋫、屈也。江沔之閒謂縈收繩索爲䋫。按許紆下一曰縈也。此卽江沔之閒語也。此云紆未縈繩。用詘訓也。凡器物曲陳之皆曰䋫。"}]},"縈":{"expl":"收韏也。从糸，熒省聲。","rad":"糸","fq":"於營切","vol":"13","py":"yínɡ","duan":[{"e":"收卷也。","n":"卷居轉切。各本作韏。非也。今依韵會、玉篇正。凡舒卷字、古用厀曲之卷。今用气勢之捲。非也。收卷長繩、重曡如環。是爲縈。於營切。今俗語尙不誤。詩周南。葛藟縈之。傳曰。縈、旋也。"}]},"絇":{"expl":"纑繩絇也。从糸句聲。讀若鳩。","rad":"糸","fq":"其俱切","vol":"13","py":"qú","duan":[{"e":"纑繩絇也。","n":"纑者、布縷也。繩者、索也。絇、糾合之謂。以讀若鳩知之。謂若纑若繩之合少爲多皆是也。廣韵。絇、九遇切。絲絇也。唐會眞記崔氏書曰。奉寄采絲一絇。元稹詩曰。棼絲不成絇。正讀九遇切。是唐人多用此語。若屨絇、禮經及禮記皆作絇。周禮作句。鄭云。箸舄屨之頭以爲行戒。句當爲絇。聲之誤也。玉裁按許不言屨飾。但言纑繩絇。許意屨絇字當從周禮作句爲正。取拘止之意。"}]},"縋":{"expl":"以繩有所縣也。《春秋傳》曰：“夜縋納師。”从糸追聲。","rad":"糸","fq":"持僞切","vol":"13","py":"zhuì","duan":[{"e":"㠯繩有所縣也。","n":"縣者、系也。以繩系物垂之是爲縋。縋之言垂也。玄應引縣下有鎮。"}]},"絭":{"expl":"攘臂繩也。从糸𢍏聲。","rad":"糸","fq":"居願切","vol":"13","py":"quàn","duan":[{"e":"纕臂繩也。","n":"纕各本作攘。今正。纕者、援臂也。臂褏易流。以繩約之。是繩謂之絭。絭有叚帣爲之者。史記滑稽列傳。帣韝鞠𦜕。徐廣云。帣、收衣袖也。又有叚卷爲之者。列女傳。趙津女娟攘卷操檝。卷卽絭也。禾部曰。稇、絭束也。冖部曰。冠、絭也。是引申爲凡束縛之偁。"}]},"緘":{"expl":"束篋也。从糸咸聲。","rad":"糸","fq":"古咸切","vol":"13","py":"jiān","duan":[{"e":"所㠯束匧也。","n":"所㠯二字今補。篋者、笥也。束者、縛也。束之者曰緘。引申之、齊人謂棺束曰緘。喪大記作咸。"}]},"縢":{"expl":"緘也。从糸朕聲。","rad":"糸","fq":"徒登切","vol":"13","py":"ténɡ","duan":[{"e":"緘也。","n":"亦所以束者也。周書有金縢。凡艸之藟、木之蘽曰縢。俗作藤。"}]},"編":{"expl":"次𥳑也。从糸扁聲。","rad":"糸","fq":"布玄切","vol":"13","py":"biān","duan":[{"e":"次𥳑也。","n":"以絲次弟竹𥳑而排列之曰編。孔子讀易。韋編三絕。𠕋字下曰。象其札一長一短。中有二編之形。然則駢比其𥳑。上下用絲編二。是以有得靑絲編考工記者也。禮之編茅爲鼎鼏。周禮王后之編列髮爲之。亦猶是法也。"}]},"嘯":{"expl":"吹聲也。从口肅聲。","rad":"口","fq":"穌弔切","vol":"02","py":"xiào","duan":[{"e":"吹聲也。","n":"召南箋曰。嘯、蹙口而出聲也。"}]},"維":{"expl":"車蓋維也。从糸隹聲。","rad":"糸","fq":"以追切","vol":"13","py":"wéi","duan":[{"e":"車葢維也。","n":"車葢之制、詳於考工記。而其維無考。許以此篆專系之車葢。葢必有所受矣。引申之、凡相系者曰維。韍維、綬維是也。管子曰。禮義廉恥。國之四維。"}]},"絥":{"expl":"車絥也。从糸伏聲。","rad":"糸","fq":"平袐切","vol":"13","py":"bèi","duan":[{"e":"車絥也。","n":"郊祀志。雍五畤路車各一乘。駕被具。西畤、畦畤禺車各一乘。禺馬四匹。駕被具。師古曰。駕車備馬之飾皆具。按駕車之飾此所謂絥也。被馬之飾、革部所謂鞁也。"}]},"䋊":{"expl":"乘輿馬飾也。从糸正聲。","rad":"糸","fq":"諸盈切","vol":"13","py":"zhēnɡ","duan":[{"e":"䋊綊、","n":"逗。各本少此二字。今依全書通例補。"}]},"綊":{"expl":"䋊綊也。从糸夾聲。","rad":"糸","fq":"胡頰切","vol":"13","py":"xié","duan":[{"e":"䋊綊也。","n":"其義巳釋於上。故此但云䋊綊也。几緜連字不可分釋者、其例如此。"}]},"䋣":{"expl":"馬髦飾也。从糸𣫭聲。《春秋傳》曰：“可以稱旌緐乎？”","rad":"糸","fq":"附袁切","vol":"13","py":"fán","duan":[{"e":"馬髦飾也。","n":"馬髦、謂馬鬛也。飾亦妝飾之飾。葢集絲絛下垂爲飾曰緐。引申爲緐多。又俗改其字作繁。俗形行而本形廢。引申之義行而本義廢矣。至若鄭注周禮、禮記之繁纓。繁讀爲鞶帶之鞶。謂今馬大帶也。此易字之例。其說與許說絕殊。"}]},"繮":{"expl":"馬紲也。从糸畺聲。","rad":"糸","fq":"居良切","vol":"13","py":"jiānɡ","duan":[{"e":"馬紲也。","n":"釋名曰。韁、疆也。繫之使不得出疆限也。"}]},"紛":{"expl":"馬尾韜也。从糸分聲。","rad":"糸","fq":"撫文切","vol":"13","py":"fēn","duan":[{"e":"馬尾韜也。","n":"韜、劒衣也。引申爲凡衣之偁。釋名曰。紛、放也。防其放弛以拘之也。楊子言車軨馬𩡺。馬𩡺謂結束馬尾。豈韜之而後結之與。羽獵賦注。紛、旗流也。尙書。敿乃干。傳曰。施汝盾紛。離騷用繽紛字。皆引申叚借也。"}]},"紂":{"expl":"馬緧也。从糸，肘省聲。","rad":"糸","fq":"除柳切","vol":"13","py":"zhòu","duan":[{"e":"馬緧也。","n":"方言曰。車紂、自關而車、周洛韓鄭汝潁而車謂之䋺。或謂之曲綯。或謂之曲綸。自關而西謂之紂。"}]},"緧":{"expl":"馬紂也。从糸酋聲。","rad":"糸","fq":"七由切","vol":"13","py":"qiū","duan":[{"e":"馬紂也。","n":"考工記。必䱸其牛後。注云。䱸讀爲緧。關車謂紂爲緧。按亦作䋺。商王紂、古文尙書作受。"}]},"絆":{"expl":"馬縶也。从糸半聲。","rad":"糸","fq":"博幔切","vol":"13","py":"bàn","duan":[{"e":"馬𩡳也。","n":"馬部𩡳下曰。馬絆也。與此爲轉注。小雅。縶之維之。傳曰。縶、絆。維、繫也。周頌曰。言授之縶。以縶其馬。箋云。縶、絆也。按縶謂繩。用此繩亦謂之縶。此凡字之大例。有客其冣明者也。引申爲凡止之偁。"}]},"台":{"expl":"說也。从口㠯聲。","rad":"口","fq":"與之切","vol":"02","py":"yí","duan":[{"e":"說也。","n":"台說者、今之怡悅字。說文怡訓和。無悅字。今文尙書。舜讓于德不台。見漢書王莽傳、班固典引。而五帝本紀本之作舜讓于德不台懌。自序曰。唐堯遜位、虞舜不台。惠之早霣、諸吕不台。皆謂不爲百姓所悅也。古文禹貢。袛台德先。鄭注。敬悅天子之德旣先。"}]},"𦅨":{"expl":"絆前兩足也。从糸須聲。漢令：蠻夷卒有𦅨。","rad":"糸","fq":"相主切","vol":"13","py":"xǔ","duan":[{"e":"絆歬㒳足也。","n":"莊子馬蹏篇。連之以羈𦄼。崔云。絆前㒳足也。吴都賦。𦄼麋麖。劉注同。"}]},"紖":{"expl":"牛系也。从糸引聲。讀若矤。","rad":"糸","fq":"直引切","vol":"13","py":"zhèn","duan":[{"e":"牛系也。","n":"牛系、所以系牛者也。周禮封人作絼。鄭司農云。絼、箸牛鼻繩。所以牽牛者。今時謂之雉。與古者名同。後鄭云。絼字當以豸爲聲。按絼讀如豸。池爾切。漢人呼雉卽絼也。絼變作紖、而讀丈忍切。仍絼雉之雙聲。今人讀紖余忍切、則非也。少儀曰。牛則執紖。"}]},"縼":{"expl":"以長繩繫牛也。从糸旋聲。","rad":"糸","fq":"辭戀切","vol":"13","py":"xuàn","duan":[{"e":"㠯長繩系牛也。","n":"玉篇云。以長繩系牛馬放之也。"}]},"縻":{"expl":"牛轡也。从糸麻聲。","rad":"糸","fq":"靡爲切","vol":"13","py":"mí","duan":[{"e":"牛𦆕也。","n":"𦆕本馬𦆕也。大車駕牛者則曰牛𦆕。是爲縻。潘岳賦曰。洪縻在手。凡言羈縻勿絕、謂如馬牛然也。"}]},"紲":{"expl":"系也。从糸丗聲。《春秋傳》曰：“臣負羈紲。”","rad":"糸","fq":"私列切","vol":"13","py":"xiè","duan":[{"e":"犬系也。","n":"犬字各本無。今補。少儀。犬則執緤。牛則執紖。馬則執靮。注曰。緤、紖、靮皆所以繫制之者。按許以此篆次於牛系、牛？之後。其爲用少儀顯然也。緤本犬系。引申之、馬亦曰紲。故上文繮下曰馬紲也。若紲本謂馬、則宜次於繮篆後矣。"}]},"𦄿":{"expl":"索也。从糸黑聲。","rad":"糸","fq":"莫北切","vol":"13","py":"mò","duan":[{"e":"索也。","n":"易。係用徽纆。劉表曰。三股曰徽。㒳股曰纆。字林曰。㒳合曰糾。三合曰纆。"}]},"緪":{"expl":"大索也。一曰急也。从糸恆聲。","rad":"糸","fq":"古恒切","vol":"13","py":"ɡēnɡ","duan":[{"e":"大索也。","n":"通俗文。大索曰緪。"}]},"繘":{"expl":"綆也。从糸矞聲。","rad":"糸","fq":"余聿切","vol":"13","py":"yù","duan":[{"e":"䌄也。","n":"易井卦。汽至亦未繘井。羸其瓶。鄭云。繘、綆也。方言曰。繘、自關而東周洛韓魏之閒謂之綆。或謂之絡。關西謂之繘。"}]},"綆":{"expl":"汲井綆也。从糸更聲。","rad":"糸","fq":"古杏切","vol":"13","py":"ɡěnɡ","duan":[{"e":"汲井䌄也。","n":"汲者、引水於井也。綆者、汲水索也。何以盛水、則有缶。缶部曰𦉥、汲缾也是也。何以引缾而上、則有綆。春秋傳具綆缶是也。"}]},"絠":{"expl":"彈彄也。从糸有聲。","rad":"糸","fq":"弋宰切","vol":"13","py":"ǎi","duan":[{"e":"彈彄也。","n":"彈者、開弓也。彄者、弓弩耑弦所凥也。弦與弓弩於發矢時相離、是名絠。"}]},"嗂":{"expl":"喜也。从口䍃聲。","rad":"口","fq":"余招切","vol":"02","py":"yáo","duan":[{"e":"喜也。从口。䍃聲。","n":"余招切。二部。此字與䚻義相近。"}]},"𦅾":{"expl":"生絲縷也。从糸敫聲。","rad":"糸","fq":"之若切","vol":"13","py":"zhuó","duan":[{"e":"生絲縷也。","n":"生絲爲縷也。凡蠶者爲絲。麻者爲縷。絲細縷麤。故糾合之絲得偁縷。"}]},"繴":{"expl":"繴謂之罿，罿謂之罬，罬謂之罦。捕鳥覆車也。从糸辟聲。","rad":"糸","fq":"博戹切","vol":"13","py":"bì","duan":[{"e":"繴謂之罿。罿謂之罬。罬謂之罦。捕鳥覆車也。","n":"見釋器及网部。"}]},"緍":{"expl":"釣魚𦅾也。从糸昏聲。吳人解衣相被，謂之緍。","rad":"糸","fq":"武巾切","vol":"13","py":"mín","duan":[{"e":"釣魚𦅾也。","n":"𦅾本施於鳥者。而鉤魚之繩似之。故曰釣魚𦅾。召南曰。其釣維何。維絲伊緍。傳曰。緍、綸也。謂糾絲爲繩也。"}]},"絮":{"expl":"敝緜也。从糸如聲。","rad":"糸","fq":"息據切","vol":"13","py":"xù","duan":[{"e":"敝緜也。","n":"緜者、聯𣁋也。因以爲絮之偁。敝者、敗衣也。因以爲孰之偁。敝緜、孰緜也。是之謂絮。凡絮必絲爲之。古無今之木緜也。以絮納袷衣閒爲袍曰褚。亦曰裝。褚亦作著。以麻縕爲袍亦曰褚。"}]},"絡":{"expl":"絮也。一曰麻未漚也。从糸各聲。","rad":"糸","fq":"盧各切","vol":"13","py":"luò","duan":[{"e":"絮也。","n":"今人聯絡之言。葢本於此。包絡字、漢人多叚落爲之。其實絡之引申也。楊雄傳曰。緜絡天地。以絮喻也。"}]},"纊":{"expl":"絮也。从糸廣聲。《春秋傳》曰：“皆如挾纊。”","rad":"糸","fq":"苦謗切","vol":"13","py":"kuànɡ","duan":[{"e":"絮也。","n":"玉藻。纊爲繭。注曰。纊、今之新緜也。按鄭釋纊爲新緜者、以别於縕之爲新緜及舊絮也。許則謂纊爲絲絮。不分新故。謂縕爲麻紼。與鄭絕異。"}]},"紙":{"expl":"絮一苫也。从糸氏聲。","rad":"糸","fq":"諸氏切","vol":"13","py":"zhǐ","duan":[{"e":"絮一𥮒也。","n":"𥮒各本譌笘。今正。𥮒下曰。潎絮簀也。潎下曰。於水中擊絮也。後漢書曰。蔡倫造意。用樹膚、麻頭及敝布、魚网以爲紙。元興元年奏上之。自是莫不從用焉。天下咸稱蔡侯紙。按造紙昉於漂絮。其初絲絮爲之。以𥮒荐而成之。今用竹質木皮爲紙。亦有緻密竹簾荐之是也。通俗文曰。方絮曰紙。釋名曰。紙、砥也。平滑如砥。"}]},"䋨":{"expl":"治敝絮也。从糸咅聲。","rad":"糸","fq":"芳武切","vol":"13","py":"fǔ","duan":[{"e":"治敝絮也。","n":"敝絮猶故絮也。"}]},"䋈":{"expl":"絜緼也。一曰敝絮。从糸奴聲。《易》曰：“需有衣䋈。”","rad":"糸","fq":"女余切","vol":"13","py":"rú","duan":[{"e":"絜縕也。","n":"絜縕謂束縕也。束縕見蒯通傳。"}]},"繫":{"expl":"繫𦃇也。一曰惡絮。从糸毄聲。","rad":"糸","fq":"古詣切","vol":"13","py":"jì","duan":[{"e":"繫𦃇也。一曰惡絮。","n":"一曰猶一名也。繫𦃇讀如谿黎。曡韵字。音轉爲縴𦃇。縴苦堅切。廣韵十二齊、一先皆曰。縴𦃇、惡絮。是也。釋名曰。煮繭曰莫。莫、幕也。貧者著衣可以幕絮也。或謂之牽離。煮熟爛牽引使離散如絮也。按此與煮繭絓頭不同物。編太平御覽者合而一之。誤矣。"}]},"启":{"expl":"開也。从戶从口。","rad":"口","fq":"康禮切","vol":"02","py":"qǐ","duan":[{"e":"開也。","n":"按後人用啟字訓開。乃廢启不行矣。啟、敎也。玉篇引堯典。胤子朱启明。釋天。明星謂之启明。"}]},"𦃇":{"expl":"繫𦃇也。一曰維也。从糸虒聲。","rad":"糸","fq":"郎兮切","vol":"13","py":"lí","duan":[{"e":"繫𦃇也。从糸。虒聲。","n":"郞兮切。十六部。"}]},"緝":{"expl":"績也。从糸咠聲。","rad":"糸","fq":"七入切","vol":"13","py":"jī","duan":[{"e":"績也。","n":"自緝篆至絣篆皆說麻事。麻事與蠶事相似。故亦从糸。凡麻枲先分其莖與皮曰木。因而漚之。取所漚之麻而林之。林之爲言微也。微纖爲功、析其皮如絲。而撚之、而𠟪之、而續之、而後爲縷。是曰績。亦曰緝。亦絫言緝績。孟子曰。妻辟纑。趙注曰。緝績其麻曰辟。按辟與擘肌分理之擘同。謂始於析麻皮爲絲也。引申之、用縷以縫衣亦爲緝。如禮經云斬者不緝也𪗋者緝也是也。又引申之爲積厚流光之偁。大雅傳曰緝𤋮光明也是也。"}]},"𥿩":{"expl":"績所緝也。从糸次聲。","rad":"糸","fq":"七四切","vol":"13","py":"cì","duan":[{"e":"績所未緝者。","n":"各本作績所緝也。今依廣韵正。㒳縷相接而後爲緝。未撚接之前、豫林纖微諸縷以儲偫之、是爲絘。令其次弟可用也。引申之、周禮有絘布。鄭司農云。列肆之税布。"}]},"績":{"expl":"緝也。从糸責聲。","rad":"糸","fq":"則歴切","vol":"13","py":"jī","duan":[{"e":"緝也。","n":"豳風。八月載績。傳曰。載績、絲事畢而麻事起矣。績之言積也。積短爲長。積少爲多。故釋詁曰。績、繼也。事也。業也。功也。成也。左傳曰。遠績禹功。大雅曰。維禹之績。傳曰。績、功也。"}]},"纑":{"expl":"布縷也。从糸盧聲。","rad":"糸","fq":"洛乎切","vol":"13","py":"lú","duan":[{"e":"布縷也。","n":"言布縷者、以别乎絲縷也。績之而成縷、可以爲布。是曰纑。禮經縷分别若干𦫵以爲麤細。五服之縷不同也。趙岐曰。湅麻曰纑。麻部䵈下曰。未湅治纑也。然則湅治之乃曰纑。葢縷有不湅者。若斬衰、齊衰、大功、小功之縷皆不湅。緦衰之縷則湅之。若吉服之縷則無不湅者。不湅者曰䵈。湅者曰纑。統呼曰縷。"}]},"紨":{"expl":"布也。一曰粗紬。从糸付聲。","rad":"糸","fq":"防無切","vol":"13","py":"fū","duan":[{"e":"布也。","n":"謂布名。"}]},"𦄑":{"expl":"蜀細布也。从糸彗聲。","rad":"糸","fq":"祥歲切","vol":"13","py":"suì","duan":[{"e":"蜀細布也。","n":"左思蜀都賦。黄潤比筒。注。黃潤、謂筒中細布也。楊雄蜀都賦曰。筒中黃潤。一端數金。"}]},"絺":{"expl":"細葛也。从糸希聲。","rad":"糸","fq":"丑脂切","vol":"13","py":"chī","duan":[{"e":"細葛也。","n":"葛者、絺綌艸也。其緝績之一如麻枲。其所成之布、細者曰絺。粗者曰綌。葢艸有不同。如今之葛布有黃艸葛、其粗者也。"}]},"綌":{"expl":"粗葛也。从糸谷聲。","rad":"糸","fq":"綺𢧢切","vol":"13","py":"xì","duan":[{"e":"粗葛也。从糸。𧮫聲。","n":"綺戟切。古音在五部。"}]},"縐":{"expl":"絺之細也。《詩》曰：“蒙彼縐絺。”一曰蹴也。从糸芻聲。","rad":"糸","fq":"側救切","vol":"13","py":"zhòu","duan":[{"e":"絺之細者也。","n":"者字依御覽補。"}]},"𤩯":{"expl":"玉也。从玉毄聲。讀若鬲。","rad":"玉","fq":"郎擊切","vol":"01","py":"lì","duan":[{"e":"玉也。从王。毄聲。讀若鬲。","n":"郞擊切。十六部。"}]},"嗿":{"expl":"聲也。从口貪聲。《詩》曰：“有嗿其饁。”","rad":"口","fq":"他感切","vol":"02","py":"tǎn","duan":[{"e":"聲也。","n":"周頌傳曰。嗿、衆皃。按許以字从口。故釋與毛異。"}]},"絟":{"expl":"細布也。从糸全聲。","rad":"糸","fq":"此緣切","vol":"13","py":"quán","duan":[{"e":"細布也。","n":"江都王傳。遺帝荃葛。師古曰。字本作絟。千全反。又千劣反。江南筩布之屬皆爲荃也。"}]},"紵":{"expl":"檾屬。細者爲絟，粗者爲紵。从糸宁聲。","rad":"糸","fq":"直呂切","vol":"13","py":"zhù","duan":[{"e":"檾屬。","n":"檾者、枲屬也。陳風曰。東門之池。可以漚紵。"}]},"緦":{"expl":"十五升布也。一曰兩麻一絲布也。从糸思聲。","rad":"糸","fq":"息茲切","vol":"13","py":"sī","duan":[{"e":"十五升抽其半布也。","n":"各本無抽其半三字。當由不通人刪之。今補。緦者、布名。猶大功、小功皆布名也。經云緦麻三月者。注云。緦麻、緦布衰裳而麻絰帶也。今本注內刪下緦字、則不可通矣。傳曰。緦者十五升抽其半。有事其縷。無事其布曰緦。凡布幅廣二尺二寸。禮經布八十縷爲升。卽許之布八十縷爲稯也。斬衰三升、三升有半。齊衰四升。繐衰小功之縷四升有半。大功八升若九升。小功十升若十一升。緦布朝服之縷七升有半。升數各不同。而皆合二尺二寸之度以成布。十五升去半者、十五升朝服之升數也。去其半則爲七升有半。朝服用十五升、其布密。緦用其半、其布疏。謂之緦者、鄭曰治其縷細如絲也。傳所謂有事其縷也。繐衰用小功之縷。而升數不及半。緦用朝服之縷。而升數衹取"}]},"緆":{"expl":"細布也。从糸易聲。","rad":"糸","fq":"先擊切","vol":"13","py":"xī","duan":[{"e":"細布也。","n":"布一本作麻。古亦呼布爲麻也。燕禮。幂用綌若錫。鄭注。今文錫爲緆。緆、易也。治其布使滑易也。按今文其本字。古文其叚借字也。子虛賦被阿錫。卽列子之衣阿緆。許意從禮今文。故錄緆字。喪服錫衰傳曰。錫者何也。麻之有錫者也。錫者十五升抽其半。無事其縷。有事其布曰錫。按據是則緆之與緦、但一事其縷、一事其布爲少異耳。其爲十五升之半則同也。何緦下偁傳以釋之、而緆下不偁傳也。曰緦在五服之內、故聖人特製其字。錫衰不在五服内、故聖人用錫之名、不别製字。錫衰之錫與細布之緆、其實不同也。葢古者布十五升爲冣細。十五升布成、治之使滑易。是曰緆。錫衰則半十五升而治之。亦名曰緆。實非緆也。是以傳之釋經也。先之曰錫者何也。麻之有錫"}]},"緰":{"expl":"緰貲，布也。从糸俞聲。","rad":"糸","fq":"度矦切","vol":"13","py":"tóu","duan":[{"e":"緰貲、","n":"逗。"}]},"縗":{"expl":"服衣。長六寸，博四寸，直心。从糸衰聲。","rad":"糸","fq":"倉回切","vol":"13","py":"cuī","duan":[{"e":"喪服衣。","n":"喪字各本無。今補。凡服上曰衣、下曰裳。禮衰裳連言。卽衣裳也。以衰統負板辟領等爲言也。"}]},"絰":{"expl":"喪首戴也。从糸至聲。","rad":"糸","fq":"徒結切","vol":"13","py":"dié","duan":[{"e":"喪首戴也。","n":"喪服經苴絰。注曰。麻在首在要皆曰絰。絰之言實也。明孝子有忠實之心。故爲制此服焉。首絰象緇布冠之缺項。要絰象大帶。又有絞帶象革帶。按經傳首要皆言絰。而首章傳苴絰大搹去五分一以爲帶。齊衰之絰、斬衰之帶也云云。然則在首爲絰。在要爲帶。經特舉絰以統帶耳。故許以喪首戴釋絰。猶言當心之縗。則負板、辟領皆統其中也。"}]},"緶":{"expl":"交枲也。一曰緁衣也。从糸便聲。","rad":"糸","fq":"房連切","vol":"13","py":"biàn","duan":[{"e":"交枲也。","n":"謂以枲二股交辮之也。交絲爲辮。交枲爲？。"}]},"䋀":{"expl":"履也。一曰青絲頭履也。讀若阡陌之陌。从糸戶聲。","rad":"糸","fq":"亡百切","vol":"13","py":"huà","duan":[{"e":"𡳐也。","n":"𡳐者、足所依也。方言曰。絲作之者謂之𡳐。麻作之者謂之不借。或謂之屨。或謂之𩊅角。或謂之麤。或謂之㞜。或謂之䋀。𡳐其通語也。"}]},"䋽":{"expl":"枲履也。从糸封聲。","rad":"糸","fq":"博蠓切","vol":"13","py":"běnɡ","duan":[{"e":"枲𡳐也。","n":"枲者、麻也。急就篇屐屩𦂌藨。今俗語𡳐之判合爲幫。讀如邦。"}]},"咸":{"expl":"皆也。悉也。从口从戌。戌，悉也。","rad":"口","fq":"胡監切","vol":"02","py":"xián","duan":[{"e":"皆也。悉也。","n":"咸、皆也。見釋詁。"}]},"緉":{"expl":"履兩枚也。一曰絞也。从糸从兩，兩亦聲。","rad":"糸","fq":"力讓切","vol":"13","py":"liǎnɡ","duan":[{"e":"𡳐㒳枚也。","n":"齊風。葛屨五㒳。𡳐必㒳而後成用也。是之謂？。"}]},"絜":{"expl":"麻一耑也。从糸㓞聲。","rad":"糸","fq":"古屑切","vol":"13","py":"jié","duan":[{"e":"麻一耑也。","n":"一耑猶一束也。耑、頭也。束之必齊其首。故曰耑。人部係下云。絜束也。是知絜爲束也。束之必圍之。故引申之圍度曰絜。束之則不𢽳曼。故又引申爲㓗淨。俗作潔。經典作絜。"}]},"繆":{"expl":"枲之十絜也。一曰綢繆。从糸翏聲。","rad":"糸","fq":"武彪切","vol":"13","py":"móu","duan":[{"e":"枲之十絜也。","n":"枲卽麻也。十絜猶十束也。亦叚爲謬誤字。亦叚爲謚法之穆。"}]},"綢":{"expl":"繆也。从糸周聲。","rad":"糸","fq":"直由切","vol":"13","py":"chóu","duan":[{"e":"繆也。","n":"謂枲之十絜、一曰綢繆二義皆與繆同也。今人綢繆字不分用。然詩都人士單用綢字。曰綢直如髮。毛傳以密直釋之。則綢卽稠之叚借也。"}]},"縕":{"expl":"紼也。从糸𥁕聲。","rad":"糸","fq":"於云切","vol":"13","py":"yùn","duan":[{"e":"紼也。","n":"玉藻。纊爲繭。縕爲袍。注曰。纊、新緜也。縕、今之纊及故絮也。纊及故絮者、謂以新緜合故絮裝衣。鄭說與許異。衣部曰。以絮曰襺。以縕曰袍。許絲絮不分新舊。槩謂之纊。以亂麻謂之縕。孔安國釋論語曰。縕、枲著也。許所本也。蒯通傳。束縕乞火。師古曰。縕、亂麻。"}]},"紼":{"expl":"亂系也。从糸弗聲。","rad":"糸","fq":"分勿切","vol":"13","py":"fú","duan":[{"e":"亂枲也。","n":"枲各本作系。不可通。今正。亂枲者、亂麻也。可以裝衣。可以然火。可以緝之爲索。故采尗毛傳曰。紼、繂也。言用紼爲索也。"}]},"絣":{"expl":"氐人殊縷布也。从糸幷聲。","rad":"糸","fq":"北萌切","vol":"13","py":"bēnɡ","duan":[{"e":"氐人殊縷布也。","n":"漢武都郡、應劭曰。故白馬氐羌。華陽國志曰。武都郡有氐傁。殊縷布者、葢殊其縷色而相閒織之。絣之言騈也。"}]},"紕":{"expl":"氐人𦇧也。讀若《禹貢》玭珠。从糸比聲。","rad":"糸","fq":"卑履切","vol":"13","py":"bǐ","duan":[{"e":"氐人𦇧也。","n":"氐人所織毛布也。周書伊尹爲四方獻令。正西以紕罽爲獻。後漢西南夷傳。冄駹夷能作毞毲。毞卽紕也。華陽國志同。禮記用紕爲紕繆字。"}]},"𦇧":{"expl":"西胡毳布也。从糸罽聲。","rad":"糸","fq":"居例切","vol":"13","py":"jì","duan":[{"e":"西胡毳布也。","n":"西胡見玉部？注。毳者、獸細毛也。用織爲布、是曰𦇧。亦叚罽爲之。"}]},"縊":{"expl":"經也。从糸益聲。《春秋傳》曰：“夷姜縊。”","rad":"糸","fq":"於賜切","vol":"13","py":"yì","duan":[{"e":"絞也。","n":"絞各本作經。庸人所改也。今正。交部曰。絞、縊也。與此爲轉注。絞縊必㒳股辮爲之。喪服傳曰。喪之絰不摎垂葢不成也。不摎垂、謂不絞也。經本訓從絲爲一股。縊死必㒳股爲之。以其直縣也。故亦謂之經。許解縊必不云經也。左傳曰。若其有罪。絞縊以戮。手部曰。摎、縛殺也。"}]},"呈":{"expl":"平也。从口壬聲。","rad":"口","fq":"直貞切","vol":"02","py":"chénɡ","duan":[{"e":"平也。","n":"今義云示也。見也。"}]},"綏":{"expl":"車中把也。从糸从妥。","rad":"糸","fq":"息遺切","vol":"13","py":"suī","duan":[{"e":"車中靶也。","n":"靶各本作把。玉篇作車中靶也。廣韵引說文同。按靶是、把非。靶者、轡也。轡在車前。而綏則系於車中。御者執以授登車者。故别之曰車中靶也。少儀曰。車則脱綏。執以將命。綏本系於車中、故可脱。郭璞注子虛賦曰。綏、所執以登車。論語曰。𦫵車必正立執綏。周生烈曰。正立執綏、所以爲安。按引申爲凡安之偁。"}]},"彝":{"expl":"宗廟常器也。从糸；糸，綦也。廾持米，器中寶也。彑聲。此與爵相似。《周禮》：“六彝：雞彝、鳥彝、黃彝、虎彝、蟲彝、斝彝。以待祼將之禮。”","rad":"糸","fq":"以脂切","vol":"13","py":"yí","duan":[{"e":"宗廟常器也。","n":"彝本常器。故引申爲彝常。大雅。民之秉彝。傳曰。彝、常也。"}]},"緻":{"expl":"密也。从糸致聲。","rad":"糸","fq":"直利切","vol":"13","py":"zhì","duan":[]},"緗":{"expl":"帛淺黃色也。从糸相聲。","rad":"糸","fq":"息良切","vol":"13","py":"xiānɡ","duan":[]},"緋":{"expl":"帛赤色也。从糸非聲。","rad":"糸","fq":"甫微切","vol":"13","py":"fēi","duan":[]},"緅":{"expl":"帛青赤色也。从糸取聲。","rad":"糸","fq":"子矦切","vol":"13","py":"zōu","duan":[]},"繖":{"expl":"蓋也。从糸𢿱聲。","rad":"糸","fq":"穌旱切","vol":"13","py":"sǎn","duan":[]},"綀":{"expl":"布屬。从糸束聲。","rad":"糸","fq":"所菹切","vol":"13","py":"shū","duan":[]},"縡":{"expl":"事也。从糸宰聲。","rad":"糸","fq":"子代切","vol":"13","py":"zǎi","duan":[]},"繾":{"expl":"繾綣，不相離也。从糸遣聲。","rad":"糸","fq":"去演切","vol":"13","py":"qiǎn","duan":[]},"綣":{"expl":"繾綣也。从糸卷聲。","rad":"糸","fq":"去阮切","vol":"13","py":"quǎn","duan":[]},"素":{"expl":"白緻繒也。从糸、𠂹，取其澤也。凡素之屬皆从素。","rad":"素","fq":"桑故切","vol":"13","py":"sù","duan":[{"e":"白致繒也。","n":"繒之白而細者也。致者、今之緻字。漢人作注不作緻。近人改爲緻。又於糸部增緻篆。皆非也。鄭注襍記曰。素、生帛也。然則生帛曰素。對湅繒曰練而言。以其色白也。故爲凡白之偁。以白受采也。故凡物之質曰素。如㱿下一曰素也是也。以質未有文也。故曰素食、曰素王。伐檀毛傳曰。素、空也。"}]},"𦅽":{"expl":"素屬。从素𠬞聲。","rad":"素","fq":"居玉切","vol":"13","py":"jú","duan":[{"e":"𦃃屬。从𦃃。𠬞聲。","n":"居玉切。三部。"}]},"䋤":{"expl":"白約，縞也。从素勺聲。","rad":"素","fq":"以灼切","vol":"13","py":"yuè","duan":[{"e":"白䋤、","n":"逗。"}]},"𦆾":{"expl":"素屬。从素率聲。","rad":"素","fq":"所律切","vol":"13","py":"lǜ","duan":[{"e":"𦃃屬。","n":"素當作索。索見𣎵部。繩索也。从素之字、古亦从糸。故？字或作𦆽。或作繂。采尗毛傳曰。紼、繂也。謂麻繩也。今說文譌作素屬。乃不可通矣。"}]},"繛":{"expl":"𦅻也。从素卓聲。","rad":"素","fq":"昌約切","vol":"13","py":"chuò","duan":[{"e":"𦅻也。","n":"淇澳毛傳曰。綽、緩也。"}]},"𦅻":{"expl":"繛也。从素，爰省。","rad":"素","fq":"胡玩切","vol":"13","py":"huǎn","duan":[{"e":"繛也。","n":"糸部曰。紓、緩也。然則緩、紓也。"}]},"絲":{"expl":"蠶所吐也。从二糸。凡絲之屬皆从絲。","rad":"絲","fq":"息茲切","vol":"13","py":"sī","duan":[{"e":"蠶所吐也。","n":"吐者、寫也。"}]},"轡":{"expl":"馬轡也。从絲从軎。與連同意。《詩》曰：“六轡如絲。”","rad":"絲","fq":"兵媚切","vol":"13","py":"pèi","duan":[]},"𢇅":{"expl":"織絹从糸貫杼也。从絲省，卝聲。","rad":"絲","fq":"古還切","vol":"13","py":"ɡuān","duan":[{"e":"織㠯絲毌杼也。","n":"織字下各本衍絹字。玉篇又誤緝。今刪。以絲各本誤作从糸。毌作貫。今正。杼者、機之持緯者。毌、穿物持之也。以絲貫於杼中而後織。是之謂𢇂。杼之往來、如關機合開也。"}]},"啻":{"expl":"語時不啻也。从口帝聲。一曰啻，諟也。讀若鞮。","rad":"口","fq":"施智切","vol":"02","py":"chì","duan":[{"e":"語時不啻也。","n":"玄應引倉頡篇曰。不啻、多也。按不啻者、多之䛐也。秦誓曰。不啻若自其口出。世說新語云。王文度弟阿智。惡乃不啻。玉篇云。買賣云不啻也。可知爲市井常談矣。不啻如楚人言夥頤。啻亦作翅。支聲帝聲同部也。疒部疧下曰。病不翅。孟子曰。奚翅食重。"}]},"率":{"expl":"捕鳥畢也。象絲罔，上下其竿柄也。凡率之屬皆从率。","rad":"率","fq":"所律切","vol":"13","py":"shuài","duan":[{"e":"捕鳥畢也。","n":"畢者、田网也。所以捕鳥。亦名率。按此篆本義不行。凡？訓將？也、䢦訓先導也皆不用本字而用率。又或用帥。如緜傳云率循也、北山傳云率循也、其字皆當作䢦是也。又詳帥下。左傳藻率。服虔曰。禮有率巾。卽許書之帥也。"}]},"虫":{"expl":"一名蝮，博三寸，首大如擘指。象其臥形。物之微細，或行，或毛，或蠃，或介，或鱗，以虫爲象。凡虫之屬皆从虫。","rad":"虫","fq":"許偉切","vol":"13","py":"huǐ","duan":[{"e":"一名𧐛。","n":"爾雅釋魚。蝮、虫。今本虫作虺。"}]},"蝮":{"expl":"虫也。从虫复聲。","rad":"虫","fq":"芳目切","vol":"13","py":"fù","duan":[{"e":"虫也。","n":"是曰轉注。考老之例也。招䰟曰。蝮蛇蓁蓁。"}]},"螣":{"expl":"神蛇也。从虫朕聲。","rad":"虫","fq":"徒登切","vol":"13","py":"ténɡ","duan":[{"e":"神它也。","n":"荀卿曰。螣蛇無足而飛。毛詩叚借爲？字。"}]},"蚦":{"expl":"大蛇。可食。从虫冄聲。","rad":"虫","fq":"人占切","vol":"13","py":"rán","duan":[{"e":"大它可食。从虫。冄聲。","n":"人占切。七部。"}]},"螼":{"expl":"螾也。从虫堇聲。","rad":"虫","fq":"弃忍切","vol":"13","py":"qǐn","duan":[{"e":"螾也。","n":"釋蟲曰。螼、蚓、蜸蚕。許謂螼也。蚓也。蜸蚕也。一物三名也。蚓許作螾。"}]},"螾":{"expl":"側行者。从虫寅聲。","rad":"虫","fq":"余忍切","vol":"13","py":"yǐn","duan":[{"e":"側行者。","n":"考工記。卻行、仄行。鄭曰。卻行、螾衍屬。仄行、蟹屬。與許異。今觀丘蚓實卻行。非側行。鄭說長也。丘蚓俗曰曲蟮。漢巴郡有朐忍縣。以此蟲得名。丘朐曲一語之轉也。或譌胊忍爲胊䏰。讀如蠢潤二音。遠失之矣。"}]},"螉":{"expl":"蟲，在牛馬皮者。从虫翁聲。","rad":"虫","fq":"烏紅切","vol":"13","py":"wēnɡ","duan":[{"e":"螉䗥。","n":"各本無此二字。今補。"}]},"䗥":{"expl":"螉䗥也。从虫從聲。","rad":"虫","fq":"子紅切","vol":"13","py":"zōnɡ","duan":[{"e":"螉䗥也。从虫。從聲。","n":"子紅切。九部。"}]},"蠁":{"expl":"知聲蟲也。从虫鄉聲。","rad":"虫","fq":"許兩切","vol":"13","py":"xiǎnɡ","duan":[{"e":"知聲蟲也。","n":"十部曰。肸蠁、布也。釋蟲曰。國貉、蟲蠁。廣雅曰。土蛹、蠁蟲。"}]},"吉":{"expl":"善也。从士、口。","rad":"口","fq":"居質切","vol":"02","py":"jí","duan":[{"e":"善也。从士口。","n":"居質切。十二部。"}]},"蛁":{"expl":"蟲也。从虫召聲。","rad":"虫","fq":"都僚切","vol":"13","py":"diāo","duan":[{"e":"蟲也。","n":"謂蟲名也。按玉篇以蛁蟧釋之。非也。蛁自蟲名。下文蚗下蛁蟟、别一蟲名。凡單字爲名者、不得與雙字爲名者相牽混。蛁蟧卽蛁蟟、不得以釋蛁也。"}]},"𧑎":{"expl":"蟲也。从虫𠭥聲。","rad":"虫","fq":"祖外切","vol":"13","py":"cuì","duan":[{"e":"蟲也。","n":"謂蟲名。"}]},"蛹":{"expl":"繭蟲也。从虫甬聲。","rad":"虫","fq":"余隴切","vol":"13","py":"yǒnɡ","duan":[{"e":"繭蟲也。","n":"按許於繭曰蠶衣也。於絲曰蠶所吐也。於蠶曰任絲蟲也。於？曰蠶化飛？也。蛹之爲物、在成繭之後、化？之前。非與蠶有二物也。立文不當曰繭蟲。當曰繭中蠶也。乃使先後如貫珠然。疑轉寫必有譌亂。"}]},"螝":{"expl":"蛹也。从虫鬼聲。讀若潰。","rad":"虫","fq":"胡罪切","vol":"13","py":"ɡuī","duan":[{"e":"蛹也。","n":"見釋蟲。顔氏家訓曰。莊子螝二首。螝卽古虺字。見古今字詁。按字詁原文必曰古螝今虺。以許書律之。古字叚借也。"}]},"蛕":{"expl":"腹中長蟲也。从虫有聲。","rad":"虫","fq":"戶恢切","vol":"13","py":"huí","duan":[{"e":"腹中長蟲也。从虫。有聲。","n":"户恢切。古音在一部。"}]},"蟯":{"expl":"腹中短蟲也。从虫堯聲。","rad":"虫","fq":"如招切","vol":"13","py":"náo","duan":[{"e":"腹中短蟲也。","n":"倉公列傳。診其病曰蟯瘕。"}]},"雖":{"expl":"似蜥蜴而大。从虫唯聲。","rad":"虫","fq":"息遺切","vol":"13","py":"suī","duan":[{"e":"佀蜥易而大。","n":"易各本作蜴。誤。今正。此字之本義也。自借以爲語䛐。尟有知其本義者矣。常棣云。每有良朋。又云。雖有兄弟。傳云。每、雖也。凡人竆極其欲曰恣雎。雖卽雎也。按方言守宮在澤中者、東齊海岱謂之螔䗔。注云。似蜥易大而有鱗。䗔字疑雖之誤。"}]},"虺":{"expl":"虺以注鳴。《詩》曰：“胡爲纵蜥。”从虫兀聲。","rad":"虫","fq":"許偉切","vol":"13","py":"huǐ","duan":[{"e":"㠯注鳴者。","n":"者字今補。注者、咮字之叚借。許用考工記文也。梓人職云。以注鳴者。鄭云。精列屬。與許不同也。上文雖下云似蜥易。下文蜥下云蜥易。則虺爲蜥易屬可知矣。今爾雅以爲虫蝮字。"}]},"蜥":{"expl":"蜥易也。从虫析聲。","rad":"虫","fq":"先擊切","vol":"13","py":"xī","duan":[{"e":"蜥易也。","n":"易下曰。蜥易、蝘蜓。蝘蜓、守宮也。渾言之。此分别蜥易、蝘蜓、榮螈爲三。析言之也。方言曰。守宮、秦晉西夏或謂之蠦？。或謂之蜥易。"}]},"蝘":{"expl":"在壁曰蝘蜓，在艸曰蜥易。从虫匽聲。","rad":"虫","fq":"於殄切","vol":"13","py":"yǎn","duan":[{"e":"在壁曰蝘蜓。在艸曰蜥易。","n":"析言之。"}]},"周":{"expl":"密也。从用、口。","rad":"口","fq":"職畱切","vol":"02","py":"zhōu","duan":[{"e":"密也。","n":"密、山部曰山如堂者。引伸訓爲周緻也。左傳。晏子曰。淸濁小大。短長疾徐。哀樂剛柔。遟速高下。出入周疏。以相濟也。以周與疏反對。又襄二十七年。春。胥梁帶使諸喪邑者。具車徒以受地。必周。杜皆云。周、密也。按忠信爲周。謂忠信之人無不周密者。"}]},"蜓":{"expl":"蝘蜓也。从虫廷聲。一曰螾蜓。","rad":"虫","fq":"徒典切","vol":"13","py":"diàn","duan":[{"e":"蝘蜓也。从虫。廷聲。","n":"徒典切。古音在十一部。"}]},"蚖":{"expl":"榮蚖，蛇醫，以注鳴者。从虫元聲。","rad":"虫","fq":"愚袁切","vol":"13","py":"yuán","duan":[{"e":"榮蚖、","n":"逗。"}]},"蠸":{"expl":"蟲也。一曰大螫也。讀若蜀都布名。从虫雚聲。","rad":"虫","fq":"巨員切","vol":"13","py":"quán","duan":[{"e":"蟲也。","n":"謂蟲名。未詳何物。釋蟲有蠸、輿父、守瓜。"}]},"螟":{"expl":"蟲食穀葉者。吏冥冥犯法卽生螟。从虫从冥，冥亦聲。","rad":"虫","fq":"莫經切","vol":"13","py":"mínɡ","duan":[{"e":"蟲食穀心者。吏冥冥犯法卽生螟。","n":"心各本譌葉。今依開元占經正。釋蟲、毛傳皆曰。食心曰螟。食葉曰？。食根曰蟊。食節曰賊。云吏冥冥犯法卽生螟、正爲食心言之。惟食心、故从虫冥會意。"}]},"蟘":{"expl":"蟲，食苗葉者。吏乞貸則生蟘。从虫从貸，貸亦聲。《詩》曰：“去其螟蟘。”","rad":"虫","fq":"徒得切","vol":"13","py":"tè","duan":[{"e":"蟲食苗葉者。","n":"見爾雅、毛傳。"}]},"蟣":{"expl":"蝨子也。一曰齊謂蛭曰蟣。从虫幾聲。","rad":"虫","fq":"居狶切","vol":"13","py":"jǐ","duan":[{"e":"蝨子也。","n":"蝨、齧人蟲也。子其卵也。戰國策作幾瑟。叚借字。"}]},"蛭":{"expl":"蟣也。从虫至聲。","rad":"虫","fq":"之日切","vol":"13","py":"zhì","duan":[{"e":"蟣也。","n":"此蒙上蟣字第二義釋之。似後人所移。原書當不在是。水蛭者、今之馬黃。旣是水物。當與下蛟螭虯蜦爲類。蛭蟣、釋魚文。"}]},"蝚":{"expl":"蛭蝚，至掌也。从虫柔聲。","rad":"虫","fq":"耳由切","vol":"13","py":"róu","duan":[{"e":"蛭蝚、","n":"逗。"}]},"蛣":{"expl":"蛣䖦，蝎也。从虫吉聲。","rad":"虫","fq":"去吉切","vol":"13","py":"jié","duan":[{"e":"蛣䖦、","n":"逗。"}]},"䖦":{"expl":"蛣䖦也。从虫出聲。","rad":"虫","fq":"區勿切","vol":"13","py":"qū","duan":[{"e":"蛣䖦也。从虫。出聲。","n":"區勿切。十五部。今爾雅作𧌑。"}]},"唐":{"expl":"大言也。从口庚聲。","rad":"口","fq":"徒郎切","vol":"02","py":"tánɡ","duan":[{"e":"大言也。","n":"引伸爲大也。如說尙書者云。唐之爲言蕩蕩也。見論衡。又爲空也。如梵書云。福不唐捐。凡陂塘字古皆作唐。取虚而多受之意。𨸏部曰。隄、唐也。"}]},"蟫":{"expl":"白魚也。从虫覃聲。","rad":"虫","fq":"余箴切","vol":"13","py":"yín","duan":[{"e":"白魚也。","n":"今衣、書中白蟲有粉如銀者是也。一名蛃魚。本艸經謂之衣魚。"}]},"蛵":{"expl":"丁蛵，負勞也。从虫巠聲。","rad":"虫","fq":"戶經切","vol":"13","py":"xīnɡ","duan":[{"e":"丁蛵、","n":"逗。曡韵。"}]},"蜭":{"expl":"毛蠹也。从虫臽聲。","rad":"虫","fq":"乎感切","vol":"13","py":"hàn","duan":[{"e":"毛蠹也。","n":"釋蟲文。蠹者、木中蟲也。蜭居木中。其形外有毛。能食木。故曰毛蠹。是爲蜭。蜭之言陷也。"}]},"蟜":{"expl":"蟲也。从虫喬聲。","rad":"虫","fq":"居夭切","vol":"13","py":"jiǎo","duan":[{"e":"蟲也。","n":"謂蟲名。按上蜭下蛓同類也。則蟜當亦蜭蛓之類耳。"}]},"蛓":{"expl":"毛蟲也。从虫𢦔聲。","rad":"虫","fq":"千志切","vol":"13","py":"cì","duan":[{"e":"毛蟲也。","n":"不曰毛蠹者、不居木中。但食葉也。釋蟲云。蟔、蛅蟴。郭云。蛓屬也。今靑州人呼蛓爲蛅蟴。孫叔然云。八角螫蟲。失之。按今俗云刺毛者是也。食木葉。體有棱角、有毛、有采色。毛能螫人。叔然說不誤也。其老而成蛹。則外有𣪊如雀卵然。本艸經謂之雀甕。或出成蛾放子如蠶子。或卽卵育於𣪊中。故本艸云。雀甕、蛅蟖房也。蛅蟴音髯斯。"}]},"䖯":{"expl":"蠆也。从虫圭聲。","rad":"虫","fq":"烏蝸切","vol":"13","py":"kuí","duan":[{"e":"𧍣也。","n":"史記律書。北至於䖯。䖯者、主毒螫殺萬物也。䖯而藏之。九月也。"}]},"蚔":{"expl":"䖯也。从虫氏聲。","rad":"虫","fq":"巨支切","vol":"13","py":"qí","duan":[{"e":"䖯也。","n":"此篆與螘子之蚳迥别。孟子書當是蚔鼃。鼃卽䖯。大夫以蚔䖯爲名也。"}]},"𧍣":{"expl":"毒蟲也。象形。","rad":"虫","fq":"丑芥切","vol":"13","py":"chài","duan":[{"e":"毒蟲也。","n":"左傳曰。蠭蠆有毒。詩曰。卷髮如蠆。通俗文曰。蠆長尾謂之蠍。蠍毒傷人曰䖧。䖧張列反。或作蜇。旦聲。非且聲也。"}]},"蝤":{"expl":"蝤𧓉也。从虫酋聲。","rad":"虫","fq":"字秋切","vol":"13","py":"qiú","duan":[{"e":"蝤𧓉也。","n":"詩衞風。領如蝤蠐。傳曰。蝤蠐、蝎蟲也。爾雅同。按下文云。蝎、蝤𧓉也。然則二者爲轉注。"}]},"𧓉":{"expl":"𧓉𧕐也。从虫齊聲。","rad":"虫","fq":"徂兮切","vol":"13","py":"qí","duan":[{"e":"𧓉𧕐也。","n":"釋蟲。蝤蠐、蝎。郭云。在木中者。蟦、蠐螬。郭云。在糞土中者也。是二者似同而異。宋掌禹錫、蘇頌亦辯蠐螬與蝤蠐、蝎不同。許意謂蝤蠐、蝎爲一物。而蠐螬下不云蝎也。葢亦不謂一物矣。"}]},"𠼡":{"expl":"誰也。从口、𢏚，又聲。𢏚，古文疇。","rad":"口","fq":"直由切","vol":"02","py":"chóu","duan":[{"e":"誰也。从口𢏚。又聲𢏚、古文疇。","n":"按此篆疑有誤。白部曰。𤾊、䛐也。从白、𢏚聲。引唐書帝曰𤾊咨。與此音義大同。但其字从口𢏚聲足矣。不當兼从又聲。又在一部。非聲也。老部𦓃、酉部𨢫、巾部𢄛皆从𠷎聲。竹部？、火部？、言部？、邑部？皆从𦓃聲。絶無从𠼡聲之字。可知此正當作𤾊。爲𦓃之聲。直由切。三部。"}]},"蝎":{"expl":"蝤蠐也。从虫曷聲。","rad":"虫","fq":"胡葛切","vol":"13","py":"hé","duan":[{"e":"蝤𧓉也。","n":"釋蟲曰。蝎、桑蠹。桑中蟲也。按上文許云蛣䖦、蝎也。不類廁於此者、許意蛣䖦别爲一物也。葢一類而種别者多矣。"}]},"強":{"expl":"蚚也。从虫弘聲。","rad":"虫","fq":"巨良切","vol":"13","py":"qiánɡ","duan":[{"e":"蚚也。","n":"下云蚚、強也。二字爲轉注。釋蟲曰。強、醜捋。郭曰。以腳自摩捋。叚借爲彊弱之彊。"}]},"蚚":{"expl":"强也。从虫斤聲。","rad":"虫","fq":"巨衣切","vol":"13","py":"qí","duan":[{"e":"強也。从虫。斤聲。","n":"巨衣切。古音在十三部。"}]},"蜀":{"expl":"葵中蠶也。从虫，上目象蜀頭形，中象其身蜎蜎。《詩》曰：“蜎蜎者蜀。”","rad":"虫","fq":"市玉切","vol":"13","py":"shǔ","duan":[{"e":"葵中蠶也。","n":"葵爾雅釋文引作桑。詩曰。蜎蜎者蠋。蒸在桑野。似作桑爲長。毛傳曰。蜎蜎、蠋皃。蠋、桑蟲也。傳言蟲、許言蠶者、蜀似蠶也。淮南子曰。蠶與蜀相類、而愛僧異也。桑中蠹卽蝤蠐。"}]},"蠲":{"expl":"馬蠲也。从虫、目，益聲。纽，象形。《明堂月令》曰：“腐艸爲蠲。”","rad":"虫","fq":"古玄切","vol":"13","py":"juān","duan":[{"e":"馬蠲也。","n":"馬蠲亦名馬蚿。亦名馬蚈。亦名馬蠸。見呂覽仲夏紀、淮南時則訓高注。而爾雅釋蟲蛝、馬䗃。郭注。馬蠲、蚐。俗呼馬𧏿。方言曰。馬蚿大者謂之馬蚰。蚰𧏿同字也。莊子謂之蚿。多足蟲也。今巫山夔州人謂之艸鞵絆。亦曰百足蟲。茅茨陳朽則多生之。故淮南、呂覽皆曰腐艸化爲蚈。高注曰。蚈讀如蹊徑之蹊是也。其注淮南云。一曰熒火。乃備異說。鄭注戴記腐艸爲熒曰。熒、飛蟲、熒火也。葢非古文古說。"}]},"螕":{"expl":"齧牛蟲也。从虫𣬉聲。","rad":"虫","fq":"邊兮切","vol":"13","py":"bī","duan":[{"e":"齧牛蟲也。","n":"今人謂齧狗蟲。語亦同。通俗文曰。狗蝨曰螕。"}]},"蠖":{"expl":"尺蠖，屈申蟲。从虫蒦聲。","rad":"虫","fq":"烏郭切","vol":"13","py":"huò","duan":[{"e":"尺蠖、","n":"逗。曡韵字。"}]},"蝝":{"expl":"復陶也。劉歆說：蝝，蚍蜉子。董仲舒說：蝗子也。从虫彖聲。","rad":"虫","fq":"與專切","vol":"13","py":"yuán","duan":[{"e":"復陶也。","n":"釋蟲曰。蝝、蝮蜪。俗字从虫也。國語曰。蟲舍蚳蝝。韋注。蝝、蝮蜪也。可以食。按此說葢與下文二說畫然爲三。郭注爾雅則牽合董說耳。復陶未知於今何物。"}]},"螻":{"expl":"螻蛄也。从虫婁聲。一曰𧐡、天螻。","rad":"虫","fq":"洛矦切","vol":"13","py":"lóu","duan":[{"e":"螻蛄也。","n":"今之土狗也。"}]},"蛄":{"expl":"螻蛄也。从虫古聲。","rad":"虫","fq":"古乎切","vol":"13","py":"ɡū","duan":[{"e":"螻蛄也。","n":"孟子。蠅蚋姑嘬之。蚋一作？。或云？姑卽螻蛄也。"}]},"嘾":{"expl":"含深也。从口覃聲。","rad":"口","fq":"徒感切","vol":"02","py":"dàn","duan":[{"e":"含㴱也。","n":"莊子曰。大甘而嘾。"}]},"蠪":{"expl":"丁螘也。从虫龍聲。","rad":"虫","fq":"盧紅切","vol":"13","py":"lónɡ","duan":[{"e":"蠪丁、螘也。","n":"按此當於蠪丁爲逗。各本刪蠪字者、非也。讀爾雅者以丁螘爲句。亦非。蠪丁、螘之一名耳。爾雅丁作朾。"}]},"蛾":{"expl":"羅也。从虫我聲。","rad":"虫","fq":"五何切","vol":"13","py":"yǐ","duan":[{"e":"羅也。","n":"蛾羅見釋蟲。許次於此。當是螘一名蛾。古書說蛾爲？𧕰者多矣。蛾是正字。蟻是或體。許意此蛾是螘。䖵部之？是蠶？。二字有别。郭注爾雅蛾羅爲蠶？。非許意也。爾雅螘字本或作蛾。葢古因二字雙聲通用。要之本是一物。非叚借也。"}]},"螘":{"expl":"蚍蜉也。从虫豈聲。","rad":"虫","fq":"魚綺切","vol":"13","py":"yǐ","duan":[{"e":"𧖕𧕰也。","n":"俗作蚍蜉。非是。今正。蟲部曰。蠶𧕰、大螘也。析言之也。渾言之則凡螘皆曰𧖕𧕰。爾雅。蚍蜉、大螘。小者螘。亦是析言。"}]},"蚳":{"expl":"螘子也。从虫氐聲。《周禮》有蚳醢。讀若祁。","rad":"虫","fq":"直尼切","vol":"13","py":"chí","duan":[{"e":"螘子也。","n":"釋蟲曰。螘子、蚳。郭云。蟻卵也。周禮饋食之豆有蚳醢。鄭曰。蚳、蛾子。國語。蟲舍蚳蝝。韋注同。"}]},"蠜":{"expl":"𨸏蠜也。从虫樊聲。","rad":"虫","fq":"附袁切","vol":"13","py":"fán","duan":[{"e":"𨸏蠜也。","n":"召南。趯趯阜螽。傳曰。阜螽、蠜也。趯趯、躍也。"}]},"𧍓":{"expl":"悉𧍓也。从虫帥聲。","rad":"虫","fq":"所律切","vol":"13","py":"shuài","duan":[{"e":"悉𧍓也。","n":"唐風。蟋蟀在堂。傳曰。蟋蟀、蛬也。按許書無蛬字。今人叚蛩爲之。"}]},"蝒":{"expl":"馬蜩也。从虫面聲。","rad":"虫","fq":"武延切","vol":"13","py":"mián","duan":[{"e":"馬蜩也。","n":"與釋蟲同。凡言馬者謂大。馬蜩者、蜩之大者也。方言曰。蟬、其大者謂之蟧。或謂之蝒馬。蝒馬二字誤倒。此篆不與下文蜩蟬螇蚗諸篆爲伍。不得其故。恐是淺人亂之耳。"}]},"𧒾":{"expl":"𧒾蠰，不過也。从虫當聲。","rad":"虫","fq":"都郎切","vol":"13","py":"dānɡ","duan":[{"e":"𧒾蠰、","n":"逗。"}]},"蠰":{"expl":"𧒾蠰也。从虫襄聲。","rad":"虫","fq":"汝羊切","vol":"13","py":"nánɡ","duan":[{"e":"𧒾蠰也。从虫。襄聲。","n":"汝羊切。十部。"}]},"蜋":{"expl":"堂蜋也。从虫良聲。一名蚚父。","rad":"虫","fq":"魯當切","vol":"13","py":"lánɡ","duan":[{"e":"堂蜋也。","n":"堂蜋與𧒾蠰一語小異耳。"}]},"璠":{"expl":"璵璠。魯之寶玉。从玉番聲。孔子曰：“美哉璵璠。遠而望之，奐若也；近而視之，瑟若也。一則理勝，二則孚勝。”","rad":"玉","fq":"附袁切","vol":"01","py":"fán","duan":[{"e":"璠與、","n":"逗。與各本作璵。鉉本有篆文璵字。云說文闕載。依注所有增爲十九文之一。鍇本則張次立補之。考左傳釋文曰。璵本又作與。音餘。此可證古本左傳、說文皆不从玉。後人輒加篆文之璵。可勿補也。又各本作璵璠。今依太平御覽所引作璠璵。法言亦作璠璵。"}]},"噎":{"expl":"飯窒也。从口壹聲。","rad":"口","fq":"烏結切","vol":"02","py":"yē","duan":[{"e":"飯窒也。","n":"王風。中心如噎毛曰。謂噎憂不能息也。噎憂雙聲。憂卽終日號而不嚘之嚘。氣逆也。今本毛傳譌脫。惟玉篇不誤。鄭風傳。憂不能息。憂亦讀爲嚘。欠部曰。欭、嚘也。欭嚘卽噎憂。劉氏台拱說。"}]},"蛸":{"expl":"𧓎蛸，堂蜋子。从虫肖聲。","rad":"虫","fq":"相邀切","vol":"13","py":"xiāo","duan":[{"e":"𧓎蛸、","n":"逗。"}]},"蛢":{"expl":"𧑐蟥，以翼鳴者。从虫并聲。","rad":"虫","fq":"薄經切","vol":"13","py":"pínɡ","duan":[{"e":"𧑐蟥、","n":"逗。"}]},"𧑐":{"expl":"𧑐蟥也。从虫矞聲。","rad":"虫","fq":"余律切","vol":"13","py":"yù","duan":[{"e":"𧑐蟥、蛢也。","n":"蛢字今補。此轉注之例也。"}]},"蟥":{"expl":"𧑐蟥也。从虫黃聲。","rad":"虫","fq":"乎光切","vol":"13","py":"huánɡ","duan":[{"e":"𧑐蟥也。从虫。黃聲。","n":"乎光切。十部。"}]},"䗐":{"expl":"蛄䗐，强芈也。从虫施聲。","rad":"虫","fq":"式支切","vol":"13","py":"shī","duan":[{"e":"姑䗐、","n":"逗。"}]},"蛅":{"expl":"蛅斯，墨也。从虫占聲。","rad":"虫","fq":"職廉切","vol":"13","py":"zhān","duan":[{"e":"蛅斯、","n":"逗。"}]},"蜆":{"expl":"縊女也。从虫見聲。","rad":"虫","fq":"胡典切","vol":"13","py":"xiàn","duan":[{"e":"縊女也。","n":"與釋蟲同。郭云。小黑蟲。赤頭。憙自經死。故曰縊女。"}]},"蜰":{"expl":"盧蜰也。从虫肥聲。","rad":"虫","fq":"符非切","vol":"13","py":"féi","duan":[{"e":"盧蜰也。","n":"按爾雅蜚、蠦蜰爲一物。許書蜚在蟲部。蜰在虫部。不言一物。許實有所見也。唐本艸說蜚蠊味辛辣而臭。漢中人食之。一名蠦蜰。"}]},"𧍕":{"expl":"渠䖼。一曰天社。从虫却聲。","rad":"虫","fq":"其虐切","vol":"13","py":"jué","duan":[{"e":"渠𧍕、","n":"逗。"}]},"𧒘":{"expl":"𧒘蠃，蒲盧，細要土蠭也。天地之性，細要，純雄，無子。《詩》曰：“螟𧕅有子，𧒘蠃負之。”从虫𩰬聲。","rad":"虫","fq":"古火切","vol":"13","py":"ɡuǒ","duan":[{"e":"𧒘蠃、","n":"逗。曡韵。"}]},"嗢":{"expl":"咽也。从口𥁕聲。","rad":"口","fq":"烏沒切","vol":"02","py":"wà","duan":[{"e":"咽也。","n":"咽當作噎。聲之誤也。欠部曰。䯉、咽中息不利也。與嗢音義同。𥬇云嗢噱者。嗢在㗋中。噱在口也。"}]},"蠃":{"expl":"蜾蠃也。从虫𣎆聲。一曰虒蝓。","rad":"虫","fq":"郎果切","vol":"13","py":"luǒ","duan":[{"e":"𧒘蠃也。从虫。𣎆聲。","n":"郎果切。十七部。"}]},"𧕅":{"expl":"螟𧕅，桑蟲也。从虫霝聲。","rad":"虫","fq":"卽丁切","vol":"13","py":"línɡ","duan":[{"e":"螟𧕅、","n":"逗。曡韵。"}]},"蛺":{"expl":"蛺蜨也。从虫夾聲。","rad":"虫","fq":"兼叶切","vol":"13","py":"jiá","duan":[{"e":"蛺蜨也。","n":"曡韵爲名。今俗云胡蝶。見莊子。"}]},"蜨":{"expl":"蛺蜨也。从虫疌聲。","rad":"虫","fq":"徒叶切","vol":"13","py":"dié","duan":[{"e":"蛺蜨也。从虫。疌聲。","n":"徒叶切。八部。俗作蝶。"}]},"蚩":{"expl":"蟲也。从虫之聲。","rad":"虫","fq":"赤之切","vol":"13","py":"chī","duan":[{"e":"蚩蟲也。","n":"蚩字今補。此三字句。謂有蟲名蚩也。叚借爲氓之蚩蚩。毛傳曰。蚩蚩、郭厚之兒。玉篇曰。癡也。此謂毛詩。又曰𥬇也。此謂叚蚩爲𣢑也。"}]},"螌":{"expl":"螌蝥，毒蟲也。从虫般聲。","rad":"虫","fq":"布還切","vol":"13","py":"bān","duan":[{"e":"螌蝥、","n":"逗。雙聲。"}]},"蝥":{"expl":"螌蝥也。从虫敄聲。","rad":"虫","fq":"莫交切","vol":"13","py":"máo","duan":[{"e":"螌蝥也。从虫。敄聲。","n":"莫交切。按古音當如木。在三部。俗依本艸讀耳。蟲部曰。？亦或从敄。"}]},"蟠":{"expl":"鼠婦也。从虫番聲。","rad":"虫","fq":"附袁切","vol":"13","py":"fán","duan":[{"e":"鼠婦也。","n":"釋蟲曰。蟠、鼠負。負又作婦。本艸經曰。鼠婦、一名負蟠。郭樸曰。罋器底蟲。按此溼生蟲。今蘇州人所謂鞵底蟲也。蟠音附袁切。借爲蟠曲字。如樂記云。禮樂之極乎天而蟠乎地。方言曰。未陞天龍謂之蟠龍。此讀如盤。舟部般旋字之叚借也。"}]},"𧉅":{"expl":"蛜威，委黍。委黍，鼠婦也。从虫，伊省聲。","rad":"虫","fq":"於脂切","vol":"13","py":"yī","duan":[{"e":"𧉅威、","n":"𧉅各本作蛜。今正。𧉅威曡韵字。逗。"}]},"蜙":{"expl":"蜙蝑，以股鳴者。从虫松聲。","rad":"虫","fq":"息恭切","vol":"13","py":"sōnɡ","duan":[{"e":"蜙蝑、","n":"逗。雙聲。"}]},"哯":{"expl":"不歐而吐也。从口見聲。","rad":"口","fq":"胡典切","vol":"02","py":"xiàn","duan":[{"e":"不歐而吐也。","n":"欠部曰。歐、吐也。渾言之。此云不歐而吐也者、析言之。歐以匈㗋言。吐以出口言也。有匈㗋不作惡而已吐出者、謂之哯。玉篇、廣韵作不顧而唾。非也。"}]},"蝑":{"expl":"蜙蝑也。从虫胥聲。","rad":"虫","fq":"相居切","vol":"13","py":"xū","duan":[{"e":"蜙蝑也。从虫。胥聲。","n":"相居切。五部。陸氏引許愼先呂反。"}]},"蟅":{"expl":"蟲也。从虫庶聲。","rad":"虫","fq":"之夜切","vol":"13","py":"zhè","duan":[{"e":"螽也。","n":"螽各本譌作蟲。今正。方言曰。蟒、宋魏之閒謂之𧊇。南楚之外謂之蟅蟒。或謂之𧑥。郭注。卽蝗也。蟅音近詐。蟒音莫梗反。亦呼虴蜢。按卽今北人所謂蛨蚱。江南人謂之蝗蟲。蟅蟒、虴蜢一語之轉。許書上文云蜙蝑。下文曰蝗。蟅亦蝗也。故列字之次如此。若廣雅、本艸所云蟅者皆非許意。"}]},"蝗":{"expl":"螽也。从虫皇聲。","rad":"虫","fq":"乎光切","vol":"13","py":"huánɡ","duan":[{"e":"螽也。","n":"䖵部曰。螽、蝗也。是爲轉注。漢書五行傳曰。介蟲之孼者。謂小蟲有甲飛揚之類。陽氣所生也。於春秋爲螽。今謂之蝗。按螽蝗古今語也。是以春秋書螽。月令再言蝗蟲。月令、呂不韋所作。"}]},"蜩":{"expl":"蟬也。从虫周聲。《詩》曰：“五月鳴蜩。”","rad":"虫","fq":"徒聊切","vol":"13","py":"tiáo","duan":[{"e":"蟬也。","n":"豳風傳曰。蜩、螗也。大雅。如蜩如㜍。傳曰。蜩、蟬也。螗、蝘也。小雅。鳴蜩嘒嘒。傳曰。蜩、蟬也。不同者、或渾言。或析言。蟬之類不同也。夏小正傳曰。唐蜩者匽。爾雅曰。蜩、蜋蜩、螗蜩。許書無螗字。螗葢蟬之大者也。當依小正作唐。"}]},"蟬":{"expl":"以㫄鳴者。从虫單聲。","rad":"虫","fq":"市連切","vol":"13","py":"chán","duan":[{"e":"㠯旁鳴者。","n":"考工記梓人文。鄭云。旁鳴、蜩蜺屬。正義云。蟬鳴在脅。"}]},"蜺":{"expl":"寒蜩也。从虫兒聲。","rad":"虫","fq":"五雞切","vol":"13","py":"ní","duan":[{"e":"寒蜩也。","n":"方言。小而黑者謂之蜺。又曰。𧕄謂之寒蜩。寒蜩、瘖蜩也。不言蜺與寒蜩爲一。許本爾雅爲說。釋蟲曰。蜺、寒蜩。月令。七月、寒蟬鳴。鄭曰。寒蟬、寒蜩。謂蜺也。郭樸云。寒螿也。"}]},"螇":{"expl":"螇鹿，蛁蟟也。从虫奚聲。","rad":"虫","fq":"胡雞切","vol":"13","py":"xī","duan":[{"e":"螇鹿、","n":"逗。"}]},"蚗":{"expl":"𧉅蚗，蛁蟟也。从虫夬聲。","rad":"虫","fq":"於悅切","vol":"13","py":"jué","duan":[{"e":"𧉅蚗、","n":"逗。方言作蛥蚗。蛥音折。蚗音于列反。蛥多聲。不當音折。疑方言有誤。當從許作𧉅。音伊。"}]},"𧉄":{"expl":"𧉅蚗，蟬屬。讀若周天子赧。从虫丏聲。","rad":"虫","fq":"武延切","vol":"13","py":"mián","duan":[{"e":"𧉄蚗、","n":"逗。各本皆作𧉅蚗。則與篆文不屬。今依廣韵二仙所引正。"}]},"蛚":{"expl":"蜻蛚也。从虫列聲。","rad":"虫","fq":"良薛切","vol":"13","py":"liè","duan":[{"e":"蜻蛚也。","n":"按楊雄、李巡、陸璣、郭樸、玉篇、廣韵皆云。蟋蟀一名蜻𧊿。但許書不與上文𧍓篆爲伍。葢不以爲一物與。鄭注考工記曰。以注鳴者、精列屬。"}]},"吐":{"expl":"寫也。从口土聲。","rad":"口","fq":"他魯切","vol":"02","py":"tǔ","duan":[{"e":"寫也。从口。土聲。","n":"他魯切。五部。"}]},"蜻":{"expl":"蜻蛚也。从虫青聲。","rad":"虫","fq":"子盈切","vol":"13","py":"jīnɡ","duan":[{"e":"蜻蛚也。从虫。青聲。","n":"子盈切。十一部。按蜻蛚二篆當先蜻後蛚。後人倒之。下先蜻蛉則同此蜻。如𧉅蚗同𧉅威之𧉅、螟𧕅同食穀之螟也。"}]},"蛉":{"expl":"蜻蛉也。从虫令聲。一名桑桹。","rad":"虫","fq":"郎丁切","vol":"13","py":"línɡ","duan":[{"e":"蜻蛉也。","n":"戰國策曰。六足四翼。飛翔乎天地之閒。方言曰。蜻蛉謂之蝍蛉。郭云。江東謂之狐黎。淮南人呼䗧𧉅。音康伊。按淮南書水蠆爲䗓。卽蜻蛉也。今人作蜻蝏、蜻蜓。"}]},"蠓":{"expl":"蠛蠓也。从虫蒙聲。","rad":"虫","fq":"莫孔切","vol":"13","py":"měnɡ","duan":[{"e":"蔑蠓也。","n":"各本蔑作蠛。無此字。今正。蔑之言末也。𣁋也。爾雅作蠛。非古也。釋蟲曰。蠓、蠛蠓。孫炎曰。此蟲小於蚊。郭圖讚曰。小蟲似蜹。風舂雨磑。謂其飛上下如舂則天風。回旋如䃺則天雨。陸佃引郭語互易之。非也。史記。蜚鴻滿壄。索隠引高誘曰。飛鴻、蠛蠓也。按古鴻蒙爲曡韵。故高君知鴻爲蠓也。楊雄賦。浮蠛蠓而撇天。蠛蠓猶鴻蒙也。細至於蠓、則其外皆鴻蒙矣。故其字从蒙。"}]},"𧎾":{"expl":"螶𧎾也。一曰蜉游。朝生莫死者。从虫𡭴聲。","rad":"虫","fq":"离灼切","vol":"13","py":"lüè","duan":[{"e":"螶𧎾。","n":"螶字在䖵部。故於此釋其義。而䖵部曰螶𧎾也。皆文勢之自然也。"}]},"蜹":{"expl":"秦晉謂之蜹，楚謂之蚊。从虫芮聲。","rad":"虫","fq":"而銳切","vol":"13","py":"ruì","duan":[{"e":"秦晉謂之蜹。楚謂之蟁。","n":"蟁作蚊。俗。今正。蟁在䖵部。故不類列於此也。此爲方俗殊語以舉列也。"}]},"蟰":{"expl":"蟰蛸，長股者。从虫肅聲。","rad":"虫","fq":"穌彫切","vol":"13","py":"xiāo","duan":[{"e":"蟰蛸、","n":"逗。雙聲。"}]},"𧍖":{"expl":"蟲也。从虫省聲。","rad":"虫","fq":"息正切","vol":"13","py":"shěnɡ","duan":[{"e":"𧍖蟲也。","n":"有蟲名𧍖也。"}]},"蜉":{"expl":"商何也。从虫寽聲。","rad":"虫","fq":"力輟切","vol":"13","py":"liè","duan":[{"e":"商何也。","n":"釋蟲曰。蛶、螪何。郭云未詳。陸云商失羊反。字林之亦反。按字林近古。之亦反則字本作𧏸。而許書當作啻何矣。"}]},"蜡":{"expl":"蠅䏣也。《周禮》：“蜡氏掌除骴。”从虫昔聲。","rad":"虫","fq":"鉏駕切","vol":"13","py":"qù","duan":[{"e":"蠅䏣也。","n":"肉部曰。䏣、蠅乳肉中也。蜡䏣音義皆通。"}]},"蝡":{"expl":"動也。从虫耎聲。","rad":"虫","fq":"而沇切","vol":"13","py":"ruǎn","duan":[{"e":"動也。","n":"動者、作也。蟲之動曰蝡。"}]},"噦":{"expl":"气啎也。从口歲聲。","rad":"口","fq":"於月切","vol":"02","py":"yuē","duan":[{"e":"气啎也。","n":"啎、逆也。通俗文曰。氣逆曰噦。內則曰。不敢噦噫。靈樞經說六府氣。胃爲氣逆噦。"}]},"蚑":{"expl":"行也。从虫支聲。","rad":"虫","fq":"巨支切","vol":"13","py":"qí","duan":[{"e":"徐行也。凡生之類。行皆曰蚑。","n":"依李善洞簫、琴二賦注補徐字及凡生以下八字。凡蟲行曰蚑。周書曰。蚑行喘息。小弁曰。鹿斯之奔。維足伎伎。伎本亦作跂。毛傳曰。舒皃。箋云。伎伎然舒者。畱其羣也。按其字當作蚑蚑。毛傳、鄭箋正與徐行說合也。漢書。跂跂脈脈善緣壁。其字亦當作蚑蚑。凡生之類者、或行或飛、或毛或？、或介或鱗皆是也。"}]},"蠉":{"expl":"蟲行也。从虫瞏聲。","rad":"虫","fq":"香沇切","vol":"13","py":"xuān","duan":[{"e":"蟲行也。","n":"凡蟲行曰蠉。上蚑爲徐行。則蠉爲疾行也。羽部曰。翾、小飛也。"}]},"𧈪":{"expl":"蟲曳行也。从虫屮聲。讀若騁。","rad":"虫","fq":"丑善切","vol":"13","py":"chǎn","duan":[{"e":"蟲申行也。","n":"各本作曳行。以讀若騁定之、則伸行爲是。今正。許本無伸字。衹作申。故譌爲曵也。"}]},"螸":{"expl":"螽醜螸，垂腴也。从虫欲聲。","rad":"虫","fq":"余足切","vol":"13","py":"yú","duan":[{"e":"螽醜螸。","n":"螽俗本作蠭。今依宋本、李燾本、集韵正。釋蟲曰。蠭醜螸。音義曰。蠭、施乾作螽。施所據與許合。"}]},"𧎥":{"expl":"蠅醜𧎥，搖翼也。从虫扇聲。","rad":"虫","fq":"式戰切","vol":"13","py":"shàn","duan":[{"e":"蠅醜𧎥。","n":"釋蟲文。字衹作扇。"}]},"蛻":{"expl":"蛇蟬所解皮也。从虫，捝省。","rad":"虫","fq":"輸芮切","vol":"13","py":"tuì","duan":[{"e":"它蟬所解皮也。从虫。兌聲。","n":"兌聲各本作稅省聲。淺人改耳。今正。輸芮切。十五部。"}]},"𧊝":{"expl":"螫也。从虫，若省聲。","rad":"虫","fq":"呼各切","vol":"13","py":"hē","duan":[{"e":"螫也。","n":"蠚螫葢本一字。若聲赦聲同部也。或讀呼各切。山東行此音。或讀式亦切。關西行此音。見釋玄應書。今人乃以此篆切呼各。下篆切式亦。分而二之。"}]},"螫":{"expl":"蟲行毒也。从虫赦聲。","rad":"虫","fq":"施隻切","vol":"13","py":"shì","duan":[{"e":"蟲行毒也。","n":"周頌曰。自求辛螫。古亦叚奭爲之。史記有如㒳宮螫將軍、漢書作奭將軍是也。或云䖧音知列切。亦作蜇。"}]},"蝁":{"expl":"镻也。从虫亞聲。","rad":"虫","fq":"烏各切","vol":"13","py":"è","duan":[{"e":"镻也。","n":"俗本作虺屬。今依宋本及集韵正。長部曰。镻、蝁也。與此爲轉注。詳長部下。"}]},"蛘":{"expl":"搔蛘也。从虫羊聲。","rad":"虫","fq":"余兩切","vol":"13","py":"yǎnɡ","duan":[{"e":"騷蛘也。","n":"騷各本作搔。今正。疥字下曰。騷也。今亦作搔。搔、𠜜也。非其意。唐人所引作瘙。瘙見号韵。乃俗字。許所無。依義當作騷。騷、？也。毛云動也。騷痒者、擾動於肌膚閒也。玄應引禮記蛘不敢搔。俗多用痒癢養字。葢非也。蛘从虫者、往往有蟲濳於膜。故疥字亦或作？、作蚧。"}]},"咈":{"expl":"違也。从口弗聲。《周書》曰：“咈其耇長。”","rad":"口","fq":"符弗切","vol":"02","py":"fú","duan":[{"e":"違也。","n":"違與韋同。相背也。"}]},"𧐂":{"expl":"敗創也。从虫、人、食，食亦聲。","rad":"虫","fq":"乘力切","vol":"13","py":"shí","duan":[{"e":"敗創也。","n":"敗者、毀也。創者、傷也。毀壞之傷有蟲食之。故字从虫。春秋經曰。鼷鼠食郊牛角。又曰。日有食之。字或作？。"}]},"蛟":{"expl":"龍之屬也。池魚滿三千六百，蛟來爲之長，能率魚飛。置笱水中，卽蛟去。从虫交聲。","rad":"虫","fq":"古肴切","vol":"13","py":"jiāo","duan":[{"e":"龍屬。無角曰蛟。","n":"各本作龍之屬也四字。今依韵會正。龍者、鱗蟲之長。蛟其屬。無角則屬而别也。郭氏山海經傳曰。似蛇。四腳。細頸。頸有白嬰。大者數圍。卵生。子如一二斛瓮。能呑人。按蛟或作鮫。然鮫者魚名。其字不相代也。"}]},"螭":{"expl":"若龍而黃，北方謂之地螻。从虫离聲。或云無角曰螭。","rad":"虫","fq":"丑知切","vol":"13","py":"chī","duan":[{"e":"若龍而黃。","n":"南都賦曰。憚夔龍怖蛟螭。李注引說文蛟螭若龍而黃。按李注蛟字誤衍。左思蜀都賦。或藏蛟螭。劉注云。蛟螭、水神也。一曰雌龍。一曰龍子。似亦謂蛟螭爲一物。然上林賦蛟龍赤螭。文穎曰。龍子爲螭。張揖曰。赤螭、雌。龍也。皆劉說所本。張、左之賦皆不謂蛟螭一物也。許謂离爲山神。螭爲若龍而黃。與諸家說異。司馬相如曰赤螭。楊雄解嘲曰。翠虯絳螭之將登乎天。不謂其色黃矣。"}]},"虯":{"expl":"龍子有角者。从虫丩聲。","rad":"虫","fq":"渠幽切","vol":"13","py":"qiú","duan":[{"e":"龍無角者。","n":"各本作龍子有角者。今依韵會所據正。然韵會尙誤多子字。李善注甘泉賦引說文虯、龍無角者。他家所引作有角、皆誤也。王逸注離騷天問㒳言有角曰龍、無角曰虯。高誘注淮南同。張揖上林賦注、後漢書馮衍傳注、玉篇、廣韵皆曰。無角曰虯。絕無龍子有角之說。惟廣雅云。有角曰？。卽虯字。無角曰？。卽螭字。其說乖異。恐轉寫之譌。不爲典要。"}]},"蜦":{"expl":"蛇屬，黑色，潛于神淵，能興風雨。从虫侖聲。讀若戾艸。","rad":"虫","fq":"力屯切","vol":"13","py":"lún","duan":[{"e":"它屬也。","n":"它者、虫也。象寃曲垂尾形。蜦卽其屬也。"}]},"螊":{"expl":"海蟲也。長寸而白，可食。从虫兼聲。讀若嗛。","rad":"虫","fq":"力鹽切","vol":"13","py":"lián","duan":[{"e":"海蟲也。長寸而白。可食。","n":"按自螊至蜦八篆爲一類。皆介蟲也。其外有㱿。螊其小者也。長寸而白、謂其㱿。可食、謂其中肉也。本艸所謂𧍧䗯似蛤而長扁。𧍧與螊音同。玉篇曰。螊、小蚌。可食。"}]},"蜃":{"expl":"雉入海，化爲蜃。从虫辰聲。","rad":"虫","fq":"時忍切","vol":"13","py":"shèn","duan":[{"e":"大蛤。","n":"依韵會有此二字。羅氏願曰。月令九月雀入大水爲蛤。十月雉入大水爲蜃。比雀所化爲大。故稱大蛤也。按鄭注禮記曰。大蛤曰蜃。韋注國語曰。小曰蛤。大曰蜃。高注呂覽曰。蜃、蛤也。高渾言之。鄭、韋析言之。蜃與蚌雖屬而别。郭注爾雅云。蚌卽蜃。蜃之用詳於周禮、左傳。玉部曰。珧、蜃甲也。所以飾物。珕、蜃屬。天子佩刀玉琫珧珌。士珕琫珧珌。"}]},"𧊧":{"expl":"蜃屬。有三，皆生於海。千歲化爲𧊧，秦謂之牡厲。又云百歲燕所化。魁𧊧，一名復累，老服翼所化。从虫合聲。","rad":"虫","fq":"古沓切","vol":"13","py":"ɡé","duan":[{"e":"蜃屬。","n":"屬而有大小之别也。"}]},"螷":{"expl":"階也。脩爲螷，圜爲蠇。从虫、庳。","rad":"虫","fq":"蒲猛切","vol":"13","py":"pí","duan":[{"e":"陛也。","n":"陛各本作蜌。今爾雅同。韵會作陛。卽蚌語之轉也。當依玉部作玭。玭、蚌之有聲者也。釋魚曰。蜌、螷。許無蜌字。故先螷而以陛釋之。郭云。今江東呼蚌長而陜者爲螷。陶隱居注本艸之蝏𧏑也。蝏音亭。𧏑蒲幸切。卽螷字。周禮鼈人、醢人皆有螷。鄭司農云。螷、蛤也。杜子春云。螷、蜯也。蜯卽蚌字。蚌蛤有異。故二家說不同。許用杜說也。故下文受之以蚌。"}]},"蝸":{"expl":"蝸蠃也。从虫咼聲。","rad":"虫","fq":"亡華切","vol":"13","py":"wō","duan":[{"e":"蝸、","n":"此複舉篆文之未刪者也。當依韵會刪。"}]},"嚘":{"expl":"語未定皃。从口憂聲。","rad":"口","fq":"於求切","vol":"02","py":"yōu","duan":[{"e":"語未定皃。","n":"東方朔傳曰。伊憂亞者、辭未定也。集韵云。憂或作嚘。又老子。終日號而不嗄。玉篇作不嚘。云嚘、氣逆也。太玄。柔兒于號。三日不嚘。傅奕挍定老子作？。？同嚘。"}]},"蚌":{"expl":"蜃屬。从虫𡴀聲。","rad":"虫","fq":"步項切","vol":"13","py":"bànɡ","duan":[{"e":"蜃屬。","n":"蜃當作螷。釋魚曰。蚌、含漿。鄭注鼈人云。貍物、亦謂鱴刀、含漿之屬。按珠出於蚌。玉部曰。玭、蚌之有聲者。"}]},"蠇":{"expl":"蚌屬。似螊，微大，出海中，今民食之。从虫萬聲。讀若賴。","rad":"虫","fq":"力制切","vol":"13","py":"lì","duan":[{"e":"蚌屬。佀螊𣁋大。","n":"螊卽上文長寸而白者。據本艸經牡蠣條注。則此物有絕大者。不得云似螊𣁋大也。且蛤下作厲。云秦謂之牡厲。似蛤屬有厲。蚌屬有蠇。其字不必同。不煩以本艸牽合也。許所聞或與後人不盡合。讀書不貴盡信。"}]},"蝓":{"expl":"虒蝓也。从虫俞聲。","rad":"虫","fq":"羊朱切","vol":"13","py":"yú","duan":[{"e":"虒蝓也。","n":"虒蝓讀移臾二音。今生牆壁閒溼處。無㱿。有㒳角。無足。延行地上。俗𧦝延游。卽虒蝓古語也。本艸經作𧋣蝓。云一名陵螺。後人又出蝸牛一條。據本經則𧋣蝓卽蝸牛。合之釋蟲及鄭注周禮、許造說文皆不云蠃與螔蝓爲二。葢螺之無㱿者古亦𧦝螺。有㱿者正𧦝螔蝓。不似今人語言分别𧦝也。陸佃、宼宗奭分别之說。似非古言古義。"}]},"蜎":{"expl":"蜎也。从虫肙聲。","rad":"虫","fq":"在沇切","vol":"13","py":"yuān","duan":[{"e":"肙也。","n":"肙各本作蜎。仍複篆文不可通。攷肉部肙下云。小蟲也。今據正。韵會引說文井中蟲也。恐是據爾雅注改。肙蜎葢古今字。釋蟲。蜎、蠉。蠉本訓蟲行。叚作肙字耳。郭云。井中小蛣蟩赤蟲。一名孑孑。廣雅曰。孑孑、蜎也。周禮。刺兵欲無蜎。注云。蜎、掉也。謂若井中蟲蜎蜎。詩毛傳曰。蜎蜎、蜀皃。蜀、桑蟲也。其引申之義也。今水缸中多生此物。俗謂之水蛆。其變爲？。"}]},"蟺":{"expl":"夗蟺也。从虫亶聲。","rad":"虫","fq":"常演切","vol":"13","py":"shàn","duan":[{"e":"夗蟺也。","n":"夗、轉臥也。引申爲凡宛曲之稱。夗蟺曡韵。葢謂凡蟲之冤曲之狀。篇、韵皆云。䖤蟺、蚯蚓也。雖蚓有此名、而非許意。上文蜎善曲之物也。故承之以蟺。"}]},"𧍘":{"expl":"𧍘蟉也。从虫幽聲。","rad":"虫","fq":"於虯切","vol":"13","py":"yōu","duan":[{"e":"𧍘蟉也。","n":"三字句。曡韵也。司馬相如大人賦。驂赤螭靑虯之𧍘蟉蜿蜒。謂宛轉之皃也。按篇、韵皆曰龍皃。依賦文爲訓耳。非許有龍皃二字也。"}]},"蟉":{"expl":"𧍘蟉也。从虫翏聲。","rad":"虫","fq":"力幽切","vol":"13","py":"liú","duan":[{"e":"𧍘蟉也。从虫。翏聲。","n":"力幽切。亦上聲。三部。"}]},"蟄":{"expl":"藏也。从虫執聲。","rad":"虫","fq":"直立切","vol":"13","py":"zhé","duan":[{"e":"臧也。","n":"臧者、善也。善必自隱。故别無藏字。凡蟲之伏爲蟄。周南曰。螽斯羽。蟄蟄兮。傳曰。和集也。其引申之義也。"}]},"蚨":{"expl":"青蚨，水蟲，可還錢。从虫夫聲。","rad":"虫","fq":"房無切","vol":"13","py":"fú","duan":[{"e":"青蚨、","n":"逗。"}]},"䗇":{"expl":"䗇鼀，詹諸，以脰鳴者。从虫匊聲。","rad":"虫","fq":"居六切","vol":"13","py":"jú","duan":[{"e":"䗇鼀、","n":"逗。"}]},"吃":{"expl":"言蹇難也。从口气聲。","rad":"口","fq":"居乙切","vol":"02","py":"jī","duan":[{"e":"言蹇難也。从口。气聲。","n":"居乙切。十五部。"}]},"蝦":{"expl":"蝦蟆也。从虫叚聲。","rad":"虫","fq":"乎加切","vol":"13","py":"há","duan":[{"e":"蝦蟆也。","n":"蝦蟆見於本艸經。背有黑點。身小。能跳接百蟲。解作呷呷聲。舉動極急。蟾蜍身大。背黑無點。多痱磊。不能跳。不解作聲。行動遲緩。絕然二物。陳藏器、蘇頌皆能詳言之。許於此但云蝦蟆。不云䗇鼀也。亦謂其似同而異。"}]},"蟆":{"expl":"蝦蟆也。从虫莫聲。","rad":"虫","fq":"莫遐切","vol":"13","py":"má","duan":[{"e":"蝦蟆也。从虫。𦱤聲。","n":"莫遐切。古音在五部。"}]},"蠵":{"expl":"大龜也。以胃鳴者。从虫巂聲。","rad":"虫","fq":"戶圭切","vol":"13","py":"xī","duan":[{"e":"觜蠵。","n":"二字各本無。今補。此以曡韵爲名。角部觜下曰。一曰觜蠵也。未言何物。此蒙其文釋之曰大龜。"}]},"螹":{"expl":"螹離也。从虫，漸省聲。","rad":"虫","fq":"慈染切","vol":"13","py":"jiàn","duan":[{"e":"螹離也。","n":"三字句。螹史記、文𨕖同。漢書作漸。上林賦說水族曰。鮫龍赤螭。䱍䲛螹離。司馬彪曰。螹離、魚名也。張揖曰。其形狀未聞。按許以此次於蠵蠏二篆閒。必介蟲之類。周人或以漸離爲名。取於物爲假也。斬？字或作螹胡。非也。"}]},"蠏":{"expl":"有二敖八足，㫄行，非蛇鮮之穴無所庇。从虫解聲。","rad":"虫","fq":"胡買切","vol":"13","py":"xiè","duan":[{"e":"有二敖八足。","n":"敖俗作螯、作𩪋。廣韵曰。𩪋、蟹大腳也。螯、蟹屬。然則俗作螯尤誤也。敖、出游也。故其大腳曰敖。今本大戴禮作螯。非。"}]},"蛫":{"expl":"蟹也。从虫危聲。","rad":"虫","fq":"過委切","vol":"13","py":"ɡuǐ","duan":[{"e":"蠏也。","n":"廣雅。蜅蟹、蛫也。其雄曰蜋䱺。其雌曰博帶。"}]},"蜮":{"expl":"短狐也。似鼈，三足，以气䠶害人。从虫或聲。","rad":"虫","fq":"于逼切","vol":"13","py":"yù","duan":[{"e":"短弧也。","n":"弧各本作狐。今正。毛公、班固、張揖、陸璣、杜預、范甯皆曰短弧。今惟五行志、左傳釋文作弧。不誤矣。小雅。爲鬼爲蜮。傳曰。蜮、短弧也。左傳釋文曰。短弧又作狐。按此因其以氣射害人、故謂之短弧。作狐、非也。其氣爲矢、則其體爲弧。"}]},"𧊜":{"expl":"似蜥易，長一丈，水潛，吞人卽浮，出日南。从虫屰聲。","rad":"虫","fq":"吾各切","vol":"13","py":"è","duan":[{"e":"佀蜥易長一丈。","n":"當同鼉下云長丈許。"}]},"蛧":{"expl":"蛧蜽，山川之精物也。淮南王說：蛧蜽，狀如三歲小兒，赤黑色，赤目，長耳，美髮。从虫网聲。《國語》曰：“木石之怪夔蛧蜽。”","rad":"虫","fq":"文兩切","vol":"13","py":"wǎnɡ","duan":[{"e":"蛧蜽、","n":"逗。曡韵。"}]},"蜽":{"expl":"蛧蜽也。从虫兩聲。","rad":"虫","fq":"良獎切","vol":"13","py":"liǎnɡ","duan":[{"e":"蛧蜽也。从虫。兩聲。","n":"按兩聲之字疑古衹从㒳。後人改之。良奬切。十部。"}]},"嗜":{"expl":"嗜欲，喜之也。从口耆聲。","rad":"口","fq":"常利切","vol":"02","py":"shì","duan":[{"e":"喜欲之也。","n":"此依韵會本。喜當作憙憙、悅也。經傳多假耆爲嗜。"}]},"蝯":{"expl":"善援，禺屬。从虫爰聲。","rad":"虫","fq":"雨元切","vol":"13","py":"yuán","duan":[{"e":"善援。","n":"以曡韵爲訓。援者、引也。釋獸曰。猱蝯善援。許意以蝯善攀援、故偁蝯。？則蝯之屬而巳。故不言？。"}]},"蠗":{"expl":"禺屬。从虫翟聲。","rad":"虫","fq":"首角切","vol":"13","py":"zhuó","duan":[{"e":"禺屬。","n":"亦與母猴屬而别也。按爾雅釋獸自麋鹿至闕泄目爲寓屬。此對下篇釋嘼言之。嘼者、人所飬也。寓屬者、皆寄在於野不爲人飬者。而淺者謂卽說文所謂禺屬。何其謬哉。猱蝯貜父可謂禺屬。豈其他亦可謂禺屬乎。上林賦。蛭蜩蠗蝚棲息乎其閒。郭樸云。蠗猱似獼猴而黄。蠗猱二物。郭倂言之。非也。惟史記作蠗。漢書譌作玃。司馬貞曰。西山經皋塗之山有獸名蠗、是此字。攷其所說之狀非？猴類。其字今譌作𤣎。依郭注則當作玃。未可取爲證也。"}]},"蜼":{"expl":"如母猴，卬鼻，長尾。从虫隹聲。","rad":"虫","fq":"余季切","vol":"13","py":"wèi","duan":[{"e":"如母猴。","n":"猶言禺屬也。禺者、母猴屬。許書多言母猴。母猴、獼猴、沐猴一聲之轉。周禮蜼彝。鄭曰。蜼、禺屬。"}]},"蚼":{"expl":"北方肓蚼犬，食人。从虫句聲。","rad":"虫","fq":"古厚切","vol":"13","py":"ɡǒu","duan":[{"e":"北方有蚼犬食人。","n":"海內北經。蜪犬如犬。靑。食人從首始。郭注。蜪音陶。或作蚼。音鉤。按作蚼爲是。正許所本也。周書。渠搜以鼩犬。能飛食虎豹。鼩同蚼。借鼱鼩字爲之耳。大戴禮作渠搜貢虛犬。虛亦音之轉也。今本周書作䶂犬。依文選王融曲水詩序正。"}]},"蛩":{"expl":"蛩蛩，獸也。一曰秦謂蟬蛻曰蛩。从虫巩聲。","rad":"虫","fq":"渠容切","vol":"13","py":"qiónɡ","duan":[{"e":"蛩蛩獸也。","n":"四字句。子虛、上林賦皆有蛩蛩。張揖曰。蛩蛩、靑獸。狀如馬。按史記作邛邛。"}]},"蟨":{"expl":"鼠也。一曰西方有獸，前足短，與蛩蛩、巨虛比，其名謂之蟨。从虫厥聲。","rad":"虫","fq":"居月切","vol":"13","py":"jué","duan":[{"e":"鼠也。","n":"當作蟨鼠也三字句。鼠名。此葢用呂氏春秋蟨、鼠前兔後之說。"}]},"蝙":{"expl":"蝙蝠也。从虫扁聲。","rad":"虫","fq":"布玄切","vol":"13","py":"biān","duan":[{"e":"蝙蝠、","n":"逗。"}]},"蝠":{"expl":"蝙蝠，服翼也。从虫畐聲。","rad":"虫","fq":"方六切","vol":"13","py":"fú","duan":[{"e":"蝙蝠也。从虫。畐聲。","n":"方六切。古音在一部。"}]},"蠻":{"expl":"南蠻，蛇穜。从虫䜌聲。","rad":"虫","fq":"莫還切","vol":"13","py":"mán","duan":[{"e":"南蠻。","n":"職方氏。八蠻。爾雅。九夷、八狄、七戎、六蠻、謂之四海。王制云。南方曰蠻。詩角弓。如蠻如髦。傳曰。蠻、南蠻也。采𦬊。蠢爾荊蠻。傳曰。荊蠻、荊州之蠻也。"}]},"閩":{"expl":"東南越，蛇穜。从虫門聲。","rad":"虫","fq":"武巾切","vol":"13","py":"mǐn","duan":[{"e":"東南越。","n":"釋名曰。越、夷蠻之國也。度越禮義。無所拘也。職方氏。七閩。鄭司農曰。南方曰蠻。後鄭曰。閩、蠻之别也。引國語閩芈蠻矣。"}]},"啖":{"expl":"噍啖也。从口炎聲。一曰噉。","rad":"口","fq":"徒敢切","vol":"02","py":"dàn","duan":[{"e":"噍啖也。","n":"荀子王霸篇。啖啖常欲人之有。注。啖啖幷吞之皃。"}]},"虹":{"expl":"螮蝀也。狀似蟲。从虫工聲。《明堂月令》曰：“虹始見。”","rad":"虫","fq":"戶工切","vol":"13","py":"hónɡ","duan":[{"e":"螮蝀也。","n":"釋天曰。螮蝀謂之雩。螮蝀、虹也。毛傳同。"}]},"螮":{"expl":"螮蝀，虹也。从虫帶聲。","rad":"虫","fq":"都計切","vol":"13","py":"dì","duan":[{"e":"螮蝀、","n":"逗。雙聲。"}]},"蝀":{"expl":"螮蝀也。从虫東聲。","rad":"虫","fq":"多貢切","vol":"13","py":"dònɡ","duan":[{"e":"螮蝀也。从虫。東聲。","n":"多貢切。廣韵平上二聲。九部。"}]},"蠥":{"expl":"衣服、歌謠、艸木之怪，謂之䄏。禽獸、蟲蝗之怪，謂之蠥。从虫辥聲。","rad":"虫","fq":"魚列切","vol":"13","py":"niè","duan":[{"e":"衣服歌䚻艸木之怪謂之䄏。禽獸蟲蝗之怪謂之蠥。","n":"怪者、異也。地反物爲䄏。漢五行志曰。凡艸物之類謂之妖。妖猶夭胎。言尙微。蟲豸之類謂之孽。孽則牙孽矣。及六畜、謂之旤。言其著也。及人、謂之痾。痾、病皃。言？深也。甚則異物生、謂之眚。自外來、謂之祥。祥猶禎也。氣相傷、謂之沴。沴禉臨莅。不和意也。許所說較異。葢所傳有不同矣。禽獸蟲蝗之字皆得从虫。故蠥从虫。諸書多用孽。俗作㜸。"}]},"蜑":{"expl":"南方夷也。从虫延聲。","rad":"虫","fq":"徒旱切","vol":"13","py":"dàn","duan":[]},"蟪":{"expl":"蟪蛄，蟬也。从虫惠聲。","rad":"虫","fq":"曰棫切","vol":"13","py":"huì","duan":[]},"蠛":{"expl":"蠛蠓，細蟲也。从虫蔑聲。","rad":"虫","fq":"亡結切","vol":"13","py":"miè","duan":[]},"虴":{"expl":"虴蜢，艸上蟲也。从虫乇聲。","rad":"虫","fq":"陟格切","vol":"13","py":"zhé","duan":[]},"蜢":{"expl":"虴蜢也。从虫孟聲。","rad":"虫","fq":"莫杏切","vol":"13","py":"měnɡ","duan":[]},"蟋":{"expl":"蟋𧍓也。从虫悉聲。","rad":"虫","fq":"息七切","vol":"13","py":"xī","duan":[]},"璵":{"expl":"璵璠也。从玉與聲。","rad":"玉","fq":"以諸切","vol":"01","py":"yú","duan":[]},"哽":{"expl":"語爲舌所介也。从口更聲。讀若井級綆。","rad":"口","fq":"古杏切","vol":"02","py":"ɡěnɡ","duan":[{"e":"語爲舌所介也。","n":"哽介雙聲。漢書。祝哽在前。"}]},"螳":{"expl":"螳蜋也。从虫堂聲。","rad":"虫","fq":"徒郎切","vol":"13","py":"tánɡ","duan":[]},"䖵":{"expl":"蟲之緫名也。从二虫。凡䖵之屬皆从䖵。讀若昆。","rad":"䖵","fq":"古魂切","vol":"13","py":"kūn","duan":[{"e":"蟲之緫名也。","n":"蟲下曰。有足謂之蟲。無足謂之豸。析言之耳。渾言之則無足亦蟲也。虫下曰。或行或飛。或毛或？。或介或鱗。皆以虫爲象。故蟲皆从虫。而虫可讀爲蟲。蟲之緫名偁䖵。凡經傳言昆蟲、卽䖵蟲也。日部曰。昆、同也。夏小正昆小蟲傳曰。昆者、衆也。猶䰟䰟也。䰟䰟者、動也。小蟲動也。月令。昆蟲未蟄。鄭曰。昆、明也。許意與小正傳同。"}]},"蠶":{"expl":"任絲也。从䖵朁聲。","rad":"䖵","fq":"昨含切","vol":"13","py":"cán","duan":[{"e":"任絲蟲也。","n":"任俗譌作吐。今正。任與蠶以㬪韵爲訓也。言惟此物能任此事。美之也。絲下曰。蠶所吐也。"}]},"𧒎":{"expl":"蠶化飛蟲。从䖵我聲。","rad":"䖵","fq":"五何切","vol":"13","py":"é","duan":[{"e":"蠶匕飛𧒎。","n":"匕各本作化。今正。匕者、變也。蠶吐絲則成蛹於繭中。蛹復化而爲？。按此？與虫部之蛾羅主謂螘者、𢧵然不同。而郭氏釋爾雅蛾羅爲蠶蛾。非許意也。"}]},"𧎮":{"expl":"齧人跳蟲。从䖵㕚聲。㕚，古爪字。","rad":"䖵","fq":"子皓切","vol":"13","py":"zǎo","duan":[{"e":"齧人跳蟲也。","n":"齧、噬也。跳、躍也。蝨但齧人。𧎮則加之善躍。故著之。惡之甚也。"}]},"蝨":{"expl":"齧人蟲。从䖵卂聲。","rad":"䖵","fq":"所櫛切","vol":"13","py":"shī","duan":[{"e":"齧人蟲。","n":"古或叚幾瑟作蟣蝨。蟣者、蝨子也。"}]},"𧍸":{"expl":"蝗也。从䖵夂聲。夂，古文終字。","rad":"䖵","fq":"職戎切","vol":"13","py":"zhōnɡ","duan":[{"e":"蝗也。","n":"蝗下曰。螽也。是爲轉注。按爾雅有蛗螽、草螽、蜤螽、蟿螽、土螽。皆所謂螽醜也。蜤螽、詩作斯螽。亦云螽斯。毛、許皆訓以蜙蝑。皆螽類而非螽也。惟春秋所書者爲螽。"}]},"𧒝":{"expl":"蟲也。从䖵，展省聲。","rad":"䖵","fq":"知衍切","vol":"13","py":"zhǎn","duan":[{"e":"𧖉蟲也。","n":"蟲上補？字。三字一句。蟲名也。"}]},"蠽":{"expl":"小蟬蜩也。从䖵𢧵聲。","rad":"䖵","fq":"子列切","vol":"13","py":"jié","duan":[{"e":"小蟬蜩也。","n":"謂蟬之小者也。釋蟲曰。蠽。茅蜩。郭云。江東呼爲茅蠽。似蟬而小。靑色。方言曰。蟬、其小者謂之麥蚻。郭云。如蟬而小。靑色。今關西呼麥蠽。按茅麥雙聲。蠽蚻同字。郭云。蠽音癰？之？。"}]},"蠿":{"expl":"蠿蟊，作罔蛛蟊也。从䖵𢇍聲。𢇍，古絕字。","rad":"䖵","fq":"側八切","vol":"13","py":"zhuō","duan":[{"e":"蠿蟊、","n":"逗。"}]},"嘐":{"expl":"誇語也。从口翏聲。","rad":"口","fq":"古肴切","vol":"02","py":"xiāo","duan":[{"e":"誇語也。","n":"孟子。何以謂之狂也。曰其志嘐嘐然。曰古之人。古之人。夷考其行而不掩焉者也。"}]},"蟊":{"expl":"蠿蟊也。从䖵矛聲。","rad":"䖵","fq":"莫交切","vol":"13","py":"máo","duan":[{"e":"蠿蟊也。从䖵。矛聲。","n":"此字與蟲部食艸根者絕異。莫交切。古音謀在三部。"}]},"𧕝":{"expl":"蟲也。从䖵寍聲。","rad":"䖵","fq":"奴丁切","vol":"13","py":"nínɡ","duan":[{"e":"𧕝蟲也。","n":"蟲上補𧕝字。三字句。蟲名也。廣韵云螻蛄。"}]},"𧕐":{"expl":"𧓉𧕐也。从䖵曹聲。","rad":"䖵","fq":"財牢切","vol":"13","py":"cáo","duan":[{"e":"𧓉𧖤也。","n":"𧓉字見虫部。"}]},"𧕱":{"expl":"螻蛄也。从䖵舝聲。","rad":"䖵","fq":"胡葛切","vol":"13","py":"xiá","duan":[{"e":"螻蛄也。","n":"螻蛄見虫部。一名？。"}]},"𧓎":{"expl":"𧓎蛸也。从䖵卑聲。","rad":"䖵","fq":"匹標切","vol":"13","py":"pí","duan":[{"e":"𧓎蛸也。","n":"三字句。蛸字見虫部。"}]},"蠭":{"expl":"飛蟲螫人者。从䖵逢聲。","rad":"䖵","fq":"𢾭容切","vol":"13","py":"fēnɡ","duan":[{"e":"飛蟲螫人者。","n":"左傳。蠭？有毒。按釋蟲言土蠭、木蠭。無單言蠭者。許書則？蠃下云。細腰土蠭也。卽爾雅之土蠭。然則此單言蠭。卽爾雅之木蠭也。本艸經露蜂房、亦謂木上大黃蠭窠也。其房大者如罋。小者如桶。云露蠭、正對土蠭在地中言之。許謂土蠭爲細要純雄。其飛蟲螫人者、則謂大黃蠭。竝非細要純雄無子者。內則、檀弓謂之范。俗作𧍙。其子可食。故內則庶羞雀、鷃、蜩、范。"}]},"𧖅":{"expl":"蠭甘飴也。一曰螟子。从䖵鼏聲。","rad":"䖵","fq":"彌必切","vol":"13","py":"mì","duan":[{"e":"蠭甘飴也。","n":"飴者、米？煎也。蠭作食甘如之。凡蠭皆有？。方言。蠭大而蜜者謂之壷蠭。郭云。今黑蠭穿竹木作孔。亦有有蜜者。是則蠭飴名？。不主謂今之蜜蠭也。叚借爲？𣳚字。釋詁曰。？𣳚、勉也。亦作？𣳚。韓詩作蜜勿。毛詩作僶勉。"}]},"螶":{"expl":"螶𧐑也。从䖵巨聲。","rad":"䖵","fq":"强魚切","vol":"13","py":"qú","duan":[{"e":"螶𧎾也。","n":"三字句。𧎾字見虫部。"}]},"蟁":{"expl":"齧人飛蟲。从䖵民聲。","rad":"䖵","fq":"無分切","vol":"13","py":"wén","duan":[{"e":"齧人飛蟲。","n":"齧人而又善飛者。"}]},"蝱":{"expl":"齧人飛蟲。从䖵亡聲。","rad":"䖵","fq":"武庚切","vol":"13","py":"ménɡ","duan":[{"e":"齧人飛蟲。","n":"人當作牛。楚語。譬如牛馬。處暑之旣至。䖟䗽之旣多。而不能掉其尾。韋云。大曰䖟。小曰䗽。說苑曰。蠹蝝仆柱梁。蚊蝱走牛羊。史記。搏牛之蝱、不可以破蟣蝨。淮南書曰。蟁䖟不食駒犢。今人尙謂齧牛者爲牛蝱。本艸經有木䖟、蜚䖟。"}]},"啁":{"expl":"啁，嘐也。从口周聲。","rad":"口","fq":"陟交切","vol":"02","py":"zhāo","duan":[{"e":"啁、","n":"此複舉字未刪者。"}]},"蠹":{"expl":"木中蟲。从䖵橐聲。","rad":"䖵","fq":"當故切","vol":"13","py":"dù","duan":[{"e":"木中蟲。","n":"在木中食木者也。今俗謂之蛀。音注。左傳曰。公聚朽蠹。"}]},"蠡":{"expl":"蟲齧木中也。从䖵彖聲。","rad":"䖵","fq":"盧啓切","vol":"13","py":"lǐ","duan":[{"e":"蟲齧木中也。","n":"此非蟲名。乃謂螙之食木曰蠡也。朱子注孟子曰蠡者齧木蟲、則誤矣。蠡之言剺也。如刀之剺物。蠡叚借之用極多。或借爲蠃蚌字。或借爲瓢？字。楚辭。覽芷圃之蠡蠡。又借爲禾黍離離字。孟子曰。以追蠡。趙注曰。追、鐘鈕也。鈕擘齧處深矣。蠡蠡、欲絕之皃。此又以蠡同離、同劙。方言曰。劙、解也。又曰。蠡、分也。皆其義也。不知叚借之恉、乃云鐘鈕如蟲齧而欲絕。是株守許書之辭。而未能通許書之意矣。"}]},"𧒔":{"expl":"多足蟲也。从䖵求聲。","rad":"䖵","fq":"巨鳩切","vol":"13","py":"qiú","duan":[{"e":"多足蟲也。","n":"周禮赤犮氏。凡隙屋除其貍蟲。鄭曰。貍蟲、䗪、肌求之屬。按䗪見本艸經。一名地鼈。今俗所謂地鼈蟲也。似鼠婦。肌求本或作蛷。多足之蟲。今俗所謂蓑衣蟲也。通俗文曰。務求謂之蚑蛷。廣雅曰。蛷螋、？蛷也。玄應曰。關西呼？溲爲蚑蛷。蚑蛷卽鄭所謂肌蛷也。陶隱居、陳藏器作蠷螋。音劬蘇。"}]},"𧖚":{"expl":"蚍𧖚也。从䖵㯱聲。","rad":"䖵","fq":"縛牟切","vol":"13","py":"fú","duan":[{"e":"𧖕𧕰也。","n":"蟲部？𧕰、大螘也。此不言大螘者、義見於上一字。全書之例如是也。蚍蜉、大螘。釋蟲文。郭云。俗呼爲馬蚍蜉。按馬之言大也。"}]},"𧕲":{"expl":"蟲食也。从䖵雋聲。","rad":"䖵","fq":"子兖切","vol":"13","py":"juǎn","duan":[{"e":"蟲𠊊也。","n":"？之言吮也。吮欶也。鳥曰嗉。寓鼠曰嗛。昆蟲曰？。"}]},"蠢":{"expl":"蟲動也。从䖵春聲。","rad":"䖵","fq":"尺尹切","vol":"13","py":"chǔn","duan":[{"e":"蟲動也。","n":"此與蝡義同。以轉注之法言之。可云蝡也。引申爲凡動之偁。詩。蠢爾荆蠻。毛傳曰。蠢、動也。鄉飮酒義曰。東方者春。春之爲言蠢也。產萬物者也。注云。蠢、動生之皃。亦叚春爲之。考工記。張皮矦而棲鵠、則春以功。注云。春讀爲蠢。作也。出也。蠢與心部惷訓亂義異。"}]},"蟲":{"expl":"有足謂之蟲，無足謂之豸。从三虫。凡蟲之屬皆从蟲。","rad":"蟲","fq":"直弓切","vol":"13","py":"chónɡ","duan":[{"e":"有足謂之蟲。無足謂之豸。","n":"有舉渾言以包析言者。有舉析言以包渾言者。此蟲豸析言以包渾言也。蟲者、蝡動之緫名。前文旣詳之矣。故衹引爾雅釋蟲之文。豸者、獸長脊行豸豸然欲有所伺殺形也。本謂有足之蟲。因凡蟲無足者其行但見長脊豸豸然、故得叚借豸名。今人俗語云蟲豸。詩。溫隆蟲蟲。毛傳曰。蟲蟲而𤍠也。按蟲蟲葢融融之叚借。韓詩作烔。許所不取。"}]},"𧔨":{"expl":"蟲食艸根者。从蟲，象其形。吏抵冒取民財則生。","rad":"蟲","fq":"莫浮切","vol":"13","py":"máo","duan":[{"e":"蟲食艸𣒨者。","n":"艸當作苗。小雅。去其螟螣。及其蟊賊。釋蟲。食苗𣒨、蟊。毛傳。食𣒨曰蟊。螟𧎢已見虫部。𧎢是介屬。螟𧎢是𧝹屬。"}]},"𧖕":{"expl":"蚍蜉，大螘也。从蟲𣬈聲。","rad":"蟲","fq":"房脂切","vol":"13","py":"pí","duan":[{"e":"𧖕𧖚、","n":"逗。雙聲。𧖚見䖵部。"}]},"𧖔":{"expl":"蟁也。从蟲𨳌聲。","rad":"蟲","fq":"武巾切","vol":"13","py":"lìn","duan":[{"e":"蟁也。","n":"蟁之一名。"}]},"哇":{"expl":"諂聲也。从口圭聲。讀若醫。","rad":"口","fq":"於佳切","vol":"02","py":"wā","duan":[{"e":"諂聲也。","n":"淫哇也。王莽傳又假？爲哇。"}]},"𧕿":{"expl":"臭蟲，負蠜也。从蟲非聲。","rad":"蟲","fq":"房未切","vol":"13","py":"fěi","duan":[{"e":"臭蟲。負蠜也。","n":"按臭蟲下有奪字。當云臭蟲也、一曰負蠜也。畫然二說。如虫部蝝下之竝載三說也。春秋莊二十九年。秋、有蜚。左氏傳曰。爲災也。公羊傳曰。紀異也。穀梁傳曰。一有一亡曰有。漢五行志。劉歆以爲負蠜也。性不食穀。食穀爲災。按子駿葢演左氏說也。劉向以爲蜚色靑。近靑眚。非中國所有。南越盛暑。男女同川澤。淫風所生。爲蟲臭惡。是時嚴公取齊淫女爲夫人。旣入。淫於兩叔。故蜚至。按子政葢演穀梁之說。而何休、范𡩋皆從之也。許列臭蟲於先。而負蠜次之。許意子政說長也。負蠜與蠜畫然二物。釋蟲曰。？螽、蠜也。毛傳同。許同。此一物也。釋蟲曰。草螽、今爾雅作蟲譌負蠜也。毛傳則云草蟲、常羊也。常羊卽負蠜。鄭箋云。艸蟲鳴則阜螽躍而從之。是以"}]},"蠱":{"expl":"腹中蟲也。《春秋傳》曰：“皿蟲爲蠱。”“晦淫之所生也。”臬桀死之鬼亦爲蠱。从蟲从皿。皿，物之用也。","rad":"蟲","fq":"公戶切","vol":"13","py":"ɡǔ","duan":[{"e":"腹中蟲也。","n":"中蟲皆讀去聲。廣韵、集韵皆曰。蟲直衆切。蟲食物也。亦作蚛腹。中蟲者、謂腹內中蟲食之毒也。自外而入故曰中。自內而？故曰蟲。此與虫部腹中長蟲、腹中短蟲讀異。周禮庶氏。掌除毒蠱。注云。毒蠱、蟲物而病害人者。賊律曰。敢蠱人及敎令者棄市。左氏正義曰。以毒藥藥人。令人不自知。今律謂之蠱。玄應屢引說文蠱、腹中蟲也。謂行蟲毒也。下五字葢黙注語。顧野王輿地志曰。主人行食飮中殺人。人不覺也。字從箸蟲於飮食器中會意。"}]},"風":{"expl":"八風也。東方曰明庶風，東南曰清明風，南方曰景風，西南曰涼風，西方曰閶闔風，西北曰不周風，北方曰廣莫風，東北曰融風。風動蟲生。故蟲八日而化。从虫凡聲。凡風之屬皆从風。","rad":"風","fq":"方戎切","vol":"13","py":"fēnɡ","duan":[{"e":"八風也。東方曰朙庶風。東南曰淸朙風。南方曰景風。西南曰涼風。西方曰閶𨵵風。西北曰不周風。北方曰廣莫風。東北曰融風。","n":"樂記。八風從律而不姦。鄭曰。八風從律、應節至也。左氏傳。夫舞所以節八音而行八風。服注。八卦之風也。乾音石其風不周。坎音革、其風廣莫。艮音匏、其風融。震音竹、其風明庶。巽音木、其風淸明。離音絲、其風景。坤音土、其風涼。兌音金、其風閶？。易通卦驗曰。立春、調風至。春分、明庶風至。立夏、淸明風至。夏至、景風至。立秋、涼風至。秋分、閶？風至。立冬、不周風至。冬至、廣莫風至。白虎通調風作條風。條者、生也。明庶者、迎眾也。淸明者、芒也。景者、大也。言陽氣長養也。涼、寒也。陰氣行也。閶？者、咸收藏也。不周者、不交也。言陰陽未合化矣。廣莫者、大莫也。開陽氣也。按調風、條風、融風、一也。八卦、八節、八方、一也。"}]},"𩘁":{"expl":"北風謂之𩘁。从風，涼省聲。","rad":"風","fq":"呂張切","vol":"13","py":"liánɡ","duan":[{"e":"北風謂之𩘁。","n":"爾雅。南風謂之凱風。東風謂之谷風。北風謂之涼風。西風謂之泰風。毛傳於詩凱風、谷風皆用爲訓。桑柔之大風、則不言何風。而箋以西風釋之。若邶詩北風其涼、本無涼風字。故毛但曰寒涼之風而已。不用爾雅也。陸氏爾雅音義曰。涼本或作？。許所據爾雅同或作本。"}]},"𩖶":{"expl":"小風也。从風朮聲。","rad":"風","fq":"翾聿切","vol":"13","py":"xuè","duan":[{"e":"小風也。","n":"也玉篇作皃。廣韵之䬂、卽此字也。"}]},"飆":{"expl":"扶搖風也。从風猋聲。","rad":"風","fq":"甫遙切","vol":"13","py":"biāo","duan":[{"e":"扶搖風也。","n":"司馬注莊子云。上行風謂之扶搖。釋天曰。扶搖謂之猋。郭云。暴風從下上。按爾雅、月令用古字。陸云。字林作飇。不言說文。此等舉一以包二耳。"}]},"飄":{"expl":"回風也。从風㶾聲。","rad":"風","fq":"撫招切","vol":"13","py":"piāo","duan":[{"e":"回風也。","n":"回者、般旋而起之風。莊子所謂羊角。司馬云。風曲上行若羊角也。釋天云。迴風爲飄。匪風毛傳同。按何人斯傳曰。飄風、暴起之風。依文爲義。故不云回風。"}]},"颯":{"expl":"翔風也。从風立聲。","rad":"風","fq":"穌合切","vol":"13","py":"sà","duan":[{"e":"風聲也。","n":"各本作翔風也。今依文選風賦注正。廣韵同。九歌曰。風颯颯木蕭蕭。風賦曰。有風颯然而至。翔風非字意也。"}]},"飂":{"expl":"高風也。从風翏聲。","rad":"風","fq":"力求切","vol":"13","py":"liú","duan":[{"e":"高風也。","n":"吕氏春秋有始覽曰。西方曰飂風。"}]},"䬍":{"expl":"疾風也。从風从忽，忽亦聲。","rad":"風","fq":"呼骨切","vol":"13","py":"hū","duan":[{"e":"疾風也。","n":"廣雅作？。廣韵曰。？爲䬍之俗。然則作？者又？之省也。按古有颸字。亦訓疾風。楚飢切。見楚辭及吳都賦。"}]},"𠱫":{"expl":"語相訶歫也。从口歫䇂。䇂，惡聲也。讀若櫱。","rad":"口","fq":"五葛切","vol":"02","py":"è","duan":[{"e":"語相訶歫也。","n":"歫今之拒字。訶歫者、訶而拒之。"}]},"䬑":{"expl":"大風也。从風胃聲。","rad":"風","fq":"王勿切","vol":"13","py":"wèi","duan":[{"e":"大風也。从風。胃聲。","n":"王忽切。十五部。玉篇于貴切。"}]},"䫻":{"expl":"大風也。从風日聲。","rad":"風","fq":"于筆切","vol":"13","py":"yù","duan":[{"e":"大風也。从風。曰聲。","n":"曰各本作日月之日。非聲也。今倂篆體正。于筆切。十五部。"}]},"颺":{"expl":"風所飛揚也。从風昜聲。","rad":"風","fq":"與章切","vol":"13","py":"yánɡ","duan":[{"e":"風所飛揚也。","n":"揚者。飛舉也。"}]},"䬆":{"expl":"風雨暴疾也。从風利聲。讀若栗。","rad":"風","fq":"力質切","vol":"13","py":"lì","duan":[{"e":"䬆颲、","n":"二字各本無。今補。㬪韵字也。逗。"}]},"颲":{"expl":"烈風也。从風𠛱聲。讀若𠛱。","rad":"風","fq":"良薛切","vol":"13","py":"liè","duan":[{"e":"䬆颲也。","n":"各本作烈風也。今正。詩。二之日栗烈。說文仌部作凓冽。今本冽譌？。陸氏音義不偁仌部。而曰說文作䬆颲。葢由㬪韵音同而誤也。然可以證古本之䬆颲緜聨矣。廣韵五質䬆下曰。䬆颲暴風。十七薛颲下曰。風雨暴至。亦可爲證。"}]},"颸":{"expl":"涼風也。从風思聲。","rad":"風","fq":"息茲切","vol":"13","py":"sī","duan":[]},"䬒":{"expl":"颼飂也。从風叜聲。","rad":"風","fq":"所鳩切","vol":"13","py":"sōu","duan":[]},"颭":{"expl":"風吹浪動也。从風占聲。","rad":"風","fq":"隻冉切","vol":"13","py":"zhǎn","duan":[]},"它":{"expl":"虫也。从虫而長，象冤曲垂尾形。上古艸居患它，故相問無它乎。凡它之屬皆从它。","rad":"它","fq":"託何切","vol":"13","py":"tā","duan":[{"e":"虫也。从虫而長。象冤曲𠂹尾形。","n":"𠂹各本作垂。今正。𠂹者、艸木華葉𠂹也。引申爲凡物下𠂹之偁。垂者遠邊。非其義。冤曲者、其體。垂尾者、其末。？象其臥形。故詘尾而短。？象其上冤曲而下垂尾。故長。詘尾謂之虫。垂尾謂之它。它與𠂹古音同也。詩。維虺維蛇。女子之祥。吳語。爲虺弗摧。爲蛇將若何。虺皆虫之叚借。皆謂或臥或垂尾耳。臥者較易制。曳尾而行者難制。故曰爲虺弗摧、爲蛇將若何也。託何切。十七部。今人蛇與它異義異音。蛇食遮切。"}]},"龜":{"expl":"舊也。外骨内肉者也。从它，龜頭與它頭同。天地之性，廣肩無雄；龜鼈之類，以它爲雄。象足甲尾之形。凡龜之屬皆从龜。","rad":"龜","fq":"居追切","vol":"13","py":"ɡuī","duan":[{"e":"舊也。","n":"此以㬪韵爲訓。門聞、戶護之例。龜古音姬。亦音鳩。舊古音曰。亦音忌。舊本鴟舊字。叚借爲故舊。卽久字也。劉向曰。蓍之言耆。龜之言久。龜千歲而靈。蓍百年而神。以其長久、故能辨吉凶。白虎通語略同。龜之大者曰鼇。敖與久音相近。"}]},"吺":{"expl":"讘吺，多言也。从口，投省聲。","rad":"口","fq":"當矦切","vol":"02","py":"dōu","duan":[{"e":"讘吺、","n":"逗。"}]},"终":{"expl":"龜名。从龜夂聲。夂，古文終字。","rad":"龜","fq":"徒冬切","vol":"13","py":"tónɡ","duan":[{"e":"龜名。","n":"當作？龜也三字句。"}]},"䶲":{"expl":"龜甲邊也。从龜冄聲。天子巨䶲，尺有二寸，諸矦尺，大夫八寸，士六寸。","rad":"龜","fq":"没閻切","vol":"13","py":"rán","duan":[{"e":"龜甲邊也。","n":"公羊傳曰。龜靑純。何注。純、緣也。謂。緣甲？也。千歲之龜靑？。明乎吉凶也。樂記、史記樂書皆曰。靑黑緣者、天子之寶龜也。按？者？之省。？之叚借字。劉淵林注蜀都賦引譙周異物志曰。涪陵多大龜。其甲可以卜。其緣中叉。今釵字似瑇瑁。名曰靈叉。郭注爾雅亦用其語。而今本多譌字。緣者、甲之邊也。甲文象木戴孚甲之象。故介蟲外骨謂之甲。"}]},"黽":{"expl":"鼃黽也。从它，象形。𪓑頭與它頭同。凡𪓑之屬皆从𪓑。","rad":"黽","fq":"莫杏切","vol":"13","py":"měnɡ","duan":[{"e":"鼃黽也。","n":"周禮蟈氏。掌去鼃黽。鄭司農云。蟈、蝦蟇也。月令曰。螻蟈鳴。鼃黽、蝦蟇屬。書或爲掌去蝦蟇。玄謂蟈、今御所食蛙也。齊魯之閒謂鼃爲蟈。黽、耿黽也。蟈與耿黽尢怒鳴。爲？人耳。故去之。按蛙卽鼃字。依大鄭說則鼃黽二字爲一物。依後鄭說則鼃卽蟈、爲一物。黽乃耿黽、爲一物。依許黽下曰鼃黽也。似同大鄭說。然有當辯者。許果合二字爲一物。則黽篆下當云鼃黽、蝦蟆也。鼃下云鼃黽也。乃合全書之例。而蝦蟆篆居虫部。此則單舉鼃篆。釋曰蝦蟆。黽篆下則曰鼃黽也。是許意鼃黽爲一物。鼃爲一物。凡兩字爲名一字與他物同者、不可與他物牽混。知鼃黽非鼃也。許之鼃黽卽鄭之耿黽。鼃古音圭。與耿雙聲。故得爲一字。絫𧦝曰鼃黽、耿黽。單𧦝曰黽。爾雅。鼃"}]},"鼈":{"expl":"甲蟲也。从𪓑敝聲。","rad":"黽","fq":"并列切","vol":"13","py":"biē","duan":[{"e":"甲蟲也。","n":"考工記注。外骨、龜屬。內骨、蟞屬。按鼈骨較龜稍內耳。實介屬也。故周易鼈蟹蠃蚌龜爲一屬。"}]},"黿":{"expl":"大鼈也。从𪓑元聲。","rad":"黽","fq":"愚袁切","vol":"13","py":"yuán","duan":[{"e":"大鼈也。","n":"今目驗黿與鼈同形。而但分大小之別。"}]},"鼃":{"expl":"蝦蟇也。从𪓑圭聲。","rad":"黽","fq":"烏媧切","vol":"13","py":"wā","duan":[{"e":"蝦蟆屬。","n":"屬各本作也。今依韵會九佳所據小徐本正。廣韵同。蝦蟆見虫部。蝦蟆與詹諸小別。鼃則與蝦蟆大別。而其形相似。故言屬而別見。漢書武帝紀。元鼎五年。鼃、蝦蟆鬬。是可知其別矣。鼃者、周禮所謂蟈。今南人所謂水雞。亦曰田雞。鼃蛤皆其鳴聲也。故宋人詩多云吠蛤。亦云蛙聲閤閤。"}]},"鼀":{"expl":"圥鼀，詹諸也。其鳴詹諸，其皮鼀鼀，其行圥圥。从黽从圥，圥亦聲。","rad":"黽","fq":"七宿切","vol":"13","py":"cù","duan":[{"e":"圥鼀、","n":"逗。㬪韵。"}]},"𪓿":{"expl":"𪓰𪓿，詹諸也。《詩》曰：“得此𪓰𪓿。”言其行𪓿𪓿。从黽爾聲。","rad":"黽","fq":"式支切","vol":"13","py":"shī","duan":[{"e":"𪓰𪓿、","n":"逗。"}]},"鼉":{"expl":"水蟲。似蜥易，長大。从黽單聲。","rad":"黽","fq":"徒何切","vol":"13","py":"tuó","duan":[{"e":"水蟲。佀蜥易。長丈所。","n":"所字依太平御覽補。丈所猶丈許也。大雅靈臺傳曰。？、魚屬。馬部驒下曰。靑驪白鱗文如？魚。許依毛謂之？魚也。"}]},"𪓷":{"expl":"水蟲也。薉貉之民食之。从黽奚聲。","rad":"黽","fq":"胡雞切","vol":"13","py":"xí","duan":[{"e":"水蟲也。薉貉之民食之。","n":"葢猶中國之食鼃、謂之水雞也。"}]},"呧":{"expl":"苛也。从口氐聲。","rad":"口","fq":"都禮切","vol":"02","py":"dǐ","duan":[{"e":"苛也。","n":"苛者、訶之假借字。漢人多用荷爲訶。亦用苛爲訶。"}]},"䵶":{"expl":"𪓷屬，頭有兩角，出遼東。从黽句聲。","rad":"黽","fq":"其俱切","vol":"13","py":"qú","duan":[{"e":"𪓷屬。頭有㒳角。","n":"以頭有二角別於𪓷也。葢亦可食。"}]},"蠅":{"expl":"營營青蠅。蟲之大腹者。从黽从虫。","rad":"黽","fq":"余陵切","vol":"13","py":"yínɡ","duan":[{"e":"營營靑蠅。","n":"小雅靑蠅文。傳曰。營營、往來皃。"}]},"䵹":{"expl":"䵹鼄，蟊也。从黽，𥏼省聲。","rad":"黽","fq":"陟离切","vol":"13","py":"zhī","duan":[{"e":"䵹鼄、","n":"逗。雙聲。"}]},"鼄":{"expl":"䵹鼄也。从黽朱聲。","rad":"黽","fq":"陟輸切","vol":"13","py":"zhū","duan":[{"e":"䵹鼄也。从黽。朱聲。","n":"陟輸切。四部。"}]},"鼂":{"expl":"匽鼂也。讀若朝。楊雄說：匽鼂，蟲名。杜林以爲朝旦，非是。从黽从旦。","rad":"黽","fq":"直遙切","vol":"13","py":"cháo","duan":[{"e":"匽鼂也。讀若朝。","n":"陟遙切。二部。"}]},"鼇":{"expl":"海大鼈也。从黽敖聲。","rad":"黽","fq":"五牢切","vol":"13","py":"áo","duan":[]},"卵":{"expl":"凡物無乳者卵生。象形。凡卵之屬皆从卵。","rad":"卵","fq":"盧管切","vol":"13","py":"luǎn","duan":[{"e":"凡物無乳者卵生。","n":"？部曰。人及鳥生子曰乳。獸曰產。此云凡物無乳者卵生。按此乳字與？部乳字義少異。此乳謂乳汁也。惟人及四足之獸有之。故其子胎生。羽蟲、鱗蟲、介蟲及一切昆蟲皆無乳汁。其子卵生。故曰凡物無乳者卵生。然則何以言人及鳥生曰乳、獸曰產也。此乳猶抱也、嫗也。方言。北燕朝鮮洌水之閒謂伏雞曰抱。爵子及雞雛皆謂之鷇。其卵伏而未孚、始化謂之涅。鄭注樂記曰。以體曰嫗。惟鳥於卵伏之抱之。旣孚而或生哺之。有似人之抱哺其子。凡獸之恩勤遜於是。故以鳥之將子與人竝言。乳實乳汁之義之引申。許泥𠃉爲鳥。故訓乳曰人及鳥也。子部曰。㝅、乳也。此乳汁之乳。字及孺皆曰乳子也。此乳哺之乳。此云無乳者卵生、亦指謂乳汁也。"}]},"毈":{"expl":"卵不孚也。从卵段聲。","rad":"卵","fq":"徒玩切","vol":"13","py":"duàn","duan":[{"e":"卵不孚也。","n":"爪部曰。孚者、卵卽孚也。从爪子。不孚者、卵坼不成。樂記曰。卵生者不殈。鄭曰。殈、裂也。今齊人語有云殈者。按殈卽毈也。吕氏春秋。雞卵心毈。管子五行篇。羽卵者不段。叚段爲之。"}]},"二":{"expl":"地之數也。从偶一。凡二之屬皆从二。","rad":"二","fq":"而至切","vol":"13","py":"èr","duan":[{"e":"地之數也。","n":"易曰。天一地二。惟初大始。道立於一。有一而後有二。元气初分。輕淸昜爲天。重濁侌爲地。"}]},"亟":{"expl":"敏疾也。从人从口，从又从二。二，天地也。","rad":"二","fq":"紀力切","vol":"13","py":"jí","duan":[{"e":"敏疾也。","n":"攴部曰。敏者、疾也。疾者、本無其字、依聲託事之字也。後人以捷當之。今人亟分入聲去聲。入之訓急也。去之訓數也。古無是分別。數亦急也。非有二義。詩。亟其乘屋。箋云。亟、急也。詩多叚棘爲亟。如棘人欒欒。傳曰。棘、急也。我是用棘。非棘其欲。皆同。禮記作匪革其猶。革亦亟之叚借字也。釋言曰。悈、急也。亦作㥛。皆亟字之異者耳。"}]},"呰":{"expl":"苛也。从口此聲。","rad":"口","fq":"將此切","vol":"02","py":"zǐ","duan":[{"e":"苛也。","n":"苛亦當作訶。玄應引作訶。凡言呰毀當用呰。喪服四制。呰者莫不知禮之所生也。鄭云。口毀曰呰。玄應引如此。今禮記作訾。按少儀注㒳云訾、思也。"}]},"恒":{"expl":"常也。从心从舟，在二之閒上下。心以舟施，恆也。","rad":"二","fq":"胡登切","vol":"13","py":"hénɡ","duan":[{"e":"常也。","n":"常當作長。古長久字衹作長。淺人稍稍分別。乃或借下帬之常爲之。故至集韵乃有一曰久也之訓。而篇、韵皆無之。此俗字之不可不正者也。時之長與尺寸之長、非有二義。"}]},"亘":{"expl":"求亘也。从二从囘。囘，古文回，象亘回形。上下，所求物也。","rad":"二","fq":"須緣切","vol":"13","py":"xuān","duan":[{"e":"求回也。","n":"回各本作𠄢。今正。以回釋𠄢。以雙聲爲訓也。回者、轉也。？字經典不見。易屯卦磐桓。磐亦作盤。亦作槃。義當作般。桓義當作？。般者、辟也。？者、回也。馬融云。槃桓、旋也。是二字皆叚借也。凡舟之旋曰般。旌旗之指？曰旋。車之運曰轉。？柄曰斡。皆其意也。"}]},"竺":{"expl":"厚也。从二竹聲。","rad":"二","fq":"冬毒切","vol":"13","py":"dǔ","duan":[{"e":"𣆪也。","n":"𣆪各本作厚。今正。許意厚薄字當作𣆪。山陵之𣆪乃作？。不容一之。爾雅、毛傳皆曰。篤、厚也。今經典絕少作竺者。惟釋詁尙存其舊。叚借之字行而眞字廢矣。篤、馬行鈍遲也。聲同而義略相近。故叚借之字專行焉。"}]},"凡":{"expl":"最括也。从二，二，偶也。从绅，绅，古文及。","rad":"二","fq":"浮䒦切","vol":"13","py":"fán","duan":[{"e":"冣𢬸而言也。","n":"冣各本作最。最者、犯而取也。非其義。今正。冣者、積也。才句切。𢬸者、絜也。絜者、束也。絜者、麻一耑。束之成一耑也。冣𢬸者、緫聚而絜束之也。意內言外曰䛐。其意冣𢬸、其言凡也。春秋䋣露曰。號凡而略。名目而詳。目者、徧辨其事也。凡者、獨舉其大也。享鬼神者號一曰祭。祭之散名。春曰祠、夏曰礿、秋曰嘗、冬曰丞。獵禽獸者號一曰田。田之散名。春苗、秋蒐、冬狩。按周禮多言凡。六典、凡也。治典、敎典、禮典、政典、刑典、事典、目也。鄭注。言冣目者、謂其緫數也。若其他言凡祭祀、凡賓客、凡禮事、凡邦之弔事。言師掌官成以治凡。亦皆聚括之謂。舉其凡、則若网在綱。杜預之說春秋曰。傳之義例。緫歸諸凡。凡之言氾也。包舉氾濫一切之"}]},"土":{"expl":"地之吐生物者也。二象地之下、地之中，物出形也。凡土之屬皆从土。","rad":"土","fq":"它魯切","vol":"13","py":"tǔ","duan":[{"e":"地之吐生萬物者也。","n":"吐土㬪韵。釋名曰。土、吐也。吐萬物也。"}]},"地":{"expl":"元气初分，輕清陽爲天，重濁陰爲地。萬物所陳𠛱也。从土也聲。","rad":"土","fq":"徒内切","vol":"13","py":"dì","duan":[{"e":"元气初分。輕淸昜爲天。重濁侌爲地。","n":"元者、始也。陰陽大論曰。黃帝問於岐伯曰。地之爲下否乎。岐伯曰。地爲人之下。大虛之中者也。黃帝曰。馮乎。岐伯曰。大氣舉之也。按地之重濁而包舉乎輕淸之氣中。是以不墜。"}]},"坤":{"expl":"地也。《易》之卦也。从土从申。土位在申。","rad":"土","fq":"苦昆切","vol":"13","py":"kūn","duan":[{"e":"地也。易之卦也。","n":"象傳曰。地勢坤。君子以厚德載物。說卦傳曰。坤、順也。按伏羲取天地之德爲卦。名曰乾坤。"}]},"垓":{"expl":"兼垓八極地也。《國語》曰：“天子居九垓之田。”从土亥聲。","rad":"土","fq":"古哀切","vol":"13","py":"ɡāi","duan":[{"e":"兼晐八極地也。","n":"晐各本作垓。今正。晐俗作該。日部晐下曰。兼晐也。此用其義釋垓。以㬪韵爲訓也。凡四方所至謂之四極。八到所至謂之八極。淮南書曰。八紘之外乃有八極。非此義也。兼備八極之地謂之垓。"}]},"墺":{"expl":"四方土可居也。从土奧聲。","rad":"土","fq":"於六切","vol":"13","py":"ào","duan":[{"e":"四方之土可定凥者也。","n":"各本作四方土可居也。少三字。今依李善西都賦注正。禹貢。四墺旣宅。今作隩者、衞包改也。僞孔傳曰。四方之土可居。玉篇土部引夏書四墺旣宅。廣韵三十七号墺字注曰。四墺、四方土。文選西都賦。天地之隩區。李注引此說文。知班賦本从土。唐以後人乃改之。如今本尙書釋文之作隩耳。周語。宅爲九隩。注云。隩、內也。其字从𨸏。"}]},"堣":{"expl":"堣夷，在冀州陽谷。立春日，日值之而出。从土禺聲。《尚書》曰：“宅堣夷。”","rad":"土","fq":"噳俱切","vol":"13","py":"yú","duan":[{"e":"堣夷、","n":"逗。"}]},"嗻":{"expl":"遮也。从口庶聲。","rad":"口","fq":"之夜切","vol":"02","py":"zhè","duan":[{"e":"遮也。","n":"廣韵。嗻、多語之皃。然則遮者、謂多言遏遮人言也。"}]},"坶":{"expl":"朝歌南七十里地。《周書》：“武王與紂戰于坶野。”从土母聲。","rad":"土","fq":"莫六切","vol":"13","py":"mù","duan":[{"e":"朝歌南七十里地。周書曰。武王與紂戰于坶野。","n":"此書序文也。今書序紂作受。坶作牧。詩大明。矢于牧野。正義引鄭書序注云。牧野、紂南郊地名。禮記及詩作㙁野。古字耳。此鄭所見詩、禮記作㙁。書序衹作牧也。許所據序則作坶。葢所傳有不同。坶作㙁者、字之增改也。每亦母聲也。"}]},"坡":{"expl":"阪也。从土皮聲。","rad":"土","fq":"滂禾切","vol":"13","py":"pō","duan":[{"e":"阪也。","n":"𨸏部曰。坡者曰阪。此二篆轉注也。又曰。陂、阪也。是坡陂二字音義皆同也。坡謂其陂陀。毛詩。隰則有泮。傳曰。泮、坡也。此釋叚借之法。謂泮卽坡之雙聲叚借也。鄭不從其說。而易之曰讀爲畔。"}]},"坪":{"expl":"地平也。从土从平，平亦聲。","rad":"土","fq":"皮命切","vol":"13","py":"pínɡ","duan":[{"e":"地平也。","n":"舊鈔小徐本作？。廣韵。？、地名。今義也。"}]},"均":{"expl":"平徧也。从土从勻，勻亦聲。","rad":"土","fq":"居勻切","vol":"13","py":"jūn","duan":[{"e":"平徧也。","n":"平者、語平舒也。引申爲凡平舒之偁。徧者、帀也。平徧者、平而帀也。言無所不平也。小雅節南山傳曰。均、平也。古多叚旬爲均。亦叚鈞爲均。"}]},"壤":{"expl":"柔土也。从土襄聲。","rad":"土","fq":"如兩切","vol":"13","py":"rǎnɡ","duan":[{"e":"柔土也。","n":"大雅。陶復陶穴。毛傳。陶其土而復之。陶其壤而穴之。九章筭術。今有穿地積一萬尺。問爲堅壤各幾何。荅曰。爲堅七千五百尺。爲壤一萬二千五百尺。穿地四。爲壤五。爲堅三。爲墟四。劉徽注。壤謂息土。堅謂築土。周禮。辨十有二壤之名物、而知其種。以敎稼穡樹蓺。注。壤亦土也。以萬物自生言則言土。土猶吐也。以人所耕而樹蓺言則言壤。壤、和緩之皃。某氏注尙書曰。無塊曰壤。周禮草人。墳壤用麋。勃壤用狐。鄭云。墳壤潤解。勃壤粉解。釋名曰。壤、瀼也。肥濡意也。按言物性之自然。壤異乎堅土。言人功、則凡土皆得而壤之。壤與柔弱雙聲。穀梁。日有食之。傳曰。吐者外壤。食者內壤。闕然不見其壤。有食之者也。麋信云。齊魯之閒謂鑿地出土、鼠"}]},"塙":{"expl":"堅不可拔也。从土高聲。","rad":"土","fq":"苦角切","vol":"13","py":"què","duan":[{"e":"堅不可拔也。","n":"堅者、剛土也。拔者、擢也。不可拔者、不可擢而起之也。易文言曰。確乎其不可拔。潛龍也。虞翻曰。確、剛皃也。鄭曰。堅高之皃。按今易皆作確。攷釋文曰。說文云高至。𣪠辭。夫乾、確然示人易矣。釋文曰。說文云高至。皆不言說文作隺。是則陸所據易二皆作隺。而今本俗誤也。許意隺訓高至。塙訓堅不可拔。文言字作隺而義从塙。𣪠辭乃義如其字。"}]},"墽":{"expl":"磽也。从土敫聲。","rad":"土","fq":"口交切","vol":"13","py":"qiāo","duan":[{"e":"磽也。","n":"石部曰。磽者、礊石也。礊者、堅也。礉之義同磽。則兼謂土石堅？耳。其字亦作墝。何注公羊云。墝埆不生五穀曰不毛。"}]},"壚":{"expl":"剛土也。从土盧聲。","rad":"土","fq":"洛乎切","vol":"13","py":"lú","duan":[{"e":"黑剛土也。","n":"各本無黑字。依韵會則小徐有。尙書正義所引同。今補。釋名曰。土黑曰壚。盧然解散也。周禮草人。埴壚用豕。鄭云。埴壚、黏疏者。以黏釋埴。以疏釋壚。黑部曰。齊謂黑爲黸。古文作旅。許於黸得其義云黑而剛。則疏之義亦見矣。"}]},"㙚":{"expl":"赤剛土也。从土，觲省聲。","rad":"土","fq":"息營切","vol":"13","py":"xīnɡ","duan":[{"e":"赤剛土也。","n":"草人。凡糞種、騂剛用牛。故書騂爲挈。杜子春挈讀爲騂。謂地色赤而土剛强也。按馬部無？字。子春易字作解。必塙然易爲㙚字。而許用其說入說文也。然則相承作？又譌作騂者、乃大繆耳。"}]},"埴":{"expl":"黏土也。从土直聲。","rad":"土","fq":"常職切","vol":"13","py":"zhí","duan":[{"e":"黏土也。","n":"禹貢。厥土赤埴墳。周禮草人埴壚。攷工記。搏埴之工。孔傳、鄭注皆曰。埴、黏土也。釋名。土黃而細密曰埴。埴、膱也。黏昵如脂之膱也。按禹貢埴字、鄭本作戠而讀爲熾。熾、赤皃也。見禹貢音義及蜀都賦丹沙赩熾李注。又太平御覽三十七引東晉會稽謝沈古文尙書注。徐州土赤戠墳。戠音志。又禹貢正義曰。戠埴音義同。埴爲黏土。故土黏曰戠。葢孔本本亦作戠。惟孔釋戠爲黏土。鄭易戠爲熾。釋爲赤皃。見經文赤戠連讀爲異耳。據釋文則韋昭所注漢地理志亦作戠。而今漢書作埴。晉書成公綏天地賦云。海岱赤𡑌。華梁靑黎。何超音義𡑌尺志反。此又戠之加土㫄者也。戠𡑌？皆埴之異字。"}]},"唊":{"expl":"妄語也。从口夾聲。讀若莢。","rad":"口","fq":"古叶切","vol":"02","py":"jiá","duan":[{"e":"妄語也。","n":"廣韵。唊唊、多言也。"}]},"坴":{"expl":"土塊坴坴也。从土圥聲。讀若逐。一曰坴梁。","rad":"土","fq":"力竹切","vol":"13","py":"lù","duan":[{"e":"土凷坴坴也。","n":"坴坴、大凷之皃。"}]},"𡍦":{"expl":"土也。洛陽有大𡍦里。从土軍聲。","rad":"土","fq":"戶昆切","vol":"13","py":"hún","duan":[{"e":"土也。","n":"土葢凷之誤。集韵凷字亦作𡍦。類篇𡍦亦苦會切。墣也。葢自坴至堛倂重文六篆皆言凷。此土也二字淺人所改。"}]},"墣":{"expl":"塊也。从土菐聲。","rad":"土","fq":"匹角切","vol":"13","py":"pú","duan":[{"e":"凷也。","n":"吳語曰。㳙人疇枕王以墣。淮南書曰。土之勝水也。非以一墣塞江。"}]},"凷":{"expl":"墣也。从土，一屈象形。","rad":"土","fq":"苦對切","vol":"13","py":"kuài","duan":[{"e":"墣也。","n":"是曰轉注。喪服傳曰。寢苫枕凷。"}]},"堛":{"expl":"凷也。从土畐聲。","rad":"土","fq":"芳逼切","vol":"13","py":"bì","duan":[{"e":"凷也。","n":"釋言。凷、堛也。郭引枕王以堛。堛卽墣之異文。禮運蕢桴注曰。蕢讀爲凷。聲之誤也。凷、堛也。"}]},"堫":{"expl":"穜也。一曰内其中也。从土㚇聲。","rad":"土","fq":"子紅切","vol":"13","py":"zōnɡ","duan":[{"e":"穜也。","n":"穜者、埶也。堫者、以禾穜入土也。廣雅曰。䎫、𦔉也。卽堫、穜字之異體也。"}]},"塍":{"expl":"稻中畦也。从土朕聲。","rad":"土","fq":"食陵切","vol":"13","py":"chénɡ","duan":[{"e":"稻田中畦埓也。","n":"集韵、類篇、宋本作稻中畦也。今本及文𨕖注作稻田畦也。韵㑹作稻中畦埓也。今合訂之如此。畦、五十畞之介也。埓者、庳垣。亦所以爲畍。稻田中作介畫以蓄水。取義於此。謂之塍必言稻中者、禾黍不必爲此。惟稻必蓄水以養之。周禮稻人。以遂均水。以列舍水。鄭曰。遂、田首受水小溝也。列、田之畦埓也。開遂舍水於列中。按列讀如遮迾之迾。非人所行之畛陌也。許、鄭說正同。今四川謂之田繩子。江浙謂之田緪。緪亦繩也。西都賦。溝塍刻鏤。"}]},"坺":{"expl":"治也。一曰臿土謂之坺。《詩》曰：“武王載坺。”一曰塵皃。从土犮聲。","rad":"土","fq":"蒲撥切","vol":"13","py":"bá","duan":[{"e":"坺土也。","n":"坺字各本無。今補。厽下曰。絫坺土爲牆壁。凡初出於田爲坺土。稍治之乃爲凷。"}]},"坄":{"expl":"陶竈窻也。从土，役省聲。","rad":"土","fq":"營隻切","vol":"13","py":"yì","duan":[{"e":"匋竈窗也。","n":"匋各本作陶。今正。缶部曰。匋者、瓦器竈也。穴部曰。窗者、通空也。燒瓦器之竈上必通孔。謂之坄者、其火熒然而出也。士喪禮。爲垼於西牆下。東鄉。注云。垼、塊竈。旣夕記云。垼用塊。注云。塊、堛也。葢士喪之竈、土凷爲之。以煮沐浴者之潘水。不似人家廚竈。必令適爲之。且僅通孔可煮而已。故謂之坄。不謂之竈也。坄、禮經作垼。古文禮作役。"}]},"基":{"expl":"牆始也。从土其聲。","rad":"土","fq":"居之切","vol":"13","py":"jī","duan":[{"e":"牆始也。","n":"𨸏部曰。阯者、基也。此蒙基而釋之。牆始者、本義也。引申之爲凡始之偁。釋詁、周語、毛詩傳皆曰。基、始也。禮經古文借基爲期年字。"}]},"丅":{"expl":"底也。指事。","rad":"丄","fq":"胡雅切","vol":"01","py":"xià","duan":[{"e":"底也。","n":"底當作氐。广部曰。底者、山凥也。一曰下也。許氏解字多用轉注。轉注者、互訓也。底云下也。故下云底也。此之謂轉注。全書皆當以此求之。抑此底字當作氐。广部一曰下也四字。疑後人所綴。何者。許書無低字。日部昏下曰从氐省。氐者、下也。正與此下者氐也爲轉注。上、高也。下、氐也。高氐亦正相反相對。今本氐篆解云至也。亦當本作下也。如是正之。乃見許氏發揮轉注之恉。有好學深思者。當能心知其意也。"}]},"瑾":{"expl":"瑾瑜，美玉也。从玉堇聲。","rad":"玉","fq":"居隱切","vol":"01","py":"jǐn","duan":[{"e":"瑾瑜、","n":"逗。"}]},"嗑":{"expl":"多言也。从口盍聲。讀若甲。","rad":"口","fq":"候榼切","vol":"02","py":"kè","duan":[{"e":"多言也。从口。盍聲。讀若甲。","n":"𠊱榼切。八部。"}]},"垣":{"expl":"牆也。从土亘聲。","rad":"土","fq":"雨元切","vol":"13","py":"yuán","duan":[{"e":"牆也。","n":"此云垣者。牆也。渾言之。牆下日垣蔽也。析言之。垣蔽者、牆又爲垣之蔽也。垣自其大言之。牆自其高言之。"}]},"圪":{"expl":"牆高也。《詩》曰：“崇墉𡉛𡉛。”从土乞聲。","rad":"土","fq":"魚迄切","vol":"13","py":"yì","duan":[{"e":"牆高皃也。","n":"大雅皇矣曰。崇墉言言。傳曰。言言、高大也。又曰。崇墉仡仡。傳曰。仡仡猶言言也。依說文本作圪圪。"}]},"堵":{"expl":"垣也。五版爲一堵。从土者聲。","rad":"土","fq":"當古切","vol":"13","py":"dǔ","duan":[{"e":"垣也。","n":"儒行曰。儒有一畞之宫。環堵之室。注云。宫謂牆垣也。堵、面一堵也。面一堵者、謂面各一堵也。依鄭說堵與垣別。大氐散文則通。對文則別也。"}]},"壁":{"expl":"垣也。从土辟聲。","rad":"土","fq":"比激切","vol":"13","py":"bì","duan":[{"e":"垣也。","n":"釋名。壁、辟也。辟禦風寒也。按壁自其直立言之。"}]},"㙩":{"expl":"周垣也。从土尞聲。","rad":"土","fq":"力沼切","vol":"13","py":"liáo","duan":[{"e":"𠣘垣也。","n":"𠣘各本作周。今正。𠣘、帀也。周、密也。義異。𠣘垣謂垣之圍帀者也。西都賦曰。繚以周牆四百餘里。西京賦曰。繚亘綿聯。薛注。繚亘猶繞了也。按魏都賦亦曰。繚亘開囿。今本皆譌作繚垣。非也。繚亘雙聲字。"}]},"堨":{"expl":"壁間隙也。从土曷聲。讀若謁。","rad":"土","fq":"魚列切","vol":"13","py":"yè","duan":[{"e":"壁閒隙也。","n":"隙者、壁際也。壁際者、壁之釁也。亦曰堨。此古義也。今義堰也。讀同壅遏。後人所用俗字也。"}]},"埒":{"expl":"卑垣也。从土寽聲。","rad":"土","fq":"力輟切","vol":"13","py":"liè","duan":[{"e":"庳垣也。","n":"庳者、中伏舍也。引申之爲卑也。按廣韵引孟康云。等庳垣也。似孟氏所據爲長。等者、齊等也。卑垣延長而齊等若一。是之謂埒。引申之爲涯際之偁。如淮南道有形埒是也。爲回環之偁。如爾雅水潦所還埒丘、又馬埒是也。又爲相等之偁。如史記富埒天子之類是也。孟康語葢出漢書音義。今宜依以補等字。"}]},"堪":{"expl":"地突也。从土甚聲。","rad":"土","fq":"口含切","vol":"13","py":"kān","duan":[{"e":"地突也。","n":"突者、犬從穴中暫出也。因以爲坳突之偁。俗乃製凹凸字。地之突出者曰堪。淮南書曰。堪輿行雄以起雌。許注曰。堪、天道。輿、地道也。見文𨕖注。甘泉賦。屬堪輿以壁壘。張晏曰。堪輿、天地緫名也。按張說未安。堪言地高處無不勝任也。所謂雄也。輿言地下處無不居納也。所謂雌也。引申之、凡勝任皆曰堪。古叚戡？爲之。"}]},"堀":{"expl":"突也。《詩》曰：“蜉蝣堀閱。”从土，屈省聲。","rad":"土","fq":"苦骨切","vol":"13","py":"kū","duan":[]},"堂":{"expl":"殿也。从土尚聲。","rad":"土","fq":"徒郎切","vol":"13","py":"tánɡ","duan":[{"e":"殿也。","n":"殿者、擊聲也。叚借爲宫殿字者。釋宫室曰。殿、有殿鄂也。殿鄂卽禮記注之沂鄂。沂、說文作垠、作圻。釋名釋形體亦曰。臀、殿也。高厚有殿鄂也。古音？聲、斤聲、？聲互通。合音作幾、作畿。是以禮記彫幾謂有沂鄂。堂之所以偁殿者、正謂前有陛四緣皆高起。沂鄂㬎然。故名之殿。許以殿釋堂者、以今釋古也。古曰堂。漢以後曰殿。古上下皆偁堂。漢上下皆偁殿。至唐以後、人臣無有偁殿者矣。初學記謂殿之名、起於始皇紀曰作前殿。葉大慶攷古質疑。博引說苑諸書以證古有殿名。要其所引皆漢人所作書也。卽六韜亦豈眞周人書哉。"}]},"嗙":{"expl":"謌聲。嗙喻也。从口㫄聲。司馬相如說，淮南宋蔡舞嗙喻也。","rad":"口","fq":"補盲切","vol":"02","py":"bēnɡ","duan":[{"e":"訶聲。嗙喻也。从口。旁聲。","n":"補？切。十部。"}]},"垜":{"expl":"堂塾也。从土朵聲。","rad":"土","fq":"丁果切","vol":"13","py":"duǒ","duan":[{"e":"門堂孰也。","n":"門字孰字今補正。攷工記。門堂三之二。室三之一。鄭曰。門堂、門側之堂也。釋宫曰。門側之堂謂之塾。孫炎、郭樸皆曰。夾門堂也。堂無塾。門堂乃有塾。刪去門字、於制不可通矣。孰、經典皆作塾。以孰加土、猶以孰加火耳。謂之孰者、白虎通云。所以必有塾何。欲以飾門因取其名。明臣下當見於君。必孰思其事。是知其字。古作孰而已。後乃加之土也。謂之垛者何也。朵者、木下垂。門堂伸出於門之前後。略取其意。後代有朵殿。今俗謂門㒳邊伸出小牆曰垛頭。其遺語也。孰之制。於正堂之脩廣得三之二。其室於正堂之脩廣得三之一。北向堂者爲孰。得堂脩廣三之一。南向者亦爲孰。亦得堂脩廣三之一。故曰門堂三之二也。室三之一者、北向南向㒳孰之中共一室。"}]},"坫":{"expl":"屏也。从土占聲。","rad":"土","fq":"都念切","vol":"13","py":"diàn","duan":[{"e":"屛也。","n":"陳氏禮書曰。坫之別凡有四。記曰。反坫出尊。論語曰。邦君爲兩君之好有反坫。此反爵之坫也。記曰。崇坫康圭。此奠玉之坫也。記又曰。士於坫一。此庋食之坫也。士冠禮。爵弁、皮弁、緇布冠各一匴。執以待於西坫南。大射。將射。工遷於下。東坫之東南。士喪禮。牀？夷衾。𩜹於西坫南。旣夕禮。設棜於東堂下南順。齊於坫。此堂隅之坫也。爾雅曰。垝謂之坫。郭云。坫、㙐也。在堂隅。按㙐本作墆。高皃也。以土爲之。高可屛蔽。故許云屛也。其字俗作店。崔豹曰。店、置也。所以置貨鬻物也。"}]},"垷":{"expl":"涂也。从土見聲。","rad":"土","fq":"胡典切","vol":"13","py":"xiàn","duan":[{"e":"涂也。","n":"以下五涂字皆涂泥引申之義也。涂泥可以附物者也。故引伸之、用以附物亦曰涂。詩角弓曰。如塗塗附。傳曰。塗、泥也。附、箸也。按上涂謂泥。下涂附連讀謂箸。鄭箋則謂以塗塗木桴。涂附謂之垷。廣雅。挸、拭也。卽垷字之異也。"}]},"墐":{"expl":"涂也。从土堇聲。","rad":"土","fq":"渠吝切","vol":"13","py":"jìn","duan":[{"e":"涂也。","n":"內則曰。塗之以謹塗。注曰。謹當爲墐。聲之誤也。墐塗、塗有穰草也。按合和黍穰而塗之謂之墐塗。取乾則易擘也。"}]},"𡏲":{"expl":"仰涂也。从土旣聲。","rad":"土","fq":"其冀切","vol":"13","py":"xì","duan":[{"e":"卬涂也。","n":"卬各本作仰。今正。卬涂、舉首而涂之。郢人施廣領大袖以仰塗是也。周書杍材曰。旣勤垣墉。惟其塗墍茨。按以艸葢屋曰茨。塗墍茨者、涂其茨之下也。故必卬涂。標有梅傳。墍、取也。假樂傳。墍、息也。皆叚借字。"}]},"堊":{"expl":"白涂也。从土亞聲。","rad":"土","fq":"烏各切","vol":"13","py":"è","duan":[{"e":"白涂也。","n":"以白物涂白之也。周禮曰。其祧則守祧幽堊之。注云。幽讀爲黝。黝、黑也。堊、白也。爾雅曰。地謂之黝。牆謂之堊。郭云。黑飾地、白飾牆也。釋名曰。堊、亞也。亞、次也。先泥之。次以白灰飾之也。按謂涂白爲堊。因謂白土爲堊。古用蜃灰。周禮。共白盛之蜃。注云。謂飾牆使白之蜃也。今東萊用蛤。謂之叉灰云。"}]},"墀":{"expl":"涂地也。从土犀聲。《禮》：“天子赤墀。”","rad":"土","fq":"直泥切","vol":"13","py":"chí","duan":[{"e":"涂地也。","n":"巾部曰。？、墀地以巾捫之也。凡涂地爲墀。今因謂地爲墀矣。"}]},"墼":{"expl":"瓴適也。一曰未燒也。从土毄聲。","rad":"土","fq":"古歴切","vol":"13","py":"jī","duan":[{"e":"令適也。","n":"瓦部甓下曰。令甓也。按令甓卽令適也。甓適墼三字同韵。釋宫曰。瓴甋謂之甓郭云。㼾甎也。陳風。中唐有甓。傳曰。甓、令適也。字作令適、零嫡二音。加瓦者俗字也。㼾甎亦皆俗字。甎古衹作專。如斯干傳曰。瓦、紡專也。寸部專下曰。一曰紡專也。皆可證。陸德明云。字林作塼。此許、吕各因時作字書之例。許意在存古。吕意在宜今也。韋注吳語曰。員曰囷。方曰鹿。然則鹿專者、言其方正也。亦曰墼。"}]},"𡊄":{"expl":"埽除也。从土弁聲。讀若糞。","rad":"土","fq":"方問切","vol":"13","py":"fèn","duan":[{"e":"埽除也。","n":"？字曲禮作糞。少儀作拚。又皆作𢹔。糞卽華部之？字。與？音同義略同。拚其叚借字也。少儀曰。汎埽曰埽。埽席前曰拚。此析言之也。許以埽除釋？。以？釋埽。渾言之也。弟子職。旣拚漱。謂埽席前也。汎拚正席。謂廣？內外、不止席前也。小雅伐木箋。亦以灑𢹔釋洒埽。"}]},"噧":{"expl":"高气多言也。从口，蠆省聲。《春秋傳》曰：“噧言。”","rad":"口","fq":"訶介切","vol":"02","py":"xiè","duan":[{"e":"高气多言也。","n":"廣韵曰。高聲皃。又多言。"}]},"埽":{"expl":"棄也。从土从帚。","rad":"土","fq":"穌老切","vol":"13","py":"sǎo","duan":[{"e":"𡊅也。","n":"𡊅各本譌棄。今正。此二篆爲轉注也。"}]},"在":{"expl":"存也。从土才聲。","rad":"土","fq":"昨代切","vol":"13","py":"zài","duan":[{"e":"存也。","n":"存、恤問也。釋詁。徂、在、存也。在、存、察也。按虞夏書在訓察。謂在與伺音同。卽存問之義也。在之義古訓爲存問。今義但訓爲存兦之存。"}]},"坐":{"expl":"止也。从土，从畱省。土，所止也。此與畱同意。","rad":"土","fq":"但臥切","vol":"13","py":"zuò","duan":[{"e":"止也。","n":"止、下基也。引申爲住止。凡言坐落、坐罪是也。引申爲席地而坐。小雅。不遑啓處。傳曰。啓、跪。處、居也。古謂跪爲啓。謂坐爲凥、爲處。凥俗作居。引申謂凡止箸爲坐。"}]},"坁":{"expl":"箸也。从土氏聲。","rad":"土","fq":"諸氏切","vol":"13","py":"zhǐ","duan":[{"e":"箸也。","n":"韵會作箸止也。箸直略切、者字之叚借也。行之旣久。乃不可變矣。凡言者者、別事䛐也。有所箸之䛐也。故凡言箸、皆者引申之義。左傳昭廿九年。物乃坁伏。鬱湮不育。杜注。坁、止也。此坁字見於經者。而開成石經譌作坻。其義迥異。楚金所見左傳故未誤。尋其所由。葢唐初已有誤坻者。故釋文曰。坁音旨。又音丁禮反。後一音則已譌爲坻。凡字切丁禮者、皆氐聲也。今版本釋文及左傳及廣韵四紙皆作坻。坻行而坁廢矣。"}]},"塡":{"expl":"塞也。从土眞聲。","rad":"土","fq":"陟鄰切、待秊切","vol":"13","py":"tián","duan":[{"e":"𡫳也。","n":"𡫳各本作塞。塞、隔也。非其義也。𡫳下云窒也。窒下云？也。窴亦？也。塡與窴音義同。？之則堅固。其義引申爲久。大雅。倉兄塡兮。傳曰。塡、久也。常棣。烝也無戎。傳曰。烝、塡也。東山。烝在桑野。傳曰。烝、窴也。而爾雅釋詁則曰塵、久也。是塡窴塵三字音同。故鄭箋東山云。古者聲塡窴塵同也。塵爲叚借字。葢古經有作塵者。今新陳字作陳。非古也。而古音之存者也。詩詞內作鎭、亦是此字。"}]},"坦":{"expl":"安也。从土旦聲。","rad":"土","fq":"他但切","vol":"13","py":"tǎn","duan":[{"e":"安也。","n":"論語曰。君子坦蕩蕩。按魯讀爲坦湯湯。此如陳風子之湯兮傳曰。湯、蕩也。謂湯爲蕩之叚借字也。司馬相如賦叚壇爲坦。"}]},"坒":{"expl":"地相次比也。衞大夫貞子名坒。从土比聲。","rad":"土","fq":"毗至切","vol":"13","py":"bì","duan":[{"e":"地相次坒也。","n":"依小徐及玉篇、廣韵作次坒。大徐作次比。"}]},"堤":{"expl":"滯也。从土是聲。","rad":"土","fq":"丁礼切","vol":"13","py":"dǐ","duan":[{"e":"滯也。","n":"滯者、冰也。按此篆與坁篆音義皆同。國語曰。戾久將底。底箸滯淫。左傳曰。勿使有所壅閉湫底。杜云。底、滯也。釋詁底底皆訓止也。底字與坁堤字、音雖別而義略同。俗用堤爲隄、則非。"}]},"壎":{"expl":"樂器也。以土爲之，六孔。从土熏聲。","rad":"土","fq":"況袁切","vol":"13","py":"xūn","duan":[{"e":"樂器也。㠯土作。","n":"句。"}]},"封":{"expl":"爵諸矦之土也。从之从土从寸，守其制度也。公侯，百里；伯，七十里；子男，五十里。","rad":"土","fq":"府容切","vol":"13","py":"fēnɡ","duan":[{"e":"爵諸侯之土也。","n":"謂爵命諸侯以是土也。詩毛傳。之子、嫁子也。之事、祭事也。莊子之人也、卽是人也。然則之土言是土也。其義之土、故其字从之土。引申爲凡畛域之偁。大司徒注曰。封、起土畍也。封人注曰。聚土曰封。謂壝堳埒及小封疆也。冢人注曰。王公曰丘。諸臣曰封。又引申爲大也。又引申爲？固之偁。"}]},"叴":{"expl":"高气也。从口九聲。臨淮有叴猶縣。","rad":"口","fq":"巨鳩切","vol":"02","py":"qiú","duan":[{"e":"高气也。从口。九聲。","n":"巨鳩切。三部。詩叴矛、是此叴字。"}]},"壐":{"expl":"王者印也。所以主土。从土爾聲。","rad":"土","fq":"斯氏切","vol":"13","py":"xǐ","duan":[{"e":"王者之印也。","n":"印者、執政所持信也。王者所執則曰璽。按周禮貨賄用璽節注云。璽節主以通貨賄。璽節者、今之印章也。左傳。季武子璽書追而與公冶。皆非謂王者。葢古者尊卑通偁。至秦漢而後爲至尊之偁。故始皇本紀。乃爲璽書賜公子扶蘇。中車府令趙高行符璽事。蔡邕獨𣃔曰。皇帝六璽皆玉螭虎紐。許此語舉漢制也。"}]},"墨":{"expl":"書墨也。从土从黑，黑亦聲。","rad":"土","fq":"莫北切","vol":"13","py":"mò","duan":[{"e":"書墨也。","n":"聿下曰。所以書也。楚謂之聿。吳謂之不律。燕謂之弗。秦謂之筆。此云墨、書墨也。葢筆墨自古有之。不始於蒙恬也。箸於竹帛謂之書。竹木以桼。帛必以墨。用帛亦必不起於秦漢也。周人用璽書印章必施於帛。而不可施於竹木。然則古不專用竹木信矣。引申之爲晉於是始墨。肉食者無墨。爲貪以敗官爲墨。"}]},"垸":{"expl":"以桼和灰而䰍也。从土完聲。一曰補垸。","rad":"土","fq":"胡玩切","vol":"13","py":"huán","duan":[{"e":"㠯桼龢灰丸而䰍也。","n":"龢各本作和。今正。丸大徐無。今依小徐。桼者、木汁可以䰍物也。丸者、圜也。傾側而轉者。䰍者、䰍桼也。說詳桼部。灰者、燒骨爲灰也。玄應梵書音義曰。通俗文曰燒骨以漆曰垸。倉頡訓詁曰垸以漆和之。今中國言垸。江南言？。？音瑞。垸胡灌切。玉裁按許㯡下云桼垸。周禮巾車杜子春云。軟讀爲垸桼之桼。輪人注。鄭云丸漆之。葢以桼合和燒骨之灰。摶而丸之。以䰍擦物。丸與垸㬪韵爲訓。丸而䰍之。旣乾如沙磣不光潤。乃摩之。鄭所云丸漆之乾、乃以石摩平之也。旣摩乃復桼之。許於㯡下所云桼垸已復桼之也。如此數四。乃後𢾅丹雘。今時桼工亦略同此。垸或叚浣爲之。如角人注骨入桼浣者受之以量也。或叚睆爲之。如檀弓華而睆。孫炎云。睆、桼也。叔然乃"}]},"型":{"expl":"鑄器之法也。从土刑聲。","rad":"土","fq":"戶經切","vol":"13","py":"xínɡ","duan":[{"e":"鑄器之灋也。","n":"以木爲之曰模。以竹曰笵。以土曰型。引申之爲典？。叚借㓝字爲之。俗作𠛬。非是。詩毛傳屢云㓝、法也。又或叚形爲之。左傳引詩形民之力。而無醉飽之心。謂程量其力之所能爲而不過也。"}]},"埻":{"expl":"射臬也。从土𦎫聲。讀若準。","rad":"土","fq":"之允切","vol":"13","py":"zhǔn","duan":[{"e":"𡓑旳。","n":"各本無此二字。今補。木部臬下曰。䠶？旳也。此與爲轉注。亦有單言？者。旳、明也。亦有單言旳者。"}]},"塒":{"expl":"雞棲垣爲塒。从土時聲。","rad":"土","fq":"市之切","vol":"13","py":"shí","duan":[{"e":"雞棲於垣爲塒。","n":"釋宫。鑿垣而棲爲塒。王風傳同。按許意與古異。連雞棲於庳垣。不必鑿穴也。"}]},"城":{"expl":"以盛民也。从土从成，成亦聲。","rad":"土","fq":"氏征切","vol":"13","py":"chénɡ","duan":[{"e":"㠯盛民也。","n":"言盛者、如黍稷之在器中也。"}]},"墉":{"expl":"城垣也。从土庸聲。","rad":"土","fq":"余封切","vol":"13","py":"yōnɡ","duan":[{"e":"城垣也。","n":"皇矣。以伐崇墉。傳曰。墉、城也。崧高。以作爾庸。傳曰。庸、城也。庸墉古今字也。城者、言其中之盛受。墉者、言其外之牆垣具也。毛統言之。許析言之也。周易曰。乗其墉。又曰。公用射隼於高墉之上。"}]},"𡑢":{"expl":"城上女垣也。从土葉聲。","rad":"土","fq":"徒叶切","vol":"13","py":"dié","duan":[{"e":"城上女垣也。","n":"女之言小也。𨸏部陴下日。城上俾倪女牆也。？與陴異字而同義。左傳。堙之。環城傅於堞。杜曰。堞、女牆也。古之城以土。不若今人以專也。土之上閒加以專牆。爲之射孔。以伺非常。曰俾倪、曰陴、亦曰？。左傳。盧蒲嫳攻崔氏。崔氏堞其宫而守之。弗克。此謂於宫牆之上。又加俾倪也。"}]},"坎":{"expl":"陷也。从土欠聲。","rad":"土","fq":"苦感切","vol":"13","py":"kǎn","duan":[{"e":"陷也。","n":"陷者、高下也。高下者、高而入於下也。因謂阱謂坎。井部曰。阱者、大陷也。穴部曰。？、坎中更有坎也。易曰。坎、陷也。習坎、重險也。毛詩傳曰。坎坎、擊𡔷聲。按此謂坎坎爲竷竷之叚借字也。"}]},"嘮":{"expl":"嘮呶，讙也。从口勞聲。","rad":"口","fq":"敕交切","vol":"02","py":"chāo","duan":[{"e":"嘮呶、讙也。从口。勞聲。","n":"敕交切。二部。"}]},"墊":{"expl":"下也。《春秋傳》曰：“墊隘。”从土執聲。","rad":"土","fq":"都念切","vol":"13","py":"diàn","duan":[{"e":"下也。","n":"謂地之下也。臯陶謨曰。下民昏墊。因以爲凡下之偁。方言曰。凡柱而下曰㘿。屋而下曰墊。馬部云。騫、馬腹墊也。漢後用爲褺江縣字。"}]},"坻":{"expl":"小渚也。《詩》曰：“宛在水中坻。”从土氐聲。","rad":"土","fq":"直尼切","vol":"13","py":"chí","duan":[{"e":"小渚也。","n":"爾雅曰。小州曰渚。小渚曰沚。小沚曰坻。毛詩周南、秦傳曰。水中可居者曰州。渚、小州也。坻、小渚也。小渚曰沚。今按毛傳不應坻沚同訓。若云坻、小沚也。小渚曰沚。則於爾雅合。許水部渚下引爾雅小州曰渚。沚下云小渚也。皆與爾雅、毛傳同。則此小渚亦當作小沚明矣。坻者、水中可居之冣小者也。"}]},"㙷":{"expl":"下入也。从土㬎聲。","rad":"土","fq":"敕立切","vol":"13","py":"zhí","duan":[{"e":"下入也。","n":"此與下溼曰隰義略同。吳都賦曰。𡍪㙷鱗接。李注曰。𡍪㙷、枝柯相重㬪皃也。按太沖之𡍪㙷、卽許書之㞚㞏。楚立除立二切。"}]},"垎":{"expl":"水乾也。一曰堅也。从土各聲。","rad":"土","fq":"胡格切","vol":"13","py":"hè","duan":[{"e":"水乾也。","n":"乾音干。玉篇、廣韵皆作土乾也爲長。謂土中之水乾而無潤也。王逸九思。冰凍兮垎澤。自注。垎、竭也。寒而水澤竭成冰。按水澤竭所謂乾也。今楚辭作洛澤。廣韵、集韵十九鐸皆引冬冰兮𠗂澤。誤甚。"}]},"垐":{"expl":"以土增大道上。从土次聲。","rad":"土","fq":"疾資切","vol":"13","py":"cí","duan":[{"e":"㠯土增大道上。","n":"增、益也。此與茨同意。以艸次於屋上曰茨。以土次於道上曰垐。"}]},"增":{"expl":"益也。从土曾聲。","rad":"土","fq":"作滕切","vol":"13","py":"zēnɡ","duan":[{"e":"益也。","n":"益者、饒也。會下曰。曾、益也。是可叚曾爲之。"}]},"埤":{"expl":"增也。从土卑聲。","rad":"土","fq":"符支切","vol":"13","py":"pí","duan":[{"e":"增也。","n":"詩北門曰。政事一埤益我。傳曰。埤、厚也。此與會部朇、衣部裨音義皆同。凡从曾之字皆取加高之意。會部曰。曾者、益也。是其意也。凡从卑之字皆取自卑加高之意。所謂天道𧇾盈益謙。君子捊多益寡也。凡形聲中有會意者例此。"}]},"坿":{"expl":"益也。从土付聲。","rad":"土","fq":"符遇切","vol":"13","py":"fù","duan":[{"e":"益也。","n":"吕氏春秋。七月紀。坿牆垣。高注。坿讀如符。坿猶培也。十月紀。坿城郭。高注坿、益也。令高固也。按今多用附訓益。附乃附婁。讀步口切。非益義也。今附行而坿廢矣。"}]},"塞":{"expl":"隔也。从土从𡨄。","rad":"土","fq":"先代切","vol":"13","py":"sài","duan":[{"e":"隔也。","n":"𨸏部隔下云塞也。是爲轉注。俗用爲窒？字。而塞之義、？之形俱廢矣。廣韵曰。邊塞也。明堂位。四塞世告至。注云。四塞謂夷服、鎭服、蕃服、在四方爲蔽塞者。按鄭注所謂天子守在四夷也。戰國策。齊有長城巨防。足以爲塞。吕氏春秋。天下有九塞。所謂守在四竟也。邶風、庸風傳曰。塞、瘞也。塞、充實也。皆謂塞爲㥶之叚借字也。"}]},"圣":{"expl":"汝潁之閒謂致力於地曰圣。从土从又。讀若兔窟。","rad":"土","fq":"苦骨切","vol":"13","py":"kū","duan":[{"e":"汝潁之閒謂致力於地曰圣。","n":"此方俗殊語也。致力必以手。故其字从又土會意。"}]},"呶":{"expl":"讙聲也。从口奴聲。《詩》曰：“載號載呶。”","rad":"口","fq":"女交切","vol":"02","py":"náo","duan":[{"e":"讙聲也。从口。奴聲。","n":"女交切。古音在五部。"}]},"垍":{"expl":"堅土也。从土自聲。讀若臮。","rad":"土","fq":"其冀切","vol":"13","py":"jì","duan":[{"e":"堅土也。","n":"堅者、剛也。堅土、周禮所謂彊㯺。鄭云彊堅者是也。按㯺一作壏。管子。纑土之次曰五壏。五壏之狀、芬焉若穅以肥。說與鄭異。"}]},"埱":{"expl":"气出土也。一曰始也。从土叔聲。","rad":"土","fq":"昌六切","vol":"13","py":"chù","duan":[{"e":"气出土也。","n":"气之出土滃然。故埱與歜音義皆略同。引申爲凡气出之偁。或叚借椒爲埱。周頌曰。有飶其香。有椒其馨。傳曰。飶、芬香也。椒猶飶也。按椒沈作俶。尺叔反。沈說善矣。若作埱尤合。飶與埱皆謂香气突出觸鼻。非謂椒𦕼也。"}]},"埵":{"expl":"堅土也。从土𡍮聲。讀若朵。","rad":"土","fq":"丁果切","vol":"13","py":"duǒ","duan":[{"e":"堅土也。","n":"玉篇云。确也。"}]},"埐":{"expl":"地也。从土练聲。","rad":"土","fq":"子林切","vol":"13","py":"jīn","duan":[{"e":"地也。","n":"未詳。"}]},"埾":{"expl":"土積也。从土，从聚省。","rad":"土","fq":"才句切","vol":"13","py":"jù","duan":[{"e":"積土也。","n":"捊下曰。引埾也。引申爲凡聚之偁。各書多借爲聚字。白虎通。琮之爲言埾也。象萬物之宗埾也。今乃譌爲聖。"}]},"壔":{"expl":"保也。高土也。从土𠷎聲。讀若毒。","rad":"土","fq":"都皓切","vol":"13","py":"dǎo","duan":[{"e":"保也。","n":"保集韵、類篇作堡。俗字也。檀弓。公叔禺人遇負杖入保者息。月令。四鄙入保。注皆云。都邑小城曰保。許云。保謂之？。"}]},"培":{"expl":"培敦。土田山川也。从土咅聲。","rad":"土","fq":"薄回切","vol":"13","py":"péi","duan":[{"e":"培敦、","n":"逗。"}]},"埩":{"expl":"治也。从土爭聲。","rad":"土","fq":"疾郢切","vol":"13","py":"zhēnɡ","duan":[{"e":"治也。","n":"治土曰埩。廣韵曰。埩、魯城北門池也。公羊傳作爭。許水部作淨。"}]},"墇":{"expl":"擁也。从土章聲。","rad":"土","fq":"之亮切","vol":"13","py":"zhànɡ","duan":[{"e":"𢹬也。","n":"擁者、袌也。袌、許之抱字。謂圍抱以擁水也。疑當作邕。邕俗作雝。廣韵。墇、壅也。壅又雍之俗。此與障音同義小異。祭法、魯語鯀鄣洪水當作此墇字。韋昭曰。防也。"}]},"𡍫":{"expl":"遏遮也。从土則聲。","rad":"土","fq":"初力切","vol":"13","py":"cè","duan":[{"e":"遏遮也。","n":"未聞。"}]},"叱":{"expl":"訶也。从口七聲。","rad":"口","fq":"昌栗切","vol":"02","py":"chì","duan":[{"e":"訶也。","n":"訶、大言而怒也。"}]},"垠":{"expl":"地垠也。一曰岸也。从土艮聲。","rad":"土","fq":"語斤切","vol":"13","py":"yín","duan":[{"e":"地𡋳㖾也。","n":"咢字各本無。今補。玄應書卷八引圻、地圻咢也。文𨕖七發注引圻、地圻堮也。堮者、後人增土。咢則許書本然。淺人以咢爲怪。因或改或刪耳。按古者邊畍謂之垠咢。周禮典瑞、輈人、禮記郊特牲、少儀、哀公問五注皆云圻鄂。圻或作沂。張平子西京賦作垠鍔。注引許氏淮南子注曰。垠鍔、端厓也。甘泉賦李注曰。鄂、垠鄂也。按垠亦作圻。或作沂者叚借字。淮南書亦作㙬。玉篇曰。古文也。咢作鄂作鍔者、皆叚借字。或作？作？者、異體也。咢者、譁訟也。叚借之、毛詩鄂不韡韡。鄂葢本作咢。毛傳曰。咢猶咢咢然。言外發也。箋云。承華者曰咢。不當作柎。柎、咢足也。毛意本謂花瓣外出者。鄭牋則以詩上句爲華、不謂蒂。故謂咢爲下系於蒂、而上承華瓣者。毛云。"}]},"墠":{"expl":"野土也。从土單聲。","rad":"土","fq":"常衍切","vol":"13","py":"shàn","duan":[{"e":"野土也。","n":"野者、郊外也。野土者、於野治地除艸。鄭風。東門之壇。壇卽墠字。傳曰。除地町町者。町町、平意。左傳。楚公子圍逆女於鄭。鄭人請墠聽命。楚人曰。若野賜之。是委君況於草莽也。可見墠必在野也。鄭子產草舍不爲壇。壇卽墠字。可見墠必除草也。周書。爲三壇同墠。此壇高、墠下之證也。祭法。王立七廟。二祧。一壇一墠。注曰。封土曰壇。除地曰墠。此壇、墠之別也。築土曰封。除地曰禪。凡言封禪、亦是壇墠而已。經典多用壇爲墠。古音略同也。"}]},"垑":{"expl":"恃也。从土多聲。","rad":"土","fq":"尺氏切","vol":"13","py":"chǐ","duan":[{"e":"恃也。","n":"廣韵曰。垑、恃土地也。疑所見是完本。恃土地者、自多其土地。故字从多土。玉篇。垑、治土地名。恐有錯誤矣。釋詁曰。恀、恃也。謂自多之意。一說爾雅葢本作垑。故許同之。"}]},"壘":{"expl":"軍壁也。从土畾聲。","rad":"土","fq":"力委切","vol":"13","py":"lěi","duan":[{"e":"軍壁也。","n":"萬二千五百人爲軍。行軍所駐爲垣曰軍壁。壘之言絫也。壘與垒字音義皆別。周禮量人。營軍之壘舍。鄭云。軍壁曰壘。晉語趙鞅使尹鐸墮晉陽壘培。韋曰。壘墼曰培。"}]},"垝":{"expl":"毀垣也。从土危聲。《詩》曰：“乘彼垝垣。”","rad":"土","fq":"過委切","vol":"13","py":"ɡuǐ","duan":[{"e":"毀垣也。","n":"當曰垝垣、毀垣也。衞風氓曰。乗彼垝垣。傳曰。垝、毀也。下文云。毀、缺也。"}]},"圮":{"expl":"毀也。《虞書》曰：“方命圮族。”从土己聲。","rad":"土","fq":"符鄙切","vol":"13","py":"pǐ","duan":[{"e":"毀也。","n":"廣韵。岸毀。又覆也。"}]},"垔":{"expl":"塞也。《尚書》曰：“鯀垔洪水。”从土西聲。","rad":"土","fq":"於眞切","vol":"13","py":"yīn","duan":[{"e":"𡫳也。","n":"按此字古書多作堙、作陻。眞字乃廢矣。左傳井堙木刊服注、周語墮高堙庳韋注皆同此。"}]},"塹":{"expl":"阬也。一曰大也。从土斬聲。","rad":"土","fq":"七豔切","vol":"13","py":"qiàn","duan":[{"e":"阬也。","n":"江沅曰。阬、閬也。閬、門高大之皃。門之高大、阬之深廣相似也。故𨸏部阬閬也、卽緜傳之阬高貌。古毛詩葢作皋門有阬耳。塹則與阬之深廣同義。玉裁按江說是也。左氏傳注。塹、溝塹也。廣韵曰。遶城水也。史記李斯列傳。陗塹之勢異。塹乃漸之叚借。謂斗直者與陂陀者之勢不同也。"}]},"埂":{"expl":"秦謂阬爲埂。从土更聲。讀若井汲綆。","rad":"土","fq":"古杏切","vol":"13","py":"ɡěnɡ","duan":[{"e":"秦謂阬爲𡎩。","n":"秦謂阬塹曰埂。二字音略同。此與釋詁阬壑隍漮虛也同義。若廣韵曰吳人謂堤封爲埂。今江東語謂畦埒爲埂。此又別一方語。非許所謂。"}]},"壙":{"expl":"塹穴也。一曰大也。从土廣聲。","rad":"土","fq":"苦謗切","vol":"13","py":"kuànɡ","duan":[{"e":"塹穴也。","n":"謂塹地爲穴也。墓穴也。周禮方相氏。及墓入壙。以戈擊四隅。鄭曰。壙、穿地中也。"}]},"噴":{"expl":"吒也。从口賁聲。一曰鼓鼻。","rad":"口","fq":"普魂切","vol":"02","py":"pēn","duan":[{"e":"吒也。从口。賁聲。","n":"普䰟切。十三部。"}]},"塏":{"expl":"高燥也。从土豈聲。","rad":"土","fq":"苦亥切","vol":"13","py":"kǎi","duan":[{"e":"高燥也。","n":"燥者、乾也。左傳。請更諸爽塏者。杜曰。爽、明也。塏、燥也。"}]},"毀":{"expl":"缺也。从土，毇省聲。","rad":"土","fq":"許委切","vol":"13","py":"huǐ","duan":[{"e":"缺也。","n":"缺者、器破也。因爲凡破之偁。"}]},"壓":{"expl":"壞也。一曰塞補。从土厭聲。","rad":"土","fq":"烏狎切","vol":"13","py":"yā","duan":[{"e":"壞也。","n":"此與厂部厭義絕不同。而學者多不能辨。廣韵壓下云。鎭也、降也、笮也。乃皆厭之訓也。"}]},"壞":{"expl":"敗也。从土褱聲。","rad":"土","fq":"下怪切","vol":"13","py":"huài","duan":[{"e":"敗也。","n":"敗者、毀也。"}]},"坷":{"expl":"坎坷也。梁國寕陵有坷亭。从土可聲。","rad":"土","fq":"康我切","vol":"13","py":"kě","duan":[{"e":"坎坷也。","n":"坎坷雙聲。謂不平也。"}]},"㙤":{"expl":"𡍩也。从土虖聲。","rad":"土","fq":"呼訝切","vol":"13","py":"xià","duan":[{"e":"𡍩也。","n":"與缶部之罅音義皆同。"}]},"坼":{"expl":"裂也。《詩》曰：“不𡍩不疈。”从土㡿聲。","rad":"土","fq":"丑格切","vol":"13","py":"chè","duan":[{"e":"裂也。","n":"裂者、繒餘也。因以爲凡隙之偁。"}]},"坱":{"expl":"塵埃也。从土央聲。","rad":"土","fq":"於亮切","vol":"13","py":"yǎnɡ","duan":[{"e":"𪋻埃也。","n":"塵者、鹿行土也。引申爲土飛揚之偁。坱者、塵埃廣大之皃也。賈誼賦曰。大鈞播物兮坱圠無垠。王逸楚辭注曰。坱、霧昧皃。"}]},"塺":{"expl":"塵也。从土麻聲。","rad":"土","fq":"亡果切","vol":"13","py":"méi","duan":[{"e":"𪋻也。","n":"楚辭。愈氛霧其如塺。王逸曰。塺塵也。按塺之言蒙也。"}]},"塿":{"expl":"塺土也。从土婁聲。","rad":"土","fq":"洛矦切","vol":"13","py":"lǒu","duan":[{"e":"塺土也。从土。婁聲。","n":"洛侯切。四部。俗書附婁作培塿。"}]},"吒":{"expl":"噴也。叱怒也。从口乇聲。","rad":"口","fq":"陟駕切","vol":"02","py":"zhà","duan":[{"e":"噴也。叱怒也。","n":"此三字明叱噴吒三字互訓也。曲禮曰。母吒食。謂當食而叱怒他事。嫌於怒食。故注云嫌薄之。淮陰矦傳曰。項王喑噁叱吒。千人皆廢。"}]},"坋":{"expl":"塵也。从土分聲。一曰大防也。","rad":"土","fq":"房吻切","vol":"13","py":"fèn","duan":[{"e":"𪋻也。","n":"凡爲細末糝物若被物者皆曰坋。如左氏芥其雞。賈逵云。季氏擣芥爲末。播其雞翼。可以坌郈氏雞。五行志。棄灰於道者黥。孟康云。商鞅以棄灰於道必坋人。坋人必鬥。故設黥㓝以？其源。貨殖傳胃脯。晉灼云。燖羊胃以末椒薑坋之。皆是也。其音則後漢東夷傳注引說文蒲頓反爲長。今俗語如蓬去聲。按坋之言被也。"}]},"𡌦":{"expl":"塵也。从土非聲。","rad":"土","fq":"房未切","vol":"13","py":"fèi","duan":[{"e":"𪋻也。","n":"塵玉篇作塺。𡌦之言沸也。"}]},"埃":{"expl":"塵也。从土矣聲。","rad":"土","fq":"烏開切","vol":"13","py":"āi","duan":[{"e":"𪋻也。","n":"莊子曰。野馬也。塵埃也。生物之以息相吹也。絫言之曰塵埃。"}]},"㙠":{"expl":"塵埃也。从土殹聲。","rad":"土","fq":"烏雞切","vol":"13","py":"yī","duan":[{"e":"𪋻埃也。","n":"埃當从玉篇作㙠。㙠之言翳也。"}]},"垽":{"expl":"澱也。从土沂聲。","rad":"土","fq":"魚僅切","vol":"13","py":"yìn","duan":[{"e":"澱也。","n":"水部曰。澱、滓垽也。是二篆爲轉注。二字義同。音亦同部。"}]},"垢":{"expl":"濁也。从土后聲。","rad":"土","fq":"古厚切","vol":"13","py":"ɡòu","duan":[{"e":"濁也。","n":"濁、水部曰水名也。而濁穢字用之。"}]},"㙪":{"expl":"天陰塵也。《詩》曰：“㙪㙪其陰。”从土壹聲。","rad":"土","fq":"於計切","vol":"13","py":"yì","duan":[{"e":"天侌𪋻起也。","n":"依玉篇補起字較完。"}]},"坏":{"expl":"丘再成者也。一曰瓦未燒。从土不聲。","rad":"土","fq":"芳桮切","vol":"13","py":"pī","duan":[{"e":"丘一成者也。","n":"一各本作再。今正。水經注曰。河水又東逕成皋大伾山下。爾雅。山一成謂之伾。許愼、吕忱等並以爲丘一成也。孔安國以爲再成曰伾。據此、是俗以孔傳改易許書。今本非善長所見也。"}]},"垤":{"expl":"螘封也。《詩》曰：“鸛鳴于垤。”从土至聲。","rad":"土","fq":"徒結切","vol":"13","py":"dié","duan":[{"e":"螘封也。","n":"螘封者、其土似封畍之高。故謂之封。周禮注。聚土曰封。此亦其意也。詩毛傳曰。垤、螘冢也。按垤之言突也。"}]},"坥":{"expl":"益州部謂螾場曰坥。从土且聲。","rad":"土","fq":"七余切","vol":"13","py":"qū","duan":[{"e":"益州部謂螾場曰坥。","n":"郡國志。自漢中至犍爲屬國郡國十二。益州刺史部也。螾、丘蚓也。場失羊切。俗作塲。古作壤。穀梁傳。吐者外壤。食者內壤。徐邈、麋信皆作場。音傷。是也。螾場謂其外吐之土。方言曰。梁宋之閒蚍蜉䵓鼠之場謂之坻。螾場謂之坥。郭云。其糞曰坥。按醫書謂之蚓樓。今土面虛起者是也。許云益部、與梁宋之閒不合。疑方言宋當作益。"}]},"噊":{"expl":"危也。从口矞聲。","rad":"口","fq":"余律切","vol":"02","py":"yù","duan":[{"e":"危也。","n":"見釋詁。"}]},"埍":{"expl":"徒隸所居也。一曰女牢。一曰亭部。从土肙聲。","rad":"土","fq":"古泫切","vol":"13","py":"juǎn","duan":[{"e":"徒隷所凥也。","n":"徒隷、賤者偁。"}]},"𧷎":{"expl":"囚突出也。从土㕢聲。","rad":"土","fq":"胡八切","vol":"13","py":"kū","duan":[{"e":"囚突出也。从土。㕢聲。","n":"胡八切。十五部。"}]},"瘞":{"expl":"幽薶也。从土㾜聲。","rad":"土","fq":"於罽切","vol":"13","py":"yì","duan":[{"e":"幽薶也。","n":"艸部曰。薶者、瘞也。二篆爲轉注。幽者、隱也。隱而薶之也。絫言之則曰瘞薶。"}]},"堋":{"expl":"喪葬下土也。从土朋聲。《春秋傳》曰：“朝而堋。”《禮》謂之封，《周官》謂之窆。《虞書》曰：“堋淫于家。”","rad":"土","fq":"方鄧切","vol":"13","py":"bènɡ","duan":[{"e":"喪葬下土也。","n":"謂葬時下棺於壙中也。是名曰堋。"}]},"垗":{"expl":"畔也。爲四畤界，祭其中。《周禮》曰：“垗五帝於四郊。”从土兆聲。","rad":"土","fq":"治小切","vol":"13","py":"zhào","duan":[{"e":"畔也。","n":"畔者、田畍也。畍者、竟也。垗畔𩀱聲。"}]},"塋":{"expl":"墓也。从土，熒省聲。","rad":"土","fq":"余傾切","vol":"13","py":"yínɡ","duan":[{"e":"墓地。","n":"地各本作也。今正。玉篇及文𨕖李注引皆作地。漢書音義如淳曰。塋、𠣥田也。詩。蘝蔓于域。毛傳。域、塋也。按塋之言營也。營者、帀居也。經營其地而葬之。故其字从營。"}]},"墓":{"expl":"丘也。从土莫聲。","rad":"土","fq":"莫故切","vol":"13","py":"mù","duan":[{"e":"丘墓也。","n":"墓字今補。丘謂之虛。故曰丘墓。亦曰虛墓。檀弓曰虛墓之閒、未施哀於民而民哀是也。周禮有冢人、有墓大夫。鄭曰。𠣥、封土爲丘壠。象冢而爲之。墓、冢塋之地。孝子所思慕之處。然則丘自其高言。墓自其平言。渾言之則曰丘墓也。墓之言規模也。方言。凡葬而無墳謂之墓。所以墓謂之墲。注引漢劉向傳初陵之墲。今漢書作初陵之橅。"}]},"墳":{"expl":"墓也。从土賁聲。","rad":"土","fq":"符分切","vol":"13","py":"fén","duan":[{"e":"墓也。","n":"此渾言之也。析言之則墓爲平處。墳爲高處。故檀弓孔子曰。古者墓而不墳。邯鄲淳孝女曹娥碑曰。丘墓起墳。鄭注禮記曰。墓謂兆域。今之封塋也。土之高者曰墳。此其別也。方言曰。冢、秦晉之閒謂之墳。或謂之培。或謂之堬。或謂之埰。或謂之埌。或謂之壠。自關而東謂之丘。小者謂之塿。大者謂之丘。此又別國方言之不同也。墳之義多引申叚借用之。如厥土黑墳。公置之地、地墳。此引申之用也。如遵彼汝墳。借墳爲坋。周禮墳衍。借墳爲濆也。"}]},"壟":{"expl":"丘壠也。从土龍聲。","rad":"土","fq":"力歱切","vol":"13","py":"lǒnɡ","duan":[{"e":"丘壠也。","n":"高者曰丘壠。周禮注曰。冢、封土爲丘壠也。曲禮。適墓不登壟。注曰。爲其不敬。壟、冢也。墓、塋域。是則壠非謂墓畍也。郭注方言曰。有畍埒似耕壠以名之。此恐方語而非經義也。壟畝之偁、取高起之義引申之耳。"}]},"壇":{"expl":"祭場也。从土亶聲。","rad":"土","fq":"徒干切","vol":"13","py":"tán","duan":[{"e":"祭壇場也。","n":"祭法注。封土曰壇。除地曰墠。楚語。屛攝之位。壇場之所。韋注。屛攝、爲祭祀之位也。除地曰場。漢孝文帝紀。其廣增諸祀壇場珪幣。師古曰。築土爲壇。除地爲場。按墠卽場也。爲場而後壇之。壇之前又必除地爲場。以爲祭神道。故壇場必連言之。宋本作祭場也。無壇字。非是。若祭法壇與墠則異地。場有不壇者。壇則無不場也。"}]},"瑜":{"expl":"瑾瑜，美玉也。从玉俞聲。","rad":"玉","fq":"羊朱切","vol":"01","py":"yú","duan":[{"e":"瑾瑜也。","n":"凡合二字成文。如瑾瑜、玟瑰之類。其義旣舉於上字。則下字例不復舉。俗本多亂之。此也字之上有美玉二字是。"}]},"啐":{"expl":"驚也。从口卒聲。","rad":"口","fq":"七外切","vol":"02","py":"cuì","duan":[{"e":"驚也。从口。卒聲。","n":"七外切。十五部。儀禮今文以爲？酒字。"}]},"場":{"expl":"祭神道也。一曰田不耕。一曰治穀田也。从土昜聲。","rad":"土","fq":"直良切","vol":"13","py":"chánɡ","duan":[{"e":"祭神道也。","n":"也廣韵作處。玉篇引國語屛攝之位曰壇。今譌場壇之所除地曰場。"}]},"圭":{"expl":"瑞玉也。上圜下方。公執桓圭，九寸；矦執信圭，伯執躬圭，皆七寸；子執穀璧，男執蒲璧，皆五寸。以封諸矦。从重土。楚爵有執圭。","rad":"土","fq":"古畦切","vol":"13","py":"ɡuī","duan":[{"e":"瑞玉也。","n":"瑞者、以玉爲信也。"}]},"圯":{"expl":"東楚謂橋爲圯。从土巳聲。","rad":"土","fq":"與之切","vol":"13","py":"yí","duan":[{"e":"東楚謂橋。","n":"大史公曰。彭城以東。東海、吳、廣陵。此東楚也。史、漢。張良嘗閒從容步游下邳圯上。服䖍曰。汜音頤。楚人謂橋爲汜。按字當作圯。史、漢叚汜爲之。故服子愼讀如頤也。或云姚察見史記本有从土旁者。應劭曰。汜水之上、謂窮瀆無水之上也。則應說从水作汜爲合。與从土訓橋異。詳水部汜下。"}]},"垂":{"expl":"遠邊也。从土𠂹聲。","rad":"土","fq":"是爲切","vol":"13","py":"chuí","duan":[{"e":"遠邊也。","n":"？部曰。邊者、行？崖也。？者、遠邊也。崖者、高邊也。邊本謂行於？崖。因之？崖有遠邊高邊之偁。厓有山邊之偁矣。逍遙游。翼若？天之雲。崔云。？猶邊也。其大如天一面雲也。漢書。千金之子、坐不？堂。謂坐不於堂之邊也。？本謂遠邊。引申之、凡邊皆曰？。俗書邊？字作？。乃由用？爲𠂹。不得不用？爲？矣。𨸏部曰。？、危也。則無邊義。"}]},"塗":{"expl":"泥也。从土涂聲。","rad":"土","fq":"同都切","vol":"13","py":"tú","duan":[]},"塓":{"expl":"塗也。从土冥聲。","rad":"土","fq":"莫狄切","vol":"13","py":"mì","duan":[]},"埏":{"expl":"八方之地也。从土延聲。","rad":"土","fq":"以然切","vol":"13","py":"yán","duan":[]},"埸":{"expl":"疆也。从土易聲。","rad":"土","fq":"羊益切","vol":"13","py":"yì","duan":[]},"境":{"expl":"疆也。从土竟聲。經典通用竟。","rad":"土","fq":"居領切","vol":"13","py":"jìnɡ","duan":[]},"唇":{"expl":"驚也。从口辰聲。","rad":"口","fq":"側鄰切","vol":"02","py":"zhēn","duan":[{"e":"驚也。","n":"後人以震字爲之。"}]},"塾":{"expl":"門側堂也。从土孰聲。","rad":"土","fq":"殊六切","vol":"13","py":"shú","duan":[]},"细":{"expl":"耕也。从土豤聲。","rad":"土","fq":"康很切","vol":"13","py":"kěn","duan":[]},"塘":{"expl":"隄也。从土唐聲。","rad":"土","fq":"徒郎切","vol":"13","py":"tánɡ","duan":[]},"坳":{"expl":"地不平也。从土幼聲。","rad":"土","fq":"於交切","vol":"13","py":"āo","duan":[]},"壒":{"expl":"塵也。从土蓋聲。","rad":"土","fq":"於蓋切","vol":"13","py":"ài","duan":[]},"墜":{"expl":"陊也。从土隊聲。古通用䃍。","rad":"土","fq":"直類切","vol":"13","py":"zhuì","duan":[]},"塔":{"expl":"西域浮屠也。从土荅聲。","rad":"土","fq":"土盍切","vol":"13","py":"tǎ","duan":[]},"坊":{"expl":"邑里之名。从土方聲。古通用埅。","rad":"土","fq":"府良切","vol":"13","py":"fānɡ","duan":[]},"垚":{"expl":"土高也。从三土。凡垚之屬皆从垚。","rad":"垚","fq":"吾聊切","vol":"13","py":"yáo","duan":[{"e":"土高皃。","n":"依韵會所據本。與廣韵合。"}]},"堯":{"expl":"高也。从垚在兀上，高遠也。","rad":"垚","fq":"吾聊切","vol":"13","py":"yáo","duan":[{"e":"高也。","n":"堯本謂高。陶唐氏以爲號。白虎通曰。堯猶嶢嶢。嶢嶢、至高之皃。按焦嶢、山高皃。見山部。堯之言至高也。舜、山海經作俊。俊之言至大也。皆生時臣民所偁之號。非謚也。"}]},"吁":{"expl":"驚也。从口于聲。","rad":"口","fq":"況于切","vol":"02","py":"xū","duan":[{"e":"驚也。从口。亏聲。","n":"況于切。五部。按此篆當刪。說見亏部。"}]},"堇":{"expl":"黏土也。从土，从黃省。凡堇之屬皆从堇。","rad":"堇","fq":"巨斤切","vol":"13","py":"qín","duan":[{"e":"黏土也。","n":"內則。塗之以謹塗。鄭曰。謹當爲墐。聲之誤也。墐塗、塗有穰草也。按鄭注墐當爲堇。轉寫者誤加土耳。玉篇引禮堇涂。是希馮時不誤也。鄭謂土帶穰曰堇。許說不尒。葢土性黏者。與埴異字同義也。"}]},"艱":{"expl":"土難治也。从堇艮聲。","rad":"堇","fq":"古閑切","vol":"13","py":"jiān","duan":[{"e":"土難治也。","n":"引申之、凡難理皆曰艱。按許書無？字。疑古艱卽今？字。豤亦艮聲也。"}]},"里":{"expl":"居也。从田从土。凡里之屬皆从里。","rad":"里","fq":"良止切","vol":"13","py":"lǐ","duan":[{"e":"凥也。","n":"鄭風。無踰我里。傳曰。里、居也。二十五家爲里。周禮載師廛里。鄭云。廛里者、若今云邑居矣。里、居也。縣師郊里。鄭云。郊里、郊所居也。遺人鄉里。鄭云。鄉里、鄉所居也。遂人曰。五家爲鄰。五鄰爲里。榖梁傳曰。古者三百步爲里。毛詩亦借里爲悝。悝、病也。"}]},"釐":{"expl":"家福也。从里𠩺聲。","rad":"里","fq":"里之切","vol":"13","py":"lí","duan":[{"e":"家福也。","n":"家福者、家居獲祐也。易曰。積善之家。必有餘慶。漢孝文帝紀。詔曰。今吾聞祠官祝釐。皆歸福於朕躬。如淳曰。釐、福也。賈誼傳受釐宣室是也。如說冣合。應劭注釐爲祭餘肉。失之。師古直謂釐爲禧之叚借字。禧與釐雖同在古音弟一部。然義各有當。釐字从里。里者、家居也。故許釋爲家福。與禧訓禮吉不同。春秋三經僖公、史記作釐公。叚借字耳。有叚釐爲氂者。經解云差若毫氂、或作釐是也。有叚釐爲賚者。大雅釐爾女士傳曰。釐、予也。釐爾圭瓚傳曰。釐、賜也。有叚釐爲理者。堯典允釐百工是也。"}]},"野":{"expl":"郊外也。从里予聲。","rad":"里","fq":"羊者切","vol":"13","py":"yě","duan":[{"e":"郊外也。","n":"邑部曰。歫國百里曰郊。冂部曰。邑外謂之郊。郊外謂之野。野外謂之林。林外謂之冂。詩召南、邶風傳皆曰。郊外曰野。鄭風傳曰。野、四郊之外也。論語。質勝文則野。包咸曰。野如野人。言鄙略也。"}]},"田":{"expl":"陳也。樹穀曰田。象四囗。十，阡陌之制也。凡田之屬皆从田。","rad":"田","fq":"待秊切","vol":"13","py":"tián","duan":[{"e":"敶也。","n":"各本作陳。今正。敶者、列也。田與敶古皆音陳。故以㬪韵爲訓。取其敶列之整齊謂之田。凡言田田者、卽陳陳相因也。陳陳當作敶敶。陳敬仲之後爲田氏。田卽陳字。叚田爲陳也。"}]},"町":{"expl":"田踐處曰町。从田丁聲。","rad":"田","fq":"他頂切","vol":"13","py":"tīnɡ","duan":[{"e":"田踐處曰町。","n":"玉裁按此踐字疑淺人所增。廣韵靑韵注曰田處。迥韵注曰田塸。塸者、俗區字。田處者、謂人所田之處。淺人以二字古奧。乃因下文町疃爲禽獸踐處、妄增之。左傳。町原防。杜曰。原防不得方正如井田。別爲小頃町。賈逵曰。原防之地。九夫爲町。三町而當一井。急就篇頃町畍畞。顏注。平地爲町。一曰町、治田處也。西京賦編町成篁。薛注。町謂𤱶畞也。釋名州國篇曰。鄭、町也。其地多平。町町然也。論衡。町町若荆軻之廬。詩毛傳曰。墠、除地町町者。皆謂平坦。於踐義不相涉。"}]},"𤲬":{"expl":"城下田也。一曰𤲬，郤也。从田耎聲。","rad":"田","fq":"而緣切","vol":"13","py":"ruán","duan":[{"e":"城下田也。","n":"所謂附郭之田也。張晏云。城？地也。"}]},"疇":{"expl":"耕治之田也。从田，象耕屈之形。","rad":"田","fq":"直由切","vol":"13","py":"chóu","duan":[{"e":"耕治之田也。","n":"耕者、𤛿也。𤛿其田而治之。其田曰𤲮。有謂麻田曰𤲮者。劉向說苑、蔡邕月令章句、韋昭國語注、如淳漢書注同。此別爲一說。非許義也。有謂𤲮爲畍埒小畔際者。劉逵蜀都注、張載魏都注之說。亦非許義。許謂耕治之田爲𤲮。耕治必有耦。且必非一耦。故賈逵注國語曰。一井爲𤲮。杜預注左傳曰。並畔爲𤲮。並畔則二井也。引申之、高注國策、韋注漢書。𤲮、類也。王逸注楚辝。二人爲匹。四人爲𤲮。張晏注漢書。𤲮、等也。如淳曰。家業世世相傳爲𤲮。攷國語。人與人相𤲮。家與家相𤲮。戰國策曰。夫物各有𤲮。漢書曰。𤲮人子弟。𤲮其爵邑。王粲賦。顯敞寡𤲮。曹植賦。命𤲮嘯侣。葢自唐以前無不用从田之𤲮。絕無用从人之儔訓類者。此古今之變。不可不知也。楊"}]},"疁":{"expl":"燒穜也。《漢律》曰：“疁田茠艸。”从田翏聲。","rad":"田","fq":"力求切","vol":"13","py":"liú","duan":[{"e":"燒穜也。","n":"篇、韵皆云。田不耕、火種也。謂焚其艸木而下種。葢治山田之法爲然。史記曰。楚越之地或火耕。杜甫夔府詩。燒畬度地偏。"}]},"嘵":{"expl":"懼也。从口堯聲。《詩》曰：“唯予音之嘵嘵。”","rad":"口","fq":"許么切","vol":"02","py":"xiāo","duan":[{"e":"懼聲也。","n":"豳風毛傳曰。嘵嘵、懼也。"}]},"畬":{"expl":"三歲治田也。《易》曰：“不葘，畬田。”从田余聲。","rad":"田","fq":"以諸切","vol":"13","py":"yú","duan":[{"e":"二歲治田也。","n":"二各本作三。今正。周易音義云。畬、馬曰田三歲。說文云二歲治田。此許作二之證。攷釋地曰。一歲曰葘。二歲曰新田。三歲曰畬。小雅、周頌毛傳同。馬融、孫炎、郭樸皆同。鄭注禮記坊記、許造說文、虞翻注易无妄皆云二歲曰畬。許全書多宗毛公。而意有未安者則不從。此其一也。葘、艸部云反耕田也。反耕者、初耕反艸。一歲爲然。二歲則用力漸舒矣。畬之言舒也。三歲則爲新田。"}]},"㽥":{"expl":"和田也。从田柔聲。","rad":"田","fq":"耳由切","vol":"13","py":"róu","duan":[{"e":"龢田也。","n":"考工記車人。爲耒。堅地欲直庛。柔地欲句庛。地官草人。墳壤用豕。鄭曰。墳壤、潤解也。曰柔地、曰潤解皆龢田之謂。對剛土而言。"}]},"畸":{"expl":"殘田也。从田奇聲。","rad":"田","fq":"居宜切","vol":"13","py":"jī","duan":[{"e":"𣧻田也。","n":"𣧻各本作殘。今正。殘者、賊也。𣧻者、禽獸所食餘也。因之凡餘謂之𣧻。今則殘行而𣧻廢矣。殘田者、餘田不整齊者也。凡奇零字皆應於畸引申用之。今則奇行而畸廢矣。"}]},"㽨":{"expl":"殘田也。《詩》曰：“天方薦㽨。”从田差聲。","rad":"田","fq":"昨何切","vol":"13","py":"cuó","duan":[{"e":"𣧻薉田也。","n":"薉字依集韵、類篇、韵會所據補。𣧻而且蕪之田也。是曰㽨。"}]},"畮":{"expl":"六尺爲步，步百爲畮。从田𣫭聲。","rad":"田","fq":"莫厚切","vol":"13","py":"mǔ","duan":[{"e":"六尺爲步。步百爲畮。","n":"司馬法如是。王制曰。方一里者爲田九百畮。謂方里而井。"}]},"甸":{"expl":"天子五百里地。从田，包省。","rad":"田","fq":"堂練切","vol":"13","py":"diàn","duan":[{"e":"天子五百里內田。","n":"禹貢。五百里甸服。周語曰。先王之制。邦內甸服。韋注云。邦內、謂天子畿內千里之地。商頌曰。邦畿千里。惟民所止。王制曰。千里之內曰甸。京邑在其中央。故夏書曰。五百里甸服。則古今同矣。甸、王田也。服、服其職業也。自商以前、邦畿內爲甸服。武王克殷。周公致大平。因禹所弼除甸內。更制天下爲九服。千里之內謂之王畿。王畿之外曰侯服。侯服之外曰甸服。祭謀父諫穆王稱先王之制。猶以王畿爲甸服者。甸古名。世俗所習也。故周襄王謂晉文公曰。昔我先王之有天下也、規方千里以爲甸服是也。周禮亦以蠻服爲要服。足以相況也。按周制王畿千里。不在九服。而亦未嘗不從古曰甸服也。若小司徒九夫爲井。四井爲邑。四邑爲丘。四丘爲甸。鄭云。甸之言"}]},"畿":{"expl":"天子千里地。以遠近言之，則言畿也。从田，幾省聲。","rad":"田","fq":"巨衣切","vol":"13","py":"jī","duan":[{"e":"天子千里地。","n":"卽天子五百里內田也。五百里自其一面言。千里自其四面言。爲方百里者百也。商頌。邦畿千里。傳曰。畿、疆也。大司馬九畿注曰。畿猶限也。"}]},"畦":{"expl":"田五十畝曰畦。从田圭聲。","rad":"田","fq":"戶圭切","vol":"13","py":"qí","duan":[{"e":"田五十畮曰畦。","n":"離騷。畦畱夷與揭車。王逸注。五十畞曰畦。蜀都賦劉注曰。楚辭倚沼畦瀛。王逸曰。瀛、澤中也。班固以爲畦、田五十畞也。此葢班固釋畦畱夷之語。今俗本文𨕖逸之。按孟子曰。圭田五十畞。然則畦从圭田會意兼形聲與。又用爲畦畛。史記。千畦薑韭。韋昭曰。畦猶壟也。"}]},"畹":{"expl":"田三十畝也。从田宛聲。","rad":"田","fq":"於阮切","vol":"13","py":"wǎn","duan":[{"e":"田三十畮曰畹。","n":"大徐本三作二。誤。魏都賦。下畹高堂。張注云。班固曰畹、三十畞也。此葢孟堅離騷章句滋蘭九畹之解也。王注乃云十二畞曰畹。或曰田之長爲畹。恐非是。"}]},"畔":{"expl":"田界也。从田半聲。","rad":"田","fq":"薄半切","vol":"13","py":"pàn","duan":[{"e":"田界也。","n":"田界者、田之竟處也。左傳。子產曰。行無越思。如農之有畔、其過鮮矣。一夫百畞、則畔爲百畞之界也。引申爲凡界之偁。或叚泮爲之。氓詩曰。隰則有泮。傳曰。泮、坡也。坡卽陂。箋云。泮讀爲畔。畔、涯也。經典多借爲叛字。論語。佛？以中牟畔。大雅。無然畔援。傳曰。無是畔道。無是援取。"}]},"嘖":{"expl":"大呼也。从口責聲。","rad":"口","fq":"士革切","vol":"02","py":"zé","duan":[{"e":"大呼也。","n":"呼當作嘑。廣韵。㗲嘖、叫也。左傳定四年。嘖有煩言。"}]},"畍":{"expl":"境也。从田介聲。","rad":"田","fq":"古拜切","vol":"13","py":"jiè","duan":[{"e":"竟也。","n":"竟俗本作境。今正。樂曲盡爲竟。引申爲凡邊竟之偁。界之言介也。介者、畫也。畫者、介也。象田四界。聿所以畫之。介界古今字。爾雅曰。疆、界、垂也。按垂、遠邊也。"}]},"㽘":{"expl":"境也。一曰陌也。趙魏謂陌爲㽘。从田亢聲。","rad":"田","fq":"古郎切","vol":"13","py":"ɡǎnɡ","duan":[{"e":"竟也。","n":"竟俗本作境。今正。"}]},"畷":{"expl":"兩陌閒道也，廣六尺。从田叕聲。","rad":"田","fq":"陟劣切","vol":"13","py":"zhuì","duan":[{"e":"㒳百閒道也。","n":"百者、百夫洫上之涂也。兩百夫之閒而有洫。洫上有涂。兩千夫之閒而有澮。澮上有道。所謂阡也。洫橫則澮縱。涂橫則道縱。故道在中縱。而左右各十涂皆橫。是謂兩陌閒道。是之謂畷。郊特牲。饗農及郵表畷。注云。郵表畷、謂田畯所以督約百姓於井閒之處。引詩爲下國畷郵。按畷之言綴也。眾涂所綴也。於此爲田畯督約百姓之處。若街彈室者然。曰郵表畷。"}]},"畛":{"expl":"井田閒陌也。从田㐱聲。","rad":"田","fq":"之忍切","vol":"13","py":"zhěn","duan":[{"e":"井田閒百也。","n":"井田閒者、謂十夫閒也。兩十夫之閒猶井閒也。徑畛涂道路皆可謂之陌阡。故曰井田閒陌。遂人曰。十夫有溝。溝上有畛。周頌曰。徂隰徂畛。毛傳曰。畛、埸也。按埸者、疆埸也。信南山疆埸有瓜是也。古衹作易。左傳曰。封畛土略。謂疆界。"}]},"畤":{"expl":"天地五帝所基址，祭地。从田寺聲。右扶風有五畤。好畤、鄜畤，皆黃帝時祭。或曰秦文公立也。","rad":"田","fq":"周市切","vol":"13","py":"zhì","duan":[{"e":"天地五帝所基止祭地也。","n":"止依韵會正。下基也。以基止釋畤。以曡韵爲訓也。所基止祭地謂祭天地五帝者。立基止於此而祭之之地也。畤不見於經。秦人因周制垗五帝於四郊。依附爲之。垗字音譌。遂製畤字耳。考封禪書。秦襄公居西垂。作西畤。祠白帝。其後文公都汧。作鄜畤。郊祭白帝。其後德公居雍。宣公作密畤於渭南。祭靑帝。靈公作吳陽上畤。祭黃帝。作下畤。祭炎帝。獻公作畦畤櫟陽。祀白帝。漢高祖立黑帝祠。命曰北畤。按密上下三畤及鄜畤及北畤、謂之雍五畤。祭靑黃赤白黑五帝之地也。先言天地者、秦時謂五帝卽天地。故曰唯雍四畤。上帝爲尊。秦之郊見卽祭畤也。"}]},"略":{"expl":"經略土地也。从田各聲。","rad":"田","fq":"烏約切","vol":"13","py":"lüè","duan":[{"e":"經略土地也。","n":"昭七年左傳。芋尹無宇曰。天子經略。諸侯正封。古之制也。杜注。經營天下。略有四海。故曰經略。正封。封疆有定分也。禹貢曰。嵎夷旣略。凡經界曰略。左傳曰。吾將略地。又曰。略基阯。引申之、規取其地亦曰略地。几舉其要而用功少皆曰略。略者對詳而言。"}]},"當":{"expl":"田相值也。从田尚聲。","rad":"田","fq":"都郎切","vol":"13","py":"dānɡ","duan":[{"e":"田相値也。","n":"値者、持也。田與田相持也。引申之、凡相持相抵皆日當。報下曰當辠人也。是其一耑也。流俗妄分平去二音。所謂無事自擾。"}]},"畯":{"expl":"農夫也。从田夋聲。","rad":"田","fq":"子峻切","vol":"13","py":"jùn","duan":[{"e":"農夫也。","n":"釋言曰。畯、農夫也。孫云。農夫、田官也。詩七月。田畯至喜。傳曰。畯、田大夫也。周禮籥章。以樂田畯。注。鄭司農云。田畯、古之先敎田者。按田畯、敎田之官。亦謂之田。月令。命田舍東郊。鄭曰。田謂田畯。主農之官也。亦謂之農。郊特牲。大蜡饗農。鄭曰。農、田畯也。田畯敎田之時。則親而尊之。詩三言田畯至喜是也。死而爲神則祭之。周禮之樂田畯、大蜡饗農是也。"}]},"甿":{"expl":"田民也。从田亡聲。","rad":"田","fq":"武庚切","vol":"13","py":"ménɡ","duan":[{"e":"田民也。","n":"甿爲田民。農爲耕人。其義一也。民部曰。氓、民也。此从田。故曰田民也。唐人諱民。故氓之蚩蚩、周禮以下劑致氓、石經皆改爲甿。古衹作萌。故許引周禮以興耡利萌。葢古本如是。鄭云。變民言萌。異外內也。萌猶懵懵無知貌。"}]},"疄":{"expl":"轢田也。从田粦聲。","rad":"田","fq":"良刃切","vol":"13","py":"lìn","duan":[{"e":"轢田也。","n":"轢、車所踐也。子虚賦。掩兔轔鹿。字从車。上林賦。車徒之所閵轢。又叚閵爲之。足部曰。蹸、轢也。義相近。"}]},"嗷":{"expl":"眾口愁也。从口敖聲。《詩》曰：“哀鳴嗷嗷。”","rad":"口","fq":"五牢切","vol":"02","py":"áo","duan":[{"e":"眾口愁也。","n":"董仲舒傳。嚻嚻苦不足。食貨志。天下謷謷。陳湯傳。熬熬苦之。皆同音假借字也。"}]},"畱":{"expl":"止也。从田丣聲。","rad":"田","fq":"力求切","vol":"13","py":"liú","duan":[{"e":"止也。","n":"稽下曰。稽、畱止也。"}]},"畜":{"expl":"田畜也。《淮南子》曰：“玄田爲畜。”","rad":"田","fq":"丑六切","vol":"13","py":"chù","duan":[{"e":"田畜也。","n":"田畜謂力田之蓄積也。貨殖列傳曰。富人爭奢侈。而任氏獨折節爲儉。力田畜。田畜人爭取賤賈。任氏獨取貴善。非田畜所出弗衣食。艸部曰。蓄、積也。畜與蓄義略同。畜从田。其源也。蓄从艸。其委也。俗用畜爲六嘼字。古叚爲好字。如說苑尹逸對成王曰。民善之則畜也。不善則讎也。晏子對景公曰。畜君何尤。畜君者、好君也。謂畜卽好之同音叚借也。"}]},"疃":{"expl":"禽獸所踐處也。《詩》曰：“町疃鹿場。”从田童聲。","rad":"田","fq":"土短切","vol":"13","py":"tuǎn","duan":[{"e":"禽獸所踐處也。","n":"踐者、𡳐也。獸足蹂地曰厹。其所蹂之處曰疃。本不專謂鹿。詩則言鹿而已。"}]},"畼":{"expl":"不生也。从田昜聲。","rad":"田","fq":"丑亮切","vol":"13","py":"chànɡ","duan":[{"e":"不生也。","n":"今之暢葢卽此字之隷變。詩。文茵暢轂。傳曰。暢轂、長轂也。月令。命之曰暢月。注曰。暢、充也。葢皆義之相反而相生者也。"}]},"畕":{"expl":"比田也。从二田。凡畕之屬皆从畕。","rad":"畕","fq":"居良切","vol":"13","py":"jiānɡ","duan":[{"e":"比田也。","n":"比、密也。二人爲从。反从爲比。比田者、㒳田密近也。"}]},"畺":{"expl":"界也。从畕；三，其界畫也。","rad":"畕","fq":"居良切","vol":"13","py":"jiānɡ","duan":[{"e":"界也。","n":"七月。萬壽無疆。傳曰。疆、竟也。田部曰。界、竟也。然則畺界義同。竟境正俗字。信南山。我疆我理。傳曰。疆、畫經界也。理、分地理也。緜曰。乃疆乃理。江漢曰。于疆于理。其義皆同。經界出於人爲。地理必因地阞。二者必相因而至。不知地阞則水不行。"}]},"黃":{"expl":"地之色也。从田从炗，炗亦聲。炗，古文光。凡黃之屬皆从黃。","rad":"黃","fq":"乎光切","vol":"13","py":"huánɡ","duan":[{"e":"地之色也。","n":"玄者、幽遠也。則爲天之色可知。易曰。夫玄黃者、天地之襍也。天玄而地黃。"}]},"䵌":{"expl":"赤黃也。一曰輕易人䵌姁也。从黃夾聲。","rad":"黃","fq":"許兼切","vol":"13","py":"xiān","duan":[{"e":"赤黃色也。","n":"赤黃者、赤色敝而黃也。色字依類篇補。"}]},"䵎":{"expl":"黃黑色也。从黃耑聲。","rad":"黃","fq":"他耑切","vol":"13","py":"tuān","duan":[{"e":"黑黃色也。","n":"黑黃各本作黃黑。疑當作黑黄、黑色之敝而黃也。詩。我馬玄黃。傳曰。玄馬病則黃。正此意。若黃黑則士克水之色。謂之駵黃。"}]},"䵋":{"expl":"青黃色也。从黃有聲。","rad":"黃","fq":"呼辠切","vol":"13","py":"wěi","duan":[{"e":"靑黃色也。","n":"靑色敝而黃也。"}]},"唸":{"expl":"㕧也。从口念聲。《詩》曰：“民之方唸㕧。”","rad":"口","fq":"都見切","vol":"02","py":"diàn","duan":[{"e":"唸吚、","n":"逗。"}]},"黇":{"expl":"白黃色也。从黃占聲。","rad":"黃","fq":"他兼切","vol":"13","py":"tiān","duan":[{"e":"白黃色也。","n":"白色之敝而黃也。"}]},"黊":{"expl":"鮮明黃也。从黃圭聲。","rad":"黃","fq":"戶圭切","vol":"13","py":"huà","duan":[{"e":"鱻朙黃色也。","n":"依篇、韵補色字。上文皆非正黃色。惟此爲鮮明正黃耳。艸部蘳以爲聲。"}]},"男":{"expl":"丈夫也。从田从力。言男用力於田也。凡男之屬皆从男。","rad":"男","fq":"那含切","vol":"13","py":"nán","duan":[{"e":"丈夫也。","n":"夫下曰。周制八寸爲尺。十尺爲丈。人長一丈。故曰丈夫。白虎通曰。男、任也。任功業也。古男與任同音。故公侯伯子男、王莽男作任。"}]},"舅":{"expl":"母之兄弟爲𦥶，妻之父爲外𦥶。从男臼聲。","rad":"男","fq":"其久切","vol":"13","py":"jiù","duan":[{"e":"母之兄弟爲舅。","n":"釋親曰。母之晜弟爲舅。毛傳同。按周人謂兄爲晜也。舅之言舊也。猶姑之言故也。父之昆弟偁父。母之昆弟不得偁父。故偁舅。凡同姓可偁父。凡異姓不可偁父。故舅之也。今俗人言舅父者、非也。母之父母曷爲曰外王父、外王母與。父之父母偁王父王母。故母之父母得偁王父王母而外以別之也。父之昆弟偁從父。故母之？妹偁從母也。舍是則異姓無有偁父母者也。異姓可偁舅。故婦偁夫之父曰舅。男子偁妻之父曰外舅。母之從父昆弟曰從舅。又偁父之舅曰大舅。見後漢書。大者、今太字。"}]},"甥":{"expl":"謂我舅者，吾謂之甥也。从男生聲。","rad":"男","fq":"所更切","vol":"13","py":"shēnɡ","duan":[{"e":"謂我舅者吾謂之甥。","n":"釋親文。此泛釋甥義也。若母之昆弟爲吾舅。則謂吾爲甥矣。若妻之父爲吾外舅。則亦謂吾爲甥矣。釋親妻黨章曰。姑之子爲甥。舅之子爲甥。妻之晜弟爲甥。？妹之夫爲甥。注謂平等相甥。非也。姑之子、吾父母得甥之。舅之子、吾母姪之。吾父得甥之。妻之昆弟、吾父母得甥之。？妹之夫、吾父母壻之而甥之。是四者皆舅吾父者也。舅者、耆舊之偁。甥者、後生之偁。故異姓尊卑異等者以此相偁。爾雅類列於此。亦以見舅之子、妻之昆弟偁吾父皆曰舅。不似後世俗呼也。其立文如此者、從其便也。自來不得其解。則謂平等相甥。吾？妹之夫、吾父旣甥之矣。吾又呼之爲甥。此豈正名之義乎。姑之子爲外兄弟。舅之子爲內兄弟。妻之昆弟爲婚兄弟。？妹之夫爲姻兄弟。旣"}]},"力":{"expl":"筋也。象人筋之形。治功曰力，能圉大災。凡力之屬皆从力。","rad":"力","fq":"林直切","vol":"13","py":"lì","duan":[{"e":"筋也。","n":"筋下曰。肉之力也。二篆爲轉注。筋者其體。力者其用也。非有二物。引申之、凡精神所勝任皆曰力。"}]},"勳":{"expl":"能成王功也。从力熏聲。","rad":"力","fq":"許云切","vol":"13","py":"xūn","duan":[{"e":"能成王功也。","n":"司勳曰。王功曰勳。鄭云。輔成王業若周公。"}]},"功":{"expl":"以勞定國也。从力从工，工亦聲。","rad":"力","fq":"古紅切","vol":"13","py":"ɡōnɡ","duan":[{"e":"㠯勞定國也。","n":"司勳曰。國功曰功。鄭曰。𠈃全國家若伊尹。許則舉祭法文以釋之也。詩。以奏膚公。傳曰。膚犬也。公、功也。此謂叚公爲功也。"}]},"助":{"expl":"左也。从力且聲。","rad":"力","fq":"牀倨切","vol":"13","py":"zhù","duan":[{"e":"左也。","n":"左今之佐字。左下曰。手相左助也。二篆爲轉注。右下曰。手口相助也。易傳曰。右者、助也。按左右皆爲助。左者、以ナ助又。右者、以手助口。疑此解當云左右也。傳寫奪右字。商頌曰。實左右商王。傳云。左右、助也。"}]},"𠣊":{"expl":"助也。从力从非，慮聲。","rad":"力","fq":"良倨切","vol":"13","py":"lǜ","duan":[{"e":"助也。从力非。","n":"力去其非也。"}]},"㕧":{"expl":"唸㕧，呻也。从口尸聲。","rad":"口","fq":"馨伊切","vol":"02","py":"xī","duan":[]},"勑":{"expl":"勞也。从力來聲。","rad":"力","fq":"洛代切","vol":"13","py":"lài","duan":[{"e":"勞也。","n":"此當云勞勑也。淺人刪一字耳。此勞依今法讀去聲。孟子放勳曰。勞之來之。詩序曰。萬民離散。不安其居。宣王能勞來還定安集之。來皆勑之省。俗作徠。"}]},"劼":{"expl":"愼也。从力吉聲。《周書》曰：“汝劼毖殷獻臣。”","rad":"力","fq":"巨乙切","vol":"13","py":"jié","duan":[{"e":"愼也。","n":"愼者、謹也。廣韵曰。用力也。又固也。勤也。"}]},"務":{"expl":"趣也。从力敄聲。","rad":"力","fq":"亡遇切","vol":"13","py":"wù","duan":[{"e":"趣也。","n":"趣者、疾走也。務者、言其促疾於事也。"}]},"勥":{"expl":"迫也。从力强聲。","rad":"力","fq":"巨良切","vol":"13","py":"qiǎnɡ","duan":[{"e":"迫也。","n":"迫者、近也。按所謂實偪處此也。勥與彊義別。彊者、有力。勥者、以力相迫也。凡云勉勥者、當用此字。今則用強彊而勥？廢矣。"}]},"勱":{"expl":"勉力也。《周書》曰：“用勱相我邦家。”讀若萬。从力萬聲。","rad":"力","fq":"莫話切","vol":"13","py":"mài","duan":[{"e":"勉力也。","n":"勉者、勥也。亦作邁。左傳引夏書。臯陶邁種德。邁、勉也。"}]},"𠢤":{"expl":"勥也。从力厥聲。","rad":"力","fq":"瞿月切","vol":"13","py":"jué","duan":[{"e":"彊力也。","n":"彊力各本作勥力。非。今依玉篇、廣韵正。俗語？彊。彊讀去聲。"}]},"勍":{"expl":"彊也。《春秋傳》曰：“勍敵之人。”从力京聲。","rad":"力","fq":"渠京切","vol":"13","py":"qínɡ","duan":[{"e":"彊也。春秋傳曰。勍敵之人。","n":"彊者、弓有力也。引申爲凡有力之偁。春秋傳者、僖二十二年左傳文。杜亦曰。勍、強也。按勍與人部之倞字音義皆同。而勍獨見左氏。"}]},"勁":{"expl":"彊也。从力巠聲。","rad":"力","fq":"吉正切","vol":"13","py":"jìnɡ","duan":[{"e":"彊也。","n":"廣韵。勁、健也。"}]},"勉":{"expl":"彊也。从力免聲。","rad":"力","fq":"亡辨切","vol":"13","py":"miǎn","duan":[{"e":"勥也。","n":"勥舊作彊。非其義也。凡言勉者皆相迫之意。自勉者、自迫也。勉人者、迫人也。毛詩黽勉、韓詩作密勿。爾雅作？？。大雅毛傳曰。亹亹、勉也。周易鄭注。亹亹猶？？也。"}]},"劭":{"expl":"勉也。从力召聲。讀若舜樂《韶》。","rad":"力","fq":"寔照切","vol":"13","py":"shào","duan":[{"e":"勉也。","n":"釋詁同。漢成帝詔曰。先帝劭農。蘇林曰。劭音翹。精異之意也。晉灼曰。劭、勸勉也。按卪部邵、高也。邵與劭相似。轉寫容有互譌者。如應仲遠之名。當是卲字。此蘇林所說當亦是卲農。爾雅、方言皆曰。釗、勉也。釗當是劭之叚借字。"}]},"㘙":{"expl":"呻也。从口嚴聲。","rad":"口","fq":"五銜切","vol":"02","py":"yán","duan":[{"e":"呻也。从口。嚴聲。","n":"五銜切。八部。廣韵作？。"}]},"勖":{"expl":"勉也。《周書》曰：“勖哉，夫子！”从力冒聲。","rad":"力","fq":"許玉切","vol":"13","py":"xù","duan":[{"e":"勉也。","n":"釋詁同。邶風。以勖寡人。傳曰。勖、勉也。方言。釗、薄、勉也。秦晉曰釗。或曰薄。南楚之外曰薄努。自關而東周鄭之閒曰勔釗。齊魯曰勖。按勖古讀如茂。與懋音義皆同。故般庚懋建大命。予其懋𥳑相爾。今文尙書懋皆作勖。見隷釋石經殘碑。心部曰。懋、勉也。"}]},"勸":{"expl":"勉也。从力雚聲。","rad":"力","fq":"去願切","vol":"13","py":"quàn","duan":[{"e":"勉也。","n":"廣韵曰。奬勉也。按勉之而悅從亦曰勸。"}]},"勝":{"expl":"任也。从力朕聲。","rad":"力","fq":"識蒸切","vol":"13","py":"shēnɡ","duan":[{"e":"任也。","n":"任者、𠈃也。𠈃者、當也。凡能舉之、能克之皆曰勝。本無二義二音。而俗強分平去。"}]},"勶":{"expl":"發也。从力从徹，徹亦聲。","rad":"力","fq":"丑列切","vol":"13","py":"chè","duan":[{"e":"發也。","n":"發者、䠶發也。引申爲凡發去之偁。勶與徹義別。徹者、通也。勶謂除去。若禮之有司徹、客徹重席、詩之徹我牆屋、其字皆當作勶。不訓通也。或作撤、乃勶之俗也。"}]},"勠":{"expl":"并力也。从力翏聲。","rad":"力","fq":"力竹切","vol":"13","py":"lù","duan":[{"e":"勠力、幷力也。","n":"勠力二字依後漢劉虞傳注引補。文賦注引賈逵國語解詁曰。勠力、幷力也。許所本也。幷者、相從也。倂者、竝也。幷倂古通用矣。左傳、國語或云勠力同心。或云勠力一心。皆謂數人共致力。僞尙書傳訓云陳力。斯失之。古書多有誤作戮者。"}]},"勨":{"expl":"繇緩也。从力象聲。","rad":"力","fq":"余兩切","vol":"13","py":"xiànɡ","duan":[{"e":"䌛緩也。","n":"䌛葢今之傜字。言傜役緩也。與勠爲反對之詞。"}]},"動":{"expl":"作也。从力重聲。","rad":"力","fq":"徒總切","vol":"13","py":"dònɡ","duan":[{"e":"作也。","n":"作者、起也。"}]},"㔣":{"expl":"推也。从力畾聲。","rad":"力","fq":"盧對切","vol":"13","py":"lèi","duan":[{"e":"推也。","n":"推依今音他回切。㔣者、以物磊磊自高推下也。古用兵下礧石。李陵傳作壘石。晁錯傳具藺石。如淳注曰。城上雷石。周禮注亦作雷。唐書李光弼傳。擂石車。又作擂。其實用㔣爲正字也。故許書之字可用而不用者多矣。子虛賦曰。礧石相擊。硍硍礚礚。亦當作㔣。"}]},"劣":{"expl":"弱也。从力少聲。","rad":"力","fq":"力輟切","vol":"13","py":"liè","duan":[{"e":"弱也。","n":"弱者、橈也。"}]},"勞":{"expl":"劇也。从力，熒省。熒，火燒冂，用力者勞。","rad":"力","fq":"魯刀切","vol":"13","py":"láo","duan":[{"e":"勮也。","n":"勮各本从刀、作劇。今訂从力。文𨕖北征賦注引說文劇、甚也。恐是許書本作勮。用力甚也。後因以爲凡甚之詞。又譌其字从刀耳。以俟明者定之。"}]},"呻":{"expl":"吟也。从口申聲。","rad":"口","fq":"失人切","vol":"02","py":"shēn","duan":[{"e":"吟也。","n":"按呻者吟之舒。吟者呻之急。渾言則不別也。"}]},"勮":{"expl":"務也。从力豦聲。","rad":"力","fq":"其據切","vol":"13","py":"jù","duan":[{"e":"務也。","n":"務者、趣也。用力尤甚者。"}]},"勀":{"expl":"尤極也。从力𠑽聲。","rad":"力","fq":"苦得切","vol":"13","py":"kè","duan":[{"e":"尤勮也。","n":"勮大徐作極。小徐作勮。今正。勊又勮之尤者也。剋者、以力制勝之謂。故其事爲尤勞。許書勊與克義不同。克者、肩也。肩者、任也。以春秋所書言之。如辛已雨。不克葬。戊午日下昃。乃克葬。如晉人纳㨗葘于邾。弗克納。此克之義也。如鄭伯克段于鄢。傳曰。得儁曰克。此勊之義也。勊之字譌而从刀作剋。猶勮之譌而从刀也。經典有克無剋。百家之書克剋不分。而勊乃廢矣。"}]},"勩":{"expl":"勞也。《詩》曰：“莫知我勩。”从力貰聲。","rad":"力","fq":"余制切","vol":"13","py":"yì","duan":[{"e":"勞也。","n":"毛詩傳同。按凡物久用而勞敝曰勩。明楊愼荅中官問。謂牙牌摩損。當用鋊字。今按非也。當用勩字。今人謂物消磨曰勩是也。蘇州謂衣久箸曰勩箸。"}]},"勦":{"expl":"勞也。《春秋傳》曰：“安用勦民？”从力巢聲。","rad":"力","fq":"小子切","vol":"13","py":"jiǎo","duan":[{"e":"勞也。从力。巢聲。","n":"子小切。又楚交切。二部。"}]},"劵":{"expl":"勞也。从力，卷省聲。","rad":"力","fq":"渠卷切","vol":"13","py":"juàn","duan":[{"e":"勞也。","n":"輈人。終日馳騁。左不楗。書楗或作劵。鄭云。劵今倦字也。據此則漢時已倦行劵廢矣。"}]},"勤":{"expl":"勞也。从力𡏳聲。","rad":"力","fq":"巨巾切","vol":"13","py":"qín","duan":[{"e":"勞也。","n":"慰其勤亦曰勤。"}]},"加":{"expl":"語相增加也。从力从口。","rad":"力","fq":"古牙切","vol":"13","py":"jiā","duan":[{"e":"語相譄加也。","n":"譄各本作增。今正。增者、益也。義不與此同。譄下曰。加也。誣下曰。加也。此云語相譄加也。知譄誣加三字同義矣。誣人曰譄。亦曰加。故加从力。論語曰。我不欲人之加諸我也。吾亦欲無加諸人。馬融曰。加、陵也。袁宏曰。加、不得理之謂也。劉知幾史通曰。承其誣𡚶。重以加諸。韓愈爭臣論曰。吾聞君子不欲加諸人。而惡訐以爲直者。皆得加字本義。引申之、凡據其上曰加。故加巢卽架巢。"}]},"𠢕":{"expl":"健也。从力敖聲。讀若豪。","rad":"力","fq":"五牢切","vol":"13","py":"háo","duan":[{"e":"健也。","n":"健者、伉也。此豪傑眞字。自叚豪爲之、而𠢕廢矣。豪、豕鬛如筆管者。"}]},"勇":{"expl":"气也。从力甬聲。","rad":"力","fq":"余隴切","vol":"13","py":"yǒnɡ","duan":[{"e":"气也。","n":"气、雲气也。引申爲人充體之气之偁。力者、筋也。勇者、气也。气之所至。力亦至焉。心之所至。气乃至焉。故古文勇从心。左傳曰。共用之謂勇。"}]},"勃":{"expl":"排也。从力孛聲。","rad":"力","fq":"薄没切","vol":"13","py":"bó","duan":[{"e":"排也。","n":"排者、擠也。今俗語謂以力旋轉曰勃。當用此字。論語。色孛如也。許所引乃本字本義。謂𤱿孛、盛气也。今論叚借勃字。殊失其恉。"}]},"玒":{"expl":"玉也。从玉工聲。","rad":"玉","fq":"戶工切","vol":"01","py":"hónɡ","duan":[{"e":"玉也。从王。工聲。","n":"戸工切。九部。"}]},"吟":{"expl":"呻也。从口今聲。","rad":"口","fq":"魚音切","vol":"02","py":"yín","duan":[{"e":"呻也。从口。今聲。","n":"魚音切。七部。"}]},"勡":{"expl":"劫也。从力㶾聲。","rad":"力","fq":"匹眇切","vol":"13","py":"piào","duan":[{"e":"劫也。","n":"以力脅止人而取其物也。賈誼傳曰。盜者白晝大都之中。勡吏而奪之金。貨殖傳曰。攻剽椎埋。按此篆諸書多从刀。而許刀部剽下曰。一曰剽劫人也。是在許時固从力从刀竝行。二形不必有是非矣。"}]},"劫":{"expl":"人欲去，以力脅止曰劫。或曰以力止去曰劫。","rad":"力","fq":"居怯切","vol":"13","py":"jié","duan":[{"e":"人欲去㠯力脅止曰劫。","n":"脅猶迫也。俗作愶。古無其字。用脅而已。以力止人之去曰劫。不專謂盜。而盜禦人於國門之外亦劫也。太史公曰。劫人作姦。"}]},"飭":{"expl":"致堅也。从人从力，食聲。讀若敕。","rad":"力","fq":"恥力切","vol":"13","py":"chì","duan":[{"e":"致臤也。","n":"臤者、堅也。致者、送詣也。致之於堅。是之謂飭。攷工記曰。審曲面勢以飭五材。謂五材皆必堅緻也。又曰。飭力以長地材。謂整頓其人力也。凡人物皆得云飭。飭人而筋骸束矣。飭物而器用精良矣。其字形與飾相似。故古書多有互譌者。飾在外。飭在內。其義不同。竊謂許書工下云巧飾也。當作巧也、飭也。飭卽記所謂飭五材。辨民器。謂之百工。不徒修飾其外而已。凡經傳子史之譌皆可以意正之。飭與敕義略相近。敕、誡也。"}]},"劾":{"expl":"法有辠也。从力亥聲。","rad":"力","fq":"胡槩切","vol":"13","py":"hé","duan":[{"e":"灋有辠也。","n":"法者、謂以法施之。廣韵曰。劾、推窮罪人也。"}]},"募":{"expl":"廣求也。从力莫聲。","rad":"力","fq":"莫故切","vol":"13","py":"mù","duan":[{"e":"廣求之也。","n":"依光武紀注增之字。"}]},"劬":{"expl":"勞也。从力句聲。","rad":"力","fq":"其俱切","vol":"13","py":"qú","duan":[]},"勢":{"expl":"盛力權也。从力埶聲。經典通用埶。","rad":"力","fq":"舒制切","vol":"13","py":"shì","duan":[]},"勘":{"expl":"校也。从力甚聲。","rad":"力","fq":"苦紺切","vol":"13","py":"kàn","duan":[]},"辦":{"expl":"致力也。从力辡聲。","rad":"力","fq":"蒲莧切","vol":"13","py":"bàn","duan":[]},"劦":{"expl":"同力也。从三力。《山海經》曰：“惟號之山，其風若劦。”凡劦之屬皆从劦。","rad":"劦","fq":"胡頰切","vol":"13","py":"xié","duan":[{"e":"同力也。","n":"同力者、龢也。龢、調也。"}]},"嗞":{"expl":"嗟也。从口兹聲。","rad":"口","fq":"子之切","vol":"02","py":"zī","duan":[{"e":"嗟也。","n":"嗟言部作？。云？、嗞也。與此爲互訓。今本言部作咨也。淺人𡚶改耳。謀事曰咨。音義皆殊。戰國策秦策五。平原令見諸公。必爲言之曰。嗟嗞乎。司空馬。詩綢繆。子兮子兮。如此良人何。毛傳。子兮者、嗟茲也。茲當作？。古言？嗞。今人作嗟咨。非也。廣韵。嗞嗟、憂聲也。"}]},"恊":{"expl":"同心之和。从劦从心。","rad":"劦","fq":"胡頰切","vol":"13","py":"xié","duan":[{"e":"同心之龢也。","n":"同心一如同力。故从劦心會意。"}]},"𢣢":{"expl":"同思之和。从劦从思。","rad":"劦","fq":"胡頰切","vol":"13","py":"xié","duan":[{"e":"同思之龢也。","n":"同思一如同力。"}]},"協":{"expl":"眾之同和也。从劦从十。","rad":"劦","fq":"胡頰切","vol":"13","py":"xié","duan":[{"e":"同眾之龢也。","n":"各本作衆之和同。非是。今正。同衆之和。一如同力。"}]},"金":{"expl":"五色金也。黃爲之長。久薶不生衣，百鍊不輕，从革不違。西方之行。生於土，从土；左右注，象金在土中形；今聲。凡金之屬皆从金。","rad":"金","fq":"居音切","vol":"14","py":"jīn","duan":[{"e":"五色金也。","n":"凡有五色。皆謂之金也。下文白金、靑金、赤金、黑金、合黃金爲五色。"}]},"銀":{"expl":"白金也。从金艮聲。","rad":"金","fq":"語巾切","vol":"14","py":"yín","duan":[{"e":"白金也。","n":"黃金旣專金名。其外四者皆各有名爾雅曰。黃金謂之璗。其美者謂之鏐。然則黃金自有名。而許以璗系諸玉部。云金之美者、與玉同色。與釋器不合、何也。璗爲金、而字从玉。許書主釋字形。故其說如此也。爾雅又曰。白金謂之銀。其美者謂之鐐。此則許所本也。"}]},"鐐":{"expl":"白金也。从金尞聲。","rad":"金","fq":"洛蕭切","vol":"14","py":"liáo","duan":[{"e":"白金也。","n":"爾雅别之曰其美者。許不别也。毛詩傳曰。大夫鐐琫而鐐珌。"}]},"鋈":{"expl":"白金也。从金，𦰚省聲。","rad":"金","fq":"烏酷切","vol":"14","py":"wù","duan":[{"e":"白金也。从金。𣵽省聲。","n":"大徐𣵽省聲。小徐沃聲。考說文芺聲之字未有省艸者。鋈字今三見於毛詩。小戎毛傳曰。沃、白金也。而車部軜下詩曰𣵽以觼軜。引詩正作𣵽不作鋈。知古本毛詩衹作𣵽。𣵽卽鐐之叚借字。古芺聲尞聲同部也。金部本有鐐無鋈。淺人乃依今毛詩補之。烏酷切。二部。"}]},"鉛":{"expl":"青金也。从金㕣聲。","rad":"金","fq":"與專切","vol":"14","py":"qiān","duan":[{"e":"靑金也。从金。㕣聲。","n":"與專切。十四部。"}]},"錫":{"expl":"銀鉛之閒也。从金易聲。","rad":"金","fq":"先擊切","vol":"14","py":"xī","duan":[{"e":"銀鉛之閒也。","n":"周禮？人注曰。鈏也。職方氏曰。鑞也。鑞字說文無。經典多叚錫爲賜字。凡言錫予者、卽賜之叚借也。"}]},"鈏":{"expl":"錫也。从金引聲。","rad":"金","fq":"羊晉切","vol":"14","py":"yǐn","duan":[{"e":"錫也。","n":"見釋器"}]},"哤":{"expl":"哤異之言。从口尨聲。一曰雜語。讀若尨。","rad":"口","fq":"莫江切","vol":"02","py":"mánɡ","duan":[{"e":"哤異之言。","n":"齊語曰。四民者勿使襍處。襍處則其言哤。其事易。韋注。哤、亂也。"}]},"銅":{"expl":"赤金也。从金同聲。","rad":"金","fq":"徒紅切","vol":"14","py":"tónɡ","duan":[{"e":"赤金也。","n":"銅色本赤。今之白銅、㸃化爲之耳。食貨志曰。金有三等。黃金爲上。白金爲中。赤金爲下。孟康曰。赤金、丹陽銅也。按丹陽銅卽吳王濞傳章郡銅山、貨殖傳章山之銅也。"}]},"鏈":{"expl":"銅屬。从金連聲。","rad":"金","fq":"力延切","vol":"14","py":"lián","duan":[{"e":"銅屬。","n":"應劭曰。鏈似銅。與許說合。"}]},"鐵":{"expl":"黑金也。从金𢧤聲。","rad":"金","fq":"天結切","vol":"14","py":"tiě","duan":[{"e":"黑金也。从金。𢧤聲。","n":"天結切。十二部。"}]},"鍇":{"expl":"九江謂鐵曰鍇。从金皆聲。","rad":"金","fq":"苦駭切","vol":"14","py":"kǎi","duan":[{"e":"九江謂鐵曰鍇。从金。皆聲。","n":"苦駭切。十五部。"}]},"鋚":{"expl":"鐵也。一曰轡首銅。从金攸聲。","rad":"金","fq":"以周切","vol":"14","py":"tiáo","duan":[{"e":"鐵也。一曰𦆕首銅也。","n":"别一義。小雅。䩦革沖沖毛傳曰。䩦、轡也。革、轡首也。按䩦轡也當作䩦轡首飾也。轉寫奪去二字耳。下文云。沖沖、垂飾皃。正承轡首飾而言。許釋鋚爲轡首銅。鋚卽䩦字。詩本作攸。轉寫誤作䩦。攸革皆古文叚借字也。古金石文字作𠈹勒。或作鋚勒。轡首銅者、以銅飾轡首也。革部勒下云。馬頭絡銜也。卽毛傳所謂轡首也。周頌載見箋云。鶬謂金飾。正與轡首銅之訓合。大雅韓奕鞟以爲鞃。淺以爲幦。鋚以飾勒。金以飾軛。四事文意一例。鋚勒謂以銅飾轡之近馬頭處。垂之沖沖然也。"}]},"鏤":{"expl":"剛鐵，可以刻鏤。从金婁聲。《夏書》曰：“梁州貢鏤。”一曰鏤，釜也。","rad":"金","fq":"盧候切","vol":"14","py":"lòu","duan":[{"e":"剛鐵也。可㠯刻鏤。","n":"鏤本剛鐵之名。剛鐵可受鐫刻。故鐫刻亦曰鏤。釋器曰。金謂之鏤。鏤、䤹也。詩。鉤膺鏤鍚。箋皆訓刻金。許以可以刻鏤釋鏤。此卽已已也、？？也之例也。今則引申之義行而本義廢矣。禹貢梁州貢鏤。某氏傳亦云剛鐵。"}]},"鐼":{"expl":"鐵屬。从金賁聲。讀若熏。","rad":"金","fq":"火運切","vol":"14","py":"fén","duan":[{"e":"鐵屬。从金。賁聲。讀若熏。","n":"小徐本讀若訓。火運切。十三部。"}]},"銑":{"expl":"金之澤者。一曰小鑿。一曰鐘兩角謂之銑。从金先聲。","rad":"金","fq":"穌典切","vol":"14","py":"xiǎn","duan":[{"e":"金之澤者。","n":"澤者、光潤也。釋器曰。絶澤謂之銑、晉語。玦之以金銑者。寒之甚矣。韋注。銑猶洒也。洒洒、寒皃。言於太子無温潤也。許言其光潤。韋言寒皃。皆謂金之精者耳。似異而非異也。"}]},"鋻":{"expl":"剛也。从金臤聲。","rad":"金","fq":"古甸切","vol":"14","py":"jiàn","duan":[{"e":"𠟎也。","n":"𠟎各本譌剛。今正。刀部曰。𠟎、刀劍刃也。刃下曰。刀鋻也。故𠟎與鋻爲轉注。王褒聖主得賢臣頌曰。淸水淬其鋒。李善引三倉解詁云。淬作刀鋻也。文𨕖俗本譌爲鑒。"}]},"鑗":{"expl":"金屬。一曰剥也。从金黎聲。","rad":"金","fq":"郎兮切","vol":"14","py":"lí","duan":[{"e":"金屬也。一曰剝也。","n":"剝者裂也。剝訓裂。知鑗與剺義同音别。方言。蠡、分也。注謂分割也。此卽鑗之叚借。方言又曰。劙、解也。亦卽此字。"}]},"叫":{"expl":"嘑也。从口丩聲。","rad":"口","fq":"古弔切","vol":"02","py":"jiào","duan":[{"e":"嘑也。从口。丩聲。","n":"古弔切。古音在三部。按㗊部嘂、言部訆皆訓大嘑。與此音同義小異。疑叫字淺人所增。"}]},"錄":{"expl":"金色也。从金录聲。","rad":"金","fq":"力玉切","vol":"14","py":"lù","duan":[{"e":"金色也。","n":"錄與綠同音。金色在靑黃之閒也。叚借爲省錄字。慮之叚借也。故錄囚卽慮囚。云庸錄者、猶無慮也。言其緐猥。"}]},"鑄":{"expl":"銷金也。从金壽聲。","rad":"金","fq":"之戍切","vol":"14","py":"zhù","duan":[{"e":"銷金也。从金。壽聲。","n":"之戍切。古音在三部。亦讀如祝。"}]},"銷":{"expl":"鑠金也。从金肖聲。","rad":"金","fq":"相邀切","vol":"14","py":"xiāo","duan":[{"e":"鑠金也。从金。肖聲。","n":"相邀切。二部。"}]},"鑠":{"expl":"銷金也。从金樂聲。","rad":"金","fq":"書藥切","vol":"14","py":"shuò","duan":[{"e":"銷金也。从金。樂聲。","n":"書藥切。二部。"}]},"鍊":{"expl":"冶金也。从金柬聲。","rad":"金","fq":"郎甸切","vol":"14","py":"liàn","duan":[{"e":"治金也。","n":"治大徐本譌作冶。今正。湅、治絲也。練、治繒也。鍊、治金也。皆謂㶕湅欲其精。非苐冶之而已。冶者、銷也。引申之、凡治之使精曰鍊。"}]},"釘":{"expl":"鍊鉼黃金。从金丁聲。","rad":"金","fq":"當經切","vol":"14","py":"dīnɡ","duan":[{"e":"鍊鉼黃金也。","n":"周禮職金。旅於上帝。則共其金版。饗諸侯亦如之。注曰。鉼金謂之版。此版所施未聞。按今爾雅鉼金謂之鈑。鈑系版之譌。則鉼當是餠之譌也。凡物匾之曰餅。鍊餅、鍊而成之。"}]},"錮":{"expl":"鑄塞也。从金固聲。","rad":"金","fq":"古慕切","vol":"14","py":"ɡù","duan":[{"e":"鑄𡫳也。","n":"𡫳作塞。誤。今正。凡銷鐵以窒穿穴謂之錮。左傳曰。子反請以重幣錮之。漢書曰。下錮三泉。"}]},"鑲":{"expl":"作型中膓也。从金襄聲。","rad":"金","fq":"汝羊切","vol":"14","py":"ránɡ","duan":[{"e":"作𡌒中腸也。","n":"𡌒者、鑄器之法也。其中腸謂之鑲。猶𤓰中腸謂之瓤也。鑲亦用爲句鑲。兵器也。别一義。見釋名。"}]},"鎔":{"expl":"冶器法也。从金容聲。","rad":"金","fq":"金封切","vol":"14","py":"rónɡ","duan":[{"e":"冶器灋也。","n":"冶者、銷也。鑄也。董仲舒傳曰。猶泥之在鈞。唯甄者之所爲。猶金之在鎔。唯冶者之所鑄。師古曰。鎔謂鑄器之模範也。今人多失其義。"}]},"鋏":{"expl":"可以持冶器鑄鎔者。从金夾聲。讀若漁人莢魚之莢。一曰若挾持。","rad":"金","fq":"古叶切","vol":"14","py":"jiá","duan":[{"e":"可㠯持冶器鑄鎔者也。","n":"冶器者鑄於鎔中。則以此物夾而出之。此物金爲之。故从金。"}]},"嘅":{"expl":"嘆也。从口旣聲。《詩》曰：“嘅其嘆矣。”","rad":"口","fq":"苦蓋切","vol":"02","py":"kài","duan":[{"e":"嘆也。从口。旣聲。","n":"苦葢切。十五部。"}]},"鍛":{"expl":"小冶也。从金段聲。","rad":"金","fq":"丁貫切","vol":"14","py":"duàn","duan":[{"e":"小冶也。","n":"小冶謂小作鑪韛以冶金。如嵇康之鍛竈是也。冶之則必椎之。故曰鍛鐵。殳部曰。段、椎物也。鍛从段金、會意兼形聲。考工記。段氏爲鎛器。段卽鍛也。詩之碫石、則鍛質也。"}]},"鋌":{"expl":"銅𨮯樸也。从金廷聲。","rad":"金","fq":"徒鼎切","vol":"14","py":"dìnɡ","duan":[{"e":"銅鐵樸也。","n":"樸、木素也。因以爲凡素之偁。小徐作朴。非也。石部曰。磺、銅鐵樸。鋌與磺義同音别。亦謂之鋇。淮南書曰。苗山之鋌。"}]},"䥵":{"expl":"𨮯文也。从金曉聲。","rad":"金","fq":"呼鳥切","vol":"14","py":"xiǎo","duan":[{"e":"鐵文也。","n":"謂鐵之文理也。"}]},"鏡":{"expl":"景也。从金竟聲。","rad":"金","fq":"居慶切","vol":"14","py":"jìnɡ","duan":[{"e":"景也。","n":"景者、光也。金有光可照物謂之鏡。此以曡韵爲訓也。鏡亦曰鑒。雙聲字也。"}]},"鉹":{"expl":"曲鉹也。从金多聲。一曰鬵鼎，讀若𢴨。一曰《詩》云“侈兮哆兮”。","rad":"金","fq":"尺氏切","vol":"14","py":"chǐ","duan":[{"e":"曲鉹也。从金。多聲。","n":"尺氏切。古音在十七部。"}]},"銒":{"expl":"似鍾而頸長。从金幵聲。","rad":"金","fq":"戶經切","vol":"14","py":"xínɡ","duan":[{"e":"佀鍾而長頸。","n":"鍾俗本作鐘。今從宋本。鍾者、酒器。見下。此以相聯爲文矣。用此知古酒鍾有腹有頸。葢大其下小其上也。"}]},"鍾":{"expl":"酒器也。从金重聲。","rad":"金","fq":"職容切","vol":"14","py":"zhōnɡ","duan":[{"e":"酒器也。","n":"古者此器葢用以宁酒。故大其下、小其頸。自鍾傾之而入於尊。自尊勺之而入於觶。故量之大者亦曰鍾。引申之義爲鍾聚。"}]},"鑑":{"expl":"大盆也。一曰監諸，可以取明水於月。从金監聲。","rad":"金","fq":"革懺切","vol":"14","py":"jiàn","duan":[{"e":"大盆也。","n":"盆者、盎也。凌人。春始治鑑。注云。鑑如甀、大口。以盛冰。置食物於中。以禦温氣。春而始治之。按鄭云如甀。醢人作醢云塗置甀中。則鑑如今之甕。許云大盆。則與鄭說不符。疑許說爲是。且字从金。必以金爲之也。"}]},"鐈":{"expl":"似鼎而長足。从金喬聲。","rad":"金","fq":"巨嬌切","vol":"14","py":"qiáo","duan":[{"e":"佀鼎而長足。从金。喬聲。","n":"巨嬌切。二部。"}]},"䥙":{"expl":"陽䥙也。从金隊聲。","rad":"金","fq":"徐醉切","vol":"14","py":"suì","duan":[{"e":"陽䥙也。从金。隊聲。","n":"按此字非其次。疑後人因上說方諸而增之。周禮秋官本作遂。"}]},"唌":{"expl":"語唌嘆也。从口延聲。","rad":"口","fq":"夕連切","vol":"02","py":"xián","duan":[{"e":"語唌嘆也。","n":"梁鴻傳。競舉枉兮措直。咸先佞兮唌唌。注。唌音延。讒言捷急之皃。郭注爾雅。假爲㳄字。夕連切。"}]},"鋞":{"expl":"温器也。圜直上。从金坙聲。","rad":"金","fq":"戶經切","vol":"14","py":"xínɡ","duan":[{"e":"𥁕器也。","n":"𥁕各本作温。今正。許書温系水名。𥁕訓仁也。𥁕訓仁、故引申爲𥁕煗字。煗下曰。𥁕也。㬮下曰。安㬮、𥁕也。凡經史可借用温。而許書不宜自相矛盾。凡讀許書者知此。則九千三百餘文之說解絕無不可通之處矣。葢非用其字之本義。卽用其字之引申之義。𣃔無有風馬牛不相及者也。温訓水名。此云温器也。是爲風馬牛不相及矣。𥁕器者、謂可用煗物之器也。"}]},"鑴":{"expl":"瓽也。从金巂聲。","rad":"金","fq":"戶圭切","vol":"14","py":"xī","duan":[{"e":"瓽也。","n":"瓦部曰。瓽、大盆也。然則鑴與鑑同物。周禮眡祲。十煇、三曰鑴。鄭注。鑴讀爲童子佩觿之觿。謂日㫄氣刺日也。按今本周禮注觿譌金㫄。非是。觿者、佩角。銳耑可以解結。故鄭讀鑴爲觿。今本作讀如。亦非也。"}]},"鑊":{"expl":"鑴也。从金蒦聲。","rad":"金","fq":"胡郭切","vol":"14","py":"huò","duan":[{"e":"鑴也。","n":"少牢饋食禮有羊鑊、有豕鑊。鑊所以煑也。"}]},"鍑":{"expl":"釜大口者。从金复聲。","rad":"金","fq":"方副切","vol":"14","py":"fù","duan":[{"e":"如𨥏而大口者。","n":"如而二字依玄應補。？者、鬴之或字。鬲部曰。鬴、鍑屬。是二篆爲轉注也。方言曰。？、自關而西或謂之鍑。"}]},"鍪":{"expl":"鍑屬。从金敄聲。","rad":"金","fq":"莫浮切","vol":"14","py":"móu","duan":[{"e":"鍑屬。从金。敄聲。","n":"莫浮切。三部。"}]},"錪":{"expl":"朝鮮謂釜曰錪。从金典聲。","rad":"金","fq":"他典切","vol":"14","py":"tiǎn","duan":[{"e":"朝鮮謂釜曰錪。","n":"方言。鍑、北燕朝鮮洌水之閒或謂之錪。或謂之鉼。"}]},"銼":{"expl":"鍑也。从金坐聲。","rad":"金","fq":"昨禾切","vol":"14","py":"cuò","duan":[{"e":"銼𨰠。","n":"二字依全書通例補。曡韵字。"}]},"𨰠":{"expl":"銼𨰠也。从金羸聲。","rad":"金","fq":"魯戈切","vol":"14","py":"luó","duan":[{"e":"銼𨰠也。从金。羸聲。","n":"魯戈切。十七部。"}]},"𨦕":{"expl":"器也。从金㓝聲。","rad":"金","fq":"戶經切","vol":"14","py":"xínɡ","duan":[{"e":"器也。","n":"此禮器也。魯頌。毛炰胾羹。傳曰。羹、大羹。？羹也。按大羹、煮肉汁不和。貴其質也。？羹、肉汁之有菜和者也。大羹盛之於登。？羹盛之於？。？羹菜和謂之芼。其詳在禮經。？經典亦作銒。此猶㓝罰字本从井。作𠛬非正字也。內饔職？作㓝、亦叚借字。"}]},"鎬":{"expl":"温器也。从金高聲。武王所都，在長安西上林苑中，字亦如此。","rad":"金","fq":"乎老切","vol":"14","py":"hào","duan":[{"e":"𥁕器也。从金。高聲。","n":"乎老切。二部。"}]},"嘆":{"expl":"吞歎也。从口，歎省聲。一曰太息也。","rad":"口","fq":"他案切","vol":"02","py":"tàn","duan":[{"e":"吞歎也。","n":"九經字㨾作吞聲也。非。按嘆歎二字今人通用。毛詩中㒳體錯出。依說文則義異。歎近於喜。嘆近於哀。故嘆訓吞歎。吞其歎而不能發。詳欠部。"}]},"䥝":{"expl":"温器也。一曰金器。从金麀聲。","rad":"金","fq":"於刀切","vol":"14","py":"āo","duan":[{"e":"𥁕器也。","n":"𥁕各本作温。今正。下同。廣韵曰。䥝、銅瓫也。今江東尙有䥝孰之語。與火部以微火温肉之？義同。或作𤏶。或作鏖。集韵曰。盡死殺人曰鏖糟。漢霍去病合短兵、鏖皋蘭下是也。"}]},"銚":{"expl":"温器也。一曰田器。从金兆聲。","rad":"金","fq":"以招切","vol":"14","py":"yáo","duan":[{"e":"𥁕器也。","n":"今煮物瓦器謂之銚子。讀徒弔切是也。"}]},"𨪐":{"expl":"酒器也。从金，𠁁象器形。","rad":"金","fq":"大口切","vol":"14","py":"dòu","duan":[{"e":"酒器也。","n":"未聞。或曰卽行葦之大斗。非是。毛傳大斗長三尺。謂勺柄長三尺也。"}]},"鐎":{"expl":"鐎斗也。从金焦聲。","rad":"金","fq":"即消切","vol":"14","py":"jiāo","duan":[{"e":"鐎斗也。","n":"卽刀斗也。孟康曰。以銅作鐎器。受一斗。晝炊飯食。夜擊持行。名曰刀斗。荀悅曰。刀斗小鈴。如宫中傳夜鈴也。蘇林曰。形如鋗。以銅作之。無緣。受一斗。故云刀斗。鐎卽鈴也。廣韵。温器。三足而有柄。"}]},"鋗":{"expl":"小盆也。从金肙聲。","rad":"金","fq":"火玄切","vol":"14","py":"xuān","duan":[{"e":"小盆也。","n":"廣韵曰。銅銚。"}]},"鏏":{"expl":"鼎也。从金彗聲。讀若彗。","rad":"金","fq":"于歲切","vol":"14","py":"wèi","duan":[{"e":"鼎也。","n":"淮南說林訓。水火相憎。鏏在其閒。五味以和。注曰。鏏、小鼎。又曰。鼎無耳爲鏏。"}]},"鍵":{"expl":"鉉也。一曰車轄。从金建聲。","rad":"金","fq":"渠偃切","vol":"14","py":"jiàn","duan":[{"e":"鉉也。","n":"謂鼎扃也。以木橫關鼎耳而舉之。非是則旣炊之鼎不可舉也。故謂之關鍵。引申之爲門戶之鍵閉。門部曰。關、以木橫持門戶也。門之關猶鼎之鉉也。"}]},"鉉":{"expl":"舉鼎也。《易》謂之鉉，《禮》謂之鼏。从金玄聲。","rad":"金","fq":"胡犬切","vol":"14","py":"xuàn","duan":[{"e":"所㠯舉鼎也。","n":"所以二字今補。汲古閣於舉鼎下增具字。今刪正。手部曰。扛、橫關對舉也。謂橫關於㒳耳。露其耑以㒳手對舉之。非是則難扛也。"}]},"鋊":{"expl":"可以句鼎耳及鑪炭。从金谷聲。一曰銅㞕。讀若浴。","rad":"金","fq":"余足切","vol":"14","py":"yù","duan":[{"e":"可㠯句鼎耳及鑪炭。","n":"句讀如鉤。鉤鼎耳舉之、鉤鑪炭出之之器也。"}]},"鎣":{"expl":"器也。从金，熒省聲。讀若銑。","rad":"金","fq":"烏定切","vol":"14","py":"yìnɡ","duan":[{"e":"器也","n":"謂摩鋥之器也。以金爲之。爾雅注曰。鸊鷉膏中鎣刀。"}]},"喝":{"expl":"㵣也。从口曷聲。","rad":"口","fq":"於介切","vol":"02","py":"yè","duan":[{"e":"㵣也。","n":"疑當作㵣音也。今脫音字耳。莊子庚桑楚。終日嗥而嗌不嗄。崔譔本作不喝。云啞也。子虛賦。榜人歌聲流喝。郭璞曰。言悲嘶也。又謝希逸文。喝邊簫於松霧。"}]},"鑯":{"expl":"𨮯器也。一曰鑴也。从金韱聲。","rad":"金","fq":"子廉切","vol":"14","py":"jiān","duan":[{"e":"鐵器也。","n":"葢銳利之器。郭注爾雅用爲今之尖字。融丘、鑯頂者。"}]},"錠":{"expl":"鐙也。从金定聲。","rad":"金","fq":"丁定切","vol":"14","py":"dìnɡ","duan":[{"e":"鐙也。","n":"廣韵曰。豆有足曰錠。無足曰鐙。玄應引聲類無豆字。誤矣。"}]},"鐙":{"expl":"錠也。从金登聲。","rad":"金","fq":"都滕切","vol":"14","py":"dēnɡ","duan":[{"e":"錠也。","n":"祭統曰。夫人薦豆執校。執醴授之執鐙。注曰。校、豆中央直者也。鐙、豆下跗也。執醴者以豆授夫人。執其下跗。夫人受之。執其中央直者。按跗、說文作柎。闌足也。鐙有柎。則無足曰鐙之說未可信。豆之遺制爲今俗用燈盞。徐氏兄弟遂以膏鐙解說文。誤矣。生民傳曰。木曰豆。瓦曰登。豆薦菹醢。登薦大羹。箋云。祀天用瓦豆。陶器質也。然則瓦登用於祭天。廟中之鐙。笵金爲之。故其字从金。"}]},"鏶":{"expl":"鍱也。从金集聲。","rad":"金","fq":"奏入切","vol":"14","py":"jí","duan":[{"e":"鍱也。从金。集聲。","n":"秦入切。七部"}]},"鍱":{"expl":"鏶也。从金葉聲。齊謂之鍱。","rad":"金","fq":"與涉切","vol":"14","py":"yè","duan":[{"e":"鏶也。","n":"此謂金銅鐵椎薄成葉者。"}]},"鏟":{"expl":"鏶也。一曰平𨮯。从金産聲。","rad":"金","fq":"初限切","vol":"14","py":"chǎn","duan":[{"e":"鏶也。从金。產聲。","n":"初限切。十四部。"}]},"鑪":{"expl":"方鑪也。从金盧聲。","rad":"金","fq":"洛胡切","vol":"14","py":"lú","duan":[{"e":"方鑪也。","n":"方對下圜言之。凡㸐炭之器曰鑪。定公三年左傳。邾莊公自投於牀。廢於鑪炭。爛。遂卒。"}]},"鏇":{"expl":"圜鑪也。从金旋聲。","rad":"金","fq":"辭戀切","vol":"14","py":"xuàn","duan":[{"e":"圜鑪也。","n":"玄應曰。周成難字作檈。謂以繩轉軸裁木爲器曰檈。按圜鑪之義之引申也。古文苑美人賦。金帀熏香。說者以爲圜鑪。"}]},"𨪉":{"expl":"器也。从金虒聲。","rad":"金","fq":"杜兮切","vol":"14","py":"tí","duan":[{"e":"器也。从金。虒聲。","n":"杜兮切。十六部。"}]},"鐪":{"expl":"煎膠器也。从金虜聲。","rad":"金","fq":"郎古切","vol":"14","py":"lǔ","duan":[{"e":"𤋎膠器也。","n":"煎、熬也。膠、作之以皮。故熬之而後成。"}]},"哨":{"expl":"不容也。从口肖聲。","rad":"口","fq":"才肖切","vol":"02","py":"shào","duan":[{"e":"不容也。","n":"鄭注考工記曰。哨頃、小也。記投壷曰。某有枉矢哨壷。"}]},"釦":{"expl":"金飾器口。从金从口，口亦聲。","rad":"金","fq":"苦厚切","vol":"14","py":"kòu","duan":[{"e":"金飾器口。","n":"謂以金涂器口。許所謂錯金。今俗所謂鍍金也。漢舊儀。大官尙食。用黃金釦器。中官私官尙食。用白銀釦器。後漢和熹鄧皇后紀。蜀漢釦器。班固西都賦。玄墀釦切。謂金涂門限也。切者、門限。吳語。三軍皆譁釦以振旅。韋曰。譁釦、喧呼。此釦乃叚借字。"}]},"錯":{"expl":"金涂也。从金昔聲。","rad":"金","fq":"倉各切","vol":"14","py":"cuò","duan":[{"e":"金涂也。","n":"涂俗作塗。又或作？。謂以金措其上也。或借爲措字。措者、置也。或借爲摩厝字。厝者、厲石也。或借爲䢒逪字。東西曰䢒。邪行曰逪也。"}]},"䥏":{"expl":"鉏䥏也。从金御聲。","rad":"金","fq":"魚舉切","vol":"14","py":"yǔ","duan":[{"e":"鉏䥏也。","n":"鉏音牀吕切。䥏音魚巨切。曡韵字。齒部齟齬、齒不相值也。鉏䥏、葢亦器之能相抵拒錯摩者。故廣韵以不相當釋鉏鋙。周禮玉人注云駔牙。左傳人有名鉏吾者。皆此二者之同音叚借。"}]},"錡":{"expl":"鉏䥏也。从金奇聲。江淮之閒謂釜曰錡。","rad":"金","fq":"魚綺切","vol":"14","py":"yǐ","duan":[{"e":"鉏䥏也。","n":"豳風。旣破我斧。又缺我錡。傳曰。鑿屬曰錡。此葢所謂鉏䥏者與。字或作奇。"}]},"鍤":{"expl":"郭衣鍼也。从金臿聲。","rad":"金","fq":"楚洽切","vol":"14","py":"chā","duan":[{"e":"𩫏衣鍼也。","n":"𩫏各本作郭。今正。郭者、齊之郭氏虛也。𩫏者、城𩫏。民所度居也。古無廓字。衹用郭字。其實當用𩫏。如𡔷下云郭皮甲而出。此云郭衣。皆謂恢廓。張衣於版、以鍼密籖其週使伸直。今之治裘者正如此。是曰𩫏衣。其鍼曰鍤。鍤之言深入也。以爲鍫臿字者、失之遠矣。"}]},"鉥":{"expl":"綦鍼也。从金术聲。","rad":"金","fq":"食聿切","vol":"14","py":"shù","duan":[{"e":"綦鍼也。","n":"綦疑當作長。管子。一女必有一刀一錐。一箴一鉥。房注。鉥時橘切。長鍼也。玉篇亦曰長鍼。"}]},"鍼":{"expl":"所以縫也。从金咸聲。","rad":"金","fq":"職深切","vol":"14","py":"zhēn","duan":[{"e":"所㠯縫也。","n":"縫者、以鍼紩衣也。竹部箴下曰。綴衣箴也。以竹爲之、僅可聯綴衣。以金爲之、乃可縫衣。"}]},"鈹":{"expl":"大鍼也。一曰劒如刀裝者。从金皮聲。","rad":"金","fq":"敷羈切","vol":"14","py":"pī","duan":[{"e":"大鍼也。","n":"玄應曰。醫家用以破癰。"}]},"鎩":{"expl":"鈹有鐸也。从金殺聲。","rad":"金","fq":"所拜切","vol":"14","py":"shā","duan":[{"e":"鈹有𨰳也。","n":"鐔、劒鼻也。云鈹有鐔者、則知鈹有不爲鼻者矣。如刀裝之鈹不爲鼻者也。賈誼曰。鉏櫌棘矝、非銛於句戟長鎩。張衡曰。植鎩縣瞂。用戒不虞。曰長曰植、則鎩有柄。有柄故不爲鼻。薛綜解一曰鋌。似㒳刃刀。鋌謂其上出之鋒也。淮南書。飛鳥鎩羽。許注曰。鎩、殘也。左思賦亦曰鳥鎩翮。此等鎩字乃引申之義。鎩可殘羽、故凡見殘者曰鎩。公羊作摋。宋萬臂摋仇牧。碎其首。何云。側手擊曰摋。"}]},"鈕":{"expl":"印鼻也。从金丑聲。","rad":"金","fq":"女久切","vol":"14","py":"niǔ","duan":[{"e":"印鼻也。从金。丑聲。","n":"女久切。三部。"}]},"吪":{"expl":"動也。从口化聲。《詩》曰：“尚寐無吪。”","rad":"口","fq":"五禾切","vol":"02","py":"é","duan":[{"e":"動也。","n":"見釋詁、毛詩傳。"}]},"銎":{"expl":"斤釜穿也。从金𢀜聲。","rad":"金","fq":"曲恭切","vol":"14","py":"qiōnɡ","duan":[{"e":"斤斧穿也。","n":"穿者、通也。詩釋文作斧空也三字。謂斤斧之孔、所以受柄者。豳風毛傳曰。方銎曰斨。隋銎曰斧。隋謂狹長。"}]},"鈭":{"expl":"鈭錍，釜也。从金此聲。","rad":"金","fq":"即移切","vol":"14","py":"zī","duan":[{"e":"鈭錍。斧也。","n":"斧之一種也。㬪韵字。"}]},"錍":{"expl":"鈭錍也。从金卑聲。","rad":"金","fq":"府移切","vol":"14","py":"bēi","duan":[{"e":"鈭錍也。从金。卑聲。","n":"府移切。十六部。"}]},"鏨":{"expl":"小鑿也。从金从斬，斬亦聲。","rad":"金","fq":"藏濫切","vol":"14","py":"zàn","duan":[{"e":"小鑿也。从金斬。斬亦聲。","n":"藏濫切。八部。"}]},"鐫":{"expl":"穿木鐫也。从金雋聲。一曰琢石也。讀若瀸。","rad":"金","fq":"子全切","vol":"14","py":"juān","duan":[{"e":"破木鐫也。","n":"謂破木之器曰鐫也。因而破木謂之鐫矣。"}]},"鑿":{"expl":"穿木也。从金，𥽿省聲。","rad":"金","fq":"在各切","vol":"14","py":"záo","duan":[{"e":"所㠯穿木也。","n":"所以二字今補。穿木之器曰鑿。因之旣穿之孔亦曰鑿矣。考工記曰。量其鑿深以爲輻廣。九辨。圜鑿而方枘。音家讀曹報反。"}]},"銛":{"expl":"鍤屬。从金舌聲。讀若棪。桑欽讀若鐮。","rad":"金","fq":"息廉切","vol":"14","py":"xiān","duan":[{"e":"臿屬。","n":"臿大徐作鍤。則是郭衣鍼矣。臿者、舂去麥皮也。叚借爲鍫臿。卽上文田器之銚也。其屬亦曰銛。俗作杴。廣韵曰。古作？。或作㸝。皆卽銛字。引申爲銛利字。賈誼曰。莫邪爲鈍。鉛刀爲銛。漢書音義曰。銛、利也。又按方言曰。銛、取也。此引申叚借之義也。孟子。以言銛之。以不言銛之。今本誤作餂。"}]},"鈂":{"expl":"臿屬。从金冘聲。","rad":"金","fq":"直深切","vol":"14","py":"chén","duan":[{"e":"臿屬也。从金。冘聲。讀若沈。","n":"直深切。七部。"}]},"䤥":{"expl":"臿屬。从金危聲。一曰瑩𨮯也。讀若跛行。","rad":"金","fq":"過委切","vol":"14","py":"ɡuǐ","duan":[{"e":"臿金也。从金。危聲。","n":"過委切。十六部。"}]},"鐅":{"expl":"河内謂臿頭金也。从金敝聲。","rad":"金","fq":"芳滅切","vol":"14","py":"piě","duan":[{"e":"河内謂臿頭金也。","n":"郭注方言曰。江東謂鍫刃爲鐅。"}]},"𤦃":{"expl":"𤦃瓄，玉也。从玉來聲。","rad":"玉","fq":"落哀切","vol":"01","py":"lái","duan":[{"e":"𤦃瓄、","n":"逗。"}]},"噆":{"expl":"嗛也。从口朁聲。","rad":"口","fq":"子荅切","vol":"02","py":"cǎn","duan":[{"e":"嗛也。","n":"玄應引作銜也。嗛銜音義同。"}]},"錢":{"expl":"銚也。古田器。从金戔聲。《詩》曰：“庤乃錢鎛。”","rad":"金","fq":"即淺切","vol":"14","py":"jiǎn","duan":[{"e":"銚也。古者田器。","n":"詩毛傳云尒。見上文銚字下。云古田器者、古謂之錢。今則但謂之銚、謂之臿。不謂之錢。而錢以爲貨泉之名。"}]},"钁":{"expl":"大鉏也。从金矍聲。","rad":"金","fq":"居縛切","vol":"14","py":"jué","duan":[{"e":"大鉏也。","n":"鉏之大者曰钁。"}]},"鈐":{"expl":"鈐𨬍，大犂也。一曰類㭒。从金今聲。","rad":"金","fq":"巨淹切","vol":"14","py":"qián","duan":[{"e":"鈐𨬍、","n":"逗。"}]},"𨬍":{"expl":"鈐𨬍也。从金隋聲。","rad":"金","fq":"徒果切","vol":"14","py":"duò","duan":[{"e":"鈐𨬍也。从金。隋聲。","n":"徒果切。十七部。"}]},"鏺":{"expl":"兩刃，木柄，可以刈艸。从金發聲。讀若撥。","rad":"金","fq":"普活切","vol":"14","py":"pō","duan":[{"e":"㒳刃有木柄。可㠯乂艸。","n":"㒳刃如劒然。㒳邊有刃。乂、芟艸也。字或作刈。"}]},"鉵":{"expl":"㭒屬。从金，蟲省聲。讀若同。","rad":"金","fq":"徒冬切","vol":"14","py":"tónɡ","duan":[{"e":"枱屬也。","n":"枱大徐作㭒。今正。葢大徐耒下云耒㭒。而木部枱音弋之切。此部之誤亦同。"}]},"鉏":{"expl":"立薅所用也。从金且聲。","rad":"金","fq":"士魚切","vol":"14","py":"chú","duan":[{"e":"立薅斫也。","n":"斫也各本作所用也。今依廣韵正。薅者、披去田艸也。斫者、斤也。斤以斫木。此則斫田艸者也。云立薅者、古薅艸坐爲之。其器、曰槈。其柄短。若立爲之、則其器曰鉏。其柄長。槈之用淺。鉏之用可深。故曰斫。釋名曰。齊人謂其柄曰橿。橿然正直也。頭曰鶴。似鶴頭也。橿見木部。"}]},"䥯":{"expl":"㭒屬。从金罷聲。讀若嬀。","rad":"金","fq":"彼爲切","vol":"14","py":"bēi","duan":[{"e":"枱屬也。","n":"枱大徐作㭒。非。"}]},"鎌":{"expl":"鍥也。从金兼聲。","rad":"金","fq":"力鹽切","vol":"14","py":"lián","duan":[{"e":"鍥也。从金。兼聲。","n":"力鹽切。七部。俗作鐮。"}]},"鍥":{"expl":"鎌也。从金契聲。","rad":"金","fq":"苦結切","vol":"14","py":"qiè","duan":[{"e":"鎌也。","n":"方言曰。刈鉤、江淮陳楚之閒謂之鉊。或謂之鐹。自關而西或謂之鉤。或謂之鎌。或謂之鍥。鍥、郭音結。刀部曰。𠛎、鎌也。卽方言之刈鉤也。"}]},"吝":{"expl":"恨惜也。从口文聲。《易》曰：“以往吝。”","rad":"口","fq":"良刃切","vol":"02","py":"lìn","duan":[{"e":"恨惜也。","n":"慳吝亦恨惜也。"}]},"鉊":{"expl":"大𨮯也。从金召聲。鎌謂之鉊，張徹說。","rad":"金","fq":"止搖切","vol":"14","py":"zhāo","duan":[{"e":"大鎌也。","n":"見方言。"}]},"銍":{"expl":"穫禾短鎌也。从金至聲。","rad":"金","fq":"陟栗切","vol":"14","py":"zhì","duan":[{"e":"穫禾短鎌也。","n":"周頌。奄觀銍艾。傳曰。銍、穫也。按艾同乂。穫也。銍所以穫也。淺人刪所以二字。禹貢。二百里納銍。某氏曰。銍艾謂禾穗。亦謂所穫之穗爲銍。"}]},"鎭":{"expl":"博壓也。从金眞聲。","rad":"金","fq":"陟刃切","vol":"14","py":"zhèn","duan":[{"e":"博壓也。","n":"博當作簙。局戲也。壓當作厭。笮也。謂局戲以此鎭壓。如今賭錢者之有樁也。未知許意然否。引申之爲重也。安也。壓也。"}]},"鉆":{"expl":"𨮯銸也。从金占聲。一曰膏車𨮯鉆。","rad":"金","fq":"敕淹切","vol":"14","py":"chān","duan":[{"e":"鐵銸也。","n":"周禮典同注。飛鉆涅闇。疏引鬼谷子飛鉗。"}]},"銸":{"expl":"鉆也。从金𦔮聲。","rad":"金","fq":"陟葉切","vol":"14","py":"zhé","duan":[{"e":"鉆也。","n":"此與竹部籋義同音近。"}]},"鉗":{"expl":"以𨮯有所劫束也。从金甘聲。","rad":"金","fq":"巨淹切","vol":"14","py":"qián","duan":[{"e":"㠯鐵有所劫束也。","n":"劫者、以力脅止也。束者、縛也。"}]},"釱":{"expl":"𨮯鉗也。从金大聲。","rad":"金","fq":"特計切","vol":"14","py":"dì","duan":[{"e":"鐵鉗也。","n":"鐵御覽作脛。平準書釱左趾。釱、踏腳鉗也。狀如跟衣。箸足下。重六斤以代刖。"}]},"鋸":{"expl":"槍唐也。从金居聲。","rad":"金","fq":"居御切","vol":"14","py":"jù","duan":[{"e":"槍唐也。","n":"槍唐葢漢人語。廣韵引古史考曰。孟莊子作鋸。"}]},"鐕":{"expl":"可以綴著物者。从金朁聲。","rad":"金","fq":"則參切","vol":"14","py":"zān","duan":[{"e":"可㠯綴箸物者。","n":"喪大記。君裏棺用朱綠。用襍金？。大夫裏棺用玄綠。用牛骨？。注。？所以琢箸裏。按今謂釘者皆是。非獨棺釘也。"}]},"錐":{"expl":"銳也。从金隹聲。","rad":"金","fq":"藏追切","vol":"14","py":"zhuī","duan":[{"e":"銳也。","n":"此門聞也、戸護也之例。"}]},"各":{"expl":"異辭也。从口、夊。夊者，有行而止之，不相聽也。","rad":"口","fq":"古洛切","vol":"02","py":"ɡè","duan":[{"e":"異䛐也。","n":"䛐者意內而言外。異爲意。各爲言也。"}]},"鑱":{"expl":"銳也。从金毚聲。","rad":"金","fq":"士銜切","vol":"14","py":"chán","duan":[{"e":"銳也。从金。毚聲。","n":"士銜切。八部。"}]},"銳":{"expl":"芒也。从金兌聲。","rad":"金","fq":"以芮切","vol":"14","py":"ruì","duan":[{"e":"芒也。","n":"芒者、艸耑也。艸耑必鑯。故引申爲芒角字。今俗用鋒鋩字、古衹用夆芒。"}]},"鏝":{"expl":"𨮯杇也。从金曼聲。","rad":"金","fq":"母官切","vol":"14","py":"màn","duan":[{"e":"鐵杇也。","n":"杇所以涂也。秦謂之杇。關東謂之槾。从木。是則木爲者曰杇。金爲者曰鏝。許以从木从金别之也。戰國策。豫讓刃其杅。杅而有刃。知古者通偁。"}]},"鑽":{"expl":"所以穿也。从金贊聲。","rad":"金","fq":"借官切","vol":"14","py":"zuàn","duan":[{"e":"所㠯穿也。","n":"本是器名。因之謂穿亦曰鑽。"}]},"鑢":{"expl":"錯銅𨮯也。从金慮聲。","rad":"金","fq":"良據切","vol":"14","py":"lǜ","duan":[{"e":"厝銅鐵也。","n":"厝作錯。誤厝者、厲石也。故以爲凡砥厲之字。厲銅鐵謂之鑢。故其字从金。周禮注作䥨。"}]},"銓":{"expl":"衡也。从金全聲。","rad":"金","fq":"此緣切","vol":"14","py":"quán","duan":[{"e":"稱也。","n":"稱各本作衡。今正。禾部稱、銓也。與此爲轉注。乃全書之通例。稱卽今秤字。衡者、牛觸橫大木其角。權衡字經典用之。許不尒。葢古權衡二字皆叚借字。權爲垂之叚借。古十四部與十七部合音。是以若干爲若柯。桓表爲和表。斟灌爲斟戈。毛詩觀爲多之借。單聲之鼉鄲入戈韵。垂古音陀。叚權爲之。俗乃作錘。若衡則叚借之橫字。權衡者、一直一橫之謂。"}]},"銖":{"expl":"權十分黍之重也。从金朱聲。","rad":"金","fq":"市朱切","vol":"14","py":"zhū","duan":[{"e":"權十絫黍之重也。","n":"各本作權十分黍之重也。今正。權、五權也。五權、銖兩斤鈞䄷也。厽部曰。絫、十黍之重也。此云銖、權十絫黍之重也。㒳部曰。兩、二十四銖爲一兩。斤本無其字。以斫木之斤爲之。十六兩也。鈞、三十斤也。禾部曰。䄷、百二十斤也。按許說與漢律曆志合。志曰。一龠容千二百黍。重十二銖。㒳之、二十四銖爲兩。十六兩爲斤。三十斤爲鈞。四鈞爲石。此許所本。言十絫黍者、謂百黍也。必言黍者、蒙十黍之重爲絫而言。又使兩、斤、鈞、䄷、黍數可計也。若禾部稱下云。十二粟爲一分。十二分爲一銖。則用淮南天文訓。與律曆志别爲一說、粟者、禾實也。以今禾黍驗之。粟輕於黍遠甚。程氏瑶田說。"}]},"鋝":{"expl":"十銖二十五分之十三也。从金寽聲。《周禮》曰：“重三鋝。”北方以二十兩爲鋝。","rad":"金","fq":"力錣切","vol":"14","py":"lüè","duan":[{"e":"十一銖二十五分銖之十三也。","n":"各本十一銖作十銖。二十五分銖奪銖字。今依尙書音義、漢蕭望之傳注、廣韵十七薛正。十一銖、計黍千一百。云二十五分銖之十三者、此用命分之法。百黍以四除之。凡二十五而除盡。命爲二十五分。二十五分之十三。得五十二黍。命爲二十五分銖之十三。合十一銖。共爲黍千一百五十二。"}]},"鍰":{"expl":"鋝也。从金爰聲。《罰書》曰：“列百鍰。”","rad":"金","fq":"戶關切","vol":"14","py":"huán","duan":[{"e":"鋝也。","n":"尚書釋文引六鋝也。六誤衍。鄭注攷工記曰。許叔重說文解字云。鋝、鍰也。今東萊謂大半兩爲鈞。十鈞爲環。環重六兩大半兩。鍰鋝似同矣。周禮職金正義曰。夏侯、歐陽說。墨罰疑赦。其罰百率。古以六兩爲率。古尚書說百鍰。鍰者、率也。一率、十一銖二十五分銖之十三也。百鍰爲三斤。鄭玄以爲古之率多作鍰。玉裁按古文尚書吕㓝作鍰。今文尙書作率。亦作𨕖。或作饌。史記周本紀作率。尙書大傳一𩜹六兩、作𩜹。漢書蕭望之傳金𨕖之法、作𨕖。皆今文尚書也。今文謂率六兩。說古文者謂鍰六兩大半兩。許用古文說者也。百鍰爲三斤。正與十一銖二十五分銖之十三數相合。"}]},"錙":{"expl":"六銖也。从金甾聲。","rad":"金","fq":"側持切","vol":"14","py":"zī","duan":[{"e":"六銖也。","n":"爲黍六百。鄭注禮記儒行曰。八兩爲鍿。高注詮言訓曰。六兩曰鍿。倍鍿曰錘。風俗通義曰。銖六則錘。錘、暉也。二錘則鍿。鍿、熾也。二鍿則兩也。廣韵曰。八銖爲鍿。其說皆乖異。不與許合。惟高注說山訓曰。六銖曰鍿。八銖曰錘。與許說合。與詮言注乖異。疑說山之注乃許注之僅存者也。"}]},"錘":{"expl":"八銖也。从金垂聲。","rad":"金","fq":"直垂切","vol":"14","py":"chuí","duan":[{"e":"八銖也。","n":"爲黍八百。諸家說異見上。後人謂稱之權爲錘。漢志所謂以輕重爲宜。圜而環之。今之肉倍好者也。古字衹當作𡍮。謂有物𡍮之而使平。"}]},"鈞":{"expl":"三十斤也。从金勻聲。","rad":"金","fq":"居勻切","vol":"14","py":"jūn","duan":[{"e":"三十斤也。","n":"斤者、十六兩也。三十斤、爲銖萬一千五百二十。爲絫二十七萬六千四百八十。漢志曰。鈞者、均也。陽施其氣。陰化其物。皆得其成就平均也。按古多叚鈞爲均。"}]},"鈀":{"expl":"兵車也。一曰𨮯也。《司馬法》：“晨夜内鈀車。”从金巴聲。","rad":"金","fq":"伯加切","vol":"14","py":"bā","duan":[{"e":"兵車也。从金。巴聲。","n":"伯加切。古音在五部。"}]},"鐲":{"expl":"鉦也。从金蜀聲。軍法：司馬執鐲。","rad":"金","fq":"直角切","vol":"14","py":"zhuó","duan":[{"e":"鉦也。","n":"周禮𡔷人。以金鐲節𡔷。鄭注。鐲、鉦也。形如小鐘。軍行鳴之以爲𡔷節。大鄭云。讀如濁其源之濁。"}]},"鈴":{"expl":"令丁也。从金从令，令亦聲。","rad":"金","fq":"郎丁切","vol":"14","py":"línɡ","duan":[{"e":"令丁也。","n":"令平聲。令丁㬪韵字。晉語十一注。丁寧、令丁。謂鉦也。吳語十九。丁寧、令丁。謂鉦也。今國語皆奪令丁字。而存於舊音補音。廣韵曰。鈴似鐘而小。然則鐲鈴一物也。古謂之丁寧。漢謂之令丁。在旂上者亦曰鈴。"}]},"鉦":{"expl":"鐃也。似鈴，柄中，上下通。从金正聲。","rad":"金","fq":"諸盈切","vol":"14","py":"zhēnɡ","duan":[{"e":"鐃也。佀鈴柄中。","n":"句。"}]},"鐃":{"expl":"小鉦也。軍法：卒長執鐃。从金堯聲。","rad":"金","fq":"女交切","vol":"14","py":"náo","duan":[{"e":"小鉦也。","n":"鉦鐃一物。而鐃較小。渾言不别。析言則有辨也。周禮言鐃不言鉦。詩言鉦不言鐃。不得以大小别之。大司馬。仲冬大閱。乃𡔷退。鳴鐃且卻。左傳。陳子曰。吾聞𡔷不聞金。亦謂聞𡔷進、聞鐃退也。"}]},"鐸":{"expl":"大鈴也。軍法：五人爲伍，五伍爲兩，兩司馬執鐸。从金睪聲。","rad":"金","fq":"徒洛切","vol":"14","py":"duó","duan":[{"e":"大鈴也。","n":"𡔷人。以金鐸通𡔷。注。鐸、大鈴也。謂鈴之大者。說者謂軍法所用金鈴金舌、謂之金鐸。施令時所用金鈴木舌、則謂之木鐸。按大司馬職曰振鐸。又曰摝鐸。鄭謂摝、掩上振之。鐸之制同鈴。"}]},"鑮":{"expl":"大鐘，湻于之屬，所以應鐘磬也。堵以二，金樂則鼓鏄應之。从金薄聲。","rad":"金","fq":"匹各切","vol":"14","py":"bó","duan":[{"e":"大鐘。𤂸于之屬。所㠯應鐘磬也。","n":"大鐘下當有也字。鄭注周禮、禮經皆云。鎛似鐘而大。國語韋注云。鎛、小鐘也。葢誤鄭云似鐘、則非鐘也。故許旣云大鐘、而又云淳于之屬。淳于國語、周禮注作錞于。周禮作錞、乃矛㦸之鐏也。𡔷人。以金錞和鼓。注曰。錞、錞于也。圜如碓頭。大上小下。樂作鳴之。與鼓相和。疏謂出於漢之大予樂官。韋注吳語曰。唐尙書云錞于、鐲。非也。錞于與鐲各異物。今按古鐘制隋圜。錞于如碓頭正圜。許云淳于之屬。葢鑮正圜大於編鐘。爲後代鐘式正圜之始。云所以應鐘磬者、大射儀。笙磬西面。其南笙鐘。其南鑮。頌磬東面。其南頌鐘。其南鑮。鐘磬編縣。鑮特縣。於此知鑮所以應鐘磬。淳于以和鼓。事正相類。"}]},"鏞":{"expl":"大鐘謂之鏞。从金庸聲。","rad":"金","fq":"余封切","vol":"14","py":"yōnɡ","duan":[{"e":"大鐘謂之鏞。","n":"爾雅文。大雅、商頌毛傳皆同。惟商頌字作庸。古文叚借。考工記曰。大鐘十分其𡔷閒以其一爲之厚。"}]},"唁":{"expl":"弔生也。从口言聲。《詩》曰：“歸唁衞侯。”","rad":"口","fq":"魚變切","vol":"02","py":"yàn","duan":[{"e":"弔生也。","n":"庸風。歸唁衞矦。春秋。齊矦唁公于野井。穀梁傳、毛傳皆云。弔失國曰唁。此言弔生者。以弔生爲唁、別於弔死爲弔也。何注公羊云。弔亡國曰唁。弔死曰弔。與此相發明。今本公羊注弔死國曰弔。衍國字。"}]},"鐘":{"expl":"樂鐘也。秋分之音，物穜成。从金童聲。古者垂作鐘。","rad":"金","fq":"職茸切","vol":"14","py":"zhōnɡ","duan":[{"e":"樂鐘也。","n":"當作金樂也。"}]},"鈁":{"expl":"方鐘也。从金方聲。","rad":"金","fq":"府良切","vol":"14","py":"fānɡ","duan":[{"e":"方鐘也。","n":"廣韵曰。鑊屬。今義也。"}]},"鎛":{"expl":"鎛鱗也。鐘上橫木上金華也。一曰田器。从金尃聲。《詩》曰：“庤乃錢鎛。”","rad":"金","fq":"補各切","vol":"14","py":"bó","duan":[{"e":"鎛鱗也。","n":"也衍。"}]},"鍠":{"expl":"鐘聲也。从金皇聲。《詩》曰：“鐘鼓鍠鍠。”","rad":"金","fq":"乎光切","vol":"14","py":"huánɡ","duan":[{"e":"鐘聲也。从金。𦤃聲。","n":"乎光切。十部。"}]},"鎗":{"expl":"鐘聲也。从金倉聲。","rad":"金","fq":"楚庚切","vol":"14","py":"chēnɡ","duan":[{"e":"鎗鏓。","n":"二字各本無。今依全書例補之。雙聲字也。"}]},"鏓":{"expl":"鎗鍃也。一曰大鑿，平木者。从金悤聲。","rad":"金","fq":"倉紅切","vol":"14","py":"cōnɡ","duan":[{"e":"鎗鏓也。","n":"學記曰。善待問者如撞鐘。叩之以小者則小鳴。叩之以大者則大鳴。待其松容。然後盡其聲。注曰。松容謂重撞擊也。鎗鏓善狀鐘聲。今尟用此者。"}]},"錚":{"expl":"金聲也。从金爭聲。","rad":"金","fq":"側莖切","vol":"14","py":"zhēnɡ","duan":[{"e":"金聲也。","n":"後漢書曰。鐵中錚錚。鐵堅則聲異也。玉篇云。錚同鎗。非是。"}]},"鏜":{"expl":"鐘鼓之聲。从金堂聲。《詩》曰：“擊鼓其鏜。”","rad":"金","fq":"上郎切","vol":"14","py":"tānɡ","duan":[{"e":"鐘𡔷之聲也。","n":"𡔷部曰。？、𡔷聲也。引詩擊𡔷其？。爲其字之从𡔷也。此引詩擊𡔷其鏜。葢有韓、毛之異與。邶風傳曰。鏜、擊𡔷聲也。許以其从金、故先之以鐘曰鐘𡔷之聲。相如賦作闛𩍈。司馬法曰。𡔷聲不過閶。皆叚借字。"}]},"鑋":{"expl":"金聲也。从金輕聲。讀若《春秋傳》曰“𨆪而乘它車”。","rad":"金","fq":"苦定切","vol":"14","py":"qìnɡ","duan":[{"e":"金聲也。从金。輕聲。","n":"苦定切。十一部。篇、韵皆有去盈切。"}]},"鐔":{"expl":"劒鼻也。从金覃聲。","rad":"金","fq":"徐林切","vol":"14","py":"xín","duan":[{"e":"劒鼻也。","n":"攷工記、曲禮、少儀所謂劒首也。通藝錄曰。劒鼻謂之鐔。鐔謂之珥。又謂之環。一謂之劒口。有孔曰口。視其旁如耳然曰珥。面之曰鼻。對末言之曰首。玉裁按莊子說劒凡五事。曰鋒鍔脊鐔夾。鋒者其耑。許書之鏠字。左傳所謂劒末也。鍔者其刃。許之？字。脊者其身中隆處。記因之有㒳從臘廣之偁也。鐔者其鼻。玉部所謂設？處也。夾者其柄。鐔在其耑。記所謂莖。許刀部所謂㓡也。印鼻、劒鼻、瓜鼻皆謂鼻者。鼻猶初也。始生子爲鼻子。"}]},"哀":{"expl":"閔也。从口衣聲。","rad":"口","fq":"烏開切","vol":"02","py":"āi","duan":[{"e":"閔也。","n":"閔、弔者在門也。引伸之凡哀皆曰閔。"}]},"鏌":{"expl":"鏌釾也。从金莫聲。","rad":"金","fq":"慕各切","vol":"14","py":"mò","duan":[{"e":"鏌釾、","n":"逗。"}]},"釾":{"expl":"鏌釾也。从金牙聲。","rad":"金","fq":"以遮切","vol":"14","py":"yé","duan":[{"e":"鏌釾也。从金。牙聲。","n":"以遮切。古音在五部。曡韵字也。漢郭究碑作鋣。杜篤傳注引同。"}]},"鏢":{"expl":"刀削末銅也。从金㶾聲。","rad":"金","fq":"撫招切","vol":"14","py":"biāo","duan":[{"e":"刀削末銅也。","n":"削者、刀鞞也。私妙切。俗作韒。刀室之末。以銅飾之曰鏢。鞞用革。故其末飾銅耳。而高誘注天文訓云。標讀如刀末爲鏢。通俗文曰。刀鋒爲𨭚。皆自刀言、不自刀室言。與許說異矣。"}]},"鈒":{"expl":"鋋也。从金及聲。","rad":"金","fq":"穌合切","vol":"14","py":"sà","duan":[{"e":"鋋也。","n":"廣韵云。？也。又云。鈒鏤。皆非古義。"}]},"鋋":{"expl":"小矛也。从金延聲。","rad":"金","fq":"市連切","vol":"14","py":"chán","duan":[{"e":"小矛也。","n":"矛者、酋矛。長二丈。建於兵車者也。其小者可用戰曰鋋。坶誓立爾矛是也。鄭風、魯頌有二矛。秦風有厹矛。方言曰。矛或謂之鋋。師古注漢書曰。鋋、鐵把短矛也。"}]},"鈗":{"expl":"侍臣所執兵也。从金允聲。《周書》曰：“一人冕，執鈗。”讀若允。","rad":"金","fq":"余凖切","vol":"14","py":"yǔn","duan":[{"e":"侍臣所執兵也。从金。允聲。周書曰。一人冕執鈗。讀若允。","n":"按顧命作執銳。僞孔傳云。銳、矛屬也。陸氏音義云。銳以稅反。不言說文作鈗、讀若允。與其說文作黺、作？、作？、作凭、作㓃、詳引許書之例不合。此可疑一也。顧氏玉篇無鈗字、有銳字。云徒會切、矛也。在鈒鋋之下、鉈鏦錟之上。正與說文列字次弟同。惟易鈗爲銳耳。此可疑二也。漢書長揚賦。兖鋋瘢耆。張佖引說文同今本以釋兖。謂兖當作鈗。是說文今本至南唐張佖乃見之。與小徐本同。此可疑三也。廣韵十七準無鈗字。惟十四泰銳杜外切、矛也。是可知陸法言切韵、孫愐唐韵皆無鈗矣。此可疑四也。集韵十四太銳徒外切、矛屬。毛氏禮部韵略、黃氏韵會皆同。以至毛居正六經正誤云。銳、矛屬。許氏說文音兌。廣韵徒外切。今音以稅切、非也。當從說文廣韵"}]},"鉈":{"expl":"短矛也。从金它聲。","rad":"金","fq":"食遮切","vol":"14","py":"shī","duan":[{"e":"短矛也。","n":"方言曰。矛、吳揚江淮南楚五湖之閒謂之鍦。或謂之鋋。或謂之縱。按鍦卽鉈字。廣雅作？。晉書。丈八鉈矛左右盤。"}]},"鏦":{"expl":"矛也。从金從聲。","rad":"金","fq":"七恭切","vol":"14","py":"cōnɡ","duan":[{"e":"矛也。从金。從聲。","n":"七恭切。九部。今楚江切。"}]},"錟":{"expl":"長矛也。从金炎聲。讀若老耼。","rad":"金","fq":"徒甘切","vol":"14","py":"tán","duan":[{"e":"長矛也。","n":"本義也。史記。錟戈在後。又非錟於句？長鎩。叚爲銛利字也。劉伯莊云。四廉反。而毛晃讀同剡。"}]},"鏠":{"expl":"兵耑也。从金逢聲。","rad":"金","fq":"敷容切","vol":"14","py":"fēnɡ","duan":[{"e":"兵耑也。","n":"兵械也。耑、物初生之題。引申爲凡物之顚與末。凡金器之尖曰鏠。俗作鋒。古亦作夆。山之顚曰夆。古無峯字。"}]},"嗁":{"expl":"號也。从口虒聲。","rad":"口","fq":"杜兮切","vol":"02","py":"tí","duan":[{"e":"号也。","n":"号各本作號。今正。号下曰。痛聲也。此可證嗁号與嘑號不同字也。号、痛聲。哭、哀聲。痛在內。哀形於外。此嗁與哭之別也。喪大記。始卒。主人啼。兄弟哭。婦人哭踊。注。悲哀有㴱淺也。若嬰兒中路失母。能勿啼乎。按鄭用襍記語也。嗁俗作啼。士喪禮作諦。古多假諦爲嗁。"}]},"錞":{"expl":"矛𢧢柲下銅，鐏也。从金𦎫聲。《詩》曰：“叴矛沃𨯢。”","rad":"金","fq":"徒對切","vol":"14","py":"duì","duan":[]},"鐏":{"expl":"柲下銅也。从金尊聲。","rad":"金","fq":"徂寸切","vol":"14","py":"zùn","duan":[{"e":"柲下銅也。","n":"曲禮曰。進戈者前其鐏。後其刃。進矛？者前其鐓。注云。後刃、敬也。三兵鐏鐓雖在下。猶爲首也。銳底曰鐏。取其鐏地。平底曰鐓。取其鐓地。按鐏地、可入地。鐓地、箸地而已。知古鐓讀如敦也。鄭析言之。許渾言不析者、葢銳鈍皆可爲。非必戈銳而矛？鈍也。曲禮或互文耳。"}]},"鏐":{"expl":"弩眉也。一曰黃金之美者。从金翏聲。","rad":"金","fq":"力幽切","vol":"14","py":"liú","duan":[{"e":"弩睂也。从金。翏聲。","n":"力幽切。三部。"}]},"𨩀":{"expl":"矢。金鏃翦羽謂之鏃。从金矦聲。","rad":"金","fq":"乎鉤切","vol":"14","py":"hóu","duan":[{"e":"矢金族翦羽謂之鍭。","n":"族各本作鏃。今正。？部曰。族、矢鏠也。束之族族也。是可以證矣。大雅傳曰。？矢參亭。參亭者、考工記所謂一在前、二在後也。釋器曰。金鏃翦羽謂之？。"}]},"鏑":{"expl":"矢鏠也。从金啻聲。","rad":"金","fq":"都歴切","vol":"14","py":"dí","duan":[{"e":"矢鏠也。","n":"謂矢族之入物者。古亦作鍉。是聲啻聲同部也。"}]},"鎧":{"expl":"甲也。从金豈聲。","rad":"金","fq":"苦亥切","vol":"14","py":"kǎi","duan":[{"e":"甲也。","n":"甲本十干之首。从木戴孚甲之象。因引申爲甲冑字。古曰甲。漢人曰鎧。故漢人以鎧釋甲。"}]},"釬":{"expl":"臂鎧也。从金干聲。","rad":"金","fq":"矦旰切","vol":"14","py":"hàn","duan":[{"e":"臂鎧也。","n":"管子戒曰。弛弓脫釬。房注。釬所以扞弦。按房非也。禮射時箸左臂者謂之遂。亦謂之拾。若戰陣所用臂鎧謂之釬。㒳臂皆箸之。又非無事時所箸臂衣謂之韝也。"}]},"錏":{"expl":"錏鍜，頸鎧也。从金亞聲。","rad":"金","fq":"烏牙切","vol":"14","py":"yā","duan":[{"e":"錏鍜、","n":"逗。曡韵字也。"}]},"鍜":{"expl":"錏鍜也。从金叚聲。","rad":"金","fq":"乎加切","vol":"14","py":"xiá","duan":[{"e":"錏鍜也。从金。叚聲。","n":"乎加切。古音在五部。"}]},"鐧":{"expl":"車軸𨮯也。从金閒聲。","rad":"金","fq":"古莧切","vol":"14","py":"jiàn","duan":[{"e":"車軸鐵也。","n":"此與舝異義。舝者、車軸耑鍵也。謂以鐵鐕毌軸頭而制之也。車軸之在釭中者、以鐵鍱裹之謂之鐗。釋名曰。？、閒也。閒釭軸之閒。使不相摩也。按釭中亦以鐵鍱裹之。則鐵與鐵相摩。而轂軸之木皆不傷。乃名鐵之在軸者曰鐗。在轂者曰釭。"}]},"嗀":{"expl":"歐皃。从口㱿聲。《春秋傳》曰：“君將嗀之。”","rad":"口","fq":"許角切","vol":"02","py":"hù","duan":[{"e":"歐皃。","n":"今俗語如此。"}]},"釭":{"expl":"車轂中𨮯也。从金工聲。","rad":"金","fq":"古雙切","vol":"14","py":"ɡānɡ","duan":[{"e":"車轂中鐵也。","n":"木部曰。橾、車轂中空也。今攷工記作藪。大鄭云。藪讀爲蜂藪之藪。謂轂空壺中也。按壺中謂三十輻葘所趨。非以鐵鍱裏之。懼其易傷也。其裏之之鐵鍱曰釭。因之壺中亦曰釭。釋名曰。釭、空也。其中空也。方言曰。自關而西謂之釭。引申之、凡空中可受者皆曰釭。漢書曰昭陽宮璧帶爲黃金釭、函藍田璧是也。俗謂膏燈爲釭。亦取凹處盛膏之意。如方言釭亦曰鍋也。釭有鐵、則軸又易傷。故又有鐗。"}]},"銴":{"expl":"車樘結也。一曰銅生五色也。从金折聲。讀若誓。","rad":"金","fq":"時制切","vol":"14","py":"shì","duan":[{"e":"車樘結也。","n":"木部曰。樘、衺柱也。古音堂。今音丑庚切。考工記注曰。䟫讀如牚距之牚、車牚之牚。然則車樘、漢人語也。急就篇、釋名作棠。劉𤋮曰。棠、？也。在車㒳旁。？？使不得進卻也。今按其結曰銴。其制未詳。葢可以系車？者。"}]},"釳":{"expl":"乘輿馬頭上防𨥊。插以翟尾、𨮯翮，象角。所以防綱羅𨥊去之。从金气聲。","rad":"金","fq":"許訖切","vol":"14","py":"xì","duan":[{"e":"椉輿馬頭上防𨥊。","n":"乗輿、天子之車。防古多作方。方𨥊者其名。下言其制。"}]},"鑾":{"expl":"人君乘車，四馬鑣，八鑾鈴，象鸞鳥聲，和則敬也。从金，从鸞省。","rad":"金","fq":"洛官切","vol":"14","py":"luán","duan":[{"e":"人君椉車四馬鑣八鑾。","n":"鑣上當有四字。每鑣二鑾。四馬故四鑣。四鑣故八鑾也。鑣者、馬銜也。銜者、馬勒口中也。許云人君乗車四馬者、人君兼天子諸侯言。此破天子駕六之說也。五經異義。易孟、京、春秋公羊說。天子駕六。毛詩說。天子至大夫同駕四。士駕二。詩云。駟騵彭彭。武王所乗。龍旂承祀。六轡耳耳。魯僖所乗。四牡騑騑。周道倭遲。大夫所乗。謹按禮王度記曰。天子駕六。諸侯與卿大夫駕四。大夫駕三。士駕二。庶人駕一。與易、春秋同。鄭駁曰。周禮校人掌王馬之政。凡頒良馬而養乗之。乗馬一師四圉。四馬爲乗。此一圉養一馬、而一師監之也。尙書顧命。諸侯入應門。皆布乗黃朱。言獻四黃馬朱鬛也。旣實周天子駕六。校人則何不以馬與圉以六爲數。顧命諸侯何以不獻六"}]},"鉞":{"expl":"車鑾聲也。从金戉聲。《詩》曰：“鑾聲鉞鉞。”","rad":"金","fq":"呼會切","vol":"14","py":"huì","duan":[{"e":"車鑾聲也。从金。戉聲。詩曰。鑾聲鉞鉞。","n":"徐鉉等曰。今俗作鐬。以鉞作斧戉之戉。非是。呼會切。十五部。玉裁按詩采菽。鸞聲嘒嘒。傳曰。中節也。泮水。鸞聲噦噦。傳曰。言其聲也。釋文不言有作鐬者。鼎臣何以云今作鐬與。攷玉篇、廣韵皆有鐬字。注呼會切。鈴聲也。而泮水噦噦呼會反。鑾聲卽鈴聲。然則古本毛詩非無作鐬鐬者。故篇、韵猶存其說。鐬爲正字。采菽嘒嘒呼惠反。殆叚借字。許訓噦爲气啎。見於內則。詩不得以狀鑾聲。或叚借可也。以戉聲之字狀鸞聲。尤殊不類。鐬从歳聲。歳从戌聲。戌聲歳聲則與鑾聲相似。詩言和鑾雝雝。宫聲也。車緩行。舒徐聲也。八鑾鎗鎗。鑾聲銊銊。鳴玉鑾之秋秋。商聲也。車將止。舌與鈴相摩聲也。疑古毛詩泮水本作銊銊。後乃變爲鐬字。許所據作銊、戌聲。辛"}]},"鐊":{"expl":"馬頭飾也。从金陽聲。《詩》曰：“鉤膺鏤鐊。”一曰鍱，車輪𨮯。","rad":"金","fq":"與章切","vol":"14","py":"yánɡ","duan":[{"e":"馬頭飾也。","n":"韓奕傳曰。鏤鍚、有金鏤其鍚也。箋云。睂上曰鍚。刻金飾之。今當盧也。按人睂目閒廣揚曰揚。故馬睂上飾曰鍚。盧卽顱字。"}]},"銜":{"expl":"馬勒口中。从金从行。銜，行馬者也。","rad":"金","fq":"戶監切","vol":"14","py":"xián","duan":[{"e":"馬勒口中也。","n":"也當作者。革部曰。勒、馬頭落銜也。落謂絡其頭。銜謂關其口。統謂之勒也。其在口中者謂之銜。落以𩊚爲之。𩊚、生革也。銜以鐵爲之。故其字从金。引申爲凡口含之用。"}]},"鑣":{"expl":"馬銜也。从金麃聲。","rad":"金","fq":"補嬌切","vol":"14","py":"biāo","duan":[{"e":"馬銜也。","n":"馬銜橫毌口中。其㒳耑外出者系以鑾鈴。又巾部曰。幩、馬纏鑣扇汗也。葢扇汗亦繞於㒳耑。"}]},"鉣":{"expl":"組帶𨮯也。从金，劫省聲。讀若劫。","rad":"金","fq":"居怯切","vol":"14","py":"jié","duan":[{"e":"組帶鐵也。","n":"按組上疑當有馬字。"}]},"鈇":{"expl":"莝斫刀也。从金夫聲。","rad":"金","fq":"甫無切","vol":"14","py":"fū","duan":[{"e":"斫莝刀也。","n":"各本作莝斫刀。今按尹翁歸傳注作斫莝刀。後漢馮魴傳注但云莝刀。近是。而尙奪字。莝者、斬芻也。斬芻之刀今之㔍刀。禮記屢言鈇鉞。秋官掌戮注曰。斬以鈇鉞。若今要斬。殺以刀刃。若今棄市。古多訓鈇爲椹質。文𨕖𠕋魏公九錫文。引倉頡篇鈇、椹質也。鉞、斧也。公羊傳曰。不忍加之鈇鑕。鑕卽質。何休云。斬𦝫之㓝。范睢曰。匈當椹質。要待斧鉞。漢王訢傳。暴勝之將斬訢。訢已伏質而仰言。因壯而貰之。然則斬人皆胸伏椹質。說倉頡者謂椹質爲鈇。以古詩斬芻之質謂之稾砧。隱語夫字言之。說倉頡者、是也。然則許此解當云莝刀質也。俗人不得其解。因删去質字耳。若五經文字云。鈇音斧。又與斧同。則甚繆誤。後漢獻帝紀。加鈇鉞虎賁。注引倉頡篇鈇、斧也"}]},"咼":{"expl":"口戾不正也。从口冎聲。","rad":"口","fq":"苦媧切","vol":"02","py":"kuā","duan":[{"e":"口戾不正也。","n":"通俗文。斜戾曰咼。"}]},"釣":{"expl":"鉤魚也。从金勺聲。","rad":"金","fq":"多嘯切","vol":"14","py":"diào","duan":[{"e":"鉤魚也。","n":"鉤者、曲金也。以曲金取魚謂之釣。"}]},"𨫔":{"expl":"羊箠耑有𨮯。从金埶聲。讀若至。","rad":"金","fq":"脂利切","vol":"14","py":"zhì","duan":[{"e":"羊𥴓也。耑有鐵。","n":"也字依廣韵補。？者、所以擊馬也。因之擊羊者謂之羊？。其耑有鐵。故字从金。淮南道應訓曰。白公罷朝而立。倒杖策。錣上貫頤。高注云。策、馬捶。端有針以刺馬謂之錣。倒杖策、故錣貫頤也。又氾論訓注曰。錣椯頭箴。按錣卽許之？字。捶同箠。椯者、箠也。馬箠亦耑有鐵。其用同也。曲禮所謂策彗䘏勿。"}]},"鋃":{"expl":"鋃鏜，瑣也。从金良聲。","rad":"金","fq":"魯當切","vol":"14","py":"lánɡ","duan":[{"e":"鋃鐺、","n":"逗。曡韵字。"}]},"鐺":{"expl":"鋃鏜也。从金當聲。","rad":"金","fq":"都郎切","vol":"14","py":"dānɡ","duan":[{"e":"鋃鐺也。从金。當聲。","n":"都郎切。十部。今俗用爲酒鎗字。楚庚切。"}]},"鋂":{"expl":"大瑣也。一環貫二者。从金每聲。《詩》曰：“盧重鋂。”","rad":"金","fq":"莫桮切","vol":"14","py":"méi","duan":[{"e":"大環也。一環毌二者。","n":"環各本作瑣。毌原作貫。今正。盧令三章曰。盧重鋂。傳曰。鋂、一環貫二也。上文重環傳云。子母環、謂以一環毌一環。此云一環毌二。以一毌二、則一環差大。故許知爲大環也。玉篇、廣韵皆云大環。用許之舊。詩正義引說文鋂、環也。一環貫二。由其以大環貫小環釋子母環。遂刪此大字而云環。固未誤也。非綿連者不得云瑣。犬飾以纓環不以瑣。且犬旣有紲矣。何爲施以大銀鐺乎。○韵會一環貫二者五字在每聲之下。葢此五字後人所增。"}]},"鍡":{"expl":"鍡鑸，不平也。从金畏聲。","rad":"金","fq":"烏賄切","vol":"14","py":"wěi","duan":[{"e":"鍡鑸、","n":"逗。㬪韵字。"}]},"鑸":{"expl":"鍡鑸也。从金壘聲。","rad":"金","fq":"洛猥切","vol":"14","py":"lěi","duan":[{"e":"鍡鑸也。从金。壘聲。","n":"洛猥切。十五部。"}]},"鎎":{"expl":"怒戰也。从金氣聲。《春秋傳》曰：“諸矦敵王所鎎。”","rad":"金","fq":"許旣切","vol":"14","py":"xì","duan":[{"e":"怒戰也。","n":"怒則有氣。戰則用兵。故其字从金氣、氣者、气之叚借字也。"}]},"鋪":{"expl":"箸門鋪首也。从金甫聲。","rad":"金","fq":"普胡切","vol":"14","py":"pū","duan":[{"e":"箸門抪首也。","n":"抪各本作鋪。依舞賦李注正。手部曰。抪、捫持也。捫持者、古者箸門爲蠃形。謂之椒圖。是曰鋪首。以金爲之、則曰金鋪。以靑畫瑣文鏤中、則曰靑瑣。見西京、蜀都賦注。按大雅鋪敦淮濆箋云。陳屯其兵於淮水之上。此謂叚鋪爲敷也。今人用鋪字本此。江漢。淮夷來鋪。傳曰。鋪、病也。則謂叚鋪爲痡也。"}]},"鐉":{"expl":"所以鉤門戶樞也。一曰治門戶器也。从金巽聲。","rad":"金","fq":"此緣切","vol":"14","py":"quān","duan":[{"e":"所㠯鉤門戶樞也。","n":"門戶樞有不利轉者。以此鉤轉之也。"}]},"𠴫":{"expl":"嗼也。从口叔聲。","rad":"口","fq":"前歴切","vol":"02","py":"jì","duan":[{"e":"𠴫嗼也。","n":"三字一句。俗本刪𠴫字。非也。宀部曰。寂、無人聲也。"}]},"鈔":{"expl":"叉取也。从金少聲。","rad":"金","fq":"楚交切","vol":"14","py":"chāo","duan":[{"e":"叉取也。","n":"叉者、手指相逪也。手指突入其閒而取之、是之謂鈔。字从金者、容以金鐵諸器刺取之矣。曲禮曰。母剿說。剿卽鈔字之叚借也。今謂竊取人文字曰鈔。俗作抄。"}]},"錔":{"expl":"以金有所冒也。从金沓聲。","rad":"金","fq":"他荅切","vol":"14","py":"tà","duan":[{"e":"㠯金有所冃也。","n":"冃各本作冒。凡覆乎上者、頭衣之義之引申耳。輨下曰。轂耑錔也。錔取重沓之意。故多借沓爲之。漢外戚傳。切皆銅沓黃金涂。謂以銅冒門限。以黃金涂銅也。高注吕覽郈氏金距云。以利鐵作假距。沓其距上。卽服注左傳以金錔距也。手部㧺下曰。亦曰韜也。"}]},"銽":{"expl":"斷也。从金𠯑聲。","rad":"金","fq":"古𣴠切","vol":"14","py":"ɡuā","duan":[{"e":"𣃔也。","n":"未聞。"}]},"鉻":{"expl":"𩮜也。从金各聲。","rad":"金","fq":"盧各切","vol":"14","py":"luò","duan":[{"e":"𩮜也。","n":"𩮜者、鬀髮也。亦謂之鉻。俗作㓢、作㪾。"}]},"𨭖":{"expl":"伐擊也。从金亶聲。","rad":"金","fq":"旨善切","vol":"14","py":"zhǎn","duan":[{"e":"伐擊也。从金。亶聲。","n":"？善切。十四部。"}]},"鏃":{"expl":"利也。从金族聲。","rad":"金","fq":"作木切","vol":"14","py":"zú","duan":[{"e":"利也。","n":"今用爲矢鏠之族。與許不同。疑後所增字。"}]},"鈌":{"expl":"刺也。从金夬聲。","rad":"金","fq":"於決切","vol":"14","py":"jué","duan":[{"e":"刺也。从金。夬聲。","n":"於決切。十五部。"}]},"鏉":{"expl":"利也。从金欶聲。","rad":"金","fq":"所右切","vol":"14","py":"shòu","duan":[{"e":"利也。","n":"玉篇、廣韵云。鐵生鏉也。亦曰鉎。此今義。非古義也。古云鐵繡作采。"}]},"鐂":{"expl":"殺也。","rad":"金","fq":"力求切","vol":"14","py":"liú","duan":[]},"錉":{"expl":"業也。賈人占錉。从金昏聲。","rad":"金","fq":"武巾切","vol":"14","py":"mín","duan":[{"e":"業也。賈人占錉。从金。昏聲。","n":"武？切。十二部。按此字必後人所增。必當刪者。史、漢賈人緍錢字从糸。李匪曰。緍、絲也。以貫錢也。引詩維絲伊緍。如淳引胡公云。緍錢爲緍者、詩云？之蚩蚩。抱布貿絲。故謂之緍也。不知何人因二千一算改爲錉字。正如矢族改爲鏃耳。以業訓之。尤不可通。"}]},"瓊":{"expl":"赤玉也。从玉敻聲。","rad":"玉","fq":"渠營切","vol":"01","py":"qiónɡ","duan":[{"e":"亦玉也。","n":"亦各本作赤。非。說文時有言亦者。如李賢所引診亦視也、鳥部鸞亦神靈之精也之類。此上下文皆云玉也。則瓊亦當爲玉名。倘是赤玉。當廁璊瑕二篆閒矣。離騷曰。折瓊枝以爲羞。廣雅玉類首瓊支。此瓊爲玉名之證也。唐人陸德明、張守節皆引作赤玉。則其誤已久。詩瓊琚、瓊瑤、瓊華、瓊瑩、瓊英、瓊瑰。毛傳云。瓊、玉之美者也。葢瓊支爲玉之最美者。故廣雅言玉首瓊支。因而引伸凡玉石之美皆謂之瓊。應劭曰。瓊、玉之華也。是其理也。"}]},"嗼":{"expl":"𠴫嗼也。从口莫聲。","rad":"口","fq":"莫各切","vol":"02","py":"mò","duan":[{"e":"𠴫嗼也。","n":"按歺部云寂㱳。義略同。爾雅釋詁曰。嗼、定也。吕覽首時篇嗼然。高注。嗼然、無聲也。今毛詩。求民之莫。毛曰。莫、定也。又貉其德音。左傳、韓詩貉皆作莫。韓云。莫、定也。"}]},"鉅":{"expl":"大剛也。从金巨聲。","rad":"金","fq":"其呂切","vol":"14","py":"jù","duan":[{"e":"大剛也。","n":"孫卿議兵篇曰。宛鉅鐵釶。慘如蠭蠆。史記禮書本之曰。宛之鉅鐵施。鑽如蠭蠆。徐廣云。大剛曰鉅。按引申爲鉅大字。"}]},"鎕":{"expl":"鎕銻，火齊。从金唐聲。","rad":"金","fq":"徒郎切","vol":"14","py":"tánɡ","duan":[{"e":"鎕銻、","n":"逗。雙聲字。"}]},"銻":{"expl":"鎕銻也。从金弟聲。","rad":"金","fq":"杜兮切","vol":"14","py":"tí","duan":[{"e":"鎕銻也。从金。弟聲。","n":"杜兮切。十五部。"}]},"鈋":{"expl":"吪圜也。从金化聲。","rad":"金","fq":"五禾切","vol":"14","py":"é","duan":[{"e":"吪圜也。","n":"吪動也。謂本不圜、變化而圜也。廣韵曰。鈋、刓也。去角也。"}]},"鐜":{"expl":"下垂也。一曰千斤椎。从金敦聲。","rad":"金","fq":"都回切","vol":"14","py":"duī","duan":[{"e":"矛𢧢柲下銅鐏也。","n":"柲、欑也。欑、積竹杖也。矛𢧢之矝以積竹杖爲之。其首非銅裹而固之恐易散。故有銅鐏。故字从金。秦風毛傳曰。𨯢、鐏也。"}]},"鍒":{"expl":"𨮯之耎也。从金从柔，柔亦聲。","rad":"金","fq":"耳由切","vol":"14","py":"róu","duan":[{"e":"鐵之耎也。","n":"耎猶偄也。偄者、弱也。鍒正爲鉅之反。"}]},"錭":{"expl":"鈍也。从金周聲。","rad":"金","fq":"徒刀切","vol":"14","py":"táo","duan":[{"e":"鈍也。","n":"今俗謂挫抑人爲錭鈍。讀如刀。"}]},"鈍":{"expl":"錭也。从金屯聲。","rad":"金","fq":"徒困切","vol":"14","py":"dùn","duan":[{"e":"錭也。","n":"古亦叚頓爲之。"}]},"𨥦":{"expl":"利也。从金𠂔聲。讀若齊。","rad":"金","fq":"徂奚切","vol":"14","py":"qí","duan":[{"e":"利也。","n":"周易。喪其資斧。子夏傳及衆家並作齊。應劭云。齊、利也。然則𨥳爲正字。齊爲叚借字。"}]},"錗":{"expl":"側意。从金委聲。","rad":"金","fq":"女恚切","vol":"14","py":"nèi","duan":[{"e":"側意。","n":"司部曰。䛐者、意內而言外也。側意猶側䛐。錗卽今之歪字。唐人曰夭邪。"}]},"鑺":{"expl":"兵器也。从金瞿聲。","rad":"金","fq":"其俱切","vol":"14","py":"qú","duan":[]},"銘":{"expl":"記也。从金名聲。","rad":"金","fq":"莫經切","vol":"14","py":"mínɡ","duan":[]},"鎖":{"expl":"𨮯鎖，門鍵也。从金𧴪聲。","rad":"金","fq":"穌果切","vol":"14","py":"suǒ","duan":[]},"鈿":{"expl":"金華也。从金田聲。","rad":"金","fq":"待秊切","vol":"14","py":"tián","duan":[]},"釧":{"expl":"臂環也。从金川聲。","rad":"金","fq":"尺絹切","vol":"14","py":"chuàn","duan":[]},"釵":{"expl":"笄屬。从金叉聲。本只作叉，此字後人所加。","rad":"金","fq":"楚佳切","vol":"14","py":"chāi","duan":[]},"釽":{"expl":"裂也。从金、爪。","rad":"金","fq":"普擊切","vol":"14","py":"pī","duan":[]},"幵":{"expl":"平也。象二干對構，上平也。凡幵之屬皆从幵。徐鉉曰：“幵但象物平，無音義也。”","rad":"幵","fq":"古賢切","vol":"14","py":"jiān","duan":[{"e":"平也。","n":"凡岐頭㒳平曰幵。幵字、古書罕見。禹貢。道岍及岐。許書無？字。葢古衹名幵山。後人加之山旁。必岐頭平起之山也。用幵爲聲之字音讀多岐。如汧、麉、？硏、姸、？在先韵。音之近是者也。如幷、𠛬、形、郉、銒入淸靑韵。此轉移之遠者也。如筓、？入齊韵。此轉移更遠者也。幵从二干。古音仍讀如干。何以證之。籀文栞讀若刊。小篆作栞。然則干幵同音可知。㓝罰字本从井。𠛬剄字从幵。畫然異字異音。今則絶不知有从井之字。以𠛬代㓝。音義㒳失。而凡𠛬聲幷聲之字盡失古音。得吾說存之。而後大略可證。"}]},"勺":{"expl":"挹取也。象形，中有實，與包同意。凡勺之屬皆从勺。","rad":"勺","fq":"之若切","vol":"14","py":"zhuó","duan":[{"e":"枓也。","n":"二字依玄應書卷四補。木部枓下云勺也。此云勺、枓也。是爲轉注。考老之例也。考工記。勺一升。注曰。勺、尊斗也。斗同枓。謂挹以注於尊之枓也。士冠禮注亦云。尊斗、所以𣂏酒也。今皆譌尊升。不可通矣。詩。酌以大斗。毛云。長三尺。謂其柄。"}]},"与":{"expl":"賜予也。一勺爲与。此与與同。","rad":"勺","fq":"余呂切","vol":"14","py":"yǔ","duan":[{"e":"賜予也。","n":"賜、予也。予、推予歬人也。"}]},"嗾":{"expl":"使犬聲。从口族聲。《春秋傳》曰：“公嗾夫獒。”","rad":"口","fq":"穌奏切","vol":"02","py":"sǒu","duan":[{"e":"使犬聲。","n":"見左傳宣二年。使犬者、作之噬也。方言曰。秦晉之西鄙自冀隴而西使犬曰哨。郭音騷。哨與嗾一聲之轉。公羊疏云。今呼犬謂之屬。"}]},"几":{"expl":"踞几也。象形。《周禮》五几：玉几、雕几、彤几、䰍几、素几。凡几之屬皆从几。","rad":"几","fq":"居履切","vol":"14","py":"jǐ","duan":[{"e":"凥几也。","n":"凥各本作踞。今正。凥几者、謂人所凥之几也。凥、処也。処、止也。古之凥今悉改爲居。乃改云居几。旣又改爲蹲踞俗字。古人坐而凭几。蹲則未有倚几者也。几俗作机。左傳設机而不倚、周易渙奔其机皆俗字。"}]},"凭":{"expl":"依几也。从几从任。《周書》：“凭玉几。”讀若馮。","rad":"几","fq":"皮冰切","vol":"14","py":"pínɡ","duan":[{"e":"依几也。","n":"依者、倚也。凭几亦作馮几。叚借字。臥則隱几。"}]},"凥":{"expl":"處也。从尸得几而止。《孝經》曰：“仲尼凥。”凥，謂閒居如此。","rad":"几","fq":"九魚切","vol":"14","py":"jū","duan":[{"e":"処也。","n":"各本作處。今正。凡尸得几謂之凥。尸卽人也。引申之爲凡凥処之字。旣又以蹲居之字代凥。别製踞爲蹲居字。乃致居行而凥廢矣。方言、廣雅凥処字皆不作居。而或妄改之。許書如家凥也、宋凥也、寁凥之速也、寠無禮凥也、宭羣凥也之類皆改爲居。而許書之衇絡不可知矣。"}]},"処":{"expl":"止也。得几而止。从几从夂。","rad":"几","fq":"昌與切","vol":"14","py":"chǔ","duan":[{"e":"止也。","n":"人遇几而止。引申之爲凡凥処之字。俗分别其上去。"}]},"且":{"expl":"薦也。从几，足有二橫，一其下地也。凡且之屬皆从且。","rad":"且","fq":"子余切","vol":"14","py":"jū","duan":[{"e":"所㠯薦也。","n":"所㠯二字今補。薦當作荐。今不改者、存其舊以示人推究也。薦訓獸所食艸。荐訓薦席。薦席謂艸席也。艸席可爲藉謂之荐。故凡言藉當曰荐。而經傳薦荐不分。凡藉義皆多用薦。實非許意。且、古音俎。所以承藉進物者。引申之、凡有藉之䛐皆曰且。凡語助云且者、必其義有二。有藉而加之也。云嫴且、苟且者、謂僅有藉而無所加。粗略之䛐也。凡經注言且字者十有一。鄉飲酒禮注。同姓則以伯仲别之。又同、則以且字别之。言同姓之中有伯仲同者、則呼某甫也。少牢饋食禮注。伯某之某、且字也。士喪禮父某甫注云。某甫、且字也。若言山甫、孔甫。士虞禮適爾皇祖某甫注云。某甫、且字也。若言尼甫。又曲禮有天王某甫注云。某甫、且字也。檀弓烏呼哀哉尼甫注云。"}]},"俎":{"expl":"禮俎也。从半肉在且上。","rad":"且","fq":"側呂切","vol":"14","py":"zǔ","duan":[{"e":"禮俎也。","n":"謂禮經之俎也。"}]},"𧇿":{"expl":"且往也。从且豦聲。","rad":"且","fq":"昨誤切","vol":"14","py":"zù","duan":[{"e":"且往也。","n":"且往、言姑且往也。匆遽之意。"}]},"斤":{"expl":"斫木也。象形。凡斤之屬皆从斤。","rad":"斤","fq":"舉欣切","vol":"14","py":"jīn","duan":[{"e":"斫木斧也。","n":"此依小徐本。凡用斫物者皆曰斧。斫木之斧、則謂之斤。"}]},"斧":{"expl":"斫也。从斤父聲。","rad":"斤","fq":"方矩切","vol":"14","py":"fǔ","duan":[{"e":"所㠯斫也。","n":"所㠯二字今補。斧之爲用廣矣。斤則不見於他用也。葢其制有異矣。白與黑相次文曰黼。葢如畫斧然。故亦曰斧藻。"}]},"斨":{"expl":"方銎斧也。从斤爿聲。《詩》曰：“又缺我斨。”","rad":"斤","fq":"七羊切","vol":"14","py":"qiānɡ","duan":[{"e":"方銎。斧也。","n":"銎者、斤斧空也。毛詩傳曰。隋銎曰斧。方銎曰斨。隋讀如妥。謂不正方而長也。"}]},"吠":{"expl":"犬鳴也。从犬、口。","rad":"口","fq":"符廢切","vol":"02","py":"fèi","duan":[{"e":"犬鳴。从口犬。","n":"口犬者動口之犬也。字林作㕹。則爲形聲字。太玄曰。鴟鳩在林。㕹彼衆經。文𨕖注引戰國策作𠲎。亦是形聲字。符廢切。十五部。"}]},"斫":{"expl":"擊也。从斤石聲。","rad":"斤","fq":"之若切","vol":"14","py":"zhuó","duan":[{"e":"擊也。","n":"擊者、攴也。凡斫木、斫地、斫人皆曰斫矣。"}]},"斪":{"expl":"斫也。从斤句聲。","rad":"斤","fq":"其俱切","vol":"14","py":"qú","duan":[{"e":"斪斸、","n":"逗。"}]},"斸":{"expl":"斫也。从斤屬聲。","rad":"斤","fq":"陟玉切","vol":"14","py":"zhú","duan":[{"e":"斪斸也。","n":"原作斫也。今依全書通例正。木部有欘字、所以斫也。齊謂之茲其。葢實一字。"}]},"斲":{"expl":"斫也。从斤、𠁁。","rad":"斤","fq":"竹角切","vol":"14","py":"zhuó","duan":[{"e":"斫也。从斤。𠁁聲。","n":"小徐有聲。鍇曰。非聲。鉉曰。𠁁器也。斤以斲之。皆不知古音者也。古音三部四部同入。今音析入三覺。竹角切。"}]},"釿":{"expl":"劑斷也。从斤、金。","rad":"斤","fq":"宜引切","vol":"14","py":"yǐn","duan":[{"e":"劑𣃔也。","n":"劑者、齊也小徐無𣃔字。釋名曰。釿者、謹也。板廣不可得制、削又有節。則用此釿之。所以詳謹、令平滅斧迹也。六書故曰。釿魚斤切。似鐋而小。按此篆葢从斤、金聲。讀若呻吟之吟。其義謂以斤斧之屬制𣃔金鐵物也。今俗閒謂戾𣃔堅爲釿𣃔。當卽此字。劉成國以謹也釋之。葢已失其義誤其音。非許入斤部之？矣。"}]},"所":{"expl":"伐木聲也。从斤戶聲。《詩》曰：“伐木所所。”","rad":"斤","fq":"疏舉切","vol":"14","py":"suǒ","duan":[{"e":"伐木聲也。","n":"伐木聲、乃此字本義。用爲處所者、叚借爲処字也。若王所、行在所之類是也。用爲分别之䛐者、又从処所之義引申之。若予所否者、所不與舅氏同心者之類是也。皆於本義無涉。是眞叚借矣。"}]},"斯":{"expl":"析也。从斤其聲。《詩》曰：“斧以斯之。”","rad":"斤","fq":"息移切","vol":"14","py":"sī","duan":[{"e":"析也。","n":"以曡韵爲訓。陳風曰。墓門有棘。斧以斯之。傳曰。斯、析也。叚借訓爲此。亦曡韵也。殷其靁傳曰。斯、此也。"}]},"斮":{"expl":"斬也。从斤昔聲。","rad":"斤","fq":"側略切","vol":"14","py":"zhuó","duan":[{"e":"斬也。","n":"斬者、𢧵也。𢧵者、𣃔也。斫用衺。斮、𢧵用正。"}]},"𣃔":{"expl":"截也。从斤从𢇍。𢇍，古文絕。","rad":"斤","fq":"徒玩切","vol":"14","py":"duàn","duan":[{"e":"𢧵也。","n":"戈部𢧵下曰𣃔也。今人𣃔物讀上聲。物已𣃔讀去聲。引申之義爲決𣃔。讀丁貫切。"}]},"𣂞":{"expl":"柯擊也。从斤良聲。","rad":"斤","fq":"來可切","vol":"14","py":"luǒ","duan":[{"e":"柯擊也。","n":"柯廣韵作相。"}]},"咆":{"expl":"噑也。从口包聲。","rad":"口","fq":"薄交切","vol":"02","py":"páo","duan":[{"e":"嗥也。","n":"廣韵曰。咆虓、熊虎聲。"}]},"新":{"expl":"取木也。从斤新聲。","rad":"斤","fq":"息鄰切","vol":"14","py":"xīn","duan":[{"e":"取木也。","n":"取木者、新之本義。引申之爲凡始基之偁。采𦬊傳曰。田一歲曰葘。二歲曰新田。其一耑也。"}]},"斦":{"expl":"二斤也。从二斤。","rad":"斤","fq":"語斤切","vol":"14","py":"yín","duan":[{"e":"二斤也。闕。","n":"二斤也、言形而義在其中。爾雅毛傳曰。斤斤、明也。葢其義與。闕者、言其義其音未之聞也。大徐語斤切。質字从此。"}]},"斗":{"expl":"十升也。象形，有柄。凡斗之屬皆从斗。","rad":"斗","fq":"當口切","vol":"14","py":"dǒu","duan":[{"e":"十升也。","n":"賈昌朝作升十之也。此篆叚借爲斗陗之斗。因斗形方直也。俗乃製徒字。"}]},"斛":{"expl":"十斗也。从斗角聲。","rad":"斗","fq":"胡谷切","vol":"14","py":"hú","duan":[{"e":"十斗也。","n":"律曆志曰。量者、躍於龠。合於合。登於升。聚於斗。角於斛。考工記。豆實三而成觳。受斗二升。鬲部亦曰。斗二升曰觳。然則謂觳卽斛者、謬也。"}]},"斝":{"expl":"玉爵也。夏曰琖，殷曰斝，周曰爵。从吅从斗，冂象形。與爵同意。或說斝受六斗。","rad":"斗","fq":"古雅切","vol":"14","py":"jiǎ","duan":[{"e":"玉爵也。夏曰醆。","n":"小徐如此。大徐作琖。皆許所無。周禮量人音義曰。琖側產反。劉昌宗本作？。音同。按古當用戔字。後人以意加旁。"}]},"料":{"expl":"量也。从斗，米在其中。讀若遼。","rad":"斗","fq":"洛蕭切","vol":"14","py":"liào","duan":[{"e":"量也。","n":"量者、稱輕重也。稱其輕重曰量。稱其多少曰料。其義一也。知其多少、斯知其輕重矣。如稻重一䄷爲粟二十斗是也。引申之、凡所量度豫備之物曰料。讀去聲。"}]},"斞":{"expl":"量也。从斗臾聲。《周禮》曰：“桼三斞。”","rad":"斗","fq":"以主切","vol":"14","py":"yǔ","duan":[{"e":"量也。","n":"此量讀五量之量。"}]},"斡":{"expl":"蠡柄也。从斗倝聲。楊雄、杜林說：皆以爲軺車輪斡。","rad":"斗","fq":"烏括切","vol":"14","py":"wò","duan":[{"e":"蠡柄也。","n":"此蠡非蟲齧木中。乃本無其字依聲叚借之字。見瓢字下。又見？字下。方言則从瓜作？矣。楊雄曰。瓢也。郭云。瓠勺也。判瓠爲瓢以爲勺。必執其柄而後可以挹物。執其柄則運旋在我。故謂之斡。引申之、凡執柄樞轉運皆謂之斡。賈誼鵩鳥賦云斡流而遷、張華勵志詩云大儀斡運皆是也。或叚借筦字。楚詞云。筦維焉繫。天極焉加。或作幹字。程氏瑤田云。考工記旋蟲謂之幹。葢斡之譌也。"}]},"魁":{"expl":"羹斗也。从斗鬼聲。","rad":"斗","fq":"苦回切","vol":"14","py":"kuí","duan":[{"e":"羮斗也。","n":"斗當作枓。古斗枓通用。然許例以義爲別。枓、勺也。抒羮之勺也。史記趙襄子使廚人操銅枓以食代王及從者。行斟。陰令宰人以枓擊殺代王。斟者、羹汁也。魁頭大而柄長。毛詩傳曰大斗長三尺是也。引申之、凡物大皆曰魁。如檀弓不爲魁、游俠傳曰閭里之俠原涉爲魁、翟方進傳芋魁、百官志里有里魁皆是。北斗七星。魁方杓曲。魁象首、杓象柄也。若國語注小阜曰魁。卽說文𠂤字之叚借。亦未嘗不取枓首之意。"}]},"斠":{"expl":"平斗斛也。从斗冓聲。","rad":"斗","fq":"古岳切","vol":"14","py":"jiào","duan":[{"e":"平斗斛量也。","n":"月令。角斗甬。正權槩。鄭注。角、正皆謂平之也。𧢲者、斠之叚借字。今俗謂之校。音如教。因有書校讎字作此者。音義雖近。亦大好奇矣。"}]},"嗥":{"expl":"咆也。从口皐聲。","rad":"口","fq":"乎刀切","vol":"02","py":"háo","duan":[{"e":"咆也。","n":"廣韵。噑、熊虎聲。左傳曰。狐貍所居。豺狼所噑。"}]},"斟":{"expl":"勺也。从斗甚聲。","rad":"斗","fq":"職深切","vol":"14","py":"zhēn","duan":[{"e":"勺也。","n":"勺玉篇、廣韵作酌。按許以盛酒行觴爲？。則水漿不曰酌。枓曰勺。用枓挹注亦曰勺。詩。泂酌彼行潦。挹彼注茲。則勺？古通也。勺之謂之斟。引申之盛於勺者亦謂之斟。方言。斟、汁也。北燕朝鮮洌水之閒曰斟。左傳羊斟不與、趙世家張儀列傳廚人進斟是也。又引申之。凡增益謂之斟。方言曰。斟、益也。南楚凡相益而又少謂之不斟。凡病少愈而加劇亦謂之不斟。或謂之何斟。言雖少損無所益也。勺之斟之、多少在已。故凡處分曰斟勺。今多用斟？。○左傳。華元殺羊食士。其御羊斟不與。此羊斟謂羊汁也。宋世家說此事云。華元殺羊以食士。其御羊羹不及。可以證左傳之解矣。傳當本作其御羊羊斟不與。上羊其名也。故字叔牂。君子謂羊斟非人也。其羊斟之謂乎。二"}]},"斜":{"expl":"杼也。从斗余聲。讀若荼。","rad":"斗","fq":"似嗟切","vol":"14","py":"xié","duan":[{"e":"抒也。","n":"抒各本从木。今正。手部曰。抒者、挹也。挹者、抒也。水部浚、抒也。革部？、所以抒井也。臼部舀、抒臼也。凡以斗挹出之謂之斜。故字从斗。音轉義移。乃用爲衺。俗人乃以人之衺正作邪。物之衺正作斜。其可𣢑有如此者。"}]},"㪺":{"expl":"挹也。从斗𥇛聲。","rad":"斗","fq":"舉朱切","vol":"14","py":"jū","duan":[{"e":"挹也。","n":"挹亦抒也。詩箋、禮注皆用㪺。皆謂挹酒於尊中也。如鄭說、則賔筵之仇乃此字之叚借。"}]},"㪵":{"expl":"量物分半也。从斗从半，半亦聲。","rad":"斗","fq":"博幔切","vol":"14","py":"bàn","duan":[{"e":"量物分半也。","n":"量之而分其半、故字从斗半。漢書。士卒食半菽。孟康曰。半、五斗器名也。王邵曰。言半、量器名。容半升也。今按半卽㪵也。廣韵㪵注五升。然則孟康語升誤斗。王劭語斗誤升。當改正。集韵云。一曰升五十謂之㪵。當有誤。人日食五升菽。略同周官之人月二鬴也。字从半斗。卽以五升釋之。許意不尒。"}]},"𣂆":{"expl":"量溢也。从斗㫄聲。","rad":"斗","fq":"普郎切","vol":"14","py":"pānɡ","duan":[{"e":"量旁溢也。","n":"大徐無旁。非。旁者、溥也。形聲包會意。"}]},"㪻":{"expl":"杼滿也。从斗䜌聲。","rad":"斗","fq":"俱願切","vol":"14","py":"juàn","duan":[{"e":"抒屚也。","n":"屚各本作滿。誤。玄應作漏爲是。依許義當作屚。謂抒而屚之有所注也。元和汪元亮曰。今賣酒家汲酒於甕中之器、名曰酒端。傾入於屚篼。而注於酒缾。是其物也。通俗文曰。汲取曰㪻。"}]},"斣":{"expl":"相易物，俱等爲斣。从斗蜀聲。","rad":"斗","fq":"易六切","vol":"14","py":"dòu","duan":[{"e":"相易物俱等爲斣。从斗。蜀聲。","n":"昌六切。三部。今南俗有此語。而篇、韵皆丁豆切。按小徐本無此篆。"}]},"𣂀":{"expl":"斛㫄有𣂀。从斗𠩓聲。一曰突也。一曰利也。《尔疋》曰：“𣂀謂之疀。”古田器也。","rad":"斗","fq":"土雕切","vol":"14","py":"tiāo","duan":[{"e":"斛旁有庣也。","n":"庣各本作𣂁。今正。斛旁有庣、謂斛中有寬於方尺之處。若作有𣂁、是斛外有物名𣂁矣。漢律曆志曰。量者、龠合升斗斛也。其法用銅。方尺而圜其外。旁有庣焉。鄭氏曰。庣、過也、算方一尺。所受一斛。過九氂五豪。然後成斛。劉徽注九章算術曰。晉武庫中所作銅斛。其篆書字題斛旁云。律嘉量斛、方一尺而圜其外。庣旁九氂五豪。幂一百六十二寸。深一尺。積一千六百二十寸。容十斗。及斛底律嘉量斗、方尺而圜其外。庣旁九氂五豪。幂一百六十二寸。深一寸。積一百六十二寸。容一斗。升居斛旁。合龠在斛耳上。與律曆志同。按庣旁者謂方一尺而又寬九氂五豪也。不寬九氂五豪則不容十斗。故製字从斗庣會意。"}]},"升":{"expl":"十龠也。从斗，亦象形。","rad":"斗","fq":"識蒸切","vol":"14","py":"shēnɡ","duan":[{"e":"十合也。","n":"十合各本作十龠。誤。今正。律曆志曰。合龠爲合。十合爲升。十升爲斗。十斗爲斛。而五量嘉矣。作十龠則不可通。古經傳登多作升。古文叚借也。禮經注曰。布八十縷爲升。升字當爲登。今之禮皆爲升。俗誤已行久矣。按今俗所用又作陞。經有言升不言登者、如周易是也。有言登不言升者、左傳是也。"}]},"矛":{"expl":"酋矛也。建於兵車，長二丈。象形。凡矛之屬皆从矛。","rad":"矛","fq":"莫浮切","vol":"14","py":"máo","duan":[{"e":"酋矛也。建於兵車。長二丈。","n":"見考工記。記有酋矛、夷矛。酋矛常有四尺。夷矛三尋。鄭注。酋夷、長短。酋之言遒也。酋近夷長矣。按許不言夷矛者、兵車所不建。不常用也。魯頌箋云。兵車之法。左人持弓。右人持矛。中人御。"}]},"喈":{"expl":"鳥鳴聲。从口皆聲。一曰鳳皇鳴聲喈喈。","rad":"口","fq":"古諧切","vol":"02","py":"jiē","duan":[{"e":"烏鳴聲也。从口。皆聲。","n":"古諧切。十五部。"}]},"𥍫":{"expl":"矛屬。从矛良聲。","rad":"矛","fq":"魯當切","vol":"14","py":"lánɡ","duan":[{"e":"矛屬。","n":"廣韵曰短矛。"}]},"𥎆":{"expl":"矛屬。从矛害聲。","rad":"矛","fq":"苦蓋切","vol":"14","py":"kài","duan":[{"e":"矛屬。从矛。害聲。","n":"苦葢切。十五部。"}]},"矠":{"expl":"矛屬。从矛昔聲。讀若笮。","rad":"矛","fq":"士革切","vol":"14","py":"zé","duan":[{"e":"矛屬。","n":"魯語。矠魚鼈以爲夏槁。韋云。矠、𢳇也。𢳇刺魚鼈以爲槁儲也。按此矠字引申之義也。周禮作簎魚鼈。注云。謂杈刺泥中搏取之。莊子。擉鼈於江。東京賦。毒冒不蔟。皆音近義同者也。"}]},"矜":{"expl":"矛柄也。从矛今聲。","rad":"矛","fq":"居陵切","vol":"14","py":"jīn","duan":[]},"䂇":{"expl":"剌也。从矛丑聲。","rad":"矛","fq":"女久切","vol":"14","py":"niǔ","duan":[{"e":"刺也。从矛。丑聲。","n":"女久切。三部。篇、韵女六切。"}]},"車":{"expl":"輿輪之緫名。夏后時奚仲所造。象形。凡車之屬皆从車。","rad":"車","fq":"尺遮切","vol":"14","py":"chē","duan":[{"e":"輿輪之緫名也。","n":"車之事多矣。獨言輿輪者。以轂輻牙皆統於輪。軾䡈軫軹轛皆統於輿。輈與軸則所以行此輿輪者也。故倉頡之制字、但象其一輿㒳輪一軸。許君之說字、謂之輿輪之緫名。言輪而軸見矣。渾言之則輿輪之緫名。析言之則惟輿偁車。以人所居也。故攷工記曰輿人爲車。"}]},"軒":{"expl":"曲輈藩車。从車干聲。","rad":"車","fq":"虚言切","vol":"14","py":"xuān","duan":[{"e":"曲輈藩車也。","n":"謂曲輈而有藩蔽之車也。曲輈者、戴先生曰。小車謂之輈。大車謂之轅。人所乗欲其安。故小車暢轂梁輈。大車任載而已。故短轂直轅。艸部曰。藩者、屛也。服䖍注左傳、薛綜解東京賦、劉昭注輿服志皆云車有藩曰軒。皆同許說。許於藩車上必云曲輈者、以輈穹曲而上。而後得言軒。凡軒舉之義引申於此。曲輈、所謂軒轅也。杜注左傳於軒皆曰大夫車。定九年曰。犀軒、卿車。"}]},"輜":{"expl":"軿車前，衣車後也。从車甾聲。","rad":"車","fq":"側持切","vol":"14","py":"zī","duan":[{"e":"輺軿、","n":"逗。"}]},"軿":{"expl":"輜車也。从車并聲。","rad":"車","fq":"薄丁切","vol":"14","py":"pínɡ","duan":[{"e":"輺輧也。","n":"各本上解作輧車前衣車後也。此解作輺車也。皆誤。今依全書通例正之。輺輧俗多聯舉。故備析言渾言之解。周禮。苹車之萃。鄭曰。苹猶屛也。所用對敵自隱蔽之車也。杜子春云。苹車當爲輧車。據此則兵車亦有輧車矣。"}]},"轀":{"expl":"臥車也。从車𥁕聲。","rad":"車","fq":"烏魂切","vol":"14","py":"wēn","duan":[{"e":"臥車也。","n":"史記始皇𡹔於沙丘。不發喪。棺載轀涼車中。百官奏事。宦者輒從轀涼車中可其奏。漢霍光傳。載光屍柩以轀輬車。孟康曰。如衣車有䆫牖。閉之則溫。開之則涼。故名之轀輬車也。師古曰。轀輬本安車。可以臥息。後因載喪。飾以桺翣。故遂爲喪車耳。轀者密閉。輬者旁開䆫牖。各别一乗。隨事爲名。後人旣專以載喪。又去其一。總爲藩飾。而合二名呼之耳。按顏說是也。本是二車可偃息者。故許分解曰臥車。始皇本紀上渾言曰轀輬車。下言上轀車臭。以屍實在轀車。不在輬車也。古二車隨行。惟意所適。"}]},"哮":{"expl":"豕驚聲也。从口孝聲。","rad":"口","fq":"許交切","vol":"02","py":"xiāo","duan":[{"e":"豕驚聲也。","n":"按哮亦作豞。許角切。吳都賦曰。封豨？。李云。？、豨聲。呼學切。亦卽哮字。但字形有譌耳。"}]},"輬":{"expl":"臥車也。从車京聲。","rad":"車","fq":"呂張切","vol":"14","py":"liánɡ","duan":[{"e":"臥車也。","n":"史記作涼。"}]},"軺":{"expl":"小車也。从車召聲。","rad":"車","fq":"以招切","vol":"14","py":"yáo","duan":[{"e":"小車也。","n":"漢平帝紀。立軺倂馬。服䖍曰。立軺、立乗小車也。"}]},"輕":{"expl":"輕車也。从車坙聲。","rad":"車","fq":"去盈切","vol":"14","py":"qīnɡ","duan":[{"e":"輕車也。","n":"三字句。周禮。輕車之萃。鄭曰。輕車、所用馳敵致師之車也。漢之發材官輕車。亦謂兵車。輕本車名。故字从車。引申爲凡輕重之輕。作音者乃以經之輕車讀遣政反。古無是分别矣。"}]},"輶":{"expl":"輕車也。从車酋聲。《詩》曰：“輶車鑾鑣。”","rad":"車","fq":"以周切","vol":"14","py":"yóu","duan":[{"e":"輕車也。","n":"輶車卽輕車也。本是車名。引申爲凡輕之偁。大雅。德輶如毛。箋云。輶、輕也。此引申之義也。"}]},"輣":{"expl":"兵車也。从車朋聲。","rad":"車","fq":"薄庚切","vol":"14","py":"pénɡ","duan":[{"e":"樓車也。","n":"樓各本作兵。今正。光武紀。衝輣撞城。李賢引許愼云。輣、樓車也。李注文𨕖亦曰樓車。前書敘傳注。鄧展作兵車。乃或用以改許書耳。"}]},"軘":{"expl":"兵車也。从車屯聲。","rad":"車","fq":"徒魂切","vol":"14","py":"tún","duan":[{"e":"兵車也。","n":"軘車見左傳宣十二年、襄十一年。服䖍曰。屯守之車。杜預曰。兵車名。"}]},"䡴":{"expl":"陷敶車也。从車童聲。","rad":"車","fq":"尺容切","vol":"14","py":"chōnɡ","duan":[{"e":"陷敶車也。","n":"敶者、列也。見攴部。於此可見古戰陣字用此矣。用陳者、叚借字也。作陣者、俗字也。大雅。與爾臨衝。傳曰。臨、臨車也。衝、衝車也。釋文曰。說文作䡴。陷陣車也。定八年左傳。主人焚衝。釋文亦云爾。前、後漢書衝輣。衝皆卽䡴字。李善曰。衝、字略作䡴。"}]},"轈":{"expl":"兵高車加巢以望敵也。从車巢聲。《春秋傳》曰：“楚子登轈車。”","rad":"車","fq":"鉏交切","vol":"14","py":"cháo","duan":[{"e":"兵車高如巢㠯望敵也。","n":"左傳正義引兵高車加巢以望敵。與釋文及今本不同。今本爲長。篇、韵皆云若巢。亦今本也。今左傳作巢車。杜曰。巢車、車上爲櫓。此正言櫓似巢。不得言加巢。宣十五年傳。晉使解揚如宋。楚子登諸樓車。服䖍曰。樓車所以窺望敵軍。兵法所謂雲梯者。杜曰。樓車、車上望櫓。"}]},"輿":{"expl":"車輿也。从車舁聲。","rad":"車","fq":"以諸切","vol":"14","py":"yú","duan":[{"e":"車輿也。","n":"車輿謂車之輿也。攷工記。輿人爲車。注曰。車、輿也。按不言爲輿而言爲車者、輿爲人所居。可獨得車名也。軾䡈軫軹轛皆輿事也。"}]},"輯":{"expl":"車和輯也。从車咠聲。","rad":"車","fq":"秦入切","vol":"14","py":"jí","duan":[{"e":"車輿也。","n":"各本作車和輯也。大誤。今正。自轈篆以上皆車名。自輿篆至軜篆皆車上事件。其閒不得有車和之訓。許書列字次弟有倫。可攷而知也。叚令訓爲車和。則此篆當與軼？？軭軔輟䡔轚諸篆爲類。列子湯問篇唐殷敬順釋文引說文輯、車輿也。殷氏所見未誤。大玄。礥上九。崇崇高山。下有川波。其人有輯航、可與過。測曰。高山大川不輯航不克也。此輯謂輿。山必輿、川必航。而後可過。是古義見於子雲之書。非無可徵也。輿之中無所不居。無所不載。因引申爲斂義。喪大記檀弓之輯杖、輯屨是也。又爲和義。爾雅。輯、和也。版詩毛傳同。公劉傳曰。和睦也。引申義行。本義遂廢。淺人少可多怪。改易許書。此字从車之恉遂不可得而聞矣。"}]},"喔":{"expl":"雞聲也。从口屋聲。","rad":"口","fq":"於角切","vol":"02","py":"wō","duan":[{"e":"雞聲也。从口。屋聲。","n":"於角切。三部。"}]},"䡬":{"expl":"衣車蓋也。从車曼聲。","rad":"車","fq":"莫半切","vol":"14","py":"màn","duan":[{"e":"衣車葢也。","n":"衣車、上文之輺輧是也。四圍爲衣。上爲葢。皆以蔽輿也。故廁於輿下。集韵云。一曰戰車。以遮矢也。"}]},"軓":{"expl":"車軾前也。从車凡聲。《周禮》曰：“立當前軓。”","rad":"車","fq":"","vol":"14","py":"fàn","duan":[{"e":"車軾歬也。","n":"杜子春注大馭職、鄭司農注輈人、後鄭注少儀皆曰。軓謂車軾前也。秦風。陰靷鋈續。傳曰。陰、揜軓也。戴先生云。車旁曰輢。式前曰軓。皆揜輿版也。軓以揜式前。故漢人亦呼曰揜軓。詩謂之陰。攷工記輈人軓前十尺。書或作𨊠。大馭祭𨊠。杜子春云。𨊠當爲軓。禮記少儀祭范。鄭曰。大馭作祭軓。軓與范聲同。按其字葢古文作𨊠。今字作軓。叚借作笵。笵又譌范。此岐出之由也。鄭於少儀注謂軾前。於輈人注云。𨊠是𨊠法也。謂輿下三面材。輢軾之所尌。持車正也。其說亦互異。攷工注取範圍之意。謂軾前及㒳輢所尌皆爲𨊠。析言之則曰軾前。"}]},"軾":{"expl":"車前也。从車式聲。","rad":"車","fq":"賞職切","vol":"14","py":"shì","duan":[{"e":"車歬也。","n":"此當作車輿前也。不言輿者、輿人爲車。車卽輿也。輿之在前者曰軾。在旁者曰輢。皆輿之體。非與輿二物也。戴先生曰。軾與較皆車闌上之木。周於輿外。非橫在輿中。較有㒳。在㒳旁。軾有三面。故說文槩言之曰車前。軾卑於較者。以便車前射御執兵。亦因之伏以式敬。玉裁謂輿四圍。旁謂之輢。前謂之軾。軾卑於較二尺二寸。說詳先生考工記圖。"}]},"輅":{"expl":"車軨前橫木也。从車各聲。","rad":"車","fq":"洛故切","vol":"14","py":"lù","duan":[{"e":"車軨歬橫木也。","n":"婁敬傳。脫輓輅。蘇林曰。輅音凍𠗂之𠗂。一木橫遮車前。二人挽之。三人推之。劉昭注輿服志曰。韵集云軛前橫木曰輅。按軛前當依許作軨前。輓輅之車用人。不用牛馬。疑有轅無軛也。禮經旣夕篇。賓奉幣由馬西當前輅。注曰。輅、轅縛所以屬引。疏曰。謂以木縛車轅上。以屬引於上而挽之。是喪車亦有轅無軛。輅之見於經者此而已矣。若左傳梁由靡虢射輅秦伯、狂狡輅鄭人。皆謂車前相接可以禽之。此輅引申之義也。故杜曰輅、迎也。應邵注漢云。輅謂以木當𦙄以挽車。廣韵用之。改其字作？。形與義皆非。以木當𦙄、乃今之縴板。與輅各物。解嘲云。婁敬委輅脫輓。謂委車前橫木、脫縴板。輅非𦙄前木也。"}]},"䡈":{"expl":"車騎上曲銅也。从車爻聲。","rad":"車","fq":"古岳切","vol":"14","py":"jué","duan":[{"e":"車輢上曲鉤也。","n":"各本作車騎上曲銅也。今依李善西京賦、七啓二注正。攷工記車人。以其廣之半、爲之式崇。以其隧之半、爲之較崇。較高五尺五寸。高於軾者二尺二寸也。戴先生曰。左右㒳較。故衞風曰。猗重較兮。毛傳。重較、卿士之車。因詩辭傅會耳。非禮制也。玉裁按䡈之制、葢漢與周異。周時䡈高於軾。高處正方有隅。故謂之䡈。䡈之言角也。至漢乃圜之如半月然。故許云車上曲鉤。曲鉤、言句中鉤也。圜之則亦謂之車耳。其飾則崔豹云文官靑耳。武官赤耳。西京賦云。戴翠帽。倚金較。荀卿及史記禮書云。彌龍以養威。彌許書作𦗕。解云乗輿金耳也。皆謂䡈爲龍形、而飾以金。司馬氏輿服志。乗輿金薄繆龍。爲輿倚較。是其義也。下文公列侯安車倚鹿。然則䡈辨尊卑。自周已"}]},"䡊":{"expl":"車耳反出也。从車从反，反亦聲。","rad":"車","fq":"府遠切","vol":"14","py":"fǎn","duan":[{"e":"車耳反出也。","n":"車耳卽䡈也。其反出者謂之䡊。反出、謂圜角有邪倚向外者也。漢景帝詔。吏六百石以上。皆長吏也。或不更服。出入閭里。與民無異。令長吏二千石車朱㒳轓。千石至六百石朱左轓。應劭曰。車耳反出。所以爲之藩屛、翳塵泥也。二千石雙朱。其次乃偏朱其左。䡊以簟爲之。或用革。按此說師古非之。是也。轓與䡊㒳物、㒳字。轓、蔽也。許軒下云。曲輈藩車。字作藩。詩之茀。周禮之蔽。左傳以藩載欒盈。輿服志畫轓、黑轓、朱轓是也。䡈之反出者曰䡊。景帝紀自謂車蔽。不得以車耳釋之也。"}]},"轛":{"expl":"車橫軨也。从車對聲。《周禮》曰：“參分軹圍，去一以爲轛圍。”","rad":"車","fq":"追萃切","vol":"14","py":"zhuì","duan":[{"e":"車橫軨也。","n":"謂車闌也。木部橫下曰。闌木也。攷工記曰。參分軹圍、去一以爲轛圍。注。兵車之轛圍、二寸八十一分寸之十四。轛、式之植者橫者也。鄭司農云。謂車輿軨立者也。按許云橫軨也。橫訓闌。則直者衡者皆在內矣。漢人從衡字衹作衡。不作橫。橫者、桄也。後鄭又云。轛者、以其鄉人爲名。按字所以从對與。"}]},"輢":{"expl":"車㫄也。从車奇聲。","rad":"車","fq":"於綺切","vol":"14","py":"yǐ","duan":[{"e":"車旁也。","n":"謂車㒳旁。式之後、䡈之下也。注家謂之輢。按輢者、言人所倚也。前者對之、故曰轛。旁者倚之、故曰輢。兵車、戈殳？矛皆臿於車輢。輢之上曰䡈。"}]},"輒":{"expl":"車兩輢也。从車𦔮聲。","rad":"車","fq":"陟葉切","vol":"14","py":"zhé","duan":[{"e":"車㒳輢也。","n":"㒳各本作兩。今正。車㒳輢謂之輒。按車必有㒳輢。如人必有㒳耳。故从耴。耴、耳垂也。此篆在輢篆之先。故輢篆下但云車旁、而不言㒳。凡許全書之例。皆以難曉之篆先於易知之篆。如輯下云車輿也。而後出輿篆。輒下云車㒳輢也。而後出輢篆。是也。廣韵作車相倚也。乃字之誤。不可從。凡專輒用此字者、此引申之義。凡人有所倚恃而妄爲之。如人在輿之倚於輢也。"}]},"䡅":{"expl":"車約䡅也。从車川聲。《周禮》曰：“孤乘夏䡅。”一曰下棺車曰䡅。","rad":"車","fq":"敕倫切","vol":"14","py":"chūn","duan":[{"e":"車約䡅也。","n":"巾車職云。孤乗夏篆。卿乗夏縵。大鄭曰。夏、赤也。篆讀爲圭瑑之瑑。夏瑑、轂有約也。玄謂夏瑑、五采畫轂約也。夏縵亦五采畫、無瑑耳。玉裁謂鄭說夏瑑卽詩之約軝。毛公所謂長轂之軝、朱而約之也。但許君篆作䡅。以約䡅系之輿。下文以約軝系之轂。與二鄭迥異。依許意葢謂轛輢軨等皆有物纏束之。謂之約䡅。以赤畫之。謂之夏䡅。卿雖赤畫而無約。謂之夏縵。䡅之言巡也。巡繞之䛐。此許之周禮說也。"}]},"呝":{"expl":"喔也。从口戹聲。","rad":"口","fq":"鳥格切","vol":"02","py":"è","duan":[{"e":"喔也。","n":"呝喔雙聲。射雉賦。良遊呃喔。引之規裏。廣韵卄一麥曰。呝喔、鳥聲。疑㒳篆文下本皆云呝喔。後人亂之耳。"}]},"轖":{"expl":"車籍交錯也。从車嗇聲。","rad":"車","fq":"所力切","vol":"14","py":"sè","duan":[{"e":"車箱交革也。","n":"各本革作錯。李善七發注、顏師古急就篇注作交革。今從之。車箱各本作車籍。七發注同。急就注、廣韵作車藉。皆不可通。今以意正之曰車箱。箱與籍字形之誤也。毛大東傳曰。服、牝服也。箱、大車之箱也。鄭曰。大車、平地任載之車。竹部曰。箱、大車牝服也。按箱本謂大車之輿。引申之而凡車之輿皆得名箱。此箱不謂大車也。交革者、交猶遮也。謂以去毛獸皮鞔其外。攷工記。棧車欲弇。注曰。爲其無革鞔不堅。易坼壞也。飾車欲侈。注曰。飾車、革鞔輿也。大夫以上革輓輿。巾車職。士乗棧車。注曰。棧車、不革輓而漆之。王之玉路、金路、象路皆以革輓。而有玉金象之飾。因有玉金象之名。革路鞔之以革而漆之。無他飾。故偁革路。木路不鞔。以革漆之而已。"}]},"軨":{"expl":"車轖閒橫木。从車令聲。","rad":"車","fq":"郎丁切","vol":"14","py":"línɡ","duan":[{"e":"車轖閒橫木。","n":"車轖閒、蒙上文言之。猶言車輿閒也。木部曰。橫、闌木也。車轖閒橫木、謂車輢之直者衡者也。軾與車輢皆以木一橫一直爲方格成之。如今之大方格然。楚辭。倚結軨兮長大息。涕潺湲兮下霑軾。戴先生曰。軨者、軾較下縱橫木緫名。卽攷工記之軹轛也。結軨謂軨之橫從交結。倚軨而涕霑軾、則是倚於輢內之軨。故其涕得下霑軾也。玉裁按惟此軨乃許所謂。若曲禮僕展軨效駕。軨卽輪。亦作轔。士喪禮注所云轉轔。展軨、謂使馬稍動車輪也。東京賦。疏轂飛軨。薛解曰。飛軨、以緹紬一作油廣八尺當作寸長拄地。左青龍。右白虎。繫軸頭取㒳邊飾。二千石亦然。但無畫耳。此葢漢制。師古取以注急就篇之軨。殊誤。急就軹軾軫竝言正謂橫直結軨耳。"}]},"輑":{"expl":"軺車前橫木也。从車君聲。讀若帬，又讀若褌。","rad":"車","fq":"牛尹切","vol":"14","py":"yǐn","duan":[{"e":"軺車歬橫木也。","n":"軺車、小車也。木部曰。橫、闌木也。軺車前橫木、謂小車軾輢之直者衡者也。方言曰。輑謂之軸。按軸字恐有誤。"}]},"軫":{"expl":"車後橫木也。从車㐱聲。","rad":"車","fq":"之忍切","vol":"14","py":"zhěn","duan":[{"e":"車後橫木也。","n":"木部橫、闌木也。輿人注曰。軫、輿後橫者也。方言曰。軫謂之枕。秦風。小戎俴收。傳曰。收、軫也。近戴先生曰。輿下之材、合而成方。通名軫。故曰軫之方也。以象地也。鄭注專以輿後橫木爲軫。以輢式之所尌三面材爲軓。又以軓爲任正者。如其說宜記於輿人。今輈人爲之。殆非也。輿人爲式、較、軹、轛、軫、輢、軓。輈人爲輈、衡、軸、伏兔。記不言輢、軓、衡、伏兔之度。輢軓、輿揜版耳。衡圍準乎軸。伏兔、取節於輈。當兔、省文互見。桐城姚氏鼐曰。記曰軫之方以象地。葢軫方六尺六寸。記曰參分車廣。以其一爲隧。葢以二尺二寸爲輿後。其前廣如軫。而深四尺四寸。以設立木焉。是爲收。毛公曰。收、軫也。謂輿深四尺四寸收於軫矣。非謂軫名收也。玉"}]},"轐":{"expl":"車伏兔也。从車菐聲。《周禮》曰：“加軫與轐焉。”","rad":"車","fq":"博木切","vol":"14","py":"bú","duan":[{"e":"車伏兔也。","n":"戴先生曰。伏兔謂之轐。易小畜九三。輿脫輻。大畜九二。輿脫輹。大壯九四。壯於大輿之輹。說文。轐、車伏兔也。輹、車軸縛也。釋名。屐、似人屐也。又曰伏兔。在軸上似之也。又曰輹。輹、伏也。伏於軸上也。按轐輹實一字。其下有革以縛於軸。今易小畜作輻。系傳寫者誤。輻在轂與牙之閒。非可脫者。玉裁謂劉成國合輹於伏兔。非也。依許則伏兔名轐。車軸之縛名輹。迥然二物。轐之言僕也。毛傳曰。僕、附也。爲伏兔之形附於軸上。以𩊚固之。輈葘於㒳伏兔閒者、名曰當兔。"}]},"𨏵":{"expl":"車伏兔下革也。从車𡖀聲。𡖀，古昏字。讀若閔。","rad":"車","fq":"眉殞切","vol":"14","py":"mǐn","duan":[{"e":"車伏兔下革也。","n":"謂以𩊚固之於軸上也。𩊚者、生革可以爲縷束也。"}]},"軸":{"expl":"持輪也。从車由聲。","rad":"車","fq":"直六切","vol":"14","py":"zhóu","duan":[{"e":"所㠯持輪者也。","n":"所以者三字今補。軸所以持輪、引伸爲凡機樞之偁。若織機之持經者亦謂之軸是也。小雅。杼軸其空。今本作柚。乃俗誤耳。若方言土作謂之抒、木作謂之軸。亦是引申之義。抒作杼。軸作柚。皆非也。方言抒軸與大東無涉。"}]},"輹":{"expl":"車軸縛也。从車复聲。《易》曰：“輿脫輹。”","rad":"車","fq":"芳六切","vol":"14","py":"fù","duan":[{"e":"車軸縛也。","n":"謂以革若絲之類纏束於軸、以固軸也。縛者、束也。古者束輈曰楘。曰歷錄。束軸曰輹。亦曰鞪。約轂曰約軝。衣衡曰㡔。皆所以爲固。皆見於許書。輈束箸於外。故詩箸其數。軸束隱於輿下。故不知其數。釋名曰。？、複也。重複非一之言也。？當爲輹。轉寫誤耳。或曰？當爲輻之誤。若屐下云又曰輹。輹當爲轐。"}]},"軔":{"expl":"礙車也。从車刃聲。","rad":"車","fq":"而振切","vol":"14","py":"rèn","duan":[{"e":"所㠯礙車也。","n":"所㠯二字今補。玄應時已失之。離騷朝發軔於蒼梧。王逸曰。軔、支輪木也。"}]},"輮":{"expl":"車軔也。从車柔聲。","rad":"車","fq":"人九切","vol":"14","py":"róu","duan":[{"e":"車网也。","n":"今本作車軔。篇、韵皆作車輞。輞譌爲軔。見爾雅釋文。从車旁、葢俗。古衹作网耳。或曰許本有𨋹篆。解曰車𨋹也。在輮篆之上。今軔篆卽𨋹之誤。然許有軔篆、諸家引之。疑未能明也。車网者、輪邊圍繞如网然。攷工記謂之牙。牙也者、以爲固抱也。又謂之輮。行澤者反輮。行山者仄輮。大鄭曰。牙世閒或謂之㒺。釋名曰。輞、罔也。㒺羅周輪之外也。關西曰輮。言曲揉也。按牙亦作枒。木部枒下曰。一曰車网會也。所以名牙者、合衆曲而爲之。如襍佩之牙、亦曲體也。亦謂之渠。俗作？。尙書大傳大貝如車渠是也。車网木必擇材。攷工記注曰。今世牙以橿。爾雅注曰。杻、檍。材中車𨋹。又赤栜中爲車𨋹。"}]},"珦":{"expl":"玉也。从玉向聲。","rad":"玉","fq":"許亮切","vol":"01","py":"xiànɡ","duan":[{"e":"玉也。从王。向聲。","n":"許亮切。十部。"}]},"咮":{"expl":"鳥口也。从口朱聲。","rad":"口","fq":"章俱切","vol":"02","py":"zhòu","duan":[{"e":"鳥口也。","n":"今人噣咮啄三字同音通用。許分別甚明。人口不曰咮。"}]},"𨍶":{"expl":"車輮規也。一曰一輪車。从車，熒省聲。讀若煢。","rad":"車","fq":"張營切","vol":"14","py":"qiónɡ","duan":[{"e":"車輮規也。","n":"規者、圜之匡郭也。考工記曰。規之以眡其圜。萭之以眡其匡。注曰。輪中規則圜矣。等爲萭蔞以運輪上。輪中萭蔞則不匡剌也。按此謂作輮之笵。"}]},"轂":{"expl":"輻所凑也。从車𣪊聲。","rad":"車","fq":"古禄切","vol":"14","py":"ɡǔ","duan":[{"e":"輻所湊也。","n":"湊者、水上人所會也。引申爲凡會之偁。老子曰。三十輻共一轂。轂中空曰橾。見木部。"}]},"輥":{"expl":"轂齊等皃。从車昆聲。《周禮》曰：“望其轂，欲其輥。”","rad":"車","fq":"古本切","vol":"14","py":"ɡǔn","duan":[{"e":"轂𪗍等皃也。","n":"等者、𪗍𥳑也。因爲凡齊之偁。𪗍者、等也。輥者、轂匀整之皃也。戴先生曰。齊等者、不橈減也。榦木圜甚。"}]},"軝":{"expl":"長轂之軝也，以朱約之。从車氏聲。《詩》曰：“約軝錯衡。”","rad":"車","fq":"渠支切","vol":"14","py":"qí","duan":[{"e":"長轂之軝也。㠯朱約之。","n":"小雅斯干傳曰。軝、長轂之軝也。朱而約之。長轂者、小戎所謂暢轂也。傳曰。暢轂、長轂也。大車轂長尺五寸。兵車、田車、乗車轂長三尺二寸。五分三尺二寸之長。一爲賢、得六寸四分。三爲軹、得尺九寸二分。虛其一者、畱以置輻也。參分三尺二寸之長。二在外、一在内、以置其輻。二在外而三爲軹者在是。一在內而一爲賢者在是。考工記此軹字、卽毛詩之軝字。軹者同音叚借字也。取此尺九寸二分者、以革約之而朱其革。詩所謂約軝也。考工記詳之曰。容轂必直。陳篆必正。施膠必厚。施筋必數。幬必負榦。旣摩。革色靑白。謂之轂之善。說者曰。容者、治轂爲之形容也。篆、轂約也。幬負榦者、革轂相應。無贏不足也。旣摩革色青白者、謂丸桼之乾而以石摩平之"}]},"軹":{"expl":"車輪小穿也。从車只聲。","rad":"車","fq":"諸氏切","vol":"14","py":"zhǐ","duan":[{"e":"車輪小穿也。","n":"輪當作轂。輪人職曰。五分其轂之長。去一以爲賢。去三以爲軹。鄭司農云。賢、大穿也。軹、小穿也。後鄭又改記文作去二爲賢。程氏辨其非是。詳見通藝錄。許同先鄭。"}]},"軎":{"expl":"車軸耑也。从車，象形。杜林說。","rad":"車","fq":"于濊切","vol":"14","py":"wèi","duan":[{"e":"車軸耑也。","n":"耑者、物初生之題也。因以爲凡頟之偁。車軸之末見於轂外者曰軎。軎之言遂也、出也。如鄭說、轂末小穿曰軹。而軎出於此穿外。然古說軹軎多不分。如大馭右祭㒳軹。故書軹爲𨊻。杜子春云。𨊻當作軹。軹謂㒳轊也。是非合轂末軸末爲一乎。今按少儀曰。祭左右軌。大馭曰。祭㒳軹。於事實同。少儀曰祭笵。大馭曰祭軓。范軓於聲同。本無不合。祭㒳轊、所以祭輪也。祭軓、所以祭輿也。言輪輿而全車在是矣。轂末曰軹。乃大鄭刱說。子春未嘗謂轂末曰軹。此注當是本作故書𨊻爲軹。杜子春云。軹當作𨊻。謂㒳轊也。或讀𨊻爲簪筓之筓。葢㒳軎左右出轂外。如筓之出髮。然有鐵舝以鍵之。又似筓之毌髮也。故其字从幵。取上平岐頭之意。若轂末之穿不可冒此名。況當杜"}]},"輻":{"expl":"輪轑也。从車畐聲。","rad":"車","fq":"方六切","vol":"14","py":"fú","duan":[{"e":"輪轑也。","n":"以上六篆言轂而及軸末之出於轂者。故遂以湊於轂者終之也。輻凡三十。"}]},"轑":{"expl":"蓋弓也。一曰輻也。从車𤋯聲。","rad":"車","fq":"盧皓切","vol":"14","py":"lǎo","duan":[{"e":"車葢弓也。","n":"輪人爲葢。葢弓二十有八。以象恆星也。鄭注曰。弓者、葢橑也。葢弓曰轑。亦曰橑。橑者、椽也。形略相似也。重棼亦偁重轑。張敞傳殿屋重轑是也。釋名曰。轑、葢叉也。叉者、今爪字。非叉字。玉部瑵下曰。車葢玉瑵。以玉爲爪也。詳彼注。"}]},"軑":{"expl":"車輨也。从車大聲。","rad":"車","fq":"特計切","vol":"14","py":"dì","duan":[{"e":"車輨也。","n":"離騷曰。齊玉軑而竝馳。王逸釋爲車轄。非也。玉篇、廣韵皆云車轄。轄皆輨之誤也。"}]},"輨":{"expl":"轂端沓也。从車官聲。","rad":"車","fq":"古滿切","vol":"14","py":"ɡuǎn","duan":[{"e":"轂耑錔也。","n":"錔者、以金有所冒也。轂孔之裏以金裏之曰釭。轂孔之外以金表之曰輨。輨之言管也。方言曰。關之東西曰輨。南楚曰軑。趙魏之閒曰鍊𨬍。軑音大。鍊音柬。"}]},"嚶":{"expl":"鳥鳴也。从口嬰聲。","rad":"口","fq":"鳥莖切","vol":"02","py":"yīnɡ","duan":[{"e":"鳥鳴也。","n":"小雅。鳥鳴嚶嚶。毛曰。嚶嚶、驚懼也。釋訓曰。丁丁嚶嚶、相切直也。鄭曰。嚶嚶、㒳鳥聲也。按詩。鳥鳴嚶嚶。出自幽谷。本不言何鳥。昔人因嚶嚶似離黃之聲。出谷遷喬亦似離黃出蟄土而登樹。故就嚶改鸎爲倉庚之名。唐試士以鸎出谷命題。本毛詩也。古者倉庚名離黃、名？黃、名楚雀、名黃栗畱、黃鸝畱。不名黃鸎。亦無鸎字也。惟高誘注吕覽曰。含桃、鸎桃。鸎鳥所含。陸璣詩疏云。黃鸝畱、豳州人謂之黃鸎。鸎字始見。要因其聲製字耳。果名、依高誘作鸎桃爲是。鄭注月令作櫻桃者、乃俗人所改。詩交交桑扈。有鶯其羽。毛公云。鶯然有文章也。鶯絶非鸎。唐人耕韵鶯注。鳥羽文也。鸎注。黃鸎也。一韵中可竝用。舊本唐詩黃鸎字皆如此。元明以後淺人乃謂古"}]},"轅":{"expl":"輈也。从車袁聲。","rad":"車","fq":"雨元切","vol":"14","py":"yuán","duan":[{"e":"輈也。","n":"攷工記。輈人爲輈。車人爲大車之轅。是輈與轅别也。許渾言之者、通偁則一也。轅之言如攀援而上也。"}]},"輈":{"expl":"轅也。从車舟聲。","rad":"車","fq":"張流切","vol":"14","py":"zhōu","duan":[{"e":"轅也。从車。舟聲。","n":"張流切。三部。"}]},"䡞":{"expl":"直轅車纩也。从車具聲。","rad":"車","fq":"居玉切","vol":"14","py":"jú","duan":[{"e":"直轅𩎈也。","n":"按依車部？當系曲轅車。且此處列字次弟。應論車轅。不應論衡縛。韵會作直轅車也。無？字爲是。當從之。直轅車、大車也。"}]},"䡇":{"expl":"車轅耑持衡者。从車元聲。","rad":"車","fq":"魚厥切","vol":"14","py":"yuè","duan":[{"e":"車轅耑持衡者。","n":"衡者、橫木。長六尺六寸。以施軶駕馬頸者也。持衡者曰䡇。則衡與轅耑相接之關鍵也。戴先生曰。大車鬲以駕牛。小車衡以駕馬。轅耑持鬲。其關鍵名輗。輈耑持衡。其關鍵名軏。輈轅所以引車。必施輗軏然後行。信之在人、亦交接相持之關鍵。故孔子以輗軏喻信。"}]},"軶":{"expl":"轅前也。从車戹聲。","rad":"車","fq":"於革切","vol":"14","py":"è","duan":[{"e":"轅歬也。","n":"曰轅前者、謂衡也。自其橫言之謂之衡。自其扼制馬言之謂之軶。隷省作軛。毛詩韓奕作厄。士喪禮今文作厄。叚借字也。車人爲大車作鬲。亦叚借字。西京賦作槅。木部曰。槅、大車枙也。枙當作軶。"}]},"䡣":{"expl":"軶軥也。从車軍聲。","rad":"車","fq":"乎昆切","vol":"14","py":"hún","duan":[{"e":"軶軥也。","n":"軛軥之異名曰䡣也。䡣之言圍也。下圍馬頸也。廣韵曰。還也。車相避也。與古義異。"}]},"軥":{"expl":"軶下曲者。从車句聲。","rad":"車","fq":"古候切","vol":"14","py":"qú","duan":[{"e":"軶下曲者。","n":"軶木上平而下爲㒳坳。加於㒳服馬之頸。是曰軥。韓奕毛傳曰。厄、烏噣也。小爾雅曰。衡、㧖也。㧖下者謂之烏啄。釋名曰。槅、扼也。所以扼牛頭也。馬曰烏啄。下向叉馬頸。似烏開口向下啄物時也。噣啄同字。軶與軥同體。左傳。射㒳軥而還。服注。車軛㒳邊叉馬頸者。"}]},"轙":{"expl":"車衡載轡者。从車義聲。","rad":"車","fq":"魚綺切","vol":"14","py":"yǐ","duan":[{"e":"車衡載𦆕者。","n":"釋器曰。載轡謂之轙。郭云。車軛上環。轡所貫也。四馬八轡。除驂馬內轡納於軾前之觼。在手者惟六轡。驂馬外轡復有游環。以與服馬四轡同入軛上大環。以便總持。大環謂之轙。東京賦。龍輈華轙。此本義也。郊祀歌。靈禗禗。象輿轙。如淳曰。轙者、僕人嚴駕待發之意。此引申之義也。整船亦曰艤。同轙意。"}]},"軜":{"expl":"驂馬内轡繫軾前者。从車内聲。《詩》曰：“𣵽以𧥎軜。”","rad":"車","fq":"奴荅切","vol":"14","py":"nà","duan":[{"e":"驂馬內𦆕系軾歬者。","n":"系各本作繫。繫見糸部。非其義也。今正。驂馬㒳內轡爲環系諸軾前。故御者衹六轡在手。秦風毛傳曰。軜、驂內轡也。是則軜之言內、謂內轡也。其所入軾前之環曰觼。角部曰觼、環之有舌者是也。詩言觼軜者、言施觼於軜也。大戴禮。六官以爲轡。司會均入以爲軜。此引申叚借之義也。"}]},"䡓":{"expl":"車搖也。从車从行。一曰衍省聲。","rad":"車","fq":"古絢切","vol":"14","py":"juàn","duan":[{"e":"車搖也。","n":"未聞。以篆之次第詳之。此篆當亦謂車上一物。而今失傳。車搖當是譌字。"}]},"啄":{"expl":"鳥食也。从口豖聲。","rad":"口","fq":"竹角切","vol":"02","py":"zhuó","duan":[{"e":"鳥食也。","n":"鳥咮銳。食物似琢。吳都賦說水鳥曰。彫琢蔓藻。"}]},"𨋬":{"expl":"軺車後登也。从車丞聲。讀若《易》“抍馬”之抍。","rad":"車","fq":"署陵切","vol":"14","py":"chénɡ","duan":[{"e":"軺車後登也。","n":"廣韵十六蒸、四十二拯皆曰。𨋬、軺車後登。出字林。今按不言出說文。恐是吕氏後增之字。非許舊也。古車無不後登者。"}]},"載":{"expl":"乘也。从車𢦔聲。","rad":"車","fq":"作代切","vol":"14","py":"zài","duan":[{"e":"椉也。","n":"乗者、覆也。上覆之則下載之。故其義相成。引申之謂所載之物曰載。如詩載輸爾載。下載音才再反是也。引申爲凡載物之偁。如詩汎汎楊舟、載沈載浮、中庸天地之無不持載是也。又叚借之爲始。才之叚借也。才者、艸木之初也、夏曰載、亦謂四時終始也。又叚借爲事。詩上天之載。毛傳曰載、事也是也。又叚爲語䛐。詩載馳載驅。毛傳載、辭也。春日載陽。箋云載之言則也。"}]},"軍":{"expl":"圜圍也。四千人爲軍。从車，从包省。軍，兵車也。","rad":"車","fq":"舉云切","vol":"14","py":"jūn","duan":[{"e":"圜圍也。","n":"於字形得圜義。於字音得圍義。凡渾䡣煇等軍聲之字皆兼取其義。"}]},"軷":{"expl":"出，將有事於道，必先告其神，立壇四通，樹茅以依神，爲軷。旣祭軷，轢於牲而行，爲範軷。《詩》曰：“取羝以軷。”从車犮聲。","rad":"車","fq":"蒲撥切","vol":"14","py":"bá","duan":[{"e":"出將有事於道。必先告其神。立壇四通。尌茅㠯依神爲軷。","n":"此言軷之義"}]},"範":{"expl":"範軷也。从車，笵省聲。讀與犯同。","rad":"車","fq":"犯","vol":"14","py":"fàn","duan":[{"e":"範軷也。","n":"三字句。其義已見上。故衹云範軷也。"}]},"䡾":{"expl":"載高皃。从車，𣡌省聲。","rad":"車","fq":"五葛切","vol":"14","py":"niè","duan":[{"e":"載高貌。","n":"䡾䡾、車載高皃。衞風。庶姜孽孽。毛云。孽孽、盛飾。韓詩作䡾䡾、長皃。吕覽。宋王作爲蘖臺。高誘曰。蘖當作䡾。詩曰。庶姜䡾䡾。高長皃。然則韓爲本字。毛爲叚借字。爾雅。蓁蓁、孽孽、戴也。亦載高之意也。西京賦。飛檐䡾䡾。"}]},"轄":{"expl":"車聲也。从車害聲。一曰轄，鍵也。","rad":"車","fq":"胡八切","vol":"14","py":"xiá","duan":[{"e":"車聲也。","n":"轂與軸相切聲也。史記大人賦輵轄。漢書轄作螛。張揖曰。輵螛、搖目吐舌皃。則史記爲譌字矣。"}]},"轉":{"expl":"運也。从車專聲。","rad":"車","fq":"知戀切","vol":"14","py":"zhuǎn","duan":[{"e":"還也。","n":"還大徐作運。非。還者、復也。復者、往來也。運訓迻徙。非其義也。還卽今環字。"}]},"輸":{"expl":"委輸也。从車俞聲。","rad":"車","fq":"式朱切","vol":"14","py":"shū","duan":[{"e":"委輸也。","n":"委者、委隨也。委輸者、委隨輸寫也。以車遷賄曰委輸。亦單言曰輸。引申之、凡傾寫皆曰輸。輸於彼、則彼贏而此不足。故勝負曰贏輸。不足則如墮壞然。故春秋鄭人來輸平。公羊、穀梁皆曰。輸者、墮也。左傳作渝。渝、變也。"}]},"輖":{"expl":"重也。从車周聲。","rad":"車","fq":"職流切","vol":"14","py":"zhōu","duan":[{"e":"重也。","n":"謂車重也。小雅。戎車旣安。如輊如軒。毛曰。輊、摰也。考工記大車之轅摰。鄭曰。摰、輖也。士喪禮軒輖中。鄭曰。輖、𦥎也。摰𦥎輊同字。輖雙聲。許書有輖摰而已。摰者、依聲託事字也。軒言車輕。輖言車重。引申爲凡物之輕重。故禮經以之言矢。周南叚輖爲？字。故毛傳曰。輖、？也。而說詩者或以本義釋之。"}]},"唬":{"expl":"嗁聲也。一曰虎聲。从口从虎。讀若暠。","rad":"口","fq":"呼訏切","vol":"02","py":"xiāo","duan":[{"e":"虎聲也。","n":"鍇本不誤。鉉本改爲嗁聲。誤甚。自吠篆已下。皆言鳥獸矣。通俗文曰。虎聲謂之哮。唬當讀呼去聲。亦讀如罅字。从虎口、虎亦聲也。五部。"}]},"輩":{"expl":"若軍發車百兩爲一輩。从車非聲。","rad":"車","fq":"補妹切","vol":"14","py":"bèi","duan":[{"e":"若軍發車百㒳爲輩。","n":"㒳各本作兩。今正。車之偁㒳者、謂一車㒳輪。無取二十四銖之兩。此許之字例也。若軍發車百㒳爲輩、葢用司馬灋故言。故以若發聲。今司馬灋存者尟矣。引申之爲什伍同等之偁。如鄭注宫正云。使之輩作輩學。相勸帥也。"}]},"軋":{"expl":"𨋚也。从車乙聲。","rad":"車","fq":"烏轄切","vol":"14","py":"yà","duan":[{"e":"𨋁也。","n":"𨋁大徐作輾。非也。匈奴傳曰。有罪小者軋。大者死。顏曰。謂輾轉轢其骨節。按本謂車之𨋁於路。引申之爲勢相傾。"}]},"𨋚":{"expl":"轢也。从車㞋聲。","rad":"車","fq":"尼展切","vol":"14","py":"niǎn","duan":[]},"轢":{"expl":"車所踐也。从車樂聲。","rad":"車","fq":"郎擊切","vol":"14","py":"lì","duan":[{"e":"車所踐也。","n":"踐者、𡳐也。軷下曰轢牲而行是也。"}]},"軌":{"expl":"車徹也。从車九聲。","rad":"車","fq":"居洧切","vol":"14","py":"ɡuǐ","duan":[{"e":"車徹也。","n":"攴部曰。徹者、通也。車徹者、謂輿之下㒳輪之閒空中可通。故曰車徹。是謂之車軌。軌之名謂輿之下隋方空處。老子所謂當其無有車之用也。高誘注吕氏春秋曰。㒳輪之閒曰軌。毛公匏有苦葉傳曰。由輈以下曰軌。合此二語、知軌所在矣。上歫輿。下歫地。㒳旁歫輪。此之謂軌。毛云由輈以下、則輿下之輈、軌也。輈下之軸、軌也。虚空之處未至於地皆軌也。濡軌者、水濡輪閒空虛之處。而至於軸。而至於輈。則必入輿矣。故濟盈𣃔無有濟濡軌之水者。禮義之大防也。毛何以不言㒳輪之閒、而言由輈以下乎。曰㒳輪之閒、自廣陿言之。凡言度涂以軌者、必以之。由輈以下、自高庳言之。詩言濡軌、晏子言其深滅軌、以之。中庸車同軌、兼廣陿高庳言之。徹廣六尺。軹崇三"}]},"𨌰":{"expl":"車迹也。从車，從省聲。","rad":"車","fq":"卽容切","vol":"14","py":"zōnɡ","duan":[{"e":"車迹也。","n":"㒳輪之迹也。迹者、步處也。因引申爲凡迹之偁。㒳輪之迹亦謂之軌徹。而非軌徹之體也。莊子曰。夫迹、𡳐之所出。而迹豈𡳐也。𨌰之言從也。有所從來也。又可從是以求其質也。𨌰古字衹作從。羔羊傳曰。委蛇委蛇、行可從迹也。君子偕老傳曰。委委、行可委曲從迹也。俗變爲蹤。再變爲踪。固不若用許書𨌰字矣。"}]},"軼":{"expl":"車相出也。从車失聲。","rad":"車","fq":"夷質切","vol":"14","py":"yì","duan":[{"e":"車相出也。","n":"車之後者、突出於前也。楚辭。軼迅風於清源。禹貢。沇水入于河。泆爲熒。漢志作軼。鄭注司㓝曰。過失若舉刃欲斫伐而軼中人者。皆本義之引申叚借也。"}]},"䡩":{"expl":"車䡩𨥺也。从車眞聲。讀若《論語》“鏗尔，舍瑟而作”。又讀若掔。","rad":"車","fq":"苦閑切","vol":"14","py":"kēnɡ","duan":[{"e":"車䡩弘聲也。","n":"弘大徐作鈏。非。小徐作？。集韵作䡏。亦誤。今正。？、谷中響也。宖、屋響也。弘、弓聲也。車聲䡩弘、借弓聲之字耳。䡩弘、大聲。"}]},"𨎌":{"expl":"抵也。从車埶聲。","rad":"車","fq":"陟利切","vol":"14","py":"zhì","duan":[{"e":"抵也。","n":"抵者、擠也。擠者、排也。車抵於是而不過、是曰？。如馬之不前曰？驇。詳𡴂部。？與車重之摰𦥎輊䡹本各義。與輖又殊音。而集韵緫合爲一字。誤矣。小徐引潘岳賦如？如軒。今按潘作䡹、不作？也。"}]},"軭":{"expl":"車戾也。从車匡聲。","rad":"車","fq":"巨王切","vol":"14","py":"kuánɡ","duan":[{"e":"車戾也。","n":"戾者、曲也。考工記曰。萭之以眂其匡也。注云。等爲萭蔞以運輪上。輪中萭蔞則不匡剌也。軭不專謂輪。凡偏戾皆是。"}]},"呦":{"expl":"鹿鳴聲也。从口幼聲。","rad":"口","fq":"伊虬切","vol":"02","py":"yōu","duan":[{"e":"鹿鳴聲也。","n":"見小雅。"}]},"輟":{"expl":"車小缺復合者。从車叕聲。","rad":"車","fq":"陟劣切","vol":"14","py":"chuò","duan":[]},"䡔":{"expl":"礙也。从車多聲。","rad":"車","fq":"康禮切","vol":"14","py":"qǐ","duan":[{"e":"礙也。","n":"礙者、止也。"}]},"轚":{"expl":"車轄相擊也。从車从毄，毄亦聲。《周禮》曰：“舟輿擊互者。”","rad":"車","fq":"古歴切","vol":"14","py":"jí","duan":[{"e":"車轄相擊也。","n":"轄者、鍵也。鍵在軎頭。謂車軎相擊也。諸書亦言車轂相擊。"}]},"𨏉":{"expl":"治車軸也。从車算聲。","rad":"車","fq":"所眷切","vol":"14","py":"shuàn","duan":[{"e":"治車軸也。","n":"治篇、韵皆作？。四字句。鏇轉規圜之意。"}]},"軻":{"expl":"接軸車也。从車可聲。","rad":"車","fq":"康我切","vol":"14","py":"kě","duan":[{"e":"椄軸車也。","n":"椄各本作接。今正。椄者、續木也。軸所以持輪。而㒳木相椄則危矣。故引申之多迍曰轗軻。趙邠卿曰。孟子名軻。字則未聞也。而廣韵曰。孟子居貧轗軻。故名軻。字子居。"}]},"䡰":{"expl":"車堅也。从車殸聲。","rad":"車","fq":"口莖切","vol":"14","py":"kēnɡ","duan":[{"e":"車堅也。","n":"堅者、剛也。"}]},"軵":{"expl":"反推車，令有所付也。从車从付。讀若胥。","rad":"車","fq":"而隴切","vol":"14","py":"rǒnɡ","duan":[{"e":"反推車令有所付也。","n":"反推車者、謂不順也。付、與也。本可不與、而故欲與之。至於逆推車以與之而不顧。此說其字之會意也。故其字从車付。"}]},"輪":{"expl":"有輻曰輪，無輻曰輇。从車侖聲。","rad":"車","fq":"力屯切","vol":"14","py":"lún","duan":[{"e":"有輻曰輪。","n":"云有輻者、對無輻而言也。輪之言倫也。从侖。侖、理也。三十輻㒳㒳相當而不迆。故曰輪。"}]},"輇":{"expl":"蕃車下庳輪也。一曰無輻也。从車全聲。讀若饌。","rad":"車","fq":"市緣切","vol":"14","py":"quán","duan":[{"e":"蕃車下庳輪也。","n":"蕃當作藩。藩車見軒字下。庳者、屋卑也。因以爲凡？之偁。藩車而下爲卑輪。葢所謂安車。輪卑則車安矣。未知是否。"}]},"輗":{"expl":"大車轅耑持衡者。从車兒聲。","rad":"車","fq":"五雞切","vol":"14","py":"ní","duan":[{"e":"大車轅耑持衡者也。","n":"轅與衡相接之關鍵也。墨子曰。吾不知爲車輗者巧也。用咫尺之木。不費一朝之事。而引三十石之任。此與小車之䡇同用而異名。許不與䡇篆爲伍者、大車别於小車也。自輗至輂五篆皆言大車。前文䡞篆當亦廁此處。"}]},"噳":{"expl":"麋鹿羣口相聚皃。从口虞聲。《詩》曰：“麀鹿噳噳。”","rad":"口","fq":"魚矩切","vol":"02","py":"yǔ","duan":[{"e":"麋鹿羣口相聚皃。","n":"大雅。麀鹿噳噳。毛曰。噳噳然衆也。小雅。麀鹿麌麌。毛曰。麌麌、衆多也。按毛意麌麌卽噳噳之假借也。說文無麌。"}]},"軧":{"expl":"大車後也。从車氐聲。","rad":"車","fq":"丁禮切","vol":"14","py":"dǐ","duan":[{"e":"大車後也。","n":"大車以載任器。牝負長八尺。謂較也。其後必崇。其闌與三面等。非若小車之後也。故曰軧。軧之言底也。"}]},"轃":{"expl":"大車簀也。从車秦聲。讀若臻。","rad":"車","fq":"側詵切","vol":"14","py":"zhēn","duan":[{"e":"大車簀也。","n":"此以雙聲爲訓。簀者、牀棧也。大車之藉似之。小車謂之茵。車重席也。以虎皮者謂之文茵。大車謂之轃。竹木爲之。"}]},"轒":{"expl":"淮陽名車穹隆轒。从車賁聲。","rad":"車","fq":"符分切","vol":"14","py":"fén","duan":[{"e":"淮陽名車穹隆轒。","n":"淮陽、漢國。有縣九。今開封府陳州以南是其地。車穹隆、卽車葢弓也。方言曰。車枸簍、宋魏陳楚之閒謂之䈐。或謂之𥳎籠。秦晉之閒自關而西謂之枸簍。西隴謂之？。南楚之外謂之篷。或謂之隆屈。郭云。卽車弓也。按許之穹隆卽𥳎籠也。許之轒葢卽㮥字與。抑淮陽謂之轒、爲方言所不載也。釋名曰隆强。或曰車弓。長楊賦碎轒輼。别一義也。"}]},"䡝":{"expl":"大車後壓也。从車宛聲。","rad":"車","fq":"於云切","vol":"14","py":"yuān","duan":[{"e":"大車後壓也。","n":"壓當依玉篇作厭。厭、笮也。所以鎭大車後者。"}]},"輂":{"expl":"大車駕馬也。从車共聲。","rad":"車","fq":"居玉切","vol":"14","py":"jú","duan":[{"e":"大車駕馬者也。","n":"者字今補。小司徒。正治輂輦。注曰。輂、駕馬。所以載任器。與許說同。云大車駕馬者、言者以别於駕牛也。古大車多駕牛。其駕馬者則謂之輂。按左氏傳。陳畚梮。梮者、土轝。漢五行志作輂。是梮乃輂之或字也。史河渠書。山行卽橋。一作檋。夏本紀正作檋。漢溝洫志作山行則梮。韋昭曰。梮、木器。如今𨏮牀。人舉以行也。然則周禮輂之制。四方如車之輿。故曰轝。或作𨏮。或駕馬、或人舉皆宜。用之徙土、則謂之土轝。卽公羊之筍。史記之箯輿也。用之舁人、則謂之橋。橋卽漢書輿轎而越嶺之轎字也。左氏正義謂梮字从手。其說非是。禮經輁軸。輁卽輂字之異者。注云。輁狀如長牀是也。夏禹四載乗輂。葢亦馬引之。不然。何以云桀始乗人車。攷古者所當辯也。"}]},"𨌅":{"expl":"連車也。一曰却車抵堂爲𨌅。从車，差省聲。讀若遟。","rad":"車","fq":"士皆切","vol":"14","py":"chái","duan":[{"e":"連車也。","n":"謂車牽聯而行、有等差也。左傳差車、官名。"}]},"輦":{"expl":"輓車也。从車，从㚘在車前引之。","rad":"車","fq":"力展切","vol":"14","py":"niǎn","duan":[{"e":"輓車也。","n":"謂人輓以行之車也。小司徒輂輦注曰。輦、人輓行。所以載任器也。司馬法云。夏后氏謂輦曰余車。殷曰胡奴車。周曰輜輦。夏后氏二十人而輦。殷十八人而輦。周十五人而輦。故書輦作連。鄭司農云。連讀爲輦。按夫部㚘、竝行也。輦字从此。輦設輅於車前。用索輓之。故从車㚘會意。㚘在前。車在後。故連字下曰負車。連輦古今字。周禮、管子皆作連。此車名輦。輓此車之人名輦者。爾雅曰。徒御不警。徒、輦者也。毛傳同。又詩。我任我輦。毛傳曰。任者、輦者。釋名曰。輦、人所輦也。"}]},"輓":{"expl":"引之也。从車免聲。","rad":"車","fq":"無遠切","vol":"14","py":"wǎn","duan":[{"e":"引車也。","n":"引車曰輓。引申之、凡引皆曰輓。左傳曰。或輓之。或推之。欲無入、得乎。史記借爲晚字。"}]},"軖":{"expl":"紡車也。一曰一輪車。从車㞷聲。讀若狂。","rad":"車","fq":"巨王切","vol":"14","py":"kuánɡ","duan":[]},"轘":{"expl":"車裂人也。从車瞏聲。《春秋傳》曰：“轘諸栗門。”","rad":"車","fq":"胡慣切","vol":"14","py":"huàn","duan":[{"e":"車裂人也。","n":"周禮條狼氏。誓僕右曰殺。誓馭曰車轘。注曰。車轘、謂車裂也。"}]},"喁":{"expl":"魚口上見。从口禺聲。","rad":"口","fq":"魚容切","vol":"02","py":"yónɡ","duan":[{"e":"魚口上見。","n":"師古、玄應皆作衆口。按魚是也。淮南書。水濁則魚噞喁。劉逵注吳都賦曰。噞喁、魚在水中羣出動口皃。喁本狀魚。引伸他用。如論語素王受命讖莫不喁喁延頸歸德、淮南書羣生莫不喁喁然仰其德、司馬相如傳延頸舉踵喁喁然皆是也。"}]},"斬":{"expl":"𢧵也。从車从斤。斬法車裂也。","rad":"車","fq":"側減切","vol":"14","py":"zhǎn","duan":[{"e":"𢧵也。","n":"𢧵者、𣃔也。𩠐部？、𢧵也。周禮掌戮注曰。斬以鈇鉞。若今𦝫斬也。殺以刀刃。若今棄市也。本謂斬人。引申爲凡絕之偁。"}]},"輭":{"expl":"喪車也。从車而聲。","rad":"車","fq":"如之切","vol":"14","py":"ér","duan":[]},"輔":{"expl":"人頰車也。从車甫聲。","rad":"車","fq":"扶雨切","vol":"14","py":"fǔ","duan":[{"e":"春秋傳曰。輔車相依。","n":"凡許書有不言其義徑舉經傳者。如？下云詞之？矣、鶴下云鶴鳴九皋聲聞于天、艴下云色艴如也、絢下云詩云素以爲絢兮之類是也。此引春秋傳僖公五年文。不言輔義者、義已具於傳文矣。小雅正月曰。其車旣載。乃棄爾輔。傳曰。大車旣載。又棄其輔也。無棄爾輔。員于爾輻。傳曰。員、益也。正義云。大車、牛車也。爲車不言从輔。此云棄輔、則輔是可解脫之物。葢如今人縛杖於輻以防輔車也。今按呂覽權勳篇曰。宫之奇諫虞公曰。虞之與虢也。若車之有輔也。車依輔。輔亦依車。虞虢之勢是也。此卽詩無棄爾輔之說也。合詩與左傳則車之有輔信矣。引申之義爲凡相助之偁。今則借義行而本義廢。尠有知輔爲車之一物者矣。人部曰。俌、輔也。以引申之義釋本義也。今"}]},"轟":{"expl":"羣車聲也。从三車。","rad":"車","fq":"呼宏切","vol":"14","py":"hōnɡ","duan":[{"e":"轟轟、","n":"二字依文𨕖注補"}]},"轏":{"expl":"車名。从車孱聲。","rad":"車","fq":"士限切","vol":"14","py":"zhàn","duan":[]},"轔":{"expl":"車聲。从車粦聲。","rad":"車","fq":"力珍切","vol":"14","py":"lín","duan":[]},"轍":{"expl":"車迹也。从車，徹省聲。本通用徹，後人所加。","rad":"車","fq":"直列切","vol":"14","py":"zhé","duan":[]},"𠂤":{"expl":"小𨸏也。象形。凡𠂤之屬皆从𠂤。","rad":"𠂤","fq":"都回切","vol":"14","py":"duī","duan":[{"e":"小𨸏也。","n":"小𨸏、𨸏之小者也。廣雅本之。曰。𠂤、細阜也。今譌舛不可讀矣。小𨸏曰𠂤。國語叚借魁字爲之。周語。夫高山而蕩以爲魁陵糞土。賈逵、韋昭皆曰。小阜曰魁。卽許之𠂤也。賈逵注見海賦。其字俗作堆。堆行而𠂤廢矣。氏下云。山岸脅之堆、旁箸欲落𡐦者曰氏。小徐作堆。大徐則刪之。士冠禮注。追猶堆也。是追卽𠂤之叚借字。李善注七發曰。追古堆字。詩。追琢其章。追亦同𠂤。葢古治金玉突起者爲𠂤。穿穴者爲琢。𠂤語之轉爲敦。如爾雅之敦丘。俗作墩。詩。敦彼獨宿。傳以敦敦然釋之。皆是也。"}]},"𡴎":{"expl":"危高也。从𠂤屮聲。讀若臬。","rad":"𠂤","fq":"魚列切","vol":"14","py":"niè","duan":[{"e":"危高也。从𠂤。屮聲。讀若臬。","n":"魚列切。十五部"}]},"官":{"expl":"吏，事君也。从宀从𠂤。𠂤猶眾也。此與師同意。","rad":"𠂤","fq":"古丸切","vol":"14","py":"ɡuān","duan":[{"e":"吏事君也。从宀𠂤。","n":"會意。古丸切。十四部。"}]},"局":{"expl":"促也。从口在尺下，復局之。一曰博，所以行棊。象形。","rad":"口","fq":"渠綠切","vol":"02","py":"jú","duan":[{"e":"促也。","n":"以㬪韵爲訓。"}]},"𨸏":{"expl":"大陸，山無石者。象形。凡𨸏之屬皆从𨸏。","rad":"𨸏","fq":"房九切","vol":"14","py":"fù","duan":[{"e":"大陸也。","n":"也字今補。釋地、毛傳皆曰。大陸曰阜。李巡曰。高平曰陸。謂土地豐正名爲陸。陸土地獨高大名曰阜。阜冣大名爲陵。引申之爲凡厚、凡大、凡多之稱。秦風傳曰。阜、大也。鄭風傳曰。阜、盛也。國語注曰。阜、厚也。皆由土山高厚演之。"}]},"陵":{"expl":"大𨸏也。从𨸏夌聲。","rad":"𨸏","fq":"力膺切","vol":"14","py":"línɡ","duan":[{"e":"大𨸏也。","n":"釋地、毛傳皆曰。大阜曰陵。釋名曰。陵、隆也。體隆高也。按引申之爲乘也、上也、躐也、侵陵也、陵夷也。皆夌字之叚借也。久部曰。夌、越也。一曰。夌、徲也。夌徲、卽陵夷也。"}]},"䧰":{"expl":"大𨸏也。从𨸏鯀聲。","rad":"𨸏","fq":"胡本切","vol":"14","py":"hùn","duan":[{"e":"大𨸏也。","n":"以其昆干綿遠爲言。"}]},"阞":{"expl":"地理也。从𨸏力聲。","rad":"𨸏","fq":"盧則切","vol":"14","py":"lè","duan":[{"e":"地理也。","n":"攷工記曰。凡溝逆地阞。謂之不行。注云。溝謂造溝。阞謂脈理。按力者、筋也。筋有脈絡可尋。故凡有理之字皆从力。阞者、地理也。朸者、木理也。泐者、水理也。手部有扐、亦同意。"}]},"陰":{"expl":"闇也。水之南、山之北也。从𨸏侌聲。","rad":"𨸏","fq":"於今切","vol":"14","py":"yīn","duan":[{"e":"闇也。","n":"闇者、閉門也。閉門則爲幽暗。故以爲高明之反。"}]},"陽":{"expl":"高、明也。从𨸏昜聲。","rad":"𨸏","fq":"與章切","vol":"14","py":"yánɡ","duan":[{"e":"高朙也。","n":"闇之反也。"}]},"陸":{"expl":"高平地。从𨸏从坴，坴亦聲。","rad":"𨸏","fq":"力竹切","vol":"14","py":"lù","duan":[{"e":"高平地。","n":"釋地、毛傳皆曰。高平曰陸。"}]},"阿":{"expl":"大陵也。一曰曲𨸏也。从𨸏可聲。","rad":"𨸏","fq":"烏何切","vol":"14","py":"ē","duan":[{"e":"大陵曰阿。","n":"釋地、毛傳皆曰。大陵曰阿。"}]},"陂":{"expl":"阪也。一曰沱也。从𨸏皮聲。","rad":"𨸏","fq":"彼爲切","vol":"14","py":"bēi","duan":[{"e":"阪也。","n":"陂與坡音義皆同。凡陂必邪立。故引申之義爲傾邪。子虛賦。罷池陂陀。言旁穨也。易。無平不陂。洪範。無偏無陂。"}]},"阪":{"expl":"坡者曰阪。一曰澤障。一曰山脅也。从𨸏反聲。","rad":"𨸏","fq":"府遠切","vol":"14","py":"bǎn","duan":[{"e":"坡者曰阪。","n":"釋地、毛傳皆曰。陂者曰阪。許云坡者曰阪。然則坡陂異部同字也。說卦傳。其於稼也爲反生。叚借反爲阪也。"}]},"㕣":{"expl":"山閒陷泥地。从口，从水敗皃。讀若沇州之沇。九州之渥地也，故以沇名焉。","rad":"口","fq":"以轉切","vol":"02","py":"yǎn","duan":[{"e":"山閒陷泥地。","n":"閒玉篇作㵎。陷當作淊。字之誤。水部曰。淊、泥水淊淊也。"}]},"陬":{"expl":"阪隅也。从𨸏取聲。","rad":"𨸏","fq":"子侯切","vol":"14","py":"zōu","duan":[{"e":"阪隅也。","n":"謂阪之角也。正月爲陬。亦謂寅方在東北隅也。引申爲凡隅之偁。陬與隅㬪韵爲訓。"}]},"隅":{"expl":"陬也。从𨸏禺聲。","rad":"𨸏","fq":"噳俱切","vol":"14","py":"yú","duan":[{"e":"陬也。","n":"隅與陬爲轉注。廣雅曰。陬、角也。小雅箋曰。丘隅、丘角也。上言阪此不言阪者、不主謂阪之隅也。考工記宮隅、城隅、謂角浮思也。大雅。惟德之隅。傳曰。隅、廉也。今人謂邊爲廉。角爲隅。古不別其字。亦作嵎、作湡。"}]},"險":{"expl":"阻，難也。从𨸏僉聲。","rad":"𨸏","fq":"虚檢切","vol":"14","py":"xiǎn","duan":[{"e":"阻難也。从𨸏。僉聲。","n":"虛檢切。七部。"}]},"限":{"expl":"阻也。一曰門榍。从𨸏艮聲。","rad":"𨸏","fq":"乎簡切","vol":"14","py":"xiàn","duan":[{"e":"阻也。","n":"廣韵。度也。齊也。畍也。皆其引申之義。"}]},"阻":{"expl":"險也。从𨸏且聲。","rad":"𨸏","fq":"側呂切","vol":"14","py":"zǔ","duan":[{"e":"險也。从𨸏。且聲。","n":"大射儀。且左還母周。注曰。古文且爲阻。堯典古文。黎民俎飢。鄭注云。俎讀曰阻。是皆古文叚借字也。側呂切。五部。"}]},"陮":{"expl":"陮隗，高也。从𨸏隹聲。","rad":"𨸏","fq":"都辠切","vol":"14","py":"duì","duan":[{"e":"陮隗、","n":"逗。"}]},"隗":{"expl":"陮隗也。从𨸏鬼聲。","rad":"𨸏","fq":"五辠切","vol":"14","py":"wěi","duan":[{"e":"陮隗也。从𨸏。鬼聲。","n":"五辠切。十五部。"}]},"阭":{"expl":"高也。一曰石也。从𨸏允聲。","rad":"𨸏","fq":"余準切","vol":"14","py":"yǔn","duan":[{"e":"高也。从𨸏。允聲。","n":"余準切。玉篇余剸切。十三十四部。"}]},"𨻌":{"expl":"磊也。从𨸏𠂹聲。","rad":"𨸏","fq":"洛猥切","vol":"14","py":"lěi","duan":[{"e":"磊𨻌也。","n":"各本奪𨻌字。今補。磊𨻌猶磊？也。㬪韵字。"}]},"陗":{"expl":"陖也。从𨸏肖聲。","rad":"𨸏","fq":"七笑切","vol":"14","py":"qiào","duan":[{"e":"陖也。","n":"凡斗直者曰陗。李斯列傳曰。樓季也而難五丈之限。跛牂也而易百仞之高。陗塹之勢異也。塹當爲漸。陂陀者曰漸。斗直者曰陗。凡閒出者曰㕊陗。斗俗作陡。古書皆作斗。"}]},"哦":{"expl":"吟也。从口我聲。","rad":"口","fq":"五何切","vol":"02","py":"é","duan":[]},"陖":{"expl":"陗高也。从𨸏夋聲。","rad":"𨸏","fq":"私閏切","vol":"14","py":"jùn","duan":[{"e":"陗高也。","n":"謂斗直而高也。卑者雖直、不得云陖矣。山部𡺲或作峻。高也。此陖、陗高也。是峻陖之別也。專言高者、或未必陗矣。陖古叚借洒字爲之。邶風曰。新臺有洒。傳曰。洒、高峻也。峻卽陖之同音通用。傳意謂經之洒、卽陖之叚借也。西聲夋聲古音同在十三部。釋丘曰。望厓洒而高岸。夷上洒下漘。洒而高、謂體斗直而頂高出也。夷上洒下、謂頂平不高出而體亦斗直也。李巡注甚明了。而郭樸說誤。"}]},"隥":{"expl":"仰也。从𨸏登聲。","rad":"𨸏","fq":"都鄧切","vol":"14","py":"dènɡ","duan":[{"e":"仰也。","n":"仰者、舉也。登陟之道曰隥。亦作墱。西都賦。陵墱道而超西墉。西京賦。墱道邐倚以正東。薛曰。墱、閣道也。按閣道謂淩空如棧道者。"}]},"𨹟":{"expl":"阨陜也。从𨸏㔷聲。","rad":"𨸏","fq":"盧𠊱切","vol":"14","py":"lòu","duan":[{"e":"阸陜也。","n":"阸者、塞也。陜者、隘也。𨺅部曰。隘者、陋也。然則陋與隘爲轉注。阸陜者、如邊塞狹隘也。故从𨸏。引申爲凡鄙小之偁。賈子曰。反雅爲陋。淮南注曰。陋、鄙小也。"}]},"陜":{"expl":"隘也。从𨸏夾聲。","rad":"𨸏","fq":"矦夾切","vol":"14","py":"xiá","duan":[{"e":"隘也。从𨸏。夾聲。","n":"侯夾切。八部。俗作陿、峽、狹。"}]},"陟":{"expl":"登也。从𨸏从步。","rad":"𨸏","fq":"竹力切","vol":"14","py":"zhì","duan":[{"e":"登也。","n":"釋詁曰。陟、陞也。毛傳曰。陟、𦫵也。陞者、𦫵之俗字。𦫵者、登之叚借。禮喪服注曰。今文禮皆登爲𦫵。俗誤巳行久矣。據鄭說則古文禮皆作登也。許此作登不作𦫵者、許書說解不用叚借字也。漢人用同音字代本字。旣乃不知有本字。所謂本有其字、依聲託事者然也。"}]},"陷":{"expl":"高下也。一曰陊也。从𨸏从臽，臽亦聲。","rad":"𨸏","fq":"戶𤟟切","vol":"14","py":"xiàn","duan":[{"e":"高下也。","n":"高下者、高與下有懸絕之勢也。高下之形曰陷。故自高入於下亦曰陷。義之引申也。易曰。坎、陷也。謂陽陷陰中也。凡深𣳚其中曰陷。"}]},"隰":{"expl":"阪下溼也。从𨸏㬎聲。","rad":"𨸏","fq":"似入切","vol":"14","py":"xí","duan":[{"e":"阪下溼也。","n":"釋丘曰。下溼曰隰。又曰。陂者曰阪。下者曰隰。葢上隰指平地言之。下隰指阪言之。阪形固高、而其四旁窊溼處亦謂之隰也。許用後說者、以其字从𨸏也。"}]},"䧢":{"expl":"𢼮也。从𨸏區聲。","rad":"𨸏","fq":"豈俱切","vol":"14","py":"qū","duan":[{"e":"㩻䧢也。","n":"各本奪䧢字。今補。危部㩻篆下曰。㩻䧢也。此亦曰㩻䧢也。㩻䧢以雙聲成文。謂傾側不安、不能久立也。不容刪一字矣。㩻䧢、他書作崎嶇。漢碑亦作嶇。"}]},"隤":{"expl":"下隊也。从𨸏貴聲。","rad":"𨸏","fq":"杜回切","vol":"14","py":"tuí","duan":[{"e":"下隊也。","n":"𣪠辭曰。夫乾確然示人易矣。夫坤隤然示人𥳑矣。許冂部曰。隺、高至也。引易夫乾隺然。然則正與下隊作反對語。按隤、與穨音同而義異。如李陵傳隤其家聲、𣃔不可作穨矣。"}]},"隊":{"expl":"從高隊也。从𨸏㒸聲。","rad":"𨸏","fq":"徒對切","vol":"14","py":"zhuì","duan":[{"e":"從高隊也。","n":"隊墜正俗字。古書多作隊。今則墜行而隊廢矣。大徐以墜附土部。非許意。釋詁。隊、落也。釋文从墜而以隊附見。傎矣。左傳曰。以成一隊。杜注。百人爲隊。葢古語一隊、猶言一堆。物墮於地則聚。因之名隊爲行列之偁。後人以墜入至韵。以隊入隊韵。而莫測其原委矣。"}]},"㻝":{"expl":"玉也。从玉剌聲。","rad":"玉","fq":"盧達切","vol":"01","py":"là","duan":[{"e":"玉也。从王。剌聲。","n":"盧達切。十五部。"}]},"嗃":{"expl":"嗃嗃，嚴酷皃。从口高聲。","rad":"口","fq":"呼各切","vol":"02","py":"hè","duan":[]},"降":{"expl":"下也。从𨸏夅聲。","rad":"𨸏","fq":"古巷切","vol":"14","py":"jiànɡ","duan":[{"e":"下也。","n":"此下爲自上而下。故廁於隊隕之閒。釋詁曰。降、落也。古多叚降爲夅。夂部曰。夅、服也。此今人讀下江切之正字。詩召南。我心則降。毛傳曰。降、下也。春秋經。郕降于齊師。何注曰。降者、自伏之文。又齊人降鄣。穀梁傳曰。降猶下也。皆夅之叚借字也。分爲平去韵、而昧其原委矣。以地言曰降、故从𨸏。以人言曰夅、故从夂㐄相承。"}]},"隕":{"expl":"從高下也。从𨸏員聲。《易》曰：“有隕自天。”","rad":"𨸏","fq":"于敏切","vol":"14","py":"yǔn","duan":[{"e":"從高下也。","n":"釋詁曰。隕、下、落也。毛傳曰。隕、隋也。隋卽陊字。"}]},"隉":{"expl":"危也。从𨸏，从毀省。徐巡以爲：隉，凶也。賈侍中說：隉，法度也。班固說：不安也。《周書》曰：“邦之阢隉。”讀若虹蜺之蜺。","rad":"𨸏","fq":"五結切","vol":"14","py":"niè","duan":[{"e":"危也。","n":"危者、在高而懼也。秦誓曰。邦之杌隉。易作臲卼。許出部之槷𦤙、不安也。皆字異而音義同。"}]},"阤":{"expl":"小崩也。从𨸏也聲。","rad":"𨸏","fq":"丈尔切","vol":"14","py":"zhì","duan":[{"e":"小𡹔也。","n":"大曰𡹔。小曰阤。吳都賦曰。崩巒阤岑。此其義也。子虛賦曰。登降阤靡。上林賦曰。巖阤甗錡。皆謂欹傾也。後人多用陊爲之。古書或用褫爲之。"}]},"隓":{"expl":"敗城𨸏曰隓。从𨸏𢀡聲。","rad":"𨸏","fq":"許規切","vol":"14","py":"huī","duan":[{"e":"敗城𨸏曰隓。从𨸏。𢀡聲。","n":"許書無𢀡字。葢或古有此文。或絫左爲聲。皆未可知。𡐦爲篆文、則隓爲古籒可知也。山部隓曰隓聲。肉部隋曰隓省聲。皆用此爲聲也。小篆隓作𡐦。隷變作墮。俗作隳。用墮爲𡹔落之義。用隳爲傾壞之義。習非成是。積習難反也。虞書曰。萬事墮哉。墮本敗城阜之偁。故其字从𨸏。引申爲凡阤壞之偁。許規切。古音在十七部。"}]},"𨻺":{"expl":"仄也。从𨸏从頃，頃亦聲。","rad":"𨸏","fq":"去營切","vol":"14","py":"qīnɡ","duan":[{"e":"仄也。","n":"仄下曰。側傾也。頃者、頭不正也。故从頁。傾者、人之仄也。故从人。？者、山阜之仄也。故从𨸏。禹貢西頃、葢可作此字。"}]},"陊":{"expl":"落也。从𨸏多聲。","rad":"𨸏","fq":"徒果切","vol":"14","py":"duò","duan":[{"e":"落也。","n":"艸部曰。艸曰苓。木曰落。引申之、凡自上而下皆曰落。石部？下曰。上摘山巖空靑珊瑚陊之。吳都賦曰。？陊山谷。按今字叚墮爲陊。而叚陊爲阤。義雖略相近。而實本不同。召南毛傳。盛極則隋落者梅也。又叚隋爲陊。"}]},"阬":{"expl":"門也。从𨸏亢聲。","rad":"𨸏","fq":"客庚切","vol":"14","py":"kēnɡ","duan":[{"e":"閬也。","n":"閬者、門高大之皃也。引申之、凡孔穴深大皆曰閬阬。釋詁云。虛也。地之孔穴虛處與門同。故曰閬也。以㬪韵爲訓。詩曰。皋門有伉。然則門亦得偁阬也。○今按閬訓迂遠。疑本作？。俗作？。又譌閬耳。阬塹、亦？阻也。土部曰。塹者、阬也。然則阬者塹也爲轉注。"}]},"𨽍":{"expl":"通溝也。从𨸏賣聲。讀若瀆。","rad":"𨸏","fq":"徒谷切","vol":"14","py":"dú","duan":[{"e":"通溝。","n":"句。西都賦曰。通溝大漕。潰渭洞河。"}]},"防":{"expl":"隄也。从𨸏方聲。","rad":"𨸏","fq":"符方切","vol":"14","py":"fánɡ","duan":[{"e":"隄也。","n":"周禮稻人曰。以防止水。注云。偃豬者、畜流水之陂也。防者、豬旁隄也。引申爲凡備禦之偁。禮記鄭目錄云。名曰坊記者、以其記六藝之義。所以坊人之失者也。防之俗作坊。"}]},"售":{"expl":"賣去手也。从口，雔省聲。《詩》曰：“賈用不售”。","rad":"口","fq":"承臭切","vol":"02","py":"shòu","duan":[]},"隄":{"expl":"唐也。从𨸏是聲。","rad":"𨸏","fq":"都兮切","vol":"14","py":"dī","duan":[{"e":"唐也。","n":"唐塘正俗字。唐者、大言也。叚借爲陂唐。乃又益之土旁作塘矣。隄與唐得互爲訓者、猶陂與池得互爲訓也。其實窊者爲池、爲唐。障其外者爲陂、爲隄。"}]},"阯":{"expl":"基也。从𨸏止聲。","rad":"𨸏","fq":"諸市切","vol":"14","py":"zhǐ","duan":[{"e":"基也。","n":"止下曰。下基也。阯與止音義皆同。止者、艸木之基也。阯者、城阜之基也。"}]},"陘":{"expl":"山絕坎也。从𨸏坙聲。","rad":"𨸏","fq":"戶經切","vol":"14","py":"xínɡ","duan":[{"e":"山絕坎也。","n":"釋山曰。山絕、陘。按今爾雅奪坎字。郭注云。連山中𣃔絕。非是。陘者、領也。孟子作徑。云山徑之蹊。趙注。山徑、山領也。楊子法言作山𡷨之蹊。皆卽陘字。凡巠聲之字皆訓直而長者。河北八陘。一曰軹關陘。二曰太行陘。三曰白陘。四曰滏口陘。五曰井陘。六曰飛狐陘。七曰蒲陰陘。八曰軍都陘。戴先生水地記曰。此皆㒳山中隔以成隘道也。軹關之山與太行中隔沁水。其山脈來自大岳。白陘之山與大行中隔丹水。其山脈自發鳩別而東。井陘滏口之山與白陘中隔漳水。其山脈自淸漳之源沾領別而東。飛狐蒲陰之山與井陘中隔滹沱。其山脈來自北岳。軍都之山與蒲陰中隔桑乾水。其山脈自大同府之外陰山別而東。大行之名尤顯著。故偁大行八陘。元和郡縣圖志引述征記"}]},"附":{"expl":"附𡝤，小土山也。从𨸏付聲。《春秋傳》曰：“附𡝤無松栢。”","rad":"𨸏","fq":"符又切","vol":"14","py":"bù","duan":[{"e":"附婁、","n":"逗。㬪韵字。"}]},"阺":{"expl":"秦謂陵阪曰阺。从𨸏氐聲。","rad":"𨸏","fq":"丁禮切","vol":"14","py":"dǐ","duan":[{"e":"秦謂陵阪曰阺。","n":"大𨸏曰陵。坡曰阪。秦人方言皆曰阺也。漢書楊雄解嘲曰。響若坁隤。應劭云。天水有大坂。名曰隴坁。其山堆旁箸𡹔落作聲。聞數百里。故曰坁隤。按仲遠誤也。依說文則巴蜀名山岸脅之旁箸欲落𡐦者曰氏。氏𡹔聞數百里。秦謂陵阪曰阺。其字則氏與阺不同。其語言則秦與巴蜀不同。且氏主謂石。故𡹔聲聞遠。阺主謂土。陵阪皆土阜也。氏或譌作坁。韋昭音若是理之是。不誤。阺字或作坻。音丁兮丁禮二反。高唐賦。臨大阺之稸水。是其正字也。自仲遠合而一之。古音十六十五部之別亦淆矣。凡氏聲在十六部。凡氐聲在十五部。"}]},"阢":{"expl":"石山戴土也。从𨸏从兀，兀亦聲。","rad":"𨸏","fq":"五忽切","vol":"14","py":"wù","duan":[{"e":"石山戴土也。","n":"戴小徐作載。釋山曰。石戴土謂之崔嵬。然則崔嵬一名阢也。"}]},"隒":{"expl":"崖也。从𨸏兼聲。讀若儼。","rad":"𨸏","fq":"魚檢切","vol":"14","py":"yǎn","duan":[{"e":"崖也。","n":"崖者、高邊也。按今俗語謂邊曰隒。當作此字。王風傳曰。涘者、厓也。漘者、水隒也。葢平者曰厓。高起者曰隒。釋山云。重甗、隒。"}]},"阸":{"expl":"塞也。从𨸏戹聲。","rad":"𨸏","fq":"於革切","vol":"14","py":"è","duan":[{"e":"塞也。","n":"塞先代切。與窒？字別。塞者、隔也。阸之言扼也。"}]},"隔":{"expl":"障也。从𨸏鬲聲。","rad":"𨸏","fq":"古覈切","vol":"14","py":"ɡé","duan":[{"e":"塞也。","n":"塞先代切。各本作障。今依西京賦注所引作塞也。與土部塞隔也爲轉注。廣韵亦曰。塞也。西京賦曰。隴坻之隘。隔閡華戎。"}]},"障":{"expl":"隔也。从𨸏章聲。","rad":"𨸏","fq":"之亮切","vol":"14","py":"zhànɡ","duan":[{"e":"隔也。从𨸏。章聲。","n":"之亮切。十部。"}]},"噞":{"expl":"噞喁，魚口上見也。从口僉聲。","rad":"口","fq":"魚檢切","vol":"02","py":"yǎn","duan":[]},"隱":{"expl":"蔽也。从𨸏㥯聲。","rad":"𨸏","fq":"於謹切","vol":"14","py":"yǐn","duan":[{"e":"蔽也。","n":"艸部曰。蔽茀、小皃也。小則不可見。故隱之訓曰蔽。若孟子隱几字則當爲？。𠬪部曰。？、有所據也。"}]},"隩":{"expl":"水隈，崖也。从𨸏奧聲。","rad":"𨸏","fq":"烏到切","vol":"14","py":"ào","duan":[{"e":"水隈厓也。","n":"厓、山邊也。引申之爲水邊。隈厓、謂曲邊也。釋丘曰。厓內爲隩。外爲鞫。毛詩。瞻彼淇奧。傳曰。奧、隈也。奥者、隩之叚借字也。又芮鞫之卽。毛曰。芮、水厓也。鞫、究也。鄭曰。芮之言內也。水之內曰隩。水之外曰鞫。漢書作𨸰。字林作㘲。"}]},"隈":{"expl":"水曲，隩也。从𨸏畏聲。","rad":"𨸏","fq":"烏恢切","vol":"14","py":"wēi","duan":[{"e":"水曲也。","n":"各本作水曲隩也。今依西都、海賦二注訂。"}]},"𠳋":{"expl":"𦥳商，小塊也。从𨸏从臾。","rad":"𨸏","fq":"去衍切","vol":"14","py":"qiǎn","duan":[{"e":"𨺫商、","n":"逗。此葢古語。"}]},"𨼬":{"expl":"水衡官、谷也。从𨸏解聲。一曰小谿。","rad":"𨸏","fq":"胡買切","vol":"14","py":"xiè","duan":[{"e":"水衡官谷也。","n":"未詳。水衡官、見漢書百官公卿表。又天文志解谷。晉灼曰。谷名。葢非此。"}]},"隴":{"expl":"天水大阪也。从𨸏龍聲。","rad":"𨸏","fq":"力鍾切","vol":"14","py":"lǒnɡ","duan":[{"e":"天水大阪也。","n":"地理志。天水郡有隴縣。郡國志。漢陽郡、永平十七年天水郡更名也。隴縣有大阪名隴坻。按坻卽上文阺字也。"}]},"䧇":{"expl":"酒泉天依阪也。从𨸏衣聲。","rad":"𨸏","fq":"於希切","vol":"14","py":"yī","duan":[{"e":"酒泉天䧇阪也。","n":"地理志。酒泉郡天䧇縣。師古曰。此地有天䧇阪。故以名。"}]},"陝":{"expl":"弘農陝也。古虢國，王季之子所封也。从𨸏夾聲。","rad":"𨸏","fq":"失冉切","vol":"14","py":"shǎn","duan":[{"e":"弘農陝也。","n":"地理志。弘農郡陝縣。後志同。今河南直𣜩陝州有廢陝縣。"}]},"𨼊":{"expl":"弘農陝東陬也。从𨸏無聲。","rad":"𨸏","fq":"武扶切","vol":"14","py":"wú","duan":[{"e":"弘農陝東陬也。","n":"陬者、隅也。"}]},"𨹵":{"expl":"河東安邑陬也。从𨸏卷聲。","rad":"𨸏","fq":"居遠切","vol":"14","py":"juǎn","duan":[{"e":"河東安邑陬也。从𨸏。卷聲。","n":"居遠切。十四部。"}]},"唳":{"expl":"鶴鳴也。从口戾聲。","rad":"口","fq":"朗計切","vol":"02","py":"lì","duan":[]},"陭":{"expl":"上黨陭氏阪也。从𨸏奇聲。","rad":"𨸏","fq":"於离切","vol":"14","py":"yì","duan":[{"e":"上黨陭氏阪也。","n":"地理志。上黨郡有陭氏縣。葢因有陭氏阪以名也。今本郡國志作猗氏。因河東猗氏而誤。"}]},"隃":{"expl":"北陵西隃，鴈門是也。从𨸏俞聲。","rad":"𨸏","fq":"傷遇切","vol":"14","py":"shù","duan":[{"e":"北陵西隃鴈門是也。","n":"此八字用爾雅釋地。郭注曰。鴈門山是也。史記趙世家作先俞。古西先同音也。地理志。鴈門郡。秦置。句注山在陰館。按句注山一名西陘山。一名鴈門山。今在山西代州西北二十五里。有鴈門關。"}]},"阮":{"expl":"代郡五阮關也。从𨸏元聲。","rad":"𨸏","fq":"虞遠切","vol":"14","py":"yuán","duan":[{"e":"代郡五阮關也。","n":"地理志。代郡有五原關。阮者正字。原者叚借字也。成帝紀作五阮關。如淳曰。近捲反。"}]},"䧊":{"expl":"大𨸏也。一曰右扶風𨞅有䧊𨸏。从𨸏告聲。","rad":"𨸏","fq":"苦𦰚切","vol":"14","py":"kū","duan":[{"e":"大𨸏也。","n":"前云大𨸏曰陵矣。此云大𨸏曰䧊。未聞。"}]},"陚":{"expl":"丘名。从𨸏武聲。","rad":"𨸏","fq":"方遇切","vol":"14","py":"fù","duan":[{"e":"丘名。从𨸏。武聲。","n":"方遇切。五部。"}]},"𨺟":{"expl":"丘名。从𨸏貞聲。","rad":"𨸏","fq":"陟盈切","vol":"14","py":"zhēnɡ","duan":[{"e":"丘名。从𨸏。貞聲。","n":"陟盈切。十一部。"}]},"䦺":{"expl":"丘名。从𨸏丁聲。讀若丁。","rad":"𨸏","fq":"當經切","vol":"14","py":"dīnɡ","duan":[{"e":"丘名。从𨸏。丁聲。讀若丁。","n":"當經切。十一部。"}]},"䧦":{"expl":"鄭地，阪。从𨸏爲聲。《春秋傳》曰：“將會鄭伯于䧦。”","rad":"𨸏","fq":"許爲切","vol":"14","py":"huī","duan":[{"e":"鄭地阪。从𨸏。爲聲。","n":"許爲切。釋文于詭切。古音在十七部。"}]},"陼":{"expl":"如渚者陼丘。水中高者也。从𨸏者聲。","rad":"𨸏","fq":"當古切","vol":"14","py":"zhǔ","duan":[{"e":"如渚者陼丘。水中高者也。","n":"釋水曰。水中可居者曰州。小州曰渚。釋丘曰。如渚者陼丘。謂在水中高而平。如水中小州然也。許本之爲說。今爾雅作小洲曰陼。如陼者陼丘。溷淆通用。"}]},"陳":{"expl":"宛丘，舜後嬀滿之所封。从𨸏从木，申聲。","rad":"𨸏","fq":"直珍切","vol":"14","py":"chén","duan":[{"e":"宛丘也。","n":"韵會有也。"}]},"喫":{"expl":"食也。从口契聲。","rad":"口","fq":"苦擊切","vol":"02","py":"chī","duan":[]},"陶":{"expl":"再成丘也，在濟陰。从𨸏匋聲。《夏書》曰：“東至于陶丘。”陶丘有堯城，堯嘗所居，故堯號陶唐氏。","rad":"𨸏","fq":"徒刀切","vol":"14","py":"táo","duan":[{"e":"再成丘也。在濟陰。","n":"釋丘曰。一成爲敦丘。再成爲陶丘。禹貢曰。道沇水東流爲濟。入于河。泆爲熒。東出于陶丘北。地理志曰。濟陰郡定陶縣。禹貢陶丘在西南。按定陶故城在今山東曹州府定陶縣西南。古陶丘在焉。"}]},"𨹸":{"expl":"耕以臿浚出下壚土也。一曰耕休田也。从𨸏从土，召聲。","rad":"𨸏","fq":"之少切","vol":"14","py":"zhào","duan":[{"e":"耕㠯臿浚出下壚土也。","n":"耕謂耕者也。臿當依十二篇𠙹部作？。古田器。斗部引爾雅𣂁謂之？是也。郭樸曰。𣂁？古鍫鍤字。浚者、抒也。抒者挹也。壚者、黑剛土也。耕者用鍫抒取地下黑剛土謂之？。釋名曰。鍤、插地起土也、或曰銷。或曰鏵。其板曰葉。鏵卽木部之㭉。㭉者、㒳刃臿也。"}]},"阽":{"expl":"壁危也。从𨸏占聲。","rad":"𨸏","fq":"余廉切","vol":"14","py":"yán","duan":[{"e":"壁危也。","n":"引申爲凡物之危。漢文帝詔曰。或阽於死亡。如淳曰。阽、近邊欲墮之意。"}]},"除":{"expl":"殿陛也。从𨸏余聲。","rad":"𨸏","fq":"直魚切","vol":"14","py":"chú","duan":[{"e":"殿陛也。","n":"殿謂宮殿。殿陛謂之除。因之凡去舊更新皆曰除。取拾級更易之義也。天保。何福不除。傳曰。除、開也。"}]},"階":{"expl":"陛也。从𨸏皆聲。","rad":"𨸏","fq":"古諧切","vol":"14","py":"jiē","duan":[{"e":"陛也。","n":"因之凡以漸而𦫵皆曰階。木部曰。梯、木階也。"}]},"阼":{"expl":"主階也。从𨸏乍聲。","rad":"𨸏","fq":"昨誤切","vol":"14","py":"zuò","duan":[{"e":"主階也。","n":"階之在東者。古者天子踐阼臨祭祀。故國運曰阼。"}]},"陛":{"expl":"升高階也。从𨸏坒聲。","rad":"𨸏","fq":"旁禮切","vol":"14","py":"bì","duan":[{"e":"𦫵高陛也。","n":"𦫵登古今字。古叚𦫵爲登也。自卑而可以登高者謂之陛。賈？曰。陛九級上廉遠地。則堂高。陛無級廉近地。則堂卑。獨𣃔曰。羣臣與至尊言。不敢指斥。故呼在陛下者而吿之。"}]},"陔":{"expl":"階次也。从𨸏亥聲。","rad":"𨸏","fq":"古哀切","vol":"14","py":"ɡāi","duan":[{"e":"階次也。","n":"近階之處也。小雅有南陔序曰。南陔、孝子相戒以養也。束晢詩曰。循彼南陔。言采其蘭。是用階次之說矣。而禮經賓出奏陔夏注曰。以爲行節。序以戒釋陔。皆取引申叚借之義。"}]},"際":{"expl":"壁會也。从𨸏祭聲。","rad":"𨸏","fq":"子例切","vol":"14","py":"jì","duan":[{"e":"壁會也。","n":"㒳牆相合之縫也。引申之、凡㒳合皆曰際。際取壁之㒳合、猶閒取門之㒳合也。詩菀桺鄭箋。瘵、接也。此謂叚瘵爲際。"}]},"隙":{"expl":"壁際孔也。从𨸏从𡭴，𡭴亦聲。","rad":"𨸏","fq":"綺戟切","vol":"14","py":"xì","duan":[{"e":"壁際也。","n":"今本際下有孔字。依文選沈約詠月詩注正。左傳曰。牆之隙壞。誰之咎也。際自分而合言之。隙自合而分言之。引申之、凡坼裂皆曰隙。又引申之、凡閒空皆曰隙。叚借以郤爲之。"}]},"喚":{"expl":"𧦝也。从口奐聲。古通用奐。","rad":"口","fq":"呼貫切","vol":"02","py":"huàn","duan":[]},"陪":{"expl":"重土也。一曰滿也。从𨸏咅聲。","rad":"𨸏","fq":"薄回切","vol":"14","py":"péi","duan":[{"e":"重土也。","n":"左傳曰。分之土田陪敦。注曰。陪、增也。敦、厚也。諸侯之臣於天子曰陪臣。取重土之義之引申也。"}]},"䧘":{"expl":"道邊庳垣也。从𨸏彖聲。","rad":"𨸏","fq":"徒玩切","vol":"14","py":"zhuàn","duan":[{"e":"道邊庳垣也。","n":"未聞。"}]},"陾":{"expl":"築牆聲也。从𨸏耎聲。《詩》云：“捄之陾陾。”","rad":"𨸏","fq":"如乘切","vol":"14","py":"rénɡ","duan":[{"e":"築牆聲也。从𨸏。耎聲。","n":"如乘切。六部。"}]},"陴":{"expl":"城上女牆俾倪也。从𨸏卑聲。","rad":"𨸏","fq":"符支切","vol":"14","py":"pí","duan":[{"e":"城上女牆。俾倪也。","n":"土部曰。堞、城上女垣也。凡小者謂之女。女牆卽女垣也。俾倪曡韵字。或作睥睨。或作埤堄。皆俗字。城上爲小牆。作孔穴可以窺外。謂之俾倪。左傳宣十二年。守陴者皆哭。杜注。陴、城上俾倪。釋名云。城上垣曰俾倪。言於其孔中俾倪非常。亦曰陴。陴、裨也。言裨助城之高也。亦曰女牆。"}]},"隍":{"expl":"城池也。有水曰池，無水曰隍。从𨸏皇聲。《易》曰：“城復于隍。”","rad":"𨸏","fq":"乎光切","vol":"14","py":"huánɡ","duan":[{"e":"城池也。","n":"池之在城外者也。"}]},"阹":{"expl":"依山谷爲牛馬圈也。从𨸏去聲。","rad":"𨸏","fq":"去魚切","vol":"14","py":"qū","duan":[{"e":"依山谷爲午馬圈也。","n":"司馬相如上林賦、楊雄傳、左思吳都賦皆有此字。郭樸、李奇、劉淵林注皆略同許。"}]},"陲":{"expl":"危也。从𨸏垂聲。","rad":"𨸏","fq":"是爲切","vol":"14","py":"chuí","duan":[{"e":"危也。","n":"許義垂訓遠邊。陲訓危。以垂从土、陲从𨸏之故。今義訓垂爲懸則訓陲爲邊。邊陲行而邊垂廢矣。"}]},"隖":{"expl":"小障也。一曰庳城也。从𨸏烏聲。","rad":"𨸏","fq":"安古切","vol":"14","py":"wǔ","duan":[{"e":"小障也。","n":"障、隔也。埤蒼云。小障曰隖。通俗文。營居爲隖。"}]},"院":{"expl":"堅也。从𨸏完聲。","rad":"𨸏","fq":"王眷切","vol":"14","py":"yuàn","duan":[]},"陯":{"expl":"山𨸏陷也。从𨸏侖聲。","rad":"𨸏","fq":"盧昆切","vol":"14","py":"lún","duan":[{"e":"山𨸏陷也。","n":"今則淪行而陯廢矣。"}]},"咍":{"expl":"蚩笑也。从口从台。","rad":"口","fq":"呼來切","vol":"02","py":"hāi","duan":[]},"陙":{"expl":"水𨸏也。从𨸏辰聲。","rad":"𨸏","fq":"食倫切","vol":"14","py":"chún","duan":[{"e":"水𨸏也。","n":"水集韵作小。"}]},"䧖":{"expl":"水𨸏也。从𨸏戔聲。","rad":"𨸏","fq":"慈衍切","vol":"14","py":"jiàn","duan":[{"e":"水𨸏也。从𨸏。戔聲。","n":"慈衍切。十四部。"}]},"阠":{"expl":"陵名。从𨸏卂聲。","rad":"𨸏","fq":"所臻切","vol":"14","py":"shēn","duan":[]},"阡":{"expl":"路東西爲陌，南北爲阡。从𨸏千聲。","rad":"𨸏","fq":"倉先切","vol":"14","py":"qiān","duan":[]},"𨺅":{"expl":"兩𨸏之閒也。从二𨸏。凡𨺅之屬皆从𨺅。","rad":"𨺅","fq":"房九切","vol":"14","py":"fù","duan":[{"e":"㒳𨸏之閒也。从二𨸏。","n":"似醉切。按此字不得其音。大徐依𤎩讀也。廣韵、玉篇扶救切。又依𨸏音讀也。"}]},"𨼱":{"expl":"𨸏䆕也。从𨺅，決省聲。","rad":"𨺅","fq":"於決切","vol":"14","py":"jué","duan":[{"e":"𨸏䆕也。","n":"䆕者、穿也。謂㒳𨸏閒空闕處也。"}]},"𨽝":{"expl":"𨹟也。从𨺅，纷聲。纷，籒文嗌字。","rad":"𨺅","fq":"烏懈切","vol":"14","py":"ài","duan":[{"e":"陋也。","n":"𨸏部曰。陋者、阸陜也。阸者、塞也。陜者、隘也。然則四字相爲轉注。"}]},"𨽵":{"expl":"塞上𠅘守㷭火者。从𨺅从火，遂聲。","rad":"𨺅","fq":"徐醉切","vol":"14","py":"suì","duan":[{"e":"塞上亭。守㷭火者也。","n":"注見火部㷭下。彼云㷭𤎩、𠊱表也。緫釋此二篆。此云塞上亭守㷭火者、謂邊塞之上守望㷭火之亭。故其字从𨺅。在阸隘之閒也。"}]},"厽":{"expl":"絫坺土爲牆壁。象形。凡厽之屬皆从厽。","rad":"厽","fq":"力軌切","vol":"14","py":"lěi","duan":[{"e":"絫坺土爲牆壁。","n":"絫者、今之累字。土部曰。一臿土謂之坺。臿者、今之鍫。以鍫取田閒土塊。令方整不散。今里俗云坺頭是也。亦謂之版光。累之爲牆壁。野外軍壁多如是。民家亦如是矣。軍壁則謂之壘。"}]},"絫":{"expl":"增也。从厽从糸。絫，十黍之重也。","rad":"厽","fq":"力軌切","vol":"14","py":"lěi","duan":[{"e":"增也。","n":"增者、益也。凡增益謂之積絫。絫之隷變作累。累行而絫廢。古書時見絫字、乃不識爲今之累字。良僞切、亦如是。"}]},"嘲":{"expl":"謔也。从口朝聲。《漢書》通用啁。","rad":"口","fq":"陟交切","vol":"02","py":"cháo","duan":[]},"垒":{"expl":"絫墼也。从厽从土。","rad":"厽","fq":"力軌切","vol":"14","py":"lěi","duan":[{"e":"絫墼也。","n":"墼者、令適未燒者也。巳燒者爲令適。今俗謂之塼。古作專。未燒者謂之墼。今俗謂之土墼。坺土則又未成墼者。積坺土爲牆曰厽。積墼爲牆曰垒。此音同義異之字也。土部曰。軍壁曰壘。此又音義皆異之字也。玉篇之注甚誤。故辨之。禮喪服。翦屛柱楣。注曰。於中門之外。垒墼爲之。今本垒皆譌壘。急就篇墼壘、亦當作垒。葢俗字厽畾之不分者多矣。"}]},"四":{"expl":"陰𢿙也。象四分之形。凡四之屬皆从四。","rad":"四","fq":"息利切","vol":"14","py":"sì","duan":[{"e":"侌數也。","n":"自一篇列一部、三部。十三篇列二部。二篇列八部。三篇列十部。數未備也。故於此類列之。"}]},"宁":{"expl":"辨積物也。象形。凡宁之屬皆从宁。","rad":"宁","fq":"直呂切","vol":"14","py":"zhù","duan":[{"e":"辨積物也。","n":"辨今俗字作辦。音蒲莧切。古無二字二音也。周禮。以辨民器。辨、具也。分別而具之。故其字从刀。積者、聚也。宁與貯葢古今字。周禮注作𡪄。史記作積著。釋宫。門屛之閒曰宁。郭云。人君視朝所宁立處。毛詩傳云。宁立、久立也。然則凡云宁立者、正積物之義之引申。俗字作佇、作竚。皆非是。以其可宁立也、故謂之宁。齊風作著。"}]},"𤲑":{"expl":"㡒也。所以載盛米。从宁从甾。甾，缶也。","rad":"宁","fq":"陟呂切","vol":"14","py":"zhǔ","duan":[{"e":"㡒也。所㠯盛米也。","n":"今本盛上有載。依廣韵刪。巾部曰。㡒、載米？也。二篆爲轉注。今俗以艸爲之、俗語如遁。卽㡒字也。以竹爲之、俗語如巨。卽？字也。皆所以盛米。"}]},"叕":{"expl":"綴聯也。象形。凡叕之屬皆从叕。","rad":"叕","fq":"陟劣切","vol":"14","py":"zhuó","duan":[{"e":"綴聯也。","n":"以綴釋叕、猶以絫釋厽也。聯者、連也。"}]},"綴":{"expl":"合箸也。从叕从糸。","rad":"叕","fq":"陟衞切","vol":"14","py":"zhuì","duan":[{"e":"合箸也。","n":"玄應書作合令箸也。箸直略切。古多叚綴爲贅。"}]},"亞":{"expl":"醜也。象人局背之形。賈侍中說：以爲次弟也。凡亞之屬皆从亞。","rad":"亞","fq":"衣駕切","vol":"14","py":"yà","duan":[{"e":"醜也。","n":"此亞之本義。亞與惡音義皆同。故詛楚文亞駞。禮記作惡池。史記盧綰孫他之封惡谷。漢書作亞𠔌。宋時玉印曰周惡夫印。劉原甫以爲卽條矦亞父。"}]},"𣉩":{"expl":"闕。","rad":"亞","fq":"衣駕切","vol":"14","py":"yà","duan":[{"e":"闕。","n":"謂形音義之說皆闕也。大徐衣駕切。按？字讀如？、則其音傳矣。"}]},"五":{"expl":"五行也。从二，陰陽在天地閒交午也。凡五之屬皆从五。","rad":"五","fq":"疑古切","vol":"14","py":"wǔ","duan":[{"e":"五行也。","n":"古之聖人知有水火木金土五者。而後造此字也。"}]},"六":{"expl":"《易》之數，陰變於六，正於八。从入从八。凡六之屬皆从六。","rad":"六","fq":"力竹切","vol":"14","py":"liù","duan":[{"e":"易之數。侌變於六。正於八。","n":"此謂六爲陰之變。八爲陰之正也。與下文言七九一例。八篆巳見二篇。故類言之。六爲陰之變。九爲陽之變。聖人以九六繫爻。而不以七八。金氏榜曰。乾鑿度謂七八爲彖。九六爲變。故彖占七八。爻占九六。一爻變者以變爻占。是爻占九六也。六爻皆不變及變兩爻以上者、占之彖辭。是彖占七八也。公子重耳筮得貞屯悔豫皆八。董因筮得泰之八。穆姜筮得艮之八。凡陰不變者爲八也。"}]},"呀":{"expl":"張口皃。从口牙聲。","rad":"口","fq":"許加切","vol":"02","py":"xiā","duan":[]},"七":{"expl":"陽之正也。从一，微陰从中衺出也。凡七之屬皆从七。","rad":"七","fq":"親吉切","vol":"14","py":"qī","duan":[{"e":"昜之正也。","n":"易用九不用七。亦用變不用正也。然則凡筮陽不變者當爲七。但左傳、國語未之見。"}]},"九":{"expl":"陽之變也。象其屈曲究盡之形。凡九之屬皆从九。","rad":"九","fq":"舉有切","vol":"14","py":"jiǔ","duan":[{"e":"昜之變也。","n":"列子、春秋䋣露、白虎通、廣雅皆云。九、究也。"}]},"馗":{"expl":"九達道也。似龜背，故謂之馗。馗，高也。从九从首。","rad":"九","fq":"渠追切","vol":"14","py":"kuí","duan":[{"e":"九𨔶道也。","n":"釋宫曰。九𨔶謂之馗。韓詩。施于中馗。"}]},"禸":{"expl":"獸足蹂地也。象形，九聲。《尔疋》曰：“狐貍貛貉醜，其足𨆌，其迹厹。”凡厹之屬皆从厹。","rad":"禸","fq":"人九切","vol":"14","py":"róu","duan":[{"e":"獸足蹂地也。","n":"足著地謂之厹。以蹂釋厹、以小篆釋古文也。先古文後小篆者、上部先二之例也。"}]},"禽":{"expl":"走獸緫名。从厹，象形，今聲。禽、离、兕頭相似。","rad":"禸","fq":"巨今切","vol":"14","py":"qín","duan":[{"e":"走獸總名。","n":"釋鳥曰。二足而羽謂之禽。四足而毛謂之獸。許不同者、其字从厹。厹爲獸迹。鳥迹不云厹也。然則倉頡造字之本意謂四足而走者明矣。以名毛屬者名羽屬。此乃偁謂之轉移叚借。及其久也、遂爲羽屬之定名矣。爾雅自其轉移者言之。許指造字之本言之。凡經典禽字、有謂毛屬者。有謂羽屬者。有兼舉者。故白虎通曰。禽者何。鳥獸之總名。"}]},"离":{"expl":"山神，獸也。从禽頭，从厹从屮。歐陽喬說：离，猛獸也。","rad":"禸","fq":"呂支切","vol":"14","py":"chī","duan":[{"e":"山神也。","n":"也字今補。"}]},"萬":{"expl":"蟲也。从厹，象形。","rad":"禸","fq":"無販切","vol":"14","py":"wàn","duan":[{"e":"蟲也。","n":"謂蟲名也。叚借爲十千數名。而十千無正字。遂久叚不歸。學者昧其本義矣。唐人十千作万。故廣韵万與萬別。"}]},"禹":{"expl":"蟲也。从厹，象形。","rad":"禸","fq":"王矩切","vol":"14","py":"yǔ","duan":[{"e":"蟲也。","n":"夏王以爲名。學者昧其本義。"}]},"𥝋":{"expl":"周成王時，州靡國獻𥝋。人身，反踵，自笑，笑即上脣掩其目。食人。北方謂之土螻。《尔疋》云：“𥝋𥝋，如人，被髮。”一名䲷陽。从厹，象形。","rad":"禸","fq":"符未切","vol":"14","py":"fèi","duan":[{"e":"周成王時。州靡國獻𥝋𥝋。人身反歱。","n":"足跟也。作踵者、誤。"}]},"禼":{"expl":"蟲也。从厹，象形。讀與偰同。","rad":"禸","fq":"私列切","vol":"14","py":"xiè","duan":[{"e":"蟲也。","n":"殷玄王以爲名。見漢書。俗改用偰契字。"}]},"凵":{"expl":"張口也。象形。凡凵之屬皆从凵。","rad":"凵","fq":"口犯切","vol":"02","py":"kǎn","duan":[{"e":"張口也。象形。","n":"也廣韵作皃。口犯切。八部。"}]},"嘼":{"expl":"㹌也。象耳、頭、足厹地之形。古文嘼，下从厹。凡嘼之屬皆从嘼。","rad":"嘼","fq":"許救切","vol":"14","py":"chù","duan":[{"e":"獸牲也。","n":"爾雅釋文引字林嘼㹌也。說文嘼牲也。今本說文作㹌也、乃後人以字林改說文耳。嘼牲二字連文。禮記、左傳皆云名子者不以畜牲是也。牛部㹌字下亦曰。嘼牲也。圈下曰。養嘼之閑。齅下曰。讀若嘼牲之嘼。今俗語多云畜牲。嘼今多用畜者、俗書叚借而然。爾雅釋獸釋嘼必異其名者、陸德明曰。嘼是嘼養之名。獸是毛蟲總號。故釋嘼惟論馬牛羊雞犬。釋獸通說百獸之名。按尙書武成歸嘼、今作歸獸。二字不分久矣。凡畜養古作嘼養。"}]},"獸":{"expl":"守備者。从嘼从犬。","rad":"嘼","fq":"舒救切","vol":"14","py":"shòu","duan":[{"e":"守備者也。","n":"以曡韵爲訓。能守能備、如虎豹在山是也。"}]},"甲":{"expl":"東方之孟，陽气萌動，从木戴孚甲之象。一曰人頭宐爲甲，甲象人頭。凡甲之屬皆从甲。","rad":"甲","fq":"古狎切","vol":"14","py":"jiǎ","duan":[{"e":"東方之孟。昜气𦹩動。","n":"史記曆書曰。甲者、言萬物剖符甲而出也。漢書律曆志曰。出甲於甲。月令注曰。日之行、春東從靑道發生。月爲之佐。時萬物皆解孚甲。月令曰。孟春之月。天氣下降。地氣下騰。天地和同。艸木萌動。今本小篆作？。古文作？。今正。說詳戈部戎字下。"}]},"乙":{"expl":"象春艸木冤曲而出，陰气尚彊，其出乙乙也。與丨同意。乙承甲，象人頸。凡乙之屬皆从乙。","rad":"乙","fq":"於筆切","vol":"14","py":"yǐ","duan":[{"e":"象春艸木冤曲而出。侌气尙彊。其出乙乙也。","n":"冤之言？。曲之言詘也。乙乙、難出之皃。史記曰。乙者、言萬物生？？也。漢書曰。奮？於乙。文賦曰。思？？其若抽。？？皆乙乙之叚借。？从乙聲。故同音相叚。月令鄭注云。乙之言？也。時萬物皆抽？而出。物之出土艱屯。如車之輾地澁滯。"}]},"乾":{"expl":"上出也。从乙，乙，物之達也；倝聲。","rad":"乙","fq":"渠焉切","vol":"14","py":"qián","duan":[{"e":"上出也。","n":"此乾字之本義也。自有文字以後。乃用爲卦名。而孔子釋之曰。健也。健之義生於上出。上出爲乾。下注則爲溼。故乾與溼相對。俗別其音。古無是也。"}]},"亂":{"expl":"治也。从乙，乙，治之也；从𤔔。","rad":"乙","fq":"郎段切","vol":"14","py":"luàn","duan":[{"e":"不治也。从乙𤔔。乙、治之也。","n":"各本作治也。从乙。乙治之也。从𤔔。文理不可通。今更正。亂本訓不治。不治則欲其治。故其字从乙。乙以治之。謂詘者𨔶之也。轉注之法。乃訓亂爲治。如武王曰予有亂十人是也。𠬪部𤔔、不治也。幺子相亂。𠬪治之也。文法正同。亦爲後人改竄不可讀。郎段切。十四部。"}]},"尢":{"expl":"異也。从乙又聲。","rad":"乙","fq":"羽求切","vol":"14","py":"yóu","duan":[{"e":"異也。从乙。又聲。","n":"羽求切。古音在一部。讀如怡。"}]},"丙":{"expl":"位南方，萬物成，炳然。陰气初起，陽气將虧。从一入冂。一者，陽也。丙承乙，象人肩。凡丙之屬皆从丙。","rad":"丙","fq":"兵永切","vol":"14","py":"bǐnɡ","duan":[{"e":"位南方。","n":"句。"}]},"丁":{"expl":"夏時萬物皆丁實。象形。丁承丙，象人心。凡丁之屬皆从丁。","rad":"丁","fq":"當經切","vol":"14","py":"dīnɡ","duan":[{"e":"夏時萬物皆丁實。","n":"丁實小徐本作丁壯成實。律書曰。丁者、言萬物之丁壯也。律曆志曰。大盛於丁。鄭注月令曰。時萬物皆強大。"}]},"戊":{"expl":"中宮也。象六甲五龍相拘絞也。戊承丁，象人脅。凡戊之屬皆从戊。","rad":"戊","fq":"莫𠊱切","vol":"14","py":"wù","duan":[{"e":"中宫也。","n":"鄭注月令曰。戊之言茂也。萬物皆枝葉茂盛。律曆志曰。豐楙於戊。"}]},"珣":{"expl":"醫無閭珣玗琪，《周書》所謂夷玉也。从玉旬聲。一曰器，讀若宣。","rad":"玉","fq":"相倫切","vol":"01","py":"xún","duan":[{"e":"醫無閭之珣㺮璂。","n":"爾雅曰。東北之美者、有醫無閭之珣玗琪焉。璂琪同。醫無閭、山名。在今盛京錦州府廣寧縣西十里。屈原賦謂之於微閭。珣玗璂合三字爲玉名。玗璂二字又各有本義。故不連舉其篆也。葢醫無閭、珣玗璂、皆東夷語。"}]},"吅":{"expl":"驚嘑也。从二口。凡吅之屬皆从吅。讀若讙。","rad":"吅","fq":"況袁切","vol":"02","py":"xuān","duan":[{"e":"驚嘑也。","n":"玉篇云。吅與讙通。按言部讙譁二字互訓。與驚嘑義別。"}]},"成":{"expl":"就也。从戊丁聲。","rad":"戊","fq":"氏征切","vol":"14","py":"chénɡ","duan":[{"e":"就也。从戊。丁聲。","n":"氏征切。十一部。"}]},"己":{"expl":"中宮也。象萬物辟藏詘形也。己承戊，象人腹。凡己之屬皆从己。","rad":"己","fq":"居擬切","vol":"14","py":"jǐ","duan":[{"e":"中宫也。","n":"戊已皆中宫。故中央土。其日戊已。注曰。己之言起也。律曆志曰。理紀於已。釋名曰。已、皆有定形可紀識也。引申之義爲人已。言已以別於人者。己在中。人在外。可紀識也。論語。克已復禮爲仁。克已言自勝也。"}]},"巹":{"expl":"謹身有所承也。从己、丞。讀若《詩》云“赤舄己己”。","rad":"己","fq":"居隱切","vol":"14","py":"jǐn","duan":[{"e":"謹身有所承也。","n":"承者、奉也。受也。按禮記借爲合？字。？見豆部。"}]},"㠱":{"expl":"長踞也。从己其聲。讀若杞。","rad":"己","fq":"暨己切","vol":"14","py":"jì","duan":[{"e":"長居也。","n":"居各本作踞。俗字也。尸部曰。居者、蹲也。長居謂箕其股而坐。許云㠱居者、卽他書之箕踞也。玉篇云。㠱卽跽字。長跪也。非許意。許於足部跽下云。長跪也。與㠱別。"}]},"巴":{"expl":"蟲也。或曰食象蛇。象形。凡巴之屬皆从巴。","rad":"巴","fq":"伯加切","vol":"14","py":"bā","duan":[{"e":"蟲也。","n":"謂蟲名。"}]},"𢃳":{"expl":"𢱧擊也。从巴、帚，闕。","rad":"巴","fq":"博下切","vol":"14","py":"bǎ","duan":[{"e":"𢱧擊也。","n":"𢱧者、反手擊也。今之琵琶、古當作𢱧？。"}]},"庚":{"expl":"位西方，象秋時萬物庚庚有實也。庚承己，象人𪗇。凡庚之屬皆从庚。","rad":"庚","fq":"古行切","vol":"14","py":"ɡēnɡ","duan":[{"e":"位西方。","n":"律書曰。庚者、言陰氣更萬物。律曆志。斂更於庚。月令注曰。庚之言更也。萬物皆肅然更改。秀實新成。"}]},"辛":{"expl":"秋時萬物成而孰；金剛，味辛，辛痛即泣出。从一从䇂。䇂，辠也。辛承庚，象人股。凡辛之屬皆从辛。","rad":"辛","fq":"息鄰切","vol":"14","py":"xīn","duan":[{"e":"秋時萬物成而𦏧。","n":"律書曰。辛者、言萬物之新生。故曰辛。律曆志曰。悉新於辛。釋名曰。辛、新也。物初新者、皆收成也。"}]},"辠":{"expl":"犯法也。从辛从自，言辠人蹙鼻苦辛之憂。秦以辠似皇字，改爲罪。","rad":"辛","fq":"徂賄切","vol":"14","py":"zuì","duan":[{"e":"犯灋也。从辛自。","n":"辛自、卽酸鼻也。徂賄切。十五部。"}]},"辜":{"expl":"辠也。从辛古聲。","rad":"辛","fq":"古乎切","vol":"14","py":"ɡū","duan":[{"e":"辠也。","n":"周禮。殺王之親者辜之。鄭注。辜之言枯也。謂磔之。按辜本非常重罪。引申之、凡有罪皆曰辜。"}]},"𤕦":{"expl":"亂也。从爻、工、交、吅。一曰窒𤕦。讀若禳。","rad":"吅","fq":"女庚切","vol":"02","py":"nínɡ","duan":[{"e":"亂也。从爻工交吅。","n":"疑有譌脫。寸部？、繹理也。从口从工从又从寸。工口亂也。又寸分理之。彡聲。與𤕦同意。是則从吅从爻从工者亦亂也。从己分理之。？不云理、？不云亂者。互見其義也。乙部曰。亂、治也。𠬪部曰。𤔔、治也。幺子相亂𠬪治之。凡言亂而治在焉。易竆則變也。莊子在宥傖囊。崔譔作戕囊。云戕囊猶搶攘。晉灼注漢書曰。搶攘、亂皃也。搶攘㬪韵。本在陽唐韵。轉入庚韵。攘卽𤕦之假借。凡髮亂曰？鬤。艸亂曰？薴。皆搶攘同意。"}]},"辥":{"expl":"辠也。从辛𡴎聲。","rad":"辛","fq":"私列切","vol":"14","py":"xuē","duan":[{"e":"辠也。","n":"此字古書內罕見。"}]},"辤":{"expl":"不受也。从辛从受。受辛宜辤之。","rad":"辛","fq":"似兹切","vol":"14","py":"cí","duan":[{"e":"不受也。","n":"聘禮。辭、曰非禮也敢。注曰。辭、不受也。按經傳凡辤讓皆作辭說字。固屬叚借。而學者乃罕知有辤讓本字。或又用辤爲辭說而愈惑矣。禮經一書。多言辭曰。謂其文辭如是也。聘禮之辭曰非禮也敢。則於辭爲逗。謂辤則其辭如是也。故鄭特注之。以別於他處之言辭曰者。哀六年左傳。五辭而後許。釋文曰。辭本又作辤。"}]},"辭":{"expl":"訟也。从𤔔，𤔔猶理辜也。𤔔，理也。","rad":"辛","fq":"似兹切","vol":"14","py":"cí","duan":[{"e":"說也。","n":"今本說譌訟。廣韵七之所引不誤。今本此說譌爲訟。訩字下訟譌爲說。其誤正同。言部曰。說者、釋也。"}]},"辡":{"expl":"辠人相與訟也。从二辛。凡辡之屬皆从辡。","rad":"辡","fq":"方免切","vol":"14","py":"biǎn","duan":[{"e":"辠人相與訟也。从二辛。","n":"會意。方免切。十二部。"}]},"辯":{"expl":"治也。从言在辡之閒。","rad":"辡","fq":"符蹇切","vol":"14","py":"biàn","duan":[{"e":"治也。","n":"治者、理也。俗多與辨不別。辨者、判也。"}]},"壬":{"expl":"位北方也。陰極陽生，故《易》曰：“龍戰于野。”戰者，接也。象人褢妊之形。承亥壬以子，生之敘也。與巫同意。壬承辛，象人脛。脛，任體也。凡壬之屬皆从壬。","rad":"壬","fq":"如林切","vol":"14","py":"rén","duan":[{"e":"位北方也。侌極昜生。","n":"月令鄭注。壬之言任也。時萬物懷任於下。律書曰。壬之爲言任也。言陽气任養萬物於下也。律曆志曰。懷任於壬。釋名曰。壬、妊也。陰陽交。物懷妊。至子而萌也。"}]},"癸":{"expl":"冬時，水土平，可揆度也。象水從四方流入地中之形。癸承壬，象人足。凡癸之屬皆从癸。","rad":"癸","fq":"居誄切","vol":"14","py":"ɡuǐ","duan":[{"e":"冬時水土平。可揆度也。","n":"揆癸曡䪨。律書曰。癸之爲言揆也。言萬物可揆度。律曆志曰。陳揆於癸。"}]},"子":{"expl":"十一月，陽气動，萬物滋，人以爲偁。象形。凡子之屬皆从子。(李陽冰曰：“子在襁緥中，足併也。”)","rad":"子","fq":"卽里切","vol":"14","py":"zǐ","duan":[{"e":"十一月昜气動。萬物滋。","n":"律書。子者、滋也。言萬物滋於下也。律曆志曰。孶萌於子。"}]},"孕":{"expl":"褢子也。从子从几。","rad":"子","fq":"以證切","vol":"14","py":"yùn","duan":[{"e":"褢子也。从子。乃聲。","n":"乃聲二字各本作从几。誤。今正。艸部艿字、人部仍字皆乃聲。管子孕作𣎜。从繩省聲、可證也。以證切。六部。"}]},"㝃":{"expl":"生子免身也。从子从免。","rad":"子","fq":"芳萬切","vol":"14","py":"miǎn","duan":[{"e":"生子免身也。从子免。","n":"按許書無免字。據此條則必當有免字。偶然逸之。正如由字耳。免聲當在古音十四部。或音問。則在十三部。與兔聲之在五部者迥不同矣。但立乎今日以言六書。免由皆不能得其象形會意。不得謂古無免由字也。㝃則會意兼形聲。亡辯切。十四部。"}]},"嚴":{"expl":"教命急也。从吅𠪚聲。","rad":"吅","fq":"語杴切","vol":"02","py":"yán","duan":[{"e":"敎命急也。","n":"嚴急㬪韵。趙注孟子曰。事嚴、喪事急。"}]},"字":{"expl":"乳也。从子在宀下，子亦聲。","rad":"子","fq":"疾置切","vol":"14","py":"zì","duan":[{"e":"乳也。","n":"人及鳥生子曰乳。獸曰㹌。引申之爲撫字。亦引申之爲文字。敘云。字者、言孶乳而浸多也。"}]},"㝅":{"expl":"乳也。从子𣪊聲。一曰㝅瞀也。","rad":"子","fq":"古𠊱切","vol":"14","py":"ɡòu","duan":[{"e":"乳也。","n":"上文之乳、謂生子也。此乳者、謂旣生而乳哺之也。左傳曰。楚人謂乳㝅。其音乃苟切。今本左傳作？。漢書作穀。或作彀。或作？。皆非也。音亦如？。"}]},"孿":{"expl":"一乳兩子也。从子䜌聲。","rad":"子","fq":"生患切","vol":"14","py":"luán","duan":[{"e":"一乳㒳子也。","n":"此謂人也。孿之言連也。"}]},"孺":{"expl":"乳子也。一曰輸也，輸尚小也。从子需聲。","rad":"子","fq":"而遇切","vol":"14","py":"rú","duan":[{"e":"乳子也。","n":"以曡韵爲訓。凡幼者曰孺子。此其義也。爾雅曰。孺、屬也。亦以同音爲訓。屬者、聯也。"}]},"季":{"expl":"少偁也。从子，从稚省，稚亦聲。","rad":"子","fq":"居悸切","vol":"14","py":"jì","duan":[{"e":"少偁也。","n":"叔季皆謂少者。而季又少於叔。"}]},"孟":{"expl":"長也。从子皿聲。","rad":"子","fq":"莫更切","vol":"14","py":"mènɡ","duan":[{"e":"長也。从子。皿聲。","n":"莫更切。古音在十部。讀如芒。爾雅。孟、勉也。此借孟爲猛。"}]},"孼":{"expl":"庶子也。从子辥聲。","rad":"子","fq":"魚列切","vol":"14","py":"niè","duan":[{"e":"庶子也。","n":"玉藻。公子曰臣孼。鄭注。孼當作枿。聲之誤也。玉裁按此記文本作枿。注曰。枿當作孼。後人因注改經。又因經改注。師古匡謬正俗未之知也。凡木萌旁出皆曰櫱。人之支子曰孼。其義略同。故古或通用。固不必指爲聲誤。何注公羊曰。庶孼、衆賤子。猶樹之有櫱生。得其義矣。"}]},"孳":{"expl":"汲汲生也。从子兹聲。","rad":"子","fq":"子之切","vol":"14","py":"zī","duan":[{"e":"孶孶、彶彶生也。","n":"孶孶二字各本無。今依玄應書補。攴部孜下曰。孜孜、彶彶也。此云孶孶、彶彶生也。孜孶二字古多通用。堯典。鳥獸孶尾。某氏傳曰。乳化曰孶。然則蕃生之義當用孶。故从茲。無怠之義當用孜。故从攴。"}]},"孤":{"expl":"無父也。从子瓜聲。","rad":"子","fq":"古乎切","vol":"14","py":"ɡū","duan":[{"e":"無父也。","n":"孟子曰。幼而無父曰孤。引申之、凡單獨皆曰孤。弧則不相酬應。故背恩者曰孤負。孤則人輕賤之。故鄭注儀禮曰。不以己尊孤人也。"}]},"存":{"expl":"恤問也。从子才聲。","rad":"子","fq":"徂尊切","vol":"14","py":"cún","duan":[{"e":"恤問也。","n":"恤、𢝊也。收也。爾雅曰。在、存也。在、存、省、士、察也。今人於在存字皆不得其本義。"}]},"咢":{"expl":"譁訟也。从吅屰聲。","rad":"吅","fq":"五各切","vol":"02","py":"è","duan":[{"e":"譁訟也。","n":"引伸爲徒擊𡔷曰咢。又韋賢傳。咢咢黃髪。"}]},"𡥈":{"expl":"放也。从子爻聲。","rad":"子","fq":"古肴切","vol":"14","py":"jiào","duan":[{"e":"放也。","n":"放各本譌作效。今依宋刻及集韵正。放仿古通用。許曰。放、逐也。仿、相似也。𡥈訓放者、謂隨之依之也。今人則專用仿矣。敎字、學字皆以𡥈會意。敎者、與人以可放也。學者、放而像之也。放分兩切。"}]},"疑":{"expl":"惑也。从子、止、匕，矢聲。","rad":"子","fq":"語其切","vol":"14","py":"yí","duan":[{"e":"惑也。","n":"惑、亂也。"}]},"了":{"expl":"尦也。从子無臂。象形。凡了之屬皆从了。","rad":"了","fq":"盧鳥切","vol":"14","py":"liǎo","duan":[{"e":"尦也。","n":"尦、行脛相交也。牛行腳相交爲尦。凡物二股或一股結糾紾縳不直伸者、曰了戾。方言。軫、戾也。郭注。相了戻也。淮南原道訓注、楊倞荀卿注、王砅素問注、段成式酉陽雜組及諸書皆有了戾字。而或妄改之。方言曰。佻、縣也。郭注。了佻、縣物皃。丁小反。按他書引皆作了？。亦卽許之了尦也。叚借爲憭悟字。"}]},"孑":{"expl":"無右臂也。从了，乚象形。","rad":"了","fq":"居桀切","vol":"14","py":"jié","duan":[{"e":"無又臂也。","n":"引申之、凡特立爲孑。詩曰。孑孑干旄。又曰。靡有孑遺。方言曰。？而無刃、秦晉之閒謂之釨。釨卽孑字。左傳正作孑。"}]},"孒":{"expl":"無左臂也。从了，丿象形。","rad":"了","fq":"居月切","vol":"14","py":"jué","duan":[{"e":"無𠂇臂也。","n":"大荒西經。有人名曰吳回。奇左。是無右臂。郭注。卽奇肱也。又大荒之山有人焉。是顓頊之子。三面一臂。郭注。無左臂也。廣雅。孑孒、蜎也。郭樸云。井中小蛣蟩赤蟲也。"}]},"孨":{"expl":"謹也。从三子。凡孨之屬皆从孨。讀若翦。","rad":"孨","fq":"旨兖切","vol":"14","py":"zhuǎn","duan":[{"e":"謹也。","n":"大戴禮曰。博學而孱守之。正謂謹也。引申之義爲弱小。史記。吾王孱王也。韋昭曰。仁謹皃。與許合。孟康曰。冀州人謂愞弱爲孱。此引申之義。其字則多叚孱爲孨。"}]},"孱":{"expl":"迮也。一曰呻吟也。从孨在尸下。","rad":"孨","fq":"七連切","vol":"14","py":"chán","duan":[{"e":"迮也。","n":"按此迮當爲笮。今之窄字也。"}]},"孴":{"expl":"盛皃。从孨从曰。讀若薿薿。一曰若存。","rad":"孨","fq":"魚紀切","vol":"14","py":"nǐ","duan":[{"e":"盛皃。","n":"文𨕖靈光殿賦曰。芝、栭欑羅以戢孴。李注。戢孴、衆皃。"}]},"𠫓":{"expl":"不順忽出也。从到子。《易》曰：“突如其來如。”不孝子突出，不容於内也。凡𠫓之屬皆从𠫓。","rad":"𠫓","fq":"他骨切","vol":"14","py":"tū","duan":[{"e":"不順忽出也。","n":"謂凡物之反其常。凡事之屰其理。突出至前者。皆是也。不專謂人子。"}]},"育":{"expl":"養子使作善也。从𠫓肉聲。《虞書》曰：“教育子。”","rad":"𠫓","fq":"余六切","vol":"14","py":"yù","duan":[{"e":"養子使作善也。","n":"孟子曰。中也養不中。才也養不才。"}]},"單":{"expl":"大也。从吅、红，吅亦聲。闕。","rad":"吅","fq":"都寒切","vol":"02","py":"dān","duan":[{"e":"大也。","n":"當爲大言也。淺人刪言字。如誣加言也。淺人亦刪言字。爾雅、廣雅說大皆無單。引伸爲雙之反對。大雅。其軍三單。毛云。三單、相襲也。鄭云。丁夫適滿三軍之數。無羨卒也。"}]},"疏":{"expl":"通也。从𡿮从疋，疋亦聲。","rad":"𠫓","fq":"所葅切","vol":"14","py":"shū","duan":[{"e":"通也。","n":"疋部曰。？、通也。疏與？音義皆同。皆从疋者、疋所以通也。鄭注月令明堂位、薛解西京賦張注靈光殿賦皆訓疏爲刻鏤。古？疏？三字通用矣。疏之引申爲疏闊、分疏、疏記。"}]},"丑":{"expl":"紐也。十二月，萬物動，用事。象手之形。時加丑，亦舉手時也。凡丑之屬皆从丑。","rad":"丑","fq":"敕九切","vol":"14","py":"chǒu","duan":[{"e":"紐也。","n":"律曆志曰。紐牙於丑。釋名曰。丑、紐也。寒氣自屈紐也。淮南天文訓、廣雅釋言皆曰。丑、紐也。糸部曰。紐、系也。一曰結而可解。十二月陰氣之固結巳漸解。故曰紐也。"}]},"䏔":{"expl":"食肉也。从丑从肉。","rad":"丑","fq":"女久切","vol":"14","py":"niǔ","duan":[{"e":"食肉也。","n":"食肉必用手。故从丑肉。"}]},"羞":{"expl":"進獻也。从羊，羊，所進也；从丑，丑亦聲。","rad":"丑","fq":"息流切","vol":"14","py":"xiū","duan":[{"e":"進獻也。","n":"宗廟犬名羹獻。犬？者獻之。犬羊一也。故从羊。引申之、凡進皆曰羞。今文尙書。次二曰羞用五事。羞、進也。"}]},"寅":{"expl":"髕也。正月，陽气動，去黃泉，欲上出，陰尚彊，象宀不達，髕寅於下也。凡寅之屬皆从寅。","rad":"寅","fq":"弋眞切","vol":"14","py":"yín","duan":[{"e":"髕也。","n":"髕、字之誤也。當作濥。史記、淮南王書作螾。律書曰。寅言萬物始生螾然也。天文訓曰。斗指寅則萬物螾。高注。螾、動生皃。律曆志曰。引達於寅。釋名曰。寅、演也。演生物也。廣雅曰。寅、演也。晉書樂志曰。正月之辰謂之寅。寅、津也。謂物之津塗。按漢志、廣雅演字皆濥之誤。水部曰。濥、水？行地中濥濥也。演、長流也。俗人不知二字之別。濥多誤爲演。以濥釋寅者。正月陽氣欲上出。如水泉欲上行也。螾之爲物。詰詘於黃泉。而能上出。故其字从寅。律書、天文訓以螾釋寅。"}]},"卯":{"expl":"冒也。二月，萬物冒地而出。象開門之形。故二月爲天門。凡卯之屬皆从卯。","rad":"戼","fq":"莫飽切","vol":"14","py":"mǎo","duan":[{"e":"冒也。二月萬物冒地而出。","n":"律書曰。卯之爲言茂也。言萬物茂也。律曆志。冒茆於卯。天文訓曰。卯則茂茂然。釋名曰。卯、冒也。載冒土而出也。葢陽氣至是始出地。"}]},"辰":{"expl":"震也。三月，陽气動，靁電振，民農時也。物皆生，从乙、匕，象芒達；厂，聲也。辰，房星，天時也。从二，二，古文上字。凡辰之屬皆从辰。","rad":"辰","fq":"植鄰切","vol":"14","py":"chén","duan":[{"e":"震也。三月昜气動。靁電振。民農時也。物皆生。","n":"震振古通用。振、奮也。律書曰。辰者、言萬物之蜄也。律曆志曰。振美於辰。釋名曰。辰、伸也。物皆伸舒而出也。季春之月。生氣方盛。陽氣發泄。句者畢出。萌者盡達。二月靁發聲。始電至。三月而大振動。豳風曰。四之日舉止。故曰民農時。"}]},"辱":{"expl":"恥也。从寸在辰下。失耕時，於封畺上戮之也。辰者，農之時也。故房星爲辰，田候也。","rad":"辰","fq":"而蜀切","vol":"14","py":"rǔ","duan":[{"e":"恥也。","n":"心部曰。恥、辱也。此之謂轉注。儀禮注曰。以白造緇曰辱。"}]},"巳":{"expl":"巳也。四月，陽气巳出，陰气巳藏，萬物見，成文章，故巳爲蛇，象形。凡巳之屬皆从巳。","rad":"巳","fq":"詳里切","vol":"14","py":"sì","duan":[{"e":"巳也。","n":"律書曰。巳者、言萬物之巳盡也。律曆志曰。巳盛於巳。淮南天文訓曰。巳則生巳定也。釋名曰。巳、畢布巳也。辰巳之巳旣久用爲巳然巳止之巳。故卽以巳然之巳釋之。序卦傳。蒙者、蒙也。比者、比也。剝者、剝也。毛詩傳曰。虚、虚也。自古訓故有此例。卽用本字、不叚異字也。小雅斯干箋云。似讀爲巳午之巳。巳續妣祖者、謂巳成其宫廟也。此可見漢人巳午與巳然無二音。其義則異而同也。廣雅釋言。巳、㠯也。乃淺人所改。近大興朱氏重刻汲古閣說文改爲己也。殊誤。"}]},"㠯":{"expl":"用也。从反巳。賈侍中說：巳，意巳實也。象形。","rad":"巳","fq":"羊止切","vol":"14","py":"yǐ","duan":[{"e":"用也。","n":"用者、可施行也。凡㠯字皆此訓。"}]},"喌":{"expl":"呼雞重言之。从吅州聲。讀若祝。","rad":"吅","fq":"之六切","vol":"02","py":"zhōu","duan":[{"e":"呼雞重言之。","n":"當云喌喌、呼雞重言之也。淺人刪之耳。夏小正。正月雞桴粥。粥也者、相粥之時也。案相粥之時也、一本作相粥粥呼也。粥喌古今字。雞聲喌喌。故人效其聲𧦝之。風俗通曰。呼雞朱朱。俗說雞本朱公化而爲之。今呼雞曰朱朱也。謹按。說文解字喌从二口。二口爲讙。州其聲也。讀若祝。祝者、誘致禽畜和順之意。喌與朱音相似耳。今按應仲遠似當引小正爲原本。"}]},"午":{"expl":"啎也。五月，陰气午逆陽。冒地而出。此予矢同意。凡午之屬皆从午。","rad":"午","fq":"疑古切","vol":"14","py":"wǔ","duan":[{"e":"啎也。","n":"啎者、屰也。"}]},"啎":{"expl":"逆也。从午吾聲。","rad":"午","fq":"五故切","vol":"14","py":"wǔ","duan":[{"e":"屰也。","n":"屰各本作逆。今正。逆、迎也。屰、不順也。今則逆行而屰廢矣。相迎者必相屰。古亦通用逆爲屰。攷儀禮之梧受。爾雅、釋名之梧丘。太史公書之魁梧、枝梧。漢書之抵梧。皆是啎之譌字。啎、屰也。迎也。遻也。不識啎字、乃多妄改。管子七臣七主篇。事無常而法令申。不？。則失國勢。戰國策有樓？。吕覽明理篇。亂世之民長短頡？百疾。高注。？、迎也。字皆左吾右午。啎之或體也。姚宏云。字書無之。過矣。"}]},"未":{"expl":"味也。六月，滋味也。五行，木老於未。象木重枝葉也。凡未之屬皆从未。","rad":"未","fq":"無沸切","vol":"14","py":"wèi","duan":[{"e":"味也。","n":"口部曰。味者、滋味也。"}]},"申":{"expl":"神也。七月，陰气成，體自申束。从臼，自持也。吏臣（段注“臣”作“以” ）餔時聽事，申旦政也。凡申之屬皆从申。","rad":"申","fq":"失人切","vol":"14","py":"shēn","duan":[{"e":"神也。","n":"神不可通。當是本作？。如巳巳也之例。謂此申酉之篆卽今引申之義也。淺人不得其例。妄改爲神。攷諸古說無有合者。律書曰。申者、言陰用事。申則萬物。故曰申。律曆志曰。申堅於申。天文訓曰。申者、申之也。皆以申釋申。爲許所本。而今本淮南改申之作呻之。其可𣢑一而巳。或曰神當作身。下云陰氣成體。釋名、晉書樂志、玉篇、廣韵皆云。申、身也。許說身字从申省聲。皆其證。此說近是。然恐尙非許意。"}]},"𣍃":{"expl":"擊小鼓，引樂聲也。从申柬聲。","rad":"申","fq":"羊晉切","vol":"14","py":"yìn","duan":[{"e":"擊小𡔷引樂聲也。","n":"周禮小師。𡔷朄。鄭司農云。朄、小𡔷名。周頌。應田縣𡔷。箋云。田當作朄。朄、小𡔷。在大𡔷旁。應鼙之屬也。聲轉字誤。變而作田。"}]},"㬰":{"expl":"束縛捽抴爲臾。从申从乙。","rad":"申","fq":"羊朱切","vol":"14","py":"yú","duan":[]},"曳":{"expl":"臾曳也。从申丿聲。","rad":"申","fq":"余制切","vol":"14","py":"yè","duan":[{"e":"臾曳也。","n":"臾曳巳見上文。故但云臾曳也。此許之通例也。臾曳雙聲。猶牽引也。引之則長。故衣長曰曳地。"}]},"酉":{"expl":"就也。八月黍成，可爲酎酒。象古文酉之形。凡酉之屬皆从酉。","rad":"酉","fq":"與久切","vol":"14","py":"yǒu","duan":[{"e":"就也。","n":"就、高也。律書曰。酉者、萬物之老也。律曆志曰。畱孰於酉。天文訓曰。酉者、飽也。釋名曰。酉、秀也。秀者、物皆成也。"}]},"酒":{"expl":"就也，所以就人性之善惡。从水从酉，酉亦聲。一曰造也，吉凶所造也。 古者儀狄作酒醪，禹嘗之而美，遂䟽儀狄。杜康作秫酒。","rad":"酉","fq":"子酉切","vol":"14","py":"jiǔ","duan":[{"e":"就也。所㠯就人性之善惡。","n":"賓主百拜者、酒也。淫酗者、亦酒也。"}]},"𨢊":{"expl":"𥶶生衣也。从酉冡聲。","rad":"酉","fq":"莫紅切","vol":"14","py":"ménɡ","duan":[{"e":"？生衣也。","n":"方言曰。䴿、麴也。郭注云。音蒙。有衣麴。"}]},"哭":{"expl":"哀聲也。从吅，獄省聲。凡哭之屬皆从哭。","rad":"哭","fq":"苦屋切","vol":"02","py":"kū","duan":[{"e":"哀聲也。从吅。从獄省聲。","n":"苦屋切。三部。按許書言省聲、多有可疑者。取一偏旁。不載全字。指爲某字之省。若家之爲豭省、哭之从獄省。皆不可信。獄固从㹜。非从犬。而取㹜之半。然則何不取？獨倏𤞞之省乎。竊謂从犬之字、如狡獪狂默猝猥？狠獷狀獳狎狃犯猜猛犺㹤狟戾獨狩臭獘獻類猶卅字皆从犬、而移以言人。安見非器本謂犬噑、而移以言人也。凡造字之本意有不可得者、如秃之从禾。用字之本義亦有不可知者、如家之从豕、哭之从犬。愚以爲家入豕部从豕宀、哭入犬部从犬吅。皆會意、而移以言人。庶可正省聲之勉強皮傅乎。哭部當廁犬部之後。"}]},"䤁":{"expl":"孰𥶶也。从酉甚聲。","rad":"酉","fq":"余箴切","vol":"14","py":"yín","duan":[{"e":"孰？也。从酉。甚聲。","n":"余箴切。七部。"}]},"釀":{"expl":"醞也。作酒曰釀。从酉襄聲。","rad":"酉","fq":"女亮切","vol":"14","py":"niànɡ","duan":[{"e":"醞也。作酒曰釀。","n":"周禮。酒人掌爲五齊三酒。爲猶作也。"}]},"醞":{"expl":"釀也。从酉𥁕聲。","rad":"酉","fq":"於問切","vol":"14","py":"yùn","duan":[{"e":"釀也。","n":"引申爲醞藉。詩小宛箋、禮記禮噐注、漢書匡張孔馬傳贊皆曰醞藉。師古云。謂如醞釀及薦藉。道其寛博重厚也。今人多作蘊藉。失之遠矣。毛詩叚借溫字。"}]},"𨠒":{"expl":"酒疾孰也。从酉弁聲。","rad":"酉","fq":"芳萬切","vol":"14","py":"fàn","duan":[{"e":"酒疾孰也。","n":"廣韵云。一宿酒。謂一宿而孰也。"}]},"酴":{"expl":"酒母也。从酉余聲。讀若廬。","rad":"酉","fq":"同都切","vol":"14","py":"tú","duan":[{"e":"酒母也。","n":"米部？、酒母也。此酴亦訓酒母。則今之酵也。玉篇曰。麥酒。不去滓飲也。"}]},"釃":{"expl":"下酒也。一曰醇也。从酉麗聲。","rad":"酉","fq":"所綺切","vol":"14","py":"shī","duan":[{"e":"下酒也。","n":"小雅曰。釃酒有藇。又曰。有酒湑我。傳曰。以筐曰釃。以藪曰湑。湑莤之也。引申爲分疏之義。溝洫志云釃二渠以引河是也。司馬相如傳借灑。"}]},"䣺":{"expl":"𨢌酒也。从酉肙聲。","rad":"酉","fq":"古玄切","vol":"14","py":"juān","duan":[{"e":"𨢌酒也。","n":"玉篇曰。以孔下酒也。按謂㳙㳙而下也。"}]},"𨢌":{"expl":"䣺也。从酉鬲聲。","rad":"酉","fq":"郎擊切","vol":"14","py":"lì","duan":[{"e":"䣺也。","n":"廣韵曰。下酒也。按謂滴瀝而下也。在水部作瀝。在酒部作？。周禮量人作歷。古文叚借。"}]},"醴":{"expl":"酒一宿孰也。从酉豊聲。","rad":"酉","fq":"盧啟切","vol":"14","py":"lǐ","duan":[{"e":"酒一宿孰也。","n":"周禮酒正注曰。醴猶體也。成而汁滓相將。如今恬酒矣。按汁滓相將、葢如今江東人家之白酒。滓卽糟也。滓多、故酌醴者用柶。醴甘、故曰如今恬酒。恬卽甛也。許云一宿孰、則此酒易成與。禮經以醴敬賓曰醴賓。注多改爲禮賓。"}]},"醪":{"expl":"汁滓酒也。从酉翏聲。","rad":"酉","fq":"魯刀切","vol":"14","py":"láo","duan":[{"e":"汁滓酒也。","n":"米部曰。糟、酒滓也。許意此爲汁滓相將之酒。醴爲一宿孰之酒。與鄭異。"}]},"喪":{"expl":"亾也。从哭从亾。會意。亾亦聲。","rad":"哭","fq":"息郎切","vol":"02","py":"sànɡ","duan":[{"e":"亡也。","n":"亡部曰。亡、逃也。亡非死之謂。故中庸曰。事死如事生。事亡如事存。尙書大傳曰。王之於仁人也。死者封其墓。況於生者乎。王之於賢人也。亡者表其閭。況於在者乎。皆存亡與生死分別言之。凶禮謂之喪者、鄭禮經目錄云不忍言死而言喪。喪者、棄亡之辭。若全居於彼焉。己失之耳。是則死曰喪之義也。公子重耳自偁身喪、魯昭公自偁喪人。此喪字之本義也。凡喪失字本皆平聲。俗讀去聲、以別於死喪平聲。非古也。"}]},"醇":{"expl":"不澆酒也。从酉𦎫聲。","rad":"酉","fq":"常倫切","vol":"14","py":"chún","duan":[{"e":"不澆酒也。","n":"澆、？也。凡酒沃之以水則薄。不襍以水則曰醇。故厚薄曰醇澆。醇襍亦卽此字。一色成體謂之醇。純其叚借字。"}]},"醹":{"expl":"厚酒也。从酉需聲。《詩》曰：“酒醴惟醹。”","rad":"酉","fq":"而主切","vol":"14","py":"rǔ","duan":[{"e":"厚酒也。","n":"大雅。酒醴維醹。傳曰。醹厚也。此以曡韵爲訓。"}]},"酎":{"expl":"三重醇酒也。从酉，从時省。《明堂月令》曰：“孟秋，天子飲酎。”","rad":"酉","fq":"除柳切","vol":"14","py":"zhòu","duan":[{"e":"三重醇酒也。","n":"廣韵作三重釀酒。當从之。謂用酒爲水釀之。是再重之酒也。次又用再重之酒爲水釀之。是三重之酒也。杜預注左傳曰。酒之新孰重者曰耐。鄭注月令曰。酎之言醇也。謂重釀之酒也。醇者其義。釀者其事實。金壇于氏明季時以此法爲酒。"}]},"醠":{"expl":"濁酒也。从酉盎聲。","rad":"酉","fq":"烏浪切","vol":"14","py":"ànɡ","duan":[{"e":"濁酒也。","n":"醠周禮作盎。古文叚借也。鄭曰。盎猶翁也。成而翁翁葱。白色。如今酂白矣。釋文云。酂白、今之白醝酒也。宜作醝。按鄭曰五齊泛醴尤濁。縮酌者。盎以下羞淸。此非與許不合也。但云羞淸、則固濁也。盎淸於醴而濁於緹、沈。卽緹、沈亦非全淸也。淮南說林訓。淸醠之美。高注。醠、淸酒。亦與鄭意同。"}]},"醲":{"expl":"厚酒也。从酉農聲。","rad":"酉","fq":"女容切","vol":"14","py":"nónɡ","duan":[{"e":"厚酒也。","n":"鴻範。次三曰。農用八政。鄭曰。農讀爲醲。然則凡厚皆得爲醲也。"}]},"䤊":{"expl":"酒也。从酉茸聲。","rad":"酉","fq":"而容切","vol":"14","py":"rónɡ","duan":[{"e":"重釀酒也。从酉。耳聲。","n":"此篆各本作䤊。解云酒也。从酉、茸聲。而容切。廣韵、玉篇皆有䣵無䤊。解云重釀也。玉篇列字正與說文次弟相合。然則古本說文作䣵可知矣。廣雅亦云䣵汝吏切。今據以更正。仍吏切。一部。○又按艸部之茸亦耳聲也。則䣵可而容切。"}]},"酤":{"expl":"一宿酒也。一曰買酒也。从酉古聲。","rad":"酉","fq":"古乎切","vol":"14","py":"ɡū","duan":[{"e":"一宿酒也。","n":"商頌。旣載淸酤。傳曰。酤、酒也。小雅。無酒酤我。傳曰。酤、一宿酒也。"}]},"𨢮":{"expl":"酒也。从酉，𥏼省。","rad":"酉","fq":"陟离切","vol":"14","py":"zhī","duan":[{"e":"酒也。","n":"玉篇曰。酒厚。"}]},"𨣨":{"expl":"泛齊，行酒也。从酉監聲。","rad":"酉","fq":"盧瞰切","vol":"14","py":"làn","duan":[{"e":"泛齊。行酒也。","n":"泛齊見周禮酒正。鄭曰。泛者、成而滓泛泛然。如今宜成醪矣。行酒未聞。疑是貨物行敝之行。謂行用之酒也。行酒上疑當有一曰二字。"}]},"䤗":{"expl":"酒味淫也。从酉，竷省聲。讀若《春秋傳》曰“美而豔”。","rad":"酉","fq":"古禫切","vol":"14","py":"ɡǎn","duan":[{"e":"酒味淫也。","n":"淫者、浸淫隨理也。謂酒味淫液深長。"}]},"走":{"expl":"趨也。从夭、止。夭止者，屈也。凡走之屬皆从走。","rad":"走","fq":"子苟切","vol":"02","py":"zǒu","duan":[{"e":"趨也。","n":"釋名曰。徐行曰步。疾行曰趨。疾趨曰走。此析言之。許渾言不別也。今俗謂走徐、趨疾者、非。"}]},"酷":{"expl":"酒厚味也。从酉告聲。","rad":"酉","fq":"苦𦰚切","vol":"14","py":"kù","duan":[{"e":"酒味厚也。","n":"依廣韵訂。引申爲巳甚之義。白虎通曰。酷、極也。敎令窮極也。"}]},"醰":{"expl":"酒味苦也。从酉覃聲。","rad":"酉","fq":"徒紺切","vol":"14","py":"dàn","duan":[{"e":"酒味長也。","n":"廣韵、玉篇皆云。酒味不長也。不是賸字。集韵云。酒味苦也。由宋時說文以酓義系醰篆而奪酓之故耳。汲古初刻時正如此。或曰古酓覃同部。疑無二字。然小徐本分列畫然。小徐作甛長味也。按洞簫賦良醰醰而有味。李注引字林醰甛同長味也。同是賸字。"}]},"䣪":{"expl":"酒色也。从酉巿聲。","rad":"酉","fq":"普活切","vol":"14","py":"pò","duan":[{"e":"酒色也。","n":"謂酒之顔色也。廣韵曰。酒氣。"}]},"配":{"expl":"酒色也。从酉己聲。","rad":"酉","fq":"滂佩切","vol":"14","py":"pèi","duan":[{"e":"酒色也。","n":"本義如是。後人借爲妃字、而本義廢矣。妃者、匹也。"}]},"䣧":{"expl":"酒色也。从酉弋聲。","rad":"酉","fq":"與職切","vol":"14","py":"yì","duan":[{"e":"酒色也。从酉。弋聲。","n":"與職切。一部。"}]},"醆":{"expl":"爵也。一曰酒濁而微清也。从酉戔聲。","rad":"酉","fq":"阻限切","vol":"14","py":"zhǎn","duan":[]},"酌":{"expl":"盛酒行觴也。从酉勺聲。","rad":"酉","fq":"之若切","vol":"14","py":"zhuó","duan":[{"e":"盛酒行觴也。","n":"盛酒於觶中以飲人曰行觴。投壷云。命酌曰請行觴。觶實曰觴。詩曰。我姑酌彼金罍。取行觴之意曰。泂酌彼行潦。取盛酒之意。"}]},"醮":{"expl":"冠娶禮。祭。从酉焦聲。","rad":"酉","fq":"子肖切","vol":"14","py":"jiào","duan":[{"e":"冠娶禮祭也。","n":"士冠禮。若不醴則醮用酒。三加、凡三醮。鄭曰。酌而無酬酢曰醮。士昏禮。父醮子。命之迎婦。嫡婦則酌之以醴。庶婦使人醮之。酌之以酒。鄭曰。酒不酬酢曰醮。依鄭說、非謂祭也。而許云冠娶禮祭。事屬可疑。詳經文不言祭也。葢古本作冠娶妻禮也。一曰祭也。轉寫有奪與。祭者別一義。不蒙冠婚。宋玉高唐賦。醮諸神禮太一。此後世醮祀之始見也。"}]},"䤐":{"expl":"歃酒也。从酉朁聲。","rad":"酉","fq":"子朕切","vol":"14","py":"jǐn","duan":[{"e":"歃酒也。","n":"歃、歠也。歠、㱃也。歃謂小飲之。"}]},"𨟴":{"expl":"少少㱃也。从酉勻聲。","rad":"酉","fq":"余刃切","vol":"14","py":"yìn","duan":[{"e":"少少㱃也。","n":"士昏禮注。酳、漱也。酳之言演也、安也。漱所以潔口。且演安其所食。特牲、少牢注意略同。曲禮注。以酒曰酳。按禮、禮記皆作酳。許書作？。玉篇云？酳同字。是也。攷士虞禮注、少牢禮注皆云。古文酳作酌。特牲注云。今文酳皆爲酌。三酌字必皆？之字誤。其一云今文者、則古文之誤。許於此字用古文禮。故从？。禮記多用今文禮。故記作酳。酳从胤省聲。"}]},"趨":{"expl":"走也。从走芻聲。","rad":"走","fq":"七逾切","vol":"02","py":"qū","duan":[{"e":"走也。","n":"曲禮注曰。行而張足曰趨。按張足過於布武。大雅。左右趣之。毛曰。趣、趨也。此謂假借趣爲趨也。"}]},"醻":{"expl":"主人進客也。从酉𠷎聲。","rad":"酉","fq":"市流切","vol":"14","py":"chóu","duan":[{"e":"獻醻、主人進客也。","n":"楚茨箋曰。始主人酌賓爲獻。賓旣酌主人。主人又自飲酌䚔曰醻。至旅而爵交錯以徧。彤弓傳曰。醻、報也。謂報客之酢也。瓠葉傳曰。醻、道飲也。謂主人必自飲。如今俗之勸酒也。"}]},"醋":{"expl":"客酌主人也。从酉昔聲。","rad":"酉","fq":"在各切","vol":"14","py":"zuó","duan":[{"e":"客酌主人也。","n":"瓠葉傳曰。酢、報也。彤弓箋曰。主人獻賓。賓酢主人。主人又飲而酌賓。謂之醻。"}]},"䤉":{"expl":"㱃酒俱盡也。从酉𥁑聲。","rad":"酉","fq":"迷必切","vol":"14","py":"mì","duan":[{"e":"㱃酒俱盡也。从酉。𥁑聲。","n":"迷必切。十二部。"}]},"釂":{"expl":"㱃酒盡也。从酉，嚼省聲。","rad":"酉","fq":"子肖切","vol":"14","py":"jiào","duan":[{"e":"㱃酒盡也。","n":"酒當作爵。此形聲包會意字也。曲禮注曰。盡爵曰釂。按欠部？、酒盡也。與此音義同。而本部醮釂則各義。水部曰。潐、盡也。謂水也。"}]},"酣":{"expl":"酒樂也。从酉从甘，甘亦聲。","rad":"酉","fq":"胡甘切","vol":"14","py":"hān","duan":[{"e":"酒樂也。","n":"張晏曰。中酒曰酣。引申爲凡飽足之偁。"}]},"酖":{"expl":"樂酒也。从酉冘聲。","rad":"酉","fq":"丁含切","vol":"14","py":"dān","duan":[{"e":"樂酒也。","n":"酒樂者、因酒而樂。樂酒者、所樂在酒。其義別也。毛詩叚耽及湛以爲酖。氓傳曰。耽、樂也。鹿鳴傳曰。湛、樂之久也。引申爲凡樂之偁。左傳曰。宴安酖毒。不可懷也。從來謂卽鴆字。竊謂非也。所樂非其正、卽毒也。謂之酖毒。"}]},"醧":{"expl":"私宴㱃也。从酉區聲。","rad":"酉","fq":"依倨切","vol":"14","py":"yù","duan":[{"e":"宴厶㱃也。","n":"厶各本作私。今正。宴私各本作私宴。今正。小雅楚茨。諸父兄弟。備言燕私。傳曰。宴而盡其私恩也。尙書大傳曰。旣侍其宗。然後得燕私。燕私者何也。祭巳而與族人飲。飲而不醉、是不親。醉而不出、是不敬。湛露傳曰。夜飲、燕私也。宗子有事。則族人皆侍。不醉而出、是不親也。醉而不出、是渫宗也。特牲饋食禮注曰。尙書傳曰。宗室有事。族人皆侍終日。大宗巳侍於賓。暮然後燕私。燕私者何也。祭巳而與族人飲也。皆燕私之證。今湛露傳亦譌爲私燕矣。宴私之飲謂之醧。見韓詩。魏都賦。愔愔醧燕。張載注云。韓詩曰。賓爾籩豆。飲酒之醧。能者飲、不能者巳謂之醧。東都賦。登降飫宴之禮旣畢。李善引薛君韓詩章句曰。曰飲酒之禮。跣而上坐者謂之宴。今"}]},"醵":{"expl":"會㱃酒也。从酉豦聲。","rad":"酉","fq":"其虐切","vol":"14","py":"jù","duan":[{"e":"會㱃酒也。","n":"禮器注曰。合錢飲酒曰醵。"}]},"酺":{"expl":"王德布，大㱃酒也。从酉甫聲。","rad":"酉","fq":"薄乎切","vol":"14","py":"pú","duan":[{"e":"王𢛳布大㱃酒也。","n":"禮器注引王居明堂禮曰。仲秋乃命國醵。葢醵餔略同也。漢文帝紀。餔五日。文穎曰。音步。漢律。三人以上無故飲酒。罰金四兩。今詔横賜得令會聚飲食五日也。伏䖍音蒲。按周禮族師祭酺注。酺者、爲人物災害之神。別一義。"}]},"醅":{"expl":"醉飽也。从酉咅聲。","rad":"酉","fq":"匹回切","vol":"14","py":"pēi","duan":[{"e":"醉飽也。","n":"後人用潑醅字。謂酒未？也。與古義絕殊。"}]},"璐":{"expl":"玉也。从玉路聲。","rad":"玉","fq":"洛故切","vol":"01","py":"lù","duan":[{"e":"玉也。","n":"九章。被明月兮佩寶璐。王逸注。寶璐、美玉也。"}]},"赴":{"expl":"趨也。从走，仆省聲。","rad":"走","fq":"芳遇切","vol":"02","py":"fù","duan":[{"e":"趨也。","n":"聘禮。赴者未至。士喪禮。赴曰君之臣某死。注皆云。今文赴作計。按古文計告字衹作赴者、取急疾之意。今文从言。急疾意轉隱矣。故言部不收計字者、从古文不从今文也。凡許於禮經从今文則不收古文字。如口部有名、金部無銘是也。从古文則不收今文字。如赴是也。襍記作計不作赴者、禮記多用今文禮也。左傳作赴者、左𠀌明述春秋傳以古文。故與古文禮同也。"}]},"醉":{"expl":"卒也。卒其度量，不至於亂也。一曰潰也。从酉从卒。","rad":"酉","fq":"將遂切","vol":"14","py":"zuì","duan":[{"e":"卒也。卒其度量不至於亂也。","n":"以曡韵爲訓。"}]},"醺":{"expl":"醉也。从酉熏聲。《詩》曰：“公尸來燕醺醺。”","rad":"酉","fq":"許云切","vol":"14","py":"xūn","duan":[{"e":"醉也。","n":"謂酒氣熏蒸。"}]},"醟":{"expl":"䣱也。从酉，熒省聲。","rad":"酉","fq":"爲命切","vol":"14","py":"yònɡ","duan":[{"e":"䣱酒也。","n":"無逸曰。酗于酒德。"}]},"䣱":{"expl":"醉醟也。从酉句聲。","rad":"酉","fq":"香遇切","vol":"14","py":"xù","duan":[{"e":"酒醟也。","n":"依尙書釋文訂。書作酗。某氏傳曰。以酒爲凶曰酗。周禮司救注亦云酗醟。"}]},"酲":{"expl":"病酒也。一曰醉而覺也。从酉呈聲。","rad":"酉","fq":"直貞切","vol":"14","py":"chénɡ","duan":[{"e":"病酒也。","n":"小雅。憂心如酲。傳曰。病酒曰酲。"}]},"醫":{"expl":"治病工也。殹，惡姿也；醫之性然。得酒而使，从酉。王育說。一曰殹，病聲。酒所以治病也。《周禮》有醫酒。古者巫彭初作醫。","rad":"酉","fq":"於其切","vol":"14","py":"yī","duan":[{"e":"治病工也。","n":"周禮有醫師、食醫、疾醫、瘍醫、獸醫。"}]},"莤":{"expl":"禮祭，束茅，加于祼圭，而灌鬯酒，是爲莤。象神歆之也。一曰莤，榼上塞也。从酉从艸。《春秋傳》曰：“尔貢包茅不入，王祭不供，無以莤酒。”","rad":"酉","fq":"所六切","vol":"14","py":"sù","duan":[{"e":"禮。","n":"句。"}]},"醨":{"expl":"薄酒也。从酉离聲。讀若離。","rad":"酉","fq":"呂支切","vol":"14","py":"lí","duan":[{"e":"薄酒也。","n":"薄對厚言。上文醪醇醹酎皆謂厚酒。故謂厚薄爲醇醨。今人作漓、乃俗字也。屈原賦曰。何不餔其糟而歠其醨。"}]},"䤘":{"expl":"酢也。从酉韱聲。","rad":"酉","fq":"初減切","vol":"14","py":"chǎn","duan":[{"e":"酢也。","n":"二字雙聲。"}]},"酸":{"expl":"酢也。从酉夋聲。關東謂酢曰酸。","rad":"酉","fq":"素官切","vol":"14","py":"suān","duan":[{"e":"酢也。","n":"月令。春三月、其味酸。鴻範。曲直作酸。"}]},"趣":{"expl":"疾也。从走取聲。","rad":"走","fq":"七句切","vol":"02","py":"qù","duan":[{"e":"疾也。","n":"大雅。來朝趣馬。箋云。言其辟惡早且疾也。玉篇所引如是。獨爲不誤。早釋來朝、疾釋趣馬也。又濟濟辟王。左右趣之。箋云。左右之諸臣皆促疾於事。周禮趣馬。大鄭曰。趣馬、趣養馬者也。按趣養馬、謂督促養馬。古音七口反。音轉乃有淸須七句二反。後人言歸趣旨趣者、乃引伸之義。輒讀爲七句、以別於七苟。非古義古音也。"}]},"酨":{"expl":"酢𤖅也。从酉𢦔聲。","rad":"酉","fq":"徒奈切","vol":"14","py":"zài","duan":[{"e":"酢浆也。","n":"水部浆下曰。酢浆也。酢浆謂酨也。酨浆二篆爲轉注。鄭注內則曰。漿、酢酨也。許書漿下當是酢酨也。後人改之耳。鄭注周禮四飲曰。漿、今之酨漿也。絫言之曰酨漿。"}]},"醶":{"expl":"酢𤖅也。从酉僉聲。","rad":"酉","fq":"魚窆切","vol":"14","py":"yàn","duan":[{"e":"酢浆也。","n":"漿酨醶三者同物。"}]},"酢":{"expl":"醶也。 从酉乍聲。","rad":"酉","fq":"倉故切","vol":"14","py":"cù","duan":[{"e":"醶也。","n":"酢本酨漿之名。引申之、凡味酸者皆謂之酢。上文䤘、酢也。酸、酢也。皆用酢引申之義也。"}]},"酏":{"expl":"黍酒也。从酉也聲。一曰甜也。賈侍中說：酏爲鬻清。","rad":"酉","fq":"移尔切","vol":"14","py":"yǐ","duan":[{"e":"黍酒也。","n":"周禮四飲、四曰酏。注曰。今之粥也。酏飲粥稀、者之淸也。禮記內則黍酏注曰。酏、粥也。或以酏爲醴。注曰。釀粥爲醴也。按飲非酒也。故五齊三酒掌於酒人。六飲掌於漿人。而許酏下曰黍酒。醫下曰醫酒。葢許意與鄭說不同。故賈侍中酏爲粥淸、爲別一說。賈與鄭合也。"}]},"𨡓":{"expl":"盬也。从肉从酉，酒以和𨡓也；爿聲。","rad":"酉","fq":"即亮切","vol":"14","py":"jiànɡ","duan":[{"e":"醢也。从肉酉。","n":"从肉者、醢無不用肉也。"}]},"醢":{"expl":"肉𨡓也。从酉、𥁓。","rad":"酉","fq":"呼改切","vol":"14","py":"hǎi","duan":[{"e":"肉𤖕也。","n":"周禮醢人。掌？醢。麋臡、鹿臡、麇臡、蠃醢、蠯醢、蚳醢、魚醢、兔醢、鴈醢。凡醢皆肉也。鄭曰。作醢及臡者、必先膊乾其肉。乃復莝之。襍以粱麴及鹽。漬以美酒。塗置甀中。百日則成矣。此？从肉从酉之恉也。許訓？云血醢。訓凡醢曰肉？。就字形別之耳。"}]},"𨡭":{"expl":"𨡭䤅，榆𨡓也。从酉敄聲。","rad":"酉","fq":"莫𠊱切","vol":"14","py":"mú","duan":[{"e":"𨡭䤅、","n":"逗。"}]},"䤅":{"expl":"𨡭䤅也。从酉俞聲。","rad":"酉","fq":"田𠊱切","vol":"14","py":"tú","duan":[{"e":"𨡭䤅也。从酉。兪聲。","n":"田𠋫切。四部。按或音茂逗。或音牟頭。或音模途。皆曡韵也。"}]},"酹":{"expl":"餟祭也。从酉寽聲。","rad":"酉","fq":"郎外切","vol":"14","py":"lèi","duan":[{"e":"餟祭也。","n":"食部餟下曰。？祭也。與此爲轉注。廣韵曰。以酒沃地。史記。其下四方地爲餟食。葢餟？皆於地。餟謂肉。故漢書作腏。？謂酒。故从酉。"}]},"𨢡":{"expl":"擣榆𨡓也。从酉畢聲。","rad":"酉","fq":"蒲計切","vol":"14","py":"bì","duan":[{"e":"𢶈榆𤖕也。","n":"擣、築也。擣而爲之謂之𨢡。"}]},"超":{"expl":"跳也。从走召聲。","rad":"走","fq":"敕宵切","vol":"02","py":"chāo","duan":[{"e":"跳也。","n":"跳一曰躍也。躍、迅也。迅、疾也。然則超與趣同義。"}]},"䤎":{"expl":"𨡓也。从酉矞聲。","rad":"酉","fq":"居律切","vol":"14","py":"jú","duan":[{"e":"𤖕也。","n":"廣雅同。玉篇曰。䤉𤖕也。䤉𤖕亦見廣雅。"}]},"䣼":{"expl":"雜味也。从酉京聲。","rad":"酉","fq":"力讓切","vol":"14","py":"liánɡ","duan":[{"e":"襍味也。","n":"周禮漿人六飲。鄭司農云。涼、以水和酒也。玄謂涼、今寒粥。若糗飯襍水也。內則有濫無涼。鄭曰。以諸和水也。以周禮六飲校之。則濫、涼也。紀莒之閒名諸爲濫。按許作䣼、卽周官、內則之涼字也。襍味者、卽以諸和水說也。乾者爲桃諸、梅諸。水漬爲桃濫。於釋名可得其義也。內則正義曰。諸者、衆襍之辭。又按廣雅云。䣼、？也。疑襍味下本有？字。故廁於此。若六飲之涼、則巳見水部。"}]},"䤔":{"expl":"闕。","rad":"酉","fq":"慈冉切","vol":"14","py":"jiàn","duan":[{"e":"闕。","n":"慈冄切。八部。"}]},"䣸":{"expl":"闕。","rad":"酉","fq":"而𤥎切","vol":"14","py":"rǎn","duan":[{"e":"闕。","n":"而剡切。七部。按依玉篇、廣韵上字下當云䤔䣸、味薄也。从酉、漸聲。下字下當云䤔䣸也。从酉、任聲。二篆曡韵。而今本但注闕字。疑許書本無此二篆。"}]},"酪":{"expl":"乳𤖅也。从酉各聲。","rad":"酉","fq":"盧各切","vol":"14","py":"lào","duan":[]},"醐":{"expl":"醍醐，酪之精者也。从酉胡聲。","rad":"酉","fq":"户吴切","vol":"14","py":"hú","duan":[]},"酩":{"expl":"酩酊，醉也。从酉名聲。","rad":"酉","fq":"莫迥切","vol":"14","py":"mǐnɡ","duan":[]},"酊":{"expl":"酩酊也。从酉丁聲。","rad":"酉","fq":"都挺切","vol":"14","py":"dǐnɡ","duan":[]},"醒":{"expl":"醉解也。从酉星聲。按：酲字注云：一曰醉而覺也。則古酲，亦音醒也。","rad":"酉","fq":"桑經切","vol":"14","py":"xǐnɡ","duan":[]},"醍":{"expl":"清酒也。从酉是聲。","rad":"酉","fq":"它禮切","vol":"14","py":"tǐ","duan":[]},"趫":{"expl":"善緣木走之才。从走喬聲。讀若王子蹻。","rad":"走","fq":"去嚻切","vol":"02","py":"qiāo","duan":[{"e":"善緣木之士也。","n":"依二京賦注、衆經音義訂。吳都賦曰。趫材悍壯。此焉比廬。成公綏洛禊賦曰。趫才逸態。習水善浮。按張注列子說符篇異伎云僑人。郭注山海經長股國言有喬國。今伎家僑人象此。僑人今俗謂之踹僑。僑卽趫字。去嚻切。"}]},"酋":{"expl":"繹酒也。从酉，水半見於上。《禮》有“大酋”，掌酒官也。凡酋之屬皆从酋。","rad":"酋","fq":"字秋切","vol":"14","py":"qiú","duan":[{"e":"繹酒也。","n":"繹之言昔也。昔、久也。多下曰。从重夕。夕者、相繹也。故重夕爲多。然則繹酒謂日久之酒。對？爲疾孰酒、醴酤爲一宿酒言之。繹俗作醳。周禮酒人三酒注曰。事酒、酌有事者之酒。其酒則今之醳酒也。昔酒、今之酋久白酒。所謂舊醳者也。淸酒、今中山冬釀接夏而成。郊特牲舊澤之酒注曰。澤讀爲醳。舊醳之酒、謂昔酒也。玉裁按許云繹酒、葢兼事酒昔酒言之。事酒謂繹酒。昔酒謂舊繹之酒也。酋之義引申之、凡久皆曰酋。久則有終。大雅。似先公酋矣。傳曰。酋、終也。"}]},"𢍜":{"expl":"酒器也。从酋，廾以奉之。《周禮》六尊：犧尊、象尊、著尊、壺尊、太尊、山尊，以待祭祀賓客之禮。","rad":"酋","fq":"祖昆切","vol":"14","py":"zūn","duan":[{"e":"酒器也。","n":"凡酒必實於尊以待酌者。鄭注禮曰。置酒曰尊。凡酌酒者必資於尊。故引申以爲尊卑字。猶貴賤本謂貨物而引申之也。自專用爲尊卑字、而別製罇樽爲酒尊字矣。"}]},"戌":{"expl":"滅也。九月，陽气微，萬物畢成，陽下入地也。五行，土生於戊，盛於戌。从戊含一。凡戌之屬皆从戌。","rad":"戌","fq":"辛聿切","vol":"14","py":"xū","duan":[{"e":"烕也。九月昜气微。萬物畢成。昜下入地也。","n":"烕大徐作滅。非。火部曰。烕、滅也。本毛詩傳。火死於戌。陽氣至戌而盡。故烕从火戌。此以烕釋戌之恉也。律書曰。戌者、萬物盡滅。淮南天文訓。戌者、滅也。律曆志。畢入於戌。釋名。戌、恤也。物當收斂矜恤之也。九月於卦爲剝。五陰方盛。一陽將盡。陽下入地。故其字从土中含一。"}]},"亥":{"expl":"荄也。十月，微陽起，接盛陰。从二，二，古文上字。一人男，一人女也。从乙，象褢子咳咳之形。《春秋傳》曰：“亥有二首六身。”凡亥之屬皆从亥。","rad":"亥","fq":"胡改切","vol":"14","py":"hài","duan":[{"e":"荄也。十月微昜起接盛侌。","n":"律曆志曰。該閡於亥。天文訓曰。亥者、閡也。釋名曰。亥、核也。收藏萬物。核取其好惡眞僞也。許云荄也者。荄、根也。陽氣根於下也。十月於卦爲坤。微陽從地中起接盛陰。卽壬下所云陰極陽生。故易曰。龍戰於野。戰者、接也。"}]},"赳":{"expl":"輕勁有才力也。从走丩聲。讀若鐈。","rad":"走","fq":"居黝切","vol":"02","py":"jiū","duan":[{"e":"輕勁有才力也。","n":"周南傳曰。赳赳、武皃。釋訓曰。洸洸赳赳、武也。詩音義引爾雅。武作勇。"}]},"䞚":{"expl":"緣大木也。一曰行皃。从走支聲。","rad":"走","fq":"巨之切","vol":"02","py":"qí","duan":[{"e":"緣大木也。","n":"與蚑音義略同。"}]},"趮":{"expl":"疾也。从走喿聲。","rad":"走","fq":"則到切","vol":"02","py":"zào","duan":[{"e":"疾也。","n":"考工記。羽豐則遟。羽殺則趮。鄭云。趮、㫄掉也。按今字作躁。"}]},"趯":{"expl":"踊也。从走翟聲。","rad":"走","fq":"以灼切","vol":"02","py":"yuè","duan":[{"e":"躍也。","n":"召南傳曰。趯趯、躍也。足部曰。躍、迅也。"}]},"𧽸":{"expl":"蹠也。从走厥聲。","rad":"走","fq":"居月切","vol":"02","py":"jué","duan":[{"e":"蹠也。","n":"𧽸、跳起也。足部曰。楚人謂跳躍曰蹠。"}]},"越":{"expl":"度也。从走戉聲。","rad":"走","fq":"王伐切","vol":"02","py":"yuè","duan":[{"e":"度也。","n":"與辵部𨒋字音義同。周頌。對越在夭。箋云。越、於也。此假借越爲粤也。尙書有越無粤。大誥、文矦之命越字魏三體石經作粤。說文引粤三日丁亥。今召誥作越三日丁巳。"}]},"瓚":{"expl":"三玉二石也。从玉贊聲。《禮》：“天子用全，純玉也；上公用駹，四玉一石；侯用瓚；伯用埒，玉石半相埒也。”","rad":"玉","fq":"徂贊切","vol":"01","py":"zàn","duan":[{"e":"三玉二石也。从王。贊聲。","n":"徂贊切。十四部。"}]},"趁":{"expl":"𧾍也。从走㐱聲。讀若塵。","rad":"走","fq":"丑刃切","vol":"02","py":"chèn","duan":[{"e":"𧾍也。从走。㐱聲。讀若塵。","n":"丑忍切。十三部。按趁當平聲。同馬部駗。張人切。今人趁逐字作此。反語爲丑刃。非古義古音也。"}]},"𧾍":{"expl":"趁也。从走亶聲。","rad":"走","fq":"張連切","vol":"02","py":"zhān","duan":[{"e":"趁也。","n":"按趁𧾍卽屯六二屯如亶如。馬融云。難行不進之皃。亶俗本作邅。葉林宗抄宋版釋文、吕祖謙音訓皆作亶。馬部作駗驙。駗驙、馬載重難也。皆雙聲㬪韵。疑㒳篆下本皆作趁𧾍也。"}]},"趞":{"expl":"趞趞也。一曰行皃。从走昔聲。","rad":"走","fq":"七雀切","vol":"02","py":"què","duan":[{"e":"趬趞也。从走。昔聲。","n":"七雀切。古音在五部。"}]},"趬":{"expl":"行輕皃。一曰趬，舉足也。从走堯聲。","rad":"走","fq":"牽遙切","vol":"02","py":"qiāo","duan":[{"e":"行輕皃。","n":"今俗語輕趬。當用此字。"}]},"𧼏":{"expl":"急走也。从走弦聲。","rad":"走","fq":"胡田切","vol":"02","py":"xián","duan":[{"e":"急走也。从走。弦聲。","n":"形聲包會意。从弦有急意也。胡田切。十二部。"}]},"趀":{"expl":"蒼卒也。从走𠂔聲。讀若資。","rad":"走","fq":"取私切","vol":"02","py":"cī","duan":[{"e":"倉卒也。","n":"倉俗从？。誤。夬九四。其行次且。次鄭作？。論語。造次必於是。造次、馬云急遽也。鄭云倉卒也。然則次者、趀之假借字。錢氏大昕說。"}]},"𧽤":{"expl":"輕行也。从走票聲。","rad":"走","fq":"撫招切","vol":"02","py":"piāo","duan":[{"e":"輕行也。从走。票聲。","n":"撫招切。二部。"}]},"𧼒":{"expl":"行皃。从走臤聲。讀若菣。","rad":"走","fq":"弃忍切","vol":"02","py":"qǐn","duan":[{"e":"行皃。从走。臤聲。讀若菣。","n":"棄忍切。十二部。"}]},"趥":{"expl":"行皃。从走酋聲。","rad":"走","fq":"千牛切","vol":"02","py":"qiū","duan":[{"e":"行皃。从走。酋聲。","n":"千牛切。三部。"}]},"䟉":{"expl":"行皃。从走蜀聲。讀若燭。","rad":"走","fq":"之欲切","vol":"02","py":"zhú","duan":[{"e":"行皃。","n":"篇、韵皆曰。小兒行。"}]}};
